INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')), 1, 'Season 1', 'The first season of The Twilight Zone aired Fridays at 10:00–10:30 pm on CBS from October 2, 1959 to July 1, 1960. There are 36 episodes, including the pilot, "Where Is Everybody?". The theme music for this season, written by Bernard Herrman, is different from the music most commonly associated with the series, written by Marius Constant for the second season onwards.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0052520')) AND numero_temporada = 1), 1, 'Where Is Everybody?', 'Mike Ferris finds himself in a town strangely devoid of people. But despite the emptiness, he has the odd feeling that he''s being watched...', 26, '1959-10-02');
