INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 1, 'The Man Trap', 'Doctor Leonard “Bones” McCoy meets a former girlfriend when the enterprise brings supplies to a remote archaeological survey group. Still attractive to McCoy, the woman''s current appearance hides a dark and deadly secret.', 50, '1966-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 2, 'Charlie X', 'Raised from boyhood by non-corporeal beings, 17 year old Charles Evans is picked up and transferred to the Enterprise. On board the ship, the teenager proves dangerously unable to wield his enormous psionic powers with maturity.', 51, '1966-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 3, 'Where No Man Has Gone Before', 'When Enterprise encounters a Force Field at the edge of the Galaxy, one of the crew members psionic abilities are accelerated to God like proportions causing him to become a powerful murderous being.', 51, '1966-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 4, 'The Naked Time', 'An alien virus strips the enterprise crew of their inhibitions, causing chaos as each crew member is overcome by hidden emotions. Meanwhile, the Enterprise is being pulled inexorably into a nearby planet''s gravity well.', 51, '1966-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 5, 'The Enemy Within', 'Split by a transporter malfunction into two beings with very different personalities, the resulting twin Captain Kirk proves that neither a purely evil nor a sweetly good captain can survive without the missing half.', 50, '1966-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 6, 'Mudd''s Women', 'Rescuing the crew of a ship from an asteroid belt, the Enterprise plays host to conman extraordinaire, the cunning Harry Mudd and his cargo: three beautiful women looking for suitors.', 50, '1966-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 7, 'What Are Little Girls Made Of?', 'Helping nurse Christine Chapel search for her fiancé, the Enterprise finds a detached Dr. Korby working on a plan to create Android duplicates of key figures, beginning with James Kirk.', 50, '1966-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 8, 'Miri', 'On a planet populated by children whose aging process has been slowed artificially. Kirk’s  landing party members contract a virus that kills adults. Despite their violent attacks, Kirk is determined to help the children.', 50, '1966-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 9, 'Dagger of the Mind', 'When a wild eyed maniac escaping from the Tantalus Penal Colony turns out to be one of the psychiatric staff, Kirk investigates the institution and discovers a chilling exercise in mind control.', 50, '1966-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 10, 'The Corbomite Maneuver', 'Threatened by the sinister captain of a powerful alien vessel, Kirk claims that the Enterprise carries a powerful explosive which will destroy both ships. The move produces unexpected actions from the alien adversary.', 50, '1966-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 11, 'The Menagerie (1)', 'Apparently summoned to Star Base 11, Kirk, Spock and McCoy visit a former Enterprise Commander, the paralyzed and horribly disfigured Christopher Pike. Uncharacteristically, Spock commandeers the Enterprise, then turns himself in for court martial.', 49, '1966-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 12, 'The Menagerie (2)', 'Spock''s court martial reveals the actions of Captain Pike on his previous visit to Talos IV, where the powerful Talosians tried to persuade Pike to breed with women provided for the purpose.', 50, '1966-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 13, 'The Conscience of the King', 'Contacted by one of the other two witnesses to the crimes of mass murderer  “Kodos the Executioner,” Kirk is persuaded that the criminal may be disguising himself as an actor in a traveling theatrical troupe.', 50, '1966-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 14, 'Balance of Terror', 'Despite the earlier Romulan war, the Romulans have never been seen in person. The Enterprise, in pursuit of a Romulan aggressor, makes a discovery that causes suspicion about a senior crew member.', 50, '1966-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 15, 'Shore Leave', 'When McCoy sees the White Rabbit from Alice in Wonderland, the crew begins to realize that the planet they are visiting seems to have the dangerous power to turn any thought into reality.', 50, '1966-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 16, 'The Galileo Seven', 'Crash landing on a planet populated by hostile giants, the 7-man crew of the shuttlecraft Galileo find themselves unable to communicate with the enterprise or to escape the planet''s atmosphere.', 50, '1967-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 17, 'The Squire of Gothos', 'Encountering an uncharted planet in an empty region of space, Kirk and his crew are entertained by Trelane, a playful being who lacks the self-control to wield his great psionic powers with discipline.', 50, '1967-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 18, 'Arena', 'With both their ships held captive by powerful beings, Kirk and the captain of the alien vessel are placed on an asteroid to fight for their lives and the lives of their crews.', 51, '1967-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 1), 19, 'Tomorrow Is Yesterday', 'In a freak accident the Enterprise is sent back to 20th century Earth, and must find their way back without changing history.', 50, '1967-01-26');
