INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 13, 'Elaan of Troyius', 'The USS Enterprise ferries a spoiled princess whose betrothal to a royal Troyian is hoped will bring peace to a star system at war.', 51, '1968-12-20');
