INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 15, 'Let That Be Your Last Battlefield', 'The Enterprise encounters two duo-chromatic and mutually belligerent aliens who put the ship in the middle of their old conflict.', 51, '1969-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 16, 'The Mark of Gideon', 'A race of overpopulated aliens abduct Captain Kirk to solve their problem.', 51, '1969-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 17, 'That Which Survives', 'Kirk, McCoy, and Sulu are stranded on a barren planet where a mysterious woman attempts to kill them one at a time, while the Enterprise must travel halfway across the galaxy to rescue them.', 51, '1969-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 18, 'The Lights of Zetar', 'Strange incorporeal aliens threaten the Memory Alpha station and the Enterprise.', 51, '1969-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 19, 'Requiem for Methuselah', 'The crew of the Enterprise encounter an immortal human in this science fiction variation on Shakespeare''s The Tempest.', 51, '1969-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 20, 'The Way to Eden', 'The Enterprise picks up a group of space "hippies" looking for Eden.', 51, '1969-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 21, 'The Cloud Minders', 'Captain Kirk races against time to acquire plague-fighting minerals from a world in the midst of a civil uprising against a grievous social class disparity.', 51, '1969-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0060028')) AND numero_temporada = 3), 22, 'The Savage Curtain', 'Aliens force Captain Kirk and First Officer Spock to join forces with "Abraham Lincoln" and "Surak" to battle villains in a contest of good vs. evil.', 51, '1969-03-07');
