INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0063950', 'Scooby Doo, Where Are You!', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0053484'), 'SERIE', 'Four teenage friends, Fred Jones, Daphne Blake, Velma Dinkley, and Shaggy Rogers, along with their talking dog, Scooby-Doo, travel around in their van, The Mystery Machine, solving strange, spooky, and hilariously kooky mysteries.', '1969-01-01', 'https://m.media-amazon.com/images/M/MV5BZWY2YWM1NzItMTM4OC00OWExLTkxZGItNzNmYzI4MmFiYjVmXkEyXkFqcGc@._V1_.jpg');
