INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 1, 'What a Night for a Knight', 'After coming back from the movies Scooby-Doo and Shaggy come across a pick up truck and a suit of armor in the driver''s seat. According to an ancient superstition the armor comes to life during the night of a full moon.', 22, '1969-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 2, 'A Clue for Scooby-Doo', 'While Scooby-Doo is surfing, he encounters a creature in a diving suit. An old sea salt tells the gang that it''s the ghost of Captain Cutler who is responsible for the disappearance of many ships.', 22, '1969-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 3, 'Hassle in the Castle', 'The gang gets shipwrecked on an island that happens to be an old lair for a pirate. They find a map, but there is a warning telling them to leave the island.  The warning appears justified when a ghost called ''The Phantom'' is after them.', 22, '1969-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 4, 'Mine Your Own Business', 'Thanks to Shaggy''s slightly flawed map reading skills, the gang finds themselves in an abandoned western town. The owner tells them that guests were scared off by a strange man who came to the town centuries ago and won''t leave until he finds the last remains of his gold claim.', 22, '1969-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 5, 'Decoy for a Dognapper', 'Scooby-Doo witnesses a dog kidnapping at the park. After hearing about it, the gang decides to use Scooby-Doo as bait to capture the kidnappers.', 22, '1969-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 6, 'What the Hex Going On?', 'The gang sees a strange man go into a weird mansion. They learn that he is a friend of their Uncle Stewart. Stewart tells them that the ghost of the Kingston Mansion caused him to turn old. Strange things start happening when Sharron and Uncle Stewart vanish.', 22, '1969-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 7, 'Never Ape an Ape Man', 'The gang gets volunteered as workers by Daphne''s uncle, a director currently filming a movie about a fierce creature called the ape man. Rumor has it that the real ape man is alive. The gang soon learns that it''s not just a rumor.', 22, '1969-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 8, 'Foul Play in Funland', 'The gang gets excited about the opening of an amusement park.  But when they see the rides on before it opens, they start to get suspicious.', 22, '1969-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 9, 'The Backstage Rage', 'While coming home from getting pizza, Shaggy finds a violin case full of money. While calling the gang Scooby-Doo goes to help an injured poodle and the money is taken. The gang suspects that the money was fake.', 22, '1969-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 10, 'Bedlam in the Big Top', 'The gang rescues two circus people who tell them that they have left a circus because it''s bad luck. The ring master tells them of a mysterious person called ''The Ghost Clown'' who is responsible for the many strange accidents and incidents in the circus.', 22, '1969-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 11, 'A Gaggle of Galloping Ghosts', 'The gang, on their way to the Frankenstein castle, visits a gypsy fortune teller who warns them not to go to the castle. They ignore her warning and go anyway. The trouble begins when Daphne is taken hostage and the gang finds themselves in the clutches of a trio of monsters.', 22, '1969-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 12, 'Scooby-Doo and a Mummy, Too', 'The gang, at the college museum, gets the lead on a dead Egyptian ruler named Inca. According to an ancient superstition, if he were ever removed from his crypt, he would turn the people who moved him into stone. Shaggy finds a rare coin that the Professor is trying to study. The trouble begins when Shaggy accidentally takes the coin and the mummy is on the loose looking for it.', 22, '1969-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 13, 'Which Witch is Which?', 'The gang gets lost while driving to a concert. They ask a man to give them directions only to learn that he''s a zombie. They also learn of a nearby witch who is responsible for the zombie''s resurrection.', 22, '1969-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 14, 'Go Away Ghost Ship', 'The gang investigates the appearance of a Ghost Pirate.', 22, '1969-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 15, 'Spooky Space Kook', 'A spaceman haunts an abandoned airfield.', 22, '1969-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 16, 'A Night of Fright is No Delight', 'Scooby-Doo inherits a mansion after saving Colonel Beauregard Sanders from drowning some years ago. He and some other heirs will each get a fortune if they stay the night but there''s a warning that the house is haunted. The warning appears justified when someone (or something) comes to frighten the heirs away.', 22, '1970-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 1), 17, 'That''s Snow Ghost', 'While on vacation in the Himalayas, the gang goes to a winter lodge where the owner tells them about the ghost of a Yeti that is out to get revenge on the man that caused his death and will turn anyone into ghosts.', 22, '1970-01-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 1, 'Nowhere to Hyde', 'While driving back from the movies, the gang finds a strange man in the back of the Mystery Machine. They recognize it as the ghost of Mr. Hyde who is a jewel thief. They follow him to a house where they meet a descendent of Dr. Jekyll who claims to be the ghost of Hyde, but is he telling the truth?', 22, '1970-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 2, 'Mystery Mask Mix-Up', 'While in China, the gang pursues an ancient Chinese mask at an antique show. Soon strange things start happening. The gang is pursued by some horrible ghosts. They learn that the ghost of long dead emperor has returned to claim what is rightfully his. Things take a serious turn when Daphne is taken hostage.', 22, '1970-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 3, 'Scooby''s Night With a Frozen Fright', 'While fishing, the gang encounters a frozen caveman. The gang takes it Ocean Land to keep it in the cooler but someone melts the ice and now the caveman is on the loose.', 22, '1970-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 4, 'Jeepers, It''s the Creeper', 'While driving to the barnyard dance, the gang finds an injured bank guard. He gives them a blank paper and says something about a flame. The gang learns of a local bank robber called the Creeper. Things take a serious turn when the Creeper tries to steal the blank paper.', 22, '1970-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 5, 'Haunted House Hang-Up', 'While driving to a concert, the gang gets lost. A strange man with a lantern tells them to avoid taking a right fork in the road. That would take them to a mansion that''s rumored to be haunted by a headless man.', 22, '1970-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 6, 'A Tiki Scare Is No Fair', 'Scooby and Shaggy are having a fun time in Hawaii with their guide John Simms. Things take a serious turn when a voodoo witch doctor shows up and Simms mysteriously vanishes.', 22, '1970-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 7, 'Who''s Afraid of the Big Bad Werewolf?', 'While camping out in the woods, the gang comes across a tombstone of a man that was a werewolf. Are they pursuing the ghost of a werewolf?', 22, '1970-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 2), 8, 'Don''t Fool With a Phantom', 'The gang is having fun at a TV station with their friend Johnny but then a wax creature shows up. Johnny tells them that years ago a wax maker named Grisby used to work for the station. He was fired and threatened to bring one of his wax creations to life to seek revenge on the people who fired him.', 22, '1970-10-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 1, 'Watch Out! The Willawaw!', 'Velma gets asked by her uncle Dave to visit. But while visiting, they find out that he''s vanished. Then, they encountered the legendary Willawaw and two Owlmen who may be responsible for uncle Dave''s disappearance. Legend has it if an owl calls your name, you''ll be the next victim the Willawaw claims.', 22, '1978-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 2, 'Creepy Tangle in the Bermuda Triangle', 'A hurricane strands the gang on the island base of a UFO.', 22, '1978-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 3, 'A Scary Night With a Snow Beast Fright', 'A fur-covered dinosaur terrorizes the North Pole.', 22, '1978-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 4, 'To Switch a Witch', 'A witch seeks revenge 200 years after being burned at the stake.', 22, '1978-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 5, 'The Tar Monster', 'A tar monster haunts the lost city of Byzantius, Turkey.', 22, '1978-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 6, 'A Highland Fling With a Monstrous Thing', 'The Loch Ness monster terrorizes Velma''s friend, Aggie MacDuff.', 22, '1978-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 7, 'The Creepy Case of Old Iron Face', 'The kids visit Skull Island, where there''s an old prison still inhabited by Iron Face, a mean prisoner who had a iron mask welded to his face. With him and his torpedo-like sharks, will the kids last long?', 22, '1978-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 8, 'Jeepers, It''s the Jaguaro!', 'After their plane crashes in the Amazon jungle, Scooby and the gang face a tigerlike creature.', 22, '1978-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 9, 'Make a Beeline Away From That Feline', 'Daphne''s aunt transforms into a cat creature and robs jewelry stores in her sleep.', 22, '1978-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 10, 'The Creepy Creature of Vulture''s Claw', 'The gang visits their friend, Professor Greer, at Vulture''s Claw Botanical Gardens and discovers a strange creature that roams around the place.', 22, '1978-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 11, 'The Diabolical Disc Demon', 'The gang go to Decade Records recording studio to see a live recording from their friend, Jimmy Lewis, but the building is haunted by the Phantom, who is trying to find a song by a missing writer, and will stop at nothing until he gets it.', 22, '1978-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 12, 'Scooby''s Chinese Fortune Kooky Caper', 'The gang travel to China to visit a friend. While there, the gang run into the Moon Monster, who is turning people into stone if they run into its shadow.', 22, '1978-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 13, 'A Menace in Venice', 'The gang visit their friend, Antonio, in Venice, Italy, and find that he''s haunted by the ghost of an ancestor, the Ghostly Gondolier, who seeks to steal the ancient necklace/family heirloom Antonio wears!', 22, '1978-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 14, 'Don''t Go Near the Fortress of Fear', 'The gang head to Puerto Rico to go on holiday. They visit an ancient fortress where the ghost of General Juan Carlos, who guards the El Moro Fortress, warns them to stay away.', 22, '1978-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 15, 'The Warlock of Wimbledon', 'While touring England, the gang come upon tennis star, Jimmy Pelton, who''s been cursed by Anthos, a warlock, and told to forfeit the Wimbledon tournament.', 22, '1978-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0063950')) AND numero_temporada = 3), 16, 'The Beast is Awake in Bottomless Lake', 'On a fishing trip, the gang end up in Canada at the newly deserted village of Bottomless Lake. Turns out the beast has scared everyone away, which only leaves Scooby, and the gang, to fritter away.', 22, '1978-12-23');
