INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0068098', 'M*A*S*H', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0239291'), 'SERIE', 'The staff of an Army hospital in the Korean War find that laughter is the best way to deal with their situation.', '1972-01-01', 'https://m.media-amazon.com/images/M/MV5BN2U1YTAyMjktOGRjZi00OWUzLTliMzItY2U0MjliNzNhOGFlXkEyXkFqcGc@._V1_.jpg');
