INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 1), 1, 'A Touch of Class', 'A confidence trickster comes to stay at the hotel, just after Basil has taken an ad in a posh magazine to upgrade the clientele.', 30, '1975-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 1), 2, 'The Builders', 'The Fawltys take a holiday and leave Polly and Manuel to run the place just as O''Reilly''s builders come to redo the lobby.', 28, '1975-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 1), 3, 'The Wedding Party', 'Basil wants ''none of that'' going on in his rooms and suspects some guests and Polly of carrying on.', 33, '1975-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 1), 4, 'The Hotel Inspectors', 'Some inspectors are in town and Basil gets paranoid, so he alternately fawns over and offends his guests.', 29, '1975-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 1), 5, 'Gourmet Night', 'To bring the right type of crowd into the hotel Basil establishes a Gourmet Night.', 29, '1975-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 1), 6, 'The Germans', 'Sybil goes into the hospital for toe surgery, leaving Basil to cope with a fire drill single-handed. After a couple of blows on the head, Basil tells some German guests where Germany went wrong in WWII.', 31, '1975-10-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')), 2, 'Series 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 2), 1, 'Communication Problems', 'A selectively deaf woman named Mrs Richards insists that she has had a large amount of money stolen at the hotel, and against Sybil''s wishes Basil puts a fiver on Dragonfly.', 31, '1979-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 2), 2, 'The Psychiatrist', 'A psychiatrist and his wife come to stay and Basil thinks Sybil is telling them all about his life.', 36, '1979-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 2), 3, 'Waldorf Salad', 'An American and his wife get unsatisfactory service at Fawlty Towers when he orders a Waldorf salad, after the kitchen has closed.', 32, '1979-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 2), 4, 'The Kipper and the Corpse', 'Unknown to Basil, a guest dies in the night and he tries to serve him breakfast anyway and an obnoxious woman insists on service for her dog.', 32, '1979-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 2), 5, 'The Anniversary', 'Sybil leaves before Basil''s surprise anniversary party and Basil spends the evening trying to convince their friends she''s ill.', 29, '1979-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072500')) AND numero_temporada = 2), 6, 'Basil the Rat', 'The health inspector is coming and Basil tells Manuel to get rid of his pet rat, which he later finds out is named Basil.', 34, '1979-10-25');
