INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 1, 'Series 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 1), 1, 'Big Brother', 'Del''s confident at last he''s on to a winner with Trigger''s consignment of Old English vinyl briefcases. How can his brother Rodney even think of abandoning the high-flying world of trading for a real job?', 30, '1981-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 1), 2, 'Go West Young Man', 'Rodney’s depressed. His mate Mickey Pearce has moved in on his bird – Monica of the fat thighs – and life isn’t exactly a social whirl. Del has the solution – they’ll all be millionaires in a year – cue his smooth friend Boycie and a very dodgy deal…', 31, '1981-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 1), 3, 'Cash and Curry', 'Del''s swooping in on the deal of a lifetime - it could keep them in Pilau rice forever. All he has to do is get hold of a poxy statue. Trouble is, he hasn''t reckoned on a touch of gang warfare.', 30, '1981-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 1), 4, 'The Second Time Around', 'Del''s rekindled passion with old flame Pauline and it looks like wedding bells are in the air again. Rodney''s not so thrilled after what happened to her first two husbands...', 30, '1981-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 1), 5, 'A Slow Bus to Chingford', 'Del has a dream: The Trotter corporate skyscraper, rising majestically against the Peckham skyline. It''s time for the latest moneymaking scam, Trotter''s Ethnic Tours. But, why are there no takers?', 30, '1981-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 1), 6, 'The Russians Are Coming', 'The threat of nuclear war looms over Peckham. What will become of the Nag''s Head if the Russians attack? One things guaranteed: the Trotters will be sitting pretty in their DIY shelter...', 30, '1981-10-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 2, 'Series 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 1, 'The Long Legs of the Law', 'Streuth! Rodder''s besmirching the good reputation of the Trotter family by dating a policewoman...', 28, '1982-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 2, 'Ashes to Ashes', 'Del''s busy selling Trig''s gran''s genuine antique urns. Trouble is, one of them is Trig''s Grandad''s last resting place!', 29, '1982-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 3, 'A Losing Streak', 'Del and Boycie are set to play the biggest poker game Peckham''s ever seen... But what exactly has Boycie got up his sleeve?', 31, '1982-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 4, 'No Greater Love....', 'Rodney''s got himself a bird at last! Unfortunately, she''s no spring chicken and her jailbird husband is about to be released...', 29, '1982-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 5, 'The Yellow Peril', 'Del''s got a job painting a Chinese restaurant - but is he wise to get some help from Rodney ''Leonardo'' Trotter?', 29, '1982-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 6, 'It Never Rains....', 'The Trotter family holiday is underway when Grandad runs into a bit of trouble with the Spanish police.', 30, '1982-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 2), 7, 'A Touch of Glass', 'Del introduces the Dresden-collecting aristocracy to some North Korean porcelain and his chandelier-cleaning service.', 28, '1982-12-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 3, 'Series 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 1, 'Homesick', 'Del Boy uses Rodney''s election as chairman of the local tenants'' association to plot a move to ground-floor accommodation.', 29, '1983-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 2, 'Healthy Competition', 'Rodney breaks up the Trotter partnership to go it alone - with Mickey Pearce! Does Mickey''s trip to the Costas mean that the duo are opening a Spanish branch already?', 30, '1983-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 3, 'Friday the 14th', 'The Trotters visit Devon for a weekend''s fishing but get involved with an escaped ''psycho'' from the local mental hospital.', 29, '1983-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 4, 'Yesterday Never Comes', 'Del Boy falls for posh tart Miranda when she comes to view a ''Queen Anne'' cabinet, but Miranda is more interested in the painting that the boys'' Gran lifted from her art dealer employer.', 30, '1983-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 5, 'May the Force Be with You', 'D.I. Slater is on the track of a stolen microwave oven and Del Boy is in the frame.', 30, '1983-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 6, 'Wanted', 'Rodney is on the run after he is accused of being the ''Peckham Pouncer'' - but where is that fragrant smell, wafting through the ventilation ducts of Nelson Mandela House, coming from?', 30, '1983-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 3), 7, 'Who''s a Pretty Boy?', 'Del Boy arranges for Rodney and Grandad to redecorate Denzil and Corinne''s flat. What is Corrinne going to say when she finds out that her canary is brown bread ?', 27, '1983-12-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 4, 'Series 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 1, 'Happy Returns', 'Rodney''s in love with Debbie from the newsagents. Could this mean the end of his dirty magazine fetish? Trouble is she''s only 19, and 19 1/2 years ago Del was pretty friendly with her mum...', 31, '1985-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 2, 'Strained Relations', 'After Grandad''s funeral, Delboy & Rodney are surprised to find that his brother, Uncle Albert, has moved in with them - bringing his nautical nightmares.', 30, '1985-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 3, 'Hole in One', 'The Trotters are potless, so Uncle Albert comes to the rescue by having an ''accident'' with the open cellar door of the Nag''s Head.', 30, '1985-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 4, 'It''s Only Rock and Roll', 'Rodney is the drumless drummer in Mental Micky''s band, ''A Bunch Of Wallies''. Del Boy takes on the job of manager, getting them an abortive St. Paddy''s night gig at The Shamrock Club.', 29, '1985-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 5, 'Sleeping Dogs Lie', 'Del''s on to a great money making scheme - looking after Boycie and Marlene''s new puppy Dukie for a steal at £60 a week. Should be a doddle - a bit of the old Pedigree Chum and they should be away. Then Dukie falls victim to Salmonella poisoning...', 30, '1985-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 6, 'Watching the Girls Go By', 'Del sets Rodney up with a date, but when she gets to the do at the Nag''s Head she makes Rodney wish he hadn''t.', 29, '1985-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 4), 7, 'As One Door Closes', 'When Del Boy''s hooky ''louvry'' door deal, financed with Denzil''s redundancy money, falls through, the boys attempt to repay him by catching a rare butterfly.', 30, '1985-04-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 5, 'Series 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 5), 1, 'From Prussia with Love', 'When a German damsel turns up in the Nag''s Head, she''s definitely in distress - and nine months pregnant at that. Rodney''s all beer and sympathy, but Del''s got an idea - could this be the answer to Boycie and Marlene''s dreams of a child and a golden opportunity to make a few bob along the way?', 30, '1986-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 5), 2, 'The Miracle of Peckham', 'Del Boy gets religion when the Madonna at the local church is seen to shed tears. But why does she only cry when it''s raining, and where did that lead in Del''s garage come from?', 30, '1986-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 5), 3, 'The Longest Night', 'A burglar makes a daring raid on the local supermarket just as Del and family are out buying their weekly French stick. What''s worse, Del sold him a duff watch down the local market...', 28, '1986-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 5), 4, 'Tea for Three', 'Del''s tampered with the sunbed controls and Rodney''s seeing red - literally! His face is done to a turn. He''ll hardly wow Trigger''s niece, Lisa, with his handsome good looks now, which leaves the way pretty clear for Del himself. But revenge should certainly be sweet when Rodders volunteers Del for a spot of hang gliding.', 31, '1986-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 5), 5, 'Video Nasty', 'Rodney gets a grant from the local college to make a film, but first he must come up with a viable screenplay. Del gets him a secondhand typewriter, and also suggests a storyline of ''A Rhino Loose in the City''. To make matters worse, the director, Mickey Pearce, fed up with waiting for Rodney to write the story, starts making porn films, only for Rodney to end up starring in one.', 29, '1986-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 5), 6, 'Who Wants to Be a Millionaire?', 'Del Boy gets the chance to make a new start (and to become a millionaire) in Australia - fronting Jumbo Mills''s used car business.', 30, '1986-10-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 6, 'Series 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 6), 1, 'Yuppy Love', '''80s fever is spreading fast! Del Boy''s on the up and into the exciting world of red braces and yuppy sorts. Armed with his filofax and briefcase, he''s ready to take on the city - well, Peckham anyway. Meanwhile, Rodney''s on the pull, with a classy new bird called Cassandra. Wonder what she''ll think of Nelson Mandela House...', 48, '1989-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 6), 2, 'Danger UXD', 'Just faking a signature on a delivery note means that Del can take possession of 50 dolls for absolutely nothing. The only problem is that ''Lusty Linda'' and ''Erotic Estelle'' are not exactly what he had in mind and would seem more appropriate to Dirty Barry''s dubious trade than to the local toyshop...', 48, '1989-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 6), 3, 'Chain Gang', 'It''s the deal of a lifetime! Faced with the opportunity to buy 250 18 carat gold chains from retired jeweller Arnie, Del can''t resist. Hastily a multi-million dollar business consortium is formed - well, Mike from the Nag''s Head, Trig, Boycie, Uncle Albert and a reluctant Rodney, anyway. Everything''s pretty cushty until Arnie''s taken ill just as the deal is about to be sealed, and Del is left feeling that all that glitters...', 50, '1989-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 6), 4, 'The Unlucky Winner Is...', 'Rodney''s won a holiday for three in the Mediterranean, courtesy of Del and the Megaflakes drawing competition. The only snag is he''s got to pretend he''s 14 years old all week. Should be a doddle - all he''s got to do is keep his head down. Then the skateboarding and breakdancing competitions begin...', 50, '1989-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 6), 5, 'Sickness & Wealth', 'While excruciating stomach cramps and a constant diet of health salts might drive some people to visit the doctor, not our Del! Oh no, he''s only suffering from that scourge of all yuppies, PMA - Positive Mental Attitude! So it''s going to require some nifty plotting by Rodney and Uncle Albert to get Del to visit the dreaded ''D'' word!', 57, '1989-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 6), 6, 'Little Problems', 'With his diploma in Computer Science, new job in Cassandra''s father''s firm and impending marriage, Rodney''s certainly on the up. Del''s even promised to take care of his share of the flat deposit. Only problem is, Del''s gone and got himself into a bit of bother over some hooky mobile phones with the less-than-understanding Driscoll brothers, and unless he comes up with £2,000 pretty sharpish they''re going to take care of him...', 50, '1989-02-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')), 7, 'Series 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 1, 'The Sky''s the Limit', 'What can Albert and Del do about Rodney leaving Cassandra and moving back in? Alan suggests that Rodney pick her up when she arrives back from her week in Spain. However, chaos at Gatwick means that the evening Rodney planned doesn''t happen. Could there be some connection with Del''s purchase of a satellite dish?', 50, '1990-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 2, 'The Chance of a Lunchtime', 'Raquel has an audition for a play, and Del has volunteered to help her rehearse. Rodney and Cassandra meet for supper, each thinking that the other made the first move. Things seem to be going well before Rodney gets tangled up with Trudy. Del tells Albert and Rodney that he sees two people when he looks at Raquel. Either Raquel''s pregnant or Del''s drunk!', 49, '1991-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 3, 'Stage Fright', 'With Raquel pregnant, Del ''Yuppy'' Trotter''s plan to achieve millionaire status must move up a gear. So the chance to supply the cabaret at the Starlight Rooms for old ''friend'' Eric to the tune of 600 quid is too good to miss. With Raquel dusting off her vocal chords in the kitchen and Trig''s mate Tony Angelino, the singing dustman, waiting in the wings, everything''s sorted. Until Del discovers exactly who the real owner of the club is and the extent of Tony''s vocal range...', 50, '1991-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 4, 'The Class of ''62', 'A class of ''62 reunion in the Nag''s Head signals Roy Slater''s return to Civvy Street after years in the nick. But why has the crooked ex-copper decided to come back to Peckham when he is universally loathed? Just as Trig, Del, Boycie and Denzil begin to believe that he really has changed for the better, Del discovers the real reason for his return...', 49, '1991-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 5, 'He Ain''t Heavy, He''s My Uncle', 'After a night at the Nag''s Head, Uncle Albert comes home beaten up and tells tales of two, three or was it four muggers. But something isn''t right and he runs away from home. Finally Del Boy and Rodney realise where to find him.', 49, '1991-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0081912')) AND numero_temporada = 7), 6, 'Three Men, a Woman and a Baby', 'Del''s about to become a father, but even that can''t cheer Rodney up. The Polar Cap is melting, the rainforest is dying, the sea is being poisoned, and he hasn''t had ''a bit'' for months. Maybe one of Del''s new ponytail wigs could enhance his image in Cassandra''s eyes...', 49, '1991-02-03');
