INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 23, 'Relief Bartender', 'Sam hires a new bartender and appoints himself as host/manager of Cheers. But when his new strategy goes belly-up and he is forced to return to the bar, somebody has to be fired.', 24, '1986-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 24, 'Strange Bedfellows (1)', 'Local councilwoman Janet Eldridge comes to Cheers as part of her re-election campaign, and Sam finds hismelf smitten with her. Janet and Sam become a couple, but a jealous Diane joins the opposition campaign fearing that if Janet wins the election, she will win Sam''s heart as well. Meanwhile Frasier also joins the opposition campaign hoping to win Diane back.', 24, '1986-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 25, 'Strange Bedfellows (2)', 'Sam and Janet''s relationship is getting stronger and stronger whilst Diane gets more jealous. Janet suggests that Sam fire iane to sever all ties with his past, but Diane overhears and quits before he can fire her. Vera''s sister Donna is visiting the Petersons and Norm is worried that Donna will flirt with him like she did on her last visit.', 24, '1986-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 4), 26, 'Strange Bedfellows (3)', 'Janet has won the election and is hosting her press conference at Cheers. Diane turns up to apologize to Sam but ends up asking Janet some personal questions which causes Sam to throw her out of the bar. Later Sam and Janet talk and realize their relationship won''t work, so break it off. Sam then picks up the telephone, rings someone and then asks them to marry him..... Meanwhile Vera has been called away, so Donna is left alone with Norm, much to his horror.', 24, '1986-05-15');
