INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 11, 'The Book of Samuel', 'Woody delves into Sam''s legendary black book to find a date to impress his former girl friend, who is coming to Cheers to introduce her fiancé.', 24, '1986-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 12, 'Dance, Diane, Dance', 'Frasier''s effort to lighten a dance instructor''s harsh criticism of Diane''s efforts backfires when she decides to audition for the Boston Ballet.', 23, '1986-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 13, 'Chambers vs. Malone', 'Sam proposes to Diane again and ends up charged with assault and battery when she turns him down again.', 24, '1987-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 14, 'Diamond Sam', 'Sam regrets trying to buy Diane an engagement ring that is a cheap imitation.', 24, '1987-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 15, 'Spellbound', 'Diane and Carla console Loretta, who has caught Nick cheating on her. They counsel her to stand on her own two feet and leave Nick. When Nick comes into the bar to claim her back, a chivalrous Sam stands up for her. Nick takes that as a sign that Sam has stolen Loretta from him. So Nick threatens to steal the same from Sam, that being Diane. Nick makes an attempt to wine and dine Diane, then Loretta, then Carla and then any of the three who will give him the time of day. Meanwhile, Frasier, the chess expert, has met his match in simpleton Woody.', 24, '1987-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 16, 'Never Love a Goalie (1)', 'Carla falls for Eddie, a hockey goalie; meanwhile, Diane is foreman of a jury in an attempted murder trial.', 24, '1987-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 17, 'Never Love a Goalie (2)', 'Carla and Eddie are now in a relationship. Ever since Carla blew him the kiss and Eddie let in that cheap goal, Eddie has been on a slump. The most superstitious couple ever, Eddie and Carla analyze Eddie''s life routine since the slump started, the only change in routine being Carla in his life. Not only does Carla come to the conclusion that she may be a jinx, but so does every one else in the bar. Carla has to decide to dump Eddie and have him regain his winning streak, or stay with Eddie at the price of the Bruins. Or is there another solution? Meanwhile, Diane is still at the trial and still talking to whoever will listen to her. Reminiscent of 12 Angry Men (1957), Diane stands alone in the jury as the dissenting voice thinking that the accused is guilty, comparing the relationship of the accused and his victim wife to Sam and herself. If she can''t win in the court of law, she figures, out of a streak of good luck, that she can win outside the legal system.', 24, '1987-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 18, 'One Last Fling', 'For the bachelor party the guys at the bar throw for Sam, Woody offhandedly asks Diane if she would be the girl who jumps out of the cake. Although she abhors such male sexual rituals, she agrees if only to stop someone else from "pleasuring" Sam. At the party, just as Diane is ready to come out of the cake, Norm makes a comment which makes Sam re examine out loud for the first time this wedding and the fact that Diane will now be the one and only woman in his life. After jumping out of the cake mad at Sam for his comments, Diane later offers Sam a proposition: she will give him a last 24-hours of freedom to do whatever he pleases with whomever he pleases. Sam excitedly agrees until Diane throws in that she too will have her last 24-hours of freedom to do whatever she pleases with whomever she pleases. Will Sam still go along with Diane''s plan and if so what will he do and what will she do?', 24, '1987-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 19, 'Dog Bites Cliff', 'On his postal route, Cliff is bitten by a dog, and decides to sue the owner for $200,000. Madeline, the dog''s owner, ends up being a beautiful, voluptuous woman, but one that is up front about wanting to help Cliff despite the fact that she has little money. Cliff and Madeline start dating, the gang at the bar thinking that it only a ploy on her part for Cliff not to sue. Cliff realizes this is the case, but is still dating her in hopes of trading dropping the lawsuit for a roll in the sack. Madeline announces to everyone that her lawyer wants her to get Cliff to sign a waiver to absolve her of any responsibility, but she refuses to do so. Perhaps Madeline really does like Cliff. Or maybe she''s got other methods of getting her way. Madeline and Cliff make it all the way to bed in a nice suite at the Ritz, when... Meanwhile, Diane is off on a Buddhist monastery retreat for a couple of weeks.', 23, '1987-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 20, 'Dinner at Eight-ish', 'Frasier and Lilith invite Sam and Diane over for dinner to celebrate their first week of cohabitation. But things start going wrong when Lilith finds out Frasier and Diane were engaged, and she locks herself in the bathroom. Then Sam and Diane have an argument as well. Meanwhile Cliff agrees to babysit Carla''s kids.', 24, '1987-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 21, 'Simon Says', 'Diane badgers a noted British marriage counselor into seeing her and Sam for a pre-nuptial session, then refuses to heed his advice.', 24, '1987-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 22, 'The Godfather, Part III', 'Sam''s goddaughter Joyce Pantusso (the late Coach''s niece) has come to Boston for a visit. Not wanting her to get into trouble, Sam asks Woody to help her out and show her around - but Woody and Joyce have a surprise for Sam when they get engaged!', 23, '1987-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 23, 'Norm''s First Hurrah', 'Norm elaborates on his new position with a top CPA firm and is caught in his little white lies when the gang decides to surprise him at work. Meanwhile Cliff finds a $20 note - and Woody has lost one.', 23, '1987-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 24, 'Cheers: The Motion Picture', 'The gang tries to reassure a nervous Mr. and Mrs. Boyd back in Indiana that Woody is fine and has wonderful friends in Boston by making a home movie of an average day at Cheers.', 24, '1987-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 25, 'A House Is Not a Home', 'Diane is haunted by the memories of the couple who lived a long and happy life together in the home she and Sam have purchased.', 24, '1987-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 5), 26, 'I Do, Adieu', 'Dr. Sumner Sloane returns to Cheers on Diane and Sam''s wedding day to tell her that a publisher is interested in one of her class manuscripts if she can go to work immediately on rewrites.', 24, '1987-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 1, 'Home Is the Sailor', 'Sam returns to Cheers six months after he sold it to a large corporation to pursue a life of leisure on board a new boat. Now the boat has sunk and he''s looking for a job.', 24, '1987-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 2, '''I'' on Sports', 'Sam tries to dodge his bar duties so he can fill in for a friend as a sports broadcaster.', 24, '1987-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 3, 'Little Carla, Happy at Last (1)', 'Carla and Eddie plan to get married if they can get past superstition, Eddie''s mother, Carla''s children, and Rebecca''s nerves as she waits for her boss to show up at the bar.', 23, '1987-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 4, 'Little Carla, Happy at Last (2)', 'Carla and Eddie plan to get married if they can get past superstition, Eddie''s mother, Carla''s children, and Rebecca''s nerves as she waits for her boss to show up at the bar.', 23, '1987-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 5, 'The Crane Mutiny', 'The gang tries to convince Frasier that Rebecca desires him after he quarrels with Lilith and Rebecca replaces Sam''s picture with one of Robert Urich.', 24, '1987-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 6, 'Paint Your Office', 'Norm gets to know Rebecca better when he paints her office as a way of paying off his bar tab.', 24, '1987-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 7, 'The Last Angry Mailman', 'Cliff is opposed to selling out the family home so a convenience store can be built there, but his mother is all for the idea. Meanwhile, the gang tries to find out about Rebecca''s college knickname- ""Backseat Becky"".', 24, '1987-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 8, 'Bidding on the Boys', 'Sam and Woody are up for bids at a charity auction but less than thrilled at their new ""owners.""', 24, '1987-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 9, 'Pudd''n head Boyd', 'Woody meets an elderly woman while wearing his makeup for the role of Mark Twain, and begins dating her.', 24, '1987-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 10, 'A Kiss is Still a Kiss', 'Rebecca asks an eager Sam to escort her to a company function to correct a false impression held by her boss.', 24, '1987-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 11, 'My Fair Clavin', 'Cliff helps his girl friend improve her appearance then regrets it when all sorts start to hit on her, including Sam.', 24, '1987-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 12, 'Christmas Cheers', 'Christmas Eve is depressing at Cheers as Sam rushes to find Rebecca a gift, Rebecca makes everyone work late, and Norm''s Santa Claus buddies gather to celebrate the end of the season.', 24, '1987-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 13, 'Woody for Hire meets Norman of the Apes', 'Woody tries to convince his friends that he got a small part on Spenser: For Hire and Cliff and Norm quarrel about a practical joke involving a chimpanzee.', 24, '1988-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 14, 'And God Created Woodman', 'Woody takes responsibility for a vase broken by Rebecca at a company party, and winds up pals with the big boss.', 24, '1988-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 15, 'Tale of Two Cuties', 'Annie Tortelli fills in for Carla at Cheers and Mr. Drake makes Rebecca turn green by personally hiring a pretty young woman to work at Cheers.', 23, '1988-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 16, 'Yacht of Fools', 'Rebecca thinks she''s finally got a shot at Evan Drake when he invites her and Sam for a weekend aboard his yacht.', 24, '1988-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 17, 'To All the Girls I''ve Loved Before', 'Frasier''s bachelor party turns out depressing and bleak while Lilith''s shower threatens to burst into flames.', 24, '1988-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 18, 'Let Sleeping Drakes Lie', 'Rebecca moons over Evan Drake''s bedroom as Norm repaints it, but she''s caught when the man returns unexpectedly.', 24, '1988-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 19, 'Airport V', 'Carla tries to conquer her fear of flying with Frasier''s help and Rebecca waits tensely for a visit from a restaurant critic.', 24, '1988-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 20, 'The Sam in the Gray Flannel Suit', 'Rebecca is hurt and jealous when Sam''s promoted to corporate headquarters until she finds out why he was moved up.', 24, '1988-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 21, 'Our Hourly Bread', 'Rebecca decides to take Woody''s suggestion of raffling off a Caribbean vacation to get the bar out of a slump.', 24, '1988-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 22, 'Slumber Party Massacred', 'Lilith and Rebecca throw a teenage slumber party to cheer up Carla after she learns she''s soon going to be a grandmother.', 24, '1988-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 23, 'Bar Wars', 'The gang at Cheers declares war when rival bar, Gary''s Old Town Tavern, steals the trophy celebrating their one and only sporting victory in a bowling tournament.', 23, '1988-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 24, 'The Big Kiss-Off', 'Sam and Woody wager over who can be the first to plant a three-second kiss on Rebecca.', 24, '1988-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 6), 25, 'Backseat Becky, Up Front', 'A desperate Rebecca goes to extraordinary lengths for a moment alone with Evan Drake as he prepares to move to Japan.', 23, '1988-05-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0083399')) AND numero_temporada = 7), 1, 'How to Recede in Business', 'Rebecca is still smarting from Evan Drake''s departure to Japan. So instead of men, she focuses her energies on furthering her career - she figures that Evan Drake took all the key players from the company to Japan with him, and thus all those that knew she is a "washout" are now all gone - and buying a Mercedes. But realistically, her defences are weakened, so when Sam asks her out again, she accepts, albeit without much enthusiasm. Just as Rebecca and Sam are about to go on their first date, Rebecca''s new boss, Greg Stone, comes to the bar. Rebecca, having a boss fixation, drops Sam at the sight of Mr. Stone. For her, it is love at first sight all over again.', 23, '1988-10-27');
