INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072562')) AND numero_temporada = 5), 17, 'Strother Martin/The Specials', 'The host for the episode is Strother Martin, and the musical guest is The Specials. The skits for this episode are as follows: Rosalyn Carter talks about sections of the 1980 census intended for illegal aliens, including questions about how they got into the US, where they would hide if the INS came to their homes, and how much they would be willing to do housework for. During his opening monologue, Strother Martin reveals that he was asked to host the show because Lorne Michaels mistook him for Tennessee Williams, and so far he''s been keeping up the act. At Camp Beau Soleil, the campers are forced to learn French by the brutal camp counselor, Le Capitain, but a camper named Luke is determined to escape. Additional skits include a variety show will, the Conductor''s Club, Any Town, and Food. The Specials perform "Gangsters" and "Too Much, Too Young".', 67, '1980-04-19');
