INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072562')), 14, 'Season 14', 'Saturday Night Live aired its fourteenth season during the 1988 - 1989 television season on NBC. The season began on October 8, 1988, and ended on May 20, 1989. 20 episodes were produced. Before the start of the season, no changes were made to the cast. However, as the season progressed Lorne Michaels would hire two new people to the cast: Mike Myers and Ben Stiller, who joined the show midseason as featured players. Stiller had actually appeared on the show before; his film made it onto the show in the episode hosted by Charlton Heston in 1987.
