INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072562')), 20, 'Season 20', 'Saturday Night Live aired its twentieth season during the 1994–95 television season on NBC. The twentieth season began on September 24, 1994 and ended on May 13, 1995. Much like seasons six and eleven, this season was lambasted by critics for its decline in quality. Season twenty suffered from having sketches based on very thin premises, a high number of which focused on or mentioned O. J. Simpson''s 1995 murder trial.
