INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072562')), 21, 'Season 21', 'The twenty-first season began September 30, 1995 and ended on May 18, 1996. 20 episodes were produced. SNL once again dodged cancellation from season twenty''s low ratings and scathing reviews about the show''s decline in quality. Only five cast members: Norm Macdonald, Mark McKinney, Tim Meadows, Molly Shannon and David Spade returned to the show from the previous season. This would be the final season for David Spade. Spade had agreed to stay only for a year so that he could be a bridge between the old and new casts. Newcomers David Koechner and Nancy Walls were also let go after this season.');
