INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072562')), 22, 'Season 22', 'The twenty-second season began on September 28, 1996 and ended on May 17, 1997 with 20 episodes in all. Many changes happened before the start of the season. David Koechner and Nancy Walls were both let go after one season with the show. David Spade left the show on his own terms. This season is also notable for the people who hosted. Seven of the twenty hosts were former cast members. They included Dana Carvey, Robert Downey, Jr., Phil Hartman, Chris Rock and Martin Short. Chevy Chase and Mike Myers would host later in the season. This would mark Chase''s final time hosting before getting banned.');
