INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0072562')), 23, 'Season 23', 'The twenty-third season started September 27, 1997 and ended on May 9, 1998, with 20 episodes being produced. A few changes happened before the start of the season; Colin Quinn was promoted to repertory status and Mark McKinney left the show while Fred Wolf left in the start of the twenty-second season. This season was also notable for not having any featured players or any new cast members. This season was also the only season to have an opening sequence that didn''t show any shots of New York City, being replaced by a 1950''s-inspired design.');
