INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 1, 'Season 1', 'Sent to prison by a military court for a crime they didn''t commit, these four commandos escaped from a maximum-security stockade and now survive in the Los Angeles underground as soldiers of fortune. So, if you have a problem and there''s no one else who can help, and if you think you can find them, maybe you can hire The A-Team.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 1, 'Mexican Slayride', 'Newspaper reporter, Amy Allen, sets out to prove the A-Team really exists and ends up hiring them to rescue one of her fellow reporters whose been kidnapped by Mexican outlaws.', 95, '1983-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 2, 'Children of Jamestown', 'After the A-Team rescues a girl from a crazed cult leader, they are captured by the man''s followers and made the quarry of a death hunt.', 48, '1983-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 3, 'Pros and Cons', 'B.A.''s friend is held in a prison where the warden holds fight-to-the-death-boxing matches whose winner receives short-lived freedom.', 49, '1983-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 4, 'A Small and Deadly War', 'Hannibal plays cat and mouse with a renegade S.W.A.T. A-Team that''s committing murders for hire.', 49, '1983-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 5, 'Black Day at Bad Rock', 'While treating a seriously wounded B.A., a suspicious small town doctor notifies the sheriff, who fears that B.A. may be part of a biker gang returning to free its jailed leader.', 49, '1983-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 6, 'The Rabbit Who Ate Las Vegas', 'The A-Team gets involved in a mob power play when two girls ask them to find their college professor who went to Las Vegas with a perfect gambling system and never came back.', 49, '1983-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 7, 'The Out-of-Towners', 'The A-Team takes up the cause of New York shopkeepers against neighborhood protection racketeers.', 49, '1983-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 8, 'Holiday in the Hills', 'B.A.''s fear of flying is justified when the A-Team''s plane crashes in the backwoods where they must battle mountain men to keep a man from being burned at the stake.', 49, '1983-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 9, 'West Coast Turnaround', 'The A-Team delivers produce to the market for a farmer who is slowly being driven out of business by a land-hungry rancher.', 49, '1983-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 10, 'One More Time', 'The US government recruits the A-Team to rescue a general and his daughter from guerillas in Borneo.', 49, '1983-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 11, 'Till Death Do Us Part', 'The A-Team has to rescue a reluctant bride being forced to marry her late father''s business partner.', 49, '1983-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 12, 'The Beast from the Belly of a Boeing', 'Hannibal''s plan to free a hijacked airborne 747 requires a bit of adjustment when B.A. becomes cataleptic and Murdock temporarily blinded.', 49, '1983-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 1), 13, 'A Nice Place to Visit', 'The A-Team comes to the aid of a small town being terrorized by a murderous family.', 47, '1983-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 2, 'Season 2', 'Pile into that famous black van for another season of adrenaline-pumping adventure with Hannibal, Face, Murdock and B.A. as they fight for justice against dangerous criminals, while staying one step ahead of their archenemy, Colonel Decker.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 2), 1, 'Diamonds ''n Dust', 'The A-Team agrees to transport explosives to a Zimbabwe diamond mine after the owner dies trying to do it himself.', 48, '1983-09-20');
