INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 6, 'Body Slam', 'Hulk Hogan asks his old friend B.A. for the A-Team''s help against a mobster who is out to close down a youth center for no apparent reason.', 49, '1985-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 7, 'Blood, Sweat and Cheers', 'Someone sabotages a car at a regional stock-car race and attracts the A-Team''s attention-the car belongs to Hannibal''s nephew.', 50, '1985-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 8, 'Mind Games', 'Face quits the A-Team after receiving a full government pardon and quickly becomes a celebrity, the rest of the A-Team keeps an eye on him suspecting the pardon''s not 100% legit.', 49, '1985-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 9, 'There Goes the Neighborhood', 'The A-Team moves a rock star threatened with kidnapping into a quiet suburban neighborhood, which doesn''t stay quite for long.', 48, '1985-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 10, 'The Doctor Is Out', 'The A-Team travels to South America to find Murdock''s psychiatrist, accompanied by a woman claiming to be his daughter.', 48, '1985-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 11, 'Uncle Buckle-Up', 'The A-Team discovers a kiddie show is a front for a heroin ring when Hannibal auditions for a part.', 48, '1985-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 12, 'Wheel of Fortune', 'Murdock''s fortunes rise and fall as he uses Face''s system to win big on "Wheel of Fortune" but then is kidnapped during a plot to steal a Soviet gunship.', 48, '1986-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 13, 'The A-Team is Coming, The A-Team is Coming', 'Soviet spys need the A-Teams help in preventing the theft of an American satellite weapon, whose disappearance would disrupt world peace.', 47, '1986-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 14, 'Members Only', 'Face''s chances of getting into an exclusive country club are severely hampered by the A-Team''s battles on club property with a crooked bank president.', 48, '1986-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 15, 'Cowboy George', 'Face believes he''s booked country singer Cowboy George into one of the roughest dance halls in the Southwest, but his agent friend delivers Boy George instead.', 49, '1986-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 16, 'Waiting for Insane Wayne', 'When Murdock gets mistaken for an insane mercenary the A-Team is drawn into a fight over property rights and an oil well.', 49, '1986-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 17, 'The Duke of Whispering Pines', 'One of B.A.''s old girlfriends has a problem; her husband, B.A.''s old college rival, has disappeared.', 49, '1986-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 18, 'Beneath the Surface', 'Face returns to his orphanage for a reunion and meets an old friend''s sister, who''s worried about her brother''s disappearance, and an old girlfriend, who is in cahoots with Fulbright to trap Face for the reward.', 49, '1986-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 19, 'Mission of Peace', 'Senior citizens hire the A-Team to protect their historic Texas mission home and tourist attraction from land developers.', 49, '1986-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 20, 'The Trouble with Harry', 'Hulk Hogan comes to visit B.A. but the reunion is interrupted by a cry for help from a troubled youth with an alcoholic father.', 48, '1986-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 21, 'A Little Town with an Accent', 'The A-Team discovers an organized crime kingpin believed to be dead is behind the intimidation of several gas station owners.', 48, '1986-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 4), 22, 'The Sound of Thunder', 'General Fulbright captures the A-Team then offers to let them prove their innocence by accompanying him to Vietnam and rescuing a POW who could clear their names.', 48, '1986-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')), 5, 'Season 5', 'B.A., Hannibal, Murdock and Face confront their greatest challenges yet when the mysterious General Stockwell joins them to battle bad guys that include hitmen, hijackers, and mercenary monks.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 1, 'Dishpan Man', 'The A-Team is blackmailed by retired General Stockwell, who kidnaps Hannibal and threatens to have him prosecuted if the A-Team fails to secure the release of hostages held on a plane in Spain.', 49, '1986-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 2, 'Trial by Fire', 'The A-Team''s court martial begins and a surprising motive for the death of Colonel Morrison is revealed.', 48, '1986-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 3, 'Firing Line', 'General Stockwell interferes with the plans of Murdock and Frankie to free the rest of the A-Team before the Army can execute them.', 49, '1986-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 4, 'Quarterback Sneak', 'The A-Team uses a football game as a cover to sneak a chemical warfare scientist out of East Germany.', 49, '1986-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 5, 'The Theory of Revolution', 'The outbreak of a revolution interferes with the planned rescue of three Americans from a Third World Country.', 47, '1986-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 6, 'The Say UNCLE Affair', 'Stockwell is kidnapped by his former partner who has "gone bad" and the A-Team has 18 hours to find him or forever loose any chances of securing a pardon.', 48, '1986-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 7, 'Alive at Five', 'Face plans to leave the A-Team but gets involved in the rescue of a newswoman from a paranoid mob chief.', 48, '1986-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 8, 'Family Reunion', 'A former political adviser offers to trade a diary for a reunion with his daughter- who Face is hitting on, but Murdock learns that the man may be Face''s father and the daughter Face''s sister.', 49, '1986-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 9, 'Point of No Return', 'Stockwell refuses to allow the A-Team to go after Hannibal when he fails to check in while on a solo mission in hostile territory.', 48, '1986-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 10, 'The Crystal Skull', 'The A-Team''s effort to secure a valuable religious artifact involves them with warring island tribes who mistake Murdoch for a God and some unusual missionaries.', 48, '1986-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 11, 'The Spy Who Mugged Me', 'Murdock poses as suave secret agent to catch a killer before he can complete another assignment.', 49, '1986-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 12, 'The Grey Team', 'The A-Team must bring a girl in who has stolen a briefcase from her father, filled with material she believes he''s selling to the Soviets.', 48, '1986-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0084967')) AND numero_temporada = 5), 13, 'Without Reservations', 'Frankie and Face visit Murdock at his job in a restaurant, and all three become hostages of mobsters out to kill a patron, the US Attorney General.', 48, '1987-03-08');
