INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 1, 'The Secret of the Dragon Balls', 'Bulma''s search for six more Dragon Balls leads her to a remote valley and to Son Goku, who is in possession of one of the balls. Their relationship gets off to a rocky start, but after Goku saves Bulma''s life, the two join forces in search of the remaining five Dragon Balls. They had better take care, for an evil force - Pilaf - also seeks the Dragon Balls.', 25, '1986-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 2, 'The Emperor''s Quest', 'Without realizing where they are, Bulma and Goku camp near Ryugadani, a foreboding land where one of the Dragon Balls lies hidden. Pilaf dispatches his henchmen to recover the ball, but they and Goku run into each other and a pack of ravenous wolves. Who will emerge the winner?', 25, '1986-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 3, 'The Nimbus Cloud of Roshi', 'As a token of appreciation, the Turtle Hermit presents Goku Kinto''un, a magical flying cloud that can be ridden only by someone pure of heart. He gives Bulma an orange bauble that he wears around his neck, a seemingly worthless stone that had washed up on the beach. It turns out that this "bauble" is in fact a Dragon Ball. Unfortunately for our friends, Pilaf and his aids, Mai and Shu, are also after this same Dragon Ball...and now they know that Bulma has it.', 25, '1986-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 4, 'Oolong the Terrible', 'Goku and Bulma arrive at a certain village, where the fifth Dragon Ball is located. Goku is mistaken for the freely shape-shifting monster Oolong, who raids the village, and is hit by a sudden attack from one of the villagers! Bulma makes a promise with the villagers that “We’ll take care of Oolong in exchange for the Six-Star Ball that’s in this village”. Goku disguises himself as one of the village girls, and the captured monster’s true identity turns out to be a piglet, of all things!! Bulma and Goku obtain the Six-Star Ball. Taking in Oolong as their ally, they continue their adventure to find the remaining Dragon Balls!!', 25, '1986-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 5, 'Yamcha the Desert Bandit', 'Goku and the others aim for Mt. Frypan. Because Bulma dropped her capsules into a river, they end up having to cross a desert on foot! Completely exhausted, Bulma rests there. At this point, the desert bandit Yamcha appears, and tries to seize Oolong’s capsules. Goku battles Yamcha, but he has no power on account of his empty stomach. At the critical moment, Bulma wakes up and Yamcha, who can’t bear to be around women, runs away with a few sharp parting remarks.', 25, '1986-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 6, 'Keep an Eye on the Dragon Balls', 'Yamcha attacks at night in an attempt to steal Oolong’s capsules! As Yamcha looks into the condition of their opponents, he learns about the Dragon Balls. Yamcha and Pu’er try to steal Goku and the others’ Dragon Balls through any means necessary, but fail!! At this point, they come up with the plan of waiting for Goku and the others to gather all seven Dragon Balls, and then steal them. Unaware of this, Goku and the others aim for Mt. Frypan in search of the sixth Dragon Ball.', 25, '1986-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 7, 'The Ox King on Fire Mountain', 'After arriving at Mt. Frypan, Goku and the others land in a pinch when they are spotted by Gyumao, who stands guard over his castle!! However, Gyumao’s attitude quickly changes when he learns that Goku and the others know Muten Roshi! In order to extinguish Mt. Frypan’s fire, Gyumao requests Goku go with his daughter Chi-Chi and borrow Muten Roshi’s Basho Fan. Goku finds Chi-Chi, who can ride on Kinto''un, but he powers down when she grabs his tail! Seeing this, Yamcha discovers Goku’s weakness!!', 25, '1986-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 8, 'The Kamehameha Wave', 'Having thrown away the Basho Fan, Muten Roshi heads to Mt. Frypan to extinguish its flames himself!! Muten Roshi’s grand attack, the Kamehameha, puts out the blazing flames! Goku and the others safely obtain the Dragon Ball, and are about to head off in search of the final one. But Bulma is detained by Muten Roshi, since she promised to let him fondle her breasts if he put out the flames. Bulma gets out of this pinch by asking Oolong to transform into her.', 25, '1986-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 9, 'Boss Rabbit''s Magic Touch', 'Goku and the others visit a stand in order to fill up on gasoline. The townspeople are all frightened of Bulma, who is wearing rabbit ears. They don’t understand why, but then some scoundrels calling themselves the Rabbit Gang show up! Their boss, the Carrotizor, has the power to turn anyone who touches his hand into a carrot!! Bulma is turned into a carrot by him. Unable to merely watch, Yamcha rescues Bulma. Goku and the others defeat the Rabbit Gang, and once again set out to search for the Dragon Balls!!', 25, '1986-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 10, 'The Dragon Balls are Stolen!', 'Goku and the others aim for the final Dragon Ball! However, their Dragon Balls are stolen by Pilaf and his underlings, who are plotting to use the Dragon Balls to take over the world!! Wanting to have his wish granted by Shen Long, Yamcha once again ends up helping Bulma and the others in order to obtain the Dragon Balls. In order to get the Dragon Balls back, Goku and the others invade Pilaf’s secret base. But they are all caught by the ingenious trap set by Pilaf. Goku’s Four-Star Ball is in danger!!', 25, '1986-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 11, 'The Penalty is Pinball', 'After being put to sleep by sleeping gas, Goku and the others have the Four-Star Ball stolen from them! Pilaf finally has all seven Dragon Balls, and he attempts to call forth Shen Long!! In order to stop Pilaf’s scheme, Goku uses the Kamehameha to open a hole in the wall of the room that they are imprisoned in! As Pu’er and Oolong transform into bats and head out the hole to take back the Dragon Balls, Shen Long is finally summoned! Will the world become Pilaf’s…?!', 25, '1986-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 12, 'A Wish to the Eternal Dragon', 'Shen Long finally appears! Pilaf tries to say his wish, in order to rule the world!! Because Oolong said his wish of “Give me a girl’s panties” a moment sooner, his wish ended up being granted! With the wish granted, Shen Long returns again to the Dragon Balls, and they scatter to the four winds. Enraged, Pilaf imprisons Goku and the others in a room covered in fortified glass and iron plates, intending to kill them with the sun’s hot rays, but…?!', 25, '1986-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 13, 'The Legend of Goku', 'Goku and the others have been captured once again by Pilaf. That night, Goku looks at the full moon, and suddenly turns wild and starts transforming into an Oozaru!! He smashes the prison that they are imprisoned in, and Yamcha and the rest manage to escape, but having lost his reason, Goku continues to rampage!! Yamcha then cuts off Goku’s weakness, his tail! Goku wakes up after returning to normal. The party promises to reunite, and the Dragon Team splits up.', 25, '1986-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 14, 'Goku''s Rival', 'Done with collecting the Dragon Balls, Goku heads to the Turtle Hermit’s place to receive training! However, in order to become the Turtle Hermit’s pupil, the fee is to bring a pichi-pichi gal!! At the same time, a person comes from across the sea. The boy, who calls himself Kuririn, came in order to become the Turtle Hermit’s pupil, just like Goku! In order to be received as a pupil, Kuririn presents a large stash of porn magazines that he brought. Will he manage to safely become a pupil…?!', 25, '1986-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 15, 'Look Out for Launch', 'Goku and Kuririn set out in search of a pichi-pichi gal, the fee for becoming a pupil of the Turtle Hermit. Saving Lunch, a girl who was pursued by the police, they immediately bring her to the Turtle Hermit’s place! Having passed the test, Goku and Kuririn are recognized as the Turtle Hermit’s pupils!! But it turns out that Lunch is an incredibly peculiar girl with two personalities, and becomes either violent or peaceful each time she sneezes!!', 25, '1986-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 16, 'Find That Stone!', 'Moving to a large island, the Turtle Hermit begins the training. First, in order to learn Goku and Kuririn’s ability, he measures how fast they can run 100 meters. The two look promising, and the Turtle Hermit gives them some training before dinner. It’s a great trial where he throws a stone with the “turtle” mark on it into the jungle, then tells the two to find it! The person who doesn’t manage to find it will go without dinner! Goku and Kuririn take this severe training in earnest!! The sly Kuririn seizes victory in this contest!', 25, '1986-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 17, 'Milk Delivery', 'The basic training finally begins! To start off, Goku and Kuririn are given milk delivery as their early morning training! Carrying the milk boxes, they do things like skip and zig-zag around rows of trees!! Furthermore, they climb stone stairs that rise high into the air, cross over a valley on a large tree, cross through a desert of quicksand and a raging river while keeping their balance, and get chased by dinosaurs as a bonus! This is their ultra-hard milk delivery training that surpasses ordinary knowledge!!', 25, '1986-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 18, 'The Turtle Hermit Way', 'With their early morning training over, they continue on to their morning training. In order to strengthen their arms and legs, they train by plowing a field barehanded! After breakfast it’s study time!! After lunch, they take an afternoon nap until 1:30. During the afternoon they help out with construction work. It’s training where they sweat, toughen their muscles, and even receive a part-time job salary! Furthermore, they carry themselves through rough training to toughen their reflexes, swimming ten laps around a lake while being chased by sharks and dodging the frenzied attacks of bees, to finally end a full day of training!', 25, '1986-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 19, 'The Tournament Begins', 'Goku and Kuririn continue their training by wearing 40 kg shells on their back! The two are aiming for the Tenkaichi Budokai, which opens in a month!! The day before the tournament, the Turtle Hermit takes them to the island where it will be held! At the tournament registration area, Goku reunites with Yamcha, Bulma, Oolong, and Pu’er. Goku is delighted when he learns that Yamcha is also participating! The next day, the Tenkaichi Budokai is at last decided!!', 25, '1986-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 20, 'Elimination Round', 'The Tenkaichi Budokai is held once every five years! A mere eight people are able to participate in the tournament’s main event! The preliminaries to select those eight people are divided up into four blocks!! Goku and Kuririn fully display the results of the harsh training that they received from the Turtle Hermit!! Tossing a veteran to his defeat, Goku splendidly gains the right to participate in the main event! What’s more, Yamcha also advances well, and wins his ticket to the Tenkaichi Budokai main event!!', 25, '1986-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 21, 'Smells Like Trouble', 'The first round of the Tenkaichi Budokai main event is Kuririn vs. Bacterian! Bacterian is a formidable opponent who uses his filth as a weapon, with his foul smell paralyzing his opponents. With bad breath, farts, and the like, he assaults Kuririn with foul-smelling attacks!! The helpless Kuririn is finally downed!! At that time, Kuririn awakens from this nightmare of smells when Goku tells him “You don’t have a nose!” Launching a fierce counterattack against Bacterian, Kuririn breaks through the first round!', 25, '1986-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 22, 'Quarterfinals Begin', 'It’s the second match, Yamcha vs Jackie Chun! The mysterious old man Jackie Chun defies Yamcha’s rapid attacks, and breaks through even his special attack, the Roga fufu-ken (Wolf Fang Gale Fist)!! Furthermore, Jackie seizes victory by raising a wind with a swing of his left hand, blowing Yamcha out of bounds! In the third match, the serious Namu is assaulted by Ran-Fan’s sex appeal strategy!! But Namu achieves a turnabout victory when he defeats Ran-Fan with a single blow after freeing himself from distracting thoughts!', 25, '1986-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 23, 'Monster Beast Giran', 'At last it’s Goku’s turn! The one facing Goku in the fourth match was the powerful opponent Giran!! Goku is knocked around by Giran’s stream of unfair attacks! Giran traps Goku in the rubbery Guru-Guru Gum that he shoots from his mouth!! Goku is in an absolutely desperate pinch! Just as he is about to be thrown out of the ring, his chopped-off tail suddenly grows back, and his power multiplies! Seeing this, Giran surrenders!!', 25, '1986-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 24, 'Krillin''s Frantic Attack!', 'The fifth match is the semi-finals fight, Kuririn vs. Jackie Chun. Kuririn and Jackie’s battle unfolds at ultra-fast speed that the eye can’t follow!! The spectators who came to watch the Tenkaichi Budokai are extremely excited by the pair’s high level battle!! Kuririn puts up a good fight against Jackie, but he rushes to win! Because of this, he is hit by Jackie’s karate chops after Jackie goes around behind his back, and is downed!! Sadly, Kuririn is defeated during the semi-finals.', 25, '1986-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 25, 'Danger From Above', 'The sixth match is Goku and Namu’s semi-finals fight. Goku attacks Namu by imitating the Zanzouken that Jackie displayed during his fight with Kuririn. Namu skillfully dodges this attack! Namu attempts to finish Goku off with his special attack, the Tenku pekeji-ken! Goku is hit by the attack and downed, but revives right before the count of ten! Namu further comes out him with the Super Tenku pekeji-ken, but Goku breaks through the technique. Goku then advances to the finals!', 25, '1986-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 26, 'The Grand Finals', 'The finals for the 21st Tenkaichi Budokai have been decided! Goku is knocked out of bounds by Jackie. But he spins his tail like a propeller and comes back! Goku and Jackie at last put forth their best. The two fire a Kamehameha at the same time!! Goku’s Kamehameha evenly matches Jackie’s, and knocks it back!! Demonstrating a back-and-forth display of such attacks as the Zanzouken, the Suiken, and the Saruken, their red-hot battle continues!', 25, '1986-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 27, 'Number One Under the Moon?', 'Becoming serious against Goku, Jackie uses the Yoiko Min-Min Ken! Goku enters a deep sleep. He somehow manages to escape this pinch, but he is assaulted by Jackie’s special attack, the Bankoku-Bikkuri-Sho! With a shockwave like an electric current running up his entire body, Goku is robbed of the ability to move. But just as he’s about to surrender, his eyes catch sight of the full moon! Against Goku, who has transformed into an Oozaru once again, Jackie fires an extra-large Kamehameha!! What is Goku’s fate…?!', 25, '1986-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 28, 'The Final Blow', 'Jackie blew away the moon, guarding against Goku ever becoming an Oozaru again!! At the same time, Goku returns to his normal form, and the match is restarted. With their energy rapidly falling from exhaustion and hunger, the two muster the last of their power, and their clash unfolds. Having received slightly less damage, Jackie declares that he has won the championship, and he achieves victory. Having learned that there are many strong people in the world, Goku and Kuririn vow to train even harder!', 25, '1986-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 29, 'The Roaming Lake', 'Searching for the Dragon Balls, Goku comes to a desert region where he hears the legend of the moving lake. There, Goku rescues Namu as he is attacked by monsters. Namu has gone upstream to investigate why the river has dried up! After discovering that Giran and his tribe had damned up the river, Goku breaks the dam with a Kamehameha, but this time a sandstorm buries the river!! The villagers despair, but after the sandstorm leaves, it leaves behind the legendary lake.', 25, '1986-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 30, 'Pilaf and the Mystery Force', 'After the Dragon Radar is stolen by a thief, Goku spots it in a secondhand goods store. A Dragon Ball signal shows up there! However, the Dragon Ball that Pilaf and co. buy from the store owner is a complete fake! The store owner also tries to sell a fake to a mysterious army who are searching for the Dragon Balls, but they see through this and shoot him. The real Dragon Ball turns out to be in a bird’s nest on the roof of the shop!! Startled by the sound of gunfire, the bird flies off with the Dragon Ball.', 25, '1986-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 31, 'Wedding Plans?', 'The army that was searching for the Dragon Ball was in fact Captain Silver’s Red Ribbon Army unit. Silver and Pilaf go after the Dragon Ball. The Dragon Ball turns out to be inside the stomach of a monster that Gyumao defeats. Hearing that Goku is coming, they prepare a reception for him. Pilaf makes Shuu into a fake Goku, and enters the village, but the Silver Corp. attacks! Taking advantage of the confusion, Pilaf gets the Dragon Ball and flees to his moving base. Having reunited with Chichi, Goku perceives that something is amiss, and hurries to the village!!', 25, '1986-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 32, 'The Flying Fortress — Vanished!', 'Giving his parting words to Gyumao and Chichi, Goku goes after Pilaf and co. Meanwhile, following the signal on the Dragon Radar, Silver discovers Pilaf’s secret base. Calling for reinforcements, Silver commences a general offensive! Having infiltrated the base, Goku also hurries to where the Dragon Ball is!! Pilaf is forced to flee, but the moving base he is riding in is hit by the combined attacks of the Red Ribbon Army, and Goku is caught in the explosion!! The Dragon Ball finally falls into Silver’s hands.', 25, '1986-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 33, 'The Legend of a Dragon', 'After returning to Red Ribbon Army Headquarters, Silver receives his orders from the commander, and sallies forth to once again search for the Dragon Balls. Meanwhile, having been rescued by Kinto''un from the moving base’s explosion, Goku also reopens his search for the Four-Star Ball. Silver realizes that a baby monkey Goku saved on a mountain has a Dragon Ball, and shoots fire at the mountain! The monkeys are pursued by the fire. As Silver aims a rifle at the baby monkey, it is saved by Goku!! However, the Dragon Ball floats down the stream.', 25, '1986-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 34, 'Cruel General Red', 'Using the Dragon Radar that Bulma made, Goku easily spots the Dragon Ball that drifted down the river. However, Kinto''un is blown away by Captain Silver’s bazooka! After defeating Silver with a single swipe of his tail, Goku heads north in a plane flown by a robot who came out of a capsule. Goku shudders from the extreme cold. The robot is frozen solid as well, and the plane crashes!! Having been frozen solid, Goku is saved by a girl named Sno.', 25, '1986-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 35, 'Cold Reception', 'Goku wakes up in Sno’s house, and receives gentle care from her and her mother. Sno is frightened when she hears that Goku is searching for the Dragon Balls. In this village, General White of the Red Ribbon Army has taken the mayor hostage, and is using the townspeople to search for a Dragon Ball! After regaining his health, Goku defeats the soldiers who came in pursuit of him, and heads for General White’s base, Muscle Tower, in order to rescue the mayor! After defeating the soldiers outside, Goku immediately thrusts himself up to the second floor!!', 25, '1986-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 36, 'Major Metallitron', 'General White’s voice resounds throughout Muscle Tower. He provokes Goku as he ascends to the uppermost floor, where the mayor is. Goku defeats the soldiers on the second floor, and advances on to the third. The third floor was protected by the immortal giant, Sergeant Metallic! Goku has a hard battle against Metallic, who rises up again no matter how many times Goku knocks him down. He won’t stop, even after having his head blown off with a Kamehameha! It turns out he is a robot!! However, Metallic stops just as Goku is in a pinch. His battery had run out.', 25, '1986-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 37, 'Ninja Murasaki is Coming!', 'After infiltrating the pitch black fourth floor, Goku is hit by Master Sergeant Murasaki’s ninja attacks. He has a difficult battle against these relentless attacks! But Goku reads Murasaki’s movement, and his attacks turn the situation around. Goku breaks through Murasaki’s ninjutsu, one after the other. Finally, Murasaki’s sword breaks! Murasaki challenges Goku to an unarmed match, and Goku puts away the Nyoi-Bo. Murasaki takes advantage of this opening to throw a boomerang shuriken. Goku is caught off guard, and is hit directly in the back of the head!! Goku is in grave danger!!', 25, '1986-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 38, 'Five Murasakis', 'Unable to finish Goku off with the boomerang shuriken, Murasaki uses his final ninjutsu, Bunshin no Jutsu (Split-Image Technique). Having somehow increased to five people, the Murasakis each take out their different weapons! Unable to tell which of them is the real one, Goku has no choice but to run! However, it turns out the Mursakis are merely a set of quintuplets. Now aware that they are all real, Goku uses Zanzouken to defeat four of them in the blink of an eye. With no other card to play, Mursaki calls forth Artificial Human No. 8!!', 25, '1986-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 39, 'Mysterious Android No. 8', 'Artificial Human No. 8, who Murasaki summoned, turns out to have a gentle personality, and doesn’t like conflict. As Murasaki is about to destroy No. 8, who won’t listen to his orders, Goku blows Murasaki away with a single blow! Now Goku’s friend, No. 8 (Ha-chan) leads him to the uppermost level, floor six. Ha-chan tries to persuade White to stop doing bad things. But Goku and Ha-chan fall through a trap door to the fifth floor. Down there is the lair of the monster Buyon!!', 25, '1986-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 40, 'Horrifying Buyon', 'Imprisoned on the fifth floor, Buyon is a monster who is completely unaffected by Goku’s techniques! His body can absorb any attack. Goku is in an absolutely desperate pinch!! But Goku destroys the wall, having remembered the time when he was frozen!! Buyon is frozen solid by the frigidly cold air!! After enduring the frigid air by huddling close to Ha-chan, who is immune to the cold, Goku manages to shatter Buyon with a single blow!! Returning to the sixth floor, Goku attacks White.', 25, '1986-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 41, 'The Fall of Muscle Tower', 'After being beaten up by Goku, White guides the two of them to the mayor’s room. The second Goku and Ha-chan let their guard down, he takes the mayor hostage! Ha-chan doesn’t know what to do. Goku is downed after being hit with a single shot from the powered gun!! The second shot will finish him off. However, Ha-chan acts as a human shield and protects Goku!! With White in a panic, Ha-chan’s punch explodes!! Having saved Goku and the mayor, Ha-chan destroys Muscle Tower.', 25, '1986-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 42, 'The Secret of Dr. Flappe', 'It turns out that Ha-chan had the Dragon Ball. He had hidden it, knowing that the villagers would be killed once they found it. The mayor recommends that Ha-chan stay in the village, but Ha-chan says it is dangerous, because of his self-destruct mechanism. In order to get Ha-chan’s self-destruct mechanism removed, they visit his creator, Dr. Flappe. But Murasaki has gone there ahead of them! He steals Goku’s luggage, in an attempt to find the Dragon Balls. However, it only contained Goku’s bento (single-portion meal)?! The self-destruct mechanism is safely removed.', 25, '1986-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 43, 'A Trip to the City', 'In order to fix his malfunctioning Dragon Radar, Goku heads to West City, where Bulma lives. Kinto''un is also revived, and the trip goes well. However, Goku doesn’t know Bulma’s address! While having trouble with hoodlums, Goku goes around asking for Bulma, but there’s no way for him to find her in such a big city. Goku is taken to Bulma’s house by a policeman. It turns out that Bulma is the sole daughter of Capsule Corporation, a large company famous even in this metropolis!!', 25, '1986-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 44, 'Master Thief, Hasky', 'Goku finally reunites with Bulma. However, Bulma and Yamcha are right in the middle of an argument! Riding on Kinto''un with Bulma, who has become small using the micro-band, Goku reunites with Yamcha and the others. But Yamcha, unaware of the shrunken Bulma, talks bad about her right to her face!! Goku and the others set off for the floating amusement park, with Bulma in a completely bad mood. Husky is there, an entrepreneur hired by the Red Ribbon Army, and is aiming for Goku’s Dragon Balls.', 25, '1986-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 45, 'Danger in the Air', 'Drawing closer to Goku and the others as they play in the floating amusement park, Husky tries to seduce Yamcha, who was carrying a Dragon Ball. Figuring out his opponent’s true identity, Yamcha corners her but is taken out by Bulma, who mistakes this for a love scene!! Husky leaves a bomb and runs away. Goku breaks the bomb’s controls just in the nick of time, and retakes the Dragon Balls. But it’s a completely angry Bulma who sets out with Goku to search for the Dragon Balls.', 25, '1987-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 46, 'Bulma''s Bad Day', 'Bulma and Goku arrived at the middle of the sea. This was General Blue’s territory, where he’s searching for the Dragon Balls! Dropped into the sea by Bulma from a nearby island, Goku dives, but it is very deep and he can’t hold his breath! Left on her own, Bulma wanders around the island trying to buy capsules, but it turned out there was a Red Ribbon Army base there!! Goku comes running and defeats the soldiers who are assaulting Bulma!! Goku suggests that they borrow a submarine from the Turtle Hermit.', 25, '1987-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 47, 'Kame House — Found!', 'Goku arrives at Kame House, but Kuririn and Lunch are using the submarine to go shopping. The Turtle Hermit asks for the micro-band in exchange for letting them borrow the submarine. He plans on making himself small and peeking in on her in the toilet and bath! However, when the Turtle Hermit goes to peak on Bulma when she uses the toilet, he’s flushed down the toilet!! When Kuririn comes back, Goku and Bulma set off with him. Meanwhile, having used the dragon radar to follow Goku’s Dragon Balls, General Blue discovers Kame House.', 25, '1987-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 48, 'Deep Blue Sea', 'In addition to his group pursuing Goku and the others, General Blue launches a detached group to attack Kame House. They believe that the Turtle Hermit is the scientist who created the Dragon Radar. Going after the Dragon Ball which fell into the sea-bottom chasm, Goku and the others enter the cavity in the chasm from the other side, and discover a cave. General Blue’s submarine then suddenly attacks! Bulma and Kuririn panic when they learn that the ones attacking them are the Red Ribbon Army!! Blue’s submarine pursues Goku and the others as they flee into the cave!!', 25, '1987-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 49, 'Roshi Surprise', 'General Blue’s detached group arrives at Kame House. The commander threatens the Turtle Hermit, but is instead easily defeated! The commander takes Lunch hostage, but he is completely cornered after Lunch sneezes and becomes violent. Meanwhile, after fleeing into the cave, Goku and the others’ submarine has entered a waterless cave. They run off, leaving the submarine behind. For some reason, the cave is equipped with electric lights… This was the pirates’ secret base!!', 25, '1987-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 50, 'The Trap is Sprung', 'Treasure is supposedly hidden in the pirate’s cave. And to protect that treasure, naturally traps were set! Goku and the others somehow manage to pass through these traps, such as a wall that shoots spears, or a trap door that opens above lava. The Red Ribbon troops are completely wiped out, except for Blue!! Goku and the others come to the end of the path, and come out into the pirate’s sea-bottom dock. Goku can sense that something is moving. A skeleton-type battle robot appears, and immediately starts attacking them!!', 25, '1987-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 51, 'Beware of Robot', 'Goku and Kuririn challenge the skeleton robot to a battle. However, the robot is strong! Goku is buried in rubble, and Bulma and Kuririn are cornered inside a building. Just as the two are in a hopeless situation, Goku emerges from the rubble and saves them! After Bulma and Kuririn run off, Goku performs a dive-bomb attack from the roof!! This makes even the powerful robot explode, and Goku follows after the two. However, Blue alters the sign left by Bulma and Kuririn!!', 25, '1987-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 52, 'The Pirate Treasure', 'Goku takes the wrong path due to Blue’s trick. The robot’s explosion makes the cave begin to collapse! Bulma and Kuririn arrive at the pirate’s hiding place, but Blue follows them there. An even fight unfolds between Blue and Kuririn! However, Kuririn becomes unable to move when he looks into Blue’s shining eyes. It turns out that Blue has psychic powers!! Goku comes running in as Blue is about to finish Kuririn off!!', 25, '1987-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 53, 'Blue, Black and Blue', 'Goku overwhelmingly dominates in his battle against Blue! Beaten about, Blue uses his psychic powers to paralyze Goku, and pulls out a rifle! Goku is in a pinch!! But Blue is surprised by a mouse that passes by, and his psychic powers are undone! Counterattacking, Goku KO’s Blue!! Bulma and Kuririn try to escape in a pirate submarine, and Goku follows after them once he’s found the Dragon Ball. The cave is about to collapse.', 25, '1987-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 54, 'Escape From Pirate Cave', 'Just as the cave is about to collapse, Goku appears at the sea-bottom dock!! He has with him the mouse he owes his life to. Bulma launches the submarine, but it runs out of gas and stops. The sea-bottom canal is collapsing! Goku’s Kamehameha pushes the submarine to safety!! They return to Kame House with a pirate diamond. However, Blue has tenaciously survived, and follows them!! What’s more, Lunch takes the diamond and leaves after changing into her violent form.', 25, '1987-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 55, 'Penguin Village', 'Blue uses his psychic powers to manipulate ropes to attack Goku and the others, who are relaxing after having returned from the sea-bottom cave! Everyone is tied up, and Goku has his tail grabbed and cannot put out his full power!! Blue steals the Dragon Balls and plants a bomb, then flees. Goku is saved by Lunch, who returns after reverting to her original personality, and he chases after Blue’s rocket!! After an intense chase, the two of them at last arrive in Penguin Village, home to Arale Norimaki!!', 25, '1987-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 56, 'Strange Visitor', 'Arale, the girl Goku meets in Penguin Village, is a mysterious young girl who can run at super speed, and even ride the Kinto''un. The village’s police force, consisting of Taro and the others, attempt to capture Blue of the Red Ribbon Army, but they can’t scratch him! The Dragon Radar is malfunctioning, and Goku cannot pinpoint the position of the Dragon Balls. At a loss, Goku takes Arale’s advice and visits Dr. Senbe, who just might be able to fix the Dragon Radar!!', 25, '1987-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 57, 'Arale vs. Blue', 'Dr. Senbe’s eldest son Turbo-kun fixes the Dragon Radar. Blue then appears, takes Arale as a hostage, and steals the Dragon Radar, using his physic powers to immobilize Goku!! At this time, Arale uses amazing power to send Blue flying!! However, even though the Dragon Balls are returned, the Dragon Radar was sent flying along with Blue. Goku receives a newly made Dragon Radar from Turbo, and leaves Penguin Village behind.', 25, '1987-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 58, 'The Land of Korin', 'A volcanic eruption sends the Four-Star Ball flying into the Karin Holy Land, a place protected by Bora and his son Upa. Bora uses his tremendous power to drive back Captain Yellow’s Red Ribbon Army troop, who came in pursuit of the Dragon Ball! However, Yellow takes Upa hostage and demands the Dragon Ball. But Goku happens to pass by, defeats Yellow in a single blow, and saves Upa!! Meanwhile at Red Ribbon Army Headquarters, the world’s greatest assassin Tao Pai-pai shows up, having been summoned by Commander Red!!', 25, '1987-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 59, 'The Notorious Mercenary', 'After finally managing to return to Red Ribbon Army Headquarters, Blue is killed by a single blow from Tao Pai-pai’s tongue. Tao Pai-pai then sets off for the Karin Holy Land to eliminate Goku! Meanwhile, Goku obtains his heart’s desire, the Four-Star Ball. He also hears the legend of the Super Holy Water, water received from a sage who lives at the top of Karin Tower, and that if drunk will multiply one’s power many times over. Tao Pai-pai then shows up. Bora stands to face him, but before Tao Pai-pai’s fearsome power he is killed in the blink of an eye!! Goku challenges Tao Pai-pai, but?!', 25, '1987-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 60, 'Tao Attacks!', 'Goku is completely helpless before the might of Tao Pai-pai, who is unaffected by even the Kamehameha. Goku is felled after taking a direct hit from Tao Pai-pai’s sure-to-kill Dodonpa! Tao Pai-pai steals the Dragon Balls, and heads to a town to get new clothes to replace his tattered ones. However, Goku survived!! The Four-Star Ball that he had on his breast protected him!! After resolving to use the Dragon Balls to restore Bora to life, Goku climbs Karin Tower in order to become stronger than Tao Pai-pai. However, no matter how far he climbs, he is still unable to see the top.', 25, '1987-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 61, 'Korin Tower', 'Goku struggles his way to the top of the tower, and there he meets the cat sage Karin, who has the appearance of a cat. In order to drink the Super Sacred Water that will multiple his power many times over, Goku must actually steal the jar that contains the Super Sacred Water from Karin-sama! Goku pursues Karin-sama with all his might, but is unable to even touch the jar!! Karin-sama says that the only one to have ever drunk the Super Sacred Water was Muten Roshi, 300 years ago. Yet Karin-sama says it took him three years to manage to drink the water!!', 25, '1987-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 62, 'Sacred Water', 'After going to retrieve the Four-Star Ball that Karin-sama dropped, Goku makes the round trip up Karin Tower in three hours, even though it took him an entire day when he first climbed up! Furthermore, Goku copies the sleeping Karin-sama‘s breathing and movement during the night, and is then able to read Karin-sama‘s movements and finally obtain the jar of Super Sacred Water. But it contains ordinary water?! It turns out that the act of obtaining the jar was itself training that increased his power many times over!! At that time, having obtained brand new clothes, Tao Pai-pai sets out for the holy land once again.', 25, '1987-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 63, 'The Return of Goku', 'Arriving in the holy land, Tao Pai-pai attacks Upa in order to learn the location of the Four-Star Ball. Tao Pai-pai loses patience with Upa, who won’t say anything, and tries to kill him, but that’s when Goku comes running in! Goku and Tao Pai-pai confront each other once again! This time, the powered up Goku has a firm advantage!! After realizing that Goku has obtained more power through the legendary Super Sacred Water, Tao Pai-pai climbs the tower in order to drink the water himself. However, Goku doesn’t try to follow him.', 25, '1987-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 64, 'The Last of Mercenary Tao', 'Having climbed Karin Tower, Tao Pai-pai tries to get the Super Sacred Water by threatening Karin-sama. However, Karin-sama successfully tricks Tao Pai-pai, and sends him back to the surface! After descending back to the holy land, Tao Pai-pai unleashes a violent attack, but Goku is unharmed!! Tao Pai-pai turns pale and uses a bomb, but Goku kicks it back and Tao Pai-pai ends up blowing himself away. After gathering the four Dragon Balls, Goku flies off to the Red Ribbon Army Headquarters to gather the remaining ones!!', 25, '1987-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 65, 'Confront the Red Ribbon Army', 'Using the Dragon Radar that was stolen from Goku, Captain Violet returns to Red Ribbon Army Headquarters with a second Dragon Ball. Commander Red is not aware of Tao Pai-pai’s defeat, and looks on in good humor as the signal from the four Dragon Balls Goku is carrying approach on the radar. Meanwhile, Goku’s friends at Kame House use Bulma’s reconnaissance mecha to learn that Goku’s target is the Red Ribbon Army’s stronghold! In order to rescue Goku, Bulma and the others hurry to the Red Ribbon Army Headquarters in Yamcha’s plane!', 25, '1987-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 66, 'A Real Bind', 'Goku’s friends pick up Kuririn, who was out shopping, and head on after Goku. They are all prepared to die. Meanwhile, the Red Ribbon Army realizes that the approaching signal isn’t Tao Pai-pai, and begins a general offensive against Goku! Knocking around missiles and fighter planes, Goku charges into the base, and in the blink of an eye defeats nearly half the soldiers! Commander Red is horrified at Goku’s power, which far surpasses his imagination!!', 25, '1987-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 67, 'The End of Commander Red', 'The Red Ribbon Army is on the brink of annihilation because of Goku. Captain Violet steals the money in the vault and flees! The cornered Commander Red attempts to kill Goku as well as Black. It turns out that Red’s objective was merely to use the Dragon Balls to make himself taller. Having survived, Black kills Red and confronts Goku in the Battle Jacket! Goku is KO’d by the Jacket’s formidable power, and cannot move! A sure-to-kill beam aims for Goku!!', 25, '1987-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 68, 'The Last Dragon Ball', 'After Goku dodges the beam, Black attempts to use a missile to blow Goku up together with the entire base, but Goku repels this missile! As Black realizes he has no chance to win and tries to run away, Goku settles things with a single blow, and the Battle Jacket explodes! Goku reunites with his friends, who were hiding in the forest preparing their strategy, and even they are amazed at his strength. Only one Dragon Ball remains. However, for some reason the Dragon Radar isn’t picking up its signal.', 25, '1987-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 69, 'Who is Fortuneteller Baba?', 'Goku has wiped out the Red Ribbon Army, but he can’t figure out the location of the seventh Dragon Ball! From there, he ends up requesting a divination from the fortune-teller Uranai Baba, who the Turtle Hermit told him about. On the way, Goku and the others stop by Karin Tower and take Upa with them to Uranai Baba’s palace! However, in order to receive a divination from Uranai Baba, one must either pay 10 million zeni, or win in a battle against her five competitors! Goku and the others reluctantly agree to fight, but…', 25, '1987-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 70, 'We are the Five Warriors', 'Dracula Man, the first opponent, challenges Kuririn! Kuririn is filled with confidence, but he gets bitten in the head by Dracula Man and has his blood sucked! Having lost a large amount of blood, Kuririn is ultimately defeated by Dracula Man. Goku and the others then work on a strategy, and Upa and Puar participate together. They blow Dracula Man away with the things a vampire hates, garlic and the crucifix! Moving on, they pass the baton to Yamcha, but the next opponent is Mr. Invisible, an invisible man of all things!!', 25, '1987-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 71, 'Deadly Battle', 'Yamcha has a tough battle with an undetectable invisible man as his opponent! Goku returns after having been instructed by Kuririn to bring the Turtle Hermit and Bulma. Kuririn pulls down Bulma’s clothes when the timing is right, and blood shoots from the Turtle Hermit’s nose once he sees Bulma’s chest! Bathed in this nosebleed, the invisible man’s form appears, and he is defeated by Yamcha. Kuririn’s strategy wins! Meanwhile, the battleground is moved to the “Demons'' Toilet”!', 25, '1987-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 72, 'Goku''s Turn', 'The “Demons'' Toilet” is lined with demon statues, and surrounded by a poisonous bog! The mysterious third contestant to appear is the mummy man, Mummy-kun! But in contrast to his appearance, Mummy-kun has ultra power and speed that surpasses Yamcha’s. Yamcha faces him with determination, but the difference in their power becomes clear. Still not understanding, Yamcha fights on until the end, but he is finally defeated! Then in place of Yamcha, who put up a good fight, Goku at last debuts!', 25, '1987-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 73, 'The Devilmite Beam', 'The fight between Mummy-kun and Goku begins. Mummy-kun attacks furiously, but it is completely ineffective against Goku! Angered, Mummy-kun uses his bandages to attack?! The bandages wrap around his entire body, but Goku doesn’t surrender! Thinking quickly, he uses the poisonous bog to break out of the bandages, then defeats Mummy-kun with a single punch! The fourth person to appear is the devil Akkuman! However, even Akkuman is helpless against Goku’s power?!', 25, '1987-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 74, 'The Mysterious Fifth Man', 'Akkuman has a rough battle against Goku’s overwhelming power, and fires the Devil Might Beam. It’s a frightful attack that infinitely multiplies the tiny evil hidden without a person’s heart, causing them to explode! Goku is bathed in the Devil Might Beam, but for some reason it doesn’t work on him! It turns out that Goku somehow doesn’t possess an evil heart!! Goku finally blows Akkuman away! And then the fifth man finally appears, but for some reason Goku feels nostalgic.', 25, '1987-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 75, 'The Strong Ones', 'The fox mask-wearing fifth man is no ordinary person! A breathless offensive-defensive battle unfolds!! And then the fox mask man fires a Kamehameha of all things! But Goku doesn’t lose, and returns fire with his own Kamehameha, knocking the man down! In the instant it seemed like Goku had won, the fox mask man grabs onto Goku’s weakness, his tail! Seeing this, the Turtle Hermit realizes the fox mask man’s identity. He says that the opponent’s identity is Son Goku’s dead adoptive grandfather, Son Gohan!!', 25, '1987-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 76, 'True Colors of the Masked Man', 'Grabbing onto Goku’s tail, the fox mask man knocks Goku around! But then Goku’s tail comes off!! As Goku is about to counterattack, having lost his weakness, the man quickly surrenders. His identity was Goku’s adoptive grandfather Son Gohan after all!! Goku rejoices in their reunion! Thanks to Uranai Baba, Gohan was able to return from the afterlife for a single day. After the brief reunion, Gohan returns to the afterlife once again!', 25, '1987-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 77, 'Pilaf''s Tactics', 'After having Uranai Baba divine the location of the seventh Dragon Ball, Goku immediately sets off on Kinto''un to find it. But it turns out that the ones in possession of the Dragon Ball are Pilaf and his lackeys, who had previously given Goku and the others a hard time. Goku ends up in a showdown over the Dragon Ball with Pilaf, who is plotting to rule the world! Pilaf confidently challenges Goku in his mecha, the Pilaf Machine. He puts up an unexpectedly good fight, but loses in the end! Goku finally obtains the last Dragon Ball!!', 25, '1987-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 78, 'The Eternal Dragon Rises', 'Having collected the seven Dragon Balls, Goku returns to Karin Tower with Upa. Then in response to Goku’s summons, Shen Long appears once again! While he’s afraid of the gigantic Shen Long, Upa still speaks his wish! Hearing the wish, Shen Long brings Upa’s father Bora back to life, who was killed by Tao Pai-pai!! Goku says his parting words to Upa and his father, then returns to his friends. Then at the Turtle Hermit’s advice, he sets out on a trip in search of even greater power!', 25, '1987-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 79, 'Terror and Plague', 'Having set off on his own journey of training, Goku visits Chao’s village, a boy he met along the way. The village where Chao lives is plagued by the outlaw brothers named Kinkaku and Ginkaku! Goku confronts Kinkaku and Ginkaku, but ends up sealed inside a mysterious gourd that sucks you in if you don’t reply when your name is called!! However, Goku is saved thanks to the Nyoi-Bo. He steals the gourd away from the two and punishes them!', 25, '1987-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 80, 'Goku vs. Sky Dragon', 'Continuing on his training journey, in the city Goku learns of a martial artist named Chin Taiken, and ends up taking the place of the ill martial artist in an important match! But Taiken’s son, Shoken, doesn’t like the idea of Goku participating, and feeds him laxative-spiked food. The match with Ten Long, master of Hyuga-Ryu, then begins! An intense battle unfolds, but Goku’s stomach starts to feel strange due to the laxative! However, he somehow endures this to win the match!!', 25, '1987-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 81, 'Goku Goes to Demon Land', 'In the middle of his journey, Goku happens to pass by the Village of Fiends! When night falls, fiends appear from the Demon Realm Gate located between this world and the Demon Realm, and run wild in the village! In order to rescue Princess Misa, who was kidnapped by the fiends, Goku sets out to enter the Demon Realm Gate!! After having a showdown with Shura, the martial arts master of the Demon Realm, Goku blinds the fiends’ eyes with a Kamehameha and rescues Princess Misa while they’re off guard! The Demon Realm Gate is then sealed once again by Goku!!', 25, '1987-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 82, 'The Rampage of InoShikaCho', 'Goku sees the two martial artists Tenshinhan and Chiaotzu defeat the monster Inoshikacho, whose rampages had plagued the villagers. However, in reality the pair were friends with Inoshikacho, and deceitfully took money from the villagers! Goku tries to alert the villagers of the truth but gets framed instead, and he and Inoshikacho are chased by the villagers!! However, in the end the villagers’ distrust clears, and the reformed Inoshikacho ends up living with them in peace.', 25, '1987-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 83, 'Which Way to Papaya Island?', 'Three years have passed since Goku set out on his training journey. One day, Goku rescues the fox boy Konkichi, who was being pursued by an evil group. In gratitude to Goku, Konkichi says he will obtain the traveling fare for going to the Tenkaichi Budokai grounds. However, Konkichi is arrested for being a bank robber! Konkichi protests that while he may be a thief, he’s no bank robber! For Konkichi’s sake, Goku does a splendid job of capturing the real criminals!!', 25, '1987-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 84, 'Rivals and Arrivals', 'The 22nd Tenkaichi Budokai at last opens! When Kuririn and Yamcha arrive at the tournament grounds, the Turtle Hermit’s rival the Crane Hermit and his disciples Chiaotzu and Tenshinhan appear before them! The Crane Hermit leaves after saying some dreadfully insulting things! Meanwhile, Goku is nowhere to be found, and the tournament registration deadline has almost come! As everyone worries, Goku appears in the nick of time!! The friends enjoy their three-year reunion!', 25, '1987-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 85, 'Preliminary Peril', 'The tournament preliminaries have begun! Kuririn and Yamcha naturally advance through their respective brackets. Tenshinhan and Chiaotzu show up there, and rile them up with their bold demeanor. Sparks fly between the Turtle Hermit and the Crane Hermit’s disciples before the matches have even begun. Tenshinhan easily wins during his first appearance in the preliminaries, displaying a mere fraction of his bottomless ability! And then Goku’s turn has finally come! His opponent is King Chapa, well known as a master!!', 25, '1987-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 86, 'Then There Were Eight', 'Goku’s match against King Chapa begins! It seems that even Goku was having a difficult fight, but he brushed King Chapa’s attacks aside like they were nothing and achieved a sweeping victory!! Afterwards, Goku and the others continue to do well at advancing in the preliminaries! And Jackie Chun, the champion of the previous tournament, naturally advances as well! Meanwhile, Tenshinhan cruelly defeats Namu, who had fought against Goku in the semi-finals during the previous tournament! Goku and co. plus Tenshinhan and Chiaotzu thus ended up all participating in the main tournament!', 25, '1987-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 87, 'Yamcha vs. Tien', 'A lottery takes place to decide the match opponents out of the eight contestants who have survived into the main tournament. Tenshinhan uses Chiaotzu’s psychic powers to fix the match combinations as he sees fit! Because of this, the first match becomes a match of Yamcha versus Tenshinhan!! Yamcha harbors an extraordinary animosity towards the provocative Tenshinhan! When the match then starts, it becomes a white-hot offensive and defensive battle, with neither side giving an inch!!', 25, '1987-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 88, 'Yamcha''s Big Break', 'Yamcha and Tenshinhan violently clash! Yamcha uses the Shin Roga fu-fu ken against Tenshinhan, but is gradually pushed back and is in a pinch. As his final hand, Yamcha fires a Kamehameha!! But Tenshinhan deflects the Kamehameha and defeats the faltering Yamcha in midair! Furthermore, he strikes the already unconscious Yamcha with a finishing blow! Goku burns with intense anger at the coldhearted Tenshinhan!!', 25, '1987-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 89, 'Full-Moon Vengeance', 'The Manwolf, who goes up against Jackie Chun in the second match, seems to harbor a grudge towards Jackie for some reason! The cause of this turns out to be because Jackie destroyed the moon with a Kamehameha in the previous tournament. Since then the Manwolf, who transforms into a human when he looks at the moon, has been unable to return to being a human. Jackie handles the Manwolf with ease and wins the match!! He then chooses Kuririn’s head to stand in for the moon, and restores the Manwolf to being human.', 25, '1987-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 90, 'The Dodon Wave', 'The third match becomes a showdown between Kuririn and Chiaotzu! Kuririn is bewildered by Chiaotzu’s strange techniques!! Flying freely through the air, Chiaotzu fires a “Dodonpa“, the same technique used by the assassin Tao Pai-pai! It turns out that Tao Pai-pai is actually the Crane Hermit’s younger brother!! After learning that Goku defeated Tao Pai-pai, the Crane Hermit orders Chiaotzu to kill Kuririn! Cornered, Kuririn resolves to using a Kamehameha!!', 25, '1987-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 91, 'Counting Controversy!!', 'The Kamehameha that Kuririn fired hits Chiaotzu head-on! Angered, Chiaotzu uses his psychic powers to prevent Kuririn from moving, and attacks him! But Kuririn realizes that Chiaotzu releases his psychic powers through his hands, and instantly throws out a math question! He then defeats Chiaotzu as Chiaotzu tries to use his hands to do the calculations!! That night, Goku is attacked by the Crane Hermit! However, Tenshinhan enters and stops him, vowing that he will defeat Goku in their match!!', 25, '1987-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 92, 'Goku Enters the Ring', 'Goku’s turn has come at last! His opponent is the popular action star, contestant Panputto! But Panputto’s manager is afraid of Goku’s strength, and right before the match he tricks Goku and takes him away! As Goku is on the verge of losing by default, through Lunch’s help he barely manages to make it to the match on time! The match then begins, and Goku wins in the blink of an eye! Goku has already acquired strength above the level of an ordinary human!!', 25, '1987-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 93, 'Tien Shinhan vs. Jackie Chun', 'The first match of the semi-finals ends up being a matchup of Jackie Chun versus Tenshinhan! Before the match, the two both burn with fierce fighting spirit!! The match then begins! Jackie uses a multi-fold Zanzouken, but Tenshinhan splendidly breaks through it!! Having made light of Jackie, Tenshinhan is overwhelmed by his strength! Meanwhile, seeing that Tenshinhan possess power greater than he imagined, Jackie begins to feel that a new age is coming!!', 25, '1987-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 94, 'Stepping Down', 'It’s the blazing white-hot match of Jackie versus Tenshinhan! Tenshinhan gets serious, and uses the Taiyou-ken! Flinching at the flash, Jackie is downed by a knee kick! After standing back up, Jackie tries to persuade Tenshinhan to walk on the true path. But Tenshinhan realizes that Jackie is the Turtle Hermit, and fires a Kamehameha of all things! Jackie deflects the Kamehameha, and jumps down from the arena, willingly receiving an out of bounds loss!', 25, '1987-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 95, 'Goku vs. Krillin', 'Having won through Jackie’s out of bounds loss, Tenshinhan is completely unable to understand what has happened! He then willingly meets with the Turtle Hermit and questions him on his reasons! The Turtle Hermit says that it is because the time has come for him to gradually turn the era over to the young heroes. He then again tries to persuade Tenshinhan to walk on the true path. Tenshinhan’s heart has begun to gradually turn. At the tournament grounds, Goku and Kuririn’s very first fight has begun! The two fight at full force, not holding back!!', 25, '1988-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 96, 'Tail''s Tale', 'A battle where neither side gives an inch unfolds in the semi-finals! Kuririn has grown far more since last time, but Goku has become even stronger than that!! As Kuririn begins to be gradually pushed back, he takes advantage of an opening and grabs Goku’s weakness, his tail! But this doesn’t affect Goku, who during his training strengthened even his tail!! Goku moves at such high speeds that he can’t be seen and attacks Kuririn, knocking him from the arena and winning the match!!', 25, '1988-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 97, 'Final Match: Goku vs. Tien', 'The morning of the finals at last arrives. There’s a big clamor at the tournament grounds as it overflows with people trying to watch the match! Seeing this, Goku burns with fighting spirit!! Meanwhile, Tenshinhan is moved by the Turtle Hermit’s words, and heads to the arena as if to stop his uncertainty. And then the final round begins at last! Once the match begins, the two immediately launch into a grand, intense battle!! But Tenshinhan has seen through Goku’s fighting style, and attacks as if pressuring Goku for a response. Goku is in a great pinch!!', 25, '1988-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 98, 'Victory''s Edge', 'Tenshinhan uses his secret technique, the Haikyu-ken, to smash Goku into the floor! But Goku gets up easily, and faces Tenshinhan not with the power he uses for matches, but rather the power he uses for battle! Their techniques smash furiously against each other! Goku’s Zanzouken is effective, and Tenshinhan is downed!! Tenshinhan uses his even more secret technique, the Taiyou-Ken, but Goku counters it with sunglasses and instead Tenshinhan is the one to be knocked down! The two continue their super-intense match, but Goku’s condition suddenly becomes strange!!', 25, '1988-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 99, 'Tien''s Insurrection', 'Goku has suddenly become unable to move his body! This is due to Chiaotzu’s psychic powers!! He sealed up Goku’s movement on the Crane Hermit’s orders. But Tenshinhan realizes the Crane Hermit’s trick, and puts a stop to it! The heart of a proper martial artist has sprouted in Tenshinhan!! The Crane Hermit is mad with rage, but he is knocked off into the distance by the Turtle Hermit’s Kamehameha. And then this time for sure, Goku and Tenshinhan’s earnest match begins!!', 25, '1988-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 100, 'The Spirit Cannon', 'To test Goku’s ability, Tenshinhan uses his still even more secret technique, the Shiyou-ken! Two arms appear from his back, and Tenshinhan attacks with all four arms!! But Goku continues his attack without even flinching! In order to decide the match, Tenshinhan resolves to use his ultimate secret technique, the Kikouhou (Energy Cannon)! It’s a frightful technique that has destructive power many levels greater than the Kamehameha! The arena is then completely blown away by the Kikouhou!!', 25, '1988-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 101, 'The Fallen', 'The Kikouhou has left both fighters weary and exhausted. With all of their energy gone and the stage destroyed by the Kikouhou, Tenshinhan and Goku plummet towards the Earth, with the first to touch down losing the match! A new Champion is crowned today!', 25, '1988-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 102, 'Enter King Piccolo', 'Kuririn is dead! As Goku sets out on a quest for revenge, his friends attempt to learn the identity of Kuririn''s killer. All clues lead to the Turtle Hermit''s past and an evil that could destroy the world!', 25, '1988-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 103, 'Tambourine Attacks!', 'Piccolo Daimao has begun his sinister plot to restore his power and take over the world. All he needs are the seven Dragon Balls and all of the Tenkaichi Budokai participants - dead.', 25, '1988-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 104, 'Mark of the Demon', 'The evil Piccolo Daimao has sent his henchman, Tambourine to kill all the warriors that could foil his plan. Goku, in an effort to avenge Kuririn''s death, is defeated by Tambourine and left stranded. He runs into a strange mountain man - but is he friend or foe?', 25, '1988-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 105, 'Here Comes Yajirobe', 'Lost in the wilderness, Goku fights for his honor after a mountain boy accuse him of stealing his fish. Meanwhile, the Turtle Hermit and company desperately search for a means of stopping Piccolo Daimao from obtaining the Dragon Balls and annihilating all martial artists!', 25, '1988-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 106, 'Terrible Tambourine', 'Tambourine continues his seek-and-slaughter campaign of martial artists as he sets his sight on victim eight: Yamcha! The Turtle Hermit takes Tenshinhan and Chiaotzu on a cross-country race for the Dragon Balls, as they try to stay ahead of the competition, Piccolo Daimao and his dastardly horde. Meanwhile Goku attempts to persuade mountain-boy Yajirobe to hand over his Dragon Ball to help save Kuririn!', 25, '1988-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 107, 'Tien''s Atonement', 'Tambourine closes in on Goku and Yajirobe as the two warriors engage in a cross-country chase - of each other. Meanwhile, to obtain a Dragon Ball Tenshinhan must first atone for the brutality of his past.', 25, '1988-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 108, 'Goku''s Revenge', 'The final showdown between Goku and Tambourine is here! As Goku fights to avenge Kuririn''s death, the Turtle Hermit, Tenshinhan, and Chiaotzu continue their race against Piccolo Daimao for the Dragon Balls. However, Piccolo Daimao is out to get those responsible for Cymbal''s demise, and the trail leads him to Goku!', 25, '1988-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 109, 'Goku vs. King Piccolo', 'Son Goku must stand alone as he faces the wrath of Piccolo Daimao. Without aid, and protecting the One-Star Dragon Ball, Goku defends his life as the dastardly alien seeks revenge for the deaths of Cymbal and Tambourine, two of his prized soldiers. The Turtle Hermit finds himself between a rock and a hard place as he quests for the Three-Star ball.', 25, '1988-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 110, 'Piccolo Closes In', 'Exhausted, bruised, and alone, Goku makes a final stand against the seemingly indestructible Piccolo Daimao. As the Turtle Hermit and others continue their pursuit of the Dragon Balls, it becomes clear that the trail leads to the dark forces of Piccolo Daimao and judgment day for our heroes.', 25, '1988-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 111, 'Roshi''s Gambit', 'Global destruction is one wish away if Piccolo Daimao succeeds in calling fourth the Eternal Dragon. The Turtle Hermit answers the call for a hero by placing himself between the creature and the remaining Dragon Balls. However, in his attempt to save the world, he may pay the ultimate price.', 25, '1988-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 112, 'King Piccolo''s Wish', 'Piccolo Daimao has called forth the Eternal Dragon. The Turtle Hermit is down, Tenshinhan can''t get up and Chiaotzu is scared stiff. With no one to oppose him, Piccolo Daimao prepares to make a wish, which if granted, could become the world''s greatest nightmare!', 25, '1988-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 113, 'Siege on Chow Castle', 'The invasion has begun! A youthful Piccolo Daimao sets out to vanquish the world, sector by sector, and he''s starting out with the peaceful inhabitants of the King''s realm! Meanwhile, Goku hopes to regain his strength by visiting Karin Tower, if he can climb it, exhausted and frail.', 25, '1988-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 114, 'Conquest and Power', 'Goku''s reunion with Karin is filled with hope and disappointment as the hero receives shocking news! Meanwhile Piccolo Daimao attempts to force the King''s obedience through a horrific display of brutality towards his kingdom and subjects as Tenshinhan prepares for the long journey to learn the secret of the Mafuba.', 25, '1988-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 115, 'Awaken Darkness', 'Something stirs in the cold, deep black below. Moans bellow from a hallow cavern beneath the ice. The Dark is alive! And it calls for Goku, as he sets out on a dangerous quest to find the Super Spirit Water. One sip could mean amazing power - or painful death!', 25, '1988-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 116, 'A Taste of Destiny', 'Goku and Yajirobe seek the Super Spirit Water, a mystical beverage that will grant either great power or death. But surprise follows surprise as Goku finally finds Darkness, the keeper of the Super Spirit Water. After Goku proves himself worthy, Darkness allows him to drink the perilous potion. But will he be empowered or perished?', 25, '1988-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 117, 'The Ultimate Sacrifice', 'Tenshinhan masters the Mafuba, deciding to use it against the evil Piccolo Daimao. One problem: if used against an opponent the Mafuba will kill its user! Meanwhile Goku and Yajirobe return to Karin Tower where Goku discovers his new powers and is given another Kinto''un. Can Goku reach Piccolo Daimao before Tenshinhan sacrifices himself?', 25, '1988-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 118, 'Prelude to Vengeance', 'Piccolo Daimao has declared annihilation of the world, one sector at a time. First up, Metro West, home of Bulma''s parents. Tenshinhan, having mastered the Mafuba, prepares to fight Piccolo Daimao, but a new menace threatens all. Goku race to offer aid, but will it be too late?', 25, '1988-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 119, 'Battle Cry', 'There''s a new beast in town and his name is Drum. Tenshinhan must go through him before he can fight Piccolo Daimao. The problem is, Drum moves faster than Tenshinhan''s eyes - all three of them! Goku is on his way, but will he arrive in time to save the day?', 25, '1988-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 120, 'Goku Strikes Back', 'Goku is back to face Piccolo Daimao, and not a moment too soon! As Tenshinhan and the rest of the resistance endure their most desperate hour, only Goku stands between Piccolo Daimao and the destruction of Metro West. It''s more than just a rematch, it''s the battle to save the world!', 25, '1988-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 121, 'The Biggest Crisis', 'Piccolo Daimao puts all of Metro West on edge when he invades the King''s Castle, but Goku is not about to let him take over without a fight. While Tenshinhan watches from the sidelines, the young warrior takes it on the chin and refuses to go down. It''s a fierce battle but even Goku has his limits. How much can he take?', 25, '1988-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 122, 'Final Showdown', 'The fierce battle between Goku and Piccolo Daimao continues, but Piccolo gains the advantage when he breaks Goku down limb by limb. To make matters worse, Tenshinhan is used as a pawn in the battle. Goku is forced to make an awful choice. Will he surrender to Piccolo Daimao and save his friend or choose to fight and risk his own life?', 25, '1988-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 123, 'Lost and Found', 'With Piccolo Daimao''s reign of terror at an end, Goku has time to mend his wounds. As he heals he learns that there may be a way to revive his lost friends - face to face meeting with the creator of the Dragon Balls! The one problem is that the only way to get to the mysterious God is by using his Nyoi-bo, and it has gone missing!', 25, '1988-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 124, 'Temple Above the Clouds', 'Goku finds his lost Nyoi-bo and uses it to climb to God''s temple in the sky. The only problem is that when he arrives he must face off against God''s assistant Mr. Popo in a test of strength. Does Goku have what it takes to pass this test and earn a meeting with the mysterious God?', 25, '1988-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 125, 'Earth''s Guardian Emerges', 'The moment has arrived for Goku to come face to face with the amazing God, Guardian of Earth! But even the wise Karin could not prepare Goku for what he will see when the mysterious Guardian emerges!', 25, '1988-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 126, 'Eternal Dragon Resurrected', 'After Goku mistakes God for the villainous Piccolo Daimao it is time for the young warrior to begin his grueling three year training for the next Tenkaichi Budokai. In exchange for Goku''s promise God agrees to revive the Eternal Dragon!', 25, '1988-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 127, 'Quicker than Lightning', 'Goku''s first task under his new teacher is a death-defying mission to the top of Mount Thunder to fetch the legendary Holy Crown. But the mystical artifact has a deadly secret! Goku will have to be quicker than lightning to accomplish this task - alive!', 25, '1988-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 128, 'Secret of the Woods', 'Continuing his training, Goku follows Mr. Popo''s instruction and enters the deep, dark woods. While searching for a worthy sparring partner, Goku stumbles across a surprising discovery hidden deep within the secluded labyrinth - and finds help a most unexpected way!', 25, '1988-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 129, 'The Time Room', 'Goku journeys through time, where he meets a young Muten Roshi! But Roshi has a problem of his own - his arch rival, Shen! While the two rivals battle for the affections of the same girl, Goku attempts a new power with the help of Mutaito.', 25, '1988-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 130, 'Goku''s Doll', '"Be careful what you wish for. You just might get it!" Goku learns this lesson the hard way when he asks Mr. Popo for the ultimate sparring partner to aid in his training. What he gets is the battle of his life! Meanwhile, Yamcha and the others continue their long journey to reach Karin Tower, in hopes of receiving training from the wise Master.', 25, '1988-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 131, 'Walking Their Own Ways', 'Preparing for the Tenkaichi Budokai, Goku gets some important training tips from Mr. Popo. Meanwhile, Tenshinhan, Yamcha, Chiaotzu and Kuririn make their way to Karin Tower for some training of their own. Unfortunately they are sidetracked by a village celebrating a mysterious festival to their mountain spirit. Once the mountain erupts it is up to our heroes to put a lid on the active volcano!', 25, '1988-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 132, 'Hotter than Lava', 'While Goku continues his training, Tenshinhan, Yamcha, Chiaotzu and Kuririn find themselves in a very hot situation! A remote village is threatened by an erupting volcano and it is up to the good guys to put a lid on it. The time has come to put their new training to the test!', 25, '1988-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 133, 'Changes', 'Warriors the world over are lining up to compete as the Tenkaichi Budokai prepares to get under way. Unfortunately, all of the Turtle Hermit''s pupils are missing, including Goku. With the entry-deadline approaching, the competitive future of our heroes look bleak, as does Muten Roshi''s patience.', 25, '1988-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 134, 'Preliminary Peril', 'The Tenkaichi Budokai gets underway as Goku and the others compete in the exciting preliminary round. But the competition threatens to turn ugly when Goku gets a visit from an old adversary.', 25, '1988-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 135, 'Battle of the Eight', 'The preliminary round continues as Goku, Yamcha, Kuririn, and Tenshinhan battle one opponent after another in hopes of advancing to the semi-final round. Meanwhile, the Turtle Hermit is confronted by an old rival.', 25, '1988-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 136, 'Tien Shinhan vs. Mercenary Tao', 'The Budokai gets underway as Tenshinhan battles his former mentor turned cyborg, Tao Pai Pai. Tensions run high as the former assassin attempts to take Tenshinhan down - permanently!', 25, '1988-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 137, 'Anonymous Proposal', 'Goku takes on his most lovely opponent yet in the second match of the Tenkaichi Budokai. Know only as Anonymous, the beautiful warrior''s identity is a mysterious as her fierce anger toward Goku, who must win the match in order to learn her real name.', 25, '1988-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 138, 'The Mysterious Hero', 'The Budokai continues with a double header! First up, Kuririn battles Ma Junior, Piccolo Daimao''s alter ego, and every bit as powerful. Yamcha jumps in the ring next, opposing Shen, whose meek appearance may hide a darker threat.', 25, '1988-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 139, 'Rematch', 'Yamcha scratches to stay in the ring as Shen reveals his true ability - and identity. Goku and Tenshinhan must fight one another in a friendly rematch to claim the last remaining spot for the semi-finals.', 25, '1988-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 140, 'Goku Gains Speed', 'As the battle between Tenshinhan and Goku rages, Goku unloads a heavy burden, one that may shift the balance in the extraordinary showdown. All eyes turn to Tenshinhan as an embarrassing moment spurs him to make a dangerous choice.', 25, '1989-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 141, 'The Four Faces of Tien', 'Goku has always been able to handle himself in the ring, but when his fight with Tenshinhan turns into a war against an army, he finds himself in serious jeopardy. Tenshinhan''s new technique may spell the end for our hero!', 25, '1989-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 142, 'Kami vs. Piccolo', 'Goku is eager to fight Ma Junior, but God fears his inexperience will be his downfall. Shen takes on Ma Junior in the last round of the semi-finals, where his shocking agenda is revealed.', 25, '1989-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 143, 'Battle for the Future', 'Goku faces the ultimate test as he confronts his greatest nemesis in the final round of the Budokai. This time his fight is for more than the title. The future of the free world is at stake!', 25, '1989-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 144, 'Super Kamehameha', 'The battle to save the planet continues as Goku tries to take down Ma Junior in the final match of the 23rd Tenkaichi Budokai. Goku has an ultimate weapon: The Ultimate Super Kamehameha Wave. However, if he uses it to destroy Ma Junior, God will be sacrificed, having been trapped inside Ma Junior''s stomach.', 25, '1989-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 145, 'Junior No More', 'Ma Junior reveals a startling secret that shocks the tournament. Goku finds himself facing a huge dilemma, as he fights for the championship becomes the fight for survival!', 25, '1989-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 146, 'Goku''s Trap', 'As the exhausting battle between Goku and Ma Junior continues, Goku avoids disaster by taking the battle within. Ma Junior surprises all when he unveils a new threat!', 25, '1989-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 147, 'Goku Hangs On', 'The Tenkaichi Budokai begins to fall to piece as Ma Junior unveils a technique that not only threatens to destroy Goku, but his friends as well. Even the mighty God believes that there is no way for Goku to survive in this winner-take-all massacre!', 25, '1989-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 148, 'The Victor', 'The end of the 23rd Tenkaichi Budokai finds Goku struggling for survival as Ma Junior gets the upper hand, poised to take the Title and his life. God devises a way to rescue the young hero, but his plan calls for the ultimate sacrifice!', 25, '1989-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 149, 'Dress in Flames', 'Eager to announce their wedding plans, Goku and Chichi return to her father''s kingdom. The good news is short-lived when the Gyumao''s castle goes up in flames! Goku embarks on a quest to find a sacred tool, which can save the Gyumao and his future with Chichi.', 25, '1989-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 150, 'The Fire-Eater', 'Goku and Chichi''s search for the Basho-sen leads them into the heart of a fiery volcano. Once inside, they must face a mighty creature that consumes flames: the Fire-Eater!', 25, '1989-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 151, 'Outrageous Octagon', 'Goku''s search for the Basho-sen leads him to a treacherous mountain that has a strange curse. Chichi is faced with the biggest mess of her life when she meets a mysterious old woman, while the Gyumao tries to flee the raging fires that threaten to destroy his castle!', 25, '1989-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 152, 'Mystery of the Dark World', 'After the Basho-sen fails to put out the fire threatening the Gyumao, Goku and Chichi set out to find the Eightfold Furnace, believed to be the last hope for extinguishing the deadly blaze. But before they can complete their quest, Goku must solve the mystery of the next world.', 25, '1989-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088509')) AND numero_temporada = 1), 153, 'The End, the Beginning', 'Goku and Chichi must travel to Mt. Gogyo in a last ditch effort to save her father, the Gyumao, from the deadly magical flames, which threaten to consume his kingdom. Before Goku can complete his quest, he must fan the flames of Fate and hope he does not get burned!', 25, '1989-04-19');
