INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0088794', 'Better Off Dead', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0390822'), 'PELICULA', 'After his girlfriend dumps him for a boorish ski jock, a depressed high-school student begins to ineptly attempt suicide, which brings him nothing but embarrassment. A French exchange student starts to change his outlook on life.', '1985-01-01', 'https://m.media-amazon.com/images/M/MV5BZGQzNmQ3MmItZjQyOS00NmEyLTgwMTQtOTM3ZTE5NGY5N2M5XkEyXkFqcGc@._V1_.jpg');
