INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 1, 'Pilot', 'When a science lab studying the ozone layer mysteriously explodes, MacGyver is called in to rescue the scientists that are trapped underground. It''s soon discovered that the explosion cracked a tank of sulfuric acid, and MacGyver is in a race against time before the Army uses a missile to seal up the base.', 49, '1985-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 2, 'The Golden Triangle', 'When MacGyver tries to retrieve a canister filled with a deadly chemical in Burma, he stumbles right into an area known as the Golden Triangle, where the military uses farmers as slaves on the opium fields. MacGyver is mistaken for a narcotics agent and is captured, but convinces the slaves to fight their oppression. MacGyver assists by setting several traps at the slave camp, and when the army returns to suppress the unrest, the real action begins.', 48, '1985-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 3, 'Thief of Budapest', 'MacGyver travels to Budapest to meet with a Russian double agent who is in possession of a watch containing information about other Russian spies. However, before MacGyver can take the watch, the agent is killed and the watch is stolen. Now MacGyver must work with the Gypsies to get it back.', 48, '1985-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 4, 'The Gauntlet', 'MacGyver attempts to get a reporter out of a Central American country with evidence linking a general to an illegal arms dealer. As they reach the border, it is clear escaping to Mexico will be no easy task, as the general and the arms dealer have every imaginable route severely guarded.', 49, '1985-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 5, 'The Heist', 'When $60 million worth of stolen diamonds destined for a relief charity end up in the hands of casino owner Jack Catlin, MacGyver must head to the Virgin Islands to try and get them back. With the help of Chris Rhodes, a senator''s daughter, MacGyver masterminds a plan to break into Catlin''s vault and steal them back.', 45, '1985-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 6, 'Trumbo''s World', 'MacGyver comes along on a expedition to Brazil with his friend, entomologist Dr. Alden. They meet with a landowner and recluse, Trumbo, who is initially hostile. However, when they realize that a mile-wide column of army ants is moving through the jungle, they team together to mount a defense.', 45, '1985-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 7, 'Last Stand', 'When MacGyver is on his way to a vacation, he takes the wrong way and ends up at a small airstrip where everybody seems to be behaving strangely. Too late, he discovers that the airstrip has been taken hostage, and he has been caught in the middle of a plane-hijacking attempt.', 48, '1985-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 8, 'Hellfire', 'During a trip to visit some friends, an accident starts a fire in an oil well owned by MacGyver''s friends. MacGyver and his buddy then go to fetch dynamite in an abandonned mine at great peril to themselves after they decide the dynamite is the only feasible way the fire can be put out. However, when they use it, the fire only becomes more intense. Can MacGyver and his Hellfire friend survive the incredible heat to put out the fire and save the oil buried underneath the well?', 45, '1985-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 9, 'The Prodigal', 'A man wants to testify against his mobster brother in Federal Court, and MacGyver has the job of keeping him safe, but the man''s mother is dying and he wants to visit her.', 45, '1985-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 10, 'Target MacGyver', 'After blowing away a nuclear facility under the control of an aggressive world leader, MacGyver returns home for some peace and quiet, only to find his boss waiting for him. He advises MacGyver that a contract is out on his life and he needs to skip town for awhile.', 45, '1985-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 11, 'Nightmares', 'When MacGyver comes home with some important documents, he''s drugged by enemy agents and told that he will die in six hours if he doesn''t retrieve the documents for them. But MacGyver, using an old prisoner trick, escapes. Now the only problem is convincing someone that he''s not just another drunk.', 45, '1986-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 12, 'Deathlock', 'MacGyver is trapped in a mansion with Pete, a code expert, and a government agent who may or may not be on their side. However, an old nemesis has electronically booby-trapped the entire mansion to make sure they can''t go anywhere.', 45, '1986-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 13, 'Flame''s End', 'An old girlfriend of MacGyver''s contacts him for help after she discovers evidence of uranium thefts from a nuclear processing plant where she works.', 45, '1986-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 14, 'Countdown', 'A mysterious person who calls himself "Viking" has just bombed the cruise ship Victoria, underway in the North Pacific Ocean. He demands six million dollars or another bomb will go off within hours. So MacGyver gets called in, along with his old Vietnam bomb-defusal partner, Charlie Robinson, to disarm it. But when they get there, they find out there''s more than one bomb on the ship. Complications arise when MacGyver''s partner sets off one of the bombs, and the bomber decides that DXS operated in bad faith and refuses to hand over the bomb-disarming instructions after he gets the extortion money.', 47, '1986-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 15, 'The Enemy Within', 'After a daring escape from East Germany where he gets rescued, and in the process saves a fellow operative with a quick mechanical fix, MacGyver thinks that he deserves some peaceful vacation time. But Pete lures him into baby-sitting a Russian defector who can identify KGB agents.', 45, '1986-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 16, 'Every Time She Smiles', 'MacGyver is on his way out of Bulgaria with a secret microfilm, when he meets Penny Parker, a beautiful, talkative American, who is on the run from her lover, a man named Stephan Frolov. She stashes some jewels on MacGyver, thus making him a suspect, and now MacGyver and Penny must flee Bulgaria together.', 45, '1986-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 17, 'To Be a Man', 'In Afghanistan, wounded and hunted by the Soviets, MacGyver is given refuge by an Afghan woman and her son. But they are themselves at the mercy of an Afghan thug, who will kill MacGyver if he finds him at his woman.', 45, '1986-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 18, 'Ugly Duckling', 'A 15-year-old genius accidentally hacks into a defective missile guidance system and attracts the attention of both the FBI and some black marketeers, who think that she may fix it for them. It''s up to MacGyver to save her from being kidnapped by either side.', 45, '1986-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 19, 'Slow Death', 'At the beginning of the episode, MacGyver literally has to jump onto a moving train that he missed earlier to return top-secret files and documents to the U.S. Government. Soon after, a local tribe stops the train. They take all passengers hostage until the men responsible for the death of the tribal leader''s son is found among the passengers.', 45, '1986-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 20, 'The Escape', 'When a mother superior at a religious mission in North Africa asks MacGyver to help a young woman with something, he is glad to help. However, when he finds out the young woman wants him to break her brother out of jail, he may have taken on more than he expected.', 45, '1986-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 21, 'A Prisoner of Conscience', 'Pete Thornton investigates the supposed death of an old friend, a prominent Russian dissident, and finds he must get his friend''s daughter Maria out of the country before the secret police arrest her for an alleged conspiracy. However, while in Russia, Pete bumps into MacGyver, who followed him from the United States. While disappointed MacGyver followed him, Pete gladly welcomes MacGyver into his plans when the secret police arrive to take Maria into custody. Following a high speed boat chase to escape the police, Pete and MacGyver find out from Maria that her father is not dead, he is being held in a maximum security ward at a state mental institution. To get into the mental hospital, MacGyver plays the part of a mad patient and Pete plays the part of a doctor who has been assigned to him. With the help of the other patients, MacGyver is able to escape into Ward Zero, where Pete''s friend is held. MacGyver breaks him out and hides him with the other patients.', 45, '1986-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 1), 22, 'The Assassin', 'Posing as a watchmaker who manufactures bomb timers, MacGyver manages to catch a master killer—Piedra—before he attempts an assassination on a high-profile target. However, Piedra isn''t about to be stopped for long.', 45, '1986-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 1, 'The Human Factor', 'MacGyver and Pete are testing a new security system at the Strategic Research Development Administration. MacGyver successfully bypasses the security and meets Dr. Jill Ludlam, the system''s designer. She tries to turn off the security system, but it doesn''t realize that it was just a test. MacGyver and Dr. Ludlam are then forced to find a way out, as the security system, named Sandy, tries to destroy the "intruders."', 45, '1986-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 2, 'The Eraser', 'Mac inadvertently leads a hit man to his target, believing that he''s helping a father find his lost son.', 45, '1986-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 3, 'Twice Stung', 'MacGyver and Pete have a surprise party planned for a colleague, but when the colleague doesn''t show up, MacGyver goes looking for him, and finds him on the verge of committing suicide. When questioned why he would do such a thing, Kelly explains that a con artist has swindled him out of his life savings. MacGyver tells Pete about Kelly''s situation and the two of them decide that they will get Kelly''s money back from the con.', 45, '1986-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 4, 'The Wish Child', 'While MacGyver goes to pick up a Chinese friend''s brother from a birthday party, he witnesses something strange: Paul is being called "The Wish Child." It seems that a greedy businessman has wrapped him up in a scam, because he looks exactly like a boy from an old legend that owns the secret of immortality. Now, MacGyver must try to talk him out of this, because Paul is starting to believe he really is The Wish Child!', 45, '1986-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 5, 'Final Approach', 'MacGyver goes to the mountains to lead four ex-gangster teens on a Phoenix Foundation funded rehabilitation trip. When he gets there, he finds that this task may be a little more complicated then he thought. All of the kids are very rebellious and one of them has a bad grudge against another one. A couple of days later when MacGyver is returning with the kids, their plane crashes in the middle of the wilderness and one of them is injured. Now, MacGyver must fix the plane and help the kids work out their differences so they can save their friend.', 45, '1986-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 6, 'Jack of Lies', 'MacGyver, returning home one night, walks into his apartment, only to everything he owns missing from his apartment. Initially suspecting a robbery, MacGyver eventually comes to the conclusion that his old friend Jack Dalton is the one responsible for the theft.', 45, '1986-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 7, 'The Road Not Taken', 'MacGyver and Pete head to Asia to rescue a nun, who is an old friend of Pete''s, and the orphaned children she takes care of from aggressive regime troops. While there, MacGyver runs into someone he never expected, his old fiancee, Debra. Now MacGyver must complete his mission, work out his differences with Debra, and escape from the troops, all before the troops find them.', 45, '1986-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 8, 'Eagles', 'While hang gliding in the west, MacGyver crosses paths with an escaped felon who shot and wounded a rare eagle. Now, with the help of his new friend Susan Cooper and her son Darin, MacGyver must heal the eagle and trap the felon before he kills more eagles.', 45, '1986-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 9, 'Silent World', 'While helping the Phoenix Foundation test a new missile-guidance system for the government, MacGyver''s efforts are hampered by men who are trying to steal it. When the men escape with it, MacGyver turns to his deaf friend, who has been having premonition-type dreams of this happening. Now MacGyver must try and analyze her dreams so that he can find the men who stole the system.', 45, '1986-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 10, 'Three for the Road', 'A retired actor and his wife stop at a motel on the way to Los Angeles. MacGyver rescues them from a drunkard who nearly makes a mark on their car.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 11, 'Phoenix Under Siege', 'While retrieving tickets for a hockey game at the Phoenix Foundation, MacGyver and his grandpa Harry get caught in the middle of a woman''s plot to blow up the building using a bomb that she herself made. They try to escape, but are locked in. Now they must figure another way out before she activates the bomb.', 45, '1987-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 12, 'Family Matter', 'Pete''s ex-wife and son are kidnapped down in Louisiana while on an archaeological trip. The kidnappers demand that Pete comes to Louisiana in exchange for letting his family go. But when he gets there, it soon becomes apparent that they don''t plan to let any of them go.', 45, '1987-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 13, 'Soft Touch', 'MacGyver puts up Penny Parker for a few days while she''s looking for a job as a singing telegram. But on her first day, she happens to witness two thugs torturing a man. Unfortunately, she can''t find her way back, and when she does, MacGyver thinks this may be the start of something bigger as the victim is a Federal agent.', 45, '1987-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 14, 'Birth Day', 'MacGyver''s fishing trip is cut short when he meets a very pregnant woman whose husband is out to kill her. Accidentally, she found out that his half-way home for ex-cons is really a recruiting place for new crimes. Mac and the woman are chased into a warehouse where they are trapped.', 45, '1987-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 15, 'Pirates', 'While on an expedition to find a Spanish treasure fleet, Dr. Barbara Ortega''s boat is hi-jacked by modern-day pirates. They steal the small amount of treasure that she has already found - including the ship''s log, which is the key to finding the whole fleet - and take off. When she makes it public that she was hi-jacked, the Phoenix Foundation sends MacGyver to help. Now, MacGyver and Barbara must recover the ship''s log, so she can find the treasure before the pirates do.', 45, '1987-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 16, 'Out in the Cold', 'When MacGyver and Pete go skiing, a man switches poles with MacGyver, only moments before being gunned down and killed by his former friends. But the gunshot starts an avalanche, which covers MacGyver completely, leaving it up to Pete to convince the mountain rangers to stage a search and rescue before the next avalanche comes. As MacGyver finally is dug up, the gangsters are there, waiting for him, and whatever is hidden in that ski pole.', 45, '1987-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 17, 'Dalton, Jack of Spies', 'Dalton, who is believed to be dead, recruits MacGyver to help uncover a CIA mole.', 45, '1987-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 18, 'Partners', 'MacGyver and Pete meet at a wrecking yard, both thinking that the other one arranged the meeting. Soon an unknown assailant captures them inside a big truck. Their only clue is an obituary for them and Jack Dalton.', 45, '1987-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 19, 'Bushmaster', 'When MacGyver is sent to rescue an American pilot held in Central America for supposed espionage, his wargame-trained daughter tags along, but she didn''t quite come prepared for the real thing. MacGyver must now rescue the pilot while keeping his daughter safe from the soldiers.', 45, '1987-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 20, 'Friends', 'MacGyver''s friends throw a birthday party for him, but he''s somberly reflecting on his past and future. While reflecting, MacGyver decides to leave the Phoenix Foundation to get married and have a family. Can Pete convince him of how important he is to the Foundation and get him to change his mind?', 45, '1987-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 21, 'D.O.A.: MacGyver', 'MacGyver is called to a meeting with a former British spy, who has learned of a group of terrorists that will use a new plastic explosive in a vengeful attack on the U.S. army. This explosive can be hidden anywhere. However, before the spy can give MacGyver all the details he is shot. MacGyver flees through a window and is picked up by a boat. The female who owns the boat soon learns that the man she has rescued doesn''t have any memory.', 45, '1987-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 2), 22, 'For Love or Money', 'MacGyver is forced to work with a ruthless freelance agent to rescue a human rights activist who is being held in a psychiatric hospital in Czechoslovakia. The rescue is an apparent success, until the secret police then kidnap the activist''s wife to get him back.', 45, '1987-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 1, 'Lost Love (1)', 'While helping the People''s Republic of China secure a priceless national treasure—The Ming Dragon—in a San Diego museum, MacGyver runs into a Lisa, a woman that he had loved and thought was long dead. MacGyver learns that Lisa has been alive all these years and needs his help escaping the KGB.', 45, '1987-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 2, 'Lost Love (2)', 'The KBG have Lisa in their grasp, and MacGyver must get The Ming Dragon for them to free Lisa. MacGyver enlists the help of his old buddy, Jack Dalton, to help him steal it.', 45, '1987-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 3, 'Back From the Dead', 'Jimmy Kendall, living undercover after testifying against his Mob bosses, surfaces when he becomes the manager for a winning baseball team.', 45, '1987-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 4, 'Ghost Ship', 'While mapping the wilderness for the Phoenix foundation, MacGyver stumbles on a deserted ship and finds a runaway girl who tells him that the rest of crew was driven away by Bigfoot.', 45, '1987-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 5, 'Fire and Ice', 'A jewel thief with diplomatic immunity kills Mac''s friend. But there are more people involved in the crime - and Mac can''t be sure who''s on his side.', 45, '1987-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 6, 'GX-1', 'Mac and Nikki race to recover equipment from a downed experimental plane before the Soviets, who are using a psychic to guide them to the wreckage.', 45, '1987-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 7, 'Jack in the Box', 'MacGyver and Jack Dalton are arrested in Arkansas by a corrupt sheriff who arrests people to make them work in a labor camp used for mining gold. MacGyver wants to escape, but Jack has other ideas: He wants to find five million dollars his uncle Charlie left in the mines years before.', 45, '1987-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 8, 'The Widowmaker', 'MacGyver is forced out of his grief over the tragic death of a friend by a madman with a score to settle from their past association.', 45, '1987-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 9, 'Hell Week', 'A desperate physics student goes off the deep end and boobytraps a college lab when he fails to win a science competition and to live up to his father''s high expectations.', 45, '1987-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 10, 'Blow Out', 'MacGyver teams up with colleague Nikki Carpenter to find out who is behind the attempts on her life. When they find out that the man who tried to kill her is connected to two terrorists who blew up a local post office, MacGyver and Nikki must find out what the terrorist''s next target is before it''s too late.', 45, '1987-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 11, 'Kill Zone', 'An impulsive scientist who cuts corners in her research work creates an uncontrollably mutating organism that speeds up the aging process.', 45, '1988-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 12, 'Early Retirement', 'While testing a new nuclear bomb defusing team at the Phoenix Foundation, a deadly explosion kills three men. Pete blames himself for not inspecting their equipment better and resigns from his job out of guilt. However, Pete is replaced by a not-so-trustworthy man—one who may have been connected to the explosion.', 45, '1988-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 13, 'Thin Ice', 'While back in Minnesota to fill in as coach for a high-school hockey team, MacGyver tries to change the attitude of a callous player who has a shot at playing for the pros. But when this kid''s ambition lands another player in the hospital, MacGyver must try and find out what or who is pushing him so hard to succeed.', 45, '1988-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 14, 'The Odd Triple', 'After returning home from a long assignment, MacGyver has an unwelcome surprise. Jack Dalton is waiting and wants him to help with a new scheme. A wealthy woman has just acquired some invaluable jewels, needing Jack to fly her back to her home in France. Things seem to be going fine, that is, until they land. Jack and MacGyver are arrested and accused of theft.', 45, '1988-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 15, 'The Negotiator', 'MacGyver becomes infatuated with a woman while conducting environmental-impact studies. However, what MacGyver does not know is that the woman was hired to "persuade" him to skip the studies—and if necessary, kill him.', 45, '1988-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 16, 'The Spoilers', 'After MacGyver witnesses someone dumping toxic waste that''s polluting mountain streams, he and Pete enlist a reclusive mountain man nicknamed "Earthquake" to help lead them to the culprit. Things become complicated, though, as Earthquake''s flashbacks to his military service in the Vietnam War make him unstable and threaten their case.', 45, '1988-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 17, 'Mask of the Wolf', 'Jack and Mac help an ancient Indian search for a wolf mask that two mercenaries are also eager to have.', 45, '1988-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 18, 'Rock the Cradle', 'Mac and Jack return from a flight to find an abandoned baby in Jack''s hangar, complete with a desperate note from the mother and his own endowment fund hidden in his diapers.', 45, '1988-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 19, 'The Endangered', 'While visiting an old girlfriend who''s a park ranger at a wildlife reserve, MacGyver runs into deadly poachers who are intent on hunting animals on the reserve. When MacGyver tries to uncover their plot, they come after him. Now it''s a race against time to escape the poachers, save the animals, and save their own lives.', 45, '1988-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 3), 20, 'Murderers'' Sky', 'When the head of a American-Chinese shipping company is attacked in his office by a killer, MacGyver and the man''s grandson—who is heir to the company—must find out who was behind the attempt on his life.', 45, '1988-05-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 1, 'The Secret of Parker House', 'MacGyver accompanies Penny Parker to an old house she inherited from her Aunt Betty, who mysteriously died 30 years before. When strange things start happening, Penny is sure that the house is haunted.', 45, '1988-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 2, 'Blood Brothers', 'MacGyver returns to his home town of Mission City, Minnesota to meet up with two old friends, Chuck and Neil, so they can dig up a time capsule they buried twenty-five years before. However, MacGyver is hesitant to dig the capsule up because he is still haunted by the death of his old friend Jesse, who died when MacGyver was young. But now MacGyver has another problem to deal with. Chuck''s and Neil''s sons, Danny and Sean, have gotten wrapped up in a drug deal, and the dealer is after Danny. Danny takes off to hide, and now MacGyver must find him, before the drug dealer does.', 45, '1988-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 3, 'The Outsiders', 'MacGyver helps an Amish family, who saved his life, from having their farm seized by the government.', 45, '1988-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 4, 'On a Wing and a Prayer', 'Central American rebels capture Pete and a nun during a coup d''état, and it''s up to MacGyver and Jack to rescue them.', 45, '1988-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 5, 'Collision Course', 'When a friend of Mac''s is injured in a crash, Mac agrees to test the new racing engine designed by the Phoenix Foundation. However a business rival has other plans for him, and he has someone from the inside to help him.', 45, '1988-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 6, 'The Survivors', 'While on assignment to test field agents for the Phoenix Foundation, MacGyver and Pete discover the wreckage of a DEA plane shot down by dangerous drug smugglers.', 45, '1989-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 7, 'Deadly Dreams', 'MacGyver gets involved in the search for an escaped serial killer. Soon he comes to the conclusion that the killer had help from another prisoner—an even more sinister man.', 45, '1989-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 8, 'Ma Dalton', 'After Jack receives momentos of his father from an anonymous sender, he and MacGyver launch a search for Jack''s mother, who''s been missing since he was boy—and they aren''t the only ones hunting for her.', 45, '1989-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 9, 'Cleo Rocks', 'Penny Parker''s big chance in a major professional role is threatened from two directions: a money shortage and several deaths linked to the musical she is set to perform in.', 45, '1989-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 10, 'Fraternity of Thieves', 'Pete is conflicted when he discovers that the Phoenix Foundation employee selling classified information turns out to be his son.', 45, '1989-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 11, 'The Battle of Tommy Giordano', 'The young son of MacGyver''s co-worker is kidnapped by the boy''s father. MacGyver must go and retrieve the boy from the house of the boy''s uncle—a powerful mob boss.', 45, '1989-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 12, 'The Challenge', 'An inner city youth club is threatened when a black resident is framed for auto theft by a neighborhood racist who''ll stop at nothing to close the center—even murder.', 45, '1989-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 13, 'Runners', 'MacGyver helps a young runaway with a vicious pimp and a tragic secret about her policeman father.', 45, '1989-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 14, 'Gold Rush', 'MacGyver joins a joint U.S.-U.S.S.R. team trekking into the Alaskan wilderness to retrieve a huge amount of Russian gold from a downed plane only to learn that someone has beaten them to it.', 45, '1989-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 15, 'The Invisible Killer', 'MacGyver heads up a trip with four other Phoenix Foundation employees into the wilderness as part of a stress reduction program. After discovering that a prison bus accident has freed several prisoners, the employees begin to question each other''s behavior. MacGyver must now figure out which man, if any, is not to be trusted before it''s too late.', 45, '1989-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 16, 'Brainwashed', 'Jack Dalton is brainwashed by an African politician and his wife to assassinate the leader of an African nation, who is in town for an awards ceremony.', 45, '1989-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 17, 'Easy Target', 'MacGyver and Pete are captured by terrorists intent on wiping out a nearby city with an electromagnetic pulse, unless their leader is freed.', 45, '1989-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 18, 'Renegade', 'MacGyver works hard to retrieve the anthrax bacillus stolen by a former Navy commando who once saved his life, and is now suffering the effects of an old head wound.', 45, '1989-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 4), 19, 'Unfinished Business', 'Jack, MacGyver, and Pete review their past adventures while on a gold-panning expedition, unaware they''re being stalked by a vengeful killer.', 45, '1989-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')), 5, 'Season 5', NULL);
