INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 4, 'The Prometheus Syndrome', 'MacGyver becomes personally involved in the effort to find a psychopathic arsonist.', 45, '1991-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 5, 'The Coltons', 'Mac''s old friends, the bounty-hunting Colton brothers try to find a young woman who''s the only witness to a Chinatown murder, aided by their wise and patient mother, their impatient younger brother and their dog, Frog.', 45, '1991-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 6, 'Walking Dead', 'Mac helps his neighbor, Mama Lorraine, rescue a young student activist who has been kidnapped and turned into a zombie by Haitian terrorists hiding behind a powerful voodoo priest.', 45, '1991-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 7, 'Good Knight MacGyver (1)', 'A genealogy investigation and a knock on the head takes Mac back to King Arthur''s court, where he must use his knowledge to prove Merlin innocent of harming the King, find the fair Cecilia and foil Morgana''s attempt to take over the throne.', 45, '1991-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 8, 'Good Knight MacGyver (2)', 'A genealogy investigation and a knock on the head takes Mac back to King Arthur''s court, where he must use his knowledge to prove Merlin innocent of harming the King, find the fair Cecilia and foil Morgana''s attempt to take over the throne.', 45, '1991-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 9, 'Deadly Silents', 'Mac tries to help an old silent film star retrieve the only existing prints of his work from a pair of special-effects obsessed fans.', 45, '1991-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 10, 'Split Decision', 'Mac''s friend Earl Dent looks to him for help when he fights to retain custody of his teenage daughter while preparing for a boxing comeback that bookmakers want him to throw.', 45, '1991-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 11, 'Gunz ''n Boyz', 'Mac and the Challenger Club try to help a boy prepared to take the rap for another boy murdered by weapons dealers exploiting the fear and suspicion in the neighborhood.', 45, '1991-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 12, 'Off the Wall', 'Mac battles a callous slumlord when a young graffiti artist asks for help when his grandmother faces eviction from the apartment where she''s spent her life.', 45, '1991-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 13, 'The Stringer', 'While working with Chinese dissidents to expose illegal labor camps, MacGyver gets unexpected help from a young photojournalist who claims to be his son!', 45, '1992-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0088559')) AND numero_temporada = 7), 14, 'The Mountain of Youth', 'MacGyver joins Jack Dalton in Kabulstan on a search for a fountain of youth, but finds himself battling nuclear terrorists in the process.', 45, '1992-05-21');
