INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 1, 'Our Very First Show', 'Widowed father Danny Tanner asks his friend Joey and his brother-in-law Jesse for their help in raising his three willful daughters.', 24, '1987-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 2, 'Our Very First Night', 'Jesse is left to baby-sit Michelle and turns the chore into a rock gig replete with midnight sundaes and hair dyeing.', 25, '1987-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 3, 'The First Day of School', 'Stephanie''s first-day-of-school jitters have Danny, Joey and Jesse playing superdad.', 25, '1987-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 4, 'The Return of Grandma', 'Danny, Jesse and Joey''s moms all threaten to move in if the guys don''t brush up on their housekeeping.', 25, '1987-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 5, 'Sea Cruise', 'Danny''s all-male fishing trip turns into a loveboat cruise replete with a female captain and an all-girl band.', 25, '1987-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 6, 'Daddy''s Home', 'Danny flies off to work minutes before Stephanie''s ballet debut as a dying swan, and Joey decides to trade wings with Jesse.', 25, '1987-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 7, 'Knock Yourself Out', 'Danny''s tryout as a cable boxing announcer isn''t a knockout; the guys try to save the baby from being knocked out by a cold.', 25, '1987-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 8, 'Jesse''s Girl', 'Jesse and Joey entertain everyone with stories of romantic dreams--one of which comes true.', 24, '1987-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 9, 'The Miracle of Thanksgiving', 'Everyone teams up to prepare the Thanksgiving feast--and the results aren''t worth gobbling.', 25, '1987-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 10, 'Joey''s Place', 'As Joey starts getting ready for a comedy tour, the family starts acting like he''s already gone.', 25, '1987-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 11, 'The Big Three-O', 'Danny crashes his surprise 30th-birthday party only to discover that Jesse dunked his favorite car.', 25, '1987-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 12, 'Our Very First Promo', 'Danny and his family are chosen to make a promo to boost ratings at the TV station.', 24, '1987-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 13, 'Sisterly Love', 'Sibling rivalry takes to the screen when Stephanie gets the part in the TV commercial for which DJ was auditioning.', 25, '1988-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 14, 'Half a Love Story', 'Jesse uses Michelle to get a date with one of Danny''s co-workers.', 25, '1988-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 15, 'A Pox in Our House', 'When chicken pox spreads through the household, Danny may have to scratch his chance to play basketball with the Harlem Globetrotters.', 25, '1988-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 16, 'But Seriously, Folks', 'Joey''s comic debut is jinxed when a guest in the audience takes his spot.', 25, '1988-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 17, 'Danny''s Very First Date', 'Danny''s kids are less than pleased to find out he might date the hive mother of Stephanie''s honeybee troop.', 25, '1988-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 18, 'Just One of the Guys', 'DJ wishes she were one of the guys when her cousin comes for a visit and spends most of his time with Danny.', 24, '1988-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 19, 'The Seven-Month Itch (1)', 'Jesse''s lack of privacy drives him out of the house for a break from the family, and he winds up missing the baby''s birthday.', 25, '1988-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 20, 'The Seven-Month Itch (2)', 'Jesse''s guilt increases when he misinterprets a phone call from Stephanie to mean the baby''s ill.', 25, '1988-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 21, 'Mad Money', 'Jesse gyrates as an Elvis impersonator, Joey discovers an old savings bond and starts spending money right and left.', 24, '1988-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 1), 22, 'D.J. Tanner''s Day Off', 'When DJ ditches school to get a rock singer''s autograph, she doesn''t count on Joey showing up where all the action is.', 25, '1988-05-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 1, 'Cutting It Close', 'Teaser: Danny, Joey, Jesse, D.J., Stephanie, and Michelle play Ring around the Rosie, but Michelle doesn''t understand it.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 2, 'Tanner vs. Gibbler', 'It''s Kimmy''s 12th birthday, and D.J. has planned a surprise birthday party for Kimmy. When Stephanie slips up and mentions the party to Kimmy, Kimmy decides to bring her new friends Nina and Melissa, two older girls, to the party with her. Upon arriving, all Nina and Melissa want to do is invite a bunch of friends over to trash the house, so when D.J. kicks Nina and Melissa out of the house for even thinking about trashing the house, Kimmy abandons the party and goes to the mall with Nina and Melissa, and this starts a feud between D.J. and Kimmy. With help from Jesse and Joey, D.J. and Kimmy end their feud, as Kimmy realizes that D.J. doesn''t want her to forget who her real friends are. Meanwhile, Danny is removed from his job as a sportscaster at the TV station, because the station has created a new morning show titled ""Wake Up, San Francisco"", and they need two people to host the new show. Danny is named a', 24, '1988-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 3, 'It''s Not My Job', 'Teaser: Preparing for a Halloween party, the guys are dressed as the Three Stooges -- Jesse as Moe, Joey as Curly, and Danny as Larry.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 4, 'D.J.''s Very First Horse', 'Teaser: Michelle wakes Joey up just to tell him he''s asleep. Main Synopsis: "Wake Up, San Francisco" is broadcasting an episode from a horse stable, where D.J. sees a horse named Rocket. D.J. desperately wants Rocket, and the only way she''ll get him is if she has enough money to make the payments needed to keep Rocket in the stable, so D.J. and Kimmy pool their money together and start making Rocket''s stable payments, without Danny knowing it. D.J. thinks Danny won''t let her have the horse unless she proves to him that she can handle the responsibility, so her plan is to secretly keep up the payments for a couple of weeks then tell Danny about Rocket, because D.J. figures that 2 weeks is enough to prove to Danny that she can handle the responsibility so Danny won''t say no. When Kimmy messes up and blows her half of the money, D.J. can''t make the next stable payment, so in a desperate effort to make sure she doesn''t lose Rocket, D.J. takes Rocket to the house with her. Danny is shocked', 24, '1988-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 5, 'Jingle Hell', 'Teaser: D.J. shows Michelle how to blow bubbles with gum. Main Synopsis: When Joey gives Jesse the inspiration Jesse needs to write an advertising jingle that Jesse has been having problems with, the result is that the jingle is bought. This bit of success leads to Jesse making an offer to Joey -- he now wants Joey to be his writing partner. Joey accepts the offer. When Joey gives the next jingle ""the Joey treatment"", and it''s not bought, a feud erupts between Jesse and Joey, but they work things out and decide to remain partners. Meanwhile, D.J. and Stephanie are feuding because Stephanie is always messing up things that belong to D.J., and D.J. is out to teach Stephanie a lesson about it, starting by tying all of Stephanie''s shoes together by the laces while Stephanie''s not wearing them.', 24, '1988-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 6, 'Beach Boy Bingo', 'Teaser: Stephanie reads a fairy tale to Michelle. Main Synopsis: In a radio contest, D.J. wins a ""dream night for 2"" with the Beach Boys. Problem is, according to the rules of the contest, D.J. is allowed to take only one of the guys with her, and she can''t decide who to go with. When the Beach Boys show up to pick D.J. up, they make things easier by allowing D.J. to bring Stephanie, Michelle, and all three of the guys with her.  Tag: More from the family''s dream night with the Beach Boys.', 24, '1988-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 7, 'Joey Gets Tough', 'Teaser: Jesse is weight training with Michelle "Superbaby" Tanner.  Main Synopsis: While Danny and Jesse are out, Joey is left in charge of the girls. D.J. and Stephanie want to stay up late so they can watch a Tiffany concert on TV. When Danny comes home and sees that they are up late watching the concert, Danny tells Joey that whenever Joey is at home alone with the girls, he needs to make them follow the rules of the house, so on the next day, D.J. arrives home from school an hour late without telling Joey that she was with friends, practicing for an hour for an upcoming karate tournament, and Joey grounds D.J. -- for the weekend when the tournament is scheduled to take place. D.J. becomes furious, angrily reminds Joey that he''s not her father, and then storms off to the bedroom that she and Stephanie occupy. Later, Joey goes upstairs to the bedroom, where he explains that after school, during the hour when he didn''t know where D.J. was, he was scared to death. D.J. agrees that she', 24, '1988-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 8, 'Triple Date', 'Teaser: Stephanie, Michelle, Danny, and the "Bicycle bus".  Main Synopsis: Danny has a new girlfriend named Denise, and he invites Denise and her two friends Zoey and Cheryl over to the house so Zoey and Cheryl can meet Jesse and Joey while D.J. is upstairs keeping an eye on Stephanie and Michelle. It turns out that Denise is a woman that Jesse once dated, and this has Danny wondering if there could possibly be a woman in San Francisco that Jesse hasn''t dated. Zoey doesn''t like Joey''s jokes, but Joey and Cheryl get along with each other just fine. Danny is depressed because Denise is still hung up on Jesse and she can''t get her mind off of Jesse because she thinks she and Jesse have an opportunity to get back together, until a talk with Jesse finally has Denise coming to her senses. Meanwhile, Stephanie causes D.J. to accidentally drop Danny''s wedding ring down the drain in the upstairs bathroom sink. With a little work, Denise and the guys help D.J. and Stephanie get the ring back.', 24, '1988-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 9, 'Our Very First Christmas Show', 'The family is on a flight to Colorado to spend Christmas with some relatives, and this is a trip that Danny has spent months planning -- but on the way to Colorado, a blizzard forces an emergency landing at an unfamiliar airport. The family is forced to spend Christmas in the baggage claim room, where everyone thinks Christmas is ruined this time around. Among the things that happen here are: Jesse''s father Nick tries to get Jesse to kiss Becky under a mistletoe, D.J. is upset that the gifts that the family brought along on the flight with them are missing, and Michelle is afraid of Lionel, a man who made her cry on the airplane. Jesse, becoming ever so frustrated by everyone''s sour attitudes, speaks to the people in the baggage claim room about the real meaning of Christmas, then Santa Claus shows up and shows the family where the missing gifts are, and it turns out that Lionel is Santa Claus.', 24, '1988-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 10, 'Middle Age Crazy', 'Stephanie knows it''s not easy being the middle child. The way things are going, Stephanie thinks that D.J. and Michelle are getting all of the attention. Jesse and Joey are working on a jingle until they start helping D.J. with a science project, ignoring Stephanie''s request for them to watch her break a hula-hoop record. Danny is trying to videotape Michelle for "Wake Up, San Francisco", ignoring Stephanie''s request for him to watch her break the hula-hoop record that she wanted Jesse and Joey to watch her break. Stephanie has had enough, and she believes that the only way she''ll get out of this situation is if she is not living at home anymore, so she decides that she wants to marry her friend Harry, then the guys come to their senses and realize how they''ve made Stephanie feel.', 24, '1989-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 11, 'A Little Romance', 'D.J. has her first boyfriend, Michael Montfort, but D.J. is crushed when Michael leaves her for Kathy Santoni, because Michael believes Kathy is prettier than D.J. is. Meanwhile, Becky and Danny are hosting a charity event where eligible bachelors are auctioned off to women who want a date with them. Three of the participating bachelors are Danny, Jesse, and Joey. Jesse ends up receiving the highest bid of them all -- from a very jealous Becky.', 24, '1989-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 12, 'Fogged In', 'Jesse and Joey have been up all night working on their latest jingle, which is for "Casa De Pancakes". When D.J. and Kimmy unknowingly erase the jingle from the tape it was recorded on by recording their version of "The Locomotion" on what they thought was a blank tape, Jesse loses his temper and yells at D.J. and Kimmy.', 24, '1989-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 13, 'Working Mothers', 'Jesse and Joey''s latest jingle is such a success that they are offered a fixed job composing jingles for Mr. Malatesta. D.J. and Stephanie fear that if Jesse and Joey take this job, knowing that Danny works at the TV station every day, then no one will be home to take care of them, especially during the three month summer break from school. D.J. and Stephanie''s fears go away when Jesse and Joey decide to take the job, but do their work from the house, with their office being in the attic.', 24, '1989-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 14, 'Little Shop of Sweaters', 'It''s Valentine''s Day, and Danny has bought D.J. the royal blue sweater that D.J. wanted. D.J. puts on the sweater with a shirt under it, and goes to school. At recess, D.J. takes off the sweater so she won''t sweat all over it, and after she puts the sweater on the ground, the school''s gardener runs over it with a lawn mower, and the sweater is shredded. D.J. doesn''t want Danny to know about this, so she, Kimmy, and Stephanie go to the mall to buy a replacement sweater, which is priced at $80, which was the cost of the shredded sweater. Stephanie sees a sign on the checkout counter that says ""buy now, pay later"". Not realizing that a credit card is required to do what the sign says, Stephanie grabs the sweater in an effort to help D.J., and this gets Stephanie accused of shoplifting.', 24, '1989-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 15, 'Pal Joey', 'A little over a year and a half ago, when Jesse and Joey moved into the house, Jesse and Joey didn''t exactly get along with each other very well at the beginning, but since then, they have become good friends, and it''s making Danny feel left out because lately, Joey has been taking Danny for granted. When Danny confronts Joey, they remember the day they became friends back in the 5th grade on February 23, 1968, when they protected each other from a bully named Sheldon. When Danny and Joey head to the school where this happened 21 years ago, they literally unearth the pledge they signed, which was a pledge to always be friends. Joey apologizes for taking their friendship for granted, and then he and Danny call Jesse to the school so Jesse can add his name to the pledge. Meanwhile, Stephanie''s friend Harry has a crush on D.J., leading Stephanie to accuse D.J. of stealing her friend.', 24, '1989-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 16, 'Baby Love', 'Becky''s sister Connie Anderson has arrived for a visit, and she has brought her son Howie, who is Michelle''s age, with her. Michelle and Howie become best friends, but when it comes time for Connie and Howie to go back home to Valentine, Nebraska, it gives Michelle what seems like an incurable case of heartbreak. The guys try to cheer Michelle up, but to no avail. On the next day, Jesse takes Michelle to his bedroom, and he plays a song for Michelle, and manages to coax a smile out of her, but she still misses Howie, but Becky takes care of that by videotaping Howie talking into the camera at the airport, and when Michelle watches the tape, the tape makes it look Like Howie is talking to Michelle. Howie misses Michelle just as much as Michelle misses Howie. After watching the tape, Michelle feels a lot better, and Jesse comments that Becky would be a great mother. Meanwhile, Step', 24, '1989-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 17, 'El Problema Grande de D.J.', 'D.J. has good grades throughout her report card, except for in Spanish class, where she was given a D. D.J. asks Danny to talk to Spanish teacher Linda Mosley about the grade. When Linda comes over to the house to talk to Danny about it, the conversation ends in a kiss -- right in front of D.J. and some of her friends. This makes D.J. a target for teasing, and she''s angry with Danny for making her a target for teasing. D.J. is also angry that Danny didn''t get her Spanish grade changed. Danny gets D.J. to admit that the more difficult the Spanish class became, the more she gave up on it. Meanwhile, Mr. Malatesta gives Michelle a spot in a marshmallow commercial that Joey and Jesse have been assigned to work on.', 24, '1989-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 18, 'Goodbye, Mr. Bear', 'It''s time for the annual spring-cleaning, and this has become one of Danny''s favorite times of the year. During the Spring cleaning, Jesse learns what "little cause, big effect" means when he accidentally breaks a drawer handle in the kitchen, and ends up having to renovate the kitchen''s entire network of cabinets and drawers because the broken handle''s design has been discontinued, and a new design Jesse buys doesn''t go very well with the cabinet design that is in the kitchen, so Jesse buys cabinets that go with the new handles. Meanwhile, Stephanie is frantic. It seems that Mr. Bear, the stuffed toy that the girls'' mother Pam Tanner gave Stephanie on the day Pam brought newborn Michelle home from the hospital, is missing. Stephanie doesn''t want to lose Mr. Bear, because it was a gift from Pam, and it reminds Stephanie of her.', 24, '1989-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 19, 'Blast from the Past', 'In college, Joey had a girlfriend named Patty Fogerty, who ended up leaving Joey for a guy named Michael Winchester. This left Joey devastated, because he wanted to marry Patty and spend the rest of his life with her. Now, Years later, Patty tracks down Joey''s bedroom phone number and calls him. Joey invites Patty over to the house, and Danny doesn''t like this one bit, because he doesn''t want to see Joey once again get hurt by Patty, who explains that she left Joey for Michael Winchester because she wanted more romance in her life and while she thought Joey was funny, she didn''t think Joey was romantic enough. Meanwhile, Kimmy uses Stephanie and D.J. as guinea pigs for a magic trick involving a pair of magician''s handcuffs that belong to Kimmy''s brother, who is in Las Vegas. Kimmy does the trick too well -- D.J. and Stephanie are now cuffed to each other, and Kimmy realizes she doesn''', 24, '1989-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 20, 'I''m There for You, Babe', 'It''s Jesse''s 26th birthday, and it seems that everyone''s trying to pull him in every direction at the same time. He''s scheduled to coach D.J. and Kimmy''s soccer team in a game at 3:30pm, he and Joey are doing a jingle for a credit dentist commercial, Danny schedules Jesse to perform at the Smash Club in front of music critic Sam Battersby, Stephanie needs Jesse to bake 100 of his special cookies for a school bake sale, and Michelle needs Jesse to fix her jack-in-the-box toy. Jesse coaches the soccer team to a win, then Becky shows up at the house and asks Jesse to go with her to the wedding of her aunt''s former son-in-law tomorrow, then Danny asks Jesse to fix his car. Jesse thinks he can handle it all, until he and the family go to the Smash Club and Jesse discovers that the Rippers didn''t show up because he and the Rippers ended up booked for two gigs on the same night -- the one at the Smash Club and one at the Holiday Inn i', 24, '1989-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 21, 'Luck Be a Lady (1)', 'The family travels to Lake Tahoe, where the girls get lucky gambling and Jesse forces Rebecca''s hand in their game of hearts.', 24, '1989-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 2), 22, 'Luck Be a Lady (2)', 'Jesse and Rebecca propose to say "I do" to each other, unless Danny gets them to eschew the whole idea.', 24, '1989-05-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 1, 'Tanner''s Island', 'Danny takes the Tanners to Hawaii in honor of their two year anniversary since becoming a family. While there, Danny becomes his usual controlling self and takes the family around together, including on a visit to a deserted island where he forgets to tie the boat and it sails away. The family thinks they''re doomed until they find out they are in fact on Pua Island where they meant they go for a show. Also Joey keeps seeing a hula girl he likes, and Jesse & Becky have an argument about Elvis.', 23, '1989-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 2, 'Back to School Blues', 'The new school year is starting, and Stephanie, who is entering 2nd grade, is the only Tanner left in her school, and she expects a bad day at school, but instead, it turns out to be a good day for Stephanie. The same can''t be said for 12-year-old D.J., who is entering 7th grade, a step closer to becoming a teenager. On her first day in junior high, D.J. is humiliated by Colleen and Susan, a couple of bullies. On the next morning, D.J. decides to put on make-up, because she believes the only way to fit in among the 7th graders is to do what Kimmy and virtually all of the other 7th grade girls are doing -- look twice as old as she really is by putting on makeup. Danny thinks D.J. is overdoing it, so he lets Becky help D.J. with the makeup. Meanwhile, Joey tries to teach Jesse how to play golf so they can impress a client who likes to play golf.', 23, '1989-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 3, 'Breaking Up Is Hard to Do (in 22 Minutes)', 'Sometimes, Jesse thinks it''s not fun to do what Becky wants to do, and Becky sometimes thinks it''s not fun to do what Jesse wants to do. This leads to an argument between Jesse and Becky, and then leads to a break-up between the two. Jesse starts dating a woman named Diane, and Jesse constantly talks about Becky on his date with Diane, because he regrets the break-up. Jesse brings Diane home with him, and Diane looks at Becky and says, ""If you''re not Becky, you''re going to hear a lot about her"". Touched by this, Becky realizes that she also regrets the break-up, so she and Jesse work things out and decide to stay together. Meanwhile, Stephanie loses a tooth, and "Tooth Fairy" Danny mistakenly leaves Stephanie a 20-dollar bill under her pillow when in the darkness of night time, he thought he had pulled a 1-dollar bill out of his wallet. Danny and the guys also try to teach Michelle that she shouldn''t be selfish during playtime.', 23, '1989-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 4, 'Nerd for a Day', 'Jesse tells Stephanie that she must apologize for going along with her classmates in teasing Walter, a kid who wears eyeglasses, but the apology makes Walter think Stephanie loves him, and when Stephanie''s friends come over to the house and see Stephanie talking to Walter, they make Stephanie a target for teasing, until Stephanie turns the tables on them, and shows them how it feels to be teased. Meanwhile, at school, D.J. has been assigned to follow and observe a person for a day, then write an essay about that person. D.J. chooses Michelle to be the subject for the essay, and on ""Wake Up, San Francisco"", Joey fills in for Becky as Danny''s co-host while Becky is out of town.', 23, '1989-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 5, 'Granny Tanny', 'Danny''s mother Claire has arrived for a visit. Claire has retired from her job, and Danny wants to make Claire feel that she is still a needed person, but Danny''s plan ends up working too well -- now Claire wants to move into the Tanner house. Danny has a talk with Claire, and since there is nothing keeping her in the state of Washington anymore, Danny decides to help Claire search for an apartment near the Tanner house. During Claire''s visit, Michelle''s crib is replaced with a new bed for Michelle...but all Michelle wants to do is jump up and down on the new bed.', 23, '1989-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 6, 'Star Search', 'The family watches a videotape from when Danny and Joey were in college, and on the tape, Joey gave himself a deadline of 10 years to be a successful comedian. The end of the 10-year deadline is now two weeks away. Danny surprises Joey with a chance to appear on Star Search, hosted by Ed McMahon. Joey is accepted as a contestant on the show, and he competes against defending champion Steve Oedekerk, who wins yet again, leaving Joey feeling depressed about not being able to honor the 10 year deadline he set for himself, but Michelle lifts his spirits.', 23, '1989-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 7, 'And They Call It Puppy Love', 'Joey and Michelle are outside having a little rest in the backyard when a golden retriever shows up and steals Joey''s snack. The girls want to keep the dog, but Danny''s not sure that he should allow that. Jesse is not thrilled at all when the dog picks his bed, of all places, to give birth to a litter of puppies. The dog''s owner, Frank Flood, who is from Ohio, arrives to pick up the dog after the guys call him and tell him where the dog is, and Frank decides to give the family one of the puppies. Danny allows the girls to accept the puppy from Frank.', 23, '1989-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 8, 'Divorce Court', 'Sharing a bedroom with Stephanie is driving D.J. crazy, and they end up arguing about when who is allowed in the room and when who''s not. In an effort to solve the problem, Danny, Jesse, and Joey set up a courtroom kind of setting in the living room, with Danny being the "judge" and Jesse and Joey being the two "attorneys", but the guys themselves have a problem. They have bet each other as to who among them is the most athletic, and to settle the bet, they have challenged each other to a foot race on a nearby track. It becomes even more serious when Becky shows up with the "Wake Up, San Francisco" crew to tape the race, which Danny wins -- literally by a nose.', 23, '1989-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 9, 'Dr. Dare Rides Again', 'Teaser: Danny and the girls name their new puppy "Comet", which is the name that D.J. suggested.  Main Synopsis: Jesse is reunited with Pete Biaco, a friend he hasn''t seen in three years. As they talk about old times, particularly a time when Jesse was known as "Dr. Dare" and successfully performed a life-threatening stunt, Pete mentions that Jesse is obviously not that same guy anymore. Jesse, who feels that he has lost a lot of "action" in his life, takes this as an insult and prepares to repeat the life-threatening stunt as Becky and Pete try to stop him.', 23, '1989-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 10, 'The Greatest Birthday on Earth', 'It''s Michelle''s 3rd birthday, and the guys have decided to throw a "circus" birthday party for Michelle, complete with clowns and other things seen in circuses. Before the party, Danny complains about a problem with his car, and Jesse agrees to fix it. Jesse can''t fix it, so he takes Stephanie and Michelle out to a gas station with him to have it fixed. After the car is fixed, Jesse and the girls decide to visit the restroom before they leave, and during this time, Elmer, the mechanic, locks the station up without knowing that Jesse, Stephanie, and Michelle are still inside. Michelle''s friends arrive at the house, and Danny, Joey, and D.J. try to keep them busy, in hopes that Jesse, Stephanie, and Michelle will be home soon. At the gas station, Jesse and Stephanie throw a makeshift "circus" party for Michelle, then Elmer returns three hours later, and he''s surprised that he locked Jesse, Stephanie, and Michelle in the station. Elmer unlocks the station to let them out. By this time, Mi', 23, '1989-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 11, 'Aftershocks', 'An earthquake has left its emotional marks on Stephanie, and now the only thing she wants to do is cling to Danny. Jesse and Joey suggest taking Stephanie to a child psychiatrist. Danny reluctantly follows the suggestion and takes Stephanie to Doctor Mary-Ann Steiner, who uses a picture Stephanie drew to get her to explain her behavior -- on the day of the earthquake, Danny was three hours late getting home from work, and Stephanie thought she''d never see Danny again, and she''s been clinging to Danny ever since, so she''ll always know where he is. Doctor Steiner helps Stephanie come up with a solution to her problem. Meanwhile, D.J. wants to hide from the world when she gets her first zit -- right on her nose.', 23, '1989-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 12, 'Joey & Stacy and... Oh, Yeah, Jesse', 'Joey has fallen for Stacy, one of Jesse''s background singers. Stacy, who feels the same way about Joey, notices how bossy Jesse is to Joey while they''re at work making commercials, so she encourages Joey to refuse to be bossed around by Jesse all the time. When a presentation that''s based on an idea by Jesse is rejected, Joey substitutes his own idea for the presentation, and Joey''s version of the presentation is not rejected. This leaves Jesse angry and feeling like the odd man out, and Jesse takes it out on Joey and Stacy, until Danny helps Jesse realize that he is too bossy, and Joey was right to assert himself, so Jesse apologizes to Joey and Stacy and promises that he''ll try not to be so bossy to Joey anymore. Meanwhile, Comet, as playful as he is, has a habit of damaging things that are lying around the house, and Stephanie''s favorite stuffed toy, Mr. Bear, is Comet''s latest victim. Fortunatel', 23, '1989-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 13, 'No More Mr. Dumb Guy', 'Becky invites Jesse to accompany her to a well-cultured soiree, but Jesse declines, because he feels that he wouldn''t fit in. As soon as Jesse discovers that Eric Trent, who was Becky''s English professor in college, will be there, Jesse becomes jealous, afraid that someone who is more intelligent than he is will sweep Becky off her feet, so he studies hard so he can prove to Becky that he''s intelligent enough for her. Meanwhile, D.J. and Stephanie teach Michelle how to insult people, and when Danny hears this, he wants D.J. and Stephanie to teach Michelle that insults are not nice.', 23, '1990-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 14, 'Misadventures in Babysitting', 'D.J. wants her own phone number because having only one phone number in a house with 5 other people is driving her crazy. D.J. is willing to pay for the new phone number herself, but she needs a way to earn money, so she takes a job babysitting Brian Kagan, a little terror who really takes a toll on her. The guys are having a poker game in Danny''s kitchen, and Becky and Jesse can''t agree as to where to spend Christmas. Brian ends up getting his head stuck in the railing of the stairs in his house, and Danny leaves the poker game when D.J. calls him about it. Danny helps Brian, and decides to let D.J. have her own phone line because D.J. did the right thing by calling Danny for help when she needed it instead of trying to handle the situation on her own.', 23, '1990-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 15, 'Lust in the Dust', 'For what seems like the millionth time, Danny has broken a date, and this time it''s because her earlobes were not the right size. D.J. and Stephanie set Danny up with Stephanie''s dance teacher Karen Penner, and when Danny and Karen go to her apartment, Danny sees what a mess it is, and breaks yet another date. It seems that Danny has been deliberately nitpicking and finding mostly trivial things wrong with his dates, so he can have a reason to cancel them, because almost three years after Pam''s death, Danny is still extremely nervous about dating again. Jesse and Joey convince Danny to give Karen another chance.', 23, '1990-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 16, 'Bye, Bye Birdie', 'It''s Michelle''s first day of preschool, a day that she has highly anticipated, but at preschool, Michelle accidentally lets the class''s pet bird fly out the classroom window, and now none of her new classmates want to be her friend, but that attitude changes when she brings a new bird to class. Meanwhile, Stephanie, who is fascinated by D.J., wants to read D.J.''s diary and learn all of her secrets, but Stephanie unintentionally breaks the lock that holds the diary closed, and when Stephanie tries to glue the lock back onto the diary, she ends up gluing her hand to the diary''s cover.', 23, '1990-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 17, '13 Candles', 'It''s D.J.''s 13th birthday. A lot of friends are coming to D.J.''s birthday party, including Kevin, a boy D.J. has a crush on. While the party''s music is playing, Kimmy tries to get D.J. and Kevin to dance with each other, but they''re too nervous, so Kimmy and the rest of D.J.''s friends try to get D.J. and Kevin to kiss by setting them up during a game of "spin the bottle". After a spin, just as D.J. and Kevin are about to kiss, Danny, Jesse, and Joey -- who overheard the whole situation -- get overprotective and barge in and stop it from happening. D.J. becomes furious and feels embarrassed by what the guys did, and she feels that they have ruined her 13th birthday. Becky talks to D.J. and the guys, and the guys remember that they themselves played "spin the bottle" when they were D.J.''s age, so after D.J. talks to Becky about the situation, the guys apologize to D.J. for overreacting, and D.J. apologizes for being angry.', 23, '1990-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 18, 'Mr. Egghead', 'Teaser: Michelle and Danny record the welcome message on the new answering machine.  Main Synopsis: Joey gets a chance to be "Mr. Egghead" on a TV science show called "Mr. Egghead". Stephanie and her class are the guests on Joey''s tryout episode. Joey feels like Mr. Scrambled Egghead when he accidentally breaks Stephanie''s nose during the taping of the show, and Stephanie and her class are scheduled to have their class picture taken on the next day. Stephanie was humiliated in her class picture last year, because the photographer snapped the picture while Stephanie was in the middle of a sneeze, but this year, Stephanie absolutely refuses to let a bandage on her nose result in yet another humiliating class picture, because she''s afraid her classmates will call her "Robo-nose".', 23, '1990-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 19, 'Those Better Not Be the Days', 'Danny, Jesse, and Joey feel that the girls are taking them for granted. No matter what the guys do, they never receive a "thank you" from the girls, so the guys decide to teach the girls a needed lesson by switching roles and letting the girls see how it feels to be the adults for a day, but when it seems that the girls are not catching on as planned, the guys look into what could happen in the future if the girls continue to take them for granted. Jesse thinks the worst part about the future they imagined is that he wore a hair piece. Later, the girls do catch on to the lesson the guys are trying to teach them, and they admit their mistake of taking the guys for granted.', 23, '1990-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 20, 'Honey, I Broke the House', 'Jesse wants to have a romantic night with Becky, who tells Jesse that she can''t because she is scheduled for a business dinner with Beau McIntyre, a former football player who is scheduled to be a guest on "Wake Up, San Francisco", and this makes Jesse jealous. There are 20 minutes left until Stephanie has to be at dance class, so what is there to do until then? She can''t get anyone to listen to her about how her day has gone so far, even Joey, who is preoccupied with his new car ""Rosie"". When Joey sees a nick in Rosie''s paint, he leaves with Comet to go to Sid & Jean''s Auto Supplies to buy a bottle of touch up paint. While Joey is gone, Stephanie gets inside of "Rosie" so she''ll have something to do. As she is sitting in the driver''s seat, she decides to turn the radio on, and after messing with the radio, and it doesn''t come on, Stephanie turns the key, hoping that she''s turning it toward the auxiliary option that allows you', 23, '1990-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 21, 'Just Say No Way', 'D.J. and Kimmy organize the "Spring Backwards Dance" at school. For this dance, the girls must ask the boys to the dance. D.J. is too nervous to ask Kevin, so Stephanie does it for her. At the dance, D.J. finds Kevin and two other boys, Sam and Paul, drinking beer. D.J. takes the beer away from them in an effort to stop them. Unfortunately, this is when Jesse enters the hallway and sees D.J. holding the beer can. As a result, Jesse goes crazy and wrongfully accuses D.J. of drinking, and Jesse, Danny, and Joey refuse to believe D.J. when she tells them the truth that she was not drinking and that she was trying to stop Kevin, Sam, and Paul from drinking. Later, Jesse and the guys feel like complete fools for doubting D.J. when Kevin tells Jesse and Danny the truth, exactly what D.J. told them.', 23, '1990-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 22, 'Three Men and Another Baby', 'The family is babysitting the Kagans'' new baby, Tony, for a night. Tony bonds with Jesse, who lets Tony sleep in Michelle''s old crib, lets Tony play with Michelle''s toys, and sings Michelle''s special bedtime song to Tony, and this leaves Michelle thinking Jesse no longer cares about her. Jesse proves Michelle wrong when he realizes how hurt he''s making her feel. Meanwhile, Danny enrolls Comet in obedience school, and it''s not making Comet as obedient as Danny would like for him to be.', 23, '1990-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 23, 'Fraternity Reunion', 'It''s the night of a reunion for Joey and Danny -- the reunion of Chi Sigma Sigma (CSS), the college fraternity they were in 10 years ago. Joey and Danny remember that the fraternity burned Danny''s Chi Sigma Sigma jacket 10 years ago when Danny messed up and unintentionally allowed a sorority, Lambda Tau Delta (LTD), to steal the stuffed seal that was Chi Sigma Sigma''s mascot. The Lambda Tau Delta girls tickled Danny to the ground and took the seal. Since the LTD girls are also having a reunion, Joey and Danny see an opportunity to get the seal back from the LTD girls. D.J. and Kimmy then accidentally break the TV while trying to take it upstairs, and Danny tells D.J. and Kimmy that they are not allowed to see each other for three weeks. Later, Danny and Joey head off to the reunion while D.J. stays home to watch Stephanie and Michelle.', 23, '1990-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 3), 24, 'Our Very First Telethon', 'Tag: Mike Love still singing while the Tanners dance.', 23, '1990-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 1, 'Greek Week', 'Jesse''s grandparents, Gina and Iorgos "Papouli" Katsopolis arrive for a visit from Greece and they are celebrating the 50th anniversary of their wedding.', 23, '1990-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 2, 'Crimes and Michelle''s Demeanor', 'Main Synopsis: Michelle encourages Stephanie and D.J. to have a pillow fight with her, and a window ends up getting broken during the pillow fight. Danny punishes D.J. and Stephanie, but he fails to punish Michelle, who started the whole thing. This is because Danny is having a hard time realizing that Michelle, who is almost four-years-old, is old enough to be punished. When D.J. and Stephanie open Danny''s eyes to the situation, they give Danny the courage to give Michelle her first punishment. Meanwhile, Jesse buys an expensive engagement ring for Becky, who tries to stop Jesse from selling his Elvis Presley signed guitar in order to pay for the ring.', 23, '1990-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 3, 'The I.Q. Man', 'Teaser: Michelle is in bed with Comet.    Main Synopsis: Jesse and Joey have prepared a commercial for a cologne company. The client, Ms. Garland, wants Jesse to play the main role in the commercial. When Ms. Garland demands that Jesse wear less than he is willing to wear in the commercial, Jesse and Joey decide to stop working for Mr. Malatesta. On career day at D.J.''s school, the family encourages Jesse and Joey to continue to work together in the advertising business, but without Mr. Malatesta, so with the help of a loan from Danny, who wants to be a silent partner, Jesse and Joey open up their own business.', 23, '1990-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 4, 'Slumber Party', 'Teaser: Michelle builds a block tower with D.J.''s help.    Main Synopsis: Stephanie''s Honeybee troop is holding a mother/daughter slumber party, and this awakens feelings of loss in Stephanie, because Stephanie knows that she''s the only girl in the troop who doesn''t have a mother. Becky, who was a member of a Honeybee troop when she was a kid, agrees to accompany Stephanie to the slumber party, but when Becky''s car breaks down in Placerville, Joey must take Becky''s place at the party. The activities don''t exactly fit Joey, so a devastated Stephanie goes back home, unleashes an angry tirade, and says that she hates the fact that she doesn''t have a mother, because her mother Pam died a few years ago. D.J. talks to Stephanie, and Stephanie agrees to go back to the party, and this time, D.J. goes with her, and things turn out better with D.J., who used to be in a Honeybee troop. Meanwhile, Danny offers the attic as office space for Joey and Jesse''s business, Double J Creative Services, so', 23, '1990-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 5, 'Good News, Bad News', 'Teaser: Joey teaches Michelle a joke.   Main Synopsis: D.J. is the new editor-in-chief of the school newspaper, and she plays favorites by making Kimmy the editor of the sports page. When Kimmy turns in a report that looks like it belongs in the gossip column, D.J. tells Kimmy to rewrite the story, but when Kimmy refuses, D.J. fires her, and this leads to a feud between D.J. and Kimmy, but they work things out. Meanwhile, Double J Creative Services is hired by the TV station, which wants a commercial made for ""Wake Up, San Francisco"", but working with Danny on this commercial is anything but fun. Meanwhile, Michelle plays ""echo"" with Stephanie, and hearing Michelle repeat every word Stephanie says is driving Stephanie crazy.', 23, '1990-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 6, 'A Pinch for a Pinch', 'Teaser: Michelle and Joey play hockey in the living room.    Main Synopsis: It''s Joey''s week to be a parent volunteer at Michelle''s preschool, but on the Thursday of that week, Joey has an appointment with a dentist, so he gets Jesse to cover for him at the preschool. When class bully Aaron starts bullying Michelle, Jesse loses his temper with Aaron and tells Michelle to retaliate by giving Aaron a taste of his own medicine. When the teacher, Mrs. Manning, sees this, she punishes both Aaron and Michelle. Jesse, who believes Aaron should be the only one to be punished, takes Michelle out of the preschool. Danny understands that Jesse was trying to protect Michelle from Aaron, but Danny feels that Jesse shouldn''t have had to take Michelle out of the preschool, so Danny straightens things out with Mrs. Manning so Michelle can go back to preschool. Meanwhile, Kimmy, who is now in charge of the horoscope in the school newspaper, writes a horoscope under Stephanie''s sign, and Stephanie freak', 23, '1990-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 7, 'Viva Las Joey', 'Teaser: Michelle tells Jesse she has an "owie".  Main Synopsis: Because of an illness, the Aronson Chimps, who are scheduled to open for Wayne Newton in Las Vegas, can''t perform, so Joey''s agent gets him booked to take the place of the Aronson Chimps. As Joey is packing, and everyone is preparing to go to Las Vegas, Jesse suggests that Joey call his mother Mindy to tell her to come to Las Vegas to see him, but Joey mentions that Mindy has a job working as Goofy at Disney World, so Jesse asks Joey if he would like to invite his father to see the show. Joey tells Jesse that he doesn''t think his father, Colonel Gladstone, would be able to make it to the show. This gives D.J. and Stephanie an idea -- why don''t they surprise Joey by secretly inviting the Colonel to the show? The family heads to Las Vegas after D.J. and Stephanie leave a message on the Colonel''s answering machine. In Joey''s dressing room, Stephanie slips up and mentions that she and D.J. secretly invited the Colonel. Danny', 23, '1990-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 8, 'Shape Up', 'Teaser: Jesse and Michelle have "Fiber Bears" cereal for breakfast.  Main Synopsis: It''s getting close to Kimmy''s 14th birthday. Of course, D.J. is among the guests invited to Kimmy''s birthday party, which is scheduled to take place at a local hotel''s indoor swimming pool. D.J. is afraid to let her friends see her in a swimsuit, so she secretly begins a diet that could become dangerous. The first person to notice the diet''s adverse effects is Stephanie, who reluctantly promises to keep her mouth shut, but while the family is at a local gym, D.J. collapses, indicating that the diet has become dangerous. Stephanie, who is afraid D.J. may hurt herself even worse by continuing the diet, can''t keep her mouth shut any longer, so she tells the guys about the diet, and Danny helps D.J. realize that her looks don''t matter to her friends as much as she thinks.', 23, '1990-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 9, 'One Last Kiss', 'Teaser: Danny and Michelle help Stephanie prepare Comet''s birthday party.   Main Synopsis: At the 10 year reunion at Jesse''s old high school, Jesse is reunited with Carrie Fowler, his high school sweetheart. They parted ways 10 years ago when Carrie took advantage of a chance to be a model in France while Jesse wanted to try to succeed in the music business. It seems that Carrie still has feelings for Jesse, and Becky is the reason why Jesse doesn''t feel the same way. Meanwhile, Stephanie throws a birthday party for Comet.', 23, '1990-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 10, 'Terror in Tanner Town', 'Teaser: Tailcoat and top hat fitting for Jesse, who doesn''t want to wear a tailcoat and top hat when he and Becky get married.    Main Synopsis: Danny introduces the family to his new girlfriend Cindy, who is divorced and has a son named Rusty. When Cindy is called to the laundromat she owns, Rusty stays behind at the Tanner house and terrorizes the family in hopes of breaking Danny and Cindy up, because Rusty wants Cindy to re-unite with his father.', 23, '1990-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 11, 'Secret Admirer', 'Teaser: Jesse and Michelle eat the cream filling out of their cookies.   Main Synopsis: D.J. has fallen for Ricky, the paperboy. This gives Rusty the idea for his latest prank. Rusty writes a love letter and plans to make D.J. think the letter is from Ricky. Rusty tells Michelle to give the letter to D.J., and the trick backfires when Michelle gives the letter to Stephanie instead and tells Stephanie that the letter is from Rusty. This starts a chain reaction where everyone else in the house intercepts the letter and falls for it.', 23, '1990-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 12, 'Danny in Charge', 'Teaser: The guys put Michelle to bed on the night of her 4th birthday.  Main Synopsis: While Jesse and Joey are in the forest to try to find a fox to film for a commercial and Becky is out of town, Danny is home by himself with the girls, and he sees an opportunity to prove that he''s a "superdad". Danny promises to attend a school science fair that Stephanie has entered a project in. Later, Danny promises to see "Romeo and Juliet", a school play where D.J. will play as Juliet. Danny then realizes that he has a big problem -- both events are scheduled to take place on the same day at the same time and Stephanie and D.J. each try their best to get Danny to attend the event that they want him to attend. Stephanie wants Danny to go to the science fair, and D.J. wants him to go to the play, but on the big night, Danny doesn''t show up. After the play and the science fair are over, D.J. and Stephanie go home and discover that Danny fell asleep and missed the play and the science fair, and th', 23, '1990-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 13, 'Happy New Year', 'Teaser: Michelle and a caterpillar.   Main Synopsis: Joey has not yet found a date for New Year''s Eve. Therefore, Danny and Jesse secretly videotape Joey and send the tape to a local video dating service. Joey''s date ends up being a woman named Christine, and he and Christine fall in love at first sight when they see that they have almost everything in common. Joey wants to take Christine to Las Vegas and get married, but later realizes that they need to take the time to get to really know each other first. Meanwhile, when Kimmy and D.J. throw a New Year''s Eve party at Kimmy''s house with the intention of inviting ""just a few close friends"", they end up with more than 400 guests.', 23, '1990-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 14, 'Working Girl', 'Teaser: Michelle plays with drums.  Main Synopsis: 14-year-old D.J. desperately wants to buy an expensive pair of shoes, so when she doesn''t get the money from Danny, she asks Danny to let her get a job so she can earn enough money to get the shoes. Danny reluctantly lets D.J. start working for a photographer named Jack, and her job is to make reluctant kids smile for the camera. Danny allows D.J. to have the job under one condition -- D.J. must make sure her grades don''t drop. D.J.''s science grade has been suffering lately, but she believes that the job will not only get her enough money to buy the shoes, but she also believes that this job will prove to Danny that she''s not a little kid anymore, but D.J. ends up in a sticky situation when she brings home a science exam with an "F" on it, and when D.J. tells Danny that she thought that this job would prove to Danny that she''s not a little kid anymore, Danny tells D.J. that there is nothing wrong with being a kid, and Danny also tells', 23, '1991-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 15, 'Ol'' Brown Eyes', 'Teaser: Jesse teaches Michelle how to do a cool walk.  Main Synopsis: D.J. organizes a benefit to raise money for a new computer for the school, and Danny will be the host of the benefit show. To prove to D.J. that he''s cool, Danny wants to sing a song at the benefit -- "My Generation" by The Who. D.J. thinks that if Danny does this, Danny would be so dorky that D.J. won''t ever be able to show her face in school again. Meanwhile, Michelle has come up with a new game -- she hides an object, and whoever the object belongs to must find it, and one of the objects she has hidden is the wedding ring Jesse intends to give to Becky at the wedding, and Joey must find it.', 23, '1991-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 16, 'Stephanie Gets Framed', 'Teaser: Michelle is brushing her teeth.   Main Synopsis: Danny is informed that Stephanie is having problems reading at school. Stephanie is taken to an eye doctor who prescribes eyeglasses for her to use for reading. Stephanie doesn''t want the glasses because she''s afraid her classmates will make fun of her and think that she''s a nerd because of the glasses. She feels better about having the glasses when she gets some advice from Steve Urkel, the visiting cousin of D.J.''s friend Julie. Meanwhile, Jesse must choose a best man for the wedding.', 23, '1991-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 17, 'A Fish Called Martin', 'Teaser: Michelle sings with Jesse and the Rippers.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 18, 'The Wedding (1)', 'Teaser: Danny tells Michelle that she''ll be the flower girl at the wedding.   Main Synopsis: It''s the day before Jesse and Becky''s wedding. Stephanie and D.J. are using Danny''s camcorder to tape the events leading up to the wedding, and they also intend to tape the wedding. Becky''s sister Connie Anderson has arrived and brought her son Howie with her, but Michelle and Howie don''t remember each other from when Connie and Howie visited 2 years ago. Minutes later, Becky''s parents Kenneth and Nedra arrive. Kenneth explains that they would have arrived earlier, had a man on a motorcycle not cut them off. Jesse shows up and explains that he would have been home earlier if he had not been stuck behind a slow driver. When Kenneth and Jesse see each other''s faces, Kenneth realizes that Jesse was the man on the motorcycle and Jesse realizes that Kenneth was the slow driver. From the start, it seems that Jesse and Kenneth can''t get along with each other. Later, Kenneth has a talk with Jesse, and', 23, '1991-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 19, 'The Wedding (2)', 'Teaser: A recap of part 1.   Main Synopsis: A tomato filled truck driven by a tomato farmer parks under Jesse, who releases himself from the parachute, and falls safely into the bed of the truck. The farmer tells Jesse he''s in a town known as ""Tomato Country"". Jesse then tries to use the farmer''s truck to go to the church for the wedding, but that''s when a cop shows up. By now, it''s 10:25am, and Jesse is 25 minutes late for the wedding. The phone at the church rings, and it''s Jesse, who tells Becky that he''s in jail in Tomato Country. Becky heads to the jail and gets Jesse released. They make it back to the church, where they are pronounced husband and wife. After a party at the Tanner home, Jesse and Becky leave for their honeymoon.', 23, '1991-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 20, 'Fuller House', 'Teaser: Jesse and Becky have arrived home from their honeymoon.   Main Synopsis: Jesse and Becky return from their honeymoon, which took place in Bora Bora, an island near Tahiti. Becky reminds Jesse that he needs to start packing if he''s going to move to Becky''s home. Michelle doesn''t take this very well, because she doesn''t want Jesse to move out, so Michelle starts packing to go with Jesse, who explains things to Michelle. Jesse''s belongings are moved to Becky''s house, but Jesse still has feelings of emptiness. Danny and Joey can''t seem to cheer Michelle up, until Jesse arrives for a visit on the next morning. Becky sets it up to where she and Jesse will be spending the night at the Tanner house, sleeping on two cots in the attic. That night, Becky tells Jesse that she talked to Danny, who has agreed to let Jesse renovate the house''s 1300 square foot attic into a family sized apartment so Jesse doesn''t have to move out. As a result, a new arrangement is made -- Joey will move into J', 23, '1991-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 21, 'The Hole-in-the-Wall Gang', 'Teaser: Michelle helps Joey move into the bedroom that used to be Jesse''s bedroom.  Main Synopsis: Stephanie wants to be just like D.J., so she starts dressing like D.J., and tries to act like D.J., who is getting ready to go to the food court of a local mall with Kimmy. D.J. wants to wear something "fun" to the mall, so she, Kimmy, Stephanie, and Michelle head to Danny''s bedroom, where D.J. starts looking for something to wear from Danny''s closet. Stephanie tries to do the same thing, but when D.J. tries to stop her, they end up accidentally pulling out the rod that Danny''s shirts are hung on. This is when D.J. and Stephanie argue over who is going to put the rod back in the closet, and when D.J. tells Stephanie to let go of the rod, that''s exactly what she does -- and accidentally sends the rod into the wall, putting a hole in the wall. That''s when Kimmy goes home. The girls go to the attic, where Jesse is working on renovating the attic and not letting Joey do anything to help him.', 23, '1991-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 22, 'Stephanie Plays the Field', 'Teaser: Danny arrives home from shopping.  Main Synopsis: Danny is the head coach of the Giants, a local little league baseball team. Stephanie has fallen for Brett Davis, who plays for a rival team called the Cubs. This makes Stephanie want to join the Giants and play for Danny, and her surprisingly good pitching makes it easy for her to become a member of the team. In an upcoming game, the Giants are scheduled to play against the Cubs, so Brett tells Stephanie to take it easy and not throw the "Tanner Twister" whenever Brett''s at bat because Brett''s father will be at the game videotaping Brett, and Brett doesn''t want his father to see him get outdone by a girl, but Stephanie just can''t bring herself to throw the game for Brett, and the Giants win when Stephanie strikes Brett out for the third out in the last inning of the game. Fortunately, Brett understands why Stephanie did this, and admits that he shouldn''t have asked Stephanie to go easy on him at the game. Meanwhile, Becky and', 23, '1991-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 23, 'Joey Goes Hollywood', 'Teaser: Jesse and Michelle play with puppets.   Main Synopsis: Joey lands a part in a new comedy show, starring alongside Annette Funicello and Frankie Avalon. The family accompanies Joey to Los Angeles for the taping of the series opener, and after this, the new comedy show is turned into a cartoon with Joey, Frankie, and Annette providing the main voices in the show. Meanwhile, Stephanie wants to change her name because she''s being harassed by classmates who call her ""Step On Me"".', 23, '1991-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 24, 'Girls Just Wanna Have Fun', 'Teaser: Jesse plays drums and the keyboard well enough, but he needs practice on the saxophone.  Main Synopsis: D.J. wants to meet a boy named Ryan at a house where Kimmy will be babysitting Aaron Bailey. Danny, who wants D.J. to stay home to do her homework instead of doing her homework with Kimmy, won''t let D.J. go to the house where Kimmy is babysitting Aaron. D.J. decides to go anyway, so she asks Becky to cover for her, promising Becky that she''ll be back in 10 minutes, but 10 minutes becomes 30 minutes, and Becky can no longer find a way to cover for D.J. anymore. When D.J. arrives home, Becky talks to her, and D.J. admits that she took advantage of her friendship with Becky and that the reason why D.J. was gone longer than she said she would be is because she and Ryan were really starting to get along with each other. Meanwhile, Jesse and Joey put a pool table in their office. Jesse, calling himself "The Kid", thinks he can''t be beat in the game of pool, until he discovers the', 23, '1991-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 25, 'The Graduates', 'Teaser: Joey and Michelle sing the blues.   Main Synopsis: At age 33, Danny feels like he doesn''t have as much youth in him as he used to, so he starts dating a 21-year-old college student named Kirsten. Meanwhile, D.J. has graduated from 8th grade, Michelle has graduated from preschool, and Stephanie feels left out because her 3rd grade year has ended without a graduation ceremony.', 23, '1991-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 4), 26, 'Rock the Cradle', 'A pregnancy test indicates that Becky is pregnant. She tells everyone except for Jesse, because she can''t get Jesse to listen to her because Jesse is obsessed with the fact the he and the Rippers will be going on tour for four months over the summer. When Becky finally does get Jesse to listen, Jesse is excited about the pregnancy. Meanwhile, Michelle makes up an invisible friend named Glen, because she misses her friends from preschool.', 23, '1991-05-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 1, 'Double Trouble', 'Jesse is back home from the tour that he and the Rippers went on over the summer, and an ultrasound shows that Becky is carrying twins. While this thrills Becky, the same can''t be said for Jesse, who feels afraid of what is now a double responsibility that awaits him, because he doesn''t want to mess up in any way as a father. The family helps Jesse come to grips with this fear, and Jesse is happy about Becky carrying twins, and they have told Dr. Sinclair that they want to wait until birth to know what gender the babies are. Meanwhile, as the new school year starts, Stephanie is nervous about entering 4th grade, until she meets her new teacher, Mr. Lowry, whom she now has a crush on. Michelle is worried about what kindergarten will be like, until she befriends Teddy, one of her new classmates.', 24, '1991-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 2, 'Matchmaker Michelle', 'After a talk with Teddy, Michelle realizes that she doesn''t know how it feels to have a mother, so in order to have a mother, Michelle tries to find a woman for Danny, and Michelle believes that her teacher, Miss Wiltrout, is exactly the one she''s looking for. Meanwhile, when a record company tells Jesse that Jesse and the Rippers'' image is too soft, Jesse and Joey work together to try to come up with a tougher image for the band, and D.J. is writing an essay for school, and it''s titled "What it''s like to be someone else". For this essay, D.J. temporarily switches places with Kimmy.', 24, '1991-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 3, 'Take My Sister, Please', 'D.J. is absolutely fed up with Stephanie. Therefore, D.J. petitions the guys to let her have her own bedroom -- something she hasn''t had in 4 years. The guys talk it over, and they decide to let D.J. have her own bedroom. D.J. feels relieved, after four years of sharing a bedroom with Stephanie. The new arrangement is that D.J. and Michelle will switch rooms, and as a result, Michelle will be Stephanie''s new roommate, while D.J. takes over Michelle''s old bedroom. Problem is, Michelle doesn''t want to be Stephanie''s roommate either, making Stephanie believe that no one wants to live with her. For D.J., this puts the prospect of having her own room in jeopardy, until she helps Stephanie accept the change, and they help Michelle accept the fact that she''ll be Stephanie''s new roommate. Meanwhile, Becky''s Lamaze instructor, Lisa Green, holds a Lamaze class in the living room with Jesse and Becky and some of their friends.', 24, '1991-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 4, 'Oh Where, Oh Where Has My Little Girl Gone?', 'Todd Mitchell, one of high school freshman D.J.''s schoolmates, is spreading a false rumor around school that D.J. is the worst kisser. It''s Todd''s way of getting even with D.J. for refusing to let Todd kiss her on the way home from the library. D.J. shows Kimmy a sympathy card that D.J. got from Kathy Santoni, who, on the card, refers to the situation as a "mega crisis". Later, under the guise of collecting dirty clothes to take downstairs to the laundry room, Danny goes upstairs to D.J.''s bedroom while she''s not there and finds the card. The term "mega crisis" arouses Danny''s curiosity, and he wants to know what D.J.''s mega crisis is. Later, at a bowling alley, Danny is spending some time with D.J. when Kimmy shows up and takes D.J. to the mall, where Todd Mitchell is continuing to spread the rumor. At home, Danny slips up and mentions "mega crisis", indicating to D.J. that Danny has seen the card.', 24, '1991-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 5, 'The King and I', 'A record company tells Jesse that if he can write a song that can be a hit, Jesse and the Rippers will be signed. When the family prepares to go to Lake Pollock for a big family reunion, Jesse, who is frustrated by his lack of song ideas, says in an angry way that he can''t go to Lake Pollock with the family. Later, in a diner, an Elvis Presley impersonator helps Jesse realize that he was wrong to lose his temper and snap at the family, and that his obsession with writing a hit song for the record company has made him forget how important his family is to him.', 24, '1991-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 6, 'The Legend of Ranger Joe', 'Joey feels like his life is going nowhere. He doesn''t want to read a bad review of his last performance, and he doesn''t have to, because the newspaper''s employees are on strike, then the KFLX radio station calls and asks Jesse a cartoon trivia question that Jesse can''t answer, but Joey answers it correctly, winning tickets to the Donny and Marie reunion, then Linda, an attractive technician from Hilltop Cable Company, comes over and puts a booster on the cable out back, then comes inside and works on the TV. Now channels such as the Truck and Tractor Pull network are available. Before leaving, Linda agrees to go to the Donny and Marie reunion with Joey. Jesse and Joey then sit down to watch "Wake Up, San Francisco". The first guest is local children''s TV show legend Ranger Roy, who is Joey''s childhood idol. Roy announces that after 30 years of hosting his show, he is retiring, but before he does, a new "ranger" will be chosen.', 24, '1991-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 7, 'The Volunteer', 'After school is dismissed for the day, D.J. goes to the Golden Gate Nursing Home to visit 75 year old Eddie Johnson, her "adopted grandparent" in the Adopt-A-Grandparent program. At home, Stephanie and Kimmy have a disagreement -- Kimmy seems to think her dog Coco is smarter than Comet, so they agree to invite all the dogs that live in their neighborhood into the Tanner family backyard for a little dog show in order to settle this. D.J. has promised to be the judge, so at the end of her visit with Eddie, D.J. tells Eddie about the dog show. Eddie wants to see the show, so he sneaks out of the nursing home and goes with D.J. to the house. At home, D.J. notices Eddie acting strange, like he doesn''t know who D.J. is.', 24, '1991-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 8, 'Gotta Dance', 'Stephanie''s dance teacher has told Stephanie that Stephanie has the potential to become a professional dancer. It would be a dream come true for Stephanie, but it means taking special classes before and after school and on weekends, an earlier bedtime, and less TV. Stephanie convinces Danny to let her have a shot at it. As a result, Stephanie no longer has enough free time to spend with friends and family, and she has a dance recital coming up, and Danny is more excited about it than Stephanie is. On the night of the recital, Danny tells Stephanie that if the director of the Bayview Dance Academy, who is in the audience, likes Stephanie''s performance, Stephanie can get into Bayview''s summer dance camp. Minutes later, the recital begins, and Stephanie messes it up on purpose. Stephanie then tells Danny that she wants things to go back to the way they were, when she had the time to spend with friends and family', 24, '1991-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 9, 'Happy Birthday, Babies (1)', 'It''s Michelle''s 5th birthday. Michelle is afraid she''s about to lose her status as "the baby of the family", because Becky is pregnant. Michelle thinks this status is what makes her special. As a result, even though she can''t stop it, Michelle doesn''t want to be 5 years old. As the family convinces Michelle that she''s special to them no matter what, Jesse is having what he thinks are sympathy pains.', 24, '1991-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 10, 'Happy Birthday, Babies (2)', 'Michelle''s birthday party has just started when Becky announces that she''s going into labor. The twins are coming, and she needs to get to the hospital, fast. When Jesse leaves to take Becky to the hospital, the others stay behind to speed up Michelle''s birthday party so they can get to the hospital to be there when the twins are born. At the hospital, Jesse''s "sympathy" pains turn out to be appendicitis. As Jesse undergoes an emergency appendectomy, Danny is the one who is at Becky''s side for the time being. After the surgery, Jesse is placed in the maternity room that Becky is in, and even though he went through an operation, Jesse is still at Becky''s side when Becky gives birth to twin boys. Nicholas "Nicky" Katsopolis is named after Jesse''s father, and Alexander "Alex" Katsopolis is named after the teacher who inspired Becky to go into journalism.', 24, '1991-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 11, 'Nicky and/or Alexander', 'Becky and the twins come home from the hospital, and Becky''s doctor has mentioned that it''s common for new mothers to have mood swings. Nicky and Alex are still wearing their hospital bracelets. Michelle feels left out when D.J. and Stephanie are allowed to hold the twins and Michelle is not allowed to. Becky wants to take a picture of Nicky and Alex for her mother Nedra, but Becky wants Nicky and Alex to be wearing the booties Nedra made for them, but Jesse doesn''t think the booties are manly, and he wants the twins to look manly. Later, Becky removes the bracelets from the twins, but leaves the booties on the twins so she can tell them apart. Minutes later, while Becky is out of the room, Jesse removes the booties from Nicky and Alex''s feet. It takes Jesse only a few seconds to realize that now he can''t tell Nicky and Alex apart without the bracelets and the booties. Jesse and Becky finally let Michelle hold one of the twins, and', 24, '1991-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 12, 'Bachelor of the Month', 'Danny introduces Vicky to the family, and Bay City magazine has chosen Danny as their bachelor of the month. When the issue that Danny is in is released, a lot of women start asking Danny out on dates. Because of this, Danny is out virtually every night, and Michelle misses Danny being home to tuck her in at bedtime every night. On "Wake Up, San Francisco", Vicky accuses Danny of being a shallow date even though she has never dated Danny, and as a result, Danny asks Vicky out so she can experience a date with Danny. When Danny and Vicky go on their date, Michelle and Teddy stow away in Danny''s car so Michelle can be with Danny. A few minutes after arriving at the restaurant, Danny sees Michelle and Teddy sitting at a table close to the one he and Vicky are sitting at. Danny talks to Michelle, and apologizes for not spending much time with her lately. At home, Danny and Vicky share a kiss. Meanwhile, in the attic, Jesse has f', 24, '1991-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 13, 'Easy Rider', 'Michelle wants to learn how to ride her bicycle without the training wheels on it, and Joey volunteers to teach her. During the bicycle lesson from Joey, Michelle crashes into a bush and gets a scrape on her hand, and she tells Joey that she doesn''t trust him anymore, but Joey encourages Michelle to continue to learn how to ride her bike, and convinces her to trust him. Meanwhile, Becky and Jesse take Nicky and Alex to visit Becky''s aunt Ida, and they end up taking almost everything in Nicky and Alex''s bedroom with them. Also, Danny and Vicky become closer.', 24, '1991-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 14, 'Sisters in Crime', 'Danny, Jesse, and Joey are participating in a charity ice hockey game for KTMB TV, the TV station that Danny, Becky, Vicky, and Joey work for. Becky and Vicky will be at the game too, so Becky drops Nicky and Alex off at her aunt Ida''s house while D.J. stays home to baby-sit Stephanie and Michelle. After all the adults have left, Steve Peters, a boy from D.J.''s school, shows up to take D.J. to the movies. Problem is, Michelle has the sniffles and is not allowed out of the house while she has the sniffles, and Stephanie needs to finish her book report. D.J., who desperately does not want to miss out on a date with Steve, decides to remedy this problem by taking Michelle and Stephanie to the movies with her and Steve. Problem is, between Steve and D.J., they don''t have enough money for Michelle and Stephanie to get into the theater, but Kimmy happens to work at the theater. D.J. talks Kimmy into letting Stephanie and Michelle', 23, '1991-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 15, 'Play It Again, Jesse', 'It''s time for Becky to return to "Wake Up, San Francisco", and Vicky has received an offer from a TV station in Chicago. Jesse, after yet another record company has rejected him, is now the only one who stays home with the kids while Danny, Becky, and Joey work at the TV station during the day, and Jesse''s pride is hurting because Becky is the one who earns the money, while Jesse is like a stay-at-home mom. In order to solve this problem and start earning money, Jesse gets a job at an airport playing with The Diplomats, the airport''s lounge band, and at the airport, Becky convinces Jesse that the fact that Becky earns the money and Jesse is like a stay-at-home mom does not mean that Jesse has become the weaker gender in their marriage. Also at the airport, Danny says goodbye to Vicky, who has accepted the offer from the TV station in Chicago, so Danny and Vicky will be maintaining a long distance relationship.', 24, '1992-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 16, 'Crushed', 'It''s Stephanie''s 10th birthday. When Stephanie hears that Tommy Page, her favorite singer, is scheduled to be a guest on "Wake Up, San Francisco", she begs Danny to invite Tommy to her birthday party, but Danny refuses. What Danny doesn''t want Stephanie to know is that he has arranged for Tommy to be at the party, but he wants to surprise Stephanie, and that''s why he told Stephanie he wouldn''t invite Tommy. After Stephanie''s party begins, Danny brings Tommy home with him, and Stephanie is shocked. Stephanie just happens to have a monumental crush on Tommy, but Stephanie is devastated when she later sees Tommy and D.J. kissing. Stephanie declares war on D.J. for this, until Tommy helps straighten things out between them.', 24, '1992-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 17, 'Spellbound', 'Stephanie has won a class spelling bee at school, and she is now in the finals for best speller in the 4th grade. Stephanie''s success in spelling makes Michelle want to learn how to read. At the 4th grade finals, the spelling bee ends up narrowed down to two students -- Stephanie and the "Human Dictionary" Davey Chu. Stephanie is severely disappointed when Davey wins, so she challenges Davey to another spelling bee, one on one, this time in the Tanner house with Danny being the judge. Once again, Davey wins, and Stephanie becomes even angrier until Danny tells her that even if she loses at things sometimes, he''s still proud of her for putting forth her best effort. Meanwhile, Joey needs a piece of music to introduce cartoons on "The Ranger Joe Show", and he talks Jesse into trying to write the piece of music the show needs.', 24, '1992-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 18, 'Too Much Monkey Business', 'Danny''s sister Wendy has returned to the USA from the African country of Uganda. Wendy is a primate researcher and she has a pet chimpanzee named Ginger, who quickly becomes attached to Jesse for some reason. Wendy is scheduled for a job interview at the local zoo, so Joey takes her to the interview. A package is in the mail, and when Stephanie and Michelle open it, it turns out to be a figure named "Nikata". The tag on it says that there will be a curse over the family if no one "feeds" Nikata.', 24, '1992-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 19, 'The Devil Made Me Do It', 'After Jesse tells Michelle that she''s not allowed to touch his musical instruments while he''s not in the studio, she plays with them anyway while Jesse''s not in the studio, and Jesse enters the room and reminds her of the rule he just made, then tells Danny what Michelle did, so Danny grounds Michelle for the day. Michelle is so angry that Jesse told on her that she runs away to Teddy''s house, and she doesn''t want to come back home, until Danny and Jesse trick her. At home, Jesse tells Michelle that he felt terrible about telling on her, and that she needs to know that she can''t break the rules of the house, and that''s why he told on her. Meanwhile, D.J. tries to help settle an argument between Stephanie and Kimmy.', 23, '1992-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 20, 'Driving Miss D.J.', 'D.J. now has her learner''s permit and she''s eager to learn how to drive. When Danny tries to teach D.J. how to drive, he makes her more nervous than she already is with the way he gives instructions, and by being overprotective. When Jesse tries to teach D.J. how to drive, Jesse makes her so nervous that she accidentally lays a huge scratch on Jesse''s car. When the guys finally realize how helpless they are making D.J. feel by complicating her efforts to learn how to drive, they find the strength to let go and help D.J. do her learning in peace. Meanwhile, Joey helps Michelle realize that she must stop annoying Stephanie whenever Stephanie has friends over to the house.', 24, '1992-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 21, 'Yours, Mine and Ours', 'Danny arrives home from work, and notices that the girls are in a bad mood because they haven''t had a good day. Neither has Joey, who would rather forget that day''s "Ranger Joe" episode. Danny suggests that they take a little time off from this stress and go out as a family for "Tanner Family Fun Night". Jesse and Becky stay at home with Nicky and Alex. Danny and Joey and the girls go to a pirate themed seafood restaurant, where D.J. is afraid she''ll be embarrassed in front of her classmate Shelly Phillips, who is also at the restaurant, and Joey and the girls seem to get a little more bitter, but they lighten up when they are forced to "walk the plank" -- right into a pit full of balls. Meanwhile, at home, Jesse and Becky are having a disagreement as to how Nicky and Alex should be raised, and complicating things is the fact that Alex is sick and has a fever for the first time in his life.', 23, '1992-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 22, 'The Trouble with Danny', 'It''s time for Spring cleaning, one of Danny''s favorite times of the year, but this year, Danny is overdoing it worse than ever. Everyone except for Danny gathers in D.J.''s bedroom for a meeting about this, and some hurtful things are said about Danny. What they don''t know is that Danny is in D.J.''s closet installing shelf paper, and Danny overheard the whole meeting. In order to make the family happy, Danny tries to be as sloppy as he can, but then slips up and mentions something that he heard Joey say during the meeting, and Danny is forced to admit that he was in D.J.''s closet at the time of the meeting. The family apologizes for hurting Danny, and Danny admits that he needs to find a balance between clean and dirty instead of going too far in either direction -- and so does Michelle.', 23, '1992-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 23, 'Five''s a Crowd', 'D.J.''s date with a heavy-metal band member rocks Danny, who leads a recon mission to the drive-in.', 23, '1992-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 24, 'Girls Will Be Boys', 'Michelle decides it''s better to be a boy after her friend is hassled for being friends with a girl.', 23, '1992-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 25, 'Captain Video (1)', 'Jesse fears his music career will never take off, while D.J. wants to take off for Barcelona for the summer.', 23, '1992-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 5), 26, 'Captain Video (2)', 'Efforts to turn Jesse''s ballad into a rap tune strike a sour note and turn him against the deal.', 24, '1992-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 1, 'Come Fly with Me', 'D.J. touches down from Spain with a new boyfriend, and Stephanie and Michelle take off on an accidental flight of fancy--to New Zealand.', 24, '1992-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 2, 'The Long Goodbye', 'Michelle''s best friend must move away; and Danny reexamines his long-distance relationship with Vicky.', 24, '1992-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 3, 'Road to Tokyo', 'Jesse and family fly to Tokyo when his single hits No. 1 in Japan, but stardom seems to eclipse his priorities.', 24, '1992-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 4, 'Radio Days', 'When Jesse and Joey exchange insults on a radio show, they''re a hit and the station offers them their own program.', 24, '1992-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 5, 'Lovers and Other Tanners', 'Love is in the air for D.J., but Danny doesn''t like it.', 24, '1992-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 6, 'Educating Jesse', 'Jesse reveals that he''s a high-school dropout, but he wants to drop back in to get his diploma.', 24, '1992-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 7, 'Trouble in Twin Town', 'Rebecca''s arrogant cousin Dick, his wife and their daughters visit for a twins convention.', 24, '1992-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 8, 'The Play''s the Thing', 'When Jesse and Joey cast another kid as the Yankee Doodle Boy in a school show, Michelle becomes a cranky doodle girl.', 24, '1992-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 9, 'Nice Guys Finish First', 'Joey can''t get fired up for a hockey match after being taunted about a humbling experience on the ice.', 24, '1992-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 10, 'I''m Not D.J.', 'Peer pressure dictates that Stephanie must have her ears pierced, but Danny disagrees.', 24, '1992-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 11, 'Designing Mothers', 'Danny thinks Vicky''s mother wants to redesign his life; Joey and Jesse fear the new station manager may oust them.', 24, '1992-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 12, 'A Very Tanner Christmas', 'Christmas brings a breakup between Steve and D.J., and a lesson in the meaning of the season for Stephanie and Michelle.', 24, '1992-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 13, 'The Dating Game', 'Stephanie is on an emotional roller coaster over her first "date"; Joey''s loopy about having Alison over for dinner.', 24, '1993-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 14, 'Birthday Blues', 'Preoccupied with her and Steve''s anniversary, D.J. forgets Kimmy''s birthday, but Kimmy thinks a party''s in the works.', 24, '1993-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 15, 'Be True to Your Preschool', 'After Jesse lies about the twins'' talents on their preschool application, he has to think fast when the school shows an interest in the boys.', 24, '1993-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 16, 'The Heartbreak Kid', 'Michelle isn''t kidding when she proposes to Steve.', 24, '1993-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 17, 'Silence Is Not Golden', 'A boy swears Stephanie to silence about the fact that his father beats him.', 23, '1993-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 18, 'Please Don''t Touch the Dinosaur', 'Michelle makes no bones about choosing Jesse''s "fun" group over Danny''s on a trip to a dinosaur museum.', 24, '1993-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 19, 'Subterranean Graduation Blues', 'Things are rolling for Jesse until he gets stuck in the subway en route to his graduation--where he''s supposed to give the commencement address.', 24, '1993-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 20, 'Grand Gift Auto', 'Joey buys D.J. what he thinks is a really hot car for her birthday, not knowing it''s really hot.', 24, '1993-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 21, 'Room for One More?', 'Jesse wants another baby, but it''s a circus when he tries to prove he can juggle all his responsibilities and still handle one more.', 24, '1993-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 22, 'Prom Night', 'D.J.''s hopes for a fairy-tale prom night take a dramatic turn when Steve and his old girlfriend are crowned prom king and queen.', 24, '1993-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 23, 'The House Meets the Mouse (1)', 'Jesse''s band gets a gig playing at Disney World, and the family joins him.', 23, '1993-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 6), 24, 'The House Meets the Mouse (2)', 'The search continues for Disney World''s Princess for the Day, Michelle, while Danny gets ready to pop the question to Vicky.', 24, '1993-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 1, 'It Was a Dark and Stormy Night', 'D.J., Stephanie, Michelle, and Kimmy have returned home from a summer at Camp Lakota. Michelle tells Jesse that she no longer wants Jesse to call her "Munchkin", which Jesse has affectionately called her for years, because everyone at camp gave her the nickname "Trailmix", and she likes it. Danny feels hurt when D.J., Stephanie, and Michelle act like they didn''t miss the family one bit while they were at Camp Lakota. Upstairs, Stephanie and D.J. are surprised that Michelle has brought home a rabbit named Gilbert.', 24, '1993-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 2, 'The Apartment', 'Danny is shocked when D.J. tells him that her classmate Kathy Santoni is pregnant, and Danny feels uncomfortable when D.J. says she''s going to go to Steve''s new apartment to watch TV with him. Danny tells D.J. to be home by 11:00pm, which is her curfew. Danny gives D.J. permission to go to Steve''s apartment because he is told that Kimmy will be with D.J. at the apartment. What Danny doesn''t know is that circumstances have prevented Kimmy from being able to be with D.J. the whole time at Steve''s apartment. Later, it''s past midnight, and D.J. is still not home yet. Danny calls Kimmy, who gives him the address of Steve''s new apartment. A few minutes later, Danny knocks on Steve''s door, but there is no answer because Steve and D.J. are asleep beside each other on the couch. They fell asleep while watching the Arnold Schwarzenegger movie "The Terminator".', 24, '1993-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 3, 'Wrong-Way Tanner', 'Like Stephanie and D.J. once did, Michelle becomes a member of a local soccer team that Joey is now the head coach of. Danny and Jesse are overly excited about it, and in her first game, Michelle kicks the ball the wrong way and scores the winning goal for the opposing team. This has Michelle wanting to leave the team because she feels like she can no longer face her teammates, who chewed her out about costing them a game. Joey explains to Jesse and Danny that if they would have let Joey do his job as head coach and not put so much pressure on Michelle and made her so nervous, Michelle would have felt more comfortable in the game and maybe a little less prone to mistakes. As this is going on, Stephanie is videotaping a day in the life of the Tanners as a project for school.', 24, '1993-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 4, 'Tough Love', 'Nicky and Alex are having behavior problems that are adversely affecting the lives of those who love them. Nicky and Alex even destroy Michelle''s science project, which was a model of the nine planets. An angry Michelle lets on that Jesse and Becky should start making Nicky and Alex behave, so Jesse takes the twins to their bedroom for their first punishment, which is a timeout, meaning that they''re grounded to their room for a portion of the day. After doing this, Jesse feels guilty when the twins call him "mean daddy" for this, and a "mean daddy" is the last thing Jesse wants to be. Becky reassures Jesse that the twins obviously didn''t know that what they said to Jesse was hurtful. Meanwhile, Danny, who fears that the girls are too finicky to like Vicky''s cooking, bribes Stephanie and Michelle into giving Vicky compliments at the dinner table so they won''t make Vicky feel hurt.', 24, '1993-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 5, 'Fast Friends', 'For two weeks, Stephanie has been in 6th grade at DiMaggio Junior High School. Her old friends all attend different schools now, and Stephanie is desperate to make new friends, and she meets a group of 7th graders led by Gia Mahan, and they want Stephanie to smoke with them. That''s why Stephanie is not sure that these girls are her type of friends. Meanwhile, Jesse and Joey are having a special on their radio show, "Rush Hour Renegades", where they have brought in D.J., Steve, and Kimmy to talk to teenagers who call in to seek advice.', 24, '1993-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 6, 'Smash Club: The Next Generation', 'Jesse is shocked to discover that he has inherited the Smash Club from Buzz Markel. Jesse and the Rippers played gigs at the Smash Club more than virtually any other band, but the place has been closed down for the past couple of years. Jesse will become the owner only if he can reopen the club. If he can''t do it, the club will be turned into a parking lot. After receiving some ideas from D.J., Kimmy, Stephanie, and Steve, Jesse decides to reopen the Smash Club as a place where anyone can come to hear cool new music from new bands -- no age limit like the Smash Club had before, when people had to be 21 or older to get in. Jesse''s plans also state that no alcoholic beverages will be served in "The New Smash Club". Jesse and Joey head to the Smash Club, which is, of course, a mess.', 24, '1993-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 7, 'High Anxiety', 'Michelle, who is in 2nd grade, is growing up faster than Danny is accepting. Danny still treats Michelle like a baby, and Michelle has had enough of that, so even though she doesn''t want to have to get mad at Danny, she angrily tells Danny to stop treating her like a baby. Danny realizes that he needs to let go and start letting his kids grow up as they get older, so Danny talks to Michelle and promises to stop treating Michelle like a baby. Meanwhile, Jesse is overwhelmed by the fact that he has so many decisions to make about needs for the Smash Club, which he hasn''t opened yet.', 24, '1993-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 8, 'Another Opening, Another No Show', 'Jesse is now ready to reopen the Smash Club, and Danny, Joey, Becky, D.J., Kimmy, Stephanie, and Michelle will be helping Jesse at the club on this special night. Jesse wants absolutely nothing to go wrong, so he starts acting cranky around everyone. The opening could be a disaster when Jesse ends up locked in the Smash Club''s storage room with Kimmy. As Danny, Joey, Becky, and the girls run the Smash Club the best they can while they think Jesse and Kimmy haven''t showed up yet, Kimmy helps Jesse realize that Jesse was wrong to be cranky around everyone, and this teaches Jesse that if he wants to be a good boss, then he shouldn''t treat his employees the way he treated Danny, Joey, Becky, and the girls. Jesse and Kimmy free themselves from the storage room, and the club has a fairly successful grand opening. At home, Jesse apologizes for the way he treated Kimmy and the family.', 24, '1993-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 9, 'The Day of the Rhino', 'Michelle and her friends are angry at their favorite TV character "Rigby the Rhino". After seeing a commercial advertising a big, plush "action Rigby", Michelle and each of her friends order one, but instead of receiving a big, plush Rigby, they each receive a tiny plastic Rigby -- a clear case of false advertisement. Joey takes Michelle and her friends, along with their tiny plastic Rigbys, to Bayview Mall, where Rigby is making an appearance, and there is a large group of kids and their parents who are there to see Rigby. Joey, Michelle, and her friends don''t want these kids to be swindled by a commercial that was a lie, so they show their tiny plastic Rigbys to these kids and warn these kids that the commercial was a lie.', 24, '1993-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 10, 'The Prying Game', 'While at a local public library, Stephanie sees an attractive blonde haired girl planting a kiss on Steve''s cheek. Stephanie doesn''t want to say anything to D.J. until she''s sure Steve is seeing another girl. That''s why Stephanie and Kimmy break into Steve''s apartment, so they can investigate. Stephanie and Kimmy are nailed when D.J. and Steve show up. The girl who kissed Steve on the cheek was his cousin Edie, who kissed him out of friendship, proving that Steve is not seeing someone else. D.J. goes ballistic and tells a stunned Stephanie to stay out of her life, because D.J. feels that by breaking into Steve''s apartment, Stephanie has reached a new low when it comes to invading D.J.''s privacy.', 24, '1993-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 11, 'The Bicycle Thief', 'Michelle tells the family that her bicycle is missing, so the family starts a search for it. Later on, Danny, Jesse, and Joey have each brought home a bicycle that looks like Michelle''s, but it turns out that none of the three bikes belong to Michelle. At the same time, the disappearances of the three bikes is being investigated by Crime Catchers, a neighborhood watch program led by Mrs. Carruthers, who works at the school Michelle goes to. It turns out that Michelle had forgotten that she left her bike at her friend Derek Boyd''s house.', 24, '1993-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 12, 'Support Your Local Parents', 'In playgroups, 2-year-old Nicky and Alex refuse to play with anyone except for each other. Jesse is too stubborn to admit that this is a problem, until he and Becky attend a support group for parents of twins. After the visit with the support group, Jesse later admits that he didn''t want to acknowledge the problem because he was afraid that he may discover that he''s somehow the cause of it and he doesn''t want to do anything to mess up Nicky and Alex''s lives, but Jesse was proven wrong at the support group. Meanwhile, D.J. gets a traffic ticket for "obstruction of vision" when Kimmy decides to air out her socks by sticking her feet out the window of the car. D.J. wants to keep the ticket a secret from Danny because she''s afraid Danny will never let her drive the car again. Stephanie and Michelle use this information to their advantage to force D.J. to let them borrow clothes from her.', 24, '1993-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 13, 'The Perfect Couple', 'Joey is the host of the test pilot episode of a game show called "The Perfect Couple", a show that would remind you of the Newlywed Game. The three couples on the game are a dating couple (D.J. and Steve), an engaged couple (Danny and Vicky), and a married couple (Jesse and Becky). While everyone is out, doing the new show, Stephanie and Michelle have their work cut out for them as they babysit Nicky and Alex. Vicky is out of town, so she can''t be on the show with Danny, and Estelle, the woman who substitutes for Vicky, seems to know Danny all too well, and as a result of the show, D.J. thinks she and Steve don''t know each other well enough. When Vicky shows up at the studio that "The Perfect Couple" was taped in, she tells Danny that her lifelong dream of being a network news anchor has come true -- she has accepted a job as a network news anchor in New York City.', 24, '1993-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 14, 'Is It True About Stephanie?', 'Stephanie''s classmate Jamie, who plays guitar with some friends in a band called "Human Pudding", asks Stephanie out on a date to the Smash Club, and Stephanie excitedly agrees to go to the Smash Club with Jamie. Stephanie''s classmate Gia Mahan is not as excited, because Gia also has her eyes on Jamie, and she''s not about to let Stephanie have him that easily. In order to make Jamie cancel his date with Stephanie, Gia spreads a false rumor at school that Stephanie wouldn''t have any dates if she didn''t pay guys to date her. Gia''s plan works, and Jamie breaks the date, so Stephanie gets even with Gia by hanging up a blowup of Gia''s awful report card in the hallway. This makes Gia feel even more hurt than Stephanie felt when Gia spread the false rumor about Stephanie. Noticing how hurt Gia feels makes Stephanie feel guilty.', 24, '1994-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 15, 'The Test', 'It''s the day before D.J.''s SAT, and she''s so nervous about it that when she goes to sleep that night, she has a nightmare about it in which everything possible goes wrong: D.J. oversleeps on the day of the test and is late, and Ms. Twitchel, a neighbor D.J. yelled at, is the teacher, Danny and Becky come by to broadcast the test live, and with too many last-minute changes to the test, D.J. fails the test with not even her name written correctly. When D.J. wakes up from this nightmare, Danny convinces her that she doesn''t have to be so nervous about the SAT, and her teacher turns out to be a much friendlier teacher named Mrs. Moffatt.', 24, '1994-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 16, 'Joey''s Funny Valentine', 'After a couple of weeks of dating her, Joey introduces his new girlfriend Roxy Martin to the family. Roxy is a comedian, like Joey. Roxy is nervous about meeting the family, and as a result, she can''t think of anything funny to say. After Roxy meets the family, Jesse schedules Roxy to perform on comedy night at the Smash Club, where Roxy adds insulting jokes about the family to her comedy routine. At home, after returning Little Sid to its owner Big Sid, the girls are given a choice of one item from Big Sid''s store for free, and this leads to arguments between the girls, who each want a different item. D.J. wants to get a big-screen TV, and Stephanie wants to get a Karaoke machine. The decisive vote is left up to Michelle.', 24, '1994-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 17, 'The Last Dance', 'In a special episode: Jesse''s grandfather Iorgos "Papouli" Katsopolis is back from Greece for another visit. The family finds it pleasant to have Papouli around. One morning during Papouli''s visit, everyone goes to wake him up after Michelle has gone to school -- only to discover that Papouli has died in his sleep. His death was caused by heart failure. When Michelle arrives home from school later that day, Danny tells her that Papouli has died. Michelle is devastated, and it turns out that only one person can comfort Michelle, and that person is Jesse, who is taking it just as hard. Kimmy and D.J. argue over a pair of sunglasses, but Papouli''s death helps them realize that friendship is too important for them to argue over a pair of sunglasses.', 24, '1994-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 18, 'Kissing Cousins', 'Jesse has returned home from Greece, where he attended Papouli''s funeral, and he has brought his cousin Stavros home with him. What Jesse doesn''t know is that Stavros is a womanizing con artist. Stavros (also played by John Stamos) swindles Joey out of a watch and $20, makes a pass at Becky, gets Danny a $65 parking ticket, and Stavros also makes D.J. pay for an awful-smelling goat pizza that Stavros had the money for all along. When everyone tries to tell Jesse what kind of man Stavros is, Jesse refuses to believe them. The Smash Club is the setting for Stavros''s latest scam, in which he says that a severe mudslide has occurred in his hometown in Greece and he is raising money at the Smash Club for his hometown''s recovery from the mudslide. Becky and the girls discover that there was no mudslide, and that Stavros plans to take the money -- and Becky -- on an airplane flight to Florida with him.', 24, '1994-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 19, 'Love on the Rocks', 'Steve goes to a seminar in Los Angeles with his film class, and D.J. doesn''t seem as excited as Steve is. A few days later, D.J. tells Becky that she''s worried about her relationship with Steve. That night, Steve calls from Los Angeles, and he sounds like he''s having a blast. D.J. goes mountain climbing on Eagle Mountain with Kimmy and her boyfriend Keanu. A few days later, Steve returns to San Francisco from Los Angeles, and he thinks D.J. is acting like she didn''t miss him. After an argument with D.J., Steve goes home. That night, D.J. tells Danny that it feels like she and Steve are not on the same wavelength anymore. On the next day, D.J. takes Steve to Eagle Mountain, where they have a long talk, and they decide to break up because they are no longer as passionate about their relationship as they once were.', 24, '1994-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 20, 'Michelle a la Carte', 'After being insulted by a boy named Kenny, Michelle decides that she wants to be in the annual downhill soapbox derby championship, and she gets Becky to help her build a soapbox car. Michelle feels like dropping out of the race when she hears comments about how girls shouldn''t be in the race. Becky talks Michelle into not quitting, and the elimination heats begin. In the final race, it''s Michelle against Kenny, who has never lost a race -- and Kenny gets what he deserves when Michelle races past him and wins the championship. Meanwhile, Stephanie gives Joey ballet lessons as a way to help Joey improve his skills in ice hockey, and Joey ends up accidentally ripping the seat of his pants.', 24, '1994-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 21, 'Be Your Own Best Friend', 'In Michelle''s class on parent volunteer day, a new student is introduced. It''s Michelle''s best friend Teddy, who moved to Texas a little more than a year ago. Michelle is thrilled that Teddy and his family have moved back to San Francisco. When Michelle tries to be a best friend to both Teddy and Denise, she ends up with no friend at all, until Danny helps Michelle, Teddy, and Denise realize that it''s possible for someone to have two best friends. Meanwhile, on "Rush Hour Renegades", Joey and his girlfriend Roxy Martin make Jesse feel like the odd man out by not letting Jesse get a word in edgewise on the show.', 24, '1994-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 22, 'A Date with Fate', 'For the first time since Danny and Vicky''s breakup and D.J. and Steve''s breakup, D.J. and Danny are both back in the dating pool. Stephanie has arranged a blind date for D.J., and Danny takes Becky''s suggestion to date a TV camera operator named Bernadette. But then Danny and D.J. inadvertently go to the same restaurant with their dates, and D.J.''s and Danny''s partners take off together. D.J. then meets a friendly waiter, and helping an old lady in the restaurant pays off for Danny. Meanwhile, Jesse prepares Nicky and Alex to celebrate Mother''s Day, and Nicky and Alex start celebrating a day early.', 24, '1994-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 23, 'Too Little Richard Too Late', 'Michelle''s favorite part of school, the arts program, has been cancelled because of budget cuts. At a PTA meeting, Danny and Joey stand up for the arts program, and Danny nominates Joey for PTA president. His opponent, Mrs. Carruthers, won''t give up without a fight, but with the help of Denise''s uncle Richard, Joey becomes the co-president of the PTA with Mrs. Carruthers, and they decide that the arts program, which is a favorite among a lot of the students, should be brought back to the school.', 24, '1994-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 7), 24, 'A House Divided', 'When the family starts complaining that there is not enough room in the house for 9 people, they consider finding other places to live. Millionaire industrialist Lou Bond shows up wanting to buy the house from Danny, because Mr. Bond used to live in the house before the Tanners moved in years ago, and it''s the house that Mr. Bond grew up in. Michelle is the only one who is against the idea of selling the house and moving out of it, so she tries everything to stop the sale from happening. With the help of her friends, Michelle succeeds. Everyone realizes that this house has been a part of the family for years. It''s more than just walls and a roof -- it''s their lives, where they have had so many good times together. With this to think about, Danny decides to not sell the house.', 24, '1994-05-17');
