INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 2, 'Breaking Away', 'The twins may be ready for preschool, but Jesse isn''t ready to let them go; Stephanie asserts herself by not cleaning her room.', 23, '1994-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 3, 'Making Out Is Hard to Do', 'Danny discovers Stephanie''s lied to him and gone to an unsupervised party; Barry Williams records a hit with Jesse''s former band.', 23, '1994-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 4, 'I''ve Got a Secret', 'Michelle lets Danny know she''s in a secret club, but she''s bounced when he spills the beans.', 23, '1994-10-18');
