INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 6, 'You Pet It, You Bought It', 'Michelle buys a donkey with the money she makes selling lemonade.', 23, '1994-11-01');
