INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 8, 'Claire and Present Danger', 'Stephanie and Gia are pleased when Danny begins dating Gia''s mom--but Michelle''s not.', 23, '1994-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 9, 'Stephanie''s Wild Ride', 'Stephanie takes a wild ride with some older boys, and D.J. is the only one who knows.', 22, '1994-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 10, 'Under the Influence', 'D.J. saves Kimmy when she gets drunk at a fraternity party, but Kimmy blames D.J. for ruining her fun.', 23, '1994-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 11, 'Arrest Ye Merry Gentlemen', 'A novelty-store owner refuses to exchange Michelle''s gift for Danny on Christmas Eve.', 23, '1994-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 12, 'D.J.''s Choice', 'D.J. faces a dilemma when Nelson and Viper both vie for her affection.', 23, '1995-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 13, 'The Producer', 'When Rebecca is named the producer of the morning show, it only produces bitterness in Danny.', 23, '1995-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 14, 'Super Bowl Fun Day', 'Michelle and her friends demand that Joey and Jesse take them to the museum on Super Bowl Sunday.', 23, '1995-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 15, 'My Left and Right Foot', 'Michelle frets over the size of her feet.', 23, '1995-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 16, 'Air Jesse', 'When Jesse proves to be a hapless hoopster, he gets some pointers from an all-time great: Kareem Abdul-Jabbar.', 23, '1995-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 17, 'Dateless in San Francisco', 'As Valentine''s Day nears, Rebecca thinks Jesse''s lost his romantic spark; and Joey has a secret admirer.', 23, '1995-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 18, 'We Got the Beat', 'Stephanie and friends form a band for a talent contest, but decide they don''t need Jesse''s help.', 23, '1995-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 19, 'Taking the Plunge', 'Kimmy decides to marry her plumber boyfriend after her college aspirations go down the drain.', 23, '1995-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 20, 'Up on the Roof', 'D.J. plays a prank on the principal when she gets his convertible put on the school roof--but the caper backfires.', 23, '1995-03-14');
