INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092359')) AND numero_temporada = 8), 22, 'All Stood Up', 'Stephanie is heartbroken when she''s stood up. Meanwhile, a doctor orders Jesse to reduce his stress level.', 23, '1995-04-04');
