INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0092400', 'Married... with Children', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0169394'), 'SERIE', 'Al is the quintessential working class dad. Peggy, his wife, always wants more from him. With their children, they go through the highs and lows of ordinary life.', '1987-01-01', 'https://m.media-amazon.com/images/M/MV5BN2M5MjIwY2MtNmRhZC00MjFlLWEwM2ItODFmNjEyZmMzNjFlXkEyXkFqcGc@._V1_.jpg');
