INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 1, 'Pilot', 'In this pilot we meet Al and Peg Bundy, a very dysfunctional Chicago family. In the pilot, Al and Peg, who have no friends, meet their new neighbors Steve and Marcy Rhoades. Steve and Marcy are a very happily married couple until they learn from the Bundys.', 22, '1987-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 2, 'Thinnergy', 'Marcy gives Peggy the book "Thinnergy", which is a book about health. Very inspired by the book, Peggy goes on a diet and tries to convince the family to join in, but they refuse.   When the diet makes Peggy really annoying, Steve convinces Al to join the diet, and persuades Peggy to quit.', 22, '1987-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 3, 'But I Didn''t Shoot the Deputy', 'The Bundys and the Rhoades'' hear of crime in the neighborhood. Al buys a gun, and the Rhoades'' buy a dog. Al hears a noise and accidentally kills the dog, thinking it was a burglar.', 22, '1987-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 4, 'Whose Room Is It Anyway', 'Steve and Marcy plan on adding another room to their house with their tax refund. Al tries to coax Steve into building a pool room, while Peg and Marcy decide on an exercise room. Who will win?', 22, '1987-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 5, 'Have You Driven a Ford Lately?', 'Al and Steve draw closer together when they try to restore a 1965 Mustang. Peg and Marcy on the other hand can''t stop from despising their husbands.', 22, '1987-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 6, 'Sixteen Years and What Do You Get', 'Al is unable to purchase a gift for Peg on their 16th wedding anniversary as his credit card seemed to be maxed out.', 22, '1987-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 7, 'Married... Without Children', 'In an attempt to spice up their marriage, Al and Peg check in at a hotel, while Steve and Marcy babysit Bud and Kelly. The Rhoades'' learn that babysitting the young Bundys is a mistake when the kids turn their home into a rioting party.', 22, '1987-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 8, 'The Poker Game', 'Al invites Steve to play poker, but Steve ends up losing his paycheck to Al. Afraid to tell Marcy the truth, Steve tries to convince Peggy to give him the check back.', 22, '1987-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 9, 'Peggy Sue Got Work', 'Peg wants a VCR and Al won''t get it for her. She ends up working at a department store for money, which disrupts her and Al''s relationship.', 22, '1987-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 10, 'Al Loses His Cherry', 'Al spends some time at Luke Ventura''s apartment after running out from a fight with Peg.', 22, '1987-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 11, 'Nightmare on Al''s Street', 'Steve is away on business and Marcy is having sexual fantasies with Al involuntarily. Marcy becomes so disgusted and she tells Peg, who tries to give her tips on how to avoid them.', 22, '1987-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 12, 'Where''s the Boss', 'After thinking that his boss is dead, Al tries to find another job unless he gets some appreciation and credit for his work.', 22, '1987-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 1), 13, 'Johnny Be Gone', 'Al and Peggy delay going to a closing of their favorite hamburger joint when Bud and Kelly run into a problem. Meanwhile, Steve and Marcy prepare a party for some executive big-shots.', 22, '1987-06-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 2), 1, 'Poppy''s by the Tree (1)', 'In the second season opener, the Bundys go to a sleazy, dumpy motel in Dumpwater Florida. Trouble head their way when an axe murderer, who hates tourists, arrives.', 22, '1987-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 2), 2, 'Poppy''s by the Tree (2)', 'Peg is kidnapped by the axe murderer and it''s up to Al to save her.', 22, '1987-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 2), 3, 'If I Were a Rich Man', 'Al and Steve visit the vault at Steve''s bank and the next day, one million dollars is reported missing. Peg and the kids hear about it and worship Al thinking that he stole the money and that they are now a wealthy family.', 22, '1987-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 2), 4, 'Buck Can Do It', 'One of the Bundys neighbors threaten to sue when Buck the dog mates with their dog, and asks the Bundys to neuter Buck, which Al refuses to do.', 22, '1987-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0092400')) AND numero_temporada = 2), 5, 'Girls Just Want to Have Fun (1)', 'Marcy and Steve have a fight, which leads to Marcy joining Peggy and her friends going to a strip club, where Marcy accidentally loses her wedding ring ... down a stripper''s pants.', 22, '1987-10-18');
