INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 1), 3, 'D-I-V-O-R-C-E', 'Jackie babysits while Roseanne and Dan go out to a formal restaurant dinner -- at which they see a recently divorced friend.', 23, '1988-11-01');
