INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 1, 'Two Down, One to Go', 'Roseanne is suffering from empty-nest syndrome as Darlene heads for school. But after Darlene gets settled into her dorm, the two have a revealing mother-daughter chat, and Roseanne returns home with a plan.', 23, '1993-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 2, 'The Mommy''s Curse', 'Brutally honest Roseanne suffers the consequences after telling Bev that she''s had her fill of her at the Lunch Box. Meanwhile, Jackie jumps back into the dating arena.', 23, '1993-09-21');
