INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 4, 'A Stash from the Past', 'Foreman Dan feels lower than low for getting tough with his employees at work, while Roseanne lectures David for getting high after she finds a stash of pot in the house -- then realizes it is hers from decades ago.', 23, '1993-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 5, 'Be My Baby', 'After months of trying to get pregnant, Roseanne learns that Jackie is expecting -- and Fred is the unknowing father.', 23, '1993-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 6, 'Halloween V', 'Halloween at the diner becomes complicated when Nancy complains that Dan doesn''t like her, and Roseanne discovers that Darlene and David are each dating others.', 23, '1993-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 7, 'Homeward Bound', 'Darlene visits, making David realize how much he misses her; Roseanne urges Dan to have a man-to-man chat with D. J. after they discover he''s been spending too much time behind locked doors.', 23, '1993-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 8, 'Guilt by Imagination', 'Dan has a hard time concealing the fact that he had lunch with an old flame.', 23, '1993-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 9, 'Homecoming', 'Becky and Mark return home for Dan''s high school football team''s 20th anniversary party. It soon becomes apparent that there''s trouble in paradise, so Roseanne schemes to break them up.', 23, '1993-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 10, 'Thanksgiving ''93', 'The Connors'' dysfunctional-family Thanksgiving finds Becky preparing the bird, Dan and Mark duking it out, and an absent-minded Nana Mary revealing Bev''s secret about her marriage.', 23, '1993-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 11, 'The Driver''s Seat', 'Leon convinces Jackie and Nancy to open the restaurant for breakfast, causing Roseanne to fear he is planning to force her out. Roseanne''s car is stolen -- by D.J., and her violent reaction frightens her that she may repeat the pattern of her own abuse as a child, while Dan blames her anger on work stress.', 23, '1993-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 12, 'White Trash Christmas', 'Roseanne and Dan snub the neighborhood association by putting up gaudy Xmas decorations, and become furious with Becky when she gives the check they have given her for college to Mark and takes a job as a waitress in a tacky bar.', 23, '1993-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 13, 'Suck Up Or Shut Up', 'Roseanne joins a women''s club in hopes of establishing useful contacts, leaving D.J. high and dry with a weird classmate whose mother also belongs. Meanwhile, Mark drops a bombshell on Becky when Dan discovers that he has dropped out of school.', 23, '1994-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 14, 'Busted', 'Dan and Roseanne try to talk Mark into coming back to Becky; meanwhile, Roseanne finds out that David is living with Darlene and heads for Chicago to confront them.', 23, '1994-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 15, 'David vs Goliath', 'Guilt and Roseanne''s slavedriving push David to confess to Dan that he was living with Darlene in Chicago, and Dan throws him out; Jackie refuses to take money for the baby from Fred; Roseanne and Becky try to pressure Dan to hire Mark.', 23, '1994-02-01');
