INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 17, 'Don''t Make Room for Daddy', 'Roseanne becomes involved in a family feud as Fred sues Jackie for custody of their unborn child; Mark and D.J. tease David for being unmanly.', 23, '1994-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 18, 'Don''t Ask, Don''t Tell', 'Roseanne is the life of the party at a gay bar, until Nancy''s new girlfriend plants a disturbing kiss on her; meanwhile, back home, Becky''s old flame gives Mark reason to distrust Becky.', 23, '1994-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 19, 'Labor Day', 'Jackie is due to give birth, and has to choose between Fred and Roseanne to accompany her to the delivery room.', 23, '1994-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 20, 'Past Imperfect', 'When Dan''s father misses an alimony payment, Dan and Roseanne argue about covering it; meanwhile, Fred becomes concerned about Jackie''s sexual past.', 23, '1994-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 21, 'Lies My Father Told Me', 'Roseanne helps Dan understand his dad''s lying about his mom''s mental state.', 23, '1994-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 22, 'I Pray the Lord My Stove to Keep', 'Darlene discovers that D.J. has been sneaking off after to school to attend church; D.J. gives Roseanne a hard time about morals when she accepts a mistaken delivery of a second stove at the diner.', 23, '1994-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 23, 'Body by Jake', 'Bev moves in after breaking her pelvis at the retirement home, blaming Dan for not safeproofing her shower; then Roseanne discovers that it happened while Bev and Jake were having sex.', 23, '1994-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 24, 'Isn''t It Romantic?', 'Fred asks Roseanne how to propose to Jackie, then uses hints from Jackie''s favourite soap opera; an enraged Roseanne demands romance from Dan, then turns to fantasy; Mark and David struggle with the concepts of feminism.', 23, '1994-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 6), 25, 'Altar Egos', 'Egos clash when Jackie and Fred can''t make a decision about their marriage. Fred is having what Dan calls the moment of clarity, a case of the jitters that affects some men just before the big day. But what''s really bothering Fred is his belief that Jackie has feelings for someone she sees almost every day and whom she is always asking to come over and fix stuff, none other than Dan.', 23, '1994-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')), 7, 'Season 7', NULL);
