INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 2, 'Two for One', 'Dan is anxious at the thought of Roseanne having another child; Roseanne is upset to discover that Darlene is seeing a college student and that David has accepted it.', 23, '1994-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 3, 'Snoop Davey Dave', 'Smarting over being dumped by Darlene, David tells her parents that she has been experimenting with drugs at college.', 23, '1994-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 4, 'Girl Talk', 'Dan, Mark, and Fred indulge in a little "girl talk" and are horrified to discover what their respective wives have told each other about the men''s sexual preferences and dysfunctions.', 23, '1994-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 5, 'Sleeper', 'David has to move in with D.J. when the basement is flooded; David hesitantly admits to Becky that he had an erotic dream; she assumes it was about her; D.J. tells Mark, who tries to beat up David; then David confesses the dream was really about Roseanne.', 23, '1994-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 6, 'Skeleton in the Closet', 'Leon outdoes himself hosting a Halloween soiree with the Lunch Box clan and a bevy of his gay friends, many of whom seem to know Fred intimately.  Meanwhile, Jackie and Roseanne visit Bev''s hairdresser and become convinced that she wears a wig.', 23, '1994-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 7, 'Follow the Son', 'D.J. wants out of his busboy job at the Lunch Box, and David wants to put the kibosh on Darlene''s moving in with her new squeeze Jimmy -- who misinterprets David''s obsessive interest in him.', 23, '1994-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 8, 'Punch and Jimmy', 'An impromptu visit to Darlene''s apartment gives Roseanne a clear picture of what Jimmy is all about. Meanwhile at home, Dan finds himself a bit fuzzy on parenting skills: D.J. is being beaten up by a bully, and taking it out on David.', 23, '1994-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 9, 'White Men Can''t Kiss', 'D.J.''s refusal to kiss a black student in the school play brings Dan and Roseanne face to face with their own racial prejudices.', 23, '1994-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 10, 'Thanksgiving ''94', 'Thanksgiving is a real turkey at the Conner household when Roseanne gets alarming medical news she can''t confirm with the pre-natal clinic, and Nana Mary arrives with a feeble husband on her arm -- then upsets Bev by discussing the two abortions Nana Mary had years ago.', 23, '1994-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 11, 'Maybe Baby', 'Roseanne is warring with Dan and in a dither over her upcoming second medical test, which may require a difficult decision -- one she believes is hers alone to make.', 23, '1994-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 12, 'The Parenting Trap', 'Dan takes the bull by the horns after he learns that D.J. isn''t performing well in school. Meanwhile, to Roseanne''s horror, Darlene seems genuinely impressed with David''s dimwitted new girlfriend.', 23, '1994-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 13, 'Rear Window', 'The Connors get an eyeful from a new elderly neighbor couple who enjoy nudity in their home but are all too visible from Roseanne and Dan''s bedroom. Meanwhile, Mark is so convinced that he is losing Becky to David that he asks Darlene for help.', 23, '1995-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 14, 'My Name is Bev', 'After Bev is charged with drunken driving, Jackie and Roseanne accompany her to a compulsory AA seminar.  Her new resolve of sobriety on Super Bowl Sunday wreaks havoc with Dan''s keg party.', 23, '1995-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 15, 'Bed and Bored', 'Roseanne feigns illness to get some rest, but grows bored instead; Jackie confronts Bev about having been a rotten mother to her.', 23, '1995-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 16, 'Sisters', 'Sibling rivalries fester when Jackie complains to Roseanne about D.J.''s annoying visits, and Roseanne lures Darlene home.', 23, '1995-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 17, 'Lost Youth', 'Jealousies mount between David and Mark over vulnerable Lunch Box waitress Stacy, whom David asks to pose for a wall mural in the diner; Jackie complains to Fred that their lovemaking needs a shot in the arm, even though he likes it just the way it is.', 23, '1995-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 18, 'Single Married Female', 'In Roseanne''s absence, Dan gets unexpected advice from David after discovering a scandalous secret concerning Jackie.', 23, '1995-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 19, 'The Clip Show: All About Rosey (1)', 'Youngsters Roseanne and Jackie visit a fortuneteller who gives them a peek into their futures via her crystal ball. In the future, Jackie takes an adult, autistic D.J. to see a psychiatrist.', 23, '1995-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 20, 'The Clip Show: All About Rosey (2)', 'The "Sitcom Moms Welcome Wagon" visits Roseanne.', 23, '1995-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 21, 'Husbands and Wives', 'Just as Fred gets ready to cave in and return home, Roseanne comes to regret sticking her nose in where it doesn''t belong by trying to reunite him with Jackie.', 23, '1995-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 22, 'Happy Trailers', 'Becky and Mark finally leave the Conner nest to move into a tacky trailer park, but when Roseanne and Dan try to help out financially, their offers are met with a wall of resistance. Meanwhile, a tipsy neighbor drops by to put out the trailer park welcome mat.', 23, '1995-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 23, 'The Blaming of the Shrew', 'Dan puts his foot down when D.J. allows a pushy vixen to boss him around; and Jackie gets a few things off her chest when she and Fred visit a therapist to save their marriage.', 23, '1995-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 24, 'The Birds and the Frozen Bees', 'Roseanne has a bee in her bonnet over the possibility that David may like another girl better than Darlene -- who risks losing him if she doesn''t take her mom''s advice and act fast.', 23, '1995-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 25, 'Couch Potatoes', 'Because the Conners have been selected as a Neilsen family, Roseanne decrees that their household viewing habits must change.', 23, '1995-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 7), 26, 'Sherwood Schwartz: A Loving Tribute', 'A Gilligan''s Island fantasy plays into the season finale, which finds Dan torn between pleasing Roseanne and building a boat for a future adventure. Dan becomes the Skipper, Leon becomes Mr. Howell, Bev becomes Mrs. Howell, Jackie becomes Gilligan, Darlene becomes Maryanne, and Roseanne becomes Ginger.', 23, '1995-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 1, 'Shower the People You Love with Stuff', 'Hostesses Becky and Darlene disagree over Roseanne''s baby shower.', 23, '1995-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 2, 'Let Them Eat Junk', 'Jackie chews out Roseanne for feeding baby Andy junk food; D.J. spends a picture-perfect day observing what makes Dan tick after Dan becomes upset to discover D.J.''s only photo of him shows him sitting drinking beer -- pretty much what makes him tick.', 23, '1995-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 3, 'Roseanne in the Hood', 'Roseanne will stop at nothing to crush the competition when a new, more posh eatery -- complete with a salad bar and a drive-through window -- opens up across from the Lunch Box.', 23, '1995-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 4, 'The Last Date', 'The temptation to crash a stranger''s bar mitzvah at a local hotel is too much for Roseanne as she drags Dan out on the town for a "last hurrah" before the baby is born.', 23, '1995-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 5, 'Halloween: the Final Chapter', 'Roseanne reigns as "Queen of the Gypsies, consort of wizards and seer of souls" on Halloween, when an Ouija board sending a message from "The Dead" portends an unexpected event: she''s in labor.', 23, '1995-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 6, 'The Fifties Show', 'The Conners find themselves going back in time in this spoof of 1950s sitcoms (shot mostly in black and white): Roseanne''s a fussy housewife, Dan is a hapless businessman stewing over "the Anderson account," and Jackie''s the wacky neighbor.', 23, '1995-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 7, 'The Getaway, Almost', 'Roseanne and Jackie''s shopping trip with the baby becomes an outing a la Thelma and Louise after they give a lift to a rebellious teen, then force a trucker off the road.', 23, '1995-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 8, 'The Last Thursday in November', 'When D.J.''s teacher gives his students free rein, the class Thanksgiving pageant takes on a decidedly modern, Pulp Fiction twist-- and offends many of the parents, but not the Conners.', 23, '1995-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 9, 'Of Mice and Dan', 'With his old band mate performing in town, Dan''s got the blues. Seems he regrets giving up his youthful dreams to settle down with Roseanne.', 23, '1995-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 10, 'Direct to Video', 'While Roseanne narrates a video time capsule for her unborn child, Becky and Darlene find old love letters of Dan and Roseanne''s; D.J. gets upset when he finds his parents did not fill out his baby book; and Mark cooks dinner for the Conner clan.', 23, '1995-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 11, 'December Bride', 'Christmas for the Conners bring more than the usual holiday cheer and festivities, it also brings a wedding -- for Leon and Scott.', 23, '1995-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 12, 'The Thrilla Near the Vanilla Extract', 'Did someone say food fight? That''s what Roseanne and Jackie''s stint offering samples at a supermarket turns into when Jackie outsells her sister.', 23, '1996-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 13, 'The White Sheep of the Family', 'D.J. inherits $500 in his great aunt Harriet''s will (because he was the only member of the family she never met) and blows half of it on a trombone to impress a girl who plays tuba in the school band. Meanwhile, Darlene alienates everyone by mentioning that she has turned down a $500/week job in advertising, an entry level position that would pay her more than both her parents earn.', 23, '1996-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 14, 'Becky Howser, M.D.', 'Roseanne advises an unhappy Becky to change her life -- not realizing that Mark doesn''t share his wife''s eagerness for change, so Becky intends to change her marriage.', 23, '1996-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 15, 'Out of the Past', 'While Nana Mary amuses Roseanne and Jackie with a box of their childhood treasures, Dan and his pals reluctantly play poker with Leon and Scott.', 23, '1996-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 16, 'Construction Junction', 'Dan weighs the merits of giving up his boring garage job for a new construction endeavor with his pals; Jackie surfs the internet and becomes addicted.', 23, '1996-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 17, 'We''re Going to Disney World (1)', 'The family goes hog wild with excitement -- and with plans to travel to Disney World -- when Dan brings home his final paycheck from the Lanford City Garage.', 23, '1996-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 18, 'Disney World War II (2)', 'Fireworks and fanfare accompany the Conners on a whirlwind tour of the magical kingdom of Disney World, when Darlene finds she''s actually happy in the presence of Winnie the Pooh.', 23, '1996-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 19, 'Springtime for David', 'David moves out after getting a job at a theme park known as "the happiest place in Illinois," where he''s soon transformed into an ultra-perky worker with an eerie smile.', 23, '1996-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 20, 'Another Mouth to Shut Up', 'Just weeks after their hot night in Disney World, Darlene drops a proposal -- and a surprise announcement: she''s pregnant -- on David, whose major life changes seem to be happening all in one day.', 23, '1996-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 21, 'Morning Becomes Obnoxious', 'After an impromptu interview at the diner goes spectacularly well, Roseanne prepares to "Wake Up Chicago" on a morning TV talk show as a news commentator with a unique and "opinionated blue-collar outlook" -- and with Jackie as her manager.', 23, '1996-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 22, 'Ballroom Blitz', 'Bev''s smitten with her passionate ballroom-dance instructor -- until a drama unfolds on the dance floor when he starts flirting with the newly divorced Jackie.', 23, '1996-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 23, 'The Wedding', 'Darlene''s wedding day brings unexpected tears, joy and tenderness as Dan is finally able to express his love to Darlene and the young couple''s wedding vows bring Roseanne to tears.', 23, '1996-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 24, 'Heart & Soul', 'Roseanne''s brave and witty front masks her fears after Dan suffers a heart attack during Darlene''s wedding reception.', 23, '1996-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 8), 25, 'Fights and Stuff', 'Dan returns home from hospital with orders from the doctor for a new diet regime -- and strict orders from Roseanne about changing his lifestyle.', 23, '1996-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 1, 'Call Waiting', 'Roseanne goes on a spiritual odyssey in front of the TV. After walking out on Dan in the heat of anger, Roseanne is now holed up at Jackie''s, mesmerized by the sitcom couples she grew up with on That Girl, The Mary Tyler Moore Show, and I Dream of Jeannie. Meanwhile, back at the Conner house, Dan is listlessly puttering around fixing things -- but he''d rather "fix things" in his marriage. And, much like the TV couples occupying Roseanne''s thoughts, Dan and Roseanne just might discover that they''re better off together than apart. In the coda, Jackie realizes that they have won $108 million in the state lottery.', 23, '1996-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 2, 'Millions from Heaven', 'The Connors win the biggest lottery payoff in state history but insist they''re still "just folks."', 23, '1996-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 3, 'What a Day for a Daydream', 'Newly wealthy Roseanne indulges in daydreams involving Hugh Hefner and an appearance on the Jerry Springer Show in which she imagines her dreams, and even some of her nightmares, coming true thanks to the lottery winnings.', 23, '1996-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 4, 'Honor Thy Mother', 'While Roseanne and Jackie anticipate indulging themselves to unlock their "divine female essence" at a luxury spa, Dan is just plain morose -- and finally admits why: nagging worries about a family member, his institutionalized mother.', 23, '1996-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 5, 'Someday My Prince Will Come', 'A Moldavian prince descends on Lanford with one purpose in mind: to romance Jackie. It seems he''s developed a royal crush on her after seeing her briefly on TV.', 23, '1996-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 6, 'Pampered to a Pulp', 'Roseanne and Jackie fight the battle of the bulge during their sojourn at a luxury spa, where past-life regression therapy brings out the imagined warrior in Roseanne.', 23, '1996-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 7, 'Satan, Darling', 'Absolutely fabulous glam gals Jennifer Saunders and Joanna Lumley (in character as Edina and Patsy) are among the few down-to-earth participants in Roseanne''s outrageous Halloween outing. They''re guests at an Upper West Side soiree, where new multimillionaires Roseanne and Jackie have gained entrance into New York society. But for grandmother-to-be Roseanne, a witches'' coven soon comes into play "a la Rosemary''s Baby” and bizarre happenings begin to involve a very pregnant Darlene.', 23, '1996-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 8, 'Hoi Polloi Meets Hoiti Toiti', 'A visit with the wealthy Wentworths on Martha''s Vineyard gives the Conners a glimpse into new friend Astrid''s dysfunctional family. And before long, the Conners are teaching the snobby elitists some truths about real life.', 23, '1996-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 9, 'Roseambo', 'Roseanne battles a group of women-hating terrorists who hold her family and a foreign diplomat hostage on a train to Washington, D.C.', 23, '1996-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 10, 'Home is Where the Afghan Is', 'The absence of Dan, a series of family squabbles, and a shocking revelation by Bev mar the Conners'' first Thanksgiving as a rich and famous family, and they start to realize that money does not necessarily buy happiness.', 23, '1996-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 11, 'Mothers and Other Strangers', 'Bev pays a visit to her free-spirited mom in search of answers, while Roseanne awaits Dan''s return with trepidation, fearing he might not recognize the place -- or her new look.', 23, '1996-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 12, 'Home for the Holidays', 'After a long stay in California with his mother, Dan returns home for Christmas and he, Roseanne and the rest of the family begin to realize how fortunate they are to have each other and how much they have to be thankful for as the old year ends.', 23, '1996-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 13, 'Say It Ain''t So', 'Jackie forces Dan to reveal some devastating news to Roseanne: he''s been having an affair in California with a nurse who cared for his mother. Meanwhile, D.J. wants the job of videotaping Darlene giving birth; and Jackie must face a harsh truth about her own love life.', 23, '1997-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 14, 'Hit the Road, Jack', 'As Dan packs his bags to leave, Roseanne drowns her sorrows in fast food while driving aimlessly around Lanford, and D.J. finds a soul mate to share his troubles.', 23, '1997-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 15, 'The War Room', 'When a heartbroken Roseanne locks herself in her room and won''t come out, her family and friends all try in their own unique way to help her get out of her funk. Friends and family try an intervention after they''re unable to rouse a listless Roseanne out of bed, where she''s been for four days amid piles of junk food, depressed over Dan''s affair.', 23, '1997-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 16, 'Lanford''s Elite (1)', 'At a party at the swank Lanford Country Club, Roseanne forges a surprising bond with Edgar Wellman, Jr., the son of her hated former boss. When he reveals some shocking news about the future of Lanford, Roseanne realizes she may be the only one who can save her hometown.', 23, '1997-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 17, 'Some Enchanted Merger (2)', 'After they wrap up the Wellman Plastics buyout, Roseanne doesn''t know what to do when she finds herself deeply attracted to Edgar Wellman, Jr., and realizes that he is equally bewitched by her.', 23, '1997-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 18, 'A Second Chance', 'Bothered by rumors about Roseanne and "that Wellman guy," Dan sweeps by to take Roseanne out for a ride. Roseanne and Dan begin to take the first tentative steps toward putting their marriage back together. But their reconciliation is disrupted when a frantic call comes in from Jackie: Darlene has been suddenly rushed to the hospital.', 23, '1997-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 19, 'The Miracle', 'When Darlene gives birth to a very premature baby, the doctors offer very little hope for the child''s survival. But Roseanne sets out to prove that love, affection, and human contact are better than any medicine.', 23, '1997-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 20, 'Roseanne-Feld', 'Jackie and Mark take in a female wrestling match; D.J. is not prepared when he realizes he may be about to have his first sexual experience when a night of watching videos with Heather turns into a night of passion; and Bev introduces Leon and Scott to her new "friend," a boozy lounge singer named Joyce.', 23, '1997-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 21, 'The Truth Be Told', 'Roseanne learns some truths about the price of fame when two high-powered television programmers bombard her with all sorts of bizarre ideas about how network and cable TV would tell her life story. Roseanne is appalled to learn that one wants to sanitize her life and the other wants to spice it up. At the same time, Bev is happily telling stories about Roseanne to a friendly florist, unaware that he is actually a tabloid reporter.', 23, '1997-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 22, 'Arsenic and Old Mom', 'Dan''s eccentric mom heads straight for Lanford after she''s released from hospital, claiming to be cured. Problem is, Dan thinks she''s trying to kill him.', 23, '1997-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 23, 'Into That Good Night (1)', 'Darlene and David bring home their new baby. Roseanne''s sage advice for her daughter? "The best part is when you can mold their tender little egos to fit your every whim," she says. But the baby''s not the only news. When friends and family gather to celebrate the birth, Becky and Mark have a surprising secret -- and Leon and Scott make an announcement.', 23, '1997-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 9), 24, 'Into That Good Night (2)', 'Roseanne fans find out much more than they thought they would in the second half of the season finale', 23, '1997-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 1, 'Twenty Years to Life', 'Roseanne and Dan adjust to living under the same roof with Darlene and her two children, Harris and Mark, when Darlene loses her job. Meanwhile, Becky announces she is going to be a surrogate to make extra money; and Roseanne and Jackie are at odds with one another.', 23, '2018-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 2, 'Dress to Impress', 'Darlene’s son, Mark, gets caught with a pocket knife after being bullied on the first day of his new school. Meanwhile, Becky invites Andrea over to meet the family and is nervous to bring her home.', 23, '2018-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 3, 'Roseanne Gets the Chair', 'Roseanne’s clash with Darlene over how she’s raising her kids – especially Harris – reaches a breaking point; while Dan tries to help Roseanne with her bad knee by getting her an elevator chair, which she refuses to use because she doesn’t want to admit getting old.', 23, '2018-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 4, 'Eggs Over, Not Easy', 'A crucial moment for Becky’s surrogacy arrangement forces her and Darlene to critically assess each other’s lives. Meanwhile, an animal rescue organization rejects Jackie’s application to adopt a puppy; and Roseanne makes a plan to change their mind.', 23, '2018-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 5, 'Darlene v. David', 'David unexpectedly shows up for Harris’ birthday after being absent for years, forcing Darlene to re-examine their relationship and the rest of the family. Meanwhile, Roseanne and Jackie’s mother, Bev, temporarily moves into the Conner home after an incident at the nursing home prevents her from returning', 23, '2018-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 6, 'No Country for Old Women', 'After Beverly gets kicked out of the nursing home, Roseanne and Jackie fight over who will take care of their mother. Meanwhile, Mark''s creative touch with building a birdhouse for Dan''s customer is more than Dan can handle, but Darlene defends her son.', 23, '2018-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 7, 'Go Cubs', 'The Conners can''t pay their Wi-Fi bill, so they befriend their new neighbors to use the Internet for Mary to Skype with mom Geena, who is stationed in Afghanistan. Meanwhile, Dan loses an important job and D.J. admits post-military life has been hard, so they come up with a plan to make extra money.', 23, '2018-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 8, 'Netflix & Pill', 'After celebrating their 45th anniversary, Roseanne reveals to Dan a bigger problem with her bad knee. Meanwhile, Crystal announces her retirement as a waitress at the casino, and Becky and Darlene compete for the job, which has full-time benefits.', 23, '2018-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094540')) AND numero_temporada = 10), 9, 'Knee Deep', 'Roseanne''s knee gets worse so Dan is forced to a make an important work decision; but when a major storm hits Lanford, their fortunes change for the better. Later, Darlene realizes she has to go back to her first passion, writing.', 23, '2018-05-22');
