INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0095765', 'Cinema Paradiso', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0868153'), 'PELICULA', 'Salvatore, a famous film director, returns to his hometown for the funeral of the local theater''s film projectionist, Alfredo. He reminisces about his life as a young boy falling in love with cinema.', '1988-01-01', 'https://m.media-amazon.com/images/M/MV5BMTljNzc4YWEtYTZlMS00ODMyLWIwMTAtNWQxY2VkMDEwYTk5XkEyXkFqcGc@._V1_.jpg');
