INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 1, 'The Adventure of the Clapham Cook', 'A Mrs Ernestine Todd, from Clapham, asks Poirot to help her find her cook, Eliza, who has disappeared. Poirot, who aims to accept only really significant cases, is at first insulted by such a trivial request. However, after he sees the contents of the missing cook''s trunk, he decides the case could prove to be worthy of his talents.', 52, '1989-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 2, 'Murder in the Mews', 'Within hours of the Bonfire Night fireworks beginning Poirot finds himself investigating a violent death in Hastings'' mews garage.', 52, '1989-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 3, 'The Adventure of Johnnie Waverly', 'Country squire Marcus Waverly calls on Poirot for help in dealing with kidnap threats against his son. Hastings is appalled by the thought of someone going around kidnapping children and it becomes a race against time to find the identity of the mystery letter writer.', 52, '1989-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 4, 'Four and Twenty Blackbirds', 'At a London restaurant where he often eats, Poirot notices that another regular customer has diverted from his usual meal. As old Anthony Gascoigne lies dying in Brighton, his estranged twin brother, Henry, falls to his death. A tragic accident, or murder? Poirot begins to see connections and decides the answer to the mystery lies in a blackberry pie.', 52, '1989-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 5, 'The Third Floor Flat', 'Poirot discovers a murder in his own block of flats, and goes on the trail of boisterous neighbours and strange nocturnal noises in the lift shaft.', 50, '1989-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 6, 'Triangle at Rhodes', 'Poirot is on holiday at the Palace Hotel, Rhodes, when an Englishwoman, Mrs Valentine Chantry, is poisoned. Poirot unravels several complicated relationships between those staying at the Palace Hotel.', 53, '1989-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 7, 'Problem at Sea', 'Poirot and Hastings are on board a ship steaming towards Alexandria. Poirot recovers from his usual sea-sickness to take an interest in some fellow passengers, especially the Clappertons. On arrival at Alexandria, Mrs Clapperton is found murdered in her cabin.', 53, '1989-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 8, 'The Incredible Theft', 'Lord Mayfield, an aircraft manufacturer, tries to trap a spy at his country house, but his plan goes terribly wrong. Lady Mayfield sends for Poirot, who tells a few home truths.', 51, '1989-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 9, 'The King of Clubs', 'Lovely young actress Valerie St Clair, engaged to marry Prince Paul of Maurania, is the only witness to the murder of Henry Reedburn, a shady and overbearing producer. Prince Paul appeals to Poirot to save Valerie from police suspicion, and the great detective finds he has a conundrum to ponder on, ''When is a murder not a murder?''', 48, '1989-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 1), 10, 'The Dream', 'Millionaire business man Benedict Farley, a well known eccentric, consults Poirot about bad dreams he has been having. Mr. Farley has dreamed repeatedly of killing himself. Sadly, he does not follow Poirot''s advice. When Farley is found dead, Poirot fails to believe that it is suicide and suspects a murder plot relying on hypnosis.', 51, '1989-03-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 2, 'Season 2', 'In the second series, as always, Poirot''s ingenious mind manages to find a way through a number of mysteries. He even manages to feign disinterest in a case when it is apparent that Hastings wishes to take the glory in order to impress a lady.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 1, 'Peril at End House', 'Poirot and Hastings take a holiday in Cornwall, looking for peace and quiet. They meet Miss Nick Buckley, who lives near their hotel at End House, and she tells Poirot she has had three near-fatal accidents in a few weeks. He then finds a bullet hole in her hat, returns with her to End House and is drawn into a complex murder investigation.....', 107, '1990-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 2, 'The Veiled Lady', 'Poirot calls to see the veiled lady of the title (Lady Millicent Castle-Vaughn) at her London hotel. Lady Millicent is about to be married, but a mean blackmailer called Lavington has got hold of a love letter she wrote years before to another man. Lavington wants twenty thousand pounds, and Poirot makes up his mind to recover the letter himself, even if it means impersonating a Swiss locksmith.', 50, '1990-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 3, 'The Lost Mine', 'Hastings and Poirot are playing Monopoly when they are interrupted by Lord Pearson, the elegant Chairman of the London and Shanghai Bank. The banker asks them to investigate the disappearance of a Mr Ling - a highly-valued customer who before he went missing had arranged to sell Lord Pearson a map showing the location of a long-lost silver mine. Ling is found murdered, a young stockbroker is implicated, and Poirot has to untangle a complicated plot.', 53, '1990-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 4, 'The Cornish Mystery', 'Poirot travels to Cornwall, summoned by a Mrs Pengelley, who suspects her dentist husband is poisoning her because he''s fallen in love with his young assistant. Unhappily, Poirot finds Mrs Pengelley dead on his arrival, so he sets out to catch her killer.', 49, '1990-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 5, 'The Disappearance of Mr. Davenheim', 'Matthew Davenheim, a rich banker, disappears on a walk from his country house to the village post office, and Inspector Japp of Scotland Yard is put onto the case. Poirot, who has developed an interest in conjuring tricks, bets Japp five pounds that he can solve the mystery without leaving his apartment.', 53, '1990-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 6, 'Double Sin', 'Poirot tells a surprised Hastings he''s decided to retire and suggests they take a holiday in the Lake District. On the way, Hastings befriends a young woman who is missing a collection of valuable miniatures. The case involves a famous writer and a beautiful woman in a sports car, and to the relief of Hastings Poirot''s thoughts of retirement soon seem far away.', 52, '1990-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 7, 'The Adventure of the Cheap Flat', 'A glamorous nightclub singer turned spy has stolen the US Navy''s plans for a new submarine, and an FBI agent called Burt is in London to catch her. Burt dismisses Poirot as a gumshoe, and Poirot is likewise not impressed by the self-important G-man. Poirot is drawn into the case when it appears that the submarine plans will fall into the hands of the Fascist government in Italy unless they are recovered. When Poirot meets a young couple who''ve got an amazing bargain on a prime apartment, he sees a connection with the spy case.', 52, '1990-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 8, 'The Kidnapped Prime Minister', 'Poirot is called in when the British Prime Minister and his secretary are kidnapped in France on their way to a League of Nations conference - and he is given just a day and a half to solve the case.', 53, '1990-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 2), 9, 'The Adventure of the Western Star', 'Marie Marvelle, a Belgian film star, receives threatening letters from a chinaman which demand her famous diamond, the Western Star. Marie visits her old friend Hercule Poirot in London, seeking his help, and Poirot tackles the case with relish.', 52, '1990-03-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 1, 'The Mysterious Affair at Styles', 'Recovering from the horrors of World War I, British Army officer Arthur Hastings hopes to find peace and quiet at a country manor in the English countryside. But when the matriarch dies during the night from strychnine poisoning, Hastings enlists the help of an old friend staying nearby with other war refugees to help solve the murder: former Belgian police detective Hercule Poirot.', 108, '1990-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 2, 'How Does Your Garden Grow?', 'Suggestions of a Communist conspiracy cast suspicion on a murdered woman''s Russian servant. Meanwhile, Poirot has a rose named after him, and a ceremony at the Chelsea Flower Show makes him the centre of attention. Hastings receives a packet of seeds and develops hay fever.', 53, '1991-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 3, 'The Million Dollar Bond Robbery', 'The London and Scottish Bank is sending a huge shipment of Liberty Bonds to New York on the liner Queen Mary. Poirot, who suffers terribly from sea-sickness, is asked to see the bonds safely across the Atlantic.', 53, '1991-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 4, 'The Plymouth Express', 'An Australian shipping tycoon wants Poirot to check out his daughter''s suitors. Then the young lady takes a trip on the Plymouth Express, and Poirot finds himself investigating a jewel theft on the train.', 52, '1991-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 5, 'Wasps'' Nest', 'Poirot  visits a garden fete, where a wasps'' nest adds to the tension. He meets the son of an old friend who has his girl-friend, a fashion model, with him, and Poirot soon suspects that they are both in danger. He has to solve a mystery which includes cyanide, failing brakes and mixed-up love lives. Meanwhile, Hastings has a new hobby which Poirot finds helpful in cracking the case.', 53, '1991-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 6, 'The Tragedy at Marsdon Manor', 'Poirot is summoned to Marsdon by the owner of a country inn there to solve a murder. But the inn-keeper is a would-be thriller writer, and to Poirot''s dismay the murder turns out to be fictional. Thankfully, though, there is soon a real (if seemingly supernatural) murder at the big house. Things get even more interesting when a young wife claims that a tree in her garden is haunted by a laughing ghost, and there are also signs of black magic from East Africa. Poirot lays a clever ambush to smoke out the killer,confident that he or she will turn out to be human.', 53, '1991-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 7, 'The Double Clue', 'Japp (who is really worried that failure could cost him his job) seeks Poirot''s help in investigating a series of jewel thefts, and two remarkable things happen. Poirot falls in love (with the beautiful and clever Countess Vera Rossakoff) and he also meets a criminal intellect which he finds worthy of him. As the countess is his main suspect, Poirot spends most of his time with her - which for once leaves Hastings and Miss Lemon to do most of the actual detective work.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 8, 'The Mystery of the Spanish Chest', 'Poirot is called in to help a woman who lives in fear of her husband, and he is invited to a dinner party which goes horribly wrong.', 53, '1991-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 9, 'The Theft of the Royal Ruby', 'Poirot prepares to spend a quiet Christmas on his own with a box of chocolates, but he has to give up his plans when the British government asks for his urgent help. Prince Farouk, a  young member of the Egyptian royal family visiting London, has lost a famous ruby, and this is deemed to be a matter of national security.', 48, '1991-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 10, 'The Affair at the Victory Ball', 'Poirot attends the Victory Ball, a costume party where you are expected to dress as someone famous, as himself. However, when two members of a party of six dressed as characters from classical Italian comedy are subsequently found dead, Poirot finds himself working with Chief Inspector Japp to solve the case. The solution to the deaths of Viscount Cronshaw and Coco Courtney is to be found in determining the correct time of death and identifying an impostor at the ball. Poirot takes to the airwaves and reveals the identity of the killer on a live BBC radio broadcast.', 52, '1991-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 3), 11, 'The Mystery of Hunter''s Lodge', 'Hercule Poirot accompanies his friend Captain Hastings on a weekend shooting party at the home of Harrington Pace, but he isn''t having a very good time. He comes down with the flu and takes to his bed but when Pace is shot dead in his study, he rises to the occasion to assist Inspector Japp in solving the case.', 52, '1991-03-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 4), 1, 'The ABC Murders', 'Beside the bodies of three murder victims lies a copy of the ABC Railway Guide.', 105, '1992-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 4), 2, 'Death in the Clouds', 'On an airplane, flying from Paris to London, one of the passengers is killed by a poison dart while Poirot sleeps.', 106, '1992-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 4), 3, 'One, Two, Buckle My Shoe', 'Poirot believes his dentist was murdered and Japp thinks it was a suicide.', 106, '1992-01-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 1, 'The Adventure of the Egyptian Tomb', 'An archaeologist dies of a heart attack shortly after opening an ancient Egyptian tomb, but his widow thinks there is dirty work at the crossroads and calls Poirot.', 52, '1993-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 2, 'The Underdog', 'A wealthy industrialist is found dead in his study. Is his death related to a discovery made at his chemical factory? And is his wife all she seems?', 53, '1993-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 3, 'The Yellow Iris', 'Friends and family gather at a dinner party to mark the second anniversary of a woman''s death. Meanwhile, Poirot is caught up in a coup d''etat and arrested as a spy, which prevents him from solving a murder at a French restaurant owned by an Italian in Buenos Aires.', 52, '1993-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 4, 'The Case of the Missing Will', 'Poirot has to execute the final wishes of an old friend who has been killed.', 53, '1993-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 5, 'The Adventure of the Italian Nobleman', 'Poirot is drawn into the underworld of London''s Little Italy when Captain Hastings looks for a new car, but instead finds murder.', 52, '1993-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 6, 'The Chocolate Box', 'Poirot returns to Belgium for the first time since the Great War. There he revisits a twenty-year-old murder mystery that was never officially solved.', 52, '1993-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 7, 'Dead Man''s Mirror', 'When Poirot investigates the mysterious death of a despised art dealer, he finds that he has more than enough suspects from whom to choose.', 52, '1993-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 5), 8, 'Jewel Robbery at the Grand Metropolitan', 'Mrs. Opalsen''s famous pearls are stolen and Poirot is happily on hand to investigate. A complex theft calls for a sophisticated solution. Unfortunately, Poirot is hindered everywhere he goes by being mistaken for ''Lucky Len''.', 51, '1993-03-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 6), 1, 'Hercule Poirot''s Christmas', 'Poirot''s Christmas is interrupted by Simeon Lee, who believes his life is threatened. Simeon is soon killed and his diamonds stolen.', 107, '1994-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 6), 2, 'Hickory Dickory Dock', 'A string of thefts at a student hostel run by Miss Lemon''s sister ends in death and Poirot has a number of plots and sub-plots to untangle. A certain mouse is the only witness to a string of murders.', 103, '1995-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 6), 3, 'Murder on the Links', 'Poirot and Hastings are on holiday in Deauville and receive a visit from Paul Renauld, who believes he''s being cheated by Chileans. Renauld is kidnapped and his body is later found buried in a new golf bunker. French detective Giraud unwisely challenges Poirot to catch the killer before he can.', 94, '1996-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 6), 4, 'Dumb Witness', 'Poirot and Hastings are at Lake Windermere for an attempt on the world speed-boat record. An elderly widow is hurt by falling down stairs, then later killed by poisoning with phosphorus.', 103, '1997-03-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 7), 1, 'The Murder of Roger Ackroyd', 'Living quietly in the small village of King''s Abbot, sleuth Hercule Poirot becomes involved in the murder of successful industrialist Roger Ackroyd. The number of potential killers is almost as great as the population of the village itself. As Poirot investigates he sees that there might be a connection to the suicide of a local woman, and the death the previous year of her husband.', 99, '2000-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 7), 2, 'Lord Edgware Dies', 'Lady Edgware has a dilemma in that her husband has consistently refused to give her a divorce. She asks Hercule Poirot to visit the man and see if there is any possibility of convincing him. When Lord Edgware is found dead, there is no great surprise, but there are a good number of suspects.', 99, '2000-02-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 8), 1, 'Evil Under the Sun', 'After collapsing with heart problems, Hercule Poirot visits a seaside health farm on Burgh Island. While there, the flirtatious heiress Arlena Stewart is found strangled on a secluded beach.', 103, '2001-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 8), 2, 'Murder in Mesopotamia', 'While accompanying his friend Hastings to a dig in Iraq, Hercule Poirot becomes involved in the murder of an archaeologist''s wife.', 103, '2001-07-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 9), 1, 'Five Little Pigs', 'Lucy Crale hires Poirot to solve the murder of her father sixteen years before, and Poirot finds a number of possible suspects who are still alive.', 97, '2003-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 9), 2, 'Sad Cypress', 'Young Elinor Carlisle, engaged to marry the dashing Roddy Winter, finds herself charged with the fatal poisoning of Mary Gerrard, her rival in love. Poirot has the job of saving Elinor, but the evidence against her is overwhelming.', 97, '2003-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 9), 3, 'Death on the Nile', 'A wealthy British heiress honeymooning on a Nile cruise ship is stalked by a former friend, whose boyfriend she had stolen before making him her new husband.', 102, '2004-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 9), 4, 'The Hollow', 'Poirot is spending a week-end with the Angkatells, at their country house called The Hollow.', 97, '2004-04-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 10), 1, 'The Mystery of the Blue Train', 'After traveling on the Blue Train from Calais to Nice, Hercule Poirot is pressed into service to help solve the murder of heiress Ruth Kettering who is found savagely beaten in her compartment.', 98, '2006-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 10), 2, 'Cards on the Table', 'Hercule Poirot finds himself investigating the murder of his dinner host, Mr. Shaitana, who was stabbed in the heart while his guests played bridge.', 96, '2006-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 10), 3, 'After the Funeral', 'Hercule Poirot''s solicitor, Gilbert Entwhistle, asks Poirot to help solve a riddle and a murder.', 97, '2006-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 10), 4, 'Taken at the Flood', 'Hercule Poirot finds himself trying to solve the mystery of the Cloade family', 97, '2006-04-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 11), 1, 'Mrs. McGinty''s Dead', 'James Bentley is arrested for the murder of old Mrs McGinty. It looks like an open and shut case, but Superintendent Spence is not convinced. He turns to Poirot for help, and together with Poirot''s writer friend Ariadne Oliver they set out to find the real killer.', 97, '2008-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 11), 2, 'Cat Among the Pigeons', 'Poirot finds a connection between a recent murder and a revolution in the Middle Eastern kingdom of Ramat.', 97, '2008-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 11), 3, 'Third Girl', 'Three single girls share a London flat. The first works as a secretary; the second is an artist; the third, who comes to Poirot for help, disappears believing she is a murderer.', 97, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 11), 4, 'Appointment with Death', 'On holiday in Jerusalem, Poirot hears about an archaeological expedition to Syria led by the eccentric Lord Boynton and his son Leonard, who believe they are on the track of the head of St John the Baptist. Drawn to visit the dig, Poirot meets Boynton''s dominating, fabulously rich, American-born second wife. However, events are overtaken by the discovery of Lady Boynton''s dead body and revelations about her fortune.', 97, '2009-12-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 12), 1, 'Three Act Tragedy', 'When a vicar chokes to death on a cocktail while attending a party held by actor Sir Charles Cartwright, Poirot initially dismisses the idea of murder but reconsiders when another guest dies in the same manner.', 92, '2010-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 12), 2, 'Hallowe''en Party', 'During a village''s Hallowe''en party, a young girl boasts of having witnessed a murder from years before. No one believes her tale until her body is found later on in the evening, drowned in the apple-bobbing bucket.', 92, '2010-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 12), 3, 'Murder on the Orient Express', 'Poirot investigates the murder of a shady American businessman stabbed in his compartment on the Orient Express when it is blocked by a blizzard in Croatia.', 92, '2010-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 12), 4, 'The Clocks', 'Four clocks surround an unidentified corpse in a blind woman''s house, and a young typist is summoned to the crime scene. However, Poirot is convinced that the complicated setup is merely hiding a simpler solution.', 92, '2011-12-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 13), 1, 'Elephants Can Remember', 'Poirot investigates a strange and gruesome murder of an elderly psychiatrist. Ariadne Oliver is pressed to try and uncover the truth behind two decade-old deaths. They soon find out that their separate investigations are linked and work together to try and solve the mystery.', 92, '2013-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 13), 2, 'The Big Four', 'With the world on the brink of WWII, there is more political turmoil when it appears that the famous Peace Party is in fact a cover for the Big Four.', 91, '2013-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 13), 3, 'Dead Man''s Folly', 'Ariadne Oliver is asked to devise a murder hunt for a Devon fête, but her sense of foreboding summons Poirot to the scene. Her fears are realized when, during the fête, the girl playing her murder victim winds up well and truly murdered.', 92, '2013-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 13), 4, 'The Labours of Hercules', 'In an effort to recover his confidence after a rare professional failure, Poirot sets off for the Swiss Alps in pursuit of a missing maid.', 94, '2013-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0094525')) AND numero_temporada = 13), 5, 'Curtain: Poirot''s Last Case', 'An ailing Poirot returns to Styles with Hastings nearly three decades after solving their first mystery together there in order to prevent an unscrupulous and ingenious serial killer from claiming more victims.', 93, '2013-11-13');
