INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 1, 'Mr. Bean', 'Mr. Bean attends a mathematics exam, where he tries to copy from a student under the nose of the invigilator, when he realizes that he has studied the wrong maths equations. Afterwards, he surreptitiously changes into his swimming trunks so as not to be noticed by someone sitting nearby at a beach. And later struggles to stay awake during a church service and obnoxiously sings the refrain of the hymn "All Creatures of Our God and King," much to the annoyance of the man sitting next to him, Mr. Sprout.', 25, '1990-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 2, 'The Return of Mr. Bean', 'Mr. Bean goes to a department store and buys various items. Afterwards, he goes to a fancy restaurant where he tries to dispose his awful-tasting meal. And finally, Bean goes to a Royal greeting and gets into mischief.', 25, '1990-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 3, 'The Curse of Mr. Bean', 'Mr. Bean goes to a swimming pool, where he finds himself scared to death on the high diving board. When he''s done, he tries several different ways to get his car out of the parking garage after he realizes he doesn''t have enough money to do it the normal way. After that, he sits on a park bench and uses an unusual method of making himself a sandwich. Finally, he goes to a cinema and tries to survive a terrifying horror movie with his girlfriend.', 25, '1990-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 4, 'Mr. Bean Goes to Town', 'Mr. Bean purchases a new TV, only to experience a spot of reception trouble. He then takes a stroll in the park to try out his new camera, which is promptly stolen. This leads to an identity parade, where Bean does his best to discover the identity of the camera thief. Later, Bean''s night on the town spells disaster for a stage magician. Lastly, Mr. Bean shows off his dancing skills at Club Phut.', 24, '1991-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 5, 'The Trouble with Mr. Bean', 'Mr. Bean, late for his dental appointment, tries to get dressed and clean his teeth whilst on the way. After arriving just in time for the appointment, he ends up administering an anesthetic to the hapless dentist. After visiting the dentist, Bean has a picnic in the park, where he tangles with a pesky fly and a remote-control toy boat.', 25, '1992-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 6, 'Mr. Bean Rides Again', 'At the bus stop, Mr. Bean tries his best to revive a heart attack victim before using an ambulance to jump-start his own mini-car. Later, when posting a letter, he loses his only stamp, but that doesn''t stop him from sending his letter anyway. Whilst preparing for his holiday, Mr. Bean demonstrates a novel (if not entirely efficient) method of packing, then disposes of a bothersome train passenger, and tries to entertain an airsick boy during a plane flight.', 24, '1992-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 7, 'Merry Christmas Mr. Bean', 'While Christmas shopping, Mr. Bean purchases a bulky string of tree lights before making a shambles of a department store toy section. He later manages to acquire a free turkey and Christmas tree, and attempts to conduct a Salvation Army band. Finally, during Christmas dinner, Bean has quite a surprise in store for his long-suffering girlfriend.', 27, '1992-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 8, 'Mr. Bean in Room 426', 'Mr. Bean goes to a hotel where he causes trouble and seeks competition in his hotel neighbor. After he eats some spoiled oysters, he wakes up at night from some loud noise and ends up being locked out of his room.', 25, '1993-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 9, 'Do-It-Yourself Mr. Bean', 'On New Year''s Eve, Bean hosts his very own party with his friends Rupert and Hubert, but it isn''t long before his guests discover that there is more fun at the party next door and trick Bean into letting them go. The following morning on New Year''s Day, Bean buys some new tools and a large recliner armchair at the January sales of a department store and has a unique way of driving home. He then tries painting his flat himself and starts off the new year with a bang.', 25, '1994-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 10, 'Mind the Baby, Mr. Bean', 'On his way to the Southsea funfair, Mr. Bean accidentally becomes lumbered with a baby boy with no idea of how or where he came from, forcing him to try having fun at the fair with the baby. Throughout the day, the baby manages to survive Bean''s unique style of mishaps before eventually being reunited with his mother.', 25, '1994-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 11, 'Back to School Mr. Bean', 'Mr. Bean attends an open day of a local school, where he unleashes his usual brand of chaos in the various classes he visits. Afterwards, Bean''s day soon takes a sombre turn when he finds that his Mini isn''t parked where he left it and is crushed by an Army Tank during the demonstration.', 25, '1994-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 12, 'Tee Off, Mr. Bean', 'After causing chaos at the town launderette while having his laundry cleaned, Bean tries his hand at mini golf, but after being told by the course''s owner that he can only touch the ball with the club and not with his hands, Bean''s poor aim leads him on an elaborate tour around town before ultimately returning to the course several hours later with a final score of 3,427 strokes.', 25, '1995-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 13, 'Goodnight, Mr. Bean', 'At a hospital waiting room, Bean uses various methods to skip ahead of the queue but his antics backfire. Later at a park, he decorates Queen''s Guard, so that he can take a picture. And at the end of the day, Bean tries to cure his insomnia with some unusual methods at home.', 24, '1995-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096657')) AND numero_temporada = 1), 14, 'Hair by Mr. Bean of London', 'At a barbershop, Mr. Bean inadvertently holds the fort for the barber when he is distracted by a phonecall, resulting in him giving several customers terrible haircuts. Later, Bean heads to a fête, where he cheats at all the games and enters Teddy into a children''s pet show, where his inanimacy allows Bean to pass all the obedience tests with flying colours. And finally, after a train journey, Bean accidentally loses his ticket and unsuccessfully tries to sneak out past the station''s guard inside a mail bag.', 27, '1995-11-15');
