INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')), 1, 'Season 1', 'Will Smith is revealed to be a street-smart teenager from West Philadelphia, who is sent to live with his wealthy relatives at their Bel Air, Los Angeles mansion. His relatives include Phillip Banks, Will''s strict and gruff uncle, and Vivian Banks, Will''s no-nonsense, forthright, and career-minded aunt. Other members of the Banks family include Carlton Banks, Will''s preppy and arrogant cousin, Hilary Banks, Will''s attractive but dumb, eldest cousin, Ashley Banks, Will''s youngest cousin, and Geoffrey, the family''s cynical English Butler. Will''s lifestyle often clashes with that of his relatives there, and frequently got him or other members of the family into trouble as well.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 1, 'The Fresh Prince Project', 'Aunt Vivian tries to mediate between her husband Philip and the newly arrived Will.', 23, '1990-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 2, 'Bang the Drum, Ashley', 'Will persuades Ashley to pawn her violin for a drum set.', 24, '1990-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 3, 'Clubba Hubba', 'Will wants to go out with a beautiful girl he meets at the country club, but first he must figure out how to impress her extremely snobbish and very protective father so he seeks tips from cousin Carlton on becoming preppie.', 22, '1990-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 4, 'Not with My Pig, You Don''t', 'Will tries to smooth things between Philip and his very rural parents when they visit to see him receive an award.', 24, '1990-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 5, 'Homeboy, Sweet Homeboy', 'Will gets a visit from an old pal named Ice Tray, who, to Vivian and Philip''s dismay, warms up to Hilary.', 24, '1990-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 6, 'Mistaken Identity', 'Jailed, Will and Carlton stage a media stunt.', 24, '1990-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 7, 'Def Poet''s Society', 'Will joins his prep school''s poetry club.', 24, '1990-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 8, 'Someday Your Prince Will Be in Effect (1)', 'Carlton and Will, babe magnets. Who will be first to get a date for Hilary''s Halloween party?', 24, '1990-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 9, 'Someday Your Prince Will Be in Effect (2)', 'Carlton and Will, babe magnets. Who will be first to get a date for Hilary''s Halloween party?', 25, '1990-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 10, 'Kiss My Butler', 'Happy birthday Geoffrey! For a gift, Will tries matchmaking, then falls for Geoffrey''s date himself.', 24, '1990-11-05');
