INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 12, 'Talking Turkey', 'A holiday visit from Will''s taskmaster mother puts the kibosh on conspicuous consumption and puts the kids to work preparing Thanksgiving dinner.', 24, '1990-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 13, 'Knowledge is Power', 'Hilary becomes Will''s personal maid when he threatens to disclose she''s dropped out of UCLA.', 24, '1990-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 14, 'Day Damn One', 'Will tells Ashley''s slumber party guests a scary tale about his first day at Bel-Air Academy.', 24, '1990-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 15, 'Deck the Halls', 'Will inimitably dresses the mansion for the holidays, to the dismay of the neighbors, including heavyweight boxing champion Evander Holyfield.', 24, '1990-12-10');
