INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 1), 25, 'Working It Out', 'Rap''s Queen Latifah plays Hilary''s new actress boss, who wants Will as her boy toy - or Hilary''s glamorous job is over.', 24, '1991-05-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')), 2, 'Season 2', 'The prince is back and fresher than ever! In the second season of this inspiring comedy, as the Banks family continues to adjust to Will living with them in Bel-Air, they find themselves questioning how they live in the process. Meanwhile, Will’s fear of becoming like his uptight Uncle Philip and his preppy cousin Carlton prompts him to take drastic action to make sure this doesn’t happen. Race relations become a hot topic in the Banks household when Will’s mother, Vy (guest star Vernee Watson-Johnson, Southland; Sister, Sister), has trouble accepting that her sister Janice (guest star Charlayne Woodard, ER) is marrying a Caucasian man. And Philip and Vivian’s past returns with open arms when a Sixties radical is invited into their home. Hilarity and heart combine in the second season of The Fresh Prince of Bel-Air. Guest stars this season include Nicholle Tom (The Nanny), Allen Payne (House of Payne) and members of New Edition Ricky Bell, Michael Bivins and Ronnie DeVoe.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 2), 1, 'Did the Earth Move for You?', 'Will''s all-consuming romance with a new girlfriend shakes up the Banks'' household, as does Mother Nature, trapping them together during an earthquake.', 24, '1991-09-09');
