INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 2), 24, 'Strip-Tease for Two', 'Will and Carlton lose their shirts investing on a tip - then take jobs as strippers to recoup their losses and get Vivian''s bracelet out of hock.', 23, '1992-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')), 3, 'Season 3', 'Season three of The Fresh Prince of Bel-Air finds Will (Will Smith) firmly entrenched in the Banks family, having traded his rough-and-tumble Philadelphia youth for posh surroundings in Bel-Air. This year, Will hip-hops over to the same prep school as Carlton (Alfonso Ribeiro) and starts scoping out colleges. While Will tries to work his mojo on reluctant Monique (Kim Fields, Living Single), Hilary (Karyn Parsons) breaks into show business and learns some hard lessons. But the kids aren’t the only ones riding life’s highs and lows. Philip (James Avery) jumps into the race for superior court judge, opposing his sleazy but powerful former mentor (Sherman Hemsley, The Jeffersons). And Vivian (Janet Hubert-Whitten) surprises everyone by announcing that she’s pregnant! Also appearing in this hilarious and poignant season are Oprah Winfrey, Vanessa Williams (Ugly Betty), comic D.L. Hughley, singer Tom Jones and boxer Riddick Bowe. All 24 episodes are fresh — and ready for your enjoyment.');
