INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 3), 19, 'Just Say Yo', 'Will learns a sobering lesson after Carlton pops the wrong pills from Will''s locker, mistaking amphetamines for vitamins, and winds up in hospital.', 24, '1993-02-15');
