INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 3), 24, 'Six Degrees of Graduation', 'Vy anticipates Will''s graduation with enthusiasm, but there may be discord when she learns Will is failing music. To pass his music class, Will must sing at the graduation ceremony - with a class of eight-year-olds.', 24, '1993-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')), 4, 'Season 4', 'Charming and cocky Will continues his reign as The Fresh Prince of Bel-Air in the fourth fast-paced season of this hit family comedy with heart. Will (Will Smith) and Carlton (Alfonso Ribeiro) are living large at college — even though they live in their family’s pool house. When they’re not hunting the honeys, like the superhot Jackie (Tyra Banks), the boys pledge a fraternity, where Will finds out that racism cuts both ways. At home, Will sneaks the dieting Philip (James Avery) some snacks, not realizing he’s endangering his uncle’s life. And Ashley (Tatyana Ali) breaks out of her childhood shell in a big way by undergoing an extremely sexy makeover, exploring the dating world and demanding some “Respect” from her parents by belting out the classic song. Donald Trump, Hugh Hefner, Dick Clark, Ben Vereen (Roots), Robert Guillaume (Benson), Pam Grier (Jackie Brown), jazzman Branford Marsalis and Boys II Men guest star in this laugh-filled 26-episode season of the freshest show around.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 4), 1, 'Where There''s a Will, There''s a Way (1)', 'Will and Carlton begin their first year of college by moving into their own apartment, while Philip and Vivian enjoy their newborn son. Hilary learns that Trevor plans to propose marriage to her during an elaborate stunt on his TV news show.', 22, '1993-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 4), 2, 'Where There''s a Will, There''s a Way (2)', 'Will and Carlton begin their first year of college by moving into their own apartment, while Philip and Vivian enjoy their newborn son. Hilary learns that Trevor plans to propose marriage to her during an elaborate stunt on his TV news show.', 23, '1993-09-20');
