INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')), 5, 'Season 5', 'Will meets Lisa — and before you can say “Go slow, bro,” he’s in love, engaged, and standing before the minister with 50 pounds of iced shrimp melting in the banquet hall. All that romance must be contagious, because Carlton finds his soul sister through online dating. Unfortunately, that’s only half right. It’s Hilary. And there’s a lot more than love going on as Will grapples with a big orange whale, a mobster, a bear, Jay Leno, Lisa’s cantankerous dad, and in one of the series’ most memorable episodes, a bullet with his name on it. Get ready for laugh-out-loud fun!');
