INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 5), 17, 'Will is from Mars...', 'Thanks to relationship counseling, Will and Lisa hop to move on up to a new understanding in preparation for marriage. Meanwhile Hillary wants Geoffrey to work at her new home.', 23, '1995-02-20');
