INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 5), 20, 'As the Will Turns', 'Will inadvertently finds himself in the right place at the right time and lands a part in a daytime soap opera.', 23, '1995-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 5), 21, 'Save the Last Trance for Me', 'Put into a trance by a stage hypnotist, Will behaves like a 4-year-old just as the family gears up for an interview with the admissions head of a private school.', 23, '1995-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 5), 22, 'To Thine Own Self Be Blue... and Gold', 'A dream job for Will with a businessman friend of Philip''s turns into a nightmare when the man offers him a bonus to help bribe a councilman.', 23, '1995-04-24');
