INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 5), 24, 'Love in an Elevator', 'Stuck and out of luck, Will spends his bachelor party trapped in an elevator with a feuding Carlton and Jazz.', 23, '1995-05-08');
