INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')), 6, 'Season 6', 'After Will becomes Hilary''s talent coordinator, her show goes national and she is lured to New York, where Ashley hopes to model. When Philip presides over a high-profile Hollywood case, his ambition almost ruins his marriage.');
