INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098800')) AND numero_temporada = 6), 5, 'The Script Formerly Known As...', 'Will decides to book a juror dismissed from Philip''s big show-biz madam sex-scandal case for Hilary''s show, which results in embarrassment for Judge Banks and some annoying apologies from Will and Hilary.', 23, '1995-10-16');
