INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 2, 'The Truth', 'George''s relationship with a former IRS worker eases Jerry''s tax worries--until she becomes George''s former relationship; Kramer sees too much of Elaine while seeing her roommate.', 23, '1991-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 3, 'The Pen', 'Elaine regrets accompanying Jerry on a visit to his parents, where local gossip includes how Jerry acquired a pen that writes upside down.', 23, '1991-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 4, 'The Dog', 'Jerry''s gig as a dog sitter provides some time alone to George and Elaine, who find they have little to say.', 23, '1991-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 5, 'The Library', 'A library cop says Jerry is 20 years overdue with a steamy novel.', 23, '1991-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 6, 'The Parking Garage', 'Saturday at the mall with the gang, none of whom bothered to note where the car was parked.', 23, '1991-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 7, 'The Cafe', 'While Jerry tries to help a cafe owner, Elaine tries to help George with an IQ test, and Kramer...well, nobody can help Kramer.', 23, '1991-11-06');
