INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 9, 'The Nose Job', 'Kramer is the catalyst for George to urge his otherwise wonderful girlfriend to get a nose job, while Jerry dates a beauty whose brain is a beaut.', 23, '1991-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 10, 'The Stranded', 'Jerry pays a high price for being stranded at a party by George, who pays the price for romance in the workplace but forgets to pay for something else.', 23, '1991-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 11, 'The Alternate Side', 'Jerry gets his car stolen; Kramer gets a line in a Woody Allen film; George gets a job; and Elaine gets tired of her boyfriend.', 23, '1991-12-04');
