INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 15, 'The Suicide', 'A psychic warns George to cancel his vacation; Jerry is hit on by his neighbor''s girl after the neighbor''s suicide attempt; Elaine fasts.', 24, '1992-01-29');
