INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098904')) AND numero_temporada = 3), 17, 'The Boyfriend (1)', 'Jerry becomes friends with baseball''s Keith Hernandez, who has a history with Kramer and would like a future with Elaine.', 24, '1992-02-12');
