INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 3, 'Homer''s Odyssey', 'After being fired from the nuclear power plant for negligence, Homer becomes a safety activist.', 24, '1990-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 4, 'There''s No Disgrace Like Home', 'After seeing families being nice to each other at a company picnic, Homer orders the Simpsons to a family therapist.', 23, '1990-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 5, 'Bart the General', 'Terrorized by the school bully, Bart seeks counsel from Grandpa Simpson, who takes him to a warfare expert for basic training.', 23, '1990-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 6, 'Moaning Lisa', 'The meaning of life and second grade have Lisa playing the blues solo, until she jams with a kindred spirit; Homer seeks tutelage to beat Bart at video boxing.', 24, '1990-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 7, 'The Call of the Simpsons', 'The Simpsons put the wild back in the wilderness when their RV goes over a cliff and Homer and Bart go for help, get lost and lose their clothes.', 24, '1990-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 8, 'The Telltale Head', 'Bart pulls a stunt that shocks the entire town, including the new friends he was trying to impress.', 23, '1990-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 9, 'Life on the Fast Lane', 'Homer''s bowling-ball gift "for Marge" prompts her to take up the sport, and maybe also a handsome instructor who offers to teach her "many things."', 24, '1990-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 10, 'Homer''s Night Out', 'Shutterbug Bart captures Homer with a sexy entertainer at a bachelor party.', 24, '1990-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 11, 'The Crepes of Wrath', 'A little story about how Bart saves France after blowing up Principal Skinner''s mom with a cherry bomb.', 24, '1990-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 12, 'Krusty Gets Busted', 'Bart''s TV hero Krusty the Clown is arrested for a convenience-store robbery, and witness Homer must testify against the clown.', 24, '1990-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 1), 13, 'Some Enchanted Evening', 'Homer takes Marge out for a romantic night, leaving the kids with a sitter, who''s profiled on "America''s Most Armed and Dangerous."', 23, '1990-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 1, 'Bart Gets an ''F''', 'Bart fails four consecutive history exams and the school psychiatrist recommends that Bart repeat the fourth grade.', 24, '1990-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 2, 'Simpson and Delilah', 'Homer uses his medical insurance to buy Dimoxinil, a miracle hair-growth formula. After growing luxurious locks, he''s given a promotion which allows him to hire a secretary named Karl and makes grand promises to his family at home.', 24, '1990-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 3, 'Treehouse of Horror', 'The Simpson kids hide in the family treehouse and tell each other spooky stories. The first regards haunted houses, the second introduces Kang and Kodos for the first time in an alien abduction, and the third is a Simpson-adapted retelling of The Raven.', 24, '1990-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 4, 'Two Cars in Every Garage and Three Eyes on Every Fish', 'Bart catches a three-eyed fish in a river downstream of the Nuclear Power Plant. This causes the plant to become inspected, and in order to prevent it from being shut down, Mr. Burns decides to run for governor. After a hard campaign which sees Burns rise from being universally despised to running neck and neck with popular incumbent Mary Bailey, it is decided that Burns will have dinner with a random employee the night before the election. Homer is chosen, much to Marge''s chagrin.', 24, '1990-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 5, 'Dancin'' Homer', 'Homer fires up the crowd at a Springfield Isotopes baseball game and is chosen to be the team''s new mascot. He immediately becomes a popular attraction and the Isotopes start a winning streak. As a result, Homer is promoted to a team in Capital City, the Capital City Capitals.', 24, '1990-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 6, 'Dead Putting Society', 'Bart and Todd Flanders decide to enter a miniature golf tournament. Homer becomes confident that Bart will win and makes a bet with Ned that the father of the boy that does not win will have to mow their neighbors lawn in their wife''s Sunday dress. ', 24, '1990-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 7, 'Bart vs. Thanksgiving', 'Lisa makes a table centerpiece for the Thanksgiving dinner, which Bart accidentally destroys. After he is sent to his room by his parents, Bart angrily runs away from home and experiences a very different kind of Thanksgiving holiday.', 24, '1990-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 8, 'Bart the Daredevil', 'The Simpsons go to a Monster truck rally that features famous daredevil Lance Murdock. Bart immediately becomes enamored and decides that he wants to become a daredevil as well. His first stunt ends in injury, but to gain the respect of his friends, he promises a far more impressive feat to them: to jump the Springfield Gorge.', 23, '1990-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 9, 'Itchy & Scratchy & Marge', 'Maggie attacks Homer with a mallet after seeing it on Itchy & Scratchy. Marge begins a protest outside the production offices, demanding the show be retooled to prevent further violence.', 24, '1990-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 10, 'Bart Gets Hit by a Car', 'After Mr. Burns hits Bart with his car, ambulance-chasing attorney Lionel Hutz persuades Homer and Marge to sue for a million dollars.', 24, '1991-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 11, 'One Fish, Two Fish, Blowfish, Blue Fish', 'After eating poisonous blowfish at a sushi restaurant, Homer decides to live life to the fullest in the 24 hours he has left to live.', 24, '1991-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 12, 'The Way We Was', 'When the TV breaks, Marge and Homer entertain the kids with the story of how they first met.', 24, '1991-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 13, 'Homer vs. Lisa and the 8th Commandment', 'Homer becomes the most popular guy in town when he gets an illegal cable hook-up, but Lisa fears he will go to hell for violating the Eighth Commandment.', 24, '1991-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 14, 'Principal Charming', 'When Marge begs Homer to find Selma a husband, he sets her up with Principal Skinner... who falls in love with Patty instead.', 24, '1991-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 15, 'Oh Brother, Where Art Thou?', 'Homer''s long-lost half-brother is the CEO of a car company that''s wildly successful... until he hires Homer to help design a car for the average man.', 24, '1991-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 16, 'Bart''s Dog Gets an ''F''', 'After a series of destructive acts, Homer decides that Santa''s Little Helper must go unless he passes obedience school. As the dog''s last hours with the family approach, Bart must find a way to get through to him.', 24, '1991-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 2), 17, 'Old Money', 'When Grandpa''s new girlfriend at the Springfield Retirement Castle dies, he inherits her savings and must decide the best way to spend his windfall.', 23, '1991-03-28');
