INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 7), 3, 'Home Sweet Homediddly-Dum-Doodily', 'When Homer and Marge are found to be unfit parents, the kids are placed with the Flanders family. Reluctant participants in the Flanderses'' wholesome family activities, Bart and Lisa become the targets of an emergency baptism.', 23, '1995-10-01');
