INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 7), 6, 'Treehouse of Horror VI', 'In "Attack of the 50 Foot Eyesores," strange atmospheric conditions bring giant advertising statues to life. In "Nightmare on Evergreen Terrace," Groundskeeper Willie is killed in a freak accident and seeks revenge in the childrens'' dreams. In the final segment, Homer steps through a secret portal and becomes three-dimensional.', 23, '1995-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 7), 7, 'King-Size Homer', 'Homer tries to gain sixty pounds so he can stay home on disability. When he nearly causes a catastrophe at the plant, Homer reconsiders his plan.', 23, '1995-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 7), 8, 'Mother Simpson', 'Homer discovers that his mother is still alive, a former radical who is a fugitive from the law. When her old nemesis Burns spots her and tips off the FBI, she is forced to return to the underground.', 23, '1995-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 7), 9, 'Sideshow Bob''s Last Gleaming', 'After Sideshow Bob escapes from prison, the Springfield Air Show is the setting for his ill-fated vendetta against television and Krusty the Clown.', 23, '1995-11-26');
