INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 8), 24, 'The Simpsons Spin-Off Showcase', 'Troy McClure presents three Simpsons spinoff spoofs: In "Chief Wiggum, P.I.," Chief Wiggum becomes a New Orleans detective. Next, Grampa Simpson''s soul is trapped inside Moe''s Love tester machine in "The Love-Matic Grampa." Finally, the Simpson family hosts a ''70s-style variety show.', 23, '1997-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 8), 25, 'The Secret War of Lisa Simpson', 'Lisa joins the all-male military school where Bart is sent for discipline. Then comes the hazing.', 23, '1997-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 1, 'The City of New York vs. Homer Simpson', 'Designated driver Barney absconds to Manhattan in Homer''s car and leaves it there. But when the family journeys to the Big Apple to retrieve their property, Homer discovers his car has been booted.', 23, '1997-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 2, 'The Principal and the Pauper', 'Unmasked as an impostor, Principal Skinner flees to Capital City to reclaim his former life as a shiftless good-for-nothing. The people of Springfield gain a newfound appreciation for him and form a plan to bring him back.', 23, '1997-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 3, 'Lisa''s Sax', 'After Lisa’s saxophone is destroyed, the Simpsons reminisce about how she originally got the instrument. On the hottest day of the year, Homer must decide whether to buy an air conditioner or replace Lisa’s sax.', 23, '1997-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 4, 'Treehouse of Horror VIII', 'In “The Homega Man,” Homer faces a post-apocalyptic Springfield. Next, Bart attempts to become Superfly in "Fly vs. Fly." In “Easy-Bake Coven,” amidst a witch hunt in 1649, Marge and her sisters invent trick-or-treating.', 23, '1997-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 5, 'The Cartridge Family', 'Alarmed by a soccer riot, Homer buys a handgun. His reckless behavior drives Marge and the kids out of the house, and even his new gun club buddies desert him.', 23, '1997-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 6, 'Bart Star', 'When Homer becomes the coach of a peewee football team, he replaces star quarterback Nelson with the less talented Bart. Facing his teammates’ scorn, Bart looks for a way out but finds a better way to show his team spirit.', 23, '1997-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 7, 'The Two Mrs. Nahasapeemapetilons', 'Trying to escape his arranged marriage, Apu asks Marge to pose as his wife during his mother’s visit. When the ruse fails, Homer makes a last-ditch attempt to intervene, but Apu is smitten with his new bride Manjula.', 23, '1997-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 8, 'Lisa the Skeptic', 'When a skeleton is unearthed at the site of a future shopping mall, all Springfield is convinced it is the skeleton of an angel – except Lisa.', 23, '1997-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 9, 'Realty Bites', 'When Marge gets her real estate license, she learns to put a positive spin on the flaws of the houses she’s selling. But when the Flanders buy the Murder House, she realizes she has to tell the truth.', 23, '1997-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 10, 'Miracle on Evergreen Terrace', 'After accidentally ruining the family’s Christmas tree and presents, Bart buries the evidence and claims a burglar stole everything. When Kent Brockman does a human interest story on the family’s tragic loss, the townspeople shower the family with generosity… until the truth comes out.', 23, '1997-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 11, 'All Singing, All Dancing', 'Homer rents a Clint Eastwood movie and is dismayed to find it''s a musical. Using clips from past episodes, the rest of the family reminds him about the many times he and other members of the family and town have broken into song and dance.', 23, '1998-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 12, 'Bart Carny', 'When the carnival comes to town, Homer and Bart wind up working the ring toss. A father-son team of grifters shows them the downside of the “carny code,” but the Simpsons beat them at their own game.', 23, '1998-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 13, 'The Joy of Sect', 'A cult lures in most of Springfield to toil for “The Leader.” After Marge escapes and has the family deprogrammed, Homer exposes the man behind the spaceship.', 23, '1998-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 14, 'Das Bus', 'When Otto drives the school bus off a bridge, the kids wind up on a deserted island, fending for themselves in a “Lord of the Flies” parody. Back in Springfield, Homer takes on Bill Gates.', 23, '1998-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 15, 'The Last Temptation of Krust', 'Krusty bombs at a charity comedy event and feels like a tired old hack. With the Simpsons’ support, Krusty takes his act in a fresh new direction… but in the end, his true nature asserts itself.', 23, '1998-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 16, 'Dumbbell Indemnity', 'Moe goes broke trying to wine and dine a new girlfriend. Desperate for money, he cooks up an insurance scam with Homer.', 23, '1998-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 17, 'Lisa the Simpson', 'Lisa struggles with solving a simple puzzle and fears that the "Simpson gene” is suddenly wiping out her intelligence. Homer stages a family reunion in hopes of introducing Lisa to some Simpsons she can respect.', 23, '1998-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 18, 'This Little Wiggy', 'At Marge’s insistence, Bart has a “play date” with Ralph. Bart suddenly sees the upside of this friendship when he discovers Chief Wiggum’s “master key” and goes to explore Springfield’s abandoned prison.', 23, '1998-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 19, 'Simpson Tide', 'When Homer joins the Naval Reserve, a captain takes a liking to him and leaves him in charge of a nuclear submarine.', 23, '1998-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 20, 'The Trouble with Trillions', 'Facing an IRS audit, Homer agrees to help the feds bust Mr. Burns for a missing trillion-dollar bill. When Burns makes an anti-government stand, Homer flees with him to Cuba.', 23, '1998-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 21, 'Girly Edition', 'Lisa becomes the anchor of a kids’ news program but is upstaged by Bart’s treacly human interest stories. At home, Homer corrupts a helper monkey.', 23, '1998-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 22, 'Trash of the Titans', 'Homer feuds with the Springfield garbage men and decides to run for Sanitation Commissioner. After winning the election with a sleazy campaign, Homer can’t keep the extravagant promises he made to the town.', 23, '1998-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 23, 'King of the Hill', 'After Rainier Wolfcastle helps Homer get in shape, Homer accepts a challenge to climb the Murderhorn, the tallest mountain in Springfield.', 23, '1998-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 24, 'Lost Our Lisa', 'Bart’s latest stunt thwarts Lisa’s plan to attend a museum exhibit. When she tries to go alone and takes the wrong bus, Homer sets out to find her.', 23, '1998-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 9), 25, 'Natural Born Kissers', 'Homer and Marge try to spice up their love life and are caught baring it all in public. Bart and Lisa discover an alternate ending to Casablanca.', 23, '1998-05-17');
