INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 1, 'Lard of the Dance', 'Homer and Bart try to make money by selling used grease. Meanwhile, Lisa organizes a school dance but feels alienated when a new classmate and her friends try to act like adults.', 23, '1998-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 2, 'The Wizard of Evergreen Terrace', 'A midlife crisis prompts Homer to quit his job and become an inventor.', 23, '1998-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 3, 'Bart the Mother', 'Under Nelson''s bad influence, Bart shoots a bird with a BB gun. Stricken with remorse, he tries to nurture the eggs from the bird''s nest, which hatch into a species of lizard outlawed in Springfield.', 23, '1998-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 4, 'Treehouse of Horror IX', 'In "Hell Toupée," Snake is sent to the electric chair, and his hair is transplanted onto Homer. In "The Terror of Tiny Toon," Bart and Lisa become cartoon characters in an episode of Itchy & Scratchy. In "Starship Poopers," a growth spurt casts doubt on Maggie''s paternity, and the family goes on the Jerry Springer show.', 23, '1998-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 5, 'When You Dish Upon a Star', 'After a chance encounter with Hollywood celebrities secretly living in Springfield, Homer becomes their friend and gofer... until he spills the beans to the gang at Moe''s.', 23, '1998-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 6, 'D''oh-in'' in the Wind', 'In a quest to learn Homer''s middle name, Homer and Grandpa travel to his mother''s old commune, where Homer embraces the hippie life.', 23, '1998-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 7, 'Lisa Gets an ''A''', 'Stuck at home with a cold, Lisa gets addicted to a video game and neglects her homework. Her A+++ on a test wins the school a grant, but when she confesses that she cheated, Skinner covers it up. Meanwhile, Homer raises a lobster.', 23, '1998-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 8, 'Homer Simpson in: ''Kidney Trouble''', 'When Grandpa needs a new kidney, Homer agrees to donate one, but then chickens out.', 23, '1998-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 9, 'Mayored to the Mob', 'After a riot at a sci-fi convention, Mayor Quimby hires Homer as his bodyguard, and Homer witnesses the rampant corruption in town politics. When Homer takes a stand, he runs afoul of the Springfield mafia.', 23, '1998-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 10, 'Viva Ned Flanders', 'When clean-living Ned Flanders wants to experience a new side of life, Homer takes him to Las Vegas. After a drunken binge, they marry a pair of cocktail waitresses.', 23, '1999-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 11, 'Wild Barts Can''t Be Broken', 'Scapegoated for the vandalism of drunken Isotopes fans, the children of Springfield wage war on the adults by broadcasting their secrets on the radio.', 23, '1999-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 12, 'Sunday, Cruddy Sunday', 'Homer and his friends charter a bus to the Super Bowl, only to find that their tickets are fake. Misadventures ensue.', 23, '1999-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 13, 'Homer to the Max', 'A new TV series features a suave and debonair character named Homer Simpson. Homer capitalizes on his new namesake, until the character is rewritten to be a bumbling fool. Trying to recapture the positive attention he enjoyed, Homer changes his name to "Max Power."', 23, '1999-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 14, 'I''m with Cupid', 'Apu is making the husbands of Springfield look bad with his extravagent Valentine''s Day efforts for Manjula. When the men try to sabotage Apu''s grand gesture, they accidentally wind up benefiting from it.', 23, '1999-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 15, 'Marge Simpson in: ''Screaming Yellow Honkers''', 'A new Canyonero SUV turns timid Marge into an aggressive driver, and her road rage lands her in traffic school. But when a stampede occurs at the zoo, the town looks to Marge to save the day.', 23, '1999-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 16, 'Make Room for Lisa', 'Indebted from a mishap at the Smithsonian, Homer lets a cell phone company put a transmitter in the house. Forced to share a room with Bart, Lisa resents Homer until a New Age experience gives her empathy.', 23, '1999-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 17, 'Maximum Homerdrive', 'After beating Homer in a steak-eating competition, a trucker dies; Homer and Bart take over his rig to complete his shipment.', 23, '1999-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 18, 'Simpsons Bible Stories', 'When Reverend Lovejoy subjects the congregation to an extended Bible reading, the Simpsons fall asleep and have dreams based on Bible stories.', 23, '1999-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 19, 'Mom and Pop Art', 'Homer''s failed do-it-yourself project gets mistaken for "outsider art." Suddenly in the limelight, Homer must come up with new "works" to impress the art world.', 23, '1999-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 20, 'The Old Man and the ''C'' Student', 'When Bart ruins Springfield''s chance to host the Olympics, the kids are sentenced to community service work at the retirement home. To help the residents recapture their youth, Bart takes them on an ill-fated boat ride.', 23, '1999-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 21, 'Monty Can''t Buy Me Love', 'A new mogul wins the hearts of the townspeople with a shower of cash. Jealous, Mr. Burns asks Homer to help make him a beloved billionaire too, and they hatch a plan to bring the Loch Ness Monster to Springfield.', 23, '1999-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 22, 'They Saved Lisa''s Brain', 'Mayor Quimby flees Springfield, leaving the town chapter of Mensa in charge. As the group''s new power goes to their heads, they take their utopian plans too far and the townspeople revolt.', 23, '1999-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 10), 23, 'Thirty Minutes Over Tokyo', 'After their bank account is drained at a cyber-cafe, the Simpsons go on a disastrous low-budget trip to Japan, where they wind up as contestants on a humiliating game show.', 23, '1999-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 1, 'Beyond Blunderdome', 'Homer befriends Mel Gibson just as Mel is completing a remake of Mr. Smith Goes To Washington. Homer convinces Mel to make the film more violent, with disastrous results.', 23, '1999-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 2, 'Brother''s Little Helper', 'When Bart commits an extremely destructive prank, he is given Focusyn, a pill to help him concentrate in school. At first the results are impressive, and then Bart starts believing in a conspiracy involving spy satellites and major league baseball.', 23, '1999-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 3, 'Guess Who''s Coming to Criticize Dinner?', 'With Lisa''s help, Homer uses his vast knowledge of food to become the town''s leading restaurant critic. But when he gets petty and vindictive in his criticisms, all the other chefs in town try to kill him.', 23, '1999-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 4, 'Treehouse of Horror X', 'In "I Know What You Diddily-Iddly-Did" the Simpsons fear they have killed Ned Flanders. "Desperately Xeeking Xena" satirizes superheroes of yore with "Stretch Dude" Bart and "Clobber Girl" Lisa. And "Life''s A Glitch, Then You Die" depicts the upcoming horror of Y2K.', 23, '1999-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 5, 'E-I-E-I-(Annoyed Grunt)', 'Fleeing from a duel, Homer takes his family to live on a farm. There he discovers that by mixing tomatoes, tobacco and radioactivity from the nuclear plant, he can create a dangerously delicious new substance.', 23, '1999-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 6, 'Hello Gutter, Hello Fadder', 'Homer bowls a perfect 300 game, then concludes that the greatest accomplishment of his life is behind him. He reconnects with the world by bonding with baby Maggie.', 23, '1999-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 7, 'Eight Misbehavin''', 'Due to overuse of fertility medication, Apu and wife Manjula give birth to octuplets. Desperate for money, Apu loans the babies to an unscrupulous carny promoter, then needs Homer''s help to get them back.', 23, '1999-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 8, 'Take My Wife, Sleaze', 'After winning a motorcycle at a dance contest, Homer becomes part of a motorcycle gang. But when he puts Marge''s photo in a biker magazine, a much tougher gang takes her, and he must win her back.', 23, '1999-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 9, 'Grift of the Magi', 'In this Christmas-themed episode, the students of Springfield Elementary are unwittingly used as a focus group to test new toys. The product of their labors, a cuddly doll named Funzo, is a lot more sinister than he appears.', 23, '1999-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 10, 'Little Big Mom', 'When Marge leaves the house to recuperate from a skating injury, everything goes to hell - until Lisa convinces Homer and Bart they have leprosy.', 23, '2000-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 11, 'Faith Off', 'Homer gets a bucket stuck on his head, and when it is removed the town is convinced that Bart has the powers of a faith healer. Then mobster Fat Tony tries to turn the boy''s spiritual abilities into more sinister directions.', 23, '2000-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 12, 'The Mansion Family', 'Worried about his health, Mr. Burns visits the Mayo Clinic. He lets Homer housesit his mansion, which leads of course to an offshore knife fight and an attack by Chinese pirates.', 23, '2000-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 13, 'Saddlesore Galactica', 'Homer and Bart befriend a diving horse at a county fair. They turn it into a racehorse with an attitude, whose success runs them afoul of mysterious, tree-dwelling jockeys.', 23, '2000-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 14, 'Alone Again, Natura-Diddily', 'Ned''s wife Maude is inadvertently killed by a T-shirt accident at an auto race. Homer and his family try to help Ned cope.', 23, '2000-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 15, 'Missionary: Impossible', 'When Homer fails to give money he promised over the phone, he is forced by PBS stars to flee the country. He becomes a missionary on a small tropical island, where he introduces the natives to casino gambling.', 23, '2000-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 16, 'Pygmoelian', 'Plastic surgery gives Moe the bartender a handsome new face and a whole new life as a soap opera star.', 23, '2000-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 17, 'Bart to the Future', 'We see a possible future in which Bart is a grown-up slacker, living with Ralph Wiggum, while Lisa is no less than President of the United States.', 22, '2000-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 18, 'Days of Wine and D''oh''ses', 'After being embarrassed by a drunken video of himself, Barney vows to sober up. Newly clean, he gets work as a helicopter pilot.', 23, '2000-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 19, 'Kill the Alligator and Run', 'After a terrible bout with insomnia, Homer takes the family to Florida during spring break. There, they kill a beloved alligator and are sentenced to a chain gang.', 23, '2000-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 20, 'Last Tap Dance in Springfield', 'Lisa enters a tap dancing academy, where the teacher is a child star who never quite grew up. Meanwhile, Homer gets laser eye surgery.', 23, '2000-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 21, 'It''s a Mad, Mad, Mad, Mad Marge', 'Otto''s girlfriend seems to be usurping Marge''s role when she moves in with the family after a dispute over heavy metal.', 23, '2000-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 11), 22, 'Behind the Laughter', 'A "Behind the Music"-style look at the Simpsons, narrated by VH1''s Jim Forbes, shows their rise to stardom--and the "private hell" that followed.', 23, '2000-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 1, 'Treehouse of Horror XI', 'This year''s Halloween story sees The Simpsons as "The Munsters" (with everyone except Lisa getting killed), Homer as a wandering spirit on the hunt for a good deed in "G-G-Ghost D-D-Dad," Bart and Lisa as peasants in a fairy tale forest in "Scary Tales Can Come True," and Lisa inadvertently dooming mankind by rescuing a dolphin in "Night of the Dolphin."', 23, '2000-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 2, 'A Tale of Two Springfields', 'While calling Animal Control over a badger taking residence in Santa''s Little Helper''s doghouse, Homer discovers that Springfield has two different area codes–and ends up leading a revolt that splits the town in two.', 22, '2000-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 3, 'Insane Clown Poppy', 'Krusty takes parenting lessons from Homer when, during an outdoor book fair, a girl tells Krusty that she is his long-lost daughter from a one-night stand with a female soldier who fought during the first Gulf War.', 23, '2000-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 4, 'Lisa the Tree Hugger', 'Lisa falls for the teenaged leader of a militant environmentalist group and tries to impress him by living in Springfield''s oldest tree in order to keep it from being cut down.', 23, '2000-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 5, 'Homer vs. Dignity', 'When the Simpsons once again have financial problems, Mr. Burns pays Homer to play pranks on others and humiliate himself in public. Meanwhile, Smithers creates a Malibu Stacy-themed musical.', 22, '2000-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 6, 'The Computer Wore Menace Shoes', 'Homer decides to buy a computer after turning up to the Plant to find it closed by e-mail. He then creates his own website and it eventually gains attention when he posts gossip. Homer dubs himself as "Mr. X" to conceal his identity. When he reveals that he is Mr. X, he becomes drugged into a mysterious island where people who know too much are imprisoned after Homer starts writing conspiracy theories such as flu shots.', 23, '2000-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 7, 'The Great Money Caper', 'Homer and Bart become father–son con artists (after Bart is given money out of pity when Homer decided to not take him home), but soon find that they are the ones being had.', 23, '2000-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 8, 'Skinner''s Sense of Snow', 'A snowstorm traps the students of Springfield Elementary inside, with them overthrowing Principal Skinner when he uses his Army skills to control them. Meanwhile, Homer tries to rescue the children–using Flanders'' car.', 24, '2000-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 9, 'HOMЯ', 'While working as a human guinea pig (to pay off the family''s lost savings after making a bad investment), Homer discovers the root cause of his subnormal intelligence: a crayon that was lodged in his brain ever since he was a boy. He decides to have it removed to increase his IQ, but discovers that being smart does not necessarily equal being happy.', 23, '2001-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 10, 'Pokey Mom', 'Marge tries to rehabilitate a convict with remarkable artistic talent. Meanwhile, Homer uses a trash can to fix people''s spines.', 23, '2001-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 11, 'Worst Episode Ever', 'Bart and Milhouse are banned from The Android Dungeon after stopping Comic Book Guy from buying a box of priceless Star Wars memorabilia for $5, but are hired as his replacements when Comic Book Guy has a heart attack and is advised to leave his job in order to make friends.', 23, '2001-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 12, 'Tennis the Menace', 'While making funeral arrangements for Grampa''s future, the funeral planner pitches the idea of a mausoleum that uses the same amount of cement as a full-sized tennis court. This prompts Homer to instead build a tennis court in his backyard, initially mistaking the sport for "Foxy Boxing". The tennis court makes Marge and Homer popular in town, but it turns out that this is only because Homer''s inferior tennis ability makes them an easy target. Bart on the other hand, shines as a natural.', 23, '2001-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 13, 'Day of the Jackanapes', 'Krusty announces his retirement due to interference from network executives and the growing popularity of the big-money game show "Me Wantee", but when Krusty reveals to Sideshow Bob that all of the episodes featuring him have been erased, Sideshow Bob uses Krusty''s biggest fan (Bart) to murder him during Krusty''s farewell show.', 23, '2001-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 14, 'New Kids on the Blecch', 'A music producer selects Bart, Nelson, Milhouse and Ralph to be members of the next hit boy band, who record subliminal songs about joining the Navy.', 23, '2001-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 15, 'Hungry, Hungry Homer', 'Homer becomes a Good Samaritan after discovering the simple joys of helping people in need–which is put to the test when he goes on a hunger strike after the owner of the Springfield Isotopes attempts to discredit him when Homer stumbles on his plot to discreetly move the team to Albuquerque, New Mexico.', 23, '2001-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 16, 'Bye Bye Nerdie', 'When Lisa becomes the target of a female bully, Lisa discovers a scientific reason as to why bullies pick on nerds. Meanwhile, Homer goes into the baby-proofing business, which is threatening the businesses of pediatricians and greeting card salesmen.', 23, '2001-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 17, 'Simpson Safari', 'When the Simpsons run out of food thanks to a bag boy strike (caused by Homer), the family finds an old box of animal crackers with a sweepstakes that sends The Simpsons to Africa.', 23, '2001-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 18, 'Trilogy of Error', 'Homer''s rush to the hospital to reattach his thumb, Lisa''s rush to school to win the science fair, and Bart''s run-in with an illegal fireworks scheme are interconnected in a parody of Go and Run Lola Run.', 23, '2001-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 19, 'I''m Goin'' to Praiseland', 'After finding a sketchbook belonging to his late wife Maude, Ned Flanders opens a Bible-themed amusement park to honor her memory.', 23, '2001-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 20, 'Children of a Lesser Clod', 'After spraining his knee during a basketball game, Homer begins taking care of the neighborhood kids to cure his boredom, prompting jealousy from Bart and Lisa, who feel that Homer is giving the kids the attention they never had.', 23, '2001-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 12), 21, 'Simpsons Tall Tales', 'When Homer refuses to pay a five dollar airport tax to fly to Delaware, the family is forced to ride in a livestock car of a train instead. There they meet a singing hobo who tells three tall tales:  Homer as Paul Bunyan.  Lisa as Connie Appleseed, a parody of Johnny Appleseed.  Bart as Tom Sawyer with Nelson as Huckleberry Finn.', 23, '2001-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 1, 'Treehouse of Horror XII', 'In the twelfth Treehouse of Horror episode:
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 2, 'The Parent Rap', 'Bart gets in trouble for joyriding in a police car, but feels confident he will be let off by Judge Snyder. However, Snyder goes on vacation before ruling his verdict and is replaced with a coldhearted judge named Constance Harm. She accuses Homer of being a negligent father and sentences him to be tethered to Bart. The two are against it at first but later start to bond. Marge however is unable to take anymore of it and slices the tether off of them both. Homer and Marge then go after Judge Harm only to end up sinking her houseboat. Eventually Bart decides to take punishment and is about to be sentenced to 5 year in juvenile hall, only though Judge Snyder returns and dismisses Harm.', 23, '2001-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 3, 'Homer the Moe', 'Moe becomes depressed and decides to return to bartending school so he can re-evaluate himself. He meets an old teacher, who suggests that Moe try improving his bar, which might make him happier. Moe takes the advice, and turns his bar into a trendy nightclub, which does not sit well with his regular customers Homer, Lenny, Carl, and Barney.', 23, '2001-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 4, 'A Hunka Hunka Burns in Love', 'Homer becomes a fortune cookie writer for a Chinatown restaurant. Mr. Burns reads one of Homer''s fortunes, which says that the reader will find love before Flag Day is over. Burns goes searching for love and meets Gloria, a meter maid, and asks her out. Gloria reluctantly agrees, and Burns recruits Homer to help him look young and hip to his new girlfriend.', 23, '2001-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 5, 'The Blunder Years', 'After tricking Marge into thinking an advertising spokesman is coming to visit her, Homer takes Marge and the rest of the family to a restaurant. A hypnotist uses his powers on Homer, and makes him remember a horrific childhood incident where Homer found a dead body in a ravine. The Simpson family decides to investigate this and find out where the body came from.', 23, '2001-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 6, 'She of Little Faith', 'After Homer and Bart''s model rocket damages the church, Mr. Burns makes a deal to commercialize the church in return for paying for the damages. Lisa becomes disgusted at what the church has become, so she decides to find a new religion suitable for her. She eventually converts to Buddhism, causing Marge to fear for Lisa''s soul.', 23, '2001-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 7, 'Brawl in the Family', 'A social worker is assigned to make the Simpson family functional after they get arrested for fighting while playing Monopoly. He helps them learn how to work together and function as a family. The moment is ruined when, Ginger and Amber, the barmaids who married Homer and Flanders while they were drunk in "Viva Ned Flanders", arrive at the Simpsons'' home, which outrages Marge.', 23, '2002-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 8, 'Sweets and Sour Marge', 'Springfield is officially declared the World''s Fattest Town after an attempt to break a world record lands everyone on top of a truck scale. Out of embarrassment and disgust, Marge goes on a crusade against the local sugar corporation. However, when sugar is banned, Homer, Bart, Mr. Burns and Apu start bootlegging sugar.', 23, '2002-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 9, 'Jaws Wired Shut', 'A jaw injury from colliding with a new town statue turns Homer into a better listener while recuperating with his jaws wired shut, but once the wires come off, Homer does not go back to being loud and obnoxious and Marge becomes starved for thrills.', 23, '2002-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 10, 'Half-Decent Proposal', 'Homer develops a snoring problem, so Marge decides to spend a night with her sisters Patty and Selma. After a night of drinking, Marge sees a news report about her ex-prom date Artie Ziff, who is now very wealthy, and decides to send him an e-mail. Artie is still obsessed with Marge, so he offers the Simpsons $1 million in exchange for Marge spending a weekend with him.', 23, '2002-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 11, 'The Bart Wants What It Wants', 'Bart befriends Rainer Wolfcastle''s daughter Greta. She has a crush on Bart, but he does not seem to realize it and eventually stops seeing her. Seeking revenge, Greta begins dating Bart''s best friend Milhouse, which causes Bart to start missing her. She leaves for Toronto with her father, and Bart convinces his family to follow them there.', 23, '2002-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 12, 'The Lastest Gun in the West', 'While running away from a vicious dog, Bart meets Buck McCoy, a former Western film star. Bart begins hanging out with him and starts to idolize him. Bart wants to help McCoy stage a comeback, so he convinces all of the kids in town to become interested in the Wild West. McCoy appears on the Krusty the Clown Show, but the comeback flops when Buck begins drinking again and injures Krusty the Clown.', 23, '2002-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 13, 'The Old Man and the Key', 'Grampa falls in love with Zelda, a woman who has an interest in men who can drive. He decides to get his driver''s license back, but is ignorant to Homer and Marge''s concerns that she is only using him for his car.', 22, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 14, 'Tales from the Public Domain', 'When Homer gets a notice from the library that he has a book of classic tales that is years overdue, he finds it on the shelf and reads three stories: The Odyssey (where Homer and his bar buddies try to get home after fighting the Trojans), Joan of Arc (where Lisa leads the French against the English with the help of God), and Hamlet (where Bart tries to kill Moe after Moe kills Homer in order to marry Marge).', 23, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 15, 'Blame It on Lisa', 'When Homer gets the family''s telephone service cut off for refusing to pay for calls made to Rio de Janeiro, Brazil, Lisa confesses that she was the one who called Rio after sponsoring an orphan who goes missing. She convinces the family to travel to Brazil to look for him. However, once there, they have no luck finding him, and Homer is kidnapped.', 23, '2002-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 16, 'Weekend at Burnsie''s', 'Homer is prescribed medicinal marijuana after getting pecked in the eyes by a murder of crows. While his family and friends worry about the drug altering his personality, Homer becomes Mr. Burns''s vice president after cracking up at Burns''s antiquated jokes.', 23, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 17, 'Gump Roast', 'In this clip show episode, Homer is honored at a Friars'' Club Roast. A number of characters show up to roast him, but the celebrating is interrupted by Kang and Kodos, who say that humanity will be judged based on Homer''s experiences.', 22, '2002-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 18, 'I Am Furious (Yellow)', 'Inspired by a cartoonist who speaks at the school as part of a career day assembly, Bart creates a comic book series based on Homer and his anger problems, which turns into a popular Internet cartoon series called Angry Dad. Homer finds out about this and is at first outraged, but after talking to his family, he decides to try to become a less angry person.', 23, '2002-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 19, 'The Sweetest Apu', 'Homer and Marge discover that Apu is having an affair with the Squishee delivery lady at the Kwik-E-Mart. They decide to keep Apu''s wife Manjula from finding out about it. However, she eventually learns of Apu''s affair by watching store security tapes. She throws Apu out of the house and decides to file for divorce, but soon realizes that she misses him.', 22, '2002-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 20, 'Little Girl in the Big Ten', 'Lisa tries to fit in with two college students by lying about her age. She finds that the college atmosphere is perfect for her, but her lie is soon discovered and she is shunned by her fellow elementary school students. Meanwhile, Bart is diagnosed with a weakened immune system after getting bitten by a Chinese mosquito and must live in a plastic, germ-free bubble.', 23, '2002-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 21, 'The Frying Game', 'While faced with community service for abusing an endangered insect, Homer begins assisting an elderly woman named Mrs. Bellamy. One night, Mrs. Bellamy is murdered, and Homer and Marge are accused of committing the crime.', 22, '2002-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 13), 22, 'Poppa''s Got a Brand New Badge', 'Homer starts a security company with Lenny and Carl after the police are ineffective during a blackout, and eventually Mayor Quimby decides to have them replace the police. Homer finds that he excels at the job, but then he runs afoul of mob boss Fat Tony, who threatens Homer with death unless he leaves town.', 23, '2002-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 14, 'Season 14', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 1, 'Treehouse of Horror XIII', 'The 13th Treehouse of Horror episode, consisting of three self-contained segments.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 2, 'How I Spent My Strummer Vacation', 'A drunken Homer appears on the show Taxicab Conversations and rants about how awful his life as a husband and father is. Although his family is at first outraged, they realise that they do somewhat burden him and decide to make up for it by sending him to a Rock ''n Roll Fantasy Camp where he mingles with rock stars, including Mick Jagger and Keith Richards. The rock stars ask Homer to help out at a concert and, expecting that he will be allowed to perform, he accepts. Actually, they want him to test the microphones; however, a humiliated Homer grabs a guitar and starts playing.', 23, '2002-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 3, 'Bart vs. Lisa vs. the Third Grade', 'The Simpsons buy a satellite television, which Bart spends so much time watching that he does not study for an important achievement test. He scores so low that Principal Skinner demotes him to third grade, while Lisa does so well that she is moved up to third grade. The two are placed in the same class and become rivals. During a trip to Capital City, they get separated from their class and are forced to help each other in order to find their classmates.', 22, '2002-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 4, 'Large Marge', 'Thinking Homer does not find her attractive anymore, Marge decides to get liposuction, but instead receives breast implants. She becomes adored by many of the men in Springfield, and becomes a spokesmodel for trade shows. Meanwhile, Bart and Milhouse try to imitate a stunt they saw on an episode of Batman that guest stars Krusty the Clown. When the stunt ends badly, media watchdog groups blame Krusty, forcing the clown to make his show more safety-conscious and less fun.', 23, '2002-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 5, 'Helter Shelter', 'The Simpson family has to find temporary residence while their house is fumigated for termites. When they run out of options, they decide to become contestants on a reality show where families live in the manner that people did in 1895. The family is initially miserable, but slowly adapt to their new life, which causes the show to lose ratings. The producers decide to try to boost viewers by dumping the house in a river and forcing the family to survive in the wilderness. However, the Simpsons find a bunch of rejects from other reality shows and they attack the producers.', 23, '2002-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 6, 'The Great Louse Detective', 'The Simpson family win a free spa weekend, and Homer is nearly killed when a mysterious figure locks him in a sauna. Chief Wiggum decides to hire someone who can think like a murderer in order to find one. Bart''s mortal enemy Sideshow Bob is sent to live with the Simpsons so he can help find Homer''s attempted killer. Bob and Homer track down the attempted murderer and discover that it is Frank Grimes, Jr., the son of a man that Homer drove to insanity (in the season eight episode "Homer''s Enemy"). After Grimes is arrested, Bob tries to kill Bart, but he finds that he has "grown accustomed to [his] face" and cannot harm him.', 23, '2002-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 7, 'Special Edna', 'Ms. Edna Krabappel begins to lose faith in her relationship with Principal Skinner and becomes depressed. Bart wants to cheer her up and decides to nominate her for the Teacher of the Year Award. Ms. Krabappel and the Simpsons are given a free trip to Epcot Center in Orlando, Florida. Skinner decides that he needs to do something to win Edna back, so he follows them there. He tries to sabotage Edna''s chances of winning the award, in hopes that she will become so depressed that she will come back to him. However, he has a change of heart and proposes to her.', 23, '2003-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 8, 'The Dad Who Knew Too Little', 'Homer hires a private detective to learn more about Lisa. But when Homer refuses to pay the detective''s expenses, he frames Lisa for a crime she didn''t commit, forcing her and Homer to go on the run.', 23, '2003-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 9, 'The Strong Arms of the Ma', 'Marge gets mugged and becomes so traumatized that she develops Agoraphobia. She hides in the basement. Having little else to do, she decides to exercise with a weight set Homer bought from Rainier Wolfcastle''s garage sale. She becomes so strong and confident that she is able to leave the basement. She continues working out and decides to start taking steroids so she can enter a bodybuilding competition. One night at Moe''s Tavern she loses her temper and starts destroying the bar and fighting all of the patrons. Homer confronts Marge and says he misses the sweet woman that he married. Marge, horrified at what she has done, apologizes and decides to stop working out.', 22, '2003-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 10, 'Pray Anything', 'Homer becomes depressed when he sees that Ned Flanders seems to be better off than him. To remedy this, he begins to pray constantly. Meanwhile, the Simpsons discover that tree roots have clogged up their plumbing. The house becomes too run down to live in, and Homer prays for a solution. Homer is injured while attending church; he sues Reverend Lovejoy and is awarded the deed to the church. He throws a huge house-warming party, in which all of the partiers drink and engage in sinful activities. It suddenly starts raining and the town begins to flood. The townspeople flee to the roof of the church. Homer tries praying again but the flood keeps rising. Reverend Lovejoy returns in a helicopter and leads everyone in prayer, asking God to forgive them, and the rain stops.', 22, '2003-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 11, 'Barting Over', 'Bart learns that he was once a child actor in commercials and that all the money earned was spent by Homer. In retaliation, Bart petitions the court to have himself legally emancipated from his parents and moves out of the Simpson house. Bart is initially miserable in his new apartment, but discovers that skateboarder Tony Hawk lives on one of the floors above. He and Hawk become friends, and Bart is content with his new life. Homer apologizes to Bart and requests that he return home. Bart accepts the apology, but tells his family that he is going on tour with Hawk. At an event, Homer speaks to Bart and finally promises Bart that he will never treat him badly again.', 23, '2003-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 12, 'I''m Spelling as Fast as I Can', 'Lisa competes at a spelling bee and earns the right to compete in the Spell-lympics, becoming the pride of the town. The host of the show George Plimpton, asks her to intentionally lose so that a more popular boy can win. Lisa refuses and continues to compete, but accidentally misspells a word and loses. Meanwhile, Homer tours with a group obsessed with eating Krusty Burger''s latest sandwich.', 23, '2003-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 13, 'A Star is Born-Again', 'During the annual Jellyfish Festival, Ned Flanders realizes that he is lonely and becomes depressed. One night, he meets a beautiful woman, who asks him out on a date. He soon learns that the woman is Sara Sloan, a famous actress. Sloan is charmed by Flanders'' wholesomeness, and they continue to date to the point at which she asks that he move to Hollywood. Flanders, worried that Hollywood would conflict with his conservative Christian values, refuses, so Sloan instead decides to stay in Springfield. However, their relationship does not work out, due to his insistence on marriage.', 23, '2003-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 14, 'Mr. Spritz Goes to Washington', 'An air traffic route is redirected so that airplanes start flying directly over the Simpsons'' house. The noise starts to disrupt their lives and, desperate for a solution, the family turns to their Congressman. However, he dies of a heart attack, so they ask Krusty the Clown to run for Congress so that he can help them. Krusty is successful in his campaign, but finds that his air traffic bill is ignored by the veteran Congressmen. He soon becomes disillusioned with the system, so the Simpsons, with guidance from Walter Mondale, help him out by blackmailing one of his opponents and attaching the bill to a more popular one. The bill passes, and the air traffic is re-routed.', 23, '2003-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 15, 'C. E. D''oh', 'Homer decides to try for a promotion at Springfield Nuclear Power Plant and suggests several ideas to Mr. Burns, all of which are rejected. One night, Homer overhears Burns admit that the plant''s real owner is a canary to protect Burns from responsibility for any wrongdoing by the power plant. Homer releases the bird and tells Burns that nuclear inspectors have arrived for a surprise inspection. Burns, desperate to find a scapegoat, names Homer the new owner. As his first act, Homer fires Burns and takes control of the Plant. However, he finds that his work life as a CEO is conflicting with his family life. Homer decides to return to his old job and gives ownership back to Burns.', 23, '2003-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 16, '''Scuse Me While I Miss the Sky', 'A snobby British filmmaker named Declan Desmond begins making a documentary about student life at Springfield Elementary School. When introduced to Lisa, he tells her that she has too many goals and suggests that she pick one career. Lisa focuses on astronomy, but cannot watch the stars because of light pollution. She convinces Mayor Quimby to decrease the light''s intensity during the night, which only results in an increase in the crime rate. Quimby bows to public pressure and switches the lights back on permanently. Lisa overloads the generators at the Power Plant, causing a power outage, and is able to watch a meteor shower undisturbed by light.', 23, '2003-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 17, 'Three Gays of the Condo', 'After yet another Homer and Marge fight, Homer ends up sharing a condo with two homosexuals - who don''t exactly think Homer is straight.', 23, '2003-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 18, 'Dude, Where''s My Ranch?', 'When challenged to think up a new Christmas carol, Homer instead writes a song about how much he hates Ned Flanders. The song becomes such a hit that the Simpsons become sick of hearing it and take a trip to a dude ranch. Lisa develops affections for a local boy named Luke but becomes jealous when he hears him talking to a girl named Clara on the telephone. One night, she meets Clara and gives her the wrong directions, leading her to become lost. After Lisa discovers that Clara is actually Luke''s sister, she rushes to find her. She saves Clara, and decides to tell Luke what happened, but he is offended and dumps her. Meanwhile, Bart and Homer decide to help a tribe of Native Americans who want a beaver dam removed so they can reclaim their land.', 23, '2003-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 19, 'Old Yeller-Belly', 'Homer throws out Santa''s Little Helper for not saving him from a fire, but soon the dog becomes Duff''s new mascot.', 23, '2003-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 20, 'Brake My Wife, Please', 'Homer becomes obsessed with using new gadgets in his car. One day, he becomes distracted and drives off a pier, losing his driver''s license. Unable to use a car, Homer starts to learn the joys of walking. Meanwhile, Marge shoulders the burden of Homer''s driving duties and becomes stressed out. One day, as Homer sings about the virtues of walking, Marge accidentally runs him over with her car. Later, as Homer recuperates from the accident, he begins to suspect that Marge is trying to hurt him. They fight and go to see a marriage counselor. The counselor advises Homer to perform one completely unselfish gesture to win Marge back. Homer holds a party with all of her friends and a surprised Marge tells Homer that she loves him.', 23, '2003-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 21, 'The Bart of War', 'After destroying Flanders'' shrine to The Beatles, Bart and Milhouse are punished by being put in community groups. Bart joins the Pre-Teen Braves along with Ralph Wiggum, Nelson Muntz and Database. Led by Marge, they start engaging in community activities. However, they soon become rivals with The Cavalry Kids, led by Milhouse. The two groups try to outdo each other and become involved in a contest to sell the most candy. The Cavalry Kids win the prize of singing the national anthem at a baseball game. However, the Pre-Teen Braves pretend to be The Cavalry Kids and sing their own version of the national anthem. As the crowd becomes enraged, the real Cavalry Kids arrive and a massive stadium-wide brawl erupts. Marge becomes upset, and the fighting ends when an image of her crying is shown on the JumboTron.', 23, '2003-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 14), 22, 'Moe Baby Blues', 'Moe Szyslak becomes lonely and decides to commit suicide by jumping off a bridge. However, he inadvertently saves Maggie Simpson when she is sent flying from the Simpsons'' car window and into his arms. He starts playing with Maggie and becomes attached to her, telling her the story of The Godfather. Homer and Marge become upset about how much time Moe is spending with Maggie and forbid him from seeing her again. One night, Maggie wakes up and hears Fat Tony and the Springfield Mafia outside the house and decides to follow them. When Homer and Marge find her missing, they automatically assume that Moe kidnapped her. When Moe is told that Maggie is missing, his request to help find her is granted by Homer. Maggie follows the mobsters to Luigi''s restaurant, where Fat Tony''s gang gets into a gun battle with a rival family. Homer, Marge and Moe track Maggie down and Moe decides to go inside and save Maggie. After Moe saves Maggie''s life, Homer allows the two to spend more time together.', 23, '2003-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 15, 'Season 15', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 1, 'Treehouse of Horror XIV', '"Reaper Madness" - Death becomes Homer and our hero must learn to reap what he sows (and pull a fast one on the almighty). "Frinkenstein" - Soon to be Nobel-prize winning Professor Frink reanimates his father for some gruesome body parts-swapping. "Stop the World, I Want to Goof Off" - A parody of Clockstoppers, starring Bart and Milhouse.', 23, '2003-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 2, 'My Mother the Carjacker', 'Homer''s mother returns, and after being cleared of all charges, is re-imprisoned on a technicality.', 23, '2003-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 3, 'The President Wore Pearls', 'In this loose parody of the musical/movie Evita, Lisa is elected Student Body president, but is unaware that the school staff is using her for their own devices and as a scapegoat if something goes wrong.', 23, '2003-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 4, 'The Regina Monologues', 'After making over $3000 from his own museum featuring a $1000 bill, Bart takes the family to London (on the suggestion of Grampa), where Homer is arrested for treason after crashing into the Queen.', 23, '2003-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 5, 'The Fat and the Furriest', 'Homer is humiliated when he appears on the news running from a bear that nearly attacks him at the city dump. After Grampa scolds him, he swears to fight the bear himself.', 22, '2003-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 6, 'Today I Am a Clown', 'Krusty discovers that he never had a bar mitzvah as a child. He quits his show to have it as an adult, with the help of his father, Rabbi Krustofski. Meanwhile, Homer hosts a late-night talk show a la "Politically Incorrect with Bill Maher" as a replacement for Krusty''s show.', 23, '2003-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 7, '''Tis the Fifteenth Season', 'Homer realizes how selfish he is after he spends all the family''s Christmas money on a present for himself. He becomes the nicest guy in town, making Ned Flanders jealous.', 23, '2003-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 8, 'Marge vs. Singles, Seniors, Childless Couples and Teens, and Gays', 'When a group of singles, seniors, childless couples, teens and gays band together to protest having to accommodate families (including paying property taxes used to teach children they do not have) after a riot at a children''s concert, Marge takes up the cause for the families, with some help from Bart and Lisa.', 23, '2004-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 9, 'I, (Annoyed Grunt)-Bot', 'Homer builds a battle robot to win Bart''s respect, and places it in a tournament against other robots. What Bart does not know, though, is that the robot is actually Homer in costume. Meanwhile, Snowball II dies and Lisa tries to find a replacement cat.', 23, '2004-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 10, 'Diatribe of a Mad Housewife', 'Marge writes a romance novel with characters based on Homer and Ned Flanders that becomes a hit. Meanwhile, Homer gets fired from the power plant again and becomes an ambulance driver.', 23, '2004-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 11, 'Margical History Tour', 'When the local library proves to be useless for the kids'' class project, Marge tells Milhouse, Bart, and Lisa three Simpsons-style historical accounts: Henry VIII''s (Homer''s) attempts at siring a son, Lewis and Clark (Lenny and Carl) exploring the USA''s wilderness with Sacagawea (Lisa), and Salieri (Lisa again) out to ruin piano-playing virtuoso Mozart (Bart).', 23, '2004-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 12, 'Milhouse Doesn''t Live Here Anymore', 'Bart finds a friend in his own sister Lisa after Milhouse moves away to Capitol City to live with his divorced mom. Meanwhile Homer goes into panhandling to buy anniversary gifts for Marge. Later on Milhouse returns and Bart goes back being friends with him.', 23, '2004-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 13, 'Smart & Smarter', 'When Maggie does better than Lisa on an IQ test, Lisa becomes upset over no longer being the smart one and tries to lead Maggie astray.', 23, '2004-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 14, 'The Ziff Who Came to Dinner', 'The Simpsons go on a late-night attic search after Bart and Lisa (who are freaked out over a horror movie Homer let them watch) begin hearing voices -- and find Marge''s ex-prom date Artie Ziff, who''s on the run for cheating the shareholders of his company.', 23, '2004-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 15, 'Co-Dependents'' Day', 'Homer and Marge''s bond becomes stronger when they both get drunk on wine, but soon the bond unravels when Homer blames Marge for crashing the car and Marge gets sent to rehab. Meanwhile, Bart and Lisa complain to Randall Curtis (a George Lucas-esque science fiction movie director) about his latest film.', 23, '2004-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 16, 'The Wandering Juvie', 'Bart gets sent to juvenile hall after fooling everyone that there was a marriage concerning him. He encounters a dangerous girl there... He flees with Gina, but then the two are caught by Wiggum.', 23, '2004-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 17, 'My Big Fat Geek Wedding', 'After hearing that Skinner is getting cold feet about their wedding, Edna leaves Skinner at the altar and, after sending back one marriage gift, hooks up with Comic Book Guy. Meanwhile, Homer and Marge have an argument about if their marriage is still solid or not.', 23, '2004-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 18, 'Catch ''Em If You Can', 'After a ruined movie night, thanks to Bart and Lisa, Homer and Marge take a vacation away from them, but decide to go to Miami instead of going to see an uncle. When Bart and Lisa catch wind of their parents'' secret plan, Bart steals Rod''s credit card (just like Homer stole Ned''s) and go after them.', 23, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 19, 'Simple Simpson', 'Homer becomes "Pie Man", a masked vigilante who delivers a pie in the face of justice to evildoers. However, after attacking Mr. Burns, Burns hires him as a personal hitman, until Homer is ordered to attack the Dalai Lama.', 23, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 20, 'The Way We Weren''t', 'Homer and Marge recall the story of their first kiss at a summer camp when they were children—an event which was not all happy, as Homer (unwillingly) betrayed Marge by standing her up on their second date.', 23, '2004-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 21, 'Bart-Mangled Banner', 'After receiving an injection from Dr. Hibbert, Bart becomes temporarily deaf, which makes him impervious to being bullied, until he accidentally moons the American flag during a donkey basketball game, prompting everyone in town to accuse the Simpsons of being unpatriotic under the new "Government Knows Best" Act.', 23, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 15), 22, 'Fraudcast News', 'Mr. Burns buys out Springfield''s media outlets after a newspaper mistakenly reports his death, and Lisa''s homemade newspaper is next on his list.', 23, '2004-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 16, 'Season 16', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 1, 'Treehouse of Horror XV', 'Ned Flanders'' head injury gives him the power to predict others'' deaths, Bart and Lisa play detective when a string of Victorian-era prostitutes are murdered by Jack the Ripper, and the Simpsons go on a fantastic voyage inside Mr. Burns'' body to save Maggie.', 23, '2004-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 2, 'All''s Fair in Oven War', 'Marge gets her kitchen remodeled and the dishes she makes inside it get rave reviews. The suggestion of Ned Flanders leads her to enter a cooking contest. However, Marge realizes the competition is harder than it seems. Meanwhile, Bart finds Homer''s vintage Playdude magazines and decides to adopt the lifestyle he sees within the articles.', 23, '2004-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 3, 'Sleeping with the Enemy', 'Marge finds Nelson and acts as a mother figure towards him due to her children''s loss of interest in her. Meanwhile, Lisa gets teased about her big butt, and becomes obsessed with her weight.', 23, '2004-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 4, 'She Used to Be My Girl', 'Marge meets up with a former high-school pal who is now a famous news anchor, and she wonders if she made the right life choice.', 23, '2004-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 5, 'Fat Man and Little Boy', 'When Bart writes slogans on T-shirts, he catches the attention of Goose Gladwell, a gag-gift entrepreneur, and soon becomes a T-shirt mogul; Homer feels he no longer has a place in the family when Bart becomes the breadwinner.', 23, '2004-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 6, 'Midnight Rx', 'Homer, Grampa, Apu and Flanders travel to Canada to buy sorely needed prescription drugs with fake Canadian health-care cards.', 23, '2005-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 7, 'Mommie Beerest', 'When Marge discovers Homer has remortgaged the house to help Moe''s bar, she takes over as landlady. Little does Homer know, Moe and Marge are a match made in pub heaven.', 23, '2005-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 8, 'Homer and Ned''s Hail Mary Pass', 'Homer''s impromptu dance at a carnival leads to a job choreographing victory dances for sports stars Tom Brady, Warren Sapp, Michelle Kwan, Yao Ming and LeBron James.', 23, '2005-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 9, 'Pranksta Rap', 'Bart fakes his own kidnapping to get out of being punished for going to a rap concert, but the ruse goes too far when Milhouse''s father is implicated as the kidnapper and Chief Wiggum sees this as an opportunity to make a name for himself as a competent police officer.', 23, '2005-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 10, 'There''s Something About Marrying', 'Springfield legalizes same-sex marriage to increase tourism. After becoming a minister, Homer starts to wed people to make money. Meanwhile, Marge''s sister Patty comes out as a lesbian and reveals that she is going to marry a woman named Veronica.', 23, '2005-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 11, 'On a Clear Day I Can''t See My Sister', 'Lisa does what every little sister has dreamed of - she gets a restraining order put on her big brother. Bart is forced to live in the back garden, but soon realises the joy of communing with nature.', 23, '2005-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 12, 'Goo Goo Gai Pan', 'Selma decides to adopt a child from China, but when the rules say she must be married, Homer must pose as her husband for the fearsome adoption agent Madame Wu.', 23, '2005-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 13, 'Mobile Homer', 'When Marge starts economising, Homer thinks he''s being left out of the family''s important financial decisions, so splashes out on an expensive camper van and sets up camp on the driveway.', 23, '2005-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 14, 'The Seven-Beer Snitch', 'After Shelbyville accuses Springfield of being hicks, Marge convinces the townspeople to fund a Frank Gehry-designed concert hall, which is then converted to a prison when the concert hall goes bankrupt on opening night. Meanwhile, Bart and Lisa investigate Snowball II''s recent weight gain.', 23, '2005-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 15, 'Future-Drama', 'Through Professor Frink''s future machine, Bart and Lisa see their lives in the year 2013, where Bart steals Lisa''s chances at going to an Ivy League school in order to impress a skater girl named Jenda while Homer (now separated from Marge and living in an underwater apartment) fights Krusty the Clown after Marge begins dating him.', 23, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 16, 'Don''t Fear the Roofer', 'Homer meets a new friend, Ray the Roofer, but gets confined to a mental institution when his friends and family believe he made him up.', 23, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 17, 'The Heartbroke Kid', 'When Bart endangers his health by bingeing on vending-machine food, the Simpsons turn their home into a hostel in order to afford sending him to a forced starvation facility.', 23, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 18, 'A Star Is Torn', 'Lisa agrees to enter a Krusty-sponsored "Li''l Starmaker" competition and panics when another contestant outperforms her.', 23, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 19, 'Thank God It''s Doomsday', 'Homer sees a movie about the end of the world and fears the same thing will happen in real life after seeing a chain of random occurrences and doing a complicated math equation that predicts the end will come on May 18th.', 23, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 20, 'Home Away from Homer', 'Flanders rents a room to two college girls who, without his knowledge, use the spare room to broadcast live softcore pornographic web videos of themselves.', 23, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 16), 21, 'The Father, the Son and the Holy Guest Star', 'Bart gets expelled from school and transfers to a Catholic school, where a hip priest named Father Sean tries to convert Bart and Homer to Catholicism, which worries Marge when she believes that Catholics do not go to the same heaven as Protestants and discovers that Catholic women do not use birth control.', 23, '2005-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 17, 'Season 17', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 1, 'The Bonfire of the Manatees', 'After Homer gets into trouble over his football gambling debts, he allows the Springfield Mafia to shoot a "snuggle film" in the house without Marge''s permission. When she and the kids return home from a trip to "Santa''s Village" and find production still going on, a furious Marge leaves for the beach and encounters a marine biologist named Caleb Thorn who has dedicated his life to saving manatees.', 22, '2005-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 2, 'The Girl Who Slept Too Little', 'After the family successfully protest against a stamp museum being built next to their house, a cemetery is built near the Simpson house instead, making the normally unflappable Lisa realize that someone as smart as her can be afraid of something.', 23, '2005-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 3, 'Milhouse of Sand and Fog', 'Never one to miss the opportunity to make a quick buck, Homer cashes in on Maggie''s bout of chicken pox. He decides to host a Pox Party and charges parents to infect their children.', 23, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 4, 'Treehouse of Horror XVI', 'Bart ends up in a coma after attempting to jump from the roof to the swimming pool at Spinster Arms Apartments, while attending a hunting party at Burns Manor, Homer panics and believes the prey is the hunting party, and after losing a Halloween costume contest to Dr Hibbert as Dracula, a real witch puts a spell on the people of Springfield.', 23, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 5, 'Marge''s Son Poisoning', 'When Bart decides to spend a bit of time with Marge, it''s not long before he''s buying tea sets and singing duets. Has he turned into a mummy''s boy?', 23, '2005-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 6, 'See Homer Run', 'Homer becomes Springfield''s safety guru and before long he''s challenging Mayor Quimby for office. Until, that is, there''s an embarrassing mishap with his costume.', 23, '2005-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 7, 'The Last of the Red Hat Mamas', 'Marge is shunned after Homer has an altercation with the Easter Bunny at the mayor''s egg hunt. A lonely Marge joins a women''s group who plan to steal $1 million from Mr Burns.', 23, '2005-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 8, 'The Italian Bob', 'Homer brings the whole family along when he is sent to Italy to pick up a new sports car for Mr. Burns, when they find themselves in a small town that Sideshow Bob has become the mayor of.', 23, '2005-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 9, 'Simpsons Christmas Stories', 'The Simpsons re-enact the Nativity; a World War II tale stars Grampa, Mr. Burns and Santa; a musical features "The Nutcracker Suite."', 23, '2005-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 10, 'Homer''s Paternity Coot', 'Mail from forty years earlier is discovered, and a letter from Homer Simpson''s mother''s old boyfriend states that he is Homer''s true father. Homer sets out to find his supposed new father, leaving Abe behind.', 23, '2006-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 11, 'We''re on the Road to D''ohwhere', 'After Bart steals a key from Principal Skinner''s office and gets himself into hot water, Marge and Homer send him to a behavior modification camp.', 23, '2006-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 12, 'My Fair Laddy', 'Mr. Krupt is the school’s new gym teacher and introduces Bart and the kids to “BOMBARDMENT!” Bart’s attempt to get back at the new gym teacher results in the destruction of Groundskeeper Willie’s shack and the family takes him in. Lisa decides to make Willie the focus of her science fair project and tries to turn him into a “proper gentleman” with surprising results. Meanwhile, Homer has ruined his last pair of blue pants and attempts to generate interest in them so the manufacturer will start making them again.', 23, '2006-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 13, 'The Seemingly Never-Ending Story', 'The family is on a nature walk through “Carl’s Dad Caverns,” when Homer tries to get a piece from a stalactite. This results in the family falling through the cave floor and winds up with Homer getting stuck in the ceiling of one of the lower chambers of the cave. Marge, Bart and Maggie go off to find help, while Lisa stays behind and tells her father a story to pass the time. Her story involves running from a bighorn sheep and into Mr. Burn’s mansion. The pair evades the tenacious sheep by finding refuge in the mansion’s attic, where Mr. Burns tells her the story of how he came to work at Moe’s Tavern by losing a scavenger hunt with a rich Texan. While there he learned (and tells to Lisa) the tale of the Moe’s treasure. The stories within stories culminate in the fate of the treasure being determined in the cave.', 23, '2006-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 14, 'Bart Has Two Mommies', 'The family is at a church fund-raiser, where Homer tries to ensure his rubber duck onto victory, but Flanders wins the big prize, which he doesn’t want and gives it to Marge. In return Marge agrees to watch Rod and Todd while Ned is attending a left-handed convention. While Marge is spending all her time with the Rod and Todd and trying to let them learn how to be boys; Homer takes Bart and Lisa to a home for former celebrity animals and a monkey kidnaps Bart. Marge’s ability to be a mother comes into question when Ned discovers what she is doing with his boys and the local news covers Bart’s current predicament.', 23, '2006-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 15, 'Homer Simpson, This Is Your Wife', 'Homer is stoked for a party, where Lenny shows off his new plasma screen HD TV. Three days later and Homer still hasn’t left Lenny’s apartment. Lenny eventually gets him to leave and Marge enters them in a contest where they can win a plasma TV of their own. They don’t win, but 3rd place gets them a tour of the FOX studios, where Homer learns about a wife-swapping show where he can win enough money to buy his own plasma TV. Marge agrees to appear and they exchange wives with the Heathbar family. Charles Heathbar winds up falling in love with Marge (who is giving him what he needs), while his real wife Verity finds Homer detestable.', 22, '2006-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 16, 'Million Dollar Abie', 'Homer spearheads the effort to get pro-football to bring a new franchise to Springfield. The football commissioner, on his way to officially award the franchise, stops at the Simpson house where Grandpa (mistaking him for a burglar) attacks him. Springfield loses out and Abe becomes the town’s pariah. After trying and failing assisted suicide, Abe decides to live his life without fear and when the town decides to reuse their football stadium as a bullfighting ring, he volunteers to be the toreador. Ever the activist, granddaughter Lisa protests his new profession.', 23, '2006-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 17, 'Kiss Kiss, Bang Bangalore', 'At the power plant a movie is shown where the workers endorse outsourcing and Mr. Burns announces that he is closing the plant and moving the work to India. Homer is the only union employee left on the payroll and he is sent to India to train the replacement workers, when he succeeds beyond expectations, he is given total control of the plant and declares himself a god. Meanwhile, Selma & Patty take Bart and Lisa to their MacGyver convention. When they discover Richard Dean Anderson doesn’t like MacGyver and much as they do, they kidnap him in retaliation. Anderson escapes only to enjoy the thrill and he turns himself back in so that he can escape again. When it happens over and over again, soon Patty and Selma are the ones who need a means of escape.', 23, '2006-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 18, 'The Wettest Stories Ever Told', 'As the family waits for their food at “The Frying Dutchman,” they pass the time by telling stories. Lisa tells about the Mayflower’s journey to America, where Marge and her kids are Pilgrims and they are joined by a knave named Homer who joins their family to escape the authorities. Bart recounts the story of Mutiny on the Bounty featuring Skinner as Captain Bligh and Bart as Mr. Christian. Homer tells the tale of the maiden voyage of a cruise ship in the 1970s featuring of a ship that can’t flip over, which of course it does and the attempts of the survivors to get out of the ship alive.', 23, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 19, 'Girls Just Want to Have Sums', 'The family attends "Stab-A-Lot: The Itchy and Scratchy Musical." The musical''s director is a graduate of Springfield Elementary and Principal Skinner puts his foot in mouth when he makes sexist comments about her education and that of women in general. He tries to make the situation better, but only buries himself deeper and deeper until he is fired and replaced by Women''s Educational Expert Melanie Upfoot. The first thing she does is split the school into girls and the boys. Lisa dislikes the way girls are being taught math and she ventures over to the boy''s side of the school in search of a challenge. Disguising herself as Jake Boyman she starts attending the boy''s school but while she finds the math problems more interesting, it is being a boy that is a greater challenge.', 23, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 20, 'Regarding Margie', 'Marge goes on a cleaning frenzy before the housekeeper she’s won the services of comes to the house. One spot remains and she mixes a number of toxic cleaners together to tackle the job. The noxious mixture knocks her out and she wakes up suffering from amnesia. Marge is taken home and the family tries to bring back her memory. She starts to get back memories of her children and other insignificant things, but when it comes to remembering her husband, nothing he does seems to jog her memory. When he can’t get her to remember him, he tries to win her all over again, especially after Patty and Selma get her back out on the dating scene.', 23, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 21, 'The Monkey Suit', 'Working through their checklists of things to do before summer ends, Lisa gets the family to go a museum. At the Springfield Museum of Natural History there is an exhibit Lisa is excited to see on Women’s History turns into an exhibit on the history of weapons, which excites Homer and Bart. When Flanders sees the exhibit of evolution and another that mocks creationism, he raises an alarm. Reverend Lovejoy gets Skinner to have creationism taught in school. Lisa is the only one who holds onto the scientific theory. She brings the topic up at the town meeting and the town votes to teach only one theory, creationism. Lisa decides to hold her own class on evolution, until she is arrested. The ACLU gives her a lawyer who is up against a slick Southern lawyer, but ultimately it’s a family member that is a key to her defense.', 22, '2006-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 17), 22, 'Marge and Homer Turn a Couple Play', 'When Homer hears that the Isotopes are on a winning streak, he takes the family to the game. The first baseman’s game is going bad, caused by his sexy singing wife Tabitha embarrassing him during the game’s national anthem. Buck Mitchell sees Marge and Homer’s kiss on the game’s Kiss-Cam and comes to them for marital advice. They start working with the couple and Buck’s baseball career turns around, but it and the Simpson marriage goes awry again when Buck catches Homer giving Tabitha a neck massage. While Marge and Homer try keeping their marriage together they also try to get Buck and Tabitha back together.', 23, '2006-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 18, 'Season 18', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 1, 'The Mook, the Chef, the Wife and Her Homer', 'Lisa''s friendship with Fat Tony''s son Michael prompts mob boss Tony to invite the Simpsons over for dinner. Michael says he''d rather be a chef than take over the family business, but that''s before Tony is shot by a rival mobster.', 22, '2006-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 2, 'Jazzy and the Pussycats', 'A child psychiatrist suggests drumming to channel Bart''s energy, and the boy proves he''s got the beat when he shows some talent on the skins.', 23, '2006-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 3, 'Please Homer, Don''t Hammer ''Em', 'Marge reads Homer''s carpentry books and becomes very handy at fixing things. Gender bias keeps the townspeople from accepting a female carpenter, so Marge pretends that Homer does the work. Meanwhile, Bart torments Skinner when he learns the principal has an extreme allergy to peanuts.', 23, '2006-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 4, 'Treehouse of Horror XVII', 'The 17th annual Halloween trilogy. Included: "Married to the Blob," in which a meteor turns Homer into a monster; "You Gotta Know When to Golem," about a monster from Jewish folklore; and "The Day the Earth Looked Stupid," about an alien invasion.', 23, '2006-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 5, 'G.I. (Annoyed Grunt)', 'Homer is bamboozled by Army recruiters and winds up in basic training, where he runs afoul of a tough-minded colonel and is assigned to play the enemy in war games.', 22, '2006-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 6, 'Moe''N''a Lisa', 'Lisa sees poetry in the notes Moe sticks to the walls of his hotel room, so she sends his work to a poetry journal, which publishes it, making Moe the toast of the literary circuit.', 23, '2006-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 7, 'Ice Cream of Margie (With the Light Blue Hair)', 'Homer is fired and decides to buy an ice-cream truck. Marge makes use of the mountains of Popsicle sticks from Homer''s ice-cream consumption by creating sculptures of Springfield citizens with them, leading to a feature about her on the news.', 23, '2006-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 8, 'The Haw-Hawed Couple', 'When Bart ends up the only guest at Nelson''s birthday party, the bully decides he''s his best friend and goes about protecting Bart in a parody of "Goodfellas." Meanwhile, Homer reads Lisa to sleep and debates on whether to reveal the book''s sad ending to her.', 23, '2006-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 9, 'Kill Gil, Volumes I & II', 'Homer jumps into a brawl during a holiday ice-skating show. To escape the melee, Marge takes the family Christmas shopping, where a chance encounter with Gil leads to bad luck for Gil and the Simpson clan.', 23, '2006-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 10, 'The Wife Aquatic', 'Selma and Patti''s home movies make Marge nostalgic for the Barnacle Bay vacations of her youth, so Homer takes the family there, but the area has changed since the Bouviers were little girls.', 22, '2007-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 11, 'Revenge Is a Dish Best Served Three Times', 'Homer learns three lessons about revenge from stories told by Marge, Lisa and Bart that parody "The Count of Monte Cristo," "Revenge of the Nerds" and "Batman Begins."', 23, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 12, 'Little Big Girl', 'Lisa pretends to be Native American for multicultural day at school. Meanwhile, Bart finds love with an older woman.', 22, '2007-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 13, 'Springfield Up', 'A documentary filmmaker who interviewed a group of Springfield schoolchildren 32 years ago has followed up at eight-year intervals to film how their lives have unfolded.', 23, '2007-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 14, 'Yokel Chords', 'Bart has to see a psychiatrist after he starts a panic at school by telling a story about a murderous cafeteria worker. Meanwhile, Lisa tries to civilize Cletus Spuckler''s hillbilly children, with mixed results.', 23, '2007-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 15, 'Rome-Old and Juli-Eh', 'Selma and Grampa embark on a May-December romance, and Bart and Lisa get into trouble with deliverymen over cardboard boxes.', 22, '2007-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 16, 'Homerazzi', 'After a celebrity scandal is accidentally captured in a family photo, Homer decides to become a paparazzo.', 22, '2007-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 17, 'Marge Gamer', 'Marge goes online for the first time and becomes obsessed with a role-playing game that Bart and many of their neighbors are playing. Meanwhile, Lisa develops her own obsession--for soccer--and Homer becomes a referee.', 23, '2007-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 18, 'The Boys of Bummer', 'Bart goes from hero to goat on his Little League team after an error in the championship game. Meanwhile, Homer falls asleep on a bed in a department store. When he''s awakened, he raves about the mattress and is given a job as a salesman.', 23, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 19, 'Crook and Ladder', 'Homer, Apu, Moe and Skinner volunteer as firemen after Homer''s sleepwalking accident injures the town''s firefighters. They do some light looting at the fires to make up for not being compensated, but Marge and Lisa shame them into mending their ways.', 23, '2007-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 20, 'Stop or My Dog Will Shoot!', 'The Simpsons'' pooch, Santa''s Little Helper, becomes a police dog.', 23, '2007-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 21, '24 Minutes', 'In a parody of "24," the school''s Counter Truancy Unit tries to stop three sixth-graders planning to disrupt the school bake sale with a stink bomb.', 23, '2007-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 18), 22, 'You Kent Always Say What You Want', 'Newsman Kent Brockman is fired for swearing on the air when Homer dumps coffee in his lap, but Lisa gets Brockman back in the game with her Webcam.', 23, '2007-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 19, 'Season 19', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 1, 'He Loves to Fly and He D''ohs', 'Homer falls in love with the high life of flying in private planes when he saves Mr. Burns from drowning, and Burns repays him by flying him to Chicago for a night on the town.', 22, '2007-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 2, 'The Homer of Seville', 'A freak accident gives Homer an operatic singing voice, and he becomes a star at the Springfield Opera. But with fame and fortune comes a price: He''s continually bothered by fans, an obsessed woman in particular.', 23, '2007-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 3, 'Midnight Towboy', 'Homer takes a job as a tow-truck driver, and Marge hires a service that claims to make babies less clingy. Both decisions have unexpected consequences.', 23, '2007-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 4, 'I Don''t Wanna Know Why the Caged Bird Sings', 'Marge is held hostage during a bank robbery and forms an uneasy bond with one of the thieves before he''s taken to prison.', 23, '2007-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 5, 'Treehouse of Horror XVIII', 'The series'' 18th Halloween show features three vignettes that parody movies: one that spoofs "Mr. & Mrs. Smith"; one that sends up "E.T."; and one that parodies "Se7en."', 23, '2007-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 6, 'Little Orphan Millie', 'Milhouse stays with the Simpsons when his parents remarry each other and honeymoon on a cruise ship. But when his parents are knocked overboard and lost at sea, Milhouse decides to grow up and be a man.', 23, '2007-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 7, 'Husbands and Knives', 'Marge opens a gym for real women because she''s disenchanted with Springfield''s snooty, glitzy L.A. Body Works. Her gym, Shapes: A Gym for Women, is a huge success, launching a chain that makes Marge rich and famous. But Homer fears Marge will leave him for someone more attractive and goes to extreme lengths to try to save his marriage.', 23, '2007-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 8, 'Funeral for a Fiend', 'Sideshow Bob tries again for revenge against the Simpsons.', 23, '2007-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 9, 'Eternal Moonshine of the Simpson Mind', 'Homer loses his memory--and his family--when he drinks Moe''s most potent libation, the Forget-Me-Shot, in an episode that spoofs "Eternal Sunshine of the Spotless Mind" and "It''s a Wonderful Life."', 23, '2007-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 10, 'E Pluribus Wiggum', 'Homer burns down Springfield''s fast-food district. In order to float a bond issue to rebuild it, Mayor Quimby moves up election day, making Springfield''s primary election the first in the nation. This causes the town to be overrun with reporters, candidates and pundits.', 23, '2008-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 11, 'That 90''s Show', 'Flashbacks follow Marge and Homer back to their dating days, when she was a college student and he was working for his father to support her. Then Marge becomes smitten with a professor, so a sorrowful Homer turns to music--and invents grunge.', 23, '2008-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 12, 'Love, Springfieldian Style', 'Homer and Marge celebrate Valentine''s Day by going on the Tunnel of Love ride at a carnival, but they end up stranded when Bart pulls a prank involving gelatin. To pass the time, Homer tells the love story of Bonnie and Clyde, Marge tells her version of "Lady and the Tramp," and Bart tells the love story of Sid Vicious and Nancy Spungen.', 23, '2008-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 13, 'The Debarted', 'A new kid at school named Donny works with Bart on his pranks. But when the pranks start to backfire, Bart wonders if he can trust his new accomplice. Meanwhile, the Simpsons get a fancy loaner car after Marge gets in an accident, and Homer falls in love with it.', 23, '2008-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 14, 'Dial ''N'' for Nerder', 'Homer cheats on his diet, so Marge gets a reality show called "The Sneakers" to check up on him. Meanwhile, Bart and Lisa fear that a prank they played on Martin Prince had deadly consequences.', 23, '2008-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 15, 'Smoke on the Daughter', 'With Lisa''s encouragement, Marge pursues her dream of becoming a ballerina. But when Marge auditions at the ballet academy, Lisa is invited to enroll. Unfortunately, Lisa becomes addicted to secondhand smoke from the other dancers. Meanwhile, Homer''s beef-jerky operation runs into a snag.', 23, '2008-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 16, 'Papa Don''t Leech', 'The Simpsons take in a country singer Homer used to manage who owes back taxes to Springfield. She is now destitute, so the family tries to help her get back on her feet.', 23, '2008-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 17, 'Apocalypse Cow', 'Bart joins the 4-H club and raises a calf to be a blue-ribbon-winning bull, but panics when he learns the bull will be slaughtered.', 23, '2008-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 18, 'Any Given Sundance', 'Lisa makes a film about her family that gets accepted by the Sundance Film Festival, and the Simpsons go to Park City, Utah, to attend.', 23, '2008-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 19, 'Mona Leaves-a', 'Homer''s mother, Mona, returns, but Homer is reluctant to trust her because she abandoned him so many times as a child.', 23, '2008-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 19), 20, 'All About Lisa', 'Lisa receives Springfield''s Entertainer of the Year Award, and Sideshow Mel narrates her history in showbiz in a wry spoof of "All About Eve."', 23, '2008-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 20, 'Season 20', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 1, 'Sex, Pies and Idiot Scrapes', 'Bounty hunter Ned is forced to scrap his partnership with Homer when the hapless layabout skips bail, and Marge mistakenly takes a job at an erotic bakery.', 23, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 2, 'Lost Verizon', 'Bart lands himself in trouble when he steals a mobile phone from Denis Leary and subsequently uses it to land the actor a comical film role. The troublemaker then leads his family to the ancient ruins of Machu Picchu after Marge confiscates the device and decides to use its GPS technology to track her son.', 23, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 3, 'Double, Double, Boy in Trouble', 'An irreverent take on the Prince and the Pauper. Bart enthusiastically trades lives with a wealthy lookalike after landing himself in trouble for triggering a rampage of vacuum cleaners, but finds the lavish lifestyle too much when he becomes the target of all his new friends'' pranks.', 23, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 4, 'Treehouse of Horror XIX', 'Springfield is the setting for parodies of Charlie Brown, It''s the Great Pumpkin and Michael Bay''s Transformers as Homer''s vote on election day is misread by a renegade machine.', 23, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 5, 'Dangerous Curves', 'Homer and Marge remember the ups and downs of their marriage through a series of flashbacks, including the time they each began flirting with guests at a glamorous party - a situation that led to a food fight and an unexpected swim in the pool.', 23, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 6, 'Homer and Lisa Exchange Cross Words', 'Lisa learns she is good at crossword puzzles and enters a city-wide contest. Homer discovers he has a flair for letting loved ones down so he opens Sweet Conclusions Break-Up Service, but lands himself in trouble with his daughter when he places a bet against her in the competition.', 23, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 7, 'Mypods and Boomsticks', 'Lisa struggles to become the proud owner of a Mypod, and Homer believes Bart''s new Middle-Eastern friend Bashir is involved in a terrorist plot to destroy the Springfield Mall.', 23, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 8, 'The Burns and the Bees', 'Mr Burns wins a professional basketball team in a poker game at the annual billionaire''s retreat. He decides to build a state-of-the-art facility in an attempt to lure fans, but the stadium site is on the last remaining bee colony in Springfield - prompting Lisa to lead a protest.', 23, '2008-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 9, 'Lisa the Drama Queen', 'Lisa lets her imagination run wild when she makes a new friend and they create a magical kingdom together called Equalia, complete with characters and plotlines. But they find themselves facing a nightmare when the boundaries between reality and fantasy are blurred. With the voice of Emily Blunt.', 22, '2009-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 10, 'Take My Life, Please', 'Homer is jealous when old classmate Vance Connor is inducted into the Springfield Walk of Fame. Lenny and Carl confess they fixed the result in favor of Principal Dondelinger - leading the hapless father to speculate on how his life would have changed had he won the ballot.', 22, '2009-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 11, 'How the Test Was Won', 'Bart gets a perfect score on a practice test for a national achievement test, which not only rattles Lisa, but it means Bart gets to attend a special party instead of having to take the actual test. Meanwhile, Homer must avoid injuring himself for an entire afternoon after failing to pay his insurance.', 22, '2009-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 12, 'No Loan Again, Naturally', 'When the adjustable rate on the Simpson couple''s mortgage resets at more than the pair can afford, they must sell their house. Good Samaritan Ned Flanders buys the house and rents it out to them at an affordable rate. But Homer pushes his luck too far when he takes advantage of Ned''s generous landlord duties.', 22, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 13, 'Gone Maggie Gone', 'Lisa infiltrates a convent in order to steal back Maggie who was accidentally taken in by nuns. While in the convent, Lisa uncovers a series of cryptic clues leading to a hidden jewel in Springfield. With help from resident history buffs Principal Skinner and Comic Book Guy, Lisa sets off to find the coveted prize. But Springfield''s Freemasons are also hot on the trail of the jewel, and Lisa must race against them to find the jewel and rescue Maggie.', 23, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 14, 'In the Name of the Grandfather', 'The Simpsons travel to Ireland so that Grampa can have a final drink at O''Flanagan''s Pub - an old watering hole of his. But when the small town of Dunkilderry isn''t quite what Grampa remembers it as, and O''Flanagans has become a rundown and empty pub, he and Homer decide to buy it and fix it up.', 23, '2009-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 15, 'Wedding for Disaster', 'After Marge and Homer''s marriage turns out to be invalid, they decide to re-do their vows. But when Homer goes missing, Bart and Lisa smell something funny and investigate his disappearance.', 23, '2009-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 16, 'Eeny Teeny Maya Moe', 'Moe once again searches for love and falls for a woman named Maya over the Internet. However, when Moe meets Maya face-to-face, he discovers it''s more like face-to-knee, as Maya is only three feet tall.', 23, '2009-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 17, 'The Good, the Sad and the Drugly', 'Bart falls in love with a charitable girl named Jenny, prompting Bart to behave in order to date her. Meanwhile, Lisa becomes depressed when she writes a report on Springfield''s future.', 23, '2009-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 18, 'Father Knows Worst', 'Bart and Lisa start struggling in their academic and social lives at school and Homer starts monitoring them and forcing them to do better. Meanwhile, Marge discovers a sauna in the basement.', 23, '2009-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 19, 'Waverly Hills 9-0-2-1-D''oh', 'When Marge learns Springfield Elementary is the worst school in the state, she and Homer rent an apartment in the upscale Waverly Hills school district so Bart and Lisa can attend a better school. Meanwhile, Homer moves into the rented Waverly Hills apartment and gets used to the bachelor lifestyle.', 23, '2009-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 20, 'Four Great Women and a Manicure', 'Marge and Lisa visit the nail salon where they engage in a spirited debate as to whether a woman can be smart, powerful and beautiful all at the same time and spin four tales of famous women featuring famous Springfield faces: Selma as Queen Elizabeth I, Lisa as Snow White, Marge as Lady Macbeth and Maggie as Howard Roark, the idealistic architect protagonist from Ayn Rand’s The Fountainhead.', 23, '2009-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 20), 21, 'Coming to Homerica', 'When nearby Ogdenville’s economy crumbles due to tainted barley discovered in Krusty’s veggie burgers, the unemployed workers of Ogdenville flock to Springfield. After Mayor Quimby closes Springfield’s borders and enlists private citizens to help patrol them, Homer organizes a border patrol group.', 22, '2009-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 21, 'Season 21', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 1, 'Homer the Whopper', 'Homer gets the lead in a movie about a superhero who can take on the powers of every superhero in any comic book he touches. To whip Homer into superhero shape, the studio hires a celebrity fitness trainer.', 22, '2009-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 2, 'Bart Gets a ''Z''', 'The fourth grade students of Springfield Elementary School decide to spike Ms. Krabappel''s coffee in order to teach her a lesson after she takes away their cell phones. She is fired by Principal Skinner, who hires a new teacher named Zachary Vaughn. Although Vaughn is a hip young teacher who impresses the students, Bart is plagued by guilt and tries to get Ms. Krabappel hired back.', 23, '2009-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 3, 'The Great Wife Hope', 'The men and boys in Springfield become obsessed with Ultimate Punch Kick and Choke Championships, a violent sport where fighters inflict severe pain on each other. When Marge and her friends stage a protest against the sport, the show''s promoter embraces the controversy and challenges Marge to a match, promising to shut down the competition if she wins. She begins to train with rhythmic gymnastics, but her family step in and get her professional martial arts help to give her a real chance at winning.', 22, '2009-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 4, 'Treehouse of Horror XX', 'Dial "M" for Murder or Press "#" to Return to Main Menu- Lisa is forced into a Hitchcockian murder scheme by Bart.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 5, 'The Devil Wears Nada', 'Marge and a group called the "Charity Chicks" pose for a calendar in hopes of raising money for charity, but Marge becomes the talk of the town thanks to her racy poses. Meanwhile, Carl is chosen as the newest supervisor at the nuclear power plant, and hires Homer to be his personal assistant.', 23, '2009-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 6, 'Pranks and Greens', 'Principal Skinner is getting fed up with Bart''s pranks, so he informs Bart that he is not the best prankster after all. A former student named Andy Hamilton is hailed as the best prankster, and Bart sets out on a mission to track Andy down. However, when Bart finds out that Andy is a 19-year-old still in his pranking days, they become fast friends.', 22, '2009-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 7, 'Rednecks and Broomsticks', 'Lisa befriends three teenaged Wiccans after getting lost in the woods during a game of hide-and-seek, and must clear her new friends'' names when they are accused of cursing the townspeople with their supposed witchcraft. Meanwhile, Homer befriends Cletus after learning that he and his friends make their own moonshine.', 22, '2009-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 8, 'Oh Brother, Where Bart Thou?', 'One snowy day in Springfield, Lisa informs Bart that she and Maggie share a bond that Bart will never understand because he doesn''t have a brother, so Bart asks Homer for a baby brother. When Homer denies Bart''s request, Bart makes his way to the Springfield Orphanage to find what he thinks he''s missing.', 23, '2009-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 9, 'Thursdays with Abie', 'Grampa is sitting on a bench waiting for his family when a thoughtful-looking man named Marshall Goldman approaches him and asks to hear about his life. Grampa tells Goldman about the time he was on a World War II battleship, which was hit by an enemy torpedo, and Goldman, a human-interest columnist, publishes it in The Springfield Shopper. Later, Grampa meets Mitch Albom and shares another story with Goldman for a follow-up article. Homer becomes jealous of Grampa''s newfound fame and seeks a surrogate father. But when Homer discovers a draft of Goldman''s third story, he must race to find Grampa before it is published and his life is changed forever.', 23, '2010-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 10, 'Once Upon a Time in Springfield', 'Krusty grudgingly adds a pretty, singing cohost named Princess Penelope to his show in order to attract more female viewers. Girls love her, and ratings improve, but Bart and Milhouse want to get the show back to the way it was. The situation gets more complicated when Krusty and Penelope fall in love and decide to get married. Meanwhile, Homer, Lenny, and Carl consider working at a competing nuclear plant when Mr. Burns cuts off their daily doughnut service. ', 22, '2010-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 11, 'Million Dollar Maybe', 'Homer blows off Marge to buy a lottery ticket and winds up winning the million-dollar jackpot. Fearing how Marge will react if she finds out the reason Homer missed their date, Homer keeps his newly inherited fortune a secret and spoils his family with “anonymous” gifts. When Bart finds out, he and Homer spend the money like it’s going out of style, including buying front-row to tickets to see Coldplay in concert.', 23, '2010-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 12, 'Boy Meets Curl', 'Homer takes Marge out for a romantic evening of ice skating and hand-holding, but upon entering the rink, they encounter a curling team practising. Marge and Homer take to the ice and discover their love for the sport, and soon after, join the curling team and compete with them in the Olympic trials. Team Springfield claims the win and moves on to the 2010 Vancouver Games where Bob Costas covers the action. Meanwhile, sleazy vendors introduce Lisa to the world of collecting Olympic pins, and before long, Lisa is hopelessly addicted.', 23, '2010-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 13, 'The Color Yellow', 'When Miss Hoover asks her students to research their family history, Lisa is horrified to discover that most of her ancestors were bad people – a motley crew of horse thieves and deadbeats. But while rummaging through the attic, Lisa happens upon a diary kept by her ancestor, Eliza Simpson. As Eliza’s story unfolds, Lisa learns that her family was part of the Underground Railroad, a group that helped slaves escape to freedom. Eliza recounts liberating a slave named Virgil, but when Lisa presents her findings at school, some of her classmates refute it, leaving Lisa determined to exonerate her family’s name.', 23, '2010-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 14, 'Postcards from the Wedge', 'When Bart fails to turn in his homework, Mrs. Krabappel sends a letter home about Bart''s behaviour. Despite Bart''s best efforts to intercept it, Homer reads the letter, and he and Marge visit Principal Skinner for a parent-teacher conference. Furious, Homer punishes him, but Marge takes a more sympathetic approach. When Bart realizes he can pit Homer and Marge against each other to his benefit, his scheming reaches new heights.', 23, '2010-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 15, 'Stealing First Base', 'Principal Skinner announces that Mrs. Krabappel was called out of town and budget cuts dictate that, until she returns, the school''s two fourth grade classes will merge. Bart reluctantly shares a desk with Nikki and develops a flirtatious rapport. Bart talks to Grampa about his new crush, and at Grampa''s suggestion, gives Nikki a kiss. But when Nikki starts sending Bart mixed signals, he swears off women forever. Meanwhile, Lisa''s classmates ostracize her for being an overachiever, and First Lady Michelle Obama, a self-professed nerd, comes to Lisa''s defence.', 22, '2010-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 16, 'The Greatest Story Ever D''ohed', 'The Simpsons family vacation in Israel with Ned Flanders, but Homer does not appreciate any of the culture—until an Israeli tour guide named Jakob shows him around and, in a severe state of dehydration, Homer believes he is the Messiah.', 23, '2010-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 17, 'American History X-cellent', 'When the police are called to diffuse a rowdy crowd at Mr. Burns'' estate, one of the officers recognizes priceless stolen paintings on the walls, and the maniacal billionaire is taken downtown for questioning. With Mr. Burns gone, Smithers takes charge of the power plant. But when employees take advantage of his good nature, he exacts revenge by forcing the employees to work night and day. These unfair working conditions prompt Homer and his crew to devise a plan to bust out Mr. Burns.', 22, '2010-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 18, 'Chief of Hearts', 'Homer is completing his court-ordered community service when he befriends his supervisor, Chief Wiggum, by offering him one of his sandwiches. Touched by the act of kindness, Wiggum assigns the other convicts unpleasant tasks, but allows Homer to join him at the picnic table. They continue to grow close, but when the Chief gets injured during a botched bank robbery, Homer doesn''t come through when Wiggum needs him the most. Meanwhile, Bart becomes addicted to Battle Ball, a Japanese game made up of plastic balls and magnetic cards, and his family and teachers try to help him kick the habit.', 22, '2010-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 19, 'The Squirt and the Whale', 'The Simpsons decide to embrace a cheaper, alternate source of energy by erecting a wind turbine in their backyard. But when Homer realizes some of the power is being directed to the local electric company, he decides to remove his home from the grid and becomes completely dependent upon an unreliable source of power. Meanwhile, a storm erupts, trapping a magnificent 150-foot-long blue whale ashore, and Lisa and Homer attempt to help the poor creature.', 22, '2010-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 20, 'To Surveil with Love', 'A bomb squad mistakenly blows up Homer''s unattended gym bag, releasing radiation into the city and authorities react by suspending civil liberties. Wiggum and his men install surveillance cameras around Springfield and round up suspected terrorists, including groundskeeper Willie, but when monitoring the nonstop flow of video imagery proves to be too much, Wiggum enlists concerned citizens to help keep the city safe. Meanwhile, Lisa becomes fed up with being blonde, so she dyes her hair a dark color.', 22, '2010-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 21, 'Moe Letter Blues', 'As Mother''s Day approaches, Moe narrates an episode in which he writes a letter to Homer, Apu and Reverend Lovejoy, who are vacationing with their children, and threatens to run away with one of their wives. While the trio tries to determine whose wife Moe is referring to, Homer, Lovejoy and Apu flashback to the intimate moments they initially ignored between Moe and Marge, Manjula and Helen Lovejoy. But when the boys return from their trip, they''re in for the surprise of their lives.', 22, '2010-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 22, 'The Bob Next Door', 'Bart becomes convinced that his new neighbor, Walt, is his archenemy, Sideshow Bob, disguised and back for revenge. But when Marge tries to convince Bart otherwise by taking him to visit the state penitentiary, a disturbing truth is revealed.', 22, '2010-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 21), 23, 'Judge Me Tender', 'When Moe discovers a hidden talent for judging contests, he is approached by a television agent to join the AMERICAN IDOL judges'' panel. Moe flies to Los Angeles where he tours the Fox lot and receives some sage career advice. Meanwhile, Homer drives Marge crazy when he begins hanging around the house.', 22, '2010-05-23');
