INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 1, 'Elementary School Musical', 'Marge sends Lisa to a performing arts camp, where counselors and fellow campers inspire her to embrace her creative side; upon returning to Springfield, Lisa grows restless with her boring suburban lifestyle.', 23, '2010-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 2, 'Loan-a-Lisa', 'Grampa gives each family member a portion of his savings; Lisa worries that Nelson''s instant success with a new business venture might lure him away from continuing his education.', 23, '2010-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 3, 'MoneyBART', 'Lisa starts coaching Bart''s Little League team; Marge and Bart spend the day at an amusement park, where former MLB manager Mike Scioscia gives Bart advice.', 22, '2010-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 4, 'Treehouse of Horror XXI', 'Worried about the effects of violent video games, Marge encourages Bart and Milhouse to play board games; Lisa becomes smitten with a new student, a vampire; while on a second honeymoon, Homer and Marge rescue a castaway who escaped from his ship.', 23, '2010-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 5, 'Lisa Simpson, This Isn''t Your Life', 'Fearing that she will end up like Marge, Lisa pledges to focus solely on her academics and not get distracted by other things; Bart puts Nelson in his place and unintentionally earns the title of school bully.', 23, '2010-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 6, 'The Fool Monty', 'Mr. Burns becomes distraught at the town''s apathetic reaction to the announcement that he has only weeks to live; Bart secretly takes Burns into the family''s home.', 23, '2010-11-21');
