INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 8, 'The Fight Before Christmas', 'When the rest of the family seems to lack Christmas spirit, Marge contacts Martha Clause.', 23, '2010-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 9, 'Donnie Fatso', 'Homer ends up in the Springfield penitentiary after getting caught bribing an official; an FBI investigator offers Homer a way to reduce his jail time.', 23, '2010-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 10, 'Moms I''d Like to Forget', 'Marge reconnects with a close group of mothers she used to be friends with; Bart tries to break up their group when his playdates stop being fun.', 22, '2011-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 11, 'Flaming Moe', 'When Smithers transforms Moe''s pub into a refined and trendy lounge, the establishment becomes Springfield''s local gay hangout; Principal Skinner falls for the new, free-spirited music teacher.', 23, '2011-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 12, 'Homer the Father', 'When Homer insists Bart must earn the new dirt bike he wants, Bart comes up with a scheme; James Lipton interviews a TV cast.', 22, '2011-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 13, 'The Blue and the Gray', 'Moe attends a seminar in hope of gaining more confidence with women; Marge makes a change after discovering her gray hair.', 23, '2011-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 14, 'Angry Dad: The Movie', 'Bart''s film about an angry father quickly becomes a critical favorite, winning him several awards.', 23, '2011-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 22), 15, 'The Scorpion''s Tale', 'During a field trip, Lisa discovers desert water that makes usually combative creatures get along; after getting kicked out of the retirement home, Grampa comes to live with the family.', 23, '2011-03-06');
