INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 23), 20, 'The Spy Who Learned Me', 'Marge and Homer go on a date, but Marge is embarrassed when Homer talks during the movie; when Homer gets hurt and can''t work, he tries to learn how to be a better husband from a man he believes is a movie star.', 23, '2012-05-06');
