INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 2, 'Treehouse of Horror XXIII', 'A black hole threatens to swallow Springfield, Homer tries to find the source of paranormal activity, and a "Back to the Future" parody in which Bart keeps Marge from marrying Homer.', 23, '2012-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 3, 'Adventures in Baby-Getting', 'When Marge''s car falls into a sink hole, she buys the perfect replacement to fit her family of five. But she quickly grows to hate it because, as she tells a shocked Homer, the car would be too small if she wanted to have another baby. Meanwhile, Bart and his friends are determined to find out what secret Lisa is keeping when Bart finds her cryptic messages and follows her sneaking off downtown for covert meetings after school.', 22, '2012-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 4, 'Gone Abie Gone', 'Homer and Marge try to track down Grampa by following clues that lead to secrets from his past.', 23, '2012-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 5, 'Penny-Wiseguys', 'Homer is shocked to discover that his bowling teammate is an accountant for Fat Tony and his mob. When Fat Tony gets jury duty, he appoints Dan as the temporary don of the mafia. Meanwhile, Lisa adds insects to her vegetarian diet after she passes out in the middle of a saxophone solo, but starts questioning her decision when bugs start pleading for mercy in her dreams.', 22, '2012-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 6, 'A Tree Grows in Springfield', 'Homer wins a MyPad at the school auction and Steve Mobbs, who is now in heaven, talks to Homer through it. Homer goes into a funk when he breaks the myPad, until Ned Flanders discovers a miracle tree in the Simpsons'' back garden.', 23, '2012-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 7, 'The Day the Earth Stood Cool', 'A "cool family" from Portland moves in next door to the Simpsons. Homer is desperate to befriend them, while Marge is skeptical, thinking that being cool is not all it''s cracked up to be.', 23, '2012-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 8, 'To Cur, with Love', 'Grampa has to move into the Simpsons house following a fire at the retirement home, and on moving day, Homer ''throws his back out'' and ''rests'' at home. He later finds an advert for a video game, Villageville on his myPad, and starts playing. During that time, Homer loses Santa''s Little Helper. When the family find him, Homer doesn''t seem to care because he''s "not a dog person". Grampa later tells the rest of the family the story of Homer''s childhood companion, pet dog Bongo.', 22, '2012-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 9, 'Homer Goes to Prep School', 'Homer joins the "Springfield Preppers," an off-the-grid survivalist group whose leader has set up a top-secret retreat outside of town to prepare for the end of the world.', 22, '2013-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 10, 'A Test Before Trying', 'The fate of Springfield Elementary rests on Bart and his test scores, and Homer finds way to make money with his own parking meter.', 23, '2013-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 11, 'The Changing of the Guardian', 'A tornado touches down in Springfield which sucks up Santa''s Little Helper. While Homer and Marge are out looking for the family dog, the tornado strikes again and almost takes Marge and Homer. Marge is distraught about the kids and decide to pick a  guardian to care for the children.', 22, '2013-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 12, 'Love Is a Many-Splintered Thing', 'Bart''s dream girl, Mary Spuckler, comes to town, but his failure to pay her enough attention is having a negative impact on their relationship. Meanwhile, Homer once again runs afoul of Marge and lands in the doghouse.', 22, '2013-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 13, 'Hardly Kirk-ing', 'Bart and Milhouse explore the perks of adulthood following a shaving experiment.', 22, '2013-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 14, 'Gorgeous Grampa', 'Homer''s obsession with the TV show "Storage Battles" leads the family to discover Grampa''s past identity as "Gorgeous Godfrey," the most feared, villainous man in pro-wrestling history', 23, '2013-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 15, 'Black-Eyed, Please', 'When Flanders'' parents prove to prefer Homer''s company to his, he jealously responds by giving Homer a shiner, and then tries desperately to reconcile with him. Meanwhile, Lisa is at a loss to understand why a new substitute teacher is bullying her for no obvious reason.', 22, '2013-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 16, 'Dark Knight Court', 'Springfield''s Easter is ruined by a prank and all fingers point to Bart. It is up to Lisa to save her brother, in a student court presided over by Attorney General Janet Reno. Meanwhile, inspired by an old comic book, Mr. Burns becomes an ineffectual superhero—fruit bat man.', 23, '2013-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 17, 'What Animated Women Want', 'Homer''s behavior once again lands him in hot water with Marge and he needs to fathom a way to save his marriage, while a dose of "A Streetcar Named Desire" drives Milhouse to affect a Marlon Brando-esque bad-boy demeanor in an effort to impress Lisa.', 23, '2013-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 18, 'Pulpit Friction', 'Homer is recruited to be a deacon by the cutting-edge new pastor. The dry cleaner mistakenly switches Marge''s wedding dress for one of Krusty''s costumes.', 23, '2013-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 19, 'Whiskey Business', 'Moe is flying high after venture capitalists take a shine to his homemade whiskey, while Grampa, after injuring himself babysitting Bart, decides he''d rather be looked after by his grandson than be at the nursing home. Also, Lisa voices her displeasure at a hologram of music legend Bleeding Gums Murphy, and Sonny Rollins (as himself) shows up to ask her to stop all that jazz about boycotting a record label.', 23, '2013-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 20, 'The Fabulous Faker Boy', 'Marge encourages Bart to explore his creative side, and his initial reticence quickly subsides when she hires Slava’s beautiful daughter, Zhenya, as his new piano instructor. Homer is shocked when he loses the last two hairs on his head, and employs a wide variety of headgear to try and keep his new found baldness a secret from Marge.', 23, '2013-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 21, 'The Saga of Carl', 'Homer, Moe, Lenny and Carl win $200,000 in the Springfield Lottery. But when Carl takes off to Iceland – his homeland – with all the winnings, the guys embark on a Nordic adventure to get the cash back.', 23, '2013-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 24), 22, 'Dangers on a Train', 'When Marge tries to buy Homer snack cakes for their anniversary, she winds up meeting a married man who shares a common love of British Television. Ignorant of all, Homer attempts to secretly construct a romantic anniversary train in the Simpsons back yard.', 23, '2013-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 25, 'Season 25', NULL);
