INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 2, 'Treehouse of Horror XXIV', 'The scariest Simpsons Halloween show yet, featuring an opening by Guillermo Del Toro.', 23, '2013-10-06');
