INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 4, 'YOLO', 'Marge encourages Homer to cross an item off an old to-do list by inviting an old pen pal to visit; Lisa institutes an honor code at school.', 22, '2013-11-10');
