INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 6, 'The Kid Is All Right', 'Lisa discovers her new best friend is a Republican who is opposing her in the class election.', 23, '2013-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 7, 'Yellow Subterfuge', 'Principal Skinner promises the students that the best-behaved among them can take a ride in a submarine. When Skinner gives all the kids a clean slate, Bart believes even his own past indiscretions will be forgotten if he doesn’t get into any more trouble. Meanwhile Lisa tries to help a cash-poor Krusty to turn things around by suggesting he sell the foreign rights to his shows.', 22, '2013-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 8, 'White Christmas Blues', 'Springfield is inundated with holiday revelers after the nuclear power plant springs a radiation leak, causing snow to fall all over town. When the tourists drive up Christmas shopping prices, Marge opens up the Simpsons'' house to boarders.', 22, '2013-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 9, 'Steal This Episode', 'Homer becomes annoyed with movie theaters, so Bart teaches him how to download movies illegally. Homer is delighted with his discovery of free movies until he''s caught for piracy. Deputy Director Gratman, the FBI''s anti-piracy boss, is tasked with hunting down Homer, who stands accused of illegally downloading a film.', 23, '2014-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 10, 'Married to the Blob', 'When Comic Book Guy meets a woman writing an autobiographical manga, he seeks Homer''s advice on dating.', 22, '2014-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 11, 'Specs and the City', 'When Marge tries Homer''s new high-tech glasses on, he learns she''s seeing a marriage counselor; Bart refuses to buy Nelson a Valentine''s Day card.', 23, '2014-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 12, 'Diggs', 'A recent transfer student named Diggs rescues Bart from a confrontation with bullies.', 23, '2014-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 13, 'The Man Who Grew Too Much', 'During a research trip, Lisa learns that Sideshow Bob is the chief scientist at a big chemical engineering company; Marge tries to teach a teen church group about healthy sexual practices.', 22, '2014-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 14, 'The Winter of His Content', 'When Retirement Castle is closed, Marge asks Grampa and two other octogenarians to move in; Nelson befriends Bart after Bart defends him.', 22, '2014-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 15, 'The War of Art', 'After Lisa''s new pet guinea pig destroys the Simpsons'' living room art, Marge finds a beautiful painting at the Van Houten''s yard sale, which Homer snaps up for 20 bucks', 23, '2014-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 16, 'You Don''t Have to Live Like a Referee', 'Homer is recruited as a World Cup referee after Lisa extols his integrity on the youth soccer field in a Springfield Elementary speech contest. But when the Simpsons travel to Brazil (again), Homer finds his honesty tested by one of South America''s slickest gangsters in the soccer match-bribing business.', 23, '2014-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 17, 'Luca$', 'Lisa dates a competitive eater; Bart benefits from helping convict Snake Jailbird escape from a jam.', 23, '2014-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 18, 'Days of Future Future', 'Set in the future, Homer has a new clone for every time he dies. Lisa is married to a zombie version of Milhouse, while Bart deals with custody issues with his ex-wife, Jenda. Each defines what love means to them.', 23, '2014-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 19, 'What to Expect When Bart''s Expecting', 'When Bart''s voodoo doll spell accidentally makes his teacher pregnant, he becomes a savior to couples hoping to conceive.', 22, '2014-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 20, 'Brick Like Me', 'Homer wakes up in a Springfield where everyone and everything is made out of Legos, and he must figure his way out before he gets stuck in the plastic world forever.', 23, '2014-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 21, 'Pay Pal', 'Marge swears off befriending any more couples when Homer offends their charming new British neighbors, but when Lisa declares that she, too, doesn’t need friends, Marge reconsiders.', 22, '2014-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 25), 22, 'The Yellow Badge of Cowardge', 'Bart feels guilty after he wins the annual "last day of school" race around Springfield Elementary School, with help from Nelson, who beats up the frontrunner, Milhouse. Meanwhile, Homer tries to bring back 4th of July fireworks after they are canceled due to budget cuts.', 22, '2014-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 26, 'Season 26', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 1, 'Clown in the Dumps', 'A Springfield resident dies, Krusty retires after he''s offended by a comedy cable channel roast of him, and Lisa tries to protect Homer from getting hurt.', 22, '2014-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 2, 'The Wreck of the Relationship', 'When Bart disrespects Homer''s authority, Homer makes a point to try his hand at parenting. This proves fruitless, so Marge signs them up for the Relation Ship, where they''ll resolve their conflicts at sea. Meanwhile, Marge is in charge of Homer''s fantasy football league, but manages to win despite being the underdog.', 23, '2014-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 3, 'Super Franchise Me', 'Marge opens a sandwich franchise store after her sandwiches become a huge hit at Springfield Elementary. But running day-to-day at the store proves challenging, especially when the same franchise opens another location across the street.', 22, '2014-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 4, 'Treehouse of Horror XXV', 'In a Halloween-theme episode Bart reads Aramaic symbols from the bottom of his desk and he and Lisa are transported to an alternate world filled with demons. Also, Moe organizes a "Clockwork Orange"-ish gang in which member Dum (Homer) falls for a young lady (Marge) who wants him to quit. In a homage to "The Others," the Simpsons reconnect with their earlier incarnations from the Tracey Ullman era.', 23, '2014-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 5, 'Opposites A-Frack', 'Lisa brings in assembly woman Maxine Lombard to put a stop to Mr. Burns'' fracking operation, but is taken aback when the two political opponents find themselves attracted to one another.', 23, '2014-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 6, 'Simpsorama', 'The Planet Express crew come to present-day Springfield to prevent the Simpsons from destroying the future.', 22, '2014-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 7, 'Blazed and Confused', 'Bart schemes to bring down his new teacher, Mr. Lassen, who is a terrible bully. Meanwhile, The Simpsons go to Burning Man.', 22, '2014-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 8, 'Covercraft', 'Homer has a mid-life crisis, takes up bass guitar and forms a cover band with some of the other dads in town. But the band''s modest early success is soon overwhelmed by the breakout potential of their most unlikely star, Apu.', 23, '2014-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 9, 'I Won''t Be Home for Christmas', 'After Moe convinces Homer to stay out drinking on Christmas Eve, Marge tells Homer not to come home. This leads to Homer''s sad trek through lonely Springfield, where he learns that the only place where one should truly get drunk on Christmas is home.', 22, '2014-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 10, 'The Man Who Came to Be Dinner', 'During a trip to "Dizzneeland" the Simpsons board the wrong ride, Rocket To Your Doom, and are transported through the galaxy to Kang and Kodos'' home planet, where they are held captive at the local zoo and the inhabitants decide to eat Homer.', 23, '2015-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 11, 'Bart''s New Friend', 'Bart has a new accomplice and best friend when Homer is hypnotized at the circus and believes he is a young boy again.', 22, '2015-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 12, 'The Musk Who Fell to Earth', 'When inventor Elon Musk lands in Springfield, he and Homer become fast friends and revolutionize the town''s nuclear plant. But when Musk goes overboard and Mr. Burns wants him removed, Homer must figure out a way to break up with him.', 22, '2015-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 13, 'Walking Big & Tall', 'When Lisa learns Springfield''s anthem was stolen from another town she writes a replacement. Meanwhile, Homer learns the meaning of "Wide Pride".', 23, '2015-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 14, 'My Fare Lady', 'When Marge gets fed up with the thankless duty of chauffeuring her kids around, she begins working as a driver for a transportation app service. Meanwhile, Homer bankrupts Moe when he watches over the bar for one night, which forces Moe to take a temporary job as a janitor at the nuclear plant.', 22, '2015-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 15, 'The Princess Guide', 'Homer is put in charge of keeping Princess Kemi out of trouble while her father, a Nigerian king, works out a uranium deal with Mr. Burns.', 23, '2015-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 16, 'Sky Police', 'Chief Wiggum is mistakenly delivered a military jet pack, which he gleefully accepts and uses in order to fight crime. But when the jet pack crashes into the church, the congregation, led by Marge, must resort to gambling and counting cards in order to collect money to repair the church.', 23, '2015-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 17, 'Waiting for Duffman', 'When Duffman (guest voice Stacy Keach) undergoes hip replacement surgery and retires, the company sets up a reality show competition to find his replacement. Homer wins the competition, and because the job requires him to stay sober, he learns that beer isn''t as necessary as he thought to have a good time.', 23, '2015-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 18, 'Peeping Mom', 'Bart lies about being involved in a bulldozer crash, so Marge decides to follow him everywhere until he confesses. Meanwhile, Homer ignores Santa’s Little Helper when Flanders gets a new dog.', 23, '2015-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 19, 'The Kids Are All Fight', 'When Homer gets an old film roll developed, the family takes a trip down memory lane to see the origins of how Bart and Lisa first started fighting with each other.', 22, '2015-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 20, 'Let''s Go Fly a Coot', 'The Simpsons learn about Grampa’s days in the Air Force, and Bart takes up smoking to impress Milhouse’s Dutch cousin, Annika.', 23, '2015-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 21, 'Bull-E', 'After Bart gets bullied at the school dance, Marge convinces the town to pass anti-bullying legislation. Homer then gets arrested and sent to rehab for bullying Ned Flanders, only to subsequently leave rehab as a hero.', 23, '2015-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 26), 22, 'Mathlete''s Feat', 'When a modernized Springfield Elementary has a technical meltdown, Lisa transforms it into a Waldorf school. Meanwhile, Groundskeeper Willie becomes the coach of the mathletes.', 22, '2015-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 27, 'Season 27', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 1, 'Every Man''s Dream', 'Homer is diagnosed with narcolepsy, but instead of returning home with his prescription medication, he returns home drunk. He and Marge visit a marriage counselor and have a trial separation, during which Homer begins dating a 20-something.', 22, '2015-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 2, 'Cue Detective', 'Scotty Boom, a Chew Network super-chef, challenges Homer to a smoke-off. But when someone steals Homer’s secret weapon – a smoker he bought off a mysterious man at a BBQ shack – Lisa and Bart are on the case.', 23, '2015-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 3, 'Puffless', 'Upon learning that their father really died of lung cancer, Selma and Patty agree to quit smoking. When Selma relapses, an angry Patty moves in with Marge and Homer.', 23, '2015-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 4, 'Halloween of Horror', 'When Lisa becomes scared at the Krustyland Halloween Horror Night, Homer is forced to take down his Everscream Terrors decorations. Halloween pop-up employees seek vengeance on Homer for causing them to lose their jobs, and rob his house while Homer and Lisa hide out in the attic. Homer and Lisa light up their stored holiday decorations to attract attention and stand up to the intruders.', 23, '2015-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 5, 'Treehouse of Horror XXVI', 'In the annual fright fest Halloween episode, Sideshow Bob finally kills Bart, only to reanimate him; Homer wakes up with short-term memory loss; and Lisa, Bart, and Milhouse get super powers from radiation.', 22, '2015-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 6, 'Friend with Benefit', 'Lisa makes a new pal at school named Harper, whose internet billionaire father becomes buddies with a different Simpson: Homer. Soon, though, Lisa becomes worried that Harper is a little too entitled.', 23, '2015-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 7, 'Lisa with an ''S''', 'When Homer loses $5,000 at a poker game with Broadway legend Laney Fontaine, the only way he is able to settle the bet is if he loans Lisa to Laney for a month. Then, Laney turns Lisa into a show biz kid and Marge and Homer fear they made a mistake letting her go. So they head to New York to get her back.', 22, '2015-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 8, 'Paths of Glory', 'Lisa sets out to restore the tarnished reputation of Springfield’s first female inventor. To find her invention, she scours an abandoned asylum and a restaurant that caters to men. Bart joins Lisa at the asylum, stealing one of the homicidal patient’s notebooks, and bragging to the boys at school that he wrote the entries himself. This revelation causes Homer and Marge to believe he is a sociopath, which Bart decides to use to his advantage until things go too far.', 23, '2015-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 9, 'Barthood', 'Bart’s coming of age story a la “Boyhood” chronicles his life from six years old to his time as an accomplished young man. Along the way, his tense relationship with Homer, an overly uncaring version of himself, and Lisa, who overshadows him in every way possible, shape Bart more than he realizes.', 23, '2015-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 10, 'The Girl Code', 'After a photo Marge posts on social media gets Homer fired, he returns to the best job he ever had, a dishwasher at a Greek restaurant. This same post inspires Lisa to code an app that predicts the real-life consequences of anything you post online, only to create sentient artificial intelligence.', 23, '2016-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 11, 'Teenage Mutant Milk-Caused Hurdles', 'There is a new teacher at Springfield Elementary, and a captivated Bart tries everything to win her over. Meanwhile, Homer decides to buy a new brand of “milk,” which causes early puberty, both for Bart (augmenting his wooing powers) and Lisa (whose small bout with acne opens her up to the world of makeup and popularity).', 22, '2016-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 12, 'Much Apu About Something', 'Sanjay passes his stake in the Kwik-E-Mart to his millennial son, Jay, who turns it into a hip, health food market against Apu’s insistence on tradition. Bart, whom Homer had convinced to give up pranking, is called upon to return to his trickster life and take down the new store.', 22, '2016-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 13, 'Love Is in the N2-O2-Ar-CO2-Ne-He-CH4', 'Lonely Professor Frink uses science to turn himself into a man whom women find attractive. Then,  overwhelmed by the attention, he invents an algorithm to perfectly pair the lonely men and women of Springfield, realizing that scientific exploration is his true love. Meanwhile, Marge, Bart, and Lisa visit Grampa for Valentine''s Day and try to rescue the old folks from a drug-induced hallucination that allows them to relive their happiest memories.', 22, '2016-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 14, 'Gal of Constant Sorrow', 'After Bart accidentally sends a sweet homeless woman''s cart into the river, he allows her to live in his closet for a small fee. When Lisa discovers that the woman is an incredible folk singer, she offers her own closet and plans a concert, only to be disappointed by Hettie''s surprising substance abuse and violent nature. Meanwhile Homer tries to prove he''s handy, but accidentally traps the cat in the walls of the house.', 22, '2016-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 15, 'Lisa the Veterinarian', 'After performing CPR on a tased raccoon, Lisa discovers her calling to be veterinarian and becomes an intern at the local office, but learns a tough lesson when her neglected class hamster dies. Meanwhile, Marge moonlights as a crime scene cleaner for a little extra money, and the trauma of the gory scenes make her increasingly dead inside.', 23, '2016-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 16, 'The Marge-ian Chronicles', 'Not feeling unique, Lisa signs up for the Mars One Space Colony – to Marge’s dismay. Then, Marge hires Bart to go through the tryout process with Lisa to make her want to quit.', 23, '2016-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 17, 'The Burns Cage', 'After Smithers is crushed by Mr. Burns'' lack of affection towards him, other characters attempt to find a boyfriend for him. Meanwhile, Milhouse competes against a new boy for the lead role in a school production of Casablanca, so he can act alongside his own unrequited love, Lisa.', 22, '2016-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 18, 'How Lisa Got Her Marge Back', 'After getting into an argument, Marge takes Lisa on a touristy trip to Capital City, where, after attending a musical, they meet the show’s star who reminds Lisa how lucky she is to have such a great mom. Meanwhile, Bart is frustrated that everyone expects his pranks, so he teams up with Maggie to trick people.', 22, '2016-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 19, 'Fland Canyon', 'Homer recalls a tense family vacation to the Grand Canyon with the Flanders family. At first, the Flanders’ perfection puts the families at odds, but when they get stranded and Ned and Bart go for help, the families finally bond.', 22, '2016-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 20, 'To Courier with Love', '"The Simpsons are going to..." Paris (well, Homer and Marge are), but in order to be able to afford the trip, Homer has to smuggle an exotic snake into France so it can be made into a gourmet meal.', 22, '2016-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 21, 'Simprovised', 'After butchering a speech in front of all of his friends at work, Homer turns to improv comedy to gain back his confidence in his public speaking skills.  Meanwhile, Marge decides to rebuild Bart’s lackluster treehouse, but tensions rise when Bart questions her building skills. Also, in the episode’s last three minutes, Homer  appears LIVE for the first time on television (both for East and West Coast broadcasts) to answer fan questions.', 23, '2016-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 27), 22, 'Orange is the New Yellow', 'Marge goes to prison for letting Bart play in a park unsupervised.', 22, '2016-05-22');
