INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 14, 'Fatzcarraldo', 'All of the fast food restaurants in Springfield go healthy, forcing Homer to turn to the last bastion of greasy food for comfort.', 22, '2017-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 15, 'The Cad and the Hat', 'Bart deals with his guilt after betraying Lisa; Springfield is in awe of Homer when he is revealed to be a chess savant.', 22, '2017-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 16, 'Kamp Krustier', 'Bart and Lisa return home from Kamp Krustier early, interrupting Homer and Marge''s romantic encounters; Bart and Lisa confront a source of trauma.', 22, '2017-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 17, '22 for 30', 'Bart goes from delinquent with detention to the star basketball player at Springfield Elementary. Lisa covers Bart’s success for the school paper, and Homer becomes the team’s coach. Things go awry when Bart gets involved with the mafia', 23, '2017-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 18, 'A Father''s Watch', 'Marge turns to a series of parenting experts for advice when she becomes worried that Bart is destined for failure; Homer decides to open a trophy store; Grampa gives Bart a watch coveted by Homer.', 22, '2017-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 19, 'The Caper Chase', 'Disappointed in Yale, Mr. Burns decides to start his own for-profit university and Homer is hired as a professor', 23, '2017-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 20, 'Looking for Mr. Goodbart', 'Bart gets in trouble on Grandparents Day at school and is forced to hang out with Skinner''s mother as punishment. After spending time with various grandmas in the neighborhood, he learns the benefits of hanging out with the elderly, but eventually recognizes the dangers of taking advantage of them. Meanwhile, Peekimon Get has taken over the town of Springfield.', 22, '2017-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 21, 'Moho House', 'Mr. Burns makes a bet with his old friend that nothing can break Homer and Marge apart. But that''s where Moe comes in.', 23, '2017-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 28), 22, 'Dogtown', 'After a successful animal rights campaign, all dogs in Springfield are allowed to go where they want and do what they want. Pack mentality quickly kicks in and the dogs of Springfield assert their dominance by threatening the people.', 22, '2017-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')), 29, 'Season 29', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 29), 1, 'The Serfsons', 'In a magical medieval world, Marge''s mother is turned into an Ice Walker and the only way for Homer to afford the cure is to force Lisa to use illegal magic. When the King discovers this, he kidnaps Lisa, and Homer must lead a feudal uprising to save her.', 23, '2017-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 29), 2, 'Springfield Splendor', 'Marge and Lisa turn Lisa’s sad experience into a successful graphic novel-turned-Broadway show, but they struggle with creative differences and ego.', 23, '2017-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 29), 3, 'Whistler''s Father', 'Homer discovers that Maggie is a whistling savant and launches her baby-celebrity career. Meanwhile, Marge impresses Fat Tony with her interior design taste, and he hires her to style his brothel.', 22, '2017-10-15');
