INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 31), 9, 'Todd, Todd, Why Hast Thou Forsaken Me?', 'Todd blames God for the death of his mother and rejects his faith, so Ned sends him to live with the Simpsons, hoping they can scare him into believing in God again.', 22, '2019-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 31), 10, 'Bobby: It''s Cold Outside', 'Sideshow Bob gets contracted as this year’s mall Santa. Meanwhile, someone is stealing all the Christmas packages off people’s front porches.', 23, '2019-12-15');
