INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0096697')) AND numero_temporada = 31), 18, 'The Incredible Lightness of Being a Baby', 'Mr. Burns tasks Homer with swindling Cletus Spuckler out of his newfound helium fortune. Meanwhile, Maggie is reunited with Hudson from Playdate with Destiny again, only for Marge to tear them apart after his mother annoys her.', 23, '2020-04-19');
