INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 1, 'Prescription For Death', 'When a young woman dies during a hectic emergency room night shift, her father claims the hospital was negligent, and an investigation leads the detectives to believe that the doctor treating her may have been drunk on duty.', 48, '1990-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 2, 'Subterranean Homeboy Blues', 'The shooting of two black men by a white woman in a crowded subway initially appears to be a case of self-defense, but further investigation reveals revenge as a possible motive.', 47, '1990-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 3, 'The Reaper''s Helper', 'The death of a man with AIDS appears to be the work of a serial killer who may have been motivated by mercy.', 46, '1990-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 4, 'Kiss the Girls And Make Them Die', 'Stone has difficulty prosecuting a privileged preppie with a history of abusing his girlfriends after one of them dies at his hands.', 47, '1990-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 5, 'Happily Ever After', 'Greevey and Logan have a hunch that robbery is a cover for the real motive in the death of a millionaire in a parking garage.', 48, '1990-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 6, 'Everybody''s Favorite Bagman', 'The mugging of a councilman leads the detectives to arrest a mobster, who in turn leads Stone and Robinette to corrupt city officials.', 45, '1990-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 7, 'By Hooker, By Crook', 'When Logan and Greevey investigate how a family man came to be found unconscious in Central Park, they uncover a very high-class call girl operation run by a well-educated socialite.', 47, '1990-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 8, 'Poison Ivy', 'The shooting of a black honors student stirs up racial tensions, especially after it becomes apparent that the cop responsible for the death may have planted a gun on the body to excuse the shooting.', 47, '1990-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 9, 'Indifference', 'During the investigation into the death of a little girl in a respectable, middle-class family, Greevey and Logan uncover a myriad of family secrets involving abuse, molestation, and murder.', 48, '1990-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 10, 'Prisoner Of Love', 'A city arts commissioner and a socialite come under investigation when an artist noted for his sadomasochistic themes is found dead under suspicious circumstances.', 46, '1990-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 11, 'Out Of The Half-Light', 'Greevey and Logan''s investigation into a black teenager''s claim that she was raped by white policemen is hampered by a publicity hungry, black politician who will not grant the detectives access to the victim.', 47, '1990-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 12, 'Life Choice', 'Stone faces pressure from the public and from Schiff as he prepares to prosecute the person accused of bombing an abortion clinic.', 48, '1991-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 13, 'A Death In The Family', 'Police start a citywide manhunt for a man suspected of killing a cop during a rooftop pursuit.', 46, '1991-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 14, 'The Violence Of Summer', 'Greevey and Logan reopen an investigation to help Stone and Robinette build a stronger case against three boys accused of gang-raping a TV reporter.', 47, '1991-02-05');
