INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 16, 'The Torrents Of Greed (2)', 'Stone tries to salvage his prosecution of the Masucci family when Beigel faces bribery charges and seems willing to turn against his brother-in-law.', 47, '1991-02-19');
