INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 18, 'The Secret Sharers', 'Stone faces a flashy Texas lawyer and a hostile community as he tries to prosecute a young man accused of killing a drug dealer.', 48, '1991-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 19, 'The Serpent''s Tooth', 'Two brothers appear to be the logical suspects in the murder of their wealthy parents.', 48, '1991-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 1), 20, 'The Troubles', 'Logan is forced to face his cultural biases when both a Cuban drug dealer and an Irish terrorist are suspected of killing a Lebanese gunrunner.', 47, '1991-03-26');
