INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 4, 'Asylum', 'The conviction of a homeless man for murder is threatened on appeal based on the lack of a search warrant for his "home", which was a lean-to in Central Park.', 47, '1991-10-08');
