INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 6, 'Misconception', 'The mugging of a pregnant legal secretary leads to a case involving her lover, her boss and charges of murder when she loses the baby.', 48, '1991-10-29');
