INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 8, 'Out Of Control', 'The detectives investigate the gang rape of a college student during a fraternity Holloween party.', 48, '1991-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 9, 'Renunciation', 'A hit-and-run investigation leads to the discovery of a schoolteacher carrying on an affair with one of her students. Cerreta and Logan suspect that she may have manipulated him into killing her husband.', 47, '1991-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 10, 'Heaven', 'The investigation into a social-club fire which claimed 53 fatalities leads to a connection between arson, illegal immigrants and the sale of green cards.', 47, '1991-11-26');
