INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 12, 'Star Struck', 'An obsessive fan pleads temporary insanity when he is charged with attempting to murder the soap-opera actress who is the center of his life.', 47, '1992-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 13, 'Severance', 'Stone faces an old rival in court as he tries to link a hit man and three murders to a sleazy lawyer and a powerful man behind bars.', 47, '1992-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 14, 'Blood Is Thicker...', 'An apparent mugging ends in the death of a wealthy woman but the case comes to hang on a silver pin that may have been in the victim''s possession.', 48, '1992-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 15, 'Trust', 'Stone is determined to see that a teenage boy doesn''t get away with murder twice when the young man is brought to trial for the shooting death of one of his friends.', 48, '1992-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 2), 16, 'Vengeance', 'The parents of a murdered woman contest Stone''s prosecution of her killer so that he can be extradited to their home state, where the death penalty still exists.', 47, '1992-02-18');
