INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 1, 'Causa Mortis', 'McCoy''s new second chair, ADA Jamie Ross, is determined to prosecute as harshly as possible a carjacker who took the life of a teacher as she   pleaded for her life on an audio tape discovered at the crime scene.', 47, '1996-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 2, 'I.D.', 'The cops tackle identifying a corpse left in an elevator, and McCoy finds his prosecution of the suspect later hampered by a vindictive judge who resents Ross''s in-court rebuke for sexual harassment.', 47, '1996-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 3, 'Good Girl', 'Briscoe and Curtis have to break the mutual alibi of two girlfriends as they try to find the killer of a young black man, whose angry parents pressure McCoy to indict a young woman who claims the victim had raped her.', 47, '1996-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 4, 'Survivor', 'Briscoe and Curtis''s investigation of the murder of a rare coin dealer nets them a millionaire as a suspect, but Ross has to play detective too as the DA''s office tries to establish a provenance for the missing coin collection.', 47, '1996-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 5, 'Corruption', 'Curtis, angered by the attitude of an old colleague of Briscoe''s, looks beyond the findings of an IAB investigation and turns up evidence of police corruption that puts the DA''s office into competition with an ambitious judge and Briscoe under investigation for stealing evidence from a police lockup.', 47, '1996-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 6, 'Double Blind', 'The murder of a janitor in a university laboratory building leads back to a student employee whose participation in a drug study may have prompted the crime.', 47, '1996-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 7, 'Deadbeat', 'The murder of a deadbeat father whose son is dying of leukemia presents McCoy and Ross with a sympathetic suspect and a moral dilemma.', 47, '1996-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 8, 'Family Business', 'The murder of Richard Speigel, chief financial officer for an exclusive, family-owned department store goes from the sitting room to the bedroom and into the board room as suspicion shifts from co-workers to family members.', 46, '1996-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 9, 'Entrapment', 'The case against Huey Tate, a young man accused of shooting the well-known leader of the African-American Congress comes undone when the New York authorities learn that their chief witness was once an informant for the FBI, and is still under their protection.', 47, '1997-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 10, 'Legacy', 'The sidewalk shooting of a young husband uncovers the fact that his wife''s first husband died in a inadequately investigated accident, and that they may have been having an affair before it happened.', 47, '1997-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 11, 'Menace', 'The detectives face a difficult struggle getting witnesses to a girl''s apparent suicide to come forward while Ross tries to prove that a known bully is the one really responsible for her actions.', 47, '1997-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 12, 'Barter', 'An unpromising case of murder suddenly develops new leads when the cops explore the possibility that the victim was mistaken for someone else. McCoy walks a thin line in the matter of ethical conduct as he tries to make a case against a lendor who uses unscrupulous methods to collect the money owed to him.', 47, '1997-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 13, 'Matrimony', 'The discovery of a would-be thief refocuses a murder investigation, leaving the prosecutors the task of making a conspiracy case against the deceased''s attorney and the pretty young widow.', 47, '1997-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 14, 'Working Mom', 'The murder of an ex-cop with a penchant for blackmail and illicit sex brings feminist lawyer Lanie Stieglitz into court against McCoy to defend a suburban wife and mother.', 47, '1997-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 15, 'D-Girl', 'A headless corpse fished out of the river sends Briscoe and Curtis out to Los Angeles to obtain a blood sample from their chief suspect while McCoy and Ross back in New York try to obtain a court order for the procedure.', 45, '1997-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 16, 'Turnaround', 'Back in New York with their suspect, Briscoe and Curtis try to pin down his schedule on the night of the murder, but find instead that another man was in the area at the right time and more importantly, might have a motive for the crime. But after the issuance of a new arrest warrant, McCoy and Ross have to fly to LA to defend their warrant against attacks by the man''s defense counsel, Ross''s former husband Neal Gorton.', 45, '1997-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 17, 'Showtime', 'The trial of Eddie Newman begins but the prosecution''s chances of conviction are hampered by a "dream team" of defense attorneys, Gorton''s personal pressures on Ross, the public questioning of the relationship between Curtis and Lisa Lundquist, and a surprise accusation.', 47, '1997-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 18, 'Mad Dog', 'McCoy becomes obsessed with nailing a serial rapist recently released on parole and pushes the cops perilously close to harassment as he attempts to connect the man with a new rape and murder matching his previous M.O.', 48, '1997-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 19, 'Double Down', 'The cops'' best hope of finding a kidnapped hired car driver alive is one of the armed robbers who grabbed him after a job, but the immunity deal he demands in return would effectively preclude his prosecution for the shooting death of an off-duty cop, placing McCoy in a difficult position as he seeks to placate the cops, who want the guy prosecuted, and the kidnapped man''s wife, who wants every avenue of saving her husband explored.', 47, '1997-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 20, 'We Like Mike', 'A young man who claims to have helped a murdered young man change a flat tire is first the cops'' primary suspect, then the prosecutors'' chief witness.', 47, '1997-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 21, 'Passion', 'Briscoe and Curtis investigate the death of a pretty young book editor who was reputedly having an affair with one of her authors, and find themselves focusing on the author''s long time companion, who steadfastly denies there was anything wrong with their relationship.', 47, '1997-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 22, 'Past Imperfect', 'The cops have a definite clue when a bloodstain that''s not the same as the victim reveals that the killer was a blood relative, and the prosecutors stumble when their chief suspect claims their chief witness is her lawyer, and his knowledge of the crime represents privileged communications.', 47, '1997-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 7), 23, 'Terminal', 'The cops uncover a man with a secret second life as they try to learn who opened fire on a group of people disembarking from a party cruise, but his guilt or innocence becomes almost a second thought as Schiff goes toe to toe with the governor and the States Attorney General over the decision to seek the death penalty.', 47, '1997-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 1, 'Thrill', 'The cops break the seemingly random murder of a pizza delivery guy with a little ""undercover"" work in the park, but McCoy and Ross face a harder battle to get a conviction when the two defendants resolutely point the finger at each other, and the one item identifying the actual killer is the recording of a confession-made to a priest.', 47, '1997-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 2, 'Denial', 'Bloody sheets and an apparently stolen credit card lead Briscoe and Curtis to a pair of college age lovers who present McCoy and Ross with a united front of denial that one of them killed their newborn son and disposed of the body.', 47, '1997-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 3, 'Navy Blues', 'McCoy finds himself battling the Navy and the office of the Judge Advocate General as he tries to prosecute a female pilot accused of murdering her married lover after he tried to break off with her.', 46, '1997-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 4, 'Harvest', 'A discrepancy concerning the time of death of a drive-by shooting victim leads McCoy and Ross to initiate prosecutions against both the shooter and the doctor who harvested her organs as transplant donations.', 47, '1997-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 5, 'Nullification', 'After the cops trace an eagle tattoo on a man shot and killed while holding up an armored truck to a group of militia members, McCoy finds himself facing one of their number as the pro se counsel for his friends, arguing for the concept of "jury nullification", the right of a jury to protect a defendant from an unjust law by finding him not guilty despite the evidence.', 47, '1997-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 6, 'Baby, It''s You (I)', 'It''s old home week for Briscoe when an apparent murder of a teenage model in New York develops ties to Baltimore and Detectives Munch and Falsone pay a visit to the Big Apple to observe the case. Meanwhile, McCoy finds himself battling the attorney of the victim''s parents for access to his clients and the Baltimore DA for jurisdiction.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 7, 'Blood', 'The paternity of a black baby given up for adoption by a white mother might provide a clue to her murderer but it also unearths some long buried family secrets.', 47, '1997-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 8, 'Shadow', 'The murder of a bail bondsman looks fairly routine until the chance words of the chief suspect uncovers possible case-fixing between a shady lawyer and an unknown contact within the judicial system.', 47, '1997-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 9, 'Burned', 'A message overheard on an answering machine leads Briscoe and Curtis to a confessed murderer and the home of wealthy Carl Anderton, whose stubborn non-cooperation with the district attorney threatens to create a serious miscarriage of justice.', 45, '1997-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 10, 'Ritual', 'The investigation into the death of a man who initially appears to be the victim of a mugging victim reveals him to be a Middle Eastern physician who performs genital mutilations on young girls.', 45, '1997-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 11, 'Under the Influence', 'After Briscoe and Curtis finally determine who was driving the car that killed three people, the legal prosecution stands in danger of becoming a kangaroo court when McCoy''s feelings over Kincaid mesh with the political agenda of an ambitious judge anxious to make an example of the defendant.', 47, '1998-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 12, 'Expert', 'The shooting of two people in a restaurant restroom takes some abrupt turns as they try to discover who exactly the intended victim was, and the prosecutors have to deal with a defendant claiming to have been in a dissociative state while committing the crime-- the same defense used years before by the defendant''s father.', 47, '1998-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 13, 'Castoff', 'The street murder of a woman who worked with underprivileged kids takes a turn towards the bizarre when the detectives uncover she had a predilection for kinky sex, and that one of her current partners appears to be a serial killer, who offers an overexposure to television violence as his defense during his trial.', 46, '1998-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 14, 'Grief', 'The cops, as they try to pin down the specifics of an assault on a man reluctant to talk about it, uncover the alleged rape of two women in custodial care. But as the prosecutors attempt to prepare their case, a reluctant witness changes their view of the cases.', 46, '1998-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 15, 'Faccia a Faccia', 'Taking on an apparent mafia murder, Detectives Briscoe and Curtis are stymied by a dead witness and a seemingly incoherent mob boss.', 47, '1998-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 16, 'Divorce', 'The stabbing death of a psychologist draws Detectives Briscoe and Curtis into a heated divorce case and pits McCoy and Ross against a manipulative attorney.', 47, '1998-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 17, 'Carrier', 'The death of a college student leads to a case involving an HIV-positive male who''s seeking to infect as many young women as possible. McCoy, testing right-to-privacy ethics, wants to charge him with murder.', 46, '1998-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 18, 'Stalker', 'When a woman is found unconscious at the bottom of her apartment stairs, Briscoe and Curtis must figure out what happened -- before it''s too late. In order to make his case, McCoy pits the two detectives against each other in the courtroom.', 46, '1998-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 19, 'Disappeared', 'A defendant refuses to allow his lawyer to raise the issue of insanity, this complicating matters for the brother who turned him in with hopes of securing medical treatment for him.', 46, '1998-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 20, 'Burden', 'After a 12-year-old quadriplegic dies at home in his bed, paramedics claim that he was suffocated and the suspects include the boy''s parents and sister.', 47, '1998-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 21, 'Bad Girl', 'Schiff''s re-election may hinge on the stabbing death of a police officer; Briscoe''s daughter is arrested for dealing drugs.', 47, '1998-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 22, 'Damaged', 'The case of a teacher''s shooting uncovers a vendetta involving the rape of a mentally challenged coed by three students, whose attorney claims they weren''t aware of her condition.', 47, '1998-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 8), 23, 'Tabloid', 'Tabloid journalism comes under scrutiny during the investigations into the deaths of a gossip columnist and a celebrity target he pursued.', 45, '1998-05-13');
