INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 10), 22, 'High & Low', 'Detectives Briscoe and Green probe the strangulation of a college coed who moonlighted as a stripper, and while they believe a pair of drug-dealing skinheads   committed the murder, they struggle to determine the motive of the strip club owner who paid them for the hit. However, as they work their way up the ladder   of complicity, the cops learn that the slaying is keyed to an insider trading scam that forces Assistant D.A. McCoy to connect a former porn star with   a businessman.', 45, '2000-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 10), 23, 'Stiff', 'The detectives'' investigation into why a wealthy woman is comatose involves her husband, daughter and doctor.', 44, '2000-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 10), 24, 'Vaya Con Dios', 'The death of an elderly man trying to find who was responsible for the torture killing of his son in 1973 Chile leads to a high-level foreign colonel who is now in a Manhattan hospital.', 46, '2000-05-24');
