INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 1, 'Endurance', 'After a disabled boy dies of smoke inhalation during a fire, his parents and a building tenant with a history of ""accidental"" fires become suspects.', 45, '2000-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 2, 'Turnstile Justice', 'After a woman''s body is found in a subway station, a suspect is arrested, but the resulting case concerns the lack of medication supplied him while in prison.', 45, '2000-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 3, 'Dissonance', 'The detectives investigate the murder of a young violinist whose fellow musicians resented her rapid rise to fame, in a trial that results in threats exchanged between Lewin and the presiding judge who has a history of bias against McCoy.', 45, '2000-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 4, 'Standoff', 'After a prisoner''s murder, an investigation leads to a suspect, but the question arises if he acted on his own or on orders from within the prison.', 45, '2000-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 5, 'Return', 'The murder of a storeowner leads to a case where the suspect flees to Israel and may be protected from extradition by Israel''s Law of Return.', 45, '2000-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 6, 'Burn Baby Burn', 'A former Black Panther, accused of murdering a Caucasian police officer, questions Green''s integrity amidst a politically charged trial.', 45, '2000-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 7, 'Amends', 'Under pressure from the department''s top brass, a 20-year-old murder case, initally investigated by Briscoe''s now retired boss, is reopened involving the slaying of a teen-age girl with the spoiled son of a politically connected family as the prime suspect.', 45, '2000-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 8, 'Thin Ice', 'The killing of a school-hockey coach leads to a case in which the defendant claims that he committed the crime while suffering from ""sports rage.""', 45, '2000-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 9, 'Hubris', 'An assistant manager at a jewelers discovers four bodies at the store, leading to the prosecution of an amiable murder suspect who insists on representing himself, and winning the admiration of a female juror.', 45, '2001-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 10, 'Whose Monkey is it Anyway?', 'The death of a lab technician and the abduction of 17 infected monkeys lead to a trial involving the treatment of research animals.', 45, '2001-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 11, 'Sunday in the Park with Jorge', 'Following "wilding incidents" in Central Park, a woman''s body is found in the lake and the suspects include the deceased''s wealthy husband.', 45, '2001-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 12, 'Teenage Wasteland', 'The beating death of a restaurant owner leads Briscoe and Green to thrill-seeking teenagers; McCoy and Lewin are forced to decide how young is too young for the death penalty.', 45, '2001-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 13, 'Phobia', 'When a gay man is beaten to death during the abduction of his adopted infant son, Detectives Briscoe and Green suspect that ransom from the murder victim''s wealthy partner may have been the motive for the crime. But as more is learned about the child''s birth mother and homophobic biological father, Assistant D.A.''s McCoy and Carmichael find that what appeared to be a botched kidnapping might be more accurately prosecuted as a hate crime.', 45, '2001-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 14, 'A Losing Season', 'When a pregnant loan officer is found in the trunk of her car with fatal gunshot wounds, Detectives Briscoe and Green at first suspect a carjacking or the woman''s fiance and co-worker. But as the woman''s premature baby clings to life in the hospital, the investigation turns to professional basketball player Cris Cody, whose ties to the dead woman may extend beyond the loans she approved for him--and may include reason for him to want her and her unborn child dead.', 45, '2001-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 15, 'Swept Away - A Very Special Episode', 'When a participant in a TV reality show is murdered, McCoy goes after the producers and network executives for deliberately fomenting hostility among the participants to boost the ratings. All too appropriately, the outcome of the case hinges on a videotape made by a hidden-camera.', 45, '2001-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 16, 'Bronx Cheer', 'When a woman is found strangled to death with a large quantity of the drug Ecstasy in her handbag, Detectives Briscoe and Green have difficulty gathering sufficient evidence for an indictment of their prime suspect, drug-dealer Francis ''Taz'' Partell. But when they question one of his former associates, they discover new evidence indicating that Taz is responsible for the earlier murder of a bouncer in Bronx county.', 45, '2001-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 17, 'Ego', 'When the dead body of Karen Hall, an investigator with the State Attorney General''s Office Criminal Division, is found in a Manhattan river, Detectives Briscoe and Green find that her boss, Frank Conroy, had written off her disappearance as a random kidnapping from an Albany train station. But as more is learned about Conroy''s controlling relationships -- with the dead woman, with his wife and with a long-term girlfriend -- he quickly becomes a suspect.', 45, '2001-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 18, 'White Lie', 'When a couple is found dead in their apartment, Detectives Briscoe and Green follow the trail of drugs and money, which leads to Caryn Wyman, the wife of a U.S. Army Major responsible for the country''s anti-drug efforts in Colombia. Despite the evidence linking Caryn to the drugs, she is fearful of cooperating with the police--until A.D.A. McCoy convinces her and her husband that she has no choice but to risk her life to catch the killer.', 45, '2001-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 19, 'Whiplash', 'When an hispanic male is found dead from a severe chest trauma, Detectives Briscoe and Green discover that he and two other illegal immigrants had been in a staged automobile accident. As evidence mounts linking numerous similar car crashes with the same employer, chiropractor, insurance adjuster, and lawyers, A.D.A.s McCoy and Carmichael must determine who is ultimately responsible for the man''s death, from which so many others profited.', 45, '2001-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 20, 'All My Children', 'The murder of a prep school student points to a mystery woman who may have been extorting money from the victim''s wealthy father.', 45, '2001-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 21, 'Brother''s Keeper', 'Briscoe and Green discover a murdered businessman may have been the target of a well-known criminal , but the investigation stumbles when the FBI acts as the suspect''s alibi.', 45, '2001-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 22, 'School Daze', 'Jamie Ross returns to defend a student accused in a mass school slaying.', 45, '2001-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 23, 'Judge Dread', 'An attempted murder of a tough Judge leads Briscoe and Green on a wild goose chase to track down the inimical criminal.  When the perpetrator is found, Carmichael and McCoy have a difficult time making a case.', 45, '2001-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 11), 24, 'Deep Vote', 'A woman''s murder leads the police to discover   the actual target was a reporter who did a story about improprieties in a recent senatorial election.   Carmichael can''t get the reporter to reveal her sources for a story that contains allegations that the vote was fixed and ballots tampered with, even though   the reporter''s life is at risk.   Without the source, McCoy and Carmichael have a difficult time making a case against the Senator, who they believe has ties to the mob and ordered the hit   on the reporter. The case hinges on 2000 missing ballots from the vote that were stolen by the mob. Once the ballots are found, there is a big court battle   about whether or not the ballots should be counted. McCoy believes that the ballots will show Benton''s motive for ordering the hit, but an appellate court   won''t allow it, so their case is virtually dead.   In the end, McCoy is able to convince the reporter to reveal her source and have him testify against the senator.', 45, '2001-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 1, 'Who Let The Dogs Out?', 'The investigation into the death of a jogger mauled by a vicious dog leads to an Attica inmate, his attorneys, and an underground dog-fighting ring.', 45, '2001-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 2, 'Armed Forces', 'The fatal stabbing of a man leads to the discovery of his status as a Vietnam war veteran and the truths uncovered about an incident that occured with him and three former soliders in his division.', 45, '2001-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 3, 'For Love Or Money', 'The death of a parolee, who was a hit man, leads to a wealthy widow and daughter and whether they hired him to kill their rich relative.', 45, '2001-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 4, 'Soldier of Fortune', 'The daring daylight kidnapping of a diamond dealer which results in two murders at the scene uncovers an international dynasty of diamond sales and its links to a foreign civil war.', 45, '2001-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 5, 'Possession', 'Investigating the murder of a woman in a rent-controlled apartment, the detectives discover that she was engaged in a long-running battle with her landlord and had been blocking the potentially lucrative sale of the building.', 45, '2001-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 6, 'Formerly Famous', 'The shooting death of a former singer''s wife leads the detectives to investigate his manager and sons after his explanation of the events surrounding her death have no credibility.', 45, '2001-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 7, 'Myth of Fingerprints', 'A murder investigation uncovers deliberately faulty forensics in the wrongful conviction of two men 12 years earlier in the case that paved the way for Van Buren''s promotion.', 45, '2001-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 8, 'The Fire This Time', 'When a building is set ablaze, a girl must be identified despite her fatal burns. Through further investigation, it turns out that an extreme environmentalist group struck the match...', 45, '2001-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 9, '3 Dawg Night', 'When a celebrity is implicated in a nightclub murder, McCoy and Southerlyn battle the flaks who attempt to insulate their client from any involvement or interrogation.', 45, '2001-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 10, 'Prejudice', 'The murder of a magazine publishing company''s black CEO leads to a suspect who has a clear streak of racism and whose attorney intends on using that as a mental defect.', 45, '2001-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 11, 'The Collar', 'The death of a cleric leads the detectives to a priest who was given information by a murder suspect outside of the church but insists that he can''t discuss anything about it, bringing McCoy to question whether the confessional seal should apply.', 45, '2002-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 12, 'Undercovered', 'The father of a dying girl gets his revenge on an insurance executive who denied a certain leukemia treatment for his daughter. One problem arises when the father is technically on both sides of the law.', 45, '2002-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 13, 'DR 1-102', 'The bludgeoning of two women in their apartment leads the detectives to a suspect who has taken a hostage while demanding legal representation ... and Southerlyn''s actions, while heroic, results in disbarment proceedings against her for violation of Disciplinary Rule 1-102.', 45, '2002-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 14, 'Missing', 'When a girl''s parents frantically search for her, Briscoe and Green see that the girl''s belongings were packed up in her apartment. They learn that the girl had been seeing a married man -- her boss. When the boss is brought up on charges, his wife sheds some new evidence.', 45, '2002-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 15, 'Access Nation', 'The murder of a psychologist leads to a case involving a computer company that sells information and their responsibility in shielding their clients'' history in order to serve their needs.', 45, '2002-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 16, 'Born Again', 'The investigation into the death of an 11-year-old girl uncovers the possible culpability of the child''s mother and a rebirthing therapist.', 45, '2002-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 17, 'Girl Most Likely', 'When a high school student is found dead in an apartment building, Briscoe and Green suspect that the murder was a result of her running a website.  As McCoy and Southerlyn investigate the case further, they realize that her best friend, who was reluctant to come forward as a witness, may be the answer to the murder.', 45, '2002-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 18, 'Equal Rights', 'A stock analyst''s murder leads the detectives to a corporation whose stock had fallen ... and plenty of suspects in the investors.', 45, '2002-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 19, 'Slaughter', 'The investigation of a student''s killing leads to a case involving meat contamination at a food service.', 45, '2002-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 20, 'Dazzled', 'A woman is drugged and falls to her death, and the evidence suggests that her ex-boyfriend and her current husband''s ex-wife may have conspired to kill her.', 45, '2002-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 21, 'Foul Play', 'The investigation into the death of a private investigator uncovers corruption, deceit, and immigration fraud in a Youth Baseball League whose manager will go to any lengths to win.', 45, '2002-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 22, 'Attorney Client', 'The wife of an attorney with many disgruntled clients is killed but the detectives believe that he was the intended target as he was willing to reveal information despite confidentially agreements.  As the investigation continues, his tumultuous love life is exposed and the prosecutors are suspicious of his desire to return to the courtroom.', 45, '2002-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 23, 'Oxymoron', 'The investigation of a woman''s strangulation leads to a case involving the selling of drugs and a gangster''s son.', 45, '2002-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 12), 24, 'Patriot', 'A tenement building explodes and the lone victim is Joseph Haden. The building was rent controlled and there had been a tenant strike, so the police initially suspect arson. But the landlord doesn''t have insurance, ruling out their arson theory, and the medical examiner discovers that Haden''s neck was broken and he was tied up before the explosion happened. Trying to figure out Haden is even more difficult. He didn''t appear to have a family or a girlfriend and never got any substantial mail. He worked at the Jiffy Job service station making minimum wage, yet had $90,000 in the bank. Briscoe and Green do some more digging and find out that Haden was using an alias, and his real name was Yusuf Haddad.', 45, '2002-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 1, 'American Jihad', 'An American Muslim becomes the prime suspect in a double murder after an academic challenges his religious beliefs.', 45, '2002-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 2, 'Shangri-La', 'The murder of a female high school English teacher uncovers a love triangle that includes a female student and a male teacher, both of whom become suspects.  The prosecutors have to deal with the student''s multiple identities and refusal to live past adolescence.', 45, '2002-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 3, 'True Crime', 'Investigating the death of a rock band singer who had large amounts of cocaine and heroin in her system, the detectives question a former boyfriend who was a disgruntled band mate of her late husband.  The prosecuters are hampered by the actions of a retired detective, who worked a case with Briscoe several years back, turned writer whose unconventional research tactics makes him a suspect as well.', 45, '2002-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 4, 'Tragedy on Rye', 'A struggling actress is murdered in an apparent robbery-homicide where a video tape, made by a couple touring the city sold to a local news station, shows three suspects loading the stolen property into an SUV.  They are charged with felony murder, a capital crime, and causes unrest with Southerlyn surrounding the death penalty.', 44, '2002-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 5, 'The Ring', 'The discovery of a body in Hells Kitchen who had been wearing a $40,000 diamond ring leads the detectives back to the World Trade Center attacks as the victim had been reported to have died when Tower One collapsed.  The ensuing investigation leads to a fiancee and a lover and the determination that the events of 9/11 may have been good timing to hide the fact that she was murdered the night before.', 43, '2002-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 6, 'Hitman', 'The execution style shooting of a city contractor leads Detectives Briscoe and Green to suspect a professional hitman. They first focus upon possible enemies of the victim, but end up suspecting the victim''s wife and her boyfried of hiring the killer. However later discovered evidence leads McCoy and Southerlyn to a conspirator that no one had suspected.', 45, '2002-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 7, 'Open Season', 'A defense attorney who had just acquitted a cop killer is gunned down outside a Manhattan restaurant.  The detectives start with police officers in the precinct of the injured officer, then to his brother, before they are led to a white supremacist who is part of a national network.  McCoy is faced with the unlikely prospect that the defendant''s attorney, his friend of 20 years and a friend of the slain lawyer, played a part in the murder of a Florida district attorney following the defendant''s arrest.  McCoy is able to make a deal that perserves the integrity of his adversary, but not without a cost.', 45, '2002-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 8, 'Asterisk', 'A star baseball player becomes the prime suspect in the murder of his limousine driver when it is discovered that the driver regularly supplied steroids to the sports icon.  The subsequent investigation reveals blackmail as the underlying motive for the murder.', 44, '2002-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 9, 'The Wheel', 'The smoldering corpse of an Asian girl found outside the Chinese consul general''s apartment leads the detectives to believe she had made a political statement.  When forensics shows that she had been murdered beforehand, they find themselves in the middle of a religious conflict with the consul general their prime suspect and his attorney an old friend of District Attorney Branch.', 43, '2002-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 10, 'Mother''s Day', 'The hit-and-run death of a popular high-school student leaves the detectives suspecting the girl''s father was the real target. When evidence reveals that the death was possibly a random killing, they are able to track down their suspect to his apartment. However things get complicated when their killer is murdered, and the person who committed the crime happens to be the victim''s mother.', 45, '2003-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 11, 'Chosen', 'The murder of a bookie with a high-class clientelle leads the detectives to arrest his partner.  Charged with first-degree murder, his attorney puts forth an unusual defense strategy that turns the trial into a political statement.', 45, '2003-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 12, 'Under God', 'A dead teenager''s father and a vigilante priest are suspects in the killing of a drug dealer.', 45, '2003-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 13, 'Absentia', 'When the witness in a jewelry store robbery-homicide fails to appear in court, McCoy suspects foul play until he discovers that the man is a fugitive in a 20-year-old murder case.', 45, '2003-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 14, 'Star Crossed', 'The bludgeoning of a luxury sports car dealer leads the detectives to a mentally challenged man and his girlfriend who is extremely attractive and whose expensive tastes leads her to be equally manipulative.', 45, '2003-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 15, 'Bitch', 'The death of a stockbroker leads the detectives to his girlfriend whose mother is a cosmetics mogul who has a long standing friendship with Branch, and will stop at nothing to protect her corporate image by using hormone replacement therapy withdrawal as the basis for her defense.', 45, '2003-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 16, 'Suicide Box', 'A media-savvy attorney defends a black teenager accused of shooting an off-duty policy officer.', 45, '2003-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 17, 'Genius', 'Investigating the murder of a cab driver, the detectives come to suspect a famous author and his protege, a former child prodigy.', 44, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 18, 'Maritime', 'A missing football player becomes the prime suspect in the murder of a woman whose body is discovered floating in the East River.', 44, '2003-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 19, 'Seer', 'The prime suspect in the murder of a woman outside a sex club claims to have merely witnessed the crime via a psychic vision.', 43, '2003-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 20, 'Kid Pro Quo', 'The murder of an admissions director of a private school leads the detectives to investigate a pair of angry parents whose children were denied admission, but then set their sights on the headmaster when they discover that the victim was about to go public with the denied admissions.', 43, '2003-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 21, 'House Calls', 'The suspicious death of a Russian model leads the detectives to suspect medical malpractice.', 43, '2003-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 22, 'Sheltered', 'It''s a race against time as the detectives go on the hunt for a sniper whose victims are shot in broad daylight.', 45, '2003-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 23, 'Couples', 'Briscoe and Green catch four murders and a kidnapping on the same day, and get handed confessions in each case.', 42, '2003-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 13), 24, 'Smoke', 'Briscoe and Green are assigned to a case involving an eccentric comedian who may have killed his young son by dangling him off a ledge.', 45, '2003-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 14, 'Season 14', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 1, 'Bodies', 'While investigating the death of a teenaged girl, the detectives stumble on a pattern of crimes that indicate they are after a serial killer.  The suspect, however, puts the prosecutors through an ethical ringer when he discloses his attorney''s knowledge of the victims and their whereabouts.', 45, '2003-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 2, 'Bounty', 'The investigation into the murder of a bounty hunter leads to a reporter with compromised ethics and a dubious defense strategy.', 45, '2003-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 3, 'Patient Zero', 'The investigation into the carjacking of a vehicle containing vials of a deadly virus leads the detectives on a search for the first person infected with the virus and a biochemist whose sinister motivations were driven by passion.', 45, '2003-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 4, 'Shrunk', 'The police and prosecutors investigate the connection between an award-winning songwriter and the young woman found murdered in his home to discover who would profit by her death at his hands.', 45, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 5, 'Blaze', 'A teenager''s need for parental love, acceptance and recognition sets in motion the events leading to the deaths of 23 concert goers for a band''s illegal pyrotechnics.', 45, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 6, 'Identity', 'When a man is found murdered shortly after depositing almost $400,000 in his savings account, the investigation into the source of funds reveals that the victim ran an identity theft scam which left an elderly man homeless and impoverished.', 45, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 7, 'Floater', 'The husband of a woman whose partially decomposed body is found floating in the Hudson River becomes the prime suspect in her murder until the prosecutors uncover a connection between her prospective attorney and a judge who has heard a suspiciously high number of his cases.', 45, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 8, 'Embedded', 'After a reporter accused of causing the deaths of soldiers with whom he was embedded in Iraq by reporting on their troop movements is shot and wounded on the eve of his return to the front, the ballistics report indicates that the gun belonged to one of the dead soldiers, leading the detectives to uncover who brought the gun back from the front and committed the crime.', 45, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 9, 'Compassion', 'When a con man passing himself off as a grief counselor is poisoned by a respected doctor he victimized, McCoy must determine whether revenge or insanity prompted the crime.', 45, '2003-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 10, 'Ill-Conceived', 'The owner of a clothing company with alien immigrant workers is found murdered which sends the detectives on a search for an unidentified evening caller whose girlfriend, also a worker in the factory, recently gave  birth.  Upon discovery that the victim was also the baby''s father, the boyfriend is arrested with the motive being an office affair until the victim''s widow discloses that it was a surrogate arrangement.', 45, '2003-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 11, 'Darwinian', 'The apparent hit-and-run of a homeless man send the detectives on a search for the driver, a high profile female publicist, which fuels the fire for the prosecutors to obtain a murder conviction.  Forensic evidence given during the trial reveal that the victim was severely beaten before being hit by the car which leads to a suspect within the homeless community.', 45, '2004-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 12, 'Payback', 'The investigation into the murder of a former bookie turned mob informant reveals a disturbing new wrinkle in organized crime involving legitimate businessmen moonlighting as contract hitmen in a battle for mob leadership, and ends with a Federal ploy to nullify the plea bargain in the case, leaving McCoy seething and two more people dead.', 45, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 13, 'Married with Children', 'The death of a woman who fell from a hotel balcony leads to a case involving a lesbian couple and a state law banning gay adoption', 45, '2004-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 14, 'City Hall', 'A city employee''s clerical error sets in motion a chain of events which culminates in a fatal shooting at City Hall and a secret Federal court proceeding with sinister implications.', 45, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 15, 'Veteran''s Day', 'A decorated Gulf War veteran grief-stricken over the Afghanistan combat death of his son murders an anti-war protester, claiming at trial that he acted under extreme emotional distress.', 45, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 16, 'Can I Get a Witness?', 'McCoy faces an uphill battle in proving that witnesses to the murder of a drug mule were bribed, intimidated, and eventually murdered on the orders of the drug dealer accused of the crime.', 45, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 17, 'Hands Free', 'When McCoy fails to win a murder conviction against an eccentric cross dressing millionaire for the death of his neighbor, he redoubles the effort to convict the man for  murdering his second wife years earlier by demonstrating that he murdered a witness to the crime.', 45, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 18, 'Evil Breeds', 'When a Holocaust survivor is murdered on the eve of her testimony in the deportation trial of a former concentration camp guard, McCoy prosecutes the man and the Neo-Nazi sympathizer who''s running a fundraising web site for him, and must debunk a Holocaust denial defense which claims that the millions of deaths resulted from disease, pestilence and wartime conditions.', 45, '2004-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 19, 'Nowhere Man', 'The District Attorney''s Office is set on its ear when the investigation into the death of an A.D.A. uncovers a scandal that could imperil hundreds of cases.', 45, '2004-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 20, 'Everybody Loves Raimondo''s', 'Greed, treachery and disrespect shape the motives for murder when two men are gunned down at an exclusive restaurant.', 45, '2004-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 21, 'Vendetta', 'The investigation into a bar room brawl fatality reveals a detective''s decades-old vendetta against a petty criminal turned murderer who was falsely accused of one murder after evading conviction on another.', 45, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 22, 'Gaijin', 'Van Buren has reservations about Branch''s tactics in luring a Ginza nightclub owner back to New York after the Japanese government is unwilling to extradite him to face charges of conspiracy and murder in the death of his wife on a New York City vacation.', 45, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 23, 'Caviar Emptor', 'When a caviar importer is murdered the day after his wedding to a much-younger woman, the large pool of suspects includes his new wife, his children, and his chief competitor, each of whom has a compelling motive for committing the crime.', 45, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 14), 24, 'C.O.D.', 'Briscoe bids farewell to the 27 as the prosecution of two women for killing each other''s husbands comes to a successful conclusion.', 45, '2004-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 15, 'Season 15', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 1, 'Paradigm', 'An Iraqi immigrant who murders a former military policewoman in retaliation for torturing her brother at Abu Ghraib prison claims that she is covered as an enemy combatant under the terms of the Geneva Convention.', 45, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 2, 'The Dead Wives Club', 'When a woman abandoned by her firefighter husband for his partner''s widow is threatened with also losing custody of her children, she murders her romantic rival, claiming that 9/11 post-traumatic stress syndrome prompted her actions.', 45, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 3, 'The Brotherhood', 'When a prison gang puts out a contract on a Sing Sing corrections officer and his family, assigning the job to a newly released ex-con, the terrified officer pleads preemptive self-defense after he''s brought to trial for the parolee''s murder. As the trial proceeds, the gang attempts to affect the outcome of the case by sending a death threat to the presiding judge, who refuses to be intimidated. Shortly after the conclusion of the trial, McCoy discovers that the defendant''s fears about the power and the reach of the gang were well-placed.', 45, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 4, 'Coming Down Hard', 'McCoy goes after the C.E.O. of a pharmaceutical company who knowingly commissioned further clinical trials on a drug to extend its patent protection yielding millions of dollars of profit without disclosing that previous clinical studies had demonstrated that the drug created a high risk of suicide in its users.', 45, '2004-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 5, 'Gunplay', 'After Green goes undercover to gather evidence on the gun dealers who murdered two detectives during a buy-and-bust, McCoy is able to connect the hit men to the attorney who paid them to avenge the death of his gun-running stepson at the hands of the same detectives during a similar buy-and-bust several years earlier.', 45, '2004-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 6, 'Cut', 'When a plastic surgeon''s greed and narcissism contribute to his failure to care for a patient that ultimately results in her death, Branch insists that McCoy prosecute him for criminally negligent homicide, rather than leave the matter to the civil courts, after an investigation reveals a several instances of the doctor''s inattention to patient care.', 45, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 7, 'Gov Love', 'The investigation into the death of a governor''s wife uncovers a web of infidelity, greed, and corruption which forces McCoy to counter a defense based on a ground-breaking interpretation of spousal privilege.', 45, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 8, 'Cry Wolf', 'The detectives are skeptical when a former street activist turned shock jock with a history of staging phony muggings to gain publicity for his causes appears to be the subject of an attempt on his life after publicly assailing a mobster, but they begin to believe his story after they discover that the married jock was involved with the mobster''s mistress.', 45, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 9, 'All in the Family', 'When the investigation into the contract killing of a jeweler uncovers his plan to roll over on his Russian mob connections to a federal prosecutor, as well as an unhappy wife whom he refused to divorce, McCoy must determine who financed the hit.', 45, '2004-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 10, 'Enemy', 'The prosecution of a drug trafficker responsible for a stash house massacre is hampered when McCoy discovers that the defendant claims diplomatic immunity, and has been working as an undercover operative aiding the U.S. military in Afghanistan.', 45, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 11, 'Fixed', 'When a paroled child murderer is run down, the investigation leads to a terrified social worker and an experimental prison therapy program.', 45, '2004-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 12, 'Mammon', 'The investigation into the murder of a wealthy husband leads to the uncovering of a conspiracy involving infidelity and greed and leads to one defendant attempting to evade justice by killing the other.', 45, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 13, 'Ain''t No Love', 'When a rap producer is found shot to death in his studio, detectives focus on his protege, whose demos link him and a friend to a second murder. As the investigation unfolds, Southerlyn''s opinions put her sharply at odds with both McCoy and Branch.', 45, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 14, 'Fluency', 'Fontana and Green are baffled by a series of flu-related deaths until they discover that the victims were given fake vaccine. McCoy goes after the con man who distributed the vaccine for murder.', 45, '2005-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 15, 'Obsession', 'A conservative talk show host involved in a sexual harassment scandal is murdered, but the trail leads to the victim''s wife and an obsessed stalker.', 45, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 16, 'The Sixth Man', 'McCoy prosecutes a famous basketball star accused of murdering a man who was suing him because of a massive brawl between players and fans.', 45, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 17, 'License to Kill', 'The investigation into a fatal traffic accident leads Fontana and Green to a slaughtered hunting party in the woods and an unknown man who may have been pursuing vigilante justice.', 45, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 18, 'Dining Out', 'When a TV network executive is found murdered, Detectives Fontana and Green suspect a pair of twins who were stealing from the organization until they discover a celebrity chef with whom the married victim shared an affair. The nimble and charming chef is adroit at cultivating relationships with judges and juries alike, but prosecutor McCoy intends to reveal that the suspect''s cooking show was about to be cancelled by his late lover.', 45, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 19, 'Sects', 'Police and prosecutors go after a fanatical cult leader who encourages sex with children among her followers.', 45, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 20, 'Tombstone (I)', 'The bludgeoned corpse of a promiscuous lawyer is found in her office and detectives treat her former lovers as suspects until DNA evidence points to a co-worker.  This crossover continues on Law & Order: Trial By Jury S01E08 Skeleton (II).', 45, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 21, 'Publish and Perish', 'Fontana and his temporary partner, Det. Nick Falco, must tread lightly when they discover links between a powerful police commissioner and the murders of an infamous   porn actress and a maverick publisher.', 45, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 22, 'Sport of Kings', 'The shooting of a Panamanian jockey sends Fontana and Falco into the colorful world of horse racing, and they learn that the animal''s owner used stolen funds for the purchase.', 45, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 23, 'In God We Trust', 'When Fontana and Falco investigate an arson which caused the death of a firefighter, they discover a murder weapon tied to a nine year old murder and a hate crime in which the defendent attempts to have his case dismissed because he became a born again Christian after committing the murder.', 45, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 15), 24, 'Locomotion', 'After a man causes a massive train crash that results in multiple deaths, McCoy tries to prosecute him for murder despite his insanity defense. But McCoy finds himself hampered by a defense attorney whose own agenda may undercut that of his client.', 45, '2005-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 16, 'Season 16', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 1, 'Red Ball', 'A young girl is abducted in broad daylight, and the only link to the girl is an ex-convict who wants a deal before he''s willing to talk.', 45, '2005-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 2, 'Flaw (II)', 'Green and Fontana bring SVU Detective Olivia Benson onto their scene when a DOA has her number on his cell phone.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 3, 'Ghosts', 'Fontana and McCoy pursue a man believed to have murdered a young girl ten years earlier despite numerous obstacles.', 45, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 4, 'Age of Innocence', 'The bombing death of a husband set to remove the feeding tube of his wife, who''s in a persistent vegetative state, focuses the investigation on the protesters.', 45, '2005-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 5, 'Life Line', 'Police turn their attention to the murder of an undercover reporter, but realise that the killer isn''t as guilty as he appears.', 45, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 6, 'Birthright', 'Teenage suspect Traci Sands dies in police custody after being arrested for the murder of the man who reported her to child protective services. Rodgers reveals that she died because someone outfitted her with a benecrine I.U.D. that reacted with Sands'' sickle cell syndrome and ended up killing her. Fontana and Green follow the trail to a charitable clinic and nurse Gloria Rhodes, who believes she is saving the world by sterilizing women that she does not believe are worthy of having children. McCoy faces former assistant district attorney Paul Robinette in court as Robinette defends Rhodes.', 45, '2005-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 7, 'House of Cards', 'The team investigates the killing of a single mother and the abduction of her child.', 45, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 8, 'New York Minute', 'Detectives discover that the owner of a trucking company has been smuggling illegal aliens and suspect that a citizens border-patrol member has killed him.', 45, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 9, 'Criminal Law', 'The deaths of three women with the same name lead Fontana and Green to the nine-year-old conviction of Leland Barnes, who had shot and killed his wife in an office full of people. With two of the three witnesses against him dead and Jack McCoy on the hit list, the detectives struggle to determine how Barnes, who has been in prison the entire time, got someone on the outside to kill the only people who could keep him in jail. The investigation leads them to Leland''s two sons, with surprising results.', 45, '2005-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 10, 'Acid', 'After the daughter of one of Van Buren''s college friends is found dead in her room, a suicide, Van Buren joins Green and Fontana in hunting down the man who burned her face with acid months earlier, ultimately leading to her suicide. Van Buren is unsucces', 45, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 11, 'Bible Story', 'The case of a man who defiled a copy of the Torah turns into a religious battle for McCoy.', 45, '2005-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 12, 'Family Friend', 'After Philip and Valerie Messick are attacked in their home, Green and Fontana follow the trail to a small-time thug named Jay Fleckner. After Valerie''s testimony unintentionally helps free Fleckner, he is found dead, and detectives soon realise that Bob Cerullo, a family friend of Valerie and her late husband, was the triggerman. Unfortunately, when McCoy attempts to prosecute Cerullo, a retired cop, he threatens to claim that he deliberately planted evidence in his past cases in an attempt to get McCoy to drop all the charges.', 45, '2006-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 13, 'Heart of Darkness', 'A journalist''s suicide becomes suspect after Green and Fontana find evidence at the scene suggesting that it wasn''t a suicide after all.', 45, '2006-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 14, 'Magnet', 'Fontana and Green arrest a fellow student after a young man is murdered, but McCoy faces a tough adversary when he tries to prosecute the crime.', 45, '2006-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 15, 'Choice of Evils', 'After the body of a teenage boy is found dead in a warehouse, detectives use DNA to connect the boy to a convicted rapist and serial killer, then to the boy''s mother, Allison Ashburn, the convict''s ex-wife. While trying to solve Danny''s murder, Fontana and Green learn that he recently got his girlfriend Tina pregnant, and his mother had seen him recently when she had given him money despite having claimed she hadn''t seen him for months. Allison finally admits that she murdered her son after the police arrest her new husband John, but claims she did it to save the world from her son, whom she was convinced would become a monster just like her father. Borgia and McCoy face an uphill battle trying to convict the perfect soccer mom.', 45, '2006-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 16, 'Cost of Capital', 'The case against a high powered executive accused of killing her lover rests on the executive''s estranged husband and unstable teenage daughter.', 45, '2006-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 17, 'America, Inc.', 'After Jeffrey Pope, a private military contractor, is found dead, suspicion eventually leads Green and Fontana to Robbie Howell, the younger brother of a man who died because of Pope''s incompetance, and Kevin Boatman, Nick Howell''s former co-worker who had witnessed the tragic events in Iraq.', 45, '2006-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 18, 'Thinking Makes It So', 'Fontana and Green investigate when a bank manager is involved in the robbing of his own bank and learn that his daughter is being held hostage and that he had to go along with the robbery or risk losing his daughter.', 45, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 19, 'Positive', 'When a teenage boy commits suicide after firing on a doctor and hitting an innocent party, Fontana and Green investigate why he was after the doctor to begin with.', 45, '2006-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 20, 'Kingmaker', 'After undercover cop Dana Baker is murdered, Fontana and Green learn that the man who killed her had discovered her identity after seeing a photograph of her.', 45, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 21, 'Hindsight', 'Fontana and Green are called in to investigate when Green''s former replacement, Nick Falco, is suspected of murdering a young woman he had spent the night with.', 45, '2006-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 16), 22, 'Invaders', 'The family of a man who once turned his customers into the police is slain, and the ensuing fracas pits McCoy against a corrupt D.E.A. agent.', 45, '2006-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 17, 'Season 17', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 1, 'Fame', 'Green and Cassady investigate the death of a cop accidentally killed during a botched robbery which leads them to stolen photographs of a celebrity mother married to a player.', 45, '2006-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 2, 'Avatar', 'Green and Cassady investigate after the photograph of a dead woman is found on a popular website, B-Frendz.com. Their investigation leads them to a mentally disturbed young man whom the teenage daughter of the victim claims kidnapped and raped her, but his lawyer offers up an even greater incentive -- the supposed kidnapping victim, Molly Preston.', 45, '2006-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 3, 'Home Sweet', 'When eight-year-old Jenna Wechsler dies as a result of a building explosion, Green and Cassady follow the trail of evidence to Rosalie Schaffner, the owner''s ex-wife. McCoy and Rubirosa pursue Rosalie Schaffner despite a lack of concrete evidence, but the case takes a turn when Rubirosa finds a piece of evidence that points them in a new direction.', 45, '2006-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 4, 'Fear America', 'After Eric Khabaly is seen being murdered on tape in what appears to be an American movement against Islam, Green and Cassady investigate the case which leads them to Khabaly''s cousin, Ben Faoud, who appears to be connected to a terrorist cell functioning inside New York. Unfortunately, the best link to Faoud appears to surround a recent shipment of uranium, which McCoy and Rubirosa are forbidden to mention by the federal government. When news of the uranium leaks out, McCoy and Rubirosa find themselves the victims of intense federal scrutiny, and Paul Robinette''s vigorous defense of young Faoud doesn''t help matters.', 45, '2006-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 5, 'Public Service Homicide', 'When Carl Mullaly is discovered murdered in his apartment, Green and Cassady learn that he had recently been profiled on HardFocus, a tabloid talk show that exposes sex offenders who are caught via the ScumWatch website. With an eight-year-old girl as the only eye witness, detectives arrest the murderer, but McCoy and Rubirosa soon learn that HardFocus is a lot more involved than they claim.', 45, '2006-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 6, 'Profiteer', 'The shooting of a local businessman is linked to a killing in Iraq, and McCoy and Rubirosa refuse to allow the killer to plead out.', 45, '2006-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 7, 'In Vino Veritas', 'A has-been actor wearing blood-stained clothing arrested for drunken driving reveals religious prejudices during his rantings.', 45, '2006-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 8, 'Release', 'After Hudson Moore is found bludgeoned in the back of the Babes Being Bad bus, suspicion initially truns to the company''s creator, Chris Drake, until video footage leads detectives to a young woman who was with Moore the night that he died. After concentrating their investigation on the young woman, the reasons behind Moore''s murder soon become apparent, and McCoy and Rubirosa struggle to prosecute a man who, while not directly responsible for the murder, may have been responsible for the incidents that led up to it.', 45, '2006-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 9, 'Deadlock', 'Green and Cassady hunt a mass murderer Leon Vorgitch, who recently escaped from prison. The finally corner Vorgitch in a school with a room full of hostages, and before surrendering himself to police, Vorgitch shoots a number of innocent children. His unwillingness to accept a deal infuriates McCoy, as it gives him more time to escape prison again. When the father of one of his victims takes justice into his own hands and ends up being used as a campaign slogan for a local politician, McCoy and Rubirosa try to convince Robert Purcell not to let himself be a scapegoat for a political platform.', 45, '2006-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 10, 'Corner Office', 'After corporate attorney Charles Dillon is discovered dead in a hotel room, Green and Cassady investigate and learn that the company he was working for is in the process of being indicted. Their investigation leads them to a high-priced callgirl, Julia Veloso, who turns out to have been romantically involved with the company''s C.E.O., Samantha Weaver. McCoy and Rubirosa find themselves at odds as Rubirosa wonders if McCoy''s prosecution of Weaver has more to do with her gender than her guilt.', 45, '2006-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 11, 'Remains of the Day', 'After Michael Jones dies in his mother''s hospital room with no immediate explanation, his mother Ashley accuses her former husband''s adult children, Miles and Hillary Foster, who are fighting her for control of their father''s substantial fortune. The autopsy rules out the Fosters, and points Green and Cassady in the direction of illegally harvested donor bones, which Jones had received in a transplant eighteen months prior. McCoy and Rubirosa struggle to prosecute the case after it becomes clear the only way they will get the evidence they need is to test another young man who received bone grafts from the same woman who had given Michael Jones his legs.', 45, '2007-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 12, 'Charity Case', 'Green and Cassady investigate after Sean Archer, a producer who had recently adopted a child from Africa with his wife, well-known actress Sofia, is gunned down outside an ice cream shop while holding baby Christopher. The shooting is soon linked to the recent adoption of Christopher, which had received international scrutiny because it appeared to have been pushed through based on the couple''s celebrity status. McCoy and Rubirosa initially investigate the murder of Sean Archer, which soon turns into an investigation of a child''s death when the identity of baby Christopher comes under question.', 45, '2007-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 13, 'Talking Points', 'The shooting of university student Jason Miles at a political rally hosted by controversial speaker Judith Barlow leaves any number of suspects, but after Green and Cassady prove that two of the people they''ve questioned are lying about their alibis, they turn their attention to Malcom Yates, a grad student who claimed to be with Jason''s girlfriend at the time of his death. McCoy and Rubirosa realise that Yates went after Barlow because of her open criticism of stem-cell research, something that Yates had high hopes could help find a cure for his own Parkinsons.', 45, '2007-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 14, 'Church', 'A reverend confesses to the murder of a young gay actor, but McCoy and Rubirosa soon learn that he may not be the guilty party.', 45, '2007-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 15, 'Melting Pot', 'After an actress is found dead in her apartment, Green and Cassady attempt to prove that her death was not a suicide.', 45, '2007-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 16, 'Murder Book', 'After publisher Serena Darby is found murdered in her apartment, suspicion turns to J.P. Lange, a former professional baseball player acquitted of his wife''s murder who had written a book hypothesising how he would have committed the murder. Green and Cassady follow the trail of evidence from Lange to Gerald Stockwell, a former ghostwriter on the book, but Stockwell tries to clear himself by offering McCoy and Rubirosa proof that one of the jurors in Lange''s trial was paid off to force an acquittal.', 45, '2007-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 17, 'Good Faith', 'Green and Cassady investigate an arson turned homicide when a body found in a burned church turns out to have been murdered before the fire started.', 45, '2007-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 18, 'Bling', 'Green and Cassady investigate the murder of a female rapper.', 45, '2007-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 19, 'Fallout', 'Green and Cassady get mixed up with the Russian consulate after Peter Rostov dies of ricin poisoning. Their investigation leads them first to his work, where they learn he spent a great deal of time traveling back and forth between Russia, and secondly to his brother, Karl. It isn''t long before they link the Rostov brothers to an illegal prostitution ring trafficking in young Russian woman, but McCoy is faced with trying to get the remaining Rostov brother to testify so he can prosecute Brezin, the father of one of the trafficked girls.', 45, '2007-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 20, 'Captive', 'Green and Cassady follow the leads when a young boy is found murdered to a suspected serial pedophile/murderer.', 45, '2007-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 21, 'Over Here', 'The detectives link the deaths of two homeless men to the war in Iraq.', 45, '2007-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 17), 22, 'The Family Hour', 'When Nicole Bailey, the ex-wife of a respected former senator, is found murdered and brutalised in her home, Green and Cassady look first at the senator, but follow the trail of clues to a dysfunctional family with a number of potentially embarrassing secrets. McCoy finds himself in the hot seat when he is forced to argue the case in front of a judge more interested in public relations than justice.', 45, '2007-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')), 18, 'Season 18', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 18), 1, 'Called Home', 'Cyrus Lupo returns to New York after four years abroad to deal with his own terror. Lupo and Green investigate two suicides committed the same way. The detectives are suspicious of a parolee known as "Dr. Death".', 45, '2008-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 18), 2, 'Darkness', 'Lupo and Green''s first offical case together is a kidnapping that happened during a citywide blackout; a housekeeper is slain and a mother and daughter are kidnapped. The evidence that links all the kidnappers is the father and husband of the kidnap victims. When they search the kidnappers'' hideout, they find preparations which implies that the kidnappers knew that the blackout was coming. Cutter must convince the man to testify after he has lied about a search warrant to save the man''s daughter, or else the kidnappers will all go free. Issues of a warrantless search arise. Courtroom scenes revolve around questions of Enron-like manipulation of energy.', 45, '2008-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 18), 3, 'Misbegotten', 'The explosion of a package including scientific research injures a pregnant security guard, leading to the investigation of the scientist''s experiments.', 45, '2008-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 18), 4, 'Bottomless', 'The investigation into a pair of missing pants leads to the murder of a young lawyer. Lupo and Green soon turn their suspicions to a businessman who works for a shady multinational corporation called SavingsMart.', 45, '2008-01-16');
