INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 12, 'Never Say Goodbye', 'After investigating a flight attendant''s murder, Walker''s methods are scrutinized during the trial. Meanwhile, Price and Maroun try to reveal the defendant''s state of mind.', 42, '2026-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 13, 'New Normal', 'Walker revisits his undercover identity to get details on a gang-related murder. Saddled with a weak case, Baxter and Price weigh the consequences of ruining another department''s investigation to get their conviction.', 42, '2026-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 14, 'Remedies', 'The 2-7 arrests an unlikely suspect when a popular wellness personality is murdered. Price and Maroun must determine if revealing the victim''s past will help or hurt their case.', 42, '2026-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 15, 'Bright Lights', 'A fashion designer is murdered with a stolen gun. With only circumstantial evidence supporting the case, Price and Maroun must expose a witness'' private life to get a conviction.', 42, '2026-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 16, 'Fate''s Cruel Joke', 'After a woman''s body is discovered in a suitcase, Price and Maroun disagree over the charges to bring against the prime suspect. Riley faces scrutiny when he''s involved in an on-duty car accident.', 42, '2026-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 17, 'Beyond Measure', 'Riley and Walker investigate the murder of a beloved museum security guard and the theft of a priceless artifact. Baxter and Price must balance their pursuit of justice with public pressure to return the artifact.', 41, '2026-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 18, 'Ride or Die', 'A talented local news reporter is brutally murdered. Maroun''s mentor takes the case for the defense, pitting Maroun against the woman who shaped her career.', 43, '2026-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 19, 'Accidentally Like a Martyr', 'A woman from a famous family is found dead on her birthday; Price and Maroun have an uphill battle in court when the defense presents two viable suspects in the crime.', 0, '2026-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0098844')) AND numero_temporada = 25), 20, 'Episode 20', NULL, 0, '2026-05-07');
