INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')), 1, 'Season 1', 'Tim “The Tool Man” Taylor hosts a DIY show while navigating mishaps at home, often causing more chaos than fixes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 1, 'Pilot', 'Tim decides to rewire the dishwasher against Jill''s wishes and ends up blowing more than her fuse.', 24, '1991-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 2, 'Mow Better Blues', 'After breaking one of Tim''s tools that has been in the family for twenty years, Mark fears that he will be traded in after Brad and Randy make up a story about ""Peter"", their former brother that was traded in after he broke one of Tim''s flashlights.', 24, '1991-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 3, 'Off Sides', 'When she can''t find a babysitter, Jill has a magician watch the kids while she and Tim go on their romantic dinner. However, Tim is too distracted by a football game to pay attention to her. Meanwhile, the kids accidentally lock the magician in a trunk.', 24, '1991-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 4, 'Satellite on a Hot Tim''s Roof', 'Tim becomes green with envy while putting up a new satellite dish on the roof when Jill''s teacher visits.', 24, '1991-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 5, 'Wild Kingdom', 'While working in the basement, Tim hears some strange noises.  Is it a mouse or is it a creepy crawly snake?', 24, '1991-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 6, 'Adventures in Fine Dining', 'Tim bets Jill that he can teach the boys some table manners.', 24, '1991-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 7, 'Nothing More Than Feelings', 'After Jill drove while her oil light was on, Tim shares this with the Tool Time audience and the other guys say their wives don''t respect their tools.', 24, '1991-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 8, 'Flying Sauces', 'Tim cooks up a plan for Mark to get even with his brothers, and offers "Tool Time" viewers nutrition tips.', 24, '1991-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 9, 'Bubble, Bubble, Toil and Trouble', 'Tim decides to put in another sink in the bathroom so his shaving junk won''t be in Jill''s way, but the project takes longer than he expects.', 24, '1991-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 10, 'Reach Out and Teach Someone', 'Tim decides to do a Tool Time special for women to teach plumbing.  After being called an idiot by Randy, Brad worries that he will do bad on a test. Tim starts his hotrod.', 24, '1991-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 11, 'Look Who''s Not Talking', 'Jill gets stage fright when she has to deliver a speech in front of women at the Library Association. Tim and Mark dress up as women to help her get over her fear.', 24, '1991-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 12, 'Yule Better Watch Out', 'Tim competes in the neighborhood Christmas light competition.  Mark writes his Christmas list to Santa, but Brad and Randy tell him Santa is dead.', 24, '1991-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 13, 'Up Your Alley', 'Tim and Jill have a bowling match against eachother and try no to make it competitive, until the K&B Construction guys show up.  The boys get in trouble at an arcade.', 24, '1992-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 14, 'For Whom the Belch Tolls', 'Jill doesn''t want Stu Cutler, Tim''s old college friend, in the house.  So Tim tries to keep him away but when he gives in and Stu comes to the house, he insults Tim and Jill and belches with the boys.', 24, '1992-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 15, 'Forever Jung', 'Karen visits and Tim must stand up to her.  Jennifer invites Brad to her parents'' anniversary, so Jill teaches him how to dance.', 24, '1992-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 16, 'Jill''s Birthday', 'Tim gets Jill a lifetime membership to a health care club, until she says she will never exercise again.  Brad and Randy spend all of their money on a baseball card, so they make Mark give them a "brother tax" to get Jill a present.', 24, '1992-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 1), 17, 'What About Bob?', 'Tim cheats to beat Tool Time guest Bob Vila at a trivia game.  Randy pulls a prank on Curtis, a geek at school.', 24, '1992-02-11');
