INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 3), 1, 'Maybe, Baby', 'Jill''s sister Carol is having a baby girl. When they talk about the baby''s name and Jill is going through the boys'' baby toys, she wishes she could have a baby girl. Tim tells Randy and Brad that Jill always wanted a girl so they tell Mark that Jill wished he had been a girl. This upsets Mark and when Jill wants to bake a cake with him, he doesn''t want to. When she finds out the truth, she tells Mark that what Randy and Brad told him isn''t true. Tim is also upset because he doesn''t want another child. But he feels alright again when Jill tells him that they don''t have the time for another child.', 24, '1993-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 3), 2, 'Aisle See You In My Dreams', 'At Al''s 35th birthday, he wants a wife and kids, so Jill fixes him up with Ilene Markham.  Al finds out that Ilene wants kids too, so he proposes to her on Tool Time.  Randy and Brad write a letter to Mark pretending to be Isaiah Thomas, so Tim and Jill tell Mark to get revenge.', 24, '1993-09-22');
