INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 3), 4, 'A Sew, Sew Evening', 'Tim has trouble with Joe Morton, his new neighbor, after Joe dents part of his hot rod.  Jill becomes good friends with Marie Morton, Joe''s wife.  Brad signs up for home ec. as his elective to meet girls, but when the other boys in school find out about his plan, it doesn''t work out the way he planned.', 24, '1993-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 3), 5, 'Arrivederci, Binford', 'Tim is afraid to cry after Mr. Binford, his boss and close friend, passes away.', 24, '1993-10-13');
