INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 7, 'Jill''s Passion', 'Ian, a man Jill met at the YMCA gym, asks her out, mistaking Tim for her brother.  That night Jill has a dream about him.  But after talking to Patty, a friend, and Tim she straightens it out.', 22, '1997-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 8, 'Losing My Religion', 'Randy questions his religion.  Tim breaks a valuable piece of church equipment.', 22, '1997-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 9, 'Thanksgiving', 'The Taylors go to a football game in a box seat for Thanksgiving.  But Tim manages to black out all the lights.', 22, '1997-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 10, 'The Dating Game', 'Tim takes Al to a club to meet women after they find out Ilene is engaged.', 22, '1997-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 11, 'Bright Christmas', 'Tim does te ultimate Christmas decorating display job.  Jill is worried when she finds out her mother is dating.', 22, '1997-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 12, 'The Old College Try', 'Tim realizes his friends are boring, so he starts hanging out with students half his age.', 22, '1998-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 13, 'An Older Woman', 'Brad''s getting MARRIED... well, maybe not after Tim and Jill get through with him. The Taylor parents try to make Brad realize that he''s not ready for the commitment of marriage to a college girl he just recently met at a party.', 22, '1998-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 14, 'Tim ''The Landlord'' Taylor', 'Al rents a house from Tim and Tim takes advantage of him as his landlord.  Meanwhile, Randy and Brad buy the same shirt.', 22, '1998-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 15, 'Say Goodnight, Gracie', 'Tim begins to want to have more children after Marty asks him to babysit one of the twins. After some discussions about his vasectomy with Jill, and some words of wisdom from Wilson, he decides that being able to return the twins after playing with them is the best idea. Mark is still wearing black, but with an added touch (of lipstick) for this episode.', 22, '1998-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 16, 'What a Drag', 'On Tool Time, Tim and Al show viewers how to prepare for a severe winter storm. When Tim falls through the gazebo he discovers a small bag of marijuana taped to the underside of the swing. Jill and Tim stake out their backyard from Wilson''s to catch the culprit... to everyone''s surprise, Brad is caught red-handed with the goods.', 22, '1998-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 17, 'Taking Jill for Granite', 'The Taylors do a kitchen remodel, but a surprise is in store when Tim and Jill find out who the installer is.', 22, '1998-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 18, 'Futile Attraction', 'Tim becomes suspicious that Heidi and Al are having a hot affair when he finds out she has separated from her husband; he sets out to find out exactly how much of an affair they are having. On Tool Time, Tim adds a little MORE POWER to his golf swing when golf-pro Payne Stewart guests.', 22, '1998-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 19, 'Desperately Seeking Willow', 'While staying over at the Taylors, Willow doesn''t return home from a club one night... Jill fears the worst and sends the whole family out searching for her. It''s Saint Patrick''s day on Tool Time, and who better to celebrate with than the boys from K&B Construction.', 22, '1998-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 20, 'The Write Stuff', 'On Tool Time, Tim manages to throw himself out a window while doing renovation work. Jill tries to get Tim to help prepare for a tax audit. Brad and Randy become rivals when Brad''s article ""Hey Yo!"" takes the spotlight away from Randy''s ""Genetic Mutations in the Second Half of the 20th Century.""', 22, '1998-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 21, 'The Son Also Mooches', 'It''s Jill''s turn to worry about needing glasses as she reaches middle age. Tim worries that his mother is going to lose money on another of his brother Jeff''s business schemes.', 22, '1998-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 22, 'Believe It or Not', 'On Tool Time, ""Men''s Convenience Week"" features a visit by Grant Hill of the Detroit Pistons. Wilson becomes upset with Tim after Tim tells everyone about Wilson''s encounter with an alien, something Wilson would rather Tim had kept to himself.', 22, '1998-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 23, 'Rebel Without Night Driving Privileges', 'Randy''s driving, get off the sidewalk! ... Randy doesn''t feel that he''s being treated fairly when his driving privileges differ from those Brad had when he first got his license. On Tool Time, ""Judy''s Rat"" pulls cable through hard to reach spaces.', 22, '1998-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 24, 'Tool-Thousand-One: A Space Odyssey', 'Tool Time is revisited by Astronauts Ken Bowersox and Steve Hawley, who announce that a Binford tool will be used on their next shuttle mission. Will Tim or Al win the competition to be the one to use the tool in space? Back on Earth, Mark tries to impress a girl by making a dramatic change to his appearance.', 22, '1998-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 7), 25, 'From Top to Bottom', 'Jill makes some embarassing remarks about Tim on a talk show, while he watches it from Harry''s Hardware, with all his friends.', 22, '1998-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')), 8, 'Season 8', 'In the final season, Tim must choose between fame and family as “Tool Time” reaches new heights and home becomes more important than ever.');
