INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 4, 'Taylor Got Game', 'While Brad studies for his SAT''s, a friend of Wilson''s offers him the chance to play professional international soccer in Europe.', 22, '1998-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 5, 'Al''s Fair Lady', 'Jill is concerned when Al''s new rich girlfriend keeps buying him extravagant gifts in order to keep him in the relationship.', 22, '1998-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 6, 'Bewitched', 'At a Halloween party Tim encourages Wilson to break up with his girlfriend. who claims to be a witch. But, after he dumps her he mysteriously disappears. Tim blames the witch but when the police arrive Tim is accused of Wilson''s disappearance.', 22, '1998-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 7, 'Not-So-Great Scott', 'When Tim overhears Jill saying that one of her patients is having an affair with Heidi''s husband, Tim has trouble keeping it from Heidi.', 22, '1998-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 8, 'Tim''s First Car', 'When Tim''s first car is destroyed before his eyes in a junkyard, Jill decides to find him a replica of it. Meanwhile, Mark helps Brad make a video for his college applications.', 22, '1998-11-10');
