INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 10, 'Thanks, But No Thanks', 'Tim invites his brother Marty and his twins to live with him when he discovers that Marty and his wife Nancy are separated.', 22, '1998-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 11, 'Home For The Holidays', 'Randy returns from Costa Rica for Christmas only to discover the changes that have taken place in his absence and that life has gone on without him.', 22, '1998-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 12, 'Ploys For Tots', 'Tim and Jill try to teach Marty the best way to parent when one of the twins keeps throwing tantrums to get her own way.', 22, '1998-12-15');
