INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 14, 'Home Alone', 'Tim gets preoccupied when he is left alone to write his book.', 22, '1999-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 15, 'Knee Deep', 'Brad blames Tim for possibly ruining his soccer career when he injures his knee on a piece of hardware during a Tool Time shoot at the house. The magicians Penn & Teller appear on Tool Time.', 22, '1999-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 16, 'Mark''s Big Break', 'Tim commissions Mark to make a video to celebrate the completion of his hot rod. When Tim is disappointed with the result, Mark films a new version - with a dance number set to "Greased Lightning."', 22, '1999-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 17, 'Young At Heart', 'Jill is angry when Tim spends too much time with his new female mechanic near their anniversary.', 22, '1999-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 18, 'Love''s Labor Lost (1)', 'Plans for a ski trip are put on hold when Jill needs an emergency hysterectomy. Tim helps her face the situation, but becomes frightened when complications arise during surgery.', 22, '1999-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 19, 'Love''s Labor Lost (2)', 'Tim waits for news on Jill''s surgery. Jill will be fine, although she had to have her ovaries completely removed, not partially as was first thought. Jill''s mother comes to visit to help with her daughter''s care and with her mood swings.', 22, '1999-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 20, 'Neighbors', 'Tim and Wilson''s friendship is tested when Wilson wins $10,000 and decides to build an elaborate science lab in his backyard - which blocks the Taylor family''s view.', 22, '1999-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 21, 'A Hardware Habit To Break', 'Harry announces that he is retiring and selling the hardware store. Tim organizes a fundraising party for the store, but ends up buying it himself. But when the customers dry up, Tim begins to wonder what he is doing wrong.', 22, '1999-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 22, 'Loose Lips And Freudian Slips', 'Jill''s thesis is before the committee. During Mark''s student film viewing, Jill''s psychology professor sees Jill criticize him and Jill is worried that this will affect the thesis committee''s decision.', 22, '1999-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 23, 'Trouble-A-Bruin', 'Troubles brew on Tool Time when Bud mandates that no non-Binford products are to be used on the show. Brad has to decide whether or not to play soccer earlier than he is scheduled to when he has an opportunity to play in front of a UCLA scout.', 22, '1999-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0101120')) AND numero_temporada = 8), 24, 'Dead Weight', 'Tool Time continues to be a "jewel" despite the continued excess presence of the Binford name. Things rapidly turn sad when Al decides to take his mother out to dinner to tell her he''s going to get married... and she has a heart attack and dies.', 22, '1999-05-18');
