INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')) AND numero_temporada = 1), 1, 'The Cat and the Claw (1)', 'Catwoman steals a necklace to finance the purchase of land for a mountain lion reserve, but is stopped by a group of terrorists.', 22, '1992-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')) AND numero_temporada = 1), 2, 'On Leather Wings', 'When a vicious bat creature known as Man-Bat, starts terrorizing Gotham City, everyone mistakenly thinks that Batman is the culprit. Batman must find out who the mysterious Man-Bat is and clear his own name.', 22, '1992-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')) AND numero_temporada = 1), 3, 'Heart of Ice', 'Brilliant cryogenics expert Dr. Victor Fries is transformed into Mr. Freeze, a vengeful creature who can only survive in subzero temperatures.', 22, '1992-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')) AND numero_temporada = 1), 4, 'Feat of Clay (1)', 'A popular actor renowned for his ability to play any part has a terrible secret—he''s addicted to a strange chemical formula that enables him to alter his facial features without makeup.', 22, '1992-09-08');
