INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')) AND numero_temporada = 1), 58, 'The Demon''s Quest (2)', 'Batman discovers Ra''s Al Ghul''s plan to flood the Earth with chemicals and return it to a lush, green planet, destroying all existing life in the process.', 22, '1993-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')) AND numero_temporada = 1), 59, 'Read My Lips', 'Batman investigates a series of baffling crimes and discovers that the crime czar is a wooden dummy, manipulated by a mild-mannered man called the Ventriloquist.', 22, '1993-05-10');
