INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103359')), 2, 'Season 2', 'The second season of Batman: TAS was titled The Adventures of Batman & Robin and initially aired in May 1994 to September 1995.');
