INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 1, 'Night of the Sentinels (1)', 'A young teenager has been rejecting her mutant powers ever since she discovered them. But when giant robots track her down, it''s up to the X-Men to save her.', 21, '1992-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 2, 'Night of the Sentinels (2)', 'Breaking into the Mutant Control Agency''s headquarters to destroy the registration files on mutants, the X-Men lose two of their members against the Sentinels, but eventually gain another.', 21, '1992-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 3, 'Enter Magneto', 'As the Beast faces an arraignment in court before a mutant-hating public, the X-Men unwillingly take in an old enemy of Wolverine''s. Magneto, an old friend turned enemy of Professor Xavier''s, attacks a military base in an attempt to unite mutants against humanity.', 21, '1992-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 4, 'Deadly Reunions', 'Magneto & Professor Xavier come face to face for the first time in years amid an exploding factory, while Sabretooth & Wolverine face off in the mansion.', 21, '1993-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 5, 'Captive Hearts', 'Wolverine must overcome his feelings for Jean, and Storm must overcome her crippling claustrophobia, when the team journeys into the sewer to rescue Jean Grey & Cyclops from a race of hideously deformed mutants known as Morlocks, and their leader Callisto, who wants to make Scott her king.', 21, '1993-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 6, 'Cold Vengeance', 'Having left the X-Men to seek peace in the arctic, Wolverine instead finds himself battling Sabretooth for the safety of an Inuit tribe. Storm, Gambit, and Jubilee investigate an island resort which welcomes mutants, and might be too good to be true.', 21, '1993-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 7, 'Slave Island', 'Gambit, Storm, and Jubilee become slave labor on the island resort of Genosha, along with other mutants, forced to help build the new power source for a Sentinel factory. They''re given aide in escaping by a mysterious mercenary named Cable.', 21, '1993-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 8, 'The Unstoppable Juggernaut', 'The X-Men return from Genosha, finding the home destroyed, and Professor Xavier missing. They suspect a super-strong Russian mutant named Colossus, but the real culprit turns out to be someone more human, far tougher, and with deeper ties to the Professor.', 21, '1993-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 9, 'The Cure', 'Rogue seeks a scientist who claims to be able to "cure" any mutant of their powers, unaware that neither he, nor his process, are what they appear to be.', 21, '1993-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 10, 'Come the Apocalypse', 'An ancient and immensely powerful mutant, known as Apocalypse, creates four Horsemen to help usher in a new world where survival of the fittest reigns.', 21, '1993-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 11, 'Days of Future Past (1)', 'A mutant from more than half a century into the future, named Bishop, arrives in the present, attempting to change history for the better, by stopping an X-Man from committing an assassination. But between being chased by a future breed of Sentinel, and the details of his mission being fuzzy, he''s got his work cut out for him.', 21, '1993-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 12, 'Days of Future Past (2)', 'Aware of an impending assassination which will create a catastrophic future, the X-Men must deal with threats both outside and within their team.', 21, '1993-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 1), 13, 'The Final Decision', 'Prominent anti-mutant and presidential hopeful Senator Kelly is caught in a tug-of-war between Magneto''s goal of mutant superiority, the X-Men''s dream of peaceful co-existance between mutants and humans, and the mutant-hunting Sentinel robots'' goals of global domination.', 21, '1993-03-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 1, 'Till Death Do Us Part (1)', 'The X-Men are divided and conquered, by none other than a friend they had thought dead.', 21, '1993-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 2, 'Till Death Do Us Part (2)', 'As Morph''s seeking of revenge on the X-Men begins to run into some snags, Cyclops & Jean Grey get their Honeymoon cut short by the machinations of Mister Sinister and the Nasty Boys.', 21, '1993-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 3, 'Whatever It Takes', 'Storm returns to her village in Africa, and must choose between her life and that of her godson when a powerful evil overtakes him. Meanwhile, Wolverine tracks down Morph in the Amazon, and Professor Xavier & Magneto find their situation going from bad to worse as they end up in a hidden land.', 21, '1993-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 4, 'Red Dawn', 'Jubilee joins Colossus as he returns to his homeland of Russia, and helps him face an unbeatable menace from the Cold War, who wishes to restore the former Soviet Union, and has a history with Wolverine.', 21, '1993-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 5, 'Repo Man', 'Wolverine is led back to his homeland of Canada, and is attacked by his former teammates from the supergroup Alpha Flight. The government wants the secrets of his adamantium skeleton back, and are willing to take him apart to get it.', 21, '1993-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 6, 'X-Ternally Yours', 'Gambit must come face to face with the past he''s been running from for years, as he returns to Louisiana to save his brother from the woman he left at the altar.', 21, '1993-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 7, 'Time Fugitives (1)', 'Bishop returns from the future to again attempt to fix his world, this time trying to stop a plague from infecting mutants. But his noble actions lead to a far greater tragedy.', 21, '1993-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 8, 'Time Fugitives (2)', 'To stablize his own timeline, Cable comes to the present to prevent Bishop from saving mutant-kind from Apocalypse''s plague.', 21, '1993-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 9, 'A Rogue''s Tale', 'Haunted by visions of a strange woman, Rogue must come to grips with the dark secrets of her past prior to joining the X-Men.', 21, '1994-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 10, 'Beauty & the Beast', 'Beast falls in love with his patient, a blind woman named Carly, and though the feelings are mutual, her mutant-hating father and anti-mutant sentiment drive a split between the pair. Meanwhile, Wolverine seeks to take down the Friends of Humanity from the inside out.', 21, '1994-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 11, 'Mojovision', 'An alien being named Mojo abducts the X-Men to use as forced action stars of television programming.', 21, '1994-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 12, 'Reunion (1)', 'Professor Xavier and Magneto gain a native ally, as they finally come face to face with the new ruler of the Savage Land. A lead from Morph sets up a rematch between Wolverine, Cyclops, Jean Grey and Mister Sinister & his Nasty Boys.', 21, '1994-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 2), 13, 'Reunion (2)', 'The X-Men find themselves powerless in the Savage Land, and become fodder for Mr. Sinister''s experiments. It''s up to Wolverine and Ka-Zar to initiate a rescue.', 21, '1994-02-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 1, 'Out of the Past (1)', 'A group of cyborg mercenaries, led by a woman from Wolverine''s past, seek his forced help in unlocking the secrets of a long buried alien spacecraft.', 21, '1994-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 2, 'Out of the Past (2)', 'An alien being called the Spirit Drinker drains the life-force of Jubilee and the Reavers, making strained allies of Wolverine and Lady Deathstrike.', 21, '1994-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 3, 'The Phoenix Saga: Sacrifice (1)', 'Following visions from recent dreams, Professor Xavier sends his X-Men on a mission to the Eagle One Space-Station, putting them in the middle of an interstellar conflict.', 21, '1994-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 4, 'The Phoenix Saga: The Dark Shroud (2)', 'The X-Men barely survive their return trip from space, Jean Grey discovering herself changed by the experience. Professor Xavier''s dark half is given form, and proceeds to attack his students.', 22, '1994-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 5, 'The Phoenix Saga: Cry of the Banshee (3)', 'Professor Xavier''s claims of the capture of his alien soulmate Lilandra by Juggernaut and Black Tom Cassidy are met with skepticism.', 21, '1994-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 6, 'The Phoenix Saga: The Starjammers (4)', 'Lilandra seeks to protect the M''Kraan Crystal from her wicked brother, the Emperor D''Ken. But the interstellar pirates known as the Starjammers capture it, and Cyclops, in an effort to enact their own revenge scheme on the emperor.', 21, '1994-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 7, 'The Phoenix Saga: Child of Light (5)', 'Shi''ar Emperor D''Ken''s rise to power via the M''Kraan Crystal is causing a universal implosion. The X-Men, Imperial Guard, and Starjammers find themselves overpowered and unable to stop it. Jean Grey must unleash her destiny as the host of the Phoenix, even at a most personal cost.', 21, '1994-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 8, 'Savage Land, Strange Heart (1)', 'Mutant-draining, pterodactyl-man Sauron is persuaded into capturing Storm by Zaladane, the high priestess of Savage Land Sun God Garokk, unaware of her ulterior motives for unleashing the mutant''s full potential.', 21, '1994-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 9, 'Savage Land, Strange Heart (2)', 'Storm''s unfettered weather-fury continues setting the stage for the rise of Garokk. Even if Storm can be brought back under control, the Sun God''s geothermal rejuvenation will spell an end to the Antarctic paradise known as the Savage Land.', 21, '1994-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 10, 'Obsession', 'Fueled on by his desire to seek vengeance against the immortal mutant that changed him into a weapon of evil, Archangel persaudes Rogue into helping him hunt down and destroy Apocalypse.', 21, '1994-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 11, 'The Dark Phoenix: Dazzled (1)', 'The flirtation between Cyclops and a mutant singer named Dazzler exacerbates the Phoenix-controlled side of Jean Grey, leaving her open for manipulation by a secret sect of mutants coveting her immense powers for their own evil designs.', 21, '1994-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 12, 'The Dark Phoenix: The Inner Circle (2)', 'The Circle Club makes the Phoenix-controlled Jean Grey their new Queen, but finds two factors opposing it: her mental bond with Cyclops, and the presumed-dead Wolverine stalking after them.', 21, '1994-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 13, 'The Dark Phoenix: The Dark Phoenix (3)', 'As the Dark Phoenix grows increasingly hostile, even destroying an entire star system, the X-Men struggle to figure out a way to stop her without harming their teammate Jean Grey.', 20, '1994-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 14, 'The Dark Phoenix: The Fate of the Phoenix (4)', 'The X-Men face the Shi''ar Imperial Guard in a trial by combat to spare the life of Jean Grey, though even they begin to question the safety of the universe as long as the Dark Phoenix remains alive inside her.', 21, '1994-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 15, 'Cold Comfort', 'A founding member of the X-Men, named Iceman, breaks into a government facility. He refuses to trust his former teammates about his reasons for doing so, but when Jubilee aids him in his quest, it leads to the team going up against another group of mutants, known as X-Factor.', 21, '1995-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 16, 'Orphan''s End', 'Cyclops discovers that Corsair, the leader of the interstellar band of pirates known as the Starjammers, is his father. He''s a fugitive on the run from the Shi''ar empire, and seeks his help in proving his innocence. But can the man who abandoned him as a child truly be trusted?', 20, '1995-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 17, 'The Juggernaut Returns', 'Professor Xavier''s step-brother, and sworn enemy, the Juggernaut loses his powers to a bumbling archeologist. He must overcome the pain of their childhood together, and have the powers restored to him to save his life.', 21, '1995-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 18, 'Nightcrawler', 'Gambit, Rogue, and Wolverine take a ski trip in Germany. While Gambit and Rogue seem to be enjoying themselves, Wolverine is restless, and longs for some action. When he hears reports of a demon hiding in a local monastery, his investigation reveals not a demon, but a mutant, Nightcrawler, whose devilish appearance is in stark contrast to his peaceful and deeply philosophical nature.', 21, '1995-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 3), 19, 'Weapon X, Lies, and Video Tape', 'A cryptic postcard unleashes a flood of maddening and painful memories in Wolverine that threaten to drive him insane. To keep his mind from being torn apart, Wolverine and Beast travel to the one location that may hold the answers to his hidden past: the ruins of the top-secret Weapon X lab where Wolverine''s bones were laced with adamantium. There he encounters other former ''test subjects''—Sabretooth, Maverick and Silver Fox—who are suffering similar mental breakdowns.', 21, '1995-06-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 1, 'One Man''s Worth (1)', 'Bishop & Shard recruit Wolverine & Storm for a time travel mission to save Professor Xavier''s life. Except they''re from the parallel timeline where he died before founding the X-Men, a world where humans and mutants are in a constant war with one another. Not only do they pair lack a connection to him, but correcting history may put an end to their marriage.', 21, '1995-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 2, 'One Man''s Worth (2)', 'Bishop, Shard, and the alternate-present versions of Wolverine & Storm, will have one more chance to save Xavier from being killed before he founded the X-Men... if they can survive the alternate-future ruled entirely unopposed by Mastermold.', 21, '1995-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 3, 'Courage', 'Morph feels he''s finally ready to return to the X-Men. But his homecoming is interrupted by the return of the Sentinels, the robotic mutant-hunters who nearly killed him the last time he faced them. Will history repeat itself?', 21, '1995-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 4, 'Proteus (1)', 'The long hidden secret patient of Muir Island, a reality-warping mutant teen known as Proteus, escapes from his 15 year long captivity, and wreaks havoc across Scotland searching out his father.', 21, '1995-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 5, 'Proteus (2)', 'Tracking down his father, who is now a candidate for Secretary of State, Proteus continues threatening lives with his uncontrolable powers. It''s up to Professor X alone to try to stop the boy who brought even Wolverine to his knees.', 21, '1995-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 6, 'Sanctuary (1)', 'Magneto builds a home strictly for mutants on the orbiting base known as Asteroid M. The message goes out worldwide of initial exodus, and he finds just as many eager to join him, as those anxious to destroy him.', 21, '1995-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 7, 'Sanctuary (2)', 'With Magneto seemingly dead, Fabian Cortez takes over Asteroid M, and initiates a nuclear war with Earth. The X-Men attempt to sabotage his warhead stockpile, and rescue Gambit, finding assistance in the most unlikely of places.', 20, '1995-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 8, 'Beyond Good and Evil (1)', 'Apocalypse steals Cable''s computer in the year 3999, allowing him to time travel to the past, where he schemes to bring an end to his struggle against inferior mutants once and for all. This leads to Bishop becoming trapped amid the timestream, and brings', 21, '1995-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 9, 'Beyond Good and Evil (2)', 'When Oracle, the psychic member of the Imperial Guard is kidnapped by Apocalypse, Professor Xavier deduces his scheme involves capturing mutants with telepathic abilities. The X-Men are split up to track them down before the villains can, which puts Wolverine & Shard in the middle of a scuffle between Archangel and a ninja named Psylocke.', 21, '1995-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 10, 'Beyond Good and Evil (3)', 'After swiping the government''s own time machine, Cable ends up recruiting the X-Men on his mission to destroy Apocalypse''s source of immortality at its creation.', 21, '1995-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 11, 'Beyond Good and Evil (4)', 'Two of Apocalypse''s former evil allies, the captive Wolverine, the loose cannon Cable, and the exiled Bishop, come together to free the kidnapped psychics and save reality from being rewritten.', 21, '1995-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 12, 'Have Yourself a Morlock Little X-Mas', 'Jubilee''s first Christmas with the X-Men doesn''t go exactly as she expected, when she, Storm, and Wolverine become involved with a mission to save the Morlock child known as Leech.', 20, '1995-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 13, 'The Lotus and the Steel', 'Finding himself continually losing control, Wolverine takes a sabbatical to Japan, in an effort to find inner peace in temple-building. Instead, he faces a village under siege by a group of bandits, and struggles to help them without compromising his search for his true nature.', 20, '1996-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 14, 'Love in Vain', 'In a New Mexico desert, Wolverine witnesses the crash of a spaceship carrying horrific, alien bug-like creatures—the Family—which overwhelm him. Rogue reunites with her first boyfriend, Cody, who ends up being a part of the Family''s plot to have Rogue become their new leader.', 20, '1996-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 15, 'Secrets, Not Long Buried', 'Cyclops heads solo to the desert town of Skull Mesa, where humans and mutants live in harmony, to visit an old mentor from his youth. But he not only finds himself powerless when he arrives, but discovers the place under the rule of a maniacal mutant, with none of the citizens willing to take a stand.', 20, '1996-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 16, 'Xavier Remembers', 'Trapped on the astral plane after suffering a concussion, Professor Xavier is at the mercy of the Shadow King, and in desperate need of help from his X-Men, who are unable to hear him.', 20, '1996-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 4), 17, 'Family Ties', 'X-Factor''s Quicksilver, and his sister, the Avenger called Scarlet Witch, seek revenge against Magneto when they learn that he was responsible for their birth mother''s death. But the trio is unaware of the common bond between them, nor the true purposes of the mysterious man who brought them all together.', 21, '1996-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 1, 'The Phalanx Covenant (1)', 'Rushing to investigate a disturbance downtown, the X-Men find Sabretooth on the rampage again, but realize too late that it isn''t really Sabretooth at all. It is the Phalanx, a voracious alien life-form that can assume the guise of anything or anyone. Before long, the X-Men are all captured, except for Beast, who must find a way to stop the alien horror from devouring the entire Earth.', 20, '1996-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 2, 'The Phalanx Covenant (2)', 'Snatched from the jaws of the Phalanx by the villainous Mr. Sinister, Beast and Forge search for allies to help them battle the alien threat. Gathering assistance from such unlikely sources as Magneto and Sinister himself, they embark upon a daring and risky plan to free the planet from the clutches of the Phalanx by traveling straight into the belly of the beast.', 20, '1996-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 3, 'A Deal with the Devil', 'The former Soviet Union''s living weapon, Omega Red, is thawed out by the US Military to deal with an abandoned Soviet nuclear submarine near Hawaii. He asks for his old enemy, Wolverine, and the woman responsible for freezing him most recently, Storm, to accompany him on the mission. Omega Red is offered restored humanity, but once aboard the warhead-filled sub, he reveals his true, deadly intentions.', 20, '1996-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 4, 'No Mutant Is an Island', 'Cyclops, still in mourning after Jean Grey''s "death", quits the X-men and returns to his orphanage home and encounters his friend Sarah. She tells him that a wealthy man has decided to adopt all the mutant children, especially Rusty, but his intentions are to make them his army to destroy all humans in the world so that mutants are accepted. It''s up to Cyclops to stop him and save the mutant children.', 20, '1996-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 5, 'Longshot', 'Longshot, a rebel from another world, tumbles into this world with no memory and a murderous gang led by the six-armed woman warrior Spiral hot on his trail. It turns out that Longshot is on the run from Mojo, maniacal inter-dimensional TV executive. Using Jubilee as the ''prize'', Mojo and his minions lure Longshot and the X-Men into a deadly contest which Mojo broadcasts ''live'' to up his ratings.', 20, '1996-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 6, 'Bloodlines', 'Nightcrawler gets a mysterious message. He is informed that his birth mother (whom he never knew) is in trouble. He turns to the X-Men for assistance. Jubilee is baffled that Nightcrawler wants to help the mother who abandoned him -- she has never known her birth parents and feels pretty hostile toward them, whoever they are. Nightcrawler admits there has been pain, but his faith in God has helped him overcome her rejection. The plot thickens when one of the team members recognizes Nightcrawler''s mother''s voice.', 20, '1996-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 7, 'Storm Front (1)', 'The dashing alien, Arkon, unleashes terrible weather conditions over Washington D.C. to get Storm''s attention. It works, he begs her to return with him to his planet, Corsus, to save it from meteorological chaos which threatens his people.', 20, '1996-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 8, 'Storm Front (2)', 'Spectacular preparations for Storm''s wedding to Arkon proceed quickly. But as Jubilee helps Storm, the new queen, prepare for the wedding, Jubilee can''t help notice how badly the palace workers are treated. Meanwhile, Wolverine, Cyclops and Beast discover there are fleet ships bringing slaves from the neighboring planet.', 21, '1996-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 9, 'Jubilee''s Fairytale Theatre', 'Jubilee tells children her own fairy tale having herself, her fellow X-Men and their greatest enemies be the characters in it.', 20, '1996-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 10, 'The Fifth Horseman', 'Fabian Cortez helps Apocalypse escape from the astral plane.', 20, '1997-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 11, 'Old Soldiers', 'Wolverine thinks back to the time when he fought during World War II and teamed up with Captain America.', 20, '1997-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 12, 'Descent', 'The origin of Mr. Sinister is revealed.', 20, '1997-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 13, 'Hidden Agendas', 'When the army learns of Sam Guthrie''s cannonball power, they try to enlist him in their ranks.', 20, '1997-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0103584')) AND numero_temporada = 5), 14, 'Graduation Day', 'At a Mutant/Human Relations Summit, Henry Peter Gyrich attacks.', 20, '1997-09-20');
