INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106080')), 1, 'Season 1', 'Fran Fine is a street-smart, down-on-her-luck diva who finds herself hired for a job for which she never even applied! Now, she''s the nanny for a rich, sophisticated family in Manhattan, and when this blue-collar girl from the block moves in with a blue blood, widowed Broadway producer and his three children, the comedy is red hot!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106080')) AND numero_temporada = 1), 1, 'The Nanny', 'Fran has just been dumped by her fiancé and employer, and is selling cosmetics door-to-door, when she happens to be in the right place at the right time.', 25, '1993-11-03');
