INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106080')), 2, 'Season 2', 'In the second season, Nanny Fine continues her inimitable style of witty one-liners, physical comedy, and fashion flair. As the season unfolds, Fran is mistaken for a nurse, arrested for kidnapping a baby, and cast in a Broadway production. Sparks of affection continue to fly between Miss Fine and Mr. Sheffield, while the razor-sharp repartee of C.C. Babcock and Niles further fuels the hilarity.');
