INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106080')) AND numero_temporada = 2), 8, 'Pishke Business', 'Maxwell has Fran pretend to be C.C. in order to get theatrical backing from a man C.C. attacked to get a cab.', 24, '1994-10-31');
