INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 9, 'Poetic License: An Ode to Holden Caulfield', 'When Cory degrades a student''s poem that Mr. Feeny reads in class, he is dismayed when he finds out that Shawn wrote it.', 24, '1998-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 10, 'And in Case I Don''t See Ya', 'In an effort to become more popular, Eric creates a TV show similar to The Truman Show featuring his roommates, but it''s Rachel who becomes the campus darling. Meanwhile, Cory and Shawn expect special treatment from Mr. Feeny.', 24, '1998-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 11, 'Santa''s Little Helpers', 'Now that Cory and Topanga both know that Shawn and Angela still love each other, they have conflicting views on what to do about it -- especially when, unbeknownst to each other, Cory invites Shawn to join their family Christmas while Topanga invites Angela. Topanga wants to let well enough alone, but Cory misses no opportunity to throw his friends together, but the consequences are not exactly what he wants: after they finally kiss, Angela expresses her love for Shawn, but he protests that he is "not ready" to make the same commitment and she storms off for good. Meanwhile, Eric takes his store Santa job a little too seriously when he convinces Rachel and Jack to help him steal his family''s gifts in order to make underprivileged children happy.', 24, '1998-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 12, 'Cutting the Cord', 'Shawn and Angela draw up a restraining order forbidding Cory and Topanga from any further interference in their romantic lives, but Shawn still has a difficult time seeing Angela date someone else -- especially when they all wind up in the same restaurant together. Meanwhile, Alan tries to overcome his feeling too old for another baby by shopping for a motorcycle, and Eric becomes an over-enthusiastic birthing coach.', 24, '1999-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 13, 'We''ll Have A Good Time Then...', 'Shawn and Jack''s ne''er-do-well father Chet reappears on campus suddenly and, confronted by an angry Shawn, promises that he has come to stay and make amends to his sons for never being there for them. But after treating them to a steak dinner and consuming a piece of Rachel''s "killer" chocolate cake, Chet suffers a heart attack.', 24, '1999-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 14, 'Getting Hitched', 'Cory and Topanga play "The Fiancée Game" to prove how compatible they are, and are crushed when Eric and Rachel prove to know far more about each other than they do. Topanga suggests a quick solution: they should live together on campus and really get to know each other. (Cory mistakenly thinks this means sex and buys satin pyjamas and sheets.) Living together shows them sides of each other they''re not too crazy about: for example, his big toe clipping flies across the room and lodges in her already-applied facial cream. Meanwhile, Shawn has ignored Jack''s repeated call about clearing out Chet''s trailer, and, once persuaded, is freshly outraged to discover evidence that Chet went to Jack''s stepfather for help in financing Shawn''s college education. He decides to take the trailer out on the highway and convinces Cory to accompany him "for the weekend," but oddly insists on saying goodbye to Topanga. Then Jack, who has been struggling to contain his own grief in deference to Shawn''s feelings, falls apart and cries helplessly in Rachel''s arms; and Eric walks in to find them kissing passionately.', 24, '1999-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 15, 'Road Trip', 'To take his mind off his dad''s death, Shawn takes Cory along on a soul-searching road trip in Chet''s trailer, where they end up at a truck stop where the young waitresses are searching for something more, just like Shawn -- and Cory discovers that Shawn has no intention of returning home.', 24, '1999-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 16, 'My Baby Valentine', 'Cory becomes upset when Topanga seems less interested in spending Valentine''s Day with him than with consoling Amy about the last stages of her pregnancy, so when Topanga decides to cheer Amy up with a baby shower, Cory takes charge. Unfortunately his concept of a baby shower turns out to be a female version of a bachelor party, complete with a pizza-guy stripper, but the disgusted guests are distracted when Amy''s waters break and she is rushed to hospital for a premature delivery -- one which the new Matthews baby may not survive. Meanwhile, Shawn is still on the road to nowhere; Morgan is less than happy about the arrival of a new sibling; and Jack and Rachel worry about the effect of revealing their new relationship to Eric -- who announces he already knows, and is moving out.', 24, '1999-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 17, 'Resurrection', 'While everyone anxiously awaits news about newly born Joshua Matthews, Cory''s continued self-absorption alienates Topanga, who now considers herself a member of the Matthews family. Even Eric''s little friend Tommy views Joshua as his new "brother." It''s only when Shawn returns and is accepted by the elder Matthews as "family" does Cory realize where his true values lie.', 24, '1999-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 18, 'Can I Help to Cheer You?', 'Topanga is in wedding plan mode, and persuades (strongarms) Cory into accompanying her, Shawn and Angela to a posh ceremony in the hall of her dreams -- where an unhappy father of the bride offers Cory a million dollars to marry his daughter. Meanwhile, Tommy pleads with a heartbroken Eric to adopt him so he won''t have to move to California, and Eric pretends to no longer want Tommy so he can be happy with his new family.', 24, '1999-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 19, 'Bee True', 'The series returns to form as Cory and Shawn unite for the last time as a "bad boy" team to help Mr. Feeny, whose hesitation in declaring his feelings for Dean Bolander looks like a fatal mistake when her ex-husband Curits returns from an expedition bent on winning her back. Shawn and Cory trash the interloper''s lab and blame in on a jealous rage by Feeny -- who then saves Dean Bolander''s life for real by swatting the rare bee brought back by Curits just before it stings his highly allergic love. She explains that she was not taken in for a moment by the boys'' ruse -- just impressed that Feeny''s students care about him so much. Meanwhile, Rachel challenges Jack to take her out on a real date.', 24, '1999-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 20, 'The Truth About Honesty', 'When Cory and Topanga make an agreement to tell the truth about everything and everyone, their totally honest pact creates tension at Rachel and Jack''s first dinner party. When the party guests play a game that forces them to also tell the truth, personal feelings are revealed that they would rather keep to themselves.', 24, '1999-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 21, 'The Psychotic Episode', 'When Cory has nightmares where the recurring theme finds him trying to kill Shawn in imaginative ways, he goes to Feeny for an interpretation. Meanwhile, Eric finds a new, but odd, roommate -- one who seems to have seen Hitchcock''s "Psycho" once too often.', 24, '1999-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 6), 22, 'State of the Unions', 'While Cory deals with his anxieties about his impending marriage, Topanga''s parents come for a visit and reveal some unexpected news: they are on the brink of separating. Meanwhile, Feeny pops the question to Dean Bolander, and they agree to get married in the Matthews living-room; and a self-pitying Eric asks Shawn for advice on how to cope with losing Rachel to Jack.', 24, '1999-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 1, 'Show Me the Love (Part 1)', 'Topanga''s decision to end things with Cory affects Angela''s resolve to reunite with Shawn. Meanwhile, Jack and Rachel don''t fare much better, and Eric sees his chance to move back in vanish after the ladies come knocking.', 24, '1999-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 2, 'For Love and Apartments (Part 2)', 'As Cory and Shawn hit Pittsburgh to reunite Topanga''s folks, WWF star Mankind refs a battle between Jack, Eric and the ladies over possession of the apartment.', 24, '1999-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 3, 'Angela''s Men', 'A few good men come to Angela''s aid when Shawn recruits her military dad to help the lonely lady deal with her missing mom. Meanwhile, Eric maps out a strategy to exact his revenge on Topanga for beating him up and stealing his apartment.', 24, '1999-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 4, 'No Such Thing as a Sure Thing', 'On the eve of the big game, Eric gets Jack in over his head with a bookie, while Topanga decides to put her money on Cory after her mom visits.', 24, '1999-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 5, 'You Light Up My Union', 'Jack and Eric learn the art of dealing with each other when they take over as managers of the student union. Meanwhile, Rachel reads the guys the riot act after Cory and Shawn pry into her diary.', 24, '1999-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 6, 'They''re Killing Us', 'Topanga and Cory hash out their wedding woes, which include his selection for best man and her dress-hating bridesmaids. Meanwhile, Alan and Amy try to cut costs by hiring Feeny as the big day''s musical attraction.', 24, '1999-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 7, 'It''s About Time', 'Cory and Topanga''s big day hits a major hitch after Eric alters their wedding locale and Shawn quits as best man.', 24, '1999-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 8, 'The Honeymooners', 'Eric follows Cory and Topanga to their tropical honeymoon, a destination where the newlyweds consider relocating, permanently. But as the days go by, each of the trio discovers the true meaning of family and friends and the comforts of home.', 24, '1999-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 9, 'The Honeymoon Is Over', 'The honeymoon is over for Cory and Topanga: the newlyweds realize they have no home to call their own, after Shawn moves into the girls'' apartment and the Matthews refuse to take them in.', 24, '1999-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 10, 'Pickett Fences', 'Cory and Topanga realize that a house is not for them after Shawn sells them on working together to fix up their apartment. Meanwhile, Angela and Rachel play the roommate shuffle once again; and Jack and Eric get a new boss at the student union.', 24, '1999-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 11, 'What a Drag!', 'Jack and Eric find life a drag when they pose as women-ugly women-to escape the clutches of a campus goon. Meanwhile, Topanga can''t paint over her horror when Cory redecorates the apartment.', 24, '1999-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 12, 'Family Trees', 'Shawn struggles to accept the fact that he has no idea who his parents are. Meanwhile, Eric puts together a surprise party for his dad, who has an even bigger surprise for the despondent Shawn.', 24, '1999-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 13, 'The Provider', 'Cory and Topanga''s love nest turns into a battle zone after she lands a better job than his at-home telemarketing gig. Meanwhile, Eric gets his money''s worth out of a lucky penny, until he passes it on to his brother.', 24, '2000-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 14, 'I''m Gonna Be Like You, Dad', 'Topanga develops an acute case of Cory-itis after he overreacts to his low score in a magazine''s health quiz (which indicates he should already be dead). Meanwhile, Eric joins the family business and shocks his father by doing well at it-while Amy, in turn, is shocked at Alan''s lack of faith in his son.', 24, '2000-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 15, 'The War (Part 1)', 'A fierce war of pranks ensues after Cory and Shawn slight Rachel.', 24, '2000-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 16, 'Seven the Hard Way (Part 2)', 'After a war of harmless pranks goes too far and threatens to break up the old gang, Feeny steps in to help mend fences. But he finds that even his intervention may not be enough to reunite the once-tight teens.', 24, '2000-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 17, 'She''s Having My Baby Back Ribs', 'When Topanga diets to stem a slight weight gain, Cory panics that her new size may be due to a different type of baby fat. Meanwhile, Eric has a hard time watching his own weight.', 24, '2000-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 18, 'How Cory and Topanga Got Their Groove Back', 'Cory and Topanga try to shed their humdrum personas by hosting a bash on the same night as the school''s biggest party of the year. Meanwhile, Jack concocts a get-rich-quick scheme after a bump on the head bestows Eric with telepathic powers.', 24, '2000-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 19, 'Brotherly Shove', 'Family ties threaten to choke Eric and Cory when they argue over what to sell--and what to save--at a Matthews garage sale. Meanwhile, Jack and Shawn try to become more brotherly, but can''t find anything in common to bond over.', 24, '2000-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 20, 'As Time Goes By', 'A film-noir spoof finds Topanga causing waves at a placid resort where her uptight ways lead someone to murder.', 24, '2000-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 21, 'Angela''s Ashes', 'Shawn hits rough waters as Angela preps to move overseas with her dad. Topanga pursues a job in New York, though a clueless Cory misses the boat on her own plans to relocate.', 24, '2000-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 22, 'Brave New World (Part 1)', 'In a clip-filled series finale, Cory and the gang bid Mr. Feeny farewell as he and Topanga head to New York. Meanwhile, Jack, Eric and Shawn make big moves of their own.', 24, '2000-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0105958')) AND numero_temporada = 7), 23, 'Brave New World (Part 2)', 'In a clip-filled series finale, Cory and the gang bid Mr. Feeny farewell as he and Topanga head to New York. Meanwhile, Jack, Eric and Shawn make big moves of their own.', 24, '2000-05-05');
