INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')), 1, 'Season 1', 'The Provisional Government of Bajor invites Starfleet to help them rebuild after the Cardassian Occupation. Commander Benjamin Sisko is selected to take command of their space station, formerly known as Terok Nor that is then designated by Starfleet as Deep Space 9. As part of the agreement between the Federation and Bajor, Starfleet will help them to become a member of the Federation.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 1, 'Emissary', 'Stardate: 46379.1.  Commander Benjamin Sisko and a new crew of Starfleet and Bajoran officers take command of an abandoned Cardassian space station and make an incredible discovery that will change the galaxy and Sisko''s future.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 2, 'Past Prologue', 'Stardate: Unknown.  Kira finds her loyalties divided when a Bajoran extremist wanted by the Cardassians comes to the station with questionable intentions.', 45, '1993-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 3, 'A Man Alone', 'Stardate: 46421.5.  When the return of a man Odo sent to prison years earlier leads to his murder aboard the station, Odo becomes the prime suspect and a target for harassment.', 45, '1993-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 4, 'Babel', 'Stardate: 46423.7.  A deadly virus created by the Bajorans 18 years earlier inadvertently breaks loose aboard the station, and prompts a race against the clock to find a cure.', 45, '1993-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 5, 'Captive Pursuit', 'Stardate: Unknown.  When O''Brien befriends the station''s first visitor from the Gamma Quadrant, he learns that the mysterious alien is on the run from determined pursuers.', 45, '1993-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 6, 'Q-Less', 'Stardate: 46531.2.  Vash arrives from the Gamma Quadrant as Q plagues the station and an unknown force threatens to destroy it.', 45, '1993-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 7, 'Dax', 'Stardate: 46910.1.  Jadzia Dax is charged with a murder that her symbiont''s previous host Curzon allegedly committed. Now an extradition hearing may decide whether Jadzia can be held responsible for the actions of a previous life.', 45, '1993-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 8, 'The Passenger', 'Stardate: Unknown.  A dangerous killer dies in an apparent accident, but the security officer providing his transport to prison believes the criminal''s consciousness may have yet survived.', 45, '1993-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 9, 'Move Along Home', 'The Wadi from the Gamma Quadrant are to make first contact and decide to visit DS9. When they catch Quark cheating they let him off by playing a special game.', 45, '1993-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 10, 'The Nagus', 'Stardate: Unknown.  Grand Nagus Zek, the leader of Ferengi society, comes to DS9 to oversee the introduction of a Ferengi business presence in the Gamma Quadrant and announce Quark as his successor.', 45, '1993-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 11, 'Vortex', 'Stardate: Unknown.  A wanted man from the Gamma Quadrant with questionable motives reveals to Odo stories about other "Changelings," which may hold clues to Odo''s mysterious origin.', 45, '1993-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 12, 'Battle Lines', 'Stardate: Unknown.  Sisko, Kira, and Bashir take Kai Opaka through the wormhole for a brief excursion in the Gamma Quadrant. But when they crash-land on a desolate planet, they find a divided, warring penal colony where no one ever dies.', 45, '1993-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 13, 'The Storyteller', 'Stardate: 46729.1.  When O''Brien and Bashir beam down to a Bajoran village, the community selects O''Brien as their next Sirah - expecting him to save them from a menacing entity.', 45, '1993-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 14, 'Progress', 'Stardate: 46844.3.  Kira finds herself in a difficult moral situation when her job demands she force an adamant Bajoran man from his home in the name of progress.', 45, '1993-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 15, 'If Wishes Were Horses', 'Stardate: 46853.2.  The DS9 crew''s own imaginations cause mysterious beings with unknown intentions to appear on the station.', 45, '1993-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 16, 'The Forsaken', 'Stardate: 46925.1.  Odo and Lwaxanna Troi come to a mutual understanding when a computer malfunction causes them to become trapped in a turbolift.', 45, '1993-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 17, 'Dramatis Personae', 'Stardate: 46922.3.  An alien "telepathic matrix" causes the DS9 crew to re-enact an ancient power struggle, leading Kira to attempt mutiny and overthrow Sisko.', 45, '1993-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 18, 'Duet', 'A Cardassian suffering from Kalla-Nohra, a disease that indicates he served in a labor camp, visits DS9. Kira is determined to convict him as a war criminal.', 45, '1993-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 1), 19, 'In the Hands of the Prophets', 'Stardate: Unknown.  The Federation and Bajoran people of DS9 fall into conflict when a Bajoran religious extremist comes to the station and challenges the secular teachings of Keiko O''Brien''s school.', 43, '1993-06-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')), 2, 'Season 2', 'In their second year together, the crew of Deep Space 9 face problems that will affect the galaxy forever. A Bajoran extremist group attempts to force the Federation out of the Bajoran system. The Cardassians are secretly supplying them with weapons, hoping to return to reclaim the planet and hold the Bajoran wormhole for the Cardassian Union. However, the greatest enemy of all is lurking beyond it.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 2), 1, 'The Homecoming (1)', 'Stardate: Unknown. Word that a previously thought dead Bajoran resistance legend is still alive sends Kira and Chief O''Brien to Cardassia IV to rescue him; meanwhile "The Circle", a sect of the Bajoran provisional government that is intent on wiping out alien influence, is sneaking into power.', 45, '1993-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 2), 2, 'The Circle (2)', 'Stardate: Unknown. Kira spends time with Vedek Bareil on Bajor just as "The Circle" begins arming themselves from a mysterious source.', 45, '1993-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 2), 3, 'The Siege (3)', 'Stardate: Unknown. As a "Circle"-led Bajoran military tries to occupy the station, a skeleton crew led by Sisko fight to reveal "The Circle''s" big secret before they are forced to evacuate themselves. Meanwhile, Kira and Dax lead a mission to reveal the truth about "The Circle" on Bajor.', 45, '1993-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 2), 4, 'Invasive Procedures', 'Stardate: 47182.1. A jealous Trill, who had waited his entire life to receive a symbiont but never had, decides to steal one. . . Dax''s!', 45, '1993-10-17');
