INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 2), 7, 'Rules of Acquisition', 'Stardate: Unknown. A female Ferengi, posing as a male to be available to participate in business (a rule STRICTLY forbidden by the Ferengi government), falls for Quark during very important negotiations between the Ferengi and a Gamma Quadrant race.', 45, '1993-11-07');
