INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 2), 18, 'Profit and Loss', 'Stardate: Unknown. A Cardassian woman, who was once a former flame of Quark''s, visits the station under dubious circumstances.', 45, '1994-03-20');
