INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')), 3, 'Season 3', 'Season 3 of Deep Space Nine marks a turning point for the series, as it introduces the USS Defiant, a powerful starship that allows the crew to explore the Gamma Quadrant and face the threat of the Dominion, a vast and ruthless empire ruled by the shape-shifting Founders.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 3), 1, 'The Search (1)', 'Stardate: 48213.1. Instead of waiting for the Jem''Hadar to attack, Sisko wants to try a different approach. He wants to take a new class starship to try to find the Founders.', 45, '1994-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 3), 2, 'The Search (2)', 'Stardate: 48213.1. Odo has found his home and is introduced. Meanwhile Sisko finds out peace talks between the Dominion and the Federation have already started.', 45, '1994-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 3), 3, 'The House of Quark', 'Stardate: Unknown. Quark tries to boost his reputation by taking credit for the accidental death of a Klingon in his bar, but lands himself in the middle of a Klingon political struggle.', 45, '1994-10-10');
