INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 4), 24, 'Body Parts', 'Stardate: Unknown. Quarks hears on Ferenginar he is going to die. Rom convinces him to sell his remains. After an accident, Bashir has to move Keiko''s baby to Kira''s womb.', 45, '1996-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 4), 25, 'Broken Link', 'Stardate: 49962.4. Odo is suddenly struck by illness. He is barely able to hold shape. Bashir and Odo see no other alternative then going to the Founders. Garak wants to come along.', 45, '1996-06-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')), 5, 'Season 5', 'Season 5 of Deep Space Nine begins the Dominion War arc that will dominate the rest of the show. The Federation and its allies face a new enemy in the form of the Cardassian-Dominion alliance, which threatens to conquer the Alpha Quadrant.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 1, 'Apocalypse Rising', 'Stardate: Unknown. With the war between Klingons and Federation intensifying, Sisko must make a plan to expose Gowron as a changeling. Odo is still having trouble with becoming a solid.', 45, '1996-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 2, 'The Ship', 'Stardate: 50049.3. The crew find a crashed Jem’Hadar ship and work to repair it and capture it for the Federation, but are confronted by a Dominion force determined to recover the ship’s cargo.', 45, '1996-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 3, 'Looking for par''Mach in All the Wrong Places', 'Stardate: Unknown. While Worf helps Quark to pursue his former wife Grilka, O''Brien and Kira grow uncomfortably close to each other.', 45, '1996-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 4, 'Nor the Battle to the Strong', 'Stardate: Unknown. Jake, reporting from the front lines, sees what war truly is.', 45, '1996-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 5, 'The Assignment', 'Stardate: Unknown. An alien entity has possessed Keiko''s body and is holding it hostage until O''Brien completes an assignment for it.', 45, '1996-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 6, 'Trials and Tribble-ations', 'Stardate: 4523.7. In this celebration of the 30th anniversary of The Original Series, the disgraced Klingon spy Darvin travels back in time to undo his century-old defeat by James Kirk. The DS9 crew must track him down and stop him, while blending in with the crew of the original Enterprise NCC-1701.', 45, '1996-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 7, 'Let He Who Is Without Sin...', 'Stardate: Unknown. While vacationing on Risa, Worf and Dax meet a group of fundamentalist protesters who claim that the Federation has gone soft.', 45, '1996-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 8, 'Things Past', 'Stardate: Unknown. Sisko, Dax, Odo and Garak find themselves in the past when the Cardassians controlled the station, and a crime that Odo investigated may be the key.', 45, '1996-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 9, 'The Ascent', 'Stardate: Unknown. When Odo and Quark crash land, they must put aside their differences to climb a mountain to signal for help. Jake and Nog try to be roommates, but their different styles clash.', 45, '1996-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 10, 'Rapture', 'Stardate: Unknown. After a brain injury, Sisko begins experiencing powerful visions through time. He dives fully into the role of the Emissary, while becoming obsessed with finding a legendary Bajoran ruin.', 45, '1996-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 11, 'The Darkness and the Light', 'Stardate: 50416.2. A mysterious assassin begins wiping out all the members of Kira''s old resistance cell.', 45, '1997-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 12, 'The Begotten', 'Stardate: Unknown. The discovery of an infant Changeling gives Odo a chance to put right the trauma of his own upbringing, while his “father” Dr. Mora insists on a more clinical approach.', 45, '1997-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 13, 'For the Uniform', 'Stardate: 50485.2. When the traitorous Eddington returns, Sisko will go to any lengths to capture him.', 45, '1997-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 14, 'In Purgatory''s Shadow (1)', 'Stardate: Unknown. A coded message from the Gamma Quadrant leads Garak to believe his mentor, Enabran Tain, is still alive. He and Worf seek him out, only to discover something much worse: a Dominion invasion fleet poised to attack the Alpha Quadrant.', 45, '1997-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 15, 'By Inferno''s Light (2)', 'Stardate: 50564.2. The station readies for a Dominion attack. Worf and Garak meet some unexpected friends in a Dominion Prison camp.', 45, '1997-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 16, 'Doctor Bashir, I Presume?', 'Stardate: Unknown. Dr. Bashir is selected to be the model for the next-generation of Emergency Medical Hologram (EMH). But he balks when his parents are invited to the station to be interviewed by the EMH programmer, Dr. Zimmerman. There is a dark secret in his family that he''s afraid that his parents will reveal.', 45, '1997-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 17, 'A Simple Investigation', 'Odo helps a woman hiding on the station from organized criminals, but quickly develops a personal interest in the case.', 45, '1997-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 18, 'Business As Usual', 'Stardate: Unknown. Quark must wrestle with his conscience when he becomes involved with arms merchants.', 45, '1997-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 19, 'Ties of Blood and Water', 'Stardate: 50712.2. When a Cardassian official that thinks of Kira as his daughter is dying, he agrees to reveal all he knows to her. But the experience dredges up Kira''s memories of her own father''s death.', 45, '1997-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 20, 'Ferengi Love Songs', 'Stardate: Unknown. Quark doesn''t know whether to be panicked or overjoyed when he learns that his mother is the new lover of the Grand Nagus.', 45, '1997-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 21, 'Soldiers of the Empire', 'Stardate: Unknown. Dax and Worf accompany Martok on his first command since being held by the Dominion. But the ship they are given hasn''t seen victory in months and the crew is near mutinous.', 45, '1997-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 22, 'Children of Time', 'Stardate: 50814.2. The DS9 crew discovers a colony that, due to a time travel accident, turns out to be inhabited by the crew''s own descendants.', 45, '1997-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 23, 'Blaze of Glory', 'Stardate: Unknown. Sisko learns that the Maquis are planning a devastating attack on Cardassia, and must rely on the traitor Eddington to help him prevent it.', 45, '1997-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 24, 'Empok Nor', 'Stardate: Unknown. While salvaging components from DS9''s sister station, the crew run afoul of a "surprise" left behind by the Cardassians.', 45, '1997-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 25, 'In the Cards', 'Stardate: 50929.4. Jake has his heart set on a vintage Willie Mays baseball card as a present to cheer up his father, whose spirits are flagging from the ongoing conflict.', 45, '1997-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 5), 26, 'Call to Arms', 'Stardate: 50975.2. Sisko decides to mine the wormhole to prevent further Dominion ships crossing into the Alpha Quadrant. This provokes an attack by the Dominion and the Cardassians, and a desperate last stand on Deep Space Nine.', 45, '1997-06-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')), 6, 'Season 6', 'Season 6 of Deep Space Nine marks the height of the Dominion War arc, as it depicts the Federation and its allies in a desperate struggle against the Cardassian-Dominion alliance, which has occupied Deep Space Nine and the Bajoran system.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 1, 'A Time to Stand', 'Stardate: Unknown. As the war between the Federation and the Dominion continues, Sisko and his crew are reassigned from the Defiant, while Kira and Odo cope with the bureaucracy of the station''s occupation.', 45, '1997-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 2, 'Rocks and Shoals', 'Stardate: Unknown. Sisko and his crew are marooned on a barren planet with a squadron of Jem''Hadar soldiers and their wounded Vorta overseer. But when the Vorta seeks out Sisko to make a deal, can he be trusted? And should Sisko accept the treacherous proposal?', 45, '1997-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 3, 'Sons and Daughters', 'Stardate: Unknown. Worf and his son Alexander must come to terms with one another when Alexander is assigned to the Rotarran and voices his intentions to become a warrior. Meanwhile, Kira finds herself between friend and foe when Ziyal returns to the station and reconciles with her father.', 45, '1997-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 4, 'Behind the Lines', 'Stardate: 51145.3. Odo finds his priorities at odds with Kira''s resistance efforts when the Female Changeling comes to him and offers to guide him in learning about the Great Link.', 45, '1997-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 5, 'Favor the Bold (1)', 'Stardate: Unknown. On the eve of Dukat successfully disabling the minefield, Sisko coordinates a massive assault to retake Deep Space Nine.', 45, '1997-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 6, 'Sacrifice of Angels (2)', 'Stardate: Unknown. The Federation''s only hope of stopping massive Dominion reinforcements from entering the Alpha Quadrant relies on Sisko''s suicide mission to reach DS9 before the minefield is destroyed.', 45, '1997-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 7, 'You Are Cordially Invited', 'Stardate: 51247.5. Dax and Worf find their wedding plans threatened when Martok''s wife challenges Jadzia''s worthiness to be admitted into their house.', 45, '1997-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 8, 'Resurrection', 'Stardate: Unknown. Kira finds herself falling in love with the mirror-universe version of Bareil, who has crossed the reality plane to begin a new life.', 45, '1997-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 9, 'Statistical Probabilities', 'Stardate: Unknown. Bashir agrees to counsel a group of eccentric, genetically enhanced humans ... and finds himself reevaluating his own enhanced nature when they calculate a disastrous prediction for the outcome of the Dominion War.', 45, '1997-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 10, 'The Magnificent Ferengi', 'Stardate: Unknown. When Quark and Rom''s mother is abducted by the Dominion, the two brothers recruit an all-Ferengi team to embark on a dangerous mission to get her back.', 45, '1998-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 11, 'Waltz', 'Stardate: 51408.6. After being attacked by Cardassian forces, Sisko gets stranded with a very psychotic Gul Dukat, who was being transported to his trial. Meanwhile the crew of the Defiant races to rescue survivors.', 45, '1998-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 12, 'Who Mourns for Morn?', 'Stardate: Unknown. A former patron of Quark''s bequeaths everything to him.', 45, '1998-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 13, 'Far Beyond the Stars', 'Stardate: Unknown. Captain Sisko has a full sensory vision of himself as an under-appreciated science fiction magazine writer in 1950s America.', 45, '1998-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 14, 'One Little Ship', 'Stardate: 51474.2. An attack by the Dominion on Sisko''s ship endangers Dax and her crew aboard as she leads them into an anomaly that shrinks them to a very minute size. Unfortunately, they were being held stable by Sisko within a tractor beam, which was discontinued during the attack.', 45, '1998-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 15, 'Honor Among Thieves', 'Stardate: Unknown. Chief O''Brien goes undercover to infiltrate an Orion crime ring.', 45, '1998-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 16, 'Change of Heart', 'Stardate: 51597.2. Worf and Jadzia travel to the badlands to procure some information on the Dominion from a traitorous Cardassian. Bashir wants to engage in a holo-suite spy simulation, but O''Brien prefers to brush up on his tongo game after watching Jadzia lose to Quark.', 45, '1998-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 17, 'Wrongs Darker Than Death or Night', 'Stardate: Unknown. After receiving some disturbing information from Gul Dukat, Major Kira seeks Sisko''s approval as Emissary to travel back in time to find out the truth about her mother. Meanwhile, Chief O''Brien and Dr. Bashir discuss a holosuite program surrounding the Battle of the Alamo.', 45, '1998-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 18, 'Inquisition', 'Stardate: Unknown. Dr. Bashir''s plans to attend a medical conference at a breezy resort are canceled when Starfleet Intelligence boards DS9, suspecting the doctor of treason.', 45, '1998-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 19, 'In the Pale Moonlight', 'Stardate: 51721.3. To save the Federation in a critical scheme, Sisko comes to realize that he must violate its fundamental principles to do so.', 45, '1998-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 20, 'His Way', 'Stardate: Unknown. Odo is schooled in the ways of romance by a holographic programmed lounge singer.', 45, '1998-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 21, 'The Reckoning', 'Stardate: Unknown. Sisko runs afoul of Kai Winn when he removes a Bajoran artifact from an archaeological dig after he receives a vision from the Prophets.', 45, '1998-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 22, 'Valiant', 'Stardate: 51825.4. Jake and Nog''s runabout comes under attack from the Jem''Hadar. They are rescued by the Valiant, a ship manned by Red Squad, a elite group of young Starfleet cadets.', 45, '1998-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 23, 'Profit and Lace', 'Stardate: Unknown. Quark''s mother and the Grand Nagus show up on DS9, announcing a new amendment to the Bill of Opportunities he has instituted on the home planet of Ferenganar, and then follows up with the announcement, that, due to the new amendment, chaos has followed and he has been deposed.', 45, '1998-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 24, 'Time''s Orphan', 'Stardate: Unknown. The Chief''s daughter gets caught in a time displacement and when they get her back, she is considerably older.', 45, '1998-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 25, 'The Sound of Her Voice', 'Stardate: 51948.3. As the Defiant races to a shipwrecked officer who is days away, the crew keeps in contact with her. Meanwhile, Jake follows Quark''s latest scheme for story research.', 45, '1998-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 6), 26, 'Tears of the Prophets', 'Stardate: Unknown. When Sisko is picked to head up an attack on the Cardassian homeworld, the Prophets appear to him in a vision, warning him of impending doom if he leaves the station.', 45, '1998-06-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')), 7, 'Season 7', 'Season 7 of Deep Space Nine marks the end of the series, as it concludes the Dominion War arc and the saga of the characters and their relationships. The Federation and its allies face the final showdown with the Cardassian-Dominion alliance, which is aided by the Breen. Sisko and his crew must also deal with the threat of the pah-wraiths, the evil counterparts of the Prophets, who are unleashed by Kai Winn and Dukat.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 1, 'Image in the Sand', 'Stardate: Unknown. As Kira begins working with a Romulan presence aboard the station, Sisko looks for answers in a vision he receives from the Prophets, leading him to uncover a family secret.', 45, '1998-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 2, 'Shadows and Symbols', 'Stardate: 52152.6. As Sisko searches for the Orb of the Emissary, Kira prepares a blockade opposing the Romulans near the Bajoran moon Durna. Meanwhile, Worf and Martok lead a suicide mission in Jadzia''s name.', 45, '1998-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 3, 'Afterimage', 'Stardate: Unknown. Ezri Dax finds difficulty in trying to settle into a new life, as Jadzia''s memories and relationships provide her with one emotional challenge after another.', 45, '1998-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 4, 'Take Me Out to the Holosuite', 'Stardate: Unknown. Sisko is challenged by a Vulcan captain to a competitive match in an Earth game of skill known as ... baseball.', 45, '1998-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 5, 'Chrysalis', 'Stardate: Unknown. Bashir begins falling in love with a genetically engineered patient whom he helped bring out of her state of introversion.', 45, '1998-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 6, 'Treachery, Faith, and the Great River', 'Stardate: Unknown. A clone of Weyoun seeking asylum submits himself to Odo as a prisoner, offering invaluable information about the Dominion.', 45, '1998-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 7, 'Once More Unto the Breach', 'Stardate: Unknown. With nowhere to turn and old age having made him obsolete, Klingon legend Kor asks Worf to help him find one last glorious battle.', 45, '1998-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 8, 'The Siege of AR-558', 'Stardate: Unknown. Sisko''s crew is diverted to the front lines, where, alongside war-torn Starfleet officers, they must make a stand against a Jem''Hadar assault.', 45, '1998-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 9, 'Covenant', 'Stardate: Unknown. Kira is kidnapped by a Bajoran Pah-wraith cult led by Dukat.', 45, '1998-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 10, 'It''s Only a Paper Moon', 'Stardate: Unknown. Mentally and emotionally scarred by his combat injuries, Nog seeks comfort in the holographic fantasy world of Vic Fontaine.', 45, '1998-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 11, 'Prodigal Daughter', 'Stardate: Unknown. A search for O''Brien, who has gone missing somewhere near Ezri''s home world, reunites Ezri with her family and their troubles.', 45, '1999-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 12, 'The Emperor''s New Cloak', 'Stardate: Unknown. The Grand Nagus goes missing in the mirror universe, leading Quark and Rom on a mission to track him down.', 45, '1999-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 13, 'Field of Fire', 'Stardate: Unknown. A murder investigation prompts Ezri to confront the repressed memories of Joran, a former Dax host who had killed three people.', 45, '1999-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 14, 'Chimera', 'Stardate: 51474.2. A shapeshifter, one of "the hundred" sent from the Link centuries ago to explore the galaxy, tries to convince Odo to abandon his life as a humanoid in favor of a grander quest.', 45, '1999-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 15, 'Badda-Bing, Badda-Bang', 'Stardate: Unknown. A surprise programming feature brings mobsters to take over Vic''s lounge, leading the DS9 crew to devise a plan to get rid of them.', 45, '1999-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 16, 'Inter Arma Enim Silent Leges', 'Stardate: Unknown. When the mysterious Sloan attempts to recruit Bashir for an undercover mission on Romulus, Sisko orders Bashir to go along with the plan, in hopes of learning more about Section 31.', 45, '1999-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 17, 'Penumbra', 'Stardate: 52576.2. While Ezri goes searching for Worf, who has been missing since a Dominion attack on his ship, Sisko proposes marriage to Kasidy and begins plans to build a house on Bajor.', 45, '1999-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 18, '''Til Death Do Us Part', 'Stardate: Unknown. Sisko must decide whether to oppose the Prophets and marry Kasidy. Meanwhile, Dukat comes to DS9 with a Bajoran identity and a plan to manipulate Kai Winn; and Worf and Ezri are held captive by the Breen.', 45, '1999-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 19, 'Strange Bedfellows', 'Stardate: Unknown. A new alliance between the Dominion and the Breen further appalls Damar. Meanwhile, Winn finds her spirituality thrown into chaos when she has a vision from the Pah-wraiths.', 45, '1999-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 20, 'The Changing Face of Evil', 'Stardate: Unknown. As Winn begins studying her uncertain role in following the path of the Pah-wraiths, the Federation engages in battle for the first time against the Dominion and their new Breen allies.', 45, '1999-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 21, 'When It Rains...', 'Stardate: Unknown. As Kira leads a mission to help organize Damar''s resistance forces, Bashir learns that Odo has been infected with the disease sweeping through the Great Link.', 45, '1999-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 22, 'Tacking Into the Wind', 'Stardate: Unknown. As tensions mount within Kira and Damar''s resistance cell, Worf realizes he must take action to prevent Gowron from making a key strategic mistake.', 45, '1999-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 23, 'Extreme Measures', 'Stardate: 52645.7. Bashir and O''Brien capture Sloan and probe his mind in a search for the cure to Odo''s disease.', 45, '1999-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 24, 'The Dogs of War', 'Stardate: 52861.3. With the Cardassian resistance movement crushed, Kira, Damar, and Garak find themselves trapped behind enemy lines. Meanwhile, Grand Nagus Zek announces his retirement and plans to name Quark his successor.', 45, '1999-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106145')) AND numero_temporada = 7), 25, 'What You Leave Behind', 'Stardate: 52902.0. As the war careens toward a final showdown on Cardassia, Sisko''s definitive action as the Emissary draws near.', 90, '1999-06-02');
