INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 1, 'Season 1', 'Two agents from vastly different backgrounds join forces to solve cases the FBI has labeled X-Files, involving paranormal or unexplained phenomena. Both are determined to uncover hidden truths — one searching for otherworldly answers, the other for more earthbound scientific explanations. Together they will make discoveries neither could have ever imagined.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 1, 'Pilot', 'Agent Dana Scully is assigned to work with Agent Fox Mulder on the X-Files in an attempt to debunk his work on the paranormal. Their first case takes them to Oregon to investigate the unsolved murders of several high-school classmates.', 49, '1993-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 2, 'Deep Throat', 'Mulder and Scully investigate the mysterious case of a military test pilot who disappeared after experiencing strange psychotic behavior. While on the case, Mulder meets a mysterious man who claims to have classified information about investigations into the paranormal.', 46, '1993-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 3, 'Squeeze', 'Mulder and Scully search for a killer whose savage murder spree reoccurs every thirty years, where there appears to be no tangible method for the murderer''s entrance and escape.', 43, '1993-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 4, 'Conduit', 'As Section Chief Blevins expresses his concern with the direction of the X-Files, Mulder becomes obsessed with solving a case that closely parallels an encounter he experienced as a child: the abduction of his kid sister, Samantha.', 45, '1993-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 5, 'The Jersey Devil', 'Mulder and Scully track a legendary creature that has roamed the New Jersey countryside for over forty years..', 45, '1993-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 6, 'Shadows', 'Mulder and Scully investigate the deaths of two men believed to have been killed by a powerful psychokinetic force.', 46, '1993-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 7, 'Ghost in the Machine', 'It''s Halloween, and Mulder and Scully are investigating the strange death of a corporate executive in a sophisticated high-tech building.', 46, '1993-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 8, 'Ice', 'In the claustrophobic isolation of a remote outpost in Alaska, Mulder and Scully investigate the horrifying deaths of scientists.', 46, '1993-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 9, 'Space', 'Mulder and Scully are contacted by a communications specialist from NASA who shows them evidence of sabotage in the space programme.', 47, '1993-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 10, 'Fallen Angel', 'Mulder puts the future of the X-Files in jeopardy when he heads to a UFO crash site being rapidly covered up by the military. He is arrested, and while in jail he meets Max Fenig, a UFO nut whose NICAP group has followed Mulder''s work on the X-Files. When Mulder is released, Scully urges him to return to Washington to face his superiors and try to save his job, but Mulder finds out that Max is more than meets the eye and ignores Scully to try and save him instead.', 46, '1993-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 11, 'Eve', 'When two fathers on opposite sides of the country are inexplicably murdered at the exact same time in the exact same way, Mulder and Scully are called in to investigate. When they discover that the two fathers'' eight-year-old daughters are identical twins, they realize that something even stranger is going on.', 46, '1993-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 12, 'Fire', 'An old Oxford girlfriend of Mulder''s asks for his help on an international case concerning the unexplainable execution of several British dignitaries, and they encounter an assassin who can produce fire from his bare hands.', 46, '1993-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 13, 'Beyond the Sea', 'When death row inmate Luther Lee Boggs claims to be psychic and can lead Mulder to a serial killer in return for a lesser sentence of life in prison, Scully becomes an unwilling believer when Boggs tells her that she can communicate through him with her recently deceased father.', 46, '1994-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 14, 'Gender Bender', 'A series of sexually-oriented murders, which are identical except that the killer appears to be both male and female, draws Scully and Mulder to an Amish-type community of people called the Kindred.', 45, '1994-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 15, 'Lazarus', 'When FBI Agent Jack Willis and bank robber Warren Dupre are both shot at the same time during a robbery attempt, Dupre dies when Willis is brought back to life. When Willis rushes out of the hospital and begins acting strangely, Mulder concludes that Dupre has come back to life in Willis'' body.', 46, '1994-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 16, 'Young at Heart', 'Mulder becomes the target of someone from his past named John Barnett. He was a jewelry store robber with an itchy trigger finger that Mulder sent to prison when he first joined the Bureau. The only problem is that Barnett died four years ago.', 46, '1994-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 17, 'E.B.E.', 'Mulder and Scully receive information from Deep Throat about a UFO that was shot down over Iraq and has been secretly transported to the US. However, Deep Throat then intentionally misleads the agents to prevent them from discovering the truth.', 45, '1994-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 18, 'Miracle Man', 'A young man who has the power to heal people with his touch begins to question his gift when people start dying after he has supposedly healed them.', 46, '1994-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 19, 'Shapes', 'Mulder and Scully travel to a Native American reservation to investigate the death of a man who was mistaken for a wild animal and may have been the legendary Manitou, a man who can shape-shift into a beast.', 46, '1994-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 20, 'Darkness Falls', 'When a group of loggers in the Washington State National Forest disappear in the same way that another group disappeared 50 years ago, Mulder and Scully go along to investigate and find themselves trapped in a cabin surrounded by flesh eating insects that only attack at night.', 44, '1994-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 21, 'Tooms', 'Eugene Tooms is released from the sanitarium, and Mulder becomes personally involved to ensure that he is caught in the act of getting the last human liver he needs to go into hibernation for another 30 years.', 46, '1994-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 22, 'Born Again', 'After a detective and his former partner die in unexplained circumstances, the accidents are linked to a little girl who witnessed both deaths. Mulder believes that she may be the reincarnation of a policeman murdered by his colleagues.', 45, '1994-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 23, 'Roland', 'Mulder and Scully investigate the death of a scientist working on advanced propulsion technology. The mentally challenged janitor Roland, who has secretly been completing the scientist''s work, is the prime suspect.', 46, '1994-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 1), 24, 'The Erlenmeyer Flask', 'When Deep Throat points out a news story about a fugitive who apparently drowned, Mulder and Scully cannot see what makes the case special but follow it up anyway. With Deep Throat''s insistence, they discover evidence of a secret government project code-named Purity Control, which uses human test subjects and infects them with extraterrestrial DNA. However, the evidence and everyone who has seen it is quickly being eliminated.', 46, '1994-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 2, 'Season 2', 'The X-Files has been shut down and Mulder and Scully are separated. Scully finds herself teaching classes at the FBI Academy in Quantico, Virginia, while Mulder is assigned to surveillance duty. With Agent Alex Krycek as his new partner, and the mysterious X as his new source of information, Mulder struggles to keep his search for the truth alive. But ironically it is Scully who experiences the close encounter Mulder has longed for, taking a journey that will ultimately bring the two agents back together and forging a bond that will make them closer than ever before.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 1, 'Little Green Men', 'With the X-Files closed, Scully has been assigned as an instructor at the FBI Academy while Mulder is doing menial surveillance work. After meeting with Senator Matheson, one of his supporters in regards to the X-Files, Mulder disobeys orders and heads to an abandoned SETI site in Puerto Rico which has inexplicably reactivated itself and could provide proof of contact with extra-terrestrial life.', 46, '1994-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 2, 'The Host', 'A.D. Skinner sends Mulder to investigate a body which washed into the New Jersey sewer from the ocean. Mulder believes that the basic blue-collar assignment is punishment, but by Skinner''s own admission, what he discovers is a true X-File.', 46, '1994-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 3, 'Blood', 'When several violent deaths in a small farming community are connected by the destruction of digital devices, Mulder believes that people are being driven to kill by the use of subliminal messages in the digital readouts.', 46, '1994-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 4, 'Sleepless', 'Mulder reluctantly accepts a new partner, Agent Alex Krycek, and they investigate the deaths of several Green Beret soldiers who participated in a sleep deprivation experiment during the Vietnam war.', 45, '1994-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 5, 'Duane Barry (1)', 'Mulder is called to a hostage situation involving Duane Barry, a former FBI Agent who claims to be an alien abductee and wants to get back to the abduction site with someone who will be taken instead of him. Unfortunately, the someone he eventually chooses is Scully.', 46, '1994-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 6, 'Ascension (2)', 'When Mulder finds out that Scully was kidnapped by Duane Barry, he risks the wrath of his superiors and the annoyance of Agent Krycek in order to do whatever it takes to find her. Meanwhile, Krycek is found to be reporting Mulder''s activities to the Cigarette-Smoking Man.', 46, '1994-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 7, '3', 'Mulder, back on the X-Files but alone for the first time, investigates a series of vampire-like murders in Los Angeles and finds himself falling for the one woman that may be the prime suspect.', 46, '1994-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 8, 'One Breath', 'Scully mysteriously appears in a Washington hospital, alive but in a coma, and Mulder must fight to keep her alive in order to find out what happened to her and who did it to her. Meanwhile, Scully fights her own personal battle as she decides whether to stay or go on to the next world.', 46, '1994-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 9, 'Firewalker', 'Mulder and Scully, reunited at last, head for an active volcano under a geological study and find a deadly life form that can survive in the searing heat of the crater and is killing the scientists to avoid being discovered.', 46, '1994-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 10, 'Red Museum', 'While investigating the connection between the abduction of several teenagers and a rural religious cult, Mulder and Scully discover a secret test being performed on the children using the "Purity Control" alien DNA from ''The Erlenmeyer Flask'' which leads Mulder to "the crew-cut man", Deep Throat''s murderer.', 46, '1994-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 11, 'Excelsis Dei', 'Mulder and Scully uncover strange occurrences in an elderly care home when one of the nurses is attacked by an unseen force she claims to be one of the 90 year old residents.', 45, '1994-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 12, 'Aubrey', 'When a detective mysteriously uncovers the remains of an FBI agent who disappeared in the 1940s while investigating a similar murder case to one she is now on, Mulder and Scully believe that the original killer had passed his genetic trait of violence to his grandchild.', 46, '1995-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 13, 'Irresistible', 'A mortuary worker who gets his thrills from collecting hair and fingernails from the dead begins killing his soon-to-be collectibles himself and sets his seriously disturbed sights on Scully.', 46, '1995-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 14, 'Die Hand Die Verletzt', 'The ritualistic murder of a teenager in a small town gets Mulder and Scully caught up in a secret occult practice within the local school''s PTA and a substitute teacher with strange powers.', 46, '1995-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 15, 'Fresh Bones', 'While investigating several deaths and murders within a Haitian refugee camp, Mulder and Scully get caught in the middle of a secret war between the camp commander and a Voodoo priest.', 46, '1995-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 16, 'Colony (1)', 'After the obituaries of four identical men are e-mailed to Mulder, the agents are contacted by a shadowy CIA agent who tells them about a bounty hunter sent to wipe out the beginning of a colony of clones. Meanwhile Mulder is distracted by the sudden reappearance of his sister Samantha.', 45, '1995-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 17, 'End Game (2)', 'The alien bounty hunter kidnaps Scully and wants to trade her for Mulder''s sister, who is revealed to be a clone herself. After the trade goes badly and Mulder discovers the truth about Samantha, he tracks the bounty hunter to his ship buried in the arctic ice and demands the whereabouts of his real sister.', 46, '1995-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 18, 'Fearful Symmetry', 'In a small town in Idaho, a man is killed by what seems to be an invisible elephant. Mulder''s investigation into the local zoo, its owners and a local animal rights group uncovers evidence of insidious alien experiments.', 45, '1995-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 19, 'Død Kalm', 'When half the crew of a Navy ship abandon their boat in a life raft and are rescued 18 hours later looking about 60 years older than they should be, Mulder suggests that the ship is caught in a time field which is speeding up their aging.', 46, '1995-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 20, 'Humbug', 'Mulder and Scully travel to Gibsonton, Florida, a town built and populated by circus and sideshow performers to investigate the death of Jerald Glazebrook, The Alligator Man. While searching for leads on the killer, the agents come across many bizarre characters including the local sheriff who was once known as Jim Jim, the Dog-Faced Boy.', 46, '1995-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 21, 'The Calusari', 'The agents investigate when a young boy''s family is plagued by a series of tragic accidents.', 45, '1995-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 22, 'F. Emasculata', 'When a plague-like illness kills ten men inside a maximum security prison, Scully tries to get into the quarantine site and discover the cause and origin of the contagion, while Mulder and a group of US Marshals track two escapees who may be infected.', 46, '1995-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 23, 'Soft Light', 'An experiment in dark matter accidentally turns a scientist''s shadow into a deadly weapon that can unzip a person''s molecules if they are touched by it.', 45, '1995-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 24, 'Our Town', 'After several disappearances in a small town, Mulder and Scully investigate and find hundreds of human bones in the river. They discover that the man behind the town''s main source of wealth, a chicken processing plant, has found a way to prolong his life through cannibalism.', 45, '1995-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 2), 25, 'Anasazi (1)', 'Mulder receives an encrypted computer disk containing the defense department''s top secret files on extraterrestrial life and becomes a target. Scully takes him to a Navajo family that unearthed a buried secret to decipher the disk.', 46, '1995-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 3, 'Season 3', 'Mulder is missing and assumed dead . . . although Scully experiences a vision in which he is still alive. Yet even as they are reunited, each must deal with an additional personal loss, tragedies that ultimately serve to strengthen their connection to each other. And they soon find themselves depending on that strength as familiar foes resurface and preconceived notions are shattered.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 1, 'The Blessing Way (2)', 'Scully finds her career with the FBI in jeopardy as Mulder is still missing and the Cigarette Smoking Man is pursuing the stolen files. The Navajo elders find Mulder''s body in a cave and perform an ancient ceremony to call the spirit back to the empty vessel.', 46, '1995-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 2, 'Paper Clip (3)', 'A.D. Skinner and Scully are at a standoff when Mulder bursts in and discovers that Skinner has the digital tape. Reunited, Mulder and Scully travel to a secret vault inside a mine and find an elaborate filing system of medical records which reveals that Mulder''s sister may not have been the first choice for abduction. Meanwhile, Skinner deals with the Cigarette-Smoking Man for their safety.', 46, '1995-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 3, 'D.P.O.', 'Mulder and Scully investigate a series of human and cattle deaths by lightning and are led to a teenage boy who is the only survivor out of five people recently hit by lightning strikes.', 45, '1995-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 4, 'Clyde Bruckman''s Final Repose', 'In the midst of a psychic sideshow while on a murder case, Mulder and Scully enlist the help of a man who may have a true psychic ability to foresee how people will die to help the agents catch a man killing fortune tellers.', 46, '1995-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 5, 'The List', 'Nobody takes much notice when a death row inmate vows on the electric chair to come back from the dead and kill five men who have wronged him during his time in prison, until a guard is mysteriously murdered in the former inmate''s cell.', 46, '1995-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 6, '2Shy', 'A man with a genetic abnormality, who must prey on overweight women in order to suck the fatty tissue from their bodies, begins to meet his victims through internet chat rooms.', 46, '1995-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 7, 'The Walk', 'After a suicide attempt and multiple murders at a military hospital, Mulder and Scully meet a quadruple amputee who has gained the power of astral projection and is taking out his personal frustrations on his commanding officers.', 46, '1995-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 8, 'Oubliette', 'Mulder seeks the help of a woman who he believes has a special connection with a young girl who has recently been kidnapped by the same man who held her captive many years earlier.', 46, '1995-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 9, 'Nisei (1)', 'An investigation into a video of an alien autopsy puts Mulder and Scully in the middle of a conspiracy involving WWII Japanese scientists brought to America to continue their experiments which may shed light on Scully''s abduction.', 45, '1995-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 10, '731 (2)', 'Mulder is trapped inside a train car which contains a suspected alien-human hybrid and also a bomb, while Scully pursues the truth about her abduction and the mystery behind the implant in her neck.', 46, '1995-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 11, 'Revelations', 'Mulder and Scully swap roles as they pursue a man killing priests that claim to have the wounds of Christ. The agents find and must protect a young boy who may be a real stigmatic. While Scully''s faith draws her close to the boy, Mulder is convinced of another explanation.', 45, '1995-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 12, 'War of the Coprophages', 'Widespread panic is caused in a small community after numerous deaths are linked to killer cockroaches, and a government agricultural agency is discovered to have set up a secret experiment involving insects.', 45, '1996-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 13, 'Syzygy', 'A rare planetary alignment causes strange behavior in the residents of a small town, but particularly in two teenage girls who were born at the exact same moment on that date. While investigating the strange occurrences Mulder''s interest in the local female detective makes Scully jealous.', 45, '1996-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 14, 'Grotesque', 'A serial killer is captured after a three year manhunt, and he claims an evil spirit is responsible for the crimes. When the killings continue as he sits in jail, Mulder''s battle with a former colleague gets more heated when he suggests that something more paranormal may be involved.', 45, '1996-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 15, 'Piper Maru (1)', 'A French salvage ship searching for a lost WWII fighter plane unknowingly surfaces an alien which appears in the form of black oil and has the ability to jump hosts. Mulder heads to Hong Kong to investigate the salvage broker who sold the information to the French and he encounters Krycek, who has been selling information from the MJ documents. As Mulder prepares to take Krycek back to the US, the alien makes its way to Hong Kong and takes control of Krycek.', 45, '1996-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 16, 'Apocrypha (2)', 'Mulder pursues Krycek (unaware of  the alien that has taken over his body) to get back the DAT tape containing the MJ documents. Meanwhile, the shooting of A.D. Skinner uncovers evidence that could lead Scully to her sister''s murderer.', 45, '1996-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 17, 'Pusher', 'Mulder and Scully are asked to help in a case involving Robert Patrick Modell, a murderer possessing the psychic ability to force his will onto people. Due to a brain tumor that is slowly killing him, he is searching for a "worthy adversary" and forces Mulder into a battle of mind over matter.', 45, '1996-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 18, 'Teso Dos Bichos', 'The unearthing of an ancient Ecuadorian Amaru urn and its removal to America despite protests leads to a series of deaths linked to a shaman spirit released by the urn.', 44, '1996-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 19, 'Hell Money', 'Mulder, Scully and a local Chinese American cop investigate deaths of several Chinese men found to be missing vital internal organs. The clues lead them to a deadly secret lottery run by the Triads in San Francisco''s Chinatown district. The game is free to play but losing will cost you more than an arm and a leg.', 45, '1996-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 20, 'Jose Chung''s "From Outer Space"', 'A alien abduction of two teenagers with endless versions of the same story prompts a science-fiction novelist to to write a book about the incident; however, nobody involved with the investigation can tell him the full story with any accuracy.', 45, '1996-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 21, 'Avatar', 'During a one-night-stand in the midst of his divorce, A.D. Skinner becomes a murder suspect, and Mulder and Scully return the many favors that he has done for them by analyzing evidence that someone doesn''t want uncovered to prove his innocence.', 45, '1996-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 22, 'Quagmire', 'Mulder and Scully investigate a series of disappearances and attacks around a lake where Mulder believes that the local legend about a lake monster may be all too real. Frustrated Scully insightfully confronts Mulder about the futility of their work on the X-Files.', 43, '1996-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 23, 'Wetwired', 'Mulder and Scully investigate a series of murders linked to a mysterious device that alters television signals causing paranoid hallucinations. One of them falls victim to it.', 45, '1996-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 3), 24, 'Talitha Cumi (1)', 'After his mother suffers a stroke under strange circumstances, Mulder searches for a strange, benevolent alien man that possesses miraculous healing powers. With the help from Mr. X, he learns about the involvement of the Cigarette-Smoking Man and uncovers some secrets kept by his parents.', 45, '1996-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 4, 'Season 4', 'The prophetic words of the alien Bounty Hunter resonate throughout the fourth season, beginning with the near death of Mulder''s mother and the murder of the mysterious X. Even the return of Alex Krycek and the alien black oil are overshadowed by Scully''s cancer. Then the tragic reappearance of Max Fenig leads to the death of a fellow FBI agent. Yet even as these events strengthen Mulder''s belief in a growing conspiracy, a startling truth revealed to Scully plunges him into a crisis of faith which could prove his ultimate undoing.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 1, 'Herrenvolk (2)', 'With his mother on a deathbed and the alien bounty hunter in pursuit, Mulder decides to put Jeremiah Smith, the alien healer, in mortal danger for a chance to finally uncover the whole truth behind the alien conspiracy. Meanwhile, the Syndicate suspects that they have a traitor in their midst and set up a trap.', 45, '1996-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 2, 'Home', 'A baby is found buried alive in shallow ground and appears to have birth defects resulting from generations of inbreeding, leading Mulder and Scully to a reclusive family who have a history of inbred children.', 45, '1996-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 3, 'Teliko', 'After several African-American men are killed and the color is drained from their skin, Mulder learns about the Teliko, an African folktale about a creature who must suck the pigmentation from a persons body in order to survive.', 44, '1996-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 4, 'Unruhe', 'Several kidnappings of young women linked by distorted photographs lead Mulder and Scully to a man who can imprint his darkest fantasies onto undeveloped film and is trying to save the women from the "howlers".', 45, '1996-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 5, 'The Field Where I Died', 'After an FBI raid on a doomsday cult called the "Temple of the Seven Stars", Mulder meets Melissa, a cultist who claims to have known him in a previous life during the American Civil War. Scully believes the woman is a delusional schizophrenic, but Mulder allows himself to be drawn into her fantasies.', 45, '1996-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 6, 'Sanguinarium', 'After a doctor loses control and kills a patient on the operating table, Scully hypothesizes that it''s linked to work-related stress, while Mulder is convinced of a more sinister reason. After he finds a link between the victim and the four witches Sabbaths, he suspects that a nurse may be practicing witchcraft.', 45, '1996-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 7, 'Musings of a Cigarette Smoking Man', 'The Lone Gunmen reveal the (possibly fake) secret history of the Cigarette Smoking Man to Mulder and Scully; from a young captain in the U.S. Army recruited to assassinate President Kennedy, to becoming the mysterious man in the shadows at the height of a global conspiracy.', 45, '1996-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 8, 'Tunguska (1)', 'Mulder is given a tip about potentially dangerous paramilitary operations on the U.S. soil but during the sting operation is surprised to find out the identity of his mysterious informant - it turns out to be Alex Krycek. Suspicious about his true motives, Mulder reluctantly follows the information provided by Krycek. However, soon he discovers a much bigger conspiracy which takes him to a gulag in Tunguska, Russia where prisoners are being used for experiments involving a substance of alien origin.', 45, '1996-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 9, 'Terma (2)', 'While imprisoned in Russia and infected with the Black Cancer, Mulder learns that Krycek is working with the men responsible and everything has been a setup from the start, while Scully and Skinner are called to a suspicious Senate hearing where the only question is the whereabouts of Agent Mulder.', 45, '1996-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 10, 'Paper Hearts', 'Mulder''s dreams help him in finding the body of a little girl which reopens one of his old cases in the Violent Crimes Unit. This leads him to believe that the killer he captured had more victims and that Mulder''s sister Samantha may have been one of them.', 45, '1996-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 11, 'El Mundo Gira', 'After a strange yellow rain kills a migrant girl, her family believes that a mythical creature el chupacabra was the cause and that it has manifested itself inside her fiancé''s brother, who has since disappeared.', 45, '1997-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 12, 'Leonard Betts', 'After the body of a decapitated EMT disappears from the morgue and an identical man starts work at the same hospital, Mulder believes that the man has the ability to regrow parts of his body, including his head. The agents soon discover that Betts'' body is riddled with cancer and he is able to live in that condition but needs to feed on cancerous tumors to keep up his strength.', 45, '1997-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 13, 'Never Again', 'While Mulder is forced to take a vacation he leaves Scully with an assignment to keep her busy until he returns. However, she decides to start living and goes on a date with a man who believes that his tattoo talks to him and is telling him to stay away from other women.', 45, '1997-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 14, 'Memento Mori', 'Scully''s recent failing health is revealed to be an inoperable cancer in her skull, which appears to be common among abductees and she attempts to come to terms with her condition. Meanwhile, Mulder and the Lone Gunmen break into a high-security research lab to find the cure that could save her life.', 45, '1997-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 15, 'Kaddish', 'After a Jewish man is murdered in a Jewish community, his killers are murdered, too. Mulder and Scully have to determine whether someone is exacting vengeance or larger forces are at work.', 45, '1997-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 16, 'Unrequited', 'When a U.S. military general is inexplicably murdered in the back of his limousine, a paramilitary group is suspected. They believe it was a soldier who they liberated from a Vietnam POW camp and is plotting to kill certain corrupt military figures.', 43, '1997-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 17, 'Tempus Fugit (1)', 'While celebrating Scully''s 33rd birthday, a strange woman informs Mulder that NICAP member Max Fenig (see Fallen Angel) has recently died in a plane crash. After a visit to the crash site and finding Max''s body with radiation burns on it, Mulder suggests that the plane was intercepted by a UFO and is rapidly being covered up by the military.', 45, '1997-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 18, 'Max (2)', 'Mulder is arrested for investigating the plane crash and interfering with a military operation, while Scully is caught in the attempted assassination of Corporal Frish.', 45, '1997-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 19, 'Synchrony', 'A case involving a strange old man warning two scientists of events in the immediate future which come to pass (and the use of their experimental flash-freezing compound that does not exist yet) has Mulder believing that one of the scientists has come from the future to stop his own scientific breakthrough from becoming reality.', 44, '1997-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 20, 'Small Potatoes', 'Five babies in the same town are all born with tails and the local OB-GYN is blamed for tampering with fertilized eggs. However, Mulder discovers the culprit to be a simple man with a genetic deformity who may have the ability to alter his appearance.', 45, '1997-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 21, 'Zero Sum', 'After a swarm of bees mysteriously kill a postal worker in an enclosed restroom, Assistant Director Skinner covers it up by destroying the evidence. In order to complete the task he poses as Agent Mulder, however his deception backfires. When Mulder finds out and confronts him, Skinner reveals that he is working for the Cigarette-Smoking Man in order to obtain a possible cure for Scully''s cancer.', 45, '1997-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 22, 'Elegy', 'After a man sees a woman trapped inside a bowling alley pin setter, he goes for help and finds police standing next to a body of the same woman. Mulder and Scully join the investigation and follow up this lead which the police won''t bother with, and they are led to a mentally challenged man who works at the bowling alley.', 45, '1997-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 23, 'Demons', 'Covered in blood and suffering from amnesia, Mulder pieces together the events of the last few days, but the trail leads to a double murder that appears to have been committed with Mulder''s weapon.', 45, '1997-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 4), 24, 'Gethsemane (1)', 'Mulder fights to prove that a discovery frozen in the mountains of Canada is an irrefutable evidence of alien life, but his quest for the truth only leads to more lies and an unthinkable conclusion.', 45, '1997-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 5, 'Season 5', 'Even as Scully’s genetically altered DNA brings her closer to the brink of death, government agent Michael Kritschgau helps Mulder in the search for a cure, partly to atone for his own involvement with perpetrating the alien hoax. Scully’s DNA comes into play once again when she discovers she is the mother of a little girl named Emily, an incident that could only be related to her abduction years earlier. But in the end it is a young boy named Gibson Praise whose body may contain genetic proof of man’s relationship to an alien race — and who may hold the key to unlocking the mysteries of the X-Files.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 1, 'Redux (2)', 'Scully helps Mulder fake his own death in order for him to go undetected through the Department of Defence and find out the answers to his new questions about the government hoax concerning the existence of extraterrestrial life. Meanwhile, at a joint FBI/DOD inquiry, Scully''s attempt to drive out the Conspiracy''s informant is halted as her cancer takes a bad turn.', 45, '1997-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 2, 'Redux II (3)', 'The Cigarette-Smoking Man helps Mulder to obtain Scully''s cure and also lets him see his real sister who doesn''t turn out to be as happy to see Mulder as he would''ve liked. In return for this, the Cigarette-Smoking Man asks that Mulder quit the FBI and work for him in the Syndicate where he could have power and respect which Mulder turns down, deciding to stay on the side of justice. While Scully''s cure appears to have worked, the Cigarette-Smoking Man faces his own enemies and disappears, presumed dead.', 47, '1997-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 3, 'Unusual Suspects', 'Set in 1989, the story of the founding of The Lone Gunmen is finally told as we see how a straight-laced federal employee, a sex mad AV expert, and a nerdy computer hacker meet Susanne Modeski, a strange woman with evidence of a government conspiracy. When their plan to expose the conspiracy fails and Susanne is captured by a group of men-in-black, led by none other than X, they soon become a paranoid group of government watchdogs.', 45, '1997-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 4, 'Detour', 'While on their way to an FBI group communication seminar, Mulder and Scully manage to escape when they come across a situation in the Florida forest area where three men have recently disappeared.', 45, '1997-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 5, 'The Post-Modern Prometheus', 'Filmed in glorious black and white with a comic book feel to it, this is a modern retelling of Frankenstein as Mulder and Scully get caught up in a town where the residents live on Jerry Springer episodes and fear a two-faced monster who has been impregnating the women.', 47, '1997-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 6, 'Christmas Carol (1)', 'On her Christmas vacation with her brother''s family, Scully receives a mysterious phone call from a familiar voice who says, "She needs your help. Go to her." The phone call leads Scully to a murder case where the victim''s 3-year-old adopted daughter bears an uncanny likeness to her sister, Melissa, at that age. The emotional roller coaster that follows has Scully believing that her sister had a baby during a period when she traveled the country and she tries to adopt the child, knowing that caring for the little girl would change her life.', 46, '1997-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 7, 'Emily (2)', 'DNA testing on Emily reveals that she is actually Scully''s daughter and Mulder comes to assist her. While Mulder is looking for any information about where and how the girl was born, Scully searches for a cure to Emily''s strange illness.', 46, '1997-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 8, 'Kitsunegari', 'Pusher returns as Robert Patrick Modell escapes from the mental hospital and the FBI promptly organizes a manhunt, assuming that he will continue where he left off. But is he really trying to get revenge on Mulder, or does he want to warn him of another evil?', 46, '1998-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 9, 'Schizogeny', 'A therapist working with children from abusive families is found to be implanting them with the memories of her own abuse suffered at the hands of her late father, when one of her patients tries to kill his stepfather.', 46, '1998-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 10, 'Chinga', 'Master of Horror Stephen King''s first effort at an X-File sees Scully''s well deserved vacation going terribly wrong and landing her in a small Maine town where one of the residents is believed to be a witch, and her autistic daughter''s doll has frighteningly evil powers.', 45, '1998-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 11, 'Kill Switch', 'A super-intelligent virus program is let loose on the internet and begins to grow and expand by itself, eventually killing its creator when he tries to eradicate it.', 46, '1998-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 12, 'Bad Blood', 'After Mulder chases down and kills a young man who he believes to be a vampire, the agents return to DC aware of the mistake they just made. Faced with a lawsuit from the family of the man, they recount each of their sides to the story leading up to the event. In the extremely humorous stories that follow we see how Scully and Mulder both perceive each other.', 46, '1998-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 13, 'Patient X (1)', 'Mulder and Scully meet Cassandra Spender, a woman who claims to be a multiple abductee and wants to deliver a positive message about the aliens. Mulder''s new found disbelief in extraterrestrial activity is enhanced while Scully forms a special bond with the woman. A series of group attacks against abductees take place and the shadowy Syndicate believes that a rebel alien resistance is attempting to destroy all their work.', 46, '1998-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 14, 'The Red and the Black (2)', 'After the gathering at the abduction site where everyone is killed by the rebel bounty hunters, Cassandra Spender disappears and Mulder is blamed by her son, Jeffrey, who is an up-and-coming FBI agent. Meanwhile, the Syndicate is continuing their tests to create a vaccine for the Black Cancer and Marita Covarrubias becomes an unwilling test subject.', 46, '1998-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 15, 'Travelers', 'In 1990 Agent Fox Mulder visits an aging FBI Agent named Arthur Dales. He listens to a story of the agents assigned to a would-be X-File in the Cold War era of the 1950''s and how Mulder''s father was connected to a series of strange deaths.', 46, '1998-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 16, 'Mind’s Eye', 'Mulder and Scully try to get answers out of a stubborn blind woman found at a murder scene who may have the ability to look through the killer''s eyes in her mind.', 46, '1998-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 17, 'All Souls', 'Scully faces her Catholic faith and the loss of her daughter Emily when she is asked to help a family whose adopted daughter was found dead in a position that looked like she was struck down by God himself.', 46, '1998-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 18, 'The Pine Bluff Variant', 'Scully fears that Mulder has gone to the other side when she sees him assisting a federal suspect escape custody. In truth he has infiltrated a terrorist group testing a deadly biological weapon that can eat through a person''s flesh.', 46, '1998-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 19, 'Folie à Deux', 'Mulder is held hostage inside an office where a man claims his boss is a monster and has clouded all their minds while he turns them into zombies one by one, which is disbelieved until Mulder opens his mind and allows himself to see it too.', 46, '1998-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 5), 20, 'The End', 'The Cigarette-Smoking Man returns as Mulder investigates the attempted assassination of a young boy with psychic powers who may be the proof that he has looked for all his life.', 47, '1998-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 6, 'Season 6', 'When a terrorist bomb destroys a building in Dallas, Texas FBI agents Fox Mulder and Dana Scully are drawn into a dangerous conspiracy surpassing anything they’ve ever encountered. With the dubious assistance of a paranoid doctor, Mulder and Scully risk their careers and their lives to hunt down a deadly virus which may be extraterrestrial in origin — and could destroy all life on Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 1, 'The Beginning', 'Mulder is less than thrilled when an Office of Professional Conduct board refuses to reassign him and Scully to The X-Files and even more so when he learns that Agent Spender and Agent Fowley have become their successors. When Gibson Praise reappears and comes to them for help, Mulder and Scully attempt to continue their quest undercover despite having fewer friends and less access and protection than ever before.', 46, '1998-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 2, 'Drive', 'Mulder is trapped in a car with a man who has developed a serious ear condition which can only be suppressed by driving west at high speeds. As Scully tries to find the cause and a cure for the problem, Mulder and the man get closer and closer to the ocean.', 46, '1998-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 3, 'Triangle', 'Mulder goes to the Bermuda Triangle when he learns that the Queen Anne, a British luxury liner which disappeared during WWII, has reappeared in the middle of the Sargasso Sea. Mulder''s boat is wrecked and after floating in the water, he is hauled aboard the ship which has just been hijacked by the Nazis searching for the man who will build the atom bomb.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 4, 'Dreamland (1)', 'While being detained near the famed "Dreamland" Area 51, a strange craft flies overhead and Mulder swaps bodies with an Area 51 "Man-in-Black". While the other agent has fun in Mulder''s body, Mulder himself finds it difficult to fit into someone else''s life, especially a shadowy one. Mulder contacts Scully about the body swap and tries to get her the flight data recorder from the UFO test flight, but his alter ego uses Mulder''s FBI persona to have him arrested.', 46, '1998-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 5, 'Dreamland II (2)', 'Mulder is thrown in jail at the Area 51 compound but is released when it is discovered that the flight data recorder he stole was a fake. Scully comes to her senses and realizes that the Mulder she sees isn''t who he really is and heads back to Nevada to help the real Mulder. Meanwhile, the mechanism that caused the body swap is rapidly snapping back, undoing everything in its wake, and Mulder and his alter ego must race to put themselves back where they belong.', 46, '1998-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 6, 'How the Ghosts Stole Christmas', 'Mulder talks Scully into investigating a haunted house on Christmas Eve where several couples have met their fate on that very night. While there, they encounter endless tricks and traps set by a ghostly couple who originally made a lovers suicide pact in the house. The ghosts try to convince Mulder and Scully to kill each other.', 45, '1998-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 7, 'Terms of Endearment', 'After a scan of a couple''s unborn child is found to have strange growths protruding from the head and back, the fetus is taken from inside the mother by a demon creature while she is asleep. Mulder heads to investigate after Agent Spender dismisses the claims, and discovers that the father is actually a demon who wants to have a normal child.', 46, '1999-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 8, 'The Rain King', 'Strange weather phenomena in a small town leads Mulder to believe that a weatherman''s deep emotions and unspoken love toward his workmate are becoming real in the form of snow and tornadoes.', 46, '1999-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 9, 'S.R. 819', 'Mulder and Scully have 24 hours to save A.D. Skinner from being killed by a biologically engineered disease. The disease appears to be created by a shadowy government organization, but in order to save Skinner''s life they must determine who wants him dead and why. With Skinner''s condition worsening, Mulder seeks assistance from Senator Matheson, who he hopes can provide some answers and help him to find a cure.', 46, '1999-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 10, 'Tithonus', 'Assistant Director Kersh tries to tear Scully and Mulder apart when he partners Scully with a New York agent investigating Alfred Fellig, a freelance police photographer who conveniently shows up to document the scene of a death as soon as it happens.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 11, 'Two Fathers (1)', 'While the Cigarette-Smoking Man recites to an unseen listener everything about the work of the Syndicate involving a global conspiracy in cooperation with an alien species, Cassandra Spender reappears and is pursued by the scientists who would rather kill her than keep her alive. Cassandra runs to Mulder''s apartment and demands that he shoot her because she is the culmination of 50 years work - a living alien/human hybrid - and colonization will begin if the aliens find out about her.', 44, '1999-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 12, 'One Son (2)', 'The Cigarette-Smoking Man reveals all the government secrets from the past 50 years in order for his son, Jeffery Spender, to join him in his work. Mulder learns that the final stage of the conspiracy will soon begin with the hybridization of the Syndicate members, and he must stop it from happening. Agent Spender deceives his father and arranges for Mulder and Scully to be reassigned to the X-Files, which doesn''t sit too well with the Cigarette-Smoking Man.', 45, '1999-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 13, 'Agua Mala', 'Arthur Dales summons Mulder and Scully to his holiday home in Florida where he is concerned over the disappearance of his neighbors. Despite the raging hurricane, Mulder and Scully head out to investigate and discover several strange deaths caused by an octopus-like sea creature that swam in through the overflowing sewer system.', 45, '1999-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 14, 'Monday', 'A woman is forced to relive the same day over and over as she tries to prevent Mulder and Scully from being killed by her boyfriend during a bank robbery attempt. As the events restart again and again, Mulder''s sense of Deja-vu grows stronger.', 46, '1999-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 15, 'Arcadia', 'On their first official case back on the X-Files, Mulder and Scully go undercover as a married couple at a prestigious planned community where several residents have recently disappeared after failing to comply with the rules and regulations.', 46, '1999-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 16, 'Alpha', 'A mysterious dog thought to be the last of a rare Asian breed is responsible for several murders which Mulder and Scully are investigating. Now the agents have to find a way to stop the dog before it kills again.', 46, '1999-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 17, 'Trevor', 'After a tornado rips through a prison camp, one of the inmates disappears from solitary confinement and the prison warden is killed. As Mulder and Scully track him, he appears to have the power to pass through solid matter while changing its composition.', 46, '1999-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 18, 'Milagro', 'A writer living next to Mulder becomes obsessed with Scully and confesses to her that he is using her for a character in his novel. Scully finds herself strangely drawn to him even though he is now the prime suspect in the murder case that she and Mulder are investigating.', 46, '1999-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 19, 'The Unnatural', 'Mulder meets with Agent Arthur Dales'' brother (also named Arthur) and is told a tale of a talented negro baseball player from Roswell, New Mexico in the 1940''s who may have been an alien that ran away from his colony because of his love for the game.', 46, '1999-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 20, 'Three of a Kind', 'While on a stakeout of a Government Defense Convention in Las Vegas, The Lone Gunmen are reunited with Susanne Modeski, the mysterious woman who disappeared ten years earlier when they first met Agent Mulder.', 46, '1999-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 21, 'Field Trip', 'When the bodies of a couple who have been missing for less than a week are discovered to have been reduced to bone, Mulder suggests that recent paranormal phenomena in the area may have caused the accelerated decomposition.', 46, '1999-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 6), 22, 'Biogenesis (1)', 'Two scientists confer about each of their metal objects that were found in Africa and they theorize that the objects are pieces of a puzzle which could be undeniable proof that human, plant, and animal life did not originate on this planet. When one of the scientists is killed and the objects are stolen, the agents investigate and Mulder begins to experience severe neurological pain caused by the objects.', 46, '1999-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 7, 'Season 7', 'As Mulder lies in a neurological unit, his brain under attack by a deadly onslaught of electrical impulses, Scully struggles to decipher strange symbols covering a spacecraft found submerged off West Africa''s Ivory Coast. But the connection between these two phenomena is just the first of many challenges the agents are destined to confront. For they are about to enter a time of closure and a time of new beginnings. For Mulder there''s the death of his mother and Diana Fowley, and the end of his search for his abducted sister, Samantha. For Scully it is a time to face her own personal demons, among them the return of death fetishist Donnie Pfaster. Yet just as Scully faces the ultimate new beginning, the ultimate horror occurs — the abduction of Mulder.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 1, 'The Sixth Extinction (2)', 'While Scully travels to Africa to piece together the meaning of the symbols on the spaceship beached on the Ivory Coast, Mulder is imprisoned by his own frenetic brain activity. He manages to get a message to Skinner who finds Kritschgau, and together they try to understand what is happening to Mulder before it is too late.', 45, '1999-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 2, 'The Sixth Extinction II: Amor Fati (3)', 'Scully frantically searches for a way to help her ailing partner without having anyone to turn to for help, while a catatonic Mulder''s dreams lead him away from his mission and the X-Files to a place which he believes is a better life.', 45, '1999-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 3, 'Hungry', 'A monster who feeds on human brain matter tries to lead a normal life, but he soon cannot control his feelings of hunger.', 45, '1999-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 4, 'Millennium', 'As the year 2000 draws closer, the agents are up against a man from the Millennium Group who believes that he can bring about the end of the world on the 31st of December if he resurrects four former members from the dead. To gain more insight into the group and its practices, Mulder and Scully enlist criminal profiler Frank Black to assist them in the investigation.', 45, '1999-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 5, 'Rush', 'A young man who has gained the ability to move faster than the eye can see begins to use his new power to kill his enemies, including the local sheriff who happens to be his father.', 45, '1999-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 6, 'The Goldberg Variation', 'Mulder and Scully get caught in a real-life Rube Goldberg device when they meet Henry Weems, who just may be the luckiest man on Earth - except everyone around him doesn''t seem to be that lucky.', 45, '1999-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 7, 'Orison', 'Reverend Orison hopes to save Donnie Pfaster''s soul by helping him break out of prison, but Donnie immediately plans to go after the victim that once escaped him... Scully.', 45, '2000-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 8, 'The Amazing Maleeni', 'When a small-time magician performs a trick where it appears that he turns his head all the way around but is then found in his van dead with his head neatly sawed off, Mulder and Scully suspect he was murdered and get caught up in an intricate scheme planned by two magicians trying to rob a bank.', 45, '2000-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 9, 'Signs and Wonders', 'Snakes are killing the unrighteous, but Mulder and Scully doubt that this is a case of divine intervention.', 45, '2000-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 10, 'Sein Und Zeit (1)', 'A young girl inexplicably disappears from her home, and Mulder requests the case even though it is a full FBI matter, not just an X-File. When Mulder takes some outrageous leaps to convince the girl''s parents that she will be found, Scully fears that Mulder is becoming too personally involved with the case because of his sister''s abduction.', 45, '2000-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 11, 'Closure (2)', 'After arresting the murderer of Amber-Lynn LaPierre and discovering a mass grave site containing the bodies of dozens of missing children, a man comes to Mulder and claims to have had visions of other victims who aren''t buried at the site. Despite Scully''s objections, he takes Mulder on a journey which reveals what truly happened to his sister.', 45, '2000-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 12, 'X-Cops', 'A Los Angeles police officer who is being filmed for the show COPS is attacked by a strange monster and Mulder and Scully are investigating the case. Scully is wary of having their faces put on national television but Mulder welcomes the publicity.', 45, '2000-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 13, 'First Person Shooter', 'The Lone Gunmen call Mulder and Scully to a virtual reality development lab where they learn that one of the program testers was killed inside the computer generated game environment by the digital image of a woman. Needing to get his yah-yah''s, Mulder enters the game to fight the woman, but Scully must step in to save him.', 45, '2000-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 14, 'Theef', 'Mulder and Scully suspect that hexcraft is the source of threats against a doctor''s family.', 45, '2000-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 15, 'En Ami', 'The Cigarette-Smoking Man offers to show Scully the cure for all diseases if she travels with him, but on one condition:  Mulder must not know about her trip.', 45, '2000-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 16, 'Chimera', 'As Mulder investigates a missing person case with a key feature being a menacing raven, he learns to enjoy the creature comforts of a well-tended home while Scully must tough it out on an uncomfortable stakeout.', 45, '2000-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 17, 'all things', 'A series of coincidences leads Scully to a married man she had an affair with during medical school but left him to protect his family.', 45, '2000-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 18, 'Brand X', 'While protecting a man due to testify against the Morley cigarette company, Skinner is horrified when the witness dies mysteriously. What the agents soon discover is that a new brand of cigarette has a dangerous secret.', 45, '2000-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 19, 'Hollywood A.D.', 'Mulder and Scully watch a movie with themselves as characters and are thoroughly disgusted at how they and their case are portrayed on the big screen. They recount how 18 months earlier they were followed around by a Hollywood producer while investigating a case concerning The Lazarus Bowl - a mythical piece of pottery reputed to have inscribed on it the words that Jesus Christ spoke when he raised Lazarus from the dead.', 45, '2000-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 20, 'Fight Club', 'Mulder and Scully cross paths with two women who are identical and have followed each other across 17 states in the last three years, causing chaos and mayhem wherever they are.', 45, '2000-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 21, 'Je Souhaite', 'Mulder and Scully discover a genie in a rug who, after 500 years of granting wishes, has come to the conclusion that people are still as greedy and self-centered as they always have been, and she begins to corrupt the wishes she grants if they are not specific enough.', 45, '2000-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 7), 22, 'Requiem', 'Mulder and Scully return to the town of their first X-Files investigation where a UFO has crashed in the forest. The Cigarette-Smoking Man arranges for Krycek to be released from prison in order for him to make contact with the aliens and begin rebuilding the "Project", while Scully''s health appears to be taking a turn.', 45, '2000-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 8, 'Season 8', 'After Mulder’s disappearance, Scully returns to FBI headquarters to find Special Agent John Doggett heading up a FBI manhunt for her partner. Knowing that type of search will prove futile, Scully and Skinner turn to the Lone Gunmen in hopes of uncovering information about additional UFO activity around the time of Mulder’s disappearance. Although such information leads them to Gibson Praise, the man with Gibson, a man who appears to be Mulder, is in fact an alien bounty hunter. Finally realizing that Mulder will not be found so easily, Agent Doggett is officially assigned to the X-Files. Now, after all she has been through with Mulder, it is Scully who is “the believer” and who must find a way to work with “the skeptic,” John Doggett.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 1, 'Within (1)', 'Newly appointed Deputy Director Kersh organizes a manhunt for Mulder and assigns Agent John Doggett to head the team. Scully and Skinner go along with the investigation but are warned by Kersh that they will be fired if anything is said about aliens. Scully, along with the Lone Gunmen, surmise that the Bounty Hunter is trying to erase all evidence of abductions, and they realize that he may be going after Gibson Praise, who is now living at a school in Arizona. Agent Doggett comes to the same conclusion and his team race Scully and Skinner to the school where they find Mulder trying to kidnap Gibson.', 45, '2000-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 2, 'Without (2)', 'As the search for Mulder intensifies in the Arizona desert, Gibson Praise leads Scully to believe that she is truly closer to her target. Meanwhile, A.D. Kersh informs Agent Doggett that he has been assigned as Mulder''s successor on the X-Files.', 45, '2000-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 3, 'Patience', 'While tackling his first X-File case about a series of gruesome murders surrounding a bat-like creature, Doggett quickly learns that his investigative techniques are somewhat dissimilar to Scully''s.', 45, '2000-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 4, 'Roadrunners', 'Scully evades Doggett''s help in investigating a vicious murder in a remote area of Utah, and she is trapped in the small town by a religious cult that believe a slug-like creature is the second coming of God who needs a human host to survive.', 45, '2000-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 5, 'Invocation', 'In 1990 a little boy inexplicably disappeared from his crowded school playground and was never seen again until now, ten years later, and he hasn''t aged a day.', 45, '2000-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 6, 'Redrum', 'A prominent lawyer wakes to find himself in jail and about to be prosecuted for the murder of his wife. He has no memory of this event however, and when the days begin to regress backward towards the murder, he realizes that he has been given a second chance.', 45, '2000-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 7, 'Via Negativa', 'Working without Scully''s input, Doggett and Skinner try to stop the mysterious murder spree of a drug-induced religious cult leader, and it becomes clear that the man can enter the dreams of the people he knows and can kill them in their sleep.', 45, '2000-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 8, 'Surekill', 'When a real estate agent is shot inside a prison cell by someone who apparently fired from the roof, Scully and Doggett track him to two exterminators, one of whom has x-ray vision.', 45, '2001-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 9, 'Salvage', 'A man whose blood is rapidly changing into metal alloy enacts revenge on those who caused his condition.', 45, '2001-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 10, 'Badlaa', 'An Indian mystic whose son died in a chemical plant accident smuggles himself into the United States and takes his revenge on two families in suburban Washington, D.C.', 45, '2001-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 11, 'The Gift', 'Doggett comes upon an old case that Mulder kept secret from Scully and he follows up the investigation, hoping to find a possible connection to Mulder''s disappearance.', 45, '2001-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 12, 'Medusa', 'Scully and Doggett must race against the clock to investigate and fight off a contagion lurking in the subway tunnels of Boston.', 45, '2001-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 13, 'Per Manum', 'When Scully and Doggett are contacted by a man who claims his wife was murdered shortly after giving birth to an alien baby, Scully digs deeper into reports of alien fertilization on humans, and she begins to question her own pregnancy and its conception.', 45, '2001-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 14, 'This Is Not Happening (1)', 'When Teresa Hoese (the woman Scully and Mulder met the previous spring in Oregon just before Mulder was abducted) is found in a desert after enduring alien testing, Doggett alerts Scully that this could have something to do with Mulder and his whereabouts. Skinner joins them and they travel to the hospital where Teresa is clinging to life by a thread, and Scully realizes that this is exactly what''s going on with Mulder.', 45, '2001-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 15, 'Deadalive (2)', 'Shortly after Mulder is buried, Billy Miles is found very dead, but he somehow comes back to life. Skinner and Scully put all their hopes into digging up Mulder and discovering that he too, is still alive. As Mulder lies in the hospital without indication that he is going to fully recover, Krycek comes to Skinner and offers him a vaccine to the virus that has infected Mulder, but the cost of the vaccine is that Skinner has to kill Scully''s unborn child.', 45, '2001-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 16, 'Three Words', 'Mulder''s request for reassignment to the X-Files is denied by Kersh, who hopes that Mulder will simply quit the FBI. When a census worker is killed on the White House lawn trying to get information to the President, Mulder gets in over his head trying to discover what the man knew.', 45, '2001-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 17, 'Empedocles', 'Special Agent Reyes enlists Mulder''s help in investigating a supernatural killer''s connection to the unsolved murder of Agent Doggett''s son, Luke.', 45, '2001-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 18, 'Vienen', 'Mulder and Doggett are reluctantly thrown together to investigate several deaths aboard an oil rig, and Mulder becomes convinced that the rig is really carrying the black oil alien.', 45, '2001-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 19, 'Alone', 'While Scully takes maternity leave, Doggett is partnered with a young agent who is fascinated with the X-Files and has followed Mulder and Scully''s careers. She and Doggett investigate the death of an old man and the disappearance of his son, but when they disappear as well Mulder heads out to search for them.', 45, '2001-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 20, 'Essence (1)', 'Mulder and Doggett join forces to investigate the arson attack on a genetics lab where one of the doctors suspected of experimenting with alien impregnation is killed. They encounter Billy Miles, who has been changed into an alien replicant after his recent abduction and is attempting to erase evidence of the tests. When a woman helping Scully out at home is found to be a part of the conspiracy, the agents, along with Monica Reyes and Alex Krycek, know they must protect Scully and her baby from Billy Miles and get her out of the city.', 45, '2001-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 8), 21, 'Existence (2)', 'Mulder, Doggett and Skinner attempt to fight off the alien replicants, and they find a connection to the conspiracy that leads into the FBI while Reyes and Scully head to a remote farm to safeguard the birth of Scully''s child.', 45, '2001-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 9, 'Season 9', 'Aware his presence only puts Scully and William in jeopardy Mulder once again disappears — but at least this time it is his own choice. A frustrated Agent Doggett tries to find Mulder so he can proceed with his investigation against Deputy Director Kersh, but Scully and Skinner finally convince him to drop his case. Yet even as Scully helps Agent Doggett and Agent Reyes on some of their cases she realizes William is still in danger. When she learns a religious cult wants her son dead she turns to the Lone Gunmen. But even they cannot prevent William from being kidnapped, a fact which forces Scully to make a painful decision. Yet even in her darkest hour she receives word that Mulder has been found — and is being held in a military brig for the murder of a man who cannot die.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 1, 'Nothing Important Happened Today (1)', 'Agent Doggett investigates the death of an EPA official after his car is forced off a bridge by a woman he picked up. He asks for assistance on the case from Scully, who has returned to her teaching position at the FBI Academy in Quantico.', 45, '2001-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 2, 'Nothing Important Happened Today II (2)', 'Doggett catches up with Shannon McMahon, the woman who the EPA official picked up. She claims to be a super soldier and that the people she has killed were poisoning the water supply, and she wants Doggett to expose the truth.', 45, '2001-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 3, 'Dæmonicus', 'Doggett and Reyes investigate the murder of a couple in West Virginia that has all the signs of a satanic ritual killing. They link the murder to a doctor who is incarcerated in a mental institute, and Doggett becomes convinced that the doctor is orchestrating the crimes from within the hospital.', 45, '2001-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 4, '4-D', 'During a stakeout of murderer Irwin Lukesh, Doggett sees Reyes attacked by Lukesh, but then we see Reyes and Doggett in her apartment, apparently both fine. Elsewhere at the same time, Doggett is shot and Lukesh identifies Reyes as the shooter. While Reyes is asked for her badge and gun by A.D. Follmer, and Doggett lies in hospital near death, the conflicting circumstances of the stakeout and Doggett''s shooting do not add up and it becomes clear that Lukesh possesses the power to switch between parallel universes and alter the events in each.', 45, '2001-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 5, 'Lord of the Flies', 'When a stunt on a local cable reality show goes horribly wrong resulting in a man''s death, Doggett and Reyes investigate. But when flies pour out of the victims eye sockets, they find themselves relying on Scully''s expertise and ask her to join the investigation.', 45, '2001-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 6, 'Trust No 1', 'Scully is approached by a couple who claim their baby has the same abilities as William and have information about the super soldier program; however, they will only talk to Mulder, believing him the only person who can make the connections and uncover the truth. Scully is forced into an awkward situation when she has to decide whether to put Mulder''s life in more danger even though she desperately wants to see him.', 45, '2002-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 7, 'John Doe', 'Scully and Reyes join forces to try and find Doggett when he goes missing. Doggett has his own problems, having woken up in jail in Mexico suffering from amnesia. With no knowledge of who he is, Doggett is befriended by a local who soon has him working smuggling illegal immigrants across the border.', 45, '2002-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 8, 'Hellbound', 'Agent Reyes takes the lead while investigating an X-file case, surrounding a man found skinned alive after having visions of seeing other people appearing skinned alive. Reyes calls on Scully''s expertise to help on the investigation, which pays off when Scully finds a link to a case from 1960.', 45, '2002-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 9, 'Provenance (1)', 'When pieces of the spaceship beached in Africa resurface, the conspiracy within the FBI attempts to hide the information from the X-Files, especially the one person for whom the pieces have a special significance - Scully.   When Doggett and Reyes discover that Scully and her child have been put in great danger, they race to protect her and William from the evil forces pursuing him, and Scully is forced to take drastic measures to protect her child.', 45, '2002-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 10, 'Providence (2)', 'Scully is anxious to recover William from his kidnappers and takes matters into her own hands when the FBI''s attempts to assist in the investigation are less than helpful. With the help of the Lone Gunmen, Scully discovers terrifying information about her child''s captors, and is once again forced to confront the mystery regarding the sinister interest in her son.', 44, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 11, 'Audrey Pauley', 'After a car accident, Reyes finds herself in a very gray area, while Doggett desperately denies doctors'' diagnoses about his partner, who witnesses a strange disappearance.', 45, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 12, 'Underneath', 'Scully, Doggett and Reyes investigate an old case that Doggett worked on as a cop in Brooklyn, dubbed "The Screwdriver Killer". They try to determine whether the man who was convicted and has just been released from prison was actually the man responsible for the murders.', 45, '2002-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 13, 'Improbable', 'When Reyes uses numerology to connect the murders of several women to an obsessed serial killer, she and Scully become trapped with a mysterious checker-playing man who may or may not be the killer.', 45, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 14, 'Scary Monsters', 'Agent Harrison talks Doggett and Reyes into investigating a boy''s claim that monsters killed his mother, who was officially determined to have stabbed herself repeatedly.', 43, '2002-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 15, 'Jump the Shark', 'The agents ask the Lone Gunmen to help find their friendly foe Yves Adele Harlow after former Area 51 Man-In-Black Morris Fletcher claims she is one of the super-soldiers.', 45, '2002-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 16, 'William', 'Doggett catches someone in the X-files office trying to steal documents pertaining to Mulder''s sister. The intruder is a severely scarred man who blames his disfigurement on Government conspirators. He claims the source of that information - and, in fact, the one who helped him gain entry - is Mulder. Although he refuses to divulge the missing agent''s whereabouts, the mystery man has enough knowledge of the X-files and its history to lead Doggett to suspect that he just might be Mulder himself. Scully''s fears for the safety of her son are elevated when he is injected with an unknown substance. With the mystery surrounding William becoming even darker, Scully must allow herself to send him away for his own safety.', 45, '2002-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 17, 'Release', 'When an FBI cadet with amazing profiling skills approaches Doggett, Reyes, and Scully with a lead on a suspect in a series of recent murders, he claims the same killer is responsible for the death of Doggett''s son. The agents find themselves wondering if his knowledge of the deaths is because of his obsession with the cases he has studied at Quantico, or if he is in some way involved in the murders.', 45, '2002-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 18, 'Sunshine Days', 'Doggett and Reyes investigate a murder outside the house that the original Brady Bunch series was filmed in. The house is owned by a man named Oliver who is obsessed with the show and has rigged the house into a series of traps and changing appearances to look like the Brady house.', 45, '2002-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 19, 'The Truth (1)', 'After not knowing Fox Mulder''s whereabouts for the last year, A.D. Skinner and Agent Scully learn he''s being held for the murder of a military man he couldn''t possibly have killed: Knowle Rohrer, one of the government''s secret super-soldiers. With Skinner acting as Mulder''s defense, people who Mulder has dealt with during his last nine years as an FBI agent testify on his behalf. But the military tribunal isn''t interested in the truth.', 45, '2002-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 9), 20, 'The Truth (2)', 'When an unexpected person comes to Mulder''s rescue, Mulder refuses to slip north over the border to safety. Instead, he heads southwest to the Anasazi ruins of New Mexico seeking a mysterious wise man who the Indians call "The Keeper of the Truth".', 45, '2002-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 10), 1, 'My Struggle', 'Agents Mulder and Scully return after 13 years to investigate a government conspiracy at the behest of a popular web-TV-show host, who introduces them to a woman who claims she''s an alien abductee and shares startling news with them.', 44, '2016-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 10), 2, 'Founder''s Mutation', 'When Mulder and Scully try to discover what unseen force may have driven a scientist to commit suicide, they turn up a laboratory where extreme genetic experimentation has bred subjects possessing dangerous powers.', 44, '2016-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 10), 3, 'Mulder & Scully Meet the Were-Monster', 'Mulder and Scully investigate a dead body in the woods, and try to determine whether it was the work of a serial killer, an animal or a mysterious creature seen by eyewitnesses. Meanwhile, a disillusioned Mulder confronts some of his own demons.', 44, '2016-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 10), 4, 'Home Again', 'Mulder and Scully investigate the murder of a city official, a crime that doesn''t appear to have been committed by human hands. Meanwhile, Scully faces deeply emotional feelings about the child she gave up for adoption.', 44, '2016-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 10), 5, 'Babylon', 'Scully and Mulder investigate when an art gallery displaying offensive artwork is bombed, and need to discover a way to communicate with the comatose perpetrator to try and prevent a future attack.', 44, '2016-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 10), 6, 'My Struggle II', 'The season concludes with people all across the country falling gravely ill. A widespread panic develops and Scully looks within to find a cure. Meanwhile, Mulder confronts the man he believes to be behind it all, but another figure from Mulder and Scully''s past may prove to be the key to their salvation.', 44, '2016-02-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 1, 'My Struggle III', 'Mulder and Scully learn that they aren''t the only ones desperately searching for their long-lost son, William. The very fate of the world may depend on it.', 42, '2018-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 2, 'This', 'A chilling secret is revealed when an old friend reaches out to Mulder and Scully in a seemingly impossible way.', 44, '2018-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 3, 'Plus One', 'Mulder and Scully investigate a case where people are plagued by their own doppelgangers.', 44, '2018-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 4, 'The Lost Art of Forehead Sweat', 'Exploring the idea of The Mandela Effect, in which large groups of people remember an alternate history, Mulder and Scully find out how the X-Files themselves may really have originated.', 44, '2018-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 5, 'Ghouli', 'When a pair of teenage girls attack one another, each believing the other to be a monster, Mulder and Scully find that their investigation could possibly lead back to their long-lost son, William.', 45, '2018-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 6, 'Kitten', 'Skinner goes AWOL when his past comes back to haunt him. As Mulder and Scully try to track him down, their growing mistrust of him reaches its apex.', 44, '2018-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 7, 'Rm9sbG93ZXJz', 'In a world of ever-increasing automation and artificial intelligence, Mulder and Scully find themselves targets in a deadly game of cat-and-mouse.', 44, '2018-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 8, 'Familiar', 'Mulder and Scully investigate the brutal animal attack of a little boy in Connecticut, while suspecting darker forces are at play.', 44, '2018-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 9, 'Nothing Lasts Forever', 'While investigating human organ theft, Mulder and Scully uncover a mysterious cult consumed with macabre rituals.', 44, '2018-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106179')) AND numero_temporada = 11), 10, 'My Struggle IV', 'Mulder and Scully rush to find an on-the-run William while the Cigarette Smoking Man pushes forward with his ultimate plan.', 44, '2018-03-21');
