INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 1, 'The Good Son', 'Psychiatrist Frasier Crane returns to his hometown of Seattle to host a radio talk show, but soon discovers he could use a shrink himself when his father moves in.', 23, '1993-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 2, 'Space Quest', 'Fed up with a lack of privacy at home and at work, Frasier decides it''s time for his father to move out.', 23, '1993-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 3, 'Dinner at Eight', 'It''s a culinary culture clash when Frasier and Niles join their father for dinner at his favorite restaurant.', 23, '1993-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 4, 'I Hate Frasier Crane', 'After trading barbs with a newspaper columnist, Frasier rises to the challenge of a fist fight.', 23, '1993-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 5, 'Here''s Looking at You', 'Frasier plays matchmaker for his father and the eligible bachelorette Martin spied through his telescope.', 23, '1993-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 6, 'The Crucible', 'Frasier is furious when he learns that his newest art purchase is actually a fake.', 23, '1993-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 7, 'Call Me Irresponsible', 'Frasier faces a personal and professional dilemma when he begins dating the ex-girlfriend of one of his radio show callers.', 23, '1993-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 8, 'Beloved Infidel', 'When Frasier and Niles see their father dining with an old family friend, they conclude that Martin once had an affair with the woman.', 23, '1993-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 9, 'Selling Out', 'When Frasier is lured into doing on-air endorsements, his professional credibility comes under fire.', 23, '1993-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 10, 'Oops', 'When Frasier contributes to the rumor mill, he causes Bulldog to lose his job.', 23, '1993-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 1), 11, 'Death Becomes Him', 'When a seemingly healthy colleague dies unexpectedly, Frasier becomes obsessed with his own mortality.', 23, '1993-12-02');
