INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 8), 2, 'And the Dish Ran Away with the Spoon (2)', 'Daphne considers dumping Niles after Donny and Mel''s plotting stresses her out. Fortunately, Frasier comes to the lovers'' aid once again.', 24, '2000-10-24');
