INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 8), 4, 'The Great Crane Robbery', 'Frasier frets when his billionaire boss slavishly copies his aesthetic tastes, and Mel blackmails Niles into making a social faux pas.', 24, '2000-11-14');
