INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 8), 9, 'Frasier''s Edge', 'A lifetime achievement award sends Frasier into an existential crisis which culminates in a battle of wits with his old mentor; Daphne''s weight gain doesn''t go unnoticed.', 24, '2001-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 8), 10, 'Cranes Unplugged', 'Frasier gets a visit from his video-game obsessed son, Frederick; Daphne and Niles play Cupid for a lonely Roz.', 24, '2001-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 8), 11, 'Motor Skills', 'Frasier and Niles realize their helplessness when Frasier''s car stalls, so they enrol in an auto repair night class. They quickly fall behind, and understand what it''s like to be remedial students.', 24, '2001-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 8), 12, 'The Show Must Go Off', 'Frasier and Niles try to reawaken the career of Jackson Hedley, an old actor they saw perform Hamlet when they were young. When they see him perform again, however, they realize that he is talentless and will humiliate himself.', 24, '2001-02-06');
