INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 2, 'Don Juan in Hell (2)', 'Troubled by his recent relationship woes, Frasier goes to the country for peace and quiet but ends up facing the ghosts of failed relationships past.', 24, '2001-09-25');
