INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 6, 'Room Full of Heroes', 'Frasier holds a ''Dress as Your Hero'' Halloween party, but nobody can tell who he is.  Meanwhile, Niles dresses as Martin, Daphne as Elton John, Martin as Joe DiMaggio and Roz as Wonder Woman for the party.', 24, '2001-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 7, 'Bla-Z-Boy', 'An accident causes a mess on Frasier''s carpet and the destruction of Martin''s chair.  Meanwhile, Niles gives piano lessons to talented Roz and not-so-talented Daphne.', 24, '2001-11-06');
