INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 9, 'Sharing Kirby', 'Blood pressures and spirits rise as an intern becomes the pawn in Frasier and Niles'' battle over a wine cellar tour.', 24, '2001-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 10, 'Junior Agent', 'Frasier gets an annoying new agent in the middle of a competition between him and a rival radio broadcaster.', 24, '2001-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 11, 'Bully for Martin', 'After Frasier witnesses Martin get chewed out by his boss, Frasier feels obligated to say something on his behalf. However, it only serves to make things worse.', 24, '2001-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 12, 'Mother Load (1)', 'When Daphne and Niles decide to move in with each other, Daphne''s mother and Simon arrive on a surprise visit.  Daphne and Niles decide to put off moving in together until her visiting relatives are gone.  Meanwhile, Frasier feuds with Cam Winston, his neighbor, over where Cam parks his large vehicle.', 24, '2002-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 13, 'Mother Load (2)', 'Daphne and Niles continue to try and hide the fact that they have moved in with each other from Mrs. Moon.  She makes such a mess of things that the only way she will leave is if Simon takes care of her, but Simon has left for California.  Meanwhile, Frasier''s neighbor Cam drapes the American flag over his balcony, and Frasier cannot complain because it would seem unpatriotic.', 24, '2002-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 14, 'Juvenilia', 'Kenny tells Frasier and Roz that some recent research into KACL listeners shows that Frasier''s average listener is an older gentleman who keeps the radio on for company. He suggests Frasier reach out to the youth.', 24, '2002-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 15, 'The Proposal', 'Niles plans on proposing to Daphne, so he prepares his speech; buys a ring; and hires a choir, a string quartet, a trumpet player and Wolfgang Puck.  But Daphne''s mother is still staying with them, and on the night Niles plans to propose, Daphne begins to feel ill.', 24, '2002-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 16, 'Wheels of Fortune', 'Frasier is unimpressed when his scheming, scamming ex-brother-in-law rolls in for a visit -- now in a wheelchair -- and claims to be a reformed, God-fearing man who needs money for a revival ministry.', 24, '2002-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 17, 'Three Blind Dates', 'Niles sets Frasier up with Lisa, a patient who owns a bookstore, but they never run into each other.  Roz sets Frasier up with Suzanne, an artist, who ends up hating Frasier.  Martin sets Frasier up with Kris, an attractive girl from his building, who seems to know every man at the bar.  But Frasier later runs into and hits it off with Lisa.', 24, '2002-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 18, 'War of the Words', 'A-N-X-I-E-T-Y seizes Frasier at the National Spelling Bee, where his son Frederick is a leading competitor.', 24, '2002-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 19, 'Deathtrap', 'While Frasier and Niles uncover a human skull under the floor of their childhood home and let their imagination get the better of them, Roz''s daughter''s hamster has died and she is uncertain how to break it to her.', 24, '2002-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 20, 'The Love You Fake', 'To quell a feud between Frasier and an upstairs antagonist, Martin and the neighbor''s mother feign a romance.', 24, '2002-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 21, 'Cheerful Goodbyes', 'Frasier returns to Boston to give a speech, and Niles, Daphne and Martin tag along to see the city. Once there, Frasier runs into Cliff Clavin.', 24, '2002-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 22, 'Frasier Has Spokane', 'Frasier''s show has branched out to Spokane, and he goes to the station in Spokane to meet the press. He quickly finds out that the press and his callers refuse to warm up to him.', 24, '2002-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 23, 'The Guilt Trippers', 'Guilt feelings over a sexual liaison with Roz plague Frasier, who heads out to her family reunion in Wisconsin to make amends.', 24, '2002-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 9), 24, 'Moons Over Seattle', 'Niles'' persistence finally convinces Daphne''s father to come to Seattle to reconcile with his wife. Daphne is disappointed that Niles didn''t consult her first, but is on board with the plan.', 24, '2002-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 1, 'The Ring Cycle', 'After Daphne and Niles elope in Reno, they are forced to go through several fake ceremonies in not to upset friends and family who wanted to be at the wedding.', 24, '2002-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 2, 'Enemy at the Gate', 'Frasier drives Niles back from a shopping excursion. Just as they enter the parking garage, Frasier suddenly realizes that the clock in his car is incorrect and that he is going to be late for his show.', 24, '2002-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 3, 'Proxy Prexy', 'Frasier is desperate to finally win the presidency of the condo board after several unsuccessful attempts.  However, he admits that he has no chance because he has rubbed all of the board members the wrong way at one time or another.', 24, '2002-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 4, 'Kissing Cousin', 'Frasier is surprised to learn that Kenny has never unpacked the boxes in his office because he views all of his jobs as temporary.  Roz''s younger cousin Jen comes to stay with her for the week.  She is extremely cynical and opinionated, and quickly gets on Frasier''s nerves.', 24, '2002-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 5, 'Tales from the Crypt', 'Frasier is infuriated when Bulldog successfully pulls several practical jokes on him.  He vows to get revenge, and plots an elaborate prank that he takes way too seriously.  Martin and Roz predict that he will fail because he is terrible at carrying out pranks.  .', 24, '2002-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 6, 'Star Mitzvah', 'As Frasier prepares for Frederick''s bar mitzvah, Noel offers to translate Frasier''s speech into Hebrew in exchange for an autograph from a science fiction convention.  However, when Frasier doesn''t keep his end of the bargain, Noel uses his wealth of Star Trek knowledge to take revenge.', 24, '2002-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 7, 'Bristle While You Work (1)', 'Niles becomes concerned about a lingering toothache after his dentist assures him that there is nothing wrong with the tooth.  He tells Roz that there is a chance that he may be suffering from referred pain; and that the pain could actually be a sign of a heart condition.', 24, '2002-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 8, 'Rooms With a View (2)', 'Niles prepares to undergo heart bypass surgery.  He is surprised to receive a call wishing him well from Maris, who had learned of his plight from a gossipy acquaintance.  Frasier tries to keep Roz and the family at ease by researching the procedure (as well as the doctors'' backgrounds) and printing out detailed descriptions for everyone.', 24, '2002-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 9, 'Don''t Go Breaking My Heart (3)', 'Niles recovers rapidly from his heart surgery and receives the go-ahead from doctors to resume normal activities, but seems reluctant to do this.  He maintains his strict post-operative diet, and refuses to exercise or share a bed with Daphne.', 24, '2002-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 10, 'We Two Kings', 'Frasier and Niles bicker over who gets to host the family Christmas celebration. When it seems that Martin will have to work, they decide to bring Christmas to him, with disastrous results. Meanwhile, Roz finds herself attracted to a hunky shopping mall Santa.', 24, '2002-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 11, 'Door Jam', 'Frasier mistakenly receives some of Cam Winston''s mail, including a mysterious invitation to an exclusive locale.  Frasier and Niles are surprised to have been left out of the loop about this new hot spot, and become obsessed with finding out more information.', 24, '2003-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 12, 'The Harassed', 'Frasier is forced to give up ten minutes of his show for a new financial analysis segment. When the beautiful new stock market reporter''s attitude rubs everyone the wrong way, Frasier misreads her signals, which lands everyone in a sexual harassment seminar.', 24, '2003-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 13, 'Lilith Needs a Favor', 'Lilith comes to Seattle, and tells Frasier that she would like to have another child.  She wants him to father the child through artificial insemination so that Frederick could have a full-sibling.  Frasier is hesitant to go along with this, so Lilith tries to manipulate him by bringing up touching stories from Frederick''s childhood.', 24, '2003-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 14, 'Daphne Does Dinner', 'Niles and Frasier plan a party to celebrate the unveiling of a painting that Niles has just purchased.  However, Daphne notes that every event the brothers host inevitably ends in disaster.', 24, '2003-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 15, 'Trophy Girlfriend', 'Tired of being humiliated in his club''s annual squash tournament, Niles ditches Frasier and pairs with a younger partner.  A P.E. teacher named Chelsea asks Frasier to team with her in the mixed doubles competition.', 24, '2003-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 16, 'Fraternal Schwinns', 'KACL organizes a bike-a-thon to raise money for AIDS research.  Frasier plans to just make a financial donation, but is goaded into participating after Julia announces her intention to take part.  Daphne suggests that she and Niles also enter the event.', 24, '2003-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 17, 'Kenny on the Couch', 'Kenny becomes extremely depressed after his divorce is finalized.  Frasier offers to refer him to another psychiatrist, but Kenny says that he would prefer to discuss his problems with Frasier.', 24, '2003-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 18, 'Roe to Perdition', 'Frasier and Niles become a big hit when, at a party, they serve beluga caviar they purchased on the black market. Meanwhile, Martin has a tough time returning $40 an ATM gave him in error.', 24, '2003-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 19, 'Some Assembly Required', 'Frasier''s co-workers cajole him into helping them build a house for Habitat for Humanity.  Frasier mostly seems to get in the way, and his participation is limited to stirring paint and a little bit of sanding.', 24, '2003-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 20, 'Farewell, Nervosa', 'Frasier consults his old friend Avery for advice on his finances.  Avery says that Frasier''s spending habits are out of control.  Frasier becomes depressed and heads out to Cafe Nervosa to think about a solution.', 24, '2003-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 21, 'The Devil and Dr. Phil', 'Frasier learns that Dr. Phil McGraw is in town for a special.  The two are old friends, but Frasier is angry at Phil for supposedly swindling him out of $200 in a poker game.  He reluctantly agrees to take the star-struck Roz to the set to see him.', 24, '2003-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 22, 'Fathers and Sons', 'Leland Barton, Hester''s former research assistant, comes for a visit after a long absence from Seattle.  Roz becomes alarmed when Leland confesses his deep affection for Hester.', 24, '2003-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 23, 'Analyzed Kiss', 'Julia becomes extremely depressed after breaking up with Avery, who had never followed through on his promise to leave his wife for her.  He tries to deny her the credit for their software company, an endeavor for which she did most of the work.', 24, '2003-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 10), 24, 'A New Position for Roz', 'Roz tries to train the woefully incompetent Noel as Frasier''s new producer as she prepares to leave KACL.  She becomes increasingly melancholy about the possibility of leaving Frasier, and bristles upon learning of his new relationship with Julia.', 24, '2003-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 1, 'No Sex, Please, We''re Skittish', 'Roz''s return to KACL rattles Frasier, who''s reinvolved with Julia; Niles'' fatherhood plans get an unexpected setback he determines to remedy with an unorthodox virility enhancer.', 24, '2003-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 2, 'A Man, a Plan and a Gal: Julia', 'Love blinds Frasier to the faults of Julia, who behaves obnoxiously and insensitively at a Crane dinner gathering. For starters, she embarrasses Daphne, then winds up chattering incessantly on her cell phone.', 24, '2003-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 3, 'The Doctor Is Out', 'Frasier and Niles suspect that Roz''s new boyfriend, Barry, is gay.  They see Barry on the street and believe that he has gone into a gay bar.  Frasier, worried that Barry is leading Roz on, goes inside to confront him.', 24, '2003-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 4, 'The Babysitter', 'A courtship makes rivals of Martin and Frasier, who are vying for the affections of the latter''s former baby-sitter, now a lounge singer with a vivacious personality and a quick wit that''s appealing to both Crane senior and junior.', 24, '2003-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 5, 'The Placeholder', 'Roz tries to convince Frasier to go out with her friend Ann.  She feels that Frasier is too particular about who he dates, and adds that there is nothing wrong with continuing to date around until the right person comes along.', 24, '2003-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 6, 'I''m Listening', 'Frasier overhears Ronee making a date with another man.  He tells Martin, who is furious at him for eavesdropping.  Ronee later breaks the news to Martin herself, explaining that she didn''t think they had an exclusive relationship.', 24, '2003-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 7, 'Maris Returns (1)', 'Niles receives a phone call from a panicked Maris, who asks to meet him for lunch.  She asks for advice on how to handle her violent, philandering lover.  Niles recommends that she leave him immediately.', 24, '2003-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 8, 'Murder Most Maris (2)', 'Niles is questioned by the police because he loaned Maris the murder weapon--an antique crossbow--for use in a play.  Maris insists that she acted in self-defense.  She continually calls Niles from jail, leaving Daphne extremely angry.', 24, '2003-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 9, 'Guns N'' Neuroses', 'Lilith comes to town for a one-day conference.  She and Frasier try to get together, but keep having to cancel.  Lilith discusses her romantic problems with a colleague at Cafe Nervosa before having to return to the conference.', 24, '2003-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 10, 'Seabee Jeebies', 'Niles gains notoriety throughout Seattle because of his involvement in Maris''s murder case.  He and Daphne mingle with the city''s social elite (including Bill Gates), and he is able to finagle reservations at booked restaurants.', 24, '2003-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 11, 'High Holidays', 'Frasier is shocked when Frederick comes to visit sporting his new ''goth'' look.  Meanwhile, realising that he never rebelled in his adolescence, Niles decides to try marijuana...with unexpected results.', 24, '2003-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 12, 'Frasier-Lite', 'Weight loss challenges KACL, enrolled in a pound-shedding contest that pits Frasier against a taunting nemesis who bullied him in high school.', 24, '2004-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 13, 'The Ann Who Came To Dinner', 'Lawsuit fears plague Frasier over an accident in his kitchen that befell his insurer: a former date named Ann he snubbed. Now, Frasier entreats her to recuperate at his place, where Ann takes full advantage of the situation.', 24, '2004-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 14, 'Freudian Sleep', 'Strange dreams dominate this episode, which finds Frasier wed to Daphne, now a vociferous eater; Niles a carefree philanderer, dallying with bikini-clad repairwomen; and Martin a dashing hoofer, performing with Ronee.', 24, '2004-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 15, 'Caught in the Act', 'Roz is disappointed when she is unable to get Alice tickets to a concert by children''s performer Nanny G.  After his family reveals that he used to be married to her, Frasier agrees to help Roz secure tickets.', 24, '2004-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 16, 'Boo!', 'A practical joke backfires, giving Martin a ''mild cardiac event'' that he''s anxious to keep secret from Ronee, fearing that she''ll think he''s become ''some feeble old guy''.', 24, '2004-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 17, 'Coots and Ladders', 'Guilty feelings seize Frasier, who, just for a thrill, swipes a medallion from his neighbor, a chatty, trusting widow. Now he sets out to secretly return the object, with the reluctant help of Niles.', 24, '2004-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 18, 'Match Game', 'Lovelorn Frasier engages a matchmaker, who mismatches him with dinner dates that turn disastrous; well-meaning Niles hires a kooky helpmate for Daphne''s delivery who works with a shaman ...and a drummer.', 24, '2004-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 19, 'Miss Right Now', 'Martin worries about a visit from Ronee''s mother.  She dislikes him because she once saw Martin innocently comforting the teenage Ronee and assumed he was trying to ''take her virtue''.', 24, '2004-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 20, 'And Frasier Makes Three', 'Courting unnerves Frasier, whose wooing of a winsome matchmaker is constantly interrupted by her disarming beau, a dedicated environmentalist who''s also quite cosmopolitan.', 24, '2004-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 21, 'Detour', 'Country ways test Frasier and Charlotte, who''re stranded at a farmhouse with a very odd family that has no idea who he is. Back home, a physical therapist is mistaken for a stripper in a situation that greatly embarrasses Niles.', 24, '2004-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 22, 'Crock Tales', 'As Frasier prepares for a dinner party, he considers throwing away an old broken crock pot.  However, the crock pot stirs many memories of past experiences with his friends and family.', 24, '2004-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 23, 'Goodnight, Seattle (1)', 'During an especially bumpy flight Frasier tells a fellow passenger about his eventful past few weeks which are recounted in a long flashback. Bebe tells Frasier that he has been offered the chance to replace a recently deceased San Francisco radio host.', 24, '2004-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0106004')) AND numero_temporada = 11), 24, 'Goodnight, Seattle (2)', 'Daphne gives birth to a healthy son David. Frasier marries Martin and Ronee in the vet''s office before Daphne and the baby leave for the hospital. Frasier grows very lonely with Martin out of the apartment and Daphne and Niles busy with their son.', 24, '2004-05-13');
