INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 1, 'Pilot', 'After Rachel leaves her fiancé at the altar, she moves in with Monica and finds that independence is not so easy, particularly without Daddy''s credit cards.', 23, '1994-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 2, 'The One with the Sonogram at the End', 'Ross''s lesbian ex-wife Carol is pregnant with his child, and he doesn''t like her choice of last name for the baby. Rachel finds out that her ex-fiancé went on what would have been their honeymoon with her maid of honor.', 23, '1994-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 3, 'The One with the Thumb', 'Monica finds it difficult to break up with her latest boyfriend whom everyone likes; Chandler is reunited with his beloved cigarettes; Phoebe receives a large sum of money.', 23, '1994-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 4, 'The One with George Stephanopoulos', 'While the men attend a hockey game and end up at a hospital, a delivery man accidentally brings a pizza meant for George Stephanopoulos, who lives across the street from the girls; they decide to peek at the former White House advisor with their binoculars.', 23, '1994-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 5, 'The One with the East German Laundry Detergent', 'While Chandler and Phoebe decide to break up with their significant others on the same night, Ross helps Rachel do laundry and considers the evening a first date. Joey has Monica pose as his new girlfriend, because he wants to get back with the girl he just dumped.', 23, '1994-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 6, 'The One with the Butt', 'Joey gets his big film break when he''s hired to be Al Pacino''s stunt butt. Ross tries to be less conservative and Chandler thinks his fantasies have come true when he has an affair with a married woman.', 21, '1994-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 7, 'The One with the Blackout', 'A power outage leaves Chandler stranded in an ATM vestibule with Victoria''s Secret model Jill Goodacre, whom he desperately tries to impress, Ross tries to ask Rachel out on a date, and Joey learns that Monica used to be infatuated with him.', 23, '1994-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 8, 'The One Where Nana Dies Twice', 'Monica and Ross mourn the death of their grandmother with a little help from the gang, and Monica and her mom come to an unspoken understanding about the relationship between mothers and daughters. Meanwhile, Chandler is irritated by office speculation that he is gay.', 23, '1994-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 9, 'The One Where Underdog Gets Away', 'Monica''s first Thanksgiving dinner for the gang goes horribly wrong when they all run to the rooftop to see the runaway Underdog balloon from the parade.', 23, '1994-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 10, 'The One with the Monkey', 'The gang makes--then breaks--a pact to celebrate New Year''s Eve without dates. Ross compensates for his loneliness by getting a roommate, a monkey named Marcel.', 23, '1994-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 11, 'The One with Mrs. Bing', 'Chandler''s romance-novelist mother comes to New York to visit him, and Joey catches her and Ross kissing.', 23, '1995-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 12, 'The One with the Dozen Lasagnas', 'Everyone knows the sex of Ross''s baby, except for Ross, who doesn''t want to find out until it''s born. Monica gives Paolo one of the dozen lasagnas she made for her aunt, who doesn''t want them anymore because they''ve got meat in them.', 23, '1995-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 13, 'The One with the Boobies', 'Chandler accidentally sees Rachel wandering around topless after her shower, so Rachel tries to even the score. And no one can stand Phoebe''s new boyfriend, an irritating guy named Roger.', 23, '1995-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 14, 'The One with the Candy Hearts', 'Ross''s first date in nine years is on Valentine''s Day with a beautiful neighbor. Susan and Carol, also out on a romantic date; end up at the same restaurant. Joey sets Chandler up on a blind date. And Phoebe, Rachel and Monica decide to spend the holiday building a boyfriend bonfire in their apartment.', 23, '1995-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 15, 'The One with the Stoned Guy', 'Monica cooks a gourmet meal for a restaurateur looking for a new chef but, unfortunately, he''s stoned. After working as a data processing permanent temp for five years, Chandler gets promoted. And Ross has a date with a beautiful colleague.', 23, '1995-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 16, 'The One with Two Parts (1)', 'Joey falls for Phoebe''s twin sister, Ursula, making Phoebe feel neglected. Ross has doubts about parenthood when he attends Lamaze classes with Carol and Susan. Meanwhile, Chandler finds himself between a rock and a hard place, when he is told to fire an employee he is attracted to.', 23, '1995-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 17, 'The One with Two Parts (2)', 'When Rachel sprains her ankle and has no insurance, she cajoles Monica into trading identities so she can use Monica''s coverage. When Phoebe''s twin sister, Ursula, breaks Joey''s heart, Phoebe tries to fix it.', 23, '1995-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 18, 'The One with All the Poker', 'Tired of being referred to by customers as "Excuse me" Rachel interviews for a job as an assistant buyer at Saks Fifth Avenue. She also sees another side of the usually docile Ross when the girls face the boys during a not-so-friendly game of poker.', 23, '1995-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 19, 'The One Where the Monkey Gets Away', 'The gang searches frantically for Marcel, who slipped out of the apartment while Rachel was baby-sitting him. Just as it looks as though Rachel and Ross might actually spend a romantic evening together, her ex-fiancé barges in and declares his love for her.', 23, '1995-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 20, 'The One with the Evil Orthodontist', 'Rachel and Barry start dating again, which is kind of awkward since he''s now engaged to Mindy, who wants Rachel to be her maid of honor. Meanwhile, Chandler goes nuts when a woman he likes won''t return his phone calls.', 23, '1995-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 21, 'The One with the Fake Monica', 'When Monica''s credit card is stolen, she, along with Phoebe and Rachel, decide to catch the thief. Joey enlists his friends to help him come up with a less ethnic-sounding stage name. And  Ross finds out that Marcel has reached sexual maturity and needs to be with other monkeys.', 23, '1995-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 22, 'The One with the Ick Factor', 'After losing his virginity to her, Monica''s boyfriend reveals that he''s a high school senior. When Phoebe temps as Chandler''s secretary, she finds out a secret.', 23, '1995-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 23, 'The One with the Birth', 'As Monica''s biological clock ticks away like a time bomb, Carol goes into labor. Ross, Susan and Phoebe end up getting locked in a closet just as Carol''s about to give birth to the baby. And Rachel flirts with an OB/GYN.', 23, '1995-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 1), 24, 'The One Where Rachel Finds Out', 'Joey''s new girlfriend wants to go to bed with him but he can''t, yet. During Rachel''s birthday party, Chandler accidentally lets it slip that Ross is in love with her. However, Ross is on his way to China and Rachel can''t decide whether she wants to be more than friends with Ross.', 23, '1995-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 1, 'The One with Ross''s New Girlfriend', 'Rachel waits patiently at the airport for Ross, returning from China. Meanwhile, after giving Joey and Chandler new haircuts, Phoebe is persuaded to cut Monica''s hair. And Joey learns that his tailor is a very naughty man.', 23, '1995-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 2, 'The One with the Breast Milk', 'The guys are uncomfortable with the thought of Carol''s breast milk while Rachel is upset by Monica''s growing friendship with Julie. Meanwhile, Joey competes with a fellow cologne spritzer for the affections of a beautiful colleague.', 23, '1995-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 3, 'The One Where Heckles Dies', 'After Mr. Heckles dies and leaves all his belongings to Monica and Rachel, Chandler discovers eerie similarities between the late eccentric man and his own life. Ross and Phoebe have a dispute over the progression of evolution.', 23, '1995-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 4, 'The One with Phoebe''s Husband', 'The gang is amazed to learn that Phoebe married a gay Canadian ice dancer to help him get his green card. And Ross seeks relationship advice from Rachel.', 23, '1995-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 5, 'The One with Five Steaks and an Eggplant', 'When a sexy woman calls the wrong number, Chandler seeks to make the most of the situation. Income issues divide the friends; Monica, Ross and Chandler have money, while Phoebe, Rachel and Joey don''t.', 23, '1995-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 6, 'The One with the Baby on the Bus', 'Chandler and Joey lose Ross''s son, Ben, while checking out women on a bus. Phoebe loses her Central Perk singing gig to a professional singer. And Ross has an allergic reaction to Monica''s kiwi-lime pie.', 23, '1995-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 7, 'The One Where Ross Finds Out', 'A drunken Rachel is persuaded to call Ross and reveal her feelings for him on his answering machine. Now, Ross must make a decision between her and Julie. Meanwhile, Monica finds work as Chandler''s personal trainer and Phoebe has a hard time trying to get her boyfriend to have sex with her.', 23, '1995-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 8, 'The One with the List', 'Ross enlists Joey and Chandler to help with his decision to choose Julie or Rachel by making a list of the pros and cons of each. Big mistake. Meanwhile, Monica gets a job making food with a synthetic chocolate substitute called Mockolate.', 23, '1995-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 9, 'The One with Phoebe''s Dad', 'It''s Christmas time and Monica tries tipping with cookies, rather than cash, with mixed results. Phoebe tries to track down her real father. And Chandler and Joey wait too late to shop for presents.', 23, '1995-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 10, 'The One with Russ', 'Monica gets back together with Fun Bobby. Joey lands a role of a neurosurgeon on Days of Our Lives. And Rachel, dating a guy named Russ, can''t see his uncanny resemblance to Ross.', 23, '1996-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 11, 'The One with the Lesbian Wedding', 'Monica caters the wedding of Ross''s ex-wife and her lesbian lover. Phoebe is possessed by the spirit of an 82-year-old massage client who dies in the middle of a session. And Rachel''s mom comes to visit and drops a bombshell.', 23, '1996-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 12, 'The One After the Super Bowl (1)', 'Ross goes to visit Marcel, his monkey, while on a trip to California. Joey gets his first fan letter and ends up dating the woman. Phoebe is asked to sing for the children at the library, but their parents are horrified by her lyrics.', 23, '1996-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 13, 'The One After the Super Bowl (2)', 'Rachel and Monica compete for the affections of Jean-Claude Van Damme after meeting him on a movie set. Chandler meets a former schoolmate while an excited Joey gets a role as an extra in the movie. Ross and Marcel go on a whirlwind tour of the city.', 23, '1996-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 14, 'The One with the Prom Video', 'After getting his big break, with Days of Our Lives, Joey pays Chandler back. Monica is unemployed and hard up for money. Monica and Rachel''s prom video reveals Monica''s former girth, Rachel''s former nose and the way Ross has always felt about Rachel.', 23, '1996-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 15, 'The One Where Ross and Rachel... You Know', 'Joey buys a big screen TV and two leather recliners with his newfound money. Monica has a catering job for one of her parents'' friends and becomes infatuated. Ross and Rachel attempt to have their first real date, but Rachel laughs every time they kiss. When they try again the next evening, they are interrupted when Ross is called into the museum.', 23, '1996-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 16, 'The One Where Joey Moves Out', 'After having a fight with Chandler, Joey decides to move out. Rachel and Phoebe decide to get tattoos. And, on his birthday, Mr. Geller receives the unsettling news that his best friend and his daughter are dating.', 23, '1996-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 17, 'The One Where Eddie Moves In', 'Phoebe is discovered by a record producer who wants to make "Smelly Cat" a video. Ross''s new relationship with Rachel makes Monica feel like she''s living with her brother again... and she hates it.  And Joey considers moving back in with Chandler, but Chandler has a new roommate.', 23, '1996-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 18, 'The One Where Dr. Ramoray Dies', 'Chandler learns more about his new roommate, Eddie. Ross is stressed out to learn that Rachel had ''animal sex'' with Paolo. Richard and Monica are uncomfortable to learn what their numbers of ex-lovers are. Joey''s remarks to a fan magazine could cause him to lose his job playing Dr Ramoray.', 23, '1996-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 19, 'The One Where Eddie Won''t Go', 'Creeped out by his bizarre new roommate, Chandler demands he move out; Eddie agrees... but won''t go. Joey has trouble coming to grips with the death of Dr. Drake Ramoray and is facing some exorbitant bills. And a new book on women''s empowerment inspires the ladies to have a "goddess meeting."', 23, '1996-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 20, 'The One Where Old Yeller Dies', 'Monica''s new boyfriend impresses Chandler and Joey. Phoebe''s world view is shattered when she finds out what she missed as a child, and Rachel resents the fact that Ross has planned their whole life together.', 23, '1996-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 21, 'The One with the Bullies', 'Monica is broke and decides to gamble on the stock market, while Chandler and Ross run into a couple of bullies in Central Park. Rachel and Joey help Phoebe locate her father, but a vicious dog prevents Phoebe from finally meeting him.', 23, '1996-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 22, 'The One with the Two Parties', 'Monica decides to hold a surprise birthday for Rachel, but everything goes wrong when Rachel''s estranged parents turn up unexpectedly. The party then splits into two factions, but complications inevitably ensue.', 23, '1996-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 23, 'The One with the Chicken Pox', 'Phoebe''s submariner ex-boyfriend visits New York on leave for 2 weeks from the Navy. Unfortunately, Phoebe catches chicken pox at Ben''s first birthday party. When Monica realizes that Richard has no real neuroses, she worries that she is too strange for him. Chandler organizes a job as a processor for Joey.', 23, '1996-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 2), 24, 'The One with Barry and Mindy''s Wedding', 'Rachel agrees to be maid of honor at her ex-fiancé''s wedding; she relives the nightmare of her own failed wedding day. Meanwhile, Chandler becomes enamored with a woman he meets on the Internet, but is surprised when he finally meets her. Monica ponders her future with Richard.', 23, '1996-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 1, 'The One with the Princess Leia Fantasy', 'Ross reveals a fantasy to Rachel involving a certain "Star Wars" character. Monica suffers from insomnia after her breakup with Richard. And Chandler, back together with Janice, wants Joey to bond with her.', 23, '1996-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 2, 'The One Where No One''s Ready', 'In a race against the clock, a stressed Ross tries to get the gang dressed and ready for a black-tie benefit at the museum while Joey and Chandler clash over personal belongings and personal space.', 23, '1996-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 3, 'The One with the Jam', 'Phoebe dates a man who thinks he''s stalking her twin sister. Ross and Rachel give Chandler "boyfriend" lessons. Monica decides the best way to get over Richard is to keep herself busy, so she uses her free time to make jam and considers insemination via a sperm bank.', 23, '1996-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 4, 'The One with the Metaphorical Tunnel', 'Phoebe poses as Joey''s agent and has some success in getting him auditions. Ross panics when he sees his son with a Barbie doll. Chandler is advancing in his relationship with Janice and, realizing that he has a fear of commitment, goes to the girls for advice.', 23, '1996-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 5, 'The One with Frank, Jr.', 'Phoebe''s half-brother visits, but they have trouble bonding. Joey attempts to build an entertainment center. Ross is challenged to name the five celebrities he''d like to sleep with most.', 23, '1996-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 6, 'The One with the Flashback', 'When Janice asks the gang if any of them have ever slept together, the friends flash back to a time three years before.', 23, '1996-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 7, 'The One with the Race Car Bed', 'Monica buys a new bed from Janice''s soon-to-be-ex-husband, "The Mattress King", but the wrong one is delivered.  Rachel''s attempts to have her father and Ross bond fail, until she stops trying. Joey gets a job teaching a soap opera acting class.', 23, '1996-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 8, 'The One with the Giant Poking Device', 'When Phoebe believes she''s killed the ugly naked guy across the street from Rachel and Monica, Joey constructs a long poking device. Joey and Monica catch Janice kissing her ex-husband; Chandler confronts Janice.', 23, '1996-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 9, 'The One with the Football', 'Emotions become the feast of the day when the gang plays a game of touch football on Thanksgiving. Joey and Chandler argue over who gets to date a model while Ross and Monica argue over winning in a case of sibling rivalry.', 23, '1996-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 10, 'The One Where Rachel Quits', 'Rachel makes a rash decision after Gunther tells her she needs to be retrained.  Phoebe tries to help Joey when he gets a job selling Christmas trees.  And Ross accidentally breaks a girl''s leg and tries to make it up to her.', 23, '1996-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 11, 'The One Where Chandler Can''t Remember Which Sister', 'Ross is suspicious about Rachel''s possible job offer from a good-looking stranger.  And a drunken Chandler fools around with one of Joey''s sisters, but he can''t remember which one.', 23, '1997-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 12, 'The One with All the Jealousy', 'Ross becomes increasingly jealous of Rachel''s new colleague, Mark, and spies on her. Monica hooks up with a co-worker, who writes her a poem with a hidden meaning. One of Joey''s numerous lies on his resume is exposed when he takes part in a Broadway musical.', 23, '1997-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 13, 'The One Where Monica and Richard Are Just Friends', 'Monica''s willpower is tested when she runs into Richard at the video store. Rachel agrees to read The Shining if Joey reads Little Women. Phoebe''s athletic date has a problem with short shorts.', 23, '1997-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 14, 'The One with Phoebe''s Ex-Partner', 'Phoebe is reunited with her former singing partner who thinks "Smelly Cat" has hit potential; Chandler dates a woman with a prosthetic leg who also has some history with Joey. Meanwhile, Ross goes to a fashion seminar with Rachel, so she won''t go with Mark, but falls asleep in the middle of it.', 23, '1997-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 15, 'The One Where Ross and Rachel Take a Break', 'Wanting more time to focus on her new job, Rachel suggests that she and Ross take a break from their relationship. Ross later seeks solace at a party. Phoebe dates a diplomat who needs an interpreter to communicate with her. Chandler and Joey ponder a ménage a trois with a woman who seems hot for both of them.', 23, '1997-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 16, 'The One with the Morning After', 'Ross tries to prevent Rachel from learning his disturbing secret. She finds out anyway and they go back to her apartment to have a fight. The other four friends are trapped in Monica''s bedroom, forced to listen in.', 24, '1997-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 17, 'The One Without the Ski Trip', 'Ross and Rachel compete to spend time with their other friends. When a lonely Ross is excluded from Rachel''s ski trip with her pals, he visits Carol. On the way to the cabin, they run out of gas. Meanwhile, Chandler starts smoking again.', 23, '1997-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 18, 'The One with the Hypnosis Tape', 'Monica receives a tip from an admirer worth a small fortune then goes out with the guy. A hypnosis tape intended to assist Chandler to stop smoking has a rather strange side effect. Phoebe is upset when her 18-year-old half-brother, Frank Jr., makes a surprise announcement that he is getting married - to a woman more than twice his age.', 23, '1997-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 19, 'The One with the Tiny T-Shirt', 'Rachel goes on her first date after splitting from Ross... and it''s with Mark, her former colleague. Joey is cast in a play and develops a crush on his costar. Monica continues to date Pete, even though she is still not attracted to him.', 23, '1997-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 20, 'The One with the Dollhouse', 'Monica inherits a beautiful dollhouse that is too elaborate to play with, so Phoebe makes her own. Joey thinks he''s found his true love, and Rachel''s boss dates Chandler, placing her in a dangerous situation.', 23, '1997-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 21, 'The One with the Chick and the Duck', 'Monica considers a dream job as head chef in Pete''s new restaurant, but Phoebe fears there is more to the deal. Ross makes a sacrifice to help Rachel, who may have a broken rib. Meanwhile, Joey buys Chandler an unusual pet.', 23, '1997-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 22, 'The One with the Screamer', 'When Rachel finds out that Ross is bringing a date to the premiere of Joey''s big play, she finds one of her own. Ross alone concludes that her date is insane. Poor Phoebe is on hold for days with a company she needs to talk to before her phone warranty expires. Meanwhile, Joey''s play gets terrible reviews, but his co-star provides some comfort.', 23, '1997-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 23, 'The One with Ross''s Thing', 'Afflicted with a mysterious skin condition on his butt that doctors cannot identify the cause of, Ross seeks advice from Phoebe''s herbalist. Phoebe finds herself in a dilemma when she cannot choose between two guys. Monica can''t decide about Pete when she thinks he is going to propose.', 23, '1997-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 24, 'The One with the Ultimate Fighting Champion', 'To Monica''s horror, Pete wants to be the Ultimate Fighting Champion. Chandler has a problem when his new boss is slaphappy. Phoebe sets Ross up on a date with a woman who used to be bald. The group overhears a scandalous conversation at Central Perk.', 23, '1997-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 3), 25, 'The One at the Beach', 'Phoebe invites everyone to stay at her massage client''s beach house for the weekend. In search of her father, Phoebe meets someone who knows details about her family. Rachel expresses her jealousy of Ross'' uninhibited girlfriend and Joey nags the friends into agreeing to play strip poker with unintended results. Chandler wonders why Monica doesn''t think he''s serious after asking if she would ever date him.', 23, '1997-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 1, 'The One with the Jellyfish', 'Ross chooses between Rachel and his bald-headed girlfriend Bonnie. Phoebe struggles to deal with the revelation that her mother''s friend is actually her mother. Monica gets stung by a jellyfish, forcing Chandler and Joey to step up to the plate in order to relieve her pain.', 23, '1997-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 2, 'The One with the Cat', 'Phoebe believes that her adoptive mother''s spirit resides in a cat that jumped into her guitar case in Central Perk.  Monica goes on a date with Rachel''s hunky high-school boyfriend, who was cool in high-school, but a failure now. And when Joey and Chandler decide to sell the entertainment center, Joey takes stupidity to a new level.', 23, '1997-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 3, 'The One with the ''Cuffs', 'Monica caters a party for her mother, who still doesn''t quite know how to talk to her daughter. Chandler''s encounter with Rachel''s boss leads to an embarrassing situation. And an encyclopedia salesman takes advantage of Joey.', 23, '1997-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 4, 'The One with the Ballroom Dancing', 'Joey attempts ballroom dancing in order to help Monica and Rachel keep their illegal sublet. Phoebe is attracted to one of her massage clients. And Ross tries to help Chandler quit the gym.', 23, '1997-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 5, 'The One with Joey''s New Girlfriend', 'Chandler hits on a woman at Central Perk, not realizing she is Joey''s new girlfriend. He soon realizes he is very attracted to, possibly in love, with her. Ross and Rachel play the jealousy game in their relationships. And Phoebe desperately tries to catch a cold after discovering that her voice is sexier and her singing better when she has phlegm in her throat.', 23, '1997-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 6, 'The One with the Dirty Girl', 'Ross''s new girlfriend seems nearly perfect until he visits her house and discovers that her apartment is incredibly dirty.  Chandler helps Joey pick out a thoughtful present for Kathy''s birthday. Rachel attempts to finish a crossword puzzle by herself. And Phoebe helps Monica cater a funeral.', 23, '1997-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 7, 'The One Where Chandler Crosses the Line', 'Chandler must decide between the girl of his dreams and his best friend when he and Kathy share a passionate kiss. Needless to say, Joey is not happy when he finds out about it. And nobody wants to tell Ross how awful his keyboard playing is.', 23, '1997-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 8, 'The One with Chandler in a Box', 'Chandler agrees to spend Thanksgiving in a shipping crate as penance for kissing Kathy. The gang decides to give each other Secret Santa gifts. After Monica gets ice in her eye, she ends up visiting Richard''s son, who is as attracted to Monica as his father was.', 23, '1997-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 9, 'The One Where They''re Going to Party!', 'Chandler and Ross''s college friend Gandalf is planning to come to town. Gandalf is "the party wizard." Ross and Chandler are very excited until Gandalf cancels. However, they decide to make their own party with Joey''s help. Joanna squashes Rachel''s chance at a promotion. And when Monica fills in for a friend as food critic for a small newspaper, she must decide between a steady job as head chef of a restaurant she panned or keeping her catering business with her friend Phoebe.', 23, '1997-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 10, 'The One with the Girl from Poughkeepsie', 'Ross must decide whether to continue dating a girl he must travel two-and-a-half hours to see. Chandler sets Rachel up with a co-worker who misunderstands her intentions. Monica is being treated poorly by her new co-workers so she hires Joey just so she can fire him and show who''s the boss. And Phoebe tries to write the perfect holiday song.', 23, '1997-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 11, 'The One with Phoebe''s Uterus', 'Phoebe considers her options when her brother visits with his new wife and asks her to carry their child. Joey works as a tour guide at Ross''s museum and tries to tear down the walls between tour guides and scientists. And Chandler seeks advice from Monica and Rachel after he fears that he will not live up to Kathy''s sexual expectations--especially since the last guy she slept with before him was Joey.', 23, '1998-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 12, 'The One with the Embryos', 'Phoebe''s uterus is examined for implantation of the embryos. Meanwhile, a seemingly harmless game between Chandler and Joey against Monica and Rachel escalates into a full blown contest where the stakes are raised higher and higher.', 23, '1998-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 13, 'The One with Rachel''s Crush', 'After seeing Kathy''s play, Chandler becomes convinced she is cheating on him with her co-star. Rachel develops a crush on one of her customers. Monica becomes jealous when she realizes she is no longer the ''hostess''.', 23, '1998-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 14, 'The One with Joey''s Dirty Day', 'After a three-day fishing trip with his dad, Joey is in a jam when he doesn''t have time to take a shower before going to the set of Charlton Heston''s new movie.  Rachel, continuing to fawn over clothing shopper Joshua, sets Ross up with her boss''s niece Emily when she is unable to take her to the opera. And while Chandler is despondent after his breakup with Kathy, the girls take him to a strip club.', 23, '1998-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 15, 'The One with All the Rugby', 'Chandler runs into Janice, and finds her more irritating than ever. Meanwhile, Ross attempts to learn how to play rugby to impress Emily and Monica obsesses over an electric switch in her new apartment.', 23, '1998-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 16, 'The One with the Fake Party', 'With two days left until Emily''s departure back to England, Rachel throws a fake party for her, just so that she can see Joshua outside of work. And a pregnant (vegetarian) Phoebe craves meat.', 23, '1998-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 17, 'The One with the Free Porn', 'Chandler and Joey discover that they''re getting a free porno station on their TV. Monica encourages Ross to tell Emily he loves her just before she leaves for London. Phoebe gets some shocking news when she visits her OB-GYN.', 23, '1998-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 18, 'The One with Rachel''s New Dress', 'Rachel has an awkward encounter with Joshua''s parents. Phoebe is offered the chance to name one of the triplets. Ross becomes paranoid when Emily goes to London with Susan.', 23, '1998-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 19, 'The One with All the Haste', 'Ross proposes to Emily. Monica and Rachel try to win their apartment back from Chandler and Joey.', 23, '1998-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 20, 'The One with All the Wedding Dresses', 'Chandler takes Joey to a sleep clinic when he starts snoring. After Ross asks Monica to pick up Emily''s wedding dress, she tries it on and can''t stop wearing it. Meanwhile, jealous of Ross''s proposal to Emily, Rachel tries to talk Joshua into marriage.', 23, '1998-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 21, 'The One with the Invitation', 'As Ross and Emily send out wedding invitations, he and Rachel each look back on their relationship together while Joey and Chandler look for a purpose in life.', 23, '1998-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 22, 'The One with the Worst Best Man Ever', 'Joey convinces Ross to pick him as his best man instead of Chandler. He throws a great bachelor party, but the next morning he''s shocked to find out that the wedding ring is missing and he suspects that the stripper stole it. Meanwhile, Phoebe is experiencing major mood swings due to her pregnancy and the girls decide to throw her a baby shower to cheer her up, but it only makes matters worse.', 23, '1998-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 4), 23, 'The One with Ross''s Wedding', 'The gang heads over to London for Ross and Emily''s wedding. Joey can''t contain his excitement about London which annoys Chandler to no end and results in two of them arguing. While the guys are touring the city, Monica, together with Ross and Emily, visit the chapel where the wedding ceremony is supposed to take place only to find out that it''s being torn down prematurely.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 1, 'The One After Ross Says Rachel', 'In the aftermath of his Freudian slip, Ross tries to rescue his marriage with Emily.  Meanwhile, Chandler and Monica try and find a moment alone in order to continue their affair while overseas.', 23, '1998-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 2, 'The One with All the Kissing', 'Ross continues to try and mend his marriage to Emily. When Chandler accidentally kisses Monica in front of everyone before leaving for work, he tries to recover by kissing Rachel and Phoebe as well. Meanwhile, Phoebe starts getting irritated by everyone''s London stories.', 23, '1998-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 3, 'The One Hundredth', 'Phoebe is rushed to the hospital for the birth of her brother''s triplets. While there, Joey winds up with severe sympathy pains that turn out to be kidney stones. Meanwhile, Rachel tries to set Monica up on a date with a male nurse.', 23, '1998-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 4, 'The One Where Phoebe Hates PBS', 'Joey lands a job with a PBS telethon, which ignites an old hatred Phoebe has towards the network.  Meanwhile, Monica tries to convince Rachel that she''s dating someone from work to hide her relationship with Chandler. And Ross finally gets in touch with Emily and they try to work it out.', 23, '1998-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 5, 'The One with the Kips', 'Monica and Chandler plan an Atlantic City getaway in order to have an intimate weekend away from their friends.  Meanwhile, Ross prepares himself to tell Rachel that he can''t see her anymore.', 23, '1998-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 6, 'The One with the Yeti', 'Emily decides that the only way to continue her marriage with Ross is to have him get rid of all traces of Rachel in his apartment.  Meanwhile, Rachel and Monica mistake a hairy neighbor for a yeti.', 23, '1998-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 7, 'The One Where Ross Moves In', 'Chandler and Joey let Ross move in with them once his marriage to Emily falls apart.  Meanwhile, Phoebe gets involved with the local health inspector and Rachel becomes convinced that Danny is trying to seduce her with mind games.', 23, '1998-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 8, 'The One with All the Thanksgivings', 'Although the Thanksgiving meal is great, Chandler is still moody over his parent''s divorce during the holiday when he was a boy and Ross is depressed about his second divorce. The group reminisces about their worst Thanksgivings in order to cheer them up, and Monica''s worst memory is revealed.', 23, '1998-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 9, 'The One with Ross''s Sandwich', 'Joey starts to get uncomfortable with protecting Monica and Chandler''s secret, especially when it places him in embarrassing situations with the rest of the group. Meanwhile, Ross becomes enraged at work when someone swipes his turkey sandwich. Phoebe and Rachel enroll in a literature class.', 23, '1998-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 10, 'The One with the Inappropriate Sister', 'Joey teaches Ross how to be unemployed. Phoebe is working for the Salvation Army during the holidays. Monica is tired of Rachel''s obsessing about Danny and asks him to go out with her. Ross convinces Joey to write a play about himself. Phoebe is distressed after finding out that New Yorkers are mean. Rachel meets Danny''s sister and is dismayed when the two seem a little too playful. Phoebe vows a return to "Street Phoebe."', 23, '1998-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 11, 'The One with All the Resolutions', 'With the New Year, the friends make New Year''s resolutions. Ross resolves to try a new thing every day. Chandler resolves to not make fun of his friends for a week. Joey resolves to learn how to play the guitar, with Phoebe as his teacher. Rachel resolves to give up gossiping. Chandler nearly goes insane holding it all in. Ross is stuck in a sticky situation at his date''s apartment, in constricting and hot leather pants. Rachel discovers a big secret (Monica and Chandler) that threatens to spoil her resolution.', 23, '1999-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 12, 'The One with Chandler''s Work Laugh', 'Monica begins to hang out with Chandler during his work functions, since they don''t have to keep their relationship a secret among his coworkers.  However, she learns that Chandler has a second, more annoying personality when he''s around his boss.  Meanwhile, Ross learns that Emily is getting remarried and in his grief hooks up with an old nemesis of the gang: Janice.', 23, '1999-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 13, 'The One with Joey''s Bag', 'Phoebe''s grandmother dies, and Phoebe is shocked when her father turns up at the funeral. Meanwhile, Rachel gives Joey a "man''s bag" for an audition, and Chandler is scared to tell Monica he doesn''t like her massages.', 23, '1999-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 14, 'The One Where Everybody Finds Out', 'When the friends discover that Ugly Naked Guy is moving out of his apartment, Ross leaps at the opportunity to get his own place again. Phoebe finds out about Monica and Chandler''s relationship, and tries to get them to reveal the truth by seducing Chandler.', 23, '1999-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 15, 'The One with the Girl Who Hits Joey', 'Joey starts dating Katie, a little girl who packs a mean punch.  When Ross refuses to contribute to the retirement fund of the building''s maintenance man, he winds up offending everyone in the building. Meanwhile, Chandler freaks out about his relationship with Monica.', 23, '1999-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 16, 'The One with the Cop', 'Joey has a dream about Monica and becomes convinced he is in love with her. Meanwhile, Phoebe finds a police badge in Central Perk and uses it to go on missions of mercy. And Ross buys a new sofa but has trouble moving it up the stairs into his new apartment.', 23, '1999-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 17, 'The One with Rachel''s Inadvertent Kiss', 'Monica becomes jealous of Phoebe and Gary. Rachel has an awkward encounter when she interviews for a new job. Joey tries to meet a girl living in Ross''s building, but has trouble with finding her apartment.', 23, '1999-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 18, 'The One Where Rachel Smokes', 'Rachel decides to start smoking in order to avoid missing important meetings with her boss. Meanwhile, Ben gets offered an audition for a soup commercial, and Joey auditions to be Ben''s father during the ad. Also, Monica and Phoebe plan a surprise birthday party for Rachel together, but Monica takes over.', 23, '1999-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 19, 'The One Where Ross Can''t Flirt', 'As Joey''s Italian-speaking grandmother visits to watch him on TV, Ross has trouble flirting with the pizza delivery girl, and Rachel tries to find an earring of Monica''s that she has misplaced.', 23, '1999-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 20, 'The One with the Ride Along', 'While the guys go on a ride-along with Gary, Rachel accidentally deletes a message from Emily on Ross''s answering machine.', 23, '1999-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 21, 'The One with the Ball', 'Phoebe learns that Gary is going to ask her to move in with him and thinking this is way to fast, she tries to get Chandler to talk him out of this decision. Rachel buys an expensive sphynx cat but is disappointed when it doesn''t behave as she hoped it would. Meanwhile, Ross and Joey start throwing a ball while they are bored but it changes from a time-filler to a super-competitive obsession when Monica joins in.', 23, '1999-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 22, 'The One with Joey''s Big Break', 'Joey seems to have finally hit big when he gets offered a lead part in a movie shooting outside of Las Vegas. However, when Chandler begins expressing doubts about the film''s legitimacy, it causes a rift in their friendship. Also, Rachel gets an eye infection but is reluctant to seek treatment because of her eye phobia. And Phoebe is mad at Ross, but doesn''t know why.', 23, '1999-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 5), 23, 'The One in Vegas', 'Chandler decides the only way to mend his friendship with Joey is to fly out to Vegas and visit him. Phoebe is determined not to be left out on another adventure, so everyone winds up going. Trouble is in the water, however, when Chandler finds out that Monica had lunch with Richard. Meanwhile, Ross and Rachel try to embarrass each other after an awkward encounter.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 1, 'The One After Vegas', 'Ross and Rachel experience the world’s worst hangover when they realize they’ve gotten married.  Chandler and Monica back away from their own altar plans.  Phoebe and Joey head back to New York in the taxi cab.', 23, '1999-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 2, 'The One Where Ross Hugs Rachel', 'Monica and Chandler decide to move in together, leading Rachel to believe that all three of them will be roommates, and Monica doesn''t want to tell her the truth.  Meanwhile, Ross tries to keep Rachel from learning that their marriage hasn''t been annulled.', 22, '1999-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 3, 'The One with Ross''s Denial', 'Monica and Chandler disagree over how to redecorate Rachel''s old room. Joey advertises for a "non-ugly" roommate. Ross is unwilling to accept that he still has feelings for Rachel.', 22, '1999-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 4, 'The One Where Joey Loses His Insurance', 'Joey''s health benefits lapse just as he develops a hernia. Ross is asked to give a lecture at NYU and eager to impress his students, he puts on a fake British accent. Meanwhile, Phoebe gets some bad news from her psychic.', 22, '1999-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 5, 'The One with Joey''s Porsche', 'Ross and Rachel try to get an annulment, but run into some legal obstacles. Joey finds keys to a Porsche in Central Perk and discovers some perks of being a fancy car owner. Meanwhile, Chandler, Monica and Phoebe babysit the triplets.', 22, '1999-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 6, 'The One on the Last Night', 'On the last night before Chandler and Monica move in together, Monica and Rachel argue, while Chandler tries to give Joey money to help him pay the upcoming bills.', 22, '1999-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 7, 'The One Where Phoebe Runs', 'Now roommates Phoebe and Rachel decide to start running together, but Rachel is embarrassed by Phoebe''s odd running style. Joey finds a sexy new female roommate and tries very hard not to flirt with her. Meanwhile, Chandler decides to surprise Monica by cleaning the apartment, but forgets where everything goes. Ross tries to help him remedy the situation.', 22, '1999-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 8, 'The One with Ross''s Teeth', 'Ross goes too far while trying to impress a date by over-whitening his teeth. Rachel uses gossip to get her boss to like her after Phoebe supposedly makes out with Ralph Lauren. Meanwhile, Chandler convinces Joey that the changes Janine has introduced to their old apartment is making it too girly.', 22, '1999-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 9, 'The One Where Ross Got High', 'It''s Thanksgiving and Monica''s parents are coming to visit, which is a problem because, not only they do not like Chandler, they also don''t know that he and Monica are living together. Rachel is tasked with making a Thanksgiving dessert, but she does so with mixed results. Meanwhile, Joey and Ross are eager to finish the dinner and leave, because they want to go to a Thanksgiving party with Janine and her dancer friends.', 23, '1999-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 10, 'The One with the Routine', 'Janine gets an invitation to dance on "Dick Clark''s New Year''s Rockin'' Eve" and she invites Joey, Monica and Ross to join her. Being huge fans of the show, Monica and Ross get overly excited. At the taping, Joey tries to kiss Janine at midnight and Monica and Ross resurrect their dance routine from high school. Meanwhile, Rachel, Phoebe and Chandler look for Monica''s Christmas presents.', 22, '1999-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 11, 'The One with the Apothecary Table', 'Rachel orders an apothecary table from Pottery Barn, which is a problem because Phoebe hates the mass-producing company. After Janine and Joey double date with Chandler and Monica, Janine tells Joey that she thinks the other two are boring. Ross buys a new apothecary table too, which causes problems for Rachel. After a confrontation with Monica and Chandler, Joey breaks up with Janine and she moves out.', 22, '2000-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 12, 'The One with the Joke', 'After a joke gets published in Playboy, Chandler and Ross have an argument about who came up with it first. Meanwhile, a wayward remark of Phoebe''s leads to trouble between the girls and a broke Joey starts working at Central Perk.', 22, '2000-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 13, 'The One with Rachel''s Sister (1)', 'Joey gets in trouble for giving attractive female customers free food at Central Perk. A sick Monica desperately tries to convince Chandler that she''s not sick. After her father cuts her off, Rachel''s sister Jill comes to town. Rachel encourages her to start an independent life by finding a job and an apartment, but one thing leads to another and Jill ends up asking Ross out on a date. Even though Rachel doesn''t want to admit it, she clearly isn''t okay with that...', 22, '2000-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 14, 'The One Where Chandler Can''t Cry (2)', 'Chandler admits that he hasn''t cried since he was a child. Phoebe discovers that Ursula is starring in porno movies using her name. Rachel desperately tries to stop Ross and Jill from starting a relationship.', 23, '2000-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 15, 'The One That Could Have Been', 'Barry and Mindy''s impending divorce prompts the gang to fantasize about what their lives might be like if they''d all taken different courses. Ross is still married to Carol, and Rachel is married to Barry, but fawning over famous soap star Joey Tribbiani. Monica is still fat and dating a doctor. Chandler is an aspiring writer and Phoebe is a Wall Street shark for Merrill Lynch.  The gang continue to fantasize about how different their lives could have been. Carol and Ross decide to have a threesome to spice up their marriage. Rachel goes to Joey''s but is incredibly nervous about cheating and gets drunk. Meanwhile, Monica''s dinner date falls through and Chandler tries to cheer her up but things take an unexpected turn.', 45, '2000-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 16, 'The One with Unagi', 'Joey tries to earn some extra money by entering a medical study, however, there''s a slight problem: the study is for identical twins. Rachel and Phoebe take self-defense classes, but Ross attempts to give them a lesson in Unagi instead. Meanwhile, Chandler and Monica agree to give each other homemade presents for Valentine''s Day.', 22, '2000-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 17, 'The One Where Ross Dates a Student', 'At the end of semester Ross gets his student evaluations and one of them writes that he''s hot. It turns out to be a cute girl named Elizabeth and even though it could cost him his job, Ross considers dating her. An ex-girlfriend of Chandler''s from college is directing the new Al Pacino movie and Joey asks Chandler for help with getting an audition. Meanwhile, after a fire ruins Phoebe and Rachel''s apartment, they''re forced to find temporary living spaces with Monica and Joey.', 22, '2000-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 18, 'The One with Joey''s Fridge', 'After Joey''s fridge breaks, he tries to cajole his friends into helping him buy a new one. Meanwhile, Ralph Lauren is organizing a charity ball and Rachel looks for a date, however, unexpectedly it turns into a competition between Monica & Chandler against Phoebe for finding the best candidate. Ross continues to date Elizabeth, but he gets nervous when she makes plans for a spring break at Daytona Beach.', 22, '2000-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 19, 'The One with Mac and C.H.E.E.S.E.', 'Joey gets an audition for the lead character in a new TV show. When the audition is rescheduled, Chandler takes the message but forgets to tell Joey. When Joey misses the audition, he gets upset and the group reminisces about their mishaps in the past.', 22, '2000-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 20, 'The One Where Ross Meets Elizabeth''s Dad', 'Ross meets Elizabeth''s father for the first time and unfortunately he takes an instant disliking to Ross. However Paul does hit it off with Rachel and she tries to talk Ross up but does so with mixed results. Joey almost gets fired from "Mac and C.H.E.E.S.E." after offending the operator of the robot. Meanwhile, Phoebe writes a book based on Monica and Chandler.', 23, '2000-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 21, 'The One Where Paul''s the Man', 'While visiting an art museum, Monica puts her name on a two-year waiting list to use the museum for a wedding. Accidentally Chandler finds out about this and freaks out. Meanwhile, Paul threatens to have Ross fired from the university if he continues to date Elizabeth, however, that doesn''t stop the two of them from going to her dad''s mountain cabin over the weekend. Unfortunately for them, Paul has the same idea to bring Rachel there.', 23, '2000-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 22, 'The One with the Ring', 'Chandler and Phoebe shop for a ring for Monica. Chandler finds the perfect one, but Phoebe accidentally lets it get away. While Chandler is busy with getting the ring back, Joey and Ross are lead to believe that he''s mad at them, so they decide to team up and give him a cold shoulder treatment. Rachel continues to date Paul and wants him to open up to her, however, he opens up a bit too much.', 23, '2000-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 6), 23, 'The One with the Proposal', 'Chandler plans to propose to Monica at dinner, but his plans go awry when Richard shows up at the same restaurant. Meanwhile, Phoebe and Joey join Rachel at a charity auction only to discover that Joey isn''t aware what a silent auction is. And Ross and Elizabeth''s relationship comes to a crossroad.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 1, 'The One with Monica''s Thunder', 'The gang celebrate Monica and Chandler''s engagement. Phoebe wants to be the musician at the wedding and comes up with a new song, while Joey tries to dress and act like a 19-year-old for an audition. Ross and Rachel briefly reunite and after Monica catches them kissing, she''s convinced that Rachel is trying to steal her thunder.', 22, '2000-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 2, 'The One with Rachel''s Book', 'As Monica starts planning her wedding she''s shocked to find out that her parents have spent her entire wedding fund. However, her spirits are restored when she discovers that Chandler has enough savings for her dream wedding scenario. Phoebe temporarily moves into Ross''s apartment, bringing her massage clients with her. This leads to some weird encounters for Ross. Meanwhile, Joey mocks Rachel when he finds an erotic novel she is reading.', 22, '2000-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 3, 'The One with Phoebe''s Cookies', 'Monica tries to figure out Phoebe''s grandmother''s secret chocolate chip cookie recipe. Meanwhile, Rachel tries to teach Joey how to sail, and Chandler has an awkward encounter when he tries to bond with Monica''s father.', 21, '2000-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 4, 'The One with Rachel''s Assistant', 'While hiring a new assistant, Rachel is torn between hiring a much more qualified woman, or a handsome but inexperienced young man. Monica, Chandler and Ross engage in a war of secret sharing after Monica and Chandler vow to be more honest. Meanwhile, Joey has problems when his TV show is cancelled after just one airing.', 22, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 5, 'The One with the Engagement Picture', 'While taking an engagement picture for himself and Monica, Chandler cannot make anything but a weird face. Meanwhile, Rachel enlists Joey to take Tag out for a night on the town. Also, Phoebe and Ross date a couple in the middle of a divorce.', 22, '2000-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 6, 'The One with the Nap Partners', 'Joey and Ross accidentally take a nap together - and much to their dismay, find that they liked it. Phoebe and Rachel compete to become Monica''s maid of honor.', 22, '2000-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 7, 'The One with Ross''s Library Book', 'Rachel and Phoebe befriend a girl Joey''s dating and they try to convince him to get more serious with her, however he''s reluctant to do so. At least at first. Meanwhile, Ross discovers that his doctoral dissertation is hosted at university''s library and is very excited about the fact. Unfortunately, he soon finds out that students aren''t exactly reading it, but rather engaging in other ''physical activities'' in the paleontology section. Also, Monica runs into Janice and before she knows it, Janice has invited herself to Monica''s wedding. Needless to say that neither she nor Chandler are exactly ecstatic about it and they both try to find a way to tactfully uninvite her.', 22, '2000-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 8, 'The One Where Chandler Doesn''t Like Dogs', 'Ross drives himself insane when he can''t name all 50 states in a simple game. Tag joins the gang for Thanksgiving dinner, where Joey accidentally spills the beans about Rachel''s crush on him. Phoebe sneaks a dog into the apartment, making Chandler extremely nervous.', 22, '2000-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 9, 'The One with All the Candy', 'When Phoebe tells the gang about how she was too poor to have a bike as a child, Ross goes out and buys her one. While Phoebe absolutely loves the bike, the gang soon discovers that she doesn''t actually know how to ride one. Meanwhile, Monica decides to make candy in order to get to know her neighbours, and while they all love the candy, nobody is particularly interested in Monica herself. Rachel and Tag try to hide their relationship at work, but things go awry when Rachel writes a playful work evaluation of Tag that he accidentally turns in to Human Resources.', 22, '2000-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 10, 'The One with the Holiday Armadillo', 'Ross''s plans to teach Ben about Hanukkah are continually thwarted when the young boy can''t get his mind off of Santa. Meanwhile, Phoebe prepares to move back into her refurbished apartment, with or without Rachel. However, she''ll stop at nothing to get Rachel to go with her, including buying Joey a drum set. Monica is mystified by Chandler''s inability to tip properly.', 22, '2000-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 11, 'The One with All the Cheesecakes', 'Phoebe gets upset with Joey when he blows off dinner with her for a date, however only a few days later she finds herself in the same situation but with their roles reversed. Meanwhile, Chandler and Rachel enjoy a cheesecake that gets delivered to their address by accident. They feel guilt-ridden at first, but it''s just too delicious. Also, Ross and Monica attend a wedding reception of their cousin and find themselves in an awkward situation.', 22, '2001-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 12, 'The One Where They''re Up All Night', 'After the gang head up to the roof to see a passing comet, separate events unfold that lead to them all having a sleepless night.', 22, '2001-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 13, 'The One Where Rosita Dies', 'Rachel accidentally breaks Joey''s armchair (that he''s named Rosita) and while they''re out shopping for a new one, it appears that Rosita has magically "healed" herself. Meanwhile, Phoebe takes a temp job as a telemarketer for an office supply company and when her first client turns out to be suicidal, she goes out of her way to talk him out of it. Also, Ross and Monica find out that their parents are selling their childhood home.', 22, '2001-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 14, 'The One Where They All Turn Thirty', 'When Rachel turns 30, the gang reminisces about their 30th birthdays. Ross buys a sports car to look cool, Monica gets drunk, and Phoebe, while trying to patch things up with Ursula, discovers that she is actually 31.', 22, '2001-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 15, 'The One with Joey''s New Brain', 'Joey''s character on Days of Our Lives is awakened from his coma with a brain transplant from one of the show''s most legendary characters. Ross practices the bagpipes for Monica and Chandler''s wedding. Meanwhile, Phoebe and Rachel fight over a guy who left his cell phone in Central Perk.', 23, '2001-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 16, 'The One with the Truth About London', 'Chandler is shocked to find out who Monica really wanted to sleep with the night they first got together in London. Meanwhile, Rachel gets into trouble with Ross when she teaches Ben practical jokes.', 22, '2001-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 17, 'The One with the Cheap Wedding Dress', 'Monica regrets telling a woman about a discount bridal shop when they end up fighting over the same dress. Meanwhile, Joey and Ross discover that they''re dating the same girl.', 22, '2001-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 18, 'The One with Joey''s Award', 'Joey is nominated for a Soapie Award for his part on Days of Our Lives, and while he doesn''t win, he ends up with an award anyway - together with his partner in crime, Rachel. Meanwhile, Ross finds himself in an awkward position when one of his students proclaims that he failed his midterm because he''s in love with Ross. Also, Monica freaks out a little when she realizes that after marrying Chandler she''s not gonna experience a rush of dating someone new ever again. In a surprising change of roles, Chandler becomes a voice of reason that calms her.', 22, '2001-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 19, 'The One with Ross and Monica''s Cousin', 'Joey auditions for a big movie role which will require him to appear naked. A problem arises, however, when the part calls for an uncircumcised man. Meanwhile, Rachel and Phoebe go through the trouble of organizing  a last minute bridal shower for Monica. And Ross becomes attracted to his cousin after she visits.', 22, '2001-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 20, 'The One with Rachel''s Big Kiss', 'At Central Perk Rachel runs into her friend from college, Melissa, and it turns out they share something more than just a friendship. Meanwhile, Monica plans the seating arrangement for the wedding and is taken by surprise when Joey mentions that his parents are coming to the wedding too. Also, Chandler and Ross argue who gets to wear a celebrity tux for the event.', 22, '2001-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 21, 'The One with the Vows', 'Monica and Chandler are getting married in four weeks and have to write their vows, but neither has a clue what to say, so they reflect on their past. In the end, the only real problem is who will be saying the vows first.', 22, '2001-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 22, 'The One with Chandler''s Dad', 'When Monica''s Porsche shows up again, Ross and Rachel hit the freeway together and it turns out to be an adventurous ride. Meanwhile, Chandler and Monica go off to Vegas to find Chandler''s estranged father. And back at home, Joey proves his masculinity to Phoebe.', 22, '2001-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 7), 23, 'The One with Chandler and Monica''s Wedding', 'So close to the wedding, Chandler suddenly realizes the overwhelming meaning of getting married and takes off without warning anyone. Meanwhile, Joey acts opposite a famous actor in a movie, but can''t bring himself to tell him that he spits when he says his lines. Phoebe and Ross try to find Chandler before the wedding starts, while Rachel tries to hinder Monica, so that she doesn''t find out the shocking news. On the day of the wedding Joey encounters a scheduling problem, while Phoebe and Rachel come across a surprising discovery.', 44, '2001-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 1, 'The One After "I Do"', 'The excitement of Monica and Chandler''s wedding is diminished by the news that someone may be pregnant. Chandler''s hopes of not embarrassing Monica on the dance floor are ruined by his slippery new shoes, and Ross'' attempts to flirt with an attractive wedding guest.', 23, '2001-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 2, 'The One with the Red Sweater', 'Speculation regarding the father of Rachel''s baby leads to a misunderstanding when Joey discovers a red sweater left behind in a one-night stand Rachel had. Meanwhile, Chandler and Ross search for the disposable cameras left behind at the wedding and Monica goes on a present-opening binge.', 22, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 3, 'The One Where Rachel Tells...', 'Chandler and Monica prepare to leave for their honeymoon as Rachel prepares to tell Ross that he''s the father of her baby. While traveling, Monica and Chandler become jealous of another honeymooning couple who get bumped to first class on the airplane. Meanwhile, Joey and Phoebe scheme to get inside the newlyweds'' apartment after discovering that they don''t have a key.', 23, '2001-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 4, 'The One with the Videotape', 'Monica and Chandler return from their honeymoon with stories of a couple that they met on the flight back, but soon discover that the couple gave them a wrong number. Meanwhile, Ross and Rachel tell everyone about the night they were together, however, their stories differ as to who made the first move. While Ross emphatically defends his side of the story, he accidentally reveals that he has the encounter on videotape. Unsurprisingly, everyone wants to see it.', 23, '2001-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 5, 'The One with Rachel''s Date', 'Phoebe begins dating a guy who works for Monica as a sous-chef, however, they soon find themselves in an awkward position when things don''t work out for either of them. Meanwhile, Ross discovers that a co-worker of Chandler''s has been calling him Toby for five years. And Joey sets Rachel up on a date with one of his co-stars, which freaks Ross out when he realizes that this guy might become a step-father of his and Rachel''s baby.', 22, '2001-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 6, 'The One with the Halloween Party', 'Monica and Chandler decide to throw a costumed Halloween party. Meanwhile, Phoebe runs into Ursula, who''s preparing to get married soon, and as a courtesy invites her and her fiancé to the party. When they finally meet, Phoebe takes an instant liking to him, but soon she discovers that he knows nothing about the "real" Ursula.', 22, '2001-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 7, 'The One with the Stain', 'Chandler hires a maid, whom Monica suspects is stealing her clothing. Eric has broken up with Ursula and is ready to date Phoebe, except for one problem: he can''t look at her without seeing Ursula. Meanwhile, Ross tries to get Rachel an apartment in his building, but the woman living there isn''t in a hurry to die, and Joey wants Rachel to stay with him.', 22, '2001-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 8, 'The One with the Stripper', 'Chandler finds out that Monica had a bachelorette party with a stripper, even though they promised not to have bachelor/bachelorette parties. Monica feels bad about it, so she organizes a bachelor party including a stripper for Chandler, however, the only one excited about it seems to be Joey. Meanwhile, Rachel prepares to have dinner with her dad and tell him that she''s pregnant and it doesn''t go particularly well for either of the involved parties.', 22, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 9, 'The One with the Rumor', 'Monica invites Will, an old high school friend of her and Ross over for a Thanksgiving dinner, unaware that he isn''t too fond of Rachel. Meanwhile, Joey vows to eat an entire turkey by himself, and Chandler and Phoebe pretend to watch a football game in order to avoid helping in the kitchen.', 22, '2001-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 10, 'The One with Monica''s Boots', 'Chandler is peeved when Monica splurges on an expensive pair of boots. Meanwhile, Phoebe learns that Ben and Sting''s son attend the same school and she angles to meet the celebrity and get concert tickets. Also, after Joey''s sister Dina tells him that she''s pregnant, he freaks out and goes to find the father to marry them. Rachel tries to calm him down.', 22, '2001-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 11, 'The One with Ross''s Step Forward', 'Ross starts to panic when Mona suggests that the two of them could send out a holiday card together, thinking that their relationship is starting to move too fast. Chandler''s newly divorced boss tries to get Monica and Chandler to go out to a dinner with him, but Monica can''t stand him, so Chandler steps up to cover for her. Meanwhile, Rachel''s hormones start acting up due to her pregnancy, causing her to hit on almost every guy she meets.', 22, '2001-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 12, 'The One Where Joey Dates Rachel', 'Phoebe gets Monica and Chandler a Ms. Pacman arcade game for a wedding present, which leads to some heavy competition between Monica, Phoebe, and, surprisingly, Chandler. Ross gets to teach an advanced class because of a retiring professor, but soon learns that its on the other side of town, and he doesn''t have enough time to get there. Meanwhile, Joey takes Rachel to dinner on a pretend date and they have a great time together, however, at the end of the night things take an unexpected turn.', 22, '2002-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 13, 'The One Where Chandler Takes a Bath', 'Monica turns Chandler on to the concept of taking a bath to relax, complete with scented oils and candles. Ross and Rachel toss baby names back and forth while deciding whether to learn the baby''s sex. Meanwhile, Joey struggles with his feelings for Rachel.', 22, '2002-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 14, 'The One with the Secret Closet', 'Chandler''s very curious about a locked closet by the bathroom in their apartment, but Monica won''t tell him what is inside. After Phoebe convinces Monica to get a massage from her, she soon finds out that Monica makes sexual noises during the process, which makes Phoebe very uncomfortable. Meanwhile, Rachel feels her baby kick for the first time and Ross is upset when he can''t be more involved in Rachel''s pregnancy issues.', 22, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 15, 'The One with the Birthing Video', 'During Valentine''s Day, Chandler and Monica discover the miracle of birth by watching an extremely graphic video. Ross hides the fact that Rachel is now living with him from Mona, which only gets him into more trouble. Meanwhile, Phoebe tries to help with Joey''s depression caused by his feelings for Rachel by lending him the world''s happiest dog.', 22, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 16, 'The One Where Joey Tells Rachel', 'After Joey reveals to Ross that he''s in love with Rachel, Ross has a hard time accepting this revelation. However, after giving it some thought, he convinces Joey to tell Rachel how he feels. So he does exactly that by taking Rachel out to dinner, however, her reaction to the news isn''t quite what he expected. Meanwhile, Phoebe claims that she has met Monica''s soulmate which makes Chandler really anxious.', 21, '2002-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 17, 'The One with the Tea Leaves', 'At Central Perk Phoebe does a reading of tea leaves which tell her that she''s soon going to meet a man of her dreams. In fact, she does meet a man she keeps constantly bumping into, however, he turns out to be a bit creepy to say the least. Meanwhile, after their conversation, things between Joey and Rachel are still weird and Joey keeps finding excuses to avoid her. As a result Rachel comes up with a rather crazy problem at work to draw him into a conversation. She doesn''t realize though, how far he''s willing to go to help with her fake problem after their conversation is over. Also, Ross tries to retrieve his favorite shirt from Mona''s, interrupted when she returns home with a date.', 22, '2002-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 18, 'The One in Massapequa', 'Everybody prepares to go out to Long Island for the elder Gellers'' 35th wedding anniversary party. Monica struggles to prepare the perfect toast that would make everybody cry. Meanwhile, Ross and Rachel discover that his parents have told people they''re married and they decide to just go along with it for the night. However, Rachel gets carried away a little telling stories about their "wedding" that didn''t happen. Also, Phoebe invites her new boyfriend, Parker, who is extremely enthusiastic.', 22, '2002-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 19, 'The One with Joey''s Interview', 'Joey prepares for an interview with Soap Opera Digest, although he''s afraid of saying something stupid and getting himself into trouble, so he enlists his friends to make sure things go well. During the interview, he reminisces about his past acting experiences, his friends and his romantic life.', 22, '2002-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 20, 'The One with the Baby Shower', 'Monica and Phoebe throw Rachel a baby shower but forget to invite Rachel''s mom. During the baby shower Rachel panics when she realizes she has no idea how to look after the baby after the birth. Meanwhile, Joey auditions for a job as a host for a new game show called "Bamboozled", and Chandler and Ross help him practice.', 22, '2002-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 21, 'The One with the Cooking Class', 'Monica''s restaurant gets a bad review in the Post. After confronting the critic who wrote it, she decides to join a cooking class, with Joey in tow. Meanwhile, Rachel gets jealous when Ross hits it off with a woman at the baby department store. And Chandler prepares for a job interview after Phoebe tells him that he makes a bad first impression.', 22, '2002-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 22, 'The One Where Rachel Is Late', 'Monica and Phoebe bet on when Rachel''s baby will be born as the due date comes and goes as Rachel becomes extremely irritable. Meanwhile, Joey invites Chandler to his big movie premiere and he manages to fall asleep during it. Also, Ross attempts to help Rachel speed things along by trying every possible method suggested by the doctor, except one.', 22, '2002-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 8), 23, 'The One Where Rachel Has a Baby', 'Ross and Rachel go to the hospital to have their baby, but it''s a long labor. They get stuck in a semi-private room, and many other couples come and go before Rachel is ready to deliver - the last couple being Janice and her new husband. Meanwhile, Chandler and Monica decide to start trying to have a baby, but can''t find an empty hospital room where they wouldn''t be disturbed. Also, Phoebe meets a handsome stranger and "recruits" Dr. Drake Ramoray to gather some personal information about him.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 1, 'The One Where No One Proposes', 'Following Rachel''s acceptance of Joey''s accidental proposal, confusion reigns as Rachel wonders whether it was the right thing to do and Phoebe can''t seem to mind her own business. Finally, Rachel, Ross and Joey get together and figure out that no one was actually going to propose. Meanwhile, Mr. Geller walks in on Monica and Chandler having sex in a closet.', 24, '2002-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 2, 'The One Where Emma Cries', 'Chandler, having trouble getting enough sleep at home, falls asleep in a meeting and accidentally agrees to run his company''s Tulsa office. Emma won''t stop crying after Rachel interrupts her nap; Monica and Phoebe try to help get her back to sleep. Meanwhile, Ross is still mad at Joey, and breaks his finger trying to punch him.', 24, '2002-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 3, 'The One with the Pediatrician', 'Rachel''s pediatrician drops her as a client because she calls him incessantly to ask about any insignificant issue concerning Emma, so now she must find a new one, which puts Ross in an awkward situation. Meanwhile, Joey arranges a blind date for Phoebe. Also, as Chandler and Monica are preparing to leave for Tulsa, Monica receives a job offer from a prestige restaurant in Manhattan.', 24, '2002-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 4, 'The One with the Sharks', 'After Phoebe has a talk with Ross, it prompts her to realize that she''s never had a long term relationship. Monica makes a startling discovery while visiting Chandler in Tulsa. Also, Joey goes on a date with an attractive woman and discovers that her apartment seems really familiar, although he doesn''t remember sleeping with her before.', 24, '2002-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 5, 'The One with Phoebe''s Birthday Dinner', 'The friends are looking forward to getting together and celebrating Phoebe''s birthday. However, on the day of the party, Ross struggles to convince Rachel to leave Emma with Mrs. Geller babysitting, and Monica and Chandler get into an argument, after Monica discovers that he''s been smoking. All of this causes them to be incredibly late, leaving Phoebe and Joey alone at a restaurant with a table for six.', 24, '2002-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 6, 'The One with the Male Nanny', 'Ross and Rachel hire a nanny for Emma named Sandy and things seem to be going great. However, Ross is uncomfortable having a male nanny. Meanwhile, Chandler becomes upset when Monica says that somebody from her new job is the funniest guy she''s ever met. Also, after Phoebe and Mike  decide to take their relationship to a new level and exchange apartment keys, Phoebe gets a surprise visit from her ex-boyfriend David.', 33, '2002-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 7, 'The One with Ross''s Inappropriate Song', 'Ross finds a way to make Emma laugh - singing Sir Mix-A-Lot''s "Baby Got Back." Needless to say, Rachel isn''t as amused, once she finds out. Meanwhile, Phoebe meets Mike''s parents and tries her best to leave a good impression. Also, while viewing Richard''s old apartment, Joey and Chandler discover a video tape with Monica''s name on it, which causes Chandler to freak out, since he thinks it''s a sex tape.', 24, '2002-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 8, 'The One with Rachel''s Other Sister', 'Rachel''s sister Amy tags along for Thanksgiving at Monica''s place, because her (married) boyfriend cancels their plans. While watching the parade, Joey realizes that he forgot to show up for the Days of Our Lives cast float, and he asks Phoebe''s help to come up with a believable lie. The dinner goes fairly well, however, Monica constantly obsesses about anybody damaging her best china. To make matters worse, Amy comes up with a crazy scenario involving Emma, which sparks a massive argument among the gang.', 26, '2002-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 9, 'The One with Rachel''s Phone Number', 'Joey becomes convinced that Monica is having an affair, after Chandler sneaks back into town without him knowing, in order to have some alone time with his wife. Meanwhile, Rachel and Phoebe have a girls night out, and Rachel gives her phone number to a guy they meet at a bar. Also, Ross and Mike try to hang out together but it doesn''t go very well, since they can''t find a common interest to talk about.', 24, '2002-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 10, 'The One with Christmas in Tulsa', 'Everyone in the gang gets a little upset when Chandler announces that he''ll be spending Christmas and New Year''s Eve in Tulsa because of work. To make matters worse, Monica gets quite jealous when she finds out that one of Chandler''s co-workers is a former Miss Oklahoma runner-up. After doing some retrospection, Chandler decides to quit his job.', 24, '2002-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 11, 'The One Where Rachel Goes Back to Work', 'Chandler starts looking for a job and is anxious about having a baby with Monica while uncertain about his career prospects. Meanwhile, Rachel visits work and finds out that during her leave, a guy named Gavin has been temporarily assigned to take care of her job. She starts to feel insecure about her job position and decides to come back from her leave early. Also, Phoebe works as an extra on Joey''s TV show and brings even more drama to the set.', 24, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 12, 'The One with Phoebe''s Rats', 'Gavin gives Rachel a very interesting birthday gift while Ross begs Joey to stay away from Emma''s hot new nanny. Meanwhile, Mike meets and then accidentally murders Phoebe''s unusual pet.', 24, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 13, 'The One Where Monica Sings', 'A night at Mike''s piano bar gives Monica a very showy moment in the spotlight. Ross struggles to move on after witnessing Gavin and Rachel kiss. Meanwhile, Chandler employs his secret skill to repair Joey''s botched eyebrow-waxing job.', 31, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 14, 'The One with the Blind Dates', 'Phoebe and Joey purposely set Ross and Rachel up on bad dates in the hopes they''ll get back together. Meanwhile, Monica and Chandler babysit Emma, and aren''t being as responsible as they should be.', 24, '2003-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 15, 'The One with the Mugging', 'Joey endures a draining audition at the hands of a pompous actor-director. Ross and Phoebe discover a secret link after being mugged together on the street. Chandler''s advertising internship gets off to an impressive start.', 23, '2003-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 16, 'The One with the Boob Job', 'While reviewing their monthly expenses, Monica and Chandler discover that their situation is less than stellar. This results in Monica asking Joey to lend her some money without telling Chandler. When Chandler eventually finds out, Joey comes up with a lie that Monica needs the money for breast enhancement procedure. Meanwhile, Phoebe gets really excited as she and Mike decide to move in together, but her excitement quickly dissipates once she discovers that Mike doesn''t see himself getting married ever again. Also, Rachel''s attempt to baby-proof the apartment tampers with a frustrated Joey''s sanity.', 24, '2003-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 17, 'The One with the Memorial Service', 'Chandler''s jokey entry on his and Ross''s college website leads to a faux burial service for the allegedly dead and obviously unpopular Gellar. Meanwhile, Joey is unwilling to give his favorite stuffed animal, Hugsy, to Emma. And Phoebe asks Monica to help her avoid a post-breakup tryst with Mike.', 24, '2003-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 18, 'The One with the Lottery', 'Monica leads the gang, except for a scoffing Ross, to purchase a bunch of lottery tickets for the multi-million-dollar powerball jackpot. However, as they gleefully plot about how they will spend the fortune if they win, they start bickering among themselves until Phoebe takes matters into her own hands. Meanwhile, Chandler frets as he waits for a phone call about a hiring job position and Rachel thinks baby Emma is close to saying her first words.', 23, '2003-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 19, 'The One with Rachel''s Dream', 'After visiting the set of "Days of Our Lives", Rachel catches herself dreaming about a romantic encounter with Joey. Meanwhile, Chandler buys a non-refundable weekend getaway for himself and Monica, but when she can''t get time off at work, Ross joins him. Also, Phoebe takes advantage of Monica''s restaurant clientele.', 25, '2003-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 20, 'The One with the Soap Opera Party', 'Joey secretly throws a party on the roof of his building for the "Days of Our Lives" cast and he reluctantly invites the rest of the gang, once they discover his plans. Meanwhile, Ross meets a new colleague, Charlie, and is instantly attracted to her, however, he feels intimidated once he learns about her accomplished ex-boyfriends. Also, everyone forgets to tell Chandler about the change of plans and he gets stuck at a theater play by himself.', 24, '2003-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 21, 'The One with the Fertility Test', 'Joey comes to Ross for advice on dating Charlie, since they don''t share much of the same interests. Meanwhile, Chandler and Monica bump into Janice at a fertility clinic. Also, Rachel has a gift certificate for a massage at a fancy massage place which Phoebe doesn''t want her to use, since she doesn''t approve of big corporations.', 28, '2003-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 22, 'The One with the Donor', 'Rachel and Phoebe take Joey''s girlfriend Charlie shopping, where she overhears the two of them gossiping about Joey. Meanwhile, Ross gives a presentation to a fellow professor in the hopes of getting the role of keynote speaker at the paleontology convention in Barbados. Also, Monica and Chandler consider alternate pregnancy options making some people really uncomfortable in the process.', 25, '2003-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 9), 23, 'The One in Barbados', 'The gang heads down to Barbados for the paleontology conference. While Ross and Charlie are excited about attending multiple seminars, the rest of the gang just want to enjoy their time on the beach but the rainy weather prevents them from doing so. Things, however, are far from boring - Phoebe discovers that she still has feelings for Mike even though she enjoys spending time with David, Rachel feels lonely and struggles to keep her feelings about Joey to herself, and Chandler is amused by Monica''s hair.', 52, '2003-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 1, 'The One After Joey and Rachel Kiss', 'After leaving Barbados, Joey and Ross both attempt to come clean to each other that they''re dating Rachel and Charlie, however, various obstacles constantly get in their way. Meanwhile, Monica gets a new haircut much to Chandler''s dismay and Phoebe finds out that Mike has another girlfriend.', 30, '2003-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 2, 'The One Where Ross Is Fine', 'After Ross finds out about Joey and Rachel''s relationship, he invites Rachel, Joey and Charlie to a dinner party at his apartment, which ends up being really uncomfortable for everyone involved. Meanwhile, Monica and Chandler are overwhelmed by various adoption options and Phoebe suggests talking to a couple that has gone through the process. Unfortunately things go sideways when Chandler can''t keep his big mouth shut. Also, Phoebe is visited by her brother, Frank Jr., who is desperate because he can no longer cope with his precocious triplets.', 24, '2003-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 3, 'The One with Ross''s Tan', 'Ross goes to a spray-on tanning salon but fails to follow the ''simple'' instructions. Meanwhile, Joey and Rachel struggle to make the transition from friends to lovers. Also, Monica and Phoebe try to avoid an annoying woman that used to live in their building.', 25, '2003-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 4, 'The One with the Cake', 'On Emma''s first birthday, Ross and Rachel convince everyone to delay their plans so they can attend her party, however plans go awry when Emma''s birthday cake is revealed.', 23, '2003-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 5, 'The One Where Rachel''s Sister Babysits', 'To help her younger sister, Amy, become a more responsible person, Rachel overrides Ross'' strong protests and allows Amy to baby-sit Emma but soon regrets that decision. Meanwhile, Joey volunteers to write a recommendation letter for Monica and Chandler''s adoption agency, however, he''s concerned about not sounding smart. Also, Phoebe unknowingly thwarts Mike''s "anniversary" surprise for her.', 29, '2003-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 6, 'The One with Ross''s Grant', 'Ross has a chance to be selected by Dr. Benjamin Hobart for an esteemed paleontology grant. Unfortunately, Hobart happens to be Charlie''s obsessed ex-boyfriend. Meanwhile, Phoebe tries to give a hideous painting she created to an extremely reluctant Monica and Rachel. Also, Joey is offended when Chandler lies about viewing Joey''s bizarre audition tape reel.', 25, '2003-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 7, 'The One with the Home Study', 'Monica and Chandler nervously prepare for a visit from an adoption worker who will decide if they would be suitable parents. Meanwhile, Phoebe and Mike keep changing their minds about donating their wedding money to a children''s charity. And Ross tries to help Rachel overcome her fear of swing sets so that baby Emma can enjoy the playground.', 24, '2003-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 8, 'The One with the Late Thanksgiving', 'Joey, Ross, Rachel and Phoebe convince Monica and Chandler to host a Thanksgiving dinner, however the four of them end up arriving an hour late as the boys decide to go to Rangers game, while the girls take Emma to a baby beauty pageant. This enrages Monica and she refuses to let the famished guests into her and Chandler''s apartment which causes even bigger problems.', 24, '2003-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 9, 'The One with the Birth Mother', 'Nervous and excited, Monica and Chandler travel to Ohio to meet a young pregnant woman, Erica Simmons, who is considering allowing them to adopt her child when it''s born. Upon meeting her they discover that due to a mix-up at the adoption agency, Erica thinks that Monica is a reverend and Chandler is a doctor. Meanwhile, Joey dates Phoebe''s friend but annoys her with his territorial eating habits. Also Rachel picks out an outfit for Ross to wear on a date but due to a mix up he ends up in an awkward position.', 25, '2004-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 10, 'The One Where Chandler Gets Caught', 'After Phoebe and Rachel catch Chandler getting into a car with an unknown blonde woman, they follow them to the suburbs. Fearing that Chandler is cheating on Monica, they inform her and learn that the woman is a real estate agent. The pair has been secretly shopping for houses and struggling with how to tell their best friends about their plans. Together the friends reminisce about their good times in the apartment.', 23, '2004-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 11, 'The One Where the Stripper Cries', 'Joey is a celebrity contestant on "The $100,000 Pyramid," with its actual host, Donny Osmond. Meanwhile, Phoebe''s bachelorette party features a rather unexpected surprise when the stripper shows up. Also, Chandler and Ross attend a college reunion and flash back to 1987 to reflect on a pact they made when they were in college.', 28, '2004-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 12, 'The One with Phoebe''s Wedding', 'As the big day approaches, Phoebe''s wedding planner, Monica, makes everyone around her crazy because according to her - every little thing needs to happen around schedule. This doesn''t sit well with Phoebe and she fires her. Unfortunately, on the wedding day New York is hit with the worst snowstorm its seen in 20 years, forcing plans to change. As a substitute for Phoebe''s incarcerated father, Joey takes his role much too seriously. Meanwhile, Chandler and Ross discover that neither of them has a part in the wedding; however, after one of Mike''s groomsmen is unable to attend, they compete for the open position by any means necessary.', 30, '2004-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 13, 'The One Where Joey Speaks French', 'Joey implores Francophile Phoebe to teach him French before an important audition, but she quickly becomes exasperated. Meanwhile, surrogate mom Erica is visiting town and tells the Bings that the baby''s father may be a shovel killer. Also, Ross and Rachel grow closer after her sarcastic father, Dr. Green, suffers a heart attack.', 24, '2004-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 14, 'The One with Princess Consuela', 'Monica and Chandler visit their potential new house and bring Joey along, who''s still upset about them moving, so he''s determined to change their minds. Meanwhile, Phoebe learns that she can legally change her name to whatever she wants, so she considers something more exotic. Also, Ross gets tenure at his job, while Rachel''s unfortunate job interview actually leads her to some new career opportunities.', 24, '2004-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 15, 'The One Where Estelle Dies', 'After Rachel makes a startling announcement about her possibly accepting a new job offer in Paris, Ross secretly schemes to get her former job back at Ralph Lauren. Joey is so flustered by all of the upheaval in his friends'' lives that Phoebe prevents him from learning about the sudden death of his agent Estelle. Meanwhile, Monica and Chandler check out the house for sale next door to their new suburban home and make a stunning discovery.', 24, '2004-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 16, 'The One with Rachel''s Going Away Party', 'Extremely pregnant Erica visits Monica and Chandler just as they are preparing to move to their new house in the suburbs. At the same time Rachel has packed and ready for her move to Paris, so on her last night in New York the gang hosts a farewell party for her. She says goodbye to each of her friends individually, except for Ross and he''s offended. However, before the night is over, there will be more surprises.', 23, '2004-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108778')) AND numero_temporada = 10), 17, 'The Last One', 'Erica goes into labor and the new parents, Monica and Chandler, get a bit more than they bargained for. Meanwhile, Joey gets them a housewarming gift - Chick Jr. and Duck Jr., who unfortunately get trapped inside the foosball table. Also, after their night together, Ross realizes that he''s still in love with Rachel and doesn''t want her to leave. Other friends convince him to go after her and Phoebe races Ross to the airport in a bid to stop Rachel from leaving for Paris.
