INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 1, '24 Hours', 'A day''s worth of trauma takes its toll on the men and women of the ER. Dr. Greene looks into leaving the ER and joining private practice. Among other events, multiple casualties are brought in when a building collapses. New medical students report for duty, including Dr. Benton''s new trainee, the young and inexperienced John Carter.', 87, '1994-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 2, 'Day One', 'Dr. Lewis tries to get a mentally disturbed individual admitted to the psych ward. Carter has a difficult day, treating many members of wedding party, suffering from food poisoning. Dr. Ross finally visits Carol, eight weeks after her suicide attempt. Dr. Greene deals with an elderly gentleman having a difficult time letting go of his dying wife. He also discovers that Jenn passed the bar exam.', 47, '1994-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 3, 'Going Home', 'Carol returns after her eight week absence, finding Doug holding himself responsible.  Carter finds himself watching over a mysterious, mentally ill singing woman.  Susan clashes with Dr. Kayson over a diagnosis.  Dr. Greene treats a domestic violence victim.', 48, '1994-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 4, 'Hit and Run', 'Carter has a difficult day when he has to identify a dead teenager and notify his parents.  It doesn''t help that he notifies the wrong family.  Doug woos Carol, despite Taglieri''s presence in her life.  Benton clashes with brother-in-law Walt after he neglects family duties.', 47, '1994-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 5, 'Into That Good Night', 'A business contractor with a bad heart gathers his family around him in the ER as he prepares for the end.  Dr. Ross helps an asthmatic teenage girl when her mother doesn''t have the funds.  Carter worries that he may have contracted an STD from Liz.  Dr. Lewis treats a teenager with alcohol poisoning.  Jenn Greene prepares to move to Milwaukee.', 46, '1994-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 6, 'Chicago Heat', 'The air conditioning quits on the hottest day in October which, coupled with closed ERs in Chicago''s other two hospitals, leads to an extremely hectic day.  Dr. Ross treats a six-year-old suffering from a cocaine overdose; Ivan Gregor, the liquor store owner, shoots and seriously wounds a young teenager.  Susan''s immature sister Chloe drops by, wreaking havoc in Susan''s life.  Doug picks up a pharmaceutical saleswoman, much to Carol''s displeasure.', 45, '1994-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 7, 'Another Perfect Day', 'Benton and Langworthy interview for the Starzl fellowship.  A drunk Chloe throws a tantrum in the hospital.  Benton saves a man with a throat wound, earning Morganstern''s praise.  Carter has a good day, winning a bottle of champagne and getting three leads on apartments.  Carol has second thoughts about moving in with Tag after a spontaneous kiss with Doug.', 45, '1994-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 8, '9 1/2 Hours', 'Hathaway treats a rape victim.  Walt brings Benton''s mother to the ER with a sprained ankle.  Carter shows his annoyance toward Benton and his stand-offish attitude.  Mark calls in sick to spend time with his wife, leaving Doug as a hectic acting chief.  Div shows signs of snapping, overreacting at the smallest provocation.  The ER gets a new desk clerk, ''Bob''.', 43, '1994-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 9, 'ER Confidential', 'Carter and Benton treat a suicidal transgender woman.  Doug feels like a ''kept man'' in his relationship with Linda Farrell.  A patient entrusts Carol with the particulars in an accident.  Cvetic continues to battle his demons, ending up wandering down the middle of a crowded street.', 45, '1994-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 10, 'Blizzard', 'A severe blizzard leaves the ER utterly devoid of patients, leaving the staff free to goof off.  In the middle of their fun, a call comes from dispatch, informing the ER of a 40-car pile-up with dozens of casualties.  The ER goes from being deserted to capacity.  All surgeons are called in.  Bob surprises everyone with a quick and life-saving decision.  A new doctor, Angela Hicks, arrives just at the right time.  Ross and Linda return from the Caribbean just as Carol makes a surprise announcement.', 47, '1994-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 11, 'The Gift', 'Benton makes a critical error when he publicizes the availability of a dying man''s organs before obtaining the wife''s permission.  Lewis discovers that Cvetic has quit his job at the hospital, moved out of his apartment, and dropped out of sight.  Carter makes a move on Susan.  Chloe announces her pregnancy.', 46, '1994-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 12, 'Happy New Year', 'Carter fumbles his way through his first look at surgery.  Dr. Lewis'' nemesis, Dr. Kayson, makes her New Year''s Day decidedly unpleasant.  Chloe announces she''s moving to Texas with her boyfriend.', 45, '1995-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 13, 'Luck of the Draw', 'Carter trains one of Benton''s new students, Deb Chen.  Hathaway has her hands full with an emotionally challenged patient who''s obsessed with colors.  A sociologist provokes people to measure their reaction times for a study.  Kayson brings charges against Susan in the Vennerbeck death, leading Morganstern to question Susan''s assertiveness.  Benton and Walt hunt for Peter''s missing mother.', 45, '1995-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 14, 'Long Day''s Journey', 'A case of apparent spousal abuse is not what it seems. Deb outshines Carter after he is up all night preparing for a presentation. Peter informs Jackie he''s hired a helper for his mother.  First Kayson''s reprimand against Susan is denied, then Susan has a chance to prove herself when Kayson is brought in as a patient.  Dr. Ross meets Diane Leeds, of risk management, and her son Jake.', 46, '1995-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 15, 'Feb 5, ''95', 'Morganstern invites Mark to join the staff as an attending physician.  Mark treats an woman with breast cancer, who begs him to kill her.  Deb "wows" Benton with her amazing presentation, leaving Carter in the rear again.  Benton offends Haleh, who spends her day making his job extremely more difficult.  The ER gets new crash carts, which are promptly stolen by cardiology.', 45, '1995-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 16, 'Make of Two Hearts', 'Carol worries about a Russian girl with AIDS who''s brought in and then abandoned by her foster mother.  Kayson asks Susan to be his Valentine.  Deb accidentally consumes LSD-laced chocolates.', 44, '1995-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 17, 'The Birthday Party', 'Dr. Hicks berates Benton when he tries to switch shifts to attend his mother''s birthday party.  A teenage girl, a frequent patient of the ER, is brought in for a drug overdose.  Carol decides she wants to adopt Tatiana while Tag isn''t so sure.  Dr. Ross slugs an abusive father in the lobby.  Jen accepts a job offer in Milwaukee despite Mark''s offer from Morganstern.  Deb and Carter await the arrival of sub-internship applications.', 46, '1995-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 18, 'Sleepless in Chicago', 'Peter refuses to sleep, despite Hicks'' order, in the middle of a 48-hour shift.  His lack of sleep catches up with him when he is supposed to be watching his mother.  A doctor, who turns out to be a con artist, visits the ER to use it as a model for a new hospital, in the process offering Susan a job.  Jenn tells Mark she wants to separate from him.  Dr. Ross treats an abused young girl.  Carol receives bad news about her attempt to adopt Tatiana.  Morganstern informs Mark he''s leaving for Boston and will be strongly recommending Mark to his replacement, leaving a surprised Mark uncertain as to his job prospects.', 47, '1995-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 19, 'Love''s Labor Lost', 'A busy Dr. Greene goes all day in solving his patients'' problems until he encounters the case of a pregnant woman suffering from complications that threaten both her life and her unborn baby''s.', 46, '1995-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 20, 'Full Moon, Saturday Night', 'Mark, still upset over the loss of Jodi O''Brien, takes the night off but ends up in the ER anyway, albeit an hour late, when the new chief runs a drill at 2:00 a.m.  Benton begins to realize his mother''s future is not bright.  Carter and Deb compete against each other.  A small moon coinciding with the naturally heavy Saturday night traffic causes an exciting night.', 46, '1995-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 21, 'House of Cards', 'Deb and Carter compete furiously for procedures after Benton announces their books are due a week earlier than previously announced.  Deb commits a nearly deadly error on a patient while trying to keep up with Carter.  Doug''s relationship with Diane Leeds grows.  Peter and Jackie decide to put their mother in a home.  Dr. Greene is put on trial, so to speak, in the M conference for Jodi O''Brien.  Chloe returns.', 45, '1995-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 22, 'Men Plan, God Laughs', 'Susan has her hands full with a pregnant Chloe.  Benton goes to dinner with Jeanie.  Greene further alienates Swift when he decides to honor a family commitment rather than stay longer at the ER to help him.  Carter makes a good impression on Dr. Swift.  Doug turns down an offer to "celebrate" with Linda Farrell, instead getting more serious with Diane as he agrees to coach Jake''s Little League team.', 46, '1995-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 23, 'Love Among the Ruins', 'Mark and Jennifer struggle to remain together as Mark has moved in with her in Milwaukee.  Doug coaches Jake''s little league team.  Chloe''s irresponsibility wears Susan down.  Carter asks Benton to fill out a recommendation for the ER sub-I.  Carol and Tag try to write their wedding vows; he becomes upset when Carol invites Diane Leeds, knowing that she''ll bring Doug.  Peter exhibits a growing attraction for Jeanie.  Susan discovers what happened to Div when she spies his picture in a cabbie''s dating service photo book.  The staff discovers that Carter comes from a wealthy background.', 46, '1995-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 24, 'Motherhood', 'Susan is forced into the role of parent when Chloe gives birth and both Chloe and her mother, Cookie, shirk responsibility.  Doug is surprised and a bit frightened when Diane suggests they move in together.  Unfortunately, Linda Farrell happens to be around to take advantage of his nervousness.  Carter is offered the ER sub-I but turns it down in anticipation of receiving a surgical position.  Peter receives unpleasant news; his mother has died.', 47, '1995-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 1), 25, 'Everything Old Is New Again', 'Carter faces his last day in the hospital with aplomb, harshly grading Benton on an evaluation report.  He later rescinds the report after finding out that the surgical sub-I is his.  Carol faces wedding day jitters, culminating in Tag''s deciding to call off the wedding.  Chloe disappears again, abandoning little Susie with Susan.  Dr. Swift changes his mind and decides to support Mark.  Jake visits Doug.', 46, '1995-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 1, 'Welcome Back Carter!', 'The ER treats victims of a gang shootout.  Carter arrives late and unprepared for his new position.  Mark learns all about being an attending, including senior staff''s habit of bad-mouthing the residents, particularly Doug Ross.  Mark hires a new chief resident, Kerry Weaver.  New third year med students arrive to complete their ER rotation.', 45, '1995-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 2, 'Summer Run', 'Kerry Weaver manages to offend just about everyone in her first day as chief resident.  Carol goes on a ride-along with paramedics Shep and Raul, sharing a ferris wheel ride with Shep.  Peter and Jeanie''s secret relationship comes to a head.  Susan is stuck caring for Little Susie while Chloe attends school.  Dr. Ross has his hands full with a young pyromaniac.  Carter shows interest in med student Harper Tracy.', 46, '1995-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 3, 'Do One, Teach One, Kill One', 'Carter gets his first patient...and loses him.  Susan''s feud with Kerry Weaver intensifies when Weaver demands all of Susan''s procedures be cleared with her.  Chloe abandons Little Susie again for a lucrative career in the flea market business.  Carol finishes her paramedic recertification by picking up a very overweight, lethargic man.  Shep hits on Carol.  Jeanie ends her relationship with Benton.  Wendy conducts interviews with various ER staffers for an article on Dr. Greene.  Dr. Ross cares for a four-year-old Asian boy with AIDS.', 45, '1995-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 4, 'What Life?', 'Weaver and Susan''s feud escalates to the point where Mark needs to step in and fix it.  Benton is involved in a parking lot altercation, resulting in a broken hand and Carter replacing him in surgery.  Mark cares for an abandoned elderly woman.  Susan tries to juggle her work and care for Little Susie.  Shep risks his life to bring in a gunshot victim.', 45, '1995-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 5, 'And Baby Makes Two', 'Dr. Ross treats the dying Chia-Chia.  Susan tries to find a way to keep Little Susie, asking her parents for help.  Benton treats an injured woman who refuses to press charges against her abusive policeman husband.  Carol and Harper are tricked by a patient from the "turkey file."  Lydia helps Loretta the prostitute outfit herself for a job interview.  The staff celebrates Weaver''s day off.', 45, '1995-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 6, 'Days Like This', 'Speculation runs through the ER, on a very hectic day, about Randi''s possible criminal history.  Mark faces an ethical dilemma when he has to decide whether to report yet another of Doug Ross''s indiscretions--Doug slept with med student Harper Tracy.  Carter becomes upset when Harper confesses this to him.  Carol meets with a mobile notary to finish the paperwork to purchase a house.  Bernstein informs Doug that he need to look for other employment.  Benton is visibly upset when Jeanie begins work in the ER as a physician''s assistant.', 45, '1995-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 7, 'Hell and High Water', 'In the middle of a torrential rainstorm, Dr. Ross stumbles across a child trapped in a drainage pipe rapidly filling with water.  Doug does everything possible to save the boy, Ben Larkin.  Harper develops a bond with a young girl with separated parents.', 45, '1995-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 8, 'The Secret Sharer', 'Doug''s heroics earn him a second chance as Bernstein and Morganstern ask him to stay on.  Doug and Mark clash when each treats a seriously injured patient and want to use the same equipment.  Benton learns that Jeanie has separated from Al.  After missing an earlier diagnosis, Carter overcompensates on his next patient and catches a break when the test results reveal something.  Shep gets on Carol''s bad side when he makes disparaging remarks about the people who make botched suicide attempts.  Doug gets a phone call from his estranged father.', 47, '1995-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 9, 'Home', 'Carol and Jeanie try to find a home for a schizophrenic architect.  Carter signs Benton up for an interview with Vucelich for a prestigious study.  Carter and Harper try to find a place to make out.  Jenn and Rachel are involved in a car accident; Mark is thrown for a loop when he learns that Jenn has been having an affair with a coworker.  Doug dines with his mother.  Susan receives $3000 in the mail from Chloe.', 46, '1995-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 10, 'A Miracle Happens Here', 'The ER staffers are in decidedly unfestive moods as Christmas arrives.  Carol''s spirits are lifted by a Santa-like patient.  Mark is outraged when Jenn decides to stay in Milwaukee over Christmas.  Benton and Carter score points with Vucelich when Carter convinces an older gentleman, Ruby, to include his wife in Vucelich''s study.  Mark gives a deposition in the O''Brien case.  The death of a priest threatens to start a gang war.  Weaver receives a surprise visit from an African friend.  A Holocaust survivor, the victim of a carjacking, brings Chanukah to the ER.', 46, '1995-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 11, 'Dead of Winter', 'Shep and Raul bring a dozen malnourished and abandoned children into the ER, keeping everyone very busy.  Shep has a run-in with Malik and Benton when he makes an off-handed racially insensitive remark.  Carter''s high from the admission of Mrs. Rubadoux to the study ends when she shows no signs of recovery.  Jeanie and Carol clash when Jeanie receives a poor evaluation.  Al asks Jeanie to give him another chance.  Mark is served with divorce papers.', 46, '1996-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 12, 'True Lies', 'Mark tries to find a way to tell Rachel about his impending divorce.  Benton attends a banquet at Vucelich''s home, with Jeanie as his date.  Carter finally tells Mr. Rubadoux about his wife''s terminal condition, making the man furious.  Morganstern is admitted to the hospital after breaking a leg at a Scottish family reunion.', 46, '1996-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 13, 'It''s Not Easy Being Greene', 'Mark is riddled with self doubt as the hospital prepares to settle the O''Brien suit.  Kerry appoints herself as Susan''s personal mentor.  Carol mind a bucketful of expensive worms.  Doug balks at counseling a teenage boy who thinks he might be gay.  Benton uncovers some disturbing information concerning Vucelich''s study.  Carter steals a diagnosis from Harper.', 45, '1996-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 14, 'The Right Thing', 'Benton decides to blow the whistle on Vucelich''s unethical study methods, causing Vucelich to drop him from the study.  Susan treats a street couple, one of whom has passed HIV to the other.  Doug receives a visit from his estranged father.  Carter spreads rumors about an affair between Mark and Susan.  Mark buys a motorcycle.  Prostitute Loretta has cervical cancer.', 45, '1996-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 15, 'Baby Shower', 'The ER hosts roughly a dozen pregnant women when a sprinkler bursts in the maternity ward.  Carter plays tour guide for the visiting surgical intern hopefuls before going through the interview himself.  Benton tries to bring a hopeless patient back from the brink of death in a marathon surgery.  Jerry tries to convince the others that basketball player Scottie Pippen visisted.  Doug visits his father.', 46, '1996-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 16, 'The Healers', 'Shep and Raul respond to a massive fire without proper equipment, risking their lives to save addicts and their children.  Shep will be okay, but Raul has third-degree burns covering his body; it''s only a matter of time.  The ER is flooded with burn victims.  Chloe returns to Chicago.  Doug is stood up by his father for a basketball game.', 45, '1996-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 17, 'The Match Game', 'Susan institutes extra precautions in case Chloe tries to reclaim Little Susie.  Mark changes his look, growing a goatee and wearing contact lenses.  Carol and Jeanie square off over the care of a transient.  Carter celebrates when he receives his residency match, putting his patient and his job at risk.  Shep, still suffering from Raul''s death, is surly with new parter Reilly.  Benton and Ross have differences when Peter discloses a critical mistake made by Doug, raising animosity between the two.', 45, '1996-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 18, 'A Shift in the Night', 'Mark finds himself manning a very crowded ER on his scheduled night off, filling in while Doug is out with whiplash and Susan meets with her lawyer.  He tries to juggle hunger pangs, 40+ patients in the waiting room and a never-ending stream of traumas.', 45, '1996-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 19, 'Fire in the Belly', 'Carter engages in competition with new surgical resident-in-training Dale Edson upon learning that residents will be evaluated and graded; only the top ones advancing to second year.  It doesn''t help that Dale once had a relationship with Harper.  Mark flirts with infomercial director Iris.  Peter faces the fallout from his altercation with Doug when surgeons begin dropping him from procedures.  Shep begins exhibiting uncontrolled hostility, first to a patient being abusive with Carol, then a pedestrian.  Susan and Chloe try to reach an agreement regarding Little Susie.', 46, '1996-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 20, 'Fevers of Unknown Origin', 'Susan throws herself into her work to escape her stressful personal life, earning recognition from Kerry and Mark, who begins preliminary discussions on next year''s chief resident.  Carter needs a pedes rotation, and fast, with Doug to graduate med school.  Doug takes up with his father''s girlfriend.  Shep overreacts and attacks an Asian boy interfering at a scene.  Mark and Jenn try to discuss their divorce amicably, with unforeseen results.  Benton is named Resident of the Year.  Harper leaves for an OB rotation at Parkland in Dallas.', 46, '1996-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 21, 'Take These Broken Wings', 'Susan visits a psychiatrist to cope with the loss of Little Susie.  Jeanie''s estranged husband Al checks in the ER complaining of flu-like symptoms, which turn out to be caused by HIV.  Shep expects Carol to back his version of events during an official investigation of his behavior.  Loretta takes a turn for the worse.  Doug discovers that his father has disappeared with a LOT of Karen''s money.', 46, '1996-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 2), 22, 'John Carter, M.D.', 'Carol is pushed to the breaking point after another day when politics triumph over health care, and she quits.  Dr. Greene "trades his soul" when he agrees to back Weaver for ER attending, in exchange for her support of Susan for chief resident.  Jeanie takes an HIV test and informs Peter he should get himself tested as well.  Carter invites Benton to his med school graduation, which he himself misses.  Shep''s refusal to see a psychiatrist risks his relationship with Carol.', 46, '1996-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 1, 'Dr. Carter, I Presume', 'It''s the first day of Carter''s internship. He has a 36 hour shift and overnight he has to cover the ER, the ICU as well as the surgical patients.', 45, '1996-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 2, 'Let the Games Begin', 'While the whole staff is worried the ER might close, Jeanie has her own problems in dealing with being HIV-positive.', 45, '1996-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 3, 'Don''t Ask, Don''t Tell', 'Donald Anspaugh has a new method to increase the staff''s efficiency, new intern Maggie Doyle joins the ER and Susan asks Mark to come along to Hawaii.', 45, '1996-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 4, 'Last Call', 'Doug''s one-night-stand has a seizure and he brings her to the ER.', 45, '1996-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 5, 'Ghosts', 'While Mark is anxious about Susan''s return from her holiday, Doug and Carol ride along with the health mobile.', 45, '1996-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 6, 'Fear of Flying', 'While on their helicopter flight rotation, Mark and Susan find an injured family of four who they bring to the ER.', 45, '1996-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 7, 'No Brain, No Gain', 'Encouraged by Carol, Mark finally asks Susan out. Benton tries to save a boy, despite the fact Doug thinks he''s brain dead.', 45, '1996-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 8, 'Union Station', 'It''s Susan''s last day. Carol stands up for her nurses when one of them is being rotated to another department.', 45, '1996-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 9, 'Ask Me No Questions, I''ll Tell You No Lies', 'Carol worries about her physics exam while Mark is heart-broken about Susan''s departure and focuses solely on his job.', 45, '1996-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 10, 'Homeless for the Holidays', 'Mark and Kerry have to create a policy regarding HIV-positive employees, which leads to gossip amongst the nurses.', 45, '1996-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 11, 'Night Shift', 'Carol has to fire two of the nurses. Meanwhile, Gant feels Benton is too hard on him.', 45, '1997-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 12, 'Post Mortem', 'Carter feels guilty about Gant''s death. Benton doesn''t want to talk about it.', 45, '1997-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 13, 'Fortune''s Fools', 'Benton can''t keep his mind on the job, Mark and Chuny break up and Carol does what she needs to do regarding the fatal error she has made.', 45, '1997-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 14, 'Whose Appy Now?', 'Doug treats a dying 17-year old cystic fibrosis patient who doesn''t want to be resuscitated. Carter gets to operate Benton.', 45, '1997-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 15, 'The Long Way Around', 'Nurse Carol Hathaway is held hostage during a convenience store robbery, then befriends one of the gunmen.', 45, '1997-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 16, 'Faith', 'Carol will hear whether her suspension is permanent or not. Mark and Doyle do what they can to get a patient with Down syndrome on a heart transplant list.', 45, '1997-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 17, 'Tribes', 'Benton goes into Carla''s private hospital files when he fears that something may be wrong with their baby; Jeanie treats a suicidal woman who reveals a surprising secret; and Greene learns that Rachel has been lying about her health.', 45, '1997-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 18, 'You Bet Your Life', 'Benton tries to find out if everything''s OK with Carla''s baby. Carter tries to get a man operated, despite the fact Anspaugh thinks he will die no matter what.', 45, '1997-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 19, 'Calling Dr. Hathaway', 'Benton takes a day off to help Carla. Carter finds out Edson falsified a chart.', 45, '1997-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 20, 'Random Acts', 'Jeanie asks Greg to help Al get into a special AIDS-program at the hospital. Olbes brings in her grandfather, who had a stroke.', 45, '1997-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 21, 'Make a Wish', 'It''s Carol''s birthday, Mark is returning to work after being assaulted and Carla goes into premature labor.', 45, '1997-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 3), 22, 'One More for the Road', 'Anspaugh is furious when Carter tells him he wants to quit surgery. Charlie is brought in with an overdose. Mark keeps struggling with his beating.', 45, '1997-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 1, 'Ambush', 'While a film crew is filming in the ER, it''s Elizabeth Corday''s first day.', 45, '1997-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 2, 'Something New', 'Carter is exited about getting his own med student and Mark and Carol interview candidates for the desk clerk position.', 45, '1997-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 3, 'Friendly Fire', 'Cynthia Hooper starts as the new desk clerk. Benton and Carla disagree over whether or not their son should be circumcised. Al gets in an accident at work.', 45, '1997-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 4, 'When the Bough Breaks', 'His ex-wife Jennifer tells Mark he can''t see Rachel until he''s got his act together. Reece gets to go home. Al has lost his job.', 45, '1997-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 5, 'Good Touch, Bad Touch', 'Carol would like to have a women''s and children''s health care clinic within the ER. Benton has trouble combining work and fatherhood.', 45, '1997-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 6, 'Ground Zero', 'Al wants to move to Atlanta where he got a job offer. Jeanie however isn''t keen on moving. Carol talks to Carter''s grandmother about the clinic.', 45, '1997-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 7, 'Fathers and Sons', 'Ross and Greene travel to a near-deserted stretch of California to investigate circumstances surrounding a death in Doug''s family.', 45, '1997-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 8, 'Freak Show', 'Benton has a very extraordinary and interesting case when he comes across a boy with reversed internal organs.', 45, '1997-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 9, 'Obstruction of Justice', 'Jeanie believes she''s been fired because she has HIV and fights her dismissal.', 45, '1997-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 10, 'Do You See What I See?', 'Mark treats an old lady who has been brutally raped. Carter''s grandmother visits Carol''s clinic. After he''s touched by Benton, a blind man can see again!', 45, '1997-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 11, 'Think Warm Thoughts', 'Dr. Anspaugh''s 13-year-old son is brought in and Anspaugh asks Mark to look after him. Another old lady who has been raped is brought in.', 45, '1998-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 12, 'Sharp Relief', 'Kerry starts to doubt the methods of Synergix. Carter tries to help his cousin beat his drug addiction. Jeanie becomes Scott Anspaugh''s part-time caregiver.', 45, '1998-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 13, 'Carter''s Choice', 'Another elderly rape victim is brought in. So is the rapist.', 45, '1998-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 14, 'Family Practice', 'Greene flies to San Diego when his mother falls and is hospitalized. His concern increases when he finds her acting "completely loony and out of control." To make matters worse, he butts heads with his dad over her care.', 45, '1998-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 15, 'Exodus', 'Because of benzene that''s been spread, the ER has to close. Weaver gets felled and Carter has to take the lead.', 45, '1998-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 16, 'My Brother''s Keeper', 'Mark finds out Cynthia has moved. Carter''s cousin Chase is brought in because of a heroin overdose. Doug and Kerry clash after she found a flaw in his study.', 45, '1998-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 17, 'A Bloody Mess', 'Jeanie fears Scott Anspaugh''s cancer may have returned. Hathaway learns a disturbing secret about a 16-year-old girl. A pregnant patient fears she''ll miscarry; Morgenstern returns to work, but perhaps too soon after his heart attack.', 45, '1998-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 18, 'Gut Reaction', 'Carter finally works up enough nerve to ask Del Amico out. Jeanie tries to help Scotty decide whether to undergo an experimental treatment and Benton takes unexpected action during an operation with Morgenstern.', 45, '1998-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 19, 'Shades of Gray', 'Del Amico, Ross and Corday confront disturbing situations after the bombing of a women''s clinic. Benton comes under review for controversial actions in the OR. Jeanie endures one of the most difficult days of her life as she says goodbye to a friend.', 45, '1998-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 20, 'Of Past Regret and Future Fear', 'A 31-year-old security guard is brought in suffering from severe chemical burns, and a 21-year-old man is wheeled in after falling 75 feet into a river. Meanwhile, Benton is upset that Carla''s boyfriend is part of Reese''s baptism.', 45, '1998-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 21, 'Suffer the Little Children', 'Ross treats a 6-month-old recovering from methadone withdrawal. A televangelist and his wife, who''s suffering from an infection, plan a broadcast from the ER. Del Amico''s old boyfriend arrives, and Jeanie fears her health is rapidly declining.', 45, '1998-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 4), 22, 'A Hole in the Heart', 'Ross and Hathaway''s jobs are in jeopardy after their unauthorized treatment of a drug-addicted 7-month-old boy is discovered. Corday loses her sponsorship. Carter suspects Del Amico''s boyfriend when drugs are stolen.', 45, '1998-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 1, 'Day for Knight', 'Third-year med student Lucy Knight reports to the ER for the first day of her rotation. Greene takes a teacherly interest in her, helping her get acquainted, but she gets off to a bad start with the irritable Carter when she speaks insensitively, and without Carter present, with a patient''s wife about her husband''s very serious condition. The rest of the day finds her comforting a woman who has suffered a miscarriage, getting locked out on the roof, having Carol bail her out on a simple procedure, and trying to figure out Kerry Weaver''s "Tour on Tape."', 45, '1998-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 2, 'Split Second', 'Dr. Corday''s father visits from overseas in an attempt to convince her to join his medical practice.  Weaver suggests that Elizabeth look into alternative methods to stay in America, like starting over as an intern.  Weaver also doesn''t let an opportunity pass to remind Doug of the way he bypassed her authority in the McLean case.  Lucy continues learning, earning more of Carter''s respect than she deserves.  Peter takes Reese in for another hearing test.  Mark has several discussions with paramedics about the state of the EMT program.  Carol hires a nurse practitioner to help out in the clinic.  Carter is having trouble being an RA in the dorms.', 45, '1998-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 3, 'They Treat Horses, Don''t They?', 'Mark goes to a trauma scene with the EMTs, where he treats a gunshot victim who has a bomb strapped to himself. Later, Mark’s daughter persuades him to treat a horse with colic, and Jerry gets the bad end of the enema. Carter intubates an elderly woman who is DNR. When her HMO declines to admit her, Carter either has to find a relative quickly or let her die. Kerry finds herself more and more frustrated when Anspaugh suggests that they''re not considering her for ER Chief, and she discovers she’s the last to hear that Doug was made a pediatric attending. Corday serves her last day as a surgical fellow. Benton meets with Carla to discuss getting Reese hearing aids. Jeanie returns from vacation. Carter goes out with Roxanne, the insurance saleswoman he treated.', 45, '1998-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 4, 'Vanishing Act', 'Dr. Corday begins her first day as an intern, first by being assigned to Dale Edson, then being treated as Romano''s lapdog.  Kerry is interviewed for ER chief.  Doug and Carol ponder parenthood when Carol realizes she may be pregnant.  Carol and Lynette try to keep a wounded gang-banger from leaving and seeking retaliation.  Lucy faces the wrath of Carter when he discovers that she doesn''t know how to start an IV.  Jeanie asks Doug if she can be a full-time PA for the pediatric ER.', 45, '1998-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 5, 'Masquerade', 'Halloween night finds the ER awash with allergic or otherwise incapacitated children.  Kerry tolerates a visiting candidate for chief while she waits for the official vote.  Romano operates on an 11-year-old girl and finds she''s genetically male.  Carter leaves Lucy in charge of a dorm party he''s supposed to be overseeing, with unfortunate results.  Mark learns that Jenn''s moving to St. Louis--with Rachel.  Mark and Carol treat a pregnant schizophrenic.', 45, '1998-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 6, 'Stuck on You', 'After Mark saves a 16-year-old assault victim in a daring rescue, he tries to convince the boy to leave the streets for a shelter.  Carter loses his beard when two carpet installers come in covered with glue.  Peter consults a deaf physician regarding Reese''s hearing condition.  Corday is reassigned as Benton''s intern.  Kerry hears more discouraging news regarding her bid for ER chief.  Carter loses his RA job, forcing him to go apartment hunting.  He finds one--in Weaver''s basement.', 45, '1998-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 7, 'Hazed and Confused', 'Dr. Corday commits a deadly error after being on-call for nearly 36 hours straight.  Peter visits Dr. Kotlowitz and receives encouragement regarding a cochlear implant for Reese.  Dr. Amanda Lee, a prospective new ER chief, visits.  In the wake of a failed pregnancy attempt, Carol lashes out at a mother using abortion as a means of selective birth control.  Carter and Lucy feud when Carter accidentally uses her palm computer and finds out what she thinks of him.  Mark panics during a paramedic initation.', 45, '1998-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 8, 'The Good Fight', 'Carter and Lucy scramble across Chicago to find a dying girl''s father who''s a perfect match for her very rare blood type.  Benton operates without transfusions to save the little girl''s life.', 45, '1998-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 9, 'Good Luck, Ruth Johnson', 'Carter plays tour guide for Ruth Johnson, who was born in the hospital 100 years ago to the day, and her large family.  Carol treats a boy who was hit by a car and tells a story of being chased, his friend being shot in the process.  Peter observes Kotlowitz install a cochlear implant and decides to wait before scheduling an operation for Reese.  Mark dines with Dr. Lee, new ER chief.  Dr. Corday proposes radical changes in scheduling at an M&M conference, and later decides to break off her relationship with Benton.', 45, '1998-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 10, 'The Miracle Worker', 'Benton''s attempts to get away to Carla and Reese on Christmas Eve are continually thwarted by Romano, culminating in Benton forcing the drunken Romano away from a patient.  Carter believes he''s found a Christmas miracle when a teenage girl with a rare blood type needs an organ donation at the same time a brain-dead patient with the same blood type is in the hospital.  After witnessing Dr. Lee rifling through Greene''s locker, Jerry becomes convinced that she''s stalking Mark.', 45, '1998-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 11, 'Nobody Doesn''t Like Amanda Lee', 'Amanda Lee''s obsession with Dr. Greene comes to a head when Mark inadvertantly digs up old med school records damaging to her career.  Carter tries to save Lucy from Edson''s advances.  Peter treats Dr. Parks'' grandchild, who interprets for her deaf mother and grandmother.  Police officer Reggie Moore asks Jeanie out.  Kerry receives a call from someone claiming to be her mother.  Doug receives a job offer from Portland.', 45, '1999-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 12, 'Double Blind', 'Doug jeopardizes future federal grants for the entire ER when he breaks a double blind study by giving a sample drug to an ailing patient.  Doyle lodges a sexual harassment complaint against Romano, hoping Dr. Corday will lend support.  Lucy begins her surgery rotation under Benton''s tutelage.  The two of them treat a man claiming to be 140-years-old.  Mark declines to proceed in the NASA program.  Carol questions Lynette''s intentions when she hosts a women''s health clinic for African American women only.  Mark goes to bat for Pickman when she inadvertently leaves a severely injured man at an accident scene.', 45, '1999-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 13, 'Choosing Joi', 'Ricky Abbott returns to the ER.  Doug forges papers to allow Joi to treat Ricky at home.  Corday decides to back out of the Romano sexual harassment investigation after he threatens to expose her relationship with Benton.  Romano is later named Acting Chief of the ER.  Dr. Greene treats a Nigerian janitor for back pain and impotency.  Carol and the nurses watch a bunch of dogs when their owner is hospitalized.  Carter diagnoses a med student with Hodgkin''s disease.  Kerry initiates a search for her biological parents.', 45, '1999-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 14, 'The Storm (1)', 'Doug faces possible criminal charges after Ricky Abbott dies when Ross bypasses system lockouts to enable Joi to give Ricky a lethal dosage of dilaudin.  Doug is delegated to desk duty, Carol''s clinic is shut down for acquiring the P.C.A. machine for Ricky, and Greene and Weaver face future disciplinary action for not reporting Doug''s tampering with the double blind study.  Carter and Lucy discover a mutual attraction.  Benton studies with a sign language instructor.', 45, '1999-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 15, 'The Storm (2)', 'Greene assists paramedics in treating injured children at a school bus accident.  En route, Doug and Jeanie survive their own accident.  Kerry stops Doug from treating Jeanie...or any other patient.  Doug decides to resign and leave Chicago for the Northwest and asks Carol to come with him.  She decides against it, but he leaves anyway.  Carol steps down from running the clinic so that Anspaugh will keep it open.  Jeanie discovers she may have contracted hepatitis.  Hospital janitor Mobalage''s wife is stabbed.', 45, '1999-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 16, 'Middle of Nowhere', 'Peter accepts Romano''s suggestion and takes a two-week job in Minnesota to earn some extra money.  Unfortunately, before he gets a chance to leave, he''s transferred to backwoods Mississippi, where the hospital is only a two-room building.  Peter battles local racism, delivers a difficult infant while battling the grandfather''s concerns that the child might be black, and uses unorthodox methods to save two shrimp boat workers.  Meanwhile, back in Chicago, Jeanie''s condition worsens.', 45, '1999-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 17, 'Sticks and Stones', 'During a paramedic ride-along, Carter is forced to drive the ambulance while fleeing a riot scene and inadvertently runs over a teenage boy.  Later, a paramedic is shot by an angry mob looking for the driver of the ambulance.  Carol is despondent following Doug''s departure.  She later discloses that she''s pregnant.  Kerry is intrigued by an injured pro wrestler and his relationship with his father.  Lucy tangles with an Asian family that requests their matriarch not be told of a cancerous tumor.  Jeanie turns down dates with both Dr. Baker and Reggie, telling each she''s seeing someone else.', 45, '1999-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 18, 'Point of Origin', 'Greene tries to help Mobalage when he''s about to be deported.  Kerry tries to save a woman she believes is her birth mother.  Hathaway decides to have Doug''s child.  Benton and Corday clash over an ER fellowship.  Carter is in charge for the day, part of a requirement for applying for chief resident.', 45, '1999-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 19, 'Rites of Spring', 'Romano forces Benton to choose between the trauma and cardiothoracic fellowships.  Carol worries that she may have lost her child.  Corday and Greene bond on the way to a medical conference.  Carter mentors an aspiring teenager.  Lucy, on a psychiatry rotation, treats an overmedicated foster child.  Jeanie finds her faith while treating a reverend.', 45, '1999-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 20, 'Power', 'The hospital suffers through a series of power outages.  Carol''s decision to send Doug a fax about her pregnancy is thwarted by the power outages.  The staff is on alert after a raped and beaten patient is found in a hallway.  Romano begs Corday to stay in trauma.  Carter and Roxanne break up.  Carter and Lucy treat a pheromone saleswoman.', 45, '1999-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 21, 'Responsible Parties', 'The ER docs tend to three teenagers who were in an accident on the way to their senior prom.  Greene and Carter treat the most severely injured, a boy suffering from third degree burns over 80% of his body.  Benton receives the ER trauma fellowship.  Carol finally tells Doug about her pregnancy; Kerry also figures it out.  Mark and Elizabeth draw closer.  Lucy tells Carter about her Ritalin addiction.  "FBI agents" bring in a shot stripper.', 45, '1999-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 5), 22, 'Getting to Know You', 'Carol''s pregnancy becomes public knowledge as she learns that she''s having twins.  Lucy has problems trying to go off Ritalin.  Peter learns Carla plans to move to Germany.  Kerry finds an abandoned youngster and brings him to the ER.  Mark and Elizabeth discuss their relationship.  Jeanie and Reggie draw closer again.', 45, '1999-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 1, 'Leave It to Weaver', 'When Anspaugh decides to retire as chief of staff and return to surgery, he appoints Romano as his replacement. Greene expresses reservations about the decision, but Weaver does not support Greene. Romano makes Weaver the new chief of emergency medicine.', 45, '1999-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 2, 'Last Rites', 'After his mother''s funeral, Dr. Greene comforts his father in San Diego. In Chicago, Romano surprises Corday by appointing her associate chief of surgery. Corday treats Elaine, Carter''s lover, for breast cancer.', 45, '1999-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 3, 'Greene with Envy', 'A recommendation from Weaver allows Jeanie to have temporary approval as a foster parent for baby Carlos. Reggie and Jeanie get married. Lucy and Kovac talk with a young woman whose husband they believe is very dangerous.', 45, '1999-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 4, 'Sins of the Fathers', 'Hathaway befriends an out-of-work waitress, Meg. Seven-months pregnant, Meg cannot afford prenatal care. Hathaway invites her to the hospital, performs free tests and helps her interview for a job in the cafeteria.', 45, '1999-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 5, 'Truth & Consequences', 'A prank in a high school science class goes terribly awry, injuring a teacher and several students. Hathaway discovers Meg''s drug addiction. Weaver and Greene notice Lawrence gets easily confused.', 45, '1999-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 6, 'The Peace of Wild Things', 'Benton struggles with the idea of taking a DNA test to determine whether or not Reese is actually his son. As the signs continue to pile up, Kerry and Mark use a fake patient to convince Dr. Lawrence of his Alzheimer''s. Carter has trouble persuading a woman from a nursing home fire to sign a DNR for her husband and later is asked to forge charts for a family with no insurance. Carol continues to meddle in Meg''s life, having her arrested so that she can be detoxed. Cleo is blamed for an explosion in the suture room but it may actually be Dr. Dave''s fault.', 45, '1999-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 7, 'Humpty Dumpty', 'Weaver tries to save the life of a rape victim while Corday struggles with feelings of disdain as she is forced to save the rapist. Cleo treats a teenage alcoholic boy whose alcoholic mother refuses to recognize her problem or his.', 45, '1999-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 8, 'Great Expectations', 'On Thanksgiving Day Carol goes into labor. She''s able to get to the ER only thanks to Luka''s help. She delivers the first baby in the ER, but the second causes some trouble. Greene leaves Elizabeth to deal with his father and daughter, as he rushes to assist Carol.', 45, '1999-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 9, 'How the Finch Stole Christmas', 'Kovac and Haleh take care of Hathaway''s twins so the new mother can finally get some rest. The job transfer for Carla''s husband does not get approved allowing Reese to stay in Chicago. Lucy endeavors to get a heart transplant for a young woman and goes to Romano''s house begging him to perform the surgery.', 45, '1999-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 10, 'Family Matters', 'In order to get her paitient to tell her the location of a missing body, Corday agrees to grant him a fatal wish. Kovac befriends two brothers. He tells Weaver that his wife and children died in the Bosnian war. Former medical student Deb Chen returns to County General as a resident, using her Chinese name, Jing-Mei Chen.', 45, '2000-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 11, 'The Domino Heart', 'Lucy''s patient finally gets a heart transplant but does not survive. The transplanted heart will now go to another recipient. Greene interferes in a gay domestic situation. Corday tricked her patient who murdered several women and now he''s being transferred to a county jail.', 45, '2000-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 12, 'Abby Road', 'Two boys brought in after a fight at school leads Cleo to discover that one of them has been injecting himself with hormones. Hathaway''s obstetrics nurse, Abby Lockhart, joins the ER as a third year medical student on an ER rotation.', 45, '2000-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 13, 'Be Still My Heart', 'Dr. Greene and Corday bond with their parents, Lucy cares for a patient with a psychotic break, and Valentine''s Day celebrations in the ER end tragically for one of the students.', 45, '2000-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 14, 'All in the Family', 'Carter and Lucy are discovered and the staff struggles to save them and go on with normal patient care.', 45, '2000-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 15, 'Be Patient', 'Kovac witnesses an accident and saves the young victim''s life. Carter slowly recovers from his brutal attack and undergoes excruciating physical therapy. Hathaway helps two sexually active 14-year-old girls.', 45, '2000-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 16, 'Under Control', 'Even though he suffers from intense pain due to his stabbing injuries, Carter returns to work and prescribes a controversial procedure for a suicidal patient. Greene tries to convince his father to undergo cancer treatment.', 45, '2000-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 17, 'Viable Options', 'Chen''s patient refuses to reveal to his daughter that she might have inherited a terrible disease from him. Weaver defies Romano''s authority and performs a procedure that gets her suspended. An available kidney causes friction between Corday and Kovac as they decide which one of their patients will get it.', 45, '2000-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 18, 'Match Made in Heaven', 'After Corday refuses to perform exploratory surgery on Cleo''s patient, Cleo enlists Benton''s help, infuriating Corday. Abby cares for a pregnant woman with five children who wants an abortion. Greene lovingly tends to his dying father at home.', 45, '2000-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 19, 'The Fastest Year', 'Carter seeks psychiatric help because he can''t sleep. He then visits the wife of his attacker. Weaver returns to work after her suspension. Hathaway and Kovac share a kiss.', 45, '2000-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 20, 'Loose Ends', 'Weaver reprimands Carter for doing a dangerous procedure without consulting Kovac. She also talks to Hathaway about Hathaway''s lack of focus on the job. And while treating a 6-year-old patient involved in a minor car accident, Malucci and Cleo discover the girl has been sexually molested recently by her father.', 45, '2000-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 21, 'Such Sweet Sorrow', 'Greene prepares to bury his father. Chen worries about Carter''s mood swings. After witnessing the interaction between a dying woman and her family, Hathaway realizes she wants her family together and flies to Seattle to join Ross.', 45, '2000-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 6), 22, 'May Day', 'As the result of a school shooting, Kovac and Benton care for the gunman and his victims. Abby discovers that Carter has been illegally injecting pain relievers. Greene and Weaver confront Carter about his problem, and Weaver orders him to enter a drug rehabilitation center or leave the hospital permanently.', 45, '2000-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 1, 'Homecoming', 'Dr. Carter struggles with his drug dependency; a custodial strike leaves the ER cluttered with garbage; a riot at a high-school football game leaves several wounded.', 45, '2000-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 2, 'Sand and Water', 'A young couple cope with their baby being premature; Greene and Corday struggle with their relationship.', 45, '2000-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 3, 'Mars Attacks', 'Dr. Carter is allowed a cautious restart with small steps. An extremely blond Dr. Malucci is very curious who''s made Dr. Chen pregnant. Dr. Benton has been written out of all the hospital''s systems and is stunned by Dr. Romano. An unfortunate incident at a Science Fiction convention makes it look like scenes from the movie ''Mars Attacks''.', 45, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 4, 'Benton Backwards', 'Benton is unable to find a job after Romano negatively influences local hospitals. He reluctantly agrees to accept Romano''s demeaning offer of a per diem job at County with no benefits. Kovac and Abby are attacked by a mugger with a steel pipe. Injured, Kovac protects Abby and smashes the robber''s head on the ground repeatedly.', 45, '2000-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 5, 'Flight of Fancy', 'Greene flies in a helicopter to a remote area of Indiana to rescue a heart transplant patient. The helicopter develops problems, and Greene arranges for paramedics to transport the patient to County. Because Weaver is gone for the day, Romano appoints Benton in charge of the ER. Kovac is plagued by the death of the mugger.', 45, '2000-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 6, 'The Visit', 'Corday rushes through a surgical procedure in order to take off on a romantic weekend with Greene. She is later called back to the hospital after her patient suffers complications. Abby''s mother, Maggie, who suffers from bipolar disorder (manic-depressive) and refuses to take her medication, unexpectedly visits Abby at the hospital and wreaks havoc on Abby''s life.', 45, '2000-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 7, 'Rescue Me', 'Tests reveal that Greene has a brain tumor, but he hides the news from Corday. Corday finds out that she is being sued for malpractice. She also reveals to Greene that she is pregnant. Abby''s mother refuses to leave. Abby expresses resentment over her difficult childhood to her mother but resignedly brings her home for Thanksgiving dinner.', 45, '2000-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 8, 'The Dance We Do', 'Maggie''s emotional instability worsens. She refuses her medication, becomes combative and flees the hospital. Abby finds solace with Kovac. The gang member girlfriend of Benton''s deceased nephew knows who killed him and that he was hated for his antigang stance.', 45, '2000-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 9, 'The Greatest of Gifts', 'Chen gives birth, but insists on breastfeeding the infant before she gives it to the adoptive parents. Greene and Corday consult a brain specialist in New York City who believes the tumor can be safely removed. Stressed and tired, Carter impulsively swallows two painkiller pills but intentionally vomits them. He confesses to Abby.', 45, '2000-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 10, 'Piece of Mind', 'Mark Green is in New York on New Years Eve for cancer surgery. Meanwhile a father and son are involved in a car crash.', 45, '2001-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 11, 'Rock, Paper, Scissors', 'Benton and Cleo clash over his deceased nephew''s girlfriend. They finally agree to call a social worker. Benton confesses his love to Cleo. The spinal surgery malpractice suit is settled by employing a technicality: the equipment used was later recalled by the manufacturer. But Corday now doubts her abilities as a surgeon.', 45, '2001-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 12, 'Surrender', 'Greene returns to work but confuses words and displays uncharacteristic anger. Eager to get out of his per diem situation, Benton agrees to a full time position. Carter visits his cousin, who became paralyzed after a drug overdose. A workplace disaster results in numerous injuries and fatalities among illegal immigrants.', 45, '2001-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 13, 'Thy Will Be Done', 'Weaver becomes concerned about Greene''s cognitive skills and surreptitiously calls for an official evaluation of his competency. Corday plans her wedding to Greene. Bishop Stewart returns, and Kovacs realizes the man has a terrible disease. Dateless for a charity function, Carter invites Abby to attend with him.', 45, '2001-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 14, 'A Walk in the Woods', 'As the new director of diversity, Benton studies medical school applications and discovers that his own academic record did not qualify him--he was admitted because of affirmative action. Weaver feels uncomfortable amongst Legaspi''s lesbian friends. Carter treats an unvaccinated child who contracted measles.', 45, '2001-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 15, 'The Crossing', 'In the series'' 150th episode, a massive train wreck mobilizes the emergency room doctors. Corday, Carter and Kovac rush to the scene. Corday falls and injures her back, bringing on contractions in only her 25th week of pregnancy. While amputating the legs of a fallen firefighter, Corday stops because of her pain.', 45, '2001-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 16, 'Witch Hunt', 'Weaver fears for her own reputation when Legaspi is accused of sexual harassment. Afraid to reveal her relationship with Legaspi--for both personal and professional reasons--Weaver fails to support her during the investigation. An infant is abducted from the hospital and later found on a train platform.', 45, '2001-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 17, 'Survival of the Fittest', 'A demented patient causes a shootout in the emergency room. After terrorizing people in the ER with a gun, she gets shot by a policeman. She soon dies. Benton later discover her dementia was caused by an aftereffect of his surgery that he and Cleo should have detected. Carter pursues a cute intern.', 45, '2001-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 18, 'April Showers', 'Numerous mishaps threaten to mar Corday and Greene''s wedding day. As the very pregnant Corday becomes increasingly agitated, the presence of her bickering divorced parents does little to improve her mood. With the intense rain, Greene has a difficult time making it to the church. But, evenutally, he arrives and they joyfully wed.', 45, '2001-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 19, 'Sailing Away', 'Abby and Carter travel to Oklahoma to rescue Abby''s mentally ill mother and bring her back to Chicago. In Chicago, Maggie suffers from a sleeping pills overdose. At County General, Kovac frantically revives her. Benton treats a college student injured in a fraternity prank.', 45, '2001-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 20, 'Fear of Commitment', 'Maggie contests Abby''s attempt to institutionalize her. Weaver treats a few bizarre patients. When Legaspi returns to work after being exonerated of sexual harassment, Weaver tries to reconcile with her. Benton injures his hand while transporting his former teacher to the hospital and must contend with the teacher''s wisecracking elderly buddies.', 45, '2001-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 21, 'Where the Heart Is', 'Cleo and Carla clash after Reese gets hurt while in Cleo''s care. Weaver and Kovac cannot save the life of a developmentally challenged woman''s only caregiver. Abby goes to a therapy session with Maggie. Later, Abby confesses to Maggie that she is afraid to bear children because they might be bipolar like her mother.', 45, '2001-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 7), 22, 'Rampage', 'The ER is flooded with foster care home residents, attacked by a shooter bent on tracking down his son, who , with the help of Dr. Green, was put into the foster care system amid allegations he was being abused by his father.', 45, '2001-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 1, 'Four Corners', 'Weaver returns to the emergency room after a self-imposed sabbatical of three weeks, wondering how her newfound lesbian identity will affect her workplace relationships. Having purposely allowed a mass murderer to die, Greene must keep the secret amidst the scrutiny of his superiors.', 45, '2001-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 2, 'The Longer You Stay', 'Carter is overwhelmed by patients from a rock concert riot. Benton''s former girlfriend is killed in a car accident. Newly promoted to chief resident, Chen panics and misdiagnoses a patient. Kovac angers Abby by flirting with a waitress.', 45, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 3, 'Blood Sugar Sex Magic', 'Greene''s daughter comes to live with him and Corday. Carter and Abby become more intimate. Chen must prove her skills while saving a baby. Weaver terminates Malucci after witnessing him having sex in an ambulance.', 45, '2001-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 4, 'Never Say Never', 'Dr. Susan Lewis arrives, looking for work in the Chicago area again. Greene hires her, over Weaver''s objection. Chen nervously attends a risk management review, accompanied by the unforgiving Weaver, to discuss a patient who recently died under Chen''s supervision.', 45, '2001-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 5, 'Start All Over Again', 'Lewis faces a hectic first day back at County General. Benton and Roger become frantic when they can''t locate Reese. Carter''s grandmother is brought to the emergency room. Carter and Abby deal with inept medical students.', 45, '2001-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 6, 'Supplies and Demands', 'Corday''s ordeal, caused by the recent infection-related deaths of several of her patients, worsens when she is closely observed by a stern taskmaster. Corday is outraged when a county investigator accuses her of deliberately euthanizing the patients, who all happened to be elderly.', 45, '2001-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 7, 'If I Should Fall from Grace', 'A new medical student, Michael Gallant, arrives in the ER. He''s supposed to be working under Dr. Carter''s supervision but his grandmother is unwell. Elizabeth Corday is convinced that other doctors are refusing to work with as a result of the mysterious deaths.', 45, '2001-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 8, 'Partly Cloudy, Chance of Rain', 'When a torrential rainstorm pounds Chicago, patients deluge the emergency room while Weaver speeds to an accident site. There, she finds a pregnant woman, Vicki lying injured inside a wrecked ambulance while live power lines spark. Fourth-year student Michael Gallant makes a dangerous decision in order to help.', 45, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 9, 'Quo Vadis?', 'Peter Benton continues his court fight against Reese''s stepfather, Roger, who seems to have the upper hand. When a woman is accidentally shot during a gas station robbery, Dr. Corday tries to convince the husband to let them harvest her organs. A 15 year old boxer is brought in with a head trauma after sparring with his older brother. Newlyweds are having trouble when she constantly breaks out in a rash; Carter thinks he knows the cause.', 45, '2001-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 10, 'I''ll Be Home for Christmas', 'Benton commits perjury on the witness stand in order to gain custody of Reese.  When Romano refuses to give him a more even schedule, Peter resigns and seeks a job at the clinic where Cleo is newly employed.  Benton is granted custody of Reese and he and Cleo decide to move to the suburbs together.  Meanwhile, Carter''s father visits for Christmas with the news that he''s getting divorced, Weaver and Sandy Lopez finally go on a date, and Abby catches Nicole in the maternity ward, recovering from an abortion.', 45, '2001-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 11, 'Beyond Repair', 'Abby helps a distraught boy whose mother died of a stroke; a man with schizophrenia, who once stabbed Carter and killed a doctor checks into the ER.', 45, '2002-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 12, 'A River in Egypt', 'An injured and condemned murderer wants to die in the ER rather than await execution; Abby advises a neighbor to seek shelter from her abusive husband.', 45, '2002-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 13, 'Damage Is Done', 'An accidental overdose brings Drs. Green and Corday''s baby into the ER.', 45, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 14, 'A Simple Twist of Fate', 'Greene confronts Corday when she orders Rachel out of their home; Abby tries to protect a battered neighbor who refuses to press charges against her husband.', 45, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 15, 'It''s All in Your Head', 'After Dr. Corday moves out, Dr. Green fights loneliness and pain by immersing himself into his work. He is treating a father in the ER who severely burned himself while experimenting with illegal drugs. Abby fumes when the man who beat her is released and moves back in next door; the returning Jerry clashes with fellow desk jockey Frank.', 45, '2002-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 16, 'Secrets and Lies', 'After some staff members are caught going through a dominatrix''s bag, Weaver makes them attend a sexual harassment seminar, where they learn about each other.', 45, '2002-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 17, 'Bygones', 'Drs. Corday and Greene are awkward when working together in the ER. Dr. Weaver treats victims of an intense fire that may take the life of a dear friend.', 45, '2002-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 18, 'Orion in the Sky', 'As Dr. Greene''s brain tumor begins affecting his coordination, he becomes concerned that his fate will be similar to the terminally ill patients he treats.', 45, '2002-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 19, 'Brothers and Sisters (I)', 'When Dr. Lewis gets a hysterical call from her niece, Susie, she hurries to New York to search for the child and her sister Chloe.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 20, 'The Letter', 'Dr. Carter reads a letter from terminally ill Dr. Green to the ER staff. Dr. Weaver lashes out at a mentally challenged patient. A terminal, homeless man continues asking for Dr. Green.', 45, '2002-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 21, 'On the Beach', 'Dr. Greene''s final days are spent in Hawaii with Rachel, teaching her to drive and surf. When he suffers a seizure, Elizabeth is called. Mark refuses to go home. He manages to make amends with his daughter before his eventual death.', 45, '2002-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 8), 22, 'Lockdown', 'Just when the ER is understaffed and swamped, two children who were brought in turn out to have full blown smallpox. The entire ER must be locked down. The staff needs to improvise while they battle not only the disease but also frayed tempers.', 45, '2002-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 1, 'Chaos Theory', 'Dr. Carter, Abby and other staff of the ER are quarantined as the CDC investigate a mysterious, deadly outbreak.', 45, '2002-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 2, 'Dead Again', 'After another hospital shuts down, the ER is flooded with patients. Dr. Pratt resuscitates a heart-attack victim who had been pronounced dead.', 45, '2002-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 3, 'Insurrection', 'Dr. Carter leads a walk-out of staff protesting lack of security in the ER.', 45, '2002-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 4, 'Walk Like a Man', 'Weaver makes a mistake on live television while demonstrating flu shots, inadvertently sticking two reporters with the same needle.  In the bathroom later, Susan and Abby catch Weaver in a stall with a needle.  Weaver confesses to Susan that she''s taking hormones.  Carter, assuming Susan knows already, tells her about Abby''s drinking problem.  Abby becomes nurse manager, and argues with Carter about her drinking.  Luka flirts with a patient''s mom and is caught emerging from a storage closet with her.  Gallant has a rough day: Pratt butts in on a patient of his, and Stella Willis dies because Kayson didn''t bother with thorough treatment.', 45, '2002-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 5, 'A Hopeless Wound', 'On a busy Halloween night, Carter and Abby are the only staffers in costume when victims of an apartment building fire pack the ER. Corday takes on a new med student for a surgical rotation - Paul Nathan, who suffers from Parkinson''s disease and decided to pursue medicine after being diagnosed. Despite a difficult first day, both professionally and medically, Nathan makes a difficult diagnosis. Romano''s rehab lags behind his expectations, and he begins to doubt his role in surgery is no longer an option.', 45, '2002-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 6, 'One Can Only Hope', 'Corday clashes with new surgical resident Paul Nathan regarding his intervention into the treatment of a sickly young woman, Alison, who has signed a "do not resuscitate" order. Abby wonders about the erratic behavior of her visiting brother Eric, and feels conflicted over a nurse''s official complaint against Kovac, Abby''s former lover. Meanwhile, Pratt comforts Chen after a patient threatens her, and Corday suspects that an unconscious, 14-year-old female patient has been sexually assaulted.', 45, '2002-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 7, 'Tell Me Where It Hurts', 'Abby fears the worst when her brother Eric suddenly disappears. Carter and Chen treat a frightened Chinese immigrant nanny, Tong-Yi, whom they suspect was impregnated by her employer. Meanwhile, new surgical resident Paul Nathan, who is struggling to overcome a physical disability, tries to help in the emergency room—but his fellow doctors do not appreciate his advice to patients. Unable to quench his sexual appetites, Kovac also gets into trouble in his professional life, despite his admirable resolve to find an eye specialist to treat a young gunshot victim. Gallant and fellow medical student Erin Harkins engage in an escalating competition of medical knowledge. And Weaver gets some much-needed good news.', 45, '2002-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 8, 'First Snowfall', 'Abby''s family nightmare continues as she and her mother Maggie search for Abby''s missing brother Eric, who Abby suspects is suffering from serious mental problems. Meanwhile, Corday treats a family of patients who, while building a snowman, were severely injured after being struck by a truck driver.', 45, '2002-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 9, 'Next of Kin', 'Abby is distressed when her mother interferes with Eric''s treatment at a psychiatric hospital. Pratt treats a frightened young girl who has been injured in an auto accident and desperately wants to hide a secret.  An unhappy Luka forms an unlikely bond with a lonely elderly woman who makes him a surprising offer.  Chen is overcome with upsetting memories when a baby is abandoned in the emergency room.  Pratt takes action after Leon is fired from his menial job.', 45, '2002-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 10, 'Hindsight', 'Dr. Kovac''s speeding causes a crash on an icy road. The ER staff treats angry elves and a female hockey player with a head injury.', 45, '2002-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 11, 'A Little Help From My Friends', 'Dr. Pratt brings a gun into the ER; Dr. Weaver tries to conceal her pregnancy; a woman plots against her dying husband; Dr. Chen treats math students who overdosed on an unknown stimulant.', 45, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 12, 'A Saint in the City', 'Dr. Weaver is in a difficult situation when an alderman tests positive for syphilis. Dr. Carter is impressed when he meets a man who runs an inner city clinic.', 45, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 13, 'No Good Deed Goes Unpunished', 'Dr. Pratt''s disabled roommate leads him to a wounded thief. Dr Carter decides to practice medicine in Africa. A doctor makes a pass at Dr. Corday.', 45, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 14, 'No Strings Attached', 'Abby''s troubled brother is missing. A car runs into a crowd of teen girls. The alderman with syphilis gives Dr. Weaver a promotion. Dr. Lewis looks forward to a blind date.', 45, '2003-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 15, 'A Boy Falling Out of the Sky', 'Abby comes close to breaking down trying to deal with her mother. Dr. Pratt goes for his required paramedic ride-along. Dr. Weaver confronts the man who stole her purse. Dr. Lewis has a teen admirer.', 45, '2003-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 16, 'A Thousand Cranes', 'The police question Drs. Pratt and Gallant about a rampage at the diner across from the ER. Dr. Lewis befriends her teen admirer, a cancer patient.', 45, '2003-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 17, 'The Advocate', 'Dr. Weaver bends the rules and treats the Alderman''s lover for syphilis. Dr. Kovac''s patient claims she was sexually abused at a boot camp for troubled youth. Dr. Carter treats a women with a nasty personality.', 45, '2003-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 18, 'Finders Keepers', 'Dr. Romano seizes control of the ER and manages to offend everyone. Dr. Kovac asks Dr. Corday''s help in the quest to bring a sickly Croatian boy to the U.S. for medical treatment.', 45, '2003-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 19, 'Things Change', 'A psychotic patient threatens Abby. Dr. Weaver suspects a woman poisoned her own baby. Dr. Romano continues to make rash judgments.', 45, '2003-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 20, 'Foreign Affairs', 'Dr. Carter tries to prevent a grieving gang member from going after vengeance. Dr. Kovac races against time to save a Croatian boy''s life. A baseball player gets treatment for a heart problem.', 45, '2003-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 21, 'When Night Meets Day', 'Carter''s day shift and Pratt''s night shift (his final shift at County) are intercut.  Both men have extremely busy days.  Doc Magoo''s burns down.  Luka calls Carter from the Congo and asks for help.  Carter decides to go.  Pratt decides to stay at County.  In other parts of the hospital, Romano has his now-useless left arm amputated.', 45, '2003-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 9), 22, 'Kisangani', 'Carter travels to the Congo after Luka calls and asks for help.  During the course of his two weeks there, he learns how much different the conditions are against what he''s used to.  Luka decides to stay for a while as Carter heads back to Chicago, ending up at a sleeping Abby''s bedside.', 45, '2003-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 1, 'Now What?', 'Carter returns from Africa, going straight to Abby''s bedside.  Her response to seeing him is to ask for her key back.  She is very chilly towards him all day until new med student Neela Rasgotra answers a phone call for Carter. The message: Luka is dead. Carter decides to go back to the Congo to bring the body back. Neela has a tough first day in the ER, earning Chen''s ire after Pratt flirts with her.  Gallant, now a full-fledged doctor, helps to show her the ropes.', 45, '2003-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 2, 'The Lost', 'John Carter returns to the Congo to retrieve Luka Kovac''s body. He finds however that the area where was killed is still too dangerous to enter. He and Gillian finally manage to hitch a ride with a Red Cross worker, Debbie, who is going to the area. In flashbacks, we learn how Kovac and his fellow aid workers were taken prisoner by rebel troops. They are shot, one at a time, until only Luka is left. Amid the destruction of the eastern Congo, we learn his fate. Carter also makes a fateful decision.', 45, '2003-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 3, 'Dear Abby', 'Luka Kovac arrives safely at County General and is hospitalized for treatment. His friend Gillian delivers John Carter''s letter to Abby.', 45, '2003-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 4, 'Shifts Happen', 'Confident second-year resident Pratt wants to prove his abilities when he works the graveyard shift (11 p.m. to 7 a.m.), but his heroics sometimes backfire. Pratt shows contempt for a man, Ed Gamble, who presents no symptoms of disease but temporarily loses his speech.', 45, '2003-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 5, 'Out of Africa', 'Ben Hollander is a distraught architect whose degenerating eyesight causes him despondent while a spirited new nurse, Samantha Taggart joins the staff. Elsewhere, disaster strikes when the doctors suspect a mother is abusing her child while Dr. Corday learns something shocking about the charismatic Dr. Dorset, and Dr. Archie Morris is overwhelmed by the chaos and grisly conditions of life in the E.R.', 45, '2003-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 6, 'The Greater Good', 'Pratt and Kovac clash over a miscarriage-prone young woman, Denny, who arrives to deliver a premature baby. Pratt wants to make heroic efforts to save the unborn child, while Kovac is adamantly against spending vast amounts of money to keep the forever sickly baby alive.', 45, '2003-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 7, 'Death and Taxes', 'To everyone''s amazement, Lewis makes a date to share a home-cooked dinner with the elderly Ben Hollander, her depressed patient who is going blind.', 45, '2003-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 8, 'Freefall', 'On Thanksgiving Day, a helicopter crash outside the ER leaves several injured, and kills Dr. Romano. Alex tries to bring Sam and Luka together.', 45, '2003-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 9, 'Missing', 'Neela helps treat two Amish teens who were in a car crash. Sam argues with Dr. Kovac when he pays too much attention to her son.', 45, '2003-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 10, 'Makemba', 'Dr. Carter celebrates Christmas at a clinic in the Congo dealing with low supplies and anti-Americanism, but in the meantime, falling for an AIDS worker named Makemba.', 45, '2003-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 11, 'Touch and Go', 'Carter returns to County General to hearty welcomes. Although Abby is shocked to learn that Carter''s beautiful African girlfriend, Kem, is already pregnant with Carter''s child, Abby has moved on with her life as well, going back to medical school.', 45, '2004-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 12, 'NICU', 'Abby and Neela are assigned to a month-long rotation in the neonatal intensive care unit where they experience emotional roller coasters while caring for the sick infants.', 45, '2004-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 13, 'Get Carter', 'Dr. Carter''s girlfriend makes an impression as she observes ER operations. Dr. Gallant is almost shot during a domestic incident. Dr. Weaver dedicates a center to the memory of Dr. Romano.', 45, '2004-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 14, 'Impulse Control', 'Sam treats an abused, pregnant teen. Dr. Carter introduces African girlfriend Makemba to wintertime. ER chaos shocks a risk-assessment expert. Dr. Pratt and Abby restrain a man who has tuberculosis.', 45, '2004-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 15, 'Blood Relations', 'Carter misses his pregnant girlfriend who has returned to Africa. A family of four is rushed to the emergency room after suffering carbon monoxide poisoning from their faulty furnace--forcing the claustrophobic Neela to accompany a newborn baby into an extremely uncomfortable hyperbaric chamber.', 45, '2004-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 16, 'Forgive and Forget', 'Morris streets a patient without getting a psych consult, and the guy steals a tank and heads for County.  Gillian is visiting Luka, and Sam''s not happy about it.  Luka and Sam make up by the end of the day though.  A 13-year-old boy has chlamydia.  Frank has a heart attack.  Corday plays the dating game, going out with two men.', 45, '2004-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 17, 'The Student', 'Carter sticks up for Neela when the other attendings doubt her future in the ER.  Neela caves to the pressure and accidentally gives a patient the wrong medication.  Gallant takes the blame for her though.  Sam and Luka try to plan Alex''s birthday party.  Frank visits on his way to therapy.  Chen''s home nurse quits after her dad behaves poorly.', 45, '2004-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 18, 'Where There''s Smoke', 'Weaver rushes to the aid of her female life partner, Sandy Lopez, when the firefighter is severely injured while working and must now battle for her life. Frightened Weaver whispers hope to Sandy by reminding the victim of their newborn child.', 45, '2004-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 19, 'Just a Touch', 'Pratt struggles to diagnose a woman who suffers mysterious chronic seizures. An attractive woman, Campbell, informally accuses flirtatious Pratt of sexual harassment. Abby ponders how to get her contentious patients'' attention during her psychiatric department rotation.', 45, '2004-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 20, 'Abby Normal', 'A panic-stricken Weaver is ordered to give her son to the Lopez family. Carter greets the returning Kem, but their meeting with his father, Jack, gets tense after Carter announces plans for his grandmother''s estate.', 45, '2004-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 21, 'Midnight', 'Carter takes Kem to the hospital to check on their baby since it''s not kicking anymore.', 45, '2004-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 10), 22, 'Drive', 'Kovacs stops to help a woman and her son whose car broke down. Steve is getting close to Alex, and Sam panics. Abby is looking for her letter whether to see she passed her boards. Pratt shows off his new Chrysler. Elgin tries to build a connection between him and Pratt. Jing-Mei might be battered by her senile father.', 45, '2004-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 1, 'One for the Road', 'After being shot at, Pratt, Jing-Mei and Elgin are trying to get of their sinking car. Sam took Alex with her while fleeing for Steve, Kovac is considering to go after them. Abby wants to go to bed since tomorrow is her first day as a doctor, but is thwarted by Weaver, whose custody battle might take a dramatic turn. A young drug-dealer is brought in with "a foreign object" in her tunnel of life.', 45, '2004-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 2, 'Damaged', 'Neela is still struggling with her decision not to continue becoming a doctor. We discover that Ray is in a band. Kovac and Sam are amoureux, but where does that leave them?', 45, '2004-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 3, 'Try Carter', 'It''s a busy Fourth of July and Carter is the only attending working.', 45, '2004-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 4, 'Fear', 'Carter, Pratt, Kovac and Abby are dealing with a woman and her three children who''ve jumped from a three floor apartment trying to escape from the father. Meanwhile Dr. Lewis becomes Chief of Emergency Medicine, Howard quits his internship and Dr. Corday is facing dismissal.', 45, '2004-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 5, 'An Intern''s Guide to the Galaxy', 'Neela starts a new job in the emergency room after working at the convenience store near the hospital. On Neela''s first day, Pratt expects the interns, Abby, Ray and Neela, to take on a large patient load during their shifts. Pratt turns processing the patients into a competition, in which Ray is clearly going to be the winner.', 45, '2004-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 6, 'Time of Death', 'The last 44 minutes of ex-con & alcoholic Charlie Metcalf''s life are in the ER, as he slowly succumbs to end-stage liver failure.', 45, '2004-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 7, 'White Guy, Dark Hair', 'A rape victim, barely able to speak, does all she can to help police find her attacker.', 45, '2004-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 8, 'A Shot in the Dark', 'A wounded police officer''s teenage son must make a life or death decision. Abby tries to convince a girl needing appendicitis surgery to stay at County, but her fathers wants her transferred to another hospital.', 45, '2004-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 9, 'Twas the Night', 'Abby has a dialysis patient in critical condition, but she cannot find his physician, who does not want to be bothered during the holidays.', 45, '2004-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 10, 'Skin', 'Gang members kidnap Abby hoping she can save one of their members with a gunshot wound. Ray starts treating a patient, but when she requests a new doctor, he gets offended.', 45, '2005-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 11, 'Only Connect', 'Two teens enter the ER with gunshot wounds. When one dies, Neela botches telling the next of kin, making the woman hysterical.', 45, '2005-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 12, 'The Providers', 'When a 16-year-old girl who had received a kidney transplant from her father arrives at the emergency room feeling dizzy, Carter traces the problem to a new drug that the girl was taking to control seizures related to her kidney dysfunction.', 45, '2005-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 13, 'Middleman', 'While examining a young boy, Pratt finds a suspicious gash across his chest and calls Wendall for a consult. Kovac and Pratt examine a man who was shot when he confronted his boss with a gun. Jake tries to convince Abby to date him despite his being a student.', 45, '2005-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 14, 'Just As I Am', 'Dr. Weaver meets her birth mother, but their relationship changes when Kerry reveals she is gay. Dr. Carter causes a commotion when he confronts a couple hoping to scam some painkillers.', 45, '2005-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 15, 'Alone in a Crowd', 'A soccer mom finds herself completely aware of everything going on around her, but is unable to move or speak after suffering a stroke.', 45, '2005-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 16, 'Here and There', 'Neela (who''s in Chicago) and Gallant (who''s in Iraq) miss each other and write letters. Gallant also tries to save the life of a little girl.', 45, '2005-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 17, 'Back in the World', 'Sam''s ex-husband shows up and wants to take Alex on a trip. Gallant is back and Neela hopes to see him before he goes back to Iraq.', 45, '2005-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 18, 'Refusal of Care', 'A woman on a hunger strike refuses treatment until the INS give her son another deportation hearing. Abby searches for proof when she suspects a patient is the victim of elder abuse.', 45, '2005-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 19, 'Ruby Redux', 'Jules ''Ruby'' Rubadoux is back in the ER. He''s still angry with Carter about the death of his wife.', 45, '2005-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 20, 'You Are Here', 'Morris is named the new chief resident, which makes nobody really happy, except Morris. Meanwhile Luka and Sam are having communication problems, Carter gets a promotion Susan really wanted and Ray finds out a 14-year old who always comes in for free drugs has been raped.', 45, '2005-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 21, 'Carter est Amoureux', 'After Carter finds out Kem''s mother is hospitalized in Paris he decides to go there to tell Kem how he feels about her. Meanwhile, Ray makes a fatal error.', 45, '2005-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 11), 22, 'The Show Must Go On', 'Casualties of a disaster flood the ER, which is short-handed because everyone is at Dr. Carter''s going-away party because he''s leaving the ER after 11 years. Dr. Pratt looks for the courage to confront his father, Charlie.', 45, '2005-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 1, 'Cañon City', 'Sam and Luka go on the search for her runaway son, Alex. Meanwhile, Pratt and Lewis guide Abby, Neela and Ray, who have become R2''s, on how to teach the new interns.', 45, '2005-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 2, 'Nobody''s Baby', 'Much to Ray''s dislike, a surrogate mother in labor doesn''t want to have a C-section and endangers the life of the baby. Meanwhile, Sam tells Luka she and Alex are moving out. Pratt meets his half-brother and -sister, and Abby makes a difficult decision about a young boy.', 45, '2005-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 3, 'Man with No Name', 'Luka has a very bad day: New nurse manager Eve Peyton notices he doesn''t want to work with Sam and tells him so. At the end of the day he''s drunk and Abby takes him home.', 45, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 4, 'Blame it on the Rain', 'The rainy night brings in diverse patients including a mother involved in a car accident with her baby, a man with a satisfaction facilitator, and a comatose patient who suddenly wakes up. Also, Sam steps up to Eve and her strict ways and Jerry gets struck by lightening!', 45, '2005-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 5, 'Wake Up', 'A new attending, Dr. Victor Clemente, comes aboard and quickly makes a stir on the ER. Abby''s breast cancer patient convinces her to take a long awaited test. Luka befriends a young woman who awakes from a six-year coma. Also, Weaver shows Clemente who runs the ER.', 45, '2005-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 6, 'Dream House', 'Pratt''s half-brother tries to get him to make ends meet with his estranged father. Clemente treats an infant chimpanzee and involves Abby and Neela on the secret case. Eve promotes Sam and her first tasks is to fire a beloved nurse.', 45, '2005-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 7, 'The Human Shield', 'A kidnaped girl is the victim of police shooting. Abby is stuck in the middle of a disagreement between Luka and Clemente. Neela receives a phone call from Iraq. Later, Luka and Abby share a kiss.', 45, '2005-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 8, 'Two Ships', 'The ER prepares to take in victims from a plane collision, while Neela and Pratt head out to the crash site where Neela makes heroic efforts. At the end of the day, Neela gets a surprising visit.', 45, '2005-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 9, 'I Do', 'Gallant impulsively asks Neela to marry her that exact day, she says I do but soon gets cold feet. Morris stands up to Weaver on a patients course of treatment. Luka, Sam and Clemente treat a boy who contracted HIV from his mother. Also, Abby and Luka redefine their relationship and Luka is named the new Chief of Emergency Medicine.', 45, '2005-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 10, 'All About Christmas Eve', 'Pratt and Weaver try to create a Christmas miracle when they work to save a girl wounded from gunfire. Eve gets into trouble after punching a disruptive patient. Also, Abby has a special gift for Luka.', 45, '2005-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 11, 'If Not Now', 'Neela treats a religious teenage girl who turns out to be pregnant. Abby and Kovac struggle to figure out what to do with her unexpected pregnancy.', 45, '2006-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 12, 'Split Decisions', 'Ray helps an old friend escape from her abusive father. Dubenko volunteers in the ER but can''t seem to handle a slow day. Abby and Kovac go baby shopping, while Neela gets unexpected and upsetting news from Gallant.', 45, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 13, 'Body and Soul', 'Dr. Nate Lennox, a former professor with ALS, is brought in as the progression of his disease is chronicled through his own flashbacks as he is treated by each of the doctors at one point. As Lennox wants to give up, Abby fights to convince him to keep on fighting.', 45, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 14, 'Quintessence of Dust', 'An unexpected visitor puts Clemente in the middle of a domestic dispute. Meanwhile, Luka and Abby await test results on their unborn child; Neela struggles with her surgical elective and Pratt ends up with an unexpected suitor when he participates in a charity bachelor auction.', 45, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 15, 'Darfur', 'In the Sudan, Carter and a colleague struggle to save a woman who was raped by a band of militants. Back in the ER, Clemente asks to return to work after the shooting incident, but Kovac refuses. Meanwhile, Neela and Pratt have a work dispute, and, in a related incident, K.J.''s father shows up again in the ER.', 45, '2006-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 16, 'Out on a Limb', 'When is it time to go out on a limb? Armand Assante guest stars as a patient who makes Sam an offer she might not be able to refuse. Luka must calm Abby’s baby-related fears after an incident at the hospital places everyone at risk. Kerry makes a difficult choice, and Neela joins a support group.', 45, '2006-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 17, 'Lost in America', 'Abby and Luka desperately try to keep a young woman brought into the ER with stab wounds to the neck alive. As her condition begins to worsen, Clemente steps in and tries a risky procedure on the girl in order to save her life. Meanwhile, Neela pulls an all-nighter in preparation for a speech at a surgeon''s convention, Ray treats a man claiming to have swallowed a bottle of pills, and Sam decides to take a part-time job with Richard to help her with childcare expenses.', 45, '2006-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 18, 'Strange Bedfellows', 'When Luka answers a call for help, he discovers not everyone is pleased. Will he honor his commitment, or ask a colleague to step in for him? Abby and Morris wrestle with the strange case of a car crash victim. Having made a change in her life, Sam finds herself enjoying a few new perks. Neela has unexpected visitors, with even more unexpected news.', 45, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 19, 'No Place to Hide', 'Pratt departs for Africa with attitude to spare but makes his first contact with harsh reality before the plane lands.  Abby senses something is not what is seems when she treats a 12-year-old and her grandmother, then differs with Luka over the best course of action.  A prisoner is brought to the ER with what everyone thinks is a fake case of appendicitis.  Morris is dressed, and ready, to impress, but Albright’s not.  It’s time for Kerry to return to work and Clemente doesn’t know when it’s time to leave.', 45, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 20, 'There Are No Angels Here', 'Pratt gets to work in Darfur alongside Carter and his co-workers, but is troubled by astounding number of people needing care and finds himself making a dangerous journey.', 45, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 21, 'The Gallant Hero and the Tragic Victor', 'Pratt struggles to get a straight story when two abused boys come into the ER with their father. Two U.S. Army officers enter the ER.', 45, '2006-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 12), 22, '21 Guns', 'Chaos reigns in the ER when two prisoners are brought in for treatment, but instead plot a violent escape. Their desperate actions place one doctor in harm''s way, and forces one nurse to become a tool in their plan.', 45, '2006-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 1, 'Bloodline', 'Weaver, Kovac, and the other doctors work frantically to try to save Jerry and a pregnant Abby, who were both critically injured during the shootout that left the ER in shambles. Meanwhile, Sam tries to escape from her ex-boyfriend and his criminal accomplices as they head north, but things quickly turn violent.', 45, '2006-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 2, 'Graduation Day', 'As Abby and Luka cope with their newborn''s life and death struggle, the couple is shocked to receive a surprise visitor: Abby''s mother Maggie. Meanwhile, Sam fears the prospect of criminal charges; Neela discovers that Tony Gates will be joining the ER team as an intern and Morris gets his job back while Weaver gets demoted.', 45, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 3, 'Somebody To Love', 'Gates is assigned to the case of a closeted gay man whose partner clashes with his family; Neela meets her new surgical chief, Dr. Crenshaw; and Pratt must cope with the flood of new interns.', 45, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 4, 'Parenthood', 'Abby and Kovac discover both the joys and difficulties of raising a newborn; Morris is wrongfully accused of being a child molester; Pratt has his trial-by-fire when he has to handle the ER alone, juggling multiple traumas, teaching duties and a troublesome intern. Neela continues to be the target of her difficult supervisor, and Sam discovers her sons latest extra-curricular activity.', 45, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 5, 'Ames v. Kovac', 'Curtis Ames, a carpenter who suffered a stroke under Kovac''s care, sues him for malpractice. Kovac and Ames square off in court as each man''s recollections of Ames'' treatment are recounted via testimony and flashbacks. Meanwhile, Abby returns to work and must adjust to the dramatic changes in her life, and Pratt''s early morning trip to the barbershop results in a new awareness of community need. Also, Abby and Pratt try an unconventional method for treating a heart patient and Neela tries a risky procedure which doesn''t sit well with her chief.', 45, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 6, 'Heart of the Matter', 'Kovac anxiously awaits the verdict between himself and Curtis Ames but fears the worst. Meanwhile, Neela disobeys her chief''s orders and also questions her feelings for Gates, and Weaver unwittingly steals the spotlight from Morris in his big television debut.', 45, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 7, 'Jigsaw', 'A belligerent young man with the flu turns out to be more than he seems, and presents a challenge to Morris and Sam when he refuses treatment. Abby''s chance encounter with Curtis Ames leaves Kovac uneasy. Meanwhile, Pratt discovers a local church''s risky drug exchange program, Neela and Gates square off, and Weaver gets an interesting offer.', 45, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 8, 'Reason to Believe', 'A mysterious illness leaves little hope when a group of homeless kids enter the ER and one of them believes that Neela is a guardian angel in blue; Abby and Kovac clash over a possible case of domestic abuse; Pratt makes a shocking discovery about his brother, and Weaver is unexpectedly called into action when her television appearance becomes a real emergency.', 45, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 9, 'Scoop and Run', 'Thanksgiving at County is quiet, with the normal number of routine (or nearly so) emergencies. But Abby makes up for the lack of excitement while returning to the hospital as the doctor on a helicopter transport.', 45, '2006-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 10, 'Tell Me No Secrets...', 'Kovac and Gates treat a girl who appears to have been assaulted. When the police are no help with Ames, Kovac decides to confront the problem himself; Morris and other doctors work on a patient with an ice pick in his ear. Meanwhile, Ray tries to keep his new relationship a secret and Pratt can''t fully deal when his half-brother officially comes out. Also, a new male nurse arrives.', 45, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 11, 'City of Mercy', 'It''s Christmas in the ER. A homeless boy sends Gates and Ray on a mission. Meanwhile, in the ER, Neela oversees an unusual kidney transplant case; Sam takes a stand when a patient is dumped in an alley by another hospital; and Morris plays Santa for a special girl and learns the meaning of Christmas.', 45, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 12, 'Breach of Trust', 'Weaver cares for a Katrina survivor who''s reluctant to having surgery on her foot; budget cuts force Luka to make a difficult personnel decision. Also, Gates'' home life intrudes on the ER; and Pratt and Hope are shaken after a patient in their care dies needlessly.', 45, '2007-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 13, 'A House Divided', 'Kovac reacts negatively when he sees Abby giving extra attention to a patient; Ray and Gates clash over a patient, pinning Neela in the middle; and Ben takes things to the next level with Sam. Meanwhile, Pratt is under investigation and Weaver says a final goodbye to the ER.', 45, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 14, 'Murmurs of the Heart', 'Kovac finds himself in a tense confrontation with Curtis Ames, and Abby must act to protect her family. Meanwhile, Neela and Gates rush to get Meg to the hospital while Sam''s new home is soon under threat from fire.', 45, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 15, 'Dying is Easy...', 'Abby and Sam try to treat an obnoxious, aspiring comedian with mysterious symptoms; Pratt must defend his actions in front of the medical board; Neela scrubs in on a kidney donor transplant; and Morris, as the lone attending, must run a busy ER. Also, Kovac gets a surprising proposal from Abby.', 45, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 16, 'Crisis of Conscience', 'Kovac and Gates find themselves with a moral dilemma when a woman comes into the ER with acute liver failure; Neela finds herself questioning what is right when Manish decides to give up a kidney to a complete stranger. Meanwhile, Ray fights to get to the bottom of a cheerleaders accidental fall; Abby gets a prediction for her future; and Alex''s troubles continue to intrude on Sam''s work life.', 45, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 17, 'From Here to Paternity', 'A blizzard strands a family in the snow and Abby and Pratt quickly try to save the family. A gang shooting challenges Morris and Pratt. Meanwhile, Kovac and Abby begin making wedding plans, but their engagement might not be very secret; Gates struggles with the reappearance of his father and the possibility of losing Sarah; and Neela becomes jealous when Dubenko brings in a new surgical intern.', 45, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 18, 'Photographs and Memories', 'It''s Sam''s birthday, but she finds it hard to be away from her son Alex. Meanwhile, Sam meets a photographer taking pictures of a terminal patient and she gives Sam a new perspective on life. Dubenko''s new surgical intern unsettles Neela during a trauma; Gates is shadowed by a new and nerdy intern and later must tell Sarah the truth that he may be her biological father. Also, Morris and Hope annoy Kovac and Abby when they try to help with their wedding preparations.', 45, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 19, 'Family Business', 'Kovac and Gates deal with a hopeless father whose son succumbs to heart failure; Pratt tries to resolve the tension between him and his brother; an Armenian man tries to be a good samaritan but ends up crashing near the ER; Abby sneaks in baby Joe when she worries his sickness may be worse than it seems; Also, Sam injures the instructor of a self-defense seminar.', 45, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 20, 'Lights Out', 'In 12 hours, the ER will shut down. As Kovac is under pressure to take care of the patients before the final hours, he makes a pivotal decision about his future. Meanwhile, Sam befriends a photojournalist who returns only this time she''s terminally ill; Pratt is concerned when his brother ends up in the ER drunk; Morris confronts Gates when he ignores his orders and angrily sends him home while Gates tries to defend his actions.', 45, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 21, 'I Don''t', 'What is suppose to be a departmental dinner organized by Kovac turns out to be the surprise of a lifetime for Abby when she soon learns it''s a surprise wedding, secretly planned by the eager groom. Meanwhile, at the wedding, ER staffers enjoy themselves with music and booze while Neela finds herself the center of unexpected attention between Gates and Ray, which leads to a drunken fight and a shocking conclusion.', 48, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 22, 'Sea Change', 'Dr. Kevin Moretti, an ICU specialist bent on change, joins the ER team. Change comes elsewhere as Luka and Abby adjust to being husband and wife, Pratt tries to be a new man to his lady friend, Morris and Hope take things to the next level, and Ray goes missing. Later on, Luka gets a troubling phone call.', 45, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 13), 23, 'The Honeymoon is Over', 'Season Finale: Luka postpones his honeymoon, leaving Abby, Joe and the ER behind to begin a different journey. Meanwhile, it''s Moretti''s first day as Chief of Emergency Medicine, and everyone feels the effects of his style, especially Pratt and Morris. Neela learns of Ray''s fate, then joins an anti-war rally and finds herself in a dangerous situation. Gates faces a crisis on the home front.', 45, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 14, 'Season 14', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 1, 'The War Comes Home', 'Season Premiere.  Moretti''s first day is challenging as the ER is inundated with casualties from the peace rally - including Neela. Dubenko faces a crisis in surgery. Abby, Pratt and Morris conspire about how to deal with a shared problem.  A new intern arrives unexpectedly, and Gates is reassigned.', 45, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 2, 'In a Different Light', 'Moretti begins to make his presence felt, as he implements changes in the way patients are seen. The ER staff differ on how procedure when a patient comes in with a bullet in him needed as evidence.  Neela finds herself the object of more attention that she wants, or needs.  Abby had passport woes, and struggles with the changes being made.  Pratt and Morris find themselves forced to defend their actions, Hope prepares for  a new mission, and Gates finds himself labeled the reject in his new assignment.', 45, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 3, 'Officer Down', 'Two wounded police auxiliary officers present challenges in the ER.  Neela settles in with Abby as she recovers, while Pratt and Bettina consider their relationship.  Gates tries to get a patient on a drug trial, with Dubenko''s help. And Morris is in a funk that not even a pretty woman can help.', 45, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 4, 'Gravity', 'When Baby Joe is injured by a fall at the playground and rushed to the hospital, Abby is unable to reach Luka to tell him.', 45, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 5, 'Under the Influence', 'Moretti reassigns Gates back to the ER and treats a couple involved in a car accident. Morris prepares to take his written board exams. Neela is assigned a young genius intern. Kovac plans to extend his stay in Croatia while Abby struggles with single parenthood.', 45, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 6, 'The Test', 'Morris and Pratt cram for their medical boards when Morretti brings in a new attending physician to help with the load. Sam and Abby work on an attention-hungry patient who comes into the ER with elusive symptoms.', 45, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 7, 'Blackout', 'A power outage strikes on an unusually hot day, bringing nursing home patients suffering from hyperthermia to the ER. Abby and Pratt disagree about diagnostic tests for a fussy baby. Morris and Pratt get their board results, and the ER staff celebrates at Ike''s. Moretti and Abby''s interactions intensify, and Abby finds herself at a dark and frightening crossroads.', 45, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 8, 'Coming Home', 'Everyone at the ER is happily surprised to see Luka back from Croatia. Great news awaits Neela. Sarah once again needs rescuing by Tony, and patients are causing problems for Morris.', 45, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 9, 'Skye''s the Limit', 'It''s time for changes at the ER when Anspaugh makes an unpopular decision. Abby has old demons to fight with, which distance her from friends and family. Even Luka seems to be at a loss to help Abby. Love is in the air when a secret romance blooms between two doctors.', 45, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 10, '300 Patients', 'ER''s 300th episode finds Luka and Abby hurriedly preparing to travel to Croatia after Luka''s father passes away. Luka confronts Abby about the estrangement between them, and she eventually reaches out and asks for his help. A man rushes to the ER when his wife is seriously injured in a car accident, and finds someone very unexpected there with her. Julia holds a service to bless the ER and remember the patients that have been lost through the years.', 45, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 11, 'Status Quo', 'After being passed over for Chief of the ER, Pratt is looking for a hospital that will appreciate his talents. A former employee of the ER brings her sick son in for tests. Neela''s cousin is in town for a visit, and Morris and Harold compete for her affections.', 45, '2008-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 12, 'Believe the Unseen', 'Abby is back from rehab and finds herself the object of scrutiny. She confesses to Pratt that Luka might stay in Croatia longer than planned. Harold seems to have won over Neela''s cousin. Multiple victims from a fire fill the ER.', 45, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 13, 'Atonement', 'Neela''s short visit in Ortho turns into a game of hockey. Bettina wants to take her relationship with Pratt to the next level, but Pratt is not keen on the idea. Gates and Sam disagree over a patient. Julia provides some spiritual guidance in order to ease a prison doctor''s bad conscience.', 45, '2008-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 14, 'Owner of a Broken Heart', 'Pratt and a new doctor on the scene disagree on how to teach the interns. Gates treats a young woman with serious heart problems. Abby heads to Croatia, and ponders whether and how to tell Luka about her unfortunate choices. Sam discovers that Julia has moved on in more ways than one.', 45, '2008-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 15, '...As the Day She Was Born', 'Neela, worn out after being on shift for over 24 hours, has to make a quick decision regarding an accident victim''s torn aorta. Sarah''s grandparents are in town, and Hank is rushed to the ER after collapsing during an outing. Gates tries to convey to Sam that his feelings for her are serious.', 45, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 16, 'Truth Will Out', 'Kovac is in Chicago looking for hospice-care work. Neela''s aorta surgery has caused an infection in her patient. Abby treats a teen who has been beaten up. Brenner continues to cause problems for the ER staff.', 45, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 17, 'Under Pressure', 'There''s been a jewelry robbery in town, and Neela finds out that one of her patients might have had something to do with it. Pratt makes an effort to save his relationship with Bettina, and Abby worries about her marriage, sensing that Luka may have given up on it.', 45, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 18, 'Tandem Repeats', 'Neela''s aortic rupture patient is in need of yet another follow up surgery, and they are starting to take a toll on her. Morris talks with a shrink about his experience with the jewelery thieves. Abby needs to make a tough decision when a new opportunity is presented to her.', 45, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 14), 19, 'The Chicago Way', 'When a drunk patient is admitted to the ER, his actions endanger everyone at County. Pratt is still pursuing his dreams of becoming Chief of the ER, and Gates is worried about his future with Sam. Luka unexpectedly runs into Dr. Moretti.', 45, '2008-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')), 15, 'Season 15', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 1, 'Life After Death', 'The 15th and final season of ER begins with the devastating repercussions of the ambulance explosion. As Morris and Neela do everything they can to save a wounded colleague, Abby treats a young girl injured during the blast.', 45, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 2, 'Another Thursday at County', 'Everyone in the ER is trying to cope with the loss of their colleague. The staff feels defensive toward the new Chief and her tough disposition. Gates and the new interns treat a bio terrorist who has a lethal secret that endangers them all. Neela makes a great effort to get Dubenko back on the surgery staff, and gets help from an unexpected source.', 45, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 3, 'The Book of Abby', 'Abby''s first day as an attending is bittersweet. Neela is hurt when she finds out Abby''s news from someone else. Abby and the new ER Chief argue over how to treat a gunshot victim. Abby comes to Sam''s aid when she faces a nurses'' disciplinary board.', 45, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 4, 'Parental Guidance', 'Dr. Banfield defends herself during a mugging. Dubenko returns to work, due in no small part to Brenner''s organized protests. A young gymnast comes into the ER with injuries consistent with a fall, but Banfield and Gates each think a different family member may actually be to blame. Sarah neglects to ask Gates''s permission before getting her tongue pierced.', 45, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 5, 'Haunted', 'It''s Halloween night, and the interns continue to be paired with the residents. Gates''s teaching methods with Daria, and her responses, belittle Sam. A school fight results in a stabbing and a nose that won''t stop bleeding, with Brenner treating the victims and being deeply affected by the truth behind their confrontation. The staff, especially Neela, are enthusiastic about a surprise visitor. Gates gets locked in a maintenance area with a quiet young boy.', 45, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 6, 'Oh, Brother', 'Chaz, now a med student, begins his ER rotation. Morris takes him under his wing and shows him some risky procedures, endangering a patient and raising Banfield''s ire. Neela becomes upset when Banfield questions her authority and skills in front of her intern. Gates invites Sam and Alex to move in with him and Sarah.', 45, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 7, 'Heal Thyself', 'While out for a mind-clearing run, Banfield encounters a desperate situation and finds herself trying to rescue a young girl from drowning in a nearby lake. Painful memories of her son in mortal danger and Dr. Greene''s heroic attempts to save him are triggered during the experience. Meanwhile, Gates attempts to pull some strings to help out a homeless war veteran, and the interns continue to struggle in the ER.', 45, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 8, 'Age of Innocence', 'Sam gets frustrated with Gates when he gets obsessed with finding a homeless war hero. Neela is upset at her intern after he gets the entire surgery department into a lawsuit. A husband and wife come into the ER after someone tried to burn down their home. Brenner loses his cool with a patient and it gets physical.', 45, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 9, 'Let it Snow', 'As a snowstorm hits Chicago, Sam''s son Alex crashes a car and ends up in critical condition in the ER. Neela gives a deposition in the malpractice suit against her. Banfield and Morris are both at a medical conference in Omaha, and when the snow cancels all flights out, they share a memorable and surprising evening.', 45, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 10, 'The High Holiday', 'A package for Morris from his deceased father is delivered to the ER. Sam has some anxiety over Alex being removed from the ventilator. A woman with a high-risk pregnancy worries that she will be deported. An old friend returns to celebrate the holidays.', 45, '2008-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 11, 'Separation Anxiety', 'When a drug deal goes bad, two brothers sustain serious injuries and are brought to the ER. Tensions continue between Gates and Sam, coming to a head when Tony is the last to know Alex is about to be released from the hospital. Neela has to tell a young girl with sickle cell anemia that she must have an operation, and the case leads her to consider specializing in pediatric surgery. A feisty patient takes Morris into her confidence. Banfield ponders her choices about expanding her family.', 45, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 12, 'Dream Runner', 'Neela has recurring dreams about trying to save a girl with sickle cell anemia. In them, she also goes to an attending interview and sees an old colleague, has conversations with Ray, welcomes Brenner back from Australia, and assists Gates and Banfield in trying to save a "dream runner" who jumped out of a window during his sleep.', 45, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 13, 'Love is a Battlefield', 'Morris faces a complicated case involving a young girl hit while riding her bicycle. Gates finds it very difficult to let go of his feelings for Sam. Neela becomes quite flustered when Brenner returns from Australia.', 45, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 14, 'A Long, Strange Trip', 'Gates and Morris tend to an elderly man who was assaulted on the street. Sam ''s sister shows up unexpectedly. Brenner and Dubenko clash while treating a mother thought to have late-stage cancer. Dr. Morgenstern returns to the ER to assist a former mentor who is seriously ill.', 45, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 15, 'The Family Man', 'A car accident in the ambulance bay injures a woman with a young child and leaves the mother in need of surgery with a significant recovery time. Brenner has difficulty finding a family member to care for the daughter. Gates treats an elderly patient who refuses treatment because he''s afraid his condition will prolong an inevitable death. Morris impresses Claudia and her family. Neela tells Brenner about her job offer from North Carolina.', 45, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 16, 'The Beginning of the End', 'It''s Valentine''s Day. Dr. John Carter is back at the County. Brenner and Neela are getting closer. Dr. Banfield is having a hard time trying to have a baby. And Puck and mushrooms may not be a good combination.', 45, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 17, 'T-Minus-6', 'Carter finds himself struggling with County''s new technology and procedures. After becoming frustrated with the in vitro-fertilization, Banfield and her husband discuss adoption as an option. Sam''s mother arrives in an altered state of mind.', 45, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 18, 'What We Do', 'A camera crew shooting footage for a documentary interviews members of the ER staff. Detective Claudia Diaz is brought in, critically injured with gunshot wounds. Neela laments the lack of communication between her and Brenner. Sam struggles to reconcile with her mother. Carter''s condition worsens quite suddenly.', 45, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 19, 'Old Times', 'Neela and Sam are shocked when they arrive back to the airport with transplant organs only to find that their plane has left them. Dr. Carter gets a surprise visit from an old friend while waiting for his kidney transplant. Dr. Banfield bonds with an abandoned baby boy that is left at the ER.', 45, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 20, 'Shifting Equilibrium', 'On Neela''s last day at County, she has doubts as to whether she is making the right decision.', 45, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 21, 'I Feel Good', 'The ER doctors and nurses help out at Camp Del Corazon, a camp for kids who have had open-heart surgery, working alongside the camp counselor.', 45, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0108757')) AND numero_temporada = 15), 22, 'And in the End...', 'As Carter prepares to open a new facility for the underprivileged, some old friends/colleagues gather. Rachel Greene, Mark Greene''s daughter, applies for an internship at County.', 90, '2009-04-02');
