INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')), 1, 'Season 1', 'The first season introduces the incorrigible Father Ted, the dim-witted Father Dougal, the irascible Father Jack along with their long-suffering housekeeper Mrs. Doyle. Father Ted faces challenges at every turn as he tries to bring stability to his congregation and the surreal townspeople of Craggy Island, Ireland.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 1), 1, 'Good Luck, Father Ted', 'Ted gets his chance to be on TV when he is to be interviewed by a magazine programme. But ''FunLand'', the most pathetic travelling fair ever conceived has come to Craggy Island, and while Ted is distracted with Father Jack, Dougal seizes his moment of glory.', 24, '1995-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 1), 2, 'Entertaining Father Stone', 'The world''s most boring priest comes to stay, and he just won''t go away. After his worst ever birthday party, Father Ted prays for deliverance from Father Stone, but a lightning strike wasn''t what he expected.', 24, '1995-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 1), 3, 'The Passion of Saint Tibulus', 'The local cinema is showing a film condemned by the Church for its X-rated and blasphemous depiction of Saint Tibulus. Bishop Brennan is dispatched to the island to ensure that the priests take to the picket line in protest. But their defiant stand only gives more publicity to the film, which becomes an overnight success. It is left to Father Jack to stop the Bishop from sending them packing.', 24, '1995-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 1), 4, 'Competition Time', 'It''s the ''All Priests Stars In Their Eyes Lookalike Competition'', and showbusiness personality Henry Sellers, a former alcoholic, has landed on the island to host the festivities. Father Ted is determined not to go as Mother Teresa again, but he isn''t the only one to think of Elvis. It takes some quick thinking to beat Father Byrne''s team from nearby Rugged Island.', 24, '1995-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 1), 5, 'And God Created Woman', 'A blossoming romance between Father Ted and steamy novelist Polly Clarke threatens to come between a group of visiting nuns and their favourite priest. Among other things, Ted delivers an entire service in a matter of milliseconds, and becomes involved in an armed robbery.', 24, '1995-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 1), 6, 'Grant Unto Him Eternal Rest', 'After an overdose of floor polish, Father Jack finally bites the dust, and Ted and Dougal discover they''ve been left a fortune in his will - providing they allay his fear of being buried alive by spending a night with him in the crypt.', 24, '1995-05-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')), 2, 'Season 2', 'The second season carries on with the error prone lives of three priests living with their housekeeper in Ireland on the bizarre Craggy Island. The three Fathers disastrously attempt to rig a raffle, make efforts to give-up their vices for Lent , adopt a pet rabbit, and occasionally tend to matters of the soul.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 1, 'Hell', 'Ted, Dougal and Jack go on an all-expenses-spared holiday to Kilkelly Caravan Park. They meet a young couple, and are soon in trouble with the police. Entertainment comes in the shape of St Kevin''s Stump and the Magic Road. Father Jack goes missing; Father Noel Furlong and his youth group turn up to put the final nail in the coffin of the holiday.', 24, '1996-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 2, 'Think Fast, Father Ted', 'The roof of the Parochial House is leaking, and Ted decides on a raffle to raise the funds, with a car as the prize. Unfortunately, an accident with a cyclist puts something of a dent in the vehicle. A similar car is borrowed from the Dancing Priest in order to save the raffle; however, the priests must then win in order to return the car. Despite this intrigue, the roof does not get repaired.', 24, '1996-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 3, 'Tentacles of Doom', 'The Holy Stone of Clonrichert is to be upgraded to a class 2 relic, and unfortunately this entails three Bishops visiting the island - Father Jack must be housetrained quickly. Only one of the bishops dies - Ted therefore considers this to have been a relatively successful visit.', 24, '1996-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 4, 'Old Grey Whistle Theft', 'Ted goes on a picnic, Mr Benson''s whistle is stolen and Dougal learns an important lesson about true friendship. Ted narrowly avoids incriminating himself to save Dougal''s worthless hide', 24, '1996-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 5, 'A Song for Europe', 'Fathers Ted and Dougal enter A Song For Europe with My Lovely Horse. The tune is stolen from the b-side of a Norwegian song that didn''t even win A Song For Norway but the lyrics are all their own work. Somehow they get through to Eurovision and score.... nil points.', 24, '1996-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 6, 'The Plague', 'Rabbit-phobic Bishop Brennan pays a visit to investigate reports of Father Jack sleepwalking naked. Unfortunately Dougal has overrun the house with rabbits, and a Terry & June-style farce ensues as Ted and Dougal attempt to keep Father Jack in bed, and the ever-multiplying rabbits away from the bishop.', 24, '1996-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 7, 'Rock a Hula Ted', 'Ted is asked to judge the ''Lovely Girls'' competition while Dougal is left in charge of the house. Father Jack is mistaken for Bob Geldof and Dougal manages to give the house away to a feminist rock star called Niamh Connolly. Ted has to get the house back, but how will this affect his dinner plans with the winner of the ''Lovely Girls'' competition?', 24, '1996-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 8, 'Cigarettes and Alcohol and Rollerblading', 'Ted and co. enter a giving-things-up-for-Lent contest and soon discover that abstinence is easier preached than done. Father Jack sobers up for the first time in years, but Dougal and Ted find their resolve wavering. To strengthen their vows Ted calls in a nun to supervise them. She turns out to be a sadist of the first water, and the results are inevitable.', 24, '1996-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 9, 'New Jack City', 'After discovering Father Jack is suffering yet again(!) from "hairy hand syndrome," Ted is delighted to send Jack, by "doctor''s orders," to St. Clabberts Old Folks Home (otherwise known as ''Jurassic Park''). Unfortunately, Jack''s replacement happens to be one of the nastiest priests ever - Father Fintan Stack. Along with his disregard for the church, Stack has a rather irritating habit of playing jungle music loudly at 3 o''clock in the morning, and a plan is hatched to get Jack back to sort out Stack.', 24, '1996-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 2), 10, 'Flight Into Terror', 'Ted and co. end up crammed in an aeroplane along with every other priest who has appeared in their lives after a visit to the Shrine of Kinlettle. In a usual fit of stupidity, Dougal manages to empty the fuel tanks on the plane. To make matters worse, there are only two parachutes, so Ted devises a way for the priests to compete for the parachutes. Unfortunately, Jack has other plans.', 24, '1996-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')), 3, 'Season 3', 'Season three continues its'' hilarious portrayal of life on Craggy Island. With missteps abound, the Fathers Ted, Dougal and Jack become the target of pranks and revenge. Adventures on the mainland and poorly placed bets also add to absurdity.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 1, 'Are You Right There Father Ted?', 'Ted finally escapes to a new posting at Castlelawn Parochial House, Dublin, with civilised company and frequent jaunts to Paris. Unfortunately a slight misunderstanding over some expenses sends Ted back to his old compadres on the island. After a spot of lads'' housecleaning results in Ted being mistakenly tarred as a racist, Ted holds a celebration of Chinese culture to clear his name - though ''Kung Fu Fighting'' may not have been an inspired choice of soundtrack. Just when it looks like a happy ending might be in store, a mix-up over some soft furnishings and Nazi memorabilia leaves the Chinese community with a sweet ''n'' sour taste in the mouth.', 24, '1998-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 2, 'Chirpy Burpy Cheap Sheep', 'Ted gets mixed up in a web of intrigue and double-cross when he bets the Parochial House heating budget on Chris, the burping sheep. The lads bring Chris to stay at the house in an attempt to improve his chances at ''King of the Sheep 98'', but can Ted quell his burping in time for the great day?', 24, '1998-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 3, 'Speed 3', 'Ted and Dougal turn detective to discover who''s behind the bumper crop of hairy babies on Craggy Island. However when justice is done on the culprit he takes a terrible revenge. Dougal''s moonlighting stint as island milkman is marred by a bomb set to go off if the milk float drops below 4mph. Does ''The Poseidon Adventure'' hold the key to his rescue, or would Father Jack''s pet brick come in more useful?', 24, '1998-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 4, 'The Mainland', 'A perfectly routine trip to the mainland results in Dougal almost dying from malnutrition, Mrs Doyle being chucked in the clink, Ted nearly being beaten up by Victor Meldrew, and Father Jack joining Alcoholics Anonymous. A chance encounter with old friends Noel Furlong and the St. Luke''s Youth Group in some spooky caves spells spelaeological trouble for our heroes.', 24, '1998-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 5, 'Escape from Victory', 'It''s the All-Priests Over-75s Five-A-Side Football challenge, and disaster looms when Ted''s star player is nobbled by a bottle of Dreamy-Sleepy Nighty Snoozy-Snooze. Fortunately a pair of fake rubber arms and a remote-controlled wheelchair put our lads in with a chance of beating Dick Byrne this year. As long as they can fool the referee...', 24, '1998-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 6, 'Kicking Bishop Brennan up the Arse', 'A lost bet with Dick Byrne means Ted has to kick Bishop Brennan up the arse. On cue, Len arrives with PA Father Jessup, the world''s most sarcastic priest. Elaborate preparations, a camera, a skirting board, a set of watercolours and some psychological warfare on Ted''s part ensure a successful outcome. Or do they?', 24, '1998-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 7, 'Night of the Nearly Dead', 'Jumper-wearing pop sensation Eoin McLove comes to visit. Unfortunately his presence leads hundreds of infatuated middle-aged ladies to surround the house, and the usual hilarious mix-ups ensue. But McLove''s easy-going stage persona masks a terrible secret.', 24, '1998-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0111958')) AND numero_temporada = 3), 8, 'Going to America', 'Ted performs a genuinely unselfish act, and is rewarded with the offer of a parish in California - his wildest dreams come true. However, parting from his long-time companions at the Parochial House proves tricky. Unless Ted can break the news of his departure tactfully to Dougal, Jack and Mrs Doyle, he won''t be going to America...', 26, '1998-05-01');
