INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0112159', 'Neon Genesis Evangelion', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0030417'), 'SERIE', 'In a post-cataclysmic future, reluctant teen Shinji Ikari is called by his estranged father to pilot an Evangelion for NERV, humanity''s last defense against invading Angels threatening Tokyo-3.', '1995-01-01', 'https://m.media-amazon.com/images/M/MV5BZjZjZGI3ZDQtODNmZC00NjE0LTlmYTUtOTljMWI2YjNmMTQ0XkEyXkFqcGc@._V1_.jpg');
