INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0112178', 'Star Trek: Voyager', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0515237'), 'SERIE', 'Pulled to the far side of the galaxy, where the Federation is seventy-five years away at maximum warp speed, the crew of the Starfleet star-ship Voyager must forge a truce with a group of Maquis rebels in order to find a way home.', '1995-01-01', 'https://m.media-amazon.com/images/M/MV5BMmM2YjBjYzItYmFlOC00MDllLWJiOTQtNjY0MGY5NWI1MDFmXkEyXkFqcGc@._V1_.jpg');
