INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')), 1, 'Season 1', 'Pulled to the far side of the galaxy, where the Federation is 75 years away at maximum warp speed, a Starfleet ship must cooperate with Maquis rebels to find a way home.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 1, 'Caretaker', 'Stardate: 48315.6. The USS Voyager, led by Captain Kathryn Janeway, is sent into the dangerous Badlands in pursuit of a Maquis ship, only for both ships to find themselves 70,000 light years from home in the uncharted Delta Quadrant.', 92, '1995-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 2, 'Parallax', 'Stardate: 48439.7. As the Maquis crewmembers begin to integrate themselves into the Starfleet crew, Voyager becomes trapped in a quantum singularity.', 46, '1995-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 3, 'Time and Again', 'Stardate: Unknown. After being hit by the shockwave of a devastating planet-wide explosion, Voyager investigates. While on the surface, Janeway and Paris are accidentally ''shifted'' one day into the past.', 46, '1995-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 4, 'Phage', 'Stardate: 48532.4. During an away mission, Neelix is attacked and his lungs are surgically removed. His only hope for survival is if the crew of Voyager can get them back.', 46, '1995-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 5, 'The Cloud', 'Stardate: 48546.2. Janeway tries to figure out what her dynamic with the crew should be while all stuck in the Delta Quadrant together. Voyager tries to harvest omicron particles to refuel the ship, but inadvertently injures a spacefaring organism.', 46, '1995-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 6, 'Eye of the Needle', 'Stardate: 48579.4. The discovery of a wormhole leading to the Alpha Quadrant elates the crew, however, their only contact within range is a skeptical and paranoid Romulan.', 46, '1995-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 7, 'Ex Post Facto', 'Stardate: Unknown. Tom Paris is accused of a murder he claims he did not commit. His sentence is to re-live the last few moments of his victim''s life every 14 hours through a memory transplant.', 46, '1995-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 8, 'Emanations', 'Stardate: 48623.5. A transporter accident swaps Harry Kim with a dying woman from another dimension. Harry finds himself among aliens who believe he’s returned from their afterlife, while the woman, expecting paradise, wakes up on the Voyager.', 46, '1995-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 9, 'Prime Factors', 'Stardate: 48642.5. The Voyager crew are offered luxurious shore leave by the advanced and gregarious Sikarians, who have a device that could send Voyager 40,000 light years closer to home. However, Sikarian law strictly prohibits sharing their technology with others.', 46, '1995-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 10, 'State of Flux', 'Stardate: 48658.2. When stolen Federation technology is found on a severely damaged Kazon Nistrim ship, Seska becomes the prime suspect. The evidence is further reinforced when questions arise regarding her true heritage.', 46, '1995-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 11, 'Heroes and Demons', 'Stardate: 48693.2. Harry Kim disappears from the holodeck during his holo-novel, "Beowulf." According to the characters, he died at the hands of a mystical beast known as "Grendel". When Chakotay and Tuvok also disappear, the Doctor is transferred to the holodeck to investigate.', 46, '1995-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 12, 'Cathexis', 'Stardate: 48734.2. After Chakotay and Tuvok are injured in a shuttle accident, a non-corporeal life form begins to wreak havoc on Voyager by infiltrating the minds of the crew and altering the ship''s systems one by one.', 46, '1995-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 13, 'Faces', 'Stardate: 48784.2. The Vidiians capture Paris, Torres and Durst while on an away mission. Torres is taken to a lab and ''split'' into two people: one human, and one Klingon.', 46, '1995-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 14, 'Jetrel', 'Stardate: 48832.1. The inventor of a weapon that slaughtered Neelix’s people contacts Neelix to warn of a fatal disease he may have contracted as a side effect.', 46, '1995-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 1), 15, 'Learning Curve', 'Stardate: 48846.5. In order to bring some rebellious Maquis crewmembers into line, Tuvok gives them a Starfleet Academy crash course. Meanwhile, the crew investigate a series of failures affecting the Voyager’s bio-neural systems.', 46, '1995-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')), 2, 'Season 2', 'Capt. Janeway and her crew encounter the Kazon and other new Delta Quadrant enemies as they continue the long, perilous journey back to Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 1, 'The 37''s', 'Stardate: 48975.1. The crew happen upon a 1936 Ford truck adrift in space, leading to the discovery of a cryogenic chamber of humans abducted in the 1930s, including Amelia Earhart.', 46, '1995-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 2, 'Initiations', 'Stardate: 49005.3. A young Kazon, desperate to prove himself and earn his name, tries to attack Chakotay.', 46, '1995-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 3, 'Projections', 'Stardate: 48892.1. The Emergency Medical Hologram is activated during a red alert and finds the ship has been abandoned after an unknown emergency. As he explores, evidence mounts that the Doctor may in fact be the only real human in a holo-program called Voyager.', 46, '1995-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 4, 'Elogium', 'Stardate: 48921.3. While the crew of Voyager investigate a cluster of space-borne life forms, Kes begins exhibiting strange intense symptoms.', 46, '1995-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 5, 'Non Sequitur', 'Stardate: 49011. Harry Kim arises one morning to find he is back in San Francisco on Earth with his girlfriend Libby. In order to help him restore reality, he enlists the help of a shady figure in France by the name of Tom Paris, who has no idea who Harry is.', 46, '1995-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 6, 'Twisted', 'Stardate: Unknown. Voyager enters a spatial distortion ring, which causes the ship’s layout to shift in confusing ways.', 46, '1995-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 7, 'Parturition', 'Stardate: Unknown. Tom Paris and Neelix, while fighting over Kes’s affections, crash-land on a dangerous planet and become responsible for a sickly baby creature.', 46, '1995-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 8, 'Persistence of Vision', 'Stardate: Unknown. Captain Janeway starts seeing characters and objects from her holo-novel around the ship. Soon afterwards the crew begins entering a catatonic state one by one, while only Kes and the Doctor remain unaffected.', 46, '1995-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 9, 'Tattoo', 'Stardate: Unknown. Upon discovering a cultural symbol drawn in the ground on a planet that was used by his ancestors to ''heal the land'', Chakotay tries to contact the beings his tribe called the ''Sky Spirits.''', 46, '1995-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 10, 'Cold Fire', 'Stardate: 49164.8. The crew of Voyager make contact with the Caretaker''s mate, Suspiria, and a community of Ocampa that have been living on her Array. One of the Ocampa begins to train Kes in growing her psychic abilities, but pushes her to become more powerful than she can control.', 46, '1995-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 11, 'Maneuvers', 'Stardate: Unknown. After the Kazon steal some Federation technology Chakotay goes after them on his own and is captured.', 46, '1995-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 12, 'Resistance', 'Stardate: Unknown. Tuvok and B''Elanna are captured and imprisoned after an away mission to obtain a chemical vital to Voyager''s systems from a black market go wrong. Janeway is knocked unconscious and is rescued by a man who believes that she is his daughter.', 46, '1995-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 13, 'Prototype', 'Stardate: Unknown. After finding and repairing a robot found drifting in space, B''Elanna is abducted and forced to design a new prototype or Voyager will be destroyed.', 46, '1996-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 14, 'Alliances', 'Stardate: Unknown. Janeway tries to make an alliance with a Kazon sect for their own protection and so they can continue their journey through the Delta Quadrant.', 46, '1996-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 15, 'Threshold', 'Stardate: Unknown. After finding a type of dilithium that can survive at a higher temperatures, Tom Paris comes up with the ingenious idea of attempting to cross the transwarp threshold in an attempt to find a way to get home faster.', 46, '1996-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 16, 'Meld', 'Stardate: Unknown. In order to help out Lon Suder, a psychopath who killed a crewmember, Tuvok performs a mind meld. Soon after, he begins showing violent tendencies, which develop until he loses control.', 46, '1996-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 17, 'Dreadnought', 'Stardate: 49447. When Voyager encounters a Cardassian missile ship in the Delta Quadrant named ''Dreadnought'', B''Elanna must disarm it before it destroys a planet with millions of innocent people.', 46, '1996-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 18, 'Death Wish', 'Stardate: 49301.2. A suicidal Q threatens the future of the Q-Continuum after he requests asylum aboard Voyager.', 46, '1996-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 19, 'Lifesigns', 'Stardate: 46504.3. After receiving a Vidiian patient who is about to die from the Phage, the doctor transfers her consciousness into the ship''s computer and creates a holographic body. He soon finds himself becoming deeply attracted to her.', 46, '1996-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 20, 'Investigations', 'Stardate: 49485.2. After weeks of erratic behavior, Tom Paris leaves Voyager and joins a Talaxian convoy.', 46, '1996-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 21, 'Deadlock', 'Stardate: 49548.7. An accident in a plasma cloud duplicates Voyager after they are attacked by the Vidiians. During the aftermath, the ship is severely damaged, Ensign Wildman''s baby dies and Harry Kim is sucked into space through a hull breach.', 46, '1996-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 22, 'Innocence', 'Stardate: Unknown. When Tuvok crashes on a moon, he discovers three small children who believe they are about to die.', 46, '1996-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 23, 'The Thaw', 'Stardate: Unknown. The crew of Voyager encounters a planet that has recently entered an ice age. They discover a series of stasis chambers where a small group of people are mentally connected to an artificial environment that turned horribly wrong.', 46, '1996-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 24, 'Tuvix', 'Stardate: 49655.2. A transporter accident merges Tuvok and Neelix into one new being who calls himself ''Tuvix.''', 46, '1996-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 25, 'Resolutions', 'Stardate: 49690.1. When Captain Janeway and Chakotay contract an incurable virus they are left on a planet that shield them from its effects. While Janeway searches for a cure, she begins to form a deeper relationship with her first officer. Onboard Voyager, Tuvok, who is now in command, faces a near mutiny.', 46, '1996-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 2), 26, 'Basics (1)', 'Stardate: Unknown. Voyager receives a distress signal from Seska, who claims that Maje Cullah is going to take her baby away from her, a baby she says is Chakotay''s. Chakotay is skeptical, but can''t take the risk of abandoning his child, should it really prove to be his. Janeway authorises a mission to rescue Chakotay''s child and the ship moves deep into Kazon Nistrim territory. However: was Seska for real, or is this all an elaborate trap?', 46, '1996-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')), 3, 'Season 3', 'As Capt. Janeway and her crew continue their journey home, they face many obstacles, including a time rip that sends them back to 20th-century Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 1, 'Basics (2)', 'Stardate: 50023.4. Voyager is captured by the Kazon and the crew are dumped on a planet in its early stages of evolution.  As only Tom Paris and Lon Suder have evaded capture, it''s up to them and the EMH to come up with a plan to retake the ship.', 46, '1996-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 2, 'Flashback', 'Stardate: 50126.4. After falling ill to what appears to be a repressed memory Tuvok must perform a mind-meld with Captain Janeway in order to survive. The meld takes them back to when Tuvok was a junior science officer aboard the U.S.S. Excelsior under the command of Captain Hikaru Sulu.', 46, '1996-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 3, 'The Chute', 'Stardate: 50156.2. Paris and Kim are sent to an Akritian prison after being accused of a terrorist bombing.', 46, '1996-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 4, 'The Swarm', 'Stardate: 50252.3. Voyager must cross through the territory of a mysterious and fiercely isolationist species.  Meanwhile, B’Ellana tries to help the Doctor when he begins losing his memory.', 46, '1996-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 5, 'False Profits', 'Stardate: 50074.3. The crew encounter a Bronze Age culture ruled by two “Sages” – a pair of Ferengi who arrived through a wormhole from the Alpha Quadrant.', 46, '1996-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 6, 'Remember', 'Stardate: 50203.1. After Voyager encounter a telepathic species, B''Elanna starts having powerful dreams that depict the life of a woman and her lover in a time of great political and social upheaval.', 46, '1996-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 7, 'Sacred Ground', 'Stardate: 50063.2. Captain Janeway has to undergo a rigorous ritual in order to save Kes'' life when she is knocked unconscious.', 46, '1996-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 8, 'Future''s End (1)', 'Stardate: Unknown. Voyager is attacked by a Timeship from 500 years in the future, but the two ships are hurled into the past and Voyager is stranded in the year 1996.', 46, '1996-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 9, 'Future''s End (2)', 'Stardate: 50312.5. While trying to rescue Paris and Tuvok, Torres and Chakotay are captured by a gang of weapons smugglers who believe that they are from the government.', 46, '1996-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 10, 'Warlord', 'Stardate: 50348.1. A dying warlord transfers his consciousness to Kes’s body and uses her to stage a bloody coup on his home world.', 46, '1996-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 11, 'The Q and the Grey', 'Stardate: 50384.2. Q begins courting Captain Janeway, claiming that her having his child is the only way to end a civil war wracking the Q Continuum.', 46, '1996-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 12, 'Macrocosm', 'Stardate: Unknown. After returning from a first contact mission, Janeway, Neelix and the Doctor must retake Voyager from an infestation of microorganisms that grow to an alarming size.', 46, '1996-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 13, 'Fair Trade', 'Stardate: Unknown. Voyager arrives at the dangerous and uncharted Nekrit Expanse. Neelix, feeling useless now that he can’t guide them, reaches out to a shady contact to find the crew a map.', 46, '1997-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 14, 'Alter Ego', 'Stardate: 50460.3. Ensign Kim asks for Tuvok’s help controlling his emotions when he finds himself desperately in love with a holodeck character.', 46, '1997-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 15, 'Coda', 'Stardate: 50518.6. Captain Janeway and Chakotay are trapped in a time loop, reliving the same disastrous shuttle crash.', 46, '1997-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 16, 'Blood Fever', 'Stardate: 50537.2. Ensign Vorik expresses his desire to mate with B''Elanna during his Pon-Farr. After they get in a brawl over the matter, Torres begins showing signs of the Pon-Farr herself.', 46, '1997-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 17, 'Unity', 'Stardate: 50614.2. During an away mission, Chakotay discovers a Federation hailing signature coming from an alien planet. After landing, he learns that all is not peaceful, and those helping him have not been entirely honest about their true origins.', 46, '1997-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 18, 'Darkling', 'Stardate: 50693.2. When the doctor tries to improve his personality by incorporating the psychological profiles of famous and historical people, he is overwhelmed by their dark sides and begins exhibiting signs of a split personality, one the regular doctor, and the other dark and evil. Kes asks to leave Voyager when they encounter a race with vast knowledge of the region of space they are currently exploring.', 46, '1997-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 19, 'Rise', 'Stardate: Unknown. Neelix is pushed to the limits when Tuvok''s attitude becomes too much to bear while the pair is on an away mission to help evacuate a Nezu planet, which is being bombarded with asteroids.', 46, '1997-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 20, 'Favorite Son', 'Stardate: 50732.4. Harry Kim experiences strong senses of deja vu in an unknown region of space. He soon learns that he is native to this region and that he is T''Karian, not human.', 46, '1997-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 21, 'Before and After', 'Stardate: 50973. Kes begins traveling backwards through time from the moment of her death. With each shift, she comes closer to a solution but she also grows months and years younger at a time.', 46, '1997-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 22, 'Real Life', 'Stardate: 50863.2. The Doctor decides he should create a holographic family in order to expand himself. When B''Elanna is disgusted by its unrealistic perfectionism, she alters the program to include random events and outcomes with interesting and devastating results.', 46, '1997-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 23, 'Distant Origin', 'Stardate: Unknown. An alien palaeontologist discovers a common ancestral link between his people and humans. He believes that this proves that his people (the Voth) evolved on Earth and migrated to the Delta Quadrant millions of years ago, but his government is not as willing to believe his interpretation of the evidence.', 46, '1997-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 24, 'Displaced', 'Stardate: 50912.4. Crew members are replaced one-by-one with aliens from an unknown race.', 46, '1997-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 25, 'Worst Case Scenario', 'Stardate: 50953.4. B''Elanna Torres discovers a holodeck program where Chakotay and the Maquis rebel against Janeway.', 46, '1997-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 3), 26, 'Scorpion (1)', 'Stardate: 50984.3. Voyager finally enters Borg space, only to discover a threat more powerful than the Borg themselves.', 46, '1997-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')), 4, 'Season 4', 'On their long voyage back to Earth, Capt. Janeway and her spaceship crew do battle with Kazons, Borg, Cardassians and other galactic enemies.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 1, 'Scorpion (2)', 'Stardate: 51003.7. The Voyager crew, allied with the Borg, prepare to battle the sinister alien Species 8472. But can an alliance between opinionated individuals and a collective race of consumers survive such fundamental differences?', 44, '1997-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 2, 'The Gift', 'Stardate: 51008. Janeway begins the process of integrating Seven of Nine into the Voyager crew. Meanwhile, Kes begins to experience extreme advances in her mental powers.', 46, '1997-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 3, 'Day of Honor', 'Stardate: Unknown. When Voyager is forced to eject its warp core, Torres and Paris take a shuttle to retrieve it. But when the shuttle is damaged, the two officers are forced to abandon it—and find themselves alone in space with a rapidly depleting oxygen supply.', 46, '1997-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 4, 'Nemesis', 'Stardate: 51082.4. Chakotay is stranded on a planet where two races are trying to wipe each other out in a massive, planet-wide war.', 46, '1997-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 5, 'Revulsion', 'Stardate: 51186.2. Torres and the Doctor assist a holographic ship''s servant whose crew has been killed. Meanwhile, when Kim and Seven of Nine are assigned to work on a project together, the ensign attempts to get to know the person inside the mysterious former-Borg.', 46, '1997-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 6, 'The Raven', 'Stardate: Unknown. Seven of Nine steals a shuttlecraft and flees Voyager in an attempt to answer a mysterious homing beacon and return to the Borg Collective.', 46, '1997-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 7, 'Scientific Method', 'Stardate: 51244.3. When members of the crew begin suffering from bizarre mutations, Seven of Nine may be the only one who can uncover the reasons why.', 46, '1997-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 8, 'Year of Hell (1)', 'Stardate: 51268.4. The Voyager crew finds its determination and morale challenged when trying to survive a brutal, long-lasting conflict with a race called the Krenim.', 46, '1997-11-05');
