INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 10, 'Random Thoughts', 'Stardate: 51367.2. After making contact with a race of telepaths, the Voyager crew must help defuse a volatile situation when a local citizen acts on a random, violent thought inadvertently tranferred from Torres.', 46, '1997-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 11, 'Concerning Flight', 'Stardate: 51386.4. Janeway and the hologram of Leonardo da Vinci must work together to retrieve Voyager''s main computer processor, which has been stolen by alien thieves.', 46, '1997-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 12, 'Mortal Coil', 'Stardate: 51449.2. Neelix is killed during an away mission, but Seven of Nine is able to revive him using Borg technology, leading him into a crisis of faith regarding the afterlife.', 46, '1997-12-17');
