INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 14, 'Message in a Bottle', 'Stardate: Unknown. When Seven discovers an alien communications array, the crew devises a way of sending the Doctor''s program across it into the Alpha Quadrant, where he finds himself aboard a Starfleet vessel that has been commandeered by the Romulans.', 46, '1998-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 15, 'Hunters', 'Stardate: 51501.4. As letters from the Alpha Quadrant come trickling through the communications array, the Voyager crew learns of an assortment of joyous, disturbing, and inevitable news.', 46, '1998-02-11');
