INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 18, 'The Killing Game (1)', 'Stardate: Unknown. After having taken over Voyager, the Hirogen supply the crew members with artificial identities and subject them to violent holodeck simulations.', 46, '1998-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 4), 19, 'The Killing Game (2)', 'Stardate: 51715.2. The crew must stop an artificial holodeck rendition of a World War II battle from spilling onto the decks of the ship while simultaneously dealing with a Hirogen takeover.', 46, '1998-03-04');
