INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 5), 23, 'Relativity', 'Stardate: Unknown. The crew of a time ship from the future recruits Seven to attempt preventing Voyager''s forthcoming destruction.', 46, '1999-05-12');
