INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 5), 25, 'Equinox (1)', 'Stardate: Unknown. Voyager encounters another Federation starship, the USS Equinox, in the Delta Quadrant. But as an alien presence prepares an attack, Janeway begins to uncover the Equinox''s sinister secret.', 46, '1999-05-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')), 6, 'Season 6', 'The Voyager crew encounters Borg children and establishes long-range communications with Starfleet, while the Doctor becomes a musical celebrity.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 1, 'Equinox (2)', 'Stardate: Unknown. As Janeway''s determination to capture Captain Ransom becomes an obsession, Ransom begins having second thoughts about his methods.', 44, '1999-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 2, 'Survival Instinct', 'Stardate: 53049.2. The arrival of three mysterious "individuals" among an influx of visitors to Voyager has mysterious consequences for Seven, who must relive a Borg experience from eight years earlier.', 44, '1999-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 3, 'Barge of the Dead', 'Stardate: Unknown. A near-death experience sends Torres into the apparent Klingon afterlife, and leaves her searching for answers when she returns.', 44, '1999-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 4, 'Tinker Tenor Doctor Spy', 'Stardate: Unknown. The Doctor programs himself with the ability to daydream, but quickly loses track of the line between reality and fantasy. Meanwhile, an alien attempts to spy on Voyager through the Doctor’s eyes but takes his imaginings for reality.', 44, '1999-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 5, 'Alice', 'Stardate: Unknown. Tom Paris buys a beaten-up old hot-rod of a ship to restore, but B’Ellana begins to worry as Tom grows increasingly obsessed with the ship.', 44, '1999-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 6, 'Riddles', 'Stardate: Unknown. A mysterious alien attack leaves Tuvok''s brain damaged and his personality altered, leaving Neelix to try to rehabilitate him.', 44, '1999-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 7, 'Dragon''s Teeth', 'Stardate: Unknown. The ship is placed in danger when it comes under attack from a territorial race of aliens known as the Turei. While sheltering on a planet, Captain Janeway tries to make an alliance with its inhabitants, the Vaadwaur. However, she soon begins to think that the Vaadwaur may pose a bigger threat than the enemy above.', 44, '1999-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 8, 'One Small Step', 'Stardate: Unknown. Voyager searches for a long-lost Mars spacecraft.', 44, '1999-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 9, 'The Voyager Conspiracy', 'Stardate: Unknown. Seven of Nine obsessively investigate pursues a conspiracy theory about Voyager’s arrival in the Delta Quadrant.', 44, '1999-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 10, 'Pathfinder', 'Stardate: Unknown. On Earth, Lt. Reginald Barclay works on a way to contact Voyager, but grows  increasingly obsessed with his own holodeck simulation of the crew.', 44, '1999-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 11, 'Fair Haven', 'Stardate: Unknown. As the crew enjoys time off in a holo-program created by Tom Paris, and set in an Irish village named ''Fair Haven,'' Captain Janeway falls for a handsome holo-character specifically designed for her. A deadly neutrino wave approaching Voyager shortly bring the festivities to a halt as this wave may prove to be more dangerous than they first imagined.', 44, '2000-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 12, 'Blink of an Eye', 'Stardate: Unknown. Voyager becomes the target of a society it inadvertently helped to create within a short period of time.', 44, '2000-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 13, 'Virtuoso', 'Stardate: Unknown. When the Doctor''s singing talents are discovered by a technologically superior race, his new found popularity makes him consider resigning his commission to stay on the alien world with his millions of adoring fans.', 44, '2000-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 14, 'Memorial', 'Stardate: Unknown. The crew of Voyager experience vivid memories and dreams of a battle they don''t remember having, with an enemy they have never encountered.', 44, '2000-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 15, 'Tsunkatse', 'Stardate: Unknown. Seven of Nine is kidnapped and forced into the ring in a violent combat sport.', 44, '2000-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 16, 'Collective', 'Stardate: Unknown. Voyager encounters a damaged Borg cube run by immature would-be drones cut off from the Collective.', 44, '2000-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 17, 'Spirit Folk', 'Stardate: Unknown. The inhabitants of the holo-city of Fair Haven suspect the Voyager crew of having mystical powers when they witness the use of their futuristic technology.', 44, '2000-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 18, 'Ashes to Ashes', 'Stardate: Unknown. Ensign Lindsay Ballard returns to Voyager after being killed during a previous away mission. An alien race known as the Kobali, whose only method of reproduction is ''resurrection'' of the dead through genetic engineering had revived her and taken her as a new member of their race. When the full extent of her new Kobali genes are activated, they reach a point where she must choose between her old home on the ship, or her new home with her adoptive Kobali family.', 44, '2000-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 19, 'Child''s Play', 'Stardate: Unknown. Seven''s feelings and maternal instincts are awakened when the crew locates the parents of one of the Borg children to whom Seven has grown attached.', 44, '2000-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 20, 'Good Shepherd', 'Stardate: Unknown. Captain Janeway takes three crewmen with poor performance records on an away mission in the Delta Flyer in an attempt to bring them to Starfleet standards. However, an unexpected collision with a Dark Matter comet leaves the crew in a perilous situation.', 44, '2000-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 21, 'Live Fast and Prosper', 'Stardate: Unknown. A group of con artists impersonate Captain Janeway and the crew of Voyager. The crew must find the imposters soon, or they, themselves will be punished for the con artists'' crimes.', 44, '2000-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 22, 'Muse', 'Stardate: Unknown. An alien poet discovers an unconscious B''Elanna Torres after her crash landing in the Delta Flyer. However, this poet intends on using her in a play based on her life on Voyager to win favour with his Warlord.', 44, '2000-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 23, 'Fury', 'Stardate: Unknown. Kes returns to Voyager in a state of rage, blaming Captain Janeway for her past. Using her expanded Ocampan powers in a fit of revenge, she travels through time to deliver the crew to the Vidiians.', 44, '2000-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 24, 'Life Line', 'Stardate: Unknown. News reaches Voyager through the up-and-running Pathfinder project that the Doctor''s creator, Lewis Zimmerman, is critically ill. In an attempt to save his life, the Doctor''s program is transmitted to the Alpha Quadrant, but once there, he finds Zimmerman does not want to be examined by an ''obsolete'' EMH program.', 44, '2000-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 25, 'The Haunting of Deck Twelve', 'Stardate: Unknown. When Voyager encounters some engineering problems, Neelix keeps the Borg children entertained by telling the story of an adventure that the crew experienced several months ago, with the ghost that lives on deck twelve.', 44, '2000-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 6), 26, 'Unimatrix Zero (1)', 'Stardate: Unknown. Seven of Nine is contacted by Borg drones who have the ability to exist in a virtual realm that gives them freedom as individuals.', 44, '2000-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')), 7, 'Season 7', 'Capt. Janeway leads the Voyager in a fight against the Borg, delves into political infighting, escapes a void and finally makes her way back home.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 1, 'Unimatrix Zero (2)', 'Stardate: 54014.4 - Partially transformed into Borg drones, Janeway, Tuvok, and Torres run a covert operation on board a Borg ship to infect the collective with a virus that will free subdued individuals from the hive''s control.', 44, '2000-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 2, 'Imperfection', 'Stardate: 54129.4 - A key Borg component in Seven''s brain begins shutting down, leading to the possibility that she may be facing the equivalent of a terminal illness.', 44, '2000-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 3, 'Drive', 'Stardate: 54058.6 - Torres and Paris'' relationship takes a twist on the eve of a shuttle racing event Paris has entered, celebrating the anniversary of a peace treaty in a former war zone.', 44, '2000-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 4, 'Repression', 'Stardate: 54090.4 - An investigation of mysterious attacks on members of the crew uncovers a buried plot involving Tuvok and a Maquis fanatic.', 44, '2000-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 5, 'Critical Care', 'Stardate: Unknown - The Doctor is abducted from Voyager and forced to work in a hospital where patients are treated based on their social status.', 44, '2000-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 6, 'Inside Man', 'Stardate: 54208.3 - The Voyager crew receives a transmission from the Alpha Quadrant that contains an interactive holographic program of Lieutenant Barclay, who informs them that Starfleet has found Voyager a way home.', 44, '2000-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 7, 'Body and Soul', 'Stardate: 54283.3 - In a region of space where holograms are prohibited, the Doctor is forced to hide by transferring his program into Seven''s mind, upon which he takes over control of her body.', 44, '2000-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 8, 'Nightingale', 'Stardate: 54274.7 - Ensign Kim finds himself making the hard choices of mission commander when he agrees to help the crew of a ship in need.', 44, '2000-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 9, 'Flesh and Blood (1)', 'Stardate: 54337.5 - Voyager answers a distress call from a Hirogen outpost – only to find carnage caused by holographic technology that Captain Janeway has given them.', 45, '2000-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 10, 'Flesh and Blood (2)', 'Stardate: 54337.5 - Voyager secretly trails two Hirogen ships in pursuit of the renegade hologram ship. Iden, the band''s self-appointed leader, begins showing signs of delusional behaviour when he considers himself as the ''saviour of his people'', and believes that his people will worship him as a God in their new settlement. With Voyager and the Hirogen ships trailing close behind, the Doctor and Torres must find a way to disable the ships and the holograms before they come under attack from the Hirogen, and before Iden can execute his plan.', 40, '2000-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 11, 'Shattered', 'Stardate: Unknown - A spatial anomaly divides Voyager into various time frames of the past and future, leaving Chakotay as the only person who may be able to put the pieces back together.', 44, '2001-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 12, 'Lineage', 'Stardate: 54452.6 - When B''Elanna learns she is pregnant, she tries to proactively repress her child''s Klingon heritage on the basis of her own troubled past.', 44, '2001-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 13, 'Repentance', 'Stardate: 54474.6 - When Voyager provides emergency transportation for alien prisoners sentenced to die, a medical procedure unexpectedly and radically changes the values and temperament of one of the prisoners.', 44, '2001-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 14, 'Prophecy', 'Stardate: 54518.2 - The captain of a Klingon ship on a generational holy mission believes Torres'' unborn child may lead them to a new era of enlightenment.', 44, '2001-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 15, 'The Void', 'Stardate: 54553.4 - Voyager is pulled into a barren spatial void where survival is based on preying upon others.', 44, '2001-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 16, 'Workforce (1)', 'Stardate: 54584.3 - The Voyager crew is abducted to an alien world, where their memories are altered and they are dropped into the large population of an industrial labor force.', 44, '2001-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 17, 'Workforce (2)', 'Stardate: 54622.4 - It''s up to Chakotay, Kim, and the Doctor to liberate the Voyager crew and help uncover a conspiracy of illegal labor practices.', 44, '2001-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 18, 'Human Error', 'Stardate: Unknown - Seven of Nine runs a series of holodeck simulations to explore her untapped emotions.', 44, '2001-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 19, 'Q2', 'Stardate: 54704.5 - Q comes to Voyager and asks Janeway to help him teach lessons of responsibility to his troublesome son.', 44, '2001-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 20, 'Author, Author', 'Stardate: 54732.3 - When the Doctor arranges to have his recently completed holodeck novel published in the Alpha Quadrant, certain aspects of the story hit too close to home among his shipmates.', 44, '2001-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 21, 'Friendship One', 'Stardate: 54775.4 - The Voyager crew, on a mission to track down a historic Earth probe designed to contact intelligent life, finds the probe had indeed crossed paths with another civilization, but with catastrophic results.', 44, '2001-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 22, 'Natural Law', 'Stardate: 54817.5 - Chakotay and Seven find themselves trapped with a primitive culture that is separated from the rest of its world by an energy field designed to protect them.', 44, '2001-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 23, 'Homestead', 'Stardate: 54868.6 - Neelix finds he must make hard choices when he becomes involved in the struggle of Talaxian refugees whose home in an asteroid belt is threatened by alien miners.', 44, '2001-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 24, 'Renaissance Man', 'Stardate: 54890.7 - The Doctor is forced to carry out a secret mission where he must impersonate members of the Voyager crew.', 44, '2001-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112178')) AND numero_temporada = 7), 25, 'Endgame', 'Stardate: 54973.4 - Twenty-six years in the future, a regretful Admiral Janeway hatches an audacious plan to bring Voyager home sooner, rather than have it spend an additional sixteen years making its journey.', 86, '2001-05-23');
