INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0112230', 'Xena: Warrior Princess', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0561703'), 'SERIE', 'Xena, a mighty Warrior Princess with a dark past, sets out to redeem herself. She is joined by small town bard, Gabrielle. Together they journey the ancient world and fight for the greater good against ruthless Warlords and Gods.', '1995-01-01', 'https://m.media-amazon.com/images/M/MV5BZWNhMmQ1YzEtMWM0YS00ZDcxLWFkMjEtNWYyOGE2MjhhYWUxXkEyXkFqcGc@._V1_.jpg');
