INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 1, 'Sins of the Past', 'Xena battles an evil warlord, a vengeful Cyclops and harsh weather during her journey home to Amphipolis, where she''s joined by a young woman named Gabrielle, who''s a resourceful young protege.', 44, '1995-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 2, 'Chariots of War', 'Xena defends a town against a band of thugs led by a father and son duo, and when she is wounded, Gabrielle is left worrying for the warrior princess.', 44, '1995-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 3, 'Dreamworker', 'When Gabrielle is kidnapped by a mystic, Xena enters an altered state of consciousness and must face ghosts from her past in order to rescue her friend.', 44, '1995-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 4, 'Cradle of Hope', 'Xena employs stealthy maneuvers to protect an infant who an oracle claims will one day usurp the King''s throne. Meanwhile, Xena must also make sure that Pandora, the granddaughter of the legendary original, is able to reset the lock on her precious box.', 44, '1995-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 5, 'The Path Not Taken', 'In order to stop a war Xena must save a princess that has been taken from her home. The kidnapping could lead to a war. Xena realizes that a weapons dealer is the one that has caused everything. When she tracks the dealer, she meets her old love Marcus, but she is not sure how she feels about him.', 44, '1995-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 6, 'The Reckoning', 'Xena is mistaken for the killer who attacked and murdered a group of townspeople and is put on trial, causing Ares, the god of war, to be delighted at the success of his plan.', 44, '1995-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 7, 'The Titans', 'Gabrielle fools around with an ancient scroll and releases three Titans from centuries of captivity. Once again, Xena must save a village from destruction. Gabrielle also finds time for love.', 44, '1995-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 8, 'Prometheus', 'When the gods capture Prometheus, mankind begins to lose the gifts he gave them: fire and the ability to heal themselves. It''s up to Xena, Gabrielle, Hercules and Iolaus to try to free Prometheus from his chains but whoever is the one who frees him, may end up dead.', 44, '1995-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 9, 'Death in Chains', 'Xena must free Hade''s sister, Celesta, Death Herself, from King Sisyphus who wants to cheat death by holding her hostage, thus prolonging his life.', 44, '1995-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 10, 'Hooves & Harlots', 'When Xena and Gabrielle encounter the Amazons, Gabrielle tries to save an Amazon and unwittingly finds herself an Amazon princess.', 44, '1995-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 11, 'The Black Wolf', 'Xena infiltrates a band of rebels led by the Black Wolf and helps them defend themselves against Xerxes the warlord.', 44, '1996-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 12, 'Beware Greeks Bearing Gifts', 'Helen of Troy summons Xena and asks her to help end the war between the Greeks and the Trojans, that began over her.', 44, '1996-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 13, 'Athens City Academy of the Performing Bards', 'Gabrielle wants to enter the Athens City Academy of the Performing Bards, but finds that it is not quite what she thought it would be. She helps another aspiring bard discover his true storytelling talent.', 44, '1996-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 14, 'A Fistful of Dinars', 'Xena searches for Ambrosia, a substance capable of turning someone into a god. She hopes to find it before someone who is unworthy to be a god does.', 44, '1996-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 15, 'Warrior... Princess', 'The daughter of King Lias, Diana, is the target of assassins. Fortunately, Xena looks almost exactly like her. So, Xena goes undercover to force the assassins out of hiding and capture them.', 44, '1996-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 16, 'Mortal Beloved', 'When her dead love Marcus, asks Xena to help save good souls, she travels to the underworld to set things right.', 44, '1996-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 17, 'The Royal Couple of Thieves', 'Xena enlists the help of Autolycus, the King of Thieves, in order to steal a treasure chest from a warlord and return it to its rightful owners - unless Autolycus has something to say about that.', 44, '1996-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 18, 'The Prodigal', 'After freezing in the face of danger, a confused Gabrielle returns home to Potidaea, where she receives a not-so-warm welcome from the people, who have hired a so-called warrior to save them from a warlord.', 44, '1996-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 19, 'Altared States', 'A young boy is hunted by his father and brother. They want to sacrifice him to their god, because their "faith" demands it. It''s up to Xena and a drugged Gabrielle to save him.', 44, '1996-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 20, 'Ties That Bind', 'As the god of war, Ares, schemes to make Xena lead his army, the warrior princess meets a man claiming to be her long-lost father.', 44, '1996-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 21, 'The Greater Good', 'Xena helps Salmoneus, aka Lord Seltzer, when a warlord wants him dead, due to a bad transaction. Meanwhile, a mysterious blond woman is stalking Xena.', 44, '1996-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 22, 'Callisto', 'The female warrior Callisto, tries to turn the world against Xena by committing acts of terrorism in her name, while Xena struggles to reclaim her true identity and discover why this angry young woman is doing this.', 44, '1996-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 23, 'Death Mask', 'After learning a raiding party''s leader was responsible for the destruction in their village, Xena and her brother set out to destroy him.', 44, '1996-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 1), 24, 'Is There a Doctor in the House?', 'Xena attempts to stop a war between two brothers, while Gabrielle tends to a pregnant Amazon sister, who is carrying the child of a centaur.', 44, '1996-07-29');
