INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 1, 'Orphan of War', 'When Xena tries to help the centaurs protect a sacred stone that contains their evil, she encounters someone from her past...her son.', 44, '1996-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 2, 'Remember Nothing', 'When Xena defends the Fates''s temple, they give her the gift of changing the past: her brother Lyceus never died and she never became the warrior princess...but that also means she never met Gabrielle.', 44, '1996-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 3, 'The Giant Killer', 'When Gabrielle defends a young Isrealite named David, her life is threatended until Xena proposes to fight her old friend, the giant Goliath in return for freedom for the Philistines.', 44, '1996-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 4, 'Girls Just Wanna Have Fun', 'When Orpheus loses the power to subdue the god Bacchus with his music, Xena and Gabrielle risk their lives to end Bacchus''s reign of terror.', 44, '1996-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 5, 'Return of Callisto', 'Gabrielle plans to marry Perdicus, her hometown sweetheart, and must leave Xena and their travels, at the same time that Callisto has escaped from prison and is headed straight for them with vengeance in mind.', 44, '1996-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 6, 'Warrior... Princess... Tramp', 'When Diana''s father takes ill, Xena is summoned and runs into yet another lookalike, a barmaid named Meg, who seems quite taken with Joxer.', 44, '1996-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 7, 'Intimate Stranger', 'Callisto makes a bargain with Ares, from Tarturus, to switch bodies with Xena, sending Xena into Tarturus and freeing Callisto. Xena, in Callisto''s form, makes her own bargain with Hades, to make things right but the only problem is...she has one day to fix it.', 44, '1996-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 8, 'Ten Little Warlords', 'Trapped in the body of Callisto, Xena must help a mortal Ares recover his sword and restore him as the god of war. If she doesn''t mortals will not be able to control their anger and she''ll never recover her own body.', 44, '1996-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 9, 'A Solstice Carol', 'During Winter Solstice, Xena and Gabrielle visit a town where it''s Scrooge-like King has deemed that celebrating the holiday is a crime.', 44, '1996-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 10, 'The Xena Scrolls', 'In the year 1940, two female archaeologists searching for the Xena scrolls end up in an ancient tomb confronting legendary figures from the past.', 44, '1997-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 11, 'Here She Comes... Miss Amphipolis', 'Xena masquerades as a beauty pageant contestant, to stop a sabateur, bent on destroying a peace treaty between two warlords.', 44, '1997-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 12, 'Destiny', 'After being gravely injured, Xena''s life flashes before her, including the time when she learned the art of pressure points from a slavegirl and when she met Julius Caesar for the very first time.', 44, '1997-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 13, 'The Quest', 'After Xena''s death, Gabrielle becomes Queen of the Amazons, while Autolycus finds himself possessed by the warrior princess, Xena who needs ambrosia to bring herself back to life. But Xena''s rebirth and Gabrielle''s life are both threatened by an Amazon bent on obtaining the Amazon crown and the ambrosia.', 44, '1997-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 14, 'A Necessary Evil', 'Xena, Gabrielle and the Amazons must battle an evil Amazon, who ate ambrosia and is now a god. She wants Gabrielle dead and in order to stop her, Xena and Gabrielle resort to asking for the help of the now immortal Callisto.', 44, '1997-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 15, 'A Day in the Life', 'Xena and Gabrielle spend a day trying to save two villages, one from a band of thugs, the other from a giant, while getting on each other''s nerves and trying to not kill on another.', 44, '1997-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 16, 'For Him the Bell Tolls', 'With Xena away on a mission, Gabrielle must contend with Aphrodite, who''s interfering in one of Cupid''s lovespells that will unite two kingdoms and who''s put a spell on Joxer, who behaves like a real hero whenver a bell rings.', 44, '1997-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 17, 'The Execution', 'Xena and Gabrielle have only one day to determine what really happened when Gabrielle''s friend, Meleagor, is sentenced to death for a murder he didn''t commit.', 44, '1997-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 18, 'Blind Faith', 'After getting oil in her eys during a fight, Xena goes blind and must deal with a man determined to kill her and rescue Gabrielle before she is forced to marry a king, who has died, or Gabrielle will soon join him.', 44, '1997-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 19, 'Ulysses', 'Xena and Gabrielle must help Ulysses, King of Ithica, who is trying to return to his island homeland after ten years away, but the god of the sea, Poseidon, doesn''t make it easy.', 44, '1997-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 20, 'The Price', 'After becoming the hunted prey of the vicious Horde, Xena must lead the local army against them, while Gabrielle tends to the wounded and worries that Xena is returning to her dark and dangerous ways by stooping to the Horde''s level.', 44, '1997-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 21, 'Lost Mariner', 'After a shipwreck, Xena must rescue Gabrielle from the cursed ship of Cecrops, the lost mariner, where anyone who steps aboard is there until they die.', 44, '1997-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 2), 22, 'A Comedy of Eros', 'When Cupid''s infant son, Bliss, runs amok putting love spells on unsuspecting people, Xena falls in love with the warlord, Draco, Draco falls for Gabrielle and Gabrielle gets the hots for Joxer.', 44, '1997-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 1, 'The Furies', 'At Ares''s request, Xena is judged by the Furies for not avenging the murder of her father and is punished by persecution and madness, leaving Gabrielle to try and solve the problem and reverse Xena''s insanity.', 44, '1997-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 2, 'Been There, Done That', 'The day goes from bad to worse when Joxer is killed, but when the day begins again...and again...Xena realizes she''s the only one who knows what''s happening and remembers the previous days, she has a second chance to change things.', 44, '1997-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 3, 'The Dirty Half Dozen', 'Xena, Gabrielle and four warriors go up against Ares and his new army who possess armor and weapons forged by the god, Hephaestus, which cannot be harmed by any mortal weapons.', 44, '1997-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 4, 'The Deliverer', 'When Xena travels to Brittania to help stop Caesar''s invasion, Gabrielle is tricked into losing her blood innocence, by taking the life of an innocent, which binds her to the evil ""one god"" Dahuk.', 44, '1997-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 5, 'Gabrielle''s Hope', 'In Brittania, Gabrielle becomes pregnant and rapidly gives birth to a baby girl she names Hope. Xena is unsure of what to do because the child is the offspring of the evil god Dahuk and she cannot decide between killing the child or protecting her.', 44, '1997-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 6, 'The Debt (1)', 'When Xena is summoned to the distant kingdom of Chin to kill the Green Dragon, a task she left undone years before, she tells Gabrielle about her past in Chin in an attempt to justify why she must commit murder.', 44, '1997-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 7, 'The Debt (2)', 'After Gabrielle''s betrayal of Xena''s murderous intentions, Xena is imprisoned by the Green Dragon and sentenced to die, and she reminisces about Lao Mao''s teachings and the debt owed to her.', 44, '1997-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 8, 'The King of Assassins', 'It''s double trouble when Gabrielle, Autolycus and Joxer plot to stop Joxer''s lookalike brother, Jett, a deadly assassin, from killing his next target - Queen Cleopatra.', 44, '1997-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 9, 'Warrior... Priestess... Tramp', 'When Xena and Gabrielle meet yet another Xena-lookalike, a virgin priestess named Leah, they have to figure out who''s plotting against Leah and keep Meg and Joxer safe at the same time.', 44, '1998-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 10, 'The Quill Is Mightier...', 'Jealous of Xena''s legendary deeds, Aphrodite puts a spell on Gabrielle''s scroll, causing everything written on it to magically become real.', 44, '1998-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 11, 'Maternal Instincts', 'Maternial instincts are in the air when Gabrielle encounters her evil daughter Hope, who has freed Callisto in order to kill Xena''s son, Solan and plans on severing the friendship of Xena and Gabrielle forever.', 44, '1998-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 12, 'The Bitter Suite', 'After trying to kill one another, grief-stricken Xena and Gabrielle awake in a strange land called Illusia, filled with familiar faces, where they must face the pain and anger caused by the deaths of their children and forgive one another in order to live.', 44, '1998-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 13, 'One Against an Army', 'Xena, alone, must battle the ruthless Persian army and stop them from plundering Greece, as well as save a poisoned Gabrielle who is slowly dying.', 44, '1998-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 14, 'Forgiven', 'A brash teen tries to convince Xena that she would make a better partner than Gabrielle, by leading the duo to the stolen Urn of Apollo.', 44, '1998-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 15, 'King Con', 'When Joxer is beaten to near-death, Xena teams up with two con artists to avenge Joxer, with a major con scam against a ruthless gaming house owner and his son.', 44, '1998-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 16, 'When in Rome...', 'It''s all about power, when Xena must deal with Caesar and the politics of Rome by trading a Roman aristocrat for the leader of the Gauls, whom Xena wants freed but first she must try not to kill the hated Caesar.', 44, '1998-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 17, 'Forget Me Not', 'Tortured by her memories of Hope and past misdeeds, Gabrielle visits the temple of Mnemosyne, goddess of memory, and must travel through her past in an effort to live with her memories or erase them forever. Meanwhile, Joxer must protect Gabrielle''s body while her mind is away.', 44, '1998-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 18, 'Fins, Femmes and Gems', 'While trying to recover the North Star that Aphrodite has stolen, Xena becomes obsessed with fish, Gabrielle with her own reflection and Joxer with being an apeman, all thanks to Aphrodite''s distracting obsession spells.', 44, '1998-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 19, 'Tsunami', 'Xena must board a ship carrying prisoners when Gabrielle, in the belief she''s freeing a captured Autolycus, does the same, but they''re all wet when a tsunami strikes.', 44, '1998-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 20, 'Vanishing Act', 'Xena and Gabrielle team up with Autolycus to recover a statue that is a symbol of peace between two villages, but they must steal it back Autolycus''s way in order for him to maintain his reputation.', 44, '1998-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 21, 'Sacrifice (1)', 'Xena and Gabrielle must stop Gabrielle''s friend, Seraphin, from sacrificing herself to bring back a goddess, but they also have to contend with Ares and Callisto, who are helping Hope be reborn.', 44, '1998-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 3), 22, 'Sacrifice (2)', 'When Gabrielle''s evil daughter, Hope, takes the form of her mother and joins forces with Ares to create a race of superbeings, Xena and Gabrielle must stop her reign of terror.', 44, '1998-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 1, 'Adventures in the Sin Trade (1)', 'After Gabrielle sacrificed herself to stop Hope, a grief-stricken Xena must travel to the Amazon Land of the Dead to find Gabrielle, and Xena revisits her past with the shamoness Alti, along the way.', 44, '1998-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 2, 'Adventures in the Sin Trade (2)', 'At the Amazon Place of Rest, Xena must battle the evil shamoness Alti and free the spirits of the dead Amazons from her past, before she can continue on to find Gabrielle.', 44, '1998-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 3, 'A Family Affair', 'When Xena and Joxer travel to Potidaea, they find Hope posing as Gabrielle and they must stop her and her monstrous offspring from destroying the world, and along the way Xena recovers the real Gabrielle.', 44, '1998-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 4, 'In Sickness and In Hell', 'Xena and Gabrielle, plagued by a myriad of ailments, try to help Joxer defend a Scythian army, while trying not to kill one another.', 44, '1998-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 5, 'A Good Day', 'Teaming with Greek Soldiers, Xena plots against Caesar and Pompey, whose war between one another has spilled over from Rome to Greece, and Xena plans to send them both back to where they came from.', 44, '1998-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 6, 'A Tale of Two Muses', 'Xena and Gabrielle help their friend Tara, to change an oppressed town where dancing is outlawed, and they include Autolycus in their plans to cut footloose and fancy free.', 44, '1998-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 7, 'Locked Up and Tied Down', 'When Xena allows herself to be tried and convicted of the murder of an innocent woman, who she left to die in the past, Gabrielle struggles to uncover the truth and free Xena from Shark Island Prison.', 44, '1998-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 8, 'Crusader', 'Xena meets a woman who preaches ""the way of the light"", but her practices leave something to be desired, when Xena learns of Najara''s reform or die policy for prisoners.', 44, '1998-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 9, 'Past Imperfect', 'Xena and Gabrielle work to save a village that is being destroyed in exactly the same manner in which she destroyed another village in a battle with the Centaurs years before.', 44, '1999-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 10, 'The Key to the Kingdom', 'Joxer, Meg and Autolycus team up to steal the infamous ""key"" that''s prophecized to lead to the crown of Athena, the joke''s on Autolycus when he learns the key is really a baby and Meg wants to be his mother.', 44, '1999-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 11, 'Daughter of Pomira', 'Xena and Gabrielle set out to recover a young girl who was kidnapped six years ago by the Horde, but they don''t count on the fact that the child has been raised as one of the Horde and doesn''t want to leave the only family she knows.', 44, '1999-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 12, 'If the Shoe Fits...', 'While journeying to reunite little princess Alecia with her father and the stepmother she dislikes, Xena, Gabrielle, Joxer and Aphrodite take turns regaling the child with fairy tales with familiar faces.', 44, '1999-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 13, 'Paradise Found', 'In India, Xena and Gabrielle wake up in a seeming land of paradise where a mystical man named Aidan, teaches Gabrielle the art of meditation, but Xena discovers he''s just feeding off Gabrielle''s goodness and must let go of all the good in her, in order to save Gabrielle.', 44, '1999-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 14, 'Devi', 'While travelling in India, Xena and Gabrielle meet Eli, a magician, and Gabrielle suddenly acquires the power to heal and is deemed a Devi, a healing deity but Xena is suspicious of the power''s source.', 44, '1999-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 15, 'Between the Lines', 'An Indiana ritual sends Xena''s soul into the karmic future for an encounter with the reincarnation of the evil shamoness Alti.', 44, '1999-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 16, 'The Way', 'Xena seeks the help of the god Krishna, to rescue Gabrielle and Eli from the clutches of Indrajit, the King of the Demons.', 44, '1999-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 17, 'The Play''s the Thing', 'The Queen of Cons, Zera, convinces Gabrielle to base a play on her adventures with Xena, with the hidden motive of running off with the production''s investment money.', 44, '1999-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 18, 'The Convert', 'Najara returns claiming a newfound mantra for nonviolence, while Xena becomes suspicious of her new outlook. Meanwhile, Joxer wrestles with the guilt of his first kill, and stuggles with admitting his guilt to the son of the man he killed.', 44, '1999-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 19, 'Takes One to Know One', 'Family and friends gather for Gabrielle''s surprise birthday party only to become suspects in a murder investigation instead when a bounty hunter looking to take Xena in, is murdered. Now Discord, the newly appointed goddess of retribution, has given Xena until sunrise to find the killer or everyone she loves will be taken to the underworld.', 44, '1999-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 20, 'Endgame', 'Gabrielle becomes Queen of the Amazons after Ephiny dies at the hand of Brutus, and Xena must fave Caesar and Pompey and their armies while keeping an eye on a rebellious Amazon.', 44, '1999-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 21, 'The Ides of March', 'Callisto returns from Hell with a double mission: corrupt Xena and make Julius Caesar emperor, but plans change when Caesar''s allies turn on him and when Roman soldiers capture and crucify Xena and Gabrielle.', 44, '1999-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 4), 22, 'Déjà Vu All Over Again', 'A present-day woman believes she''s the reincarnation of Xena, the warrior princess, while her disbelieving boyfriend thinks she''s crazy, and seeks help from a past life expert, with some familiar faces along the way.', 44, '1999-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 1, 'Fallen Angel', 'While Joxer, Amarice and Eli try to recover Xena and Gabrielle''s bodies, a war over their souls is waged with Heaven''s angels and Hell''s demons, which includes Callisto in their ranks.', 44, '1999-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 2, 'Chakram', 'After Eli resurrects Xena and Gabrielle, Xena loses her memory of all the violence in her life, and in order to recover her self, she and her friends must join her broken chakram with it''s counterpart, but Ares wants them both and will stop at nothing to get them.', 44, '1999-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 3, 'Succession', 'Ares decides to pit Mavican, Xena, and Gabrielle in a fight to the death in an unkown arena. One catch, Xena and Gabrielle share one body and Mavican is determined to fill-out her destiny of the one who kills Xena.', 44, '1999-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 4, 'Animal Attraction', 'While getting a little rest and relaxation in Spamona, Gabrielle tries to train her new horse, Amarice makes a love connection with Joxer''s friend, Arman, Joxer pines for Gabrielle, and Xena helps an old frien with a warlord problem, while exhibiting signs of pregnancy.', 44, '1999-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 5, 'Them Bones, Them Bones', 'Xena and Gabrielle cross over to the spirit realm to stop Alti from draining Xena''s baby''s lifeforce, so she can enter the physical world in the child''s body.', 44, '1999-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 6, 'Purity', 'Xena, Gabrielle and Joxer journey to Chin, when Lao Mao''s daughter summons Xena to help protect her mother''s book of wisdom from falling into the hands of her evil sister.', 44, '1999-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 7, 'Back in the Bottle', 'After a vision Xena, Gabrielle, and Joxer return to Chin, where they are reunited with Kao Syn. Where they must defeat the warlord Khan, who has joined forces with the evil spirits of Pao Tsu and Ming Ten, aka The Green Dragon, and knows the recipe of the deadly black powder.', 44, '1999-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 8, 'Little Problems', 'Thanks to Aphrodite, Xena is trapped in the body of a little girl and must help the child deal with the grief over her mother''s death, while Gabrielle and Aphrodite separate the two before sunset as well as keep Xena''s body safe from the bad guys.', 44, '1999-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 9, 'Seeds of Faith', 'When Eli preaches of the death of the Olympian gods, Xena and Gabrielle attempt to protect him from Ares but to no avail, while guidance is dished out by the angel Callisto and the secret of Xena''s child''s conception is revealed.', 44, '2000-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 10, 'Lyre, Lyre, Hearts on Fire', 'Xena holds a battle of the bands contest in a quest for peace between Amazons and a lovesick-for-Gabrielle Draco, in the musical capital of Greec. Meanwhile Joxer runs into his other brother, the flamboyant Jace and Xena tries to evade her mother''s attempts at matchmaking.', 44, '2000-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 11, 'Punch Lines', 'Suffering from writers''s block, Gabrielle tells Aphrodite about her day in which a depressed god shrunk her and Argo and how she attempted to correct the situation before a very moody Xena catches on. Meanwhile, Xena tries to control her hormone-induced temper but to no avail.', 44, '2000-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 12, 'God Fearing Child', 'Xena and Gabrielle team up with Hercules, when Zeus declares that Xena''s unborn child must die so that the prophecy will not be fulfilled. Meanwhile, Xena decides to travel to the underworld to retrieve Hade''s helmet of invisiblity to allow her and her baby to hide, and runs into her son, Solan who has chosen to live in Tarturus.', 44, '2000-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 13, 'Eternal Bonds', 'After the birth of baby Eve, Xena and Gabrielle must protect the infant from the Olympian gods who want to destroy her, while Xena tries to rid herself of a doting Ares and Gabrielle tries to retrieve the antidote for the poison that is slowly killing Joxer.', 44, '2000-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 14, 'Amphipolis Under Siege', 'On a visit home to see her mother, Xena, Gabrielle and baby Eve are trapped in Amphipolis when Athena and her army surround the village and plan to kill Xena''s child.', 44, '2000-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 15, 'Married with Fishsticks', 'When Gabrielle hits her head and falls into the ocean, she gets amnesia and a merman tries to convince her that she''s his wife and mother to his fishy offspring.', 44, '2000-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 16, 'Lifeblood', 'Xena and Gabrielle travel to the Amazon village to make baby Eve an Amazon princess and find that they must stop a war instead.', 44, '2000-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 17, 'Kindred Spirits', 'At the Amazon village, Gabrielle is torn between staying as Queen of the Amazons, and sharing adventures with Xena and baby Eve.', 44, '2000-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 18, 'Antony & Cleopatra', 'When Cleopatra is murdered, Xena poses as the Egyptian queen in order to find out the identity of the killer, while romancing Marc Antony.', 44, '2000-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 19, 'Looking Death in the Eye', 'In the future, an old Joxer obtains a scroll that tells how Xena and Gabrielle tricked the Fates into setting in motion the twilight of the gods and how Gabrielle and Xena were presumed dead for 25 years and baby Eve went missing.', 44, '2000-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 20, 'Livia', 'Twenty-five years have passed when Xena and Gabrielle finally awake from their icy sleep, and they set out to find Xena''s daughter, Eve, only to discover the world is not the same and neither is Eve. She''s now known as Livia, the Bitch of Rome, a bloodthirsty warrior with Ares as her mentor and lover.', 44, '2000-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 21, 'Eve', 'Xena, Gabrielle, Joxer and Virgil try to track down Livia/Eve and have no trouble when they find ravaged villages. After finding her, Xena faces Livia/Eve in battle once again.', 44, '2000-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 5), 22, 'Motherhood', 'Xena faces the gods of Olympus in a battle to the death when she acquires some new powers. Meanwhile, Gabrielle and Eve, are fighting battles of their own.', 44, '2000-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 1, 'Coming Home', 'Ares needs Xena''s help to restore his godly powers, but he gets more than he bargained for when the Furies attempt to drive him crazy with illusions.', 44, '2000-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 2, 'The Haunting of Amphipolis', 'On her trip home to Amphipolis, Xena finds the town possessed and sinister powers from Hell awaiting her, Gabrielle and Eve.', 44, '2000-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 3, 'Heart of Darkness', 'Xena must devise a plan to avoid inheriting the kingdom of Hell, and it won''t be easy with her heart turning cold and an angel named Lucifer ambitiously trying to force her to descend to her throne.', 44, '2000-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 4, 'Who''s Gurkhan?', 'Gabrielle sets out on a rescue mission to North Africa with the gang in tow, when she discovers her neice has been kidnapped by an elusive warlord named Gurkhan.', 44, '2000-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 5, 'Legacy', 'Xena and Gabrielle try to help two warring African tribes unite against their Roman enemies and Gabrielle must live with herself when she accidently takes the life of an unarmed young man.', 44, '2000-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 6, 'The Abyss', 'When searching for Virgil, Xena and Gabrielle are confronted by cannibals and they must stay alive in order to rescue Virgil before he becomes their next meal.', 44, '2000-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 7, 'The Rheingold (1)', 'When Xena journeys to Norse to stop a vicious beast she created, Gabrielle soon follows and learns of Xena''s past as a valkeryie and the crimes she committed after she made the Rheingold into a powerful ring.', 44, '2000-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 8, 'The Ring (2)', 'Gabrielle, Brunnhilda and Beowulf find Xena alive after the Grindl''s attack. When they arrive to the mine where the Grindl is hidden, Xena reveals the monster was once the valkyrie Grinhilda, who put the Rheingold Ring on her finger as a desperate attempt to stop Xena''s reign of terror.', 44, '2000-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 9, 'Return of the Valkyrie (3)', 'Xena has amnesia and believes herself to be Hrothgar''s bride, Wealthea but she must regain her memory in order to save Gabrielle from eternal sleep.', 44, '2000-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 10, 'Old Ares Had a Farm', 'Xena disguises a mortal Ares as a farmer in the middle of nowhere in order to hide him from warlords seeking revenge.', 44, '2001-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 11, 'Dangerous Prey', 'Xena becomes the ultimate prey for a deranged hunter, Prince Morloch, bent on hunting down Amazons for sport.', 44, '2001-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 12, 'The God You Know', 'Michael, the Arch-Angel, orders Xena to hunt down the Roman emperor, Caligula, who has stolen Aphrodite''s godhood and kill him before he can do anymore harm.', 44, '2001-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 13, 'You Are There', 'A tabloid reporter tries to get the scoop on Xena and her motivation for her quest to obtain the legendary golden apples from Valhalla.', 44, '2001-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 14, 'Path of Vengeance', 'When Eve returns to make amends for her past, she is captured by the Amazons and sentenced to execution unless Xena and Gabrielle can save her.', 44, '2001-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 15, 'To Helicon and Back', 'Gabrielle leads the Amazons on a rescue mission to Helicon to save Queen Varia from the vengeful half-god son of Artemis, who''s bent on destroying every Amazon.', 44, '2001-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 16, 'Send in the Clones', 'In modern-day New York City, a mysterious woman and three fans of Xena use hair samples to create clones of Xena and Gabrielle, who face a familiar enemy from their past.', 44, '2001-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 17, 'Last of the Centaurs', 'Xena and Gabrielle become embroiled in a conflict between centaurs and Lord Belach, whose daughter has run off with one of the hoofed creatures. Xena has conflicted emotions, however, as Belach is the son of her past lover Borias and the centaur, Xenan, is the son of the deceased Ephiny.', 44, '2001-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 18, 'When Fates Collide', 'After escaping from Hades and capturing the Fates, Caesar changes the Threads of Fate in order to change his destiny.  He makes Xena his empress and rules the world by her side. Gabrielle is a talented playwright and Alti is the High Priestess of Rome, and she wants all the power for herself and will stop at nothing to get it.', 44, '2001-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 19, 'Many Happy Returns', 'While on their way to deliver Hermes'' helmet to Thebes, Xena and Gabrielle save a young virgin from being sacrificed by a group of religious zealots.', 44, '2001-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 20, 'Soul Possession', 'The discovery of an ancient scroll that indicates Xena married Ares leads to a highly charged press briefing attended by the modern-day reincarnations of Xena, Ares, Gabrielle and Joxer.', 44, '2001-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 21, 'A Friend in Need (1)', 'In Part 1 of a two-part series finale, Xena learns that an army led by a samurai ghost is threatening the Japanese city of Higuchi. She also discovers that because of her past actions with Borias, she is responsible for the warrior''s rise to power. Accompanied by Gabrielle, Xena sets out to save the city and make amends for her past.', 44, '2001-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0112230')) AND numero_temporada = 6), 22, 'A Friend in Need (2)', 'Conclusion of the series finale: Xena and Gabrielle face their greatest threat when they head into battle against the evil samurai ghost Yodoshi and his army of 20,000 elite warriors.', 44, '2001-06-18');
