INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 1, 'DeeDeemensional', 'In "Deedeemensional", Dee Dee time-travels to save Dexter from a monster. In "Magmanamus", Monkey goes up against a lava being that dislikes human-caused noise. In "Maternal Combat", when his mother falls, Dexter creates a robot mom to substitute for her.', 7, '1996-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 2, 'Dial M for Monkey: Magmanamus', 'Monkey must defend the city from a giant underground lava monster, Magmanamus, who cannot sleep because of the noise created by its residents.', 7, '1996-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 3, 'Maternal Combat', 'When his mother falls ill, Dexter creates a robot to do her chores. Dee Dee gets hold of its remote control and wreaks havoc, forcing Dexter to create a second robot to counter Dee Dee''s.', 7, '1996-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 4, 'Dexter Dodgeball', 'Dexter is forced to play dodgeball by his P. E. teacher. Constantly failing, Dexter builds a robotic exoskeleton to defend himself.', 7, '1996-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 5, 'Dial M for Monkey: Rasslor', 'Intergalactic wrestling champion Rasslor challenges Earth''s superheroes, including Monkey, with the planet''s fate at stake.', 7, '1996-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 6, 'Dexter''s Assistant', 'In need of an assistant to operate his latest invention, Dexter performs a brain transplant on Dee Dee to make her smart enough to fulfill the role. With her new brain, Dee Dee proves to be more intelligent than Dexter.', 7, '1996-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 7, 'Dexter''s Rival', 'Mandark Astronomanov, a new student at Dexter''s school, seems to be superior to Dexter academically. Mandark forces Dexter to shut down his lab so that Mandark''s lab can gain more power. However, with the help of Dee Dee, Dexter manages to destroy Mandark''s lab.', 7, '1996-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 8, 'Dial M for Monkey: Simion', 'Monkey encounters Simion, an intelligent anthropomorphic chimpanzee who seeks vengeance on humans for turning him into his current state.', 7, '1996-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 9, 'Old Man Dexter', 'Banned from watching a late-night movie due to his young age, Dexter uses his technology to artificially grow into adulthood, but Dee Dee tampers with his machine, causing Dexter to turn into an old man.', 7, '1996-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 10, 'Double Trouble', 'Dee Dee and her friends, Lee Lee and Mee Mee, enter Dexter''s lab and wreak havoc. Dexter clones himself to stop them, but the girls too make clones of themselves.', 7, '1996-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 11, 'Dial M for Monkey: Barbequor', 'Monkey''s birthday party is interrupted by Barbequor an intergalactic villain who plans to eat the planets, and his sidekick, the Silver Spooner.', 7, '1996-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 12, 'Changes', 'Rerun of "Dexter''s Laboratory", the first "What a Cartoon!" pilot.', 7, '1996-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 13, 'Jurassic Pooch', 'To clone a dinosaur with an incomplete DNA sequence, Dexter uses his dog''s genetic code to fill in the gaps.', 7, '1996-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 14, 'Dial M For Monkey: Orgon Grindor', 'While on a date with Agent Honeydew, Monkey gets hypnotized by the music of the Organ Grindor who commands him to rob Fort Knox.', 7, '1996-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 15, 'Dimwit Dexter', 'Due to overworking his brain, Dexter''s mind shuts down, making him act idiotic.', 7, '1996-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 16, 'Dee Dee''s Room', 'After Dee Dee steals his critical invention, Dexter ventures into her room to find it.', 7, '1996-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 17, 'Dial M For Monkey: Huntor', 'Monkey encounters an alien hunter named Huntor and must fight him to save Agent Honeydew and Commander Chief.', 7, '1996-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 18, 'The Big Sister', 'Rerun of the second "What a Cartoon!" pilot.', 7, '1996-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 19, 'Star Spangled Sidekicks', 'Dexter and Dee Dee enter tryouts to become Major Glory''s sidekick. When Dee Dee wins, Dexter realizes that fancy costumes are not the only criterion to become a superhero.', 7, '1996-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 20, 'The Justice Friends: TV Super Pals', 'With only one television in their apartment, Major Glory, Krunk, and Valhallen disagree on what to watch: Major Glory''s televised capture of the Disgruntled Postman, TV Puppet Pals, or the monster truck pull.', 7, '1996-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 21, 'Game Over', 'Dexter and Dee Dee''s father buys a video game for them to play, but the game sucks Dexter inside when he plugs in the cartridge, and it is up to Dee Dee to bring him out.', 7, '1996-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 22, 'Babysitter Blues', 'Dexter has a crush on his teenage babysitter Lisa. When he finds out that she has a boyfriend, he sabotages their relationship and accelerates his age by ten years in an attempt to win her heart.', 7, '1996-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 23, 'The Justice Friends: Valhallen''s Room', 'Valhallen loses his magic ax and starts turning into a nerd, forcing Major Glory and Krunk to enter his room to find it.', 7, '1996-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 24, 'Dream Machine', 'When Dexter''s nightmares become frequent and problematic, he invents a machine that allows him to have nice dreams, as long as Dee Dee can operate it properly while she is awake.', 7, '1996-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 25, 'Dollhouse Drama', 'Suspicious that Dee Dee has not entered his lab even once on a particular day, Dexter shrinks himself and enters her room to spy on her. He soon becomes an unwilling character in Dee Dee''s doll story, but he believes the story to be real.', 7, '1996-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 26, 'The Justice Friends: Krunk''s Date', 'While fighting Comrade Red and his gang, Krunk falls in love with his equivalent in their gang, She-Thing.', 7, '1996-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 27, 'The Big Cheese', 'Dexter''s new device allows him to study for the next day''s French test while sleeping. It malfunctions, causing a single phrase -omelette du fromage- to repeat throughout the night, causing Dexter to wake up the next morning speaking nothing else except "omelette du fromage".', 7, '1996-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 28, 'Way of the Dee Dee', 'Dee Dee teaches Dexter how to live life her way instead of being lonely and purely focused on science.', 7, '1996-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 29, 'The Justice Friends: Say Uncle Sam', 'Major Glory forces Krunk and Valhallen to tidy up their apartment for his Uncle Sam, who is coming over for a visit.', 7, '1996-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 30, 'Tribe Called Girl', 'To learn more about girls, Dexter camouflages himself and enters Dee Dee''s room, where she is having a sleepover with her friends Lee Lee and Mee Mee. He gets caught by the girls, who force him to take part in their activities.', 7, '1996-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 31, 'Spacecase', 'To prevent himself from being taken away by aliens for experimentation, Dexter tricks Dee Dee into going instead, but he regrets his decision after realizing how much he cares for her.', 7, '1996-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 32, 'The Justice Friends: Ratman', 'To fix their apartment''s plumbing, Krunk and Valhallen go to the basement, where they meet Ratman, a diminutive vigilante raised by rats (a parody of Batman).', 7, '1996-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 33, 'Dexter''s Debt', 'Dexter''s lab is threatened with repossession unless he can repay his debt to NASA. When Dee Dee wins the same amount in a lottery, he decides to steal her money out of desperation.', 7, '1996-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 34, 'The Justice Friends: Bee Where?', 'Major Glory, Krunk, and Valhallen try to rid their apartment of a bee.', 7, '1996-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 35, 'Mandarker', 'Following the destruction of his lab by Dexter and Dee Dee (in the episode Dexter''s Rival), Mandark turns to magic to beat Dexter at the science fair.', 7, '1996-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 36, 'Inflata Dee Dee', 'Dee Dee inflates Dexter''s hydro-plasmatic suit and constantly floats in the air, prompting Dexter to bring her down.', 7, '1997-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 37, 'The Justice Friends: Can''t Nap', 'After fellow Justice Friend White Tiger helps Valhallen stop a super-villain, the latter invites him to spend the night in his apartment, forgetting that Major Glory is allergic to cats.', 7, '1997-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 1), 38, 'Monstory', 'Not interested in hearing Dee Dee''s long-winded story, Dexter gives her a silencing formula to keep her quiet, but it instead turns her into a giant monster still bent on telling her story. When he realizes that nothing can make her quiet, he becomes a giant monster himself.', 7, '1997-01-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 1, 'Beard to be Feared', 'After a fright from Dee Dee, Dexter lays down in the beard growing machine and tries to grow a beard like his hero, Action Hank. Unfortunately, everyone thinks he''s a hero.', 7, '1997-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 2, 'Quackor the Fowl', 'Mandark doesn''t know that his pet duck is really Quackor the Fowl, Monkey''s rival. Quackor overhears Mandark talking in his sleep about destroying Dexter''s lab and tries to do it, unaware that Monkey is Dexter''s pet.', 7, '1997-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 3, 'Ant Pants', 'Dexter prevents Dee Dee from destroying some ants. In order to teach her about ants, Dexter and Dee enter Dexter''s ant farm. The ants think Dexter is a criminal and has him fight to the death with a stronger ant.', 7, '1997-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 4, 'Mom and Jerry', 'Dexter switches his brain with a mouse, and must avoid his mother when she decides to exterminate him. A Parody of Tom and Jerry.', 7, '1997-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 5, 'Chubby Cheese', 'At the Chubby Cheese pizza restaurant, Dexter wears a Chubby Cheese hat and tries to slow down the Whack The Weasel machine to win a stuffed Monkey doll before Dee Dee does.', 7, '1997-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 6, 'That Crazy Robot', 'One of Dexter''s robots becomes Dee Dee''s servant when she removes a wrench that froze him up, but the robot is willing to destroy anyone who is mean to her or scolds her, including Dexter.', 7, '1997-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 7, 'D & DD', 'When Dexter''s friends tire of the complicated traps he sets up as Dungeon Master (he has their character''s killed every time), they put Dee Dee in charge for a change of pace.', 11, '1997-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 8, 'Hamhocks and Armlocks', 'Dexter''s father gets challenged to an arm wrestling match against a local champion at a truck stop, when he causes the champion to lose for the first time, but refuses to do so even when he trashes the family car. He finally accepts the challenge when he slams the door in Mom''s face. Dee Dee knows he''ll get creamed, so Dexter builds him a robotic arm to help him win the match.', 11, '1997-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 9, 'Hunger Strikes', 'Dexter uses radiation therapy so he can like vegetables, it actually causes him to only eat vegetables, also, the therapy has consequences if Dexter goes too long without them. He turns into a Parody of The Incredible Hulk without vegetables.', 7, '1997-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 10, 'The Koos is Loose', 'Dee Dee''s imaginary friend comes to life and annoys Dexter. Dexter ends up wishing him away, then he realizes he made a terrible mistake.', 7, '1997-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 11, 'Morning Stretch', 'Dexter oversleeps and still has to finish his homework along with getting ready for school and eating breakfast, so he creates a helmet that expands thirty seconds into thirty minutes, but realizes that slowing down time is more detrimental than helpful. When he gets everything done, the helmet shuts off. But Dee Dee blocks his door causing him to miss the bus. When Dexter asks Dee Dee why, she replies "Snow Day, school''s canceled!". Dexter realizes he did all that rushing around for nothing!', 7, '1997-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 12, 'Dee Dee Locks and the Ness Monster', 'Dee Dee Locks and the Ness Monster—Dexter''s mother forces Dexter to read to Dee Dee when she''s sick, but she makes up her own story after being bored by Dexter''s story (which was actually a science article). The story is completely mixed up and makes no sense. Dexter ends up catching Dee Dee''s illness.', 7, '1997-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 13, 'Backfire', 'Dexter fuses Dee Dee with the family car by accident, causing mayhem. A Parody of Herbie the Love Bug.', 7, '1997-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 14, 'Book ''Em', 'Dexter accidentally takes a library book without checking it out, so he and Dee Dee try to put it back without being caught.', 7, '1997-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 15, 'Sister''s Got a Brand New Bag', 'Dee Dee''s new dance annoys Dexter to no end.', 7, '1997-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 16, 'Shoo, Shoe Gnomes', 'Dexter calls upon the "shoe gnomes" to repair his boots, but can''t rid himself of them afterwards. The only way to get rid of them, according to Dee Dee, is to kick them in the butt. Dexter gets rid of the last one with his boot, but it''s damaged again.', 7, '1997-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 17, 'Lab of The Lost', 'Dexter ends up in the "old part of the lab" where his earliest inventions, long since forgotten, are not too happy to see him. They are mad at him for saying they were his greatest inventions, then moved on to another great invention.', 7, '1997-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 18, 'Labels', 'Dexter and Dee Dee label everything in the house. When their parents get home, they mistake Dexter for Dee Dee (he had a Dee Dee label on his forehead), but he already blamed Dee Dee for the chaos.', 7, '1997-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 19, 'Game Show', 'Dexter and Dee Dee compete against each other on a game show. Where Dexter can''t seem to win.', 7, '1997-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115157')) AND numero_temporada = 2), 20, 'Fantastic Boyage', 'Dexter tries to inject himself into Dee Dee to find a cure to the common cold, but ends up inside his dog. He believes Dee Dee has been infected with a dog virus. He is then mistaken for the first human virus to infect a dog by the vet.', 7, '1997-08-27');
