INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')), 1, 'Season 1', 'On her 16th birthday, Sabrina Spellman discovers she’s half-witch, half-mortal. Living with her aunts Hilda and Zelda, and their talking cat Salem, she begins mastering her magical powers while navigating high school life and her budding romance with Harvey Kinkle.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 1), 1, 'Pilot', 'On her sixteenth birthday, Sabrina Spellman finds out that she is a witch. However, instead of helping her, it actually makes life more difficult, especially after she gets on the wrong side of head cheerleader, Libby.', 22, '1996-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 1), 2, 'Bundt Friday', 'Sabrina slips Libby some truth sprinkles to make her confess to spreading nasty lies, but her plan backfires when the goodies make Jenny reveal she''s sweet on Sabrina''s love interest, Harvey. Meanwhile, Hilda prepares for a date with Drell - despite his having stood her up over 1,000 times in the past.', 22, '1996-10-04');
