INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 7), 11, 'The Lyin'', the Witch and the Wardrobe', 'Sabrina gets a job for Morgan to provide clothes for a celebrity photo shoot, but in the end has to fire her.', 22, '2003-01-17');
