INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 7), 15, 'Cirque du Sabrina', 'After Sabrina''s room turns into a circus tent, she must walk up and down the tightrope until she finds a balance in life between boyfriend, friends and her job.', 22, '2003-02-14');
