INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 7), 17, 'Romance Looming', 'Sabrina makes the fates mad when she saves Morgan''s life and Aaron confesses his love to Sabrina.', 22, '2003-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 7), 18, 'Spellmanian Slip', 'When bickering breaks out at Sabrina''s dinner with her future in-laws she casts a harmony spell and everyone breaks out in song.', 22, '2003-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 7), 19, 'You Slay Me', 'After asking Cinderella for advice on her wedding, Sabrina literally turns into a monster about the preparations.', 22, '2003-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115341')) AND numero_temporada = 7), 20, 'A Fish Tale', 'When Aunt Irma finds out that Sabrina is marrying a mortal she turns Aaron into a fish. The episode ends with Sabrina finding Harvey''s note that says that he will always love her.', 22, '2003-04-17');
