INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 2, 'Harry Frankfurt', 'Tonight philosophy professor and author of <I>On Truth</I>, Harry Frankfurt.', 0, '2007-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 3, 'Gov. Mike Huckabee', 'Tonight former Arkansas Governor Mike Huckabee. Jon discusses the first 100 hours of the Democrats and there great start, namely Congress shutting down on the first day (to watch a football game which started at 8:30PM). Jon talks with Jon Oliver, senior comparative presidential historian about media pundits who compare Bush with Lincoln.', 0, '2007-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 4, 'Peter O''Toole', 'Tonight legendary actor and star of <I>Venus</I>, Peter O''Toole.Jon begins with a review of George Bush''s presidential address about his change of strategy in Iraq. He then discusses Bush''s speech with Major Rob Riggle, the show''s military analyst. Finally, Jon looks at the Democrats response and the media''s use of puns to describe Bush''s last chance to cure the Iraq War.', 0, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 5, 'Josh Bernstein', 'Tonight the host of <I>Digging for the Truth</I> and author of <I>Digging for the Truth: One Man''s Epic Adventure Exploring the World''s Greatest Archaeological Mysteries</I>, Josh Bernstein.Jon first looks at the Senate Foreign Relation Committee and the disapproval of Bush''s new Iraq plan as the Senator''s discuss the details with Condoleeza Rice. Finally, Senior Black Correspondent Larry Wilmore discusses Martin Luther King Jr. Day with Jon.', 0, '2007-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 6, 'Michael Oren', 'Tonight journalist and author of <I>Power, Faith and Fantasy: America in the Middle East 1776 to the Present</I>, Michael Oren.Jon begins by looking at Steve Jobs introduction of the IPhone and then on to Iraq and the White House''s public relations offensive to sell Bush''s new strategy. Jon discusses Bush''s plan further with John Oliver, Senior Policy Analyst. Finally, Jon delves deeper into criticism of the Bush plan with an in depth analysis of Rep. David Wu''s comments comparing Bush to Star Trek''s Klingons, with Senior Star Trek Analogy Analysts, Leonard Nimoy and George Takei.', 0, '2007-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 7, 'Jerry Rice', 'Tonight former pro-football player and author of <I>Go Long!: My Journey and Beyond the Game and the Fame</I>, Jerry Rice.Jon begins by looking at Castro and the several conflicting reports surrounding his health, including one report stating that Castro had to be implanted with an artificial anus. Jon then looks at Obama''s announcement stating that he is starting an exploratory committee in a segment called Countdown to Obamania. Jon then looks at the American Idol premiere with John Hodgman, Resident Expert. Finally, Rob Riggle looks at local politics with a man who changed his name to Andy Griffith in order to run in the election for local sheriff.', 0, '2007-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 8, 'Robin Wright Penn', 'Tonight actress and star of <I>Hounddog</I>, Robin Wright Penn.Jon first looks at the Doomsday Clock which was set five minutes ahead, now five minutes before midnight and world wide armageddon. Jon then looks at the start of the non-binding resolution extravaganza, where each Senator seemingly has his own resolution. Jon then looks at NBC''s Dateline segment where they capture would-be child predators on camera and confront them, and ABC''s Primetime Live response to that ratings grabber. Don Bakkedahl takes that story deeper by taking a look at exploitative television by seeing how people react to shocking behavior. Finally, Jon looks at Rick Sanchez, the reporter who volunteered to taser himself on camera, and all the would be reporters who follow in his painful, sometimes arousing footsteps in Taser Wars 2007.', 0, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 9, 'Gen. Rupert Smith', 'Tonight former British Army General Rupert Smith, author of <I>The Utility of Force: The Art of War in the Modern World</I>.Jon begins with a look at the President''s State of the Union Address and Bush''s strong use of the word strong. Jon discusses with Jason Jones, Senior Political Analyst, the piece of mind we Americans sacrifice when we watch the news about Iraq. Jon briefly looks at all the new nominees who dropped their hat into the presidential race of 2008. Finally, Jon looks at the online newspaper versus the paper kind, and how people are using the vows section of the N.Y. Times to tell their life story as well as living obituaries, where the dead person speaks his own obituary.', 0, '2007-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 10, 'Terry McAuliffe', 'Tonight the chairman of the Democratic National Committee, Terry McAuliffe.Jon starts off with a look at the Oscar nominations and how he wasn''t asked to host them this year. He then segues into Indecision 2008, with a brief look at the candidates and the media''s thirst for polls over who will win the primaries one year from now. Jon discusses with Senior Polling Expert, Samantha Bee, polling in general and how the numbers rise and fall over the course of a few hours. Finally, Louis Black looks at television show disclaimers and apologies in Back in Black.', 0, '2007-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 11, 'Scott McClellan', 'Tonight former White House press secretary Scott McClellan.Jon begins with a thorough review of the President''s State of the Union address. Rob Riggle and Samantha Bee then report on their overall impressions of the speech. Finally, Jon looks at the Democrats and medias response to Bush''s speech.', 0, '2007-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 12, 'Sen. Charles Schumer', 'Tonight New York Senator Charles Schumer.Jon begins with a look at Senator John Kerry''s long winded speech about how he is not running for President. Finally, Jon looks at Wolf Blitzer''s interview of Dick Cheney and his lack of commenting on anything, specifically how he refuses to answer any question about his lesbian daughter.', 0, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 13, 'Bill Gates', 'Tonight the founder of Microsoft, Bill Gates and his quick exit after the interview.Jon starts the show with a look at who has or has not said they will run for President. Indecision ''08 continues with Jon focusing on two of the Democratic candidates. First, Jon looks at Hillary Clinton and her joking about her husband''s infidelity. Finally, Jon looks at the media''s overreaction to Obama attending a muslim private school.', 0, '2007-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 14, 'Neil deGrasse Tyson', 'Tonight astrophysicist and author of <I>Death by Black Hole: And Other Cosmic Quandries</I>, Neil deGrasse Tyson.Jon begins with a look at the Scooter Libby trial with a summary as to how it all began. Furthermore, John Oliver, Senior White House Correspondent comments on the Libby trial in more detail. Finally, Jon looks at how the primaries are now being moved up to earlier and earlier dates. He discusses this with John Hodgman, Resident Expert.', 0, '2007-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 15, 'Sen. Joe Biden', 'Tonight Delaware Senator Joe Biden.Jon first looks at Bush''s comments on Vice President Dick Cheney. Jon then looks at Bush''s new Iraq strategy, or lack therof, and how anyone fpund disagreeing with Bush, in effect emboldens the terrorists. Jon talks with John Oliver, Senior White House Correspondent, about the intricacies of emboldening terrorists. Finally, Jon discusses with Larry Wilmore, Senior Black Historian, black history month''s purpose.', 0, '2007-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 16, 'Sienna Miller', 'Tonight actress and star of <I>Factory Girl</I>, Sienna Miller.Jon first looks at Mary Cheney, the Vice President''s lesbian daughter, who stated that the birth of her child should not be used for political maneuvering in response to Wolf Blitzer''s interview the day before. Jon delves deeper into the issue as to why Dick Cheney''s daughter is off limits with John Oliver, Senior Media Critic. Jon also talks with Chrissy Gephardt, lesbian daughter of former presidential candidate, Dick Gephardt. Finally, Jason Jones exposes the real Orange County in a two-part series.', 0, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 17, 'Walter Scheib', 'Tonight former White House chef and author of <I>White House Chef: Eleven Years, Two Presidents, One Kitchen</I>, Walter Scheib.Jon begins with a look at the Super Bowl and the ads. Jon moves on to the Bush administrations acceptance of the new global warming report. Dan Bakkedahl, Senior White House Correspondent, talks with Jon about this development. Finally, France shuts off the lights from famous buildings as a response to global warming, Jon discusses this with John Oliver, Senior Envirospondent.', 0, '2007-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 18, 'Mike Rowe', 'Tonight the host of <I>Dirty Jobs</I>, Mike Rowe.Jon begins with a look at evangelical minister Ted Haggard, who is now apparently completely heterosexual. Jon then looks at the non-binding resolution wars that continue in Congress. Also, Jon looks at the songs of the new Democratic presidential candidates. Finally, Jason Jones finishes his second part of a two part series on Laguna Beach.', 0, '2007-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 19, 'Ralph Nader', 'Tonight consumer advocate and author of <I>The Seventeen Traditions</I>, Ralph Nader.Jon begins with the bizarre story of the crazy diaper wearing astronaut Lisa Nowak out for revenge. He discusses this latest story with Rob Riggle, Senior Space Correspondent. Finally, Jon look at the media''s use of various kinds of news consultant and discusses this with Samantha Bee, Senior Continental Revenge Trek Analyst.', 0, '2007-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 20, 'John Mellencamp', 'Tonight, musician John Mellencamp.Jon first looks at the moral outrage over a Super Bowl snickers ad and a suicide prevention groups complaint over GM''s ad showing a robot killing itself after losing its job. Jon then looks at Paul Bremmer''s failure to account for $8 billion that went to Iraq for reconstruction. Finally, John Oliver investigates a man in Colorado who is suing a bar for sex discrimination because they have a ladies night.', 0, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 21, 'Jeffrey Rosen', 'Tonight law professor and legal editor for the <I>New Republic</I> and author of <I>The Supreme Court: The Personalities and Rivalries That Defined America</I>, Jeffrey Rosen.Jon looks at the media''s heavy coverage of Anna Nicole''s death with Rob Riggle, Senior Entertainment Correspondent & Jason Jones, Senior Media Analyst. Finally, Jon looks at Obama''s announcement that he is running for President and he discusses this with Senior Black Correspondent, Larry Wilmore.', 0, '2007-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 22, 'Christopher Horner', 'Tonight attorney and senior fellow at the Competitive Enterprise Institute and author of <I>The Politically Incorrect Guide to Global Warming (and Environmentalism)</I>, Christopher Horner.Jon first looks at the media''s coverage of Anna Nicole''s death fridge and a look inside CNN''s own break room fridge. Jon then looks at Douglas Feith, the man who disseminated intelligence to the President about Iraq. Finally, Dan Bakkedahl looks at the polar bear clubs reaction to global warming.', 0, '2007-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 23, 'Ishmael Beah', 'Tonight former child soldier in Sierra Leone''s civil war and author of <I>A Long Way Gone: Memoirs of a Boy Soldier</I>, Ishmael Beah.Jon begins the show with a look at the deal struck with North Korea to stop their nuclear weapons program and John Bolton''s disapproval of it. Jon then talks with John Hodgman about the nature of love. Finally, Jason Jones looks at partisan political dating sites in ''Must Love Dogma.', 0, '2007-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 24, 'Meredith Vieria', 'Tonight the co-host of <I>Today</I>, Meredith Vieria.Jon begins with a review of the House of Representatives debate and inaction as they try to pass their non-binding resolution. Jon then looks at Iran who, according to the U.S. government, is supplying weapons to insurgents in Iraq. Finally, Jon discusses this Iranian development with John Oliver, Senior Military Speculator.', 0, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 25, 'Craig Newmark', 'Tonight the founder of craigslist.com, Craig Newmark.Jon begins by looking at last nights Oscars with Senior Entertainalist, John Oliver. Finally, Samantha Bee gives us a glimpse at religion and fashion in Fashion Week in God.', 0, '2007-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 26, 'John Amaechi', 'Tonight former NBA star and author of <I>Man in the Middle</I>, John Amaechi.Jon begins with a look at Laura Bush''s opinion about the current state of Iraq. Jon then looks at the Clinton/Obama war in the media over what David Geffen said. Jon discusses this further with Jason Jones, Senior Hollywood Correspondent. Finally, Rob Riggle looks at rural America''s reaction to a Muslim mosque being built in Texas in Loathe Thy Neighbor.', 0, '2007-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 27, 'Jake Gyllenhaal', 'Tonight actor and star of <I>Zodiac</I>, Jake Gyllenhaal.Jon starts off with a story about a hepatitis exposure scare at a Sports Illustrated party for the latest swimsuit issue. Jon then talks about Vice President Cheney''s recent trips overseas with John Oliver, Senior Cheney Chaser. Finally, Lewis Black in Back in Black.', 0, '2007-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 28, 'Sam Sheridan', 'Tonight sports journalist and author of <I>A Fighter’s Heart: One Man’s Journey Through the World of Fighting</I>, Sam Sheridan.Jon starts off with a story about Al Sharpton, whose great grandfather it turns out, was once owned as a slave by the now deceased Senator Strom Thurmond''s relatives. Jon asks Al Sharpton his opinion about this new story. Finally, a look at the new documentary by James Cameron about Jesus'' tomb and conservatives outrage.', 0, '2007-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 29, 'Bob Woodruff', 'Tonight, journalist and author of In an Instant: A Family''s Journey of Love and Healing, Bob Woodruff. Jon first looks at and later discusses the conditions at Walter Reed Army Medical center with Senior Military Analyst, John Oliver. Finally, Jon looks at the Bush administrations record of deflecting blame, even now with the problems at Walter Reed.', 0, '2007-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 30, 'Dr. Richard Jadick', 'Tonight, military doctor and author of On Call In Hell: A Doctor''s Iraq War Story, Dr. Richard Jadick.Jon first looks at the Scooter Libby guilty verdict. He then talks about the Walter Reed hearings in Congress and Bush''s address to the veterans of the American Legion with Rob Riggle, Senior Military Analyst. Finally, Samantha Bee in a segment called Sam on Your Side. She interviews a CT atheist who is looking to sue a town because the local church bells annoy him.', 0, '2007-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 31, 'Wynton Marsalis', 'Tonight, jazz musician Wynton Marsalis promotes his new album From The Plantation To The Penitentiary.Jon begins with a brief history about the Scooter Libby trial. He discusses this further with Senior Legal Analyst, Samantha Bee. Jon ends the segment with a Robert Novak douchebag montage. Finally, Jon talks with John Hodgman about athletes and the effects of HGH, human growth hormone.', 0, '2007-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 32, 'Dr. Sharon Moalem', 'Tonight, Dr. Sharon Moalem, author of Survival of the Sickest: A Medical Maverick Discovers Why We Need Disease.Jon starts off with a report about journalists who are being killed in Russia for criticizing Putin. Kremlin Bureau Chief John Oliver talks with Jon about this new report. Indecision 2008 continues with a look at Clinton & Obama''s Southern accent impersonations during their speech''s in Selma, AL. Finally, Dan Bakkedahl, Senior Horologist, looks at the upcoming apocalypse that will be caused by daylight savings time being moved up 3 weeks.', 0, '2007-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 33, 'Senator Chris Dodd', 'Tonight on the show, 2008 presidential candidate Chris Dodd.Jon opens the show with the big announcement by Senator Chuck Hagel that he may or may not run for President. Jon then looks at the continuing President Bush tour of South America in a segment called "Bush: ¿Donde Esta?" Aasif Mandvi talks with Jon about Halliburton moving their corporate headquarters to Dubai in "The Long Kiss Dubai". Finally, Samantha Bee looks at the current celebrity trend of adopting foreign babies in "Totally Doing Starbusiness".', 0, '2007-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 34, 'John Waters', 'Tonight, cult film director John Waters talks about his new Court TV series, ''Til Death Do Us Part.Jon begins with Bush''s last day touring South America where he apparently helped box lettuce in Guatemala. Jon then looks at the Democrats complicated withdrawal plan out of Iraq in a segment called ''08 Simple Rules for Dating our Withdrawal. Jon then discusses Vice President Cheney''s clout and how it never seems to run out. Finally, Jon looks at the Democrats withdrawal from a Fox News sponsored debate because of something Roger Ailes, Fox News President said.', 0, '2007-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 35, 'Zbigniew Brzezinski', 'Tonight, political scientist and the former U.S. National Security Advisor to Jimmy Carter, Zbigniew Brzezinski, promoting his new book Second Chance: Three Presidents and the Crisis of American Superpower.Jon begins with a look at Senator Chris Dodd''s blog. Jon then looks into the Attorney General Alberto Gonzalez scandal, where 8 U.S. attorneys were fired for political reasons in a segment called "Nuthin'' But A.G. Thang". Jon then talks about the scandal with Aasif Mandvi, Senior Legal Correspondent, in a segment called "Seedy Gonzalez". Finally, a look at a curious phrase White House appointees use: "Serving at the pleasure of the President".', 0, '2007-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 36, 'Sandra Bullock', 'Tonight, actress Sandra Bullock promotes her new movie, Premonition.Jon begins with a final look at Bush''s tour of South America, which ended in Mexico. Jon then talks about Khalid Sheikh Mohamed''s confession about planning several terrorist attacks, including 9/11. Jon then talks with Jon Oliver, Senior Produce Analyst, about the Chiquita banana scandal in a segment called "Banana Drama". Chiquita apparently paid $1.7 million in protection money to a Columbian terrorist group. Finally, Jon looks at Iran''s outrage over the new movie 300 and how it unfairly disparages Persians.', 0, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 37, 'Stephen Prothero', 'Tonight, the chair of the religion department at Boston University and author of <I>Religious Literacy: What Every American Need to Know-And Doesn’t</I>, Stephen Prothero.Jon begins by marking the 4th anniversary of the Iraq War. Jon then looks at the compelling testimony of Valerie Plame in front of the House Committee on Oversight and Government Reform in a segment called "Blondie". Finally, Jason Jones looks at potential cures for homosexuality in a segment called "Diagnosis Mystery".', 0, '2007-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 38, 'John Bolton', 'Tonight, former U.S. Ambassador to the U.N. from August 2005 until December 2006, John Bolton.Jon begins with a look at the continuing Justice Department scandal. Jon then talks with Rob Riggle about a term Karl Rove used in an email differentiating between disloyal district attorneys and "loyal Bushies". Finally, all aboard John McCain''s Straight Talk Express, because its back and fortunate for us, won''t allow McCain to lie as Jon shows in a clip showing McCain misspeak.', 0, '2007-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 39, 'Chris Hansen', 'Tonight, Dateline NBC journalist Chris Hansen promotes his continuing segment on the show and his new book, To Catch a Predator.Jon begins the show with the constitutional showdown over whether Karl Rove will testify about the firing of the eight U.S. attorney''s. Jon then looks at Bush''s response to the scandal and the "reasonable proposal" he made to have Karl Rove testify, in private and not under oath. John Oliver, Senior Washington Correspondent talks about this proposal with Jon in a segment called "Eight Men Out". Finally, a recap of the John Bolton interview from last night''s episode and Bolton''s continuing assertion that Jon is wrong. Jon talks about a specific point he made about Abraham Lincoln in last night''s interview with Doris Kearns Goodwin (an expert who wrote a book on Lincoln) and how Bolton was in fact, the one who was wrong.', 0, '2007-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 40, 'Don Cheadle', 'Tonight, actor Don Cheadle promotes his new movie, Reign Over Me.Jon first talks about Al Gore testifying in front of Congress about global warming in a segment called "Welcome Back, Hotter". Jon then talks about the fired U.S. Attorney''s and Press Secretary Tony Snow trying to sell Bush''s offer that Karl Rove testify in private and not under oath in "Showdown at Justice". Finally, Jon talks with Demetri Martin about Viacom suing Google and YouTube over copyright infringment.', 0, '2007-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 41, 'Senator John Kerry', 'Tonight, Senator John Kerry promotes his new book, This Moment on Earth: Today''s New Environmentalists and Their Vision for the Future.', 0, '2007-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 42, 'Dennis Miller', 'Tonight, comedian Dennis Miller promotes his new radio show.', 0, '2007-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 43, 'Bill Richardson', 'Tonight, current Governor of New Mexico and 2008 presidential candidate who is also promoting his book, ''Between Worlds: The Making of an American Life'', Bill Richardson. Jon begins with a look at Bush''s repsonse to the Dems troop withdrawal bill in a segment called "Furious George". Jon then talks with John Hodgman about the President''s use of executive privilege. Finally, Larry Wilmore & John Oliver look at the n-word and whether it should be banned in a segment entitled "Wilmore & Oliver Investigates".', 0, '2007-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 44, 'Philip Zimbardo', 'Tonight, psychologist Philip Zimbardo promotes his new book, The Lucifer Effect: Understanding How Good People Turn Evil.', 0, '2007-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 45, 'Bill Bradley', NULL, 0, '2007-04-09');
