INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 47, 'Halle Berry', NULL, 0, '2007-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 48, 'Richard Preston', NULL, 0, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 49, 'Andrew Card', 'Tonight, former White House Chief of Staff for President George W. Bush, Andy Card. Jon begins the show with the fired U.S. attorney''s scandal. Over 5 million White House staffer e-mails have gone missing, including some containing information about the fired attorneys in a segment called "The Amazing Erase". The White House claims that the e-mails were mistakenly erased. To put the story in perspective, Jon calls Sen. Ted Stevens(R) from Alaska to help explain the complexity of the internet and email. Furthermore, Jon talks with Senior Technology Correspondent Jason Jones about how easily these e-mails could be accidentally erased.', 0, '2007-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 50, 'Sig Hansen', 'Tonight, Norwegian fisherman Sig Hansen from the show Deadliest Catch on the Discovery Channel. Jon begins the show with a brief talk about the big rainstorm in the Northeast. Jon then talks about Paul Wolfowitz who used his influence at the World Bank to get a promotion and raise for his girlfriend in a segment called "Loan Wolf". On a lighter note, Jon talks about Richard Gere who over the weekend kissed a Bollywood star during an AIDS awareness rally in India in a segment called "American Gigolo". This kiss led to massive protests in India since public displays of affection are frowned upon there. Senior Mumbai Bureau Chief Aasif Mandvi talks with Jon about the protests, which included burning effigies of Gere on the street. Finally, Rob Riggle goes to Largo, FL and talks with Steve Stanton who was fired from his job as a city manager because he is transgendered in a segment called "Suddenly Susan".', 0, '2007-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 51, 'Ali Allawi', 'Tonight, former Minister of Trade, Defense, & later Finance in the Interim Iraq Governing Council, Ali Allawi, who is also promoting his new book, The Occupation of Iraq: Winning the War, Losing the Peace. Jon begins tonight''s show with "Mess O''Potamia", where amid one of the bloodiest days in Iraq, 6 Shiite cabinet ministers resigned because Prime Minister al-Maliki will not set a timetable for U.S. troop withdrawal. Also, Jon looks at Bush''s new war czar position, which has been created to apparently cut through all the federal bureaucracy bogging down the Iraq War. Since the position has been rejected by 5 generals that have been asked to fill the spot, the White House is changing the name from "war czar" to "execution manager". Finally, Senior Financial Correspondent John Oliver talks with Jon about the contradictions plaguing the U.S. economy as the stock market hits an all time high, but the dollar has reduced in value by half as $1 now equals 2 British pounds.', 0, '2007-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 52, 'Jeremy Scahill', 'Tonight, journalist and author of Blackwater: The Rise of the World''s Most Powerful Mercenary Army, Jeremy Scahill. Jon begins the show by talking with Senior Legal Correspondent Aasif Mandvi about the Supreme Courts decision to affirm the partial birth abortion ban in a segment called "America Decides". Jon then talks about Attorney General Alberto Gonzalez who testified before the Senate about not recalling anything he may or may not have done. Finally, Jason Jones talks with Frosty Hardison, a man who got his daughter''s Seattle school board to stop a teacher from showing the movie An Inconvenient Truth in her class in a segment called "Apocalypse How?".', 0, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 53, 'Matt Cooper', 'Tonight, journalist for the Condé Nast Portfolio, Matt Cooper. Jon begins tonight show with a look at France''s runoff election for President between conservative Nicolas Sarkozy and socialist Segolene Royal. Jon then does a brief recap of the Alberto Gonbzalez testimony and talks with Senior Washington Correspondent John Oliver about Bush''s reaction to the testimony. Finally, Samantha Bee does a story about Earth Day in a segment called "Man v. Earth: The Wreckoning".', 0, '2007-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 54, 'Senator John McCain', 'Tonight, presidential candidate Senator John McCain. Jon begins the show with a look at the continuing battle in Washington D.C. over funding for the war and the use of timetables in a segment called "Mess O''Potomac". Finally, Jon talks with 1st term President Bush and 2nd term Bush using past clips of the President that seemingly contradict one another.', 0, '2007-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 55, 'Garry Shandling', 'Tonight, comedian Garry Shandling promotes his new DVD Not Just the Best of the Larry Sanders Show. Jon begins tonight''s show with a look at Baghdad and how the Bush administration is bridging the gap between Shiites and Sunnis by building a series of walls in Baghdad in a segment called "Extreme Makeover: Baghdad Edition". Jon then talks with Baghdad Bureau Chief Aasif Mandvi about the Baghdad walls in a segment called "Wall or Nothing". Finally, Lewis Black makes fun of several Earth Day television specials in "Back in Black".', 0, '2007-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 56, 'Richard Gere', 'Tonight, actor Richard Gere promotes his new movie The Hoax.', 0, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 57, 'Christopher Hitchens', 'Tonight, author and journalist Christopher Hitchens promotes his book God Is Not Great: How Religion Poisons Everything.', 0, '2007-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 58, 'Tobey Maguire', NULL, 0, '2007-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 59, 'Pierre Rehov', 'Tonight, director Pierre Rehov promotes his new documentary out on DVD, Suicide Killers. Jon begins the show with a good old fashioned Washington D.C. sex scandal. Deborah Jeane Palfrey a.k.a. Miz Julia, has submitted 46 pounds of telephone records from an escort service she ran for 13 years. Jon looks at the media frenzy to see which powerful D.C. men are on the list in a segment called "Beltway: Unbuckled". Senior Washington Correspondent Jason Jones talks with Jon about the how one can hire an escort legally and for nonsexual reasons, namely, by always laying down on your stomach while you get your "massage". Finally, Aasif Mandvi takes a look at both sides of the debate over Chief Illiniwek, the mascot for the University of Illinois at Urbana-Champaign who recently was retired because of protests saying the chief perpetuated rascist stereotypes in a segment called "Trail of Cheers".', 0, '2007-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 60, 'Ted Koppel', 'Tonight, journalist Ted Koppel. Politicians on television programs us common folks watch are prevalent this week as Jon begins the show by looking at President Bush and Laura Bush on American Idol & Hillary Clinton on The Insider. As the 4th anniversary of Bush''s mission accomplished on the aircraft carrier fiasco loomed large this week, the Democrats passed the Iraq funding bill only to have it vetoed by Bush in a continuing show segment, "Mess O'' Potamac". Finally, snitchin'' is not hip in the African-American community. Just ask Cam''ron, a rapper who made it clear that those who snitch to the police about crimes in the community, even a serial killer who lives next door, have no street cred and thus sales of their rap albums suffer. Senior Black Correspondent Larry Wilmore talks with Jon about the ethical implications of this stop snitchin'' phenomenon and the rappers code of "effix".', 0, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 61, 'Lee Gutkind', 'Tonight, author Lee Gutkind promotes his new book Almost Human: Making Robots Think. Jon begins the show with an in depth look at the Republican presidential candidate debate last week in a continuing show segment, "Clusterf@#k to the White House". Senior Correspondent Aasif Mandvi reporting live from the gates of hell talks with Jon about John McCain''s comment at the debate that he will hunt Osama bin Laden to the gates of hell in a segment called "Styx & Stones". Finally, John Oliver gives us a behind the scenes look at the Republican debate.', 0, '2007-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 62, 'George Tenet', 'Tonight, former director of the CIA and author of At the Center of the Storm: My Years at the CIA, George Tenet. Jon begins with Queen Elizabeth II visit to Washington D.C. where she hung out with President Bush at a series of events in a segment called "Elizabeth II: Visit from a Nice Old Lady". Finally, Jon talks with Royal Watcher John Oliver who wasn''t as excited as he should be about the Queen''s visit.', 0, '2007-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 63, 'Michael Beschloss', 'Tonight, presidential historian Michael Beschloss promotes his new book Presidential Courage: Brave Leaders and How They Changed America 1789-1989. Jon begins with a foiled terrorist plot to attack Fort Dix in New Jersey by terrorists who delivered pizza to the army base. "Mess O''Potamia" continues as Jon reports about a secret 24 member all Shiite panel dubbed "The Office" who exert their authority to overrule official government decisions in order to help Shiite militias. But fear not, because Dick Cheney is on the way to Iraq to pay a visit and offer his support as Jon''s theory on Cheney''s evilness is proved once again. The segment concludes with a report about a Palestinian kid''s show sporting a Mickey Mouse like character that encourages kids to hate Jews & America. And finally, Jon talks with Youth Spotting Expert Demetri Martin who discusses and give us tips on the use of video resumes to set one apart from those dreary paper resumes.', 0, '2007-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 64, 'Reza Aslan', 'Tonight, author of No god but God: The Origins, Evolution, and Future of Islam, Reza Aslan. The show begins with "Mess O'' Potomac" as Jon talks about the new Iraq spending bill that promises Bush half of the money now and the other half contingent on a July progress report. Of course, Bush plans another veto saying that any restrictions placed on the Iraq War by Congress is unacceptable and promotes defeatism. So when will the war end and what is Bush''s definition of victory or success in Iraq? Jon looks at a series of clips showing the flexibility of Bush''s definitions over the course of the Iraq War and also talks with Baghdad Bureau Chief Aasif Mandvi. Finally, Jon crosses over the Atlantic to Great Britain, where Tony Blair announced that he is planning on stepping down as Prime Minister on June 27th. Jon goes over some of the highlights of his speech in a segment called "The Blair Ditch Project".', 0, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 65, 'Jeremy Paxman', 'Tonight, BBC news reporter and author of the new book, On Royalty: A Very Polite Inquiry into Some Strangely Related Families, Jeremy Paxman. The show begins with a clip of Bush "The Decider" taking matters into his own hands and conducting an orchestra during the 400th anniversary of the founding of Jamestown. The fired U.S. attorney''s scandal continues as Alberto Gonzalez testifies about what he doesn''t remember before the House Judiciary Committee in a segment called "House A.G.". Senior Legal Correspondent Rob Riggle talks with Jon about how White House officials can never comment before, during, and after investigations into wrongdoing in a segment called "Speak No Evil". Finally, Samantha Bee in "This Week In God" talks about the history of Mormons as it relates to current presidential candidate Mitt Romney & about a hispanic man in Florida who founded a church based on the claim that he is the Antichrist.', 0, '2007-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 66, 'Tim Russert', 'Tonight, the host of Meet the Press and author of Wisdom of Our Fathers: Lessons and Letters from Daughters and Sons, Tim Russert. "Clusterf@#k to the White House" continues with Jon showing us four of the presidential candidates hitting the airwaves on Mother''s Day to talk about themselves. Jason Jones enlightens us about the importance of good skin and spin doctoring for politicians in a segment called "Nip/Talk". Finally, in a segment entitled "Banned Width", Jon talks about how reporters are now banned from filming insurgent bombings in Iraq & U.S. soldiers are banned from going on websites like YouTube & MySpace under the guise of protecting confidential military information.', 0, '2007-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 67, 'Don Rickles', NULL, 0, '2007-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 68, 'Brink Lindsey', 'Tonight, contributing editor to Reason Magazine & author of the new book The Age of Abundance: How Prosperity Transformed America''s Politics and Culture, Brink Lindsey.', 0, '2007-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 69, 'Zaki Chehab', 'Tonight, journalist and author of Inside Hamas: The Untold Story of the Militant Islamic Movement, Zaki Chehab. The show begins with some breaking news out of the Middle East that amazingly has nothing to do with the U.S. in a segment called "Middle East Trouble?" Military forces in Lebanon attacked a Palestinian refugee camp that harbored an al-Qaeda sect called Fatah al-Islam. Senior Beirut Correspondent Jason Jones stops by to give his report on the breaking news out of Lebanon. The end of an era is at hand as Bush and Blair part ways in a segment called "The End of the Affair". Jon provides us with a touching montage of Bush & Blair''s greatest moments together with Dirty Dancing''s "I''ve Had The Time Of My Life" playing in the background.', 0, '2007-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 70, 'Margaret Spellings', 'Tonight, the current Secretary of Education under President Bush, Margaret Spellings. Jon begins tonights show with the new Immigration Reform Bill being proposed in Congress in a segment called "Aliens v. Senators". Senior Immigration Correspondent Aasif Mandvi goes over some of the more complicated parts of the bill with Jon. Finally, Dan Bakkedahl experiences the joy in what it''s like to be a Mexican crossing the border illegally in a segment called "Mexodus".', 0, '2007-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 71, 'Lt. Col. Kevin Robbins', 'Tonight, the commander of the U.S. Air Force Air Demonstration Squadron “Thunderbirds”, Lt. Col. Kevin Robbins. Jon begins the show with "Mess O''Potomac" as the Democrats withdraw any timetables they had in their Iraq War funding bill, instead opting for a series of objectives that have to be met by the Iraqi''s. Who determines if they meet these objectives, why Bush of course. Jon nails Senator Harry Reid who agreed with the new bill, even though it''s substantially similar to Senator John Warner''s bill, which Reid previously said was weak and compared it to an old cup of tea sitting on a table for a few weeks. Jon then looks at Jimmy Carter''s comment that the Bush administration is the worst in history. Senior Presidential Historian John Oliver talks with Jon and delve into Carter''s comments and about past president''s that may have been worse.', 0, '2007-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 72, 'Al Gore', 'Tonight, former politician and current political activist on the environment and author of The Assault on Reason, Al Gore. Jon begins with a look at the media blitzkrieg on reports about high gas prices in a segment called "Gas Pains". Senior Petroleum Expert Rob Riggle dresses up in Mad Max gear to talk with Jon about this story. Finally, Jon reports about Monica Goodling who testified before the House Judiciary Committee about the fired U.S. attorney''s in a segment called "Illegally Blonde".', 0, '2007-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 73, 'Rep. Ron Paul', 'Tonight, Jon talks with Republican candidate for President, Ron Paul. Jon begins tonight''s show by describing his vacation last week to Greece where he met a man named Andrew on the plane, who incidentally is the same man who caused the tuberculosis scare around the world. "Clusterf@#k to the White House" continues as Jon reports on the recent Democrat debate. Jon looks at the multitude of raise your hand questions by Wolf Blitzer, the we all speak the same language of Hillary Clinton, the Edwards/Obama snaps, & Biden''s glory hole rhetoric. Finally, Jon calls Larry Flynt to discuss his recent Washington Post ad offering $1 million for proof that any government official had an extramarital affair.', 0, '2007-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 74, 'Paul Rudd', 'Tonight, actor Paul Rudd promotes his new movie Knocked Up. Jon begins the show tonight with the Scooter Libby jail sentence. Libby was sentenced to 30 months in jail and a $250,000 fine. Letters of praise and denouncement were sent to the judge to help him determine a sentence. Jon takes a look at some of the letters sent in praise of Libby from the likes of such distinguished individuals as Henry Kissinger & Donald Rumsfeld. Jon reports on Congressman William Jefferson who was charged on numerous counts of corruption in a segment called "Father of the Bribe". Jon not only highlights the numerous charges against Jefferson, but the fact that he kept $90,000 in his freezer. Jon then shows us a nice montage of Bush using the same language he denounced opponents of the immigration reform bill as using, namely, empty political rhetoric such as the word amnesty to induce fear in a segment called "Hasta la Visa".', 0, '2007-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 75, 'Michael Barone', 'Tonight, political analyst and author of Our First Revolution: The Remarkable British Upheaval That Inspired America''s Founding Fathers, Michael Barone. Jon begins with "Clusterf@#k to the White House" and a look at Tuesday''s Republican debate. Jon highlights some of the debate''s finer points from whether the candidates would invade Iraq given what they know now, would they allow openly gay members of the military, and general ''I believe in God'' comments and fear mongering. Also, Senior Campaign Theologian John Oliver talks with Jon about God''s use of lightning during the debate when Giuliani was speaking about abortion. Finally, Lewis Black in "Back in Black" reports on new technology. Lewis talks about Big Brother in google''s new Street View option in google map, a new device allowing movie theatre patrons to rat out rude behavior, and myspace.com reporting the identities of sex predators.', 0, '2007-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 76, 'Eddie Izzard', 'Tonight, comedian and star of the FX show The Riches and Ocean''s 13, Eddie Izzard. Jon begins the show by reporting on London''s new Olympic logo for the 2012 Olympics. Apparently, the animated logo was removed from the internet for fear that it would cause seizures. Jon then reports on the G-8 Summit in Germany, which sparked a number of protests in a segment called "8 Simple Rulers". Also, Jon reports on Bush''s clash with his buddy Vladimir Putin about what to do about the proposed missile shield over Eastern Europe. Finally, a rerun of Samantha Bee''s report on gays "corrupting" Nascar by using Fructis hair care products as a sponsor in a segment called "Gays of Thunder".', 0, '2007-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 77, 'David Steinberg', 'Tonight, comedian and author of The Book of David, David Steinberg. Jon begins with the weekends big story as Peter Pace, the Chairman of the Joint Chiefs of Staff, was ousted from his position. As CNN attempted to cover this major news story, they were interrupted by the biggest news story of them all, Paris Hilton entering a car going to jail. Jon shows us that as reluctant as CNN was in covering this story, they did it all day anyway. Next, Jon covers Bush''s trip to Europe where Bush was treated like a rock star in Albania in a segment called "Albaniacs". Jon calls Dennis Miller for some help in creating a Bush/Albania joke. Bush also met with the Pope for the first time and Senior Papist Jason Jones talks with Jon about Bush''s visit. Finally, Resident Expert John Hodgman talks with Jon about why mixed martial arts is so popular.', 0, '2007-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 78, 'Bob Shrum', 'Tonight, political consultant and author of No Excuses: Concessions of a Serial Campaigner, Bob Shrum. Jon begins tonight with the Senate''s debate over whether they should even vote on the immigration bill in a segment called "Kill Bill". Jon then reports on Alberto Gonzales'' no confidence vote in the Senate, again, to see if they should vote on it at all, in a segment called "Kill Bill Volume 2". Finally, Samantha Bee reports on whether the U.S.', 0, '2007-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 79, 'Allan Brandt', 'Tonight, the author of The Cigarette Century: The Rise, Fall, and Deadly Persistence of the Product That Defined America, Allan Brandt. "Mess O''Potamia" continues as Jon reports on the second bombing of a holy Shi''ite mosque in Samara by insurgents. Jon reports on Bush''s war czar Douglas Lute who says that progress in the war is uneven. Jon also talks about how the military is now fighting alongside the very same insurgents they were fighting against, which brings to mind that old adage, the enemy of my enemy is my friend. The segment ends with Senior Iraq Correspondent Aasif Mandvi talking with Jon about these new developments in Iraq. Finally, Senior Black Correspondent Larry Wilmore didn''t have much to say about any African-American related news, so after putting on a Detroit Red Wings cap he became a Senior Mexican Correspondent and talked with Jon about immigration reform.', 0, '2007-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 80, 'Angelina Jolie', 'Tonight, actress Angelina Jolie promotes her new movie A Mighty Heart. Jon begins the show tonight by showing us the duplicity of White House Press Secretary Tony Snow. Two months ago, Snow said the 8 fired U.S. attorneys were fired for performance reasons. Yesterday, Snow said he never said that. "Clusterf@#k to the White House" continues with Jon reporting on Giuliani''s 12 easily mockable commitments, Romney''s flip floppery on abortion, & McCain''s drunken bout with a burger. Jon then highlights the candidates use of the internet in their campaigns such as: buying Rudy Giuliani gear, dinner with Barack, Hillary Clinton''s theme song videos, & Gravel''s creepy "Rock" video. Finally, Jon reports on a bit of controversy over at the Weather Channel who''s chief climatologist said that no meteorologist should get a seal of approval by the American Meteorological Society if they do not speak about global warming.', 0, '2007-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 81, 'Steve Carell', 'Tonight, actor and comedian Steve Carell promotes his new movie Evan Almighty. With so much going on in the Middle East, Jon begins the show and leaves it up to chance by spinning the spinner to see which part of the Middle East he will cover. The winner, the Gaza Strip. Another good old fashioned civil war is in the making as Jon reports on the infighting between Fatah and Hamas in a segment called "Crisis in Gaza: Warportunity in the Middle East". Senior Gaza Correspondent Aasif Mandvi talks with Jon about this recent development. Finally, Senior Movie Reviewer Rob Riggle reviews Evan Almighty in a segment called "Shits & Riggles". He said the movie was really bad, mainly due to the fact that that he is jealous of Steve Carell''s booming career.', 0, '2007-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 82, 'Brian Williams', 'Tonight, journalist and anchor of NBC''s Nightly News, Brian Williams.', 0, '2007-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 83, 'Fareed Zakaria', 'Tonight, journalist Fareed Zakaria.', 0, '2007-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 84, 'Greg Bear', 'Tonight, author Greg Bear promotes his new novel Quantico.', 0, '2007-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 85, 'Steve Vogel', 'Tonight, author of The Pentagon: A History, Steve Vogel. Jon begins tonight with a report on Dick Cheney in a segment called "Dick Move". Cheney refuses to comply with the Information Security Oversight Office, a unit of the National Archives that monitors the Executive Branch''s handling of classified information. As Jon reports, Cheney sought to abolish this oversight unit with a shotgun, but when that didn''t work, Cheney argued that he is not part of the Executive Branch of government and therefore not subject to an executive order asking him to relinquish information. Senior White House Correspondent John Oliver talked with Jon about how Cheney is his own separate branch of government. Finally, Jason Jones reports on a man who gave his Purple Heart to President Bush because of the emotional pains and criticism Bush is experiencing in a segment called "Heart Attack".', 0, '2007-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 86, 'Bruce Willis', 'Tonight, actor Bruce Willis promotes his new movie Live Free or Die Hard. Jon begins tonight''s show with something you might not know about our illustrious Vice President in a segment called "You Don''t Know Dick". Dick Cheney apparently has a man-sized safe in his office that he uses to store his ''workaday business''. Next, Jon reports on four recent Supreme Court decisions in a segment called "Decisions ''07". Jon creates a spinner out of the swing vote judge on the court, Anthony Kennedy. Unfortunately, Kennedy sided with the conservative side of the court in every 5-4 decision. Senior Political Analyst Samantha Bee talks with Jon about the make-up of the Supreme Court and the fact that Cheney is a Supreme Court judge too. Finally, "Trendspotting with Demetri Martin". Youth correspondent Demetri Martin talks about credit cards and how they they target college campuses. Demetri finds this to be a good thing as going deeper into debt is alright since were all gonna die someday anyway.', 0, '2007-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 87, 'Michael Moore', 'Tonight, director Michael Moore promotes his new documentary, Sicko. Jon begins the show with another installment of "You Don''t Know Dick". Tonight''s little ''Dick nugget'' is the fact that the Vice President''s residence at the U.S. Naval Observatory is blocked out of Google Earth and pixelated. This is due to the fact that whatever Cheney touches, pixelates instantly. Next, "Clusterf@#k to the White House". Jon reports on Giuliani''s visit to Pat Robertson''s Regent University and one of Giuliani''s aid indicted on cocaine charges. Jon also reports on Former EPA Administrator Christie Todd Whitman who testified in front of a House subcommittee defending why she allowed 9/11 rescue workers to work in unsafe breathing conditions, proclaiming at the time that the air was safe to breathe. Finally, Lewis Black in "Back in Black". Lewis talks about how right-wingers are trying to make the internet more conservative.', 0, '2007-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 88, 'Claire Danes', 'Tonight, actress Claire Danes promotes her new movie Evening. Jon begins again with tonight''s "You Don''t Know Dick" as we learn that Dick Cheney invented his own top secret fication stamp that he stamps documents with. In other Cheney news, Cheney once told Senator Patrick Leahy to go f*ck himself. Well today, Leahy got his revenge and sent a subpoena to the V.P. to obtain info on the administrations wiretap program. Next, Jon reports on the immigration bill that was resurrected only to be killed once again in a segment called "Mexican Standoff". Resident Expert John Hodgman reports on the debate over this bill, including footage of some media pundits who claim illegal aliens bring in disease and criminals into the U.S. Finally, the iPhone is coming out this Friday and Senior Technology Correspondent Rob Riggle will do anything to get his hands on one, including kicking over baby strollers.', 0, '2007-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 89, 'Josh Rushing', 'Tonight, author of Mission Al Jazeera: Build a Bridge, Seek the Truth, Change the World, U.S. Marine Captain Josh Rushing, a former press officer for U.S. Central Command (CENTCOM) during the 2003 Invasion of Iraq. Jon returns after two weeks off and begins by reporting on the Scooter Libby commutation. Next, Jon reports on the ''progress'' made in Iraq the last two weeks in "Mess O''Potomac". As the Iraqi Parliament is taking off the whole month of August because of the sweltering heat in Baghdad, Jon reports on the Iraqi report card released by the Bush administration last week. Jon also shows us the political contortions used by the Bush administration to sell this progress. Senior Military Affairs Correspondent Rob Riggle talks with Jon about these latest developments. Finally, John Oliver files a report on Sen. James Inhofe''s proposal to make English the official language of the U.S. in a segment called "Language Burier".', 0, '2007-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 90, 'Christopher Walken', 'Tonight, actor Christopher Walken promotes his new movie Hairspray. Jon begins tonight reporting on Louisiana Senator David Vitter, who recently was found to be on the D.C. madam''s phone list. So you think the Bush administration can''t sink any lower with all the scandals surrounding them right now, well Jon has a surprise for us in a segment called "You Have No Idea!" Former Bush administration Surgeon General Dr. Richard Carmona was not allowed to speak at the Special Olympics because the Kennedy''s support the Olympics. Also, Dr. Carmona had to mention Bush in a positive light at his speaking engagements, a minimum of 3 times. His homophobic replacement Dr. John Holsinger was a worthy replacement, as Jon notes from Dr. Holsinger''s reports writing in graphic detail about a scientific basis as to why homosexuality is abnormal. Finally, Jon reports on the Catholic church sex abuse scandal in a segment called "Hot & Fathered".', 0, '2007-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 91, 'Matt Groening', 'Tonight, the creator of The Simpsons, who is also promoting the upcoming Simpsons Movie, Matt Groening. Jon begins the show tonight commenting on the Atlanta Falcons quarterback arrested for dogfighting. Jon then reports on the Senate all-nighter as Dems try to tire Republicans out with debate over the Iraq War in a segment called "C-Span After Dark". As Jon notes, the all-night session had a simple message, ''Let Us Vote''. Dems want to vote on an amendment that would bring the troops home by next April while the Republicans are using a filibuster to block them from even voting. The final tally, 52-47, short of the 60 votes needed. Political Theatre Critic John Oliver highlights some of the more dramatic aspects of the Senate debates. Washington Bureau Chief Aasif Mandvi talks with Jon about the sacrifice Senators made in staying up all night.', 0, '2007-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 92, 'Adam Sandler', 'Tonight, Adam Sandler promotes his new movie I Now Pronounce You Chuck and Larry. Jon begins by going to Senior Literary Correspondent John Oliver who''s at a local NYC bookstore with a report on the upcoming final Harry Potter book in a segment called "Harry Potter and the Endless Build Up". Jon then reports on the current state of Al Qaeda in a segment called "Return of the Jihad". Bush''s rhetoric over the years that the terrorist group has weakened is contradictory to a recent National Intelligence Estimate stating that Al Qaeda is stronger than ever. The Bush administration insists that they were right to invade Iraq because it has weakened the terrorists, yet we need to continue to stay in Iraq because of how strong the terrorists are there. Jon talks with Senior Political Correspondent Aasif Mandvi about this mind boggling contradiction.', 0, '2007-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 93, 'Neil deGrasse Tyson', 'Tonight, astrophysicist and the host of the new PBS show NOVA ScienceNOW, Neil deGrasse Tyson. Jon begins tonight reporting on the short lived presidency of Dick Cheney last Saturday in a segment called "The Cheney Presidency Remembered". While Bush was undergoing a colonoscopy and had to be under anasthesia, Dick Cheney was President for 2 hours. Jon gives a blow by blow account of this event, taking us on a tour of Bush''s colon and Cheney''s short lived attempt to start another war. Senior Presidential Historian Samantha Kearns Bee talks about the history of this temporary transfer of power in her new book on the Cheney presidency called "Classified, Assified, or Grassified: Nobody Presides for Free, The Cheney Presidency". Jon then reports on the ambassador to Iraq, Ryan Crocker, who talked with the Senate Foreign Relations Committee via a 60" plasma television from Iraq in a continuing show segment called "Mess O'' Potomac".', 0, '2007-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 94, 'Robert Pallitto', 'Tonight, political scientist and author of Presidential Secrecy and the Law, Robert Pallitto. Jon devotes the entire episode to the CNN YouTube debate last night in a segment called "Indecision v.2.008". Senior Political Reporter Jason Jones talks about his concern that everyday people asking candidates questions threatens real life reporters. Finally, John Oliver takes over Demitri Martin''s "Trendspotting" and asks the question whether the YouTube debate has youthanized politics.', 0, '2007-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 95, 'Rob Gifford', 'Tonight, a correspondent on National Public Radio and author of China Road: A Journey into the Future of a Rising Power, Rob Gifford. Jon begins tonight reporting on the House Judiciary Committee citing Josh Bolten and Harriet Miers with contempt of Congress for refusing to testify under oath about the Alberto Gonzalez firings. Who enforces this contempt of Congress charge, why Alberto Gonzalez of course. Jon continues by looking at Alberto''s testimony yesterday before the Senate Judiciary Committee in a segment called "Hearing Problems". Alberto''s ''I don''t recalls'' have transformed into flat out refusals to answer any questions. Senior White House Correspondent Rob Riggle discusses the situation with Jon. Finally, Lewis Black in "Back in Black".', 0, '2007-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 96, 'Robert Dallek', 'Tonight, presidential historian and author of Nixon and Kissinger: Partners in Power, Robert Dallek. Jon begins tonight''s show reporting on a story from New Zealand in a segment called "Kiwi the People". The democratically elected government of New Zealand banned the use of any footage from their Parliament for the purpose of satire, ridicule, or denigration. Jon comes to the rescue, taking some footage of their Parliament and spices it up with some political satire and fart jokes. Jon also reports on the suspensions of cyclists in the Tour de France for suspected drug use in a segment called "The Audacity of Dope". Then, Senior Flood Correspondent John Oliver reports from the top of London''s Big Ben due to the massive flooding of Great Britain in a segment called "London Flooding". Finally, Jason Jones reports on a lazy Las Vegas man who rents a scooter used for disabled people to move around the city in a segment called "High Rollers".', 0, '2007-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 97, 'Alastair Campbell', 'Tonight, former press secretary to Tony Blair as well as the author of The Blair Years: The Alastair Campbell Diaries, Alastair Campbell. Jon begins tonight with some sports news as Iraq''s soccer team defeats Saudi Arabia in the Asian Cup in a segment called "Achieving Our Goooal". Senior "Football" Correspondent John Oliver talked about the celebrations in the streets of Iraq resulting in only seven deaths for the day, a record low for Iraq. Jon then talks about Sen. Patrick Leahy who issued a subpoena for Karl Rove to testify about the fired U.S. attorney''s scandal in a segment called "The Sworn Supremacy". Also, Senior White House Correspondent Aasif Mandvi talks about the use of contempt by the Bush administration. Finally, Jon reports on Britain''s new prime minister Gordon Brown who had a sleepover with Bush at Camp David in a segment called "Foxy Brown". As Jon notes, Bush has a new British lapdog.', 0, '2007-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 98, 'Lewis Gordon Pugh', 'Tonight, swimmer & environmentalist Lewis Gordon Pugh. Jon begins tonight reporting on an old Daily Show favorite, Senator Ted Stevens in a segment called "Buy-Cameral Legislature". The FBI & IRS raided Senator Stevens Alaskan home due to allegations that he took oil company bribes in return for lucrative state contracts. As Jon reports, Stevens is being investigated due to his relationship with Bill Allen, an oil company contractor who was convicted this year of bribing state lawmakers. Stevens'' home renovation more than doubled the size of his home & was overseen by Allen who''s company has made millions in federal contracts. Senior Legislative Correspondent Jason Jones discusses some recent stories of political corruption. Jon then reports on the media''s focus on the amount of cleavage shown and clothing worn by the presidential candidates in a segment called "Indecision ''08".', 0, '2007-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 99, 'Jed Babbin', 'Tonight, former deputy undersecretary of defense during the first Bush administration and author of In The Words of Our Enemies, Jed Babbin. Jon begins tonight reporting on a "giant squid having sex with bigfoot" moment as both Donald Rumsfeld and Dick Cheney were on television yesterday answering questions. Jon first reports on Rumsfeld who was called before the Senate to answer questions about the friendly fire death/coverup of Pat Tillman in a segment called "The Rummy Returns". As Jon notes, even though Rumsfeld has been out of the game for awhile, he jumps right back in not recalling anything. Next, Jon reports on Dick Cheney who was interviewed by CNN''s Larry King in a segment called "I Now Pronounce You Dick & Larry". Jon highlights the better parts of the interview, such as Cheney''s lack of regret & disregard of polls.', 0, '2007-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 100, 'Matt Damon', 'Tonight, actor and star of the new film The Bourne Ultimatum, Matt Damon. Jon begins tonight with another Dick Cheney fun fact in a segment called "You Don''t Know Dick". When Dick was secretary of defense for the first President Bush, he met with King Hassan of Morocco. As the meeting started, the king put a small silver box containing a fragment of the Koran in his translator''s hand and swore him to secrecy on pain of death, whereupon Cheney said, "Damn, I need one of those”. Next, Jon reports on how the presidential candidates use food in there internet clips in a segment called "Indecision v. 2.008: Food Edition". Jon shows us various clips: the Clintons eating at a Dairy Queen, dinner with Barack contest winners converse, Edwards eats at Wendy''s for his 30th anniversary, and Giuliani apparently doesn''t eat food, just terrorists. Finally, "Clusterf@#k to the White House" continues as Clinton v.', 0, '2007-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 101, 'Andy Samberg', 'Tonight, comedian Andy Samberg from Saturday Night Live and the star of the new movie Hot Rod. Jon begins tonight reporting on Florida Representative Bob Allen who was caught offering money to an undercover police officer for oral sex in a segment called "Clusterf@#k to the White House: Drop and Give Me $20". As Jon notes, Bob Allen authored a bill outlawing the very same lewd acts in public he was caught of and is also the state co-chair of John McCain''s campaign. Mr. Allen has a simple explanation for this incident, his fear of black people. Senior Political Correspondent John Oliver talks with Jon about other possible defenses Allen could have used instead of being racist. Clusterf@#k continues as Jon reports on the Democratic meeting in Chicago to debate amongst online bloggers in a segment called "Yearly Kos Convention". The highlight of the event was Hillary Clinton, who says she accepts money from lobbyists because they''re real people, but is not influenced by them.', 0, '2007-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 102, 'Sen. Joe Biden', 'Tonight, presidential candidate and author of Promises to Keep: On Life and Politics, Senator Joe Biden. Jon begins tonight reporting on Barry Bonds hitting 756 homeruns, breaking Hank Aaron''s record. Senior Correspondent Rob Riggle talks to Jon about where he was during this historic event. Jon then reports on the missing 200,000 weapons given to Iraqi security forces in a segment called "Going, Going, Gun". General Petraeus explains this mishap by saying it was a clerical error. As Jon notes, this isn''t the first time something has gone missing in Iraq. The list includes such things as 380 tons of explosives, 12 billion U.S. taxpayer dollars, & 300,000 barrels a day for four years of Iraqi crude oil. Finally, Buck Henry stopped by to talk about Rupert Murdoch who purchased Dow Jones for $5 billion, which is also the company that owns the Wall Street Journal in a segment called "The Henry Stops Here".', 0, '2007-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 103, 'Tal Ben-Shahar', 'Tonight, psychologist and author of Happier: Learn the Secrets to Daily Joy and Lasting Fulfillment, Tal Ben-Shahar. Jon begins tonight reporting on the recent FOX News interview of President Bush with Neil Cavuto in a segment called "President Bush: In His Own Words". Jon pokes fun at all the nonsensical ways Bush tries to get his point across and his attempt to explain to us, ''in other words'', how he thinks. Finally, Jon reports on Mitt Romney''s five sons who have decided to forego military service for a more nobler cause, getting their dad elected in a segment called "Mess O'' Poromnia". Senior Campaign Embedder Aasif Mandvi reports from Iowa about the five brothers struggle.', 0, '2007-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 104, 'Bill Kristol', 'Tonight, editor of The Weekly Standard, Bill Kristol. Jon begins tonight with a curious tingling sensation running down the back of his spine. Karl Rove resigned from the Bush administation in a segment called "The Departed". Senior White House Correspondent John Oliver talks with Jon about this new story. Finally, Jon talks about the frequent occurrence of memory loss in the Bush administration. Is it some sort of contagious virus? To discover the true cause of this vexing problem, Jon talks with Dr. Mony J. de Leon, Professor of Psychiatry and Director of the Center for Brain Health at NYU.', 0, '2007-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 105, 'Denis Leary', 'Tonight, star of the show Rescue Me, Denis Leary. Wolfowitz, Rumsfeld, and now Rove gone, Jon begins tonight reporting on the new blood being injected into the Bush administration in a segment called "Rice & Ripken: Together at... Why!?" Condoleeza Rice announced that Cal Ripken Jr. will be a U.S. public diplomacy envoy, who''s first mission is to go to China. Jon then reports on the recent Democratic candidates forum on the channel Logo, a channel geared towards homosexuals in a segment called "Clusterf@#k to the White House: Divas Live". Melissa Etheridge was one of the participants questioning the Democrats, all the while, constantly talking about herself. Jon then shows various clips of the candidates trying to support the gay community, while at the same time trying to show the rest of the country that they don''t support them, otherwise known as gay marriage golf.', 0, '2007-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 106, 'Stephen F. Hayes', 'Tonight, author of Cheney: The Untold Story of America''s Most Powerful and Controversial Vice President, Stephen F. Hayes. Jon first reports on the recent visit of Nicolas Sarkozy with President Bush in Maine. Senior Western White House Correspondent Samantha Bee reports from Crawford, TX with some record breaking news. Bush has taken 423 vacation days and is on the verge of breaking Ronald Reagans 436. Next, Larry Wilmore asks the question, "Is America Ready For A Black President?" Larry looks at Obama and whether he''s black enough to be considered black and also uses the Negrometer to determine how black a president America is ready for. Finally, Jon shows us a 1994 video of Dick Cheney explaining why it was good thing we didn''t invade Baghdad during the first Iraq War in a segment called "Even Dick Don''t Know Dick".', 0, '2007-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 107, 'Sen. John McCain', 'Tonight, Republican presidential candidate Sen. John McCain promotes his new book, Hard Call: Great Decisions and the Extraordinary People Who Made Them. Jon first reports on the China toy recall crisis in a segment called "Great Recall of China". Senior Plaything Analyst John Oliver reports from his play room on this breaking story. And finally "Cluster@#k to the White House" continues with Jon reporting on Hillary Clinton who refuses to share her personal papers from when she was in the White House with Bill. Also, Jon shows various clips of presidential candidates going to hospitals; Clinton steps in the shoes of a nurse, Edwards shaves an old man, & Obama cleans a hospital room.', 0, '2007-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 108, 'Nikolas Kozloff', 'Tonight, author of Hugo Chavez: Oil, Politics, and the Challenge to the U.S., Nikolas Kozloff. Jon begins the show tonight going live from Baghdad to the show''s two Senior Baghdad Correspondent''s, Rob Riggle & Aasif Mandvi in a segment called "Operation Silent Thunder". The two correspondent''s compete to prove who really is in Iraq. Riggle prevails and ends the segment showing us some of his experiences in Iraq. Jon then reports on the Democrats, who for the 27th time meet to debate in a continuing show segment, "Clusterf@#k to the White House". Some of the big highlights was the fly landing on Sen. Chris Dodd''s head and the camera''s intense focus on Dennis Kucinich''s very attractive wife, even when Kucinich wasn''t speaking. Finally, Jon reports on Hugo Chavez who is consolodating his power by attempting to eliminate presidential term limits, silencing a television channel which is critical of his policies, and buying $3 billion worth of weapons in case the U.S. invades.', 0, '2007-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 109, 'Alan Weisman', 'Tonight, journalist and author of The World Without Us, Alan Weisman. Jon begins tonight reporting on NBC Sports coverage of the Michael Vick guilty plea. The coverage was apparently more concerned about Vick''s career and the gambling aspect of the dogfighting scandal. Jon then goes to Senior Baghdad Correspondent Rob Riggle who''s in Iraq in a segment called "Operation: Fluffy Bunny". Rep. Mike Pence once compared Iraq to a summer market in Indiana. Riggle shows us the subtle similarities between Indiana and Iraq. Finally, Jon reports on Karl Rove''s farewell tour on the Sunday morning talk show circuit and reviews some of Karl Rove''s greatest hits in a segment called "Superbad".', 0, '2007-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 110, 'Sen. Barack Obama', 'Tonight, presidential candidate Senator Barack Obama. Jon begins tonight reporting on the impatience President Bush is trying to quell about the Iraq War and the concerns over the Iraqi Parliament''s vacation time in August due to the 130 degree heat in Iraq. Jon goes to Senior Baghdad Correspondent Rob Riggle who''s in Iraq in a segment called "Operation Macho Kick-Ass". Riggle shows us some clips of American troops wishing the Iraqi Parliament a good vacation as they do menial tasks around Iraq. Finally, Jon reports on the complex intricacies that is American foreign policy in a segment called "America To The Rescue". For example, invading Iraq has strengthened Iran, creating fear in Saudi Arabia, leading to the U.S. selling $20 billion of weapons to the Saudi''s, thus intimidating the Israeli''s who are afraid of Hamas which is supported by the Saudi''s, causing the U.S. to increase military aid to Israel by 25% or $30 billion over 10 years.', 0, '2007-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 111, 'Lt. Col. John Nagl', 'Tonight, one of the military''s staff who helped write the Counterinsurgency Field Manual, Lt. Col. John Nagl. Jon first reports on President Bush, who goes over a list of America''s past wars to gain support for the Iraq War in a segment called "War Wars". Bush has also apparently changed his mind and is now comparing Iraq to Vietnam, saying that America''s mistake was not starting the Vietnam War, but ending it. Senior Political Correspondent Aasif Mandvi reviews Bush''s speech from Crawford TX talking about the potential benefits of prolonging the Vietnam War. For instance, Bush would have prolonged his college career to avoid being sent over to Vietnam and would have become a smarter man. Another added benefit, the splendor that would be the Vietnam Memorial, which could be seen from space as it stretches from D.C. to Times Square with the names of the victims.', 0, '2007-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 112, 'Jeff Garlin', 'Tonight, comedian Jeff Garlin promotes his new movie I Want Someone to Eat Cheese With and the airing of new shows for Curb Your Enthusiasm. Jon begins tonight''s show with news that Senator Larry Craig filed court papers to withdraw his guilty plea over the bathroom sex bust. Senior Public Restroom Correspondent Rob Corddry returns to the show after spending a year undercover at the Minneapolis Int''l Airport. Rob discusses the in''s and out''s of gay bathroom sex etiquette. Jon concludes the segment with a song highlighting the juicy details about the Craig scandal with a hip-hop singer in a segment called "R-Party: Trapped in the Closet". Finally, "Mess O''Potamia" continues with the Petraus report coming out today and Bush''s 6 hour trip to Iraq last week. Senior Foreign Policy Analyst Rob Riggle talked about the progress Bush saw with his own eyes during his short trip inside a heavily fortified part of Iraq''s Anbar province.', 0, '2007-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 113, 'Jodie Foster', 'Tonight, actress Jodie Foster promotes her new movie, The Brave One. Jon begins tonight''s show reporting on the overly hyped Petraeus report on the progress made in Iraq in a segment called "Iraq Me Dave Petraeus". As Jon notes, Petraeus'' testimony before the House had some mic problems. Petraeus also gave a disclaimer before officially testifying saying that he wrote the report himself and not the White House. But as Jon shows us in back to back clips, Petraeus and Bush essentially speak the same language. Resident Expert John Hodgman stopped by to talk with Jon about his keys to success and how Bush consistently redefines failure as success.', 0, '2007-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 114, 'Robert Draper', 'Tonight, author of Dead Certain: The Presidency of George W. Bush, Robert Draper. Jon begins tonight''s show with some news out of Russia. It seem Vladimir Putin not only dissolved his government by firing his prime minister and his entire cabinet, but also exploded the "father of all bombs", which despite its capability of evaporating all life, is also environmentally friendly. Next, Jon reports on some screaming war protesters at General Petraeus'' hearing in a segment called "You''re Not Helping". Jon then reports on the Democratic debates on the spanish channel Univision in a segment called "Clusterf@#k a la Casa Blanca". Some of the highlights, candidate Bill Richardson was barred from speaking Spanish so as not to gain an unfair advantage, the major topic for the night was of course immigration, and the Republican version was cancelled because only John McCain signed up. Finally, John Oliver speaks with the Qatari ambassador to the U.N.', 0, '2007-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 115, 'Douglas Farah', 'Tonight, journalist and author of Merchant of Death: Money, Guns, Planes, and the Man Who Makes War Possible, Douglas Farah. Jon begins tonight''s show with an update on Senator John McCain''s Straight Talk Express bus now changed into the No Surrender bus. Jon called John over the phone to see how the new bus was treating the Senator. Next, Jon talks about Petraeus'' Senate testimony and the 7 minutes allowed per Senator to ask their questions in a segment called "Iraq Me: Dave Petraeus". Senator Barbara Boxer spent the entire 7 minutes not asking a single question. Finally, Samantha Bee in a segment called "This Week In God: Back to School Edition". The religious topics this evening: a plan to teach Arabic in a public school in Brooklyn whose principal was eventually fired for a white Jewish lady, footbaths for Muslims in a university unisex bathroom, and a religious university created by the founder of Dominoes pizza.', 0, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 12), 116, 'Alan Greenspan', 'Tonight, former Federal Reserve Chairman and author of The Age of Turbulence: Adventures in a New World, Alan Greenspan. Jon begins tonight with a look at the burgeoning new O.J. Simpson story and the media''s spin on the phrase, "What goes on in Vegas, stays in Vegas". Next, Jon tries to sum up Alberto Gonzalez in three words as Alberto enjoyed his last day as Attorney General last Friday in a segment called "That''s Al Folks".', 0, '2007-09-18');
