INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 13), 153, 'Anne Hathaway', 'Three people die in an attempt to get a jump on their holiday shopping. John Oliver explains who is responsible for the terror attacks in Mumbai. Plaxico Burress lets down America''s youth by shooting himself in the thigh. MSNBC replaces Fox News as the new administration''s mouthpiece, and Anne Hathaway vows to become a train wreck.', 0, '2008-12-01');
