INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')), 29, 'Season 29', 'Following the departure of host Trevor Noah at the end of 2022, a series of guest hosts from both within and outside "The Daily Show''s" correspondents roster filled the program''s anchor chair throughout 2023, each sitting in for a one-week assignment.  On January 24, 2024, it was announced that Jon Stewart would return to the show he had hosted from 1999 to 2015.  This time around, in addition to serving as an executive producer, Stewart will host Monday episodes through at least the end of the 2024 U.S. election cycle.
