INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 29), 82, 'August 12, 2024 - Mark Cuban', 'Returning from COVID ("First-timer, did not care for it"), Jon examines Donald Trump''s hard time adjusting to Kamala Harris'' rising poll numbers, and posits that Trump''s use of the same "boilerplate" critiques on Harris that he previously applied to Joe Biden means that Trump desires to see Biden return to the race;[79] Mark Cuban discusses Silicon Valley''s love of Trump, the future of AI, and how transparent drug pricing benefits the healthcare system.', 46, '2024-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 29), 83, 'August 13, 2024 - Gabby Thomas', 'Desi Lydic tackles Donald Trump''s glitchy interview with Elon Musk on X, in which a slurring Trump announced plans to close the Department of Education, played ''90s pop culture trivia with Vladimir Putin, and revealed his new celebrity crush. On an Olympics edition of Sports War, Ronny Chieng and Michael Kosta recap the biggest stories from the 2024 Paris Games, including why Australian breaker Raygun is sure to be this year''s hottest Halloween costume. Also, three-time gold medalist Gabby Thomas joins Desi to discuss her big wins for Team USA, a moment she spent five years training for.', 35, '2024-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 29), 84, 'August 14, 2024 - Mark Duplass', 'Desi Lydic watches the leaked Project 2025 training videos and discovers the secret right-wing plan for transforming government, undoing climate rules, and eliminating all pronouns from the English language. Plus, the people who made them are a little weird and have close ties to Donald Trump, despite his denials. Grace Kuhlenschmidt explores the drawbacks of having a gerontocracy by chatting with UC Irvine neuropolitics researcher Mark Fisher and visits Congressman Maxwell Frost for a younger politician''s perspective. Also, actor, writer, producer, and director Mark Duplass talks to Desi about his second Emmy nomination for his role on the Apple TV+ series "The Morning Show."', 35, '2024-08-14');
