INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 29), 136, 'December 10, 2024 - Deb Haaland', 'Michael Kosta tackles the arrest of Luigi Mangione, the suspected United Healthcare CEO assassin, and unpacks America''s crush on the "hot felon". Special guest is Interior Secretary Deb Haaland.', 35, '2024-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 29), 137, 'December 11, 2024 - T.J. English', 'Michael Kosta investigates the manifesto of suspected UHC CEO shooter Luigi Mangione. Author T.J. English chronicles the rise & fall of an American cocaine empire in his latest book, "The Last Kilo".', 32, '2024-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 29), 138, 'December 12, 2024 - Peter Sarsgaard', 'Michael Kosta covers Time Magazine''s half-hearted Person of the Year, "Donald Trump". Actor Peter Sarsgaard discusses his new film "September 5", about the 1972 Munich Olympic terrorist attack.', 28, '2024-12-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')), 30, 'Season 30', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 1, 'January 6, 2025 - Jamie Raskin', 'Jon Stewart kicks off 2025 with an unusually civil Jan. 6 election certification, and right-wing media''s desperate attempts to make the Bourbon Street attack about immigration. Plus, Jon unpacks the eerily normal digital footprints of recent terrorists and questions the internet''s role in their radicalizations. "We''re going to be standing up every single day for the Constitution, the Bill of Rights, and the freedom of the people." Rep. Jamie Raskin of Maryland joins Jon Stewart from Washington D.C. to discuss the country''s future following the certification of Donald Trump''s 2024 election win. As the newly-elected ranking member of the House Judiciary Committee, he weighs in on Democratic priorities moving forward, engaging young voters through the Democracy Summer project, his friendship with Rep. Lauren Boebert, and positive memories from the day after the 2021 insurrection.', 39, '2025-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 2, 'January 7, 2025 - Halina Reijn', 'Desi Lydic discusses Trump''s imperialist push ahead of his inauguration, including making Canada the 51st state, renaming the Gulf of Mexico, and possibly invading Greenland. Plus, Jordan Klepper is hyped about colonialism''s apparent comeback. Desi Lydic breaks down how companies like Meta, McDonald''s, and Amazon are doing everything from ditching facts to bribing Melania with a documentary to get in the president-elect''s good graces. "My movie is sort of a letter to myself to kind of encourage myself to be more unapologetically my authentic self, without shame." Writer and director of the new film "Babygirl," Halina Reijn sits down with Desi Lydic to discuss the questions she set out to explore through the film about shame, sexuality, and authenticity, subverting the tropes of the erotic thriller genre, and how her background as an actress informs her directing.', 27, '2025-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 3, 'January 8, 2025 - Richard Reeves', 'Desi Lydic covers conservative media''s support for Trump''s Greenland invasion idea, Trump blaming Gavin Newsom for the LA wildfires, and Trump''s plans for pardoning the Jan. 6 insurrectionists. Desi Lydic tackles New York''s controversial new congestion pricing toll, while Josh Johnson hits the street to hear from real New Yorkers. "People say men don''t have problems. They are the problem." Founding president of the American Institute for Boys and Men and "Of Boys and Men" author, Richard Reeves, sits down with Desi Lydic to initiate a national conversation about the issues facing America''s young men. They discuss creating a space for dialogue about men''s issues without blaming women, how the phrase "toxic masculinity" pushes men from productive conversation, increasing the amount of men in teaching and mental healthcare, and how Trump acknowledged men''s issues but encouraged America to move backward.', 32, '2025-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 4, 'January 9, 2025 - Marianne Jean-Baptiste', 'Desi Lydic tackles the historically awkward reunion between Trump and all his political enemies at Jimmy Carter''s funeral. Plus, conservatives blame DEI for the raging wildfires in LA, so Michael Kosta is stepping in to help with his straight white maleness. Desi Lydic and Jordan Klepper are back with another Sports War to discuss the latest sports news: from NFL players hitting cash-out incentives to the college bowl''s delicious new mascots to whether wokeness killed the NBA''s ratings. Academy Award-nominated actor Marianne Jean-Baptiste sits down with Desi Lydic to discuss her critically acclaimed new film, "Hard Truths." She discusses the real-life inspiration behind her character Pansy, who''s "a bit of a difficult woman," the collaborative process with director Mike Leigh on set, and gets into character with reactions to today''s headlines.', 26, '2025-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 5, 'January 13, 2025 - Mark Carney', 'Jon Stewart examines how Trump''s finger-pointing, and the GOP''s threats to withhold disaster relief for the L.A. wildfires are missing the bigger picture: nature is fucked, and helping those in pain shouldn''t be a political issue. Mark Carney, Canadian economist and former Governor of the Bank of Canada and Bank of England, chats with Jon Stewart about his country''s response to Donald Trump''s desire to annex Canada: "It''s not going to happen." They also discuss the impending financial crisis Canada faces if Trump follows through on his tariff threats and how the country''s upcoming election involving the leader of the opposition Conservative Party Pierre Poilievre mirrors the 2024 U.S. presidential race. Carney also discusses his bona fides as he considers entering the race to replace Trudeau as the leader of Canada''s Liberal Party.', 43, '2025-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 6, 'January 14, 2025 - Boyd Holbrook', 'Jordan Klepper recaps Pete Hegseth''s Senate confirmation hearing for Secretary of Defense, which featured Republicans pretending to vet the Fox News anchor and Democrats questioning his infidelities, drinking problem, and misogyny. Plus, Desi Lydic teaches Jordan Klepper a lesson on digging too deeply into Trump''s cabinet selects. From humble Midwest beginnings to a dishonorable discharge from the army to landing his perfect job as a Fox News personality, Trump''s Secretary of Defense nominee is ready to fight... for his right... to party. This is the Daily Showography of Pete Hegseth. Actor Boyd Holbrook sits down with Jordan Klepper to talk about his experience playing Johnny Cash in the new film, "A Complete Unknown." They discuss working with director James Mangold on the legacy of playing Johnny Cash, Cash''s letters to Bob Dylan on the back of airplane barf bags, the pressures of portraying a real person on film, and how Christian Bale threw him a bone early in his career.', 28, '2025-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 7, 'January 15, 2025 - ALOK', 'Jordan Klepper reports on the Israel-Hamas ceasefire and TikTok''s final days. While Americans wait to find out if Trump or Elon Musk will come to TikTok''s rescue, Michael Kosta joins the ranks of those turning to Chinese alternative apps like RedNote. Why go to jail when you can get elected president? At James & Carino Law Firm, experts follow Trump''s lead in keeping their clients out of the slammer with their new slogan: "Stop trying to beat the law and start putting yourself above it." "All living is just stand-up comedy." Comedian, actor, and poet ALOK sits down with Jordan Klepper to discuss their new comedy special, "Biology!" They explain how reckoning with mortality inspired their set, embracing humor as a practice of resistance against transphobia, getting performance advice from Christopher Guest, and why Meta bending the knee for Trump is actually a trans allegory.', 28, '2025-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 8, 'January 16, 2025 - Rep. Tom Suozzi', 'Jordan Klepper covers Biden''s ominous farewell address, in which he warned about the end of democracy and formation of an oligarchy. Plus, Desi Lydic and Michael Kosta try to sort out the most important detail of the Israel-Hamas ceasefire: Who gets the credit? Grace Kuhlenschmidt revisits famed election prognosticator Allan Lichtman, who wrongly predicted a Harris victory, to demand answers on why Trump was victorious and educate him on the impact of Charli XCX. "We''ve gotta figure out how do we resist when essential, but how do we try to work together to get stuff done when we can?" Representative Tom Suozzi of New York''s third Congressional District sits down with Jordan Klepper to discuss what he thinks is the best strategy for Democrats during Trump''s second term, including a willingness to meet Republicans halfway when appropriate, and avoiding the GOP''s culture war distractions to focus on building up the middle class.', 36, '2025-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 9, 'January 20, 2025 - Brooke Harrington', 'Jon Stewart unravels the absurd "weave" that was Trump''s Inauguration Day, from Joe Biden''s buzzer-beater pardons to the tech billionaire VIPs in attendance to the new president''s passive-aggressive transfer of power. Plus, the Best F**kin News Team has full coverage on day one of the second Trump era. Brooke Harrington, economic sociologist at Dartmouth College and author of "Offshore: Stealth Wealth and the New Colonialism," sits down with Jon Stewart to discuss modern American oligarchies and the behavior of the ultra-rich. They talk about Donald Trump''s "broligarchy" of America''s tech billionaires, how they differ from the oligarchs of Russia and the Gilded Age, the lack of oblige and social norms imposed on these tech tycoons, and how a coalition of laborers is the only way to dismantle the system.', 40, '2025-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 10, 'January 21, 2025 - Stephanie Hsu', 'Ronny Chieng on Trump pulling the U.S. out of international treaties and organizations, pardoning the January 6th rioters, dissing Melania, and celebrating with the YMCA. Plus, Josh Johnson joins freed insurrectionists on their next criminal adventure. Jordan Klepper went to Trump''s inauguration to talk to MAGA diehards who traveled near and far to witness Trump''s... garbage truck? Actor Stephanie Hsu sits down with Ronny Chieng to discuss her new Peacock series, "Laid." She shares how Ali Wong''s advice pushed her to sign on for the dark rom-com, getting her big break in the "SpongeBob SquarePants" Broadway musical, and the importance of "Everything Everywhere All At Once." Plus, Stephanie offers a behind-the-scenes peek into Ronny''s unparalleled professionalism.', 33, '2025-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 11, 'January 22, 2024 - Talib Kweli', 'Ronny Chieng covers Trump''s face-off with a woke pastor, his lukewarm review of church, and a "fuck-it" approach to the Jan. 6 pardons. Plus, Troy Iwata investigates if the GOP''s amnesia for insurrectionist violence is really a disease. Triumph the Insult Comic Dog goes to the People''s March to talk to protestors about ways they can mobilize against the Trump administration, from new logos to Jimmy Carter conspiracies to storming a nearby coffee shop. Legendary hip-hop artist Talib Kweli sits down with Ronny Chieng to discuss the future of the music industry and his latest album "The Confidence of Knowing." They talk about supporting artists outside of streaming, how hip-hop is deeply rooted in social justice, understanding the political divide beyond Democrat vs. Republican, and how tech billionaires profit off our social media engagement.', 30, '2025-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 12, 'January 23, 2025 - Al Madrigal', 'Ronny Chieng dives into Trump''s first week: DEI snitches, affirmative action''s rollback to 1965, and a block on a "blatantly unconstitutional" executive order. Plus, Al Madrigal joins to discuss an enemy greater than immigrant violence: face tattoos. Charlamagne Tha God on why canceling rappers who performed at Trump''s inauguration is misplaced anger and how Democrats should move forward by following the GOP''s model of staying mad. Former Daily Show correspondent Al Madrigal sits down with Ronny Chieng to talk about his role in the series "Lopez vs. Lopez." They discuss working with comedy legend George Lopez, the chain letters Rob Riggle passed down to correspondents from Stephen Colbert, and the beauty of LA''s community mobilizing after the fires.', 30, '2025-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 13, 'January 27, 2025 - Royal Ramey', 'Jon Stewart discusses China''s new A.I. tool "DeepSeek," and urges Democrats to convince voters of THEIR plan rather than react to Trump''s "fascist" first week of executive orders. Chief Royal Ramey, a formerly incarcerated firefighter, and CEO and co-founder of the Forestry and Fire Recruitment Program, joins Jon Stewart to discuss how his program helps other formerly incarcerated people find a career in the fire sector. They discuss the hands-on training he received while incarcerated, why the work appeals to those currently serving time, and how helping a community and experiencing the "prison-to-public servant pipeline" changed his life.', 40, '2025-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 14, 'January 28, 2025 - Lil Rel Howery', 'Michael Kosta checks in on the latest Trumpworld news: new press secretary Karoline Leavitt, the banning of trans people in the military, and the aftermath of pardoned Jan. 6 insurrectionists. Plus, Troy Iwata sets up an elaborate sting for J6 sex offenders. Ronny Chieng and Michael Kosta debate Travis Kelce and Taylor Swift''s Super Bowl "ring," Philadelphia''s mayor''s misspelled Eagles chant, and a nacho tray distraction at a NHL game in the latest installment of Sports War. Comedian and actor Lil Rel Howery chats with Michael Kosta about starring in the new animated film "Dog Man," how therapy has benefited his life and his comedy, and the "Get Out" tagline that follows him at every T.S.A. checkpoint.', 29, '2025-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 15, 'January 29, 2025 - Rachel Mason', 'Michael Kosta tackles RFK Jr.''s confirmation hearing for health secretary, including protests from his family and medical professionals, his questionable stances on vaccines and AIDS, and Bernie Sanders''s onesie interrogation. Plus, the polio virus (Troy Iwata) shares his excitement about returning to work. Now that Trump-aligned billionaires run various social media platforms, Grace Kuhlenschmidt asks New Yorkers if they will finally delete their apps. Filmmaker Rachel Mason sits down with Michael Kosta to discuss her new Max docuseries, "An Update on Our Family." She explains what attracted her to the story of the Stauffer family, popular YouTube vloggers who shared their overseas adoption online, the ethics of profiting off your children via content, and how she navigates oversharing on her own social media accounts.', 33, '2025-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 16, 'January 30, 2025 - Vince Beiser', 'Michael Kosta on the tragic Washington D.C. plane crash and Trump''s baseless blame of DEI for the catastrophe. Plus, the Best F**kin'' News team breaks down which of Trump''s nominees was least qualified at their Senate hearings. Dry January is ending, but Lewis Black can''t figure out why it started. From Dry January to Damp January, Lewis Black asks the over-labelled generation why they''d pick the coldest, most chaotic month to go sober in this instalment of Back to Black. Journalist and author Vince Beiser sits down with Michael Kosta to discuss the paradox of electric vehicles and renewable energy and his latest book "Power Metal: The Race for the Resources That Will Shape the Future." They talk about how preventing climate change has led to a rush for "critical" metals, how China has dominated the field of mining and manufacturing, the minerals and metals behind Trump''s Greenland obsession, recycling electronic waste, and the importance of reusing and repairing gadgets.', 33, '2025-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 17, 'February 3, 2025 - Mo Amer', 'Jon Stewart examines Trump''s attacks on trans people, Canada, and DEI as his first presidential orders of business and asks: How is that making America great again? Plus, the Best F**kin'' News Team debate on where they rank in the DEI hierarchy. Mo Amer, a writer, stand-up comedian, and co-creator and star of "Mo," sits down with Jon Stewart to discuss the second season of his Peabody Award-winning Netflix series, inspired by his own refugee experience. They discuss how the series explores the complexities of statelessness and asylum, the absurdities of the immigration process, and how he leaned on Jon for support while figuring out whether to talk about Oct. 7 on his show.', 38, '2025-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 18, 'February 4, 2025 - Nicole Avant', 'Desi Lydic covers Elon Musk''s purge of USAID, Louisiana Senator John Kennedy''s lust for omelets, and Trump''s January 6 revenge on top FBI officials. Plus, Troy Iwata checks in to answer the burning question: Is any of this legal? If your company is sucking up to Trump by dismantling DEI initiatives, The Daily Show has you covered with this HR training video to help workers unlearn all those "woke" teachings. Acclaimed producer and best-selling author Nicole Avant talks to Desi Lydic about the true story behind the Netflix movie "The Six Triple Eight" of an all-Black, all-female battalion that contributed to a victory in WWII and describes what she learned about the Coast Guard in her former role as Ambassador to the Bahamas. She also discusses her book "Think You''ll Be Happy," which tells the story of her grief and path to healing after the tragic loss of her mother, and how her mother''s last words to her serve as both the title of the book and her mantra in life.', 35, '2025-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 19, 'February 5, 2025 - Julia Stiles', 'Desi Lydic tackles Trump''s proposal to take over Gaza and push all the Palestinians out to build a resort. Plus, Republicans try to spin the president''s plan, and Jordan Klepper gets in on the brainstorming sesh. Don''t worry about trade wars, Starbucks''s bathroom policy, or egg prices breaking the bank because Michael Kosta is back with guaranteed money-making tips in a new Ko$ta Doin'' Business. Emmy and Golden Globe-nominated actor Julia Stiles sits down with Desi Lydic to talk about her feature directorial debut, "Wish You Were Here." They discuss being in the "driver''s seat" as a director after years of acting, working with longtime friend Vanessa Carlton, balancing the humorous love story with universal issues, and how becoming a parent prepared her for managing film crews and actors on set.', 29, '2025-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 20, 'February 6, 2025 - Ke Huy Quan', 'Desi Lydic covers Trump''s latest executive actions, including a combination walk back/double-down on his Gaza plan, a ban on trans athletes that he probably didn''t proofread, and a "National Garden of American Heroes." Plus, Ronny Chieng and Josh Johnson debate which Americans are statue-worthy. Elon Musk needs Democrats to get their heads in the game and for Republicans to open their eyes before Elon Musk destroys the government like it''s a SpaceX rocket. "Love Hurts" actor Ke Huy Quan joins Desi Lydic to discuss his upcoming action flick that''s like "‘Die Hard'' for hopeless romantics." The Oscar-winning actor shares why his character represents a different type of action star, whether co-star Marshawn Lynch went full "Beast Mode" on him, and his tearful onscreen reunion with "Goonies" co-star Sean Astin. Plus, Quan auditions for his dream role as a supervillain with some incredibly evil line readings.', 29, '2025-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 21, 'February 10, 2025 - David Remnick', 'Jon Stewart tackles Trump''s attempt to be the Super Bowl MVP and examines the president''s rejection of federal agencies, birthright citizenship, and basic constitutional checks and balances. Plus, John Oliver welcomes America to its monarchy era. The New Yorker editor David Remnick sits down with Jon Stewart to discuss the magazine''s 100th Anniversary Issue and journey since its inception in 1925. They also talk about the importance of long-form journalism, especially under the overwhelming second Trump administration, as well as how the president is overstepping executive power, the danger of the tech oligarchy, and the need for Democratic politicians and citizens alike to finish licking their wounds and take action.', 45, '2025-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 22, 'February 11, 2025 - Jesse Eisenberg', 'Jordan Klepper on Trump''s boredom over his own tariffs, Pete Hegseth''s half-woke Fort Bragg rebrand, and Eric Adams''s "get out of jail" card. Plus, Grace Kuhlenschmidt, Michael Kosta, and Troy Iwata take a lesson from Mayor Adams on how to multi-task at the salon. Jordan Klepper and Ronny Chieng face off in Sports War over the Eagles'' blowout Super Bowl win, Shohei Ohtani''s interpreter''s sentencing, and Kendrick Lamar''s brutal takedown of Drake during his halftime performance. Academy Award-nominated actor Jesse Eisenberg sits down with Jordan Klepper to discuss writing, directing, and starring in his Oscar-nominated film, "A Real Pain." They talk about carrying generational grief and grappling with his own life''s meaning as a descendant of Holocaust survivors, how he got unprecedented access to film at a concentration camp in Poland, how his relationship with Kieran Culkin mirrors their characters, and how that influenced his role as director.', 32, '2025-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 23, 'February 12, 2025 - Colman Domingo', 'Jordan Klepper covers Trump pushing his Gaza takeover plan even further and the hypocrisy, conflicts of interest, and terrible "jokes" behind the most powerful unelected bureaucrat in D.C., Elon Musk. Marco Rubio was not always the it-girl of D.C. With his humble Florida beginnings and perfect lack of moral integrity, he was able to sneak his way in with Trump''s in-crowd. This is the Daily Showography of Marco Rubio narrated by Molly Ringwald. "The only agenda is looking into a person''s humanity and filling it with art and hope. That''s the agenda of the film." Emmy-winning actor Colman Domingo talks to Jordan Klepper about his Oscar-nominated performance in the film "Sing Sing," which is based on a real rehabilitation through the arts program at Sing Sing prison, including the meta experience of making the film with a cast of formerly incarcerated actors playing versions of themselves and the transformative power of art and theater.', 30, '2025-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 24, 'February 13, 2025 - Brady Corbet', 'Jordan Klepper tackles Trump getting "hot" and heavy with the Kennedy Center, the government confirming RFK Jr. as health secretary, and the president fumbling peace negotiations between Russia and Ukraine before they even start. Josh Johnson asks New Yorkers how they''re dealing with eggflation and tries to get in on the egg grift. "Audiences do want daring, original, provocative films." Brady Corbet, writer and director of "The Brutalist," joins Jordan Klepper to discuss his ten-time Oscar-nominated film. He explains how Trump''s first-term push to "Make Federal Buildings Beautiful Again" inspired the story, why the architect at the film''s center, László Tóth, feels so realistic, the connection between Brutalist architecture and the immigrant experience, and how he pulled it all off using VistaVision and a meager $10 million budget.', 30, '2025-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 25, 'February 24, 2025 - Rupa Bhattacharyya', 'Jon Stewart dives into Trump''s new Department of Government Efficiency, a.k.a. DOGE, and how the Elon Musk-led project masks its allegiance to corporate overlords and negligence to the American people under the guise of slashing the government''s budget. "We shouldn''t live in a world where the only programs that get saved are the ones Republicans are willing to put their stamp of approval on." Jon Stewart joins Georgetown Law''s Rupa Bhattacharyya, former Special Master of the September 11th Victim Compensation Fund, to discuss how Elon Musk and the DOGE project''s reckless budget cuts are affecting valuable programs like the one she used to oversee. Bhattacharyya explains how federal agencies and programs were typically non-politicized until Trump''s second administration, how similar uncertainty is affecting the World Trade Center Health Program, and why these roles are what the government exists to provide.', 39, '2025-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 26, 'February 25, 2025 - Wendi McLendon-Covey', 'Desi Lydic tackles Trump''s continued defense of Russia to Fox News''s dismay and his captivation with Emmanuel Macron''s accent, despite the French president''s attempts to sway him. Desi Lydic dives into the recent failures of Elon Musk''s Department of Government Efficiency, including the "DOGE ultimatum" issued to federal workers via email. Plus, as government workers protest, Michael Kosta unpacks the symbolism in an AI-generated video circulating of Trump and, uh, Musk''s toes. Actor Wendi McLendon-Covey joins Desi Lydic to discuss how her improv background prepared her for a career in comedy and the improvised sitcom pilot they worked on together years ago that led to a misguided boat purchase. McLendon-Covey also talks about the increased appreciation for healthcare workers she''s gained from playing a hospital administrator on the new NBC show "St. Denis Medical," and the next fake profession she''d like to play.', 30, '2025-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 27, 'February 26, 2025 - Rosebud Baker', 'Desi Lydic tackles Trump''s first cabinet meeting, which included Elon Musk accidentally canceling Ebola prevention and RFK Jr. downplaying the measles outbreak. Meanwhile, Trump announces $5M "gold card" for wealthy immigrants. Meet Elon Musk''s Body Movement Choreographer, Jean Lemón, the mastermind behind Elon''s X jump and heart-to-the-crowd salute. Comedian, actor & writer Rosebud Baker sits down with Desi Lydic to discuss her Netflix stand-up special "The Mother Lode." They talk about filming the special before and after giving birth, portraying an honest journey to motherhood, why Baker''s daughter is at high risk for becoming a comedian, and how kicking pigeons helps her cope while writing SNL''s Weekend Update.', 26, '2025-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 28, 'February 27, 2025 - Gabrielle Union', 'Desi Lydic rates the Democratic Party''s methods of opposing Trump on the cringe-o-meter: from off-key protest chants to interpretive dance to podcasts. Plus, with so many Dems saying "Fuck Trump," Grace Kuhlenschmidt thinks that might just be a great idea. As Black History Month comes to an end, Josh Johnson asks New Yorkers if they can censor Black history just as well as the White House has. "You have to be willing to do the right thing even if it makes you uncomfortable or even if it doesn''t actively benefit you, because real equality and real liberation is what benefits all of us." Actor, producer, and entrepreneur Gabrielle Union sits down with Desi Lydic for a conversation about making the new film she stars in, "Riff Raff," and how she uses her power as a producer to enact positive change in the industry and uplift people who are typically overlooked. They also discuss Union''s pride in her daughter Zaya''s activism work for the queer community and trans rights.', 28, '2025-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 29, 'March 3, 2025 - Matthew Desmond', 'Jon Stewart dives into the Oval Office meeting between Trump, Vance, and Zelenskyy, which shocked viewers more than John Cena''s heel-turn. Plus, Jon calls bullshit on Elon Musk''s challenge to an interview. "Investing in American people and stabilizing communities that need it the most is the best way for all of us." Sociologist at Princeton University and Pulitzer Prize-winning author of "Evicted," Matthew Desmond sits down with Jon Stewart to discuss his latest book, "Poverty, by America." They talk about America''s welfare state, how society benefits from poverty, the opportunity to close the poverty gap if the top one percent paid their taxes, and empowering the poor with better choices like building worker power, and expanding housing choice. They also highlight how Democrats need to get more serious about economic justice to fully commit to poverty abolitionism.', 46, '2025-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 30, 'March 4, 2025 - Mae Martin', 'Michael Kosta tackles Trump launching a trade war with Canada, Trudeau responding to Trump with a "disappointed dad" message, and the GOP blaming Biden for stock market issues. Plus, Grace Kuhlenschmidt unlocks American pride as things with Canada get ugly. Trump voters, Tesla owners, and Yeezy wearers are all suffering from buyer''s remorse right now. Ricky Velez offers some advice for dealing with the disappointment and getting rid of your now Nazi-affiliated purchases. Mae Martin, an award-winning comedian, actor, and writer, sits down with Michael Kosta to discuss "I''m a TV," their debut album as a singer-songwriter. They talk about the differences between performing as a stand-up and as a musician, finding new vulnerability as a songwriter after their top surgery, the solemn inspiration behind the song "Big Bear," and that one time they got a tattoo using a stick and poke kit.', 29, '2025-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 31, 'March 5, 2025 - Julien Baker & Mackenzie Scott aka "Torres"', 'Michael Kosta explains why Trump''s joint session speech felt like a theatrical production with appearances by co-star Elon Musk, over-the-top trolling, and blatant lies as the Democrats helplessly wielded their props. Critically acclaimed musicians, Julien Baker and Mackenzie Scott aka "Torres" sit down with Michael Kosta to discuss their forthcoming album, "Send A Prayer My Way." They talk about banding together during lockdown to create a country album, navigating a spiritual relationship with the divine, and writing a song about the unconditional love of a dog. Julien Baker and Mackenzie Scott perform "Bottom of a Bottle" from their forthcoming album, "Send A Prayer My Way."', 31, '2025-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 32, 'March 6, 2025 - Antoni Porowski', 'Michael Kosta on Trump doubling down then ditching Canada and Mexico tariffs, the GOP pretending the plunging stock market is normal, and the president pissing off China. Plus, Josh Johnson takes inspiration from Trump flip-flopping on tariffs. These days in America it''s easier to get a gun than get rid of one. Desi Lydic headed to Michigan to get to the bottom of the state''s "buy back" initiative that turned out to be refurbishing guns instead of destroying them. Bestselling author and culinary expert Antoni Porowski talks to Michael Kosta about hosting his new National Geographic show, "No Taste Like Home," which uses a dish significant to each guest as an entry point to a journey through their family and ancestral history. They discuss the extensive research process that goes into the show, some of the most emotional moments of the season, and why food is so important to Porowski and how he connects with his own family.', 30, '2025-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 33, 'March 17, 2025 - Sen. Chris Murphy', 'Jon Stewart highlights how the Democrats'' divisiveness over Trump''s budget bill is emblematic of their lack of vision, plummeting approval ratings, and continued losses against the MAGA cult. Third-term Senator Chris Murphy of Connecticut sits down with Jon Stewart to talk about the Democratic party''s path moving forward. He explains why he disagreed over the Dems'' decision not to filibuster the GOP budget, why his colleagues should be willing to take more risks, how misaligned priorities cost them voters to Trump, and the need to rally behind long-lasting ideas.', 41, '2025-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 34, 'March 18, 2025 - Ezra Klein & Derek Thompson', 'Jordan Klepper breaks down how Trump''s attempt to mass-deport Venezuelans by invoking a racist wartime law has led to a feud with the federal judge and an all-out constitutional crisis. Plus, Troy Iwata checks in on sick MAGA children who have just learned that their letters from the president were signed by... an autopen. The recent string of plane crash catastrophes has air traffic controllers overworked and travelers worried. In an all-new "Back In Black," Lewis Black breaks down America''s airline problem, the insufferable ways fliers ease their anxiety, and how Elon Musk is making it all worse. New York Times Opinion columnist Ezra Klein and staff writer for The Atlantic, Derek Thompson, talk to Jordan Klepper about their new book, "Abundance," which details how lawmakers can solve the affordability crisis by "building and inventing more of what we need."', 33, '2025-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 35, 'March 19, 2025 - Anthony Carrigan', 'Jordan Klepper covers the backlash against Elon Musk, including town hall rage against his unconfirmed DOGE position and sweeping Tesla vandalization. Plus, some advice for the returning NASA astronauts on how to acclimate to Trump and Elon''s new world. Trump is getting rid of all DEI celebrations... except for St. Patrick''s Day! Michael Kosta takes to the streets of NYC on St. Paddy''s Day to ask Irish Trump supporters what makes them so lucky. Emmy-nominated actor Anthony Carrigan sits down with Jordan Klepper to discuss his new film "Death of a Unicorn." They talk about working with unicorns through practical effects, experimenting with a Scottish accent, how Bill Hader opened the door for his character''s continuation in "Barry," and his upcoming role as Metamorpho in James Gunn''s "Superman."', 23, '2025-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 36, 'March 20, 2025 - Peter Wolf', 'Jordan Klepper covers Trump''s anti-DEI fallout, including the Pentagon''s erasure of Jackie Robinson and The Enola Gay. Plus, Troy Iwata joins the Republicans'' campaign to revive Tesla stock and keep Elon Musk rich. With many Americans preparing for doomsday, the apocalypse has become good business. Michael Kosta visits Fortitude Ranch, a post-apocalyptic survival community where preppers can wait out the end times in country-club glamour with their own rooms, artillery, and food supplies…for a hefty amount of cash. Legendary musician, artist, and New York Times best-selling author Peter Wolf joins Jordan Klepper to talk about his new memoir, "Waiting on the Moon." The former J. Geils Band frontman recounts the era in which he wrote their album "Full House," and how he strived to write a "not-boring" memoir by sharing vignettes about the people he idolized.', 35, '2025-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 37, 'March 24, 2025 - Paul Rudd', 'Jon Stewart goes old-school Daily Show on Trump and Republicans who pride themselves on "saving" free speech, all while censoring anybody who doesn''t agree with them. Paul Rudd sits down with Jon Stewart to chat about his latest starring roles in the films "Death of a Unicorn" and "Friendship," watching their kids grow up, and, of course, pharmaceutical side effects to the perineum.', 37, '2025-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 38, 'March 25, 2025 - Michelle Wu', 'Ronny Chieng tackles Republicans'' desperate attempts to defend Trump administration officials accidentally adding a journalist to their Signal group chat for planning missile strikes on Yemen. Ronny Chieng and Jordan Klepper face off in a March Madness edition of Sports War, where the two debate the McNeese student manager''s rise to fame, fans'' upset over a lack of upsets, and the NCAA tournament''s link to vasectomy season. Plus, a special Sports War halftime report from Grace Kuhlenschmidt. "We''re the safest city because we are safe for everyone." Boston Mayor Michelle Wu sits down with Ronny Chieng to discuss blazing a trail as Boston''s first female and first Asian-American elected mayor. They talk about winning over Boston''s passionate and diverse constituency by focusing on solving their everyday challenges, valuing immigrants for a safer environment, investing in affordable housing, and why Boston remains the safest big city in America.', 37, '2025-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 39, 'March 26, 2025 - Steve Coogan', 'Ronny Chieng dives into the churn of Signal-gate as Pete Hegseth downplays the war chat, Michael Waltz makes excuses, and journalist Jeffrey Goldberg brings receipts. Chris Distefano jumps in to solve America''s issues, from export tariffs to immigration to DOGE cuts to Canada and Greenland sovereignty. Comedian and actor Steve Coogan joins Ronny Chieng to discuss his expansive career and new film, "The Penguin Lessons." They talk about their experiences at Edinburgh Fringe, his West End run portraying four roles in a "Dr. Strangelove" adaptation, why comic characters like his infamous Alan Partridge speak to both political parties, and his experience on-set with real and robotic penguins.', 39, '2025-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 40, 'March 27, 2025 - Bill Murray', 'Ronny Chieng covers the upcoming Wisconsin Supreme Court election, including Elon Musk''s $20 million intervention in Republican Brad Schimel''s campaign, attack ads against the wrong Susan Crawford, and alternating pro-paedophilia smear campaigns. Also, Grace Kuhlenschmidt sees how billionaires are turning elections into games. Ronny Chieng on JD and Usha Vance''s big trip to Greenland, where native protesters are chanting "MAGA: Make America Go Away". Bill Murray sits down with Ronny Chieng to discuss his latest film, "The Friend", as well as his legendary career in TV and film. Murray talks about his philosophy of trying to stay in the moment, why he moved to France with his family after starring in a string of comedy blockbusters like "Ghostbusters", his pivot to working with independent filmmakers like Wes Anderson, Jim Jarmusch, and Sofia Coppola, and what he gained from being a part of comedy institutions at The Second City and "Saturday Night Live".', 34, '2025-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 41, 'March 31, 2025 - Oren Cass', 'Jon Stewart checks in on the state of democracy after Trump considers an unconstitutional third term in office, then takes a look at how all the national security officials involved in Signalgate have managed to skirt any accountability and keep their jobs, all while thousands of hard-working government employees lose theirs in DOGE layoffs. Oren Cass, chief economist at American Compass, who writes the "Understanding America" newsletter, sits down with Jon Stewart to discuss conservative economic policies of the New Right, which will be outlined in his forthcoming book, "The New Conservatives." Cass describes a conservative shift from faith in markets, using tariffs as incentives to pursue profit that supports society, how livable wages are the key to a strong economy, and the U.S.''s ideal economic and security alliance that includes balanced trade, owning defense burdens, and keeping China out.', 52, '2025-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 42, 'April 1, 2025 - Gianna Toboni', 'Michael Kosta breaks down the Trump administration''s disregard for the Constitution: Trump''s plan for a third term that even Republicans think is an April Fool''s joke, omitting due process on ICE deportations, and a mistaken deportation to El Salvador that can''t be undone. Also, Josh Johnson lays out the difference between Kid Rock''s tattoos and deportation tattoos. Lenard McKelvey (aka "Charlamagne Tha God") has had enough of Chuck Schumer and Gavin Newsom''s stale brands of politics and calls on the struggling Democratic Party to rebrand and match the energy of people like Cory Booker and Jasmine Crockett. "If we are going to have this practice carried out in our name and on our dime… then I think we need to face what we are actually doing". Gianna Toboni, an Emmy-winning journalist, joins Michael Kosta to share findings from her new book, "The Volunteer: The Failure of the Death Penalty in America and One Inmate''s Quest to Die With Dignity".', 31, '2025-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 43, 'April 2, 2025 - Melissa Arnot Reid', 'Michael Kosta recaps surprising wins for the Democrats, including a victory in the Wisconsin Supreme Court race despite Elon Musk''s financial interference, and a record-breaking 25-hour speech by Cory Booker. Plus, Trump launches his "Liberation Day" tariffs, and Republicans scramble to supply cover. In the first installment of "Mysteries of Donald Trump''s Very Very Large A-Brain" Trump explores the word "groceries," a concept he calls "old-fashioned." Then, Grace Kuhlenschmidt educates New York shoppers on the new Trump-era food store lingo. "We can be flawed and still be deserving of achieving great things." Melissa Arnot Reid, the first American woman to summit and descend Mount Everest without supplemental oxygen, talks to Michael Kosta about her new memoir, "Enough: Climbing Toward a True Self on Mount Everest." She opens up about using high-level climbing as a sometimes unhealthy coping mechanism and why her journey to inner peace is a "forever climb."', 29, '2025-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 44, 'April 3, 2025 - Scott Glenn', 'Michael Kosta recaps Trump''s tariffs fallout, from a stock market crash to cabinet officials taking to the airwaves to cheerlead the move. Also, Grace Kuhlenschmidt checks in on the penguins who now find themselves in a trade war. Jordan Klepper profiles Brian Glenn: Chief White House Correspondent of Real America''s Voice, boyfriend of Marjorie Taylor Greene, and the man famous for exposing his shocking and crass lack of awareness by asking Zelenskyy, "Why don''t you wear a suit?" in the latest "News To Meet Ya!". Legendary actor Scott Glenn sits down with Michael Kosta to discuss playing the mysterious Jim Hollinger on HBO''s "The White Lotus." Glenn talks about turning down the role before falling in love with the hit show, preparing for the rhythm of Thailand by learning Thai martial arts, how Off-Broadway opening night is scarier than skydiving, and why he''s uninspired by the "slash" career mentality in Hollywood. Glenn also advises Kosta on motorcycle safety.', 28, '2025-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 45, 'April 7, 2025 - Rahm Emanuel', 'Jon Stewart on the fallout from Trump''s tariffs, a stock market in a near-recession free fall, and the GOP''s spin of the economic turmoil as "no biggie". "Nobody will ever trust us. In eight weeks, he''s destroyed 80 years of reputation that America built". Rahm Emanuel, former ambassador to Japan under Biden and a current advisor at investment-banking firm Centerview Partners, joins Jon Stewart to talk about the United States'' international trade predicament in the wake of Trump''s tariffs. They discuss why it''s one of the most reckless things done by a president, why he thinks these policies gave China a "get-out-of-jail-free" card, his experience under the Obama administration, and why he believes a Democratic governor could be the one to turn the party around.', 45, '2025-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 46, 'April 8, 2025 - Mallory McMorrow', 'Desi Lydic covers the ongoing economic crisis from Trump''s trade war, which has created tension between Trump''s two favorite goons, Peter Navarro and Elon Musk. Meanwhile, Fox News''s journalistic integrity is front-and-center with their top story: "Look over there!" Also, Michael Kosta reports on how the tariff pile-on with China could have American manufacturers like his grandfather screwed. In the latest edition of Everything is Stupid, Ronny Chieng reveals the perverted trend ruining art history across the globe: fondling the breasts of female statues to find love, luck, and second base. "We can all write our own future together and not have hateful people decide it for us". Michigan state Sen. Mallory McMorrow talks to Desi Lydic about her book "Hate Won''t Win", which originated from her viral speech after being slandered by a political rival, and her desire to inspire others to find their own voices.', 33, '2025-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 47, 'April 9, 2025 - Olivia Munn', 'Desi Lydic tracks Trump''s "Tariff Day" roller coaster ride, from his shock announcement of a 90-day pause on reciprocal tariffs, to slapping even more tariffs on China. Plus, Olivia Munn explains how Trump''s tariff chaos is all just brushstrokes in the art of his deal. Could resurrecting the woolly mammoth be the fix for modern climate change? Troy Iwata sits down with leading scientists and paleontologists to determine if engineering woolly mammoths could be a problem or a solution. Former Daily Show correspondent and actor Olivia Munn sits down with Desi Lydic to discuss her new Apple TV+ series "Your Friends & Neighbors." They talk about Munn''s first day as a correspondent 14 years ago, bending gender stereotypes as the "fun mom," opening up about her struggle with postpartum anxiety, how a health test saved her life from breast cancer, and the role alongside Jon Hamm that brought her back to acting.', 35, '2025-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 48, 'April 10, 2025 - Bowen Yang', 'Desi Lydic tackles Trump''s cabinet of ass-kissers, his war on water pressure, and Kristi Noem''s viral gun photo-op. Plus, Troy Iwata breaks down the White House''s top issue: temperamental showers. Michael Kosta dives into America''s mad money problems in the face of Trump''s tariffs: panicked shopping on the rise, price hikes on everyday toys and goods, and the uncertainty around those precious iPhones. "Saturday Night Live" star and "Las Culturistas" co-host Bowen Yang sits down with Desi Lydic to discuss his new rom-com, "The Wedding Banquet." He shares the process behind his portrayals of hilarious "SNL" villains like JD Vance and George Santos, whether his pop-culture podcast has changed over the years, and why his new film feels like a "warm hug of a movie."', 31, '2025-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 49, 'April 14, 2025 - Ramy Youssef', 'Jon Stewart measures Trump''s weight on the authoritarian scale. Between the president''s refusal to correct the wrongful deportation of Kilmar Abrego Garcia to his incompetence on a variety of issues, Donald''s dictatorship isn''t looking very healthy. Award-winning actor and comedian, Ramy Youssef joins Jon Stewart to talk about the new animated series he co-created called "#1 Happy Family USA" and how the series, which follows a Muslim family trying to navigate post-9/11 America, resonates in Trump''s second term. They also discuss his favorite parts about making an animated show, the family members who inspire some of the characters, and how the word "Islamaphobia" kind of lets Islamaphobes off the hook.', 37, '2025-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 50, 'April 15, 2025 - Nimesh Patel', 'Ronny Chieng tackles the Trump administration shirking responsibility for a Maryland father''s mistaken deportation to El Salvador, their aggressive media tirade invoking Osama Bin Laden, and Harvard''s defiance of Donald Trump. Also, Josh Johnson explains how Trump''s power changes from Harvard to El Salvador. Trump promised that under his presidency, the rest of the world would fear and respect America "like never before". Desi Lydic takes a look at how other countries are responding to his massive trade war with a little less "R-E-S-P-E-C-T" and a little more "F-U". Emmy-nominated writer and comedian Nimesh Patel sits down with Ronny Chieng to discuss his upcoming stand-up tour. They chat about the first time they met in the New York comedy scene, the importance of crashing out on stage, why his daughter is "the biggest tariff" he''s encountered thus far, and the well-known Indians of MAGA.', 28, '2025-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 51, 'April 16, 2025 - Sen. Tammy Duckworth', 'Ronny Chieng breaks down how JD Vance''s comments calling Chinese people "peasants" have escalated both the shade war and the trade war with China, impacting American industries from automakers to Hollywood. Plus, Troy Iwata chimes in on the one thriving business of the trade war: TikTok luxury knockoffs. Michael Kosta checks in with Canadians to see how they feel about Donald Trump''s aims to make them America''s 51st state, including one ex-pat who immigrated to Canada when Trump first became president and a gun-loving member of Canada''s silent MAGA minority. Iraq War veteran and Democratic Senator from Illinois Tammy Duckworth sits down with Ronny Chieng to discuss the work she is doing in Congress to improve care for veterans and how the Trump administration is setting back that progress by taking jobs away from thousands of veterans and making DOGE cuts to life-saving Veterans'' Affairs programs.', 36, '2025-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 52, 'April 17, 2025 - Nancy Kwan', 'Ronny Chieng covers Elon Musk''s mission to have babies over DM, Pete Hegseth''s Air Force diversity purge, RFK Jr.''s anti-vaccine coded attack on autism, and proof he has never seen "Love on the Spectrum." Michael Kosta & Ronny Chieng go head to head over Rory McIlroy''s Masters Tournament takeover, brand-new Barbie Lebron James, Bryce Harper''s on-field gender reveal, and Baltimore''s oyster rebrand. "There will always be political clashes, that''s what makes the world interesting." Hollywood icon Nancy Kwan sits down with Ronny Chieng to discuss her trailblazing career and new book, "The World of Nancy Kwan: A Memoir by Hollywood''s Asian Superstar." They talk about an accidental screen test that brought her to Hollywood, a friendship with Bruce Lee that began in Hong Kong, and Kwan offers her perspective on what the West can learn from the East.', 34, '2025-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 53, 'April 28, 2025 - Chris Hughes', 'Jon Stewart takes a look at Trump''s first 100 days: from plummeting approval ratings to unfulfilled promises on immigration, health, and the economy, to destroying his reputation as a shrewd negotiator with China and Ukraine. Chris Hughes, an economist and the author of "Marketcrafters," sits down with Jon Stewart to unpack the economy''s fall under Trump and how understanding how politicians have shaped markets to work better could be its solution. They discuss how both parties have used marketcrafting to benefit Americans, whether the current economy requires an intervention, the need for institutions to help marketcrafting directly affect people over corporations, and his belief in a positive agenda for the future. Plus, as a co-founder of Facebook, Hughes weighs in on the company''s involvement with the Trump administration.', 41, '2025-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 54, 'April 29, 2025 - Katherine Maher', 'On Trump''s official second 100th day in office, Jordan Klepper delves into his lack of follow-through, including the division he''s sown, his back-and-forth on tariffs and firings, and taunting Canada until they elected a liberal prime minister. Trump let Elon Musk take a chainsaw to the federal workforce in order to save taxpayers money, but after hearing from some of the government employees who lost their jobs, Desi Lydic is starting to think the real waste, fraud, and abuse was living inside DOGE this whole time. "We know that the existence of local news, and public radio in particular, contributes to lower rates of polarization, higher rates of civic engagement, and higher rates of civic trust." NPR CEO Katherine Maher joins Jordan Klepper to stress the important functions of public media that are under threat from the Trump administration, especially educational children''s programming and local reporting in rural areas where public radio is often the only source for local news.', 27, '2025-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 55, 'April 30, 2025 - Jon Meacham', 'Desi Lydic covers Trump''s 100th day celebrations: inviting ABC News into the White House to misunderstand the Declaration of Independence, grooving to his famous "YMCA" dance, and putting the economy on financial Ozempic. From the dark halls of Santa Monica to the caves of the Trump administration, Stephen Miller has been working in the shadows as the White House Chief of Staff. From influencing election denial to mass deportations, can Stephen Miller''s vampiric bite kill American democracy? "If we get things right just enough of the time… that''s what democracy is, because it''s the fullest expression of all of us." Pulitzer Prize-winning presidential biographer Jon Meacham joins Desi Lydic to discuss the impact of Trump''s presidency on democracy.', 37, '2025-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 56, 'May 1, 2025 - Elissa Slotkin', 'Michael Kosta continues TDS coverage of Trump''s 100th day in office with reports from NewsNation''s town hall, where the president racially slighted Stephen A. Smith, as well as details on Mike Waltz''s exit and subsequent United Nations promotion, and Pam Bondi''s ridiculous claims about fentanyl deaths. With anxiety-inducing news cycles and Trump Derangement Syndrome on the rise, it''s easy to feel helpless with the current administration. But in these times of despair and uncertainty, the Hang In There poster will take all your Trump-related anxieties away! The perfect comforting distraction in these disturbing political times. "We don''t have the right to tune out when previous generations fought and fought and fought." Michigan Sen. Elissa Slotkin, the youngest Democratic female serving in the U.S. Senate, joins Michael Kosta to share her perspective on the current state of national security and the Democratic agenda moving forward.', 29, '2025-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 57, 'May 5, 2025 -  Rutger Bregman', 'Jon Stewart sorts Trump''s latest barrage of bullshit into the "OK" and "NOT OK" piles, including telling kids to cut down on dolls and pencils, calling for Alcatraz to reopen, posting AI-generated images of himself as the Pope, and shrugging off the Constitution. Historian and best-selling author Rutger Bregman joins Jon Stewart to unpack his latest book, "Moral Ambition", which is a call to action for people, especially those with education and privilege, to devote their talent and resources to careers and causes that make the world a better place. He describes how the political left has often made the mistake of placing moral purity above political relevance, and what they can learn from conservatives about building small movements into a larger, results-oriented coalition.', 41, '2025-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 58, 'May 6, 2025 - Glennon Doyle, Abby Wambach & Amanda Doyle', 'Desi Lydic recaps Trump''s oblivious reaction to getting friend-zoned by Canadian Prime Minister Mark Carney and prepares for a summer of shitty air travel as the Real ID deadline approaches and Newark Airport spirals into more chaos. Ronny Chieng breaks down how AI chatbot romances aren''t as stupid as you might guess; they''re stupid in some surprising ways, too. "This is not a time for self-help but for collective wisdom, where we learn from each other". "We Can Do Hard Things" podcast hosts Glennon Doyle, Abby Wambach, and Amanda Doyle sit down with Desi Lydic to discuss their new guidebook "We Can Do Hard Things: Answers to Life''s 20 Questions". They share the experience of living life "off the menu" by deviating from regulated paths, cultivating an ordinary life at home to make room for extraordinary moments, sharing a breast cancer diagnosis to stop gatekeeping information on women''s bodies, and finding a lane of activism to shift our perspective in grim political times.', 33, '2025-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 59, 'May 7, 2025 - John Green', 'Desi Lydic dives into Trump''s ominous "big announcement," the president renames the Persian Gulf, another US fighter jet falls off an aircraft carrier, and kids swap tariff-priced Barbies for the promise of economic freedom. In honor of the conclave, Lewis Black sounds off on the Vatican''s mysterious process to select a new pope, including this year''s parlay options, the surprising number of cardinals taking lessons from the Oscar-nominated "Conclave" film, and the merch being sold to incompetent tourists. "This is the middle of the story, not the end of the story, and it falls on us to write a better end." John Green, an award-winning author and global healthcare reform advocate, sits down with Desi Lydic to discuss his No. 1 New York Times bestseller, "Everything Is Tuberculosis: The History and Persistence of Our Deadliest Infection."', 27, '2025-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 60, 'May 8, 2025 - Michelle Buteau', 'Desi Lydic has the latest from the Vatican after the announcement of the first American pope, Leo XIV, including the world''s reaction to a Chicago-style pope and Fox News immediately yelling at him to speak English. Plus, Michael Kosta celebrates America''s conclave win. Following Trump''s ban on transgender people in the military, Jordan Klepper met with a panel of esteemed service members to discuss the president''s rejection of their qualifications, which stand in stark contrast to Trump''s own bone spur excuses. "It is not only the New York that I live in, but it''s also the America that I want to live in." Comedian, writer, and actor Michelle Buteau sits down with Desi Lydic to share how the Netflix series that she created and stars in, "Survival of the Thickest," began as a book of essays written just after her twins were born.', 29, '2025-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 61, 'May 12, 2025 - Gen. Stanley McChrystal', 'After Trump teased an upcoming "big announcement" last week, Jon Stewart contemplates what news Americans are supposed to be so psyched for: the possible suspension of due process, Trump''s appointment of Fox News host Jeanine Pirro as D.C. district attorney, Qatar''s $400 million luxury jet "gift" for Trump, or lower prices on the "fat shot drug"? "Our character is the essential identity of us as people and us as a nation, and we''ve let it erode." Retired four-star general who served 34 years in the U.S. Army, General Stanley McChrystal, sits down with Jon Stewart to discuss his book "On Character: Choices that Define a Life." They talk about leading a national conversation on character, employing empathy in war to negotiate with ideological warriors and mercenaries, what upset him most about Defense Sec. Pete Hegseth''s Signal chat leak, and how his wife taught him to live "with no use for the rear view mirror."', 39, '2025-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 62, 'May 13, 2025 - Matt Wolf', 'Jordan Klepper breaks down day one of Saudi Arabia''s effort to buy Trump''s affection: Arabian horses, a McDonald''s food truck, some business deals, and a mid-meeting nap. Plus, Michael Kosta is so taken by the Saudis'' lavish welcome he almost forgets about their oppression and orchestration of 9/11. Trump''s 2024 campaign blitz through right-wing podcasters and influencers bought him a big win among young male voters, so Jordan Klepper sat down with liberal darling and Twitch streamer Hasan Piker to better understand how the Left can find a bridge into bro culture, and how easily men are sucked into the manosphere by social media algorithms. Award-winning filmmaker Matt Wolf sits down with Jordan Klepper to discuss his new two-part HBO documentary, "Pee-Wee as Himself," which tells the story of the late comedian Paul Reubens in his own words.', 27, '2025-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 63, 'May 14, 2025 - Colum McCann', 'Jordan Klepper covers Trump''s lavish welcome in Qatar and lifting of Syrian sanctions, while RFK Jr. lands himself in muddy waters over swimming in a contaminated creek. Plus, Grace Kuhlenschmidt and Troy Iwata fight over investigating Trump''s $400 million jet vs. the sewage-tainted Rock Creek. The Trump administration is full of corruption, bigotry, and incompetence, but there''s one thing about them that Leslie Jones hates the most: They''re fucking GOOFY! She breaks down how Elon''s dad jokes, RFK Jr.''s sewage-swimming, and everything about JD Vance are only Making America Goofy Asses. Colum McCann, National Book Award-winning author, sits down with Jordan Klepper to discuss his latest novel, "Twist", which follows the people who fix the underwater cables that carry the world''s digital information at the extreme depths of the ocean.', 28, '2025-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 64, 'May 15, 2025 - Rep. Jake Auchincloss', 'Jordan Klepper recaps Trump''s visit to the United Arab Emirates, where he was greeted by a lackluster hair dance ceremony, serenaded a Qatari military base with Lee Greenwood, and twisted discussions about drones into a ramble about Sean Duffy and Pete Buttigieg''s bicycle. Plus, as his Middle Eastern tour comes to an end, Josh Johnson analyzes whether the president accomplished anything. Ronny Chieng tests out effective altruism by joining the Shrimp Welfare Project to ascertain if sparing shrimp from anxiety and painful death is a productive way to be philanthropic. "If we''re going to govern from a place of trust with the American people, we have to show people what we are for, not just what we are against". Massachusetts Democratic Congressman Jake Auchincloss joins Jordan Klepper to unpack his recent 27-hour markup session of the House Energy and Commerce Committee.', 30, '2025-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 65, 'May 19, 2025 - Patrick McGee', 'Jon Stewart critiques the media spin on Joe Biden''s cancer diagnosis, from CNN''s shameless promotion of Jake Tapper''s book to Fox News''s "but"-tainted sympathies. ward-winning journalist Patrick McGee joins Jon Stewart to discuss how Apple built China in his new book "Apple in China: The Capture of the World''s Greatest Company". They talk about Apple "sleepwalking" into this crisis, building a competitive market in Xi Jinping''s authoritarian state, the vocational training that boosted rivals, how Trump''s attempted Apple boycott backfired, and whether investments may be facilitating the annexation of Taiwan.', 44, '2025-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 66, 'May 20, 2025 - Prabal Gurung', 'Ronny Chieng covers Trump''s cabinet cracking under pressure, from Kristi Noem drawing a blank on habeas corpus, immigration getting the Bravo treatment, Kash Patel and Dan Bongino flip-flopping on Jeffrey Epstein''s "suicide", and Sean Duffy finding an air travel solution in a Jesus painting. In the latest edition of Sports War, Ronny Chieng and Michael Kosta go head to head over NYC''s street-wide Knicks celebration, the Dodgers'' new Japanese pitcher''s bathroom requests, and Bill Belichick spending the rest of his life with 24-year-old Jordon Hudson. Prabal Gurung, award-winning fashion designer and author of the new memoir "Walk Like a Girl", describes to Ronny Chieng how his rise through the fashion world of New York began with the support of his family in Nepal, especially his mother.', 41, '2025-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 67, 'May 21, 2025 - Simon Pegg', 'Ronny Chieng tackles the president of South Africa''s uncomfortable White House visit and a MAGA couple shortchanged by a "RUMP" watch. Plus, Trump sets his heart on a $542 billion "golden dome" to protect America from hypothetical attacks, including those provoked by international roast comic Grace Kuhlenschmidt. Lenard McKelvey (aka "Charlamagne Tha God") looks at Republicans'' obsession with Trump as a father figure and reminds them that not only is Trump a bad dad to his own kids, he''s an abusive dad to Americans. Screenwriter, comedian, and actor Simon Pegg joins Ronny Chieng to promote the final installment of the franchise, "Mission: Impossible - The Final Reckoning". They talk about Pegg''s humble beginnings doing standup with his goldfish, how the director Christopher McQuarrie weaved earlier films into the franchise''s ending, the power of movie theaters to unite people in experiences, and Tom Cruise''s comedic timing while performing epic live-action stunts.', 34, '2025-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 68, 'May 22, 2025 - Dawn Staley', 'Ronny Chieng covers the House passing Trump''s "Big Beautiful Bill", trading Medicaid, food stamps, and the national debt for a waiver on silencer registration fees. Plus, the Big Beautiful Bill (Troy Iwata) can''t handle the Democrats'' poetic attack on his looks. Homeland Security Secretary Kristi Noem is asking undocumented migrants to self-deport for a $1000 stipend, and Al Madrigal is taking her up on the offer. He tells Ronny Chieng how he''s living large in South Sudan, the DHS''s new favorite war-torn dumping ground. Dawn Staley, basketball legend and head coach of the University of South Carolina women''s basketball team, talks to Ronny Chieng about her new memoir, "Uncommon Favor", and how she''s built a championship program by valuing individuals over analytics and meeting her players where they are.', 30, '2025-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 69, 'June 2, 2025 - Carole Cadwalladr', 'Jon Stewart tracks Elon Musk''s White House crash, from the high of being Trump''s "first buddy" to the low of his black-eyed DOGE send-off. Now that the 100-day honeymoon is over, Jon also checks in on Trump''s other struggling cabinet members, like the FBI''s burned-out deputy director, Dan Bongino. "I think what is happening in America is they are building a techno-authoritarian surveillance state." Carole Cadwalladr, the award-winning journalist behind the Substack newsletter "How to Survive the Broligarchy," talks to Jon Stewart about how the U.S. government ignored the huge wake-up call that was the Cambridge Analytica-Facebook data breach scandal – a story Cadwalladr broke and which resulted in no legislative protections for citizens'' private data. She warns about the unregulated dangers that data-mining and AI pose to individual privacy and freedom, and what people and institutions can do to push back on big tech''s authoritarian agenda.', 42, '2025-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 70, 'June 3, 2025 - Candace Parker', 'Michael Kosta unpacks Elon Musk calling Trump''s Big Beautiful Bill a "disgusting abomination"; the head of FEMA learning there''s a hurricane season; Social Security chief Frank Bisignano googling "social security"; and Tulsi Gabbard''s Fox News-style intelligence briefing makeover. For those airline customers nervous that diverse pilots aren''t qualified for their jobs, White Flight''s racial support pilots can put their minds at ease. Let a white male stand-in reassure passengers that their plane won''t crash from DEI, while the actual pilots do all the work behind the scenes. "I would challenge anyone to love the game of basketball more than me". Candace Parker, three-time WNBA champion and two-time Olympic gold medalist, joins Michael Kosta to discuss her new book, "The Can-Do Mindset".', 30, '2025-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 71, 'June 4, 2025 - Leah Litman', 'Michael Kosta dives into the fallout of Trump''s Big Beautiful Bill: Elon slamming the "sprawling spending bill" and turning on Trump, Democrats backing Elon''s criticisms, and Marjorie Taylor Greene revealing she never read it in the first place. Plus, the Big Beautiful Bill (Troy Iwata) claps back at all the new haters. The Trump administration has pushed out legacy media outlets from the White House press room in favor of more conspiratorial right-wing "new media" figures like Tim Pool: a conservative YouTuber and podcaster passionate about stroking Trump''s ego and delivering truthful reporting sponsored by Russian interests. "The next several decades might look like a ‘Hunger Games'' for liberal constitutional democracy." University of Michigan Law professor and "Strict Scrutiny" co-host Leah Litman joins Michael Kosta to discuss her New York Times bestseller, "Lawless: How the Supreme Court Runs on Conservative Grievance, Fringe Theories, and Bad Vibes."', 35, '2025-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 72, 'June 5, 2025 - Jonathan D. Cohen', 'Michael Kosta unpacks the latest in Musk and Trump''s messy bromance breakup: Elon doubling down on critiques against the Big Beautiful Bill, Trump''s parent-level guilt, Kanye West calling for a ceasefire, and threats of an Epstein files leak. Plus, Grace Kuhlenschmidt explains that the president is merely playing a game of 7D chess. Students and teachers alike are outsourcing all their work to AI, but Lewis Black thinks kids should stop experimenting with AI in college and go back to experimenting with fun things, like LSD. Jonathan D. Cohen, historian and author of the new book, "Losing Big: America''s Bet on Sports Gambling," joins Michael Kosta to break down how legalized sports betting has become such a huge part of American sports culture, industry, and has created a public health gambling addiction crisis, especially among young men.', 32, '2025-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 73, 'June 9, 2025 - Stephen A. Smith', 'Jon Stewart examines chaos in the MAGA-verse, as escalating ICE raids in Los Angeles erupt in protests, Stephen Miller hunts for nonviolent immigrants, Elon plays the Epstein card on Trump, and the Trump-Elon alpha male war reveals itself as a sensitive baby feud. "I want to be a major player in terms of a voice and a conduit for change. I want to make sure that people know that the BS has got to stop". Stephen A. Smith, bestselling author & presenter of "The Stephen A. Smith Show", sits down with Jon Stewart to discuss why he would rather be a hellraiser than an elected official, how politicians have divided and contributed to the demise of America, and why the messenger matters in politics.', 39, '2025-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 74, 'June 10, 2025 - Bryan Cranston', 'Desi Lydic has the latest updates from the L.A. ICE protests, including Trump''s outsized military deployment to the city, which defies both California Governor Gavin Newsom and the... "Pussy Comitatus Act"? Plus, one soldier sends a letter home from the frontlines of the L.A. war. Where does the public stand on Trump vs. Elon? Grace Kuhlenschmidt and Josh Johnson head out to ask New Yorkers to pick: Team Douche or Team Pedophile? Bryan Cranston joins Desi Lydic to discuss his new movie, "Everything''s Going To Be Great," and a busy year of work, including his third film with Wes Anderson and playing a hilarious exec on "The Studio." He shares how he navigates portraying vastly different characters, why he had to really sell himself to get the role of Walter White, and his passion for live theater.', 30, '2025-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 75, 'June 11, 2025 - Atsuko Okatsuka', 'Desi Lydic tackles Trump''s politicized Fort Bragg rally, which screened soldiers for loyalty and waist size. Also, Trump plans a $45 million military parade for his birthday, and Ronny Chieng is pumped to sit courtside at a display of America''s military might. Corporate America has been suspiciously quiet this Pride Month due to fear of backlash from the Trump administration. Desi Lydic and Troy Iwata discuss the current muted tones of Pride Month, and how the corporations will have to prove themselves when the pendulum swings back to the gays. Comedian Atsuko Okatsuka talks to Desi Lydic about her new Hulu stand-up special, "Father", including how her lack of housework partly inspired the title, as well as the intentional juxtaposition of her colorful clothes and set with the deeply personal stories she mines for levity.', 26, '2025-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 76, 'June 12, 2025 - Jeff Hiller', 'Desi Lydic tackles Elon Musk''s vague apology to Trump; RFK Jr. putting his conspiracy buddies in charge at the CDC; and Tulsi Gabbard getting AI to do the FBI''s homework. Also, Trump celebrated deploying the military on Angelenos with tickets to "Les Misérables", so Jordan Klepper, Michael Kosta, and Josh Johnson debate whether the president is a Jean Valjean or a Javert. Stephen A. Smith is the King of Takes, but how did he begin his reign? From the Fashion Institute of Technology to Winston-Salem State University, Smith went from the basketball court to print media, ensuring that everyone knew he had all the best takes. After getting a job at ESPN, Smith taught everyone the difference between talking shit and taking shit. Actor, writer, and comedian Jeff Hiller sits down with Desi Lydic to discuss his new memoir, "Actress of a Certain Age".', 32, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 77, 'June 16, 2025 - John Mulaney', 'Jon Stewart breaks down Netanyahu''s "urgent" strike on Iran''s nuclear program, MAGA''s sustained focus on battling protesters and immigrants in Democratic cities, and how Trump''s unattended parade of weaponry explains America''s muted response to the Minnesota assassination. "This isn''t the most important message you''ll hear tonight, but everyone should fight three teenagers once a year." John Mulaney, actor, writer, comedian, and host of the Netflix show "Everybody''s Live," fought three 14-year-old boys on the finale of his talk show and lived to tell Jon Stewart the tale. They get deep into fighting strategies, masculinity, father-son competition, the guy who threw his shoes at George W. Bush, and more. Plus, a game of Daily Show Interview Guest Jeopardy.', 50, '2025-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 78, 'June 17, 2025 - Bill Clinton & James Patterson', 'Jordan Klepper dives into Trump''s Irish exit from Canada''s G7 Summit to explore a "better than a ceasefire" between Israel and Iran, and how Trump''s threats against Iran''s ayatollah started an intra-MAGA beef with Tucker Carlson. Plus, Michael Kosta finds a delicious way to capitalize on the situation in Iran. Was Trump''s parade a military celebration or a show of authoritarian power? Jordan Klepper hit the streets of Washington, D.C., to talk to MAGA during Trump''s $45 million military parade. Klepper asks folks how they feel about DOGE cuts, the L.A. protests, and whether they showed up to celebrate the military or the president''s birthday. "If you don''t like who''s being elected, and you don''t like what they''re doing, you got to get out there and fight for it. And one of the things that we try to do in this book is to make people see that."', 49, '2025-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 79, 'June 18, 2025 - Matt Berninger', 'Jordan Klepper covers the latest on a potential war with Iran, including the fight between Tucker Carlson and Sen. Ted Cruz that was heard across the MAGA-verse and Trump''s big decision to ignore the problem and focus on erecting flagpoles. Jordan Klepper and Desi Lydic go head-to-head over the latest sports news: DeMarcus Cousins''s outburst in Puerto Rico, Aaron Rodgers''s surprise wedding, and Caitlin Clark''s return to the WNBA. Grammy award-winning singer-songwriter and frontman of the band The National, Matt Berninger, sits down with Jordan Klepper to discuss traveling back to his Midwest roots in his new solo album "Get Sunk." They talk about burning down the idea of who you are to find your authentic self, how he started writing songs on baseballs, connecting to Taylor Swift''s honest songwriting, and how the song "Inland Ocean" is a prologue for the album.', 36, '2025-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 80, 'July 7, 2025 - Steve Kroft', 'Jon Stewart covers the passage of Trump''s Big Beautiful Bill: Republicans bashing then endorsing the megabill, trading tax cuts to sway senators, giving a $40 billion infusion to ICE, boosting billionaires at the expense of Medicaid and SNAP, and more. Former CBS "60 Minutes" correspondent and Emmy and Peabody Award-winning journalist Steve Kroft joins Jon Stewart to discuss a $16 million settlement in President Trump''s lawsuit against Paramount Global, CBS and Comedy Central''s parent company. They discuss how an incoming corporate merger and pressure from Trump''s FCC may have influenced the settlement, why journalists and legal experts consider it a "shakedown," its impact on freedom of the press, and the one thing Trump didn''t get: an apology.', 44, '2025-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 81, 'July 8, 2025 - Michael Luo', 'The Department of Justice (and Michael Kosta) try to gaslight Ronny Chieng about a suddenly "nonexistent" Jeffrey Epstein client list, Trump lists Benjamin Netanyahu as a reference on his Nobel Peace Prize application, and the TSA ends their foot fetish. Ronny Chieng checks in on the status of Trump''s trade war, including the president''s half-firm decision on another tariff delay and his new international trade pen pal, "Mr. Japan." "History is written by the powerful, and the powerless are often left out of history." Michael Luo, author of "Strangers in the Land: Exclusion, Belonging, and the Epic Story of the Chinese in America" and executive editor at The New Yorker, joins Ronny Chieng to discuss the untold stories of Asian American persistence and resilience in the face of bigotry.', 34, '2025-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 82, 'July 9, 2025 - Lauren Greenfield', 'Ronny Chieng dives into the expanding world of AI: Elon Musk''s de-wokified Grok goes Nazi, a Marco Rubio imposter fools government officials, and Grace Kuhlenschmidt appreciates the mediocre world of AI-generated music. Don''t worry about Trump''s Big Beautiful Bill passing, because Michael Kosta is cracking the code on how you can exploit Medicaid cuts, gambling taxes, and even Alaskan tax breaks to make some sweet dough. Emmy Award-winning filmmaker Lauren Greenfield and Ronny Chieng dive into the effects of social media on teens, which she explores firsthand in her latest docu-series, "Social Studies". She shares how she built up enough trust with the teenage documentary subjects to record their phone activities and how their discussion group highlighted children''s hunger for in-person conversation and connection with their peers.', 35, '2025-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 83, 'July 10, 2025 - Youngmi Mayer', 'Ronny Chieng weighs in on Trump''s international affairs: a hike in tariffs to help his Brazilian doppelgänger stay out of prison, an Iranian threat to his sunbathed bellybutton, and a light refresher on the pause in aid to Ukraine. Plus, Josh Johnson reflects on Trump''s understanding of African culture, from their languages to their love languages. Troy Iwata finds one job that AI can''t do: human carpet. Performance artist and professional human carpet Georgio shares examples of his work and gives Troy a crash course in letting people walk all over you. Writer and comedienne Youngmi Mayer sits down with Ronny Chieng to discuss her memoir "I''m Laughing Because I''m Crying". They talk about growing up in Korea under the influence of pro-American propaganda, learning her Korean family history from her "certified yapper" mother, getting bullied for being biracial in Korea, and how she embodied the Korean practice of laughing through trauma in the book.', 34, '2025-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 84, 'July 14, 2025 - Kyla Scanlon', 'Jon Stewart delves into the MAGA furor over Trump''s handling of the Epstein case, Trump''s cheap distractions-turned-threats against Rosie O''Donnell, and the president''s double standard on red state vs. blue state relief. Plus, Jon demands accountability from Elmo for his antisemitic rant on X. "Most economic problems are political problems at the end of the day." Economic commentator Kyla Scanlon sits down with Jon Stewart to discuss her book, "In This Economy? How Money and Markets Really Work." They talk about the importance of teaching Americans about the economy in accessible ways, how the government has weaponized people to justify Medicaid cuts under Trump''s Big Beautiful Bill, why labor and capital don''t have to be mutually exclusive, and why she''s optimistic about the future.', 44, '2025-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 85, 'July 15, 2025 - Thomas Chatterton Williams', 'With MAGA and Democrats demanding answers about the Epstein files and Trump denying their existence, Jordan Klepper charts the president''s well-documented history with Jeffrey Epstein and Ghislaine Maxwell, which might be why the president wants the entire thing to blow over. Also, Michael Kosta offers up a defense from Mar-a-Lago. Do you have a moment to talk about the environment with Nick Offerman? "To talk about it only as a matter of identity actually limits our ability to engage non-Black people in the struggle, which is that no American should be OK with law enforcement being able to break somebody, especially a poor person without any resources, the way that they broke George Floyd, whatever color you are". Thomas Chatterton Williams, staff writer at The Atlantic and author of the forthcoming book, "Summer of Our Discontent: The Age of Certainty and the Demise of Discourse", joins Jordan Klepper to discuss his analysis of America''s fall from Obama-era optimism.', 46, '2025-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 86, 'July 16, 2025 - Jennifer Kaytin Robinson', 'Jordan Klepper follows MAGA''s continued frustration with Trump for not releasing the Epstein files, and Trump''s continued frustration with MAGA for not shutting up about it. Also, Lauren Boebert suggests the GOP''s own underage-sex-trafficking expert, Matt Gaetz, should lead a special counsel investigation into the hidden files, but The Daily Show''s Grace Kuhlenschmidt already has all the evidence Trump''s supporters could ever need. There are currently over 400 political third parties in the U.S., and Elon Musk is adding a new one to the list: the "America Party". Michael Kosta talks to New Yorkers to see which of Elon''s party platforms speak to voters: antisemitism, white supremacy, or ketamine. "My love of film was forged in the blanket forts of middle school sleepovers". Writer and director Jennifer Kaytin Robinson sits down with Jordan Klepper to discuss her theatrical feature debut, "I Know What You Did Last Summer".', 28, '2025-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 87, 'July 17, 2025 - Reggie Watts', 'Jordan Klepper covers Trump''s ugly battle with Federal Reserve Chair Jerome Powell, which is fueled by Powell''s refusal to lower interest rates despite Trump''s toothless threats to fire him. Plus, Desi Lydic breaks down the president''s attempt to use the Fed''s building renovations as an excuse to send Powell packing. Everybody poops, even New York City cab drivers. But without access to a bathroom, where are cabbies supposed to go when they gotta go? Josh Johnson hears from a panel of taxi drivers to better understand this problem, and helps the founder of the New York State Federation of Taxi Drivers workshop some possible solutions. "Comedy is a form of rapid community." Comedian and musician Reggie Watts, who served as band leader for "The Late Late Show" for eight years, sits down with Jordan Klepper to discuss his Reggie Watts Live tour and the state of comedy.', 33, '2025-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 88, 'July 21, 2025 - Dr. Patrick Soon-Shiong', 'Jon Stewart dives into Trump''s crude birthday card to Epstein and his desperate attempts to distract MAGA with Hillary''s emails, the release of the MLK files, and the return of racist football mascots. Plus, Jon reacts to CBS cancelling "The Late Show with Stephen Colbert" and calls upon corporations, advertisers, and institutions to "sack up" with the help of the "Go Fuck Yourself" choir. Chairman of the Los Angeles Times and of ImmunityBio, Dr. Patrick Soon-Shiong sits down with Jon Stewart to share how his groundbreaking work in cancer research and his surprising purchase of the Los Angeles Times in 2018 are both part of his vision to heal the country and give everyone an opportunity at the American dream. He offers a background to his work in finding cancer treatments that harness the body''s natural immunity – a departure from decades of the harmful, money-making chemotherapy standard – and shares how growing up in apartheid South Africa gave him a deep appreciation for news media.', 49, '2025-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 89, 'July 22, 2025 - Rob Franklin', 'Josh Johnson kicks off his first day behind the host desk with possible new intel from Ghislaine Maxwell and Trump''s latest batch of Epstein distractions: a 2016 Obama conspiracy, releasing the MLK files, and even admitting that he''s not a medical marvel. Plus, you won''t believe the 100% real Epstein bombshells that Grace Kuhlenschmidt found in the MLK files. Lenard McKelvey aka "Charlamagne Tha God" unpacks the 79-year-old Trump''s recent memory loss, agitation, inappropriate behavior, confusion, and disorientation, all of which just so happen to be symptoms of dementia. Fiction and poetry writer Rob Franklin sits down with Josh Johnson to discuss his critically acclaimed debut novel, "Great Black Hope". They talk about exploring respectability politics through the main character, Smith, the tension between race and class in the justice system, and how not knowing your height is true tall privilege.', 34, '2025-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 90, 'July 23, 2025 - Samara Cyn', 'Josh Johnson covers the breaking story that the DOJ informed Trump he was on the Epstein list, newly unearthed photos of Trump''s friendship with Epstein, and the president''s wild pledge to lower drug prices by 1000%. Plus, Michael Kosta explains why Trump''s Epstein drama is all Obama''s fault. Samara Cyn, a recording artist making her late-night television debut, joins Josh Johnson to discuss her new EP, "backroads." They talk about her raw and real lyrics, why her new EP is more lighthearted than her last release, how her music touches on the "really weird" state of a world going back on immigrant, LGBTQ+, and women''s rights, and her song "hardheaded," which tackles privilege head-on. Samara Cyn makes her television debut with a performance of "hardheaded" off her EP "backroads."', 30, '2025-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 91, 'July 24, 2025 - Christopher McDonald', 'Josh Johnson covers the aftermath of revelations that Trump knew he was on the Epstein list: Pam Bondi bails on her CPAC appearance, videos connecting Epstein to Trump surface, and everyone in the MAGA-verse, from GOP lawmakers to the QAnon Shaman, want answers. Jordan Klepper takes on conservative CNN commentator Scott Jennings, a former White House aide for George W. Bush who quickly ditched his establishment-bucking opinions to spew MAGA talking points for "the fun party." "I think you must have a bad guy to feed your leading man, especially in ‘Happy Gilmore''." Emmy-nominated actor Christopher McDonald sits down with Josh Johnson to discuss revisiting his career-defining role as Shooter McGavin in "Happy Gilmore 2." They talk about how the actor is known as "Shooter" among fans, the responsibility of playing a bad guy, and his dream storyline for "Hacks."', 35, '2025-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 92, 'July 28, 2025 - Peter Beinart', 'Jon Stewart dives into Trump''s golf shenanigans in Scotland, the Republican "caddies" providing him cover on the Epstein scandal back home, and the possibility of a pardon for Ghislaine Maxwell. Plus, Jessica Williams will NOT allow Beyoncé to be roped into Trump''s use of exceptional Black people as a distraction. Editor-at-large of "Jewish Currents," who writes "The Beinart Notebook" on Substack, Peter Beinart sits down with Jon Stewart to discuss his book, "Being Jewish After the Destruction of Gaza: A Reckoning," and speaking out against Israel. They talk about learning from Jewish history to be the saviors rather than the oppressors, America and the U.N.''s failure to hold Benjamin Netanyahu accountable, the urgency of engaging in critical discourse with other Jews, and how listening to Palestinian stories can illuminate the dehumanizing conditions.', 43, '2025-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 93, 'July 29, 2025 - Jenny Slate', 'Desi Lydic covers Trump opening a new golf course in Scotland before tending to his side hustle of president of the United States to strike a new trade deal with the E.U., which will finally bring product prices to... another all-time high? Plus, Michael Kosta and Grace Kuhlenschmidt take advantage of the government''s latest workplace policy: Take Your God to Work Day. Ever wonder what happens when 911 calls YOU? In this edition of "Everything Is Stupid," Ronny Chieng roasts the 911 dispatcher who messed with a real-life Karen by awarding her a Booby Prize for incessant calling, and suffered the consequences. Actor Jenny Slate joins Desi Lydic to discuss her Emmy-nominated role in "Dying for Sex." They talk about the show''s powerful story, based on a podcast about a woman going through Stage 4 breast cancer (portrayed by Michelle Williams), and her experiences playing the woman''s best friend, Nikki.', 25, '2025-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 94, 'July 30, 2025 - Alison Brie & Dave Franco', 'In another installment of The Worst Wing, Desi Lydic tackles Lee Zeldin telling everyone in the EPA to be more chill about climate change, Marco Rubio lighting a birth control bonfire, and Kristi Noem finding another animal to scare. Plus, Pete Hegseth''s got a new addiction: polygraph testing Pentagon insiders to see who''s talked shit about him. From his humble beginnings in Newark to his scrappy days in Boston, Joe Rogan has always pushed his brains to the limit. Rogan''s stand-up comedy led him to a career in television, eventually inspiring him to start his own podcast where he could ask the really important questions, like, "Wouldn''t it be crazy if a wolf wore a fedora?". This is The Daily "Showography" of Joe Rogan. Actors and producers Alison Brie and Dave Franco sit down with Desi Lydic to discuss starring in the new horror movie "Together".', 28, '2025-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 95, 'July 31, 2025 - Tony Hale', 'Desi Lydic takes on the only story big enough to eclipse the Epstein files: Sydney Sweeney''s controversial denim ad. Public pushback over the ad''s supposed white supremacy undertones has the GOP spinning out of control, while Megyn Kelly rebuilds the glass ceiling with accusations that America is jealous of Sweeney''s "hotness." Trump''s association with Jeffrey Epstein has been all over the news lately, but Jordan Klepper knows from years of talking to MAGA that if Trump does come out in the files, we can expect a very rational response. Emmy Award-winning actor and producer Tony Hale talks to Desi Lydic about his new film, "Sketch," sharing how the film''s story about a child''s drawings coming to life was inspired by writer-director Seth Worly''s sister, and how the movie can open up conversations for adults and kids alike about the importance of expressing emotions.', 27, '2025-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 96, 'September 8, 2025 - Spike Lee', 'Rumors have been swirling about the American president''s potentially failing health, and between his cankles, a tribute video from the White House, and global leaders throwing Nobel Prize nominations at the guy like he''s the oldest Make-A-Wish kid in the world, Jon Stewart can''t help but wonder: IS Trump dying? Academy Award-winning filmmaker Spike Lee joins Jon Stewart to discuss his new movie, "Highest 2 Lowest", in cinemas and now streaming on Apple TV+. They talk about Lee''s experiences over the years working with the film''s star, Denzel Washington, the high-stakes story, what he learned from his parents growing up in Brooklyn, and if it''s the Knicks'' year.', 35, '2025-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 97, 'September 9, 2025 - Patrick McEnroe', 'With Trump''s cryptic and sexually suggestive birthday card to Epstein revealed, Michael Kosta dives into a lazy cover-up by the White House, a possible quid pro quo to buy Ghislaine Maxwell''s silence, and an excuse to blame it on Biden. Michael Kosta and Ronny Chieng spar over the biggest headlines in sports, including drunk crowds at the U.S. Open, Jalen Carter''s spit-tacular start to the NFL season, and AI coming for jobs in minor league baseball. Former professional tennis player and International Tennis Hall of Fame president, Patrick McEnroe, and fellow former pro tennis player, Michael Kosta, dissect last week''s U.S. Open, which McEnroe commented on for ESPN. McEnroe discusses the men''s final between Carlos Alcaraz and Jannik Sinner and how the two powerhouses are pushing each other and the sport forward, the importance of players like women''s finalist Amanda Anisimova being open about their mental health.', 40, '2025-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 98, 'September 10, 2025 - Michael Grunwald', 'Michael Kosta breaks down Trump''s Department of War, a.k.a. the new billion-dollar nickname for the Department of Defense, and Josh Johnson is hyped up for the president to go to war with America''s biggest enemy: America. Thanks to Trump, Canadian tourism is way down, with many citizens scared to visit the U.S. So Jordan Klepper visits the city of Burlington, VT, to see just how desperate Vermonters are to win back the Canucks and drink some beer. Michael Grunwald, award-winning journalist and bestselling author of "We Are Eating the Earth: The Race to Fix Our Food System," sits down with Michael Kosta to discuss how agriculture is our biggest climate issue. They discuss the deforestation caused by pasture for cattle, how to make more calories on less acreage, the meat and energy alternatives providing hope, and how to maintain appreciation for farmers while searching for a better way.', 33, '2025-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 99, 'September 11, 2025 - Rainn Wilson', 'Michael Kosta dives into the aftermath of Charlie Kirk''s assassination, including Trump''s inflammatory response, bizarre takes in the media, and a predictable partisan blame game, and reflects on what we can learn from violent tragedies on the anniversary of 9/11. Why are governments around the world so concerned with bovine blasts? Grace Kuhlenschmidt dives into the science of livestock emissions by speaking with Washington state Rep. Lisa Parshley, who is hoping to start a tax on cow farts, farmer Jake Yancey, who doesn''t give a fart, and the OG experts on burps: children. "If we simply turn to compassion, and really harness it as an energy, we can affect some transformation." Actor Rainn Wilson sits down with Michael Kosta to discuss his new movie, "Code 3."', 31, '2025-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 100, 'September 16, 2025 - Jay Duplass & Michael Strassner', 'Desi Lydic unpacks the toxic internet landscape in the aftermath of Charlie Kirk''s assassination, where members of the Trump administration have called for people to lose their jobs for criticizing Kirk, the attorney general has seemingly forgotten the meaning of free speech, and Trump only wants to discuss White House renovations. Plus, Michael Kosta offers some solid reasoning for going back to the ‘80s. After siccing the National Guard on Washington D.C., Trump is chomping at the bit to militarize other Democrat-run U.S. cities, including New York. Grace Kuhlenschmidt asks New Yorkers if they think the National Guard has what it takes to make it in the Big Apple. "I''m so happy I''m here, because I almost missed it." Michael Strassner and Jay Duplass sit down with Desi Lydic to discuss the critically acclaimed independent film they co-wrote, "The Baltimorons,".', 31, '2025-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 101, 'September 17, 2025 - Cooper Hoffman', 'Desi Lydic covers Congress grilling Kash Patel over buried details of the Epstein files and Trump''s attempt to put an ocean between himself and the Epstein controversy via a castle-filled king cosplay in the U.K. Lewis Black has learned what a Labubu is, and he''s pissed. He roasts every aspect of Labubu culture, from Labu-baptisms to toy theft, and offers Americans an equally stupid doll alternative to waste their money on. Actor Cooper Hoffman sits down with Desi Lydic to discuss his role in the new film, "The Long Walk." They talk about how Stephen King''s dystopian novel feels relevant today, the physical challenges of walking 15 miles a day while acting, learning to lean into humanity with Hoffman''s co-star David Jonsson, and the importance of having people walk beside you through life.', 24, '2025-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 102, 'September 18, 2025 - Maria Ressa', 'A humble, obedient Jon Stewart heaps praise upon America''s Glorious Leader, Donald J. Trump, and provides an FCC-approved refresher on the rules of free speech in the wake of Jimmy Kimmel''s suspension. Plus, the TDS News Team serenades the world''s greatest, large-penised leader. "It''s both deja vu and PTSD." Maria Ressa, Nobel Peace Prize-winning journalist and author of the book "How to Stand Up to a Dictator," sits down with Jon Stewart for a conversation about Trump''s authoritarian attacks on free speech in the wake of Disney taking Jimmy Kimmel off the air in fealty to the president and his hand-picked FCC Chair. Ressa, who in 2020 was jailed in the Philippines for her journalism criticizing the country''s former president Rodrigo Duterte, warns about the similarities between the dictatorship she lived under and the Trump administration.', 43, '2025-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 103, 'September 22, 2025 - Jacinda Ardern', 'Jon Stewart unpacks Jimmy Kimmel''s return to television amid outcry over his suspension, a sign of the times in an era where President Trump isn''t even hiding his flagrant attacks on free speech, retaliation against his political enemies, and the brazen corruption in his administration. "We need more leaders who are willing to be humans while they''re in the job." Jacinda Ardern, the former Prime Minister of New Zealand, sits down with Jon Stewart to discuss her experiences in office, which she chronicles in her memoir, "A Different Kind of Power," and upcoming HBO documentary, "Prime Minister." They discuss making progress on issues like child poverty and climate change while also managing a domestic terrorist attack and the Covid pandemic. She emphasizes the importance of politicians spending their political capital on "doing the right thing," the globalization of political polarization, and how it''s a courageous act to be optimistic in these times.', 42, '2025-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 104, 'September 23, 2025 - John Fugelsang', 'Jordan Klepper recaps Trump and RFK''s latest pseudo-scientific bombshells: Tylenol causes autism, vaccines flood baby bodies, and the Amish are leading the world in modern medicine. Also, which Daily Show correspondents made the list for Rapture Tuesday? Jordan Klepper dives into Trump''s appearance at the United Nations General Assembly, where global diplomacy and updates on Ukraine played second fiddle to his grudge against an out-of-order escalator. "Jesus''s movement was about humility, it was about service to others, it was about uplifting the marginalized, not about total right-wing domination". John Fugelsang, presenter of "Tell Me Everything" on SiriusXM Progress and author of the New York Times Bestseller "Separation of Church and Hate", talks to Jordan Klepper about how MAGA and the far-right have wrongly co-opted Christianity as a cloak for authoritarianism and bigotry.', 30, '2025-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 105, 'September 24, 2025 - Sebastian Murphy', 'Jordan Klepper covers how Putin''s fuckboi antics pushed Trump into Ukraine''s arms, while Grace Kuhlenschmidt and the rest of MAGA unravel a sick plot to prank the president in a conspiracy that starts at the bottom of a malfunctioning U.N. escalator and goes all the way to the top. Sebastian Murphy, the frontman of Swedish punk band Viagra Boys, sits down with Jordan Klepper to talk about their latest album, "viagr aboys." They discuss how the band got its name, the Mariah Carey song that brought them together, moving to Sweden after growing up in America, and the band''s satirical and often hypermasculine-parodying resistance music that lets audiences know "freaks are welcome." Swedish post-punk band Viagra Boys performs "Pyramid of Health" from their latest album, "viagr aboys."', 27, '2025-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 106, 'September 25, 2025 - Regina Hall', 'Jordan Klepper dives into Trump''s latest adventures in pettiness, from framing Biden''s autopen signature among portraits in the Presidential Walk of Fame to framing James Comey for crimes despite getting a political assist from the former FBI director in 2016. Also, Troy Iwata explains how Lindsey Halligan''s appointment to U.S. Attorney despite her lack of experience is giving major "Legally Blonde" vibes. Trump and MAGA want to whitewash the history of slavery in America from Smithsonian museums because they think racism is talked about too much, but Leslie Jones says we''re actually not talking about racism enough. She shows how racism persists in the country, seen everywhere from train cars to Congress, and explains how racism won''t be solved unless everyone gets a better education about Black people in the classroom and in the media. Actress Regina Hall joins Jordan Klepper to talk about her new movie, "One Battle After Another", directed by Paul Thomas Anderson.', 30, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 107, 'September 29, 2025 - Jill Lepore', 'After a string of mass shootings across the U.S., America swaps out "thoughts and prayers" for a left vs. right blame game, Republicans hypocritically criticize the Democrats'' "violent rhetoric," and Trump escalates a nonexistent problem by deploying troops to Portland. "Just because we''ve written [the laws] down doesn''t mean that we can''t aspire to make things better." Harvard law professor and staff writer at The New Yorker, Jill Lepore, joins Jon Stewart to discuss her new bestselling book, "We the People: A History of the U.S. Constitution." She points to the years-long process of trial and error that went into writing the Constitution as an example of how the document was designed with the intention to be changed and improved upon, and emphasizes the foundational right to amend the document as Americans see fit.', 43, '2025-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 108, 'September 30, 2025 - Cristela Alonzo', 'Ronny Chieng recaps Pete Hegseth and Donald Trump''s sudden gathering of top military leaders, where the president announced his intention to use Democrat-run cities as training grounds for the National Guard, and where Secretary of War Pete Hegseth fat-shamed troops, hawked his book, and made cringey jokes. Ricky Velez unpacks how the ubiquity of online sports betting has become a problem for Las Vegas casinos and an even bigger problem for American men, and how, instead of trying to protect people from these billion-dollar gambling apps, Trump is just taking a cut for himself. Comedian Cristela Alonzo sits down with Ronny Chieng to discuss comedy institutions, the American dream, and her new Netflix special, "Upper Classy." They talk about paying homage to comedy and participating in its evolution, using joy as an act of resistance, how politicians focus on the middle class and forget the lower class, and what she learned growing up in Texas with an undocumented mother.', 35, '2025-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 109, 'October 1, 2025 - Benny Safdie', 'With a government shutdown fully in effect, Ronny Chieng takes a look at Trump''s confusingly racist AI videos of Democratic leaders and braces for how the shutdown will impact everything from the TSA to national parks. Plus, Josh Johnson reports live from the Grand Canyon, which is already turning into a literal shithole. Michael Kosta has the hottest moolah-making tips for how to capitalize on recent economic headlines, like adults ordering from the kids'' menu, the tooth fairy short-changing kids, and a recall on exploding Prosecco bottles from Costco, in the latest installment of "Ko$ta Doing Business". Writer and director Benny Safdie talks to Ronny Chieng about the inspiration and creative process behind his new film, "The Smashing Machine", which is based on the life of MMA fighter Mark Kerr.', 32, '2025-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 110, 'October 2, 2025 - Kevin Nguyen', 'Ronny Chieng covers Day 2 of the government shutdown: Republicans and Democrats are dueling via sombrero and cat memes, Trump is going after blue cities with a vengeance, and his administration is surprisingly joyful. Plus, Michael Kosta joins with expert analysis of MAGA''s unconventional shutdown strategy. White House advisor Thaddeus Mandible Crowley excavates America''s ancient laws to justify whatever insane idea jumps into Trump''s head, be it fornicating for national security or banning uggos. Author and features editor at The Verge, Kevin Nguyen, sits down with Ronny Chieng to talk about his new book, "Mỹ Documents: A Novel". They discuss the story''s timely premise about "a far-fetched dystopian future where the government is detaining people for no reason", the title''s nod to the Vietnamese language, the importance of learning your family''s history, and how the book tackles nuanced ideas around Asian American identity.', 31, '2025-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 111, 'October 6, 2025 - Tristan Harris', 'Jon Stewart dives into the emerging effects of the government shutdown, the battle over healthcare that has Republicans and Democrats pointing fingers, and Trump''s delight in using the shutdown to continue steamrolling Democrats and the Constitution. "This does not have to be our destiny." Co-founder of the Center for Humane Technology Tristan Harris sits down with Jon Stewart to discuss how AI has already disrupted the workforce as current iterations of the technology have dropped entry-level work by 13%, tech companies prioritization of their first-to-market stance over product and human safety, and how reliance on AI is stifling human growth.', 45, '2025-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 112, 'October 7, 2025 - Wawa Gatheru', 'Josh Johnson dives into AG Pam Bondi''s refusal to answer questions about Epstein during a fiery Senate hearing, Trump pretending to forget Ghislaine Maxwell''s name while also not ruling out a pardon for her, and the president''s recent obsession with whether he''ll make it to heaven. Plus, Troy Iwata reveals what it really takes to earn an afterlife. Burmese pythons are decimating the ecosystem of Florida''s Everglades, but Amy Siewe, a.k.a. the Python Huntress, is on a mission to take out this slithery problem. Michael Kosta joins her on a python hunt and gives this hero the thankssssss she deserves. Founder and Executive Director of Black Girl Environmentalist, Wawa Gatheru, sits down with Josh Johnson to discuss her organization''s mission to build a pipeline in the climate sector for Black women and gender expansive people to create more environmental equity and provide resources for the next generation of green leaders.', 36, '2025-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 113, 'October 8, 2025 - Anthony Ramos', 'Josh Johnson shares the latest updates on the government shutdown as the Trump administration searches for files on Amelia Earhart, the FAA faces staff shortages due to unpaid workers, Transportation Secretary Sean Duffy lends an unhelpful hand, and the president issues an ominous message to furloughed government workers. Also, Jordan Klepper decodes the president''s apparent taunts. Between women getting trapped in game machines, beloved mascots being arrested in front of children, and joyless, boozeless grown-up arcades, Ronny Chieng lays out how Chuck E. Cheese makes adults act stupid. Broadway star, singer, and actor Anthony Ramos joins Josh Johnson to talk about his new movie, "A House of Dynamite", directed by Kathryn Bigelow. They discuss the intense thriller in which he portrays Major Daniel Gonzalez, a military officer in charge of the battalion that monitors intercontinental ballistic missiles, how he unwound during filming.', 30, '2025-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 114, 'October 9, 2025 - Hunter Prosper', 'Josh Johnson dives into the peace deal Trump brokered between Israel and Hamas, and the president''s heightened focus on a supposedly more dangerous and local enemy: Antifa. As troops menace Portland, Trump uses the Antifa bogeyman to justify military invasion, suspension of habeas corpus, and a bunch of other random agendas. On "Tech Yeah", our expert Grace Kuhlenschmidt breaks down the biggest news in innovation, including the realer-than-life Sora 2 video generation tool, new big-screen It Girl (and AI actress) Tilly Norwood, and the first-ever robot Olympics, where the athletes come pre-programmed with CTE. "What connects us as a species is this emotional experience we''re all going through". Content creator, ICU nurse, and "Stories From a Stranger" author Hunter Prosper sits down with Josh Johnson to discuss his book, inspired by videos in which he interviews strangers about their lives.', 33, '2025-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 115, 'October 20, 2025 - Bernie Sanders', 'Jon Stewart examines the "No Kings" protests that failed to meet Fox News''s violent expectations, why Trump fits the mold of a gold-smeared monarch, and how even the Declaration of Independence foreshadowed Trump''s king-ish antics. "It''s got to be a bottom-on-up revolution, not a top-down." Senator Bernie Sanders sits down with Jon Stewart to discuss his latest book, "Fight Oligarchy." They talk about harnessing the energy of the "No Kings" rallies to build a clear vision for the Democratic party, prioritizing universal healthcare and affordable housing expansion, how Trump has embraced some socialist policies, the danger of corporations and oligarchs regulating the government, and making AI work for working people.', 44, '2025-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 116, 'October 21, 2025 - Catherine Bracy', 'Michael Kosta checks in on Trump''s latest White House makeover, which includes demolishing the First Lady''s quarters to build a gigantic ballroom in the East Wing. Plus, while a Democrat apologizes for problematic Reddit posts, Trump''s nominee for special counsel blames his pro-Nazi text messages on AI, and Ronny Chieng teaches politicians how to get away with racism. From Fox News to Trump, everyone on the Right is calling NYC mayoral candidate Zohran Mamdani a "communist." Desi Lydic sits down with Joe Sims, the co-chair of the Communist Party USA, to discuss how we''re using the C-word all wrong. Catherine Bracy, author of "World Eaters: How Venture Capital is Cannibalizing the Economy," talks to Michael Kosta about the evolution of venture capital, from its origin as a mid-20th-century funding solution for risky companies with big potential for technological advancement, to the harmful economic backbone of the tech industry it has become today.', 36, '2025-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 117, 'October 22, 2025 - Ryan Holiday', 'While thousands of government employees are working without pay during the ongoing government shutdown, Donald Trump is squeezing $230 million from the Department of Justice as compensation for the "damage" of being federally investigated. Michael Kosta breaks down the conflict of interest that''s so bad, it even has legal experts saying "duh," and Troy Iwata gives a peek into what new grifts the president is cooking up in his corruption lab. Lewis Black takes a look at the new health craze tricking Americans into thinking they can have their protein-filled cake and eat it too.  Ryan Holiday, creator of "Daily Stoic" and author of "Wisdom Takes Work," sits down with Michael Kosta to discuss teaching children Stoicism by example, how wisdom calibrates courage, discipline, and justice, the difference between schooling and true education, and the spectrum of Stoicism in public figures from Abraham Lincoln to Elon Musk.', 35, '2025-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 118, 'October 23, 2025 - Jeff Tweedy', 'Michael Kosta dives into the alleged involvement of Portland Trail Blazers head coach Chauncey Billups and Miami Heat star Terry Rozier in illegal gambling schemes. Plus, Donald Trump continues to defend the construction of his mega-sized White House ballroom as he fully demolishes the East Wing. And Josh Johnson thanks the contractor-in-chief on behalf of waltz-loving podcast bros everywhere. Jeff Tweedy, Grammy award-winning frontman of the band Wilco and bestselling author, sits down with Michael Kosta to discuss his new solo album, "Twilight Override," named to evoke his feeling of getting older and watching a world that "appears to be getting darker." Tweedy also discusses why he''s glad to have spent his formative years as a musician in the midwest, his theory that repressed trauma after Covid is one cause of present-day chaos, and the need for everyone to spend less time on their phones and more time with people who love them.', 30, '2025-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 119, 'October 27, 2025 - Zohran Mamdani', 'After Trump echoes a complaint that he''s unappreciated by Americans for his "sacrifices," Jon Stewart looks at all the things the president has accomplished without getting proper recognition, like going against protocol to tear down the East Wing of the White House for an ostentatious ballroom, or blowing up Venezuelan boats without due process. Jon also takes a look at the Republicans properly eating s**t for the president and determines that a third term is the only appropriate show of gratitude for this poor little billionaire. New York City mayoral candidate Zohran Mamdani sits down with Jon Stewart to discuss building a campaign on delivering politics that "aspire for more than what you''re living through," ensuring his tax plans aren''t just popular but precedented, taking safety beyond the NYPD to job and housing security, reaching the hearts of young voters with inviting rhetoric, and whether the days of endorsements deciding elections have come to an end.', 40, '2025-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 120, 'October 28, 2025 - Lucy Dacus', 'Desi Lydic breaks down Trump''s trip to Japan, which included a shockingly firm handshake from new Prime Minister Sanae Takaichi, decadent gifts to win the president''s heart, and a quick survey for the U.S. Navy about magnets. Plus, Troy Iwata is pretty sure Trump''s embarrassing antics in Tokyo are the worst things America has ever done to Japan. Grammy Award-winning musician Lucy Dacus joins Desi Lydic to discuss "Forever Is a Feeling: The Archives," an expanded edition of her latest record, which has been called the "most romantic album of 2025." They talk about what makes a good love song, why writing this music felt like therapy, whether fame has impacted her creative process, and how her song "Best Guest" inspired her to get ordained and perform weddings on tour at a time when the Trump administration is threatening LGBTQ+ unions. Grammy Award-winning musician Lucy Dacus joins Desi Lydic to discuss "Forever Is a Feeling: The Archives".', 30, '2025-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 121, 'October 29, 2025 - Aubrey Plaza & Dan Murphy', 'Desi Lydic covers Trump''s state visit to South Korea, where he was honoured with a "Yas King" rally, a golden crown, and the unofficial U.S. presidential anthem, "YMCA". Meanwhile, millions of Trump''s constituents face a hunger crisis as SNAP benefits run out of funding due to the never-ending shutdown, and the GOP pretends there''s nothing they can do about it. Michael Kosta has a list of billionaire sugar daddies who are happy to step in and help, as long as Americans don''t mind getting a little freaky. Democrats have been riding high since the success of the "No Kings" protests and the emergence of Democratic prospects like Zohran Mamdani. But why is the Democratic Party so afraid to harness this energy? Lenard McKelvey (aka "Charlamagne Tha God") breaks down how to swap this tired system for an energetic change. Emmy-nominated actor Aubrey Plaza and writer-producer Dan Murphy join Desi Lydic to discuss their new children''s book, "Luna and the Witch Throw a Hallowe''en Party".', 29, '2025-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 122, 'October 30, 2025 - Justine Lupe', 'Desi Lydic recaps Trump''s meeting with Chinese President Xi Jinping, where they had an unsurprisingly fruitless discussion about tariffs. Then, after Marjorie Taylor Greene calls out the GOP''s lackluster response to the government shutdown and demands the release of the Epstein files, Desi is haunted by the question: Does she (gulp) agree with Marjorie Taylor Greene? Ronny Chieng takes a look at Neo, the new robot maid designed to help with everyday tasks, such as cracking walnuts, loading the dishwasher like a drunk person, and giving a remote human operator a glimpse into your home. Justine Lupe sits down with Desi Lydic to discuss her role in the hit Netflix series, "Nobody Wants This." Lupe dives into playing codependent sisters with Kristen Bell, navigating her character''s ambiguous dynamics with Timothy Simons, being adored by her partners on and off screen, and what her girlfriends have taught her about love and strength.', 31, '2025-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 123, 'November 3, 2025 - Joe Manchin', 'Between Trump throwing a lavish "Great Gatsby"-themed party on the night that SNAP benefits ran out for millions of Americans, dragging his feet to open court-ordered emergency funding for food stamps while throwing billions of bailout dollars at Argentina, and the GOP''s general racism-tinged disdain for SNAP recipients, Jon Stewart seriously doubts that the president''s "big heart" goes out to anyone but himself and the toadies on his VIP list. Former U.S. senator and West Virginia governor Joe Manchin sits down with Jon Stewart to discuss his memoir, "Dead Center: In Defense of Common Sense." They talk about whether centrism exists in the Trump era, Manchin''s experience working across partisan lines in the Senate, the state of the Democratic Party in West Virginia, why he never voted for a government shutdown, and how he thinks the country can move forward.', 50, '2025-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 124, 'November 4, 2025 - Sanna Marin', 'As Election Day wraps up, Jordan Klepper recaps the suspenseful New York City mayoral race infused with Islamophobic fearmongering of Zohran Mamdani and an uphill battle for Andrew Cuomo, culminating in an 11th-hour scandal over a Billy Joel song. Also, Ronny Chieng reports that Cuomo is feeling confident, thanks to his lucky O.J. Simpson-style Ford Bronco and other criminal-lookalike charms. The eyes of the world seem to be on the New York City mayoral race, so Grace Kuhlenschmidt conducted her own Times Square exit poll to ask non-New Yorkers which candidate they endorse for an election they can''t vote in. "There''s always hope if there''s action". Former Prime Minister of Finland, Sanna Marin, talks to Jordan Klepper about her new memoir, "Hope In Action".', 33, '2025-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 125, 'November 5, 2025 - Scott Galloway', 'Jordan Klepper dives into the big wins for Democrats across the country last night, including in the hotly contested mayoral race in New York City, which ended in a historic victory for Zohran Mamdani that sparked threats of a mass exodus of Cuomo supporters from the city. Plus, nobody is more eager to get out of the city than Eric Adams, the guy who''s still in charge at City Hall, so The Daily Show takes a final look back at the legacy the outgoing mayor is leaving behind. In the Art of the Altercation, Desi Lydic unpacks Donald Trump''s long and tumultuous relationship with New York, a home he once called "the greatest city in the world," but now, as president, thinks is a crime-infested hellhole that needs to be punished. NYU professor, co-host of the Pivot podcast, and bestselling author, Scott Galloway, joins Jordan Klepper to discuss his latest book, "Notes on Being a Man."', 33, '2025-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 126, 'November 6, 2025 - Ethan Hawke', 'Trump plays dead fish during a medical emergency in the Oval Office, the White House''s Ozempic announcement has Americans losing 400 pounds each, the president finds a new enemy in Nigeria, and Jordan Klepper reports on shutdown-induced flight cancellations that will have people walking home for the holidays. On another episode of Sports War, Jordan Klepper and Ronny Chieng fight over whether the Dodgers deserved to win the World Series, the integrity of the NBA amid a sports gambling scandal, and an Aussie darts player whose dirty nickname sparked controversy. Academy Award-nominated actor Ethan Hawke sits down with Jordan Klepper to discuss his new movie "Blue Moon," which takes place on an "important night in art history," after Lorenz Hart attends the premiere of his former collaborator''s musical, "Oklahoma!"', 31, '2025-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 127, 'November 10, 2025 - Rep. Chris Deluzio & Rep. Pat Ryan', 'In the wake of Democrats'' decision to end the government shutdown, Jon Stewart returns to his prediction that they were going to piss away last week''s hard-earned electoral victories. With nothing to gain from caving, momentum on their side, and a deeply unpopular president, Jon compares the Democrats to the New York Giants, who at least had the good sense to fire their coach. "A lot of politicians who voted to send guys like us to places like Iraq, spending trillions, all of a sudden want to count pennies when it''s time to care for the veterans they sent to fight." Rep. Chris Deluzio of Pennsylvania and Rep. Pat Ryan of New York, who are both Iraq war veterans and members of the House Armed Services Committee, talk to Jon Stewart about how the Trump administration prioritizes a trillion dollar military budget over the livelihood of veterans and service members.', 44, '2025-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 128, 'November 11, 2025 - Rob Riggle', 'The Democrats'' popular affordability platform has Trump jealously weaving plans for 50-year mortgages and socialist-seeming tariff rebates, and Josh Johnson deciphers how the "money man" president thinks $2,000 checks will solve everything. On this edition of Who Won It Best, Desi Lydic and Troy Iwata dive into the crèmè de la crème of awards season: the Fox Nation Patriot Awards, where Sean Hannity tortured the crowd with his singing, Mike Waltz got an adoring shoutout, Melania Trump plugged her Amazon flick, and Jason Aldean shined as the biggest star they could muster. Actor, comedian, former Daily Show correspondent, and U.S. Marine Corps veteran Rob Riggle joins Josh Johnson to discuss his memoir, "Grit, Spit, and Never Quit: A Marine''s Guide to Comedy and Life."', 35, '2025-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 129, 'November 12, 2025 - Jay Jurden', 'Josh Johnson dives into newly released bombshell emails from Jeffrey Epstein that might implicate Trump, considering he referred to the president as the "dog that hasn''t barked." Plus, on the heels of whistleblower revelations that Ghislaine Maxwell''s prison accommodations include puppies and TV time, Ronny Chieng explains why this is all perfectly normal. Nick Offerman holds a microscope to Trump''s "I love farmers" act to expose the policies, corporations, and advancements in processed food that have Americans yearning to eat like Europeans and small farmers struggling to stay afloat. Writer, actor, and comedian Jay Jurden sits down with Josh Johnson to discuss his debut stand-up special, "Yes Ma''am" on Hulu. He shares why his Southern charm prevents him from feeling like a real New Yorker, his experience studying theater at a football school, how studying the dramatic arts helps him stay present on stage, and his favorite jokes that both he and Wanda Sykes have ever written.', 37, '2025-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 130, 'November 13, 2025 - Miguel Pimentel', 'In the wake of new Jeffrey Epstein emails implicating Trump, the GOP unhelpfully backed up the president by releasing 20,000 new Epstein files of their own, and Josh Johnson unpacks new revelations, including the two men''s frenemy relationship and apparent connection to cosmetics heiress Celina Midelfart, as well as conservative pundits like Megyn Kelly''s attempts to downplay the bombshell. Plus, Troy Iwata offers a scathing critique of Epstein''s email grammar. The AI revolution is integrating chatbots like Grok and ChatGPT into all aspects of life, from education to friendship, so Ronny Chieng fights the dumbing effects of AI on college campuses by transforming himself into a real-life chatbot. Grammy award-winning artist Miguel Pimentel talks to Josh Johnson about returning to music after an eight-year break with his new album, "CAOS". Miguel shares how that time of personal reflection and connection to his Mexican heritage informed his new album through celebration of his culture.', 37, '2025-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 131, 'November 17, 2025 - Christiane Amanpour', 'A batch of newly surfaced Epstein emails sparks Trump''s fight-or-flight mode, a diversionary DOJ investigation into the Democrats, and a Fox News crash out as pundits try to downplay the Epstein files. While rumors swirl about a jaw-dropping degree of closeness between Donald Trump and Bill Clinton, Jon Stewart urges the GOP to hold their Epstein sleuthing to the same standard as their investigation into the QAnon Pizzagate conspiracy. CNN''s Chief International Anchor and host of the global affairs program, "Amanpour," Christiane Amanpour sits down with Jon Stewart to discuss how the Epstein scandal has highlighted the importance of truth-based journalism. They talk about using investigative journalism to combat authoritarianism and hold the "invincible" elite accountable, and how the "drip, drip, drip" story of the Epstein files has fed itself and divided MAGA.', 45, '2025-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 132, 'November 18, 2025 - Mitsuyo Miyazaki aka "Hikari"', 'An (almost) unanimous vote in the House to release the Epstein files has Trump reversing his opposition to save face, Marjorie Taylor Greene looking like she''s severed from MAGA, and Saudi Arabia''s visiting crown prince getting a pass for murder. Ronny Chieng reflects on the road to releasing the Epstein files and Trump''s key to uncovering the elite sex trafficking scandal: "Don''t talk about it." You thought holiday travel was miserable? Try being an air traffic controller. Leslie Jones breaks down how the people with one of the most important jobs in America are being treated with Spirit Airlines-level disrespect and asks airlines to quit thinking so much about luxury perks and to start supporting these vital employees with better technology, better pay, and maybe some of that TSA-confiscated cocaine. Writer, producer, and director Mitsuyo Miyazaki aka "Hikari" joins Ronny Chieng to discuss her new movie, "Rental Family".', 34, '2025-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 133, 'November 19, 2025 - Sean Sherman', 'Ronny Chieng dives into Trump''s friendly meeting with Saudi Crown Prince MBS despite the president''s famously anti-Muslim past, and covers the latest updates on the release of the Epstein files, which was quickly approved by the House and Senate and now seemingly has the endorsement of the president himself. That said, Jordan Klepper offers a few reasons why we might not like what we see. Grace Kuhlenschmidt tackles Russia''s first face-planting robot, an AI version of your dead granny, and does America want music that''s fully AI-generated? Tech yeah, they do! James Beard award-winning chef Sean Sherman sits down with Ronny Chieng to discuss his new book "Turtle Island: Foods and Traditions of the Indigenous Peoples of North America." They talk about using food as a tool for promoting curiosity and empathy, focusing on Indigenous and healthy foods at his restaurant.', 33, '2025-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 134, 'November 20, 2025 - Sebastian Maniscalco', 'Ronny Chieng dives into Trump''s signing of the Epstein Files Transparency Act, Pam Bondi''s shell-shocked statements about a new Epstein investigation aimed at Democrats, U.S. Attorney Lindsey Halligan''s monumental screwup in the Comey case, Grok''s ego-stroking of Elon Musk, and Melania Trump''s unlikely speech to Marines about AI warfare. Plus, Michael Kosta looks into Transportation Sec. Sean Duffy''s current problem with air travel: bad manners. America might be getting sick of RFK Jr. as health secretary, but much like the worm in his brain, he doesn''t appear to be going anywhere. While you won''t find his brand of non-professional medical advice on "Grey''s Anatomy" or "The Pitt," you can find it on a bold new medical drama: RFK Hospital. Record-breaking comedian, actor, and podcast host Sebastian Maniscalco sits down with Ronny Chieng to discuss his latest Hulu special, "It Ain''t Right."', 32, '2025-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 135, 'December 1, 2025 - Elizabeth Kolbert', 'Trump spent the weekend celebrating Thanksgiving the traditional way: abusing reporters, calling Tim Walz the R-word, and bragging about his "perfect" MRI score. Plus, while the president spins a National Guard shooting for his anti-immigrant agenda, Jon Stewart slams the double standard of criminal justice for immigrants and J6 insurrectionists. Pulitzer Prize-winning author and staff writer at The New Yorker, Elizabeth Kolbert, sits down with Jon Stewart to discuss her latest book, "Life on a Little-Known Planet: Dispatches from a Changing World." They talk about matching the awareness of climate problems with an effort for change, humans wasting 10,000 years of "climate stability" by inventing ways to disrupt it, the Trump administration''s climate policy regression, and how developing countries are reaping both financial and environmental gains by leaning into clean energy.', 43, '2025-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 136, 'December 2, 2025 - Nikki DeLoach', 'Desi Lydic covers Melania getting into the mandatory Christmas spirit by decorating the un-bulldozed parts of the White House, Kash Patel refusing to do his job without a big girl FBI jacket, and Pete Hegseth responding to possible war crimes charges by throwing his admiral and a cartoon turtle under the bus. Plus, Jordan Klepper wants YOU to join Hegseth''s scapegoat army. Michael Kosta drops the hottest tips for a cash-tacular Christmas: Skip expensive Christmas gifts by converting religions, swap pasta for wringing sauce cloths, and gift an AI teddy bear that covers sex ed. Actor and philanthropist Nikki DeLoach sits down with her friend Desi Lydic to discuss starring in the latest Hallmark movie, "A Grand Ole Opry Christmas," how working on the film was a healing experience for her after losing her father, and why Hallmark movies seem to resonate with viewers during hard times.', 37, '2025-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 137, 'December 3, 2025 - Asi Wind', 'Josh Johnson tracks Trump''s flimsy war on narco-terrorism, from threatening more war-crimey attacks on suspected Venezuelan drug traffickers to pardoning the Honduran ex-president who smuggled enough cocaine to get the whole world high, and Troy Iwata just wants a clear answer: drugs good or drugs bad? Is the AI bubble at risk of popping? Ronny Chieng sits down with Peter Wildeford of the Institute for AI Policy and Strategy to investigate the risks of AI taking our jobs and tanking our economy as the "circle jerk" of AI companies goes all-in on robots. "People have a desire to see magic, I''m only there to help them." Award-winning magician and mentalist Asi Wind talks to Josh Johnson about his "More Than Magic" U.S. and Australia tour, the trick that (literally) sparked his passion for the craft, and why he sees magic as a collaboration with his audience. Plus, Wind treats Josh Johnson to a few mind-blowing tricks.', 36, '2025-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 138, 'December 4, 2025 - Ken Casey', 'Images of Epstein''s island reveal a penchant for creepy decor and a commitment to oral hygiene, Pete Hegseth gets cagey about turning over his phone for the Signalgate investigation, the Pentagon''s press team is replaced by MAGA personalities, and Jordan Klepper investigates Trump''s commitment to being labeled a "president of peace," signage and all. Afraid of the woke leftists'' war against Christmas? Keep the sanctity of the holiday season alive with the brand-new Trump Tinsel, made from recycled shreddings of the Epstein files. The president promised he was going to release them, but he never said how! Frontman of the band Dropkick Murphys, Ken Casey, sits down with Jordan Klepper to discuss their latest album, "For The People." They talk about the roots of punk in political activism, getting inspiration from bands who sang about Reagan, Bush, and the Queen of England.', 30, '2025-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 139, 'December 8, 2025 - Malala Yousafzai', 'Trump contradicts his phony FIFA peace prize by cranking up the heat on military action in Venezuela, a country Newsmax host Greg Kelly couldn''t find on a map, and Jon Stewart gets an assist from The Daily Show archives and a time-traveling Rob Corddry to show how MAGA''s drumbeat for war with Venezuela is Iraq all over again. "True bravery is still doing what you believe in, even when you''re scared." Malala Yousafzai, a Nobel Peace Prize laureate, education activist, and bestselling author, returns to The Daily Show to chat with Jon Stewart about her new memoir, "Finding My Way." They talk about how much her life has changed since she first visited the show at 16, including graduating college and getting married, and how she came to realize she doesn''t have to be perfect. She also opens up about managing mental health and societal projections while pursuing activist work and the school for women she founded in Pakistan, which just graduated its first-ever class.', 45, '2025-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 140, 'December 9, 2025 - Cory Doctorow', 'Ronny Chieng covers the latest on the Trump administration''s petty changes to free-entry days at national parks, the president''s promise to bail out farmers after f**king up the economy, Melania''s attempt to spread some yuletide cheer, and Sean Duffy''s Department of Transportation press conference that turned into a d**k-measuring contest against RFK Jr. On another edition of Who Won It Best, Desi Lydic and Troy Iwata recap the FIFA World Cup Draw and Peace Prize Ceremony, the biggest award show you''ve never heard of, where the balls were mingled, the Village People performed the "YMCA," and Trump received a trophy, medal, and certificate before jetting over to the Kennedy Center Honors to make KISS''s big night all about himself. Journalist, internet activist, and author Cory Doctorow talks to Ronny Chieng about the concept behind his latest book, "Enshittification," which breaks down how tech giants made the internet worse for everybody by locking in users only to turn on them.', 38, '2025-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 141, 'December 10, 2025 - Annie Leibovitz', 'Desi Lydic catches a Fox News closed caption writer''s "minor" Freudian slip during Trump''s economic rally, an event that focused less on affordability and more on Joe Biden. Plus, Michael Kosta explains why the president has been lashing out at female reporters so much lately: he''s going through man-o-pause. TikTok''s biggest trends in 2025 had "6-7" becoming the word of the year, high school seniors cosplaying assassins, people damaging property Kool-Aid Man-style, and Lewis Black wondering what the fuck is wrong with our society. Legendary photographer Annie Leibovitz joins Desi Lydic to discuss her powerful new collection of career-spanning work titled "Women". They talk about breaking stereotypes of pregnant women with Demi Moore''s Vanity Fair cover, capturing Michelle Obama as she found her laid back self after eight years as first lady, her favorite unsmiling image of her mum where the camera "disappears", and Gloria Steinem''s message in the book about women "not going backward".', 35, '2025-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 30), 142, 'December 11, 2025 - Lonnie Thompson', 'The America-Venezuela conflict escalates as the Department of Homeland Security TikTok-ifies the seizing of an oil tanker, and Trump can''t resist taking credit for the "Captain Phillips" moment. Also, the State Department bans the font Calibri for being "too woke", and Michael Kosta unpacks the new beef between conservatives and the font''s creator. This Christmas, gather round from all sides of the political spectrum for the holiday rom-com "Oh, Trolly Night!". Watch online enemies and unlikely lovers come together to find out the answer to the question: Can love Trump hate? Paleoclimatologist at The Ohio State University Lonnie Thompson sits down with Michael Kosta to discuss his groundbreaking work collecting ice cores in tropical glaciers – the subject of the film "Canary," which is available to stream for free on YouTube over the holidays.', 0, '2025-12-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')), 31, 'Season 31', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 1, 'January 5, 2026 - Sen. Mark Kelly', 'Jon Stewart dives into the Trump administration''s abduction of Venezuelan President Nicolas Maduro, Trump''s collusion with oil companies to exploit Venezuela''s resources, and the emergence of the "Donroe Doctrine" as Trump threatens more international takeovers. Senator Mark Kelly of Arizona, who also served in the Navy as a captain and combat pilot, joins Jon Stewart after news broke that he was being censured by Secretary of War Pete Hegseth for telling U.S. service members to refuse illegal orders. They discuss the president''s "major ego problem," why he stands by his message as the Trump administration continues to levy attacks against free speech, frustrations with Democratic leadership, and the importance of Democrats taking control of the House and the Senate to put President Trump in check.', 43, '2026-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 2, 'January 6, 2026 - Park Chan-wook', 'Ronny Chieng unpacks former Venezuelan President Nicolas Maduro''s abduction and first day in court, where he and his wife got some good couples, time pleading not guilty to cocaine trafficking charges. Meanwhile, MAGA attempts to justify Trump''s intervention by downplaying the episode, citing Christianity, and downright playing the bully. The latest scientific studies show that microplastics are just about everything, and we''re ingesting them at an alarming rate. Thankfully, there''s a new product that''s sure to help us take advantage of all the plastic we''re downing each day — eventually. Legendary Korean filmmaker, Director Park Chan-wook, sits down with Ronny Chieng (without any translation help from Ken Jeong) to discuss his new film, "No Other Choice," which he adapted from an American novel. They discuss what attracted him to this story, which follows a devoted company man who is fired and directs his rage toward his competitors on the job market.', 34, '2026-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 3, 'January 7, 2026 - Stephen J. Dubner', 'Ronny Chieng covers how Trump is taking charge of Venezuela''s oil industry and replacing their old dictator with a new one: himself. Plus, this Venezuela takeover is so much fun, the president adds a bunch of other countries to his To-Be-Overthrown list, including Greenland, and Michael Kosta couldn''t be more excited to be part of Trump''s nation-extorting mafia. Jordan Klepper profiles Benny Johnson, social media star turned White House press commentator, who caught Trump''s eye with his generic vitriol, Russian backing, penchant for plagiarism, and unyielding obsession with Batman.  Stephen J. Dubner, host of "Freakonomics Radio" and co-author of "Freakonomics," sits down with Ronny Chieng to discuss the book''s 20th anniversary edition. They talk about how Dubner and his co-author Steven Levitt wove together storytelling and data to present case studies without imposing their own judgment, and how their publisher, doubtful of the title, liberated them to write the book they wanted.', 37, '2026-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 4, 'January 8, 2026 - Lucy Liu', 'Minneapolis tells ICE to "get the f**k out" after an agent fatally shot a woman, Kristi Noem smears the victim as a terrorist while MAGA decides she deserved it, and Ronny Chieng questions ICE''s PR push to recruit highly aggressive, unqualified agents and unleash them on American cities. Americans are known for spoiling their living pets, but what about the ones who''ve passed? Michael Kosta explores the rising popularity of pet psychics, like Danielle MacKinnon, who claims to have the intuitive ability to communicate with all animals, past and present. Kosta learns about her process, meets her very real clients, and attempts to glean some insight into his relationship with his own dog, Walter. Actor and producer Lucy Liu sits down with Ronny Chieng to discuss her new film, "Rosemead," which is based on a true story about a terminally ill mother and her son. They talk about Liu''s connection with the film and how its themes of mental health and grief affected her.', 38, '2026-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 5, 'January 12, 2026 - Jenin Younes', 'on Stewart digs into Trump announcing himself as Venezuela''s acting president via Wikipedia, dividing Venezuela amongst cooperating oil companies, making a game-time decision to involve himself in Iran, and setting his sights on conquering Greenland so Russia can''t have it. Plus, Trump''s rules for January 6th rioters don''t square with the MAGA rhetoric around the January 7th ICE killing of Renee Good. Civil liberties attorney and co-host of the podcast, "Previously Prohibited," Jenin Younes, joins Jon Stewart to discuss how MAGA''s rewriting of the Minneapolis ICE shooting signals a perpetual escalation in violating civil liberties. They talk about how Trump has transitioned from protecting free speech to supporting censorship, JD Vance''s justification over the legality of the Minneapolis shooting, how the Right''s anti-immigrant rhetoric appeals to working-class Americans'' frustrations, and why ICE is targeting blue states and sanctuary cities while exaggerating their "non-compliance."', 42, '2026-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 6, 'January 13, 2026 - Joachim Trier', 'Jordan Klepper rounds up the latest indiscretions from Trump''s cabinet, including Pete Hegseth adding perfidy to his collection of alleged war crimes, Labor Secretary Lori Chavez-DeRemer bringing back the good old-fashioned political sex scandal, and RFK Jr. making America heart attack again with his upside-down food pyramid, which Troy Iwata breaks down for us. Lenard McKelvey (aka "Charlamagne Tha God") is celebrating MLK Day like it''s his last, because with this president, it might be. Thanks to the Trump administration''s backsliding on the national holiday, MAGA''s disparaging remarks against Dr. King, and Elon Musk''s call for white solidarity, Donald Trump''s birthday is in the running to replace MLK Day. Award-winning director and screenwriter Joachim Trier joins Jordan Klepper to discuss his latest critically acclaimed film, "Sentimental Value." They talk about the influence of early skateboarding films on challenging actors to take risks, developing a cast built on trust.', 29, '2026-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 7, 'January 14, 2026 - Langhorne Slim', 'Donald Trump gives a Ford factory worker the middle finger and delivers a message of "keep protesting" but only for Iranians, immigration raids escalate in Minnesota, ICE engages in blatant racial and accent profiling, and Jordan Klepper highlights the Minnesotans fighting back with music, costumes, and bologna. Musician Langhorne Slim joins Jordan Klepper to talk about his new album, "The Dreamin'' Kind." They discuss the importance of dreamers and creativity, especially during uncertain times, how politics have changed the way his older music resonates, collaborating with Greta Van Fleet, and his mission to make joyful music that''ll have you wanting to "shake it." Langhorne Slim performs "Rock N Roll" from his upcoming album, "The Dreamin'' Kind," which is due to be released on January 16.', 24, '2026-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 8, 'January 15, 2026 - Wagner Moura', 'Jordan Klepper covers the latest on Trump''s "whole milk" antics, the president''s push to take over Greenland that has Europe mobilizing, and Mayor Zohran Mamdani''s burgeoning communist reign in New York City, which has unleashed terrors such as expanded access to childcare and free public restrooms. Grace Kuhlenschmidt breaks down the latest tech from the CES conference: candy that puts voices in your head, razors that botch your haircut for you, robots that can see you but can''t hear you, and a chance to fulfill your dreams of beating up a machine! Actor Wagner Moura joins Jordan Klepper, fresh off his Golden Globe win for his performance in "The Secret Agent". Moura, a Brazilian native, describes how the film, which takes place in 1977 Brazil during a heavy dictatorship, was a way for him and director Kleber Mendonça Filho to process their perplexity after their country''s return to dictatorship values with the election of far-right president Jair Bolsonaro in 2018.', 35, '2026-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 9, 'January 20, 2026 - Artis Stevens', 'After receiving a secondhand Nobel Peace Prize from the real winner, Maria Corina Machado, Trump decides peace is for chumps and doubles down on his plans to take over Greenland, angering both Emmanuel Macron and Emmanuel Macron''s eye. Plus, while Josh Johnson thinks the president''s plan to extort Greenland out of Europe''s hands through tariffs will only hurt Americans, Michael Kosta demonstrates how kicking one''s own ass is the ultimate fighting strategy. Trump still wants Greenland and is threatening our European allies if they don''t go along with his plan, but this story has been brewing for a while. As Jordan Klepper''s recent trip to Norway showed us, the president''s anti-peace reputation has long been the talk of the town. President and CEO of Big Brothers Big Sisters of America, Artis Stevens, sits down with Josh Johnson to discuss the power of mentorship.', 27, '2026-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 10, 'January 21, 2026 - Simu Liu', 'Trump closes out his first year as president (again) with a finger-crushing book of accomplishments while he leans into his goal for Year 2: acquiring Greenland. Josh Johnson tracks how Trump''s mumbling about his need to own "Iceland" in Davos morphed into a vague "concept of a deal" with the president who never hears the word "no." In another edition of Everything Is Stupid, Ronny Chieng details the rise and fall of an alleged scam that anyone with a sane mind could''ve seen coming: former New York City Mayor Eric Adams''s risky unregulated crypto token, which he compared to Betsy Ross before it crashed spectacularly. "The Copenhagen Test" star Simu Liu sits down with Josh Johnson to discuss his new series on Peacock and his upcoming Broadway debut in "Oh, Mary!" He shares what it''s like to portray Mary''s Teacher on stage, the similarities and differences between acting in film and for a live audience, his experience in stunt performance inspired by the greats like Jackie Chan & Jet Li.', 30, '2026-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 11, 'January 22, 2026 - Alexandria Stapleton', 'Josh Johnson gives a progress report on Trump''s first year in office based on his campaign pledges to generate more jobs, make Americans rich, improve healthcare, and protect free speech. Naturally, the only person to benefit from these promises is Trump, who now has everything but a normal-looking hand. Lewis Black takes on Gen Z''s nostalgic penchant for the past and the ridiculous "throwback" fads the younger generation is reviving, including cigarette smoking, "dumb phones" to help them think thoughts, tramp stamps, and the mall. Emmy award-winning documentarian Alexandria Stapleton talks to Josh Johnson about producing and directing the Netflix docuseries, "Sean Combs: The Reckoning," including her shared concern with producing partner Curtis "50 Cent" Jackson not to indict the entire Hip-Hop culture along with the music mogul & how the sense of trepidation among the documentary crew & interview participants has shifted since the release of the series and the arrest of Sean Combs.', 30, '2026-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 12, 'January 26, 2026 - Jason Rezaian', 'After the second murder of a Minnesota ICE protester by federal agents, Jon Stewart breaks down the increasingly unhinged gaslighting from Trump officials who are trying to paint victim Alex Pretti as a "domestic terrorist" & ICE agents as innocent kittens despite clear video evidence to the contrary. As MAGA & Kristi Noem ignore even their precious Second Amendment in their attempts to justify the shooting of a legally armed citizen, Jon points to the real weapon threatening this administration: cameras. Director of Press Freedom Initiatives at The Washington Post, Jason Rezaian discusses the deadly protests in Iran and the importance of collecting details of the Iranian experience despite the impermeable internet blackouts. How Trump''s desire to make a deal with Iran would only empower the current oppressive regime, the benefits of including Iranian dissidents in the U.S. in policy conversations, and the humor that carried Rezaian through his 544-day wrongful prison sentence in Iran.', 43, '2026-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 13, 'January 27, 2026 - Michael Urie', 'Desi Lydic dives into the backlash over the Trump administration''s immigration crackdown in Minnesota: GOPers push back against the DHS''s attacks on Alex Pretti for carrying a legal firearm, Border Patrol Commander Greg Bovino gets a station reassignment and a screen time limit, and Trump resorts to finding Bovino''s replacement via suggestions from "Fox & Friends" host Brian Kilmeade. Plus, Troy Iwata pitches a new look for Greg Bovino to match his demotion. Michael Kosta and Ronny Chieng duke it out on another edition of Sports War, debating who you should root for at the upcoming Super Bowl LX, the merits of "Heated Rivalry" putting NHL on the map, and "Nordick shame" after Olympic Norwegian ski jumpers were suspended for enlarging their crotches. Emmy-nominated actor Michael Urie talks with Desi Lydic about the new season of "Shrinking", his run Broadway, and getting his start on "Ugly Betty," where the legendary Vanessa Williams gave him the agency to take big acting swings.', 35, '2026-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 14, 'January 28, 2026 - Gov. Mikie Sherrill', 'Desi Lydic dives into the Trump administration''s scramble to blame each other for the handling of Alex Pretti''s shooting by federal agents in Minnesota, Trump''s rally against Congresswoman Ilhan Omar, who was attacked at a town hall in the wake of his demonizing rhetoric, and the president''s rollout of Trump Accounts, which he announced alongside MAGA''s newest spokeswoman, Nicki Minaj. In this edition of In My Opinion, Whitney Cummings profiles the Democratic politicians lined up for the 2028 presidential race, from Josh Shapiro to Gavin Newsom, and the quirky penchants for cosplay, veganism, and convicted felons that they bring to the table. New Jersey Governor Mikie Sherrill, who recently became the nation''s first woman veteran to be elected governor, sits down with Desi Lydic to discuss how her time serving in a gridlocked Congress motivated her to run for governor and the difference she''s already seen in her ability to create change.', 36, '2026-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 15, 'January 29, 2026 - Katherine LaNasa', 'Democrats express their outrage over the Trump administration''s immigration crackdown, with Chuck Schumer calling Kristi Noem and Stephen Miller "fucking liars" and Hakeem Jeffries on accidental mute. Plus, Desi Lydic plunges into the world of Melania ahead of her documentary debut, which was produced by Jeff Bezos, directed by disgraced filmmaker Brett Ratner, and created by a crew too ashamed to have their names in the credits. Grace Kuhlenschmidt meets Wisconsin native and snakebite enthusiast Tim Friede, who has built up an immunity to 19 of the most venomous snake species, and learns that doing your own medical research can save lives... when done with the help of a team of medical science experts. Emmy Award-winning actress Katherine LaNasa talks with Desi Lydic about her starring role as Nurse Dana in "The Pitt". They talk about landing a job on her last day of radiation, her experience with ER nurses during treatment, and the insight "The Pitt" gives to broken hospital systems.', 29, '2026-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 16, 'February 2, 2026 - Heather Ann Thompson', 'Trump declares himself "absolved" by the latest release of Epstein files, while Elon Musk''s Christmas wish for a trip to the sex island is put on blast, and Jon Stewart finds himself on Epstein''s list… for documentary voiceovers. Plus, as MAGA continues to shield the president from all accountability, Jon Stewart shines a light on the double standard of sanctuary given to Trump vs. immigrants. Historian and Pulitzer Prize-winning author Heather Ann Thompson sits down with Jon Stewart to discuss her new book, "Fear and Fury: The Reagan Eighties, the Bernie Goetz Shootings, and the Rebirth of White Rage." They talk about how big a figure Bernie Goetz was in 1980s New York, hailed as a "vigilante" for shooting four young Black men on a subway train despite the attack being unprovoked, the story''s parallels to ICE shooting protesters in Minneapolis, the costs of violence, and how these types of injustices paved the way for Donald Trump.', 40, '2026-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 17, 'February 3, 2026 - Paul Rosolie', 'Conservatives amp up their mission to MAGA-fy America by overshadowing Bad Bunny''s Super Bowl performance with Turning Point USA''s own D-list halftime show, and Michael Kosta connects the dots between Trump''s call for Republicans to "nationalize" voting and the president''s never-ending claim that the 2020 election was stolen. Plus, Troy Iwata explains why Trump''s pitch to cancel the midterms is peak comedy. With Amazon''s $40 million documentary about the first lady premiering at the Trump Kennedy Center, Jordan Klepper ventured to Washington, D.C., where he chatted with attendees about director Brett Ratner''s appearance in the Epstein files, whether the film''s purchase was a bribe, and why this is what our country should be focused on right now not Minneapolis. Amazon rainforest conservationist, wildlife filmmaker, and author Paul Rosolie talks to Michael about his latest book, "Junglekeeper: What It Takes to Change the World."', 34, '2026-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 18, 'February 4, 2026 - Patricia Lee aka "Ms. Pat"', 'Michael Kosta dives into Trump''s recent moves to steer the country back on track, which include the release of lame new "America Is Back" hats, telling CNN''s Kaitlan Collins to get over the Epstein files and smile more, & continuing his D.C. makeover by building a massive arch across from the Lincoln Memorial. Plus, Grace Kuhlenschmidt shares further updates on the president''s construction rampage. The state that brought you President Ronald Reagan and Governor Arnold Schwarzenegger offer a thrilling new contender for the White House: Governor Gavin Newsom. Patricia Lee aka "Ms. Pat", comedienne, actress, & co-creator of the hit BET+ series, "The Ms. Pat Show," sits down with Michael Kosta to discuss the show''s fifth season. They talk about fighting through network pulls for the chance to speak out about immigration, portraying a unique-yet-universal mother to viewers, preparing for a doomsday scenario, & learning to believe in herself after being shot, abused, and incarcerated.', 29, '2026-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 19, 'February 5, 2026 - Jon Shenk & Marcus Capone', 'Michael Kosta reports on Trump revealing a supposed secret military weapon called the “Discombobulator,” and the impact of newly released Epstein emails on global figures - Andrew Mountbatten-Windsor facing renewed scrutiny, Sarah Ferguson shutting down her charity, and Bill Clinton preparing to testify before Congress. Despite Trump’s frequent mentions in the files, he remains unaffected. Desi Lydic explores Trump’s long running conflicts with the NFL, from reduced violence to team name changes and halftime shows. A 2014 discussion with Stephen A. Smith even raises the question of whether the NFL helped enable Trump’s rise. Kosta also speaks to director Jon Shenk and former Navy SEAL Marcus Capone about Capone’s experience with the psychedelic treatment ibogaine, highlighted in the Netflix documentary In Waves and War, and his work with VETS, a nonprofit helping veterans access similar therapy.', 32, '2026-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 20, 'February 9, 2026 - Gov. Andy Beshear', 'Jon Stewart calls out MAGA’s quick outrage at anything outside their narrow values—from boycotting Bad Bunny’s Super Bowl show to Trump’s racist social‑media attacks on the Obamas and criticism of a U.S. Olympic skier for mild comments about America. He’s joined by Kentucky Governor Andy Beshear, who discusses how Trump’s tariffs have killed jobs and raised costs, and how recent bills have harmed rural healthcare. They talk about signs of MAGA’s grip weakening in Kentucky, why Democrats should speak more plainly to connect with voters, challenging the administration in court, and focusing on the deeper purpose behind Democratic policies.', 47, '2026-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 21, 'February 10, 2026 - Tim Blake Nelson', 'Jordan Klepper reviews new details from the unredacted Epstein files, noting extensive references to Trump and examining the broader fallout. He covers public backlash toward King Charles, questions faced by Commerce Secretary Howard Lutnick regarding visits to Epstein Island, and scrutiny of paleontologist Jack Horner’s associations with Epstein. Klepper also highlights RFK Jr.’s past field trip with Epstein and Ghislaine Maxwell. In a new Sports War segment, Klepper and Desi Lydic debate major sports headlines, including Bad Bunny’s historic Super Bowl halftime show, a Winter Olympian’s protest against ICE, and a figure skater competing in a Minion costume. Actor and filmmaker Tim Blake Nelson joins to discuss his novel Superhero, exploring how his experience on film sets shaped the story, the cultural role of superhero films, and how these narratives reflect America’s polarized views of good and evil.', 34, '2026-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 22, 'February 11, 2026 - Andrew Jarecki', 'Attorney General Pam Bondi delivered a tense and unfocused appearance before Congress regarding Epstein‑related questions. An Olympic biathlete admitted to an affair after earning a bronze medal, and Grace Kuhlenschmidt challenged Jordan Klepper on Trump’s sudden opposition to opening a new U.S.–Canada bridge. Troy Iwata highlighted international issues, including a Chinese app used to check on loved ones without direct contact, reports of fries in England washing into the ocean, and Germany’s use of militarized insects. Filmmaker Andrew Jarecki discussed The Alabama Solution, his Oscar‑nominated documentary exposing Alabama’s prison conditions through contraband cell‑phone footage, the activism of incarcerated individuals, the punishment they face, and how Alex Pretti’s death underscores the importance of documenting abuse.', 35, '2026-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 23, 'February 12, 2026 - Minneapolis Mayor Jacob Frey', 'Jordan Klepper examines President Trump’s recently promoted “Undisputed Champion of Beautiful Clean Coal” award and the administration’s related policy actions, including directing the Pentagon to purchase electricity from coal fired plants, limiting the EPA’s ability to regulate greenhouse gas emissions, and assuring coal miners of the administration’s continued support. Grace Kuhlenschmidt reports on American remote workers relocating to Mexico City in pursuit of lower living costs and lifestyle benefits, alongside perspectives from local residents concerned about rising rents and cultural displacement. Minneapolis Mayor Jacob Frey discusses the conclusion of Operation Metro Surge and the withdrawal of ICE agents, highlighting the role of community advocacy and collaboration with other city leaders to protect residents’ rights and resist federal overreach.', 37, '2026-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 24, 'February 23, 2026 - A. Mechele Dickerson', 'Team USA sweeps Canada for gold in Olympic hockey, Jon Stewart navigates how MAGA interprets this win as proof of America''s democratic superiority, and Desi Lydic homes in on the U.S. Olympic team''s secret weapon: superior political systems. Plus, Jon explains how the Supreme Court took a wrecking ball to Trump''s tariff strategy and examines why the U.S. is on the brink of war with Iran. "It''s not just that the middle class is suffering because of one thing; they''re suffering because of everything." A. Mechele Dickerson, University of Texas law professor and author of "The Middle-Class New Deal: Restoring Upward Mobility and the American Dream," joins Jon Stewart to discuss how the government created the middle class they''ve now abandoned, how mortgage interest deductions, HOA exclusions, and school hours hinder the middle class, and how to restore the tentpoles of pension jobs and home ownership that fuel the middle-class American dream.', 46, '2026-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 25, 'February 24, 2026 - Padma Lakshmi', 'Desi Lydic covers wild headlines from Trump’s orbit, including RFK Jr.’s odd sauna moment with Kid Rock, JD Vance’s questionable recipe, and Kristi Noem’s controversial deportation flight. After FCC Chairman Brendan Carr calls for more patriotic TV, Jordan Klepper keeps The Daily Show suitably star-spangled with public-domain tunes. With climate change and nuclear war looming, Michael Kosta dives into the science of sex in space with researchers Simon Dubé and Maria Santaguida, even testing his own readiness. Padma Lakshmi discusses launching her CBS series America’s Culinary Kitchen, the freedom to shape it, uplifting chefs worldwide, worries about anti-immigrant policies’ impact on food, and pokes fun at Vance’s cooking skills.', 35, '2026-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 26, 'February 25, 2026 - Jonathan Haidt & Catherine Price', 'Desi Lydic provides a concise overview of Donald Trump’s unusually long State of the Union address, noting its blend of dramatic rhetoric and frequent standing ovations. Jordan Klepper examines LindellTV, a 24/7 outlet created by Mike Lindell, highlighting its mix of partisan commentary, unconventional programming, and technical issues. In a joint interview, authors Jonathan Haidt and Catherine Price discuss their new book, The Amazing Generation, which offers guidance on helping young people build healthier relationships with technology. They emphasize fostering real world connection, establishing structured screen use at home, and encouraging policy action to address tech driven mental health challenges.', 34, '2026-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 27, 'February 26, 2026 - Christa Miller', 'Desi Lydic unpacks the newest chaos from the Epstein files: Bill Gates blurts out details about past romances, the Clintons deliver closed door testimony on their Epstein links, and an old allegation against Trump resurfaces despite the DOJ’s attempts to bury it. She also highlights Republicans turning a simple snowball fight into supposed NYPD “terrorism,” while Michael Kosta rushes out to gather evidence before it melts. Grace Kuhlenschmidt spotlights oddball tech—from fart tracking underwear to science proven dance moves, Waymo’s human door closer fix, and an AI video pairing Brad Pitt and Tom Cruise to answer who killed Epstein. Christa Miller joins to discuss her Shrinking character’s empty nester arc, embracing vulnerability, collaborating with husband Bill Lawrence, how NYC nightclub work shaped her music supervision skills, and the surprising IMDB credit she shares with Desi.', 31, '2026-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 28, 'March 2, 2026 - Jafar Panahi', 'Jon Stewart dives into America and Israel''s impromptu attack on Iran, Trump''s laid-back war announcement from the Mar-a-Lago basement, and MAGA''s refusal to sell the American people on the plan, purpose, and duration of the war. Plus, Jordan Klepper reveals America''s calculated war strategy: winging it. Award-winning filmmaker Jafar Panahi sits down with Jon Stewart and his interpreter Sheida Dayani to discuss his latest film, "It Was Just An Accident," which is currently nominated for two Academy Awards. They talk about suffering a 20-year ban from filmmaking under the Iranian regime, the difference between a socially engaged filmmaker and one who caters to audiences, displaying the difference between humanity and authoritarianism through characters'' doubt, and why, despite censorship and mass killings, he continues to return to Iran.', 49, '2026-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 29, 'March 3, 2026 - Geeta Gandbhir', 'Michael Kosta breaks down the chaotic first days of Trump’s clash with Iran: the U.S. offering bus evacuations for Americans in the Middle East, Trump gearing up for another possible forever war, conservatives arguing over what counts as “war,” and a friendly fire incident that destroyed $300 million in U.S. fighter jets. Leslie Jones tackles the eternal question of what’s going on with men, digging into loneliness, misogynistic podcasts, non human girlfriend stand ins, and the questionable hygiene habits holding men back—before dishing out some tough love therapy. Filmmaker Geeta Gandbhir joins Kosta to discuss her two Oscar nominated documentaries, covering raw body cam footage in The Perfect Neighbor, the grief of gun violence survivors, the racial bias enabled by stand your ground laws, and how The Devil Is Busy explores the intersection of faith and reproductive rights, using filmmaking to reflect society’s deeper truths.', 37, '2026-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 30, 'March 4, 2026 - Erika Alexander', 'America’s war on Iran spirals within five days, with Trump weighing worst‑case scenarios, a nepo baby suddenly floated as a potential Iranian leader, Sen. Markwayne Mullin fumbling his war talk, and Michael Kosta pushing Pete Hegseth to reconsider his cartoon‑villain “no mercy” speech. Meanwhile, a very drunk Grace Kuhlenschmidt jokingly nominates Trump as Iran’s new supreme leader. Josh Johnson recaps the messiest awards show imaginable, after a Tourette’s activist involuntarily shouted the N‑word at Michael B. Jordan and Delroy Lindo during their BAFTA presentation, sparking chaos between Black Twitter and Neurodivergent TikTok—though Josh insists the real culprit is the BBC. Later, Erika Alexander, star of NBC’s The Fall and Rise of Reggie Dinkins, talks with Michael about returning to TV, confronting Hollywood’s discriminatory systems after Living Single, building opportunities through Color Farm Media, and advising rising Black actors to stay authentic and work relentlessly.', 31, '2026-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 31, 'March 5, 2026 - Mychal Threets', 'Michael Kosta breaks down the latest chaos in Trump’s cabinet as DHS Secretary Kristi Noem is fired amid ICE turmoil, corruption claims, and swirling affair rumors. RFK Jr. somehow picks fights with both Dunkin’ and Starbucks, while Pete Hegseth finds time—despite a war in Iran—to push his personal mission of stripping Scouting America of its supposed wokeness. Jordan Klepper even flatters Hegseth in hopes of earning the ironic “Bros Before Hoes” badge. Meanwhile, Grace Kuhlenschmidt explores America’s first car free neighborhood with controversial “freedom fighter” Katie Hopkins to uncover the truth behind rising 15 minute cities: visionary walkable havens or government run traps? And librarian and new “Reading Rainbow” host Mychal Threets joins Michael to share his mental health journey, the life saving role libraries played for him, and the message behind his book, I''m So Happy You’re Here—a celebration of library joy and a reminder that no one is alone.', 24, '2026-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 32, 'March 16, 2026 - Mayor Matt Mahan', 'Trump''s war in the Middle East rages on, with Iran closing the Strait of Hormuz and Americans gearing up to face the infamous R-word: recession. Plus, FCC Chair Brendan Carr and Defense Secretary Pete Hegseth aren''t happy with the news media''s confused coverage of the war in Iran, so Jon Stewart gets some truth and clarity from a panel of experts: President Trump, Donald J. Trump, DJT, and John Barron. "We''ve got to ask our government to do better before we ask people to give more." Mayor Matt Mahan of San José sits down with Jon Stewart to discuss his candidacy for governor of California. They talk about building constituents'' trust by reducing homelessness, crime, and delivering on housing promises, regulating AI to help the industry boom in a way that protects people''s livelihoods and privacy, and what his background in public school teaching and tech start-ups taught him about examining data to create pragmatic solutions in government.', 43, '2026-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 33, 'March 17, 2026 - George Saunders', 'Jordan Klepper dives into the confidence boost from a former American president that supposedly inspired Trump to consider "taking Cuba", counterterrorism official Joe Kent resigning over the war in Iran, and MAGA turning on each other with "micropenis" allegations. Also, Troy Iwata runs his gaydar on Iran''s new supreme leader to find out if he''s queerbaiting Americans. Freedom of speech is under attack, but thanks to the Trump administration, now you can say anything you want about the president for just $50 a month! Fork over your cash and rest easy knowing that Free Speech Plus has your back, if you don''t mention corruption, cankles, Epstein, or his little dick. Subscribe today! NYT''s Bestselling author, George Saunders sits down with Jordan Klepper to discuss his latest novel, "Vigil". They discuss how he tapped into the mindset of a character who is forced to rationalize their horrible decisions and how accountability can be a form of grace.', 32, '2026-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 34, 'March 18, 2026 - Steve Zahn', 'Jordan Klepper breaks down how Republicans are addressing Americans'' concerns about rising gas prices from the war in Iran by telling them to suck it up and quit whining, DHS secretary nominee Markwayne Mullin finds his Senate confirmation hearing dominated by an old beef with Rand Paul, and Grace Kuhlenschmidt encourages politicians to settle their differences the right way: a duel at 10 paces! On another edition of Sports War, Jordan Klepper and Desi Lydic bicker about the use of AI to fill out March Madness brackets and backlash against an NBA event honoring a strip club. Emmy-nominated actor Steve Zahn sits down with Jordan Klepper to discuss his new film, "She Dances." They talk about wearing many hats as producer, co-writer, and actor, using his "dance dad" background to write a comedy that deals with grief, why no one else could play the part but his own daughter, and evolving with co-star Ethan Hawke from playing slackers in "Reality Bites" to being veteran actors.', 29, '2026-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 35, 'March 19, 2026 - Rebecca Traister', 'Trump bombs a Pearl Harbor joke at a meeting with Japan''s prime minister after a reporter asked him about the Iran war, and Jordan Klepper finds the optimism in Afroman winning a defamation suit against the police who raided his home, preserving free speech through relentless mockery, brutal infidelity jokes, & lemon pound cakes. Michael Kosta delivers the latest get-rich-now opportunities from the hottest business headlines: The Fast Food Wars get a greasy relaunch, Topo Chico mineral water dries up in the U.S., and rare Pokemon cards have collectors collecting fat stacks. Rebecca Traister, author and writer for New York Magazine, talks to Jordan about her latest book, "Angry Girls Will Get Us Through". They discuss the constructive power of anger to bring people together & affect social change, and the mission of her book to tell the under-recognized stories of angry women, girls, & nonbinary people who sparked some of the most impactful moments of change throughout American history.', 29, '2026-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 36, 'March 23, 2026 - Jake Sullivan', 'Trump’s eventful weekend of golfing, sightseeing, and ignoring the imploding effects of the war in Iran has Jon Stewart wondering who the hell the president has been claiming to negotiate with overseas, and whether this "top person" even exists. Plus, airport chaos amid a government shutdown has ICE filling in for the TSA as part of Trump''s escalating chaos rampage. Jake Sullivan, former National Security Advisor, Harvard Kennedy School professor, and co-host of “The Long Game” podcast, joins Jon Stewart to break down the war in Iran, U.S. foreign policy, and the future of nuclear negotiations. Sullivan shares his insights on President Trump’s approach to Iran and Iran’s “coherent and clear” strategy. Plus, Sullivan reflects on his time working on secret negotiations with Iranian officials during the Obama administration and tells the story of a historic first direct contact between U.S. and Iranian presidents since 1979.', 42, '2026-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 37, 'March 24, 2026 - Sterling K. Brown', 'President Trump cheerfully accepts a mysterious “gift” from his enemies in Iran, yet forces TSA agents to work without pay as travelers slog through nine hour airport lines—all because he refuses to approve a bipartisan deal in Congress. He’s also sending untrained ICE agents into airports, and even though they’re not helping ease the chaos, Josh Johnson is at least relieved they’re not out on the streets. Meanwhile, AI is reshaping the world, warping young minds, stealing jobs, and maybe even plotting humanity’s downfall. Former OpenAI researcher and whistleblower Daniel Kokotajlo tells Ronny Chieng why he believes current AI poses a real extinction threat. Emmy winner and Oscar nominee Sterling K. Brown joins Johnson to talk about his series Paradise, why he became an actor “to entertain, educate, and edify,” and how struggling artists can stay motivated. Plus, Josh Johnson delivers the Mini Roast of Sterling K. Brown.', 37, '2026-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 38, 'March 25, 2026 - Joel Martinez aka "The Kid Mero"', 'Josh Johnson covers updates on the situation in Iran: Al Roker forecasts "haboobs" developing in the Middle East, Tehran defiantly refuses a ceasefire agreement, and Trump declares the war over and "won" while Pete Hegseth''s loosened enlistment requirements say otherwise. Desi Lydic highlights the politicians striking out on social media in both short-form and long-form as they try to garner Gen Z''s attention ahead of the midterms. From short cringey TikToks to long cringey podcasts, Desi is begging politicians to connect with young people by talking like actual human beings. Comedian, writer, and host of "Mornings with Mero", Joel Martinez aka "The Kid Mero" joins Josh to discuss making radio sound like New York again. They talk about evolving from a lifelong listener of HOT 97 to their newest host, connecting to listeners who call with open confessions, advocating for unhoused youth with Covenant House, and Joel shows Josh how to tie his Timberlands the "New York way".', 34, '2026-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 39, 'March 26, 2026 - Eiza González', 'Josh Johnson breaks down a packed week in chaos, from Markwayne Mullin replacing DHS shopaholic Kristi Noem to Trump publicly auditing Mullin’s Native American identity. He also tackles Dr. Oz flash-mobbing his way into reduced health expenditures, Melania seemingly swapping out her husband for a humanoid stand-in, and an RFK Jr. anecdote involving a raccoon penis that permanently alters your brain chemistry. Meanwhile, Troy Iwata takes on international headlines that somehow make America look slightly less unhinged: Danish politicians woo voters in saunas, a French mayoral race boiling down to Hittler vs. Zielinski, Kenya shutting down an ant-smuggling operation, and Kim Jong Un fully embracing girl-dad dictatorship energy. Plus, actor Eiza González joins Josh to discuss her new film Mike & Nick & Nick & Alice, embracing comedy, playing a quirky femme fatale opposite James Marsden and Vince Vaughn, and reflecting on her journey from child stardom in Mexico to immigrating to the U.S.', 32, '2026-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 40, 'March 30, 2026 - Cindy Cohn', 'Happy one monthiversary of the Iran war. With the Strait of Hormuz still closed, Jon Stewart looks at how global shortages are rippling outward, hitting everything from grain and helium to pickleballs. At home, Americans flood the streets for the No Kings protests while CPAC counters with Trump’s Yassss Kings rally. The U.S. also finally gets a detailed explanation of the president’s objectives and exit strategy—limited, for now, to the White House ballroom. Jon speaks with attorney Cindy Cohn about her book, Privacy’s Defender: My Thirty Year Fight Against Digital Surveillance, and her work leading the Electronic Frontier Foundation. She reflects on the post 9/11 surveillance fight, warns how internet regulation can backfire, and argues that meaningful reform requires strong privacy laws, new tech business models, and more choices for users. As she notes, the solution isn’t better dictators—it’s fewer of them.', 49, '2026-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 41, 'March 31, 2026 - Julio Torres', 'Desi Lydic dives into Lindsey Graham''s wartime day off at Disney World, Pete Hegseth''s poetic take on the Iran War, Trump''s flailing on the Strait of Hormuz as gas prices reach over $4 a gallon, and the leaked sexcapades of Kristi Noem''s husband that make her fuck plane look tame. Ronny Chieng and Michael Kosta drive each other March Mad over a UConn "buzzer-beater" win against Duke and go head-to-head over big news in baseball, including instant replay for umpires and instant diarrhoea for ballpark foodies. Award-winning filmmaker and comedian, Julio Torres, sits down with Desi to discuss his new HBO special, "Color Theories". Torres invites viewers into an immersive experience in his whimsical world; he explains how Democrats and Republicans embody navy blue and burgundy because of what they hide, why everyone has a little bit of synesthesia, and whether anyone knows what color "puce" is.', 38, '2026-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 42, 'April 1, 2026 - Dr. Mary Claire Haver', 'Desi Lydic takes on Trump’s appearance at Supreme Court oral arguments on birthright citizenship as he argues the constitutional right should apply only to “billionaires”, while also pushing ahead with construction of the White House ballroom despite a federal judge ordering it stopped. Trump also unveils plans for a presidential hotel brary. Lewis Black breaks down prediction markets, where people are now betting on everything from future wars to Trump’s next insult, with some markets giving Jesus better odds of returning than the New York Jets have of winning a Super Bowl. Desi is also joined by board certified OB/GYN Dr. Mary Claire Haver, founder of The ''Pause Life, to discuss her book The New Perimenopause. Dr. Haver explains what perimenopause is, why early mental and neurological symptoms are often misdiagnosed, and how women can advocate for their health and navigate this “second puberty” without suffering.', 37, '2026-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 43, 'April 13, 2026 - Aziz Abu Sarah & Moaz Inon', 'Jon Stewart dives into the backlash over Trump Jesus-ifying himself with AI, the president claiming he was just depicting himself as a "doctor" (treating a bedridden Jon Stewart?), and Trump starting an Easter beef with Pope Leo. Plus, JD Vance fails to secure a deal with Iran while ALSO failing to get Hungarian strongman Viktor Orban re-elected. "We don''t have to be on opposite sides. We can be on the same side, fighting for justice together, fighting for peace together". Peace activists and authors of "The Future Is Peace", Aziz Abu Sarah and Maoz Inon sit down with Jon Stewart to share their inspirational story of family loss and choosing reconciliation over revenge in the Israeli-Palestinian conflict. Through honest dialogue, visits to Holocaust and Palestinian sites, and confronting painful stories, they spread the message of how empathy can break cycles of violence and war. They also challenge the idea that empathy is naïve and share what it was like meeting Pope Francis.', 48, '2026-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 44, 'April 14, 2026 - Bao Nguyen', 'Ronny Chieng dives into JD Vance''s ill-prepared excuse for Trump''s Jesus AI, the VP telling Pope Leo how to pope, RFK Jr. utilizing his best asset for podcasting, and Trump saying he''ll "look into" FEMA head Gregg Phillips''s Waffle House teleportation claims. In this installment of "In My Opinion", Nick Offerman sounds off on how Trump is injecting his self-aggrandising "jackassery" into America''s 250th birthday - from slapping his John Hancock onto American currency to staging a UFC "battle" at the White House - and calls on citizens to find their own way to patriotically party down. Acclaimed film-maker Bao Nguyen sits down with Ronny to discuss his latest documentary, "BTS: The Return". They talk about following BTS''s creative process as a fly on the wall, the big reunion after the band completed their national military service, the documentary narrative around honesty rather than facts, and the band''s vulnerable moments when living out their normal lives.', 34, '2026-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 45, 'April 15, 2026 - Zoe Lister-Jones', 'JD Vance continues his apology tour on Trump''s behalf at a TPUSA event, begging Gen Z not to leave MAGA over Iran and Epstein frustrations, and Ronny Chieng tries to make sense of Trump''s "Diet Coke is healthy" logic. Also, since Trump''s Jesus AI images won''t stop, Grace Kuhlenschmidt steps in as a fully supportive, temporary "war pope". Professional naming expert Marco Glennwald III is losing his mind over the president''s insistence on naming every goddamn thing after himself. Filmmaker and actress Zoe Lister-Jones sits down with Ronny to discuss starring in the Peacock series, "The Miniature Wife". They talk about co-starring as a billionaire and an evil scientist, portraying power dynamics in relationships through a fantastical lens, being exposed to feminist filmmaking from her video artist mother, and giving her TV series "Slip" – which she wrote, directed, and starred in – a "new life" on Peacock.', 40, '2026-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 46, 'April 16, 2026 - Lee Sung Jin', 'Ronny Chieng dives into America’s escalating clash with Iran, from global fuel shortages that leave Thai news anchors visibly sweating to Iran’s AI generated video of Jesus condemning Trump—and whether it qualifies as “patriotic” by Pete Hegseth’s standards. Somehow, the chaos is also buoying the American stock market. Iran’s surge of online “slopaganda” even inspires Michael Kosta to join the meme war. Grace Kuhlenschmidt rounds up the latest tech absurdities in Tech Yeah!, covering “tech neck”, marathon runners racing robots in China, and an AI avatar that might finally make Mark Zuckerberg seem lifelike. Writer director Lee Sung Jin joins Ronny to unpack how "Beef" evolved from a PowerPoint pitch into an award winning Netflix hit, exploring its real life inspirations, generational tensions, and a return to Korea to film with legends Youn Yuh jung and Song Kang ho—complete with a surprise visit from Parasite director Bong Joon ho.', 37, '2026-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 47, 'April 20, 2026 - Annalena Baerbock', 'Jon Stewart unpacks Trump’s Iran “Art of the Deal”, tracing threats, consequences, and concessions that add up to winning nothing. Republicans hail a self-declared victory as “a brilliant day for the world”, while Trump signs a bill to fast-track the psychedelic ibogaine, boasting, “You think Biden could do that?”. Stewart also sits down with UN General Assembly President Annalena Baerbock, who breaks down the growing challenges facing the United Nations — from tensions in the Strait of Hormuz to the limits of the Security Council veto — arguing diplomacy is both harder and more necessary than ever. She also discusses selecting the next UN Secretary-General, and whether member states will finally choose a woman to lead the body in its 80-year history.', 44, '2026-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0115147')) AND numero_temporada = 31), 48, 'April 21, 2026 - Noah Wyle', 'The Trump administration lands in hot water for partying too hard, with FBI chief Kash Patel suing The Atlantic over reports of his drinking, Labor Secretary Lori Chavez-DeRemer resigning amid allegations of affairs and strip club visits, and her husband banned from department headquarters over sexual misconduct claims. Michael Kosta digs into the Department of Labor’s new HR training video. Meanwhile, during an unpopular war with Iran and a heated pope fight, Jordan Klepper heads to a TPUSA event in Phoenix to see if the MAGA faithful are still riding with Trump. Noah Wyle joins Michael to talk Season 2 of HBO Max’s The Pitt, exploring mental health through Dr. Robinavitch, balancing tragedy with hope, and reflecting on how today’s audiences compare with the ER era — and how his perspective has changed since his Dr. Carter days.', 33, '2026-04-21');
