INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0118421', 'Oz', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0002835'), 'SERIE', 'Follows the daily activities of the Inmates at the Oswald Maximum Security Correctional Facility (aka "Oz" for short), an unusual prison where its criminal inhabitants face challenges head on behind bars and do all they can to stay alive.', '1997-01-01', 'https://m.media-amazon.com/images/M/MV5BMjI1ZGJmMGYtYWE1YS00NDAyLThmNGItZWNjZmFiODkxZDUwXkEyXkFqcGc@._V1_.jpg');
