INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')), 1, 'Season 1', 'Welcome to Emerald City, an experimental unit of the Oswald Maximum Security Prison or "Oz." As run by Tim McManus and overseen by Warden Leo Glynn. Em City is about prisoner rehabilitation over public retribution. No matter how hardened a criminal or killer, whether you''re in for a few years or in for life, you have a role to play. Once inside, choose your friends carefully. Every group - Muslims, Latinos, Italians, Aryans - stick close to mutual friends and terrorize mutual enemies. Don''t smile. Get yourself a weapon. Stay on everybody''s good side... if you can find one.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 1, 'The Routine', 'In the "Emerald City" experimental unit of Oswald State Penitentiary, we meet some of the diverse inmates who live within a pecking order of Homeboys, Latinos, Muslims, Irish, Aryans, and Wiseguys. No clear-cut leader emerges—with the possible exception of Kareem Saïd, a Muslim author who preaches non-violence and abstinence. Saïd''s arrival doesn''t prevent a short-fused Mafia inmate named Dino Ortolani from ticking off just about everybody—a habit that ends up burning him.', 56, '1997-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 2, 'Visits, Conjugal and Otherwise', 'With Schibetta and the prison brass in a race to uncover Ortolani''s killer (for very different reasons), we see how inmates react to visits from both their wives and, in one case, family members who are also in prison.', 57, '1997-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 3, 'God''s Chillin''', 'As friction grows in the wake of increasing deaths, Schibetta, Saïd, and Keane are brought together by Glynn, who tells them to keep their respective groups quiet or else he''ll lock the prison down. The tension increases following a visit from Governor Devlin, who was responsible for the ban on smoking and conjugal visits.', 57, '1997-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 4, 'Capital P', 'Governor Devlin has reinstated capital punishment in the state, and the first Oz prisoner scheduled to die is Keane.', 57, '1997-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 5, 'Straight Life', 'The infiltration of drugs into Oz has reached unprecedented levels, and the undercover efforts of McManus and Glynn to find out who''s smuggling them in backfires in a deadly way. Despite a lockdown in Emerald City, the drugs continue to trickle in—and the blame shifts from prisoners to corrupt officials.', 57, '1997-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 6, 'To Your Health', 'Three generations of Alvarezes—all prisoners at Oz—are united when the partiarch, Ricardo, is found face down in his cell, suffering from Alzheimer''s disease. Meanwhile, Beecher, who as Schillinger''s "prag" has been forced to wear women''s clothes, flips out after taking PCP.', 57, '1997-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 7, 'Plan B', 'A recovered Saïd ostracizes Mershah for turning his back on him when he was dying—and orders the rest of the Muslims to do the same. Impressed by Saïd''s power, Groves makes a deadly decision in his honor. Meanwhile, Beecher, transformed by prison life, finally gets revenge on Schillinger.', 56, '1997-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 1), 8, 'A Game of Checkers', 'Beecher is released from the hole and Schillinger is left eyeless and weak. A riot breaks out after two white punks get into a fight over checkers. Frustration, sexuality, hate, revenge, racism all rear their ugly heads, causing the violence to escalate.', 57, '1997-08-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')), 2, 'Season 2', 'All that glitters is not Emerald City. Following the bloodbath that ended the prison riot, life is returning to far from normal for those who survived in the experimental unit of Oz. The Aryan Schillinger still butts heads with Beecher. The mob, led by Schibetta, continues to find its business cut into by the cold-hearted Adebisi. Warden Glynn and Tim McManus struggle to do the right thing for their prisoners, facing adversity at every turn from Governor Devlin. New prisoners include the sexually provocative child killer Shirley Bellinger and a guilty priest who will be forced to pay a terrible penance. The world of Oz will shatter your expectations in a new season where safety is not a option.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 1, 'The Tip', 'In the aftermath of the riot that killed six inmates and two officers, Oz is locked down, and Emerald City prisoners are sent either to solitary or "gen pop." A special committee is appointed to investigate the riot and Governor Devlin''s handling of it. The committee''s leader is law-school Dean Alvah Case, who roams Oz questioning inmates and officers alike. Inside a gen-pop prisoner named James Robson demands that Beecher perform oral sex on him, and gets a painful tip in return. Case determines that the death of inmate Scott Ross during the riot was no accident-but is the truth better left untold?', 56, '1998-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 2, 'Ancient Tribes', 'Ten months after the riot, Em City re-opens. A recovered McManus creates a council of group representatives to keep order, and initiates GED classes to help inmates get high-school equivalency diplomas. Having been told by O''Reily that Adebisi was responsible for his father''s death, Peter Schibetta takes over the kitchen by cashing in a favor Glynn owes the family. As Schillinger''s parole hearing nears, Beecher taunts his nemesis mercilessly in an attempt to ruin Schillinger''s quest for freedom. Glynn''s duaghter is raped by a group of Latinos, and the warden takes out his frustations on Alvarez. O''Reily learns he may have breast cancer.', 57, '1998-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 3, 'Great Men', 'Alvarez knows who raped Glynn''s daughter, but refuses to tell the warden. Wangler is making progress at school, but his cellmate, Adebisi, isn''t a fan of higher education. When Augustus Hill''s judge is convicted of accepting bribes, Said takes up Hill''s case to get him a second trial. Diagnosed with cancer, O''Reily goes to a hospital to get a prison-paid lumpectomy, which is cheaper than a mastectomy. The Aryans are losing credibility in Oz, so Schillinger arranges to have a tough named Vogel killed with Beecher being the next on the hit list. Finally, the prison is filled with excitement as a woman, Shirley Bellinger, arrives on death row to be executed.', 57, '1998-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 4, 'Losing Your Appeal', 'Augustus Hill''s court appeal is denied, despite the efforts of Said, who has better luck getting Poet''s poems published. Meanwhile, O''Reily survives his lumpectomy, and now focuses his attention on Dr. Nathan. Trying to cut a deal after killing an Aryan inmate, Richie Hanlon is forced instead to admit to a murder he didn''t commit. Schibetta offers Alvarez a piece of his drug biz in exchange for killing Adebisi. Beecher is forced to meet with the judge who sentenced him; it appears she has a guilty conscience. Beecher''s new roommate, Chris Keller, seems to hate Aryans as much as Beecher but appearances can be misleading.', 58, '1998-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 5, 'Family Bizness', 'With their enmity at a boiling point, Adebisi poisons Schibetta -- but not fatally. Now that his brother has turned himself in for murder, Glynn no longer owes Schibetta any favors. Sister Peter Marie figures out that Giles witnessed who killed her husband. Poet, now a published author, gets his parole, but Governor Devlin still takes away funds from McManus''s high-school equivalency program. When Beecher learns his wife committed suicide, Keller offers comfort, but his advances are rebuked. Meanwhile O''Reily is in love with Dr. Nathan, and gets his brother Cyril to have her husband killed.', 58, '1998-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 6, 'Strange Bedfellows', 'Schilinger enlists Said to get him out of jail, but Said backs out. McManus decides not to incriminate Wittlesey in Ross''s death. A recovered Schibetta edures more pain after being raped by Adebisi. Meanwhile, Alvarez is bumped out of the Latino power seat by Raoul Hernandez, a.k.a. El Cid. New inmate Jiggy Walker claims he was Gov. Devlin''s personal crack dealer. The two go head-to-head in the media before Walker is discredited and sent to genpop. Reimondo finds out that Giles murdered the man who killed her husband and Dr. Nathan confronts O''Reily about her husband''s death. Schillinger''s plan to destroy Beecher approaches fruition when Beecher falls in love with Keller.', 59, '1998-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 7, 'Animal Farm', 'Cyril O''Reily, Ryan''s brother comes to Oz and is immediately violated by Schillinger. Ryan tries to get him away from OZ, but Cyril instead lands in the hole. El Cid tells Alvarez the only way he can "stay in the game" is to "pluck out" the eyes of a prison guard, Rivera. Bellinger and Adebisi exchanging love letters without meeting. Nappa, the new Wiseguys leader, wants Adebisi to be punished for raping his godson Peter Schibetta. Robert Sippel, a Catholic priest who spent ten years in OZ for molesting a 14-year-old boy is released and but Poet returns.', 57, '1998-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 2), 8, 'Escape from Oz', 'Wittlesey is transferred to Gen Pop and replaced by Karl Metzger, a Nazi. Mack and another Aryan try to escape through Busmalis and Rebadow''s tunnel but the tunnel collapses and kills the two Aryans. Hill gets the idea of escaping Oz by hiding in a coffin. Sippel re-enters Oz because he can''t deal with life on the outside, but Schillinger crucifies him -- literally. Alvarez gouges out Rivera''s eyes and is put in solitary for life. Needing a blood transfusion for Rivera, Dr. Nathan finds that only O''Reily has the same blood type; he agrees to donate in exchange for getting his brother Cyril near him. Keller and Schillinger reveal their sordid plan of deceit to Beecher while breakingv both his arms and legs. Fortune teller Kipkemei Jara gives Adebisi hope of a new life; but he is murdered by Wangler on orders from Antonio Nappa. The grief this causes Adebisi lands him in the psych ward. Said is pardoned by Governor Devlin, but refuses choosing to return to Em City instead.', 68, '1998-08-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')), 3, 'Season 3', 'The name on the street is Oz, but the name on the wall is the Oswald Maximum Security Penitentiary - or it was. Now it''s being changed to the Oswald State Correctional Facility. Maybe by getting rid of the word "penitentiary," the state is finally admitting that nobody''s penitent. Nobody''s sorry. NOBODY.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 1, 'The Truth and Nothing But...', 'In addition to the name change to "Oswald State Correctional Facility," more changes abound. Newbies Coyle, Kahn, and Ricardo arrive and partner up with Wangler, Said, and Hernandez respectively. Adebisi''s "recovery" prompts a return. Clayton Hughes, son of a past Oz guard who came through the ranks with Glynn, asks Glynn to hire him. Meanwhile new Officer Howell, gets friendly with McManus. A managed health care company takes over Oz''s infirmary, to Dr. Nathan''s disgust and Alvarez''s detriment. Cyril O''Reily still has nightmares about being raped by Schillinger and Ryan schemes on revenge. Said develops an unlikely alliance as he starts a hunger fast in response to McManus rejecting his request for food in his cell during his holy season. Keller confesses his part in setting up Beecher and is immediately taken into protective custody. Beecher gets some oh-so-sweet revenge.', 56, '1999-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 2, 'Napoleon''s Boney Parts', 'The hack ain''t comin'' back, and everyone''s trying to figure out who did the deed; especially Schillinger and Said. McManus hires a new officer Sean Murphy who''s also a friend of Tim''s. Despite Glynn''s reservations, an inmate boxing program is is created and inmates get psyched for the competition. While closely shaving Hill, Coyle gives the gruesome details of his crime, which include the death of an infant and the discovery of indisputable evidence to his claim. Disgusted, Hill decides Coyle should pay and gives the info to Warden Glynn. Adebisi gets approved to work in the AIDS ward. While Howell and Wittelsey converse about McManus, he appears with bad news for Wittelsey. Meanwhile, Schillinger''s son Andy has been arrested and is due to arrive to Oz any day. Keller, stir-crazy from being in protective custody, goes back to Em City with painful results. Alvarez begins deteriorating now that his medication has been eliminated.', 56, '1999-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 3, 'Legs', 'With a new day breaking, Officer Howell makes a gruesome discovery. Dr. Nathan takes action against medical official Garvey. Ricardo and Hughes have a brief confrontation that results in a reprimand. Said''s attorney brings good news and a special delivery. Richie Hanlon explains to Shirley Bellinger why he''s on death row. New prisoner Stanislofsky joins the fold. Each group in Oz prepares their boxer for upcoming matches. Hill returns from testifying against Coyle, and the jury''s still out as to whether or not that was the smartest move. Said solicits assistance from Nappa, Schillinger and Guerra. Nappa turns over control to Pancamo after discovering he has a debilitating illness.', 58, '1999-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 4, 'Unnatural Disasters', 'Andy Schillinger arrives to Oz and Vern tries to get Warden Glynn to move Andy in with him. McManus is sued for sexual harassment. Sister Pete has questions after a session with Keller. Miguel gets a directive from Hernandez. Said gets old wounds opened when his sister visits. Ryan scores another victory. Officer Hughes makes a "stunning" move on an inmate and Richie Hanlon''s death sentence is overturned.', 59, '1999-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 5, 'U.S. Male', 'After getting pummeled by Khan in a boxing match, Kenny discovers his wife''s infidelity and arranges a contract. Miguel prepares to meet his victim face to face. McManus'' lawsuit starts taking it''s toll as he wrestles with settling or going to court. New inmate Kosygin is mysterious at best and Stanislofsky keeps a safe distance. Busmalis gets a surprise in the mail. Hughes presses Glynn for more information about past deeds. Beecher and Andrew form an alliance that angers Schillinger and Poet and Junior get a hot reception.', 59, '1999-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 6, 'Cruel and Unusual Punishments', 'When Cudney threatens to spill the truth about Cyril''s "wins", Ryan solicits Kosygin for help. He then schemes to have Kosygin and Stanislofsky eliminated and finally, tips off the hacks to get Hernandez and Ricardo busted. Busmalis gets a welcome visitor. Sister Pete''s questions keep rising after sessions with Keller. Nappa continues working on his new project. Beecher asks Said for lessons in the Islamic faith.', 58, '1999-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 7, 'Secret Identities', 'Sister Pete''s anger is roused and forces her to confession. Wangler and Adebisi register a complaint to the Warden. Yet another inmate meets with demise. Bellinger enlists McManus'' help. Glynn and Hughes have an important conversation. Adebisi begins sowing seeds of discontent and a fight erupts in the gym resulting in a lockdown.', 60, '1999-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 3), 8, 'Out o'' Time', 'When his plea for an expedited return to solitary goes on deaf ears, Miguel takes matters into his own hands. Glynn finds out who raped his daughter. Hill gets sent to the hole. The boxing finals match ends in tragedy. A hack makes an exit...and an impression .....by leaving a holiday gift for an inmate.', 59, '1999-09-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')), 4, 'Season 4', 'The Millennium ended with a bang at Oswald State Correctional Facility, Level Four - aka, Emerald City - as racial tensions reached an all-time high. Now, following a two-week lockdown and the appointment of a new Unit Manager, things are definitely changing, but not necessarily for the better. Prison officials are looking for ways to end the hostilities and return Emerald City to normal... but when was Em City ever normal?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 1, 'A Cock and Balls Story', 'The lockdown ends. After Hamid Khan''s body is taken off life support, the Muslim''s choose Arif to lead them. Meanwhile, Cyril''s having nightmares about delivering the fatal blow to Khan in the boxing match. Ryan asks Sister Pete to intervene. Murphy makes a suggestion to help ease some of the strain in solitary after another inmate commits suicide. Father Mukada plants an inventive idea in Beecher''s head on how to deal with Schillinger. Shirley Bellinger returns awaiting her date with the noose. New inmate Mobay, arrives to Oz and his cellmate Hill is immediately suspicious. Gov. Devlin invites Glynn to be his running mate in the Gov''s re-election bid. McManus gets an update on Wittlesey, who hasn''t returned from vacation and a shootout in Oz results in four deaths.', 60, '2000-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 2, 'Obituaries', 'Mobay has his first meeting with Adebisi. Glynn fires McManus after Tim makes a foolish outburst during the slain CO''s memorial service. Sister Pete still wrestles with ending her service as a nun. Beecher''s dad pays a visit and gives an update. Schillinger is visited by his other son, Hank. Said''s decision to help Cramer secure a new trial is met with strong opposition by the Muslims. Poet grieves and ponders his next move now that Wangler and Pierce are dead. O''Reily''s plan to get the cell phone backfires and results in another inmate''s death. Bellinger returns to Oz to await her impending execution.', 56, '2000-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 3, 'The Bill of Wrongs', 'All is crazy after Busmalis and Alvarez flee from Oz via one of Busmalis'' tunnels. Hernandez discloses details about the shooting to Glynn and mentions Tarrant getting the gun from Adebisi, who got the gun originally from Clayton Hughes. Glynn confronts Hughes, Hughes confesses immediately and is quickly arrested. New inmate Morales is offered Hernandez''s end of the "tit" trade only if he kills Hernandez. Morales asks Rebadow to do the deed in exchange for anything Rebadow wants and Rebadow accepts. Escapee Busmalis is caught and returned to Oz where he is rebuked by Rebadow. A "fresh from the hole" Adebisi begins implementing his plan to get a new Em City administrator. A cell phone appears and Ryan schemes to get his hands on it. Like most O''Reily schemes, someone ends up dead and this case is no different as Hoyt''s recruited to do the "honors". Said scores a victory for Jason Cramer and Shirley Bellinger gets a visitor.', 57, '2000-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 4, 'Works of Mercy', 'The kidnapping of Beecher''s children has everyone upset and Beecher inconsolable. Schillinger gets questioned and of course, claims to know nothing about the deed. Beecher decides to initiate his own investigation. Soon after, a package with horrendous contents arrives for Beecher. Meanwhile, Oz prepares for Shirley Bellinger''s hanging as the death penalty protests continue. A visit from the Cardinal creates mixed feelings for Sister Pete and Father Ray. Said announces good and bad news in the state''s decision for the inmates. Another Rebadow prediction comes chillingly true. O''Reily''s still searching for that elusive cell phone and Dr. Nathan asks Glynn for permission to return to work earlier than expected.', 56, '2000-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 5, 'Gray Matter', 'Things get a bit lively on death row after Shirley Bellinger''s execution-- Miles begins painting a self-portrait, Ginzburg''s health deteriorates from AIDS and Deyell severely injures himself. Mobay''s ordered to kill someone as a final test of his loyalty and a new prisoner, whom Mobay''s familiar with, makes the perfect victim. A call stirs McManus'' emotions again. New inmate Supreme Allah arrives creating tension and uneasiness for Arif. On his way to his son''s funeral, Beecher asks Keller an intimate question. A changed Rebadow asks for permission from Morales to kill again. After a fight with the gangsters, Cyril''s put on heavier sedatives. For Ryan O''Reilly, he gets the cell phone after ratting to Hoyt and he also meets Dr. Nathan''s attacker.', 56, '2000-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 6, 'A Word to the Wise', 'An investigation into Goergen''s death starts and Mobay''s anxious when the investigator targets him first. Tensions begin to rise as Querns turns a seemingly deaf ear and blind eye to the blatant violations committed by black inmates. An inmate transfer works in Adebisi''s favor. Arif challenges Querns''s authority. Ginzburg''s poor health forces him to request an early execution and Sister Pete convinces Glynn to make it happen. Glynn''s press conference announcement forces his daughter to make a major decision. Beecher''s daughter arrives alive and Keller confesses to Mukada.', 56, '2000-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 7, 'A Town Without Pity', 'Ryan and Howell get frisky. After leaving the hole and apologizing to Busmalis for the stabbing Rebadow suffers an attack due to a brain tumor. Busmalis reacts by doing what he does best--start another tunnel. Unbeknownst to the doctors and everyone else, Cyril''s recovering psychologically more than he can actually show. Arif confesses to Said about his own demons and asks for forgiveness and help. Said plots with McManus to end Querns'' and Adebisi''s control. Hank Schillinger beats the kidnapping rap and once Beecher finds out, he plots with Pancamo for revenge. After Keller reveals his plot to kill him, Eli Zabitz asks Schillinger for protection. Schillinger agrees but sends Robson to eliminate Zabitz instead. Hughes, now raging beyond sensibility, makes an attempt on Devlin''s life at a press conference. Keller and Father Ray have an intense discussion about Beecher.', 60, '2000-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 8, 'You Bet Your Life', 'After Hughes''s attack on Devlin, Glynn withdraws from the race. Alvarez is still on the loose. Supreme Allah gets an unwanted surprise.', 58, '2000-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 9, 'Medium Rare', 'Adebisi''s death still looms large over Oz. Against Glynn''s better judgement and with special permission from the Gov., a TV news crew comes to Oz to film. Ryan O'' Reily recognizes the star reporter as a past enemy and he immediately embarks on revenge. After interviewing inmates -- including Poet who strongly suggests the cover up can be exposed through Adebisi''s video tapes-- the show''s producer gets busy digging for answers. McManus discovers this and immediately tells Glynn to destroy Adebisi''s tapes or face Oz possilby being shut down. The star reporter moves into a pod with Cyril for the evening to catch a "verite" view of Oz. The stunt backfires as Cyril (with prompting from O''Reilly) brutally beats the reporter.', 53, '2001-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 10, 'Conversions', 'New inmate Burr Redding arrives and stands ready to assume control of the drug business. Dr. Nathan returns. Tidd approaches Schillinger with a plan to kill Said. Several Asian refugees are housed in Em City while the government decides their fate and they unwillingly get caught in a power struggle between Morales and Redding. Glynn hires an energetic new assistant who piques everyone''s interest.', 59, '2001-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 11, 'Revenge is Sweet', 'Robson and Hoyt tell Rev. Cloutier to back off of Schillinger. Schillinger and Beecher have their first counseling interaction session. Tidd continues to get close to Said by defending Arif in a fight. Arif goes to Said and pleads Tidd''s case to accept him into their Muslim group. Busmalis requests that he and his girlfriend be married. Glynn hosts the Warden''s conference and is given an update on Hughes by Querns. Glynn soon has Hughes transferred to Oz''s cops unit so he can protect him. This unit is also where Johnny Basil (Mobay) is locked up. Keller''s old buddy Ronnie gets close to Beecher causing Keller to get jealous. Ronnie''s offered a sentence reduction in exchange for corroborating evidence of Keller''s involvement in some past murders. Beecher finds this out and warns Keller, who doesn''t believe him. Keller question''s Ronnie about the matter and then, comes up with his own solution. Em City inmates are selected for drug testing experiment that promises to age the person quickly therefore reducing their actual time spent in prison.', 59, '2001-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 12, 'Cuts Like a Knife', 'O''Reily regrets getting Cyril involved with the trial drug when it starts taking effect. Meanwhile, Giles''s request for an unusual method of execution creates controversy and the Chinese refugees are deported...but not before plotting revenge on Morales.', 60, '2001-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 13, 'Blizzard of ''01', 'O''Reily is in for a surprise when a visitor reveals the truth about his past, while Cyril faces trouble for his difficult behavior. Meanwhile, Morales and Redding lay out plans that could lead to all-out war in Em City.', 59, '2001-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 14, 'Orpheus Descending', 'McManus calls a superficial truce between Redding and Morales. Basil finally sees his wife, but Hughes ends up spoiling their happiness. Meanwhile, Cyril''s latest outburst proves to be the last straw.', 59, '2001-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 15, 'Even the Score', 'McManus finds he is unable to turn his back on White. Beecher tells the parents of the young girl he killed that he''s up for parole. Howell tries to blackmail O''Reily so she can get to Cyril, but he throws her for a loop--and then O''Reily is thrown himself by a family secret.', 58, '2001-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 4), 16, 'Famous Last Words', 'In the Season Four finale, Hill discovers where his true allegiances lie. Redding''s plot to use the Colonel against Morales has an unexpected outcome. Cloutier runs into trouble from his church on the outside and his parishioners in Oz. White gets a little too close to McManus. Beecher''s agony about his parole hearing leads to a shocking climax.', 63, '2001-02-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')), 5, 'Season 5', 'It''s a new year...but just another day in Oz. The renovations following the fire are complete: the walls are cleaner, the cafeteria is bigger and everything seems fresher...everything on the outside that is. Inside the hearts and minds of the prisoners, Oz is just as dark and raw as it ever was. Emerald City may look new, but the old, festering feuds are always just around the corner.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 1, 'Visitation', 'A ribbon cutting ceremony, complete with the Governor doing the honors, signals the opening of a newly constructed Oz. Warden Glynn doesn''t resign but he''s more battle weary. White, Alvarez and other inmates in solitary are temporarily transferred to Em City while repairs are being made. As Schillinger and Robson recover from their wounds, they begin planning revenge on the Muslims. Conversely, Said plans to plead guilty for the attempted murder of Robson & Schillinger. The fate of Rev. Cloutier is revealed and inmates expecting visits from family members get shocking news.', 58, '2002-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 2, 'Laws of Gravity', 'Alvarez and Guerra come up with a new way to settle their beef -- Guerra will stab Alvarez in the shoulder without killing him. Morales questions Guerra''s decision to do this while he attempts to grieve for his sister. Rebadow gets more bad news about his grandson which prompts him to search for alternatives. Montgomery asks for more hush money from Ryan so Ryan devises a plan to have Montgomery eliminated. Officer Brass returns to Oz to get facts on who attacked him. Ellie O''Connor arrives as the Governor''s liaison to Oz only past memories of her failed marriage to McManus return. Schibetta returns and Schillinger shanks Pancamo after learning that he had Hank killed. McManus makes an offer to Said and White to hopefully curb White''s erratic and sometimes bizarre behavior. Ryan''s mom, Suzanne Fitzgerald comes to Oz to instruct inmates in performance arts.', 58, '2002-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 3, 'Dream a Little Dream of Me', 'After recovering from his shank wound, Alvarez gains a follower. Busmalis starts a letter writing campaign to get "Miss Sally''s Schoolhouse" back on the air. Rebadow finds a way to raise the money for his grandson''s treatment. Jia Kenmin returns to Oz after recovering from the coma induced by a blow from Cyril. After Schillinger''s released, Redding and Morales form a pact to eliminate the Italians from the drug trade. Schibetta makes a move on the Aryans only it backfires with terrifying results. Kirk continues planning ways to kill Cloutier. After carrying out messages he "received" from Cloutier, Hoyt confesses to all his past murders. Cloutier makes a move that mystifies everyone.', 53, '2002-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 4, 'Next Stop: Valhalla', 'Guerra kills Alvarez''s new follower and the guilt surrounding it forces Alvarez to make a confession to Mukada. Alvarez, Hill and Penders sign up for a seeing-eye dog-training program. Dr. Nathan attacks a patient while having a flashback of her rape. Cyril shanks and kills Li Chien, which gets Cyril sent to solitary and Ryan sent to the cage. During an interaction session Beecher attacks Schillinger after Schillinger denies ever raping him. Redding asks Glynn for control of the kitchen. Hill''s grief over his dead mother and divorce from his wife send him back to drugs happily supplied by Poet. Beecher''s new podmate is the son of a prominent family Beecher knew well. Because of that, Beecher decides to protect him from the Aryans at all costs.', 57, '2002-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 5, 'Wheel of Fortune', 'Said and Arif go to Warden Glynn about Lalar''s murder. Angry and full of rage, Said then confronts White about passing drugs. Unsatisfied with White''s response, Said beats White severely, which gets Said thrown in the hole. Chucky Pancamo''s condition worsens. On orders from Schillinger, Winthrop gets into a fight with Guenzel. Schillinger goes to with a deal, he''ll let Beecher work for him delivering mail to Keller if Beecher has Guenzel transferred to Gen Pop so Schillinger can have him. Keller discovers the feds have compelling evidence linking him to one of the past murders. Meanwhile, Howell makes her move on Keller, Rebadow''s ship comes in...for someone else and Hill becomes gravely ill.', 59, '2002-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 6, 'Variety', 'Said returns from the hole ready to apologize to White. The inmate variety show takes shape with Busmalis as MC and White the featured performer. Robson''s painful teeth force him to the dentist, something he secretly fears. The dentist recommends gum replacement surgery. Alvarez wants to give his dog to Rivera the Oz guard he blinded. Cyril''s trial looms and Ryan''s worried. Redding continues to search for culprit that gave Hill the drugs. Poet, in an attempt to hide the truth from Redding convinces Busmalis to tell Redding that one of the Italians did the deed. This results in Redding having DeSantos poisoned. Chucky''s condition worsens and out of fear, he summons Sister Peter for spiritual help. Meanwhile, Sister Pete starts looking for Guenzel''s attackers only the 3 who know (Said, Beecher, Schillinger) refuse to divulge.', 57, '2002-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 7, 'Good Intentions', 'Redding discovers that Busmalis lied about DeSantos. Furious, he confronts Morales and the confrontation gets the two of them thrown in the hole. Cyril gets convicted of the murder and Ryan tells the attorney not to appeal. Meanwhile Sister Pete, Father Meehan and Suzanne Fitzgerald meet to devise another plan in Cyril''s defense. Rebadow fumes over not getting the lottery money. Mc Manus'' offer to search Oz''s databases reveals an inmate with the same blood history as Rebadow''s grandson. Rebadow meets the man only to be rejected by him. The rumor of Robson''s replacement gums coming from a black patient prompts Schillinger to consult with Aryan Nation leader. The result? Robson gets banned from the Aryans.', 57, '2002-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 5), 8, 'Impotence', 'Robson returns from solitary to discover he''s been kicked out of the "Brotherhood" and moved to another cell. McManus tells Glynn he''ll write a letter supporting Alvarez''s bid for parole. Problem is, Alvarez attacks one of the parole board members and gets thrown back into solitary. Dr. Nathan''s guilt worsens as Chucky slips into a coma from the septic infection. Schillinger tells new inmate Cutler he has to kill a black inmate to join the "Brotherhood" and Cutler selects Said as his victim. White''s gets this information and goes to protect Said only they get into a tussle and Cutler almost dies. Rebadow gets to go see his dying grandson only to have to return later for the boy''s funeral. Busmalis gets a letter from Norma who wants to visit. She does and brings surprising news. Beecher moves to make a confession during the interaction session. The result? Schillinger gets convicted of rape and is transferred to solitary indefinitely. Father Meehan touches a nerve with Ryan and forces him to acknowledge a childhood incident that scarred Ryan for life. A stabbing intended for Redding, claims an innocent inmate instead.', 59, '2002-02-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')), 6, 'Season 6', 'On the surface, not much has changed inside the walls of Oswald State Penitentiary. Schillinger has revenge on his mind, Cyril is facing execution, Beecher is hoping for parole, and McManus is finding solace in a meditative maze. But there''s toil and trouble brewing in the Oz cauldron, as the Oz players rehearse for their presentation of Macbeth and the climactic final act.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 1, 'Dead Man Talking', 'At the bi-annual review of solitary prisoners, the board decides to release Alvarez and Schillinger back into gen pop. Rebadow, still mourning the loss of his grandson, gets transferred to work in the library, where he is thrilled to meet the new librarian, Stella Coffo. Meanwhile, Timmy Kirk, now sentenced to Death Row, pleads to Father Mukada to help exorcize him; Ryan O''Reily seeks to prove his brother Cyril had no premeditated plans of murder; and Winthrop makes Schillinger an offer he can''t refuse.', 56, '2003-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 2, 'See No Evil, Hear No Evil, Smell No Evil', 'The unexpected arrival of Mayor Wilson Loewen at Oz spurs an ironic turn involving Schillinger and Beecher. Meanwhile, Dr. Nathan discovers why solitary inmates are getting sick; a new business plan within Oz inspires Redding; Schibetta looks to puts a curse on the O''Reily family; and some Death Row prisoners get a bang out of a magazine photo shoot.', 57, '2003-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 3, 'Sonata de Oz', 'Schillinger has a disappointing visit with his "hero", Mayor Loewen. Glynn has to face up to the truth when Oz loses its first prisoner to toxic poisoning. Down in solitary, Officer Brass gets some quality one-on-one time with Morales. Cyril undergoes a round of unusual therapy, and Said gets more than he bargained for in leading the Muslims into a new business venture.', 57, '2003-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 4, 'A Failure to Communicate', 'Glynn receives some good and bad news on the toxic-poisoning case. Meanwhile, Rebadow''s relationship with Stella hits a snag; Keller and Beecher work out a mutually beneficial arrangement; Poet and Redding nearly come to blows; Hoyt is transferred from Death Row; and Robson finally gets some redemption.', 57, '2003-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 5, '4 Giveness', 'Everyone has a different opinion of new inmate Idzik; Alvarez receives shocking news; Redding''s attempts at reform continue; Murphy makes a confession to Glynn; Morales''(David Zayas) medical suspicions are confirmed; and Beecher''s devotion to Keller leads him into a perilous position.', 56, '2003-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 6, 'A Day in the Death...', 'Idzik faces his enemies; the intrigues behind the Loewen case get more complicated; changes are made in the hospital; the Muslims run into business trouble; Rebadow and Stella get closer; and the inmates rally to support the O''Reilys.', 57, '2003-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 7, 'Junkyard Dawgs', 'Three new inmates arrive, one of whom is close to the O''Reilys; Busmalis and Rebadow prove to be "true Romeos"; the Keller-Beecher-Schillinger triangle gets more pointed; and an awards banquet ends in a fateful discovery.', 57, '2003-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118421')) AND numero_temporada = 6), 8, 'Exeunt Omnes', 'Oz is in upheaval following the return of Martin Querns. Meanwhile, Howell and Robson each receive troubling news, Mukada answers an unsolved mystery, and the O''Reilys struggle to make amends. Finally, the prison production of ''Macbeth'' ends with a staggering final act.', 98, '2003-02-23');
