INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')), 1, 'Season 1', 'After moving to Sunnydale, California, Buffy Anne Summers just wants to be a normal teenager. Back in Los Angeles, her first Watcher had died; she inadvertently burned down the gymnasium at her old high school; and her parents got a divorce. The move to Sunnydale is supposed to give both her and her mother, Joyce, a clean slate. But then she meets the school librarian, Rupert Giles, and quickly learns there is no escaping her destiny. With Giles as her new Watcher, she reluctantly steps back into her role as the Slayer. But this time she is not fighting alone. She now has an inner circle of special friends-- Willow, Xander, Cordelia, and a mysterious young man named Angel-- ready to join the fight and drive in a stake or two if need be.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 1, 'Welcome to the Hellmouth (1)', 'When teen vampire slayer Buffy tries to start a new life at Sunnydale High, she discovers that the school sits atop a demonic dimensional portal.', 42, '1997-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 2, 'The Harvest (2)', 'Buffy and her friends encounter a powerful vampire bent on opening a portal to a dimension inhabited by demons.', 43, '1997-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 3, 'Witch', 'Buffy suspects she has a witch on her hands when the cheerleading squad falls victim to sudden blindness and spontaneous combustion.', 43, '1997-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 4, 'Teacher''s Pet', 'Buffy''s biology teacher is killed by a giant praying mantis that assumes the form of a beautiful substitute teacher.', 43, '1997-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 5, 'Never Kill a Boy on the First Date', 'With Buffy preoccupied by her date with Owen, Giles is trapped by a group of vampires seeking to raise a powerful leader.', 43, '1997-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 6, 'The Pack', 'Xander and several other students are possessed by the spirit of a demonic breed of hyenas that wreak havoc at the high school.', 43, '1997-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 7, 'Angel', 'Buffy discovers Angel''s dark secret and hesitates to do anything about it, which could spell danger for someone she loves.', 43, '1997-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 8, 'I, Robot... You, Jane', 'Willow''s new Internet chat buddy turns out to be a powerful demon electronically unleashed from a centuries-old, newly digitized book.', 43, '1997-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 9, 'The Puppet Show', 'Buffy suspects that a ventriloquist''s dummy may be harvesting organs from classmates performing in a talent show.', 43, '1997-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 10, 'Nightmares', 'A series of strange occurrences lead Buffy and her friends to discover that their worst nightmares have literally become reality.', 43, '1997-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 11, 'Out of Mind, Out of Sight', 'When an invisible menace starts attacking students and faculty at Sunnydale High, the Scooby Gang traces the problem back to Cordelia.', 43, '1997-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 1), 12, 'Prophecy Girl', 'Buffy''s life may hang in the balance as Giles uncovers an ancient book that foretells not only her death, but also the end of the world.', 44, '1997-06-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')), 2, 'Season 2', 'New vampires Spike and Drusilla come to town along with the new slayer, Kendra Young, who was activated as a result of Buffy''s brief death in the season one finale. Xander becomes involved with Cordelia, while Willow becomes involved with witchcraft and Daniel "Oz" Osbourne becomes a werewolf after being bitten by a young cousin who just happens to be a werewolf. Buffy and the vampire Angel develop a relationship over the course of the season, but Angel''s dark past as the evil and sadistic Angelus threatens to destroy Buffy and the world.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 1, 'When She Was Bad', 'Buffy returns from summer vacation sporting an attitude and suffers from recurring nightmares involving the Master. Meanwhile, the Anointed One and his followers plot their revenge.', 43, '1997-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 2, 'Some Assembly Required', 'Two science club nerds use body parts to create the "perfect girlfriend" for a teenager who has been brought back from the dead.', 42, '1997-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 3, 'School Hard', 'Buffy''s mother and friends become trapped inside Sunnydale High School when a vampire named Spike launches an attack against the Slayer on Parent-Teacher night.', 43, '1997-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 4, 'Inca Mummy Girl', 'An Incan Princess mummy is reanimated in Sunnydale where she sucks the life force from others in order to stay alive.', 43, '1997-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 5, 'Reptile Boy', 'Buffy and Cordelia inadvertently attend a frat party hosted by a murderous cult.', 42, '1997-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 6, 'Halloween', 'On Halloween, Buffy and her friends patronize an unusual costume shop where customers turn into whatever costume they are wearing.', 42, '1997-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 7, 'Lie to Me', 'Buffy is lured into a trap by a group of undead wannabes who hope that Spike will make them vampires in exchange for giving him the Slayer.', 43, '1997-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 8, 'The Dark Age', 'Giles'' past comes back to haunt him as a demon he and Ethan Rayne summoned in their wild youth seeks them out in Sunnydale.', 43, '1997-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 9, 'What''s My Line? (1)', 'Spike brings in three professional bounty hunters to eliminate Buffy while she ponders on what her profession might be if her fate wasn''t already sealed.', 42, '1997-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 10, 'What''s My Line? (2)', 'Buffy joins forces with another Slayer in hopes of saving Angel from the clutches of Spike and Drusilla.', 41, '1997-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 11, 'Ted', 'Buffy''s mom introduces her new boyfriend, who charms everyone except Buffy. When she confronts his dark side, she is left questioning her actions.', 43, '1997-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 12, 'Bad Eggs', 'Buffy and her friends are given eggs to take care of for a health class assignment, but aren''t prepared for what hatches.', 43, '1998-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 2), 13, 'Surprise (1)', 'To give Buffy a surprise on her 17th birthday, Drusilla and Spike bring together the body parts of a dismembered demon who cannot be killed.', 43, '1998-01-19');
