INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 6), 22, 'Grave', 'Giles arrives to face Willow, armed with powerful borrowed magic. Willow, overwhelmed by power and grief, plans a ritual to put the world out of its misery.', 43, '2002-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')), 7, 'Season 7', 'As Buffy accompanies Dawn on her first day at the new Sunnydale High, Giles continues Willow''s magic education in England. But while Buffy is surprised to be offered a guidance counselor job, Willow is shocked to experience a horrific future vision of the Hellmouth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 1, 'Lessons', 'Sunnydale High is re-opened, with a new designed campus and a new principal, Robin Wood. It is Dawn''s first day at school there and Buffy accompanies her to class, only to discover evil spirits lurking in the basement.', 43, '2002-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 2, 'Beneath You', 'The gang meet a young woman who is being chased by a giant worm.', 43, '2002-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 3, 'Same Time, Same Place', 'Willow returns to Sunnydale, but fears her friends have abandoned her when she finds herself completely unable to perceive them. Meanwhile, the rest of the gang don’t see Willow either, but fear she is involved when a body turns up without its skin.', 43, '2002-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 4, 'Help', 'Buffy begins a new job as school counsellor at Sunnydale High. On her first day she encounters a troubled young girl who is convinced she is about to die.', 43, '2002-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 5, 'Selfless', 'Anya''s violent and deadly act of vengeance leaves everyone stunned. Buffy must put aside her feelings and take action before more people die.', 43, '2002-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 6, 'Him', 'Xander and Spike search for the source of a spell that has bewitched the girls into competing for the affections of the high school quarterback.', 43, '2002-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 7, 'Conversations with Dead People', 'Buffy talks through her troubles with an old high school classmate who has recently become a vampire. Cassie, the late student Buffy tried to help, appears to Willow with a posthumous message from Tara. Dawn experiences a terrifying haunting. And Andrew and Jonathan return to Sunnydale High on a mission.', 43, '2002-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 8, 'Sleeper', 'Buffy and her friends fear Spike may be to blame when a number of people around town mysteriously disappear.', 43, '2002-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 9, 'Never Leave Me', 'Buffy and the gang capture and interrogate Spike and Andrew.', 43, '2002-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 10, 'Bring on the Night', 'Giles returns to Sunnydale with three potential slayers, whom Buffy must protect from The First. Meanwhile, a ferocious Uber-vampire is released from the Hellmouth and Buffy must kill it before it kills one of the potentials.', 43, '2002-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 11, 'Showtime', 'Buffy has to keep the ever increasing number of potential Slayers from panicking while Giles and Anya seek answers from the Beljoxa''s Eye.', 43, '2003-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 12, 'Potential', 'Buffy takes the Potentials to a demon bar and then to Spike''s crypt, in order to teach them the art of slaying. When Willow casts a spell to seek out the next Potential, the spell leads them to believe that Dawn may be a future slayer.', 43, '2003-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 13, 'The Killer in Me', 'Kennedy, a potential Slayer, takes Willow on a date, which is interrupted when Willow finds herself transformed into Warren. The other Potentials go on a retreat with Giles, who the gang realize may have been replaced by the First. Spike''s chip is having agonizing malfunctions, and he and Buffy return to the Initiative to search for a fix.', 43, '2003-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 14, 'First Date', 'Buffy accepts a dinner invitation from Principal Wood, and tries to figure out his true intentions. Xander goes out with a girl from the hardware store. The First tries to convince Andrew to murder the potential Slayers. Giles returns from China with a new Potential, but struggles with the language barrier.', 43, '2003-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 15, 'Get It Done', 'Buffy introduces Principal Wood to the rest of the team. He brings an artifact that transports Buffy to see the origin of the Slayer, but the others must face a powerful demon to bring her back.', 43, '2003-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 16, 'Storyteller', 'Andrew creates a documentary called "Buffy, Slayer of the Vampyres", a record of the current situation in Sunnydale to show to future generations. He manages to capture many important moments, and to annoy almost everyone in the house. But Buffy needs to tear him away from his filmmaking because the Seal of Danzalthar is active and Andrew may hold the key to closing it before it destroys the town.', 43, '2003-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 17, 'Lies My Parents Told Me', 'Robin Wood seeks revenge on Spike for killing his mother nearly 30 years ago, whilst everyone else tries to find out how The First has control over him.', 43, '2003-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 18, 'Dirty Girls', 'Faith returns to Sunnydale just as a new villain, Caleb, arrives and sends Buffy a message in the form of a badly beaten Potential. Buffy leads the rest of the girls to Caleb and The First''s lair, with devastating consequences.', 43, '2003-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 19, 'Empty Places', 'After their horrifying loss at the vineyard, the gang turn against Buffy and begin to follow Faith instead. Meanwhile, Spike and Andrew travel to an old church to question a priest about Caleb.', 43, '2003-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 20, 'Touched', 'After being ousted from the group, Buffy tries to figure out how to move forward. Faith and the Potentials plan to interrogate a Bringer for information on Caleb and the First. Many people turn to each other for comfort in the face of the impending apocalypse.', 43, '2003-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 21, 'End of Days', 'Buffy has a powerful new weapon, but the gang cannot find any information about the origins of the mysterious scythe. Eventually the Slayer goes herself in search of knowledge, and finds a new ally, an old friend, and great danger.', 43, '2003-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118276')) AND numero_temporada = 7), 22, 'Chosen', 'Buffy conceives a plan to defeat the First once and for all.', 43, '2003-05-20');
