INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0118480', 'Stargate SG-1', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0217938'), 'SERIE', 'Set after the events of the Stargate (1994) movie, the series follows SG-1, one of many secret military teams of soldiers and scientists who travel through a gateway to other planets and fight against dangerous aliens to protect earth.', '1997-01-01', 'https://m.media-amazon.com/images/M/MV5BMTc3MjEwMTc5N15BMl5BanBnXkFtZTcwNzQ2NjQ4NA@@._V1_.jpg');
