INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')), 1, 'Season 1', 'A military-science expedition team discovering how to use the ancient device, named the Stargate, to explore the galaxy. However, they encountered a powerful enemy in the film named the Goa''uld, who are bent on destroying Earth and all who oppose them.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 1, 'Children of the Gods (1)', 'When powerful aliens come through Earth''s Stargate, Colonel Jack O''Neill returns to Abydos to retrieve Daniel Jackson, who has discovered that the alien transit system includes much more than the two planets.', 46, '1997-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 2, 'Children of the Gods (2)', 'Colonel O''Neill, leading the new SG-1, track Apophis back to the planet Chulak to rescue Sha''re and Skaara, and befriend one of Apophis'' Jaffa guards.', 46, '1997-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 3, 'The Enemy Within', 'Major Kawalsky is possessed by a Goa''uld, and the SGC must find a way to remove it without killing him.', 44, '1997-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 4, 'Emancipation', 'An alien civilization is forced to reconsider their views on women when Carter rebels against their social customs.', 44, '1997-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 5, 'The Broca Divide', 'Members of SG-1 become infected with an alien virus that turns them into primitive beings. Dr. Fraiser must find a cure to save the team and the alien population from whom it was contracted.', 44, '1997-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 6, 'The First Commandment', 'SG-1 must stop a renegade Stargate commander, who has gone mad and set himself up as a god on an alien planet.', 44, '1997-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 7, 'Cold Lazarus', 'During an off-world assignment, Jack is struck down by energy from a blue crystal... which creates a duplicate of him that returns to Earth in Jack''s place.', 44, '1997-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 8, 'The Nox', 'Pressed by the government to acquire new technologies, SG-1 is led to a world inhabited by a seemingly primative race. When Apophis arrives, SG-1 ambush him with disasterous consequences.', 44, '1997-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 9, 'Brief Candle', 'SG-1 discovers a race of attractive people who age extremely rapidly. The situation becomes personal when O''Neill begins to suffer from the same accelerated aging, and must live out the rest of his life on the planet.', 44, '1997-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 10, 'Thor''s Hammer', 'Teal''c and O''Neill are transported to an underground cage designed by the Asgard to protect an alien world from the Goa''uld.', 44, '1997-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 11, 'The Torment of Tantalus', 'SG-1 tracks down Catherine Langford''s fiancee, who took the first Stargate trip in 1945, and discovers an ancient meeting hall that may hold the secrets of the universe itself.', 44, '1997-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 12, 'Bloodlines', 'Teal''c returns to Chulak to stop his people from implanting his son with a larval Goa''uld.', 44, '1997-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 13, 'Fire and Water', 'Daniel is taken captive by an alien with a hidden agenda, while SG-1 is made to believe he is dead.', 44, '1997-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 14, 'Hathor', 'The banished Goa''uld Hathor is found in an ancient sarcophagus Earth, and takes over the S.G.C. with hopes of raising a new army against the System Lords.', 44, '1997-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 15, 'Singularity', 'A mysterious affliction wipes out the entire population of a planet, plus an SG team -- except for one young girl. Carter befriends her, but learns that she is being used by the Goa''uld.', 44, '1997-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 16, 'Cor-Ai', 'Teal''c must stand trial for a crime committed while he served as first prime of Apophis when a villager on an alien world identifies him as the Jaffa who killed his father.', 44, '1998-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 17, 'Enigma', 'The SG-1 team rescues a group of advanced humans from a planet near destruction, and must find a new home for the refugees before the Pentagon gets their hands on them.', 44, '1998-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 18, 'Solitudes', 'Colonel O''Neill and Captain Carter are separated from Jackson and Teal''c during a Stargate journey, and are trapped on a desolate ice world with no way of escape.', 44, '1998-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 19, 'Tin Man', 'The members of SG-1 arrive on P3X-989 and are knocked unconscious. They wake up and return to Earth only to find that they are not quite themselves.', 44, '1998-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 20, 'There But For the Grace of God', 'An alien artifact transports Daniel to an alternate reality, where he is not a part of the Stargate program and the Goa''uld -- led by Teal''c -- are invading Earth.', 44, '1998-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 21, 'Politics (1)', 'Senator Kinsey arrives at the SGC to investigate the program and determine whether the great drain on the U.S. budget is worthwhile, prompting the team to recall missions from the past year.', 44, '1998-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 1), 22, 'Within the Serpent''s Grasp (2)', 'SG-1 escapes through the Stargate before it is shut down, and learns that Daniel''s alternate reality vision is true: Apophis is moving to attack Earth from above. The team must stop Apophis and his son, Klorel, who inhabits the body of their friend Skaara.', 44, '1998-03-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')), 2, 'Season 2', 'O''Neill and the team return to Cimmeria, the planet where they destroyed Thor''s Hammer to help Teal''c escape. They find that the Goa''uld have invaded and many of the people are dead. Can they help to find Thor''s weapons to fight off the invasion before they are all captured or killed?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 2), 1, 'The Serpent''s Lair (3)', 'With SG-1 trapped on Klorel''s ship, it seems that Earth is doomed as the Pyramid Ships prepare to destroy Earth.', 44, '1998-06-26');
