INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 2), 8, 'Family', 'The SG-1 team attempt to rescue Teal''c''s son, who has been kidnapped and brainwashed by Apophis. Teal''c learns disturbing news about his wife.', 44, '1998-08-14');
