INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 6, 'Avatar', 'Teal''c is trapped in a virtual reality simulation, in which he must defend the base from a Goa''uld super-soldier incursion.', 44, '2004-08-13');
