INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 8, 'Covenant', 'A businessman threatens to expose the secrets of alien life to the world, forcing Stargate Command to bring him into the loop.', 44, '2004-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 9, 'Sacrifices', 'The impending wedding of his son is the least of Teal''c''s worries when the Hak''tyl plan an uprising against the Goa''uld Moloc, driving a wedge between Teal''c and Ishta.', 44, '2004-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 10, 'Endgame', 'The Stargate is stolen, leading SG-1 to discover that the Trust has taken control of an advanced ship in orbit. Teal''c investigates a series of wide-spread Jaffa deaths.', 44, '2004-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 11, 'Gemini', 'A duplicate of Colonel Carter seeks help from Stargate Command in defeating the Replicator Fifth, who she claims has found a way to counter the Asgard''s new weapon.', 44, '2005-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 12, 'Prometheus Unbound', 'After the Prometheus responds to a distress call from a Goa''uld ship, Daniel Jackson finds himself a captive when Earth''s ship is stolen.', 44, '2005-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 13, 'It''s Good to Be King', 'SG-1 comes to the aid of a world about to be invaded by the Goa''uld, only to discover that the local king is Earth''s Harry Maybourne.', 43, '2005-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 14, 'Full Alert', 'Relations between the U.S. and Russia are strained when Russian military leaders claim that the U.S. government has been compromised by the Goa''uld.', 44, '2005-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 15, 'Citizen Joe', 'Jack is confronted in his home by an irate barber...who claims to know everything about the Stargate project and SG-1.', 44, '2005-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 16, 'Reckoning (1)', 'The Replicators begin a systematic attack of the Goa''uld, forcing Baal to come to Earth for help. The Jaffa Resistance risk their entire movement in an attempt to retake a holy city in Baal''s domain.', 44, '2005-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 17, 'Reckoning (2)', 'The fate of the galaxy hangs in the balance as Sam and Jacob search for the only weapon capable of stopping the Replicator onslaught. O''Neill leads a defense of the S.G.C., while Daniel squares off against Replicator Carter.', 44, '2005-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 18, 'Threads', 'While Daniel finds himself in a mysterious diner suspended between death and ascension, Jacob''s fate takes an unexpected turn, Jack and Sam consider their romantic lives, and Anubis unleashes his plan for galactic destruction.', 65, '2005-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 19, 'Moebius (1)', 'SG-1 travels back in time in a daring plan to steal a piece of Ancient technology from Ra, the powerful Goa''uld who ruled in ancient Egypt.', 44, '2005-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 8), 20, 'Moebius (2)', 'With the timeline changed by SG-1''s actions in the distant past, an alternate version of SG-1 must use the newly-discovered time ship to set things right.', 44, '2005-03-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')), 9, 'Season 9', 'As one team member transitions into a new role, another is met with hesitation in season nine. Having learned of the Ori''s plan to control the mortal plane, the team must find Merlin''s secret weapon that may destroy the Ori and ensure the safety of Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 1, 'Avalon (1)', 'An Air Force pilot attempts to reassemble SG-1 after they have gone their separate ways. An old "friend" arrives on Earth asking for Daniel''s help in finding an ancient treasure -- and she won''t take no for an answer.', 44, '2005-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 2, 'Avalon (2)', 'An Ancient communications device renders Daniel and Vala unconscious, sending their minds to another galaxy -- where they inhabit the bodies of two people persecuted by the followers of an evil religion.', 44, '2005-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 3, 'Origin (3)', 'Daniel comes face to face with the Ori, a fiery race of beings who demand the worship of mortals. Elsewhere, Stargate Command encounters the first Ori missionary in our galaxy.', 44, '2005-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 4, 'The Ties That Bind', 'Jackson and Mitchell must join Vala on an interplanetary scavenger hunt when they learn that they are still bound together by an alien energy field.', 44, '2005-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 5, 'The Powers That Be', 'SG-1 visits a world whose people once worshipped Vala as a god -- and demand that she stand trial when she confesses to manipulating them.', 44, '2005-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 6, 'Beachhead', 'Samantha Carter returns to Stargate Command when the Ori seize control of a planet, using an expanding force field to gain a foothold in our galaxy.', 44, '2005-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 7, 'Ex Deus Machina', 'SG-1 investigates when evidence suggests that there are still Goa''uld hiding on Earth -- including a former System Lord. Tensions between Earth and the Free Jaffa continue to mount.', 44, '2005-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 8, 'Babylon', 'Colonel Mitchell is injured in a skirmish with a warrior from a mythic tribe of rebel Jaffa, and is trained in their fighting techniques only so that he may engage in a ritual battle to the death.', 44, '2005-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 9, 'Prototype', 'SG-1 finds a genetically advanced Goa''uld-human hybrid created by Anubis, and returns him to Earth for study. But even keeping him alive may not be worth the risk.', 44, '2005-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 10, 'The Fourth Horseman (1)', 'Earth is infected with a deadly Ori plague, prompting an ally from SG-1''s past to come to their aid. Gerak proposes that the Free Jaffa follow the Ori religion.', 44, '2005-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 11, 'The Fourth Horseman (2)', 'As the Ori plague spreads rapidly, SG-1 hopes that the Prior who caused the disease may hold the key to its cure. Gerak tries to rally the Jaffa to the Ori''s cause, prompting Teal''c and Bra''tac to initiate a resistance.', 44, '2006-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 12, 'Collateral Damage', 'When SG-1 travels to an Asgard Protected Planet, Colonel Mitchell is accused of a murder he did not commit.', 44, '2006-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 13, 'Ripple Effect', 'Multiple SG-1s show up at Stargate Command, leading the "real" team to conclude that they have each been inadvertantly displaced from different parallel realities.', 44, '2006-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 14, 'Stronghold', 'Baal kidnaps Teal''c as part of a plot to brainwash those Jaffa advocating a move toward democracy. Cameron Mitchell learns that an old friend is about to die.', 44, '2006-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 15, 'Ethon', 'Daniel is imprisoned on a world under the influence of the Ori, and the Prometheus is caught in a firefight when SG-1 tries to rescue him.', 44, '2006-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 16, 'Off the Grid', 'SG-1 is captured after a deal with the Lucian Alliance goes bad ... and the planet''s Stargate goes missing. Meanwhile, a former System Lord attempts to rebuild his empire.', 43, '2006-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 17, 'The Scourge', 'A tour of an off-world research base for a group of foreign diplomats turns dangerous when an insidious insect species gets loose.', 44, '2006-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 18, 'Arthur''s Mantle', 'Mitchell and Carter are shifted to another dimension, making them invisible to everyone at the S.G.C. Meanwhile, Teal''c and SG-9 discover that the Sodan have been brutally attacked.', 44, '2006-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 19, 'Crusade', 'Vala Mal Doran makes contact with Stargate Command from the Ori home galaxy, and tells the story of her life undercover in a village of followers building the Ori''s invasion fleet.', 44, '2006-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 9), 20, 'Camelot', 'SG-1 discovers the village of Camelot on an alien world, and must face Merlin''s security system when they go in search of an Ancient weapon. Elsewhere, Earth and its allies assemble a fleet when a working Ori Supergate is discovered.', 43, '2006-03-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')), 10, 'Season 10', 'As the team embarks upon its tenth year, Vala, a former Goa''uld host turned freedom-fighter, joins SG-1 in their battle to defend the galaxy from the holy war of the Ori. Having discovered the existence of a weapon capable of defeating the Ori, the team is now in a race against time to find it before more systems fall to the influence of the Priors and the threat of the newly arrived Origin fleet.  
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 1, 'Flesh and Blood', 'As the Ori invade the Jaffa planet Chulak, Vala and Daniel must deal with their leader: Vala''s young daughter, rapidly aged by the Ori to serve their purposes.', 44, '2006-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 2, 'Morpheus', 'SG-1 investigates a problem off-world and soon finds that they have become victims themselves: they cannot stay awake. Meanwhile, Vala Mal Doran undergoes an evaluation on Earth, hoping to join SG-1.', 44, '2006-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 3, 'The Pegasus Project', 'Daniel and Vala travel to Atlantis in search of Merlin''s anti-Ori weapon, while Sam, and Mitchell join forces with Dr. McKay to lock out the Ori supergate.', 44, '2006-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 4, 'Insiders', 'When Ba''al comes to Earth seeking help, Stargate Command must capture his clones and determine which one is the genuine article.', 44, '2006-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 5, 'Uninvited', 'Teal''c discovers a world where people are being savagely attacked by an elusive creature, leading SG-1 to a stunning discovery about its potential origin.', 44, '2006-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 6, '200', 'Martin Lloyd seeks out SG-1 for assistance when his failed TV show based on the real Stargate program becomes a feature film.', 44, '2006-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 7, 'Counterstrike', 'The Jaffa take the fight to the Ori, using a genocidal weapon on their new worshipers and landing SG-1 in the middle of a war they can''t control.', 44, '2006-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 8, 'Memento Mori', 'Stricken with amnesia and on the run, Vala takes a job as a waitress as she tries to piece together who she is and what happened to her.', 44, '2006-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 9, 'Company of Thieves', 'Cameron Mitchell must go undercover inside the deadly Lucian Alliance to prevent his teammates from becoming casualties of an Alliance civil war.', 44, '2006-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 10, 'The Quest (1)', 'SG-1 races against Baal in the hunt to find the Sangraal, Merlin''s anti-Ori weapon, and comes up against a series of ancient trials.', 44, '2006-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 11, 'The Quest (2)', 'When the team finds Merlin himself, they must help him complete the Sangraal weapon before Adria and her Ori forces can track them down.', 44, '2007-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 12, 'Line in the Sand', 'SG-1 tries to defend a planet from the Ori by hiding its people in another dimension. Vala attempts to convince her husband Tomin of the Ori''s true motives.', 44, '2007-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 13, 'The Road Not Taken', 'An experiment gone wrong pulls Samantha Carter into a parallel reality, where she must save Earth from an Ori assault before she will be allowed to return home.', 44, '2007-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 14, 'The Shroud', 'When SG-1 discovers that Daniel Jackson has been turned into a Prior of the Ori, they must determine whether or not his plan to destroy the Ori is genuine.', 44, '2007-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 15, 'Bounty', 'When the Lucian Alliance puts a bounty on SG-1''s heads, Cameron Mitchell finds himself a target while attending his high school reunion.', 43, '2007-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 16, 'Bad Guys', 'SG-1 realizes they have stepped through the gate into another planet''s museum -- but are mistaken for a band of zealous rebels who have taken hostages.', 43, '2007-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 17, 'Talion', 'When a terrorist attack decimates a Jaffa summit Teal''c strikes out on a quest for revenge, believing that the perpetrator is one of his own pupils.', 44, '2007-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 18, 'Family Ties', 'Earth provides sanctuary for Vala''s estranged, con artist father after he provides intel about a Jaffa plot to attack the planet.', 44, '2007-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 19, 'Dominion', 'SG-1 hatches an elaborate plan to try and capture Adria, using Vala as bait.', 44, '2007-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118480')) AND numero_temporada = 10), 20, 'Unending', 'Trapped on board the Odyssey, the members of SG-1 must live out the rest of their lives together when Carter activates a time dilation field to save the ship from destruction.', 44, '2007-06-22');
