INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 1, 'Pilot', 'Middle-class Texan Hank Hill blows his top when an overzealous social worker accuses him of child abuse after rumors about his son''s black eye get out of hand.', 22, '1997-01-12');
