INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 3, 'The Order of the Straight Arrow', 'A camping trip with Bobby''s scout troop leaves Hank griping after the boy clubs an endangered bird during a faux hunt. Meanwhile, Peggy embarks on a mysterious quest.', 22, '1997-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 4, 'Hank''s Got the Willies', 'Hank''s determination to find a role model for Bobby leads to an unexpected encounter with Hank''s own hero.', 22, '1997-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 5, 'Luanne''s Saga', 'When Luanne breaks up with Buckley, Hank takes it upon himself to pick up the pieces of his niece''s broken heart, only to be left fuming when she makes a play for Boomhauer.', 22, '1997-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 6, 'Hank''s Unmentionable Problem', 'A concerned Peggy inadvertently spreads the word about Hank''s bout with constipation, leaving her husband flushed with embarrassment.', 22, '1997-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 7, 'Westie Side Story', 'The Hills'' new Laotian neighbors cause Peggy and Hank confusion and consternation after a culture clash leads to suspicion over a missing dog.', 22, '1997-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 8, 'Shins of the Father', 'Hank''s caught in the middle when his overbearing father pays a visit--and incurs the wrath of a patience-exhausted Peggy.', 22, '1997-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 9, 'Peggy the Boggle Champ', 'Peggy and Hank head to Dallas so Peggy can compete in a boggle tournament, but Hank decides to forego the tournament in order to attend a lawnmower expo.', 22, '1997-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 10, 'Keeping Up with Our Joneses', 'Hank and Peggy''s love of cigarettes is rekindled after Hank catches Bobby smoking, but Luanne is determined to nip their habit in the butt.', 22, '1997-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 11, 'King of the Ant Hill', 'Hank''s burning mad when he discovers fire ants on his lawn on the eve of the neighborhood block party.', 22, '1997-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 1), 12, 'Plastic White Female', 'Luanne and Bobby each face a crisis: she''s fearful of failing her beauty exam, while he frets over his first boy-girl party.', 22, '1997-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 1, 'How to Fire a Rifle Without Really Trying', 'When Bobby discovers the one sport he is good at, marksmanship, he and Hank decide to enter a father & son tournament. As it turns out Hank is a terrible marksman.', 22, '1997-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 2, 'Texas City Twister', 'Luanne moves back into her home, a trailer, just as a twister is about to hit.', 22, '1997-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 3, 'Arrow Head', 'After Hank finds an arrow head in his lawn, Peggy gives a archaeologist permission to have an archaeological dig their yard.', 22, '1997-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 4, 'Hilloween', 'Hank is excited about Halloween until someone complains and has the holiday canceled.', 22, '1997-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 5, 'Jumpin'' Crack Bass (It''s a Gas, Gas, Gas)', 'In an effort to catch more fish than his friends, Hank decides to buy special "bait" from a street vendor. He soon finds himself in trouble with the law.', 22, '1997-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 6, 'Husky Bobby', 'Much to Hank''s dismay, Bobby becomes a plus sized model.', 22, '1997-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 7, 'The Man Who Shot Cane Skretteburg', 'Hank and the guys seek vengeance after a group of teenagers beat them at paint-ball.', 22, '1997-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 8, 'The Son That Got Away', 'Bobby and Connie get in trouble at school. They skirt their ensuing punishment and are joined by Joseph, as they head to "The Caves". Hank and Kahn quickly pursue them, knowing that the caves are Arlen''s make-out point.', 21, '1997-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 9, 'The Company Man', 'Hank struggles to portray himself and his life as that of a stereotypical Texan cowboy''s for a Hollywood cowboy movie fan in order to secure a business deal for Strickland Propane.', 22, '1997-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 10, 'Bobby Slam', 'Bobby joins the wrestling team and is caught in a dilemma when he has to fight Connie in order to make the team.', 22, '1997-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 11, 'The Unbearable Blindness of Laying', 'Hank''s mother bring home her new boyfriend, an affectionate Jewish man named Gary. After Hank sees the two of them having relations, he goes blind.', 22, '1997-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 12, 'Meet the Manger Babies', 'After seeing that Luanne is depressed, Hank volunteers to buy her some hand puppets at a rummage sale. Luanne starts doing a Christian puppet show, The Manger Babies. Hank agrees to play God in the televised version of the puppet show. When it turns out that the show will be on at the same time as the Super Bowl, Hank has to choose between helping Luanne or watching the game.', 22, '1998-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 13, 'Snow Job', 'When Hank''s boss, Buck Strickland, has another heart attack, Hank expects to be put in charge of the company while Buck is recuperating. Instead Buck picks Lloyd Vickers, a business-school graduate, and puts Hank in charge of feeding his dogs. At Buck''s house, Hank discovers that Buck''s stove is electric, not propane. Realizing that Buck is just in propane for the money, Hank considers leaving the propane business and opening up a general store instead.', 22, '1998-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 14, 'I Remember Mono', 'On Valentine''s Day, Peggy finds out that Hank lied to her when they were dating: he told her he was at home one week with a football injury, when he actually got mono from kissing another girl. She sets out to uncover the whole truth, and finds herself face to face with the past.', 22, '1998-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 15, 'Three Days of the Kahndo', 'Hank and his family go with Kahn and his family to spend a weekend in a duplex condo in Mexico. When Kahn discovers that only the bottom half of the condo has been rented, he breaks into the top half and lets Hank stay there. Dale shows up to stay with the Hills, and when Hank, Kahn and Dale are arrested for breaking into the upstairs condo, they have to sneak back across the border.', 22, '1998-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 16, 'Traffic Jam', 'After Hank has a car accident, he has to go to traffic school. The teacher of the traffic school is a comedian, Booda Sack, who gets laughs by insulting the audience. Inspired by Booda Sack, Bobby tries developing a stand-up act of his own. Booda Sack tells Bobby that to be funny, he needs to get in touch with his roots as a white man. Looking for something about "white roots" on the internet, Bobby comes across all the material he needs on a site called the White Nationalist Brotherhood.', 22, '1998-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 17, 'Hank''s Dirty Laundry', 'When Hank tries to buy a new dryer, he is told that his credit is no good because he owes money to Arlen Video. The video store''s computer says he rented and never returned a pornographic movie, Cuffs and Collars. Hank refuses to pay for a movie he never rented, and sets out to prove that the computer was wrong.', 22, '1998-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 18, 'The Final Shinsult', 'When Cotton learns that the U.S. government is giving the artificial leg of General Santa Ana back to Mexico, he teams up with Dale to steal the leg from the Arlen Museum.', 22, '1998-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 19, 'Leanne''s Saga', 'When Luanne''s mother, Leanne, is released from prison, she starts living in the Hills'' garage, and becomes romantically involved with Bill. Bill is busy fighting a foot fungus, with every last dime.', 22, '1998-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 20, 'Junkie Business', 'After Hank realizes that his new employee at Strickland Propane is a drug addict, he can''t fire him, because drug addiction counts as a disability under the Americans With Disabilities Act.', 22, '1998-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 21, 'Life in the Fast Lane, Bobby''s Saga', 'To teach his son the value of a dollar, Hank makes Bobby get a job selling drinks at the racetrack, and tells Bobby to do everything his boss says. What Hank doesn''t know is that Bobby''s boss, Jimmy Witchard, is a complete moron who makes Bobby do humiliating and even dangerous tasks. Meanwhile, Boomhauer competes for the right to drive the pace car in the NASCAR race.', 22, '1998-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 22, 'Peggy''s Turtle Song', 'After Bobby eats too much sugar one morning, he is mistakenly diagnosed with attention deficit disorder. Feeling guilty about not spending enough time with her son, Peggy decides to give up teaching and be a stay-at-home mother, a decision Hank fully approves of. But Peggy is so bored at home that she starts taking guitar lessons, and composes a symbolic song about a turtle trapped in her shell. Meanwhile, Bobby takes pills for his ADD, and Luanne becomes convinced that she caught ADD from Bobby.', 22, '1998-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 2), 23, 'Propane Boom', 'When Mega Lo Mart starts selling propane, Strickland Propane can''t compete with their prices, and Hank loses his job. He winds up working in the propane department at Mega Lo Mart, under the supervision of Luanne''s boyfriend Buckley. Hank and other Mega Lo Mart employees decide to protest the way the company destroys small businesses, by disrupting a concert by the company spokesman, Chuck Mangione. Meanwhile, Luanne, who wanted Buckley to give her the job that he gave to Hank, tells Buckley she''s breaking up with him. And Hank, Luanne and Buckley are the only people in the Mega Lo Mart when Hank notices a leak...', 22, '1998-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 1, 'Death of a Propane Salesman', 'Hank and Luanne survive the Mega Lo Mart explosion, but Buckley is no more. Hank finds that he is scared of propane, and tries to figure out how to deal with his fear of dying. Meanwhile, Luanne, who lost all her hair in the explosion, decides to become an activist like Sinead O''Connor.', 22, '1998-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 2, 'And They Call It Bobby Love', 'Bobby starts dating Marie, a girl who''s two years older than him. Bobby takes the relationship more seriously than Marie does, and is heartbroken when she dances with other guys. Marie decides to "move on" leaving Bobby an emotional wreck. Meanwhile, Hank and the guys find an abandoned couch in the alley, and grow to depend on it.', 22, '1998-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 3, 'Peggy''s Headache', 'When Peggy starts writing "musings" for the local newspaper, the pressure gives her a headache, so she goes to John Redcorn for a therapeutic massage. When she finds out that Dale''s wife Nancy is having an affair with John Redcorn, she is so horrified that she decides to tell Dale about it.', 22, '1998-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 4, 'Pregnant Paws', 'Hank wants to breed Ladybird, but the veterinarian says that she has a narrow uterus and probably can''t have children. Hank becomes obsessed with finding a way to get Ladybird pregnant, which annoys Peggy, because she''s the one who really wants another baby. Meanwhile, Dale becomes a bounty hunter and is assigned to hunt down a man with several unpaid parking tickets. He decides that he needs a hound to accompany him on his first bounty, so he nabs Ladybird, to Hank''s horror.', 22, '1998-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 5, 'Next of Shin', 'Hank tries several different methods to improve his sperm count so he can get Peggy pregnant. The frustration of not being able to have another child becomes worse when Cotton shows up and announces that he got his wife pregnant. But Cotton becomes so nervous at the prospect of having a baby at his age that he flees to Las Vegas, and Hank, Bill and Dale go after him.', 22, '1998-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 6, 'Peggy''s Pageant Fever', 'A beauty pageant offers Peggy the chance to win a truck. If she can endure a series of rigorous makeovers to impress the judges.', 22, '1998-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 7, 'Nine Pretty Darn Angry Men', 'Hank is outraged when he attends a lawn mower focus group and discovers that the new model of his favorite mower has been turned into an upgraded "yuppified" version.', 22, '1998-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 8, 'Good Hill Hunting', 'All the kids in the neighborhood are going on their first hunt, but Hank is unable to get a hunting license for him and Bobby. Bobby is so upset about being denied the chance at a rite of passage that he starts to regress into acting like a little kid. Hank reluctantly decides to take Bobby hunting at the La Grunta Resort.', 22, '1998-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 9, 'Pretty, Pretty Dresses', 'At Christmastime, Bill becomes even more depressed than usual, because it''s the anniversary of when his wife Lenore left him. Bill tries to commit suicide, and when that doesn''t work out, he dresses up in Lenore''s old clothes and declares that he is Lenore.', 22, '1998-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 10, 'A Firefighting We Will Go', 'Hank and his friends become volunteer firefighters. They manage to wreck a fire hydrant, ruin a funeral, and finally burn down the Arlen firehouse. When the Fire Captain comes to ask what happened, the trio turns the story around to match each of their scenarios.', 22, '1999-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 11, 'To Spank, with Love', 'After being taunted and pantsed by one of her students, Peggy loses it and spanks him. She is immediately fired, but Cotton and his old buddies start a campaign to get "Paddlin'' Peggy" reinstated. Once she is back teaching, Peggy uses her reputation for violence to scare her students, and takes things too far, in true Peggy fashion.', 22, '1999-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 12, 'Three Coaches and a Bobby', 'Hank gets his tough old football coach to lead Bobby''s football team. When the coach proves to be a tyrant, Bobby decides to quit football and join the soccer team, much to Hank''s disappointment. Meanwhile, Peggy tries to fit in with the other soccer moms, and takes a crash course from Minh on Soccer-mom etiquette.', 22, '1999-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 13, 'De-Kahnstructing Henry', 'Kahn gets a great new job and invites Hank over to the office, hoping to make him jealous. While bragging about his job, Kahn gives away government secrets, swearing Hank to secrecy. Hank talks to Bill about Kahn''s job, and Kahn gets fired for it.', 22, '1999-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 14, 'The Wedding of Bobby Hill', 'Angry that Luanne cost him his job house-sitting Boomhauer''s house, Bobby replaces her birth control pills with candy.', 22, '1999-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 15, 'Sleight of Hank', 'Hank and Peggy go to a magic show where Peggy gets to be the volunteer in the best trick. Hank tries to figure out how the trick was done, and Peggy won''t tell him. Meanwhile, Bobby is looking for a way to liven up his Sunday School report on Jesus, and when he sees the magician, he incorporates some of the tricks and patter into the report, calling it "The Amazing Jesus."', 22, '1999-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 16, 'Jon Vitti Presents: "Return to La Grunta"', 'Hank gets Luanne a job as a golf course drink girl at the La Grunta resort. In gratitude, Luanne gets Hank a chance to swim with a dolphin. Hank pets the dolphin, and the dolphin becomes aroused and tries to become sexually intimate with him. In return for his silence, the hotel pays him off, and Hank tells Luanne never to talk about what happened. Luanne gets sexually harassed by one of the golfers, she decides to follow Hank''s example and not talk about it.', 22, '1999-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 17, 'Escape from Party Island', 'Hank takes his mother and her friends to a museum of miniatures in Port Aransas, and they get stuck in the middle of MTV''s Spring Break. Meanwhile, Bill tries to put the moves on Peggy while Hank is away.', 22, '1999-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 18, 'Love Hurts... and So Does Art', 'Worried at the prospect of going to a school dance with Connie, Bobby starts overeating at the local deli, and develops gout. Meanwhile, Hank goes to an art gallery in Dallas and finds that they are displaying an X-ray of his constipated colon.', 22, '1999-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 19, 'Hank''s Cowboy Movie', 'After Hank and Bobby visit the Dallas Cowboys training camp in Wichita Falls, Hank decides to make a video that will convince the team to move their camp to Arlen.', 22, '1999-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 20, 'Dog Dale Afternoon', 'When Dale brings home a new ''Super Mower'' the neighbors are jealous, but his attitude leaves everyone with a bad taste in their mouths. To knock him down a few notches, the crew decides to hide his new mower, & make it look like a conspiracy, Peggy gets involved and it goes too far. Dale gets pushed over the edge & it is Hank that goes to help him back down.', 22, '1999-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 21, 'Revenge of the Lutefisk', 'Arlen''s new minister is a woman, which everyone except Cotton seems to accept. When Bobby eats all of a Midwestern fish dish prepared by the minister, it somehow leads to him accidentally burning down the church. Everyone assumes that Cotton did it, and he is arrested for a hate crime.', 22, '1999-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 22, 'Death and Texas', 'Peggy gets a letter from a Death Row convict who says that he is a former student of hers, and that she had the most positive impact on his life. She starts visiting him in prison and bringing him what she thinks is timer sand for Boggle -- not realizing that it''s actually cocaine. Meanwhile, Dale wants to become an executioner.', 22, '1999-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 23, 'Wings of the Dope', 'While studying for her beauty school exam, Luanne sees someone bouncing on Buckley''s old trampoline. It''s Buckley, who has come back as an angel. Hank and Peggy think Luanne was hallucinating after using too many hair-dying chemicals, but Hank''s friends come to believe in the existence of Buckley''s Angel. But Luanne finds that Buckley isn''t much more help to her as an angel than he was when he was alive.', 22, '1999-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 24, 'Take Me Out of the Ball Game', 'When Thaterton stacks his Company softball team with Pro sports stars, Hank pulls Peggy off of her own Softball team to become the Ace pitcher for Strickland Propane. Unfortunately, Hank''s over-managing causes her to lose her stuff, and cause her to lose the love for the sport.', 22, '1999-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 3), 25, 'As Old as the Hills...', 'Peggy and Hank''s 20th-anniversary party leaves the missus missing their youth; and a bottle of tequila is the highlight of their private revelry.', 22, '1999-05-18');
