INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 2, 'Cotton''s Plot', 'Freed from a six-week body cast, non-ambulatory Peggy takes physical therapy from Cotton, who drills her military style. Meanwhile, Hank''s pals make use of her cast.', 22, '1999-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 3, 'Bills Are Made to Be Broken', 'Bill is accepting, but Hank isn''t, when opposing players lie down to let an injured high-school jock break Bill''s touchdown record.', 22, '1999-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 4, 'Little Horrors of Shop', 'Forced to take a vacation, Hank becomes a substitute shop teacher, and a popular one, rousing jealousy in Peggy.', 22, '1999-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 5, 'Aisle 8A', 'Hank is the only one home when houseguest Connie has her first encounter with menstruation--and neither knows what to do. Meanwhile, someone has to explain PMS to Bobby.', 22, '1999-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 6, 'A Beer Can Named Desire', 'Bill meets Cajun relatives and Hank competes for $1 million in a beer promotion at a football game in New Orleans.', 22, '1999-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 7, 'Happy Hank''s Giving', 'Hank''s propane-smoked turkey is a casualty in "a war called ''Thanksgiving at the Airport''" as weather stalls the Hills'' trip to Peggy''s folks in Montana.', 22, '1999-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 8, 'Not in My Back-hoe', 'Jealous of Hank''s new acquaintance, Bill and Dale give Hank an ultimatum, and compound their mistake when they try to make amends.', 22, '1999-11-28');
