INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 10, 'Hillennium', 'A propane shortage gives Hank Y2K fears that alter his Christmas-gift plans; Dale''s stash of hoarded goods is destroyed by a hamster that he was planning to use for food.', 22, '1999-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 11, 'Old Glory', 'Bobby keeps mum that his mom wrote the A-plus essay that made him a school star.', 22, '2000-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 12, 'Rodeo Days', 'Bobby''s new calling is rodeo roping, but his first experience with livestock introduces him to an ambition even greater--at least to Bobby.', 22, '2000-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 13, 'Hanky Panky', 'Hank and Peggy are caught in the middle after Strickland''s wife catches him with his girlfriend.', 22, '2000-02-06');
