INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 15, 'Naked Ambition', 'Bobby''s accidental glimpse of a naked Luanne has Joseph yearning to get his own look. But Connie catches them trying to peep, and thinks she''s the target.', 22, '2000-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 16, 'Movin'' On Up', 'Luanne moves out and into the house across the alley, where her roommates don''t carry any of the load.', 22, '2000-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 17, 'Bill of Sales', 'Bill becomes Peggy''s star--and only--salesman in a health-food sales operation, and his profits net them a trip to a conference in San Antonio, where they must share a room.', 22, '2000-03-12');
