INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 19, 'Hank''s Bad Hair Day', 'After his lifelong barber loses it, Hank turns to Army haircutter Bill, who does a fine job on his first civilian head, but at a Government price, prompting Hank to declare war.', 22, '2000-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 20, 'Meet the Propaniacs', 'Bobby''s impromptu comedy at a propane sale prompts Strickland to send him on the road to entertain at other outlets, leading to a big trade show in front of the Texas propane president.', 22, '2000-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 21, 'Nancy Boys', 'After joining the Hills for a free romantic dinner, the Gribbles sleep together, and guilt grabs Nancy for cheating on her lover, John Redcorn.', 22, '2000-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 22, 'Flush with Power', 'Water restrictions prompt Hank to join the zoning board, while Bobby blackmails Kahn for bribing a water-meter reader.', 22, '2000-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 23, 'Transnational Amusements Presents: Peggy''s Magic Sex Feet', 'Peggy''s embarrassment about her big feet ends when she meets a fetishist who directs her in a video Hank thinks is dirty, but Peggy approves of--wholefootedly.', 22, '2000-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 4), 24, 'Peggy''s Fan Fair', 'At Nashville''s Fan Fair, Peggy accuses Randy Travis of stealing her song, while Brooks & Dunn counsel Bobby about Connie.', 22, '2000-05-21');
