INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 9), 15, 'It Ain''t Over ''til the Fat Neighbor Sings', 'Bill finds happiness in a men''s chorus, where the required devotion jeopardizes his Army career.', 22, '2005-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 1, 'Hank''s on Board', 'Hank discovers that Dale and Boomhauer take yearly vacations together, and assumes that they are trying to avoid Bill.  He invites his family and Bill along for a weekend at the beach, but during the trip, Hank realizes that his friends are actually trying to avoid him because he’s uptight and bossy. Peggy advises Hank to throw caution to the wind and have some fun with his buddies, but the results leave Hank and the guys overboard.', 22, '2005-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 2, 'Bystand Me', 'When the Arlen Bystander gets a new editor, Peggy gets a job writing a household hints column.  Except Peggy doesn''t know any household hints, so she gets Minh to supply her with housekeeping tips in exchange for the answers to the New York Times crossword puzzles.  Meanwhile, Hank makes Bobby get a paper route.', 22, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 3, 'Bill''s House', 'After Bill nurses Hank, Peggy and Bobby through the flu, he starts to feel lonely when there is no one else to take care of.  Hank gets Bill to volunteer at a halfway house for alcoholics, and Bill invites the residents to stay with him. As more and more houseguests show up, Hank becomes determined to find them a permanent residence. Meanwhile, Peggy makes a promise to God that if she gets over the flu, she''ll learn to ride a bike, and Bobby makes her keep her promise.', 22, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 4, 'Harlottown', 'When Hank and Peggy try to clean up a historic Arlen landmark, they find out that the town was founded by harlots and was once a place of ill-repute. The new city manager uses the city''s rediscovered history to turn the town into a tourist trap for the adult porn industry. Frustrated by the changes, Hank decides to move the family – that is, until he is aided by adult actress Candee.', 22, '2005-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 5, 'A Portrait of the Artist as a Young Clown', 'Hoping to get Bobby to stop cracking jokes in school, Hank enrolls Bobby in a clown class at the local community college.  The pretentious instructor teaches Bobby classical comedic theory and sucks all the fun out of him.', 22, '2005-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 6, 'Orange You Sad I Did Say Banana?', 'Kahn is accused of having become so assimilated that he''s a "banana" -- the Asian equivalent of an "Oreo."  To get back to his Laotian heritage, Kahn adopts a simple lifestyle and abandons the swimming pool his neighbors helped build.', 22, '2005-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 7, 'You Gotta Believe (In Moderation)', 'In order to raise money to save the Tom Landry Middle School baseball program, Hank invites a Harlem Globetrotters-type softball team to compete against his community league Arlen Zephyrs.  But Hank ruins the show by deciding to take the game seriously.', 22, '2006-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 8, 'Business Is Picking Up', 'When Bobby attends the school''s job shadow program, he winds up interning for Peter Sterling, a man who runs a pooper-scooper business. Bobby is so impressed by Peter that he decides to pursue the same career.  Meanwhile, Hank is trying to train Joseph at Strickland Propane.', 22, '2006-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 9, 'The Year of Washing Dangerously', 'Hank gets sucked into Kahn''s get-rich-quick scheme when Kahn buys the car wash that hosts car cruising on Friday nights. But Kahn wrecks the business by trying to cut corners, and gets bought out by Buck Strickland. Meanwhile, Peggy tries to figure out if Nancy is deliberately refusing to take her calls.', 22, '2006-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 10, 'Hank Fixes Everything', 'Buck Strickland embarks on a propane price war with Thatherton and two other rivals, and hires the guys from "American Chopper" to boost sales at the Propane Expo.  When the ''war'' goes too far, and the companies are all losing profit, Hank takes matters into his own hands, and calls a meeting.  Unfortunately, the owners decide to ''price fix'' and get caught.  Meanwhile, Lucky and Luanne wait for Brownsville Station tickets, in line 6 days before tickets go on sale.', 23, '2006-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 11, 'Church Hopping', 'When Reverend Stroup gives the Hills'' pew at the Arlen First Methodist Church to another family, Hank and his family decide to find another church. A slick pastor tries to bribe the Hills into worshipping at his Megachurch.', 22, '2006-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 12, '24 Hour Propane People', 'When Buck gets banned from his favorite strip club, he refocuses on making Strickland Propane a "fun" place to work. He makes his employees dress in costumes, have sleepovers in the office and use hip catchphrases. It''s up to Hank to get everyone focused on selling propane again.', 22, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 13, 'The Texas Panhandler', 'Instead of getting a job, Bobby and Joseph discover that they can make more money, and look cooler, by hanging out on street corners and begging.', 22, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 14, 'Hank''s Bully', 'A young boy, Caleb, starts following Hank around, making fun of him and generally annoying him.  Hank isn''t sure how to deal with such a young bully.', 22, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 10), 15, 'Edu-macating Lucky', 'Lucky asks Peggy to help him get his GED in the hopes of improving his chances of marrying Luanne.  Peggy intentionally teaches him the wrong information so he''ll fail and give up the idea of marrying her niece, but then she starts to suspect that Luanne might be pregnant.', 22, '2006-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 1, 'The Peggy Horror Picture Show', 'Feeling unfeminine after a clothing exchange party with the neighborhood girls, Hank offers Peggy a new pair of shoes. After finding that her usual place in Lubbock is out of business, she stumbles upon ''Clairissa''s Closet'', and a new best friend, Carolyn. They become the best of friends, until Peggy finds out that Carolyn is a he, and Carolyn finds that Peggy is a she.', 22, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 2, 'SerPUNt', 'When Bobby''s snakes gets into the toilet Hank decides to call Animal Control. But instead of taking care of the problem they make the city believe that the problem is worse than it is causing panic. Now it is up to Dale to save the city.', 22, '2007-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 3, 'Blood and Sauce', 'The guys discuss what they want to pass on to their children, Bill becomes despondent because he doesn’t have any. In an effort to cheer him up, they help Bill put together a Dauterive family reunion, only to be thwarted by the realization that Bill only has one living relative. Bill winds up sharing an incredible barbeque with his neighbors and teaches Bobby the secret sauce recipe.', 22, '2007-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 4, 'Luanne Gets Lucky', 'When Lucky ditches Luanne to go stumping with Hank and the gang, Luanne accepts an invitation to attend Arlen High School''s Senior Prom. Lucky''s friends Mud Dobber and Elvin take it upon themeselves bully Luanne''s 15-year-old date.', 22, '2007-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 5, 'Hank Gets Dusted', 'Hank is crestfallen when Cotton gives his beloved Cadillac to Cousin Dusty, however things get even worse when Dusty shows up at Hank''s house with a reality TV show crew.', 22, '2007-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 6, 'Glen Peggy Glen Ross', 'Peggy loses her job at The Arlen Bystander and begins a new career as a real estate agent. Meanwhile, after Dale buys a set of titanium golf clubs at a police auction, he gives the clubs to Hank.  However, Hank has trouble playing with a set of clubs that once belonged to a convicted murderer.', 22, '2007-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 7, 'The Passion of Dauterive', 'After Bill survives a roof cave-in over his bed he has a religious experience which involves a romantic liaison with Reverend Stroup.', 22, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 8, 'Grand Theft Arlen', 'Hank becomes obsessed with a video game about propane.  Meanwhile, Bobby trains for the Presidential Fitness Test.', 22, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 9, 'Peggy’s Gone to Pots', 'Peggy tries to reach the pinnacle of real estate success by selling houses in the exclusive neighborhood of Arlen Heights, but she winds up selling pots door to door. Meanwhile the real Rusty Shackleford pays a visit to Dale.', 22, '2007-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 10, 'Hair Today, Gone Today', 'Nancy turns to her mother for help when the stress of home life and unresolved feelings for Redcorn cause her hair to fall out.', 22, '2007-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 11, 'Bill, Bulk and the Body Buddies', 'Bill has to shape up for an upcoming Army physical, but when he becomes friends with a group of body builders he becomes aggressive and develops a bad attitude.  Hank and the gang have to come to the rescue.', 22, '2007-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 11), 12, 'Lucky''s Wedding Suit', 'When Lucky wants to give Luanne the expensive wedding that she desires, he sues Dale with a frivolous lawsuit after having an accident on the job.  After Lucky''s lawyer finds out that Dale does not have insurance, he goes after Strickland Propane.', 22, '2007-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 1, 'Suite Smells of Excess', 'When the guys take Bobby to a college football game, their hijinks land them in a VIP box suite and calling plays for the visiting team.', 0, '2007-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 2, 'Bobby Rae', 'To impress a girl, Bobby protests against soda machines in the school.  However, since the teachers have been using the drink machine money to pay for their "retreat", they decide to fight back. Meanwhile, Dale decides to record his friends'' witty quotes and put them all in a book.', 0, '2007-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 3, 'The Powder Puff Boys', 'Hank encourages Bobby when he is asked to cheerleader for the girls in the school''s annual Powder Puff game.  Bobby soon learns that there is a tradition and Hank, Bill, Dale and Principal Moss were once "Powder Puff Boys" themselves. However, the boys learn that Peggy and the PTA Are trying to put a stop to the tradition.', 0, '2007-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 4, 'Four Wave Intersection', 'Arlen is hit by a heat wave and Hank and the gang take the kids to the water park. Unfortunately, when they have to tangle with a group of surfer bullies, Boomhauer, who is usually cool, winds up embarrassing himself. Meanwhile, Bill becomes known as the famous "Heat-Waver" when he begins to stand on the side of the highway and wave to motorists.', 21, '2007-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 5, 'Death Picks Cotton', 'When the family goes out to a restaurant where the food is cooked at the table Cotton throws a tantrum and gets into a fight with the chef.  The fight leaves Cotton near death in the hospital.', 21, '2007-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 6, 'Raise the Steaks', 'After Hank falls in love with organic food he starts his own mini co-op garden in his back yard.', 21, '2007-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 7, 'Tears of an Inflatable Clown', 'Bobby gets mixed up with racial intolerance at Tom Landry Junior High.  Meanwhile, Lucky hurts himself by catching a frisbee made of barbed wire and the gang has to convince him to go to the hospital.', 21, '2007-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 8, 'The Minh Who Knew Too Much', 'Minh joins the Arlen Gun Club so that she can practice her skeet-shooting skills and become a member of the Nine Rivers Country Club team.  However, Minh loses track of the goal when she starts to identify with her "hillbilly" neighbors.', 22, '2007-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 9, 'Dream Weaver', 'After they have financial troubles, Nancy convinces Dale to go on a "vocation vacation" to learn a new career.  Unfortunately, Dale picks basket-weaving, and he''s not very good at it. Meanwhile, Peggy, Bill and Kahn try to create the next great Internet video.', 21, '2007-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 10, 'Doggone Crazy', 'Ladybird is put on a list of vicious dogs after she gets a little crazy and bites Hank.  Afterwards, Hank is urged by a veterinarian to take Ladybird to a "dog spiritualist".', 21, '2008-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 11, 'Trans-Fascism', 'Hank helps Buck Strickland battle the Arlen City Council and a rival restaurant after "Sugarfoots" loses its business due to a local ban on the sale of foods containing trans fats.', 21, '2008-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 12, 'Untitled Blake McCormick Project', 'Bill falls in love after he has a blind date with Charlene, a hot single mother. However, Dale''s intuition tells him  something is not quite right with the whole situation.', 22, '2008-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 13, 'The Accidental Terrorist', 'Hank buys Peggy a new car, and like he has always done he pays sticker price for it.  However, after he realizes that he has been ripped off for years, he plots revenge against the car salesman.', 22, '2008-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 14, 'Lady and Gentrification', 'Hank''s agrees to speak at Enrique''s daughter''s quinceañera.  However, some of Peggy''s real-estate clients fall in love with the quaint Mexican neighborhood and start to move in.', 22, '2008-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 15, 'Behind Closed Doors', 'Peggy becomes over-protective after a child goes missing in Arlen.', 22, '2008-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 16, 'Pour Some Sugar on Kahn', 'Kahn escapes to the bar and takes up Karaoke after Minh''s father comes to visit. Meanwhile, Bobby and Peggy compete in an escalating game where they try to outdo each other.', 22, '2008-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 17, 'Six Characters in Search of a House', 'Peggy has trouble selling a house when she realizes that the current residents are scaring away the buyers, so she hires actors to play their parts.', 22, '2008-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 18, 'The Courtship of Joseph''s Father', 'Dale''s son becomes the star quarterback for Landry High School, but Dale pushes the boy to accept a private school''s offer, which includes a cash contract.', 22, '2008-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 19, 'Strangeness on a Train', 'Stressed that her birthday parties never live up to her expectations, Peggy plans herself a disco-themed party on a mystery train, but after Luanne ruins the surprise, Peggy worries her parties will always end badly. However, a new mystery arises after a couple sneaks away for some private time in the train bathroom, and the partygoers must figure out who did it.', 22, '2008-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 20, 'Cops and Robert', 'Bobby has to work as a deputy for the school''s police officer after he is framed for throwing a soda can.  Meanwhile, Hank accidentally takes the wallet of a man he thought stole his own wallet, however when he tries to return the wallet the man does not take it too well.', 22, '2008-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 21, 'It Came from the Garage', 'Wanting to spend some quality time with his son, Hank distracts Dale, Bill and Boomhauer with a boat building competition. However, when bats attack the construction garage, Hank has to give up his idea of spending time with Bobby.', 22, '2008-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 12), 22, 'Life: A Loser''s Manual', 'Luanne''s long-lost father and Peggy''s brother Hoyt, a two-strike felon, comes to Arlen. After Hoyt gets caught committing another crime, Lucky feels bad and takes the blame, leaving Hoyt free to continue his life of crime.', 21, '2008-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 1, 'Dia-BILL-ic Shock', 'Bill''s love of sugary snacks causes diabetes. After a doctor tells Bill that he will lose his legs he decides to start using a wheelchair. Once he is wheelchair bound he finds camaraderie with Thunder, a wheelchair sports enthusiast. Things turn around for Bill until Thunder finds out that Bill does not really need the wheelchair.', 21, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 2, 'Earthy Girls Are Easy', 'When a local paper plans to run a story about Strickland Propane dumping old propane tanks into the river, Hank suggests that the company go green. Dale, in an attempt to impress the ladies, organizes an Earth benefit concert.', 21, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 3, 'Square-Footed Monster', 'Hank and the guys do a good deed when they fix-up a neighborhood house, however after Ted Wassonasong buys the house he decides to knock down the house and build a mansion.', 21, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 4, 'Lost in MySpace', 'Hank has bad feelings when Mr. Strickland decides to create a MySpace page for Strickland Propane. Hank''s fears come true when Donna posts personal videos and information to the web site.', 20, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 5, 'No Bobby Left Behind', 'In order to raise the school''s average for standardized tests, Principal Moss classifies Bobby as a low achievement student. However, the plan backfires after Bobby is placed in a class where he no longer has to do homework and doesn''t have to take the tests.', 21, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 6, 'A Bill Full of Dollars', 'Peggy, Minh and Dale play the stock market together, however they lose money in their initial investment. To improve their odds they decide to study the consumer habits of an "average man" and Bill becomes the subject of their study. Meanwhile, after Peggy buys the family a new flat screen TV, Hank and Bobby have difficulty figuring out all the advanced features.', 21, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 7, 'Straight as an Arrow', 'Hank tries to help Bobby become a member of the Order of the Straight Arrow, but he disagrees with the "Arrowmaster" who is a new member of Arlen. Meanwhile, Peggy gets involved in the disagreement as she is the local Welcome Wagon representative.', 21, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 8, 'Lucky See, Monkey Do', 'Lucky''s sister Myrna and her children attend a baby shower in which Peggy is throwing for Luanne. It doesn''t take long before Myrna and Peggy clash over how the children will be raised by Luanne, with Peggy wanting the good, old fashioned skills where as Myrna likes the more modern way and by the book.', 21, '2009-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 9, 'What Happens at the National Propane Gas Convention in Memphis Stays at the National Propane Gas Convention in Memphis', 'The Propane Hall of Fame is inducting Buck Strickland this year and he has asked Hank to come with him to make sure he stays out of trouble. This becomes a hard task after Buck meets his illegitimate son while at the event in Memphis.', 21, '2009-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 10, 'Master of Puppets', 'Bobby is left waiting at the mall when Hank and Peggy''s date goes long. Feeling his parents'' guilt, Bobby uses the incident to pit each against one another to show him their affection. Soon, Peggy and Hank stop giving him anything Bobby wants and he demands they spend more time with him.', 21, '2009-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 11, 'Bwah My Nose', 'Hank and the gang get a rematch for the high-school championship game they lost, when Bill accidentally breaks Hank''s nose during a practice. He gets it fixed by a plastic surgeon and loves his new nose—maybe too much.', 21, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 12, 'Uncool Customer', 'After Peggy finds out that she is not cool she befriends one of Arlen''s most glamorous and cool moms in an effort to learn how to be cool. Bobby befriends her daughter, a girl named Michael Savage.', 21, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 13, 'Nancy Does Dallas', 'After Nancy takes a glamorous new job in Dallas and temporarily leaving Dale behind he finds the freedom of the bachelor life too hard to handle.', 21, '2009-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 14, 'Born Again on the Fourth of July', 'Bobby is offered an intervention at the church, after Hank becomes upset by his misbehavior. Meanwhile, Hank and his pals challenge a rival neighborhood to a Fourth of July fireworks showdown', 21, '2009-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 15, 'Serves Me Right for Giving General George S. Patton the Bathroom Key', 'Hank discovers that his father''s last requests are a collection of bizarre tasks including the wish to have his ashes flushed down a toilet that General George S. Patton once used. Meanwhile, Bill and Dale bicker over an empty beer can.', 21, '2009-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 16, 'Bad News Bill', 'Hank is troubled when Bobby''s Little League Coach is hassling Bobby about his lack of ability until Hank realizes that the Coach is only trying to make Bobby a better player.', 21, '2009-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 17, 'Manger Baby Einstein', 'Luanne tries to become a breakout star in the children''s entertainment industry.', 21, '2009-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 18, 'Uh-Oh Canada', 'After Boomhauer trades houses with a Canadian family for the summer the Arlen gang tries to make some new neighbors at feel welcome. However it soon becomes apparent that Canadians and Arlenites do not see eye to eye.', 21, '2009-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 19, 'The Boy Can''t Help It', 'Bobby becomes quite the ladies'' man when several girls in his class consider him a potential date for the Homecoming dance, but Hank is worried that Bobby is being used.', 21, '2009-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0118375')) AND numero_temporada = 13), 20, 'To Sirloin with Love', 'Thankful to finally have something in common with his son, Hank is proud when Bobby’s knowledge of beef earns him a spot on a college team bound for the State Championships.', 21, '2009-09-13');
