INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 1, 'Saiyan Saga', 'After years of peace since the defeat of Piccolo Daimaoh, Goku now lives peacefully with his wife, Chi-Chi, and their son, Gohan. But everything changes when a mysterious warrior called Raditz arrives on Earth, revealing that he is Goku''s brother and that they both belong to the warrior race of the Saiyans, a brutal people who conquer planets.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 1, 'The New Threat', 'Goku’s quiet life with his family and friends is about to be interrupted. A new threat - a powerful and sinister alien - is on its way to Earth.', 25, '1989-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 2, 'Reunions', 'Goku and Gohan attend a reunion on Roshi’s island, where Goku introduces his son to all of his old friends. The smiles quickly fade, however, as an unexpected visitor - Raditz - lands on the island.', 25, '1989-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 3, 'Unlikely Alliance', 'Raditz has kidnapped Gohan, and unless Goku agrees to join the sinister Saiyan, he may never see his son again! All hope is not lost, however, as a second visitor arrives, and Goku forges an unlikely alliance!', 25, '1989-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 4, 'Piccolo''s Plan', 'Piccolo may have a way to stop Raditz - the Makankosappo! There’s only one problem. He needs time to gather energy for the blast, which means Goku must fight Raditz alone!', 25, '1989-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 5, 'Gohan''s Rage', 'Gohan unleashes a mighty attack that not even Radtiz can resist! But as quickly as his power appears, it vanishes. When Raditz prepares to strike back, Goku must make the ultimate sacrifice to save his son!', 25, '1989-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 6, 'No Time Like the Present', 'Piccolo takes Gohan into the wild for a harsh training program. Meanwhile, Goku embarks on a new adventure in the next world, as he travels the endless Snake Way to reach the legendary King Kai!', 25, '1989-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 7, 'Day 1', 'Gohan begins his first day of Piccolo’s training. Alone in the wilderness, he must quickly learn to take care of himself. But that isn’t easy when he’s tired, hungry - and being chased by bloodthirsty dinosaurs!', 25, '1989-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 8, 'Gohan Goes Bananas!', 'Korin wants Krillin, Yamcha, Tien, and Chiaotzu to report for special training! Meanwhile, Gohan’s grueling training causes him to undergo a shocking transformation!', 25, '1989-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 9, 'The Strangest Robot', 'To escape a pack of wild animals, Gohan ventures into an ancient cave, where he meets an old Capsule Corp robot. The robot has lived alone in the cave for over 30 years, and he’s not happy to have visitors!', 25, '1989-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 10, 'A New Friend', 'Gohan’s wilderness adventure continues, as he makes a new dinosaur friend! He’s happy to finally have some company until he’s harshly reminded that not all dinosaurs are friendly!', 25, '1989-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 11, 'Terror on Arlia', 'On planet Arlia, Vegeta and Nappa become prisoners of the tyrant king who rules the planet. After a brief scuffle with the monster Yeddy, the Arlians realize that the two Saiyans are more than they can handle.', 25, '1989-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 12, 'Global Training', 'Gohan spends his day tormenting a T-Rex. Across the planet, Tien and Chiaotzu find their training interrupted by Launch. Meanwhile, Goku tries to find King Kai on Snake Way.', 25, '1989-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 13, 'Goz and Mez', 'Goku encounters two giant ogres who want nothing more than to use the hero as a play toy! If he can defeat their challenges, the ogres vow to show him the way back to Snake Way.', 25, '1989-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 14, 'Princess Snake', 'Back on Snake Way, Goku comes across a house he believes might belong to King Kai! Unfortunately, the dwelling is inhabited by Princess Snake, and she’ll do anything to keep Goku as her prisoner forever!', 25, '1989-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 15, 'Dueling Piccolos', 'Piccolo flies off the handle during his fight with Raditz and splits in two! Meanwhile, Gohan decides to take a raft across the sea to visit his mother, gets caught in a storm, and suddenly remembers that he can’t swim!', 25, '1989-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 16, 'Plight of the Children', 'Gohan finds shelter with a gang of orphans living on the run from meddling adults. The group’s leader hatches a plan to take the kids to a safer hiding place, but when the police show up everything goes wrong!', 25, '1989-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 17, 'Pendulum Room Peril', 'Earth’s top warriors visit Kami’s Pendulum Room where the past, present, and future co-exist. After a trip back in time, they realize they’ll need to train harder to stand a chance against the approaching Saiyans.', 25, '1989-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 18, 'The End of Snake Way', 'Gohan continues training, but a full moon causes the young Saiyan to rampage out of control! Meanwhile, Goku makes it to the end of Snake Way only to mistake a friendly ape named Bubbles for King Kai!', 25, '1989-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 19, 'Defying Gravity', 'The intense gravity of King Kai’s planet makes Goku’s training difficult, but when he learns that the Saiyans are used to extreme fighting conditions, Goku is inspired to give it his all. Will it be enough?', 25, '1989-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 20, 'Goku''s Ancestors', 'After Goku struggles to bash Gregory with a hammer, King Kai inspires him with the story of the Saiyan race - and offers to train him personally! Will it be enough to stop the looming Saiyan invasion?', 25, '1989-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 21, 'Counting Down', 'Goku’s training is complete, so the gang summons the Eternal Dragon to wish him back to life. There’s only one day left before the Saiyans arrive. Unfortunately, it will take Goku two days to return!', 25, '1989-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 22, 'The Darkest Day', 'Vegeta and Nappa mark their arrival with the destruction of an entire city! When the Z-Fighters confront them, the heroes must face an onslaught of Saibamen under the command of the Saiyans.', 25, '1989-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 23, 'Saibamen Attack!', 'Krillin, Piccolo, and Gohan stand face to face with the sinister Saiyans and their diabolical henchmen. The villains have already proven terrifyingly powerful. Can Earth’s heroes hold out until Goku arrives?', 25, '1989-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 24, 'The Power of Nappa', 'Enraged over the loss of Yamcha, Krillin unleashes a powerful attack that destroys the maniacal Saibamen once and for all. Now Earth’s defenders must battle the Saiyans themselves - starting with Nappa.', 25, '1989-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 25, 'Sacrifice', 'Chiaotzu sacrifices himself to save his friends from Nappa, but when the smoke clears, the villain still stands! Luckily, Tien has one trick left that could forever silence the Saiyan warrior!', 25, '1989-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 26, 'Nappa''s Rampage', 'Vegeta has called a halt to the fighting, and Nappa uses the time to go on a rampage! Meanwhile, Goku reaches the end of Snake Way and races to rejoin his friends - but is he already too late?', 25, '1989-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 27, 'Nimbus Speed', 'Piccolo, Gohan, and Krillin do their best to stop the Saiyans from finding the Dragon Balls. Meanwhile, Goku rushes back to Earth on the Flying Nimbus, armed with more power than ever before!', 25, '1989-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 28, 'Goku''s Arrival', 'Piccolo makes the ultimate sacrifice to save Gohan from the rampaging Saiyans. Just when all seems lost, Goku returns to Earth with an incredible new level of power and confronts the invaders.', 25, '1989-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 29, 'Lesson Number One', 'Locked in battle with the Saiyans, Goku gives Nappa a brutal demonstration of the training he received from King Kai. Broken and defeated, Nappa must now face the ferocious wrath of Vegeta!', 25, '1989-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 30, 'Goku vs. Vegeta', 'Goku decides to take on mighty Vegeta all by himself! The two appear evenly matched, but both are hiding their true strength. The epic battle is underway - which mighty warrior will claim victory?', 25, '1989-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 31, 'Saiyan Sized Secret', 'Vegeta and Goku continue trading brutal blows, but the action intensifies when Vegeta reveals the secret power of the Saiyans: the ability to transform into a giant, planet-destroying ape!', 25, '1989-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 32, 'Spirit Bomb Away!', 'Goku feels the brunt of Vegeta’s fully-realized Saiyan power! Earth’s greatest hero is left with no choice except to use the Spirit Bomb. If his attack fails, he may find himself completely doomed!', 25, '1990-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 33, 'Hero in the Shadows', 'With Goku caught in the clutches of the giant ape Vegeta, Krillin attacks with his Destructo Disk! When his effort falls short, an unlikely hero steps out of the shadows!', 25, '1990-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 34, 'Krillin''s Offensive', 'Goku passes the power of the Spirit Bomb to Krillin, who - with King Kai’s guidance - launches the bomb at Vegeta. The Saiyan is sent flying into the sky, but is the evil warrior really gone for good?', 25, '1990-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 35, 'Mercy', 'Vegeta is crushed beneath the full weight of Gohan’s giant ape form! With the Saiyan battered and defeated, Krillin moves to finish the Saiyan with a final blow - but Goku has other plans.', 25, '1990-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 36, 'Picking Up The Pieces', 'The gang mourns the loss of Yamcha, Tien, Chiaotzu, and Piccolo. With Kami gone, Earth’s Dragon Balls have disappeared. Will the surviving heroes find a way to wish their fallen friends back to life?', 25, '1990-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 37, 'Plans for Departure', 'Bulma accidentally destroys the Saiyan spaceship! Luckily, Mr. Popo reveals the existence of another ship that may be able to reach Namek. Can they find it in time, and will the old ship still work if they do?', 25, '1990-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 38, 'Nursing Wounds', 'Goku, Krillin, and Gohan prepare for the return of the Saiyans. Meanwhile, Bulma and Mr. Popo search for a second spaceship capable of transporting her to Planet Namek.', 25, '1990-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 1), 39, 'Friends or Foes?', 'Gohan, Bulma, and Krillin blast off for Planet Namek in search of the magic Dragon Balls, but their journey quickly turns chaotic when they encounter a bizarre situation in the vacuum of space!', 25, '1990-03-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 2, 'Namek Saga', 'While Goku recovers from injuries suffered during battle with the Saiyans, his friends begin their perilous quest for the Namekian Dragon Balls. Awaiting their arrival on Planet Namek is the powerful Ginyu Force – and the vile monster Frieza!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 1, 'Held Captive', 'Bulma, Gohan, and Krillin are mistaken for friends of Frieza and taken prisoner by an angry army of children! To regain their freedom and continue on their mission, the gang must convince the kids of their innocence.', 25, '1990-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 2, 'Look Out Below', 'A near-fatal crash landing turns out to have a silver lining when Bulma, Gohan, and Krillin are rescued by two friendly Namekians who agree to help them locate the seven Dragon Balls.', 25, '1990-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 3, 'The Search Continues', 'Gohan, Krillin, and Bulma continue their search for the Dragon Balls with the help of their new friend Zaacro. Back on Earth, Goku has escaped from the hospital to begin training for his upcoming re-match with Vegeta.', 25, '1990-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 4, 'A Friendly Surprise', 'As Bulma, Krillin, and Gohan close in on the last of the Dragon Balls, they uncover a shocking secret about their Namekian friends. Meanwhile, Goku works to build up his strength, and Vegeta sets his sights on revenge!', 25, '1990-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 5, 'Brood of Evil', 'Bulma, Krillin, and Gohan finally continue their quest to locate all seven Dragon balls. Unfortunately, the gang soon discovers that they aren’t the only ones seeking the magical orbs!', 25, '1990-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 6, 'Frieza Strikes!', 'Krillin, Gohan, and Bulma are horrified to see Vegeta’s space pod land on Planet Namek, but the Saiyan Prince is the least of their problems. Yet another epically evil villain has come to Namek in search of the Dragon Balls!', 25, '1990-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 7, 'Defying Orders', 'With the odds are rapidly mounting against them, Krillin and Gohan will need some serious help if they hope to recover the Dragon Balls from Frieza and his henchmen.', 25, '1990-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 8, 'Namek''s Defense', 'Krillin and Gohan get their first glimpse of Frieza’s cruelty as the villain unleashes his henchmen upon an unsuspecting Namek village. Frieza wants the fifth Dragon Ball, and he is prepared to learn its location by any means necessary!', 25, '1990-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 9, 'The Hunted', 'Gohan risks his life to rescue a Namek boy from the clutches of Frieza’s evil henchmen. Now Gohan and Krillin have an even bigger problem on their hands: Dodoria is chasing them, and he won’t stop until he has his revenge!', 25, '1990-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 10, 'The Prince Fights Back', 'Dodoria’s search for Krillin and Gohan brings him face to face with an unexpected foe - Vegeta! The Saiyan prince has a score to settle with Dodoria, and the time for a final showdown between these two powerful villains has arrived!', 25, '1990-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 11, 'Unexpected Problem', 'Goku’s journey to Namek takes an unexpected detour when his spaceship is knocked off course by an asteroid! Goku has to act fast to get his ship back on track because he’s headed straight for the fiery center of a star!', 25, '1990-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 12, 'Vegeta has a Ball', 'With his new abilities, Vegeta quickly tracks down and forcefully acquires another Dragon Ball. Now, there is only one magic orb left to find, and Dende knows who has it - the Eldest Namekian!', 25, '1990-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 13, 'The Past and Future', 'King Kai becomes concerned after learning that Goku is on a collision course with the ruthless Frieza. Meanwhile, back on Planet Namek, the battle between Vegeta and Zarbon has begun!', 25, '1990-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 14, 'Zarbon''s Surprise', 'Vegeta’s latest battle heats up as Zarbon reveals his true power: the ability to transform into a monstrous beast! With his increased size and strength, Zarbon seems ready to turn the lights out on the Saiyan Prince - permanently!', 25, '1990-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 15, 'Guru''s Gift', 'When Krillin speaks to the Eldest Namekian, he gets a double surprise! Not only does he receive a Dragon Ball, but the sleeping powers within him are awoken! Will Krillin’s incredible new strength be enough to save his friends?', 25, '1990-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 16, 'Piccolo vs. Everyone', 'Yamcha, Tien, and Chiaotzu continue training, but their workout gets intense when Piccolo challenges them all to a three-on-one bout! Back on Namek, Frieza’s henchmen try to revive Vegeta in order to obtain the missing Dragon Ball.', 25, '1990-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 17, 'Zarbon''s Mission', 'Vegeta escapes from the clutches of Frieza, and steals the Dragon Balls in the process! Elsewhere, Goku’s journey through space grows perilous as his ship is caught in a powerful magnetic storm!', 25, '1990-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 18, 'Gohan, the Hunted', 'Krillin returns from his meeting with the Eldest Namekian only to be greeted by a pair of unwelcome visitors: Vegeta and Zarbon! Meanwhile, Gohan discovers the seventh and final Dragon Ball!', 25, '1990-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 19, 'Unknown Enemies', 'The Ginyu Force has been dispatched to Planet Namek to help search for the Dragon Balls. Unaware of this new threat, Krillin and Gohan struggle to keep the seventh Dragon Ball from falling into Vegeta’s evil hands.', 25, '1990-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 20, 'Destination: Guru', 'While Krillin and Gohan visit the Eldest Namekian, they leave the seventh Dragon Ball their hidden camp. When the Dragon Ball mysteriously disappears, Bulma must embark on a daring underwater adventure to get it back!', 25, '1990-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 21, 'Bulma''s Big Day', 'Bulma is taken hostage by Frieza’s evil henchmen, who force her to lead them on an underwater quest for the Dragon Balls. Without Gohan and Krillin to save her, she’ll have to outsmart her captors — or wind up sleeping with the fishes!', 25, '1990-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 22, 'Hidden Power', 'Krillin and Gohan complete their journey to Guru’s house, but little do they know, Vegeta is hot on their trail! Can Guru unlock Gohan’s hidden powers in time to hold off the rampaging Saiyan’s wrath?', 25, '1990-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 23, 'New Ally, New Problem', 'The Ginyu Force has arrived on Planet Namek! Now, Vegeta, Krillin, and Gohan must form an uneasy alliance as they stand face to face with five of the fiercest warriors in the universe!', 25, '1990-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 24, 'Guldo''s Mind Binds', 'The battle with the Ginyu Force begins, as Gohan and Krillin launch a barrage of explosive energy blasts at Guldo! The Heroes are rendered helpless by Guldo’s Mind Blind technique, and this time, there is no one to save them!', 25, '1990-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 25, 'Recoome Unleashed', 'The battle with Guldo may be over, but the real nightmare is just beginning! Recoome, the most massive member of the Ginyu Force, is ready to fight, and even the mighty Vegeta’s attacks have no effect on this monstrous foe!', 25, '1990-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 26, 'Let the Battle Begin', 'With Krillin and Vegeta both out of commission, only Gohan remains to carry on the fight against Recoome! The young Saiyan must summon every ounce of his strength and courage in order to face this powerful foe.', 25, '1990-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 27, 'Goku''s New Power', 'Goku has arrived on Planet Namek, and without a second to lose! Gohan and Krillin are hanging by a thread, held at the mercy of the Ginyu Force! Has Goku’s training in 100-times gravity prepared him to face these powerful foes?', 25, '1990-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 28, 'A Legend Revealed', 'As Vegeta, Krillin, and Gohan look on, Goku easily deflects the attacks of Jeice and Burter, two of the Force’s fiercest warriors. Could Goku have become what Vegeta thought was only a legend: a Super Saiyan?', 25, '1990-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 29, 'Ginyu Assault', 'When Goku proves too much for Burter and Jeice to handle on their own, Jeice retreats in search of reinforcements. Now, the real test for Goku and his newly-acquired powers is about to begin as Captain Ginyu enters the fight!', 25, '1990-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 30, 'Incredible Force!', 'As the battle between Goku and Captain Ginyu rages on, Gohan and Krillin steal the unguarded Dragon Balls from Frieza’s ship. It’s a race against time, and our heroes must unlock the power of the Dragon Balls before it’s too late!', 25, '1990-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 31, 'Frieza Approaches', 'Goku astounds Captain Ginyu with his amazing new powers, but the Captain still has a few tricks up his sleeve! Meanwhile, Frieza arrives at the home of the Eldest Namek and begins a battle with the noble warrior, Nail!', 25, '1990-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 32, 'Goku Is Ginyu and Ginyu Is Goku', 'In an attempt to save the Elder, Nail fights a hopeless battle against the ruthless Frieza. Meanwhile, finding himself no match for Goku’s superior abilities, Captain Ginyu unleashes his ultimate attack, the Body Switch Technique!', 25, '1990-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 33, 'Calling the Eternal Dragon', 'Armed with the Dragon Radar, Gohan and Krillin recover the seven Dragon Balls from their hiding places. But before they can summon the Eternal Dragon to make their wish, they are confronted by a powerful new enemy - Goku?!', 25, '1990-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 34, 'Gohan, Defeat Your Dad!', 'After taking control of Goku’s body, Captain Ginyu turns his attention to Gohan and Krillin! With Goku trapped in the Captain’s broken body, it’s up to Gohan to stop the rampaging Ginyu!', 25, '1991-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 2), 35, 'Captain Ginyu... The Frog', 'As the bout between Captain Ginyu and Vegeta heats up, Goku summons the last of his strength and tricks his foe into reversing the Body Switch Technique. Now, Goku, Krillin, and Gohan must join forces with Vegeta for the battle with Frieza.', 25, '1991-01-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 3, 'Frieza Saga', 'All seven Namekian Dragon Balls have been assembled, and the dragon Porunga has been summoned. Goku and his loyal friends must stop Frieza from making his wish for immortality. To defeat this monstrous foe – a Super Saiyan must emerge!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 1, 'Password Is Porunga', 'Having acquired all seven Namekian Dragon Balls, Krillin and Gohan are ready to summon the dragon and make their wish. There’s just one problem: they don’t know the password!', 25, '1991-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 2, 'Piccolo''s Return', 'With the help of young Dende, Krillin and Gohan learn they will be granted three wishes! But even as Krillin and Gohan call upon the dragon, Vegeta races to the scene on a mission to wish for mortality!', 25, '1991-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 3, 'The Fusion', 'With the Dragon Balls gone and his plan in ruins, Frieza unleashes his fury upon Vegeta, Gohan, and Krillin. Elsewhere, the newly-revived Piccolo finds himself on Planet Namek. Will his arrival be enough to turn the tide?', 25, '1991-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 4, 'Fighting Power: One Million??', 'Frieza reveals a dark secret from Vegeta’s past, but the villain has an even more shocking secret in store for the Z-fighters! As the monster’s power level rises to terrifying new heights, all hope for the universe seems lost!', 25, '1991-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 5, 'Gohan Attacks', 'Frieza claims his first victim, Krillin, and Gohan must summon every ounce of his strength in order to save his friend. Can the young Saiyan put a stop to Freiza’s ruthless onslaught, or is he destined to become the next victim?', 25, '1991-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 6, 'Piccolo the Super-Namek', 'Gohan and Krillin continue their struggle against the overwhelming powers of Frieza, but as the fighting reaches its peak, a new warrior arrives on the battlefield to aid them in their efforts!', 25, '1991-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 7, 'Déjà vu', 'Piccolo quickly takes control of the battle with Frieza, and the putrid purple monster is shocked to learn the secret behind his opponent’s powers!', 25, '1991-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 8, 'Frieza''s Second Transformation', 'Just as it appears that Piccolo has gained the upper hand, Frieza quickly dashes all hopes for victory by revealing his second monstrous transformation!', 25, '1991-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 9, 'Another Transformation?', 'Unable to watch as Piccolo is overwhelmed by Frieza, Gohan springs into action! Meanwhile, Vegeta devises a risky plan for transforming himself into a Super Saiyan!', 25, '1991-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 10, 'Dende''s Demise', 'Having reached his ultimate form, Frieza is determined to destroy the remaining Z-fighters one by one, but Vegeta boldly announces the end of Frieza’s tyrannical reign! Are Vegeta’s claims true? Has he become a Super Saiyan?', 25, '1991-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 11, 'The Renewed Goku', 'Despite his new powers, Vegeta proves no match for Frieza! Meanwhile, Goku’s time in the rejuvenation chamber is nearly complete! Can he reach the battlefield in time to save his friends?', 25, '1991-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 12, 'The End of Vegeta', 'Goku rejoins his friends on the battlefield, but not before Vegeta is defeated by Frieza! As the Saiyan Prince clings to life by a thread, he reveals the secrets of his violent past.', 25, '1991-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 13, 'The Ultimate Battle', 'Feeling a new sense of connection to the dwindling Saiyan race, Goku wages war on the monstrous Frieza! As the fight intensifies, Frieza directs his energy blasts at Namek itself, turning the planet into a lava-spewing war zone!', 25, '1991-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 14, 'Clash of the Super Powers', 'Goku and Frieza continue their epic battle! An underwater attack puts Goku on top until Frieza traps him in an energy ball! It''s fun and games for Frieza, but the exploding ball may prove deadly for Goku!', 25, '1991-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 15, 'Frieza''s Boast', 'Frieza vows to beat Goku without using his hands, but the mighty Saiyan soon makes the mosnter eat his words! Elsewhere, Captain Ginyu uses his Body Switch Technique on Bulma, leaving her trapped in the body of a frog!', 25, '1991-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 16, 'Bold and Fearless', 'Captain Ginyu returns to the battlefield in Bulma''s body! Can Piccolo, Krillin, and Gohan handle this Femme Fatale? Later, Frieza powers up to fifty percent of his maximum, and Goku finds himself completely outmatched!', 25, '1991-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 17, 'Embodiment of Fire', 'Goku’s powerful Kaio-Ken attack has no effect on Frieza, who is still only fighting with fifty-percent of his power! Just as it seems Frieza has won the battle, a dream-like vision helps Goku ascend to a higher level of power and strength!', 25, '1991-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 18, 'Trump Card', 'Once again, Goku is rescued by a vision! This time, Vegeta talks to Goku from beyond the grave to offer new hope and encouragement! But when Goku realizes that the battle against Frieza is futile, he turns to his last resort: the Spirit Bomb!', 25, '1991-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 19, 'Keep the Chance Alive', 'Yamcha, Tien, and Chiaotzu find themselves in serious trouble when the Ginyu Force invades King Kai’s planet! Meanwhile, as Frieza thwarts Goku’s efforts to gather energy for the Spirit Bomb, Piccolo must enter the battle!', 25, '1991-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 20, 'Power of the Spirit', 'Chaos erupts on King Kai’s planet as the Z-fighters battle the Ginyu Force! Back on Planet Namek, the life and death struggle between Piccolo and Frieza rages on, and Goku completes his Spirit Bomb!', 25, '1991-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 21, 'Transformed at Last', 'A victory celebration comes to a halt when Frieza reappears! With no reserves left, Goku watches helplessly as Frieza directs his fury at Piccolo and Krillin. Enraged by the loss of his friends, Goku undergoes a wild transformation!', 25, '1991-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 22, 'Explosion of Anger', 'Engulfed in golden light, Goku announces that he is now a Super Saiyan! Frieza is unimpressed - until the fighting begins! In a raging battle, Frieza is horrified when he realizes that Goku is now superior to him in every way!', 25, '1991-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 23, 'Namek''s Destruction', 'Finding himself no match for Goku, Frieza attacks Planet Namek! Unable to react in time, Goku is forced to watch helplessly as the fiery blast rips through Namek’s core! Can anyone survive such incredible destruction?', 25, '1991-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 24, 'A Final Attack', 'With only minutes to go before the planet explodes, Frieza reaches his maximum power! Meanwhile, Gohan and Bulma race back to Goku’s spaceship. Can Goku defeat Frieza in time to rejoin his son and fly to safety?', 25, '1991-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 25, 'Approaching Destruction', 'The battle between Goku and Frieza rages on! Back on Earth, the seven Dragon Balls have been restored, but with Namek’s destruction imminent, can Kami and Mr. Popo summon the Eternal Dragon before it’s too late?', 25, '1991-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 26, 'Gohan Returns', 'Frieza’s victims have been wished back to life, but as they begin to rise, Goku falls - overwhelmed by Frieza’s devastating assault. Sensing his father’s defeat, Gohan rushes to the scene as the universe’s final hope.', 25, '1991-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 27, 'The Last Wish', 'Guru and the people of Namek have been brought back to life, and the dragon Porunga has reappeared to grant the last of three wishes. While a newly enraged Goku resumes his onslaught against the evil Frieza, Dende races to make the final wish!', 25, '1991-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 28, 'Duel on a Vanishing Planet', 'Goku chooses to stay behind and finish his fight with Frieza. With Namek set to explode any second, there seems no way for Goku to defeat Frieza and escape in time! Has the Super Saiyan made the greatest mistake of his life?', 26, '1991-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 29, 'Pathos of Frieza', 'Time grows short for Goku as each passing second brings Namek closer to ultimate destruction. As the Super Saiyan’s strength increases with every blow, it appears his epic battle with Frieza has at last reached its conclusion!', 25, '1991-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 30, 'Frieza Defeated!!', 'Frieza lashes out in a blind rage, launching a reckless volley of energy attacks. In the face of Goku’s superior power, the evil tyrant’s greatest fear has finally been realized: defeat at the hands of a Super Saiyan!', 25, '1991-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 31, 'Mighty Blast of Rage', 'Even after being sliced into pieces by his own energy disk, Frieza isn’t ready to release his stranglehold on the universe. With what little power he has left, Frieza fires a final energy blast after Goku as he leaves the battlefield!', 25, '1991-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 32, 'Namek''s Explosion... Goku''s End?', 'Even though it looks like Goku is trapped on the exploding planet Namek, Dende has a good reason to celebrate: the Dragon Balls have the power to bring Goku back! But if that’s the case, why does everyone still look so sad?', 25, '1991-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 3), 33, 'Goku''s Alive!!', 'It is a time of joyful reunions as old friends long absent are finally wished home with the Dragon Balls! Krillin and Yamcha are brought back from the spirit world, but Porunga, the Namekian dragon, has startling news about Goku!', 25, '1991-09-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 4, 'Androids Saga', 'After peace returns to Earth with the defeat of Freeza, a new danger approaches. A mysterious young man called Trunks appears from the future and warns Goku and the Z Warriors about the imminent arrival of two powerful androids created by the scientist Dr. Gero, a former member of the Red Ribbon Force who seeks revenge against Goku. The androids called 17 and 18 wiped out almost all of humanity in Trunks'' future.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 1, 'The Heavens Tremble', 'Gohan''s going fishing, Krillin''s found a girlfriend, and it looks as though peace has once again returned to the Earth. But a terrible evil lurks beneath this tranquil surface: Garlic Junior has escaped from the Dead Zone!', 25, '1991-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 2, 'Black Fog of Terror', 'With the help of the Spice Boys, Garlic Junior releases the Black Water Mist upon an unsuspecting world. As the dreaded fog spreads, so does Garlic Junior''s control over the Earth!', 25, '1991-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 3, 'Battle in Kami''s Lookout', 'As Piccolo attempts to hold off the Spice Boys and the infected Z Fighters, Gohan and Krillin race toward Kami’s Lookout to retrieve the one thing capable of reversing the effects of the Black Water Mist: the Sacred Water!', 25, '1991-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 4, 'Fight With Piccolo', 'With Piccolo infected by the Black Water Mist and Kami trapped in a glass bottle, Garlic Jr. allows his Spice Boys to “have sport” with Earth’s heroic defenders. Will Spice’s energy blast finish off Krillin for good?', 25, '1991-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 5, 'Call for Restoration', 'Krillin, after suffering a Spice Boys beating, attempts to free Kami and Mr. Popo, but he soon falls prey to the Black Water Mist. Gohan is the only hero left who can save the Earth, but can he do it with his two best friends against him?', 25, '1991-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 6, 'Suicidal Course', 'Piccolo and Krillin spring their trap, revealing that they have pretended to be infected by the Black Water Mist! Enraged, Garlic Jr. transforms using the energy of the Makyo Star and warns that the Sacred Water’s effectiveness will soon expire.', 25, '1991-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 7, 'Extreme Measures', 'Garlic Junior and his Spice Boys harness the evil power of the Makyo Star to become stronger than ever, but Gohan, Krillin, and Piccolo are ready to battle this new threat!', 25, '1991-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 8, 'The World Awakens', 'In a last ditch effort to save his friends, Gohan launches an all out assault on Garlic Junior! Meanwhile, deep within the Lookout, Kami and Mr. Popo are under siege by the Former Guardians!', 25, '1991-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 9, 'Brief Chance for Victory', 'Blinded by rage and desperate to destroy his enemies, Garlic Junior uses his power to open up the Dead Zone! With Piccolo and Krillin out of commission, Gohan is the only one left who can stop him!', 25, '1991-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 10, 'Krillin''s Proposal', 'Even though peace has been restored on Earth, Krillin faces his toughest challenge ever: surviving a shopping trip with Maron! And it looks like she’s picking out a wedding dress! Are Krillin and Maron planning to tie the knot?', 25, '1991-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 11, 'Frieza''s Counterattack', 'Gohan’s cracking the books, and his new tutor is cracking the whip! But study time is almost over, for a powerful evil is racing toward the Earth! Gohan’s worst fears have come to life: Frieza has survived!', 25, '1991-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 12, 'The Mysterious Youth', 'The Earth faces its darkest hour as Frieza and his father King Cold rapidly approach! Without Goku to assist them, the Z-Fighters prepare to launch a desperate attack against the most powerful evil the universe has ever known!', 25, '1991-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 13, 'Another Super Saiyan?', 'Frieza and King Cold descend upon the Earth, but a mysterious warrior has come to thwart their diabolical plot for revenge. Does this brash young hero have what it takes to stand up to these twin titans of evil?', 25, '1991-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 14, 'Welcome Back Goku', 'After defeating Frieza and King Cold, the mysterious stranger announces the exact time and place of Goku''s arrival on Earth. Can this young Super-Saiyan really predict the future?! Gohan and the others are determined to find out!', 26, '1991-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 15, 'Mystery Revealed', 'After testing Goku in combat, the mysterious stranger reveals his true identity! What does his timely arrival mean?! In a startling conversation with Goku, this powerful hero from the future tells all!', 25, '1992-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 16, 'Goku''s Special Technique', 'The future has been written - or has it? That’s what Goku and the rest of the Z-Fighters must decide as they hear Trunks’ ominous warning. The Androids are coming! And they just might be bringing the end of the world with them!', 25, '1992-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 17, 'Z Warriors Prepare', 'Gohan learns some new tricks, Vegeta pushes himself to the breaking point, and Yamcha struggles just to keep up as everyone prepares to face the looming Android menace! But will all their preparations be enough?', 25, '1992-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 18, 'Goku''s Ordeal', 'ChiChi wants a car! Goku and Piccolo take a day off from training to enroll in driving school. These two mighty warriors may be the Earth’s only chance for survival, but what are the chances they’ll learn how to parallel park?', 25, '1992-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 19, 'The Androids Appear', 'Three years have come and gone, and the day of reckoning has finally arrived! The Androids are here, and they’re wreaking havoc on an unsuspecting city! Goku and his friends must now put their training to the test!', 25, '1992-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 20, 'A Handy Trick', 'Yamcha is held at the mercy of the ruthless Android 20, and Goku and the others must race to help their friend. Believing their power to be far superior, the Androids tempt Goku’s rage by leveling half of the city!', 25, '1992-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 21, 'Double Trouble for Goku', 'The battle with the Androids begins as Goku launches an all out assault against Android 19. The Super Saiyan seems to have the fight under control, but something is about to go horribly wrong!', 25, '1992-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 22, 'Upgrade to Super Saiyan', 'Attacked from within by a crippling virus, Goku is helpless against the maniacal Android 19. But just when it looks like the end for Goku, Vegeta appears on the scene! And he’s got a few big surprises in store for the Androids!', 25, '1992-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 23, 'The Secret of Dr. Gero', 'In his first fight as a Super Saiyan, Vegeta takes control of the battlefield and defeats Android 19 in convincing fashion! Unwilling to share 19’s fate, Android 20 runs for cover in the mountains!', 25, '1992-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 24, 'More Androids?!', 'Vegeta, Piccolo, and Gohan lead an exhaustive search through the mountains for Android 20. But the hunters are also the hunted! Android 20 lurks in the shadows, ready to strike, and it looks like Piccolo is his first target!', 25, '1992-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 25, 'Follow Dr. Gero', 'Our heroes make a startling discovery: Android 20 is none other than Dr. Gero himself! Before they can act on this new knowledge, the diabolical doctor flees to his secret laboratory, where he intends to awaken more killer androids!', 25, '1992-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 26, 'Nightmare Comes True', 'The race is on, as the Z-Fighters search frantically for Dr. Gero’s hidden laboratory! But rather than stop the androids before they’re activated, Vegeta wants a challenge! Despite Trunks’ warning, he chooses to fight the androids alone', 25, '1992-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 27, 'Goku''s Assassin', 'Dr. Gero escapes to his mountain hideout and brings his killer androids to life. Without the help of Goku, all hope seems lost. Dr. Gero appears one step closer to ultimate vengeance, but his evil creations have a vendetta of their own!', 25, '1992-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 28, 'Deadly Beauty', 'Vegeta and Android 18 have a showdown on the highway. Trunks and the others are there to help, but the Saiyan prince insists on fighting his opponent man-to-android! Will Vegeta’s overconfidence be his undoing?', 25, '1992-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 29, 'No Match for the Androids', 'In an earthshaking battle, the beautiful Android 18 brings Vegeta to his knees. But before she can deliver the final blow, Trunks steps in to help. Soon an all out war between good and evil begins, and the androids have the upper hand.', 25, '1992-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 30, 'Last Ditch Effort', 'Vegeta, Trunks, Tien, and Piccolo realize a grim truth: unless they can increase their powers quickly, they’ll have no chance against the androids. In a drastic move, Piccolo flies to Kami’s Lookout and makes a most unexpected proposal!', 25, '1992-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 31, 'Closing In', 'The androids hit the road in pursuit of Goku, but they’re delayed by some hyperactive hoodlums. Krillin and Trunks race to move Goku to a safer hiding place, and Kami wrestles with Piccolo’s difficult offer.', 25, '1992-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 4), 32, 'Unwelcome Discovery', 'The Z-fighters retreat to Master Roshi’s house to plan their next move. Meanwhile, Bulma makes a startling discovery: the wreckage of a second time capsule! Where did it come from, and more importantly, who was in it?', 25, '1992-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 5, 'Cell Saga', 'As the battle with the Androids rages on, a fierce evil rises from the shadows: the monster known as Cell. Dr. Gero’s heinous creation is the ultimate weapon, a fighting machine built from the genetic material of the greatest warriors ever to walk the Earth!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 1, 'Seized with Fear', 'Trunks and Krillin join Bulma at the crash site of the mysterious time capsule and find an eerie clue: the shell of a large, locust-like creature! Whatever arrived in the time capsule isn’t human, and it’s on the loose!', 25, '1992-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 2, 'The Reunion', 'An insect-like monster threatens to turn Gingertown into a ghastly graveyard! In response to this new menace, Kami fuses with Piccolo, and the resulting Super Namekian flies to Gingertown for a showdown of epic proportions!', 25, '1992-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 3, 'Borrowed Powers', 'Gingertown becomes a battlefield as Piccolo confronts Cell. This monster from the future gains his strength by sucking the life out of his victims! But that’s not the creature’s only talent. He also knows the Kamehameha Wave!', 25, '1992-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 4, 'His Name is Cell', 'Heavily-armored tanks fail to halt Cell’s rampage, and now it’s up to Piccolo to stop the monster! As the Namekian fights for survival, Cell reveals that he’s actually an android, the ultimate achievement of Dr. Gero!', 25, '1992-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 5, 'Piccolo''s Folly', 'Piccolo cleverly distracts Cell long enough to regenerate his arm. The Namekian is ready for another round, and Krillin and Trunks have arrived to provide backup! With the odds mounting against him, Cell makes a tactical decision.', 25, '1992-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 6, 'Laboratory Basement', 'With hopes of saving the future, Trunks and Krillin race to destroy Dr. Gero’s lab. Meanwhile, Piccolo and Tien search for the elusive Cell. But how can they stop an enemy who knows their every move?', 25, '1992-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 7, 'Our Hero Awakes', 'In South City, Cell plows through more civilians and accidentally runs into Krillin! Goku finally gets back on his feet, but with Cell and the other androids in full stride, can the Saiyan hero still make a difference?', 25, '1992-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 8, 'Time Chamber', 'As Cell continues his deadly march, Goku hatches a plan to squeeze a year’s worth of training into just one day! Back at Master Roshi’s, the android trio arrives looking for Goku! Can Piccolo hold them off until the Saiyans return?', 25, '1992-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 9, 'The Monster is Coming', 'Behind the closed doors of the Hyperbolic Time Chamber, Vegeta and Trunks struggle to push past the level of Super Saiyan! Down on Earth, Piccolo challenges Android 17 to a battle!', 25, '1992-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 10, 'He''s Here', 'Stronger than ever after fusing with Kami, Piccolo leads the attack against the androids! It looks like the Super Namekian has things under control until Cell arrives on the battlefield! Can anyone stop this hideous monster?!', 25, '1992-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 11, 'Up to Piccolo', 'Just as Cell is about to absorb Android 17, Piccolo bravely steps in and foils the monster’s plan! Does the Super Namekian really have a chance at stopping Cell on his own?! Or is he simply putting off the inevitable?', 25, '1992-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 12, 'Silent Warrior', 'When Android 16 claims to be as strong as Cell, it seems like a wild boast! But after he launches an offensive that throws Cell against the ropes, it becomes clear that the big android has the power to back up his words!', 25, '1992-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 13, 'Say Goodbye, 17', 'It’s android against android as 16 clashes with Cell. Android 16 is the stronger fighter, but Cell is far too driven to be stopped now! With an underhanded attack, Cell moves one step closer to his gruesome transformation!', 25, '1992-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 14, 'Sacrifice', 'With an onslaught of psychic blasts, Tien gives Androids 16 and 18 a chance to escape, but the powerful attack rapidly drains his strength. Tien may have saved the androids, but can he save himself?', 26, '1992-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 15, 'Saiyans Emerge', 'Trunks and Vegeta emerge from the time chamber after a year of intense training. Goku and Gohan are next into the room, but with Cell nearing his ultimate form, can the fighters afford to wait another day?', 25, '1992-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 16, 'Super Vegeta', 'Cell obliterates a chain of islands in search of Android 18! Vegeta, fresh from the time chamber, is ready to test his new strength against the monster, but is he really stronger than a Super Saiyan?', 25, '1992-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 17, 'Bow to the Prince', 'It’s show-and-tell for Vegeta as he demonstrates how much difference a year of training can make! Meanwhile, back in the time chamber, Gohan struggles to become a Super Saiyan.', 25, '1992-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 18, 'Hour of Temptation', 'Vegeta quickly pounds Cell six feet into the ground! With his back against the wall, the monstrous android attacks Vegeta’s weakest point: his arrogance! Can the Saiyan Prince resist Cell’s tempting challenge?', 25, '1992-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 19, 'Krillin''s Decision', 'With beautiful Android 18 in his sights, Krillin clutches the controller that will shut her down forever. But when the moment arrives, the little man hesitates! All the while, Cell looms overhead, hungry for perfection!', 25, '1992-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 20, 'The Last Defense', 'With the remote control smashed, Krillin and Trunks must save Android 18 from Cell’s power-hungry grasp. But Vegeta has other plans in mind. Will trunks attack his own father to save humanity?', 25, '1992-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 21, 'Cell is Complete', 'The earth’s greatest fear has come true: Cell is complete! Can anyone stop the android nightmare in his final, perfect form? As the heroes nervously line up, a glimmer of hope shines from above. Gohan is a Super Saiyan!', 26, '1992-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 22, 'Vegeta Must Pay', 'After allowing Cell to reach his final form, Vegeta is ready for the challenge he was promised. But as Cell easily deflects the Saiyan’s every blow, it’s clear that Vegeta has more on his hands than he bargained for!', 25, '1992-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 23, 'Trunks Ascends', 'Tapping into the deepest wells of his energy, Vegeta summons one last attack: the Final Flash! Meanwhile, Trunks struggles to decide whether or not to help his father. Vegeta’s pride is at stake, but so is his life!', 25, '1992-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 24, 'Saving Throw', 'Vegeta lies unconscious after his battle with Cell, and Trunks unleashes his hidden powers to save his father’s life. With Goku and Gohan still training, Trunks is the only person standing in the evil android’s way.', 25, '1992-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 25, 'Ghosts from Tomorrow', 'Trunks vows to stop the future from repeating itself; Cell can’t wait for the future to unfold. It’s all up for grabs as the two warriors prepare for battle. Only one future will survive. Whose will it be?', 25, '1992-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 5), 26, 'The Cell Games', 'Realizing that his powers are no match for his opponent, Trunks accepts defeat, only to be given a second chance when Cell proposes a tournament! Is Cell really interested in competition, or does he have a sinister motive?', 25, '1992-11-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 6, 'Cell Games Saga', 'Humanity nears extinction as Cell achieves his deadly perfect form! Eager to display his new power, the monster proposes a tournament. If Earth produces a worthy challenger, whether be it Goku or Mr. Satan, mankind will be spared. But if not – death comes to all!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 1, 'What is the Tournament?', 'While Trunks tells the others of Cell’s plans to hold a tournament, the diabolical android begins his preparations for the competition by constructing a fighting arena. Do the Z-Fighters have a chance, or is this a contest that only Cell can win?', 25, '1992-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 2, 'The Doomsday Broadcast', 'Cell breaks into showbiz, literally! The sinister android hijacks a television station in order to announce his "Cell Games" to the world! But are there any challengers left with the strength and courage to get into the ring?', 25, '1992-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 3, 'Meet Me in the Ring', 'Panicked Earthlings flee their homes to escape Cell’s wrath, but all hope is not lost! Back at the Lookout, Goku and Gohan finally emerge from the Time Chamber. After a quick trip to size up the competition, Goku is ready to battle Cell!', 25, '1992-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 4, 'No Worries Here', 'With nine days until Cell''s tournament begins, Vegeta, Piccolo, and Trunks plan to return to the Hyperbolic Time Chamber. But Goku decides that he and Gohan have had enough training! What does Goku know that the others don''t?', 25, '1992-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 5, 'A Girl Named Lime', 'Gohan stumbles upon a village that has retreated to a nearby shelter, and when he discovers that the owner of the shelter is capitalizing on the villagers'' fear of Cell, he comes up with a Super Saiyan solution to the problem!', 25, '1993-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 6, 'Memories of Gohan', 'As the Cell Games draw near, Goku enjoys his remaining time with friends and family! First he fishes with Krillin, then he strolls down memory lane with Chichi, and finally it''s time for a very special boy to blow out the candles!', 25, '1993-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 7, 'A New Guardian', 'When the Royal Military foolishly tries to stop Cell with ordinary weapons, the attack quickly becomes a suicide mission! Goku is determined to revive the fallen soldiers, but that will require new Dragon Balls!', 25, '1993-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 8, 'Dende''s Dragon', 'With help from King Kai, Goku travels to Namek to recruit a new guardian for the Earth! Most of the Namekians refuse the offer, but there’s one little guy who can’t wait to go! Dende is back, and he’s going to create a new Dragon!', 25, '1993-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 9, 'The Puzzle of General Tao', 'Goku comes face to face with an old adversary: General Tao! The search for the Dragon Balls led Goku to the aging general, but unless the Super Saiyan can solve the crafty villain’s puzzle, the search may end in vain!', 25, '1993-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 10, 'The Games Begin', 'The wait is over, and the Cell Games are ready to begin! The Z-Fighters arrive ringside, only to discover another challenger already on the scene. It’s none other than World Martial Arts Champion, Mr. Satan!', 25, '1993-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 11, 'Losers Fight First', 'Caroni and Pirozhki, Mr. Satan’s top students, make a spectacular entrance to the ring, but are they really ready to rumble with Cell? Don’t miss a minute of the fun, because this fight could be over fast!', 25, '1993-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 12, 'Goku vs. Cell', 'The main event begins! Now free of distraction, Goku steps into the ring to face Cell. The Earth shakes and the heavens tremble as these mighty super warriors collide! And that’s just the warm up!', 25, '1993-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 13, 'Cell''s Bag of Tricks', 'Cell attacks Goku with a dazzling array of moves: the Destructo Disk, the Special Beam Cannon, even the Kamehameha Wave! So far, Goku has been able to match Cell blow for blow, but how will the Super Saiyan fare against such a lethal arsenal?', 25, '1993-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 14, 'No More Rules', 'As the battle intensifies, Cell quickly grows tired of the rules he created for the tournament. With a flick of his finger, the Android destroys the ring, instantly turning the Cell Games into a deadly fight to the finish!', 25, '1993-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 15, 'The Fight is Over', 'Goku blasts Cell with a Kamehameha Wave that reduces the android to a pile of cinders, but his triumph is short-lived. The monster shows his amazing resilience by fully regenerating himself!', 25, '1993-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 16, 'Faith in a Boy', 'After surrendering to Cell, Goku names the next challenger to enter the Cell Games: Gohan! Goku has supreme faith in his son’s abilities, but the young Saiyan will need a lot more than his father’s confidence if he’s going to survive!', 25, '1993-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 17, 'Gohan''s Plea', 'The fight between Gohan and Cell intensifies, but the villain’s attacks seem to have no effect on the boy! Could the young hero really have the power to defeat the evil android once and for all?', 25, '1993-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 18, 'Android Explosion', 'Cell is determined to unleash Gohan’s full potential, but the boy refuses to fight, prompting the android to torture Gohan’s friends instead! Next, Cell does the unthinkable by spawning miniature Cells to attack the Z-Fighters!', 25, '1993-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 19, 'Cell Juniors Attack!', 'Gohan boils with rage as the Cell Juniors wreak havoc on the Z-Fighters. The boy struggles to resist the urge to fight, but he’s a powder keg waiting to explode, and Android 16 appears ready to light the fuse!', 25, '1993-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 20, 'Awakening', 'Spurred by Android 16’s dying words, Gohan’s hidden power is finally unleashed! With his new strength and speed, Gohan easily destroys the wicked Cell Juniors, but his sights are set on a bigger target!', 25, '1993-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 21, 'The Unstoppable Gohan', 'Cell’s desire for battle turns into a nightmare as Gohan unleashes the full fury of his strength. The evil android powers up to his maximum level, but will it be enough to spare him from the wrath of Super Saiyan?', 25, '1993-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 22, 'Cell''s Break Down', 'Gohan’s Super Saiyan strength appears to have no limit, and the young hero delivers a blow so severe it causes Cell to cough up Android 18! As the monster wears down, Gohan prepares to end the battle once and for all!', 25, '1993-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 23, 'A Hero''s Farewell', 'Clearly overmatched by Gohan, Cell initiates his last line of defense: a self-destruct program that will blow up the entire planet! With only seconds to spare, Goku risks everything to transport Cell away from the Earth.', 25, '1993-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 24, 'Cell Returns!', 'The nightmare continues! Cell explodes, but a particle of his nucleus survives the blast, providing all the android needs to regenerate himself! Restored to his ultimate form, Cell returns to the Earth more powerful than ever!', 25, '1993-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 25, 'The Horror Won''t End', 'After easily dispensing of both Trunks and Vegeta, Cell announces a new plan. First, he’ll destroy the Earth, and after that, the Universe will be his next target! Can this weapon of ultimate destruction be stopped?', 25, '1993-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 26, 'Save the World', 'The final showdown begins! While Goku telepathically coaches Gohan from the Other World, the Z-Fighters jump in for a five-sided attack! Gohan has the potential inside him, but can Goku show him how to unlock it?', 25, '1993-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 27, 'Goku''s Decision', 'Cell is finally defeated, but the Z-Fighters still have much to resolve! Can they make it to the Lookout in time to heal the badly-injured Gohan? Is Android 18 still a threat? And can our heroes find a way to bring back Goku?', 25, '1993-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 28, 'One More Wish', 'After Goku’s decision to stay in the after-world, Krillin uses the final wish to save Android 18, but does he have the courage to reveal his true feelings? And is anyone brave enough to break the news of Goku''s passing to Chichi?!', 25, '1993-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 6), 29, 'Free the Future', 'Peace and order have been restored on Earth in the present, but Trunks’ future world is still a place of darkness and despair! Once he arrives home, the future will be forever changed!', 25, '1993-07-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 7, 'World Tournament Saga', 'In the seven years since Cell’s defeat, life on Earth has returned to normal. But now, the time has come for a new World Martial Arts Tournament. Goku returns from Other World to challenge Mr. Satan for his title – and to guard against the arrival of a new evil!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 1, 'Warriors of the Dead', 'When Goku hears about a martial arts master known as the Grand Kai, he rushes to meet him for a lesson! Meanwhile, Cell, Frieza, King Cold and the Ginyu Force have teamed up to take control of Other World!', 25, '1993-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 2, 'Tournament Begins', 'Goku must train for 10,000 years before he can study under the Grand Kai! But when the West, South, and East Kai’s decide to hold an Other World Tournament, Goku gets his chance! All he has to do is defeat the greatest fighters of all time!', 25, '1993-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 3, 'Water Fight', 'The Other World Tournament advances to the Quarter-Finals, and the battles are out of this world! Goku''s opponent, Arqua, appears to be a wimp, but things change quickly when he transforms the entire ring into water!', 25, '1993-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 4, 'Final Round', 'Goku advances to the final round of the tournament where he will face the warrior Pikkon! Sparks of energy fly as the brawlers battle for the title! When Pikkon reveals a Piccolo-like secret, Goku must up the ante! It''s Super Saiyan time!', 25, '1993-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 5, 'Goku vs. Pikkon', 'Goku may be a Super Saiyan, but can he withstand Pikkon''s unbelievable Thunder Flash Attack?! And that''s not all! While Goku''s been fighting in Other World, seven years have passed on Earth, Gohan is now a teenager!', 25, '1993-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 6, 'Gohan Goes to High School', 'On his first day of high school, Gohan stops a truckload of bank robbers by turning Super Saiyan. Now, the city can''t stop talking about this mysterious "Gold Fighter!” Can Gohan get through class without revealing his secret identity?', 25, '1993-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 7, 'I Am Saiyaman!', 'Afraid he’ll be recognized by his classmates, Gohan gets Bulma to design a retractable super-hero costume that he can activate in an instant. Say goodbye to Gohan - and hello to Saiyaman!', 25, '1993-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 8, 'Gohan''s First Date', 'Gohan thinks being a super-hero is a snap until a pretty girl named Angela discovers his secret. When Angela threatens to tell all unless he goes on a date with her, Gohan''s life suddenly becomes more complicated than ever!', 25, '1993-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 9, 'Rescue Videl', 'When the Red Shark Gang kidnaps the mayor and demands a showdown with Mr. Satan, it''s Videl who answers the challenge. Gohan knows Videl is in over her head, but he can''t leave his classroom to help her without blowing his cover!', 25, '1993-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 10, 'Blackmail', 'When a greedy circus promoter kidnaps a baby dinosaur, all he sees are dollar signs! Little does he know, that the dinosaur is a close, personal friend of the Great Saiyaman!', 25, '1993-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 11, 'I''ll Fight Too!', 'Lights! Camera! Action! The Great Saiyaman is about to become a movie star! But the hero’s brush with stardom better not take long, because he has to hurry up and tell all of his old friends the big news: Goku’s coming back!', 25, '1993-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 12, 'The Newest Super Saiyan', 'While training for the upcoming tournament, Gohan discovers that Goten has already reached the level of Super Saiyan! Sparks fly when the brothers spar, but the main event happens when Videl meets Chichi for the first time!', 25, '1993-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 13, 'Take Flight, Videl', 'With the Tournament fast approaching, Videl and Goten must learn to fly! Miles away, Vegeta holds a training session of his own, and his young son, Trunks, has a big surprise in store for him', 25, '1993-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 14, 'Gather for the Tournament', 'Videl learns to fly, and Gohan and Goten do some last minute honing of their Super Saiyan skills. On the island where the tournament will be held, a special guest arrives! What do you say to a hero who''s been dead for seven years?!', 25, '1993-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 15, 'Camera Shy', 'High school jock, Sharpner, discovers his crush, Videl, has her heart set on the mysterious Great Saiyaman! Refusing to be replaced, Sharpner vows to ruin the caped fighter by unmasking his true identity and capturing it on film!', 25, '1993-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 16, 'The World Tournament', 'The action begins as the World Martial Arts Tournament opens with the Junior Division! Thirty-five young fighters vie for the prize, but the matches prove to be more comedy than competition - until Trunks steps into the ring!', 25, '1993-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 17, 'Trunks vs. Goten', 'Goten and Trunks breeze through the Junior Division of the tournament until they find themselves going head-to-head in the finals! Who will win this exciting match? This is one championship fight you won''t want to miss!', 25, '1993-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 18, 'Best of the Boys', 'The match for the Junior Division World Championship continues as Goten and Trunks battle for the title! The winner of this final joust becomes the new World Champion! Can Goten outwit the cunning Trunks?', 25, '1994-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 19, 'Big Trouble, Little Trunks', 'After winning the championship, Trunks fights an exhibition match against Mr. Satan! Can the Champ hold on to his reputation as the world''s strongest fighter? Meanwhile, two mysterious figures reveal themselves to Goku!', 25, '1994-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 20, 'Who Will Fight Who?', 'Trunks and Gohan infiltrate the adult competition at the tournament by donning the disguise of Mighty Mask. The pairings for the day’s matches are selected. The first to fight: Krillin vs. Pintar, a man easily ten times Krillin’s size!', 25, '1994-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 21, 'Forfeit of Piccolo', 'Piccolo stuns the crowd by surrendering to his mysterious opponent before the first punch is thrown! Next into the ring is Videl, who must face the enormous Spopovitch. Will she be able to handle such a large job?', 25, '1994-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 22, 'A Dark and Secret Power', 'Videl takes to the ring for what is expected to be an easy victory over Spopovitch. She hits the towering brute with everything she’s got, but her attacks have no effect. It seems Spopovitch is possessed by a supernatural power!', 25, '1994-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 23, 'Videl Is Crushed', 'To everyone’s horror, Spopovitch delays his inevitable victory for the purposes of torturing Videl! It appears the muscle-bound thug isn’t going to stop until he kills her! Will Videl make it out of the ring alive?', 25, '1994-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 24, 'Identities Revealed', 'Gohan’s identity is finally discovered as he takes his place on the tournament floor, but he has bigger things to worry about. His opponent, Kibito, is determined to see him transform into a Super Saiyan!', 25, '1994-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 7), 25, 'Energy Drain', 'When Gohan transforms into a Super Saiyan, Spopovitch and Yamu spring into action! Armed with a mysterious energy-draining device, the pair launch an attack on the golden-haired teen.', 25, '1994-03-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 8, 'Majin Buu Saga', 'The evil wizard Babidi embarks on a quest for vengeance, seeking to fulfill his father''s thwarted dreams of universal domination. Supreme Kai enlists Goku and the Z-Fighters to stop Babidi and his vile minions, but a deadly new threat emerges – Majin Vegeta!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 1, 'The Wizard''s Curse', 'The Z-Fighters race to stop Babidi’s cronies from delivering the pure energy that will be used resurrect the dreaded Majin Buu. Will they find Babidi’s hidden spaceship in time?', 25, '1994-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 2, 'King of the Demons', 'Piccolo and Krillin are turned to stone by Dabura! Determined to save their friends, Goku, Gohan, and Vegeta board Babidi’s ship only to find themselves trapped! Can they save their friends and find their way out?', 25, '1994-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 3, 'Vegeta Attacks', 'At each stage of Babidi’s ship, Goku, Gohan, and Vegeta must face a fearsome warrior, each more powerful than the last. There’s no room for error! Even the tiniest mistake will enable Babidi to steal their energy for Majin Buu!', 25, '1994-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 4, 'Next Up, Goku', 'Babidi unleashes his monster Yakon to steal the Z-Fighters’ energy for Majin Buu. The battle at Stage Two is sure to be intense, as Yakon is one of the most fearsome creatures in the universe!', 25, '1994-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 5, 'Battle Supreme', 'At the World Martial Arts Tournament, the five remaining competitors enter the ring for an all-out Battle Royale! The fists fly as Number 18, Mighty Mask, and Mr. Satan duke it out to decide who will be the next Champion of the World!', 25, '1994-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 6, 'Eighteen Unmasks', 'The battle heats up as Number 18 and Mighty Mask take their fight to the skies! Number 18 gives it everything she’s got, but her attacks prove useless against her masked opponent. Could she find the edge she needs to win?', 25, '1994-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 7, 'Pay to Win', 'As the final bout of the tournament continues, Number 18 throws the defending champ for a loop by offering to throw the fight! Meanwhile, Babidi has selected his warrior for Stage 3: Dabura, King of the Demon World!', 25, '1994-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 8, 'Heart of a Villain', 'The intense battle between Gohan and Dabura rages on, but just as the Stage 3 clash reaches a heated peak, Dabura stops the fight! Why has the evil giant conceded, and what is the great discovery he claims to have made?', 25, '1994-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 9, 'The Dark Prince Returns', 'In an all-out assault against Vegeta, Babidi uses his power to undo the unsuspecting Prince from within! Vegeta is stripped of his good qualities by the wicked wizard, and becomes the heartless warrior that he once was!', 25, '1994-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 10, 'Vegeta''s Pride', 'Evil Vegeta gives Goku an ultimatum: fight - or watch him annihilate more innocent lives! Goku vows to settle the score between them once and for all, but the Supreme Kai steps between the Saiyans with a bold declaration!', 25, '1994-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 11, 'The Long Awaited Fight', 'The battle between Goku and Vegeta has begun! With Babidi’s magic enhancing his already incredible strength, Vegeta matches Goku move for move, but every blow the Saiyan Prince lands is a boost for Majin Buu!', 25, '1994-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 12, 'Magic Ball of Buu', 'With the fight between Goku and Vegeta supplying vast quantities of energy for Majin Buu, there’s not a moment to lose! Can Gohan muster up the strength to stop the evil wizard before it’s too late?', 25, '1994-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 13, 'Buu Is Hatched', 'The seal encasing Buu is finally broken! Supreme Kai insists on retreat, but Gohan refuses, launching an incredible series of energy attacks. When the shell opens, nothing is inside! Gohan, however, knows it’s no time to celebrate.', 25, '1994-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 14, 'The Losses Begin', 'With his big pink belly and infantile behavior, Buu doesn’t fit the bill of a galaxy destroyer - until he hurls Dabura into a cliff with a single blow! Gohan senses a limitless power, and the Supreme Kai insists this is the end!', 25, '1994-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 15, 'The Terror of Mr. Buu', 'Supreme Kai must use his unique fighting powers to keep Buu at bay - or lose his life! One mile away, Goten and Trunks stumble upon Piccolo, still frozen in stone, and accidentally shatter him to pieces! And there’s more! The King of Demons returns!', 25, '1994-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 16, 'Meal Time', 'Free from the grip of Babidi, Vegeta decides to seek his revenge by destroying the monster Majin Buu. Assuming Gohan to be a victim of the voracious villain, the Super Saiyan goes ballistic. Can Vegeta bring down Buu?', 25, '1994-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 17, 'The Warrior''s Decision', 'With Goku and Gohan missing in action, it’s up to Vegeta to end Majin Buu’s reign of terror. The Saiyan prince gives it his all, but Buu’s powers may be more than he can handle!', 25, '1994-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 18, 'Final Atonement', 'Trunks and Goten save Vegeta from a savage beating, but the prideful prince is determined to destroy Majin Buu by himself. Vegeta is prepared to risk everything to defeat this foe, but is he really ready to give up his own life?', 25, '1994-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 19, 'Evil Lives On', 'Majin Buu’s flesh is scattered on the battlefield, but his mystical power is rebuilding the monster into one deadly piece! Babidi is recovering, too, having narrowly survived Piccolo’s attack!', 25, '1994-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 20, 'Find the Dragon Balls', 'Anxious to undo the massacre caused by Vegeta, Bulma and the others search frantically for the seven Dragon Balls! Meanwhile, the injured Goku finally awakens, and Dende uses his healing powers to bring him back to speed!', 25, '1994-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 21, 'Revival', 'Goku hatches a plan for defeating Majin Buu: Fusion! By joining two fighters of equal size and strength, an entirely new fighter can be created. But only one such pair remains—Goten and Trunks! Can the young half-Saiyans save the world?', 25, '1994-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 22, 'Global Announcement', 'Babidi seeks vengeance against Piccolo, Goten, and Trunks! Plastering images on everyone’s mind, Babidi threatens to terrorize humanity until the trio is brought forward! Meanwhile, Gohan is taken to Supreme Kai’s world!', 25, '1994-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 23, 'Learn to Fuse!', 'Goku begins training Goten and Trunks in the art of Fusion. Meanwhile, Gohan, having been healed in Supreme Kai’s world, tries to remove the legendary Z-Sword to use in the fight against Majin Buu!', 25, '1994-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 24, 'The Z Sword', 'Majin Buu launches into a feeding frenzy, transforming an entire town’s population into chocolate! Gohan draws the ancient Z-Sword, Goku struggles to teach Goten and Trunks the art of Fusion, and an unlikely hero is asked to join the fight!', 25, '1994-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 25, 'Race to Capsule Corp.', 'As Goten and Trunks train to stop the vicious Majin Buu, Idasa’s jaded mother tells Babidi exactly where Trunks lives! The Z-Fighters must now find a way to stop the evil wizard before he reaches Capsule Corp!', 25, '1994-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 26, 'Super Saiyan 3?!', 'Trunks searches frantically for the lost dragon radar, and Goku powers-up to an unimaginable level: Super Saiyan 3! Will this newfound strength be enough to stop Majin Buu from destroying West City?', 25, '1994-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 27, 'Buu''s Mutiny', 'Goku uses his new Super Saiyan 3 abilities to combat the evil Majin Buu, buying Trunks the time he needs to locate the missing Dragon Radar. But now that Goku has started the fight, he may not be able to escape!', 25, '1994-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 28, 'The Fusion Dance', 'Liberated from his master, Majin Buu becomes even more destructive than before, wiping out entire cities in mere seconds! Earth’s only hope now rests on the shoulders of two young warriors: Goten and Trunks!', 25, '1994-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 29, 'Goku''s Time Is Up', 'Tensions rise for Goten and Trunks as their duel with Majin Buu approaches. Meanwhile, Buu prepares for the upcoming battle by building himself a home! Elsewhere, Goku bids a poignant farewell as he finally returns to Other World.', 25, '1994-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 30, 'Return to Other World', 'While Trunks and Goten continue their quest to perfect the Fusion Technique, Gohan seeks to master the Z-Sword. Back on Earth, an encounter with a blind boy reveals that there is another side to the belligerent Buu!', 26, '1994-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 31, 'Out from the Broken Sword', 'When Gohan’s intense training breaks the legendary Z-Sword, all hope seems lost until Old Kai emerges and from the legendary weapon. Who is this aged fellow, and does he really have the incredible power he claims to possess?', 26, '1994-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 32, 'Gotenks Is Born', 'After many comical misfires, Trunks and Goten finally perfect the Fusion technique, and Gotenks is born! Defying Piccolo’s command, the super-kid immediately leaves to go fight Majin Buu! Is Gotenks ready for the fight of his young life?', 26, '1994-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 33, 'Unlikely Friendship', 'As Majin Buu continues to terrorize humanity, a lone savior appears: Mr. Satan! His Megaton punch won’t be enough to stop the monster, but this unlikely hero may have a few surprises in store for Buu!', 26, '1995-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 8), 34, 'I Kill No More', 'While the Z-Fighters continue training in preparation for their battle with Majin Buu, Mr. Satan devises some sneakier plans to take the villain down. But will he even need to carry them out? Is Majin Buu having a change of heart?', 26, '1995-01-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')), 9, 'Kid Buu Saga', 'Majin Buu''s rampage continues, and the only hope of defeating this terrifying foe is the Fusion Technique. For this desperate plan to succeed, two fierce rivals, Goku and Vegeta, must combine their powers in a heroic attempt to stop Majin Buu once and for all!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 1, 'The Evil of Men', 'When Mr. Satan inspires Majin Buu to give up his evil ways, it seems the professional pretender has really saved the world! But when a deranged madman suddenly spoils Buu’s good mood, the pink terror goes on another rampage!', 26, '1995-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 2, 'Buu Against Buu', 'The Battle of the Buus begins as Majin Buu fights his evil counterpart! The good Buu gets a taste of his own medicine when he’s turned into chocolate! Evil Buu gobbles him up, and a horrible transformation takes place! Who is this radical new Buu?', 26, '1995-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 3, 'Empty Planet', 'When the new and improved Majin Buu makes a surprise visit to the Lookout to challenge Gotenks, every second becomes a test of survival! And where are Trunks and Goten during the chaos that erupts?... Sound asleep, of course!', 26, '1995-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 4, 'Time Struggle', 'Before he can unleash his fury on the remaining Z-Fighters, Majin Buu is coaxed into the Hyperbolic Time Chamber. Inside, Trunks and Goten are training diligently, but will they have enough time to perfect their new moves before Majin Buu arrives?', 26, '1995-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 5, 'Super Moves of Gotenks', 'The long awaited rematch between Majin Buu and Gotenks begins! But when Gotenks’ fighting techniques come up short, he is forced to improvise - resulting in some of the craziest attack moves ever!', 26, '1995-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 6, 'Trapped in Forever', 'The battle between Gotenks and Majin Buu rages on inside the Hyperbolic Time Chamber. On the outside, family and friends wait anxiously for Gotenks and Piccolo to reappear. Can they successfully defeat Majin Buu and make it out alive?', 26, '1995-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 7, 'Feeding Frenzy', 'Powered by his insatiable hunger, Majin Buu escapes the Hyperbolic Time Chamber, leaving Piccolo and Gotenks trapped inside. Krillin and the gang are forced to fight the monster on their own. Will Buu finally make a meal out of the good guys?', 26, '1995-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 8, 'Gotenks Is Awesome!', 'Super Saiyan 3 Gotenks continues his fight with Majin Buu, and the Lookout is caught in the crossfire! As Gotenks turns up the power, so does Majin Buu - and by the time it’s over, one of them will be in way over his head!', 26, '1995-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 9, 'Unlucky Break', 'Gohan continues his training on the World of the Kais. Meanwhile, Gotenks briefly takes the upper hand in the battle with Majin Buu before his techniques begin to fall apart. Will Gohan be ready in time to step in and finish the fight?', 26, '1995-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 10, 'A Whole New Gohan', 'When Gotenks’ fusion unravels, it appears the end has finally come for Goten and Trunks. But just as things seem their worst, Gohan descends on the scene with his newly awakened powers! Finally, the tables are turning on Majin Buu!', 26, '1995-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 11, 'Search for Survivors', 'After being dominated on the battlefield, Majin Buu blows himself up in a desperate attempt to destroy Gohan! But is this just a ploy? Gohan seems to think so! Is Majin Buu plotting an ambush or simply trying to buy a little time?', 26, '1995-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 12, 'Majin-Buu Transforms', 'Majin Buu reappears, ready for battle, but rather than continue his fight against Gohan, Buu stages a clever deception to absorb Gotenks and Piccolo. With the wisdom of Piccolo and the power of Super Saiyan Gotenks, Buu transforms into “Super Buu!”', 26, '1995-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 13, 'The Old Kai''s Weapon', 'After absorbing Piccolo and Gotenks, Majin Buu’s powers have increased exponentially! Armed with some new tricks, Majin Buu is poised for global destruction. Now that Gohan is alone and weakening, is there anyone who can stop the monster?', 26, '1995-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 14, 'Ready to Fuse?', 'Goku watches helplessly from Other World as Majin Buu sets his sights on Gohan. Luckily the Old Kai reveals a secret source of power that could save the day. Is Goku ready to bond with his son and put an end to Majin Buu’s reign of terror?', 26, '1995-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 15, 'Union of Rivals', 'After Majin Buu absorbs Gohan, Goku’s plan to join forces with his son is ruined. But an unlikely ally arrives on the scene—Vegeta! Will the Saiyan Prince put aside his differences and agree to merge with Goku?', 26, '1995-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 16, 'Meet Vegito', 'The bodies of Goku and Vegeta join to form a new Saiyan warrior. The monster Majin Buu is impressed by the strength of his new opponent, but refuses to take him seriously. Will Majin Buu’s arrogance be his undoing?', 26, '1995-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 17, 'Rip in the Universe', 'The newly-formed Saiyan warrior Super Vegito matches Majin Buu punch for punch. But the monster’s new opponent stirs up an uncontrollable anger within the very heart of the beast. Will Majin Buu’s frenzy mean the end of planet Earth?', 26, '1995-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 18, 'Vegito... Downsized', 'The battle rages on between Vegito and Majin Buu! The Super Saiyan Combo seems to have the fight well in hand. But is Vegito tempting fate by toying with Buu? What terrible tricks does the wily, pink monster still have up his sleeve?', 26, '1995-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 19, 'The Incredible Fighting Candy', 'Having been reduced to a coffee-flavored candy, it seems nothing can stop Vegito from being consumed by the evil Majin Buu. But when the gumdrop fights back, Buu realizes that the battle is far from over!', 26, '1995-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 20, 'The Innards of Buu', 'When Majin Buu absorbs Vegito, the fused Saiyan separates into Goku and Vegeta once again. Deep within the villain, they reveal their plan to rescue Gohan and the others. Can the duo survive the digestive process and carry out their mission?', 26, '1995-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 21, 'Mind Trap', 'Dangers abound as Goku and Vegeta continue their search for Gohan and inside of Majin Buu’s body! After meeting some disgusting bedfellows, they finally find what they’re looking for as they enter Majin Buu’s head!', 26, '1995-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 22, 'Deadly Vision', 'Goku and Vegeta reunite the others only to be attacked by Majin Buu! The showdown proves that fighting Buu inside his own head is a mind-bending experience. Can Goku and Vegeta survive in this twisted house of horrors where all is Buu?', 26, '1995-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 23, 'Evil Kid Buu!', 'When Super Buu’s body begins to mutate once again, Goku and Vegeta have to get out fast! But what awaits them should they manage to escape? What will the insidious Buu turn into next?', 26, '1995-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 24, 'End of Earth', 'After the cords of attachment to the roly-poly Buu are cut by Vegeta, Majin Buu should mutate into a much weaker form. But instead he gets even stronger! This baffles everyone but Kibito Kai, who discloses Majin Buu''s bizarre history!', 26, '1995-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 25, 'True Saiyans Fight Alone', 'With Earth erased from existence, Majin Buu begins his search for Goku and Vegeta, leaving entire worlds destroyed in his wake. But when Buu''s hunt leads him to the World of the Kais, Goku and Vegeta draw the line!', 26, '1995-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 26, 'Battle for the Universe Begins', 'With Majin Buu ready for a fight, Kibito Kai is stunned to see Goku and Vegeta playing a game of Rock, Paper, Scissors! Rather than use the Fusion Technique to join their powers, the duo has decided to fight Buu one at a time!', 26, '1995-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 27, 'Vegeta''s Respect', 'When Super Saiyan 3 Goku collapses from exhaustion, Vegeta enters the fight, but he doesn’t last long! Just as Majin Buu is about to deliver the deathblow, Goku makes a comeback!', 26, '1995-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 28, 'Minute of Desperation', 'Goku''s powers are fading, and he must end the battle before it''s too late! Enter Vegeta, who begins a furious battle with Buu to buy Goku the time needed to gather energy. Outclassed by his opponent, can the Saiyan Prince survive!?', 26, '1995-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 29, 'Old Buu Emerges', 'When Vegeta falls, Mr. Satan steps in to take up the challenge! It appears the wannabe hero has signed his death warrant, but when Buu attempts to attack, the monster is crippled by agony!', 26, '1995-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 30, 'Earth Reborn', 'As good Majin Buu wages an all-out war against his evil counterpart, Vegeta asks Dende to summon the Dragon on the new Planet Namek. With the good Buu''s power dwindling, will Vegeta have enough time to carry out the final phase of his plan?', 26, '1995-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 31, 'Call to Action', 'Goku awaits the arrival of the Earthlings’ collective energy to vitalize the Spirit Bomb, but the energy isn’t coming! Have the people of the Earth turned a deaf ear to Vegeta’s plea for help at this most critical hour?', 26, '1995-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 32, 'People of Earth Unite', 'The foolish Earthlings ignore Goku, but when Mr. Satan asks for help, the humans have a change of heart. Will their outpouring of energy arrive in time? Goku can only wait and watch as Vegeta crumbles under the might of Majin Buu!', 26, '1995-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 33, 'Spirit Bomb Triumphant', 'After the good Buu and Mr. Satan free Vegeta, Goku launches the Spirit Bomb! Unfortunately, the weary Saiyan doesn’t have enough power to deliver the blast, and Buu sends it right back at him! Will Goku be destroyed by his own attack?', 26, '1995-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 34, 'Celebrations with Majin Buu', 'When Goku and his companions return to Earth after defeating Majin Buu, they are welcomed with open arms. But nobody is happy to see the good Buu! Can Mr. Satan’s pink pal manage to fit into society? Or is he destined to become an outcast?', 26, '1995-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 35, 'He''s Always Late', 'Goku has his hands full guarding four dragon eggs from the dangers of the wild, but even if he can save the baby dragons, he will soon face an even more dangerous peril: an angry Chi Chi!', 26, '1996-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 36, 'Granddaughter Pan', 'It’s been ten years since the demise of evil Majin Buu, and Earth is once again at peace. Gohan is a scholar. Trunks and Goten are strong, young teenagers! Vegeta and Bulma have a new daughter! And Goku is a grandfather!', 26, '1996-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 37, 'Buu''s Reincarnation', 'A new World Tournament is set to begin! With help from Majin Buu, Goku rigs the drawing so he faces a mysterious fighter in the first round of the finals! Is this timid, little village boy called Uub really as strong as Goku thinks?', 26, '1996-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121220')) AND numero_temporada = 9), 38, 'Goku''s Next Journey', 'Uub grows stronger as the battle rages, soon becoming the Saiyan’s equal, but before the match is decided, Goku makes a startling revelation! With his plan revealed, Goku and Uub depart the arena, leaving a stunned crowd in their wake.', 26, '1996-01-31');
