INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 1, 'Season 1', 'This is the season that started it all! Join Stan, Kyle Cartman and Kenny as these four animated tykes take on the supernatural, the extraordinary and the insane. For them, it’s all part of growing up in South Park.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 1, 'Cartman Gets an Anal Probe', 'While the boys are waiting for the school bus, Cartman explains the odd nightmare he had the previous night involving alien visitors abducting him from his bed. Meanwhile Kyle and Stan try to convince Cartman that the dream was in fact a reality.', 23, '1997-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 2, 'Volcano', 'The boys get together with Stan''s Uncle Jimbo and Jimbo''s war-buddy Ned for a hunting trip in the nearby mountains. After Cartman''s mom makes sure her "little" boy is safe and sound (much to Cartman''s dismay) the group heads off for adventure. As they drive away from the town, Jimbo explains the "finer" points of hunting.', 23, '1997-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 3, 'Weight Gain 4000', 'Mr. Garrison starts the day off with a special announcement; one of South Park''s own has won a national essay contest. Everyone is shocked to learn that the winner is Cartman, who doesn''t even remember what he wrote about.', 23, '1997-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 4, 'Big Gay Al''s Big Gay Boat Ride', 'Stan''s got a new dog named Sparky. Stan proclaims his pet to be the toughest dog on the mountain. Though while Stan thinks his dog is ready for fighting, Sparky proceeds to hump Sylvester like a little bitch. The other boys taunt Stan about his gay dog and Sparky runs away to find someone who will love him for who he is.', 23, '1997-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 5, 'An Elephant Makes Love to a Pig', 'Stan notices a new addition in their bus stop crew, an elephant standing alongside Kyle. At school, class lessons for the day involve genetic engineering (conveniently enough). Kyle questions the possibility of a genetically engineered elephant made smaller by design. The boys have to beat the rough kids in their genetics experiment, and will try anything to do it.', 23, '1997-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 6, 'Death', '"Happy Birthday" to Stan''s Grandpa Marsh who just turned 102. How does the wizened Mr. Marsh feel about his birthday? He sums it up in five words; "I wish I were dead" and proceeds trying to end his life enlisting Stan to do it for him. However, Stan is aware of a very important thing if he kills his grandfather, he''d be in trouble, and if he''s in trouble he can''t watch Terrance and Phillip.', 23, '1997-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 7, 'Pinkeye', 'The first Halloween episode starts off with the failure of the Mir Space Station, which crashes right on Kenny. An ambulance comes and takes his body off to the morgue. The boys start to brag about their Halloween costumes. At the morgue, a freak accident involving a bottle of Worcestershire sauce occurs, and next thing you know Kenny is a member of the undead. Kenny breaks free and wanders off into the night.', 23, '1997-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 8, 'Starvin'' Marvin', 'The four boys are at Cartman''s house watching the "Terrance & Philip Thanksgiving Special" on television. During a break from the show, a Sally Struthers commercial convinces the boys that the prospect of a free "Taiko" sport watch with a five-dollar donation is irresistible. Typical greedy American youth. So Stan dials in, using his mother''s credit card number and makes their donation.', 23, '1997-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 9, 'Mr. Hankey, the Christmas Poo', 'South Park Elementary is on stage rehearsing for the schools play. Kyle begins to sing a song about Mr. Hankey, the Christmas Poo. Of course, no one has any idea what the heck he''s singing about. Kyle explains that Mr. Hankey comes every year to all the good boys and girls who have a lot of fiber in their diet. Everyone thinks he''s insane and he gets sent to a mental institute.', 23, '1997-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 10, 'Damien', 'Eric is handing out invitations to his birthday party at school. Mr. Garrison informs them all that there is a new student joining the class. Announcing to all that he is Damien, the son of Satan. Even as Damien demonstrates his demonic powers the children are more loathsome than impressed.', 23, '1998-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 11, 'Tom''s Rhinoplasty', 'Mr. Garrison deserts the class for a visit to Tom''s Rhinoplasty. All the boys compete for the attention of their beautiful substitute teacher Ms. Ellen.', 23, '1998-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 12, 'Mecha-Streisand', 'The boys meet up with Barbara Streisand who wants to take over the world with Kyle''s discovery at an archaeological dig. Leonard Maltin, Sydney Potier, and Robert Smith come to the rescue to defeat Babs and her terrible destruction.', 23, '1998-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 1), 13, 'Cartman''s Mom Is a Dirty Slut', 'Cartman needs to find out who his father is but his mom is no help. Learning that his father could be one of the many people that his mom had "relations" with during an annual party called "The Drunken Barn Dance", he finds that there''s more to his mother than he thought.', 23, '1998-02-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 2, 'Season 2', 'Join Stan, Kyle, Cartman and Kenny as they discover the identity of Cartman''s father, learn about Conjoined Twin-Myslexia and thaw a prehistoric ice man. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 1, 'Terrance and Phillip in Not Without My Anus', 'The show starts off with the build up from last season''s cliffhanger revolving around Cartman''s paternal origins. However, just as it seems they are about to get on with the second half of "Cartman''s Mom Is A Dirty Slut," they do a 180 degree turn-around and reveal that for April Fool''s Day they will be showing Terrance & Phillip in "Not Without My Anus".', 23, '1998-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 2, 'Cartman''s Mom Is Still a Dirty Slut', 'Dr. Mephisto is about to reveal who Eric Cartman''s father really is! Glass shatters and gunshots ring out. A mysterious assailant apparently shot Mephisto while the lights were off. Much to Eric''s chagrin, they rush Mephisto off to the hospital. Chef rushes out the door with Mephisto in hand. They must fight against time to learn Eric''s background, who is his father? Where does he come from?', 23, '1998-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 3, 'Ike''s Wee Wee', 'Ike''s going to have a Briss and everyone is invited! Stan, Kenny, and Cartman find out what a Briss really is and try to warn Kyle that his parents are going to cut off Ike''s wee wee. Kyle sends Ike away to protect him from his scissor wielding parents.', 23, '1998-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 4, 'Chickenlover', 'The Booktastic bus is in town and soon everyone finds out that Officer Barbrady can''t read. He is whisked off to school with the boys so he can save his job. While he''s there someone in South Park is having sex with the town''s chickens and only Officer Barbrady with his new deputies Kenny, Kyle, Stan, and Cartman can stop them!', 23, '1998-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 5, 'Conjoined Fetus Lady', 'Kyle is injured and must go to see the school nurse and is terrified because of the stories he''s heard. She looks fairly normal, except for the dead fetus sticking out of her head. Kyle''s mother educates the boys on her "condition" and decides that everyone in South Park should be made aware. Meanwhile, the South Park Cows dodgeball team goes to the state, national and finally the international finals in China.', 23, '1998-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 6, 'The Mexican Staring Frog of Southern Sri Lanka', 'Mr. Garrison assigns the boys to learn about Vietnam from somebody they know. Stan''s Uncle Jimbo and his friend Ned tell the boys their outrageous tale. Mr. Garrison doesn''t believe the boy''s report and gives them detention. They plot revenge against Stan''s Uncle by submitting a phony video of the Mexican Staring Frog of Southern Sri Lanka to them.', 23, '1998-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 7, 'City on the Edge of Forever (Flashbacks)', 'While their school bus is dangling on the edge of a cliff, the boys remember some of their past adventures. Mrs. Crabtree catches a ride into town with a stranger and winds up doing a brief stint as a standup comedienne. Back in South Park, Mr. Mackey convinces the parents that their missing children must have run away. In the end it''s all a dream within a dream.', 23, '1998-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 8, 'Summer Sucks', 'Schools out for summer and with Mr. Hat missing, Mr. Garrison is over the edge. The state has a ban on the sale of fireworks, and it screws up the boy''s plans for a 4th of July celebration. Mr. Garrison seeks psychiatric help from Dr. Katz while Jimbo and Ned go to Mexico, in an attempt to smuggle fireworks back to the children of America.', 23, '1998-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 9, 'Chef''s Chocolate Salty Balls', 'A film festival moves to South Park, only to have a devastating effect on the sewer system. Mr. Hankey calls upon Kyle for help. The movie people interpret Kyle''s pleading as a pitch and they quickly turn his story into a film starring Tom Hanks and a monkey they call "Mr. Hankey." Kyle is outraged that the filmmakers aren''t hearing his pleas. Soon Chef''s Salty Chocolate Balls energizes everyone.', 23, '1998-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 10, 'Chickenpox', 'Cartman''s mother plots to give the boys the chickenpox by sending them over to Kenny''s for a sleepover. Both Stan and Cartman breakout, but Kyle remains immune. Kyle discovers "the parental conspiracy" and with the other boys hires a prostitute to give their parents herpes. Meanwhile, Kenny''s mother and Kyle''s mother reunite their husbands who were both childhood friends that drifted apart.', 23, '1998-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 11, 'Roger Ebert Should Lay Off the Fatty Foods', 'The kids go on a field trip to the planetarium. All of the children except Cartman are acting weird. As usual Stan and Kyle, with Kenny''s sacrifice, try to get to bottom of the mystery. Meanwhile, Cartman wins an appearance on a snack commercial. The four boys get to the root of the strange planetarium.', 23, '1998-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 12, 'Clubhouses', 'Stan needs to build a clubhouse so he and Kyle can play "Truth or Dare" with Wendy and her friend, who has a crush on Kyle. Cartman and Kenny retaliate by building a clubhouse of their own; only theirs has hot chicks. Meanwhile, the Marshes marriage breaks up and Stan learns a valuable lesson about love and family.', 23, '1998-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 13, 'Cow Days', 'South Park''s annual "Cow Days" party is happening! The cows become transfixed on a cow statue. In order to get the money they need to win Terrance and Phillip dolls, the boys sign Cartman up for a bull riding contest. A freak accident has Cartman believing he is a Vietnamese prostitute named Ming Li. The boys learn about money and cow insanity.', 23, '1998-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 14, 'Chef Aid', 'Chef is getting sued by Capitalist Records for trying to obtain the rights to a song he wrote twenty years ago. He needs 2 million dollars to hire Johnny Cochran. In response the boys round up all of Chef''s old musician friends and organize a huge concert to raise the cash.', 23, '1998-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 15, 'Spookyfish', 'Sharon Marsh''s Aunt Flo makes her monthly visit and she has present for Stan, a fish. Stan''s fish really freaks him out, especially when the dead bodies start piling up. Mrs. Marsh is convinced Stan is doing the killings and begins hiding the bodies. The boys discover there are two Cartmans and a gateway to a parallel universe at the "Indian Burial Ground Pet Store."', 23, '1998-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 16, 'Merry Christmas Charlie Manson!', 'Kyle, Stan and Kenny accompany Eric and his family to a Christmas celebration with the Cartman family. One of Cartman''s relatives breaks out of jail for the reunion, with his cellmate, Charles Manson.', 23, '1998-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 17, 'Gnomes', 'Harbucks coffee plans to move into South Park and drive Tweek coffee shop out of business. Mr. Garrison assigns a report on current events to help him keep his job. The boys are planning on doing their report on the underpants gnomes. Tweek''s father schemes to use the boy''s report as a platform for fighting Harbucks. The report the boys deliver sparks the town into taking action.', 23, '1998-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 2), 18, 'Prehistoric Ice Man', 'Kyle falls into a cave. Stan goes to rescue him and finds an iceman, and the two fight each other for sole credit. Dr. Mephisto discovers that the iceman has been frozen since 1996. The iceman is put on display and the fighting Kyle and Stan free him. The iceman tries to return to his family, but finds himself a man out of time. Meanwhile, the government has their own plans to use the iceman in their plot against Sweden.', 23, '1999-01-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 3, 'Season 3', 'Return to everyone’s favorite mountain town for seventeen outrageously bizarre episodes of South Park. Along the way, you’ll meet the Succubus, get caught up in the Chinpokomon frenzy and find out why citizens are spontaneously combusting.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 1, 'Rainforest Shmainforest', 'Mr. Mackey punishes the boys by forcing them to join the "Getting Gay With Kids" choir. The choir is going to Costa Rica to help save the rainforest. While on a tour of the rainforest the choir group gets lost when a snake kills their guide. They soon discover the evils of the rainforest, which changes the choir group''s message.', 23, '1999-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 2, 'Spontaneous Combustion', 'Kenny spontaneously combusts. The mayor asks Randy Marsh to find a solution. The boys try to help Kyle''s dad to get an erection. One way they think they can help is by performing the Stations of the Cross at church crucifying Cartman and waiting three days for his res-erection. Randy Marsh figures out the reason everyone is combusting is because they are withholding their farts.', 23, '1999-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 3, 'The Succubus', 'Kyle and Stan try to rescue Chef from the clutches of the Succubus that he is going to marry. Meanwhile, Cartman deals with his eye problems and the optometrist he doesn''t like. Chef''s Mama and Papa appear for the first time.', 23, '1999-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 4, 'Jakovasaurs', 'The boys discover a live prehistoric Jakovasaur while camping on Stark''s Pond. The government and the citizens of South Park are interested in trying to help keep this endangered species alive, until they all realize how annoying the Jakovasaurs really are. The only one who really enjoys them is Cartman. The boys try distracting him while the town tries to send the Jakovasaurs to France.', 23, '1999-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 5, 'Tweek vs. Craig', 'The boys take Shop class and try to set-up a fight between Tweek and Craig. Kenny is delighted in safely taking the Home Economics course. When the big fight arrives, the combatants don''t know what to do; so Jimbo and Ned teach Tweek boxing and Cartman has Craig instructed in the art of Sumo. Shop teacher Mr. Adler has a recurring dream about a woman that he was never able to say goodbye to.', 23, '1999-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 6, 'Sexual Harassment Panda', 'Sexual Harassment Panda visits Mr. Garrison''s class. Cartman sues Stan for sexual harassment and Kyle''s dad is getting rich. The boys go in search of "Sexual Harassment Panda" to stop the insanity. They find him at "The Island of Misfit Mascots Commune" and convince him to change his cause. He becomes Petey, the "don''t sue people" Panda.', 23, '1999-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 7, 'Cat Orgy', 'Shelly Marsh is babysitting Cartman. Shelly invites her boyfriend over and he in turn invites his band. Cartman has to prove that Shelly has violated the rules. Meanwhile, the Cartman''s cat is in heat, searches for a good time and invites all the cats in the neighborhood back to the empty Cartman house for an orgy.', 23, '1999-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 8, 'Two Guys Naked in a Hot Tub', 'Stan''s parents bring him to Mr. Mackey''s party, but he gets sent down to the basement to be with the lame kids. Kyle and Stan''s fathers experiment with their homosexual tendencies. The ATF is convinced that the meteor shower party is actually a gathering of a religious cult that is going to commit suicide when the meteor shower arrives. Stan tries to save himself and the party from the ATF.', 23, '1999-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 9, 'Jewbilee', 'Kyle invites Kenny to join him at Jewbilee, a Boy Scout-like gathering for Jewish kids. His parents are going to attend Mr. Mackey''s party. At camp, Ike is sent to join the little group called "Squirts." Kyle and Kenny, join the scouts, where they concentrate on soap sculptures. This art is key to the Jewish elders celebration of Moses however, Moses identifies Kenny as not being Jewish and Kenny is banished from the camp.', 23, '1999-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 10, 'Korn''s Groovy Pirate Ghost Mystery', 'Korn comes to South Park for a Halloween gig and learns of the boys problems with the 5th graders at South Park Elementary. Korn agrees to help the boys get revenge on the mean 5th graders all in a spooky Scooby Doo rip off!', 23, '1999-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 11, 'Chinpokomon', 'The kids of South Park discover Chinpokomon, Japan''s #1 cool toy to own! Wanting to avoid being losers, they persuade their parents to buy them the toys only to discover that the Chinpokomon are designed to brainwash them into bombing Pearl Harbor. The parents band together to stop Japan and save America!', 23, '1999-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 12, 'Hooked on Monkey Fonics', 'Mrs. Cartman is about to give Eric a present. Of course Eric is hoping it will be some kind of toy, but it ends up being Hooked On Monkey Phonics to help him win the big South Park Annual Spelling Bee. Kyle finds Rebecca Cutswald to be quite intriguing and tries to woo her with his charm and teach her how to love and learn in public school.', 23, '1999-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 13, 'Starvin'' Marvin in Space', 'Starvin'' Marvin finds an alien ship and begins searching out a new home for his people. The government interrogates the boys to find out about Marvin and direct them to Sally Struthers. Marvin stops in South Park to pick up the boys and take them to the planet Marklar. The Marklarians are willing to let the Ethiopians relocate to their world and the Christian channel does all they can to stop them.', 23, '1999-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 14, 'The Red Badge of Gayness', 'South Park''s Civil War reenactment, sponsored by "Jagerminz S''More Flavored Schnapps," gets out of hand. Cartman persuades the drunken lot to defeat the northerners so that he can win a bet with Kyle and Stan that will make them his slaves for one month.', 23, '1999-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 15, 'Mr. Hankey''s Christmas Classics', 'Mr. Hankey introduces 10 musical segments highlighting songs the on the CD "Mr. Hankey''s Christmas Classics." The boys and all of the other South Park characters sing their own songs for the Holidays and realize that Christmas is all about the presents.', 23, '1999-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 16, 'Are You There God? It''s Me, Jesus', 'Cartman is convinced he is going through puberty since he started bleeding out of his ass. Dr. Mephisto gives Stan some hormones and he takes the entire bottle. Stan gets facial hair, boobs and his voice starts changing. People are waiting outside of Jesus'' home to see what kind of miracle he offers which ends up involving a comeback performance of a very old Rod Stewart and eventually an appearance by God.', 23, '1999-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 3), 17, 'World Wide Recorder Concert', 'The children of South Park are practicing "My Country ''Tis of Thee" for the "4 Million Child Blow," sponsored by Yoko Ono. Mr. Garrison doesn''t want to go because his father still lives there. At the concert Stan and Kyle try to figure out a way to "out cool" the kids from New York. Cartman tries to find "the brown noise" and is successful. Stan and Kyle plan against the kids from New York but their scheme goes much too far.', 23, '2000-01-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 4, 'Season 4', 'Join Stan, Kyle, Cartman and Kenny as they graduate to 4th grade, join in the 2000 election recount, the controversy over Saddam Hussein, and the introduction of Timmy!!! For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 1, 'The Tooth Fairy Tats 2000', 'The tooth fairy has visited Cartman, leaving him two dollars. He rushes to the bus stop to share his news with the others. He then unveils his latest plan. If all they all combined their lost teeth, the tooth fairy will provide them with enough cash to purchase a Sega Dreamcast. They soon find out that they are treading on someone else''s territory. Now they have to work with the mobsters to keep their manhood.', 23, '2000-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 2, 'Cartman''s Silly Hate Crime 2000', 'The kids have just won a sledding race. Token says that the only reason they won is because of Eric''s fat ass. The girls challenge the boys to a sledding race down Phil Collins Hill. Token says that the boys can''t lose thanks to Eric''s fat ass. Eric then tosses a rock into the side of Token''s head. The FBI claim that this was a hate crime and Cartman is sent to jail. Can the other boys bust Cartman out in time for the big race?', 23, '2000-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 3, 'Timmy 2000', 'There''s something wrong with new student Timmy. About the only thing Timmy can do is say his name. Ignorant of the fact that Timmy is "retarded", he is "diagnosed" with ADD, which relieves him of the responsibility to do any homework. Soon the rest of the class manages to get diagnosed with ADD, and all get prescribed Ritalin. Everyone is on Ritalin and just complacent enough to sit through a Phil Collins show.', 23, '2000-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 4, 'Quintuplets 2000', 'The boys discover 8-year-old contorting quintuplets from Romania. Cartman decides to stage his own performance. The quintuplets and their grandmother defect from Romania and wind up staying at the Marsh''s home. Thanks to Grandpa Marsh the girls'' grandmother gets "loved to death." The girl''s father is brought in by the Romanian government to demand his daughters back, Janet Reno to the rescue!', 23, '2000-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 5, 'Cartman Joins NAMBLA', 'Cartman decides to seek the friendship of older men. Using the Internet, he makes a connection with men who love to hang out with little boys. An organization called NAMBLA (North American Man Boy Love Association) holds a meeting in South Park and Cartman becomes their poster child. The boys learn how much an adult can really love a child.', 23, '2000-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 6, 'Cherokee Hair Tampons', 'Kyle needs a kidney transplant and Cartman is a perfect donor. Cartman has a $10 million price for his kidney. The other boys go to Cartman''s house with the plan to take one of his kidneys. Cartman thwarts their plan. Stan, depressed about the inevitable loss of his friend decides to take action into his own hands and with the help of the parents gets Cartman''s kidney for Kyle.', 23, '2000-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 7, 'Chef Goes Nanners', 'Chef is declaring that South Park''s flag is racist. Stan & Kyle head up the team championing the current flag, while Wendy and Cartman head up the side for a new flag. Wendy ends up confessing to Bebe of her attraction to Cartman. The debate starts, but before Wendy can make her point, she kisses Cartman to regain her composure. Chef realizes that Stan & Kyle''s point of view on the flag issue was colorblind.', 23, '2000-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 8, 'Something You Can Do with Your Finger', '"Fingerbang" is the latest boy band starring the four boys. Randy Marsh is against Stan''s participation in any boy band for dark reasons. The boys land a gig at the local mall when it is threatened because there are only 4 members in the band. Stan arrives and the group is set to perform when suddenly the mall elevator tragically crushes Kenny. A former boy band member steps into the spotlight to save the gig.', 23, '2000-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 9, 'Do the Handicapped Go to Hell? (1)', 'The boys attend church and the priest puts the fear of hell in them. They must go to Sunday school and learn that they must confess their sins. The boys are worried about Timmy, after all, he can only say his name. Feeling the need to confess their sins they catch the priest in a compromising position and decide to save themselves.', 23, '2000-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 10, 'Probably (2)', 'Cartman preaches and the children begin plans to build a church. Satan spends the night with Saddam. Kenny wasn''t killed in the previous episode, but the bus that ran him over stops in Mexico, where Kenny is found. Satan, in his time of crisis turns to God for advice. Cartman is discovered as a fraud and is sent to Mexico for punishment.', 23, '2000-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 11, 'Fourth Grade', 'The kids have to face the 4th grade, and they''re not too happy about it. Cartman cooks up a scheme to go back in time to return to the 3rd grade where things were fun and easy. Two geeks help them rig Timmy''s wheelchair into a working time machine and send Timmy on the trip of his life!', 23, '2000-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 12, 'Trapper Keeper', 'Cartman has a new Trapper Keeper (that blows Kyle''s out of the water) After he''s done bragging, a stranger tells him that it will soon take over the world if they don''t destroy it now. Cool 2001: A Space Odyssey and Akira parodies!', 23, '2000-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 13, 'Helen Keller! The Musical', 'The boys are doing their version of the Helen Keller Story and plan to beat the kindergartners show. Timmy stars as Helen Keller and gets a new friend to play with! Fireworks, fountains, and outstanding musicals galore!', 23, '2000-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 14, 'Pip', 'This is the story of Pip''s origin. Pip gets a job at the Havesham Estate where he meets Estella. She only spurns his optimism with insults. When Pip is offered the opportunity to become a gentleman he goes to London only to discover that Miss Havesham plans to break his heart. Her plan is to use Pip''s tears to power her Genesis device and will allow her to gain revenge on all men.', 23, '2000-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 15, 'Fat Camp', 'Mrs. Cartman holds an intervention for her son''s eating problem and is sending him to fat camp. Cartman returns from camp, 40 lbs. lighter. Cartman is selling candy to the fat kids. Kenny is challenged by the other children to do crazy things for money. Kenny''s popularity rises and he soon gets his own TV show. An event happens where Kenny gets inside Ms. Crabtree''s uterus for six hours.', 23, '2000-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 16, 'The Wacky Molestation Adventure', 'The "Raging Pussies" concert is on! Kyle calls the police and say his parents have been "molestering" him. Soon all the children are calling in on all the adults in South Park. Until only children live in South Park. Someone from out of town breaks down and they have the task of retrieving a book for the fat-ass. The locked-up adults of South Park get therapy to prevent them from sexually abusing their children.', 23, '2000-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 4), 17, 'A Very Crappy Christmas', 'Kyle and Ike anxiously await Mr. Hankey. When he doesn''t show, Kyle calls the others for a late night emergency meeting. They find Mr. Hankey living with his alcoholic wife and their three little nuggets. He tells them that no one is into Christmas. They all decide to try and spread some Christmas cheer. Their effort fails and the boys decide to create an animated special of their own. Featuring Jesus, Santa Claus and themselves.', 23, '2000-12-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 5, 'Season 5', 'Join Stan, Kyle, Cartman and Kenny as they welcome Jimmy the new handi-capable kid in town & Towelie, Radiohead guest stars, Big Gay Al returns, and Terrance and Phillip break up. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 1, 'It Hits the Fan', 'The you-know-what hits the fan 162 times when the citizens of South Park hear the word "Sh*t" on the popular show, "Cop Drama." Boffo ratings have the executives at HBC plotting further use of the curse word, as the nation is struck by a mysterious plague that unleashes the ancient Knights of Standards and Practices. Only Chef and the boys can save South Park, and the world!', 23, '2001-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 2, 'Cripple Fight', 'Big Gay Al returns to South Park, only to be thrown out as Scoutmaster to the boys for being gay. The boys rally to his defense, with the help of the new "handi-capable" kid, Jimmy. But there''s only room for one crippled kid in South Park, so Timmy and Jimmy throw off the gloves, as well as the crutches and wheelchair, in an all out slugfest to end all slugfests.', 23, '2001-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 3, 'Super Best Friends', 'Stan, Kyle, Cartman and Kenny discover David Blaine, magician and Cult Leader. Stan finds out early that the Blainiacs are not as nice as they thought. Stan has to convince Kyle, Kenny and Cartman that they''ve been brainwashed... but will he get to them in time? Jesus has a few tricks up his sleeve! Super Best Friends to the rescue!', 23, '2001-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 4, 'Scott Tenorman Must Die', 'Cartman goes medieval on Scott Tenorman''s ass when ginger-haired Scott tricks our supple hero into buying his pubic hair for $16.12. Radiohead guest stars and plays a role in Cartman''s elaborate scheme at getting sweet revenge on his unsuspecting foe.', 23, '2001-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 5, 'Terrance and Phillip: Behind the Blow', 'In the grand tradition of Wham UK, flatulant Canadian superstars, Terrance and Phillip, have broken up over creative differences. The clock is ticking as the boys struggle to reunite the fartastic duo, and recruit them in time for South Park''s Earth Day festivities.', 23, '2001-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 6, 'Cartmanland', 'Cartman inherits one million dollars from his grandmother, fulfilling his lifelong dream of owning his own amusement park, Cartmanland! A hemorrhoid erupts in Kyle''s ass when he learns of Cartman''s undeserved fortune, making him question the very existence of God, and whether there''s a reason to stay alive in a world where someone like Cartman is happy.', 23, '2001-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 7, 'Proper Condom Use', 'Thanks to Stan''s "handy" work, the children of South Park must endure sex education from the unlikely duo of Mr. Mackey and Ms. Choksondik. While the two adults take their lessons to heart, the children are left frightened, mis-informed, and armed for battle against the opposite sex. Much hilarity ensues.', 23, '2001-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 8, 'Towelie', 'The boys get a new video game system and their plans for the next 38 hours is to play it! Untill they discover Towelie, a government secret, genetically engineered towel that gets his special powers from gettin'' high. When the government steals Stan''s new Game Sphere the boys will stop at nothing to get it back. Losing precious gaming time they find Towelie and begin the struggle of the century.', 23, '2001-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 9, 'Osama Bin Laden Has Farty Pants', 'In the wake of the terrorist attack on the United States, the boys find themselves accidentally sent to Afghanistan, where they encounter their Afghani counterparts and try to understand why they hate Americans. While they are there they also take on the Taliban and Cartman pits his fat ass against Bin Laden himself.', 23, '2001-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 10, 'How to Eat with Your Butt', 'Cartman has finally gone too far when a prank involving Kenny''s sweet cheeks results in him blowing a "funny fuse." After a photo of Kenny''s better side finds it''s way onto the side of a milk carton, an unusual couple arrives in South Park to claim their missing child. Much ass kissing ensues.', 23, '2001-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 11, 'The Entity', 'Kyle’s cousin comes to town and after Kyle sees how stereotypically Jewish his cousin Kyle is, he worries about how Cartman is going to react when he meets him. Meanwhile, Mr. Garrison invents an alternative form of transportation that requires the rider to use more than just their hands and legs to control it.', 23, '2001-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 12, 'Here Comes the Neighborhood', 'Feeling like an outcast for being the only rich kid in town, Token succeeds in attracting several other wealthy people to South Park. Meanwhile, the townspeople, fearing that their little hamlet is rapidly going up the drain, attempt to run the new residents out of town by any means necessary.', 23, '2001-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 13, 'Kenny Dies', 'In a very special episode of South Park, Cartman fights for Kenny''s life when he speaks before Congress in favor of stem cell research. Meanwhile, Stan has trouble dealing with his friend''s impending demise.', 23, '2001-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 5), 14, 'Butters'' Very Own Episode', 'Butters finds out what his father has been up to late at night and when his mother hears, she overreacts by trying to kill her son and then herself back at home. After returning home and forgiving her husband, she realizes what she has done to her son and they spin a story to the media to cover their tracks. Meanwhile, Butters obsesses with returning home so that he can join his parents for an anniversary dinner at Bennigan’s.', 23, '2001-12-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 6, 'Season 6', 'In this series Stan convinces the boys to kidnap all the calves from a local farm after a look at how veal is made turns him vegetarian; Professor Chaos struggles to find an evil scheme that hasn''t already been done on ''The Simpsons''; and when Bebe''s breasts begin to take shape, the boys can''t understand why they''re suddenly interested in her.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 1, 'Jared Has Aides', 'The boys decide to fatten up Butters so that he can lose weight by eating at their favorite restaurant just like Jared, the sub sandwich guy. Jared, who is making an appearance in town reveals another secret to his weight loss, he has aides.', 23, '2002-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 2, 'Asspen', 'With their parents stuck in Time Share Hell, our boys are on their own on the slopes of Aspen, circa 1985. Stan gets challenged to a ski race and must win in order to save the youth center, get the girl, and free the trapped spirits of the Wakacha Vampire Indians. Not that he really cares.', 23, '2002-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 3, 'Freak Strike', 'The boys learn that disfigured people get prizes for appearing on a talk show and they sign Butters up. When the prize he gets can’t be shared, Cartman has his mother join him on a segment called, "Please Help My out of Control Child."', 23, '2002-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 4, 'Fun With Veal', 'The boys learn where veal comes from and they decide to save the calves by hiding them in Stan’s room, where they all intend to stay until the calves are guaranteed their safety. During the siege Stan develops symptoms of an illness caused by his new vegan diet.', 23, '2002-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 5, 'The New Terrance and Phillip Movie Trailer', 'The boys have to sit through "The Russell Crowe Show" in order to see the premiere of the trailer for the new Terrance and Phillip movie. Meanwhile, Chef’s new TV has taken on a life of its own.', 23, '2002-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 6, 'Professor Chaos', 'Butters isn’t working out and Cartman, Kyle and Stan decide to fire him and hold auditions for his replacement. Becoming an outcast, Butters becomes a super-villain with plans to cause chaos wherever he goes.', 23, '2002-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 7, 'The Simpsons Already Did It', 'Professor Chaos returns with brand new, super evil, schemes to wreak havoc on South Park; unfortunately, the Simpsons have already done them all. Meanwhile, a super secret ingredient helps Cartman''s "Sea People" evolve at an alarming rate.', 23, '2002-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 8, 'Red Hot Catholic Love', 'Father Maxi is concerned with all the molestation claims that have been placed against the Catholic Church recently. After most of his parishioners turn to Atheism as an answer, he travels to the Vatican to get some answers.', 23, '2002-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 9, 'Free Hat', 'The boys go out to see the new edition of Star Wars: Episode V and during the previews they find out that the movie studios are planning on re-releasing more movies with digitally enhanced effects. In an effort to stop this injustice, they go off to find Steven Spielberg and George Lucas.', 23, '2002-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 10, 'Bebe''s Boobs Destroy Society', 'After nearly five years and 89 episodes, it finally happens: Cartman gets kicked out of the gang. The reason? Bebe gets boobs and the boys go ape, threatening their friendships and society as we know it.', 23, '2002-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 11, 'Child Abduction is Not Funny', 'In an effort to protect their children from kidnappers, the parents of South Park hire the owner and operator of the local City Wok to build a Great Wall around the city. When crazy things like Kid trackers and Mongolions come into the picture. The parents learn a very important lesson themselves about trusting strangers.', 23, '2002-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 12, 'A Ladder to Heaven', 'Stan, Kyle, and Cartman win all the candy they can eat in a contest. There''s just one problem, Kenny had the ticket. Now to get their prize, the boys have decided to build a ladder to Heaven in order to get the ticket back from their dead friend.', 23, '2002-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 13, 'The Return of the Fellowship of the Ring to the Two Towers', 'The boys are on a mission: return "The Lord of the Rings" to the Two Towers Video Store in Conifer. But this is no ordinary copy. Butters, the evil sixth graders, and the boys'' parents all try to steal the ring, er tape, from the boys. Will they succeed?', 23, '2002-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 14, 'The Death Camp of Tolerance', 'A loveable new character, Mr Slave, makes his debut as Mr. Garrison desperately tries to get fired from his new job as the boys'' 4th grade teacher. Meanwhile, the boys get sent to the Deathcamp of Intolerance for not tolerating Mr. Garrison''s intolerable behavior.', 23, '2002-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 15, 'The Biggest Douche in the Universe', 'When a famous psychic fails to help him exorcise Kenny from his body, Cartman takes other steps to achieve his goal. He and Chef travel to the moors of Scotland, where Chef''s mom tries a little of her voodoo magic on him. Meanwhile, after the boys encounter with the TV psychic, Kyle is paralyzed with fear at the thought of members of the spirit world watching over him. Only by debunking those who claim they can communicate with the dead can Stan save Kyle.', 23, '2002-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 16, 'My Future Self n'' Me', 'When a 32 year old man claiming to be Stan from the future shows up in South Park, young Stan is forced to come to terms with the loser he will become. Meanwhile, South Park''s own little entrepreneur, Eric Cartman is at the helm a new money making venture. Cartman is in the business of revenge.', 23, '2002-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 6), 17, 'Red Sleigh Down', 'In an effort to redeem himself days before Christmas, Cartman decides to bring Christmas to the Iraqis. So, along with Stan, Kyle, and Kenny they catch a ride with Mr. Hankey to the North Pole to bring Christmas to Iraq.', 23, '2002-12-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 7, 'Season 7', 'Join Stan, Kyle, Cartman and Kenny as they go gaga for “Queer Eye,” start their own Christian Rock Band, and discover that Earth is an intergalactic reality show that''s about to be cancelled. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 1, 'Cancelled', 'The boys are at the bus stop and they seem to be reliving events that they went through 6 seasons earlier; that is Kyle "kicking the baby" his little brother Ike and Cartman talking about his strange dream, which the other boys identify as visitors. What''s going on in South Park? Did the boys travel back in time, or is some sinister force at work?', 23, '2003-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 2, 'Krazy Kripples', 'Jimmy and Timmy pull together a group of people like themselves and call their new club the "Crips."', 23, '2003-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 3, 'Toilet Paper', 'The boys are given a detention due to their attitudes in art class. Cartman decides that they need to toilet paper (TP) the art teacher''s house in revenge.', 23, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 4, 'I''m a Little Bit Country', 'After participating in a walk-out against the war in Iraq, Mr. Garrison tells the boys they have to write a report on the founding fathers.  Cartman decides he''s going to figure out a way to flashback to the past and learn all about history first hand.', 23, '2003-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 5, 'Fat Butt and Pancake Head', 'For a report on Cultural Diversity, Cartman chooses to do one on Latinos in the arts with the help of a Jennifer Lopez hand puppet.  Later, at the mall, the puppet insists they make a music video, which launches the hand puppet''s musical career.  There''s just one problem, the REAL J-Lo shows up to protest the hand''s authenticity.', 23, '2003-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 6, 'Lil'' Crime Stoppers', 'The boys are playing "junior detectives," and have to find a kidnapped doll. After a daring rescue, they are taken back to Park County Police Headquarters. Upon their arrival, the Chief makes them "real" junior detectives and gives them their first assignment: breaking up a meth lab. The boys soon learn being real detectives isn''t as fun as they thought.', 23, '2003-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 7, 'Red Man''s Greed', 'The owners of the Three Feathers Indian Casino have decided to buy out the town of South Park in order to create a super-highway from Denver to their Casino. The townfolk only have one night to make $350,000. So they head to the casino...', 23, '2003-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 8, 'South Park is Gay', 'The metrosexual fad has hit South Park thanks to the "Queer Eye Guys," and all the men in town are affected, except for Kyle and his Dad.  Stan, Kenny, and Cartman give Kyle a makeover, and Gerald isn''t far behind. Soon the women of South Park grow tired of the fad, as does Mr. Garrison.', 23, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 9, 'Christian Rock Hard', 'The boys have hit a crossroads with their band "Moop." Cartman wants the band to play Christian Rock, and leaves the band when Stan, Kyle, and Kenny don''t agree. Before leaving, Cartman bets Kyle $10 that he will get a platinum album with a Christian Rock band before "Moop" can.', 23, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 10, 'Grey Dawn', 'Due to a rise in deaths due to senior citizens behind the wheel, the State of Colorado has revoked all the driver licenses of senior citizens.  Soon after, the AARP shows up to fight for the rights of their comrades.', 23, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 11, 'Casa Bonita', 'Kyle is going to Casa Bonita for his birthday, but he can only bring three friends. He chooses Stan, Kenny, and Butters. Cartman, outraged by not being chosen, comes up with a plan to take Butters out of the picture.', 23, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 12, 'All About Mormons', 'A new student, Gary Harrison, joins the 4th grade. Gary is a Mormon from Utah. The children decide he needs to get his ass kicked, and they choose Stan to do it. After an awkward exchange of words, Stan is invited to Gary''s house, where he learns all about Mormons.', 23, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 13, 'Butt Out', 'After seeing an auditorium presentation on the dangers of smoking (and in some ways, not smoking), the boys light up behind the school and are soon caught in the middle of Rob Reiner''s Anti-Tobacco campaign.', 23, '2003-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 14, 'Raisins', 'In an effort to find some closure in breaking up with Wendy, the boys take Stan to Raisins (a junior Hooters) so he can forget about her. Meanwhile, a trip to Raisins does big things for Butters, as he falls in love with a waitress.', 23, '2003-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 7), 15, 'It''s Christmas in Canada', 'When Ike is claimed by his Canadian birth parents, the boys set out to gain an audience with the Canadian Prime Minister. Meanwhile, Cartman''s biggest concern is that the boys don''t spend all of Christmas in Canada.', 23, '2003-12-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 8, 'Season 8', 'Join Stan, Kyle, Cartman and Kenny as they witness the girls’ celebrity-worship of ditzy, rich, sex-tape-making socialites and take part in an awesome anime battle with Professor Chaos. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 1, 'Good Times with Weapons', 'South Park takes on the look of Japanese Anime. The boys are transformed into Japanese Warriors after they buy martial arts weapons at a local flea market. Their sworn enemy, Professor Chaos, confronts them and a highly stylized battle ensues.', 23, '2004-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 2, 'Up the Down Steroid', 'Jimmy is in training for an upcoming sporting event and he’s determined to win at any cost. Cartman feels he can easily take first place against Jimmy. He just has to convince the qualifying committee he’s handicapped.', 23, '2004-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 3, 'The Passion of the Jew', 'Kyle finally sees “The Passion” and is forced to admit Cartman has been right all along. Meanwhile many of the film’s hardcore fans band together under Cartman’s leadership to carry out it’s message.', 23, '2004-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 4, 'You Got F''d in the A', 'It’s up to Stan to put a team of South Park’s best dancers together to compete against a rival troupe from Orange County. While Butters has won awards for his dancing, he refuses to help Stan out, as he hasn’t been able to dance since the tragic death of eight audience members at his last competition.', 23, '2004-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 5, 'AWESOM-O', 'Cartman dresses up like a robot, calls himself AWESOM-O, and moves in with Butters. His plan is to learn all of Butter’s innermost secrets and then use them against him. While Butters is thrilled to have found a new best friend, the Army believes AWESOM-O is some new secret weapon, and Hollywood is after the phony robot to develop their next big blockbuster.', 23, '2004-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 6, 'The Jeffersons', 'All the children of South Park are attracted to Mr. Jefferson, his son and their home filled with games, toys and animals. Cartman goes out of his way to get Mr. Jefferson to love him while the local police force resent him for being black and wealthy and decide to bring him down.', 23, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 7, 'Goobacks', 'Humans from the year 4035 are arriving in droves in South Park! Everything gets a little too crowded when people from the future arrive through a recently discovered time portal. When the boys try to earn some extra money, the time immigrants, who are willing to do the same work for next to nothing, take their jobs.', 23, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 8, 'Douche and Turd', 'When PETA demonstrates against the use of a cow as South Park Elementary’s mascot, the student body is forced to choose a new one. As the election approaches, Kyle tries to convince everyone that his candidate, a giant douche, is better than Cartman’s nominee, a turd sandwich.', 23, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 9, 'Something Wall-Mart This Way Comes', 'The streets of South Park are like a ghost-town when a giant Wall-Mart lures all the townspeople to the new store with its incredible bargains. Cartman becomes a boy possessed by the power of Wall-Mart and its low, low prices. In order to save their town, Stan and Kyle have to find a way to destroy the ever-expanding superstore while keeping Cartman from stabbing them in the back.', 23, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 10, 'Pre-School', 'For five long years, Stan, Kyle, Kenny, Cartman and Butters have kept a secret about a horrible incident that happened back in pre-school. Now, the kid who took the fall for the group, Trent Boyett, is getting out of juvie and his first order of business is revenge.', 23, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 11, 'Quest for Ratings', 'The boys of South Park produce their own morning news show on the school’s closed-circuit television station and are immediately caught up in the intense competition for ratings.', 23, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 12, 'Stupid Spoiled Whore Video Playset', 'All the fourth grade girls idolize a rich, famous and spoiled socialite. They even have her brand new toy set that comes complete with video camera, night vision filter, play money and losable cell phone. In an effort to impress their idol, the girls pursue the boys to make their own videos.', 23, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 13, 'Cartman''s Incredible Gift', 'After sustaining a severe head injury, Cartman appears to have the power to see into the future. South Park detectives are quick to enlist his help in cracking unsolved murder cases and Cartman is more than willing to help, for a price. In the meantime, a group of licensed psychics cry foul when Cartman refuses to join their ranks.', 23, '2004-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 8), 14, 'Woodland Critter Christmas', 'Stan is approached by the forest critters and asked to help them build a manger in anticipation of the birth of their Lord and Savior. Stan complies, only to find out that they serve a very different Lord.', 23, '2004-12-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 9, 'Season 9', 'Join Stan, Kyle, Cartman and Kenny as they deal with the perceived dangers of global warming, a certain actor''s sexuality is questioned, and the Pope arrives to witness a religious miracle. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 1, 'Mr. Garrison''s Fancy New Vagina', 'Mr. Garrison goes to great lengths to get what he’s always wanted…a sex change. As he enjoys his new womanly attributes, the rest of the town gets in touch with their inner feelings too. Meanwhile, Kyle wrestles with the fact that Jews just aren’t good at basketball.', 23, '2005-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 2, 'Die Hippie, Die', 'Cartman seeks to rid the world of hippies once and for all.', 23, '2005-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 3, 'Wing', 'As talent agents, Cartman, Stan, Kyle and Kenny can bank 10% of their client’s earnings. After they pool all their resources to impress their one and only client, another agency steals him away. Desperate to earn their money back, they take on another client with plans to launch her on a new reality show.', 23, '2005-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 4, 'Best Friends Forever', 'Kenny is the only one of his friends to get the newest, coolest portable gaming device and Cartman can’t deal with it. Will they remain best friends forever?', 23, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 5, 'The Losing Edge', 'If the boys can lose just one baseball game, it gets them out of playing the boring sport for the entire summer.', 23, '2005-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 6, 'The Death of Eric Cartman', 'Butters is freaked out when he thinks he can communicate with the dead. Although his parents have made it clear to him there are no such things as ghosts, Butters is sure one is haunting him. Butters knows he has to give up his ghost pal or be put into a mental institution.', 23, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 7, 'Erection Day', 'All the kids are getting ready for the big South Park Elementary Talent Show and Jimmy can’t wait to perform his new comedy routines. But lately, just like generations of little boys before him, Jimmy’s noticed that one of his body parts has a mind of its own. Knowing he can’t get up in front of the entire school in an excited state, Jimmy must find a way to gain control of his raging hormones in time to perform in the show.', 23, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 8, 'Two Days Before the Day After Tomorrow', 'A global warming state of emergency is declared in South Park. The world’s largest beaver dam breaks and floods the adjacent town of Beaverton. As the victims wait for help to arrive, everyone in South Park tackles priority number one: who is to blame? Only Stan and Cartman know who’s really at fault.', 23, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 9, 'Marjorine', 'The 4th grade girls are having a sleepover. It’s imperative that the boys find out what goes on behind those closed doors. Butters is picked to be the boy who must fake his death, become a girl and infiltrate this age-old feminine tradition.', 23, '2005-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 10, 'Follow That Egg', 'Mrs. Garrison realizes he still has feelings for Mr. Slave. But, Mr. Slave has moved on. He plans to marry his new love as soon as the Governor signs the same-sex marriage bill. Mrs. Garrison leads the charge against gay marriage.', 23, '2005-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 11, 'Ginger Kids', 'Cartman suffers from a mysterious and sudden on-set of the disease, Gingervitus. Sick and tired of being ripped-on because he now has red hair, light skin and freckles, he rallies all ginger kids everywhere to fight against discrimination.', 23, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 12, 'Trapped in the Closet', 'Religious leaders recognize Stan as the second coming and a whole soap opera unfolds with the help of a famous R&B singer. The results of Stan’s personality test reveal that he’s depressed. While Stan looks to a new religion for answers, the church leaders recognize Stan as the second coming. Some A-List Hollywood celebrities join the faithful who have set up camp right in front of Stan’s house.', 23, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 13, 'Free Willzyx', 'A “talking” whale inspires the fourth-graders to risk everything to return him to his family. With the police on their tails, the boys enlist the help of a foreign government and embark upon an adventure you’ll not soon forget. One in which the boys learn just how far you would go for a friend.', 23, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 9), 14, 'Bloody Mary', 'Stan is embarrassed in front of his friends when his dad gets pulled over for drunk driving. In a neighboring town, a bleeding statue of Mary is discovered and the faithful are flocking to the site hoping to be healed. Stan’s dad is sure the bleeding Virgin can cure him of his disease.', 23, '2005-12-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 10, 'Season 10', 'Join Stan, Kyle, Cartman and Kenny as they witness the death of Chef, defeat a virtual villain out to destroy the world, and suffer the consequences of Cartman’s video game console obsession. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 1, 'The Return of Chef', 'The town is excited when Chef returns to town after world traveling with the “Super Adventure Club,” but the boys notice something is different about Chef.  It seems that Chef’s new sense of adventure has gotten the better of him and the boys try to save him.', 23, '2006-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 2, 'Smug Alert!', 'Stan is the driving force who gets the citizens of South Park to all buy hybrid cars. Just as everyone starts to feel really good about what they’re doing to help save the earth, a stormy dark mass has started accumulating over the town.', 23, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 3, 'Cartoon Wars (1)', 'Cartman and Kyle are at war over the popular cartoon, Family Guy. Kyle loves it and Cartman hates it. When the show airs some controversial content the boys go on a cross country chase with the fate of Family Guy lying with the first boy to reach Hollywood.', 23, '2006-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 4, 'Cartoon Wars (2)', 'With Kyle left behind, Cartman makes his way to FOX to get the Family Guy episode pulled, hoping to ultimately get rid of the show once and for all.', 23, '2006-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 5, 'A Million Little Fibers', 'Towelie writes a book and it gets selected for Oprah’s book club.  It becomes a best seller with everyone getting a lot help for their addictions; until a faction of Oprah''s staff leak the truth about the book.', 23, '2006-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 6, 'Manbearpig', 'While assisting an ex-Vice President in his quest for attention, the boys get trapped by a cave-in and while searching for a way out, Cartman discovers treasure.  Now he has to figure out how to get out of the cave without the others knowing about it and he can keep it all for himself.', 23, '2006-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 7, 'Tsst', 'When Cartman''s mom realizes she can''t control her son anymore, she gets help from an expert. Cesar Millan, “The Dog Whisperer" takes on the challenge and while he might have what it takes, Eric Cartman''s not going down without a fight.', 23, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 8, 'Make Love, Not Warcraft', 'A renegade player threatens the Massively Multiplayer Online game World of Warcraft and the fate of the game lay in the hands of Cartman, Kyle, Stan and Kenny.', 23, '2006-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 9, 'Mystery of the Urinal Deuce', 'Cartman reveals who masterminded the attacks of 9/11, while Kyle and Stan search for the real truth; meanwhile Mr. Mackey just wants to know who dropped the deuce in the urinal.', 23, '2006-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 10, 'Miss Teacher Bangs a Boy', 'Cartman, South Park Elementary’s new hallway monitor, takes it personally when he finds out that a teacher has been kissing a student in his jurisdiction.  He helps Kyle stop his little brother’s affair with his “Nice” hot teacher.', 23, '2006-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 11, 'Hell on Earth 2006', 'Satan is throwing the world''s biggest Halloween costume party, and no one is getting in without a blue wrist band. Unfortunately, even Satan can''t plan for everything as a religious organization and the antics of the most notorious serial killers of all time might ruin his good time.', 23, '2006-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 12, 'Go God Go (1)', 'The topic of evolution is introduced to the 4th graders of South Park Elementary and while their teacher is against the theory a change of mind has implications for the future.  And speaking of the future, Cartman is trying to send himself there; to the exact date that the newest video game console, the Nintendo Wii is being released.', 23, '2006-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 13, 'Go God Go XII (2)', 'Last week, in an attempt to make his wait for the Wii instantaneous, Cartman froze himself. Through a bizarre twist of fate, he woke up 500 years in the future, where there are warring factions, some angry sea otters, and worst of all: No Nintendo Wii! Will Cartman get out of this crazy future? Or will he be doomed to never get his hands on the Wii?', 23, '2006-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 10), 14, 'Stanley''s Cup', 'Stan becomes coach of a Pee Wee Hockey team and for the benefit of one his players he tries to make them into a team of winners.  Meanwhile his father deals with the memory of Stan’s performance in a Pee Wee hockey game from years earlier, when Stan had the opportunity to score the game winning goal.', 23, '2006-11-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 11, 'Season 11', 'It’s a season of diabolical secrets as Cartman covers up a salacious photo and the boys reveal a bizarre Easter society. An explosive visit from Hillary Clinton, a world-record crap and the Imaginationland trilogy only add to the awesomeness of Season 11.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 1, 'With Apologies to Jesse Jackson', 'Randy uses the "N" word on live TV and faces public ridicule for it and Stan tries to understand Token''s feelings on the subject. Meanwhile, a little person visits South Park Elementary and Cartman can''t stop himself from laughing at him.', 23, '2007-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 2, 'Cartman Sucks', 'Butters'' dad sends him off to special camp to "Pray the Gay Away" when he believes that his son is bi-curious after catching him in a compromising position with Cartman.  Meanwhile, Cartman does his best to retrieve a photo of him in that compromising position before too many people find out about it.', 23, '2007-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 3, 'Lice Capades', 'When a breakout of headlice hits South Park Elementary, Mrs. Garrison refuses to say which child brought the plague to the school. So, Cartman takes it upon himself to find out who it is so the kids can make fun of them. Meanwhile, a louse Travis, is desperate to save his fellow lice from imminent destruction from a conscious world.', 23, '2007-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 4, 'The Snuke', 'The citizens of South Park are gearing up for the arrival of Hillary Clinton for a big campaign rally. Meanwhile, Cartman suspects that a new Muslim student is involved in a possible terrorist attack. Every minute counts for Cartman as he uses his own interrogation methods on his suspect. But could the plan to target Clinton be just the tip of the iceberg?', 23, '2007-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 5, 'Fantastic Easter Special', 'Stan wants to know the real reason kids have to decorate eggs for Easter, and what, if anything eggs and bunnies have to do with Jesus dying for his sins. To get to the bottom of it, Kyle and Stan get wrapped up in a bizarre society that guards a legendary secret.', 23, '2007-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 6, 'D-Yikes!', 'Once again Ms. Garrison gets dumped, but this time she decides to take it out on her fourth grade class. When the boys have finally had enough of their teacher''s erratic mood swings and excessive homework assignments, they find out that there are people-for-hire that can help out in any situation. Meanwhile, Ms. Garrison is finding life without men has its upsides.', 23, '2007-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 7, 'Night of the Living Homeless', 'The number of homeless people in South Park is increasing as they eat, sleep, and beg for change across the town. While the adults try to find creative solutions to deal with the homeless, the boys are trying to figure out a way to solve the problem for good', 23, '2007-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 8, 'Le Petit Tourette', 'Upon discovering Tourette''s syndrome, Cartman becomes mad with power. He finds out he has the ability to say whatever he wants without consequence, so he sets up National TV Coverage to take full advantage of his new found life.', 23, '2007-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 9, 'More Crap', 'Stan''s dad becomes South Park''s home-town hero when the guys down at the local bar see the size of his most recent crap. Randy contacts a society that keeps track of the world record, thinking his masterpiece would definitely be a contender.', 23, '2007-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 10, 'Imaginationland', 'When the entire contents of the world''s imagination lay open before them, Stan and Kyle step right in. Back in South Park, Cartman swears he''s seen a leprechaun.', 23, '2007-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 11, 'Imaginationland, Episode II', 'Stan and Kyle are being held captive at the Pentagon until they tell the government exactly how they got into Imaginationland. Elsewhere, Cartman will not give up his quest to make Kyle follow through on their bet to suck his balls.', 23, '2007-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 12, 'Imaginationland, Episode III', 'Inside Imaginationland, Stan and Butters engage in the battle of their lives as they fight the army of evil imaginary forces. Meanwhile, Cartman goes all the way to the Supreme Court to get Kyle to suck his balls.', 23, '2007-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 13, 'Guitar Queer-O', 'Stan and Kyle become obsessed with Guitar Hero to the point where they''re breaking high score records. It doesn''t take long for Stan to realize that he could go even further with a different partner. Will the stress of being a rock star get to Stan now that his best friend is no longer by his side?', 23, '2007-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 11), 14, 'The List', 'The girls in the fourth grade class have made a secret list that rates every boy''s looks from cutest to ugliest. When the boys steal the list, they are completely unprepared to deal with the results.', 23, '2007-11-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 12, 'Season 12', 'Join Stan, Kyle, Cartman and Kenny as they help a pop-princess down on her luck, negotiate a truce for striking Canadians, fight the addiction of "cheesing" and battle startling rodents. For them, it''s all part of growing up in South Park');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 1, 'Tonsil Trouble', 'After going in for a routine tonsillectomy, a botched transfusion leaves Cartman afflicted with an incurable disease. When he finds no comfort in his friends and family, how far will he go to find a cure?', 23, '2008-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 2, 'Britney''s New Look', 'While trying to escape her troubles in the secluded mountains near South Park, Britney Spears has a run-in with the boys. Stan and Kyle get swept up in her celebrity as well as the non-stop feeding frenzy that plagues her wherever she goes. The boys must take Britney to the North Pole when they learn the secret behind what makes her so popular.', 23, '2008-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 3, 'Major Boobage', 'In a South Park homage to the 1981 film, “Heavy Metal”, the boys are trying to get Kenny off the latest drug craze that’s captured the junior high and under set.', 23, '2008-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 4, 'Canada on Strike', 'The head of the World Canadian Bureau leads the country into a long and painful strike and the responsibility of brokering a settlement rests with the boys.', 23, '2008-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 5, 'Eek, A Penis!', 'While Ms. Garrison is off trying to find a way to become the man he was always intended to be, Cartman is put in charge of the classroom.', 23, '2008-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 6, 'Over Logging', 'The citizens of South Park wake up one morning shocked to find the Internet is gone. Upon hearing news that the Internet may remain in California, Randy decides to head out west with the family.', 23, '2008-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 7, 'Super Fun Time', 'While the kids are on an educational field trip to a living museum, Cartman makes Butters sneak away from the class to go to the amusement center located next door.', 23, '2008-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 8, 'The China Probrem', 'After watching the intimidating opening ceremonies of the recent Olympic games, Cartman understands that the Chinese are only just days away from invading his homeland. While the rest of the American people are haunted by the memory of a recent tragic event, only Butters will stand with Cartman as he confronts the Chinese.', 23, '2008-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 9, 'Breast Cancer Show Ever', 'Wendy gets in trouble when she threatens to beat up Cartman after school. No matter how fired up Wendy is, all bets are on Cartman. Everybody knows a girl can''t fight a boy and win.', 23, '2008-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 10, 'Pandemic', 'The boys find a way to make money off an international crisis that requires no talent and very little effort. Cartman convinces the other boys to invite Craig to get in on their latest plan. He knows Craig has just what it takes to make their dream a reality.', 23, '2008-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 11, 'Pandemic 2: The Startling', 'Giant guinea pigs are attacking cities all over the world. The boys have the key that will save everyone from the onslaught but they''re stranded in the Andes Mountains.', 23, '2008-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 12, 'About Last Night...', 'While the country celebrates the outcome of the election, the new President-elect catches everyone off guard when he arrives at the White House prematurely.', 23, '2008-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 13, 'Elementary School Musical', 'Stan realizes he could lose Wendy if he doesn''t get on board with the latest fad to hit South Park Elementary. Cartman would rather kill himself than succumb. But, when Stan, Kyle, Kenny and Cartman all realize that Butters is now more popular than they are, they have no choice but to give in to peer pressure.', 23, '2008-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 12), 14, 'The Ungroundable', 'Butters is sure he’s seen a vampire at school but he can’t get anyone to listen to him. Meanwhile, the Goth Kids are angry and frustrated when the other kids can’t tell the difference between a Goth and a Vampire.', 23, '2008-11-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 13, 'Season 13', 'Join Cartman, Kenny, Stan and Kyle as they save the economy, the whales, and a bunch of dead celebrities all while discovering the joys of Fish Sticks. For them, it''s all part of growing up in South Park');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 1, 'The Ring', 'Thinking it''s his way into her heart and other body parts, Kenny takes his new girlfriend to a Jonas Brothers concert. His dream of taking their relationship to the next level is crushed when the Jonas Brothers give them purity rings.', 23, '2009-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 2, 'The Coon', '“The Coon” rises from the trash and takes his place as a lone vigilante who wipes out crime in the town of South Park. A rival superhero appears on the scene in the form of “Mysterion” and challenges the Coon’s place as a “symbol” for the town.', 23, '2009-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 3, 'Margaritaville', 'Randy steps forward with a solution to fix the desperate financial state everyone finds themselves in. The town gets behind him and everyone starts to live a life that no longer depends on any economy at all. Meanwhile an unlikely savior makes the ultimate sacrifice to solve everyone’s problems.', 23, '2009-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 4, 'Eat, Pray, Queef', 'Someone played an April Fools joke on the boys and it didn''t go over well. Butters is incapacitated, Cartman is furious and the rest of the boys are afraid someone might do it again.', 23, '2009-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 5, 'Fishsticks', 'Cartman decides to help Jimmy with his comedy routine. Everyone loves the new joke they come up with. The joke starts to take off and it even hits all the late night talk shows. The boys are thrilled with how popular it’s become until somebody tries to take all the credit.', 23, '2009-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 6, 'Pinewood Derby', 'Randy is determined that Stan will win this year''s Pinewood Derby. He comes up with a plan that will assure Stan a first place trophy.', 23, '2009-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 7, 'Fatbeard', 'Butters and a small group of recruits join Cartman in his dream of living on skull island. Cartman promises that paradise awaits if they can just get to Somalia.', 23, '2009-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 8, 'Dead Celebrities', 'Powerful forces are tormenting Ike. He''s freaked out and the stress could kill him. Kyle and the boys are doing everything they can to save him but the poltergeists won''t leave Ike alone.', 23, '2009-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 9, 'Butters'' Bottom Bitch', 'Butters has made it all the way to the 4th grade without ever kissing a girl. All of his friends have been teasing him mercilessly. Butters is determined to catch up with the rest of the boys in his class. Meanwhile, one overly dedicated cop wages war on prostitution in South Park.', 23, '2009-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 10, 'W.T.F.', 'The boys have found their new calling in life and they hurry to sign up for the wrestling club. They soon find out the kind of wrestling they teach at school is not the same thing they saw at the WWE.', 23, '2009-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 11, 'Whale Whores', 'Stan and his family are spending his birthday at the Denver Aquarium where they will get to swim with the dolphins. Things turn bloody when the Japanese attack, kill all the dolphins and ruin Stan’s big day. There seems to be no end to the senseless killing. Stan takes on the cause to save the dolphins from the Japanese.', 23, '2009-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 12, 'The F Word', 'Everyone agrees they''ve had enough of the loud and obnoxious bikers that have arrived in South Park. The boys are taking on the Harley Riders. They thrown down the F word and the game is on.', 23, '2009-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 13, 'Dances With Smurfs', 'Eric Cartman seizes the opportunity to become the voice of change at the school when he takes over the morning announcements. His target is South Park Elementary’s Student Body President, Wendy Testaburger. Cartman is asking the tough questions and gaining followers.', 23, '2009-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 13), 14, 'Pee', 'Things at the water park are not what they seem. The boys'' fun filled day is about to turn deadly. Events are in play at Splash Town that signal the end of the world is upon us. Cartman tries to warn everyone but no one will listen. Disaster is about to strike and the boys are in a race to survive.', 23, '2009-11-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 14, 'Season 14', 'This series finds Stan, Kyle, Cartman, Kenny, Butters and co getting into fixes through their usual blend of innocence and mischievousness. As well as coming to terms with the perils of social networking and being accused of sex addiction in the furore that sweeps the nation in the wake of the revelations surrounding Tiger Woods, the boys finally reveal the identity of the suitably mysterious Mysterion in a three-part special.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 1, 'Sexual Healing', 'The nation''s top scientists come together to put a stop to the recent phenomenon of rich, successful men who suddenly want to have sex with many, many women. After extensive testing, some of the fourth grade boys in South Park Elementary are diagnosed as sex addicts.', 23, '2010-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 2, 'The Tale of Scrotie McBoogerballs', 'The boys are given a controversial book to read in school that both excites and inspires them to write one of their own. When the boys discover that Stan''s mom has found their masterpiece, their new motivation is how they can stay out of trouble.', 23, '2010-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 3, 'Medicinal Fried Chicken', 'State Law in Colorado says it''s legal to smoke pot if you have a physician''s reference. Randy is the first-in-line to buy some but he''s turned away because there''s absolutely nothing wrong with him. Randy is desperate to get a medical excuse to smoke some weed but meanwhile, Cartman will do anything to get his beloved fried chicken restaurant back.', 23, '2010-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 4, 'You Have 0 Friends', 'Kyle "friended" the wrong person and now all of his old friends are deserting him. His situation is desperate. Kyle looks for help from the one person who has always been there for him.', 23, '2010-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 5, '200', 'While on a school field trip, Stan accidentally insults Tom Cruise and sets off a chain reaction. 200 previously ridiculed celebrities stand strong in a class action lawsuit against the town of South Park.', 23, '2010-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 6, '201', 'Angry celebrities, violent ginger kids and Mecha Streisand are about to destroy South Park and all anyone wants to know is, “Who is Eric Cartman’s father?”', 23, '2010-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 7, 'Crippled Summer', 'Competition is the name of the game this summer. There is no time for Jimmy and his friends to slack off. They''re working to be this year''s champions at summer camp. Jimmy suits up and prepares to shred in the annual surfing contest.', 23, '2010-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 8, 'Poor and Stupid', 'Cartman wants to race with the pros and he''s ready to do whatever it takes to make it happen. He''s afraid that no matter how hard he tries, he''ll never reach the level of the other NASCAR drivers. Working with Butters as his pit boss, Cartman pulls out all the stops to compete in the race of his life.', 23, '2010-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 9, 'It''s a Jersey Thing', 'New Jersey is rapidly taking over the nation one state at a time and their next stop is South Park.', 23, '2010-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 10, 'Insheeption', 'When Stan is sent to the school counselor because he''s holding on to an obscene number of useless possessions, he realizes that Mr. Mackey has a hoarding disorder too.', 23, '2010-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 11, 'Coon 2: Hindsight', 'The Coon now leads an entire team of crime-fighters. They are ready to take their place among the worlds most admired and beloved super heroes. But much to the Coons dismay, someone else keeps beating them to the punch. The nation looks to another hero to get them through the BP disaster and dissention develops within the ranks of Coon and friends.', 23, '2010-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 12, 'Mysterion Rises', 'Led by Mysterion, Coon and Friends are working together to help the people in the Gulf who are at the mercy of the dark lord, Cthulhu. The Coon, scorned by his fellow super heroes and now working alone, is out for revenge.', 23, '2010-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 13, 'Coon vs. Coon & Friends', 'The Coon shows himself to be even more evil than the dark lord, Cthulhu, as he punishes his former partners in Coon & Friends. Kenny McCormick, is wrestling with the weight of his own super power through his alter-ego, Mysterion. Will Coon and Friends save the day? Will Mysterion ever come to terms with his ability to defy death? All this as the nation waits and wonders: Where is Captain Hindsight?', 23, '2010-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 14), 14, 'Crème Fraiche', 'Stan''s life is a shambles both at home and in school. Randy''s obsession with the Food Network Is changing everything. It even forces Sharon to explore a new interest of her own.', 23, '2010-11-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 15, 'Season 15', 'Join Stan, Kyle, Cartman and Kenny in the fifteenth season as they confront modern mad scientists, fundamentalist agnostics, and face their greatest challenge yet -- Stan growing a year older. For them, it''s all part of growing up in South Park.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 1, 'HUMANCENTiPAD', 'Kyle is intimately involved in the development of a revolutionary new product that is about to be launched by Apple. Meanwhile, Cartman doesn''t even have a regular iPad and blames his mother.', 23, '2011-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 2, 'Funnybot', 'At the school''s first annual Comedy Awards, Jimmy announces that the Germans are the least funny people in the world. Germany is highly insulted. They vow that retaliation toward the kids at South Park Elementary will be swift and brutal.', 23, '2011-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 3, 'Royal Pudding', 'The Prince of Canada is about to take a Princess and Ike is obsessed with the Royal Wedding.', 23, '2011-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 4, 'T.M.I.', 'Cartman is furious when he believes that the school has posted their penis sizes on the bulletin board. He throws an absolute fit; takes matters into his own hands and once again finds himself in the principal''s office. This time he gets sent to anger management therapy.', 23, '2011-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 5, 'Crack Baby Athletic Association', 'Cartman has a new protege. He''s found someone who is smart, ambitious and willing to look the other way in order to get to the top.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 6, 'City Sushi', 'Butters is diagnosed with multiple personality disorder. Meanwhile, the owner of City Wok is angered when a competing Asian restaurant opens next door.', 23, '2011-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 7, 'You''re Getting Old', 'After Stan celebrates his 10th birthday, he begins to see everything differently. The other boys think he''s become a major buzzkill and start to avoid hanging out with him. When Stan and Kyle have a major blow up, the very fabric of South Park begins to unravel.', 23, '2011-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 8, 'Ass Burgers', 'Cartman finds a unique way of coping with Asperger''s Syndrome. Even Kyle and Kenny are on board. Meanwhile, Stan can''t seem to get his life back to normal no matter what he tries. Will anything ever be the same in South Park again?', 23, '2011-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 9, 'The Last of the Meheecans', 'What begins as an innocent game between the boys turns serious when Cartman joins the U.S. Border Patrol. Not surprisingly, Cartman turns out to be really good at stopping Mexicans.', 23, '2011-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 10, 'Bass to Mouth', 'The students of South Park Elementary are the victims of a new gossip website. An elusive hacker has somehow gained access into the student''s confidential phone calls and e-mails and is posting all their juicy stories. The boys are shocked when they discover the identity of the hacker.', 23, '2011-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 11, 'Broadway Bro Down', 'Sharon is thrilled that Randy is making an effort to do more things that she enjoys. But, after he takes her to see a hit musical in Denver, Randy becomes Broadway’s biggest fan. Sharon is whisked away to New York and treated to every musical on the Great White Way.', 23, '2011-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 12, '1%', 'The kids at South Park Elementary are being punished for Cartman''s failings in the physical education department. What will Cartman do when they all gang up on him?', 23, '2011-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 13, 'A History Channel Thanksgiving', 'After watching a Thanksgiving special on The History Channel, the boys believe that aliens were involved in the original feast. But, questions remain... was the first Thanksgiving haunted? Is alien technology responsible for stuffing? The truth could change Thanksgiving for everyone.', 23, '2011-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 15), 14, 'The Poor Kid', 'With their parents in jail, Kenny and his brother and sister find themselves in the foster care system. Cartman is sincerely disturbed when Kenny is taken away. He doesn''t know who to rip on for being the poorest kid in school anymore.', 23, '2011-11-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 16, 'Season 16', 'Join Cartman, Kenny, Stan and Kyle as they hunt down the mythical Jewpacabra, ‘sketti wrestle with reality stars, and go jackin’ it in San Diego. For them, it''s all part of growing up in South Park.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 1, 'Reverse Cowgirl', 'One of the boys had been told time and time again about leaving the toilet seat up after he goes to the bathroom, but he didn''t listen. His actions have consequences and ultimately result in an unimaginable catastrophe.', 23, '2012-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 2, 'Cash for Gold', 'Cartman launches a gemstones network show and creates a very lucrative business. Stan searches for the real value of a piece of jewelry that was a gift from his Grandpa. Meanwhile, Cartmans lucrative new business preys upon an extremely vulnerable clientele.', 23, '2012-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 3, 'Faith Hilling', 'Mankind''s evolution begins to accelerate at a rapid and disturbing pace. Concurrently, another species on the planet is exhibiting the same drastic development. Eventually the two species will battle to the death and "Faith Hilling" may be humanity''s only hope.', 23, '2012-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 4, 'Jewpacabra', 'South Park''s big Easter egg hunt is in jeopardy when there are rumors of a dangerous beast lurking in the woods nearby. Cartman tries to warn everyone that their lives are at risk if they participate in the egg hunt. No one believes him until he produces video evidence of the mystery being.', 23, '2012-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 5, 'Butterballs', 'Stan wants to raise awareness about the dangers of bullying by shooting a big dance video, while Butters falls victim to an unlikely bully.', 23, '2012-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 6, 'I Should Have Never Gone Ziplining', 'The boys try zip-lining in the Colorado mountains on the last day of spring break, but their adventure takes a dangerous, life-threatening turn.', 23, '2012-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 7, 'Cartman Finds Love', 'There''s a new girl in school and everyone wants to know who she has a crush on. Cartman is especially excited. He''s discovered something inside himself that he never knew he had. Now, to make sure nobody gets in the way of true love, it''s time for Cartman to finally let someone know exactly how he feels.', 23, '2012-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 8, 'Sarcastaball', 'Randy''s campaign to prevent head injuries in football radically changes the way the game is played, but the new rules become a national sensation and even make a South Park student a star athlete.', 23, '2012-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 9, 'Raising the Bar', 'Cartman owns up to being fat and decides that driving around on a scooter is his right. Kyle sees that Cartman isn''t the only one who finds no shame in his unhealthy lifestyle. Meanwhile, Cartman discovers he has a rival in America’s Sweetheart, Honey Boo Boo.', 23, '2012-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 10, 'Insecurity', 'The man who visits all the homes in South Park every day is under suspicion. Cartman takes matters into his own hands and signs up for a home security system.', 23, '2012-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 11, 'Going Native', 'It is time for Butters to begin a journey where he will follow in the path of his Hawaiian ancestors.', 23, '2012-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 12, 'A Nightmare on FaceTime', 'The boys plans to go as the Avengers for Halloween go awry when Randy can’t go at the last minute and Stan has to help his father with a new business venture.', 23, '2012-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 13, 'A Scause for Applause', 'Rocked by the recent news of drug use by a beloved icon, the world is left feeling lost and betrayed. The boys, join with the rest of the nation, and remove their yellow wristbands. Everyone is on board, except for Stan, who just can’t seem to cut off his bracelet.', 23, '2012-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 16), 14, 'Obama Wins!', 'Eric Cartman is hiding something in his bedroom that could change the entire outcome of the Presidential election.', 23, '2012-11-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 17, 'Season 17', 'Join Stan, Kyle, Cartman and Princess Kenny as they infiltrate the NSA, thwart patient zero, tame some strange and fight in the greatest battle of their young, hot lives.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 1, 'Let Go, Let Gov', 'When Cartman manages to get himself behind the doors of the NSA, he doesn’t like what he finds in his personal file. He thinks it’s time he told everyone the truth. Meanwhile, Butters finds someone new to listen to his prayers.', 23, '2013-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 2, 'Informative Murder Porn', 'The boys use the game of MINECRAFT as a distraction to keep their parents from hurting each other.', 23, '2013-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 3, 'World War Zimmerman', 'Cartman is deeply disturbed by a single person who he sees as a threat to all humanity. He races around the country to put an end to Patient Zero, the ticking time bomb that is Token.', 23, '2013-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 4, 'Goth Kids 3: Dawn of the Posers', 'One of the Goth kids has been sent to a camp for troubled children. When she returns, her friends find her changed in a disturbing way. With their very existence threatened, the Goths have to do something drastic. They are forced to ask the Vamp kids for help.', 23, '2013-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 5, 'Taming Strange', 'When Ike hits puberty, he and Kyle start to grow apart. To save their relationship, Kyle takes Ike to see a live performance of Yo Gabba Gabba.', 23, '2013-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 6, 'Ginger Cow', 'Cartman''s latest prank has brought about the necessary spiritual conditions for world peace. Religious leaders descend upon South Park to witness a Biblical prophecy that has been fulfilled. Cartman and Kyle are the only two at odds as the world embarks upon a thousand years of peace and harmony.', 23, '2013-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 7, 'Black Friday', 'Anticipation for the biggest shopping day of the year is building. The dark days of winter are coming and that can only mean one thing: the fight to be the first in the mall on Black Friday has begun. The boys prepare to battle the crowds the day after Thanksgiving to get the best deal on the new gaming systems.', 23, '2013-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 8, 'A Song of Ass and Fire', 'Hordes of souless shoppers approach the mall in anticipation of the Black Friday sales. The kids prepare for an epic battle where one faction''s favorite gaming device will come out on top. Will Stan and Kyle''s friendship survive Black Friday?', 23, '2013-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 9, 'Titties and Dragons', 'The doors to the mall will finally open for the biggest Black Friday sale in history. The boys are divided over which gaming device to buy and a bloody battle will determine whether Xbox or Sony will be the winner.', 23, '2013-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 17), 10, 'The Hobbit', 'When Wendy tries to prove a point about how much pressure little girls feel to look like celebrities, it gets her in trouble with everyone at school, and gets Clyde a new girlfriend.', 23, '2013-12-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 18, 'Season 18', 'Join Cartman, Kenny, Stan and Kyle as they get lost in virtual reality, go underground with Cock Magic, and uncover the shocking truth about a music superstar. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 1, 'Go Fund Yourself', 'After Cartman and the boys name their new company, The Washington Redskins, they just sit back and watch the funding roll in. The head coach of the Washington Redskins football team demands that they change the name but Cartman digs in his heels. The Washington Redskins may never mean the same thing ever again.', 23, '2014-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 2, 'Gluten Free Ebola', 'Mr. Mackey is now gluten free and everyone is annoyed when he won’t quit preaching about how great he feels. But, after witnessing a disturbing demonstration of what happens to your body when you do eat gluten, South Park becomes the first town in America to go gluten free.', 23, '2014-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 3, 'The Cissy', 'Stan is searching for answers about how a person who he’s always known to be one thing could suddenly identify with another. In the meantime, the pressure of holding on to a giant secret is starting to get to Randy.', 23, '2014-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 4, 'Handicar', 'Timmy’s idea to raise money for the summer camp has everyone in South Park trying out the latest trend in transportation. Timmy’s success makes him a lot of enemies and a bloodbath of epic proportions is on the horizon.', 23, '2014-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 5, 'The Magic Bush', 'A scandalous invasion of privacy has everyone in South Park on edge when graphic video from an unknown drone is uploaded on the internet. Cartman and Butters get their hands on a drone and can''t resist the urge to take it for a spin around the neighborhood.', 23, '2014-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 6, 'Freemium Isn''t Free', 'The kids in “South Park” are playing the new Terrance and Phillip mobile game. Stan is addicted to the latest app to hit the market. Meanwhile, Terrance and Phillip aren’t feeling so good about the fortune they’re making on their new mobile game.', 23, '2014-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 7, 'Grounded Vindaloop', 'Butters is convinced that he’s living in a virtual reality. When he suddenly goes rogue and wreaks havoc at home and all over South Park, everyone struggles to figure out what’s real.', 23, '2014-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 8, 'Cock Magic', 'Kenny excels at playing the game, Magic: The Gathering. He has the boys’ full attention until a new, hard-core activity gets in the way. When Wendy tries to get Stan to pay attention to what she’s doing, she realizes that what he does with his guy friends always comes first.', 23, '2014-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 9, '#REHASH', 'After Ike refuses to play a new game with Kyle, Kyle thinks the new generation of kids is terrible. Cartman becomes part of this new generation. Meanwhile Randy has drama going on with the music industry.', 23, '2014-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 18), 10, '#HappyHolograms', 'Kyle plans a holiday special for TV in hopes of bringing families together again with help from some of the biggest names in entertainment.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 19, 'Season 19', 'Join Cartman, Kenny, Stan and Kyle as Mr. Garrison makes a bid for the White House, Randy takes the lead in gentrifying the town, and everyone is looking for their safe space. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 1, 'Stunning and Brave', 'There is a new principal at the helm of South Park Elementary. He forces the boys to confront the damage they’ve done through their history of racism and unconscious bias. It is the most stunning and brave South Park ever.', 23, '2015-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 2, 'Where My Country Gone?', 'Mr Garrison is fed up with undocumented immigrants, and proposes building a wall to keep them out.', 23, '2015-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 3, 'The City Part of Town', 'As the town is gentrifying around him, Kenny attempts to climb out of the cycle of poverty by taking a job at City Wok.', 23, '2015-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 4, 'You''re Not Yelping', 'There’s a new kid in school and his parents have opened a restaurant in the recently gentrified part of town. Cartman now considers himself the top on-line restaurant reviewer in South Park.', 23, '2015-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 5, 'Safe Space', 'Cartman is the latest victim of body shaming on Twitter. Randy has to deal with uncomfortable confrontations every time he shops at the new Whole Foods. He feels exposed at every turn and it’s ruining his Whole Foods experience. Randy and Cartman are both seeking a safe space.', 23, '2015-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 6, 'Tweek x Craig', 'The Asian girls in school are drawing dreamy pictures of Tweek and Craig.', 23, '2015-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 7, 'Naughty Ninjas', 'The citizens of South Park decide they no longer need a police force in town. ', 23, '2015-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 8, 'Sponsored Content', 'Jimmy is sent to the principal’s office for using an inappropriate word in the school paper. His integrity as a newsman runs head on into PC Principals ideology. Will Jimmy be the undoing of PC Principal?', 23, '2015-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 9, 'Truth and Advertising', 'PC Principal disappears with two of the 4th grade students.', 23, '2015-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 19), 10, 'PC Principal Final Justice', 'The gentrification of South Park is pricing Randy right out of town. Meanwhile, Kyle’s distrust of Stan has broken their friendship and thrown Kyle into a dangerous alliance.', 23, '2015-12-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')), 20, 'Season 20', 'Join Cartman, Kenny, Stan and Kyle as they confront online trolling, face the member berry epidemic, and come to terms with Cartman having a girlfriend. For them, it’s all part of growing up in South Park!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 1, 'Member Berries', 'Mr. Garrison is still on the campaign trail, and the National Anthem gets a reboot by an American Icon.', 23, '2016-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 2, 'Skank Hunt', 'At South Park Elementary, there is a heavy police presence as Kyle Broflovski walks in. In the school library, Mr. Mackey tries to help the students cope with the loss of their friend on Twitter. He encourages them to tweet about all good times they had with Heidi. At the cafeteria, Stan is suggesting that they need to stop Skankhunt42 immediately.', 23, '2016-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 3, 'The Damned', 'Skankhunt42 is thrilled with the media attention and continues to troll.', 23, '2016-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 4, 'Wieners Out', 'Butters and the other boys start a retaliatory movement against the girls. Gerald fears for his secret', 23, '2016-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 5, 'Douche and a Danish', 'Garrison finally crosses the line at his most recent Presidential rally, and the kids get pulled in to the search for the notorious Skankhunt42. Meanwhile, Gerald joins forces with the other trolls to stop Denmark from launching TrollTrace.com.', 23, '2016-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 6, 'Fort Collins', 'The Presidential election is only two weeks away and Garrison is still hiding out in Colorado.  Everyone freaks out when an entire city in Colorado gets hacked. Gerald faces ruin if his complete history of internet activity becomes public. Memberberries are afraid for their lives and Cartman starts to realize the future is in jeopardy.', 23, '2016-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 20), 7, 'Oh, Jeez', 'PC Principal tries one more time to make peace between the boys and the girls. Meanwhile Gerald comes face-to-face with the Troll Hunter.', 23, '2016-11-09');
