INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 22), 3, 'The Problem with a Poo', 'Mr. Hankey must defend his character or lose everything that is important to him. Mr. Hankey’s offensive behavior puts him in jeopardy of being fired as the Director of the Annual Christmas Pageant. Meanwhile, at South Park Elementary, Strong Woman and PC Principal face a whole new set of challenges in their relationship.', 23, '2018-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 22), 4, 'Tegridy Farms', 'Butters sells vape pens and all kinds of fruity-flavored vape accessories at school; Randy decides he should move the family to the country and take up farming.', 23, '2018-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 22), 5, 'The Scoots', 'This year, a revolution in mobility is changing Halloween for everyone. Chaos erupts as every kid is out to get more candy than they have ever gotten before. Mr. Mackey and the rest of the adults are hording emergency supplies and hoping to survive until morning.', 23, '2018-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 22), 6, 'Time to Get Cereal', 'As it turns out, everyone should have taken Al Gore Cereal. The citizens of South Park have no idea the danger they''re in. When dead citizens start popping up all over town, the boys realize they need Al Gore''s help. The boys are willing to do almost anything to save the town, and themselves, but it may be just too late.', 23, '2018-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0121955')) AND numero_temporada = 22), 7, 'Nobody Got Cereal?', 'The boys break out of jail and are on the run from the police and ManBearPig. Satan steps up to help the boys and the rest of the citizens of South Park.', 23, '2018-11-14');
