INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')), 1, 'Season 1', 'In Season 1, feeling his handle on his family and his business slipping away, mob boss Tony Soprano suffers a series of anxiety attacks that land him in the office of a psychiatrist. Opening up to his shrink, Tony relates the details of his life as a “waste-management consultant,” and tries to come to terms with the professional and private strains that have brought him to the brink of a breakdown.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 1, 'The Sopranos', 'After suffering a series of mysterious anxiety attacks, New Jersey mob boss Tony Soprano agrees to see a psychiatrist, Dr. Jennifer Melfi. As he opens up to the doctor, Tony reveals details about his problems at home and at work that involve his wife Carmela, his kids Meadow and Anthony Jr., his Uncle Junior and his domineering mother Livia.', 60, '1999-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 2, '46 Long', 'With acting boss Jackie Aprile dying of cancer, Tony prepares for a power struggle with Uncle Junior. Christopher and his associate Brendan make trouble for themselves when they jack a truck full of DVD players. Tony''s mother Livia finally agrees to live in a retirement community. Big Pussy and Paulie Walnuts are sent to find a stolen car.', 50, '1999-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 3, 'Denial, Anger, Acceptance', 'Uncle Junior''s associate Mikey Palmice stirs things up by making Junior think Tony wants to be next in line for boss. Meanwhile, Tony, Paulie and Silvio deal with Hasidic family problems.', 45, '1999-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 4, 'Meadowlands', 'Jackie Aprile''s health worsens, forcing Tony to make a tough decision. Meanwhile, Anthony Jr. learns the true nature of his father''s job in ''waste management.'' Also, Tony hires sleazy police lieutenant Vin Makazian to investigate Dr. Melfi''s background.', 53, '1999-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 5, 'College', 'During a trip to Maine for Meadow''s college interviews, Tony sees a man he believes is a relocated mob snitch. Back at home, Carmela receives comfort from Father Phil.', 57, '1999-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 6, 'Pax Soprana', 'At Tony''s suggestion, Junior is made acting boss after Jackie dies. In therapy, Tony surprises Dr. Melfi with an admission. Carmela and Irina (Tony''s mistress) both suffer as Tony''s libido takes a nosedive.', 50, '1999-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 7, 'Down Neck', 'After stealing the ''sacramental wine'' from the school chapel, Anthony Jr. is suspended. Tony is concerned that his bad influence is responsible for his son''s behavior, and has a series of disturbing flashbacks in which he remembers learning that his own father was in the mob.', 52, '1999-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 8, 'The Legend of Tennessee Moltisanti', 'At the wedding of Larry Boy''s daughter, the ''boys'' find out they''re going to be indicted, and make a premature exit to get rid of incriminating evidence at home. Upset that he isn''t getting the notoriety of other family members, an agitated Christopher has an ugly encounter with a bakery clerk.', 49, '1999-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 9, 'Boca', 'Uncle Junior enjoys a romantic tryst in Boca with his girlfriend Bobbi, not realizing that she''s been gabbing to her beauty-parlor friends about his oral talents. Meanwhile, controversy arises when Meadow''s soccer coach announces he''s leaving the school.', 52, '1999-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 10, 'A Hit Is a Hit', 'Christopher and Adrianna cut a deal with a famous gangsta rapper who claims that Hesh pocketed royalties belonging to a cousin who recorded several hit songs decades ago. Meanwhile, Tony plays golf with Cusamano and his white-bread friends.', 53, '1999-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 11, 'Nobody Knows Anything', 'After Jimmy and Pussy are arrested in an FBI raid, Makazian tells a stunned Tony that Pussy may be wired for the Feds. Tony sends Paulie to find out for sure. Later, Tony learns that Makazian might be trying to frame Pussy to get out of his gambling debts.', 49, '1999-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 12, 'Isabella', 'Hit men are sent out to whack Tony, who comes out of his depression when he meets Isabella, an Italian exchange student staying next door.', 47, '1999-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 1), 13, 'I Dream of Jeannie Cusamano', 'In the Season One finale, Tony is stunned to discover that the attempt on his life may have been ordered by someone very close to him. Later, he must deal with the fact that everyone knows he is seeing a shrink. Christopher is sent to take care of Jimmy Altieri.', 60, '1999-04-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')), 2, 'Season 2', 'His uncle''s in jail. His mother''s in the hospital. His best friend''s still missing. His sister''s moving home. His panic attacks are back. And his shrink refuses to see him. Tony Soprano has recently been elevated to the status of mob boss following a federal bust and as the second season picks up, Tony is under more stress than ever as he deals with the demands of his new position. Making matters worse, his long-lost sister Janice has arrived to take care of their ailing mother.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 1, 'Guy Walks into a Psychiatrist''s Office', 'Season Two opens with the aftermath of the federal crackdown: Junior''s in jail, Melfi refuses to see Tony, Christopher''s expanding into new business ventures, Pussy is still missing...and Tony''s adjusting to life as the new boss. To complicate matters even more, Tony''s free-spirited sister Janice arrives to take care of Livia.', 49, '2000-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 2, 'Do Not Resuscitate', 'When black protesters start picketing a construction company that used to be under Uncle Junior''s control, Tony meets with the owner--as well as the leader of the protestors--to ''fix'' the problem. Meanwhile, Janice gets sucked into Livia''s web.', 50, '2000-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 3, 'Toodle-Fucking-Oo', 'Tony busts Meadow for partying at his mother''s old house. Meanwhile, Ritchie Aprile is out of the can after ten years and looking for action--much to the chagrin of a local pizza-shop owner.', 50, '2000-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 4, 'Commendatori', 'Tony travels to Italy with Paulie and Christopher to jump-start a car-importing ''business.'' While Paulie and Christopher sample some of the Old Country''s choicest wares, Tony haggles with the head of a powerful Naples family and recruits a valuable new lieutenant named Furio.', 52, '2000-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 5, 'Big Girls Don''t Cry', 'Back in Jersey, Furio soon lives up to his name by unleashing his fury on the delinquent proprietor of a local ''tanning salon.'' Dr. Melfi shares her guilt over dumping Tony as a client during a session with her own therapist. Meanwhile, Tony learns from Hesh that his father had emotional secrets of his own.', 51, '2000-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 6, 'The Happy Wanderer', 'David Scatino, the father of Meadow''s friend Eric and the owner of a local sports store, gets on the bad sides of both Richie and Tony when he loses big in two poker games. Paying his respects at a funeral, Tony is forced to deal with the presence of Livia.', 50, '2000-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 7, 'D-Girl', 'With Anthony Jr.''s confirmation approaching, Tony and Carmela find their son''s growing apathy a cause for concern. Meanwhile, Christopher''s interest in show biz is reignited when he meets a well-known filmmaker through his cousin''s girlfriend.', 56, '2000-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 8, 'Full Leather Jacket', 'Although Richie is miffed at Tony for forcing him to build a ramp for the pizza-parlor owner he paralyzed, he decides to make a peace offering. Unhappy with their lowly status as Christopher''s lackeys, Sean and Matt decide to pledge their allegiance to Richie--through a violent, unexpected act.', 42, '2000-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 9, 'From Where to Eternity', 'Christopher has an out-of-body experience that spooks Paulie to no end. Carmela urges Tony to have a vasectomy. Visiting her own psychiatrist, Melfi reveals the ''unholy alliance'' she''s made with Tony...as well as her growing dependence on pills and alcohol.', 55, '2000-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 10, 'Bust Out', 'Richie meets with Tony to complain about his end of the garbage business, then meets with Junior to complain about Tony. Later, Tony orchestrates the ''planned bankruptcy'' of David Scatino''s sporting-goods store while Scatino''s wife introduces Carmela to her handsome widowed brother.', 59, '2000-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 11, 'House Arrest', 'Having dodged a legal bullet, Tony is advised by his lawyer to spend more time at his businesses. Junior looks for diversions to relieve the tedium of house arrest, and eventually finds one in the company of a police widow. Meanwhile, Melfi''s problems boil over while eating dinner with her son.', 57, '2000-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 12, 'The Knight in White Satin Armor', 'Engaged lovebirds Richie and Janice have an explosive first quarrel. Meanwhile, Irina takes drastic measures to try to convince Tony to continue their affair.', 60, '2000-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 2), 13, 'Funhouse', 'In the Season Two finale, Tony has a series of ''fever dreams'' that help to shed light on some of his problems--particularly his troubles over Big Pussy.', 59, '2000-04-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')), 3, 'Season 3', 'In season three, the federal wiretap begins and Meadow goes to college. Tony faces challenges from some tough newcomers, such as hothead Ralph Cifaretto, New York crime boss Johnny Sack and a sexy car saleswoman.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 1, 'Mr. Ruggerio''s Neighborhood', 'While the Soprano family goes about their day-to-day activities, the FBI begins an elaborate operation to bug their home. Tony ponders his options when Patsy starts asking too many questions about his brother''s death.', 49, '2001-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 2, 'Proshai, Livushka', 'Tony''s concerns that his mother will rat him out to the feds expire when she, literally, does. Later, Janice arrives to arrange the funeral, which takes a bizarre turn.', 56, '2001-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 3, 'Fortunate Son', 'Christopher finds that being a ''made'' man isn''t all it''s cracked up to be. Meanwhile, Janice moves into her mother''s house, where she soon gets a leg up on Livia''s former housekeeper.', 58, '2001-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 4, 'Employee of the Month', 'Dr. Melfi''s attempts to steer Tony into behavior-modification therapy take a detour when a personal crisis gets in the way. Meanwhile, Ralph Cifaretto finds a way to endear himself to Jackie Jr.--but not to Tony.', 52, '2001-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 5, 'Another Toothpick', 'Bobby ''Bacala'' Baccilieri Sr. comes out of retirement to deal with a young hothead named Mustang Sally--much to the chagrin of his son and Uncle Junior.', 59, '2001-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 6, 'University', 'Ralph''s volatile relationship with a Bada Bing stripper and his obsession with the movie ''Gladiator'' combine to put a damper on several boys''-nights-out sessions at the club. Meanwhile, at Columbia, Meadow''s relationship with Noah is put to the test by her needy roommate Caitlin.', 49, '2001-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 7, 'Second Opinion', 'Tony convinces Uncle Junior to seek a second opinion for his cancer treatment. Meanwhile, Carmela debates whether or not to take Dr. Melfi''s advice and see a shrink, Big Pussy''s wife Angie regrets asking Carmela for some money to help her sick dog, and Christopher continues to endure a humiliating probation period at the hands of kinky Paulie.', 60, '2001-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 8, 'He Is Risen', 'As Thanksgiving approaches, Tony''s feud with Ralph escalates, despite the intervention of Johnny Sack. At a frat-house mixer, Meadow and Jackie Jr. find they have more in common than mob-boss dads.', 54, '2001-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 9, 'The Telltale Moozadell', 'Tony gives Carmela a sapphire ring for her birthday...and Christopher gives Adriana her very own music club. Anthony Jr. gets busted for vandalizing the school swimming pool, but finds the punishment doesn''t fit the crime. Tony test-drives a new Mercedes--and the Mercedes saleswoman, Gloria.', 56, '2001-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 10, 'To Save Us All from Satan''s Power', 'A somnolent visit with the ghosts of Christmas past lands Tony back on Melfi''s couch. With the annual pork-store holiday party approaching, Bacala reluctantly agrees to don the Santa suit that Pussy used to wear. Tony and Furio have a holiday surprise in store for the Russian who roughed up Janice.', 46, '2001-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 11, 'Pine Barrens', 'Paulie and Christopher are engulfed in a nightmarish journey into the South Jersey woods while trying to collect a debt from a Russian mobster. Meanwhile, Meadow is suspicious that Jackie Jr. is two-timing her, and Tony finds that family demands are jeopardizing his romance with Gloria.', 60, '2001-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 12, 'Amour Fou', 'Inspired by a tale from Ralph about how his father got ''made,'' Jackie Jr. decides to ''make his move'' in organized crime by instigating a robbery caper at a local card game. Reminded by Melfi of the psychological parallels between his relationships with Gloria and with his mother, Tony finds it harder and harder to spend time with his ''crazy love.''', 60, '2001-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 3), 13, 'Army of One', 'Yet another academic misstep by A.J. forces his parents to contemplate military school. Tony orders Ralph to deal personally with the Jackie Jr. situation, and later seems to take Ralph''s side in a money dispute with Paulie. Once again, the family gathers in Artie Bucco''s restaurant, where Meadow reflects on being a Soprano.', 60, '2001-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')), 4, 'Season 4', 'With Paulie in jail, Christopher becomes acting capo in season four. Junior faces a RICO trial while Tony finds that the recession affects his businesses. Meanwhile, Furio catches Carmela''s eye, and Janice sets her sights on Bobby.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 1, 'For All Debts Public and Private', 'Tony invests in a land deal despite Carmela''s concerns about money. Junior faces his own financial woes as his trial approaches. Adriana brings her new friend to the Soprano Sunday dinner, but Adriana has no idea who Danielle is working for. Tony bonds with Christopher by giving him the opportunity to avenge the murder of his father.', 58, '2002-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 2, 'No-Show', 'With Paulie in jail, Christopher becomes acting capo, but he gets off to a bad start with Patsy. Still troubled by Jackie Jr.''s death, Meadow contemplates taking a year off from college to travel. Meanwhile, Adriana is in a bind after ending her friendship with Daniele, and Silvio discusses a misunderstanding at a Newark riverfront construction site.', 57, '2002-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 3, 'Christopher', 'Silvio and Ralph must take care of a planned protest of the Columbus Day parade by a Native American group. At an Italian pride ladies'' lunch, Carmela is embarrassed by anti-Mafia remarks. Meanwhile, Ralph deals with new relationship troubles, and Bobby receives some tough news.', 54, '2002-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 4, 'The Weight', 'A disparaging remark about his wife sets Johnny Sack off on a vendetta. Meadow decides to do volunteer work at the South Bronx Law Center; Furio hosts a housewarming party for the gang; Silvio and Chris make an offer to an old-time hit man named Lou DiMaggio; and Tony and Carmela find themselves at odds over the family''s bill-consolidation strategy.', 58, '2002-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 5, 'Pie-O-My', 'Checking out Ralph''s promising new filly at the track, Tony displays a flair for horse-racing strategy--and discovers an unexpected affinity for the stable life. Adriana finds her rock club being used as a place of business for Chris and his pals. Meanwhile, a court artist incurs the wrath of Uncle Junior, and Janice feeds Bobby in his hour of need.', 54, '2002-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 6, 'Everybody Hurts', 'After hiring an attractive French hostess, Elodi, Artie agrees to loan her brother some money, with interest. Meanwhile, Christopher gets some new responsibilities; Carmela fixes Furio up with an oral hygienist; Anthony Jr. becomes the ''dough boy'' of a new rich girlfriend; and Tony receives some unsettling news about an old acquaintance.', 55, '2002-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 7, 'Watching Too Much Television', 'Tony and the gang throw Paulie a Bada Bing bash after his release from jail, but it doesn''t take long for old tensions to resurface. Carmela''s cousin Brian throws out a hypothetical investment scenario that Tony and Ralph attempt to turn into reality with the help of Assemblyman Zellman and a black community leader.', 54, '2002-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 8, 'Mergers and Acquisitions', 'Paulie takes pains to integrate his mother Nucci into the social world at Green Grove. Meanwhile, Furio faces up to his inner feelings during a trip to Italy to see his ailing father; Ralph introduces Tony to his new ''goomar,'' Valentina; and Carmela finds a new source of investment income.', 56, '2002-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 9, 'Whoever Did This', 'After an aggressive team of reporters lowers the boom on Uncle Junior, his lawyers try a new strategy. Ralph has some fun at the expense of Paulie and his mother, but soon winds up with his own family problems. Meanwhile, Tony again finds refuge at the stables.', 56, '2002-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 10, 'The Strong, Silent Type', 'At therapy, Tony likens himself to the ''sad clown,'' but Melfi doesn''t buy into his melancholy portrait. Meanwhile, Carmela drags A.J. with her to Furio''s house to offer decorating tips and companionship; Paulie puts the finishing touches on some free artwork; and Christopher finds himself at a crossroads.', 53, '2002-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 11, 'Calling All Cars', 'After a sitdown with Carmine and Johnny Sack, Tony contemplates the future of the HUD partnership. Meanwhile, Paulie blows off steam with an old pal; Janice starts losing patience with the obsessive Bobby; and Melfi ponders the Freudian undercurrents of Tony''s latest dreams.', 47, '2002-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 12, 'Eloise', 'Tony continues to haggle with Johnny Sack and the two Carmines over the Esplanade profits. Carmela makes a decorating date she can''t keep; Furio proves a reluctant companion to Tony on a casino junket; Paulie plays an impatient chaperone to some ladies from the nursing home; and Meadow debates the true meaning of a literary classic with her mom.', 56, '2002-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 4), 13, 'Whitecaps', 'In the Season Four finale, Tony and Carmela contemplate purchasing a shore house, but a voice from the past threatens the deal. While Uncle Junior breaks out the Hearty Burgundy, Little Paulie and Benny break in a new sound system on the Stugots. With Carmine apparently intent on putting the past behind him, Tony and Johnny Sack weigh their options, carefully.', 75, '2002-12-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')), 5, 'Season 5', 'In season five, a separated Tony and Carmela negotiate family and money issues. Meanwhile, Tony''s reunion with paroled cousin Tony Blundetto may endanger his alliance with Johnny Sack; and Adriana gets in deeper with the Feds.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 1, 'Two Tonys', 'A flood of organized crime parolees changes the landscape of the Soprano/Lupertazzi alliance. Janice carries on the family''s Sunday dinner tradition. Carmela and A.J. commune with local wildlife. Christopher balks at footing the bill on ''goomar night.'' Tony tries to introduce Dr. Melfi to his ''other'' self.', 53, '2004-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 2, 'Rat Pack', 'Tony sizes up a contractor''s gift, then reunites with his paroled cousin, Tony Blundetto. Paulie and Christopher relive some not-so-special memories. Carmela launches a film club. Adriana grapples with her guilt. A familiar figure ''crosses over.''', 56, '2004-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 3, 'Where''s Johnny?', 'Tony''s power-sharing plan doesn''t fly with Johnny Sack, who makes his point through a bookie named Lorraine Calluzzo. Out on parole, Feech La Manna crosses Paulie in his attempt to break into the landscaping business. Tony gets a roommate. Junior looks into the past while testing the patience of those closest to him.', 54, '2004-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 4, 'All Happy Families', 'Carmela and Tony reunite, if only to discuss Anthony Jr.''s dwindling college prospects. Feech takes Tony''s crew on a trip down memory lane. Lorraine''s allegiances get her into hot water. A.J. has a night to remember in the Big Apple.', 52, '2004-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 5, 'Irregular Around the Margins', 'While Christopher is away, Tony gives Adriana a ride home that proves disastrous. Meanwhile, the Soprano crew plays a game of ''telephone'' with the story that turns it into something far more sinister when an enraged Christopher gets wind of it.', 51, '2004-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 6, 'Sentimental Education', 'With her son''s future at stake, Carmela puts in some extra time with his college advisor, Robert Wegler. Meanwhile, Tony Blundetto realizes it''s hard doing business with strangers, and A.J. concludes there''s no place like home.', 55, '2004-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 7, 'In Camelot', 'His father''s longtime goomar sheds light on some of Tony''s lingering emotional and financial mysteries. Meanwhile, Junior sees the upside of attending the funerals of fringe relations, while Christopher sees the downside of enabling an A.A. friend''s new addiction.', 54, '2004-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 8, 'Marco Polo', 'Friends and family gather at the Sopranos'' for a not-so-surprise 75th birthday party for Carmela''s father, Hugh. Meanwhile, Johnny Sack shows off his new wheels, Phil Leotardo pulls into Pussy''s old place for some auto repairs, and Tony B. considers accepting a familiar job on the side.', 53, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 9, 'Unidentified Black Males', 'A rumor involving his cousin puts Tony''s relationship with Johnny Sack back on thin ice. Meadow helps get her boyfriend Finn a job. A.J. ponders a ''maximum-security summer'' at Casa Carmela. Melfi links Tony''s current guilt to a past job. Carmela learns that good legal help is hard to find.', 58, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 10, 'Cold Cuts', 'Tony B. and Christopher unearth some old memories during an otherwise idyllic trip to the country. Tony and Carmela plan another party. Janice lands in anger-management therapy after a sports-rage incident. Benny and Terry solve a missing-Vespa mystery. Tony puts his sister''s newfound serenity to the test.', 52, '2004-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 11, 'The Test Dream', 'Tony escapes to the Plaza Hotel for a night of rest and relaxation, but his dreams are haunted by past faces. Another casualty falls in the war between Johnny Sack and Little Carmine, and Tony B. heads to New York for revenge.', 49, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 12, 'Long Term Parking', 'With the feds pulling a new trump card, Adriana ponders her options. Tony B. unloads some heavy baggage on Tony, and vice-versa. Johnny Sack makes Tony an offer he can refuse, and Tony offers Carmela a deal to make her real-estate dreams come true.', 56, '2004-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 5), 13, 'All Due Respect', 'In the Season Five finale, Tony''s crew circles the wagons as Johnny Sack turns up the heat. Carmela counts her blessings. Christopher is freaked out by an unexpected visitor. Benny''s connection to the plumber''s union comes in handy. A.J. demonstrates his business acumen. Tony ponders whether to execute a ''sacrifice bunt.''', 55, '2004-06-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')), 6, 'Season 6', 'As the final episodes take shape, Tony faces a myriad of stress-inducing crises at home, at work, and from the law. While his wife and children each make choices that promise to change the face of the Sopranos'' domestic life, Tony also comes to doubt the allegiances of some of those closest to him at work . . . none of whom is above suspicion.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 1, 'Members Only', 'Gene Pontecorvo makes a final break from the mob life, while Junior''s paranoid delusions could be the end of Tony.', 52, '2006-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 2, 'Join the Club', 'The family tries to cope with Tony''s hospitalization and possibly impending death, while Tony begins to hallucinate a new life parallel to his own.', 53, '2006-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 3, 'Mayham', 'While the gang begins to turn on itself, Tony finds himself at the threshold.', 56, '2006-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 4, 'The Fleshy Part of the Thigh', 'Tony goes home and returns to business, perhaps with a new frame of mind. Paulie receives a shock about his mother.', 57, '2006-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 5, 'Mr. & Mrs. John Sacrimoni Request...', 'Johnny Sack asks for permission to get out of jail for his daughters wedding; Tony''s on the look out for personal protection.', 52, '2006-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 6, 'Live Free or Die', 'Tony seeks guidance from overseas to solve a local problem; and decides whether a top earner deserves another chance.', 54, '2006-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 7, 'Luxury Lounge', 'Chris meets and beats the stars, while Artie turns violent after having his hospitality abused.', 54, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 8, 'Johnny Cakes', 'Vito considers starting a new life in New Hampshire, while Anthony continues his pursuit of revenge against Junior.', 54, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 9, 'The Ride', 'Paulie finds public opinion turned against him after an amusement ride accident, while Chris tries to start a new life as a husband and father.', 54, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 10, 'Moe n'' Joe', 'Tony reflects on how growing up with Janice colors his attitudes now, while Vito tries to make a new life for himself in New Hampshire.', 53, '2006-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 11, 'Cold Stones', 'Phil takes out his revenge on Vito, while Tony grows frustrated with Anthony''s lack of ambition or work ethic.', 56, '2006-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 12, 'Kaisha', 'Phil Leotardo seeks to continue a cycle of retaliation between the New York and Jersey families. Christopher wrestles with his addictions. Tony decides keeping Carmela occupied with the spec house is for the best. A.J. gets a new girlfriend.', 59, '2006-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 13, 'Soprano Home Movies', 'Bobby and Janice host a wild 47th birthday bash for Tony at their Adirondacks vacation home. Tony''s actions following Johnny Sack''s arrest come back to haunt him.', 51, '2007-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 14, 'Stage 5', 'Christopher''s Cleaver premieres, showing Tony how he feels about him. Johnny Sack faces a health crisis. Phil Leotardo resents his family, and himself, for being weak and downtrodden. Silvio gets caught up in New York''s power vacuum.', 56, '2007-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 15, 'Remember When', 'When Tony''s first hit is about to be unearthed, he and Paulie flee to Florida, where Tony contemplates their friendship. Junior organizes a poker game at the institution. The New York power struggle continues.', 58, '2007-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 16, 'Chasing It', 'Maria Spatafore requests help from Tony for Vito, Jr. Tony''s bad luck puts a rift between he and Hesh. A.J. makes a major choice regarding his future.', 49, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 17, 'Walk Like a Man', 'The relationship between Christopher and Paulie''s falters, while A.J. grows depressed over his break-up with Blanca.', 55, '2007-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 18, 'Kennedy and Heidi', 'The Soprano and Lupertazzi crime families quarrel over asbestos removal. Tony deals with a problematic associate. Paulie suffers a devastating personal loss. A.J. questions his friendship with Jasons Parisi and Gervasi.', 53, '2007-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 19, 'The Second Coming', 'Tony attempts to repair the rift between New Jersey and New York. A.J.''s depression struggle continues. A New York associate crosses the line with Meadow.', 53, '2007-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 20, 'The Blue Comet', 'The spectre of disloyalty among the crew hangs over Tony as Phil Leotardo decides how to handle recent issues with the Soprano crime family. A hit gone wrong comes at a huge cost. A.J.''s conquering of his depression is challenged.', 50, '2007-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0141842')) AND numero_temporada = 6), 21, 'Made in America', 'Tony seeks to find a peace with the Leotardo crew while dealing with rumors a member of his own crew may have flipped. A.J. makes a decision regarding his future and Junior''s slide into dementia continues.', 60, '2007-06-10');
