INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 1, 'Space Pilot 3000', 'On New Year''s Eve 1999, Pizza Delivery boy Philip J. Fry accidentally falls into a cryogenic chamber and is frozen for 1,000 years. Finally unfrozen, he explores New New York, meets his new best friend (a kleptomaniacal robot named Bender) and goes to work for his great-great-great-great-grand-nephew''s space delivery business.', 22, '1999-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 2, 'The Series Has Landed', 'For the crew''s first mission, they must deliver a crate full of toys for an arcade game to the moon. Fry is very excited, while it is not really a big deal in the year 3000. Fry tries to persuade Leela to go exploring on the moon, while Amy tries to recover the keys to the Planet Express Ship.', 22, '1999-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 3, 'I, Roommate', 'When it is discovered that Philip has been living in the Planet Express office, he is forced to move out. Trying to sleep standing up in Bender''s closet-sized apartment doesn''t work, so they go looking for a place both can be comfortable. Unfortunately, Bender is incompatible with the ideal apartment they do find until he has a radical... modification which makes him less than happy.', 22, '1999-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 4, 'Love''s Labours Lost in Space', 'On a mission intended to save endangered animals on a collapsing planet, Leela and the crew run into legendary starship captain Zapp Brannigan. A self-proclaimed ladies man, Zapp sees Leela as a potential new conquest. When the captain refuses to aid the animal rescue, Leela and her crew try to leave Zapp''s starship. But Zapp throws Fry and Bender in jail, and summons Leela to his "Lovenasium". They ultimately escape and arrive on the doomed planet, where Leela finally finds love - with a cute, and very useful, creature named Nibbler.', 22, '1999-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 5, 'Fear of a Bot Planet', 'Fry and Leela disguise themselves as robots to find Bender after he fails to return from a delivery to a robot planet, only to learn that he has become a celebrity in a culture which fears humans.', 22, '1999-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 6, 'A Fishful of Dollars', 'Fry discovers his bank account interest has made him a billionaire and buys the one thing the year 3000 doesn''t have, anchovies.', 22, '1999-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 7, 'My Three Suns', 'Delivery Boy Philip J. Fry is promoted to Emperor after accidentally drinking his fluid-based predecessor.', 22, '1999-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 8, 'A Big Piece of Garbage', 'A big piece of garbage that was released a thousand years ago is now on the way to Earth to destroy it. After Fry, Leela and Bender fail on placing a bomb on it, the city has to build another big piece of garbage, yet that may be a problem since trash doesn''t exist in year 3000.', 22, '1999-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 1), 9, 'Hell Is Other Robots', 'During a Beastie Boys concert, Bender runs into a high school buddy, Fender. He invites him to a party, which turns out to be robots getting high off of electricity, or "jacking on". After one try, Bender is hooked.', 22, '1999-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 1, 'A Flight to Remember', 'The Planet Express crew take a space cruise vacation. Leela tells Captain Zapp Brannigan that Fry is her boyfriend and Amy tells the same thing to her parents. Bender falls in love with a rich female robot. Problems start when the spaceship approaches a black hole.', 22, '1999-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 2, 'Mars University', 'Fry, Leela, Bender and Farnsworth have to go to Mars University where Fry has to share a room with a talking monkey, Farnsworth''s last invention. The monkey becomes a real headache when he starts beating Fry in all areas. Meanwhile, Bender is hanging out with nerd robots.', 22, '1999-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 3, 'When Aliens Attack', 'The Omicronians invade Earth, demanding to see the lost final episode of the 1999 TV show Single Female Lawyer. The Planet Express crew must re-enact the episode to appease the invading aliens.', 22, '1999-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 4, 'Fry & the Slurm Factory', 'When Fry wins a free tour of the Slurm soda factory, he and his friends split off from the tour group and make a horrifying discovery concerning the "secret ingredient" that makes Slurm so addictive.', 22, '1999-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 5, 'I Second That Emotion', 'Professor Farnsworth installs an empathy chip in Bender after the inconsiderate robot flushes Nibbler down the toilet. With his newfound emotions, a concerned Bender ventures into the mutant-infested sewers to rescue Leela''s beloved pet.', 22, '1999-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 6, 'Brannigan, Begin Again', 'Upon destroying the new DOOP headquarters, Zapp Brannigan and Kif find themselves court-martialed and dishonorably discharged. They take up jobs at Planet Express, where Kif learns what respect feels like and Zapp incites a mutiny against Leela.', 22, '1999-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 7, 'A Head in the Polls', 'When the price of titanium skyrockets, Bender pawns his titanium-rich body and lives the high life as just a head. But when the head-in-a-jar of Richard M. Nixon uses Bender''s body to run for election for President of Earth, Bender vows to get his rightful property back.', 22, '1999-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 8, 'Xmas Story', 'To apologize for an inconsiderate remark, Fry searches for the perfect Xmas gift for Leela, all the while trying to avoid the murderous SantaBot, whose standards for niceness are astronomically high.', 22, '1999-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 9, 'Why Must I Be a Crustacean in Love?', 'When Dr. Zoidberg runs amok during the Decapodian mating season, Fry sets out to teach him how to woo a mate. Things backfire when Zoidberg''s desired mate falls for Fry instead, and Zoidberg challenges Fry to a battle to the death.', 22, '2000-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 10, 'Put Your Head on My Shoulders', 'Fry''s brief relationship with Amy is forcibly prolonged when a near-fatal car crash leaves Fry''s head grafted to Amy''s left shoulder. Meanwhile, Bender cashes in on Valentine''s Day by starting a dating service.', 22, '2000-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 11, 'Lesser of Two Evils', 'Fry suspects Bender''s new buddy, a bending unit named Flexo who looks almost exactly like Bender, of being pure evil. When a valuable atom of Jumbonium goes missing, Fry suspects Flexo, but can''t tell which robot is which.', 22, '2000-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 12, 'Raging Bender', 'Bender is the featured attraction in the Ultimate Robot Fighting League, but his glory is short-lived when he is instructed to intentionally lose his next match. Leela vows to lead Bender to victory, in an effort to show up her unsupportive martial arts teacher.', 22, '2000-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 13, 'A Bicyclops Built For Two', 'Leela meets Alkazar, who claims to be the only other remaining cyclops in the universe. But when Alkazar invites Leela back to his home planet and treats her like a slave, Fry suspects that something is amiss.', 22, '2000-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 14, 'How Hermes Requisitioned His Groove Back', 'When Hermes takes a stress-relieving vacation, replacement bureaucrat Morgan Proctor becomes infatuated with Fry. Bender threatens to publicize their affair, but Morgan removes Bender''s memory and hides it within the cavernous Central Bureaucracy.', 22, '2000-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 15, 'A Clone of My Own', 'Professor Farnsworth unveils his clone, Cubert Farnsworth, whom he plans to leave everything to upon his retirement. But Cubert wants no part of Farnsworth''s lifestyle, prompting the professor into a premature retirement on the Near-Death Star.', 22, '2000-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 16, 'The Deep South', 'A fishing trip over the ocean takes a turn for the worse when a colossal mouth bass pulls the Planet Express ship to the bottom of the sea. There, Fry falls in love with a mermaid named Umbriel, and the crew discovers the sunken city of Atlanta, Georgia.', 22, '2000-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 17, 'Bender Gets Made', 'Bender takes a new job in the Robot Mafia, but his loyalty is tested when he goes along on the robotic gangster''s efforts to rob the Planet Express ship.', 22, '2000-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 18, 'The Problem with Popplers', 'The crew discovers an irresistible source of food on a distant planet, and brings it back to Earth to be sold at the Fishy Joe''s restaurant chain. But when it''s discovered that the so-called "Popplers" are actually Omicronian babies, the Omicronians demand recompense.', 22, '2000-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 19, 'Mother''s Day', 'Mom reprograms the world''s robots to rebel against humanity. The only hope of salvation is Mom''s old flame - Professor Farnsworth, who must rekindle his romance with Mom in order to save mankind.', 22, '2000-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 2), 20, 'Anthology of Interest I', 'The Professor''s "What-If" machine simulates Bender, Leela and Fry''s wishes. Bender discovers what it would be like if he were 500 feet tall, Leela discovers what it would be like if she were more impulsive, and Fry discovers what would happen if he never came to the future.', 22, '2000-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 1, 'The Honking', 'When the inheritance Bender claims in the Old Country isn''t quite what he expected, the Planet Express crew has to find the source of an age-old curse.', 22, '2000-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 2, 'War Is the H-Word', 'Fry and Bender enlist in the army to get a soldiers discount for bubblegum. When they are called to fight a war on a planet of bouncing ball aliens, Leela disguises herself as man to enlist with them. Bender is eventually sent to parley with the enemy, but this turns out to be a ploy.', 22, '2000-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 3, 'The Cryonic Woman', 'Fry is reunited with his old girlfriend from the 20th Century, but she doesn''t adapt to the 31st century as well as he has. Convincing Fry to return to the cryogenic chamber, they awaken in a barren wasteland and struggle to make a place for themselves.', 22, '2000-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 4, 'Parasites Lost', 'When Fry becomes infested with parasitic worms that make him stronger and smarter, he finally finds the perfect way to profess his feelings to Leela. Meanwhile, the rest of the crew goes on a journey into Fry''s body to eradicate the worms.', 22, '2001-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 5, 'Amazon Women in the Mood', 'A double-date for Kif, Amy, Zapp, and Leela ends in disaster when their orbiting restaurant crashes on planet Amazonia. The hulking female inhabitants of the planet take their male captives to the omniscient Femputer, who orders Fry, Zapp, and Kif to death by "snu-snu".', 22, '2001-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 6, 'Bendless Love', 'Bender''s urge to bend prompts Professor Farnsworth to send him on a rehabilitation visit to a steel factory, where he falls in love with a shapely fem-bot named Angleyne. But Bender''s old rival Flexo and the intrusion of the Robot Mafia threaten to throw a wrench into the proceedings.', 22, '2001-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 7, 'The Day the Earth Stood Stupid', 'Earth is invaded by super-intelligent flying brains, who sap the Earth''s populace of their intelligence. Leela is taken to Nibbler''s home planet Eternia, where the Nibblonians explain that only one human is immune to the brains'' powers - Fry.', 22, '2001-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 8, 'That''s Lobstertainment!', 'Dr. Zoidberg reunites with his uncle, silent hologram star Harold Zoid, and the two of them set out to make a movie together. They cast the temperamental Calculon in the lead role, who demands an Oscar for his performance, but the movie doesn''t go over well with audiences.', 22, '2001-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 9, 'The Birdbot of Ice-Catraz', 'A sober Bender crashes a dark matter tanker on Pluto, threatening the penguin reserve nearby. Leela helps out in the clean-up, but when the penguins begin mating out of control, drastic action must be taken to thin the herd.', 22, '2001-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 10, 'The Luck of the Fryrish', 'After a string of bad luck, Fry ventures into the decaying ruins of Old New York to regain his lucky seven-leaf clover from his childhood, only to find that his brother Yancy Fry had stolen not only the clover, but Fry''s identity as well. Fry sets out to exhume his brother''s body, but discovers the startling truth about Yancy instead.', 22, '2001-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 11, 'The Cyber House Rules', 'Leela meets up with her former orphanarium playmate Adlai Atkins, now a plastic surgeon, who offers to grant Leela surgery that will give her two eyes. Meanwhile, Bender adopts twelve orphans in order to collect $1200 in government stipends.', 22, '2001-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 12, 'Insane in the Mainframe', 'Accused of robbing a bank, Fry and Bender plead insanity and are both sent to a robot insane asylum. While Bender and his buddy Roberto plan an escape, Fry is brainwashed into thinking that he is a robot.', 22, '2001-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 13, 'Bendin'' in the Wind', 'When Bender is paralyzed in a tragic can opener accident, he discovers his musical washboard skills and goes on tour as a member of Beck''s folk-rock band, acting as a voice for broken robots everywhere. Fry, Leela, Amy, and Zoidberg tag along in Fry''s antique 1960s VW Van.', 22, '2001-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 14, 'Time Keeps On Slippin''', 'While creating a team of mutants to play the Harlem Globetrotters, the Professor accidentally causes a disruption in time that threatens the existence of the universe. Meanwhile, Fry tries to win an unreceptive Leela''s heart.', 22, '2001-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 3), 15, 'I Dated a Robot', 'Fry discovers the ability to download any celebrity onto a blank robot, and chooses to download Lucy Liu, with whom he falls madly in love. Repulsed by this disgusting display of human/robot love, Leela, Bender, and Zoidberg set out to shut down Nappster.com and put an end to illegal celebrity downloads forever.', 22, '2001-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 1, 'Roswell That Ends Well', 'A spacetime accident leaves the Planet Express crew stranded in Roswell, New Mexico in the year 1947, where a shattered Bender is mistaken for UFO debris and Zoidberg is captured as an alien specimen. Leela and the professor work to get everybody home, while Fry tries to keep his accident-prone grandfather alive.', 22, '2001-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 2, 'A Tale of Two Santas', 'A Planet Express mission to Robot Santa''s colony on Neptune leaves the murderous robot trapped in the frozen sea, and Bender takes over as Santa, vowing to bring peace and goodwill to Xmas again. But when Bender is mistaken for the real Robot Santa, he is arrested and sentenced to death.', 22, '2001-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 3, 'Anthology of Interest II', 'When the Professor fine tunes his "What-If" machine, Bender discovers what it would be like if he were human, Fry discovers what it would be like if life were more like a video game, and Leela discovers what it would be like if she found her true home.', 22, '2002-01-06');
