INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 6, 'Where the Buggalo Roam', 'When Amy''s parents'' ranch is hit by a dust storm that blows away their herd of buggalo, Kif sets out to prove his masculinity by rounding up the herd, only to become entangled with the native Martians.', 22, '2002-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 7, 'A Pharaoh to Remember', 'Bender fears that nobody will remember him after he dies, and sees his chance for immortality when the crew is enslaved on the planet Osiris 4. Posing as the planet''s new pharaoh, Bender orders a humongous statue built in his honor, and quickly goes mad with power.', 22, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 8, 'Godfellas', 'Bender is accidentally shot out of the ship''s torpedo tube and becomes lost in space. Floating through the ethereal darkness, Bender becomes inhabited with tiny alien life forms, but has trouble playing God to their unyielding prayers.', 22, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 9, 'Future Stock', 'With Planet Express in financial trouble, Fry nominates a flashy businessman from the 1980s to replace Professor Farnsworth as CEO of the company.', 22, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 10, 'A Leela of Her Own', 'Leela endeavors to become the first female blernsball player, but her lack of depth perception hinders her skills. Nevertheless, she becomes the pitcher for the New New York Mets, purely for her novelty value.', 22, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0149460')) AND numero_temporada = 4), 11, '30% Iron Chef', 'Bender, insulted by the reception his terrible cooking receives, runs away and joins a space hobo camp, where he apprentices with a legendary former TV chef. Meanwhile, Dr. Zoidberg accidentally destroys Professor Farnsworth''s prized ship-in-a-bottle and frames Fry.', 22, '2002-04-14');
