INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0157246', 'Will & Grace', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0123273'), 'SERIE', 'Gay lawyer Will and straight interior designer Grace share a New York City apartment. Their best friends are gleeful and proud gay Jack and charismatic, filthy-rich, amoral socialite Karen.', '1998-01-01', 'https://m.media-amazon.com/images/M/MV5BNDMwOTExZGUtNjFiMS00MzljLWJhMzYtYWFhMDUzOWUyYjMwXkEyXkFqcGc@._V1_.jpg');
