INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 1, 'Season 1', 'Meet Will & Grace. Grace is a sassy and smart interior designer, Will is a gorgeous and super-cool lawyer. They’re both looking for love and they’re made for each other in every way but one - Grace is straight, Will is gay. The first season of Will & Grace premiered on September 21, 1998, and concluded on May 13, 1999. It consisted of 22 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 1, 'The Pilot (Love & Marriage)', 'When Grace receives an unexpected marriage proposal from her boyfriend, Will tries to be supportive of her decision but finally tells her that she''s making a mistake, even though he''s putting their friendship at risk. The situation is complicated by interference from Grace''s socialite assistant, Karen, and Will''s outrageous friend, Jack.', 22, '1998-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 2, 'A New Lease On Life', 'Will must decide whether to support Grace''s independence by encouraging her to take an apartment across town or selfishly keep her close by inviting her to share his living space. The decision may be made easier, however, by the nagging presence of Will''s current roommate, Jack, and his parrot, Guapo. Meanwhile, Karen and Jack meet for the first time and find each other to be fabulous.', 22, '1998-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 3, 'Head Case', 'When Grace moves in with Will, she complains that the guest bathroom is too small and suggests knocking the common wall down to create one big master bathroom, which results in Will having to confront his own issues on change and his ability to have a successful relationship. Meanwhile, Jack and Karen bear the brunt of Will and Grace''s displaced anger.', 22, '1998-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 4, 'Between a Rock and Harlin''s Place', 'When Grace decorates Harlin''s apartment, she gets carried away with a cowboy theme. Will is both shocked and embarrassed by the cowboy chic and makes an even greater mess of the situation. Meanwhile, Jack decides to embark on a “singing career“ with a little help from Karen.', 22, '1998-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 5, 'Boo! Humbug', 'Will and Grace plan to spend a serious Halloween together watching Ingmar Bergman movies at home--until Harlin drops off his over-eager kids at their place when he''s called away on business. Meanwhile, Jack convinces Karen to accompany him to the downtown parade where she becomes an honorary drag queen.', 22, '1998-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 6, 'William, Tell', 'When Jack reveals to Grace that Will once had an affair with a "client," she becomes paranoid that Will is keeping secrets from her. Her suspicions continue to grow when Will meets Karen for a discreet meeting to discuss her legal problems and will only tell Grace he''s meeting with a client.', 22, '1998-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 7, 'Where There''s A Will, There''s No Way', 'Grace blames her relationship with Will as the reason for her lack of interest in dating and decides they can no longer have fun together. Meanwhile, Jack enlists Will''s help when the IRS catches up with him.', 22, '1998-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 8, 'The Buying Game', 'Grace has the opportunity to buy the studio that serves as her office space and turns to Will for first-time buyer advice. However, Will''s negotiating tactics lead Grace to believe that Will thinks she is incapable of closing the deal and she sets out to prove him wrong. Meanwhile, Jack wants to become a massage therapist and practices his technique on a delighted Karen.', 22, '1998-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 9, 'The Truth About Will and Dogs', 'After Grace defies Will''s wishes and brings home a puppy, Will can''t resist the pooch and begins to treat him like a newborn baby. Meanwhile, Jack and Karen worry about the dog''s effect on Will and Grace and insist that the new parents go out for a night on the town.', 22, '1998-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 10, 'The Big Vent', 'Will and Grace become hooked on a real-life soap opera unfolding in their neighbors'' apartment when they begin eavesdropping through the new heating vent in their floor. As Will and Grace live vicariously through the marital infidelities of the downstairs couple, Jack feels neglected and enlists Karen''s help in staging a play that drives the message home to his two best friends.', 22, '1999-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 11, 'Will On Ice', 'It''s Will''s birthday and all he wants is a nice, quiet dinner with his two best friends, Grace and Jack. When Jack and Grace discover they share a passion for figure skating, they surprise Will with tickets for Champions on Ice and Karen reluctantly joins the special evening.', 22, '1999-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 12, 'My Fair Maid-y', 'Will hires a cleaning lady to "rescue" his designing roommate Grace from the creative chaos that litters their apartment, and while preparing for an annual decorators'' contest, Grace develops a dependency on her maid and can''t create without her. Meanwhile, Jack poses as an attorney in Will''s office to impress an attractive guy he hopes to date.', 22, '1999-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 13, 'The Unsinkable Mommy Adler', 'Grace''s visiting mom, Bobbi Adler, a would-be star whose propensity for breaking out into show tunes and impressions dismays her daughter â€“ and delights Will, Jack and Karen â€“ wreaks havoc by suggesting Will and Grace wed, despite their sexual differences. When Will winces at the fantasy of committing to anyone who needs to be the star of a relationship, Grace realizes she''s more of a chip off the old block than she imagined.', 22, '1999-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 14, 'Big Brother is Coming: Part I', 'A "surprise" birthday party for Jack astounds Will when his estranged older brother Sam turns up at the fete at Grace''s invitation. Not only do sparks fly between the brothers, but electricity of a different sort crackles between Grace and Sam. Meanwhile, Karen flashes her platinum card for Jack as the pair shop until they drop at a boutique where the snooty salesmen previously had snubbed Jack.', 22, '1999-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 15, 'Big Brother is Coming: Part II', 'A wary Grace tells Will of her romance with his brother, Sam, and unleashes an avalanche of resentment. While Will wrestles with sibling rivalry, Karen helps Jack come to grips with turning 30 by hiring him as her personal assistant and leads Grace to sort through her true feelings for the Trumans.', 22, '1999-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 16, 'Yours, Mine Or Ours', 'Stunned to find they have a ''date'' with the same guy, Will and Grace compete for the affections of a handsome, charming new neighbor at dinner, and even Jack''s finely-tuned gaydar can''t pick up his preference. Meanwhile, Karen contemplates firing her driver and in a twist of irony asks Grace to role-play firing an incompetent employee.', 22, '1999-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 17, 'Secrets and Lays', 'The gang retreats to a cabin in Vermont for the weekend, where Grace rekindles romance with an old flame and tries to hide the fling from Will, who''s pining on the eve of his would-be anniversary. Meanwhile, Karen''s culinary efforts go up in smoke, as does Jack''s attempt to cheer Will by dragging him to a gay pub, where the town barber-turned-hair stylist sidles up to him.', 22, '1999-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 18, 'Grace, Replaced', 'Will finds a "substitute Grace" in Val, a new neighbor who is available for plans with Will while Grace is consumed with work. As Will and Val continue to spend more time together, Grace fears that she has been replaced and fights with Val to regain Will''s attention. Meanwhile, Jack seeks support from Karen after the court finds him guilty of slapping a meter maid and sentences him to pick up trash.', 22, '1999-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 19, 'Will Works Out', 'Will invites Jack to his gym on a "buddy pass," but when he expresses his embarrassment to Grace over his buddy''s gay behavior, Jack overhears the comments and looks to set him straight about prejudice. Meanwhile, Grace continues to lend her ear when Karen''s marriage hits rocky ground and she and Karen share an evening of girl talk.', 22, '1999-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 20, 'Saving Grace', 'A successful and arrogant New York publicist hires Grace to decorate his house with the condition that she fixes him up with Will. But there''s a problem: Will can''t stand the guy. Meanwhile, Jack uses Karen to teach Will how to kiss someone he finds unattractive.', 22, '1999-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 21, 'Alley Cats', 'When Rob and Ellen admit that they don''t have fun playing games with Will and Grace because of Grace''s competitive nature, Grace works to change her image. However, as Grace loses her competitive edge, Will''s emerges and he convinces his partner to care only about winning. Meanwhile, after learning how to administer CPR from Jack, Karen saves a workman''s life.', 22, '1999-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 1), 22, 'Object Of My Rejection', 'Will is stunned to discover that Grace is dating her ex-fiance Danny once again, but he chooses not to interfere after he''s accused of being meddlesome. Meanwhile, Jack agrees to take a walk down the aisle with Karen''s combative maid, Rosario, who needs a groom to help her smooth out some immigration problems.', 22, '1999-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 2, 'Season 2', 'Grace has moved out and Jack has gotten married. But, since Grace is just across the hallway and Jack is married to Rosario, expect more hysterical situations, sharper comedy, and more of the bitchiest one-liners.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 1, 'Guess Who''s Not Coming To Dinner', 'Despite her moving out (to across the hall), Will still feels that Grace clings to him, so she asserts her independence by having a dinner party without him.  Meanwhile, to keep the INS at bay, Jack is forced to move in with Rosario.', 22, '1999-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 2, 'Election', 'When Grace feels that Will is abusing his power as president of the tenant''s association, she runs against him. Karen tries to buy back Jack''s forgiveness when she lets his beloved bird, Guapo, fly out the window.', 22, '1999-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 3, 'Das Boob', 'A deceiving, but flattering, newspaper photo makes Grace look more "endowed" than she really is and gains her the attention of a former high school heartthrob who was never one to keep abreast of her before. Jack is destroyed to learn that Will had a fling with Walter, Jack''s ex-boyfriend.', 22, '1999-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 4, 'Whose Mom Is It Anyway?', 'Grace is jealous when her mother stops match making for her, and instead sets Will up. Jack must convince an INS agent (who he dated once) that he and Rosario are happily married.', 22, '1999-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 5, 'Polk Defeats Truman', 'When his work for Harlin takes up all his time, Will drops all his other legal clients; a decision that later comes up to bite. Meanwhile Grace tries to teach Karen how to live on a budget.', 22, '1999-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 6, 'To Serve and Disinfect', 'An unemployed Will agrees to serve as one of Jack''s cater-waiters, until he learns that he''ll be catering for American Bar Association.  Grace discovers Karen''s darkest secret: she once made a porn video.', 22, '1999-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 7, 'Homo For The Holidays', 'Will and Grace are shocked to learn that Jack never told his mother he was gay and encourage him to open up to her at Thanksgiving.  The evening brings a revelation for Jack as well: his father isn''t who he thinks it is.', 22, '1999-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 8, 'Terms Of Employment', 'Grace looks to Will for representation when a hotshot lawyer doesn''t pay her for a consulting assignment, but he ends up making Will a job offer. Meanwhile, Jack and Karen turn a training film set into an adult entertainment experience.', 22, '1999-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 9, 'I Never Promised You An Olive Garden', 'Tired of Rob and Ellen''s low-rent taste in dining, Will and Grace start hanging with a pair of hip downtowners they meet at a sushi joint. But as the new pals paint the town, Rob and Ellen see red when they catch their best friends lying to avoid plans to dine at their favorite eatery: a coupon-crazy Italian chain in Secaucus. Meanwhile, Jack''s inner child gets a little pick-me-up when he joins Karen at a PTA meeting at her kid''s school.', 22, '1999-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 10, 'Tea and a Total Lack Of Sympathy', 'When they appear on their favorite TV show, Antiques on the Road, Grace can''t wait to dress down the guests who are ever hopeful that their tchotchkes are worth a fortune, while Jack just wants to undress the show''s attractive appraiser, Porcelain Paul. But then it''s all business when they realize that their junky, thrift-store teapot is actually valued at $30,000. Meanwhile, Will''s new boss makes the reluctant lawyer kiss up to Karen in hopes of landing her hubby as a client.', 22, '2000-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 11, 'Seeds Of Discontent', 'Grace is excited to meet Will''s best friend from high school until she learns that the woman has made a request: to be implanted with Will''s sperm.  Now Grace has to confront Will about Will being her ""backup.""', 22, '2000-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 12, 'He''s Come Undone', 'Erotic dreams about Grace send Will to a therapist, who seems more interested in Grace.  Meanwhile Jack and Karen clash over her treatment of Rosario.', 22, '2000-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 13, 'Oh Dad, Poor Dad, He''s Kept Me In The Closet And I''m So Sad', 'Will''s ideal relationship with his loving father sours when his dad prepares to accept an award at his company''s dinner banquet but tries to dissuade his son from attending because he''s told everyone that Will is married to Grace. Meanwhile, Karen''s private detective finds Jack''s biological father.', 22, '2000-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 14, 'Acting Out', 'Will and Jack appear on Today to protest NBC for cutting a gay kiss out of an eagerly-waited sitcom episode. Will is frustrated with Jack on how much he wanted to see that kiss and kisses him. Elsewhere, Grace confides in Karen about dumping her boyfriend.', 22, '2000-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 15, 'Advise and Resent', 'When Will is set up on a blind date by his boss, he has internal debates on whether or not to go. Of course, Jack gives Will advice on how to be a good blind date. Meanwhile, Grace continues to struggle with her wimpy boyfriend Josh as Karen doles out some typically un-wanted advice.', 22, '2000-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 16, 'Hey La, Hey La, My Ex-Boyfriend''s Back', 'Will thinks that he has another chance with Michael, his old boyfriend and Grace''s new client.  Meanwhile, Karen tries taking her ""career"" more seriously and asks Grace for greater responsibilities.', 22, '2000-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 17, 'The Hospital Show', 'While on a blind date, Will finds out that Karen''s husband Stan has had a heart attack and rushes to the hospital to be with the gang. Will, Jack, Grace, and Rosario all speculate on who Karen will turn to for her inevitable emotional breakdown. After all, who will pay the bills if Stan dies?', 22, '2000-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 18, 'Sweet & Sour Charity', 'After winning concert tickets from a radio contest, Grace vows to get more involved and she volunteers herself and Will to help out at the community center. Unfortunately, her charitable work conficts with the concert. Meanwhile, while collecting clothes to give to the mission, Jack donates a pair of Karen''s most-prized shoes.', 22, '2000-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 19, 'An Affair To Forget', 'When Rob and Ellen ask Will and Grace to be the best man and maid of honor at their wedding, Grace''s sexy past with the groom is exposed when Ellen learns at her bachelorette party that Grace once slept with Rob. Meanwhile, Jack is confused by his reaction to the entertainment at Rob''s bachelor party.', 22, '2000-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 20, 'Girls, Interrupted', 'Despite their history, Grace spends a fun evening with Val [ from ep. # 18 Grace, Replaced] only to have Will suspect her of stealing. Meanwhile Jack becomes attracted to the leader of Welcome Home-an organization for gays who have converted to going straight, so he acts straight to woo the man.', 22, '2000-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 21, 'There But For The Grace Of Grace', 'It''s a scary glimpse into the future for Will and Grace when they visit their curmudgeonly retired college professor only to discover that he is a bitter old man that has a ""Grace"" of his own. Meanwhile, Karen must confront her most mortal enemy, the kitchen, when Stan requests a homecooked meal for his birthday, and she looks to Jack and Ben to come to her rescue.', 22, '2000-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 22, 'My Best Friend''s Tush', 'Grace is thrilled when, thanks to Karen''s social connections, she gets the chance to land a prestigious client for her interior-decorating firm. The only problem? She must compete with international design goddess Helena Barnes. To help boost Grace''s confidence, Karen assumes the alias of ""Anastasia Beaverhausen"" to dig up dirt on the socialite. Meanwhile, Jack tries marketing an odd invention: a tush pad for riding the New York City subway.', 22, '2000-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 23, 'Ben? Her? (1)', 'To help make peace between Grace and Ben, Will has them both over to dinner, only to have their relationship go beyond friendship.  But then Will finds out that Ben is dating someone else.  Meanwhile Jack catches Rosario in a clinch with a lover and learns that she wants a divorce.', 22, '2000-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 2), 24, 'Ben? Her? (2)', 'Forced by his boss to betray both of his friends, Will quits--only to discover that everything isn''t as it seems.  Frustrated, he leaves a lost Jack and Grace behind and ends up on a tropical island without a care in the world.  Until Ben shows up.', 22, '2000-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 3, 'Season 3', 'The third year opens with Will (Eric McCormack) returning from his stay on a tropical island to find that Grace (Debra Messing) - who is torn between two boyfriends - and his friend Jack (Sean Hayes) have bonded.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 1, 'New Will City', 'After three months on the island, Will finally returns only to learn that Jack and Grace have bonded in his absence.  Meanwhile Grace still can''t decide between Josh and Ben; When Karen tries to smuggle pearls in the States, Rosario ends up taking the rap.', 22, '2000-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 2, 'Fear and Clothing', 'Terrified after someone breaks into her apartment, Grace stays with Will.  Unfortunately, having both her and Jack under one roof is driving Will crazy and he forces them to choose which one will move out; Jack and Karen are still at odds over his divorce from Rosario.', 22, '2000-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 3, 'Husbands and Trophy Wives', 'Will and Jack can''t wait to arrive at the house of two old friends who are known for their wild parties but they discover that the former party animals are now sedately raising an adopted baby girl -- and Will shocks Jack when he volunteers to test his shaky parenting skills by babysitting her for them. Elsewhere at a snooty yacht club, Grace believes that Karen is jealous of her romantic relationship with Ben but then later regrets taunting her.', 22, '2000-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 4, 'Girl Trouble', 'Grace''s delight in having a bright intern whom she can mentor turns into horror when the young woman re-makes herself into the spitting image of sassy, brassy Karen -- and that''s at least one too many Karens to handle. Meanwhile, Will and Jack volunteer to act out scenes for a gay sensitivity seminar for the local police but the peaceful intent is lost when they tussle with two lesbian cast members who strongly object to their non-inclusive, sexist language.', 22, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 5, 'Grace 0, Jack 2000', 'Grace has made up her mind to break up with Ben because she''s convinced their relationship is going nowhere -- but his charm and refusal to call it quits tempt her to reconsider. Meanwhile, Jack''s latest and most outrageous cabaret gig is an absolute bomb until he frantically works an unwilling Will into the act by mercilessly ridiculing his attending friend''s most-private confessions.', 22, '2000-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 6, 'Love Plus One', 'Grace rejects an ex-boyfriend''s suggestion that she participate with him and his girlfriend in a romantic escapade but when she confides in Will and Karen -- who fall down laughing at the prospect -- the conservative Grace considers throwing caution to the wind. Meanwhile, Will tries to help a newly employed Jack meet a customer at a clothing store by prompting him with witty lines like a latter-day Cyrano de Bergerac.', 22, '2000-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 7, 'Gypsies, Tramps and Weed', 'Will reluctantly decides to use a birthday gift certificate from Grace to consult a psychic about his future and encounters an absent-minded fortune teller whose frighteningly personal predictions leave him reeling. Elsewhere, a guilt-ridden Grace hires a lackadaisical waiter whom she helped to get fired while Jack, who forever idolizes music, TV and film legend Cher, stumbles onto the real deal and meets the Oscar winner herself -- whom he mistakes for a drag queen.', 22, '2000-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 8, 'Lows In The Mid-Eighties (1)', 'In a flashback to Thanksgiving 1985, coed Grace invites her college boyfriend Will home to meet her family, but their romantic relationship swerves dramatically when a conflicted Will phones a teenaged Jack for some crucial advice. Unfortunately, Will and an angry Grace end up temporarily estranged when he blurts out the truth and she orders him out of the house -- and her life.', 22, '2000-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 9, 'Lows In The Mid-Eighties (2)', 'In a flashback to Thanksgiving 1985, coed Grace invites her college boyfriend Will home to meet her family, but their romantic relationship swerves dramatically when a conflicted Will phones a teenaged Jack for some crucial advice. Unfortunately, Will and an angry Grace end up temporarily estranged when he blurts out the truth and she orders him out of the house -- and her life.', 22, '2000-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 10, 'Three''s A Crowd, Six Is A Freak Show', 'Just as Grace seems to be on the verge of a promising relationship, she undergoes a minor medical procedure that leaves her with an embarrassing ugly sore on her lip, but even though her new beau accepts her temporary blight, she cannot return the favor when she is horrified to learn he has six toes on one foot. Meanwhile, Will vies with Jack for the attentions of the same man until each agrees to walk away to preserve their friendship.', 22, '2000-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 11, 'Coffee & Commitment', 'When they are asked to read at the civil union of two friends, Will and Grace verbally spar over her self-serving, get-and-take attitude where Will is responsible for everything -- but what''s really bugging him is the overwhelming feeling that Grace is behaving more like a wife than an old friend. Meanwhile, Karen tries to help a caffeine-addicted Jack get over a failed crush but he''s so jacked-up on java that only a tough-love approach will work.', 22, '2001-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 12, 'Swimming Pools... Movie Stars', 'Will and Grace get carried away in an escrow undertow when they pose as a wealthy couple shopping for homes of the rich-and-famous and visit Sandra Bernhard''s posh townhouse where they become fast friends and make an fake offer -- but their ploy fizzles when she accepts their offer. Elsewhere, Karen is forced to attend her young stepson''s swim meet and is uncharacteristically chastised by another mother for arriving late while Jack begins attending Co-dependents Anonymous meetings.', 22, '2001-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 13, 'Crazy In Love', 'A sports-challenged Will tries to impress his new friend Matt â€“ a sportscaster â€“ with his athletic skills by checking into a batting cage but it takes Grace to show him how to improve his swing. Meanwhile, Grace is given a mission: impossible when Jack and Karen ask her to exotically re-decorate Jack''s apartment.', 22, '2001-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 14, 'Brothers, A Love Story', 'Will is torn over ending his newfound relationship with Matt, a rising TV sportcaster who is extremely reluctant to let the world â€“ especially his macho business associates â€“ know about his sexual preference, so he continues to refer to Will as his ""brother."" Meanwhile, as Grace does her best to help Will decide, Karen is livid when she discovers that he helped draft her husband''s will, which will award much of his estate to charity.', 22, '2001-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 15, 'My Uncle The Car', 'Grace dispatches Will to sell her dearly departed uncle''s jalopy but after he makes the sale to an enterprising nun, a guilty Grace changes her mind and wants to buy it back -- but the sister makes it clear that, short of a miracle, it''s going to cost her plenty. Elsewhere, Karen must duel with an equally eccentric rich friend for the housecleaning services of Rosario while Jack suddenly sees the world differently when he believes his missing father is African-American.', 22, '2001-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 16, 'Cheaters (1)', 'Grace is apoplectic when she catches Will''s philandering father on the arm of a glamorous stranger, but she gets even more worked up when she tells Will -- and he''s happy living with denial. Speaking of cheaters, Karen misunderstands Grace and suddenly suspects that her husband Stan is having an affair, so she sets out to even the score.', 22, '2001-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 17, 'Cheaters (2)', 'Grace is apoplectic when she catches Will''s philandering father on the arm of a glamorous stranger, but she gets even more worked up when she tells Will -- and he''s happy living with denial. Speaking of cheaters, Karen misunderstands Grace and suddenly suspects that her husband Stan is having an affair, so she sets out to even the score.', 22, '2001-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 18, 'Mad Dogs and Average Men', 'Grace is smitten when she meets Sumner, Karen''s charming and handsome nephew, but Grace''s attempts to arrange a date are constantly thwarted when Karen conjures up a litany of lies to dissuade her. Meanwhile, Will tries to terminate his dead-end relationship with a needy nebbish, but postpones the dramatic moment because he''s so infatuated with the guy''s lovable doggie, Pepper.', 22, '2001-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 19, 'Poker? I Don''t Even Like Her', 'Grace''s lousy poker playing leads Will''s friends to ban her from the game, but Grace makes an amazing turnaround to stay in; Karen uses a snippy socialite as a guinea pig for cosmetic surgery.', 22, '2001-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 20, 'An Old-Fashioned Piano Party', 'When Grace frets that she and Will might drift apart like their similar friends, she impulsively buys an expensive piano which she hopes will cement their mutual bond and love for music â€“ or at least give her an excuse to perform a lot of show tunes. Meanwhile, when Jack is dumped by his latest romantic interest, he vents his grief by writing trashy novels which instantly draw Karen''s passionate attention.', 22, '2001-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 21, 'The Young and the Tactless', 'Grace gives romantic advice to her slovenly new neighbor, Nathan, in hope of reuniting him with his girlfriend so he will move away. Meanwhile, Will and Jack are out on the town with an unwelcome chaperone: Karen''s oblivious mother-in-law.', 22, '2001-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 22, 'Alice Doesn''t Lisp Here Anymore', 'When Grace learns that an old school mate who she made fun of has died, guilt makes her attend the funeral.  Meanwhile, Jack is nominated for a gay cabaret award.', 22, '2001-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 23, 'Last Of The Really Odd Lovers', 'Grace hates herself for her fatal attraction to Nathan and wants to keep her embarrassing romance with him a secret. Likewise, Will prefers to maintain discretion in his relationship with a much younger man. Meanwhile, Jack revels in the attention lavished on him by Grace''s eccentric friend, Val.', 22, '2001-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 24, 'Sons and Lovers (1)', 'An exasperated Grace tries to mediate between a resentful Will and her sloppy, free-spirited boyfriend Nathan when Nathan moves in while Jack is in a royal dither as he plans to finally meet his unseen father face-to-face. However, Grace grows nervous when the two polar-opposite men find some common ground and she ponders how a devoted boyfriend might affect her equally important relationship with her longtime buddy Will. After settling his father issues, Jack later gets the surprise of his life in a most unexpected fashion.', 22, '2001-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 3), 25, 'Sons and Lovers (2)', 'An exasperated Grace tries to mediate between a resentful Will and her sloppy, free-spirited boyfriend Nathan when Nathan moves in while Jack is in a royal dither as he plans to finally meet his unseen father face-to-face. However, Grace grows nervous when the two polar-opposite men find some common ground and she ponders how a devoted boyfriend might affect her equally important relationship with her longtime buddy Will. After settling his father issues, Jack later gets the surprise of his life in a most unexpected fashion.', 22, '2001-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 4, 'Season 4', 'Jack reconnects with his teenage son, Karen faces upheaval in her extravagant lifestyle, and Will and Grace navigate their evolving friendship amid career and dating mishaps. Guest stars like Cher, Sandra Bernhard, and Woody Harrelson bring standout moments in this sharp and heartfelt season.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 1, 'The Third Wheel Gets The Grace', 'Will returns from vacation to discover that Grace''s romantic relationship with neighbor Nathan is humming along. Nathan feels neglected when Will and Grace resume their chummy friendship, complete with their own private language and code. Meanwhile, Jack proudly takes his new-found son Elliot shopping for school at Barney''s while Rosario and Karen each cruise the merchandise looking for the perfect "anniversary gift".', 22, '2001-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 2, 'Past and Presents', 'The new lawyer in Will''s firm is the same lout who bullied him as a child; Nathan''s birthday flusters Grace, who''s outdone in the gift department by Karen.', 22, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 3, 'Crouching Father, Hidden Husband', 'Jack is puffed up with paternal pride as he escorts his long-lost teenaged son Elliot to a junior high school dance but not before he coerces Grace into posing as Elliot''s date â€“ which only revives her own tortured memories of rejection from school dances many years before. Elsewhere, Karen has great fun at her lawyer Will''s expense when she continues to capriciously summon him for bogus ""emergencies"" â€“ that is, until she really needs him.', 22, '2001-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 4, 'Prison Blues', 'After Stan is arrested for tax evasion, Grace and Karen timidly visit him in prison. Grace is so moved to help her worried friend that she moves right into Karen''s deluxe apartment-in-the-sky, where she becomes a demanding guest who''s soon hooked on servants, bubble baths and an extravagant lifestyle. Meanwhile, as Stan''s attorney, Will struggles with stage-fright when he babbles on during a TV news interview, so Jack convinces him to polish his communication skills by attending an acting class ruled by an imperious teacher.', 22, '2001-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 5, 'Loose Lips Sink Relationships', 'In a sneaky ploy to bum a night off from work at Barney''s department store, a conniving Jack plays matchmaker and takes advantage of his geeky female supervisor''s interest in Will, while mindful of Will''s fantasy of modeling in the store''s catalogue. Jack parlays their mutual desires into a "date", even though his unsuspecting friend doesn''t have a clue of her intentions. Elsewhere, Grace goes where no woman should when she compares her previous sexual experience with her boyfriend Nathan''s.', 22, '2001-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 6, 'Rules Of Engagement', 'During an intimate moment, Nathan pops the question of marriage to Grace but she recoils simply because the situation didn''t fit her childhood fantasy of a proposal. When she realizes her mistake, she returns the favor, but doesn''t get the response she hoped she''d get.', 22, '2001-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 7, 'Bed, Bath & Beyond', 'While a baleful Grace wallows in bed as she grieves over losing her boyfriend Nathan, an enterprising Will tries all his old tricks to spring her from her mattress and back into the real world''s whirl. But when Jack and Karen arrive, Will fears that their bizarre efforts to help might actually drive Grace futher into her shell -- not to mention therapy.', 22, '2001-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 8, 'Star-Spangled Banter', 'Will and Grace elect to disagree when it comes to choosing sides during a mayoral election; she supports the female Jewish candidate and he''s voting for the gay nominee. To settle matters, the roomies host fund-raisers attended simultaneously by both aspirants.', 22, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 9, 'Moveable Feast (1)', 'Rather than be apart on Thanksgiving Day, Will and Grace join Jack and Karen for a festive holiday motor tour of their respective dysfunctional families, including Grace''s domineering mother as well as Will''s willful mom and Jack''s stepdad -- with unsettling results. Meanwhile, back home, a waiting Rosario bastes and tastes their juicy turkey.', 22, '2001-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 10, 'Moveable Feast (2)', 'This episode is also known as "Thanksgiving."  Will and Grace join Jack and Karen in a motor tour of their respective families. (Double-length Episode)', 22, '2001-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 11, 'Stakin'' Care Of Business', 'At the gym, Will spies another guy who looks maddeningly familiar, while Jack gets a workout as he keeps repeating one of his nonsensical catchphrases in hopes of seeing it become popular among the sweat set. Meanwhile, Grace gets some bad advice from Karen when she seeks a loan to expand her company so she stoops to asking her wealthy employee herself for the moneyâ€”even if she has to resort to drastic measures to get the point across.', 22, '2001-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 12, 'Jingle Balls', 'Grace is hired as seasonal help to decorate the Christmas display windows of fashionable Barney''s; Will meets a ballet dancer but is too embarrassed to introduce his friends.', 22, '2001-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 13, 'Whoa, Nelly', 'Will & Grace try to lure Tina, Will''s dad''s mistress, away from Will''s father by setting her up with another man.  Unfortunately the only man available is Will''s gay friend, Larry.  Also, Karen buys a horse for breeding, but the stud is more interested in stallions.', 22, '2002-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 14, 'Grace In The Hole', 'While visiting Karen''s incarcerated husband, Grace re-discovers a handsome high school friend who''s also doing time in prison, and despite Will''s advice, she''s soon dressing up and visiting the inmate while dreaming of a life together outside the Big House. Conversely, a sympathetic Rosario chides Karen for not standing by her man â€“ and bets her boozy boss that she and pal Jack cannot stay penned-up together in the same room for three days without harming each other.', 22, '2002-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 15, 'Dyeing Is Easy, Comedy Is Hard', 'Rosie O''Donnell plays Bonnie, a no-nonsense single mom who clashes with Jack over the raising of their son, Elliot, fathered from Jack''s sperm-bank donation. Bonnie''s enraged because Jack had 12-year-old Elliot''s hair bleached blond, so she lays down the law. ""From now on,"" she tells him, ""stay out of my kid''s life. I don''t want you to see him again."" A parallel storyline unfolds at a wedding gala, where Will poses as a tennis pro (because nobody likes lawyers); and Grace caustically toasts the bridegroom, her ex-fiancÃ©. ""I''ve always thought about having a child,"" she says. ""But not as a husband.""', 22, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 16, 'A Chorus Lie', 'Matt Damon makes a guest appearance as a clever charmer named Owen, who''s competing against Jack for a spot in New York''s Gay Men''s Chorus. Truth be told, however, Owen is totally straight and is really after the group''s big perk: a summer trip to Europe, all-expenses paid. Jack suspects Owen''s ruse but needs proof. How about the hug test? Now a flustered Jack reluctantly turns to Grace to ""in"" Owen. Meanwhile, a scheming Karen tries to pass off an unwitting Will as her lover and not her lawyer when she discovers that she''s the object of pity for being single at her own Valentine''s Day party', 22, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 17, 'Someone Old, Someplace New', 'Will and Grace feel they need more elbow room, so they search for larger digs and find an exquisite placeâ€”despite the efforts of Sandra Bernhardâ€”but to finance the move, they illegally sub-let their old apartment. Meanwhile, a well-intentioned Jack begins filming a documentary of Karen''s colorful life to celebrate her birthday but accidentally stumbles upon her estranged, lowlife mom.', 22, '2002-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 18, 'Something Borrowed, Someone''s Due', 'After Will and Grace move into their expansive new dream apartment, they discover the awful pangs of separation anxiety as they pine for their smaller old digs now happily occupied by their friends who sub-let the place. Elsewhere, Jack tries to reconcile Karen with her estranged grifter of a mom, who wants to recruit her daughter for her next caper.', 22, '2002-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 19, 'Cheatin'' Trouble Blues', 'Will presents his newly reconciled parents with a cruise for their anniversary, but their individual secrets ruin his hopes.', 22, '2002-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 20, 'Went To A Garden Potty', 'In the aftermath of his parents'' divorce, Will salvages a beloved garden gnome â€“ nicknamed ""Squatsie"" â€“ and proudly plants the childhood relic in his apartment''s community area until Grace accidentally delivers a coup de grace on the gnome''s dome with a shovel. Elsewhere, Jack consults his acting coach when he fears that his heterosexual role in a mattress commercial produced by Karen will stereotype him for more meaningful gay acting gigs in the future.', 22, '2002-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 21, 'He Shoots, They Snore', 'Teaching a design seminar challenges Grace; chaperoning Jack''s son occupies Will at the youth''s basketball tourney.', 22, '2002-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 22, 'Wedding Balls', 'Will expects two friends to arrive in New York to plan a wedding, but when the bride-to-be falls ill, he asks a willing Grace to work with the clueless groom to work out the details â€“ but she gets a little too involved in the dreamy details and fancies herself a bride instead. Meanwhile, Will and Karen get chummy over a steamy potboiler book that they''re both reading which leaves a jealous Jack fuming as the odd man out in the book-of-the-month club.', 22, '2002-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 23, 'Fagel Attraction', 'After his laptop computer is stolen, Will meets a sociable police detective who takes a special interest in his case as they go undercover â€“ but Will doesn''t know that the gumshoe is secretly participating in Jack''s therapy group for gays. Elsewhere, Grace is again hassled by her psycho neighbor Val who ""opens"" a rival design business and prospers by stealing Grace''s ideas.', 22, '2002-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 24, 'Hocus Focus', 'After Will wins a portrait session at a charity auction, he takes Grace to pose for a notoriously eccentric celebrity photographer but the unfocused shooter''s bizarre methods ultimately produce a funky image that flatters Grace â€“ and frightens Will. Meanwhile, Jack''s back with another performance act, and this time he employs magic tricks but regrets using Karen as his assistant.', 22, '2002-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 25, 'A Buncha White Chicks Sittin'' Around Talkin''', 'When Will hears his ""biological clock"" ticking, he shocks Grace by asking her to become the mother of his baby but when they meet with a therapist, Grace reveals that she''s uneasy about the necessary sacrifices â€“ and makes a startling revelation. Inspired by Will''s ""seize-the-day"" quest, Jack and Karen are also moved to pursue their goals: for him, it''s auditioning for a legitimate Broadway production; for her, it''s visiting her imprisoned husband for a dreaded conjugal visit.', 22, '2002-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 26, 'A.I.: Artificial Insemination (1)', 'After Will and Grace decide to have a baby together, obstacles pile up before them, including a missing specimen sample and bungled insemination efforts that have them teetering between artificial and natural means â€“ all leading to mis-conceptions. Meanwhile, when Jack considers giving up his show-business aspirations, until he gets some career advice from a ""divine"" entity â€“ his idol, Cher. Likewise, married Karen is sorely tempted by the romantic tickling of a rich and natty gentleman.', 22, '2002-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 4), 27, 'A.I.: Artificial Insemination (2)', 'After Will and Grace decide to have a baby together, obstacles pile up before them, including a missing specimen sample and bungled insemination efforts that have them teetering between artificial and natural meansâ€”all leading to mis-conceptions. Meanwhile, Jack considers giving up his show-business aspirations, until he gets some career advice from a ""divine"" entity: his idol Cher. Likewise, married Karen is sorely tempted by the romantic tickling of a rich and natty gentleman.', 22, '2002-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 5, 'Season 5', 'Season Five finds Will and Grace considering having a baby, the possibility of true love for Grace, Karen’s (Megan Mulally) world changing, Jack’s (Sean Hayes) apartmentside cafe and of course plenty more snappy one liners and even a few dance moves.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 1, '...And the Horse He Rode In On', 'A dazed Grace is rescued by a handsome Jewish doctor who pulls her up on his horse and delivers her just in time for her insemination with an impatient Will. But their new relationship as expectant parents puts a strain on Will and Grace''s relationship when they agree not to date until their baby is born. Meanwhile, a restless Karen can''t make up her mind about cheating on her imprisoned husband with the genteel but ardent suitor Lionel.', 22, '2002-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 2, 'Bacon And Eggs', 'After stalking actor Kevin Bacon, Jack lands his dream job when the unsuspecting celebrity hires him as his personal assistant and immediately assigns him to find out who''s been harassing him. Elsewhere, while Will and Grace wait for the right color to appear on their home pregnancy test, Grace is visited by a handsome doctor who makes her a tempting offer. In addition, Karen looks for a way out of her on-again, off-again relationship with the courtly and irresistible suitor Lionel.', 22, '2002-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 3, 'The Kid Stays Out Of The Picture', 'Grace is so entranced by her budding romantic relationship with a handsome doctor that she asks an impatient Will for an extra month to re-consider her commitment to conceiving their child through artificial insemination resulting in verbal sparring match.', 22, '2002-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 4, 'Humongous Growth', 'While Will and Grace are feuding, Karen and Jack hatch a wobbly plan to patch up their differences about co-parenting a baby by tricking each one into attending the same child''s birthday party. After arguing over who brought the better gift, the feathers continue to fly as the best friends fuss over their conflicting agendas.', 22, '2002-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 5, 'It''s The Gay Pumpkin, Charlie Brown', 'A bicycling adventure tests Will and Grace up in the Catskills with Leo and his pal in a quest for Halloween pumpkins.', 22, '2002-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 6, 'Boardroom & A Parked Place', 'Gene Wilder plays Mr. Stein, the long-absent senior partner of Will''s firm, who shows up unexpectedly to reassume command. He just might succeed if he weren''t such a frantic, neurotic mess. What he needs is a smart, attentive lieutenant who can make decisions and do some of the dirty work (like firing people). Enter Will. Meanwhile, Grace and Jack are shocked to discover that their highfalutin'' pal Karen is now poorer than a church mouse and living in her limo.', 22, '2002-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 7, 'The Needle & Omelet''s Done', 'When Grace accompanies Leo to dinner with some ""friends,"" she doesn''t realize that he''s tricked her and instead introduced her to his real parents and she soon regrets her earlier salty dialogue and suggestive attitude. Elsewhere, Jack is again confronted by Zandra his gruff acting teacher when he tries to showcase his meager talent in a class while a willing Will joins Karen in subjecting to a Botox facial injection.', 22, '2002-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 8, 'Marry Me A Little (1)', 'Grace and Leo impetuously take their vows at a Central Park wedding that is a ratings stunt hosted by Today''s Katie Couric. Grace''s pals, especially Will, are hurt that they weren''t invited, but all seems forgiven when everyone including Grace''s outspoken mom and the subdued Mrs. Marcus gather days later for a swank reception. It should be a festive bash, but the emergence of unsettling details about Leo and about the park nuptials give Grace reason to wonder whether she has made a mistake.', 22, '2002-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 9, 'Marry Me A Little More (2)', 'Grace''s wedding to Leo leaves Will feeling upset over losing his best friend.', 22, '2002-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 10, 'The Honeymoon''s Over', 'After a displaced Karen is booted from her Palace Hotel digs, a sympathetic Will agrees to let her move in with him at least until she turns his apartment into a federal disaster zone with her exorbitant lifestyle, forcing Will to try and unload her onto Grace''s shoulders. Meanwhile, Jack loses style points when he poses incognito out of fear that the ""Gay Mafia"" has it out for him.', 22, '2002-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 11, 'All About Christmas Eve', 'On Christmas Eve, Grace is torn when she has only two tickets to ""The Nutcracker"" and can''t take both her best friend Will and new husband Leo, but her back-and-forth indecision leaves Will spinning like a Hanukkah dreidel between a dithering Grace and his previous holiday plans with Jack and Karen.', 22, '2002-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 12, 'Field Of Queens', 'Alternately flirty and shy, and acting “incredibly” like a schoolgirl, Karen falls for a suave and sexy restaurateur. The two of them seemed to hit it off on their first date, but then, he hasn''t called her in three days. So buttinsky Grace makes it her mission to confront Prince Charming and find out why. Elsewhere, Will and Jack join a gay men''s soccer team, and Will, for one, is hardly having a ball. "They were running and kicking and pushing each other down." he says. "It was supposed to be gay sports. Where were the lingering hugs?"', 22, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 13, 'Fagmalion Part One: Gay It Forward', 'New relationships discomfit Will and Grace. For starters, Karen fixes up Will with her cousin Barry, who, according to his matchmaker, is ""handsome [and] hot."" So imagine Will''s surpise when he goes on a blind date with Barry and finds he''s actually a self-conscious, dreadfully dressed geek who admits at thirtysomething that he''s just coming out of the closet. Back in Brooklyn in her new digs, Grace entertains her interesting new neighbor: an extroverted masseuse named Julie, who Grace suspects may be too interested in her.', 22, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 14, 'Fagmalion Part Two: Attack Of The Clones', 'Will and Jack continue their campaign to adapt Karen''s awkward cousin Barry to his new lifestyle but their flamboyant efforts to help him only remind Will of his own clumsy experiences when he came out in 1986. Elsewhere, Grace feels abandoned by Leo when he leaves for three weeks to offer his medical services to the needy in Africa.', 22, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 15, 'Homojo', 'Jack suffers Karen''s wrath when he is seduced into friendship with her manipulative British romantic rival, who has set up house with Karen''s ex-husband. Meanwhile, Will and Grace try to re-connect their lagging friendship with a competitive night of board games with their friends.', 22, '2003-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 16, 'Women & Children First', 'Demi Moore plays Sissy Palmer-Ginsburg, Jack''s babysitter who now becomes his roomate. On the other hand, Will hates her.Grace faces an identity crisis as a wife.', 22, '2003-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 17, 'Fagmalion Part Three: Bye, Bye, Beardy', 'Will finds a guy that he''s interested in.', 22, '2003-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 18, 'Fagmalion Part Four: The Guy Who Loved Me', 'While Jack and Barry have their first date, Will interrupts to confess that he has feelings for Barry. Then Jack and Will give Barry an ultimatum: he must choose which one he would like to date. The decision is made - Will. At her hotel, Karen mocks Rosario by putting on a maid''s apron. She is then mistaken for an actual maid by a very handsome maintenance man who has a disliking for the rich. In order to be near him, she and Rosario switch roles. After a week of perfect dates, Will tells Barry that he wants their relationship to be exclusive. However, Barry claims that he needs to play the field more and see what''s out there before he settles down.', 22, '2003-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 19, 'Sex, Losers, & Videotape', 'Will, Karen and Will''s boss Mr. Stein (Gene Wilder) form an anti-romance club thanks to Will and his recent break-up with Barry.  The three hold two meetings claiming that ""love stinks"" until Karen and Mr. Stein form a budding relationship.  The two carry on having sex and dating behind Wills back not wanting to hurt him.  Will breaks up the club after he finds out claiming that ""If you''re going to form a club for people who are alone and bitter, you have to at least stay bitter.""
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 20, 'Leo Unwrapped', 'Will attempts to sneak Leo back from Africa to surprise Grace for her birthday.  But things don''t quite go as planed.  All starting with when Grace runs into Leo who arrived a little too soon.  But, to spare Will''s feelings, they agree to act like they never saw each other.  Grace asks Karen and Jack to keep Leo busy until her ""birthday surprise.""  Unfortunately, the duo takes their mission too seriously.', 22, '2003-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 21, 'Dolls and Dolls', 'Karen looks for a place to live, and succeeds in finding an apartment with a gal named Liz.  Liz turns to be just as self-important and skanky as Karen, so it''s a perfect match.  Meanwhile, Grace and Jack are concerned about Will when he gets injured and relies heavily on painkillers.', 22, '2003-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 22, 'May Divorce Be With You', 'The divorce proceedings begin, and Karen is shocked to learn that Will is Stan''s lawyer, not hers.  On a whim, she hires Soupie, a wet-behind-the-ears lawyer with a child''s mentality.  Meanwhile, Grace is caught in a social faux pas when her biggest client ever has an on-again, off-again relationship with Jack.', 22, '2003-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 23, '23', 'In the middle of her divorce proceedings, Karen learns that ex-husband Stan has suddenly passed away, and the funeral becomes a contest of wills between Karen and her British rival, and a free-for-all when the will is read for everyone who ever felt deserving, such as Will. Meanwhile, Grace is shocked when recently returned husband Leo is called back into service by Doctors Without Borders and asks her to make the trip with him to Guatemala.', 22, '2003-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 5), 24, '24', 'Karen, Will, Jack, and Grace go on a trip in Karen''s yacht to sprinkle Stan''s ashes into the Caribbean while Leo is flying to Guatamala with an atractive co-worker. While Karen sprinkles Stan''s ashes she finds Lorraine has been stowing on board. While Karen and Loraiinne fight, Will and Jack get drunk. Lorainne pushes Karen off the board and Rosairo jumps off after her. The next morning Grace finds Leo''s bag with a letter from his co-worker Danni saying that she wants Leo. Will wakes up in bed naked with a hangover and a naked Jack in the bed with him. Meanwhile Karen and Rosairo are stuck on a cargo boat.', 22, '2003-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 6, 'Season 6', 'Will (Eric McCormack), Grace (Debra Messing), Jack (Sean Hayes) and Karen (Megan Mullally) are joined by an incredible array of guest stars making up a new suitor for Karen, Grace’s older sister Janet, Will’s gorgeous boyfriend and Leo’s ex-girlfriend.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 1, 'Dames At Sea', 'Will and Jack awake in a precarious position - sharing a bed in the nude - while at sea. Unable to remember every detail from the night before, the two alleged bedfellows deny the possibility that anything happened, but each grow concerned as to how to dump the other. Meanwhile, Grace''s discovery of a love letter in Leo''s bag from a female colleague prompts her to doubt his fidelity and Karen survives a night fighting for her life while afloat in the forbidding night sea and a freighter full of russian sailors, and must honor a pact with savior Rosario.', 22, '2003-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 2, 'Last Ex To Brooklyn', 'When Leo invites his hip and trendy ex-girlfriend to a friendly dinner party, Grace turns to Will, Jack and Karen to round out the guest list and keep the night running smoothly. However, when Leo''s ex turns out to be the only girl Will ever slept with, Grace''s jealousy gets the better of her. Meanwhile, Karen discovers Lorraine''s dog Chompers hiding in Stan''s closet and searches for a new owner for the puppy.', 22, '2003-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 3, 'Home Court Disadvantage', 'When Grace and Leo join Karen for a friendly game of tennis at her exclusive club, her fierce playing style sends Grace fleeing the court. However, when the reason for her angry play is her hatred for Leo, Grace is determined to find a way for them to get along. Elsewhere, a nervous Will suckers Jack into visiting his depressed mother in Connecticut hoping they can cheer her up.', 22, '2003-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 4, 'Me and Mr. Jones', 'Earning a brief speaking role in an off Broadway play, Jack shares the stage with legendary actor James Earl Jones. However, when the play''s director rejects James'' performance in favor of Jack''s one-line triumph, the award-winning actor looks to his co-star for instruction - enrolling in the McFarland acting school. Meanwhile, new roommates Will and his mother Marilyn continue their living arrangement, despite a secret desire to part ways.', 22, '2003-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 5, 'A-Story, Bee-Story', 'Depressed over his decision to leave Doctors Without Borders, Leo turns to a motivated Will to rekindle his love for New York. However, when Will''s version of ""the best of New York"" filled with long shopping trips and high tea doesn''t do the trick, Leo decides to move in a different direction. Meanwhile, Jack teams up with his new coach Karen as they prepare for the annual gay spelling bee.', 22, '2003-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 6, 'Heart Like A Wheelchair', 'Continuing his new role as caretaker for a disabled Marilyn, a resentful Will takes his wheelchair-bound mother for an afternoon roll in the park and bumps into an attractive bachelor Tom wheeling an invalid of his own. Using his mother as a reason for a daily rendezvous in the park, Will attempts to build up the courage to ask Tom out. Elsewhere, Karen continues her lifelong quest to hunt down hubby-stealing Lorraine tracking her to a room at the Peninsula hotel only to discover occupant to be her father Lester.', 22, '2003-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 7, 'Nice In White Satin', 'Will learns that Karen missed her physical, so he takes her to one of the finest doctors in the city. It is not until after the doctor does a demonstration on Will that Karen obliges. While at the office, Jack flirts with a male nurse, and he later announces that he''s going to be a nurse himself. The problem is, training costs $2,700, and Will and Karen are reluctant to give him the money. Once they pay the fees, Jack, fickle as ever, announces that he''s taken up surfing, and that he needs $1,600 for lessons. Will and Karen are about to let the nursing school know of his decision to drop out until Jack comes up with an inventive way to feed Karen her calcium pills.', 22, '2003-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 8, 'Swimming From Cambodia', 'When Grace returns back to New York for her mother''s birthday, Will tries to coerce her into staying in town a bit longer so the two can spend some quality time together. Meanwhile, Jack struggles with his new nursing teacher, Nurse Carver so Karen threatens her into letting Jack skip class and still make the grade. But, to everyone''s surprise Jack discovers that he really misses nursing school and learning.', 22, '2003-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 9, 'Strangers With Candice', 'Hoping to cheer up Grace, a well-dressed Will takes his best friend with him on a dinner date. When the date stands him up, Will catches the eye of a female patron while Grace bumps into a guy with whom she once shared an ordinary, forgettable romantic encounter. Meanwhile, Karen takes student nurse Jack out to celebrate his school ""success"" but the evening turns sour when Karen runs into her ultimate nemesis, Candice Bergen. The meeting sparks yet another round in the Bergen/Walker Prank War of 2003.', 22, '2003-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 10, 'Fanilow', 'Opting out of the annual Grace Adler Design Christmas party, ultimate ""Fanilow"" Will spends the night waiting in line for tickets to a special Barry Manilow concert only to have his weak bladder force him to make a quick pit stop and entrust Grace to hold his place. However, Will''s snubbing of an overweight man in the bathroom line leaves his chances of meeting his idol in doubt. Meanwhile, a distraught Grace discovers her mother has cancelled on their annual Hanukkah shopping spree to have dinner with Jack. And Karen is embraced by the inspiring music of Manilow waiting in line with a Fanilow named Cheryl.', 22, '2003-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 11, 'The Accidental Tsuris', 'When Grace''s rebellious, free-loading older sister Janet comes to town to launch her new jewelry enterprise/folding table subway stand, Grace decides to put her foot down casting her sibling away. However, when her tough love prompts Janet to go corporate by taking a 9-5 job and studio apartment, Grace can''t seem to handle her new image. Meanwhile, Karen continues to spurn Lyle''s proposals of marriage, only to have a change of heart after Lorraine stops by for an impromptu visit, to declare her disapproval over Karen''s ""relationship"" with her father.', 22, '2004-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 12, 'A Gay/December Romance', 'Attending a local gallery opening, Will catches the eye of a rich plastic surgeon, who uses his vast fortune to provide the modest lawyer with a new level of material possessions. However, when Will realizes that he has become a ""lady of leisure,"" he decides to confront his sugar daddy/boyfriend. Meanwhile, Grace''s thirst for delectable noodles sends her to a new local restaurant, but an argument with the owner prompts her to launch a boycott of the establishment.', 22, '2004-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 13, 'Ice Cream Balls', 'Love is in the air as Will''s slightly eccentric new client falls for Jack after he interrupts their meeting, but when Jack refuses to accept the romantic offer, Will sinks to bribing him in the hopes of furthering his career. Elsewhere, Grace and Karen take a trip to Leo''s cabin in Vermont in order to fix the plumbing â€“ and uncover a secret pile of cash in the master bed.', 22, '2004-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 14, 'Looking For Mr. Good Enough', 'Will decides to further his cooking skills by taking a class and invites Jack to join him in the kitchen but when Jack decides to include his new boyfriend, the gourmet attorney finds himself a sad single in a cooking class full of couples. Elsewhere, Karen''s mother Lois returns to town, slightly unnerving her daughter and calling on Grace''s thrifty design talents to help decorate her new apartment.', 22, '2004-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 15, 'Flip-Flop (1)', 'Dynamic enterprisers Will and Grace begin a new business venture as they buy old apartments to refurbish and re-sell for a tidy profit. When budding ""student nurse"" Jack bumps into his former acting mentor Zandra, the pair of entrepreneurs finds their first project apartment. Meanwhile, Karen renews her romance with Lyle Finster, but the couple''s bliss is interrupted by an unfortunate houseguest when Lorraine moves in.', 22, '2004-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 16, 'Flip-Flop (2)', 'Enjoying the success of their new business venture, entrepreneurs Will and Grace help their apartment buyers Jack and Stuart settle into their new life under one roof. However, when Grace receives a higher offer on the apartment, the ""friendly flippers"" attempt to break up the happy couple by encouraging Jack''s cold feet as they see a chance to make a quick buck. Meanwhile, Karen demands that Lyle finally discipline his unruly daughter Lorraine, nearly shattering the couple''s budding romance.', 22, '2004-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 17, 'East Side Story', 'Will and Grace ride the success of their recent real-estate venture to expand to the East Side but clash with the reigning champs of ""apartment flippers"" lesbians Deirdre and Monet. Fighting against their new competition''s intimidation tactics, the enterprising duo must rely on Will''s masculine sex appeal in the hopes of dividing the same-sex real-estate moguls. Meanwhile, Karen seeks the spiritual guidance of John Edward in order to comfort her guilt over her recent engagement.', 22, '2004-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 18, 'Courting Disaster', 'Searching for a movie-watching pal after Stuart opts out, Jack invites Grace for an afternoon at the theatre. However, when the duo discovers Stuart and a mystery man secretly catching a matinee, Jack is left questioning their relationship. Elsewhere, Will attempts to teach Karen the skills of driving, but the road warriors have a run in with the law their first trip behind the wheel, prompting Will to fight the ticket in traffic court.', 22, '2004-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 19, 'No Sex ''N'' The City', 'Tip-toeing through his budding relationship, an apprehensive Will makes the mistake of taking Grace''s advice on love, playing hard-to-get with his new pseudo-boyfriend. However, when his game playing causes a rift in this budding romance, Will is left questioning Grace''s wisdom in matters of the heart. Meanwhile, a distraught Jack and Karen bravely attempt to soldier on after learning their favorite television show will be going off the air forcing them to say goodbye to their six favorite Friends and a psychiatrist named Frasier Crane.', 22, '2004-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 20, 'Fred Astaire and Ginger Chicken', 'Smitten with his new boyfriend Vince, Will puts his relationship to the test introducing him to the overly critical Grace for her approval. However, when Grace abruptly cuts the introduction short, Will is convinced of her disapproval of Vince and thus begins to question his own feelings. Meanwhile, Karen drops a bombshell on Jack, revealing that after her upcoming wedding their friendship will be forever changed, forcing him to begin casting calls for her replacement.', 22, '2004-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 21, 'I Never Cheered For My Father', 'Responding to the pleas of his father''s mistress-turned-girlfriend Tina, Will attempts to discover whether there is a new woman in his dad''s life. However, when his father''s new mistress turns out to be his mother, Will must find a way to break the shocking truth to Tina. Meanwhile, Elliot''s decision to try out for his high school cheerleading squad has Jack all smiles as he is determined to help his son make the team.', 22, '2004-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 22, 'Speechless', 'On the eve of his graduation from nursing school, a nervous Jack turns to Will for help writing his commencement address. Reconnecting with his past dreams of being an accomplished playwright, Will over-analyzes the speech, searching for the life experience that sent Jack to nursing school as a source of inspiration.', 22, '2004-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 23, 'I Do (1)', 'Opting to forgo a picturesque fall wedding to elope in Las Vegas, Karen hops a plane to ""Sin City"" with fiance Lyle and faithful friends Will and Jack but when she bumps into vacationing superstar Jennifer Lopez, she asks J-Lo to sing at the ceremony. Meanwhile, Leo returns from Cambodia to meet up with Grace at the wedding, but their reunion is delayed by a freak design accident.', 22, '2004-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 6), 24, 'Oh, No, You Di-In''t (2)', 'Opting to forego a picturesque fall wedding and elope in Las Vegas, Karen hops a plane to ""Sin City"" with fiance Lyle and faithful friends Will and Jack. After arriving, they bump into superstar Jennifer Lopez who is vacationing and agrees on behalf of Rosario to sing at the ceremony. Meanwhile, Leo returns from Cambodia to meet up with Grace at the wedding, but their reunion is delayed by a freak design accident.', 22, '2004-04-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 7, 'Season 7', 'Series 7 of Will & Grace kicks off with the fall out from Leo’s adultery, Grace has left him and moved back in with Will taking most of his possessions with her.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 1, 'FYI: I Hurt, Too', 'Jack and Jennifer Lopez return from her summer tour to relax, but a pushy Karen recruits Jack to help her get Lopez''s attention for her newly written song, ""FYI:  I Hurt, Too."" Meanwhile, Grace takes out her frustrations over her cheating husband Leo on a beat-up Will.', 22, '2004-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 2, 'Back Up Dancer', 'After Jack is fired as a backup dancer by Jennifer Lopez, she gets him an audition with Janet Jackson for her performance tour. Meanwhile, Will and Grace try to get back to business as usual and mend Grace''s broken heart, only to have her come between Will and Vince.', 22, '2004-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 3, 'One Gay At A Time', 'Free food lures Grace to an AA meeting, where she runs into Val.  Meanwhile, Jack starts work as a TV executive at a gay network, something which Will is not aware of when he comes to the network for an appointment so he can give suggestions.', 22, '2004-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 4, 'Company', 'When Will and Grace meet a stranger named Ned in the elevator, Grace accuses Will of being too nice to people he doesn''t know. While Grace befriends Ned and invites him to dinner, Will makes some nasty remarks about him, but they soon discover that Ned''s not the best company to keep. Meanwhile, Jack is having trouble at his new company because he feels he can''t relate to his co-workers after they mock him about his Cher doll. Karen and Rosario lend some much-needed support.', 22, '2004-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 5, 'Key Party', 'A birthday party for Will (who''s 40 going on 37) is an uneasy celebration, thanks to a symbolic gift from his new lover that betokens commitment.  The strangest present:  a nude portrait of Will that''s lacking in certain details.', 22, '2004-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 6, 'The Newlydreads', 'Grace and Karen are hired to decorate an apartment of a newlywed couple and they want their place to be all about love. Will Grace and Karen, two newly divorced women, be able to do the task?  Meanwhile, a doomed bookstore gets help from Will... sort of.', 22, '2004-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 7, 'Will & Grace & Vince & Nadine', 'When Will and Grace invite Vince and Nadine over for a meet-and-greet dinner, they find to their horror that their guests are actually polar opposites of themselves. Meanwhile, Karen is still angry with Grace and decides to leave the interior design firm when Jack comes to her rescue and hires her to be his new assistant at ""Out TV.""', 22, '2004-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 8, 'Saving Grace, Again (1)', 'Grace comes home from a great date and listens to a staticy message she''s received from Leo.  Grace hides the message from Will, but when Will learns about it, he decides to take Grace to the Berkshires to get her mind off of Leo.  Meanwhile, Karen and Jack try to set each other up.', 22, '2004-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 9, 'Saving Grace, Again (2)', 'The group go on a road trip for Grace''s get away weekend -- a weekend devoted to not mentioning the name ""Leo."" Jack and Karen hate the car ride and decide to bail on the plan. Elsewhere, when Jack spots Peter a ""sinfully delicious"" man who Jack remembers from a cocoa commercial when he was a kid, he recruits him to be the new face of ""Out TV,"" much to the surprise of Rip Taylor who also wants the gig', 22, '2004-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 10, 'Queens For A Day (1)', 'When Vince''s mother injures her leg and is unable to make her traditional Italian Thanksgiving, Will comes to the rescue by offering to make his own special dinner, but Vince''s mother refuses to give Will any credit. Meanwhile, Jack gives Vince''s sister Ro a few pointers on a big secret she is keeping from her family and fiancé. Meanwhile, Grace and Karen get very cozy with Vince''s much younger cousin.', 22, '2004-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 11, 'Queens For A Day (2)', 'When Vince''s mother injures her leg and is unable to make her traditional Italian Thanksgiving, Will comes to the rescue by offering to make his own special dinner, but Vince''s mother refuses to give Will any credit. Meanwhile, Jack gives Vince''s sister Ro a few pointers on a big secret she is keeping from her family and fiancé. Meanwhile, Grace and Karen get very cozy with Vince''s much younger cousin.', 22, '2004-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 12, 'Christmas Break', 'Grace attends a holiday party at Will''s mother Marilyn''s home and accidentally breaks a treasured Lladro figurine. Will convinces Grace not to tell his mother and to blame the accident on one of the other guests at the party. Elsewhere, Karen''s stepdaughter, Olivia, comes to stay for the Christmas holiday. While lunching at the mall they start making fun of people, but Karen''s remarks are especially mean and Olivia and her friends take offense.', 22, '2004-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 13, 'Board Games', 'Scott Woolley, an old high school classmate seeks revenge on Karen for ruining his senior year by trying to become president of Walker Inc.  After Scott shows a presentation that wows the board, he takes control of the company, much to Karen''s dismay.  Meanwhile, Jack and Grace take the day off of work to go to the movies.  While at the supermarket getting snacks, they run into Vince and his co-worker, and assume Vince is cheating on Will.', 22, '2005-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 14, 'Partners', 'Will is up for partner at his law firm. His boss, Margot, invites the candidates for partner to a dinner at her house, where she will ultimately make the final decision. Will, who is worried that Vince will ruin his chances of getting the promotion, is reluctant to bring him as his date. Grace also attends Margot''s dinner party under the pretense that Margot has set her up on a blind date. Once there, Grace realizes the blind date is with Margot''s husband. Elsewhere, Rosario becomes sick and Karen refuses to believe she is really ill.', 22, '2005-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 15, 'Bully Woolley', 'Scott Woolley, under the alias Haley Joel Osment, hires Grace to design his new restaurant under the condition Grace fires Karen from her design firm. Grace later tells Karen about the incident and they realize the man that hired Grace is really Woolley. Grace and Karen decide to trap him in his lie. Meanwhile, Jack takes Will out for a boys'' night to get his mind off of Vince, but ends up abandoning Will at the club. In an effort to make it up to Will, Jack takes him out to lunch and tries to ignore everyone around him except, Will. The task becomes incredibly difficult once Jack realizes Patti Lupone has entered the restaurant.', 22, '2005-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 16, 'Dance Cards & Greeting Cards', 'Grace tries to ignore the greeting card holiday but romantic urges eventually send her into the arms of the enemy -- none other than Nick, a hunky greeting card writer. In a dramatic change of events, Karen''s former nemesis Scott Wooley tries to win her heart by showering her with gifts but Karen''s eyes are on larger things -- her new overweight internet date. Elsewhere, after dancing with a lesbian couple Will and Jack find comfort in each other''s arms for the Valentine''s Day spotlight dance.', 22, '2005-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 17, 'The Birds and the Bees', 'Grace drags Will along to keep her in check during her first date with Nick only to leave a heated Will at his table for one. Meanwhile, Karen hatches a wild plan to get Jack a date with Aaron, the neighborhood bird enthusiast, only to ruffle some feathers when things don''t quite go as planned.', 22, '2005-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 18, 'The Fabulous Baker Boy', 'Will agrees to fire Karen''s pastry chef until the baker cooks up a delectable love triangle for the three of them. Meanwhile, Grace enlists Jack''s help in launching boyfriend Nick''s career as a television writer but Jack shatters Nick''s script-writing dreams.', 22, '2005-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 19, 'Sour Balls', 'Jack convinces Will that they need a change of scenery and should buy a vacation home in an up-and-coming gay community. After purchasing a new pad, the duo find out that it is not quite the gay getaway they had imagined. Instead, Jack landed the two in a blue collar town. Meanwhile, Ellen asks Grace to babysit her kids for a day, but when Karen wants to get involved, Grace epresses her doubts about Karen''s ability to take care of children.', 22, '2005-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 20, 'The Blonde Leading The Blind', 'When Will convinces Grace to see his therapist, Dr. Georgia Keller, he becomes increasingly jealous when the two women form an instant friendship. Grace and Will begin to compete fiercely for Georgia''s attention -- and a place in her upcoming book. Meanwhile, glasses bring Karen to a whole new level of clarity and she becomes overly critical of Jack.', 22, '2005-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 21, 'It''s a Dad, Dad, Dad, Dad World', 'When Grace convinces Karen to accompany her to her father Martin''s birthday bash, the situation turns awkward when it is just the three of them. Struggling to gain the attention of her seemingly aloof father, Grace tags along with him to the golf range in hopes of scoring some quality bonding time. Meanwhile, Karen keeps herself entertained with Martin''s buddy, Burt. Meanwhile, excited about the date that Jack has arranged for him, Will discovers the true meaning of the phrase ""blind date.""', 22, '2005-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 22, 'From Queer To Eternity', 'After a near-death experience in a Jean Boutique, Grace decides to write her will and enlists Will''s legal expertise to make sure she''s fair when bequeathing her money.  Grace visits Will''s mother to find out how much Will plans to leave her and is shocked by what she finds.  Thanks to Grace, Will also takes a look at his life and decides it''s time to make a life altering career move.  Meanwhile, Jack and Karen find an imposter teaching Jack''s ""McFarland Method Of Acting.""  Realizing he needs new material to get back into teaching, Jack changes his method to win back his students.', 22, '2005-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 23, 'Friends With Benefits', 'Having quit his job at the law firm, Will turns to a career in writing where he catches the eye of Malcolm, who claims to have high-profile connections -- but when his writing career fails, Malcolm has another job offer for Will. Meanwhile, Tom, an old flame from college, returns to ask Grace to design a hotel that he and his wife just bought -- only to discover that there are still romantic feelings between the two of them. Jack struggles to produce his latest show for OutTV, but spoiled child star Randall fails to embody Jack''s vision. Under threat of a lawsuit, Karen is forced to publicly apologize to Beverly for an embarrassing rumor.', 22, '2005-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 7), 24, 'Kiss & Tell', 'After his first day, Will becomes suspicious of his new job -- especially when he finds himself in an empty office with no co-workers, a German shepherd and a Russian-speaking thug.', 22, '2005-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')), 8, 'Season 8', 'The final season of Will & Grace is here! But dry your eyes and turn off the Gloria Gaynor as there’s still bucket loads of laughs to enjoy before your favourite foursome ride off into the sunset.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 1, 'Alive and Schticking', 'Grace contemplates having an affair with a married man. Elsewhere, Jack begins new career as a host of his new talk show "Jack Talk." Will gets some advice from Malcolm and tries to hide from Karen the fact that Stan is alive.', 22, '2005-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 2, 'I Second That Emotion', 'Karen feels rattled by Stan''s return and Will steps in to help her. Meanwhile Grace is labeled homophobic after her comments on Jack''s talk show are misconstrued by gay men from all over New York.', 22, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 3, 'The Old Man and the Sea', 'When Jack learns that Will never learned how to swim, Jack insists that he teach Will how. Meanwhile, Karen sets Grace up on a blind date with one of Malcolm’s friends.', 22, '2005-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 4, 'Steams Like Old Times', 'Karen is finally forced to come to terms with her feelings for her presumed-dead husband when Jack surprisingly tells her he thinks she belongs with Stanley, not Malcolm.', 22, '2005-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 5, 'The Hole Truth', 'The day before Will’s charity auction and carnival, Jack meets and begins dating Baby Glenn, who is still riding his fifteen minutes of fame from when he got trapped in a hole for three days in the eighties.', 22, '2005-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 6, 'Love is in the Airplane', 'While en route to London, Will and Grace spot Grace’s ex-husband Leo on their flight. Will charms a pair of gay flight attendants, who also happen to be dating, so he can smuggle Grace into first class to talk to Leo.', 22, '2005-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 7, 'Birds of a Feather Boa', 'When Jack decides on a whim to move, Will is excited at the thought of helping him look for a place. While attending Beverley''s wife''s memorial “celebration,” Karen and Grace experience a wardrobe malfunction, which they must try to conceal.', 22, '2005-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 8, 'Swish Out of Water', 'Grace finds it impossible to put up with her mother Bobbi’s constant nitpicking, so Jack takes it upon himself to help her because, according to him, no one knows how to be a good daughter better than a gay son.', 22, '2005-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 9, 'A Little Christmas Queer', 'While spending the holidays at Will’s mother Marilyn’s house, Grace gets cozy with Will’s brother and old flame Sam. Sam’s adopted daughter finds a fan in Karen, who is intrigued by the little girl.', 22, '2005-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 10, 'Von Trapped', 'The "Sound of Music Sing-Along" has come to town and no one is more excited than Grace. She plans for her and Will to attend the musical in character-like style by dressing up in costumes.', 22, '2006-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 11, 'Bathroom Humor', 'Karen celebrates her birthday with some of New York''s crème de la crème, but the festivities turn sour when she ends up crammed in the bathroom with Grace, Will and Jack, who have all embarrassed themselves at the party.', 22, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 12, 'Forbidden Fruit', 'Grace is concerned and confused when Will so adamantly insists that she turn down her job offer from his former boss Margot, who has asked Grace to redecorate the law firm.', 22, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 13, 'Cop to It', 'Will and Grace dread a dinner date with married friends Rob and Ellen who likely called the meeting to announce Ellen is pregnant yet again, but when the couple reveals that they are separated and loving it, Grace gets depressed.', 22, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 14, 'I Love L. Gay', 'Will, Karen, and a star struck Grace travel to Los Angeles to support Jack as he accepts a HAPI award for Best Local Cable Gay Talk Show Host. Coincidently, Will runs into James while in LA, but to his surprise James is Canadian and in jeopardy of being deported.', 22, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 15, 'The Definition of Marriage', 'The big day has finally arrived - Grace and James are getting ready for their green card wedding. To Grace''s dismay, Karen takes it upon herself to ignore her wish for a low-key wedding ceremony and decides to arrange including hiring Hall & Oates.', 22, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 16, 'Grace Expectations', 'A nervous but optimistic Grace decides it''s finally time to tell Leo she is pregnant with his child, but when she finally works up enough courage to actually meet her ex-husband she receives some unexpected news.', 22, '2006-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 17, 'Cowboys and Iranians', 'An ecstatic Jack coerces Will into coming out with him to a gay cowboy bar to meet his new boyfriend Travis. Will soon discovers that Travis is not as perfect as he seems and steps up to defend Jack''s honor, which eventually leads to a bar fight.', 22, '2006-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 18, 'Buy, Buy Baby', 'After a large corporation takes over OutTV, Jack''s talk show "JackTalk" is completely revamped. An immediate change comes when the new conservative owners hire Amber-Louise as "JackTalk''s" new co-host.', 22, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 19, 'Blanket Apology', 'After losing his job as the host of "JackTalk," Jack vows never to return to acting. An unrelenting Karen, however, will not let Jack give up on his passion and decides to do whatever it takes to get Jack to an audition.', 22, '2006-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 20, 'The Mourning Son', 'Friends and family gather for the funeral of Will''s father. At the reception everyone shares with Will fond last memories of his father, while Will''s last memory of his father is not as pleasant. Marilyn helps him realize the changes needed in his life.', 22, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 21, 'Partners ''n'' Crime', 'Will and Grace begin attending childbirth classes in preparation for the baby, but as Will and Vince take another chance at their relationship, Grace starts to doubt whether Will is up for raising a child with her.', 22, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 22, 'Whatever Happened to Baby Gin?', 'Just as Will and Grace are settling into the idea of raising the baby together, Will''s boyfriend Vince surprises him with an announcement that will ultimately lead Will to choose between his commitment to Grace and his relationship with Vince.', 22, '2006-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 23, 'The Finale (1)', 'The culmination of eight seasons ends tonight with a one-hour series finale - will Will and Grace raise a child together and find ultimate happiness? Will Jack find anyone that loves him as much as he loves himself? Will Karen find true happiness with the absence of Stan? All these questions and more will be answered as this groundbreaking series concludes eight amazing seasons.', 22, '2006-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0157246')) AND numero_temporada = 8), 24, 'The Finale (2)', 'The culmination of eight seasons ends tonight with a one-hour series finale - will Will and Grace raise a child together and find ultimate happiness? Will Jack find anyone that loves him as much as he loves himself? Will Karen find true happiness with the absence of Stan? All these questions and more will be answered as this groundbreaking series concludes eight amazing seasons.', 22, '2006-05-18');
