INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0159206', 'Sex and the City', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0455078'), 'SERIE', 'Four career women navigate life in NYC. Carrie writes about relationships, Charlotte runs an art gallery, Miranda practices law, and Samantha excels in PR. Each brings unique views on love, work, and friendship.', '1998-01-01', 'https://m.media-amazon.com/images/M/MV5BNjMwNzczODYtZDQwZC00NjJmLTg5ZWYtYzUxZjViYmNhN2IyXkEyXkFqcGc@._V1_.jpg');
