INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')), 1, 'Season 1', 'Thirtysomething writer Carrie Bradshaw''s experiences on the New York singles scene serve as the inspiration for her newspaper column: ''Sex and the City''. The struggles of finding a partner are seen through the eyes of Carrie and her best friends Samantha, Charlotte, and Miranda.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 1, 'Sex and the City', 'At a birthday party for thirty-something Miranda, Carrie and her friends vow to stop worrying about finding the "perfect" male and start having sex "like men". Carrie has several encounters with tycoon heartthrob Mr. Big. Miranda starts dating nice-guy Skipper Johnston. Charlotte goes on a date with Capote Duncan, but when she tells him she won''t have sex with him, he goes to a club and winds up going home with Samantha.', 25, '1998-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 2, 'Models and Mortals', 'After Miranda and Skipper bump into each other at the convenience store, they sleep together for the first time. Carrie interviews Barkley, a modelizer who videotapes his conquests. Derek, a male model client of Stanford Blatch, spends the night with Carrie after a fashion show, although they don''t sleep together. Samantha chases Barkley while at a fashion show, in order to be taped.', 25, '1998-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 3, 'Bay of Married Pigs', 'Carrie is invited to go up to their Hamptons beach house by Patience and Peter, but in the morning she bumps into Peter in the hall without his underwear on. Some friends introduce her to Sean, ''The Marrying Guy''; when she can''t keep up on his quick-march to commitment, he ditches her for commitment-phile Charlotte. Miranda''s colleague from work, Jeff, introduces her to a lesbian, Sid, at a baseball game, and they are invited to her senior partner''s dinner party.', 22, '1998-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 4, 'Valley of the Twenty-Something Guys', 'Mr. Big and Carrie continue to bump into each other during social events, which leads them to try to organize their first "drink thing". On a night out, Carrie meets twenty-something Sam for a fling, which turns out not to be so glamorous in the light of day.', 22, '1998-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 5, 'The Power of Female Sex', 'Carrie bumps into international party-girl Amalita and her latest man Carlo in a shoe store, who in turn introduce her to a French Architect, Gilles. He leaves Carrie $1,000 on the nightstand after a one-night stand. Charlotte meets Neville Morgan, a renowned artist, who paints pictures of her vagina for his latest exhibition.', 23, '1998-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 6, 'Secret Sex', 'Carrie and Mr. Big have their first official "date", but Carrie suspects Mr. Big is keeping her secret from his social circle. Miranda dates a man from her gym class, but she discovers a spanking video in Ted''s apartment.', 22, '1998-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 7, 'The Monogamists', 'Carrie and Mr. Big begin dating on a regular basis, but she learns after bumping into him that he is dating other women. Samantha begins to look for an apartment to purchase.', 23, '1998-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 8, 'Three''s a Crowd', 'Charlotte is dating Jack, who wants a threesome, but she is unsure. Carrie discovers that Mr. Big has an ex-wife, and feels threatened. Samantha is seeing a married man; when his wife finds out, she proposes a threesome to keep their marriage together. Miranda feels unattractive and looks for affirmation that she isn''t.', 23, '1998-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 9, 'The Turtle and the Hare', 'Mr. Big tells Carrie he''s never going to marry again, which unsettles her. Miranda introduces the friends to the Rabbit, a mechanical aid, and Charlotte becomes addicted. Stanford Blatch proposes to Carrie as a cover, so he can inherit his part of the family fortune.', 22, '1998-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 10, 'The Baby Shower', 'The four women attend a baby shower for their one-time wild-child friend Laney in her new buttoned-down Connecticut-suburb environs. Carrie is forced to think about motherhood by her late period. Miranda regards the other guests as part of the cult of The Motherhood. Still-single Charlotte fears her dreams of being a wife and mother are slipping away. Samantha throws a "no-baby shower" in response to the one the four women attended.', 22, '1998-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 11, 'The Drought', 'Carrie''s relationship with Mr. Big has been going on for long enough that it is becoming less physical, especially after she farts in bed. Charlotte is dating a man who isn''t interested in sex anymore thanks to the side-effects of Prozac. Samantha discovers that not having sex can be erotic. Miranda realizes that she hasn''t had sex for months.', 25, '1998-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 1), 12, 'Oh Come All Ye Faithful', 'After being introduced as "a friend" to his mother, Carrie realizes her relationship with Mr. Big is one-sided and breaks up with him. Miranda dates an up-and-coming playwright who is also an up-tight Catholic. Samantha falls in love with a perfect man, but he doesn''t measure up to her requirements. Charlotte gets psychic readings to see if she''ll ever marry.', 27, '1998-08-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')), 2, 'Season 2', 'Carrie begins dating again in the wake of her break-up with Mr. Big while Samantha, Charlotte and Miranda continue to provide fodder for her column.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 1, 'Take Me Out to the Ballgame', 'Carrie meets "the new Yankee," Joe, at a baseball game, all the while preparing for her first post-breakup encounter with Big. Miranda gets fed up with the girls always talking about men. Samantha gets frustrated with James'' "deficiencies". Charlotte dates a guy named Paul Ericson who has a tendency to adjust his package... a lot.', 24, '1999-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 2, 'The Awful Truth', 'Carrie accidentally suggests that her friend Susan Sharon leave her domineering, violent husband. Miranda builds up the courage to talk dirty in bed. Charlotte tries to replace the perfect man with the perfect dog. Samantha gets dragged to couples'' therapy with James and tries to avoid talking about her real problem with their sex life.', 24, '1999-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 3, 'The Freak Show', 'Carrie turns freakish herself after dating a string of freaky guys and freaks out the very normal Ben when trying to discover his secret freakiness. Miranda dates "Manhattan Guy," a guy who hasn''t left Manhattan in ten years. Charlotte dates the renowned "Mr. Pussy" and tries to make a real relationship out of it. Samantha decides to get plastic surgery and freaks out during the consult.', 24, '1999-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 4, 'They Shoot Single People, Don''t They?', 'Single and fabulous Carrie gets a horrible photo taken for the cover story of New York Magazine: Single and Fabulous...?. Miranda fakes orgasms with her current boyfriend. Charlotte starts dating her handyman. Samantha dates a club owner, who calls them a "we" right away.', 25, '1999-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 5, 'Four Women and a Funeral', 'Carrie starts seeing Mr. Big again. Miranda buys her own apartment on the Upper West Side. Charlotte meets a recent widower at a cemetery. Samantha''s actions with a married man gets her in trouble with the New York high-society "ladies who lunch" and only a titanic star can help her out.', 26, '1999-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 6, 'The Cheating Curve', 'Carrie starts to "officially" date Mr. Big again. Miranda dates a guy who insists on watching porn while they have sex. Fed up with cheating men, Charlotte spends time with her new friends, the "Power Lesbians." Samantha starts dating her gym instructor who "brands" her with a lightning bolt.', 24, '1999-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 7, 'The Chicken Dance', 'Carrie gets fed up with Big''s inability to pay attention to her. Miranda inadvertently sets her interior designer up with a long-distance would-be boyfriend, and they marry after only four weeks. Charlotte has a "warp speed" relationship with a guy she meets at the wedding. Samantha is upset when she experiences "déjà-screw": sleeping with a guy she previously did fifteen years ago.', 24, '1999-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 8, 'The Man, the Myth, the Viagra', 'A frustrated Carrie tries to get Big to make time to meet the girls. Miranda meets Steve Brady, a cute bartender who wants to be more than a one-night stand. Samantha dates an incredibly wealthy man in his seventies with a sumptuous lifestyle and a pocket full of Viagra.', 24, '1999-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 9, 'Old Dogs, New Dicks', 'Carrie tries to get Big to stop checking out other women when they''re together. Miranda and Steve''s opposite schedules become a problem. Samantha runs into an old hockey-player boyfriend who is now a blonde drag queen named Samantha. Charlotte is turned-off when she dates a man who has not been circumcised; Carrie points out to Charlotte that 85% of men are not circumcised while Samantha claims to prefer uncircumcised men.', 25, '1999-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 10, 'The Caste System', 'Carrie gets fed up with high society while at an Upper East Side party with Big. Miranda and Steve have an argument over money and social status. Charlotte meets Wiley Ford, the movie star and joins his entourage. Samantha dates a wealthy real-estate developer with a Southeast Asian live-in servant who has her master wrapped around her little finger.', 26, '1999-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 11, 'Evolution', 'Carrie tries to leave her mark at Big''s place by leaving some personal items behind. Miranda finds out that one of her ovaries has stopped producing eggs. Charlotte dates Stefan, a pastry chef who she mistakenly thought was gay but is, in his own words, a "gay straight man". Samantha tries to get revenge on Dominic, her ex who broke her heart.', 25, '1999-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 12, 'La Douleur Exquise!', 'Carrie is horrified when Big casually tells her he''s moving to Paris for seven months. Miranda dates a man who only wants to have sex in places where they might get caught. Charlotte meets Buster, a high-end shoe salesman with a serious foot fetish. Samantha introduces the girls to a hot new S&M restaurant.', 27, '1999-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 13, 'Games People Play', 'Carrie starts going to therapy after obsessing about Big for too long. Offended by the diagnosis of dating men who are wrong for her, she dates cute fellow-patient Seth (Jon Bon Jovi)...a guy who loses interest in women after sleeping with them. Miranda plays "peek-a-boo" with her cute across-the-airshaft neighbor. Samantha dates a sports fanatic whose mood depends on who won the game that night.', 20, '1999-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 14, 'The Fuck Buddy', 'Carrie tries to make a relationship with her "fuck buddy." Miranda dates an abusive, condescending lawyer. Charlotte becomes a free-wheeling dater and double-books dates with two guys on the same night. Samantha overhears the couple moaning next door, and decides to outdo them.', 24, '1999-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 15, 'Shortcomings', 'Carrie dates an author who has a premature ejaculation problem and finds that she regrets having to break-up... with his perfect family. Child-phobic Miranda dates a divorced father who has a son. Charlotte''s brother Wesley stays with her after his wife leaves him. Samantha gives Charlotte''s brother what he really needs: sex.', 25, '1999-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 16, 'Was It Good for You?', 'Carrie dates a recovering alcoholic who becomes obsessed with her. Charlotte is determined to learn how to have good sex after her latest partner falls asleep on her, and drags the girls to a Tantric sex class. Samantha gets an offer to have a threesome with two curious gay friends.', 26, '1999-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 17, 'Twenty-Something Girls vs. Thirty-Something Women', 'Carrie unexpectedly runs into Mr. Big—and his new 27-year-old girlfriend, Natasha—at a Hamptons party. Miranda tries in vain to have some mature fun in the Hamptons. Charlotte pretends to be in her twenties so she can date a cute 26-year-old. Samantha''s 25-year-old ex-assistant is hired to throw a big Hamptons party using her Rolodex for the guest list.', 24, '1999-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 2), 18, 'Ex and the City', 'After learning of Big''s engagement, a freaked-out Carrie tries to cope with the ramifications. Miranda sleeps with Steve for the first time after their breakup. Charlotte tries to overcome her fear of horseback riding. Samantha dates a guy who''s "Mr. Too-Big", determined to overcome his over-endowment.', 31, '1999-10-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 1, 'Where There''s Smoke...', 'Carrie meets a politician at a FDNY calendar benefit in Staten Island. Miranda gets help from Steve after she undergoes LASIK eye surgery. Tired of waiting for a fairytale romance, Charlotte begins aggressively searching for a "Prince Charming" to marry. Samantha dates the pinup-boy fireman she met at the benefit.', 28, '2000-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 2, 'Politically Erect', 'Carrie continues dating her politician beau, but finds his sexual fetish to be anything but ''golden''. Miranda doesn''t know how to respond when Steve asks her to "go steady". Charlotte throws a "used date" party to find a new man. Samantha dates a short man who shops at the Boy''s Department in Bloomingdale''s.', 27, '2000-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 3, 'Attack of the 5''10" Woman', 'Carrie must confront her past with Big when she runs into Natasha, Big''s wife. Miranda hires Magda, an Eastern European maid with very traditional values. Charlotte deals with some of her body issues at a spa. Samantha gets banned from Helena Rubinstein when she gets physical with a masseur.', 25, '2000-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 4, 'Boy, Girl, Boy, Girl...', 'Carrie dates a twenty-something man who''s openly bisexual. Miranda deals with personal issues when Steve proposes moving in with her. Charlotte poses as a drag king for an artist at her gallery. Samantha butts heads with her new twenty-something male assistant.', 27, '2000-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 5, 'No Ifs, Ands, or Butts', 'Carrie''s smoking becomes a problem when she goes on her first date with Aidan Shaw. Miranda makes more time for Steve in her life. Charlotte dates the worst kisser she''s ever met. Samantha dates a black man whose sister is racist.', 30, '2000-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 6, 'Are We Sluts?', 'Carrie wants to sleep with Aidan, but he''s reluctant to rush into a physical relationship. Miranda discovers she has chlamydia and has to inform her past sexual partners. Charlotte''s new boyfriend calls her names during sex. Samantha''s neighbors disapprove of her sex life after a late-night visitor lets in a burglar.', 22, '2000-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 7, 'Drama Queens', 'Carrie obsesses about her perfect relationship when Aidan suggests she meet his parents. Miranda enjoys her intimate life with Steve. Charlotte gets upset when a married friend won''t set her up with his bachelor buddy. Samantha tries Viagra while sleeping with a doctor.', 25, '2000-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 8, 'The Big Time', 'Carrie runs into Big who confesses that he misses her and can''t stop thinking about her. Miranda gets annoyed with Steve''s childish habits when he suggests they have a baby together. Charlotte falls in love with Trey after only a few weeks of dating and is convinced he''s "The One". Samantha believes she''s hit menopause when her period is a week late.', 28, '2000-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 9, 'Easy Come, Easy Go', 'Big tells Carrie that he''s leaving his wife. Miranda deals with her breakup and Steve moving out of the apartment. After meeting the MacDougal family matriarch, Charlotte maneuvers Trey into making an "alrighty" proposal. Samantha is upset when dating a hot guy with "funky spunk".', 30, '2000-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 10, 'All or Nothing', 'Carrie feels guilty and wants to quit her affair with Big. Miranda enjoys phone sex with a co-worker from Chicago. Charlotte negotiates the terms of her prenuptial agreement with Trey''s mother, Bunny. After celebrating her move to the new apartment in the exclusive Meatpacking District, Samantha''s bout of the ''flu gives her a pessimistic outlook on life.', 29, '2000-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 11, 'Running with Scissors', 'Carrie continues her affair with Big, and tells Samantha after a girly night and Miranda after a drink on their cocktail night. Charlotte finds out by accident, when she bumps into them on the street together. No longer meeting in hotels where nobody knows them in to avoid getting caught,Natasha comes home early from the Hamptons catching Carrie in Big''s apartment. She chases Carrie out, falls down the stairs and cracks her tooth. Carrie takes her to A&E where she tells Big "they are so over they need a new word for over". Miranda tries continually to get Carrie to end her affair. Charlotte hires stylist Anthony Marentino to help her find the perfect wedding dress. Samantha meets the "male version of herself", but he refuses to sleep with her because she hasn''t had an HIV test.', 28, '2000-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 12, 'Don''t Ask, Don''t Tell', 'Carrie struggles to find the right time to tell Aidan about her affair. Miranda tells a guy she''s a stewardess in hopes of getting a date. Charlotte has her dream wedding and marries Trey MacDougal—even after attempted late-night tryst reveals Trey''s serious shortcomings. Cunning linguist Samantha sleeps with Trey''s Scottish cousin, despite being unable to understand him.', 28, '2000-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 13, 'Escape from New York', 'Carrie meets with actor/producer Matthew McConaughey in LA to talk about optioning her columns to make a movie. Miranda wrestles with the level of open sexuality in Los Angeles. Charlotte uses the Internet to deal with Trey''s impotence problem. Samantha meets a dildo model.', 26, '2000-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 14, 'Sex and Another City', 'Carrie meets a publicity agent for celebrities who shows her the perks of the rich and famous in LA. Miranda meets an old friend from New York who''s lost his East-Coast edge. Charlotte comes to LA after getting fed up with Trey''s sexual problems. Samantha meets her idol, Hugh Hefner, and gets the girls invited to a party at the Playboy Mansion.', 27, '2000-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 15, 'Hot Child in the City', 'Carrie dates a hunky comic-book store owner who still lives with his parents. Miranda gets braces. Charlotte is shocked when she catches the supposedly impotent Trey masturbating. Samantha''s latest client is Jenny Brier (Kat Dennings), a 13-year-old Jewish-American princess, planning her million-dollar bat mitzvah.', 29, '2000-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 16, 'Frenemies', 'Carrie teaches at The Learning Annex—only her course on "How to Find Love" is as successful as her own love life. Miranda dates one of Carrie''s ex-boyfriends (known as Mr. A--hole), whom she meets at the funeral of a dead never-met blind-date. Charlotte gets sexually frustrated with her sex life with Trey. Samantha gets in a fight with Charlotte about her attitude toward sex.', 27, '2000-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 17, 'What Goes Around Comes Around', 'Carrie decides, after a broad-daylight Manolo mugging, that she must clear herself of bad karma and decides she needs to talk with Natasha about her affair with Big. Miranda dates a gorgeous NYPD detective and becomes self-conscious about her own looks. Unhappily-married Charlotte struggles with her lust for a hunky gardener; she and Trey decide to separate. Samantha meets another Sam Jones, who turns out to be an NYU student and desperate virgin.', 28, '2000-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 3), 18, 'Cock a Doodle Do!', 'Carrie meets with Big for the first time since his marriage ended. Miranda gets frustrated when she thinks the Chinese take-out girl mocks her stay-at-home lifestyle. Charlotte moves back into her old apartment and gets an up-lifting visit from Trey in the middle of the night. Samantha feuds with the raucous transsexual prostitutes who conduct business outside her apartment at two in the morning.', 34, '2000-10-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 1, 'The Agony and the ''Ex''-tacy', 'Carrie thinks about men and the future when no one shows up for her birthday party. Miranda confronts her married friends about her single life. Charlotte tries to deal with her separation from Trey. Samantha tries to seduce a celibate monk. The girls make a pact that they are soulmates, and men are nice guys to have fun with.', 29, '2001-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 2, 'The Real Me', 'Carrie is reluctant when asked to be a celebrity model in a high-profile fashion show. Miranda gets a lesson in confidence when a buff guy at the gym asks her out. Charlotte works up the courage to look at her "depressed" vagina in a hand-mirror. Samantha immortalizes herself by having nude photographs taken.', 29, '2001-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 3, 'Defining Moments', 'Carrie meets a jazz musician while on a pseudo-date with Big. Miranda tries to get more comfortable using the bathroom in front of her date. Charlotte is dismayed that Trey only wants to have sex in places where they can get caught. Samantha meets Maria, a lesbian painter, at Charlotte''s gallery, and questions her own sexuality.', 28, '2001-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 4, 'What''s Sex Got to Do with It?', 'Carrie continues to date Ray King, the jazzman, but finds he has an ADHD problem. Miranda substitutes chocolate for sex. Charlotte deals with Trey getting a little too overconfident in bed. Samantha tells the girls she''s in a relationship with Maria and is now a lesbian.', 26, '2001-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 5, 'Ghost Town', 'Carrie gets an invitation to the opening of Steve—and Aidan''s—new bar, Scout. Miranda thinks she has a ghost in her apartment. Charlotte butts heads with Trey''s mother, Bunny, when redecorating their apartment. Samantha''s girlfriend Maria gets fed up with the many, many men from Samantha''s past.', 28, '2001-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 6, 'Baby, Talk Is Cheap', 'Carrie realizes she wants to get back together with Aidan. Miranda gets a surprise when she sleeps with "marathon man". Charlotte and Trey decide to start trying to have a baby. Samantha uses fake nipples and attracts a man who uses "baby-talk" during sex.', 28, '2001-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 7, 'Time and Punishment', 'Big calls Carrie—while she''s having sex with Aidan. Miranda throws her neck out after fighting with Charlotte. Charlotte decides to leave the gallery to pursue motherhood full-time. Samantha''s latest guy tells her she needs to shave below the belt.', 28, '2001-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 8, 'My Motherboard, My Self', 'Carrie''s laptop crashes, and when Aidan tries to help, she pushes him away. Miranda''s mother dies unexpectantly, but at the funeral, her family is more upset by her single status. Charlotte becomes the "Martha Stewart of funerals". Samantha "loses" her orgasm.', 28, '2001-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 9, 'Sex and the Country', 'Carrie is dragged to Aidan''s country home in Suffern, New York. Charlotte visits the MacDougal "compound" in Connecticut. Miranda yells at Steve when he tells her he has testicular cancer but has no clue about his condition. Samantha gets annoyed when her dates keep asking her what she''s doing "next weekend".', 27, '2001-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 10, 'Belles of the Balls', 'Carrie invites Big up to Aidan''s country home to talk. Charlotte tries to discuss her and Trey''s infertility problems. Miranda sleeps with Steve to cheer him up after he has one of his testicles removed. Samantha tries to get the PR position for hotelier Richard Wright.', 29, '2001-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 11, 'Coulda, Woulda, Shoulda', 'Carrie is reluctant to tell Aidan that she had an abortion when she was 22. Charlotte discovers she only has a fifteen percent chance of getting pregnant naturally. Miranda finds out she''s pregnant by Steve, and debates whether or not to keep the baby. Samantha gets Lucy Liu as a client and tries to use the relationship to her advantage.', 28, '2001-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 12, 'Just Say Yes', 'Aidan proposes to Carrie. Charlotte discusses adoption with Trey, but hits a wall when Bunny finds out that the baby could be Chinese. Miranda tells Steve she''s having his baby. Samantha starts sleeping with her boss, Richard Wright.', 28, '2001-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 13, 'The Good Fight', 'Carrie and Aidan have a huge fight over the clutter in her apartment after Aidan moves in. Charlotte and Trey have a huge fight when he brings home a cardboard baby as a gag gift. Miranda goes on a date despite being pregnant. Samantha finally gives in to Richard''s romantic overtures.', 27, '2002-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 14, 'All That Glitters', 'Carrie finds time away from stay-at-home boy Aidan with a gay Aussie shoe distributor at the exclusive Bungalow 8. Charlotte and Trey separate permanently after their apartment is photographed in House & Garden. Miranda accidentally outs her co-worker after he tells the office gossip that she''s pregnant. Samantha tells Richard she loves him while high on ecstasy.', 28, '2002-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 15, 'Change of a Dress', 'Carrie freaks out about marrying Aidan. Charlotte takes tap classes, and has a meltdown during the "Tea for Two" number when she realizes she isn''t ready to be alone after her divorce. Miranda must feign excitement when she learns her baby''s sex. Samantha finds out Richard is seeing other women, and pushes him to be monogamous with her.', 28, '2002-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 16, 'Ring a Ding Ding', 'Carrie is forced to buy her apartment back from Aidan or move out. Mr. Big writes her a check as a loan, but she doesn''t know whether she should accept it. Charlotte doesn''t know what to do with her engagement ring. Miranda has to refurbish her wardrobe after gaining pregnancy weight. Samantha tries to trick Richard into saying he loves her.', 28, '2002-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 17, 'A ''Vogue'' Idea', 'Carrie starts working at Vogue and finds out from her acerbic editor that she doesn''t have a Vogue idea about relationships. Charlotte throws a baby shower for Miranda, but Miranda gets fed up with her after she tries to make the shower too cutesy. Richard asks Samantha for a threesome with a 21-year-old for his birthday.', 28, '2002-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 4), 18, 'I Heart NY', 'Carrie is shocked to find out that Big is moving to Napa, California and plans to give him a New York send-off. Charlotte begins dating another recent divorcé. Miranda prepares for the new baby as her delivery date nears. Samantha suspects Richard may be cheating on her.', 30, '2002-02-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 1, 'Anchors Away', 'Carrie realizes her relationship with New York City is as dysfunctional as is her relationship with men. Charlotte decides she needs to distance herself from her former life as "Mrs. MacDougal". Miranda tries to adjust to her new life with her baby, Brady Hobbes. Samantha gets phone calls from Richard begging her to take him back.', 28, '2002-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 2, 'Unoriginal Sin', 'Carrie gets an offer from a publisher who wants to make a book out of her column. Charlotte takes a self-help seminar and takes affirmations to try to find love again. Miranda agrees to have Brady baptized, and chooses Carrie as the godmother. Samantha takes Richard back, despite the girls advising against it.', 28, '2002-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 3, 'Luck Be an Old Lady', 'Carrie desperately tries to get everyone together for Charlotte''s "thirty-faux" birthday. Charlotte doesn''t want to turn 36 because she feels she''s getting old. Miranda goes to Atlantic City with the girls, feeling self-conscious about her weight. Samantha is paranoid that Richard is cheating with the entire female hotel staff.', 28, '2002-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 4, 'Cover Girl', 'Carrie works with publicist Samantha to try to get the perfect look for her book cover. Charlotte starts reading self-help books. Miranda goes to Weight Watchers to lose her baby weight. Samantha gets upset when she feels the girls are judging her outrageous sex life.', 27, '2002-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 5, 'Plus One Is the Loneliest Number', 'Carrie invites Jack Berger to her book opening party, which turns out to be a huge event. Charlotte butts heads with Bunny MacDougal. Miranda''s single life and her life with Brady conflict. Samantha gets an impulse-buy chemical peel that goes awry.', 28, '2002-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 6, 'Critical Condition', 'Carrie deals with her past with Aidan when she runs into Nina Katz, who had dated Aidan after he and Carrie split up. Charlotte gets a tough lawyer to go up against Bunny in a fight to keep her apartment. Miranda has no one to turn to when she needs help taking care of Brady. Samantha tries to return a spent vibrator, then spends some of her free time on Miranda.', 28, '2002-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 7, 'The Big Journey', 'Carrie goes to San Francisco to promote her book and visit Big. Charlotte sleeps with her unappealing (to her) divorce lawyer, Harry Goldenblatt. Samantha accompanies Carrie to California, looking for a good time.', 28, '2002-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 5), 8, 'I Love a Charade', 'The girls attend the Hamptons wedding of an over-the-hill socialite and a lounge singer whom they all thought was gay. Carrie encounters Jack Berger again. Charlotte goes public with her relationship with Harry. Miranda gets more comfortable with the baby and with her role as a mother. Samantha throws a huge party at Richard Wright''s Hamptons house.', 28, '2002-09-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 1, 'To Market, to Market', 'While nervously anticipating her first date with Berger, Carrie runs into Aidan for the first time since their breakup, and is surprised by how far he''s moved on. Miranda realizes she''s in love with Steve—only to hear he has a new girlfriend. Charlotte struggles with Harry''s assertion that he can only marry a Jew. Samantha sleeps with a stockbroker who gives insider tips while inside her.', 28, '2003-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 2, 'Great Sexpectations', 'Carrie and Berger''s dates sizzle in the restaurants, but fizzle in the bedroom. Miranda becomes addicted to a British show featuring an interracial romance. A tenacious Charlotte pursues converting to Judaism for Harry. Samantha and the girls go to a cold-food restaurant where Samantha meets hot waiter Jerry Jerrod (Smith).', 27, '2003-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 3, 'The Perfect Present', 'After Berger flips out and flips off his ex-girlfriend''s answer-phone message, Carrie tries to not think about her influence on his life. Miranda finds condoms in Brady''s diaper bag and gets upset with Steve. Newly converted Charlotte mourns the loss of Christmas. An on-the-job quickie with Samantha gets Smith fired from a catering gig.', 27, '2003-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 4, 'Pick-A-Little, Talk-A-Little', 'Carrie feels bad for criticizing a minor point in Berger''s book. When Berger teaches Miranda how to tell that a guy is "not that into her", she feels the need to spread the word to other women. Charlotte cooks her first Shabbat dinner for Harry. Samantha and Jerry act out all their sexual fantasies.', 27, '2003-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 5, 'Lights, Camera, Relationship!', 'Carrie receives a big royalty check for her book sales, which upsets Berger— whose book deal has been dropped. A lovesick Miranda helps Steve bake cupcakes—for his new girlfriend. Charlotte is reluctant to date after Harry leaves her. Samantha takes charge of the PR for Jerry''s struggling play where he gives a striking—and nude—performance.', 27, '2003-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 6, 'Hop, Skip, and a Week', 'Berger tells Carrie that he needs a break from their relationship. Workaholic Miranda has to cut her hours at work in order to spend more time with Brady. Women from the synagogue compete to set Charlotte up with their single sons, but she runs into Harry at a singles night, and they realize they are meant to be together. PR Manager Samantha changes Jerry''s name to Smith and gets him great exposure on a revealing billboard in Times Square.', 27, '2003-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 7, 'The Post-It Always Sticks Twice', 'Berger returns, but then breaks up with Carrie with a Post-It note. Miranda finally loses all her baby-weight and rediscovers her "skinny jeans". Charlotte decides she wants a small wedding. Samantha is reluctant to be labeled as Smith''s "girlfriend".', 27, '2003-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 8, 'The Catch', 'Carrie finds that a casual fling with Harry''s best man is a pain in the neck. Miranda is scared of meeting Steve''s new girlfriend. After Harry accidentally sees Charlotte in her wedding dress before the big day, she is convinced their wedding is cursed. Self-sufficient Samantha struggles without a man around.', 27, '2003-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 9, 'A Woman''s Right to Shoes', 'Carrie''s shoes are stolen at a party; the hostess (Tatum O''Neal) not only refuses to apologize, but shames her for her extravagant footwear — and lifestyle choices. Miranda gets chicken pox, and she flirts with the handsome black doctor who just moved into her building. Charlotte must adjust to living with Harry (and his tea bags) in her pristine apartment. Children misbehaving in nice restaurants annoy Samantha.', 27, '2003-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 10, 'Boy, Interrupted', 'Carrie''s high-school sweetheart visits her in New York—on his way to a mental asylum in Connecticut. Miranda develops a crush on her attractive neighbor Robert, the team doctor for the Knicks. In order to get into an exclusive pool at the SoHo House, Samantha pretends to be a member — and British. Geri Halliwell and David Duchovny guest-star.', 27, '2003-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 11, 'The Domino Effect', 'Carrie shows strange signs of distress when Big needs heart surgery. Miranda gets close to her new boyfriend Robert, but is reluctant to introduce him to Steve. Reproductively-challenged Charlotte tries acupuncture in order to get pregnant. Samantha refuses to hold hands with Smith.', 26, '2003-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 12, 'One', 'Carrie meets fifty-something Russian artist, Aleksandr Petrovsky (Mikhail Baryshnikov), at a gallery. Miranda''s boyfriend Robert says "I love you" but she cannot say it back. Charlotte is delighted to discover she''s pregnant — then devastated when she miscarries. After finding one gray hair down under, Samantha dyes her pubic hair with shocking results.', 32, '2003-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 13, 'Let There Be Light', 'Carrie begins to feel attached to Aleksandr but cannot ignore his womanizing past. Together again, Steve moves into Miranda''s apartment and finds it hard to avoid her angry ex-boyfriend Robert. Charlotte tries to forget her miscarriage by volunteering. Samantha accompanies Smith to an industry party hosted by Richard Wright.', 29, '2004-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 14, 'The Ick Factor', 'Carrie finds Aleksandr''s old-world romantic attention a little overwhelming. Miranda prepares for her non-traditional wedding to Steve. Charlotte and Harry''s romantic French dinner leads to a night of the runs. Samantha considers a breast augmentation and receives some unexpected news.', 27, '2004-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 15, 'Catch-38', 'Carrie discovers that Aleksandr has decided to not have any more children. Miranda and Steve go on their honeymoon to a remote inn in upstate New York. Baby Brady sees Charlotte and Harry having sex. Samantha uses Smith''s fame to get her an appointment with a well-known female oncologist.', 28, '2004-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 16, 'Out of the Frying Pan', 'Carrie gets upset at Aleksandr for being inconsiderate of her feelings about Samantha''s cancer. When her new family outgrows her apartment, Miranda considers buying a house in Brooklyn. Charlotte receives a dog and names her Elizabeth Taylor. Samantha''s hair falls out as a result of chemotherapy.', 28, '2004-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 17, 'The Cold War', 'Aleksandr refuses to talk about his work or introduce Carrie to his friends. Miranda adjusts to life in Brooklyn. Charlotte decides to enter Elizabeth Taylor in a dog show. Samantha makes a sex tape with Smith after a tabloid reports that she''s his "fag hag".', 28, '2004-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 18, 'Splat!', 'Petrovsky hosts a dinner party for Carrie''s inner circle, and makes a shocking announcement. Later, the death of an old party friend (Kristen Johnston) helps Carrie reach a big decision.', 28, '2004-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 19, 'An American Girl in Paris (Part Une)', 'Before joining the Russian in Paris, Carrie has one last dinner in New York with Samantha, Charlotte and Miranda. However, life in the City of Light doesn''t live up to her expectations. After being told-off by Carrie before the dinner, Big goes to girls for advice; they tell him to go to Paris and find their girl.', 31, '2004-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0159206')) AND numero_temporada = 6), 20, 'An American Girl in Paris (Part Deux)', 'Carrie is desperately lonely in Paris as Petrovsky is spending so much time on his new exhibit. The chemo treatments are killing Samantha''s sex drive. Miranda must take care of Steve''s mother after she has a stroke. Charlotte and Harry try to adopt a baby. Big finds Carrie in Paris and says the words she''s been waiting six years to hear.', 43, '2004-02-22');
