INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0158552', 'Charmed', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0470971'), 'SERIE', 'Three sisters discover that they are descendants of a line of good female witches and are destined to fight against the forces of evil.', '1998-01-01', 'https://m.media-amazon.com/images/M/MV5BOGU5MGU3NmYtOTIzNi00NTg2LTkxMWUtNjQwMzhiNWQ5NzQ0XkEyXkFqcGc@._V1_.jpg');
