INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 1, 'Season 1', 'The three Halliwell sisters discover that they are descendents of a line of female witches. Each has a special ability (stopping time, moving objects, seeing the future), and they can also combine their abilities into the "Power of Three" to fight demons, warlocks, and other evils.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 1, 'Something Wicca This Way Comes', 'Three sisters reunite after the death of their beloved grandmother, and learn they have inherited much more than the family manor.', 42, '1998-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 2, 'I''ve Got You Under My Skin', 'Piper has trouble dealing with her powers and fears what might happen if she enters a church. Meanwhile, Phoebe meets a photographer who sucks the life out of young women to keep himself young, and Prue faces relationship complications with Andy when she gets a job at an auction house.', 42, '1998-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 3, 'Thank You for Not Morphing', 'The sisters'' father returns after a 20 year absence, and the new neighbors aren''t what they seem.', 42, '1998-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 4, 'Dead Man Dating', 'Piper falls for the ghost of a recently murdered man who needs her help. Meanwhile, Phoebe works as a psychic to help others and make money for Prue''s birthday present, and Prue discovers a devastating betrayal.', 42, '1998-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 5, 'Dream Sorcerer', 'Prue finds her sleep disturbed by strange visions in which she''s taunted by a man. Meanwhile Phoebe and Piper cast a spell to attract men, but it turns out too strong, and they can barely escape their myriad of admirers.', 42, '1998-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 6, 'The Wedding from Hell', 'The sisters must face Hecate, a powerful demon goddess, who is preying upon a woman, her son & his fiancee, and attempting to conceive a full demon child.', 42, '1998-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 7, 'The Fourth Sister', 'A troubled teenage girl befriends Phoebe with the hopes of joining the Halliwells, but she''s been lured to the dark powers of witchcraft by a sorceress. Meanwhile, Prue tries to find some alone time with Andy and Phoebe and Piper vie for the attention of Leo.', 42, '1998-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 8, 'The Truth Is Out There... and It Hurts', 'Acting on Phoebe''s premonitions, the sisters race to stop a mysterious killer from striking again. Meanwhile, Prue finds a truth spell and uses it to find out what Andy''s reaction to her being a witch would be.', 42, '1998-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 9, 'The Witch Is Back', 'A warlock from the past is released from his curse and tries to steal the sisters'' powers with the help of Rex and Hannah, but the sisters resurrect their ancestor to combat him. Meanwhile, Piper works up her courage to ask Leo out and Andy gets frustrated by Prue''s continued involvement with bizarre police investigations.', 42, '1998-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 10, 'Wicca Envy', 'When Prue is framed for stealing from the auction house and arrested, it is revealed that her boss, Rex, is a warlock. It''s up to Piper and Phoebe to prove Prue''s innocence and vanquish Rex before its too late.', 44, '1999-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 11, 'Feats of Clay', 'When Phoebe''s ex-boyfriend comes to town he brings trouble in the form of a stolen Egyptian urn which carries a mortal curse. Meanwhile, Prue tries to save the auction house from bankruptcy, and Piper''s witchcraft backfires.', 42, '1999-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 12, 'The Wendigo', 'When Piper is attacked by a vicious beast, Andy goes on a stakeout with an FBI agent who is hunting the creature. Meanwhile, Prue hires Phoebe to work at the auction house, but Phoebe''s vision of a terrible car crash immediately sends her off on a mission to find a long-lost child.', 42, '1999-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 13, 'From Fear to Eternity', 'The sisters'' mother warns them about a demon from the underworld who comes around every 1300 years on Friday the 13th to literally scare witches to death and feed on their fear. Meanwhile, Phoebe has misgivings about her expected duties at her new job and Piper is frustrated by her superstition about relationships started on Friday the 13th.', 42, '1999-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 14, 'Secrets and Guys', 'Prue helps a young witch who has been kidnapped, and renews her own faith in having children. Meanwhile, Phoebe finds out that Leo is hiding an important secret that threatens his relationship with Piper.', 42, '1999-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 15, 'Is There A Woogy In The House?', 'Phoebe''s fear of the Woogyman amuses Prue and Piper, until an earthquake releases a shadow demon. Phoebe under the control of the Woogyman tries to kill Prue and Piper, who must find a way to rescue Phoebe and get rid of the Woogyman.', 42, '1999-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 16, 'Which Prue Is It, Anyway?', 'When Phoebe has a premonition of Prue being stabbed to death, it coincides with a warrior coming to town in order to kill the eldest sibling witch as he did to the sisters'' great-great-great-aunt.', 42, '1999-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 17, 'That ''70s Episode', 'A powerful warlock shows up claiming that he made a pact with the sisters'' mother in which he spared her life in exchange for the girls'' powers. Fleeing him, the three sisters go back in time to the 1970s when their mother was still alive and they try to prevent the pact.', 42, '1999-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 18, 'When Bad Warlocks Go Good', 'Prue attempts to help a young man, who desires to become a priest in order to avoid fulfilling his destiny as a warlock of the Evil Charmed Ones. Meanwhile, Phoebe tries to get Piper to stop shying away from a date with Josh.', 42, '1999-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 19, 'Out of Sight', 'When Prue witnesses and tries to stop a kidnapping of a young boy in the park, a reporter sees her using her powers. He tries to blackmail her to get a sensational story for his newspaper. Phoebe and Piper attempt to learn more about the demons who stole the child and come across a similar kidnapping that happened 20 years ago. Meanwhile, Andy gets involved in the kidnapping case and finally confirms his suspicions about Prue''s powers.', 44, '1999-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 20, 'The Power of Two', 'After Piper leaves on a business trip, it doesn''t take long for some friction to appear between Prue and Phoebe. However, they set their differences aside when they run into a ghost of a serial killer who''s looking for a revenge against people who sentenced him with a death penalty. Meanwhile, the many unsolved crime cases are finally starting to catch up with Andy when people from Internal Affairs take an interest in them.', 45, '1999-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 21, 'Love Hurts', 'The sisters are about to go on a relaxing weekend getaway to Cabo, when a mortally wounded Leo shows up and asks for their help to save a young woman who''s being chased by a darklighter. Desperate to save Leo, Piper casts a spell that swaps their powers, however in doing so, she accidentally swaps the powers of Prue and Phoebe as well. Meanwhile, pressed by an Internal Affairs investigation Andy decides to leave his job in order to protect Prue''s secret from being exposed.', 45, '1999-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 1), 22, 'Déjà Vu All Over Again', 'A warlock repeatedly attempts to kill the Charmed Ones, with a help from demon Tempus turning back time after each failure so that he can try again. However, because of the endless time loop and her power of premonition, Phoebe experiences a number of strong cases of déjà vu and is able to figure out that there are evil forces after them.', 44, '1999-05-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 2, 'Season 2', 'The sisters continue to balance their personal lives with their magic as they begin to gain more control over their powers. The sisters also find themselves traveling to both the past and the future throughout the season, in addition to facing their own family history when they are forced to destroy the demon that was responsible for their mother''s death.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 1, 'Witch Trial', 'On their first anniversary of becoming witches, the sisters face a cloven-hoofed demon called Abraxas, that steals the Book of Shadows and undoes the spells they''ve cast.', 44, '1999-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 2, 'Morality Bites', 'When Phoebe has a vision of herself being burnt to death, the sisters travel ten years into the future to learn what happened. Only to discover that she used her powers to kill someone, causing a local DA to begin modern day witch trials as a platform for political office. Meanwhile, Prue and Piper try to save Phoebe, but they both are surprised and somewhat disappointed to learn how their lives turned out.', 45, '1999-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 3, 'The Painted World', 'Prue is sucked into another dimension and finds herself trapped inside a painting with a dangerous warlock. Meanwhile, after damaging Prue''s car, Phoebe tries to get the funds for the repair.', 44, '1999-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 4, 'The Devil''s Music', 'Leo lures the manager of Dishwalla to P3, aware that the manager has made a pact with a demon that grants him fame and fortune in exchange for innocent souls. Meanwhile, Darryl soon becomes involved when he investigates the mysterious disappearance of young women from many of Dishwalla''s past concerts, and suspects that more will disappear when they next perform.', 43, '1999-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 5, 'She''s a Man, Baby, a Man!', 'The sisters discover that Phoebe is psychically linked, through her powers, to a man-killing demon known as a ''Succubus.'' In order to lure the Succubus to the sisters, Prue casts a spell, which turns her into a man. Meanwhile, Piper discovers from a video tape at the dating service that their new neighbour, Dan, is interested in her.', 44, '1999-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 6, 'That Old Black Magic', 'The sisters must find and train the ''Chosen One'' to vanquish a powerful evil witch that could destroy the Charmed Ones.', 44, '1999-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 7, 'They''re Everywhere', 'A band of knowledge-stealing warlocks hunt down a young man who uncovered the location of one of the greatest sources of power in the world. Meanwhile, Prue has her hands full with Jack Sheridan.', 43, '1999-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 8, 'P3 H2O', 'The sisters must face and destroy the demon that was responsible for their mother''s death 20 years ago. In the process, they uncover a chapter of their mother''s life that they never knew about - one that disturbingly mirrors Piper''s current relationship with Leo.', 45, '1999-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 9, 'Ms. Hellfire', 'An assassination attempt on the sisters'' lives forces Prue to go undercover as the woman who tried to kill them, known as Ms. Hellfire. While undercover, she becomes romantically involved with the man who hired the original Ms. Hellfire.', 44, '2000-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 10, 'Heartbreak City', 'A demon named Drasi steals Cupid''s ring, which brings couples together. Now Cupid must convince the Halliwells to help him get it back before Drasi breaks all of the relationships, thus killing Cupid.', 43, '2000-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 11, 'Reckless Abandon', 'The sisters must find a way to vanquish a ghost who is intent on killing all of the men in a family line, including the last male, a baby named Matthew.', 44, '2000-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 12, 'Awakened', 'When Piper contracts a life-threatening tropical virus that leaves her in intensive care, and to try to save her life, Prue and Phoebe cast an ''awakening'' spell. However, since the spell was used for personal gain, the sisters can no longer sleep, and Piper''s sickness spreads into an epidemic as a direct consequence. Also, Prue quits her job at Buckland''s and Phoebe enrolls in university.', 44, '2000-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 13, 'Animal Pragmatism', 'After a group of lonely mortal women at a University cast a spell that turns three animals into men and they start wreaking havoc on the town, the Halliwell sisters need to act fast to stop them. Also, Prue has a hard time adjusting to life being unemployed.', 44, '2000-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 14, 'Pardon My Past', 'Phoebe experiences flashes of one of her past lives when she and her sisters were cousins in the 1920s. However, in this past life, Phoebe was evil and power mad and a curse was bestowed upon her that could affect future Phoebe''s life.', 45, '2000-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 15, 'Give Me a Sign', 'After Prue''s former crush, Bane, is broken out of jail, he seeks her help for defeating a powerful demon by... kidnapping her. Meanwhile, Phoebe tries to help Piper choose between Dan and Leo by casting a spell, but the results are rather unexpected.', 44, '2000-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 16, 'Murphy''s Luck', 'After Prue prevents a woman from committing suicide, a Darklighter puts a curse on her that throws her into a depression that could cost her life.', 43, '2000-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 17, 'How to Make a Quilt Out of Americans', 'A group of three elderly witches, one of them close friends of the Halliwells'' grandmother, summon a demon to restore their youth. However, in return, the demon wants the powers of the Charmed Ones.', 43, '2000-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 18, 'Chick Flick', 'A warlock brings characters to life from old B-grade horror movies in an attempt to kill the Charmed Ones.', 42, '2000-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 19, 'Ex Libris', 'The sisters must find a demon responsible for the murder of one of Phoebe''s classmates. Meanwhile, Dan discovers that Leo was previously married, and decides to take matters into his own hands, while Prue attempts to help a man who is looking for a witness to his daughter''s murder.', 42, '2000-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 20, 'Astral Monkey', 'The doctor that treated Piper when she was critically ill discovers, and gains, the Haliwells'' powers. After being twisted by the magic now within him, he goes on a sadistic organ-harvesting spree, targeting criminals in the streets.', 42, '2000-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 21, 'Apocalypse Not', 'When a vanquishing spell goes awry while the Halliwells try to destroy the 4 Horsemen of the Apocalypse, Prue and one of the Horsemen become trapped in a vortex. Piper and Phoebe enlist the help of the three remaining Horsemen to free Prue and the fourth Horseman before the vortex closes, and both are killed.', 42, '2000-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 2), 22, 'Be Careful What You Witch For', 'A Genie, employed by a Dragon Warlock to steal the Halliwells'' powers, offers to grant each sister one wish for whatever they most desire.', 42, '2000-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 3, 'Season 3', 'The third season of Charmed sees many dramatic changes in the sisters'' lives. As Cole/Belthazor moves his way into The Charmed Ones'' lives, he becomes conflicted between his duty toward The Triad and his love for Phoebe.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 1, 'The Honeymoon''s Over', 'While Piper and Leo are away, Prue and Phoebe must face a series of demons known as Guardians, who protect mortal murderers in exchange for the souls of innocents. After saving Darryl from a Guardian, Prue and Phoebe must testify in court, where they stumble upon an evil conspiracy. Meanwhile, Phoebe falls in love with the new district attorney, Cole Turner.', 42, '2000-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 2, 'Magic Hour', 'The sisters must find a way to break a curse which turns a man into an Owl by day and his girlfriend into a Wolf by night. Meanwhile, Prue discovers a way to hold Piper and Leo''s wedding without ''The Powers That Be'' finding out.', 42, '2000-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 3, 'Once Upon a Time', 'With Piper growing more concerned that Leo will never return, Prue and Phoebe try to save a little girl and a fairy princess from evil Trolls. When Prue and Phoebe need Piper''s help, her concern with Leo causes a spell to backfire, placing the girl in danger.', 42, '2000-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 4, 'All Halliwell''s Eve', 'On Halloween, the sisters are pulled back in time to the 1600''s to save a witch and her soon-to-be-born child from the hands of an evil witch who wants to raise the child evil. The sisters later discover that this situation may have more personal implications than they first imagined.', 42, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 5, 'Sight Unseen', 'Prue becomes increasingly paranoid over attacks from the Triad, and the mysterious threat Belthazor poses. After the house is robbed, Prue is convinced the Triad is launching an attack, when the real culprit is more mortal than all three sisters realise.', 42, '2000-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 6, 'Primrose Empath', 'Prue begins experiencing the powers of an empath, thanks to a warlock, but she soons loses control. Meanwhile, Phoebe''s relationship with Cole becomes turbulent when he tells her he doesn''t want to see her anymore.', 42, '2000-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 7, 'Power Outage', 'In an attempt to destroy the Charmed Ones, Cole enlists the help of Andras, a demon who magnifies anger into rage. Meanwhile, when the sisters lose their magic after using their powers against each other, they are left defenseless against attacks from the Triad and Belthazor.', 42, '2000-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 8, 'Sleuthing with the Enemy', 'When the sisters discover that Cole is Belthazor, Phoebe must make one of the toughest decisions of her life: either vanquish her boyfriend or keep one of the most dangerous demons known to exist alive.', 42, '2000-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 9, 'Coyote Piper', 'Prue & Phoebe have their hands full when Piper is possessed by the spirit of an evil witch, on the day of her high school reunion.', 42, '2001-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 10, 'We All Scream for Ice Cream', 'The sisters trace a mysterious Ice Cream Van who abducts children, but the evil may not be who they initially suspect. Meanwhile, the girls'' dad Victor comes for a visit.', 42, '2001-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 11, 'Blinded by the Whitelighter', 'The sisters must stop a warlock from executing his plan to steal specific powers from witches in his attempt to kill every whitelighter in the world.', 42, '2001-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 12, 'Wrestling with Demons', 'When Prue discovers that her ex-boyfriend is being led down the path to becoming a demon, the sisters must risk their lives in an underworld wrestling ring to save his soul.', 42, '2001-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 13, 'Bride and Gloom', 'When a shapeshifting warlock tricks Prue into a shot-gun wedding in order to steal the Book of Shadows, Phoebe and Piper are lured to the dark side and begin to enjoy their new evil powers.', 42, '2001-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 14, 'The Good, the Bad, and the Cursed', 'When Phoebe feels the pain of an injured American-Indian ghost she sees in a deserted town, Prue travels back in time to the mid-1800s to save the man, and Phoebe, from death at the hands of a local thug.', 42, '2001-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 15, 'Just Harried', 'On the day of Piper''s marriage to Leo, Prue''s Astrally Projected-self adopts an uninhibited, wild personality that threatens to ruin the wedding and place Prue in jail for Murder.', 42, '2001-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 16, 'Death Takes a Halliwell', 'Prue, growing weary of her battles to save innocents and in fighting off the Angel of Death, is forced to turn her back on a dying soul, and must come to grips with her feelings towards fate and the death of her mother.', 42, '2001-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 17, 'Pre-Witched', 'While the sisters must deal with the possibility of being separated as the newlyweds plan to move out on their own, they recall a time before they knew they were the Charmed Ones, when the girls were coming to grips with the death of Grams and Phoebe''s departure to New York.', 42, '2001-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 18, 'Sin Francisco', 'A demon turns people into the embodiment of each of the deadly sins, including the Charmed Ones and Leo.', 42, '2001-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 19, 'The Demon Who Came in from the Cold', 'Cole poses as Belthazar to infiltrate an internet organization run by evil, that plans on controlling the world''s information flow on the internet. Meanwhile, the sisters must vanquish the warlock posing as the company''s manager without exposing Cole''s role in the situation.', 42, '2001-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 20, 'Exit Strategy', 'The evil Brotherhood plots to sabotage Cole''s relationship with Phoebe in an attempt to turn him back to evil. Meanwhile, Piper''s power develops with some explosive results.', 42, '2001-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 21, 'Look Who''s Barking', 'Phoebe has a premonition of a murderous banshee while adding on to the Belthazar section of the Book of Shadows, thus causing her to think Cole is responsible. But when the sisters cast a spell it backfires and turns Prue into a dog, and when Prue gets hit by a car, Phoebe''s remorse causes the banshee to attack her, turning her into a banshee.', 42, '2001-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 3), 22, 'All Hell Breaks Loose', 'When the Halliwell sisters are exposed as witches on nation-wide television, they form a pact with The Source to reverse time and undo the damage. However, in the process, one of the sisters makes the ultimate sacrifice, placing the Power of Three in mortal danger.', 42, '2001-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 4, 'Season 4', 'Season 4 brings big changes in the lives of the Halliwell sisters. As they face the loss of a sister, Paige Matthews arrives - half sister to the Halliwells. As Piper and Phoebe cope with the death of their sister, they learn to accept Paige and teach her the ways of witchcraft all while perfecting the use of their own growing powers.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 1, 'Charmed Again (1)', 'Mourning the death of Prue, Piper and Phoebe must now come to grips with the loss of their oldest sister, and the loss of the Power of Three. However, The Source discovers an unknown sister - the daughter of Patty and her whitelighter Sam, who had been kept hidden, Paige, the now-youngest Halliwell can restore the Power of Three and reunite the sisters'' strength as witches.', 42, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 2, 'Charmed Again (2)', 'Mourning the death of Prue, Piper and Phoebe must now come to grips with the loss of their oldest sister, and the loss of the Power of Three. However, The Source discovers an unknown sister - the daughter of Patty and her whitelighter Sam, who had been kept hidden, Paige, the now-youngest Halliwell can restore the Power of Three and reunite the sisters'' strength as witches.', 42, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 3, 'Hell Hath No Fury', 'Paige takes the Book of Shadows into her work to cast spells which help her co-workers. Meanwhile, Piper, who is filled with anger over the death of Prue and the recent actions of Paige, is possessed by a member of a supernatural band of vigilantes known as the Furies.', 42, '2001-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 4, 'Enter the Demon', 'While making a potion, Paige accidentally switches bodies with Phoebe. Meanwhile, when an apprentice ninja kills his master, the sisters must find a way to vanquish him, while learning to control their switched powers.', 42, '2001-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 5, 'Size Matters', 'Piper, Phoebe and Paige are shrunk to a height of five inches when they walk into a trap set by a demon named Gamil.', 42, '2001-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 6, 'A Knight to Remember', 'Paige accidentally summons a medieval knight, who believes Paige is the love of his life. However, the knight is under the influence of an evil sorceress.', 42, '2001-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 7, 'Brain Drain', 'The Source sends Piper into a deep coma, where she perceives an alternate reality. Phoebe and Paige must find a way to return her to reality and save her from giving up her powers while she is delusional.', 42, '2001-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 8, 'Black as Cole', 'Cole must face his true demonic nature when he is faced with another demon who is mistaken as the murderer of local witches who belong to the same coven. Meanwhile, Cole proposes to Phoebe, and Piper and Leo consider their future involving children.', 42, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 9, 'Muse to My Ears', 'The Halliwell sisters must find a way to release Muses which have been abducted by a warlock who is attempting to build an evil faction in the absence of The Source.', 42, '2001-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 10, 'A Paige from the Past', 'With Leo as her guide, Paige goes back in time to her teen years, in an attempt to resolve her feelings about the accident that killed her parents. Meanwhile, Piper must prevent ghosts, who have inhabited Phoebe''s and Cole''s bodies, from fulfilling their mission.', 42, '2002-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 11, 'Trial by Magic', 'While Phoebe performs jury duty in a murder case, she is hit with a premonition about the real killer, and must convince the rest of the jury that the defendant is not guilty without exposing magic. Meanwhile, Piper, Paige and Leo try help Phoebe find the real murderer, but they stumble upon a gang of demons involved and they must solve the crime and keep Paige''s friend out of danger before Phoebe gets thrown off the jury.', 42, '2002-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 12, 'Lost and Bound', 'Wanting to protect a ten-year-old orphaned boy who is a firestarter, Piper and Leo try to hunt down the demon before he can deliver the kid to The Source. Meanwhile, Phoebe is given Gram''s wedding ring by Cole, but to their surprise the ring has been cursed to transform the wearer into a traditional 1950''s suburban housewife.', 42, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 13, 'Charmed and Dangerous', 'The Source breaks an age-old agreement between good and evil by stealing The Hollow, an ancient vapor which he uses to absorb Piper & Paige''s powers. Meanwhile, Phoebe must allow Cole to help them, despite her having a premonition involving Cole sacrificing his life to save her from evil, but there may be more to the premonition that Phoebe just can''t see.', 42, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 14, 'The Three Faces of Phoebe', 'Phoebe develops a case of cold feet over marrying Cole and casts a spell which brings a young innocent Phoebe and an old cynical Phoebe to the Manor to help her make a decision. Meanwhile, while Cole is horrified to find that The Source is now taking over his entire being, The Source''s chief rival, who believes The Source is dead, is convinced by The Seer to kill The Charmed Ones in order to earn the allegiance of the entire underworld.', 42, '2002-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 15, 'Marry-Go-Round', 'As Phoebe prepares for her wedding day, she is completely unaware that the Source has taken over Cole''s body, a plot that will likely ruin the big event. Meanwhile, when the Seer tells the Source that if he can marry Phoebe in the ""dark way"", it will insure that their future son will be the most powerful, evil being ever.', 42, '2002-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 16, 'The Fifth Halliwell', 'Amongst newlyweds, Phoebe & Cole and already-married, Leo & Piper, Paige begins like a fifth-wheel but she continues her suspicions about Cole. Meanwhile, the Source plots to impregnate Phoebe with his evil spawn.', 42, '2002-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 17, 'Saving Private Leo', 'When two ghosts from Leo''s past return to seek revenge, Leo faces his demons by submitting, causing Piper''s life to be threatened,leaving Paige to deal with the situation. Meanwhile, Cole tries to convince Phoebe they need a home of their own.', 42, '2002-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 18, 'Bite Me', 'A vampire queen tries to dethrone Cole as ruler of the Underworld and attempts to turn Paige against her sisters. Meanwhile, Phoebe begins to feel under the weather.', 42, '2002-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 19, 'We''re Off to See the Wizard', 'Phoebe tells Piper and Paige that she is pregnant, and that Cole is the father. Meanwhile, Piper and Paige team up with a wizard to stop the coronation of the new Source, unaware that it is Cole and Phoebe is soon to be his Queen of the Underworld.', 42, '2002-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 20, 'Long Live the Queen', 'Phoebe accepts her new role in Cole''s life, but she still sets out to save an innocent after she has a premonition and even seeks her sisters'' help in protecting the man. Meanwhile, Piper''s heart doesn''t seem to be in it as she prepares to defend her family against any new threats from the underworld.', 42, '2002-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 21, 'Womb Raider', 'The Seer plans to steal Phoebe''s unborn baby so she can raise the child to become the next Source and prevent the throne from passing on to another demon. Meanwhile, the baby begins to take over control of Phoebe''s body, which proves dangerous to Paige.', 42, '2002-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 4), 22, 'Witch Way Now?', 'When the Angel of Destiny offers the sisters a chance to relinquish their powers and lead normal lives as a reward for vanquishing the Source of All Evil, their decision is put on the back burner, while they try and avoid an FBI agent who has them under surveillance and deal with Cole''s calls for help, who is trapped in another realm, holding onto his love for Phoebe.', 42, '2002-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 5, 'Season 5', 'Season 5 ties up loose ends and brings in new characters. Piper deals with being a Charmed One while being pregnant. After the birth, and learning that she is the mother of a very important and powerful child, Piper must then face various demonic forces who intend to either kill or capture her son.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 1, 'A Witch''s Tail (1)', 'Piper, Phoebe and Paige come to the aid of Mylie, a Mermaid-turned-human, when she shows up looking for their help after a pact she made with an evil Sea Hag begins to go drastically wrong. Meanwhile, Phoebe attempts to divorce Cole, until he shows up claiming to want her back, Paige, attempts to juggle her new position as a full fledged Social Worker, as well as being a Charmed One, and Piper must protect her unborn baby, and face her fear of water.', 42, '2002-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 2, 'A Witch''s Tail (2)', 'Piper, Paige and Leo struggle to convince Phoebe, now a mermaid, to come back to her life as a Charmed One, when she decides to ""swim"" away from her problems with Cole. Meanwhile, Piper casts a spell to stop her panic attacks but instead of facing her fear, she suppresses it, endangering herself and her baby, when a sea Demon comes after her mermaid sister, Phoebe. In order to help Phoebe, Paige takes drastic measures and enlists the aid of Cole, and his newfound demonic powers.', 42, '2002-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 3, 'Happily Ever After', 'An evil witch traps the Halliwell sisters in distorted versions of classic fairy tales, where Phoebe attends a ball as Cinderella and meets Prince Charming, Paige has a taste of Snow White''s poisoned apple, and Piper encounters a big, bad wolf, as Little Red Riding Hood.', 42, '2002-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 4, 'Siren Song', 'Cole and Phoebe both fall under the spell of the Siren, who lures husbands to her and entrances their wives to follow with the intent to kill, leaving Piper and Paige to figure out how to save Phoebe. Piper, upset with Leo because he does not understand the challenges of being pregnant, and Leo, frustrated that Piper does not realize the demands of being a Whitelighter, have their personas switched magically by their unborn child.', 42, '2002-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 5, 'Witches in Tights', 'When a demon coerces a boy into turning him into an evil comic book villain so he can steal an Elder''s powers, the boy transforms The Charmed Ones into comic book heroes with superhuman strengths to prevent this from happening.', 42, '2002-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 6, 'The Eyes Have It', 'While seeking the advice of a fortune teller regarding her missing power of premonition, Phoebe discovers that there is a demon who has been stealing the eyes of Gypsies. Meanwhile, Piper wants to see a doctor about her baby, but Leo is concerned about the threat of exposure.', 42, '2002-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 7, 'Sympathy for the Demon', 'Barbas, the Demon of Fear, returns and tricks Paige into giving him Cole''s powers, and plots revenge on the Halliwell sisters by playing them against their darkest fears.', 42, '2002-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 8, 'A Witch in Time', 'When Phoebe must constantly save the life of her new boyfriend, a warlock shows up from the future, claiming that future Cole sent him in order to kill the boyfriend before Phoebe''s dies instead. However, present Cole cannot allow this and tries to help the sisters protect Miles, but when the warlock decides to work on his own agenda, by stealing the Book of Shadows, it results in the death of two of the Halliwell sisters. The survivor must decide whether going back to change the past is the right thing to do.', 42, '2002-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 9, 'Sam I Am', 'Paige gets to know the Whitelighter in her, when she meets her first charge, a man named Sam, unbeknownst to her is actually her real father. Meanwhile Cole tries every possible way to get himself vanquished by the Charmed Ones. Piper and Leo have problems in finding a magical creature that does the babysitting part, and things go bad to worse when they''re poisoned by a Darklighter, leaving Sam as the only one who can save them.', 42, '2002-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 10, 'Y Tu Mummy Tambien', 'Phoebe falls prey to Jeric, a demon in search of the perfect body to hold the spirit of Isis, his dead lover. To trap the spirit, Jeric mummifies Phoebe''s body. Meanwhile, Cole tries to save Phoebe by making a deal with the demon.', 42, '2003-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 11, 'The Importance of Being Phoebe', 'After kidnapping Phoebe, Cole sends a shapeshifter to assume Phoebe''s identity to help him manipulate Piper and Paige into giving him ownership of the Manor, allowing him access to the powerful Nexus located beneath the house. Meanwhile, Phoebe plans her escape, and Cole gets Paige arrested and ensures that Piper''s club fails to pass health inspections in order to keep them distracted.', 42, '2003-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 12, 'Centennial Charmed', 'In his twisted attempt to win Phoebe''s heart back, Cole casts a spell that alters reality, that eliminates Paige as a Halliwell and destroys the Power of Three. Meanwhile, Paige suddenly finds that her sisters have no knowledge of her existence and that past villians have come back to haunt them.', 42, '2003-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 13, 'House Call', 'Glen returns to Paige''s life with a big surprise - he is about to get married to a girl called Jessica. Meanwhile, the sisters summon a Witch Doctor whom they want to dispatch all the evil remnants that surround the Manor.', 42, '2003-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 14, 'Sand Francisco Dreamin''', 'A demon attacks The Charmed Ones with dream dust, causing their nightmares to come to life. Paige is harassed by an evil clown at a baby shower, Piper has an affair and Phoebe is chased by a maniac with a chainsaw. The sisters must use magic to put themselves to sleep to re-enter their nightmares and unmask the symbolic meaning of their dreams.', 42, '2003-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 15, 'The Day the Magic Died', 'Phoebe and Paige go to a summit meeting with the leaders of evil and discover that all magic - both good and bad - has disappeared enabling the leaders to steal Piper''s about-to-be-born baby and welcome the twice-blessed child into the kingdom of evil.', 42, '2003-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 16, 'Baby''s First Demon', 'The Charmed Ones must protect Piper''s son from two demons, but the baby has a few surprises of his own. Meanwhile, Paige goes undercover as a bounty hunter and Phoebe''s future with the newspaper is threatened by the new owner.', 42, '2003-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 17, 'Lucky Charmed', 'The Charmed Ones face a demon who has been killing Leprechauns and stealing their magic but when the Leprechauns endow the sisters with good luck, which enables Paige to gain material wealth, Phoebe to meet a man, and Piper to book a major star to play P3, plans backfire.', 42, '2003-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 18, 'Cat House', 'When Piper and Leo begin to have marital problems, Piper casts a spell to allow them to literally see their past together. However, the spell goes awry when Phoebe and Paige are sent back in time to relive Piper''s memories, and a warlock bent on destroying the Charmed Ones tags along for the ride.', 42, '2003-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 19, 'Nymphs Just Wanna Have Fun', 'When a demon attacks and kills one of the three nympths that protect a lake, the Charmed ones try to help. However, once the demon is destroyed, the nypmphs decide Paige should replace the fallen nymph, and they won''t take no for an answer.', 42, '2003-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 20, 'Sense and Sense Ability', 'In order to get close to baby Wyatt, the Crone steals one of the senses from each of The Charmed Ones, in an attempt to fool the child.', 42, '2003-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 21, 'Necromancing the Stone', 'When Grams comes to the manor for a Wiccan birthing ceremony, for Wyatt, the sisters find out that she has brought a memory from her past, a former lover who wants to kill the Charmed Ones and bring back the love they once shared. Meanwhile, Phoebe contemplates Jason''s invitation, even though it will take her away from her family, and Paige casts a truth spell to figure out if Nate can accept her being a witch.', 42, '2003-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 22, 'Oh My Goddess (1)', 'When the mythic Gods, the Titans, are released and kill all the elders, Leo is forced to take over. Meanwhile, a mysterious Whitelighter from the future guides the Charmed Ones when Leo gives the girls the ultimate power to vanquish the Titans, recreating them as Greek Goddesses, despite the risk that they will be seduced by their vast new powers.', 42, '2003-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 5), 23, 'Oh My Goddess (2)', 'Now all powerful Greek goddesses, the Charmed Ones must try to not be seduced by their new powers and stay focused on vanquishing the Titans before they destroy all the whitelighters. Meanwhile, Leo must decide whether to become an elder or stay with Piper & Wyatt.', 42, '2003-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 6, 'Season 6', 'The sixth season focuses on new characters as well as The Charmed Ones. Leo leaves on a quest making life hard for Piper as a single mother to Wyatt. Chris travels back in time and we learn about his true connection to the Halliwells.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 1, 'Valhalley of the Dolls (1)', 'Phoebe and Paige search for Leo after Paige accidentally causes a ""chipper"" Piper to have amnesia, but the sisters soon learn he is being held on the mythical Island of Valhalla. Unfortunately they have no idea that it''s because of Chris and his mysterious plans. Meanwhile, Phoebe discovers she is now an empath, and the dangers of this newfound power.', 42, '2003-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 2, 'Valhalley of the Dolls (2)', 'Phoebe and Paige search for Leo after Paige accidentally causes a ""chipper"" Piper to have amnesia, but the sisters soon learn he is being held on the mythical Island of Valhalla. Unfortunately they have no idea that it''s because of Chris and his mysterious plans. Meanwhile, Phoebe discovers she is now an empath, and the dangers of this newfound power.', 42, '2003-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 3, 'Forget Me...Not', 'The Cleaners kidnap Wyatt and erase his existence, after the child accidentally brings a dragon to life. When Piper, Phoebe and Paige regain their memories they relive the day Wyatt was kidnapped. Meanwhile, Paige is caught in the middle of sexual harassment troubles, Phoebe continues to cope with her newfound power of empathy, and Leo gives Chris a new assignment.', 42, '2003-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 4, 'The Power of Three Blondes', 'When three evil sisters magically steal the Charmed Ones'' identities and powers, Piper, Phoebe and Paige must convince Chris that they are the real Charmed Ones in order to get their lives back. Meanwhile, Piper realizes that Wyatt needs time with Leo, who continues on his quest to find out who put him on the Island of Valhalla.', 42, '2003-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 5, 'Love''s a Witch', 'While working for Grandma Callaway, Paige becomes the witness to a dangerous magical family feud going back for generations. The Halliwell sisters try to help Richard Montana end the feud before it escalates any further.', 42, '2003-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 6, 'My Three Witches', 'The Halliwell sisters attempt to escape magical realities where their secret desires come true, after Chris and the demon Gith try to teach them a lesson. Meanwhile, Leo demands that the Elders strip Chris of his Whitelighter status.', 42, '2003-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 7, 'Soul Survivor', 'Paige is forced to make a deal with a demon, in order to recover her boss''s soul. Meanwhile, Piper learns that Wyatt has been sabotaging her dates, Phoebe gets a new writing partner, and Chris and Leo accidentally travel back in time.', 42, '2003-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 8, 'Sword and the City', 'The Charmed Ones are called upon by The Lady of the Lake to help protect Excalibur, the legendary Sword in the Stone. Meanwhile, numerous magical beings arrive at the manor to try their hand at pulling the sword from the stone, but it''s Piper who finally pulls Excalibur out of the stone, causing a surprise figure to appear.', 42, '2003-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 9, 'Little Monsters', 'After vanquishing a Manticore demon, Piper, Phoebe and Paige become foster parents to its orphaned half-breed infant. But when Chris urges the girls to vanquish the child, they believe that if they raise the baby with love, they can change it''s destiny. Meanwhile, Phoebe surprises her boyfriend Jason when she blurts out her true feelings, and Paige gives Darryl a superpower.', 42, '2003-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 10, 'Chris-Crossed', 'Bianca, a woman from the future, arrives to take Chris''s powers, and Leo learns that she is actually part of an assassin family of witches. Meanwhile, Paige decides to move in with Richard, while Phoebe ponders joining Jason in Hong Kong.', 42, '2003-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 11, 'Witchstock', 'Paige finds herself transported back in time to an era of free love and free magic, where she discovers Grams, a peace-loving hippie, who is on a crusade to rid the world of evil through the magical power of love.', 42, '2004-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 12, 'Prince Charmed', 'After Piper vanquishes a demon from Wyatt''s room, she has an epiphany about the rest of her life concerning Wyatt. Unable to handle''s Piper''s revelation, Paige and Phoebe decide to remind Piper of the importance of love by conjuring up a ""Mr. Right"" as Piper''s birthday present. Meanwhile, Chris convinces the sisters to bind Wyatt''s powers, then demonic cult members kidnap the baby.', 42, '2004-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 13, 'Used Karma', 'Jason breaks up with Phoebe when he finally learns her and her sisters are really witches. Meanwhile, Richard attempts to free himself of his family''s karma, and Piper and Paige try to vanquish a group of Swarm Demons, the last on Chris'' list of the most significant threats to Wyatt.', 42, '2004-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 14, 'The Legend of Sleepy Halliwell', 'The Charmed Ones help out Leo''s mentor, Gideon, when he wants to find out who cast the spell of darkness over a magic school and conjured the headless horseman who has been beheading the teachers. Meanwhile, Phoebe goes on a vision quest.', 42, '2004-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 15, 'I Dream of Phoebe', 'When Phoebe frees a genie from a bottle, she soons finds that she must take the genie''s place. Meanwhile, anxious to put Leo and Piper back together, Chris uses Phoebe to make his wish come true, but she takes his instructions too literally.', 42, '2004-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 16, 'The Courtship of Wyatt''s Father', 'Gideon makes a deal with the Darklighters to get rid of Leo, but they accidentally send Leo and Piper to the Ghostly plane, leaving Phoebe and Paige to believe that they are both dead. Meanwhile, Chris begins to disappear and reveals that he must be conceived before the night is over or he will vanish forever.', 42, '2004-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 17, 'Hyde School Reunion', 'Phoebe accidentally casts a spell on herself that allows her wild teenage personality to take over, and teen Phoebe is eager to use her magic to her advantage. Meanwhile, Piper asks her father to find out why Chris is avoiding her.', 42, '2004-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 18, 'Spin City', 'When Piper is kidnapped and cocooned by the Spider Demon, and becomes Chris infected with the Demon''s venom, causing him to mutate into a spider, Paige, Phoebe and Leo try to rescue them. Meanwhile, Leo finally learns why Chris resents him.', 42, '2004-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 19, 'Crimes and Witch Demeanors', 'When Phoebe and Paige are caught on tape using their powers, the Cleaners, cover up the situation by implicating Darryl as a murderer. When the sisters try to help, they end up on trial instead. Meanwhile, Leo and Chris work together to help free the sisters and Darryl.', 42, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 20, 'A Wrong Day''s Journey into Right', 'With Piper away at magic school and Phoebe without her active powers, overworked Paige conjures Mr. Right for stress relief but, unknowingly, releases his evil twin, Mr. Wrong.', 42, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 21, 'Witch Wars', 'Under the pressure that the Halliwell sisters will discover his evil plot, Gideon conspires with two demons to make Piper, Phoebe and Paige part of ""Witch Wars"", a new demonic reality television show where demon contestants compete in a series of contests to hunt down the Charmed ones.', 42, '2004-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 22, 'It''s a Bad, Bad, Bad, Bad World (1)', 'Gideon creates a portal that puts Chris and Leo in a mirrored world where evil prevails, and Phoebe and Paige travel to the parallel universe to rescue them. Meanwhile, Piper gives birth to baby Chris.', 42, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 6), 23, 'It''s a Bad, Bad, Bad, Bad World (2)', 'Gideon creates a portal that puts Chris and Leo in a mirrored world where evil prevails, and Phoebe and Paige travel to the parallel universe to rescue them. Meanwhile, Piper gives birth to baby Chris.', 42, '2004-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 7, 'Season 7', 'The sisters question themselves after Gideon''s betrayal. Phoebe is such an emotional wreck that her boss lets her take a break and hires a ghost writer -- a man with whom she takes awhile to warm up to but eventually develops feelings for. Finally, darkness surrounds the sisters in the form Zankou, a demon who had been locked away by The Source.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 1, 'A Call to Arms', 'A grief-stricken Piper and Leo attend a Hindu wedding, where they inadvertently receive the powers of Hindu gods, and it''s up to Phoebe and Paige to keep them from consummating their love in order to save the universe.', 42, '2004-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 2, 'The Bare Witch Project', 'The Charmed Ones have their hands full, when thanks to a bored Magic School student, they must keep Lord Dyson from killing the infamous Lady Godiva before she can travel back in time and complete her famous ride. Meanwhile, Phoebe has reservations about Les being able to properly write an advice column for women.', 42, '2004-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 3, 'Cheaper by the Coven', 'When Paige and Phoebe summon Grams for Chris''s wiccaning, Grams puts a spell on the children to try to end their sibling rivalry, but instead it reverts the sisters back to bickering teenagers. Meanwhile Phoebe, still acting like a teenager, attends an award ceremony with Les, and Leo consults a demonic seer to find out who is behind the attack on Wyatt.', 42, '2004-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 4, 'Charrrmed!', 'When Paige encounters Captain Black Jack Cutting, an 18th century pirate in search of the Fountain of Youth, the curse on his life becomes her problem. Meanwhile, Leslie manipulates a contest in order to spend time with Phoebe, Leo fights with the creature that caused him to kill an Elder, and a mysterious federal agent comes to town to investigate the Halliwells.', 42, '2004-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 5, 'Styx Feet Under', 'In an attempt to stop a demon on a murderous rampage upon his human relatives, Paige casts a spell that inadvertently blocks all death, and it''s up to the Charmed Ones to make things right, when the Angel of Death wants the mess cleaned up. Meanwhile, Agent Brody reveals that he has been following the Halliwells longer than they thought, and Phoebe must deal with her feelings toward Leslie.', 42, '2004-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 6, 'Once in a Blue Moon', 'When a blue moon causes amok at the same time the girls are assigned a new whitelighter, thanks to the Elder''s suspicion of Leo, trouble brews. Meanwhile, Agent Brody tells Paige of a powerful new threat, and Phoebe & Leslie confess their true feelings for each other as Leslie prepares to leave.', 42, '2004-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 7, 'Someone to Witch Over Me', 'Agent Brody and Paige investigate when they discover that the demon Sarpedon is capturing innocents'' guardian angels and using them to protect himself from the new power. Meanwhile, Piper and Phoebe encourage Leo to go on a vision quest to face his demons.', 42, '2004-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 8, 'Charmed Noir', 'Paige and Agent Brody, are drawn into an unfinished novel that takes place in the 1930s, and they must elude the gangsters in pursuit of the famed Burmese falcon. Meanwhile, Phoebe, Piper and Leo work to re-write the novel to help get Paige and Brody out of it, before they''re killed.', 42, '2004-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 9, 'There''s Something About Leo', 'Piper learns Leo is an Avatar, when he confesses to her, despite the objections of the other Avatars, who believe Piper should find out on her own. Meanwhile, Phoebe and Paige ask Kyle for help, but his reaction proves disastrous.', 42, '2004-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 10, 'Witchness Protection', 'The Avatars enlist Leo to protect the Seer because she has information that could help them destroy the demons. Meanwhile, Brody reveals a secret to Paige, and Phoebe and Darryl continue to investigate Brody.', 42, '2004-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 11, 'Ordinary Witches', 'When Piper switches powers with Phoebe, to allow her to see the vision of the utopian world, Zankou interferes, and causes their powers to be transferred to innocent bystanders, who run amok. Meanwhile, Brody''s murderious desires prompt Paige to take him on a journey back to his childhood to learn the truth about his parents'' death.', 42, '2005-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 12, 'Extreme Makeover: World Edition', 'At the same time that the Avatars are planning to transform the world into their envisioned utopia, Zankou kidnaps Brody and is forced to cast a paranoia spell on the Halliwell sisters.', 42, '2005-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 13, 'Charmageddon', 'Leo discovers that the Charmed Ones'' conflict-free world comes with a higher price than anticipated, so he must join Zankou to stop the Avatars and reverse the change.', 42, '2005-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 14, 'Carpe Demon', 'When Paige tries to hire a new professor for the Magic School, one of the candidates, Drake, turns out to be an ex-demon who made a deal with a sorcerer to become human. Meanwhile, Leo faces the Elders.', 42, '2005-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 15, 'Show Ghouls', 'When Daryll''s friend is possessed by the spirit of an innocent killed in a fire in 1899, Phoebe and Drake transport themselves back in time to the caberet where it happened. However things go from bad to worse, when they find they cannot travel back to their own time. Meanwhile, Piper convinces Leo they need to take a family vacation.', 42, '2005-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 16, 'The Seven Year Witch', 'Piper is attacked by demons and winds up in a coma, and as she hovers between life and death, her spirit meets a familiar face who wants to help restore Phoebe''s faith in love. Phoebe, Drake & Paige rush to save Piper by attempting to locate Leo, who''s memory has been wiped clean by the Elders in attempt to allow him to choose his own destiny: be an Elder forever or choose Piper, and become mortal.', 42, '2005-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 17, 'Scry Hard', 'In an attempt to lure the sisters out of the manor, Zankou sends his underlings to attack Leo, in order for him to search the house for the Nexus and release the Shadow, the ultimate power. Meanwhile, in order to protect his parents Wyatt magically shrinks them and traps them inside a dollhouse, and Phoebe is left in charge of the newspaper.', 42, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 18, 'Little Box of Horrors', 'The sisters scramble to recover Pandora''s Box when it falls into the hands of a shapeshifting demon who intends to open it and fill the world with all of its sorrows. Meanwhile, Paige''s Whitelighter side rises to the surface, when she begins hearing calls from the Elders, and Leo and Piper clash over parenting issues - namely raising magical children.', 42, '2005-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 19, 'Freaky Phoebe', 'A powerful sorceress switches bodies with Phoebe, who ends up trapped in the Underworld. Meanwhile, Paige faces a big problem when her new charge refuses her help.', 42, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 20, 'Imaginary Fiends', 'Unbeknownst to the sisters, baby Wyatt''s new ""imaginary"" friend is actually a demon named Vicus who is trying to win Wyatt''s trust to turn him evil. Meanwhile, Piper casts a spell to be able to understand baby Wyatt, but inadvertently brings 25-year-old Wyatt back from the future.', 42, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 21, 'Death Becomes Them', 'When a person who was killed right in front of Phoebe comes back from the dead to blame her, she becomes guilt-ridden and vulnerable, creating an opportunity for Zankou to steal the Book of Shadows. Meanwhile, Paige has a new charge who knows nothing about magic, and Piper and Leo attempt to plan Chris''s first birthday party.', 42, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 7), 22, 'Something Wicca This Way Goes', 'When the sisters try to divert Zankou''s attention from the Nexus, he hatches a plan to absorb all their powers. But when the girls realize what Zankou is up to, they are forced with a life-altering decision: sacrifice their powers or their lives.', 42, '2005-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')), 8, 'Season 8', 'The sisters have to live under false identities to be free of demons. Each sister remains unhappy and eventually decides to return to their Charmed lives. Paige, however, begins helping a young witch named Billie, who eventually discovers the sisters'' magical secrets but agrees to keep them under wraps in exchange for witchcraft training.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 1, 'Still Charmed and Kicking', 'After being presumed dead, the Halliwell sisters begin their demon-free existence with new identities: Phoebe is overwhelmed with visions of her future husband; Paige begins hearing her whitelighter call, which draws her to a mysterious young witch; Piper attempts to deal with her financial situation, the club and her children. Meanwhile, a brash young demon decides that he wants the Halliwell manor as a trophy and plots to kill Victor to get to it.', 42, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 2, 'Malice in Wonderland', 'While attempting to take over the Underworld, a young demon plots to lure the Charmed Ones out of hiding, but when Billie stumbles onto his plot ,she becomes one of his victims instead.', 42, '2005-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 3, 'Run, Piper, Run', 'When Piper goes for a job interview with a corporate recruiter, she''s shocked to learn that the background check of her assumed identity was that of a woman wanted for murder. Meanwhile, Phoebe has a premonition of Dex being in an earthquake.', 42, '2005-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 4, 'Desperate Housewitches', 'Wyatt''s school play brings out the competitive nature in Piper when her hand-sewn costume & parenting abilities are criticized by another mother. However things go from bad to worse, because this Stepford-like mother is actually a demon in disguise bent on kidnapping Wyatt in a plot to resurrect the Source. Meanwhile, Paige spies Dex with another woman, and despite Phoebe''s objections, butts in.', 42, '2005-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 5, 'Rewitched', 'Billie jeopardizes the Charmed Ones'' new lives when Agent Murphy spots her using her powers to save an innocent. Meanwhile, Phoebe''s overnight trip with Dex comes to a surprising conclusion when Billie casts a spell to make her happy, a spell with unexpected consequences.', 42, '2005-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 6, 'Kill Billie: Vol. 1', 'Billie must deal with her painful childhood memories of her sister''s kidnapping, before she can vanquish her latest demon target, The Dogan. Meanwhile, the press are bombarding the sisters, since the announcement of their teaming with Homeland Security, so Paige goes to the Elders for help.', 42, '2005-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 7, 'The Lost Picture Show', 'Wanting to return to her old career as a social worker, Paige''s plans get put on hold, when her Whitelighter father, Sam, returns asking for her help with his charge. Meanwhile, Piper and Leo go to see a magical marriage counselor who thinks the best therapy is for them to walk a mile in each others'' shoes - literally.', 42, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 8, 'Battle of the Hexes', 'Agent Murphy gives the sisters their first Homeland Security case - searching through cold case files, where Phoebe and Billie discover a belt that gives Billie superpowers. Meanwhile, Piper and Leo are on the hunt for a band to play at P3; and Paige meets a handsome man, who happens to be her new charge''s parole officer.', 42, '2005-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 9, 'Hulkus Pocus', 'When a demon escapes from custody, Agent Murphy enlists the Charmed Ones to help, where they learn a government created virus is spreading amongst magical beings, that causes them to "hulk out". Meanwhile, Billie becomes infected with the virus and it''s up to the sisters to find an antidote.', 42, '2005-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 10, 'Vaya Con Leos', 'The Angel of Death returns to visit the Charmed Ones but they''re shocked to learn that he''s there for Leo. To try to stop him from taking Leo, Piper casts a spell that backfires, making every man a Leo lookalike, forcing Piper to take drastic measures and ask the Elders and the Avatars for help. Meanwhile, Billie continues her search for the truth behind her sister''s disappearance.', 42, '2005-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 11, 'Mr. & Mrs. Witch', 'When her parents come for a visit, Billie accidently transforms them into assassins and also manages to contact a demon who is posing as a human. Meanwhile, Piper attempts to continue her life without Leo; Paige tries to make a connection with Henry; Phoebe tries to find a way to have her own life.', 42, '2006-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 12, 'Payback''s a Witch', 'With the intention of helping his parolee get a loan, Henry, along with Paige, go to a bank but instead the parolee decides to take everyone at the bank hostage. Meanwhile, Phoebe and Piper have their hands full when, during his third birthday party, Wyatt turns three of his toys into real people.', 42, '2006-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 13, 'Repo Manor', 'Phoebe, in an attempt to move on with her own life, signs a lease for a new apartment, and Paige considers moving in with Henry. However the sisters are forced to remain under the same roof when a demon shrinks them and traps them in a replica dollhouse of the Manor.', 42, '2006-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 14, '12 Angry Zen', 'During Chinese New Year, a demon attempts to steal a mystical wooden staff, that''s protected by the Zodiacs and they enlist the aid of Piper. Meanwhile, Phoebe enjoys her new place by throwing a housewarming party that gets out of control; a monk teaches Billie how to use her power of projection to find her sister; Paige tries to get through to Henry about her magical abilities.', 42, '2006-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 15, 'The Last Temptation of Christy', 'Paige learns the difficulties of dating a mortal when Henry becomes too involved in the magical world and is torn when another suitor arrives hoping to convince her to marry him so they can become the ultimate magical couple. Meanwhile, Billie finally finds her missing sister, Christy; Piper faces a romantic decision when she runs into an old flame and begins to wonder if she should move on with her life.', 42, '2006-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 16, 'Engaged and Confused', 'Piper organizes an engagement party for Paige and Henry, but the couple begin to get cold feet. Meanwhile, Phoebe discovers a strange man following her but soon learns he is actually Cupid; a demon kidnaps Christy in order to get to the Charmed Ones.', 42, '2006-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 17, 'Generation Hex', 'After Paige and Henry leave for their honeymoon, Cupid "Coop" takes Phoebe on a journey through her past romances in an attempt to revive her excitement for love. Meanwhile, a group of magical teens, who are protégés of Leo, come to the manor seeking refuge from demons that have overtaken the Magic School, forcing Piper to take charge. Billie and Christy''s parents come to town for a visit, but Christy refuses to see them in order to test Billie.', 42, '2006-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 18, 'The Torn Identity', 'Coop comes to the conclusion that he has fallen for Phoebe but she''d rather spend her life with a mortal. Meanwhile, Piper is on the hunt for killer demons; Paige finds it hard balancing life as a Charmed One with that of a married woman.', 42, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 19, 'The Jung and the Restless', 'Piper and Phoebe devise a plan to recover Leo. Meanwhile, Paige rescues her new charge from a Darklighter; Billie is forced to make an important decision.', 42, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 20, 'Gone with the Witches', 'In an attempt to destroy the reputation of the Charmed Ones, Billie & Christy resort to trying to make the magical community see that the Halliwells only care about themselves. Meanwhile, Phoebe begins to lust after Coop; Paige cannot hear her charges'' call for help; Piper becomes the perfect 1950s housewife.', 42, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 21, 'Kill Billie: Vol. 2', 'Forced to hide from Billie and Christy, the Charmed Ones find themselves stuck in the Underworld. Meanwhile, Leo appears to Piper and offers demonic approval; Coop searches for Phoebe; Billie & Christy resort to summoning the Hollow to stop the Charmed Ones and the Charmed Ones do the same.', 42, '2006-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0158552')) AND numero_temporada = 8), 22, 'Forever Charmed', 'Piper & Leo, with help from Coop''s ring, must travel back in time to change the events that lead to the deaths of Piper''s sisters. Meanwhile, Billie uses her power of Projection to do the same thing; many familiar faces gather to help Piper in her time of need.', 42, '2006-05-21');
