INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')), 1, 'Season 1', 'Angel, the dashing demon from Buffy the Vampire Slayer, embarks on his own supernatural adventures in Los Angeles. City of Angels. City of Broken Dreams. Between pervasive evil and countless temptations lurking beneath the city''s glittery facade, L.A is the ideal address for a fallen vampire looking to save a few lost souls and, in turn, perhaps redeem his own.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 1, 'City of', 'Angel moves to L.A. where he meets up with Cordelia, another Sunnydale transplant who comes to work for him, and Doyle, a half-demon who gets visions of people in trouble.', 45, '1999-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 2, 'Lonely Heart', 'Angel, with the aid of a new friend, tracks a serial killer whose hunting ground is L.A.''s single bars.', 45, '1999-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 3, 'In the Dark', 'Spike follows Oz to L.A. and enlists the help of a demented vampire to regain a mystical relic from Angel.', 43, '1999-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 4, 'I Fall to Pieces', 'A desperate young woman pleads for Angel''s help, as her disembodied stalker grows more violent. Meanwhile Doyle goes to work with Melissa.', 43, '1999-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 5, 'Rm w/a Vu', 'Cordelia finds a perfect apartment, but it''s got just one flaw: it''s haunted. Meanwhile, Doyle flees the phantoms of his past.', 44, '1999-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 6, 'Sense & Sensitivity', 'Kate''s temper buys her a trip to sensitivity training, which has a strange effect on her... and those around her.', 43, '1999-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 7, 'The Bachelor Party', 'Doyle''s past love comes to town, but her new fiancé has other plans for him. Doyle gets a vision of Buffy.', 45, '1999-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 8, 'I Will Remember You', 'Old feelings are rekindled when Buffy comes to L.A. to visit Angel. Buffy and Angel are attacked by a Mohra demon, and together they slay it', 45, '1999-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 9, 'Hero', 'Doyle is presented with an opportunity for atonement when a band of frightened refugees seek his help.', 44, '1999-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 10, 'Parting Gifts', 'Angel and Cordelia, still coping with the death of their friend, are aided by an old friend in the pursuit of a demon bounty.', 43, '1999-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 11, 'Somnambulist', 'When a killer stalks the L.A. streets using a mark that Angelus once used, Angel must face the possibility that he is committing the murders in his sleep.', 43, '2000-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 12, 'Expecting', 'After a one-night stand goes bad, Cordelia wakes up to find herself extremely pregnant with something extremely unnatural.', 41, '2000-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 13, 'She', 'Angel forms tenuous truce with a warrior demon in order to save refugees from another dimension.', 42, '2000-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 14, 'I''ve Got You Under My Skin', 'A troubled family enlists Angel and Wesley to help them exorcise their resident demon.', 42, '2000-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 15, 'The Prodigal', 'Angel''s conflict with Kate and her dad stirs up memories of his own father.', 39, '2000-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 16, 'The Ring', 'In pursuit of a missing man, Angel becomes enslaved to an underground-fighting ring.', 41, '2000-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 17, 'Eternity', 'When an embattled celebrity enlists Angel to protect her from a stalker, her interest in Angel could cost him his soul.', 42, '2000-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 18, 'Five by Five (1)', 'Rogue slayer Faith comes to town, and when she partners up with Wolfram and Hart, Angel''s life is in danger.', 41, '2000-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 19, 'Sanctuary (2)', 'Everyone, including Buffy Summers, is out to get Faith, and Angel is the only man who can stop them.', 40, '2000-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 20, 'War Zone', 'When Angel tracks down a millionaire''s blackmailer, he gets caught in the middle of a gang war between street kids and vampires.', 40, '2000-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 21, 'Blind Date', 'Angel must break into Wolfram and Hart to prevent an assassin from carrying out her deadly mission.', 42, '2000-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 1), 22, 'To Shanshu in L.A.', 'Wolfram and Hart raise a powerful new foe to strike down Angel and those close to him.', 41, '2000-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')), 2, 'Season 2', 'Angel continues to seek redemption in season two, but a fatal mistake makes him realize that racking up the body count isn’t the way to go. So with a renewed sense of purpose and Cordelia, Wesley and Gunn at his side, Angel sets out to make the streets of Los Angeles a little safer for everyone — unaware that Wolfram & Hart has summoned someone from his past to make sure he fails.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 1, 'Judgment', 'Angel protects a pregnant woman being hunted down by demons after he inadvertently slays her guardian.', 42, '2000-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 2, 'Are You Now or Have You Ever Been', 'In the 1950s, Angel aids a woman hiding from her past inside a hotel with a long history of death and mayhem. Meanwhile, in the present day, Angel and his colleagues hunt down a demon responsible for the carnage.', 43, '2000-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 3, 'First Impressions', 'Angel encounters an amorous Darla in his dreams; Cordelia vows to protect Gunn after she experiences a vision depicting him in mortal danger.', 40, '2000-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 4, 'Untouched', 'Angel attempts to help a girl with telekinetic powers before she falls into the hands of Wolfram and Hart.', 43, '2000-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 5, 'Dear Boy', 'Darla attempts to drive Angel over the edge in hopes of getting him to embrace his dark side.', 43, '2000-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 6, 'Guise Will Be Guise', 'Angel meets with a swami in hopes of ending his obsession with Darla; meanwhile, Wesley assumes Angel''s identity and plays bodyguard to a wealthy business man''s daughter.', 42, '2000-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 7, 'Darla', 'Lindsey finds himself drawn to Darla as her mental state deteriorates.', 43, '2000-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 8, 'The Shroud of Rahmon', 'Angel goes undercover with the help of the witty and street smart Gunn in order to prevent a mind-altering shroud from falling into the wrong hands.', 41, '2000-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 9, 'The Trial', 'Still haunted by flashbacks of his 150-year fling with the dreaded Darla, Angel sends Gunn out to find her.', 41, '2000-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 10, 'Reunion', 'The newly revamped deadly duo of Drusilla and Darla hit the streets of L.A. Angel is frantic, searching for the terrible twosome.', 40, '2000-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 11, 'Redefinition', 'Angel takes on Darla and Drusilla as they hold try-outs for people who want to wreak havoc.', 41, '2001-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 12, 'Blood Money', 'Angel threatens to reveal Wolfram and Hart''s criminal activities when he discovers they''re stealing large contributions being made to a teen shelter. However, someone from Angel''s past has other plans for him.', 41, '2001-01-23');
