INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 15, 'Reprise', 'Wolfram and Hart''s senior partner is coming to visit. When Angel learns that the "senior partner" is actually an evil and merciless demon from hell, he must sacrifice his own life to destroy the powerful beast.', 43, '2001-02-20');
