INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 2), 17, 'Disharmony', 'While the group tries to track down a cult of vampires with a wicked scheme, Cordelia gets a surprise visit from her high school friend Harmony. Unaware that Harmony is now a vampire, Cordelia invites her to join the team on a mission.', 42, '2001-04-17');
