INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 15, 'Orpheus', 'As Faith and Angelus lay drugged and possibly dying, they flash back to key events in Angel''s life... and Willow comes to help the others in the quest to restore Angel''s soul.', 41, '2003-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 16, 'Players', 'As Angel tries to remember what Lilah''s book said about the Master, Lorne plans a cleansing ritual to regain his empathetic powers, and Gunn helps Gwen with some corporate espionage.', 41, '2003-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 17, 'Inside Out', 'As Cordelia prepares to give birth, Angel and his friends finally learn that she - or an evil presence controlling her - is the Beast''s master.', 42, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 18, 'Shiny Happy People', 'While everyone else worships the beautiful woman Cordelia bore, Fred sees another side of her.', 43, '2003-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 19, 'The Magic Bullet', 'As Jasmine''s influence continues to spread, Fred finally tricks Angel into seeing her true nature.', 43, '2003-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 20, 'Sacrifice', 'While hiding in a sewer, Angel and his friends battle a nasty monster provides some clues that might help in the larger battle against Jasmine.', 41, '2003-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 21, 'Peace Out', 'Angel returns from the monster''s dimension and finally defuses Jasmine''s all-compassing powers.', 42, '2003-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 4), 22, 'Home', 'Lilah returns from the dead to offer Angel and his friends full ownership of Wolfram and Hart.', 43, '2003-05-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')), 5, 'Season 5', 'The Angel Investigations team is stunned when the Senior Partners of Wolfram and Hart give them control of the L.A. office. The gang quickly moves in, and although everyone is delighted at the amazing resources they now have at their command, they can’t stop wondering what the catch is.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 1, 'Conviction', 'Some old acquaintances come back into Angel''s life as he and his friends begin running Wolfram and Hart and try to figure out why they''ve been selected to do so.', 43, '2003-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 2, 'Just Rewards', 'Angel and Spike challenge a necromancer who is unhappy with Wolfram and Hart''s new leadership.', 42, '2003-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 3, 'Unleashed', 'Angel tries to help a young woman who has been turned into a werewolf and is being pursued by a group of truly rarified gourmets.', 41, '2003-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 4, 'Hell Bound', 'After being menaced by a series of gruesome ghosts no one else can see, Spike finally comes face to face with the spectral being who''s been trying to drag him into hell.', 43, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 5, 'Life of the Party', 'Strange things happen when Lorne has his sleep removed right before Wolfram and Hart''s big Halloween party.', 42, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 6, 'The Cautionary Tale of Numero Cinco', 'While losing heart for his own career as a hero, Angel befriends a disheartened, elderly hero, and battles an Aztec warrior who literally eats the hearts of heroes.', 42, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 7, 'Lineage', 'When Wesley''s father visits Wolfram and Hart, the firm is attacked by a troop of spooky Ninja cyborgs.', 41, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 8, 'Destiny', 'After Spike receives a strange package, Wolfram and Hart employees are possessed by evil... while Angel and Spike are set against each other in a quest that brings their 100-year-old rivalry to a head.', 41, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 9, 'Harm''s Way', 'When Harmony wakes up next to a dead man with vampire bites in his neck, she''s afraid she lost her head and killed him... but she can''t remember doing it.', 42, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 10, 'Soul Purpose', 'When Spike is talked into taking up the good-deeds business, Eve lets loose a soul sucking parasite on Angel, who then suffers disturbing feverish hallucinations as he sleeps.', 41, '2004-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 11, 'Damage', 'A deranged vampire slayer is convinced that Spike is the man who kidnapped and tortured her when she was a child.', 42, '2004-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 12, 'You''re Welcome', 'When Lindsey returns and tries to defeat Angel using a secret "failsafe" entity created by the Powers That Be, Cordelia emerges from her coma to help save Angel.', 42, '2004-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 13, 'Why We Fight', 'A World War II submarine sailor - the only man Angel ever turned into a vampire since regaining his soul - returns to seek his revenge.', 41, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 14, 'Smile Time', 'While Nina the werewolf show romantic interest in Angel, he investigates a demon-infested children''s television program and gets turned into a puppet; Gunn makes a deal to keep his newly implanted mental powers; and Wes and Fred''s relationship heats up.', 41, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 15, 'A Hole in the World', 'After being breathed on by an ancient sarcophagus, Fred contracts a mystery illness and lies near death while Angel and his friends try to figure out what''s wrong with her.', 42, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 16, 'Shells', 'Mourning Fred''s death, Angel and his friends vow to find a way to bring her back, which leads to a confrontation with the ancient god Illyria, who now occupies Fred''s body.', 42, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 17, 'Underneath', 'Angel, Gunn and Spike rescue Lindsey from a suburban hell dimension; Lorne and Eve are pursued by a representative of the senior partners; and Wesley consoles Illyria, who hates her new world.', 43, '2004-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 18, 'Origin', 'When a warlock brings Connor back into Angel''s life, Wesley finds out that Angel has tinkered with the memories of his friends.', 43, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 19, 'Time Bomb', 'As Angel and Hamilton urge Wesley to get rid of Illyria, she suffers a cataclysmic physical breakdown; and Gunn clashes with Angel over the enforcement of an evil demon contract.', 43, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 20, 'The Girl in Question', 'While Angel and Spike to go Italy to retrieve the head of a demon mobster (and save Buffy from a new suitor), Fred''s parents arrive at Wolfram and Hart, looking for their daughter.', 43, '2004-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 21, 'Power Play', 'As Angel''s behaviour grows increasingly hostile, his friends learn he''s associating with members of an evil secret society, and may have deliberately engineered Fred''s death.', 42, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0162065')) AND numero_temporada = 5), 22, 'Not Fade Away', 'Angel and his friends prepare for their suicide attack on the Circle of the Black Thorn.', 42, '2004-05-19');
