INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 1, 'Jeff Davis', 'The improv comedy begins with a round of “Props,” “Sound Effects” and a hilarious “Doo Wop” segment about a woman who falls victim in a taxidermy tragedy.', 22, '2001-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 2, 'Kathy Greenwood', 'Games include “Props”; “Living Scenery”; and a round of “Song Styles” that finds Wayne Brady crooning to a fitness trainer from the audience.', 22, '2001-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 3, 'Chip Esten', 'Highlights include “Weird Newscasters” with a cowboy and a synchronized swim team; “Narrate,” a film noir scene set in a bike shop; “Duet,” in which a duo serenade Merrilee, the pet photographer; “The Blind Date Hoedown,” and “Three-Headed Broadway Star,” in which Drew, Wayne and Ryan sing “I Love You for Your Shoes” to an audience member.', 22, '2001-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 4, 'Kathy Greenwood', '"Questions Only" sees romance break out at a luxurious European health spa; Ruth and Lisa provide "Sound Effects" for Ryan and Colin, two American GIs attempting an escape from a German World War II POW camp; "Scenes from a Hat" include "original rejected poses for the Mona Lisa"; "Songs of James Bond."', 22, '2001-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 5, 'Chip Esten', 'Games include Wayne Brady ''n a spoof of ''N Sync for a round of “Let''s Make a Date”; an audience serenade during “Duets.” Also: “Doo Wop”; “Party Quirks”; and “Scene to Rap.” Ryan Stiles, Colin Mochrie, Drew Carey.', 22, '2001-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 6, 'Kathy Greenwood', 'Ryan Stiles yuks it up as a cowboy-influenced weatherman in “Weird Newscaster.” Also: “Party Quirks” and “Newsflash.” Other players include Colin Mochrie, Wayne Brady and host Drew Carey.', 22, '2001-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 7, 'Brad Sherwood', 'Games include “Let''s Make a Date,” “Party Quirks” and “Scenes from a Hat.” Also: Drew joins the cast for a “Family Reunion Hoedown.” Regulars include Ryan Stiles, Colin Mochrie and Wayne Brady.', 22, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 8, 'Kathy Greenwood', 'Games include a round of “Film, TV and Theatre Styles,” with the guys taking on kids'' shows, Westerns and Shakespeare. Also, Wayne Brady and Chip Esten perform an impromptu theme song for a new sitcom. Other players include Ryan Stiles and Colin Mochrie. Drew Carey hosts.', 22, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 4), 9, 'Chip Esten', '“Hollywood Director” finds Wayne Brady striking a pose as female supermodel and Chip Esten as her unhappy hubby. Also: rounds of “Song Titles,” “Scenes from a Hat” and a heavy-metal “Duet.” Other players include Colin Mochrie and Ryan Stiles. Drew Carey hosts.', 22, '2001-10-10');
