INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 9, 'Chip Esten', 'In "Superheroes," Stinky Man (Colin) tries to solve a dead possum in his parking spot with his friends Giggling Nipple-Tweak Man (Ryan), Captain Luau (Chip), and Temper Tantrum Kid (Wayne); "Scenes from a Hat" are "disturbing people to get a lap dance from," "unfortunate times to sneeze," "jobs where you shouldn''t kid around," and "the Munchkins: What are they doing now?"; "Stand, Sit, Lie" comes back after a three-season hiatus, with expectant mother Ryan is cared for by flirtatious midwife Wayne, with Colin the nervous husband; in "Party Quirks," Chip tries to guess various acts getting booed off the stage during Amateur Night at the Apollo (Wayne), a bomb squad member who received a tip that there are bombs in people''s pants (Colin), and a series of ugly sea creatures swimming up to the cameras (Ryan); after finding humor in Drew nearly choking himself with a breath mint, the show continues with "Show-Stopping Number," featuring Ryan, Colin, and Wayne in a factory.', 22, '2002-11-29');
