INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 14, 'Chip Esten', 'Games include Wayne as a whole family of acrobats in “Let''s Make a Date”; and Ryan as the star of “Drew Carey, The Musical.” Also: A round of “Dubbing”; “Scenes From a Hat”; and “Props.” Other players include Colin Mochrie and host Drew Carey.', 22, '2003-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 15, 'Kathy Griffin', 'Guest Kathy Griffin plays a teenage groupie. Also: Wayne Brady as Don King promoting an “improve your sex life” video; Ryan Stiles as a David Copperfield wannabe.', 22, '2003-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 16, 'Brad Sherwood', 'Wayne Brady loses more than his shirt at a casino, and plays both Michael Jackson and James Brown in a “celebrity death match.” Also: the Blues Brothers sing to a sign-language interpreter; and host Drew Carey joins in a “Hoedown” about growing up.', 22, '2003-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 17, 'Greg Proops', 'Exercise maven---and frequent punchline--- Richard Simmons joins the guys for a round of “Living Props” and sweats to the ditties during a disco-themed “Song Styles.” Also: “Multiple Personalities” and “Newsflash.”', 22, '2003-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 18, 'Brad Sherwood', 'Games include “Press Conference,” featuring Colin Mochrie as Batman; and a round of “All in One Voice,” which finds the guys channeling a piggy puppet to serenade one another. Wayne Brady, Ryan Stiles and host Drew Carey also perform.', 22, '2003-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 19, 'Kathy Griffin', 'David Hasselhoff drops by for a round of “Song Styles” with Wayne; and a game called “Dubbing,” in which he plays (what else?) a lifeguard. Also: “News Flash” and “Two-Line Vocabulary.” Other players include Ryan Stiles, Colin Mochrie and host Drew Carey.', 22, '2003-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 20, 'Greg Proops', 'Greg Proops tries to get his groove on in a round of “Weird Newscasters.” Also: “Scenes from a Hat”; “Film Dub”; “Party Quirks”; and “World''s Worst Dating Service Video.” Other players include Colin Mochrie and Ryan Stiles.', 22, '2003-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 21, 'Greg Proops', 'Colin and Ryan play sorority girls with unusual athletic abilities in “Sportscasters”; Colin goes psycho as an unstable flight attendant in “Let''s Make a Date”; Wayne croons to a female bodybuilder in “Song Styles.”', 22, '2003-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 22, 'Chip Esten', 'Highlights include a “Hoedown” about the Man of Steel; a round of “Hollywood Director” set in a prison; and a musical bit, in which Colin, Ryan and Wayne serenade their favorite “Bartender.”', 22, '2003-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 23, 'Kathy Greenwood', 'In a round called “Number of Words,” the players can only speak so many lines of dialogue, all from ”The Wizard of Oz.” Players include Wayne Brady, Colin Mochrie and Ryan Stiles.', 22, '2003-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 24, 'Brad Sherwood', 'Batman (Colin Mochrie) and Robin (Ryan Stiles)require sound effects from the audience. Mochrie, Stiles and Brad Sherwood are foul-mouthed auto mechanics. And host Drew Carey goes to the zoo.', 22, '2003-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 25, 'Chip Esten', 'Games include “Superheroes,” with Colin as Mad Cow Man; a round of “Living Scenery”; “Scenes from a Hat”; and Wayne and Chip serenading belly-dancing twins with a “Duet.”', 22, '2003-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 26, 'Jeff Davis', 'Games include “Let''s Make a Date”; “Hoedown”; “Scenes From a Hat”; and “News Flash.” Also: a round of “Greatest Hits.” The ensemble features Wayne Brady, Colin Mochire, Ryan Stiles and host Drew Carey.', 22, '2003-07-25');
