INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 28, 'Greg Proops', 'Game 1 - Scene To Music: Ryan, a gung-ho pest exterminator, bursts in on the hotel room of Colin and Wayne, a newlywed couple.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 29, 'Kathy Griffin', 'Game 1   Press Conference: Colin as the 1st man to make love on the moon.
