INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 31, 'Brad Sherwood', 'Games include “Hollywood Director,” with Ryan Stiles and Wayne Brady as Arctic explorers; and a round of “Two-Line Vocabulary” set in the wild, wild west. Also: Colin Mochrie tries to figure out who he is in “Press Conference.”', 22, '2003-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 32, 'Jeff Davis', 'Instead of points, the players win $100 for winning rounds, which include a pair of pop divas duking it out during “Weird Newscasters”; “Scenes from a Hat”; and “Greatest Hits.”', 22, '2003-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 33, 'Greg Proops', 'A round of “Hats” has the gang seeking clients for the world''s worst dating service; audience members wind up playing “Let''s Make a Date.”', 22, '2003-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 5), 34, 'Chip Esten', 'In "Hollywood Director," town sheriff Ryan has finally caught the fugitive gunslinger Chip and puts him in jail, but Wayne comes in as a member of Chip''s gang, and Colin gives them the styles of falling in love with each other and product testimonials. In "Improbable Mission," Wayne is the voice on the tape informing secret agents Colin and Ryan that they must go shopping at the grocery store. In "Scenes From A Hat," the scenes are "bad times to use the athletic butt slap," "topics of conversation that always ruin dinner parties," "what the Whose Line? cast will ask Santa for this Christmas," and "things your waitress can say that can be misconstrued as sexual." In "Greatest Hits," Colin and Ryan sell Songs of Pregnancy, with songs performed by Wayne and Chip.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 1, 'Chip Esten', 'Hollywood Director features Colin giving notes to a western cowboy (Ryan) holding up a train with a beautiful woman (Wayne) on it, with another cowboy to the rescue (Chip);  Doo Wop features Colin, Chip, and Wayne singing about Diana, who was killed in a tragic bowling accident; Scenes from a Hat includes ""What Drew Whispers in his date''s ear,"" and ""A bad time for that laxative to kick in""; Greatest Hits features Colin and Ryan introducing ""Songs of Hor-ror Movies"".
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 2, 'Brad Sherwood', 'Hollywood Director features Coin giving notes to two feisty French cheifs (Wayne and Ryan), and the fireman coming to help when things go wrong (Brad).  Weird Newscasters features a wig shop owner doing a cheesy promo for his shop on the newscast (Brad), a sportscaster who lives a double life as a drag queen (Wayne), and a drill seargent, training his out of shape troops (Ryan).  Walking a dog is an Improbable Mission for Colin and Ryan, and Brad, Ryan and Wayne do an ode to superheroes as The Boogie Woogie Sisters.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 3, 'Chip Esten', 'In Newsflash, Colin is the Anchor with Co-Anchor Chip as a 1950s teen rebel biker, in sports Wayne is a harem girl sent in to entertain the sultan and it''s weatherman Ryan''s last day and he wants to go out in a blaze of glory! In Sound effects, Colin is an emergency room-surgeon getting called in on new-years eve, where Ryan provides the sound effects. In Title Sequence, Ryan, a sumo wrestler, and Colin, a model, acts out to Chip and Wayne''s song. In Scene with an Audience member Emily who works at a store plays Batgirl in the scene. Batman, Ryan has come to the rescue of Batgirl from the clutches of the Riddler, Colin. In Greates Hits Wayne and Chip sings songs of the warrior princess; Jerry Lee Lewis - Lalalalala; Kid Rock - Clubs, Spears and Shields; Techno - Huge women, puny men; The winner is Chip, and the rest of the gang have to play Questions Only on board of the Titanic.', 22, '2004-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 4, 'Greg Proops', 'In Let''s Make a Date, Wayne gets a turn as a guesser, with Greg an angry guest on Jerry Springer, Colin a ventriloquist whose dummy is sabotaging his chances, and Ryan as a frustrated writer going insane in a remote hotel; a Poseidon Adventure Scene to Rap; Ryan provides old-school Sound Effects for Jedi knight Colin who gets the call that the Empire is attacking; Film Dub for Ryan, Colin, and Greg is one day at the gas station; Wayne sings Ryan and Colin''s Songs of Hockey on Greatest Hits.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 5, 'Greg Proops', 'First up, Superheroes had Greg(Shedding Cat Man), Ryan(Strutting Pick-up Artist Boy), Colin(Exciteable Hamster Boy), and Wayne(Very Enthusiastic Game Show Contestant Boy) solving the problem of a clogged toilet. Then Questionable Impressions was set in a funeral home. Props had Ryan and Colin vs. Wayne and Greg. Wayne sang to Terri who worked in a clothing store and goes to the beach in a gospel style in Song Styles. Following was Moving People, where Colin(moved by Shauna) is a doctor flying in to rescue Ryan(moved by Amy) who has been bitten by a poisonous snake. Then Dating Service Videos(announced as Hats) had Ryan and Colin vs. Wayne and Greg again. Lastly, Hoedown was about pregnancy tests. No winner was announced, Wayne and Ryan were declared the winners and read the credits as a wrestling team challenging their opponents.', 22, '2004-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 6, 'Chip Esten', 'Colin, the Queen of England, announces that he''s having an affair with Ryan Stiles in Press Conference; Neely and Andrea give Sound Effects to a gallant knight (Ryan) trying to reach Rapunzel (Colin) in the tallest tower of the witch''s castle, then free her and escape past the witch, the sleeping dragon, and other dangers so they can be wed (in honor of Valentine''s Day); Chip and Wayne sing a R&B Duet to the Loyola Marymount University cheerleaders; cheerleaders Jennifer, Pamela, and Ryanne become Living Scenery for Ryan and Colin, two cowboys out on the range tend to their cattle and set up camp for the night; Wayne, Chip, Colin, and Ryan sing an Irish Drinking Song about farting.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 7, 'Greg Proops', 'Let''s Make A Date started things with Greg choosing from Wayne(Michael Jackson turning into a wereworlf), Colin(world''s most annoying person to sit next to on an airplane) and Ryan (evil scientist in lad about to mutate into horrific versions of the other two bachelors). Next was Newsflash, with Greg and Ryan giving clues to Colin, who was standing in front of footage of babies. Then it was Funeral with Greg hosting the funeral of Joe, a fisherman with Colin and Ryan the mourners. Then Party Quirks had Greg hosting again, with Wayne a heroic fireman determined to rescue everyone, Colin as talent night at an old folks home, and Ryan as a series of delivery guys in porn films. African Chant had all four chanting to Crystal, a candy hawker at a raceway. Greg was declared the winner so Drew joined the others in a game of Props. All four read the credits as lingerie models in a catalog.', 22, '2004-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 8, 'Chip Esten', 'Seating Order: Wayne, Chip, Colin and Ryan.Film, TV, & Theatre Styles: Ryan and Colin have disguised themselves as women in an all-female band to hide from Wayne, a hit man working for the mob.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 9, 'Denny Siegel', 'Game 1: Questions Only - High school prom dates (Paraphrased.)
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 6), 10, 'Chip Esten', 'Colin''s Magnet Man is stuck at the North Pole in Superheroes, joined by Mesmerized by Moving Objects Man (Ryan), the Bob Fosse Kid (Chip), and Chainsaw Massacre Boy (Wayne); a Chip and Wayne Duet about a sponge in a Busby Berkeley song with Colin and Ryan joining in as Busby Berkeley dancers; Weird Newscasters finds coanchor Chip as Snagglepuss, sportsman Wayne finds his neighbor peeping on him and decides to put on a ""little show,"" and weatherman Ryan is the rise and fall of a female Hollywood legend of the silver screen; Colin reports to Ryan and Chip in Newsflash from clips of Ryan; an Irish Drinking Song about giving birth.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 1, 'Brad Sherwood', 'The crisis for the Superheroes is no ceramics, with Brad as Tom Arnold, Ryan as Guy Who Channels the Spirits of Farm Animals, Colin as Captain Streaker, and Wayne as Man Who Mimics Everyone While On Caffeine; Film Dub is one day at the doctor''s office; a body odor Infomercial; Brad hosts Party Quirks with a high-energy android who keeps running out of power and recharges by kissing someone''s head (Wayne), a Russian ballet dancer (Colin), and a series of the world''s dumbest criminals caught on tape (Ryan); ""Songs of the Presidents"" in Greatest Hits.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 2, 'Kathy Greenwood', 'Kathy is the contestant on Let''s Make a Date, choosing from Uncle Ernie who''s drinking too much and is about to ruin his niece Colin''s wedding reception (Wayne), a heroic frog leading ""The Great Escape"" of all the frogs from a French restaurant (Colin), and someone who''s founded a cult that worships Colin and he lives his life by Colin''s example (Ryan); Two-Line Vocabulary features SWAT team commander Colin and his two agents Wayne (""Is this it?"" and ""I want to go first."") and Ryan (""Should I be doing this?"" and ""What''s the point of that?"") about to infiltrate a group of terrorists; Film Dub has Ryan, Colin, and Kathy at a themed restaurant; Sound Effects has audience members Karen and Sharon provide sounds for Ryan and Colin, whom they don''t know who''s who, as Clark Kent (Ryan) is having an intimate evening with Lois Lane (Colin) when he gets a message that Lex Luthor is subjecting the city to a series of terrors; Show-Stopping Number at a bank for everyone but Kathy.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 3, 'Greg Proops', 'The show opens with the bitter divorce Award Show, then Colin is Noah announcing he''s eaten all the animals during a Press Conference.  Then, it''s an infomercial to stop being drunk.  After that, it''s Sound Effects with Ryan and Colin being two musketeers and an Irish Drinking Song about first cars.  Greg wins, so everyone else plays Props.', 22, '2005-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 4, 'Chip Esten', 'Weird Newscasters: Colin is the anchor... Chip is the co-anchor and the ""lion from the Wizard of Oz who was given an overactive libido instead of courage"". Wayne is on sports and is a ""desparate caveman looking for food, a warm cave and a mate"". Ryan does the weather and ""becomes extremely nervous when he suddenly discovers it''s the first day of Ryan hunting season"".   Song Styles: Chip and Wayne sing a gospel style song to Mira the Hebrew teacher.   Whose Line: Buffy the vampire slayer (Colin) has come to kill Count Dracula (Ryan).   Greatest Hits: The Songs of Rome.   Irish Drinking Song: All about falling out of a car on a date.   There is no winner... it''s a four-way tie... so they all read the credits as trash-talking basketball players.', 22, '2005-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 5, 'Chip Esten', 'Song Titles has the four at an office Christmas party. In Duet, Chip and Wayne sing to Lily the Crossing Guard as the Backstreet Boys. In Action Replay, Wayne and Chip are two campers getting dressed in the morning, and discover insects crawled in their clothes. Then, Ryan and Colin perform a different scene using the same body movements. In Greatest Hits, Colin and Ryan sell a compilation album about pregnancy, as sung by Chip and Wayne.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 6, 'Kathy Greenwood', 'The show starts with Let''s Make A Date. Kathy has to pick from Wayne (a temperamental queen bee gathering nectar from people''s faces), Colin (a born to be wild biker chick going from guy to guy to find a new stud to ride behind) and Ryan (having an entire relationship with the stool Colin is sitting on).   In Whose Line, Indiana Jones (Ryan) and his feisty female companion (Colin) are trapped in a snake-infested Egyptian tomb and their torches are about to go out.   In Dead Bodies, Bosley (Ryan) is being held captive by a beautiful villainess (audience member Kelsey), who is torturing him with sexual seduction when one of Charlie''s Angels (Kathy) bursts in to rescue him.   Greatest Hits features a 25 CD set of ""Songs of the Fast Food Worker"".   Kathy wins, so Drew & Ryan play against Wayne & Colin in Props.   Ryan reads the credits pretending he''s in later life and his relationship with the stool is on the rocks.', 22, '2005-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 7, 'Brad Sherwood', 'The studio is cold for Superheroes Cottage Cheese Man (Brad), the Narrowly Escapes Death Kid (Ryan), Captain Salmon (Colin), and Caught in a Wind Tunnel Boy (Wayne); Brad, Colin, and Ryan play If You Know What I Mean as three supermarket employees on the night shift; All in One Voice features ""The First Time We Swam"" with Lucy and Ricky Ricardo (Colin/Wayne and Ryan/Brad respectively); in Film Dub, all four provide voices for a team of suit salesmen trying to make a sale; Cathy and Veena provide Sound Effects for Ryan and Colin, two nervous World War II parachutists are about to go on a mission into occupied France; Scenes from a Hat are ""the curriculum at Hillbilly University,"" ""I didn''t know the mic was on,"" and ""nightly bedside prayers of Whose Line cast members.""
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 8, 'Chip Esten', 'Chip appears on Let''s Make a Date, hoping to choose from a mean female wrestler who receives a Valentine and is desperate to find her secret admirer (Wayne), the mad Headless Horseman looking for a hideous head to replace his own (Colin), and a mischievous gargoyle at the top of Notre Dame Cathedral who keeps coming alive to cause trouble (Ryan); ""Film, TV, and Theater Styles"" is Colin is a distraught bride, and Wayne is her angry mother, coming to fashion designer Ryan on the morning of the wedding since the dress doesn''t fit, in the styles of MacGyver, soap opera, pyschic network, WWF, Crocodile Hunter, and Antique Roadshow; then a Doo-Wop about Erica, who died tragically in a freak gene-splicing accident; ""Songs of the Lunchlady"" in Greatest Hits, with hillbilly (""Aprons, Hairnets, and Knee-Highs"") and punk (""Don''t Want Your Milk!"").
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 9, 'Chip Esten', 'Game 1: Let''s Make A Date   Contestant - Chip   Bachelor #1 - Wayne: Cheesy Mexican Troubadour Who Sings Unbelievably Insulting Songs About The People He Serenades   Bachelor #2 - Colin: Panicking Dutch Peasant Who Thinks The Openings In People''s Faces Are Leaky Holes In A Dyke   Bachelor #3 - Ryan: Recently Out-Of-The-Closet Robin Hood Selecting His Band Of Merry Men & Taking Them To Rob The Rich
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 10, 'Greg Proops', 'Game 1: Hollywood Director
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 11, 'Greg Proops', 'In Superheroes, the crisis is no more shaving cream for Not Hot But Spicy Man (Greg), Ridicules People Behind Their Back Boy (Ryan), Captain Panic (Colin), and Malfunctioning Robot Doctor (Wayne). Ryan and Colin are training to be firemen in Hey You Down There, with Greg narrating. Colin directs Hollywood Director, with a vampire bat (Ryan) who flies into the bedroom of a mouthy college girl (Wayne), who is showering and getting ready for a date. After Ryan transforms into Count Dracula, Professor Van Helesing (Greg) kicks down the door to confront him.  In Two Line Vocabulary, Colin, Wayne, and Ryan are three soldiers caught in a foxhole under enemy fire. Colin can say anything. Ryan can only say ""Do you want a piece of this?"" and ""You remind me of my mother when you do that"". Wayne can only say ""Is that what I think it is?"" and ""I don''t think so"". In Scene to Rap the four rap in Jurassic Park.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 12, 'Kathy Greenwood', 'Let''s Make a Date has Kathy choosing from Wayne, the Hyenas from ""The Lion King"", Colin, a sensitive teenage French Canadian nerd (paraphrased), and Ryan, a Lounge Singer on the Titanic (paraphrased)
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 13, 'Kathy Greenwood', 'In Hollywood Director Ryan plays a hunky plumber who has just finished installing a shower... when frisky housewife, Kathy, insists on testing it with him. Kathy''s outraged mother, Wayne, makes a dramatic entrance and catches them in the act. The suggestions they''re given by the director, Colin, are ""like fast-talking gansters from a 40''s film noir"", ""like you have giant butts"" and ""like a violent, slow-motion shoot-out"".   The Three-Headed Broadway Star song is called ""Can''t Stop Thinking About Your Pants"" and is sung by Wayne, Ryan & Colin to Gillian.   Scenes From A Hat subjects are ""what the Queen of England is really saying to the people in the greeting line"", ""what Lassie was really trying to tell everyone"", ""people you wouldn''t want to go on an intergalactic flight with"", ""if adults settled disputes the way kids do"" and ""if songs were written about life''s most embarassing moments"".   The Helping Hands scene has Kathy visiting her Austrian penpal (Ryan) and he''s trying to impress', 22, '2005-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 14, 'Jeff Davis', 'Number of Words is a scene from ""The Mummy"", Egyption Guide, Jeff (four words), and Fiesty Female Archeologist, Colin (two words), open up a tomb, releasing the evil Mummy, Wayne (three words). Then, dashing adventurer, Ryan (five words), comes to rescue them.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 15, 'Brad Sherwood', 'In Questionable Impressions, the four are at a police station. Brad and Wayne sing to Bill the Liquor Clerk as REM in Duet. In Sound Effects, audience members Giselle and Jenny provide the sound effects for Farmer Ryan and Wife Colin are rounding up their animals because of an approaching storm, when they are amazed to see a UFO approaching. In Greatest Hits, Colin and Ryan sell Songs of Las Vegas, as sung by Wayne and Brad.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 16, 'Kathy Greenwood', 'In Let''s Make A Date Kathy is the contestant. Wayne is a ""mission impossible agent lowering himself into a room to retrieve secret microfilm in Colin & Ryan''s pants pockets"". Colin is ""having passionate secret affairs with Wayne & Ryan''s shoes but must decide between them"". Ryan is a ""comedian who is bound & strapped to a time bomb that counts down whenever the audience isn''t laughing"".   Really Bad Hangover is next where Kathy & Colin act out a scene where a couple wake up in the morning... and Ryan & Wayne do the amplified hangover sound effects.   Scenes From A Hat subjects are ""bad songs to sing while making love"", ""the last thing you would expect to come out of your grandmother''s mouth"", ""adults who are still experiencing the terrible two''s"" and ""unusual acts performed on talent night at the convent"".   In Film Dub Ryan, Kathy & Colin improvise a scene... ""one day at the trailer park"".   The Greatest Hits CD set this time is The Songs of the Circus.   Wayne wins the show... so Dre', 22, '2005-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 17, 'Kathy Greenwood', '[b]Hollywood Director[/b] has Colin directing a foxhunt with the Lady of the Manor, Kathy, who accidently shoots the Sexy Stable Boy, Ryan. As she is removing the buck shot from his rear end, her dashing jealous fiancee, Lord Wayne, rides in with the horses and hounds. In [b]Dubbing[/b], in a 1930''s speakeasy, mobster Colin starts hitting on audience member Megan (whose voice is provided by Wayne), the sexy nightclub entertainer. Her boyfriend, rival mobster Ryan, breaks in. In [b]Scenes From a Hat[/b], the quartet performs ""Bad times to take off your pants"", ""Weird things to time"", and ""Unfortunate moments to become nauseous"". [b]Greatest Hits[/b] has Colin and Ryan introducing Songs of Paris, as sung by Wayne. Wayne wins, so everyone else plays [b]Foreign Film Dub[/b]. Drew and Kathy act out the Japanese film, ""Ramen Aplenty"". Ryan translates for Drew and Colin translates for Kathy.', 22, '2005-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 18, 'Greg Proops', 'In Hollywood Director, Colin directs a scene from ""The Exorcist"", with Wayne as the Possessed Daughter, with Ryan as the Distaught Mother trying to tie her down to the bed, and Greg as the priest. In Remote Control, the topic is cows for Greg as Ricki Lake, Wayne as a Spanish Game Show, Colin as Wrestling Smackdown, and Ryan as the Crocodile Hunter. In Song Styles, Wayne sings to Jill the Volleyball Coach from Calabasas, in the style of Cab Calloway. In', 22, '2005-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 19, 'Chip Esten', 'In Hollywood Director, Colin directs. College Jock, Chip, and his nagging girlfriend, Ryan, are lost and scared in the woods and take refuge inside a creepy log cabin. Suddenly, Freddy Krueger, Wayne, bursts through the window. In Newsflash Colin reports to Chip and Ryan in front of overweight dancers. Chip hosts Party Quirks with Wayne (Desperate to show off his wrestling skills by challenging all-comers to wrestler on stage with him), Colin (James Bond on an important mission, who has a terrible case of food poisoning), and Ryan (series of purebreds competing at a dog show but easily distracted by the crowd). In Bartender Chip tends to Wayne, who is celebrating puberty, Ryan, who thinks he''s a princess, and Colin, who is angry about his divorce. Ryan wins, so he watches Wayne, Drew, Colin, and Chip sing the Affair Hoedown.', 22, '2005-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 20, 'Brad Sherwood', 'Number of Words is a scene from Star Trek, has Captain Kirk (Ryan, 3 words) has been captured by a Klingon (Wayne, 4 words). Mr. Spock (Brad, 5 words) and Scotty (Colin, 2 words) beam down to the planet to rescue them. Scenes From a Hat has the quartet act out ""Things you don''t want to be shouting at a party when the music suddenly stops"", ""Bad things to say or do with someone with a hairy back"", ""Poems about embarrassing moments"", and ""The worst soap opera cliffhanger lines leading into a commercial"". In Dubbing, Colin is an explorer who finds Jane, audience member Rachel (voiced by Brad) in the jungle, taking Cheetah for a walk and tries to pursuade her to return to civilization with him. Suddenly Tarzan, played by Ryan,  swings in to reclaim her. Colin and Ryan then sell a Greatest Hits compilation based on TV Detective and Cop Shows, as sung by Brad and Wayne, in the styles of the Rolling Stones, Opera, and a Burlesque Stripper Song.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 21, 'Chip Esten', 'Let''s Make a Date has Chip chhose from Wayne (All The Characters from Austin Powers), Colin (Dunk Tank Loudmouth Unknowingly Suspended Above a Pool of Piranha Fish), or Ryan (Series of Kids Coming to see Department Store Sanata Colin with their Christmas Wish Lists).   In Duet, Chip and Wayne sing to Nicole the Receptionist in the style of swing. In Bartender, Chip tends to Colin, who is mad about his haircut, and Ryan, who is in love with his shoes. Chip hosts Party Quirks. His guests are Wayne (Entire Night''s Entertainment at a Hawaiian Hotel Luau), Colin (Salty Old Sea Dog who can See Amazing Sights in People''s Bellybuttons), and Ryan (Series of Temperamental Actresses Screen Testing for a Nude Sceen with Chip). The four sing the Broke Up Irish Drinking Song.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 22, 'Kathy Greenwood', 'Let''s Make a Date has Kathy choose from Wayne (Panicky Frat Boy Waking Up On His Wedding Day Blindfolded, Naked & Handcuffed To Colin), Colin (Incompetent 1940s Gangster Who Bungles A Bank Robbery And Has To Make A Desperate Escape), and Ryan (Smart-Mouthed Brat Who''s Been Told Never To Lick The Metal Plate In Colin''s Head In Winter). In Motown Group, Wayne, Colin, and Ryan sing ""Do the Fireman"". In Narrate, Ryan and Colin are at a lingerie shop. The Scenes From a Hat the four act out are ""Other People Dorothy Might Have Met And What They Would Have Asked The Wizard For"", ""Something You Always Wanted To Tell Your Parents But Couldn''t Until Now"", ""Titles Of Self-Help Books Written By Dogs"", ""World''s Worst Person To Share An Elevator With"", ""What Phone Sex Operators Are Really Doing On The Other Line"", ""How Men Can Make The Most Of Their Time While They Are Stuck Cuddling With The Little Woman"", and ""The Last Thing Drew Carey Thinks Before He Drifts Off To Sleep"".
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 23, 'Kathy Greenwood', 'Weird Newscasters   Colin anchors... Kathy co-anchors as a ""Jerry Springer guest who''s been brought on to reveal her shocking secret to husband Colin""... Wayne is the sports guy who is a ""world famous fashion designer training his new models how to work the catwalk""... Ryan is on the weather who is ""using everyone else''s bodies as his weather maps"".   Number of Words   Deleted scene from Rocky. Colin plays Rocky (3 words), Ryan plays Rocky''s coach (5 words), Kathy plays Rocky''s wife Adrian (2 words) and Wayne plays Rocky''s tough-talking opponent (4 words).   Action Replay   Kathy and Wayne act out a scene where the boss is arriving for dinner any minute. Kathy is struggling to fit into her tight outfit, while her husband Wayne frantically tries to fix a burst pipe under the sink.   Living Scenery   Colin and Ryan play a couple who ride donkeys into the Grand Canyon for a romantic overnight camping trip. Wayne and Kathy are the props.   Showstopping Number   Wayne, Colin and Ryan are in', 22, '2005-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 24, 'Brad Sherwood', 'Game 1: Hollywood Director Ryan and Wayne as two Southern convicts.Game 2: Mowtown Group""Do The Policeman.""Game 3: Sound Effects James Bond and Colin are tied up in a villain''s mountains headquarters.Game 4: Greatest Hits Songs Of The President Artificial Winner: Colin Drew Game: Props Credits Roll: Wayne and Brad as two guys in a bar complaining about the people who have made their lives miserable.', 22, '2005-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 7), 25, 'Kathy Greenwood', 'Seating Order: Wayne, Kathy, Colin and Ryan.Questions Only:  Kathy and Wayne start in a scene where they are a very passionate couple who stumble across Frankenstein''s castle one stormy night.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0163507')) AND numero_temporada = 8), 1, 'Denny Siegel', 'In Fashion Models, Denny commentates on the Security Guard Fashion Show.  In Let''s Make a Date, Denny must choose from a Spanish game show host (Wayne), an inept lap dancer (Colin), and a man in traction after an accident caused by Denny (Ryan).  In Narrate, Colin and Ryan act out a film noir scene at a bus stop.  Film Dub has Ryan, Denny, and Colin improvising an announcement at the airline office.  In Film, Theatre and Television Styles, Wayne is an upstart young pool hustler challenging Ryan, the veteran pool guy.  In Hey, You Down There!, Denny narrates for Ryan and Colin in “How to Cope with Problems on a Long Road Trip.”  In Props, it''s Ryan and Denny vs. Colin and Wayne.  Finally, the entire gang, except Drew, sing another Blind Date Hoedown.', 22, '2005-10-03');
