INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 1), 1, 'Pilot', 'Doug''s kingdom comes under attack when his recently widowed father-in-law, Arthur, moves in rather than go to a retirement home, turning Doug''s TV room into Arthur''s bedroom.', 23, '1998-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 1), 2, 'Fat City', 'After seeing photos of Carrie''s stout mother, Doug worries that Carrie will gain weight as well, and tricks her into starting a diet.', 23, '1998-09-28');
