INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 2, 'Window Pain', 'Feeling inferior to, and looked down upon by, the new neighbors, Carrie tries to make a good impression, but Doug couldn''t care less. Meanwhile, Arthur tries to use Spence for free subway rides.', 25, '2002-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 3, 'Holy Mackerel', 'Doug and Carrie start going to church after an uncomfortable encounter with their priest and when Carrie''s prayer for a raise is answered, she gets a little carried away and starts praying for such trivial matters as a shoe sale.', 25, '2002-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 4, 'Kirbed Enthusiasm', 'Deacon asks Doug to help him coach his 8-year-old son''s football team and the boy challenges Doug to try out for a semi-pro team, but Carrie isn''t thrilled with the idea until she sees an interesting photo of him.', 25, '2002-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 5, 'Mammary Lane', 'Doug''s bowling team prepares for a tournament, while Carrie agrees to babysit Mr. Kaplan''s son, in hopes of furthering her career. But when Doug throws out a mercy flirt and Carrie runs into an awkward set of hands, all goes downhill.', 25, '2002-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 6, 'Business Affairs', 'Doug stops by Carrie''s office and is introduced to her work-husband Curt. Although Carrie assures him that he has nothing to worry about since Curt is gay, Doug is threatened by just how close the two are.', 25, '2002-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 7, 'Flame Resistant', 'Carrie meets Doug''s ex-girlfriend Margy and is surprised to learn that Margy is still very close with Doug''s mother.', 25, '2002-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 8, 'Flash Photography', 'At a wedding, Doug takes a naughty picture with a disposable camera supplied by the bride and groom. After letting Danny take the blame, and after confessing to a priest, he has the dreaded task of coming forward with the truth.', 25, '2002-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 9, 'Connect Four', 'Carrie wins four company seats to Knicks games, but insists on taking a couple over Doug''s friends. Meanwhile, Arthur digs himself a hole by pretending he can "fix" parking tickets.', 25, '2002-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 10, 'Loaner Car', 'Doug loans Carrie to Deacon to help prepare Thanksgiving dinner. When Deacon ditches her for Holly''s services, his web of lies soon gets out of control. Trying to cover it up, Doug continues to dig a hole for himself.', 25, '2002-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 11, 'Mentalo Case', 'A toy from their childhood leads to a rift between Deacon and Doug. Meanwhile, Carrie tries to give her father a great Christmas gift, but this proves hard to do when everyone thinks of the wrong gifts they are receiving, altering their original gift choices.', 25, '2002-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 12, 'Jung Frankenstein', 'Carrie thinks Doug needs professional help to control his excessive eating habits, so she persuades him to see a therapist. When Carrie sees Doug''s great inprovements, she asks the therapist to work on Doug''s other issues. Meanwhile, Arthur believes he''s addicted to nasal spray and fights to stay off of it.', 25, '2003-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 13, 'Attention Deficit', 'Doug becomes obsessed with his own Super Bowl party after learning that many of his friends will be attending a party thrown by a new co-worker. While Doug is focused on winning back as many guests as possible, Carrie complains that Doug doesn''t think about her enough during the day. Problems arise when Doug tries to throw the ultimate Super Bowl party and prove to Carrie he''s an attentive husband.', 25, '2003-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 14, 'Prints Charming', 'Doug and Carrie photos get mixed up with another couples. When Doug and Carrie look at the other couples photos, they find out that their lives aren''t as good as the others, so they try to do what are seen in the photos. Arthur''s new cellphone is in no use when no one calls him.', 25, '2003-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 15, 'Animal Attraction', 'Doug cannot spend time with Carrie on Valentine''s Day, because he has to deliver penguins, with Deacon, from one zoo to another. Meanwhile, Carrie and Holly go out, with Carrie giving Holly tips to land a man.', 25, '2003-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 16, 'Golden Moldy', 'Doug and Carrie are having fun on their vacation with their neighbors in St. Croix, but once Arthur calls with a quote on the current mold problem in the house, all is not so fun.', 25, '2003-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 17, 'S''Poor House', 'The mold problem in the Heffernan household grows and Doug and Carrie find out to fix the problem will cost them $12,000! Doug, with his tail between his legs, goes to his father to ask for the money, but hits a wall when he wants to know why he and Carrie don''t have it in the bank.', 25, '2003-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 18, 'Steve Moscow', 'Doug and Carrie try to get the Russian workers to repair their house, by going to extreme lengths of giving them vodka.', 25, '2003-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 19, 'Cowardly Lyin''', 'Carrie gets tickets to an opera but Doug doesn''t want to go so he has Deacon help him lie to get out of it. Carrie catches him in the lie which prompts Doug to confess to a series of lies he''s been hiding.', 25, '2003-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 20, 'Driving Reign', 'Danny asks Doug for a letter of recommendation at IPS so he can move up to being a driver like Doug. Since this idea does not appeal to Doug, Carrie decides she will write the letter and have Doug sign it.', 25, '2003-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 21, 'Clothes Encounter', 'Carrie can''t stop buying expensive clothes, and then returning them within a few days. Spence''s new girlfriend is afraid of his dog and tells him to decide who he wants, the dog or her.', 25, '2003-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 22, 'Queens''bro Bridge', 'Arthur and his half-brother Skitch are reunited when Doug sets it up for them to meet again at the tollbooth Skitch works at on the freeway. When Doug realizes they own a house together, he sees the possibility of getting his basement back and he and Carrie having some personal time.', 25, '2003-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 23, 'Dog Shelter', 'Carrie learns from Janet that Doug had a dog when he was 11, that they still have today, and Doug is 38! Janet admits to Carrie that the dog died, and they replaced it without Doug knowing.', 25, '2003-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 24, 'Taste Buds', 'Since Doug never gets what he wants from Carrie, he uses Arthur to ask Carrie for them, so he gets what he wants. Meanwhile, Spence is first on line to see a new movie.', 25, '2003-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 5), 25, 'Bed Spread', 'After Doug breaks their bed, Doug and Carrie find temporarily having separate beds is improving their marriage. Arthur discovers that their sweet neighbor, Lou Ferrigno, is actually quite a gossip.', 25, '2003-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 1, 'Doug Less (1)', 'The sixth season opens with a newly svelte Doug and a surprisingly jealous Carrie, who just can''t hide her disdain when people constantly compliment her hubby on his weight loss. Doug decides to suprise her by taking her to an old holiday spot of theirs.', 25, '2003-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 2, 'Doug Less (2)', 'Doug surprises Carrie with a romantic weekend away at a resort. Doug and Carrie try to get over an argument they''ve been having, but only make things worse. Deacon finds Spence and Danny in bed together. Arthur decides he is in an emergency situation.', 25, '2003-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 3, 'King Pong', 'When Arthur handily beats Doug in several games of ping-pong, Doug decides to test his skills on Carrie, but is humiliated when he loses once again. In a desperate attempt to keep his ego intact, he asks Arthur to train him so that he can beat his wife.', 25, '2003-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 4, 'Dreading Vows', 'Endless complications make Doug and Carrie quickly regret their decision to renew their wedding vows. In the midst of the wedding planning Arthur is praying that his wedding present, aged Port wine, will go unused when he discovers the value of the fine wine on E-bay.', 25, '2003-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 5, 'Nocturnal Omission', 'Doug and Carrie don''t agree on whether to tell Deacon, who''s planning a night with a gorgeous stewardess he just met, that Kelly wants to reconcile.', 25, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 6, 'Affidavit Justice', 'When the partners of Carrie''s law firm notice Doug''s softball skills, they ask him to pretend that he''s a lawyer in order to play on their company team. Carrie worries that Doug won''t be able to pull off being a lawyer, but he is so convincing, an opposing firm offers him a job.', 25, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 7, 'Secret Garden', 'Carrie fears that her new gynecologist will drop her as a patient after she recommends Danny do some landscaping for him and Danny overcharges the doctor for the work.', 25, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 8, 'Eggsit Strategy', 'Carrie hears that her law firm is laying off people and worries about her job, though her resigning boss is only worried about getting an omelette bar goodbye party. Meanwhile, Doug is in hot water with Deacon when he loses the koosh ball Deacon received from his son as a gift.', 25, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 9, 'Thanks Man', 'It''s Thanksgiving in the Heffernan household and while Carrie cooks dinner for ten people, Doug lets a stranger into the house to use the phone. He is convinced the stranger is a nice guy but Carrie is not so trusting.', 25, '2003-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 10, 'American Idle', 'With Doug on her back over her lack of motivation in finding a new job, Carrie enlists the help of Arthur and opens up her own company making decorative cell phone covers, then forces her friends to come to a showing.', 25, '2003-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 11, 'Santa Claustrophobia', 'Doug finds it unbearable working with Carrie when she takes a temporary job at his company during the holidays. Arthur tries to get various friends to pose for a Christmas card picture with him.', 25, '2003-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 12, 'Dougie Houser', 'In flashbacks, Doug and Carrie recall buying their house almost 10 years earlier and how it was mainly Carrie''s decision because Doug preferred a different place.', 25, '2004-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 13, 'Frigid Heirs', 'Arthur wins $2,500 at a bingo game, and agrees to share some of his winnings with Doug and Carrie. Unfortunately, Arthur feels that he should decide how they will spend their portion.', 25, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 14, 'Switch Sitters', 'After countless times of babysitting Deacon and Kelly''s children, Doug and Carrie feel that Deacon and Kelly should return the favor and babysit Arthur every once in a while.', 25, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 15, 'Cheap Saks', 'Though she quickly realizes why Doug dumped her so long ago, Carrie stays friends with his former girlfriend to take advantage of her employee discount at Saks Fifth Avenue.', 25, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 16, 'Damned Yanky', 'Carrie''s infuriated when Doug sleep-talks about women while anesthetized, so she comes up with a proscribed list of women for Doug''s daydreams.', 25, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 17, 'Multiple Plots', 'When Arthur tries to sell Spence his adjoining burial plot, he winds up selling it to Spence''s mother, Veronica. Doug is assigned a new delivery route and is freaked out by a man at one of his daily stops who always answers the door wearing nothing but a towel around his waist.', 25, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 18, 'Trash Talker', 'Doug and Deacon''s relationship hits a speed bump when Deacon unknowingly befriends Doug''s grade school archenemy.', 25, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 19, 'Precedent Nixin''', 'Carrie asks Deacon and Kelly to accompany her and Doug to Florida for their visit with the in-laws so that they''ll be forced to stay at a hotel instead of with Doug''s parents, prompting a guilt-trip from Janet.', 25, '2004-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 20, 'Foe: Pa', 'Doug must heal the breach between father and daughter when Arthur ruins Carrie''s job interview at a prestigious real-estate development firm by making a nuisance of himself in the company''s lobby.', 25, '2004-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 21, 'Tank Heaven', 'Doug sabotages Carrie''s attempts to start hanging out with her co-workers by scaring them off with several crude techniques. Meanwhile, Spence and Danny realize that women like men who take care of the elderly and start using Arthur as bait.', 25, '2004-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 22, 'Alter Ego', 'What starts out as a valiant effort to win back the heart of Spence''s ex-girlfriend, Denise, quickly goes south as Danny gets a sudden case of lockjaw and the group spends all the money they took out as cash advances from their credit cards.', 25, '2004-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 23, 'Icky Shuffle', 'A bedridden Carrie gets Doug to team with Arthur for a shuffleboard tournament, but his skills aren''t to Arthur''s liking. Meanwhile, Carrie pretends to continue being sick so that Holly will continue to cook for her.', 25, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 6), 24, 'Awful Bigamy', 'After Holly gets kicked out of her apartment, Arthur insists that she stay with him in the basement until she finds a new place, making Doug realize the benefits of having two women in his life.', 25, '2004-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 1, 'Lost Vegas', 'In an attempt to go to Las Vegas for a weekend with the guys, Doug begins to build up credit by taking Carrie to a spa. Meanwhile, after hearing about Las Vegas, Arthur trains Spence on how to count cards, before visiting a small casino, being held for orphans.', 25, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 2, 'Dugan Groupie', 'Carrie and Doug have a conflict of interest when Carrie begins to stay late every night at work but it leaves Doug to feel neglected.', 25, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 3, 'Furious Gorge', 'On the way to a overeating support group, Doug notices an abusive relationship group,  and decides to join them instead. Although, Carrie becomes suspicious when he not only gains weight, but begins to cower in her presence.', 25, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 4, 'Entertainment Weakly', 'Doug''s position as the "Funny Guy" is threatened, when IPS'' new employee wins over the workforce with his impersonations. Meanwhile, an assistant is hired to work for Carrie, and ends up performing more work than expected.', 25, '2004-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 5, 'Name Dropper', 'Doug digs a deeper hole for himself when he fakes a heart attack to avoid angering Carrie for not knowing her friend''s name.', 25, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 6, 'Offtrack... Bedding', 'Doug''s parents pay a visit to the Heffernan household, where Doug surprises them with theater tickets. However, Joe Heffernan is distracted by his Train Fair, which causes Janet to develop a friendship with Arthur.', 25, '2004-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 7, 'Silent Mite', 'While Christmas shopping at the mall, Doug loses his wallet and begins a quest to find the wallet and the culprit who may have stolen it. But with no help from Carrie or the cops, he requests the help of Arthur.', 25, '2004-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 8, 'Awed Couple', 'While Doug and Carrie are at dinner with Neal and Marcy, they are introduced to Marc and Renne, with whom they have an instant connection.', 25, '2004-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 9, 'Cologne Ranger', 'After ten years of marriage, Doug finds a new love – in the form of designer cologne that Carrie can''t stand, but his scent-ual affair forces Carrie to demonstrate bad behaviors of her own. Meanwhile, Arthur attempts to show Spence and Holly the finer points of movie hopping.', 25, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 10, 'Domestic Disturbance', 'Carrie uses her extra income to hire a maid, but Doug feels left out and decides to hire his own help in the form of Spence''s mom, Veronica. Soon, Veronica proves to make more messes than she cleans, especially when her newly subordinate position makes Arthur pine for her.', 25, '2005-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 11, 'Pour Judgment', 'Doug decides to pursue a long-abandoned dream to become a bartender, much to Carrie''s angst.  Although she starts to warm up the the idea, Doug soon realizes that dreams are not always what they are cracked up to be.  Meanwhile Arthur enters the dangerous world of politics.', 25, '2005-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 12, 'Gym Neighbors', 'When the Heffernans begin working out with the Ferrigno''s, Doug secretly makes a pact with Lou so he can sit around instead of working out.', 25, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 13, 'Gorilla Warfare', 'Carrie recalls what Doug said to her when they were dating that made her want to marry him, but then she learns a horrifying truth about that night; Danny falls for Holly after his girlfriend breaks up with him', 25, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 14, 'Hi, School', 'When delivering a package to his old high school, Doug meets his old football coach, and against Carrie''s wishes, begins to return to the school on a regular basis as the football hero.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 15, 'Deconstructing Carrie', 'Carrie is discouraged about her looks as she faces her 35th birthday so Doug gets construction workers to hoot and holler at her as she passes by in hopes of cheering her up. Also, Arthur tries to come up with a perfect gift for his daughter.', 25, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 16, 'Black List', 'When Deacon snubs his usual boys for a new African-American friend, Doug desperately tries to find his own "roots" in an attempt to win him back.  Meanwhile, Carrie runs her cuticles ragged to find out why her manicurist will no longer schedule her appointments.', 25, '2005-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 17, 'Wish Boned', 'What starts out as a great trip quickly turns into a nightmare as Doug and Arthur are forced to switch planes, which puts them in Pittsburgh instead of St. Louis.', 25, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 18, 'Van, Go', 'While eating at a new cafe with Deacon, Doug manages to agitate their waitress so much that she demands they fight once her shift ends. Meanwhile, Carrie asks Holly to go shopping with her, only so that she can use her van.', 25, '2005-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 19, 'Ice Cubed', 'When a checkout girl is distracted making personal calls and accidentally doesn''t charge Carrie for her digital music player, Carrie walks out the store with free merchandise.', 25, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 20, 'Catching Hell', 'A work event in a ballpark skybox leads Carrie, Doug and his buddies out to the game - but when an important client finds fault with Doug, Spence has to step in as the devoted husband. At Arthur''s dinner party, guest Bernard, turns the table against him.', 25, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 21, 'Slippery Slope', 'Doug lures Carrie to a timeshare sales ski weekend where the strength of their relationship is tested under the intense sales pressure. On the same excursion, Spence and Danny feel the sting of intolerance when they assume the role of a "couple" to enjoy the weekend.', 25, '2005-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 7), 22, 'Buy Curious', 'Doug reluctantly agrees to Carrie''s idea to "flip" their deceased neighbor''s house but doesn''t hesitate to blame her when the cost of the much-needed home improvements start to add up.', 25, '2005-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 1, 'Pole Lox', 'Doug convinces Carrie to take pole dancing lessons, but is disappointed when she puts on a show for him. Meanwhile, Arthur worries her new hobby is a result of his poor parenting, and smothers her in effort to make up lost time.', 25, '2005-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 2, 'Vocal Discord', 'When Doug and Carrie accidentally get a transcription of one of their arguments, they decide marriage counseling might not be a bad idea. And when Arthur gets hold of it, their argument becomes entertainment for a senior citizens'' group.', 25, '2005-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 3, 'Consummate Professional', 'Carrie finds out that while dating, Doug lied about getting a job to get her to sleep with him.', 25, '2005-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 4, 'Like Hell', 'Doug and Carrie both have feelings of not being entirely popular at their workplaces, and both overcompensate to rectify the situation', 25, '2005-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 5, 'Sandwiched Out', 'A sandwich named for Deacon at Coopers ruffles Doug''s feathers. Meanwhile, Carrie schemes to prevent Holly from moving to Manhattan.', 25, '2005-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 6, 'Shear Torture', 'Doug''s frequent hair salon visits make Carrie suspicious. Meanwhile, Spence has his own adventures en route to a sci-fi convention.', 25, '2005-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 7, 'Inn Escapable', 'A trip to a bed & breakfast becomes more than Doug and Carrie can handle. Meanwhile, Arthur has a romantic dilemma of his own.', 25, '2005-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 8, 'Move Doubt', 'Doug and Carrie hear conflicting reasons why Deacon and Kelly are not interested in becoming neighbors. Meanwhile, Danny and Spence each have their eye on a beautiful Albanian girl, who misinterprets the situation.', 25, '2005-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 9, 'G''Night, Stalker', 'Doug''s karaoke performance gets him an e-mail stalker.', 25, '2005-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 10, 'Raygin Bulls', 'Doug and Ray Barone have a "guy''s night out." Meanwhile, Carrie gets a shock upon visiting her mother''s grave.', 25, '2005-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 11, 'Baker''s Doesn''t', 'Doug and Carrie are roped into helping out at their church during the holidays: he guards the manger, while she tries to bake a cake.  Also, Arthur and Spence attempt to write a Christmas song so they can cash in on the holiday.', 25, '2005-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 12, 'Fresh Brood', 'Doug borrows a baby from Danny to prove to Carrie that they''re ready for a family. Meanwhile, Arthur feels he deserves to be a coffee shop''s "customer of the month."', 25, '2006-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 13, 'Gambling N''Diction', 'After she beats him and his friends in a friendly poker game, Doug convinces his mother to try to enter a high-stakes tournament. Meanwhile, Carrie gets Spence to help her lose her accent to improve her chances of getting a promotion.', 25, '2006-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 14, 'Apartment Complex', 'Doug and his pals rent an apartment to use as a secret hang-out. Meanwhile, Carrie goes to great lengths to please her newest client, Kirstie Alley.', 25, '2006-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 15, 'Buggie Nights', 'Bed bugs brought home by Arthur from a vacation force Doug and Carrie out of the house while a creepy exterminator does his job. Meanwhile, Spence and Danny argue over where to go for vacation.', 25, '2006-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 16, 'Knee Jerk', 'After Carrie accidentally injures Doug, he milks it to avoid distasteful tasks. Meanwhile, Arthur catches on to the ruse, and uses it to his advantage.', 25, '2006-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 17, 'Present Tense', 'The Heffernans hate an anniversary gift from the Palmers so much, they stage a robbery to rid themselves of it.', 25, '2006-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 18, 'Sold-Y Locks', 'In order to afford a cruise, Doug convinces Carrie to cut her hair to sell to a wig maker, but regrets his idea after the deed is done.', 25, '2006-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 19, 'Emotional Rollercoaster', 'Doug''s lie to get Carrie to let him ride a rollercoaster at an amusement park blows up in his face. Meanwhile, Arthur lets Deacon shuttle him around in a wheelchair so they can jump to the front of the park''s lines and Danny and Spence search for girls to pick up.', 25, '2006-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 20, 'Four Play', 'One night at the movie theatre, Doug and Carrie can''t decide on which film they want to see. They run into Deacon and Kelly and it turns out Kelly wants to see what Doug wants to see and Deacon likes the movie that Carrie likes.', 25, '2006-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 21, 'Hartford Wailer', 'Doug crashes Carrie''s weekend company retreat, not realizing she''s blown it off for a relaxing day with her girlfriends. Meanwhile, Danny and Spence pose as staff to sneak into a Huey Lewis concert.', 25, '2006-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 22, 'Fight Schlub', 'Doug befriends a driver from one of IPS'' competitors, but eventually discovers it''s just a ruse to make him the butt of a joke. Meanwhile, Carrie becomes a mentor for a troubled teen, but isn''t the best of influences.', 25, '2006-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 8), 23, 'Acting Out', 'After he sets a fire in the basement, Carrie decides it''s time for Arthur to enter a retirement home, but Doug makes a discovery that makes him want to change Carrie''s mind. Danny and Spence have a face-off over an agreement to swap bedrooms.', 25, '2006-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 1, 'Mama Cast', 'Doug decides to spend the Heffernans'' tax refund on an ice cream truck. Meanwhile, Carrie fills in as a pretend mom at model homes, and discovers a reemergence of her maternal desires.', 25, '2006-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 2, 'Affair Trade', 'Doug panics when he starts getting sexy phone messages meant for another Doug Heffernan, but Carrie doesn''t seem to care.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 3, 'Moxie Moron', 'Doug and Deacon fill in for Supervisor O''Boyle at the IPS depot. Carrie regrets her decision to complain about her company''s chinzy gift for work on an important project.', 25, '2006-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 4, 'Major Disturbance', 'The Palmers'' vacation plans are ruined when Doug frightens Major so much that he refuses to be babysat by the Heffernans. In the meantime, Arthur begins hiring out himself and friends from the senior center to ride with solo drivers so they can use car-pool lanes.', 25, '2006-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 5, 'Ruff Goin''', 'Feeling hurt over not being invited to a block party, Doug adopts a dog just to prove to the neighbors that he''s an okay guy-a decision he soon regrets. Meanwhile, Arthur falls prey to the gambling bug when trying to help Danny beat it.', 25, '2006-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 6, 'Brace Yourself', 'An unflattering picture by Major prompts Arthur to ask Doug and Carrie for braces. Meanwhile, Kelly hires an out-of-work Spence to help out around the house.', 25, '2007-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 7, 'Home Cheapo', 'Carrie is convinced that Deacon and Kelly were only able to afford a vacation home by being cheap. Meanwhile, Arthur tries to help Spence get a new job.', 25, '2007-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 8, 'Offensive Fowl', 'Carrie soon grows tired of Doug''s forcing his new vegetarian lifestyle down her throat. Meanwhile, Carrie''s boss wants to start discussing novels with her and Spence takes on some humiliating new jobs.', 25, '2007-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 9, 'Mild Bunch', 'Doug''s 20th high school reunion seems like a dud until an old friend comes up with a way to retaliate for a past grievance with their old principal.', 25, '2007-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 10, 'Manhattan Project', 'Carrie''s ecstatic when an affordable apartment opens in Manhattan, but Doug''s reluctant to leave Queens. Arthur meets singer Ava St. Clair.', 25, '2007-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 11, 'Single Spaced', 'Seeing friends who recently had a child makes Doug and Carrie consider adopting.', 25, '2007-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165581')) AND numero_temporada = 9), 12, 'China Syndrome (1)', 'Doug and Carrie''s marital tension continues, as they ponder whether they have a future together. Arthur and Ava''s wedding day turns problematic.', 25, '2007-05-14');
