INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 1, 'That ''70s Pilot', 'While Eric Forman is swiping beer for his best friends Donna Pinciotti, Michael Kelso, and Steven Hyde, his parents Red and Kitty hint that he may be getting the old Vista Cruiser.  Now Eric can drive all of his friends – including the new foreign exchange student, Fez – to a Todd Rundgren concert in Milwaukee.  A minor snag occurs when Kelso''s obnoxious girlfriend, Jackie Burkhart, finds out and invites herself along.  An even bigger snag occurs when Red tells Eric that he can''t drive the car out of Point Place.', 23, '1998-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 2, 'Eric''s Birthday', 'Eric''s 17th birthday is coming up and he really doesn''t want a party.  Unfortunately, it''s extremely obvious that Kitty is planning a surprise party against his wishes – she''s even invited his older sister Laurie home from college for the event.  Eric enlists Laurie''s help in calling off the party while Kelso naively tries to attract her interest.  And Donna, who''s unsure about the state of her relationship with Eric, gets advice from Jackie on what to get him for a gift.', 23, '1998-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 3, 'Streaking', 'President Ford comes to Point Place; Red is chosen to ask him a question, but struggles as he tries to speak.  Eric and the guys welcome the President by streaking.  Donna has to wear an American flag jumpsuit Bob gave her.', 23, '1998-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 4, 'Battle of the Sexists', 'Red''s hours at the plant are cut, so he fills his free time fixing things around the house, much to Kitty''s dismay.  Donna beats Eric at basketball, which sets off series of contests between them.  Midge and Kitty each give their kids some pointers on harmonious relationships.  The guys tease Kelso for being "pig-whipped" by Jackie.', 23, '1998-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 5, 'Eric''s Burger Job', 'With her parents going to the Playboy Club over the weekend, Donna drops Eric some unsubtle hints that she wants to hang out alone with him.  Unfortunately, Eric is so preoccupied with getting a job at the new Fatso Burger that he completely misses her signals.  Kelso gets the idea to throw a toga party at the Pinciotti house, but Donna''s less than enthused about the prospect.  As for Eric, he quickly finds that work eats up a lot of his free time.', 23, '1998-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 6, 'The Keg', 'Eric skips school with Donna, Hyde, and Kelso for the first time in his life.  Unbelievably, the gang finds a keg in the middle of the road and sees it as a sign that they should throw a party.  Problems arise, however, when they all realize that there''s no beer tap after the party is in full swing.  Meanwhile, Red and Bob have their suspicions about what the kids are up to and launch a full scale search of Point Place.', 23, '1998-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 7, 'That Disco Episode', 'The kids decide to go to a disco but Steven doesn''t know how to dance so Mrs. Forman teaches him to dance. Mr. Pinciotti walks in on them in a compromising position and believes they''re having an affair. Kelso gets jealous of Fez because he thinks he''s putting the moves on Jackie.', 23, '1998-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 8, 'Drive-In', 'Eric and Donna go to the drive-in. Eric doesn''t want Kelso and Jackie to go because they''d be competition but Donna invites them anyway. Fez''s house parents think he''s listening to the devil''s music (a copy of Kiss'' Destroyer album). Red and Kitty spend the evening out and almost get arrested.', 23, '1998-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 9, 'Thanksgiving', 'Laurie comes home for Thanksgiving with her friend Kate.  Eric is annoyed that he''ll have to give up his room for their guest, until he sees how hot Kate is.  Jackie alerts Donna to the trouble she could be facing now that a college girl is sleeping in Eric''s bed.  Kitty tries vainly to avoid her mother-in-law''s phone calls as she prepares for Thanksgiving dinner.', 23, '1998-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 10, 'Sunday, Bloody Sunday', 'Red''s mother spends a Sunday with them and drives everyone crazy, except Fez. She seems to have a certain fondness for him.', 23, '1998-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 11, 'Eric''s Buddy', 'Eric has a new friend and Steven and Kelso can''t stand it. Steven doesn''t like him because he''s rich and Eric doesn''t give him a ride home anymore because Buddy has a Trans Am. Kelso, on the other hand, seems like a worried spouse. Eric starts to feel uncomfortable around him however when Buddy makes a move on him. Buddy apparently thought that Eric was also gay. And Red makes his first sale.', 23, '1998-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 12, 'The Best Christmas Ever', 'Red gives Eric 40 bucks to buy a Christmas tree and says that he can keep the change for his party. So Eric, Hyde and Kelso cut down a tree off the interstate and keep the money. They spend the money on beer and Kelso buys Jackie a Christmas present. Laurie spikes the punch with rum and Jackie''s friend''s are all attracted to Fez all of the sudden. Red has to work on Christmas Eve and not long after he gets home cops show up at his door telling him that his Christmas tree was illegally obtained and that they have to confiscate it. Also Hyde has a thing for Donna.', 23, '1998-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 13, 'Ski Trip', 'Jackie dumps Kelso after he makes out with Pam Macy and invites everyone but him to her parent''s ski cabin for the weekend.  Eric, excited about what this could mean for him and Donna, pays no attention to Kelso''s whining about being left behind or Red''s tips about driving in the snow.  He doesn''t realize that Hyde keeps hitting on Donna and Kelso plans on following them to the lodge.  Also, Kitty gets mad at Red over a past indiscretion and Fez has his first experience with snow.', 23, '1999-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 14, 'Stolen Car', 'When Eric scratches the car, Red suspends his driving privileges, so the gang has to walk everywhere. That is, until Kelso''s cousin lends him a car. They get arrested though because the car was reported stolen. With one phone call, Kelso calls Jackie and she tells him that she''ll have sex with him once he gets out of prison. The whole incident was a mix-up and the gang is released.', 23, '1999-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 15, 'That Wrestling Show', 'Kitty thinks that it would be a good idea if Red and Eric become friends.  She forces Eric to invite Red to go with the gang to a wrestling event in Kenosha.  Bob tags along and seeks help from Fez and Hyde over Midge''s decision to start therapy.  And Jackie is super nice to Kelso now that they''ve done the deed.', 23, '1999-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 16, 'First Date', 'Valentine''s Day is coming up, so Eric decides to ask Donna out on their official first date and give her his class ring.  She breaks her study date with Hyde in order to go, leading Hyde to realize he only has one last chance with her.  Red and Kitty discover they don''t have that much in common with Bob and Midge anymore.  And Jackie explains to Kelso how things are going to work now that they''ve "proven their love" to each other.', 23, '1999-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 17, 'The Pill', 'Since no one else is around, Jackie confides in Eric that she thinks she might be pregnant.   Eric passes the news on to Donna, who tries to get Jackie to tell Kelso.  The incident inspires Donna to go on birth control pills.  Her decision inadvertantly causes Eric a lot of grief when Bob and the Formans find out.', 23, '1999-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 18, 'Career Day', 'It''s career day and the gang must spend the day working with their parents.  Eric goes to the hospital with Kitty and is amazed at all she has to deal with every day.  Fez accompanies Hyde and interviews cafeteria lady "Gross Edna" while mother and son feud.  Poor Michael spends the entire day trying to figure out what his dad does, while Donna is mortified by Bob''s crazy promotional antics.  And Red finally finds one of Eric''s friends he likes: Jackie.', 23, '1999-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 19, 'Prom Night', 'Prom night is fast approaching and Eric gets a motel room as part of his "spontaneous" plan to "do it" with Donna on the big night.  When Jackie finds out that Kelso asked slutty Pam Macy to prom, she gets Hyde to take her out of pity.  Fez wants to take his pretty English teacher to the prom.  As for the adults, they struggle with how to respond to Midge''s idea for her future career.', 23, '1999-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 20, 'A New Hope', 'The guys go see Star Wars and are all completely blown away by it.  Red asks Eric to hang out with his boss''s son now that he''s started working at the plant full-time again.  David was an awkward kid the last time Eric saw him, but now he''s a hunk who likes reading Donna''s short stories.  Also, Laurie starts hitting on Kelso out of boredom.', 23, '1999-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 21, 'Water Tower', 'The guys paint a pot leaf on the water tower and Kelso falls off trying to fix it because everyone thinks it looks like the finger. Instead of going to the hospital they go to Eric''s cause his mom''s a nurse. When Eric goes to get her he walks in on his parents having sex. Having trouble sleeping and not being able to look his parents in the eyes leads his parents to believe he''s on drugs.', 23, '1999-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 22, 'Punk Chick', 'Hyde meets a girl who''s the female version of him. She tries to convince him to go to New York with her but he decides that it would be best if he stayed behind. Kelso and Red make smaller paddles for Pong. Fez feels left out of everything. Jackie tries to bake a pie for home economics project, but she ruins it every time.', 23, '1999-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 23, 'Grandma''s Dead', 'Red''s mother Bernice has once again managed to make everyone miserable during one of her visits.  While driving his grandmother home, Eric lashes out and tells her that it wouldn''t kill her to be nice once in a while.  Bernice promptly drops dead, leaving Eric to think he killed her.  The entire Forman family (including Laurie and Red''s brother Marty) comes together for her funeral while Eric gets drunk at a bar with the guys.', 23, '1999-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 24, 'Hyde Moves In', 'The gang goes skinny-dipping and Jackie gets sick. Hyde moves in with the Formans when his mom runs away with a trucker. Bob takes a liking to one of Midge''s feminist friends.', 23, '1999-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 1), 25, 'The Good Son', 'Eric loves having Hyde as a "brother" because he does all of Eric''s chores but when his parents start to prefer Hyde he starts to hate him. Hyde changes from the conspiracy minded trouble-making guy Eric loves to a total bore. Midge and Bob are having relationship problems. Red''s old war buddy comes back and Red finds out that he''s a swinger.', 23, '1999-07-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 1, 'Garage Sale', 'The Foreman''s have a garage sale and Hyde makes "special brownies" to help out. When Red, Kitty, Bob, and Midge accidentally eat a plate of the brownies, a stoned Red sells the Vista Cruiser.', 23, '1999-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 2, 'Red''s Last Day', 'It''s Red''s last day of work, and he decides to drown his unemployment sorrows at a bar.  Kitty sends Eric to pick Red up; he, Hyde and Fez end up drinking with Red instead, leaving none of them in any condition to drive.  Kelso gets a van, and christens it the "shaggin'' wagon."', 23, '1999-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 3, 'The Velvet Rope', 'Now that he''s unemployed, the job hunt is on for Red.  The gang decides to go to a dance club, and Jackie manages to convince Kelso that dressing like David Bowie is a good idea.  Once at the club, Donna, Fez and Hyde have no problem getting in, but Eric can''t make it past the overly large bouncer.', 22, '1999-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 4, 'Laurie and the Professor', 'Bob and Midge''s marital troubles spill over into a fight over Donna''s affection.  One of Laurie''s college professors comes to Point Place to see if he can convince Laurie to return to classes, and he takes a ''hands-on'' approach to the task, much to Eric''s shock.  Fez looks for a woman, and Hyde looks for a room to sleep in.', 23, '1999-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 5, 'Halloween', 'The gang, looking for something fun to do on Halloween, revisits their old grammar school, where they find their permanent records. Looking through them, they find out some interesting things about each other. Fez discovers trick or treating.', 23, '1999-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 6, 'Vanstock', 'Eric, Donna, Kelso, Hyde and Fez are all going to Vanstock, Wisconsin''s own Woodstock. Jackie says she doesn''t want to go, so Kelso invites Laurie. In the end, both girls go leaving Kelso stuck in the middle. Donna gets mad at Eric for not telling her about Kelso and Laurie. Fez spends the night girl chatting to Jackie and Laurie, much to Kelso''s chagrin while Hyde attempts drop him in it. Red becomes addicted to soaps.', 23, '1999-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 7, 'I Love Cake', 'Eric freaks out when Donna says ''I love you,'' and all he can think of to say in return is ''I love cake.''  Donna, not knowing how to deal with this, turns to Jackie for relationship advice.  Midge kicks Bob out of the house; he stays with the Formans and Red has to act as a go-between to try to mend their marriage.  Kelso gets a new leather jacket that he thinks makes him look like Marlon Brando, but the everyone else thinks he looks like the Fonz.', 23, '1999-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 8, 'Sleepover', 'Donna finally sleeps with Eric, but when the guys find out that all they did was sleep, they tease him mercilessly.  Hyde gets a job at the FotoHut, and finds out that compared to his boss, he''s a workaholic.  And Kitty has to work double shifts at the hospital, leaving Red to do the cooking.', 22, '1999-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 9, 'Eric Gets Suspended', 'Donna is acting out over her parents'' break up and takes up smoking. Eric gets caught holding one of her cigarettes in the school yard and is suspended. Even though Eric tries explaining what really happened, Red punishes him. Fez and Hyde go on a double date, set up by Fez''s host parents; Hyde can''t decide which girl he likes better. Jackie and Kelso argue over how many stuffed animals she can have in his van.', 22, '1999-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 10, 'Red''s Birthday', 'It''s Red''s birthday and the roof collapses so Eric gets him some 2 x 4s to fix it. Bob and Midge take Red and Kitty out for dinner but they each bring a date and ditch them to do it in the car. Eric is mad at Donna for talking to Hyde about her parent''s problems instead of talking to him.', 22, '1999-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 11, 'Laurie Moves Out', 'Laurie moves out and Red is annoyed when he finds out she moved in with a guy instead of with a girlfriend like she told him. She then moves back in when the guy goes back to his wife. Jackie suspects Kelso of being unfaithful.', 22, '1999-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 12, 'Eric''s Stash', 'Eric''s secret stash of money goes missing, and Hyde is the first and only suspect.  Hyde denies taking it, and everyone is shocked when the real culprit is revealed.  Fez and Kelso help Jackie prepare for a beauty pageant.', 22, '2000-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 13, 'Hunting', 'Red and Bob take the guys deer hunting; Hyde chills out, Fez bags dinner using only a few primitive weapons, Kelso is a menace with his gun, and Red and Eric bond in the deer blind. Meanwhile, Kitty and Midge have a girls'' night with Donna, Jackie and Laurie, but with nothing to talk about, the end up playing poker.', 22, '2000-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 14, 'Red''s New Job', 'Eric gets a job at Price Mart as a cashier while Red gets one as a supervisor. Kelso tries to break up with Laurie because she wants a real relationship but Laurie threatens to tell Jackie about her and Kelso.', 22, '2000-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 15, 'Burning Down the House', 'With her parents away, Jackie plans on throwing a small, classy dinner party.  Kelso tries to turn it into a fun party, and invites everyone he knows; Jackie is upset, and when Kelso tries to fix things, he only ends up making them worse.  Hyde makes it with a snobby girl from school, but the guys don''t believe him.  Red finds out that Bob wears a toupee, and then has to spend an uncomfortable evening not talking about it.', 22, '2000-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 16, 'The First Time', 'Bob and Midge renew their wedding vows, with Donna writing the words and Red as best man. But Kitty is left out, until a bridesmaid gets lost in passion.', 22, '2000-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 17, 'Afterglow', 'Contrary to what she tells Eric, Donna''s review of their first sexual encounter is not good--or private; Red celebrates his first paycheck and buys a motorcycle.', 22, '2000-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 18, 'Kitty and Eric''s Night Out', 'Jackie misses Fez''s attention when he gets a girlfriend, who passed up Hyde; Eric and Kitty go to a movie together.', 22, '2000-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 19, 'Parents Find Out', 'Kitty is devastated after the police catch Donna and Eric having sex in the Vista Cruiser.', 22, '2000-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 20, 'Kiss of Death', 'Eric lies after accidentally running over Donna''s cat; Laurie sets Kelso up for a fall; Fez sees "Fez''s Angels" while under anesthesia to have his appendix removed.', 22, '2000-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 21, 'Kelso''s Serenade', 'Kelso tries to win Jackie back with a song; Kitty drags the family to see elderly Aunt Pearl; Donna thinks Eric takes her for granted.', 22, '2000-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 22, 'Jackie Moves On', 'Fez finally has a date with Jackie, but not the same Jackie he''s coveted; Eric and Laurie have a war of embarrassing secrets; and Kitty reveals her secret about Red''s mother''s necklace.', 22, '2000-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 23, 'Holy Crap!', 'Kitty calls on a divine power, of sorts, when Eric and Laurie forsake going to church; Kelso''s budding beard stirs Jackie.', 22, '2000-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 24, 'Red Fired Up', 'Eric appreciates another employee who draws Red''s ire away from himself; Kelso and Laurie date openly, and receive separate cautions from Hyde and Kitty.', 22, '2000-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 25, 'Cat Fight Club', 'Hyde helps Jackie take a Zen approach to Kelso and Laurie, who introduce their relationship to Red at the Forman dinner table.', 22, '2000-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 2), 26, 'Moon Over Point Place', 'Donna moons in a yearbook picture; Jackie claims Hyde as her new best friend; Kitty "clears the air" about Eric and Donna having sex.', 22, '2000-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 1, 'Reefer Madness', 'Hyde returns from jail only to find Red beyond furious and ready to kick him out of the house. Afraid that he''ll turn the other kids into dope fiends, Red asks Eric if Hyde has ever pressured him to do drugs in the past. Eric wonders if he should confess the truth to Red in order to keep him from forcing Hyde out. Elsewhere, Leo visits the Formans to speak on Steven''s behalf while Donna uncovers the reason behind Jackie''s new found obsession with Hyde.', 21, '2000-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 2, 'Red Sees Red', 'As punishment for being "dope-heads", Red gives Eric and Hyde a curfew.  Laurie is all for it until she discovers that it applies to her too.  Red booby-traps the house so that he''ll know if there are any escape attempts, and keeps increasing the discipline, despite Kitty''s pleas for leniency.  Jackie is still trying to convince Hyde that she''s the woman for him, but he''s not buying it.', 21, '2000-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 3, 'Hyde''s Father', 'The guys get into a bar without showing their fake IDs only to learn that the bartender is none other than Hyde''s father, Bud.  Kitty finds out about this and, against Hyde''s wishes and Red''s advice, invites Bud over in an attempt to set things right between father and son.  Meanwhile, Donna is disgusted when she finds out that Eric keeps dirty magazines under his bed.  And Fez tries to woo Donna and Jackie using suggestions he reads in Playboy.', 21, '2000-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 4, 'Too Old to Trick or Treat, Too Young to Die', 'A Halloween episode filled with parodies of Alfred Hitchcock movies: "Rear Window", "Vertigo", "The Birds", "North By Northwest" and "Psycho".', 21, '2000-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 5, 'Roller Disco', 'Jackie has wonderful news: there''s a roller disco competition in Kenosha and she wants Hyde to be her partner.  When she finds that he''s more than unwilling, she''s left with a choice between Kelso and Fez, and after seeing their moves, she chooses Fez.  This leaves Kelso less than happy, and more than a little jealous.  Red, meanwhile, is being sued by an ex-Price Mart employee for wrongful termination, and has to prove to the Labor Board that he''s not "unnecessarily angry."', 21, '2000-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 6, 'Eric''s Panties', 'Donna finds a pair of panties in the Vista Cruiser and thinks that Eric is cheating on her with his lab partner.  Everyone is in for a big shock when they find out who the panties really belong to.  Red''s doctor''s appointment shows that he has high blood pressure, so Kitty puts him on a strict diet, which he finds inedible.  Kelso gains a new nickname due to a mishap in the cafeteria.', 21, '2000-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 7, 'Baby Fever', 'Red is not happy when Kitty becomes obsessed with the idea of having another baby after bringing a friend''s child home for Laurie to baby-sit.  Laurie is completely at a loss on how to take care of a baby until her maternal instincts eventually kick in.  Donna gets mad at Eric for thinking that she''ll stay home with the children when they have their own.  And Hyde and Fez mediate a mock divorce settlement between Jackie and Kelso after Jackie crashes Kelso''s van.', 21, '2000-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 8, 'Jackie Bags Hyde', 'It''s Veteran''s Day and the Formans are getting ready for their annual barbeque after the town parade. Trouble is that Bob, who was only in the National Guard and never saw any action, has inexplicably decided to throw his own barbeque in competition with the Formans. Hyde tells Jackie point blank that he''s not interested, inspiring her to bring a date to the Formans'' to make him jealous. This ploy causes Hyde to come to a horrifying realization about his true feelings for Jackie.', 21, '2000-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 9, 'Hyde''s Christmas Rager', 'Living with Bud has some definite benefits; Hyde finds this out when he''s having his first Christmas party at Bud''s place, and Bud leaves the guys alone with a keg of beer.  Eric suffers the consequences of being bad at quarters, and has to be carried home, where Red and Kitty decide that Bud needs a talking to about proper parenting practices.  Meanwhile, Jackie is desperate for a boyfriend, and drags Donna out to a bar where they meet some interesting firemen.', 21, '2000-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 10, 'Ice Shack', 'Kelso''s new master plan to get Jackie back is to copy all the lovey-dovey things that Eric does for Donna.  To carry out this plan, he tricks the three of them into going to his uncle''s ice shack for the weekend.  But his plan hits a major snag when Fez tags along and does everything in his power to make Kelso look bad.  Back in Point Place, Kitty orders Red to talk to Laurie about her future, while Hyde – who''s on probation – gets pulled over while driving Leo and his suspicious brown paper bag.', 21, '2001-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 11, 'Who Wants It More', 'After an argument, Eric and Donna decide to withhold sex to see who''ll cave in first. Red is nearly killed by a falling tree and it changes his whole outlook on life. He starts being nice to people, even Fez, but he soon realizes that that''s not who he is. Kelso claims to have seen a UFO.', 21, '2001-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 12, 'Fez Gets a Girl', 'Fez has a crush on a girl but is too shy to approach her, so Donna sets them up together. Donna wins two tickets to see Led Zeppelin in concert but Eric can''t go because he has to work so she gives one to Fez and the other to Caroline, the girl that Fez has a crush on, because Kelso, Hyde and Jackie keep fighting over who she''s going to take. Eric is named Price Mart employee of the month and it goes to his head. Laurie uses Kitty as a hair model and Kitty doesn''t like the job she did but won''t tell her because Laurie wants to quit already after only two weeks in beauty school.', 21, '2001-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 13, 'Dine & Dash', 'Kelso invites the gang to an expensive dinner but skips on the bill, leaving Eric and Donna in the restaurant with no money. The two of them decide to shed their "square" personalities and get back at the gang. Bob is upset that Red didn''t offer him a job at Price Mart.', 21, '2001-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 14, 'Radio Daze', 'Donna gets a job at a radio station and Eric gets jealous because on the air she''s known as Hot Donna and supposedly single. Red gets Earl fired from Fatso Burger but Kitty makes him get Earl his job back. Leo wants to sell his car to Kelso but then changes his mind and gives it to Hyde.', 21, '2001-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 15, 'Donna''s Panties', 'Eric pulls Donna''s pants down in public and reveals her granny panties to everyone.  So he tries to make up by giving her sexy panties on Valentine''s Day. When Kelso finds out that Laurie cheated on him he realizes how Jackie must have felt when he cheated on her with Laurie; to Jackie''s surprise he doesn''t want her to feel sorry for him. Fez asks Caroline to go steady with him and only afterwards does he finds out that she has some strange ideas about romance.', 21, '2001-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 16, 'Romantic Weekend', 'Eric finds a brochure for a nice motel and plans a romantic weekend with Donna, who''s glad for the chance to get away from her feuding parents.  Both lie about their whereabouts to their parents.  But the lie blows up in their faces when they learn who their neighbors are at the motel.  Meanwhile, Kelso thinks that he''s not a man any more because he can''t perform with Pam Macy.', 21, '2001-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 17, 'Kitty''s Birthday (That''s Today?!)', 'It''s Kitty''s birthday and the only one who remembers is Hyde.  To make up for forgetting, Eric and Red agree to do the most horrifying thing imaginable. Meanwhile, Kelso plans to win Jackie back by being her friend, but it doesn''t work the way he thinks it would.  And Hyde learns something disturbing about Caroline when he drives her home in his new car.', 21, '2001-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 18, 'The Trials of M. Kelso', 'Jackie tests Kelso to see if she should get back together with him. Fez, Eric and Hyde vandalize an opposing school''s locker room because Fez was beaten up by their jocks. Kitty is angry at Bob and Midge for not inviting her and Red to their party until she finds out that Bob and Midge are nudists.', 21, '2001-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 19, 'Eric''s Naughty No-No', 'Kitty''s sister visits and Kitty thinks she''s only there to show off that she''s more successful. After going to see an X-rated movie, Eric tries a new move on Donna but it freaks her out; Kelso learns that honesty is the best policy.', 21, '2001-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 20, 'Holy Craps!', 'Kitty forces Red, Eric, Hyde and Kelso to help out at a church fundraiser. Red spends all of his time at the craps table, Kelso and Hyde cheat at bingo so they can win all the prizes. Eric is busy worrying about his relationship with Donna because a church member told him that his wife was nice too, when they first met, until they got tired of each other. Jackie and Donna tell Fez that Caroline is a psycho so he dumps her after she threatens him.', 21, '2001-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 21, 'Fez Dates Donna', 'Fez and Donna pretend to date so Caroline will leave him alone, but she stalks him anyways, until Fez tells her he doesn''t like her any more. Bob reads the deed to his house and discovers that he owns half of Red''s garage but Red sets him straight by turning the deed around and proving him wrong. Eric and Hyde have a pool going on when Kelso and Jackie will fight.', 21, '2001-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 22, 'Eric''s Drunken Tattoo', 'After reading an entry in Donna''s diary, Eric decides to get a tattoo, but things don''t turn out the way he planned.  Kitty has Pastor Dave over for dinner and he ends up in the hospital; Jackie tries to get Kelso to sleep so he can repeat something he said before when he was sleeping.', 21, '2001-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 23, 'Canadian Road Trip', 'Eric, Hyde, Fez, Kelso and Leo go to Canada to get some beer.  Unfortunately, they get stopped on their way back across the border because Fez lost his green card. Donna tries to convince Jackie that she''s being scammed by a modeling agency. Red gets a bonus at work: a Beta Max so he can tape something now and watch it later, but he forgets a vital step in the process.', 21, '2001-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 24, 'Backstage Pass', 'Eric gets upset at Donna when she goes backstage at a Ted Nugent concert and then forgets about him; Hyde and Fez get busted for selling counterfeit t-shirts; Kelso tries to be more romantic; and Red and Kitty can''t remember how they first met.', 21, '2001-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 3), 25, 'The Promise Ring', 'Eric gives Donna a promise ring but things don''t turn out the way that he planned; Jackie, seeing Donna''s ring, demands that Michael gives her a promise ring too; Hyde and Fez go cruising for chicks.', 21, '2001-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 1, 'It''s a Wonderful Life', 'Eric is distraught after his break-up with Donna and wishes that they never kissed in the first place. As soon as he utters this wish, a guardian angel appears to teach Eric that it''s better to have loved and lost than to have never loved at all. The angel takes Eric on a journey to the future -- the ''80s -- to show him how everyone''s lives would''ve turned out if he and Donna never got together. Eric remains unconvinced that the pain of his break-up was worth it, until the angel shows him all the wonderful memories he would have never had.', 21, '2001-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 2, 'Eric''s Depression', 'Four days after the big break-up, Eric locks himself in his room ignoring Red and Kitty''s pleas for him to come out and talk about it. Meanwhile, the gang goes to Funland without Eric, and Kelso gets lost.', 21, '2001-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 3, 'Pinciotti vs. Forman', 'Eric kicks Donna out of the basement when she tries to hang out with their friends.  Jackie inspires Donna to compete with Eric over their friends.  The competition threatens to tear the entire group apart.  Meanwhile, Kitty is ecstatic when she learns that Red has become friends with Pastor Dave.', 21, '2001-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 4, 'Hyde Gets a Girl', 'Eric and Fez decide Hyde needs a girlfriend so they throw a party and invite lots of pretty girls, and Hyde isn''t the only one to meet someone he likes; Eric finds a new way to deal with his depression over losing Donna; Kelso and Bob compete to win a van in a radio station contest.', 21, '2001-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 5, 'Bye-Bye Basement', 'After Hyde moves back in with the Formans, Kitty decides to redecorate the basement so she hires Leo and his cousin Theo to do the job. Meanwhile, Donna and Eric engage in post-break-up bickering, while Fez takes up ballet to meet girls only to discover that they consider him one of the girls.', 21, '2001-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 6, 'The Relapse', 'Bob is in denial after Midge leaves. Donna seeks comfort in the arms of Eric, who thinks this means they''re back together. Kelso and Fez go to the supermarket to try and pick up older women.', 21, '2001-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 7, 'Uncomfortable Ball Stuff', 'Donna keeps her promise to accompany Eric to the Pricemart Ball as a friend, but she gets jealous when she sees Eric with another girl. Fez gets a job at the Foto Hut but gets fired for being too efficient and making Hyde and Leo look bad, even though they''re the only other two who work there and Leo is the boss. Bob meets a woman at the supermarket.', 21, '2001-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 8, 'Donna''s Story', 'Eric is upset when Donna writes a story in the school newspaper that sounds exactly like events that happened in their relationship; he decides to write his own story. Red and Kitty have dinner with Bob and his new girlfriend.  Red doesn''t like her because she''s taught Bob how to stand up for himself.  Kelso invests in a pinball machine but loses out when Fez persuades the owner to get rid of it and bring in Space Invaders instead.', 21, '2001-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 9, 'The Forgotten Son', 'Red has to produce a new Pricemart instructional film, and his choice of actor for the part of "Stockboy" leaves Eric stunned. Kitty and Donna become friends, spending time together, and Leo takes Hyde and Fez on a shopping spree after inheriting money from his Uncle.', 21, '2001-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 10, 'Red and Stacey', 'Red thinks Pricemart checkout girl Stacey is perfect for his lovelorn son. The girl impresses Red when she justifies her dubious customer relations with a phrase dear to his heart. Red encourages Eric to ask her out and he even offers to assist. But when Red talks to Stacey, she says she''s interested in someone else.  Meanwhile, Jackie and Donna give Big Rhonda a makeover for her first date with Fez.', 21, '2001-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 11, 'The Third Wheel', 'When the guys go bowling for boy''s night, Hyde throws a wrench in the plan when his "friend" Jill shows up. Kelso and Fez decide to hunt down their own ladies and leave Eric to feel like the third wheel. Meanwhile, Donna is uncomfortable when she discovers Bob''s new girlfriend is spending the night. When Red unintentionally inspires Pastor Dave to give up the cloth, he gets into trouble with Kitty and must find a way to steer Dave back to the light.', 21, '2001-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 12, 'An Eric Forman Christmas', 'Eric thinks that Christmas just isn''t as fun as it used to be when he was a kid, so Kitty suggests that he direct the church Christmas pageant.  He has some artistic differences with the gang over how things should go.  Kelso is upset that everyone is making fun of him for wanting to watch Christmas specials on television; and Red is upset over Bob''s Christmas decorations.', 21, '2001-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 13, 'Jackie Says Cheese', 'Eric catches Red looking through his dresser drawers for a condom and thinks that Red has found Hyde''s stash. Jackie gets a job as a cheese maiden and Fez is jealous of the new foreign guy.', 21, '2002-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 14, 'Eric''s Hot Cousin', 'Eric'' cousin Penny, whom he used to tease unmercifully when they were younger, comes for a visit, and she''s...grown some. All the guys are infatuated with her, much to Donna and Jackie''s dismay.  Jackie and Donna try to be hotter than Penny, with disasterous results.  Kitty, feeling like she''s not needed, wants to get a pet.', 21, '2002-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 15, 'Tornado Prom', 'A tornado is on its way to Point Place and Red and Kitty are stuck in their basement with Bob and Joanne; Eric is stuck with Donna at the radio station; the rest of the gang is stuck at the school during a dance. Kelso is named the Snow King and Jackie can''t believe she''s only the Snow Queen runner-up.', 21, '2002-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 16, 'Donna Dates a Kelso', 'Eric and Donna both start dating other people; Jackie sets Donna up with Kelso''s older brother Casey, while Eric has his pick of the girls at school after being named Point Place High''s most eligible bachelor. Fez thinks that he''s finally going to lose his virginity, and looks for a place that he and Rhonda can use for that purpose.  Bob becomes rich again and Red buys a Corvette.', 21, '2002-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 17, 'Kelso''s Career', 'Eric doesn''t know what to do when Red says ''I love you'', so he decides to say it back, but learns that Red was drugged when he said it. Fez buys Rhonda a box of candies for Valentine''s day, then can''t help but eat them all. Jackie tells Kelso to get a job so he can buy her something nice for Valentine''s day, and he finds a career that suits his interests and hobbies at the same time.', 21, '2002-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 18, 'Leo Loves Kitty', 'Hyde tries to teach Fez to drive but Fez damages the car and hurts Leo, who was taking a nap behind the car. While in the hospital Leo falls in love with Kitty and starts showing up at the Formans bearing gifts for her. Kelso becomes a department store model and Jackie is jealous because it''s her dream to be a model. She confronts him and demands that he doesn''t do it but he stands up to her and does it anyways.', 21, '2002-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 19, 'Jackie''s Cheese Squeeze', 'Eric catches Jackie kissing Todd, her boss, but instead of telling Kelso, he holds it over her head.  Jackie decides to tell Kelso about it herself, as well as telling him that Eric knew all about it.  Both of their plans backfire on them.  Kitty feels neglected and worries about becoming a Corvette-widow when Red spends all his time with his new car.', 21, '2002-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 20, 'Class Picture', 'While trying to come up with a quote for the yearbook, the gang recalls how they met for the first time. They go through the times when they each met each other, no matter how embarrassing or stupid they were. They also try to work out a saying to put under each of their pictures. Kelso finally comes up with the perfect quote for them all, "It''s been a long, strange journey...in Forman''s basement!"  The gang also realizes how strong their friendship is.', 21, '2002-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 21, 'Prank Day', 'It''s Prank Day according to Kelso, who manages to trick his friends twice with his stunts.  The guys'' attempt to retaliate backfires horribly when Red triggers their prank instead.  But rather than venting his wrath on Eric, Red joins the prank war to show the boys how it''s done.  Meanwhile, Jackie throws an impromptu slumber party to cheer Donna up on her parents'' wedding anniversary.', 21, '2002-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 22, 'Eric''s Corvette Caper', 'When Red and Kitty go out of town, Eric takes the Corvette out and lets his date drive. She manages to get it all dirty and Eric scrambles to get it clean in time because his parents are coming home early. Jackie and Donna snoop around in Casey Kelso''s room while he''s away, and discover that Michael likes to hang out there.', 21, '2002-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 23, 'Hyde''s Birthday', 'Kitty plans a surprise birthday party for Hyde''s 18th birthday.  She recruits Jackie and Fez as decorators because of their feminine creativity (much to Donna''s annoyance).  Eric, Donna, and Kelso decide to steal a street sign for Hyde''s present.  But Hyde doesn''t want to celebrate because he thinks this means he''ll have to move out of the Formans'' house.', 21, '2002-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 24, 'That ''70s Musical', 'Fez fantasizes about several musical numbers featuring himself and the rest of the gang while he gets ready for a school concert.', 21, '2002-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 25, 'Eric''s False Alarm', 'When Eric finds out that Casey is taking Donna to a motel, he decides to show up to make sure she doesn''t do anything she''ll regret.  Bob''s divorce from Midge comes through, he mentions marriage to Joanne, who totally freaks out.  Naturally, Red and Kitty are called upon to advise their neighbors, but unfortunately they aren''t offering the same advice.  And Kelso stalks Jackie at the mall to prevent her from kissing anyone else.', 21, '2002-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 26, 'Everybody Loves Casey', 'Kitty decides to throw a neighborhood barbecue after she wins a year''s worth of hot dogs.  Eric is upset when he learns Casey is invited, so he devises a convoluted plan to make Casey look bad in front of Donna.  Kelso and Jackie seek relationship advice from Cosmo to uncover the root of their problems.  Fez can''t get past second base with Rhonda; Hyde''s fed up with how the guys talk about the girls all the time.', 21, '2002-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 4), 27, 'Love, Wisconsin Style', 'Kitty and Eric go to the Hub after a dentist appointment and catch Donna (who''s drunk) skipping school with Casey. Neither Bob nor Joanne can exert any authority over Donna, so a frustrated Red intervenes while everyone watches. Meanwhile, Jackie suggests that Kelso kiss another girl so that they can reconcile. And Hyde and Fez try to decide what to do with some dead fish that they stole.', 21, '2002-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 1, 'Going to California', 'Donna has had enough of the Golden State. She misses Eric, who, although she doesn''t know it, is headed West - despite his parents'' objections - to declare his love and bring her home. Kelso, however, has decided he has found the woman of his dreams in Annette, who is beautiful and believes in him.  Back in Wisconsin, Jackie is a changed woman, thanks to a change in boyfriends.', 22, '2002-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 2, 'I Can''t Quit You Baby', 'As punishment for Donna going away to California, Bob transfers her to a Catholic School, which means that Donna won''t get to see Eric as much.  Eric is determined to fight for their right to be together, until he sees Donna in her new school uniform.  Jackie and Hyde get caught making out in the basement; Eric and Donna try to convince them to tell Kelso what''s going on.', 22, '2002-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 3, 'What Is and What Should Never Be', 'Kitty joyfully announces that she''s pregnant, but the reaction that she gets from Red leaves a lot to be desired. Eric and Donna continue their campaign to get Jackie and Hyde to tell the truth about their relationship to Kelso. A trip to the DMV seems to present the perfect opportunity, but Fez is the one who seizes the day rather than Hyde.', 22, '2002-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 4, 'Heartbreaker', 'Kitty''s parents arrive from Arizona, after being told that Kitty has some wonderful news to share with them. Kitty''s news isn''t what she thought it would be, and throws a damper on the high spirits. Donna learns a thing or two from Bea about getting people to do things, while Eric and Red learn a thing or two from the World Book about "lady problems." Kelso works out his feelings about Jackie and Hyde''s relationship.', 22, '2002-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 5, 'Ramble On', 'In a romantic moment, Donna presents Eric with a ring, much like the promise ring that he gave her, and caused their break up.  For Donna, the ring symbolizes their enduring love and committment; for Eric, it symbolizes ugliness.  To protect Donna''s feelings, he decides not to say anything, but the secret gains a life of its own.  Kitty is determined not to let menopause affect her life, but has a hard time living up to her committment.', 22, '2002-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 6, 'Over the Hills and Far Away', 'The kids prepare to make a weekend college visit to the University of Wisconsin. There''s only one snag in the plan: Donna tells Eric that Bob will not let her go to UW. Instead he wants her to visit Marquette, a small Catholic college. So Donna and Jackie visit Marquette, where Jackie spends her time worrying about Hyde; the guys go to UW with Red and a very irritable Kitty.', 22, '2002-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 7, 'Hot Dog', 'When Eric decides to buy Donna a meaningful gift, he ends up getting her an engagement ring. But after discussing it with the guys, he realizes they are too young and the ring was a bad idea. Unfortunately, Eric already told Donna he got her a surprise and on their special evening out, he''s put on the spot and forced to make the biggest decision of his life. Meanwhile, in an attempt to lift menopausal Kitty''s spirits, Red gets her a dog: Schotzy.', 22, '2002-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 8, 'Thank You', 'Eric hides the fact that he''s failing math from Red because he wants to prove that he''s starting to get serious about his future.  Red is so impressed by his son''s apparent maturity that he bumps Laurie from the adults'' table at Thanksgiving and gives her seat to Eric.  This makes Eric think that the time may finally be right to announce to his engagement to Donna.  However, the woman that Kelso brings as his date to the Formans'' dinner complicates this decision.', 22, '2002-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 9, 'Black Dog', 'When Jackie''s father is arrested for bribery, Kelso thinks she''ll come running back to him. But when Hyde and Kelso get into a brawl over Jackie, Kelso accidentally shoots Hyde with a BB gun and all hell breaks lose. Donna and Eric argue over how Hyde should deal with Jackie''s pain.  Meanwhile, Fez realizes he has a crush on his boss at the DMV.', 22, '2002-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 10, 'The Crunge', 'The S.A.T. scores have come in and everyone does significantly better than Eric.  He''s particularly upset by Donna''s high score and blames her for distracting him during the exam.   As a result, Eric enlists Red to help him buckle down and stay away from Donna until he retakes the test.  Meanwhile, Kelso discovers that he may have a bright future and Jackie pushes Hyde towards a college career.', 22, '2002-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 11, 'The Girl I Love', 'When Fez decides to introduce his new girlfriend, Nina, to the gang, Kitty offers to throw a dinner party for the event. The guys resent being dragged to a dinner party, while the girls are excited at the thought of a grown-up night.', 22, '2003-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 12, 'Misty Mountain Hop', 'Jackie recruits the Formans to help clean out her family''s mountain cabin, but decides it best not to ask for Hyde''s assistance, instead telling him she is attending a doll expo. With Jackie going away, Hyde seizes the opportunity to use Jackie''s cabin and invites Kelso and Fez. Donna and Eric get lost on the way to the cabin and spend the trip fighting. Hyde''s plan goes wrong when Kelso gets his hand, holding his stash, stuck in a vase just as Jackie and the Formans arrive.', 22, '2003-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 13, 'Your Time Is Gonna Come', 'Annette, Kelso''s girlfriend from California, comes to Point Place to visit him.  The entire gang is shocked to learn how closely her personality resembles Jackie''s, while Jackie tries to conceal her jealousy from Hyde.  Meanwhile, Kitty''s parents show up unexpectedly and announce that they''ll be moving in for a while.  This unpleasant situation gets far worse when Eric finds his grandfather collapsed in the driveway.', 22, '2003-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 14, 'Babe I''m Gonna Leave You', 'Hyde''s depressed that Jackie still seems to have feelings for Michael. Annette''s not happy either, because Kelso seems to still be attached to Jackie. And Kitty takes to her bed, because she feels her mother doesn''t love her.', 22, '2003-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 15, 'When the Levee Breaks', 'When Bob goes out of town, Eric and Donna decide to "practice" being married at her house. The gang is excited because they think this is a chance to party all weekend at the Pinciotti''s place, until Eric and Donna are forced to set them straight. Meanwhile, Kitty goes to the jewelers to pick up a ring she thinks Red got her as a surprise. But she discovers the real surprise: it''s actually an engagement ring for Donna.', 22, '2003-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 16, 'Whole Lotta Love', 'Red is angry that Donna and Eric are engaged, so he gives Eric the silent treatment, leaving it up to Donna to try to talk to him.  Fez finally does it with Nina; he''s happy that he finally did it, but afterwards, things aren''t so great.  Kelso gives Jackie a birthday present, but insists that he''s not trying to do anything; Hyde didn''t even know it was her birthday.', 22, '2003-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 17, 'The Battle of Evermore', 'Things are still bad between Red and Eric, so Kitty signs them up for the Point Place Paul Bunyan Pioneer Days Jamboree.  The estranged men must work together in order to beat Charlie and Mitch, an obnoxious father/son team who have won the past two years.  Meanwhile, Hyde doesn''t understand why Leo hasn''t called him back to work in a while.  He takes the gang to the Foto Hut only to find the place has been completely cleaned out.', 22, '2003-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 18, 'Hey, Hey What Can I Do', 'Everyone has their own reasons for going to the job fair. Eric needs a full-time job now that Red refuses to pay for college. The Photo Hut is closed, so Hyde''s looking for work too. Fez wants to make out with Nina at the DMV booth while "Hot Donna" will be signing autographs at the radio station''s booth. And after failing to flirt his way out of a parking ticket, Kelso fears that his good looks will fade and that he''ll need a practical job like other ''uggos''.', 22, '2003-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 19, 'Bring It on Home', 'The Formans discover that Jackie has been sleeping in Hyde''s room since neither of her parents are home.  The best solution that everyone can come up with is for Jackie to move in with Bob and Donna, but unforunately Jackie doesn''t appreciate everyone''s pity.  Meanwhile, Red gives Eric a hard time when he finds out that his son sleeps nude.  And Fez has dinner at Nina''s house, where he learns that her parents don''t want her dating her "third world friend".', 22, '2003-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 20, 'No Quarter', 'The Pinciottis learn very quickly that living with Jackie is going to be difficult.  Kelso swipes Jackie''s panties to taunt Hyde, who has his revenge when Kelso gets a job at the hotel kitchen where Hyde works.  Eric receives notice that he must return Donna''s engagement ring if he can''t make a payment by Friday.  His visits to the jewelry store reveal that there''s bad blood between Fez and Fenton, the jewelry guy.', 22, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 21, 'Trampled Under Foot', 'Nina breaks up with Fez, although he doesn''t realize it until the gang sets him straight. It turns out that Nina thinks Fez is too needy. As for the others, they decide to rejuvenate their dull lives by finding another friend to hang out with. Kitty has one candidate in mind, but she has an ulterior motive.', 22, '2003-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 22, 'You Shook Me', 'Hyde turns down a hot nurse out of faithfulness to Jackie, then demands that Jackie not hang out alone with Kelso any more. The recent nurse convention at the hotel inspires Fez to have an erotic dream about a nurse…who turns out to be Kelso! Naturally, Kelso freaks out, and he turns to his ex for comfort. Meanwhile, Eric accepts a job at the dog food factory where Joanne works in order to earn enough money to marry Donna.', 22, '2003-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 23, 'Nobody''s Fault But Mine', 'Hyde cheats on Jackie because he thinks she still loves Kelso. After realizing his mistake, he apologizes to her but she breaks up with him. Red and Kitty dare Eric and Donna to get married by graduation in order to pressure them into calling off their engagement. Their plan works, but a little better than they expected. Fez refuses to give Mitch Miller his driver''s license, so Mitch digs up dirt on him and Kelso. Laurie moves back home, determined to make up for her past wrongs.', 22, '2003-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 24, 'Immigrant Song', 'The Formans are horrified when they realize that Red has gone fishing - he only does that when he''s really angry. When he finally returns, Red has his final say on Eric and Donna''s decision to move. Meanwhile, Kelso, Hyde, and Fez decide to paint obscene pictures on the water tower as their senior prank. Hyde and Kelso''s arguing over Jackie lands Kelso in the hospital, leaving Fez to face the police alone and Jackie to face her feelings about who she wants to be with.', 22, '2003-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 5), 25, 'Celebration Day', 'The gang will be split in half when high school graduation is over: Eric and Donna are all set to move into their Madison apartment, while poor Fez is about to be deported.  The love triangle amongst the others grows more heated as Hyde and Kelso compete over an indecisive Jackie.   But this tense situation is put aside so that the six friends can go camping together the night before graduation.   Laurie tags along and dramatically changes Fez''s life.   Back at the Forman house, Red gives Kitty medication to help her deal with her depression over Eric''s imminent departure.', 22, '2003-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 1, 'The Kids Are Alright', 'When Jackie finds out Kelso has a new girlfriend she chooses Hyde over him, but--surprise!--he has someone new too. Eric is living with his parents to help out his dad, but all he wants is to be with Donna in Madison. Meanwhile, Kitty still tries to convince Eric he should stay with them and not go to Madison. Eric finally realizes that he can''t go away to school, but is surprised to find Donna still plans to. Kelso also finds a problem when he drinks eggs only to find out he is allergic to them.', 22, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 2, 'Join Together', 'Kelso decides to help Jackie and Hyde get back together with hilarious results. And Eric realises that the sadder Donna becomes, the more she wants sex.  Kitty decides to help Red with his new doctor-imposed diet.', 22, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 3, 'Magic Bus', 'It''s Eric''s 18th birthday and nothing is going the way he wants it.  He expects a birthday breakfast and suprise party from his mom, but Kitty is too preoccupied with resuming her sex life with Red.  Plus, it''s Donna''s last day before moving to Madison for college and Eric is struggling with letting her go.  In the end, Donna manages to salvage the day with the gift she gives him at the bus station.', 22, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 4, 'The Acid Queen', 'No one in the gang believes Kelso''s claim that he hooked up with Brooke, a beautiful and conservative older girl, at a Molly Hatchet concert.  Much to Kelso''s shock, Brooke denies knowing him and rejects all of his advances.  Brooke''s presence also disrupts Jackie and Hyde''s relationship when Jackie asks for his opinion about Brooke''s looks.  Also, Fez decides to pursue college-bound virgins while Eric learns of an interesting collection kept at the local library.', 22, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 5, 'I''m Free', 'A representative from INS is coming to find out if Fez''s marriage to Laurie is for real.  To avoid deportation, Fez must stay with the Formans and get on Red''s good side.  Donna encourages Kelso to take responsibility for his actions by talking to Brooke about the baby.  But for some reason Brooke decides to let him off the hook.', 22, '2003-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 6, 'We''re Not Gonna Take It', 'After Eric loses his job, he finds himself up for the same waiting job as Kelso at the Holiday Hotel; Donna and Jackie send newly single Bob a box of fudge to cheer him up; Red tries to help Fez and Laurie get divorced.', 22, '2003-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 7, 'Christmas', 'The cheerleaders kick Jackie off the squad, so she invites the gang to the dance to give her popularity a boost.  Kelso visits Brooke at the library in an effort to start a friendship with her.  Christmas Eve is going to be "Hot Donna''s" first shot at being a DJ at the station she works at.  And Kitty signs Red up to be the mall''s Santa Claus, sparking a rivalry between him and Bob.', 22, '2003-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 8, 'I''m a Boy', 'Eric sleeps in after a late night playing poker with the guys after work. However, he tells Donna and Kitty that he was working the entire time so that he can get their sympathy. Fez volunteers to drive Red to the doctor''s office but receives no gratitude in return. Brooke and Kelso go on an awkward double date Hyde and Jackie. Later, Brooke is introduced to Roy, who''s instantly smitten.', 22, '2004-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 9, 'Young Man Blues', 'It''s Kelso''s first day as a police cadet and he gets to drive around in a police cruiser with a real cop.  His first stop is the Forman house to break up a domestic disturbance (Fez and Laurie are fighting over her sex life).  The encounter leaves Fez burning mad, but he gets a chance for revenge when Kelso leaves the cruiser unattended.  Meanwhile, Eric attempts to fix the water pipes and lawn mower in order to prove to Red that he''s not a failure.  And Jackie joins a Big Sister program at school.', 22, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 10, 'A Legal Matter', 'Kelso freaks out when Roy suggests that he may be this year''s police academy stooge.  The only way to know for sure is to check his file, so Kelso decides to break into the police academy with Hyde and Eric.  Meanwhile, Fez is expecting to take a final exam at the INS before finally becoming a U.S. citizen.  Donna, Kitty, Jackie, and Red all tutor Fez on their versions of American history.', 22, '2004-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 11, 'I Can See for Miles', 'Kelso is ecstatic when Brooke asks him to be involved in her doctor''s meeting for their upcoming baby, but he runs into a problem when he can''t find his van. Hyde is exactly the opposite of ecstatic when Jackie redecorates his room with bright colors and lights that looks like a girl''s room. Eric and Donna also set out to discover (in Kelso''s van) what Mount Hump is like. Red is also upset that Bob gave him shoes, until he reluctantly begins to like them.', 22, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 12, 'Sally Simpson', 'Red goes to the heart doctor and finds out that they are going to send a psychiatrist to his house to find out what is causing his stress. Kitty, who believes they always blame the wife, isn''t too happy about it, so she starts to act weird. Meanwhile, Kelso introduces his co-worker, Suzy (Alyson Hannigan) to the gang. He says that he likes finally having a girl as a friend, without liking her as a girlfriend. Fez tells Kelso that he likes her. As Kelso is about to tell Suzy about Fez, she tells Kelso that she likes him. So Kelso tricks both of them. He tells Suzy she''ll be on a date with him, and tells Fez he''ll be on a date with Suzy. They both find out and are upset with Kelso, especially Fez.', 22, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 13, 'Won''t Get Fooled Again', 'Before a romantic evening with Eric, Donna realizes that she''s missed taking one of her birth control pills.  Both of them completely freak out and seek out Kitty''s advice.  Fez is still extremely angry about losing Suzy to Kelso, so he "dumps" Kelso and returns everything his former friend ever gave him.  Everyone in the gang tries to console the unhappy couple while Suzy plots to reunite them.', 22, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 14, 'Baby Don''t You Do It', 'After the recent pregnancy scare, Bob and the Formans insist that Eric and Donna go for counseling at the church.  During their first session, Eric and Donna lie to the minister about having pre-marital sex.  Kelso has also been lying lately, telling Brooke that he''s doing better at the Police Academy than he actually is.  But lying becomes more difficult after there''s a fire at the Academy.', 22, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 15, 'Who Are You', 'Jackie''s mother, Pam Burkhart (Brooke Shields) unexpectedly returns from Mexico.  Everyone tries to convince Jackie to forgive her mother and welcome her back into her life.  However, when Pam starts dating Bob, Donna and Jackie realize that Pam is still a gold-digger.  Donna and Jackie agree to do whatever it takes to break their parents up.  Kelso is scared to leave for police academy, but the guys force him to go.', 22, '2004-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 16, 'Man with Money', 'When none of the guys will help Donna and Jackie in convincing their parents not to date, they come up with their own plan to try to lure Pam away and prove she doesn''t really love Bob.  Meanwhile Red''s heart monitor keeps going off around Pam prompting Kitty to think Red is "extremely happy" around her.', 22, '2004-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 17, 'Happy Jack', 'Donna catches Eric ''taking care of business'' in her bathroom and is completely horrified. Afterwards, Eric''s friends and family tease him mercilessly and Donna can''t even look him in the eye. Amazingly, Eric actually manages to make this embarrassing situation worse when Donna finds out what brought on his need.  Meanwhile, Kelso, now calling himself "Mike" and sporting a moustache, goes on a major maturity kick, so Hyde and Fez decide to knock him down a peg or two.', 22, '2004-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 18, 'Do You Think It''s Alright?', 'Donna wants to take Eric to a department to register for wedding gifts but he doesn''t want to go. Red tells him about the easiest way to get out of shopping: choose the ugliest thing so they think you are bad at shopping, and Eric tries it. Donna falls for it, but figures it out and sends him shopping with a wedding crazed Jackie, which he actually enjoys! Donna gets mad when she finds out and gets an enraged Hyde, who told Jackie not to do wedding stuff, to help her ruin their time. Red reads one of Kitty''s "dirty girl" fantasy books, and learns a thing or two.  Kelso tries to invent something, but all his thoughts have already been invented.', 22, '2004-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 19, 'Substitute', 'When the gang sees Mitch at a putt putt course, they laugh it up at his pathetic job until they accidentally hit him in the head with a golf ball. Feeling sorry for him, Eric invites him to join the gang in the basement. But it snowballs from there when Mitch obsesses over Donna.  Meanwhile, Pam doesn''t see what the big deal is about rejecting Bob''s offer to move in together, since she is dating another man.', 22, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 20, 'Squeeze Box', 'When Hyde and Red accidentally walk in on Pam and see her topless, they are shocked by her reaction. They try to keep it a secret, but Bob, of all people, spills the beans. Meanwhile, Donna finds out about a girl Eric dated while she was with Casey.', 22, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 21, '5:15', 'Much to Eric''s chagrin, Donna agrees to be Mitch''s date to his brother''s wedding. While there, Fez meets a beautiful girl and pretends to be rich to impress her, but the big news is the shockwave Mitch makes at the wedding.....  Meanwhile, Kelso takes Brooke to a baby class.', 22, '2004-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 22, 'Sparks', 'When Eric accidentally sees Donna''s wedding dress, he unintentionally rips it. But he only makes things worse in an attempt to rectify the mistake. Kelso, Hyde and Fez get a canoe and Red is forced to find a sentimental wedding gift for Eric for his wedding.', 22, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 23, 'My Wife', 'When Donna gets a full time job as "Hot Donna" on the radio, she decides that staying in Point Place is the best thing to do. She also buys a very small trailer for her and Eric. While visiting the trailer, the gang is surprised to see Casey Kelso, who is now back in town.  The guys continue their plans and have a bachelor party for Eric, who can think of nothing but why Donna wants to stay. The girls also have their own fun at a strip club where they are again surprised to see Casey Kelso as a non-stripping employee who drives a drunk Kitty crazy.', 22, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 24, 'Going Mobile', 'The day of the rehearsal dinner, Eric comes to the realization that he could be holding Donna back if he marries her.  He attempts to tell her this when the Formans come visit the mobile home Donna picked out.  Although he denies having second thoughts, he drops enough hints to make Donna begin to worry about the wedding herself.  Meanwhile, Michael makes a very poor first impression on Brooke''s mother; Hyde and Fez try to decide who Eric''s best man will be.', 22, '2004-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 6), 25, 'The Seeker', 'Everyone does their best to cheer Donna up after Eric disappeared before the wedding.  Midge even shows up to console her daughter, but her arrival causes an awkward scene with Bob and Pam.  Also, Hyde lands in the hospital after he takes Donna to the water tower for a talk.  While Kitty looks after Hyde, she goes through his medical records and stumbles upon a life-altering piece of news.', 22, '2004-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 1, 'Time Is on My Side', 'A week after Eric and Donna''s engagement was called off, they are both on good terms, but have to make big decisions regarding their futures. Donna gets a new look, and Eric decides to take a year off, but to do that he needs to sell Donna''s engagement ring to get some money. There''s only one problem with his plan: Donna threw it off the water tower. Also, Bob is torn between Pam and Midge, and Red puts pressure on him (only because Kitty pressured Red) to choose between them. However, one of them takes the decision out of Bob''s hands.', 22, '2004-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 2, 'Let''s Spend the Night Together', 'The Formans invite Hyde''s biological father over so that Hyde can finally meet him, and everyone is shocked to discover that he''s black. Kelso waits for news from Brooke about her advancing labor, while Fez tries to deal with losing Kelso to a baby. Eric and Donna go to a feminist rally in the park.', 22, '2004-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 3, '(I Can''t Get No) Satisfaction', 'Red''s job hunt is going nowhere and he begins to wonder when he will find a job. With a year off to do whatever he wants, Eric makes a list of things to do, one of which includes graffiting a closed muffler shop as part of his new bad boy image. But unbeknownst to Eric, Red has found his new job... in the building Eric just graffitied! Kelso has issues with women; now that he''s a father to a baby girl, he has a new respect for women that gets him nowhere. And Hyde is pressured by Jackie and Kitty to call his father.', 22, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 4, 'Beast of Burden', 'Red''s new muffler shop is about to open and he asks Hyde to work for him.  This really offends Eric since the shop is called "Forman & Son" and Red didn''t even think to ask him.  But Hyde has his own dilemma when his dad offers him a job at his record company.  Fez is also on a job hunt after quitting the DMV, so Donna helps him apply for work as a shampoo boy.', 22, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 5, 'It''s Only Rock and Roll', 'Hyde starts working at his dad''s record company only to learn his job is not as cool as he thought it would be.  Kitty, feeling "unneeded, unnecessary and unloved," takes up Tai Chi with Donna and Midge.  Seeing an ad in the paper for aspiring artists, Eric tries out for the Cartoon Academy of Fort Lauderdale.  And Kelso decides to donate his entire Playboy collection to Fez.', 22, '2004-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 6, 'Rip This Joint', 'Kitty throws a party in honor of herself to boost her self esteem, but Bob feels that Midge is spending too much time with Wiliam Barnett and they have a fight, causing Midge to lock herself in the bathroom.  Eric decides to "moon and trench" Old Man Shinsky''s beautiful yard.  Kelso, because Eric didn''t make him First Lieutenant, takes his revenge on Eric, but that backfires on them both.  And Hyde succumbs to the corporate life, which Jackie finds very sexy.', 22, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 7, 'Mother''s Little Helper', 'When a hot girl tells Fez she wants to date him, he is delighted.  He later finds out the girl was supposed to date Kelso, but blew him off. After Kelso begs, Fez agrees to help him regain his lost mojo. Donna and Jackie learn that play-fighting is an art.  And Kitty tries to get Red to be more adventurous in their sex life.', 22, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 8, 'Angie', 'Things are going well for Hyde at work, until he meets his new sister, Angie, and finds that she''s not as nice as she seems.  She attempts to get Hyde fired, causing him to use his biggest weapon against her; Jackie.  Eric tells the gang that he''s studying Spanish, but Kitty lets it slip to Fez what Eric really does on Wednesday nights, and Fez just can''t keep the secret to himself.', 22, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 9, 'You Can''t Always Get What You Want', 'It''s Thanksgiving, and while Kitty prepares for the feast, Eric is making plans of his own, and they don''t include dinner at home.  He wants to go to a Styx concert; the rest of the gang is busy helping Hyde and Angie get ready for the opening of the record store.', 22, '2004-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 10, 'Surprise, Surprise', 'Hyde joins the disgruntled group of guys that can say "Kelso Slept With My Sister", much to his displeasure. Donna plugs a calender on the air for Red''s muffler shop until she discovers it is full of scantily clad babes on hotrods.  Kitty once again tries to teach Jackie how to bake, with disastrous results.', 22, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 11, 'Winter', 'Kelso gives the toys from the Toy Drive to the gang, leaving Kitty with no toys for the kids at the Ladies of Point Place Christmas Party.  Jackie is upset that Hyde won''t go to the party with her, making her think that he''s not as mature as she thought he was.  The guys have to come up with a way to get the toys to the party without the kids seeing them being brought in, and Red distracts everyone with an unusual Christmas story.', 22, '2004-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 12, 'Don''t Lie to Me', 'Jackie''s doubts of a future with Hyde come to the breaking point, and she decides to go along with a misunderstanding and pretend to be Donna, engaged to Fez, whom she calls Prince Edwardo. She drags Fez to parties, enjoying the pre-marriage life, until she is caught in the act. Meanwhile, Hyde is bothered by Angie''s relationship with Kelso, so Eric steps in to help split them up.', 22, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 13, 'Can''t You Hear Me Knocking', 'Red reluctantly agrees to take Kitty ice fishing, which doesn''t turn out to be as bad as he expected. Kelso accidentally makes a threat on the President, prompting the guys to be paranoid about everyone they meet in an attempt to hide from the government. Donna takes Jackie to a karate lesson that yields unexpected results.', 22, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 14, 'Street Fighting Man', 'When Donna gets 6 tickets to the Packers game, Eric convinces the gang to give one of them to his dad.  Hyde offers to do a ticket stub switch with Kelso and Fez, but neither Kelso nor Fez really gets the concept.  At the game, Jackie attempts to made Hyde miserable and an ecstatic Red is actually nice to Eric - until Eric buys a Chicago Bears jersey.  Kitty and Bob watch the game together back home.', 22, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 15, 'It''s All Over Now', 'There''s a sexy new intern, "Sizzlin" Sarah, at the radio station that has the guys going crazy. Sarah manipulates the station manager into firing Donna by using Donna''s feminism against her. Poor Kitty has the flu and is going to miss meeting Tom Jones at Hyde and Angie''s record store, so she makes Red go in her place to get his autograph. And Jackie seeks advice from Fez on talking to Hyde about her true feelings.', 22, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 16, 'On with the Show', 'Jackie, who''s still smarting from her breakup with Hyde, is going to host her own public television show. Hyde suspects that Fez knows what Jackie was trying to tell him at the record store. Eric meets a 36-year-old guy whose pathetic life forces him to reevaluate his own directionless existence. Angie has a hard time understanding how to "burn" someone.', 22, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 17, 'Down the Road Apiece', 'Eric decides to leave town to make a documentary about his life on the road. His car breaks down and he finds Leo. The two go to a truck stop to get something to eat. Kitty, Red, Kelso and Donna set out to find him when Eric doesn''t call home. Meanwhile, Fez talks to Jackie and Hyde about their relationship.', 22, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 18, 'Oh Baby (We Got a Good Thing Goin'')', 'When Brooke leaves Betsy in Kelso''s care, he''s ecstatic. His happiness soon ends when he notices that Betsy cries every time he holds her. Leo''s offers to help Kelso with the baby only causes him more grief. Meanwhile, Kitty shows signs of jealousy when Hyde stays with Jackie throughout a car show while Red goes off and forgets about her.', 22, '2005-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 19, 'Who''s Been Sleeping Here?', 'Donna and Eric are in disbelief when Kelso chooses Jackie and Hyde over them to be Betsy''s godparents. On the other hand, Hyde and Angie believe there''s someone breaking into the store, so Angie places a camera to see who it is. After viewing the tape, they discover it''s Fez crashing there at night because his host parents kicked him out since he already graduated. Kitty gives Fez and Kelso the idea to move in together since Kelso''s house isn''t safe for Betsy and Red wont allow them to stay when she visits.', 22, '2005-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 20, 'Gimme Shelter', 'When Eric realizes he is the only loser with no future in the group, he goes looking for a job, only to find he isn''t very good at many things. Kelso and Fez look for an apartment for the two to live together in, and Jackie arranges a dinner party to celebrate her high school graduation.', 22, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 21, '2120 So. Michigan Ave.', 'In preparation for pursuing a teaching career, Eric receives his high school transcripts and discovers that he received an incomplete in gym class. He enrolls in a summer gym course and learns that his new P.E. teacher is none other than Casey Kelso! Kelso and Fez move into their new apartment and compete over who gets the master bedroom. While they do this, Red exacts his revenge for the messes they’ve created at his house over the years.', 22, '2005-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 22, '2000 Light Years from Home', 'Kelso considers what to do about his relationship with Angie, and comes to the conclusion that it''s time to break up, but he''s not sure how to do that. He seeks some advice from Jackie on the matter, but ultimately, the decision is taken out of his hands. Eric is shocked to discover that his college tuition fund is gone, and has to find another way to raise the money. His solution is one that Kitty, Red and Donna have differing opinions on.', 22, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 23, 'Take It or Leave It', 'Jackie is offered her dream job, but unfortunately, it''s in Chicago. She wants to know what her future is with Hyde, but he''s unwilling to answer. Kitty and Donna are both still reeling over Eric''s new job, and both try, in their own ways, to get him to change his mind. The son of one of Red''s buddies from the Marines arrives in Point Place, and the guys take a liking to him when they find out what his dad does now.', 22, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 24, 'Short and Curlies', 'As Eric prepares to go to Africa, Kitty is still having problems dealing with his departure. Donna is also having problems; she can''t come up with an appropriate going away gift, but some advice from Kitty puts her on the right track. Charlie accidentally sees Kitty naked, and his attempts at apologizing only make things worse. Jackie is still in Point Place after telling everyone she was leaving for Chicago; her attempts to give Hyde one last ~last~ chance don''t quite go the way she hopes they would.', 22, '2005-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 7), 25, '''Til the Next Goodbye', 'Kelso drops Jackie off in Chicago, but she is immediately homesick and reaches out to the gang for companionship. Eric finds out at the last minute that Kitty deliberately hid a letter outlining the vaccination shots he’s required to have before going to Africa for the year. He has his final Circle with the guys only to finally be busted by Red! As Eric says his good-byes to everyone, Hyde talks to Leo about his true feelings for Jackie and decides to follow her to Chicago…with disastrous results.', 22, '2005-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 1, 'Bohemian Rhapsody', 'Hyde returns from a Las Vegas sojourn, confronts Jackie about Kelso and finds Leo has mismanaged the record store; Kitty makes an audio tape for Eric and admits experimenting with the boys'' stash.', 22, '2005-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 2, 'Somebody to Love', 'Hyde sets to fire Leo for mismanaging the record store, but ends up with a new employee; Jackie has a night out to move on from Hyde.', 22, '2005-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 3, 'You''re My Best Friend', 'A surprise bachelor party for Hyde falls apart when the guest of honor lands in jail, while his wife gets to know his ex-girlfriend a little better.', 22, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 4, 'Misfire', 'Red and Kitty are celebrating their 25th Wedding Anniversary, and this makes Kelso think that it''s time for him to get married.  He decides to propose, but before he can do this, he meets Vic, a businessman with a proposal of his own; one that Kelso can''t say no to.  And Donna is upset that Eric hasn''t contacted her from Africa yet.', 22, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 5, 'Stone Cold Crazy', 'Donna''s sexy pictures for Eric repeatedly fall into the wrong hands; Jackie moves in with Fez, whose crazy ex-girlfriend better not find out.', 22, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 6, 'Long Away', 'Red hires Leo to take pictures at his veterans reunion; Jackie and Fez suspect Donna is cheating on Eric.', 22, '2005-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 7, 'Fun It', 'The gang steals the ceramic clown mascot of a burger joint, and the whole town is angry except for Red, who never could stand the thing.', 22, '2005-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 8, 'Good Company', 'Fez has a fling with an older woman who''s one of Kitty''s friends.', 22, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 9, 'Who Needs You', 'Hyde and Sam''s constant fighting gets to Red and Kitty; Donna hosts a radio fund-raiser; and Fez and Jackie have landlord problems.', 22, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 10, 'Sweet Lady', 'Jackie meets the local star while at the salon with Fez: talk show host Christine St. George.  Her new goal in life is to be Christine''s co-anchor on "What''s Up Wisconsin?", but breaking in to show business is harder than she thought it would be.  She finally gets a job working with Christine, but it''s not quite the job she wanted.  Randy wants to take Donna away to a cabin, which makes her suspect his intentions; Red takes Hyde to his Lodge, and Hyde''s intentions come under suspicion.', 22, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 11, 'Good Old Fashioned Lover Boy', 'Kitty helps Jackie impress her boss; the guys are shocked when Leo reveals the object of his affection.', 22, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 12, 'Killer Queen', 'Red lets Hyde in on a Valentine''s Day secret; Christine opens up to Jackie about her love life; and Randy has big plans for a date.', 22, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 13, 'Spread Your Wings', 'With memories of Eric still fresh, Donna worries how the gang will react now that she''s dating Randy. Meanwhile, Fez tries to impress a coworker at the salon.', 22, '2006-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 14, 'Son and Daughter', 'Hyde house-sits for his father while he attends an Eric Clapton concert; Kitty is beside herself now that Donna''s dating Randy.', 22, '2006-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 15, 'Keep Yourself Alive', 'Fez loses Kitty''s engagement ring on the ride home from the county fair, so the gang goes over the river and through the woods to look for it while Red searches for the right time to tell his wife the truth about her jewelry.', 22, '2006-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 16, 'My Fairy King', 'Red refuses to go quietly when a national muffler chain threatens his business; Hyde learns the naked truth about his marriage to Sam; and Jackie surprises herself with her list of an ideal man''s qualities.', 22, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 17, 'Crazy Little Thing Called Love', 'Jackie reluctantly seeks help from a therapist after she finally realizes her feelings for Fez; Red''s retirement creates more work for Hyde.', 22, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 18, 'We Will Rock You', 'Red and Kitty have a hunch about their new neighbors; Hyde hosts a bonfire to burn disco records in spite of Fez and Jackie''s protests.', 22, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 19, 'Sheer Heart Attack', 'Hyde shows Red a way to get rid of extra medication; Fez''s latest girlfriend makes Jackie almost as crazy as she is.', 22, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 20, 'Leaving Home Ain''t Easy', 'Donna rethinks her future after her dad announces he''s moving to Florida; Jackie plots revenge on Fez for turning her down.', 22, '2006-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 21, 'Love of My Life', 'Fez gets a visit from a friend from home (wherever that is); Red and Kitty show their house to prospective buyers; and Hyde''s father has a surprise at the store.', 22, '2006-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0165598')) AND numero_temporada = 8), 22, 'That ''70s Finale', 'Kelso returns on New Year''s Eve 1979 to celebrate, while Red and Kitty rethink their plans to move to Florida.', 22, '2006-05-18');
