INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 1, 'Monkey See, Doggie Do', 'Mojo Jojo unleashes a curse that turns everyone into dogs, including the Powerpuff Girls, but the three sniff out a solution and show Mojo Jojo that their bite is worse than his bark.', 12, '1998-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 2, 'Mommy Fearest', 'Professor Utonium falls head-over-heels in love for the lovely Ima Goodlady. Unfortunately, she''s really the sinister Sedusa, out to keep the Girls grounded for the first time ever while she commits crimes around Townsville, such as making off with the Mayor''s jewels.', 12, '1998-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 3, 'Insect Inside', 'The Powerpuff Girls hate roaches. Roach Coach uses this to his advantage to take over Townsville. Can the Powerpuff Girls overcome their fear of roaches?', 12, '1998-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 4, 'Powerpuff Bluff', 'After putting 3 criminals to jail those 3 criminals dress up as the Powerpuff Girls. Spreading crime wherever they go these impostors ruin the girls'' reputation.', 12, '1998-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 5, 'Octi Evil', 'The heinous Him toys with Bubbles'' mind by speaking to her through Octi, her favorite stuffed animal. Following Octi/Him''s instructions, Bubbles provokes a fight between her sisters that prompts the Professor to issue a time-out until the Girls can make amends and make squid meat out of the giant, Him-controlled Octi.', 12, '1998-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 6, 'Geshundfight', 'The Amoeba Boys'' ill-conceived plan to stand in front of the "Keep off the Grass" sign at Townsville Park all night in the rain leaves them with a terrible virus. When they infect the Townsville population, it''s up to the Girls to find the antidote.', 12, '1998-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 7, 'Buttercrush', 'Buttercup becomes smitten with Ace, the leader of the Ganggreen Gang. However, when the gang exploits her infatuation and lures Blossom and Bubbles into danger, Buttercup quickly comes to her sisters'' rescue and shows the boys the real meaning of the word "crush."', 12, '1998-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 8, 'Fuzzy Logic', 'A squirrel trespasses on Fuzzy Lumpkins private property. Fuzzy chases him all the way into Townsville and goes crazy hurting all the citizens that stand in his way.', 12, '1998-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 9, 'Boogie Frights', 'When all the lights go out at night the Boogie Man and his monsters come out to boogie all night long.', 12, '1998-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 10, 'Abracadaver', 'The Mayor tells the girls'' a story about a famous magician who died by a trick with a laughing audience. Now the magician has come back to life to take out his revenge.', 12, '1998-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 11, 'Telephonies', 'The Ganggreen Gang gets hold of the Mayor''s hotline to the Powerpuff Girls and makes prank calls, sending the Girls on a wild goose chase all over town. However, when it''s the notorious villain''s Mojo Jojo, Fuzzy, and Him that the gang disturbs, they learn the price of making prank calls.', 12, '1998-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 12, 'Tough Love', 'The citizens of Townsville loves The Powerpuff Girls and its annoying Him, so Him turns everyone''s love for the Powerpuff Girls into hate.', 12, '1998-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 13, 'Major Competition', 'There''s a new man in town: Major Man, an impossibly perfect superhero who cuts in on the Girls'' turf. Unfortunately, Major Man isn''t as perfect as he is supposed to be as the girls soon discover, and come up with an idea to make Major Man reveal the fraud that he is in the midst of a monster attack.', 12, '1999-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 14, 'Mr. Mojo''s Rising', 'Mojo Jojo kidnaps the Professor in a plot to steal the girls'' powers when they arrive.', 12, '1999-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 15, 'Paste Makes Waste', 'Buttercup teases paste-eating classmate Elmer. When a fly with atomic chemicals enters the paste, Elmer turns into a destructive Paste Monster. Buttercup has to get out of a sticky situation by doing something against her tough nature—apologizing.', 12, '1999-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 16, 'Ice Sore', 'On a very hot and humid day Blossom discovers that she has ice powers.', 12, '1999-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 17, 'Bubblevicious', 'Bubbles is tired of people dismissing her as more sugar than spice. When she sets out to prove she''s hardcore, she takes everyone by surprise, even Mojo Jojo.', 12, '1999-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 18, 'The Bare Facts', 'Mojo kidnaps the Mayor and the Powerpuff Girls rescue him, but when the Mayor tries to get the story out of them each Powerpuff Girl has their own version.', 12, '1999-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 1), 19, 'Cat Man Do', 'Bubbles saves a seemingly innocent little cat from the clutches of an evil villain, but when the Girls discover it''s actually the Cat who is evil, they must save the Professor from becoming the "purr-fect" victim.', 12, '1999-01-27');
