INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 5), 30, 'Live & Let Dynamo', 'Dynamo returns and this time is against Townsville and destroying the town along with terrorizing it''s citizens.', 12, '2004-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 5), 31, 'Mo'' Linguish', 'Mojo is sentenced to do community service for Townsville and begins teaching English at the Learning Annex.', 12, '2004-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 5), 32, 'Oops, I Did It Again', 'When the Professor realizes that all his successful experiments are actually just accidents, he sets out to do something brilliant on purpose!', 12, '2004-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 5), 33, 'A Made Up Story', 'Someone is defacing all the posters and statues of Townsville with make-up.', 21, '2004-05-14');
