INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 1, 'Little Miss Interprets', 'When the Girls hear the Professor trying to make something out of sugar, spice, and everything nice, they are sure he''s trying to create new little girls.', 12, '2004-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 2, 'Night Mayor', 'The Mayor keeps having the same dream over and over again, but he never sees the end. Now it''s up Girls to go into the Mayor''s head and solve this mystery.', 12, '2004-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 3, 'Custody Battle', 'When Mojo discovers that the Rowdyruff Boys have returned, he competes with Him to determine who''s the more evil father.', 12, '2004-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 4, 'City of Nutsville', 'One day during a picnic Bubbles get stung in her mouth by a bee. After a visit by the doctor she is forbidden to speak for a week. Suddenly when all the squirrels in Townsville get mad, Blossom and Buttercup are unable to do anything without Bubbles special ability. Now it''s up to Bubbles and Bullet to stop this crime.', 12, '2004-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 5, 'Aspirations', 'The Ganggreen Gang is committing brilliant crimes for Sedusa so she can get her revenge on the girls for making her bald.', 21, '2004-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 6, 'That''s Not My Baby', 'The girls rescue a baby from a monster and are forced to care for it when they can''t find its mother.', 12, '2004-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 7, 'Simian Says', '"Custody Battle" Mojo discovers that the Rowdyruff Boys are back and is determined to show them that he is a more evil dad than Him.', 12, '2004-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 8, 'Sun Scream', 'The girls get bad sunburns.', 12, '2004-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 9, 'City of Frownsville', 'Lou Gubrious sets a crying ray on Townsville.', 12, '2004-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 10, 'West In Pieces', 'Professor Utomium sends the Steamypuff Girls to save the western town of Townsville from Mojo the Kid.', 22, '2004-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 11, 'Crazy Mixed Up Puffs', 'The Powerpuff Girls must literally work as one to try and stop Mojo Jojo from destroying Townsville.', 12, '2004-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 12, 'Mizzen In Action', 'Captain Crack McGraigen and his crew are tossed forward in time.', 12, '2004-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 13, 'Roughing It Up', 'The Powerpuff Girls and the Professor set on an old-fashioned vacation to the Townsville Swamp. Trouble is, Fuzzy and his nephews are there too.', 12, '2004-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 14, 'What''s the Big Idea?', 'Twenty stories tall, The Powerpuff Girls spell disaster for Townsville when they delicately try to stop Mojo Jojo from taking over.', 12, '2004-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 15, 'Nuthin'' Special', 'Buttercup feels left out when she realizes that she doesn''t have any special powers like her sisters.', 12, '2005-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 16, 'Neighbor Hood', 'When a TV show convinces kids to send in money to enter a special contest, Bubbles and the rest of the kids in the neighbor hood raise money to enter it.', 12, '2005-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 17, 'I See a Funny Cartoon in Your Future', 'A medium named Madame Argentina, and her side-kick, Fred the duck (he really is a duck) attempt to steal money from Townsville''s citizens by offering to contact a dead relative for them.', 12, '2005-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0175058')) AND numero_temporada = 6), 18, 'Octi Gone', 'Professor Utonium is hosting a party for all the rich and famous people in Townsville, so Bubbles makes sure that she is the most beautiful of the girls by continually grooming herself. While doing this, she notices one of Octi''s legs poking out from under the girls'' bed, so she goes to pick him up to find that all that''s there is one of Octi''s legs! After waking up from the shock, she vows to exact revenge on the person who ''killed'' Octi.', 12, '2005-03-25');
