INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')), 1, 'Series 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 1, 'Beginnings', 'The plot for the entire series begins here: two late twenty somethings who are looking for a place to live. They find one, only it means posing as a couple, and so the two main characters, Tim and Daisy, set off to learn about each other. This way we are introduced to the various characters and their backgrounds.', 25, '1999-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 2, 'Gatherings', 'Once the new roommates have finished unpacking, Daisy is looking for any excuse not to sit down and do some work. So, she persuades Tim to throw a housewarming party, complete with the paperboy as a guest, a homemade foil mirror ball, and Prefab Sprout on the stereo!', 25, '1999-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 3, 'Art', 'Brian receives an invitation to the new performance art show of his ex-partner Vulva. He plucks up the courage to go, along with Tim and Daisy, but is treated horribly by Vulva. Tim comes to the rescue after his violence tendencies are brought out by a bowl of Twiglets. Meanwhile, Daisy has a magazine interview which doesn''t go too well, and the experience leads her to try a little performance art of her own.', 26, '1999-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 4, 'Battles', 'After being dumped by her boyfriend, Daisy decides she needs companionship and heads to the pound to get herself a dog, not realizing that Tim is scared of dogs. Meanwhile, Tim and Mike go paint balling, and meet up with Duane Benzie, the man who Tim''s ex girlfriend Sarah left him for.', 25, '1999-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 5, 'Chaos', 'Colin goes missing when Tim takes him out for a late night walk, and at first Daisy suspects that Tim has deliberately got rid of him. Later, they receive a note tipping them off that Colin has been dognapped by an evil vivisectionist! They gather the troops and start a rescue mission.', 25, '1999-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 6, 'Epiphanies', 'Tim''s friend Tyres stops by the flat and invites the two "friends" out for a night of clubbing. They decide to take him up on the offer, and round up Mike, Brian and Twist to join them.', 25, '1999-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 1), 7, 'Ends', 'Tim''s ex Sarah calls him up and wants to get together, Tim is over the moon at the idea of them getting back together, though Mike and Daisy are less impressed and worried about him getting hurt again. Meanwhile, Mike is up for re-evaluation for the TA, and is delighted to be let back in. Tim meets up with Sarah and it turns out she really does want to try again with him, but at the last moment he sees sense and declines, not wanting to give up all his has with Daisy and his friends.', 25, '1999-11-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')), 2, 'Series  2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 1, 'Back', 'Daisy returns from her Eastern travels to find Mike has been living in her room, and that the enigmatic stranger she met on the way may have been even more mysterious than she thought. Turns out that he swapped bags with her, and she''s now being followed by secret agents keen to get to the contents.', 25, '2001-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 2, 'Change', 'The fighting between Marsha and her daughter Amber escalates, until Amber finally storms out, leaving Marsha with an empty room. Meanwhile, Daisy is still out of work, and Tim has been fired for getting a bit too worked up about The Phantom Menace. The two of them head to the dole office together, but after Daisy is refused any money, things look bad. Especially when they arrive home to find Mike has moved upstairs into the now spare room.', 25, '2001-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 3, 'Mettle', 'Mike and Tim are through to the quarter finals of Robot Wars, but trouble is brewing as a rival team who didn''t get through decide to sabotage their efforts. Meanwhile, Brian is invited to do an installation at an art gallery, and Marsha goes along to offer support and enjoy the free booze.', 25, '2001-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 4, 'Help', 'Tim is delighted but nervous as anything when Damian Knox of Darkstar Comics asks him to bring in his portfolio. The last time they met Knox cruelly put down Tim''s work, hence Tim drew a less than flattering portrait of him. Daisy puts this drawing into Tim''s portfolio, trying to help, and leaving Tim with a short time to retrieve the drawing, with the assistance of Mike and Tyres.', 26, '2001-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 5, 'Gone', 'When Sophie has to cancel a date with Tim at short notice, he and Daisy decide to go out for the evening, leaving Mike and Brian in charge of walking Colin. Tim and Daisy''s adventures include bumping into Tim''s old enemy Duane Benzie, a group of angry teens who are trying to score, and losing their keys.', 25, '2001-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 6, 'Dissolution', 'The gang go out for dinner to celebrate Daisy''s birthday, and Marsha gets very suspicious as Tim flirts constantly with Sophie and seems to pay no attention to Daisy. She eventually tells Daisy that she saw the two of them kissing, leading Daisy to admit that she and Tim aren''t really a couple and never were. Marsha is devastated to find out that they''d all been lying to her, and storms out of the restaurant and then the flat.', 27, '2001-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0187664')) AND numero_temporada = 2), 7, 'Leaves', 'When Tim, Daisy and the others discover that Marsha has put the place up for sale, they panic and start trying to make plans to find her and win her back. Meanwhile, Daisy is offered a job on a local newspaper back home, and decides to take it, and Sophie is also leaving for a new job - though hers is in Seattle. After successfully getting through to Marsha, Tim finds the note from Daisy saying she''s leaving. He is forced to send Mike to take Sophie to the airport whilst he rushes to the train station to persuade Daisy to stay.', 27, '2001-04-13');
