INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 1, 'Indigo League', 'It’s Ash Ketchum’s tenth birthday, and he’s ready to do what many 10-year-olds in the Kanto region set out to do—become a Pokémon Trainer! Things don’t go exactly the way he planned when he ends up with a Pikachu instead of a standard first Pokémon, and winning Gym Badges turns out to be much tougher than he thought. Luckily he’s got former Gym Leaders Brock and Misty at his side, along with a bevy of new Pokémon friends, including Bulbasaur, Squirtle, and Charmander.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 1, 'Pokémon - I Choose You!', 'Meet Ash Ketchum, a 10-year-old boy full of imagination, confidence, and dreams that are almost too big for his village of Pallet Town—plus the desire to become a Pokémon Master!', 23, '1997-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 2, 'Pokémon Emergency!', 'Ash rushes into Viridian City with his gravely wounded Pikachu. The city''s on high alert for Pokémon thieves-thieves like Jessie, James, and Meowth of Team Rocket, a group of bad guys dedicated to stealing valuable Pokémon.', 23, '1997-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 3, 'Ash Catches a Pokémon', 'Ash discovers and catches a Caterpie—his first Pokémon capture! Though Ash is excited, Misty is grossed out by Bug-type Pokémon, so she is repulsed by its attempts to be friends with her. At night, as Ash and Misty sleep, Caterpie shares with Pikachu its dream of evolving into a Butterfree.', 23, '1997-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 4, 'Challenge of the Samurai', 'Misty and Ash continue to wander the Viridian Forest when they spot a Weedle. As Ash battles it, he''s distracted by a boy dressed as a samurai and calling himself (naturally) Samurai. Samurai challenges Ash to a battle, and Ash gets the advantage when his Metapod defends itself against Samurai''s Pinsir. Samurai sends out his own Metapod—and a standoff begins.', 23, '1997-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 5, 'Showdown in Pewter City', 'Jessie, James, and Meowth dig a trap for our heroes, but they end up falling into it themselves! Ash and Misty arrive at Pewter City and meet a curious fellow named Flint, who notices that Pikachu is tired and shows them the way to the Pokémon Center.', 23, '1997-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 6, 'Clefairy and the Moon Stone', 'Will Team Rocket steal the Moon Stone? Are there other Clefairy lurking about, and do they carry Moon Stones, too? And is the legend of the Moon Stone true?', 23, '1997-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 7, 'The Water Flowers of Cerulean City', 'Ash seeks the Cascade badge in Cerulean City—but for some reason, Misty doesn''t want to join them. When Ash and Brock show up, the city is buzzing about a break-in that just took place—and are initially accused of the crime!', 23, '1997-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 8, 'The Path to the Pokémon League', 'On the way to Vermillion City, Ash meets AJ, a Gym Leader at an unsanctioned Gym who has 98 wins and zero losses. They battle, and Ash is surprised that AJ''s Ground-type Sandshrew can easily beat his Flying-type Pokémon.', 23, '1997-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 9, 'The School of Hard Knocks', 'While searching for firewood in the foggy woods, Ash and Pikachu discover a bunch of prep-school kids bullying a classmate named Joe.', 23, '1997-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 10, 'Bulbasaur and the Hidden Village', 'Ash and Misty, while arguing, discover an Oddish. As Misty''s Starmie weakens the Oddish, a Bulbasaur appears and fights Starmie while the Oddish runs off into the woods.', 23, '1997-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 11, 'Charmander - The Stray Pokémon', 'Our friends, lost, discover an injured Charmander. Pikachu talks to it and learns that it''s been waiting a long time for its trainer to return.', 23, '1997-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 12, 'Here Comes the Squirtle Squad', 'Ash and his friends walk along a path and fall into a hole dug by a batch of mischievous Squirtle. Ash climbs out and tries to battle them, but they scatter when Officer Jenny arrives.', 23, '1997-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 13, 'Mystery at the Lighthouse', 'A tremendously large shadow begins to take form in the sea mists, but this possible discovery could be hindered due to the infamous Team Rocket lurking in the background cooking up another one of their schemes.', 23, '1997-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 14, 'Electric Shock Showdown', 'Our heroes finally reach Vermillion City, and they discover that the Pokémon Center is filled with Pokémon hurt during battles with Lt. Surge, the Vermillion City Gym Leader.', 23, '1997-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 15, 'Battle Aboard the St. Anne', 'Ash and his friends board a fancy cruise ship called the St. Anne, thanks to tickets provided by two friendly but familiar-looking people. We soon learn that they''re actually Jessie and James in disguise!', 23, '1997-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 16, 'Pokémon Shipwreck', 'The St. Anne has capsized and sunk with Ash, the gang, and Team Rocket trapped inside. Now, both sides must put aside their differences in order to escape.', 23, '1997-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 17, 'Island of the Giant Pokémon', 'As our heroes and Team Rocket beat the odds by surviving the sinking ship, they are dragged into another potentially deadly situation when they are attacked by the ferocious Pokémon, Gyarados.', 23, '1997-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 18, 'Beauty and the Beach', 'Ash and his friends have finally arrived in Porta Vista, a beach-side tourist town. After destroying an old man''s ship, they must help in the old man''s business. To attempt to pay the man back faster, Misty enters a beauty contest, only to discover she is competing against Jessie and James.', 23, '1997-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 19, 'Tentacool & Tentacruel', 'Our heroes arrive at Hutber Port, where a ferryboat line runs to the mainland.', 23, '1997-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 20, 'The Ghost of Maiden''s Peak', 'After leaving Acapulco in search of Saffron City, our heroes finally arrive at a small port town in the middle of celebrating a summer festival.', 23, '1997-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 21, 'Bye Bye Butterfree', 'When the party sees a flock of Butterfree flying above the ocean, Brock, as a Pokémon breeder, explains that it is the Butterfree''s egg-laying season.', 23, '1997-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 22, 'Abra and the Psychic Showdown', 'The party finally arrives in Saffron City where a young girl manages a gym of Pokémon using her psychic powers. If Ash defeats this particular Gym Leader, Ash can earn a gold badge.', 23, '1997-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 23, 'The Tower of Terror', 'In search of a ghost Pokémon, Ash heads immediately for a tower in Lavender Town where they are said to dwell.', 23, '1997-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 24, 'Haunter Versus Kadabra', 'Unbeknownst to Ash, one of the ghost Pokémon decides to join Ash and friends on their journey and more importantly help Ash battle the powerful Saffron City Gym Leader.', 23, '1997-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 25, 'Primeape Goes Bananas', 'On their way to Celadon City, our heroes encounter Mankey, a wild Pokémon that if rubbed the wrong way can go into uncontrollable fits. Not realizing its unpredictability, the party accidentally upsets Mankey.', 23, '1997-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 26, 'Pokémon Scent-sation!', 'The party arrives in Celadon City, a perfectly pleasant town full of large department stores, condominiums, and fancy arcades.', 23, '1997-09-23');
