INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 28, 'Pokémon Fashion Flash', 'At Brock''s persistent request, our heroes stop by Caesar Street, a town of breeders famous for its Pokémon beauty salons.', 23, '1997-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 29, 'The Punchy Pokémon', 'In the outskirts of Fuchsia City, our heroes come across Hitmonchan, a fighter-Pokémon. With little thought, Ash attempts to capture it, but he and Pikachu are badly defeated.', 23, '1997-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 30, 'Sparks Fly for Magnemite', 'As our heroes make their way through the industrial town of Gringy City, Pikachu, perhaps weary from travel, is in a strange state; the electric sacks on his cheeks are continually twitching as though overcharged.', 23, '1997-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 31, 'Dig Those Diglett!', 'Ash, Brock, Misty and Pikachu are lost deep in the mountains. As they press forward on a rough road not even shown on their map, they suddenly hear a large explosion.', 23, '1997-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 32, 'The Ninja-Poké Showdown', 'Fuchsia Gym, the authorized gym where Ash seeks his next badge, turns out to be a hidden ninja''s lair. After finally discovering and entering the gym, he is held up by a complex system of traps.', 23, '1997-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 33, 'The Flame Pokémon-athon!', 'Our heroes come to a prairie where the Laramies, a family of Pokémon Ranchers live. They learn from a daughter of the Laramie family that a race is held at the ranch once a year to measure the growth of everyone''s Pokémon.', 23, '1997-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 34, 'The Kangaskhan Kid', 'Our heroes accompany Officer Jenny into the forest, intent on pursuing the Pokémon poachers in the area.', 23, '1997-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 35, 'The Legend of Dratini', 'Ash and his friends get challenged by Team Rocket in seeing who can capture the most Pokémon within the Safari Zone, with Ash catching a whole herd of Tauros. As soon as Ash and his friends head out Pokémon hunting, Team Rocket manages to get the drop on the game warden (Mr. Kaiza) and forces him into giving up the location on where Dratini is (the Dragon Valley). In the end, Ash, his friends, Team Rocket, and Kaiza end up seeing the legendary Dratini and Dragonair, with the heroes saving the day.', 23, '1997-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 36, 'The Bridge Bike Gang', 'Ash and the others happen upon a town that can only be reached by a long bike bridge, but they don''t have enough money to rent bikes for the crossing.', 23, '1997-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 37, 'Ditto''s Mysterious Mansion', 'Our heroes take shelter in a cabin that turns out to be the Copycat House of a trainer who has a Pikachu that is a Ditto, the Transform Pokémon.', 23, '1997-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 38, 'Cyber Soldier Porygon', 'Ash and his friends arrive at Pokémon Center where the PokéBall transfer machine has been causing problems, as the transferred Pokémon never end up at the other side. Ash and his friends decide to accompany Porygon, a computerized Pokémon, used by Professor Akihabara to investigate the problem, only to discover Team Rocket and another Porygon are to blame.', 23, '1997-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 39, 'Pikachu''s Goodbye', 'Ash and the others discover a group of wild Pikachu in a secluded area of the woods. How will Pikachu feel seeing others of its kind in the wild?', 23, '1998-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 40, 'The Battling Eevee Brothers', 'Tracing a path through the woods, the party comes across a tree baited with a plate of food and water. An Eevee is bound to the trunk with string.', 23, '1998-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 41, 'Wake Up, Snorlax!', 'On empty stomachs, our heroes'' search for food brings them to a small village, but find there is no food at the bakery nor at the grocery store; even the town restaurant is out of food.', 23, '1998-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 42, 'Showdown at Dark City', 'In the middle of a terrible desert, our heroes inadvertently wandered into Dark City. With no name but Dark, the city has fallen into ruin.', 23, '1998-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 43, 'The March of the Exeggutor Squad', 'After discovering there''s a traveling carnival nearby, Ash, Misty and Brock join in on the fun of the fair and stumble across a rather dull magic show.', 23, '1998-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 44, 'The Problem with Paras', 'Team Rocket never let up with their constant interception, but today something seems strange. The coin on Meowth''s forehead is blinking red, indicating overheating.', 23, '1998-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 45, 'The Song of Jigglypuff', 'Our heroes trudge along, resigning themselves to the idea of camping out in the desert as the sun slowly sets. Suddenly they see bright lights in front of them: a glamorous city appears before them, covered in neon lights.', 23, '1998-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 46, 'Attack of the Prehistoric Pokémon', 'Our heroes approach Grampa Canyon, famous for the beautiful scenery of its valley. As they approach, however, they find wave upon wave of people also heading for Grampa Canyon.', 23, '1998-05-28');
