INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 60, 'Beach Blank-Out Blastoise', 'As Ash and the gang are rushing to catch the last ferry off of Cinnabar Island, they stumble over a rare Pokémon in trouble.', 23, '1998-08-27');
