INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 62, 'Clefairy Tales', 'Ash, Brock and Misty get sidetracked on their way to Viridian City when all of their belongings mysteriously disappear.', 23, '1998-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 63, 'The Battle of the Badge', 'Ash and friends finally make their way to Viridian City where Ash hopes to earn his Earth Badge.', 23, '1998-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 64, 'It''s Mr. Mime Time!', 'On their way back to Pallet Town, Ash, Brock and Misty encounter a runaway Mr. Mime.', 23, '1998-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 65, 'Holiday Hi-Jynx', 'Ash, Misty, Brock, and their Pokémon must return a lost Jynx to Santa before Christmas, with the help of a Lapras. Meanwhile, Jessie attempts to take revenge on Santa for stealing her favorite doll when she was young.', 23, '1998-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 66, 'Snow Way Out!', 'Pikachu is lost in a snowy mountain forest! Can Ash and the gang stay warm while tracking down their missing pal?', 23, '1998-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 67, 'Showdown at the Po-ké Corral', 'Back in Pallet Town, Ash finds Gary, already there, waiting to partake in the Pokémon League. Always having a bitter rivalry with Gary, Professor Oak tells them both the meaning of Pokémon. Meanwhile, Team Rocket is trying to get inside the lab to steal the Pokémon.', 23, '1998-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 68, 'The Evolution Solution', 'Ash goes to Seafoam Island to help Professor Oak to discover the mystery of how Slowpoke evolves into Slowbro. There, Professor Westwood V is also trying to solve the mystery. Jessie captures Shellder, and tries to rush a Slowpoke''s evolution, forcing Psyduck to stall the evolution.', 23, '1998-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 69, 'The Pi-Kahuna', 'Ash and the gang take some time off to go surfing. While surfing, however, Ash passes out, but is thankfully rescued by a surfer named Victor and his blue-eyed Pikachu, Puka. Victor then reveals his plans to surf a tsunami called Humungadunga and become a surfing legend.', 23, '1998-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 70, 'Make Room for Gloom', 'Ash goes to a flower garden to get some fertilizer for his mother, but Bulbasaur sniffs the flowers and becomes paralyzed.', 23, '1998-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 71, 'Lights, Camera, Quack-tion', 'When the gang discovers there is a movie with an all-Pokémon cast being made nearby, Ash and his friends put their Pokémon in for an audition. Misty''s Psyduck gets the main role while the others get minor roles.', 23, '1998-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 72, 'Go West Young Meowth', 'Ash and his friends go to Hollywood (although only a small nearby town) to see the premiere of the movie their Pokémon were cast in. Team Rocket follows them to find out that Meowth has history in this town; It is here where he was a member of a gang of street Meowths led by the Persian. He learned to speak and walk upright to win the heart of a female Meowth who was abandoned by her owner. Upon returning, he challenges Persian who was once his mentor for the female Meowth he thought he lost years before.', 23, '1998-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 73, 'To Master the Onixpected!', 'After watching Elite Four member Bruno on TV, Ash and his friends decide to do training in the mountains to be as strong as Bruno. However, they meet Bruno and he manipulates them to do some menial tasks for him. Meanwhile, a giant Onix is on a rampage.', 23, '1998-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 74, 'The Ancient Puzzle of Pokémopolis', 'While training, Ash and his friends accidentally uncover the ruins of Pokémopolis, an ancient city. After a bit of research, they find a giant Gengar and a giant Alakazam starting to fight. Then, a giant Jigglypuff appears to put them to sleep.', 23, '1998-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 75, 'Bad to the Bone', 'Ash and his friends offer to help a trainer that is heading for the Pokémon League to retrieve his stolen gym badges from Team Rocket.', 23, '1998-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 76, 'All Fired Up!', 'Ash finally reaches the Indigo Plateau, home of the Pokémon League conference. Before the tournament begins, they plan on lighting a ceremonial cauldron with the flame of the legendary Pokémon, Moltres. Ash, as a participant, is free to carry the flame but when Team Rocket steals it, the tournament may be cancelled.', 23, '1998-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 77, 'Round One - Begin!', 'Ash enters his first match of the tournament on the water field against Mandi the Astounding. During the battle against Mandi''s Exeggutor, Ash''s Krabby evolves into Kingler, who he then uses against Mandy''s remaining Seadra and Golbat, winning the match and moving onto the next preliminary round.', 23, '1998-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 78, 'Fire and Ice', 'For the second round Ash battles in the rock arena. Ash''s last Pokémon, Squirtle, defeats his foe''s last Pokémon, Nidorino, and he, victorious, moves on to Round 3. In the third round Ash faces a trainer named Pete in the ice arena. Both trainers are left with 2 Pokémon each. Pete uses Cloyster and Arcanine. In the end, Ash is victorious and he moves on to Round 4.', 23, '1998-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 79, 'The Fourth Round Rumble', 'In the 4th round, Ash faces a trainer named Jeanette, who uses a Beedrill, a Scyther, and a Bellsprout. The match ends with Ash victorious, and he moves on to the 5th round, becoming one of the final sixteen members of the tournament.', 23, '1999-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 80, 'A Friend in Deed', 'Ash meets a new trainer named Richie, who is eerily similar to Ash, including owning a Pikachu. However, Team Rocket makes another attempt to steal Ash''s and Richie''s Pokémon. Ash and Richie prevent Team Rocket from stealing their Pokémon. Ash discovers his next battle is against Richie. Will Ash manage to reach the quarterfinals?', 23, '1999-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 81, 'Friend and Foe Alike', 'A twist of fate pits Ash and his new friend, Richie, against each other in the fifth round of the Pokémon League Competition. Both are determined to triumph, but who will emerge victorious? And, can their friendship survive the struggle?', 23, '1999-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 1), 82, 'Friends to the End', 'After losing to Richie in the fifth round, Ash is moping around, annoyed that he lost. He is convinced by Misty that he should support Richie who is now in the quarterfinals. However, when Richie loses, they both have to look inside themselves to see if they are good trainers.', 23, '1999-01-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 2, 'Adventures in the Orange Islands', 'With his Kanto journey completed, Ash finds there’s still plenty to see and do when Professor Oak sends him and his friends to the Orange Islands. Brock falls head-over-heels for the attractive Professor Ivy and decides to stay with her, leaving Ash and Misty alone as a dynamic duo—at least until they meet intrepid Pokémon watcher Tracey Sketchit!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 1, 'Pallet Party Panic', 'After battling in the Pokémon League Tournament, Ash and his friends return to Pallet Town for a hero''s welcome.', 23, '1999-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 2, 'A Scare in the Air', 'Ash, Brock, and Misty prepare for their long journey to Valencia Island to bring back a mysterious Poké Ball for Professor Oak. After discovering that the trip will take a month to get there, Ash manages to win a free blimp ride so it will take only a day! Once on board, they realize the blimp is being powered by Team Rocket! And things only get worse from there!', 23, '1999-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 3, 'Pokéball Peril', 'After making a crash landing onto Valencia Island, our heroes get directions to Professor Ivy''s laboratory where the mysterious Pokéball is being held. Once at the laboratory, Brock realizes that Professor Ivy and her group of scientists are Pokémon breeders just like him! Suddenly Brock begins to feel at home and thinks about staying for awhile to continue his studies on Pokémon breeding.', 23, '1999-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 4, 'The Lost Lapras', 'After picking up the GS Ball from Professor Ivy, Brock decided to stay on the island so Ash and Misty head back home by blimp. Unfortunately, our duo gets double-crossed by Team Rocket once again, and Jigglypuff puts the whole crew to sleep. After another crash landing in the middle of nowhere they meet a new friend named Tracey while trying to help a Lapras that washed up on the beach.', 23, '1999-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 5, 'Fit To Be Tide', 'Ash, Misty and their new friend, Tracey, are on a new adventure exploring the Orange Islands as Ash sets out to qualify for the Orange League Tournament. After hearing that the Mikan Gym Leader is known as one of the toughest trainers in the Orange Crew, Ash can''t wait for the challenge. He learns that Pokémon battles are run a little differently on the Orange Islands, but he can always rely on his Squirtle to pull them through!', 23, '1999-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 6, 'Pikachu Re-Volts', 'Just as Ash, Misty, and Tracey set foot on Mandarin Island, Pikachu and Togepi turn against them and join a group of other angry Pokémon. When the misbehaving Pokémon disappear, Officer Jenny arrives and informs them that dozens of Pokémon have been reported missing, including Meowth! Everyone fears a Psychic attack is behind this mystery. Will Jessie and James actually join forces with our heroes? Could they possibly win a battle for the first time?', 23, '1999-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 7, 'The Crystal Onix', 'While riding around the Orange Islands on his Lapras, Ash finds a mysterious message in a bottle, which leads the gang on a new adventure. Ash, Misty and Tracey travel to Sunburst Island, which is famous for its artists and glassblowers. They meet a struggling young shopkeeper who''s seeking inspiration from a legendary crystal Onix. Having been unable to find this special Pokémon, the shopkeeper turns to our heroes. With Tracey and his observational Pokémon on board, they set out to fire up a new friend''s creative drive!', 23, '1999-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 8, 'In the Pink', 'Ash and friends are caught in a whirlpool and swept to an unexplored island where all the Pokémon are pink. It''s Pinkan Island, a Pokémon refuge where the Pokémon''s diet of Pinkan Berries causes their unique coloration. But the Pokémon aren''t all as sweet as they look. Our heroes cross paths with an enraged Nidoking, and end up cornered under a cliff.', 23, '1999-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 9, 'Shell Shock!', 'Aboard Lapras, the group follows a news crew to an uninhabited island, where a scientific expedition is underway after the discovery of a fossilized Kabuto. A series of natural disasters place our heroes in mortal danger, with only the power of their Pokémon to help them. What is the secret of the Kabuto, and who wants that secret to remain hidden?', 23, '1999-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 10, 'Stage Fight!', 'Misty meets another female trainer who also is an expert on water Pokémon. The new trainer notices some signs that Misty''s Psyduck may be ready to evolve. As the two prepare for a Pokémon battle, a Golduck springs from the water and battles for Misty. With her powerful new Pokémon, can Misty defeat both her newfound friend and Team Rocket?', 23, '1999-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 11, 'Bye Bye Psyduck', 'After stopping on another island to rest, Misty notices her Psyduck''s tail is glowing, a nearby trainer says it may mean it is time for it to evolve. So Misty challenges her to battle and when she finds she has a Golduck, she easily beats the trainer. However, Team Rocket has other plans. Later, Golduck turns out to be a wild Pokémon as Misty''s Psyduck makes an appearance. ', 23, '1999-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 12, 'The Joy of Pokémon', 'While riding Ash''s Lapras to the next island, Ash and the gang come across a tanned Nurse Joy who insists on healing Wild Water Pokémon on the island. Ash and Tracey decide to help out, but when Team Rocket arrives to stop them, a giant Magikarp arrives.', 23, '1999-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 13, 'Navel Maneuvers', 'The group arrive on Navel Island where Ash finds himself up against the Gym Leader, Danny as Ash competes for his second Orange League badge. Misty tries to tempt Ash by showing more caring attitude to Danny. Ash once again gets jealous and sad.', 23, '1999-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 14, 'Snack Attack', 'Arriving on the Grapefruit Islands, Ash discovers that there is a Snorlax going from island to island eating all the grapefruits. Ash is employed to help stop the Snorlax, but the Snorlax proves to be slippery. Later on, Ash captures the Snorlax.', 23, '1999-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 15, 'A Shipful of Shivers', 'Arriving on Moro Island, Ash and his friends hear about a long lost Orange League Trophy being found on a sunken ship, but when Team Rocket steals it, Ash and the gang follow them to a ghost ship inhabited by a Gastly and Haunter.', 23, '1999-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 16, 'Meowth Rules!', 'Meowth finds himself on an island where the inhabitants believe him to be a "Meowth God".', 23, '1999-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 17, 'Tracey Gets Bugged', 'Arriving on Murcott Island, Ash and his friends discover a wounded Scyther. After capturing it, Tracey must take it to a Pokémon Center. While there, he discovers the Scyther got dethroned from being in charge of his group.', 23, '1999-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 18, 'A Way Off Day Off', 'Deciding to take a break on a nearby island, Ash, his friends, and all their Pokémon just use the time to relax and get better acquainted. However, Team Rocket has other plans for the Pokémon and intend to steal them.', 23, '1999-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 19, 'The Mandarin Island Miss Match', 'The group descend on Mandarin Island where Ash''s arrogance emerges due to the fact that he''s won every single battle he''s had since arriving on the island but upon meeting Prima, a member of the Elite Four and challenging her to a battle, Ash starts to realize that he may have made a grave mistake.', 23, '1999-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 20, 'Wherefore Art Thou, Pokémon', 'Still on Mandarin Island, Ash and his friends go through Victorian Town where they find two Nidoran who are in love with each other but any possible hint of a relationship is being derailed by the trainers who happen to be childhood rivals.', 23, '1999-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 21, 'Get Along, Little Pokémon', 'Ash and his friends discover a man who has troops of Magnemite and has to take them to a town on the island in order to give it power. However, he gets injured, so it is up to Ash to herd up the Magnemite and get to the town.', 23, '1999-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 22, 'The Mystery Menace', 'Heading to the other end of Mandarin Island, Ash and his friends discover there''s a monster in the sewer that is causing lots of problems in the town. When the Mayor wants to blow it up, Joy protests and asks Ash and company to help.', 23, '1999-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 23, 'Misty Meets Her Match', 'Ash arrives on Trovita Island prepared to battle for his third Orange League Gym Badge. However, much to Ash''s dismay, the Gym Leader, Rudy has more than just battling on his mind, Rudy develops a crush on Misty, and Ash gets jealous once again. Rudy moves in to court Misty after she helps rescue his younger sister, Mahri. While Ash battles for the Spike Shell Badge, Misty considers the tempting offer to stay on the island with Rudy and Mahri forever.', 23, '1999-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 24, 'Bound for Trouble', 'After getting his 3rd Orange League Badge, Ash and his friends arrive on an island, where Pikachu is soon captured by Team Rocket and is chained to Meowth. But soon after Pikachu and Meowth are taken away by a giant Pidgeot, the trapped rivals eventually learn how to get along.', 23, '1999-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 25, 'Charizard Chills', 'After hearing about Ash from the Trovita Island gym leader, another trainer seeks him out for a battle. When Pikachu is knocked out during the battle, Ash turns to his Charizard, but he struggles to make the unruly Pokémon listen to him.', 23, '1999-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 26, 'The Pokémon Water War', 'On the next island, Ash and his friends see a team of firefighters consisting of Squirtles, Wartortles, and Blastoises. Eager to test its skills, Ash''s Squirtle get to train with them. But when an actual fire turns up, training has to become reality.', 23, '1999-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 27, 'Pokémon Food Fight!', 'While in a battle, Ash accidentally breaks Snorlax''s Pokéball. With the Pokémon Center on the other side of the island, Ash and his friends have to get Snorlax there. And to make matters worse, Team Rocket arrive and are hoarding the island''s food ransom until they get Pikachu.', 23, '1999-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 28, 'Pokémon Double Trouble', 'On Kumquat Island, Ash discovers Luana, the final Orange Island Gym Leader, who mistakes him for her son. After defending the island from Team Rocket, they head to the Gym to have a Double Battle where Pikachu and Charizard battle against Marowak and Alakazam but Pikachu''s and Charizard''s unwillingness to work together might end up costing Ash his chance of qualifying for the Orange League.', 23, '1999-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 29, 'The Wacky Watcher!', 'On Rind Island, Tracey meets Dr. Quackenpoker, a noted Pokémon Watcher who is doing a study on the Magikarp that climb up waterfalls and how they evolve into Gyarados. However, Team Rocket appears to steal the Magikarp and get them to evolve.', 23, '1999-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 30, 'The Stun Spore Detour', 'On Tiny Island, Ash and Tracey get affected by Stun Spore leaving it up to Misty to get an antidote to heal them. Can Misty find it with the help of her new Poliwag?', 23, '1999-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 31, 'Hello, Pummelo!', 'After winning his way to the final competition for the Orange League Winner''s Trophy, victory seems a long shot for Ash as the Gym Leader deploys a powerful Gengar that topples one of Ash''s Pokémon after another.', 23, '1999-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 32, 'Enter the Dragonite', 'As if a gym battle with a Dragonite isn''t challenge enough for one day, Team Rocket secretly surveys the weakened state of Ash''s battling Pokémon and plots to turn the situation to their advantage.', 23, '1999-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 33, 'Viva Las Lapras', 'It''s piracy on the open seas and Ash and friends must rescue a local school of Lapras from would-be poachers, but how can they be of help when the Lapras, conditioned to fear humans, shun the young Trainers?', 23, '1999-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 34, 'The Underground Round-Up', 'Having to travel by boat, Ash and his friends arrive on Hamlin Island, their final stop before returning to Kanto to discover that the town is being attacked by hundreds of Electrode. A man named Poncho is trying to stop them with his Diglett.', 23, '1999-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 35, 'A Tent Situation', 'They’re back in Pallet Town. When they get home, they discover Brock is back and he won’t explain why he left Valencia Island. However, as usual, Team Rocket try to steal all of the Pokémon in Oak’s lab by vacuuming all the Pokéballs, including the GS Ball that Oak was working on. Can they get it back?', 23, '1999-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 2), 36, 'The Rivalry Revival', 'An errand of Professor Oak''s sets Ash on the road once again, but first he must face his old hometown rival, Gary, in a Pokémon battle.', 23, '1999-10-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 3, 'The Johto Journeys', 'Upon returning to Pallet Town, Ash and Misty reunite with Brock and set out on the next stage of their Pokémon journey—the Johto region! Though he still has an errand to run for Professor Oak, Ash jumps with both feet into the Johto League, taking on a couple of Gym Leaders and adding Pokémon like Totodile and Chikorita to his team.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 3), 1, 'Don''t Touch That ''dile', 'Ash begins his journey in Johto, a largely unexplored region said to be thickly populated with Pokémon entirely new to him and his friends.', 23, '1999-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 3), 2, 'The Double Trouble Header', 'In a Pokémon battle, Ash soundly defeats an ambitious young Trainer, who runs away dejectedly.', 23, '1999-10-21');
