INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 3), 7, 'Spinarak Attack', 'Ash and friends reach a new town and hear of three mysterious robbers apparently mimicking the crimes of a legendary master thief.', 23, '1999-11-25');
