INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 3), 39, 'Forest Grumps', 'When an Ursaring attack leaves Team Rocket and our heroes in compromising positions, compromise they do, members of each team being paired with members of the other.', 23, '2000-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 3), 40, 'The Psychic Sidekicks!', 'Our heroes come to a town whose residents all raise Psychic Pokémon to repel the Ghost Pokémon that lurk nearby', 23, '2000-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 3), 41, 'The Fortune Hunters', 'A Pokémon Fortune Telling boom turns out to be a Team Rocket plot to steal Pokémon from local trainers.', 23, '2000-07-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 4, 'Johto League Champions', 'From the sprawling metropolis of Goldenrod City to the icy peak of Snowtop Mountain, the Johto region presents Ash, Misty, and Brock with exciting new adventures—along with a few familiar faces like their old friends Todd, Duplica, and Suzie! Johto’s rich past means plenty of Pokémon mysteries for our heroes to solve, and its exciting present means some tough challenges—Ash tackles three more Gyms, while handling competitions like the Pokémon Sumo Conference along the way.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 1, 'A Goldenrod Opportunity', 'Arriving in Goldenrod City, Ash is ready for his next Gym battle, but the Gym appears to be closed. Their plans delayed, our heroes decide to explore the vibrant city.', 23, '2000-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 2, 'A Dairy Tale Ending', 'After losing to Whitney at the Goldenrod Gym, Ash is thinking of a rematch with her powerful Miltank. When Whitney suggests a trip to a Miltank dairy, it''s just the chance he''s is looking for!', 23, '2000-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 3, 'Air Time!', 'With his new Gym badge in hand, Ash is asked to appear on a local radio station. But while he''s acting out a radio drama with some "professional actors," the scripted danger becomes all too lifelike!', 23, '2000-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 4, 'The Bug Stops Here', 'A Bug Pokémon Catching Contest turns into a hive of activity when Ash goes up against his rival Casey-and it isn''t long before the Team Rocket villains swarm the scene, intent on catching a few things for themselves...', 23, '2000-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 5, 'Type Casting', 'On the way to Ecruteak City, our heroes are trapped on the wrong side of a river. To get across, they first have to find a Sudowoodo...which, even for an expert, is no easy feat!', 23, '2000-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 6, 'Fossil Fools', 'When an ex-student of Professor Oak''s discovers some restored Omanyte and Omastar in the wild, our heroes are called into action to save these prehistoric Pokémon from harsh times with Team Rocket!', 23, '2000-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 7, 'Carrying On!', 'The Pidgey Express courier service is in need of our heroes'' helping hands, especially when Team Rocket wants to have the delivery Pidgey signed, sealed, and delivered to the Boss!', 23, '2000-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 8, 'Hassle in the Castle', 'Caught in a sudden downpour, our heroes find a castle clinic that uses Pokémon healers to help patients. But when Brock and the doctor end up trapped in the castle''s labyrinth, a helping hand is needed to get them out!', 23, '2000-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 9, 'Two Hits and a Miss', 'After meeting the elderly owner of a Pokémon dojo, Ash is called upon to replace the man''s granddaughter as the chosen heir! But when a vicious challenger approaches, can Ash help defend the dojo from destruction?', 23, '2000-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 10, 'A Hot Water Battle', 'Chikorita, Cyndaquil, and Totodile find themselves separated from the group and stuck in a ravine! When Meowth finds himself stuck too, an unlikely partnership forms!', 23, '2000-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 11, 'Hook, Line, and Stinker', 'Misty is reeled into a rivalry at a local Seaking fishing competition. Can she come out on top?', 23, '2000-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 12, 'Beauty and the Breeder', 'A Pokémon breeding contest gives our heroes a chance to compete, greet an old friend, and defeat Team Rocket once again!', 23, '2000-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 13, 'A Better Pill to Swallow', 'When Ash comes down with a serious stomach ache far from any hospital, a local healer and his Shuckle companions are on task to set him right!', 23, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 14, 'Power Play!', 'A run-in with his longtime rival Gary leaves Ash in a bad mood. But when Team Rocket''s latest weapon starts terrorizing the local Pokémon Center, Ash might have to turn to him for help!', 23, '2000-11-02');
