INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 17, 'Imitation Confrontation', 'Ash and the gang are happy to see Duplica again...but not as happy as the Team Rocket trio, when they discover her newest Ditto''s tiny transformations!', 23, '2000-11-23');
