INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 19, 'Ariados, Amigos', 'On their way to Ecruteak City, our heroes must help a familiar Trainer and her Ariados defend a martial arts center from a rampaging Team Rocket!', 23, '2000-12-07');
