INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 23, 'Houndoom''s Special Delivery', 'When the smoke clears after their latest run-in with Team Rocket, our heroes quickly realize that Togepi is missing! As they begin the search, Togepi has started making friends in another part of the forest.', 23, '2001-01-11');
