INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 42, 'Current Events', 'After becoming accidentally locked inside an electrical generator, Ash and Chikorita will have to avoid the aggressive security Pokémon and Team Rocket to make it out safely!', 23, '2001-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 43, 'Turning Over a New Bayleef', 'Bayleef is still getting used to its newly evolved form, and when Ash becomes impatient, it gets upset and runs away. Can our hero find his friend again and make amends?', 23, '2001-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 44, 'Doin'' What Comes Natu-rally', 'A young Natu fortune-teller learning his craft is lacking confidence in front of an audience. Can Ash help encourage the young artist''s talent?', 23, '2001-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 45, 'The Big Balloon Blow-Up', 'Our heroes take part in a high-speed race in a hot air balloon, but the stakes are raised when Team Rocket enters as well, causing chaos in the clouds!', 23, '2001-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 46, 'The Screen Actor''s Guilt', 'When a hooded man leaves a Smoochum with our heroes, it unravels a tale that will take them all the way to the bright lights of the silver screen!', 23, '2001-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 47, 'Right On, Rhydon!', 'Ash and his friends are approached by a civil engineer with a problem: she has a team of Ground-type Pokémon working to build a tunnel, but they''re terrified of the water that keeps leaking in! Can our heroes help?', 23, '2001-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 48, 'The Kecleon Caper', 'Aboard a luxury blimp, Team Rocket are trying to pinch a few valuables from wealthy travelers-but some courageous Kecleon are on hand to get the better of them!', 23, '2001-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 49, 'The Joy of Water Pokémon', 'Misty finally meets one of her idols, a Nurse Joy who specializes in Water types! But the reality doesn''t live up to the dream when Nurse Joy reveals that she doesn''t share Misty''s love for aquatic Pokémon after all...', 23, '2001-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 50, 'Got Miltank?', 'Ash and his friends have one last obstacle before Olivine City: a scorching desert! And when Cyndaquil goes missing, they have more than the heat to deal with!', 23, '2001-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 51, 'Fight for the Light!', 'Ash''s next Gym battle is under way, but it''s soon called off by Jasmine, the real Olivine Gym Leader, who claims that Ash has been battling an impostor! Will Ash now get the challenge he''s been searching for?', 23, '2001-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 4), 52, 'Machoke, Machoke Man!', 'After receiving the medicine in Cianwood City, our heroes soon discover the Gym Leader training hard with his Machoke. It''s only a matter of time before Ash decides to go toe to toe with Chuck''s Fighting-type Pokémon!', 23, '2001-08-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 5, 'Master Quest', 'With the Olivine City Gym temporarily out of commission, our heroes are off to the Whirl Cup Competition—and Misty wants in on the action! Resuming their journey, they find that Jessie, James, and Meowth aren’t the only members of Team Rocket they need to worry about, though that dastardly trio still has a few tricks up their collective sleeve. After a heated battle with the final Gym Leader, Ash moves on to the Silver Conference, but does he have the mettle to take on his old rival, Gary?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 1, 'Around the Whirlpool', 'In a scuffle with Team Rocket, Ash and friends are thrown from the ship bearing them to the Whirl Islands! Can they escape the powerful whirlpools that threaten to drag them down?', 23, '2001-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 2, 'Fly Me to the Moon', 'The Pidgey on a protected island don''t have to worry about being attacked, so most have lost interest in flying. But one of them still dreams of soaring beyond the stars! Can Ash and friends help?', 23, '2001-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 3, 'Takin'' It on the Chinchou', 'Our heroes pass a small mountain village just in time for the annual Chinchou migration. The village always sends Trainers to protect the Chinchou on their journey-but will they be enough to stop Team Rocket?', 23, '2001-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 4, 'A Corsola Caper!', 'When a family''s home is threatened by the Corsola who live nearby, it''s Ash and friends to the rescue...and maybe Misty can finally catch that Corsola she''s been after!', 23, '2001-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 5, 'Mantine Overboard!', 'After our heroes miss a ferry, they meet a diver who offers to take them to the next island...but they''re soon distracted by tales of treasure aboard a sunken ship!', 23, '2001-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 6, 'Octillery the Outcast', 'When they''re not competing in the Whirl Cup, Ash and Misty try to help a young Trainer whose Octillery has been rejected by its Remoraid friends after evolving.', 23, '2001-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 7, 'Dueling Heroes', 'After winning their preliminary rounds, Ash and Misty face formidable opponents in the Whirl Cup. Meanwhile, the Team Rocket trio have their eyes on stealing the tournament''s prize!', 23, '2001-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 8, 'The Perfect Match!', 'It''s the second round of the Whirl Cup, and Ash and Misty have been paired up against each other! Who will come out on top? And will Team Rocket''s plan to distract the police be successful?', 23, '2001-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 9, 'Plant It Now... Diglett Later', 'Our heroes are asked to help protect a village from marauders who threaten to make off with the Diglett who live there-and thanks to a delicious dinner, Team Rocket offers to help, too!', 23, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 10, 'Hi Ho Silver... Away!', 'Our heroes meet a jewelry maker who tells them the legend of the fourth Whirl Island...and who soon finds himself embroiled in a Team Rocket plot!', 23, '2001-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 11, 'The Mystery Is History', 'While two sets of Team Rocket villains set out to capture the Legendary Pokémon Lugia, Ash runs into his old friend Richie and his partner, a Pikachu named Sparky!', 23, '2001-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 12, 'A Parent Trapped!', 'The little Lugia named Silver has fallen into the hands of Butch and Cassidy of Team Rocket, and with Richie''s help, Ash must win the adult Lugia''s trust before it gets caught in the same trap!', 23, '2001-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 13, 'A Promise Is a Promise', 'While trying to rescue the two Lugia from Team Rocket, Ash and friends have been taken prisoner! Now, they must figure out a way to escape...and to free the captured Pokémon as well!', 23, '2001-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 14, 'Throwing in the Noctowl', 'Ash and friends are on a plane back to Olivine City when they get caught in a terrible storm that also sweeps up Team Rocket''s balloon! They''ll have to work together to land safely...but can they manage it?', 23, '2001-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 15, 'Nerves of Steelix!', 'After several interruptions, including yet another Team Rocket scheme, Ash''s battle against Jasmine at the Olivine Gym is finally getting under way!', 23, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 16, 'Bulbasaur... the Ambassador!', 'When the Pokémon at Professor Oak''s lab in Kanto have a hard time getting along, the professor asks Ash to send his Bulbasaur to the lab so it can help keep the peace.', 23, '2001-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 17, 'Espeon, Not Included', 'In Ecruteak City, our heroes meet up with their friend Sakura and her newly evolved Espeon. Sakura and her sisters are preparing for a dance competition, but Team Rocket is lurking in the wings, hoping to steal their Pokémon...', 23, '2001-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 18, 'For Ho-Oh the Bells Toll!', 'When our heroes investigate a sudden pealing of bells, they discover that the Crystal Bells, which are said to ring only when the Legendary Pokémon Ho-Oh returns, are missing! The researcher Eusine seems to know something...', 23, '2001-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 19, 'Extreme Pokémon!', 'When Ash runs into his old rival Gary preparing to enter his Arcanine in a race, he decides to compete as well! But first, he''ll have to chase Team Rocket away from the Pokémon Day Care.', 23, '2001-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 20, 'An EGG-sighting Adventure!', 'When the Pokémon Egg given to Ash goes missing, our heroes call on the help of a hapless Officer Jenny. It isn''t long before they realize that if they want the Egg back, they''ll have to find it themselves!', 23, '2001-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 21, 'Hatching a Plan', 'The moment has finally come: a Phanpy has hatched from Ash''s Pokémon Egg! The little Pokémon is full of energy and soon charging off...with our heroes and Team Rocket in tow!', 23, '2001-12-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 22, 'Dues and Don''ts', 'Jessie, James, and Meowth take time to lick their wounds and dream of stealing Pikachu for the glory of Team Rocket. After a chance meeting with a Team Rocket scout, it seems these dreams are blasting off before their eyes!', 23, '2002-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 23, 'Just Waiting On a Friend', 'When thick fog interrupts our heroes'' journey, a girl and her Ninetales invite them to rest at a nearby mansion...where Brock and their host fall into a romance that could turn out to be ghostly!', 23, '2002-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 24, 'A Tyrogue Full of Trouble', 'Near Mt. Mortar, our heroes run into a Trainer who is trying to curb a Tyrogue''s wild ways. But when Team Rocket gets involved, will they be able to save the troublesome Tyrogue from the villains'' clutches?', 23, '2002-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 25, 'Xatu the Future', 'Our heroes meet a young girl watching over a group of Xatu, whose psychic powers let them predict the future of a local village. When the villagers begin doubting their warnings, can the Xatu prove the truth of their visions?', 23, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 26, 'Talkin'' ''Bout an Evolution (1)', 'Reaching the Lake of Rage, Pikachu and Togepi begin to feel sick, and our heroes are attacked by an enraged red Gyarados. When Team Rocket appears on the scene, things look a lot more dangerous for Ash and friends...', 23, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 27, 'Rage of Innocence (2)', 'Things look bad for our heroes, who have been captured by Team Rocket at the Lake of Rage. With the fate of the world''s Pokémon at stake, can Ash rise to the occasion and save the day?', 23, '2002-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 28, 'As Cold as Pryce', 'Finally reaching Mahogany Town, Ash is warming up for his next Gym battle. But after getting the cold shoulder from Gym Leader Pryce, can our hero convince his frosty opponent to give him a chance?', 23, '2002-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 29, 'Nice Pryce, Baby!', 'Pryce and Ash are about to clash in a cold contest in the Mahogany Town Gym. Will Ash be able to show what he and his Pokémon are made of and earn his seventh Johto region Gym badge?', 23, '2002-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 30, 'Whichever Way the Wind Blows', 'Our heroes encounter battling groups of Bellossom and Vileplume, who have only recently evolved. As each group fights with increasing number and intensity, can our heroes put an end to the quarrelling?', 23, '2002-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 31, 'Some Like It Hot', 'The heat is rising in our heroes'' journey when Misty and her Water-type Pokémon go head to head with a willful Fire-type Trainer!', 23, '2002-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 32, 'Hocus Pokémon', 'Ash and the gang bump into a Pokémon magician, and soon they''re on the hunt to find components for her greatest spell yet!', 23, '2002-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 33, 'As Clear as Crystal', 'After yet another close encounter with Team Rocket, Pikachu is left exhausted and weak. Thankfully, a passerby takes our heroes to a nearby lake that helps recharge Electric types...but also hides a great secret!', 23, '2002-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 34, 'Same Old Song and Dance', 'Our heroes take time out to enjoy the entertainment of a young Trainer and her Igglybuff variety act. But it''s not long before Team Rocket arrives and tries to steal the show!', 23, '2002-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 35, 'Enlighten Up!', 'A chance trip to a Slowpoke temple gives our heroes an opportunity to seek enlightenment...and gives Team Rocket the chance to lighten some pockets!', 23, '2002-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 36, 'Will the Real Oak Please Stand Up?', 'A lavish celebrity event inspires Jessie and James to pretend to be the VIPs and fill their rumbling tummies. But it''s not long before their disguises are put to the test by the real guest of honor: Professor Oak!', 23, '2002-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 37, 'Wish Upon a Star Shape', 'When our heroes spot an object falling from the night sky, they rush to investigate. Soon, they find themselves joining forces with a Pokémon mystery club to uncover the secrets shared by the fallen Cleffa and the stars above!', 23, '2002-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 38, 'Outrageous Fortunes', 'Ash and Misty get into an argument over who can take on a powerful Trainer and his Poliwrath. When he accepts both challenges, the tough battles that follow give Misty some ideas for her own Poliwhirl!', 23, '2002-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 39, 'One Trick Phony!', 'Hearing of a nearby amusement park for battling, Ash is eager to test his skills. But the Team Rocket trio have recently joined the park, and they have a few ideas in store to test this Trainer''s mettle!', 23, '2002-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 40, 'I Politoed Ya So!', 'It''s a case of mistaken identity for Misty''s Politoed when it gets roped into replacing the leader of a Pokémon Cheer team...but where has the other Politoed gone?', 23, '2002-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 41, 'The Ice Cave!', 'Ash and friends enter an ice cave as it''s a shortcut to Blackthorn City. After a watery run-in with Team Rocket, Brock catches a cold and the gang finds a Pokémon Center in the cave. While a Jynx working there is taking care of Brock, Nurse Joy tells Ash and Misty that the cave is cold because of a big building working there as a refrigerator. Team Rocket finds the building and they cause trouble by reversing the structure, heating the cave and cooling the jungle outside, and make their attempt to steal the Ice-type Pokémon as well.', 23, '2002-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 42, 'Beauty Is Skin Deep', 'On the outskirts of Blackthorn City, Ash meets Gym Leader Clair, who is busy training her Dratini for a ceremony. But Team Rocket has other plans for the Dragon-type Pokémon, and Ash and Clair must work together to stop them!', 23, '2002-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 43, 'Fangs for Nothin''', 'Facing off against Blackthorn Gym Leader Clair, Ash is finding it difficult to overcome the power of her Dragon-type Pokémon. Things are harder still when Team Rocket shows up to steal Blackthorn City''s prized Dragon Fang relic!', 23, '2002-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 44, 'Great Bowls of Fire!', 'Team Rocket has taken the Blackthorn City Dragon Fang and holed up deep within the Dragon''s Den. Things look bad for the ancient relic, but help comes in the form of an old friend!', 23, '2002-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 45, 'Better Eight Than Never', 'Ash and Clair finally face off in a Gym battle that will push Ash''s skills as a Trainer to the limit! Can he win his final Johto Gym badge?', 23, '2002-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 46, 'Why? Wynaut!', 'A Team Rocket trick takes all of Ash''s hard-earned Johto Gym badges from him, but it''s not long before the troublesome trio get a taste of their own medicine. What tricksy Pokémon could have beaten them at their own game?', 23, '2002-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 47, 'Just Add Water', 'Discovering a nearby Pokémon synchronized swim team, Misty goes to check it out, and soon finds herself heading below the surface to take on the team''s Trainer in an exciting underwater battle!', 23, '2002-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 48, 'Lapras of Luxury', 'Ash barely makes it back to New Bark Town before he is off again, retrieving a Pokémon Egg for Professor Elm. However, things get interesting when he meets an old friend and Team Rocket shows up with more mischief!', 23, '2002-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 49, 'Hatch Me If You Can', 'Professor Elm''s Pokémon Egg hatches into a Larvitar! The Pokémon is unresponsive even after being checked over at the Pokémon Center, and Ash tries to cheer it up, but soon Team Rocket arrives to ruin all his hard work.', 23, '2002-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 50, 'Entei at Your Own Risk', 'On their way to Mt. Silver, our heroes relax at a hot spring and meet a young Trainer who''s tracking the Legendary Pokémon Entei. Trouble arises when Team Rocket follows them with a plan to steal Pikachu and Larvitar!', 23, '2002-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 51, 'A Crowning Achievement', 'Our heroes find a group of Slowpoke guarding a dried-up stream and hear the tale of a similar drought long ago, when one Slowpoke took the initiative to evolve into Slowking and save everyone. Can the same thing happen here?', 23, '2002-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 52, 'Here''s Lookin'' at You, Elekid', 'A cheeky Elekid starts to bother Larvitar, but soon both Pokémon are in the clutches of Team Rocket. Ash''s rival Casey wants to catch Elekid for herself, but can they mount a rescue before the villains get away?', 23, '2002-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 53, 'You''re a Star, Larvitar!', 'Our heroes have reached Mt. Silver, and Ash wastes no time starting his training for the Johto League Silver Conference. But all the Trainers around provide the perfect prey for Team Rocket, who arrive to swipe all the rare Pokémon!', 23, '2002-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 54, 'Address Unown!', 'With Mt. Silver a few yards away, Ash and co. soon spot an Unown, which quickly becomes friends with Larvitar. After which, it was attacked by Team Rocket and soon Ash and friends are swept into another dimension. Where are they now and where is Larvitar? And how did Pikachu and Togepi become giants?', 23, '2002-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 55, 'Mother of All Battles', 'After finally arriving at Mt. Silver, Ash and co. find the Preserve where Larvitar was born. There they encounter Larvitar''s mother, the same Tyranitar that was in Larvitar''s visions. The reunion is not a happy one however, even after they get reunited. The three men from Larvitar''s visions were also the ones responsible for stealing its Egg and they managed to capture the Tyranitar. Can they get mother and child reunited with the help of Ranger Mason?', 23, '2002-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 56, 'Pop Goes the Sneasel', 'Our heroes are called into action to save the Johto League Silver Conference''s opening ceremony from being stopped by a territorial Sneasel!', 23, '2002-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 57, 'A Claim to Flame!', 'The Johto League Silver Conference has begun, and Ash and his rivals are getting serious about what the future has in store!', 23, '2002-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 58, 'Love, Pokémon Style', 'As the Johto League Silver Conference heats up, Ash will have to rely on some old friends to fight off the affections of his next opponent!', 23, '2002-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 59, 'Tie One On!', 'The battle between Ash and Macy is over and Ash wins, but the next battle will determine if he will or will not go to the victory tournament. He faces off against Jackson, a trainer from Twinleaf Town who has a Meganium like Casey. Will Ash be able to win this final battle of the elimination block?', 23, '2002-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 60, 'The Ties That Bind', 'It''s Ash versus his oldest rival, Gary, in the Johto League Silver Conference, and both Trainers are ready to give it all they''ve got. But who will come out on top?', 23, '2002-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 61, 'Can''t Beat the Heat!', 'The ultimate battle continues as Ash and Gary face off. Ash will have to come up with a new plan to beat Gary''s Blastoise. Can he do it with the Pokémon he''s got, and if Ash beats Gary, who will be his next opponent?', 23, '2002-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 62, 'Playing with Fire!', 'After defeating Gary in the last round, Ash has to take on his new friend Harrison in the Johto League Silver Conference. Will our hero be able to stop the challenger from the Hoenn region?', 23, '2002-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 63, 'Johto Photo Finish', 'The scorching battle between Ash and Harrison rages on, with Charizard taking on Blaziken, a Pokémon from the Hoenn region!', 23, '2002-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 64, 'Gotta Catch Ya Later!', 'With his Johto League adventure behind him, Ash has decided to head back to Pallet Town. But it''s all too soon before he has to say goodbye to Brock and Misty, and head out alone for a new adventure!', 23, '2002-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 5), 65, 'Hoenn Alone!', 'The Hoenn region is on Ash''s mind, and he''s preparing to board a ship bound there when Team Rocket strikes! With Pikachu missing and time running out before the boat leaves, can Ash get his adventure back on track?', 22, '2002-11-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 6, 'Advanced', 'Polishing off the Silver Conference, Ash heads toward his next challenge—the far-off Hoenn region! While he must say goodbye to old friends, he makes the acquaintance of May, a Trainer just starting out on her Pokémon journey. Along with her little brother Max and the ever-reliable Brock, this pack of Pokémon Trainers begin pursuing their dreams—with Ash racking up three Gym Badges, while May changes tack to follow the Contest path of a Pokémon Coordinator.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 1, 'Get the Show on the Road!', 'Pikachu is suffering from a serious electrical overload! Can Ash and Professor Birch find a solution before it''s too late?', 23, '2002-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 2, 'A Ruin with a View', 'A power failure at the Pokémon Center leads Ash and his new friend May to an astonishing discovery!', 23, '2002-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 3, 'There''s No Place Like Hoenn', 'Ash is ready for his first Gym battle in the Hoenn region--and the Gym Leader he must face is none other than May''s father!', 23, '2002-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 4, 'You Never Can Taillow!', 'When Team Rocket turns a flock of Taillow against our heroes, an old friend comes to the rescue!', 23, '2002-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 5, 'In the Knicker of Time!', 'Ash and friends meet an eccentric Trainer who challenges May to her very first Pokémon battle!', 23, '2002-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 6, 'A Poached Ego!', 'Our heroes are on the trail of a Pokémon poacher, and Team Rocket is close behind!', 23, '2002-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 7, 'Tree''s a Crowd', 'When Ash gets lost in the woods, he meets a Treecko who''s determined to save its forest home.', 23, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 8, 'A Tail with a Twist', 'Ash''s Treecko takes on a wild Seviper, but things don''t go so well...', 23, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 9, 'Taming of the Shroomish', 'Stopping in Rinshin Town, our heroes investigate the mystery of a haunted mansion!', 23, '2003-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 10, 'You Said a Mouthful!', 'Ash can''t resist challenging a Trainer who claims to have the world''s most powerful Pokémon, but there''s something odd about this battle...', 23, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 11, 'A Bite to Remember', 'After meeting a group of Mightyena, Max befriends a Poochyena who hasn''t evolved yet and decides to train it himself!', 23, '2003-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 6), 12, 'The Lotad Lowdown', 'Our heroes meet three sisters who grow berries with the help of a nearby group of Lotad!', 23, '2003-02-13');
