INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 11, 'From Cradle to Save', 'On their way to the Battle Pike, our heroes come across a Pokémon ninja school, where they help the students rescue their Pokémon from Team Rocket''s clutches.', 23, '2005-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 12, 'Time Warp Heals All Wounds', 'At an abandoned train station, May meets a woman who lost the love of her life thanks to a sad twist of fate.', 23, '2005-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 13, 'Queen of the Serpentine', 'At the Battle Pike, Ash must further hone his on-the-spot strategy skills to defeat a soft-spoken, fierce Frontier Brain named Queen Lucy and win his fourth Frontier Symbol.', 23, '2006-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 14, 'Off the Unbeaten Path', 'After arriving on Potpourri Island, our heroes discover the Pokémon Orienteering competition just about to take place and decide to enter, vying for the coveted Pokémon Teamwork medal!', 23, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 15, 'Harley Rides Again', 'In the Wisteria Town Pokémon Contest, May discovers she is to compete against her old rival Harley.', 23, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 16, 'Odd Pokémon Out!', 'As our heroes continue toward May''s next Pokemon Contest, Ash''s Grovyle finds itself nursing a crush on Nurse Joy''s Meganium!', 23, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 17, 'Spontaneous Combusken!', 'After meeting a new Coordinator named Brianna who''s a fan of hers and an even bigger fan of Drew''s, May discovers she must battle her in order to win her third Pokémon Contest ribbon.', 23, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 18, 'Cutting the Ties that Bind!', 'After a frustrated Sceptile runs off into the forest, Ash and Pikachu go after it and run into a swarm of angry Beedrill--and the next Frontier Brain!', 23, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 19, 'Ka Boom with a View!', 'It''s time for Ash''s next Battle Frontier challenge: a battle in the impressive outdoor arena at the Battle Palace, against Frontier Brain Spenser!', 23, '2006-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 20, 'King and Queen for a Day!', 'On their way to Ash''s next Battle Frontier challenge, our heroes come across a couple of Pokémon TV stars who aren''t feeling well, so Brock''s Bonsly and James''s Mime Jr. act as stand-ins!', 23, '2006-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 21, 'Curbing the Crimson Tide!', 'After hearing stories about many Trainers and Pokémon being defeated and taunted by a mysterious talking Pokémon known as Red Lightning, our heroes decide to find out what''s really going on.', 23, '2006-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 22, 'What I Did for Love!', 'When Brock meets up with a lovely Pokémon breeder who used to be a Coordinator, she talks him into competing against May in the Gardenia Pokémon Contest!', 23, '2006-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 23, 'Three Jynx and a Baby!', 'On their way to the Battle Tower for Ash''s next challenge, our heroes come across a cute little Smoochum who is fiercely guarded by three Jynx, and Ash has to convince them he''s on their side!', 23, '2006-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 24, 'Talking a Good Game!', 'On their way to the Battle Tower, our heroes meet an amazing person who seems to be able to communicate with Pokémon by sensing their feelings...and more surprises await!', 23, '2006-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 25, 'Second Time''s the Charm!', 'After losing to Frontier Brain Anabel, Ash buckles down for some unusual special training--and Anabel joins him! Can he defeat her in the rematch?', 23, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 26, 'Pokémon Ranger! Deoxys'' Crisis!', 'After witnessing strange behavior from several kinds of Pokemon on their way to Pewter City, our heroes and Pokemon Ranger Solana encounter an electromagnetic disturbance, which leads them to the discovery of a troubled Deoxys!', 46, '2006-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 27, 'All That Glitters Is Not Golden!', 'On their way to Ash''s final Frontier Battle and Brock''s hometown of Pewter City, our heroes discover a wandering golden Sudowoodo and the estranged Trainer who caused its unusual coloring.', 23, '2006-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 28, 'New Plot, Odd Lot!', 'May is going after her fifth Contest Ribbon to qualify for the Grand Festival, but when her shady rival Harley teams up with Team Rocket, things don''t look good!', 23, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 29, 'Going for Choke!', 'After a shaky start in the Mulberry Pokémon Contest, May makes it through to the finals, where she goes up against "Jessebella"--Team Rocket''s Jessie in disguise!', 23, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 30, 'The Ole'' Berate and Switch!', 'After a squabble causes Jessie and James to part ways, they team up with fellow Team Rocket agents Butch and Cassidy for a Poké Ball-swiping scheme!', 23, '2006-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 31, 'Grating Spaces!', 'Upon arriving in Pewter City, our heroes learn that Brock''s old Gym is being remodeled by none other than Team Rocket in disguise, and Brock and Ash must battle them to put a stop to it!', 23, '2006-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 32, 'Battling the Enemy Within!', 'In the ancient ruins beneath the Battle Pyramid, Ash is mysteriously possessed by the spirit of an ancient and evil king, who challenges Frontier Brain Brandon to a battle for all of his Pokémon.', 23, '2006-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 33, 'Slaking Kong!', 'On their way to the Grand Festival, our heroes help a berry farmer reclaim his stolen crop.', 23, '2006-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 34, 'May, We Harley Drew''d Ya!', 'As the Grand Festival gets under way at the Indigo Plateau, May has her hands full trying to compete with the best Coordinators in the world, including Harley, Drew, and new friend Solidad!', 23, '2006-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 35, 'Thinning the Hoard!', 'The Grand Festival is going strong as May faces down one impressive competitor after another!', 23, '2006-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 36, 'Channeling the Battle Zone!', 'May faces Drew in the quarterfinals of the Grand Festival, and the two seem to be very evenly matched! Can May come out ahead?', 23, '2006-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 37, 'Aipom and Circumstance!', 'On their way to Ash''s rematch with Brandon at the Battle Pyramid in Fennel Valley, our heroes come across a village taking part in the annual ritual of choosing a king, and Ash''s Aipom becomes a most unwilling candidate!', 23, '2006-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 38, 'Strategy Tomorrow - Comedy Tonight!', 'Our heroes meet an aspiring comedian named Audrey and her showbiz sidekick and Pokémon partner, Chatot.', 23, '2006-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 39, 'Duels of the Jungle!', 'Our heroes find themselves embroiled in Pokémon politics as two Weavile face off for leadership of a group of Sneasel!', 23, '2006-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 40, 'Overjoyed!', 'When our heroes arrive at the Battle Pyramid for Ash''s battle with Brandon, they discover a Nurse Joy who''s a big fan of Ash and May!', 23, '2006-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 41, 'The Unbeatable Lightness of Seeing!', 'After their recent defeats in important matches at the Battle Pyramid and the Grand Festival, Ash and May are feeling a little down, until several old friends come together to support them.', 23, '2006-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 42, 'Pinch Healing!', 'When Nurse Joy becomes too ill to take care of the Pokémon Center, our heroes pitch in, coming to the aid of a Pokésitter and his charges after a bus accident.', 23, '2006-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 43, 'Gathering the Gang of Four!', 'Ash prepares for his final rematch with Brandon at the Battle Pyramid by rounding up the Pokémon he''s been with the longest, spending his time sharing old memories with them and training intensely.', 23, '2006-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 44, 'Pace - The Final Frontier!', 'Ash has lost to Brandon in two previous battles, and now his Charizard has been defeated! Can he battle back to claim the final Frontier Symbol?', 23, '2006-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 45, 'Once More with Reeling!', 'Ash has beaten the Battle Frontier, but his competitive spirit won''t let him rest for long, and he and May both sign up for an unofficial Pokémon Contest in Terracotta Town!', 23, '2006-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 9), 46, 'Home Is Where the Start Is!', 'After one last contest battle between Ash and May, our heroes go their separate ways, and Ash discovers his next adventure!', 23, '2006-09-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 10, 'Diamond and Pearl', 'If Gary Oak is headed for the Sinnoh region, then Ash Ketchum won’t be far behind! Ready to take on the Sinnoh League, Ash brings along Pikachu and meets up with Brock in Sinnoh, where the pair of Trainers are soon joined by a third—Dawn, a novice Pokémon Coordinator determined to follow in the footsteps of her mother. Both Ash and Dawn struggle with their respective paths, but it’s easy for them to make new friends, gaining new Pokémon like Turtwig and Piplup.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 1, 'Following A Maiden''s Voyage!', 'It''s always exciting when new Pokémon Trainers receives their first Pokémon, but for a girl named Dawn, things will be far more exciting than she''d ever imagined! Here in the Sinnoh region, Trainers receive their Pokémon from Professor Rowan, whose lab is near Sandgem Town—but soon after Dawn leaves her home in Twinleaf Town and heads for the lab, she''s hopelessly lost. Fortunately, she runs into Professor Rowan on the street and follows him to the lab. But while the Professor was out, his assistants accidentally let two of the starter Pokémon, Chimchar and Pilplup, break out of the lab.', 23, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 2, 'Two Degrees of Separation!', 'Dawn and Piplup begin their journey, and enter their first attempts to catch some Pokémon. Although, during those attempts, Dawn and Piplup run into Ash''s Pikachu, and Team Rocket. Meanwhile, Ash continues looking for Pikachu and meets back up with Brock, and together they go catch up with Dawn.', 23, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 3, 'When Pokémon Worlds Collide!', 'While searching for Pikachu, Ash and Brock run into a new rival named Paul, who challenges Ash to a battle, but Ash can''t compete without Pikachu; Dawn and Piplup meet Ash and Brock, and together they try to rescue Pikachu from Team Rocket.', 23, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 4, 'Dawn of a New Era!', '"The journey of a thousand miles begins with a single step."
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 5, 'Gettin'' Twiggy with It!', 'While heading to the first stop on their journey, Pikachu is captured by Team Rocket and Ash and co. are not far behind. After their balloon popped Team Rocket found Pikachu protected by a Turtwig. When Ash and co. find Pikachu with Turtwig its caretaker, a kindly old lady by the name of Clara, invited them over for lunch. Turns out she''s a Pokémon Caretaker and Turtwig (like Bulbasaur before it) is her bodyguard but it really likes Ash. Will Ash accept Turtwig?', 23, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 6, 'Different Strokes for Different Blokes!', 'While en route to Jubilife City, Ash and co. encounter Paul again. He declares a Battle with Ash to see if Ash has gotten stronger since their last battle. Will this battle end differently for Ash, or will Paul have the advantage the second time around?', 23, '2006-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 7, 'Like it or Lup It!', 'The roar of the crowd and the excitement in the air as Dawn prepares to start off her contest debut. Just kidding: it''s just Dawn practicing (and failing) her appeals training. Elsewhere, Team Rocket stole some berries that belonged to a Golduck, Wooper, Quagsire and Poliwag. Soon after this group finds Piplup and it agrees to solve the problem. Can this plucky Pokémon settle this dispute diplomatically?', 23, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 8, 'Gymbaliar!', 'Still en route to Jubilife City, Ash and co. meet a girl named Minnie who tells the gang about a Gym called the Powerzone Gym. As usual Ash wants in on the Gym Battles so he, Dawn, Brock and Minnie check it out. What kind of Gym is this, and is it authorized by the Sinnoh League?', 23, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 9, 'Setting the World on its Buneary!', 'Early one morning, Ash is awoken by Dawn who is having a "Bad Hair Morning". And anyone who dares see her with bedhead will never see another sunrise again! After a Bubble Beam attack Dawn comes out with her hair silky smooth. Later Dawn spots a Buneary, a Pokémon she has tried so hard to capture, but this one seems to be infatuated by Ash''s Pikachu. So she freezes everyone but Pikachu with an Ice Beam attack, but Pikachu did not like this and told her off, which broke her little heart. Can Pikachu be able to mend it, and will this Buneary be a part of Dawn''s small Pokémon family?', 23, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 10, 'Not on MY Watch Ya Don''t!', 'Ash and co. finally arrive at Jubilife City, the first stop in Dawn''s quest to be a great coordinator. It is there that she learns of a new fad. It''s hip, it''s hot, it''s happenin'' it''s the Pokétch and, like all girls, Dawn has to have one. She gets one from three clowns only to find out from a smart little boy named Landis that it is a fake. Will she be able to get a real Pokétch, or will she be a trend loser?', 23, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 11, 'Mounting a Coordinator Assault!', 'The first of anything can be quite stressful. Dawn has made it to the Jubilife Contest hoping to win her very first ribbon. She meets a girl by the name of Zoey, who has a Glameow just like her mom. She also meet the fabulous Jessilina (Who unbeknownst to her is really Jessie). All eyes focus on newcomer Dawn. Will she have what it takes to make it to the top?', 23, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 12, 'Arrival of a Rival!', 'As the Jubilife contest continues, Ash, Dawn, Zoey and Jessilina (aka Jessie) pass with flying colors. But the tension mounds and pressure is really put on Dawn. Will she manage to win her very first contest, or will Zoey manage to win it all?', 23, '2006-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 13, 'A Staravia Is Born!', 'Ash and the gang find a Pokémon bird-watcher named Rosebay who wonders why the bird Pokémon have been recently disappearing. They decide to investigate at a nearby canyon where they spot Team Rocket capturing multiple bird Pokémon, including Ash''s Starly. The gang works together to try and free the bird Pokémon, but will they be able to successfully save Starly from Team Rocket?', 23, '2006-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 14, 'Leave it to Brocko!', 'When Ash and his friends discover an injured and displaced Nuzleaf in a forest. Seeing that Nuzleaf is lost, they decided to return it to its home. Unfortunately, Team Rocket captures Nuzleaf and takes Brock along with he tries to stop them. However, Brock''s quick thinking and culinary skills thwart their plans and helps Nuzleaf get home safe to its friends.', 23, '2006-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 15, 'Shapes of Things to Come!', 'Ash, Dawn and Brock arrive at Oreburgh City, where Ash is stoked about getting his first Gym Badge. However, not only did Paul get there first but the Gym Leader isn''t there. Apparently Roark, the Gym Leader, went to the mines to dig for coal. When they run to meet him he said that he totally forgot his duties as a Gym Leader. When they go back, Roark decides to challenge Paul first. Will Paul be able to beat Roark?', 23, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 16, 'A Gruff Act to Follow!', 'After Paul dominated the Oreburgh Gym, Ash had to think about what Pokémon he could use. Naturally he chose Turtwig, Aipom and Pikachu to go up against Roark''s Rock-type Pokémon. Will this strategy work, or will history for Ash repeat itself?', 23, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 17, 'Wild in the Streets!', 'After Ash suffered a defeat last time, he doesn''t let it bother him as he trains with his Pokémon for his rematch with Roark. Meanwhile, Team Rocket resurrects an Aerodactyl that goes nuts and nearly destroys the city. Can Ash be able to face this ancient Pokémon again? And will Dawn be ready for her next contest?', 23, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 18, 'O''er the Rampardos We Watched!', 'Ash returns to Oreburgh Gym, ready to challenge Roark again. As the battle starts, Ash quickly surprises everyone when Pikachu manages to take down Onix. As the second battle begins, Ash pits Aipom against Geodude. After a long struggle, Ash manages to beat Geodude, and loses Pikachu and Aipom before the real test begins, defeating Roark''s newly evolved Rampardos.', 23, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 19, 'Twice Smitten, Once Shy!', 'Dawn catches a Pachirisu but quickly discovers the cute Pokémon may be too feisty to control. Seeing this, Dawn questions her competence as a trainer. Meanwhile, Team Rocket also wants Pachirisu as they try to lure it with food in order to capture it.', 23, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 20, 'Mutiny in the Bounty!', 'On the way to Floaroma Town, Ash and the others hear some screaming nearby. At a house, a Pokémon hunter named J has just captured a girl named Melodi and kidnapped her Gardevoir and she quickly flees the scene. Ash gives chase to her, and tries to battle her, only to have Pikachu frozen in stone and stolen just like Gardevoir. They decide to help Officer Jenny and try to help capture J, but eventually she also gets Meowth as well! Before she can take off, Ash, Jessie, and James sneak under her vehicle and follow her to her secret flying base. Now, the reluctant allies must work together to get back their Pokémon from J''s clutches.', 23, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 21, 'Ya See We Want an Evolution!', 'While they were walking tiredly, Team Rocket once again encounter the Magikarp salesman, not having forgotten how he tricked James into buy several Magikarp. James tries to take his money back until Magikarp salesman convinces Team Rocket to buy an Evolution Machine. Meanwhile, Ash and co. visit Oralie and Haley, two coordinators that claim to have the strongest Magikarp and Feebas ever. After both Ash and Dawn''s defeat by Oralie''s Magikarp, Team Rocket steals Magikarp, Feebas and Pikachu and tries to evolve them. Will they succeed?', 23, '2007-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 22, 'Borrowing on Bad Faith!', 'Aipom takes Ash''s hat and playfully runs away, but then finds itself in trouble. However, Aipom is saved by Jessie and then convinces Ash to let her use his Pokémon in an upcoming contest. Although, Ash worries that he may lose his Aipom to Team Rocket.', 23, '2007-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 23, 'Faced with Steelix Determination!', 'When Team Rocket was planning their next pitfall trap, their shovels suddenly got stuck in the ground. When they try to pull them out, a Steelix pops out of the ground with the shovels stuck in its head. It grows angry and begins to chase them. Meanwhile, Ash and his friends discover an injured Bidoof. After healing its injuries, they decide to help it go back to its village. However, Team Rocket and the rampaging Steelix come by, forcing them to run into Bidoof''s Village. Lucky for them, the Bidoof Village is surrounded by a huge rock wall, but Steelix will be able to break through. Now Ash and the others must find a way to stop Steelix before it destroys the Bidoof Village.', 23, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 24, 'Cooking Up a Sweet Story!', 'When a girl named Theresa asks Ash to let Pikachu stand in for her aunt Abigail''s lost Pikachu, Sugar, to help her win a baking competition, the ruse seems to work, until Abigail challenges Ash to a Pokémon battle against Pikachu. Will Ash be able to battle his own partner and best friend.', 23, '2007-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 25, 'Oh Do You Know the Poffin Plan!', 'Arriving in Floaroma Town, Dawn drags Ash and Brock to a cooking class to learn how to make a special Pokémon snack food called poffins. Meanwhile, Team Rocket hatches a scheme to get rich selling their own poffins, but a shy Roserade upends their plans.', 23, '2007-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 26, 'Getting the Pre-Contest Titters!', 'While practicing for the Floaroma Town Pokémon Contest, Dawn reunites with her childhood friend, Kenny, who plans to compete against her. Meanwhile, Jessie sends James and Meowth on a mission to steal a strong Pokémon for her contest appearance.', 23, '2007-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 27, 'Settling a Not-So-Old Score!', 'The day of the Floaroma Pokémon Contest has arrived as Dawn, her childhood friend Kenny, and a disguised Jessie are among the Coordinators vying for the prestigious Floaroma ribbon.', 23, '2007-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 28, 'Drifloon on the Wind!', 'Ash, Dawn and Brock stop at a Pokémon Center run by a Nurse Joy with two young daughters. When Nurse Joy''s younger daughter takes off on a Drifloon to find her sister, Ash sets out to save them before a brewing storm causes tragedy.', 23, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 29, 'The Champ Twins!', 'Ash and Dawn suffer defeat in a tag battle against two gifted Pokémon trainers dubbed "The Champ Twins". However, Team Rocket steals the twins'' Croconaw and Quilava before they can get a rematch.', 23, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 30, 'Some Enchanted Sweetening!', 'On their way through Eterna Forest, Ash & Co. meet up with a trainer called Cheryl. She is looking for Sweet Honey so she can get some really rare Pokémon. Having found some Burmy, she learned that it has many different evolved forms. Having obtained three of them, Cheryl is trying to evolve her final Burmy to see what it will become. Team Rocket however have their eyes set on this Worm Family. Will they be stopped?', 23, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 31, 'The Grass-Type is Always Greener!', 'After Burmy evolved into Mothim, Ash and co continue through the Eterna Forest where, along the way, they meet Gardenia, an overenthusiastic fan of Grass-type Pokémon. Ash declares a battle with her and she accepts. Will Ash win against this Grass Geek, and could she be the only one?', 23, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 32, 'An Angry Combeenation!', 'The quest for the Enchanted Honey concludes when the gang arrives at Amber Castle, which is the home to a hive of Combee and their leader, Queen Vespiquen.', 23, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 33, 'All Dressed Up with Somewhere to Go!', 'Ash, Dawn, Brock and Team Rocket enter one of the most popular contest events in the Sinnoh region, the annual Pokémon Dress-Up Contest, a costume competition. The winner of the Dress-Up contest gets a Pokémon Egg as the grand prize.', 23, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 34, 'Buizel Your Way Out of This!', 'After hearing about a powerful Buizel thwarting trainers'' attempts at capture, Ash, Dawn and Brock decides to do a round of fishing in hopes of finding it. During their fishing round, Ash and friends are joined by Dawn''s contest rival, Zoey.', 23, '2007-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 35, 'An Elite Meet and Greet!', 'As our Heroes continue to Eterna City and Ash''s second Sinnoh Gym battle challenge, they meet up with Lucian, a member of the Sinnoh Elite 4, who helps Dawn develop her training relationship with her newly caught Buizel.', 23, '2007-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 36, 'A Secret Sphere of Influence!', 'Ash and co. finally arrive in Eterna City, where Ash hopes to earn his second badge. However, they are delayed by a trip to the museum where Ash meets not only the Eterna city Officer Jenny, but is reacquainted with the Viridian City Jenny. They also run into Nando and Gardenia, who is Eterna''s Gym Leader. They learn that Team Rocket plans to steal the Adamant Orb. Can our heroes stop them, and who is really behind this theft?', 23, '2007-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 37, 'The Grass Menagerie!', 'The time has come again. Ash is now ready for his Gym Battle with Gardenia, and this time, it''s official. Knowing what to expect from her after their last battle, will Ash be able to prune Gardenia''s team, or will his team be pushing up daisies?', 23, '2007-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 38, 'One Big Happiny Family!', 'Enroute from Eterna City, Brock''s egg starts to glow. Finding a nearby Nurse Joy and await the egg to hatch. Happiny hatches from the egg and immediately takes a shine to Brock. Lacking a White Rock however, Brock goes out to find one. However, Team Rocket have their eyes set on Brock''s new Pink Pokémon. Can the new Pokémon be protected?', 23, '2007-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 39, 'Steamboat Willies!', 'On their way to Hearthome City for Dawn''s next Pokémon Contest and Ash''s next Gym battle, they let their Pokémon play in a steamboat while they go shopping. However, the steamboat ends up running away with only Ash, Brock and Dawn''s Pokémon still on board, which presents everyone with a real crisis.', 23, '2007-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 40, 'Top-Down Training!', 'While Ash and co. are at a Pokémon Center and watch a battle between Cynthia the Sinnoh League Champion and Lucian, member of the Sinnoh''s Elite Four, they hear that Cynthia is nearby. When they finally meet her, Paul appears and challenges her to a six-on-six full battle. Cynthia agrees and the battle starts. Will Paul be able to win against Cynthia and her strongest Pokémon, Garchomp?', 23, '2007-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 41, 'A Stand-Up Sit-Down!', 'The gang comes to the aid of Dawn''s friend and rival, Zoey, who injured her leg while training. After hearing that the next contest in Hearthome city is gonna be a double performance, where the coordinators must perform with two Pokémon at the same time, Zoey helps Dawn train for the Pokémon Contest.', 23, '2007-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 42, 'The Electrike Company!', 'When the gang comes across a breeder having difficulty training a struggling but gifted Electrike, Brock decides to teach him how to handle electric-type Pokémon. Meanwhile, Jessie wants to steal Electrike, but faces unusual resistance from James and Meowth.', 23, '2007-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 43, 'Malice in Wonderland!', 'What appears to be a Pokémon Center turns out to be a mysterious gate to a world where the gang''s dreams all come true. However, they begin to realize that a Pokémon has them in a hypnotic trance.', 23, '2007-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 44, 'Mass Hip-po-sis!', 'Ash, Dawn and Brock discover a lost Hippopotas and set off to return it to its herd. However, they have to fend off Team Rocket''s attacks and the Hippopotas'' sleep-inducing ability to succeed in their quest.', 23, '2007-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 45, 'Ill-Will Hunting!', 'As our Heroes continue towards Hearthome City, Ash reunites with his old friend and rival, Gary Oak. However, they have to work together in order to save a rare Shieldon from the evil clutches of Pokémon Hunter J.', 23, '2007-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 46, 'A Maze-ing Race!', 'Continuing on their way to Hearthome City, Ash and his friends take a side trip to get an upgrade for Dawn''s Poketch. Unfortunately, they ended up getting trapped in a dangerous maze, courtesy of Team Rocket.', 23, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 47, 'Sandshrew''s Locker!', 'A girl named Mira offers to use her Abra to teleport Ash, Dawn and Brock to Hearthome City, but it takes them to a lake instead. Mira explains that she needs their help to retrieve her submerged Sandshrew, which an ornery Gyarados fiercely guards.', 23, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 48, 'Satoshi and Hikari! Head for a New Adventure!!', 'A clip show unaired outside of Japan summarizing the important events of the first 47 Diamond and Pearl episodes, including Satoshi''s (Ash''s) victories over Hyouta (Roark) and Natane (Gardenia) and the introductions of new rivals Shinji (Paul) and Nozomi (Zoey).
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 49, 'Dawn''s Early Night!', 'Arriving in Hearthome City, Ash and Brock enter a tag battle, after the latter finds out that the Gym Leader isn''t there to challenge Trainers to a battle. Meanwhile, Dawn competes against Nando, Zoey and Jessilina in the Hearthome City Pokémon Contest. However, Dawn finds herself in a discouraging situation.', 23, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 50, 'Tag! We''re It...!', 'Through a suggestion from Zoey in order to help her recover from her early exist at the Hearthome contest, Dawn participate in the Hearthome City Tag Battle Competition with Ash and Brock. During opening day of the Hearthome City Tag Battle Competition, Ash, Dawn and Brock learn who they will partner with. However, Ash discovers his teammate is his rival Paul.', 23, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 51, 'Glory Blaze!', 'Paul''s abuse on Chimchar becomes dangerous to its health and causes it to collapse from exhausted during training. However, despite everyone''s protest and waring to let Chimchar rest, Pauls enters it into the second day of the Hearthome City Tag Battle anyway. The harrowing battle leads to a fateful decision for Chimchar.', 23, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 10), 52, 'Smells Like Team Spirit!', 'After Paul abandoned Chimchar, Ash offers it a new chance, join his team. Chimchar accepts Ash''s invitation to join his team. Ash battles alongside Paul in the tournament semifinals against Brock and Holly. They make it to the finals, where they are matched up against Dawn and Conway.', 23, '2007-10-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 11, 'Diamond and Pearl: Battle Dimension', 'It’s looking good for Ash as he works on his next three Gym Badges, but not so good for Dawn, coming off a pair of Contest defeats. Both will do what they can to become better Trainers, from entering the Wallace Cup competition to attending Professor Rowan’s Pokémon Summer Academy. Hopefully, the new tactics they pick up will give them the tools they need to succeed against the latest plot by Pokémon Hunter J—as well as the emerging threat of Team Galactic!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 1, 'Tears for Fears!', 'After a practice battle between Ash''s Chimchar and Dawn''s Piplup, Chimchar begins to cry because Ash was nice to it even though it lost, and Paul wasn''t. Things get worse when a trio of Zangoose attack and Chimchar has to face its fear and eventually defeats them and overcomes its fear of Zangoose. Chimchar also receives some unexpected advice from Meowth about the future.', 23, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 2, 'Once There Were Greenfields', 'Gardenia reappears in a town, organizing a special exhibition battle for the town''s children. She teams herself with James of Team Rocket in a match against Ash and Dawn. She proposes that James should leave his Cacnea with her to train when he is unable to use it to its full potential. He eventually decides to accept the offer.', 23, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 3, 'Throwing the Track Switch', 'Buizel is more interested in Ash''s gym training, and Aipom is more interested in Dawn''s contest training. Thus, Zoey suggests that Ash and Dawn do a trade.', 23, '2007-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 4, 'The Keystone Pops!', 'After Ash''s Buizel destroys the Hallowed Tower, a Spiritomb is unleashed and attacks Ash, Dawn, Brock and a nearby village. Then Jessie tells it that Ash is a descendant of the Aura Guardian that coincidentally has a Pikachu, that sealed it away. So Ash sets out to stop the Spiritomb and with Pikachu''s help, they seal it away in the Hallowed Tower.', 23, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 5, 'Bibarel Gnaws Best!', 'Ash''s group encounters a Pokémon Breeder working on the construction of a stone bridge. The woman is arguing with the bridge''s designer because of their Pokémon assistant Bibarel''s refusal to work. After the stone cutter returns, Bibarel begins to construct the bridge, with help from the gang.', 23, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 6, 'Nosing ''Round the Mountain!', 'Ash battles Alan, a trainer that wants his Nosepass to evolve into a Probopass, but it can only evolve if it levels up in Mt. Coronet. When it does, Team Rocket brainwashes it and now Ash & Co. have to get it back.', 23, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 7, 'Luxray Vision!', 'Ash encounter a young Officer Jenny named Marble and her Luxray. Luxray is unable to use its electric moves, so Ash & Co. set out to help it.', 23, '2007-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 8, 'Journey to the Unown!', 'In Solaceon Town, Ash''s group meets up with Dawn''s old friend and rival Kenny and his new Pokémon, Breloom. Kenny tells them he is going to the Solaceon Ruins, a place of worship for the legendary Dialga and Palkia, so they tag along, only to get more than they bargained for when the Unown that live in the ruins become furious along with the appearance of the sinister Team Galactic. Among the chaos, Aipom evolves into Ambipom', 23, '2007-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 9, 'Team Shocker!', 'Dawn competes against Kenny in the Solaceon Town Contest, looking for redemption after her crushing loss in Hearthome City. Jessie of course enters. Dawn loses once again and Kenny and Jessie face-off in the finals. Jessie defeats Kenny and wins her first ribbon. Zoey tells Dawn that the overuse of Swift caused Ambipom to be no longer seen and the point of an Appeal is to show off the Pokémon.', 23, '2007-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 10, 'Tanks for the Memories!', 'On their way to Veilstone City, Ash and his friends stop off at the Mountain Hut Maid Café for a nice drink of Miltank''s Milk. However, when they arrive, they learn of the troubles the Café is having, being under-staffed. Ash and his friends offer their services and soon become Maids in the Café. Brock helps Autumn, the youngest of three sisters bond with her Miltank, Ilta. All the while Dawn is trying deal with her feelings of losing a contest for a second time.', 23, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 11, 'Hot Springing a Leak!', 'Ash and his friends stop at a Hot Spring managed by Dawn''s childhood friend, Leona. Both girls are happy to meet again, but when Dawn and her friends want to go to the hot springs, they find out that there isn''t any water. Because no water is coming from the spring, the group want to investigate, along with Leona and her Swinub.', 23, '2008-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 12, 'Riding the Winds of Change!', 'Ash and company visit a town where it is plagued with a group of Gligar led by a Gliscor. Ash and friends help Officer Jenny try to remove the flying Pokémon, while Ash''s rival Paul sets his eyes on capturing Gliscor. In the end, Paul captures the Gliscor on his team, and Ash captures one of the Gligar that keeps showing up.', 23, '2008-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 13, 'Sleight of Sand!', 'When our heroes'' Pokémon are having a fun time in a sandpit, a Hippowdon appears from within. However, the over-curious Pachirisu can''t help peeping into the Hippowdon''s mouth and accidentally falls into it. The situation gets worse when Hippowdon becomes the target of the Team Rocket duo Butch and Cassidy.', 23, '2008-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 14, 'Lost Leader Strategy!', 'In the forest just outside Veilstone City, the group witness a young female martial-artist and a Lucario in a fierce battle. The girl is revealed to be Maylene, the city''s Gym Leader, at which point Ash immediately asks for a Gym Battle. However, she recently lost to Ash''s rival Paul, and is depressed over her defeat. Further insight into the matter is revealed by Reggie, Paul''s older brother. Reggie also helps Ash''s Staravia learn Brave Bird.', 23, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 15, 'Crossing the Battle Line!', 'Dawn challenges the gym leader of Veilstone City, Maylene, in hopes of helping Maylene get over her defeat. Maylene defeats Dawn and she and her Lucario regain their confidence.', 23, '2008-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 16, 'A Triple Fighting Chance!', 'Maylene finally accepts Ash''s challenge. Ash uses Staravia, Chimchar, and Buizel against Machoke, Meditite, and Lucario. The battle between Buizel and Lucario ends up in a tie but Maylene still gives Ash the Cobble Badge.', 23, '2008-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 17, 'Enter Galactic!', 'With Ash acquiring the Cobble Badge, our heroes decide to spend the night in Veilstone City before heading out. Reggie takes the group to a park with several meteoric stones lie. However, Team Galactic appears and try to steal them for their world domination plans.', 23, '2008-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 18, 'The Bells Are Singing!', 'While training Gligar, Ash hears singing. When they look to see who is singing, they meet a magician named Francesca and her three Chingling. Francesca is trying to get her spoiled Chingling to have a better attitude.', 23, '2008-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 19, 'Pokémon Ranger and the Kidnapped Riolu! (1)', 'On their travels, Ash and his friends meet up with another Pokémon Ranger—Kellyn—and a Riolu. It turns out that Hunter J is after Riolu, due to its ability to use Aura Sphere before evolving. Ash and Riolu start to bond with their shared Aura, but J is insistent on getting it. This episode relates to the secret mission in Pokémon Ranger: Shadows of Almia, from which the player can transfer a Riolu that knows Aura Sphere to their copy of Diamond, Pearl, or Platinum.', 23, '2008-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 20, 'Pokémon Ranger and the Kidnapped Riolu! (2)', 'Hunter J has managed to kidnap Riolu. But despite that, Riolu, reveals his whereabouts to Ash, using its Aura. With Rangers Kellyn and Solana joining them, Ash and his friends go to hunt down Hunter J and get Riolu back. However, J is far more formidable than anyone could have anticipated. Will Ash and friends be able to return Riolu back to its kingdom?', 23, '2008-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 21, 'Crossing Paths', 'Ash and Co. arrive at a lakeside Pokémon Center. Jessie''s Dustox sees a shiny Dustox, and follows it to the lake. Jessie releases her Dustox, allowing it to mate. This is related to the Season 1 episode 21, "Bye Bye Butterfree" where Ash releases his Butterfree so it can mate with a pink Butterfree.', 23, '2008-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 22, 'Pika and Goliath!', 'Ash and his friends meet Sho, a boy who has a Pichu and a Raichu. He mistakes Ash''s Pikachu for a wild Pokémon. Just like at the Vermillion City Gym, Ash and Pikachu have the option again to evolve Pikachu to Raichu, after a loss to a stronger opponent. Paul witnesses this defeat and scolds Ash for losing to such an opponent, but manages to redeem himself of that defeat in a rematch.', 23, '2008-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 23, 'Our Cup Runneth Over!', 'Ash, Brock and Dawn meet the Champion of the Hoenn Region, Wallace. He says he will be holding a Pokémon Contest and the winner receives a ribbon that can be used anywhere. The group spends the day with him, resulting in advice from Wallace for Dawn to play with her Pokémon more and for Ash to enter Buizel in the contest. At the end of the episode, Ash receives a phone call from his friend, May.', 23, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 24, 'A Full Course Tag Battle!', 'Ash and Brock''s old friend May, still training to become a Top Coordinator, visits Sinnoh for the Wallace Cup. Upon arrival at the Seven Stars Restaurant, they find out that only those who win a tag-battle against the restaurant''s owners can eat there. Ash partners with Brock and win the double combat with a single move. Before Dawn and May''s combat, Team Rockets steals all food from the restaurant. May and Dawn partner up and defeat both the Team Rocket and the restaurant''s owners, the later by using Blaziken and Piplup together to create a fantastic fire/water combination. There is a cameo from Drew, Harley, and Max.', 23, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 25, 'Staging a Heroes'' Welcome!', 'Ash and his friends have arrived at the Lake Resort where the Wallace Cup will take place. Zoey also arrives, and competes, too. Right when the contest began, Dawn becomes nervous and has trouble keeping her composure. Meanwhile, May decides to enter with Wartortle, and Ash enters with Buizel. There are cameos of Drew, Harley, Max, Norman, Caroline, and Solidad.', 23, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 26, 'Pruning a Passel of Pals!', 'At night, Ash takes a walk near the Lake Valor with Pikachu when suddenly, something in the center of the lake begins to glow, and it turns out that Azelf appears. When Ash tries to approach it, the shadow disappears again. The next day, the second round of the Wallace Cup begins. May''s Venusaur is then revealed, and there is a cameo appearance of May''s Skitty battling in the second round. Dawn, May and Zoey make it to the semi finals but Ash loses to a tough coordinator called Kyle. After it is Dawn''s turn to battle Kyle in the semi-final, she uses Piplup against his Crawdaunt. There are cameos of Norman, Caroline, Max, Kenny and Paul.', 23, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 27, 'Strategy with a Smile!', 'Dawn beats Kyle and May beats Zoey in the semi finals and both have to battle in the finals. In the finals, Dawn faces-off against May in the Wallace Cup. Dawn uses Piplup and May uses her Glaceon. Dawn manages to narrowly defeat May''s Glaceon by a fraction. After the contest ends, Dawn earns her second Ribbon! Now that the contest is over, May departs from Ash, Dawn, and Brock once again and goes back to Johto.', 23, '2008-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 28, 'The Thief That Keeps on Thieving!', 'When on their way to Pastoria City, Ash and friends meet a trainer named Tyler that wants to catch a Yanma. But Team Rocket ends up catching it after he weakened it. After Jessie captures the Yanma and sends it to Giovanni, who rejects it, she decides to train it herself and it quickly evolves into Yanmega.', 23, '2008-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 29, 'Chim-Charred!', 'Ash and co. are running after Gligar who has been blown away by a gust, and promptly run into Paul. After a huge argument about their different ways of treating Pokémon, Ash challenges Paul to a battle. But when Chimchar is battling Paul''s Ursaring, it activates an overpowering blaze. Chimchar also gets confused and starts randomly attacking anyone in its path.', 23, '2008-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 30, 'Cream of the Croagunk Crop!', 'After Ash & Co. arrive in Pastoria City, Crasher Wake refuses Ash''s request for a battle because he has to take care of something. They tag along and find out there is a Croagunk Festival in the Pastoria Great Marsh.', 23, '2008-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 31, 'A Crasher Course in Power!', 'At the Pastoria Gym Ash challenges Crasher Wake to a 3-on-3 Gym Battle using Pikachu, Turtwig and Buizel, while Wake uses Gyarados, Quagsire, and Floatzel. However, Pikachu accidentally shocks Buizel and this causes them to argue which makes a difficulty in helping Ash defeat Wake. Suddenly, thanks to that Buizel had rescued Pikachu from the attack; their argument concludes. Ash manages to defeat Wake and he earns the Fen Badge.', 23, '2008-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 32, 'Hungry for the Good Life!', 'A Swinub shows up at Mr. Backlot''s mansion and starts to eat all the Poffins. Dawn tries to stop it by making her own Poffins for Swinub. Dawn ends up capturing Swinub at the end of the episode.', 23, '2008-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 33, 'Fighting Fear with Fear!', 'Ash continues his training with Gligar, but finds out it has become fearful of battles since the battle against Paul''s Gliscor. The group meets Gary again, and Ash asks Gary to help him solve the problem with Gligar, and Gary gives Ash a Razor Fang, which makes Gligar evolve into Gliscor.', 23, '2008-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 34, 'Arriving in Style!', 'Ash and friends return to Hearthome City to challenge the Gym Leader who was gone during their last visit. However, they hear that the Gym Leader is still gone, making Ash unable to have his fifth Gym Battle. The group meets Paris, a Pokémon Stylist, and her Lopunny. She suggests that Dawn should enter the Hearthome Collection, a famous fashion show.', 23, '2008-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 35, 'The Psyduck Stops Here!', 'While traveling through a deep valley, Ash and friends encounter a swarm of Psyduck in the middle of a road. Upon trying to pass them, the Psyduck suddenly start attacking them.', 23, '2008-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 36, 'Camping it Up!', 'When Ash & Co. are invited to attend a Pokémon Academy, they decide to enter it. For their first task, they choose a PokéBall that contains a Pokémon inside. The trainer then has to train the Pokémon and be able to use it in battle. The gang then meets Angie, and meets Conway again.', 23, '2008-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 37, 'Up Close and Personable!', 'While at a Pokémon Academy, Ash, Dawn, Brock, Angie, and Conway find that their Pokémon are becoming hypnotized when they go near a lake. So they decide to go and investigate what''s going on.', 23, '2008-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 38, 'Ghoul Daze!', 'While Ash and friends are training at the Summer Academy, they are taught how to deal with Ghost-Type Pokémon, should they ever run into them. They are then paired up to find a hidden treasure. While searching, Conway has a run-in with a Dusknoir.', 23, '2008-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 39, 'One Team, Two Team, Red Team, Blue Team!', 'After the Trainers are finished with the training, they must use a Pokémon to bring them across a rigorous track to the finish line. Finally after a tough competition Ash and Pikachu came first, and Angie and Shinx came second which led to the victory of the red team. Everyone is given a certificate. They said good bye, and the team continued their journey.', 23, '2008-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 40, 'A Lean Mean Team Rocket Machine!', 'On their way to Celestic Town, Ash and his friends have to take Piplup to the Pokémon Center after it collapsed from over-excessive training. Meanwhile, Team Rocket, who were following the group on a slope, decide to have lunch in a luxury restaurant. But then Jessie notices that Meowth''s golden charm is buried under rolls of flab. The trio now realizes that, due to them having led a rich and luxurious life ever since they had earned the money at the summer school, they have become lazy and grown a lot in flesh. Wanting to return to their former "sharp and cool" shapes, they start a harsh training session.', 23, '2008-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 41, 'Playing the Leveling Field!', 'Zoey is facing a critical situation against a very tough coordinator. With her Glameow confused, the battle ends quickly. Ash and co. cheer for Zoey who was defeated by the mysterious trainer. This mysterious trainer is none other than Fantina, who like Hoenn''s Juan is a coordinator and the Hearthome Gym Leader. Ash requests that he battle her and she accepts. How will this battle turn out? And can it prepare Ash for his actual Gym Battle?', 23, '2008-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 42, 'Doc Brock!', 'Brock is away on an errand. When they can''t handle it, they send Gliscor to bring Brock back. Brock finds he can''t carry Gliscor back, as it can''t glide in the wind going the opposite direction, and leaves it, promising to return for it. At the end of the episode, the gang comically realizes that they left Gliscor behind, and scene shows a frustrated Gliscor with a long way to go.', 23, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 43, 'Battling the Generation Gap!', 'Dawn has entered the latest contest held in Celestic Town. Dawn meets her mother''s old rival Yuri, that wants to win this contest. When she and her mom''s rival "Lila" (Yuri in Japanese version) come face to face in the Finals of the contest Dawn has to give it all she has to win. Dawn wins the Celestic Town ribbon and her third contest ribbon.', 23, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 44, 'Losing Its Lustrous!', 'Commander Mars and Cyrus (not known yet by Ash and co. that he is a part of Team Galactic) debuted in the anime along with Commander Saturn and the other Galactic grunts . In this episode, they steal the Lustrous Orb and the Adamant Orb from the Celestic Town museum for the power to awake Dialga and Palkia in their future plans.', 23, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 45, 'Double Team Turnover!', 'In this episode Commander Jupiter is introduced. Ash and the gang are helped by Cynthia to stop Team Galactic from stealing the Lustrous Orb and the Adamant Orb, but they fail because they had no idea how large Team Galactic was.', 23, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 46, 'If the Scarf Fits, Wear It!', 'Arriving back in Solaceon Town, the gang meet up with Angie at her Parent''s Daycare. She tells them her parents are gone for a while, so she leaves the daycare to her for a while. Ash and the gang tell her about the strange monster terrorizing Solaceon Town. She later reveals that the monster is a Lickilicky that she evolved from a Lickitung which she taught it Rollout. So the gang goes out and helps her find the Lickilicky and bring it back. At the end of the episode, it is revealed the Angie may have a crush on Ash.', 23, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 47, 'A Trainer and Child Reunion!', 'As Ash and the gang are heading back to Hearthome City, they encounter Aaron, a member of the Elite Four. They see that he''s training his bug Pokémon, but also himself. He explains to the gang that he''s trying to look for a Wurmple he released as a child as he felt it could become stronger on its own, but he wants him back. The gang offers to help Aaron look for his released Wurmple. They find Aaron''s Wurmple, but since then it has evolved into Beautifly. The two become a team again. In the end, Aaron happily says thank you and a farewell, and Ash and his friends head on to Hearthome City.', 23, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 48, 'Aiding the Enemy!', 'Ash has a battle with Paul. Choosing a one-on-one battle, Paul chooses Honchkrow, and Ash chooses Turtwig. Honchkrow manages to drive Turtwig into a corner, but at the last moment, Turtwig evolves into Grotle. However, Grotle loses all its agility and loses to Honchkrow anyway. Paul then reveals to Ash that he has already obtained the Hearthome City gym badge. Afterwards, Brock confronts Paul that he met his older brother Reggie over a missing Frontier Brain symbol, which in turn, partially reveals Paul''s captious nature of becoming strong. Grotle gets up late that night and unsuccessfully tries to regain its agility. Paul''s Torterra shows up and comforts Grotle by showing it that speed isn''t everything about battles. Torterra tells Grotle that it can also rely on defense. Torterra shows an example with Ash''s Gliscor using a Steel Wing straight to the head. Torterra emerges unscathed, and Grotle resumes to its normal behavior.', 23, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 49, 'Barry''s Busting Out All Over!', 'Upon arriving at the Hearthome Gym, Ash and his friends run into Barry, a trainer from Twinleaf Town. Barry turns out to be an admirer of Paul, whom he saw when watching the Double Battle Tournament. Ash challenges Barry to a Pokémon battle. Ash chooses Chimchar, Gliscor, and Pikachu, against Barry''s Staraptor, Roserade, and Empoleon. Ash manages to narrowly defeat Barry, finishing off Empoleon with Pikachu''s Volt Tackle.', 23, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 50, 'Shield with a Twist!', 'The Gym battle between Ash and the Hearthome Gym Leader Fantina has begun. Ash chooses Buizel to battle Gengar, Chimchar to battle Mismagius, and Pikachu to battle Driftblim. Using his new counter-shield strategy Buizel defeats Gengar, Chimchar defeats Mismagius but Pikachu gets defeated by Driftblim when Fantina uses her own strategy against him, Buizel also gets defeated by Driftblim, but Chimchar finally defeats Driftblim, and Ash wins the Relic Badge. Barry, having seen Ash defeat a Gym Leader he lost to, declares that Ash is a rival if Ash can beat the leader of the Canalave Gym. Meanwhile, Jessie, as her alter ego, Jessilina, wins her second ribbon using her Yanmega in the Majolica Town Contest!', 23, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 51, 'Jumping Rocket Ship!', 'Ash and company, along with Barry, take a ride in a blimp to Canalave City. When they arrive, Team Rocket, disguised as photographers, trick them into taking a picture of all of their Pokémon, which actually turns out to be a net to kidnap them. The Pokémon fight back to attempt to escape, and everyone''s Pokémon (including Team Rocket''s) gets blown away into the sky in the process and they all get separated. A chase ensues when Team Rocket declares that whomever should find the Pokémon first, gets to keep them all. When Meowth is grouped with Pikachu, Pachirisu, and Mime Jr. after the explosion, he considers leaving Team Rocket for good. Can all of the Pokémon find their trainers?', 23, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 11), 52, 'Sleepless in Pre-Battle', 'The group heads to the Canalave Gym, but they are told that the Gym Leader isn''t there right now. At a police station, the group is told by Officer Jenny that all the people in the town are having nightmares, and that the cause of the nightmares seems to be the Pokémon Darkrai. Also, Dawn''s Swinub evolves into Piloswine in order to stop Team Rocket from stealing Cresselia.', 23, '2008-12-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 12, 'Diamond and Pearl: Galactic Battles', 'As the menace of Team Galactic continues to loom over the Sinnoh region, Ash and Dawn keep getting caught up in the schemes of this mysterious group of villains—as well as facing some other unexpected challenges! Dawn’s got her hands full dealing with the many problems of her Pokémon, while Ash’s ongoing rivalry with Paul finally comes to a head in a full 6-on-6 battle! It might be the ultimate test of training styles—will our heroes come out on top?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 1, 'Get Your Rotom Running!', 'Ash and company arrive at the gym, but the gym leader is out training on Iron Island. In the meantime, the town is suffering from nightmares and no one is getting any sleep.', 23, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 2, 'A Breed Stampede!', 'As Ash continues training for his gym battle. Dawn tries to train with her newly evolved Piloswine, and learns that her Pokémon isn''t as receptive as its non-evolved form.', 23, '2008-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 3, 'Ancient Family Matters!', 'Ash gets word that the gym leader has returned. Roark, the gym leader from Oreburg City has come to challenge his father, Byron the Canalave City gym leader. With Roark using Rampardos and Byron using Bastiodon, who will win the battle?', 23, '2008-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 4, 'Dealing With Defensive Types!', 'With Oreburgh Gym Leader Roark as referee, Ash starts his 3-on-3 Gym battle against Byron, Canalave''s fossil-loving Gym Leader. Byron''s first Pokémon is the Steel-and-Psychic Bronzor, so Ash sends out Chimchar, a Fire-type Pokémon. But Bronzor''s Ability, Heatproof, helps protect it against Chimchar''s Fire attacks, and then it uses Rain Dance to rain on Chimchar''s parade! Chimchar refuses to give up, and uses Flame Wheel in a head-on charge against Bronzor''s Gyro Ball—the hit knocks out Bronzor, but Chimchar barely manages to stay on its feet!', 23, '2008-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 5, 'Leading a Stray!', 'A Wailord blockage has trapped the boats in Canalave''s harbor, and that means Dawn can''t take a ferry to her next Contest. There''s nothing to do but sit down for lunch, but a wild Luxio and its Pokémon accomplices steal the food! Pikachu and Piplup give chase, but run straight into Team Rocket. As always, Team Rocket tries to grab Pikachu, but Ash catches up with them and escapes into the sewer with his buddy. Piplup uses Whirlpool to toss Team Rocket, and now it''s up to Ash to find his way back to his friends. As he wanders the sewers, he comes across the Luxio and its pals. They stole the food to feed a stranded Wailmer that somehow ended up in the sewer!', 23, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 6, 'Steeling Peace of Mind!', 'On Iron Island, Ash''s rival Barry is training with his Empoleon and Heracross when Empoleon suddenly turns on its Trainer. Barry calls Ash and Dawn, who are still in Canalave Town, to tell them what happened—other Pokémon on Iron Island are acting strangely, too! Ash and his friends catch the next ferry to Iron Island, with Team Rocket following them in secret, but Barry has already gone out to explore the island. Whatever is happening, only Steel-type Pokémon are affected, but why?', 23, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 7, 'Saving the World from Ruins!', 'Ash and company continue their struggle to stop Team Galactic''s latest scheme, which is somehow affecting steel type Pokémon. They learn this is just part of Team Galactic''s overall plan.', 23, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 8, 'Cheers on Castaways Isle!', 'Pikachu and Piplup get themselves stranded on an island where they discover a Corphish and several Mantykes taking care to a mysterious egg.', 23, '2009-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 9, 'Hold the Phione!', 'As Dawn prepares for the next contest, the adventurers try to spot a rare Phione. One Phione becomes attracted to one of Dawn''s Pokémon.', 23, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 10, 'Another One Gabites the Dust!', 'Dawn enters the Chocovine town Pokémon contest and meets a tough trainer named Ursula. Will she win her fourth ribbon?', 23, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 11, 'Stealing the Conversation!', 'Team Rocket steals Officer Jenny''s Chatot.', 23, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 12, 'The Drifting Snorunt!', 'A Froslass holds Meowth and Piplup captive and will only release them when her friend, a Snowrunt is returned.', 23, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 13, 'Noodles! Roamin'' Off!', 'Meowth decides to leave Team Rocket to become a Noodle Chef, which prompts the other members to pursue their own goals.', 23, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 14, 'Pursuing a Lofty Goal!', 'Ash enters a Poké Ringer contest with Staravia. Paul also enters the competition.', 23, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 15, 'Trials and Adulations!', 'Dawn encounters an Agron and become separated from Ash and Brock. When one of her Pokémon is injured fighting the Agron, she must use everything she''s learned to heal her Pokémon.', 23, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 16, 'The Mysterious Creatures, Pokémon!', 'The friends travel toward Snowpoint City.', 23, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 17, 'The Lonely Snover!', 'Ash and company encounter a Snover who longs for companionship.', 23, '2009-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 18, 'Stopped in the Name of Love!', 'Piplup seems to be worn out lately. They notice Piplup starts to glow. Everyone is excited by the prospect of Piplup evolving, except for Piplup.', 23, '2009-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 19, 'Old Rivals, New Tricks!', 'Dawn enters the Sandlestraw contest.', 23, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 20, 'To Thine Own Pokémon Be True!', 'Ash and Dawn enter a Pokémon Ping Pong Contest. After the contest, a trainer approaches Dawn and asks if he can train Ambipom for Ping Pong Contests.', 23, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 21, 'Battling a Cute Drama!', 'The group encounters a Pokémon Trainer who doesn''t appear to realize what Pokémon battles are about, and try to teach her what''s really important.', 23, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 22, 'Classroom Training!', 'Ash and company meet up with Zoey in Snowpoint City. The Gym Leader convinces Ash to teach a Pokémon class before their battle.', 23, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 23, 'Sliding Into Seventh!', 'Ash finally arrives at Snowpoint Gym for his battle with Candice. This gym will be different from his previous gym challenges, with each trainer using 4 Pokémon each. Can Ash defeat Candice and win his seventh badge?', 23, '2009-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 24, 'A Pyramiding Rage!', 'Following Ash''s victory at the Snowpoint City Gym against the Gym Leader Candice, who should appear out of nowhere but Ash''s rival Paul! Asking for a Battle with Candice as well, Paul is told he''ll have to wait until the following day. But suddenly Paul''s brother Reggie appears, and also - none other than the Kanto Frontier Brain from the Battle Pyramid, Brandon! Knowing that the only challenge Reggie ever made in his career as a Trainer that wasn''t successful was when he challenged Brandon, Paul immediately challenges Brandon on the spot, vowing to beat him and ...', 23, '2009-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 25, 'Pillars of Friendship!', 'Some Pokémon hunters attack a Temple and awaken a legendary Pokémon. The Pokémon goes on a rampage. Ash helps Brandon to calm the enraged Pokémon.', 23, '2009-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 26, 'Frozen on Their Tracks!', 'The group takes a train to their next destination. The train takes an unexpected stop. Team Rocket tries to take advantage of the situation.', 23, '2009-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 27, 'Pedal to the Mettle!', 'Ash and friends arrive at Lake Acuity, the site where Ash and Paul will have their full 6-vs-6 battle. After healing his Pokémon, Ash meets up with Paul and the two begin their long awaited battle. Who will ultimately be victorious?', 23, '2009-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 28, 'Evolving Strategies!', 'Ash and Paul continue their 6-on-6 battle. With both teams fighting extremely hard it could be anyone''s match, so Paul calls out his newly evolved Magmortar, hoping it will secure him victory.', 23, '2009-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 29, 'Uncrushing Defeat!', 'With all of his Pokémon weak and injured from the battle with Paul, Ash rushes to the Pokémon Center in order to get them healed. Nurse Joy does not, however, have the berry needed to properly heal Monferno. Brock decides to help and heads to Lake Acuity to find it. While at the lake, something strange happens.', 23, '2009-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 30, 'Promoting Healthy Tangrowth!', 'Dawn decides to start training for the next Pokémon Contest with Mamoswine. However, despite overcoming its disobedience, Mamoswine still won''t battle.', 23, '2009-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 31, 'Beating the Bustle and Hustle!', 'Dawn''s favorite television program Pokémon Hustle was employing actors near the group''s location, and, naturally, Dawn was eager for the chance to take part and therefore she, Ash and Brock decided to check the program out.', 23, '2009-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 32, 'Gateway to Ruin!', 'While returning a wild Shellos to its herd, the adventurers encounter Team Galactic as they''re trying to unearth some ruins.', 23, '2009-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 33, 'Three Sides to Every Story', 'Piplup and a wild Elekid compete over the affections of a Maril.', 23, '2009-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 34, 'Strategy Begins at Home!', 'The adventurers stay with Dawn''s mother as Dawn prepares for the next Pokémon contest. Dawn challenges her mother to a battle.', 23, '2009-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 35, 'A Faux Oak Finish!', 'Professor Oak arrives in Twin Leaf Town to give a lecture. But he gets distracted by some Pokémon, who need his assistance. Team Rocket attempt to take advantage of the situation.', 23, '2009-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 36, 'Historical Mystery Tour', 'As the Twin Leaf festival draws to a close, Ash, Dawn and Barry encounter a Xatu and wind up miniaturized and trying to find a way to return to normal.', 23, '2009-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 37, 'Challenging a Towering Figure', 'The Twin Leaf Town festival draws to a close. Only one person can challenge Palmer, Barry''s father, and one of the Battle Frontier Brains from Sinou.', 23, '2009-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 38, 'Where No Togepi Has Gone Before!', 'The young adventurers and Team Rocket encounter a mischievous Togepi.', 23, '2009-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 39, 'An Egg Scramble!', 'While they are traveling, Ash and friends meet Lyra and Khoury, who are from the Johto region. Dawn and Lyra have a battle in which Dawn wins and gets an egg, which hatches into a Cyndaquil.', 23, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 40, 'Gone With the Windworks!', 'Lyra and Khoury have joined Ash, Dawn and Brock on their journey across the Sinnoh region. However, while Dawn trains for the Lilypad Town Pokémon contest with her Cyndaquil battling Ash''s Grotle (with Piplup stealing Cyndaquil''s poffin and getting into a fight), Lyra loses her Marill, which seems to have gone to the Valley Windworks. The group make for the Windworks immediately, but Magnemite appears out of nowhere and attacks. Then, they find Marill in the basement storage room only to get locked in. After a few unsuccessful attempts to open the locked door, Ash and his friends are finally free after Pikachu cancels the lockdown by using Thunderbolt on Team Rocket and restoring power to the Windworks. Having found Lyra''s Marill, Ash and his friends are confronted by Team Rocket and their giant Magcargo Cannon, but Pikachu saves the day by using Thunderbolt. (Piplup pushes Cyndaquil to the side an gets into another fight)', 23, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 41, 'A Rivalry to Gible On!', 'Ash and Khoury compete for a wild Gible, who likes to play tricks on everyone, so Ash with his Buizel and Khoury with Totodile, try to compete to capture the wild Gible. At the end, Khoury catches the Gible as his first Sinnoh Pokémon.', 23, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 42, 'Dressed for Jess Success!', 'As the Lilypad Town Contest begins, Jessie gets sick and James takes her place in the contest. Dawn uses Piplup in the first round and James uses Meowth. Dawn and James both make it to the Semi-Final Round and compete for the Suiren Ribbon. Dawn uses Mamoswine for the battle round and James uses Carnivine. Dawn''s Mamoswine uses a new strategy with Ice Shard as Grotle swallows energy ball a few episodes ago ''(Episode 609)'', but still she loses to James. In the final round, James wins the contest and gives the ribbon to Jessie.', 23, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 43, 'Bagged Then Tagged!', 'Ash and Dawn have a tag battle against Lyra and Khoury. Ash sends out Monferno and Dawn sends out Cyndaquil. Lyra sends out Chikorita and Khoury sends out Totodile. During the battle, Totodile evolves into Croconaw. Ash''s Monferno finishes up with Mach Punch and defeats Croconaw and Monferno teams up with Cyndaquil using Flamethrower and Flame Wheel. Ash and Dawn eventually win the battle, and Lyra and Khoury leave the group and go back to Johto, but not before Khoury''s father gives Brock the Pokégear as a thanking present to them by showing Lyra and Khoury a little bit of Sinnoh.', 23, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 44, 'Try for the Family Stone!', 'A young boy with a Murkrow and a young girl with a Misdreavus compete for a Dusk Stone to evolve their respective Pokémon into either Honchkrow or Mismagius.', 23, '2009-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 45, 'Sticking with Who You Know!', 'A Pokémon scientist creates a love machine which will create a friendship between his water and electric Pokémon (Quagasire and Magnemite) but a flaw in it creates the friendship between the water and electric Pokémon all over that area. Unfortunately, Ash''s Pikachu and Dawn''s Piplup also comes under this area, thus becoming literally inseparable. The team somehow finds about this machine and helps the scientist to achieve his goal without the machine, thus helping their Pokémon to be free from their trance becoming normal again.', 23, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 46, 'Unlocking the Red Chain of Events!', 'Team Galactic reappears to begin their Red Chain project to achieve Cyrus''s goal in capturing the legendary Pokémon of Time and Space, Dialga and Palkia. Their plan was intervened by Looker of the International Police and Team Rocket, thus capturing them. But Meowth of Team Rocket blasts off alone and was saved by Ash, Dawn and Brock. Through Meowth, they came to know about Team Galactic''s theme and rescues Looker, James and Jessie, but Team Galactic completes their final plan.', 23, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 47, 'The Needs of the Three!', 'Team Galactic''s plans at capturing the Lake Trio triumph with the help of Pokémon Hunter J and upon being transported to Team Galactic''s HQ, Ash, Brock and Dawn find themselves in a tense stand-off with members of Team Galactic while learning that Cyrus, the businessman they met in the past is the leader and founder of Team Galactic. Meanwhile, Hunter J falls to her demise as her ship crashes in Lake Valor when she fails to realise that Future Sight was targeted on her.', 23, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 48, 'The Battle Finale of Legend!', 'As Team Galactic''s plan reaches its final stages, Ash, Brock and Dawn along with Cynthia, the Sinnoh Champion race against time to stop Cyrus from carrying out his plan of creating a new world. Will they succeed or will the Sinnoh region as well as the entire Pokémon world fall victim to Cyrus''s mad plans?', 23, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 49, 'The Treasure Is All Mine!', 'Ash and his friends continue their way to Asatsuki Town for Dawn''s next contest when Ash happens to find a treasure chest. However its contents prove surprising to James as he is forced to face his privileged past, his faithful childhood companion and his fiancée!', 23, '2009-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 50, 'Mastering Current Events!', 'While on the way to Sunyshore City, Ash and his friends meet a gentleman who claims to be the master of air battles. Hoping to improve his Gliscor''s flying, Ash decides to have a battle with him and his Scizor, and the results may be more than he expected... In the end, Gliscor learns Giga Impact, but Ash decides to leave it with the air battle master to train.', 23, '2009-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 51, 'Double-Time Battle Training!', 'Ash, Dawn and Brock meet Zoey and Candice after Zoey''s contest win and Dawn is trying to make new sequence and Zoey asks Dawn to battle her in a double battle and Zoey choose her newly captured Kirlia and Leafeon and Dawn chooses Cyndaquil and Mamoswine and makes her new move called ''Flame Ice''. On TV, Paul is revealed to have obtained the Mine Badge, also meaning he had obtained all the 8 badges necessary in order to compete in the Sinnoh League.', 23, '2009-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 52, 'A Meteoric Rise to Excellence!', 'As our heroes continue toward Daybreak Town and Dawn''s next Pokémon Contest, they lose their sense of direction in a large forest. Peering into the sky, all of a sudden they see what turns out to be a move called Draco Meteor. The move comes from an Altaria, a Pokémon under the tutelage of an elderly woman who calls herself Grandma Wilma. The team asks if they can watch Grandma Wilma''s coaching session with Altaria. Then the whole group is approached by a feisty Gible, which Grandma Wilma says lives in the forest. Gible wants to be able to use Draco Meteor, too, but can''t seem to pull it off!', 23, '2009-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 12), 53, 'Gotta Get a Gible!', 'Ash and friends continue on their way to the next town when they notice that the Gible they helped has been following them. Ash decides to try and catch it, but Barry shows up and wants to catch it too.', 23, '2009-12-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 13, 'Diamond and Pearl: Sinnoh League Victors', 'Watch Ash, Dawn, and Brock travel across the Sinnoh region to face challenges, battles, and the antics of Team Rocket! With Team Galactic out of the way, Ash can now focus on qualifying for the Sinnoh League. And Dawn will train to compete for her final Contest Ribbon, which would allow her to compete in the Grand Festival!');
