INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 13, 'Battling the King of the Mines!', 'With a bag full of revival herbs, our heroes have returned to Driftveil City and Ash is raring to battle Gym Leader Clay!', 23, '2012-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 14, 'Crisis at Chargestone Cave!', 'Continuing their journey to Mistralton City, our heroes encounter Chargestone Cave and a dilemma for its occupants!', 23, '2012-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 15, 'Evolution Exchange Excitement!', 'After witnessing a dramatic Pokémon trade and evolution, Ash and his friends'' excitement has just begun!', 23, '2012-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 16, 'Explorers of the Hero''s Ruin!', 'The elder Professor Juniper has invited our heroes to join him in what he promises will be an exciting adventure...and he keeps his promise!', 23, '2012-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 17, 'Battling the Bully!', 'An encounter with Pikachu''s rival from the past puts our heroes in the middle of a bullying confrontation!', 23, '2012-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 18, 'Baffling the Bouffalant!', 'Ash and friends continue their journey to Mistralton City as they head through a forest. They stop for a lunch break when suddenly they get attacked by a Bouffalant. After running away, the gang gets separated.', 23, '2012-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 19, 'Cilan Takes Flight!', 'Ash is surprised to see a long line of Trainers waiting to challenge Skyla, the Mistralton City Gym Leader, and is even more surprised when he’s told he has to make an appointment for their battle!', 23, '2012-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 20, 'An Amazing Aerial Battle!', 'After some convincing by a group of young challengers and Skyla’s grandfather, Skyla takes Ash up on his Gym Battle challenge.', 23, '2012-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 21, 'Climbing the Tower of Success!', 'After winning his sixth badge, Ash and friends bump into Stephan. He is in town to compete in the Bell of Wishes Festival that is being held that day. Ash, Iris, and Cilan, after finding out that the winner gets to ring the bell atop Mistralton Tower and get a wish granted, decide to compete in the festival.', 23, '2012-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 22, 'The Clubsplosion Begins!', 'At Ambiga Town, the local Don George holds a tournament called "Clubsplosion" to showcase Fighting-Type Pokémon, but all are welcome. Ash, Stephan, Bianca, Trip, and Georgia all enter the tournament, with Ash using his Scraggy. Ash and Scraggy''s first opponent is Angus and his Simisage.', 23, '2012-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 23, 'Search for the Clubultimate!', 'The Clubsplosion tournament continues. Iris and Excadrill face off against Burgundy and Dewott. Bianca and Emboar face off against Trip and Conkeldurr. And Dragon Buster Georgia and Bisharp face off against newcomer Gale and her Druddigon.', 23, '2012-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 24, 'A Clubsplosion of Excitement!', 'The first round of the Clubsplosion tournament ends with Bianca''s and Trip''s battle. As the second round gets underway, the remaining contestants battle for the chance to enter the Top 4 in the Clubsplosion semi-finals.', 23, '2012-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 25, 'Commanding the Clubsplosion Crown!', 'The Clubsplosion semifinals rage on. Bianca and Emboar battle Stephan and Sawk, while Ash and Scraggy battle Montgomery and his Throh. In the finals, Stephan and Sawk face Montgomery and Throh. Who will win the Clubsplosion Tournament?', 23, '2012-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 26, 'Battling the Leaf Thieves!', 'During a practice match against Iris'' Emolga, Ash''s Swadloon evolves into Leavanny. Leavanny''s leaf-sewing process causes it to make costumes for the other Pokémon, but this causes Axew to be accidentally kidnapped by a pair of Durant who are building a den. They stop to think about how they are going to enter the Durant''s den, and to be able to rescue Axew.', 23, '2012-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 27, 'A Restoration Confrontation! (1)', 'Ash, Cilan, and Iris make their way to Twist Mountain where they come across a fossil dig that has discovered a fossil Tirtouga. However, Team Rocket arrives and steals the fossil.', 23, '2012-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 28, 'A Restoration Confrontation! (2)', 'The adventure with Mount Twist, Tirtouga, and Carracosta continues.', 23, '2012-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 29, 'Evolution by Fire!', 'Stopping at Abtilbe Town''s Battle Club, Ash meets his Tepig''s former trainer Shamus who abandoned Tepig because he felt he was too weak. Angry, Ash challenges Shamus to a double battle with Snivy and Tepig going up against Shamus''s Emboar and Heatmor.', 23, '2012-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 30, 'Guarding the Guardian of the Mountain!', 'Ash, Iris, and Cilan finally arrive in Icirus City. But before Ash can challenge movie star Brycen and his Beartic for his next Gym Badge, they must help Brycen save Volcarona from the Pokémon Hunter Rizzo and his two Jellicent.', 23, '2012-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 31, 'Caution: Icy Battle Conditions!', 'Ash challenges Brycen for the Icicle Badge, putting Scraggy, Krokorok, and Pignite up against Vanillish, Cryogonal, and Beartic.', 23, '2012-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 32, 'Clash of the Connoisseurs!', 'With only one more badge left, the group heads to Opelucid City so Ash can challenge the Gym Leader. Unfortunately for Ash, the Gym in Opelucid City is closed. When the group stops in Stonesthrow Town, Cilan meets little Marigold who is picking out her first Pokémon today. Cilan offers his skills as a Pokémon Connoisseur, but another A-Class Connoisseur named Ricard Nouveau offers up his services instead of Cilan''s, and they have a battle to determine who is the better Connoisseur. All while the S-Class Connoisseur Fauxgundy watches, but they believe they have seen her somewhere before.', 23, '2012-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 33, 'Crisis at Ferroseed Research!', 'The group meets up with Dragon Buster Georgia who has a Vanilluxe now. They travel to the Ferroseed Institute to see the Moss Pokémon Ferroseed being studied, but when an accident forces an evacuation, Iris, her Axew, Ash''s Oshawott, and Georgia''s Vanilluxe are trapped inside. Iris has not yet overcome her crippling phobia of Ice-Types, and she must figure out a way out with Vanilluxe at her side.', 23, '2012-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 34, 'An Epic Defense Force!', 'After Ash and the gang arrive in Virbank City and Cilan gives them a rundown of the area’s history, they run into their filmmaking friend Luke and his Zorua! Thanks to winning a film festival with the movie our heroes helped him make (The Legend of the Pokémon Knight), Luke is there to attend a preview event for Pokéstar Studios, a theme park opening soon within the film studio lots.', 23, '2012-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 35, 'Rocking the Virbank Gym! (1)', 'Ash heads to Virbank City to face off against its Gym Leader, punk rocker Roxie from the band Koffing and the Toxics, in order to obtain his eighth Unova League Gym Badge.', 23, '2012-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 36, 'Rocking the Virbank Gym! (2)', 'Ash''s battle against Roxie for the Toxic Badge continues.', 23, '2012-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 37, 'All for the Love of Meloetta!', 'After learning the Unova League conference will not be held for three more months, Ash, Iris, and Clian meet up with Cynthia, the Sinnoh Region Champion. She says she has come to Unova to participate in an exhibition match at the Pokémon World Tournament Junior Cup, held in Lacunosa Town, and Ash learns that the prize of the tournament is a battle with Alder, Unova''s reigning Champion. As the four head out of Virbank City for Undella Town, they come across the legendary Melody Pokémon, Meloetta who seems to have fallen ill.', 23, '2012-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 38, 'Piplup, Pansage, and a Meeting of the Times!', 'Upon arriving in Undella Town, Cynthia leads the gang to her villa where Dawn and Piplup are waiting for them. Dawn has come to Unova to perfect her Coordinator skills, and Cilan decides to have a Tasting Battle to see exactly what she can do.', 23, '2012-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 39, 'Expedition to Onix Island!', 'While Cynthia is preparing for the Junior Cup, Ash, Cilan, Iris, and Dawn take a trip to an uninhabited island for some relaxation. However, they soon discover the island is home to several Onix that begin to attack them.', 23, '2012-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 40, 'The Mystery of the Missing Cubchoo!', 'While in Undella Town, Cilan helps a boy named Chris track down his missing Cubchoo. However, they instead find a roaming Beartic that might have once been Chris''s Cubchoo.', 23, '2012-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 41, 'Iris and the Rogue Dragonite!', 'When the power goes out in Undella Town, the gang tries to help out when they discover a rampaging Dragonite may be to blame. When Iris discovers the Dragonite, she believes it is truly not bad but she is soon trapped in the room with the Dragonite along with Ash''s Oshawott and Dawn''s Piplup.', 23, '2012-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 42, 'Jostling for the Junior Cup!', 'The Pokémon World Tournament Junior Cup begins, with rivals such as Trip, Georgia, and Burgundy showing up to take part in the tournament. After an exhibition match between Sinnoh Champion Cynthia''s Garchomp and Unova Elite Four member Caitlin''s Gothitelle ends in a no official winner, the first round begins. Iris is up first against Georgia, with Iris''s newly captured Dragonite being pitted up against Georgia''s Beartic.', 23, '2012-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 43, 'Battling Authority, Once Again!!', 'The quarter-final matches of the Pokémon World Tournament Junior Cup take place, and Iris must go up against Dawn, pitting Dragonite against Mammoswine. In another match, Cilan and Crustle take on Trip and Serperior.', 23, '2012-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 44, 'Ash, Iris, and Trip: Then There Were Three!!', 'With the semi-finals of the Pokémon World Tournament Junior Cup underway, and with the grand prize of having a battle with Alder on the line, Ash, Iris, and Trip go all out.', 23, '2012-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 45, 'Goodbye, Junior Cup - Hello Adventure!', 'After Trip''s match against Alder, the Junior Cup draws to a close and the contestants bid each other farewell. Ash, Iris, and Cilan meet Cameron, a young naive trainer who wants to travel with them. Dawn bids farewell as well, but not before having a practice match against Ash.', 23, '2012-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 46, 'The Road to Humilau', 'Ash, Iris, and Cilan help Cameron get to Humilau City where he wants to challenge Marlon for his own eighth Unova League Gym Badge. On the way, Ash and Cameron are separated from the group. Ash almost falls off a cliff, but then Cameron saves his life. Cameron has a "great idea" and he gets out what seems to be a "map", which was a table cloth. As they continue heading down a road, it starts to rain and then they take shelter in a nearby cave. Realizing that they didn''t have any food, Ash, Cameron and their Pokémon are hungry as Meloetta leaves only to come back with an apple. Meloetta leads them to an apple tree where they harvest the apples to bring them back to the cave to munch on them. After they ate the apples (and Cameron''s Riolu hiccups adorably), they decide to stay the night in the cave until the rain stops. Ash and Cameron exchange their goals in life. Ash wanting to a Pokémon Master while Cameron wanting to be the best Pokémon Champion in the world.', 23, '2012-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 47, 'Unrest at the Nursery', 'While still staying at Cynthia''s villa and training for the Unova League conference, Ash and the gang come across a fighting pair of Rufflet and Vullaby. It turns out they have both escaped the inexperienced Day Care Nurse, Layla. Whilst the manager is away, Ash, Iris and Cilan help Layla in the Nursery, but the ongoing conflict between the two Pokémon both craving Layla''s attention continues.', 23, '2012-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 48, 'Meloetta and the Undersea Temple', 'Ash continues to train at Cynthia''s villa until Ridley (a member of an ancient civilisation dedicated to protecting Meloetta) and his Golurk hear Meloetta''s song and come to take Meloetta back. At first, Ridley assumes Ash is associated with the thieves, but this turns out not to be the case. Before Ridley can take Meloetta home, Team Rocket assaults the group and capture Meloetta and summon up the ancient Abyssal Temple through its power and song. The heroes try to fend off Team Rocket, but with Giovanni himself present they are too strong.', 23, '2012-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 15), 49, 'Unova''s Survival Crisis', 'With Meloetta in their possession, Team Rocket''s Giovanni controls Tornadus, Thundurus and Landorus in their more powerful Therian Formes though use of the reveal glass unlocked by Meloetta''s presence and Meloetta''s song. Ash, Cilan, Iris, Cynthia, and Ridley do their best to free Meloetta and save the world from Team Rocket. But forces stronger than Team Rocket are present, and Giovanni soon finds himself not able to control himself and sets Tornadus, Thundurus, and Landorus on a path to destroy Unova rather than take it over for Team Rocket.', 23, '2012-10-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 16, 'Black & White: Adventures in Unova', 'Ash and his friends Iris and Cilan have foiled Team Rocket’s latest evil plan, but a new danger lurks on the horizon! But first, with eight Gym badges in hand, Ash is ready to take on the region’s ultimate challenge: the Unova League, where he’ll face familiar rivals and new opponents in his ongoing quest to become a Pokémon Master! Meanwhile, Iris has been having some trouble connecting with her powerful and stubborn Dragonite—can a visit home to the Village of Dragons help sort things out for the aspiring Dragon Master? And what exciting new adventures await our heroes beyond the Unova League? The answers to come, as the journey continues!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 1, 'Beauties Battling for Pride and Prestige!', 'Learning that the Unova League will be held at Vertress City, Ash and his friends prepare for the tournament, but not before making a detour towards Iris'' hometown, the Village of Dragons. But along the way, Iris drags the boys and their Pokémon into competing against a group of women who believe that their Pokémon are not only powerful but more beautiful than anyone else''s. ', 23, '2012-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 2, 'A Surface to Air Tag Battle Team!', 'On the way to the Unova League, Ash and Cilan get challenged to a Tag Battle against the brothers Soren and Rocko who have trained their Braviary (Soldier of the skies) and Drilbur (Warrior of the land) to perform amazing combination attacks. ', 23, '2012-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 3, 'A Village Homecoming!', 'On the way to Vertress City, Ash, Cilan, and Iris find their way to Iris''s hometown: the Village of Dragons. While there, Iris shows Axew to her elder and helps her childhood friend Shannon when one of her Zweilous suddenly evolves into Hydreigon and goes out of control. ', 23, '2012-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 4, 'Drayden Versus Iris: Past, Present, and Future!', 'The gang arrives in Opelucid City for Iris'' scheduled rematch against the Dragon Master and Gym Leader Drayden, who handed her and Excadrill their first-ever defeat years ago. Upon arrival, Iris remembers her difficult time in going to school there and trying to adjust to urban life. She and the others then travel to the Opelucid Gym for her rematch with Drayden, where she puts her Excadrill and Dragonite to the test, respectively, against Drayden''s Haxorus and Druddigon in order for him to evaluate her training and skills.', 23, '2012-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 5, 'Team Eevee and the Pokémon Rescue Squad!', 'Near Vertress City, the gang meets the Pokémon Rescue Squad''s Virgil - trainer of Team Eevee - and his brother Davey, whom they decide to assist in helping a group of troubled Cryoganal. ', 23, '2012-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 6, 'Curtain Up, Unova League!', 'The Unova League begins, and as the preliminary round matches get underway, Ash finds himself up against Trip. ', 23, '2012-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 7, 'Mission: Defeat Your Rival!', 'Ash''s battle against Trip continues, with Pikachu facing Serperior. As the preliminaries end and the first round begins, Bianca pits her Escavalier and Emboar against Cameron''s Samurott and Riolu. ', 23, '2012-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 8, 'Lost at the League!', 'During a break in the competition, Iris''s Axew follows a balloon and gets lost in Vertress City. Pikachu manages to track him down, but they are cornered by a group of Trubbish and their Garbodor leader. ', 23, '2012-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 9, 'Strong Strategy Steals the Show!', 'The third round of battles at the Unova League begins and Ash finds himself up against Stephan, putting Krookodile, Palpitoad, and Leavanny up against Stephan''s Liepard, Zebstrika, and Sawk.', 23, '2012-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 10, 'Cameron''s Secret Weapon!', 'In the fourth round of matches, Ash battles against Cameron - who begins the match by revealing his secret weapon, Hydreigon. ', 23, '2012-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 11, 'A Unova League Evolution!', 'Ash''s Snivy and Pikachu must face off against Cameron and his newly evolved Lucario. ', 23, '2013-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 12, 'New Places... Familiar Faces!', 'With the Unova League tournament over, Ash and company return to Nuvema Town to meet up with Professor Juniper and to tell Professor Oak about his results. Along the way, they meet Nanette who is going to see Juniper for her first Pokémon, and eventually chooses Tepig and asks to have her first battle with Ash. However, during the battle, a robot appears and it is piloted by a very familiar trio. Later, Professor Juniper gets a call from her father, who invites Ash and friends to visit him at the White Ruins, located north of Icirrus City. ', 23, '2013-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 13, 'The Name''s N!', 'On a boat heading to see ruins dedicated to Reshiram, Ash, Iris, and Cilan meet the mysterious boy calling himself N, who quickly befriends their Pokémon. However, when Team Rocket attacks the group once more and James''s Amoonguss paralyzes Pikachu with Stun Spore, N''s timely intervention helps turn the tide of the fight. ', 23, '2013-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 14, 'There''s a New Gym Leader in Town!', 'The group''s boat arrives in Aspertia City, and they arrange to meet Cheren, Professor Juniper''s acquaintance and the city''s new Gym Leader. A teacher at the local Pokémon School, Cheren is lacking in confidence regarding his worth for the title, something Cilan - as a former Gym Leader himself - connects with him over. After misadventures in the Pokémon House on the school grounds - including a series of mishaps between Cilan, Pansage, and a flock of Ducklett - Ash has an unofficial Gym match against Cheren, Oshawott facing off against Herdier. ', 23, '2013-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 15, 'Team Plasma''s Pokémon Power Plot!', 'When Team Plasma scientist Colress uses his machine to draw out Pokémon strength, the controlled wild Pokémon attack the residents of nearby Floccesy Town. Ash, Iris, and Cilan get caught in the middle of the mayhem when Pikachu and Axew also fall under his control, but when they are saved by Looker, they agree to aid him in his investigation of Team Plasma and Colress''s scheme. ', 23, '2013-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 16, 'The Light of Floccesy Ranch!', 'While stopped at Floccesy Ranch, Iris''s Dragonite helps rancher Elly''s Ampharos get into the fighting spirit. ', 23, '2013-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 17, 'Saving Braviary', 'Ash and friends once again run into N, who has freed a Braviary held captive by Team Plasma. They help him bring it to a Pokémon Center, but when Braviary is tracked by a pair of Team Plasma Grunts - Nero and Bianco, who respectively use a Seviper and Zangoose in battle - N puts his life on the line. Successfully freeing Braviary, N joins the group on their journey to the White Ruins. ', 23, '2013-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 18, 'The Pokémon Harbor Patrol!', 'Upon returning to Virbank City, Ash and friends meet Halsey who runs a rescue team consisting of his two Frillish, his Dewott, and his Watchog. Making his personal feelings on the idea of Pokémon putting themselves at risk for the sake of humans known, N''s belief that Watchog (who seems ill-suited for the Team''s risky endeavours) is being used as a tool causes an ideological clash between Halsey and N, but the two young men must put their enmities aside when a fire breaks out in Virbank City''s Industrial Complex. ', 23, '2013-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 19, 'The Fires of a Red-Hot Reunion!', 'Ash and his friends come across the Kanto Fair, and seeing a Charmander perform on stage reminds him of his old friend Charizard. He tells Iris, Cilan and N about his and Charizard''s history, with Misty and Brock making cameos during the tale. Professor Oak sends Charizard over, and after he meets Iris'' Dragonite, the two trainers agree to have a friendly match. Ash''s offer to let Charizard rejoin his team is met with approval from all parties involved. ', 23, '2013-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 20, 'Team Plasma''s Pokémon Manipulation!', 'Colress appears and tests his newly-advanced machine on Dragon-type Pokémon - first taking over a young trainer''s Haxorus, and later Iris''s Dragonite. As Ash and Charizard try to stop them, N puts himself in the crossfire, knowing the Pokémon should be friends and not fight. ', 23, '2013-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 21, 'Secrets From Out of the Fog!', 'After N is hurt by Colress''s machine, two young women, Anthea and Concordia, come to save him. It is from these two girls that Ash and the others learn the truth about N''s life, including his link to the evil Ghetsis. ', 23, '2013-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 22, 'Meowth, Colress and Team Rivalry!', 'Team Plasma''s Colress convinces Team Rocket''s Jessie and James to use his technology on Meowth to make him stronger, but it is all part of Colress''s plans to test his Pokémon controlling device. ', 23, '2013-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 23, 'Ash and N: A Clash of Ideals!', 'At the ruins dedicated to the Pokémon Reshiram, N steals the Light Stone from Cedric Juniper, and Ash''s attempt to stop him ends with them separated from the others. Team Plasma move to attack the White Ruins while Team Rocket watch on in anticipation, and Iris, Cilan and Looker attempt to fight off the enemy forces. ', 23, '2013-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 24, 'Team Plasma and the Awakening Ceremony!', 'Ash and N prepare to save Iris, Cilan, and Professor Juniper''s father from the clutches of Team Plasma before Ghetsis can revive Reshiram, but their attempts to fight back are hampered by Colress''s Pokémon controlling machine, forcing them all to call back their Pokémon. Pikachu gets hit by the machine''s beam, which sways N into surrendering the Light Stone in exchange for its freedom just as Ghetsis arrives, ready to begin the ritual. ', 23, '2013-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 25, 'What Lies Beyond Truth and Ideals!', 'As the revived Reshiram quickly falls under Ghetsis'' control, Ash and friends try to develop a strategy to stop Team Plasma. Looker convinces Team Rocket to help in the fight against the villains, while Ash and Pikachu aim to destroy the controlling machine, and N hopes to pacify the enraged Reshiram before it destroys the world in a righteous fury - akin to when it burned down Team Plasma''s castle in the past. ', 23, '2013-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 26, 'Farewell, Unova! Setting Sail for New Adventures!', 'With Team Plasma defeated once and for all, Ash decides it is time to go back to Kanto. Iris and Cilan decide to go with him to further their skills, and Professor Juniper charters all of them a cruise through the Decolore Islands on a boat with a mysterious crew. Once settled in their cabins, however, Ash finds that they are locked in and their Pokémon are not with them. ', 23, '2013-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 27, 'Danger, Sweet as Honey!', 'The cruise makes a stop on Honey Island, known for its colonies of the Honeycomb Pokémon Combee, Pupa Pokémon Kakuna, Stinger Pokémon Beedrill, and its honey-flavored cuisine. ', 23, '2013-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 28, 'Cilan and the Case of the Purrloin Witness!', 'As Ash and his friends prepare for the upcoming Marine Cup Tournament on board their new cruise ship, the group learns that Mrs. Ripple, a jewel collector, will display her collection after the tournament, but upon the tournament''s conclusion she discovers that her rare Eye of Liepard has been stolen. She suspects Mr. Shaw - a businessman and jewel collector who has been asking to buy the Eye of Liepard from her - even though it was watched over by her Watchog all night. Cilan takes on his detective role once more to discover the thief of the Eye of Liepard. ', 23, '2013-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 29, 'Crowning the Scalchop King!', 'On Scalchop Island, Ash''s Oshawott goes up against the Dewott named Caesar to see who will win the battle at the Scalchop King Competition. ', 23, '2013-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 30, 'The Island of Illusions!', 'On the way to Mahora Island, the gang''s boat passes through fog and they believe they see a familiar shape in it. After avoiding a giant Heatmor when Pikachu''s attacks do not work against it, Axew gets poisoned by a Foongus''s Mushroom Spore attack, forcing the gang to take him to an old Pokémon Center which they soon discover is operating illegally. ', 23, '2013-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 31, 'To Catch a Rotom!', 'Ash, Iris, and Cilan catch up with Professor Oak who has come to one of the Decolore Islands to investigate the Plasma Pokémon Rotom and its Forme Change capabilities. However, the Rotom native to the island are more interested in Pikachu, Emolga, and Stunfisk. ', 23, '2013-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 32, 'The Pirates of Decolore!', 'When Team Rocket tries to ransack the group''s cruise ship''s food store, they are thwarted by a group of self-styled pirate Pokémon group made up of a Croconaw, an Octillery, an Azumarill, and a Ducklett, leaving Ash to try to get the food back. ', 23, '2013-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 33, 'Butterfree and Me!', 'On Wayfarer Island, Ash and his friends see the native Metapod and Butterfree, and when they find a Caterpie who has not yet evolved, Ash takes it upon himself to help the very lazy Pokémon join the rest of its friends, remembering the times he had raising his own Butterfree years ago. ', 23, '2013-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 34, 'The Path That Leads to Goodbye!', 'On Capacia Island, after a Dunsparce Ash fails to capture hurts Axew, Iris gets so mad at him that she says she will no longer be his friend and leaves.', 23, '2013-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 35, 'Searching for a Wish!', 'Ash, Iris, and Cilan take a break on Capacia Island only to discover they have arrived on the one week once every 1000 years when Jirachi awakens and grants a wish. Gemma, a young girl who lives on the island, wants to ask Jirachi to bring prosperity back to the island, but Team Rocket has other plans. ', 23, '2013-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 36, 'Capacia Island UFO!', 'Ash must find a way to stop Beheeyem from taking over a town on Capacia Island after the townspeople, Iris, Cilan, and even Pikachu are placed under the strange Pokémons'' control. ', 23, '2013-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 37, 'The Journalist from Another Region!', 'While on Harvest Island, Ash and his friends meet the Pokémon Reporter Alexa, who has come all the way from the Kalos Region with her Gogoat and Helioptile. She has come to investigate Harvest Island''s fruit harvest festival, which the others realize has a Pokémon Sumo tournament. Ash, Iris, and Cilan enter Pignite, Pansage, and Dragonite in the tournament to win the grand prize Focus Band. ', 23, '2013-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 38, 'Mystery on a Deserted Island!', 'Alexa tells Ash, Iris, and Cilan about Yashi Island, a desert island where a pirate ship crashed years ago, and the ship''s treasure has never been found. The group decides to investigate, and Team Rocket follows to get the treasure for themselves. ', 23, '2013-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 39, 'A Pokémon of a Different Color!', 'On Cave Island, Ash and his friends meet up with Clair, Gym Leader of Johto''s Blackthorn City, who has come to the island to capture a different-colored Druddigon, but her Dragonite left without her. When they find her Dragonite, Iris''s Dragonite takes an instant dislike to it and the two fight, hampering Clair''s plans to find the different-colored Druddigon on the other side of the island from the port. ', 23, '2013-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 40, 'Celebrating the Hero''s Comet!', 'The appearance of Woodate Comet approaches, so Ash, Iris, Cilan, and Alexa go stake out the ruins where the legendary hero it is named after first spotted it. However, they must deal with several Ghost Pokémon and Team Rocket who are once again trying to capture Pikachu. ', 23, '2013-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 41, 'Go, Go Gogoat!', 'On another island, Ash, Iris, Cilan, and Alexa meet a boy named Tony who touches Alexa''s Gogoat''s horns, causing it to temporarily bond with him. They all help Tony meet his father on the other side of the island. ', 23, '2013-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 42, 'Team Rocket''s Shocking Recruit!', 'After being scolded by Iris, an ambush by Team Rocket starts to make Emolga wish she did not have to be with such strict trainers and fights on Team Rocket''s side. ', 23, '2013-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 43, 'Survival of the Striaton Gym!', 'Chili and Cress meet up with Cilan on Paladin Island as they have both been beaten by a challenger at the Striaton Gym named Morana who exclusively uses Ice-type Pokémon such as Mamoswine and Glalie. It is up to Cilan and Pansage to face off against Morana and her Abomasnow for the honor of the Striaton City Gym. ', 23, '2013-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 44, 'Best Wishes! Until We Meet Again!', 'The group finally reaches the waters off of Kanto, just as Team Rocket once again tries to do their best to take Ash''s Pikachu. ', 23, '2013-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 16), 45, 'The Dream Continues!', 'With Iris and Cilan heading off on their own adventures in Johto, Ash is restless and still wishes to become a Pokémon Master. To that end, Alexa suggests that he travel with her back to her home in the Kalos region just as Team Rocket hatches another plan to steal Pikachu. ', 23, '2013-09-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 17, 'XY', 'It’s time for Ash and Pikachu to set off on their adventures in the Kalos region! Along the way, they’re joined by some new friends—a genius inventor named Clemont, his little sister Bonnie, and Serena, a Trainer on her first journey. Ash immediately tries to challenge the Gym in Lumiose City, but doesn’t get very far before a robot throws him out! In between Gym battles, Ash and friends will be exploring this unique region, meeting all kinds of new Pokémon, and looking into a fascinating new Pokémon mystery!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 17), 1, 'Kalos, Where Dreams and Adventures Begin!', 'Ash and Pikachu have arrived in the Kalos region, and they waste no time building excitement and adventure to a fever pitch!', 23, '2013-10-17');
