INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 19), 47, 'Till We Compete Again!', 'Our heroes are going their separate ways, and it''s time for goodbyes, fond memories, and eyes to the future!', 23, '2016-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 19), 48, 'The Legend of X, Y, and Z!', 'A trip to some newly discovered ruins in Kalos reveals a rich history of compassion and caring from three Legendary Pokémon!', 23, '2016-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 19), 49, 'The Strongest Duo! Citron and Dent!!', 'Citron visits Kalos to sight-see and enters a fishing competition. Dent uses a fishing machine. Citron calls it deplorable and dismisses him as ignorant. Although unimpressed with his company, Citron agrees to being shown around Lumiose.', 23, '2016-11-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 20, 'Sun & Moon', 'What starts as a summer vacation in the tropical Alola region turns into the next exciting chapter in Ash Ketchum’s quest to become a Pokémon Master! There’s plenty for Ash and Pikachu to explore in this sunny new region, with exciting new Pokémon to discover and interesting people to learn from along the way—including the cool Professor Kukui and the fun-loving Samson Oak. More new faces will help guide Ash’s Alolan adventure, in the form of a group of skilled Trainers—Kiawe, Lana, Mallow, and Sophocles—and a mysterious research assistant called Lillie. Frequent foes Team Rocket have also made the trip to Alola, looking to swipe some high-powered new Pokémon. But they have some heavy competition on the villainy front: the ruffians of Team Skull, who delight in causing chaos and may have more sinister intentions…');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 1, 'Alola to New Adventure!', 'What begins as a vacation for our hero on Melemele Island in the Alola region turns into the promise of many, many exciting adventures to come!', 23, '2016-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 2, 'The Guardian''s Challenge!', 'Ash and Pikachu are adjusting to life in the Alola region-and it''s about to give them a powerful push in a new direction!', 23, '2016-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 3, 'Loading the Dex!', 'Ash''s journey in the Alola region is just getting under way, and our hero has a new partner to share it with!', 23, '2016-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 4, 'First Catch in Alola, Ketchum-Style!', 'Ash is after his first Pokémon in the Alola region, and the adventure that ensues is typical Ash!', 23, '2016-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 5, 'Yo, Ho, Ho! Go, Popplio!', 'Ash''s Pokémon class is off to the sea for some fishing, but Team Rocket has a completely different kind of fishing in mind!', 23, '2016-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 6, 'A Shocking Grocery Run!', 'Ash''s first day off from Pokémon School was supposed to be a relaxing break, but things don''t go quite as expected!', 23, '2016-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 7, 'That''s Why the Litten is a Scamp!', 'A feisty Litten is determined to steal food from others, and Ash and Pikachu are determined to find out why!', 23, '2016-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 8, 'Lillie''s Egg-xhilarating Challenge!', 'Lillie has a Pokémon Egg to care for until it hatches, but will fear get in her way?', 23, '2016-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 9, 'To Top a Totem!', 'Ash wants a new Z-Crystal, but he must face some formidable tasks first!', 23, '2017-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 10, 'Trial and Tribulation!', 'The Melemele Island grand trial is imminent, and Ash must square off against the power and wisdom of Kahuna Hala!', 23, '2017-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 11, 'Young Kiawe Had a Farm!', 'Ash has time off from school for training, but a fellow student''s activities away from school have our hero wanting to find out all about it!', 23, '2017-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 12, 'The Sun, the Scare, the Secret Lair!', 'Professor Kukui takes Ash and the other students for a special lesson at the beach, where they come across a bunch of Mareanie. One Mareanie causes trouble for Ash and his Pokémon when it decides to help Team Rocket (and especially James), who are under pressure from their boss to catch new Pokémon in the Alola region.', 23, '2017-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 13, 'Racing to a Big Event!', 'Mallow tells Ash about the Great Alola Pancake Race and suggests that he join in. Ash agrees and finds his main rival to be the Pancake shop owner, who has an Alolan Raichu. During the race, Team Rocket, who want the grand prize of a year''s supply of free pancakes, enter both Mimikyu and a mechanical Bewear powered by Meowth and Wobbuffet; Mimikyu is disqualified for using a Pokémon attack against Pikachu and the mechanical Bewear later self-destructs, and Team Rocket is carried off once again by the real Bewear. The Principal''s Komala wins the race at the last second. Later at the Pokémon School, Lillie''s egg begins to hatch!', 23, '2017-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 14, 'Getting to Know You!', 'Lillie''s egg hatches into an Alolan Vulpix, which she had named "Snowy" in the previous episode, and their principal''s egg into a normal Vulpix. The fire-type Vulpix starts playing with Pikachu, Togedemaru, Popplio and the others, while Snowy (an ice-type) ignores the others. Finally, it decides to accept Lillie as its trainer and gets caught in Lillie''s Pokéball by itself. Lillie decides to spend some time alone with her newfound partner and takes a walk with Snowy. Team Rocket starts following them and soon corners Lillie and Snowy. Though Lillie tries to put up a fight when Snowy uses Powder Snow, Team Rocket dominates her in battle. She and Snowy are saved by Ash and Mallow. Lillie finally learns to touch a Pokémon for the first time, even though this is exclusively for Snowy at this moment.', 23, '2017-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 15, 'Rocking Clawmark Hill!', 'Ash and Professor Kukui notice that the Rockruff that lives with Professor Kukui is disappearing at night and returning the next morning badly injured. Following it, they find out that Rockruff is participating in a secret Pokémon training ground. Ash decides to help Rockruff train. Rockruff learns to use Rock Throw. After Rockruff defeats a Magmar that previously defeated it, Professor Kukui decides to leave Rockruff in Ash''s care and Ash catches Rockruff.', 23, '2017-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 16, 'They Might Not Be Giants!', 'While training on a beach, Lana''s Popplio and Ash''s Rowlet are caught inside one of Popplio''s balloons, which is blown away by a strong wind. Rowlet bursts the balloon open, and they both crash into Team Rocket''s secret base. Meowth and Mareanie chase after them, but they are rescued by Litten. While Ash, Lana, and Mallow search for the missing pair, Litten takes them to where it has been staying with the old Stoutland. Stoutland asks Litten to help them find their trainers; however, Team Rocket is also hunting them. Who will find Litten and the lost Pokémon pair first?', 23, '2017-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 17, 'Crystal-Clear Sleuthing!', 'Ash''s Electrium Z-crystal is missing. Rotom, who is a big fan of an Alolan detective TV show, is prompted to try and find it with Pikachu as his assistant. In the meantime, Ash and the other students are all desperate to keep Kiawe, the only other Z-ring wearer, from finding out about the missing Z-crystal out of fear of his anger. However, the solution to the case may be even more surprising than anyone thinks. Rotom gets a new video camera function.', 23, '2017-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 18, 'A Seasoned Search!', 'Mallow invites her classmates to her restaurant to taste her version of Alola''s legendary stew; unfortunately, her use of Pikachu''s electric shock to cook it doesn''t go over so well. It turns out that she is missing an important ingredient: the rare Saffron honey, so Ash and Pikachu decide to help Mallow gather some honey. Their plan is to use an Oricorio to find it, but finding one is not so easy. Meanwhile, Ash''s Rowlet seems to have developed feelings for Mallow''s Bounsweet, but the feelings are not reciprocated. Team Rocket turns up once again, but this time instead of stealing Pikachu they plan to steal the Saffron honey. However, their interference causes Bounsweet to evolve into a Steenee with a devastating slap attack.', 23, '2017-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 19, 'A Guardian Rematch!', 'Ash needs to begin training for a possible rematch against Tapu Koko. Sophocles helps out with scientific methods that yields surprising results. Naturally, this arouses Tapu Koko''s interest. Tapu Koko challenges Ash and Pikachu with the whole Pokémon school looking on. Are Ash and Pikachu strong enough with the Electrium Z-Crystal power to withstand the Island Guardian''s powerful attacks?', 23, '2017-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 20, 'Partner Promises!', 'On the advice of a local shopkeeper, Ash and Pikachi (partly to escape being dragged along on the girls'' shopping spree) kayak to nearby Treasure Island, where there are lots of wild Pokémon. After watching a group of Crabrawler, following an Cutiefly to a meadow full of friendly bug Pokémon and having fun with a group of Alolan Exeggutor, they are overrun by a school of Wimpod who try to steal their snacks. Preparing to return home, they find a Wimpod trapped inside a blocked cave. With the help of one of the Exeggutor from earlier, they manage to reach and free Wimpod, who thanks Ash before returning to its school. Ash and Pikachu see another Island Guardian, Tapu Lele, who heals Ash''s bruised hands.', 23, '2017-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 21, 'One Journey Ends, Another Begins...', 'Ash and Pikachu run into Litten again, but this time something''s very wrong with its friend the old Stoutland. Ash carries Stoutland to the Pokémon Center, where Ash, Pikachu, and Rotom-Dex learn that Stoutland is dying. Litten and Stoutland escape from the Pokémon Center and return to the riverside, where Stoutland passes away in the night. After realizing what has happened, Litten is heart-broken and refuses to be comforted by anyone. After Litten finally comes to terms with the loss of its friend, Ash asks Litten to join him. Litten decides to test him by battling against Pikachu. When the battle ends in a draw, Litten chooses to become one of Ash''s Pokémon. Team Rocket''s Meowth, who for reasons of his own has been secretly watching everything, seems pleased by the outcome.', 23, '2017-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 22, 'A Shivering Shovel Search!', 'While training Litten, who is having trouble mastering Fire Fang, Ash accidentally incurs the wrath of an unfriendly Sandygast when Rockruff''s Rock Throw knocks the shovel off its head. Ash''s attempt to temporarily replace it with Rotom-Dex only makes things worse. In a rage, Sandygast evolves into Palossand and swallows up Ash and also Litten when it tries to rescue him. With both Litten and Rotom-Dex affected by Palossand''s energy drain, it is now up to the rest of Ash''s classmates to save them. While Kiawe and the others keep Palossand busy, can Pikachu and Popplio find the lost shovel in time?', 23, '2017-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 23, 'Getting the Band Back Together!', 'Ash and his classmates are excited to see DJ Leo, who is a popular local musician that plays music with his Alolan Dugtrio. After an Alolan Diglett that dances joins the group, the Dugtrio start quarreling among themselves as to which of them should take center stage. Amidst the threat of a split-up, Team Rocket steps in to steal Dugtrio.', 23, '2017-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 24, 'Alolan Open House!', 'When the Pokémon School announces a special Visitors Day, Ash''s mother and Mr. Mime come for a visit. Delia charms everyone, including all of Ash''s Alolan Pokémon. Meanwhile, Ash faces one of his toughest challenges ever... giving a report in front of his classmates, the school visitors and now his own mother! When the Team Skull grunts crash the festivities on Tauros and start causing mayhem, Delia insists on standing up to them. Can Ash and his Pokémon save the day?', 23, '2017-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 25, 'A Team-on-Team Tussle!', 'When Team Rocket see Ash and Kiawe demonstrating Z-moves, they plot to find Z-crystals for themselves. While searching, Team Rocket run into Team Skull. Both gangs spot a Darkinium Z-crystal embedded in a large rock. Will they be able to work together to get through the infestation of Rattata and Raticate from earlier that are between them and the Z-crystal? If they can, how long will this alliance last? If they can''t, who will get the Z-crystal first and will they be able to use it?', 23, '2017-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 26, 'So Long, Sophocles!', 'Sophocles and his family may be moving away, so Sophocles will have to leave the Pokémon school and all his friends. Even though he tries to keep the news from his classmates, they can see that both he and Togedemaru are very upset. Ash and his friends work together to cheer up Sophocles with a farewell party. However, when Sophocles finds out he''s made a mistake, he finds it very hard to tell his friends.', 23, '2017-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 27, 'A Glaring Rivalry!', 'A trainer named Gladion, dressed in black, battling with a powerful fiery-eyed Lycanroc and wearing a Z-ring, has appeared on Melemele Island. After seeing them in action, Ash naturally wants to battle Gladion; however, he''s totally shocked when Lillie appears and calls Gladion her brother. Gladion seems cold towards Lillie and at first refuses Ash''s challenge, but then learns that Ash got his Z-ring from Tapu Koko and had actually battled the Island Guardian. That night, Gladion''s Umbreon delivers a note to Ash agreeing to battle. It''s Ash''s Rockruff versus Gladion''s Lycanroc! However, Team Rocket, who saw Gladion defeat the Team Skull grunts earlier, can''t resist getting involved. Ash and Gladion must work together to rescue Pikachu and Lycanroc.', 23, '2017-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 28, 'Pulling Out the Pokémon Base Pepper!', 'Grab your bats and mitts: Pokémon Base season is upon us! Ash and friends can’t get enough of the popular sport, especially after watching the final Pro League game, and they’re delighted when Professor Kukui invites a star athlete to visit the Pokémon School for a special lesson. The competition gets fierce when Team Rocket arrives for a game! Get ready for some intense sports action—and the rare sight of Kiawe wearing a shirt!', 23, '2017-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 29, 'Lulled to La-La Land!', 'Students and Pokémon take a camping trip together. After they wake up feeling mysteriously drained, they realize there''s something in the forest.', 23, '2017-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 30, 'The Ol'' Raise and Switch!', 'Ash and his friends switch Pokémon for two days for a class assignment. Ash takes Snowy to his house while Pikachu goes home with Lillie.', 23, '2017-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 31, 'The Island Whisperer!', 'The Akala Island Kahuna, Olivia, comes to the Pokémon School. Ash and the rest of the class head to Akala for a practical class under her supervision.', 23, '2017-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 32, 'Treasure Hunt, Akala Style!', 'For the first class on Akala, Ash and his friends are paired with Stoutlands for a treasure hunt. Lillie and Lana struggle with their partners.', 23, '2017-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 33, 'Big Sky, Small Fry!', 'With no class today, Ash and Lana go fishing, but they may end up catching more than they bargained for since the lagoon they''re fishing in may contain a water-type Totem Pokémon. If there is, then Lana is determined to battle it. Meanwhile, Kiawe takes the rest of the gang to visit his family''s dairy farm, and Team Rocket doesn''t seem to be having much luck with their own fishing.', 23, '2017-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 34, 'A Crowning Moment of Truth!', 'The Wela Fire Festival is just starting to heat up, but someone seems determined to put it out!', 23, '2017-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 35, 'Currying Favor and Flavor!', 'Our heroes are embarking on a mission filled with good taste...and a surprising finish!', 23, '2017-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 36, 'Trials and Determinations!', 'The time for Ash''s grand trial with Olivia is finally here, and it''s no ordinary battle!', 23, '2017-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 37, 'Rising from the Ruins!', 'As if Ash''s victory at his grand trial wasn''t monumental enough, an unexpected transformation makes a memorable field trip even more momentous!', 23, '2017-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 38, 'Mimikyu Unmasked!', 'When Mimikyu faces a fashion problem, Jessie sees a bonding opportunity!', 23, '2017-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 39, 'Mallow and the Forest Teacher!', 'It''s a challenging day for Mallow and her family restaurant, and emotions are running high!', 23, '2017-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 40, 'Balloons, Brionne, and Belligerence!', 'Lana and Popplio are working hard to master their Z-Move, but their progress is soon to grow by leaps and bounds!', 23, '2017-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 41, 'Mounting an Electrifying Charge!', 'Three of our heroes are teaming up for the annual Charjabug race, an electrifying event with shocking results!', 23, '2017-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 42, 'Alola, Kanto!', 'A celebratory Pokémon School class trip turns out to be a reunion no one will ever forget!', 23, '2017-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 20), 43, 'When Regions Collide!', 'The Cerulean Gym is the setting for old and new friends, battling old and new skills!', 23, '2017-09-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 21, 'Sun & Moon: Ultra Adventures', 'When Ash sees the Legendary Pokémon Solgaleo and Lunala in a dream, he makes a promise to them. But when he wakes up, he can’t remember what it was! Will the strange Pokémon called Nebby help jog his memory? Along with their new friend and the rest of the students at the Pokémon School, Ash and Pikachu explore the Aether Foundation, an organization dedicated to Pokémon conservation and care. But it may not be as innocent as it seems, and Ash and his friends will have to work together to protect the people and Pokémon they care about as they face a mysterious power like nothing they have ever seen.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 1, 'A Dream Encounter!', 'After dreaming that he made a promise to the Legendary Pokémon Solgaleo and Lunala, Ash has a hard time waking up. On his way to school, he’s sidetracked by Tapu Koko, who guides him to a strange little Pokémon that looks like a cloud of stars. Lillie nicknames it Nebby, and Ash remembers his dream: he promised to take care of it!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 2, 'Now You See Them, Now You Don''t!', 'The Pokémon School class is sculpting with clay today! But while our heroes muse about various Pokémon and places, they disappear one by one—first appearing at the scenes of their musings, then reappearing back at school! They soon realize Nebby had used Teleport to take them to the places and Pokémon they were thinking about.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 3, 'Deceiving Appearances!', 'Our heroes visit Aether Paradise, part of the Aether Foundation run by Lillie’s mother, Lusamine. An impressive variety of Pokémon live in the conservation area, including a group of Ditto who need their shots! Professor Burnet recruits Ash and friends to help with the vaccinations while Lusamine is busy on the phone, but one of the Ditto escapes and leads our heroes on a merry chase as it keeps transforming. They eventually catch it when it disguises itself as Snowy—and Lillie realizes she can’t touch it!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 4, 'A Masked Warning!', 'When Ash gives Lycanroc a bath, an accidental splash of dirty water unleashes Lycanroc’s surprisingly red-hot temper!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 5, 'Night of a Thousand Poses!', 'Our heroes are having a sleepover at Professor Kukui’s house, and Professor Burnet agrees to join them! Everyone has a good time, but there are a couple of hiccups: during a game of Z-Move poses, Kiawe accidentally unleashes Turtonator’s Inferno Overdrive in the living room, and then Professor Burnet’s Munchlax eats everything she cooked for dinner!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 6, 'Mission: Total Recall!', 'After accidentally seeing Gladion and coming face-to-face with Silvally, Lillie is once again unable to touch Pokémon—but she’s determined to change that! With Nebby’s help, she embarks on a journey to recall the memories behind her fear. But Faba wants none of it, having been responsible for Silvally’s creation in the first place. Vowing to make sure Lillie never remembers her past, Faba captures her, and she’s again filled with fear. But Silvally rescues Lillie, and when she remembers that it was the one who saved her in the past, her fear of touching Pokémon finally vanishes!', 23, '2017-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 7, 'Faba''s Revenge!', 'Lillie can touch Pokémon again! While our heroes celebrate, a disgraced Faba is determined to prove himself to Lusamine by summoning an Ultra Beast—the same one that threatened Lillie years before. He kidnaps Nebby and convinces it to teleport him into his research lab at Aether Paradise.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 8, 'Family Determination!', 'Our heroes are in shock after Lusamine’s disappearance through an Ultra Wormhole, and they want to help get her back. But Gladion insists it’s a family matter, and he and Lillie set out on their own rescue mission. The Pokémon School class still wants to help, though, so Kahuna Hala directs them to the Altar of the Sunne on Poni Island. Meanwhile, nearing the altar, Gladion and Lillie encounter a Totem Kommo-o! With Snowy and Silvally, they defeat the Dragon-type Pokémon. Then, when the siblings rejoin the rest of our heroes, Ash again tries to convince Gladion to let everyone help. And when Lillie agrees, Gladion finally understands…', 23, '2017-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 9, 'Revealing the Stuff of Legend!', 'Our heroes are all gathered at the Altar of the Sunne, along with all four of Alola’s Island Guardians. Lillie and Gladion ask the Island Guardians for help to rescue their mother, Lusamine, who has been taken through an Ultra Wormhole by a mysterious Ultra Beast. After Tapu Koko and the others perform a ritual, little Nebby evolves into the mighty Solgaleo—one of the Legendary Pokémon of Alola!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 10, 'Rescuing the Unwilling!', 'Our heroes have made it through the Ultra Wormhole, but when they find the captured Lusamine, they’re shocked to find she wants nothing to do with them! With an Ultra Beast controlling her mind, it’s up to Lillie, Ash, and friends to rescue her. Their Pokémon spring into action—but so do Lusamine’s Pokémon, who are also under the Ultra Beast’s control. Lillie gathers her courage and reaches out to Clefable, recounting the fun they had together in years past. Her reassuring persistence pays off, and Clefable breaks free of the Ultra Beast’s control. Meanwhile, riding on Solgaleo’s back, Ash presses on to find Lusamine—and the Ultra Beast.', 23, '2017-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 11, '10,000,000 Reasons to Fight!', 'Our heroes are battling hard against a group of mind-controlled Pokémon, and Lusamine is still resisting rescue. When Gladion realizes their attacks won’t stop until the Ultra Beast is defeated, Ash suggests the two of them use Z-Moves.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 12, 'The Professors'' New Adventure!', 'Following their journey through the Ultra Wormhole, our heroes return to the Pokémon School, where Lillie thanks everyone for their help saving her mother. Later, during a walk on the beach, Professor Kukui asks Professor Burnet to marry him! They aren’t planning a wedding ceremony, but our heroes have other ideas...a surprise ceremony awaits!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 13, 'Let Sleeping Pokémon Lie!', 'Our heroes are curious about the origins (and sleep habits) of Principal Samson Oak’s partner Komala. After telling the students how they met, Samson shows off Komala’s impressive skill at battling in its sleep!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 14, 'The Dex Can''t Help It!', 'Rotom Dex is excited to house-sit while Ash and the professors go shopping. But chaos ensues when a washing machine is mistakenly delivered—and there’s a Wash Rotom inside! Somehow, the Wash Rotom ends up inside Ash’s Pokédex, and Rotom Dex takes its place in the washing machine. After a series of accidental form changes, and even some time spent inside a TV, Rotom Dex yearns to be back inside the comfort of the Pokédex. It finally succeeds, but not for long—after a big shock from Pikachu, Rotom Dex accidentally inhabits the entire Pokémon Center!', 23, '2018-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 15, 'Fighting Back The Tears!', 'After a day of shopping, Team Rocket encounters Mareanie’s first love and mentor, a Mareanie that still has feelings for its former protégé. Filled with jealousy, it evolves into a Toxapex and poisons James! In his poisoned stupor, James decides Mareanie should be with Toxapex instead of with him. When Mareanie overhears this, its sadness causes it to run away. But Toxapex can’t bear to see Mareanie cry, and it challenges James to a duel to win Mareanie back. After what turns out to be an underwhelming battle, James is victorious, and Mareanie joyously reunites with him and the rest of Team Rocket!', 23, '2018-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 16, 'Tasting the Bitter with the Sweet!', 'When Harper and Sarah tell Lana that a Pokémon saved them after they got lost in the woods, Mallow remembers the same thing happened to her and Lana when they were younger! The two friends decide it’s time to find this Pokémon, nicknamed Grandpa Forest, and offer it their thanks. Always up for an adventure, Ash and Pikachu tag along, too! Our heroes soon learn that Grandpa Forest must be a Drampa, and when they find its favorite bittersweet Haban Berry trees, they realize they’re on the right track. Then, after a brief scuffle with Team Rocket, Lana and Mallow joyfully reunite with their old friend!', 23, '2018-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 17, 'Getting a Jump on the Competition!', 'The Pokémon School students, Professor Kukui, and Kahuna Hala are visiting Mount Lanakila on Ula’ula Island, where they meet Cerah, a star of the Pokémon Sled Jump event. With the help of her Alolan Ninetales, Cerah introduces our heroes to the sport, and Lillie and Snowy are excited to try it together—even regaining their confidence after crashing during a practice run.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 18, 'A Mission of Ultra Urgency!', 'Lusamine gives our heroes their first assignment as members of the Ultra Guardians: catch an Ultra Beast named Buzzwole, who emerged from an Ultra Wormhole on Melemele Island. Equipped with the latest technology, the Ultra Guardians locate the Pokémon, whose aggressive behavior seems to reflect its anxiety about being in a strange world. Ash and Kiawe notice Buzzwole has a habit of striking heroic poses—so they join right in! With Buzzwole’s guard down, Ash catches it in a Beast Ball, and it’s soon returned to its own world through the reopened Ultra Wormhole. Though our heroes will miss Buzzwole, their first mission as Ultra Guardians is a rousing success!', 23, '2018-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 19, 'Acting True to Form!', 'When Team Rocket encounters an Alolan Meowth, Jessie and James admire its clever demeanor—but our Meowth knows from experience that this lookalike is only looking out for number one! To Meowth’s chagrin, Jessie and James want Alolan Meowth to join Team Rocket, and it even comes up with a plan to catch Pikachu once and for all. But when the plan’s set into motion, Alolan Meowth is nowhere to be found! When it reappears at Team Rocket Headquarters with the Boss, Jessie and James realize they’ve been had. Meowth is filled with jealousy, but he can also breathe a sigh of relief, as things are back to normal again!', 23, '2018-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 20, 'Pushing the Fiery Envelope!', 'The mysterious Masked Royal and his partner Incineroar star in the Battle Royal, an Alolan tradition in which four Pokémon battle until the last one standing is the winner. Ash, watching on TV, can’t wait to get in on the action—and the next day, he gets his chance!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 21, 'Satoshi and Nagetukesaru! Touchdown of Friendship!!', 'Ash takes a trip to the marketplace and meets the local group of Passimians, who have a rivalry with the Akala Island Passimians.  (exists only in Japanese)  Original title: Satoshi and Nagetukesaru! Touchdown of Friendship!!', 23, '2018-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 22, 'Turning Heads and Training Hard!', 'There’s plenty of excitement at the Pokémon School when Ilima, one of its most skilled graduates, returns for a visit. The students have heard plenty of stories of Ilima’s adventures with Eevee, and after sharing those stories with Ash and Lillie, they want to learn if the legends are true. Despite that popularity, though, Ilima’s reappearance has attracted the unwanted attention of Team Skull’s Tupp and his crew of Grunts.', 23, '2018-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 23, 'Smashing with Sketch!', 'Our heroes are learning all about Pokémon Ping-Pong, with Pokémon School graduate Ilima showing them the ins and outs of the game! Ilima plans to compete in an upcoming Pokémon Ping-Pong tournament, where he hopes to settle an old score and defeat Ikari, the winner in previous years. But while Ilima believes that consideration for his Pokémon partner is key to success, Ikari takes a more aggressive strategy. After Ikari berates his partner Mienshao during the heat of the tournament’s final game, the two lose coordination, and Ilima and his partner Smeargle emerge victorious!', 23, '2018-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 24, 'Love at First Twirl!', 'One day during class at the school, an unrecognizable creature comes to Ash and the others. When they notice it, the creature disappears, but for some reason they can no longer see Pikachu around either. It appears Pikachu was taken away by the earlier creature. An agitated Ash starts searching for Pikachu, but suddenly runs into Team Rocket.', 23, '2018-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 25, 'Real Life...Inquire Within!', 'Ash is on his way to the Pokémon Center with Pikachu, Rotom and Poipole for the school''s work experience program when he is stopped by the Team Skull grunts, who challenge him to a battle. The 3-on-1 battle backfires when something goes wrong with Zipp''s Garbodor''s Venom Shock and Team Skull is forced to retreat. At the Center, the Nurse Joy that works there has a bad cold, so Ash and the others decide to do her duties for her. With some minor hiccups (such as a mix-up about Pokémon Center uniforms and an unexpected delivery to Team Rocket''s food truck), things go well, but Zipp keeps showing up, apparently seeking treatment for his Garbodor, who is suffering from Poison Clog. The gang aren''t sure how to help Garbodor, but Nurse Joy appears and takes change of treating Garbodor with their help. By evening, Garbodor has been cured, but the Nurse Joy who treated Garbodor turns out to be a sister of the now-recovered Nurse Joy.', 23, '2018-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 26, 'Rise and Shine, Starship!', 'Sophocles is out camping with his parents and Pokémon at Bamboo Hill when he finds a strange metallic object buried in the ground. Remembering a folktale, he believes it to be the legendary spaceship Celestial Starship. The next day, after he tells his classmates about it, they go there and see it for themselves. After an unsuccessful attempt to dig it up, they return to school, where they are contacted by Lusamine about an Ultra Beast having been detected. Sophocles is surprised to discover that the Pokémon he discovered is a Celesteela, and they determine to return it home. Attempts to catch it in a Beast Ball prove unsuccessful as it is firmly rooted down. Team Rocket attempts to catch Celesteela as the Ultra Guardians try to protect it, and Team Rocket is almost incinerated as Celesteela begins to launch itself. After the Ultra Guardians create a safe launch area, they watch Celesteela fly home.', 23, '2018-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 27, 'The Young Flame Strikes Back!', 'In Kiawe''s farm, a man named Viren appears who comes up with an idea to make a resort hotel by purchasing the farm.', 23, '2018-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 28, 'Dewpider Ascending!', 'On Melemele Island, a wild Dewpider leaves its nest in search of its own pond to call home. Along the way, it gets caught up in confrontations with various Pokémon who don’t take kindly to intruders.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 29, 'Sours for the Sweet!', 'The annual Alola Bread Festival is coming up, and Mallow’s brother Ulu has unexpectedly returned home to enter! When Nina from the pancake restaurant stops by to wish Ulu good luck, he vows to win for her sake. But all his sweet Grepa Berries disappear, so our heroes jump in to help save his entry. Mallow suggests making jelly from sour Grepa Berries, sweetening it, and spreading it on Ulu’s bread. And it works! Ulu’s bread wins first prize…but when he discovers Nina’s already engaged to someone else, he suddenly takes off again on his cooking journey!', 23, '2018-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 30, 'Why Not Give Me a Z-Ring Sometime?', 'After James’s Mareanie masters a Dark-type move, Team Rocket realizes that they can finally take advantage of their Dark-type Z-Crystal. To this end, the Boss sends them to Ula’ula Island to get a Z-Ring from the kahuna—but they accidentally unleash a greedy Gengar who steals their Z-Crystal and kidnaps a girl named Acerola! Team Rocket sets off in pursuit, but can they defeat the ghostly thief? And just what are Gengar’s true intentions?', 23, '2018-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 31, 'Tough Guy Trials!', 'Ash can’t contain his excitement as he arrives on Ula’ula Island for his next grand trial. But Nanu, the island kahuna, has other ideas and leads Ash to believe someone else is the kahuna. To Nanu’s dismay, Acerola blows his cover and convinces him to grant Ash a “pre-trial” battle. Nanu is convinced Ash isn’t ready, and after his Krookodile soundly defeats Ash’s Lycanroc, he seems to prove his point. But Ash never gives up, and he vows to stay on the island and train hard for a rematch!', 23, '2018-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 32, 'Some Kind of Laziness!', 'Thanks to Acerola’s help, Ash arrives at the Ruins of Abundance, home of the Ula’ula Island Guardian Tapu Bulu. Ash wants to train with Tapu Bulu to prepare for his rematch against the Island Kahuna Nanu, and after our hero demonstrates his friendship with his Pokémon, Tapu Bulu springs into action! Showing immense power, the Island Guardian engages Ash and Lycanroc in battle. Lycanroc learns how to use Stone Edge! As the bond between Ash and Lycanroc grows, Tapu Bulu returns to its nap, satisfied that the training session was a success!', 23, '2018-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 33, 'A Battle Hand-Off!', 'Ash has been training hard, preparing for his rematch against Nanu on Ula’ula Island. But when he tells the kahuna he’s ready, Nanu has another idea. Team Rocket has just come looking for the Twerp so Mimikyu can try out its new Z-Move against Pikachu, so Nanu sends him out to battle them instead! Mimikyu proves to be a powerful opponent, but Pikachu overwhelms the opposition with a new move, Electroweb, and the Z-Move 10,000,000 Volt Thunderbolt. Ash wins, setting the stage for his Ula’ula Island grand trial!', 23, '2018-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 34, 'Guiding an Awakening!', 'With his pre-trial successfully behind him, Ash is finally ready to take the Ula’ula Island grand trial against Kahuna Nanu. Our hero is taken aback when Nanu reveals the terms of the challenge, though—Ash must defeat three of Nanu’s Pokémon with only one of his own! Ash decides that Lycanroc is up to the task, but the temperamental Pokémon might have trouble keeping its anger under control...especially when Nanu unleashes a barrage of taunts questioning Ash and Lycanroc’s teamwork.', 23, '2018-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 35, 'Twirling With a Bang!', 'Ash is back on Melemele Island, watching a fireworks display with his Pokémon School classmates. Toward the end of the show, a strange creature starts creating even more fireworks ... by making its own head explode! The next day, Lusamine summons the Ultra Guardians to deal with this Ultra Beast! When our heroes go after it, they discover a second Ultra Beast, and the two creatures face off, flinging fireworks and sparks around so no one can get close. At Ash’s suggestion, the Ultra Guardians stage their own fireworks show, combining their Pokémon’s moves into a gorgeous display that distracts the Ultra Beasts long enough to catch them!', 23, '2018-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 36, 'Showering the World With Love!', 'Ash and his Pokémon School friends visit Hokulani Observatory to view a meteor shower. But these aren’t normal meteors. They’re the space-dwelling Pokémon Minior, crashing to the ground in vast numbers! Guided by Sophocles’s cousin, Molayne, our heroes settle in for a night of making wishes on falling “stars”. When Minior land, they typically burst out of their protective rock shells, filling the evening sky with color and light. This amazing display creates a festive mood, but the celebration seems to bring back sad memories for Sophocles...', 23, '2018-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 37, 'Not Caving Under Pressure!', 'On their way to the ferry back to Melemele Island, our heroes take a shortcut through a cave. They find an area filled with luminescent moss, and Kiawe’s overexcited Marowak starts a commotion that separates everyone into groups. While the others try to find their way out, Lillie, Sophocles, and Mallow discover a group of Alolan Sandshrew in training. The Sandshrew are threatened by a Tyranitar, but Lillie intervenes. She challenges Tyranitar to a Double Battle—and wins with the help of Snowy and the Sandshrew Boss! To show their gratitude, the Sandshrew present Lillie with her very own Icium Z!', 23, '2018-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 38, 'A Young Royal Flame Ignites!', 'Another exciting Battle Royal is under way! It’s the Masked Royal versus the Revengers, a battle team known for their blatant rule-breaking. When they’re about to unleash a sneak attack on Incineroar, Ash’s Torracat charges into the ring with a sneak attack of its own—and "Ash Royal" joins the Masked Royal for a tag-team match against the Revengers’ Electivire and Magmortar! The Revengers’ boss is Viren, the ruthless developer who once threatened Kiawe’s family farm—which means the Battle Royal Dome itself is on the line! But Torracat and Incineroar prove to be a great team, and despite their opponents’ unsavory tactics, the Double Royals win the day!', 23, '2018-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 39, 'All They Want to Do Is Dance, Dance!', 'Professor Kukui has a new assignment for his class: teaching their Pokémon to dance! The students have lots of ideas—and varying degrees of success. While Mallow and Steenee are learning the traditional Alola Hula from Anela in the market, Team Rocket spies on them and makes a plan to crash the performance.  Sure enough, the villains strike, trapping everyone else in a pair of cages. But Steenee eludes capture and springs into action, leaping to the top of one cage and stomping with all its might—until it evolves into Tsareena, whose stronger legs make quick work of Team Rocket’s gadgets!', 23, '2018-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 40, 'Dummy, You Shrunk the Kids!', 'The Pokémon School has a visiting teacher: Faba! When he shows off his invention that can reduce the size of objects for easy storage, it malfunctions, and Ash, Lillie, and Sophocles are shrunk into tiny heroes! Faba recruits Rotom Dex to help him repair the machine, and meanwhile, our heroes are thrown into a world where everything is gigantic. They eventually reunite with Pikachu, who sneezes on them—causing them to return to normal size. But just when Faba thinks he’s fixed his invention, it misfires again…and the result is a towering Togedemaru!', 23, '2018-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 41, 'The Shape of Love to Come!', 'While out shopping, Ash meets a talented artist named Mina, whose partner Ribombee has an amazing power: it can tell what people and Pokémon are feeling! Poipole is fascinated, too, and shows off its own drawing skills to the rest of the Pokémon School class. It’s thrilled to draw symbols representing its love for its “Alolan family,” but after a mysterious dream, its artwork takes on a different, darker tone. Although Poipole’s motivations remain unclear, our heroes reassure it that they’re behind it no matter what! In the meantime, though, the mystery continues to deepen...', 23, '2018-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 42, 'The Long Vault Home!', 'While practicing their vaulting skills during gym class, Ash and friends compete to see who can jump the highest. The next day, an Ultra Beast named Stakataka appears in Alola—and our heroes initially mistake it for a giant vaulting challenge! But they soon realize its true identity, and they spring into action as the Ultra Guardians. After multiple failed attempts to get Stakataka into a Beast Ball, the Ultra Beast finally recognizes that our heroes are trying to help, and it agrees to be caught so it can be returned to its home world. It’s another success for the Ultra Guardians!', 23, '2018-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 43, 'I Choose Paradise!', 'The Ultra Guardians are beside themselves with excitement, as Lusamine has booked them a day at the Pokémon Paradise Resort—and the hardworking Ride Pokémon are tagging along, too! Everyone enjoys the spa’s relaxing amenities, but Team Rocket shows up in disguise with other plans: stealing all the Pokémon they can! Fortunately, the Ride Pokémon have none of it, and they make sure to dash the troublemakers’ ambitions. Our heroes finish their spa day in total luxury, while Team Rocket ends up stuck in the mud with Bewear...', 23, '2018-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 44, 'Filling the Light with Darkness!', 'Professors Kukui and Burnet have a hard time getting up in the morning, and when Ash gets to school, he discovers that the adults in his friends’ lives are in the same boat! The Aether Foundation team has a theory, but they’re exhausted too, so Ash takes charge of the Ultra Guardians (now including Gladion) to investigate.  The culprit seems to be something on the other side of an Ultra Wormhole, draining all the energy from the Ultra Auras. Our heroes track down the wormhole, and they’re excited to see the Legendary Pokémon Lunala emerge—but a mysterious and frightening creature is right on its tail!', 23, '2018-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 45, 'Full Moon and Many Arms!', 'The Ultra Guardians spring into action to protect Lunala from the mysterious creature who has chased it through the Ultra Wormhole! UB Black (as Lusamine later calls it) drains the power from Lunala’s Ultra Aura, then fastens itself onto the Legendary Pokémon to absorb it! Our heroes manage to fight it off with the help of Solgaleo, but the creature turns a similar attack on Solgaleo, absorbing it and escaping through an Ultra Wormhole.  As Lunala recovers its strength, the Ultra Guardians promise to do everything they can to rescue Solgaleo—and the kahunas prepare for a festival celebrating a solar eclipse!', 23, '2018-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 46, 'The Prism Between Light and Darkness!', 'After the mysterious creature known as UB Black absorbs Solgaleo and retreats into an Ultra Wormhole. Ash and his friends give chase and find themselves in Poipole’s original home. There, they meet a giant Pokémon named Naganadel, who tells our heroes of the threat to its world—and how UB Black may be the only hope of saving it!', 23, '2018-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 47, 'Securing the Future!', 'The Ultra Guardians, along with Faba and Professor Kukui, are attempting to return The Blinding One to its original form! As Necrozma in its “UB Black” form, it’s holding Solgaleo captive and threatening Poipole’s home world.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 48, 'A Plethora of Pikachu!', 'Ash, Kiawe, and Mimo discover an amazing place called Pikachu Valley, home to the biggest group of Pikachu they’ve ever seen! Their Trainer is a major pika-fan named Pikala, who gives everyone a set of Pikachu ears and a tail, and insists that they all talk in Pikaspeak by adding “pika” to every sentence.  At first, Ash’s Pikachu seems to be a big hit with the ladies—but Pikala clarifies that they’re just offering their usual pika-greetings. Annoyed by this behavior, the boss Pikachu challenges our buddy to a battle, but Ash’s Pikachu wins—and then thwarts an attempt by Team Rocket to grab the whole group!', 23, '2018-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 21), 49, 'Turning the Other Mask!', 'Everyone is excited when the Masked Royal announces a meet and greet at the mall! But things get complicated when Professor Burnet and Ash want to take Professor Kukui to the event…  Kukui enlists Molayne’s help to switch places and keep his secret. But James and Faba, who are both big fans, catch Molayne “stealing” the royal mask and tie him up. Unfortunately, a rival shows up for a revenge match, forcing Faba to don the mask and take to the ring!  It all works out in the end—Molayne escapes and helps Kukui get his mask back, the rival is defeated, and the Masked Royal’s secret identity is safe!', 23, '2018-10-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 22, 'Sun & Moon: Ultra Legends', 'Ash has completed three of his four grand trials in the Alola region, and more adventures await as he and his classmates acquire new Z-Crystals, make new Pokémon friends, and learn how to Mantine Surf! In their role as Ultra Guardians, the Pokémon School students take on an important mission to protect Wela Volcano. Ash meets a new rival, Hau, whose Dartrix offers Rowlet quite a challenge. Even Rotom Dex gets an adventure of its own when our heroes visit the set of its favorite TV show! And Professor Kukui''s dream of starting a Pokémon League in Alola just might be getting closer to reality...');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 1, 'Lillier and the Staff!', 'Today is the sole performance of the Pokémon School play, and everyone’s so excited! Lillie stars as Lillier, a brave adventurer who is charged with restoring Alola’s lost energy using a staff imbued with the power of Legendary Pokémon. But Act Two takes an unexpected turn, as Jessie, in disguise as Jessa Bergère, crashes the performance to steal the spotlight for herself! After some confusion, Rotom Dex writes a magnificent new script on the fly, bringing the crowd (including Ash’s mom) to applause for a job well done!', 23, '2018-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 2, 'A Haunted House for Everyone!', 'Harper and Sarah are determined to visit a haunted house, but when our heroes are stumped as to where to find one, Acerola suggests they create their own! At first, Shuppet and Mimikins provide ghostly entertainment for the twins, but then several other Ghost-type Pokémon join in on the fun. Everyone gets caught up in what looks like a scary dream, but when Komala strikes the Pokémon School bell, they all wake up and breathe a sigh of relief! Still, Lana is not amused with her sisters’ rambunctious behavior…', 23, '2018-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 3, 'Sparking Confusion!', 'The Ultra Guardians have been summoned to investigate unusual magnetic activity around Wela Volcano, where they discover a group of Alolan Geodude and Alolan Graveler munching on Spark Stones. But our heroes also find a group of rock hunters who are after the Spark Stones for themselves. The Ultra Guardians spring into action…but so does an enraged Alolan Golem, who sends the rock hunters packing! Thanks to the efforts of Sophocles’s friend Metang, the Golem eventually calms down—and it happily joins a group of Hikers who promise to keep watch over the volcano!', 23, '2018-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 4, 'Don''t Ignore the Small Stufful!', 'Ash heads to Aether Paradise to deliver the lunches Professor Burnet and Munchlax forgot at home, and he and Lillie enjoy seeing the Pokémon there. But Team Rocket is there, too, plotting to steal Pokémon while in disguise as Aether Paradise employees. When one of the Pokémon from the conservation area, an adorable Stufful, goes missing, everyone suspects Team Rocket of foul play. But Stufful refuses to leave Team Rocket’s side, and when Bewear appears to whisk them away, everyone learns that Bewear and Stufful are family! This time, Team Rocket’s exit includes a new member of the group: Stufful!', 23, '2018-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 5, 'No Stone Unturned!', 'Hau and his partner Dartrix are training hard for the island challenge when they have a run-in with Ash and Rowlet. When Ash learns that Hau’s grandfather is Kahuna Hala, he challenges his new friend to a battle!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 6, 'Bright Lights, Big Changes!', 'When Rotom Dex catches a continuity error during the filming of Alolan Detective Laki, the cast and crew are so impressed that they invite it to join the show and help Laki solve cases! Ash is thrilled, until he realizes the international shooting schedule means Rotom will have to leave…
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 7, 'We Know Where You''re Going, Eevee!', 'A familiar Eevee has been making its way across the ocean toward Alola, and its journey has been filled with adventure. A series of harrowing encounters—including a brush with Team Skull—has tested its determination, but when it finally finds our heroes, it’s as happy as can be! After forming a bond with Popplio, Eevee’s ready to join Lana’s team…but not before Lana gives it a name: Sandy! Lana and her family are thrilled to get to know her new partner—and Sandy’s excited to get to know them, too!', 23, '2018-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 8, 'Battling the Beast Within!', 'While battling Tapu Koko, Ash and Pikachu suddenly find themselves in an unfamiliar place inhabited by a menacing Ultra Beast known as Guzzlord! Guzzlord’s power is fearsome, but a mysterious man named Dia—accompanied by the Mythical Pokémon Zeraora—comes to our heroes’ aid. Ash wants to help Dia reclaim his home from Guzzlord’s destructive wrath, but after Dia defeats Ash in a test battle, our hero relents. He and Pikachu must return to their own home, but how? Dia offers them shelter for the night, but on the way, they discover an abandoned Pokémon School! What could all of this mean?', 23, '2018-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 9, 'Parallel Friendships!', 'After traveling to an unfamiliar place, Ash encounters the Pokémon School in ruins. The mysterious Dia explains that Ash must be from a parallel world, where the Alola region hasn’t been destroyed.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 10, 'Alola, Alola!', 'As our heroes prepare for a break from Pokémon School, Lana makes a surprise announcement: they have visitors! Who? None other than Misty and Brock! Everyone’s excited to show Ash’s longtime friends around Alola, and when Ash tells them about Treasure Island—a place he and Pikachu previously visited—they’re off! They meet up with a group of Mantine who love to surf, but Team Rocket is determined to make a splash—by catching the Mantine and Pikachu! But they’re no match for our heroes, who shower the trio with a series of attacks that send them blasting off again…just like old times!', 23, '2019-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 11, 'Heart of Fire! Heart of Stone!', 'Brock and Misty are having quite a busy vacation in Alola! Ash and the Pokémon School gang admire Brock’s culinary skills, boosted by delicious ingredients from Kiawe’s family farm. They decide to visit the farm on Akala Island—mostly because Brock has been determined to meet the beautiful Kahuna Olivia!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 12, 'That''s Some Spicy Island Research!', 'The Pokémon School class is visiting Poni Island, and everyone is excited about their upcoming research projects. Ash wants to compete in his fourth grand trial, but because the island currently has no kahuna, he plans to challenge Tapu Fini instead! While searching for the Island Guardian, he meets a Trainer named Hapu, who impresses our hero with her tenacity and battling skills. Although Hapu doesn’t share Ash’s enthusiasm, she respects his determination. And when Team Skull tries to capture a group of Oricorio, she jumps into the fray and defeats the hapless trio with just one hit!', 23, '2019-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 13, 'Showdown on Poni Island!', 'When Hapu learns that Ash wants to battle Tapu Fini for his Poni Island grand trial, she lectures him about the true meaning of a grand trial, and Mudsdale backs it up with a tremendous kick! Ash goes flying and lands near Gladion, who’s also come to challenge the Island Guardian.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 14, 'Evolving Research!', 'As our heroes continue their research projects, Sophocles wants to help Charjabug evolve. The pair set off to Vast Poni Canyon and encounter Horacio, who wants his own Charjabug to evolve first. But when Horacio ends up in danger, Sophocles’s Charjabug springs into rescue mode and evolves into Vikavolt!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 15, 'Run, Heroes, Run!', 'Ash and Kiawe set off to challenge Tapu Fini to a grand trial, but when they get no response, they decide to battle each other to attract its attention. When the battle gets out of hand and starts to damage the surrounding ruins, Ash finds himself trapped in an energy field as punishment, and a mysterious old man tells Kiawe he must return with a scale from Tapu Lele to rescue his friend. Kiawe completes his quest just in time—and when Tapu Fini appears and gives him a Z-Crystal, it becomes clear that this was Kiawe’s grand trial!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 16, 'Memories in the Mist!', 'Get your tissues ready, because this episode of Pokémon the Series: Sun & Moon—Ultra Legends is a real tearjerker. On Poni Island, Hapu tells Ash and friends about a strange mist created by Tapu Fini. When people and Pokémon venture into the fog, they can be temporarily reunited with loved ones who have passed on. Ash, Mallow, and Hapu herself all encounter the mist, and when Lillie and Gladion emerge from it, a shocking revelation sets the stage for an exciting mystery!', 23, '2019-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 17, 'A Grand Debut!', 'Following her standing up to Tapu Fini, Hapu has finally become the Island Kahuna of Poni Island, and Ash challenges her to her Grand Trial. Her trial requires Ash to battle her with just one Pokémon. With Hapu using her Mudsale, Ash and Pikachi face a tough battle. Will they be able to win the Grand Trial and finish Ash''s research project?', 23, '2019-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 18, 'Keeping Your Eyes on the Ball!', 'After their visit to Poni Island, Ash and the gang meet legendary Poké-golfer Kahili, who has been on a losing streak lately, and her partner Touckey (Toucannon). It''s the first time that the gang has seen Poké-Golf, a sport that''s popular in Alola, and are fascinated, so they ask Kahili to teach them how to play. In this version of Golf, both trainer and Pokémon must work together...will they do well and who is this self-proclaimed "Caddie Expert" who keeps butting in?', 23, '2019-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 19, 'Show Me the Metal!', 'Some mysterious and unknown Pokémon have arrived on Melemele Island, and they eat metal! They start wreaking havoc across the island, including eating the tools at the Pokémon School, the equipment in the Ultra Guardians'' headquarters and even James''s precious bottle cap collection. James is enraged and decides to chase down the Pokémon to get his revenge. Just who and what are they and why is one of them hanging around Ash''s Rowlet?', 23, '2019-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 20, 'Got Meltan?', 'Professor Oak has finished his research on the mysterious new Pokémon Ash reported and names the new Pokémon Meltan, a Steel-type. One of the Meltan has grown attached to Ash''s Rowlet and stows away in Ash''s backpack with Rowlet to join them all at the Pokémon School, but after an incident with a Murkrow, it loses its Hex-Nut. Rowlet tries to replace it but nothing he tries seems to work, so he and Meltan head out to find its Hex-Nut. However, they run into Team Rocket, who have found Meltan''s Hex-Nut and are still after all the Meltan. Will Rowlet be able to protect Meltan?', 23, '2019-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 21, 'This Magik Moment!', 'Sophocles is on a TV quiz show, so Ash and the gang come to the station to cheer him on. While there, they see the filming of a series starring a Magikarp; however, the Magikarp seems to have something wrong with it. On another TV show, the regular actresses don''t show up in time, which leads to Lana, Mallow and Lillie being cast as replacements.', 23, '2019-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 22, 'Beauty is Only Crystal Deep!', 'A new Ultra Beast, Pheromosa, has appeared and started attacking trainers and stealing their Z-Crystals. The Ultra Guardians are tasked with stopping Pheromosa. Pheromosa steals Team Rocket''s Z-Crystals, but while trying to stop it Meowth falls in love with Pheromosa. Will anybody be able to stop it before it''s too late?', 23, '2019-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 23, 'The Dealer of Destruction!', 'After much planning, Professor Kukui has finally announced the formation of a Pokémon League in Alola. However, while the rest of Alola (including Team Rocket) celebrates and gets ready, Team Skull''s leader Guzma is enraged and decides that he will destroy the new Pokémon League, and heads over to the Pokémon School to confront Kukui. Before things can get ugly, Ash challenges Guzma to a battle. It''s Pikachu vs. Guzma''s Golisopod; who will win, and why does Guzma hate Kukui so much?', 23, '2019-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 24, 'The Secret Princess!', 'Since their Poni Island experience made them realize that their father Mohn is still alive, Lillie and Gladion return to Aether Paradise and go through their father''s papers, hoping to find some clues. Back at the family mansion, Lusamine shows them Mohn''s old office, where Lillie discovers her father''s old Z-Ring and the inoperative Mythical Pokémon Magearna. Lillie goes to Kahuna Hala and asks for permission to use her father''s Z-Ring, and they have a battle to see if Lillie can master Z-Moves. Will Lillie and Gladion learn anything new about their father''s whereabouts, and what is Magearna''s connection to Mohn and Lillie?', 23, '2019-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 25, 'Drawn with the Wind!', 'Ash and the gang travel to picturesque Malie City on Ula''ula Island. When a strong wind blows Mallow''s hair ornament away, Shaymin chases after it, followed by Sandy and Meltan. Unfortunately, Team Rocket, who are also in Malie City, spots the trio and goes after them to catch them, but our three adventurers aren''t going to let themselves be taken without a fight!', 23, '2019-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 26, 'Aiming for the Top Floor!', 'Having learned about the Kantonian Gym in Malie City from their new friend Charlie Charma, Ash and the gang decide to visit it, but while the gym is supposed to be like a Kanto Gym, the rules are not quite the same: a challenger has to face one of the three Gym Trainers AND Charlie on each floor in a "game" in order to reach the top floor. After only Ash and Kiawe make it to the top floor they find that the "Gym Leader", Dragon-type Trainer Ryuki, has a "rock star" battle style which quickly defeats Kiawe''s Marowak. Rowlet starts off for Ash, but when Meltan jumps in to help its friend, it becomes a double-battle!', 23, '2019-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 27, 'A High-Speed Awakening!', 'Sophocles and Vikavolt are entering a Vikavolt race! When they arrive, Sophocles learns that his rival Horacio is also competing with his newly evolved Vikavolt. The entrants get off to a rousing start, but when Sophocles enters the cave route, his fear of the dark leaves him petrified. Vikavolt offers him support, leading him to realize that if his Pokémon is determined to press on, he can be courageous as well. After an interruption by Team Rocket, the race is back on, and Sophocles wins by a nose! He receives a Buginium Z as a prize, and Hapu follows up by giving him a Z-Ring!', 23, '2019-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 28, 'The One That Didn''t Get Away!', 'The students of the Pokémon School are on a relaxing fishing excursion, but Ash and Lana want to add a little more adventure to their day. The two travel a bit farther out to sea, where they have an unexpected encounter with a very powerful Pokémon! Unfortunately, this Pokémon is also in the sights of some nefarious Pokémon hunters who have no qualms about poisoning Pokémon to make them easier to catch. It’s up to Ash, Lana, and their Pokémon partners to save the day!', 23, '2019-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 29, 'A Recipe for Success!', 'When the Family Restaurant runs out of Big Mushrooms, Mallow visits Oranguru’s place in the forest to ask for more. When she arrives, she finds Meowth looking for some peace and quiet, but the place quickly becomes busy with Pokémon customers. Mallow decides to stay and help Oranguru, and she prepares scrumptious food and drinks for all kinds of Pokémon. When Tapu Koko turns out to be one of those customers, she prepares a special dish for the Island Guardian. Thrilled with its meal, Tapu Koko presents Mallow with a Grassium Z, and Oranguru gives her a Z-Ring! Now all our heroes have Z-Rings of their own!', 23, '2019-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 30, 'Spying for the Big Guy!', 'When Team Rocket receives a call from Headquarters, they come to regret their previous claim to have caught Bewear, as Matori tells them to send the Pokémon to Giovanni right away. But, of course, they haven’t actually caught Bewear—if anything, Bewear has caught them. Panic ensues when Matori arrives in Alola, but Jessie, James, and Meowth convince her that they need Bewear’s help to catch an even more impressive Pokémon. Eventually, Matori changes plans and tries to steal Stufful instead, but a disguised Meowth thwarts her plan by taking the little Pokémon’s place. Then, just in the nick of time, Bewear swoops in to take Meowth back home!', 23, '2019-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 31, 'A Fiery Training Camp Trick!', 'Excitement is building for the upcoming Alola Pokémon League, and the Pokémon School class is ready to train! Ash, Kiawe, and Sophocles decide to camp out at Kiawe’s family farm, but Sophocles is having a hard time working up the confidence to pull off a Z-Move. To help Sophocles train, Kiawe secretly enlists the help of a wild Crawdaunt who previously clashed with Turtonator. Crawdaunt launches a surprise attack on Sophocles, but Sophocles manages to overcome his fear and launch a powerful Z-Move with Vikavolt! The circumstances of the battle may have been unusual, but Sophocles is feeling more confident with a Z-Move at his command!', 23, '2019-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 32, 'Living on the Cutting Edge!', 'Someone’s been slicing and dicing objects all over Melemele Island: a cabbage at Mallow’s Family Restaurant gets chopped up, a golden Viren statue is cut in half, and the trees in Lillie’s yard are shaped into perfect topiaries! These occurrences (and more) are the work of an Ultra Beast named Kartana, who can cut anything with its bladelike body. When the Ultra Guardians ask Kartana to stop its cutting spree, it ignores them—but later it saves the day by demolishing a meteor that’s barreling straight for the Pokémon School! Grateful for Kartana’s help, our heroes bid it farewell as it returns home through an Ultra Wormhole.', 23, '2019-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 33, 'A Timeless Encounter!', 'While Ash and his Pokémon train for the upcoming Alola Pokémon League, they accidentally startle a nearby Celebi. The Mythical Pokémon flees back in time—and brings Ash and Torracat with it! Unaware that he’s in the past, Ash meets a young boy who, unbeknownst to him, is actually a younger Professor Kukui. The boy wants to learn about Pokémon moves, and Ash and Torracat demonstrate some of their skills, even receiving a Firium Z from a Totem Trevenant. But the fun suddenly ends when Celebi transports our hero back to the present day. Ash wonders where the boy went, but he’s also happy to see all his Pokémon again!', 23, '2019-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 34, 'Pikachu''s Exciting Adventure!', 'After returning to the present day, Ash and Torracat reunite with Pikachu, Lycanroc, Rowlet, and Meltan—who are all covered in dirt! It turns out the four Pokémon had been searching for Ash and Torracat after the pair’s sudden disappearance. They’re excited to recap their journey, but Ash doesn’t understand what they’re saying! He has no idea what they went through in order to find him—they even took on the role of Ultra Guardians and got some help from Clefable and Garchomp! Even though he can’t figure out how they got so filthy, our hero is just happy to be back in the company of his Pokémon friends!', 23, '2019-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 35, 'Chasing Memories, Creating Dreams!', 'Professor Kukui has finally realized his dream of establishing the Alola Pokémon League, and he’s excited to welcome everyone to the dedication of the brand-new Manalo Stadium. Much to the excitement of our heroes, he announces that the Champion of the Alola Pokémon League will be granted an exhibition battle with the Masked Royal. Ash and friends are fired up and eager to participate—and Lillie even pulls off her first Z-Move!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 36, 'League Offenders and Defenders!', 'Professor Kukui’s dream of creating an Alola Pokémon League is finally reality! Our heroes are as excited as can be, and everybody wants to participate—even Team Rocket! But there’s someone set on destroying the League and everything it stands for…Guzma, the leader of Team Skull. Full of resentment for Professor Kukui and the teachings of Kahuna Hala, he’s determined to get the last laugh by winning the League, then shutting it down for good! But Ash is having none of that, and he vows to never lose to Guzma. His friends agree—and with that, the League is off to a rousing start!', 23, '2019-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 37, 'Battle Royale 151!', 'The Alola Pokémon League is underway, and it promises to be full of action, drama, and surprises! The qualifying round is a Battle Royal competition among 151 different Trainers, and only the top 16 will make it to the next stage! A free-for-all ensues, with our heroes battling against and alongside friendly rivals like Pikala and Hiroki as well as returning foes like Viren’s cronies and Plumeria from Team Skull. When the dizzying action finally winds down, the entire Pokémon School class, Hau, Gladion, and even a disguised Team Rocket are among those left standing! Now, the question is: who will make it all the way to the top?', 23, '2019-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 38, 'Battling Besties!', 'Now that the Alola Pokémon League’s qualifying round is over, it’s time for the real matches to begin! Ash faces off against the scheming Faba, and crowd favorite Ilima takes on Team Skull’s Boss, the foul-tempered Guzma. But perhaps the most exciting match of the day occurs when Lana and Primarina battle against Mallow and Tsareena. The two may be best friends outside the arena, but that won’t stop them from giving their all during this battle!', 23, '2019-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 39, 'The Battlefield of Truth and Love!', 'As the Alola Pokémon League continues, it’s time to decide on four more competitors to move to the next round! First up is Sophocles and Vikavolt against Mina and Ribombee, and while Ribombee is powerful, it’s no match for Vikavolt’s Signal Beam! Then, it’s a Team Rocket showdown as James and Mareanie take on Jessie and Wobbuffet. The match is close, but James decides to give it his all—and wins! After that, Kiawe and Marowak defeat Acerola and Rapooh in a ghostly clash, and Lillie and Snowy face off against Gladion and Umbreon. Lillie’s skills are impressive, but Gladion still pulls off the win. On to the next round!', 23, '2019-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 40, 'Imitation is the Sincerest Form of Strategy!', 'Rowlet is determined to battle Decidueye in Ash’s Alola Pokémon League quarterfinals match against Hau, but first it needs some additional training. And just in the nick of time, Toucannon and its flock arrive to teach Rowlet a new move! Meanwhile, at Manalo Stadium, Gladion and his Lycanroc defeat James and Mareanie…and then Ash is up next! Rowlet enters the battlefield dressed in a Decidueye costume, which ends up becoming a decoy against the real Decidueye’s Sinister Arrow Raid attack! With Rowlet still standing, how will the rest of the match play out?', 23, '2019-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 41, 'Battling on the Wing!', 'The Alola Pokémon League quarterfinals continue at a lightning pace, and Ash and Rowlet are in the midst of their battle with Hau and Decidueye. The attacks fly furiously—just like the competitors themselves—until it appears that Rowlet is unable to battle. But Hala notices that Rowlet hasn’t lost yet…it’s actually just sleeping! The battle restarts, and after mastering a new move, Rowlet ends up victorious! Then, Kiawe and Charizard face off against Sophocles and Vikavolt, and the latter two successfully pull off a Z-Move—will Charizard be able to escape the devastating attack?', 23, '2019-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 42, 'The Road to the Semifinals!', 'As the Alola Pokémon League quarterfinals rage on, Kiawe and Charizard face off against Sophocles and Vikavolt in the third battle. Both sides show impressive offense and defense, making it clear they’ve trained hard. But Vikavolt’s Wild Charge attack isn’t enough to stop Charizard’s Supersonic Skystrike Z-Move, and Kiawe and Charizard end up on top!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 43, 'The Final Four!', 'We’ve reached the Alola Pokémon League semifinals! Ash is lined up to challenge Team Skull’s Guzma, but first, Kiawe will take on Gladion. Their battle allows each competitor to use two Pokémon, and given the skills possessed by both Trainers, this is going to be an exciting match. Gladion has chosen Lycanroc and Silvally to go up against Kiawe’s Alolan Marowak and Turtonator—four powerful Pokémon that have been trained to win. Lycanroc faces Marowak first, but there’s no way we’re going to spoil the outcome. We will say this, though: it’s an extremely heated battle with a cliffhanger that will leave you eagerly anticipating the next episode!', 23, '2019-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 44, 'Getting Down to the Ire!', 'The battle between Kiawe and Gladion continues, with Turtonator now facing Gladion''s Silvally, but will Kiawe''s Z-move be enough to win the battle? With Ash inspiring both of them, who knows? Then comes the match everyone''s on the edge of their seats for ... another 2-on-2, and it''s Ash vs. Guzma! But Guzma''s supposedly never been defeated! First out for Guzma is Scizor, and Ash chooses Torracat. Just as the battle gets started, Guzma switches out and brings in Golisopod, but when Torracat begins to get the upper hand, Golisopod uses U-Turn to forcibly switch-out with Scizor, who takes major damage, shocking everyone including Guzma! What''s with Golisopod? And just how long can Team Rocket''s robot-Oranguru keep Bewear and Stufful in that hot spring?', 23, '2019-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 45, 'The Wisdom Not to Run!', 'Ash and Guzma’s battle continues in the second half of the Alola Pokémon League semifinals! After the surprising defeat of Guzma’s Scizor, his Golisopod is left to take on Ash’s Torracat. Unfortunately, the exhausted Torracat is quickly defeated, leaving it up to Pikachu to face the powerful Golisopod. During the fierce battle, new details come to light, revealing why Guzma is so determined to bring down Professor Kukui and the Alola Pokémon League. Can Ash and Pikachu overcome this determined adversary?', 23, '2019-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 46, 'Final Rivals!', 'On the night before the finals, Ash''s mom, Mimey, and Professor Oak arrive at Manolo Stadium to cheer for Ash. The wild Meltan also arrive, and with their help, Meltan surprises everyone by evolving into Melmetal! The next day is the ultimate showdown between two strong rivals - Ash vs. Gladion! This time, it''s a 3-on-3 match. For their first Pokémon, Gladion chooses Silvally for his first Pokémon, while Melmetal makes its battle debut for Ash! Unfortunately, Silvally is too strong and Melmetal is quickly defeated. Ash sends in Pikachu, who defeats Silvally. Gladion then sends in Lycanroc... But Ash is shocked when the Lycanroc uses a move that it cannot learn! What''s going on?!', 23, '2019-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 47, 'Enter the Champion!', 'As the Alola Pokémon League races toward the finish line, Gladion and Zoroark unleash the Z-Move Never-Ending Nightmare against Pikachu. But Pikachu stops in its tracks to meet the threat head-on with Breakneck Blitz: a strategy that’s pure Ash! The clash of Z-Moves leaves both Pokémon unable to battle, and Ash and Gladion both respond by sending out their Lycanroc for the final stretch of the match. The two Lycanroc battle to new levels of intensity, ending with a Counter-versus-Counter showdown—and a momentous, hard-earned win for Ash!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 48, 'Z-Move Showdown!', 'Just as Ash is crowned Champion of the Alola Pokémon League, an Ultra Wormhole opens above the stadium, and an angry Guzzlord appears! Ash had battled it previously in a parallel world, so he tells Alola’s island kahunas about the Ultra Beast’s weak spot. But before they know it, two more Guzzlord appear! The kahunas and Pokémon School class leap into Z-Move action to defeat the first two, while Ash, Pikachu, and the Masked Royal reunite with Naganadel—formerly Poipole—and use Gigavolt Havoc to send the third one packing. The resulting explosion blows off the Masked Royal’s mask, revealing his true identity: Professor Kukui!', 23, '2019-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 49, 'Exhibition Unmasked!', 'The Masked Royal is finally unmasked—he’s Professor Kukui! It’s time for the Alola Pokémon League’s exhibition match, and Ash is more excited than ever to battle his mentor in a six-versus-six Full Battle. First up are Torracat and Incineroar, and when Incineroar’s Blast Burn attack pelts Torracat with overwhelming flames, Torracat surprises everyone by absorbing the fire into its own body! But the heat becomes too much for Torracat, and it retreats from battle for the time being. Ash then sends out Lycanroc, who uses a shard from its Stone Edge attack to land a blow on Incineroar. Professor Kukui responds by sending out Braviary—what will happen next?', 23, '2019-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 50, 'A Full Battle Bounty!', 'The Alola Pokémon League’s exhibition match continues with a dizzying array of Pokémon! Braviary manages to defeat Ash’s Lycanroc, and then Rowlet takes down Braviary with a powerful Brave Bird attack. Professor Kukui then calls on Venusaur, who traps Rowlet in its flower! Thanks to Feather Dance, Rowlet escapes unscathed—but then falls to Venusaur’s Sludge Bomb attack. Next up is Torracat’s fiery return to defeat Venusaur, followed by Pikachu versus Empoleon. After a dizzying Whirlpool, Ash switches in Melmetal, who takes down Empoleon but can’t withstand Incineroar’s flames. Each Trainer has three Pokémon still standing as Professor Kukui sends out Lucario, Ash responds with Naganadel, and the battle continues!', 23, '2019-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 51, 'Fiery Surprises!', 'With three Pokémon left on each side during the Alola Pokémon League’s exhibition match, Ash’s Naganadel is up against Professor Kukui’s Lucario. A strategic Dragon Pulse lands another win for Ash—and the first-ever battle victory for Naganadel!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 52, 'From Z to Shining Z!', 'As the Alola Pokémon League’s exhibition match nears its conclusion, Tapu Koko appears—it wants to team up with Professor Kukui and battle Ash! Our hero responds by sending out Naganadel, and the clash of Island Guardian and Ultra Beast powers is an amazing sight. But Tapu Koko manages to overpower Naganadel, so Ash turns to Pikachu, his last Pokémon standing! Tapu Koko raises the stakes as it and Professor Kukui unleash a legendary Z-Move reserved for Island Guardians, but Ash and Pikachu rise to the challenge with their own Z-Move: 10,000,000 Volt Thunderbolt! Once the dust clears, Tapu Koko falls, and Ash and Pikachu are victorious!', 23, '2019-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 53, 'Dreaming of the Sun and Moon!', 'With the Alola Pokémon League behind them, our heroes are deciding how to spend their upcoming vacation! Kiawe is determined to finally have an all-out battle against Ash, while Sophocles is going to take the first steps toward his dream of becoming an astronaut. Lana plans to help her dad with his ocean research, and Mallow wants to create a menu for Pokémon at the Family Restaurant. Meanwhile, Lillie continues her efforts to awaken Magearna…and succeeds! But what about Ash? After receiving some wise advice from Olivia, he decides to explore the world—first stop, Pallet Town!', 23, '2019-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 22), 54, 'Thank You, Alola! The Journey Continues!', 'As their vacation approaches, our heroes’ plans move closer to reality! Kiawe has decided to assist Olivia with her kahuna duties, while Lana, Mallow, and Sophocles continue to work toward their own goals. Now that Magearna is awake, Lillie and her family are setting out to find Mohn, and Ash is embarking on a new adventure of his own—he wants to see new places and meet new Pokémon! The Pokémon School class, Professor Kukui, and Professor Burnet are sad to see him leave Alola, but they wish him all the best for the future. And with Team Rocket also departing Alola, just what might that future hold?', 23, '2019-11-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')), 23, 'Journeys', 'Pokémon Trainer Ash Ketchum has a new plan: see the world! But first, he and his partner Pikachu are headed to the opening of the Cerise Laboratory, a research facility dedicated to uncovering the mysteries of Pokémon in every region. Ash meets Goh, another boy with boundless curiosity about Pokémon, and both are overjoyed when Professor Cerise asks them to become official research fellows. With Ash as determined as ever to become a Pokémon Master, and Goh aiming to catch one of every Pokémon (including the Mythical Mew), our heroes are in for adventure and excitement as they explore the wide world of Pokémon!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 1, 'Enter Pikachu!', 'Though he''s excited to attend Professor Oak''s Pokémon camp, Ash oversleeps when the day arrives. Newcomer Goh is just as excited — and on time.', 23, '2019-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 2, 'Legend? Go! Friends? Go!', 'Professor Oak invites Ash to the opening ceremony for Professor Cerise''s new lab in Vermilion City. Goh sets out to catch a legendary Pokémon.', 23, '2019-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 3, 'Ivysaur''s Mysterious Tower!', 'Professor Cerise asks Ash and Goh to investigate the sudden appearance of Ivysaur in Vermilion City, but the two researchers disagree on their methods.', 23, '2019-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 4, 'Settling the Scorebunny!', 'Ash and Goh head to the Galar region on assignment. During their stopover, some Pokémon steal Ash''s backpack — with Ash and Goh''s train tickets inside!', 23, '2019-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 5, 'Mind-Boggling Dynamax!', 'Once they get off the train, Ash and Goh set out on the hunt for Dynamax Pokémon. Meanwhile, a Scorbunny is hot on their trail.', 23, '2019-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 6, 'Working My Way Back to Mew!', 'After learning more about the Pokédex functions on their Rotom Phones from Professor Cerise, Ash and Goh head out to catch some local Pokémon.', 23, '2019-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 7, 'Serving Up the Flute Cup!', 'Ash and Goh travel to the Hoenn region, where Ash has entered Goh into the Battle Frontier Flute Cup. Their first opponents are Hodge and his Hariyama.', 23, '2019-12-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 8, 'The Sinnoh Iceberg Race!', 'The internet is full of reports that legendary Pokémon Ho-Oh has been seen in the Johto region. The researchers head to Ecruteak City to check it out.', 23, '2020-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 9, 'Finding a Legend!', 'The internet is full of reports that legendary Pokémon Ho-Oh has been seen in the Johto region. The researchers head to Ecruteak City to check it out.', 23, '2020-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 10, 'A Test in Paradise!', 'After a ship''s captain reports being saved by a Dragonite, Goh and Ash set out in search of the Dragonite island that they believe exists ... somewhere.', 23, '2020-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 11, 'Best Friend... Worst Nightmare!', 'While the laboratory staff deal with a mysterious power outage, Chloe contemplates her future and her relationship with Pokémon.', 23, '2020-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 12, 'Flash of the Titans!', 'Professor Cerise gives Ash and Goh tickets to the World Coronation Series finals in the Galar region, where the strongest trainers battle for glory!', 23, '2020-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 13, 'The Climb to Be the Very Best!', 'When a Gigantamax Drednaw interrupts the World Coronation finals in pursuit of Team Rocket, Ash, Goh and their Pokémon spring into action!', 23, '2020-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 14, 'Raid Battle in the Ruins!', 'Ash and Goh travel to the Unova region, where they head to the newly discovered Ruins of the Titan site at Desert Resort to search for Pokémon.', 23, '2020-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 15, 'A Snow Day for Searching!', 'After snow in Vermilion City forces Professor Cerise to shut down the lab for system maintenance, Goh heads home for a few days to visit his family.', 23, '2020-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 23), 16, 'A Chilling Curse!', 'Gengar''s hauntings at the lab resume. Ash and Goh vow to capture the poltergeist Pokémon, and Professor Cerise explains the lab''s paranormal history.', 23, '2020-03-08');
