INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 16, 'Radio Lulled the Mischievous Stars!', 'To drum up more support for Team Rocket, Jessie and James take over a radio broadcast and win over some unexpected fans.', 23, '2022-04-15');
