INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 18, 'Catching the Aura of Fate!', 'Hoping to help his Lucario grow stronger, Ash heads to the Kalos region to reconnect with Greninja, who teaches its protégé a thing or two.', 23, '2022-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 19, 'Aim for the Eight!', 'Ash must survive an entrance battle with a popular trainer to earn a spot in the top eight. But in the arena, all eyes are on the underdog from Kanto.', 23, '2022-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 20, 'Narrowing the Chaser Chase!', 'On his next trial mission for Project Mew, Goh must win a survival contest in Sea Mauville or he won''t qualify as one of the chosen three Chasers.', 23, '2022-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 21, 'The Homecoming Crown!', 'In a frozen land, Ash, Goh and Chloe search for a rare Pokémon while Lillie and her family hope to reunite with their missing father.', 23, '2022-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 22, 'Helping the Hometown Hero!', 'Back in the Alola region, Ash joins a Battle Royal with three other trainers. But when any team can attack any Pokémon, who will survive?', 23, '2022-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 23, 'Chasing to the Finish!', 'Goh competes in his final trial mission for Project Mew: capturing a Regieleki and Regidrago. Will he receive enough tokens to earn the title of Chaser?', 23, '2022-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 24, 'Friends, Rivals, Lend Me Your Spirit!', 'To prepare for the Masters Eight Tournament, Ash reunites with his many Pokémon partners to battle an old rival and get as strong as possible.', 23, '2022-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 25, 'Curtain Up! Fight the Fights!', 'The Pokémon World Coronation Series Masters Eight Tournament is underway! Ash arrives at Wyndon Stadium just in time for a battle between Leon and Alain.', 23, '2022-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 26, 'Pride of a Champion!', 'At the Masters Eight Tournament, Ash, Goh and their new friend Hop watch as Lance goes head to head with Diantha on the stage of dreams.', 23, '2022-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 27, 'The Fiery Road to Mastership!', 'Ash and his friends cheer on Cynthia and Iris in the third battle of the Masters Eight Tournament. With only one match left, will Ash''s training pay off?', 23, '2022-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 28, 'Battling as Hard as Stone!', 'Ash battles Steven Stone in the Masters Eight Tournament. But can the Alola region champion prove he belongs on the same stage as the toughest trainers?', 23, '2022-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 29, 'Koharu and Eievui - The Miracle of Evolution', 'Barrierd has launched the so-called "Barri Channel" in order to shed light on the seven wonders of the Sakuragi Laboratories! What it''s going to shed light on this time is Koharu''s non-evolving Eievui?! Can it solve the mystery of this Eievui?! In addition, the radio show "You Are Swift Radio" is soliciting listeners to submit their problems?!', 23, '2022-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 30, 'Infinite Possibilities!', 'On a camping trip with her family, Chloe encounters friends from her father''s past who help guide her in her decision whether or not to evolve Eevee.', 23, '2022-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 31, 'The Climax Begins! Satoshi''s Masters Tournament Experience!!', 'The Pokémon World Championships semifinals are starting any minute now! But first, PWCS News will bring us an exclusive, thorough analysis of the Masters Tournament! They''ll present all kinds of material ranging from analyses of the various competitors to confidential information on them! In addition, the radio show "A Dragon Dive Into Your Hearts" will present letters from its listeners!', 23, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 32, 'It''s... Champion Time! (1)', 'On the morning of Leon and Diantha''s battle, Ash and Cynthia run into two young fans who are full of questions about selecting Pokémon partners.', 23, '2022-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 33, 'Bewitch, Battle, and Bewilder! (2)', 'In the semifinals, the Sinnoh region champion Cynthia battles the very first Alola region champion Ash for the chance to take on the undefeated Leon.', 23, '2022-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 34, 'Valor: A Strategic Part of Battling! (3)', 'As the epic battle continues, underdog Ash struggles to keep up with champion Cynthia''s aggressive strategy — but he won''t go down without a fight.', 23, '2022-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 35, 'Whittle While You Work! (4)', 'The battle rages on, but Ash is down to his last Pokémon: Lucario. Can the power of their bond see them through to a victory over the Sinnoh champion?', 23, '2022-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 36, 'GO FOR DREAM! Go''s Road to Mew!!', 'A suspicious shadow is sneaking up on Go''s Smartphone Rotom in the hotel room he and Satoshi are staying at in Shoot City in the Galar region... We''ll be shedding light on the info on Go''s Pokémon and the top secret data on Project Mew contained within?! In addition, the radio show "A Blaze Kick After School" will be doing a special on childhood friends!!', 23, '2022-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 37, 'Just a Scone''s Throw from Here!', 'On the eve of the finals, Ash and Goh enjoy a day off in town and run into a group of Nickit who''ve become popular for teaching other Pokémon to behave.', 23, '2022-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 38, 'Climax! The Night Before the Decisive Battle! Satoshi VS Dande!!', 'It''s time for the Masters Tournament Finals, which will determine who''s the best in the world, and PWCS News is doing a special that will present the finals the world is eagerly awaiting in greater detail than anywhere else! The special will provide a thorough coverage of not only highlights of Satoshi and Dande''s battles, but also of the various encounters between the two! In addition, the special has obtained some exclusive news it''s going to break?!', 23, '2022-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 39, 'A Flood of Torrential Gains! (1)', 'While Goh answers an emergency call from Project Mew, Ash heads into the finals of the Masters Eight Tournament, where Leon requests a full power battle.', 23, '2022-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 40, 'Toying with Your Motions! (2)', 'With each competitor down to their final five Pokémon, the battle wages. Ash fights to get an advantage over Leon, who effortlessly sets the pace.', 23, '2022-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 41, 'Paring Pokémon While Parrying! (3)', 'The fierce battle to determine who the strongest trainer is continues. Will Ash manage to see himself through to the ultimate victory?', 23, '2022-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 42, 'Partners in Time! (4)', 'The mysterious appearance of a legendary Eternatus above Wyndon Stadium grants Ash and Leon a bonus round, where it comes down to partner versus partner.', 23, '2022-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 43, 'The Mew from Here!', 'After picking up psychic energy signals, the Chasers set out to scale treacherous Table Mountain in search of Mew... but find surprises along the way.', 23, '2022-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 44, 'In the Palms of Our Hands!', 'On Faraway Island, the Chasers make a startling discovery and find themselves transported to a mysterious realm, where Goh connects with an old friend.', 23, '2022-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 45, 'Heroes Unite!', 'Goh has a new ambition to become a trainer worthy of partnering with Mew — but he''s not sure how to broach the topic while camping with Ash and Chloe.', 23, '2022-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 46, 'This Could Be the Start of Something Big!', 'An epic battle with a legendary Pokémon reignites the fire in both Ash and Goh''s hearts. But before they set out on new journeys, they must say goodbye.', 23, '2022-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 47, 'The Road Most Traveled!', 'While walking through the woods, Ash takes a random path that leads him to exciting encounters with many different types of Pokémon — and enemies.', 24, '2023-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 48, 'A Fated Face-Off!', 'Misty believes she''s connected to a wild Clauncher by fate. Ash thinks his Corphish called dibs on it first. The only solution? A fishing battle!', 23, '2023-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 49, 'Must Be Our Heroes and the Witch!', 'To cheer up a heartsick Brock, Ash and his friends take him to a nearby flower field, where he gets lost chasing after a tricky Psychic-type Pokémon.', 23, '2023-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 50, 'Bearing Down Easy!', 'On a snowy mountaintop, Ash and the team try to help a gloomy Beartic by encouraging it to regain control of its ice powers.', 23, '2023-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 51, 'A Squad''s Worth of Passion!', 'Ash and friends decide to cheer on their old pal Squirtle at the Firefighting Squad Show, but the famous Pokémon''s managers won''t let the group say hi.', 23, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 52, 'The Same Moon, Now and Forever!', 'When Team Rocket causes Pikachu to get separated from the rest of his group, Ash relies on their strong connection to track down his best friend.', 23, '2023-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 53, 'Ride, Lapras, Ride!', 'A friendly Lapras takes Ash to a remote island, where a fellow Water-type needs the trainer''s help. But Ash can''t rescue the trapped Pokémon alone.', 23, '2023-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 54, 'Getting to the Heart of It All!', 'When a supernatural entity starts stealing heart-shaped objects from houses in a small town, Ash, Brock and Misty team up to solve the mystery.', 23, '2023-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 55, 'Rocket Revengers!', 'Team Rocket goes on a revenge mission to capture more Pokémon for their boss. The first step? Sending a Mime Jr. to gain Pikachu''s trust.', 23, '2023-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 56, 'Ash and Latios!', 'Latias takes Ash on a journey to figure out what happened to Latios. But rescuing the legendary Pokémon becomes a bigger battle than they bargained for.', 23, '2023-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0168366')) AND numero_temporada = 25), 57, 'The Rainbow and the Pokémon Master!', 'As the group splits up, Ash and Pikachu return to Pallet Town, where they get some much-needed relaxation — before Team Rocket shows up.', 23, '2023-03-24');
