INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0200276', 'The West Wing', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0592808'), 'SERIE', 'Follows US president Josiah Bartlet and his administration as they tackle various political issues in order to maintain peace and harmony in the nation.', '1999-01-01', 'https://m.media-amazon.com/images/M/MV5BY2I2Mzc0YjItN2I3MS00NjNjLWE5OWUtYmQzMjkxZjIwOGY5XkEyXkFqcGc@._V1_.jpg');
