INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 1, 'Death Has a Shadow', 'After Peter heavily drinks at a bachelor party, even though he told Lois he would not, he gets fired from his job at the Happy-go-Lucky toy factory for being hung over. Peter soon applies for welfare, but after a mix-up, gets sent a check for $150,000. Eventually, Lois finds out, and Peter decides to return the money by dumping it from a blimp at the Super Bowl. He is arrested as a result, and his family ends up coming to his rescue.', 23, '1999-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 2, 'I Never Met the Dead Man', 'While teaching Meg to drive, Peter crashes into the town satellite dish, which knocks out the city''s cable. He promises Meg that if she takes the blame, he''ll get her a car. Without TV, Peter goes crazy, which drives the family insane. Meanwhile, after refusing to eat the broccoli that Lois gives him, Stewie attempts to build a weather control device that would destroy all vegetables.', 23, '1999-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 3, 'Chitty Chitty Death Bang', 'Peter Allows Meg to go to a party with her new friend. This angers Lois because its the same day as Stewie''s birthday. What Meg doesn''t know is that she''s actually attending a cult meeting. Peter comes to pick up Meg, when the Cult Leader follows. Stewie believes him to be the "Man in White", trying to return him to the womb.', 23, '1999-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 4, 'Mind Over Murder', 'At Chris'' soccer game, Peter gets into a fight with a woman, that he thought was a man, and punches her in the face.  After being placed under house arrest, Peter becomes restless and ends up turning the basement into a full bar.  Lois begins singing each night and becomes the main attraction.  Meanwhile, Stewie creates a time machine in order to avoid teething pain, but ends up taking back much more than that.', 23, '1999-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 5, 'A Hero Sits Next Door', 'When the Griffin Family gets new neighbors that move in next door, Lois quickly becomes friends with Bonnie, Meg soon becomes attracted to their son, Kevin, and Peter becomes annoyed by the entire situation.  After Peter injures the best player on his company''s baseball team, Mr. Weed forces him to find a replacement, so Peter quickly changes his mind about his neighbors and invites Joe to play.  When Joe shows up at the game, Peter learns that he is in a wheelchair.  Joe ends up being the star of the game, which makes Peter jealous, as he wants to be a hero too.  Peter ends up trying to stop a bank robbery to prove his value, but ends up getting caught up in the whole situation.', 23, '1999-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 6, 'The Son Also Draws', 'Chris loses interest in being a youth scout, as he would rather pursue drawing and art instead. The Scout Master then kicks Chris out of the scouts. Peter then takes the family to the Big Apple to try to get Chris reinstated back into the scouts. After Peter takes a wrong turn on the way, the family ends up at a Native American casino. Lois then gets obsessed with the slot machines while Peter goes on a vision quest to prove that he has Native American blood in him.', 23, '1999-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 1), 7, 'Brian: Portrait of a Dog', 'When a heat wave hits Quahog, Peter gets Brian to enter a dog show to win $500 so that the family can get a new air conditioner. When they argue over a trick gone bad, Brian walks out on the family and Peter replaces him with a cat. Brian struggles to assert his civil rights and soon ends up at the pound. Luckily, Peter is able to bail him out by bribing the judge.', 23, '1999-05-15');
