INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 2), 2, 'Holy Crap', 'Peter''s very religious father comes to live with the family after he is forced to retire from his lifelong job at the Mill.', 23, '1999-09-30');
