INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 2), 5, 'Love Thy Trophy', 'The Griffins and their neighbors build a festival float; waitress Meg schemes to get bigger tips.', 23, '2000-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 2), 6, 'Death Is a Bitch', 'When Peter tries to get out of paying a doctors bill by faking his own death, he is visited by Death himself, who wants to take Peter away. After Death twists his ankle while chasing Peter, everyone on Earth becomes immortal while death is incapacitated.', 23, '2000-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 2), 7, 'The King Is Dead', 'When Lois become the director of the Quahog Players production of “The King and I” Peter wants a part.  He finds himself in the Producer’s Chair and starts to make some “artistic changes” to the script that involve scantily-clad women and cyborgs.', 23, '2000-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 2), 8, 'I Am Peter, Hear Me Roar', 'Forced to go to a women’s retreat for telling sexist jokes at work, Peter resists the idea at first.  After two weeks, however, Peter becomes a sensitive male.  No one likes the new Peter, especially Lois.  While attending a charity dinner, Lois does something that snaps Peter out of his feminine phase.', 23, '2000-03-28');
