INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 4, 'One If by Clam, Two If by Sea', 'When a hurricane strikes Quohog, everything is destroyed including The Drunken Clam, which is bought out by a Brit who turns it into an English pub. As it happens, pub owner Nigel Pinchley and his family move in next door to the Griffins, and Stewie tries to teach Nigel''s Cockney-accented 3-year-old daughter how to speak proper English.', 23, '2001-08-01');
