INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 12, 'To Love and Die in Dixie', 'The Griffins are put into the witness protection program.', 23, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 13, 'Screwed the Pooch', 'Peter and Lois go to the Pewterschmidts for the weekend, bringing Brian along. Brian, meanwhile, has some "issues" of his own to work out. Find out if Brian''s future is to make puppies or become "less" than he is.', 23, '2001-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 14, 'Peter Griffin: Husband, Father... Brother?', 'While trying to teach Chris about his Irish roots, Peter stumbles upon Nate Griffin, a black man in his family tree.  Peter tries to embrace his new-found heritage, but can’t quite get the hang of it.  When Lois’ father, Carter Pewtershmidt, sits the Griffin kids down for a look at his family genealogy, a dark secret is uncovered.', 23, '2001-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 15, 'Ready, Willing, and Disabled', 'Joe gets discouraged, losing his self-confidence, after he loses a thief in a chase.  Peter wants to help Joe get back to his old self so he volunteers to help train him for the decathlon at the Olympics for handicapped athletes. Peter puts steroids into Joe''s drink, pushing Joe on to victory.  Meanwhile, Stewie, Meg, and Brian fight over $26.', 23, '2001-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 16, 'A Very Special Family Guy Freakin'' Christmas', 'Christmas comes to Quahog!  While Lois attempt to make the holidays perfect for the Griffin family, Peter messes it up.  Meanwhile, Stewie learns of Santa Claus’ ability to keep 24-hour surveillance on all the world’s children.', 23, '2001-12-21');
