INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 18, 'From Method to Madness', 'Stewie attempts a career in show business; Meg dates a nudist.', 23, '2002-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 19, 'Stuck Together, Torn Apart', 'Peter''s jealously forces a trial separation; Stewie and Brian get glued together.', 23, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 20, 'Road to Europe', 'Stewie goes to England to take refuge in his favorite television show, while Lois embarrasses Peter at a KISS concert.', 23, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 21, 'Family Guy Viewer Mail #1', 'Viewer mail inspires three stories in which Peter loses his bones, the Griffins gain superpowers, and Peter and his friends appear as eight-year-old "Little Rascals."', 23, '2002-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 3), 22, 'When You Wish Upon a Weinstein', 'The day that Peter buys volcano insurance is the day that Lois becomes fed up with their constant money problems.', 23, '2004-12-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 1, 'North by North Quahog', 'Peter and Lois decide to go on a second honeymoon. But when Peter crashes the car, he decides to pose as Mel Gibson to stay in his fancy hotel suite, where they find a copy of a "The Passion of the Christ" sequel. They attempt to destroy the film and end up being chased by two priests who went to retrieve the film.', 22, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 2, 'Fast Times at Buddy Cianci Jr. High', 'Brian becomes a substitute teacher at Chris'' school after his teacher wins the lottery. When Brian is moved to teach a class of troubled kids, Chris falls in love with his new teacher, Mrs. Lockhart, who promises to love Chris only if he kills her husband. When Lois finds out, she and Stewie decide to teach Chris a lesson.', 22, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 3, 'Blind Ambition', 'After Mort bowls a perfect game, and Quagmire gets a key to the city by performing CPR, Peter notices he has nothing to be proud of. He then attempts to achieve fame by setting the world''s record for most nickels swallowed. However, a slight miscalculation leaves him blind with nickel poisoning.', 22, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 4, 'Don''t Make Me Over', 'When Meg gets turned down for a date, she asks her family for support. Lois ends up taking her to the mall, where she gets the ultimate makeover. Meanwhile, Peter tries to start a band with the guys, but when their first gig fails, the family ends up performing. Impressed by Meg''s singing, a record producer signs the family, and their travels eventually land them on "Saturday Night Live."', 22, '2005-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 5, 'The Cleveland–Loretta Quagmire', 'When Peter hears Loretta scream, he tries to help out, but discovers Loretta is cheating on Cleveland. Peter figures out that it was Quagmire and decides to tell Cleveland about it. But when Loretta walks out on Cleveland he doesn''t take it lightly.', 22, '2005-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 6, 'Petarded', 'After winning a game of Trivial Pursuit, Peter is convinced he is a genius.  To prove Peter wrong, Brian suggests he take a test of the MacArthur Genius Grant.  The test results say that Peter is technically mentally challenged.  Peter has no problem abusing this handicap until Lois is injured and the kids are taken away because Peter is not mentally fit for parenting.', 23, '2005-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 7, 'Brian the Bachelor', '"The Bachelorette" comes to Quahog and Brian is chosen to be a contestant.  Brian does not like the show, but participates just to have a vacation only to wind up falling in love with the bachelorette.  Meanwhile, Chris gets a nasty pimple on his cheek, which talks to Chris and likes to cause mischief.', 22, '2005-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 8, '8 Simple Rules for Buying My Teenage Daughter', 'Peter runs up his tab at Mort’s Pharmacy.  When he doesn’t have the money to pay, he decides to sell Meg to the Goldmans.  Neil is dating another girl which makes Meg jealous, and Stewie falls in love with Liddane, his new babysitter.', 22, '2005-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 9, 'Breaking Out Is Hard to Do', 'Lois’ kleptomania lands her in jail, leaving the Griffin household in a worse state of disarray than usual.  Peter and the family break her out and end up fugitives in Asian Town.', 22, '2005-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 10, 'Model Misbehavior', 'Lois fulfills a lifelong dream of being a model.  Stewie starts on a multi-level marketing company.  Brian in need of cash to buy his de-worming medication agrees to become his salesman.', 22, '2005-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 11, 'Peter''s Got Woods', 'Peter and Brian’s friendship becomes strained after Brian begins dating one of Meg’s high school teachers.  Peter finds a replacement friend in James Woods, who is visiting Quahog because of a suggestion to rename James Woods High after Dr. Martin Luther King Jr.', 22, '2005-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 12, 'Perfect Castaway', 'When Peter and the guys decide to go fishing, they end up caught in a storm. Stranded on a desert island, their families fear the worst. Rescued by a cruise ship months later, Peter surprises Lois at home, where he finds out that she has a new husband.', 22, '2005-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 13, 'Jungle Love', 'When Chris is supposed to be hazed for a school tradition, he runs off to South America; Peter quickly becomes frustrated by his new job at the beer factory.', 22, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 14, 'PTV', 'After a “wardrobe malfunction” occurs during a live broadcast, the FCC begins to censor all of Peter’s favorite shows.  As a result, Peter creates his own station, PTV, which broadcasts from the Griffin home.  Peter and Brian create their own edgy programming until the FCC shows up to shut down PTV and censor all controversial material in Quahog.', 23, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 15, 'Brian Goes Back to College', 'After writing a story for a local magazine, Brian gets a job at The New Yorker.', 22, '2005-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 16, 'The Courtship of Stewie''s Father', 'Lois thinks Stewie is trying to kill her due to his lack of quality time with his father, so she orders Peter to spend more time with Stewie. Meanwhile Chris starts a friendship with Herbert.', 22, '2005-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 17, 'The Fat Guy Strangler', 'Lois discovers she has a brother named Patrick and takes the family cross-country to meet him.  It turns out; he’s locked up in a mental institution.  Lois thinks he’s sane, so she checks him out to live with the Griffins.  Meanwhile, Peter starts the Society for the Acceptance of Fat Men.  But when all the fat men of Quahog are strangled one-by-one the group lives in fear.  Who could the “Fat Man Strangler” be?', 24, '2005-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 18, 'The Father, the Son, and the Holy Fonz', 'When Peter’s dad comes to visit, he tries to impose his religious beliefs on the family.  But after a mix-up with the holy-water leaves Stewie in a bubble, Peter decides to form a church worshiping his hero, the Fonz.', 22, '2005-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 19, 'Brian Sings and Swings', 'After Brian has a near-death experience in the hospital, he decides to lead a new life. He ends up getting a nightly singing gig with Frank Sinatra Jr., but his new lifestyle doesn''t last very long. Meanwhile, Meg, after joining a new after-school group, pretends to be a lesbian.', 22, '2006-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 20, 'Patriot Games', 'At his high school reunion, Peter tries to impress his fellow classmates. When Peter, heading for the bathroom, charges through the crowd of people, impresses quarterback Tom Brady, who offers Peter a spot on the New England Patriots. Meanwhile, Brian owes Stewie money, after Stewie becomes a sports bookie.', 22, '2006-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 21, 'I Take Thee Quagmire', 'When Peter wins a maid for a week as a prize on a game show, Quagmire gains an interest in her, and they eventually marry. Quagmire, stricken with his bachelor ways, tries to get out of the marriage. Meanwhile, Lois stops breast-feeding Stewie, who, as a result, goes through withdrawals.', 23, '2006-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 22, 'Sibling Rivalry', 'Peter gets a vasectomy and loses all his sex drive. Lois begins to gain weight, and as a result, Peter''s regains his interest in his wife. When Lois'' habits get out of control, she has a heart attack. The surgeon must remove Lois'' fat to reach her heart, returning her to her normal weight. Meanwhile, Stewie''s half-brother Bertram returns to confront him, where they have a war for control over the playground.', 24, '2006-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 23, 'Deep Throats', 'Meg becomes an intern for Mayor West. Brian, who is sure that the mayor is corrupt, tries to out him. Brian and Stewie, while undercover, discover that Meg is more than just an intern. Meanwhile, Peter and Lois go back to their folk singing days at a local talent show. When they begin using drugs, Chris stages an intervention.', 24, '2006-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 24, 'Peterotica', 'After reading an erotic novel, Peter gets the idea to write one himself. Carter gets sued for publishing Peter''s book on tape and loses all his money, where he is forced to become a middle-class citizen. Meanwhile, Stewie tries to train for the Olympics.', 23, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 25, 'You May Now Kiss the... Uh... Guy Who Receives', 'Brian''s gay cousin Jasper visits the Griffin house and announces that he is engaged to his partner and wants to be married at their house.  When Mayor West bans gay marriage in an effort to cover up and bring attention away from a scandal of his own, Brian resorts to hostile actions to try to change the Mayor''s mind.  Lois and Peter question their view towards gay marriage while Chris joins the "Young Republicans" Club to impress a girl.', 22, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 26, 'Petergeist', 'Peter wants to top Joe, who just built a new home theater system, so he starts to build a multiplex in his backyard.  In doing so, he discovers an Indian burial ground.  He finds an Indian chief''s skull and the Griffin house becomes haunted.  Stewie gets sucked into the television and strange events follow as they try to get Stewie back from the poltergeist.', 24, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 27, 'The Griffin Family History', 'When burglars break into the house, the Griffins take cover in the attic where they discover Peter has built a ''panic room''. They go in it, and Peter tells them about his history. They send Meg for food but the burglars catch her. The rest of the Griffins stay behind and Peter accidentally floods the room and they''re going to drown. Luckily Joe gets them out and we find out Meg has been accused of sexual harassment by the burglars.', 24, '2006-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 28, 'Stewie B. Goode', 'After losing at a swim competition, Stewie trys to eliminate his rival by blowing up a lifeguard tower. His plan backfires though, and Stewie has a near death experience that seems to change him.', 22, '2006-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 29, 'Bango Was His Name Oh!', 'Stewie convinces Brian to go on a road trip with him to San Francisco to search for a man Stewie believes is his real father.', 21, '2006-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 4), 30, 'Stu & Stewie''s Excellent Adventure', 'Stewie finds out that his life in the future is miserable. So he decides to go back in time and change events for the better.', 22, '2006-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 1, 'Stewie Loves Lois', 'Stewie becomes obsessed with Lois, after she saves Rupert. Though Lois doesn''t take to the new Stewie all too well. Meanwhile, Peter thinks his doctor is molesting him, when he undergoes a prostate exam.', 22, '2006-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 2, 'Mother Tucker', 'Peter''s mom gets a divorce. Peter feels abandoned until he sees a father figure in his mom''s new boyfriend, Tom Tucker. Meanwhile, Brian gets his own NPR style show on the radio.', 22, '2006-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 3, 'Hell Comes to Quahog', 'After Peter uses Meg''s money to buy himself a tank, she gets a job at the new Superstore in town. However, the Superstore puts all the shops in town out of business and sucks up the city''s power supply. Brian and Stewie team up to save the town from the corporate giant.', 22, '2006-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 4, 'Saving Private Brian', 'Chris is approached to join the military. Brian goes to the recruiting headquarters to voice his opinion, when Stewie signs himself and Brian up for the military. They pass Boot Camp and are shipped to Iraq, where they try to get honorably discharged by doing anything they can. Meanwhile, Chris decides to join a goth band.', 22, '2006-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 5, 'Whistle While Your Wife Works', 'When Peter gets hurt and can''t work, his boss tells him he needs to speed things up. So Lois goes to the brewery to help him out. Meanwhile, Stewie finds out that Brian is dating a very attractive but not very intelligent woman. He tries to get Brian to break up with her, but Brian can''t do it.', 22, '2006-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 6, 'Prick Up Your Ears', 'Lois discovers that Chris has some bad information about sex and she volunteers to teach a sex-ed class at the high school. Some parents become upset with her brutal honesty, and they have her replaced. A conservative christian comes to Quahog and gets rid of the condoms at James Woods High. As a result the kids find an interesting loophole. Meanwhile Stewie, terrified of the Tooth Fairy, decides to set traps to destroy him.', 22, '2006-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 7, 'Chick Cancer', 'Stewie ties the knot with his old flame Olivia, but their relationship quickly turns, and becomes normal dull marriage. It all escalates when they go on a double date with Brian and Jillian. Meanwhile, Lois introduces Peter to chick flicks, so he decides to make his own movie with a plot based on every chick movie ever.', 22, '2006-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 8, 'Barely Legal', 'Meg can''t find a date to her junior prom, and even though he is dating Jillian, Brian ends up going with Meg. At the prom, Brian gets drunk to make the night pass, but ends up making out with Meg. Meg begins to think of Brian as her boyfriend and becomes obsessed with spending every moment with him. Meanwhile, Peter, Cleveland and Quagmire join the police force to help Brian.', 22, '2006-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 9, 'Road to Rupert', 'Brian sells Rupert at a garage sale. Stewie, who is upset with Brian, takes him cross country to Colorado to find his beloved teddy, and ends up having a ski-off to win back Rupert. Meanwhile, Peter loses his license, so Meg has to drive him around.', 22, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 10, 'Peter''s Two Dads', 'After Peters dad, Francis, dies, Thelma tells him that his real father actually lives in Ireland. So Peter and Brian decide to head there in search of his father, who ends up being the town drunk. They decide to play a drinking game to prove his paternity. Meanwhile, Stewie acts out and Lois spanks him. Realizing that he likes being spanked, Stewie does whatever he can to get into trouble.', 22, '2007-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 11, 'The Tan Aquatic with Steve Zissou', 'When a bully harasses Chris, Peter goes to his defense, but ends up beating him up. Peter realizes bullying is fun and begins to bully everyone in the house. Finally, Chris stands up to Peter and beats him senseless. Meanwhile, Stewie goes out without sunscreen and becomes obsessed with getting a tan. After Brian leaves him in the tanning booth for six hours, Stewie gets sunburned and fears he has cancer. While waiting for the results of his cancer screening, Stewie begins to live his life as if he had only days to live and drives Brian crazy with his demands.', 22, '2007-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 12, 'Airport ''07', 'Quagmire takes Peter to work but Peter messes things up, causing Quagmire to lose his job as a pilot. After not being able find another job, Peter and Cleveland make plans to help him get his old job back. When the plan fails, Quagmire receives advice from his idol, Hugh Hefner.', 22, '2007-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 13, 'Bill & Peter''s Bogus Journey', 'Peter helps Bill Clinton with his flat tire, and they soon become friends. They begin spending a lot of time together and Lois begins to believe that Bill inflicting bad influence on Peter. But when she confronts Bill, they end up having sex. Peter, upset that his wife would do this, tries to get back at Lois by having an affair of his own, but soon realizes that he loves her too much to do so. Meanwhile, Lois and Stewie try to potty-train Brian.', 22, '2007-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 14, 'No Meals on Wheels', 'The Griffin family decides to start their own restaurant, though have a hard time attracting customers. After Joe promises to help, Peter is excited at the fact of it becoming a local hangout for the police. However, things don''t really turn out as hoped, and instead it begins to be popular with the handicapped. When Peter attempts to change the place, a sudden twist of irony quickly changes his mind.', 22, '2007-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 15, 'Boys Do Cry', 'Lois gets a job as the church organist, so the family decides to begin going back to church. When Stewie gets sick after receiving communion, the congregation becomes convinced that he has been possessed by the devil. While on the run, the family ends up in Texas, where Peter begins to fit right in with the cowboys, Stewie enters the "Little Miss Texas" pageant, and Chris and Meg sneak into George W. Bush''s house.', 22, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 16, 'No Chris Left Behind', 'After Chris is expelled from school, he is sent to a boarding school that his grandfather Carter attended, but Chris doesn''t exactly fit in. Meanwhile, the chicken returns to pick a fight with Peter.', 22, '2007-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 17, 'It Takes a Village Idiot, and I Married One', 'Lois runs for mayor of Quahog, though she doesn''t become the front-runner until she dumbs down her political views. Once in office, she becomes corrupted with the power that she now holds, and begins accepting bribes so that she can buy herself expensive things. Meanwhile, Peter comes to enjoy being the "first lady" of Quahog, and all of the perks that go along with it.', 22, '2007-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 5), 18, 'Meet the Quagmires', 'Death grants Peter''s wish to go back in time to 1984 when he was 18, but only for one night. He ends up bailing on a date with Lois to hang out with a movie actress. When he returns to the present, he soon realizes that everything is anything but normal, as he is now married to the former actress, and Lois is with Quagmire. Meanwhile, Stewie, Chris and Meg have also taken on Quagmire''s charming characteristics.', 22, '2007-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 1, 'Blue Harvest', 'Peter retells the story of Star Wars in this hour-long episode of Family Guy. When Princess Leia is captured by the evil Darth Vader the droids C-3PO and R2-D2 escape to the planet Tatooine to find help from the Rebel Alliance. There they encounter Luke Skywalker, Han Solo, Chewbacca and Obi-Wan Kenobi who infiltrate the Death Star then rescue the captive princess from the Death Star and return to aid the Rebellion in its fight against the Galactic Empire.', 48, '2007-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 2, 'Movin'' Out (Brian''s Song)', 'Peter convinces Brian to move in with his girlfriend Jillian and Stewie tags along to help pay the rent but he tries to interfere with their relationship. Meanwhile Meg and Chris get jobs at the convenience store where Chris befriends the manager Carl who leaves Meg to do all the work. Carl soon fires her and promotes Chris to the co-boss.', 22, '2007-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 3, 'Believe It or Not, Joe''s Walking on Air', 'When Joe feels that his disability is holding Bonnie back from living a full life, he decides to get a leg transplant. Excited about his new ability to walk, Joe engages in extreme sports, and soon ditches his current friends, for more active ones. Peter and the guys are upset at how Joe is acting and decide to teach him a lesson.', 22, '2007-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 4, 'Stewie Kills Lois (1)', 'Lois and Peter sail off on a cruise. Jealous that he was left behind, Stewie''s matricidal tendencies are rekindled. When Brian challenges him to actually do it, Stewie carries out his diabolical plan.', 21, '2007-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 5, 'Lois Kills Stewie (2)', 'Presumed dead, Lois returns from the wilderness and names Stewie as her killer. On the lookout for Stewie, Joe leads a manhunt around Quahog. Desperate to stop Stewie, Lois realizes what she must do.', 22, '2007-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 6, 'Padre de Familia', 'Peter starts an anti-immigration group after being caught up in the pro-American sentiment at a Veterans'' Day parade, but his tune quickly changes when he finds out he was born in Mexico. Unable to prove his citizenship, pass the naturalization test or convince investigators that his marriage to Lois is for real, he ends up working as a groundskeeper on his father-in-law''s estate and leading the fight for immigrant rights.', 22, '2007-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 7, 'Peter''s Daughter', 'After Quahog is hit by a flood, Meg winds up in the hospital in a coma. When she wakes up and sees a cute med student, they immediately hit it off. Overprotective of his daughter, Peter is determined to drive the med student away. That is until Meg reveals that she is pregnant.', 22, '2007-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 8, 'McStroke', 'Peter decides to grow a mustache, and after being mistaken for a fireman, ends up lending a hand when a fire breaks out at a local fast food restaurant. The owner gives him unlimited burgers as a thank you, but he eats too many and has a stroke. When Peter recovers, he vows to expose the fast-food company for what it really is, becoming friends with a genetically engineered cow along the way.', 22, '2008-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 9, 'Back to the Woods', 'James Woods returns to seek revenge against Peter. James Woods finds Peter''s wallet, which he lost at Barry Manilow concert, and procedes to steal Peter''s identity, and his family. Peter decides to ruin James'' career and image.', 22, '2008-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 10, 'Play It Again, Brian', 'Peter and Lois''s marriage hits a bit of a snag. When Brian wins the New England Rising Writer''s award, the three of them head to Martha''s Vineyard for a nice relaxing vacation. Peter''s usual drinking habits take over, and he soon spirals out of control, as does Brian''s self restraint, as he soon professes his love for Lois. Peter and Brian test their friendship over the woman of their dreams.', 22, '2008-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 11, 'The Former Life of Brian', 'Brian, afraid that he may have lost his last chance at love, searches for a former flame, Tracy. To his surprise, he discovers that he is the father to her son, Dylan. Tracy decides that Brian should raise the boy, and she drops him off at the Griffin''s house. When Dylan runs rough-shot in the house, Brian''s attitude towards parenting doesn''t settle too well with Lois and Peter.', 22, '2008-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 6), 12, 'Long John Peter', 'When Peter gets a pet parrot, he begins acting like a pirate. Peter accidentally kills the bird after raising hell through all of Quahog. Meanwhile, when Brian is visiting the vet, Chris falls in love with the intern, Anna.', 22, '2008-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 1, 'Love Blactually', 'Dissatisfied with his current love life, Brian decides to slow things down when he meets the girl of his dreams, Carolyn. However, Cleveland soon sweeps Carolyn off her feet, and Brian must do anything he can do, to win her back, even if it means involving Cleveland''s ex-wife, Loretta.', 22, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 2, 'I Dream of Jesus', 'When Peter re-discovers his love for the painfully annoying yet seductively catchy tune "Surfin'' Bird," Brian and Stewie decide to take matters into their own hands to ensure that the song will never be heard again! On the verge of tears, Peter goes to every record store in Quahog to track down his beloved jingle, and he runs into a familiar face and ends up hanging out with Jesus Christ.', 22, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 3, 'Road to Germany', 'Mort Goldman accidentally steps into Stewie''s time machine and goes back in time to 1939 Poland, and Brian and Stewie follow to retrieve him. When they find him, the Nazis invade and Mort is taken to Germany, where Stewie and Brian must go to save him, as well as find a way back to the present.', 22, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 4, 'Baby Not On Board', 'Peter gets a lasting supply of gasoline for the year, so the family decides to use it to take a road trip to the Grand Canyon. They pack up and hit the road, but it takes them a while to realize that they had forgotten to bring Stewie with them; when they do, they must make their way home posthaste.', 22, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 5, 'The Man with Two Brians', 'Eight-year-old Brian (who is 56 in dog years) seems to have lost a step or two, so Peter gets a new talking dog, New Brian, to "take some of the load off" the old one, who doesn''t like the idea at all.', 22, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 6, 'Tales of a Third Grade Nothing', 'Peter''s boss Angela sends him back to the third grade so that he can qualify for a work promotion. Meanwhile, Brian, Frank Sinatra Jr. and Stewie open the coolest club in Quahog.', 22, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 7, 'Ocean''s Three and a Half', 'After being pregnant for seven years, Bonnie finally gives birth to a beautiful baby girl named Susie!  Stewie quickly falls for the little tyke and vows to do anything to win her heart and get in her diaper. Meanwhile, Joe borrows $20,000 from a bookie to pay for Bonnie''s medical bills, but then plans to steal the money from Mr. Pewterschmidt to pay his debt.', 22, '2009-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 8, 'Family Gay', 'After buying a brain-damaged horse, which causes over $100,000 worth of damage, Peter participates in medical experiments to make some extra cash. One of the genes he is injected with turns him gay, which later results in him leaving Lois for another man. Although the family is crushed, they quickly realise the most important thing is that Peter is happy.', 22, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 9, 'The Juice Is Loose', 'Peter finds an old winning raffle ticket from 1989 that entitles him a golf outing with O.J. Simpson. After befriending him, Peter brings O.J. home home to meet the family. However, the people of Quahog aren''t too fond of the former running back.', 22, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 10, 'FOX-y Lady', 'Lois gets a job working for FOX News and has to do a report on a liberal filmmaker. However, she loses the job when her story implicates a conservative radio host.', 22, '2009-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 11, 'Not All Dogs Go to Heaven', 'Meg becomes extremely religious, and tries to convert Brian from Atheism. Meanwhile, after the family visits a Star Trek convention, Stewie kidnaps the entire cast of Star Trek: The Next Generation and forces them to hang out with him.', 22, '2009-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 12, '420', 'Brian and Stewie attempt to rally Quahog to try and legalize marijuana.', 22, '2009-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 13, 'Stew-Roids', 'Stewie starts going to the gym with Peter after he gets beaten up by Joe''s baby daughter Susie, but just when it seems that his hard work is paying off, Peter reveals that he''s been giving him anabolic steroid. Meanwhile, Chris begins dating a popular girl at school, only to see her popularity subside.', 22, '2009-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 14, 'We Love You, Conrad', 'When Brian discovers that his beloved Jillian is getting married, he hits the sauce to drown his sorrows. The next morning, he wakes up with more than a hangover. After realizing he has hooked up with "The Hills" star Lauren Conrad, he wants to run and hide. When Brian discovers Lauren is nothing like how she''s portrayed on TV, he thinks he may have found his perfect match – if only he can let Jillian go.', 22, '2009-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 15, 'Three Kings', 'Peter imagines his friends and family in three of Stephen King''s most famous works. Stand by Me parody - Twelve-year old Peter, Quagmire, Cleveland and Joe travel along a railroad track on a journey of self-discovery. Misery parody - Brian is injured in a bad car crash only to be "rescued" by his "number one fan," Stewie. The Shawshank Redemption parody - Cleveland and Peter become fast friends in prison.', 22, '2009-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 7), 16, 'Peter''s Progress', 'Peter learns from a psychic through a palm reading that he had a fascinating past life in the 17th century as Griffin Peterson, a dignified English gentleman who vied for the love of Lady Redbush in the newly founded American colony of Quahog.', 22, '2009-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 1, 'Road to the Multiverse', 'With the help of an out-of-this-world remote control, Stewie and Brian travel through alternate universes, including a post-apocalyptic world and a parallel world run by dogs where humans are pets.', 22, '2009-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 2, 'Family Goy', 'When Lois finds a lump on her breast, she goes to the doctor to test for cancer. The tests come back benign, but the doctor looks at her family medical history and reveals some news about Lois'' heritage.', 22, '2009-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 3, 'Spies Reminiscent of Us', 'Chevy Chase and Dan Aykroyd move to Quahog. Brian and Stewie find out about their secret agency. They are told that there are Russian Sleeper Cells all over US. They go talk to Mayor West, and find out he is one of the sleeper cells. They follow Mayor West to Russia where they disable a nuke aimed at the US.', 22, '2009-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 4, 'Brian''s Got a Brand New Bag', 'When Brian begins dating an older woman, the family begins to make fun of him. After Brian''s new fling breaks her hip, he gets the pleasure of becoming her errand boy.', 22, '2009-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 5, 'Hannah Banana', 'After attending to the concert of a teen superstar, Stewie discovers a surprising secret about the singer. Meanwhile back at home, Chris tries to prove the existence of the Evil Monkey.', 22, '2009-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 6, 'Quagmire''s Baby', 'Father doesn''t know best when Quagmire assumes responsibility for a baby left at his doorstep. Meanwhile, Stewie creates a stupid clone of himself that he uses as a slave. When he ends up creating a clone for Brian too, they find out that the clones are unstable, at which point the clones break down.', 22, '2009-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 7, 'Jerome Is the New Black', 'Peter and the guys interview potential friends to fill the vacancy left by Cleveland. Meanwhile, Brian discovers that Quagmire hates him.', 22, '2009-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 8, 'Dog Gone', 'When Brian accidentally kills another dog, he is surprised to see that no one cares, so he tries to convince everyone that the life of a dog should have the same value as a human one. Meanwhile, Lois hires a maid who doesn’t listen to Peter', 22, '2009-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 9, 'Business Guy', 'When Peter gives Lois’ dad the bachelor party he never had, Mr. Pewterschmidt goes into a coma. Even Dr. House can''t help. Lois gains control of Pewterschmidt Industries which she passes to Peter. He gets power-hungry and fires the board. Mr. Pewterschmidt bounces back and tries to regain control of what he’s built.', 22, '2009-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 10, 'Big Man on Hippocampus', 'When Peter hits his head and suffers amnesia after getting in a fight with Richard Dawson on Family Feud, he forgets everything about his life, including his family and friends. In an attempt to try to bring back his memory, Lois decides to reintroduce Peter to his old self, until he begins to hit on other women, much to Lois''s dismay. She decides to take the kids and leave Peter, giving Quagmire the opportunity to score with Lois. Peter now must prove to Lois he can remember her and make himself worthy of her again.', 22, '2010-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 11, 'Dial Meg for Murder', 'Brian gets a gig writing for a teen magazine about the average American girl, but when he starts trailing Meg for research he discovers that her desperate attempts at dating have led her to a guy in the slammer. When Brian tries to expose Meg’s secret to the family, he finds out that her boyfriend, Luke, has broken out of jail and has been hiding in the Griffin’s house.', 22, '2010-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 12, 'Extra Large Medium', 'When Chris and Stewie go missing for several days, Lois is at her wit''s end until she sees a psychic who assures her they are safe. Even after the boys return home, Lois and Peter''s psychic obsession continues, and Peter takes it a step too far when he starts charging neighbors for his extrasensory perception. Meanwhile, Chris develops a crush on a girl at school.', 22, '2010-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 13, 'Go, Stewie, Go!', 'Stewie cross-dresses in order to star in the American version of Jolly Farm Revue. Meanwhile, Peter makes Lois feel bad about her age.', 22, '2010-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 14, 'Peter-assment', 'After Peter has some luck selling footage of a celebrity he caught off-guard, he decides to become a full-time paparazzo. To make matters worse, his new boss, Angela, finds him irresistible and plagues him with unwanted advances. When Peter rebuffs her, he winds up getting the ax. Meanwhile, Stewie makes his theatrical debut in a school play, only to be overcome with stage fright.', 22, '2010-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 15, 'Brian Griffin''s House of Payne', 'Lois encourages Brian to submit his pilot script to a network. James Woods gets involved and things don''t exactly go according to Brian''s original plan. Meanwhile, Stewie has a bit of a mishap.', 22, '2010-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 16, 'April in Quahog', 'When the local news announces that the Earth will be destroyed by a black hole in 24 hours, everyone in Quahog goes nuts trying to live out their last day.', 22, '2010-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 17, 'Brian & Stewie', 'In the 150th episode, Brian & Stewie get locked in a bank vault, they are forced to deal with each other on a whole new level.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 18, 'Quagmire''s Dad', 'Quagmire can accept his dad''s lifestyle choices, but not when they involve Brian.', 22, '2010-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 19, 'The Splendid Source', 'Peter, Joe, and Quagmire search for the source of a dirty joke.', 22, '2010-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 8), 20, 'Something, Something, Something, Dark Side', 'Peter makes good on another power outage at home--by entertaining his family with a retelling of Star Wars Episode V: The Empire Strikes Back. Newcomers to the story include Mort as Lando Calrissian, Chris'' boss Carl as Yoda, and the Giant Chicken as the nefarious Boba Fett.', 55, '2010-05-23');
