INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 1, 'And Then There Were Fewer', 'In this murder mystery special, The Griffins as well as all the other major characters become trapped in a mansion while they are killed off one by one.', 50, '2010-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 2, 'Excellence in Broadcasting', 'Brian decides to confront Rush Limbaugh when he comes to Quahog for a book signing.', 22, '2010-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 3, 'Welcome Back Carter', 'After Peter catches Carter having an affair, he is forced into keeping a secret. But when Peter accidentally spills the beans, Lois'' mom demands a divorce, and Peter is in charge of Carter''s return to bachelorhood.', 22, '2010-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 4, 'Halloween on Spooner Street', 'Peter and Joe team up to execute a series of painful and humiliating Halloween pranks on unsuspecting family, friends and neighbors.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 5, 'Baby, You Knock Me Out', 'After Lois dominates her competition in the boxing ring, Peter decides to become her promoter.', 22, '2010-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 6, 'Brian Writes a Bestseller', 'Feeling discouraged with the progress of his writing career, Brian decides to throw in the towel until Stewie become his manager and one of his books hits the bestseller list. But when the fame goes to his head, Brian gets a wake-up call from Bill Maher.', 22, '2010-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 7, 'Road to the North Pole', 'Stewie’s favorite thing after his teddy bear, Rupert, is Christmas. So when he hears that Santa is making an appearance at the mall, he begs Brian to take him so that he can tell Santa in person what he wants for Christmas. Brian begrudgingly takes Stewie to the mall, only to get the brush-off from Santa. As a result, Stewie and Brian travel to the North Pole to find Santa and teach him a lesson in holiday cheer.', 44, '2010-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 8, 'New Kidney in Town', 'Peter needs a new kidney after his energy-drink addiction causes renal failure. Meanwhile, Chris is chosen to introduce United States President Barack Obama at his school after winning an essay contest. Trouble is, Meg wrote the essay.', 22, '2011-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 9, 'And I''m Joyce Kinney', 'Lois is outraged when local news anchor Joyce Kinney airs a negative profile on her.', 22, '2011-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 10, 'Friends of Peter G.', 'Brian and Peter are required to attend a 12-step program to deal with their drinking problems; Death gives Peter a glimpse of what life would be like without alcohol.', 22, '2011-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 11, 'German Guy', 'Chris''s search for a new hobby leads him to befriend a puppeteer named Franz, until his checkered past is revealed.', 22, '2011-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 12, 'The Hand That Rocks the Wheelchair', 'Meg is enlisted to check in on Susie and Joe while Bonnie is away but she soon becomes a little too involved. Meanwhile, Stewie accidentally creates an evil twin.', 22, '2011-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 13, 'Trading Places', 'Chris, Meg, Peter and Lois all trade places to teach each other a lesson.', 22, '2011-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 14, 'Tiegs for Two', 'When the local dry cleaner loses Peter’s favorite white shirt, he goes ballistic. Meanwhile, Brian tries to score on a date with a new friend, Denise, but ends up striking out. Instead of calling it quits on love, he decides to enlist Quagmire’s help, but things get nasty when they start to compete for the affections of each other’s old flames, Cheryl Tiegs and Jillian Russell.', 22, '2011-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 15, 'Brothers & Sisters', 'When Mayor West marries Lois’ sister, Carol, they move into the Griffin’s house to be one big “happy” family. To make room for everyone, Stewie is bumped out of his room and takes over Chris’ room, but not everyone is annoyed by the change. Peter and Mayor West bond and become best friends.', 22, '2011-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 16, 'The Big Bang Theory', 'Stewie and Brian go back in time to stop Bertram from killing Leonardo da Vinci in order to erase Stewie from the universe.', 22, '2011-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 17, 'Foreign Affairs', 'Bonnie and Lois take a little trip to Paris where Bonnie crosses the line.', 22, '2011-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 9), 18, 'It''s a Trap!', 'Peter retells the story of Return of the Jedi.', 44, '2011-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 10), 1, 'Lottery Fever', 'Peter blows his savings on lottery tickets and the family writes it off as one of his usual shenanigans until they end up millionaires. In true Griffin fashion, they can’t handle the good fortune and struggle to stay grounded.', 22, '2011-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 10), 2, 'Seahorse Seashell Party (II)', 'While the Griffins are housebound during a hurricane, Brian ingests psychedelic mushrooms. He sees bizarre and unsettling things, and acts accordingly. Meanwhile, the rest of the family is bored and irritable, and Meg finally lashes out at Chris, Lois and Peter for all the crap they''ve given her.
