INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 10), 7, 'Amish Guy', 'On the return from an adventurous day at an amusement park, the Griffins’ car breaks down in Amish country and they are stranded with no way out. When Meg falls for an Amish boy, the Griffins then find themselves in a crusade against the conservative locals.', 22, '2011-11-27');
