INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 10), 9, 'Grumpy Old Man', 'It’s winter in Quahog, and Lois’ parents take Stewie away on a trip. But when Carter falls asleep at the wheel, the family decides it might be time for him to retire. Peter and Lois take the clan to Florida to check out some fine retirement communities, but Carter refuses to go down without a fight.', 22, '2011-12-11');
