INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 1, 'Finders Keepers', 'Peter is convinced that a restaurant placemat is a treasure map. Word quickly spreads about the alleged cache, sparking a city-wide search and turning the citizens of Quahog against each other.', 22, '2013-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 2, 'Vestigial Peter', 'After a vestigial twin grows out of Peter''s neck, which he names Chip, he eventually starts realizing that people like Chip more than they like him, so Peter has him amputated. However, after Peter gets into trouble, he realizes he needs Chip more than ever.', 22, '2013-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 3, 'Quagmire''s Quagmire', 'Quagmire dates a woman named Sonja, who is just as sexually active as he is, but things take a turn for the worse when she kidnaps him to be her sex slave, so Peter, Joe and Ida must search the seedy back alleys of Quahog to rescue him. In the meantime, Brian, Stewie and Rupert get involved in a most unusual love triangle. ', 22, '2013-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 4, 'A Fistful of Meg', 'When Meg spills her lunch on the new kid at school, he makes plans to end her. Meanwhile, Peter keeps harassing Brian in the nude until it reaches the breaking point.', 22, '2013-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 5, 'Boopa-Dee Bappa-Dee', 'The Griffins go to Italy and are faced with annoying immigration laws after Peter destroys their passports. ', 22, '2013-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 6, 'Life of Brian', 'Stewie and Brian travel back in time to 17th-century Jamestown and make too many close calls with changing history. Stewie decides to destroy his time machine, but comes to regret it when Brian dies after being hit by a car. Devastated by his death, the Griffin family goes out and adopts another dog from the pet store, Vinnie, who is quickly accepted by all the members of the Griffin family, other than Stewie, who can''t get over the loss of Brian.', 22, '2013-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 7, 'Into Harmony''s Way', 'When Peter and Quagmire discover that their singing voices create beautiful harmony together, they form a singing/songwriting team, in the vein of Simon and Garfunkel. However, tensions run high when fame gets to Peter’s head.', 22, '2013-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 8, 'Christmas Guy', 'When Carter Pewterschmidt cancels the annual Quahog Christmas carnival, because he hates the holiday, Peter must transform his father-in-law from a Scrooge into a hometown hero in order to salvage the event. Meanwhile, Stewie devises a master plan to get the one and only thing he wants for Christmas.', 22, '2013-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 9, 'Peter Problems', 'When Peter gets fired for crashing a forklift into a business meeting, Lois takes a job at the grocery store while Peter becomes a stay-at-home dad — which leads to poor bedroom performance.', 22, '2014-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 10, 'Grimm Job', 'From Grimm to Griffin, three classic fairy tales get a new Quahog spin, including "Jack and the Beanstalk," "Little Red Riding Hood" and "Cinderella."', 22, '2014-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 11, 'Brian''s a Bad Father', 'Brian tries to use Dylan''s television connections to further his career.', 22, '2014-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 12, 'Mom''s the Word', 'When Peter''s mother dies, he befriends her longtime pal Evelyn, who tries to seduce him. In the meantime, Stewie feels despair upon dealing with the realities of death.', 22, '2014-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 13, '3 Acts of God', 'Peter grows frustrated when players on opposing teams continue to thank God after defeating his beloved New England Patriots football team, so he and the guys embark on a global quest to find God and ask Him to stop interfering with the outcome of professional football games.', 22, '2014-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 14, 'Fresh Heir', 'Chris becomes the heir to Carter''s fortune but refuses to accept the money; Peter desperately tries to keep the wealth in the family.', 22, '2014-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 15, 'Secondhand Spoke', 'Peter takes up smoking cigarettes, and is approached by Mr. Stone, an advertising executive who wants Peter to be the face of his anti-smoking campaign under the caveat that Peter continues to smoke. Meanwhile, Stewie helps Chris battle bullies at school.', 22, '2014-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 16, 'Herpe, the Love Sore', 'Brian gives Stewie an STD. Meanwhile, Peter and the guys fight back when another group claims their booth at The Drunken Clam.', 22, '2014-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 17, 'The Most Interesting Man in the World', 'When Peter takes Stewie to the park for some quality father-son time, he mistakenly takes the wrong baby home, prompting Lois to call him an idiot. Determined to prove to her that he''s a responsible adult, Peter goes on a business trip to Chicago and returns as an intelligent, classy person.', 22, '2014-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 18, 'Baby Got Black', 'Chris is forbidden to see Jerome''s daughter Pam, so when the kids run away together, Jerome and Peter must work together to find them.', 22, '2014-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 19, 'Meg Stinks!', 'Meg has fun partying with Peter when he takes her to a college for an interview. Brian must learn how to live in the wild when he gets sprayed by a skunk and is prohibited from entering the house.', 22, '2014-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 20, 'He''s Bla-ack!', 'Cleveland returns to town, but is instantly banned from spending time with Peter when Lois and Donna get into a big fight over parenting.', 22, '2014-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 12), 21, 'Chap Stewie', 'When Peter and Chris interrupt Stewie’s TV time, the angry baby goes back in time to break up Peter and Lois so he’s never conceived, but is shocked when he is reborn into a “Downton Abbey”-esque British household.', 22, '2014-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 1, 'The Simpsons Guy', 'In a special hour-long crossover with The Simpsons, the Griffins meet the Simpson family when they end up in Springfield after their car is stolen. Stewie takes lessons in pranks and skateboarding from Bart, while Lisa discovers - to her annoyance - that Meg is as good at playing the saxophone as she is. Peter bonds with Homer as they locate the missing car, but then they fight after Peter loses his job when Pawtucket Patriot is revealed to be a copy of Duff Beer.', 46, '2014-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 2, 'The Book of Joe', 'Peter helps Joe fulfill his dream of getting a book published, only to take over as the writer. In the meantime, Brian develops an extreme thirst for exercise.', 24, '2014-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 3, 'Baking Bad', 'Peter and Lois decide to open a cookie store, but Peter ruins things when he decides to bring clients in his own way.', 24, '2014-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 4, 'Brian the Closer', 'Brian''s cosmetic surgery leads him down a new career path as a real estate agent, which gets him into trouble with Quagmire.', 24, '2014-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 5, 'Turkey Guys', 'On the night before Thanksgiving, Brian and Peter drunkenly devour the holiday bird, and then must go out to find a replacement. In Peter absence, Chris attempts to step up and become the man of the house.', 24, '2014-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 6, 'The 2,000-Year-Old Virgin', 'After running into Jesus at the Quahog Mall, Peter is stunned to discover that the Son of God is still a virgin. So, he enlists Quagmire and Cleveland to help him throw Jesus the best birthday ever by finding a way to help him become a man.', 24, '2014-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 7, 'Stewie, Chris & Brian''s Excellent Adventure', 'To help Chris ace his ninth grade history class, Stewie and Brian employ the time travel machine for educational purposes. Not surprisingly, all three get stuck in the past.', 24, '2015-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 8, 'Our Idiot Brian', 'When Brian takes the SATs for Meg but doesn''t do very well, the family starts to doubt his intelligence; Peter tries to show Brian the upside of being stupid.	', 24, '2015-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 9, 'This Little Piggy', 'Meg is thrilled to be recruited as a model, but it turns out to be for a very specific type of modeling: the foot-fetish industry. Meanwhile, Brian accompanies Stewie on an open-road adventure when Stewie decides he wants to experience life outside of preschool. ', 24, '2015-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 10, 'Quagmire''s Mom', 'After discovering his checks are actually a large size post-it pad, Peter demands he have access to the checking account. While at the bank, Peter & Lois discover that his first name is actually Justin, so Peter embraces his new partying “bro” lifestyle. Meanwhile, Joe arrests Glenn after he sleeps with an underage girl, which leads to an unexpected reunion.', 24, '2015-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 11, 'Encyclopedia Griffin', 'Peter, Quagmire, Joe and Cleveland form a neighborhood detective agency, and are stunned to discover that Chris is a thief. Meanwhile, Lois is worried about Chris'' delusional relationship with his new girlfriend, but also sees it as an opportunity for Peter to copy Chris'' romantic gestures.', 23, '2015-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 12, 'Stewie Is Enceinte', 'Brian decides he doesn''t want to hang out with Stewie anymore, so Stewie tries to save their relationship by having a baby ... or seven ... by using Brian''s DNA to impregnate himself. Meanwhile, Peter, Joe, Quagmire and Cleveland attempt to make a viral video.', 24, '2015-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 13, 'Dr. C and the Women', 'Meg gets a new job at the airport, where she''s instantly popular for being the hottest employee there. Meanwhile, Cleveland becomes a therapist and starts giving Peter and Lois relationship advice, but Peter quickly becomes frustrated and threatens to tell Donna a big secret about what went down at Cleveland''s bachelor party.', 24, '2015-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 14, '#JOLO', 'When Peter accidentally discovers a missing child, he is hailed as town hero. Meanwhile, Joe quits his job and heads to Niagara Falls to live life to the fullest.', 23, '2015-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 15, 'Once Bitten', 'After attending obedience school, Brian becomes much more submissive, and Peter realizes he misses his old, feistier pal. Meanwhile, Chris makes a new friend at school, but feels betrayed when he discovers it was all a ploy to get closer to Meg.', 24, '2015-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 16, 'Roasted Guy', 'Peter''s friends roast him. With his feelings hurt, he seeks refuge by befriending a group of gossipy women.', 24, '2015-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 17, 'Fighting Irish', 'Peter claims he would beat Liam Neeson (guest voice Liam Neeson) in a fight, but when he is put to the test, he learns that winning is tougher than it seems. Meanwhile, Stewie becomes jealous when Lois decides to be a class mom and starts paying more attention to the other kids over him.', 24, '2015-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 13), 18, 'Take My Wife', 'Lois books a fun couple’s vacation in the Bahamas. But, much to Peter’s surprise, it turns out to be a marriage counseling program instead. Meanwhile, Carter watches the kids at home and becomes frustrated that they’re too into their electronics to play games the old-fashioned way. So he tries to fix it himself.', 24, '2015-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 14, 'Season 14', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 1, 'Pilling Them Softly', 'Stewie is diagnosed with ADD and prescribed Adderall, which Brian takes to write a 2000-page proposal to pitch to author George R.R. Martin at a book convention. Meanwhile, Quagmire and Peter compete, Iron Chef-style, to determine which of them gets to keep his new cooking show.', 25, '2015-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 2, 'Papa Has a Rollin'' Son', 'For Father’s Day, the guys track down Joe’s estranged father. But when Joe explains that his dad is intolerant of people with disabilities, Peter steps in and pretends to be Joe. Meanwhile, Stewie’s doctor tells him that he’ll only grow to be 5’1”, so he hangs out with Tiny Tom Cruise to understand what it’s like to be short.', 22, '2015-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 3, 'Guy Robot', 'Stewie doesn’t like Brian’s stand-up comedy jokes, so the two of them fight. To get back at Brian and make him jealous, Stewie builds a robot friend. But when the robot outsmarts Stewie and dumps him, Brian and Stewie reunite. Meanwhile, Lois forces Peter to get a new mattress.', 22, '2015-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 4, 'Peternormal Activity', 'The guys go to an abandoned asylum seeking inspiration for a new horror movie idea, but end up accidentally killing a man they think is keeping them hostage. Wracked with guilt, they each try to pin the murder on someone else. Meanwhile, Stewie is on a mission to destroy Brian''s glasses because he''s annoyed by how pretentious Brian''s been acting when he wears them', 22, '2015-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 5, 'Peter, Chris & Brian', 'Peter gets a check in the mail from the sale of his mother''s home and he remembers that all of his old porn is still in there. When he returns to retrieve his stash, he finds a "to Peter from Peter" tape and realizes that his life has amounted to nothing. Reeling from his own failures, Peter then attempts to fix Chris before it''s too late, and forces his son to spend time with Brian.', 22, '2015-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 6, 'Peter''s Sister', 'Peter’s sister, Karen, decides to come for Thanksgiving and bullies Peter the same way Meg treats him. While Meg is at first amused, she later feels badly and decides to help Peter train to defeat his sister in a wrestling match. Meanwhile, to avoid overeating on Thanksgiving, Stewie and Brian decide to go on a cleanse, which Stewie takes one step too far.', 22, '2015-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 7, 'Hot Pocket-Dial', 'Quagmire admits that he is in love with Lois. Unfortunately, he proclaims his love while he has accidentally pocket-dialed Peter. Peter is furious and Brian takes it upon himself to fix the situation.', 23, '2015-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 8, 'Brokeback Swanson', 'When Joe is trampled in a local running of the bulls and becomes a quadriplegic, the guys find it too difficult to hang around him. Meanwhile, Brian sleeps with a married woman, and when the husband returns home, he pretends to be the family’s new dog.', 23, '2015-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 9, 'A Shot in the Dark', 'When Peter’s couch is stolen from his front lawn, the guys form a neighborhood watch group. While on duty, Peter sees someone trying to climb into Cleveland’s house and he shoots him. Peter is then arrested and charged with a hate crime. Meanwhile, Cleveland is touched when Peter finally admits to the accident, so he takes the fall for the crime and Peter is exonerated.', 23, '2015-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 10, 'Candy, Quahog Marshmallow', 'Peter, Cleveland and Joe come across a VHS tape called “Winter/Summer” an Asian soap opera that Quagmire starred in when he was living in Korea. Unable to find the final episode of the series, the guys travel to Korea to find it and Quagmire is reunited with his old lover. Meanwhile, Stewie worries he might become a redhead.', 24, '2016-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 11, 'The Peanut Butter Kid', 'When their bank accounts begin to run dry, the Griffins look for ways to make money. Stewie gets cast in a peanut butter commercial and becomes the money maker for the family. Meanwhile, Lois and Peter become crazy show business parents and Brian helps Stewie realize that he does not want to be a child actor.', 24, '2016-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 12, 'Scammed Yankees', 'Lois and her mom, Babs, have a relaxing spa day, leaving Peter to entertain Lois’ father, Carter. The boys fall for an email scam, and have to go to Africa to get their money back. Meanwhile, Brian pursues Meg’s friend, Patty.', 24, '2016-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 13, 'An App a Day', 'Peter overloads his phone with apps. He buys a new phone with more memory, gives his old phone to Chris, and hilarity ensues. Stewie joins a tennis club and invites Brian to be his tennis partner.', 22, '2016-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 14, 'Underage Peter', 'Mayor West raises the drinking age to 50. Because of dog years, Brian is the only one old enough to buy alcohol, so Peter makes him buy all of his booze.', 22, '2016-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 15, 'A Lot Going On Upstairs', 'When Stewie refuses to sleep in his own bed because of nightmares, Peter can’t stand it, so he goes to sleep in the attic. Peter turns the attic into a man cave and all of the guys begin hanging out there, which makes Lois incredibly angry. Meanwhile, Brian helps Stewie overcome his fears by building a device to go into his nightmares and defeat his demons.', 23, '2016-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 16, 'The Heartbreak Dog', 'Meg begins working at a retirement community and starts stealing from the residents. Then Chris finds out and wants in on the heist. When the residents catch them, they blackmail them and force the thieves to listen to all of their boring stories.', 22, '2016-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 17, 'Take a Letter', 'To pay for Stewie’s private school, Lois becomes a postal worker. She finds a letter from Peter that was never sent to his old fling, Gretchen, dated a week before their marriage. When Gretchen tries to come between Lois and Peter, Lois has a plan of her own.', 22, '2016-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 18, 'The New Adventures of Old Tom', 'Peter gets lost in the mall overnight after his family abandons him. Meanwhile, Brian pretends to be a millionaire to win over a girl.', 23, '2016-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 19, 'Run, Chris, Run', 'To everyone’s surprise, Chris wins homecoming king. However, Meg finds out that the cool kids plan to prank him during the homecoming ceremony, so they go to the school to investigate. Meanwhile, Cleveland starts hanging out with Jerome, the bartender. So Peter and the guys try to replace him.', 23, '2016-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 14), 20, 'Road to India', 'Brian falls in love with a tech support worker in India, so he and Stewie travel there to find her. Meanwhile, Joe invites Peter to his bingo night, but when Peter becomes the new center of attention, Lois helps Joe reclaim the group.', 23, '2016-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')), 15, 'Season 15', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 1, 'The Boys in the Band', 'Stewie and Brian form a band aimed at children, but face a breakup when they set their eyes on the same girl. Meanwhile, Chris gets a job as Quagmire''s personal assistant for his sex life.', 24, '2016-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 2, 'Bookie of the Year', 'Brian and Lois decide it''s time for Chris to work out his anger management issues by taking up a sport. Chris surprises everyone and becomes a star baseball pitcher, which turns Peter into a gambling father, as he bets on his son''s baseball games. Meanwhile, Stewie, Brian and Frank Sinatra Jr. attempt to open an Italian restaurant.', 22, '2016-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 3, 'American Gigg-olo', 'After the local airline pilots go on strike, Quagmire looks for new work and becomes a gigolo. When his clients begin to avoid paying for his services, he asks Peter for help getting his money. Meanwhile, Brian is kicked off Peter’s health insurance, so he gets a job at a hardware store, until Stewie gets him fired and things get medical.', 22, '2016-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 4, 'Inside Family Guy', 'Family Guy takes viewers behind the scenes of a regular production week, with James Woods as the guide. See the ins-and-outs of what goes into the making of an episode and watch the drama unfold as Peter is replaced and ends up in the office of Fox Television Group Chairmen and CEOs Dana Walden and Gary Newman to pitch his very own new series.', 22, '2016-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 5, 'Chris Has Got a Date, Date, Date, Date, Date', 'Taylor Swift agrees to go to a homecoming dance with Chris after he asks her via online video. However, when she starts to fall for him, her music takes a hit. Meanwhile, Peter decides to try a new profession and sees firsthand what it''s like to be an Uber driver.', 22, '2016-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 6, 'Hot Shots', 'In order to "save" Stewie from autism, Peter and Lois decide not to vaccinate him and then proceed to convince the rest of Quahog to follow suit. Stewie runs away to save himself from diseases until Sean Penn swoops in to save the day and brings vaccines to the whole town.', 22, '2016-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 7, 'High School English', 'In an anthology episode, the cast reenacts three classic pieces of literature commonly taught in high school: "The Great Gatsby," "The Adventures of Huckleberry Finn" and "Of Mice and Men".', 22, '2016-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 8, 'Carter and Tricia', 'Carter buys the Pawtucket Patriot brewery and decides to cut some corners to save a few bucks. Peter overhears the plan and runs and tells investigative journalist Tricia Takanawa about Carter''s plan to use toxic chemicals in the beer cans. Meanwhile, Brian''s drivers'' license has expired and he enlists Stewie as an instructor.', 22, '2016-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 9, 'How the Griffin Stole Christmas', 'Peter fills in for Santa at the mall, but lets the power go to his head when he realises just what he can get away with. Meanwhile, Stewie and Brian become holiday office-party crashers.', 24, '2016-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 10, 'Passenger Fatty-Seven', 'Quagmire lands free plane tickets for the guys'' trip to San Francisco, but they begin to doubt his flying abilities after getting a look at the auto-pilot function. While in the air, sudden events give Quagmire''s skills a run for the money.', 24, '2017-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 11, 'Gronkowsbees', 'Rob Gronkowski moves into the house behind the Griffins. Stewie raises bees and sells honey at the farmers market.', 22, '2017-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 12, 'Peter''s Def Jam', 'The guys try to start a podcast, but Peter goes solo and branches out as a DJ. Meanwhile, back at the Griffin home, Lois'' allergy forces Brian to move into Stewie''s bedroom and the two have roommate difficulties.', 23, '2017-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 13, 'The Finer Strings', 'The guys decide to form a string quartet, but Peter doesn''t make the cut. Meanwhile, Brian is forced to be Carter''s seeing eye dog and enjoys the life of luxury a little too much', 24, '2017-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 14, 'The Dating Game', 'Quagmire discovers the “dating” app Tinder, forcing Peter, Joe and Cleveland to intervene and save him from his soul-sucking hedonism. Meanwhile, Stewie finds out that he has scoliosis and learns the perks of his latest diagnosis', 22, '2017-03-05');
