INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 16, 'Saturated Fat Guy', 'In an attempt to avoid eating the healthy food that Lois forces him to eat, Peter opens up his own food truck with fattening foods. Meanwhile, Meg joins a roller derby team, despite Chris thinking it’s too dangerous', 22, '2017-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 17, 'Peter''s Lost Youth', 'Peter gets jealous of Lois when she upstages him at a Red Sox fantasy baseball camp. Meanwhile, Stewie runs away from home when Meg is left to babysit him', 22, '2017-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 18, 'The Peter Principal', 'Peter becomes the temporary principal at the high school, and Meg uses his new power to get even with her bullies. Meanwhile, Brian and Stewie open a bed & breakfast that quickly turns into a brothel.', 23, '2017-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 19, 'Dearly Deported', 'When Chris'' Mexican girlfriend, Isabella, gets deported, he volunteers to take care of her twin babies. After learning that Isabella can''t come back to the U.S., the Griffins go to Mexico to return her children.', 23, '2017-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 15), 20, 'A House Full of Peters', 'Peter''s past as a sperm donor catches up to him when many of his children show up unannounced to his house.', 23, '2017-05-22');
