INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 16), 2, 'Foxx in the Men House', 'Peter becomes friends with a cool, handsome paramedic named Stryker Foxx. Wrapped up in his newfound "coolness," he soon dumps Quagmire, Joe and Cleveland.', 23, '2017-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 16), 3, 'Nanny Goats', 'Peter and Louis find themselves with a golden opportunity to reconnect as a couple after Lois'' parents get a nanny to take care of the children for them.', 23, '2017-10-15');
