INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 16), 9, 'Don''t Be a Dickens at Christmas', 'In this special holiday episode, a selfish Peter loses his Christmas spirit and is visited by ghosts of Christmas past, present and future who take him on a journey around Quahog in the style of Charles Dickens'' "A Christmas Carol".', 23, '2017-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 16), 10, 'Boy (Dog) Meets Girl (Dog)', 'Brian is smitten with a female show dog and enters a show dog competition in which the winner gets to breed her; Peter and Lois go to extreme measures to try to convince Chris that Arthur Valentine doesn''t exist.', 23, '2018-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 16), 11, 'Dog Bites Bear', 'Stewie and Brian get into a friendship-ending fight after Brian commits a terrible act to one of Stewie''s beloved toys. Meanwhile, Peter refuses to wash his hand after meeting his favorite breakfast cereal mascot, Boo Berry.', 23, '2018-01-14');
