INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 17), 14, 'Family Guy Lite', 'After a mishap at work, Peter decides to take his health more seriously and diet with the help of Quagmire, Joe, and Cleveland. When Lois takes a stab at writing a romantic fantasy novel, a curious Brian and Stewie investigate to find out who she might have a crush.', 23, '2019-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 17), 15, 'No Giggity, No Doubt', 'When the guys volunteer to chaperone the high school prom, Quagmire hits it off with Courtney only to discover that she is his daughter. To his and the gang''s surprise, Quagmire makes a serious effort to embrace parenting Courtney, joining Peter and Meg on an ill-fated father-daughter camping trip.', 23, '2019-03-10');
