INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0182576')) AND numero_temporada = 17), 18, 'Throw It Away', 'After Lois reads a new book on the joys of decluttering, she challenges the rest of the Griffins to throw anything out of the house that does not spark joy. While all starts out well, Lois soon takes the decluttering to a surprising extreme.', 23, '2019-04-28');
