INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 1, 'Season 1', 'Malcolm, a gifted 11-year-old with an IQ of 165, navigates life in a chaotic household with his overbearing mother Lois, quirky father Hal, and mischievous brothers Reese, Dewey, and Francis. As he adjusts to being placed in a class for gifted students, Malcolm deals with the typical trials of adolescence amidst his family’s antics.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 1, 'Pilot', 'Malcolm finds his life as the middle brother in an eccentric family made even more difficult by his being placed in a class for gifted students at school where he reluctantly befriends another boy with a high IQ and stands up to a bully.', 22, '2000-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 2, 'Red Dress', 'Lois must take drastic steps to discover which of her sons ruined the special dress she bought for an anniversary dinner with Hal.', 22, '2000-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 3, 'Home Alone 4', 'Lois and Hal leave the boys alone for the weekend with Francis. the boys assume that if all goes well, Francis may not have to go back to military school.', 22, '2000-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 4, 'Shame', 'Parallel stories pit Malcolm against a bullying, obnoxious new kid and Francis vies with his intimidating, military-school commandant, who''s presenting sex-education lectures. Meanwhile, Hal takes heat after cutting down a tree.', 22, '2000-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 5, 'Malcolm Babysits', 'Malcolm''s cushy babysitting job provides relief from the trailer the family''s using while their house is being fumigated, until Malcolm learns that the trust placed in him in his new position is strictly limited. Meanwhile, the military school''s master key leads Francis to a corpse, for which he provides a proper send-off.', 22, '2000-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 6, 'Sleepover', 'Malcolm sleeps over at Stevie''s house and, appalled at his over-protected lifestyle, persuades him to sneak out to a strange, late-night escapade. Francis deals with hazing at military school. Reese tries to prove he''s man enough to watch a scary movie.', 22, '2000-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 7, 'Francis Escapes', 'Francis goes AWOL from military school to link up with his girlfriend, a ditsy doozy who''s made him gaga.', 22, '2000-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 8, 'Krelboyne Picnic', 'The whole family attends a Krelboyne family picnic, and Malcolm dreads his performance in the event''s Academic Circus will make him look like a freak. Disasters abound as stage acts bomb, families feud, and Malcolm''s dad serves meat to vegetarians.', 22, '2000-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 9, 'Lois vs. Evil', 'Lois''s firing prompts household economizing. Meanwhile, Francis delights in his honor-guard duty—at a teenage beauty pageant.', 22, '2000-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 10, 'Stock Car Races', 'While Hal secretly takes the boys to the stock car races, Lois desperately searches for her missing paycheck. Francis at military school is keeping a boa constrictor as a pet.', 22, '2000-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 11, 'Funeral', 'A relative''s funeral conflicts with Malcolm''s plans for his very first date, so he tries to figure out a way to skip the bereavement ceremony.', 22, '2000-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 12, 'Cheerleader', 'A spiffy cheerleader attracts slovenly Reese, who cleans up his act—best as he can—to woo her. He even joins her rah-rah squad. Dewey tries to convince Lois and Hal to buy him a new toy. Francis has a heart-to-heart conversation with headmaster Spangler.', 22, '2000-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 13, 'Rollerskates', 'Roller-skating lessons from Hal bug Malcolm, who rebels against dad''s discipline while mom agonizes in bed from a backache she blames on Reese. Francis avoids his squad''s survival weekend.', 22, '2000-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 14, 'The Bots and the Bees', 'Malcolm and his Krelboyne classmates enlist the help of Hal for a school project, which involves a robot, and an enormous swarm of bees. Lois visits Francis at his school after he becomes injured and soon clashes with Spangler.', 22, '2000-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 15, 'Smunday', 'The boys stay home from school when their mother thinks it''s Sunday instead of Monday. Malcolm thinks of a plan to get Francis out of trouble once again. Hal gets sucked in by a Porsche dealership.', 22, '2000-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 1), 16, 'Water Park (1)', 'When the family goes to a water park for a day, Dewey is left home with an elderly, stern babysitter. Francis is hustled at pocket billiards by his military-school commandant.', 22, '2000-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 2, 'Season 2', 'The family’s misadventures continue as Malcolm faces new challenges at school and home. Reese explores his culinary talents, Dewey’s imagination runs wild, and Francis’s escapades at military school add to the family’s chaos.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 1, 'Traffic Jam (2)', 'Hal, Loi, Malcolm and Reese are trapped in a horrendous traffic jam. Francis enters himself in a bet that recalls the egg-eating wager in "Cool Hand Luke." Malcolm becomes smitten over a girl he meets. Dewey has his own little adventure--all over the world--before his family returns home.', 22, '2000-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 2, 'Halloween Approximately', 'Francis visits the week after Halloween and helps his brothers in a trick that involves a giant slingshot with icky ammo. Hal tries to catch a mysterious hot-rodder.', 22, '2000-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 3, 'Lois''s Birthday', 'Crummy gifts rile birthday gal Lois, who suddenly splits from home, leaving confusion, anxiety and desperation in her wake.', 22, '2000-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 4, 'Dinner Out', 'Shenanigans abound at the fancy spot where the family''s dining with the Kenarbans, and at Francis'' school, where rowdy teenage girls are partying.', 22, '2000-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 5, 'Casino', 'A family weekend vacation to a casino turns into an ordeal in the desert for Hal, Reese and Malcolm, who wander onto an artillery range. Francis sneaks home, but has no one to play with.', 22, '2000-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 6, 'Convention', 'Hal and Lois heads off to a convention while the boys stays home for the babysitter. Malcolm, Reese and Dewey assumed it''s just another old woman, their parents hired to watch them. They decide to do a series of pranks on their babysitter, which includes the covered up sewer tank with a blanket and a book for the old woman sit on. To their surprise, their babysitter is a hot, teen-aged girl named Patty. She is sweet to them, but also bitter because she was rejected by Francis, a long time ago, because she was obese. Now the boys compete against each other to see who will prove their eldest brother wrong in his rejection and sleep with her without sex. Meanwhile at the convention, Lois tries in vain to stop the fight between Hal and Jack, who stole his idea.', 22, '2000-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 7, 'Robbery', 'The night shift at Lucky Aide is held hostage by two robbers, since Craig does not want to give up the combination for the store''s safe. Francis tries to help a heartbroken friend at the academy, while Hal and the boys fight nature at home.', 22, '2000-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 8, 'Therapy', 'Malcolm''s humiliation as a Krelboyne drives him crazy, so he fakes his way into seeing the school''s shrink, with whom the con continues.', 22, '2000-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 9, 'High School Play', 'Malcolm gets a role in the high school play and is so captivated by high school gossip that he forgets his lines. Lois discovers the joys of massage. Hal and Dewey build a society of model buildings in the living room. Francis tries to show his individualism at school when the commandant cracks down on personal belongings.', 22, '2000-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 10, 'The Bully', 'Reese, promising champion of his school''s wrestling team, gets beaten by a girl, completely demoralizing him. So he gives up his school-bully carrier, which destabilizes the natural order of things at school. Francis tries to get out of academy at his birthday in an attempt to avoid academy-birthday-traditions.', 22, '2000-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 11, 'Old Mrs. Old', 'Dewey starts carrying a purse to school. Francis''s friend Richie joins him at military school. Malcolm becomes a slave to an old woman in the neighborhood.', 22, '2001-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 12, 'Krelboyne Girl', 'Lois and Hal try to end Dewey''s dependence on his stuffed animal Domingo by convincing him that it is too dirty. Strangely attracted, Malcolm finds himself in emotional confusion about the new weird Krelboyne girl Cynthia. At the academy Commandant Spangler re-institutes old Hickory into the school''s disciplinary system and Francis tries to convince his father Hal to lie for him to avoid punishment.', 22, '2001-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 13, 'New Neighbors', 'New neighbors, who turn out to be even more awful than Malcolm''s family, move in next door; the Marlin Academy cadets prepare for a visit from Oliver North.', 22, '2001-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 14, 'Hal Quits', 'Hal feels like his job is a piece of c* after going to Dewey''s class for parent job day. So he decides to take a "kidney failure" weeks off. While Francis is forced to work at the lucky aid over spring break.', 22, '2001-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 15, 'The Grandparents', 'Lois'' estranged parents, Ida and Victor, pay the family a visit. Right away, trouble starts brewing. Victor bonds with Reese, Ida gets Malcolm into a fight, and Dewey is haunted by childhood memories of his inattentive grandparents.', 22, '2001-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 16, 'Traffic Ticket', 'Lois gets a traffic ticket and immediately blames Francis and makes him get the money to her.  To do this, Francis stages a stunt for the other cadets'' amusement.  Malcolm finds evidence that Lois was wrong about the traffic ticket.', 22, '2001-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 17, 'Surgery', 'A hospital stay unsettles Malcolm, who''s stuck in a kids ward with what may be appendicitis. Meanwhile, at military school, Francis leads a hunger strike.', 22, '2001-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 18, 'Reese Cooks', 'A cooking class energizes Reese; a planned party irks Malcolm, whose brutal honesty hurts the hostess, Krelboyne Cynthia.', 22, '2001-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 19, 'Tutoring Reese', 'Malcolm and the Krelboynes tutor Reese, and uncover the real reason behind his failing grades.', 22, '2001-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 20, 'Bowling', 'Malcolm and Reese go to a bowling party where they vie for the attention of a cute girl.', 22, '2001-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 21, 'Malcolm vs. Reese', 'Francis has an extra ticket for a wrestling event and it is the prize pitting Malcolm vs. Reese in a one-upmanship war; caring for Craig''s cat is troublesome for Dewey.', 22, '2001-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 22, 'Mini-Bike', 'Lois forbids the boys to ride a motorbike they found, but Reese disobeys and breaks a leg.', 22, '2001-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 23, 'Carnival', 'Malcolm, Dewey, Stevie, and Reese hide out at a traveling carnival after hours and run afoul of a determined security guard and several members of the freak show.', 22, '2001-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 24, 'Evacuation', 'Hal is inadvertently responsible for a toxic chemical spill that forces a neighborhood evacuation; Malcolm deals with being grounded even in the emergency shelter; Francis suffers through a date with a geeky 12-year-old.', 22, '2001-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 2), 25, 'Flashback', 'Lois is two weeks late with her period, causing her and Hal to panic and start a big fight, while trying to keep it from the boys. And while Dewey is scared that his parents may split up, Hal and Lois remember the troubles of getting their previous four sons.', 22, '2001-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 3, 'Season 3', 'Francis leaves military school to work at a resort in Alaska, encountering new challenges under his strict boss, Lavernia. Back home, Malcolm and his brothers continue to stir up trouble, leading to humorous and unpredictable situations.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 1, 'Houseboat', 'The family takes a vacation with the Kenarbans, sharing a houseboat. And while Steve''s parents are caught in a fight, Reese and Steve socialize with some cheerleader from a nearby spirit camp, Malcolm is stuck with Hal fishing. At the military academy, Eric turns eighteen and leaves for Alaska, inspiring Francis to do something about his situation too.', 22, '2001-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 2, 'Emancipation', 'Being fed up with military school, Francis gets himself legally emancipated so he can go north to Alaska with his friend Eric and become a logger. This does not sit well at all with the family.', 22, '2001-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 3, 'Book Club', 'Lois, in an attempt to get a break from the family, joins a book club that turns out to be a night off for frustrated housewives, but it all goes a little bit haywire. Meanwhile Francis tries to get to Alaska, learning something important about himself and about truck drivers. Hal, who tries to keep the boys out of troubles for the evening, is caught in an inner conflict about how to treat them.', 22, '2001-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 4, 'Malcolm''s Girlfriend', 'Francis has to stay a couple of days in a small county jail and enjoys it more then he expected. Malcolm finds himself with a girlfriend, which add to his usual social anxiety. Dewey makes friend with a new kid in the area, helping the kid''s mother to compose Dewey''s dream birthday party for his new friend.', 22, '2001-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 5, 'Charity', 'In an effort to contribute to society and to make her boys useful at the same time, Lois "volunteers" Malcolm, Reese and Dewey for charity work at a local church. The boys are assigned to sort giant piles of donated clothing, game, appliances etc. Initially irritated at their new task, they realize the donated stuff is a lot nicer than their own possessions, and they begin swapping out their old stuff with the second-hand items. The boys soon make a enterprise out of their charity assistance, going as far as to sell things to the neighborhood kids - that is until Hal finds out. Meanwhile, Francis must come to grips with the fact his fabulous job in Alaska is not quite what he expected.', 22, '2001-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 6, 'Health Scare', 'When Hal''s doctor discovers something suspicious during his routine check-up, Lois and Hal become frantic, nervous wrecks as they wait for the test results. As a result of her anticipation, Lois becomes even stricter with the boys, leaving them to misinterpret the new house rules. Meanwhile, in Alaska, Francis comes to blows with his boss.', 22, '2001-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 7, 'Christmas', 'When Malcolm and his brothers destroy their Christmas tree ornaments, Lois punishes them by canceling Christmas and moves all the presents into the garage. The only way she will reinstate the holiday is if the boys behave impeccably up to Christmas morning. Her plan works better than expected, and Lois is touched that her family responded so well to her challenge. Meanwhile, the boys decide that Lois could use this tactic for future holidays and retaliate by breaking into the garage and opening up all the presents. Elsewhere, Francis is forced to visit his Grandma Ida for Christmas.', 22, '2001-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 8, 'Poker', 'Poker showdowns with Abe give Hal a flush; dance lessons turn Lois awhirl; an Alaskan blizzard entraps and rattles Francis. (TV Guide)', 22, '2002-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 9, 'Reese''s Job', 'Trouble finds Reese at his new fast-food job; a new Krelboyne tutors Malcolm; Hal and Lois sabotage Dewey''s plan to get a dog.', 22, '2002-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 10, 'Lois''s Makeover', 'A negative job-performance review riles Lois; hoops play with the boys energizes Hal; a vermin infestation busies rat-killer Francis.', 22, '2002-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 11, 'Company Picnic (1)', 'Juicy guest casting and ingenious plotting enliven an hourlong episode that airs in the plum post-Super Bowl slot. One storyline unfolds at Hal''s company picnic, where Lois clashes with a blabby wife and her beleaguered spouse; and Hal runs afoul of his new boss and the big cheese. In Alaska, Francis''s scheme to win a bet involves rigging a hockey game that pits loggers vs. a fearsome women''s squad led by a blowhard coach.', 22, '2002-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 12, 'Company Picnic (2)', 'After Hal is mistaken by his new boss, as that guy''s boss, Hal plays along. Malcolm is in a three-legged scavenger hunt with the girl he likes, but becomes upset after he confesses he likes her, and she says she likes another boy. Reese is also the the scavenger hunt, and at first doesn''t like the big dumb bully he is with, but they grow to like each other when they bond over beating up the other contestants and stealing their items. Lois continues to balance keeping Dewey intact and dealing with the crazy woman, but now must talk to the husband as well. Francis continues to sabotage his own team, this time on the ice.', 22, '2002-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 13, 'Reese Drives', 'Highway horror: Reese gets a learner''s permit, which he promptly proceeds to abuse by commandeering a driving-school vehicle.', 22, '2002-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 14, 'Cynthia''s Back', 'The return of the smart and sassy Cynthia rattles Malcolm, who''s astonished by her physical maturation. And so is drooling Reese.', 22, '2002-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 15, 'Hal''s Birthday', 'The arrival of Francis''s new bride on Hal''s birthday sparks a fray that drives the younger siblings out---and into a posh hotel.', 22, '2002-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 16, 'Hal Coaches', 'Clever Hal invigorates Dewey''s soccer team; sly Reese blackmails a philandering neighbor; obsessed Malcolm battles a computer program.', 22, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 17, 'Dewey''s Dog', 'Dewey rules, thanks to his new dog that intimidates Malcolm and Reese; Hal and Lois hit the town with big plans---and flu symptoms.', 22, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 18, 'Poker 2', 'Girls in the house spell trouble for the boys, who are on their own while Dad''s hosting a poker game that''s more about one-upmanship than cards.', 22, '2002-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 19, 'Clip Show', 'An embattled psychiatrist probes the boys'' naughty behavior patterns in a session framed by flashbacks to past episodes.', 22, '2002-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 20, 'Jury Duty', 'Lois gets jury duty and Hal tries to figure out what case she''s working on. Meanwhile, Malcolm and Reese saw Stevie''s mom naked and brag about it, they also take Dewey to the sewers and get lost.', 22, '2002-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 21, 'Cliques', 'Back in the general school population, the Krelboyne whiz kids wind up in cliques with jocks, skateboarders and brooding "Goths."', 22, '2002-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 3), 22, 'Monkey', 'New monkey business occupies Reese, now a self-appointed law enforcer; a capuchin monkey has it in for Lois''s co-worker, Craig.', 22, '2002-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 4, 'Season 4', 'The family dynamics shift with the arrival of baby Jamie. Malcolm navigates teenage life, including romantic interests and school pressures, while Hal and Lois juggle parenting their growing brood.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 1, 'Zoo', 'Malcolm, whose frenetic home life is a kind of zoo, begins the fourth season by accompanying his family to the real thing. A visit to the zoo offers close encounters with creatures great and small. But Hal wishes he could have passed on an encounter with Lois''s former beau, who lectures on rain-forest animals. Elsewhere, Reese butts heads with a goat; and Malcolm and Dewey take a tumble into a tiger den. Another storyline checks in on ne''er-do-well Francis, now the unlikely foreman of a dude ranch owned by a cheery German businessman.', 22, '2002-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 2, 'Humilithon', 'High school''s first day vexes Malcolm, who acquires an unfortunate nickname; and Hal, a parental "volunteer" running afoul of authority.', 22, '2002-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 3, 'Family Reunion', 'Christopher Lloyd adds to his gallery of eccentric characters, playing Hal''s quirky, cranky and very wealthy father, Walter, in this rollicking episode. The occasion is a birthday celebration for the old man, but the snooty female in-laws seem more interested in offending Lois. Their shabby behavior initially goes unnoticed by Hal, who''s desperately trying to bond with his self-centered dad; and by Dewey and Reese, who seek some of Grampa''s dough by currying favor with him. But when Lois is reduced to tears after being excluded from a group photo, the family rallies to her side with an all-out counterattack that turns the party into pandemonium.', 22, '2002-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 4, 'Stupid Girl', 'Acting dumb like Reese eases Malcolm''s stress and lands him a date with the new light of his life, an attractive girl who''s really a dim bulb.', 22, '2002-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 5, 'Forwards Backwards', 'Brotherly love is lost on Malcolm and Reese, now out to sabotage his sibling''s birthday in devilish strikes met with crafty counterattacks.', 22, '2002-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 6, 'Forbidden Girlfriend', 'Malcolm starts to date Nikki. Meanwhile, Hal and Lois must take abstinence pills in an attempt to be better parents. At the ranch, Otto is furious with the other ranchers who keep destroying the fence that Francis is building to keep the cattle inside.', 22, '2002-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 7, 'Malcolm Holds His Tongue', 'After joining the basketball team at school, Malcolm soon finds himself under the coach''s skin due to his constant complaining, which eventually gets him kicked off the team. Determined to put an end to his horrible habit of talking before he thinks, Malcolm starts "holding his tongue" which solves all the problems with his coach, girlfriend, and parents, but it ends up causing more stress than before. Meanwhile, Hal takes up speed walking and is desperate to be the best while Reese gets Craig to take him and Allison to a concert and almost ruins his date.', 22, '2003-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 8, 'Boys at Ranch', 'On a visit to Francis'' dude ranch Hal can''t help being disappointed in Francis'' success, Reese and Malcolm fear Francis has turned into an overly responsible grownup, and Gretchen punishes Dewey for breaking a valuable doll.', 22, '2003-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 9, 'Grandma Sues', 'Grandma Ida is even nastier than usual (if that''s possible) because of a tumble down the front steps that resulted in a broken collarbone, prompting her to sue her daughter and son-in-law for pain and suffering. And there''s more momentous news on the home front: Lois is pregnant.', 22, '2003-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 10, 'If Boys Were Girls', 'After being rattled by a battle among the boys, a pregnant Lois ponders the consequences of raising another brawling kid. So she fantasizes that her unruly sons have morphed into well-behaved young daughters. Malcolm becomes Mallory, Reese is transformed into Renee and Dewey turns into Daisy.', 22, '2003-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 11, 'Long Drive', 'A sex lecture from Lois rattles Malcolm; a ranch calamity unnerves Francis; disharmony among Hal''s music group is a prelude to their concert. Also, a day in jail tests a defiant Reese, who faces a "Scared Straight" encounter.', 22, '2003-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 12, 'Kicked Out', 'After Lois is out of town, Malcolm and Hal got into a fight leading Malcolm to get expelled from his house.  Malcolm lives with his girlfriend in her attic, as Hal put signs for "Missing Malcolm."', 22, '2003-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 13, 'Stereo Store', 'Jessica, a sly, 16-year-old sitter outfoxes the boys while Lois is away and Hal''s busy with a second job as a whiz of a salesman.', 22, '2003-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 14, 'Hal''s Friend', 'Malcolm tries to emancipate Dabney from his overbearing mother while Hal invites his ne''er-do-well old buddy to the house.  At the ranch, Francis is forced to share a room with Otto.', 22, '2003-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 15, 'Garage Sale', 'A garage sale that''s entrusted to Reese (yikes!) yields treasures near and dear, like Hal''s old radio transmitter, which he makes operational. And a PC dating back to 1976 that Malcolm plans to sell to Craig for $1300.', 22, '2003-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 16, 'Academic Octathalon', 'An academic competition faces the Krelboynes in an event Malcolm derides. Especially when he learns his teacher has a cheating plan. Also: a commitment to a formal dance ruffles Reese, who''s now trying to ditch his date.', 22, '2003-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 17, 'Clip Show 2', 'Hal and Lois are penning their will, and think back to all the trouble their sons put them through. It is there that Lois'' problems with Francis are finally revealed and how her inability to admit when she is wrong lead to a lot of the problems the family has been dealing with.', 22, '2003-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 18, 'Reese''s Party', 'When Hal and Lois go out of town for a "last chance" getaway before the baby comes, Reese has a big bash that gets out of hand. College-age thugs show up, cancel the party and set up a drug-making operation in the garage. All Reese and Malcolm can do is knuckle under. The good news is, Dewey''s not around. The bad news is, his baby sitter is Lois''s annoying co-worker Craig. Meanwhile, Hal and his very pregnant wife are off at a romantic retreat---feuding.', 22, '2003-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 19, 'Future Malcolm', 'Leonard, a cynical, genius chess player with no friends or job, makes Malcolm think he could grow into a similar adulthood. Determined to prevent this undesirable fate, Malcolm tries to help Leonard change his life by lining him up for a job interview with the obnoxious Craig. Meanwhile, Francis finds employ as a nude model and begins to delight in the exposure.', 22, '2003-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 20, 'Baby (1)', 'Lois goes into labor while Hal and the boys are at a bridal exposition. Ida moves in after her apartment burns down and she refuses to stay with Susan.Dewey reveals the date his parents chose for the baby''s planned delivery is his birthday in an announcement at the exposition to humiliate Hal.', 23, '2003-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 21, 'Baby (2)', 'While Lois is in labor, the house is hectic, and Hal, desperate to get home, has crashed the car on the way out of the expo.', 22, '2003-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 4), 22, 'Day Care', 'With the arrival of their fifth child, Lois and Hal search for a "creative" daycare solution.', 22, '2003-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 5, 'Season 5', 'Malcolm and his brothers find themselves in various predicaments, from neighborhood block parties to school projects gone awry. Francis’s life on the ranch presents its own set of challenges, adding to the family’s ongoing adventures.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 1, 'Vegas', 'When Dewey''s pet rabbit does good in a state contest, the family must travel to Las Vegas for the nationals. But Reese unknowingly sells the rabbit to a restaurant. Now it is up to Dewey (with a little help from a "choking" Reese) to try and save the rabbit.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 2, 'Watching the Baby', 'Hal and the boys offer to watch baby Jamie so an exhausted Lois can finally get some sleep. Hal leaves the boys in charge while he goes to the Lucky Aid to pick up more diapers. While the boys are watching Jamie, three beautiful teenage girls arrive and woo Malcolm, Reese and Stevie away for the night, leaving Dewey alone with the baby. Meanwhile at the Lucky Aid, Hal doesn''t have enough money for the diapers and Craig forces him to work. Back at home, Dewey concocts an elaborate bedtime story for Jamie involving each member of his family.', 22, '2003-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 3, 'Goodbye Kitty', 'No one wants to tell Stevie his parents are getting a divorce, until Reese spills the beans.', 22, '2003-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 4, 'Thanksgiving', 'Malcolm skips out on Thanksgiving to go to a party; Reese becomes abusive to Hal and Dewey as he attempts to prepare Thanksgiving dinner.', 22, '2003-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 5, 'Malcolm Films Reese', 'Malcolm chooses Reese as his subject for an Abnormal Psychology mid-term project; Dewey earns some extra cash as a street performer.', 22, '2003-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 6, 'Malcolm''s Job', 'Malcolm gets a job working for Lois on the drugstore loading dock but is shocked to find that Lois smokes. She makes him promise not to tell, then turns her back on him and writes him up for a silly offense.   Meanwhile, Dewey runs away to the Ranch to be with Francis because he says he is tired of Reese and Malcolm.   Hal is also busy, secretly betting on and entering Jaime in baby competitions.', 22, '2003-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 7, 'Christmas Trees', 'Hal, Reese, Malcolm, and Dewey go into business selling Christmas trees, with the boys using some of their own money, but two priests send homeless people to their business, trying to sabotage their sale.', 22, '2003-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 8, 'Block Party', 'Neighbors have the annual "The Wilkersons are gone" block party until they come home early. Reese and Dewey set up a plan to get money by letting Reese-tortured kids get revenge. Hal and Lois enter a kielbasa-eating contest and Malcolm unknowingly assists a robbery, but a surprising twist comes in the end.', 22, '2004-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 9, 'Dirty Magazine', 'Malcolm alerts the A.C.L.U. when he encounters censorship working on the high-school literary magazine; Hal tries to flirt with the woman in his office responsible for cutbacks.', 22, '2004-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 10, 'Hot Tub', 'Jamie''s babysitter coerces Malcolm into doing a "small" task for her; Dewey finds a friend, only to lose him to Reese; Francis persuades Otto to confront an old adversary that once courted Gretchen.', 22, '2004-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 11, 'Ida''s Boyfriend', 'Malcolm gets his tongue pierced and needs to hide it for a month. While Lois'' mother, Ida, comes and annouces that she will marry a rich Chinese Man that she met on a cruise. Malcolm gets complications when his tongue ring gets infected, rendering him unable to say "S''s" and he discovers that Ida has been drugging her fiancé with opiates and mood enhancers. When Lois and Hal confront Ida, she drugs them with free food. But luckily, the fiancé misses a drug treatment, and realizes that Ida is a terrible woman and he leaves her at the altar. Malcolm is punished for his tongue piercing.   Meanwhile at the ranch, Otto decides to hire a murder mystery acting troup, but it all turns out badly.', 22, '2004-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 12, 'Softball', 'Malcolm is convinced to play Softball by Lois and ends up doing very badly at it due to Lois''s hold on him. Meanwhile, Francis tries to pick fights with Lois, Reese tries to break Francis''s record of collecting toilet seats from a local junkyard, and Hal accidentally applies to become a member of the CIA.', 22, '2004-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 13, 'Lois''s Sister', 'Lois'' younger sister, Susan, pays the family a visit and brings with her expensive gifts for the boys, biting remarks for Lois and a cold shoulder for Hal – whom she has never forgiven for dumping her for Lois. Lois and Susan''s competitive relationship takes a turn for the worse when Susan gives Malcolm and Reese her prize ''65 Mustang convertible. But when Lois discovers that Susan needs a kidney transplant, she puts her anger aside and offers to donate her kidney to Susan, which Susan only sees as the perfect opportunity for Lois to one-up her.', 22, '2004-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 14, 'Malcolm Dates a Family', 'Lois blows her top over a hidden 15 percent surcharge on the bill at her family''s favorite pizza place and stages a boycott...but Hal and the boys are sneaking slices on the side. Malcolm meets Angela and becomes instantly smitten with her intellectual family...but starts to feel like a heel because he''s asked another girl to the school dance and is forced to break it off with her--er--them. And Francis is reluctant to let Otto hire an assistant for him...but soon comes to like the idea.', 22, '2004-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 15, 'Reese''s Apartment', 'Francis is determined to show his parents why they should not have kicked Reese out. Meanwhile, Malcolm helps a football player write a college essay.', 22, '2004-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 16, 'Malcolm Visits College', 'Lois tags along with Malcolm as he visits a college, but she''s determined to room in the dorm Malcolm is staying in when she learns the room is co-ed. Meanwhile, after his father denies him a piano, Dewey begins stealing objects from around the house to amuse himself and to drive Hal crazy. Reese meets a girl, who he thinks is a narc, and he pretends he is a dealer, unaware that she is really an undercover cop.', 22, '2004-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 17, 'Polly in the Middle', 'Hal sets up Abe Kenarben on a blind date with Jaime''s babysitter Polly but then realizes Lois has also set her up on a blind date - with Craig. Malcolm, Dewey (with his "lucky" shirt) and Reese also meet Reggie Jackson and Francis is embarrassed by Piama in front of his co-workers.', 22, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 18, 'Dewey''s Special Class', 'Malcolm convinces Dewey to do poorly on an I.Q. test, so that he won''t become a ridiculed Krelboyne student. But Dewey does so badly that he is placed in a class for the emotionally disturbed. Hal and Craig compete in a dance competition.', 22, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 19, 'Experiment', 'When Dewey''s annual candy selling event for school comes up, he uses the excuse of "these bars help support america" to sell them. Malcolm and Stevie attempt a science experiment, and are shocked when Reese begs to help.', 22, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 20, 'Victor''s Other Family', 'When Lois tracks down her father''s "other family," she meets Victor''s "other wife" Sylvia, and learns something shocking about her dad.', 22, '2004-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 21, 'Reese Joins the Army (1)', 'Reese''s new girlfriend Beth is about as dumb as he is. Malcolm initially dislikes her but they soon get to like each other too much and Beth breaks up with Reese. Devastated, Reese runs away and joins the army under the false surname.', 22, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 5), 22, 'Reese Joins the Army (2)', 'Reese continues to be a great soldier in the Army until he finds himself in a situation where his Sergeant cannot help. But after comparing being captured to being grounded, he takes action and leads his team to victory. But being such a successful soldier has it''s bad parts as well, as Reese prepares to jump from the plane - right into Afghanistan. Malcolm has his hands full as well as he attempts to prove Hal innocent. But being good with numbers helps as Malcolm notices all of the prosecutions given dates are on Fridays - which Hal hasn''t worked on in over 15 years. And with Reese missing and Hal''s case, Lois falls deeper and deeper into insanity.', 22, '2004-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 6, 'Season 6', 'As Malcolm enters his senior year, he faces the pressures of impending adulthood. Reese and Dewey continue their usual antics, and Hal and Lois deal with the complexities of raising their unconventional family.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 1, 'Reese Comes Home (3)', 'When Reese realizes the Army is too much for him to handle, he deserts and dresses as an Afghani woman. But Lois is on a march to find him, and travels to Kabul to hunt him down. Meanwhile, Malcolm volunteers at a veterans hospital as a way to make up for his guilt of making Reese leave.', 22, '2004-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 2, 'Buseys Run Away', 'The Buseys disappear after Dewey leaves the special-needs class; Hal becomes the leader of a group of brainless bodybuilders.', 22, '2004-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 3, 'Standee', 'When Hal and the garbageman get into a trash-dumping war (which benefits Dewey more than anyone else), Hal enlists Reese''s help. Meanwhile, Lois gets her job back at Lucky Aide (off probation), and fights against Malcolm in order to take down an offensive billboard of a smiling black janitor (whose nametag reads "Slappy") holding a mop and a 6-pack of malt liquor. Soon it''s an all-out war between mom and son - until Lois encounters a fellow employee who is more racist than the billboard.', 22, '2004-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 4, 'Pearl Harbor', 'Malcolm and Reese plot revenge after they realize their teenage neighbor has tricked each of them into believing the other is gay. Meanwhile, Hal, tired of competing with a neighbor who always outdoes his Christmas decorations, decides to create his own "holiday" to decorate his house for - Pearl Harbor Day.', 22, '2004-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 5, 'Kitty''s Back', 'Kitty returns and asks Lois for help getting Kitty''s estranged husband back; Francis comes home and puts Dewey through the torturous "Brotherhood Initiation."', 22, '2004-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 6, 'Hal''s Christmas Gift', 'Hal and Lois, strapped for cash, decide that Christmas gifts will have to be homemade this year. When everyone makes much better gifts than Hal, he spins a bigger and bigger lie about the present he has in store for them. In desperation, Hal pick-pockets Malcolm''s secret credit card, and buys the family a ski vacation.', 22, '2004-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 7, 'Hal Sleepwalks', 'Hal is sleepless because of their upcoming 20th wedding anniversary. So he ask Reese for some ideas for presents. Then Reese gets the idea to brainwash his dad while he''s nervous. Dewey''s friends are set up in an upcoming student body election when a bully nominated two of his geeky friends. Malcolm takes up playing the electric guitar, though Lois discourages his musical ability. He writes a heart warming song. When he plays & sings his creation, Dewey figures out that his song is sung to the tune of the "Meow Mix" jingle!', 22, '2005-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 8, 'Lois Battles Jamie', 'Lois thinks Jamie is out to get her when Jamie knocks over a shelf and nearly crushes her.', 22, '2005-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 9, 'Malcolm''s Car', 'When Malcolm spots a roughed up 1967 Cuda in his neighborhood, he instantly falls in love with it and purchases the car. But he gets so caught up in the difficult task of restoring it that he blows off Stevie as well as Reese who needs him for an illegal betting scheme of his. Hal on the other hand, is having success when he stumbles upon his hidden talent -- hairstyling. Lois doesn''t have time to worry about Malcolm or Hal, as she is caught up in scandal between Craig and their Lucky Aide boss Fred. Craig says he is taking time off to tutor Fred''s wife in golf but Lois finds out he is actually having an affair with her.', 22, '2005-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 10, 'Billboard', 'When Lois catches the boys vandalizing a trashy billboard for a strip club, Malcolm alters the vandalism into a women''s rights protest, which sparks a colossal media circus. In no time, feminists, conservative religious groups and national new reporters descend on the scene. After Hal grants a TV interview, a woman from his past turns up at the faux protest; and Reese, inspired by the giant billboard stripper who comes to life in his dreams, gives an impassioned speech about the objectification of women.', 22, '2005-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 11, 'Dewey''s Opera', 'When Lois buys a brand-new king-sized bed, Hal thinks that her motive is to put more distance between them and refuses to sleep in it. Moved to tears by an opera he sees on television, Dewey is inspired to write his own operatic masterpiece, "The Marriage Bed," which is based on his parents'' fight and turned into a school production. Meanwhile, Malcolm and Reese build their own street luge board; and Jamie falls head over heels for the baby girl across the street.', 22, '2005-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 12, 'Living Will', 'Hal is named executor of his neighbor''s living will and must decide whether to keep him on life support or pull the plug. In attempting to make the decision, Hal discovers he is incapable of making decisions on his own because he always defers to Lois. Meanwhile, Craig asks Malcolm, Reese and Dewey to teach him how to fight dirty since a bully from his childhood is coming to town.', 22, '2005-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 13, 'Tiki Lounge', 'When Hal and Lois realize how little time they spend together, Hal turns the garage into a private tiki lounge where he and Lois can retreat. Things go smoothly until they feud over philosophical beliefs. Meanwhile, Mr. Herkabe cons Malcolm into joining the Booster Club, where he learns a lesson about taking one for the team.', 22, '2005-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 14, 'Ida Loses a Leg', 'During Grandma''s unwelcome visit with the family, she loses her leg while saving Dewey from a moving truck. Consumed with guilt, Dewey is determined to find his Grandmother''s leg and give it the proper burial. Francis, on the other hand, begrudgingly becomes the caretaker for his stubborn, cranky grandmother. Meanwhile, Malcolm and Reese are given a new idea for a prank that forces them to stay awake days at a time to avoid the embarrassment of having their faces glued to the floor.', 22, '2005-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 15, 'Chad''s Sleepover', 'After Hal forbids Dewey from inviting his peculiar classmate Chad over for a sleepover, Dewey quickly finds out that his father had good reason to warm him. Meanwhile, Malcolm and Reese find out that they are not as popular as they once thought, then plot "revenge" on their classmates.', 22, '2005-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 16, 'No Motorcycles', 'When Francis and Piama choose to celebrate Francis'' 21st birthday at the house, Hal is reminded of a promise he made to his son as a young child, involving a motorcycle trip that Lois quickly forbids. Hal and Francis have no choice but to sneak off for their wild adventure, leaving their women behind. Meanwhile Malcolm, Dewey and Reese are held captive in their own home by a bully.', 22, '2005-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 17, 'Butterflies', 'Malcolm discovers a man, Norm, living in the Lucky Aide. He agrees to keep Norm''s secret as long as he provides Malcolm with tidbits on his new crush, a fellow Lucky Aide employee. Meanwhile, when Reese takes a job as an exterminator, he quickly learns that to drum up business he must infest the neighbors'' lawns, and chooses caterpillars as his weapon. But instead of spreading the caterpillars, he has a change of heart and begins to nurture them, ultimately leading to his own menagerie of butterflies.', 22, '2005-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 18, 'Ida''s Dance', 'Lois goes over to visit Ida, but gets unpleasantly surprised by the St. Grotus Day festival. Malcolm fails a music appreciation course, and reluctantly goes to Dewey for help. Reese and Hal secretly watch scary movies while Lois is not around, but it ends up revealing some unexpected secrets about both Reese and Hal.', 22, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 19, 'Motivational Seminar', 'Reese befriends a pack of troublesome stray dogs; Dewey feels conflicted when he starts seeing another mother-figure; Hal unwittingly becomes a motivational speaker.', 22, '2005-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 20, 'Stilts', 'After Lois and Hal are reminded of the tight budget they must uphold, Hal discovers one of his boys has been dialing a 900 number. His attempt to explain the error to the hotline''s billing department turns awry when he forgets to hang up the phone, incurring a whopping $800 charge. Meanwhile, Reese takes a job at a research clinic that pays him to pop experimental pills, and a reluctant Malcolm takes on a mortifying job at the Lucky Aide as a costumed Uncle Sam on stilts.', 22, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 21, 'Buseys Take a Hostage', 'When Hal decides to attend his first annual Neighborhood Association meeting with Malcolm, he is strongly encouraged to take on the role of President. Being his dad''s right-hand man, Malcolm sees a perfect opportunity to add some excitement to the community, while Hal''s agenda is a little bit different. Meanwhile, Francis takes on a new job as a camp activities coordinator and turns to Dewey for his input on some creative new games. While Dewey revels in his afternoon of fun, his fed-up classmates take their teacher, principal and janitor hostage.', 22, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 6), 22, 'Mrs. Tri-County', 'Unbeknownst to Lois, the boys enter her in the Mrs. Tri-County Pageant as a joke. When they overhear the other contestants remarking that Lois doesn''t have a chance of winning, they plot to help their mother take the crown. Meanwhile, Malcolm is blackmailed into delivering love notes to a contestant for Herkabe, and Reese discovers that, according to the Mrs. Tri-County Pageant manual''s scientific formula, he is beautiful.', 22, '2005-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')), 7, 'Season 7', 'In the final season, Malcolm prepares for graduation and contemplates his future. The family’s journey culminates in a series of events that highlight their growth, resilience, and the enduring bond that holds them together.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 1, 'Burning Man', 'The family attends the counterculture Burning Man festival in the desert.', 22, '2005-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 2, 'Health Insurance', 'When Hal forgets to pay the family''s health insurance, the company will not reinstate it until Monday, so he panics and locks the boys in their room to keep them from getting hurt.', 22, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 3, 'Reese vs. Stevie', 'When Hal catches Dewey smoking, he makes a deal with him that he will stop drinking coffee if Dewey quits smoking.', 22, '2005-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 4, 'Halloween', 'Reese and Malcolm try to perform the ultimate Halloween prank.', 22, '2005-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 5, 'Jessica Stays Over', 'When Jessica goes through some family troubles, Lois agrees to let her stay at the house, making the boys crazy.', 22, '2005-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 6, 'Secret Boyfriend', 'When Malcolm gets paired with a dimwitted beauty as his chemistry partner, he thinks it''s a recipe for disaster, but when she reveals her feelings for him, sparks fly. They agree to keep their romantic experiment under wraps until Malcolm realizes that she''s just embarrassed to be dating him. Meanwhile, Lois demands that Reese get a job, and she kicks him out of the house to prove that she means business.', 22, '2005-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 7, 'Blackout', 'Francis decides to surprise the family by coming home, and the power goes out in the house. Meanwhile, it''s Lois who''s in the dark when Hal decides to cancel their anniversary dinner in favor of a Reese-cooked meal at home. And Malcolm ends up in hot water after he sneaks three Dutch girls into the house.', 22, '2005-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 8, 'Army Buddy', 'When Lois finds renewed energy with orthotic inserts for her shoes, Hal fears she will not look to him for support anymore and plots to destroy the inserts. A former female army buddy of Reese''s comes to their house for a visit. But she gets defensive when Reese thinks they are way more than just friends and comes intact to the idea of trying to sleep with her.', 22, '2005-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 9, 'Malcolm Defends Reese', 'Lois thinks the new babysitter she found for Jamie is perfect... until she starts driving Lois crazy. Meanwhile, Reese starts getting picked on by the teacher when he and Malcolm are in the same class. However, Malcolm decides to defend him.', 22, '2005-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 10, 'Malcolm''s Money', 'Malcolm receives a check for $10,000. After Hal and Lois find out, they decide to keep the money and spend it on something for themselves. However, when Dewey overhears this, he wants to get in on it, too. Now, they''ll have to find a way to pay Malcolm back.', 22, '2006-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 11, 'Bride of Ida (1)', 'Lois, Hal, and Dewey go out of town for a piano competition, so they get Ida to watch over Malcolm and Reese while they''re gone. Since Ida thinks Reese needs to become a man, she comes up with a competition for Malcolm and Reese, and if Reese wins, he can take Raduca as his bride. Now, when Lois and Hal return, they''re surprised to find out that Reese has run away to Las Vegas to get married.', 22, '2006-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 12, 'College Recruiters (2)', 'A broke Francis gets talked into getting a real job by Dewey, but one of Francis'' rocker friends decides to offer him the position of tour manager of his band instead. Back home, Hal takes over the college recruiters, which Malcolm refuses to meet with, and treats each one as a suitor. However, Hal''s plans are ruined when Malcolm chooses to go Harvard.', 22, '2006-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 13, 'Mono', 'Lois discovers she has mono after a visit to the doctor. She then ends up giving it to Malcolm after her maternal instincts begin. As a result, both Lois and Malcolm are forced to spend an entire day and night together in the same room. Hal, meanwhile, is invited to all of his neighbors'' parties after they know Lois will not be attending any of them.', 22, '2006-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 14, 'Hal Grieves', 'Hal learns that his father has passed away, but sheds no tears and passes it off as nothing since he never knew him. So, to make sure nothing like that happens again, he lets the boys do whatever they want by letting them miss school and even offering to buy Malcolm a new car, until Lois puts a stop to it. Noticing how depressed Hal has become, his friend Abe brings George Takei over for a visit in an attempt to cheer him up.', 22, '2006-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 15, 'A.A.', 'Francis receives a visit from Lois and Hal to celebrate his one-year anniversary of sobriety. However, when they attend one of his A.A. meetings, it''s revealed that it was Lois who forced him to start drinking. Back home, Dewey finds Hal''s spare key for his car and tries to get Malcolm and Reese to drive him to the arcade, but, of course, they refuse.', 22, '2006-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 16, 'Lois Strikes Back', 'When four popular high school girls play an evil prank on Reese by pretending he has a secret admirer and then dropping a pig off at his front door, Lois comes to his rescue. She plots her revenge on the four unsuspecting girls and wreaks havoc on their adolescent lives. Meanwhile, Hal realizes Lois is at a dangerous emotional place so he decides to get some distance and stumbles upon the idea for making his own pitching machine out of stuff in the garage.', 22, '2006-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 17, 'Hal''s Dentist', 'Hal''s friend Trey tells him to come to his dental office when he looses a tooth during a poker game, but their friendship becomes in jeopardy when Hal''s faced with a $2,000 bill and causes a fight between them. Reese, meanwhile, teaches Lois how to ride a bike, while Malcolm and Dewey find sleeping as their new favorite pastime.', 22, '2006-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 18, 'Bomb Shelter', 'Malcolm joins a local dance class to impress a girl, but when she loses her footing, he realizes that to win the competition he''ll need a partner who can step it up. Dick, a rival student in the class who takes dancing a bit too seriously, challenges Malcolm to a dance-off. Meanwhile, Hal discovers an underground bachelor pad in the backyard.', 22, '2006-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 19, 'Stevie in the Hospital', 'When Stevie goes to the hospital, Malcolm tries making up every excuse he can think of to not go because he can''t face the truth about his illness. Meanwhile, back home, Hal gets highly competitive about his new remote control boat, while Lois thinks she''s going insane.', 22, '2006-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 20, 'Cattle Court', 'Reese meets a cute vegetarian named Carrie when he goes back to work at the meat plant. At first, he goes along with her political talk, but she catches him with a pork chop. So, to get Carrie back, he sets free all the cows at the meat plant. Malcolm, meanwhile, tries to fool Lois in order to attend a rock concert.', 22, '2006-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 21, 'Morp', 'For the senior prom, Reese gets paid to take Janine, a studious girl in class, but only after she gives him a makeover and sends him to finishing school, while Malcolm aligns with the unpopular kids to form an anti-prom they call "Morp." Unfortunately, while Malcolm and his friends protest the official dance, they don''t know how to make their "Morp" exciting. Meanwhile, Dewey discovers there aren''t any childhood pictures of him, so he concocts an elaborate scavenger hunt to punish Hal and Lois.', 22, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0212671')) AND numero_temporada = 7), 22, 'Graduation', 'Malcolm struggles with his speech when he''s elected valedictorian of his graduating class at school. However, Lois refuses to listen to any of his complaints and reveals that she wants him to become President of the United States. Meanwhile, Reese does everything he can to get a permanent job as a high school janitor, which includes creating the most disgusting mess ever. In the meantime, Hal has problems with Malcolm''s Harvard tuition, while Francis finally gets a real 9-5 job that he actually enjoys. Also returning for the family celebrations is Grandma Ida, as they all say goodbye to Malcolm when he leaves for college.', 22, '2006-05-14');
