INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0220880')) AND numero_temporada = 4), 24, 'Remembrance of Courage Past', 'Courage becomes depressed after thinking of his parents.', 11, '2002-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0220880')) AND numero_temporada = 4), 25, 'Perfect', 'Fed up with Courage''s incompetence, Eustace seeks a professional dog trainer.', 11, '2002-11-22');
