INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 1, 'Help Wanted', 'SpongeBob goes to the Krusty Krab to apply for the new fry cook job. Against the advice of Squidward, Mr. Krabs, the owner of the restaurant decides to give SpongeBob a chance. Can SpongeBob find the spatula needed for the job and serve all the hungry customers?', 8, '1999-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 2, 'Reef Blower', 'Squidward and SpongeBob are cleaning up their yards with their reef blowers. When one person ends up cleaning their yard, the others gets ruined. Who will get the clean yard in the end?', 3, '1999-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 3, 'Tea at the Treedome', 'SpongeBob meets a land squirrel named Sandy. He is invited to come over to her house, but he finds out that it is full of air. SpongeBob holds out for as long as he can, which isn''t a very long time.', 12, '1999-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 4, 'Bubblestand', 'SpongeBob and Patrick are blowing bubbles. Squidward thinks it is a simple task, but he can''t blow one single bubble. SpongeBob and Patrick need to teach him the proper bubble blowing technique.', 12, '1999-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 5, 'Ripped Pants', 'While at Goo Lagoon, SpongeBob accidentally rips his pants while trying to impress Sandy, causing everyone to laugh.', 12, '1999-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 6, 'Jellyfishing', 'To make Squidward feel better after a biking accident, SpongeBob and Patrick take him to go Jellyfishing.', 12, '1999-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 7, 'Plankton!', 'Plankton is always trying to steal the secret Krabby Patty formula, but his tiny size gets in his way. In Plankton''s latest scheme, he controls SpongeBob''s brain to try and steal the Krabby Patty recipe.', 12, '1999-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 8, 'Naughty Nautical Neighbors', 'Squidward is having a peaceful day, until he hears giggling from next door. He gets SpongeBob and Patrick to believe that they hate each other, but now they want to be his best friend.', 12, '1999-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 9, 'Boating School', 'SpongeBob is going to take a driving test, a synonym for disaster. This time is a little different, as SpongeBob gets some help from Patrick.', 12, '1999-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 10, 'Pizza Delivery', 'A customer calls and asks the Krusty Krab to deliver him some pizza. Mr. Krabs orders SpongeBob and Squidward to deliver it. SpongeBob will stop at nothing to get the pizza to the customer, even if that means getting lost.', 12, '1999-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 11, 'Home Sweet Pineapple', 'One night, some nematodes feast on SpongeBob''s pineapple house. All that is left is a tiny pebble. Now, SpongeBob must live with his parents! How will he get a new house?', 12, '1999-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 12, 'Mermaid Man and Barnacle Boy', 'SpongeBob and Patrick find that their television heroes, Mermaid Man and Barnacle Boy, are retired old people. SpongeBob and Patrick try to get them back into Superhero business again.', 12, '1999-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 13, 'Pickles', 'SpongeBob gives an incomplete Krabby Patty to Bubble Bass for the first time. SpongeBob goes crazy, and forgets how to do everything, including his job.', 12, '1999-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 14, 'Hall Monitor', 'SpongeBob is finally given the chance to be a hall monitor at his boating school, but he wastes the school day giving a speech and doesn''t get to do anything. That doesn''t mean he can''t be a Hall Monitor outside of school, right?', 12, '1999-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 15, 'Jellyfish Jam', 'A wild jellyfish follows SpongeBob home, so he decides to keep it. The jellyfish loves to party and dance. Unluckily, SpongeBob''s house turns into a party overnight with more jellyfish coming by the second.', 12, '1999-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 16, 'Sandy''s Rocket', 'SpongeBob and Patrick accidentally launch Sandy''s rocket, and land back in Bikini Bottom. They think they''ve landed on the moon and that everyone in Bikini Bottom are aliens.', 12, '1999-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 17, 'Squeaky Boots', 'Mr. Krabs gives SpongeBob a pair of "special" boots because he bought them for Pearl, but she didn''t want them. SpongeBob loves them, but the squeaking drives Mr. Krabs crazy.', 12, '1999-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 18, 'Nature Pants', 'SpongeBob wants to give up his current life to live with the jellyfish against the wishes of all his friends. But, SpongeBob learns that a jellyfish life is not an easy one.', 12, '1999-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 19, 'Opposite Day', 'Squidward gets so mad at SpongeBob and Patrick, he decides to sell his house. Squidward needs to get rid of his annoying neighbors so he can sell his house. He tells SpongeBob and Patrick that it is "Opposite Day." Squid hopes that they will act the opposite of what they usually are, annoying. Of course, it doesn''t work out as planned.', 12, '1999-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 20, 'Culture Shock', 'A talent show is taking place at the Krusty Krab to get more customers and more money, and Squidward is in charge. He will do anything to prevent SpongeBob from doing participating in it.', 12, '1999-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 21, 'F.U.N.', 'SpongeBob thinks that Plankton is evil only because he is lonely and has no friends. SpongeBob becomes Plankton''s friend and plays with him. But, Mr. Krabs is convinced that Plankton is evil and that SpongeBob should not be hanging around with him.', 12, '1999-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 22, 'MuscleBob BuffPants', 'SpongeBob thinks he can get more attention if he becomes physically fit. But he soon finds that exercise is hard work, and orders "anchor arms," which he inflates with air, and looks buff. Everyone finds out how fake he is when Sandy signs him up for the annual anchor toss competition at Muscle Beach.', 12, '1999-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 23, 'Squidward the Unfriendly Ghost', 'SpongeBob thinks he accidentally killed Squidward, so Squidward decides to use it for his advantage. Threatening to haunt them for the rest of their lives, Squidward makes SpongeBob and Patrick his servants.', 12, '1999-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 24, 'The Chaperone', 'SpongeBob takes Pearl to the prom because her previous prom date dumped her, and she is very emotional about it. SpongeBob and Pearl cause all kinds of mischief, and they eventually get thrown out of the prom.', 12, '1999-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 25, 'Employee of the Month', 'SpongeBob must try to uphold his position as "Employee of the Month," which he has won for 27 months in a row. But, when Squidward tells him the award is a scam, SpongeBob starts to tease Squidward by saying he could never be "Employee of the Month." Squidward challenges SpongeBob, and then make a mess of everything.', 12, '1999-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 26, 'Scaredy Pants', 'It''s Halloween and SpongeBob tries to scare some kids as "The Flying Dutchman," but the kids just laugh at his silly costume. SpongeBob gets Patrick to shave his head round, so he will look more like a ghost. He goes to the Krusty Krab to show off his costume, but everyone is more afraid of what is inside the costume.', 11, '1999-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 27, 'I Was a Teenage Gary', 'Gary becomes sick when Squidward forgets to feed him, so a doctor has to come and give Gary some medicine. The doctor has Squidward give Gary the shot. Squidward accidentally gives the medicine to SpongeBob instead of Gary, which turns SpongeBob into a snail.', 11, '1999-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 28, 'SB-129', 'Squidward becomes frozen while hiding from SpongeBob and Patrick. He stays frozen for so long, he wakes up in the future. Once he''s in the future, he thinks he will be able to get away from SpongeBob and Patrick, but it seems where ever he goes, they are always there somehow.', 12, '1999-12-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 29, 'Karate Choppers', 'SpongeBob and Sandy just can''t stop practicing karate, even after Mr. Krabs warns SpongeBob that he will be fired. Soon Mr. Krabs finds them in the park using karate to make sandwiches, so he hires them both to make Krabby Patties at a super fast rate using Karate.', 12, '1999-12-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 30, 'Sleepy Time', 'SpongeBob leaves his dream in order to see what everyone else is dreaming about. But the other citizens of Bikini Bottom don''t appreciate this because in the process of his "Dream Exploring" he wakes everyone up and disturbs their sleep.', 12, '2000-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 31, 'Suds', 'SpongeBob becomes sick after he leaves the door to the fridge open, and his house becomes icy. But when he gets ready to go to the doctor, Patrick scares him, and tries to cure SpongeBob himself.', 12, '2000-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 32, 'Valentine''s Day', 'SpongeBob wants to give Patrick the best Valentine''s Day gift ever, a chocolate heart shaped hot air balloon. Sandy starts to drive it over to SpongeBob and Patrick at the Valentine Day fair but, scallops attack the balloon, and SpongeBob must stall for time. Patrick goes crazy waiting for his gift, and starts to attack people at the fair.', 12, '2000-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 33, 'The Paper', 'SpongeBob gets a small piece of paper from Squidward to play with. Squidward thinks that the paper is useless and just gives it away. SpongeBob soon does many fun things with it, and makes Squidward very jealous.', 12, '2000-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 34, 'Arrgh!', 'SpongeBob and Patrick play a pirate board game based on a real treasure map. Mr. Krabs joins in and wins a bunch of times in a row. The next day, Mr. Krabs takes the two boys on a treasure hunt, but they find out later that Mr. Krabs is using the game as a map, and is going crazy trying to find the Flying Dutchman''s treasure.', 12, '2000-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 35, 'Rock Bottom', 'SpongeBob and Patrick accidentally get on the wrong bus coming out of an amusement park called Glove World, and head for a city named Rock Bottom. When they get there, Patrick gets on a bus back to Bikini Bottom, and leaves SpongeBob by mistake. How will SpongeBob ever get home?', 12, '2000-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 36, 'Texas', 'Sandy gets homesick, so SpongeBob and Patrick do as much as they can to cheer her up. When they want to throw her a surprise party and she won''t come, SpongeBob and Patrick make Sandy chase them to the Krusty Krab, where the party is being held.', 12, '2000-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 37, 'Walking Small', 'Plankton''s newest scheme involves getting someone to scare everyone away from "Goo Lagoon" so he can create his new restaurant, "The Mega Bucket." He tricks SpongeBob into scaring everyone away from the beach, until SpongeBob realizes what he is doing is wrong.', 12, '2000-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 38, 'Fools in April', 'Squidward wakes up and finds out it is April Fools Day. April Fools Day is SpongeBob''s favorite holiday so Squidward becomes paranoid, thinking SpongeBob will play a joke on him. Squidward plays a mean trick on SpongeBob, but after SpongeBob runs home crying, Squidward must apologize.', 12, '2000-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 39, 'Neptune''s Spatula', 'SpongeBob and Patrick go to the Fry Cook Museum and are looking at the exhibits, when they come across the a spatula stuck in hardened grease. This spatula could only be pulled out by a fry cook worthy enough to cook for Neptune himself. SpongeBob pulls the spatula out with ease, and is excepted to move to Atlantis as Neptune''s fry cook! But, when Neptune tells SpongeBob he cannot bring his friends, SpongeBob starts to reconsider. Will SpongeBob leave his friends behind?', 12, '2000-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 40, 'Hooky', 'Patrick introduces SpongeBob to a carnival but this "carnival" is really colored fishing hooks dropped by fishermen on land. Mr. Krabs warns SpongeBob to stay away and how dangerous they are, but Patrick keeps on talking about how fun they are. Who will SpongeBob listen to, Patrick or Mr. Krabs?', 12, '2000-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 1), 41, 'Mermaid Man and Barnacle Boy II', 'SpongeBob is awarded a prize for his life size Krabby Patty sculptures of Mermaid Man and Barnacle Boy. The prize is the "Magic Conch" as seen in many episodes of the television show "The Adventures of Mermaid Man and Barnacle Boy." The conch shell, when blown, will make a noise and Mermaid Man and Barnacle Boy will come running! It is meant only for danger. SpongeBob blows the conch for simple chores. Will the heroes be so annoyed they must take back the conch?', 12, '2000-04-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 1, 'Something Smells', 'SpongeBob eats a peanut onion sundae and acquires a hideous case of bad breath. And he can''t quite understand why everyone runs away from him whenever he talks to them.', 11, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 2, 'Bossy Boots', 'When Pearl remodels the Krusty Krab into a hip local hangout, SpongeBob worries about the fate of the original restaurant (not to mention, his position as Fry Cook!).', 11, '2000-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 3, 'Your Shoe''s Untied', 'SpongeBob forgets how to tie his shoes, so he must re-learn how. But no one else knows how, either.', 11, '2000-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 4, 'Squid''s Day Off', 'Squidward is put in charge of the Krusty Krab when Mr. Krabs goes to the hospital and decides to take the day off, but can''t help thinking SpongeBob will do something wrong.', 11, '2000-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 5, 'Big Pink Loser', 'Patrick realizes that he has never won any awards in his life, so he decides to copy everything that SpongeBob does. SpongeBob has won countless awards, so Patrick is sure that he will win one.', 11, '2000-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 6, 'Bubble Buddy', 'When no one will play with SpongeBob, he creates his own bubble buddy, but it causes many problems around town.', 11, '2000-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 7, 'Mermaid Man & Barnacle Boy III', 'Mermaid Man and Barnacle Boy decide to go on vacation, but unfortunately they don''t have anyone to look after the Merma-lair, so they ask SpongeBob and Patrick to look after it. However, they accidentally release Man Ray from a prison made of frozen tartar sauce.', 11, '2000-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 8, 'Squirrel Jokes', 'SpongeBob tells jokes in a talent show at the Krusty Krab, but ends up saying jokes about squirrels, which makes Sandy mad.', 11, '2000-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 9, 'Christmas Who?', 'SpongeBob brings Christmas to Bikini Bottom.', 24, '2000-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 10, 'Dying for Pie', 'It''s employee brotherhood day and Squidward has nothing to give to SpongeBob, so he accidentally gives SpongeBob a pie bomb. Squidward spends the whole day with SpongeBob because SpongeBob only has one day to live.', 11, '2000-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 11, 'Imitation Krabs', 'In another attempt to steal the Krabby Patty formula, Plankton makes a robot that looks just like Mr. Krabs. But in order to get the formula, he will have to do some odd things as part of the "secret handshake."', 11, '2000-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 12, 'Wormy', 'Sandy is going away and calls SpongeBob and Patrick to take care of her pets. One of them is a worm, and SpongeBob and Patrick have fun with it all day long, until the next day when it transforms into a butterfly and everybody in town gets scared of it.', 11, '2001-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 13, 'Patty Hype', 'The Krusty Krab hasn''t had costumers in weeks, so SpongeBob comes up with an idea, but Mr. Krabs and Squidward laugh at the idea. So SpongeBob opens his own restaurant and becomes a huge success in Bikini Bottom.', 11, '2001-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 14, 'Survival of the Idiots', 'Despite Sandy''s warning, SpongeBob and Patrick sneak into her treedome, during a terrible snowstorm and since the doorknob is frozen, SpongeBob and Patrick realize they have to wait until spring. Will SpongeBob and Patrick be able to survive the entire winter? Or will Sandy, and the cold weather, stop them first?', 11, '2001-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 15, 'Dumped', 'Suddenly, Gary seems to be hanging out with Patrick more than SpongeBob. SpongeBob thinks it''s because he loves Patrick more. But, what''s the real reason that Gary is attached to Patrick all of a sudden?', 11, '2001-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 16, 'Grandma''s Kisses', 'SpongeBob asks his grandma not to kiss him because her public displays of affection are embarrassing.', 11, '2001-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 17, 'Squidville', 'Squidward is fed up with living next to Spongebob and Patrick, so he finds new neighbors who are more like himself.', 11, '2001-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 18, 'No Free Rides', 'To avoid another year with SpongeBob in her class, Mrs. Puff passes him with bogus extra credit and lets him have his license, but soon realizes that the consequences are beyond bad. When SpongeBob receives a new boat-mobile from his parents, Mrs. Puff attempts to steal it, and SpongeBob will stop at nothing to stop her.', 11, '2001-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 19, 'I''m Your Biggest Fanatic', 'While at a jellyfishing fan convention, SpongeBob meets Kevin C. Cucumber, who gives him a chance to see if he can join his club, The Jellyspotters. However, SpongeBob is unaware that Kevin is only trying to make a fool out of him, but soon discovers the truth after the club attacks him with a robotic queen jellyfish.', 11, '2001-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 20, 'Pressure', 'Sandy and SpongeBob get into a fierce competition doing extreme underwater sports.', 11, '2001-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 21, 'The Smoking Peanut', 'SpongeBob accidentally throws a peanut at Clamu the Oyster and then the police think that the one who threw the peanut was Patrick.', 11, '2001-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 22, 'Shanghaied', 'When a giant anchor falls onto SpongeBob''s house, Squidward, SpongeBob and Patrick decide to climb the anchor, and they find the boat of the Flying Dutchman, who imprisons them.', 17, '2001-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 23, 'Prehibernation Week', 'Sandy is going wild over the fact that she will have to hibernate in a week.', 11, '2001-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 24, 'Life of Crime', 'SpongeBob and Patrick find out that you can borrow anything without permission as long as you return it, or that''s what wise Mr. Krabs says. SpongeBob and Patrick want a balloon, but neither one has any money, so they "borrow" it and it pops. They decide to run away and live like criminals, because they think they''re now "thieves."', 11, '2001-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 25, 'The Secret Box', 'Patrick keeps a small box everywhere he goes and refuses to tell SpongeBob what''s in it. Curiosity eventually gets the better of our spongy hero, as he decides to try and sneak a peek while Patrick is sleeping.', 11, '2001-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 26, 'Band Geeks', 'Squidward enlists the aid of SpongeBob and the rest of Bikini Bottom to form a marching band to impress Squidward''s old high school rival, Squilliam Fancyson.', 11, '2001-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 27, 'Sailor Mouth', 'SpongeBob and Patrick pick up a "bad word," and start repeating it to the shocked patrons of the Krusty Krab, but Mr. Krabs doesn''t like this!', 11, '2001-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 28, 'Artist Unknown', 'Squidward starts to teach an art class at the Recreation Center, but SpongeBob is the only person who shows up.', 11, '2001-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 29, 'Jellyfish Hunter', 'Mr. Krab''s turns SpongeBob''s idea for ''Jelly Krabby Patties'' into a colossal customer favorite, and it leads to trouble when the local population of jellyfish become hunted to near-extinction.', 11, '2001-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 30, 'The Fry Cook Games', 'SpongeBob and Patrick compete in the Fry Cook Games after they get in a fight. Who will come out victorious?', 11, '2001-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 31, 'Just One Bite', 'When SpongeBob learns that Squidward has never actually tried a Krabby Patty, he becomes obsessed with the idea that Squidward must try it.', 11, '2001-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 32, 'The Bully', 'At boating school, a new student shows up, but he says he''s gonna kick SpongeBob''s butt!', 11, '2001-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 33, 'Squid on Strike', 'SpongeBob and Squidward go on strike after they don''t get their paycheck from Mr. Krabs. How long will the strike last?', 11, '2001-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 34, 'Sandy, SpongeBob, and the Worm', 'An Alaskan Bull Worm is on the loose in Bikini Bottom, and Sandy must stop it from destroying the town.', 11, '2001-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 35, 'Procrastination', 'SpongeBob must write an 800-word essay for boating school but gets distracted easily.', 11, '2001-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 2), 36, 'I''m with Stupid', 'Patrick''s parents are coming over and Patrick doesn''t want to look stupid, so he tells SpongeBob to be stupider than him.', 11, '2001-11-30');
