INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 3), 7, 'Nasty Patty', 'A health inspector shows up at the Krusty Krab, and while he is there, SpongeBob and Mr. Krabs see the news about a guy passing himself off as a health inspector to get free food.  Mr. Krabs is so mad he and SpongeBob make a Krabby Patty made with a bunch of nasty things. After it is served to the inspector he chokes on a fly and the two think he died from the patty. They later find out that he was a real health inspector, and that the other one was caught. Now, what will SpongeBob and Mr. Krabs do with the dead health inspector?', 11, '2002-03-01');
