INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 3), 38, 'The Camping Episode', 'SpongeBob and Patrick decide to go camping for the weekend, they camp out in the backyard. Squidward lures a sea bear to the campsite by doing stuff that would allure a sea bear.', 11, '2004-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 3), 39, 'SpongeBob Meets the Strangler', 'SpongeBob goes on his early litter patrol when he catches The Strangler. After he calls the police, The Strangler (disguised with a fake mustache) decides to be SpongeBob''s bodyguard. After three parties at SpongeBob''s house, The Strangler tries to strangle SpongeBob, but never gets the chance to be alone.', 11, '2004-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 3), 40, 'Pranks a Lot', 'SpongeBob and Patrick buy a prank called Invisible Spray. After taunting each other with the spray, they run out and decide to haunt Bikini Bottom while being invisible, preferably being ghosts. But with their last victim Mr. Krab, he washes them out with water and exposes them nude (they took their clothes off because the spray stains clothes) to the whole Krusty Krab, embarrassing them.', 11, '2004-10-11');
