INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 2, 'Shell of a Man', 'Mr. Krabs is going to a naval reunion, but molts (leaves his shell) before he goes. He asks SpongeBob to go in his shell and imitate him for the reunion.', 11, '2005-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 3, 'The Lost Mattress', 'Mr. Krabs complains that his back hurts, so SpongeBob and Patrick buy a new mattress and Squidward tries to take credit for it. They give the new mattress to Mr. Krabs, but Mr. Krabs put his money in his old mattress, which SpongeBob, Patrick, and Squidward must find while Mr. Krabs is at the hospital.', 11, '2005-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 4, 'Krabs vs. Plankton', 'Plankton tries to steal the formula, but slips and sues Mr. Krabs. Mr. Krabs hires a lawyer, but his lawyer slips and is hurt, so SpongeBob must try to help Mr. Krabs win the case by trying to open a briefcase that has something very important in it.', 11, '2005-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 5, 'Skill Crane', 'Mr. Krabs gets a new toy vender by the name of "Skill Crane." At first, Squidward doesn''t like it, but when Mr. Krabs lets him and SpongeBob give it a try, Squidward becomes obsessed with it. Can he win anything from the Skill Crane before it ruins his life?', 11, '2005-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 6, 'Good Neighbors', 'It''s Sunday and Squidward just wants to relax. But when SpongeBob and Patrick elect him as Good Neighbor President, they won''t leave him alone.', 11, '2005-05-20');
