INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 8, 'Funny Pants', 'Squidward fools SpongeBob into thinking that he has a laughter-related illness and convinces SpongeBob that if he laughs one more time in the next 24 hours, his laugh box could explode.', 11, '2005-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 9, 'Mermaid Man & Barnacle Boy VI - The Motion Picture', 'The adventures of Mermaid Man and Barnacle Boy are being told in a thrilling new motion picture. But after SpongeBob learns the heroes will be played by young actors, he sets out to make his own version of the movie using the real guys, fresh from their retirement home.', 11, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 10, 'Enemy In-Law', 'Mr. Krabs'' mom is dating again, and it seems like things could be serious. Krabs tries to be happy for his mother, but he is absolutely horrified when he learns that the secret paramour is his arch-rival Plankton! Convinced that this just another trick aimed at getting the family formula for Krabby Patties, Krabs tries to reveal Plankton''s schemes and break up the ill-favored fling.', 11, '2005-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 11, 'Patrick SmartPants', 'After Patrick accidentally falls off a cliff while jellyfishing, he wakes up with superior intellect.', 11, '2005-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 12, 'SquidBob TentaclePants', 'Sandy''s experimental teleportation device malfunctions, melding SpongeBob and Squidward into one body.', 11, '2005-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 13, 'Have You Seen This Snail?', 'While trying to beat a paddle-ball world record, SpongeBob forgets to feed Gary -- for 10 days. Gary runs away to downtown Bikini Bottom where he is taken in by a kindly old woman who confuses him with one of her many deceased pets. Once SpongeBob realizes that he has neglected Gary, he sets out in a town-wide search for him. Meanwhile, as Gary is wrapped in comfy blankets and indulged in an endless assortment of snacks, he discovers a very dark secret about this sweet old woman...', 22, '2005-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 14, 'Dunces and Dragons', 'After a freak jousting accident at a Medieval Times-style restaurant, SpongeBob and Patrick are transported to a medieval version of Bikini Bottom. There they are mistaken for great knights and sent on a quest by King Krabs to rescue his daughter, the Princess Pearl, from the clutches of the evil wizard Planktonamor.', 22, '2006-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 15, 'Krusty Towers', 'After Mr. Krab''s gets a huge hotel bill he decides that he can make a profit from opening his own. When Patrick decides to visit the hotel Mr. Krabs demands Squidward to never deny a guest even the most ridiculous request, but after Patrick frustrates Squidward so badly he quits his job. Then he decides to check into the Krusty Towers.', 11, '2006-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 16, 'Mrs. Puff, You''re Fired', 'Mrs. Puff gets fired from her boating school job due to her lack of passing Spongebob. Instead, a more-intense new instructor takes her place.', 11, '2006-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 17, 'Chimps Ahoy', 'The Chimpanzee beneficiaries of Sandy''s undersea treedome are paying a visit to see what progress she has made with her inventions. But Sandy doesn''t think any of her work will satisfy the chimps, and if they don''t like what she''s invented Sandy could lose her funding forcing her to leave Bikini Bottom. SpongeBob and Patrick decide to help their distraught friend by taking over her work and finishing her inventions.', 11, '2006-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 18, 'Ghost Host', 'The Flying Dutchman takes up residence at SpongeBob''s house where he proceeds to scare, startle and surprise SpongeBob around the clock. Eventually all the spooky shenanigans grow old, and SpongeBob is no longer afraid of the Dutchman. This creates a panic for the old ghost who now fears that he has lost his scary touch. So SpongeBob decides to lend a hand and help the Flying Dutchman learn to scare people again.', 11, '2006-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 19, 'Whale of a Birthday', 'Mr. Krabs wants to give his daughter Pearl the best birthday ever. While he works on the party, SpongeBob is assigned the task of figuring out what Pearl would like for a present. So he trails her through the Bikini Bottom mall and takes note of everything she thinks is "Coral." Once Pearl arrives at her party she is horrified to find that her dad''s miserly ways have won out again. What was supposed to be the most fun and fabulous event ended up cheap and lame. It looks like Pearl''s birthday will go down in history as the worst one ever - until SpongeBob shows up with a truck-load of presents. Everything Pearl looked at in the mall was so Coral that SpongeBob bought it all - maxing out Mr. Krab''s credit card in the process.', 11, '2006-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 20, 'Karate Island', 'SpongeBob receives an invitation to take part in a competition on mysterious Karate Island for the chance to be crowned "King of Karate." SpongeBob and Sandy arrive at Karate Island and it turns out that it was just all a set-up to make SpongeBob buy real estate.', 11, '2006-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 21, 'All That Glitters', 'When a customer orders the one thing that no one has ordered for years, the monster krabby patty, SpongeBob tries to lift it, but old Spat cracks in two. So he sells every single thing he owns (plus his clothes) for a new spatula, but the spatula refuses to flip a single patty, so SpongeBob tries to get his old spatula back. Will Spat forgive him? Will SpongeBob ever be dressed again?', 11, '2006-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 22, 'Wishing You Well', 'Mr. Krabs makes SpongeBob go down the new wishing well after experiencing one for himself, and Patrick and Squidward accidentally join in. So, will they be able to get out and watch everybody''s wishes come true? Or will Mr. Krabs just make them stay down there when he enjoys the money?', 11, '2006-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 23, 'New Leaf', 'In the battle for fast food supremacy, Plankton has decided to throw in the towel and start a new business selling trinkets and souvenir gifts. He even renames his store from The Chum Bucket to The Chumporium. But Mr. Krabs doesn''t buy the change for a second. He''s determined to prove that this is nothing more than one of Plankton''s elaborate schemes aimed at stealing the Krabby Patty formula.', 11, '2006-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 24, 'Once Bitten', 'Gary starts biting everyone in town, starting with Squidward. When Squid asks if Gary has been up-to-date on all of his snail shots, SpongeBob reveals that he''s never done any of that before. This only sends Squidward into a panic. Does he now have some rare snail-related disease? Is this the end for Squidward?', 11, '2006-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 25, 'Squidtastic Voyage', 'While Squidward is playing the clarinet, he accidentally swallows the reed. SpongeBob and Patrick take a microscopic submarine to try to retrieve it from inside Squidward.', 11, '2006-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 26, 'Bummer Vacation', 'Mr. Krabs forces SpongeBob to take a vacation, but he doesn''t know how. Meanwhile, Patrick takes SpongeBob''s place as fry cook.', 11, '2006-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 27, 'Best Day Ever', 'SpongeBob is going to have the best day ever. But when work, karate, jellyfishing and Squidward''s clarinet recital don''t go as planned will his day be ruined?', 11, '2006-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 28, 'Wigstruck', 'SpongeBob finds an old-time wig and starts wearing it everywhere he goes.', 11, '2006-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 29, 'That''s No Lady', 'A misunderstanding over a vacation getaway advertisement causes Patrick to think he must "get out of town" or face dire consequences. SpongeBob can''t bear the thought of his best buddy moving away, so he decides to do what he can to hide Patrick''s identity from his "pursuers." After many failed attempts at disguises, they finally settle on the perfect one: Patrick is transformed into a girl, Patricia, to be exact. Patricia catches the eye of Mr. Krabs and soon she becomes the most charming waitress/waiter at the Krusty Krab.', 11, '2006-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 30, 'The Thing', 'After being covered in cement, the Bikini Bottomites are convinced that Squidward is an unknown species and SpongeBob tries to keep him as a pet.', 11, '2007-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 31, 'Hocus Pocus', 'SpongeBob tries out his new magic kit on Squidward and is convinced he''s turned his neighbor into an ice cream cone!', 11, '2007-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 32, 'Driven to Tears', 'For the 58th time in a row, SpongeBob has failed his driving test, so Patrick takes a test and passes. But SpongeBob is angry that he did.', 11, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 33, 'Rule of Dumb', 'Patrick''s ancestors were adlings, so Patrick is the legal king of Bikini Bottom and now he reigns/misrules Bikini Bottom.', 11, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 34, 'The Pink Purloiner', 'Patrick is jealous of SpongeBob''s jellyfish net. When SpongeBob finds out that it''s been stolen, he suspects Patrick is the culprit.', 11, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 35, 'The Gift of Gum', 'It''s Best Friends Day, so Patrick and SpongeBob trade presents.', 11, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 36, 'Rise and Shine', 'Take a look inside Patrick Star''s rock, where we see that his morning routine is anything but ordinary.', 4, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 37, 'Waiting', 'After SpongeBob discovers that his breakfast cereal has an offer for a free toy, he mails his requests. But now the hardest part is upon him: waiting for the toy to arrive.', 7, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 38, 'Sing a Song of Patrick', 'After Patrick writes a song, SpongeBob helps him try to get it played on the radio.', 11, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 39, 'Born to Be Wild', 'When SpongeBob hears that a ferocious biker gang is coming to town, SpongeBob dons his leather jacket, warms up his bike, and prepares to protect the town all by himself.', 11, '2007-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 4), 40, 'Best Frenemies', 'A new Kelp Smoothie chain is opening up all over Bikini Bottom. The chain''s smoothies are so delicious that soon everyone in town can be seen drinking one. But now that customers already have their smoothie, they don''t need to buy a beverage with their Krusty Krab order. This could hurt Mr. Krabs'' profits.', 11, '2007-03-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 1, 'Friend or Foe', 'After yet another attack on the Krusty Krab by Plankton, SpongeBob asks Mr. Krabs why they hate each other so much. Mr. Krabs tells his side of the story in a series of flashbacks.', 23, '2007-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 2, 'Spy Buddies', 'Mr. Krabs enlists SpongeBob and Patrick to spy on Plankton.', 10, '2007-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 3, 'Boat Smarts', 'Mrs. Puff presents a film on good and bad boat drivers.', 4, '2007-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 4, 'Good Ol'' Whatshisname', 'Mr. Krabs organizes a work contest for SpongeBob and Squidward that involves naming all the customers at the Krusty Krab.', 7, '2007-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 5, 'The Krusty Sponge', 'After a food critic raves about SpongeBob''s cooking, Mr. Krabs makes him the focal point of the Krusty Krab restaurant.', 10, '2007-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 6, 'Squid Wood', 'Rejected yet again by Squidward, SpongeBob decides that if he can''t hang with the real Squidward, he''ll make his own.', 10, '2007-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 7, 'New Digs', 'After being late to work, SpongeBob decides to move into the Krusty Krab.', 10, '2007-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 8, 'Krabs à la Mode', 'Plankton turns down the Krusty Krab''s thermostat as part of another Krabby Patty stealing scheme, but it backfires on him when Mr. Krabs turns the Krusty Krab into a skating rink.', 11, '2007-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 9, 'To Love a Patty', 'SpongeBob falls in love with a Krabby Patty.', 10, '2007-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 5), 10, 'Breath of Fresh Squidward', 'Squidward gets electrocuted by his own electric fence, causing a complete change in his personality.', 10, '2007-07-26');
