INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 7), 39, 'The Wreck of the Mauna Loa', 'SpongeBob and Patrick find a lost ship, which Mr. Krabs uses for financial gain.', 11, '2010-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 7), 40, 'The Great Patty Caper', 'When cooking up a new batch of Krabby Patties, Mr. Krabs accidentally sends the formula away to the other side of the ocean, and sends SpongeBob and Patrick to fetch it.', 22, '2010-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 7), 41, 'The Abrasive Side', 'Gary orders SpongeBob a product that helps him say no to anyone that needs SpongeBob''s help.', 11, '2010-11-27');
