INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 7), 46, 'The Main Drain', 'SpongeBob and Patrick seek out a legendary drain that once destroyed Bikini Bottom.', 11, '2011-01-28');
