INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 7), 52, 'Perfect Chemistry', 'Sandy makes a teleporter, which Plankton tries to use to steal the formula.', 11, '2011-02-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 1, 'A Friendly Game', 'SpongeBob and Patrick decide to build an indoor miniature golf course in SpongeBob''s pineapple house after it has rained outside. Squidward, who was sleeping and annoyed, tells the two to keep the noise down in constructing the course. They must not disturb Squidward, while Patrick distracts SpongeBob to make him lose in the process.', 12, '2011-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 2, 'Oral Report', 'While preparing to give an oral report for boating school, SpongeBob comes down with stage fright. SpongeBob asks Sandy for help, and receives a pair of goggles that would enable him to see people in their undergarments, so he will not feel nervous. However, in his oral presentation, his goggles malfunction, which makes SpongeBob to panic and run out with a boatmobile. Beating the red light, it calls the attention of a police, who starts chasing after him.', 11, '2011-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 3, 'Sentimental Sponge', 'Squidward becomes concerned when Patrick convinces SpongeBob that he needs to become more sentimental.', 12, '2011-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 4, 'Squidward''s School for Grown Ups', 'When Patrick suddenly grows a beard, he decides it is time to act like a grown-up. He tags along with Squiward, who offers to teach him everything he knows about how to be mature, much to SpongeBob''s dismay.', 11, '2011-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 5, 'The Curse of the Hex', 'An evil hagfish curses the Krusty Krab.', 11, '2011-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 6, 'The Hot Shot', 'SpongeBob gets driving lessons from the son of a legendary race-car driver, Tony Fast Jr.', 12, '2011-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 7, 'The Other Patty', 'Mr. Krabs and Plankton, his business rival and Chum Bucket owner, set out to find clues on why they have no customers. The enemies find a common enemy—a popular new restaurant—in which they must work together to steal the secret formula of its "Flabby Patty" burgers.', 12, '2011-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 8, 'Frozen Face-Off', 'SpongeBob and the gang, including Patrick, Mr. Krabs, Squidward, Sandy Cheeks, Plankton and Karen, and Gary, participate in a sled worm race for one million dollars. However, just before the race begins, Plankton sneaks off to the Krusty Krab and uses a robot as his replacement in the race. Plankton goes inside the Krusty Krab to steal the Krabby Patty formula, while the group must keep a yeti, who is attacking them, away.', 22, '2011-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 9, 'Accidents Will Happen', 'When Squidward gets hurt on the job, he menaces to take legal action unless his employer, Mr. Krabs, agrees to cater to him to his every need. Mr. Krabs, who eventually gets tired of doing everything for Squidward, hires SpongeBob and Patrick to investigate the scene.', 12, '2011-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 10, 'Drive Thru', 'Instead of paying money to repair a hole in the wall of the Krusty Krab, Mr. Krabs decides to use it to gain more income by turning it into a drive-thru window. However, his two employees, SpongeBob and Squidward, have difficulty in keeping up with orders, which results to wreak havoc.', 12, '2011-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 11, 'Sweet and Sour Squid', 'Plankton tries to befriend Squidward in order to get the Krabby Patty secret formula. However, Squidward refuses to discourse with him until SpongeBob tells Plankton that he must compliment Squidward''s music in order to strike up a friendship. The two become friends and share their music to all of Bikini Bottom.', 11, '2011-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 12, 'The Googly Artiste', 'When doing arts and crafts with his best friend SpongeBob, Patrick is coveted by everyone in town after an art critic praises his artwork. He soon becomes a famous artist, which makes Squidward jealous. When he reaches an artist''s block, Patrick must find new inspirations for his next masterpiece.', 11, '2011-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 13, 'Barnacle Face', 'The night before a school dance, Pearl gets a barnacle on her face. Mr. Krabs asks SpongeBob to help his daughter remove the blemish to save money, instead of taking Pearl to expensive treatment.', 11, '2011-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 14, 'Pet Sitter Pat', 'When SpongeBob gets an invitation to his Grandma''s birthday party, he asks his best friend Patrick to pet-sit Gary. However, Patrick only causes trouble, which makes SpongeBob angry.', 11, '2011-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 15, 'Mermaid Man Begins', 'SpongeBob and Patrick learn the secret origins of Mermaid Man and Barnacle Boy from the heroes themselves.', 11, '2011-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 16, 'Plankton''s Good Eye', 'Plankton grows himself another eye because he lacks depth perception. However, it changes his personality and causes him to be nice, because the eye is from SpongeBob''s DNA.', 11, '2011-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 17, 'House Sittin'' for Sandy', 'SpongeBob gladly accepts to house sit Sandy''s Treedome, while she is away. Sandy first shows SpongeBob what he should do, and all is quiet until Patrick arrives for a visit. The best friend causes chaos and wreak havoc, which results to the house getting destroyed.', 11, '2011-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 18, 'Smoothe Jazz at Bikini Bottom', 'Squidward and SpongeBob win backstage passes and tickets to Kelpy G''s live concert. However, Patrick eats their passes shortly after the concert begins. Losing their passes, SpongeBob and Squidward try to sneak backstage to meet Kelpy G.', 11, '2011-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 19, 'Ghoul Fools', 'SpongeBob and Patrick find a houseboat haunted by a crew of ghost pirates headed by Lord Poltergeist. The two get caught in a feud between them and the Flying Dutchman.', 22, '2011-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 20, 'Walking the Plankton', 'Mr. Krabs and SpongeBob win free tickets to a cruise, thanks to Plankton, but they do not know that it is a secret plan to steal the Krabby Patty formula. At the same time, Plankton tricks his computer wife Karen for a vacation, and she is initially excited until when she realizes that this is part of his plan to steal the formula. He lies to her and the both hop on the same cruise as Mr. Krabs and SpongeBob.', 11, '2011-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 21, 'Patrick''s Staycation', 'When feeling that he is doing the same activities every day, Patrick moans that he needs a break. SpongeBob suggests a vacation out of town, which cheers him. When at a travel agency, Patrick is given options, but they are thrown out when it is revealed that he cannot afford a trip. SpongeBob comes up with a solution—a "staycation", a vacation at home—which delights Patrick.', 11, '2011-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 22, 'Mr. Krabs Takes a Vacation', 'Mr. Krabs takes a vacation with SpongeBob and Pearl to the Bikini Bottom Mint. However, his daughter does not want to tag along, so she stays at a museum. SpongeBob and Mr. Krabs proceed inside the mint, but the tour guide is instantly annoyed by their antics. When two bank robbers seize the mint, SpongeBob and Mr. Krabs stop them and they are rewarded with a special edition one-dollar bill with their faces on it, but Pearl confiscates the dollars and spends them on a new pair of shoes, causing Mr. Krabs to blast endless tear beams in the mint.', 11, '2011-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 23, 'Mooncation', 'SpongeBob meets Sandy, who is preparing her rocket to go to the Moon for a vacation. However, SpongeBob accidentally stows away, and when on the Moon, the two set out camp. SpongeBob and Sandy play sports including sandboarding on its craters. After accidentally crashing the sandboard into the fuel tank, they immediately start the rocket because they need to return home before the fuel runs out.', 11, '2011-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 24, 'A SquarePants Family Vacation', 'SpongeBob invites Mr. Krabs, Pearl, Sandy, Mrs. Puff, Larry, Squidward, and Plankton to watch a slideshow of his family vacation to the Great Barrier Reef. In the slideshow, SpongeBob and his parents are on a family road trip with Patrick, but the two best friends get lost and end up in a forest for adventure.', 22, '2011-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 25, 'The Krabby Patty That Ate Bikini Bottom', 'While looking for spare change, Mr. Krabs notices an over-sized soybean at Sandy''s Treedome. Mr. Krabs is interested in what could have enlarged the plant, and Sandy revealed an experimental growth formula, which Mr. Krabs steals out of sight. At the Krusty Krab, he uses the growth formula on a Krabby Patty, but it keeps on growing until chaos erupts.', 11, '2011-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 26, 'Bubble Buddy Returns', 'SpongeBob receives a letter from an old friend Bubble Buddy, asking to babysit his son Shiny, who causes mischievous antics. SpongeBob must keep Shiny out of trouble and away from sharp and pointy edges.', 11, '2011-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 27, 'The Way of the Sponge', 'Sandy introduces Fuzzy Acorns, "the greatest karate master ever", to SpongeBob. The master is training Sandy to earn the "blacker belt", the highest belt in karate. SpongeBob wishes he had a belt, which Fuzzy overhears and tells SpongeBob that if he wants one, he has to earn it. Fuzzy offers to train SpongeBob so that he can earn the belt, which he reluctantly accepts.', 11, '2011-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 28, 'Bubble Troubles', 'After making bubbles with hot sauce, SpongeBob and Patrick accidentally destroy Sandy''s air supply by causing a fire and fill her Treedome with water by contaminating it. They must help her find enough oxygen in order to help them breath. In the end, SpongeBob goes to the surface to create a giant air-filled bubble, and puts it into the Treedome.', 11, '2011-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 29, 'Are You Happy Now?', 'Squidward tries to find his happiest memory, but gives up after hope is lost. Desperately, SpongeBob "helps" him create one.', 11, '2012-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 30, 'Planet of the Jellyfish', 'SpongeBob and Sandy battle an evil Jellyfish overlord, who is replacing everyone in town with clones. After searching for clues, they figure out that its weakness is mayonnaise.', 11, '2012-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 31, 'Restraining SpongeBob', 'A fed-up Squidward has had it with SpongeBob''s annoying antics, pranks, wisecracks, and practical jokes and issues SpongeBob a restraining order against his neighbor. SpongeBob is afraid that he will violate the restraining order again. (According to this restraining order, SpongeBob is not allowed to come within 15 feet of Squidward, lest he end up going to jail for the rest of his life.)', 11, '2012-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 32, 'Glove World R.I.P.', 'SpongeBob and Patrick spend a final day at Glove World before it shuts down forever, only for a new amusement park called Glove Universe to open.', 11, '2012-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 33, 'Home Sweet Rubble', 'SpongeBob''s pineapple house is falling apart and is in needing repairs, so he gets all of his friends to help him refurbish it. However, despite the big changes, SpongeBob is not happy with it. In the end, his pet snail Gary helps him with his can, which contains a fully furnished pineapple.', 11, '2012-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 34, 'Fiasco!', 'Squidward discovers a piece of art by an artist named "Fiasco", and Mr. Krabs decides to use it as an attraction to his customers at the Krusty Krab. But soon after, Plankton steals it, believing he can reverse engineer the Krabby Patty formula from it.', 11, '2012-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 35, 'Free Samples', 'Plotting to ruin Mr. Krabs, Plankton, his business rival, drives away his customers. As a result, Mr. Krabs is forced to give out free Krabby Patties in order to try to win them back.', 11, '2012-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 36, 'InSPONGEiac', 'SpongeBob has difficulty falling asleep, while Patrick struggles to stay awake.', 11, '2012-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 37, 'Treats!', 'SpongeBob brings home a box of new snail treats that Gary will do anything to get – especially when they run out.', 11, '2012-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 38, 'Squiditis', 'When Squidward goes home sick with a fake illness, SpongeBob thinks he has caught it for real.', 11, '2012-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 39, 'For Here or to Go', 'Mr. Krabs organizes a guessing game to his customers at the Krusty Krab for a Krabby Patty. When Plankton tries it, he actually wins. Mr. Krabs will do anything to stop him from collecting his prize.', 11, '2012-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 40, 'Karen 2.0', 'When Plankton replaces his computer wife Karen with an upgrade called Karen 2.0, the original Karen leaves and gets a job at the Krusty Krab.', 11, '2012-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0206512')) AND numero_temporada = 8), 41, 'Extreme Spots', 'When the drasticals come to town, SpongeBob and Patrick try to do whatever it takes to join them, no matter how extreme – or dangerous. Whether attempting sand motorbiking, hang gliding, seashell surfing or extreme bubble blowing, SpongeBob and Patrick undertake the challenge in an effort to demonstrate they are extreme.', 11, '2012-07-21');
