INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 1, 'Payback', 'Detectives Stabler and Benson investigate the murder and dismemberment of a taxi driver; the team discovers that he may have been a vicious Serbian war criminal living in the United States under a false identity.', 44, '1999-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 2, 'A Single Life', 'Benson and Stabler run into multiple dead ends while investigating the case of a woman who plummeted six stories to her death clad only in a slip.', 43, '1999-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 3, '...Or Just Look Like One', 'When a teen model is murdered and another is left for dead at a hospital emergency room, the team uncovers an insidious drug and sex conspiracy in the world of high fashion. Benson and Stabler enter into a modeling underworld of thoughtless parents, drug-dealing doctors and a trendy agency executive.', 43, '1999-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 4, 'Hysteria', 'When a young African-American woman is found dead, she is initially believed to be a prostitute and the latest in a long line of victims, but when looking into her home life Benson and Stabler realize that she does not fit the pattern, and may not be connected to the other deaths after all, but the other deaths have a connection no one anticipated.', 43, '1999-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 5, 'Wanderlust', 'When a world-traveling author is found dead in a room he rented from an alcoholic woman and her precocious 14-year-old daughter, the detectives are shocked to discover who the murderer is.', 44, '1999-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 6, 'Sophomore Jinx', 'A female student at an upper-class university is raped and murdered, and two of the college’s basketball stars are suspected. However, the college blocks their investigation at every turn because they are not willing to risk the negative publicity that the investigation could bring to the school and the upcoming championship.', 43, '1999-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 7, 'Uncivilized', 'When a young boy is found raped and murdered in a field, suspicion leads detectives to a recently paroled child molester who lives in the neighborhood.. Although they both hate what the man has done in the past, it is soon obvious to the detectives that the teenagers who initially steered them in the man''s direction are hiding secrets of their own.', 44, '1999-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 8, 'Stalked', 'When an assistant district attorney is found raped and murdered in Central Park, the Special Victims Unit learn that she’d been stalked by a real estate agent whom she’d convicted of date rape. Benson lets her emotions get the best of her as she takes it upon herself to bring the suspected rapist to justice. Stabler tries to get the man''s business partner to help him, but Benson may be the one who ends up needing help.', 44, '1999-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 9, 'Stocks & Bondage', 'An investment analyst is found hanged in her bedroom, and the Special Victims Unit explores her sordid sexual past to uncover her murderer’s identity. The team uncovers the world of bondage and sado-masochism where they first investigate the woman''s colleagues but are soon on the trail of a host of individuals involved in the world of whips and chains.', 44, '1999-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 10, 'Closure', 'When a woman is raped, she turns to the Special Victims Unit for help, but lack of evidence prevents them from apprehending the criminal. When the detectives revisit the case a few months later, they find the woman even less willing to talk about what happened, as she claims she has moved on. Things turn sticky when Benson and Cassidy spend the night together.', 44, '2000-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 11, 'Bad Blood', 'A moral coalition leader’s gay son is found murdered on the roof of his apartment building. Initially, Benson and Stabler investigate his father, a Conservative well-known for his homophobic viewpoints, but once they start looking into the young man''s living arrangements they realize the person they''re looking for may be closer than they think. Munch tries to help Benson find the man who raped her mother, and could potentially be her father.', 44, '2000-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 12, 'Russian Love Poem', 'When a multi-millionaire is found strangled in his home, Benson and Stabler turn their suspicion to his long list of lovers, which includes both men and women. Detectives discover he was involved with a group of beautiful Russian women that came to the U.S. to take advantage of wealthy Americans.', 44, '2000-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 13, 'Disrobed', 'A judge who fought for the rights of abused women is found shot in his car under sordid circumstances, and the detectives uncover a case of corruption that leads to the state parole board. The team soon turns their eye to a battered wife with a secret.', 44, '2000-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 14, 'Limitations', 'At the request of a victim, the police commissioner comes to Cragen with a special request -- close the five-year-old case of a serial rapist before the statute of limitations expires. The detectives finally get a lead but the investigation is hindered by one of the victims.', 44, '2000-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 15, 'Entitled (I)', 'After a salesman is murdered, the detectives turn their attention to the youngest daughter of a well-known family with some deep connections. But as they join forces with the officers from the two-seven, they realize that their case is connected with a long-unsolved case that Briscoe once handled years ago with his former partner Mike Logan.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 16, 'The Third Guy', 'An elderly woman is found tied up and sexually assaulted in her apartment, and suspicion is initially on the young men that had broken into her home and robbed her, but once the detectives are surprised to learn that the rape was committed after the robbery – by someone else.', 44, '2000-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 17, 'Misleader', 'The pregnant daughter-in-law of a Christian College president is murdered in her hotel room, and the detectives discover that the man had been involved in some very unholy activities.', 44, '2000-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 18, 'Chat Room', 'When a teenage girl comes into the squad room to tell the detectives that she was raped by a man she met on the Internet, the investigation leads the Special Victims Unit to a network of pedophiles and child pornographers.', 43, '2000-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 19, 'Contact', 'After seven young women in a six month time span are raped by a flash and dash assailant on the city subways, the brass calls in a psychiatrist to help the team get into the head of the perp. When he is caught, he possesses the driver''s license of a new victim who could put him away.', 42, '2000-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 20, 'Remorse', 'A female television news reporter decides to go public with her story when she attacked and raped by two men, but the decision proves to be fatal.', 44, '2000-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 21, 'Nocturne', 'After a pharmacy turns over some disturbing photos of a young boy, a beloved neighborhood piano teacher is suspected of being a sexual predator who takes advantage of his innocent young students.', 43, '2000-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 1), 22, 'Slaves', 'A Romanian immigrant is being held as a psychological prisoner by her abusive employer and his wife, who is also traumatized by years of abuse and is willing to commit murder to protect her husband. A forensic psychologist analyzes the team, and presents disturbing findings to Cragen, suggesting that one of the detectives be removed from the team.', 44, '2000-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 1, 'Wrong Is Right', 'Stabler''s daughter bears witness to a horrific crime scene: a rocket scientist found dead with his crotch on fire. The scientist had strong ties to government security and detectives must determine if that had something to do with his demise. The internal investigation into the psyches of the SVU detectives yields interesting results.', 44, '2000-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 2, 'Honor', 'The vicious sexual assault and brutal beating of an Afghan diplomat''s daughter uncovers clues that may suggest Taliban traditions justify ''honor killings'' when the child defies the wishes of their parents or their culture; the trail leads close to home.', 44, '2000-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 3, 'Closure (2)', 'Stabler and Benson investigate a sexual assault very similar to one they worked six months ago whose victim follows her alleged attacked and reports his activities to the police.', 43, '2000-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 4, 'Legacy', 'An abused 7-year-old girl lays comatose as the detectives investigate members of her dysfunctional family to determine the source of the abuse, in a case that hits close to home for Munch.', 44, '2000-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 5, 'Baby Killer', 'The tragic shooting death of a young girl leads investigators to a little boy, and they soon realize that the gun used has been used in another crime scene and a drug ring using young kids as pawns.', 43, '2000-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 6, 'Noncompliance', 'The question of patients'' rights surfaces when a schizophrenic man refusing to take his medication is suspected in the rape and stabbing death of an aspiring psychologist, whose body is found in a convenience store.', 44, '2000-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 7, 'Asunder', 'It’s a classic case of “he said, she said” when a cop’s wife charges him with rape. The truth behind the alleged rape comes to light when a history of domestic abuse is uncovered.', 44, '2000-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 8, 'Taken', 'The case of a seventeen-year-old rape victim during a gala for the opening of a luxury hotel takes a strange turn when her immediate family tries to keep the scandal quiet. Detectives soon discover that the girl isn''t the innocent that she pretends to be. Benson struggles to deal with her mother''s death and she learns about her past.', 44, '2000-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 9, 'Pixies', 'The investigation of a young gymnast''s murder involves her strict trainer, a wealthy benefactor and a competitor. Detectives must look into her pressured lifestyle to find out who did it.', 44, '2001-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 10, 'Consent', 'A college co-ed is found raped and dazed after a frat party, but can''t remember anything that happened. The detectives then find that she had a date rape drug in her system, leaving them with many suspects and accomplices, tho the victim is reluctant to press charges.', 44, '2001-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 11, 'Abuse', 'Parental neglect may have led to the tragic death of the son of two famous singers, leading them to fear for his sister. Benson develops a strong attachment to the girl who has a history of serious injuries.', 44, '2001-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 12, 'Secrets', 'An exceptional teacher, who helped inner city kids get into college, led a dangerous double life as a sex addict. When she is murdered, there is a long list of suspects but the case hits a snag after the woman''s illicit sexual history is exposed.', 44, '2001-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 13, 'Victims', 'A former police officer, now a community activist, is a suspect in the murders of known sex offenders, all of whom share a certain characteristic that scars their victims for life. The detectives find it''s difficult to protect potential victims when they used to be perps as they investigate the murders of two convicted rapists.', 44, '2001-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 14, 'Paranoia', 'The mysterious rape of a veteran police officer, who trained Benson, is first linked to her ex-husband''s gambling debts, and then to her fellow officers. It turns into a nightmare investigation as the IAB tries to thwart the SVU squad''s efforts.', 44, '2001-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 15, 'Countdown', 'The detectives become a little edgy after working around the clock to find an abducted girl when clues point to a serial murderer and rapist who kills his victims on the third day. After trapping the killer, they are prepared to give him the death penalty until they find out that one of his victims was never found and he offers her location as a plea bargain.', 44, '2001-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 16, 'Runaway', 'The search for an out-of-state police officer''s runaway daughter leads the detectives through an underground rave culture that caters to wayward teens. They use an Internet journalist to track her and their search is seen through the eyes of the squad room personnel as told in their interviews with the Internal Affairs division.', 43, '2001-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 17, 'Folly', 'Male escorts are assaulted and one is murdered, and the police have a tough time finding the bizarre couple whose sexual fantasy has turned violent. The investigation uncovers a dangerous male escort service where the boss may have reasons for sending her staff on potentially deadly dates.', 44, '2001-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 18, 'Manhunt', 'The details of a kidnapping are similar to a series of rapes and murders that may link the crime to a serial killer.', 44, '2001-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 19, 'Parasites', 'The remains of a Romanian woman are found three years after her death, buried in an apartment courtyard with a collar and leash. The detectives have a tough time finding the killer until a composite photo leads them to the victim''s identical twin sister.', 44, '2001-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 20, 'Pique', 'Observed by an FBI psychiatrist, the detectives uncover a horrifying motive for the slaying of a software company employee by a fired colleague when they learn of the suspect''s bizarre relationship with his overbearing mother and a strange sexual fetish called piquerism.', 44, '2001-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 2), 21, 'Scourge', 'A "Jack the Ripper" type murderer, who justifies his crimes with paranoid religious motivation set on by a rapidly deteriorating medical condition, is on the loose. After a citywide manhunt, Detectives Benson and Stabler are tasked with finding the killer.', 44, '2001-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 1, 'Repression', 'An 18-year-old girl is aided by her therapist in recalling repressed memories of childhood molestation by her father and reports the incest to Benson and Stabler in hopes of sparing her younger sisters the same fate. She brings charges of rape against her father who winds up murdered when those charges are dismissed.', 43, '2001-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 2, 'Wrath', 'The detectives investigate three murders that seemingly have no connection to each other, but each murder has ties to Benson''s previous cases. As they join with the FBI to investigate, the detectives worry that Benson is the intended target.', 43, '2001-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 3, 'Stolen', 'The kidnapping of an infant at a grocery store leads to an illegal adoption ring and the long lost closure of a case from 12 years prior of a murdered mother and missing baby which involved Capt. Cragen and his partner, the late Max Greevey.', 43, '2001-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 4, 'Rooftop', 'When an HIV-positive male, with a record of assaulting underage girls, is discovered in a sexual clincher with a young woman on a rooftop, the detectives are determined to put him back inside. After a series of rapes and murders of young African-American women cannot be traced to him though, they begin to wonder if they''ve been looking at the wrong suspect.', 44, '2001-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 5, 'Tangled', 'When arriving party guests find a prominent doctor beaten to death and his wife raped, the detectives have a parade of suspects and the realization that the wife was the intended victim.', 44, '2001-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 6, 'Redemption', 'A string of murders leads detectives to question an initial suspect, the Soho Strangler, but they realize he might have been the wrong person all along.', 44, '2001-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 7, 'Sacrifice', 'A man, who is shot and raped outside a gay bar, initially doesn''t want to cooperate to find his shooter. When he finally does, the investigation leads to his family and turns his life upside down.', 42, '2001-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 8, 'Inheritance', 'A series of brutal rapes and attacks on Asian women lead the police to a suspect who was himself a product of rape - his father being a rapist who was convicted. The question is brought to court of whether his genetic make-up was responsible for the crimes.', 43, '2001-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 9, 'Care', 'The battered body of a five-year-old girl in foster care is discovered and suspicion soon turns to members of the girl''s foster family as well as to the girl''s biological mother; who is the real guilty party and who is only a red herring?', 43, '2001-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 10, 'Ridicule', 'What appears as a bizarre accidental death leads to a case involving a male stripper who claims that the deceased was one of three powerful women who raped him at a bachelorette party.', 43, '2001-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 11, 'Monogamy', 'The pregnant wife of a psychiatrist is found in a parking garage, unconscious and bleeding from a gaping abdominal wound with her fetus missing. The investigation leads to infedility and uncertainty as to the paternity, adding fuel to the fire of an already agitated Stabler.', 44, '2002-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 12, 'Protection', 'A 6-year-old boy wounded in a shooting is brought to the ER but abandoned by his brother, who reported it, and their mother, who fears for her own life. The case leads the detectives to a woman who is on the run from an abusive drug-dealer boyfriend.', 44, '2002-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 13, 'Prodigy', 'Two people are found murdered in the park, including an animal rights activist who has been raped and then decapitated. Benson and Stabler must determine which of their two main suspects -- a sociopathic teenager and a recently paroled rapist -- is responsible for the murder.', 43, '2002-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 14, 'Counterfeit', 'A woman is found raped and killed by her car. Then, a similar rape is committed and the victim says that a police officer raped her after pulling her over for a supposed driving violation. This leads police to look at one of their own, until they realize the suspect is not who they think he is.', 44, '2002-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 15, 'Execution', 'Detective Stabler and Dr. Huang question a convicted serial killer on death row, hours before his execution, with the hope of solving an old murder case for the sake of the victim''s parents. The investigation goes haywire with mixed results.', 42, '2002-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 16, 'Popular', 'Stabler''s wife tells him that her friend, a high school nurse, treated a young girl for rape. Despite being advised not to find out further details, Stabler, with help from Benson, crack open the case to disturbing details.', 43, '2002-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 17, 'Surveillance', 'An accomplished cellist is raped in her own apartment and the detectives are lead to a stalker who uses surveillance equipment and has been watching her every move.', 43, '2002-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 18, 'Guilt', 'When A.D.A. Cabot is faced with a reluctant teenage witness in a child molestation case, she goes above and beyond the normal scope of duty in her search for evidence to convict the serial abuser. But her passion supercedes her compliance with the law, jeopardizing not only her case, but the careers of all involved.', 44, '2002-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 19, 'Justice', 'A rebellious 16-year-old teenager is raped and murdered; the case becomes complex when they learn that her stepfather is a judge with whom she has had major problems.', 43, '2002-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 20, 'Greed', 'Investigating the rape of the wife of a restaurateur during a robbery, leads the detectives to a similar assault, and to a locksmith.', 44, '2002-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 21, 'Denial', 'When a heroin junkie is found raped, Tutuola takes an interest in her, but he''s not the only one. The case turns into a bizarre murder investigation when the finger of a small child is found in the victim''s purse opening a can of worms that spans back thirteen years.', 44, '2002-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 22, 'Competence', 'A mentally challenged girl with Down''s Syndrome is pregnant, and the question is, was she raped or did she consent and is she competent enough to keep her child?', 42, '2002-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 3), 23, 'Silence', 'A murder in a church of a young cross-dresser leads Benson and Stabler to an alleged cover-up involving sexual child abuse by a priest.', 44, '2002-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 1, 'Chameleon', 'The detectives are on the trail of a recently paroled rapist responsible for the murder of a prostitute during a raid at a men''s club and are called to the scene where he was shot in self defense by his own gun.  However, the murder weapon was also used in another crime while he was still in prison, leading the detectives to investigate the victim through a trail of previously unsolved cases, a spending spree and another victim. They uncover a more serious criminal in the process.', 43, '2002-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 2, 'Deception', 'A family portrait painted by a kindergartner leads the detectives to investigate her mother for child sexual abuse of her teenage stepson.  When the boy''s father is found murdered, the focus of the investigation shifts to the boy -- and his stepmother goes to great lengths to protect him and prevent the detectives from learning the truth.', 44, '2002-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 3, 'Vulnerable', 'When an elderly woman with Alzheimer''s breaks into an apartment, the detectives discover she had been abused, triggering memories of similar crimes from her childhood. They discover that she had been released from a nursing home to the custody of her financially scheming son who becomes the prime suspect. However, they go back to the nursing home to find a pair of suspects; the real crime is what''s being done to the elderly.', 43, '2002-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 4, 'Lust', 'A public health doctor, the wife of a retired attorney, who tracked HIV cases is found murdered and raped in Central Park. Her work involved contacting sexual partners of HIV patients which gives the detectives a long list of suspects and the detectives try to link threatening phone calls to the crime. The discovery of a second body in Central Park with the same signature shifts the focus to a possible serial killer.', 44, '2002-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 5, 'Disappearing Acts', 'A high-powered executive is raped, but the situation is complicated by her involvement with the Feds and the Russian mob - as well as a father-son duo who are in the federal witness protection program and an agent who appears bound and determined to protect them, regardless of consequence.', 43, '2002-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 6, 'Angels', 'A battered young boy suffocates while hiding in the luggage compartment of an airport shuttle bus and it leads the detectives to his guardian and into the investigation of a perverted child molestation ring.', 44, '2002-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 7, 'Dolls', 'Detectives try and solve the gruesome murder of a sexually molested five-year-old girl whose killer, a serial pedophile, has an obsession with dolls. They race to save the life of his latest victim.', 43, '2002-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 8, 'Waste', 'The Detectives investigate the rape of a woman who''s been in a coma for a year, and after eliminating a huge pool of suspects, they make a startling discovery.', 44, '2002-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 9, 'Juvenile', 'A cancer patient, who was growing marijuana in her apartment and selling it, is found raped and murdered, sending the detectives on a hunt for two middle school students, each blaming the other.', 42, '2002-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 10, 'Resilience', 'A 14-year-old girl tries to commit suicide by jumping in front of a train after she is raped. She falsely accuses an ex-boyfriend but when the search turns to her dysfunctional family, surprise discoveries are made and SVU discovers that the family is even worse off than they thought.', 43, '2002-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 11, 'Damaged', 'A six-year-old girl is critically injured in an apparent robbery-gone-bad and later dies. The investigation gets complicated when it is discovered that the murders were designed to silence the young girl, who was sexually abused.', 43, '2003-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 12, 'Risk', 'An infant ingests pure cocaine disguised in baby formula, uncovering a complicated narcotics ring with unlikely participants and the entire squad goes undercover to flush them out.', 41, '2003-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 13, 'Rotten', 'In their investigation of a prisoner''s death, Benson and Tutuola learn that he was sexually assaulted before being incarcerated and since it happened while in custody, the police are suspected.', 42, '2003-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 14, 'Mercy', 'When the body of a 1-month-old baby girl is found stuffed inside a cooler, the detectives are horrified. But they soon learn that the baby had a genetic disorder known as Tay-Sachs disease, and it may have been a mercy killing.', 43, '2003-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 15, 'Pandora', 'The brutal rape, and subsequent death, of a female motorist turns out to be an undercover FBI informant acting as a cyber vigilante for catching online pedophiles to capture the predator trafficking internet porn. The detectives find the victim''s husband murdered and follow the trail of evidence for the latest victim she had been tracking, which ​turns into an international case of teenage prostitution, with ties to the Czech Republic.', 43, '2003-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 16, 'Tortured', 'A Tibetan woman who was tortured in her home country is found murdered, with her foot missing, and after an exhaustive search of potential suspects, the killer is a victim of torture himself.', 43, '2003-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 17, 'Privilege', 'A young female film student dressed in a maid''s uniform has apparently committed suicide but it''s very suspicious. The detectives learn that she just broke up with her very rich and powerful boyfriend.', 43, '2003-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 18, 'Desperate', 'After a young boy witnesses the brutal sexual assault and murder of his stepmother, he is too terrified to tell the detectives who attacked her.', 43, '2003-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 19, 'Appearances', 'The body of a nine-year-old beauty pageant contestant is found raped and murdered on a bus, but the case goes beyond the killer when it leads detectives to a virtual-pornography website.', 43, '2003-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 20, 'Dominance', 'A quadruple homicide with sexual overtones is just the start of an intense rampage of a serial killer that brings a homicide detective into the mix.  As the entire squad races against time to prevent further victims, the evidence uncovers a horrible situation of incest and abuse.', 43, '2003-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 21, 'Fallacy', 'A female party-goer and rape victim claims self-defense after killing her attacker. Events take an unusual turn when they find out that the victim is a pre-operative transgender.', 43, '2003-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 22, 'Futility', 'A man accused of raping several neighborhood women denies everything and represents himself in court.', 42, '2003-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 23, 'Grief', 'A dead girl is found outside a bar. The death, however, is ruled a suicide, because the victim''s boyfriend continually raped her. The victim''s father vows revenge against his daughter''s rapist.', 43, '2003-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 24, 'Perfect', 'A murdered 14-year-old girl leads the detectives to a prominent physician who specializes in reproduction therapy and exposes a dangerous "foundation" where disenfranchised young women are brainwashed.', 43, '2003-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 4), 25, 'Soulless', 'After a rape victim is abducted from the hospital and later found dead, the detectives suspect several young socialites of her rape, at a Manhattan nightclub, and subsequent murder.', 43, '2003-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 1, 'Tragedy', 'A woman with a high-risk pregnancy disappears and her ex-boyfriend, who''s the father, and engaged to the boss'' daughter, is under suspicion. In a race against time to find her as her delivery date approaches, Benson and Stabler are faced with more than one suspect willing to take the fall for the crime.', 42, '2003-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 2, 'Manic', 'Detectives enlist Dr. Huang''s help as they investigate the deaths of two high-school basketball players gunned down while shooting hoops in the gymnasium and the connection to an illegal marketing campaign by a major pharmaceutical company.', 44, '2003-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 3, 'Mother', 'A psychiatrist with unconventional methods is found sexually assaulted, unconscious and near death in a crack house. It''s easier said than done to get her to cooperate with the investigation as they are hampered by doctor-patient confidentiality as she may have been attacked by one of her patients.', 44, '2003-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 4, 'Loss', 'A female undercover agent for the DEA is raped and murdered, leading to a complicated investigation and the arrest of a suspect highly connected with a Colombian drug cartel. This is the toughest case of Cabot''s career as she is faced with death threats on herself and her family along with pressure to yield the case to federal authorities.', 44, '2003-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 5, 'Serendipity', 'A newborn baby is found dead in a gutter, sending the detectives on a hunt for the mother. She too turns up murdered, and the clues point to a serial child molester.', 42, '2003-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 6, 'Coerced', 'A schizophrenic homeless man kidnaps a boy he thinks is his son, murdering a man in the process. In resolving the case, with Dr. Huang''s help, a private mental health facility is brought into question.', 44, '2003-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 7, 'Choice', 'While patrolling, police stumble upon an attack in progress at Momma Sue’s restaurant on the pregnant owner. Her husband is arrested and then seeks to have her charged with neglect for drinking during her pregnancy. The detectives discover it''s not the first time a child has been exposed to the devastating repercussions of her uncontrolled alcoholism.', 43, '2003-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 8, 'Abomination', 'Benson and Stabler have trouble identifying a male murder victim in his 20''s found in a pile of sheets in the West Village; they later suspect an outspoken minister who was in the process of flooding the victim with hate mail and death threats. When the activist''s alibi checks out, the detectives turn their attention to a professor who objects to the victim''s thesis on the failure of sexual re-education groups.', 43, '2003-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 9, 'Control', 'A subway commuter is found castrated and bleeding profusely, leading the detectives to discover their "victim" may be the perpetrator in abducting women and forcing them to live in his dungeon for several years as his bride. As the detectives prepare to arrest their victim turned suspect, Benson arrives to find him murdered.', 44, '2003-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 10, 'Shaken', 'The discovery of a beaten infant leads detectives on a search for the attacker, who may be a pedophile. When the medical evidence shows the injuries were a result of shaken baby syndrome, their focus shifts to those closest to the child: her mother, the mother''s boyfriend and the nannies.', 44, '2003-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 11, 'Escape', 'When a convicted pedophile, desperate to prove his innocence before his terminally ill mother dies, escapes from a Virginia Correctional Facility and kidnaps his accuser to force him to recant his story, a Deputy Marshall teams up with Benson to track them down. Benson eventually finds herself in the middle of a hostage situation beginning to believe his story.', 43, '2003-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 12, 'Brotherhood', 'When the body of young man is found in a tank at a wastewater treatment plant, the medical examiner identifies a tattoo that says TE, the symbol for the fraternity Tau Omega. The investigation into the murder and sodomy of this local fraternity pledge master leads the detectives to his pornographic website featuring college girls at a local bar.', 44, '2004-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 13, 'Hate', 'A young Arab woman is brutally raped and burned, and after identifying her, the detectives suspect her husband and mother-in-law. After a man accused of the murders of three Arabs, he claims that he was genetically and biologically predisposed to hatred and violence, but soon they uncover the real impetus to the slayings.', 43, '2004-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 14, 'Ritual', 'Two garbage collectors discover what they first think is a scene of animal sacrifice but is the body of a young boy who appears to be the victim of a ritualistic killing. The investigation leads to the discovery of international child slavery.', 42, '2004-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 15, 'Families', 'The investigation into the death of a pregnant high school student exposes a long-held family secret, which precipitates yet another violent death and eventually the destruction of two families.', 43, '2004-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 16, 'Home', 'A young, emaciated boy is found by neighbors scrounging for food; detectives suspect the boy is a victim of abuse and are reluctant to let him go home.', 43, '2004-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 17, 'Mean', 'The conviction of a group of sociopathic high school bullies who turned on one of their own escalates into even more violence and death in their exclusive private school.', 43, '2004-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 18, 'Careless', 'When a young foster child dies due to a religious ritual gone awry, the detectives unravel a mysterious pattern of violence, abuse and murder within one foster care family.', 41, '2004-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 19, 'Sick', 'A wealthy toy mogul is the suspect of the sexual abuse of a child. His prosecution impeded by the child''s parents who refuse to produce their child for questioning to avoid losing the millions paid through a non-disclosure agreement, and by the discovery that a second accusation was falsified in an attempt to extort a settlement.', 43, '2004-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 20, 'Lowdown', 'Detectives try to decipher a motive for the strangulation of a Bronx assistant DA in an area where hookers stroll. When the death of the prosecutor looks staged using information gleaned from a co-worker''s caseload, Novak endangers her career to obtain a confession.', 42, '2004-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 21, 'Criminal', 'When it becomes obvious that a forensics expert raped and murdered a student, the investigation focuses on a criminology professor Cragen arrested decades earlier for similar crimes, but is the professor a perpetrator or a victim?', 43, '2004-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 22, 'Painless', 'A woman claiming to have been the victim of rape commits suicide while she is still in the emergency room.', 43, '2004-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 23, 'Bound', 'The death of a wealthy senior citizen leads to an investigation that uncovers a serial killer with childhood abandonment issues who targets the elderly.', 42, '2004-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 24, 'Poison', 'A young girl is in a coma after ingesting detergent and her mother is suspected of poisoning her. A biased judge makes the case hard to prosecute which leads to an investigation into his past.', 43, '2004-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 5), 25, 'Head', 'A boy is accused of being molested after his soccer game, but he doesn''t admit to it. His principal and his soccer coach are the prime suspects.', 44, '2004-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 6, 'Season 6', 'Detectives Benson, Stabler, Fin and Munch face serial killers, self-proclaimed psychics and cult leaders as they investigate crime in New York City.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 1, 'Birthright', 'The investigation into the attempted kidnapping of a six year old girl uncovers a fertility doctor''s scheme to steal embryos, and prompts a custody battle between the child''s biological and birth mothers.', 44, '2004-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 2, 'Debt', 'As Benson and Stabler investigate the disappearance of a mother and her teenaged daughter, they uncover a conspiracy between a corrupt immigration attorney and gangsters running a prostitution ring that is staffed by women they have smuggled into the country and imprisoned as sex slaves.', 43, '2004-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 3, 'Obscene', 'With the encouragement of a radio host, who has a dirty mouth on him, one teenager is raped and another is imprisoned when they are thrown together by the manipulative adults in their lives whose sole motivations are celebrity and publicity for their own self-serving interests.', 44, '2004-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 4, 'Scavenger', 'The entire squad races against the clock to solve the puzzles and uncover the clues scattered throughout the city by a serial killer who is taunting them to find him and the next victims on his list.', 43, '2004-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 5, 'Outcry', 'A missing teenager found beaten and tied up in a college dormitory under construction claims that she was raped by three students, but as the investigation proceeds and information obtained by the police and the press causes her story to unravel quickly, the girl recants. Since Benson remains convinced that a rape did occur, the focus of the investigation shifts to the girl''s overly-protective stepfather who has resisted the investigation from its onset.', 44, '2004-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 6, 'Conscience', 'The detectives and the district attorney get played first by the teenage murderer of a young boy, and then by the victim''s father, who uses his professional expertise to escape punishment for avenging his son''s death.', 44, '2004-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 7, 'Charisma', 'A career con artist, forger and thief turns to murder and serial pedophilia to populate the cult he created and to get his hands on a multi-million dollar trust fund. The detectives have trouble getting any leads because no one in the cult is saying anything, not even their names.', 44, '2004-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 8, 'Doubt', 'When a college student claims rape and her professor claims it was consensual sex, Stabler and Benson find themselves in the middle of a he said, she said battle, trying to decide whether to believe the alleged victim, or the alleged perpetrator who claimed she liked it rough. Benson sides with Myra, the victim, whereas Stabler finds himself wondering if Polikoff is telling the truth about being innocent, especially after Myra falsely accuses Stabler of touching her inappropriately. After giving more thought to the situation, Benson and Stabler each wonder if the other is right. Stabler has bigger problems on his hands, though, as Myra''s attorney reveals that Kathy has moved out and taken the children.', 43, '2004-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 9, 'Weak', 'After arguing with Benson about their personal lives, Stabler enlists the help of a former cop turned psychiatrist in apprehending a serial rapist and murderer who attacks disabled women.', 44, '2004-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 10, 'Haunted', 'Fin is reunited with his own son as he risks his life to save two small children, one caught in the middle of a bodega robbery and the other from the junkie who set the child''s mother up for murder and then stole him to use as a front in her scheme to boost materials for her meth lab.', 42, '2004-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 11, 'Contagious', 'After a car accident a nine-year-old girl is examined and it''s found she''s been sexually abused.  Out of fear and desperation, the girl blames her soccer coach for molesting her.  Soon a slew of other girls claim they also have been raped by the same coach.  During the investigation, Benson has to try keeping Stabler from falling apart as his wife has left him.', 43, '2005-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 12, 'Identity', 'Complications ensue in the investigation of a Stone Cold Assassins gangbanger who fell off a building after the victim that he tried to rape bit him in self-defense when the vic''s twin sister cops to the crime, seemingly impossible due to the evidence until the secrets regarding the sister''s true genetic identity are revealed.', 43, '2005-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 13, 'Quarry', 'When the body of a seven-year-old child is found, the squad again begins to investigate convicted serial killer Lucas Biggs, believing that he molested and murdered the boy. While Biggs can detail every child he ever molested, he swears that he has no memory of this one. Further investigations show that there is another suspect, but before he can be picked up, someone picks him off.', 44, '2005-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 14, 'Game', 'The squad is at a loss on what to do with a violent homicide when Stabler''s son points out that the event is straight out of a video game. Interviewing the game''s creators leads them to a former employee, who then leads them (with a few other steps along the way) to a teenage couple who claim to be unable to distinguish fantasy from reality.', 44, '2005-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 15, 'Hooked', 'When the body of a teenager is found with her older cousin''s I.D., Benson and Stabler investigate only to learn that that the teen had been part of a group who had ''hooked up'' online. As their investigation intensified, they realised that the victim was the object of an older man''s obsession, but before they can arrest him he also turns up dead.', 43, '2005-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 16, 'Ghost', 'When a wealthy couple is found dead in their home, Benson and Stabler soon realise that their deaths are connected to a drug smuggling ring. Eventually the road leads back to the same drug dealers who forced a former assistant district attorney into hiding, and Alex Cabot comes home to face her enemies.', 43, '2005-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 17, 'Rage', 'Fourteen years ago, Stabler had a chance to nail Gordon Rickett for the abduction, rape and murder of Dana MacNamara, but Rickett managed to get off. With the recent discovery of the body of Kerry Lynn Palmer, Stabler has another chance at cracking the case. They can only hold Rickett for twenty-four hours, but are able to glean enough information during that time period to at least have a place to start. Cragen and Benson both worry that Stabler will let his hatred for the suspected child molester interfere with his ability to do his job.', 43, '2005-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 18, 'Pure', 'After an 18-year-old girl is kidnapped, psychic Sebastian Ballentine comes forward claiming to have information on the killings. Stabler refuses to believe that Ballentine is a real psychic, and is convinced that the hints he is dropping about the case indicate he is somehow involved.', 43, '2005-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 19, 'Intoxicated', 'When Denise Eldridge finds her fifteen-year-old daughter Carrie in bed with twenty-one-year-old Justin, she immediately calls police to have Justin charged with statuatory rape. Benson intercedes on behalf of Carrie, calling a children''s rights lawyer to assist her, but when Denise turns up dead, Carrie and Justin both end up on the suspect list. Benson tries to get some help from Simone Bryce, but Bryce is obligated to protect her client.', 43, '2005-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 20, 'Night (I)', 'After a young woman is found raped and murdered near a nightclub with five hundred dollars stuffed into her mouth, Benson and Stabler follow the fingerprint trail on the money to Attorney Jason Whitaker, whose sole responsibility seems to be handling the trust for the Duvall family. Soon detectives are convinced that Gabriel Duvall is their rapist, but don''t have quite enough evidence to put him away. ADA Novak is working on both the case and a terrified former victim when she is brutally attacked in her office late at night.  The crossover continues on Law & Order: Trial by Jury S01:E11 Day (II).', 44, '2005-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 21, 'Blood', 'After a young woman''s baby is tossed out of a car, Benson and Stabler investigate to find out what happened, and after learning the young woman is addicted to prescription pain killers, their investigation leads them to an elderly woman named Jenny Rogers, who lives with her son Kevin and daughter-in-law Carol. The young woman finally identifies Carol Rogers as the person who solds her the drugs, but when detectives go to confront Carol they find her body, and are left trying to uncover who really killed Carol.', 44, '2005-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 22, 'Parts', 'After a woman''s head is found in a car junkyard, the detectives track it down to the black market.', 43, '2005-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 6), 23, 'Goliath', 'After the wife of a police officer claims her husband raped her, Benson and Stabler arrest the man and come close to believing his version of events when he attacks his captain. When another officer murders his wife and attempts to kill himself that same night, the whole force gets involved and soon realises that the two men both recently returned home from Afghanistan, where they were given the drug Quinium, an anti-malarial. With the reluctant help of reporter Sherm Hempell and a base doctor with an attack of conscience, Novak takes on the U.S. army. Stabler has trouble with the case because of his history in the marines.', 43, '2005-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 7, 'Season 7', 'The unit''s gut-wrenching cases include a schoolyard shooting of a child, a shady dating service and a shocking revelation regarding Tutuola''s son.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 1, 'Demons', 'Twenty years after being convicted of the rape of a teenage girl, Ray Schenkel is released, much to the dismay of retired detective William Dorsey. When a teenage girl is raped on the route Schenkel would have taken home, Stabler goes undercover as a recently paroled sex offender so that he can get into the same therapy group as Schenkel, and the same halfway house. Cragen worries that Stabler may be getting in over his head.', 42, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 2, 'Design (I)', 'Benson saves April Troost from committing suicide, but feels responsible when Troost dies during the trial of the man she accuses of raping her and getting her pregnant. It isn''t long before detectives learn that Barclay Pallister wasn''t the only man April picked up in a bar who has no recollection of sleeping with her, and the squad realizes that Troost was no victim. Their search takes them from prospective parents looking to adopt her child to the men she drugged and accosted to the sperm center she used to work at, which ends up at the center of the case.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 3, '911', 'Benson is on her way out for the evening when a call comes in from a little girl who says she''s all alone. While trying to draw the girl out, Benson is drawn deeper into the little girl''s life, and although the other officers begin to suspect the whole thing may be some sick joke, Benson is convinced that the little girl is the real deal. By talking to Maria, Benson is able to ferret enough information from her so that they have a place to start, but Maria''s captor has an affinity for electronics and has done everything he can to make sure that no one can find the little girl he bought and paid for.', 43, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 4, 'Ripped', 'When the teenage son of Stabler''s old partner comes under suspicion for attacking a classmate, Stabler''s inability to treat this like any other case gets him suspended.', 42, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 5, 'Strain', 'The discovery of the bodies of two young gay men who were both meth addicts as well as victims of a new strain of AIDS that can kill its victims in less than a year leads to an investigation. Tutuola learns that his son, Ken, is gay, and has difficulty accepting it, even though he and Benson end up going to Ken for help with infiltrating an anti-meth group. The group''s leader, Gabriel, soon becomes their top suspect when the squad realises that the two men died because they passed the disease on.', 43, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 6, 'Raw', 'After a six-year-old boy dies in a school shooting, detectives trace the gun used back to a white supremacist''s gun shop. Munch and Tutuola both face hatred and prejudice from the major suspects in the case, but their investigation soon takes them from the man who pulled the trigger back to the gun shop owner, who makes no bones about his hatred of anyone who isn''t white.', 43, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 7, 'Name', 'After the bones of a boy who disappeared in 1978 are found at a playground, Stabler, still visibly recovering from a recent gunshot wound, teams up with Vizcarrando to determine the boy''s identity, which leads them to a cold case involving four missing Puerto Rican boys that were never found.', 42, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 8, 'Starved', 'After a dating service is linked to three rapes, Olivia goes undercover to ferret out the rapist and meets Mike Jergens, a surgeon who enjoys controlling the women in his life. The detectives are soon led to his girlfriend, Cora Kennison, but shortly after testifying in the grand jury hearing Cora marries Mike. After Cora attempts suicide, Mike fights her mother, Virginia, to unplug her feeding tube.', 43, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 9, 'Rockabye', 'After sixteen-year-old Lauren Westley loses her unborn child due to a severe abdominal beating, her father''s insistence that Lauren was raped leads detectives to the baby''s father, but it isn''t long before the detectives realise that Lauren was an active party in her own beating, and the two teens had found it necessary to take the steps they did because the abortion clinic kept putting off Lauren''s request for an appointment. Novak faces a tough opponent in her own office when she and Branch disagree over the appropriate action to be taken against Wayne Mortens, the young girl''s boyfriend.', 42, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 10, 'Storm', 'When a teenager and her younger sister end up in the hospital after a day at the park, detectives learn that both girls were abducted from New Orleans after Hurricane Katrina along with a third sister who is still missing. Despite the interference of a local reporter, Jackson Zane, detectives are able to catch the kidnapper, a known pedophile, and recover the girl, but when Alvin Dutch dies and the autopsy determines it was Anthrax, Benson puts everything on the line so that she can get the truth out there.', 43, '2005-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 11, 'Alien', 'After young Sean Hamill is stabbed in the back at the schoolyard, detectives are led to Charlie Monaghan, the older boy who had previously gotten into trouble over Hamill, but it isn''t long before their attention turns to Monaghan''s half-sister Emma Boyd. Hamill had been torturing the little girl for months because she had two mothers. After getting a nice deal for Emma''s side, Benson and Stabler are thrown for a loop when Emma''s biological grandparents accuse Zoe, who had never legally adopted Emma, of sexually molesting the little girl, and evidence seems to support their claims.', 44, '2005-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 12, 'Infected', 'Monica Phelps is found dead in her apartment, her son Nathan hiding in the closet behind her body. Detectives soon link Monica''s death to philanthropist Ted Carthage, who runs an organization dedicated to helping people get off the streets. Benson is certain that Carthage is the killer, but a shaky ID from Nathan puts him back on the street. After Nathan kills Carthage himself, Sophie Devere argues that Nathan committed the killing because he saw Carthage shoot his mother -- something the gun manufacturers don''t like.', 43, '2006-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 13, 'Blast', 'The team investigates when young Carly Hunter disappears while walking home from school one day. While processing evidence found at the scene, Warner realises that the little girl has leukemia, and they need to get her home as soon as possible to begin treatment. Despite the ransom drop going wrong, the detectives are able to find the little girl thanks to evidence O''Halloran finds at the scene, but as she tells her story to Stabler and her mother, it soon becomes clear that her kidnapper is someone very close to home. Stabler and Warner end up becoming hostages when the kidnapper approaches Jake Hunter directly.', 42, '2006-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 14, 'Taboo', 'A college co-ed''s tale of rape and an unknown pregnancy is suspect after detectives learn that she''s been linked to not one but two abandoned newborns.', 43, '2006-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 15, 'Manipulated', 'After the body of Vicky Riggs is found, Benson and Stabler delve into her private life and finally learn that in addition to being a respected lawyer, she was also a stripper. A surveillance photo leads them to Linus McKellen, her boss'' husband, who was also having an affair with her. There isn''t enough evidence to prove he murdered Vicky, but when Vicky''s co-worker at the club, Josie Post, is also found murdered, DNA proves that McKellen''s semen was found in her body, despite his disabled wife Tessa''s conviction that he would never murder anyone. Suspicion turns on Tessa herself once the detectives interview the only man who seems capable of having committed the murders.', 43, '2006-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 16, 'Gone', 'Doug Waverly and Nick Pratt are charged with rape and murder in the disappearance of Canadian student Jennifer Durning after Nick''s cousin, Jason King, claims that while he had consensual sex with her that night the other two raped her. A stray pubic hair leads Novak to Keith Willis, a drunk who was paid off by the boys to get Jennifer out of the hotel and who later saw the boys kidnap her, but Willis exactly fit to be a witness as his mind has gone after years of alcohol abuse. Jason King disappears. Although they are able to find a bug in Donnelly''s office, they are not able to prove that it was placed there by Pratt or Waverly. Judge Donnelly is forced to dismiss the case against the two boys since there is no case without Jason''s testimony.', 44, '2006-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 17, 'Class', 'After Carolyn Pereira''s body is dumped in an area frequented by prostitutes, Stabler and Tutuola soon realise she had far more money than a student on financial aid should have had, and learn that she was deeply involved in the worlds of online gambling and high stakes poker. Suspects include the Gloria Culhane, the roommate who ended up with the very expensive ring that Caroline stole from a star athlete, Roddy Franklin, the star athlete who had his ring taken by Caroline, and Adam Halder, Caroline''s best friend from childhood who turned out to be her backup during her online gambling forays. Stabler makes a special plea for Halder, feeling like he and the young man have something in common because both were boys from the wrong side of the tracks dealing with rich kids who treated them like dirt.', 42, '2006-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 18, 'Venom', 'Ken Randall calls Benson for help after he''s picked up in an alley late at night. He claims that he was looking for a body after overhearing a man talk about murdering a woman and dumping her body while he was at the bar that night. Tutuola is upset that no one informed him, and determined to clear his son''s name even though Ken immediately gets his own lawyer. Tutuola turns his eye on Ken''s cousin, Darius Parker, who was with Ken that night and has been in and out of trouble for years, and after Ken voluntarily submits his DNA to clear his name, a shocking family connection between Darius and Ken is revealed. Darius confesses to having murdered the woman and her baby, but his confession is out because no one had contacted his lawyer.', 42, '2006-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 19, 'Fault', 'A manhunt ensues when Victor Paul Gitano, a recently released sex offender, kidnaps two children after killing the rest of their family. Benson and Stabler pursue Gitano only to find their own relationship challenged as both experience opportunities where they put their personal relationship ahead of their job. After having her throat slashed, Benson requests for a new partner when she hears what Stabler has to say about their relationship and their job.', 43, '2006-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 20, 'Fat', 'Stabler teams up with an new partner to investigate a sexual attack on Jessica DeLay, a sixteen-year-old girl who worked tobacco stings for the Department of Health and face an overweight young brother and sister who claim it was an act of vengeance for Jessica and her friend, Tommy Strahan, beating up their older brother Rudi for being fat. Stabler and Blaine arrest DeLay and Strahan, but when the two are released due to lack of admissable evidence, Rudi Bixton takes justice into his own hands.', 44, '2006-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 21, 'Web', 'When an eight-year-old propositions a male classmate, Stabler and Tutuola are called in to investigate the case and soon learn that Jake Winnock''s father spent seven years in prison for molesting his older brother, Teddy. D.N.A. tests clear Gregory Hensal of abusive his son, but implicate Jake''s older brother, whom detectives soon learn has been running his own personal Internet pornography site. T.A.R.U. tech Ruben Morales joins the detectives in their search for Teddy after he goes missing, but his own guilt about his nephew''s molestation after being raped by an online predator he met using the computer Morales had given him colors his judgment when dealing with one of the suspect''s.', 44, '2006-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 7), 22, 'Influence', 'After Jamie Hoskins falsely accuses two classmates of rape after a consensual act then hits nine pedestrians during an attempted suicide, medical tests reveal she has been taking medication for bipolar disorder and stopped her pills a week earlier. Jamie is charged with murder and released on her own recognizance after she agrees to take her medication, but after rock star Derek Lord, who is well known for his negative views on psychiatry, gets involved and begins spearheading her defense, Jamie again stops taking her medication. Novak is sympathetic to Jamie, but Jamie''s insistence on following Derek Lord''s advice leaves Novak with no choice but to take the case to trial.', 43, '2006-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 1, 'Informed', 'Benson is called in after a young woman shows up at the hospital, raped and beaten with her head shaved. Haley Kerns refuses to submit to a rape kit, but Benson steals her underwear before leaving the apartment and gives it to Warner to check out. When Benson returns to her apartment she encounters Star Morrison, who admits that Haley is a federal informant working with them on eco-terrorism. After Stabler is wounded while out on a search with Morrison, Benson and she work to get information from Haley before the eco-terrorists can strike.', 43, '2006-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 2, 'Clock', 'Stabler and Tutuola pair up to investigate when two teens go missing while their school is on a field trip to a local museum. Their investigation soon turns up evidence that the disappearance was staged to help Janey, who suffers from Turner''s Syndrome, be with her older boyfriend, a man with a prediliction for young girls, and to help the boy, Connor, make good on a gambling debt. Stabler experiences a rift with his daughter, Kathleen, who is upset over the way that he has handled her relationship with a young man named Kevin.', 43, '2006-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 3, 'Recall', 'Stabler and his new partner, Dani Beck, investigate the rape of a young woman named Nikki, who soon identifies a prominent lawyer, Martin Trenway, as her rapist. The squad has difficulty making the charges stick until another victim comes forward, but her testimony cannot be proven reliable. Determined to get at Trenway, Beck tracks down a woman from his past who holds the key to convicting Trenway, if they can convince her to expose the truth.', 43, '2006-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 4, 'Uncle', 'After a mother and her ten-year-old daughter are found raped and butchered in their apartment, Stabler and Beck take in a homeless man who turns out to be Munch''s uncle, Andrew. Initially he''s their main suspect until they find their way to a new suspect. Unfortunately, when their only evidence against Brent Allen Banks is thrown out in court, Andrew, suffering from mental illness, goes too far trying to do what he is convinced is the right thing.', 43, '2006-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 5, 'Confrontation', 'Stabler and Beck disagree on how to handle a case involving a rapist who seems to be escalating his attacks. Beck is getting too personally involved in the case and with the victims, which Stabler warns her against. The key witness in the case is a pregnant woman who denies having been raped more than once by the man, whose goal appears to have been to impregnate the women.', 43, '2006-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 6, 'Infiltrated', 'Novak tries to find Benson when the case for a previous rape victim, Chelsea Arndale, hinges on her testimony. Benson, meanwhile, is still living as Persephone James and has been arrested in Oregon after the ecologist''s group she has infiltrated is involved in a fracas with the local police. After the local sheriff advises her that her group is being looked at in connection with a recent murder, Benson decides to do a little investigating on her own and learns that the man was a pedophile. When she finally finds his private hideaway, it leads to a shocking conclusion.', 43, '2006-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 7, 'Underbelly', 'After a third young teen is found dead, a paw print tattoo on her lower back, Stabler and Beck investigate the tattoo, which leads them to Broder House, a foster home for young girls. They learn that Chantal was one of a number of girls who had ended up working the streets for a man named Victor. Stabler warns Beck that she can''t get emotionally involved in every case, but the two work together to bring down Victor, relying on one of his girls to get the evidence that they need.', 42, '2006-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 8, 'Cage', 'After a van containing two young children ends up in the river, Beck finds herself drawn to the young girl, Eden, and the investigation into a tape found in the vehicle turns up a mysterious death involving a controversial attachment therapy technique. Beck tries to do the right thing by saving Eden, only to find herself torn when it seems as though there is nothing she can do to help. The investigation into the rebirthing turns up a foster family who abuses the children in their care, but not all of the children agree that it was abuse.', 42, '2006-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 9, 'Choreographed', 'After Danielle Masoner dies in Central Park, Stabler follows the leads to a homeless man who turns out to be a better witness than he thought. Paired up again with Benson, Stabler investigates her death, but it keeps bringing up memories of Dani Beck for him. During the course of the investigation, Benson and Stabler learn that Danielle''s husband was sleeping with a friend of theirs, leading the squad to suspect first him, but their suspicion soon turns to the husband of the other woman.', 42, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 10, 'Scheherazade', 'Stabler heads to see terminal cancer patient Judson Tierney after a request from his parish priest, and soon realizes that Tierney has a story that he is dying to tell but only wants to tell to his estranged daughter. With Benson keeping an eye on Tierney, Stabler looks into the man''s past and learns that he was once involved in a series of unsolved bank robberies, and that he has been keeping a secret about his daughter for over twenty years.', 43, '2007-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 11, 'Burned', 'Stabler and Benson find themselves on opposite sides when Valerie Sennet accuses her estranged husband, Miles Sennet, of breaking into her home and raping her. Because Miles has no history of violence and Valerie refuses to allow detectives to use her daughter Tessa as a witness, he is soon released, and Stabler and Benson continue to clash as Benson remains convinced that Miles raped Valerie and is a danger, and Stabler believes it may be a case of a wife crying foul to punish her soon-to-be ex-husband.', 43, '2007-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 12, 'Outsider', 'Tutuola reluctantly works on a case involving the rape of a coed after his son Ken feels responsible for catching the rapist. Tutuola trying to solve the case with the rape victim unwilling to cooperate, crosses paths with another detective, Chester Lake, who is also investigating similar cases as part of Brooklyn SVU. The two clash at first but when another rape occurs, the two detectives must work together and pick up the pace before the rapist strikes again.', 43, '2007-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 13, 'Loophole', 'Stabler ends out being out of commission after a perpetrator high on PCP throws him through a window at the station, so Benson teams up with Munch and Tutuola to investigate a mysterious packet of photos. The photographs lead them to both a suspected child pornographer and a junkie burgler, but after Benson takes ill during the investigation, the team realises that there is more than child pornography at stake as their investigation soon reveals that Seth Millstead wasn''t into little boys at all, but had been using the tenants of the apartment building in an experiment for a new pesticide.', 43, '2007-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 14, 'Dependent', 'Benson and Stabler attempt to question a confused young woman about an attack on her parents that left her brother traumatized and Stabler puts his career on the line when he goes too far.', 42, '2007-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 15, 'Haystack', 'Stabler finds himself drawn into a case where a young mother has committed suicide after her baby goes missing. The case leads to questions for Benson about her own family history.', 43, '2007-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 16, 'Philadelphia', 'Benson finds herself in a bad situation when she has a closer link to a suspect than she ever could have expected.', 43, '2007-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 17, 'Sin', 'Stabler and Benson suspect a charismatic preacher in a case of murder until his wife provides them with another viable suspect.', 43, '2007-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 18, 'Responsible', 'Stabler seeks Kathleen''s help when investigating a case involving teenage alcohol abuse.', 43, '2007-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 19, 'Florida', 'When Detective Benson gets into the middle of an investigation of her brother Simon Marsden, the case begins to threaten her career. As Simon makes a run for it, Benson investigates further into his family life, and begins to question whether or not she was the product of a rape in the first place.', 43, '2007-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 20, 'Annihilated', 'A woman''s murder appears to be the result of a professional hit, when her fiancé receives death threats, apparently resulting from his CIA career. Elliot, investigating this, finds that the man may not be all that he seems.', 43, '2007-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 21, 'Pretend', 'The team investigates the death of a partially clothed teenage boy wearing a leather mask. The detectives discover that the victim''s best friend is the killer and has a video, showing that the boy''s death was the result of a backyard wrestling match gone wrong.', 42, '2007-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 8), 22, 'Screwed', 'Darius Parker, goes on trial for the rape and murder of a woman and her 14-month old child. The case brings Fin under fire from the media and even has Munch and Stabler at odds. Novak prosecutes the trial that brings Stabler and Tutuola, among others, to the stand. Many previous stories are brought into the trial.', 43, '2007-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 1, 'Alternate', 'Benson and Stabler investigate a suspected child abuse case only to learn that the woman who reported it is the real case.', 43, '2007-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 2, 'Avatar', 'Detectives are troubled to learn that someone has taken an online game too far when a girl goes missing.', 42, '2007-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 3, 'Impulsive', 'A teacher claims that a student pursued her after she''s charged with raping him.', 42, '2007-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 4, 'Savant', 'The only witness to a young woman''s horrific beating is her mentally challenged daughter.', 43, '2007-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 5, 'Harm', 'Benson and Stabler investigate the connection between the New York murder of college counselor Kate Simes and her volunteer work at a refugee center working with soldiers tortured in Iraq.', 42, '2007-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 6, 'Svengali', 'Benson comes under fire from fans of a convicted serial killer after a body turns up that greatly resembles his work.', 43, '2007-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 7, 'Blinded', 'Novak confronts ghosts from her past while handling the trial of a schizophrenic serial rapist, who seriously injured Stabler.', 42, '2007-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 8, 'Fight', 'Detectives find themselves embroiled in the world of ultimate fighting after a young girl''s death.', 43, '2007-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 9, 'Paternity', 'When the paternity of a missing young boy is placed into question, Stabler wonders if he really is the father of Kathy''s child. Later, Stabler faces the possibility of losing not only his partner but also Kathy and the baby when she and Benson are in an accident.', 43, '2007-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 10, 'Snitch', 'When a polygamist''s wife is murdered, he believes it''s related to a recent criminal case he was testifying in, but detectives believe it may be connected to his culture.', 41, '2007-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 11, 'Streetwise', 'A Park Avenue socialite''s body is found in NYC''S Central Park, and Detectives Benson and Stabler initially suspect her wealthy boyfriend.', 43, '2008-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 12, 'Signature', 'A woman''s body is found murdered in a park alongside a man with a bullet in his head - Benson and Special Agent Cooper join forces and suspect "The Woodsman", a serial killer Cooper has tried to catch for years. Lake and Benson begin to question Cooper''s true motives when the male victim is later identified as "The Woodsman".', 43, '2008-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 13, 'Unorthodox', 'Benson and Stabler investigate a tutor after a student is beaten and sexually assaulted, but their investigation soon leads them to another student.', 41, '2008-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 14, 'Inconceivable', 'The robbery of fertilized embryos from a sperm bank call for Benson and Stabler to track down the thief. Clues from the clinic''s security tape lead them to a long list of suspects including two publicity-hungry extremists. The detectives race against the clock to find the missing embryos, but that isn''t the only clock that''s ticking - Olivia considers her own fertility and the possibility of motherhood.', 41, '2008-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 15, 'Undercover', 'After a woman was found raped in a garden, Benson and Stabler realize that the case goes much deeper because of the victim''s mother, drugs, and the realization that a corrections officer is involved. Benson decides to go undercover at the same prison where the mother is, putting herself on the other side of the fence.', 43, '2008-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 16, 'Closet', 'After investment banker Jeremy Haynes is found dead, suspicions turns to his boyfriend Lincoln Haver, a professional football player who could lose everything if the truth of his sexuality became public. When news of Haver''s sexual orientation comes out, Benson comes under fire for her relationship with a reporter.', 43, '2008-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 17, 'Authority', 'An engineer plays a series of mind games with Benson and Stabler.', 43, '2008-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 18, 'Trade', 'When a pregnant woman''s body is discovered in a burned-out brownstone, the investigation turns to a family of coffee importers.', 41, '2008-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 9), 19, 'Cold', 'The squad is left at ends when Lake is caught in a gunfight and later takes a witness hostage.', 43, '2008-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 10, 'Season 10', 'Stabler confronts his own demons when his daughter is caught with drugs, and Benson follows connections between an abused child and an attack on a woman.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 1, 'Trials', 'After a young boy, Christopher Ryan, is caught driving a runaway van, Detective Elliot Stabler and Detective Benson take the seven year-old into questioning. When Christopher claims his foster parents, Gwen and Noah Sibert, bribe him in exchange for abusive medical testing, the detectives investigate his allegations.', 43, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 2, 'Confession', 'Teenage boy Eric Byers admits himself into the squad room, and warns the team about an unnatural desire towards his younger stepbrother, Cory Kelly. Detective Elliot Stabler and Olivia Benson’s suspicions arise, and Eric admits to also looking at a website to try to curb his pedophilic urge. With no crime committed, the detectives decide to investigate this “self-help” website for pedophiles leading them to it’s creator, Jake Berlin. Eric’s rage induced stepfather is also questioned, and shortly after Eric is found missing. The detectives must race to place the clues together to find and stop Eric before any crime is committed.', 44, '2008-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 3, 'Swing', 'Stabler is shocked when his daughter, Kathleen, becomes the suspect in an investigation to catch a trespasser. He seeks his estranged mother''s help in dealing with his daughter''s case.', 43, '2008-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 4, 'Lunacy', 'The investigation of a famous dead astronaut found in Battery Park has hit a dead end, causing Stabler to ask for assistance from his old mentor, Dick Finley, a former colleague of the victim and an astronaut himself.', 43, '2008-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 5, 'Retro', 'A baby with AIDS has Benson and Stabler asking for assistance from Warner as they investigate the case. They are pointed in the direction of a homeopathic doctor who has an questionable ethical past and who had prescribed the baby ineffective vitamins.', 42, '2008-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 6, 'Babes', 'Stabler and Munch uncover a chastity club and a group of girls with a pregnancy pact at a high school where they came to investigate the death of a student.', 43, '2008-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 7, 'Wildlife', 'Stabler goes undercover to infiltrate a rare animal smuggling operation.', 41, '2008-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 8, 'Persona', 'Benson finds herself going the extra mile to protect a woman abused by her spouse. The investigation turns up information regarding a long-forgotten case of 2nd degree murder and escape.', 42, '2008-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 9, 'PTSD', 'The death of a marine who was pregnant by a rapist puts the unit at odds with the Pentagon when they fight to keep the case, and Benson''s flashbacks of her own assault may further impede the investigation.', 42, '2008-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 10, 'Smut', 'A beaten and raped woman who has no memory of what happened to her puts Benson and Stabler on the trail of a serial rapist, but when women refuse to testify Olivia will have to face how her assault has affected her job performance.', 42, '2008-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 11, 'Stranger', 'When a girl who vanished four years ago reappears, she claims to have been imprisoned and sexually abused. Benson and Stabler look into the case and find themselves having to sort through what was fact and what the girl made up.', 42, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 12, 'Hothouse', 'When a teenager''s body is uncovered in the Hudson River, the detectives search for the victim''s identity which leads Benson to go undercover as a madam.', 43, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 13, 'Snatched', 'The mother of a kidnapped young girl points the detectives towards her father, an ex-con, but it is soon discovered that the grandfather is a master thief and has many enemies. However, because of Alzheimer''s, the grandfather can''t remember much of his past.', 42, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 14, 'Transitions', 'The detectives have very little to work with after a man is found badly-beaten in a strip club''s parking lot. Their questioning begins with the dancers until the victim''s ex-wife and 13-year old transgender daughter become suspects.', 43, '2009-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 15, 'Lead', 'When a pediatrician convicted of abusing patients is found dead, Stabler and Benson investigate and soon find ADA Cabot has a reason for becoming involved in the case.', 42, '2009-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 16, 'Ballerina', 'A single murder suddenly turns into a scene with three bodies, leaving Benson and Stabler to work with a strip club owner to find a murderer whose motive may be more about righteousness than perversity.', 42, '2009-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 17, 'Hell', 'Detective Munch investigates the brutal rape and beating of a young mute girl, but things become tricky when her drawing of the devil who attacked her resembles a local priest who may not be practicing his beliefs according to Canon.', 42, '2009-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 18, 'Baggage', 'A turf war ensues when Stabler and Tutuola link an artist''s murder to a serial killer, and the detective assigned to that case focuses more on their involvement in an investigation he believes belongs solely to him than on identifying the killer.', 42, '2009-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 19, 'Selfish', 'A grandmother reports that her 2 year old granddaughter has disappeared, but the Amber Alert fails to yield progress. The detectives then move their attention over to her young irresponsible mother as their prime suspect.', 42, '2009-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 20, 'Crush', 'A teenage girl who sent text messages containing nude pictures of herself is found beaten up. She next faces a harsh sentence from a judge after being arrested for producing and distributing child pornography.', 42, '2009-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 21, 'Liberties', 'A favor for a judge who is hearing a harassment case sends Stabler and Benson to interview a death-row serial killer in order to determine the fate of his son.', 43, '2009-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 10), 22, 'Zebras', 'A murder in Central Park that involves a tourist puts the SVU on high alert, but when the suspect they''ve brought in for questioning escapes, Munch has to reach out to an ex-wife in an effort to prevent another killing that''s closer to home.', 42, '2009-06-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 11, 'Season 11', 'A new ADA joins the team, a crime scene photo of a murdered teen goes viral and Stabler tries to prove Benson did not murder a biker.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 1, 'Unstable', 'Officer Nate Kendall aids a woman in trouble and becomes roped into solving a rape case. While Detectives Elliot Stabler and Olivia Benson believe that Kendall is not right for the case due to his unstable personality, Executive ADA Sonya Paxton joins the team, bringing evidence of a common thread among three other rape cases. With Paxton’s help, the team might expose a serial rapist.', 43, '2009-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 2, 'Sugar', 'A young woman''s body is found stuffed inside a suitcase, and police believe that Mindy Keefe, the victim, was a train passenger on her way to Tampa when she was murdered. Detectives Benson and Stabler turn to Keefe''s financier boyfriend, Owen Cassidy''s yacht to investigate. However, Cassidy claims he was on his boat during the time of the murder. After further searching, the detectives discover Keefe belonged to an online dating website. But when the CEO of the dating website, Vance Shepard, refuses to comment on the case, the detectives turn to ADA Sonya Paxton for help.', 42, '2009-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 3, 'Solitary', 'When Lily Milton is reported missing, her boyfriend, Parker Hubbard, points Detectives Benson and Stabler in the direction of Callum Donovan, Lily''s downstairs neighbor and convicted bank robber who spent nineteen years in solitary confinement. During the investigation into Donovan''s alibi, Lily is found alive, adding a surprising twist to the case and exposing more of Donovan''s dark past.', 43, '2009-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 4, 'Hammered', 'After a night of heavy drinking, Dalton Rindell wakes up to a bloody apartment, a terrible cut on his head and a dead woman in his bed. Unable to recall the night before, Rindell immediately calls the police. Detectives Benson and Stabler suspect the crime is the result of a deadly love triangle; however Rindell does not recognize the victim. After questioning Rindell and the victim’s family and friends, Benson and Stabler are provided with leads in several different directions. Unsure which lead to follow, the two detectives decide to return to the bar where the night began in order to piece together the gruesome truth.', 42, '2009-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 5, 'Hardwired', 'After Eva Banks makes a shocking discovery about her son''s behavior at school, she takes him to the doctor, only to find out that he has been the victim of sexual abuse. Detectives Benson and Stabler come onto the scene and question the victim and his family.', 43, '2009-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 6, 'Spooked', 'The FBI gets involved in a murder case when it becomes too dangerous for the SVU cops.', 42, '2009-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 7, 'Users', 'The team investigates the father of a murdered teenager whose crime scene photo has gone viral on the web, but they believe they''ve found a more likely suspect when they speak with the girl''s therapist. The case becomes more frustrating as alibis exclude suspects and a strange occurrence in the morgue sends them in a different direction.', 42, '2009-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 8, 'Turmoil', 'Stabler is torn between a troubling rape case which victim has had pictures posted on the net and his son, whose friend''s actions may endanger a life and both of their futures.', 44, '2009-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 9, 'Perverted', 'DNA links Olivia to the murder of a biker in Central Park whose gang specialized in hits and prostitution. With Munch and Fin assigned to the investigation and evidence continuing to mount against Benson, Elliot begins his own inquiry – determined to prove her innocence and save her career.', 42, '2009-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 10, 'Anchor', 'Fin''s investigation into three little girl''s deaths takes him into the world of immigration, anchor babies, a grassroots opposition movement, a radio talk show host who fans the hatred, and an immigration rights attorney who is somehow tied up in everything.', 42, '2009-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 11, 'Quickie', 'One case becomes two as a murder leads to a serial rapist who is busy spreading disease along with his assaults, and the detectives'' only clue is a website set up for casual and anonymous encounters.', 42, '2010-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 12, 'Shadow', 'When a rich and powerful couple with political connections is found murdered in their bedroom, Detectives Olivia Benson and Elliot Stabler decide to speak to the deceased couple''s daughter, Anne, for more information. After hearing Anne''s account of a nefarious man who has been following her, the detectives soon discover that Anne''s supposed stalker is none other than Detective Ash Ramsey of the Special Frauds division. Convinced that Anne killed her parents for their money, Ramsey becomes suspicious of Anne''s business manager and is led to believe that he helped her steal money from the foundation she runs. When blackmail and embezzlement come into play, the detectives find that their lives may be at risk over a girl with some serious parent issues.', 42, '2010-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 13, 'P.C.', 'Detectives Olivia Benson and Eliot Stabler find a woman bleeding from the neck and nearly dead. The woman dies before they reach the hospital, and soon the investigation leads them to the frontman of the death metal band Vampyre Sacrifyce. He bites girls, steals blood from the local blood bank and sings about violence to women all in the name of his strange, vampiric lifestyle. The singer claims he was nowhere near the scene of the crime, and soon a lesbian rights group led by Babs Duffy  gets involved, claiming the victim''s death was a result of police neglect. However, when more women from Babs''s group are attacked, it becomes clear that the victim''s case wasn''t an isolated incident and that someone out there has a larger plan to bring the group down.', 42, '2010-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 14, 'Savior', 'When a series of young prostitutes are found murdered with homemade prayer cards attached to their bodies, Detectives Olivia Benson and Eliot Stabler struggle to find the common thread. However, just when they think that they''ve found the murderer, Captain Donald Cragen informs the detectives that another victim named Gladys has turned up with a prayer card. This time she survived. As the case unfolds, Benson finds herself getting emotionally invested in the survivor until she is forced to make a decision that she isn''t ready to face.', 42, '2010-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 15, 'Confidential', 'Benson and Stabler investigate the abduction of a woman in a building owned by a high-powered and highly protected investment banker, but when Munch''s memory of an eerily similar crime proves true the focus turns toward potentially freeing an innocent man, and it may take the DA himself to shake loose the truth.', 43, '2010-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 16, 'Witness', 'Soon after a young girl, Laine McAlister, is raped in her apartment building''s stairwell, Detectives Olivia Benson and Eliot Stabler meet Laine in the hospital and find her extremely shaken with a large cut on her hand. After an unpleasant exchange with a man she claims is her boyfriend, the detectives become suspicious that she may have fabricated her rape to get attention. Their suspicions grow when she waits to reveal that there was an eyewitness. As the gravity of the situation intensifies, Benson and Stabler find themselves in a race to track down the witness and get a testimony before it is too late.', 43, '2010-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 17, 'Disabled', 'Detectives Olivia Benson and Eliot Stabler are called in to investigate when a disabled woman, Cara Benson, is beaten and raped. Though the victim''s condition has rendered her unable to speak, the detectives soon deduce that someone close to her is responsible, with the lead suspects being her resentful sister and troubled nephew. As the investigation continues, Benson and Stabler strive to make Cara comfortable with coming forward to stand up for herself and illuminating some of the disturbing truths about the assisted living business.', 42, '2010-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 18, 'Bedtime', 'When a journalist is found raped and murdered in her own bed, Cragen is able to connect this particular case to another five murders that happened thirty years ago, committed by the "Bedtime Butcher". To uncover the truth behind the crimes, Benson goes undercover in order to find the real killer.', 42, '2010-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 19, 'Conned', 'A case of mistaken identity complicates the investigation into the murder of whom most believe was an uninvited wedding guest at a hotel in which the body was found.', 42, '2010-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 20, 'Beef', 'After a young woman is sexually assaulted and murdered, Detectives Olivia Benson and Eliot Stabler track down the woman''s boyfriend - their first suspect - but learn that he is a devout vegan who wouldn''t hurt a fly. They soon find that the victim had been deeply involved in the fight to expose questionable practices in the meat-packing industry, even going undercover at a large company to find out the truth. Benson goes undercover herself to retrace the woman''s footsteps and to identify who the victim might have angered along the way.', 41, '2010-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 21, 'Torch', 'After two young girls die in a fire, Stabler finds a familiar face in the prosecutor assigned to the case.', 43, '2010-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 22, 'Ace', 'When a pregnant woman is raped, Detectives Olivia Benson and Eliot Stabler arrive at the hospital to find that she has fled. Even when someone is arrested for a similar offense, ADA Jo Marlowe says she doesn''t have a case in court unless they find the victim and get a statement from her. Soon, Benson and Stabler connect the woman to an illegal adoption operation, forcing them to go undercover and expose the truth.', 42, '2010-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 23, 'Wannabe', 'After a man flashes customers at an electronics store, it is discovered that someone who matches his description has recently raped three young girls. Captain Donald Cragen orchestrates a movement to catch the rapist, and a rookie cop makes an arrest. Detectives Olivia Benson and Eliot Stabler confirm that they''ve found their man, but after ADA Jo Marlowe  expresses some doubts, it is soon discovered that the so-called rookie may have some secrets of his own.', 42, '2010-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 11), 24, 'Shattered', 'The detectives end up in a dangerous situation while investigating the whereabouts of a kidnapped eight-year-old boy.', 42, '2010-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 1, 'Locum', 'Benson and Stabler are called to investigate when a little girl goes missing. They soon find out that the mother had another daughter who disappeared some years earlier and she becomes the focus of the investigation.', 42, '2010-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 2, 'Bullseye', 'The brutal rape of a ten-year-old girl leaves her unable to recall her own name. Unfortunately, once Fin assists with the ID, the detectives find that she’s not the only one with memory impairment, and Dr. Huang is brought in to assess her home situation.', 42, '2010-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 3, 'Behave', 'A woman who has been raped multiple times is afraid to leave her house. The issue of unopened rape kits will see Detective Olivia Benson travel from New York City to Los Angeles.', 43, '2010-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 4, 'Merchandise', 'A teenage girl’s death exposes a human trafficking ring and leads detectives Olivia Benson and Elliot Stabler to team up with an old friend at the U.S. Attorney’s office.', 42, '2010-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 5, 'Wet', 'Detectives Benson and Stabler arrive on the scene where a woman is found dead in Bethesda Fountain. When her squeaky clean image doesn’t match up with her promiscuous actions on the night of her murder, ADA Mikka Von encourages the cops to dig deeper into her past.', 42, '2010-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 6, 'Branded', 'Two men have been branded and sodomised by someone. Is there a connection between these men, and what nut case is on the loose?', 43, '2010-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 7, 'Trophy', 'A rape and murder investigation puts the detectives lives at risk.', 43, '2010-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 8, 'Penetration', 'Undercover FBI agent Dana Lewis returns to help the detectives with a case.', 42, '2010-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 9, 'Gray', 'Stabler''s participation in a Take Back the Night rally at Kathleen''s campus results in an extra case for him and Benson when a student claims she was raped. Unfortunately, the case turns out to be a "he said-she said" type with little evidence. Enter Sonya Paxton, and it can only get more complicated.', 43, '2010-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 10, 'Rescue', 'With young Calvin in her care, Detective Benson continues the search for his drug-addict mother, Vivian, but Detective Stabler notices a strong bond forming between Benson and the boy. When Vivian’s name comes up during a rape investigation, Captain Cragen assigns Detectives Fin and Munch to the case instead. However, it will take more than Cragen’ s orders to keep Benson away.', 41, '2010-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 11, 'Pop', 'A young boy is found dead on a park carousel after being dropped off by his uncle Joe Gilbert. When Detectives Benson and Stabler learn that the boy was beaten to death they suspect that it could be the result of a bully at school. The investigation leads to an unsettling gambling ring. Detectives suspect that Gilbert''s acquaintance, Joe Roberts is beating his wife Sandra and the case takes a horrifying turn.', 42, '2011-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 12, 'Possessed', 'A young man finds that his girlfriend Larissa Welsh has been attacked in her apartment with evidence that points to her buried past. Detectives Benson and Stabler go in search of her attacker and discover that an elderly man, Orville Underwood, may have been involved in traumatic events of Welsh’s past. For the detectives, solving the case comes down to who was in possession of the evidence.', 43, '2011-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 13, 'Mask', 'Debbie Shields comes home to find her partner Ann Jackson being raped by a man wearing a haunting mask. Shields contacts Ann''s father to notify him of her critical condition. As detectives Benson and Stabler interrogate Ann''s father, Captain Jackson, his sordid past is revealed filled with sexual and alcohol addiction. Jackson''s new role as a sex therapist is hindering the detectives from getting the information they need to solve the case and if Jackson won''t comply, the detectives are going to have to get creative.', 42, '2011-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 14, 'Dirty', 'Detective Saliyah "Sunny" Qadri goes in search of Brooklyn District Attorney Page Ferguson, who she fears may be in danger. Qadri finds Ferguson just in time to witness her fall from the top of a parking garage. When Benson arrives, she discovers that the crime scene has been tampered with. Benson turns to an old friend, Assistant U.S. Attorney Christine Danielson for help. As the investigation progresses, Benson begins to question Ferguson’s suspicious past and Qadri’s involvement in the case.', 41, '2011-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 15, 'Flight', 'When it is discovered that a teenage girl is suffering from Post Traumatic Stress Disorder due to sexual abuse, all leads point to billionaire Jordan Kress. As Detectives Benson and Stabler continue to investigate, Kress involves his lawyer, Dwight Stanitch, who throws the whole case awry.', 41, '2011-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 16, 'Spectacle', 'After the sexual assault of a young woman is videotaped and featured on a campus-wide intranet feed, detectives Elliot Stabler and Odafin "Fin" Tutuola go in search of the victim and her attacker. As they delve into the investigation, it becomes clear that the perpetrator created a spectacle to draw attention to his own issues.', 41, '2011-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 17, 'Pursuit', 'The TV host of a show that spotlights predators receives threats to her safety, and this reawakens her hunt for her sister''s abductor. An ADA with connections to the TV host then assists detectives in their investigation.', 43, '2011-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 18, 'Bully', 'An art patron finds a body, and when detectives question the murdered woman''s good friend and associates, they uncover an antagonistic work environment filled with grown-up bullies.', 42, '2011-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 19, 'Bombshell', 'A grifter named Cassandra strikes swinging men who frequent sex clubs.', 42, '2011-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 20, 'Totem', 'When a young girl is found dead with a doll that is believed to have been left as a totem, detectives Benson and Stabler team up with Captain Jackson, a psychologist who assisted them with a recent case, to investigate her murder. Jackson joins the detectives as they retrace the girl’s last steps and go to meet with her piano teacher June Frye. Jackson’s skills prove to be invaluable in deciphering the meaning of the totem and ultimately finding her killer.', 43, '2011-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 21, 'Reparations', 'Two high-powered attorneys face each other across the aisle when Casey Novak returns to the team, and Joe Dekker takes a leave of absence from his Los Angeles duties after his cousin is charged with rape. Dekker''s unwavering belief in his cousin''s innocence, and a court disturbance make Novak and Benson take another look at the evidence, which leads them to someone playing a very long game in the name of hatred.', 42, '2011-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 22, 'Bang', 'When an abandoned baby is found on playground, Detectives Benson and Stabler go in search of the child’s caregiver. Upon meeting the nanny and her boyfriend, Ken Turner, they soon realize that he is also engaged to the baby’s adoptive mother, Dede Aston. As the detectives dig deeper into Turner’s malevolent past, they realize that the law may be on his side.', 41, '2011-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 23, 'Delinquent', 'When a young woman finds a teenage boy asleep and naked in her bedroom, his mother, Bree Walsh, is quick to defend him. While Detective Benson and Detective Stabler try to figure out what truly happened, they also have to manage the sneaky teenager and his naive mother. As the detectives dig deeper, they discover how deceptive appearances can be.', 42, '2011-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 12), 24, 'Smoked', 'When a woman is murdered during an afternoon shopping trip with her daughter, Detectives Benson and Stabler are called in because she was scheduled to testify in their high-profile rape case. As the detectives continue to investigate the correlation between the murder and their case, they discover unlikely friendships that will lead them to the truth.', 41, '2011-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 13, 'Season 13', 'Season 13 dealt with the departure of Detective Elliot Stabler from the Special Victims Unit after a shooting in the squad room.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 1, 'Scorched Earth', 'An African immigrant working as a maid accuses an Italian diplomat of rape, but is she really in it just for the money? Meanwhile, Stabler''s return remains in doubt after his latest shooting.', 44, '2011-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 2, 'Personal Fouls', 'SVU investigates an accusation that a revered high school basketball coach sexually abused his players, but they ultimately may need the cooperation of a reluctant pro superstar to make the case.', 43, '2011-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 3, 'Blood Brothers', 'A pregnant thirteen-year-old girl from Washington Heights claims that the son of an ambassador raped her, but the accused goes missing before SVU can question him.', 44, '2011-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 4, 'Double Strands', 'Detective Rollins believes that SVU has caught a serial rapist from one of her earlier cases in Georgia, but a passioned request after a suicide attempt leads Amaro to suspect that they may have the wrong person.', 44, '2011-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 5, 'Missing Pieces', 'Detectives search for a missing baby on Halloween after a young mother from Buffalo tells them her car was stolen while her baby was still in it.', 43, '2011-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 6, 'True Believers', 'The SVU team works together to investigate the case of a promising music student who was brutally raped at gunpoint.', 44, '2011-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 7, 'Russian Brides', 'In order to bring down a Russian mobster running an international prostitution/kidnapping ring disguised as a Russian bride website, Cragen steps from behind the desk to go undercover.', 44, '2011-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 13), 8, 'Educated Guess', 'A patient in a mental hospital claims to have witnessed a sexual assault. However, the supposed victim is a fellow patient who has a history of making rape allegations, but she denies being assaulted this time.', 44, '2011-11-16');
