INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 26), 20, 'Shock Collar', 'When a car with a young girl in the backseat is stolen, the SVU investigates whether it was a crime of opportunity or a targeted abduction.', 42, '2025-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 26), 21, 'Aperture', 'When an assault at gunpoint is witnessed through a neighboring window, the squad scrambles to locate the victim to confirm she''s safe. A threat to extort the victim''s family leads to a shocking suspect.', 42, '2025-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 26), 22, 'Post-Rage', 'Benson investigates a string of sexual assaults targeting local female psychiatrists. The squad celebrates a promotion.', 42, '2025-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')), 27, 'Season 27', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 1, 'In the Wind', 'Danger swirls around the squad as they investigate a suspect for rape and try to protect their key witness. A new chief of detectives puts Benson to the test. An off-duty Fin tries to stop an assault in progress.', 43, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 2, 'A Waiver of Consent', 'When a member of an elite social club is assaulted, Carisi must convince witnesses to come forward despite the club''s strict confidentiality rules. Chief Tynan offers Benson some extra help. Velasco is confronted with a surprising opportunity.', 43, '2025-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 3, 'A Vicious Circle', 'Bruno suspects a bomb was planted to destroy DNA evidence in a rape case. Benson takes on a murder investigation connected to the bombing. Griffin experiences the frustrating setbacks of working an SVU case.', 43, '2025-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 4, 'Clickbait', 'When a tween suffers a life-threatening miscarriage, the SVU must unravel a web of online fabrications to identify a suspect. Rollins carefully weighs her career options.', 43, '2025-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 5, 'Feed the Craving', 'When a woman in active labor is abducted, Rollins and Curry look to her doula for an account of events. Carisi tries to get a confession in front of the jury.', 43, '2025-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 6, 'Under the Influence', 'The squad investigates an assault at a house party where no one can identify the assailant. When two suspects are detained for questioning, Rollins takes the chance to turn one against the other.', 43, '2025-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 7, 'False Idols', 'The SVU must determine fact from fantasy when a famous author twists the details of a serious crime. Fin has a challenging day at work.', 43, '2025-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 8, 'Showdown', 'When a man claims his girlfriend was kidnapped, Bruno investigates the holes in his story. Tynan comes down hard on Benson after a disagreement. Griffin must defend his police work on the stand.', 43, '2025-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 9, 'Purity (II)', 'The hunt for a murder suspect uncovers a crime with shocking legal and ethical implications. Bruno must protect his squad during a raid on a suspect''s home. Carisi and Price team up in court when Brady''s interrogation tactics undermine the case.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 10, 'Fidelis Ad Mortem', 'When Curry''s son finds a disturbing cassette tape in a thrift store haul, she and Benson must investigate a decades-old missing persons case. Griffin learns a disturbing rumor about his father.', 43, '2026-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 11, 'Career Psychopath', 'When a stranger threatens Rollins and Carisi''s lives, they suspect it''s connected to a case they worked together. Benson asks an old friend to come out of retirement for help with an investigation.', 43, '2026-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 12, 'Hubris', 'A teenager rescued from a dangerous situation begs Benson to help reunite her with her father. Carisi and CJ take the foster system to task for separating families without sufficient proof.', 43, '2026-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 13, 'Corrosive', 'An attempt on a respected judge''s life is connected to an anonymous video posted to the SVU tip line. Rollins tries to help a victim come to terms with their abuse.', 43, '2026-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 14, 'Frequency', 'A family discovers a young boy in grave danger when their baby monitor picks up a rogue frequency. Griffin goes to extremes to find the boy''s location. Rollins finds herself alone with a predator.', 43, '2026-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 15, 'Thirsty', 'Reports of an assault by a guest at a fan convention leads to a murder investigation. Tynan presents Capt. Curry with a career opportunity.', 43, '2026-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 16, 'Vivid', 'With little evidence to guide them, the SVU steps in when a woman undergoing psychedelic-assisted therapy recovers a buried memory of assault. Curry starts a new position at SVU.', 43, '2026-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 17, 'Deep Under', 'Benson is shocked to find undercover Detective Velasco at the center of a sex trafficking bust. When more women are smuggled into the city, a rescued victim begs SVU to help save her sister.', 43, '2026-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 18, 'Gimmick', 'A mysterious death in a hotel leads the squad into the world of professional fighting. Benson tries to convince a victim to come forward for the sake of his friend.', 43, '2026-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 19, 'Impropriety', 'An unconscious and injured teen abandoned outside a hospital sends the SVU on a search for the people who left her there. Benson faces serious consequences when she chooses to protect a victim''s secret under the pressure of cross-examination.', 0, '2026-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 20, 'Old Friends', 'The squad must untangle conflicting stories and long-buried secrets when a drug-fueled college reunion ends in sexual assault. With the squad under internal pressure by Tynan, Fin keeps the case on track.', 0, '2026-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0203259')) AND numero_temporada = 27), 21, 'Monster', NULL, 0, '2026-05-14');
