INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 9, 'Knit, People, Knit!', 'Christopher''s well-intentioned gesture at Stars Hollow''s knit-a-thon brings the event to an early end.', 42, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 10, 'Merry Fisticuffs', 'When Christopher witnesses a sweet moment between a couple, he becomes concerned about his partner''s commitment to him.', 41, '2006-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 11, 'Santa''s Secret Stuff', 'Luke asks Lorelai to write a character reference letter for his court case. Lorelai, Christopher and Rory have a late but extravagant Christmas.', 41, '2007-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 12, 'To Whom It May Concern', 'Sookie acts strangely. Luke attends his court case hearing. Lorelai is confronted about the character reference letter she wrote for Luke.', 42, '2007-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 13, 'I''d Rather Be In Philadelphia', 'During a family emergency, Lorelai can''t reach Christopher. Meanwhile, Logan and Luke drop everything to support Rory, Lorelai, Richard and Emily.', 42, '2007-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 14, 'Farewell, My Pet', 'Rory has a crush on the teacher filling in for Richard. Christopher and Lorelai talk about their current relationship with each other.', 42, '2007-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 15, 'I''m a Kayak, Hear Me Roar', 'Lorelai helps Emily organize domestic affairs but has trouble revealing the current state of her love life. Rory attends a birthday dinner for Logan.', 42, '2007-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 16, 'Will You Be My Lorelai Gilmore?', 'Rory has an interview. Lorelai must settle a fight between Lane and her mother. Logan reveals a failure to Rory.', 42, '2007-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 17, 'Gilmore Girls Only', 'Lorelai, Rory and Emily go on a road trip to attend the wedding of an old friend. Someone makes a surprise appearance, asking Rory to forgive him.', 41, '2007-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 18, 'Hay Bale Maze', 'Rory shows her boyfriend around Stars Hollow, while Lorelai worries he''s too irresponsible. Lorelai and Luke admit they both made mistakes.', 42, '2007-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 19, 'It''s Just Like Riding a Bike', 'After an awkward encounter, Lorelai and Luke start fighting, which Lorelai takes as a good sign. Rory gets a letter that impacts her future plans.', 42, '2007-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 20, 'Lorelai? Lorelai?', 'Rory has a scary dream about what lies ahead for her. A visitor discusses Rory''s future with Lorelai. Lorelai pours her heart out on karaoke night.', 42, '2007-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 21, 'Unto The Breach', 'Emily and Richard host a graduation party for Rory. Lorelai and Christopher are relieved to find they can still be friends. Logan surprises Rory.', 41, '2007-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0238784')) AND numero_temporada = 7), 22, 'Bon Voyage', 'In this series finale, Rory makes a sudden change in her summer plans, and Luke enlists everyone in Stars Hollow to throw her a farewell party.', 42, '2007-05-15');
