INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 1, 'The Big Problem', 'Tired of being a kid, Timmy wishes he could be older in order to go adult things, but his wish backfires when "Da Rules" states that now that he is an adult, Cosmo and Wanda can''t grant him any wishes or turn him back into a kid until he is a kid or acts like a kid.', 12, '2001-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 2, 'Power Mad', 'After wishing for a challenging virtual reality game, Timmy goes to the bathroom and leaves it unattended, and Chester and AJ decide to play. Realizing what has happened, Timmy must go into the game and play to save them.', 12, '2001-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 3, 'Spaced Out', 'While watching Crash Nebula, Timmy wishes for an alien to play with. So, Cosmo and Wanda take a real alien prince - Mark. His parents are furious and travel to Earth to blow it up.  In the meantime, Mark has fallen in love with Vicky, and Timmy can''t wish him away because GodParents can''t interfere with true love. Timmy goes to Mark''s parents and asks them to convince their son to forget about Vicky, but Timmy must first pass their toughest tests. Will he be able to fix this mess and save the Earth from destruction?', 12, '2001-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 4, 'TransParents', 'After Timmy brings an extinct dinosaur to school, his crazy teacher suspects that he has Fairy GodParents, so he tells Timmy he wants to have a conference with his "parents." Since he has aspirations of "a new world order," he thinks that if he catches fairies, he can harness their power and rule the Earth. Timmy knows he can''t explain to his real parents how he managed to come across an extinct dinosaur, so Cosmo and Wanda pose as his parents.', 12, '2001-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 5, 'A Wish Too Far', 'Timmy has a giant crush on Trixie Tang, the most popular girl in school, but she doesn''t even know he exists. In order to get Trixie to notice him, Timmy wishes for a long list of superficial things to make him popular.', 12, '2001-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 6, 'Tiny Timmy', 'Cosmo and Wanda shrink Timmy so he can complete his assignment on the microscopic universe but problems ensue when Cosmo and Wanda, who have also shrunk themselves, get eaten by Vicky. Timmy must now go inside Vicky to save his godparents but stirs up a lot of trouble in the process. To make matters worse, Vicky plans on tearing apart the house and blaming it all on Timmy to his parents.', 12, '2001-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 7, 'Father Time!', 'When Timmy breaks his dad''s sentimental, grade school trophy and gets punished, he wishes himself back in time to stop his dad (as a kid) from ever winning the dumb thing in the first place.', 12, '2001-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 8, 'Apartnership', 'After Wanda gets mad at Cosmo on their umpteenth anniversary, Cosmo visits Fairy World. There, his mom, who has always hated Wanda, announces that she has found him two new girlfriends, Twinkle and Star. In order to get Cosmo back, Wanda must compete against Twinkle and Star in a game show hosted by Cupid, but Cosmo''s mom will do anything to ensure that he doesn''t go home with Wanda.', 12, '2001-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 9, 'Chin Up', 'Timmy meets his favorite superhero, The Crimson Chin, but the discovery that he is fictional sends the hero into a deep depression. Timmy must now reverse this situation, and as a result, he gains the superhero alter-ego of Cleft the Boy Chin Wonder.', 12, '2001-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 10, 'Dog''s Day Afternoon', 'Timmy switches lives with Vicky''s dog, but swiftly discovers that the dog actually has it just as badly as he does.', 12, '2001-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 11, 'Dream Goat', 'When Timmy feels sorry for the town''s caged, prize goat, Chompy, and wishes he could be free, the goat disappears and Vicky gets blamed for goat-napping.', 12, '2001-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 1), 12, 'The Same Game', 'Timmy wishes for everyone in the world to be the same when an evil dentist won''t give him his ball back. Problems inevitably ensue, and Timmy can''t wish things back to normal as Cosmo and Wanda aren''t able figure out who he is.', 12, '2001-05-04');
