INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 4, 'Inspection Detection', 'Thanks to all the stuff he''s gotten from his fairies, Timmy''s parents suspect that he''s a shoplifter. On the same day, Cosmo and Wanda have an inspection day with Jorgen Von Strangle. Timmy must prove his innocence while his godparents prove their competence or they''ll never see each other again.', 12, '2002-03-08');
