INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 7, 'Timvisible', 'Timmy''s shot at the perfect attendance award is threatened by bully Francis. Timmy wishes to become invisible, but soon, everyone believes the school is haunted. That is, except Crocker, who knows that catching Timmy will be all the evidence he needs to prove the existence of Fairies.', 12, '2002-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 8, 'That Old Black Magic', 'Timmy goes to an amusement park in Friday the 13th and he figures that something is destroying the park, until Cosmo and Wanda give him special glasses to see the Anti-Fairies who are causing the problem.', 12, '2002-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 9, 'Super Bike', 'For the annual Father-Son bike race, Timmy wishes up a bike that''s unstoppable, unbreakable, and totally modern and cool: Super Bike. But the bike gets super jealous of Timmy''s friends and hobbies.', 12, '2002-05-10');
