INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 11, 'Foul Balled', 'When Timmy asks his fairies to use their magic to make Chester the “best baseball player” ever, things go from bad, to great, to worse.', 12, '2002-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 12, 'The Boy Who Would Be Queen', 'Timmy tells Trixie Tang that he has a great gift for her, so he can be invited to her party. Obviously, he''s lying. Later that day, Timmy and Cosmo start making of girls, and Wanda becomes so angry she turns Timmy into a girl. Timmy decides being a girl can help him/her figure out what Trixie would like for her birthday, so he/she goes off to the mall...but not without revenge on his godparents for turning him into a girl...he wishes Cosmo was a woman and Wanda was a man.', 12, '2002-06-07');
