INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 2), 15, 'Mighty Mom and Dyno Dad', 'Timmy, sick of his parents rushing to work and coming home late, tired, and never having any time for him, wishes that they had superpowers.', 12, '2002-09-06');
