INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 3), 4, 'Love Struck!', 'Timmy learns from Cupid that Tootie is destined to be his special someone, but he doesn''t want to waste his first kiss on Vicky''s little sister instead of Trixie, so he creates an elaborate Valentine for Trixie consisting of dancers and a song. After Trixie rejects him yet again, Timmy decides to wish all girls to another part of the world before Tootie can get to him.', 24, '2003-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 3), 5, 'Most Wanted Wish', 'After every wimpy kid in the school was picked over him by Tad and Chad, and Trixie chose a rock over him as her lab partner, Timmy wishes that he was the most wanted kid on Earth.', 12, '2003-05-02');
