INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 3), 7, 'Engine Blocked', 'Mr. Turner is going through mid-life crisis and impulsively buys a sports car from Vicky. Timmy wishes that he was car so he could spend time with his dad.', 12, '2003-05-09');
