INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 3), 9, 'Sleepover And Over', 'Timmy''s friends, A.J. and Chester argue and break their friendship. When they each invite him to their respective sleepovers on the same night, to watch a Crash Nebula/Crimson Chin crossover special, this creates a problem for Timmy. How will he join both of them without being discovered? How will he reunite his friends?', 12, '2003-05-17');
