INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 5, 'Just Desserts', 'Timmy''s wish for a world of desserts could mean an early end for everyone.', 12, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 6, 'You Doo!', 'Timmy wishes for a You-Doo doll of Francis for revenge. Later on, Timmy gets You-Doo dolls of mostly every main character on the show. Tootie gets the You-Doo of Timmy, and the trouble starts!', 12, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 7, 'Catman Meets The Crimson Chin', 'When Catman becomes depressed because no one in Dimmsdale appreciates his brand of cat-themed justice, Timmy wishes him into the world of the Crimson Chin.', 12, '2005-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 8, 'Back To Norm', 'Mr. Crocker receives the magic lava lamp as a present and tries to capture Timmy''s fairies in a Roadrunner-like manner', 12, '2005-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 9, 'The Masked Magician', 'Timmy wishes for Magician powers to attract everyone to his parents yard, but this has unintended consequences.', 12, '2005-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 10, 'The Big Bash', 'Timmy and Remy get in a hunt, and the winner gets a few rule-free wishes. If Remy wins, Timmy will lose his godparents, and Wandisimo gets Wanda.', 12, '2005-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 11, 'Blondas Have More Fun', 'Wanda pays a visit to her successful twin sister Blonda. The sisters spiral into bickering with each one convinced the other has a much easier life.', 12, '2005-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 12, 'Five Days Of Flarg', 'Mark the alien is missing Flarg on his planet so he has it on Earth.', 12, '2005-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 13, 'Go Young, West Man', 'TV''s Adam West, star of the superhero series "Catman," never had a real childhood. Timmy wishes that Adam could become a kid again.', 12, '2005-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 14, 'Birthday Wish', 'Timmy loans his godparents to Tootie on her birthday to make up for a lousy one.', 12, '2005-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 15, 'Timmy''s 2-D House of Horror', 'Timmy turns a boring 3-D movie volcano into a real volcano but it destroys Vicky''s house and her and her family have to live with Timmy, now he must drive them out.', 12, '2005-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 16, 'It''s A Wishful Life', 'Unappreciated by his parents, his friends and Fairy Godparents, Timmy wishes that he was never born, but he soons learns maybe everyone''s life is better out without him.', 12, '2005-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 17, 'Escape From Unwish Island', 'Everyone Timmy cares about has vanished. He soon finds all his old rejected wishes have come back for revenge.', 12, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 18, 'The Grand Plan', 'Cosmo''s Fagiggligland (what fairies use to transform into diffrent things) isn''t working and might loose his job being Timmy''s godparent. The gang must get Anti-Cosmo out of Anti-fairy jail in order to do a transplant performed by Dr. Rip Studwell. But Jorgen Vonstrangle won''t let them through or let Anti-Cosmo out!', 12, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 19, 'Hassle in the Castle', 'Timmy snoops inside his fairies fishbowl castle, but causes trouble after accidentally wishing back past godkids in the Hall of Infamy.', 12, '2005-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 20, 'Remy Rides Again', 'Remy returns and has a diabolical plan to get Timmy to become his friend and spend more time with him, just so he could get rid of his godparents.', 12, '2005-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 21, 'Talkin'' Trash', 'Wanda''s father and Timmy must clean up magical garbage in Timmy''s house.', 12, '2005-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 22, 'Timmy TV', 'Timmy has become the unknowing subject of Fairy World''s most popular Reality TV series, "Timmy TV."', 12, '2005-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 23, 'Mooooving Day', 'Timmy wishes that his Mom could sell a house to anyone. With her new found success they manage to move into a new neighborhood.', 12, '2005-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 24, 'Big Wanda', 'Someone’s kidnapped Big Daddy! With the big mob boss missing, Wanda is called in to run the family business. Her first task: a mafia makeover complete with pink trash removal uniforms, pink garbage trucks, and doilies on all the fairy world trash cans.', 12, '2005-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 25, 'Oh, Brother', 'Life would be better with an older brother. At least that''s what Timmy believes.', 12, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 26, 'What''s the Difference?', 'Timmy''s reading a find-it book when Mark Chang, in his traditional alien form, shows up. His changer is broken, and without it, Mandie will find him. In a last ditch effort to save Mark, Timmy wishes the school was like his book. But she is about to turn the school into a crater if Mark doesn’t show himself. If Cosmo and Wanda had their wands, Timmy could just wish her away. But where are the wands hiding?', 12, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 27, 'Smart Attack', 'Dad keeps trying to help Timmy with his homework. But he’s not the brightest dad, so any help he gives does more harm than good. How can Timmy get his dad to stop helping without hurting his feelings? He doesn’t. He completely avoids the subject by wishing that his dad was smart. Now that Dad has the brains of a genius, he home-school’s Timmy and pays a lot more attention to things like Timmy’s goldfish. In all the years that Timmy has had his pet fish, not once has he fed them. Dad concludes that they must be a new breed and sets out to dissect the fish in front of the entire scientific community.', 12, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 28, 'Operation FUN', 'Remy Buxaplenty has come home from military school for spring break. All he can talk about is how great his new school is, making Timmy, Chester, and AJ very jealous in the process. Timmy decides they should all get to go to Remy’s fancy academy and wishes for three scholarships. Once the boys get to their new school, they find that it is not quite the paradise Remy described -- it’s the exact opposite. The students have to get up before dawn every morning, all the teachers are drill sergeants, and pets are strictly forbidden which means that Timmy’s pet goldfish (a.k.a. Cosmo and Wanda) are confiscated and placed in storage. This of course was Remy’s plan all along, and now that Timmy can’t get to his God Parents, he cannot wish himself out of this nightmare.', 12, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 29, 'Something''s Fishy', 'Timmy is at the beach and he’s bored silly. He, Cosmo, and Wanda set off to explore the deep, and everywhere they go, but Cosmo seems to be hated by every single fish. Soon, they end up in the lost city of Atlantis. Timmy appeals to Atlantis’ leader, King Greg -- if he can show good cause why Atlanteans should be happy beneath the sea, Cosmo will be set free. Will Timmy save Cosmo?', 12, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 30, 'Presto Change-O', 'Timmy hasn’t studied for a test in Mr. Crocker’s class, so he wishes for a magical device that allows him to change places with anyone who comes in contact with it. Cosmo and Wanda are in a hurry, so they give Timmy his wish. At school, he uses this device to change places with AJ, but after that, his plan backfires. Will Timmy be able to stop Crocker from finding out about Timmy''s fairies? Find out.', 12, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 31, 'The Good Ol'' Days', 'Timmy''s got a break from Vicky; unfortunately, he''s being babysat by Dad''s Dad, Pappy. However Pappy doesn''t like any of Timmy''s modern entertainment.', 12, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 32, 'Future Lost', 'Timmy wishes for his society to be more futuristic, like a fictional character from one of Dad''s old books. However, this society is filled with robots, who are seemingly harmless, but in reality, are evil. Will Timmy escape from this dreaded society?', 12, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 33, 'Timmy The Barbarian', 'Binky''s sick, so Jorgen shows up with some soup and a bedtime story to make him feel better. The story is "Timmy the Barbarian," and as Jorgen tells it to Binky, poor Timmy, Cosmo and Wanda find themselves actually living it!', 12, '2006-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 5), 34, 'No Substitute for Crazy', 'Crocker has fallen into a well and so Timmy''s class has been assigned a substitute teacher called Mrs. Sunshine and she seems very-very nice until Timmy wishes for her to be his permanent teacher, she turns out to be even worse than Mr. Crocker when she is really an expert fairy hunter named Mrs. Doombringer.', 12, '2006-11-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 1, 'Mission Responsible', 'Timmy offers to baby-sit Poof for Cosmo and Wanda so they can have the night out.', 12, '2008-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 2, 'Hairicane', 'Sick and tired of his father''s bad haircuts, Timmy wishes for indestructible hair with a personality that can''t be cut. It then comes to life as it grows and almost destroys Dimmsdale. Meanwhile, Wanda takes Poof to the baby fairy barber shop for his first haircut.', 12, '2008-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 3, 'Open Wide And Say Aaagh!', 'Timmy''s got to have his tonsils out and Vicky is determined to make his stay in the hospital as painful as possible!', 12, '2008-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 4, 'Odd Pirates', 'The Pirates opening game is today, and everyone except Timmy is going. Timmy wishes he was at the game, but when Wanda lets Poof make the wish, they end up on a real Pirate ship. The wands get stolen, they get trapped in a net, and almost get attacked by crocodiles. When Timmy opens his big mouth, the pirate ship becomes land-born. The pirates attack the Pirates games, and the Pirates baseball team helps defeat them.', 12, '2008-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 5, 'The Odd Squad', 'Timmy wishes Cosmo was a talking car so that he and his fairies can search for the missing Mama Cosma.', 12, '2008-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 6, 'For Emergencies Only', 'Feeling that Cosmo and Wanda are neglecting him for Poof, Timmy gets his godparents to give him his own magic wand with ten wishes on it.', 12, '2008-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 7, 'Cheese & Crockers', 'On Happy Half Day where "half-ness" is celebrated, Timmy wishes for a machine that lets him become half-Timmy/ half-whatever, but it also turns Mr. Crocker into a cheese powered megalomaniac.', 12, '2008-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 8, 'The Land Before Timmy', 'Sick of technology ruining his life, Timmy wishes to live in a simpler time. He and all of Dimmsdale are then sent to the Stone Age.', 12, '2008-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 9, 'King Chang', 'Mark Chang is called back to the planet Yugopotamia to become King when Princess Mandie sizes the throne from his father, and Timmy has to get help from Vicky to save Mark and his people.', 12, '2008-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 10, 'The End of the Universe-ity', 'Dark Laser''s back and after trying (and failing) to destroy Timmy, he adopts the saying, "if you can''t beat ''em, get ''em to join you." He offers Timmy a scholarship to "Dark-Mouth University" in an effort to get him to become his evil apprentice. Timmy refuses but Mom and Dad – excited that someone else is going to pay for Timmy''s college – eagerly accept the offer. Timmy is given a dark suit with dark powers and the proviso that if Timmy tries it and doesn''t want it, Dark Laser will leave Earth alone forever. Timmy agrees, and soon it seems he''s fallen under the evil spell of the evil suit.', 12, '2008-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 11, 'Sooper Poof', 'Poof is trying to get the hang of shape shifting but unfortunately he takes after Cosmo! And worse, one of his attempts has him crash landing in front of the Turner house, where Mom and Dad find him and become convinced he''s an alien super baby they need to raise to fight for truth and justice! But Timmy can''t just steal Poof back because Mom and Dad have fallen in love with the little guy, so he must devise another way of getting Poof back to Cosmo and Wanda before Dad''s attempts to turn the baby into a super hero get them all in trouble!', 12, '2008-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 12, 'Wishing Well', 'Timmy''s been running Cosmo and Wanda ragged so Jorgen takes him to "Wishing Well", a state of the art rehabilitation facility where he can learn to wish less and be more independent. He meets two other kids with fairies and together they battle their darkest fears, escape from precarious situations…and make breakfast, all without wishing. In the end, they learn independence only when they band together to escape, which they do without any fairy assistance whatsoever. But escaping wasn''t part of Jorgen''s plan…or was it? Either way, it worked!', 12, '2008-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 13, 'Wishy Washy', 'Timmy''s wish for a magical car wash that rejuvenates anything that goes through it so his father can restore his beloved Striker Z sports car, but fossils of dinosuars and cavemen also go through it causing them to come back to life and run amok in Dimmsdale, as do Cosmo and Wanda, turning them into rebellious teenagers.', 12, '2008-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 14, 'Poof''s Playdate', 'Timmy wishes for some fairy babies to play with lonely Poof, turning Cosmo, Wanda, Jorgen, the Tooth Fairy, Juandisimo, and Cupid into fairy babies.', 12, '2008-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 15, 'Vicky Gets Fired', 'Despite all the ways Vicky has tortured Timmy, it''s only when she accidentally erases a videotape that Mom and Dad actually fire her. Determined to get a job, Vicky decides she wants to be mayor and takes over the city. As she''s ready to make Vickyville a whole new country, Timmy, who''s happy for the first time, realizes he''s got to get Vicky out of office and back as his babysitter in order to maintain peace.', 12, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 16, 'Chinred Spirits', 'Timmy''s disappointed to see how boring the Crimson Chin comics have become lately. When he spends a day with the Chin, he sees why - the Chin is lonely. Timmy wishes up a super girlfriend for him, except now the comic is both boring and romantic, yuck! Desperate, Timmy unknowingly makes a wish that changes everything, so he must undo his wish - and fast.', 12, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 17, '9 Lives', 'Binky is ill so Jorgen comes to cheer him up by telling him a magical story about Timmy Cosmo and Wanda, but this is bad news for the trio as what ever Jorgen says will happen in the story. This will be tricky for the two heroes and pack mule.', 12, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 6), 18, 'Dread & Breakfast', 'Dad''s quit his job to make sock monkeys, and there''s no income for the Turners...until Mom turns the house into a bed and breakfast. That''d be fine, if the first guests weren''t Mr. Crocker, Dark Laser and Tootie who either want to destroy Timmy or kiss him. As Timmy runs around frantically trying to stay one step ahead of his house guests, he must find a way to get everyone out without using the very fairy magic Crocker is hoping to catch him using.', 12, '2008-11-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 1, 'Bad Heir Day', 'Crocker gets a hold of Poof and decides to groom him to be the heir to his "fame and fortune."', 12, '2009-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 2, 'Freaks and Greeks', 'When Timmy''s parents go to a toga party, his fairies take him to one on Mount Olympus where he accidentily destroys it with a thunderbolt, so the gods move the party to his house.', 12, '2009-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 3, 'Mice-Capades', 'When Poof watches too much of the violent classic "cat and mouse" cartoon, "Cheesy and Sleazy", he turns Timmy and Vicky into the characters from the show.', 21, '2009-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 4, 'Formula For Disaster', 'Poof''s refusal to take his medicine and Crocker''s visit to the Turner residence to complain about Timmy''s bad grades leads to chaos in the Turner household.', 12, '2009-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 5, 'Birthday Bashed', 'Timmy looks forward to his birthday until Jorgen reminds him that each birthday draws him a year closer to losing his fairies; however, Timmy isn''t worried because his folks always forget his birthday, but he then panics when they seem to remember it this time.', 12, '2009-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 6, 'Momnipresent', 'Timmy''s preperations for the party of the year are interrupted by his mother who wants to spend some quality time with him. He then sneaks away every chance he gets to get the party ready.', 12, '2009-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 7, 'Anti-Poof', 'When Poof''s anti-fairy counterpart, Foop, is born, it is up to Poof to save his loved ones and Fairy World from him.', 24, '2009-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 8, 'Squirrely Puffs', 'It''s a race between the Squirrely Scouts and the Cream Puffs to the top of Mount Doom. Will Timmy''s team survive this harrowing challenge, or will Mom and the "girls" make them turn tail?', 12, '2009-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 9, 'Add-a-Dad', 'Timmy''s dad is very busy working, so busy in fact, that when Timmy & him are doing something fun, he suddenly has to leave & Timmy''s left alone. So he finds a solution, to wish up many dads, so that every time one of them has to leave, he has another one, but then there''s too many dads! And they all want Timmy! Then when he realizes he doesn''t want or need many dads, he has to find a way to get rid of them.......by sending them to another planet and gives them Timmy plushies so they can be happy!', 12, '2009-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 10, 'Fly Boy', 'Everybody in Dimmsdale is watching the latest horror film, "Fly Boy". But Timmy isn''t allowed to, so when he wishes to become a "fly on the wall" in order to see it, the real horror begins.', 12, '2009-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 11, 'Temporary Fairy', 'Jorgen serves as over-adventurious Timmy''s temproary godparent when Cosmo and Wanda become too busy with Poof.', 12, '2009-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 12, 'Crocker Shocker', 'Fairy World''s magic is shut down when Mr. Crocker is hypnotized into no longer believing in fairies.', 12, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 13, 'Super Zero', 'When Cosmo gets ousted from the house for being too annoying, he then becomes Dimmdale''s newest superhero.', 12, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 14, 'Dadracadabra', 'Mr. Crocker suspects that Timmy''s Dad is a fairy when Timmy and his fairies help him with his magic', 12, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 15, 'Timmy Turnip', 'Timmy meets his grandparents and quickly wishes they never came to America. He finds himself back in Ustinkistan, his grandparents'' native country, and he must somehow get on the next boat home.', 12, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 16, 'One Man Banned', 'After Timmy is rejected from the school band, he wishes everyone would love his music. But when Timmy gets his first taste of acclaim, Wanda has to stop him before he becomes completely fame-crazy.', 12, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 17, 'Frenemy Mine', 'Vicky becomes Timmy''s friend after he saves her life.', 12, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 18, 'Double Oh Schnozmo', 'Cosmo''s brother, Schnozmo, comes to visit, claiming to be a secret agent But when he turns out to be nothing but a con man, Wanda makes him take part in a real spy adventure to spare Cosmo''s feelings.', 12, '2010-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 19, 'Planet Poof', 'Feeling ignored by his family,Poof runs away to Yugopotamia where the unappreciated Queen uses his cuteness to scare the residents into giving her whatever she wants.', 12, '2010-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 20, 'The Boss Of Me', 'When Timmy goes to visit his father''s office, he wishes up a pencil that will last forever. This impresses Dad''s boss so much that he hires Timmy and orders him to fire Dad.', 12, '2010-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 21, 'He Poofs, He Scores', 'Timmy tries out for the soccer team his father coaches, the Victims. He accidently swallows Poof, however, who goes right to his brain and makes him the greatest soccer player ever.', 12, '2010-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 22, 'Play Date of Doom', 'Foop escapes from prison seeking revenge on Poof.', 12, '2010-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 23, 'Teacher''s Pet', 'When Timmy wishes that he was the teacher''s pet, Poof turns him into Mr. Crocker''s guinea pig.', 12, '2010-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 24, 'Chicken Poofs', 'Poof has the contageous Chicken Poofs disease that turns him into a chicken, and everyone he sneazes on turns into chickens as well. He then flees from the hospital, and Timmy and Cosmo try to catch him before he infects all of Dimmsdale while Wanda and Dr. Rip Studwell search for a cure.', 12, '2010-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 25, 'Stupid Cupid', 'Timmy seeks help from Cupid to win the love of Trixie Tang, but Cupid is on vacation. So Timmy has Cosmo fill in for the love god, but Cosmo only causes himself, Wanda, Mr. and Mrs. Turner, and Mr. Crocker to fall head over heals in love with all sorts of things.', 12, '2010-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 26, 'Manic Mom Day', 'When Timmy envies his mother''s life, Wanda makes makes them swap bodies for a day on a bet that if Timmy finds a mother''s life easier, Wanda will have to spend a week as a chicken; otherwise, Timmy will have to go a week without magic.', 12, '2010-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 7), 27, 'Crocker of Gold', 'Crocker captures Cosmo, mistaking him for a leperchaun, and Cosmo then steals a pot of gold from a clan of real leperchauns to buy his freedom. The clan then holds Wanda and Poof hostage until Cosmo and Timmy replace it.', 12, '2010-09-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 1, 'Love Triangle', 'Poof is upset his parents want him to take the lead role in the school play, but he quickly changes his mind after his new crush, Goldie Goldenglow gets the female lead role, but to get the role, he has to beat his archnemesis Foop, who also fell for Goldie.', 24, '2011-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 2, 'Spellementery School', 'With Poof''s first day in Spellementary School, he and Foop compete to be the most popular student there, but Foop takes it to extremes when his classmates don''t accept him, and its up to Poof to stop his anti-fairy counterpart from tearing apart the school!', 12, '2011-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 3, 'Operation Dinkelberg', 'Timmy''s Dad becomes obsessed with proving his neighbor, Mr. Dinkleberg is evil. He enlists Timmy to help him spy on Dinkleberg by dressing up like a girl scout!', 12, '2011-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 4, 'Invasion of the Dads', 'Timmy''s previous wish for a Planet of the Dads backfires when the Dads realize the one thing missing from their lives is Mom, and they come to steal her away from Dad and Timmy! It''s up to Timmy, Cosmo (in a magnify glass disguise), Wanda (in ice cube disguise, who was forced to remain in a freezer to prevent from melting), Poof (in a bee disguise), Mark Chang and a rather bumbling "Real Dad" to thwart the Dads and rescue Mom!', 24, '2011-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 5, 'Take and Fake', 'Timmy borrows Mark Chang''s fake-a-fier in order to attend Trixie''s costume party.', 12, '2011-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 6, 'Cosmo Rules', 'When Jorgen von Strangle gets the trick-ups (bouts of fairy hiccups that cause bouts of cheesy magician-like parlor magic) he isn''t able to enforce Da Rules, so he must pass it on to his closest available relative until he gets better. Unfortunately, his closest available relative is his long-lost cousin Cosmo as his Nana Boom Boom was playing Explosive Bingo and his cousin Leonard Von Strangle was on a trip in the Bahamas.', 12, '2011-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 7, 'Farm Pit', 'Mr. Turner has been fired from his job, so he tries to start up a farm instead. Unfortunately, he has no luck at growing anything, so Timmy wishes his father''s crops would grow huge. But now Timmy''s father has so much success that he wants his family to stay on the farm forever!', 12, '2011-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0235918')) AND numero_temporada = 8), 8, 'Crock Talk', 'After mysterious monster appearences of monsters on Dimmsdale, Crocker starts a webshow to comment it, and asks for viewers to call if they see a monster. Unfortunately, Timmy wishes for them, Dad calls Crocker everynight and he gets a freepass to film the fairies.', 12, '2011-07-11');
