INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 1, 'Broken Bow', 'The Enterprise, under Captain Jonathan Archer, sets off on its maiden voyage with a mission to return a wounded Klingon to his people.', 86, '2001-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 3, 'Fight or Flight', 'Captain Archer wants to convert curiosity into deeds and decides to enter a ship floating in space. Hoshi has trouble adjusting to life on Enterprise.', 44, '2001-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 4, 'Strange New World', 'Archer sends an away team to a habitable, luscious planet for observation. But when a storm occurs, the team begins to experience paranoid delusions.', 44, '2001-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 5, 'Unexpected', 'When Trip is dispatched to assist a Xyrillian ship with its power source problems, he is delighted to have a friendly encounter with one of the ship''s female engineers. However, shortly after returning to Enterprise, he discovers that their seemingly innocuous interaction has led to a surprising result.', 44, '2001-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 6, 'Terra Nova', 'The Enterprise crew alters course to investigate the mystery of Terra Nova, a legendary Earth colony whose inhabitants mysteriously disappeared decades ago. But when they arrive, they confront descendents of the colonists who have become more alien than Archer could ever have imagined.', 44, '2001-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 7, 'The Andorian Incident', 'Enterprise visits an ancient Vulcan spiritual sanctuary, despite T''Pol''s concerns that her human colleagues will be an awkward and disruptive presence there. Upon landing, they discover that the monastery has been forcibly taken over by the Andorians, a paranoid and highly excitable race of aliens with a long history of conflict with the Vulcans.', 44, '2001-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 8, 'Breaking the Ice', 'A Vulcan starship interferes with Archer''s probe of an oversized comet.', 44, '2001-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 9, 'Civilization', 'Captain Archer and the crew discover a fully inhabited, civilized though less advanced Earth-like planet. Disguised to look like its inhabitants, they pay the planet an exploratory visit where they learn that a pernicious illness is afflicting the local population. As Archer seeks to help them find the malady''s source, he finds himself in a close encounter with a comely female alien.', 44, '2001-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 10, 'Fortunate Son', 'The Enterprise crew is dispatched by Starfleet Command to assist Fortunate, a human freight vessel that has been attacked by Nausicaan pirates. On arriving, they are surprised to find that Fortunate''s crew is resistant to Archer''s efforts to help them and determined to seek revenge against their attackers, no matter the repercussions.', 44, '2001-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 11, 'Cold Front', 'When the Enterprise comes in contact with an alien vessel transporting stargazers to observe a spectacular stellar event, Archer invites them aboard the ship not realizing that Silik, a Suliban enemy, is among them. Archer quickly realizes that Silik is engaged in a nefarious time-travelling mission and must stop him before he can tamper with the course of history.', 44, '2001-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 12, 'Silent Enemy', 'When Enterprise is attacked by an unidentified enemy ship, the crew must work frantically to get their new phase canons to operate. Meanwhile, the captain charges Hoshi with finding out Malcolm''s favorite food in time for a surprise birthday dinner.', 44, '2002-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 13, 'Dear Doctor', 'The crew discovers a new planet with two races, one in desperate need of medical and scientific assistance. In the course of trying to help, Dr. Phlox recalls his own Denobulan past to address the ethical dilemmas that arise in the present.', 44, '2002-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 14, 'Sleeping Dogs', 'While investigating a gas giant, Enterprise comes across a damaged vessel hovering in the atmosphere, and T''Pol, Hoshi and Malcolm board the vessel to investigate. However, once aboard, they are ambushed by a hostile female Klingon who hijacks their shuttlepod and strands them on the Klingon ship, which threatens to implode under the pressure of the planet''s atmosphere.', 44, '2002-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 15, 'Shadows of P''Jem', 'Archer and the crew are disappointed to discover that T''Pol has been ordered by the Vulcan High Command to leave Enterprise--and equally frustrated at her seeming indifference to leaving their ranks. T''Pol''s last mission as a Starfleet officer, however, proves eventful when she and Archer are kidnapped by a militant faction on an alien planet.', 44, '2002-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 16, 'Shuttlepod One', 'Tucker and Reed set out on a mission in a shuttlepod, as Enterprise is busy investigating an asteroid field. Disaster strikes while the pair are away, leaving the shuttlepod damaged and the warp drive inoperable. They manage to make it back to the rendezvous coordinates only to discover Enterprise was apparently destroyed when it crashed into an asteroid. With the ship seemingly no more, the pair are left abandoned in the middle of nowhere with only a few days of air remaining.', 45, '2002-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 17, 'Fusion', 'Enterprise encounters a group of Vulcan civilians who have split off from the normal way of Vulcan life in an effort to explore their emotions. T''Pol is disturbed by the new visitors and warns the Captain that all attempts in the past to integrate Vulcan emotions into their lives has proven disastrous. Meanwhile, a message from Admiral Forrest leaves the Captain with the difficult task of trying to convince one of the visiting Vulcans to call home to speak with his dying father.', 44, '2002-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 18, 'Rogue Planet', 'While exploring an uncharted planet, Enterprise crew members encounter a group of aliens who are hunting down indigenous creatures for recreation. During their exploration, Archer is mesmerized by visions of an elusive, yet familiar woman who needs his help.', 44, '2002-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 19, 'Acquisition', 'Enterprise encounters Ferengi pirates who use a booby-trapped artifact to gas the crew into unconsciousness, then pillage the ship for treasures. But they haven''t counted on Tucker, who happens to be in the decon chamber and avoids the gas, and attempts to win back the ship from the pirates.', 44, '2002-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 20, 'Oasis', 'While exploring a crashed vessel on a desolate planet, the Enterprise crew is haunted by some ghostly figures, and they encounter an alien race that has survived despite insurmountable odds. Trip helps repair their derelict vessel and is befriended by Liana, an attractive humanoid alien who develops feelings for him.', 44, '2002-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 21, 'Detained', 'While exploring a planet, Archer and Mayweather enter a “military zone” and are detained in an internment prison by an alien race called Tandarans, who are at war with the Suliban. While the Enterprise crew''s previous encounters with the Suliban have been disastrous, Archer and Mayweather find themselves sharing a cell with some Suliban detainees who they believe may be wrongly imprisoned.', 44, '2002-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 22, 'Vox Sola', 'A strange, alien creature comes aboard Enterprise, and captures several crew members in its cocoon-like web. With her crewmates'' lives in jeopardy, Hoshi faces her biggest challenge yet, in trying to communicate with the lifeform, in order to return it to its home planet.', 44, '2002-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 23, 'Fallen Hero', 'Enterprise is sent to the planet Mazar to pick up a Vulcan ambassador who has been expelled for misconduct.', 44, '2002-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 24, 'Desert Crossing', 'When Archer and Trip are invited to a desert-like planet by an alien leader, they discover he is a terrorist who has lured them there under false pretences. Meanwhile, T''Pol, while in command, faces a tough decision when she cannot locate Archer and Trip in the desert.', 44, '2002-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 25, 'Two Days and Two Nights', 'Archer, Hoshi, Travis, Malcolm and Trip have decidedly different experiences during shore leave on Risa. Meanwhile, on Enterprise, Phlox enters his annual hibernation cycle.', 44, '2002-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 1), 26, 'Shockwave (1)', 'Starfleet orders Enterprise to return home when the crew seemingly causes the destruction of an alien planet. However, a visit from Crewman Daniels leads Archer to believe that this disaster was the plot of one of the factions from the temporal cold war.', 44, '2002-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')), 2, 'Season 2', 'In one short year, Jonathan Archer, captain of the starship Enterprise NX-01, has made a name for himself and his crew, both with his Starfleet superiors and perhaps less favorably with mankind''s alien neighbors.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 1, 'Shockwave (2)', 'Daniels and Archer must find a way back to the 22nd century in order to make sure history plays out as it should. Meanwhile, on board Enterprise, the Suliban have taken over the ship, but Reed, Trip, and T''Pol formulate a plan to eject the aliens.', 43, '2002-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 2, 'Carbon Creek', 'After Archer and Trip become curious about a visit she made to a Pennsylvania mining town called Carbon Creek, T''Pol explains to them that Vulcans actually had their first contact with humans in 1957. That year, a Vulcan ship crashed on Earth and three crew members survived, including T''Pol''s great grandmother. They pose as humans in Carbon Creek and take on jobs while waiting for rescue and soon find themselves becoming more involved with the town''s residents.', 43, '2002-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 3, 'Minefield', 'When attempting to explore a new planet, Enterprise triggers a cloaked mine. While the crew deal with the resulting damage, it''s discovered another mine is stuck to the hull. During Reed''s attempt to disarm it, a spike is driven into his leg, trapping him out there. While Archer goes out on the hull to help him, the rest of the crew learn they are in a minefield belonging to the Romulan Star Empire, who demand Enterprise leave or face destruction.', 43, '2002-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 4, 'Dead Stop', 'Suffering from damage inflicted in the Romulan minefield and unable to complete repairs on their own, Archer orders a distress call to be put out. A response leads Enterprise to a repair station, which surprisingly has no crew aboard it and is run by computer. Repairs on Enterprise are carried out quite efficiently and quickly, though the price for all this is much higher than the crew could''ve guessed.', 43, '2002-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 5, 'A Night in Sickbay', 'Archer spends a night in sickbay with Dr. Phlox after Porthos contracts a deadly virus on the Kreetassan homeworld. Crew members suspect Archer''s increased stress level is due to Porthos'' illness, but Dr. Phlox suspects it has to do with Archer''s repressed sexual tension.', 43, '2002-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 6, 'Marauders', 'In need of fuel, the Enterprise arrives at a Quonset mining colony for deuterium supplies. They discover that Klingons are forcing the colonists to give up all their deuterium. Archer and the rest of the crew work to train the colonists so they can fight back against the Klingons.', 43, '2002-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 7, 'The Seventh', 'Archer, Mayweather and T''Pol travel to an arctic world to apprehend a fugitive, when T''Pol is contacted by Vulcan High Command. The mission takes a dangerous turn when T''Pol begins having flashbacks that suggest the events she remembers about a former mission may not accurately relate to what happened.', 43, '2002-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 8, 'The Communicator', 'Archer and Reed return to a pre-warp society, that is on the verge of war, to recover a lost communicator from an undercover survey mission.', 43, '2002-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 9, 'Singularity', 'While Enterprise is surveying a black hole in a trinary star system, the stellar phenomenon causes strange effects on the crew.', 43, '2002-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 10, 'Vanishing Point', 'Hoshi experiences her first transporter experience and strange aftereffects lead her to believe she wasn''t reassembled correctly.', 43, '2002-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 11, 'Precious Cargo', 'Trip boards an alien cargo vessel to help repair a stasis pod, which holds a beautiful woman in suspended animation. When the woman accidentally wakes up, she reveals she''s not a passenger, but a prisoner.', 43, '2002-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 12, 'The Catwalk', 'When a lethal neutronic storm approaches faster than Enterprise can escape, the crew take shelter in the maintenance shafts inside the warp nacelles. They also provide refuge to a group of aliens, who aren''t exactly honest about themselves.', 43, '2002-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 13, 'Dawn', 'During a solo test mission on Shuttlepod One, Trip is attacked by a territorial alien and forced to land on the night side of a moon. As he tries contacting Enterprise, he discovers his alien foe has made an emergency landing nearby. The two contend with each other as an extremely hot sun rises and threatens both their lives.', 43, '2003-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 14, 'Stigma', 'Enterprise visits a planet where an Interspecies Medical Exchange conference is being held. Dr. Phlox tries to obtain research on a terminal disease from the Vulcan contingency, without revealing T''Pol has been infected by it.', 43, '2003-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 15, 'Cease Fire', 'Both the Vulcans and the Andorians make a claim to a small planet and military conflict soon erupts. As the fighting goes on, the Vulcans announce they are willing to discuss cease fire terms. However, Imperial Guard officer Shran believes only Captain Archer can be trusted to mediate the situation, which drags the Enterprise crew into the tense situation.', 43, '2003-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 16, 'Future Tense', 'The Enterprise crew find a small craft drifting in space and are surprised to find it contains a human corpse. More questions arise when the Suliban and Tholians make claims to the craft.', 43, '2003-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 17, 'Canamar', 'Archer and Tucker are arrested and placed on a prisoner transport heading for a penal colony, Canamar. They won''t have a chance to correct this error, as one of the inmates plots a takeover of the ship.', 43, '2003-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 18, 'The Crossing', 'Noncorporeal aliens possess the bodies of the Enterprise crew.', 43, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 19, 'Judgment', 'In a Klingon tribunal, Archer stands accused of aiding fugitives of the Empire and faces death if found guilty.', 43, '2003-04-09');
