INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 22, 'Cogenitor', 'The Enterprise crew makes first contact with the Vissians, a species with three genders. Trip meets one of the species'' third gender, known as Cogenitor, and learns how badly Vissians treat all Cogenitors. Trip attempts to help the Cogenitor, even though it interferes with Vissian culture.', 43, '2003-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 23, 'Regeneration', 'The remnants of an alien ship and two frozen cybernetic bodies are uncovered in the arctic by a research team. These aliens soon thaw out and flee Earth, taking the research team with them. Starfleet orders Enterprise to find them, but the crew aren''t prepared for just how dangerous these aliens really are.', 43, '2003-05-07');
