INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 25, 'Bounty', 'Archer learns the Klingons have put a price on his head when he is captured by a Tellarite bounty hunter. As Enterprise pursues, a virus causes T''Pol to go into premature Pon Farr.', 43, '2003-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 2), 26, 'The Expanse', 'An alien race known as the Xindi launch an attack on Earth, causing great casualties and massive damage. As Enterprise heads back home, an unlikely source informs Archer about the Xindi and that their next attack will destroy Earth.', 43, '2003-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')), 3, 'Season 3', 'After a devastating attack on Earth kills seven million people, Captain Archer and the crew of the NX-01 venture into the Delphic Expanse to seek out those responsible.');
