INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 15, 'Affliction (1)', 'While Enterprise visits Earth for the launch of Columbia, Phlox is kidnapped and forced to help the Klingons deal with a grave threat toward their species.', 43, '2005-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 16, 'Divergence (2)', 'With Columbia''s help, the Enterprise crew grapples with sabotage to their ship as they pursue the truth behind the kidnapping of Phlox.', 43, '2005-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 17, 'Bound', 'As a gift for negotiating with the Orion Syndicate, Captain Archer receives three Orion Slave Girls.', 43, '2005-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 18, 'In a Mirror, Darkly (1)', 'In the mirror universe, Commander Archer mutinies against Captain Forrest in order to capture a future Earth ship found in Tholian space.', 43, '2005-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 19, 'In a Mirror, Darkly (2)', 'In the mirror universe, Archer commandeers the 23rd-century Defiant from the Tholians and uses it in a nefarious power grab.', 43, '2005-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 20, 'Demons (1)', 'A xenophobic faction of humanity threatens to undermine talks to form a new coalition of planets.', 43, '2005-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 21, 'Terra Prime (2)', 'A human isolationist leader threatens to destroy Starfleet Command unless all aliens leave Earth immediately.', 43, '2005-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0244365')) AND numero_temporada = 4), 22, 'These Are the Voyages...', 'Six years in the future, an emotional Captain Archer and the crew return to Earth to face the decommission of Enterprise and signing of the Federation charter.', 43, '2005-05-13');
