INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')), 1, 'Season 1', 'As prodigal elder son Nate Fisher returns home for the holidays to news of his father''s death, the family must learn to deal with the death of one of their own—while figuring out how to go ahead with the business of living.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 1, 'Pilot', 'Nate Fisher returns home for the holidays to the shattering news of his father''s death.', 63, '2001-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 2, 'The Will', 'After a pyramid scheme owner dies and leaves his wife and baby daughter with a load of debt, Nate offers to loan them a casket. Meanwhile, the Fisher family attend the reading of their father''s will.', 52, '2001-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 3, 'The Foot', 'When a bakery owner is killed, it''s up to Federico to put the pieces back together. The family considers selling the funeral business altogether to Kroehner.', 53, '2001-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 4, 'Familia', 'After a gang member is killed, the Fishers find that his family''s wishes for burial differ from those of his gang leader. Nate''s girlfriend Brenda makes an unfavorable impression during a family dinner.', 52, '2001-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 5, 'An Open Book', 'Ruth is stunned by the visitors at a porn star''s wake; Nate has a strange first meeting with Brenda''s brother Billy; and Keith takes issue with David''s desire to replace his father as deacon at the family church.', 55, '2001-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 6, 'The Room', 'An ornery widower camps out in the Fisher Funeral Home; sparks fly between Claire and Billy; Ruth spurns Hiram and is later wooed by a Russian florist; David is pursued by a pushy parishioner while performing charity work; and an examination of the business''s receipts uncovers some interesting secrets.', 58, '2001-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 7, 'Brotherhood', 'When a young Army vet dies of Gulf War Syndrome, his brother opts for a cremation and disposal of the body; Ruth has Hiram over to cook dinner and then takes a job with Nikolai; David''s church involvement results in his casting a very important vote; and Billy interferes with Nate and Brenda''s vacation plans.', 51, '2001-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 8, 'Crossroads', 'In an effort to raise income, Nate and David decide to rent out a room in the funeral home; Claire struggles to grasp the lessons of her outreach hike in the mountains; Ruth attempts to reconcile her feelings about Hiram; Brenda''s Aussie friend gets under Nate''s skin; and David is buoyed by the news of extra funeral business.', 57, '2001-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 9, 'Life''s Too Short', 'A tragedy reunites Claire with a guy who sullied her reputation at school; David and his new boyfriend run into Keith and his new partner on the disco circuit; and Ruth has an eye-opening camping trip with Hiram.', 56, '2001-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 10, 'The New Person', 'Nate and David hire an outspoken mortician; Billy''s photo gallery exhibit features one particularly surprising shot; and Claire frets over Gabe''s inconsistent behavior.', 59, '2001-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 11, 'The Trip', 'Nate, David and Brenda take an interesting trip to Vegas for a funeral directors'' conference; a baby''s death from SIDS stuns the family; and Ruth takes a floral-arrangement class.', 55, '2001-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 12, 'A Private Life', 'A gay man''s murder forces David to confont his own fears about his lifestyle; Brenda''s parents and Nate consider getting help for the increasingly troubled Billy...but Brenda isn''t so sure that''s the answer. Meanwhile, Ruth, Claire and David all share secrets with respective acquaintances.', 57, '2001-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 1), 13, 'Knock, Knock', 'The Fisher family experiences the control-freak side of Tracy Montrose Blaire; Brenda visits a remorseful Billy; David faces problems at his church; Gabe reverts to some bad habits; and Rico finds reason to celebrate.', 60, '2001-08-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')), 2, 'Season 2', 'With owner/patriarch Nathaniel Fisher no longer alive (except in the hearts and sometime visions of his family), his survivors — wife Ruth, sons Nate and David, and daughter Claire — continue to cope with the tricky business of looking to the future while being constantly reminded of the past.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 1, 'In the Game', 'A young actress''s death prompts her castmates from a slasher film to pitch in for a cheap funeral at Fisher & Sons. Meanwhile, Ruth arranges a dinner for Nate, David and Claire--and their significant others--after reading a book for parents of gay and lesbian children.', 58, '2002-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 2, 'Out, Out Brief Candle', 'A college football player''s death during practice bothers Nate, who earlier learned of his own potentially fatal condition. Meanwhile, Federico''s request to borrow money from Nate and David is rejected, and he later learns of their newest purchase: a ''casket wall'' display.', 57, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 3, 'The Plan', 'The death of a psychic''s husband sparks some interesting conversation around Fisher & Sons. Meanwhile, Ruth is changed after attending a lengthy self-actualization seminar; Claire is upset to discover that her guidance counselor has betrayed her confidence; and Brenda walks out on a college course she enrolled in.', 57, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 4, 'Driving Mr. Mossback', 'Nate brings Claire to his old stomping ground in Seattle to help him retrieve the body of a man who feared flying. There, they stay with Lisa, a woman who still carries a torch for Nate.', 58, '2002-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 5, 'The Invisible Woman', 'Ruth takes a personal interest in the death of a woman who has no friends or relatives. Meanwhile, Brenda''s search for a literary muse prompts her to turn to one of her massage clients--a prostitute named Melissa--and Nate''s relationship with Brenda takes an unexpected turn.', 56, '2002-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 6, 'In Place of Anger', 'Mitzi Huntley arrives back in Nate and David''s lives thanks to a comparison-shopping widow. Meanwhile, Ruth''s estranged sister Sarah arrives for an unexpected visit. Later, a vodka-fueled family dinner casts a pall over Nate and Brenda''s happy news.', 56, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 7, 'Back to the Garden', 'A Jewish funeral at Fisher & Sons leads Nate to seek spiritual guidance from an intense female rabbi. Claire is surprised to meet a guy while visiting her Aunt Sarah. Meanwhile, a medical emergency prompts David to consider giving his relationship with Keith another shot. Federico''s jealous suspicions about his cousin Ramon prove to be very misguided.', 57, '2002-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 8, 'It''s the Most Wonderful Time of the Year', 'The Christmas season marks the anniversary of Nathaniel''s death...and gets everyone thinking about their last moments with him. Meanwhile, Nate and Brenda are shocked by Margaret Chenowith''s Christmas Eve guest, Claire gets into a dangerous online relationship and Federico stirs up trouble in his own family.', 55, '2002-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 9, 'Someone Else''s Eyes', 'Ruth continues to help an injured Nikolai recover, but her patience is tested when she discovers just how he broke his legs. Brenda''s escapades help her to write, but her feelings about being engaged grow more muddled--especially after Billy''s release from the hospital.', 57, '2002-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 10, 'The Secret', 'David and Keith continue trying to iron out their problems...and Karla has a secret that isn''t going to make things any better. Meanwhile, Claire takes a curious approach to photography, Ruth prepares to move ahead with Nikolai and Brenda''s engagement anxiety leads her on a sexual adventure with Melissa.', 57, '2002-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 11, 'The Liar and the Whore', 'Nate and Brenda find comfort thanks to Rabbi Ari''s advice. Ruth''s need to control the lives of Nikolai and Claire leads her to a surprising self-assessment. Federico''s suspicions about an elderly woman''s ''natural'' death lead him to place Vanessa under scrutiny. A disgruntled former client files a lawsuit against Fisher & Sons.', 50, '2002-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 12, 'I''ll Take You', 'Claire seems to be finding some direction in her life, and a newly serious Billy is an unlikely choice to help her. Tensions between Nate and Brenda finally come to a head, while Keith has a problem that threatens everything he has worked towards in his relationship with David.', 56, '2002-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 2), 13, 'The Last Time', 'Fisher & Sons is the subject of an unannounced inspection, which proves surprisingly beneficial for Federico. Meanwhile, Claire''s art-school interview takes an unexpected turn, and things grow tense between Keith and David. Also, Nate finds himself at a crossroads, both with Brenda and with his AVM.', 60, '2002-06-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')), 3, 'Season 3', 'Thanks to the financial contributions of their mortician, Federico, Fisher &amp; Sons has become Fisher &amp; Diaz, and the Fisher family members face major adjustments as they open a new chapter in their professional lives and personal relationships.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 1, 'Perfect Circles', 'Fisher & Sons has become Fisher & Diaz, and Rico is doing all he can to make sure he''s not a ''gofer'' anymore. Meanwhile, David and Keith decide to give couple''s therapy a try, Claire skips art class to get to know a crematory worker named Phil; and Ruth goes overboard in her obsession with her granddaughter Maya.', 49, '2003-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 2, 'You Never Know', 'David and Rico are at odds over doing business with the family of a deceased telemarketer, Claire finds she has more in common with a fellow art student named Russell than with Phil, and Ruth meets a new friend, Bettina. Meanwhile, David and Keith get a taste of a different kind of family life and Carol continues to make life miserable for Lisa.', 51, '2003-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 3, 'The Eye Inside', 'Keith and David find the reality of a resort vacation different than advertised, Ruth learns the meaning of ''express checkout'' during a shopping excursion with Bettina, and Claire gets a lesson in ''sick'' art from a new teacher.', 52, '2003-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 4, 'Nobody Sleeps', 'While the partner of a recently deceased gay man is orchestrating an operatic tribute at Fisher & Diaz, Lisa plans an unwanted birthday party for Ruth. Meanwhile, Claire has a night to remember with Russell and two outlaw art teachers.', 52, '2003-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 5, 'The Trap', 'Fisher & Diaz deal with the recently discovered body of a man missing for years. Meanwhile, Ruth sets the ground rules for a new live-in apprentice named Arthur, David meets an old acquaintance during an L.A. Gay Men''s Chorus rehearsal, and Claire is surprised by her responsibilities as Olivier''s new assistant.', 55, '2003-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 6, 'Making Love Work', 'A nosebleed proves deadly for one audience member queuing up to see the ''Dr. Dave'' advice show. Meanwhile, Lisa takes Maya on an illuminating camping trip, and Rico wrestles with the challenges of a double-wide corpse and ''triple X'' casket.', 50, '2003-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 7, 'Timing & Space', 'A group of familiar relatives and friends is united in mourning. Meanwhile, David and Keith play ''Leading Ladies'' at brunch with members of the Gay Men''s Chorus, Ruth and Arthur perform a rendition of ''My Favorite Things,'' and Rico grows increasingly concerned about Vanessa''s ''intense energy.''', 48, '2003-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 8, 'Tears, Bones and Desire', 'After the patriarch of a cultish new-age clan dies, Fisher & Diaz is overrun by the wives and children left behind. Meanwhile, Keith gets back at David and his brunch pals during an intense game of paintball, Claire tires of being Olivier''s lackey assistant, and Ruth and Arthur savor the smell of clean laundry.', 56, '2003-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 9, 'The Opening', 'The Fishers run into some unexpected guests at an art-school benefit featuring works for sale by Claire, Russell and Olivier. Meanwhile, David and Keith have an awkward video-store meeting with Father Jack, then haggle over the ''rules'' of three-way sex with a stranger.', 54, '2003-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 10, 'Everyone Leaves', 'A bee sting during a family picnic ends a life. Nate tends to Maya while Lisa visits her sister in Santa Cruz. Meanwhile, Vanessa seems back to her old self, to Rico''s relief; Russell''s decision to share a secret with Claire backfires; Arthur wonders whether he should be mixing laundry with Ruth; and David gets a look at another dysfunctional family.', 51, '2003-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 11, 'Death Works Overtime', 'Fisher & Diaz is brimming over with activity after a trio of unrelated deaths. Meanwhile, Nate anxiously awaits Lisa''s return from Santa Cruz; Vanessa and her sister Angelica enjoy a therapeutic shopping excursion, to Rico''s chagrin; Claire grades herself in art school, then takes another important test; and Ruth cries all over a stranger''s jacket.', 49, '2003-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 12, 'Twilight', 'After a serial killer is executed in Texas, his daughter brings him home for a fitting Fisher & Diaz funeral. Meanwhile, Ruth spends some quality time in the company of George Sibley; David arrives at a crossroads in his relationship with Keith; Rico can''t find refuge from his domestic demons; and Nate and Claire get lost in their own separate twilights.', 53, '2003-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 3), 13, 'I''m Sorry, I''m Lost', 'Death continues to shuffle its deck randomly for would-be clients of Fisher & Diaz. Meanwhile, Nate looks to quell his inner demons through extreme remedies offered at a local bar--giving Claire way more baby-sitting action than she bargained for. Also, Ruth shakes up the family with some unexpected news.', 60, '2003-06-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')), 4, 'Season 4', 'There’s a new family order at the Fisher &amp; Diaz funeral home. Although one spouse is gone, another has moved in, ushering in changes for better and worse. For Nate, Ruth, David and Claire, every day above ground is a good one. With Ruth remarried and Nate spiraling out of control, the Fishers struggle with the latest losses and additions to the family, whose dismembered pieces never seem to add up to a healthy whole.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 1, 'Falling into Place', 'In an attempt to honor Lisa''s last wishes, Nate finds himself at odds with her family. Meanwhile, David and Keith look for ''genuinely new'' ways to start over; Federico seeks out a priest for absolution; Vanessa gets tired of Angelica; Brenda does ''the neighbor thing'' with Joe; and Ruth sings the praises of her new husband George.', 58, '2004-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 2, 'In Case of Rapture', 'George puts his stamp on the Fisher home. David cautions Nate about projecting his personal grief onto their clients; Keith applies for a glamorous new job; Joe challenges the logic of Brenda''s 12-step plan; Claire reawakens her artistic muse after meeting a free spirit named Edie; and Federico proves that charity doesn''t always begin at home.', 50, '2004-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 3, 'Parallel Play', 'A group of prank-happy teenagers find their latest joke is no laughing matter. Meanwhile, the Fishers decide to hold a yard sale; David grooms Arthur for a new role; Nate gets intimately involved in Maya''s afternoon playgroup; Claire attends an art party; Ruth and George receive some unwanted wedding gifts; Federico gets caught up in family responsibilities; Keith adjusts to the peculiarities of his new job; Joe isn''t thrilled by Brenda''s yearning for normalcy; and some important memories go up in smoke.', 56, '2004-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 4, 'Can I Come Up Now?', 'David''s ex-fiancee re-enters his life in search of answers to the question, ''Why me?'' Meanwhile, Nate has a psychic rendezvous, Keith''s new job sends him into the closet, Federico identifies with David''s past, Claire decides not to let life pass her by, George dumps some surprise baggage on Ruth, and Margaret weighs in on daughter Brenda''s new relationship.', 57, '2004-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 5, 'That''s My Dog', 'With Keith out of town on business, David gets taken for a ride by a hitchhiker. Meanwhile, Nate feels out of place in a bereavement group, Ruth tries to play matchmaker--to George''s chagrin, Claire feels empty after a critique of her self-portraits, Brenda and her mom go back to school, and Federico gets an unexpected visitor at work.', 57, '2004-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 6, 'Terror Starts At Home', 'Fisher & Diaz hosts two very different parties in one night. Meanwhile, David is uncomfortable with all the comfort he''s receiving; Nate finds temporary relief at a ''canine retreat,'' Claire and her art-school friends go on a trip, Ruth grows frustrated with George''s "nasty little secrets" and Federico gets his phone wires crossed.', 54, '2004-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 7, 'The Dare', 'Ruth goes on a fossil hunt with George, and digs up Sarah and Bettina. Claire focuses her talents on Edie; Federico tries to unload on Sophia; Vanessa does some part-time detective work; Keith goes ''out'' to a bar with his co-workers; David drowns his stress; Nate dares Brenda to be honest with Joe, and receives some relationship advice himself.', 57, '2004-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 8, 'Coming and Going', 'Nate and Brenda take Maya on a train ride, getting caught in their tracks when they go a little too far. Meanwhile, David tries to ''sex-orcise'' his demons; Keith straightens out a conflict of interest; Federico starts sleeping on the job; Ruth schools George when he treads on her garden; Vanessa and Angelica take some female matters into their own hands; and Claire enjoys ''dancing'' with Edie--as a spectator sport.', 53, '2004-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 9, 'Grinding the Corn', 'Ruth and Bettina take a road trip to Mexico, leaving the men of Fisher & Diaz to some male bonding--and comic-book crime-fighting. David and Keith open up after closing their ''open'' relationship; Claire warms up to Jimmy after getting the cold shoulder from Edie and Anita; Billy resurfaces as a substitute art teacher; and Nate can''t decide what he wants from Brenda, who turns to old friends to treat the pain.', 55, '2004-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 10, 'The Black Forest', 'Nate gives Maya ''one last look'' at a memorial for Lisa, where some surprise discoveries ensue. David and Keith are inspired by a same-sex wedding; George agrees to Ruth''s marriage stipulations; Federico is disturbed by the ''new and improved'' Vanessa; Brenda crosses a bridge with her therapy client; and Claire and Billy develop something in the darkroom.', 49, '2004-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 11, 'Bomb Shelter', 'Ruth is giddy about going to a tantric workshop with George, who retreats to the family''s emergency shelter. Meanwhile, David''s last bite at a sushi restaurant threatens to cost him--and Keith--a lot more than the bill; Nate drops a bomb on Barb, which sparks a counterattack; Claire fights Russell over credit for her latest photos; Margaret''s hospital stay helps Brenda and Billy begin to heal their rift; and Vanessa shows she can beat Federico at his own game.', 49, '2004-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 4), 12, 'Untitled', 'Ruth is delighted to meet George''s daughter, but worries as his paranoid ''views'' of the future escalate. ''Star'' Claire gets high off her newfound fame; Federico pleads his case to Vanessa, who delivers a verdict; David confronts a demon face-to-face; Keith considers a business proposal; and Nate comes to final blows with Barb and Hoyt.', 59, '2004-09-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')), 5, 'Season 5', 'Everything. Everyone. Everywhere...Ends. Story elements established in the first four seasons reach a series of emotional climaxes, with Ruth overwhelmed by her mentally fragile husband George, Nate struggling to reaffirm his relationship with Brenda while raising his daughter Maya, David and Keith longing for children of their own, Claire trying to broaden her horizons, and Federico attempting to fill the void left by Vanessa. By season''s end, all will come to embrace the cycle of life—birth, death and rebirth—in ways that are both unique and interconnected.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 1, 'A Coat of White Primer', 'Ruth dreads George''s return from the hospital in light of his recent diagnosis; Nate and Brenda prep for a big day, but an emergency makes them reconsider; David and Keith discuss alternative parenting options; Rico tries internet dating; and Claire enjoys domestic bliss but crosses a line with her camera.', 55, '2005-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 2, 'Dancing for Me', 'Nate hangs with some high-school friends but finds that, as adults, they share little more than teenage memories; Ruth gets relief from George''s daughter Maggie; Brenda is reluctant to accept Margaret''s help and struggles in her new internship; David and Keith''s latest baby dream starts to resemble a nightmare; Claire bemoans being pigeonholed by her art; Billy defends his career but secretly wonders what happened to his old self; and Rico, mortified that he couldn''t take a dating hint, seeks sympathy from Vanessa.', 53, '2005-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 3, 'Hold My Hand', 'Claire is seduced by Billy''s lust for life but hits a roadblock trying to fund the next leg of her educational journey; George is haunted by visions of an early trauma; Brenda feels at home with her new supervisor Jackie; David and Keith meet a fertile young woman named Mary; Vanessa encourages Rico to mingle, so he does--at a funeral directors'' conference.', 51, '2005-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 4, 'Time Flies', 'Brenda is disturbed by Nate''s reaction to her latest news; Ruth shares her feelings about George with her knitting circle; David and Keith ''propose'' to Mary and meet Roger''s equally unconventional family; Rico is shocked at how Vanessa and the boys are doing; frustrated, George shares a beer and a song with Billy; and Nate comes home to an unpleasant surprise.', 52, '2005-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 5, 'Eat a Peach', 'Nate and Brenda discuss giving Maya a ''coherent narrative''; David and Keith await news from Mary, and meet a special little boy; Vanessa is shocked when Julio gets into trouble at school--and mortified when Rico schmoozes things over; Billy invites Claire to dinner, but has no appetite; Margaret helps stage an ambush; and Maggie brings George to a tense meal.', 50, '2005-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 6, 'The Rainbow of Her Reasons', 'Ruth happily helps ''circle the wagons'' when Sarah calls; David and Keith discover it''s hard work playing house with Anthony and his brother Durrell; Nate muses on the loss of his first love; Claire finds a temporary financial solution; Vanessa hires a nanny with unexpected talents; Rico gets an offer he can''t believe--or refuse.', 55, '2005-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 7, 'The Silence', 'David and Keith struggle to create parent-child boundaries; When Brenda and Nate get some ambiguous news, it confirms their views on life and death; Ruth fills her schedule with activities, but has trouble unwinding; Claire meets an interesting guy at work, and makes an effort to fit in; Margaret lets a cat out of the bag; and George drops a bomb on Ruth.', 57, '2005-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 8, 'Singing for Our Lives', 'A young Latina''s funeral raises questions about the culture--and future--of Fisher and Diaz. Meanwhile, David and Keith are upset when they''re not in the driver''s seat; Claire takes her co-worker Ted to an art school show; Brenda gets vital info from her doctor--and from Jackie; and Ruth goes out for some pampering and gets more than she paid for.', 56, '2005-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 9, 'Ecotone', 'David and Keith get comfortable with their new family life; Claire is shocked to discover she and Ted share a passion for politics; Ruth finds empowerment in the woods; Maggie is forced to make a series of awkward calls; Brenda faces several truths at once; Rico finally ''gets'' Vanessa; and Nate brings the family together against their will.', 49, '2005-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 10, 'All Alone', 'While David attends to family business, Keith makes an embarrassing self-discovery on the job; Brenda is challenged by Nate and answers a hard question for Maya; Margaret compares herself to her daughter; Ruth lets Bettina play nurse; Rico and Vanessa decide to protect their future; Claire is comforted by Ted''s squareness; and George makes a speech about love.', 58, '2005-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 11, 'Static', 'As David''s fears take over, Keith tries to protect him--and the boys; Billy attends to his sister; Claire goes on a drunken harassment spree and pushes Ted away; Rico pushes for a talk about the business; George tries to help Ruth with Maya; Nate urges Brenda to embrace a taboo; and Vanessa sees the future in a funeral home.', 55, '2005-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0248654')) AND numero_temporada = 5), 12, 'Everyone''s Waiting', 'David finally embraces a demon; Keith gives tough love; Nathaniel talks to his younger son; Brenda delivers and fights Nate''s negativity; Claire gets an exciting call; Ted inspires sexy photos; Margaret is impressed to see Olivier''s nurturing side; George''s limitations eclipse his intentions; and Claire drives into her future.', 73, '2005-08-21');
