INSERT IGNORE INTO Trabajadores (id_api, nombre) VALUES ('nm0011148', 'Lillian Adams');
INSERT IGNORE INTO Trabajadores (id_api, nombre) VALUES ('nm0000775', 'Christina Applegate');
INSERT IGNORE INTO Trabajadores (id_api, nombre) VALUES ('nm0000139', 'Cameron Diaz');
INSERT IGNORE INTO Trabajadores (id_api, nombre) VALUES ('nm0005048', 'Thomas Jane');
