INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0247082', 'CSI: Crime Scene Investigation', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0277830'), 'SERIE', 'A team of Crime Scene Investigators (CSI''s) work with the Las Vegas Police Department (LVPD) to solve crimes by using advanced scientific methods and technology in Las Vegas, Nevada.', '2000-01-01', 'https://m.media-amazon.com/images/M/MV5BYWRjMjU2NmUtMmQ0MS00NDMyLTg4NGItNjg1OWY2OGI4ZDM5XkEyXkFqcGc@._V1_.jpg');
