INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 1, 'Pilot', 'Gil Grissom is the supervisor of the graveyard shift of Las Vegas'' elite crime scene investigators. Holly Gribbs, fresh out of the academy, joins the team.  Jim Brass is head of the unit and is trying to scare Gribbs from CSI.  Catherine Willows, mother of a young daughter, is the number two CSI on this shift.  Warrick Brown and Nick Stokes are competing to solve their 100th case to earn a promotion to CSI 3. Grissom investigates a murder staged to look like a suicide with precious little evidence.  Warrick and Catherine take the case of a drunk who breaks into the house where he had been staying and is shot to death. Nick talks to a man who picked up a woman who drugged and robbed him.', 46, '2000-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 2, 'Cool Change', 'A man is killed after winning a fortune and then dumping his girlfriend.  So, Grissom, Nick, and newcomer to the CSI team, Sara Sidel, investigate this one.  Holly Gribbs is in the hospital and Warrick is up for suspension for leaving her at the crime scene by herself.  Holly later dies in the hospital, but Grissom doesn''t suspend Warrick.', 44, '2000-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 3, 'Crate ''n Burial', 'Grissom, Nick, and Sara search for a kidnapped woman and find more than they expected. Catherine and Warrick investigate the hit and run death of a little girl.', 45, '2000-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 4, 'Pledging Mr. Johnson', 'Grissom and Catherine investigate when a leg is found severed from a body in a lake.  They suspect the husband and boyfriend.  Meanwhile Sara and Nick investigate a fraternity pledging gone terribly wrong.', 45, '2000-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 5, 'Friends & Lovers', 'Grissom and Warrick take the case of a young man who is found naked in the desert without an obvious cause of death.  Sara gets to find out why the body of a woman who was buried last week is in a dumpster.  Catherine and Nick investigate the killing of a school''s dean by the school''s founder.', 46, '2000-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 6, 'Who Are You?', 'Catherine violates department protocol when she takes the case of a rape accusation against her ex-husband.  Warrick and Sara search for the missing bullet that will either exonerate or indict a cop for murder.  Grissom and Nick investigate when a female skeleton is found under a house buried in cement.', 46, '2000-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 7, 'Blood Drops', 'When a teenager and her sister are the sole survivors of the gruesome murder of four members of one family in a quiet suburban neighborhood, Grissom and his entire team investigate the crime. What initially looks like a bizarre cult murder becomes more disturbing when they discover the motive behind the massacre.', 45, '2000-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 8, 'Anonymous', 'Royce Harmon was murdered 3 months ago in a scene staged to look like a suicide. Now another murder has taken place. Whoever the killer is he has a thorough knowledge of forensics, he purposefully has left evidence, and has baffled Grissom and his team.  Warrick and Nick investigate the case of a man who went over a cliff in his car and is now unconscious.', 45, '2000-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 9, 'Unfriendly Skies', 'Grissom and his team investigate the death of a first class passenger on a flight to Las Vegas. The investigators are forced not only to examine the physical evidence, but also to interview all of the first class passengers to get their personal accounts of the incident.', 45, '2000-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 10, 'Sex, Lies and Larvae', 'Grissom and Sara investigate a bug riddled body found in the desert.  Warrick and Catherine look in to the theft of some valuable art.  Nick gets to find out why a missing woman''s car is found at the bus station. Warrick is suspected of having gambled on duty.', 46, '2000-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 11, 'I-15 Murders', 'A woman is abducted from a supermarket. In the store, Grissom finds a bathroom stall door that claims five women have been killed.  Warrick is caught in a casino on duty and is paired with a reluctant Sara. Their case is the apparent murder and robbery of a man who is found be his brother. Nick gets pulled in by his prostitute friend who gets in a scuffle with hotel security.', 44, '2001-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 12, 'Fahrenheit 932', 'A man convicted of arson and the murder of his wife and child seeks assistance from Grissom to help prove his innocence. Meanwhile, Catherine and Nick investigate the underground world of sports gambling when a teenager is murdered at close range.', 45, '2001-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 13, 'Boom', 'A bomb goes off in an office building killing one and injuring many more. The chief suspect is a security guard who left minutes before the explosion and has knowledge in bomb making.  Nick helps his prostitute friend again. After giving in to his passion, she is found dead the next morning. Naturally, Nick is a suspect and to make it worse, Ecklie has the case.', 46, '2001-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 14, 'To Halve and to Hold', 'When a single human bone is discovered in the desert, Grissom and Catherine must cover miles of territory to find the rest of the skeleton. And Warrick and Sarah trace the death of a male stripper to members of a wedding party who may have celebrated a little too hard the night before the nuptials.', 44, '2001-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 15, 'Table Stakes', 'At a swanky fundraiser, attended by the sheriff, a woman turns up dead in the pool.  The owner of the house is away and a young couple is housesitting. Warrick looks into an apparent professional hit in the glass elevator of one of the hotels.', 46, '2001-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 16, 'Too Tough to Die', 'A woman is abducted from a mall parking garage. She''s raped, beaten, shot and left for dead.  Sara collects evidence from her and grows attached to her.  Nick and Grissom analyze the crime scene.  Catherine and Warrick are given boxes of evidence from a shooting that goes to trial in four days.  The CSI who had the case has quit and they have to prove what happened.  To make Catherine''s life more complicated, Eddie has taken out a second mortgage without her knowledge.', 44, '2001-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 17, 'Face Lift', 'A body is found in a pottery store in what''s apparently a robbery that was interrupted. Fingerprints at the scene seem to match a twenty year old kidnapping case.  Sara and Warrick look into a case where a woman burned to death in her home. The woman was burned to an ash but only the chair she was in was burned, the rest of the house is fine. Sara believes they have a case of spontaneous combustion.', 46, '2001-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 18, '$35K O.B.O.', 'A couple leaving a restaurant on their anniversary are killed in the street and their car is stolen.  The crime scene is compromised when it rains shortly after the CSIs arrive.  It gets more mysterious when the car is found and it becomes a new crime scene. Catherine looks into the collapse of a city owned residence that kills three elderly women. She runs into problems with the city engineer responsible for the building.', 45, '2001-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 19, 'Gentle, Gentle', 'The entire team investigate the abduction of the infant child of a well to do family. Suspicion immediately falls on the child''s parents.', 46, '2001-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 20, 'Sounds of Silence', 'Two women run over a deaf man but they didn''t kill him- he was already dead.  Grissom has to find out who did it and he''s not getting help from the deaf man''s school.  Catherine and Nick investigate an apparent mob hit that leaves five dead in a coffee shop.', 46, '2001-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 21, 'Justice is Served', 'Grissom, Nick, and Warrick take the case of a jogger who was killed by a wild animal in the park. It gets complicated when they discover that the jogger had his liver removed after he was killed.  Catherine and Sara investigate the death of a six year old girl at shady carnival.', 44, '2001-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 22, 'Evaluation Day', 'On the day Grissom has to evaluate his team, a head is found in the trunk of a car. While Gil and Catherine work on the head, Sara and Nick investigate a body in the desert that''s missing it''s head. Warrick looks into a murder in juvenile detention in which his young friend James is the only witness.', 45, '2001-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 1), 23, 'Strip Strangler', 'The team is investigating the ongoing murders by a signature killer. The killer has some knowledge of forensics and has left little evidence behind. With the investigation somewhat stalled, the sheriff invites the FBI to join the case. This makes Grissom angry and it only gets worse when Sara offers to bait the killer.', 46, '2001-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 1, 'Burked', 'Grissom and crew are called in after high roller Tony Braun, a known drug addict, is found dead in his house by a gardener.  Since drug paraphernalia is discovered near his body and it is also determined that he had recently inhaled heroin, the cause of death is at first thought to be an overdose.  But further examination of the corpse reveals that Braun had been restrained at some point with duct tape, leading Grissom to believe that the victim was forced to ingest lethal amounts of heroin and, perhaps, other drugs.', 45, '2001-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 2, 'Chaos Theory', 'The entire CSI team investigates a disappearance at a local university. A young woman vanished, seemingly off the face of the earth.', 44, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 3, 'Overload', 'Grissom investigates a possible suicide at a high-profile construction site. Catherine takes on a case with a teenage boy who dies while in session with his female psychologist,', 45, '2001-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 4, 'Bully for You', 'When the class clown at the local high school is found murdered, the CSI team is called to investigate, while Nick and Sara respond to the crime scene of a decomposed body found in a bag.', 44, '2001-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 5, 'Scuba Doobie-Doo', 'Grissom, Sara and Warrick are called on to investigate an abandoned, blood-splattered apartment and Nick and Catherine must examine a dead scuba diver lodged in a tree.', 43, '2001-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 6, 'Alter Boys', 'Grissom and his team investigate a murder suspect who is caught red-handed -- burying the victims -- while Catherine and Warrick take on the case of a woman found dead in a hotel spa.', 45, '2001-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 7, 'Caged', 'Grissom and Nick investigate the death of a book restorer while Catherine and Sara are called to the scene of a fatal train crash.', 45, '2001-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 8, 'Slaves of Las Vegas', 'Grissom and Catherine investigate the apparent violent death of a woman found in a sandbox.  Warrick and Sara are called to a crime scene to investigate a shooting, which initially appears to have taken place during a robbery.', 45, '2001-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 9, 'And Then There Were None', 'Grissom and his team investigate a casino heist during which innocent victims were shot, while Catherine and Sara are called to the scene of a murder in a remote part of the desert.', 41, '2001-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 10, 'Ellie', 'Warrick heads the investigation of the murder of a con artist who turns out to be involved with Brass'' daughter, and the evidence leads Sara on a counterfeit investigation.', 43, '2001-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 11, 'Organ Grinder', 'When the body of Bob Fairmont, the real estate developer, is found, the team discovers that the crime scene has been tampered with and that the victim has been re-dressed.', 42, '2001-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 12, 'You''ve Got Male', 'Grissom and Sara are called to the crime scene when two murder victims are found hidden in pipes at a construction site in the middle of an alfalfa field, while Catherine and Nick investigate an ostensible hunting accident.', 45, '2001-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 13, 'Identity Crisis', 'Grissom''s nemesis, serial killer Paul Millander, reappears and claims a third victim in this gripping episode. The latest slaying matches Millander''s previous killings in that it recreates his father''s murder.  The killer''s next target was born Aug. 17, 1956...which just happens to be Grissom''s birthday.', 45, '2002-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 14, 'The Finger', 'Catherine is ordered by a kidnapper to accompany a man who is to deliver $1 million in ransom to him or else he will kill the man''s mistress.', 44, '2002-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 15, 'Burden of Proof', 'Grissom investigates the murder of a Las Vegas photographer whose remains were dumped at a nearby body farm where CSIs routinely study corpses, and his findings reveal that the man was apparently shot to death even though there are no bullet fragments in the body.', 45, '2002-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 16, 'Primum Non Nocere', 'Grissom, Catherine and Sara are called in to investigate the death of a hockey player on the ice. Warrick and Nick look into the apparent drug-related death of a sax player at a casino.', 45, '2002-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 17, 'Felonious Monk', 'Grissom investigates the murders of four monks who were shot point blank while chanting in a Buddhist temple; Catherine reopens a cold case in which her best friend was murdered, after the man convicted of the crime claims he''s innocent shortly before he dies.', 43, '2002-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 18, 'Chasing The Bus', 'A bus carrying 23 passengers from Los Angeles to Las Vegas crashes less than 40 miles from its destination, killing nine people.  Tthe CSIs soon discover that a recent parolee was on the bus, but is now unaccounted for.', 44, '2002-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 19, 'Stalker', 'Jane Galloway lives in fear. Her doors are triple-locked. Every shade is drawn. The bathroom window is nailed shut. An alarm system is activated. Who killed Jane, and how could the murderer have possibly entered, and left, the house?', 45, '2002-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 20, 'Cats in the Cradle', 'Grissom and Catherine investigate the stabbing death of an 80-year-old woman who lived in a run-down house full of cats; Nick and Sara comb through the remains of a car bombing that was, apparently, a murder plot gone awry.', 45, '2002-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 21, 'Anatomy of a Lye', 'Grissom and Sara investigate when a man''s body, which has been doused with lye, is found buried in a park; Nick tries to determine how a hiker apparently drowned in a desert.', 45, '2002-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 22, 'Cross Jurisdictions', 'Grissom and his crew handle their highest profile case to date when the city''s former chief of detectives is slain execution-style in his house following a wild party. Missing from the residence are the chief''s trophy wife and their 7-year-old daughter.  Catherine and Warrick follow the trail to Miami, and soon enlist the help of Horatio Caine.', 47, '2002-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 2), 23, 'The Hunger Artist', 'Season Finale. The CSIs investigate when the body of an unidentified young woman is discovered stuffed in an overturned shopping cart near a freeway underpass. Her horribly disfigured and partially decomposed face is a nightmare of blood, scabs and scars, as if she''d been shoved into a fan. A huge circular hole dominates her left cheek. Someone not only wanted her dead, Grissom reasons, but ""they wanted her ugly."" Adding to the mystery are the cart''s other contents: an expensive handbag, fashion magazines and a leather day planner with notes written in code.', 45, '2002-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 1, 'Revenge Is Best Served Cold', 'Catherine and Nick become absorbed in the dangerous world of street racing after one of the illegal sport''s hotshot drivers is found dead out in the desert at an abandoned airstrip. Back in town, Grissom and his crew probe the sudden death of a renowned poker player who suffered a violent convulsion in the middle of a high-stakes game with three others. It looks like natural causes, at first, but Grissom suspects foul play.', 43, '2002-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 2, 'The Accused Is Entitled', 'Grissom and his crew are called in to investigate the death of a young woman found in the hotel room of popular actor Tom Haviland. Haviland admits that he slept with her, but denies killing her. Grissom believes otherwise, however, after finding blood evidence on the celebrity. Then things get personal when Haviland''s lawyer hires Grissom''s former mentor, Philip Gerard, to find mistakes in the forensic part of the case. And, unfortunately for Grissom, Gerard finds plenty of errors to exploit.', 45, '2002-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 3, 'Let the Seller Beware', 'Grissom and Catherine investigate the murder of a wealthy couple who are discovered just outside of their glamorous Las Vegas house, which was up for sale. Meanwhile, Sara probes the death of a cheerleader who is found eviscerated on a soccer field, her organs having been ingested by her killer.', 45, '2002-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 4, 'A Little Murder', 'Grissom suspects murder, not suicide, when the body of a dwarf is found hanging from a rope high above a stage in a casino hotel where a convention of little people is being held. Across town, Catherine is attacked at a crime scene where a man was murdered during what appears to have been a home robbery.', 44, '2002-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 5, 'Abra-Cadaver', 'Grissom investigates when a woman vanishes while taking part in a magician''s act. The female volunteer is placed inside the Amazing Zephyr''s "Chamber of Doom" and the illusionist thrusts swords through the box. When it''s opened, she''s gone---and doesn''t reappear in her seat as she''s supposed to. Only traces of blood are left inside the chamber. Clues lead the CSIs to an eerie, decrepit mansion filled with secrets. Elsewhere, a rock star''s death on a band bus appears to be the result of an overdose, but Catherine uncovers evidence that points to murder.', 50, '2002-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 6, 'The Execution of Catherine Willows', 'Fifteen years ago, Catherine helped put John Mathers on death row for the rape and murder of a coed at a nearby college. Her body was dumped in a trash bag, and two other girls found the same way were also linked to the suspect. As the episode opens, Mathers is about to be executed when he''s granted a stay based on new DNA evidence. But while Catherine awaits the results of tests on hair samples found on the first victim, another girl at the same school is murdered... and discarded just like the first three - meaning the wrong man could be behind bars.', 43, '2002-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 7, 'Fight Night', 'A middleweight boxing champ dies in the ring after taking a brutal beating from his nemesis, but Grissom finds evidence that points to murder. Outside, in a nearby parking lot, Catherine works a crime scene where a Los Angeles gang member was gunned down, apparently by a rival gang. Also, Nick investigates a jewelry-store robbery.', 45, '2002-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 8, 'Snuff', 'Catherine called in by a pornographic-film developer to view graphic footage from a snuff movie in which a woman is brutally slain. But the clues are scant: The murderer isn''t clearly seen, the cheap-looking hotel room could be almost anywhere and the film was sent to the developer anonymously. Outside of town, Grissom investigates another killing when a body, smothered with fire ants, is found stuffed inside a large toolbox. The initial findings indicate that the person died well over a year earlier.', 42, '2002-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 9, 'Blood Lust', 'Distracted by an attractive passenger, an Indian taxi driver feels his cab strike something at a suburban intersection. When he gets out to check, he finds a teenage boy pinned beneath the left rear tire, apparently killed on impact. The cabbie jumps back into the taxi to call for help, but a mob of angry onlookers - all of them white - drags him out and beats him for the crime. When Grissom arrives on the scene, he discovers that the teen has been eviscerated and has stab wounds, but shows no signs of having been struck by the cab.', 43, '2002-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 10, 'High and Low', 'Grissom, Warrick, and Nick investigate the case of man who apparently was murdered and pushed off a six story building. Grissom''s involvement is cut short by renewed hearing problems.  Catherine looks into the murder of man outside of his regular bar.', 44, '2002-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 11, 'Recipe for Murder', 'Grissom and Catherine investigate the grisly meat grinder murder at a slaughterhouse. Warrick and Sara look into the apparent suicide of a troubled young woman.', 43, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 12, 'Got Murder?', 'Some bird watchers find a raven with a human eyeball in its beak. This eventually leads our CSIs to a divorced man and his 2 children but not much else. Warrick and Grissom look into the circumstances of David''s unusual and first autopsy. This takes them to a car dealership where the man worked.', 45, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 13, 'Random Acts of Violence', 'Warrick investigates the drive by murder of a young girl in his old neighborhood. The girl''s father is a friend and mentor of Warrick''s as well.  Warrick struggles to control his emotions to the point where Grissom pulls him off of the case.  Nick tackles the murder of a computer company employee. The only supects are the three other employees in the building.', 45, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 14, 'One Hit Wonder', 'Catherine takes the point in the investigation of an escalating series of peeping tom incidents. The crew is racing to stop the attacker before his crimes become more serious assaults.  Meanwhile, Sara reopens the dormant case of her friend, a district attorney. The DA is facing surgery to remove a bullet she got in an attack that killed her husband three years prior.', 44, '2003-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 15, 'Lady Heather''s Box', 'Grissom investigates the murder of two men that leads him to a new encounter with Lady Heather. Catherine is desperate to find out what lead to the near death of her daughter and why her ex, Eddie, disappeared.', 65, '2003-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 16, 'Lucky Strike', 'A man driving with a wooden stake in his head dies in front of a casino.  Grissom and Nick work to discover the ''vampire'' killer.  Warrick and Catherine hunt for the killer of a NBA star''s 5 year old son.', 42, '2003-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 17, 'Crash and Burn', 'An elderly woman crashes her car into a crowded restaurant. One of the patrons is Sara''s paramedic boyfriend.  Grissom and Nick investigate the possible carbon monoxide murder of a woman in her home.', 44, '2003-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 18, 'Precious Metal', 'Catherine, Nick, and Sara investigate a seemingly months old body found in the mountains. Discovery of the man''s identity lead the team to the world of robot wars.  Warrick and Grissom look into the case of a man found murdered in an alley. Complicating their efforts, the medical examiner ""lost"" the body for 11 days. Greg helps this case by doing some undercover work.', 44, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 19, 'A Night at the Movies', 'Grissom and Catherine investigate a movie-goer who was stabbed to death; the team comes to a forensic impasse while processing a teenager who died from a gunshot wound.', 44, '2003-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 20, 'Last Laugh', 'Grissom and Catherine investigate the murder of a despised comic who died onstage, apparently after drinking from a tainted bottle of water. The case grows more puzzling when a 15-year-old boy dies in a convenience store after drinking the same brand of water. Brass reopens a woman''s accidental-death case after spotting the deceased''s husband in a flashy new car with a trophy date on his arm.', 45, '2003-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 21, 'Forever', 'A murder aboard a luxurious 747 and the discovery of two formally attired teens in the desert confound Grissom and his crew in this absorbing episode. First, a horse trainer is found dead in the cargo bay of a private jet carrying 12 well-heeled passengers and a million-dollar show horse. Initially, it appears the victim was trampled to death, but Grissom and Catherine uncover evidence of foul play. Meanwhile, in the Hell''s Gate section of Death Valley, Sara and Warrick probe the apparent suicide of a 15-year-old boy found under a bedspread. The investigation intensifies when a girl''s body turns up a half-mile away.', 44, '2003-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 22, 'Play with Fire', 'A woman''s body is discovered in a small press box at a high-school football field, apparently the victim of strangulation. The evidence leads investigators to two convicts, one of whom is still in prison. At the crime lab, an explosion destroys key evidence and leaves Greg and Sara injured.', 44, '2003-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 3), 23, 'Inside the Box', 'Things get personal for the CSIs in the top-rated series'' third-season finale, which explores the intersection of the investigators'' work and their personal lives. Three masked bandits steal a safe-deposit box from a Las Vegas bank in a daring daytime heist, during which Det. Lockwood is killed. Lockwood''s death provides Grissom and his crew with added incentive to find the murderous culprits. But the case really hits home for Catherine when the evidence leads to casino owner Sam Braun, who is like a father to her. Also, Grissom''s hearing gets progressively worse and he seeks out Dr. Robbins for help.', 44, '2003-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 1, 'Assume Nothing (1)', 'Two couples meet in a bar and one of the couples is murdered. When a second couple is murdered in a similar fashion the team suspects a pair of serial killers are on the loose. The case is complicated by leaks to the press and a judge reluctant to issue a warrant. Catherine gets some troubling news about her father''s murder trial.', 44, '2003-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 2, 'All for Our Country (2)', 'When the lead suspects in Grissom''s serial killer case are murdered, Grissom suspects an inside job. Grissom and Brass are at odds when Grissom suggests it was a cop. Catherine and Sara investigate what happened to a college football fan when his bloated body is found in a bathtub.', 43, '2003-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 3, 'Homebodies', 'Grissom and Warrick get the case of an old woman found mummified in her closet. Sarah and Nick arrive to investigate a breaking and entering to find a raped teen. These cases are not as disparate as they first seem. Catherine looks into a gun found by a boy. The gun is connected to a week old murder across town that Warrick caught.', 42, '2003-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 4, 'Feeling the Heat', 'During Vegas''s latest Heat wave of triple digit temperatures, Gil and Catherine investigate a baby locked in a car. Warrick investigates a man dead of an apparent heat stroke in his house. Nick and Sarah investigate a woman''s body found floating in the lake with a blow to the head.', 44, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 5, 'Fur and Loathing', 'The team is introduced to the ""Furry"" side of Vegas when a man is found dead on the side of the road, dressed in a racoon suit. Elsewhere in Vegas, a gunshot victim is found in a deep-freezer, frozen solid.', 44, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 6, 'Jackpot', 'A severed head is shipped to Dr. Robbins from Jackpot, Nevada. Grissom goes to Jackpot to find the rest of the body and gets very little cooperation from the locals. Catherine gets an unexpected gift from her father.', 45, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 7, 'Invisible Evidence', 'Warrick''s appearance at the preliminary hearing on a rape and murder case goes terribly wrong when the only piece of evidence is thrown out on a technicality. Grissom and the team have 24 hours to make the case with new evidence or the killer will go free.', 45, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 8, 'After the Show', 'A suspect''s infatuation with Catherine results in her taking over a high profile case. The case is a missing woman who aspired to be a showgirl. Sara and Nick are angered since it takes the career making case away from them.', 45, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 9, 'Grissom Versus the Volcano', 'The sheriff is under political pressure to find who killed an air marshall with a car bomb that the sheriff witnessed. Grissom, Catherine and Nick are pressured to produce results. Warrick and Sarah try to find the murderer of the wife of a singer who headlines on the strip.', 43, '2003-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 10, 'Coming of Rage', 'A teenager is found murdered on a construction site. Grissom, Sarah, and Warrick follow the lead of blood on a hammer. Nick, with an assist from Catherine, tries to find how a woman was killed by a gunshot on her lawn when no one nearby had a gun.', 44, '2003-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 11, 'Eleven Angry Jurors', 'The lone holdout on a jury is found dead in the jury room. The eleven jurors who were voting guilty and who hated the dead juror are the natural suspects. Nick reopens a four year old case when the sister of the victim comes forward with new evidence.', 42, '2004-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 12, 'Butterflied', 'A woman found murdered in her home. Her resemblance to Sara causes Grissom to take a personal interest in the case and forces him to examine the decisions he has made in his life.', 45, '2004-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 13, 'Suckers', 'Three little CSIs (Grissom, Sara, and Nick)respond to an electrocution at a casino. The casino is hosting Japanese antiquities. The electroctution is just a ruse to steal the central piece of the exhibit. Catherine and Warrick deal with a vampire murder.', 45, '2004-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 14, 'Paper or Plastic', 'A robbery at a grocery store results in a shootout leaving five dead. The police officer at the scene believes Grissom has a grudge against him. The entire team has to process the enormous amount of evidence at the scene.', 44, '2004-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 15, 'Early Rollout', 'The whole team must investigate a crime where a husband and his porn star wife were murdered execution style.  Things get personal for Catherine when Grissom talks to her about her evaluation. Brass believes that Sara may have some type of problem.', 45, '2004-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 16, 'Getting Off', 'Catherine and Sara deal with the death of what at first seems to be a transvestite. Later during autopsy they find out that the make-up he seemed to be wearing was actually facepaint, he was a clown. Grissom, Nick, and Warrick deal with the death of a man in a homeless area. They found out he worked in a recovery center for drug users.', 43, '2004-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 17, 'XX', 'A mutilated female body is discovered tied to the undercarriage of a bus carrying prisoners from a women''s correctional facility after a severed arm flies out from beneath the vehicle and strikes a car. Catherine leads the investigation and at first believes the woman was escaping, but the evidence increasingly points to murder. Back in town, Warrick probes the death of a gambler who was stabbed multiple times in his brother''s kitchen.', 44, '2004-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 18, 'Bad to the Bone', 'A violent murder in a casino parking garage and another episode in the police interview room lead the CSIs to one shocking discovery after another. The case involves a missing woman, a long dead body and a missing child.', 44, '2004-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 19, 'Bad Words', 'Warrick, Catherine, and Nick try to determine the cause of a house fire that kills a teenage kill. The fire is in the same neighborhood as a similar arson fire. Grissom and Sara investigate a man found dead with letter tiles in his stomach. The man was a competitor in a word game tournament.', 45, '2004-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 20, 'Dead Ringer', 'Grissom, Catherine and Nick investigate the death of a runner during a competition. Meanwhile Sara and Warrick investigate the death of  couple in a hotel room, initially thought to be a murder-suicide. Both cases take place during this ''cop'' competition , with more than 20.000 attendants (all of them cops). This gives the investigations an interesting turn, as almost all the suspects and all dead people are cops.', 43, '2004-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 21, 'Turn of the Screws', 'A roller coaster runs off track leaving 6 people dead.  The CSI team must uncover whether this was an accident, or foul play. Warrick and Catherine try to find the killer of a 13 year old girl.', 44, '2004-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 22, 'No More Bets', 'Two men are found murdered after scamming Sam Braun''s casinos. Grissom and Warrick investigate after Catherine is thrown off the case. One of the suspects is the son of a man Braun caught cheating. Nick gets the promotion that Sara coveted.', 44, '2004-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 4), 23, 'Bloodlines', 'A casino employee is beaten and raped on her way home from work, but she survives and identifies her attacker. Unfortunately, a DNA test sets him free and Grissom must wrestle with whether evidence can ever lie. Later, Grissom comes to the rescue of a coworker who ends up on the other side of the law', 44, '2004-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 1, 'Viva Las Vegas', 'A wild night in Las Vegas has the CSIs simultaneously investigating four fatalities. Greg Sanders'' first day in the field has him assisting Grissom''s investigation of a fatal nightclub shooting. Meanwhile, Catherine probes into the death of a stripper found dead in a hotel room, while Sara and Nick look into the strange case of an "alien" body found near Area 51.', 46, '2004-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 2, 'Down the Drain', 'Heavy rains in Vegas wash up a body in the storm drains. As the team investigates, they find bones from another murder.', 45, '2004-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 3, 'Harvest', 'A child is abducted. As the Amber Alert goes out, the entire team investigates in a race against time. Lindsay Willows is found hitchiking to the alarm of Catherine.', 45, '2004-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 4, 'Crow''s Feet', 'A woman is found dead in a hotel suite with symptoms of the ebola virus. Another woman is found dead with similar symptoms. Catherine and Nick investigate. Sara and Greg with help from Grissom try to determine how a the owner of a home was killed. His home was tented for infestation.', 45, '2004-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 5, 'Swap Meet', 'Grissom and Sara investigate the murder of a woman after a swap party. The married couples in the neighborhood meet and switch partners. With the help of a crime scene cleaner, Nick and Warrick find there was more to their crime scene than they first thought. Catherine wants a promotion to day shift supervisor.', 45, '2004-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 6, 'What''s Eating Gilbert Grissom?', 'The killer from The Execution of Catherine Willows returns with deadly results. The entire team is engaged in a race against time to stop this sadistic killer from succeeding again. Grissom is additionally distraught by the idea that this killer is smarter than he is.', 45, '2004-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 7, 'Formalities', 'Grissom is called to a murder of a 17-year-old in a casino penthouse. Sophia Curtis (Louise Lombard) joins him in his research, she normally works in the day-shift. The entire team gets involved when its discovered that a kiddnapping took place along with the murder.', 44, '2004-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 8, 'Ch-Ch-Changes', 'A woman who was pulled over by police is found murdered two miles up the road from the stop. It''s not long before Robbins determines that the woman is, genetically speaking, not a woman.', 45, '2004-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 9, 'Mea Culpa', 'Grissom is confronted with new evidence while on the stand of a murder trial of a restaurant owner. This development requires the reopening of the case and Eckley initiates an inquiry into Grissom and his team. The results of the inquiry lead to dramatic changes of the CSI team and the series.', 44, '2004-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 10, 'No Humans Involved', 'Grissom and his team investigate the starving death of a five year old boy. They discover the boy has siblings who are in danger too. Catherine and her team determine who killed a prisoner in a holding cell brawl.', 44, '2004-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 11, 'Who Shot Sherlock?', 'Greg, for his final proficiency, has to determine how the Sherlock Holmes of a Sherlock Holmes club was killed. Nick and Warrick try to determine how the driver of jeep was killed when the car ran off the road. They have to do this under budget while Catherine is watched by Ecklie.', 45, '2005-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 12, 'Snakes', 'The swing shift has a busy time. Warrick looks into the murder of man by someone who apparently needs a wheelchair. Nick looks into the murder of woman in the subculture of the narcocorrido, songs about drug murders. The night shift is slow and lends help to Catherine''s team.', 44, '2005-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 13, 'Nesting Dolls', 'Catherine, Warrick and Nick find the body of two women at a construction site buried under tar. The swing shift are brought into the world of foreign "mail-order" brides. Sara and Catherine have a dispute in which Sara gets suspended by Ecklie for acting insubordinately towards Catherine and himself. Sara opens up to Grissom about her childhood past.', 43, '2005-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 14, 'Unbearable', 'Grissom, Sofia, Sara and Greg investigate the disappearance of a woman coming home from a night out with a friend, her abandoned car found on the edge of a highway.  Catherine, Warrick and Nick investigate the deaths of a hunter and his prey, a Kodiak bear.', 45, '2005-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 15, 'King Baby', 'When a major Las Vegas player is found dead, Ecklie orders both teams to investigate the case. The man who had secrets on everyone in Vegas had a very big one of his own.', 45, '2005-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 16, 'Big Middle', 'Catherine, Nick, and Warrick investigate a badly mutilated body in the woods. The cause of death was a shotgun blast. Nearby is a beaver dam made in part with cash. Grissom, Sarah, and Nick try to determine how a man was killed in a hotel room. It leads them to a convention of big women.', 43, '2005-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 17, 'Compulsion', 'A serial killer strikes again, and the CSI team tries new technology using evidence from a prior killing.  They find a fingerprint belonging to Jesse Acheson, who becomes the prime suspect.  A boy confesses to the killing of his brother, but evidence suggests that he may not have committed the crime.', 44, '2005-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 18, 'Spark of Life', 'Grissom, Sara, and Nick investigate a wildfire that killed one man and badly burned a woman. Catherine, Nick, and Warrick get the case of a family of three murdered in their home.', 43, '2005-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 19, '4 x 4', 'One night, four cases. Grissom and Brass get a stolen hummer and a taco stand. Warrick gets a dead car show girl. Sara and Greg get a dead bodybuilder. Nick gets a dead boy found on a bench.', 45, '2005-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 20, 'Hollywood Brass', 'Brass travels to Hollywood, California to try to track down his estranged  daughter''s friend, meanwhile trying to rekindle some kind of relationship with her.', 45, '2005-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 21, 'Committed', 'Grissom and Sara investigate the murder of a mental-hospital patient and quickly narrow down the suspects to a handful of other patients and staff members.', 42, '2005-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 22, 'Weeping Willows', 'A man (Alan Rosenberg) whom Catherine flirted with at a bar reappears in her life as a suspect in a murder investigation.', 44, '2005-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 23, 'Iced', 'Two amorous freshmen are found dead on a sleeping bag in a dorm room, and Sara and Greg run into one dead end after another as they try to determine why the students were killed. Warrick, Nick and Catherine figure out how a man is found dead in the center of a crop circle. Ecklie is called into duty for a man found dead in his car and his body later goes missing.', 44, '2005-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 24, 'Grave Danger (1)', 'The CSI teams come together to save one of their own when they learn one team member has been kidnapped and buried alive, and now they must find him before he suffocates under five feet of dirt.', 46, '2005-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 5), 25, 'Grave Danger (2)', 'The CSI teams come together to save one of their own when they learn one team member has been kidnapped and buried alive, and now they must find him before he suffocates under five feet of dirt.', 41, '2005-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 1, 'Bodies in Motion', 'The two forensic teams come back together under the leadership of Grissom and Catherine just in time to tackle three separate investigations: a murdered couple found in bed in a suspicious trailer explosion; a beautiful stripper discovered dead and dumped in the worst part of town; and two bodies found baked and decomposed after spending five days in the trunk of a car exposed to the hot Vegas sun, forcing the CSIs to ""wrap"" up the evidence and bring it back to the lab for further analysis.', 44, '2005-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 2, 'Room Service', 'An up-and-coming movie star is found dead in his hotel room after a night of partying with his groupies.', 44, '2005-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 3, 'Bite Me', 'The CSIs investigate a man''s claim that his wife fell down a set of stairs in their home.', 45, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 4, 'Shooting Stars', 'The CSIs come across an abandoned military compound being used by a small cult. The CSIs grow suspicious when they see that a mass suicide has taken place, but only 11 of the 12 beds are occupied.', 45, '2005-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 5, 'Gum Drops', 'Nick takes the lead on a case where in the house a family of four, three pools of blood are found. Nick thinks that the little girl may still be alive, but Sara is doubtful, thinking that Nick''s recent near-death experience is affecting his judgement.', 45, '2005-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 6, 'Secrets and Flies', 'A 28 year-old single mother is found dead. Initially, it''s believed to be a suicide, but Catherine determines she was murdered. Also, Ecklie summons Grissom to refute the testimony of an entomologist in a murder trial.', 45, '2005-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 7, 'A Bullet Runs Through It (1)', 'The team must investigate the death of a police officer who died during a shootout leaving hundreds of bullets on the crime scene. The case becomes complicated when it turns out that Sofia Curtis and Jim Brass were with the victims during the shootout. When it turns out the officer died from friendly fire, it is up to the team to find out who fired the fatal shot. Meanwhile, Sofia is wondering whether she fired the fatal shot or not. She decides to hide the fact that the officer stepped into her line of fire, afraid it will ruin her career.', 41, '2005-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 8, 'A Bullet Runs Through It (2)', 'The CSIs sift through the overwhelming evidence from a shootout with drug dealers in order to determine who is responsible for the death of a police officer killed during the incident.', 44, '2005-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 9, 'Dog Eat Dog', 'Catherine and Brass investigate the case in which a man is found dead in a dumpster. It soon turns out the man had a serious food problem. The trail of his death soon leads to a hotdog-eating contest.Meanwhile, Nick and Sara investigate a not-so-amicable divorce with a bizarre twist. So bizarre it eventually lead to murder when both are found dead and it looks like the dog killed one of them.', 43, '2005-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 10, 'Still Life', 'The CSI''s are called out to investigate the disappearance of a boy whose father died four years ago. Soon a couple is arrested at a convenience store with a boy matching the description of the missing kid. The only problem is they both claim it is their son.  Both parents have exactly the same picture of the boy, with a scar on exactly the same place on his face. They hope a DNA-test could confirm who the real parents are, but when this information comes to light, it lead to another bizarre twist, possibly murder.', 44, '2005-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 11, 'Werewolves', 'The CSI team investigates the murder of a man suffering from a congenital hypertrichosis, causing him to grow excessive body hair.  Elements of the case suggest a connection with a belief in werewolves. The case leads to the victim''s sister, who suffers from the same disease.  Because of her condition, she''d been hiding from the world, but it turns out that she''s hiding facts that are vital to solving the case.', 45, '2006-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 12, 'Daddy''s Little Girl', 'The CSIs investigate the stabbing of a motocross racer who was about to leave town with a young woman he had been living with.  Also, Nick comes closer to finding the truth about his kidnapping.', 45, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 13, 'Kiss-Kiss, Bye-Bye', 'The CSIs crash an elegant party for the city''s crème of the crème to discover who killed a young man.  The case gets a bit more personal for Catherine when her father, Sam Braun, is one of the suspects.', 45, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 14, 'Killer', 'The CSIs must investigate when a party girl is injured and killed in a traffic accident.', 44, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 15, 'Pirates of the Third Reich', 'The CSIs investigate the gruesome murder of Lady Heather''s estranged daughter, Zoe, who was found in the middle of the Vegas desert.', 44, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 16, 'Up In Smoke', 'The investigation into a body found in a chimney leads the CSIs to re-open an investigation of an unsolved homicide of a female teenager named Caroline Fitzgibbons.', 42, '2006-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 17, 'I Like To Watch', 'The CSIs become the focus of a reality TV series, which follows them while they investigate a serial rapist, who recently gained access to a woman''s apartment by posing as a fireman.  Also, Warrick''s work on the late-shift is causing problems with his marriage to Tina.', 43, '2006-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 18, 'The Unusual Suspect', 'When a student is arrested and tried for the murder of a popular high-school girl, the suspect''s 12-year-old sister confesses to the crime.  This results in the judge giving the prosecution 72 hours to re-examine the evidence before the jury delivers its verdict.', 44, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 19, 'Spellbound', 'The team investigates the death of a psychic who "saw" her own death while performing a reading for two other women.  Greg reveals a family secret to Grissom but Grissom believes that science will be what solves the case.', 45, '2006-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 20, 'Poppin'' Tags', 'The CSI team is lead into the rap music world as they investigate the murders of three rival teen rappers.', 43, '2006-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 21, 'Rashomama', 'A wealthy defense attorney is killed at her son’s wedding but Nick’s car, containing all the collected evidence is stolen and the case is compromised. After discovering new evidence, the team suspects that someone from the wedding party may be responsible for the murder.', 45, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 22, 'Time Of Your Death', 'A high roller who spent the night with a woman he had just met is found dead on the loading dock of the casino where he was staying. The investigation reveals that the victim won $10,000 in a pool game and was an assistant to a respected movie producer.', 42, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 23, 'Bang-Bang (1)', 'A man accused of murdering his wife and co-workers leads the CSIs on a wild ride through a busy casino, eventually barricading himself and a hostage in a casino hotel room.  The CSIs process the evidence from the crime scene to determine whether or not the man acted alone or had an accomplice.  One of the CSIs eventually steps in as a hostage negotiator, putting himself in danger.', 42, '2006-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 6), 24, 'Way To Go (2)', 'In the season finale, the CSIs wait by the bedside of one of their own when he''s shot in the line of duty.  One CSI faces a hard choice by having the power of attorney over their injured friend and colleague.  Meanwhile, the team also investigates the strange way of life of one man when he is found decapitated by a train.', 44, '2006-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 1, 'Built To Kill (1)', 'In part one of this two-part seventh season opener Grissom and Catherine handle the case of a women''s dead body found at Cirque du Soleil by a performer. Meanwhile, an investor at one of Sam Braun''s new casinos is shot to death during a party on the rooftop. Catherine''s life is in jeopardy after visiting a nightclub with Nick. Grissom finds a miniature replica of a crime scene that he is investigating.', 44, '2006-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 2, 'Built To Kill (2)', 'In the second part of this two-parter Grissom investigates the murder of an aging rockstar who is found dead in his kitchen with an exact replica of the crime scene on the counter next to him. Meanwhile, Catherine probes her own abduction and learns that someone may be targeting her family.', 45, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 3, 'Toe Tags', 'Coming straight from the perspectives of five people: Donna, Rebecca, Jack, Lou and Ray. All with one thing in common. They’re all dead. Brass and Catherine get to handle the case of Donna, who’s a cop from San Francisco, moonlighting as a bodyguard. Warrick and Greg work the case of Rebecca, who’s a former supermodel who died while hiking with her new husband Gavin. Nick and Sofia handle the case of Jack, a returning veteran from Iraq, who was killed in front of his wife and baby daughter who he just met for the first time. Grissom and Sara take the case of Lou and Ray whose bodies were found in Lou’s garage.', 43, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 4, 'Fannysmackin''', 'Three tourists are beat up, badly. One is dead, Alfonzo. Jessica is badly beaten but is still alive. Stanley, the last tourist is saved by Greg who ends up severely hurt in turn and ends up hospitalized after having to make a life altering decision.', 44, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 5, 'Double-Cross', 'Grissom and Sara may be secret lovers, but they still find ways to surprise each other like when their religious beliefs surface when two nuns find a body of a woman crucified on a makeshift cross. The woman was found in a church where the priest may be a man of sin instead of a man of God.', 44, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 6, 'Burn Out', 'Grissom attempts to get a confession from a neighborhood pedophile by having him help in locating two missing boys.  The sex offender is the main suspect.  The investigation is more complex than the team ever thought it would be.', 45, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 7, 'Post Mortem', 'While investigating an elderly woman''s murder, Grissom receives a miniature crime scene replica; Greg attends a hearing to ascertain his culpability in a teenager''s accidental death.', 45, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 8, 'Happenstance', 'Identical twins are found murdered on the same night.  The CSI’s investigate the two separate murders only to find a twist in the investigation find that leads them in another new direction.', 44, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 9, 'Living Legend', 'The Cadillac of an infamous 1970’s mob boss turns up in a lake, even though he disappeared years ago. A photo of current murder victims also turns up in the car, so the team must determine whether this current murder spree is related to the missing gangster.', 43, '2006-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 10, 'Loco Motives', 'Grissom investigates when a worker at a poultry processing plant is found dead in a stun bath used to electrocute chickens before they are slaughtered. Nearby, a miniature replica of the crime scene is discovered. It''s eerily similar to two other replicas left at scenes of homicides. Also, a man and a dead woman are found stuck in cement at a construction site; and an elderly Russian woman is discovered dead in her apartment with her head in a gas stove, but Warrick thinks she was murdered.', 45, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 11, 'Leaving Las Vegas', 'Catherine testifies in a murder trial in which a man is accused of murdering his own mother three years ago, but the suspect is found not guilty. Catherine, however, believes he did commit the crime and that he may also have killed two other people, so she sets out to find the other victims. Grissom prepares to leave on a four-week sabbatical.', 45, '2007-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 12, 'Sweet Jane', 'The team has a hard time trying to understand Michael who has become a team member since Grissom’s teaching hiatus.  They investigate the murder of an unidentified girl who may have been killed by a serial killer who has been killing since the early 1970’s.', 45, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 13, 'Redrum', 'At Keppler''s request Catherine uses a different approach to catch the killer, and in doing so she deceives the rest of the CSI team.  The team soon discovers that something is amiss in Catherine’s investigation.', 45, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 14, 'Meet Market', 'Nick and Keppler investigate the bizarre world of the black market sales of body parts after they find a body that has been burned and the organs removed.  The rest of the CSI team investigates the death of rich woman who was killed in her own home.', 44, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 15, 'Law of Gravity', 'Grissom returns from his sabbatical; Keppler is put into a compromising position when the bodies of a Trenton police officer and a hooker are found in a hotel room. The man who found them is a retired New Jersey cop and close friend to Keppler, who doesn''t reveal their relationship.', 44, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 16, 'Monster in the Box', 'Once he unseals a package sent to him through the mail, Grissom is floored when he finds a miniature crime scene inside. The finding is entirely more perplexing since the successive killer accountable for earlier related miniature crimes is now deceased. Grissom plows to examine the miniature and discover the actual location, when the investigation makes it clear the murder showed has yet to happen, but is probably going to happen soon.', 44, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 17, 'Fallen Idols', 'Grissom and his team are discouraged when they find a pool of blood as they begin investigating the disappearance of a high school basketball star and his cheerleader girlfriend.Grissom''s quip that the young lovers may have run off to Mexico is soon quashed by the discovery of drops of blood by Ryan''s vacant parking spot at the school. After finding a letterman jacket and cheerleading sweater in the field house and a pool of Ryan''s blood nearby, the team tries to determine what went awry.', 45, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 18, 'Empty Eyes', 'The terrified eyes and cryptic words of a murder victim haunt Sara while she processes the house where several showgirls were killed.', 43, '2007-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 19, 'Big Shots', 'After a man is killed in his limousine, Greg finds that the murder victim has ties to the man he had to kill in self-defense.  The team finds that the brother is involved in this investigation and has to deal with him and his hostile mother.', 42, '2007-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 20, 'Lab Rats', 'The CSI labrats take center stage to discuss the case of the Miniature Killer.', 44, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 21, 'Ending Happy', 'When a has-been boxer is killed, the CSIs must establish which of several life-threatening acts actually killed him.', 45, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 22, 'Leapin'' Lizards', 'Several suspects in a murder case are UFO-club members who believe shape-shifting aliens have been working to conquer the human race for centuries', 44, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 23, 'The Good, the Bad, and the Dominatrix', 'Grissom investigates when a sadistic client tries to murder Lady Heather (Melinda Clarke), who makes the probe more difficult when she refuses to name her attacker. Also, Grissom''s reunion with Lady Heather makes Sara uneasy.', 44, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 7), 24, 'Living Doll', 'As the CSI''s continue their search for and discover the identity of the "Miniature Killer", Grissom and Sara''s relationship gets exposed to the rest of the team as she goes missing during the investigation. The "Miniature Killer" is finally captured, but not before a member of CSI becomes the killer''s final victim.', 44, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 1, 'Dead Doll', 'With time, the weather, and the desert against them, the CSI team must work together to find Sara before she dies from the miniature killer''s attack.', 44, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 2, 'A La Cart', 'The CSI team investigates two unusual cases, one involving the suspicious death of a go-cart racer who took his hobby to the highway and paid the price with his life, and a murder at a hip new restaurant where patrons dine in the dark', 45, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 3, 'Go To Hell', 'The team investigates a girl whose whole family had been killed and she is supposedly possessed by the devil.', 44, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 4, 'The Case of the Cross-Dressing Carp', 'Grissom investigates the mysterious hanging death of a young man whose body looks like that of a female.', 44, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 5, 'The Chick Chop Flick Shop', 'Grissom and his team investigate when an actress is killed on the set of a horror porn film.', 42, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 6, 'Who and What (I)', 'Grissom and the team join forces with Jack Malone, an FBI Agent from New York to track a serial killer.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 7, 'Goodbye and Good Luck', 'Sara questions her future as a CSI when a past case comes back to haunt her, the 12 year old Hannah, who has to back up her brother one more time with all new tricks up her sleeves.', 44, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 8, 'You Kill Me', 'Hodges stages hypothetical murders in the lab in order to give his fellow lab techs a chance to play CSI, but unbenownst to them he has other motives behind his actions.  Meanwhile, after Sara''s farewell, everyone tries to comfort Grissom.', 44, '2007-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 9, 'Cockroaches', 'The team investigates an underground mob.  Warrick ends up becoming the prime suspect in a murder that''s related to the mob, and his addiction to pills starts to have a significant impact on his job as a CSI.', 44, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 10, 'Lying Down with Dogs', 'The world of illegal dog fighting is explored by Grissom and the rest of the team when they take on the case of a wealthy socialite who was murdered.  Meanwhile, Warrick struggles to clear his name in the recent exotic dancer murder case.', 42, '2007-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 11, 'Bull', 'Two murders that happen during Las Vegas'' annual bull riding rodeo are investigated by the CSIs, who find that the murders might be connected to illegal bull breeding.', 42, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 12, 'Grissom''s Divine Comedy', 'Grissom and his team battle the flu when they are called upon by D.D.A. Klein to investigate the deaths of several key witnesses for a grand jury case against a dangerous Las Vegas gang.', 44, '2008-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 13, 'A Thousand Days on Earth', 'CSI investigates the death of a little girl whose identity remains unknown.', 44, '2008-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 14, 'Drops Out', 'Brass, Catherine, Grissom and Nick work the case of a female victim found in an apartment building with a gun shot wound. Drops becomes a person of interest during the investigation, even though he is still in jail.', 43, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 15, 'The Theory of Everything', 'A deer is illegally killed, and the person found with the body in the back of his truck apparently dressed it in a tutu. The man, who was completely drunk when arrested, was being interrogated by Nick and Brass, and suddently tries to escape and is pepper sprayed. Unfazed by the spray, officers then taser him and he bursts into flames and dies. Meanwhile an unbalanced woman wearing a tinfoil outfit at the front desk tries to warn people (including Nick) of an alien invasion. After observing the burning man, she later turns up dead with green-tinted blood. When other people turn up with the same problem, it''s up to the team to figure out why. Meanwhile, an old couple dies, apparently in their sleep... but there is evidence the cases are related.', 43, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 16, 'Two and a Half Deaths', 'Grissom, Catherine, Nick, Greg and Brass are investigating the death of a well known TV star called Annabelle.', 42, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 8), 17, 'For Gedda', 'Catherine comforts Warrick when he is accused of murdering a famous Vegas gangster and even he is uncertain of his guilt or innocence.', 45, '2008-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 9), 1, 'For Warrick', 'After Warrick is shot in a Las Vegas alley, the CSI team comes together to deal with the aftermath.', 45, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 9), 2, 'The Happy Place', 'A hypnotist bank robber becomes the prime suspect in a murder investigation.', 44, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 9), 3, 'Art Imitates Life', 'After several victims are found dead while performing normal, everyday activities, the CSIs must find the reason as to why each of the victims remain upright after dying.', 45, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 9), 4, 'Let It Bleed', 'The team investigates the death of a woman who turns out to be the daughter of a wanted criminal.', 44, '2008-10-30');
