INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0247082')) AND numero_temporada = 15), 13, 'The Greater Good', 'The CSI team continues their investigation into the kidnappings and murders of young women when they learn their main suspect, Jared Briscoe, is released from jail due to lack of evidence.', 44, '2015-01-04');
