INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0262150', 'Black Books', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0219513'), 'SERIE', 'Bernard Black runs a book shop, though his customer service skills leave something to be desired. He hires Manny as an employee. Fran runs the shop next door. Between the three of them many adventures ensue.', '2000-01-01', 'https://m.media-amazon.com/images/M/MV5BOTIwNjJhYmMtMGNmNS00YTJkLTgwY2ItNDdkN2Y2MDg4YWRjXkEyXkFqcGc@._V1_.jpg');
