INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')), 1, 'Season 1', 'Meet Bernard Black, a foul tempered and eccentric bookshop owner who loves his books but hates his customers. Manny is Bernard''s long-suffering assistant and Fran is the owner of the gift shop next door to Black Books. Black Books explores Manny and Fran''s efforts to ensure Bernard has some contact with the outside world and charts the comical consequences of their efforts.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 1), 1, 'Cooking the Books', 'Bernard’s dodgy accountant has to go on the run, leaving him ill prepared to fill out his own tax return. In fact Bernard would rather do anything than fill it out.', 22, '2000-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 1), 2, 'Manny''s First Day', 'After Manny’s help with the tax return Bernard is persuaded to hire him in the shop. Unfortunately he actually sells some books, much to Bernard’s annoyance.', 23, '2000-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 1), 3, 'Grapes of Wrath', 'Bernard and Manny accept a house-sitting job to get away from their new cleaner. They also drink some wine.', 24, '2000-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 1), 4, 'The Blackout', 'A hyper, coffee fueled Manny is mistaken for a policeman.', 24, '2000-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 1), 5, 'The Big Lock-Out', 'The shop gets a new security system that no-one can work.', 24, '2000-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 1), 6, 'He''s Leaving Home', 'Manny runs away from the bookshop into the arms of a beard loving photographer.', 24, '2000-11-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')), 2, 'Season 2', 'In season two, Bernard is convinced the Manny is mad; Manny worries about the reliability of his magic hot water bottle and uses his underworld connections to help find Fran a job. Fran struggles to find her inner karma in-between trying to find her cigarettes and making excuses to have another drink. Under the constant threat from the nasty, unfeeling outside world, Bernard, Manny and Fran attempt to maintain the heaven of the bookshop even as their own relentless stupidity pushes them towards mayhem.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 2), 1, 'The Entertainer', 'Fran decides to take up piano lessons with a very prominent teacher, however all doesn''t go to plan and she ends up having to ask Manni for a favour. Meanwhile Bernard asks a girl out and once again Manni is called upon for a favour.', 24, '2002-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 2), 2, 'Fever', 'On a scorching hot day, Manni tries to maintain his body temperature so it doesn''t go over 88 degrees; Fran has problems with a new neighbour, and Bernard tries to find an appropriate "summer girl".', 24, '2002-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 2), 3, 'The Fixer', 'Bernard and Manni have to deal with a gangster turned writer who plans to hold a reading of his autobiography at the book shop, however he can''t read. Meanwhile Fran gets an office job where she isn''t quite sure what she is meant to be doing.', 23, '2002-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 2), 4, 'Blood', 'Manni and Bernard try to keep up with modern book shops and in doing so Manni helps Fran get over her boredom by encouraging her to look up her family tree.', 23, '2002-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 2), 5, 'Hello Sun', 'Fran tries to cleanse her lifestyle by taking up yoga and going on a radical diet, while Bernard and Manni receive some books on Freud and their lives descend into his famous theories.', 24, '2002-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 2), 6, 'A Nice Change', 'When construction starts next door to the shop, Manni, Bernard and Fran try to decide what to do while it continues.', 24, '2002-04-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')), 3, 'Season 3', 'Bernard Black is back for a third season of his multi-award winning and critically acclaimed comedy. Black Books continues to explore the musing and time-wasting techniques of raddled proprietor Bernard Black, his shy, multi-challenged assistant Manny Bianco and their underachieving friend Fran Katzenjammer.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 3), 1, 'Manny Come Home', 'When Manny defects to Goliath Books after an "incident" with Bernard, his ex-employer''s life spirals out of control. Meanwhile Fran returns from holiday only to be greeted by the squalor of Bernard''s shop.', 25, '2004-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 3), 2, 'Elephants and Hens', 'When Bernard holds a children''s themed book day in the shop, Fran bets Manni and Bernard they couldn''t write a children''s book over a weekend, while Bernard bets Fran back that she will have an awful time at her friend''s hen party.', 23, '2004-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 3), 3, 'Moo-Ma and Moo-Pa', 'Manny''s parents visit the shop for the weekend, and the lies he''s told them throw Fran and Bernard''s lives into chaos.', 24, '2004-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 3), 4, 'A Little Flutter', 'Bernard becomes addicted to gambling and forces Manny and Fran to compete for one job at the shop in order to finance his bets.', 24, '2004-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 3), 5, 'Travel Writer', 'Fran & Manny become enamored with a dashing travel writer giving a talk at the shop, while Bernard contends with a most unorthodox new landlord.', 24, '2004-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0262150')) AND numero_temporada = 3), 6, 'Party', 'Manny and Fran drag Bernard along with them to a party, but the drunken aftermath dredges up secrets and bitterness.', 24, '2004-04-15');
