INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')), 1, 'Season 1', 'Larry David has it all—money, security, famous friends, a nurturing wife, a fabulous Hollywood home. So why is he so intent on making a complete mess out of his life? Just because you''ve made it, doesn''t mean you''ve got it made.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 1, 'The Pants Tent', 'An innocent bunch-up in Larry''s trousers gives rise to an embarrassing situation.', 29, '2000-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 2, 'Ted and Mary', 'Larry and Cheryl''s fun-filled bowling date with Ted Danson and Mary Steenburgen ends with Larry''s shoes missing.', 29, '2000-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 3, 'Porno Gil', 'Larry sets off a bizarre chain of events (as he always seems to do) in which he is forced to attend a party at the home of a porno businessman.', 29, '2000-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 4, 'The Bracelet', 'Larry is continually thwarted in his effort to buy a bracelet as a peacemaking gift for Cheryl.', 28, '2000-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 5, 'Interior Decorator', 'Larry has some medical problems involving a certain bracelet. No biggy. Then larger problems arise when Larry finds out he shares the same interior decorator as Diane Keaton.', 29, '2000-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 6, 'The Wire', 'Hoping to bury an unsightly telephone wire dangling over their yard, Larry and Cheryl befriend a pair of bizarre neighbors who must approve the burial. The husband is an incompetent lawyer but a big Seinfeld fan, so to appease him Larry arranges to have Julia Louis-Dreyfuss come for a visit. But when the actress arrives, the lawyer is missing; he''s been hired to defend Jeff in a case involving a destructive kid Jeff sponsored for a Fresh Air Fund camp. At Larry''s house, Julia ends up buying a bracelet from the lawyer''s wife -- the same kind Larry wanted in episode 4 -- only to later accuse Larry of stealing it after he buys a similar one for Cheryl.', 30, '2000-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 7, 'AAMCO', 'Jeff gets a new car, and when Larry takes it for a spin, a commercial comes on the radio for AAMCO, with a noise sounding much like a car horn from behind. Upon hearing this, Larry curses the man behind him, prompting the man to rear-end Jeff''s brand new car. Also, Larry and Cheryl hold a dinner party.', 27, '2000-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 8, 'Beloved Aunt', 'When Cheryl''s aunt dies, Larry is left in charge of the obituary. But when the newspaper accidentally places ""beloved c*nt"" instead of beloved aunt, things take an expected turn for the worse.', 30, '2000-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 9, 'Affirmative Action', 'Larry gets himself in trouble, when he makes a racist-like comment to Richard''s friend. Also, Larry inadvertently loses Cheryl''s prescription note.', 30, '2000-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 1), 10, 'The Group', 'Larry runs into his old girlfriend, and she asks him to escort her to an incest-survivors meeting. Cheryl is asked to co-star in ""The Vagina Monologues"" when one of the actresses is sick.', 31, '2000-12-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')), 2, 'Season 2', 'Larry David is still himself—much to the chagrin of everyone around him. From cutting a doll''s hair to answering the door on Halloween to tripping a basketball legend, for every action of Larry''s, there''s an opposite and disproportionately outraged reaction.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 1, 'The Car Salesman', 'Larry David and his wife purchase a new oceanfront home owned by a television star''s agent. Meanwhile, Larry shocks his wife and friends by deciding to take a job as a car salesman.', 30, '2001-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 2, 'Thor', 'Jeff leaves his wife Susie, and worries that his private life will become public in court. Jeff''s concern affects Larry, who becomes obsessed with showing Cheryl how normal he is. Meanwhile, Larry seeks revenge on pro wrestler Thor Olson, who he believes slashed his tire after an argument on the road.', 28, '2001-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 3, 'Trick or Treat', 'Larry offends two uncostumed trick-or-treaters by not giving them candy, so they show him the "trick" side of Halloween. He also alienates Cheryl''s screenwriter friend Cliff and a Jewish neighbor AND spoils his romantic anniversary gift when Jeff arrives to play a round of golf.', 30, '2001-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 4, 'The Shrimp Incident', 'Larry is labeled a misogynist when he believes an HBO Network executive took some shrimp from of his meal, following a mistake in a delivery of Chinese food.', 29, '2001-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 5, 'The Thong', 'Larry and Richard Lewis, who both see the same psychotherapist, plot ways of ending their respective relationships with the therapist after Larry sees the man wearing a thong bathing suit.', 28, '2001-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 6, 'The Acupuncturist', 'Larry promises to pay an acupuncturist $5,000 if he can cure his neck. Meanwhile, a struggling writer asks Larry for a $5,000 loan which he promises to pay back after his father dies.', 30, '2001-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 7, 'The Doll', 'At the screening of a miniseries, the young daughter of a TV executive asks Larry to cut the hair off a beloved doll. When he complies, she becomes very upset. To remedy the situation, Larry and Jeff steal the head from Jeff''s daughter''s doll.', 30, '2001-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 8, 'Shaq', 'Larry is villainized for accidentally tripping Shaquille O''Neal at a Lakers game, but the incident ironically ends up bringing him good luck.', 30, '2001-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 9, 'The Baptism', 'Larry can''t believe that the Jewish man who is marrying Cheryl''s sister is converting to Christianity. Richard Lewis accused Larry of stealing the outgoing message of his answering machine, and Larry accuses several passengers of stealing his airline tickets.', 30, '2001-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 2), 10, 'The Massage', 'Cheryl''s psychic busts Larry for a naughty massage, and a restaurant owner busts Larry for stealing forks.', 30, '2001-11-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')), 3, 'Season 3', 'Larry and his manager Jeff''s investment in a restaurant leads to laughs when it comes to settling on a chef. Meanwhile, Larry gets into his usual assortment of problems—this time involving Christmas tipping, a manger scene, cell phone miscommunication, the ''nanny from hell,'' betraying the confidence of rapper Krazee-Eyez Killa, committing a ''penis faux pas,'' and even using his mother''s death to escape some unsavory invitations.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 1, 'Chet''s Shirt', 'While comforting a friend whose husband passed away, Larry and Cheryl comment on the husband''s shirt. Larry then goes to the department store the next day to buy it. Meanwhile, Jeff talks Larry into investing in a trendy new celebrity restaurant. Larry also gets into trouble when he throws away some trash in a random garbage can.', 30, '2002-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 2, 'The Benadryl Brownie', 'Thanks to Larry''s miscommunication on his new cell phone, Richard Lewis'' girlfriend succumbs to peanut allergies a week before they''re supposed to go to the Emmy Awards. A practicing Christian Scientist, she doesn''t take any medicine, so Richard and Larry devise a scheme to cook up some brownies laced with medicine. Like all things Larry does, the plan backfires.', 30, '2002-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 3, 'Club Soda and Salt', 'Larry, Jeff, and Ted scramble to find a chef for the new restaurant, but Larry doesn''t like Ted''s recommendation. While trying to find a replacement, Larry learns a few things - Cheryl has a new, male, tennis playing friend, people won''t take a wedding gift after a year, and that club soda and salt will get stains out of anything.', 30, '2002-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 4, 'The Nanny from Hell', 'Larry, Cheryl, Jeff and Susie encounter a ""nanny from hell"" whose reign of terror is thwarted by ten sponge cakes. Larry commits a ""penis faux pas"" after a pool party, and Richard Lewis seeks immortality from Bartlett''s Quotations.', 30, '2002-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 5, 'The Terrorist Attack', 'A rumored threat of a terrorist attack undermines a benefit performance by Alanis Morissette at the home of one of Larry''s friends. Meanwhile, Larry can''t help snubbing Mindy Reiser, wife of actor Paul Reiser, during a series of encounters at a restaurant and the perfume shop where she works.', 30, '2002-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 6, 'The Special Section', 'Larry''s mother dies while he''s shooting a film in New York City, but he doesn''t find out until he returns to Los Angeles two days after the funeral. Once he''s past the initial shock, Larry uses his loss as an excuse to avoid a number of unsavory invitations. Meanwhile, Richard Lewis accuses Larry of taking back his meditation mantra, and Larry plots to relocate his mother''s body at the cemetery.', 30, '2002-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 7, 'The Corpse-Sniffing Dog', 'Over a makeup dinner with the Braudys, Larry openly ponders the question, ""When a husband pays the check, do you have to also thank the wife?"" Meanwhile, Jeff''s return home is ruined by his allergy to the family''s corpse-sniffing German Shepherdâ€”but his daughter Sammy refuses to give away the dog. Concerned about his agent''s welfare, Larry figures out an ingenious way to give the pooch to the Braudys, who are looking for just such a dog.', 29, '2002-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 8, 'Krazee-Eyez Killa', 'Larry is accused of betraying the confidences of Wanda''s boyfriend, Crazy-Eyez Killa, a rapper he met at a party. Later, Larry alienates Jeff''s wife Susie by declining her house-tour offer. He encounters further problems when he tries to replace a sports jacket Cheryl threw out.', 30, '2002-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 9, 'Mary, Joseph and Larry', 'Larry proves himself an unskilled Christmas tipper, while both Larry and Jeff prove incompetent at creating believable alibis for the messes they get in. After offending his housekeeper, Larry makes amends with her at the expense of his wife. Later, Larry attempts to reconcile with Cheryl''s family after ruining their nativity scene.', 31, '2002-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 3), 10, 'The Grand Opening', 'Larry figures out a way to fire a chef, and alienate an important restaurant critic, in the days before his new restaurant is scheduled to open. As Susie stews over a misunderstanding with Larry and Cheryl, the Davids spend some quality time at the car wash. With its grand opening at hand, the restaurant owners hire a new chef with a penchant for speaking his mind.', 30, '2002-11-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')), 4, 'Season 4', 'Larry brings his many quirks and neuroses to the stage after he is cast in a major Broadway production. Meanwhile, as their 10th anniversary approaches, Larry reminds Cheryl of a special ''present'' she promised him when they were engaged.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 4), 1, 'Mel''s Offer', 'After going to a Karaoke bar that Mel Brooks is performing at, Mel is so impressed with Larry''s singing that he asks Larry to be the star of his broadway show.', 30, '2004-01-04');
