INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 4), 10, 'Opening Night', 'The show travels to New York City as Larry prepares to open on Broadway in "The Producers".', 59, '2004-03-14');
