INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 7), 10, 'Seinfeld', 'Not tipping for a favor gets Larry into bad graces with the studio lot''s coffee guy, while Julia Louis-Dreyfus accuses him of leaving a ring on an antique table in her house. Meanwhile, he deals with the suspicion that their closeness during production of the Seinfeld reunion has led to Cheryl sleeping with Jason Alexander.', 42, '2009-11-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')), 8, 'Season 8', 'As "Single Larry" continues to navigate the L.A. dating scene, a faulty alibi lands him back in his hometown of New York City for an extended stay—where he proves that faux-pas and character assassinations can occur just as easily in the Big Apple as in Hollywood.');
