INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 12), 8, 'The Colostomy Bag', 'When Richard enlists Larry''s help to buy a vintage car, his careless behavior leads to an unwanted outcome. Jeff secretly schemes to give Larry power of attorney.', 32, '2024-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 12), 9, 'Ken/Kendra', 'A misunderstanding with Cheryl''s masseuse threatens Larry''s image. Then, public perception of Larry sinks even lower when he gives the wrong person COVID.', 35, '2024-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0264235')) AND numero_temporada = 12), 10, 'No Lessons Learned', 'Larry returns to Atlanta, where he gets involved in Richard''s love life and reveals a secret about Cheryl.', 53, '2024-04-07');
