INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 1, 'Secret Origins', 'Batman and Superman team up to deal with an alien invasion, and a telepathic message leads the duo to a military base housing future ally J''onn J''onzz.', 72, '2001-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 2, 'In Blackest Night (1)', 'No man escapes the Manhunters.'' An alien court sends the Manhunters to bring Green Lantern back for prosecution on the charge of genocide, and the League gets involved.', 24, '2001-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 3, 'In Blackest Night (2)', 'Believing that Green Lantern is receiving an unfair trial, the Leaguers investigate, while GL''s superiors, the Guardians of the Universe, enter as witnesses. But the whole trial may be a ruse.', 24, '2001-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 4, 'The Enemy Below (1)', 'When Aquaman, ruler of Atlantis, decides he has had enough of the surface-dwellers trespassing in his ocean, the Justice League tries to smooth things over. Aquaman takes Superman''s advice and arrives in New York City to speak to the World Assembly, but it soon becomes apparent that he may have been right about the surface-dwellers all along.', 24, '2001-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 5, 'The Enemy Below (2)', 'Betrayed by his own subjects, Aquaman and the League fight to save Atlantis, the world, and Aquaman''s own son against his half-brother Orm''s coup.', 24, '2001-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 6, 'Paradise Lost (1)', 'Wonder Woman returns to Paradise Island to make up with her mother for her rapid departure, only to find the Amazons transformed to statutes. The sorcerer Felix Faust is holding them hostage to force Diana to recover three ancient artifacts.', 24, '2002-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 7, 'Paradise Lost (2)', 'The League fight to save Paradise Island and Wonder Woman''s own mother from Felix Faust and Lord Hades.', 24, '2002-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 8, 'War World (1)', 'Superman and J''onn are taken prisoner during a rescue mission gone bad, and Superman is forced to compete in a gladiatorial tournament on a distant world while Hawkgirl and Green Lantern try to rescue them.', 24, '2002-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 9, 'War World (2)', 'Fight promoter and new contestant Mongul instructs Superman to throw the fight against him, or he''ll destroy the enslaved Draaga''s home planet.', 24, '2002-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 10, 'The Brave and the Bold (1)', 'When the Flash is mind-controlled into committing a crime, he and Green Lantern work to clear his name and uncover a sinister scheme.', 24, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 11, 'The Brave and the Bold (2)', 'When Gorilla Grodd mentally enslaves a city of humans and prepares to destroy Gorilla City, Green Lantern and Flash try to defeat him while the other Leaguers move to help the ape civilization.', 24, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 12, 'Fury (1)', 'A renegade Amazon, Aresia, leads a new incarnation of the Injustice Gang to accumulate the components for a bio-weapon.', 24, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 13, 'Fury (2)', 'When the male Leaguers are infected by the same disease sweeping Earth, Wonder Woman and Hawkgirl must defeat Aresia and find a cure.', 24, '2002-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 14, 'Legends (1)', 'An explosion throws four Leaguers into an alternate dimension where they meet their childhood comic book heroes...the Justice Guild!', 24, '2002-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 15, 'Legends (2)', 'The League aid the Justice Guild against their arch-nemeses while trying to unravel the secrets of the Guild''s world.', 24, '2002-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 16, 'Injustice for All (1)', 'Exposed as a criminal, sentenced to prison, and terminally ill due to long term kryptonite exposure, Lex Luthor escapes and assembles a supervillain team consisting of Cheetah, The Shade, Solomon Grundy, Star Sapphire, Copperhead, and Ultra-Humanite to take on the Justice League, calling themselves the Injustice Gang. The Joker also becomes part of the team, but on his own choice. However, this gang proves short-lived as its major weakness proves no match for Batman''s wiles.', 24, '2002-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 17, 'Injustice for All (2)', 'Exposed as a criminal, sentenced to prison, and terminally ill due to long term kryptonite exposure, Lex Luthor escapes and assembles a supervillain team consisting of Cheetah, The Shade, Solomon Grundy, Star Sapphire, Copperhead, and Ultra-Humanite to take on the Justice League, calling themselves the Injustice Gang. The Joker also becomes part of the team, but on his own choice. However, this gang proves short-lived as its major weakness proves no match for Batman''s wiles.', 24, '2002-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 18, 'A Knight of Shadows (1)', 'The sorceress Morgaine Le Fey and her son Mordred search for the Philosopher''s Stone, and the Justice League need the help of the Demon Etrigan to thwart her.', 24, '2002-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 19, 'A Knight of Shadows (2)', 'Morgaine and Mordred get the Stone and plan to transform England and restore it to its medieval glory.', 24, '2002-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 20, 'Metamorphosis (1)', 'An old friend of John Stewart''s is inadvertently turned into a freak capable of altering his molecular structure, separating him from his girlfriend and pitting him against the League.', 24, '2002-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 21, 'Metamorphosis (2)', 'The League battle Metamorpho but soon discover that his future father-in-law, Simon Stagg, poses the true menace.', 24, '2002-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 22, 'The Savage Time (1)', 'When the present is altered, the Justice League must travel back in time to World War II to restore history.', 24, '2002-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 23, 'The Savage Time (2)', 'A separate League struggle against the Nazis and determine who is responsible for the Axis'' technological advances.', 24, '2002-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 1), 24, 'The Savage Time (3)', 'Wonder Woman and Steve Trevor survive the attack and trick the Germans into believing that the communicator was destroyed. GL and Easy Co. find the runaway and discover that Vandal Savage plans to use jet aircraft to invade America. GL boards and tries to stop Vandal''s plane while Hawkgirl, Superman, and Flash try to intercept the flight with J''onn''s help. With the aid of the Blackhawks and Flash notifying the U.S. Navy, the German flight is shot down and Vandal apparently is killed. The JLA return to the present to find everything restored and Wonder Woman visits a now elderly Steve Trevor in the restored present.', 24, '2002-11-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 1, 'Twilight (1)', 'The Justice League is forced to ally with Darkseid against an enemy powerful enough to threaten both Earth and Apokolips.', 24, '2003-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 2, 'Twilight (2)', 'The League are forced to battle both Darkseid and Brainiac, while Wonder Woman and Batman seek the aid of Orion, son of Darkseid.', 24, '2003-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 3, 'Tabula Rasa (1)', 'Lex Luthor, on the run from the League, reactivates an old LexCorp project to stop the League - an android that can duplicate the powers of anyone it sees.', 24, '2003-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 4, 'Tabula Rasa (2)', 'Even Superman is unable to defeat the android once it duplicates all of the League''s powers. Only with the aid of J''onn, suffering a crisis of faith when he is overwhelmed by humanity''s pettiness during a telepathic scan, can they turn Amazo against Lex.', 24, '2003-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 5, 'Only a Dream (1)', 'The Justice League must deal with a prison break, unaware that prisoner John Dee is using the distraction to gain access to an experimental ESP machine and gain the power to manipulate dreams.', 24, '2003-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 6, 'Only a Dream (2)', 'Four of the Leaguers are trapped in their dreams by Dr. Destiny - only J''onn and Batman can rescue them...if they don''t fall asleep first.', 24, '2003-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 7, 'Maid of Honor (1)', 'Batman and Wonder Woman find themselves enmeshed in the schemes of Vandal Savage to take over the small country of Kasnia and use its space program to blackmail the world.', 24, '2003-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 8, 'Maid of Honor (2)', 'Batman and Wonder Woman move against Kasnia to prevent Vandal Savage from terrorizing the world with his orbital rail gun.', 24, '2003-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 9, 'Hearts and Minds (1)', 'John Stewart leaves on a mission to help his fellow Green Lanterns overthrow a intergalactic dictator with strange powers.', 24, '2003-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 10, 'Hearts and Minds (2)', 'Despero''s followers attack and John is forced to use a gun when his ring becomes useless due to Despero''s mental tampering. While John, Katma, and Hawkgirl are captured, J''onn, Kilowog, and Flash must try to deactivate the mystic flames and deprive Despero of his power.', 24, '2003-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 11, 'A Better World (1)', 'The Justice Lords, an alternate version of the League from a different dimension, capture their counterparts and plan to bring their own brand of justice to the new Earth.', 24, '2003-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 12, 'A Better World (2)', 'The Justice League must escape from their imprisonment at the hands of the Justice Lords and defeat their counterparts with the help of an unlikely ally.', 24, '2003-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 13, 'Eclipsed (1)', 'A strange gemstone possesses all who touch it, turning them to evil...including Wonder Woman.', 24, '2003-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 14, 'Eclipsed (2)', 'The League discover the secret behind the "Black Heart" gem, but everyone except the Flash is possessed, and he must save the day before the sun is destroyed.', 24, '2003-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 15, 'The Terror Beyond (1)', 'After Aquaman frees Solomon Grundy, Hawkgirl and the Justice League are convinced that the Lord of Atlantis has gone rogue. But when the trail leads them to the mysterious Dr. Fate, they discover there is more to this strange partnership than meets the eye.', 24, '2003-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 16, 'The Terror Beyond (2)', 'With the initial ritual destroyed, the League, Fate, and Grundy must travel into the dimension of the Old Ones while Aquaman fights the invaders in the Earth realm.', 24, '2003-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 17, 'Secret Society (1)', 'Gorilla Grodd brings together a powerful team of villains, welding them together into a close-knit group. Meanwhile the League is plagued by it own internal problems and non-cooperation, leaving them vulnerable to attack.', 24, '2003-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 18, 'Secret Society (2)', 'The Secret Society take advantage of the League''s break-up to bring them down until only Green Lantern remains to free his comrades. When he falls as well everything looks hopeless.', 24, '2003-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 19, 'Hereafter (1)', 'After Superman makes the ultimate sacrifice to save his fellow heroes, the Justice League and rest of the grieving planet must learn to live in a world without Superman.', 24, '2003-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 20, 'Hereafter (2)', 'Superman finds himself on a devastated future Earth with the man responsible - Vandal Savage.', 24, '2003-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 21, 'Wild Cards (1)', 'In the ultimate reality show, the Joker pits the Justice League against the clock and against the Royal Flush Gang as the Justice League races to find and disarm all the bombs he''s planted along the Strip in Las Vegas.', 24, '2003-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 22, 'Wild Cards (2)', 'The League manage to defuse the Joker''s bombs and defeat the four active members of the Royal Flush Gang...but the Joker has an Ace in the hole as he executes his real master plan.', 24, '2003-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 23, 'Comfort and Joy', 'The Justice Leaguers go their separate ways to celebrate the holiday season.', 24, '2003-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0275137')) AND numero_temporada = 2), 24, 'Starcrossed (1)', 'The Thangarians, Hawkgirl''s people, arrive on Earth to aid them against the menace of the Gordanians. But all is not what it seems.', 24, '2004-05-29');
