INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 1), 8, 'X', 'Jack goes through a cave full of challenges only to find an old warrior longing to reach Valhalla.', 22, '2001-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 1), 9, 'VIII', 'Jack meets up with Mad Jack and must battle his darker self.', 23, '2001-10-15');
