INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 1, 'XIV', 'Jack comes upon a monkey-man and agrees to train his tribe in the ways of defending themselves if the monkey-man teaches him how to "jump good".', 22, '2002-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 2, 'XV', 'Three short stories: Jack vs. the Worm: Jack confronts a two-headed riddling serpent who will grant him his wish if he can answer their questions;  The Metal-Eaters: Jack confronts a family that feed on metal and eat Jack''s sword; Jack, the Gargoyle and the Fairy: Jack tries to rescue a wish-granting fairy from a gargoyle so that she may grant his wish to return home.', 22, '2002-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 3, 'XVI', 'Jack is kidnapped and placed in a chain gang of warriors chosen to battle in front of a coliseum audience against the Dome of Doom''s Champions.', 22, '2002-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 4, 'XVII', 'The Scotsman needs Jack''s help to save his kidnapped wife. But this woman is hardly the distressed damsel the Scotsman makes her out to be.', 22, '2002-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 5, 'XVIII', 'Jack goes from destroyed village to another looking for those responsible, only to find the destruction was commissioned by Aku.', 22, '2002-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 6, 'XIX', 'Jack comes upon ruins of a village and realizes it is his home. He then reflects on the past when he was a young boy.', 22, '2002-04-05');
