INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 10, 'XXIII', 'Aku sends out Demongo, the soul collector, to destroy Jack. Now Jack must fight all the mighty warrior souls that Demongo has collected.', 22, '2002-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 11, 'XXIV', 'When Jack has his sword and clothing stolen, he must give chase to a white rabbit who took them while trying to maintain his modesty.', 22, '2002-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 2), 12, 'XXV', 'Jack comes upon a battle where a mere 300 men are fighting a vast, unending army of robots and their evil robotic leader.', 22, '2002-10-04');
