INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 2, 'XXX', 'Aku leads Jack to a graveyard where the dead begin to rise. An evil spirit takes over Jack''s sword, leading Jack to defend himself against his own weapon. When Aku gets hold of the sword, Jack fears he''s finally met his end.', 22, '2002-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 3, 'XXVIII', 'When a man''s daughter is kidnapped by Aku''s Children, Jack must infiltrate a rave to stop the musical brainwashing.', 22, '2002-11-01');
