INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 5, 'XXXI', 'Jack must read hieroglyphics, solve riddles and assemble a sacred scarab to call upon Ra for help in fighting evil ancient Egyptian shadow warriors.', 22, '2002-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 6, 'XXXII', 'Jack must travel along a water creature, a mountain creature and a flying creature to get to a portal to return home. But once he reaches the portal, it is guarded by an undefeatable warrior who tells him that this portal is not for him.', 22, '2003-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 7, 'XXXIII', 'An over-friendly creature begins following Jack, messing up Jack''s every move along his quest.', 22, '2003-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 8, 'XXXIV', 'Jack and a Swamp Wizard travel to the four corners of the earth, collecting pieces that are meant to get Jack home. But when Aku reveals himself to be the Swamp Wizard, Jack must battle these pieces which are now being puppeteered by Aku''s evil hands.', 22, '2003-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 9, 'XXXV', 'When Jack enters a spooky, old mansion and gets locked inside, he catches sight of a figure and sets after it to find out what is going on. As Jack is led further and further in, he discovers that the house and its inhabitants have an evil plan that involves…him.', 22, '2003-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 10, 'XXXVI', 'Jack falls into a hidden temple sanctuary to find monks trained like him in the style of the Ancient Master. The Ancient Master''s Son then tells Jack of a portal to send him home, but in order to use it, his new friends must be sacrificed.', 22, '2003-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 3), 11, 'XXXIX', 'Jack is directed to a deathtrap-filled labyrinth which holds a diamond that can restore him to his time. Unfortunately a master thief also enters the labyrinth going for the item.', 22, '2003-06-07');
