INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 2, 'XLI - Robo/Mondo - Bot', 'Jack enters a village to discover that he is their Chosen One meant to embody the Robo-Samurai and destroy the Mondo-bot that has come to destroy them.', 22, '2003-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 3, 'XLII', 'Jack is approached by a cool Samurai-punk who wants to battle with Jack in order to prove that he is the best.', 22, '2003-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 4, 'Birth of Evil', 'When ancient gods try to destroy a powerful evil, they send one piece of the beast hurtling through space. This piece lands on earth, spreading its evil through the land. When it encroaches on an Emperor''s empire, he takes it upon himself to destroy the evil, but ends up unleashing the evil that is Aku.', 44, '2003-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 5, 'Scotsman Saves Jack', 'Jack has lost all memory of who he is and it''s up to the Scotsman to put the pieces of the puzzle together to save the samurai.', 44, '2003-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 6, 'XLIII', 'When Aku catches a cold and sneezes on Jack, Jack becomes infected with Aku’s badness which begins to take over his entire body.', 22, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 7, 'XLIV', 'When Aku raises the bounty on Jack, the best bounty hunters in the world gather to capture him.', 22, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 8, 'XLVII', 'Jack helps save a Prince and Princess whose ship has been shot down to Earth by Aku.', 22, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 9, 'XLVIII', 'Tired of all the bounty hunters and robots failing, Aku fights Jack, mano y mano.', 22, '2003-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 10, 'XLIX', 'As Jack goes through fall, winter, spring and summer, he must battle the perils that each season brings.', 22, '2004-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 11, 'L', 'Aku forces an old, ace robot assassin out of retirement to eliminate the ultimate mark - Jack.', 22, '2004-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 12, 'LI', 'Young Jack is brought to Africa for part of his training, but when his tribe is abducted, he must learn how to use their unique sword-like weapon – and fast!', 22, '2004-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 4), 13, 'LII', 'Jack finds a baby and the two travel together as Jack tries to return the boy to his mother.', 22, '2004-09-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 1, 'XCII', 'It''s been 50 years since we last saw Samurai Jack and time has not been kind to him. Aku has destroyed every time portal and Jack has stopped aging, a side effect of time travel. It seems he is cursed to just roam the land for all eternity. His past haunts him as well as a cult of assasins dedicated to killing him for Aku''s glory.', 23, '2017-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 2, 'XCIII', 'Jack''s will to survive is pushed to its absolute limits after a deadly, unseen foe launches a relentless surprise attack.', 23, '2017-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 3, 'XCIV', 'Samurai Jack is gravely injured, but still decides to face one of the deadliest foes he''s ever faced, Assassins from the Cult of Aku.', 23, '2017-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 4, 'XCV', 'Samurai Jack partners with a deadly assassin in order to escape a gargantuan creature that has swallowed them whole.', 23, '2017-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 5, 'XCVI', 'Samurai Jack fights to save a group of enslaved people from being harvested as the power source for a monstrous Mega-Robot.', 23, '2017-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 6, 'XCVII', 'Ashi''s search for Samurai Jack helps her to see his effect on the world after encountering numerous people and places where he has changed things for the better', 23, '2017-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 7, 'XCVIII', 'Jack and Ashi overcome a series of dangerous physical and spiritual tests in order to recover Jack''s sword.', 23, '2017-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 8, 'XCIX', 'The burgeoning relationship between Jack and Ashi takes a turn after they are hunted by one of the galaxy''s deadliest creatures.', 22, '2017-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 9, 'C', 'Samurai Jack''s worst fear is realized when he faces off against Aku; the demon makes a shocking discovery about Ashi that puts her in grave danger.', 23, '2017-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0278238')) AND numero_temporada = 5), 10, 'CI', 'The fate of the entire universe hangs in the balance as Samurai Jack faces Aku.', 23, '2017-05-20');
