INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 1, 'Season 1', 'Between the boy Clark Kent thought he was and the man he is destined to become lie the compelling stories of Smallville, the popular action series that reimagines the Superman saga from its roots.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 1, 'Pilot', 'The first episode tells the story of the meteor shower that hit Smallville and changed life in the Kansas town forever. Clark Kent meets Lex Luthor for the first time and encounters the first in a long line of humans mutated by the strange green meteor rocks that accompanied him on his journey to Earth.', 45, '2001-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 2, 'Metamorphosis', 'Clark must deal with Greg, a nerdish bug collector with a crush on Lana who gains the ability of various insects and uses them to lash out at anyone who opposes him.', 45, '2001-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 3, 'Hothead', 'An abusive and hot-tempered football coach gains the ability to control and project fire.', 44, '2001-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 4, 'X-Ray', 'Clark begins experiencing "vision problems" as his x-ray vision begins manifesting. Meanwhile a mysterious shapeshifter is going about town using his or her abilities to steal and get others in trouble.', 44, '2001-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 5, 'Cool', 'A jock named Sean gains the ability to absorb heat from everything and everyone around him, and begins preying on people to gain the heat he needs to survive.', 44, '2001-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 6, 'Hourglass', 'An old man uses green meteor rock to reverse the aging process, then gain vengeance on the children of the jury that put him away decades earlier. Meanwhile, another woman at the same old folks'' home has prophetic abilities and she sees the futures of both Clark and Lex.', 44, '2001-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 7, 'Craving', 'A weight-obsessed teen dieting on kryptonite-infected vegetables gains her fondest dream...but must feed on the fat of others to maintain her enhanced appearance.', 44, '2001-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 8, 'Jitters', 'An experiment at the Luthor fertilizer plant makes an old friend of the Kents literally shake and jitter, and he seeks vengeance against the Luthors, who hide the secret of his transformation behind "Level Three" at the local plant.', 42, '2001-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 9, 'Rogue', 'Clark visits Metropolis, and does a secret good deed - a police detective witnesses this and decides to look into it.', 44, '2002-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 10, 'Shimmer', 'Lex and Victoria are victims of a suspected household poltergeist.  As the disturbances become more violent, suspicion lands on Amy, the daughter of a house servant who is obsessed with Lex.  Not is all as it seems...', 44, '2002-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 11, 'Hug', 'A guy in charge of a rival fertilizer firm to LuthorCorp''s arrives in Metropolis. He is intent on buying up the Kent farm and using the land to build a rival company to Lex''s. Clark befriends a local recluse with secrets of his own.', 44, '2002-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 12, 'Leech', 'Clark''s powers are transferred into a classmate during a freak juxtaposition of meteor and storm.  Clark must deal with being normal for the first time, and his classmate Eric is unable to cope with the new powers.  Can Clark stop Eric''s rampage without his abilities?', 43, '2002-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 13, 'Kinetic', 'Whitney falls in with some former jocks who have kryptonite tattoos that give them the power to walk through walls. Meanwhile, Chloe is seriously injured and Lex has his own plans.', 44, '2002-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 14, 'Zero', 'A man from Lex''s past stalks him in conjunction with a mysterious death at Club Zero that Lex may have been responsible for. Meanwhile Chloe looks into Clark''s past as an adopted child.', 41, '2002-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 15, 'Nicodemus', 'A flower that comes from a reopened "Level Three" of the fertilizer plant brings strange reactions from several people, including Jonathan, Lana, and Pete.', 44, '2002-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 16, 'Stray', 'A young runaway, Ryan, has the power to read minds and flees his abusive stepparents. The Kents take him in and Clark soon discovers the boy''s powers and that he''s immune to them. But Ryan''s stepparents have plans to use the boy''s powers for financial gain against...Lex.', 44, '2002-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 17, 'Reaper', 'Tyler gains the power to destroy organic matter with a touch, and resolves to put the dying out of their misery...and Whitney''s father is his next target. Meanwhile Lionel and Lex spar over Lionel''s rising success in Smallville.', 44, '2002-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 18, 'Drone', 'Clark gets into a class election and one of his opponents is a krypto-mutant who can control bees. Meanwhile a reporter from Metropolis visits to do a story on Lex.', 43, '2002-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 19, 'Crush', 'Former Smallville High cartoonist Justin returns to Smallville after he loses the use of his hands in a hit and run accident. Meanwhile, Lex''s former nanny, Pamela, comes back to see how he''s doing and to apologize for leaving him after his mother''s death, bringing up some old issues for Lex.', 43, '2002-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 20, 'Obscura', 'After an explosion Lana finds herself getting visions of a serial killer...and his next target is Chloe. Meanwhile Lex and Roger look further into the meteor shower and determine that something besides meteors hit Smallville that day.', 43, '2002-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 1), 21, 'Tempest', 'Lex is hit with a surprise by his father. Clark prepares for his date with Chloe, but Mother Nature has other plans.', 44, '2002-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 2, 'Season 2', 'The legend continues to grow stronger in the second super season of Smallville.  Throughout the season’s twenty-three episodes, Clark Kent grapples with his calling as he explores his true origins: was he sent to Earth to save humanity or destroy it?  Amidst all the chaos, Lana and Clark grow closer than before; Lex gets married; Lionel lures Chloe toward the dark side; the Kents receive miraculous news; and Pete becomes the keeper of Clark’s secret.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 1, 'Vortex', 'Clark rescues Lana from the storm, but discovers that the spaceship is released, while Jonathan is buried alive with the unscrupulous reporter who discovered Clark''s secret. Meanwhile, Lex is wracked with guilt over his critically injured father.', 43, '2002-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 2, 'Heat', 'Clark gains a new power - heat-vision. As he struggles to control it, Lex gets married to the new Smallville High teacher, Desiree Atkins, little does he know that she not only has an alterior motive, but that she''s coming on to Clark too.', 44, '2002-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 3, 'Duplicity', 'Pete finds Clark''s spaceship, forcing Clark to reveal his secret to his best friend. Dr. Hamilton is plagued by kryptonite-fueled illness and focuses on Pete. Meanwhile, Lana has to deal with Nell and her plans to remarry while Lex and Lionel adjust to life together.', 42, '2002-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 4, 'Red', 'Clark has his first run-in with red kryptonite in this exploration of classic Superman mythology, turning immoral when he gets his high-school ring holding a piece of rock. Meanwhile, Lex and his father have some issues to resolve when Lionel starts taking over the manor.', 44, '2002-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 5, 'Nocturne', 'Lana has a new stalker - a boy imprisoned in his basement by his parents who sneaks out at night to visit her. Meanwhile Lionel hires Clark''s mother as his personal assistant.', 42, '2002-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 6, 'Redux', 'Martha''s father William comes to town after many years of estrangement due do his disapproval of Jonathan. Meanwhile Clark must deal with a series of old-age deaths at Smallville High, and the new principal puts his foot down.', 41, '2002-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 7, 'Lineage', 'A strange woman shows up claiming to be Clark''s biological mother...and that his father is Lionel. Meanwhile Lana decides to meet with the man who is her biological father.', 44, '2002-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 8, 'Ryan', 'Ryan (from "Stray") returns and Clark has to save him from Dr. Garner of the Summerholt Research Facility. Meanwhile, Aunt Nell leaves Smallville, and Lex wants to expand the plant but runs afoul of the mayor.', 43, '2002-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 9, 'Dichotic', 'A Smallville student, Ian, displays the ability to make clones of himself and uses his power to date both Chloe and Lana. Meanwhile Lex goes to anger management class and meets an attractive local doctor.', 42, '2002-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 10, 'Skinwalker', 'Clark becomes involved with a Native American woman, Kyla, and becomes aware of ancient Indian prophecy that warns of a man of great powers who fell from the sky. Worse, a wolflike creature is attacking the local Lexcorp construction project, and Martha and Lionel may be the next victims.', 42, '2002-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 11, 'Visage', 'Whitney returns to Smallville, eager to start back up where he left off with Lana. But everything isn''t what it seems...', 44, '2003-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 12, 'Insurgence', 'Lex hires some thugs to bug Lionel''s office but things get out of control when Lionel and Martha are taken hostage, and Clark must rescue them without revealing his secrets.', 44, '2003-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 13, 'Suspect', 'Lionel is shot in the manor, and Jonathan is the prime suspect.', 43, '2003-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 14, 'Rush', 'Students are engaging in wild, sometimes suicidal stunts, and Chloe and Pete are the next ones to become "infected."..and they use a piece of red meteor rock to get Clark to join them.', 43, '2003-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 15, 'Prodigal', 'Lex recovers his long-lost brother Lucas and uses him in a ploy to buy out his father''s share of the company. But it soon becomes clear that Lucas isn''t to be trusted, and Lex soon finds himself ousted from his own company.', 44, '2003-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 16, 'Fever', 'Martha catches a lungful of kryptonite-irradiated spores and a weakened Clark is her only hope for survival.', 44, '2003-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 17, 'Rosetta', 'Clark travels to New York to meet Dr. Swann, a brilliant scientist who holds a message for Clark from his home planet. Meanwhile Lana decides to move out of Chloe''s house after they get into an argument about Clark.', 44, '2003-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 18, 'Visitor', 'After a schoolmate claims to be an alien and proves it by using heat vision, Clark investigates and believes the boy is from Krypton. Meanwhile, Helen confronts Lex over the locked room in the mansion that holds his investigation of Clark''s secrets.', 43, '2003-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 19, 'Precipice', 'After Lana is almost assaulted by a college student, Clark injures the boy while helping her. When the Kents are sued for damages that could cost them the farm, Clark tries to find a way out of the lawsuit. Meanwhile, Helen''s obsessive ex-boyfriend comes to Smallville to win her back but when she turns him down, he stabs her, prompting Lex to take the law into his own hands.', 44, '2003-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 20, 'Witness', 'Clark runs up against super-strong robbers who are apparently tied to LexCorp. And Chloe begins to ally with Lionel, while Lana and Henry Small bond.', 42, '2003-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 21, 'Accelerate', 'Lana is haunted by the ghost of a dead friend, Emily, but the "spirit" has connections to Lionel Luthor, who is also scheming to get control of the Indian caves and "help" Lex with his wedding.', 44, '2003-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 22, 'Calling', 'Dr. Walden comes out of a coma with super-powers and a desire to kill Clark, piquing the Luthors'' interest. The spaceship starts talking to Clark, and Helen and Lex prepare for their wedding.', 44, '2003-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 2), 23, 'Exodus', 'A sense of foreboding surrounds Smallville as Clark must choose between staying with Lana and his family or fulfilling his destiny to rule the Earth. Lex and Helen prepare for their marriage, and Chloe considers Lionel''s offer to investigate Clark.', 44, '2003-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 3, 'Season 3', 'Everyone has a future.  Clark Kent has a destiny — if he’s willing to accept it and to master all the awesome powers and responsibilities that come with it. In an event-packed third season, the fascinating reinterpretation of the Superman mythology and its classic characters continues as Clark embraces the dark side and Jonathan Kent strikes a devil’s bargain with Jor-El to rescue his son.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 1, 'Exile', 'Under the influence of red kryptonite, Clark is following a life of crime in Metropolis while his friends and parents desperately try to find him. Lex is forced to confront his personal demons on a desert island, while Lionel holds a funeral for his presumed-dead son. And Jonathan Kent must pay a high price for the power necessary to bring his son back home.', 43, '2003-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 2, 'Phoenix', 'Clark gives up the ring and its effects rather than kill his father, and both he and the rescued Lex return to Smallville. Clark must deal with crime lord Morgan Edge, who has followed him to Smallville, while Lex must determine who tried to have him killed - Lionel or Helen.', 44, '2003-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 3, 'Extinction', 'Clark discovers someone is hunting people affected by the kryptonite rocks and the killer''s next target is Lex. Clark uses his powers to save Lex, but is caught off guard when the killer learns his weakness and shoots him with a kryptonite bullet.', 42, '2003-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 4, 'Slumber', 'Clark dreams he is being pursued by a frightened young girl who needs his help. However, after he discovers she is actually a comatose neighbor who should have woken up years ago, he enlists Lana''s help to uncover the truth - which puts Lana in grave danger. Meanwhile, Lionel demands that Lex undergo a full psychological evaluation before he hires him.', 44, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 5, 'Perry', 'Perry White, a once promising journalist whose career was destroyed by Lionel Luthor, arrives in Smallville in search of alien stories for a tabloid news show. In spite of being constantly inebriated, Perry believes he has witnessed Clark using his extraordinary speed, so he devises a dangerous scheme to expose Clark''s superpowers. Meanwhile, Lex learns that Perry has powerful incriminating evidence of Lionel''s shady past.', 44, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 6, 'Relic', 'Clark discovers that Jor-El was on Earth forty years ago. Lana''s great uncle, who was convicted of murdering his wife forty years ago, shows her a picture of the man he believes really killed her aunt, and she is shocked to discover the drifter looks just like Clark. Sure that the man is Jor-El, Clark''s investigation leads him to a kryptonian medallion that allows him to see bits of the past - and the life that Jor-El started for him long before he arrived on Earth.', 44, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 7, 'Magnetic', 'Clark is suspicious when Lana suddenly becomes attracted to a fellow student and begins to act rebelliously, which eventually lands her in jail. Clark''s suspicions are confirmed when he discovers Lana''s new boyfriend has magnetic powers that can move objects and alter human emotions, but when he tries to free Lana from the paranormal hold that is controlling her, she tries to kill him. Meanwhile, Lex discovers Chloe has been delving into Lionel''s past and tries to get her to join forces against his dad.', 43, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 8, 'Shattered', 'Lex locates Morgan Edge and gets him to admit to dirty dealings with Lionel, but before Lex can take it to the authorities, someone tries to kill him at the mansion. Barely surviving, Lex flees and asks Clark for help. However, when Clark returns to the mansion to investigate he finds nothing amiss, and begins to wonder if it really happened, especially after Lionel announces Lex has had a psychotic break and must be institutionalized.', 44, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 9, 'Asylum', 'Three of Clark''s former opponents approach Lex to enlist his help in luring Clark to the hospital after they hear that Lionel has requested Lex be given electroshock therapy to erase his memory. However, the plan goes awry when the villains double-cross Lex and use kryptonite to steal Clark''s powers. Meanwhile, Lana meets a mysterious stranger in the hospital.', 44, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 10, 'Whisper', 'Attempting to stop a robbery, Clark is temporarily blinded when he shoots off a burst of heat vision that is accidentally reflected back into his eyes by a piece of kryptonite and soon realizes his body has developed super-hearing to compensate for his lack of sight. However, as it was in the beginning with his other gifts, Clark doesn''t quite have his new power under control.', 41, '2004-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 11, 'Delete', 'Clark and Lana each make an attempt on Chloe''s life for unknown reasons after they receive a mysterious e-mail from the Summerholt Institute. Clark must discover the source of these e-mails after Chloe reveals she has uncovered proof that they are doing mind-control research at the lab and realizes they must be trying to kill her in order to prevent her from writing an expose. Meanwhile, Lana decides to rent the apartment above the café to Adam even though she feels he is hiding something dangerous about his past.', 43, '2004-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 12, 'Hereafter', 'Clark discovers that his schoolmate Jordan can foresee the future, but is horrified when Jordan tells him he "sees" Lana dying in a fire in the next few days. Meanwhile, suspicious of his behavior, Chloe investigates Adam''s background and discovers some disturbing news.', 42, '2004-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 13, 'Velocity', 'After Pete refuses to throw a street race, the thugs that run it threaten his life, so he asks Clark to use his powers to stop them. Furious that Pete would put himself in this position, Clark must figure out a way to save Pete and still protect his secret. Meanwhile, Jonathan begins to suffer the consequences of his deal with Jor-El.', 43, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 14, 'Obsession', 'Clark is forced to use his powers in front of Alicia, a new girl at school, but he is surprised to find out she has powers of her own. The two develop a bond through their shared secret, but things turn ugly after Alicia becomes obsessive about sharing Clark with anyone else - especially Lana. Meanwhile, Lana asks Lex to investigate Adam.', 43, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 15, 'Resurrection', 'While his father is awaiting surgery, Clark befriends a young boy, Garrett whose brother Vince just died from liver failure. However, everyone is shocked when Vince shows up alive and seemingly well - until his liver starts failing again. In a desperate attempt to keep his brother alive, Garrett straps a Kryptonite bomb to himself and demands that Vince be given Jonathan''s liver or he will blow up the building.', 41, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 16, 'Crisis', 'Clark receives a panicked call from Lana and hears a gunshot before the line goes dead, but when he arrives at the Talon he is stunned to discover she is alive and well. Clark realizes the phone call came from the next day and that Adam is the one who will shoot Lana.', 43, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 17, 'Legacy', 'When Jonathan begins to act strangely, Clark believes Jor-El is sending Jonathan messages through the key and is the cause for his father''s withdrawal from the family. Clark goes down to the caves to confront his biological father but Lionel catches him there and begins putting the pieces together, leading him straight to Dr. Swann. As the two billionaires face off, a deal is struck and Lionel''s true motives are revealed.', 43, '2004-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 18, 'Truth', 'When Chloe accidentally inhales a mysterious krypto-gas, she discovers it acts as a truth serum to anyone who comes in contact with her and decides to take advantage of her new power by going to the Kents to find out Clark''s secret. However, her new power comes with fatal consequences and Clark must find an antidote before she discovers the truth about him or worse, dies.', 43, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 19, 'Memoria', 'Believing that key information about his father''s past was lost when his memory was erased, Lex decides to join an experimental program with Dr. Garner to regain the information so he can turn his father over to the FBI. Knowing that Lex will discover his secret if he regains his memory, Clark tries to stop him but is caught by Lionel and the doctor and exposed to the same radical treatment so that Lionel can solve the mystery of Clark''s past.', 44, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 20, 'Talisman', 'Jeremiah Holdsclaw, a young Kiwatche Indian, steals a mythic knife from the tribal caves and gets superpowers similar to Clark''s. Jeremiah believes he is the fulfillment of the ancient prophecy of Naman, "the man who fell from the stars." He sets out to kill Lionel with the knife, and Clark must stop him without revealing his own secret.', 42, '2004-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 21, 'Forsaken (1)', 'Clark decides to tell Lana his secret so they can finally be together. Meanwhile, an errant FBI agent kidnaps and tortures Pete to try and force him to reveal Clark''s secret. Also, Lex panics after the FBI gives him 24 hours to turn over information on his father or face jail time, but help arrives from an unexpected source.', 43, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 3), 22, 'Covenant (2)', 'Kara, a beautiful superpowered girl from Krypton, entices Clark to join with his father and embrace his destiny. Clark is left without support after Pete''s departure when Jonathan reveals the deal he made with Jor-El. At the same time, Clark''s relationships with Lex and Lana take unexpected turns, leaving him with no one but Kara to turn to.', 43, '2004-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 4, 'Season 4', 'Clark Kent will have plenty of reasons to remember his senior year! Lois Lane  — smart, opinionated, and entirely annoying to Clark — arrives in Smallville to investigate the death of her cousin. Lana gets a new older boyfriend. Clark decides to go against his parents'' wishes and joins the football team as a quarterback. And while Clark sets off on a quest to find three mysterious Kryptonian crystals, Lex steps further from the light into darkness.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 1, 'Crusade', 'Clark returns to Smallville as Kal-El - intent on fulfilling his destiny, he goes after a powerful kryptonian crystal that Lex has obtained in Egypt. Meanwhile, newcomer Lois Lane arrives in Smallville to look into the death of her cousin Chloe, and Lana returns from Paris with a new boyfriend. Jonathan lies in a coma after the events of last year''s season finale and Lionel must deal with his new life in prison.', 44, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 2, 'Gone', 'After discovering that Chloe''s body isn''t in her coffin, Clark and Lois Lane investigate. Meanwhile, Lana''s life in Paris catches up with her in Smallville. And Lionel sends a killer to determine if Chloe is alive and kill her for sure.', 41, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 3, 'Facade', 'Abigail, an ugly high school girl, gets plastic surgery from her surgeon-mother to boost her popularity. However, her beauty hides a dark secret - when she kisses someone they''re inflicted with life-threatening hallucinations. When Lana sees Abigail with one of her victims, she becomes the next target.', 42, '2004-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 4, 'Devoted', 'Clark decides to join the football team over Jonathan''s wishes and gets the starting quarterback position when his predecessor attacks Jason over a girl. Clark and Lois investigate and discover that the cheerleaders are using kryptontie in the team''s water supply to turn them into obedient mindless boyfriends.', 43, '2004-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 5, 'Run', 'Jonathan''s wallet is stolen by a super-speed thief, Bart Allen, who is faster than Clark. Bart comes to the farm and becomes friends with Clark, but Bart returns to crime when he sees an ancient manuscript that Lex has. As Clark soon realizes, the manuscript holds a map to one of the kryptonian crystals and he must go up against Bart to recover it.', 42, '2004-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 6, 'Transference', 'Clark is drawn to the state penitentery by one of the kryptonian crystals, which Lionel is using to switch bodies with Lex. Clark intervenes and Lionel enters his body instead. While Lionel uses his newfound super-powers to regain his lost fortune and alienate Clark''s friend, Clark must convince his parents that he is the "real" Clark and reverse the processs, while avoiding murderous convicts.', 43, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 7, 'Jinx', 'Mikail Mxyzptlk, a foreign exchange student and bookie, has the power to control others and uses it to sabotage football games, including the one Clark is quarterbacking. Clark and Chloe figure out his secret, but he threatens to kill Chloe unless Clark throws the next game. Mikail came to Smallville via LuthorCorp, and Lex will do almost anything to learn his secret.', 42, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 8, 'Spell', 'Lana reads a spell book belonging to her 17th century ancestor, the witch Isabelle, and becomes possessed by her spirit. Isabelle resurrects her other two witches and together they seek out the kryptonian crystals, using their magic to render Clark powerless.', 43, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 9, 'Bound', 'Lex is accused of killing a young woman and Clark turns to Lionel for help. Meanwhile, Lana has a dream of her ancestor and a mysterious second woman - a dead ringer for Jason''s mother Genevieve, who arrives to visit her son and his new girlfriend.', 43, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 10, 'Scare', 'A Luthorcorp experiment is released into the atmosphere - a toxin that causes its victims to hallucinate their worst fear. Chloe, Clark, Lana, and Jason all fall fictim to the toxin, and Lex, desperate to find a cure, takes a dangerous antidote. Meanwhile, Lionel is released from prison and his conviction overturned thanks to a mysterious benefactor.', 41, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 11, 'Unsafe', 'Alicia (from "Obsession") is supposedly cured and returns to Smallville to start things back up with Clark. When she pushes for more and he turns reluctant, Alicia expoess him to red kryptonite, and the two go off to Las Vegas to get married. Meanwhile, Lana questions whether sex may prove the key to winning Jason back.', 42, '2005-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 12, 'Pariah', 'When a mysterious killer strikes at both Lana and Jason, Alicia is the leading suspect and even Clark comes to doubt her innocence. Feeling betrayed, she secretly tricks Clark into revealing his powers in front of one of his friends. And Genevieve returns to town with an offer for Lex, who in turn has an offer for Jason.', 44, '2005-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 13, 'Recruit', 'Clark is approached by Met U for recruitment and meets Geoff, a former Smallville resident. It soon becomes apparent that he is using his powers to paralyze anybody who gets in his way...including Lois.', 43, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 14, 'Krypto', 'Lois accidentally hits a dog and brings it back to the farm to heal, but Clark quickly realizes it has super-strength. He investigates and discovers it was part of an aborted LuthorCorp experiment...and that robbers are using the dogs to help them steal money. Meanwhile, Lana wonders what Jason is up to with his mother, and Jason is forced to ask Genevieve a few questions of his own.', 43, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 15, 'Sacred', 'After Clark receives a message from the recently-deceased Dr. Swann, he and Lana follow Jason and Lex to China in search of one of the kryptonian crystals. Lana is tortured, causing Isabelle to emerge and wreck havoc in her search for the crystal.', 43, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 16, 'Lucy', 'Lucy Lane, Lois'' younger sister, comes to Smallville but Clark catches her stealing money from the Talon to pay off a European crime syndicate. Lex offers to help but everything is not what it seems. Meanwhile, a thief breaks into Lana''s apartment and steals the crystal, and Jason suspects Lionel.', 42, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 17, 'Onyx', 'A black kryptonite explosion splits Lex in two and his evil side - Alexander - is released. Alexander imprisons Lex in the mansion then gives full vent to his evil side - he threatens to evict Lana from the Talon unless she becomes his mate, jousts with Lionel, and tries to kill Clark and Chloe when they figure out his secret.', 43, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 18, 'Spirit', 'On the eve of the Smallville High School Prom, stuck-up candidate for Prom Queen Dawn Stiles is pulled into a coma when she is involved in a car crash into a ravine filled with dozens of chunks of kryptonite. While her body lies in a coma, Dawn finds her spirit allowed to possess the bodies of others, where she can continue her quest to become Prom Queen. As a result, Martha, her body possessed by Dawn, flirts with Clark and asks him to the Prom, Lana attempts to electrocute the ex-boyfriend who dumped Dawn, Lois goes all-out to ensure she and Clark go to Prom together, and Chloe attempts to set fire to the school on Prom night.', 44, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 19, 'Blank', 'When a boy who can make people lose their memories robs the Talon, Clark goes after him but gets total amnesia. Chloe finds out what happened and has to tutor Clark in the use of his superpowers and make sure he doesn''t accidentally reveal his secret. While Clark, Chloe, and Lois try to track down Kevin, Clark takes advantage of his "new life" to ask Lana on a date. And Lex tries to turn Clark''s memory loss to his advantage by getting him to reveal the secret of the caves.', 44, '2005-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 20, 'Ageless', 'Checking out a crater in a cornfield, Clark and Lana discover a baby with no parents and take him back to the Kent farm. However, when the baby, Evan, ages from a newborn to a 7-year-old in less than a day, it becomes clear he is aging at a rapid rate and they turn to Lex for help. Meanwhile, Genevieve suspects Lex has the Chinese Kryptonian artifact and orders Lionel to either recover it...or risk putting Lex in danger of his life.', 43, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 21, 'Forever', 'Clark must stop the school photographer after he sets up a fake high school and uses his ability to petrify people to kidnap students - including Chloe and Lana - to keep the glory days of high school going forever. Meanwhile, Lex and Lionel are kidnapped and tortured by the Teagues in an effort to find the Kryptonian artifact, revealing that...Lana has it.', 43, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 4), 22, 'Commencement', 'After a nightmare, Clark goes to the cave to confront his father Jor-El. Jor-El warns that the crystals have fallen into human hands and have triggered a new meteor shower which will annihilate the Earth unless he reunites the three crystals. Meanwhile, Lex helps Lana, who has apparently commited murder, but then turns against her to get possession of her Kryptonian stone. As disaster looms, Chloe and Lois try to find Lana while Clark attempts to reassemble the stones, and Jason returns to make things unpleasant for the Kents.', 53, '2005-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 5, 'Season 5', 'Clark Kent now carries a full load of classes at Central Kansas University, but that''s not all he carries. He carries the full weight of his — perhaps the world''s — destiny. In season five, Clark finally begins to accept his destiny and takes giant leaps towards becoming the Man of Steel. He also crosses paths with Professor Milton Fine, whose presence in Smallville will have a devastating effect on his already deteriorating friendship with Lex.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 1, 'Arrival', 'Having been transported to the Fortress of Solitude, Clark is confronted by Jor-El, who tells him he cannot return to Smallville, instead he must stay and prepare to save the planet. Also, transported to the Fortress, Chloe is unable to handle the sub-zero temperature and collapses, begging Clark to use his powers to save her. Jor-El forbids him to leave, but finally acquiesces, telling Clark he must return before sunset or there will be dire consequences. Meanwhile, Lana is horrified when she sees two Kryptonian aliens emerge from a spaceship discovered in the remnants of the meteor shower. The two aliens destroy what''s left of the town searching for Kal-El.', 43, '2005-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 2, 'Mortal', 'Jor-El strips Clark of his powers, making him human. Delighted to finally be normal, Clark pursues a relationship with Lana sans secrets. However, after Lana, Jonathan and Martha are taken hostage by three thugs, Clark must figure out how to save his family without his super powers.', 42, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 3, 'Hidden', 'A krypto-mutant, Gabriel, hacks into missile codes and prepares to eliminate krypto-mutants in Smallville once and for all. A powerless Clark confronts him and is shot, and only Jor-El can save him.', 42, '2005-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 4, 'Aqua', 'At a party at Crater Lake, Lois is saved from drowning by Arthur "A.C." Curry. Arthur has incredible swimming abilities, but also a secret agenda aimed at...Lex. Meanwhile, Professor Fine discussed Lex''s weapons-manfucturing operations with Clark.', 41, '2005-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 5, 'Thirst', 'Lana joins a sorority to get housing for her last-minute college registration, but the sisters have a deadly agenda which involves turning Lana into a vampire like themselves and sending her against Clark. Meanwhile, Chloe applies to become an intern at the Daily Planet and runs up against the editor-in-chief, Pauline Kahn.', 41, '2005-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 6, 'Exposed', 'Jonathan''s oldest friend, Senator Jack Jennings, comes to Smallville looking for support in his re-election campaign, but is framed for the murder of his mistress, requiring Lois to go undercover as a stripper.', 42, '2005-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 7, 'Splinter', 'Clark gives into paranoid delusions brought on by exposure to new "silver" kryptonite, and Professor Fine is the only one who can save him... before he kills Lana.', 43, '2005-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 8, 'Solitude', 'When Martha comes down with a strange disease, Professor Fine convinces Clark that Jor-El is responsible and that the Fortress must be trying to eliminate the father of Kal-El. But Professor Fine has an ulterior motive which comes to fruition when they arrive.', 41, '2005-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 9, 'Lexmas', 'Lex  is given an envelope with damaging information that will destroy Jonathan''s life and must decide whether he will use it as it will also bring harm to Clark and Martha. Before he can decide what to do, Lex is shot and falls into a coma. He dreams that his mother visits him and shows him the life he could lead if he walks away from his father and LuthorCorp. In this alternate life, Lex is happily married to Lana with a baby on the way. Meanwhile, Chloe asks Clark to use his powers to deliver Christmas presents to needy kids.', 43, '2005-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 10, 'Fanatic', 'The Senatorial race between Jonathan and Lex heats up when Jonathan receives an anonymous threat warning him to drop out of the election. When Clark finds Jonathan badly beaten he determines to find the attackers. Lois is thrown into the mix when she is captured and she is forced to assassinate Jonathan during his speech.', 42, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 11, 'Lockdown', 'Lex and Lana are at the mercy of a deranged Smallville deputy who plans to keep them captive until Lex reveals the location of the Kryptonian spaceship. Meanwhile, the Kents can''t see eye-to-eye on campaign financing.', 42, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 12, 'Reckoning', 'Clark reveals his secret to Lana, Jonathan and Lex learn the results of the senatorial election, and there is a tragic car accident on the highway that takes the life of someone Clark loves, forcing Clark to appeal to Jor-El for help.', 43, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 13, 'Vengeance', 'Clark discovers that the new assistant at the Daily Planet, a bespectacled, bumbling woman named Andrea, is actually a mysterious female vigilante who stalks Suicide Slum. Her path crosses Clark''s as they both seek the same criminal. Meanwhile, Clark''s bottled-up grief threatens to get the best of him and LuthorCorp experiences a shakeup.', 42, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 14, 'Tomb', 'Chloe is possessed by the spirit of a young girl whose body is sealed in the Talon''s walls, and goes searching for the girl''s killer while Clark and Lois try to track her down.', 41, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 15, 'Cyborg', 'Clark finds himself up against Lex when he befriends Victor Stone, a half-machine, half-human subject who escapes from LuthorCorp with the aid of a sympathetic doctor.', 41, '2006-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 16, 'Hypnotic', 'Clark is hypnotized by a woman who uses a supposedly magical charm to control others - he reveals his super powers and is sent to kill Lex. Meanwhile, Lex has tracked down the missing Professor Fine and plans to confront him, unaware that Clark is coming to murder him.', 42, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 17, 'Void', 'Distraught over her break-up with Clark, Lana goes to a rogue medical student who experiments with a dangerous kryptonite-based serum that allows people to flat-line but see their dead loved ones. Lana attempts to see her dead parents using the serum and when Clark returns from Honduras to help her, the doctor injects him with the serum and Clark speaks with his dead father...who warns him that Lionel knows his secret. Meanwhile, Lionel continues working to get closer to Martha, and Lex has a near-death vision of his mother.', 41, '2006-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 18, 'Fragile', 'Clark befriends a little girl who has the ability to telekinetically shatter glass, then comes to her aid when it''s believed she killed her mother in a brutal stabbing attack. Meanwhile Lex and Lana grow closer together and Chloe finds out about it.', 43, '2006-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 19, 'Mercy', 'Lionel is taken hostage by a masked man who forces him to play elaborate games for the prize of staying alive. Martha goes to confront Lionel after Clark tells her Lionel knows his secret and becomes a part of the game herself, fighting for her life.', 44, '2006-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 20, 'Fade', 'Clark saves a man who in gratitude decides to help Clark in return...by using his ability to turn invisible and his skill as a hitman to kill Lex so Clark can reunite with Lana. And Clark and Lana finally square off about Lana''s new relationship.', 41, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 21, 'Oracle', 'Clark and Martha are both visited by Jonathan''s ghost, who warns them about Lionel and claims that Clark must kill him to stop him. Meanwhile Fine will do whatever it takes to get the vaccine from Lex.', 43, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 5), 22, 'Vessel', 'Professor Fine has unleashed a virus that will kill millions. Clark must put a stop to him, while Lex wonders what happens when he will tell Lana his newest secret.', 44, '2006-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 6, 'Season 6', 'Clark manages to escape from the Phantom Zone with the help of an unexpected ally. He subsequently sets out on a mission to hunt down the dangerous prisoners who followed him to Earth. Adding to Clark''s troubles, there is a new vigilante in town who goes by the name Green Arrow. Meanwhile, Lex and Lana take the next step in their relationship. As the season progresses, the rivalry between Clark Kent and Lex Luthor will explode into a fierce good-versus-evil battle.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 1, 'Zod', 'A powerless Clark is trapped in the "Phantom Zone" surrounded by the criminals his father imprisoned there. However, an unexpected ally comes to his aid. Meanwhile, Zod in Lex''s body advances his plan to transform Earth into a new Krypton, while using Lana to produce an heir.', 43, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 2, 'Sneeze', 'In the aftermath of Zod''s activities, Clark develops a new power. Lois gets a new job, Lana takes a new step in her relationship with Lex, and Lex has to deal with a new danger. Meanwhile, an old friend of Lex''s arrives in Metropolis.', 42, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 3, 'Wither', 'Clark and Chloe pursue a plant creature that uses male humans to recreate, one which has taken Jimmy Olsen as its next human breeding ground. Meanwhile, Oliver Queen asks a reluctant Lois to be his date at a charity ball held by Lex.', 42, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 4, 'Arrow', 'The mysterious Green Arrow steals a necklace from Martha, and both Lois and Clark resolve to find out who the vigilante is. While Clark determines Green Arrow''s true identity, Lex continues his investigation of the mysterious black box while Lionel warns Lana against him.', 42, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 5, 'Reunion', 'Lex and Oliver Queen return to their old prep school for a reunion, but Oliver''s old friends (and Lex''s old enemies) start dying in mysterious accidents. Meanwhile, Clark learns that someone... or something may have left the Phantom Zone with him.', 42, '2006-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 6, 'Fallout', 'After escaping from the Phantom Zone, Raya comes to Smallville to visit Clark. Raya and Clark grow close, and Raya reveals how to repair the Fortress of Solitude. Unfortunately, Baern, another escapee seeks out revenge on Clark and Raya for his time spent in the Zone.', 40, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 7, 'Rage', 'After being shot while stopping a carjacking, the Green Arrow begins acting strangely. Chloe and Clark investigate and find Oliver is taking a super drug that while healing his wound, has some dangerous side effects.', 43, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 8, 'Static', 'One of the escapees from the Phantom Zone has killed the crew of a ship in Seattle. Clark confronts the killer who feeds on the bones of his victim. In Smallville, a patient in LuthorCorp Labs escapes experimentation and seeks revenge on Lex by trapping him in a dimension where he can see and hear those around him, but they cannot see him.', 41, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 9, 'Subterranean', 'An illegal immigrant comes to Clark for help, escaping from a nearby farm where he''s working... a farm that houses a dark secret.', 41, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 10, 'Hydro', 'A Daily Planet gossip columnist uses her special power to overhear a conversation between Lana and Chloe, and publishes the conversation... where Lana admits having doubts about marrying Lex. While Chloe investigates the reporter, Lois asks Clark to help her investigate the mysterious Green Arrow bandit when she suspects he may be Oliver Queen in disguise.', 43, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 11, 'Justice', 'When Lex''s Level 33.1 project comes to fruition, Oliver Queen must bring together several of Clark''s "heroic" super-powered allies together: Arthur Curry, Bart Allen, and Victor Stone.', 43, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 12, 'Labyrinth', 'Clark is in his barn one moment... and the next finds himself in a psychiatric hospital where he discovers he''s been suffering from delusions that he came from another planet and has super-powers.', 40, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 13, 'Crimson', 'Clark is once again exposed to red kryptonite, and his "other self" goes on a rampage of sorts on Valentine''s Day, kissing the women he''s most attracted to and expressing his uninhibited feelings for the various relationships around him.', 43, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 14, 'Trespass', 'Lana has a stalker which leads her to an unexpected hideout. Also, Chloe has to reevaluate her feelings for Clark after she and Jimmy break up due to Jimmy''s belief that she isn''t really over Clark.', 42, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 15, 'Freak', 'A boy named Tobias was blinded by the meteor shower but given the ability to identify other meteor freaks. Lex is using Tobias to locate other people with abilities so that he can perform experiments on them. Lana learns of Tobias and is fearful that he will name Clark as a freak, so she offers him a cornea transplant to keep him quiet. But Tobias has some surprising news.', 43, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 16, 'Promise', 'Clark has second thoughts about Lana marrying Lex, and Lana has the same concerns. Meanwhile, the doctor involved in the secret behind Lana''s pregnancy threatens Lex with his knowledge.', 42, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 17, 'Combat', 'Clark and Chloe find an escaped Zoner named Titan who is the star of a secret fight club that puts its death battles on the internet.  Lois can tell that there is a story and goes to investigate, where she is put in the ring to fight.  Clark goes in as a super-powered fighter to take on Titan but ends up against a different opponent instead.', 40, '2007-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 18, 'Progeny', 'Lex discovers that Chloe''s mother has special abilities and forces her to help him in exchange for Chloe''s life. However, she has a trick or two of her own to use to escape.', 41, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 19, 'Nemesis', 'Lex and Clark get a chance to hash out their differences... when they''re both trapped in a cave after an explosion, and Clark is unable to get them out without revealing his powers.', 41, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 20, 'Noir', 'Lana and Lionel have a secret meeting, after which Lana is shot. While Jimmy is observing photos of the encounter, he is knocked unconscious. While unconscious Jimmy dreams about what life in Smallville would have been like in the 1940s. Clark is a reporter at the Daily Planet, Lana is a siren who planned the demise of her magnate husband Lex, and Lois is a singer at a bar that Lionel owns.', 42, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 21, 'Prototype', 'Lex tries to turn a soldier that supposedly died in Afghanistan into a "super-soldier." A senator threatens to tell the world about Lex''s labs, prompting Lex to send the "soldier" to kill the senator. Lois sees the attack and becomes the soldier''s next victim.', 41, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 6), 22, 'Phantom', 'Clark discovers the reason Lana married Lex then and sets out to kill Lionel. Lex tries to use DNA from the last phantom to power his super-soldiers. Lois goes to a dam to search for Lex''s lab but is caught by a security guard and fatally injured. Chloe''s power is discovered.', 41, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 7, 'Season 7', 'When Clark''s cousin Kara arrives on the scene, Clark advises her to keep a low profile and master her powers, but Kara has other ideas and becomes the focus of Lex Luthor''s powerlust. And, there are two Clark Kents: one is the young man whose life in a tiny Kansas town sets him on destiny''s path. The other is a Bizarro who shares Clark''s DNA, but not his values. Lane makes a career leap and Chloe Sullivan finds that balancing a meteor power with a personal life isn''t easy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 1, 'Bizarro', 'During Clark''s battle with the last Phantom Zone wraith, Lex is rescued by a mysterious woman. She then goes to the Kent farm and reveals she is Clark''s cousin, Kara, from Krypton.', 42, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 2, 'Kara', 'Clark and Lois meet Smallville''s newest arrival face-to-face, and she has some surprising news. Clark decides to leave Smallville and continue with his superhero training but Jor-el informs him that a new Kryptonian menace has arisen.', 41, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 3, 'Fierce', 'Kara takes to life in Smallville by getting a job at the Talon, and entering the Miss Sweet Corn Pageant as a contestant, overruling Clark''s objections. However, Lex takes an interest in her and three of the other contestants discover she has super-powers and decide to use her to steal a valuable time capsule.', 41, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 4, 'Cure', 'Dr. Curtis Knox says he can "cure" someone from being a "meteor freak," changing their lives. Chloe takes an interest in this, but Dr. Knox may have another secret.', 42, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 5, 'Action', 'When a movie is shot in Smallville, Clark is forced to secretly use his powers to save someone from a runaway car... but somebody is looking and becomes Clark''s biggest fan. Meanwhile, Lionel''s fate is revealed.', 42, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 6, 'Lara', 'Kara goes to Washington to look for her missing crystal, but is captured after she breaks into the lab.  She''s sedated with a truth serum that has kryptonite in it, which makes her relive a trip to Earth from the past.  In this past trip she followed Lara, Clark''s biological mother, to the Kent''s farm.  Clark saves Kara, but also ends up being affected by the serum when he burns it with his heat vision.', 42, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 7, 'Wrath', 'Lana absorbs Clark''s powers during a lightning storm, which she uses to break into Lex''s safe and steal some incriminating evidence.  After being turned away by Grant at the Daily Planet, who won''t accept her stolen evidence, Lana goes after Lex herself.  Clark tries to rescue Lex, but must first battle the super-powered Lana.', 42, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 8, 'Blue', 'Clark hears his mother''s voice trapped in Kara''s crystal, and releases her.  She gives him Jor-El''s ring made of Blue Kryptonite, which strips him of his powers.', 40, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 9, 'Gemini', 'A mysterious man who claims to be a product of Lex''s latest project plants a bomb on Chloe and uses her to force Lois to get the truth from Lex.', 42, '2007-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 10, 'Persona', 'Chloe begins to notice that Clark''s not acting like himself. Bizarro enlists the help of Brainiac.', 42, '2008-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 11, 'Siren', 'When Green Arrow''s band of heroes thwarts his efforts once too often, Lex employs a super-powered vigilante to take down the Emerald Archer.', 42, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 12, 'Fracture', 'Lex tracks the amnesiac Kara to Detroit, where Lois follows him. An obsessive busboy infatuated with Kara shoots Lex, and Chloe has to determine whether to heal him or not.', 42, '2008-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 13, 'Hero', 'Pete Ross returns to town and finds a number of surprising changes since his departure. Besides resolving his feelings toward Clark since he learned of his friend''s secret, Pete has to deal with the acquisition of a superpower of his own.', 42, '2008-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 14, 'Traveler', 'Lionel has Clark kidnapped, and when Chloe and Lana confront him, he makes them think Lex is the culprit.  Chloe and Lana then beg Jor-El to restore Kara''s memory because she''s the only person who can rescue Clark.', 42, '2008-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 15, 'Veritas', 'Clark must learn a new superpower as he and Kara join forces to take on Brainiac, putting the lives of their friends in danger.', 40, '2008-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 16, 'Descent', 'No one is safe when Lex seeks the secret of Veritas, and Clark tries to stop him.', 42, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 17, 'Sleeper', 'While Clark seeks out Brainiac to force him to fulfill his side of their bargain and restore Lana, Chloe and Jimmy go up against the government.', 40, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 18, 'Apocalypse', 'When Clark wonders if the world would be better off if he never came to Smallville, Jor-El shows him what life would have been like if he had never existed.', 41, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 19, 'Quest', 'After Lex is attacked by a mysterious stranger, he and Clark both discover the last surviving member of the Veritas group who holds the secret to controlling the Traveler.', 43, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 7), 20, 'Arctic', 'Lex is taken to the Fortress to fulfill his destiny, while Lana awakens from her coma and Chloe is arrested by the government.', 41, '2008-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 8, 'Season 8', 'Last season, Clark Kent and Lex Luthor became sworn enemies and Clark discovered more about his home planet, who his parents were, what his future holds and why he was sent to Earth. In season eight, Clark Kent is now reporter at the Daily Planet who shares a workspace with Lois Lane. And there''s a new hero in Metropolis - a hero everyone now calls the Red-Blue Blur.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 1, 'Odyssey', 'Green Arrow calls upon fellow heroes Black Canary and Aquaman to locate the missing Clark Kent, last seen in the Arctic. The Martian Manhunter also joins in to help out.', 43, '2008-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 2, 'Plastique', 'Chloe invites an injured 15-year-old to move in with her. Meanwhile, Clark experiences his first day of work with Lois.', 43, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 3, 'Toxic', 'When Oliver is poisoned, he starts having flashbacks to the period when he gained his archery skills... and met Tess. Meanwhile, Chloe has to make a decision which surprises Clark.', 43, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 4, 'Instinct', 'Tess and her team perform tests on the crystal she retrieved from the Arctic, causing it to send a beam of light into the universe; the beam of light triggers the arrival of Maxima, a queen from another planet looking for her soul mate.', 43, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 5, 'Committed', 'A heartbroken psychotic wearing a watch jeweled with kryptonite abducts Chloe and Jimmy and subjects them to a polygraph; while searching for them, Clark and Lois pose as a couple.', 43, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 6, 'Prey', 'Clark believes a recent attack in a theater may be the work of a serial killer; Davis fears that his blackouts could mean that he is the killer.', 43, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 7, 'Identity', 'Jimmy catches a red and blue blur on film when he takes a picture of Clark saving Lois from a mugger; after Tess decides to run the picture on the front page of the Daily Planet, Clark fears his identity will be discovered.', 43, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 8, 'Bloodline', 'Clark receives a package containing the crystal that Tess found in the Arctic; the crystal activates, sending Clark and Lois to the Phantom Zone, where they run into Kara (Laura Vandervoort); Zod''s wife, Faora, takes over Lois'' body.', 43, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 9, 'Abyss', 'Clark takes Chloe to the Fortress of Solitude so Jor-El can heal her after Brainiac replaces her memories with Kryptonian code.', 43, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 10, 'Bride', 'Unexpected guests crash Chloe and Jimmy''s wedding; Oliver thinks he has found Lex and sets out to confront him, but he is shocked to find Lana instead; Lois and Clark grow closer.', 42, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 11, 'Legion', 'The Persuader attacks Clark; Chloe, as Brainiac, tells Davis he is Doomsday and that he was created to destroy the "other Kryptonian" and the world.', 43, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 12, 'Bulletproof', 'Clark learns that John Jones was shot while working as a police officer; Lana tells Tess that Lex isn''t the man she thinks he is, forcing Tess to re-evaluate her position as head of Luthercorp.', 42, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 13, 'Power', 'Clark discovers that Lana is missing; Tess reveals what really happened to Lana when she woke up from her Brainiac-induced coma; Tess is shocked by what she discovers in a secret LuthorCorp facility.', 42, '2009-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 14, 'Requiem', 'An explosion at LutherCorp injures Oliver and kills all the board members.', 42, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 15, 'Infamous', 'Linda Lake returns to Metropolis and threatens to expose Clark’s secret unless he promises to give her exclusive information on the red-blue blur so she can become a star reporter again. Refusing to be blackmailed, Clark tells Lois his secret and asks her to write his story for The Daily Planet.', 43, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 16, 'Turbulence', 'Tess invites Clark to a press conference in New York but when an explosion rocks the private jet they are on, Clark must figure out how to save them without Tess learning his secret. Unbeknown to Clark, Tess orchestrated the explosion to get Clark to reveal his powers. Meanwhile, Davis discovers a surprising way to control the monster within.', 43, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 17, 'Hex', 'At Chloe’s birthday party, a mysterious magician named Zatanna grants Chloe’s wish to be more like Lois and switches the two into each other’s bodies. Zatanna searches for her father’s book of spells so she can conjure up his spirit but not before also granting Clark his deepest wish.', 42, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 18, 'Eternal', 'Tess tries to kill Davis by blowing up his truck. However, after he escapes, she realizes she needs help to destroy him and turns to Clark. Tess reveals Davis'' secret childhood with the Luthors and hints that she knows Clark''s true identity. Meanwhile, Davis runs to Chloe for help.', 43, '2009-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 19, 'Stiletto', 'Lois believes that she needs a big story to secure her reputation as a star reporter but the red/blue blur continues to elude her. However, after Chloe is mugged, Lois steps in to fend off one of the attackers and uses the opportunity to pretend a new superhero, Stiletto, has come to town and is giving exclusives to Lois. Clark is concerned Lois will hurt herself pretending to be a superhero but after he is captured by thugs with kryptonite, Lois steps in to save the day.', 43, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 20, 'Beast', 'Clark discovers that Davis is still alive and confronts Chloe about protecting him. Oliver discovers Jimmy breaking into Chloe’s apartment, but things get rapidly worse after Davis jumps from the shadows and attacks both of them.', 42, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 21, 'Injustice', 'Chloe returns and begs Clark to kill Davis, claiming he can no longer keep the beast under control.  Tess has assembled a team of meteor freaks, including Plastique, to track down Davis so Clark can kill him.  However, things get out of hand once Tess’ team discovers she is double-crossing them.', 43, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 8), 22, 'Doomsday', 'Oliver tells Clark he must kill Davis, as Doomsday is a serious threat and must be stopped at all costs.  However, Clark struggles with taking a human life, so the Green Arrow and his team decide to take matters into their own hands.  Lois takes on Tess, but the fight takes a shocking turn.  Meanwhile, Chloe gets caught in the middle of Oliver and Clark’s battle over killing Davis.', 43, '2009-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 9, 'Season 9', 'Last season, the enticing Tess Mercer maneuvered her way through town, discovered Clark''s true identity and unleashed a new world of danger. Clark, he also met his greatest match: Doomsday. When Clark wasn''t busy battling the beast, he was knee-deep in work at the Daily Planet. As Clark''s persona as the cub Planet reporter emerged, so did his feelings for Lois, the fated love of his life. In season nine, Clark Kent has to rise to the occasion as Zod and his followers scheme to take control of planet Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 1, 'Savior', 'Clark tells Jor-El he’s ready to start his training, but Jor-El sends him back to Metropolis to cut ties with Lois before he can begin.  Chloe is shocked when Lois suddenly reappears after having been missing for weeks, but Lois has no recollection of vanishing into thin air with the Legion ring.  Chloe begs Clark to use the Legion ring to go back in time to save Jimmy, but he refuses, driving a wedge into their friendship.  Meanwhile, Zod arrives at the Luthor mansion...', 42, '2009-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 2, 'Metallo', 'After being struck by a truck, John Corben wakes up alone in an abandoned apartment as a man-machine with a Kryptonite heart. Corben realizes he now has superhuman strength and sets out to exact revenge on the Red-Blue Blur, who he perceives to be an irresponsible vigilante. Against Clark''s wishes, Lois involves herself in the Red-Blue Blur''s investigation, and winds up getting kidnapped by Corben.', 42, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 3, 'Rabid', 'Zod and his soldiers release a virus into the air that turns humans into zombies.  The only way to stop it is to make an antidote from the blood of another Kryptonian.  After Lois is infected, Chloe pleads with Clark to donate his blood to stop the epidemic, even though it risks outing him to Zod.', 42, '2009-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 4, 'Echo', 'Tess forces Oliver to come to a Queen Industries gala to put the Board at ease, but things go awry when the Toyman shows up with a bomb and a plan to take revenge on Oliver. The Toyman tells Oliver he must confess to murdering Lex or he will blow the place up. Meanwhile, as part of his training, Jor-El gives Clark the ability to hear other people’s thoughts.', 42, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 5, 'Roulette', 'Oliver is drugged and kidnapped by a woman named Victoria AKA Roulette, who tells Oliver that he’s involved in a dangerous game and must fight for his life.  After Victoria shows up dead and Oliver is arrested by the police, he turns to Chloe for help.  Meanwhile, Lois berates Clark for not telling her about Oliver''s suicide attempt.', 42, '2009-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 6, 'Crossfire', 'Oliver tries to help a young street girl, Mia AKA Speedy, get out of her dangerous life by offering to train her, but Mia double crosses him. Lois asks Clark to help her land a job as an on-air television host, but the two are shocked when the station wants to hire them as a team.', 42, '2009-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 7, 'Kandor', 'Jor-El mysteriously arrives at the Kent farm searching for his son, Kal-El, but meets Chloe instead. Convinced the Blur is Jor-El, Zod enlists Tess’s help in finding him to force him to reveal the secret to his powers. Clark realizes Jor-El is alive and on Earth and races to find him before Zod does.', 42, '2009-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 8, 'Idol', 'DC Comics’ “The Wonder Twins” Zan and Jayna show up in Metropolis to help The Blur fight crime but end up botching several rescues, landing Clark in hot water with the District Attorney’s office.', 42, '2009-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 9, 'Pandora', 'Tess kidnaps Lois to find out where Lois went after she disappeared for weeks. Lois''s memory of the future depicts a Metropolis under Zod''s rule and Clark powerless under the red sun, while Chloe forms a resistance group with Oliver. After learning of these future events, Clark makes an important decision about Zod.', 42, '2009-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 10, 'Disciple', 'Oliver''s past comes back to haunt him in the form of The Dark Archer, Oliver''s former teacher, who seeks revenge on his student by taking aim at Lois and Chloe. Oliver faces down The Dark Archer after his former mentor kidnaps Mia AKA "Speedy" but is pushed to his limit and Clark races to stop him from making another deadly mistake.', 42, '2010-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 11, 'Absolute Justice', 'A man named Sylvester Pemberton tracks down Chloe and tells her he knows about her team of superheroes and needs their help. However, before he can explain who he is, he is attacked and killed by Icicle. Clark and Chloe''s investigation leads Clark to the former headquarters of the Justice Society of America where he meets up with Nelson AKA Dr. Fate, Carter Hall AKA Hawkman and Courtney AKA Star Girl. Courtney pleads with Hawkman and Dr. Fate to help her catch the killer that is targeting their group but they are reluctant to resume their duties as superheroes. Clark, John Jones, Green Arrow and Chloe team up to help the JSA stop Icicle before he murders another member of the group. Meanwhile, Lois receives a package from a mysterious agency called Checkmate, run by Amanda Waller.', 84, '2010-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 12, 'Warrior', 'Clark meets Zatanna at a comic book convention, where she tells him her father charmed a copy of the comic book "Warrior Angel" and it holds magical powers. A young man named Stephen steals the comic book and develops super powers, transforming himself into Warrior Angel and saving Chloe from a horrible accident.', 42, '2010-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 13, 'Persuasion', 'It is Valentine’s Day and while Clark is out on a date with Lois, he unknowingly becomes infected by gemstone kryptonite, which has magical wish-fulfilling properties. Clark mentions to Lois that he wishes they had a more traditional relationship,so Lois quits the Daily Planet, moves in with Clark and starts planning their wedding. Still unaware of his new power, Clark also casually tells Chloe he wishes she would spend more time watching out for him, so an infected Chloe takes his wish to heart and sets her sights on a new target – Lois.', 42, '2010-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 14, 'Conspiracy', 'Bernard Chisholm, a doctor who died and was brought back to life by the Kandorians so they can experiment on him, escapes and kidnaps some Kandorians in order to prove aliens have invaded Earth. Bernard tries to get Lois to write a story validating his claim, but when Lois refuses, he kidnaps her too. In an effort to save his people, Zod poses as a reporter from the Daily Planet and uncovers Bernard’s secret lab. Clark arrives at the lab just in time to see Zod get shot.', 42, '2010-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 15, 'Escape', 'Clark and Lois head out of town for a quiet romantic getaway, but their plans are thwarted when they run into Chloe and Oliver at their Bed & Breakfast Inn. The couples'' awkward moment is interrupted by the arrival of the Silver Banshee, who sets her sights on Clark and Oliver.  Meanwhile, Tess faces off with Zod with a surprising result.', 42, '2010-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 16, 'Checkmate', 'Tess creates an elaborate hoax in order to kidnap Green Arrow, and delivers him to Amanda Waller, who tells him that that the government is recruiting him to serve his country.  However, Green Arrow escapes before they can reveal his identity.  After Oliver brings Clark and Chloe up to speed, the three investigate and Clark is surprised to find John Jones investigating Oliver''s kidnapping too. Clark senses that John is keeping information from him.  Oliver and Clark are shocked when Tess reveals that Amanda is after something called "Watchtower."  Waller threatens to kill Chloe unless Clark gives her the names and locations of the rest of the Justice League.', 42, '2010-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 17, 'Upgrade', 'Zod continues to pose as "The Blur" and asks Lois to investigate one of Tess'' secret labs.  An explosion rocks the lab, and Lois is rescued by John Corben who was a subject of multiple experiments.  While investigating the explosion, Clark is exposed to red kryptonite.  And infected Clark takes Zod to the Fortress.  Tess turns to Chloe for help and they send in Corben to stop Clark from revealing all his secrets.', 42, '2010-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 18, 'Charade', 'Lois investigates the early prison release of ex-District Attorney Raymond Sacks but he threatens her with a gun when confronted. The Blur saves her, but is captured on film by a delivery guy who plans to sell the photo to Sacks. Lois and Clark each attempt to thwart the delivery of the photo and run into Maxwell Lord, a wealthy tycoon and Checkmate operative, who is trying to learn The Blur''s identity to eliminate him. Meanwhile, Chloe discovers Zod''s secret.', 42, '2010-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 19, 'Sacrifice', 'Tess breaks into Watchtower, triggering an elaborate security system that Chloe installed, ultimately trapping the two women inside.  Clark realizes Zod has given his soldiers super powers.', 42, '2010-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 20, 'Hostage', 'Much to Clark''s surprise, Martha Kent returns to Smallville with her new boyfriend, Perry White in tow. Lois and Perry realize they are both working on the same story about the Red Queen, and decide to team up, which ultimately puts them in serious danger. Chloe helps Clark search for the Book of Rao, which they believe contains information on how to stop Zod and his army.', 42, '2010-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 9), 21, 'Salvation', 'When Zod and the Kandorians launch their brutal attack on Earth, Chloe calls in some old friends to join the fight against the aliens.  Clark and Zod face off in an epic battle for the control of Earth.', 42, '2010-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')), 10, 'Season 10', 'As season nine drew to a close, Clark sacrificed himself to save the world from General Zod. In the tenth and final season, the timeless romance between Clark and Lois romance continues to develop, and Clark will come face-to-face with his destiny as he overcomes his final trials and forges the iconic identity that will be known for all time.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 1, 'Lazarus', 'Lois finds Clark''s lifeless body and removes the blue kryptonite enabling him to heal himself. However, Lois sneaks away before Clark fully awakens in order to protect his secret. Meanwhile, Chloe is desperate to find Oliver, so she turns to an unlikely source for answers. Jonathan returns to the Kent Farm with a message for Clark, and Tess awakens in a LuthorCorp lab.', 42, '2010-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 2, 'Shield', 'After Lois departs for Egypt, the Daily Planet hires a new reporter by the name of Cat Grant to take her place.  An assassin named Deadshot takes aim at Cat but Clark learns the man has a dangerous hidden agenda that involves The Blur.  Meanwhile, Carter Hall turns up in Egypt to keep an eye on Lois and he tells Lois about his wife Shayera.', 42, '2010-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 3, 'Supergirl', 'Clark is stunned when Kara returns to Earth and tells him Jor El sent her to stop the dark force that is coming because he doesn’t believe Clark can handle it. Meanwhile, Lois confronts Gordon Godfrey, a shock jock radio DJ who has been crusading against heroes, after he threatens the Green Arrow. However, after Godfrey is possessed by the dark force, he takes Lois hostage and Clark and Kara have to come to her rescue.', 42, '2010-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 4, 'Homecoming', 'In an attempt to cheer up Clark, Lois convinces him to attend their five-year high school reunion. A visit back to the home of the Crows has Clark remembering old times with Lana and Chloe, while Lois is furious that no one remembers her five days as a student. Brainiac 5.0 uses his Legion ring to visit from the future and takes Clark through his past, present and future. He shows Clark what really happened the night Jonathan died, Oliver’s current pain and Clark’s future at the Daily Planet with Lois and his role as Earth’s favorite red and blue superhero.', 42, '2010-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 5, 'Isis', 'Lois decides to tell Clark she knows he’s The Blur, but she accidentally activates an ancient artifact that transforms her into the Goddess Isis, complete with superpowers of her own.  Oliver and Clark reluctantly decide to ask Tess for help with Lois.  Meanwhile, after Cat Grant witnesses Lois as Isis using her superpowers, she decides Lois is the Blur and sets out to prove it.', 42, '2010-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 6, 'Harvest', 'Clark is concerned about Lois’ safety so he diverts her away from covering the Vigilante Registrations Act by suggesting she cover another story. After he comes clean with her, an angry Lois tells him that she can take care of herself, but when a flat tire strands their car in the middle of nowhere, their plans take a turn for the worse and Lois ends up in serious danger.  Meanwhile, Tess searches for a cure for Alexander, who is rapidly aging.', 42, '2010-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 7, 'Ambush', 'The General and Lucy Lane decide to drop in on Lois and Clark for a surprise Thanksgiving dinner. Clark and the General get off to a rocky start after Lois’ father bashes the superheroes and tells Clark he is trying to pass a vigilante registration law. Meanwhile, in an effort to stop the vigilante registration act from being passed, Rick Flagg lies to Lucy in order to lure Clark away from the farm long enough for him to assassinate the General. Lois is torn between making her father proud and her love for Clark.', 42, '2010-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 8, 'Abandoned', 'Lois finds a video made for her by her mother, Ella Lane, before she died. After watching the tape, Lois makes a drastic decision about her relationship with Clark that takes her to the Fortress, where she comes face to face with Jor-El and Lara.', 42, '2010-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 9, 'Patriot', 'In an effort to protect the rest of the team, Oliver  decides to register for the Vigilante Registration Act to see what the government plans to do with the new law. As he suspected, it was a trap to lure superheroes to an undisclosed location where he is confined to a jail and subjected to a battery of brutal tests under the supervision of Col. Slade. Aquaman  and his new wife Mera team up with Clark to free Oliver. Lois is frustrated when Clark continues to push aside her offers to help the team and sets out to prove she can play with the big boys.', 42, '2010-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 10, 'Luthor', 'Tess acquires a Kryptonian box that once belonged to Lionel Luthor. When Clark accidentally activates the box, he’s transported to a parallel universe where Lionel found Clark in the cornfields instead of the Kents. In this universe, Clark Luthor is a murderer and Lois is engaged to Oliver and both of them hate Clark. Clark must be careful not to tip off Lionel that he’s not his son while trying to figure out how to get back to Earth where the monster Clark Luthor was transported in his place.', 42, '2010-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 11, 'Icarus', 'The VRA is in full effect and things take an unfortunate turn of events after the Green Arrow tries to stop a mugging but is attacked by citizens for being a super hero. Clark discovers that the civilians who attacked Oliver were all marked with a darkness tattoo. Carter Hall and Star Girl return to help Clark deal with Slade’s re-emergence after he kidnaps Lois.', 42, '2010-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 12, 'Collateral', 'Clark, Oliver, Lois and Dinah are released by the VRA after being captured at Hawkman''s funeral, but each of them have flashbacks of Chloe holding them against their will. When Chloe returns, Dinah warns the others that Chloe may now be a traitor. Oliver dismisses her concerns, but Clark is unsure if he can trust Chloe after she disappeared without an explanation.', 42, '2011-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 13, 'Beacon', 'Clark is surprised to see Martha on the news speaking at a pro-vigilante rally. However, surprise quickly turns to horror when he and Lois watch as Martha gets shot on national television. Meanwhile, Lionel reveals himself to the world and reclaims LuthorCorp from Tess and Oliver. Lois and Chloe decide to cheer Clark up by showing him videos from thousands of vigilante supporters professing their support for The Blur.', 43, '2011-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 14, 'Masquerade', 'Chloe and Oliver are mistaken for FBI agents investigating Desaad''s recent string of murders and the pair are kidnapped by Desaad''s minions.  Desaad tries to infect Chloe with the darkness.  Meanwhile, Lois tells Clark he needs to be more careful with his identity and suggests a disguise.', 42, '2011-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 15, 'Fortune', 'After Zatanna sends a magically spiked bottle of champagne to Clark and Lois for their bachelor/bachlorette parties, the gang blacks out after the toast, only to wake up the next morning and realize they can''t remember anything about the night before.', 42, '2011-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 16, 'Scion', 'Lionel and Tess go head to head in a battle for the Luthor name. Clark and Lois are stunned by Tess’ latest present to them.', 42, '2011-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 17, 'Kent', 'Clark is shocked to find a mirror box in the barn. Clark Luthor surprises him and sends Clark Kent back to the alternate reality where Clark runs into a very angry Jonathan Kent. Meanwhile, back in our reality, Clark Luthor visits Tess and tells her that if she doesn’t side with him he’ll kill her. Lois asks Emil to help her bring Clark back.', 42, '2011-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 18, 'Booster', 'After everything that happened with the VRA, Lois  tells Clark it’s best to make “Clark Kent” forgettable and awkward so people don’t suspect he’s The Blur.  However, the two are stunned when a fame-hungry superhero from the future, Booster Gold, sweeps into town and begins making saves and posing for press ops, completely winning over the city of Metropolis.  Booster begins his campaign to take The Blur’s place as the “World’s Greatest Superhero” and tries to charm Lois into writing a story about him, but she’s not having his antics and begins her own campaign for The Blur.  During one of Booster’s saves, an alien weapon in the form of a scarab falls from a truck and fuses itself to a boy named Jaime Reyes, turning him into the Blue Beetle.  Unfortunately, Jaime is unable to control the suit and Blue Beetle starts attacking Metropolis.', 42, '2011-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 19, 'Dominion', 'Tess learns that General Slade was found unconscious on a street corner, proof that someone has gained access to the Phantom Zone’s escape portal and sent him back.  Clark decides to return to the exiled land to make sure other phantoms are not fleeing and is furious when Oliver tricks Clark into taking him along.  With Clark’s powers gone, the two are immediately captured by the Zoners who take them to their new leader, Zod, who is thirsting for revenge on Clark for banishing him to this Kryptonian jail.  Meanwhile, Lois learns Clark trusted Tess with a secret, but didn’t tell Lois.', 42, '2011-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 20, 'Prophecy', 'Clark takes Lois to the Fortress to get Jor-El’s blessing for their marriage. Jor-El bestows a unique wedding gift on the couple – he gives Lois Clark’s super powers so she can see what it’s like to be him for a day. Unfortunately, the Toyman has returned to Metropolis, so Lois must go up against the notorious villain instead of Clark. Meanwhile, Oliver searches for the Bow of Orion, which he believes will remove the Omega symbol from his skull, and runs into Kara, who is also on a mission to stop Darkseid.', 42, '2011-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0279600')) AND numero_temporada = 10), 21, 'Finale', 'The story of Clark Kent culminates in this epic two-hour series finale as Clark takes the last step to becoming the Man of Steel.', 84, '2011-05-13');
