INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0286788', 'What a Girl Wants', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0330140'), 'PELICULA', 'An American teenager learns that her father is a wealthy British politician running for office. Although she is eager to find him, she realizes it could cause a scandal and cost him the election.', '2003-01-01', 'https://m.media-amazon.com/images/M/MV5BZjA2ODZkYTctNDQyZC00YjllLTk0ZmMtYjE1NTQ4OWM2NDY2XkEyXkFqcGc@._V1_.jpg');
