INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0285333', 'Alias', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0646440'), 'SERIE', 'Sydney Bristow agrees to become an international spy for a secret branch of the CIA. The secrecy complicates her social and love lives, but it''s nothing compared to what happens when she finds out her employer has no ties to the CIA.', '2001-01-01', 'https://m.media-amazon.com/images/M/MV5BNWE1OTkzNTItNWY2Yy00MjY5LWI2ZDktOWQ4YjE5MWJmNzEyXkEyXkFqcGc@._V1_.jpg');
