INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')), 1, 'Season 1', 'The first season of Alias premiered September 30, 2001 on ABC and concluded May 12, 2002 and was released on DVD in region 1 on September 2, 2003. Guest stars in season one include Sir Roger Moore, Terry O''Quinn, Quentin Tarantino, and Gina Torres.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 1, 'Truth Be Told', 'Sydney''s loyalties are tested after a tragedy exposes the dark side of her superiors and the underhanded doings of her own father.', 67, '2001-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 2, 'So It Begins', 'Sydney gets shocking info on her dad''s role in Danny''s murder and takes on a countermission against the SD-6 to bring down an arms dealer linked to a missing nuclear weapon. Meanwhile, Will begins to grow suspicious of his friend''s secret life; and Vaughn is taken off Syd''s case after his mishap puts the entire world in danger.', 46, '2001-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 3, 'Parity', 'A mission to steal an ancient sketch pits Syd against her sworn nemesis, a Russian agent who''s after the same target. But when the container holding the painting proves impenetrable, the two foes are forced to team up to satisfy their respective agencies. Meanwhile, Will begins to notice something very fishy about Danny''s murder; and Francie frets over her guy''s possible infidelity.', 43, '2001-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 4, 'A Broken Heart', 'Sydney and Dixon go on a dangerous case involving the safety of the United Commerce Organization. Francie confronts Charlie about his secret date with another woman, and Will continues to get closer to the truth about Danny''s murder.', 45, '2001-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 5, 'Doppelgänger', 'Sydney''s secret double agent status is jeopardized after she smuggles a biotech engineer into SD-6 from her mission in Berlin. Will meets a woman who confesses that she was having an affair with Danny shortly before his death. Vaughn informs Sydney that her father may be working for a third secret operative agency.', 46, '2001-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 6, 'Reckoning', 'Sydney goes undercover in a mental institution to get information from Shepard, a man who has been unconsciously programmed to be a deadly assassin. Meanwhile, after Sydney becomes convinced that her father was responsible for the death of her mother 20 years earlier. Will discovers the true identity of the woman who claimed having an affair with Danny and Francie is relieved to learn that Charlie is not having an affair other woman. Marshall finds the computer worm planted in the SD-6 mainframe by the CIA.', 45, '2001-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 7, 'Color Blind', 'While helping Shepard escape from the asylum in Bucharest, Sydney discovers the shocking connection he has with her past. Meanwhile, after tracking the computer virus secretly planted by the CIA, Sloane is confronted by Alliance representative Alain Christophe, who suggests that one or more moles may have infiltrated SD-6. Will continues to investigate the woman claiming to be Danny''s mistress and Sydney finds out the truth about her father''s involvement in her mother''s death 20 years earlier.', 45, '2001-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 8, 'Time Will Tell', 'Sydney must undergo an extensive lie detector test to satisfy Sloane''s frantic search for the SD-6 mole. Meanwhile, with nemesis Anna Espinosa following her every move, Sydney seeks out the connection that a device may have to the 500-year-old prophetic Rambaldi sketch. The mystery of Kate Jones deepens as Will continues to investigate Danny''s death; and Sydney discovers that a keepsake from her mother Laura contains more disturbing connections into Jack''s past alliances.', 45, '2001-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 9, 'Mea Culpa', 'Sydney''s life is placed in mortal danger when Sloane is informed by his superior that she is the SD-6 mole. Meanwhile, Dixon''s life hangs in the balance after he is shot on a mission, and Will realizes that his discovery of Kate Jones'' pin could uncover some unexpected information.', 46, '2001-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 10, 'Spirit', 'Sydney briefs her CIA handler, Agent Vaughn, on her recent captivity at SD-6 and is surprised when he unexpectedly gives her a Christmas gift. Meanwhile Jack has to find a way to save Sydney when he discovers that Sloane has ordered her tortured and killed for being the suspected SD-6 mole. Will may be making the mistake of his life when he begins to research a name heard on a mysterious audiocassette -- SD-6.', 45, '2001-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 11, 'The Confession', 'Sydney is grateful and proud of her father after he saves her life while on a case in Havana. But her admiration is short lived when Vaughn discovers further evidence that Jack may have been responsible for the deaths of over a dozen CIA officers many years earlier.', 45, '2002-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 12, 'The Box (1)', 'When armed intruders take over SD-6, led by McKenas Cole, a man bent on exacting revenge on ex-boss Sloane, Sydney and Jack must work together to save their colleagues. Meanwhile, Will fears that his investigation of SD-6 and its link to the murder of Eloise Kurtz is placing his life in jeopardy.', 46, '2002-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 13, 'The Box (2)', 'Vaughn disobeys orders and attempts to help Sydney and Jack avert the destruction of SD-6 headquarters and all its occupants. Meanwhile, McKenas Cole continues his vendetta against Sloane and searches for a mysterious device. A desperate but determined woman convince Will to continue his investigation of SD-6 and the imprisonment of David McNeil.', 46, '2002-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 14, 'The Coup', 'Sydney and Dixon are sent to Las Vegas to gather information from a K-Directorate agent who has ties to the group that attacked and nearly destroyed SD-6. Meanwhile, Sydney learns some shocking news about Francie''s fiancé, Charlie, Will begins his journey in discovering what SD-6 really is, and Jack continues to try to be more of a father to Sydney when he helps her decide whether or not to continue with graduate school.', 46, '2002-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 15, 'Page 47', 'Vaughn asks Sydney to use her friendship with Sloane''s wife, Emily, to gain access to a mysterious Rambaldi book which happens to be under lock and key in a safe at Sloane''s home. Meanwhile, Will is kidnapped and told to drop his investigation of SD-6 or risk the lives of his family and friends, including Sydney''s.', 46, '2002-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 16, 'The Prophecy', 'Sydney is tested by the DSR to discover her mysterious link to a chilling 500-year-old picture and prophecy foretold in a Rambaldi manuscript. Meanwhile, after uncovering the identity of the rogue group leader, "The Man," Sloane learns through fellow Alliance of Twelve member Edward Poole that a close friend may be in cahoots with the enemy.', 45, '2002-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 17, 'Q & A', 'While the FBI detains and questions Sydney about her past and possible ties to a mysterious Rambaldi doomsday prophecy, Vaughn and Jack must race to free her and find a way to clear her name before her cover is blown and SD-6 is made aware of the situation. Once the rescue op has been launched, in her quest to prove her innocence, Sydney shocks even her usually unflappable father when she makes a chilling discovery that may unravel the mystery of the 500-year-old prophecy – she finds proof that Rambaldi''s writings may hold more truth about an alleged weapon of mass destruction - and the fate of her own family.', 45, '2002-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 18, 'Masquerade', 'While on a case to track the activities of Khasinau, a.k.a. "The Man," Sydney runs into her ex-lover, Noah Hicks, who broke her heart and left without saying goodbye five years earlier. Meanwhile, Sydney tells Sloane that she wants to find her mother; Jack is ordered to see CIA psychiatrist Dr. Barnett to help him deal with his churning emotions after discovering that his wife may still be alive; and Will and Francie become suspicious of Sydney''s activities after finding one of her airline ticket stubs.', 46, '2002-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 19, 'Snowman', 'Sloane begins to question where Noah''s true allegiances lie, as passion ignites between Sydney and Noah. Meanwhile, Sydney continues to uncover new information about her mother, which disturbes Jack. A rogue assassin known as the Snowman is dispatched by K-Directorate to kill Khasinau, a.k.a. "The Man." Will and Francie confront Sydney about the mysterious airline ticket stub found in her jacket.', 46, '2002-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 20, 'The Solution', 'In order to catch Khasinau and get closer to finding her mother, Sydney and Vaughn set up an undercover transaction for a Rambaldi artifact with Khasinau''s representative, Mr. Sark. But Sydney''s cover may be compromised when a SD-6 agent is sent in to thwart the sale. Meanwhile, Will is enticed to continue his investigation of SD-6 when he learns the identity of one of his kidnappers. Emily tells Sydney that she knows about SD-6, which forces Sloane to make the most difficult decision of his life.', 45, '2002-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 21, 'Rendezvous', 'Will''s life is about to change as he is sent to find the person responsible for leaking information to him about SD-6. Meanwhile, Sloane finds himself on the cusp of finally tracking down Khasinau when SD-6 captures "The Man''s" right-hand man, Mr. Sark. Dixon becomes suspicious of Sydney''s activities.', 46, '2002-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 1), 22, 'Almost Thirty Years', 'In order to save Will''s life, Sydney and Vaughn must destroy a familiar looking Rambaldi device, while Jack makes a risky deal with Khasinau''s representative, Mr. Sark. Meanwhile, the CIA believes that one of their own is a mole for "The Man"; the Alliance comes to a decision regarding the fate of Emily Sloane; Dixon''s suspicions about Sydney intensify; and Sydney finds herself face-to-face with "The Man."', 46, '2002-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')), 2, 'Season 2', 'In the second season, plotting against rogue agency SD-6 keeps superspy Sydney Bristow almost as busy as negotiating a relationship with her long-lost mother and dealing with her growing feelings for CIA handler Vaughn. What Syd doesn''t know is that there are lots more changes (costume and otherwise) ahead of her... it''s going to be a long year!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 1, 'The Enemy Walks In', 'Sydney finds herself face-to-face with her mother, whose intentions for her daughter are made chillingly clear. Meanwhile Sydney continues her search for Vaughn, not knowing if he is dead or alive after being swept away by a wall of water in Taipei. Will''s life is forever changed when he learns the truth about SD-6 and Sydney''s life as a double agent. Dixon must decide whether or not to inform Sloane of Sydney''s suspicious activities.', 44, '2002-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 2, 'Trust Me', 'Sydney must decide whether her mother''s goodwill gesture was sincere or an attempt to kill her. Will witnesses Francie discussing her restaurant plans with a man whose affiliations are questionable, and Sloane is made a full partner in the malevolent Alliance of Twelve.', 44, '2002-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 3, 'Cipher', 'Sydney must outwit Sark in order to find a crucial piece of intel. Meanwhile, Jack faces Sydney''s mother for the first time in almost 20 years. Will finally meets Vaughn and Sloane is haunted by his wife''s death.', 44, '2002-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 4, 'Dead Drop', 'Sydney''s dealings with her mother lead Jack to take drastic measures to ensure his daughter''s safety. Meanwhile Will is confronted by a mysterious woman about resurrecting his story on SD-6.', 44, '2002-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 5, 'The Indicator', 'Sydney discovers a terrifying secret when she''s sent on a case to track down a new generation of weapons. Meanwhile, Vaughn suspects Jack of setting up Sydney''s mother to take a fall. Sloane tells Jack the truth about Emily''s death.', 44, '2002-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 6, 'Salvation', 'Sydney''s trust in her father begins to fade. Meanwhile, Sydney and Vaughn may have been exposed to a deadly virus while in Taipei; Sloane haunted by Emily''s death begins to unravel. Vaughn enlists Will to help research a case.', 44, '2002-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 7, 'The Counteragent', 'Sydney races to find a cure for Vaughn, but in order to find the antidote, Sydney must make a deal with Sark that could endanger Sloane''s life. Meanwhile, Will continues his research for Vaughn and discovers some disturbing inconsistencies involving 20-year-old standardized IQ tests.', 44, '2002-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 8, 'Passage (1)', 'Sydney, Jack and Irina must put aside their differences and go undercover as a loving family in order to seize six nuclear warheads from an unfriendly nation. Meanwhile, Sloane announces to a suspicious staff that Mr. Sark will be working with SD-6, and later he is contacted by an unknown group claiming that Emily is still alive.', 43, '2002-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 9, 'Passage (2)', 'While continuing on a mission to take control of six nuclear warheads, Sydney and Jack discover where Irina''s loyalties lie when she meets up with Gerard Cuvee. Meanwhile, Sloane informs the Alliance that Emily may still be alive.', 44, '2002-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 10, 'The Abduction', 'Jack meets Alliance counterintelligence head Ariana Kane, who is sent in to investigate Emily''s disappearance and to discover who is trying to blackmail Sloane. Meanwhile, Marshall is sent on his first mission with Sydney as his partner. Vaughn schedules Will to take a CIA psych test. Francie gets suspicious over Sydney and Will''s secretive behavior.', 44, '2002-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 11, 'A Higher Echelon', 'After completing his first mission with Sydney, Marshall''s life is placed in mortal danger. Meanwhile, Ariana Kane suspects Jack as being the prime suspect in the disappearance of Sloane''s wife. Vaughn learns the truth about Jack''s involvement in the murder of CIA agent Haladki and Sydney confides in Francie about her feelings for a fellow co-worker.', 44, '2003-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 12, 'The Getaway', 'While Alliance counterintelligence head Ariana Kane tracks Sydney in order to catch her fugitive father, Jack elicits Irina''s help in finding Sloane''s blackmailer. Meanwhile, Sydney and Vaughn risk exposing their covers to SD-6 when they share a romantic dinner together while on a case in France.', 43, '2003-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 13, 'Phase One', 'Sydney and Jack are confronted by the new director of SD-6 who replaces Sloane, whose whereabouts and intentions are unknown. Meanwhile, romantic sparks begin to fly between Francie and Will.', 44, '2003-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 14, 'Double Agent', 'Sydney, Vaughn and Jack must determine whether CIA agent Lennox is who he says he is after his deep cover mission is compromised.', 44, '2003-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 15, 'A Free Agent', 'Sydney must make a life-defining decision regarding her future with the agency, while Sloane re-emerges and continues his obsessive quest to piece together the mysterious Rambaldi artifacts - with the reluctant aid of a kidnapped scientist. Meanwhile, Dixon''s marriage is put to the test after he tells his wife the truth about his occupation.', 44, '2003-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 16, 'Firebomb', 'A mysterious Rambaldi device''s powers are finally revealed and Sloane has its secrets. Meanwhile, Vaughn begs Dixon to aid the CIA in rescuing Sydney, Will is called upon to participate in a crucial CIA briefing session, and Sydney senses that Francie is keeping secrets.', 44, '2003-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 17, 'A Dark Turn', 'Sydney begins to question where Vaughn''s allegiances lie when she learns through CIA Agent Yeager that he is under investigation by the Agency. Meanwhile Irina and a crucial Rambaldi manuscript are used as bait to try to catch Sloane, and Sydney welcomes Dixon to the CIA.', 44, '2003-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 18, 'Truth Takes Time', 'Sydney faces off with her mother, while Emily must decide whether to side with her husband or betray him.', 43, '2003-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 19, 'Endgame', 'Sydney defies her father in her attempt to rescue a kidnapped scientist, while Sloane, seeking revenge, becomes more dangerous than ever. Meanwhile, Francie manipulates an unsuspecting Will for his agency connections.', 43, '2003-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 20, 'Countdown', 'A Rambaldi artifact prophesizes that an apocalyptic event will soon take place, and Dixon''s grief leads Vaughn and agency psychologist Dr. Barnett to question his intentions, as his thirst for revenge on Sloane intensifies. Meanwhile Sloane receives a life-changing revelation from a mysterious monk in Nepal, Sydney and Dixon hunt for the killer who stole the heart from his victim.', 42, '2003-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 21, 'Second Double', 'Sydney begins to question Will''s identity when he''s arrested for espionage, under suspicion of being a double. Meanwhile Sark and Irina plot to recover the Rambaldi heart, and Sloane makes Jack a business proposal.', 44, '2003-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 2), 22, 'The Telling', 'Sydney finally confronts her mother, who reveals her true motivation. Sloane, for his part, begins to execute his new grand plan and Will struggles to figure out who''s behind his set-up.', 43, '2003-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')), 3, 'Season 3', 'Thrown for a serious loop in the final episode of season 2, CIA agent Sydney Bristow starts season 3 dealing with a life -- and memory -- left in shambles. Luckily she has her resourceful father and her trusty partner to offer assistance as she searches for the truth. But a new double agent may be closer -- and more dangerous -- than Sydney suspects.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 1, 'The Two', 'Sydney tries to piece together the last two years of her life and discovers the fates of her friends and family. She confronts Vaughn about his marriage and learns the shocking fates of Jack and Sloane. Meanwhile, she is granted temporary CIA clearance on a case that may help her regain her memory.', 44, '2003-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 2, 'Succession', 'Sydney''s search for her past leads to a jailed Sark, but their Q&A is cut short when he becomes the ransom for a pair of abducted CIA scientists, whose kidnappers may be tied to the murder of his father. Jack contacts an old friend of sorts for info on Sloane''s new world-peace project, and Vaughn makes a decision about his future as an operative.', 42, '2003-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 3, 'Reunion', 'Sydney and Vaughn are reunited again as a team to prevent Sark from destroying the nation''s satellite communications system. Meanwhile, Jack must find a way to stop Marshall from uncovering the identity of a familiar murderer. Sydney accompanies Vaughn and Lauren as they meet with Sloane to ask for a favor.', 42, '2003-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 4, 'A Missing Link', 'Sydney discovers a link to her missing two years in the form of Simon Walker, the dangerous and sexy leader of a group determined on retrieving deadly biological weapons. Meanwhile, Vaughn struggles with his own feelings of jealousy and longing while Sydney is on her mission, aware of the pressures his job is putting on his marriage to Lauren. Jack takes matters into his own hands to protect his daughter, purposefully revealing Sydney''s deadly secret to Dixon in order to preserve her position inside the CIA.', 44, '2003-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 5, 'Repercussions', 'While Vaughn''s life hangs in the balance, Lauren butts heads with Sydney after learning the part she played in his stabbing. Meanwhile, Sydney further questions Sloane''s allegiances after he is kidnapped by Kazari Bomani, a kingpin in The Covenant; Jack''s cover is jeopardized when he meets with Simon to dig up information on Sydney''s missing two years; and Marshall is sent on his second mission with Sydney, posing as a high-stakes, southern gambler.', 44, '2003-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 6, 'The Nemesis', 'Sydney''s emotions are turned inside-out when she comes face-to-face with Allison, Francie''s doppelgänger, who was presumed dead but is now a key figure in The Covenant. Meanwhile Lauren''s search for Lazarey''s murderer leads her closer to discovering a connection to Sydney, and Sydney begrudgingly is assigned as Sloane''s CIA handler.', 44, '2003-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 7, 'Prelude', 'Jack takes drastic measures to ensure that the NSC never finds out the truth about Sydney''s murder of a Russian diplomat. But his actions place a heavy strain on Vaughn''s marriage, as Lauren gets closer and closer to the truth about Sydney. Meanwhile, Sydney agrees to go on a mission with Sloane in order to thwart plans to obtain the operating system to a deadly weapon -- and she discovers an unlikely ally in the hunt for her missing two years.', 44, '2003-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 8, 'Breaking Point', 'When Sydney is taken into custody by the NSC, Jack and Vaughn have no choice but to ally themselves with Sloane to rescue her. But with only hours to spare before she is forced to undergo a radical surgery to recover her memories, they must put togther an extraction team, headed by freelance operative Brill (Richard Roundtree, "Shaft"). Meanwhile, Lauren faces an impossible choice -- side with the NSC, who she wants to believe is doing the right thing, or with her husband.', 42, '2003-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 9, 'Conscious', 'After making a shocking discovery in the desert, Sydney agrees to submit to an experimental procedure conducted by an eccentric doctor, designed to retrieve her lost memories. But while Jack and Vaughn look on, Sydney''s mind proves surprisingly resistant to letting her remember her missing time -- and the process of recovering it could end up killing her. Meanwhile, Lauren makes a great sacrifice in order to make her alibi believable to Lindsey after breaking Sydney out of NSC custody, and Sloane finds himself boxed in by an unlikely enemy -- one who wants to see Sydney Bristow eliminated permanently', 44, '2003-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 10, 'Remnants', 'The identity of the mysterious "St. Aidan" forces Sydney to pull a stunned Will out of witness protection. But the pursuit sends the two old friends on a collision course with Allison -- the woman who ruined both their lives. Meanwhile, a zealous Lindsey arrests Jack and Vaughn as conspirators in Sydney''s escape from NSC custody, Sloane, still under pressure from Lindsey, puts a plan in motion to eliminate Sydney, and Dr. Brezzel has an unpleasant run-in with Sark.', 44, '2003-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 11, 'Full Disclosure', 'Sydney finally learns the shocking truth about her missing two years from an unlikely source.', 44, '2004-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 12, 'Crossings', 'Jack contacts a mysterious woman with ties to Irina to help him free Sydney and Vaughn, who have been captured and face a North Korean firing squad. But Jack is faced with a curious conundrum when the woman tells him that she will not put the rescue plan in motion until he fulfills a favor - assassinate Sloane.', 44, '2004-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 13, 'After Six', 'Sydney and Vaughn are sent to retrieve the Doleac Agenda to gain an advantage over The Covenant. For this, Sydney and Weiss must convince rogue security systems designer Toni Cummings to help the CIA break into a Lethal Response System. Meanwhile, Sark approaches an unlikely ally to kill the Covenant''s Cell leaders.', 0, '2004-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 14, 'Blowback', 'While trying to retrieve a bomb, Sydney and Vaughn are ambushed by unidentified assailants. Meanwhile, Lauren and Sark continue to solidify their new partnership, Sloane divulges a dark secret to Dr. Barnett and Marshall shows the strains of new fatherhood.', 44, '2004-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 15, 'Façade', 'Sydney and Vaughn must convince bomb maker Daniel Ryan that they are part of The Covenant in order to find out where he has hidden one of his devices. But Sydney discovers that her ties to the bomber could lead him on a suicide mission.', 44, '2004-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 16, 'Taken', 'Sydney attempts to rescue Dixon''s kids after they are kidnapped by Sark, Lauren''s status as a double agent is put to the test when she learns that she has to work with her father, and Sloane is framed as a CIA mole.', 44, '2004-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 17, 'The Frame', 'Sydney and Vaughn must track Kazari Bomani down to get hold of a piece of the Rambaldi puzzle. Meanwhile, Jack reveals his suspicions to Senator Reed about his daughter Lauren''s allegiances, and Vaughn decides what to do about his marriage.', 43, '2004-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 18, 'Unveiled', 'Sydney and Jack warn a disbelieving Vaughn about their suspicions of Lauren being the CIA mole. Meanwhile, Bomani and Sark take possession of the Rambaldi machine, Sydney and Vaughn must stop a Covenant virus that''s crippling medical facilities around the world, Sloane''s secret is revealed to Jack, and Bomani begins to lose faith in Lauren''s ability to carry out her Covenant missions.', 43, '2004-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 19, 'Hourglass', 'After finding out that Lauren is working for the Covenant, Vaughn is told to keep up the façade of a happy marriage in order to keep tabs on his wife''s activities. But he''s in for a shock when he uncovers the truth about Lauren''s mother, Olivia. Meanwhile, Jack refuses to help exonerate Sloane of his crimes and put in motion a stay of execution, and a monk discloses the identity of the Rambaldi "Passenger" to Sydney.', 44, '2004-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 20, 'Blood Ties', 'After discovering the identity of the Rambaldi "Passenger," Sydney and Jack seek the aid of Sloane, to track the "Passenger" down. Meanwhile, after learning a secret about his father from Thomas Brill, Vaughn is kidnapped and tortured by Lauren and Sark, who are about to track "The Passenger" down themselves.', 43, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 21, 'Legacy', 'With the aid of Katya Derevko and CIA imprisoned security systems designer Toni Cummings, Sydney and Vaughn attempt to track down Sloane and Nadia. But Lauren and Sark are also in hot pursuit of them in order to uncover the secrets of Rambaldi. Meanwhile, Vaughn''s obsession with tracking down Lauren is beginning to consume him, Sydney and Vaughn turn the tables on an old foe, and Katya expresses her attraction to Jack.', 44, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 3), 22, 'Resurrection', 'Lauren stages a stunning betrayal to steal classified materials from the CIA. Meanwhile, Vaughn comes face to face with his darkest demons in pursuit of his wife; Nadia must decide whether or not she can trust her father, Sloane, in the pursuit of Rambaldi''s most priceless artifact; and Sydney receives a shattering revelation that will make her question everything - and everyone - she thought she could trust.', 43, '2004-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')), 4, 'Season 4', 'The action explodes in the phenomenal fourth season when Sydney leaves the CIA to join a powerful new Black Ops unit, having no idea of the reunion in store for her.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 1, 'Authorized Personnel Only (1)', 'Sydney quits the CIA and joins a Black Ops unit called "Authorized Personnel Only" alongside Dixon, Jack, Vaughn and... Sloane. Meanwhile, the truth Sydney found out in Wittenberg endangers her relationship with Jack, and eventually she reveals the awful truth to Vaughn.', 44, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 2, 'Authorized Personnel Only (2)', 'Sydney unwillingly teams up with her father to hunt down a modern-day samurai. Meanwhile, Nadia doesn''t want to go back to the spy business, but is forced to when Sydney''s life is jeopardized. Sydney finds out the reason behind Jack''s misdeed and Nadia makes an unsettling promise.', 44, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 3, 'The Awful Truth', 'Sydney must seduce a murderous arms dealer in order to track down a stolen NSA code-breaker. Meanwhile, Vaughn fears for Weiss''s life, and Sydney and Jack argue about telling Nadia the truth about her mother.', 42, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 4, 'Ice', 'Sydney and Vaughn go undercover to track down a deadly new bio-weapon. Meanwhile, Sydney is concerned about Vaughn not having yet put Lauren behind, and Nadia turns to a Jack to find out the truth about her mother.', 41, '2005-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 5, 'Welcome to Liberty Village', 'Sydney and Vaughn go undercover as a married couple so as to find a weapon that could bring back the Dark Ages. However, the neighborhood they''ve infiltrated is not as charming as it seems.', 42, '2005-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 6, 'Nocturne', 'After being infected with a hallucinogen, Sydney starts to lose touch with reality. Vaughn and Jack must rush to find an antidote before Sydney puts her life - and others next to her - into danger.', 43, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 7, 'Détente', 'While Sydney and Nadia argue about Nadia''s acceptance of Sloane''s fatherly concerns, Sloane worries about Nadia''s well-being when she and Sydney go undercover as wealthy, irresponsible young heiresses to uncover the whereabouts of a deadly chemical.', 41, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 8, 'Echoes', 'Sloane temporarily steps down as Director of his Task Force and gives Jack full authority over the next assignment, which involves Anna Espinosa, Sydney''s old foe. However, Anna turns the tables on APO when she captures Nadia and forces Sydney to do her biddings. Sydney tells Nadia about the Rambaldi''s prophecy which dictates that two sisters will fight and only one will survive. Meanwhile, Vaughn visits Sark and tries to trick him into helping them to catch Anna. In the end, one of the sisters is mortally wounded by Anna.', 43, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 9, 'A Man of His Word', 'While Nadia is in a coma, Sark is taken into APO to help them infiltrate Cadmus Revolutionary Front and retrieve the bomb, but in return he demands to see Lauren''s corpse and that Vaughn opens her coffin for him. Nadia may be the only person with the intel they need to intercept the bomb, so Jack is forced to prematurely wake Nadia from her coma, endangering her life, which doesn''t please Sloane when he finds out.', 41, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 10, 'The Index', 'Dixon enlists Sydney to help him prove that Sloane is double-crossing the CIA and using APO to steal the Blackwell Index, a master blackmail list, and to reconstruct the Alliance. Sydney makes her way into Sloane''s house so as to copy the encryption key from his secure phone and crack his calls. When Nadia finds her, she becomes disappointed in her sister. Meanwhile, Vaughn discovers something disturbing about his father when he visits his comatose uncle.', 43, '2005-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 11, 'The Road Home', 'Sydney must protect the life of a civilian, whom she unintentionally put in danger. Meanwhile, Jack plans a visit with an old friend, and Vaughn uncovers more disturbing secrets about his father.', 42, '2005-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 12, 'The Orphan', 'Nadia puts her own life - as well Sydney''s and Weiss''s - in danger after failing to unveil her past through a dangerous criminal. Meanwhile, Vaughn finds a person who is somehow connected to his father and Nadia as well.', 44, '2005-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 13, 'Tuesday', 'When a mission goes wrong, Sydney''s is placed in danger and Marshall is the only one who can save her. Meanwhile, Dixon is exposed to a deadly pathogen released inside APO.', 44, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 14, 'Nightingale', 'Sydney and Vaughn risk their lives trying to find out the truth about Vaughn''s father. Finally, we find out why Jack and Sloane seem to be conspiring together against Sydney and Vaughn.', 43, '2005-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 15, 'Pandora', 'In an attempt to talk to Sydney, Katya Derevko deliberately poisons herself and is temporally taken out from her cell. Once Nadia tells her sister about this, Sydney visits her aunt to tell her to stay away from Nadia. However, Katya unsettles Sydney by telling her that someone framed her mother as a means of getting her killed. Sydney sets off in search of the truth behind this story. Meanwhile, Vaughn becomes a rogue agent by getting involved with the people who might know his father''s whereabouts. In the end, he and Sydney find out that the man behind these two plots is no other than A. Sloane. However, things are not exactly as they seem to be.', 44, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 16, 'Another Mister Sloane', 'Sydney and Vaughn tell Jack about Sloane''s alleged involvement in Vaughn''s search for his father and Irina''s contract on Sydney''s life. After cornering Sloane, they both conclude that someone is framing him. The APO team set a trap to catch the fake A. Sloane, but they fail. Once they realize what "Arvin Clone" is after, Sloane suggests he should step down temporarily. However, Sydney reluctantly convinces him to stay on the case, since he may the only person able to anticipate "Arvin Clone''s" next move. But Nadia fears that this pursuit may revive her father''s past obsession – Rambaldi.', 43, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 17, 'A Clean Conscience', 'Nadia''s former caretaker, Sophia, has been severely beaten. She contacts Nadia and asks to meet her. Sloane is told by Sophia that she was beaten up, because someone is trying to track Nadia down, so he and Jack decide to tell their daughters the truth – Elena Derevko, the third and the most cruelest of the Derevko sisters, has been surveilling both Sydney and Nadia for a decade. Meanwhile, Jack''s doctor advises him to tell Sydney about his illness.', 43, '2005-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 18, 'Mirage', 'Jack''s illness has caused him to hallucinate about a cure. Sydney must recreate the time when Jack was working for the CIA and hid the only man who might be able to help him now. For this, Sydney must play her own mother. Meanwhile, Sophia moves in with Sydney and Nadia.', 43, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 19, 'In Dreams...', 'The team captures the Sloane Imposter and questions him to find a rare Rambaldi orchid. The real Sloane must relive a painful memory in order to get the Imposter to reveal the orchid location.', 44, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 20, 'The Descent', 'After a tactical group infiltrates the DSR and steals Rambaldi artifacts, CIA director Hayden Chase discovers that the alarms at the DSR were disabled from Nadia''s computer, allowing the raid to happen, and shows up at the apartment to question her. Soon Sloane and Jack arrive and suspect that Sophia, who had access to the computer while she was living with Syd and Nadia, is Elena Derevko. They follow her trail to a dead Rambaldi follower, a stunning betrayal, and a presumed dead family member...', 44, '2005-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 21, 'Search and Rescue', 'Rambaldi''s catastrophic endgame begins to fall into place as a giant version of the Circumference/Mueller device is found floating over city in Russia, driving the citizens made. After a wounded Dixon reveals that Irina is alive, Sydney, Nadia, and Jack set off to find her. Irina had been captured, and then duplicated using Project Helix, in order to give the impression that she was dead.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 4), 22, 'Before the Flood', 'Jack, Sydney, Irina, Vaughn and Nadia parachute into Sovogda. They''re supposed to dismantle a giant red ball turning people into zombies. At APO, Marshall and Weiss use the Blackwell Index to blackmail the Russian minister into giving them the access codes to a Russian satellite, they discover that Elena is uplinking the satellite. A CIA agent, Brodien reminds them that the Rambaldi device is broadcasting a subaudible frequency that physiologically alters people who drink it and it is irreversible. Elena learns of the APO team''s arrival.', 44, '2005-05-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')), 5, 'Season 5', 'The final season kicks off with a shocking revelation and never lets you catch your breath as superspy Sydney Bristow faces one mother of a challenge. Old enemies and favorite guests return for the action-packed series finale.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 1, 'Prophet Five', 'After learning that the man she has known as Michael Vaughn is under investigation and suspected of being a double agent, Sydney begins to question whether their business and personal relationship over the years had all been a lie.', 44, '2005-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 2, '...1...', 'Sydney teams up with Renée - a fugitive on the CIA''s most wanted list -- to track down the murderer of a close friend before the killer can strike again. Meanwhile, Jack enlists a reluctant new agent, Thomas Grace (Balthazar Getty), and Weiss struggles to decide whether or not to accept a promotion that would force him to leave his colleagues.', 43, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 3, 'The Shed', 'Sydney is forced to partner on a mission with new APO agent Thomas Grace. They discover that Rachel Gibson -- a spy suspected of being involved in activities against the U.S. -- has something shockingly in common with Sydney.', 44, '2005-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 4, 'Mockingbird', 'While Sloane awaits the outcome of his sentencing, Sydney''s life is put in grave danger when Gordon Dean discovers that Rachel is still alive.', 44, '2005-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 5, 'Out of the Box', 'Sydney and Tom discover that Renie has stolen the cryo container, and soon find themselves under siege by a group of mercanaries who want the contents of the container. Meanwhile, Sloane takes matters into his own hands to get himself back into APO.', 43, '2005-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 6, 'Solo', 'Rachel receives a little help from Syd for her first solo mission while Sloan is back at APO in frequent contact with Gordon Dean.', 43, '2005-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 7, 'Fait Accompli', 'Sydney and APO attempt to discover whom Gordon Dean is working for and what their end game is. Meanwhile, when the group claiming to have a cure for daughter Nadia continues to play mind games with him, Sloane struggles for control.', 43, '2005-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 8, 'Bob', 'Rachel and Sydney have to join forces with Julian Sark to prevent a deadly micropulse bomb from falling in the hands of a dangerous mercenary.', 44, '2005-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 9, 'The Horizon', 'Sydney teams up with Vaughn after being kidnapped and being placed in a hypnotic. What Sydney doesn''t know is that the kidnapper is a very familiar face with an obscure interest in her unborn child.', 43, '2005-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 10, 'S.O.S.', 'The entire APO gang is trapped inside the CIA offices and Weiss saves them. However, Weiss will not be returning to APO, he will just be helping the others on a mission to obtain information regarding Sydney.', 43, '2006-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 11, 'Maternal Instinct', 'Sydney gives birth to the baby, but Sloane may need something from the newborn. Nadia awakens.', 44, '2006-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 12, 'There''s Only One Sydney Bristow', 'One month after the baby is born, Sydney is taking time off from work. Will is what pulls her back in the field while she''s on maternity leave. The enemies realize that the best way to hurt Sydney is through her friends. Anna Espinosa also returns.', 43, '2006-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 13, '30 Seconds', 'While the gang starts to learn more about the Prophet 5, Sloane is distressed to learn that Prophet Five''s cure for Nadia is just as likely to kill her. Meanwhile, Devlin returns, the search for Anna Espinosa continues, Rambaldi''s prophetic Page 47 resurfaces, and Sydney offers Renée a job at APO.', 44, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 14, 'I See Dead People', 'Marshall reports to Jack that a microchip, found in Renée Rienne''s body, is etched with the name ''Andre Micheaux''. Peyton tells Sloane that Sydney is being sent to Nepal to meet with someone regarding the chip. Sloane sends Anna, now Sydney''s doppelgänger, to intercept. When Marshall discovers that the APO office is bugged, Jack frantically tries to reach Sydney to warn her before it is too late.', 43, '2006-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 15, 'No Hard Feelings', 'Sydney now posing as Anna, brings Peyton a microchip with a device hidden in it. Meanwhile Sloane finishes translating page 47 and reports that only the chosen one can complete the circle, which leads Sark and Sydney on a dangerous mission to a prison. Rachel finally discovers Tom''s secret about what happened to his wife.', 43, '2006-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 16, 'Reprisal', 'In the first part of [the] Alias two-hour finale event, ''Reprisal,'' Sloane takes Marshall and Rachel hostage in order to discover a crucial clue to Rambaldi''s ultimate endgame, as Sydney, Vaughn and APO race to stop him.', 44, '2006-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285333')) AND numero_temporada = 5), 17, 'All the Time in the World', 'Peyton tells Sloane that she has made a deal for the Rambaldi Sphere with an ally in China. Sloane arranges for stolen missiles to be sent to Hong Kong. Sloane''s plan is revealed to the APO members, who race to stop him before he can use the Rambaldi Sphere to put the plan in motion. But this all leads to a long awaited confrontation between Sydney and Irina.', 44, '2006-05-22');
