INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 1, 'Season 1', 'Counter-terrorism agent Jack Bauer attempts to stop the assassination of United States Senator David Palmer on the day of the California presidential primary, while those spearheading the assassination plot stop at nothing to exact revenge on Bauer and Palmer.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 1, '12:00 A.M.-1:00 A.M.', 'Moments after discovering his daughter, Kimberly, has snuck out of the house, Jack Bauer is called into work. As head of the CIA''s Los Angeles Counter Terrorist Unit office he''s told that an assassination attempt will be made within the next 24 hours on the life of presidential candidate David Palmer and it''s up to his team of agents to keep Palmer alive. Meanwhile, Jack''s wife, Teri, sets out to find their daughter.', 43, '2001-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 2, '1:00 A.M.-2:00 A.M.', 'Teri receives a phone call from Alan York who says his daughter, Janet, is a friend of Kimberly''s and is also missing, so the two parents join forces to try and find the girls. Even as Jack is secretly called out of the office and given an encrypted key card containing information on the Palmer hit that could lead him to a dirty agent within his organization, the explosion of a 747 over the Mojave Desert becomes yet another piece in the puzzle.', 42, '2001-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 3, '2:00 A.M.-3:00 A.M.', 'Kimberly and Janet realize they are in danger after it becomes clear that their two dates have kidnapped them. Despite the threat on his life, Senator Palmer sneaks out of his hotel to meet a reporter who has damaging information that could affect his campaign. Back at the office, Jack has Jamey, a member of his team, decrypt the key card.', 43, '2001-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 4, '3:00 A.M.-4:00 A.M.', 'Convinced Jack needs to be relieved of his command, one of his team members, Tony, calls George Mason who arrives and puts the CTU under lock-down. With the help of his second-in-command, Nina, Jack slips out and heads for an address listed on the key card. Once there he encounters a shooter who hints that Kimberly''s disappearance is part of a bigger plan. Meanwhile, the two boys deliver Kimberly to a man named Ira Gaines.', 42, '2001-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 5, '4:00 A.M.-5:00 A.M.', 'Jack follows the arrested shooter to the police station in hopes of interrogating him only to find that Mason has arrived and taken control of the situation. But when the shooter says he will talk only to Jack, Jack learns he must break the shooter out of jail in order to learn who has kidnapped Kimberly. Back at the hotel, Senator Palmer learns more about the threatened news leak that could hurt his campaign.', 42, '2001-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 6, '5:00 A.M.-6:00 A.M.', 'Jack meets Teri and Alan York at the hospital where Janet has been admitted. But their reunion is cut short when Jack receives a phone call from Gaines telling him to follow his instructions if he ever wants to see his daughter again. Back at CTU, a dead body found in a car trunk is identified as that of Alan York. When Nina calls Teri and asks her to pass this information on to Jack, Teri suddenly realizes she is also in danger.', 43, '2001-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 7, '6:00 A.M.-7:00 A.M.', 'Now, under constant surveillance from Gaines, Jack goes back to CTU where Nina inadvertently gets in the way of Gains'' plan. Teri tries to escape from York, but her call to CTU only brings more help for York. Meanwhile, Palmer tries to convince his family that they need to tell the press about a secret personal tragedy from their past before it''s too late.', 43, '2002-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 8, '7:00 A.M.-8:00 A.M.', 'In order to save his wife and daughter, Jack is ordered to deliver a briefcase to a man at Senator Palmer''s rally. Realizing this man must be the assassin, Jack struggles to find a way to protect both Palmer and his family. Back at the CTU, Nina and Tony think they have found the traitor within the midst.', 43, '2002-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 9, '8:00 A.M.-9:00 A.M.', 'Although he prevents Palmer''s assassination, Jack is taken into custody where his story of his kidnapped wife and daughter is not believed. Knowing his family will only be kept alive if he is free to help Gaines, Jack knows he must escape. Back at Gaines'' compound, Teri and Kimberly struggle to stay alive, while at CTU the traitor reveals that the whole unit has been wired so Gaines can watch their every move.', 43, '2002-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 10, '9:00 A.M.-10:00 A.M.', 'When a new boss, Alberta Green, takes over the CTU, Nina secretly continues to help Jack locate Teri and Kim while Jack tracks down investment banker Ted Cofell, a man who is mentioned on the decrypted key card. A shocked Senator Palmer learns that one of his associates may be willing to commit murder in order to protect his campaign.', 43, '2002-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 11, '10:00 A.M.-11:00 A.M.', 'A man named Andre Drazen contacts Gaines. Clearly disappointed that the morning''s events did not go as planned he threatens to relieve Gaines of his assignment. Across town, Jack kidnaps Cofell and, after hearing Cofell''s Serbian accent, has Nina break into an old case file profiling a secret mission Jack was on in Belgrade and Kosovo two years ago. Then Jack meets Cofell''s contact: the man who claimed to be Alan York.', 43, '2002-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 12, '11:00 A.M.-12:00 P.M.', 'While Green pressures Nina and Tony to reveal Jack''s whereabouts, York leads Jack to Gaines'' compound where Jack attempts to rescue Teri and Kim without backup from CTU. Meanwhile, Senator Palmer''s plan to prevent a murder fails and he begins to suspect his wife may have a hand in the conspiracy.', 43, '2002-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 13, '12:00 P.M.-1:00 P.M.', 'Jack confronts Gaines who, realizing he has failed Drazen''s assignment, chooses death over helping Jack. Back at CTU, Nina and Tony interrogate the mother of the traitor and learn of a secret bank account containing deposits from Belgrade. They also learn that additional assassins may be making their way to Los Angeles.', 43, '2002-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 14, '1:00 P.M.-2:00 P.M.', 'While Jack is questioned at the CTU, Teri and Kim are taken to the clinic to be examined. Meanwhile, certain he recognizes the name Jack Bauer, Palmer has Jack''s background investigated. When he discovers that Jack was the sole survivor of a secret mission that he authorized two years ago, Palmer becomes convinced Jack is out for revenge and insists on talking to Jack face to face.', 43, '2002-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 15, '2:00 P.M.-3:00 P.M.', 'After Jack convinces Palmer he is not trying to kill him, they go over the "Operation Nightfall" file. The goal of the operation was killing a man named Victor Drazen, and a startling piece of information in the file convinces Jack and Palmer that they are both being targeted. Meanwhile, a scare at the clinic results in Teri and Kim being whisked away to a safe house.', 43, '2002-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 16, '3:00 P.M.-4:00 P.M.', 'Jack learns that one of the assassins, Alexis Mecir, is actually Victor Drazen''s son and has become intimate with one of Palmer''s aides. In an attempt to find the man ordering the assassinations, the aide agrees to plant a tracking device in Alexis'' wallet. Back at the safe house, Teri and Kim discover their location is no longer secret or safe.', 43, '2002-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 17, '4:00 P.M.-5:00 P.M.', 'During their escape from the safe house Teri and Kim become separated, and the traumatic events of the day result in Teri passing out and then awakening with amnesia. Assuming her mother has been re-kidnapped, Kim conducts her own search for information concerning her mother''s abductors. When the plan to track Alexis backfires, Jack pretends to be Alexis in order to keep a rendezvous with one of Alexis'' contacts.', 43, '2002-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 18, '5:00 P.M.-6:00 P.M.', 'Against his family''s wishes, Senator Palmer decides to go public about the secret scandal surrounding his family. Even as Alexis'' brother, Andre, sends another assassin to the Bauer residence in hopes of finding Teri and Kim, a confused and scared Teri meets Dr. Parslow, a man who says they are good friends. Unaware of the danger Teri is in, he offers to give her a ride home.', 43, '2002-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 19, '6:00 P.M.-7:00 P.M.', 'Alexis'' contact turns out to be a power company worker who was being paid to shut off the electricity to a power grid out in the middle of an empty field. As Jack and Mason follow up on that lead, Kim''s search for information lands her in jail, even as Palmer''s press conference disclosure could ultimately put his own son in jail.', 42, '2002-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 20, '7:00 P.M.-8:00 P.M.', 'As Kim tries to get the police to call CTU, Jack discovers that the empty field where the power grid is located actually houses a secret underground government prison and that night''s scheduled arrival is none other than Victor Drazen, the man Jack supposedly killed two years ago. Now Jack''s convinced Victor''s sons are coming to break him out.', 42, '2002-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 21, '8:00 P.M.-9:00 P.M.', 'Jack''s fears are proven true when Andre Drazen breaks into the underground facility to rescue his father. With Jack as his prisoner Victor calls CTU, but Mason tells him he doesn''t negotiate with terrorists. Desperate to buy some time, Jack tells Victor that his son, Alexis, is still alive. Back at the police station the police finally let Kim go, but her drive to CTU doesn''t go as planned.', 42, '2002-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 22, '9:00 P.M.-10:00 P.M.', 'Jack has Nina connect Victor Drazen to a hospital phone so he can talk directly to Alexis. Nina then advises Palmer of the situation. Palmer urges Mason to arrange the exchange Drazen proposed: the return of Jack for the return of Alexis. Although Alexis is delivered, Drazen holds onto Kim and tells Jack he needs to do one last thing if he wants to see his daughter again.', 42, '2002-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 23, '10:00 P.M.-11:00 P.M.', 'Jack arrives at Palmer''s hotel with a phone on which Drazen will call and ask Palmer to unfreeze $200,000,000 of his assets. When Palmer tells Jack that Drazen knows that''s impossible, Jack grabs the phone and throws it off the balcony. It explodes seconds later. Realizing Drazen will never give up, Jack suggests having the television report that Palmer died in the explosion, leaving Jack to offer himself up in exchange for Kim.', 42, '2002-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 1), 24, '11:00 P.M.-12:00 A.M.', 'When Jack arrives at Drazen''s location, he calls and asks to speak to Kim. Andre angrily refuses and says that they known Palmer is not really dead. Stunned, Jack hangs up and immediately calls Nina to tell her there''s still a traitor inside CTU. Momentarily uncertain how to proceed, Jack is suddenly shocked into action when Nina calls back with tragic news.', 43, '2002-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 2, 'Season 2', 'The second season is set 18 months after season one. The season''s main plot follows the work of now-U.S. President David Palmer and agent Jack Bauer to stop terrorists from detonating a nuclear bomb in Los Angeles. Introduced into the situation is Kate Warner, a woman who ends up getting vital information related to CTU''s mission.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 1, 'Day 2: 8:00 A.M.-9:00 A.M.', 'It''s been a year since Jack lost his wife, and the emotional toll includes estrangement from his daughter Kim, who is now a live-in au pair for a troubled family. Jack is no longer with CTU, and no longer interested in that line of work - until he''s summoned directly by President Palmer. The situation: terrorists have planted a nuclear device somewhere in Los Angeles and plan to detonate it within 24 hours.', 52, '2002-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 2, 'Day 2: 9:00 A.M.-10:00 A.M.', 'Jack reestablishes his undercover identity to join a crew of suspected terrorists that may know something about the nuclear device planted in Los Angeles. Posing as career criminal Jack Roush, his only hope in proving his loyalty to them lies in the package he''s carrying. Meanwhile, President Palmer deals with a curious press, including one particularly skeptical reporter; Kim tries to protect Megan from her father; and Kate Warner follows up on suspicions about her sister''s fiancé.', 44, '2002-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 3, 'Day 2: 10:00 A.M.-11:00 A.M.', 'Jack tries to undermine Eddie''s mission to bomb CTU while George investigates intel leading him to the site of the nuclear bomb''s construction and Kim tries to make contact with her father by heading for CTU headquarters.', 44, '2002-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 4, 'Day 2: 11:00 A.M.-12:00 P.M.', 'George returns to CTU where he orders the medics to revive a badly injured Paula, who has vital information. Palmer comes down hard on Eric for his deception. Kim takes Megan to the hospital, but the staff accuses her of abuse. Jack locates the leader of the American terrorist cell. He learns that the woman who gave them inside information on CTU is an old enemy.', 45, '2002-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 5, 'Day 2: 12:00 P.M.-1:00 P.M.', 'George refuses to allow Jack to assist in Nina''s interrogation. Jack resorts to blackmail to change George''s mind. Palmer and Stanton meet with a Middle Eastern ambassador who may be in league with Second Wave. Tony visits the Warner home and questions Reza about his possible connection with Syed Ali.', 45, '2002-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 6, 'Day 2: 1:00 P.M.-2:00 P.M.', 'Jack begins his interrogation of Nina and pushes all boundaries in order to force her to divulge the name of her contact. Palmer is surprised and suspicious when his ex wife Sherry returns and claims to have information about a conspiracy against him from within his own administration. Kim and Miguel plan to kidnap Megan from the hospital in order to take her out of LA and away from the nuclear threat.', 45, '2002-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 7, 'Day 2: 2:00 P.M.-3:00 P.M.', 'Jack forces Nina to help with a sting operation against her contact in the hopes that he can lead them to the bomb. Palmer and Mike try to gage Stanton''s loyalty when they investigate the chopper crash. George has a final conversation with his son.', 45, '2002-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 8, 'Day 2: 3:00 P.M.-4:00 P.M.', 'Kim and Miguel are arrested and the police plan to take them back to LA. Tony questions Bob Warner at CTU and learns more about his government connections. Palmer discovers a traitor in his ranks when the journalist whom he was holding is set free. Nina pulls a deadly countermove, setting herself up as the main player in the search to locate the bomb.', 44, '2002-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 9, 'Day 2: 4:00 P.M.-5:00 P.M.', 'George pits Bob against Reza in hopes of learning which one is working with Second Wave. Sherry and Lynne clash over Palmer''s speech to the press. Kate is interrogated by Syed Ali, who believes she knows too much about the bomb. Jack and Nina fight off a group of renegade soldiers while waiting to be rescued from the crash site. They nearly escape when Nina takes Jack hostage and demands to speak to the President.', 44, '2003-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 10, 'Day 2: 5:00 P.M.-6:00 P.M.', 'Two traitors are uncovered. One is the mole in the Palmer administration who is working with Stanton. The other is the member of the Warner family who helped Syed Ali to bring the bomb into the country. Jack learns of Ali''s location and tries to rescue Kate. Kim and Miguel hatch an escape plan to stay out of LA, but the results are disastrous.', 44, '2003-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 11, 'Day 2: 6:00 P.M.-7:00 P.M.', 'Kate helps Jack to locate and identify Syed Ali. Palmer places Stanton under arrest, but he won''t break. Palmer realizes he must go to extremes to make Stanton talk. Kim hits her low point of the day when she encounters a cougar in the woods.', 43, '2003-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 12, 'Day 2: 7:00 P.M.-8:00 P.M.', 'Jack engages in a brutal contest of wills with Syed Ali. George questions Bob Warner to learn more about Marie''s motivations for helping the terrorists. Kim is rescued by a mysterious hunter who offers her asylum. Lynne receives a dire warning from Sherry.', 43, '2003-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 13, 'Day 2: 8:00 P.M.-9:00 P.M.', 'Jack and his men prepare for a confrontation with Stanton''s renegade soldiers as they converge on the bomb. Kim becomes suspicious of her host, but is forced to stay because of her status with the police. Stanton finally breaks down and gives Palmer some unpleasant news.', 43, '2003-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 14, 'Day 2: 9:00 P.M.-10:00 P.M.', 'Jack and Kate try to break Marie''s resolve so they can learn the location of the bomb. Palmer confronts his ex wife with the information that Stanton gave them. George finally steps down as director of CTU and hands the position over to Tony. Kim discovers her host''s deception.', 45, '2003-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 15, 'Day 2: 10:00 P.M.-11:00 P.M.', 'Palmer, Mike and Lynne discuss various ways to dispose of the ticking bomb. They conclude that the desert is the best place to set it off. Jack determines that one man must pilot the plane carrying the bomb. He chooses to fly the plane himself and bids a tearful goodbye to his daughter. Tony and Michelle become suspicious of a Middle Eastern diplomat who is asking questions about the evidence against Syed Ali. Palmer departs for Los Angeles so he can be on hand when news of the nuclear bomb reaches the public.', 45, '2003-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 16, 'Day 2: 11:00 P.M.-12:00 A.M.', 'Jack and Michelle question Syed Ali, who claims that the audio recordings are false. Palmer prepares to wage war against the three countries who were involved in the nuclear strike. Kim gets caught in a hostage situation. Jack is contacted by a man who wants to exchange information for Kate Warner.', 44, '2003-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 17, 'Day 2: 12:00 A.M.-1:00 A.M.', 'Jack meets with the surviving Coral Snake Commando, who demands Kate Warner in exchange for evidence about the recordings. Tony and Carrie spy on Michelle when he suspects that she is working with Jack. Mike and the Vice-President turn up the pressure on Palmer, when he expresses his doubts about the impending war.', 45, '2003-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 18, 'Day 2: 1:00 A.M.-2:00 A.M.', 'Jack, Kate and Wallace fight to escape from a deadly band of commandos. Palmer decides to take a stronger stance against the civil unrest resulting from the bomb explosion. Tony''s trust in Michelle is broken when he suspects her of betraying him. Kim''s worries seem to be over when she learns the charges against her have been dropped.', 45, '2003-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 19, 'Day 2: 2:00 A.M.-3:00 A.M.', 'Jack is captured and tortured by men who want the chip. Kate and Yusuf run into a group of angry rednecks before they can deliver the chip to CTU. Tony and Michelle share a tender moment after her brother flips out. Palmer leans towards holding off the attacks, while Lynne discovers a secret operation that the Vice-President is planning against Palmer.', 45, '2003-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 20, 'Day 2: 3:00 A.M.-4:00 A.M.', 'Jack finds an ally who may help him escape from Kingsley''s men. Lynne meets with foul play before she can warn Palmer of the conspiracy against him. Chappelle interferes with Tony''s efforts to assist Jack. Kate offers her captors money in exchange for the chip.', 44, '2003-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 21, 'Day 2: 4:00 A.M.-5:00 A.M.', 'Palmer''s cabinet invokes the 25th Amendment in an attempt to remove him from power. They place him on trial for his extreme actions during the nuclear bomb threat. Jack and Michelle work against the clock to prove that the evidence against the Middle East is false.', 45, '2003-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 22, 'Day 2: 5:00 A.M.-6:00 A.M.', 'Jack locates the man who forged the audio evidence, but his efforts to break him down are sabotaged by Sherry Palmer, who has a hand in the conspiracy. Kim returns to the Matheson home, where she discovers that her problems are far from over. Palmer searches for an ally who will help him get a message out to CTU. Tony and Michelle take Chappelle out of action when he hinders their efforts to help Jack.', 45, '2003-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 23, 'Day 2: 6:00 A.M.-7:00 A.M.', 'When Jack hits a dead end with his lead, he realizes he must persuade Sherry to help him get evidence against Kingsley. Things go awry at CTU when Division becomes suspicious of Chappelle''s absence. Michelle goes off-site to work with Jack. Mike and Prescott ask Palmer to aid them as the bombers get closer to their targets.', 44, '2003-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 2), 24, 'Day 2: 7:00 A.M.-8:00 A.M.', 'Jack and Sherry Palmer prepare for a dangerous meeting with the head of the war conspiracy at the L.A. Coliseum; David Palmer sits in as the Cabinet waits for confirmation of the Cypress Chip''s invalidity; the air strike on the Middle East draws nearer; the conspiracy goes to an old agent to put Palmer out of play.', 44, '2003-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 3, 'Season 3', 'The third season is set 3 years after season two. It takes place primarily in Los Angeles but also in northern Mexico when Jack Bauer meets a family of drug dealers. Throughout the day, Jack Bauer and President David Palmer attempt to stop the release of a deadly virus by Stephen Saunders – a former government agent.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 3), 1, 'Day 3: 1:00 P.M.-2:00 P.M.', 'Three years have passed since the events of Day Two. A van deposits a dead body outside the LA Health Unit. The body is infected with a deadly virus. Tony, now in charge of CTU, learns that this is a blackmail tactic to get the US government to release a drug lord, Ramon Salazar, whom Jack has just brought down, before Salazar''s brother releases the virus into LA.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 3), 2, 'Day 3: 2:00 P.M.-3:00 P.M.', 'Jack and Chase quarrel over Chase''s relationship with Kim.  Meanwhile, they learn of a lead to the possible whereabouts of the virus after raiding a crack-house.
