INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 4, 'Season 4', 'The fourth season is set 18 months after season three. Jack is now working for Secretary of Defense James Heller after being fired by CTU due to his heroin addiction. As the day begins, he gets caught up in an elaborate terrorist plot which involves James Heller and his daughter Audrey Raines.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 4), 1, 'Day 4: 7:00 A.M.-8:00 A.M.', 'Eighteen months have elapsed since the conclusion of Day 3. A commuter train bound for Los Angeles explodes. A man steals a suitcase from a passenger in the wreckage and then kills him.
