INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 4), 4, 'Day 4: 10:00 A.M.-11:00 A.M.', 'Jack acts as a bandit and takes hostages to buy Chloe more time to get satellite surveillance. Meanwhile, Chloe must confide in Edgar for help when Driscoll becomes suspicious. Behrooz discovers just how far his mother is willing to go to insure that their secret mission is successful. Heller and Audrey attempt to escape from Omar, while Driscoll uses her influence to deal with a personal crisis.', 45, '2005-01-10');
