INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 4), 24, 'Day 4: 6:00 A.M.-7:00 A.M.', 'As the missile speeds toward its destination, Mandy cuts a deal with Jack and the President to give up Marwan''s location in exchange for a full pardon on all of her crimes.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 5, 'Season 5', 'The fifth season is set 18 months after season four. Former Counter Terrorist Unit agent Jack Bauer begins the season, working as a day-to-day laborer at an oil refinery under the alias "Frank Flynn" in Mojave, California. On a monumental day in Charles Logan''s presidency, an anti-terrorism treaty with Russian President Yuri Suvarov is about to be signed when events take a tragic turn.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 1, 'Day 5: 7:00 A.M.-8:00 A.M.', 'The Russian and US Presidents are set to sign an anti-terror treaty when assassinations rock Los Angeles, a call from a distressed Chloe forces Jack into action and President Logan''s wife believes there may be a conspiracy.', 45, '2006-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 2, 'Day 5: 8:00 A.M.-9:00 A.M.', 'Jack and Chloe infiltrate Wayne Palmer''s penthouse where David Palmer was assassinated, in the hopes of finding a clue to his murder. Jack convinces Wayne to cooperate and finds some information in Palmer''s memoirs that leads him to the airport where the Russian president is about to land.  CTU and Secret Service attempt to capture Jack, but they only find Chloe as Jack and Derek slip through their grasp.  Martha tries to convince her husband that she received an important phone call from Palmer the night before his death, but a tape of their conversation seems to contradict her claims.  Jack goes to the airport to find a lead, but a group of renegade Russian terrorists take hostages, including Derek, before he can act.', 45, '2006-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 3, 'Day 5: 9:00 A.M.-10:00 A.M.', 'Jack conceals himself inside the airport hanger and surveys the Russian separatists, feeding information to Curtis and his assault team. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 4, 'Day 5: 10:00 A.M.-11:00 A.M.', 'Jack is captured by the terrorists, who use Derek as leverage to force him to compromise CTU''s assault operation.  Logan refuses to give into the terrorist demands as the time of the co-signing of the treaty draws near. Martha tries to tell her husband of the evidence she uncovered about her phone call with Palmer, but Walt interferes with her efforts.  A new representative from District arrives at CTU and begins to undermine Buchanan''s authority.', 45, '2006-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 5, 'Day 5: 11:00 A.M.-12:00 P.M.', 'Jack returns to CTU and has an emotional reunion with Audrey, while Curtis tracks the Russians and the stolen nerve gas. 
