INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 8, 'Day 5: 2:00 P.M.-3:00 P.M.', 'Jack poses as Rossler and manages to trace one of the canisters of nerve gas, but he goes against orders from the president when the terrorists target a shopping mall. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 9, 'Day 5: 3:00 P.M.-4:00 P.M.', 'Lynn orders Curtis to take Jack into custody for violating presidential orders, but Jack breaks away from Curtis when Nathanson contacts him through Audrey and offers information on the location of the nerve gas.
