INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 16, 'Day 5: 10:00 P.M.-11:00 P.M.', 'Jack and Wayne locate a source inside Logan''s administration who has information on Palmer''s assassination. But things get complicated when they learn that Henderson is using leverage to keep her silent. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 17, 'Day 5: 11:00 P.M.-12:00 A.M.', 'Jack and Wayne locate a recording that definitively proves Logan''s involvement in the terrorist conspiracy, but Henderson corners them in the hopes of destroying the incriminating tape. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 18, 'Day 5: 12:00 A.M.-1:00 A.M.', 'Jack shows Heller the incriminating recording in the hopes that he will help them take down Logan, but Heller has plans of his own that will save face for the presidency. Miles tricks Chloe into leading CTU to Jack and Audrey. Mike and Martha both become more suspicious of Logan''s actions, while Heller confronts the president with an ultimatum.', 45, '2006-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 19, 'Day 5: 1:00 A.M.-2:00 A.M.', 'Jack captures Henderson and attempts to force him to hand over the recording, but Henderson targets Heller to buy himself more time. Logan confesses his involvement in Palmer''s assassination to a distraught Martha. Miles traces Chloe to Buchanan''s home, but Hayes finds herself questioning Logan''s motives as CTU closes in.', 45, '2006-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 20, 'Day 5: 2:00 A.M.-3:00 A.M.', 'After stowing away aboard the flight containing Henderson''s contact and the incriminating recording, Jack finds himself having to deal with a pilot who refuses to cooperate.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 21, 'Day 5: 3:00 A.M.-4:00 A.M.', 'Jack searches for a safe place to land the plane when Logan gives orders to shoot it down. Hayes readies Bierko for a transfer to a secure facility, while Audrey receives some good news about her father. Logan becomes desperate as his plans start to unravel, but an unexpected ally at CTU turns the tables in his favor.', 45, '2006-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 22, 'Day 5: 4:00 A.M.-5:00 A.M.', 'Bierko escapes from the transport taking him to Division and uses his last canister of nerve gas for a surprise strike. Jack is forced to work with Henderson to find Bierko, but Henderson wants something in return. Logan takes drastic steps to deal with Aaron when he won''t go along with the cover-up.', 45, '2006-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 23, 'Day 5: 5:00 A.M.-6:00 A.M.', 'Jack and Henderson wage an assault on the submarine as Bierko prepares to launch an attack against L.A. Chloe brings in someone from her past to aid her. Martha and Aaron enlist Mike''s help in their plans to expose Logan.', 45, '2006-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 5), 24, 'Day 5: 6:00 A.M.-7:00 A.M.', 'Jack takes his fight directly to the President as he attempts to force a confession from him that will prove his involvement in the day''s events. Martha vents her hatred for her husband in front of the press as Logan gives a eulogy over Palmer''s body. Jack and Audrey share a tender moment when it seems the crisis has subsided, but Jack finds that his problems have only begun as his past catches up with him.', 45, '2006-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 6, 'Season 6', 'The sixth season is set 20 months after season five. Over the last 11 weeks before Day 6, the United States has been targeted coast-to-coast in a series of suicide bombings. A man named Abu Fayed agrees to give the U.S. the location of Hamri Al-Assad, the supposed terrorist mastermind of these attacks, in exchange for former CTU Agent Jack Bauer with whom he has a personal grudge.');
