INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 13, 'Day 6: 6:00 P.M.-7:00 P.M.', 'The search for Gredenko finds Jack hunted inside the Russian Consulate and a former President calling on his ex-wife.', 45, '2007-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 14, 'Day 6: 7:00 P.M.-8:00 P.M.', 'CTU''s satellite tracking system is compromised as a bomb-carrying drone heads toward an unknown city. Meanwhile, US forces prepare for a nuclear retaliation on the Middle East.', 45, '2007-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 15, 'Day 6: 8:00 P.M.-9:00 P.M.', 'Jack enlists the help of an autistic man in the search for Gredenko, and Sandra Palmer makes a fateful decision.', 45, '2007-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 16, 'Day 6: 9:00 P.M.-10:00 P.M.', 'Jack baits Fayed with Gredenko, while the President faces a challenge to his office.', 45, '2007-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 17, 'Day 6: 10:00 P.M.-11:00 P.M.', 'To find the remaining suitcase bombs, both Jack and the President set up bluffs.', 45, '2007-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 18, 'Day 6: 11:00 P.M.-12:00 A.M.', 'The Chinese want Jack to give them Russian nuclear technology, and the President wants the Vice President''s resignation.', 45, '2007-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 19, 'Day 6: 12:00 A.M.-1:00 A.M.', 'Jack goes rogue to save a woman, and the White House needs a fall guy for Fayed''s success.', 45, '2007-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 20, 'Day 6: 1:00 A.M.-2:00 A.M.', 'A missing computer circuit board: the Russians get wind of Chinese espionage, the White House must find a leak, and CTU interrogates an unlikely witness.', 45, '2007-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 21, 'Day 6: 2:00 A.M.-3:00 A.M.', 'Russian ire worries the White House, while the Chinese take on CTU, and the damaged circuit board is in surprising hands.', 45, '2007-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 22, 'Day 6: 3:00 A.M.-4:00 A.M.', 'Russia presses the White House, while Jack must try to thwart the Chinese and his oldest antagonist simultaneously.', 45, '2007-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 23, 'Day 6: 4:00 A.M.-5:00 A.M.', 'In order to prevent a war with Russia, the White House orders a trade of Jack''s nephew for the circuit board, and puts Jack in custody so he cannot stop the exchange.', 45, '2007-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 6), 24, 'Day 6: 5:00 A.M.-6:00 A.M.', 'Jack rushes toward his nephew and his oldest antagonist, as a Chinese sub and F-18s race for the same destination. Chloe faints. Can Jack find any peace?', 45, '2007-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 7, 'Season 7', 'The seventh season takes place 46 months after season six and two months after 24: Redemption. Jack Bauer is on trial for alleged crimes he committed while working for CTU. Senator Blaine Mayer has disbanded CTU and strengthened the policies of Allison Taylor''s administration against torture. Bauer is brought into another counter-terrorist operation when FBI agent Renee Walker interrupts the hearing to tell him about an imminent threat.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 1, 'Day 7: 8:00 A.M.-9:00 A.M.', 'Following events in 24: Redemption Jack is pulled from his senate sub-committee hearing to assist with the deadly domestic threat and the investigation of former colleague Tony Almeida, his new undefined role is to help secure the nation. Meanwhile, President Allison Taylor presides over the escalating time-sensitive dilemmas linked to the unrest in Sangala. Chloe O’Brian and Bill Buchanan are on hand this season as well as FBI Agents Renee Walker, Larry Moss, Janis Gold and Sean Hillinger to cope with the unthinkable events', 45, '2009-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 2, 'Day 7: 9:00 A.M.-10:00 A.M.', 'Since Jack Bauer has been pulled from his senate sub-committee hearing to assist with the deadly domestic threat and the investigation of former colleague Tony Almeida, his new undefined role is to help secure the nation. Meanwhile, President Allison Taylor presides over the escalating time-sensitive dilemmas linked to the unrest in Sangala. Chloe O’Brian and Bill Buchanan are on hand this season as well as FBI Agents Renee Walker, Larry Moss, Janis Gold and Sean Hillinger to cope with the unthinkable events', 45, '2009-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 3, 'Day 7: 10:00 A.M.-11:00 A.M.', 'With Tony in custody, Jack leads his interrogation, but is shocked when a code word Tony whispers in his ear leads to old friends and a plot much deeper than anyone in the FBI anticipated. Jack once again takes the law into his own hands when he breaks Tony out of the FBI''s custody to deliver him back to the terrorist faction. Renee asks FBI technician Janis Gold to try to uncover a possible leak in the agency, but Janis is terrified when her discoveries point to fellow analyst Sean Hillinger. Colonel Dubaku sends a message to President Taylor, insisting that the US withdraw its forces from Sangala or risk a terrible attack on their soil.', 45, '2009-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 4, 'Day 7: 11:00 A.M.-12:00 P.M.', 'Buchanan takes Jack to "CTU", a secret hideout where he and Chloe had been working with Tony to uncover the conspiracy within the US government. Tony had been undercover with the terrorists aiding Juma to discover the moles. Jack agrees to help get Tony back in play by joining Emerson''s crew himself.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 5, 'Day 7: 12:00 P.M.-1:00 P.M.', 'As the threat of terrorism escalates, Jack Bauer is forced to take matters into his own hands to avert the imminent crisis facing the country. Meanwhile, lives are on the line as conflicted Agent Renee Walker copes with the volatile investigation, and FBI honcho Larry Moss is forced to keep a closer eye on his team as the nation''s security is in jeopardy. At the White House, international stakes are raised and the First Gentleman proceeds with his personal mission.', 45, '2009-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 6, 'Day 7: 1:00 P.M.-2:00 P.M.', 'As Dubaku presses President Taylor to comply with his devilish demands, she contemplates if the administration should negotiate to avert a disastrous terror attack. Meanwhile, away from the White House and the threatening international crisis, the determined First Gentleman struggles with his ongoing domestic mission, and perilous FBI Agent Walker diverts the attention of her tense colleagues. With national security on the line, Jack Bauer has a formidable plan in hopes of shielding the country in the “Day 7: 1:00-2:00 PM” episode.', 45, '2009-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 7, 'Day 7: 2:00 P.M.-3:00 P.M.', 'As U.S. troops remain in position outside of Sangala, Dubaku seeks another high-value target using the CIP module. While the entire NSA scrambles to locate the breach, the situation rapidly escalates. Paranoid FBI Agent Janis Gold commands from her post, while Jack, Tony, Renee, Chloe and Buchanan follow leads.', 45, '2009-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 8, 'Day 7: 3:00 P.M.-4:00 P.M.', 'As the country reels from the recent terror attacks and faces the mounting global ramifications, the administration refuses to acquiesce and presses on with their disapproval of the Juma regime. As Jack Bauer and team head to the White House for a pivotal meeting with President Taylor, Dubaku raises the stakes when he threatens the First Family', 45, '2009-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 9, 'Day 7: 4:00 P.M.-5:00 P.M.', 'After eight hellacious hours of this terrible day have elapsed, the country remains on edge. President Taylor struggles with the painful circumstances facing the First Family, including her daughter Olivia (guest star Sprague Grayden). Meanwhile, a huffy Chloe faces-off against paranoid FBI Agent Janis Gold, while Jack and Agent Walker track leads through Washington, D.C. to eliminate the threat of another ruthless terror attack', 45, '2009-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 10, 'Day 7: 5:00 P.M.-6:00 P.M.', 'Jack and Renee Walker pursue Dubaku through the streets of Washington, D.C., with a little cyber help from Chloe. Meanwhile, the first family and the FBI are left reeling from incidents involving turncoat agents.', 45, '2009-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 11, 'Day 7: 6:00 P.M.-7:00 P.M.', 'Not even at the halfway point of this hellacious day, two planes have collided outside of D.C., there has been an attempt on a chemical plant in Ohio, the President’s husband’s life has been threatened and the nation remains at risk. When Dubaku’s evil plan escalates to his boss, General Juma (guest star Tony Todd), the stakes are raised and steadfast President Taylor faces a deepening foreign policy dilemma.', 45, '2009-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 12, 'Day 7: 7:00 P.M.-8:00 P.M.', 'Juma and his men take the White House by storm, killing most of the Secret Service and trapping Taylor and Jack in the saferoom. His efforts to extract her are thwarted until he is informed that the President''s daughter is in the White House as well.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 13, 'Day 7: 8:00 P.M.-9:00 P.M.', 'The siege on the White House reaches an explosive end after Jack and Bill work together to try and save President Taylor.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 14, 'Day 7: 9:00 P.M.-10:00 P.M.', 'Malevolent mastermind Jonas Hodges emerges as Jack Bauer''s latest adversary as the long, terrifying day ticks deeper into the night. Jack yields results from a surprise meeting, and the fight to avert additional terror attacks continues.', 45, '2009-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 15, 'Day 7: 10:00 P.M.-11:00 P.M.', 'Olivia Taylor, the President’s daughter, becomes increasingly involved in the day’s events, and the administration reels when a high-ranking official delivers devastating news.', 45, '2009-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 16, 'Day 7: 11:00 P.M.-12:00 A.M.', 'The game changes for Jack Bauer, and the FBI is forced to collaborate with other federal agencies. As the threat intensifies, the administration shakes things up and seeks a new perspective.', 45, '2009-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 17, 'Day 7: 12:00 A.M.-1:00 A.M.', 'As the day stretches into the middle of the night, Jack and the FBI formulate a plan to prevent further terror attacks. Events take an unexpected turn when the politics surrounding the administration expand beyond the White House.', 45, '2009-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 18, 'Day 7: 1:00 A.M.-2:00 A.M.', 'Jack Bauer endures the elements and fights on to prevent an attack that could change the country forever. As the catastrophic blow to the nation nears, Tony Almeida operates from the field and Kim Bauer, who was last seen in Season Five, returns. Meanwhile, the stakes are raised when the administration is faced with a blackmail scenario.', 45, '2009-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 19, 'Day 7: 2:00 A.M.-3:00 A.M.', 'As the nation remains vulnerable, Jack Bauer endures the worsening pathogen pain. The FBI deals with recent deadly developments while matters involving key players takes this day into a unexpected direction.', 45, '2009-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 20, 'Day 7: 3:00 A.M.-4:00 A.M.', 'The nation remains vulnerable as Starkwood mastermind Jonas Hodges (guest star Jon Voight) remains at the epicenter of the mounting terrorist threat. Meanwhile, the FBI and the administration scramble to provide security and justice, and Jack Bauer questions a key suspect', 45, '2009-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 21, 'Day 7: 4:00 A.M.-5:00 A.M.', 'While lives remain on the line, an emotional Chloe copes with the declining conditions. With only a few hours left in Jack Bauer’s day, the situation worsens when the politicking inside the White House corners the divided administration.', 45, '2009-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 22, 'Day 7: 5:00 A.M.-6:00 A.M.', 'Innocent lives remain in the line of fire as this terrifying day draws to a close. Jack is faced with an unthinkable situation while his perpetually imperiled daughter, Kim (guest star Cuthbert), gets involved. Meanwhile, the imminent threat stokes the heated rivalry between Chloe and Janis.', 45, '2009-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 23, 'Day 7: 6:00 A.M.-7:00 A.M.', 'Jack Bauer is forced to help Tony escape from custody, only to find Tony plans to use Jack to reconstitute the pathogen. Aaron Pierce and Ethan Kanin work together and discover Olivia''s role in Hodges'' murder. Kim Bauer takes down her captors, and works with Renee Walker to find her father.', 45, '2009-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 7), 24, 'Day 7: 7:00 A.M.-8:00 A.M.', 'Presented with the evidence of Olivia''s actions, President Allison Taylor is forced to make a decision between her family and the Presidency. Thanks to Kim Bauer, Janis, Renee and Chloe are able to save Jack and arrest Tony before he can kill Alan Wilson. With Wilson refusing to talk and Jack about to die, the fight is no longer in the field, it''s for the hearts and souls of Jack and Renee.', 45, '2009-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 8, 'Season 8', 'Set 18 months after season 7, the story arc involves Jack Bauer contending with assassination threats made during a peace conference between President of the United States Allison Taylor and President Omar Hassan of the fictional Islamic Republic of Kamistan (IRK). The season is set in New York City, with CTU''s New York City Office having been re-activated,');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 1, 'Day 8: 4:00 P.M.-5:00 P.M.', 'Jack is back, this time in New York City spending time with his granddaughter. However, when a former contact comes to him with vital information on an upcoming terrorist assassination attempt, Jack has no choice but to become involved and take the man to CTU. But to get to CTU, they first need to survive a whole bunch of terrorists all trying to kill them. Meanwhile, Chloe struggles to settle in at her new position at the upgraded CTU, and President Allison Taylor negotiates with Middle Eastern leader Omar Hassan over weapons inspections... unaware that Hassan is the assassins'' target. Also, a journalist named Meredith Reed is suspected to have direct ties with the on-going terrorist crisis.', 45, '2010-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 2, 'Day 8: 5:00 P.M.-6:00 P.M.', 'For the first time in New York City, Jack Bauer is reluctantly drawn into action as President Allison Taylor negotiates plans for international security with Middle Eastern leader Omar Hassan. As the 8th day keeps unfolding, we learn that CTU, now upgraded and operated by M.B.A.-schooled Brian Hastings, still has Chloe O''Brian, but also expert analyst Dana Walsh and systems analyst Arlo Glass.', 45, '2010-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 3, 'Day 8: 6:00 P.M.-7:00 P.M.', 'Jack Bauer becomes further involved in preventing an assassination attempt on visiting president Omar Hassan. As the crisis continues to escalate, the crew at the newly upgraded CTU is challenged by some unexpected complicated circumstances. Meanwhile, tensions run high when an explosive event jeopardizes international security.', 45, '2010-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 4, 'Day 8: 7:00 P.M.-8:00 P.M.', 'While the newly-upgraded CTU is challenged by some unexpected and complicated circumstances, Jack Bauer becomes even more involved in preventing an upcoming assassination attempt on Omar Hassan, a visiting President. Meanwhile, international security is jeopardized by an explosive event, and Jack is reunited with agent Renee Walker.', 45, '2010-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 5, 'Day 8: 8:00 P.M.-9:00 P.M.', 'Four explosive hours after being unwillingly drawn back into action, Jack Bauer reteams with a risky Renee Walker to track some very dangerous leads. Meanwhile, back at CTU, a desperate Dana Walsh faces tense and untimely circumstances, and emotions escalate when President Taylor learns of a larger looming threat that jeopardizes the peace accord with President Hassan.', 45, '2010-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 6, 'Day 8: 9:00 P.M.-10:00 P.M.', 'Undercover Agent Renee Walker confronts her painful past when attempting to broker a deal with a ruthless, but very well-connected German arms dealer. When CTU shifts its focus from the perilous circumstances surrounding Jack and Renee, lead analyst Dana Walsh comes up with a plan to quell her situation and Chloe O''Brian puts Arlo Glass in his place. As Jack and Renee’s undercover mission takes unexpected turns, the Hassan family turmoil has President Taylor reeling as the peace agreement is jeopardized.', 45, '2010-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 7, 'Day 8: 10:00 P.M.-11:00 P.M.', 'Despite averting the assassination attempt on foreign peacekeeping leader Omar Hassan, Jack Bauer''s day intensifies when he is forced to go further undercover to secure the unsecured enriched nuclear materials. As international delegates reconvene at the United Nations, President Taylor''s goodwill comes into question and CTU races against time to assist with the mission.', 45, '2010-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 8, 'Day 8: 11:00 P.M.-12:00 A.M.', 'President Taylor pressures CTU for progress while Jack''s perilous plan has operatives panicked. As the scope of the looming threat expands, the dynamic at CTU changes and the ongoing crisis worsens.', 45, '2010-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 9, 'Day 8: 12:00 A.M.-1:00 A.M.', 'As Jack''s day enters the early morning hours, the nation remains vulnerable, and President Taylor presses on with her international peace process. With the possibility of colossal failure facing CTU, attention turns to who is to blame, and things get personal when operatives take matters into their own hands.', 45, '2010-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 10, 'Day 8: 1:00 A.M.-2:00 A.M.', 'As the terror threat continues, the Hassan family turmoil fans the flames of the increasingly urgent situation. When Jack closes in on a person of significant interest, a tense meeting between President Taylor and Omar Hassan takes an unexpected turn as the global security stakes are raised.', 45, '2010-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 11, 'Day 8: 2:00 A.M.-3:00 A.M.', 'The clock races into the middle of the night when the threat of a devastating nuclear attack accelerates as Jack tracks an informed terror suspect who has an explosive strategy. Back at CTU, a key player grapples with being demoted, and the day takes an unexpected stressful turn when pesky parole officer Bill Prady enters the picture.', 45, '2010-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 12, 'Day 8: 3:00 A.M.-4:00 A.M.', 'While Jack and Cole team up in the field to shield New York from the calamitous threat, a hostage situation has CTU completely stressed out. Meanwhile, unrelenting parole officer Prady presses on in his investigation, and unexpected developments send the Hassan family into a major tailspin.', 45, '2010-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 13, 'Day 8: 4:00 A.M.-5:00 A.M.', 'As the imminent terror threat nears and CTU copes with the day''s explosive events, the onerous NSA intervenes. Conditions at CTU remain tenuous and field operatives find intense action when Jack Bauer leads them on a risky mission. Meanwhile, Chloe and Dana make game-changing moves.', 45, '2010-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 14, 'Day 8: 5:00 A.M.-6:00 A.M.', 'President Taylor''s vision of global peace has been foiled over the last 13 hellish hours, and the situation worsens when the imminent threat of mass destruction clarifies. As her idealistic nature becomes a point of contention, she tasks Jack Bauer with a crucial mission, and advisor Ethan Kanin returns in the heart-stopping.', 45, '2010-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 15, 'Day 8: 6:00 A.M.-7:00 A.M.', 'As dawn breaks over New York, President Taylor endures a game-changing setback as the threat of mass destruction looms. Meanwhile, President Hassan makes a shocking decision that surprises his loved ones. But before long, trusted confidantes will become enemies of the state, and it''s only the beginning of the betrayals that are to come as the race against time ticks over two pulse-pounding hours.', 45, '2010-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 16, 'Day 8: 7:00 A.M.-8:00 A.M.', 'President Taylor undergoes a game-changing setback; President Hassan makes a decision that shocks his loved ones; trusted confidantes become enemies of the state.', 45, '2010-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 17, 'Day 8: 8:00 A.M.-9:00 A.M.', 'As the country reels from the day’s devastating events, stalwart President Taylor attempts to resuscitate the peace agreement, the cornerstone of her administration. Much to her dismay, she is forced to solicit the services of disgraced former President Logan. Meanwhile, Jack Bauer makes an unprecedented emotional move that triggers the unthinkable, and back at CTU, Chloe is charged with new responsibilities.', 45, '2010-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 18, 'Day 8: 9:00 A.M.-10:00 A.M.', 'With only seven hours left in the series'' final harrowing day, Jack Bauer sets out to avenge the tragic life-changing events that he has endured. As things become even more personal for Jack, he heads to CTU for an intense meeting after learning of a devastating development. Meanwhile, on the verge of achieving peace on a scale that has eluded the world for generations, President Taylor becomes deeply conflicted when former President Logan sits down at the bargaining table.', 45, '2010-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 19, 'Day 8: 10:00 A.M.-11:00 A.M.', 'With only six hours left, the clock races toward the series finale as President Allison Taylor faces impossible choices and much to the dismay of CTU, she enlists a private security firm to complete a sensitive task led by Mark Bledsoe. Meanwhile, Jack calls in a favor to his old friend Rick Vickers before he embarks upon a crucial mission of his own.', 45, '2010-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 20, 'Day 8: 11:00 A.M.-12:00 P.M.', 'With only five hours left, the clock races toward the climactic series finale as Jack stops at absolutely nothing to avenge the emotional setback of losing his beloved partner Renee Walker. Meanwhile, the administration attempts to keep the historic and pivotal peace agreement on track as undermining forces surface.', 45, '2010-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 21, 'Day 8: 12:00 P.M.-1:00 P.M.', 'With only four hours left, a rogue Jack Bauer stops at nothing to determine who is behind the day''s most devastating events, and he uncovers an unexpected lead.', 45, '2010-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 22, 'Day 8: 1:00 P.M.-2:00 P.M.', 'As the clock ticks toward the climactic series finale, three hours remain and a ruthless Jack Bauer is on an unwavering mission to uncover the truth, which only complicates circumstances for President Taylor as she prepares for a signing ceremony. Meanwhile, President Logan comes face-to-face with a formidable foe, and Chloe leads CTU on a high-stakes collision course with Jack Bauer.', 45, '2010-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 23, 'Day 8: 2:00 P.M.-3:00 P.M.', 'Emotions run high as the harrowing day climaxes with resolute President Taylor closing in on a world-changing peace treaty and a vengeful Jack Bauer taking matters into his own hands for one last and unforgettable job.', 45, '2010-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 8), 24, 'Day 8: 3:00 P.M.-4:00 P.M.', 'Emotions run high as the harrowing day climaxes with resolute President Taylor closing in on a world-changing peace treaty and a vengeful Jack Bauer taking matters into his own hands for one last and unforgettable job.', 45, '2010-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')), 9, 'Live Another Day', 'Four years after the events of Day 8, Jack Bauer remains a federal fugitive. Meanwhile, amid growing concerns over the use of US military drones in combat, President James Heller pays a historic visit to London to negotiate a treaty to continue their basing on British soil. Having heard rumors of an imminent attack against Heller, Bauer resurfaces in the city, where he is apprehended by the CIA and forcibly recruited into joining their investigation, with the promise of amnesty in return for his co-operation. As forces within the White House conspire against him, Bauer realizes that the complexity of the plot extends beyond a presidential assassination, and that the consequences of a successful attack will alter the course of history. With the help of a disgraced CIA agent and a hacker collective preaching free information, he must confront an unseen enemy whose personal vendetta threatens to push the world to the brink of war.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 1, 'Day 9: 11:00 A.M.-12:00 P.M.', 'After four years off the grid, Jack is apprehended in London by the CIA – on the very day that President James Heller arrives. As the President faces political pressure over a US drone program run from a UK-based base, only disgraced agent Kate Morgan suspects that Jack''s capture was all too easy.', 45, '2014-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 2, 'Day 9: 12:00 P.M.-1:00 P.M.', 'Jack and Chloe are on the trail of a hacker who might lead them to whoever is behind an assassination attempt on President Heller... but Kate is hot on Jack''s trail.', 45, '2014-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 3, 'Day 9: 1:00 P.M.-2:00 P.M.', 'Kate Morgan continues her hunt for Jack, as President Heller prepares to address Parliament after a devastating attack. Margot Al-Harazi proves she is willing to sacrifice anything for revenge.', 45, '2014-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 4, 'Day 9: 2:00 P.M.-3:00 P.M.', 'The terror threat escalates as Jack heads for the U.S. Embassy with the CIA closing in on him. Meanwhile, Margot asserts her authority with unthinkable force; President Heller makes an impassioned speech to Parliament; and Kate takes matters into her own hands.', 45, '2014-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 5, 'Day 9: 3:00 P.M.-4:00 P.M.', 'An unlikely duo joins forces to forestall an impending attack. The terrorist reveals her demands. The President orders a military lockdown, but it may be too late.', 45, '2014-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 6, 'Day 9: 4:00 P.M.-5:00 P.M.', 'As the smoke clears after the devastating events of the first five hours, tensions between President Heller and Prime Minister Davies boil over, and one of them decides to take matters into his own hands. In the meantime, Jack proposes a plan to locate Margot by using someone unexpected as his unsuspecting bait. Back at the CIA in London, Jordan raises suspicions about Kate''s husband.', 45, '2014-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 7, 'Day 9: 5:00 P.M.-6:00 P.M.', 'Jack and Kate race to save the life of a player tied to the terror threat; Jordan faces a perilous mission; President Heller engages Margot to put an end to her attacks.', 45, '2014-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 8, 'Day 9: 6:00 P.M.-7:00 P.M.', 'Jack Bauer and President Heller endure the unthinkable to thwart the terror attacks of mastermind Margot Al-Harazi. Meanwhile, CIA agent Jordan Reed faces a life-or-death struggle and Kate takes drastic measures to track down Margot before it''s too late.', 45, '2014-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 9, 'Day 9: 7:00 P.M.-8:00 P.M.', 'Jack and Chloe have a plan in place to eliminate the terrorist threat before any more attacks rock London. With no time to spare and lives on the line, Jack and Kate pursue crucial leads in an attempt to gain the upper hand on the incredibly intense circumstances. Meanwhile, key players reveal their true colors. intense circumstances. Meanwhile, key players reveal their true colors.', 45, '2014-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 10, 'Day 9: 8:00 P.M.-9:00 P.M.', 'Jack Bauer''s harrowing day crescendos as he pursues final leads at all costs. The emotional toll of the day''s events escalates when Kate Morgan learns the truth about her husband and Audrey confronts Boudreau about his duplicity. Making matters incredibly worse, the scope of the terror threat widens and the potential devastation reaches new heights.', 45, '2014-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 11, 'Day 9: 9:00 P.M.-10:00 P.M.', 'Audrey pursues diplomatic channels to try to prevent a full-scale war. Meanwhile, Jack Bauer leads Kate Morgan and Mark Boudreau on a mission to locate their target before it''s too late and the world is changed forever.', 45, '2014-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285331')) AND numero_temporada = 9), 12, 'Day 9: 10:00 P.M.-11:00 A.M.', 'The clock ticks toward the final seconds of Jack Bauer''s most heroic day. As the world teeters on a terror plot of mass proportions, Jack and the team reunite one last time to avert an imminent international crisis. With little time left and the fate of the free world on the line, Jack is faced with an unthinkable and grave decision. Lives will be lost and the American administration will grapple with the day''s most devastating news as the clock stops.', 45, '2014-07-14');
