INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 1, 'My First Day', 'John Dorian, "J.D." to friends, is a boyishly handsome, self-deprecatingly funny, likeable guy who would be confident if he only realized his assets. Four years of medical school have prepared J.D. for his first day as an intern at Sacred Heart Hospital - but he has his doubts.', 23, '2001-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 2, 'My Mentor', 'J.D. tries to persuade a smoker patient to quit smoking in order to impress Dr. Cox, who is just feeling lonely in his opinion. Elliot''s attitude towards Carla annoys her, thus Turk is able to go on a date with Carla, when he convinces her to forgive Elliot.', 23, '2001-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 3, 'My Best Friend''s Mistake', 'J.D. begins to feel distant from Turk, when he leaves him abandoned every time that he tries to talk to him. Elliot fights with Kelso for calling her "sweetheart," and she seeks Dr. Cox''s advice. J.D.''s relationship with Elliot goes in a time race, when he has 48 hours to kiss her before he is put into her "Friend Zone."', 23, '2001-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 4, 'My Old Lady', 'The three interns are each assigned patients with various illnesses. Statistically speaking, one of the three is going to die. J.D.''s patient is 86 year old Mrs. Tanner, who is in renal failure. 20 year old David Morrison is Turk''s hernia patient and Elliot''s patient Mrs. Guerrero only speaks Spanish and might have lupus.', 23, '2001-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 5, 'My Two Dads', 'J.D. points out what seems to be a technical mistake to Dr. Kelso, but it was really an attempt of Dr. Cox to save a woman without insurance using a dead guy''s insurance. Dr. Kelso and Dr. Cox show J.D. their different ways of looking at medicine. Meanwhile, the Janitor intimidates J.D., Elliot discovers the healing powers of her boobs and Turk gives Carla a pen he thought he took from the Lost and Found box.', 23, '2001-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 6, 'My Bad', 'Dr. Cox is still facing the threat of suspension, and coincidentally, J.D. is assigned to a special patient: Jordan Sullivan, an important board member. She is very demanding and J.D. ends up sleeping with her after he confronts her. Only he didn''t know that she is Dr. Cox''s ex-wife, and now the only one who can save J.D.''s mentor from being fired by the evil Dr. Kelso. Meanwhile, Elliot is assigned to take care of a shrink whose jaw has been wired shut, and for whom she ends up becoming a patient. Carla''s mom makes a scandal after Turk spends the night at Carla''s, and when she breaks her leg, Carla blames Turk for it.', 23, '2001-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 7, 'My Super Ego', 'J.D. has finally earned the spot as brightest student, but he''s got competition: Nick Murdoch, who seems to be nicer, friendlier and has a better butt than him. But even J.D. can''t hate the guy, for he is so nice. But he is surprised when he finds Nick sitting in a corner crying because he can''t take the pressure of medical internship. Meanwhile, Turk is having problems at the operation table and doesn''t tell Carla, who keeps bothering Dr. Cox about it. And Dr. Cox gives Turk a very unique suggestion on how to calm down before surgery.', 23, '2001-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 8, 'My Fifteen Minutes', 'J.D. and Turk become heroes after saving a cameraman''s life on TV, while heading to a strip club. But Turk quickly becomes the target of a new publicity campaign led by Dr. Kelso, exploiting the hospital''s diversity. Meanwhile, J.D. worries about his evaluation. Elliot is going out with Carla, but in the last minute she blows her off and later Elliot runs into her in a bar.', 23, '2001-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 9, 'My Day Off', 'J.D. gets to see the hospital through the eyes of a patient when he''s admitted for appendicitis. Elliot examines him and he tells everyone how cold and rough she is, which drives her crazy. J.D. doesn''t want Turk to operate on him, which hurts Turk''s feelings. Meanwhile, Dr. Cox is trying to show off to his mentor, Dr. Benson, the ex-chief of medicine, who is also a patient at the hospital. The only thing in his way is Dr. Kelso, who almost dismissed Dr. Benson prematurely.', 23, '2001-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 10, 'My Nickname', 'J.D. begins a new relationship with Carla. J.D. gains a new nickname - "Scooter" - and his relationship with Nurse Carla evolves as he begins to out-distance her medical knowledge, while Turk trembles, when he learns that his secret lunch spot was claimed years ago by the territorial Dr. Kelso. Elsewhere, Dr. Cox gives Elliot the evil eye when she won''t discharge a troublesome patient.', 23, '2001-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 11, 'My Own Personal Jesus', 'It''s Christmas, and even though J.D. and the others don''t really feel like celebrating, Turk makes a huge deal about it. But his faith and happiness are gone after a very busy night at the hospital.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 12, 'My Blind Date', 'A woman slips and falls on the wet floor of the hospital. Afraid that she might sue the hospital, Dr. Kelso asks J.D. to stand by her and be friendly, so she won''t sue them. But J.D. is very busy with Dr. Cox''s 24-hour marathon to keep his ICU patients alive.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 13, 'My Balancing Act', 'J.D. is frustrated when his budding romance with an ex-patient wilts as their dates are constantly interrupted by emergency calls, while the beastly Dr. Kelso becomes less fearsome to the wide-eyed interns, when Dr. Cox informs them how to avoid the blowhard''s bite. In addition, a perplexed Carla and Turk deal with their first sexual intimacy complication.', 23, '2002-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 14, 'My Drug Buddy', 'Alex and Elliot argue over missing medication, and J.D. needs to choose sides.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 15, 'My Bed Banter & Beyond', 'After going to bed and spending an entire day having sex, J.D. and Elliot go to work trying to hide their new secret romance, but everybody already knows it.', 23, '2002-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 16, 'My Heavy Meddle', 'When a rampaging Dr. Cox suddenly shows up at his door in a strange funk, J.D. sees a possibility of a breakthrough in their relationship - until he learns that Cox loses control in almost an annual rite. Meanwhile, Turk elects to partner with Elliot on a research project so that he can maneuver her back with his buddy J.D., and Carla struggles to fulfill a comatose patient''s final request - playing heavy metal music in his room.', 23, '2002-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 17, 'My Student', 'J.D., Elliot and Turk are receiving their first medical students, and now they finally get a chance to see what it feels like to be on the other side. Turk''s student is a very attractive young woman, to whom Dr. Cox is immediately attracted. But he doesn''t know his way around women and needs Turk to give him a little help. J.D. doesn''t know how to handle his student and Elliot''s turns out to the be son of an important CEO.', 23, '2002-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 18, 'My Tuscaloosa Heart', 'J.D. has a patient who''s rude to him and the nurses and eventually dies from cancer. J.D. feels awful for not giving him his full attention and worries maybe he could have saved the guy if he was nicer to him.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 19, 'My Old Man', 'An assortment of moms and dads descend on their offspring at home and in the workplace. J.D.''s father is a gregarious yet lonely divorcee who''s desperately trying to be just one of the guys. Elliot''s folks, on the other hand, are a snooty couple whose pompous behavior dismays their daughter. Similarly rattled is Turk, unnerved by the bonding of his girlfriend, Carla, and his brassy mother. But the most vexatious parent by far is the janitor''s dad.', 23, '2002-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 20, 'My Way or the Highway', 'Turk''s competitiveness is starting to annoy J.D., especially when it crosses the line of personal jokes and comes to patient''s matters.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 21, 'My Sacrificial Clam', 'J.D. fears being contaminated with Hepatitis B, after a needle accidentally sticks his forearm.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 22, 'My Occurrence', 'Jordan''s brother Ben is admitted at Sacred Heart for having an accident with a nail gun. J.D. learns that Ben has leukemia, but won''t believe it, since there have been many mixups in the hospital lately, so he goes on a search for the real test results.', 23, '2002-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 23, 'My Hero', 'Ben takes the news of his diagnosis pretty well - at least better than his sister Jordan and J.D. Remarkably, it is Dr. Cox who is the voice of reason and compassion, until his own fears get in the way.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 1), 24, 'My Last Day', 'It''s J.D.''s last day as an intern, and soon he will become a resident. Carla and Turk are arguing about dating other people. Elliot finally rebels against being everyone''s doormat, and J.D. is just trying to stay out of people''s way.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 1, 'My Overkill', 'Relationships between the staff of Sacred Heart Hospital have been shaken since Jordan''s revelations. Turk is sleeping on J.D.''s bed, after Carla kicked him out of his own. Elliot is having a hard time facing J.D. every day at work. J.D. desperately tries to get Dr. Cox''s attention back, unsuccessfully.', 22, '2002-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 2, 'My Nightingale', 'J.D., Elliot and Turk find themselves alone in the hospital night shift and face responsibilities without supervision for the first time. Luckily, they have Carla there to support and guide them through the night.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 3, 'My Case Study', 'When Dr. Kelso challenges the residents by offering a trip to a medical conference in Reno as a reward to the individual, who presents the most interesting case study, J.D. refuses to play along, earning him the respect of Dr. Cox.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 4, 'My Big Mouth', 'J.D. insists that Carla should open up to him. When she finally starts to do that, J.D. screws it up by telling Turk. Elliot is desperate for attention from Dr. Cox. Turk sees himself in an ethical dilemma when Dr. Kelso picks him over a female surgeon to spend a weekend in Mexico.', 22, '2002-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 5, 'My New Coat', 'Elliot sleeps with a handsome doctor she hardly knew and soon becomes the hospital tramp. Turk suffers from his back after operating with Dr. Amato, a very short surgeon. J.D. finds out that wearing a white coat doesn''t make him a better doctor, but is upset by having Dr. Cox throw in his face that he made another mistake. And Dr. Kelso is just dying for an opportunity to lash out his anger on Dr. Cox.', 22, '2002-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 6, 'My Big Brother', 'J.D.''s brother is in town. Turk is thrown out of a patient''s funeral for not knowing his name and feels even worse because earlier he made a bet with Dr. Cox over another patient''s life.', 22, '2002-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 7, 'My First Step', 'All of the male doctors are euphoric due to the visit of Julie Keaton, the pharmaceutical sales rep, except for Dr. Cox, who still believes in treating patients for their best health, instead of trying to get some attention from the hot Ms. Keaton.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 8, 'My Fruit Cups', 'When an expectant Jordan shows up unexpectedly, Cox is forced to choose between her and his new love, Julie.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 9, 'My Lucky Day', 'Ever since her father cut her off financially, Elliot''s been feeling the weight of the world on her back. While having to find a new affordable place to live, she also has to face the threat of being sued by a patient whom she told he had only eight months to live. Carla and Jordan hit a sore spot when Carla gives her opinion on Jordan and Perry''s relationship.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 10, 'My Monster', 'Elliot still doesn''t have a place to live. J.D. think he''s lost his mojo when he can''t even kiss the giftshop girl while they go out on a date. Turk and Carla are having romance problems, because she feels he''s not being as generous to her as she is to him. And Dr. Cox freaks out when he lets Jordan move in to his place due to her pregnancy.', 22, '2002-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 11, 'My Sex Buddy', 'Renewed sex with J.D. calms Elliot, who''s facing personal and professional dilemmas: She''s broke, and patients are bailing out on her.', 22, '2003-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 12, 'My New Old Friend', 'Comeuppances are in store for Dr. Cox, Dr. Kelso and J.D. from a hypochondriac, a surgical patient and Elliot, who wants more than just sex from J.D.', 22, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 13, 'My Philosophy', 'J.D. bonds with a patient, who is waiting for a heart transplant and discusses with her their idea of what death must be like. Elliot puts her foot down and demands a feminine locker room from Dr. Kelso. Turk decides it''s time to propose to Carla, but a kid swallows the engagement ring.', 22, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 14, 'My Brother, My Keeper', 'Turk is still waiting for Carla to answer his proposal and asks his brother to stay over a few days to help him deal with it. Dr. Townshend, an old friend of Dr. Kelso and one of the nicest doctors around befriends J.D.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 15, 'His Story', 'Elliot meets a nice guy at the bar, but freaks out when she finds out he''s a male nurse at Sacred Heart. Turk keeps asking Carla to marry him, but she still won''t give an answer. Dr. Cox feels the pressure he puts on himself everyday: His psychiatrist, his subordination to Dr. Kelso and his paternal feelings for J.D.', 22, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 16, 'My Karma', 'J.D. and Turk think they''ve got bad karma after hitting a car and causing an accident, while playing golf on the hospital roof. Dr. Cox bends over backwards to give Jordan as much comfort as possible on her labor day, and she confesses to J.D. that Dr. Cox is the real father. Elliot seeks advice from Carla on how to tell Paul that she''s crazy, because they''re getting more intimate and she can''t hide it anymore. But Carla is feeling too crazy herself with the upcoming wedding.', 22, '2003-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 17, 'My Own Private Practice Guy', 'A personal secret of Dr. Cox is revealed during hospital visitations by a cocky MD (Jay Mohr), who establishes a rapport with J.D.', 22, '2003-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 18, 'My T.C.W.', 'J.D. flirts with the wife of a patient who''s been in a coma for the past two years, whom they all call T.C.W. (Tasty Coma Wife). He feels guilty for doing that, even though she wants to go ahead with it. Meanwhile, he can''t stand listening to any more relationship problems, as everybody dumps their issues on his ears: Elliot, sabotaging her relationship with Paul over beef jerky, Carla, finding out her engagement ring passed through a patient''s digestive system and Dr. Cox''s unsucessful attempts to get some attention from Jordan, who can only think about her baby right now.', 22, '2003-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 19, 'My Kingdom', 'Turk takes J.D. up to surgery, and right from the start J.D. steps all over Turk when trying not to be the geek among the surgeons. Paul hears Elliot say "I love U2" while she was rearranging her CDs and thinks she said "I love you too." Dr. Cox decides to get even with Dr. Kelso by telling everyone he''s dead, revealing what people really think of him.', 22, '2003-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 20, 'My Interpretation', 'Jamie''s (T.C.W.) husband died, and J.D. struggles with the ethical issues involved in starting a relationship with her. Dr. Cox babysits his son, whom Jordan still hasn''t chosen a name for, and is disturbed that he feels nothing for the baby. Turk is haunted by erotic dreams about Elliot, which gets him into hot water with Carla.', 22, '2003-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 21, 'My Drama Queen', 'J.D. carries on with his romance with Jamie, but finds himself at a dead end after realizing she''s a drama queen. Dr. Kelso makes Dr. Cox give a class on how to approach the patients nicely in order to prevent possible law suits. Carla''s mother dies and she wants to get married.', 22, '2003-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 2), 22, 'My Dream Job', 'J.D. and Turk''s college buddy, Spence, drops by for a visit, and accidentally tells Dr. Cox a secret. Too much partying with successful Spence causes Turk and J.D. to show up late and drunk for work, which Dr. Kelso fully reprehends them for. Elliot''s feeling low since she can''t measure up to Dr. Kelso''s standards, and the Janitor starts another feud – this time over paychecks – with J.D.', 22, '2003-04-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 1, 'My Own American Girl', 'A run-in with her old flame Sean and an accident in her new car lead Elliot to the realization that nothing good has happened to her in the three years that she has been at Sacred Heart. This realization drives her to take drastic measures, including a complete makeover, both inside and out, in an attempt to change her luck.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 2, 'My Journey', 'J.D. is feeling left out of his friendship with Turk and gets hurt when Turk is scared of opening up to him.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 3, 'My White Whale', 'Finding difficulties training his interns, J.D. asks to Elliot for some help. She tells J.D. about Sean, who gave Elliot great tips based on his dolphin training that fit perfectly for her interns.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 4, 'My Lucky Night', 'Sean is a bit surprised and disturbed to learn about Elliot and J.D.''s history together, but it turns out his anger is really a cover up for his upcoming six month long trip and he doesn''t want Elliot to explode.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 5, 'My Brother, Where Art Thou?', 'Dan decides to stay with J.D. for a while after their mom''s new fiancé kicks him out, but after spending some quality time with him at the hospital, Dan isn''t sure if he likes the cynical person his little brother has become.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 6, 'My Advice to You', 'A chance meeting in the elevator sparks a new friendship between J.D. and the mysterious Danni whose ongoing dialogue about her ex forces J.D. to talk about his feelings for Elliot.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 7, 'My Fifteen Seconds', 'As J.D.''s relationship with Danni progresses, he and Dr. Cox are forced to spend more time together outside of the hospital, to Perry''s great chagrin.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 8, 'My Friend the Doctor', 'Elliot struggles to find her defining moment after Turk performs his first solo surgery. Dr. Cox deals with the reality of growing older when his back goes out. J.D. finds out that many of the hospital staff don''t know the Janitor as he does.', 24, '2003-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 9, 'My Dirty Secret', 'Elliot feels uneasy with the proper terms for sexual organs, especially after performing a pelvic exam; J.D.''s patient refuses to have surgery for prostate cancer.', 24, '2003-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 10, 'My Rule of Thumb', 'Carla and Elliot try to help a patient, Maggie, lose her virginity as she prepares to die.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 11, 'My Clean Break', 'J.D. tries to break-up with Danni, but she beats him to it when she realizes that she will always be second place to Elliot in his heart.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 12, 'My Catalyst', 'J.D. believes he may have finally found a mentor in Dr. Kevin Casey, a surgeon with obsessive-compulsive disorder, and it turns out that Dr. Cox has always been jealous of the guy.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 13, 'My Porcelain God', 'Elliot finds herself perplexed over a simple procedure that leaves her questioning her career path. She goes to seek Dr. Kevin Casey''s advice but becomes frustrated when she learns that the epiphany toilet, which the Janitor secretly installed on the roof, is getting more attention than she is.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 14, 'My Screw Up', 'Jordan''s brother and sister return, but Dr. Cox learns that his brother-in-law Ben hasn''t visited a doctor about his cancer in the two years he has been gone traveling the world.', 24, '2004-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 15, 'My Tormented Mentor', 'Jordan''s friends Allison and Maddie come to town to provide moral support for Jordan after her brother''s death – however, their constant presence does not provide any relief to Dr. Cox.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 16, 'My Butterfly', 'An ever present butterfly prompts the question on what could have happened different as Turk looks for his lucky do-rag for surgery, and Elliot tries to find a lost stuffed animal for a child needing a bone marrow transplant.', 24, '2004-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 17, 'My Moment of Un-Truth', 'J.D. must keep a secret when Carla''s "what-if" guy asks her out on a date.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 18, 'His Story II', 'Turk has to confront a young patient of his, when he accidentally cuts a nerve and the boy (who happens to be a concert pianist) loses use of one of his hands.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 19, 'My Choosiest Choice of All', 'J.D. hooks up with Danni again, after Sean returns, but he can''t forget about his passionate night with Elliot.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 20, 'My Fault', 'Elliot asks Sean to move in with her, which only adds to J.D.''s problems.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 21, 'My Self-Examination', 'J.D. is unsure what to do, when he realizes he made a mistake telling Elliot he loved her.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 3), 22, 'My Best Friend''s Wedding', 'The big day for Turk and Carla has finally arrived, but a patient holds up Turk.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 1, 'My Old Friend''s New Friend', 'Turk and Carla start to have issues when Carla tries to change everything about her new husband. Molly Clock (Heather Graham), the hospital''s new psychiatrist, becomes friends with Elliot because she believes Turk, J.D. and Carla are shutting her out. Also, when Turk and J.D.''s car blows up, Carla lets him pick out the new ride only to find that instead of a car, he buys three scooters for them, further proving Carla''s point that she needs to always be in control. The episode guest stars the Sugarhill Gang.', 22, '2004-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 2, 'My Office', 'Dr. Clock tries to reconcile J.D. and Eliot, while waiting to see which one Dr. Cox will give the Chief Resident position to. Molly and Carla are experiencing some subtle conflict and Elliot and J.D. begin to come together after long bouts of conflict of their own.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 3, 'My New Game', 'Dr. Cox is having issues with Jordan, since Ted revealed that they are still technically married due to some filing problems.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 4, 'My First Kill', 'J.D. is shocked to hear Dr. Cox tell his interns that eventually, they will screw up and kill a patient. J.D. fears his first time killing someone will soon be upon him.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 5, 'Her Story', 'Elliot becomes unsure, if she wants Molly as her mentor, when she finds out that Molly doesn''t have a perfect home life.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 6, 'My Cake', 'When Dan resurfaces, J.D. is shocked to learn his father has passed away. The reactions from his co-workers help J.D. a little, but the one person, Dr. Cox, who he wanted to be there for him is too busy with J.D.''s patients.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 7, 'My Common Enemy', 'When J.D. finds Dan with Elliot, Turk tells him to use the hurt brother excuse to get them to break up, just like Turk uses his diabetes to get stuff from Carla. But then J.D. realizes he wasn''t hurt at all...
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 8, 'My Last Chance', 'When Molly takes a job at a different city, she and J.D. end up having a night of kissing, and he tries to rush to sleep with her before she leaves.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 9, 'My Malpractical Decision', 'J.D. is approached by a malpractice attorney, asking him to do a risky procedure on her father. Meanwhile, Elliot guides Doug to a new career path and Turk struggles to avoid a hypochondriac patient.', 22, '2004-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 10, 'My Female Trouble', 'With the case against Turk on his mind, J.D. attempts to end it with Neena, but she won''t take "no" for an answer and keeps him wrapped around her finger. Carla tries her own way of persuading Mr. Corman to drop the lawsuit.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 11, 'My Unicorn', 'J.D. takes matters into his own hands, when searching for a relative for his favorite patient.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 12, 'My Best Moment', 'When J.D. has to address a bunch of pre-med students about what it''s like to be a doctor, he strays off the beaten path and chooses to discuss his best moments as a doctor instead. When he challenges the rest of the staff to do so, they all remember their best memories in the medical field.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 13, 'My Ocardial Infarction', 'Elliot starts showing J.D. up as the calmer, more competent doctor. A date with the Janitor leads to an a capella sing-off between his "group" and Ted''s band.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 14, 'My Lucky Charm', 'A man injured in a bar fight teaches Turk and J.D. a lesson about living life to the fullest.', 22, '2005-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 15, 'My Hypocritical Oath', 'J.D. has a crush on a girl, who he met at a club, and he''s torn about telling her, that her boyfriend has gonorrhea.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 16, 'My Quarantine', 'J.D. tries to impress Kylie by paying a hobo in the hospital to fake a heart attack, when everything becomes boring due to a quarantine that he caused.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 17, 'My Life in Four Cameras', 'When J.D. meets a former writer from his all time favorite TV show "Cheers," he begins to picture his life at the hospital as a bland, multiple camera sitcom, where everything is perfect and wraps up nicely.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 18, 'My Roommates', 'J.D. is thrown out of the apartment.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 19, 'My Best Laid Plans', 'J.D. ditches a seemingly uninterested Kylie for Dr. Molly Clock, who just returned from Milwaukee.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 20, 'My Boss''s Free Haircut', 'Dr. Kelso dons scrubs to prove a point to Dr. Cox, only to watch it backfire, when an obnoxious patient refuses to listen to him.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 21, 'My Lips Are Sealed', 'When Carla and J.D. go out to let Carla have some fun, they get drunk and end up accidentally kissing.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 22, 'My Big Move', 'J.D. and Carla get the silent treatment from Turk, who can''t seem to control his emotions, after learning about their kiss.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 23, 'My Faith in Humanity', 'Turk won''t open up at couples therapy.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 24, 'My Drive-By', 'Elliot is torn between moving too quickly and ruining her new relationship with Jake. Dr. Cox teaches Turk about having a healthy ego and Dr. Kelso and the Janitor fight over who gets to use the motorized cart.', 22, '2005-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 4), 25, 'My Changing Ways', 'With their residencies over, there are big changes at Sacred Heart. J.D. moves out to live on his own, while Turk and Carla consider a family change, creating another rift in their long friendship.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 1, 'My Intern''s Eyes', 'Attending at Sacred Heart, J.D. now has to deal with his own interns. Turk has doubts having children, then tries to prevent Carla from getting pregnant. Meanwhile Elliot struggles to find her way at County Hospital and doesn''t want to seem like the helpless person she was before.', 22, '2006-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 2, 'My Rite of Passage', 'J.D. wants to show Dr. Cox and Dr. Kelso how to treat interns, but instead he finds out that they laugh at his bad jokes out of fear and respect.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 3, 'My Day at the Races', 'While planning his birthday, J.D. finds a list of things he wanted to accomplish, before he turned 30. He enters a triathlon to begin. Meanwhile, Elliot discovers a side of her boyfriend Jake, that freaks her out. And Turk is working hard to impress his bosses and takes on a patient, who wants to be hypnotized during surgery in effort to be promoted.', 22, '2006-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 4, 'My Jiggly Ball', 'J.D. is asked to introduce Dr. Kelso at an awards dinner, so he wants to find out something good about him. Dr. Kelso and Dr. Cox each have a patient, whom they feel deserves the benefit of a new experimental treatment, but there is only one open slot. Elsewhere, Carla and Turk try to help Elliot get her old job at Sacred Heart back. And the Janitor taunts J.D. with the made up game of "Jiggly Ball."', 22, '2006-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 5, 'My New God', 'Dr. Cox''s religious sister Paige comes to visit for her nephew''s baptism. Turk is finding out, just how unsexy baby making can be. Elliot helps him realize that Carla finds the whole process to be romantic. Elswhere, J.D. and the Janitor start a buddy friendship.', 22, '2006-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 6, 'My Missed Perception', 'J.D. mistakes an elderly woman''s happiness as her wish to stop treatment for a fatal illness.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 7, 'My Way Home', 'In a "Wizard of Oz" homage, J.D. is trying to go home, Turk searches for a heart donor and Carla worries, that she doesn''t have the courage to become a parent. Meanwhile, Elliot doesn''t believe, that she has the brains to lead a question and answer session. Also, the Janitor is painting color coded lines throughout the hospital for easier navigation.', 22, '2006-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 8, 'My Big Bird', 'J.D., Turk, Elliot and Carla are interrogated about the mysterious death of a patient.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 9, 'My Half-Acre', 'J.D. meets the klutzy Julie, and when he becomes smitten, Elliot attempts to help out with romance advice. Meanwhile, Carla tries to find Dr. Cox''s soft side, when he refuses to kiss his son.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 10, 'Her Story II', 'J.D. is annoyed, that Julie doesn''t laugh, so Elliot encourages him, to tell her his feelings, and Turk tries to use psychology to fix the issue.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 11, 'My Buddy''s Booty', 'J.D. is still dealing with his recent breakup and trying not to kill intern Keith, who has become annoyingly perfect. To make matters worse, a favorite patient is in a serious coma and each of the staff finds their own way to deal with it.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 12, 'My Cabbage', 'Dr. Kelso is outraged, when he discovers, that a bird has been living in Sacred Heart. He orders the Janitor to dispose of it immediately. However, the Janitor likes the bird so much, he secretly keeps it as a pet. Meanwhile, J.D., annoyed with Keith, tries to get his intern fired, but things don''t turn out as intended.', 22, '2006-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 13, 'My Five Stages', 'J.D. and Dr. Cox go through the five stages of grief with their favorite patient, who is declining in health. Carla forces Turk to go on a string of double dates, including Elliot and her booty call Keith. Elsewhere, Dr. Kelso hits Ted with his car, thus Ted finally has the upper hand with a potential lawsuit.', 22, '2006-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 14, 'My Own Personal Hell', 'J.D. is sick of perfect intern Keith and he''s not the only one. Elliot''s relationship with Keith is revealed, so the other interns think that he is getting special attention. In the meantime Dr. Cox boasts about being named "The Best Doctor in the City" by a local magazine, thus Dr. Kelso assigns him to the most difficult patient in the hospital to deflate his ego. Also, Turk and Carla continue to struggle in their quest for conception.', 22, '2006-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 15, 'My Extra Mile', 'J.D. urges Cox and his fellow doctors to do special, unconventional things for their patients, but J.D. himself is not sure he can shave his head for a woman undergoing chemotherapy, after meeting a woman who loves his hair. Meanwhile,Turk and Carla attempt to eliminate all the stress in their lives, to better their chances of conceiving. Also, Elliot can''t stop giving her new boyfriend Keith stupid gifts.', 22, '2006-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 16, 'My Bright Idea', 'Turk finds out, that Carla is pregnant, before she does, so J.D. convinces Turk to tell the entire hospital staff to surprise Carla with the news. But Carla wants to personally share her baby news with everybody, so Turk and J.D. have to quickly contain the hospital gossip. Meanwhile, when Elliot puts Dr. Cox into an embarrassing situation, he decides to get even with Elliot through Keith and Carla.', 22, '2006-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 17, 'My Chopped Liver', 'When J.D. rearranges his schedule to allow himself more time to spend with Turk, Turk secretly resents hanging out with J.D. in that time because it interferes with his own "Turk Time."
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 18, 'My New Suit', 'J.D.''s brother Dan returns for a surprise visit and Elliot learns that J.D. has been telling Dan that she still likes him. A patient with weight-related problems needs an MRI, but he''s too big for the machine. Carla and Turk freak out when they begin to discuss baby names. Meanwhile, Dr. Kelso assigns Dr. Cox to assist Ted with malpractice claim paperwork after Dr. Cox insults Dr. Kelso''s son.', 22, '2006-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 19, 'His Story III', 'Turk and Carla turn J.D.''s old bedroom into a nursery for the baby. The Janitor seizes an opportunity to shove J.D. out of the picture for a day. Elsewhere, Elliot uses her mother to learn information about Keith''s peers and Turk & Dr. Cox accuse each other of not being hip.', 22, '2006-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 20, 'My Lunch', 'J.D. asks Dr. Cox out for lunch, but runs into annoying former patient Jill Tracy, who unexpectedly teaches him something about responsibility.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 21, 'My Fallen Idol', 'Dr. Cox starts drinking after his decisions result in the death of three of his patients. The staff tries to cover for him at the hospital, while everyone tries to convince him how inspiring he is for them.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 22, 'My Déjà vu, My Déjà vu', 'J.D. feels that the same things happen over and over again at the hospital. Dr. Cox returns to work, but Elliot believes that he has lost his usual confidence. Elliot calls Dr. Cox on his behavior. Carla gets fed up with Turk, because he still can do a lot of stuff, but she can''t since she is now pregnant.', 22, '2006-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 23, 'My Urologist', 'J.D. challenges an urologist''s assessment on a consult for a patient in need of a risky surgical procedure. He also starts to fall for her. Meanwhile, Elliot considers breaking up with Keith, but Carla is showing extreme hormonal changes due to her pregnancy and tries to interfere. The Janitor and Dr. Kelso are having a little tiff of their own about fear.', 22, '2006-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 5), 24, 'My Transition', 'J.D. plans a date with Kim on their night off but Elliot keeps getting in their way. Meanwhile, Elliot throws a baby shower for Carla.Perry and Jordan hand over all of Jack''s stuff to Carla. And someone announces a very surprising pregnancy.', 22, '2006-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 1, 'My Mirror Image', 'J.D. addresses the news that he is going to be a father and Dr. Cox is worried about how his anger is going to impact his offspring. Meanwhile, Carla and Turk prepare for the impending arrival of their new baby. Elliot feels left out because she is childless, while the Janitor wonders if he has wasted his life.', 22, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 2, 'My Best Friend''s Baby''s Baby and My Baby''s Baby', 'J.D. and Kim start contemplating about their future and their baby''s future. Meanwhile, Turk rushes Carla to the hospital after she goes into labor. And Jordan accuses Dr. Cox of not being a more defensive father towards Jack.', 22, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 3, 'My Coffee', 'J.D. and Kim are surprised of how much they have in common. Recently giving birth, Carla doesn''t want to return to work. Meanwhile, Elliot tries to persuade Dr. Turner, a surgeon with thirty years of experience, that medicine is the better option to work with and that surgery could kill him.', 22, '2006-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 4, 'My House', 'Dr. Cox feels like the TV character House when he has to solve several mysteries, one of them being Elliot''s anger towards Dr. Kelso, while for some reason she is taking it out on Turk.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 5, 'My Friend with Money', 'Elliot begins enjoying luxuries since she has extra money with her new private practice gig. But eventually, J.D. becomes jealous of her and that forbids him the use of these privileges.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 6, 'My Musical', 'A new patient at the hospital wakes up and sees everything happening around her as a musical.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 7, 'His Story IV', 'The hospital is seen through the eyes of Dr. Kelso, who befriends an Iraq War veteran.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 8, 'My Road to Nowhere', 'After being convinced to go to Tacoma for Kim''s first ultrasound, J.D., along with Carla, Elliot, Janitor, Keith and Ted, takes Kelso''s new RV on a road trip. Meanwhile, Jordan and Dr. Cox have trouble when Jordan''s ultrasound reveals that the baby will need surgery.', 24, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 9, 'My Perspective', 'A Croatian Doctor comes to Sacred Heart, only to find out that he has to redo his Internship there.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 10, 'My Therapeutic Month', 'J.D. develops a crush on a new physical therapist but due to his latest misfortunes, he finds it difficult to ask her out. Elliot asks Keith to move in with her, but is not willing to budge on her home rules. Turk breaks his arm and is sent back to residency by Dr. Kelso. Thanks to Dr. Cox, he realizes that he doesn''t know as much about medicine as he thought.', 24, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 11, 'My Night to Remember', 'A memory loss patient is the peg for a look back on the last seasons of Scrubs, when the Sacred Heart crew looks back at their memorable moments.', 24, '2007-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 12, 'My Fishbowl', 'When Private Dancer is released from the hospital, the military informs him that his injuries are too severe to be reinstated into the service, so he gets depressed. The Sacred Heart staff try to cheer him up, while the Janitor is having a fish problem.', 24, '2007-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 13, 'My Scrubs', 'J.D. and Turk try to treat Dr. Kelso''s uninsured friend. Meanwhile, Dr. Kelso himself is concerned about a clothing thief. Elsewhere, Dr. Cox tries to convince Elliot that a reformed drug addict isn''t exactly clean, and the Janitor blackmails Carla.', 24, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 14, 'My No Good Reason', 'Laverne and Dr. Cox engage in a philosophical debate. Carla finds a hot nanny for Isabella, and Turk struggles to find a way not to leer at her.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 15, 'My Long Goodbye', 'Laverne is brain-dead, and her family decides to take her off life support. One by one, the staff say their goodbyes, except Carla, who stoutly refuses to accept what''s happening. She consequently finds herself "haunted" by Laverne. Meanwhile, Jordan gives birth, but Dr. Cox doesn''t want to tell anyone because he doesn''t want his daughter''s birthday to always be associated with Laverne''s death.', 24, '2007-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 16, 'My Words of Wisdom', 'In the wake of Laverne''s funeral, the Sacred Heart Staff decide to implement lessons from her life to their actions. Carla is upset that everyone seems to act as if nothing has changed. Dr. Cox tries to take twenty minutes for himself every day, but has great difficulty doing that. Meanwhile, the Janitor helps J.D. and Turk treat a deaf patient. And Elliot learns that Keith wants more from their relationship.', 24, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 17, 'Their Story', 'The perspective shifts between Jordan, Ted, and Todd, as they go about their day.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 18, 'My Turf War', 'When Keith leaves town for a few days, J.D. expects that he''ll finally be able to spend some quality time with Elliot. But he doesn''t anticipate Elliot''s old college friend dropping by. J.D. switches between hitting on her and competing with her for Elliot''s attention. Meanwhile, Turk and Dr. Cox volley a hypochondriac patient back and forth since there''s nothing wrong with him.', 24, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 19, 'My Cold Shower', 'J.D. tries to get together with Elliot''s sorority sister Melody, but she just wants to make out with him without going further. Meanwhile, Keith re-proposes to Elliot after she gets to make everything perfect, while everyone has fantasies about being married to Elliot. Elliot and Carla are having problems figuring out what is wrong with two elderly patients, who show the same symptoms but have no obvious connection.', 24, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 20, 'My Conventional Wisdom', 'J.D. and Turk go to a medical convention in Phoenix, Arizona, where they run into J.D.''s ex-girlfriend Dr. Kim Briggs, who has a surprise for J.D. Meanwhile at Sacred Heart, the janitor pretends to be the chief of medicine and Dr. Cox starts to put doubts about the wedding into Elliot''s mind.', 24, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 21, 'My Rabbit', 'Kim moves in with J.D. in order to raise their child together. J.D. learns from Turk and Dr. Cox that fatherhood changes the way of how to see things.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 6), 22, 'My Point of No Return', 'In the season finale, J.D. and Elliot start thinking about their future and if they both made a mistake in not being with each other. The Janitor activates the "Brain Trust" to come up with the perfect wedding gift for Elliot.', 24, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 1, 'My Own Worst Enemy', 'In the aftermath of their near-indiscretion, Elliot realizes she doesn''t want to be with Keith, and J.D. resolves to stop sabotaging himself.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 2, 'My Hard Labor', 'Kim goes into labor, and J.D. struggles to decide if he should tell her what he really thinks of their relationship. Turk, desperate to do something not baby-related, races to beat a video game before Carla discovers him. And Dr. Cox searches for someone he trusts enough to give his daughter a shot.', 24, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 3, 'My Inconvenient Truth', 'J.D''s brother Dan returns and delivers a few home truths to his little brother. In the meantime, Elliot and Dr. Cox debate over the morals of their practice and the staff of Sacred Heart find the Janitor''s behavior rather odd after he watches "An Inconvenient Truth".', 24, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 4, 'My Identity Crisis', 'Turk tries to assure a worried Carla that their daughter will acknowledge her Latin heritage. Meanwhile the Janitor challenges J.D. to identify everyone in the hospital, when it is discovered that he uses nicknames, because he doesn''t know the people''s actual names. If J.D. can''t name all of them, he must take up the mop for a day. Elsewhere, Dr. Cox realizes that he is lonely without his wife and children.', 24, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 5, 'My Growing Pains', 'The Sacred Heart staff has to deal with their inner child, when J.D. and Turk remember their first prank, Dr. Cox has a ten year old Leukemia patient and Dr. Kelso celebrates his birthday.', 24, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 6, 'My Number One Doctor', 'Though Elliot boasts that through private practice she gets to get to know her patients, nobody seems to care. Carla is amazed at how the Janitor was able to score such an attractive girlfriend. The doctors are improving their services to get a higher ranking on a website and although J.D. appears nonchalant initially, he is elated when he is ranked #1.', 24, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 7, 'My Bad Too', 'J.D.''s teenage burn patient gives him a hard decision to make when he wants to go to his high school graduation. Turk doesn''t want Carla to find out that he secretly learned Spanish. And to address Dr. Kelso''s weight gain, Dr. Cox makes a game out of stealing his breakfast.', 24, '2008-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 8, 'My Manhood', 'When Dr. Kelso tells the Janitor that nobody cares what he thinks, he starts a newspaper called "The Janitorial" to prove him wrong. J.D. and Turk fight over their manhood issues, while Dr. Kelso is too proud to ask for help about one of his problems.', 24, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 9, 'My Dumb Luck', 'Dr. Cox had a patient that he hadn''t been able to diagnose for two years, and he is back again.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 10, 'My Waste of Time', 'Elliot and J.D. discover a major change in their relationship, when they spend time together looking for a former patient.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 7), 11, 'My Princess', 'After a hard day of work, Dr. Cox has the burden to tell his son Jack a good night story, so he disguises his hard day as a fairy tale about the little village Sacred Heartlia with Carla and Turk as the two-headed witch Turla, Elliot as the princess and J.D. as the village idiot.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 1, 'My Jerks', 'Dr. Kelso''s beautiful but unethical replacement, Dr. Maddox, shakes things up at Sacred Heart, while J.D. struggles to manage a new crop of incompetent interns and Carla helps Elliott put her ego in check.', 24, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 2, 'My Last Words', 'J.D. and Turk make a huge sacrifice concerning a decade-long steak night tradition for a dying patient. Meanwhile, Dr. Maddox, the new Chief of Medicine, begins to show her true colors.', 24, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 3, 'My Saving Grace', 'Dr. Kelso and Dr. Cox have to work together again to get rid of Dr. Maddox, while Carla faces an incompetent intern.', 24, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 4, 'My Happy Place', 'J.D. and Elliot''s relationship seems to have been rekindled when they encourage Dr. Kelso to find his true happy place.', 24, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 5, 'My ABC''s', 'Featuring a special appearance from Sesame Workshop''s "Muppets", J.D. learns a lesson about the gift of compassion, while Elliot gets scammed by intern Katie to secure a spot on Turk''s team.', 24, '2009-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 6, 'My Cookie Pants', 'Elliot and J.D. encounter a road block in their newfound romantic relationship, and Dr. Cox considers taking the now vacant Chief of Medicine post.', 24, '2009-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 7, 'My New Role', 'As his increasing workload from being Chief of Medicine begins to take a toll, the unimaginable happens when Dr. Cox reaches out to Dr. Kelso for friendship.', 24, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 8, 'My Lawyer''s in Love', 'It''s Ted''s lucky day when he falls head over heels in love with an ukulele player, and Dr. Cox realizes he cannot handle everything that is thrown at him.', 24, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 9, 'My Absence', 'J.D. manages to still bother Dr. Cox despite being away on a vacation from the hospital. Meanwhile, Turk and Carla have some big news to announce.', 24, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 10, 'My Comedy Show', 'J.D. and Turk gather up a new crop of interns as they organize their annual (and historically unfunny) sketch show.', 24, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 11, 'My Nah Nah Nah', 'While Turk views an inspiring story on SportsCenter, he comes up with a new procedure which may help a paralyzed teen. Meanwhile, Dr. Cox and the janitor are suffering from romantic problems', 24, '2009-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 12, 'Their Story II', 'J.D.''s ego becomes inflated after Dr. Cox finally gives him the recognition he''s been waiting for. Elsewhere, the senior staff receives insight from the interns.', 24, '2009-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 13, 'My Full Moon', 'A combination of a full moon and some bad luck causes Sacred Heart''s new crop of interns to receive their toughest case load yet while Elliot makes an important decision regarding her future as a doctor.', 24, '2009-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 14, 'My Soul on Fire (1)', 'The Janitor and Lady invite the Sacred Heart staff to their fake wedding in the Bahamas hoping to score some loot but their scheme is about to backfire...', 24, '2009-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 15, 'My Soul on Fire (2)', 'The tropical seaside wedding goes ahead as the Janitor and Lady tie the knot which affirms the relationship of another couple.', 24, '2009-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 16, 'My Cuz', 'Things get weird for J.D. when he discovers the identity of Kim''s new man as he plans to reach out to her in order to move closer to Sam. Meanwhile, Turk starts a campaign for a promotion.', 24, '2009-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 17, 'My Chief Concern', 'Change doesn''t come easy for the gang when J.D. considers moving closer to his son. Meanwhile, Turk gets comfortable as chief of surgery, while Ted and Gooch reach a new level in their relationship.', 24, '2009-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 8), 18, 'My Finale', 'J.D. is planning on leaving Sacred Heart but before he goes there are a few things that he wants to do including; getting a hug from Dr. Cox, and learning the Janitor''s real name. Elliot is ready for the next step in her and J.D.''s relationship and she begins moving her furniture into J.D.''s apartment.', 48, '2009-05-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')), 9, 'Med School', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 1, 'Our First Day of School', 'J.D., Turk, Cox, Kelso and intern Denise return to Sacred Heart to teach med school, while new med students Lucy, Drew, Cole and Maya are put through the ringer on their first day of school.', 24, '2009-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 2, 'Our Drunk Friend', 'Lucy learns a hard earned lesson about what it takes to be a doctor. Meanwhile J.D. and Turk spot a potential love connection between Denise and the new med student, Drew, as they play matchmakers with a little bit of help from Dr. Kelso.', 24, '2009-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 3, 'Our Role Models', 'J.D. and Drew learn a tough lesson in mentoring when Dr. Cox and Lucy show them that sometimes the student is the teacher.', 24, '2009-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 4, 'Our Histories', 'While their wives are out of town, J.D. and Turk attend a med student''s party; Kelso says goodbye to Ted and Gooch.', 24, '2009-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 5, 'Our Mysteries', 'J.D. still clamors for Dr. Turk''s approval as he approaches his final day of teaching at Sacred Heart, Lucy searches within herself for the courage to perform a basic medical procedure on a real human, and Denise and Drew make things official.', 24, '2009-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 6, 'Our New Girl-Bro', 'While Turk struggles to find a replacement best friend, Elliott offers some sound advice and guidance to an over-worked and exhausted Lucy.', 24, '2010-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 7, 'Our White Coats', 'Before receiving their white coats, the med students of Winston University must figure out why they want to be doctors, and Denise gets a little relationship help from Elliot.', 24, '2010-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 8, 'Our Couples', 'Lucy finds couplings, dysfunctional or not, throughout the hospital', 24, '2010-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 9, 'Our Stuff Gets Real', 'The reality of having a baby begins to settle in for both J.D. and Elliot while Lucy struggles with the reality of operating on people.', 24, '2010-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 10, 'Our True Lies', 'A case of guilty conscience plagues the med school when a student cheats on an exam and Dr. Cox takes it out on the entire class. Meanwhile, Denise makes a startling admission of her own.', 24, '2010-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 11, 'Our Dear Leaders', 'Lucy takes her new assignment as hell week "team leader" a bit too seriously, and Dr. Turk feels threatened when an internationally renowned surgeon pays a visit.', 24, '2010-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 12, 'Our Driving Issues', 'When Cole and Kelso both get negative results back after a few routine tests, they learn the hard way to put their egos in check in order to rein in the support of their so-called friends.', 24, '2010-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0285403')) AND numero_temporada = 9), 13, 'Our Thanks', 'The med students of Winston University finally find something to be thankful for when Cole identifies his true calling in surgery, Drew finds the love of his life, and Lucy finds the inspiration to become a doctor.', 24, '2010-03-17');
