INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0296310', 'The Blue Planet', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0288144'), 'SERIE', 'Five years in the making, taking a look at the rich tapestry of life in the world''s oceans.', '2001-01-01', 'https://m.media-amazon.com/images/M/MV5BYjgyODJmY2YtZTk4Yy00MjBlLWFlM2YtNDIyMDk5YmQxMTllXkEyXkFqcGc@._V1_.jpg');
