INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')), 1, 'The Blue Planet', 'The Blue Planet is a British nature documentary series created and produced by the BBC. It premiered on 12 September 2001 in the United Kingdom. It is narrated by David Attenborough.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 1, 'Introduction', 'Experience the power of the blue whale - the largest mammal ever to grace our planet. Learn how the sun and moon help control and tame the ocean. Travel far and wide - from the Eastern Pacific to Alaska, from the Bering Sea to the shores of Southern California - and begin to understand the complexity and power of our oceans.', 50, '2001-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 2, 'The Deep', 'A place of mountain ranges, perpetual night, pressures extremes and cold... and the weirdest life forms on our planet. Dive into the depths of the ocean, an eerie world where predators with teeth so large they can''t even close their mouths, chase bio-luminescent creatures of the deep. Discover the spectacular smoking chimneys of the hydrothermal vents. Go deeper down than you have ever been...', 50, '2001-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 3, 'Open Ocean', 'In the immense space of the open ocean the sea bed is a staggering five miles below the surface and the nearest island is over 300 miles away. Yet here live many of the most spectacular predators in the ocean. Marvel as you experience ruthless and beautiful battles between hunter and prey.', 50, '2001-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 4, 'Frozen Seas', 'An environment where only the toughest survive, the Arctic and Antarctic are unrelenting habitats. Only in spring does life begin again. Plankton blooms and feeds fast hordes of migrating fish, walruses rake the seabed for clams, and minke and humpback whales gorge themselves on gigantic swarms of krill. But it is a brief spring feast - the ice soon returns and pushes life back into the ocean.', 50, '2001-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 5, 'Seasonal Seas', 'As the days grow longer, billions of microscopic plankton bloom under the blazing sun. Here in the temperate seas, three-ton basking sharks graze among forests of giant kelp - the fastest growing plant in the world. The forests harbor thousands of other animals, including sea otters, brilliantly colored anemones, squid, and exquisite leafy dragons. But as the year wears on, storms rage in the icy sea... a desperate challenge for the animals that remain.', 50, '2001-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 6, 'Coral Seas', 'Bathed in bright sunlight and warm clear water, the coral reef is a rich oasis of life - the rainforest of the sea. Bizarrely adorned harlequin shrimp carry off a starfish several times their size, while haunting songs reverberate around the reef, heralding the arrival of humpback whales. Shimmering schools of brightly colored fish battle for territory in this competitive world where you have to stand out to survive.', 50, '2001-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 7, 'Tidal Seas', 'The sun and moon move billions of tons of water with every turn of the tide. The strongest tides empty entire bays, smash trees on riverbanks, and strand sea creatures on suddenly dry land. Weaker tides control the movements of huge numbers of fish, coaxing stingrays though astounding underwater arches. And as the water recedes, the tide can create unbelievable landscapes - like a sparkling world of salt crystals inhabited only by tiny shrimp and bright pink flamingos.', 50, '2001-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0296310')) AND numero_temporada = 1), 8, 'Coasts', 'From rocky cliffs to gentle dunes, the coasts are always changing. Day in and day out, they are battered by crashing waves. Seabirds come here by the thousands to nest, while baby turtles hatch and race to the sea, pursued by hungry predators. Young sea lion pups are born and play on the sand - until a killer whale attacks, crashing in on the surf. But when breeding season is over, life returns to the sea and the shores are empty once again.', 50, '2001-10-31');
