INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 1), 1, 'Take Your Little Gun and Get Out of My Trailer Park', 'After 18 months in jail, our Trailer Park Boys, Ricky and Julian, head back home to Sunnyvale Trailer Park aiming to get their lives back together again. The problem is that neither Ricky''s fiancee Lucy nor his dad Ray will let him back into their homes, and some guy named Cyrus has moved into Julian''s trailer, having crowned himself the new "King of the Park."', 23, '2001-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 1), 2, 'Fuck Community College, Let''s Get Drunk and Eat Chicken Fingers', 'Fed up with all their demands and complaints, Julian tells everyone that he is leaving the trailer park. Ricky, who has been living in Julian''s car on his front lawn, has one week to find a new place to live. Mr. Lahey, the trailer park supervisor, is thrilled to hear of Julian''s imminent departure but when he hears that Ricky won''t be leaving too, his worst nightmare seems about to come true.', 23, '2001-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 1), 3, 'Mr. Lahey''s Got My Porno Tape!', 'In desperate need of $2,000 to buy some hydroponics gear for his dope-growing business, Ricky reluctantly agrees to star in one of J-Rock''s amateur porn films to be shot in J-Rock''s trailer. Ricky, however, isn''t quite up to the task, and the video, entitled "From Russia With The Love Bone", eventually winds up in Mr. Lahey''s possession. Julian must convince Lahey that using the tape against Ricky would not be in Lahey''s best interest.', 23, '2001-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 1), 4, 'Mrs. Peterson''s Dog Gets Fucked Up', 'While babysitting both Trinity and Mrs. Peterson''s dog, Ricky accidentally gets shot and the dog devours a tray of hash brownies. A vet treats both the dog and Ricky. In order to pay the vet, Ricky and Julian must repossess a lawn tractor owned by a former patient who hasn''t paid the vet''s bill. The Boys successfully recover the tractor -- but not before Ricky gets shot for the second time that day.', 22, '2001-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 1), 5, 'I''m Not Gay, I Love Lucy... Wait a Second, Maybe I am Gay', 'With Ricky''s life still a mess, Julian tries to convince him that it''s time to marry Lucy. Reluctant at first, Ricky changes his mind when Julian suggests that people will always think that Ricky is gay unless he marries Lucy. Julian''s engagement present to Ricky is the ''76 New Yorker, which for weeks was up on blocks in his front yard, and is now made operational thanks to a few purloined replacement parts.', 23, '2001-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 1), 6, 'Who the Hell Invited These Idiots to My Wedding?', 'Lucy insists that Julian take over the job of organizing her wedding: which is odd since Julian isn''t the groom, Ricky is. She wants lots of people and lots of food. The people part will be easy but getting that much food will be difficult on a tight budget. Julian''s plan to hit a local grocery store runs into a snag when Ricky unexpectedly shows up in the middle of the heist. Shots are fired. The next day, the cops show up uninvited to the wedding.', 23, '2001-05-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 1, 'What in the Fuck Happened to Our Trailer Park?', 'When Ricky gets a job as a mall security guard, he puts Julian''s dope-growing operation at risk and tries to arrest Bubbles for stealing shopping carts.', 23, '2002-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 2, 'Jim Lahey Is a Drunk Bastard', 'Julian and Ricky have to make sure that Jim Lahey wins the election for trailer park supervisor over their archrival Sam Losco.', 23, '2002-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 3, 'I''ve Met Cats and Dogs Smarter Than Trevor and Cory', 'Needing extra cash to expand their dope operation, Julian and Ricky open a bar and casino in J-ROC''s trailer.', 22, '2002-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 4, 'A Dope Trailer Is No Place for a Kitty', 'When their dope plants become infested with insects, Ricky and Julian quarantine the surviving crop in Bubbles'' shed, leading to a fiery conclusion.', 23, '2002-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 5, 'The Bible Pimp', 'Ricky''s worst suspicions are realized when Julian falls for the daughter of a traveling Bible Salesman.', 23, '2002-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 6, 'Never Trust a Man with No Shirt On', 'After a big blowout with his boss, Randy quits his job and joins Julian and Ricky in their life of crime.', 23, '2002-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 2), 7, 'The Bare Pimp Project', 'With their dope-filled Airstream trailer in tow, Julian, Ricky and Bubbles lead a convoy of police cars in a long chase through the countryside as a police helicopter circles overhead.', 23, '2002-08-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')), 3, 'Season 3', NULL);
