INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 2, 'Temporary Relief Assistant Trailer Park Supervisor', 'Ricky''s job as Temporary Relief Assistant Trailer Park Supervisor threatens to blow the cover on Julian''s bootleg vodka operation.', 23, '2003-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 3, 'If I Can''t Smoke and Swear, I''m Fucked', 'Ricky defends himself, Julian and Bubbles in court on charges of operating an illegal gas station', 23, '2003-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 4, 'Who''s the Microphone Assassin?', 'Caught jacking more than just tunes, J-ROC tries to redeem himself by MC''ing a rap concert in the park.', 23, '2003-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 5, 'Closer to the Heart', 'Bubbles is so devastated about not getting tickets to the RUSH concert that Ricky decides to bring Alex Lifeson (Alex Lifeson) to the park to perform a private concert.', 23, '2003-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 6, 'Where the Fuck is Randy''s Barbeque?', 'Julian comes up with a plan to ""remarket"" barbeques.  Ricky thinks it''s a good idea to get his daughter, Trinity, and her friends in the Junior Achievers'' Program to steal the barbeques since they are minors and won''t go to jail.', 23, '2003-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 7, 'The Delusions of Officer Jim Lahey', 'Lahey looses his mind on the anniversary of his dismissal from the police force.  He puts on his old police uniform and tells everyone in the park that he is a police officer again.  He shoots at Ricky and ultimately imprisons Ricky and Julian in a homemade shed-jail.', 23, '2003-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 3), 8, 'A Shit Leopard Can''t Change Its Spots', 'Ricky gets pissed off at Julian for inviting Officer Erica Miller on the cruise.', 23, '2003-06-08');
