INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 1, 'Never Cry Shitwolf', 'Julian gets out of jail only to discover that Ricky is the new supervisor of Sunnyvale Trailer Park. Ricky and his assistant, Bubbles, have been carrying out various illegal activities.', 23, '2004-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 2, 'Man''s Gotta Eat', 'Broke, trailerless and without rum, Julian decides to leave the park and ends up living in his car in an alley. Meanwhile, Randy will do anything for a store-bought cheeseburger.', 23, '2004-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 3, 'Rub ''N Tiz''zug', 'Julian, Ricky and Bubbles open a massage parlour in the park. J-Roc and DVS (Detroit Velvet Smooth) attempt to get J-Roc arrested to increase his ""street cred.""', 23, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 4, 'The Green Bastard', 'On a family fun day in the Park, Mr. Lahey plans to get his old supervisor job from Ricky. Bubbles wrestles under the alias, ""The Green Bastard"".', 23, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 5, 'Conky', 'Bubbles has an infected tooth and the only way to get him to a hospital is with the help of his old childhood friend: a ventriloquist doll named Conky.', 23, '2004-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 6, 'If You Love Something, Set It Free', 'Bubbles befriends a dope-addicted mountain lion that has been eating weed from the Boys'' marijuana fields..', 23, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 7, 'Propane, Propane', 'The Boys are finally ready to harvest and sell their dope. Barb proposes to Ricky. Mr. Lahey goes off the deep end.', 23, '2004-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 4), 8, 'Workin'' Man', 'The Trailer Park Boys race to harvest their dope field while Jim Lahey slowly goes crazy.', 23, '2004-05-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 5), 1, 'Give Peace a Chance', 'The boys get out of jail only to find that Cory and Trevor messed up again and they don''t own the park after all. Ray is hooked on VLTs.', 23, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0290988')) AND numero_temporada = 5), 2, 'The Shit Puppets', 'Cory and Trevor start to work for Julian. The boys steal drugs from Cyrus and hatch a plan to hide it all until they can find a buyer.', 23, '2005-04-24');
