INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')), 1, 'Season 1', 'On the drug-infested streets of West Baltimore, there are good guys and there are bad guys. Sometimes you need more than a badge to tell them apart. Season 1 follows a single sprawling drug and murder investigation in Baltimore — one that culminates in a complex series of dangerous wiretaps and surveillance.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 1), 1, 'The Target', '"... when it''s not your turn." - McNulty.
