INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 2), 11, 'Bad Dreams', '''I need to get clean'' -- Sobotka
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 2), 12, 'Port in a Storm', '''Business. Always business.'' -- The Greek
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')), 3, 'Season 3', 'The heat is on in Baltimore. The drug war is being lost, bodies are piling up, and a desperate mayor wants the tide turned before the election. But the police department hasn''t got any answers. Wiretaps haven’t worked. Neither have stakeouts or street busts. With the demolition of the Franklin Terrace towers, Stringer Bell and the Barksdale crew have been forced to improvise. But no matter how hard McNulty and the detail try, the dealers always seem to be one step ahead of the game. It’s time to change the rules.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 1, 'Time After Time', '"Don''t matter how many times you get burnt, you just keep doin'' the same." -- Bodie
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 2, 'All Due Respect', '"There''s never been a paper bag." -- Colvin
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 3, 'Dead Soldiers', '"The gods will not save you." -- Burrell
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 4, 'Amsterdam', '"Why you got to go and fuck with the program?" -- Fruit
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 5, 'Straight and True', '"I had such fuckin'' hopes for us." -- McNulty
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 6, 'Homecoming', '"Just a gangster, I suppose." -- Avon Barksdale
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 7, 'Back Burners', '"Conscience do cost." -- Butchie
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 8, 'Moral Midgetry', '"Crawl, walk, and then run." -- Clay Davis
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 9, 'Slapstick', '"...while you''re waiting for moments that never come." -- Freamon
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 10, 'Reformation', '"Call it a crisis of leadership." -- Proposition Joe
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 11, 'Middle Ground', '"We ain''t gotta dream no more." -- Stringer Bell
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')) AND numero_temporada = 3), 12, 'Mission Accomplished', '"...we fight on the lie." -- Slim Charles
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')), 4, 'Season 4', 'In the projects. On the docks. In City Hall. And now, in the schools. The places and faces change, but the game remains the same. A new story begins. This year, while expanding on storylines introduced in previous seasons — including the new vocations of several characters, the rise of a new drug empire, and the city''s imminent mayoral election — the series expands its focus into Baltimore''s school system, providing an inside look at the role of the urban educational system in shaping young people''s lives. This storyline is played out through four new young characters, each of whom faces difficult choices amidst the temptation of crime and easy money.');
