INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0306414')), 5, 'Season 5', 'In the projects. On the docks. In City Hall. In the schools. And now, in the media. The places and faces change, but the game remains the same. In the fifth — and final — season, the series expands its focus into the media — specifically the role of newspapers in big-city bureaucracy — as it follows a newspaper staff as they struggle to maintain integrity and meet deadlines in the face of budget cuts and staff reductions.');
