INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0312172', 'Monk', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0957198'), 'SERIE', 'Adrian Monk is a brilliant former San Francisco detective, who now consults the police as a private consultant while battling with an obsessive-compulsive disorder.', '2002-01-01', 'https://m.media-amazon.com/images/M/MV5BNWM0YjQ4ZjYtNWYyYi00ZDVmLTg5NDQtOTkzZjljYzg2ZWI1XkEyXkFqcGc@._V1_.jpg');
