INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')), 1, 'Season 1', 'He’s ingenious, he’s phobic, and he’s obsessive-compulsive. Adrian Monk’s offbeat antics have made him unfit for duty but he’s back as a San Francisco police consultant to help out on their most baffling cases. The brilliant but neurotic Monk is now fighting crime as well as his abnormal fears of germs, heights, crowds and virtually everything else known to man.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 1, 'Mr. Monk Meets the Candidate', 'Monk investigates an assassination attempt on Mayoral Candidate Warren St. Claire and learns there''s more at play than meets the eye.', 79, '2002-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 2, 'Mr. Monk and the Psychic', 'Everyone believes psychic Dolly Flint has accomplished the impossible when she discovers the body of the former Police Commissioner''s missing wife. Everyone except Monk.', 44, '2002-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 3, 'Mr. Monk Meets Dale the Whale', 'An 800-pound recluse, aka Dale the Whale, is the number one suspect in a murder case. But how can a man who can''t even fit through his bedroom door be a murderer?', 45, '2002-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 4, 'Mr. Monk Goes to the Carnival', 'Monk, who suffers from vertigo, investigates the death of a police detective murdered on a ferris wheel.', 44, '2002-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 5, 'Mr. Monk Goes to the Asylum', 'After being temporarily institutionalized, Monk stumbles upon a four-year-old murder. Or is his mind playing tricks on him?', 44, '2002-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 6, 'Mr. Monk and the Billionaire Mugger', 'A billionaire is shot dead while mugging a couple outside a theater. It appears to be a mid-life crisis gone horribly wrong, until Monk figures out the truth.', 43, '2002-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 7, 'Mr. Monk and the Other Woman', 'Monk investigates an attorney''s death and develops a love interest in one of the suspects.', 45, '2002-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 1), 8, 'Mr. Monk and the Marathon Man', 'Monk, himself a former marathon runner, figures out the clever scheme devised by a furniture magnate to dispose of his mistress during a citywide marathon.', 44, '2002-09-13');
