INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 9, 'Mr. Monk and the Miracle', 'When three homeless men seek out Monk''s services at the holidays, Natalie convinces him to investigate the death of their friend.', 43, '2008-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 10, 'Mr. Monk''s Other Brother', 'When Monk''s delinquent half-brother, Jack Jr., escapes from prison and breaks into Monk''s apartment, he manipulates Monk into helping him find the person he claims framed him for murder.', 43, '2009-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 11, 'Mr. Monk on Wheels', 'When Natalie unwittingly helps a thief steal the bicycle of a biotech CEO, she ropes Monk into solving a crime straight out of "Encyclopedia Brown" -- until Monk learns the hard way how dangerous this thief really is.', 42, '2009-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 12, 'Mr. Monk and the Lady Next Door', 'While investigating a murder at a museum of oddities, Monk befriends a warm older woman, but he has trouble believing the friendship comes without a catch.', 43, '2009-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 13, 'Mr. Monk Makes the Playoffs', 'Monk has scored tickets to the biggest football game of the year, but he and Captain Stottlemeyer can''t go inside until they figure out who tried to blow up a fan in the parking lot.', 42, '2009-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 14, 'Mr. Monk and the Bully', 'When a childhood bully who terrorized Monk hires the detective to trail his wife, whom he suspects of infidelity, Monk relishes the opportunity to prove him right — and things get even sweeter when the bully is accused of murder.', 43, '2009-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 15, 'Mr. Monk and the Magician', 'Monk goes head-to-head with a magician he suspects of murder.', 43, '2009-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 7), 16, 'Mr. Monk Fights City Hall', 'Monk becomes involved in the disappearance of a city official that could have ramifications concerning Trudy''s murder.', 43, '2009-02-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')), 8, 'Season 8', 'A surprising link to his late wife''s past helps Adrian to solve her murder and move on to a better future as his friends'' lives begin to change.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 1, 'Mr. Monk''s Favorite Show', 'After the attempted murder of a former child star from Monk''s favorite show, Monk accepts the job as her bodyguard.', 43, '2009-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 2, 'Mr. Monk and the Foreign Man', 'While investigating the puzzling, high profile murder of a maid whose assailant apparently tried to treat her wounds, Monk finds himself increasingly drawn to another case involving a visiting African man investigating his beloved wife''s hit-and-run death.', 43, '2009-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 3, 'Mr. Monk and the UFO', 'Monk must uncover the link between a missing girl and a UFO sighting after Natalie''s car breaks down in a small desert town.', 42, '2009-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 4, 'Mr. Monk Is Someone Else', 'Monk assumes the identity of a dead hit man in an effort to foil an assassination plot.', 43, '2009-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 5, 'Mr. Monk Takes the Stand', 'Monk''s phobias threaten to undermine a big murder case when an aggressive defense attorney targets the detective''s unconventional methods in court.', 43, '2009-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 6, 'Mr. Monk and the Critic', 'Natalie becomes convinced a critic who panned her daughter Julie''s theatrical performance was responsible for a murder at the same time as the show.', 43, '2009-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 7, 'Mr. Monk and the Voodoo Curse', 'Voodoo appears to be the only explanation when unmarked dolls sent to San Francisco residents accurately predict a series of inexplicable deaths -- including, perhaps, Natalie''s.', 42, '2009-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 8, 'Mr. Monk Goes to Group Therapy', 'When Monk''s insurance company refuses to pay for more individual therapy sessions, Monk joins Dr. Bell''s therapy group, where somebody appears to be murdering his fellow patients.', 42, '2009-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 9, 'Happy Birthday, Mr. Monk', 'Natalie tries to throw a surprise birthday party for Monk while he investigates the mysterious death of an office building''s maintenance man.', 43, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 10, 'Mr. Monk and Sharona', 'When Sharona returns to San Francisco to handle legal issues related to an uncle''s death, Monk suspects foul play and finds himself torn between the differing styles of Sharona and Natalie.', 42, '2009-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 11, 'Mr. Monk and the Dog', 'Monk reluctantly adopts a dog while looking into the suspicious disappearance of its owner.', 42, '2009-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 12, 'Mr. Monk Goes Camping', 'To woo the lone holdout on the reinstatement committee, Monk accompanies Lt. Disher on a scouting trip with the man''s troublesome son -- where nature isn''t the only thing the troop has to fear.', 42, '2009-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 13, 'Mr. Monk Is the Best Man', 'In order to save the wedding of someone close to him, Monk must first find out who is trying to sabotage it and why.', 43, '2009-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 14, 'Mr. Monk and the Badge', 'Monk finds his return to the police force to be more challenging than he expected when he becomes involved in the case of a serial killer.', 43, '2009-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 15, 'Mr. Monk and the End (1)', 'Monk is called to a crime at the location where he first heard the news of his wife''s murder and begins the most important investigation of his life.', 43, '2009-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0312172')) AND numero_temporada = 8), 16, 'Mr. Monk and the End (2)', 'Monk pursues the killer of his wife.', 43, '2009-12-04');
