INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')), 1, 'Season 1', 'The Black Swordsman has flash backs to years past and his trials and tribulations in the Band of the Hawk.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 1, 'The Black Swordsman', 'A blacksmith is forging an enormous sword while a dark man with only one eye and one arm stands back and watches.', 24, '1997-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 2, 'Band of the Hawk', 'There is a great battle taking place at a fort. The attackers are doing well, except one thing stands in their way -  a grey knight and he states that none shall pass him.', 24, '1997-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 3, 'First Battle', 'Guts and Griffith begin their sword fight.', 24, '1997-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 4, 'The Hand of God', 'Guts reminisces about his childhood.', 24, '1997-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 5, 'A Wind of Swords', 'Guts is now a commander of Griffith''s army, taking many risks in battle, Casca takes him to task for it. Griffith is knighted in the Midland court much to the nobles'' dismay.', 24, '1997-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 6, 'Zodd the Immortal', 'In another raid, Guts and Griffith come across a demon known as Nosferatu Zodd.', 24, '1997-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 7, 'The Sword`s Owner', 'Princess Charlotte of Midland strikes up a friendship with Griffith.', 24, '1997-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 8, 'Conspiracy', 'Griffith and Guts continue their success in battle and Griffith is made a Count.', 22, '1997-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 9, 'Assassination', 'Griffith saves Charlotte when her horse bolts during a fox hunt. Yurius, the king''s younger brother, attempts to have him assassinated.', 24, '1997-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 10, 'Nobleman', 'Guts, sent by Griffith, assassinates Yurius and his son Adonis. Griffith gets closer to Charlotte. The Hawks depart for yet another mission.', 24, '1997-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 11, 'The Battle', 'On a stormy battlefield, Casca, Griffith''s second in command, is wounded while fighting the leader of an enemy army. Guts runs to her rescue but when she passes out at the edge of a cliff, he cannot catch her in time and they both fall into the river below.', 24, '1997-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 12, 'Together', 'Casca is still unconscious, so Guts shelters them in a cave while the rain pours down. She comes to and tells Guts about her past and about Griffith''s.', 24, '1997-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 13, 'Prepared for Death', 'Guts and Casca try to fight their way back to the Hawks while the enemy army they were fighting from before try to stop them.', 24, '1998-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 14, 'Bonfire of Dreams', 'Casca finds Judeau''s division of Hawks and leads them back to where Guts was fighting alone. Although injured, he defeated all the enemy soldiers by himself. They return to the Hawks'' camp and Casca tends to Guts'' wounds.', 24, '1998-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 15, 'The Decisive Battle', 'The King of Midland and his various generals confer about Doldrey Castle, long since captured by the Chudan Empire. Griffith plans an attack and the King agrees despite the protests of his other officers. Only one other general supports Griffith''s actions. The Hawks attack Doldrey.', 24, '1998-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 16, 'The Conqueror', 'With the help of Nosferatu Zodd, Guts defeats the defender of Doldrey Castle.', 24, '1998-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 17, 'Moment of Glory', 'With the victory at Doldrey, Griffith is promoted to White Phoenix General, an aristocratic title. The Queen of Midland and other court conspirators try to poison Griffith.', 24, '1998-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 18, 'Tombstone of Flames', 'Griffith has his revenge by having the Queen''s castle burned down.', 24, '1998-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 19, 'Separation', 'Griffith will not let Guts simply leave. He says that Guts belongs to him.', 24, '1998-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 20, 'Sparks', 'Guts arrives at the home of Godo the swordsmith and stays there for a while while Godo crafts a new sword for him. Guts practices more on his sword techniques with the help of Godo''s little daughter Erika.', 24, '1998-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 21, 'Confession', 'Guts returns in time to save the remaining Hawks from annihilation.', 24, '1998-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 22, 'Infiltration', 'With Guts help, Casca and the Hawks hope to rescue Griffith.', 24, '1998-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 23, 'Eve of the Feast', 'Breaking away from the King''s pursuing armies, the few Hawks left contemplate their future. Guts comforts Casca, who is despondent over Griffith''s condition. Griffith begins to dream.', 24, '1998-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 24, 'The Great Eclipse', 'Seduced by the promises of demons and his dreams from his childhood, Griffith agrees to fulfill his destiny and become one of the God Hand demons.', 24, '1998-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0318871')) AND numero_temporada = 1), 25, 'Time of Eternity', 'Griffith''s men are sacrificed to the demon''s appetites. Guts fights on, at first to save Griffith, then to save himself from the result of Griffith''s ambition.', 23, '1998-04-01');
