INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 1, 'Milfay', 'Ben reluctantly joins the carnival after the bank forecloses on his family''s Oklahoma farm. Brother Justin has a bizarre encounter with a poor parishioner. Sofie has a run-in at a small-town gas station.', 58, '2003-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 2, 'After the Ball Is Over', 'Ben uncovers a piece of his past as a result of Jones'' sense of humor. Justin tries to persuade a parishioner to make a deal in real estate. Sofie endures a frightening mishap involving her mother. Samson changes the carnival''s course.', 57, '2003-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 3, 'Tipton', 'Ben is the main attraction when Samson refashions the carnival as a religious revival to satisfy a town''s moral underpinnings. Justin has a powerful ally in a fight against city hall. Sofie accompanies Ben on a journey into his past.', 50, '2003-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 4, 'Black Blizzard', 'Jones looks to management when the crew turns mutinous. Appolonia is displeased with Sofie''s romantic tastes. Justin faces a difficult choice between his congregations. Ben is tested by Lodz.', 47, '2003-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 5, 'Babylon', 'Samson tries to improve the troupe''s spirits with a night of revelry. Ben has an enlightening experience at the bottom of a mineshaft. A group of miners is anxious for entertainment.', 49, '2003-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 6, 'Pick a Number', 'Revenge-minded carnies practice their own form of retribution. Justin encounters a group of hobos on his journey of self-discovery. Ben returns from another strange experience.', 57, '2003-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 7, 'The River', 'After a recent tragedy, Stumpy and Rita Sue debate their future in the carnival. In her brother''s absence, Iris receives help from a radio reporter. Ben helps Ruthie with her act.', 52, '2003-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 8, 'Lonnigan, Texas', 'Lodz disagrees with Samson''s decision to send Ben on a business trip for the carnival. A radio-show host tries to help find a wandering Justin. Sofie considers a career change.', 58, '2003-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 9, 'Insomnia', 'Ben tries to escape his dreams by staying awake. Iris uses a radio ally to help locate Justin. Samson goes back to the drawing board to increase business.', 46, '2003-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 10, 'Hot and Bothered', 'Ben and Samson go in search of the mysterious Scudder. Sofie accuses her mother of foul play. Lodz waits patiently for Ben for fall asleep. Justin returns to Mintern with a new plan.', 53, '2003-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 11, 'Day of the Dead', 'Rita Sue teaches a newcomer a few tricks of the trade. Balthus is nervous about Tommy Dolan''s allegations. Lodz gets approval from Management to help Ben.', 55, '2003-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 1), 12, 'The Day That Was the Day', 'A distraught Ben finally meets with Management. In California, Balthus and Justin deal with the tragic undercurrents of their ministry. Stumpy and Rita Sue try to save their marriage. Samson must think fast when the law comes to the carnival.', 55, '2003-11-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 1, 'Los Moscos', 'The Dust Bowl circus troupe deals with the fallout from a fatal fire and, in California, Brother Justin reaches new converts on the radio. Lila wonders what happened to Lodz. Ben takes off to find Scudder.', 51, '2005-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 2, 'Alamogordo, NM', 'The troupe sends out search parties when a distraught Sofie goes missing. Justin and Iris welcome a new housekeeper. Samson accuses Stumpy of skimming. Ben visits an old acquaintance of Scudder''s in New Mexico.', 52, '2005-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 3, 'Ingram, TX', 'Dolan continues his quest to get to the bottom of the Ministry arson. Gabriel gets into the act with Ruthie, who experiences another supernatural vision. Ben happens upon some distant relatives.', 51, '2005-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 4, 'Old Cherry Blossom Road', 'Lila hasn''t given up trying to find out what happened to the missing Lodz. Iris begs her brother not to harbor so many secrets. Jones finds new work for Sofie. Balthus sees another display of Justin''s power.', 57, '2005-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 5, 'Creed, OK', 'After a conversation with Ruthie, Sofie reaches out to Ben; Stumpy wagers on an important fight. Dolan puts pressure on Justin, who sees things in a new light after receiving a mysterious gift. Stroud''s quest to find Ben continues.', 57, '2005-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 6, 'The Road to Damascus', 'Samson runs into an old acquaintance when the troupe crosses paths with another carnival. Rita Sue''s business decisions give Stumpy fits. Justin and Iris struggle with a tough sermon. Libby''s honor is in need of defense.', 57, '2005-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 7, 'Damascus, NE', 'Stroud is closing in on Ben, who pays a visit to a run-down hotel. Justin and Iris pacify a bishop with a good meal. Sabina shares her secrets with Libby; the troupe is concerned about Sofie. Jones gets a favor from Libby.', 46, '2005-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 8, 'Outskirts, Damascus, NE', 'A local politician receives Iris and Justin''s support. Ruthie tries to hide from her visions. Rita Sue takes charge of Stumpy''s debt. Smith sees trouble for Justin. Sofie gets new work. Libby has shocking news for her parents.', 54, '2005-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 9, 'Lincoln Highway, UT', 'Ruthie''s latest vision leaves evidence behind. Lila hasn''t given up her search for the missing Lodz. Eleanor goes on a picnic with Iris. Justin''s powers calm a chaotic gathering.', 53, '2005-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 10, 'Cheyenne, WY', 'Justin has help avoiding a disaster. Iris locates another branch of her family tree. Stroud tries a strength-in-numbers approach. Libby is cowed by her mother''s authority. Ruthie pays another late-night visit to Lila.', 52, '2005-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 11, 'Outside New Canaan', 'Lila voices her opposition to Samson''s itinerary for the troupe. Justin''s baptism of the faithful coincides with another tragedy and a startling event in the migrant camp. Libby pleads with Jones to reveal his secret. Sofie sees a familiar face.', 56, '2005-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0319969')) AND numero_temporada = 2), 12, 'New Canaan, CA', 'Samson tries to stay a step ahead of impending chaos. Stroud does his best to protect Justin. Ben''s powers face the ultimate test.', 53, '2005-03-27');
