INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')), 1, 'Season 1', '1876. The Black Hills Indian Cession, two weeks after Custer''s last stand. Witness the birth of an American frontier town – and the ruthless power struggle between its just and unjust pioneers. In an age of plunder and greed, the richest gold strike in American history draws a mob of restless misfits to an outlaw settlement where everything – and everyone – has a price. The settlers, ranging from an ex-lawman to a scheming saloon owner to the legendary Wild Bill Hickok and Calamity Jane, share a constant restlessness of spirit, and survive by any means necessary. Welcome to Deadwood... a hell of a place to make your fortune.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 1, 'Deadwood', 'Former Montana marshal Seth Bullock starts a hardware business for miners, and the arrival of Wild Bill Hickok creates a stir. Meanwhile, a corrupt saloon owner brokers a land claim for a wealthy New Yorker.', 61, '2004-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 2, 'Deep Water', 'Calamity Jane helps Doc protect a young girl who survived a recent massacre. New Yorker Brom Garret realizes he may not be cut out for prospecting. Dan mulls over a difficult order from Al Swearengen.', 56, '2004-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 3, 'Reconnoitering the Rim', 'Believing he''s been duped, Brom Garret threatens to call the Pinkertons on Swearengen. Star and Bullock finally reach a deal on their hardware-store property. A new gambling outfit arrives from Chicago.', 52, '2004-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 4, 'Here Was a Man', 'Alma asks Hickok to investigate the tragic fallout of her husband''s gold claim purchase. McCall plots revenge after being humiliated at poker. Charlie Utter departs camp for Cheyenne. Doc Cochran makes a house call to the Bella Union.', 58, '2004-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 5, 'The Trial of Jack McCall', 'The town buries its most famous casualty while the man responsible is tried in Swearengen''s saloon. Trixie helps a widowed Alma care for an orphan. Doc warns of an impending epidemic.', 55, '2004-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 6, 'Plague', 'Bullock''s form of vigilante justice meets resistance from the locals. The town fathers band together to fight an epidemic. Farnum reluctantly agrees to keep an eye on Alma and Trixie. Swearengen adds journalist to his colorful résumé.', 52, '2004-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 7, 'Bullock Returns to the Camp', 'Bullock''s vigilantism makes new enemies. Utter returns to Deadwood to say goodbye to an old friend. Teenage siblings arrive on a quest to find their father. Alma holds on to her late husband''s claim despite another offer from Farnum.', 49, '2004-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 8, 'Suffer the Little Children', 'A much-needed vaccine arrives in Deadwood. There are rumblings of a treaty with the Sioux. Swearengen is reluctant to accept advice from Farnum while Trixie is away. Alma reconsiders her plans for her gold claim. Stubbs learns an important lesson from Tolliver.', 55, '2004-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 9, 'No Other Sons or Daughters', 'Swearengen makes an effort to set up an informal government. Anna and Bullock discuss Ellsworth. Jane receives a job offer from Utter. Tolliver agrees to let Stubbs strike out on her own.', 58, '2004-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 10, 'Mister Wu', 'Swearengen receives a double dose of irritation when a drug supply is stolen and bad news arrives from a nearby town. Rev. Smith is an unlikely customer at the Gem. Merrick hatches an idea for Deadwood''s first club.', 53, '2004-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 11, 'Jewel''s Boot Is Made For Walking', 'Adams helps Swearengen out of a jam. Jewel seeks out Doc for treatment. Leon and Eddie go back to work for Cy. Alma''s father arrives from New York. The camp''s choice for a sheriff doesn''t please Bullock.', 58, '2004-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 1), 12, 'Sold Under Sin', 'In the first-season finale, Farnum and Tolliver take advantage of the arrival of a U.S. Army general. Adams teaches Clagett a thing or two about loyalty. Bullock reacts when Alma''s father states his intentions regarding her claim.', 60, '2004-06-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')), 2, 'Season 2', '1877. A new day is dawning in the Black Hills outlaw camp of Deadwood. For better or worse, times are changing, and the transformation from camp to town is imminent. Unsavoury new arrivals - looking to cash in on the lucrative anarchy – and a government of outsiders usher in an era of hard decisions and brutal power struggles among the camp''s founders. Seth Bullock is the new Sheriff and forced to stand his ground against two conniving brothel owners: cutthroat Al Swearengen, and his chief rival, the cunning Cy Tolliver. The women of Deadwood prove their mettle as Calamity Jane, Alma Garret, Trixie and Joanie stake their claim in this dangerous town of scheming misfits, all learning the hard way... fortune comes with a price...');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 1, 'A Lie Agreed Upon (1)', 'Bullock and Swearengen settle their most recent score with a bloody brawl, and Joanie welcomes her new business partner---with or without Cy''s blessing. Also: a stagecoach brings important passengers; and Utter and Bullock investigate a shooting at Tom Nuttall''s.', 49, '2005-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 2, 'A Lie Agreed Upon (2)', 'Calamity Jane returns to camp; Swearengen nurses his wounds while Dan and Johnny await Bullock''s next move; Joanie and Maddie prepare their new place of business; Alma is asked to make a decision about her future. Maddie: Alice Krige. Adams: Titus Welliver.', 51, '2005-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 3, 'New Money', 'Swearengen''s deteriorating health worries his employees. Alma ponders a real-estate move after surveying her operation. A mining-company agent makes his presence known. Maddie lets Joanie in on a secret about their first client.', 58, '2005-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 4, 'Requiem for a Gleet', 'Alma fires Miss Isringhausen as her ward''s tutor. Bullock struggles with domestic life. Cochran suggests a risky surgical procedure for an ailing Swearengen. Dority deals with a former associate''s robbery proposal.', 53, '2005-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 5, 'Complications', 'Doc Cochran advises Dan and Johnny how to help Swearengen''s recovery. Thriving business at a new brothel leads to a startling discovery by Tolliver. Merrick gets a scoop from Yankton about gold claims. Bullock''s badge comes in handy for Commissioner Jarry.', 57, '2005-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 6, 'Something Very Expensive', 'Merrick gives a schoolteacher a tour of the camp. An influx of Chinese labor enters the workforce. Swearengen is finally able to honor appointments. Alma suggests the idea of a bank; and Bullock insults the owner of a gold claim.', 51, '2005-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 7, 'E.B. Was Left Out', 'Alma and Bullock discuss the camp''s financial future. Swearengen shares news about an important visitor. Wolcott seeks to make a deal with Utter involving Wild Bill Hickok''s last letter. Tolliver relies on Lee''s expertise.', 51, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 8, 'Childish Things', 'Wolcott reports his gold-claim acquisitions to his employer, George Hearst, and Nuttall shows off his new bicycle. Meanwhile, Miss Isringhausen reaches an agreement with Swearengen, who also meets with Bullock to discuss alternatives to annexation.', 50, '2005-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 9, 'Amalgamation and Capital', 'Wolcott draws Utter''s ire during the questioning of a suspect. Merrick is overzealous in re-establishing his newspaper. Fields and Hostetler have little luck with a wild horse. Swearengen alters his agreement with Miss Isringhausen.', 48, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 10, 'Advances, None Miraculous', 'Cochran''s ominous prognosis puts the camp on alert. Smallpox survivor Andy Cramed returns as a minister. Swearengen asks an unlikely pair to pull a scam on Commissioner Jarry. Martha Bullock has second thoughts about staying in Deadwood.', 49, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 11, 'The Whores Can Come', 'Jarry worries that Bullock and George Hearst will side with Montana on the annexation issue and a showdown looms between Wu and Lee. Andy Cramed holds his first religious service, though he doesn''t count on Tolliver''s participation.', 47, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 2), 12, 'Boy the Earth Talks To', 'Mining magnate George Hearst arrives while the camp is preparing for a celebration. Yankton officials react to a Swearengen power play. Violence erupts among the town''s Chinese population.', 55, '2005-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')), 3, 'Season 3', 'The lawless era in Deadwood is coming to an end. As the town''s first elections approach, it becomes apparent that, like it or not, civilization is on its way. But a civilized town is not necessarily a peaceful town, and the power struggles that determine the fate of Deadwood have never been more brutal. A ruthless newcomer, businessman George Hearst, threatens to reshape the town in his own image, forcing Deadwood''s settlers – including the steadfast lawman Seth Bullock and the cutthroat saloon owner Al Swearengen – to form strategic alliances if they expect to thrive, and survive. While bloody conflicts change the face and fate of the town, the citizens of Deadwood come to the harsh realization... some fortunes are better left unclaimed.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 1, 'Tell Your God To Ready For Blood', 'Elections are just days away, and Bullock lets his temper get away from him. Alma''s pregnancy is not progressing as expected, and Swearengen baits Hearst.', 53, '2006-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 2, 'I Am Not The Man You Take Me For', 'Campaign speeches are rescheduled, Sol makes an investment, Alma''s condition worsens, and Hearst starts a deadly game with Swearengen.', 52, '2006-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 3, 'True Colors', 'A dandy arrives by stage coach and immediately begins exploring how to bring culture to the camp, Alma and Hearst negotiate business, and Hearst''s Aunt Lou comes to camp.', 51, '2006-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 4, 'Full Faith and Credit', 'Alma presides over the bank''s grand opening, the feud over the livery between Steve and Hostetler tests Bullock''s patience, Swearengen taps Adams to negotiate with Hearst, and Joanie has reservations about Langrishe''s offer to buy her place.', 51, '2006-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 5, 'A Two-Headed Beast', 'Tolliver looks for a representative, the Captain calls Dan out, Swearengen continues to be perplexed by Hearst''s moves, and Alma and Ellsworth''s relationship takes a turn.', 53, '2006-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 6, 'A Rich Find', 'Hearst''s feathers are ruffled, Aunt Lou''s son comes to town, and Bullock and Swearengen make a decision.', 52, '2006-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 7, 'Unauthorized Cinnamon', 'A meeting of the elders occurs with surprising results, Doc''s absence is noted by Swearengen, Alma battles her addiction, and Sol offers Trixie something she never expected.', 50, '2006-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 8, 'Leviathan Smiles', 'The letter is published, Wyatt Earp hits town, delays continue with the theater, and Hearst makes a move.', 53, '2006-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 9, 'Amateur Night', 'An Amateur Night is organized by the new theater troupe, Pinkertons hit town, the students move to their new school, and Hearst makes another move regarding the elections.', 49, '2006-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 10, 'A Constant Throb', 'Swearengen is spurred to action when a prominent camp member is attacked, Langrishe makes arrangements for his theater, and Jane has an epiphany.', 48, '2006-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 11, 'The Catbird Seat', 'Another attack is made at Hearst''s behest, Harry and Bullock travel to Sturgis for campaigning, and there''s unrest in Langrishe''s troupe.', 49, '2006-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348914')) AND numero_temporada = 3), 12, 'Tell Him Something Pretty', 'Election day arrives, Hearst has his revenge, Sol and Trixie have it out, and Tolliver releases rage at his impotence.', 50, '2006-08-27');
