INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 1, 'Pilot', 'When smart, cynical 18-year-old George is killed by an errant toilet seat falling from space, she joins the ranks of an undead group of grim reapers. As she clumsily learns to adjust to her new role in the afterlife, George haphazardly hurtles towards her first dreaded assignment: to collect the soul of a little girl.', 74, '2003-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 2, 'Dead Girl Walking', 'George tries to shirk her new grim reaper responsibilities, but discovers that doing so leads to nasty consequences for the souls. She also attempts to get a real job by once again gracing the doorway of the Happy Time Temp Agency.', 41, '2003-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 3, 'Curious George', 'George discovers the price that the dead pay when they try to hang on to their past.', 44, '2003-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 4, 'Reapercussions', 'George finds a loophole in the "reaper rules" and decides to spare her next soul, but quickly learns that if you flip off Fate, Fate flings it back at you ten-fold.', 43, '2003-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 5, 'Reaping Havoc', 'George realizes that even the undead need friends, but she loses one when a reaper decides to jump to the other side.', 42, '2003-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 6, 'My Room', 'George meets her new roommate, Daisy Adair, a glamorous, but annoying 1930s ingenue-turned-reaper who has joined their group.', 44, '2003-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 7, 'Reaper Madness', 'George gets her first post-mortem kiss from a doomed schizophrenic who can see the gravelings.', 44, '2003-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 8, 'A Cook', 'George gets a pet and Rube takes a shift on the grill at Der Waffle Haus.', 44, '2003-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 9, 'Sunday Mornings', 'George makes a new friend and discovers her dad is not the person she thought he was, while Roxy''s actions cause an obnoxious lout to find religion.', 44, '2003-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 10, 'Business Unfinished', 'Daisy enlists George''s help in fleecing a wealthy society matron''s son, and Roxy faces her annual struggle to come to terms with her death.', 44, '2003-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 11, 'The Bicycle Thief', 'Needing money to buy a bicycle, George gets a new job -- and an awkward farewell party at Happy Time - while her fellow reapers face their own complications.', 43, '2003-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 12, 'Nighthawks', 'George panics when Rube is assigned to pop a soul at her family''s home.', 43, '2003-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 13, 'Vacation', 'Death takes a holiday and the reapers use the break to catch up on some paperwork.', 41, '2003-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 1), 14, 'Rest in Peace', 'While George tries to get her old job back, her family prepares to visit her grave.', 41, '2003-09-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 1, 'Send in the Clown', 'At her day job, George gets to train the boss''s cute, but dumb, nephew, while Mason dresses as a clown to reap a soul at a kid''s birthday party.', 45, '2004-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 2, 'The Ledger', 'George figures that with all the bad luck she had while she was alive, things might even out in the afterlife. But death isn''t like that.', 45, '2004-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 3, 'Ghost Story', 'In an attempt to bond with her co-workers, George goes on the annual Happy Time retreat, but she can''t escape her duties as a grim reaper.', 45, '2004-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 4, 'The Shallow End', 'George reflects back on her childhood and decides that the secret to popularity is being mean to people.', 45, '2004-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 5, 'Hurry', 'Deadlines loom large as the reapers snatch some hurried souls and George helps Delores impress an efficiency expert studying Happy Time''s operations.', 45, '2004-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 6, 'In Escrow', 'George faces her first big decision at Happy Time, and Joy looks forward to a new life after accepting an offer on the family home.', 45, '2004-08-29');
