INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 8, 'The Escape Artist', 'George nearly falls for someone she is supposed to reap, while Reggie makes friends with a young pet reaper.', 45, '2004-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0348913')) AND numero_temporada = 2), 9, 'Be Still My Heart', 'George reunites with her new love at his father''s funeral.', 45, '2004-09-19');
