INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 1, 'Black White Supremacist', 'Dave pokes fun at an annoying Mitsubishi car commercial. Dave appears in a video to show Popcopy copy store employees how to annoy the customers. Dave makes a case for hip-hop''s degradation of women, which ruins the legacy of Nat King Cole. Learn how to order your very own home stenographer. Dave plays a blind, angry white supremacist who joins the KKK, but doesn''t know he''s black.', 22, '2003-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 2, 'Introducing Tyrone Biggums', 'Dave plays crack addict Tyrone Biggums, who gives a speech to an elementary school classroom. Also featuring musical guest Mos Def.', 22, '2003-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 3, 'Love Those Breasts', 'Dave plays an angel who shows a woman, regretful of her large chest, the error of her ways in "It''s a Wonderful Chest." A shopping network spoof finds QVC selling very odd and distasteful items. Dave also shares humorous outtakes from the classic miniseries "Roots." Also featuring musical performer Talib Kweli.', 22, '2003-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 4, 'Slavery Reparations', 'Dave gives out awards to women with great "New York Boobs" and assesses the problems that would result from offering slavery reparations. Also featuring musical guest Busta Rhymes.', 22, '2003-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 5, 'Great Moments in Hookup History', 'Dave looks at "Great Moments in Hook-Up History" and is an interview guest on "Inside Chappelle''s Show Studio." Paul Mooney hosts a segment of "Ask a Black Dude." Redman offers up his new "Redman Potty Fresh" toilet cleaner in a commercial, and Dave shows a commercial for "Rocka Pads."', 22, '2003-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 6, 'The Mad Real World', 'Dave envisions what "The Real World" would be like with a black cast that includes one super white man. Also featuring musical performer David Broom.', 22, '2003-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 7, 'Wu-Tang Consulting Firm', 'Dave takes a look at a great moment in hook-up history and shows "Real Movies" based on "The Matrix" and a grim look at "Pretty Woman." The Wu Tang Clan advertises their new financial firm, and Paul Mooney offers up another segment of "Ask a Black Dude." A Jedi Scandal is exposed. Also featuring music performer Killer Mike.', 22, '2003-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 8, 'The Return of Tyrone Biggums', 'Dave looks at what really happened behind the scenes of the movies "Ghost" and "Half Baked." Dave goes inside the racism present among Hollywood''s animal stars. Dave also returns as crackhead Tyrone Biggums, whose friends stage an intervention and take him to a rehab center. Also featuring a musical performance by Slum Village.', 22, '2003-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 9, 'Blackzilla', 'Dave invades Japan in the sci-fi-themed "Blackzilla" and stars in his own video game. Dave also offers up a look at the "Player Hater''s Ball." Also featuring musical performer The Roots.', 22, '2003-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 10, 'Inner City Gang Wars', 'Dave looks at one of the world''s greatest wars. He also examines R. Kelly''s older videos to point out the future sex crimes that are indicated in the material. Also featuring another segment of "Ask a Black Dude" with Paul Mooney and a musical performance by GZA.', 22, '2003-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 11, 'Fisticuffs', 'Funkmaster Flex hires a rapper, played by Dave, who keeps repeating the same non-lyrical phrases over and over again. Dave visits a kid with cancer, but takes no mercy when he plays the kid at Playstation 2. Dave also buys a camera that has the power to see people''s innermost thoughts. Also featuring music performer De La Soul.', 22, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 1), 12, 'Trading Spouses', 'Dave delves into what would happen if couples attempted "Trading Spouses" and introduces a new family-oriented form of marijuana which contains no THC. Also featuring musical guest Blackstar.', 22, '2003-04-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 1, 'The Racial Draft', 'Dave runs for office and offers a look at life in slow motion. Dave also plays Samuel L Jackson in a beer commercial, and co-commentates on the first-ever "Racial Draft."', 22, '2004-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 2, 'The Niggar Family', 'Dave looks at what it would be like to have a black version of watermelon-smashing comedian Gallagher. Paul Mooney plays "Negrodamus" and Dave plays Calvin, who gets a job at WacArnolds. Also featuring music performer DMX.', 22, '2004-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 3, 'White People Can''t Dance', 'Dave Chappelle examines the age-old myth about white people''s inability to dance. Dave tries out a new sleep aid. The Three Daves: A retrospective look at Dave at age 18, 24 and 30.', 22, '2004-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 4, 'True Hollywood Stories - Rick James', 'Dave unveils the Love Contract and offers up the True Hollywood Story of actor Charlie Murphy, along with musical guest Ludacris.', 22, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 5, 'True Hollywood Stories - Prince', 'Paul Mooney provides answers about the mysteries of life as "Negrodamus." "Charlie Murphy''s True Hollywood Story" focuses on Prince, as he takes to the basketball court. Also featuring musical guest Cee-Lo.', 22, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 6, 'If The Internet Were Real', 'Dave examines what the daily life of rapper Lil John might be like and tries to imagine how the internet would look if it was an actual place. Also featuring musical guest Anthony Hamilton.', 22, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 7, 'World Series of Dice', 'Dave and his friends have a mishap at the drive-thru. A look at the World Series of Dice. Also featuring musical guests Common and Kanye West.', 22, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 8, 'I Know Black People', 'Dave hosts the game show "I Know Black People" and offers up another look at "When Keeping it Real Goes Wrong." Also featuring musical performer Erykah Badu.', 22, '2004-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 9, 'Oprah''s Baby Daddy', 'Dave thinks Oprah is pregant with his child. Dave also goes into his experience as a member of the O.J. Simpson trial jury. Also featuring musical guest Wyclef.', 22, '2004-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 10, 'Making Da Band', 'Dave takes a closer look at the P. Diddy-produced reality television show called "Making Da Band" and introduces a new children''s show called "Kneehigh Park." Also featuring musical guests Snoop Dogg, and Wyclef and Q-Tip.', 22, '2004-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 11, 'Greatest Misses', 'Dave introduces skits that were too crazy to make the cut, including footage of a trip to the Nelson Mandela bootcamp for teenagers. Dave also imagines what it would be like if the whole world was gay. Also featuring musical guests Kanye West and Mos Def.', 22, '2004-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 12, 'The Wayne Brady Show', 'Dave quits his show at Comedy Central and is promptly replaced by comedian Wayne Brady. Dave returns as crackhead Tyrone Biggums, who appears as a guest on "Fear Factor." Dave also hangs out with Wayne Brady, who proves to be unexpectedly menacing. Also featuring music performer Talib Kweli.', 22, '2004-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 2), 13, 'Black Bush', 'Dave looks at recent world events and tries to assess the way things would have gone had President Bush been black. Dave takes a look back at the first black person in history to use a white toilet. Dave also examines a moment in the life of Lil Jon when he plays the rapper while talking to the real Lil Jon on the phone. Also featuring a musical performance by Big Boi.', 22, '2004-04-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')), 3, 'The Lost Episodes', 'Three "lost" episodes of Dave Chappelle''s hilarious sketch comedy show turn up in this collection of laughs -- and it''s a good thing someone finally found them. Dave''s in top form as he mines all manner of controversial material for humor.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 3), 1, 'Lost Episode 1', 'Dave looks to enact vengeance on everyone who has done him wrong in the past after signing a sweet new deal. Meanwhile, people suddenly charge him a lot more money for even the most trivial things that used to cost very little.', 22, '2006-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 3), 2, 'Lost Episode 2', 'Dave hits the campaign trail as yell-happy presidential candidate Howard Dean and assumes the role of an antagonistic Gary Coleman. He also attempts to elude a crop of persistent racial stereotype pixies.', 22, '2006-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0353049')) AND numero_temporada = 3), 3, 'Lost Episode 3', 'Dave meets the powerful Show Business and offers a look at a bunch of monsters who have seen their share of discrimination.', 22, '2006-07-23');
