INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217'), 'Drama');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 1, 'Season 1', 'The first season of Nip/Tuck premiered on July 23, 2003 and concluded on October 21, 2003. It consisted of 13 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 1, 'Pilot', 'Old friends Sean (the family  man) and Christian (the playboy) are partners in a plastic surgery office.  Their relationship is under fire after Christian operates on a Colombian drug lord who pays him in drug money.  Sean''s family life is also in upheaval, and he is headed for a mid-life crisis.', 67, '2003-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 2, 'Mandi/Randi', 'Twin sisters want plastic surgery done to look different from each other. Sean moves out so he can experience life as a single man. Matt decides to try and perform a circumcision on himself after his girlfriend sees his penis. Christian is plagued with thoughts of Julia.', 48, '2003-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 3, 'Nanette Babcock', 'Sean and Julia discover Matt has tried to circumcise himself. The business is sued by a faithful client after Sean accidentally leaves a surgical tool inside of her body.  Meanwhile, Christian and Grace struggle with a mentally unstable patient.', 49, '2003-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 4, 'Sophia Lopez', 'Two recurring characters are introduced in an episode that teaches the odd-couple plastic surgeons a few lessons about moral boundaries. Patti D''Arbanville plays Wallis Forsythe, a pornography mogul who meets Christian at a party and agrees to send some business his way. And Joey Slotnick plays Merrill Bobolit, a hack surgeon who''s more successful than Sean and Christian because of his willingness to take on any client. Forsythe''s easy money and Bobolit''s sleazy competition inject a dose of conflict into Sean and Christian''s partnership--as if it needed any more of it!', 47, '2003-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 5, 'Kurt Dempsey', 'An ex-lover returns and leads Christian to a sexaholics meeting while Sean and Julia deal with an unexpected pregnancy.', 46, '2003-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 6, 'Megan O''Hara', 'Someone is vandalizing Christian''s possessions, and he attempts to find the culprit.  A chemotherapy patient who is considering breast implants brings excitement to Sean''s life, and Matt finds himself in a threesome with Vanessa and Riley.', 48, '2003-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 7, 'Cliff Mantegna', 'Christian''s difficulties with Kristin are exacerbated when his feelings for Julia are revealed.   Jude is hired as an intern, to sexy and disastrous results.  Matt is caught mid-threesome by Julia.', 47, '2003-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 8, 'Cara Fitzgerald', 'Matt accidentally hits Cara with Henry''s car, and calls Sean in to help when Cara''s mother, for religious reasons, refuses drugs and surgery to treat her injuries. Christian discovers that a patient used plastic surgery to hide a revolting crime and it brings up terrible memories of his own childhood.', 47, '2003-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 9, 'Sophia Lopez  II', 'Sean and Jude''s respective secrets are revealed, and Merril offers Christian an interesting trade: Kimber for a Lamborghini.  Christian accepts, but Kimber discovers the truth and exacts a small revenge.', 47, '2003-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 10, 'Adelle Coffin', 'Sean and Christian learn that they have to take a test in order to continue practicing. Sean and Megan visit a doctor to learn that there is nothing they can do for her. Mrs. Grubman returns to get an operation on her and her fiancé. Christian passes his test, but Sean walks out. Megan commits suicide. Julia finds out about Sean''s affair with Megan.', 47, '2003-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 11, 'Montana / Sassy / Justice', 'Ms. Caine wants an operation to get rid of her "cankles". Sean and Julia are still on the outs. Christian learns he''s going to be a father. Julia steals Christian''s brush to determine if he''s the father of Matt. Sean and Grace learn that Ms. Caine has multiple personalities. Cara recovers and gets close with Matt and Henry. Henry develops feelings for her. Cara asks Matt to the prom. Henry tells Matt that he is going to confess to Cara what happened.', 47, '2003-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 12, 'Antonia Ramos', 'Sean and Christian are reunited with an old friend, Julia bonds with Sofia Lopez, and Christian and Gina clash over their differences in opinion concerning Gina''s pregnancy.', 47, '2003-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 1), 13, 'Escobar Gallardo', 'Christian learns that Kimber and Merril are engaged. Escobar continues to have the surgeons do things for him. Liz is sent to Bermuda after being shot in the leg by one of Escobar''s people. Sean goes to kill Escobar. Escobar makes a deal with Sean; a new face for their freedom. Christian learns, in the delivery room, that he is not the father of Gina''s baby. Julia returns to get the paternity test she had done a while ago. The doctors do surgery on Escobar, and give him the face of a criminal even higher than Gallardo on the Most Wanted List - Armand Ortiz. Ortiz is arrested at the airport for bank robbing and killing a federal agent.', 50, '2003-10-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 2, 'Season 2', 'The second season of Nip/Tuck premiered on June 22, 2004 and concluded on October 5, 2004. It consisted of 16 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 1, 'Erica Noughton', 'During Erica''s facelift, Sean panics and can''t do it. Christian is having some trouble too - he''s slept with Erica, the night of Sean and Julia''s wedding. The surgery continues. Later that day, Christian is having problems with Wilbur, so he calls Julia to come help him. She gets upset on how Christian can''t handle his own responsibilities, and snaps at him for sleeping with her mother.', 55, '2004-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 2, 'Christian Troy', 'Sex gone wrong causes Christian to break his nose, but Christian is worried that Sean''s medical condition will keep him from performing the corrective surgery. He consults a rival (female) plastic surgeon across town. Christian and Gina have sex, but she gets upset when Christian tells her that he''s imagining the female plastic surgeon instead of her. Gina tells him that he looks hideous, so Christian decides to operate on his nose himself, which goes terribly wrong. Christian, trying to show that the McNamara-Troy partnership is worth something, tells Sean that he wants him to fix his nose. When Sean panics, Christian decides to go through the surgery without anesthesia, so they can do it together. Sean performs the surgery successfully. Meanwhile, Matt learns that Harry has been arrested for raping Cara Fitzgerald, and that Harry has told the authorities about the hit-and-run, and that Matt was involved. While under oath, Matt says that he had no involvement with the car accident.', 46, '2004-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 3, 'Manya Mabika', 'Manya has had a "female circumcision" as a young child, so she wants to have corrective surgery. A man requests hair implants all over the exterior of his body. Sean meets Ava, a life-coach, and enlists her to help out Julia. In addition, Sean has problems with Erica, still staying at the house, and Christian has problems with Gina.', 47, '2004-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 4, 'Mrs. Grubman', 'As Julia and Sean''s daughter Annie faces puberty, they must both face the harsh realization of maturity and deal with their own issues about getting older. When Gina tells Christian he can no longer be involved in Wilbur''s life, Christian is forced to reach out to an old flame in order to build a case to gain sole custody of Wilbur.', 46, '2004-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 5, 'Joel Gideon', 'After a car accident due to cell phone use, Sean winds up in the hospital. As a result of the accident, Sean develops a phobia of driving and other dangerous things, causing a dent in his career. He thanks the car company because their safety features saved his life. The car company, wanting a point of view from this doctor who has been in a car accident, offers Sean a new car if he agrees to inspect the cadavers they use as crash test dummies after crash tests. Sean tries to take more risks, causing Julia to become upset. Trying to take more risks, Sean decides to go shark diving, and drags Matt along with him. After realizing how much he cares for his son, Sean decides not to follow through. Christian is reminded that his son is no longer in his life, and he turns for comfort in Julia, who reveals to him that Wilber is not his only son.', 46, '2004-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 6, 'Bobbi Broderick', 'Bobbi Broderick comes to McNamara/Troy to have lipo so she could get a job at Saks. During the consult, she doesn''t bother to read the contract she signs. After the lipo doesn''t turn out to standards, she tries to get revenge against the firm by showing everyone how it "ruined her life" by showing up in restaurants and the lobby of the firm itself. Julia asks Ava to help Matt with his grades, and Ava eventually offers Matt sex in order to focus more on his schooling. Julia tries to speak with Ava about a trouble from her past - a huge mistake she made in college - and Ava realizes it involves Matt''s paternity. A woman whose lips were burnt off goes in for a consult, and learns that the doctors would have to take skin from her vagina to fix her lips. She decides to do it, because her husband has never been intimate with her down there. Sean feels uncomfortable about the woman lying to her husband where the skin has come from. She tells her husband it has come from the back of her legs. Meanwhile, as Matt becomes more attracted to Ava, he is arrested after being caught masturbating outside her window. He seeks Christian to bail him out because he thought he could trust him, but Christian becomes upset for his ignorance. Matt lashes back by saying that he already has a father, and he doesn''t need another one. After Ava and Matt finally have sex, the next morning Matt learns Ava has a son named Adrian - and they''re the same age.', 47, '2004-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 7, 'Naomi Gaines', 'When local model Naomi Gaines is raped & disfigured by an attacker named "The Carver", Sean decides to repair her injuries on a pro-bono basis, thrusting McNamara/Troy into the local media spotlight, trying to overcome the slander caused by Bobbie Broderick. After getting caught sneaking into the house late at night, Matt lies by telling his parents he was studying with Ava''s son Adrian. Adrian is forced to play along with the subject when Julia invites them all to dinner. Adrian reveals Matt & Ava''s relationship, causing Julia to lash out at Ava & Matt. When Matt becomes uncomfortable with his increasingly demanding relationship with Ava, she reveals to him the secret that his mother is keeping from him.', 46, '2004-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 8, 'Agatha Ripp', 'A patient named Agatha Ripp comes in to McNamara/Troy. She reveals to Sean & Christian that she had a stigmata, but she says that it was a lie she said to the church so they would accept her, and that she really cut herself. People of the town turn to Agatha for blessing and renewed faith, despite claiming to be a fraud. When a "stigmata" appears on her legs, the doctors do a blood test to learn that it is not her blood. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 9, 'Rose & Raven Rosenberg', 'Sean and Christian face the challenge of separating conjoined twins. The challenge is more complicated when Sean has difficulties working with Christian after learning the truth about Matt. Their constant bickering has been causing them to lose clients.', 47, '2004-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 10, 'Kimber Henry', 'A man visits with Sean and Christian in order to be given breasts because of the fact his wife lost a breast to cancer. They refuse the job at first, but Liz talks them into doing it. After a while, his wife is overwhelmed with them, and the man wants them taken out, which eventually happens. The wife seems to enjoy them too much, which causes her to question her sexuality.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 11, 'Natasha Charles', 'Natasha Charles, a blind woman, comes into have work on her eyes so she won''t appear blind. Christian begins to fall for her, and he learns a great deal about beauty from her. In an attempt to get Sean back, Julia goes to a female plastic surgeon to have breast implants. Erica visits Julia in her new apartment, and has become upset with her new lifestyle. Erica talks to Sean, and he gets mad at her also. Natasha goes out on a blind date (no pun intended) with another blind person. Christian, at the same restaurant, tells him that she is not pretty like the man had hoped, and he leaves. Christian joins Natasha, and they go home together for an intimate night.', 47, '2004-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 12, 'Julia McNamara', 'After Julia''s accident in the previous episode, Julia turns to Sean and Christian to fix her face. Sean resists at first, but eventually decides to do it after Christian lies to him and says the woman that was going to fix her face botched several jobs. Sean tells Julia that he keeps trying to forgive her and wants to try to love her again, but that it wouldn''t happen right away.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 13, 'Oona Wentworth', 'Maids and servants of a wealthy woman have a party while she is out of town, and they hire a cheap plastic surgeon to give them all Botox -- Merrill Bobolit. The women all have adverse reactions to it, and one of them comes in to have it fixed because bulges have formed on her forehead. Bobolit has now partnered with Madam Rose, who owns a chain of beauty salons. He performs unsanitary plastic surgery for lower prices in her basement, and they proudly promote this new invented "Bobotox". Christian tries to talk some sense into him, and eventually learns that Merrill is hooked on the anesthesia, and is constantly high on it - even during surgery. Christian acts as his sponsor in an AA-type rehabilitation group. Merrill becomes furious with Christian after a girl he wanted flirts with Christian.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 14, 'Trudy Nye', 'Sean and Christian repair the face of a woman abused by her husband; Sean and Julia confront Ava about her relationship with her son Adrian.', 47, '2004-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 15, 'Sean McNamara', 'Beauty is a curse on the world. It keeps us from seeing who the real monsters are.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 2), 16, 'Joan Rivers', 'Joan Rivers consults with Sean and Christian to have all of her plastic surgeries undone, because she wants her grandson Cooper to learn that you don''t have to be perfect. When she ultimately learns what she will turn out like after the work has been finished, she decides to give up on her original plan and asks the doctors to schedule her for a facelift the next morning. Matt is concerned about Ava, who seems obviously depressed. He suggests they go away to Paris and start a new life together, which she reluctantly accepts after some convincing. Matt goes to McNamara-Troy to steal drugs for her to take with them. Christian finds him, and gets upset when he learns Matt is going to Paris. Christian goes to have a talk with Ava, and when trying to make a point using sex, he learns that Ava is really a transsexual. Julia, Sean, and Christian spend the night researching, and trace their way to Maryland and a Gender Reassignment center.', 56, '2004-10-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 3, 'Season 3', 'The third season of Nip/Tuck premiered on September 20, 2005 and concluded on December 20, 2005. It consisted of 15 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 1, 'Momma Boone', 'After Christian''s Carver attack, Sean must look for a new partner to keep the practice going. Sean has to surgically separate an obese woman from a couch she has spent the past three years on. Julia realizes that she has to make a decision about the future of her marriage.', 69, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 2, 'Kiki', 'Sean hires Quentin Costa for six months during Christian''s convalescence.  The two remove tattoos from a former MS-13 gang banger using cutting edge laser technology.  Matt finds Adrian dead in Ava''s house when searching for a plane ticket to Paris. The police thinks it''s suicide.  Julia calls Erica to help Matt deal with questions regarding his sexuality.  Christian and Liz operate to repair a scar on the face of a female gorilla, Kiki.', 44, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 3, 'Derek, Alex, and Gary', 'Matt is getting out of control, and Sean, Julia and Christian are trying to find a solution. Quentin and Christian help two students whose faces are glued to the behind of a third student. Christian starts losing interest in the threesome relationship between Kimber, Kit, and himself. He asks Quentin to get involved with Kit to take her off his hands.', 44, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 4, 'Rhea Reynolds', 'A woman wants surgery to make her look like her when she was younger, to jog her Alzheimer-stricken husband''s memory.  Christian and Sean work on another Carver victim, who does not have the same physical attributes as the other victims.', 44, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 5, 'Granville Trapp', 'Rhea Reynolds is found dead (apparently murdered by the carver). Christian is the prime suspect. A man with a very hollow face (caused by the HIV medication that he''s taking) is this episode''s patient.', 44, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 6, 'Frankenlaura', 'Sean and Christian visit a mortuary where an employee created a woman from body parts of other women. They operate on a German woman. Sean is at a gathering of people over 65, trying to sell them some procedures. Gina and Julia are in business together.', 44, '2005-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 7, 'Ben White', 'Seeking fulfillment in his life, Sean becomes a surgeon for the Witness Protection Programme. A man suffering from Body Integrity Identity Disorder (BIID) threatens Christian''s life in order to force him to amputate his perfectly healthy leg. Julia, Gina, and Liz develop a new skincare product that uses semen as the main ingredient. They keep the main ingredient a secret though. Joan Rivers is the first to test the product and loves it so much she decides to endorse it.', 44, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 8, 'Tommy Bolton', 'Sean has feelings for Nikki Moretti.  Quentin goes after Julia and she welcomes his attention.  Christian has a down-syndrome patient who wants to look like the rest of his family. Christian meets with his birth mother again.', 44, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 9, 'Hannah Tedesco', 'Christian and Quentin disagree over the ethics of an extremely dangerous operation that would enhance their medical reputations. Sean is thinking about giving up everything and disappearing into the Witness Protection Program with Nikki and her son.', 44, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 10, 'Madison Berg', 'Christian still has second doubts about the wedding.  Gina tries to convince Kimber to leave him.  Matt''s new girlfriend compares plastic surgery to the work of the Nazis.', 44, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 11, 'Abby Mays', 'Sean wants Quentin out of the practice after finding out that he''s dating Julia. Christian seems to be ok after Kimber leaving him, but his actions indicate otherwise.', 44, '2005-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 12, 'Sal Perri', 'A plane crashes just after take off in Miami. Julia''s mother might be one of the passengers. Christian, Sean, Julia and Liz are all trying to save the lives of the people that survived the plane crash.', 44, '2005-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 13, 'Joy Kringle', 'Sean and Christian are perform a mico-liposuction on Joy Kringle, a woman who acts as Mrs. Claus during the Christmas season. During her lipo they find a seventeen year old fetus inside her. Julia is not feeling well. A blood test performed by Sean reveals why. She is pregnant.', 44, '2005-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 14, 'Cherry Peck', 'Christian finds out that Kimber didn''t ditch him at the altar but was abducted by the carver. Quentin is a Carver suspect. Julia has bad dreams about her pregnancy. Sean is threatened into doing pro bono work on the transgender woman who was beat up by Matt.', 44, '2005-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 3), 15, 'Quentin Costa', 'The Carver strikes at a sorority house. His identity is revealed. Ariel''s dad kidnaps Matt and Cherry. Ariel''s dad forces Matt to make a life threatening decision, while the carver tries desperately to get his last minute revenge. Julia discovers that there might be something wrong with her baby.', 44, '2005-12-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 4, 'Season 4', 'The fourth season of Nip/Tuck premiered on September 9, 2006 and concluded on December 12, 2006. It consisted of 15 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 1, 'Cindy Plumb', 'Sean and Christian may be celebrating a milestone surgery, but it looks like the future of McNamara/Troy is in jeopardy. Julia tells Sean some devastating news about the baby. Christian decides to redecorate his apartment after a disturbing appointment with his psychiatrist.', 44, '2006-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 2, 'Blu Mondae', 'Sean and Julia make a big decision regarding their unborn baby. Christian and Sean hit troubled waters with their new boss and begin to realize what it really means to have sold their business. Matt''s family doesn''t quite get his decision to pursue a new path in his life.', 44, '2006-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 3, 'Monica Wilder', 'Sean and Julia are looking for a nanny. Sean wants to turn to Christian for support after his hidden desires are revealed. But Chistian is busy going to the gym because he thinks he''s too fat.', 44, '2006-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 4, 'Shari Noble', 'After having a nipple bitten off by her dog, Shari Noble comes in to have it reconstructed before her husband returns from Iraq. Julia meets a breast-feeding expert. Christian and Liz hit a lesbian bar where Christian tries to attract one of the women there but she''s attracted to Liz instead. Sean and Christian meet with a kidney specialist for one of their patients.', 44, '2006-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 5, 'Dawn Budge', 'A lottery winner offers Christian a fortune. Christian certainly needs the money since he''s being blackmailed by James. Christian and Sean are trying to get Matt away from Kimber and Scientology. Sean offers something to Julia.', 44, '2006-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 6, 'Faith Wolper, PhD', 'Sean soon discovers that Monica Wilder doesn''t intend to leave him alone. Christian''s therapist has an obsessive torment to reveal. And Burt Landau proposes an unusual solution upon learning that Christian and Michelle are having an affair.', 44, '2006-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 7, 'Burt Landau', 'Dawn Budge needs an ear transplant. Burt Landau suffered a stroke and asks Christian and Sean to fix his face.', 44, '2006-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 8, 'Conor McNamara', 'Mrs. Grubman is back for more Plastic Surgery this time she wants Christian to preform it after she has passed on. Sean and Julia have conflicts over Conor''s Surgery.', 44, '2006-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 9, 'Liz Cruz', 'Liz''s new gilfriend, Poppy, wants her to have cosmetic surgery. James makes Christian and Michelle help her steal another kidney. Sean offers consultation to Marlowe, who wants longer legs.', 44, '2006-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 10, 'Merrill Bobolit', 'Dr. Merrill Bobolit, who''s out of jail, needs Sean''s and Christian''s professional services. Escobar Gallardo wants them to perform surgery on his face. And Matt tells his family that he''s married and that he and his wife are expecting a baby.', 44, '2006-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 11, 'Conor McNamara, 2026', 'It''s the year 2026. Conor is getting the whole family together. In the present, Julia and Sean''s marriage is at a crossroads.', 44, '2006-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 12, 'Diana Lubey', 'Even though he doubts his ability to maintain a long term relationship Christian proposes to Michelle and a lonely Sean takes a pathological case for rationalities that have as much to do with himself as with the patient, and James requires to use McNamara/Troy for her own operations.', 44, '2006-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 13, 'Reefer', 'Sean drinks to a great extent as he spends a depressing Christmas without his family; Christian gets an surprising gift when a 3-year old Wilber comes back into his life; and James pressures Michelle to help as she takes forceful measures to fill her holiday kidney quota.', 44, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 14, 'Willy Ward', 'Sean contrives to sell his portion of the practice; Michelle''s connection with James finally ends, but not with James'' boss; Gina is not happy to discover about Michelle''s role in Wilbur''s life; Matt tries to rekindle the spark with Kimber; and Poppy and Liz break up.', 44, '2006-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 4), 15, 'Gala Gallardo', 'Sean considers selling his shares of the practice to Christian and Michelle, although Michelle''s past starts to threaten her future with Christian. Meanwhile, Escobar''s wife needs cosmetic surgery.', 44, '2006-12-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 5, 'Season 5', 'The fifth season of Nip/Tuck premiered on October 30, 2007 and concluded on March 3, 2009. The unusually lengthy interval, for an American series, was a direct result of the 2007–2008 Writers Guild of America strike. The season consisted of 22 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 1, 'Carly Summers', 'Sean and Christian have relocated their practice from Miami to Los Angeles. Being new to the city they find themselves having to start from scratch business wise. What they thought would naturally fall into place turns out to require some foot work. So Christian and Sean hit the town and begin discovering a whole new world.', 44, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 2, 'Joyce & Sharon Monroe', 'Sean and Christian learn about the glamorous side of fame and the price that many are willing to pay for it. Julia visits Sean, Christian and Liz in Los Angeles with a surprise announcement.', 44, '2007-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 3, 'Everett Poe', 'Sean and Julia learn more about their new family dynamic as Sean resists Eden''s advances. Kate reveals a secret compulsion. Matt comes to Los Angeles with some troubling news for his fathers.', 44, '2007-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 4, 'Dawn Budge II', 'A series of unfortunate events unfold for an unlucky Dawn Budge, who seeks reparative surgery from Sean and Christian. Annie and Eden start to form a sisterly bond, which unnerves Sean.', 44, '2007-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 5, 'Chaz Darling', 'A patient inspires Sean to take his relationship with Kate in a new direction. Eden uses extreme methods to persuade Christian to perform surgery on a friend. Kimber reaches out to an former business associate when she and Matt fall on hard times.', 44, '2007-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 6, 'Damien Sands', 'Jealous over Sean''s new-found fame, Christian convinces Sean to tape a reality show based on their careers as plastic surgeons.', 44, '2007-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 7, 'Dr. Joshua Lee', 'Sean tries to regain his youth through his relationship with Eden. A violent and traumatic event causes Julia to question her relationship with Olivia. In an effort to better her life, Kimber makes a decision that devastates Matt.', 44, '2007-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 8, 'Duke Collins', 'Sean discovers the secret between Christian and Julia. A hospitalized Matt bonds with his rehabilitation counselor. Eden suspiciously makes peace with Julia. Kimber and Ram reveal their future plans.', 44, '2007-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 9, 'Rachel Ben Natan', 'As Julia''s health worsens, Christian falls back into old habits. Sean hires Gina as the new receptionist at McNamara/Troy in order to get back at Christian. Dawn Budge returns to McNamara/Troy after another unfortunate incident which requires cosmetic surgery.', 44, '2008-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 10, 'Magda and Jeff', 'Sean''s role on Hearts & Scalpels is expanded after he takes on an agent. A suspicious Christian questions Gina''s motives for moving to Los Angeles and working at McNamara/Troy.', 44, '2008-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 11, 'Kyle Ainge', 'Christian attempts to cope in the aftermath of a death. Colleen feels threatened when another talent agency shows an interest in Sean''s acting career.', 44, '2008-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 12, 'Lulu Grandiron', 'Eden looks to Sean for help after getting into business with Kimber and Ram. A group of wealthy socialites hire Christian for all of their cosmetic surgery needs. Sean discovers another side of Colleen.', 44, '2008-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 13, 'August Walden', 'Sean experiences the ugly side of Hollywood in the form of a television critic. Matt experiences a special bond with one of Christian''s patients. The cause of Julia''s ailing health is discovered.', 44, '2008-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 14, 'Candy Richards', 'Tragedy strikes the McNamara/Troy family after Julia learns what has caused her ill health. A visitor from Christian''s past brings revealing news. Sean finds the price of fame to be more expensive than it''s worth.', 44, '2008-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 15, 'Ronnie Chase', 'After surviving the attack by Colleen, Sean''s physical and emotional well-being are still feeling the effects. Meanwhile, Christian receives some disturbing news after lending Liz some moral support with her breast cancer scare.', 44, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 16, 'Gene Shelly', 'After being rejected by Kimber on account of his post-surgery scars and with his chemotherapy making him sick, Christian seeks support from Liz, which leads to a surprising sexual encounter between them. Sean discovers his new lover (Jaime Ray Newman) has a disturbing fetish, and further alienates Julia and Matt when they learn that he has been faking his need for a wheelchair. Raj has a life-altering sexual encounter with the wife (Beth Gargan) of McNamara/Troy''s latest patient.', 44, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 17, 'Roxy St. James', 'Sean tries to deal with his feelings for Julia, while Liz and Christian analyze their relationship and Christian meets someone who understands what he is experiencing with his breast cancer.', 44, '2009-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 18, 'Ricky Wells', 'Matt becomes envious of Sean and Raj bonding together. Christian and Liz give their relationship another chance. Raj''s father pays a visit to see his son.', 44, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 19, 'Manny Skerrit', 'Aidan Stone, a down-on-his- luck writer who has written a biopic about Sean, wants to use it to relaunch his career. Christian is asked by Kimber to give a Botox injection to her daughter so she has a better chance at becoming a baby model. Sean and Christian have been asked by a yoga instructor to perform a procedure in which neither have ever done before.', 44, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 20, 'Budi Sabri', 'A horribly disfigured man is worked on by Christian and Sean. Meanwhile, Sean hopes to strike up a relationship with the new anesthesiologist Teddy Rowe, and Christian goes for a check up with his oncologist.', 44, '2009-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 21, 'Allegra Caldarello', 'Christian decides to employ Dr. Logan Taper for the practice, while Sean is revisited by a former client from Miami to have plastic surgery so she can attract suitors once her husband dies.', 44, '2009-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 5), 22, 'Giselle Blaylock & Legend Chandler', 'As Christian and Liz make their wedding plans, he also looks for a new cancer treatment. Meanwhile, Ram Peters drops Kimber for a newer model, while Teddy informs Sean that someone close to her is gone, and Sean and Christian repair a couples neck wounds which look strikingly similar at McNamara/Troy.', 44, '2009-03-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 1, 'Don Hoberman', 'As Season 6 begins, Christian has news for Liz and the economic downturn has hit McNamara/Troy hard. But the boys might have found a lifesaver in Dr. Mike Hamoui (Mario Lopez), who''s now in L.A. and has found a very profitable niche specialty. Meanwhile, Sean''s relationship with Teddy Rowe (now played by Rose McGowan) has blossomed, and Matt, who''s down on his luck, takes up mime.', 44, '2009-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 2, 'Enigma', 'Unable to sleep, Sean finds himself in an all-night diner, then in an ER; Liz goes after Christian''s boat, leading him to offer Kimber a business deal; Sean and Christian remove tattoos from a teen obsessed with "the darker side of his personality."', 44, '2009-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 3, 'Briggitte Reinholt', 'Sean makes an important decision without consulting anyone; a morose Annie shows up in L.A. with a troubling medical condition; Christian gives Mike (Mario Lopez) tips on how to satisfy Kimber; and a new patient recognizes Teddy.', 44, '2009-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 4, 'Jenny Juggs', 'Christian struggles to understand a patient with big anger-management issues. Sean and Christian learn how Matt is earning an income, despite his attempts to keep it hidden from his family. Teddy arranges a camping trip with Sean, Annie and Conor in order to ease family tensions.', 44, '2009-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 5, 'Abigail Sullivan', 'As Matt''s crime spree catches up with him, Julia returns from New York to help in his recovery from surgery. Sean discovers devastating details about his marriage to Teddy. A new patient suffers from extreme separation anxiety.', 44, '2009-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 6, 'Alexis Stone', 'When a newly married Erica threatens to take custody of Annie and Connor, Sean and Julia present a happy and united front to thwart her efforts. Christian bonds with a new patient as Mike reveals his future plans with Kimber.', 44, '2009-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 7, 'Alexis Stone II', 'Both Matt and Alexis Stone request unusual surgical procedures from Christian. Erica discovers the horrible truth about her new husband. After a lifetime of torment from her mother, Julia seeks revenge upon her.', 44, '2009-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 8, 'Lola Wlodkowski', 'A medical consultation with Liz''s friend leads Christian to contemplate his relationship with Kimber. Sean begins to heal emotionally following an encounter with a perfection-seeking patient.', 44, '2009-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 9, 'Benny Nilsson', 'Christian''s colossal financial debt leads him to deception. An unexpected visitor stirs insecurity within Christian and brings joy to Sean. Christian bonds with a young patient when he learns about his adoption.', 44, '2009-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 6), 10, 'Wesley Clovis', 'Sean experiences an ethical and moral dilemma when McNamara/Troy is requested to perform a surgical procedure on a prison inmate. Kimber questions how far she will go to keep Christian when they receive life-changing news.', 44, '2009-12-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 1, 'Dan Daly', 'When Sean and Christian win a prestigious award from their alma mater, Sean recalls their college years and endures past pains. A new patient who self-mutilates due to a genetic disorder comes to McNamara/Troy for reconstructive surgery.', 44, '2010-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 2, 'Willow Banks', 'Christian refuses to perform surgery on a model who wants to drastically alter her beauty. Awakening after a decades-long coma, a new patient seeks surgery from Sean in order to regain his lost youth.  Kimber redecorates Sean''s new apartment.', 44, '2010-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 3, 'Joel Seabrook', 'Following a failed suicide attempt, a new patient seeks facial reconstructive surgery. Christian tries a risky maneuver with Kimber to heighten their marital passion. Sean performs pro-bono surgery with a charitable surgeon and former college friend in an attempt to quell his guilty conscious.', 44, '2010-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 4, 'Sheila Carlton', 'Christian has a crisis of conscience when Kimber''s mother Brandy visits Los Angeles. Complications arise as Sean prepares for his trip to Africa. A patient requires multiple cosmetic procedures after suffering an attack by a wild animal.', 44, '2010-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 5, 'Virginia Hayes', 'The teenage daughter of Escobar Gallardo seeks out Sean and Christian for answers about her late father, stirring tremendous guilt within Sean. A seemingly common cosmetic procedure for a struggling actress leads to chaos.', 44, '2010-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 6, 'Dr. Griffin', 'Secrets are revealed and past pains are uncovered as Sean and Christian begin psychotherapy together. Liz and Matt divulge their own confidences when they each join a therapy session.', 44, '2010-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 7, 'Christian Troy II', 'Concerned that cosmetic surgery is no longer in vogue, Sean and Christian make a unique attempt to market their surgical practice to boost a lagging clientele. Liz goes on a date with a pharmaceutical representative who is separated from her husband. Christian''s unconscious existential crises, including his loss of Kimber, come to light.', 44, '2010-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 8, 'Edith and Walter Krieger', 'Julia visits Sean and Christian in Los Angeles to share life-changing news -- and rejects romantic advances from both men. A great love from Matt''s past who has caused immeasurable family chaos turns up as Matt prepares to marry Ramona. Liz reveals that she''s happily pregnant.', 44, '2010-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0361217')) AND numero_temporada = 7), 9, 'Hiro Yoshimura', 'Sean and Christian reflect on their relationship. They also remove a scar from an elderly Japanese man and have a surprise for Liz. Meanwhile, Christian makes a deal with Ava.', 44, '2010-03-03');
