INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0362359', 'The O.C.', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0870306'), 'SERIE', 'After being kicked out of his home, a poor troubled youth, is taken in by a public defender and his family where he becomes embroiled in the lives of the wealthy, upper-class neighborhood of Newport Beach, Orange County in California.', '2003-01-01', 'https://m.media-amazon.com/images/M/MV5BNWUzMDViY2YtOGE0OS00NWFhLWJhM2ItNDE2Njc5YmRjZWQyXkEyXkFqcGc@._V1_.jpg');
