INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0365376', 'A Tale of Two Sisters', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0453518'), 'PELICULA', 'After being institutionalized in a mental hospital, Su-mi reunites with her sister, Su-yeon, and they return to live at their country home. But strange events plague the house, leading to surprising revelations and a shocking conclusion.', '2003-01-01', 'https://m.media-amazon.com/images/M/MV5BMTEwMTYwMGQtY2ZhNi00Y2QwLWIxYjktMGY1Mzk4YmE4ODY2XkEyXkFqcGc@._V1_.jpg');
