INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 3, 'Everyone Gets Atrophy', 'The family unites behind Lindsay’s campaign, but Michael senses that something is amiss. Maeby has an idea that George-Michael likes a little too much.', 28, '2018-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 4, 'Old Start, An', 'Gob acquires a new office for the company with a "premium view." Michael gets a shock when he returns to a place that holds a lot of memories.', 29, '2018-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 5, 'Sinking Feelings', 'The Bluths receive/present their award, but it weighs on George Sr. and creates new problems. Michael and George-Michael have a deep conversation.', 28, '2018-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 6, 'Emotional Baggage', 'Michael attempts to bail out Buster. George-Michael finally meets the Howards, and Ron informs Michael that his plans for the movie have changed.', 34, '2018-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 7, 'Rom-Traum', 'George-Michael thinks he''s being lied to by Michael, who thinks he''s being lied to by George Sr. Gob hires guys to help with his "closet conversion."', 31, '2018-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 8, 'Premature Independence', 'As the Second of July parade approaches, Sally steps up her campaign against Lindsay while the Bluths again struggle to keep their stories straight.', 37, '2018-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 9, 'Unexpected Company', 'Buster fails to show for his own prison release party. Michael examines company financial records. George-Michael seeks Anonymous help to deceive Rebel.', 28, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 10, 'Taste Makers', 'Michael jumps at a chance to spend more time with George-Michael, who seeks a clueless president for Fakeblock. Tobias relocates his makeshift family.', 26, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 11, 'Chain Migration', 'As George Sr. attempts to win back Lucille, Michael assembles a mold of their scheme. Meanwhile, Buster gets caught up in Tobias and Gob''s business.', 24, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 12, 'Check Mates', 'George Sr., Lucille and Maeby give honesty a try. Good news becomes bad for George-Michael. Michael remembers there''s always money ... somewhere.', 26, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 13, 'The Untethered Sole', 'Buster''s brief appearance in a TV weather report puts the Bluths back in hot water, but Michael has a plan involving his son''s definitely real company.', 29, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 14, 'Saving for Arraignment Day', 'As the trial kicks off, the Guilty Guys throw the family for a loop. Lucille learns surprising news about Dusty. George-Michael plots a distraction.', 29, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 15, 'Courting Disasters', 'George and Lucille overestimate their new lawyer''s expertise in the courtroom. Two familiar faces testify, and a video sheds more light on the case.', 31, '2019-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0367279')) AND numero_temporada = 5), 16, 'The Fallout', 'As the Bluths come together to unveil a wall, they once again discover that they deserve nothing more than to be saddled with each other forever.', 48, '2019-03-15');
