INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0369179', 'Two and a Half Men', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0927042'), 'SERIE', 'A hedonistic jingle writer''s free-wheeling life comes to an abrupt halt when his brother and 10-year-old nephew move into his Malibu beach house.', '2003-01-01', 'https://m.media-amazon.com/images/M/MV5BMzI2ZDMyNGEtNmIwOS00NTI1LThlZDctYzYzYmE3NDNlNTJlXkEyXkFqcGc@._V1_.jpg');
