INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')), 1, 'Season 1', 'Bachelor Charlie Harper’s carefree life is turned upside down when his uptight brother Alan and nephew Jake move in, sparking chaos and comedy in Malibu.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 1, 'Pilot', 'Carefree jingle writer Charlie Harper has his lifestyle altered when his uptight brother and his 10-year-old nephew move in with him.', 23, '2003-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 2, 'Big Flappy Bastards', 'Despite warnings from Charlie, Jake continues to feed seagulls on the deck and the birds invade the house. Meanwhile, Charlie thinks Judith is taking advantage of Alan, who keeps going to her house to fix things.', 21, '2003-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 3, 'Go East on Sunset Until You Reach the Gates of Hell', 'Jake wants to go home to his mom after he gets sick, prompting Alan to think he''s a failure as a husband and now as a father.', 21, '2003-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 4, 'If I Can''t Write My Chocolate Song, I''m Going to Take a Nap', 'Charlie can''t function when his housekeeper storms off because of Alan''s constant complaints, so Alan tries desperately to woo her back. Meanwhile, Rose comes to Charlie for dating advice.', 21, '2003-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 5, 'The Last Thing You Want Is to Wind Up with a Hump', 'Alan and Charlie have encounters with some highly libidinous soccer moms, but with two very different outcomes.', 19, '2003-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 6, 'Did You Check with the Captain of the Flying Monkeys?', 'The guys go to Evelyn''s house to meet the new man she''s dating, and Charlie realizes the man''s daughter is a woman he''s trying to avoid.', 21, '2003-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 7, 'If They Do Go Either Way, They''re Usually Fake', 'Judith is upset with Alan and Charlie when she learns that a surfer who uses Charlie''s shower walks around half naked in front of Jake . Then Alan''s worried when Judith and the surfer become friends.', 21, '2003-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 8, 'Twenty-Five Little Pre-Pubers Without a Snoot-Ful', 'Alan tricks Charlie into joining him and Judith in leading Jake and his classmates in the school''s annual music show.', 19, '2003-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 9, 'Phase One, Complete', 'Charlie is convinced that a woman who spent the night with him wants to turn their relationship into something serious after she befriends Jake and Evelyn.', 21, '2003-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 10, 'Merry Thanksgiving', 'Realizing he''s losing someone special, Charlie plans a Thanksgiving dinner to convince her he''s a family guy and that she should be with him.', 21, '2003-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 11, 'Alan Harper, Frontier Chiropractor', 'When Alan is surprised to see that Judith has had a makeover and is dating a man, he decides to have Charlie help him transform his image.', 20, '2003-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 12, 'Camel Filters and Pheromones', 'Berta''s granddaughter spends the day at Charlie''s, which isn''t a problem until he learns she''s a beautiful, rebellious 16-year-old.', 21, '2004-01-05');
