INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 14, 'I Can''t Afford Hyenas', 'Charlie''s financial manager informs the carefree jingle writer that he spends money faster than his royalty checks come in, and now he must go on a budget.', 21, '2004-02-02');
