INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 16, 'That Was Saliva, Alan', 'Charlie is perplexed when Frankie, the mysterious woman temporarily living in the Harper household, begins falling for Alan and not him.', 21, '2004-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 17, 'Ate the Hamburgers, Wearing the Hats', 'Charlie''s still brooding over Alan''s choice of their cousin as Jake''s guardian if both parents die when the boy has an accident while in his care and has to be rushed to the hospital.', 20, '2004-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 18, 'An Old Flame with a New Wick', 'Charlie is stunned to learn his ex-girlfriend is now a man.', 21, '2004-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 19, 'I Remember the Coatroom, I Just Don''t Remember You', 'Judith''s devious siren sister stirs things up at Jake''s 11th birthday party when she hits on Alan. Meanwhile, Evelyn brings alcohol and has a party of her own.', 19, '2004-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 20, 'Hey, I Can Pee Outside in the Dark', 'Jake''s sullen mood baffles and bothers the family and prompts Alan and Judith to take him to a child psychologist.', 21, '2004-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 21, 'No Sniffing, No Wowing', 'Charlie plays a tricky game when he gets involved with Alan''s divorce lawyer, who could make things difficult for Alan if she were, say, dumped by a self-centered lothario.', 21, '2004-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 22, 'My Doctor Has a Cow Puppet', 'When Charlie discovers that Alan is sleepwalking, he believes it''s related to his brother''s lack of sex following his divorce, and comes up with a cure.', 21, '2004-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 23, 'Just Like Buffalo', 'When Jake repeats one of Charlie''s sexist remarks in front of Judith''s support group, the women convince Judith to stop Jake''s visits with his dad and Charlie.', 21, '2004-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 1), 24, 'Can You Feel My Finger?', 'Charlie has a pregnancy scare involving one of his one-night stands and decides to go for the big "V," and we''re not talking Vegas.', 21, '2004-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')), 2, 'Season 2', 'Charlie adjusts (badly) to life with family underfoot, while Alan struggles with single fatherhood and dating again, and Jake grows into a lovable troublemaker.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 1, 'Back Off, Mary Poppins', 'Alan learns that Charlie belongs to an exclusive men''s group, and he begs his brother to let him join.', 30, '2004-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 2, 'Enjoy Those Garlic Balls', 'Judith is dating Jake''s pediatrician, and Alan is upset until Charlie points out that if she remarries, his alimony payments will end.', 30, '2004-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 3, 'A Bag Full of Jawea', 'Charlie tries to save Jake from school suspension for giving his teacher (Missi Pyle) the finger by romancing her, but his several attempts fail every time.', 30, '2004-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 4, 'Go Get Mommy''s Bra', 'Jake is very impressed and can''t stop talking about his mother''s new boyfriend, Dr. Melnick, which annoys Alan.   While Evelyn borrows Charlie''s car to help her impress a Saudi prince, because she wants to sell him real estate.  When Charlie gets his car back, he discovers his mother''s bra in the backseat.  When he finds out why it''s there he decides to trade in his car.', 21, '2004-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 5, 'Bad News from the Clinic?', 'Charlie meets his match when he falls for a woman who''s better at playing hard to get than he is.', 21, '2004-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 6, 'The Price of Healthy Gums Is Eternal Vigilance', 'Alan denies having shoplifted a toy as a child and fears he has a dark side, until Charlie admits he planted the toy on Alan to stay out of trouble himself.', 21, '2004-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 7, 'A Kosher Slaughterhouse Out in Fontana', 'Charlie and Alan hire Berta''s sister to cater a party their mother has conned them into throwing for her.', 21, '2004-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 8, 'Frankenstein and the Horny Villagers', 'Alan meets a woman named Nancy at a grocery store, who fulfills every single one of his desires, forcing Charlie to take care of Jake. After knowing Nancy for a few days Alan decides to ask her to marry him, prompting Charlie to try and talk him out of it, and he even gets help from the brothers'' mother.', 21, '2004-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 9, 'Yes, Monsignor', 'When Charlie leaves the house to avoid a date that he can''t stand, he ends up at a coffee shop, where he meets his old girlfriend Lisa.  He finds out that she broke up with her husband, and now has a child. Now he must try to convince Lisa that he''s okay with her having a child.   While Jake tries to justify to his father why he isn''t doing so well in school.', 22, '2004-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 10, 'The Salmon Under My Sweater', 'Charlie tries to get Jake''s approval on a theme song that he is hired to write for a television show, which is based on a comic book that Jake is a fan. While Alan finds out  more about Rose (including how smart she is), when he spends more time with her.', 21, '2004-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 11, 'Last Chance to See Those Tattoos', 'After getting unusually turned down at a bar, Charlie learns that a website has been made dedicated to exposing his lifestyle. Charlie sets out to find who created the site, making amends to all those he stood up, but it''s harder than it looks when all the women take the apology better than expected.', 21, '2004-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 12, 'A Lungful of Alan', 'Alan is jealous of Charlie when an old classmate, who''s now a beautiful woman, seems to be more interested in Charlie.', 21, '2005-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 13, 'Zejdz z Zmoich Wlosów (Get Off My Hair)', 'After an earthquake hits, Judith''s house is damaged and she needs a place to stay. So Alan decides to invite her to stay with him and Charlie, without getting Charlie''s permission.  Charlie isn''t happy with this, but accepts it. Alan becomes jealous when Judith goes on a date, and asks Charlie to find him a date, so that he can show Judith that he dates as well.', 20, '2005-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 14, 'Those Big Pink Things with Coconut', 'The brothers throw out their mother, after she insults the way Alan is raising Jake.  When Alan and Charlie ignore her phone calls, to get their attention she ends up in the hospital.  When Alan and Charlie show up at the hospital they aren''t sure if she''s faking, and try to call her bluff.', 21, '2005-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 15, 'Smell the Umbrella Stand', 'Alan starts to worry about a medical procedure that he is facing, and to get his mind off it, Charlie suggests they go to Las Vegas.', 21, '2005-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 16, 'Can You Eat Human Flesh with Wooden Teeth?', 'When Judith decides to take a vacation, the brothers have to take care of Jake during the week.  Alan finds it challenging, and even forgets to pick up Jake from soccer practice.   When Alan finds out that he has to go to the I.R.S. because they''re auditing him, he forces Charlie to take care of Jake, and Charlie doesn''t do any better then Alan.', 21, '2005-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 17, 'Woo-Hoo, a Hernia Exam!', 'After Charlie has back pain, Alan decides to take him to the Hospital. While there Charlie can''t stop hitting on the doctor who is examining him.  The only problem is that he has a history with her that he can''t remember.   Berta is feed up with Jake''s inability to use the bathroom properly, so she decides to make him clean it until he learns.', 21, '2005-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 18, 'It Was ''Mame'', Mom', 'Charlie is invited to a party hosted by a gay ad-executive named Eric, so Charlie asks Alan to pretend that he''s his life partner.  While at the party, Charlie meets Eric''s ex-wife Pamela, and tries to sleep with her without Eric finding out.', 21, '2005-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 19, 'A Low, Guttural Tongue-Flapping Noise', 'After Charlie takes Alan to an eye doctor, they end up at cafe where they bump into Charlie''s ex-girlfriend, Sherri. While there Alan shows an interest in Sherri, and decides to ask her out.   The problem is that Alan can''t get over Sherri''s relationship with Charlie.', 21, '2005-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 20, 'I Always Wanted a Shaved Monkey', 'Rose tries to help the brothers sort out their feelings, when Charlie and Alan take their personal frustrations out on each other.', 21, '2005-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 21, 'A Sympathetic Crotch to Cry On', 'Evelyn reads in the obituaries that her second husband, Harry has died. They all attend the funeral, including Jake who is excited at the opportunity of seeing a ""dead guy"". Charlie is excited by the opportunity of a newly single widow, and Alan is just happy to pay his respects to Harry.', 21, '2005-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 22, 'That Old Hose Bag Is My Mother', 'Evelyn buys Alan a new Sports car causing Charlie to claim that his brother has sold his soul to the Devil.  The next day, Evelyn extracts payment by insisting that Alan go on a blind, double date with her, her new beau and his daughter.  At the restaurant, Alan learns that his mother and boyfriend will not be able to join them because there was a mixup between his heart medication and Viagra and she didn''t want to ""waste it"".  As a result, Alan is left to deal with the daughter, who is on a weekend pass from a rehab center and still has some loose screws.  Alan eventually gets her back to the beach house only to have her drive off in his new sports car and become the object of a televised high-speed car chase.', 21, '2005-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 23, 'Squab, Squab, Squab, Squab, Squab', 'Evelyn demands Jake spend a night at her place when she finds out he spent Spring Break with Judith''s parents. Neither Alan nor Charlie are keen on the idea, but going to a bar after dropping off Jake quickly erases their concerns.', 20, '2005-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 2), 24, 'Does This Smell Funny to You?', 'Charlie unknowingly sleeps with an older man''s trophy wife while Jake has to read a paper to his class.', 20, '2005-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')), 3, 'Season 3', 'Family ties tighten and tension rises as Charlie’s wild ways clash with Alan’s neuroses, leading to hilarious misadventures in love, work, and parenting.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 3), 1, 'Weekend in Bangkok with Two Olympic Gymnasts', 'After falling off the roof, Alan needs Charlie''s help in looking after Jake, which interferes with Charlie''s social life.', 22, '2005-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 3), 2, 'Principal Gallagher''s Lesbian Lover', 'Jake gets suspended from school after drawing an offensive picture of a girl in his class that has large breasts. Meanwhile, Charlie is asked to watch over Alan''s chiropractic office after pulling an all-nighter.', 22, '2005-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 3), 3, 'Carpet Burns and a Bite Mark', 'Alan has been dating a lot, and Charlie soon finds out that it has been one woman - his ex-wife, Judith. He tries to stop Alan, and even brings Rose, Evelyn and Berta to interfere - but Alan ignores them all.', 22, '2005-10-03');
