INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 11), 20, 'Lotta Delis in Little Armenia', 'Alan finds an opportunity to make money; Walden addresses his co-dependency issues.', 21, '2014-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 11), 21, 'Dial 1-900-Mix-A-Lot', 'Alan''s girlfriend, Gretchen, insists he confess his true identity to Larry. Meanwhile, Walden goes on a road trip with Jenny and Barry to see his first car.', 21, '2014-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 11), 22, 'Oh, WALD-E, Good Times Ahead', 'Alan must face the consequences after revealing his identity to Larry.', 21, '2014-05-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')), 12, 'Season 12', 'In the final season, Walden and Alan take drastic (and hilarious) steps to redefine family, love, and what it means to finally grow up.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 1, 'The Ol'' Mexican Spinach', 'After a health scare on Halloween, Walden decides he needs to change his life.', 21, '2014-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 2, 'A Chic Bar in Ibiza', 'Alan has second thoughts about getting married after he''s asked to sign a pre-nup.', 21, '2014-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 3, 'Glamping in a Yurt', 'Alan and Walden have a meeting with an adoption social worker that hinges on them being convincing as a loving couple. Lyndsey returns after 60 days in rehab.', 21, '2014-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 4, 'Thirty-Eight, Sixty-Two, Thirty-Eight', 'A birth mother considers having Walden and Alan adopt her baby.', 21, '2014-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 5, 'Oontz. Oontz. Oontz.', 'Walden becomes a foster parent to a 6-year-old boy, but worries about himself when they don''t hit it off like he hoped.', 21, '2014-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 6, 'Alan Shot a Little Girl', 'Alan breaks Walden''s rules when he realizes that Louis thinks he''s cool, and he wants it to stay that way.', 21, '2014-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 7, 'Sex with an Animated Ed Asner', 'Alan and Walden befriend three moms at a kids’ gym, but things get complicated when Walden becomes attracted to one of them. Alan goes out for a girls’ night with a group of moms.', 21, '2014-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 8, 'Family, Bublé, Deep-Fried Turkey', 'Alan and Walden attempt to convince Louis that Santa Claus is real.', 21, '2014-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 9, 'Bouncy, Bouncy, Bouncy, Lyndsey', 'Walden discovers how challenging it is to be intimate with women when his foster son, Louis, is in the house.  Also, Herb asks Alan if he can go on a date with Lyndsey.', 21, '2015-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 10, 'Here I Come, Pants!', 'Alan takes it upon himself to help Walden keep Louis after the social worker discovers he and Walden are not really a gay couple.', 21, '2015-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 11, 'For Whom the Booty Calls', 'Walden joins a group for adoptive fathers, and finds it to be a nice escape from Alan.', 21, '2015-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 12, 'A Beer-Battered Rip-Off', 'When Alan breaks up with their social worker to get back together with Lyndsey, Walden worries it will affect Louis’ adoption.', 21, '2015-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 13, 'Boompa Loved His Hookers', 'Walden fears if he breaks up with Ms. McMartin, it will jeopardize his adoption of Louis. Also, Alan hesitates when Lyndsey asks him to move in with her.', 21, '2015-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0369179')) AND numero_temporada = 12), 14, 'Don''t Give a Monkey a Gun', 'After they sign their divorce papers, Walden offers Alan the gift of his choice, but when Alan chooses something selfish and impractical, it puts his relationship with Lyndsey on the line.', 21, '2015-02-12');
