INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 1, 'Yankee White', 'While on Air Force One, a Navy commanding officer dies. Agents from the Navy NCIS decide to take the investigation into their own hands and also force a Secret Service Agent to help. Now the NCIS team has to figure out if the Navy officer''s death was of natural causes or not.', 45, '2003-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 2, 'Hung Out to Dry', 'During a training exercise, a Marine''s parachute fails to open and he crashes into a parked car. The NCIS team head to the scene and have to determine if the Marine''s death was accidental or a murder.', 44, '2003-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 3, 'Seadog', 'When a Navy commander''s body washes up on shore along with the bodies of two drug runners, Gibbs refuses to believe that the sailor who was killed was dirty.', 43, '2003-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 4, 'The Immortals', 'The NCIS team investigate when a seaman''s body is found at the bottom of the sea in his dress whites, with a ceremonial sword. They discover that he was addicted to an MMORPG. Now, the team must figure out how involved he was in the game and how far he would go to get revenge on his arch enemy, another sailor.', 44, '2003-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 5, 'The Curse', 'A Navy Lieutenant who was reported missing nearly ten years ago has been found by a deer hunter. When the NCIS team arrive at the scene to investigate, they see that his remains have been mummified.', 43, '2003-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 6, 'High Seas', 'An NCIS agent who used to work under Gibbs asks for the team''s help investigating a case where sailors on an aircraft carrier are dying of a drug overdose, but have no history of any kind of drug abuse.', 44, '2003-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 7, 'Sub Rosa', 'A decomposed body is discovered in a tub of acid at a Naval base and Ducky and Abby learn that the victim was a submariner. However, there have been no reports of a sub crewmember missing.', 44, '2003-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 8, 'Minimum Security', 'The NCIS team head to Cuba to investigate a Navy translator''s connection to smuggling at a detention center after he suddenly dies at the wheel of his car when returning to the U.S. from Guantanamo Bay.', 44, '2003-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 9, 'Marine Down', 'After a Marine widow receives a call from her dead husband, the NCIS team take on the case and have to exhume the body to deduce whether the call was a prank or not.', 44, '2003-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 10, 'Left for Dead', 'After being buried alive, a woman comes out of the grave with amnesia and the only thing she remembers is that there is a bomb aboard a Navy ship. While trying to help Jane Doe recover her identity, the team find out that not everything is what it first seemed.', 44, '2004-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 11, 'Eye Spy', 'When a Navy commander, who was a technical advisor to a civilian contractor for a Navy weapon, is found dead on the beach, the NCIS team investigate the murder using satellite technology.', 44, '2004-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 12, 'My Other Left Foot', 'The NCIS team are called in when a severed leg bearing a Marine tattoo is found in a trash bin, leading them to a small town where a murder scheme is afoot.', 44, '2004-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 13, 'One Shot, One Kill', 'The team investigate when a Marine recruitment officer is found shot to death by a sniper with a grudge, who leaves a white feather behind.', 42, '2004-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 14, 'The Good Samaritan', 'A Navy dentist stops near a parked car to help a stranded motorist who pulls out a gun. The team investigate a murder with the help from a local sheriff, Charley, when they find out about the similar murder of the Navy civilian employee.', 44, '2004-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 15, 'Enigma', 'Gibbs risks his career when his former commanding officer is accused of stealing funds.', 44, '2004-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 16, 'Bête Noire', 'A terrorist holds Ducky, Gerald, and Kate hostage while NCIS investigate how exactly the terror organization member got a job at a Navy base.', 44, '2004-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 17, 'The Truth Is Out There', 'When the body of a sailor is found after a party in an illegal night club, the team investigate a number of possible leads - including blackmail and accidental death.', 43, '2004-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 18, 'UnSEALed', 'The team are looking for an ex-SEAL who escaped from prison in search of revenge. He is determined to find the real murderer of his wife.', 44, '2004-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 19, 'Dead Man Talking', 'An NCIS agent has been murdered while investigating a case and the team''s job is to find out what happened.', 45, '2004-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 20, 'Missing', 'A Marine goes missing after a date with a reporter. During the investigation, the team discover that three former members of his unit are dead and suspect the unit commander to be a serial killer.', 45, '2004-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 21, 'Split Decision', 'When a body of a murdered Marine is found in the forest, the investigation leads to the local militia and a weapon deal gone wrong.', 44, '2004-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 22, 'A Weak Link', 'Gibbs'' team investigate the death of a SEAL during a training exercise, and come to suspect that it wasn''t an accident, but a murder.', 43, '2004-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 1), 23, 'Reveille', 'The terrorist from Bête Noire returns with a plan to attack the President. Gibbs and his team follow the clues to reveal his identity and find Kate who is kidnapped.', 44, '2004-05-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 1, 'See No Evil', 'The wife and nine-year-old blind daughter of a Navy captain are kidnapped and the captain is a hostage in his own office, communicating with the kidnapper, who watches his every step via computer camera.', 44, '2004-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 2, 'The Good Wives Club', 'A mummified remains of a woman are found in an abandoned compound. The team discover that the woman was missing for several months, was wearing a wedding dress when she died, and might have been a victim of a serial killer.', 43, '2004-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 3, 'Vanished', 'The NCIS team are called in to investigate when a perfectly functioning Marine helicopter is found in the middle of a crop circle.', 44, '2004-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 4, 'Lt. Jane Doe', 'A body of a woman in a Navy uniform is found by two sailors. Ducky links the murder to an unsolved case from ten years ago, and the team searches for a serial killer who left a note promising to return.', 44, '2004-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 5, 'The Bone Yard', 'NCIS discover that an area in a Marine''s bombing range is where mafia has been dumping bodies for a while. One of the victims is an undercover FBI agent. The team set out to find a mole.', 44, '2004-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 6, 'Terminal Leave', 'The team must protect an Iraq veteran due to the threats made by terrorists. While trying to convince FBI Agent Lina Reyes to help them, the team are convinced that they have discovered the bomber.', 44, '2004-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 7, 'Call of Silence', 'Ernie Yost, an elder Marine veteran confesses to murdering his best friend almost 60 years ago in a war battle. The NCIS''s job is to solve the secrets and save Ernie from prison.', 44, '2004-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 8, 'Heart Break', 'A strange case for Gibbs and his team opens when a Navy Commander dies after successful surgery. While researching the commander''s past, the team find out that he collected a lot of enemies lately.', 43, '2004-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 9, 'Forced Entry', 'Laura Rowen, a Marine''s wife, shoots an intruder in self defense when he is about to rape her. The team take on the case and find out that the wife is leading a double life while her husband is serving overseas.', 44, '2004-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 10, 'Chained', 'Tony disappears while doing an undercover operation as an escaped prisoner who is forced to stick to a convict that owns a key to an expensive ancient Iraqi sculpture. The GPS locator that Abby planted on Tony stops working and the team are forced to find Tony before he gets murdered by the thief.', 44, '2004-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 11, 'Black Water', 'A dead body of a two-year-missing Navy officer appears on the bottom of a lake. The team investigate the case with a help of a private detective.', 43, '2005-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 12, 'Doppelgänger', 'The team take on another strange case when a telemarketer reports a possible murder of a Petty Officer who appeared to be dying over the phone.', 46, '2005-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 13, 'The Meat Puzzle', 'A "meat puzzle" starts when Ducky identifies the pieces of three bodies that were stuffed inside a barrel a few months ago. They turn out to be bodies of a judge, prosecutor, and jury foreman that worked with Ducky on a rape case ten years ago.', 43, '2005-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 14, 'Witness', 'Erin Kendall claims to have seen a murder of a sailor in an apartment across from hers. Gibbs assigns the case to McGee who believes that he can resolve it himself. However, due to the lack of physical evidence, McGee turns to the team to help him.', 44, '2005-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 15, 'Caught on Tape', 'The team take on a case of a dead Marine who recorded his death while falling off a cliff. The prime suspects are his wife and his best friend with whom he had a picnic in the camp. Gibbs finds out they had an affair behind the dead man''s back.', 43, '2005-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 16, 'Pop Life', 'NCIS start an investigation after Petty Officer Manda King is found dead in a bartender''s bed. The suspect is the owner of a competing club where Manda''s sister sings.', 44, '2005-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 17, 'An Eye for an Eye', 'When a sailor officer receives a pair of blue eyeballs, the NCIS team start investigating the case. Gibbs traces an ex-Navy agent that does illegal work.', 44, '2005-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 18, 'Bikini Wax', 'A Petty Officer that just returned to her job is found dead in the backstage of a bikini contest. The team find out that she possibly had a stalker behind her back.', 44, '2005-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 19, 'Conspiracy Theory', 'The team investigate a suicide case, believing that the main reason of her death is a nervous breakdown, but Ducky believes that she was actually murdered. FBI Special Agent Fornell helps them in the investigation. The team discover that the dead woman was involved in a love triangle and that this may have contributed to her death.', 44, '2005-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 20, 'Red Cell', 'After a Marine is murdered in a school campus the team discover a possible suspect for his murder, but they soon find the suspect murdered. Tim and Abby discover a trace to a "Red Cell" in the e-mails and the team believe that maybe the Marine was involved in a serious game.', 44, '2005-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 21, 'Hometown Hero', 'A young Marine is killed in Iraq, but he was investigated by police for a murder on a young girl in his hometown. While going through his personal belongings, they find the body of that girl. The local police believe that the corpsman murdered the girl, but Gibbs believes that he is innocent and he will try to prove it with a help of Faith Coleman.', 44, '2005-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 22, 'SWAK', 'When Tony opens a mysterious letter thinking it''s for him, a small puff of white powder comes out and releases a possible deadly virus. Soon Kate and Tony are isolated in a bio-hazard isolation room for precaution. McGee and Gibbs work to discover who sent the envelope and how to cure their friends before it''s too late for them.', 44, '2005-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 2), 23, 'Twilight', 'A group of serial terrorists seek revenge and send Ari on an assignment to kill Gibbs. The NCIS team go on a hunt after him, but when they discover that Ari has a bigger plan, it is already too late.', 43, '2005-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 1, 'Kill Ari (1)', 'After the terrorist''s attack, the NCIS team are shocked and are trying to cope with Kate''s sudden death, each in their own way. Now, their mission is to collect all the possible info on Ari and find a way to stop him before he does any more damage.', 44, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 2, 'Kill Ari (2)', 'Still stressed over Kate''s death, Gibbs is even more hurt when Ari kidnaps Ducky and decides to play with his mind. Gibbs sends Tony to follow Ziva, and after Jenny and Gibbs are almost shot to death, he is even more determined to finish once and for all with Ari, and Ziva''s strange connection to Ari will be just the help that he needs.', 44, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 3, 'Mind Games', 'Gibbs is ordered to talk to a convict that is about to be executed, in order to discover information about the place where he hid his victims, but when the plan doesn''t work, the team must solve the case in their own way.', 44, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 4, 'Silver War', 'When a corpse of a man is found inside a tomb that comes from the Civil War, the team discover that the victim, a Sergeant, was buried alive. During the investigation, Abby tracks down the last phone call of the victim.', 44, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 5, 'Switch', 'When an officer is shot to death on the freeway, the NCIS team take on the investigation. The first lead, a fact that the victim was leading a double life, take them to a possible solution of the crime, but the tables are turned when the victim''s dying message is discovered and it leads them to a totally different clue.', 44, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 6, 'The Voyeur''s Web', 'The NCIS team take up a strange case - a Marine''s wife was murdered live on the Internet. The investigation reveals that two housewives were running a live Internet sex site and now they are both missing. While looking for them, the team will try to track down the webmaster and solve the alleged murder case.', 44, '2005-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 7, 'Honor Code', 'When a six-year-old boy informs the NCIS team that his father was kidnapped, the team discover that the missing father is actually a Lt. Commander working on a secret project named Honor, and that he is the only one who has the code that can open the project.', 44, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 8, 'Under Covers', 'When bodies of two hired assassins are delivered to the NCIS team, Ziva and Tony go undercover assuming the victim''s identities in order to find the person who hired the assassins for their mission. Gibbs discovers that his team are not the only ones working on the case.', 43, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 9, 'Frame-Up', 'Tony is accused of murdering a woman whose body was found at Quantico and the team must prove his innocence.', 44, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 10, 'Probie', 'While on duty, McGee kills a man who is later discovered to be an undercover police officer. When Jen decides to approve the investigation on McGee, the NCIS team are forced to prove that McGee is not guilty, pushing Gibbs'' relationship with Jen to the limit.', 44, '2005-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 11, 'Model Behavior', 'A supermodel dies while filming a reality show on a Marine base, and the NCIS team must discover who is the model''s murderer. They discover a love triangle between the model and three other men, all suspects.', 44, '2005-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 12, 'Boxed In', 'While looking for smuggled weapons at a shipyard, Tony and Ziva disappear and it''s up to NCIS to find them. Abby tries to find them by tracking down their GPS chips, but they seem to be out of reach.', 44, '2006-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 13, 'Deception', 'When a Lt. Commander in charge of a shipment of fuel rods for nuclear power stations disappears, the NCIS team are called in. The team must solve the case in time, before the person who kidnapped the Commander finds out the secret location of the fuel rods or harms the Commander.', 43, '2006-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 14, 'Light Sleeper', 'The NCIS team investigate the murder of two Marine wives, and must find the murderers before they attack their next target, another woman.', 44, '2006-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 15, 'Head Case', 'While discovering an illegal automotive chop shop, the NCIS team stumble upon a severed head of a Marine, hidden in one of the cars from the shop. When they find possible suspects, the team will have to find the rest of the body and find the murderer.', 44, '2006-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 16, 'Family Secret', 'When an ambulance explodes while carrying the remains of a Marine''s body that was killed in a car crash, the NCIS team are called in to investigate what actually happened. The investigation leads them to some sudden discoveries - the DNA of the victim found in the ambulance doesn''t match the Marine''s DNA, the ambulance was set up to explode, and the family of the dead Marine is hiding a very important secret.', 44, '2006-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 17, 'Ravenous', 'When Marine dog tags are found in a national forest by a group of teens, the NCIS team are called in to investigate. While searching for the campsite of the Marine, the team find out that there was another person, possibly a woman, with him. The investigation takes them to an even more higher discovery - there could be a serial killer killing women in the national forest.', 44, '2006-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 18, 'Bait', 'The NCIS team must stop a teenage student from detonating a bomb attached to his body, while he''s taking the other students hostage at a Quantico base high school. Gibbs tries to stop him when he enters the classroom, only to realize that there may be someone else controlling the teenage student from the outside.', 44, '2006-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 19, 'Iced', 'Gibbs and the team are called in when a couple of kids stumble upon the body of a missing Marine in a frozen lake. As the NCIS team search the frozen lake bed for clues, they come across three more bullet-ridden bodies.', 44, '2006-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 20, 'Untouchable', 'When a Pentagon cryptographer is found dead, the NCIS team have to discover whether she was or wasn''t a Pentagon mole, and if she committed suicide. As the investigation continues, the team discover that the cryptographer wasn''t alone when she died.', 44, '2006-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 21, 'Bloodbath', 'While working on a regular murder case with the rest of the NCIS team, Abby is almost killed by evidence from the case. Soon it becomes clear that the murder was staged, and that someone wants Abby dead. The team discover some enemies from Abby''s past, and they must find out who is the person, before they kill Abby.', 44, '2006-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 22, 'Jeopardy', 'The NCIS team must protect Ziva when a suspect dies in custody, and her tactic might be the reason why the person died. Things become much more dangerous when the suspect''s brother kidnapps Jenny, and demands the release of his brother in exchange for Jenny, but he has no idea that his brother is dead.', 44, '2006-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 23, 'Hiatus (1)', 'While working on an assignment, Gibbs is seriously injured in an explosion, and taken to a hospital, where he recalls his painful past, which he has always hidden from others. The rest of the team must proceed with the investigation and put their feelings towards Gibbs'' injury aside.', 44, '2006-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 3), 24, 'Hiatus (2)', 'The NCIS team must work on an assignment against a terrorist group without Gibbs, who is still recovering from the explosion. Gibbs has to fight with memory loss, while he''s visited by his mentor and his former boss. Gibbs'' help is needed, especially when the team discover that he is the only person who has information about the terrorists'' plans.', 44, '2006-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 1, 'Shalom', 'When Ziva is framed for a political assassination, she must avoid the FBI and deal with the consequences without Gibbs'' help, who is now enjoying his retirement.', 44, '2006-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 2, 'Escaped', 'Gibbs is forced to come back out of his retirement to help Fornell, who is being threatened by a convict that escaped from prison. Gibbs and the NCIS team re-open the convict''s old robbery case.', 43, '2006-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 3, 'Singled Out', 'An abandoned car, registered to a missing Navy Lieutenant, is found with blood stains inside. The NCIS team learn that the missing Lieutenant was profiling men, trying to find a perfect man for herself.', 44, '2006-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 4, 'Faking It', 'After police pull over a driver and arrest him for a concealed weapon, a car crashes into their patrol car with a dead man behind the wheel. The arrested man turns out to be Russian and Homeland Security claim he was working for them.', 44, '2006-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 5, 'Dead and Unburied', 'When a missing Lance Corporal is found dead in a vacant house, the NCIS team discover that he was buried in the backyard and then exhumed. They learn about his identity and that he was to be deployed to Iraq, but he never showed up for duty.', 44, '2006-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 6, 'Witch Hunt', 'It''s Halloween and the NCIS team are busy investigating a ransom case. A Marine''s daughter has been kidnapped after the Marine was attacked in his home. The investigation leads them to a fact that the couple has been separated.', 44, '2006-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 7, 'Sandblast', 'When a Marine Colonel dies in an explosion at a military golf course, the NCIS team must investigate a suspected terrorist attack with the help from the Army Criminal Investigative Division.', 42, '2006-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 8, 'Once a Hero', 'When an honored Marine veteran is found dead in a hotel, the NCIS team must find out what happened to him. Soon they realize that the Marine didn''t commit suicide and that he was a homeless man.', 44, '2006-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 9, 'Twisted Sister', 'McGee breaks the rules, risking his NCIS job, to help his sister Sarah, who shows up disoriented and bloodied. While he works on figuring out what happened to his sister, the NCIS team are investigating a case of a Navy sailor, who is somehow connected to Sarah.', 44, '2006-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 10, 'Smoked', 'When a burnt and mummified body of a missing and wanted person is found in a furnace on a Marine base, NCIS must work with the FBI. The burnt man turns out to be a serial killer.', 44, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 11, 'Driven', 'When a robotic vehicle named "Otto," a part of a high-level project of the Department of Defense, causes a death of a Navy Lieutenant, and later almost kills Abby, the NCIS team must find out who sabotaged the vehicle and murdered the Lieutenant.', 43, '2006-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 12, 'Suspicion', 'When a high-level Marine intelligence officer is found murdered in a small motel room, the NCIS team must find the person who murdered her. After discovering that she was already dead for three days, and that the town authorities already "investigated" the crime, Gibbs is determined to solve the case.', 44, '2007-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 13, 'Sharif Returns', 'When the NCIS team learn that a missing ten kilograms of highly toxic chemical weapons are now in the hands of Mamoun Sharif, a wanted terrorist, they will have to find a way to find the man and stop him before it''s too late.', 44, '2007-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 14, 'Blowback', 'After catching an international arms dealer, the NCIS team learn that the Navy''s highly classified weapons system will be sold to arms dealer La Grenouille. To stop the transaction, the team send Ducky undercover.', 44, '2007-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 15, 'Friends and Lovers', 'When a dead body of a sailor is found in an abandoned part of the town, all the evidence seem to point that the person died from a drug overdose, but when the team uncover more evidence, it turns out to be a murder.', 44, '2007-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 16, 'Dead Man Walking', 'When a Navy Lieutenant becomes the victim of radiation poisoning, the NCIS team must find the person who''s behind the crime. The Lieutenant, who is working for the International Atomic Energy Agency, claims that only his two colleagues knew about his assignment, and whoever it was, the person tried to stop the Lieutenant''s next investigation.', 44, '2007-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 17, 'Skeletons', 'When an explosion at a military cemetery mausoleum reveals a crypt full of a mixture of body parts, the NCIS team must inform the families of the victims, hoping to find a connection and narrow down the suspects to find out who is behind the hideous crime.', 44, '2007-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 18, 'Iceman', 'When a supposedly frozen to death Marine turns out alive on Ducky''s autopsy table, the NCIS team have to find out about the victim''s movements in the last few days to uncover what happened to him and who left him for dead.', 44, '2007-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 19, 'Grace Period', 'When a weekend call to the NCIS tip line from an unknown source about possible terrorist activity results in the death of two agents sent into a trap, the NCIS team will have to find out who were the people responsible with the help from Agent Paula Cassidy, who holds herself responsible for the tragedy.', 44, '2007-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 20, 'Cover Story', 'McGee is under high pressure during the murder investigation of a Petty Officer based on the character for his latest book, with very little information to go on.', 44, '2007-04-10');
