INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 4), 22, 'In the Dark', 'When a blind photographer shoots the body of a Petty Officer on film, the NCIS team use his special insight to investigate the crime.', 44, '2007-05-01');
