INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 2, 'Prodigal Son (2)', 'Parker’s pursuit of vengeance for his father’s murder could have deadly consequences, while his sister, Navy vice admiral Harriet Parker, faces an impossible choice.', 43, '2025-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 3, 'The Sound and the Fury', 'When a petty officer’s death is connected to a blackmail investigation, the team is forced to work with Special Agent Sawyer on the case, which takes a terrifying turn for Torres. Meanwhile, Knight is offered an opportunity to train with NCIS Elite.', 43, '2025-10-28');
