INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 6, 'Page-Turner', 'When McGee is kidnapped while promoting his latest book in the Deep Six crime series, the team investigates his self-professed “#1 fan” – and a potential link to a murder case involving stolen classified documents.', 43, '2025-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 7, 'God Only Knows', 'A kidnapped teen leads the team to a Navy SEAL who survived captivity by the Taliban but may have committed murder after returning home. Also, Jimmy finally shares his findings about the mysterious death of Parker’s mother with his boss.', 42, '2025-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 8, 'Stolen Moments', 'When a man is shot by the Secret Service outside the vice president’s official residence, NCIS is aided in the case by a new member of the team: an AI chatbot being beta-tested by the Department of Justice.', 43, '2025-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 9, 'Heaven and Nature', 'McGee and Torres try to recover a stolen truck filled with toys for the Navy’s annual Christmas drive while the truth about Parker’s mother is finally revealed. Also, Knight is given her first NCIS: Elite mission, which involves tracking down a former member of the team.', 43, '2025-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 10, 'Her', 'On her first NCIS: Elite mission, Knight is given orders to hunt down and arrest Eleanor Bishop after the former member of the NCIS team is designated a wanted cyber-terrorist. In need of someone to trust, Bishop turns to Torres, and the two come face to face for the first time since she abruptly left nearly five years ago.', 43, '2026-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 11, 'Army of One', 'When a desperate man barricades himself inside an ammo warehouse, Knight is the only negotiator he’ll talk to, claiming she once saved him before. As explosives tick and trust frays, Knight clashes with the CID officer running the standoff, each convinced theirs is the only way out.', 43, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 12, 'In Too Deep', 'A murdered drone pilot leads the team to a missing woman from McGee’s past and a relationship he thought was long behind him. But as the case deepens, McGee realizes her reappearance could unravel more than an investigation, it could change the course of his life.', 43, '2026-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 13, 'All Good Things', 'When the son of a Marine that Gibbs once helped comes to NCIS in desperation, the fractured team reunites off the books; chasing justice without a badge may cost them more than their careers.', 43, '2026-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 14, 'Fleeting', 'Navy Week turns electric when a stolen squad car flips and reveals a sailor stabbed in the trunk; as D.C. spirals into chaos, the team chases a killer while carrying the weight of recent events.', 43, '2026-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 15, 'Knick-Knack', 'A murder aboard a museum ship becomes a cryptic treasure hunt when a dying Navy captain leaves a final clue; to solve it, the team must decode what was worth killing -- and dying -- for.', 43, '2026-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0364845')) AND numero_temporada = 23), 16, 'S.O.S.', 'S.O.S.
