INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 1, 'Pilot', 'Joey arrives in L.A. after his new agent offers him his choice of parts on two TV shows, and befriends his neighbor, Alex. His nephew, Michael, wants to move in with him at his new apartment, but Joey fears that this will upset his sister, Gina.', 28, '2004-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 2, 'Joey and the Student', 'Gina is having trouble letting Michael live his own life, by constantly hanging out at Joey''s place. Meanwhile, Joey is irritated by the notes his super leaves him. Also, the three of them go out to a bar where Joey and Gina try to teach Michael how to pick up women.', 24, '2004-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 3, 'Joey and the Party', 'Having trouble meeting new people in L.A., Joey throws a party to get to know some of his neighbors. Unfortunately, the one he''d like to get to know, Jake, seems to be more interested in Gina. Also, Alex pretends to be Michael''s girlfriend so that he can one-up his friend.', 22, '2004-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 4, 'Joey and the Book Club', 'Joey joins Michael''s book club to meet pretty women. Unfortunately for Michael, the girl he is crazy about, seems to have more interest in Joey than him. Meanwhile, looking to get her hairdressing work noticed, Gina bargains with Alex.', 22, '2004-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 5, 'Joey and the Perfect Storm', 'There''s a vacant apartment in the complex, and Joey and Michael try to hide it from Gina, fearing that she''ll want to move in to be closer to them. Also, Joey is understudying in three plays at once and unfortunately for him, he gets called upon to perform on stage in all three of them on the same evening.', 22, '2004-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 6, 'Joey and the Nemesis', 'Michael is sick and Gina is delighted cause now she feels needed again and takes care of him. However, this bothers Joey, because now his sister is around all the time, so Gina offers him to crash at her place until Michael gets better. While staying at Gina''s, Joey meets her secret boyfriend and confronts him. Also, an actor named Brian Michael David Scott repeatedly tricks Joey into missing auditions.', 22, '2004-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 7, 'Joey and the Husband', 'After Gina keeps complaining about her current workplace, Joey decides to loan her some money, so that she can open her own salon, but she has second thoughts. Also, Alex''s husband Eric returns to town and things get weird between him and Joey.', 22, '2004-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 8, 'Joey and the Dream Girl (1)', 'Gina''s high school friend Donna comes to town, recently separated from her husband. Joey, who has had a huge crush on Donna for years, is happier than ever when they start going out. However, Donna confides in Gina that her husband wants to reconcile, and begs her not to tell Joey. Meanwhile, Michael is startled to discover that he was a great baseball player when he was younger.', 22, '2004-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 9, 'Joey and the Dream Girl (2)', 'Gina reveals to Joey that Donna is considering getting back together with her husband Ron, however, Joey decides that he won''t give up without a fight. He plans a romantic week together with Donna in order to win her over. Unfortunately for him, just as he''s about to leave to pick up Donna for their trip, Ron shows up at his place and confronts him. Thankfully, Gina and Michael manage to keep Ron busy which lets Joey slip away. Meanwhile, Alex discovers that she''s hot and that hot girls get free stuff.', 22, '2004-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 10, 'Joey and the Big Audition', 'A discouraged Joey is just looking for an audition for a good show.  At Alex''s Northwestern alumni party, he''s mistaken for a fellow alumni, and introduced to the Northwestern Mafia.  They help him get an audition for a show called Deep Powder, described as "Baywatch on skis."  Joey''s a little depressed that he''s auditioning for the father of 2 teenage characters.', 22, '2004-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 11, 'Joey and the Road Trip', 'Bobbie gets Joey a job as a celebrity judge for the Miss Southwestern U.S.A. pageant, taking place in Las Vegas.  With Gina, Michael and Alex in tow, he heads for Vegas.  While there, Alex reveals her Celine Dion obsession, Michael teaches Gina how to count cards, and Joey accidentally sleeps with a pageant contestant.', 22, '2004-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 12, 'Joey and the Plot Twist', 'Joey meets Deep Powder''s executive producer, Lauren Beck.  Joey worries that he may be fired after giving away a plot twist at a press conference.  Alex, Gina and Michael decorate the apartment for Joey for Christmas.', 22, '2004-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 13, 'Joey and the Taste Test', 'Joey''s relationship with costar Katie has consequences that could get him fired from the show, unless he manages to talk her out of her dressing room.  Joey and Lauren acknowledge their feelings for one another.  After Gina teaches Alex how to make lasagna, Joey is forced to judge a taste test.', 22, '2005-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 14, 'Joey and the Premiere', 'Unable to decide who to take to the premiere of Deep Powder, Joey struggles to find tickets for Gina, Michael and Alex.  Michael meets a girl and Brent Spiner and must choose who to leave with.  Gina''s date is Lauren''s ex-boyfriend.  Alex''s date is a lesbian.  Joey and Lauren kiss.', 22, '2005-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 15, 'Joey and the Assistant', 'Following Bobbie''s advice to get an assistant, Joey winds up with Glen, who couldn''t be better.  But when Glen starts dating Gina, his worlds colliding means problems for Joey.  Eventually, Gina and Joey create some guidelines so that Glen can continue working for both of them.  Meanwhile, Alex mediates Michael''s dispute over a patent with his friend Seth.', 22, '2005-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 16, 'Joey and the Tonight Show', 'Bobbie has booked Joey on The Tonight Show with Jay Leno.  En route to the show, he''s stuck in a major traffic jam.  After giving the finger to a guy who cut him off, Michael is terrified after they are stuck next to the guy''s car.  Gina meets two guys, one in an El Camino and one in a Mercedes.  Alex saves the day when she shows up with a motorcycle that gets Joey onstage and hugging Jay Leno just in time.', 22, '2005-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 17, 'Joey and the Valentine''s Date', 'Joey accidentally makes a date with a reporter from "People" for Valentine''s Day.  He has the gang "accidentally" bump into him and his date at the restaurant to ruin the mood, but his plans backfire when she thinks he''s taking their relationship to the next level.  A drunken Alex shares some sexual secrets with Gina.  After Joey sends Michael over to hit on a table of girls, Michael actually becomes "one of the girls."', 22, '2005-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 18, 'Joey and the Wrong Name', 'Joey is nominated for a Daytime Soap Award for his death scene on Days of Our Lives.  (For the record, he was stabbed.)  He is also presenting the award for Best Supporting Actress, and a problem arises when his inability to correctly pronounce one of the nominees'' names leads to his saying the wrong name entirely.  Meanwhile, Gina struggles with the fact that she is dressed unlike herself for the event.', 22, '2005-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 19, 'Joey and the Fancy Sister', 'Joey and Gina''s sister Mary Theresa is coming for a visit, and Gina can''t stand her because she thinks the world revolves around her.  When Mary Theresa discovers that her engagement ring is fake, she decides to call off the wedding and stay in California, leaving Joey and Gina to try to find a way to get her to return to New York.  Meanwhile, Michael is oblivious of a girl''s interest in him.', 22, '2005-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 20, 'Joey and the Neighbor', 'When he investigates the hot women coming out of the apartment across the courtyard, Joey discovers beautiful new neighbor Sara, a photographer.  She is surprisingly straightforward and asks Joey out.  After his date with Sara goes well, Joey forgets to cancel his backup and she shows up at the complex.  Sara lets Joey know that she''ll be okay with him dating other women, but that she''ll be seeing other men as well.  Meanwhile, Eric is home for the first time in two months, and he and Alex are not getting along.  They have a long talk and decide to separate.', 22, '2005-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 21, 'Joey and the Spying', 'As Eric moves out of their apartment and into one across the courtyard, Alex plants herself up in Joey''s room with a pair of binoculars as Eric invites another woman over.  After Alex goes to bed, Joey sees Eric kissing the other woman.  Meanwhile, Joey''s got problems of his own: even though he and Sara are allowed to see other people, he''s not because he''s too crazy about Sara.  Trying to make her jealous, Joey discovers that she likes him as much as he likes her, and they decide not to see other people.', 22, '2005-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 22, 'Joey and the Temptation', 'Just as Joey and Sara become exclusive, Joey has to do a love scene with Carmen Electra for Deep Powder.  Meanwhile, Alex struggles with the knowledge that Eric kissed another woman.', 22, '2005-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 23, 'Joey and the Breakup', 'Joey asks Bobbie to help Sara find work.  Sara gets a job working for Newsweek in Washington DC.  Trying to get her to stay, Joey tells Sara he loves her and asks her to move in.  Meanwhile, Michael''s new girlfriend, a 45-year-old woman, cheats on him with a 60-something professor.  Alex is struggling to keep herself together.', 22, '2005-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 1), 24, 'Joey and the Moving In', 'After asking Sara to move in with him, Joey freaks out.  Sara freaks out too, and leaves without saying goodbye.  Joey is heartbroken.  On her first date in a long time, Alex accidentally offers sex to the guy, and Joey gets rid of him.  While doing shots in Joey''s bedroom and commiserating about the sad state of their love lives, Alex and Joey kiss! Meanwhile, Bobbie sets herself up with Michael at a Star Wars preview.  When Gina confronts Bobbie about being attracted to Michael, Bobbie offers her a job.', 22, '2005-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 1, 'Joey and the Big Break (1)', 'Joey is on the set of "Deep Powder" but the fate of his character is still unknown. One extra, named Zach, tries to cheer him up in the hope Joey will help him (Zach) get a line to say. Zach will give Joey some tips about how to live as an actor in Hollywood. Jenna, a young actress-wannabe, moves in the building. She wants to meet Joey, the big star, but she first meets Michael who pretends to be Joey in order to land a date with her. Joey has an audition.', 22, '2005-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 2, 'Joey and the Big Break (2)', 'Joey bursts back in an audition room asking producers for one more chance (he entered a different audition room than the one he was in before!). He is determined to have a second chance and doesn''t let the producers talk so they explain that he is in the wrong room. Not knowing what to do, producers start an audition with Joey. This leads to a funny audition with Joey saying lines for an action movie, when the producers read lines said by kids.(second part to a one-hour season premiere)', 22, '2005-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 3, 'Joey and the Spanking', 'Joey faces an unruly child actor on his new movie. When push comes to shove, Joey takes matters into his own hands with interesting results. Meanwhile, Gina helps Alex get over her lagging love life.', 22, '2005-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 4, 'Joey and the Stuntman', 'Joey is preparing to shoot a big fight scene on the set. The director offers to use a stuntman instead but Joey wants to do his own stunts. Eventually, Chuck, Joey''s stuntman comes in. Abby, the script reviser, has a chat with Joey because he doesn''t follow script at all. Michael visits the set and he and Abby hit it off. Zach works Craft and Services on the set. Meanwhile, Alex is confused about her true feelings for Joey.', 22, '2005-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 5, 'Joey and the House', 'Joey decides to buy a house now that he is bringing big bucks from the movie but can he convince the owner of the house that he should get it? Gina isn''t very supportive of the idea. Alex helps Bobbie with a harassment case.', 22, '2005-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 6, 'Joey and the ESL', 'Joey decides to enroll in an English as a second language class just to attract the attention of a beautiful woman. Elsewhere, Gina decides to help Bobbie try and find a new client.', 22, '2005-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 7, 'Joey and the Poker', 'Alex teaches Texas hold ''em to Joe. The problem is that she makes up rules so he wins all the time. Thinking that he can play the game he accepts an invitation to play celebrity poker. Michael and Abby''s relationship reaches new heights.', 22, '2005-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 8, 'Joey and the Sex Tape', 'An old girlfriend of Joey''s threatens to release an embarrassing tape. To prevent this from happening he must apologize to her on "The Ellen DeGeneres Show." Bobbie celebrates her 40th birthday.', 22, '2005-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 9, 'Joey and the Musical', 'Gloria, Candance''s grandmother, is starring in a musical at the Senior Citizen Home she''s in. When the director of the musical quits, Joey offers to direct it. Zach helps Joey out in this venture. Bobbie''s mother, who''s living in that citizen home, wants a part in the musical.', 22, '2005-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 10, 'Joey and the Bachelor Thanksgiving', 'Gina is planning a family Thanksgiving. Joey and Zach discover some ancient Native American artifacts on Joey''s property and mistakenly give them away.', 22, '2005-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 11, 'Joey and the High School Friend', 'Joey''s best friend from high school is visiting. Gina has a big surprise for Michael.', 22, '2005-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 12, 'Joey and the Tijuana Trip', 'After Michael and Abby break up, Joey takes him to Tijuana to help him get over it. Alex and Gina want to have some fun and go to a night club.', 22, '2005-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 13, 'Joey and the Christmas Party', 'Joey is having a holiday party at his old apartment. Bobbie is there with her boyfriend.', 22, '2005-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 14, 'Joey and the Snowball Fight', 'Joey is starting to act weird around Alex, because she is still going out with Dean. His action figure also arrives, it has a few flaws though. Gina thinks that she''s pregnant.', 22, '2006-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 15, 'Joey and the Dad', 'Joe''s dad comes to town for Joey''s movie premiere. His sly remarks of disrespect for Joey''s line of work are lost on his son. At least until Alex points them out to him. Elsewhere Joey runs into Carmen Electra while admiring his movies billboard. The two hit it off, until Joey finds out that the billboard for her new perfume (right next to his) is getting a lot more attention than his own.', 22, '2006-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 16, 'Joey and the Party for Alex', 'Joey''s feelings for Alex are driving him crazy. Dean throws Alex a birthday party and is going to propose to her. Gina and Jimmy are getting tattoos to show their love for each other.', 22, '2006-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 17, 'Joey and the Big Move', 'While Joey is moving out to his new house, he finds out that his house is on fire and the whole house burns out. Meanwhile Jimmy finally learns that Michael is his son and he tries to start a relationship with him, father to son.', 22, '2006-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 18, 'Joey and the Beard', 'Bobbie sets up a date for Joey with Edie, a famous actress. What he doesn''t know in the beginning is that she only needs him as a "beard".', 22, '2006-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 19, 'Joey and the Critic', 'Joey discovers a Critic on the internet and goes to visit her, only to discover that it is an 11 year old.', 22, '2006-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 20, 'Joey and the Actor''s Studio', 'Joey wants to go out with Alex but she''s not sure if she wants to go out with him.', 22, '2006-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 21, 'Joey and the Holding Hands', 'Joey wants to take his relationship with Alex to the next level, but Alex only wants sex. Gina finds out that Jimmy is married to a woman that is in prison, and Michael meets a man on internet and Michael thinks that he is a woman.', 22, '2006-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0375355')) AND numero_temporada = 2), 22, 'Joey and the Wedding', 'Jimmy and Gina get married.', 22, '2006-07-28');
