INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')), 1, 'Season 1', 'The Atlantis expedition team, led by Dr. Elizabeth Weir, arrives in the Pegasus Galaxy and discovers the lost city of Atlantis. They encounter a powerful new enemy, the Wraith, and face various challenges to protect their new home while exploring the galaxy and seeking new allies.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 1, 'Rising (1)', 'A new Stargate team embarks on a dangerous mission to a distant galaxy, where they discover a mythical lost city -- and a deadly new enemy.', 45, '2004-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 2, 'Rising (2)', 'Sheppard tries to convince Weir to mount a rescue mission to free Colonel Sumner, Teyla, and the others captured by the Wraith.', 41, '2004-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 3, 'Hide and Seek', 'The Atlantis base is threatened when the team discovers that an alien entity is in the city. McKay''s experiment with alien technology goes awry.', 44, '2004-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 4, 'Thirty Eight Minutes', 'The team finds themselves in mortal danger when their Puddle Jumper ship becomes lodged in the Stargate.', 44, '2004-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 5, 'Suspicion', 'After a series of run-ins with the Wraith, the team begins to suspect their Athosian allies of having a spy in their midst.', 48, '2004-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 6, 'Childhood''s End', 'Sheppard and the team visit a world where no one is over 24 years old -- because of a ritual suicide practice they believe keeps the Wraith at bay.', 44, '2004-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 7, 'Poisoning the Well', 'The team finds a world whose people are on the brink of a discovery that may make them immune to the Wraith feeding.', 42, '2004-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 8, 'Underground', 'Efforts to open trade relations with a species called the Genii turn sour when the team discovers their new "allies" have ulterior motives.', 44, '2004-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 9, 'Home', 'McKay''s efforts to harness the energy of an alien planet''s atmosphere allows for a return trip to Earth -- but the team may not be able to return to Atlantis.', 42, '2004-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 10, 'The Storm (1)', 'When a massive storm threatens the city, Atlantis is evacuated, only to be taken over by the team''s newest enemy.', 42, '2004-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 1), 11, 'The Eye (2)', 'Major Sheppard plays a dangerous game of cat and mouse with soldiers who have seized control of Atlantis and taken Weir and McKay hostage.', 42, '2004-11-08');
