INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 3), 17, 'Sunday', 'The team tries to relax during a mandatory day off, until an explosion leaves three people dead -- and reveals that one scientist is a walking time bomb.', 42, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 3), 18, 'Submersion', 'The team discovers an Ancient drilling station deep beneath the surface of the ocean, only to find that a Wraith queen is still alive there.', 42, '2007-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 3), 19, 'Vengeance', 'The Atlantis team investigates the disappearance of one of their allies, only to find an old enemy engineering a race of powerful monsters.', 44, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 3), 20, 'First Strike (1)', 'An unstoppable energy weapon leaves Atlantis under siege after Earth launches a preemptive attack against a very powerful enemy''s homeworld.', 42, '2007-02-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')), 4, 'Season 4', 'With changes in leadership and new allies, the team continues to battle the Wraith and confront new existential threats. Personal dynamics shift as members struggle with loss and make significant choices that shape the fate of Atlantis and its mission in the Pegasus Galaxy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 1, 'Adrift (2)', 'Floating in deep space with the city''s protective shield failing, the team must do all they can to keep Atlantis alive. A radical injury threatens Dr. Weir''s life.', 44, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 2, 'Lifeline (3)', 'Colonel Sheppard and his team embark on a risky mission to steal a Z.P.M. power module from the Replicators -- but must rely on a compromised Dr. Weir to succeed.', 43, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 3, 'Reunion', 'When a group of Ronon''s people enlist the team''s help in raiding a Wraith weapons facility, Ronon reconsiders whether his future lies in Atlantis or with his friends.', 44, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 4, 'Doppelganger', 'During an off-world mission Colonel Sheppard unknowingly becomes host to an alien entity, which infects others in Atlantis and afflicts them with terrifying nightmares.', 43, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 5, 'Travelers', 'Colonel Sheppard is captured by the inhabitants of a generational ship and their beautiful leader, who wish to use his ability to use Ancient technology for their own ends.', 43, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 6, 'Tabula Rasa', 'When a virus causes amnesia in everyone except Teyla and Ronon, the Atlantis team must work together to find a cure before their memories fade entirely.', 44, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 7, 'Missing', 'During a visit to New Athos, Teyla and Dr. Keller find themselves on the run from a primitive tribe of warriors.', 44, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 8, 'The Seer', 'The team meets a man with extraordinary prophetic abilities, who gives them a dark prediction about Atlantis''s future. The Wraith seek a new alliance with Atlantis in their war with the Replicators.', 44, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 9, 'Miller''s Crossing', 'Rodney McKay goes in search of his sister on Earth after she is kidnapped by the head of a powerful corporation.', 44, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 10, 'This Mortal Coil (1)', 'A mysterious drone crashes into Atlantis, indicating that the Replicators may have found the city. But when Elizabeth Weir appears, the team realizes that the probe is just a part of a bigger mystery.', 44, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 11, 'Be All My Sins Remember''d (2)', 'With a plan to potentially extinguish the Replicator threat, the Atlantis team must seek an alliance with a fleet of Wraith ships.', 44, '2008-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 12, 'Spoils of War', 'The team finds their former Wraith ally''s hive ship drifting in space, which leads them to a secret project that could turn the tide of a civil war.', 44, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 13, 'Quarantine', 'An automated lockdown traps Atlantis personnel in various parts of the city, each of them hoping the others will come to their rescue.', 44, '2008-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 14, 'Harmony', 'Colonel Sheppard and Dr. McKay must protect a child princess on a pilgrimage before she can become queen, and learn that she has dangerous enemies threatening her life.', 44, '2008-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 15, 'Outcast', 'While on personal leave on Earth, Sheppard and Ronon learn that scientists have engineered a human-form Replicator -- who is now on the loose.', 43, '2008-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 16, 'Trio', 'McKay, Carter, and Keller are trapped in an underground chamber while on an off-world mission, with no apparent means of escape.', 44, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 17, 'Midway', 'Teal''c visits Atlantis to counsel a headstrong Ronon, who is up for review by the I.O.A. But the two must work together when the Wraith invade the Midway space station in order to reach Earth.', 44, '2008-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 18, 'The Kindred (1)', 'As a mysterious new illness sweeps through the Pegasus Galaxy, Teyla is convinced by a vision that the father of her child is trying to communicate with her.', 44, '2008-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 19, 'The Kindred (2)', 'The team is shocked when an old friend, believed to be dead, miraculously returns to them. Teyla plans an escape from Michael''s captivity.', 44, '2008-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 4), 20, 'The Last Man (1)', 'Sheppard returns to Atlantis after a mission and finds the city abandoned, all systems dead -- and instead of ocean, sand dunes as far as the eye can see.', 44, '2008-03-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')), 5, 'Season 5', 'As Atlantis faces its greatest threats yet, the team must rely on unexpected alliances and new technologies to safeguard their city and the galaxy. The season builds toward a climactic confrontation that tests the strength, ingenuity, and resolve of the entire expedition.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 1, 'Search and Rescue (2)', 'Lt. Colonel John Sheppard and his team are trapped under the rubble of Michael''s facility in order to rescue Teyla Emmagan. As Colonel Samantha Carter launches a team to rescue the rescuers, little do they know that Michael Kenmore is also searching the planet for the survivors.', 44, '2008-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 2, 'The Seed', 'When a mysterious alien organism takes Dr. Jennifer Keller as its host, the newly revived Dr. Carson Beckett and the crew desperately search for a serum to save her from the evolving intruder before it can infiltrate Atlantis. In the meantime, Richard Woolsey officially joins the team, having been chosen as Colonel Samantha Carter''s replacement to lead the Atlantis expedition.', 44, '2008-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 3, 'Broken Ties', 'Ronon Dex is captured by Tyre, who wants to hand him to the Wraith in order to maintain his role in their circle. However, when the deal turns sour, and Tyre is left for dead, the Atlantis expedition persuade him to take back their friend. Meanwhile, The Wraith turn Ronon into a Wraith worshipper.', 43, '2008-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 4, 'The Daedalus Variations', 'The Atlantis expedition mysteriously finds the Daedalus, abandoned and drifting in space. When Lt. Colonel John Sheppard''s team come to investigate, the ship mysteriously disappears. They soon discover that the ship is actually an alternate Daedalus from a Alternate reality, and the team must find a way back to their Universe or risk being stranded forever in an unfamiliar reality.', 44, '2008-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 5, 'Ghost in the Machine', 'While on a mission, Lt. Colonel John Sheppard''s team inadvertently brings a mysterious entity to Atlantis. They soon learn that the entity is nothing more than Dr. Elizabeth Weir, who was thought to have been killed after her capture by the Asurans.', 44, '2008-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 6, 'The Shrine', 'Dr. Rodney McKay is infected with the Pegasus equivalent of Alzheimer''s disease, known as Second Childhood, a common illness among the elderly in the galaxy. The only way to save him is a shrine on Talus. The downside is that it has turned into a Wraith outpost.', 44, '2008-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 7, 'Whispers', 'Dr. Carson Beckett is called in to help a team investigating a lab that once belonged to Michael Kenmore. But soon, they realize that a group of experiments that even Michael couldn''t control are hellbent on killing the team.', 44, '2008-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 8, 'The Queen', 'The Atlantis expedition has a plan to remove the Wraith''s dependence on feeding to use an experimental gene therapy from Michael''s database. However, in order to convince the Primary, the Wraith leader, Teyla Emmagan must pose as a Hive Queen.', 44, '2008-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 9, 'Tracker', 'Dr. Jennifer Keller is kidnapped by a runner named Kiryk. While Dr. Rodney McKay and Ronon Dex tracks them, Kiryk takes Keller to a seriously injured young girl. She must do it fast, since the Wraith have found him, and are hunting them down.', 44, '2008-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 10, 'First Contact (1)', 'Dr. Daniel Jackson arrives in Atlantis to investigate a hidden lab left behind by the rogue Ancient scientist Janus. Their discovery has attracted the attention of a mysterious group of aliens, who infiltrate the city. Meanwhile, "Todd" and a delegation arrive on the Daedalus to bring forward Dr. Jennifer Keller''s gene therapy.', 44, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 11, 'The Lost Tribe (2)', 'As Dr. Rodney McKay and Dr. Daniel Jackson is held prisoner by the Vanir, they make a startling discovery about who they really are. Meanwhile, "Todd" and his Wraith hijack the Daedalus to find and destroy those who activated the Attero device. The Travelers arrive and Lt. Colonel John Sheppard must help them get to the planet before "Todd" uncovers a way to discover the device for good, even if it means sacrificing McKay and Jackson''s lives to do so.', 44, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 12, 'Outsiders', 'Dr. Carson Beckett, now a traveling doctor in Pegasus comes across a planet, where some of the villagers are refugees from Balar, a planet infected with the Hoffan drug, and destroyed by the Wraith. However, the Wraith arrive on the planet and gives the village an ultimatum, hand over the Balarians, or face destruction of the entire civilization.', 44, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 13, 'Inquisition', 'Lt. Colonel John Sheppard''s team is invited by the Coalition of Planets in order to form an alliance. However, the team is misled and is faced to stand trial, for their alleged crimes against the Pegasus galaxy. Their best chance of freedom, is the experiences of Richard Woolsey.', 44, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 14, 'The Prodigal', 'Michael Kenmore has infiltrated Atlantis with an army of his Hybrids, and closes off Stargate Operations and the surrounded levels to prevent anyone from taking it back. His plan; take Teyla Emmagan and her child to perfect his Hybrids, and to destroy the base when they''re done. Meanwhile, Lt. Colonel John Sheppard, Dr. Rodney McKay and a team try to take back the city before Michael leaves with what he wants.', 44, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 15, 'Remnants', 'While being evaluated by the International Oversight Advisory, Richard Woolsey meets a beautiful scientist new to Atlantis, who is not what she appears. Meanwhile, Lt. Colonel John Sheppard is captured and tortured by an enemy he thought he''d killed several years ago: his sworn enemy, Genii Commander Acastus Kolya.', 44, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 16, 'Brain Storm', 'Dr. Rodney McKay reluctantly returns to Earth to witness the triumph of his rival Dr. Malcolm Tunney, but must help shut down a deadly weather device when the new technology goes horribly awry.', 44, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 17, 'Infection', 'After a Wraith Hive Ship shows up over Atlantis transmitting a distress call, Lt. Colonel John Sheppard''s team discovers that its crew has been stricken with a disease they helped create.', 44, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 18, 'Identity', 'Dr. Jennifer Keller''s body is inadvertently taken over by a cunning thief, Neeva Casol. While Neeva tries to escape Atlantis, Keller finds herself imprisoned with a death sentence on another planet, forcing the team into a race against time to return Keller to her original body before she is put to death.', 44, '2008-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 19, 'Vegas', 'In the city of Las Vegas in an alternate reality, police Detective John Sheppard investigates a series of bizarre murders where each body appears to have desiccated. He is soon called to Area 51, where Dr. Rodney McKay explains the situation.', 44, '2008-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0374455')) AND numero_temporada = 5), 20, 'Enemy at the Gate', '"Todd" informs the Atlantis expedition that a rogue group of Wraith has acquired several Zero Point Modules to power a Super-hive, and wants it destroyed. However, after the Daedalus is disabled, they learn that the ship is heading straight for Earth, and they must stop it before it gets there.', 43, '2009-01-08');
