INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')), 1, 'Season 1', 'Season one begins in 52 B.C. as Gaius Julius Caesar completes his quest of Gaul after eight years of war and prepares to return with his army to Rome. But while Caesar''s self-interested niece Atia and long-lost paramour Servilia anxiously await his return, the ruling patricians despair that Caesar''s homecoming will disrupt the status quo. As Caesar''s legions move closer to Rome, allegiances are put to the test for both soldiers and civilians — and the escalating tensions climax with a full-scale conflict destined to change history.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 1, 'The Stolen Eagle', 'Eager to return to Rome after eight long years of war, Gaius Julius Caesar ends his campaign with a resounding triumph in Gaul, and news of a shattering personal loss at home. In Rome, Caesar''s old friend Pompey is counselled by the Senate, who worry about Caesar''s growing popularity. Two soldiers are enlisted to find the army''s stolen gold standard. Atia is careful to play both sides of an escalating power struggle.', 50, '2005-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 2, 'How Titus Pullo Brought Down the Republic', 'Anointed People''s Tribune by Caesar, Mark Antony returns to Rome with Octavian''s liberators, Vorenus and Pullo. After being feted by a grateful Atia, Vorenus heads home to his family, for the first time in eight years, while Pullo heads for the brothels. Pompey drafts an ultimatum stripping the general of his power.', 48, '2005-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 3, 'An Owl in a Thornbush', 'With Caesar quickly advancing toward Rome, Pompey begins ordering a retreat and forces his citizens to pick sides. Timon is forced to do Atia''s dirty work and Vorenus cannot understand why no one is resisting while on a scouting mission.', 42, '2005-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 4, 'Stealing From Saturn', 'As Pompey "maneuvers" outside the city, Caesar seeks to consolidate his hold on Rome. Atia throws a party to welcome Caesar home, while Vorenus throws one of his own to usher in his new life as a citizen businessman. Pullo''s run of luck continues when he delivers Quintus Pompey to Caesar, who in turn returns Quintus to his father''s camp, with an offer of truce he knows Pompey will never accept.', 52, '2005-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 5, 'The Ram Has Touched the Wall', 'Caesar weighs Pompey''s counteroffer against Antony''s recommendation to chase down Pompey''s vulnerable army. Vorenus is forced to reconsider his career choices after a series of business setbacks leave him with little income to support his family. A jealous Atia concocts a clever scheme to separate Caesar from Servilia. Pullo is recruited to tutor Octavian in the art of soldiering, but ends up learning a lesson or two from the boy.', 52, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 6, 'Egeria', 'When Caeser finds himself outnumbered by Pompey''s legions, he asks Antony to join the fight. Marc Antony is having fun in his new political life while he ponders a counter-offer from Pompey. Atia urges Octavian to take another step toward manhood. Vorenus and Niobe try to bring passion back to their marriage.', 56, '2005-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 7, 'Pharsalus', 'Pompey attacks an outnumbered Caesar. Vorenus and Pullo are stranded at sea. Atia continues to seek out Servilla''s friendship in order to ensure her protection, while Octavia and Servilla''s bond grows.', 56, '2005-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 8, 'Caesarion', 'Having pursued Pompey into Egypt, Caesar arrives in Alexandria and meets the boy king Ptolemy XIII, who offers the general a surprise gift. Vorenus and Pullo play liberators again, freeing Ptolemy''s incarcerated sister, Cleopatra. Caesar seeks payment from Egypt for past debts, and ends up forging a strategic union to ensure his legacy.', 53, '2005-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 9, 'Utica', 'With Scipio and Cato defeated, Caesar returns home to a hero''s welcome. Vorenus and Pullo''s showdown with local thug Erastes gets an unexpected reprieve from Caesar. Servilia''s plan to use Octavia to unearth a secret about Caesar backfires.', 54, '2005-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 10, 'Triumph', 'Unanimously proclaimed Dictator by the Senate, Caesar pronounces the war over, and prepares for five days of feasting and games honoring his "triumph." No longer an enlisted soldier, Pullo eyes a pastoral future with Eirene, while Vorenus runs for municipal magistrate, with Posca''s help. Meanwhile, Octavian retrieves Octavia from her self-imposed exile. And Servilia invites a revenge-minded Quintus Pompey into her home, to Brutus'' dismay.', 53, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 11, 'The Spoils', 'Vorenus sees to it that veteran soldiers receives severance on behalf of Caesar, and is then invited along with Niobe to one of Atia''s parties.', 49, '2005-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 1), 12, 'Kalends of February', 'Pullo and Vorenus are now heroes in the eyes of the Roman rank and file because of their arena feats. This causes Caesar to bestow rewards to those he might normally punish.', 48, '2005-11-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')), 2, 'Season 2', 'Season two''s storyline picks up right where season one left off: with the 44 B.C. assassination of Gaius Julius Caesar and the near-simultaneous death of Niobe, wife of Caesar''s faithful bodyguard Lucius Vorenus. Diverted from his post after learning that Lucius, his assumed grandson, was in fact Niobe''s illegitimate son, Vorenus now descends into near-madness over his failure to protect Caesar, his role in his spouse''s death, and the rumored murder of his estranged daughters.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 1, 'Passover', 'Things pick up shortly after Caesar''s murder. Octavian wants to keep his family from fleeing the city so he devises a plan. News of this makes Antony happy so he tells Brutus. Vorenus mourns Niobe''s death but casts aspersions upon his children.', 56, '2007-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 2, 'Son of Hades', 'Cleopatra arrives in Rome to pay her homage to Caesar, and to seek legitimization for Caesarion. Egypt''s queen causes further complications between Anthony and Atia, who still struggles with Servilia. Timon''s brother arrives from Jerusalem. The death of Erastes throws the underworld, and Rome''s river commerce into chaos, and Pullo and Vorenus step into the gap. Octavian and Anthony begin a long and bitter rivalry with a dispute over Caesar''s will and sharing of power.', 52, '2007-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 3, 'These Being the Words of Marcus Tullius Cicero', 'Brutus and Cassius struggle to raise foreign armies to oppose the Cesarean party. Mark Antony''s plans to change his post-consul proconsular governorship from Macedonia to Gaul are derailed when Cicero delivers an in-absentia message to the Senate, and throws his support behind Octavian. Vorenus struggles to contain an all-out gang war in the Aventine Collegium, of his own making, that he blames on Pullo. In the house of the Julii, Octavia passes the hours in a drug induced daze, while a duplicitous youth named Duro, planted amongst the Julii by Servilia, looks for the chance to set a deadly plan in motion.', 54, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 4, 'Testudo et Lepus (The Tortoise and the Hare)', 'Pullo races to find Vorenus with news of his family''s fate. Servilia''s plans to eliminate a rival exact a high price from her. Cicero is astonished when Octavian sends word that his victorious legions are coming home to Rome. In Rome, Timon finally grows weary of Atia''s bidding.', 50, '2007-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 5, 'Heroes of the Republic', 'Despite Pullo''s advice, Vorenus and his family return to the Collegium with his family who is reunited, and cleansed of their ordeal. Octavian is denied a triumph and urges Cicero to endorse his bid to be made Consul in exchange for an agreement to allow Cicero to veto his actions. Octavian takes both Cicero and the Senate by surprise with his first Consular act. Vorenus attempts'' to make peace with Memmio and Cotta create suspicions that he has gone soft.', 57, '2007-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 6, 'Philippi', 'Vorenus receives orders to plunge Rome into a bloodbath the likes that have not been seen since the dictatorship of Sulla. Octavia reveals her secret to Atia, and the armies of the Liberators and the Caesarians clash for the last time, with the fate of Republic in the balance.', 55, '2007-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 7, 'Death Mask', 'Antony''s nature reasserts itself, and challenges his alliance with Octavian. Timon and Levi set themselves against Herod''s plans. Servilia''s public displays of grief leave Atia unsettled. Gaia uses Pullo''s punishment as a weapon against him. His daughter''s sudden interest in business matters arouses Vorenus'' suspicions. Posca gets married.', 55, '2007-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 8, 'A Necessary Fiction', 'Octavian proclaims a new era of virtue in Rome, a program that his family and subordinates find impossible to obey. Vorenus is sent on a mission after a missing shipment of gold to discover who mysteriously hijacked it on its way to the Roman treasury. Pullo''s loss and rage are channeled against Memmio, Omnipor and their henchmen. Octavian pursues Livia as an "appropriate" bride, and issues Mark Antony an ultimatum he knows he can''t refuse.', 55, '2007-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 9, 'Deus Impeditio Esuritori Nullus (No God Can Stop a Hungry Man)', 'The people of Rome are starving. There have been many grain shortages over the past few months, but things have gotten particularly bad. In hopes of keeping the people from openly rebelling, Octavian sends Atia and Octavia to Alexandria in order to negotiate a deal with Mark Antony, though his real reasons for their trip is soon revealed. Meanwhile, Titus Pullo and Lucius Vorenus must try to keep the peace amongst many of the mercenaries who are in Rome.', 58, '2007-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0384766')) AND numero_temporada = 2), 10, 'De Patre Vostro (About Your Father)', 'Following his naval defeat at Actium, Marc Antony returns to Egypt, where he and Cleopatra settle into a world of debauchery. Octavian tries to use Pullo as leverage to Vorenus to gain acess to the palace, but Vorenus stays loyal to Antony. Finally, it is Cleopatra who dupes Antony, saving her own life by sacrificing her honor. Ceasar Augustus triumphs in Rome.', 63, '2007-03-25');
