INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0387199', 'Entourage', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0267497'), 'SERIE', 'Film star, Vince Chase, navigates the vapid terrain of Los Angeles with a close circle of friends and his trusty agent.', '2004-01-01', 'https://m.media-amazon.com/images/M/MV5BZjEyYWJlMDktNGEwMi00OTRjLWE4YzgtOTMwNDc0NzQzMDlmXkEyXkFqcGc@._V1_.jpg');
