INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 1, 'Season 1', 'Vince, Eric, Drama, and Turtle begin living it up in the wake of Vince''s latest hit, while the boys clash with Ari, attend a slew of wild parties, and decide on Vince''s next starring role: an independent film set in Queens and directed by a loose cannon named Billy Walsh.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 1, 'Entourage', 'Basking in the adulation from his latest movie premiere, Hollywood ''it'' actor Vince Chase joins childhood pals Eric, Drama and Turtle to debate the pros and cons of attending their tenth high-school reunion back east. Meanwhile, Eric – Vince''s de facto manager – incurs the wrath of Vince''s agent Ari by advising Vince to pass on a script he hasn''t even read. On the domestic-security front, Turtle agrees to test the mettle of the entourage''s new guard dog, a Rottweiler named Ahnold.', 29, '2004-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 2, 'The Review', 'Ignoring the cautionary portents of a negative review, Vince ramps up his already-excessive spending by leasing a new Rolls-Royce. Ari urges Vince to get a "real" manager, causing a wounded Eric to do some soul-searching. Meanwhile, Drama skips a "Vagina Monologues" rehearsal (go figure) to join Vince and the entourage at a wild party hosted by a sexy actress.', 26, '2004-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 3, 'Talk Show', 'After meeting a talk-show host at a boxing after-party in L.A., Vince agrees to appear on his show – despite a long-standing rift between the host and Drama. Eric and Kristen share a long goodbye; Ari puts the full-court press on a famous comic; and Luke Wilson tells Turtle how to score a free home-theater system for Vince.', 27, '2004-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 4, 'Date Night', 'Vince decides to celebrate the opening night of his latest movie, ''Head On,'' with a group date – to Eric''s chagrin. Drama''s pumped-up gal pal Tanya struts her stuff at a bowling alley; Turtle taps into Vince''s fan mail for some action; and Vince turns on the charm with unsullied pop vixen Justine Chaplin.', 26, '2004-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 5, 'The Script and the Sherpa', 'Vince''s fling with a ''cruelty-free'' vegan named Fiona – and her friendship with a laid-back L.A. ''sherpa'' – brings unexpected karma to the entourage. Eric pushes a promising new script set in Queens; Drama fears the disruptive power of his friends'' new relationships; and Turtle barters boots for booty.', 25, '2004-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 6, 'Busey and the Beach', 'Ari''s former assistant Josh, now a competing agent, woos Vince and the boys at a wild Malibu beach party. Drama ponders an alternate career in the food-service industry; Eric puts Emily in a compromising position; and Turtle irritates an actor at an art opening.', 25, '2004-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 7, 'The Scene', 'Eric is concerned over the choice of director, an indie loose cannon named Billy Walsh, for Vince''s new film. Meanwhile, Drama lobbies for a supporting role, while Ari finds he can''t mix business with pleasure.', 26, '2004-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 1), 8, 'New York', 'Sick of being known as ''Vince''s guy,'' Eric wants a title commensurate with his responsibilities. With his latest shoot taking him to New York for three months, Vince prepares to say goodbye to L.A. – as well as his many ''special'' girlfriends. Meanwhile, Drama debates taking either a high-paying TV role or a low-paying film gig, and Turtle stakes out a claim as Vince''s ''farewell party'' promoter.', 30, '2004-09-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 2, 'Season 2', 'After three months shooting an indie film in the Big Apple, the boys are back in Los Angeles. Eric is officially Vince''s manager, Turtle is running the house, Drama is hoping to enhance his on-screen assets, and Ari is pushing a blockbuster superhero role for his golden-boy client.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 1, 'The Boys Are Back in Town', 'The boys are back in town...and Ari, eager for a commercial project, pushes ''Aquaman'' – but Vince isn''t buying; Eric has an official title now, but his status is questioned when he has to make a ''sex date'' with Kristen; Drama''s agent may be moving up, but his head shots are stuck in the past; and Turtle, cranky about his new job, takes multi-tasking to a chaotic level.', 27, '2005-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 2, 'My Maserati Does 185', 'Vince agrees to a starlet''s pet project; Eric reluctantly lets a Perfect Ten model ''take care of him'' at a beach party, where Turtle misrepresents his position to get a girl; Drama develops calf envy; and Ari gets steamed up convincing the boys to read the ''Aquaman'' script.', 26, '2005-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 3, 'Aquamansion', 'When Vince falls for a house outside his price range, he suddenly sees the value of doing a franchise film. Meanwhile, the boys get psyched for a slumber party at the Mansion – but Drama''s been ''banned for life'' by Hef; Eric pressures Ari to prove himself as a deal-maker; and Turtle puts his faith in big-ticket sleepwear.', 28, '2005-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 4, 'An Offer Refused', 'As Vince and Turtle are carried away by top-dollar decorating, Eric is anxious to get an offer in writing; Drama decides on elective surgery to ''augment'' his livelihood; Ari breaks a deal in therapy with Mrs. Ari; and hotshot director Billy has big news about ''Queens Blvd.''', 24, '2005-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 5, 'Neighbors', 'Vince discovers why his gorgeous neighbor Staci has been so friendly. Eric regrets the past when he has to get through yet another gate kept by Emily. Ari tries to blackmail Dana into getting a meeting with an important director. When Drama and Turtle curb their spending, Vince grows suspicious.', 25, '2005-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 6, 'Chinatown', 'Ari encourages Vince to shoot a lucrative foreign commercial, and Drama wants to get in on the action. Eric struggles to convince Walsh to release an advance print of ''Queens Blvd.'' Turtle preps for an Xbox tournament.', 28, '2005-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 7, 'The Sundance Kids', 'Within moments of arriving at Sundance, Eric lands a lunch with studio bigwig – and gets an offer for Vince that might be too good to refuse. Ari advises him to play it safe, and Vince wants to roll the dice. Turtle and Drama don''t want to share.', 30, '2005-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 8, 'Oh, Mandy', 'One of the names on the short list to play ''Aquagirl'' exposes a secret from Vince''s past that makes Eric feel slighted. Ari gets bumped from an important list. Drama and Turtle try to enjoy their temporary new house.', 26, '2005-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 9, 'I Love You Too', 'Vince makes a splash at a convention with his new co-star. When neither Eric nor Shauna can appease a bitter journalist, Turtle sends a pair of professionals to the rescue. Ari gives Drama a rockin'' birthday gift.', 31, '2005-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 10, 'The Bat Mitzvah', 'Vince gets up-front about his feelings for Aquagirl, sending everyone into a panic. Meanwhile, Ari''s partner Terrance resurfaces, Eric splurges on an ''investment'' suit, and Drama and Turtle have high hopes for Little Miss Ari''s Bat Mitzvah.', 29, '2005-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 11, 'Blue Balls Lagoon', 'Vince receives courting lessons from Terrance and a valuable gift from Ari, Shauna flips over a press leak, and Eric gets attention – and ammo – from Terrance''s daughter Sloan. Meanwhile, Drama grows overexcited about a co-star, and Turtle plays ambassador for Vince.', 24, '2005-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 12, 'Good Morning, Saigon', 'When Vince and his co-star act out of character, Ari and Eric must face a team of angry handlers – and each other. Meanwhile, Drama and Turtle make a musical discovery while retrieving a stolen car.', 27, '2005-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 13, 'Exodus', 'Vince is blinded by love, and Eric gets cozy with Sloan. Meanwhile, Ari gets shot down in the war room, and Drama and Turtle use their paparazzi skills on an important spy mission.', 31, '2005-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 2), 14, 'The Abyss', 'Vince''s despondent mood forces Eric to consider fending for himself. Meanwhile, Ari has meetings at a coffee shop and Drama and Turtle make a vow of silence.', 27, '2005-09-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 3, 'Season 3', 'With Vince''s star expected to rise even higher in the Hollywood firmament as a result of his starring role in ''Aquaman'', Eric, Drama, Turtle, and Ari must find a way to keep stroking their golden goose while making sound decisions for a long-lasting career in a world of fleeting fame.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 1, 'Aquamom', 'As the gang anticipates the upcoming premiere for "Aquaman", the search is on for a perfect date for Vince. Meanwhile, Ari tries to cope with financial difficulties and his new office space, which is not quite what he is used to.', 25, '2006-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 2, 'One Day in the Valley', 'Ari and Eric are worried because rolling blackouts have hit Los Angeles and it may cause a decrease in the box-office totals for "Aquaman" in the area. The two ponder how to keep Vince from finding out the situation.', 25, '2006-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 3, 'Dominated', 'The gang have no idea what to think when Vince decides to hang out with his old  friend who happens to be an ex-con and wants them all to be friends. Meanwhile, Ari''s daughter ends up becoming friends with an up  and coming movie star.', 25, '2006-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 4, 'Guys and Doll', 'Dom, who has now become a part of Vince''s posse, ends up telling Vince a story that helps him get his dream role in the film, Medellin.', 25, '2006-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 5, 'Crash and Burn', 'Vince, Eric, and Ari seek to find a resolution to scheduling conflicts that would prevent Vince from doing both Medellin and Aquaman 2. Turtle deals with Saigon''s rising popularity, while Ari deals with his daughter''s continued obsession with Max.', 24, '2006-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 6, 'Three''s Company', 'Vince increases his asking price for Aquaman 2, which forces Ari to ask the studio head for yet another favor. But Vince insists that Ari finds Drama a job before he''ll accept any offer from the studio. Meanwhile, Eric''s girlfriend and her best friend make him an offer he can''t refuse, even if there are ground rules.', 25, '2006-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 7, 'Strange Days', 'Eric starts falling for the wrong girl after his threesome. Ari and Terrance come to an agency settlement. Vince is to be auctioned off at Sloan''s charity function.', 26, '2006-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 8, 'The Release', 'Vince and the entourage receive news that "Queens Boulevard" will be receiving a nationwide release. Ari must compromise with a rival to avoid threats from a group of aggressive agents. Drama is nervous about an important audition and begins to take his anger out on everyone.', 24, '2006-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 9, 'Vegas Baby, Vegas!', 'The gang heads to Vegas for a much-needed break and a $100,000 promotional appearance for Vince. But it turns out that Turtle reaps the benefits from the appearance. Eric gets jealous when Seth Green makes insinuating comments about Sloan. Vince and Ari partner at the tables, but Ari loses it when Vince''s luck ends. Drama lays it on thick with his masseur, leading to an awkward misunderstanding between them.', 25, '2006-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 10, 'I Wanna Be Sedated', 'Drama and Turtle go looking for Saigon on the day the record-deal''s supposed to be signed. Eric comes up with a project for Vince.', 28, '2006-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 11, 'What About Bob?', 'Eric, Ari, and Bob pitch the Ramones film project to the studios which causes a power struggle between Ari and Bob. Turtle wants a pair of limited edition shoes which Vince tries to buy for him. Drama begins filming his pilot.', 26, '2006-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 12, 'Sorry, Ari', 'With the apparent loss of the Ramones project and with Ari to blame, Vince and the guys begin to look for other agents to represent him.  Ari, hearing of Vince''s shopping, fights with all his might to get back the movie.  While looking at other agents, Vince realizes they are just too corporate for him and the "scumbag" Ari is the best in the business. However, since Ari cannot get the movie back, he tries to win Vince back with a corporate-style presentation himself.  This backfires because the boys find Ari to be just like everyone else now and fire Ari as they walk out of his office.', 26, '2006-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 13, 'Less Than 30', 'Vince''s new agent wants him to do a period film. In the meantime Eric and Vince agree to have lunch with Ari and Turtle plans Vince''s birthday party.', 26, '2007-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 14, 'Dog Day Afternoon', 'Amanda gets angry when Vince and Eric procrastinate over the Edith Wharton movie.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 15, 'Manic Monday', 'Amanda needs an answer on the period film, but Vince won''t commit to any other project until the cameras are actually rolling on ''Medellin.'' Amanda persists, so Vince has the crew read the script to get everybody''s opinion. Unfortunately, the script is so dry that nobody can get through it, leading Vince to realize that the project isn''t right for him after all.', 22, '2007-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 16, 'Gotcha', 'Drama finds out that he will be the target on Pauly Shore''s new Punk''d like reality show. Eric tries to relieve the tension between Vince and Amanda and Ari is jealous of a former fraternity brother.', 28, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 17, 'Return of the King', '"Medellin" is back on the table for Vince, but Ari and producer Nick Rubenstein must make the deal happen on the holy day, Yom Kippur.  They have until sundown, and must finish the deal with use of a cell phone. Eric wonders how the relationship between Vince and Amanda is affecting the deal. Drama grows attached to a race horse.', 27, '2007-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 18, 'The Resurrection', 'Eric and Vince are determined to get  "Medellin" off the ground, but the rights to the script stand in their way. Feeling tense the day of the "Five Towns" premiere, Drama seeks relief at a massage parlor, but can''t avoid Daily Variety. At the auto-body shop, Turtle meets a girl who shares his love for limited-edition sneakers, but her overbearing father hampers his game.', 30, '2007-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 19, 'The Prince''s Bride', 'Drama has an offer from Brett Ratner for "Rush Hour 3." Ari finds a backer for "Medellin" but the source of his wealth, and his wife''s intentions toward Vince, are shady. Turtle has a date with Kelly, under the watchful eye of her father.', 24, '2007-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 3), 20, 'Adios Amigos', 'Vince, Eric, Drama, and Turtle are forced to move out of the mansion. Eric moves in with Sloan and Drama wants to get an expensive condo. With "Medellin" getting into the early stages of pre-production, a surprise cast member is asked to direct.', 27, '2007-06-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 4, 'Season 4', '''Medillin'' is finally in production, but the troubles have only begun. Financial woes, bidding wars, and an irritable director all threaten to keep Vince, Eric, Drama, and Turtle away from the Palme d''Or at the Cannes Film Festival, even with Ari gripping the reins tightly as always.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 1, 'Welcome to the Jungle', 'A behind-the-scenes documentary about the filming of Medellín in Bogota, Colombia. Billy and Eric clash on the set about keeping the film on track. Billy becomes attracted to an actress which ends up disrupting the production. Drama tries to get Billy to give him a part in the film.', 30, '2007-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 2, 'The First Cut Is the Deepest', 'With the gang arriving back in America, Drama plans a party for Vince at his new condo. Ari learns that his son might not be accepted to an exclusive private school. Billy''s insecurities may prevent Vince and Eric from seeing the first cut of Medellín.', 27, '2007-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 3, 'Malibooty', 'Billy submits Medellin to the Cannes film festival, leading Eric - who thinks the film needs work - to worry that it will get rejected. Drama rekindles an old flame, and brings Turtle in as his wingman. Vince gets in over his head in Malibu.', 25, '2007-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 4, 'Sorry, Harvey', 'Ari mistakenly mishandles a top-secret script, a mistake that lands him in jail. Drama fetes the mayor of Beverly Hills, with help from Vince. Eric has to go back on his word with Harvey Weingard, a Hollywood heavyweight, when Medellín is accepted into the Cannes Film Festival.', 26, '2007-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 5, 'The Dream Team', 'The Medellin trailer is leaked on YouTube and Billy blames Eric. Drama joins an exclusive  medical marijuana club. And Ari and Lloyd engage in sabotage so that Vince can get his next project.', 26, '2007-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 6, 'The Weho Ho', 'Billy makes amends with Eric over the online leak of Medellin. Lloyd takes a leave of absence from the Miller Gold Agency for personal problems. In the meantime Turtle makes an investment.', 25, '2007-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 7, 'The Day Fuckers', 'Eric and Turtle''s love lives become a source of amusement for Vince and Drama. Ari adjusts to having his son in public school.', 28, '2007-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 8, 'Gary''s Desk', 'When Eric gets his own office, Vince eyes a piece of antique furniture that also has a rich history, but someone has already gotten his hands on it. Ari preps for a meeting with R&B superstar Mary J. Blige, but has to contend with twin-sibling rivalry in his own office.', 25, '2007-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 9, 'The Young and the Stoned', 'Eric gets into a fender-bender with Anna Faris, leading to what he believes to be "a little moment," but in the end, his career is about to change. Ari''s wife acts on a soap opera, leading him to try and dissuade her from doing so. Turtle gets prepped for a party by picking up some provisions, and girls, only to encounter the law on the way home.', 28, '2007-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 10, 'Snow Job', 'Vince, Ari, and Dana Gordon receive the script for Vince''s next project, but Billy''s interpretation is vastly different than what he was supposed to write. Vince loves the script anyway leading Ari to try and keep the studio interested. Eric is occupied with a new client and her boyfriend.', 29, '2007-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 11, 'No Cannes Do', 'A security threat at LAX strains everyone''s hopes of getting to Cannes in time for the Medellin premiere. Mrs. Ari and Lloyd both wish to take the trip with Ari to Cannes. Walsh writes Eric''s new client into his script.  Help in the end comes from a very unexpected source.', 28, '2007-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 4), 12, 'The Cannes Kids', 'In the fourth-season finale, attempts to sell “Medellin” at Cannes are complicated by the fact that no one has seen the finished product. Meanwhile, the popularity of “Viking Quest” gives Drama a boost.', 34, '2007-09-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 5, 'Season 5', 'After a disastrous screening of ''Medellin'' at the Cannes Film Festival, Vince seeks refuge from the pressure. Eric is determined to get Vince back to the top, while Ari fights to deliver for Vince. Drama continues his successful television career and Turtle re-examines his contributions.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 1, 'Fantasy Island', 'As the dismal reviews for Medellin continue to roll in, Vince hides out in a Mexican paradise with Turtle. Meanwhile, producer Carl Ertz wants a meeting with Vince about a role in a guaranteed hit, and Eric and Ari go all out to persuade him to come back to LA. Drama turns prima donna during a Five Towns photo shoot, and begins a "virtual" romance with Jacqueline, his Cannes girlfriend.', 27, '2008-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 2, 'Unlike a Virgin', 'Vince is feeling insecure about more than just his career when former flame Justine Chapin pawns him off on her friend at a party. Eric offers to represent LB and Nick, two writers of an indie film script, but can''t get them Vince, or any help from Ari. Drama maintains constant contact with Jacqueline.', 27, '2008-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 3, 'The All Out Fall Out', 'To avoid bankruptcy, Vince takes Shauna''s and his accountant''s advice by agreeing to make an appearance at a not-so-sweet-sixteen bash. After a fast and furious drag race in his new Ferrari, Ari ups the ante with Adam Davies. Still devastated by his breakup, Drama befriends a bottle of Johnny Walker Blue.', 28, '2008-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 4, 'Fire Sale', 'Ari shows interest in Eric''s indie script, imagining it as a big studio production with Vince as the lead, but believing they now have a bidding war on their hands, the writers up their price. Determined to postpone his post-breakup depression, Drama gets pumped for his guest appearance on "The View."', 24, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 5, 'Tree Trippers', 'Making the right call on a crucial career move calls for Vince and the guys to search for clarity and guidance in the arid expanse of Joshua Tree National Park. Meanwhile, Lloyd assists Ari in his time of need.', 30, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 6, 'ReDOMption', 'Ari wagers on a role for Vince in a game of golf with Alan Gray. After causing a televised car chase, Dom asks Vince to bail him out, but only Eric can afford it. Desperate for a job, Turtle agrees to be Drama''s personal assistant.', 31, '2008-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 7, 'Gotta Look Up to Get Down', 'Vince gets a taste of the fashion world when he agrees to do a Dolce & Gabbana photo shoot with a gorgeous supermodel. Ari pays his respects at a funeral while he tries to work a deal for Vince.', 28, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 8, 'First Class Jerk', 'After scoring a first class seat next to Jamie-Lynn Sigler, Turtle makes a mile-high claim the guys just don''t buy. While Ari is distracted, Josh Weinstein courts Vince.', 24, '2008-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 9, 'Pie', 'On the set of "Smokejumpers," Vince contends with first-day jitters and intimidating co-star Jason Patric. Ari has lunch with Andrew Klein, an old friend and mentor who needs his help.', 30, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 10, 'Seth Green Day', 'E''s new client Charlie gets his pilot script picked up, but the studio wants to cast E''s arch-nemesis, Seth Green. Vince confronts Verner, the director of "Smokejumpers," who tells Vince to work on his bad habits. To help impress Babs, Ari and Lloyd give Andrew a Hollywood makeover.', 29, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 11, 'Play''n with Fire', 'During shooting of a pivotal scene for "Smokejumpers," Vince gets contradictory direction from Verner, and Ari and Dana Gordon try to put out the flames. After receiving an unexpected call, Turtle has a clandestine meeting.', 29, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 5), 12, 'Return to Queens Blvd.', 'Despite a not-so-triumphant return, the guys party it up in NYC. After getting a tip from Vince''s mom, E stalks Gus Van Sant to convince him to cast Vince in a role. Meanwhile, Vince reconnects with his high school sweetheart and Drama considers an investment opportunity.', 27, '2008-11-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 6, 'Season 6', 'Vince has weathered a series of professional storms and bounced back big with his performance in the legendary Scorsese''s ''Gatsby''. Meanwhile, the guys each take steps to develop their own careers, and Ari looks to build up his agency with the help of a new partner.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 1, 'Drive', 'Vince is back in the fast lane, preparing for his driving test and an appearance with Jay Leno to promote the premiere of his new movie “Gatsby,” directed by Martin Scorsese. Meanwhile, with a nudge from Sloan, Eric considers moving into his own house, but worries about the impact on Vince and the gang. Looking for career advancement, Lloyd confronts Ari with an ultimatum, which Ari counters with a proposition of his own.', 28, '2009-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 2, 'Amongst Friends', 'Eric invites Sloan to Vince’s premiere, but just “as friends.” Ari arranges a friend date between Mrs. Gold and Andrew’s wife, but his new partner’s actions threaten to foil Ari’s plans. Meanwhile, Lloyd goes on a crash diet per Ari’s demand. And Turtle makes his red-carpet debut with Jamie-Lynn on his arm.', 27, '2009-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 3, 'One Car, Two Car, Red Car, Blue Car', 'Turtle contemplates his future career path, and seeks out Ari for advice. Meanwhile, Eric gets nervous about Charlie’s pilot after getting some unsolicited feedback from his new fling.', 26, '2009-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 4, 'Running on E', 'With production on his next film delayed, Vince searches for ways to amuse himself. Andrew tells Ari he''s ended his affair with Lizzie, but Ari has Lloyd keep an eye on him anyway. Drama auditions actresses to play his new love interest on "Five Towns"; Jamie-Lynn takes Turtle shopping for back-to-school clothes; and a bored E contemplates his next move.', 31, '2009-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 5, 'Fore!', 'At a charity golf tournament, Vince and Drama up the stakes with teammates Mark Wahlberg and Tom Brady. Eric is surprised by a job opportunity, and even more surprised when he finds out why he was considered in the first place. After refusing to break the "guy code," Ari finds himself in the doghouse with Mrs. Ari and Jeffrey Tambor.', 24, '2009-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 6, 'Murphy''s Lie', 'Eric considers the management-company offer while trying to patch things up with Ashley after a Freudian slip. Ari finally gets Mrs. Gold to forgive him at home, but an appearance by Marlo Klein tests his resolve at work. Drama tries to protect Jamie-Lynn from a disreputable network executive.', 29, '2009-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 7, 'No More Drama', 'Vince and Turtle decide to arm themselves after a break-in. Drama goes to desperate measures to repair his tarnished relationship with a network exec. On his first day at his new job, Eric butts heads with one of the managers over who can close Bob Saget as a client.', 26, '2009-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 8, 'The Sorkin Notes', 'Eric agrees to meet with Sloan, but rethinks their whole relationship after Ashley calls him. Andrew''s meltdown puts a big deal in jeopardy. Fearing for their safety, Vince and the boys decide to call in the pros.', 25, '2009-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 9, 'Security Briefs', 'Drama follows up on a tip about Vince''s suspected stalker, while Turtle gets some surprising news about the break-in. Ari steals teen heartthrob Zac Efron from Adam Davies, so Davies offers Lloyd a job as an agent, which brings him into conflict with Ari. Ashley grows increasingly suspicious of Eric.', 25, '2009-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 10, 'Berried Alive', 'Drama eyes a part on Melrose 2009 and asks Lloyd if he can get him out of his current gig on Five Towns. Still irate over Lloyd''s job offer, Ari goes to war against Lloyd to get Drama out of his contract. Citing their trust issues, Ashley asks Eric if she can read his e-mails. Turtle feels guilty about his love triangle, of sorts, with Jamie-Lynn and a UCLA co-ed.', 28, '2009-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 11, 'Scared Straight', 'Eric visits the doctor''s office after getting some unsavory news from Drama about his latest fling. Ari investigates Terrance after he unexpectedly offers to sell Ari his share of his agency. Meanwhile, Turtle prepares for Jamie-Lynn''s departure and Drama''s emotions get the best of him during his audition for Melrose 2009.', 29, '2009-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 6), 12, 'Give a Little Bit', 'When Matt Damon and LeBron James send out a charity call, an unwilling Vince takes up the challenge. Ari tries to convince his wife that his deal with Terrance will be lucrative. Drama ponders a switch in careers. Eric makes plans to meet Sloan.', 38, '2009-10-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 7, 'Season 7', 'A near-fatal accident during the filming of his latest action flick leaves Vince with a new lease on life that makes him more difficult to manage. Meanwhile, Eric, Drama, and Turtle must decide which steps to take to map out their increasingly complicated personal and professional lives.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 1, 'Stunted', 'The director of Vince''s latest action film talks his star into doing his own driving stunt, agitating both Eric and Ari. Turtle''s attraction to an underperforming employee named Alex threatens to damage his fledgling carservice business. Ari looks to add to his resume as "the biggest agent in the world" by eying an alliance with the NFL. Worried that his holding deal is about to expire, Drama pressures Lloyd, now his agent, to land him a project.', 28, '2010-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 2, 'Buzzed', 'Ari must face a public relations crisis over Vince''s movie while meeting with top NFL executives; Eric agrees to help Drama find the perfect script; Turtle accuses Alex of maxing out his corporate credit card.', 28, '2010-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 3, 'Dramedy', 'Eric and Phil try to convince Drama that he has talent on the sitcom front; Ari resists Barbara''s urgings to have Lizzie promoted; Turtle is intrigued by a business proposal from Alex; Scott Lavin continues to ingratiate himself with Vince.', 27, '2010-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 4, 'Tequila Sunrise', 'Turtle has a hard time trusting Alex; Drama gets off on the wrong foot with potential co-star John Stamos;  Ari learns that Lizzie may be siphoning off some of his clients; Eric and Scott settle their differences.', 27, '2010-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 5, 'Bottoms Up', 'Vince is impressed by porn star Sasha Grey and her literary knowledge, and ends up bringing her along to a meeting with Stan Lee. Suspecting that Lizzie is trying to steal his clients, Ari woos Jessica Simpson, Aaron Sorkin and Mike Tyson, but not before taking out his ire on Mrs. Ari. Turtle pitches Eric about Vince becoming the face of his new venture. Drama is anxious about his new series with John Stamos, especially after learning Bob Saget is eyeing his role.', 28, '2010-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 6, 'Hair', 'Facing a possible lawsuit, Ari readies himself to do battle with Lizzie and her new boss, old foe Amanda Daniels. Vince puts his next big-budget movie in jeopardy with his antics, including a risqué online video. Turtle’s romancing of Alex does not go as well as he’d envisioned. A cleaned-up Billy Walsh returns to ask Eric about directing jobs – and comes up with new show idea for Drama, who’s been wallowing in self-pity.', 27, '2010-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 7, 'Tequila and Coke', 'Seeking assurance that Vince’s life is under control, director Randall Wallace calls a meeting, but Vince parties a bit too hard the night before. Ari agrees to help Lizzie find a new job in exchange for some potentially damaging audiotapes. Turtle winds up in damage control after promising an L.A. retailer more product than he can deliver. Billy Walsh’s latest pitch leaves Drama indignant and Eric intrigued.', 29, '2010-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 8, 'Sniff Sniff Gang Bang', 'Eric is informed by Phil Yagoda (William Fichtner) that the network is interested in Drama’s show, though the star is not enthused about its content. In the wake of recent bad press, Ari attempts to fashion a kinder, gentler persona at work and home. When demand for Turtle’s tequila line outpaces production, he sets out to find new sources of funding. Vince tries to convince Sasha to turn down a high-paying offer to do another porn movie.', 30, '2010-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 9, 'Porn Scenes from an Italian Restaurant', 'To keep her out of a porn film, Vince tries to land Sasha a part on his new movie. During a chance run-in with Queen Latifah, Ari finds out that Amanda Daniels may have landed a deal he’d coveted. Eric tries to get Drama on board for Billy Walsh’s series, and Eric’s assistant Jennie (Janet Montgomery) pitches in to help persuade him. Turtle’s efforts to find financial backing from Mark Cuban gets him in hot water with his Mexican boss.', 28, '2010-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 7), 10, 'Lose Yourself', 'Ari tries to keep his wife''s surprise party on track, the guys attempt to stage an intervention for Vince, and Turtle scrambles to find investors to save the tequila business.', 31, '2010-09-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')), 8, 'Season 8', 'Vince is back from rehab with a new pet project; Ari and his wife have recently separated; Eric has broken up with Sloan after a prenup debacle, and is running his own management company with Scott Lavin; Drama is shooting his animated series, ''Johnny''s Bananas'', with Andrew Dice Clay; and Turtle has invested in the Avion tequila line and started a new business venture. The boys have been through a lot over the years: chasing dreams, women and good times as if the party would never end. But end it must. Will they make it on their own and achieve the successes they''ve always dreamed of?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 1, 'Home Sweet Home', 'The guys go to extremes to keep Vince away from temptation after he gets out of rehab, but they''re also worried about triggering a relapse when he''s excited about a lame idea for a movie. Meanwhile, Ari pleads with his wife to end their separation, and Eric and Scott court new clients for their fledgling management company.', 30, '2011-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 2, 'Out with a Bang', 'After writing a 20-page outline for his movie idea, Vince asks Billy to give it a once over. Ari finds out that Mrs. Gold may be lowering her standards after a tip from Lloyd. Drama''s "Johnny''s Bananas" costar Andrew Dice Clay needs representation, and leaves Drama reeling after getting an idea. Turtle consistently fails to get Alex on the phone. A miscommunication between Eric and Sloan turns into an encounter that Eric will not forget, yet will want to.', 26, '2011-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 3, 'One Last Shot', 'A benevolent Vince defies his friends'' advice and gives an old nemesis, producer Carl Ertz, a second chance when he claims to be interested in the miner movie. Meanwhile, Andrew Dice Clay takes a stand on his "Johnny''s Bananas" contract despite Drama''s disapproval. Lloyd convinces Ari to go on a date, and Turtle has a meeting with his boss about his future with Avion.', 31, '2011-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 4, 'Whiz Kid', 'Shauna goes into damage-control mode when Vince must pass a drug test after being caught in a compromising position. Ari escorts an old flame to Bobby Flay''s restaurant to get back at his wife following a rancorous session of couples therapy.', 23, '2011-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 5, 'Motherfucker', 'Dissatisfied with his new "Johnny''s Bananas" costar, Drama hatches a plan to bring Andrew Dice Clay back to the show. Meanwhile, Vince tries to do his own damage control with a Vanity Fair interview, Eric bonds with Sloan''s ex-stepmother over their romantic woes, and Ari''s recent tryst makes for an awkward business meeting with Dana Gordon.', 30, '2011-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 6, 'The Big Bang', 'Ari gets unsettling news from his lawyer about his divorce. Eric is floored by a gift from Melinda Clarke, but unnerved by a revelation from Johnny Galecki. Vince deals with the fallout from his interview and Turtle meets his new business partners.', 28, '2011-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 7, 'Second to Last', 'Turtle turns to his investors for more money when his new business partners eye an expensive property. Meanwhile, Eric and Melinda crash Sloan''s date, the miner movie gets personal for Ari, and Vince woos Sophia.', 30, '2011-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387199')) AND numero_temporada = 8), 8, 'The End', 'Vince takes a surprising step after a first date with Sophia. A therapy session yields mixed results for Ari and Mrs. Ari, and Vince, Drama and Turtle urge Sloan to work things out with Eric.', 31, '2011-09-11');
