INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 1, 'Series 1', 'Two dysfunctional flatmates, Mark and Jeremy, fumble through work, love, and life in South London, with their awkward thoughts laid bare in the show’s signature point‑of‑view style.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 1), 1, 'Warring Factions', 'Mark and Jeremy find themselves in competition for the same woman: Toni from next door. This is not the entire problem with Mark and his love life, rather, he is also lusting after Sophie, a co-worker, but finds himself at a loss with how to put his feelings into action. Jeremy is also pre-occupied, but not with love, with his music.', 24, '2003-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 1), 2, 'The Interview', 'Jeremy faces a dilemma: money vs. art. Should he put all his time and effort into his music and try to ''make it'' or should he be like Mark and get a 9 to 5 job to pay the bills (including three months of rent owed to Mark). Sophie is still the object of Mark''s desires and he still fumbles about trying desperately to let her know how he feels.', 24, '2003-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 1), 3, 'On The Pull', 'Mark and Jeremy go to a party to try and find some long lost love, or perhaps someone for the night. At the party Mark meets a cool goth ''teenager'' named Valarie, who wants to take their acquaintance to the next level: bowling! This gives Jeremy a chance to hook up with Toni, and allows Mark to take his mind off of Sophie . . . or will it?', 24, '2003-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 1), 4, 'Mark Makes A Friend', 'Mark attends a work conference and in the process makes a new friend, Alan Johnson, which upsets the ''El Dude'' partnership. This forces Jeremy to consider who could replace Mark as flatmate and best friend. Super-Hands is the potential replacement, but he doesn''t match up as well. Mark grows a moustache, like his new hero, Johnson whilst Jeremy is haunted by flashbacks to ''the one bad thing'' that happened when he was wrecked with Super-Hands.', 24, '2003-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 1), 5, 'Dream Job', 'Jeremy tries to wow Toni with his new job in a music studio while Mark gets passed over for promotion in favour of Sophie, and goes slowly round the twist. They then attempt to solve each other''s problems with the help of phone stalking and pepper spray.', 24, '2003-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 1), 6, 'Funeral', 'In the last episode of the series, death and terminal illness prove to be the keys to romantic success for Mark and Jeremy. Jeremy gets in with the Christians and Mark finds the perfect venue for a first date with Sophie - a funeral. Everyone''s having a great time until the paramedics arrive.', 24, '2003-10-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 2, 'Series 2', 'Mark and Jeremy’s awkward misadventures continue in South London as Mark copes with Sophie’s shifting relationships and personal setbacks, while Jeremy pursues chaotic love, new opportunities, and questionable life choices—again seen through the show’s signature inner‑thought point‑of‑view style.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 2), 1, 'Dance Class', 'Can you love two people at the same time? Jeremy believes you can, and his gorgeous new American girlfriend puts his taboo bashing beliefs to the test. Mark believes you can only love one person. Besides, he and Sophie, the object of his unrequited love, are getting on really well, especially since he starting hacking into her emails.', 27, '2004-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 2), 2, 'Jeremy Makes It', 'Jeremy is hired by an old school friend to make a soundtrack for a film he''s making. Mark makes a new friend at work who turns out to hold a fair amount of prejudice. Meanwhile, Sophie spends time with Jeff.', 26, '2004-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 2), 3, 'Local Zero', 'Jeremy wants to get closer to Nancy so he tries to impress her by joining in her volunteer work which involves working in a soup kitchen for the homeless.  Mark manages to get Johnson to think he is an alcoholic.', 25, '2004-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 2), 4, 'University Challenge', 'Mark, determined to forget Sophie, makes an effort to go out with April - but manages to blur the line between enthusiastic new boyfriend and stalker. Jeremy joins a new band, Executioners Bong, but insists that he is neither a roadie nor the equivalent of Bez.', 26, '2004-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 2), 5, 'The Man Show', 'Mark becomes depressed about Sophie living with Jeff, but Jeremy is not sure that self-mutilation is the answer. Besides, Jeremy and Jeff are getting on horribly well.', 26, '2004-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 2), 6, 'Wedding', 'Jeremy and Nancy are getting married, for visa reasons. Mark, determined to save his friend, will do whatever it takes to stop them...', 26, '2004-12-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 3, 'Series 3', 'Mark and Sophie finally start a relationship while Mark struggles with commitment and awkward life choices, and Jeremy juggles romantic complications, jury duty, and chaotic schemes—all shown through their unfiltered inner thoughts.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 3), 1, 'Mugging', 'Mark has a run-in with some muggers, who steal his precious blackberry - and put him off his stroke with Sophie as a result... Meanwhile, Jeremy faces a tricky dilemma over the love of his life and a potential threesome.', 30, '2005-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 3), 2, 'Sectioning', 'Mark and Sophie are finally beginning to go steady when Sophie is moved away from London for work. Mark is devastated, so Sophie offers phone sex as a solution, which Mark nervously accepts. Meanwhile, Jeremy is forced to consider getting an old friend sectioned.', 30, '2005-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 3), 3, 'Shrooming', 'Jeremy plans to throw a secret magic mushroom party in the flat, where he hopes to seduce his ex, Big Suze. But when Mark suddenly comes home from work with gastric flu, Jeremy''s plans go to pieces.', 30, '2005-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 3), 4, 'Sistering', 'Mark''s plans for an enjoyable and productive week off work go out the window when his sister comes to stay. Jeremy clearly has the hots for her, and when Mark warns him to back off, Jeremy just wants her more...', 24, '2005-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 3), 5, 'Jurying', 'Jeremy gets called for jury service but soon complicates things by falling for the defendant. Elsewhere, Mark & Sophie go clubbing.', 25, '2005-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 3), 6, 'Quantocking', 'Mark worries he and Sophie are drifting apart and proposes. Elsewhere Super-Hans decides to give up drugs, and Jeremy once again gets intimate with past love Big Suze.', 25, '2005-12-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 4, 'Series 4', 'With Mark and Sophie engaged, the season follows their fraught wedding preparations, growing doubts about the future, and a disastrously awkward ceremony, as Jeremy’s own escapades add to the chaos in typical cringe‑comedy fashion.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 4), 1, 'Sophie''s Parents', 'Mark continues to dread the impending doom of his wedding day, still questioning his actions from the previous season. Both Mark and Jeremy meet Sophie''s parents and brother- leading to disaster with arson, sex with a parent and drunken arguments.', 0, '2007-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 4), 2, 'Conference', 'Johnson returns, immediately taking a shine to Big Suze, proposing a deal involving her to Jeremy. Mark is caught up in Johnson''s "Project Zeus" with his reputation at the workplace hanging in the balance. Geoff makes his first appearance of the season, and Sophie spends some alone time with Jeremy in the hotel room.', 0, '2007-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 4), 3, 'Gym', 'In order to avoid spending time with Sophie, Mark gets a gym membership. Whilst there he discovers that Jeremy''s ex-wife Nancy is working there. Mark tells Jeremy who then becomes desperate to get back together with her. He decides to take a job as a cleaner at the gym and sets about stopping her from dating Mark''s personal trainer Matt.', 0, '2007-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 4), 4, 'Handyman', 'Jeremy meets his hero, techno musician Russell "The Orgazoid". He ends up working as his handyman, which leads Mark to become suspicious, as it seems that Jeremy''s job consists of making smoothies for him. Meanwhile Mark meets Sally at his school reunion, one the few girls who actually ever liked him. It turns out that she has married one of Mark''s childhood tormentors, Foz. Mark decides to try and seduce Sally whilst Sophie is away on a business trip.', 0, '2007-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 4), 5, 'Holiday', 'Jeremy takes Mark on a stag weekend, with a rented canal boat. There, they meet two sisters, Aurora and Lucy, and their father. Jeremy falls in love with Aurora, whilst Lucy becomes sexually attracted to Mark. The father offers Mark a job in India, a way out of his impending marriage to Sophie, whilst Jeremy accidentally kills, and then eats a bit of Aurora''s dog.', 0, '2007-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 4), 6, 'Wedding', 'It''s Mark''s wedding day. He is torn about whether he should go through with it or not. Jeremy discourages him but Mark continues. On the way to the reception, Sophie breaks down and runs away. Jeremy comforts Mark as the ''El Dude Brothers'' are reunited.', 0, '2007-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 5, 'Series 5', 'After the fallout from the wedding, Mark awkwardly navigates new relationships while Jeremy runs out of money and pursues various schemes, leading both flatmates into fresh humiliations and misguided life choices with all thoughts laid bare.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 5), 1, 'Burgling', 'It''s not so long since Mark''s new bride Sophie stumbled from the car, looking in appalled fascination at her husband of ten minutes and sobbed, "He''s horrible!" As we return for the fifth series of this engagingly filthy comedy, Mark (David Mitchell) is getting drunk and maudlin on wedding champagne as his flatmate Jeremy (Robert Webb) urges him to go out on a double-date: "Beggars can''t be choosers, she''s an actual woman." Mark - remember, this is a man who once based his romantic strategy on the Siege of Stalingrad - arms himself with a copy of the Friends of the British Museum magazine and goes forth again to search for love.', 0, '2008-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 5), 2, 'Spin War', 'Mark and Sophie return to work, while Jeremy renews his acquaintance with the depraved Super Hans, in yet another filthy, funny episode.', 0, '2008-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 5), 3, 'Jeremy''s Broke', 'Jeremy finally runs out of money and finds himself on a downward spiral of hunger, homelessness and criminality. Meanwhile Mark needs to find a girlfriend before his birthday party.', 0, '2008-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 5), 4, 'Jeremy''s Mummy', 'Jeremy''s tortured relationship with his very sweet mother comes under the spotlight. It emerges that Jez has been living off handouts from his mum for years and now he''s in line for half of her £40,000 bequest from an aunt. Jeremy''s need to self destruct kicks in immediately, as does Mark''s inability to stop his excruciating attempts to ingratiate himself with any mature grown-up. He adores Jeremy''s mum and hero-worships her Scots Guardsman boyfriend.', 0, '2008-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 5), 5, 'Jeremy''s Manager', 'Jeremy and Super Hans get a band manager and play a Christian rock festival. Mark comes along as their roadie, and learns how to have sex properly for the first time in his life.', 0, '2008-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 5), 6, 'Mark''s Women', 'Mark gets into online gaming and live role play with Dobby and wonders whether she may be The One. Meanwhile, Mark and Sophie finally sort out their annulment. Jeremy joins a cult.', 0, '2008-06-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 6, 'Series 6', 'Mark and Jeremy face major life changes as Sophie’s pregnancy nears, Mark pursues Dobby while juggling career ups and downs, and Jeremy falls head‑over‑heels with a new love interest, leading both into chaotic choices and awkward situations seen through their signature inner thoughts.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 6), 1, 'Jeremy at JLB', 'Newly promoted Mark decides to enjoy his additional power and wealth by splashing out on a boiler, a ''creamy elephant'' sofa and by finding Jeremy a job in the office. Things are also looking promising for Mark in his pursuit of Dobby, the company IT girl. However, a routine fire drill puts his plans into total disarray.', 0, '2009-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 6), 2, 'The Test', 'Mark makes a final play for Dobby, the object of his desires. Meanwhile, Jeremy meets a new love, Russian émigré Elena. Both guys are determined to impress, but one of them is an expectant father. And when the pregnant Sophie spills the beans, both Mark and Jeremy''s worlds change forever.', 0, '2009-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 6), 3, 'Jeremy in Love', 'Jeremy realises that he''s in love with Elena and decides to be generally less selfish to win her affection. He also thinks it might be a good idea to tell her he loves her, but Mark isn''t so sure...', 0, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 6), 4, 'The Affair', 'Mark discovers that Jeremy''s girlfriend Elena has a guilty secret. But should he tell him when Jez is clearly so happy? In addition to this, Alan Johnson offers Mark the chance to go into business with him. Mark, while reassuring himself that this is his dream offer, begins to see Johnson in a new light. Big Suze inadvertently brings Mark and Jeremy''s problems to a head', 0, '2009-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 6), 5, 'The Party', 'As a last desperate hurrah before the baby arrives, Mark and Jeremy decide to throw a party. Mark sees it as his final opportunity to reignite his relationship with Dobby, while Jeremy imagines it''s a chance to make Elena insanely jealous. But as the evening proceeds, it all becomes a bit of an emotional roller-coaster.', 0, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 6), 6, 'Das Boot', 'Time is running out for Jeremy as Elena and Gail''s marriage is imminent. However, he thinks there may be a way to get Gail off the scene and win Elena back. Meanwhile Mark, although conflicted about becoming a father, is worried that Jeff is becoming a potential rival dad. He decides that he''s going to learn to drive so that he can take Sophie to the hospital when the baby arrives. Sophie is delighted, but learning to drive doesn''t prove that easy.', 0, '2009-10-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 7, 'Series 7', 'Mark is navigating fatherhood and awkward relationships while Jeremy pursues new love interests and half‑baked career ideas, leading to more chaotic misadventures in flat shar­ing life and friendships with their inner thoughts on full display.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 7), 1, 'St Hospital''s', 'Mark and Jeremy are at the hospital awaiting the birth of Mark''s baby. Sophie is determined to have a natural birth and doesn''t want Mark to transfer any of his anxiety to the baby. Meanwhile, Jeremy is convinced he will never get over losing Elena, until he meets Zahra, whose boyfriend is in a coma.', 0, '2010-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 7), 2, 'Man Jam', 'Dobby, the object of Mark''s desires, is now dating a graphic designer named Simon. Both Gerrard and Mark are determined to win her affections. Ben offers Jeremy the ideal job as head of development for his music web site.', 0, '2010-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 7), 3, 'A Beautiful Mind', 'Jeremy holds a book group at the flat in an effort to try and impress Zahra but apart from Mr Nice, Jeremy has never read a book. Mark is concerned by not being able to satisfy Dobby''s sexual needs and decides to get some help for the problem.', 0, '2010-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 7), 4, 'Nether Zone', 'Mark''s baby''s christening day arrives and he arranges to take Jeremy to the church with him. The duo end up getting locked in the hallway of Zahra''s flat though.', 0, '2010-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 7), 5, 'Seasonal Beatings', 'Mark has invited his parents over for Christmas dinner. Everything has been planned down to the last detail but Jeremy has become over excited and Dobby and Super Hans show up as unexpected guests.', 0, '2010-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 7), 6, 'New Year''s Eve', 'Mark is depressed about Dobby on New Year''s Eve but Jeremy is determined that the ''El Dude Brothers'' are going to have the best night ever.', 0, '2010-12-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 8, 'Series 8', 'Mark and Dobby’s relationship hits bumps as they consider moving in together and Mark grows jealous of rivals, while Jeremy tries therapy and self‑improvement yet still finds ways to complicate their lives in classic cringe‑comedy fashion.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 8), 1, 'Jeremy Therapised', 'Mark has asked Dobby to move in with him, and Jeremy is faced with the prospect of moving out to make way. But Jeremy has been dragging his heels and Mark is increasingly worried that Dobby will move in with his rival, Gerrard instead.', 0, '2012-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 8), 2, 'Business Secrets of the Pharaohs', 'Mark gets a lucky break when his book, ''Business Secrets of the Pharaohs'', is accepted by a ''publisher''. Jeremy, in an attempt to kick-start his career, enrols on a life-coaching course.', 0, '2012-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 8), 3, 'The Love Bunker', 'Simon, Dobby''s ex-boyfriend, invites Mark, Dobby, Jeremy and Superhans to join him and his friends for a paintballing weekend. Mark is convinced that Simon is using the weekend as a cover to get back with Dobby, and Jeremy is convinced he can life coach Neil, Simon''s best friend.', 0, '2012-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 8), 4, 'Big Mad Andy', 'Jeremy finally agrees to leave the flat and move in with Super Hans. Mark employs a decorator, Andy, to repaint the kitchen, and Jeremy helps out by giving him free ''life-coaching'' advice. Meanwhile, Mark enrolls on a business studies evening course and meets Stephanie an attractive older woman.', 0, '2012-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 8), 5, 'Chairman Mark', 'Jeremy, desperate to avoid living with Superhans, sparks up an old relationship with Mark''s siser Sara, and moves in with her and her five-year-old son, Joshy. Mark, meanwhile, in an attempt to deal with a damp patch on his bedroom wall, launches a campaign to be elected chairman of the freehold committee of Apollo House.', 0, '2012-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')) AND numero_temporada = 8), 6, 'Quantocking II', 'Dobby is offered a job in New York by ex-boyfriend Simon. Uncertain about the offer, Dobby suggests that she and Mark spend a weekend in the country. The perfect time, as far as Jeremy is concerned, to get a few things off his chest.', 0, '2012-12-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0387764')), 9, 'Series 9', 'In the final season, Mark and Jeremy reunite after a fallout and return to their dysfunctional routines, confronting fading hopes, awkward adult life decisions, and their enduring yet turbulent bond with humor and discomfort through their signature point‑of‑view style.');
