INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 11, 'Let There be Light', 'Jamie and Adam take on The Mummy, while Kari, Grant and Tory try to stop an out-of-control car without another car.', 0, '2011-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 12, 'Paper Armor', 'Adam and Jamie explore the physics of shock waves in water, while Kari, Grant and Tory find out if paper battle armor can compare to steel.', 0, '2011-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 13, 'Bikes and Bazookas', 'Adam and Jamie test the myth that a motorcycle is a greener and cleaner machine than a car, while Kari, Tory, and Grant unleash the first RPG in MythBusters history to see if a bullet could take out a bazooka.', 0, '2011-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 14, 'Newton''s Crane Cradle', 'Jamie and Adam test a viral video that supersizes Newton''s cradle using wrecking balls, while Kari, Grant, and Tory tackle whether a bird landing on your hood is enough to tip your car off a cliff.', 0, '2011-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 15, 'Walk a Straight Line', 'Is it impossible for humans (without a point of reference) to walk in a straight line, such as when they''re blindfolded? Will binary explosives, well, explode in the case of a fender bender? The MythBusters are on the case.', 0, '2011-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 16, 'Duct Tape Plane', 'Adam and Jamie test three viral videos featuring the extraordinary excavator: Can it really row a barge? Be used to go wakeboarding? Perform seemingly impossible feats of acrobatics? Then -- using only duct tape -- Kari, Grant, and Tory attempt to patch up a plane that''s had an unfortunate encounter with a bear.', 60, '2011-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 17, 'Flying Guillotine', 'Jamie and Adam explore whether it''s safe to use the explosive C4 as a cooking fuel as long as you don''t drop anything on it, while Kari, Grant, and Tory put a Chinese martial-arts myth to the test.', 0, '2011-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 18, 'Drain Disaster', 'Find out whether a sewer drain full of combustible gas, when ignited, will turn an innocent manhole cover into a missile, and whether truck bedliners are truly bite, crash, and bomb proof.', 0, '2011-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 19, 'Wet and Wild', 'When it comes to H2O, the MythBusters are never shy about putting their bodies on the line, riding the world''s biggest waterslide, deep-sea diving in a suit of armor and swimming in syrup. Go behind the scenes of the 12 wettest myths of all time.', 0, '2011-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 20, 'Wheel of Mythfortune', 'By spinning the Wheel of Mythfortune, the MythBusters find themselves taking on five random viewer-suggested myths with titles like the "Monty Hall Paradox," "Lumber Car," "Firearm Fashion," "Hit the Deck" and "Flaming Tire." Keep those ideas coming!', 0, '2011-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 9), 21, 'Toilet Bomb', 'Adam and Jamie tackle a blockbuster bathroom bomb (from Lethal Weapon), while Kari, Tory, and Grant take to the skies to find out if flying in V-formation works for airplanes as well as it does for birds.', 0, '2011-11-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 10, 'Season 10', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 1, 'Duct Tape Island', 'Abandoned on a Hawaiian island, Jamie and Adam find themselves armed with nothing but the sticky silver adhesive. Can they use it to source water, find food, build shelter, and even escape?', 0, '2012-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 2, 'Fire vs. Ice', 'Adam and Jamie tackle an internet sensation about an epic duel between a flamethrower and a CO2 fire extinguisher, while Kari, Tory and Grant get high-tech find out if a dust cloud created by a foursome of 4x4s can really blind the all-seeing eye of the latest military spy drone.', 0, '2012-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 3, 'Square Wheels', 'Adam and Jamie test whether, after a certain speed, the ride in a car with square wheels is just as smooth as with round ones, while in Date Night Car, Tory, Kari and Grant tackle a tandem driving myth from the movie Date Night.', 0, '2012-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 4, 'Swinging Pirates', 'The Hyneman and Captain Redbeard take a swing at a Pirates of the Caribbean myth, while Kari, Tory and Grant roll out the barrel for a turbo-charged go-cart.', 0, '2012-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 5, 'Battle of the Sexes', 'CONTROVERSY! The MythBusters pit men against women in grilling, packing the car, driving and reading non-verbal cues. WHO will WIN the GENDER WARS?', 60, '2012-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 6, 'Driving in Heels', 'Spike heels and platforms may be the height of fashion, but does fancy footwear put you at risk on the road? Don''t miss Jamie and Adam''s attempt to find out. Then, in Super Glue Heroics, Tory, Grant and Kari test whether it''s possible to glue a roomful of furniture to a hotel-room ceiling as well as to substitute super glue for a seat-belt in a head-on car crash.', 60, '2012-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 7, 'Revenge of the Myth', 'The MythBusters take fan-favorite myths -- including Bird Balance, Exploding Water Heater, Fireworks Man and Viral Excavator -- to another level in the ultimate experimental ramp-up.', 0, '2012-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 8, 'Bouncing Bullet', 'Adam and Jamie take aim at a ricochet myth from the TV show Burn Notice while Kari, Tory and Grant test the Hollywood myth that if you jump when running away from an explosion, you can surf the shockwave.', 0, '2012-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 9, 'Mailbag Special', 'This fan-correspondence catch-up includes both question-answering and taking mini-myth requests such as whether you can eat a spoonful of cinnamon without drinking water.', 0, '2012-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 10, 'Bubble Pack Plunge', 'The Internet and Hollywood are put on the hot seat as Adam and Jamie test whether survival is possible if you jump from a building wrapped in bubble packaging, and Kari, Grant, and Tory experiment with a James Bond ejector seat.', 0, '2012-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 11, 'Duel Dilemmas', 'While Adam and Jamie test that first rule of modern warfare -- "never bring a knife to a gunfight" -- Kari, Grant, and Tory find out if a two-stage missile known as the fire-breathing dragon ever really existed.', 0, '2012-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 12, 'Hollywood Gunslingers', 'The MythBusters bust out with guns blazing to take aim at eight Hollywood firearms fables, including never-ending ammo, lethal nail guns and deadly silver bullets.', 0, '2012-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 13, 'Jawsome Shark Special', 'Adam Savage and Jamie Hyneman have put themselves in some pretty hair-raising scenarios to bust the biggest shark myths over the years, and now they count down their top 25 of all time. The duo also takes on new myths, shows never-seen-before footage and reveals the number-one shark myth that will quite literally blow people away.', 0, '2012-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 14, 'Titanic Survival', 'Adam and Jamie team up with Titanic movie director James Cameron to tackle the most requested myth in MythBuster history, while Kari, Grant and Tory ride a rocket-powered surfboard.', 0, '2012-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 15, 'Trench Torpedo', 'The guys fire up a myth from World War One - testing if a trench corner can slow down a shockwave and save a soldier. Tory, Kari and Grant crash clown cars to see if balloons can protect you in a crash.', 0, '2012-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 16, 'Hail Hijynx', 'Adam and Jamie take on bridge physics from the action movie Cliffhanger, while Kari, Grant and Tory test if giant hail can really sink a fishing boat.', 60, '2012-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 17, 'Fright Night', 'In this Halloween special, the MythBusters take on haunted hums and the smell of fear. Adam and Jamie see if certain sound frequencies can convince people of paranormal activity. Kari, Grant and Tory find out if the smell of fear really exists.', 0, '2012-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 18, 'Mini Myth Medley', 'The team mixes it up with a medley of viewer requested myths and hit a home run with baseball legend Matt Cain. The guys test an underwater bike ride, if you really can "know it like the back of your hand," and the potty dance.', 0, '2012-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 19, 'Cannonball Chemistry', 'Adam and Jamie test whether a mattress can really cushion a watery wipeout. Meanwhile, Kari, Tory and Grant tackle a blast from the past as they test if cannonballs made of stone can really cause carnage.', 0, '2012-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 10), 20, 'Food Fables', 'Celebrity chef Alton Brown helps the team discover if it can cook lasagna in a dishwasher or a meal beneath the hood of a car.', 0, '2012-11-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 1, 'JATO Rocket Car: Mission Accomplished?', 'MythBusters'' 10th anniversary kicks off with a blast from the past, the myth that began the busting: JATO Rocket Car. Back with more rocket power, more gadgets, and a huge rolling bunker called The Beast, will the team bust this myth once and for all?', 60, '2013-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 2, 'Deadliest Catch Crabtastic Special', 'Deadliest Catch captains Johnathan and Junior join the MythBusters to test if a crab pot will drag you overboard to the bottom if your foot is caught in a coil, if it''s better to work a 30-hr grind with no sleep, and if crab pots truly are indestructible.', 0, '2013-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 3, 'Down and Dirty/Earthquake Survival', 'The MythBusters get down and dirty to test if using a bathroom''s hand dryer is better than a paper towel and which public restroom stall is the cleanest. They also shake, rattle and roll to test if it''s better to stand in the doorway during an earthquake.', 60, '2013-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 4, 'Indy Car Special', 'The MythBusters burn rubber at the Indianapolis Motor Speedway testing racing myths. Can man beat machine in a 30-ft, standing-start sprint? Can a driver lose 10 lbs during a race? Can a race tire''s suction rip loose a manhole cover during a street race?', 60, '2013-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 5, 'Battle of the Sexes: Round 2', 'It''s Round 2 of Battle of the Sexes and the MythBusters test the cliches: Will lost men really not stop and ask for directions? Are women better multi-taskers? Which sex can parallel park with aplomb? And should "throwing like a girl" really be an insult?', 0, '2013-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 6, 'Motorcycle Water Ski', 'Jamie puts his life on the line to test the myth that a motorcycle traveling at highway speeds can drive across the surface of a lake. The MythBusters test whether you can survive a jump from a highrise with a parachute made from a hotel room''s contents.', 0, '2013-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 7, 'Hypermiling/Crash Cushions', 'Could a guy sandwiched between two big guys in the backseat of a car survive the car being T-boned by a truck? The MythBusters also hit the road to test three more hypermiling myths. Can these simple techniques really double your car''s fuel efficiency?', 0, '2013-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 8, 'Duct Tape Canyon', 'Lost in the wilderness, Adam and Jamie survive the desert, repel down canyon cliff-faces, and brave Class 5 rapids, all with duct tape and bubble wrap. Guest appearance by Nik Wallenda, famous tightrope walker, who has his own way to traverse the canyon.', 60, '2013-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 9, 'Painting With Explosives/Bifurcated Boat', 'After 7 years, it''s back to unsolved Myth-teries: Can Adam''s snowflake of death or Jamie''s special sphere paint a room with a boom? Then, the fans demand the return to the cursed, bifurcated boat myth to see if it can be split in two by a channel marker.', 0, '2013-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 10, 'Breaking Bad Special', 'Things get volatile when the MythBusters meet creator Vince Gilligan and star Aaron Paul to check the chemistry behind the hit TV show "Breaking Bad." The team recreates two iconic, acidic scenes to see if the science truly holds up, melts down, or blows.', 0, '2013-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 11), 11, 'Zombie Special', 'Adam and Jamie test two myths about the power of the zombie hoard. First, can they really break through a door thanks to working as a team of pushing power? Second, what''s the perfect weapon to use against the zombie hoard: gun or ax? Then Kari, Grant and Tory unleash their inner beast too as they find out if it''s really inevitable that zombies will catch you even though they only shuffle at 2 miles an hour!', 0, '2013-10-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 12, 'Season 12', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 1, 'Star Wars Special', 'The MythBusters test if Luke really could swing himself and Leia across a chasm with only his belt-rigged grappling hook, could an Ewok log swing crush an Imperial "Chicken Walker", and could Luke survive in a tauntaun''s belly?', 43, '2014-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 2, 'Moonshiner Myths', 'The MythBusters find out if an exploding still really could blow your house down and if you really could use hooch to fuel an unmodified car on a "moonshine run."', 43, '2014-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 3, 'Hollywood Car Crash Cliches', 'It''s wall-to-wall automotive mayhem, as the MythBusters drive through glass, plow through traffic, and fire an RPG at an SUV to take aim at classic Hollywood crash cliches.', 43, '2014-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 4, 'Car Chase Chaos / Animal Antics', 'The MythBusters test car-chase cliches: Can you really share driving, change places, or dump the driver while moving at speed? Also, from the message boards, the team tests some fan-suggested deterrents for driving away cats, bears and snakes.', 43, '2014-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 5, '*DO* Try This at Home?', 'After more than 10 years of testing impossible, dangerous and downright crazy myths that you shouldn''t or couldn''t try at home, the MythBusters investigate a host of myths that maybe you can!', 43, '2014-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 6, 'Mythssion Impossible', 'The MythBusters test three impossible idioms: Can you herd cats? Can you catch a greased pig? And, most importantly, can you cram 10 pounds of poop into a 5-pound bag?', 0, '2014-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 7, 'Bullet Baloney', 'The MythBusters take on five filmic firearm cliches: Will a bent-barreled shot gun fire? Can you fire a gun in space? Will a gun dropped in a deep fryer go off? What weird items will stop a bullet? And does a neon sign really explode when hit by a bullet?', 0, '2014-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 8, 'Supersonic Ping Pong/Ice Cannon', 'In this ballistics bonanza, Adam and Jamie ask if supersonic ping pong can go lethally wrong while Kari, Grant and Tory light the frozen fuse on a cannon made of ice!', 60, '2014-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 9, 'Fire in the Hole', 'The MythBusters tackle some of Hollywood''s favorite explosive scenarios. Could a hero really shoot a live grenade in midair and thus render it useless? Could you really contain a TNT explosion inside an ordinary object like a file cabinet or aquarium?', 60, '2014-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 10, 'Household Disasters', 'It''s YOUR house under the Myths-cro-scope this time. Could a vacuum cleaner explode while sucking up black powder? Could sunscreen scorch your skin? Could a piano crash through your roof? And finally, could an exploding water heater extinguish a house fire?', 0, '2014-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 11, 'Commercial Myths', 'The MythBusters go to vertigo-inducing heights to test out some commercial myths. Could you actually bob for an apple while jumping from a 100-foot high bungee cord? And from a viral video, could you really play a match of tennis while both players are standing on top of an airplane''s wing?', 0, '2014-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 12, 'Road Rage', 'In this episode, three car crimes straight from Hollywood are put to the test: the cliff top push, the two-wheel wipeout (and ... we do mean WIPEOUT, with Adam at the wheel to boot), and, finally, the Corvette barrel roll from "Wanted."', 60, '2014-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 13, 'Laws of Attraction', 'The MythBusters use sexy science to tackle five captivating clich?s about the laws of attraction, including whether men really do prefer blondes, if pheromone sprays really work, if bigger boobs equal bigger tips, and whether a man''s wealth really woos women.', 0, '2014-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 14, 'Traffic Tricks', 'The subject is everyone''s favorite topic of discussion besides weather: traffic! The MythBusters determine whether a roundabout (or rotary) is better than a four-way stop sign, if it''s faster to drive than fly when your trip is under 400 miles, and whether it''s better to change lanes or stay put in heavy traffic.', 0, '2014-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 12), 15, 'Plane Boarding', 'If you travel at all, you''ll LOVE this episode, as Jamie and Adam explore the most efficient ways to board an airplane (back to front? window to aisle? unassigned seating? etc.). Then, Kari, Grant and Tory determine whether you can really make a bullet out of a human tooth.', 0, '2014-08-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 13, 'Season 13', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 1, 'The Simpsons: D''oh!', 'Finally, the MythBusters meet the Simpsons! Will putting a cherry bomb in a toilet block cause all toilets to erupt with a violent fountain? Can an obese human (sorry, Homer) absorb the impact of a wrecking ball?', 43, '2015-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 2, 'The Busters of the Lost Myths', 'Adam LOVED this one, as you can imagine. Can a whip make your enemy drop his gun? Can you wrap a whip around a log and swing across a chasm? Could Indy have outrun a rolling boulder? Could Indy had survived a Mayan temple run through the various booby traps?', 43, '2015-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 3, 'A-Team Special', 'Jamie and Adam find out if it''s really possible to build a working cannon out of stuff abandoned in a barn, then test whether a sewer explosion can really take out the bad guys without serious injury.', 43, '2015-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 4, 'Video Game Special', 'Jamie and Adam -- with the help of UFC fighter Brendan Schaub and the makers of DOOM -- test how many weapons you can really take with you and remain operational. And can you really chop fruit a la Fruit Ninja?', 43, '2015-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 5, 'Transformers', 'Adam and Jamie tackle two tall tales of mechanical metamorphosis: Is it possible to convert a 2CV into a motorbike? Can you use water bottles to create an amphibious bicycle?', 43, '2015-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 6, 'San Francisco Drift', 'Jamie and Adam tackled two tall tales from the world of street racing. Does drifting really get to your destination faster? And does drifting help you park faster?', 43, '2015-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 7, 'Blow It Out of the Water', 'Having come to represent the concept of ''overwhelming victory'', this saying originally came from submarines in WW2 who were able to use torpedoes to literally blow an enemy ship up and out of the water. But is this really possible? And in the Breaking Bad season finale, Walter White took down every single bad guy with a simple crank shaft, remote control and M60. Potential reality or just fiction?', 42, '2015-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 8, 'Flights of Fantasy', 'Drone deliveries are on their way. But are those fast-spinning blades just an accident waiting to happen? And is the U-2 really the toughest aircraft in regular use to fly and land?', 43, '2015-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 9, 'Accidental Ammo', 'Jamie and Adam tackle another gruesome story about a pane of glass falling from a construction site and cutting an innocent bystander completely in half from head to toe. Then Jamie builds a Lawnmower From Hell also find out whether a stone shot from a mower can have the same power as a bullet shot from a .357.', 43, '2015-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 10, 'Dangerous Driving', 'Is it as dangerous to use hands free as it is to use a cell phone while driving? Is it really straightforward to drive at high speed in reverse?', 43, '2015-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 11, 'Supernatural Shooters', 'Adam and Jamie take aim at Hollywood''s infallible hit men and their seemingly supernatural ability to take down a target. First up, can an armed assassin use a single well-placed shot to kill his victim on the other side of a wall? Do interior walls truly provide such little protection, and can you really track an unseen target this way?', 43, '2015-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 12, 'Unfinished Business', 'Can you hold onto a grenade for longer than two hours? Can you really change a magazine in a blink-and-you-miss-it moment? Can video games make you better at real-life tasks, like golf? And can you really stop a car by using hollow spikes?', 43, '2015-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 13, 'MythBusters vs. Jaws', 'Jamie and Adam revisit Jaws'' final scene, which they''d taken on in 2005''s Exploding Scuba Tank. Will the results be different with a giant anatomically accurate shark and a bigger gun? Then the duo test two repellents: the sound of orcas and essence of "dead shark."', 43, '2015-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 13), 14, 'Star Wars (2) - The Myths Strike Back', 'Star Wars provides further fodder when Jamie and Adam see whether high ground really is important in a duel, and whether it''s possible to dive out of the way of laser blaster bullets (well, a Stormtroopers'', anyway).', 43, '2015-09-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 14, 'Season 14', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 1, 'MythBusters Revealed', 'Since 2002, the MythBusters have used science to separate fact from fiction but now, after an epic 14 years, that wild ride is coming to an end. In this special episode, Jamie and Adam reveal what''s in store for their go-big-then-go-home final season, while also pulling back the curtain to showcase how this epic series got made with behind-the-scenes exclusives.', 43, '2016-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 2, 'The Explosion Special', 'The MythBusters celebrate their explosive history with two spectacular big bangs. In MacGyver Cement Truck, our mullet-wearing hero discovers a mail truck full of TNT. Thinking quickly (as he does), MacGyver has a nearby cement truck dump its load onto the truck to smother the bomb. But would it work in real life? Then in Hovercraft Hijinks the guys tackle the one explosive technology they''ve yet to come across: landmines. Can a minefield really be safely traversed in a hovercraft?', 43, '2016-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 3, 'Tanker Crush', 'This season, Jamie and Adam try something they''ve never done before: an implosion caused by a vacuum. The tall tale goes that a freight train tank car was being steam cleaned when a rainstorm let loose. The engineers made the mistake of sealing the container full of hot steam and headed home. The rain cooled the tank car, the steam condensed and contracted, and the resulting pressure differential caused the massive steel car to crumple like a soda can. Is it possible? The MythBusters devote an entire episode and embark on the biggest logistical operation in their history to find out.', 43, '2016-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 4, 'Cooking Chaos', 'This episode takes on two viral videos. First, is it possible to fire shrimp from an air cannon through a cloud of flour, shower of egg wash, then breadcrumbs before a fireball crisps them into the perfect tempura on a plate? Second, can an underwater explosive charge juice the inside of a piece of fruit or vegetable while leaving the exterior completely undamaged?', 43, '2016-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 5, 'Driven to Destruction', 'When it comes to destroying cars, the MythBusters are experts, and in this episode, they''re going out with a bang! First, Adam sees if you can really lift up a car with nothing but a humble vacuum, before Jamie then tries to flatten a car using nothing but an absolutely massive load of C4!', 43, '2016-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 6, 'Volunteer Special', 'In their 14 years, the MythBusters have used more than 3,500 human guinea pigs, and in this special, they pay homage to each! First, Jamie and Adam summon up an army of 200 zombies to determine the ultimate weapon when the apocalypse comes. Then, using 120 shopping volunteers, the MythBusters find out the best way to wait in line at the store: Is it the "pick a lane" method or the more modern serpentine?', 43, '2016-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 7, 'Failure Is Not an Option!', 'In this last revisit, Adam and Jamie attempt to right their wrongs. First they bust out their drifting moves to find out whether drifting is faster than driving -- on dirt! Then they return to the ultimate fan favorite -- what is bulletproof -- and put lighters and fish tanks in the firing line. Finally, the guys test whether it''s possible to survive two explosions by standing directly between them.', 43, '2016-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 8, 'Rocketman', 'Adam and Jamie tackle the all-time fan favorite: Are gummy bears a viable rocket fuel?! To find out they get to grips with some genuine rocket science and sweet chemistry and then hit the Mojave Desert for testing. It''s a challenging story with plenty of ups and downs, and it finishes with a trademark Hyneman curve ball: swapping gummy bears for poop.', 43, '2016-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 9, 'Reddit Special', 'Adam and Jamie put MythBusters in the hands of redditors, choosing from several thousand of their suggestions. In Farting on FLIR Jamie and Adam address the reddit community''s request to know if a viral video purporting to show a flatus show up on an infrared camera is real or fake. Then in Ball Fall, Buster has a tough day at the office, testing whether a person would survive a 1,000-foot drop inside an inflatable ball. Paper Bag Punch sees Adam explore how easy it really is to punch your way out of a aper bag. And finally the most popular request was a gratuitous spectacular explosion. So in Snoo Boom the MythBusters oblige by blowing up reddit''s mascot.', 43, '2016-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 10, 'Grand Finale', 'Since 2002, Adam and Jamie have used science to separate fact from fiction in spectacular style! But, as the saying goes, all good things must come to an end and MythBusters is no exception. Luckily, the guys are going out with a bang and then some: an RV gets blown to kingdom come, Buster goes supersonic, Adam takes the most wild ride imaginable and ... well, Cement Truck. It all boils down to a cement truck filled with 5,000 pounds of ANFO as the MythBusters sign off in style.', 43, '2016-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 14), 11, 'Reunion', 'For this final hour of the television icon that is MythBusters, the five hosts are reunited for one last hurrah! Deep within M5, Adam Savage, Jamie Hyneman, Kari Byron, Tory Belleci and Grant Imahara join forces once more to together give a suitably epic, enlightening and emotional finale to the best science show on television.', 43, '2016-03-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 15, 'Season 15', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 15), 1, 'Heads Will Roll', 'Mythbusters returns with new hosts Jonathan and Brian.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 15), 2, 'Chimney Cannon', 'The MythBusters investigate if a burglar can be shot out of a chimney when the fireplace is lit. Then they power up a chainsaw to test if a bullet embedded in a tree will have fatal consequences.', 43, '2017-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 15), 3, 'Earthquake Water Heater', 'The MythBusters investigate if a water-heater can turn into a destructive torpedo, and reveal the explosive power of flatulence.', 43, '2017-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 15), 4, 'Rock ''n'' Roll Road Rage', NULL, 43, '2017-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 15), 5, 'Invisible Assassins', 'The MythBusters take on Hollywood''s greatest invisible assassins with a trio of tall tales of ingenious booby traps.', 43, '2017-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 15), 6, 'Dead Body Double', 'Can a human body be used protect you in a gun battle?
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')), 16, 'Season 16', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 1, 'Fire Arrow vs. Gas Tank', 'The MythBusters investigate two arrow-themed myths: Will a flaming arrow fired into a car''s gas tank cause it to explode, and is a deadly-looking tribal initiation really is as dangerous as it seems.', 43, '2018-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 2, 'Pane In The Glass', 'The MythBusters take on a glass-shattering movie myth, and search for cure to stop crying while chopping onions.', 43, '2018-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 3, 'Wild Wild West', 'The MythBusters tackle more myths in a wild west themed episode.', 43, '2018-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 4, 'Spike In The Road', 'The MythBusters test ways to beat police road spikes using DIY ingenuity and Hollywood driving skills. Secondly, they investigate if a high-powered fountain can actually lift and suspend a human being.', 43, '2018-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 5, 'Dynamite Deposit', 'The MythBusters tackle more myths using their own signature style of explosive experimentation.', 42, '2018-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 6, 'Backseat Getaway Driver', 'The MythBusters test if a fugitive could actually outrun the law while driving from the back seat, and whether it''s really possible to knock someone over with a feather.', 42, '2018-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 7, 'Electrified Escape', 'It is possible to escape from a burning car crashed into a power pole, without getting electrocuted? Is it better for a pedestrian to jump up when a car is about to hit them, or stand still?', 42, '2018-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0383126')) AND numero_temporada = 16), 8, 'Dropping a Bomb', 'Can dropping molten salt into a toilet unblock it? Is 3rd-person perspective better than 1st-person in a real world video game obstacle course?', 42, '2018-02-21');
