INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 1, 'Season 1', 'This season introduced the main characters, and established the general plot, which revolves around Michael Scott, regional manager of the Scranton branch office, trying to convince the filmmakers of the documentary that he presides over a happy, well-running office. Meanwhile, sales rep Jim Halpert finds methods to undermine his cube-mate, Dwight Schrute; receptionist Pam Beesly tries to deal with Michael''s insensitivities and flubs; and temporary employee Ryan Howard is acting mostly as an observer of the insanity around him.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 1), 1, 'Pilot', 'A documentary crew arrives at the offices of Dunder Mifflin to observe the employees and learn about modern management. Manager Michael Scott tries to paint a happy picture, while sales rep Jim fights with his nemesis Dwight and flirts with receptionist Pam.', 24, '2005-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 1), 2, 'Diversity Day', 'A consultant arrives to teach the staff about tolerance and diversity but Michael insists on imparting his own knowledge. Meanwhile, Jim struggles to keep hold of a lucrative contract extension.', 22, '2005-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 1), 3, 'Health Care', 'Michael doesn''t want to upset the staff so he gets Dwight to pass on news about the company''s reduced health provisions. Fed up with his nosiness, Jim and Pam pretend they are suffering from a variety of conditions including Ebola, Mad Cow Disease, spontaneous dentohydroplosion, hotdog fingers, nano-robot infection...', 23, '2005-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 1), 4, 'The Alliance', 'Michael arranges a morale-boosting birthday party for Meredith and is determined to come up with the funniest message in her card. Dwight wants a pact with Jim to fight the downsizing, and Michael regrets showing off when Oscar asks for sponsorship for a charity walk being undertaken by his nephew, who has cerebral palsy.', 22, '2005-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 1), 5, 'Basketball', 'The office staff play a basketball game against the warehouse workers in which Jim shows off to impress Pam and upstage her fiancee who is on the opposing team.', 23, '2005-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 1), 6, 'Hot Girl', 'A woman who comes to the office to sell purses gets the male members of staff excited. She rejects Dwight''s advances, but Michael reckons he''s still in with a chance.', 23, '2005-04-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 2, 'Season 2', 'Beginning with "The Dundies", the second season further developed into the plot of the fear of company downsizing, along with the introduction of new characters and developing some of the minor ones—especially that of Dwight Schrute. Michael Scott soon starts a relationship with his boss Jan Levenson and, Pam Beesley and Jim Halpert’s relationship become one of the focal points of the season. Their compatibility becomes more obvious as Jim’s feelings for Pam continue to grow, while she struggles with her relationship with the warehouse worker Roy Anderson.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 1, 'The Dundies', 'It''s time for the "Dundies", Dunder Mifflin''s annual awards banquet (held at the neighborhood Chili''s), and the staff must endure the excruciating performance of their inept emcee, boss Michael Scott.', 21, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 2, 'Sexual Harassment', 'Just as corporate tells Toby, one of the workers at the Scranton branch, to give a seminar on sexual harassment issues, Michael receives a visit from his obnoxious sales-rep friend Todd Packer.  The two chauvinistic friends try to prove that the office is not in need of harassment counseling, but only wind up making the situation worse, causing yet another zany day at the office.', 22, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 3, 'Office Olympics', 'While Michael and Dwight are out of the office for the day trying to close a deal on a new condo for Michael, Jim and Pam arrange for the staff to participate in an "Office Olympics," where the workers play strange, invented games (among them, Dunderball, Hate Ball...and Pam Pong) that they usually play while the boss is out.  At the end of the day, the festivities cheer up everyone - even the oblivious Michael.', 22, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 4, 'The Fire', 'The Office is forced into the parking lot for the day when a fire starts in the kitchen. To ease everyone''s boredom, Jim suggests a game of "Desert Island" and "Who Would You Do?", where certain staff members reveal a little too much information about themselves. Throughout the day, Michael talks business with Ryan, leaving Dwight feeling left out.', 22, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 5, 'Halloween', 'While everyone else in the office enjoys the spooky Halloween festivities and talks about the staff''s costumes, Michael ponders who he should fire when the threat of downsizing becomes a reality and his boss orders him to fire one of his staff.  Meanwhile, Jim and Pam put Dwight''s resume on job-searching websites, which may make Michael''s job a little easier, and Pam encourages Jim to set his goals higher by applying for a better job, which makes Jim consider his friendship with Pam.', 22, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 6, 'The Fight', 'When Dwight embarrasses Michael by punching him in the stomach at work, Jim organizes a lunchtime rematch at Dwight''s Dojo. Meanwhile, Pam becomes annoyed at Jim when he gets too physical with her, Ryan updates the emergency contact information on a secret mission, and Michael tantalizes Ryan when the boss gets a hold of Ryan''s cell phone number.', 22, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 7, 'The Client', 'When Michael and Jan try to nail down a potential new client, Christian, by taking him out to Chili''s, Michael surprises everyone with what - or who - he does.  Meanwhile, back at the office, Jim finds a semi-autobiographical script that Michael has written called Threat Level: Midnight, and he, Pam, Kevin, and the rest of the Dunder-Mifflin workers have a great time acting it out. Later that night, Pam and Jim share their first unofficial date, complete with dinner (a sandwich), candlelight, and Dwight''s pathetic fireworks display.', 22, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 8, 'Performance Review', 'Michael meets with all of his underlings to discuss their performance in the office so far. However, Michael focuses more on getting feedback about his relationship with Jan than whether or not the workers are doing their job. Later, a nervous Michael plans to shuffle through the employee suggestion box to steal exciting ideas for his imminent discussion with Jan about his own performance, but that falls apart when Jan asks to sit in on the discussion. Meanwhile, Jim and Pam try to keep Dwight under the wrong impression that the day is Friday instead of Thursday.', 22, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 9, 'Email Surveillance', 'Michael starts monitoring the emails sent out in the Dunder-Mifflin workplace, upsetting the employees. Meanwhile, Pam believes that the relationship between Dwight and Angela is more than just worker to worker, Jim throws an office BBQ at his house in order to show his roommate the kinds of people he deals with everyday, and Michael, after annoying everyone at his improv classes, crashes Jim''s party with a terrible karaoke number.', 23, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 10, 'Christmas Party', 'Michael hosts a Christmas party at the office, but somehow manages to decrease the holiday cheer when he changes the arranged secret Santa pairs to a game of "Yankee Swap", where everyone gives their pre-bought presents to a different, random worker. To boost morale, Michael introduces vodka shots while the others compete for an iPod, Jim hopes that his sentimental present, meant for Pam, doesn''t end up with Dwight, and Angela becomes enraged about Michael''s party changes.', 22, '2005-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 11, 'Booze Cruise', 'Michael takes the entire Dunder-Mifflin staff on a motivational cruise aboard a party boat on Lake Wallenpaupack, but his planned presentation is bogged down by numerous distractions, including a dance contest, limbo, snorkel shots, and the pushy Captain Jack. Also, Jim and Katy''s relationship hits the rocks as Roy and Pam finally set a wedding date, which does more than disappoint Jim, and by the end of the night, Michael''s motivational cruise doesn''t go completely to waste when he shares a heart-to-heart with one of the workers.', 22, '2006-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 12, 'The Injury', 'When Michael burns his foot with his George Foreman mini-grill, he requires the entire office staff to work around his new injury. When the workers aren''t so keen on obliging, Michael gets angry and calls in a man in a wheelchair to put out the message that disabled people are people too. Meanwhile, Dwight acts stranger than usual, acting really nice and helpful towards Pam. It isn''t until the end of the day when everyone realizes that the car accident Dwight was in earlier that day gave him a concussion (but was overshadowed by Michael''s dramatization of his own burn), and Jim and Michael immediately take him to the hospital. Needless to say, Michael doesn''t appreciate the extra attention that the doctors and nurses pay Dwight.', 22, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 13, 'The Secret', 'When Michael slips some sly references about Pam in his conversations with Jim, Jim quickly tries to do damage control to make sure that no one else in the office finds about his crush on Pam, all while slamming himself with regret for ever telling Michael in the first place. Jim goes to drastic measures, even bonding with Michael at a Hooters restaurant for lunch. Nonetheless, Jim''s efforts do little to keep Michael from revealing the secret, but Jim smooths the situation over with Pam to make it seem like nothing more than a tiny crush in the past. Meanwhile, Dwight conducts an investigation about Oscar''s mysterious absence from work, and what Dwight finds, though it goes way over his head, is surprising.', 22, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 14, 'The Carpet', 'When someone soils the carpet in Michael''s office, Michael sees it as a form of hatred towards him and realizes for the first time that not everyone may like him. Due to the odor of his office, Michael temporarily switches workspaces with Jim, and while there, Michael reminisces of his pre-management days, reliving pranks with Dwight that he and Todd Packer played on the staff. Meanwhile, Jim realizes why Kelly sits alone in the back of the office as he plays messenger for a childish flirtation between Kelly and Ryan, and Pam tries to cope with the day without Jim to make her laugh.', 22, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 15, 'Boys and Girls', 'Jan holds a "Women in the Workplace" seminar at Dunder-Mifflin for the paper company''s female employees. Michael, feeling more than a bit left out, decides to have his own "seminar" when he takes the male workers down to the warehouse.', 22, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 16, 'Valentine''s Day', 'The Dunder-Mifflin staffers join in kindergarten-like festivities for Valentine''s Day while Michael heads to New York City for a conference with the corporate heads. After showing the documenters a tour of his favorite city, Michael accidentally lets slip to the others at the conference that he and Jan hooked up, and he finds himself in hot water when Jan and the new CFO of Dunder-Mifflin hear the story. Back in Scranton, Pam becomes irked when she discovers that Roy hasn''t gotten her anything for Valentine''s Day, Dwight struggles to find a gift for Angela, and Kelley talks off Jim''s ear about her rather desperate affections for Ryan, who is less than interested.', 22, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 17, 'Dwight''s Speech', 'Dwight must confront his fear of public speaking when he is named Dunder-Mifflin''s Salesman of the Year. To prepare for a big convention where he is set to give a speech, Dwight turns to Michael to guide him in his quest to conquer the fear. Meanwhile, Pam gets wrapped up with wedding plans, but Jim has plans of a different sort: an escape route out of Dunder-Mifflin and Scranton, at least for long enough so that he doesn''t have to witness Pam''s wedding. While all of this is happening, the staffers battle it out over control of the thermostat.', 22, '2006-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 18, 'Take Your Daughter to Work Day', 'A routine office day is changed when children come to Dunder Mifflin for "Take Your Daughter to Work Day". Michael is surprised when he strikes up a friendship with the five-year old daughter of his sworn enemy, Toby. Pam is desperate to befriend her colleagues'' offspring and a misunderstanding puts Ryan under Stanley''s thumb.', 21, '2006-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 19, 'Michael''s Birthday', 'As Kevin and the rest of the crew worry about Kevin''s medical test results to see whether or not he has skin cancer, Michael gets angry because no one seems to have fun at the birthday party he threw for himself. Later, Michael takes everyone out to the skating rink to get their minds off of Kevin''s possible complications, and Pam and Jim go to the supermarket to pick up some presents for Kevin.', 22, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 20, 'Drug Testing', 'Dwight plays the role of Volunteer Sheriff after finding half a joint in the Dunder Mifflin parking lot leading to an investigation. Pam gives Jim a play challenge where he must be silent until he gives Pam a can of Coke.', 22, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 21, 'Conflict Resolution', 'When Michael takes over conflict resolution duties from HR, chaos ensues at Dunder Mifflin.', 22, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 2), 22, 'Casino Night', 'In the season finale, Dunder-Mifflin holds a Casino Night in the warehouse to benefit charity. While Michael faces the task of juggling two dates, Jim is forced to ponder the reality of transferring to the Stamford branch and what that means for his relationship with Pam.', 29, '2006-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 3, 'Season 3', 'The season marked the move of main character Jim Halpert from Scranton to Stamford, and also introduced Rashida Jones as Karen Filippelli, and Ed Helms as Andy Bernard—both members of Dunder Mifflin Stamford—as recurring characters. The main plot for the early episodes of the season deals with a recurring problem in seasons one and two—the problem of company downsizing—while in the last half of the season, inter-office relationships also became a major plot point.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 1, 'Gay Witch Hunt', 'When Michael unintentionally outs a gay employee, he stumbles through a sensitivity mine-field. Also, we find out what happened with Jim and Pam.', 22, '2006-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 2, 'The Convention', 'Kelly set Pam up on her first date since breaking up with Roy. She was very nervous. Michael tried giving her dating tips and told her she should freak her date out by wearing her wedding dress.', 22, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 3, 'The Coup', 'Michael had made it a point to have Movie Monday every week. He called the office into the conference room to watch a 30-minute installment of Varsity Blues, but Jan made an unexpected visit and did not like what she saw.', 22, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 4, 'Grief Counseling', 'Jim felt awkward at the morning meeting when his boss put him charge of managing Karen and her responsibilities. The other co-workers looked at Jim as a kiss ass. Later on, he flirted with Karen in the break room and told her she shouldn''t work until she found her favorite snack chips.', 22, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 5, 'Initiation', 'Dwight was very excited because he got to take Ryan on his first sales call. He couldn''t wait to show Ryan how the sales are really done. Before that, the men took a little side trip to the Schrute family beet farm. Dwight thought it would be funny to leave Ryan on the farm.', 22, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 6, 'Diwali', 'Michael was educating the entire staff about Diwali, the Hindu holiday that Kelly celebrated. Kelly had invited everybody from work to the celebration. Pam was unsure if she was going to make it, she later confided in Angela that she was saddened because she had nobody to attend the celebration with.', 22, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 7, 'Branch Closing', 'Jan told Michael that the board had voted to close the Scranton branch. There would be a select group of employees that would get a severance package; the others would be going to work at the Stamford branch. She informed Michael that he would be one who would get a severance package.', 31, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 8, 'The Merger', 'The Scranton branch was getting ready for their new employees to arrive in from the defunct Stamford branch. Pam was especially excited to be reunited with Jim. While, Michael was most concerned with impressing his new staff.', 31, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 9, 'The Convict', 'Angela and Kevin were trying to figure out where extra money in the budget came from. Jan let them know it was money Dunder-Mifflin received for hiring an ex-convict. Michael swore he never hired an ex-convict. Jan informed him that the person must have come from the merger.', 22, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 10, 'A Benihana Christmas', 'Michael was in the holiday spirit and couldn''t wait to share in it with his girlfriend, Carol. He had bought two tickets to paradise, hoping to whisk her away on a romantic vacation to Jamaica. Carol came by the office early to have a talk with Michael and it didn''t go well.', 42, '2006-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 11, 'Back from Vacation', 'Karen and Jim had their first big fight in the relationship. Karen had been living in a hotel since taking her job in Scranton. When she decided to live next door to Jim, he took it as the next step to living together and that was too fast. She was not pleased with his response.', 22, '2007-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 12, 'Traveling Salesmen', 'Michael decided to send his employees out into the field for sales calls. He paired himself up with Andy. He let the veterans choose who they wanted their partners to be. Phyllis chose Karen, Stanley chose Ryan and that left Jim and Dwight paired together. This wasn''t the first time Dwight and Jim had done sales calls together.', 22, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 13, 'The Return', 'Since Dwight''s departure, Andy had been clinging to Michael. Andy''s antics had been wearing very thin on his co-workers. In fact, Andy left Jim actually wishing Dwight would come back.', 29, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 14, 'Ben Franklin', 'Michael celebrates Phyllis'' wedding shower by bringing two adult performers into the office, a stripper and Ben Franklin. Meanwhile, Karen confronts Pam about her past history with Jim.', 22, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 15, 'Phyllis'' Wedding', 'It was the day of Phyllis and Bob''s wedding. Pam was upset because she noticed Phyllis had basically stolen Pam''s ideas for her and Roy''s would-be wedding. Meanwhile, Michael was very excited to be in charge of pushing Phyllis''s father''s wheelchair down the aisle.', 22, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 16, 'Business School', 'Roy stopped by Pam''s desk to let her know how excited he was to see her art show. She reminded him that it was just a small show being put on by her art class. Pam later admitted she was very happy she was back together with Roy because it showed maturity. Jim feigns indifference to the reconciliation.', 22, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 17, 'Cocktails', 'Michael was excited to be attending a party at his CFO''s house. He carpooled with Dwight and was also looking forward to meeting Jan at the party. Jan wanted to spend a night alone with Michael, but he thought it was important to come out as a couple to all of their co-workers.', 22, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 18, 'The Negotiation', 'Roy paced in the parking lot outside Dunder-Mifflin and then charged the building looking for Jim. When he spots Jim and rushed him, only to get pepper sprayed in the eyes by Dwight, who managed to spray everybody around him, as well.', 22, '2007-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 19, 'Safety Training', 'Andy was back to work, fresh from anger management training. He insisted on being called Drew, even though Jim continued to call him Andy just to toy with him. Meanwhile, Dwight had decided to shun Andy for the next three years.', 22, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 20, 'Product Recall', 'Michael was in crisis mode at Dunder-Mifflin when a disgruntled employee at the paper mill put an obscene watermark on one of their most popular orders of paper. Michael called the staff into a meeting and pointed the blame on Creed, who was responsible for quality assurance at the paper mill and blew it off.', 22, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 21, 'Women''s Appreciation', 'Phyllis walked into the office looking pale and shocked. A concerned staff surrounded her for comfort. She told them she had been flashed in the parking lot. Jim alerted the police and they already had three other incidents of flashing in the area. Michael didn''t think much of it, because it was Phyllis.', 29, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 22, 'Beach Games', 'Michael was shocked when he received a call from Corporate wanting him to interview for a position. Michael was happy, but he also had other things on his mind. Beach Day was coming up and he was taking the crew out for some fun in the sun. Not before reminding Toby he couldn''t go because somebody had to stay in the office.', 28, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 3), 23, 'The Job', 'After Pam''s outburst at Beach Day, she and Jim had a talk and realized how much they both missed their friendship. Pam never regretted her speech she gave to Jim in front of the rest of the staff; in fact, she was happy that it only took her three years to summon the courage to say what was on her mind.', 43, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 4, 'Season 4', 'Season four marked the departure of Karen Filippelli as a regular character, although she appeared for a few seconds in the first episode, "Fun Run" and in the sixth episode, "Branch Wars", as the regional manager of the Utica branch. Relationships again emerged as the main theme of the season, with Jim Halpert and Pam Beesley''s rising, and Michael Scott and Jan Levinson''s, as well as Dwight Schrute and Angela Martin''s declining. Technology was another prevalent theme as the office staff struggled with initiatives introduced by Ryan Howard to modernize the company.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 1, 'Fun Run', 'Michael comes to believe the office might be cursed in the wake of a freak accident. After scrutinizing each of his staffers'' religious beliefs, he organizes a charity 5K "fun run."', 42, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 2, 'Dunder Mifflin Infinity', 'Ryan returns to Scranton with a plan to bring Dunder Mifflin into the digital age by launching a new website - Dunder Mifflin Infinity. Michael is worried about ageism and attempts to win back clients using old fashion business skills. Relationships are on the forefront as Ryan returns to an eager Kelly, Jim and Pam are outed to the office, and Angela is still upset with Dwight about her cat.', 42, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 3, 'Launch Party', 'Michael gleefully anticipates attending the company''s Web-site launch party in New York. Meanwhile, Angela arranges a bash in Scranton, while Dwight gets wrapped up in a real paper chase: He tries to sell more paper than the Web site.', 42, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 4, 'Money', 'Michael is quickly going into debt with Jan renovating his condo. Meanwhile, it''s a barn burner when Jim and Pam check in to the Schrute family farm, which has been converted into a bed-and-breakfast.', 42, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 5, 'Local Ad', 'Michael was excited to know Dunder Mifflin bought television ad space in local markets, including Scranton. Michael wanted to create the perfect commercial. Only problem was Michael wasn''t seeing eye to eye with guys who were going to be producing the commercial.', 22, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 6, 'Branch Wars', 'Karen was now the regional manager of the Utica branch and used her position of power to woo Stanley to her branch. For the right price, Stanley agreed to make the transfer. In Scranton the news was welcomed with applause, much to Michael''s dismay.', 22, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 7, 'Survivor Man', 'Michael is feeling left out after finding out Ryan took a handful of branch managers and even Toby on a wilderness retreat, but didn''t invite him. In order to get back with nature, Michael asks Jim if he would consider a camping trip together. Hypothetically, Jim answered yes.', 22, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 8, 'The Deposition', 'Michael is driving to New York with Jan where he is going to speak at her deposition. Jan is suing Dunder Mifflin for four million dollars over her wrongful termination. Michael is excited to testify and has memorized every answer Jan told him to.', 22, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 9, 'Dinner Party', 'Michael stages an elaborate plan to finally get Pam and Jim over to his and Jan''s place for a dinner party. Jim gets trapped into it and agrees to go. Dwight overhears and wants his invitation, too. Michael says he only has six wine glasses and with Andy and Angela going too, there''s not enough room for Dwight.', 23, '2008-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 10, 'Chair Model', 'Pam is becoming more and more annoyed with Michael and his indecisiveness about ordering a desk chair. In Michael''s defense, he''s become distracted by his crush on the woman who is modeling the chair in the catalogue. He reminds Pam that since the infamous dinner party, he is now a single man.', 22, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 11, 'Night Out', 'Ryan returns to Scranton but not to a warm welcome. He is making everyone in the branch come in on a Saturday to re-enter data into the new website. Michael makes it clear that Ryan is the reason they have to come in on the weekend. The rest of the staff aren''t happy knowing a computer will be getting credit for all of their sales.', 22, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 12, 'Did I Stutter?', 'Pam is sporting a new look at work with her glasses. She admits she spent the night at a "friend''s" house and forgot her contact solution. Michael makes sure to point out that the glasses make her look ugly, and if she wants to be hot, the glasses need to come off.', 23, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 13, 'Job Fair', 'Jim is wearing his best golfing uniform because he is hitting the links with a potential client, Phil Maguire. This is a very important account for Jim because he needs to look good to Ryan, who recently put him on probation for his job performance. Andy and Kevin are also joining in the game to show their support.', 21, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 4), 14, 'Goodbye Toby', 'Toby leaves Dunder Mifflin, and Michael plans a huge goodbye party... out of joy. Angela refuses to help with it, so Michael turns to Phyllis. Dwight and Meredith harass Holly, their new HR representative.', 42, '2008-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 5, 'Season 5', 'Michael Scott and his fellow Dunder Mifflin-ites steal customers, frame co-workers, and indulge in intra-office love affairs.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 1, 'Weight Loss', 'Michael tries to motivate the Scranton branch to lose weight as part of an interoffice competition. Jim is lost after Pam leaves for art school in New York, and Angela continues to see Dwight even though she is now engaged to Andy.', 42, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 2, 'Business Ethics', 'Holly leads a business ethics seminar as a result of Ryan''s scandal, and when Michael encourages everyone to share their own unethical work behaviors, things get out of hand. Meanwhile, Jim messes with Dwight by requiring him to follow the Dunder Mifflin "Time Theft" policy.', 22, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 3, 'Baby Shower', 'Michael practices for the birth of Jan''s baby by having Dwight go over possible birthing scenarios. Meanwhile, Michael tells Holly that he will pretend to dislike her for Jan''s benefit.', 22, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 4, 'Crime Aid', 'Michael and Holly have sex for the first time, and Michael holds a fund-raiser for the office after it is burglarized. Dwight confides in Phyllis after Andy and Angela set a wedding date, and Jim runs into Pam''s ex-fiancé Roy.', 22, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 5, 'Employee Transfer', 'Pam is embarrassed when she is the only person at corporate wearing a costume on Halloween. Holly and Michael take the long trip to Nashua after they get some shocking news from corporate. Meanwhile, Dwight torments Andy and tries to get under his skin.', 22, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 6, 'Customer Survey', 'Dwight and Jim are shocked when they get the results of the annual customer survey report. Pam and Jim decide they want to spend every minute together using their bluetooth phones. Meanwhile, Angela and Andy pick an unusual location for their wedding.', 22, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 7, 'Business Trip', 'Michael is thrilled when he learns that David Wallace is sending him to Canada for a business trip, and wants to bring both Andy and Oscar with him. Jim misses Pam and he can''t wait until she returns from art school.', 22, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 8, 'Frame Toby', 'A mysterious person in the office has made a huge mess in the microwave and will not clean it up. Meanwhile, Michael has to come to terms with the fact that there have been certain personnel changes in his staff without his knowing.', 22, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 9, 'The Surplus', 'Michael has to spend the office surplus by they end of the day, but he can''t decide between a copier or new chairs. Dwight plays a dirty trick on Angela as they prepare for Andy and Angela''s wedding on the beet farm.', 22, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 10, 'Moroccan Christmas', 'Phyllis'' Moroccan-themed holiday party goes up in flames when Meredith''s hair catches on fire and Michael is forced to deal with the accident. Meanwhile, Dwight corners the market on the hottest toy of the Christmas season.', 22, '2008-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 11, 'The Duel', 'The office is on eggshells because Andy still hasn''t found out about fiancee Angela''s affair with Dwight. When Michael spills the beans, Dwight and Andy take matters into their own hands. Meanwhile, Michael is nervous about being called down to corporate for a meeting with Wallace.', 22, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 12, 'Prince Family Paper', 'Michael and Dwight go undercover to do a bit of industrial espionage on a paper company competitor. Meanwhile, the rest of the office holds a debate to settle the question: is Hilary Swank hot?', 22, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 13, 'Stress Relief', 'Dwight must makes amends with the office after his fire safety seminar goes awry; Michael tries to get his employees to relax; Andy becomes convinced that Pam and Jim are film gurus.', 42, '2009-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 14, 'Lecture Circuit (1)', 'Michael goes on a speaking tour of the other branches to explain Scranton''s relative success, accompanied by his driver, Pam. Back at the office, Dwight and Jim - now heads of the party planning committee - forget a birthday, with severe consequences. Meanwhile, Andy falls for someone he should not.', 22, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 15, 'Lecture Circuit (2)', 'Michael and Pam continue their tour of the branches with Michael taking a lesson from their visit to Utica. Dwight and Jim struggle to fulfill their new party planning duties with a grumpy staff. Angela''s new cat causes a stir.', 22, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 16, 'Blood Drive', 'A mystery woman at the office blood drive catches Michael''s eye. Dwight and Kevin both find women at the "Lonely Hearts Party," while Jim and Pam are forced to leave because of PDAs—so they have lunch with Phyllis and Bob.', 22, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 17, 'Golden Ticket', 'Michael''s idea to use "Golden Tickets" for prizes for clients causes a problem in the office. Kevin seeks advice from Andy, Jim, and Pam about dating.', 22, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 18, 'New Boss', 'Michael has big plans for his 15th anniversary party at Dunder Mifflin, but is in for a shock when the new, no-nonsense Vice President has some ideas of his own. Meanwhile, Jim''s prank on Dwight has some unexpected results.', 22, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 19, 'Two Weeks', 'Michael''s relationship with the new vice president becomes increasingly tense, as Michael finds an excuse to goof off even more than usual. Meanwhile, Pam faces the challenge of a new copier and Kelly develops a crush.', 22, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 20, 'Dream Team', 'The situation between Jim and his new boss Charles gets worse when they are competing in a parking lot soccer game. Michael tries to start his new business, but has trouble leaving his house.', 22, '2009-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 21, 'Michael Scott Paper Company', 'Tension and disillusionment begin to emerge as Michael, Pam, and Ryan move the Michael Scott Paper Company into a cramped "workspace" at the business park.', 22, '2009-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 22, 'Heavy Competition', 'Dwight''s loyalty to Michael is tested when he finds a new hero in Charles. Meanwhile, Andy tries to provide for all of Jim''s emotional needs.', 22, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 23, 'Broke', 'Michael''s new company struggles to make early morning deliveries while the office tries to get their expense reports in on time after Angela enforces Dunder Mifflin''s policy.', 22, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 24, 'Casual Friday', 'Michael has to mediate a dispute within his new sales team. Meanwhile, trouble brews in the office when several employees take the term "casual" Fridays too loosely.', 22, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 25, 'Cafe Disco', 'Michael decides to open a cafe-disco in his old office. Pam and Jim are planning a secret trip.', 22, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 5), 26, 'Company Picnic', 'At the company picnic, Michael and Holly are reunited for the first time since their split. The rest of the staff competes in games, such as the volleyball tournament.', 22, '2009-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 6, 'Season 6', 'In Season 6, the crew faces romances, marriage, parenthood, new corporate ownership, Darryl’s rise to middle management, and a ball-busting new boss.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 1, 'Gossip', 'A few interns who stayed at Dunder-Mifflin over the summer end their internship. Michael announces some potentially damaging gossip about an employee to the rest of the office, then starts to spread false rumours about others to cover up what he has unwittingly revealed.', 23, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 2, 'The Meeting', 'Michael gets worried after a request from Jim, and Pam''s busy with wedding planning. Darryl''s worker''s compensation claim makes Dwight suspicious.', 23, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 3, 'The Promotion', 'David Wallace comes bearing the news that not all the staffers will receive a raise this year. Jim pushes Dwight to the limit and causes him to form office alliances. And Pam decides she wants only cash as a wedding gift.', 23, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 4, 'Niagara', 'The Dunder Mifflin staff head to Niagara Falls for Jim and Pam''s wedding, with the understanding that her pregnancy is a forbidden discussion topic, but Jim''s slip of the tongue prods Michael to attempt damage control.', 45, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 5, 'Mafia', 'Michael becomes convinced that an insurance salesman visiting the office is a part of the mafia, and Dwight and Andy accompany Michael to a meeting with him. Meanwhile, Kevin accidentally cancels Jim''s credit card, while Jim and Pam are on their honeymoon in Puerto Rico.', 23, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 6, 'The Lover', 'Jim and Pam return from their honeymoon and discover that Michael is dating Pam''s mother, which infuriates her. Meanwhile, Dwight tries to install a recording device in Jim''s office, by giving him a wooden mallard as an apology for their long rivalry.', 23, '2009-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 7, 'Koi Pond', 'Michael and Jim head off to a meeting and Michael comes back soaked after having fallen in a koi pond. Meanwhile, Pam and Andy, as the two worst salesmen in the branch, have to go cold calling for sales.', 23, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 8, 'Double Date', 'Jim and Pam finally go on a double date with Michael and Pam''s mother Helene on Helene''s birthday, which takes a dark turn when Michael discovers just how old Helene is turning, and breaks up with her. Meanwhile, Dwight offers to do nice things for all the members of the office so that they will owe him a specific favor, but Andy ruins his plans.', 23, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 9, 'Murder', 'Rumors spread that Dunder Mifflin is in financial trouble, so Michael tries to distract the office by having everyone play a murder mystery game called Belles, Bourbon, and Bullets. Meanwhile, Andy uses the game as a way to ask out Erin, but fears he may have asked out Erin''s character, instead of Erin herself.', 23, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 10, 'Shareholder Meeting', 'Michael speaks out of line at the Dunder Mifflin shareholders meeting and creates a big problem for management, while Jim discovers that nobody in the office thinks he''s the "real" boss.', 23, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 11, 'Scott''s Tots', 'Michael and Erin meet "Scott''s Tots", a group of local teenagers whose college tuition was promised in one of Michael''s grand delusions ten years prior. Meanwhile, in Michael''s absence, Dwight convinces Jim to start an employee-of-the-month program with the intention of sabotaging Jim.', 23, '2009-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 12, 'Secret Santa', 'Michael gets upset when Jim promises Phyllis that she can be the office Santa, but the office Christmas party may be overshadowed by some bad news from David Wallace.', 23, '2009-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 13, 'The Banker', 'A banker representing a potential buyer comes to the Scranton branch to interview the H.R. department before the sale goes through.', 23, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 14, 'Sabre', 'Michael hates the changes that Dunder Mifflin''s new owner is implementing, so he turns to David Wallace for advice. Jim and Pam find the perfect day care center, but Jim''s mistake threatens to ruin the interview.', 23, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 15, 'The Manager and the Salesman', 'Sabre''s CEO wants the Scranton branch to have one manager, and Michael voluntarily steps down and lets Jim become the boss when he finds out that salespeople make more money. However, he soon comes to regret the decision.', 23, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 16, 'The Delivery', 'Pam’s contractions begin but she and Jim are determined to wait it out as long as possible so they can have more time at the hospital. Meanwhile the rest of the office tries to distract Pam from the pain with food and entertainment.', 45, '2010-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 17, 'St. Patrick''s Day', 'Michael thinks he impressed Jo only to discover someone else in the office caught her eye. Meanwhile, Dwight makes trouble on Jim''s first day back from paternity leave. Andy and Erin have an interesting first date.', 23, '2010-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 18, 'New Leads', 'When the sales staff lets Sabre''s new "sales is king" policy get to their heads, Michael hides their new, prized leads.', 23, '2010-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 19, 'Happy Hour', 'Michael gets kicked out of the bar when he pulls out all the stops to impress a friend of Jim and Pam''s. Meanwhile, Andy and Erin do their best to keep their relationship under wraps. Dwight rethinks his pre-natal contract with Angela.', 23, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 20, 'Secretary''s Day', 'Andy pulls out all the stops to give Erin a memorable Secretary''s Day. Michael reluctantly takes Erin out to lunch and lets slip about Andy''s relationship with Angela. Meanwhile, Oscar circulates a video he created that compares Kevin''s voice to Sesame Street''s Cookie Monster.', 23, '2010-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 21, 'Body Language', 'Pam and Jim work on their first sales pitch together to Donna, the manager of a local restaurant. But Michael keeps misreading the signals she''s putting out. Meanwhile, Dwight encourages Kelly to try out for the minority training program.', 23, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 22, 'The Cover-Up', 'Michael suspects Donna is cheating on him and puts P.I. Dwight Schrute on the case. Meanwhile, Andy is frustrated when no one takes his customer''s complaint seriously.', 23, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 23, 'The Chump', 'Michael is surprisingly cheerful after learning some bad news about Donna. The new parents, Pam and Jim, have trouble staying awake in the office. Meanwhile, Angela takes matters into her own hands when Dwight refuses to honor their contract.', 23, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 6), 24, 'Whistleblower', 'The press finds out that Sabre’s printers catch on fire. Jo shows up to the office in hopes of finding out who the whistleblower is. Everyone suspects Andy, who adamantly denies he leaked the information.', 23, '2010-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 7, 'Season 7', 'In Season 7, Dwight is now the owner of the building, Andy is courting Erin, Jim and Pam struggle with being new parents, and past girlfriends haunt Michael.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 1, 'Nepotism', 'Michael refuses to fire the new office assistant after everyone complains about his bad attitude. Andy plays it cool after Erin shows interest in another man. Meanwhile, Pam tries to impress Jim by pulling an office prank of her own.', 23, '2010-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 2, 'Counseling', 'Corporate assigns Michael to counseling with Toby. Dwight vows revenge on the Steamtown Mall after a shop owner snubs him. Meanwhile, Pam conspires to change her job title.', 23, '2010-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 3, 'Andy''s Play', 'Andy invites the entire office to his community theater production of Sweeney Todd in hopes that Erin will attend. Michael tries to put his jealousy aside and enjoy the performance while Jim and Pam struggle with their incompetent babysitter.', 23, '2010-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 4, 'Sex Ed', 'Michael, believing he has herpes, contacts all his ex-girlfriends, including Jan and Holly. Andy tries to play on Erin’s compassionate side by holding a sex education meeting for the office.', 23, '2010-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 5, 'The Sting', 'When a competing sales associate steals a Dunder Mifflin client, Michael, Jim and Dwight decide to set up a sting to find out his sales secrets. Andy decides to start a band after finding out a friend from college has a successful music career.', 23, '2010-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 6, 'Costume Contest', 'When Darryl takes an idea to corporate over his head, Michael freaks out. Everyone in the office is in a competitive mood as the Halloween costume contest gets underway. Meanwhile, Pam tries to get the truth out of Danny about their dating history.', 23, '2010-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 7, 'Christening', 'Pam and Jim prepare for Cece''s baptism. When Cece goes missing, Jim fears Angela has taken her.', 23, '2010-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 8, 'Viewing Party', 'An ostracized Michael does all he can to sabotage Gabe''s party while Angela requests sex from Dwight.', 23, '2010-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 9, 'WUPHF.com', 'Michael tries to save Ryan''s company by encouraging co-workers to invest. Meanwhile, Dwight has big plans for the office at Thanksgiving.', 23, '2010-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 10, 'China', 'After reading an article about China growing as a global power, Michael decides China must be stopped before they take over the US. Everyone in the office complains about Dwight''s building standards and Pam threatens to move Dunder Mifflin to a new building.', 23, '2010-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 11, 'Classy Christmas', 'Michael could not be happier when Toby has to take a leave of absence and corporate sends Holly Flax to cover for him. Pam is forced to do a second Christmas party after Michael wants the party to be on the day Holly returns to Scranton. Meanwhile, Jim regrets agreeing to a snowball fight with Dwight.', 45, '2010-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 12, 'Ultimatum', 'Michael prepares himself for the good or bad news about Holly and her boyfriend. In an effort to be an "awesome" office manager, Pam decides to put up a resolution board for everyone to post their New Year''s resolutions.', 23, '2011-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 13, 'The Seminar', 'Holly and Michael turn Andy''s business seminar into an improv challenge. Erin and Gabe compete in a board game battle.', 23, '2011-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 14, 'The Search', 'An emergency call from Helene forces Jim to abandon Michael at a gas station restroom, and Holly, Erin, and Dwight set out to rescue him. Gabe becomes offended at submissions to caption Pam''s latest work of art.', 23, '2011-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 15, 'PDA', 'The staff grows increasingly uncomfortable with Michael and Holly''s PDAs. Jim and Pam regret a champagne luncheon. Andy horns in on a romantic treasure hunt Gabe arranged for Erin.', 23, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 16, 'Threat Level Midnight', 'Michael screens his action film Threat Level Midnight to the office after eleven years of writing, shooting, re-shooting, and editing. The film features Michael as Agent Michael Scarn, Dwight as Scarn''s sidekick, and Jim as archnemesis "Goldenface," as well as several people from Michael''s past.', 23, '2011-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 17, 'Todd Packer', 'Traveling salesman Todd Packer comes to Dunder Mifflin looking for a desk job in the office. However, the office is unsure if they want him to work there due to his previous behavior. After dealing with computer problems, Andy confronts office administrator Pam to get a new computer.', 23, '2011-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 18, 'Garage Sale', 'The office holds a garage sale in the warehouse. Michael decides to propose to Holly, and runs into trouble thinking of how to do it well.', 23, '2011-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 19, 'Training Day', 'The new manager, Deangelo Vickers, has everyone hoping to make good first impressions: Andy finds himself awkwardly typecast while Jim and Pam worry that they''ve come on too strong. Only Dwight is apathetic about the new leader.', 23, '2011-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 20, 'Michael''s Last Dundies', 'Michael trains Deangelo to take over his job of hosting the Dundie Awards, while Erin struggles with her dislike for her boyfriend, Gabe.', 23, '2011-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 21, 'Goodbye, Michael', 'Michael wants to have a drama-free day at work on his last day before moving to Colorado. Meanwhile, Deangelo Vickers and Andy Bernard scramble to retain Michael''s biggest clients.', 37, '2011-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 22, 'The Inner Circle', 'When Deangelo plays favorites, his management style is exposed.', 23, '2011-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 23, 'Dwight K. Schrute, (Acting) Manager', 'Dwight takes charge of the office and immediately imposes his will on the staff. Gabe hopes to get back together with Erin.', 23, '2011-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 7), 24, 'Search Committee', 'Deangelo''s new replacement is sought out through a search committee process led by Jim.', 44, '2011-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 8, 'Season 8', 'The eighth season largely centers around Andy Bernard''s ascension to regional manager, as well as the antics of Robert California, the new CEO of Sabre, a fictional printer company that owns Dunder Mifflin. Halfway through the season, Dwight Schrute —along with Jim Halpert, Stanley Hudson, Ryan Howard, Erin Hannon, and Cathy —travel to Florida to help set up a Sabre Store, where Nellie Bertram is introduced.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 1, 'The List', 'Robert California stops by for the first time as CEO and leaves behind a mysterious list that has a line down the middle and every member of the office on either one side or the other. The office members frantically try to figure out what it means. Meanwhile, the new manager Andy faces a crisis.', 23, '2011-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 2, 'The Incentive', 'After Robert California challenges the Dunder Mifflin staffers to double their sales, Andy, taking matters into his own hands, creates an incentive program. Eventually, he promises to tattoo himself if the staff doubles their sales. Meanwhile, Pam strikes up an unlikely friendship with Angela, both of whom are pregnant.', 23, '2011-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 3, 'Lotto', 'The entire warehouse staff quits after winning the lotto, leaving Andy and Darryl to scramble for replacements while several of the office workers get a taste of the warehouse life.', 23, '2011-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 4, 'Garden Party', 'Andy plants the seeds of trying to impress Robert California by throwing a garden party at Schrute Farms. Andy''s parents and brother also attend the event, only to make him feel awkward.', 23, '2011-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 5, 'Spooked', 'Erin works to make a spooky, non-childish Halloween party with help from Gabe. Dwight becomes friends with Robert''s son, and Pam and Jim debate the existence of ghosts. Meanwhile, Robert tries to figure out everyone''s deepest fears.', 23, '2011-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 6, 'Doomsday', 'Dwight installs a Doomsday device that will fire all of the employees and effectively close down the branch if they make too many mistakes. Meanwhile, Gabe attempts to court the new warehouse worker, Val.', 23, '2011-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 7, 'Pam''s Replacement', 'Pam trains an attractive temporary worker to take her place while she is on maternity leave, and enlists Dwight''s support when she tries to show that Jim finds her replacement attractive. Meanwhile, Robert California surprises Andy, Kevin, and Darryl when he requests to join their band.', 23, '2011-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 8, 'Gettysburg', 'Andy takes some of the office staff on a field trip to Gettysburg for inspiration. Meanwhile, the rest of the office, under orders from Robert California, are tasked with coming up with a new business idea for Dunder Mifflin. Kevin proposes several ideas that catch California''s attention, although they are rather idiotic.', 23, '2011-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 9, 'Mrs. California', 'Robert California brings his wife into the office for a job, and tells Andy behind her back not to give her one which turns disastrous. Meanwhile, Dwight opens a gym in the building and tries to get Darryl to join it.', 23, '2011-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 10, 'Christmas Wishes', 'Andy attempts to make everyone''s Christmas wishes come true, including those of a drunken Erin. Meanwhile, Dwight and Jim are entangled in an escalating prank war wherein one attempts to frame the other.', 23, '2011-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 11, 'Trivia', 'Pressed to boost the bottom line, Andy finds a novel way to improve sales, while Dwight explores corporate opportunities outside Scranton.', 23, '2012-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 12, 'Pool Party', 'After Robert decides to sell his mansion following his divorce, Kevin suggests that he have an office pool party. Erin tries to make Andy jealous by flirting with Dwight. Meanwhile, Robert gives everyone a tour of his massive home.', 23, '2012-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 13, 'Jury Duty', 'Jim returns from jury duty, only to have to deal with Dwight''s pesky questions about the details of the case. Elsewhere, Angela and her senator beau welcome their baby.', 23, '2012-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 14, 'Special Project', 'Dwight scores a special assignment at Sabre''s Florida headquarters. As a result, he and Andy must decide which Scranton staffers will join him. Elsewhere, Pam returns from maternity leave.', 23, '2012-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 15, 'Tallahassee', 'Dwight arrives in Tallahassee with his team and sets out to win over the president of Sabre''s special projects. Back in Scranton, Andy fills in for reception and enjoys himself.', 23, '2012-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 16, 'After Hours', 'A power play unfolds in Tallahassee when Dwight and Todd Packer compete to become Nellie''s vice president. Meanwhile, Jim receives an unwelcome visitor, and Andy forces the Scranton staffers to work late.', 23, '2012-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 17, 'Test the Store', 'The Florida contingent puts the final touches on the new Sabre store, with Dwight preparing a theatrical presentation in his continuing bid to impress Nellie. Back in Scranton, a red-faced Andy arrives at work with a humiliating injury.', 23, '2012-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 18, 'Last Day in Florida', 'Jim comes to Dwight''s rescue when Robert slams the plan for the Sabre Store concept. Andy discovers Erin doesn''t plan to return to Scranton.', 23, '2012-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 19, 'Get the Girl', 'Andy makes a game-changing decision and takes a road-trip odyssey in the name of romance. Elsewhere, Nellie arrives at the Scranton branch and sets out to seize the manager position.', 23, '2012-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 20, 'Welcome Party', 'Robert California forces the office to throw a welcome party for Nellie, but the Party Planning Committee works on ways to sabotage it. Meanwhile, Erin tries to help Andy figure out a way to break up with Jessica.', 23, '2012-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 21, 'Angry Andy', 'Andy returns to the office to find Nellie in the manager''s chair. Meanwhile, Kelly struggles to choose between Ryan and a new man.', 23, '2012-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 22, 'Fundraiser', 'Unemployed Andy crashes a fundraiser for the Senator and winds up adopting twelve disabled dogs. Dwight discovers that winning an auction means losing money, and Darryl teaches Nellie how to eat a taco.', 23, '2012-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 23, 'Turf War', 'Andy takes a break from flambéing cherries and composing rock operas to jumpstart his Dunder Mifflin comeback. When Robert drunkenly shuts down a nearby branch, Jim and Dwight join forces to outsmart a salesman from Scranton’s uglier sister city.', 23, '2012-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 8), 24, 'Free Family Portrait Studio', 'Dwight offers free family portraits, and a stolen diaper leads to a high-speed car chase. With help from David Wallace, Andy goes undercover to try to get his job back. A new business opportunity arises for Robert California.', 23, '2012-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')), 9, 'Season 9', 'In Season 9, Andy finds his true calling in showbiz, Jim lands the job of his dreams, Erin struggles with love, and Angela''s marriage isn’t what it seems.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 1, 'New Guys', 'Two new, young employees throw Dwight and Jim off balance; Andy returns from leadership training with a desire for revenge.', 23, '2012-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 2, 'Roy''s Wedding', 'A toast at Roy''s wedding leads to Pam and Jim searching their relationships for buried secrets; Dwight reacts to Nellie''s mandatory charity initiative.', 23, '2012-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 3, 'Andy''s Ancestry', 'Andy flaunts his genealogy when he discovers he''s related to Michelle Obama. Meanwhile, Darryl struggles in his new post, Dwight teaches Erin a new language to wow her boyfriend''s family, and Nellie tries to persuade Pam that Jim''s having an affair.', 23, '2012-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 4, 'Work Bus', 'The staffers hit the road in a rented bus when the building is deemed unsafe. Meanwhile, Nellie reaches out to Andy for help in adopting a baby, and Jim uses pie to spread cheer to Pam.', 22, '2012-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 5, 'Here Comes Treble', 'It''s Halloween in the office and Andy invites his college a cappella group to perform, which leads to a confrontation with his frenemy Broccoli Rob. Meanwhile, Dwight finds evidence that a madman is loose in the office and tries to track him down, and the first meeting of Jim''s new job causes a fight with Pam.', 23, '2012-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 6, 'The Boat', 'Money problems plague Andy''s family. Meanwhile, Dwight guests on a local radio show, so the staffers harass him with outrageous phone calls, and Kevin unearths a big secret about Oscar.', 23, '2012-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 7, 'The Whale', 'The women of the office try to teach Dwight how to interact with female clients; Angela suspects the senator of cheating; Toby convinces some of the guys to grow mustaches.', 23, '2012-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 8, 'The Target', 'Angela goes to Dwight for help when she learns that her husband is having an affair. Stanley and Phyllis take advantage of Jim when he needs a favor, and Pete distracts Pam as she begins painting her mural.', 23, '2012-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 9, 'Dwight Christmas', 'When the party planning committee drops the ball on the annual Christmas party, Dwight gets everyone to celebrate with a traditional Schrute German Christmas. Darryl fears that Jim has forgotten to include him in the new job in Philadelphia. Pete teaches Erin about his favorite movie, Die Hard.', 22, '2012-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 10, 'Lice', 'Pam accidentally brings lice into the office and lets Meredith take the fall, while Dwight vows to destroy the parasites. Meanwhile, Jim has a fantastic day in Philly wooing a potential business associate. Meanwhile, Phyllis, Nellie and Kevin meddle in Darryl''s love life.', 23, '2013-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 11, 'Suit Warehouse', 'Clark brings an espresso maker to the office. Dwight and Clark pretend to be a father-and-son to land a sale. Darryl goes on an interview at Jim''s company, where Pam drops by unexpectedly.', 22, '2013-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 12, 'Customer Loyalty', 'Dwight tries to stop Darryl from moving to Jim''s start-up company. Jim misses his daughter''s first recital, to Pam''s dismay. Nellie spills the beans about Pete and Erin.', 23, '2013-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 13, 'Junior Salesman', 'Dwight is tasked with hiring a part-time salesman to be Jim''s substitute, so he rounds up a supergroup of his cronies, including his oddball beet-farmer cousin, Mose. Pam is left wondering who her new deskmate will be. Erin seeks her birth parents with help from Pete.', 23, '2013-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 14, 'Vandalism', 'Pam’s warehouse mural is defaced. Darryl has difficulty dealing with the Jim''s cleanliness habits in their apartment. Angela grudgingly allows Oscar and Kevin to attend her son’s first birthday party.', 23, '2013-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 15, 'Couples Discount', 'The staffers pair up as faux couples to score a Valentine''s Day discount at a mall. Erin tells Pete that she''ll break up with Andy when he returns, but Pete has his doubts. Jim and Pam socialize with the documentary''s soundman.', 22, '2013-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 16, 'Moving On', 'Pam interviews for a job in Philadelphia, but her potential manager reminds her of her former boss, Michael Scott. Dwight acquires the help of Angela in order to give his elderly Aunt Shirley a bath. Meanwhile, Andy attempts to make Pete and Erin feel uncomfortable.', 45, '2013-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 17, 'The Farm', 'The adventures of Dwight at his family beet farm and bed-and-breakfast come to light. Here, he and his siblings receive a surprise inheritance. Back at the office, Todd Packer tries to atone for a lifetime of boorish behavior.', 23, '2013-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 18, 'Promos', 'Everyone in the office is excited when promos start running on TV for the documentary. Dwight makes Angela jealous when he starts dating a brussel sprout farmer. Meanwhile Jim has a big meeting with Major League baseball player, Ryan Howard.', 23, '2013-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 19, 'Stairmageddon', 'The elevator goes out at the office, forcing everyone to use the stairs. Dwight forces Stanley to make a sales call. Pam and Jim talk to Nellie and Toby about relationship problems. Angela supports her man.', 22, '2013-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 20, 'Paper Airplane', 'Dwight and Angela participate in a paper airplane contest and compete against each other. Meanwhile, Andy prepares for a potential acting job, and Jim and Pam utilize new skills.', 23, '2013-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 21, 'Livin'' the Dream', 'Dwight becomes regional manager after Andy quits his job, Jim dedicates more time to his Dunder Mifflin job to save his marriage, and Angela has problems with her new living arrangements after her breakup with The Senator.', 44, '2013-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 22, 'A.A.R.M.', 'Jim convinces Dwight that he needs to choose someone to act as an Assistant to the Assistant Regional Manager; the two subsequently hold tryouts for the position. After her daycare turns away her child, Angela is forced to bring her kid to work. Andy auditions for "The Next Great A Cappella Sensation".', 45, '2013-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0386676')) AND numero_temporada = 9), 23, 'Finale', 'One year later, Dunder Mifflin employees past and present reunite for a panel discussion about the documentary and to attend Dwight and Angela''s wedding.', 45, '2013-05-16');
