INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0389564', 'The 4400', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0676671'), 'SERIE', 'As the reappearance of 4,400 missing persons on a single day confounds the global community, federal agents on the case slowly discover the ways in which the victims have been changed.', '2004-01-01', 'https://m.media-amazon.com/images/M/MV5BNjU5NDgxYmEtZjgzMy00Nzc1LWE5ZDMtZjFhMzZlNTFjZjdlXkEyXkFqcGc@._V1_.jpg');
