INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')), 1, 'Season 1', 'During the past century, thousands of people have gone missing. When 4400 of them return all at once unharmed and looking the same as when they disappeared, the government investigates, unsure of how this can be possible. What the government does not know is that the presence of these 4400 will change the human race in many unexpected ways.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 1), 1, 'Pilot', '4400 people, assumed to be dead or missing over the past fifty years, reappear in a ball of light. None have any memory of where they''ve been, and some are manifesting paranormal abilities.', 85, '2004-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 1), 2, 'The New & Improved Carl Morrissey', 'Tom and Diana investigate a 4400 who has used his ability of enhanced reflexes to become a vigilante.', 42, '2004-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 1), 3, 'Becoming', 'Tom and Diana investigate Oliver Knox, a 4400 suspected of being a serial murderer.', 42, '2004-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 1), 4, 'Trial by Fire', 'NTAC races against the clock to stop a group of fanatics targeting 4400s.', 42, '2004-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 1), 5, 'White Light', 'Diana helps Tom break Kyle out of NTAC quarantine, eventually leading them to discover the truth behind the 4400.', 42, '2004-08-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')), 2, 'Season 2', 'Over one year ago, thousands of missing people returned. Slowly, they begin to manifest strange powers - to heal and to destroy, to alter the present and to perceive the future. As it becomes clear that their gifts could reshape the world, the struggle for control begins. Who will decide the fate of humanity?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 1, 'Wake Up Call (1)', 'Tom and Diana investigate a mysterious structure being built at a psychiatric hospital, based on the drawings of one of their patients who''s a 4400.', 42, '2005-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 2, 'Wake Up Call (2)', 'Richard must protect his family when he and Lily are discovered to be 4400s.', 42, '2005-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 3, 'Voices Carry', 'A returnee exhibiting telepathic abilities seeks help from NTAC, but is instead used as a mole to infiltrate Jordan Collier''s 4400 Center.', 42, '2005-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 4, 'Weight of the World', 'Tom and Diana investigate a 4400 whose ability to increase the human bodies'' metabolism just may be this weight-conscious world''s answer to the ultimate fat-burner.', 42, '2005-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 5, 'Suffer the Children', 'Tom and Diana investigate a 4400 junior high school teacher accused of child abuse.', 42, '2005-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 6, 'As Fate Would Have It', 'A morbid premonition from Maia threatens the future of the 4400 Center.', 42, '2005-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 7, 'Life Interrupted', 'Tom finds himself in a world where the 4400 never happened.', 42, '2005-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 8, 'Carrier', 'After living for 8 years in an alternate world that only Tom and Alana remember the world with the 4400 has returned as it was at the second the 8 years started. A 30 year old 4400 woman wakes up and finds everybody else in her local community dead. Maia puts April''s love for her to a test.', 42, '2005-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 9, 'Rebirth', 'A 4400 with the ability to repair damaged chromosomes hides a shocking past. And while Richard seeks out a tormentor among his Korean War buddies, Shawn reconnects with his family and tries to help Kyle.', 42, '2005-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 10, 'Hidden', 'NTAC is keen to find Jordan Collier''s killer as Tom is desperate to find Kyle.', 42, '2005-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 11, 'Lockdown', 'A 4400 terrorist releases a signal at NTAC that makes the men violent, forcing a lockdown of the facility. Lilly questions how the Centre is handling her daughter, and Shawn tries to recruit a familiar face.', 42, '2005-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 12, 'The Fifth Page', 'When 4400s around the world come down with life-threatening illnesses, Ryland comes back to NTAC and orders the sick - and even unaffected 4400s - to be quarantined. Tom and Diana race to find a cure and discover a shocking secret in the process.', 42, '2005-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 2), 13, 'Mommy''s Bosses', 'Discovering that NTAC is behind the disease plaguing the 4400s, Tom and Diana try to get to the bottom of NTAC''s cover-up, while Kyle considers turning himself in.', 42, '2005-08-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')), 3, 'Season 3', 'The third season continues exploring the travails of the 4400 people who all at once returned in a ball of light to Earth; though the returnees had not aged physically, many of them reappeared with dramatic abilities ranging from enhanced reflexes to precognition.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 1, 'The New World (1)', 'Ryland and other government officials are on trial for withholding vital information that they discovered about the returnees when a disturbing sound is heard the courtroom. Tom and Diana, with the help of Gary Navarro, try and track down T.J Kim, who they believe is responsible for the piercing sound heard in the courtroom. Richard and Lily are forced to deal with a now grown Isabelle While Lily also suffers from a rapid aging disease that Shawn is unable to heal. Tom and Diana also investigate a radical organisation called the Nova Group that appears to have ties with Shawn and the 4400 Center.', 42, '2006-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 2, 'The New World (2)', 'Gary Navarro is arrested for the second attempt to assassinate Dennis Ryland.  Knowing she is the key to her mother''s survival, Isabelle attempts to kill herself by jumping off the 4400 center building only to survive without a scratch. Matthew Ross expresses his displeasure at her actions and tells her of the destiny she is to face.  Isabelle is troubled about what Matthew told her, but after a discussion with Shawn she decides it''s her choice with what she does with her life. Matthew  gives Isabelle a substance that can kill her if it''s injected.', 42, '2006-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 3, 'Being Tom Baldwin', 'Tom is accused of murdering TJ Kim. 17 year old Boyd Gelder has the ability to change his appearance whenever he chooses. Meanwhile, Shawn and Isabelle grow closer.', 42, '2006-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 4, 'Gone (1)', 'Someone is targeting young 4400''s and Maia gets kidnapped. A mistake from Shawn''s past comes back to haunt him. Richard is given a position of authority at the 4400 Center.', 42, '2006-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 5, 'Gone (2)', 'Tom and Diana continue to investigate the disappearance of the 4400 children. Isabelle and Shawn''s relationship becomes public.', 42, '2006-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 6, 'Graduation Day', 'Isabelle seeks revenge on the Nova Group after they attack Shawn. Alana confronts the man responsible for killing her husband and son in a car accident nine years ago.', 42, '2006-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 7, 'The Home Front', 'With the help of Dennis Ryland, NTAC track down the remining members of the NOVA group. Nikki pays Shawn a visit.', 42, '2006-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 8, 'Blink', 'Tom and Diana are drugged with a hallucinogen, that was created from oil that was secreted from the hands of a 4400.', 42, '2006-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 9, 'The Ballad of Kevin and Tess', 'Kevin is on the run after horribly mutating due to the promicin experiments. Tom and Diana go to Tess for help. Diana gets what she believes is the flu and discovers something startling.', 42, '2006-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 10, 'The Starzl Mutation', 'Tom and Diana''s investigation into a series of gruesome murders leads them to uncover another conspiracy within the government. At the 4400 Center, Shawn receives a gift from another returnee that allows him to see his future.', 42, '2006-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 11, 'The Gospel According to Collier', 'NTAC and the 4400 Center work together to find Jordan Collier. Kyle Baldwin gets a surprising visitor at the state prison.', 42, '2006-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 12, 'Terrible Swift Sword', 'NOVA group members that were in the custody of NTAC escape from jail with outside help from Jordan Collier. Diana tells April about her relationship with Ben. Shawn and Richard learn that Isabelle is working with Dennis Ryland.', 42, '2006-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 3), 13, 'Fifty–Fifty', 'Tom and Diana continue their investigation on Jordan Collier''s plan for mankind. Dennis Ryland rejoins NTAC. Isabelle prepares for battle.', 42, '2006-08-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')), 4, 'Season 4', 'Season four continues the incredible story of the 4400. Old adversaries become new allies, and family ties are strained to the breaking point in the battle over promicin. Can the 4400 lead mankind into a new world, or will the forces working against them spell the end for their kind?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 1, 'The Wrath of Graham', 'A high school student develops an ability after injecting promicin. Tom visits Isabelle in jail, while Diana searches for her missing sister. Following the advice of a young woman, named Cassie, Kyle is able to wake Shawn from his coma. Jordan Collier''s conscience gets to him. Meanwhile, NTAC gets a new director.', 42, '2007-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 2, 'Fear Itself', 'Tom and Diana search for someone who has the ability to make people''s worst fears come true. Danny seeks Shawn''s help to find a promicin shot. Meanwhile, Cassie leads Kyle to a book that contains a prophecy about Jordan Collier.', 42, '2007-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 3, 'Audrey Parker''s Come and Gone', 'Audrey Parker, an elderly woman, takes promicin and develops the ability to astral project. Meanwhile, Shawn decides to start publicly healing people again despite threats from the government to shut him down. And Ben and Maia return to Seattle to visit Diana.', 42, '2007-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 4, 'The Truth and Nothing But the Truth', 'Diana locates her sister, April, who took promicin and developed an ability that puts her life in jeopardy.', 42, '2007-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 5, 'Try The Pie', 'Tom tracks Jordan to a small town, where he meets a woman who can relieve people''s stress by talking to them. Meanwhile, Marco and Diana have a nice talk. Maia''s visions are giving her nightmares.', 42, '2007-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 6, 'The Marked', 'Jordan wants Shawn to rejoin the movement. Meanwhile, a 4400 with an amazing ability disappears.', 42, '2007-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 7, 'Till We Have Built Jerusalem', 'Jordan Collier''s movement takes a huge step forward when his followers settle in the heart of Seattle.', 42, '2007-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 8, 'No Exit', 'Tom, Diana, Jordan, Shawn, Kyle, Isabelle, Maia, Meghan, Marco, PJ and Brady all wake up inside NTAC without any memory of how they got there.', 42, '2007-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 9, 'Daddy''s Little Girl', 'Richard surprises Isabelle when he shows up in Promise City but the happy reunion takes a turn when Richard kidnaps her in hopes to start a new life with his daughter.', 42, '2007-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 10, 'One of Us', 'Tom has trouble focusing on the hunt for Richard Tyler because of dreams he''s having about the future.', 42, '2007-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 11, 'Ghost in the Machine', 'Tom and Diana must race to find the source of a computer virus that could bring down Ubient software, one of the world''s largest software companies that is run by suspected member of the marked, Drew Imroth. Meanwhile, Maia visits Promise City where she receives an unexpected birthday surprise: a visit from her birth parents.', 42, '2007-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 12, 'Tiny Machines', 'Meghan and Diana learn how to remove the entity from Tom, but the procedure is dangerous. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0389564')) AND numero_temporada = 4), 13, 'The Great Leap Forward', 'Paramedics try to resuscitate Susan Farrell. They believe that she took promicin and lost the 50/50 lotto that comes with it. Danny is certain that she did not take the shot. After arriving at the hospital with the paramedics, things get complicated as everyone around Danny start to die. Garrity and another NTAC agent are sent to the hospital to assess the situation.', 42, '2007-09-16');
