INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')), 1, 'Season 1', 'The privileged prep school teens on Manhattan’s Upper East Side first learn that notorious party girl Serena Van Der Woodsen is back in town the way they learn all the important news in their lives–from the blog of the all-knowing albeit ultra-secretive Gossip Girl. Serena’s closest friend, Blair, is just as surprised as everyone else to find that Serena has suddenly ended her self-imposed exile to boarding school and returned to Manhattan. The tension between Blair and Serena isn’t lost on Gossip Girl, who is determined to uncover and fuel any and all scandals. Does it involve Serena’s younger brother Eric, Blair’s boyfriend Nate or Nate’s buddy Chuck?  Maybe it has something to do with Dan and his sister Jenny, whose middle-class background keeps them on the fringes of this exclusive clique who live for fashion, shopping and partying–along with gossip.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 1, 'Pilot', '"It girl" Serena van der Woodsen has returned to Manhattan after a mysterious and self-imposed exile to boarding school. Serena''s best friend, Blair Waldorf, has conflicted feelings about her friend''s return since she has enjoyed being the Queen Bee during Serena''s absence and might not be ready to relinquish her new position on the social ladder, not to mention the fact that she has always suspected there may be unspoken feelings between Serena and her longtime boyfriend, Nate.', 43, '2007-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 2, 'The Wild Brunch', 'It''s the day right after the Kiss on the Lips party and Serena receives a cold reception from her former best friend Blair. Blair reveals that she knows that Serena and Nate slept together, before Serena mysteriously went to boarding school. Then Serena decides to take Dan to Chuck''s fundraiser brunch at The Palace. Meanwhile little Jenny asks Blair for advice, and Blair realizes that she maybe gains something by allowing Jenny into her inner circle.', 37, '2007-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 3, 'Poison Ivy', 'It''s Ivy week for the Upper East Side teens of Constance Billiard and St. Jude''s and the visiting representatives'' arrival brings more than just college applications. Cut-throat rivalry is at its sharpest this week as the students compete for prestigious positions. Blair discovers a shocking but juicy secret about Serena and plots to drop the bomb at the best possible moment. Dan is sure that landing the coveted usher position with the Dartmouth rep will either make or break his future at the school. Unfortunately, it''s Nate who nabs the position, despite total disinterest in the school. Meanwhile, Jenny gets closer to Serena''s younger brother Eric and Rufus asks Lily for a favor.', 40, '2007-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 4, 'Bad News Blair', 'Blair gets excited when her mother, Eleanor, chooses her to be the new face of her clothing line. However, Blair''s happiness turns quickly into feelings of betrayal and jealousy when Serena takes her spotlight and Blair finds herself back in Serena''s shadow. Meanwhile, Serena and Dan remember once again that they come from two very different worlds. Also, Nate and Chuck do a boys weekend to blow off steam after Ivy Week ends.', 41, '2007-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 5, 'Dare Devil', 'It''s their first official date and Dan tries to impress Serena with an elaborate plan for the date, but fails to understand that Serena is happier with beer than champagne. That same night Jenny is invited to the infamous Blair Waldorf sleepover and finds herself in a high stakes game of "Truth or Dare". Meanwhile, Lily finds out that Erik is missing from the treatment center, and she finds herself seeking help from her ex-boyfriend, Rufus.', 39, '2007-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 6, 'The Handmaiden''s Tale', 'Dan finds himself between two girls when his childhood friend, Vanessa, returns to N.Y. and declares her feelings for him, just as he and Serena are trying to figure out what they mean to each other. At the masked ball, Blair sends Nate on a scavenger hunt, but Nate is distracted by his feelings for Serena. Although Blair said that outsiders were not welcome to the party, a disguised Jenny and Dan sneak into the ball. Finally, Lily asks Rufus to accompany her to an Eleanor Waldorf event only to make Bart Bass jealous.', 42, '2007-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 7, 'Victor, Victrola', 'Serena and Dan finally accept that they are crazy about each other, despite that they come from polar opposite worlds. Chuck thinks of investing in a club trying to make his father Bart Bass proud of him. Nate confronts his father, about the drugs he found in his house but he denies having a problem. Jenny discovers a secret that her parents have been keeping from her. Finally, Blair is devastated by Nate''s actions when Jenny reveals that Nate kissed her by accident thinking she was Serena.', 41, '2007-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 8, 'Seventeen Candles', 'Blair is feeling heartbroken and guilty by the current state of her relationship with Nate and her recent indiscretion. But she manages to put on a happy face for her 17th birthday party and attempts to hide her feelings from her friends. Hoping that Serena and Vanessa can bond, Dan takes Vanessa to Blair''s birthday party. Jenny brings her mother home as a surprise, but Rufus isn''t ready to forgive and forget. Finally, Nate''s parents ask him to make a huge sacrifice to save his father''s business.', 39, '2007-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 9, 'Blair Waldorf Must Pie!', 'Dan invites Serena and her family to spend the holiday with his family, creating an uncomfortable situation for Rufus and Lily. The children are unaware of their complicated romantic past. Meanwhile, Blair''s freaks out when she learns that her father isn''t coming home for Thanksgiving. Nate spends the holiday with his family, but their awkward dinner quickly goes from bad to worse.', 41, '2007-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 10, 'Hi, Society', 'Serena''s grandmother announces that Serena has to go to Debutante Ball. However, Dan is not what CeCe wants as an escort for Serena, and she makes her opinion heard loud and clear, causing a rift between Serena and Dan. Although they are officially broken up, Nate asks Blair to go to the ball with him. A jealous Nate begins to suspect that Blair is seeing someone else. Jenny finds herself having to make the decision of either attending her mother''s art opening or following her dreams to the Debutante Ball, even though her parents don''t want her to go.', 41, '2007-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 11, 'Roman Holiday', 'Blair''s father, Harold, comes home for the holidays with an unexpected guest. Blair cannot hide her disappointment and makes a plan to get rid of Roman forever. Jenny and Vanessa help Serena get the best Christmas present ever for Dan, who has a surprise of his own for Serena. Rufus refuses to remain the understanding husband any longer after Alison''s former lover sends a letter to the house.', 42, '2007-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 12, 'School Lies', 'Serena, Blair, Nate, Chuck and their class break into the school swimming pool for a night of fun, but when someone nearly dies, the school threatens to expel the person responsible for the break-in. Everyone agrees to not say anything, but this creates major problems between Serena and Dan. Vanessa, while working on a documentary project about private schools, accidentally captures Blair and Chuck discussing their affair. Lily tries to tell Rufus how she really feels about him.', 42, '2008-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 13, 'The Thin Line Between Chuck and Nate', 'Gossip Girl reports that Serena van der Woodsen was seen buying pregnancy tests. Of course, on the Upper East Side, the truth is often even juicier and more scandalous than the gossip. Nate finds out about Blair and Chuck''s affair. And when everyone else finds out what happened Blair''s life comes crashing down. Meanwhile, Dan struggles to tell Serena those three special words.', 42, '2008-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 14, 'The Blair Bitch Project', 'Having been recently dethroned as Queen Bee, Blair returns to school with the support of Serena to find she is still on the outs with her old friends. Dan visits his mother over spring break, and when he returns, Jenny is on the verge of becoming a full-fledged member of the A-List crowd. Jenny must go to dangerous and even illegal lengths to fit in. Serena struggles to adjust to living with Chuck, and receives disturbing packages from an unknown sender.', 39, '2008-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 15, 'Desperately Seeking Serena', 'Serena''s world descends into chaos when a former friend, the evil Georgina Sparks returns to town. Nate connects with the last person he expected, Vanessa. Blair hatches a plan to sabotage her biggest rival, Nelly Yuki. Meanwhile Serena goes out with Georgina, but things get so bad that Serena thinks someone spiked her non-alcoholic drink. Jenny develops a crush on a dog-walker, Asher Hornsby, who might be her ticket to permanent popularity.', 41, '2008-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 16, 'All About My Brother', 'Georgina informs Serena that she can reveal a deep dark secret from Serena''s past, but no one is prepared for what Georgina does next. Blair and Jenny''s power struggle continues when each of them start spreading scandalous rumors about each other on Gossip Girl. Dan sees Jenny''s new beau, Asher, cheating on her, but Jenny won''t listen to him. Rufus goes to Lily for advice on how to handle Jenny''s new behavior. Serena tries to confront Georgina, but she leaves before Serena has a chance. After this, Serena says that she and Georgina are not friends.', 42, '2008-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 17, 'Woman on the Verge', 'After Georgina reveals the true reason Serena left Manhattan, Serena goes back into her old habits. Her friends Blair, Nate, and Chuck, in order to help her, have to put their differences aside. Meanwhile, Rufus is excited when his band is invited to perform at a Rolling Stone-sponsored concert, but Lily is the last person on earth he expects to see at the performance, especially since her wedding rehearsal dinner is the same night.', 42, '2008-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 1), 18, 'Much ''I Do'' About Nothing', 'Blair takes matters into her own hands to help Serena with the manipulative and evil Georgina Sparks. Lily, while keeping Rufus in her mind, prepares for her wedding with Bart Bass that is designed to be the Upper East Side''s social event of the year. Serena finally tells Dan the whole truth about her past and they try to work things out after Dan has cheated on her, but will it be too late? An unexpected guest shows up at Lily and Bart''s wedding. Georgina is sent somewhere where she can do no harm. Blair plans to go somewhere with Chuck.', 42, '2008-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')), 2, 'Season 2', 'Sex, lies and scandals never take a vacation. Rumors is the temperature began to climb between Nate  and Serena, who escaped to Hamptons for the summer following their break-up with Lonely Boy. As summer draws to a close, Blair returns from abroad with a hot guy on her arm and Dan, who has spent the summer assisting a famous author, decides to head to the Hamptons. Then, everyone gets back to the city for senior year. Applying for college is only one small part of the story as new romances (and some not-so-new romances) bloom and fade, scandals erupt at every turn, and alliances shift even faster than Gossip Girl can send an update.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 1, 'Summer Kind of Wonderful', 'As the summer draws to a close in the Hamptons, Serena and Nate have everyone fooled into thinking they are a couple to cover up the fact that Nate has been hooking up with a married, older woman. Blair returns from abroad with a hot guy on her arm, making a very jealous Chuck question his decision to leave Blair stranded at the heliport. Dan has spent the summer assisting a famous author. While interning for Eleanor Waldorf''s company, Jenny sneaks an invite to a much-coveted Hamptons'' White Party at which Eric introduces her to socialite Tinsley Mortimer.', 41, '2008-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 2, 'Never Been Marcused', 'Blair is over the moon that she is dating royalty and has every intention of becoming a royal herself, but a scheming Chuck has other plans for Blair and her new love, Marcus, when he introduces Blair to Marcus'' stepmother who happens to be Catherine. Meanwhile, Nate learns the downside to having an affair with Catherine when he keeps getting caught in his lies and learns his family has gone bankrupt due to his father jumping bail.', 41, '2008-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 3, 'The Dark Night', 'In a humorous twist, Blair questions the lack of passion in her relationship with Marcus, while at the same time Chuck appears to have lost his "passion" for any woman other than Blair. Meanwhile, Nate struggles between his feelings for Vanessa and his more-complicated-by-the-day relationship with Catherine. Jenny risks losing her internship when Eleanor catches Jenny critiquing one of the Eleanor Waldorf designs.', 41, '2008-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 4, 'The Ex-Files', 'Blair and her minions decide to befriend the new girl, Amanda, in order to sabotage her possible new relationship with Dan. Vanessa discovers a scandalous secret about Catherine and enlists Blair''s scheming expertise to use the information to help Nate. Meanwhile, Lily finds herself drawn back to her ex, Rufus, once again.', 41, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 5, 'The Serena Also Rises', 'In the midst of Fashion Week, a furious Blair learns that her mother, Eleanor, at the suggestion of her protege Jenny, has given Serena and her new socialite friend, Poppy Lifton, front row seats to the Eleanor Waldorf show. Hurt once again by Serena''s popularity and her mother''s betrayal, Blair decides to sabotage the show. Meanwhile, Dan starts hanging out with Chuck, but a walk on the dark side always has its risks and Dan learns that the hard way. Lily learns a secret that her new husband, Bart, has been keeping from her.', 42, '2008-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 6, 'New Haven Can Wait', 'After Blair and Serena get into a catfight, Serena decides to get even with Blair, who has always dreamed of attending Yale, by ditching her plans to visit Brown, and instead accepting the Dean of Yale''s personal invitation to visit the school. After discovering that none of his recommendation letters for Yale were ever submitted, Dan frantically tries to figure out a way to salvage his chances of getting into the school. While on the Yale campus, Chuck is kidnapped by a group of Skull and Bones members and Nate hooks up with a co-ed.', 42, '2008-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 7, 'Chuck in Real Life', 'Vanessa uses the scandalous picture of Catherine and Marcus to blackmail Blair into being a nicer person, so Blair seeks revenge by enticing Chuck to seduce Vanessa. Lily and Bart throw an extravagant housewarming party and expect their children to make them proud in front of the attending press, but a rebellious Serena isn''t ready to play by their rules. Meanwhile, Dan and Jenny discover a big secret that Nate has been keeping from his friends.', 42, '2008-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 8, 'Pret-a-Poor J', 'Jenny has a new young model friend, named Agnes, who encourages Jenny to explore her wild side, and also to confront Eleanor Waldorf who is planning to steal Jenny''s designs in order to pass them off as her own. Meanwhile, Serena and Dan attend Rufus'' latest art opening as friends, but then Serena meets an artist, named Aaron Rose, and the evening gets a little uncomfortable for Dan. Elsewhere, Blair attempts to seduce Chuck, but he proves to be tougher than she ever imagined. Also, Jenny begins to have a mutual feelings with Nate as he''s staying with her, Dan, and Rufus while searching for a place to live.', 42, '2008-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 9, 'There Might be Blood', 'Serena invites Aaron to a charity event, but soon uncovers a secret Aaron has been keeping from her. Thinking it will help her get into Yale, Blair agrees to babysit the 15-year-old daughter of a Yale donor, but her plan quickly backfires. Meanwhile, Jenny and Agnes plan a fashion show.', 42, '2008-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 10, 'Bonfire of the Vanity', 'Blair sets out on a mission to break up her mother and Cyrus Rose, her new man. Jenny moves in with Agnes as the two continue with their plans for their own fashion line. As Serena continues to fall for Aaron, she learns something that may derail their relationship forever while Dan interviews Bart Bass for an article for New York Magazine.', 42, '2008-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 11, 'The Magnificent Archibalds', 'It''s Thanksgiving time and Blair is offended when her Mom''s new man hijacks her Thanksgiving traditions. Lily attempts to strengthen the frail bond between Rufus and Jenny. Eric discovers a secret about Bart. Vanessa and Chuck help Nate deal with his father.', 42, '2008-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 12, 'It''s a Wonderful Lie', 'At the Snowflake dance, Blair and Chuck discover their lookalikes hooking up. Aaron''s ex Lexi flirts with Dan, causing trouble with Serena. Nate, Jenny and Vanessa get into a messy love triangle that involves a stolen letter and a revealing dress. Bart Bass suffers a car accident on his way to the ball.', 42, '2008-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 13, 'O Brother, Where Bart Thou?', 'The entire Upper East Side of Manhattan is rocked when Bart Bass dies suddenly in a limo accident. Serena and Eric take the news very calmly while Lily has a troubling time despite her mother, Cece''s, awkward attempts to comfort her. Chuck begins to blame Lily for his father''s death and threatens to reveal a secret that Bart found on her before his accident. Meanwhile, Blair''s mother, Eleanor, prepares for her latest marriage to Aaron''s father Cyrus.', 42, '2008-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 14, 'In the Realm of the Basses', 'Because Chuck is MIA since his father''s funeral, his Uncle Jack arrives on the Upper East Side to find and help him. Trying to forget her last conversation with Chuck, Blair focuses on being accepted into the most prestigious ladies club in the city, Colony Club. Jenny returns to Constance Billard and immediately takes on Penelope and her posse of mean girls, but no one is going down without a valiant Gossip Girl-worthy fight.', 41, '2009-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 15, 'Gone with the Will', 'Chuck, Jack and Lily come together for the reading of the will which reveals what will come of the Bass empire. Rufus and Lily''s relationship is put on hold as Rufus searches for the child he never knew he had. Meanwhile, Dan does some digging of his own and uncovers Rufus and Lily''s secret, putting him in an awkward position.', 42, '2009-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 16, 'You''ve Got Yale', 'The students are stressed out as they find out who was accepted and who didn''t make the cut for early admission to Yale. Meanwhile, Serena bonds with Rachel, her Shakespeare teacher, who is unaware of what Blair has in store for her following receiving her first B; Chuck finds an unlikely ally in his feud with Jack; and Nate and Vanessa have a romantic evening together.', 42, '2009-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 17, 'Carrnal Knowledge', 'Blair comes up with a devious plan to take down her new teacher, Rachel. Chuck has no recollection of what happened to him when he wakes up in a hotel. Nate and Vanessa try to help Chuck fill in the missing pieces of his night. Meanwhile Dan and Serena try to keep their relationship together as Rufus and Lily grow even closer.', 42, '2009-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 18, 'The Age of Dissonance', 'The Constance Billard and St. Jude seniors have the production of "The Age of Innocence". Serena has a crush on the play''s director, Julian, and enlists Vanessa''s knowledge of theater to help her get the guy''s attention. Blair receives bad news about her future that leads her on a witch hunt for the person responsible. Dan and Rachel agree to stay away from each other in the aftermath of being discovered as more than teacher and student, but find it impossible to keep that promise. Chuck find help on an unlikely friend, Carter Baizen.', 42, '2009-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 19, 'The Grandfather', 'Devastated by the turn her life has taken, Blair opts for a wild lifestyle instead of her perfect Waldorf life, causing Chuck and Serena to become concerned. Vanessa tries to convince Nate that he needs to move on after his mother''s family, the Vanderbilts, abandoned him and his mother. Trying to be honest with each other, Lily and Rufus both put together their lists of past relationships.', 42, '2009-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 20, 'Remains of the J', 'Serena throws Jenny a sixteenth birthday party, but things spin out of control when Poppy Lifton turns the party into the social event of the season. Vanessa agrees to help Chuck in a plan concerning Blair and Nate. Meanwhile, Rufus searches for a way to cover Dan''s tuition when he learns he will not receive financial aid to go to Yale.', 42, '2009-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 21, 'Seder Anything', 'Serena returns from her trip to Spain with Poppy and Gabriel. Blair makes a secret deal with Nate''s grandfather. Dan takes a job to earn money for college.', 42, '2009-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 22, 'Southern Gentlemen Prefer Blondes', 'Georgina returns to the Upper East Side but it''s not the same Georgina we all knew, she''s changed. Chuck and Nate''s relationship is at a crossroads because of their mutual interest in Blair. Serena''s relationship with Gabriel gets more complicated.', 42, '2009-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 23, 'The Wrath of Con', 'Blair puts pressure on Georgina to making amends for her past bad behavior by helping her in an evil plan. The rivalry between Nate and Chuck over Blair reaches a boiling point. Lily makes a secret plan to help Rufus with Dan''s college tuition.', 42, '2009-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 24, 'Valley Girls', 'In a flashback to the 80s, 17-year-old Lily Rhodes gets kicked out of boarding school and runs away to Los Angeles, reconnecting with her parents, Rick and Cece, and sister, Carol. Back in present day, Blair and Nate attend prom together, but the evening doesn''t turn out exactly as planned and Chuck and Serena have a little something to do with that. Serena and Lily don''t see eye-to-eye over Serena''s recent run-in with the law.', 43, '2009-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 2), 25, 'The Goodbye Gossip Girl', 'Gossip Girl decides to liven things up at the Constance Billard and St. Jude''s graduation by sending out a shocking and damaging email blast in the midst of the commencement ceremony, stirring Serena to come up with a plan of attack. The Mean Girls challenge Jenny to throw her hat in the ring to succeed Blair as Queen Bee next year. Lily and Rufus struggle to repair their relationship after Lily''s betrayal. As for the cliffhangers, Blair and Chuck finally... and Serena is shocked by... and Georgina decides to... and Dan, Nate, and Vanessa unknowingly.... Jenny and Eric do something they might end up regretting.', 42, '2009-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')), 3, 'Season 3', 'Welcome back, Upper East Siders. Summer is officially drawing to a close. Rufus, Dan and Jenny spent the summer in the Hamptons, adjusting to the van der Woodsen''s glamorous lifestyle surprisingly faster than any of them expected. Blair and Chuck are madly in love and adjusting to their new "in a relationship" status. Nate returns from his travels with a mysterious brunette in tow. Serena returns from her European adventure with many secrets to hide as she gets ready to move into her dorm at Brown. Blair is determined to have her Queen status at NYU, along with Dan and Vanessa, but her roommate sets out to ensure that she does not retain her title.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 1, 'Reversals of Fortune', 'As summer draws to an end, Blair and Chuck continue to adjust to being in a relationship with one another. Serena returns from Europe with new secrets to hide and a new relationship with Carter Baizen. Nate also returns from vacationing and brings home a mysterious girl, Bree Buckley. Meanwhile, Rufus, Dan and Jenny spend the summer in the Hamptons and learn to adjust to the van der Woodsen''s glamorous lifestyle', 41, '2009-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 2, 'The Freshmen', 'Blair, determined to have her Queen status at college, starts her first day at NYU along with Dan and Vanessa. However, Georgina, who was assigned as Blair''s roommate, sets out to ensure that she does not retain her title. Serena gets ready to move into her dorm at Brown, but has a fight with Chuck before hand. This leads her to search out Chuck''s enemy, Carter, to help her get even with him. Meanwhile, Nate and Bree''s relationship continues to grow despite the tension their relationship could cause between their families.', 41, '2009-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 3, 'The Lost Boy', 'Blair and Chuck face-off when the both set their sights on an item up for bid at Sotheby''s. Serena begins to think that Carter may have returned to his old habits, Georgina becomes interested in Dan, and Vanessa thinks that something is wrong with Scott.', 42, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 4, 'Dan De Fleurette', 'During the first day of school at Constance Billard, Jenny takes her place as the new Queen Bee. However, Blair gets in her way. Lily returns home to find that things are not as they were when she left them with Rufus. At NYU, Olivia Burke, an actress, enrolls and is assigned to be Vanessa''s roommate.', 42, '2009-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 5, 'Rufus Getting Married', 'Lily and Rufus decide to move up their wedding to the next day, but will someone or something come between them before they become man and wife? Chuck discovers a secret that Carter has been keeping from Serena. Dan and Vanessa are pulled into one of Georgina''s schemes. Blair is suspect of Bree and shares her concerns with Nate.', 41, '2009-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 6, 'Enough About Eve', 'Vanessa, hoping to finally win her mother Gabriela''s approval, desperately vies with Blair for the honor of delivering the freshman toast at NYU, but at what price? Dan invites Olivia to meet Rufus and Lily, which leads to all sorts of problems for the new couple. Serena and Nate team up to help Carter Baizen.', 42, '2009-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 7, 'How to Succeed in Bassness', 'In need of publicity for his new hotel, Chuck decides to move up his club''s opening and enlists Serena''s help to get the word out to her celebrity clients. Feeling left out of the planning, Blair attempts to win Chuck''s approval by secretly helping him with a problem concerning opening night. Dan is unnerved when he finally watches one of Olivia''s infamous sex scenes with co-star and real-life boyfriend at the time, Patrick Robinson. Jenny is forced to choose between her relationship with Eric and her new role as Queen Bee. Rufus gets Lily into the Halloween spirit.', 42, '2009-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 8, 'The Grandfather: Part II', 'Olivia says something she regrets during her appearance on Jimmy Fallon''s talkshow and tries to keep Dan from finding out. With election day around the corner, Nate suspects his grandfather will stop at nothing to get Trip elected to congress. In the midst of another feud with Serena, Blair befriends a new "it" girl and takes her to an election night party at Chuck''s hotel, hoping to make Serena jealous.', 41, '2009-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 9, 'They Shoot Humphreys, Don''t They?', 'Jenny wants to be the Queen Bee of not only Constance but of all the Upper East Side, as she lands the hottest escort for the Cotillion. Meanwhile Dan and Vanessa try to convince Olivia to stay in NY by showing her the "true college experience". Leighton Meester''s new single "Somebody to Love" is featured in the episode, along with performance from Plastiscines.', 42, '2009-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 10, 'The Last Days of Disco Stick', 'Hoping to impress the elitist theater kids at NYU, Blair sets her sights on landing a private concert with the hottest musical performer of the year, Lady Gaga. Dan and Olivia sign up to write and star in a school play, based on an idea by Blair and directed by Vanessa. With Blair out of the picture, Serena turns to Nate to help her get through a difficult situation. As a favor to Chuck, Jenny agrees to hang out with Damien, the son of an ambassador who is staying at Chuck''s hotel, but the experience proves to be a lot more intriguing than she expected.', 42, '2009-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 11, 'The Treasure of Serena Madre', 'It wouldn''t be Thanksgiving on the Upper East Side if there wasn''t a serving or two of some major drama for the holiday. Blair suspects her mom has been keeping a big secret from her, but it turns out to be something else entirely. Vanessa is supposed to spend Thanksgiving with her parents, but has a fight with her mom and shows up on Dan''s doorstep. Rufus learns that Lily has been lying to him about her mother, Cece. Chuck tells Nate that he has some potentially damaging information about one of their friends. Jenny learns that Eric was behind her very public embarrassment at Cotillion and can''t pass up a chance to get even. Serena is put in a very awkward position when her mother invites Trip and Maureen to join them for Thanksgiving dinner.', 42, '2009-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 12, 'The Debarted', 'On the anniversary of Bart Bass'' death, Chuck wrestles with an issue from the past and a serious car accident rocks the Upper East Side. Dan and Vanessa attempt to navigate their newly complicated friendship. When Jenny is accused of beating up one of her classmates, Eric is faced with a tough dilemma.', 42, '2009-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 13, 'The Hurt Locket', 'Nate and Serena decide to explore the boundaries of their friendship. Blair suspects that Chuck is having problems forgetting about the woman he saw at his father''s grave. Jenny agrees to accompany Damien to a State Dinner but is unaware that he needs her help with a drug exchange. Vanessa and Dan attempt to move past the awkwardness of Dan''s confession of love. Rufus returns from a ski trip and tries his best to avoid Lily.', 41, '2010-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 14, 'The Lady Vanished', 'Rufus and Lily grow suspect of Jenny''s relationship with Damien. Chuck learns more about the woman who may or may not be his mother. Dan and Vanessa struggle through the awkwardness of dating other people.', 41, '2010-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 15, 'The Sixteen Year Old Virgin', 'Despite being grounded, Jenny continues to see Damien who tells Jenny that he wants to have sex with her. Lily tells Rufus the big secret she has been keeping from him even though she knows it''s a huge risk. Dan and Vanessa explore a new stage of their friendship. Chuck is forced to make an extremely difficult decision about his hotel.', 42, '2010-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 16, 'The Empire Strikes Jack', 'Chuck finds himself once again at odds with his uncle, Jack Bass. Eleanor puts Blair in charge of making sure her latest fashion show is a huge success with an important client. Rufus attempts to get Jenny back on track by volunteering to have her help with Eleanor''s fashion show, but the opportunity takes a big turn for the worse when Jenny learns that Agnes will be one of the models.', 42, '2010-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 17, 'Inglourious Bassterds', 'Chuck and Blair are faced with the most difficult decision they have ever faced as a couple. Serena plans a surprise birthday party for Nate, but Jenny does her best to sabotage Serenas''s efforts. Dan and Vanessa''s new relationship hits a bump in the road.', 42, '2010-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 18, 'The Unblairable Lightness of Being', 'Chuck offers to throw a wedding for a very pregnant Dorota who insists that she and Vanya have a traditional wedding before her parents arrive from Poland and find their daughter pregnant and without a husband.. Dorota asks Blair and Chuck to be part of the ceremony and walk her down the aisle. Serena tells Nate she is having breakfast with the Humphreys when in reality she''s secretly meeting up with Carter Baizen. Rufus discovers that Lily has been lying to him about her whereabouts.', 42, '2010-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 19, 'Dr. Estrangeloved', 'When Lily''s ex-husband, Dr. William van der Woodsen, shows up unexpectedly in Manhattan, Serena finally gets the reunion she has so desperately wanted with her father, but the circumstances turn out to be far from ideal. When Serena and Nate continue to have relationship issues, a scheming Jenny is more than happy to be a shoulder for Nate to lean on... Meanwhile, Dan finds out that he didn''t get accepted into the Tisch writing program and Vanessa admits she may have been somewhat responsible.', 42, '2010-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 20, 'It''s a Dad, Dad, Dad, Dad World', 'Will''s return to the Upper East Side continues to stir up problems for Serena, Lily and his long-standing rival, Rufus. Serena and Jenny''s relationship is strained as a result of Jenny''s deception. Blair spends time on the Columbia campus and realizes where she truly belongs.... Dan learns that Vanessa has been keeping yet another secret from him.', 42, '2010-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 21, 'Ex-Husbands and Wives', 'When things get tense between Rufus and Will, Serena chooses to stand behind her father, while at the Rufus is made to feel like an outsider in his own family. Meanwhile, Jenny deliberately shares information with Will that may ultimately destroy Lily and Rufus'' marriage. After many failed attempts, Chuck makes one last grand gesture to reconcile with Blair, hoping she will finally accept the fact that they are destined to be together.', 42, '2010-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 3), 22, 'Last Tango, Then Paris', 'Blair must decide whether to meet Chuck at the top of the Empire State Building or risk losing their future together. A Gossip Girl gossip bomb involving Dan explodes Serena and Nate''s relationship. Dorota and Vanya welcome their baby. Jenny hits rock bottom. Georgina returns to the Upper East Side...and she has an agenda.', 42, '2010-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')), 4, 'Season 4', 'Season four''s main mystery revolves around Juliet Sharp, a secretive girl with an agenda against Serena involving her past. The second half of the season builds on the complications of Serena''s new found relationship with her former teacher Colin, Chuck trying to regain control of Bass Industries from Russell Thorpe, and Dan and Blair''s growing friendship. The season also focuses on Lily''s past betrayals coming back to haunt her; Chuck and Blair''s tumultuous relationship after their break up; Dan and Vanessa''s deteriorating friendship; and the arrival of Serena''s cousin Charlie Rhodes to the Upper East Side. By the end of the season, Blair has ignored Chuck, Dan has told Vanessa they are no longer friends, and Serena is on that single grind.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 1, 'Belles de Jour', 'Blair and Serena spent their summer living it up in the belly of the beast: Paris, France. But where there''s Paris there''s bound to be boutique, Balenciaga, and of course, boy trouble. Unaware of Chuck''s shooting in Prague, Blair struggles to forget him; things take a turn, however, when Chuck mysteriously shows up in Paris with a foreign stunning blonde at his arm. Meanwhile Serena contemplates which of her long-time beaus could be the one for her: Dan or Nate? Even on the Upper East Side drama erupts as Dan figures out the baby mama drama with Georgina, and Nate realizes something about himself when he meets fellow Columbia student, the intriguing Juliet.', 41, '2010-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 2, 'Double Identity', 'Living out a real-life fairytale in Paris, Blair is pursued by a handsome young man, Louis, who she suspects is a member of Monaco''s royal family. A very concerned Lily asks Serena to help her find Chuck, who hasn''t been heard from or seen in months. Meanwhile, Chuck Bass is as we''ve never seen him before, adjusting to a fresh start in Paris with a mysterious new woman, Eva, at his side. Juliet offers to help Nate win Serena back, suggesting that reigniting Dan and Vanessa''s romance may just be the trick to remove Dan from the Dan-Serena-Nate love triangle.', 41, '2010-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 3, 'The Undergraduates', 'On her first day at Columbia, Blair attempts to gain membership into an ultra-exclusive social club, Hamilton House .... but she''s in for a few big surprises. Serena begins to suspect that Juliet is intentionally sabotaging Serena''s life and that it may have something to do with Nate. Rufus is worried about Dan and decides to take matters into his own hands.', 42, '2010-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 4, 'Touch of Eva', 'Nate suspects that Juliet is keeping a big secret from him and decides to confront her. Blair schemes to undermine Chuck''s newfound happiness. Dan finds himself torn between his feelings for Serena and Vanessa.', 42, '2010-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 5, 'Goodbye, Columbia', 'An anonymous Gossip Girl blast starts a very damaging rumor about one of Columbia''s new students, Serena. On her path to greatness, Blair decides to take a class with a powerful businesswoman, Martha, who is guest-lecturing at Columbia, but a mysterious fellow student thwarts her plans to secure the prized position as Martha''s assistant.', 42, '2010-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 6, 'Easy J', 'Although Blair made it perfectly clear that Little J was no longer welcome in Manhattan after what happened with Chuck, Jenny is tempted by a once-in-a-lifetime opportunity to meet Tim Gunn, which could be a game changer for her future. Meanwhile, Serena discovers something about her new boyfriend, Colin, that may put an end to their relationship just as it was getting good.', 41, '2010-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 7, 'War at the Roses', 'Blair is caught off-guard – and not in a good way – by a surprise guest at her birthday party. Having had enough of Chuck and Blair''s games, Serena and Nate decide to plan an intervention.', 42, '2010-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 8, 'Juliet Doesn''t Live Here Anymore', 'Chuck and Blair decide it''s in both their best interests to put the past behind them and end their vindictive games. Nate confronts Juliet after discovering a secret she has been keeping from everyone. Dan and Nate realize they both still have feelings for Serena.', 42, '2010-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 9, 'The Witches of Bushwick', 'Chuck hosts a "Saints and Sinners" masquerade party at the Empire Hotel. At the party, Dan and Nate don''t know what to make of Serena''s strange behavior and mixed messages. Blair sets her sights on becoming the new face of Anne Archibald''s foundation for girls, but Anne is concerned that Blair''s friendship with Chuck Bass may be problematic.', 42, '2010-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 10, 'Gaslit', 'Chuck, Serena, Blair, Dan, Jenny and Eric find themselves faced with a crisis when a member of one of their families is hospitalized. Meanwhile, Nate attempts to help his parents, The Captain and Anne, put their complicated past behind them and reconcile.', 41, '2010-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 11, 'The Townie', 'Blair and Dan join forces to find Juliet. Serena expounds her boarding school experiences to her therapist and discovers the truth behind Juliet''s vendetta against her. Meanwhile Chuck suspects Lily has not told him the full truth.', 41, '2010-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 12, 'The Kids Are Not Alright', 'A former associate of Chuck''s father, Russell Thorpe – along with his daughter Raina – returns to Manhattan with some unfinished business for our Upper East Siders. Serena and Chuck join forces against Lily. Blair realizes that her mother, Eleanor, may be her key to becoming a future CEO. Nate worries that his father, The Captain, is having a little too much fun and not taking his parole seriously.', 42, '2011-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 13, 'Damien Darko', 'Blair is ecstatic to land an internship at W Magazine, but the thrill quickly fades when she finds out that Dan has secured one of the coveted positions as well. Chuck may have finally met his match with Russell Thorpe – and his daughter Raina – back on the Upper East Side. Nate receives alarming news about his father''s business prospects.', 41, '2011-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 14, 'Panic Roommate', 'Blair enlists Nate''s help to win over her high-strung boss, Epperly, at W Magazine. Damien stirs up more drama on the Upper East Side. Chuck finds himself torn between business and pleasure. Florence and the Machine performs an acoustic version of "Cosmic Love."', 41, '2011-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 15, 'It-Girl Happened One Night', 'With Russell Thorpe poised for a takeover attempt of Bass Industries, Chuck makes one last-ditch effort to save his family''s company. Blair is given a challenging assignment at W Magazine with the promise of a possible promotion. Serena struggles with her feelings for Ben.', 41, '2011-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 16, 'While You Weren''t Sleeping', 'It wouldn''t be a proper Upper East Side party without some major Gossip Girl drama, and for Eric''s 18th birthday celebration there is plenty to go around. Blair decides to speed up the time table on her career path to becoming a powerful woman.... but ultimately stretches herself too thin. Serena is forced to choose between her family and Ben. Chuck and Lily''s relationship remains icy in the aftermath of Lily''s betrayal.', 42, '2011-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 17, 'Empire of the Son', 'Ben''s mother comes to town, forcing issues to the surface between Ben and Serena. Russell Thorpe is determined to destroy Chuck''s family legacy, but he risks alienating his daughter, Raina, in the process. Billy Baldwin returns as William van der Woodsen, Lily''s ex-husband and Serena and Eric''s father.', 41, '2011-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 18, 'The Kids Stay in the Picture', 'As Lily awaits the consequences of her decision, William van der Woodsen, CeCe and Lily''s sister, Carol, come into town to support her and be part of a Taschen photo shoot on "modern royalty" in which the Rhodes family is participating. Unbeknownst to Carol, who has always chosen to keep her daughter Charlie far away from the Upper East Side, Charlie has followed her to New York to meet Serena and the rest of the family. Blair has an epiphany about her future, and grapples with the knowledge of whom she''s destined to be with.', 42, '2011-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 19, 'Petty in Pink', 'Serena enlists Charlie to go undercover Gossip Girl-style to determine why Dan and Blair are spending so much time together, and what role an unexpected visitor is playing in their lives. With Nate''s help, Raina decides to go on a search for her long-lost mother. Chuck''s hopes about his legacy are dashed with the reveal of devastating information from the past.', 41, '2011-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 20, 'The Princesses and the Frog', 'Blair''s dreams appear to be coming true, but Serena threatens to jeopardize it all by dredging up Blair''s past. Charlie befriends Vanessa, who may or may not have a hidden agenda. Nate is torn between his relationship with Raina and a truth he must keep hidden out of loyalty to Chuck.', 41, '2011-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 21, 'Shattered Bass', 'Charlie is finally starting to feel less like a fish-out-of-water with Serena and her friends, but complications present themselves when Charlie is invited to attend the Constance Billard alumni fundraiser. On the road to "happily ever after" Blair finds herself torn between the men in her life. Jack Bass return to the Upper East Side sets off a chain of events that could end up destroying Chuck and those closest to him.', 41, '2011-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 4), 22, 'The Wrong Goodbye', 'The episode continues from the early events of the Constance Alumni event. Georgina Sparks turns up at the event looking for trouble. Serena and Vanessa reluctantly join forces to find Dan and Charlie, who does not take Dan''s rejection of her well. Blair must make a choice between the men in her life when her life is in danger by Russell.', 41, '2011-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')), 5, 'Season 5', 'The season began in Los Angeles when a re-energized Chuck and Nate decided to pay Serena a visit. Chuck has a newfound philosophy and says "yes" to everything, even death defying stunts. Serena continues to work on the movie set, and is offered a full-time job at the end of the episode. Nate begins an affair with an older woman, Diana Payne, who may have an ulterior motive for being with Nate. Back in New York, Dan learns that Vanessa has published one chapter of his novel, and Blair continues to plan her wedding to Louis, and she also learns she is pregnant. After realizing she still had feelings for Chuck, Blair and Chuck decide to go away together, but their car crashes. As a result of the crash Blair loses her baby, Chuck nearly dies, and Blair eventually marries Louis. The season also focuses on Nate running an online gossip site NYSpectator, Blair and Dan''s friendship turning into a relationship, Chuck''s quest to find his real parents which leads him to discover that his father, Bart, is still alive, and the effects of CeCe''s death on Lily and her marriage to Rufus. At the end of the season, Blair makes a choice between Dan and Chuck, and Lily makes a choice between Rufus and Bart. Serena is seen leaving town while Dan decides to write a new book about the Upper East Side, with the help of Georgina.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 1, 'Yes, Then Zero', 'Serena loves her new job in Hollywood, but makes a costly misstep when she tries to impress her boss. Chuck and Nate arrive in Los Angeles as the last stop of their Lost Summer trip, joining Serena at a glamorous Hollywood Hills party, where Nate meets a sexy older woman. Blair and Louis return from Monaco and begin planning their royal wedding, but when Louis refuses to stand up to his family and support Blair''s choices, his weakness threatens their relationship. A magazine is planning to run an excerpt of Dan''s book until an unlikely ally steps in to help him kill the story.', 41, '2011-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 2, 'Beauty and the Feast', 'Nate reconnects unexpectedly with Diana, who offers him an exciting opportunity. Serena forces Charlie to decide which world she wants to embrace. Dan seeks out Chuck''s help to stop the publication of his book, but discovers it is Chuck who needs the help. Blair''s future sister-in-law, Beatrice, arrives from Monaco, but her motives with Blair may be more than just to get acquainted.', 42, '2011-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 3, 'The Jewel of Denial', 'Nate must decide whether to cross moral lines at Diana''s request. Dan has figured out who is publishing his book, and seeks help to stop it, but he ends up in the spotlight anyway. Chuck helps Dan come to terms with his fate, just as Dan continues to try to help Chuck break through his emotional block. Serena and Charlie return to the Upper East Side from California.', 41, '2011-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 4, 'Memoirs of an Invisible Dan', 'After much deliberation, Dan decides to gather Serena, Blair, Nate, Chuck, Rufus and Lily to reveal the truth about his book in the hope that they will support him at his book party. Meanwhile, Blair and Louis hit a crises point after Louis reads Dan''s book. Diana learns incriminating information about one of Nate''s friends and uses it to her advantage.', 41, '2011-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 5, 'The Fasting and the Furious', 'In the midst of celebrating Yom Kippur with family and friends, Blair and Louis find themselves in a power struggle with Louis'' family. Serena''s boss puts Serena in the awkward position of choosing between her new job and her relationship with Dan. Diana prepares to debut the New York Spectator, but an unfortunate last-minute surprise delays the launch and Diana expects Nate to do whatever it takes to save the day.', 42, '2011-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 6, 'I Am Number Nine', 'Blair makes all of her former minions and Charlie compete to secure the coveted bridesmaid spots in her upcoming royal wedding. Nate is tired of keeping his relationship with Diana a secret, so he decides to use Charlie to make Diana jealous. Serena''s boss is determined to acquire the film rights to Dan''s book, so Serena must put her personal feelings about Dan and the book aside in order to close the deal.', 41, '2011-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 7, 'The Big Sleep No More', 'Several of our favorite Upper East Siders attend a performance of Punchdrunk''s provocative theater experience, "Sleep No More," which translates to masks, anonymity and some surprising romantic twists by the end of the evening. Meanwhile, Diana sets her sights on Serena in her quest to ruin Gossip Girl. Dan is out on his book tour, but things aren''t exactly as they appear to his friends and family.', 41, '2011-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 8, 'All the Pretty Sources', 'Serena is hard at work planning a dream bridal shower for Blair, but it should come as no surprise that Serena has to plant some false information about the shower in order to keep Blair from finding out all the details. Chuck and Dan decide to spend the day together to distract themselves from the fact that they didn''t make the invite list for Blair''s shower. Nate and Serena find a silver bullet in Diana''s war against Gossip Girl, but struggle about whether to use it or not.', 42, '2011-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 9, 'Rhodes to Perdition', 'Lily, Charlie and Serena eagerly anticipate the Studio 54 party being thrown in CeCe''s honor. Nate takes on a new role at the Spectator, but his first big story turns out to be about someone he knows all too well. Blair turns to an unlikely person for help.', 41, '2011-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 10, 'Riding in Town Cars with Boys', 'Lily throws Charlie a party to officially introduce her to New York society. Meanwhile, Charlie''s ex-boyfriend, Max, throws a wrench into Charlie''s future as an Upper East Side princess. Dan decides it may be time to tell Blair the truth about his feelings for her.', 41, '2011-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 11, 'The End of the Affair?', 'Blair''s flashbacks reveal the fallout of her and Chuck''s car accident, which Nate realizes may have been caused by foul play. Meanwhile, Lily gets a private eye to locate Charlie; and Vera Wang makes an appearance at Blair''s bridal-dress fitting.', 42, '2012-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 12, 'Father and the Bride', 'Blair prepares to celebrate her upcoming royal wedding with a bachelorette party, but others scheme behind her back to make this a night to remember. After discovering the truth behind Chuck and Blair''s car accident, Nate joins forces with a surprising ally to gather the evidence. Serena and Dan pretend to be dating again to protect someone close to them.', 41, '2012-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 13, 'G.G.', 'The much-anticipated 100th episode will open with a musical dream sequence featuring Serena, Blair and all the men in their lives. Also, while Chuck wrestles with the reality that Blair is about to walk down the aisle with Prince Louis, the return of Georgina Sparks might make the royal affair a royal disaster.', 41, '2012-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 14, 'The Backup Dan', 'Blair must make a difficult decision about her future, the consequences of which could hurt those she loves most. Serena takes the blame for an incident with Gossip Girl in order to protect someone she loves.. Georgina smells the scent of scandal and decides to follow its trail.', 41, '2012-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 15, 'Crazy, Cupid, Love', 'It''s Valentine''s Day on the Upper East Side and Blair can''t resist playing cupid for someone she loves. Georgina is intent on stirring up more drama, so she decides to crash Nate''s Valentine''s Day party. Meanwhile, Serena is shocked by something she witnesses at the party.', 41, '2012-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 16, 'Cross Rhodes', 'Dan feels honored when he learns that Upright Citizen''s Brigade is performing excerpts from his book, Inside. Blair tries to prove Serena''s suspicions wrong in order to save their friendship.. On her way out of town, Ivy ends up on a collision course with the van der Woodsens.', 41, '2012-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 17, 'The Princess Dowry', 'Blair thinks Cyrus may have found a potential loophole in her prenup. Chuck and Georgina partner up in a scheme, but it has an unpredictable outcome.. Meanwhile, a family crisis brings William van der Woodsen back to the Upper East Side.', 41, '2012-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 18, 'Con-Heir', 'Chuck invites Jack to town to thank him for saving his life, but finds the trip doesn''t go exactly as planned. Blair and Dan attempt to consummate their new relationship -- but unexpected roadblocks get in their way. Meanwhile, Ivy finds an unlikely ally in William in her quest to be accepted on the Upper East Side, and Nate is hopeful a new investor will save his newspaper.', 41, '2012-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 19, 'It Girl, Interrupted', 'Serena decides she is ready to relinquish the spotlight and sets out to make a reluctant Lola the next "It Girl" of the Upper East Side, starting with modeling at a Kiki de Montparnasse lingerie show. Meanwhile, Chuck reaches out to Blair or advice about his past, and Diana Payne''s return to The Spectator starts a power struggle with Nate.', 41, '2012-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 20, 'Salon of the Dead', 'To celebrate their official coming out as a couple, Blair and Dan host a glamorous British-themed Salon, including guests Julian Tepper and Jenna Gribbon Lola lands the audition of a lifetime, but Gossip Girl may have other plans for the Upper East Side''s latest It Girl. Meanwhile, Lily and Rufus disagree over the best way to handle the Ivy situation, and Serena and Diana face-off over secrets they both would prefer remain secrets.', 41, '2012-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 21, 'Despicable B', 'Blair feels like her Upper East Side status might be slipping away and devises a plan to assure that doesn''t happen. Meanwhile, Lily throws a family gathering – including William, Carol and Lola – in an attempt to prove the van der Woodsen family is as united as ever. Finally, Nate digs into Diana''s past and is surprised by what he discovers.', 41, '2012-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 22, 'Raiders of the Lost Art', 'Chuck, Nate, Blair, Serena and Lola team up to uncover what they think is an explosive secret between Diana and Jack. Meanwhile, Dan is offered a prestigious fellowship in Rome for the summer.', 41, '2012-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 23, 'The Fugitives', 'Blair enlists Serena to be her stand-in at an important meeting when Blair finds herself needing to be in two places at the same time. Meanwhile, Ivy and Lola team up to help Chuck with a personal vendetta, and Nate makes a decision about the future with Diana Payne.', 40, '2012-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 5), 24, 'The Return of the Ring', 'When Gossip Girl goes after Blair as she''s never done before, Serena admits she may have unintentionally played an important role in Blair''s latest nightmare. Meanwhile, Nate invites Lola to move in with him, and Lily must make a big decision about the future of her marriage. Finally, by episode''s end, Blair will make a choice between the two men in her life...will it be Chuck or will it be Dan?', 41, '2012-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')), 6, 'Season 6', 'Serena has gone off the grid, beyond even the reach of Gossip Girl. Her friends fear for the worst and hope for the best, but even they can''t imagine where they will ultimately find her. Meanwhile, Blair has offered Chuck her heart, but is her love enough to help him win back his empire? Lonely Boy Dan has written a new book that promises to make even more trouble than the first, and this time he has no desire to remain anonymous. Nate is determined to finally reveal the true identity of Gossip Girl, thereby making a name for The Spectator, and himself. Lily and Rufus turn on one another when Rufus makes a surprising new ally who threatens Lily and her family. Anywhere else it would be too much drama to handle, but this is the Upper East Side.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 1, 'Gone Maybe Gone', 'After a brief encounter abroad, Chuck and Blair make a promise to each other about their relationship, which leaves them once again apart. Dan, with some help from an unlikely ally, Georgina, is writing a scathing tell-all book that can only mean trouble. As the sole head of The Spectator, Nate is making his own decisions and is ready to go up against Gossip Girl. As word spreads that Serena is missing, the gang bands together to find her and are shocked by what they find.', 41, '2012-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 2, 'High Infidelity', 'Trying to prove herself in adult society, Serena hosts the Central Park Conservancy''s big gala, of which she is now the newest Board Member, and she and Nate both learn something shocking about their significant others. Blair prepares to debut her new fashion line, but a rival from her past holds the key to her future. With the help of Georgina, Dan lands some meetings with publishers, but he must decide if he is willing to sacrifice his integrity in order to get his work published. Meanwhile, Chuck tries to persuade Amira to help him look into his father''s past, even if it means jeopardizing Lily and Bart''s relationship.', 42, '2012-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 3, 'Dirty Rotten Scandals', 'Feeling the pressure to make her first Waldorf Designs fashion show a success, Blair must rely on help from an unlikely source, but some unexpected scheming causes a scandal on the runway. Serena discovers that befriending Steven''s daughter Sage is trickier than she thought, especially when she is forced to put her issues with Blair aside to make Sage happy. Nate publishes Dan''s first serialized article causing a stir and producing a serious threat. Meanwhile, Chuck begins to look into the clue that Amira left behind, which may help uncover what Bart is hiding.', 42, '2012-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 4, 'Portrait of a Lady Alexander', 'Chuck''s continued investigation into his father''s dealings leads him to an unlikely event with Manhattan''s elite, where he hopes to find the one person who can tell him the truth about Bart. Serena and Steven decide to reveal their romantic histories so they aren''t surprised by anything, but neither was prepared for what they uncovered. With The Spectator in jeopardy after Dan decided to publish elsewhere, Nate must make a difficult decision to keep it in business. Meanwhile, Georgina pushes Dan to choose a worthy person to date to boost his image, but he finds himself drawn in a different direction.', 41, '2012-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 5, 'Monstrous Ball', 'After Eleanor gives Blair an ultimatum, Blair is even more determined to remedy Waldorf Designs'' problems by making a splash with a dress at the upcoming Cotillion, but a shocking revelation at the ball affects everyone. Serena becomes worried about Steven''s attitude toward her, but after some investigating she discovers the surprising reason why. Chuck finds an unlikely ally as he tries to drive a wedge between Bart and Lily''s relationship to help expose his father''s secret. Meanwhile, Dan publishes another article, but the effect is just the opposite of what he was hoping for.', 41, '2012-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 6, 'Where the Vile Things Are', 'Serena volunteers to help Dan find a new place to live but their time together brings up unexpected emotions.', 42, '2012-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 7, 'Save the Last Chance', 'Serena and Dan realize that they need to make amends with the people they have wronged. Chuck’s search for evidence of his father’s illegal activities leads him to a showdown with Bart.', 41, '2012-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 8, 'It''s Really Complicated', 'Serena and Dan decide to throw their first Thanksgiving together, inviting only their closest friends, but everyone seems to have their own agenda for attending. Feeling defeated by his father, Chuck begins a downward spiral, leaving Blair to find a solution to his problems. Meanwhile, Dan has written his latest exposé, but he must make a tough decision whether to publish it, knowing it could destroy a close friendship.', 41, '2012-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 9, 'The Revengers', 'After a run-in with an increasingly paranoid Bart, Blair grows alarmingly concerned for Chuck''s safety. However, feeling confident that his father will never hurt him, Chuck makes a deal that could change his life. Wanting to make things better for Chuck, Blair devises a plan with the help of Serena, Georgina and Sage to try and get what they need out of Bart. Meanwhile, Nate''s financial dilemma finally lands him in a place that he never thought he would be.', 41, '2012-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397442')) AND numero_temporada = 6), 10, 'New York, I Love You XOXO', 'In a fashionable farewell to remember, our favorite Upper East Siders join forces for one last soiree, and the shocking identity of Gossip Girl is finally revealed.', 39, '2012-12-17');
