INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 1, 'Blink', 'The team finds three young women, all of whom appear to have been brutalized in the same way. The only witness they have is the surviving young woman, who can communicate only through blinking. Photographs found at one of the crime scenes lead the team to a couple that had sponsored one of the victims, and the boyfriend who claims he hasn''t spoken to her in weeks.', 43, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 2, 'Creatures of the Night', 'Junkie Jordy Thompkins was shot dead in an alleyway, but the bullet that killed him is missing. Taylor and Hawkes soon realise that a rat may have eaten the bullet, and finding the rat leads them to a robbery that occurred earlier that day. After Robin Prescott is found raped and beaten in Central Park with only a peony leaf on her clothing, Stella and Flack have the daunting task of trying to find the man who raped her, but Prescott has no memory of the crime.', 42, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 3, 'American Dreamers', 'After a skeleton is found on a tour bus and turns out to be over a decade old, Mac and the team use the backpack they have found to track the belongings to a young man named Aaron Moreland, only to learn that the body they have cannot possibly belong to him. By tracing the victim''s shirt, detectives are led to a youth center worker who claims not to remember the boy, but is hiding an old secret of his own.', 43, '2004-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 4, 'Grand Master', 'On the very night that he wins a D.J. competition, DJ Banner is found dead in an alleyway outside the club where the contest is being run, prompting Mac and Flack to investigate not only the club but also Banner''s primary competition, who was jealous that his girlfriend''s voice was part of Banner''s act. Stella and Danny investigate the death of fashion designer Deborah Gayle, found face-down in the pool at her apartment by her assistant, who isn''t concerned by her boss''s demise. An autopsy reveals that the cause of death was poisoning by tetrodotoxin, a poison found in blowfish, which leads Stella and Danny to Fuqua Sushi.', 42, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 5, 'A Man a Mile', 'Stella and Aiden investigate after finding the body of a teenage girl in a creek. They soon realize that she was a middle-class girl attending a fancy school who was trying to make it seem like her family had more money than they did, and trace her movements to a nightclub. Mac and Danny investigate when a body is found in the tunnels without any protective gear on, and end up running into a brick wall when the Sandhogs union blocks many of their attempts to get information about the victim.', 42, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 6, 'Outside Man', 'Two cases. One involves multiple homicides at a restaurant and the other starts with an amputated leg found in a dumpster.', 45, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 7, 'Rain', 'When the charred bodies of two men who had been robbing a Chinatown bank are found, the entire team investigates the crime, which leads them to Doris, the missing infant of the bank''s manager. The team realises that Joanna Cho assisted with the robbery out of fear for her daughter''s life. Mac and Stella finally manage to track down the third robber, only to find him lying in a pool of blood, with a trail of bloody baby handprints leading away from the body.', 43, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 8, 'Three Generations are Enough', 'Danny and Mac investigate after a briefcase belonging to Luke Sutton is found left in the NYMEX with a bloody note inside. Their investigation into Sutton''s activities lead them to Nick Lawson, whom Sutton had been investigating for illegal trades, but who swears he had nothing to do with his disappearance. Stella and Flack investigate the death of Trina Rolston, a young pregnant women who fell to her death from the roof of a church. With Hawkes help, Stella realises that the body was thrown off the roof to mask the true cause of death. The detectives soon realise that their two cases are connected.', 44, '2004-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 9, 'Officer Blue', 'After mounted officer Valasquez is shot down in the park, Mac goes looking for the bullet that killed the officer only to learn that it is lodged in the horse''s spine and cannot be removed without being fatal to the horse. The investigation leads them to a local street vendor, but stalls when the D.A. asks Mac not to do anything to risk the horse until after the woman who donated it has a chance to say goodbye. Aiden investigates the body of a young man, Lenny Starks, who was found face-down, dead in the street. Aiden traces the young man to a local pizza parlor where she faces intimidation from the bookies who use it as a gambling front.', 44, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 10, 'Night, Mother', 'Mac and Stella investigate the murder of a woman who was stabbed in the heart with a wooden stake. The police arrest a woman who was kneeling over the body with blood on her, but Mac isn''t convinced that she committed the crime.', 43, '2004-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 11, 'Tri-Borough', 'A young John Doe, nicknamed ''Slick'', is found lying across the rails of an underground subway. At first, he appears to have died from third-rail electrocution, but an autopsy suggests that he may have met his end by other means of electrocution. Meanwhile, Leo Whitefield is found shot dead at close range in a gallery he owns, with no sign of break in or theft, and a construction worker turns up with a fatal injury to the head.', 42, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 12, 'Recycling', 'Mac, Aiden and Flack investigate when Elaine Curtis is found dead at a dog competition, a knitting needle sticking out of her chest, and no shortage of suspects ranging from judges to trainers to contestants. Stella and Danny investigate the death of bicycle messenger Michael Starling, but the crime scene may have been anywhere along his route.', 44, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 13, 'Tanglewood', 'The detectives investigate a murder at a grocery store that is also connected to the death of a young man with the tattoo "Tanglewood" on his back. A third case involves a woman who was killed in a hit-and-run auto accident.', 45, '2005-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 14, 'Blood, Sweat & Tears', 'The body of a young contortionist is found folded into a box on Coney Island, leading Mac and Stella to the circus where they find themselves embroiled in a real-life Romeo and Juliet story between the dead contortionist, Lukas, and a trapeze artist, Anasuya. Danny and Flack find a woman''s body in a laundry chute and learn that she was actually the former sorority sister of the woman who lived in that building, and turn their suspicion to the abusive husband the woman was hiding from.', 42, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 15, '''Til Death Do We Part', 'The team''s investigation into the death of Hannah Bloom, who died at her own wedding, is put on hold when her father refuses to allow them to perform an autopsy until after his daughter''s body is blessed by a rabbi. Danny and Mac turn their attention to the woman who trained the doves who were supposed to be released, but cannot tie her directly to Bloom, who died from formaldehyde poisoning. Stella, Flack and Aiden investigate when a hand is found deep underground, and soon realise that the dead man, Rick Amadori, chewed off his own hand. It seems like a slam dunk when the son of a man Amadori killed three years earlier confesses to the crime, but things aren''t as easy as they seem.', 44, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 16, 'Hush', 'A woman''s death leads our detectives to a school for sexual fetishes such as bondage and spanking.', 44, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 17, 'The Fall', 'When young gang members murder the owner of an upscale Bronx wine store, the CSI’s must work to find evidence that ultimately ties someone to the crime. Tempers flare when the murder investigation reunites Detective Flack with his long-time mentor and friend Sergeant Gavin Moran, who was the first to arrive at the crime scene. Meanwhile, Danny and Aiden investigate the death of an influential movie producer found dead on the canopy of his Chelsea apartment building.', 42, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 18, 'The Dove Commission', 'When the chief investigator of a controversial report documenting corruption within the NYPD is gunned down the day before his findings are published, Mac and Stella must find the killer, launching a massive search that makes every officer listed in the report a suspect. Meanwhile, Danny and Aiden investigate the murder of a gypsy cab driver.', 41, '2005-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 19, 'Crime and Misdemeanor', 'When the body of a young woman is discovered at a laundry facility, the bed sheets she is wrapped in lead Mac and Stella back to an upscale New York hotel that houses diplomats from around the world when the United Nations is in special session. Meanwhile, Danny and Aiden investigate the death of a homeless man found dressed as a human statue. By all accounts, the prank is deemed a misdemeanor, but Danny decides to delve further and his refusal to stop the investigation puts him at odds with Mac.', 42, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 20, 'Supply and Demand', 'When a college student is beaten, shot to death and his apartment ransacked in what appears to be a drug-related hit, the team must track down his killers. After examining the evidence in the murdered student''s apartment, the team finds traces of pure, unprocessed heroin and discovers that the victim had a female roomate who is now missing. Meanwhile, Stella''s aggressive interrogation tactics with a witness threaten her police badge.', 42, '2005-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 21, 'On the Job', 'A nanny is found dead near a park while Messer is in trouble when he may have shot another police officer.', 43, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 22, 'The Closer', 'The team examines the murder of an avid Boston Red Sox fan found dead with a ruptured spleen following a tough loss against New York. Danny must put his baseball skills to the test to piece together the evidence as the CSIs try to find out how and why he was murdered. Meanwhile, after testifying in a murder trial, Mac is confronted by the defendant, Quinn Sullivan, who questions the validity of the evidence. Mac is torn between trusting science or his desire to help a man facing jail time who swears he''s innocent. Also, when a truck kills a barely clad woman early one morning, the team investigates why she was running through the streets and from whom.', 41, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 1), 23, 'What You See Is What You See', 'While Mac dines at his local breakfast spot, a gunman opens fire, leaving a waitress critically injured and a man dead, and Mac having to choose whether to chase after the suspect or save the life of the young woman. Meanwhile, before the chaos, Mac was approached by a shy patron who awkwardly engaged him in conversation. After feeling that he saved her life during the shoot out, she asks him to join her for a drink and Mac must decide if he is ready to start dating after his wife''s tragic death.', 41, '2005-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 1, 'Summer In The City', 'Stella and Danny investigate when a jewellery designer is found dead, wearing the eight million dollar bra he created, and investigate the model he had shot and her bodyguard. Aiden begins to take the rape case she has been working on a little too personally, and is determined to stop the man before he can rape again. Hawkes gets to go into the field for the first time as he assists Mac in investigating the death of a man who liked to climb skyscrapers.', 44, '2005-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 2, 'Grand Murder at Central Station', 'Stella and Danny are heading into the world of cuddle parties: non-sexual events were adults learn to touch and hug each other. Meanwhile, Mac, Hawkes, and Flack investigate the death of a hated plastic surgeon found covered with lye with thousands of eyewitnesses during rush hour at Grand Central Station. While Mac and Stella assist Aiden in a rape case, after she breaks an evidence seal, Mac must come to terms with Aiden''s action and work up the nerve to fire her.', 45, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 3, 'Zoo York', 'Mac and Danny look into the mysterious death of a man torn apart by tigers at the Bronx Zoo, which leads them to both the dead man''s meat packing plant as well as his mafia relatives. Hawkes and Stella are left with the case of a beautiful young debutante found dead on the carousel only hours before her coming out.', 44, '2005-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 4, 'Corporate Warriors', 'Three cases. A murder during the Feast of San Gennaro with ties to a financial services company. A body sitting upright on a Central Park bench. An apartment fire where a 10-year-old boy died of smoke inhalation.', 42, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 5, 'Dancing With The Fishes', 'Mac, Stella and Flack investigate the death of a young dancer who recently won the lottery, and it isn''t long before they realise that her death is connected to Lindsay''s investigation concerning the death of a tram driver. Danny and Hawkes look into the murder of a local fish merchant, and soon find their way to a jealous friend who was angry that their child didn''t get into a prestigious school.', 42, '2005-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 6, 'Youngblood', 'When a man is found murdered in an elevator, Mac, Flack, Danny and Lindsay investigate a world where very young girls enjoy sexual encounters with much older men. They''re left trying to determine whether their best lead is a suspect, a witness ... or the intended victim. Stella and Hawkes investigate the death of a young man found in Central Park who died from an extreme allergic reaction and learn that he had been pretending to be someone that he wasn''t.', 44, '2005-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 7, 'Manhattan Manhunt (II)', 'Horatio Caine follows Henry Darius to New York so that he can keep his promise to a young boy in Miami, but by the time he and Mac are able to locate Darius he has disappeared again, leaving behind six more bodies.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 8, 'Bad Beat', 'Mac and Stella investigate a murder of a host of a high stakes poker game after a player was caught cheating and kicked out of the game. While Danny and Hawkes follow the clues that''ll lead them to solve the death of a weather girl.', 44, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 9, 'City Of The Dolls', 'Mac, Danny and Lindsay investigate the death of owner of a doll hospital. Stella and Hawkes look into the death of a woman with terminal cancer.', 45, '2005-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 10, 'Jamalot', 'Mac and Stella work on the case of a female roller derby player. Danny and Hawkes look into the murder of one of New York''s upcoming crop of writers.', 43, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 11, 'Trapped', 'Danny and Stella find innovative ways to process a crime scene while Danny is trapped in a panic room with the victim, who was the only person with the security code. As a locksmith works to cut through the titanium doors, the CSIs rush to process the evidence before the victim decays further and Danny''s oxygen runs out. Meanwhile, Mac, Dr. Hawkes and Lindsay investigate the murder of an exotic dancer found dead on a klieg light', 45, '2005-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 12, 'Wasted', 'Mac, Danny, and Dr. Hawkes investigate the death of a runway model who collapsed during a fashion show.  Meanwhile, Stella, Detective Flack, and Lindsay investigate a teriminally ill patient''s confession to the murder of his doctor.', 43, '2006-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 13, 'Risk', 'Danny is on his way home after a long shift and finds Randy Williams subway surfing. Mac and Lindsay arrive on the scene and begin to wonder if Randy Williams died from riding on top of the subway. His death is even more suspicious after they examine the body more closely.', 44, '2006-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 14, 'Stuck On You', 'Stella is invited to an art gallery where she sees several paintings done by an artist named James Golden. Stella thought she was going to Frankie''s place and not to an art gallery. Outside the exhibit two people are kissing and one of them is shot in the back with an arrow.', 44, '2006-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 15, 'Fare Game', 'Lindsay, Stella, and Mac are on the case of a dead ADA, who they discover, is involved in a "kill war" with water guns.  Meanwhile, Danny and Hawkes investigate the murder of a young lady who had a penchant for suing restaurants and taking them for all they are worth.', 43, '2006-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 16, 'Cool Hunter', 'After the body of a dead woman is found in a water tower the team suddenly realizes that the building may hold a bigger mystery than they expected.', 44, '2006-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 17, 'Necrophilia Americana', 'A young boy witnesses the death of a museum curator but doesn''t want to tell anyone about it. Danny investigates the death of an urban golfer found dead on a construction site.', 44, '2006-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 18, 'Live or Let Die', 'The life of a transplant patient hangs in the balance as the team tries to find the hijacked plane carrying the liver.', 45, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 19, 'Super Men', 'A man dressed in a superhero costume is found dead in an alley, after saving a man being mugged.  Mac, Stella, and Dr. Hawkes find his clothes in a nearby phone booth.  Danny and Lindsay investigate the murder of an NFL first-round draft pick, known as "Superman."', 44, '2006-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 20, 'Run Silent, Run Deep', 'Mac receives a phone call confessing to an old murder before the caller commits suicide. The call leads the team to a football stadium to uncover a body and they learn the suicide victim belongs to the Tanglewood gang. They also find a cigarette that puts Danny''s job on the line after his DNA is found on it.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 21, 'All Access', 'Mac and Lindsay question Kid Rock because he was the last person to see his limo driver alive when the driver is found dead in the alley just before Kid Rock’s encore performance concert.', 43, '2006-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 22, 'Stealing Home', 'Two women both claim to be the wife of a murder victim surprise Mac and Stella at the circumstances of their relationships.  Both women have been in a trinogamous marriage with the victim. Meanwhile, Danny and Lindsay investigate the murder of a young woman who is found off a dock tangled up in kelp while she is dressed as a mermaid.', 45, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 23, 'Heroes', 'Mack and Danny investigate a Marine found dead in Central Park during Fleet Week. The evidence doesn''t add up and who is Ellie? Stella, Lindsay, and  Hawkes investigate a dead body found in a burnt out car. The results of their investigation leads to a devastating loss for the whole team.', 44, '2006-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 2), 24, 'Charge of this Post', 'After a routine call leads two of the team into finding a bomb, they evacuate  but a few are still in the building along with Mac and Flack when the bomb detonates. After the explosion the CSI''s face a race against time to find the bomber and the possibility of losing one of their own. Mac must come to grips with having let a Marine die in Beirut in 1983.', 44, '2006-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 1, 'People With Money', 'The body of a man is discovered on the Brooklyn Bridge, and the only evidence is a huge marriage proposal in lights.  The CSI team works through the investigation as they learn to deal with a new medical examiner.', 43, '2006-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 2, 'Not What It Looks Like', 'Three women who are dressed as Holly Golightly rob a jewelry store and injure other shoppers in the process.  The CSI’s must work through the confusing investigation to hunt them down. Meanwhile Mac has to identify a mummified body discovered in an apartment building that was being torn down.', 45, '2006-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 3, 'Love Run Cold', 'Danny and Lindsay examine the murder of an ice princess at a vodka release party while Mac, Stella, and Don examine the death of a runner at a Marathon in Central Park. Both crimes have interesting problems the teams must overcome to find out how they both happened.', 42, '2006-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 4, 'Hung Out to Dry', 'The body of a beheaded woman found in a fraternity house is a mystery to the CSIs. Now they must sort through twisted clues and crime scene after crime scene to find the killer that has them trapped in his own little game.', 43, '2006-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 5, 'Oedipus Hex', 'The CSI''s handle to puzzling cases; Carensa is a young Suicide Girl who at 17, wanted a change of scenery and to become a Suicide girl, at 18 she gets her wish only to lose her life.  Chopper, a rising street basketball star, a homeless man trying to change his life for the better is killed and leaves a painful trail of blood which leaves Mac to figure out where and how he died.', 45, '2006-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 6, 'Open and Shut', 'The CSIs are investigating the murder of a hotel concierge, but while doing this  they hear gun shots fired across the street and find a woman clutching a gun over two dead bodies.', 43, '2006-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 7, 'Murder Sings the Blues', 'A young woman dies after she starts bleeding from the eyes, nose, and mouth while at a party aboard a subway train. Mac originally believes she is the victim of a biological attack. Later, it is revealed that Sheldon knew the victim. Across town, a wealthy playboy is found dead in an indoor lap pool in his penthouse suite. The investigation reveals that he was murdered and his last maid was fired two days earlier.', 43, '2006-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 8, 'Consequences', 'The next case for the CSI’s gets even tougher when a paintball player turns out to be the prime suspect and later goes missing the team also has another problem the evidence that should point to the prime suspect points to someone else.', 44, '2006-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 9, 'And Here''s To You, Mrs Azrael', 'The next case takes us back to Dr. Sheldon Hawks'' past and the reasons he chose to change jobs in the medical profession. The CSI team may find it extremely difficult to find out who committed the murder of the 19-year-old woman who recently started recovering from an accident.', 44, '2006-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 10, 'Sweet Sixteen', 'The team is led to a crime scene in the middle of the city involving a parachute jumper whose parachute apparently failed. And one CSI is injured when a snake is found at a crime scene.', 44, '2006-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 11, 'Raising Shane', 'After a bartender is murdered The CSI team must prove that Hawkes did not commit the murder.  That only becomes more difficult when the team is pulled off the investigation.', 43, '2006-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 12, 'Silent Night', 'The CSI team has a problem after learning the family is deaf: now they have to find a new way to catch the killer. Meanwhile, more information is given on Lindsey''s horrifying past and what led her to become a CSI.', 41, '2006-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 13, 'Obsession', 'The team must find out if one team’s fun led to murder in the New York version of the Iditarod. Another case involves the death of a kidnapper in an empty apartment  and where is the kidnap victim?', 43, '2007-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 14, 'The Lying Game', 'Can knowing a secret be a motive for murder?  The CSI team must figure out if a change in gender is cause for the death of a showgirl.  Also Lindsay goes back to Montana to try to put the person who committed the murder of four friends behind bars.', 41, '2007-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 15, 'Some Buried Bones', 'Reed Garret gives Mac some interesting information regarding the death of a college student.    Also the rest of the team will need to be a step ahead of Ava Brandt to figure out why a security guard was murdered.', 43, '2007-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 16, 'Heart of Glass', 'Mac may have a difficult time solving the murder of a music mogul the sister cleverly uses a lie detector test to cover up the crime.  Stella wonders if she has HIV due to an accident.', 43, '2007-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 17, 'The Ride-In', 'Danny and Mac have to go to Noah’s Ark to find out if a broken promise leads to his murder. Stella and Sheldon investigate the death of a man dressed as a cigarette. Stella hopes to have her job after not telling Mac that she may be HIV right away.', 43, '2007-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 18, 'Sleight Out of Hand', 'Illusionist Luke Blade may have to defend the art of magic after an illusion is thought to have killed two people.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 19, 'A Daze Of Wine And Roaches', 'At a French Revolution themed fundraiser at the UN, specifically at the French consulate, Mac, Stella and Hawkes find themselves hurdling diplomatic road blocks investigating two murders.  Meanwhile, Danny and Lindsay reunite on a “blinged” out cockroach that lead to murder.', 42, '2007-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 20, 'What Schemes May Come', 'The team finds itself investigating the murders of three different people, only to discover that two of the murder victims are linked and may have been killed by the same person. One of these cases becomes personal for Mac.', 44, '2007-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 21, 'Past Imperfect', 'Trouble begins for Mac when Clay Dobson becomes a free man due to a mistake he made. Stella learns the results of her HIV test from Adam.', 41, '2007-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 22, 'Cold Reveal', 'Mac believes he can fight the internal affairs investigation that is about to be started against him because of what happened to Clay Dobson. Can Mac explain what happened to the suspect he was chasing and will it be good enough for him to keep his job? Also Stella could lose her job as a CSI after a cold case is somehow connected to her.', 44, '2007-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 23, 'Comes Around', 'Can the team clear a tennis legend of murder? Also Mac believes that the continuing investigation into what happened with Clay Dobson is nothing but media pressure. Can friends and colleagues help save Mac Taylor’s career before it’s too late?', 42, '2007-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 3), 24, 'Snow Day', 'After Flack makes an enormous drug bust, and locks it up at CSI, the drug lords infiltrate the building at gunpoint to get them back. Now the team must resolve the hostage situations, all the while with Mac, Stella, and Hawkes trapped inside.', 43, '2007-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 1, 'Can You Hear Me Now?', 'The team find themselves investigating something that isn''t usually on the Statue of Liberty. Can a musician''s life be saved before time runs out?', 43, '2007-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 2, 'The Deep', 'Sheldon Hawkes goes under water to gather clues but could be in danger when he can''t come up for air. Mac learns of something else under water.', 40, '2007-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 3, 'You Only Die Once', 'After a series of heists in the city (one including Det. Chief Sinclair''s house) one of the "super spies" involved is robbed of his life.  The team works to solve the robberies and the murder, as both are obviously connected.', 41, '2007-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 4, 'Time''s Up', 'Is it possible to solve a murder 24 hours before it happens? Mac wonders if the suspect traveled through time to know about the murder in advance.', 43, '2007-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 5, 'Down The Rabbit Hole', 'The latest murder case takes Detective Taylor to a whole new world and he must figure out why Cheryl Duncan looks so life-like. They also discover something shocking about the murderer while online.', 43, '2007-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 6, 'Boo', 'The CSI team goes to a haunted house to solve more than just the latest case.  Before they can solve the crime Lindsay is told something will happen to her if she doesn''t leave soon.', 43, '2007-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 7, 'Commuted Sentences', 'The team has two cases tonight and two great tourist locations: Madison Square Park where a man is stabbed to death, and the Metropolitan Museum of Art, where a woman is shot dead on the steps.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 8, 'Buzzkill', 'New York City has everything: Times Square, billboards, parties, and a dead model in a giant martini glass. Now the team must find a party crasher who crashed one party too many.', 43, '2007-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 9, 'One Wedding and a Funeral', 'What would otherwise be a happy wedding goes sour when the groom... turns up dead: inside a wedding present.  After Stella finds bloody puzzle pieces inside a box on her car, Mac heads home to Chicago to solve what could be the murkiest mystery of his life.', 44, '2007-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 10, 'The Thing About Heroes', 'While in Chicago Mac uncovers more clues about his stalker and reveals his troubled past. Meanwhile, in New York the rest of the team is in danger. The hunt is on to figure out the identity of the 333 stalker before time runs out.', 43, '2007-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 11, 'Child''s Play', 'Danny is devastated when a young boy he knows is killed in the midst of a bodega robbery. Meanwhile, Lindsay, Stella and Flack investigate the death of a man killed by an exploding cigar that is connected to a joke shop proprietor and another tragedy that occurred years before.', 44, '2007-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 12, 'Happily Never After', 'Mac and the team feel they''re headed back to Kansas when they find the victim''s body with red shoes on her feet crushed to death under an unusual object. The team learns about pop up parties after finding a body.', 42, '2008-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 13, 'All in the Family', 'In this episode Mac and his team must figure out how a woman''s death and a judge''s murder are connected.   Danny has trouble dealing with Ruben Sandoval''s death.', 42, '2008-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 14, 'Playing With Matches', 'The team must figure out how a self-cleaning restroom leads to a drowning.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 15, 'DOA For a Day', 'After the CSI''s receive an anonymous tip they''re led to an old warehouse hoping to catch one of New York''s most-wanted criminals.', 43, '2008-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 16, 'Right Next Door', 'Stella''s life is in danger after her apartment is on fire; she must try to save everyone in the building.  The team also has a mystery to solve after finding a dead body in Stella''s apartment building.', 44, '2008-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 17, 'Like Water For Murder', 'The team must figure out how a young woman and a shark end up dead on the beach at the same time. This case gets even more interesting when a second body washes up on the beach.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 18, 'Admissions', 'When a guidance counselor is murdered at a private school, the mayor orders Mac and his team to drop everything to find out what happened. Mac is frustrated because he can''t devote the man hours or the personnel to finding the "Taxi Cab Killer".', 42, '2008-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 19, 'Personal Foul', 'As the search for the taxi cab killer continues riding a cab gets very deadly. The team must figure out how to keep New York City safe.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 20, 'Taxi', 'Mac and his team finally believe they have captured the taxi cab killer but there is one problem - he is found dead. Mac must figure out how to keep the streets of New York City safe while continuing to track the elusive taxicab killer', 41, '2008-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 4), 21, 'Hostage', 'When a man takes hostages during a failed attempt to rob a bank, Mac offers himself in exchange for a hostage. Only condition is that he must prove that the bank robber did not kill the bank manager, whose body is found lying in a pool of blood in the vault. On the outside of the bank, the rest of the team works to process the evidence that Mac finds and stop the SWAT team from making matters worse.', 42, '2008-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')), 5, 'Season 5', NULL);
