INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 8, 'Late Admissions', 'The CSIs must delve into the high-pressure world of an elite prep schools when a student is murdered while studying for the SAT''S. Meanwhile, Lindsay returns home to Montana to visit her father and deal with some issues from her past.', 45, '2012-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 9, 'Blood Out', 'When Det. Lovato''s cover is inadvertently blown, the CSI''s investigate the Latin street gang she infiltrated when undercover.', 44, '2012-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 10, 'The Real McCoy', 'The CSIs investigate a 1920s-inspired speakeasy when one of its owners is murdered and $10,000 goes missing. Meanwhile, Adam spends his day off in an unexpected way.', 45, '2012-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 11, 'Command+P', 'The CSIs are confronted with a puzzling mystery when two different victims are linked by the same unusual weapon.', 43, '2013-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 12, 'Civilized Lies', 'When a beloved off-duty NYPD officer perishes in a robbery, the CSIs use the art of interrogation to break down their suspects and get to the truth.', 45, '2013-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 13, 'Nine Thirteen', 'The CSIs investigate when a masked man is found at the bottom of a notorious skyscraper known for its history of mysterious deaths. Meanwhile, on her day off, Jo runs into a stranger with a surprising link to her past.', 45, '2013-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 14, 'White Gold', 'When a young pizza maker is carjacked, the CSIs must determine what the perpetrators were really after.', 42, '2013-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 15, 'Seth and Apep (2)', 'Mac and the team partner with D.B. Russell to outsmart Christine''s kidnappers before they run out of time to save her life.', 43, '2013-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 16, 'Blood Actually', 'On Valentine''s Day, Mac and the team tackle three twisted tales of love gone wrong.', 45, '2013-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0395843')) AND numero_temporada = 9), 17, 'Today Is Life', 'Community unrest over the police shooting of an unarmed man forces Mac and the team to move quickly to solve the case.', 43, '2013-02-22');
