INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 1, 'Head Cases', 'A civil-rights issue hinges on the casting choice for a version of "Annie"; a child-custody battle turns ugly; an adultery case involves Crane.', 43, '2004-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 2, 'Still Crazy After All These Years', 'An ex-lover haunts Shore, who secures the woman''s release from a psychiatric hospital where she was confined after trying to kill him. Elsewhere, Crane fights an opposing counsel''s sanction charges.', 43, '2004-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 3, 'Catch and Release', 'A client of Crane, Poole & Schmidt want to build a shopping mall on an area where salmon are spawning and Denny''s son is the environmental lawyer defending the area. Alan and Lori take a sexual harassment case and learn that Christine, whom he recently helped get released from a mental institution and who he now fears is stalking him, is opposing counsel. Sally has her first trial case where she defends a man who is accused of stealing a wallet.', 43, '2004-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 4, 'Change of Course', 'A cop killing centers on a haughty defendant, reluctantly represented by Lori and zealously by a firm veteran, who has been a patient in a mental facility. Meanwhile, Shore plays hardball with a witness in a shoplifting case involving a kleptomaniac CEO.', 43, '2004-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 5, 'An Eye for an Eye', 'Seniors take on a drug firm in a class-action case handled by the grandstanding Crane. Also: revenge motives are raised in a murder trial; and medical ethics are at issue in a civil suit.', 43, '2004-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 6, 'Truth Be Told', 'Shore''s dream lover from college, now wed to a slick mayoral candidate, hires Shore to block his opponent''s provocative TV-ad campaign. Meanwhile, a power struggle embroils Crane.', 42, '2004-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 7, 'Questionable Characters', 'A showcase for the wily, agitating Alan Shore, who badgers a dotty judge; romances Tara, whom he surreptitiously helps in a thorny criminal case; and backs Crane, who''s been arrested for solicitation.', 42, '2004-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 8, 'Loose Lips', 'Alan help a department store Santa sue to get his job back after he is terminated for being a transvestite. Brad bets Alan that he won''t win. A therapist seeks Lori''s help when one of his patients fantasizes about killing his ex-wife.', 41, '2004-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 9, 'A Greater Good', 'Alan and Denny defend a drug company that is being sued by a woman who states they provided false reasoning when they took her off of an experimental pill that was a possible cure for her sickness. Alan and Denny discover a shocking secret that could make or break their case and because of that, they become at odds with each other on how to proceed. Lori discovers that Tara''s new information for their case would win it for them, but the way she retrieved it could cost them their case and their careers. Lori learns a secret about Brad.', 43, '2004-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 10, 'Hired Guns', 'Lori and Brad defend a woman who is accused of murdering her husband and his mistress while they were in bed together. Alan''s life is endangered when he helps a woman whose ex-husband plans to kidnap their children.', 41, '2004-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 11, 'Schmidt Happens', 'A Sudanese native wants to sue the U.S. government for the lack of action taken against the mayhem happening in his country and Paul looks to Lori to take the case. Founding partner Shirley Schmidt arrives with a mission to bring order to the firm. While making herself known, she has to deal with Denny who does not wanting her there, help with Lori''s extremely high profile case, and learns that she has to keep her eye on Alan. Alan ends up defending a man who killed his mother in a fit of rage but by accident.', 41, '2005-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 12, 'From Whence We Came', 'Lori, along with Denny and Shirley, defends a school superintendent who fired two science teachers because they refused to teach creationism and is now being sued by them. Alan learns his assistant has expressed concern about their work relationship. While dealing with that issue, Alan discovers that his client Bernard Ferrion, who killed his mother, needs legal help again. One of the members of the firm is fired and learns that a close associate is not too keen on lending a supportive hand.', 43, '2005-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 13, 'It Girls and Beyond', 'Brad becomes attracted to his client who being sued for having a relationship with her boss merely for financial purposes. To make matters more difficult, Brad convinces himself that she is lying about her being a lesbian. Alan is asked to second chair on Denny''s trial case where a doctor is being sued for prescribing a drug that has not been FDA approved. While working on that, Denny is on a personal mission to prove that he is a competent attorney. Meanwhile, the staff tries to deal with Alan''s out-spoken new assistant, Catherine Piper.', 42, '2005-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 14, 'Til We Meat Again', 'While out with Tara, Alan ends up causing a bar room brawl and as a result, becomes arrested for conspiracy to commit assault and battery. Shirley and Denny represent a man whose steakhouse is being put out of business because the public wants to ban red meat for fear of Mad Cow disease.', 42, '2005-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 15, 'Tortured Souls', 'Shirley asks Alan Shore to use his odious lawyering to help her defend a police officer accused of torture. Donny Crane returns and is the opposing counsel in Denny''s case, with Chelina Hall as second chair, where a woman wants to sue her former boyfriend for saying no to her at the alter. For Denny, this is an easy case, for Donny this is to settle a score with Denny for letting him believe for 25 years that he was his father. Meanwhile, Bernard Ferrion is befriended by Catherine and Alan finds variance with that.', 42, '2005-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 16, 'Let Sales Ring', 'Milton Bombay is asking the courts to allow him to be frozen until another century so he can continue his legacy of being a great lawyer and needs Denny and Shirley to defend him. Alan and Chelina defends a high school student who accuses his teacher of censorship when he blocks out a news station on the school''s televisions.', 42, '2005-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 1), 17, 'Death Be Not Proud', 'Chelina asks Alan to assist her in Texas because her former client is getting executed but may be innocent of the crime. An old friend of Denny and Shirley asks them for legal representation when she charged with having sexual encounters for a fee. Lori files a complaint about Denny with Shirley and Paul and they seriously consider doing something about it; especially when they suspect he performed an unethical act on his recent case.', 43, '2005-03-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 1, 'The Black Widow', 'Alan Shore and Brad Chase represent Kelly Nolan who is on trial for poisoning her husband. Meanwhile, Tara Wilson second-chairs for Shirley Schmidt and is shocked to find that the opposing counsel is her former lover, Malcolm Holmes. Garrett Wells and Sara Holt assist Denise Bauer on a case where a Jewish man felt violated when his Christian co-workers held Bible readings in the workplace. To make things worse, Denise is served with divorce papers.', 43, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 2, 'Schadenfreude', 'The Kelly Nolan trial continues, but Alan, Denny and Brad run fear the worst when Kelly''s cold demeanor begins to turn off the jury. Meanwhile, Garrett and Sara are enlisted to help Denise in her divorce settlement and Malcolm convinces Tara to represent Johnny Damon, Edwin Starr''s nephew, whose performance of War strikes a nerve at a nightclub.', 43, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 3, 'Finding Nimmo', 'Denny takes Alan to Nimmo Bay, British Columbia, Canada, to help him get over his breakup with Tara. Catherine confesses to Bernard''s murder. Sara and Garrett take extreme measures to help Denise challenge her husband''s alimony demands in their divorce proceedings.', 43, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 4, 'A Whiff and a Prayer', 'Denny''s strong conservative values are put to the test when the firm represents a Democratic congressman who refused to keep a promise to his supporters. Alan tries to forget about Tara as he prepares to defend Catherine who is on trial for murder. Meanwhile, Sara is given a bizarre ultimatum.', 43, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 5, 'Men to Boys', 'Denise finds herself in a difficult position when an auto-injury case she neglected for three years comes up for trial and she is unprepared. While Garrett researches, he meets Cassie, a young paralegal whose strange sexual tendencies hide a painful past. Meanwhile Denny learns he must apologize to Lori or face a sexual harrassment suit, and Alan takes Sara out for dinner and a "show."', 43, '2005-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 6, 'Witches of Mass Destruction', 'The firm takes on two milestone cases. First, Shirley and Denise represent Christian and Wiccan parents who are outraged by a public school''s Halloween celebrations, but the case takes a turn for the worse when the clients begin arguing amongst themselves. Meanwhile, Denny and Alan''s friendship is tested when Alan helps Cassie sue the US military for the loss of her brother.', 43, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 7, 'Truly, Madly, Deeply', 'Denny is called to defend a man who raped and killed a 13-year-old girl, but decides he''d rather go to jail than spend his days defending murderers. Meanwhile, Alan must face his fear of clowns and Shirley dumps a bizarre bestiality case on Denise.', 42, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 8, 'The Ass Fat Jungle', 'Denise finds herself wanting to sue her own client when Boston''s most celebrated plastic surgeon is under fire for unorthodox techniques. Shirley takes on a difficult case involving an Alzheimer''s patient which touches her personally. Meanwhile, Alan and Denny fight their own demons as Alan asks his new secretary to protect him from night terrors and Denny undergoes an MRI.', 43, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 9, 'Gone', 'When the FBI''s hands are tied with red tape, Brad helps Denise go undercover as a rogue agent in order to find a missing boy who is close to her heart. But when legal and ethical roadblocks appear, they must make some difficult decisions.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 10, 'Legal Deficits', 'After kidnapping a witness and physically assaulting a priest, Brad is put on trial and enlists the help of Denny and Shirley to bail him out.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 11, 'The Cancer Man Can', 'Paul recruits Denise to help him defend a cancer patient who used his wealth to guarantee he would not get a placebo during a drug study.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 12, 'Helping Hands', 'Alan finds himself all alone against the firm when he decides to defend Jerry Espenson from charges of attempted murder, torture and terrorist threats.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 13, 'Too Much Information', 'Alan and Denise take on the case of a young girl whose father killed her mother after finding the mother''s whereabouts through her HMO''s website.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 14, 'Breast in Show', 'After meeting Irma for a date, Alan finds himself defending her when she is charged with a sex crime by protesting topless.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 15, 'Smile', 'Alan''s friendly demeanor quickly turns into anger when a prestigious private school turns away a child prodigy because she lacks the face muscles to smile.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 16, 'Live Big', 'Alan and Denny defend a man charged with murder after he euthanized his wife with Alzheimers.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 17, '...There''s Fire!', 'Shirley, Paul and Brad batten down the hatches as Bev files for divorce hours after her marriage to Denny, and demands half of his assets.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 18, 'Shock and Owww!', 'Shirley covertly asks Alan for help when nude photographs of her surface for auction.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 19, 'Stick It', 'Alan once again goes to bat for Melissa, this time with much less confidence, who is in serious trouble with the IRS.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 20, 'Chitty Chitty Bang Bang', 'Shirley defends a long-time client who doesn''t want his Victorian erotica collection lost in his divorce, but she is shocked when Ivan is opposing council.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 21, 'Word Salad Days', 'After beginning to speak gibberish in court, Alan turns to Denny for help in curing his new, debilitating condition.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 22, 'Ivan the Incorrigible', 'Alan decides to help Jerry with his first big attempted-murder case, but has to take drastic action when Jerry''s courtroom outbursts jeopardize the case.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 23, 'Race Ipsa', 'When Denny shoots his therapist in self-defense, the senior partners, fed up with his rogue behavior, begin to enact plans to remove him from the firm.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 24, 'Deep End of the Poole', 'Name partner Edwin Poole returns from a mental institution to Crane, Poole and Schmidt, ready to jump back in, but Shirley has reservations when he decides to sue a candy company.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 25, 'Squid Pro Quo', 'Denny once again goes head-to-head with his non-son, Donny, when he shows up in his new role as a Lawyers Without Borders representative. But Alan finds it difficult to support Denny''s defense when Denny makes light of the case.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 26, 'Spring Fever', 'Shirley once again helps Professor Cabot, whose research into human sexual behavior gets him into trouble when he''s caught with a prostitute. Marlene and Denise continue their fight for the spot to become partner by trying to assist.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 2), 27, 'BL: Los Angeles', 'While in LA, Alan takes on the case of TV star Courtney Rae, who is arrested after shooting a photographer who she mistakes for a stalker. But Denny and Barry make life difficult when they won''t stop making sexual advances toward their client.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 1, 'Can''t We All Get a Lung?', 'Terminally ill Daniel Post needs Denise and Shirley''s help after running afoul of the law. Meanwhile, Alan defends Jerry after his driving habits lead to trouble.', 43, '2006-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 2, 'New Kids on the Block', 'Crane Poole & Schmidt''s new lawyer makes his mark while defending a man charged with killing a judge. Meanwhile, Denny''s Internet romance creates trouble at the firm, and Alan helps a cross-dresser who''s out of a job.', 42, '2006-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 3, 'Desperately Seeking Shirley', 'Shirley finds an unlikely--but familiar--foe in court when her ex-husband, Ivan, wants to get rid of his postnuptial agreement to his current wife. Meanwhile, Coho engages in questionable practices in an important case, and Denny''s online date avers that size doesn''t matter.', 42, '2006-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 4, 'Fine Young Cannibal', 'Denny is attracted to feisty lawyer Bethany Horowitz as they try a case against an HMO, and Alan grows more attracted to Shirley as they defend a homeless man accused of cannibalism. Meanwhile, Coho continues his defense of accused murderer Scott Little.', 42, '2006-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 5, 'Whose God is It Anyway?', 'The media spotlight intensifies as Coho''s high-profile murder case goes to trial; Alan finds himself defending Jerry Espenson--again--but also sees another familiar face in court; and Denny''s feelings for Bethany grow.', 43, '2006-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 6, 'The Verdict', 'A shocking allegation of Oedipal proportions in the Scott Little case threatens to torpedo Coho''s defense; Alan seeks outside help to breathe some life into his relationship with Sally.', 42, '2006-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 7, 'Trick or Treat', 'Halloween brings Denise startling news about Daniel Post; Denny meets Bethany''s mother; Jerry needs Alan''s help with a federal jury matter; and the fallout from the Scott Little case continues for Coho when he''s sued by the Hooper''s nosy neighbor.', 43, '2006-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 8, 'Lincoln', 'Shirley finds herself attracting the attention of the eccentric Lincoln Meyer; Denny, Bella and Bethany prepare themselves for the results of his paternity test; and Alan helps Jerry with his defense in a difficult murder case.', 42, '2006-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 9, 'On the Ledge', 'Lincoln''s obsession with Shirley takes a dangerous turn; Jerry and Alan''s collaboration in a murder trial leads to a scotch-and-cigar session, which makes Denny jealous.', 43, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 10, 'The Nutcrackers', 'Alan represents a mother fighting for custody of her preteen daughters, who happen to be white-supremacist singers; a woman reaches for the heavens to blame someone for her husband''s death by lightning strike; a girl wants to be emancipated from her family; and Shirley and Alan''s wager becomes public at the office Christmas party.', 43, '2006-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 11, 'Angel of Death', 'Alan goes to New Orleans to help a New York attorney with the defense of a doctor on trial for euthanizing five patients during Hurricane Katrina. Meanwhile, Clarence is thrown out of an all-female gym, and Coho tries to woo Denise.', 43, '2007-01-09');
