INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 17, 'The Bride Wore Blood', 'At the courthouse, Alan runs into an old flame and coworker, who''s looking very guilty in a bloody wedding gown; Claire reluctantly defends a cell-phone thief; and Denny''s prejudices are driving a wedge between him and Bethany.', 42, '2007-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 3), 18, 'Son of the Defender', 'The past comes back to haunt Denny when a vengeful man forces the firm to find a different outcome in a decades-old murder trial. Meanwhile, Alan is jailed for contempt of court while defending a prostitute.', 43, '2007-04-03');
