INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 4), 18, 'Indecent Proposals', 'Denny is head over heels for a cattle rancher who wants the government to stop the sale of cloned meat. Meanwhile, Shirley asks Alan to sue the Democratic Party when her nephew--a delegate--disagrees with his state''s primary vote.', 43, '2008-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 4), 19, 'The Gods Must Be Crazy', 'Jerry comes to the aid of his ex-girlfriend when she''s collared for prostitution; Carl and Shirley help a woman who''s suing the church for prohibiting her from becoming a priest; Denny is wooed by power brokers to run for president.', 41, '2008-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 4), 20, 'Patriot Acts', 'Alan and Denny mark their acceptance into the Auxiliary Coast Guard, but their relationship is tested when a Massachusetts town wants Alan to help it secede from the U.S., and Denny represents the opposition.', 43, '2008-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 1, 'Smoke Signals', 'Alan answers a call for help from Bethany Horowitz in a suit against a tobacco giant, but he suffers a crisis of confidence when the opposing counsel turns out to be an old girlfriend. Meanwhile, Denny is plagued by a case of performance anxiety.', 43, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 2, 'Guardians and Gatekeepers', 'A close call for Denny involving prescription drugs inspires Alan to go after a pharmaceutical company for its unscrupulous advertising tactics. Meanwhile, Carl defends Shirley''s 17-year-old granddaughter after she''s caught voting illegally, and Jerry and Katie help a girl who was sexually assaulted in a private detention facility.', 43, '2008-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 3, 'Dances with Wolves', 'Denny is arrested on concealed-weapon charges after shooting a man who tried to rob him and Jerry. Meanwhile, a case gets personal for Alan when he tries to help a sex surrogate in a custody battle for her daughter.', 42, '2008-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 4, 'True Love', 'After an old girlfriend hires Alan to help her husband beat a murder charge, he faces a moral and professional dilemma when his lingering feelings for her elicit a secret desire for a conviction.', 43, '2008-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 5, 'The Bad Seed', 'Alan and Shirley prepare for a fight with the military on behalf of a man whose brother died under suspicious circumstances. Meanwhile, Jerry helps his sister in her search for the identity of the father of her son, who was conceived through an anonymous donor.', 43, '2008-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 6, 'Happy Trails', 'Shirley defends the notorious Catherine Piper after she accidentally blows up her doctor. Meanwhile, Alan and Denny take a break from the office, but they are out of their element at a dude ranch in Utah.', 42, '2008-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 7, 'Mad Cows', 'Alan and Denny sue the USDA on behalf of a cattle rancher who wants to test her entire herd for mad cow disease; Jerry''s consideration to make partner hinges on an up-or-down vote by the firm''s panel, which includes Paul Lewiston.', 42, '2008-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 8, 'Roe', 'Alan and Shirley help a minor in a legal battle over her pregnancy, and Jerry takes up his own defense when he faces aggravated-assault charges after an encounter with a bully.', 43, '2008-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 9, 'Kill, Baby, Kill', 'Carl and Denny go to Virginia to defend a prison guard who shot a death-row inmate when a lethal-injection execution was botched. Meanwhile, Alan and Shirley help a woman who says she lost her job after voting for John McCain.', 43, '2008-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 10, 'Thanksgiving', 'Shirley''s quiet Thanksgiving with Carl becomes considerably louder when she opens her door to other members of the firm, including Alan, Denny, Jerry, Katie and emotionally unstable partner Edwin Poole, who brings his 6-year-old foster son.', 43, '2008-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 11, 'Juiced', 'When Denny receives bad news about the state of his Alzheimer''s, Alan goes before the Massachusetts Supreme Court to plead for access to an experimental drug that could help his condition. Meanwhile, Jerry and Katie try to help a girl get into Harvard after her SAT scores arouse suspicion, and Catherine Piper returns.', 43, '2008-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 12, 'Made in China (1)', 'Financial problems may force Crane, Poole & Schmidt to be put up for sale. Meanwhile, Alan petitions the Supreme Court for Denny''s access to a non-FDA approved medicine; and Shirley and Carl plan their wedding.', 43, '2008-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0402711')) AND numero_temporada = 5), 13, 'Last Call (2)', 'Financial problems may force Crane Poole & Schmidt to be put up for sale in the series finale, which also finds Alan petitioning the Supreme Court for Denny''s access to a non-FDA approved medicine, and Shirley and Carl planning their wedding.', 42, '2008-12-08');
