INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362'), 'Acción');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362'), 'Aventura');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362'), 'Drama');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362'), 'Ciencia Ficción');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')), 1, 'Season 1', 'Season 1 picks up where the miniseries left off. After engaging in a losing battle against the Cylons, humanity''s last remnants are forced to flee under the protection of their one remaining warship, the outdated Battlestar Galactica. Pursued by the Cylons-some of whom have now taken human form-Commander Adama and President Roslin lead these last remnants of humanity in search of a new home - a planet called Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 1, '33', 'In the wake of the Cylon sneak attack, the ragtag fleet of human survivors is forced to play a deadly game of cat-and-mouse with their pursuers. Every 33 minutes, they make a jump to a new location. And every 33 minutes, the Cylons manage to find them. The pilots are on the brink of exhaustion, relying on artificial stimulants to keep fighting, and the civilians are beginning to doubt the leadership of Commander Adama and President Roslin.', 45, '2004-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 2, 'Water', 'Lt. Sharon Valerii wakes up soaking wet in the tool room with an explosive charge in her duffel bag. Shortly afterward, a mysterious explosion destroys all the port-side water tanks on Galactica, creating a crisis for the entire fleet. Sharon can''t remember a thing, but all the evidence points to her as a saboteur. She confesses her concern to Chief Tyrol, but he can''t believe she''s responsible.', 44, '2004-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 3, 'Bastille Day', 'The fleet has found a source of water, but who will take on the difficult and dangerous job of mining it from the icy planet? Commander Adama and President Roslin send Lee to the Astral Queen, a prisoner transport ship, with an offer for its inmates: Volunteer for this mission and earn "freedom points".', 44, '2004-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 4, 'Act of Contrition', 'After a flight deck accident kills 13 pilots and wounds many others, Kara is thrust into service as a flight instructor and ordered to turn a group of civilian pilots and academy washouts into full-fledged Viper pilots.', 44, '2004-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 5, 'You Can''t Go Home Again', 'When Lt. Kara Thrace goes missing in action after encountering a Cylon patrol while on a training mission, Commander Adama feels responsible — especially in light of her recent admission that she blames herself for his son Zak''s death.', 44, '2004-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 6, 'Litmus', 'When a new copy of Doral, a Cylon who had been previously exposed while serving as the Galactica''s public-relations officer, sneaks aboard and blows himself up, killing three people, Commander Adama and President Roslin must finally make public the terrifying secret known only to a select few: Cylons now look like humans.', 44, '2004-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 7, 'Six Degrees of Separation', 'When Baltar and the Number Six who lives in his head have a falling out, she abandons him, only to surface a short while later aboard the Galactica. But now she''s called Shelley Godfrey, everyone can see her, and she''s telling them that she has evidence, passed on by the late Dr. Amarak, that will prove Baltar sold out the human race to the Cylons.', 44, '2004-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 8, 'Flesh and Bone', 'A Cylon, who calls himself Leoben, is discovered on one of the ships in the fleet. Commander Adama sends Kara to interrogate him — or, rather, it. The Cylon tells Kara that he planted a nuclear device on one of the ships. Although she doesn''t believe it, Kara passes on the warning.', 44, '2004-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 9, 'Tigh Me Up, Tigh Me Down', 'President Roslin''s fears that Commander Adama is a Cylon are stoked when she learns he''s making secret wireless calls to other ships. Then, to make things worse, a single Cylon raider appears near the Galactica and begins acting strangely after being damaged in battle.', 44, '2004-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 10, 'The Hand of God', 'As its fuel supply dwindles, the fleet must seek out a new supply of tylium ore or risk becoming sitting ducks to any Cylon attack. A recon patrol finds an asteroid full of the fuel, but there''s a catch — the Cylons have found it first and established a heavily guarded refining plant.', 44, '2005-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 11, 'Colonial Day', 'When President Roslin calls an Interim Quorum of the Twelve Colonies, she discovers that democracy brings its ugly stepsisters — politics and deadly intrigue — to the party. Tom Zarek, the charismatic convicted terrorist, is elected as the delegate from Sagittaron and immediately proposes elections for the vice-presidency.', 44, '2005-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 12, 'Kobol''s Last Gleaming (1)', 'While flying a supply patrol, Crashdown and Sharon Valerii discover a bountiful planet that can support human life. Indeed, it might be Kobol, the legendary "home of the gods." The discovery prompts Commander Adama to send a ground team to investigate; it also gives new life to President Roslin''s belief that she is a tool of destiny and that this discovery, like her rapidly spreading cancer, is part of an ancient prophecy.', 44, '2005-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 1), 13, 'Kobol''s Last Gleaming (2)', 'When Commander Adama learns that Kara disobeyed orders and Jumped to Caprica on orders from President Roslin, he demands the president''s resignation, with the implied threat of a military coup. Roslin refuses his demand and sparks a confrontation.', 44, '2005-01-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')), 2, 'Season 2', 'Picking up where the first season left off, season 2 continues to chronicle the adventures of a ragtag fleet of humans, the sole survivors of a devastating nuclear attack by the robot Cylons. But it soon becomes clear that more threatens this fragile society than external forces. Massive fear, paranoia, and political ambition — all classic plagues to developing civilizations — wear away at the already-fatigued fleet.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 1, 'Scattered', 'With Adama out of action, Colonel Tigh takes his position as commander of the Galactica. Boomer is in jail, and the cat''s out of the bag - she''s a Cylon.', 44, '2005-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 2, 'Valley of Darkness', 'Tigh has to work with Lee to defeat a Cylon boarding party that threatens to take over Galactica and destroy the fleet.', 44, '2005-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 3, 'Fragged', 'Democracy is brought back to the fleet and soon with it come hardball politics and potentially deadly intrigue.', 44, '2005-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 4, 'Resistance', 'Tigh imposes martial law and threatens to split the fleet as Lee works to free President Roslin and organize democratic resistance.', 44, '2005-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 5, 'The Farm', 'Adama and Roslin fight for the hearts and minds of the fleet''s population, as Starbuck finds herself trapped in a supposed resistance hospital.', 44, '2005-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 6, 'Home (1)', 'President Roslin''s fragile coalition is put to the test in the first part of a two-part story. Apollo, who has sided with Roslin, runs into a conflict with Zarek and his accomplice Meier.', 44, '2005-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 7, 'Home (2)', 'Adama heads to Kobol to find Roslin, reassembles the fleet and heads down to Kobol himself to find the presidential party in search of the "Tomb of Athena" which allegedly leads to Earth. Apollo hangs out with Starbuck , Zarek tries to keep his cronie off plotting with Boomer who is unaware of tension building between Helo and Tyrol.', 44, '2005-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 8, 'Final Cut', 'A reporter is sent to Galactica to chronicle the harsh realities of life during wartime.', 44, '2005-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 9, 'Flight of the Phoenix', 'Sharon informs Adama that the Galatica has been infected with a computer virus that is tampering with the basic ship functions and is scanning them for weaknesses. All this is preparation for a major assault by the Cylon Raiders. So with the clock ticking, Commander Adama must pull himself together and decide: Can he trust Sharon?', 44, '2005-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 10, 'Pegasus', 'Battlestar Galactica was not the only Battlestar to have survived the cylon attack, The Battlestar Pegasus also survived.', 44, '2005-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 11, 'Resurrection Ship (1)', 'The Battlestars Galactica and Pegasus face a new Cylon target, a "Resurrection" ship, while a power struggle threatens to result in all-out war among the human fleet.', 44, '2006-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 12, 'Resurrection Ship (2)', 'The struggle between Adama and Cain is temporarily put on hold while the two Battlestars combine forces for an assault on the Cylon Resurrection Ship. Apollo faces a momentous decision and Baltar takes an interest in Gina, the Cylon prisoner.', 44, '2006-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 13, 'Epiphanies', 'As President Roslin nears death, Dr. Gaius Baltar must be groomed for the worst case scenario. Roslin orders the death of Sharon''s unborn child. A sabotaged Viper leads to an investigation that uncovers a movement of people seeking peace with the Cylons.', 44, '2006-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 14, 'Black Market', 'Pegasus'' new commander Fisk is murdered by black marketeers, and Lee is charged with solving the crime. Roslin seeks to stamp out the black market by introducing new trade regulations.', 44, '2006-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 15, 'Scar', 'A crazed Cylon Raider attacks the Colonial fleet in a series of hit-and-run attacks. Overworked Viper pilots must defend a mining operation from this Raider that they nickname "Scar."', 44, '2006-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 16, 'Sacrifice', 'A woman takes hostages on Cloud Nine and demands that Adama turn over Sharon in order to avenge her husband''s death at the hands of the Cylons.', 44, '2006-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 17, 'The Captain''s Hand', 'Apollo assists in the search for a missing Raptor team as the new commander of the Pegasus grows increasingly unstable.', 44, '2006-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 18, 'Downloaded', 'After Boomer''s consciousness is downloaded into a new body following her death, she struggles with her new life on Cylon-occupied Caprica. Number Six is asked to help Boomer adjust to her new role in Cylon society.', 44, '2006-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 19, 'Lay Down Your Burdens (1)', 'Chief Tyrol is plagued by terrifying dreams and seeks the aid of a priest. Kara leads a rescue mission to Caprica. Roslin and Baltar go head-to-head in a presidential debate that changes dramatically with the discovery of a habitable planet.', 44, '2006-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 2), 20, 'Lay Down Your Burdens (2)', 'When Baltar wins the vote, Roslin considers stealing the election because she believes he is a Cylon collaborator.', 68, '2006-03-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')), 3, 'Season 3', 'Season 3 picks up where last season''s cliffhanger finale left off, the Galactica crew discovers a habitable planet, but things become even further complicated when the Cylons, led by Caprica Six and Sharon, find the planet and offer humanity a stunning proposal of peace.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 1, 'Occupation', 'Tigh, Tyrol and Anders lead the Resistance on New Caprica to increasingly deadly attacks against the Cylons. Kara finds herself trapped in a new life with Leoben Conoy, and Duck makes a fateful decision. Meanwhile on Galactica, Adama struggles with the question of whether to return to New Caprica to mount a rescue attempt.', 44, '2006-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 2, 'Precipice', 'Adama plans to return to New Caprica and drop off a surprising person to act as a liaison between Galactica and the Resistance. Tigh''s insistence on the use of suicide bombers and ever escalating violence stuns even the fellow leaders of the Resistance. Eventually, the suicide bombings cause the Cylon occupiers to crackdown on their human subjects.', 44, '2006-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 3, 'Exodus (1)', 'Sharon helps the Resistance on New Caprica as Adama leads Galactica on a dangerous rescue operation. Tyrol races to save Cally from the execution squad. Meanwhile Anders uncovers treachery among the humans. Number Three meets the Oracle Selloi after having strange dreams about the temple.', 44, '2006-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 4, 'Exodus (2)', 'Tigh must decide the fate of his wife Ellen after the assistance she rendered to the Cylons. Lee struggles with his assignment to protect the civilian fleet on its journey toward Earth while Adama returns to New Caprica with just the Galactica. The Resistance coordinates an attack on the Cylons just as Galactica arrives. As the Cylons begin to lose control, Number Three vows to put a final end to the New Caprican experiment.', 44, '2006-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 5, 'Collaborators', 'Tyrol participates in the Circle, a secret tribunal on Galactica that tries and convicts in absentia those accused of collaborating with the Cylons during the Occupation. The death sentences--administered without the knowledge of Roslin or Adama--begin to weigh on Tyrol''s conscience. Baltar faces a similar jury among the Cylons, who must decide whether he is allowed to stay with them.', 44, '2006-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 6, 'Torn', 'Lingering feelings of rage lead Saul Tigh and Kara Thrace to cause problems aboard Galactica between the survivors from New Caprica and those who stayed with the fleet during the Occupation. Baltar assists the Cylons in an attempt to stay alive and uncovers details about Cylon civilization. A Cylon baseship falls victim to a mysterious disease.', 44, '2006-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 7, 'A Measure of Salvation', 'Apollo formulates a plan that threatens the very existence of the Cylon culture. Adama and Roslin must decide whether to follow through on the plan to use a biological weapon against the Cylons. D''Anna Biers (Number Three) believes Baltar knows who created the virus that infected and disabled the Cylon baseship. She is willing to take extreme measures to learn the truth.', 44, '2006-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 8, 'Hero', 'A figure from Adama''s past returns to haunt him. His return raises questions about why the Cylons launched their initial attack against the Twelve Colonies.', 44, '2006-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 9, 'Unfinished Business', 'Adama stages a boxing tournament on the Galactica to help the crew relax. The competitive atmosphere sets off a brutal match between Kara and Lee. Flashbacks from New Caprica reveal the origin and nature of their dispute.', 44, '2006-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 10, 'The Passage', 'The Colonial fleet faces starvation when the food-processing machines are contaminated. Kat plays a vital role in the success or failure of the "Passage" through space.', 44, '2006-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 11, 'The Eye of Jupiter', 'Tyrol discovers the Temple of Five on the algae planet. The temple may hold the Eye of Jupiter, which is believed to show the way to Earth. The Cylons take a keen interest in the discovery. Athena learns that her baby, Hera, may still be alive. Lee relies on Anders to help build civilian support for the protection of the Eye. His relationship with Kara complicates matters.', 44, '2006-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 12, 'Rapture', 'D''Anna/Number Three squares off against Adama over the Temple of the Five. Athena asks for Helo''s aid in her plan to rescue Hera. On the algae planet, Apollo orders Dee to leave her defended position in order to save Kara. Anders helps Apollo to hold off the Cylon Centurion attack. Another copy of D''Anna finds the Temple and continues her search for the identities of the Final Five. Her messianic complex begins to concern the other Cylons.', 44, '2007-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 13, 'Taking a Break from All Your Worries', 'Now on board Galactica, Baltar faces charges of treason. He contemplates suicide with the help of Number Six. Questions remain about his true identity. Is he a Cylon or isn''t he? Apollo shows off the new drinking establishment on Galactica, Joe''s Bar, to Tyrol. Apollo thinks about Kara and wonders whether his marriage to Dee is worth saving.', 44, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 14, 'The Woman King', 'The Sagittarons allege that a doctor is discriminating against them. As Helo investigates, he becomes concerned that the doctor may even be murdering patients. Meanwhile, Athena unwittingly brings Hera to the doctor for treatment.', 44, '2007-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 15, 'A Day in the Life', 'Chief Tyrol and his wife Cally become trapped in a malfunctioning airlock. Adama remembers his late wife Carolanne as he marks his wedding anniversary. His relationship with President Roslin continues to become more friendly and personal.', 44, '2007-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 16, 'Dirty Hands', 'Amid a heated labor dispute, Tyrol asks the imprisoned Baltar for advice. Seelix becomes involved after she is turned down for flight training.', 44, '2007-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 17, 'Maelstrom', 'Kara continues to have dreams about Leoben Conoy and the mandala she painted at her old apartment on Caprica. While on patrol in her Viper, she encounters a Cylon Heavy Raider. When Tyrol cannot verify Kara''s claim that the Cylon ship struck the Viper, Admiral Adama and Lee become concerned about her mental stability.', 44, '2007-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 18, 'The Son Also Rises', 'When Baltar''s representatives face assassination attempts, Adama asks Lee to protect Baltar''s lawyer. After taking on the assignment, Lee seeks to play an active role in Baltar''s defense.', 44, '2007-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 19, 'Crossroads (1)', 'Baltar''s trial testimony threatens the very stability of the fleet. Lee assists Romo Lampkin in Baltar''s defense. Some in the fleet begin to feel that Baltar is divine. Though he dismisses such beliefs, Number Six suggests that the followers may know more about his true nature than Baltar does himself.', 44, '2007-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 3), 20, 'Crossroads (2)', 'As Baltar''s trial comes to a conclusion, key members of the fleet discover that they may be the Final Five Cylons. Tigh attempts to decipher the strange music he is hearing in his head, while a Cylon fleet approaches.', 44, '2007-03-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')), 4, 'Season 4', 'As season 4 begins, the last remnants of humanity continue their search for a new home. Galactica’s crew attempts to make sense of the inexplicable while four members of the fleet are still reeling from past revelations.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 1, 'He That Believeth in Me', 'During the Cylon attack, Sam Anders has a strange encounter with a Cylon Raider. The crew of the Galactica view Starbuck''s return with suspicion and doubt. Gaius Baltar takes refuge with a group of women who believe he has the power to heal others.', 44, '2008-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 2, 'Six of One', 'The Cylons learn that the Final Five are in the Colonial fleet. Some of the Cylons want the Cavil model to stop lobotomizing the Raider ships. Starbuck desperately tries to convince the others that the fleet is going the wrong way in their search for Earth.', 44, '2008-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 3, 'The Ties That Bind', 'Kara Thrace seeks her own path in the search for Earth while the Cylons face the threat of sentient Centurions. A member of Galactica''s crew learns a dark secret about a loved one.', 44, '2008-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 4, 'Escape Velocity', 'Gaius Baltar sets off a debate on religious freedom when he promotes his belief in a single God.', 44, '2008-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 5, 'The Road Less Traveled', 'Specialist Tyrol continues to sink into despair after his recent loss. He becomes curious about Gaius Baltar''s sermons and the following he has attracted. The crew of the Demetrius grow concerned about Kara''s mental stability as an old enemy arrives with a tempting offer.', 44, '2008-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 6, 'Faith', 'The dying President Roslin and the aggressive Viper pilot Kara Thrace try to accept the new terms of the relationship with the Cylons.', 44, '2008-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 7, 'Guess What''s Coming to Dinner?', 'President Roslin faces challenges as the Colonials plot with Cylon rebels to destroy a Resurrection Hub.', 44, '2008-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 8, 'Sine Qua Non', 'With President Roslin missing along with the cylon base ship a new president must be decided on.  Galactica goes on a search for the missing base ship and the Galactica crew members that were on board.', 44, '2008-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 9, 'The Hub', 'Colonial Viper pilots plan an attack on the Resurrection Hub with their Cylon rebel allies.', 44, '2008-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 10, 'Revelations', 'D''Anna holds President Roslin and other Colonials hostage in order to draw out the Final Five from the Colonial fleet. Col. Tigh believes he has the solution to end the standoff.', 44, '2008-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 11, 'Sometimes a Great Notion', 'Kara struggles with the foreboding prediction of the Cylon Hybrid, while Adama and the Colonial fleet face despair over their shocking discovery.', 44, '2009-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 12, 'A Disquiet Follows My Soul', 'Tigh and Number Six take their first glimpse at their unborn child, Tyrol offers Adama Cylon technology in return for his fellow Cylons properly reintegrated into the fleet, and an attempted coup leads to a costly struggle to maintain civility.', 44, '2009-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 13, 'The Oath', 'Loyalties are made clear when Gaeta orchestrates a coup d''état of the Adama regime. Both prisoners and lives are taken as many of the fed up people work to take over Galactica.', 44, '2009-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 14, 'Blood on the Scales', 'President Roslin faces off against Tom Zarek and Lt. Gaeta as they try to take control of the Colonial fleet. Both the alliance with the rebel Cylons and Adama''s life are at stake.', 44, '2009-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 15, 'No Exit', 'As Sam Anders recovers from his head injury onboard the Galactica, he begins to remember events from ancient Earth. The Final Cylon struggles with the fallout from the Final Five''s former plans. One of the humanoid Cylons vows to get revenge for being created in the image of Man. Tyrol informs Admiral Adama about the extensive structural damage on the Galactica.', 44, '2009-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 16, 'Deadlock', 'Ellen escapes from Cavil only to face a momentous choice regarding the 13th Tribe and the Final Five Cylons.', 44, '2009-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 17, 'Someone to Watch Over Me', 'Kara feels lost while she struggles to cope with Sam''s continued coma, meanwhile Boomer faces charges of treason from the Cylons onboard the base ship who blame her for voting against her model during the civil war causing the deaths of thousands of Cylons.', 44, '2009-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 18, 'Islanded in a Stream of Stars', 'The rebel Cylons and the Colonial humans react to Hera''s kidnapping while the physical condition of the Galactica continues to deteriorate.', 44, '2009-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 19, 'Daybreak (1)', 'With Galactica on the verge of falling apart, Admiral Adama readies the ship for what could be its final mission, as Baltar''s Six warns that humanity''s final chapter is near.', 44, '2009-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0407362')) AND numero_temporada = 4), 20, 'Daybreak (2)', 'Adama and the Galactica crew stake the survival of the human race on their plan to rescue Hera from the Cylon colony in this, the series finale.', 92, '2009-03-20');
