INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0397306', 'American Dad!', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0400423'), 'SERIE', 'The escapades of Stan Smith, a conservative C.I.A. Agent dealing with family life, while keeping America safe.', '2005-01-01', 'https://m.media-amazon.com/images/M/MV5BZDI4ZWYwMGUtZGE1Yi00OTc5LWI3NDctMGY4ZWE4NzI4NWUwXkEyXkFqcGc@._V1_.jpg');
