INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 1, 'Season 1', 'From the delightfully twisted creative minds behind ''Family Guy'' comes ''American Dad'', the animated tour de force featuring CIA operative Stan Smith, his outrageous family and Roger, the alcoholic extraterrestrial who lives with them! Follow the adventures of the Smiths from the California desert, where Stan''s wife, Francine, relives her teenage years at the Burning Man festival, to Saudi Arabia, where the entire family is sentenced to death by the Vice and Virtue Police! Whether it''s rigging elections, erasing memories, casing sleazy strip clubs, or staging "bum fights", it''s all in a day''s work for Stan, and it''s all here in the side-splittingly hilarious first season of ''American Dad''!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 1, 'Pilot', 'Stan Smith uses his CIA skills to help 13-year-old son Steve win class president and the heart of the hottest girl in class, Lisa Silver. But when being class president makes Steve mad with power, Stan must jump in to save the day. Meanwhile, Roger, the alien Stan saved from Area 51, helps 18-year-old Hayley with her school paper. In return, she hooks him up with boatloads of junk food to curb his sweet tooth. Unfortunately, some Chocodiles send him over the edge and a sugar crash prohibits him from finishing one of her papers, forcing Hayley to pick up the pieces. And Klaus, the goldfish with the brain of a German guy, pines after mother Francine. Unfortunately for Klaus, the closest he''ll ever get to a date with her is the spin cycle with her sports bra.', 22, '2005-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 2, 'Threat Levels', 'Stan Smith is mad because after getting his wife a job (or "hobby") as a Real Estate agent, she makes more money than him. In the meantime, his daughter Hayley ran a program that helped the homeless, and Stan''s son Steve had an idea to have a Bum Fight program. To get back and to try to gain more money than his wife, Stan takes Steve''s idea and starts a Bum Fight Night where he takes bets and treats the homeless like wrestlers. But with the homeless petition, Stan has to end up fighting like a homeless man himself.', 22, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 3, 'Stan Knows Best', 'Hayley comes home from a Green Party rally with her hair dyed green, instigating a fight with Stan. While she''s sleeping, Stan cuts her hair (for her own good, of course). After learning of what Stan did, a wigged Hayley defies her father yet again by moving into the van of her new boyfriend. When Stan cuts her off financially, she gets a job as a waitress in a strip club, which pushes Stan right off the edge. Meanwhile, Steve tries to pass Roger off as his disfigured sister in order to cop a feel with a female classmate.', 22, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 4, 'Francine''s Flashback', 'When Stan forgets his anniversary, he arranges to have 20 hours of Francine''s memory erased, but the CIA temp on duty accidentally erases 20 years. Francine, having reverted to her wild child days, moves into her old apartment with Hayley as a roommate, and ends up going to a festival with Hayley''s boyfriend. Meanwhile, Steve asks a good-looking girl out, but needs his wingman, Roger, to "jump on a grenade" for him and date her ugly cousin.', 22, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 5, 'Roger Codger', 'Stan invites his boss over for dinner, but the Smith family fears getting caught hiding Roger. After a close-call, Roger goes into a coma, making everyone thinking he''s dead. After the family disposes of his body, Roger tries to get back home, but he ends up in another risky situation with the CIA.', 22, '2005-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 6, 'Homeland Insecurity', 'Francine decides to throw a block party to get in touch with the neighborhood.  Stan learns his new neighbors are Iranian and immediately suspects that they are terrorists. To prepare Steve for living near terrorists, Stan makes Steve join a group of scouts, who turn out to be trouble makers. Roger is convinced he possesses hidden alien powers and is determined to find out what they are.', 22, '2005-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 1), 7, 'Deacon Stan, Jesus Man', 'Stan goes to great lengths to compete against his rival, Chuck White, and become the new deacon of their church. Meanwhile, Roger''s "temporary problem," which Stan tries to use to his advantage, causes all sorts of problems for Steve, Betsy, the rest of the family, and eventually, Stan.', 22, '2005-06-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 2, 'Season 2', 'Terrorists (and all you bed-wetting hippie-liberal types) beware! Ultra-right-wing C.I.A. agent Stan Smith is back, taking names, and, well, you know the rest. Join Stan, along with his hilariously off-beat family, as he spans the globe to make the world safe for democracy! If you are ready to support your country, and if you''re ready for a widly outrageous animated farce from Mike Barker, Matt Weitzman and Seth MacFarlane, the creative mastermind behind Family Guy, you''re ready for American Dad! Volume two. God bless America.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 1, 'Bullocks to Stan', 'Stan finds Deputy Director Bullock, his supervisor, starting a relationship with Hayley. However, he can''t risk saying or doing anything about it because he''s up for a promotion at the CIA. Meanwhile, Steve finds Dick Cheney''s BlackBerry and uses the contact numbers to play pranks on political figures from around the world.', 22, '2005-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 2, 'A Smith in the Hand', 'When Steve brings home a permission slip to take sex ed at school, Stan flips out and demands to teach it himself. However, after Stan unrealistically explains the birds and the bees to Steve, he gets into an accident that causes him to take matters into his own hands. Meanwhile, Roger becomes a bartender in hopes of making something of himself.', 22, '2005-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 3, 'All About Steve', 'When the CIA organizes a father-son baseball game, Stan is determined to show his co-workers that his son is masculine and athletic. Unfortunately, Steve is a geek, so Stan decides to lie and ditches him. But after getting a taste of his own treatment at work, Stan turns to Steve and his sci-fi knowledge to help capture a cyber-terrorist. Meanwhile, Roger goes incognito in a desperate attempt to interact with humans.', 22, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 4, 'Con Heir', 'When Stan''s father passes away, Stan reveals his real father is actually Jack Smith, a super suave spy. Jack convinces Stan to quit the CIA and work with him at the Scarlet Alliance, an ultra-secret spy group. Francine is upset with Stan, who is busy training with Jack for a mission involving uranium, artwork and terrorists. But when the FBI shows up at the Smiths'' house looking for an international jewel thief, Francine suspects Jack is the fake.', 22, '2005-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 5, 'Stan of Arabia (1)', 'Stan has to throw a party for his boss and assumes his wife Francine will do all the work, but she refuses. With Stan as party planner, the event turns into a disaster. As a result, Stan''s boss relocates Stan and his family to Saudi Arabia, where they quickly get a taste of life on foreign ground. As American and Arabian social norms clash, gender wars heat up.', 22, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 6, 'Stan of Arabia (2)', 'As the Smiths continue to live in Saudi Arabia, Stan is fully enjoying the male-dominated society, while the rest of the family struggles with the different social norms. Meanwhile, Francine''s musical expos on gender roles gets her into trouble, and a brush with death leads the Smiths to return to the United States.', 22, '2005-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 7, 'Stannie Get Your Gun', 'Francine insists that Stan and Hayley spend an entire day together, after their arguments drive her crazy, so they can work out their differences about gun control. However, her plan backfires when he takes Hayley to the "National Gun Association Land," where their conflicting opinions about gun control drive them even further apart. Back home, Roger schemes to get revenge on Steve for eating one of his cookies by convincing him that he''s adopted.', 22, '2005-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 8, 'Star Trek', 'Steve becomes a famous author, and the entire family gets caught up in his celebrity, including Stan, who becomes an unbearable "stage parent." After Steve hooks up with an agent, he abandons his family to lead a "Cribs" lifestyle.', 22, '2005-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 9, 'Not Particularly Desperate Housewives', 'As Stan continues to dominate the household, Francine finds herself idolizing a group of women who seem to have it all. She tries to impress them and even lies in order to gain acceptance into their group, until she realizes they aren''t as perfect as they seem. Meanwhile, loyalties are tested when Stan gets a new best friend.', 22, '2005-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 10, 'Rough Trade', 'After Stan and Roger have a rough day, they get into a fight that leads to a "Freaky Friday"-type switcheroo where they get a taste of life in each other''s shoes. But after the excitement of a new life stales, they face each other''s problems as Roger is under pressure at work and Stan yearns to be needed. The swap gets out of hand as the family starts to crumble.', 22, '2006-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 11, 'Finances With Wolves', 'After receiving a hefty bonus from work, Stan buys extravagant gadgets while Francine pleads for her dream kiosk. Upset about his lack of support, Francine opens a muffin shop without his approval and gives Stan a taste of life without a housewife. In a desperate move, Stan puts Klaus'' brain back into a human body – only to discover it was a huge mistake as Klaus tries to win over Francine. Meanwhile, Steve is convinced he''s a teen wolf after watching a horror film.', 22, '2006-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 12, 'It''s Good to be the Queen', 'Because of a past incident at his own prom, where he was lured into a dance with the homecoming queen only to have a pile of pigs dropped on him, Stan wants revenge by showing off that he married a homecoming queen, Francine. A proud Stan accompanies Francine to her reunion, but when they find out that two ballots were lost and that Francine didn’t actually win the crown, Stan is devastated. Meanwhile, a dejected Steve is “saved” by a pizza delivery man with a Messianic message.', 22, '2006-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 13, 'Roger ''n Me', 'When Stan goes to Atlantic City for a bachelor party and is shunned by his so-called best friend, Roger steps in and becomes Stan''s new sidekick. Their friendship goes to a whole new level, but when they return home and face Francine, Stan realizes that what happens in Atlantic City doesn''t necessarily stay there. Meanwhile, Hayley and Steve team up to break up a good-looking couple.', 22, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 14, 'Helping Handis', 'Stan wants Steve to be popular and goes to desperate measures giving him steroids to make him bigger, better, and part of the in-crowd at school. But when the steroids have an unexpected side effect, Steve gets a lot more attention than anyone expected. Meanwhile, after Hayley makes a movie about Francine''s life as a housewife, Francine is determined to start a new career as a doctor.', 22, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 15, 'With Friends Like Steve''s', 'After Steve shows a lack of interest in Stan''s job, Stan replaces him with Barry, Steve''s malicious friend. Barry frames Steve to eliminate him from the household, but when Steve discovers Barry''s weakness, he relies on his CIA skills to save the family. Meanwhile, Roger takes an impressive keg-stand and uses it to become a fraternity brother.', 22, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 2), 16, 'Tears of a Clooney', 'When Francine''s birthday brings back haunting memories of a celebrity film moment stolen by George Clooney, Francine''s new dream is to destroy the star. But when she tries to win Clooney''s heart with the intention of breaking it, Stan actually falls for him and sabotages the plan. Meanwhile, back at home, Roger builds a vineyard and starts up a private sweat shop of foster children.', 22, '2006-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 3, 'Season 3', 'C.I.A. weapons expert Stan Smith is back, keeping the homeland secure while alienating his family and terrorising his neighbours in the process. Whether he''s saddling up for a mad cow cattle drive or destroying evidence of President Bush''s drunken debauchery, Stan does whatever it takes to ensure domestic tranquility and make the world safe for democracy of the ultra-right-wing variety! Join the Smith family and Roger, their alcoholic pet alien, for this hilarious Volume Three of ''American Dad!'' God Bless America!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 1, 'Camp Refoogee', 'When Stan tries to trick Steve into attending summer camp, things go horribly wrong and Steve ends up in a refugee camp. However, Stan, being the eternal optimist, joins Steve and manages to stage a camp Olympics between the refugees and the rebel faction living across the river.', 22, '2006-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 2, 'The American Dad After School Special', 'Stan realizes his own weight problem after he criticizes Steve about his new, overweight girlfriend, so he goes overboard with exercising, and develops anorexia. Steve realizes that his overweight girlfriend is the root of his father''s problems, and he has to make a hard choice in an effort to save his father''s life.', 22, '2006-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 3, 'Failure is Not a Factory-Installed Option', 'Stan loses his confidence, and his job, when a car salesman gets the best of him in a negotiation. Meanwhile, Roger and Steve set up a makeshift drive-in to try to get to first base with popular schoolgirls.', 22, '2006-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 4, 'Lincoln Lover', 'Stan has his heart set on speaking at the Republican National Convention on behalf of the Langley chapter, but when they pass him up for another candidate, he accepts the only endorsement he gets from the local chapter of Gay Republicans. While the people around him disapprove of his new lifestyle choice, Stan decides to follow his heart to speak on their behalf.', 22, '2006-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 5, 'Dungeons and Wagons', 'After Francine tells Stan she''s looking for excitement in their marriage, Stan gets in the driver''s seat and becomes involved in drag racing to spice things up. Meanwhile, Hayley breaks up with her boyfriend, Jeff, who is emotionally crushed until he joins Steve''s world of online gaming. When Hayley finds out, she tries to sabotage their fun.', 23, '2006-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 6, 'Iced, Iced Babies', 'When Steve''s new relationship with his girlfriend gives Francine empty nest syndrome, she tries to convince Stan to have another baby. Meanwhile, Roger tries to enroll in college with Haley in order to experience college life, but while Roger ends up teaching the class, Haley finds a new crush in her classmate Ethan (Elijah Woods), who turns out to be far from normal.', 22, '2006-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 7, 'Of Ice and Men', 'When Francine discovers Stan''s secret, decades-old passion for competitive figure skating, she decides to be supportive and becomes his pairs partner until Stan''s competitive nature gets the best of him and he ditches her for a new partner. Meanwhile, Steve''s classmate Snot finds new respect among his peers when he parades his mail-order bride around the playground.', 22, '2006-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 8, 'Irregarding Steve', 'When Roger helps Steve see that his father isn''t as smart as he always believed, the power-hungry pair set their sights on fame and fortune in New York City. It doesn''t take long for Roger to lose everything on Wall Street, and Steve contemplates prostitution after Jon Stewart shoots down his comedy routine. Meanwhile, the rest of the family is certain that the two have just run away to the tree house, so when it explodes in a lightning storm, they are devastated, but console themselves with Steve''s college fund.', 22, '2006-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 9, 'The Best Christmas Story Never Told', 'When an injunction prevents Langley Falls from lighting their annual Christmas tree, Stan blames secular non-believers for ruining his favorite holiday. With Stan''s holiday spirit at an all-time low, the Ghost of Christmas Past visits him and tries to show him the true meaning of Christmas. However, Stan is convinced that Christmas can be saved by changing the outcome of Vietnam, but finds that changing the past only dramatically changes the future.', 22, '2006-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 10, 'Bush Comes to Dinner', 'When Stan enters an essay contest to have his personal hero, President Bush, come over for dinner, he is overcome with joy when the President arrives at his doorstep. However, not everyone in the Smith family shares Stan''s excitement. Hayley tries to drill President Bush on the Iraq war, and Steve and Roger attempt to convince him that they''ve found Osama Bin Laden, but instead get him drunk. Stan tries to save the President from public humiliation, while Hayley revels in his fall from glory.', 22, '2007-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 11, 'American Dream Factory', 'When Stan feels like he''s not climbing the ladder fast enough at work, he turns to his lifelong ambition of making festive teddy bears. However, when he realizes that making a quick profit takes a lot of work, he resorts to using illegal aliens as cheap labor. Meanwhile, Hayley sees her father''s new business model as an atrocity and takes matters into her own hands by calling Uncle Sam.', 22, '2007-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 12, 'A.T. The Abusive Terrestrial', 'When Roger is rejected by Steve, who seems to be over him, Roger heads out in search of a new human companion. But when this new friend starts to abuse Roger and the relationship turns into a lot of excuses and sorry''s, Steve and Hayley scheme to get Roger out of the bad relationship and back home where he belongs. Meanwhile, Stan tours the Mr. Pibb factory and meets the man himself.', 22, '2007-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 13, 'Black Mystery Month', 'While researching a paper about George Washington Carver in celebration of Black History Month, Steve uncovers a conspiracy that''s been going on since the Civil War. When the curator of the Smithsonian Peanut Museum reaches out to tell Steve the truth, he''s mysteriously murdered, and Steve and Stan are tracked by a secret society that will stop at nothing to keep this scandalous secret of American history.', 22, '2007-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 14, 'An Apocalypse to Remember', 'Stan arrives late to a CIA nuclear drill and thinks it''s real. He decides to move the family into the mountains to survive the apocalypse. Even though he realizes his error, he begins to enjoy the attention that he gets from the family so much that he doesn''t tell them the truth. However, when the family meets a mountain man and learns the truth, Stan has some explaining to do.', 22, '2007-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 15, 'Four Little Words', 'Stan sets Bullock up on a date with one of Francine''s friends. Fearing that Francine will be right about the outcome of the date, Stan goes to great lengths to make sure it goes well by getting everyone drunk. Unfortunately, Bullock accidentally kills the woman, to which Stan frames Francine for the murder in order to keep her from asking so many questions.', 22, '2007-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 16, 'When a Stan Loves a Woman', 'After Stan discovers that Francine has a secret sex garden, he feels like their marriage may be crumbling. Looking to rekindle their romance, Francine asks for a divorce so that Stan can experience life as a bachelor again, and both learn a valuable lesson in love. Meanwhile, addicted to an energy drink, Steve finds himself panhandling in the streets to support his new habit.', 22, '2007-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 17, 'I Can''t Stan You', 'When Stan brings home CIA equipment designed to eavesdrop on conversations, he finds out that his neighbors don''t think too highly of him. In retaliation, Stan has the entire neighborhood evicted so that he can live free of any criticism. However, when an unexpected friend comes to his rescue, he realizes that gossip is a two-way street.', 22, '2007-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 18, 'The Magnificent Steven', 'After Stan is prosecuted for sending contaminated cattle to a slaughterhouse, he says that it began as a quest to make a man out of Steve. Meanwhile, Roger sparks a cat fight between Francine and Hayley, for reasons of his own.', 22, '2007-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 3), 19, 'Joint Custody', 'Roger becomes a bounty hunter, and he and Stan race cross-country to turn in Jeff, who is wanted for smuggling pot into Florida.', 22, '2007-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 4, 'Season 4', 'Attention, terrorists, pinkos, and hippies: your days are numbered! CIA Agent Stan Smith is back, stopping at nothing to make the world safe for right-wing democracy and provide for his outrageously dysfunctional extended family. Amid botched kidnappings and beefcake body doubles, Stan hosts a torturously funny CIA telethon; his wife, Francine, is reunited with her ex-fiance; and resident-alien Roger hosts a booze-soaked spring break that may just push favorite son Steve all the way through puberty. God bless American Dad!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 1, 'The Vacation Goo', 'Francine demands that Stan take the family on a vacation after she learns all of their previous vacations never actually happened: The CIA had planted artificial memories of the "vacations" in their brains so Stan could ditch them. Meanwhile, Roger wants to be a thespian.', 22, '2007-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 2, 'Meter Made', 'After Stan punches a male meter maid during a disagreement over a parking ticket, a judge sentences him to two weeks of community service--as a meter maid. Meanwhile, Hayley poses in the nude for an art class, where one of the artists turns out to be Roger.', 22, '2007-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 3, 'Dope & Faith', 'Stan prays for a friend and one is provided: a guy named Brett who''s like him in every way but one--he''s an atheist. So Stan has some evangelizing to do. Meanwhile, Steve is accepted into wizardry school.', 22, '2007-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 4, 'Big Trouble in Little Langley', 'Stan seeks out Francine''s birth parents because her visiting adoptive parents annoy him so much. But they don''t annoy Steve, especially after they give him fireworks.', 22, '2007-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 5, 'Haylias', 'Stan, who had Hayley brainwashed because he wanted her to be a sleeper CIA agent, activates her and orders her to marry a senator''s son. Meanwhile, Roger and Steve decide to open a detective agency like the ones in the ''70s TV shows they have been watching.', 22, '2007-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 6, 'The 42-Year-Old Virgin', 'Although Stan is a veteran CIA agent, it turns out that he has never killed anyone, so three of his buddies from the agency (and Roger) take him out so he can bag his "first kill."', 22, '2007-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 7, 'Surro-Gate', 'Terry and Greg, the Smiths'' gay neighbors, want to have a baby, and Francine offers to be their surrogate. Not surprisingly, Stan objects. Meanwhile, Steve and Roger play a practical joke on Klaus, who vows revenge.', 22, '2007-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 8, 'The Most Adequate Christmas Ever', 'Stan dies on Christmas Eve while trying to find a perfect Christmas tree, then wreaks havoc in heaven (and limbo) trying to return to Earth to save his family--who were dragged along on his quest--from freezing to death in the woods.', 22, '2007-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 9, 'Frannie 911', 'Stan and Francine give the constantly nasty Roger an ultimatum: Be nice or ship out. Meanwhile, Klaus and Hayley play truth or dare, and Steve decides to become a backup dancer.', 22, '2008-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 10, 'Tearjerker', 'A James Bond spoof casts Stan as a 007-type agent assigned by B (Bullock) to infiltrate the set of a movie producer named TchochkieSchmear (Klaus), who''s in cahoots with the diabolical villain Tearjerker (Roger). Their plan? To kill everyone in the world by making movies so sad, people will cry themselves to death.', 22, '2008-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 11, 'Oedipal Panties', 'When Stan''s mom gets dumped by yet another boyfriend, she comes running to Stan for support, which he willingly provides (yet again). Francine, feeling threatened, seeks to loosen this umbilical cord, with Roger''s help. Meanwhile, Klaus inadvertently gives Steve a fish disease called "ick."', 22, '2008-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 12, 'Widowmaker', 'Francine wants Stan to open up emotionally, and after a few sessions with "pretend psychiatrist" Roger, he''s more touchy-feely than she can handle. Meanwhile, Hayley kills the queen bee from Steve''s science project, and he vows vengeance.', 22, '2008-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 13, 'Red October Sky', 'Stan hunts for an ex-KGB agent but can''t find him--until he moves in next door. And Steve is building a rocket for a school science project, but can''t get it to work--until he gets some help from his new next-door neighbor. Meanwhile, Roger and Klaus head off on a European vacation.', 22, '2008-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 14, 'Office Spaceman', 'After outing himself as an alien, Roger (in disguise) finagles his way into being appointed the CIA''s chief alien hunter to take advantage of a lavish expense account--while coming up just short in attempts to catch himself. Meanwhile, Francine shocks her family by displaying a prejudice they never knew she had.', 22, '2008-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 15, 'Stanny Slickers II: The Legend of Ollie''s Gold', 'After almost dying in a car crash, Stan decides that he must do something important with his life, so he digs for the gold he claims Iran-Contra figure Oliver North buried beneath his house. Meanwhile, Roger poses as a sexually provocative female office worker, hoping he''ll be harassed so he can sue over it.', 22, '2008-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 4), 16, 'Spring Breakup', 'Francine is out of town, giving Roger an opportunity to host spring break at the Smith house for visiting college students, one of whom becomes the straying Stan''s "spring-break buddy." Meanwhile, cable music-channel host Carmen Selectra decides she wants to make Steve her sexual conquest.', 22, '2008-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 5, 'Season 5', 'The hilarious, over-the-top adventures of CIA Agent Stan Smith - a red-white-and-blue-blooded, one-man war on terror - and his delightfully dysfunctional family. Volume Five celebrates that great American pastime - revenge! Steve and his friends strike back at Bar Mitzvah boy - Etan Cohen for stealing Steve''s girlfriend, Francine puts Stan through the ringer when she finds out he''s picked a back-up wife, and Roger unleashes deadly hotdog havoc throughout Langley Falls - all in the name of good old-fashioned vengeance. Getting even is the American way, so don''t get mad...get American Dad!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 1, '1600 Candles', 'It''s Roger''s 1600th birthday, but the Smiths are too freaked out by Steve''s impending puberty to celebrate. So Roger decides to make his own birthday fun.', 22, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 2, 'The One That Got Away', 'Roger plays detective to track down a case of what he suspects is identity theft. Meanwhile, the Smith family gets sucked into a mean game of Simon Says.', 22, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 3, 'One Little Word', 'Bullock makes Stan his "No. 1" at the CIA, a promotion that makes the furious Francine the "No. 1" babysitter for Bullock''s baby son. Bullock needs someone to watch the kid because his wife''s been kidnapped by Iraqi insurgents.', 22, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 4, 'Choosey Wives Choose Smith', 'Stan learns that Francine was engaged to another man before she met him, and tracks the guy down to size him up. Meanwhile, Steve can''t stay away from a schizophrenic cat that literally has nine lives.', 22, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 5, 'Escape from Pearl Bailey', 'Steve plots revenge after girlfriend Debbie loses a very dirty election for class president. But it backfires badly.', 22, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 6, 'Pulling Double Booty', 'Hayley goes on a rampage after her boyfriend breaks up with her, but she calms down when she begins dating Stan''s CIA body double, Bill. Meanwhile, Steve and Roger get jobs separating male and female chicks at a Chinatown hatchery.', 22, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 7, 'Phantom of the Telethon', 'Stan emcees a CIA telethon to raise funds for the agency''s torture budget after Congress slashed it. But Roger is out to sabotage it because Stan stole the idea for it from him.', 22, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 8, 'Chimdale', 'When Steve suffers indignities in school because of the back brace he must wear for his scoliosis, Stan confides in him that he wears a wig to cover his baldness. Meanwhile, Roger invites both Francine and Hayley to a posh spa even though he has only two passes.', 22, '2009-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 9, 'Stan Time', 'Stan is ecstatic--and energetic--when a coworker gives him pills that allow him to stay up all night.', 22, '2009-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 10, 'Family Affair', 'The Smiths catch Roger spending time with another family--and it turns out that he has been a family "cheater" for decades.', 22, '2009-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 11, 'Live and Let Fry', 'When Langley Falls bans trans fats, Stan and Steve become smugglers. Meanwhile, Klaus gets word that he has received an inheritance but can''t collect it because the CIA has turned him into a fish.', 22, '2009-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 12, 'Roy Rogers McFreely', 'When Stan forgets to pick up grenadine at the grocery store, Roger goes ballistic and vows to get him back by taking over a project close to his heart--the Homeowner’s Association.', 22, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 13, 'Jack''s Back', 'Steve connects with his ne''er-do-well paternal grandfather, whom Stan despises for many reasons, not the least of which is that he never taught him to ride a bike. Meanwhile, Hayley must find an internship quickly, so Roger hires her to tend his bar.', 22, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 14, 'Bar Mitzvah Shuffle', 'Steve and his friends sabotage a stuck-up kid''s bar mitzvah after the kid hits on Steve''s girlfriend, Debbie. But when Snot is wrongly accused of stealing the kid''s bar-mitzvah money, his own bar mitzvah is put in jeopardy.', 22, '2009-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 15, 'Wife Insurance', 'Stan is kidnapped in Colombia, but the real trouble begins after he''s released and returns home. Meanwhile, Steve and Roger play detective duo "Wheels and the Legman."', 22, '2009-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 16, 'Delorean Story-An', 'Steve and Stan, who don''t have much in common, try to bond on a road trip to Albuquerque in search of a pair of the distinctive DeLorean doors to complete a car that Stan has been building. Meanwhile, Roger, Hayley and Francine decide to have an adventure of their own, but they can''t decide what to do.', 22, '2009-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 17, 'Every Which Way But Lose', 'Steve joins a football team to please Stan, who then takes over as coach and gives Steve the boot because he isn''t good enough. Meanwhile, Francine and Hayley vie for a blue ribbon at the county fair.', 22, '2009-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 18, 'Weiner of Our Discontent', 'Roger declares that he was sent to Earth to be "the decider" of humanity''s fate, and Stan challenges him on it.', 22, '2009-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 19, 'Daddy Queerest', 'Francine and Stan swap spouses with their gay neighbours Terry and Greg when Terry''s dad, a former football player who doesn''t know that his son is gay, arrives for a visit. Meanwhile, Steve goes on a drunken bender.', 22, '2009-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 5), 20, 'Stan''s Night Out', 'Stan leaves Francine at home to go out with the boys, but guys'' night out goes from wild to reckless when Stan finds himself in one compromising situation after another. Meanwhile, Roger and Hayley use their charm and looks to attract a frat boy.', 22, '2009-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 6, 'Season 6', 'Trigger-happy CIA operative Stan Smith will stop at nothing to defend everything that makes this country great – from strip bars to that most sacred of American institutions, crack cocaine! Whether he''s trading brains with a racehorse or rescuing Roger from bloodthirsty revolutionaries, Stan will do whatever it takes to secure the blessings of liberty in this over-the-top salute to the greatest nation on Earth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 1, 'In Country... Club', 'When Steve is selected to sing the national anthem at the Langley Falls Veterans'' Day celebration, he gets some heat from Stan who doesn''t think he''s ready for such an undertaking. Unimpressed with Steve''s vocal talents, Stan decides Steve needs to experience real war in order to sing about our country''s military prowess. But things quickly go south when Roger gets involved and Steve goes bananas.', 22, '2009-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 2, 'Moon Over Isla Island', 'In order to get a promotion at work, Stan has to convince the dictator of Isla Island to sign a treaty. Stan meets the general and accidentally kills him and has Roger pose as the leader of the small island nation. Meanwhile, Steve and Snot become competitive to see who can get farther with the other’s mom.', 22, '2009-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 3, 'Home Adrone', 'Steve is left home as the family plan a trip to Boston hoping to locate a college for Hayley.  When his friends arrive they convince him to break the rules, resulting in them finding the controls to a military drone in Stan''s study.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 4, 'Brains, Brains and Automobiles', 'Francine teaches Roger to be self-sufficient so he can get his own place; at camp, Steve and his friends fall prey to a scheme.', 22, '2009-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 5, 'Man in the Moonbounce', 'Steve must become the man of the house when Stan re-lives his childhood.', 22, '2009-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 6, 'Shallow Vows', 'Upset that Francine has let herself go, Stan takes drastic measures when she asks him to renew their wedding vows.', 22, '2009-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 7, 'My Morning Straitjacket', 'When Hayley goes to a My Morning Jacket concert against Stan’s wishes, he crashes the show to bring her back home, but when he hears their music for the first time, it calls to him and he’s smitten. Stan becomes obsessed with the band and decides to follow them on the road as a groupie.', 22, '2009-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 8, 'G-String Circus', 'Upset that Hayley no longer wants his advice, Stan decides to prove that she is missing out on his sage counseling. After meeting a stripper on an important CIA mission, Stan takes it upon himself to improve her life and show Hayley that his advice works. But when he opens a new business, hoping to prove Hayley wrong, he finds himself dancing for cash to cover up his failures.', 22, '2009-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 9, 'Rapture''s Delight', 'When the Smith family goes to church on Christmas Day, Stan is furious when he can’t get a good seat. While Francine tries to ease his frustration, a moment of divine intervention occurs. Upset that he has been left on earth with Francine during the ultimate fight between good and evil, Stan ditches his wife to get into the pearly gates of heaven, but when Francine is kidnapped, Stan fights to get her back.', 22, '2009-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 10, 'Don''t Look a Smith Horse in the Mouth', 'When Stan gets told by Francine to get rid of his gas-guzzling SUV, he and Roger hatch up a plan at the local horse track to avoid losing his car. Meanwhile, Steve and his friends help an old friend.', 22, '2010-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 11, 'A Jones for a Smith', 'Stan puts down liberal social programs because he thinks they are a waste of money and gives Francine a hard time for lending a helping hand at the local homeless shelter. When Stan develops a nasty addiction and needs help, he suddenly has a change of heart.', 22, '2010-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 12, 'May the Best Stan Win', 'Stan gives Francine "love coupons" for Valentine''s Day, but refuses to honor them once he becomes preoccupied with his very own CIA cyborg. Meanwhile, Roger helps Steve and his friends remake a classic ''80s movie.', 22, '2010-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 13, 'Return of the Bling', 'When Stan admits that his heroes include the 1980 U.S. Olympic hockey team, Roger confesses that he played on the team; Reginald tries to win over Hayley by taking her to a concert.', 22, '2010-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 14, 'Cops & Roger', 'After Roger and Francine are victims of a mugging, Roger joins the police academy so he can learn how to defend himself and his loved ones (including Stan and Steve), but he falls in with a corrupt cop (guest voice Cannavale) who leads him astray. Meanwhile, Hayley''s new friendship threatens her long-term relationship. Chaz kidnaps and leaves Stan tied up and tape-gagged. Meanwhile, Roger kills Chaz and rescues Stan, who makes his boss happy.', 22, '2010-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 15, 'Merlot Down Dirty Shame', 'When Roger and Francine go wine-tasting, Roger plants a big kiss on Francine in a drunken moment. Francine decides to tell Stan about this incident, but when they sit down to talk, Roger convinces Stan that Francine started it all.', 22, '2010-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 16, 'Bully for Steve', 'Roger studies crime scene photography; Stan bullies Steve in hopes of toughening him up.', 22, '2010-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 17, 'An Incident at Owl Creek', 'In preparation for a neighborhood pool party, Stan tells his family to get in tip-top shape.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 6), 18, 'Great Space Roaster', 'It’s Roger’s birthday, and he begs to be roasted, but when he ends up devastated by the jokes, he vows to pull his life together.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 7, 'Season 7', 'It''s a time once again to let it all hang out with an all-new volume of animated outrageousness! From the disturbed comic minds of Mike Barker, Matt Weitzman, and Family Guy creator Seth MacFarlane, comes the always insane adventures of CIA operative Stan Smith and his wonderfully twisted family. In the 100th episode, Hayley elopes with Jeff! Other episodes include Stan on jury duty, Steve walking in on his amorous parents, Roger dating Steve''s best friend, and yet another American Dad Christmas classic. Plus, there are serial killers, Turkish amphetamines, and evil clones! So, you know, the usual!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 1, '100 A.D. (1)', 'Stan offers a reward to the person who can stop Hayley and her old boyfriend from eloping.', 22, '2010-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 2, 'Son of Stan (2)', 'Francine and Stan compare parenting skills after Stan creates a clone of Steve; Roger searches for the missing bride and groom.', 22, '2010-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 3, 'Best Little Horror House in Langley Falls', 'Wanting to have the scariest haunted house on the block, Stan comes up with a ''''killer'''' setup; Steve competes to win the heart of his overprotective friend''s younger sister.', 22, '2010-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 4, 'Stan''s Food Restaurant', 'Stan is ecstatic when Roger offers to help him live out his lifelong dream of opening a restaurant to rival his favorite childhood haunt - until their different visions for what the eatery should be cause havoc. Meanwhile, Steve meets Ashley, the new girl in school who invites him over while her parents are out of town.', 22, '2010-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 5, 'White Rice', 'After an argument between Stan and Francine breaks out, Stan suggests they go see a counselor, who hypnotizes Francine and reawakens her lifelong dream of being a comedian. Meanwhile, back in Langley Falls, Steve brings home a potential love interest for Klaus.', 22, '2010-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 6, 'There Will Be Bad Blood', 'It’s Thanksgiving in Langley Falls, and as usual, Stan invites his half-brother, Rusty, over to show off his cornucopia of wealth and good fortune. But when Stan finds out that Rusty is far wealthier than he led on, Stan tries to take from Rusty what he feels is rightfully his. Things don’t go well, and the Smith family nearly loses it all.', 22, '2010-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 7, 'The People vs. Martin Sugar', 'If there’s one thing that Stan Smith loves, it’s a good jury trial. He anxiously awaits his annual jury summons. But when Roger is the defendant in the trial where Stan is the foreman, he is finally in a position to make Roger accountable for his misdeeds. Meanwhile, Jeff and Hayley move in with the Smiths, and Francine tries to get Jeff to clean up his act.', 22, '2010-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 8, 'For Whom the Sleigh Bell Tolls', 'Despite Francine''s warning, Stan gives Steve a gun for Christmas; Steve accidentally shoots Santa.', 22, '2010-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 9, 'Fart-break Hotel', 'When Roger releases lethal gas into the Smith residence, the family moves into a hotel while the fumes clear.', 22, '2011-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 10, 'Stanny Boy and Frantastic', 'Stan and Francine have trouble keeping up with a younger couple''s lifestyle.', 22, '2011-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 11, 'A Piñata Named Desire', 'With a flair for the dramatic, Roger invites Stan to attend one of his acting classes.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 12, 'You Debt Your Life', 'After an argument with Stan, Roger moves out of the house and is subsequently replaced. Meanwhile, Steve acquires a new job at Pearl Bailey High School.', 22, '2011-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 13, 'I Am the Walrus', 'When Steve challenges Stan for family dominance, Stan does everything he can to prove to Steve that he is the alpha male of the Smith house. Meanwhile, Hayley and Jeff seek marriage counseling when the honeymoon phase wears off.', 22, '2011-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 14, 'School Lies', 'In an attempt to advance in the CIA, Stan enrolls Steve in the same private school as Senator Buckingham''s daughter.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 15, 'License to Till', 'When Steve has trouble crossing over into the "cool kids" social circle, Klaus and Roger place their bets to see how quickly Roger can make him cool. Everything they try backfires until Steve becomes the in-crowds designated driver. Meanwhile, Stan and Francine take turns pranking each other.', 22, '2011-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 16, 'Jenny Fromdabloc', 'After Snot professes his love for Hayley and gets shot down, Steve and Roger devise a plan to cheer him up. Roger dresses up as Steve’s cousin from New Jersey, Jenny Fromdabloc, and Snot falls hard for her. Meanwhile, Stan wants to live like a gentleman of the 1960s, complete with dark suits and dry martinis.', 22, '2011-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 17, 'Home Wrecker', 'Stan and Francine fight over how to redecorate the house. It goes so far that they split the house down the middle and try to live without each other. Meanwhile, Principal Lewis discovers a talent of Barry.', 22, '2011-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 18, 'Flirting With Disaster', 'Francine gets a job at Stan’s office, which cramps Stan’s style and his ability to flirt with co-workers.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 7), 19, 'Gorillas in the Mist', 'Bonding with Steve at the zoo causes Stan to lose Steve in the gorilla cage.', 22, '2011-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 8, 'Season 8', 'Let your American freak flag fly when you watch this all-new collection of outrageous episodes from the comic minds of Mike Barker, Matt Weitzman and Family Guy creator Seth MacFarlane. Follow the adventures of CIA operative Stan Smith''s quirky family as they deal with Stan and Francine''s killer hot tub, Steve''s lucky panties, Hayley and Jeff adopting an evil child, and Roger wrestling his way into the record books. Loaded with celebrity guest voices, including Sarah Michelle Gellar, CeeLo Green, Alyson Hannigan, Patrick Stewart, Amy Sedaris and more, American Dad! Volume 8 is a star-powered salute to patriotic parody and hardcore hilarity!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 1, 'Hot Water', 'Stressed out by his family and his obligations, Stan decides to buy a hot tub to relieve his stress, but gets into hot water when he finds out the hot tub is evil.', 22, '2011-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 2, 'Hurricane! (III)', 'When a hurricane hits Langley Falls, the Smiths fight like mad to survive in their home.  The crossover starts on The Cleveland Show S03E02 The Hurricane (I) and Family Guy S10E02 Seahorse Seashell Party (II).', 22, '2011-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 3, 'A Ward Show', 'Roger becomes Steve''s legal guardian, but gets a little overzealous in the parenting department when he gets the principal fired. After getting beat up by the other teachers at the school, Steve decides to run away. Meanwhile, Stan and Francine attempt to make waves after discovering that their vacation at the biggest water park in the world fails to get their hearts pumping.', 22, '2011-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 4, 'The Worst Stan', 'When Stan realizes that he might never fulfill his dream of becoming a Best Man, he convinces his last single friend, Principal Lewis to marry the school’s Superintendent and to choose him as his Best Man. Stan invites Lewis’ old friend from prison to the wedding, only to discover a secret that could prevent the wedding from happening at all. Meanwhile, Roger finds the perfect pair of shorts, and an encounter with Ricky Martin makes him question his self-confidence.', 22, '2011-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 5, 'Virtual In-Stanity', 'Stan makes a desperate attempt to bond with his son by creating a busty blonde bombshell.', 22, '2011-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 6, 'The Scarlett Getter', 'When Stan runs into his former crush from CIA boot camp, his affection for her resurfaces, which drives Francine into a jealous frenzy. By including Roger in her plan for revenge, Francine accidentally leads him straight into the arms of a dangerous alien hunter. Meanwhile, Steve is struck with good luck, when he accidentally wears Hayley’s panties to school.', 22, '2011-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 7, 'Season''s Beatings', 'Father Donovan holds a Christmas play at the mall and casts Stan as Santa Claus and Roger as Jesus. But after the two get in a fight and cause a scene, Stan is kicked out of the church. Meanwhile, Hayley and Jeff adopt a child who turns out to be possessed.', 22, '2011-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 8, 'The Unbrave One', 'When Steve tries to prove himself as a macho man to Stan, he follows in Roger''s footsteps and tries to change himself from the outside in with a superhero persona. Meanwhile, Francine is going through an identity crisis of her own when she receives surprising news that could change the family forever.', 22, '2012-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 9, 'Stanny Tendergrass', 'When Stan finally has enough money to afford a membership at the golf club he has worked at for the past thirty summers, his hard work and perseverance prove to be futile when the club gives a membership to Steve first. However, things are not all what they seem when Stan realizes who the club owner really is.', 22, '2012-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 10, 'Wheels & the Legman and the Case of Grandpa''s Key', 'Stan joins Roger and Steve''s fictional detective agency, but he ruins the fun by being extremely incompetent at his "job." Roger demands that Steve fire Stan, but Steve cannot bring himself to do it and ends up lying to Roger. Things take a turn for the worse when Stan is kidnapped, and Steve must tell Roger the truth.', 22, '2012-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 11, 'Old Stan in the Mountain', 'When Stan is overly enthusiastic about his hatred for old people, a hex is placed on him that turns him into a frail, old man. Meanwhile, Roger takes Francine on a road trip to a dance competition, but she soon finds out it''s not what she bargained for.', 22, '2012-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 12, 'The Wrestler', 'When Barry (guest voice Eddie Kay Thomas) threatens Stan''s old high school wrestling record, Stan enlists Roger to beat Barry and defend his small claim to fame. However, Stan is caught off-guard when Roger, not Barry, is actually the threat to Stan''s record.', 22, '2012-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 13, 'Dr. Klaustus', 'Roger acts as the family therapist as his alter-ego "Dr. Penguin" until he is sent out to fight the war in Iraq. Klaus decides to take Roger''s role while he is away, but not without major ruckus being caused.', 22, '2012-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 14, 'Stan''s Best Friend', 'Despite Stan''s objections, Francine buys Steve the dog he has always wanted. However, when the dog suffers a horrific accident, Stan refuses to take the pup off life support because of a traumatic childhood incident.', 22, '2012-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 15, 'Less Money, Mo'' Problems', 'After losing patience with Hayley and Jeff for their freeloading ways, Stan bets the young couple that he and Francine can live on minimum wage for a month. Meanwhile, Steve and Roger embark on a mission to test drive the car of their dreams.', 22, '2012-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 16, 'The Kidney Stays In the Picture', 'Stan fears he may not be Hayley''s real father, so he goes back in time to find the truth. In doing so, he disrupts the past and must save the future.', 22, '2012-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 17, 'Ricky Spanish', 'Roger rediscovers one of personas, Ricky Spanish, and remembers why he''s the most hated person in Langley Falls. Meanwhile, the child Stan and Francine sponsored in Africa suddenly shows up on their doorstep.', 22, '2012-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 8), 18, 'Toy Whorey', 'When Stan catches Steve playing imaginary games with his toys, he decides to take his son down to Mexico to help him become a man. But the trip takes a turn for the worse when Stan and Steve are kidnapped by a drug cartel, and it’s up to Steve to break himself and Stan out of captivity.', 22, '2012-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 9, 'Season 9', 'Take a “Stan" against boring, bipartisan comedy with this all-new collection of hilariousuncensored American Dadl episodes from the infinitely creative minds of Mike Barker, Matt Weitzman and Family Guy creator Seth MacFarlane. This outrageous assortment finds Stan and Klaus switching bodies, Steve joining a boy band, Jeff being held prisoner in space, and Roger falling hard for his latest crush...Hayley!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 1, 'Love, AD Style', 'When Roger hires Hayley as a singer in his new bar, he becomes enthralled by her voice; Stan tries to prove his masculinity by negotiating a good deal on a new car.', 22, '2012-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 2, 'Killer Vacation', 'During the Smith family''s tropical vacation, Stan is ordered to kill the activities director at their resort; Jeff and Hayley try to rekindle their romance.', 22, '2012-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 3, 'Can I Be Frank with You?', 'Francine thinks Stan spends too much time with his friends; a boy band recruits Steve and his friends for a music video.', 22, '2012-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 4, 'American Stepdad', 'When Stan invites his recently widowed mother to move in, she and Roger fall in love and wed; Steve and his friends find a lost movie script.', 22, '2012-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 5, 'Why Can''t We Be Friends?', 'When Stan decides that Snot isn''t cool enough to be Steve''s best friend, he tries to separate them by staging a shooting at an ice cream parlor.', 22, '2012-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 6, 'Adventures in Hayleysitting', 'When Steve''s baby sitter is unavailable, Stan and Francine decide to leave him with Hayley; Steve sneaks out to a party to prove he''s not a goody-goody.', 22, '2012-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 7, 'National Treasure 4: Baby Franny: She''s Doing Well: The Hole Story', 'A talk show reveals that Francine was the toddler who, famously, was rescued from a well by a firefighter; Francine makes a discovery when she falls down the well on the anniversary of her rescue; Stan and Roger come up with a business idea.', 22, '2012-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 8, 'Finger Lenting Good', 'The Smiths get drunk at Roger''s Mardi Gras party and make a pact with Bullock; Roger tries to find the person who left a pastie in the attic.', 22, '2013-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 9, 'The Adventures of Twill Ongenbone and His Boy Jabari', 'Francine regrets deciding to teach Roger the value of hard work; Steve interviews Stan for a school project.', 22, '2013-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 10, 'Blood Crieth Unto Heaven', 'When Francine invites Stan''s father to a party, a dark secret about the Smith family''s past is revealed.', 22, '2013-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 11, 'Max Jets', 'Roger announces that Max Jets, a character who showers the Smith family with money, is making a return; a gold-digging waitress romances Max and threatens the family''s inheritance.', 22, '2013-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 12, 'Naked to the Limit, One More Time', 'Roger pretends to be Jeff''s imaginary friend so he can roam around the house without a disguise; when Jeff realizes Roger is an alien, Stan issues an ultimatum -- either Roger or Jeff must be killed; Steve becomes insecure about his body.', 22, '2013-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 13, 'For Black Eyes Only', 'When Black Villain shoots Stan''s new wife, Sexpun Tocome, on their honeymoon, Stan teams up with his nemesis to take him down.', 22, '2013-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 14, 'Spelling Bee My Baby', 'Francine tries to rig the school spelling bee so that Steve will win; Stan and Roger try to rush Hayley''s grieving process so she will be available to judge their badminton game.', 22, '2013-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 15, 'The Missing Kink', 'Francine tries to get Stan to spice up their sex life; Hayley tries to get back into dating and accepts a date with Snot.', 22, '2013-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 16, 'The Boring Identity', 'When Stan gets amnesia, Francine tries to turn him into her ideal husband; Steve is drawn into the corrupt side of Roger''s paper route business.', 22, '2013-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 17, 'The Full Cognitive Redaction of Avery Bullock by the Coward Stan Smith', 'Stan is shocked when he is told that Deputy Director Bullock is showing early signs of dementia and needs his memory erased; Roger hires an old friend to help Steve with a bully at school.', 22, '2013-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 18, 'Lost in Space', 'Jeff must prove his love for Hayley to Emperor Zing in order to find his way home from the spaceship that abducted him.', 22, '2013-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 9), 19, 'Da Flippity Flop', 'When Stan refuses to switch Klaus back into his original body, he steals Stan''s body; Roger builds a gym in the attic.', 22, '2013-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 10, 'Season 10', 'Belly-laugh up to the bar, folks… and satisfy your thirst for hilarity with the all-new collection of uncensored American Dad! episodes from the spirited minds of Mike Barker, Matt Weitzman and Family Guy creator Seth MacFarlane. Loaded with celebrity guest voices, including Mariah Carey, Terry Crews, Mark Cuban, Zooey Deschanel, Danny Glover and Olivia Wilde, this intoxicating assortment finds Stan fired from the CIA, Francine haunted by a sex-starved ghost, Steve kidnapped by a Christmas demon, and Roger and Klaus on a 100,000-mile road trip. Please watch responsibly.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 1, 'Steve and Snot''s Test-Tubular Adventure', 'Thwarted in their efforts to secure dates for the upcoming high school prom, Steve and Snot turn to the CIA’s cloning machine to churn out two willing ladies. But, when the device produces two uber-fast-growing newborn babies, the boys must break out their fathering skills to ready them in time for prom night. Meanwhile, Stan takes home the CIA’s cloned pet, Daren the Dodo, with disastrous consequences.', 22, '2013-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 2, 'Poltergasm', 'Francine''s "Poltergasm" starts to haunt the Smith household when she is unsatisfied by Stan in the sack, and Roger must conjure a medium named Zelda Rubinstein to help eliminate the ghost. Meanwhile, Hayley introduces her new boy-toy, Mauricio to the family.', 22, '2013-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 3, 'Buck, Wild', 'Steve decides to prove his manhood by accompanying Stan and his CIA cronies on their annual hunting excursion. Meanwhile, Roger and Klaus undertake a cross-country trek.', 22, '2013-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 4, 'Crotchwalkers', 'In a desperate attempt to show Steve that she''s still a "cool" mom, Francine teaches him a vast array of shoplifting techniques to try out at the local mall. B when their attempt to pull off the ultimate heist at "The Gash" goes awry, Steve is captured and sent to a Venezuelan sweatshop. Meanwhile, Roger, Hayley and Klaus form Langley Falls'' first Russian Balalaika trio.', 22, '2013-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 5, 'Kung Pao Turkey', 'Stan''s plans for a perfect Thanksgiving watching football in his underwear are thwarted when Francine invites her adoptive parents to join them for the holiday.', 22, '2013-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 6, 'Independent Movie', 'Determined to get Snot to confront his emotions after his father passes away, Steve and friends embark on an epic cross-country road trip to the funeral. But Steve''s commitment to his friend wavers when he falls for a Pixie Dream Girl along the way. Meanwhile, Stan and Roger invent an automatic cake-cutter for the Home Shopping Network, but their partnership is tested when they only make a "verbal agreement" to split the profits.', 22, '2013-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 7, 'Faking Bad', 'In this “Breaking Bad” parody, Hayley tries to fit in with a popular group of her former high school friends and, in the process, discovers Steve has an amazing ability to create incredibly realistic fake IDs. Sensing a business opportunity, Hayley builds out Steve’s operation, but they don’t count on having to deal with the other kingpin of the Langley Falls fake ID game: Kevin Ramage (Roger in disguise).', 22, '2013-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 8, 'Minstrel Krampus', 'When Steve starts acting like a spoiled brat during the holidays, Stan takes him to see his incarcerated Grandpa Jack, who tells him the story of how he caught Minstrel Krampus, a legendary demon who punishes naughty children on Christmas. Stan decides that releasing Krampus is the only way to straighten out Steve''s attitude. But when Krampus kidnaps Steve, it''s up to Stan and Roger to get him back. Meanwhile, Hayley gets a job at the airport, but quickly realizes that she might not be cut out for customer service.', 22, '2013-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 9, 'Vision: Impossible', 'Roger suffers a horrific car crash as he tries to take a picture of his crotch on a traffic speed cam. After waking up from a coma, he starts to have eerie visions of the future, and saves the Smiths from a terrible fire. But, Roger''s abuse of his newfound powers soon draws the ire of his fellow family members and the Smiths must learn to cope with the uncertainty of the future.', 22, '2014-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 10, 'Familyland', 'Francine tries to relive the Smith kids'' childhood by taking a group trip to the "Familyland" theme park that ends up being anything but family-friendly.', 22, '2014-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 11, 'Cock of the Sleepwalk', 'Stan mixes up his nighttime routine after his 100th kill, but mistakenly unleashes a "good" Stan in his sleep - Jekyll & Hyde-style - who''s hell-bent on pursuing all the good deeds that real Stan would never consider, and stopping him from ever killing again.', 22, '2014-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 12, 'Introducing the Naughty Stewardesses', 'Roger forges a radical plan to help Steve date the hot girl at school. Roger will switch faces with Steve "Face/Off"-style, seduce her, then tag Steve back in after she''s fallen for him. But, Roger soon decides he may actually want to keep her for himself. Meanwhile, Stan and Francine become "Charlie''s Angels"-type airline stewardesses to thwart an evil plan by Mark Cuban who wants to blow up the sun.', 22, '2014-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 13, 'I Ain''t No Holodeck Boy', 'Stan is frustrated that Steve and his friends never play outside, but Francine refuses to let Stan take the kids to the woods for some outdoor fun. Of course, Stan finds a loophole, by drugging the kids and putting them on the CIA''s holodeck, which, naturally, goes awry. Meanwhile, Hayley buys Roger''s home star on the International Star Registry and claims she''s now his queen.', 22, '2014-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 14, 'Stan Goes on the Pill', 'Stan tries an experimental pill from the CIA and turns into a girl. Meanwhile, Klaus and Roger start a business selling Stan''s suits as he no longer needs them as a female.', 22, '2014-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 15, 'Honey, I''m Homeland', 'Stan attempts to infiltrate the "Occupy" movement, based on CIA intelligence that a leftist cell is planning a terrorist attack. But when he''s captured and returned home by a group of radicals, Hayley suspects her father may have been "turned".', 22, '2014-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 16, 'She Swill Survive', 'Stan fears that Hayley has no life skills so he forces her to take a job as a bartender in Roger''s attic bar but, when Bullock becomes Hayley''s best customer, Stan realizes that he can use his daughter''s knowledge to get ahead at work.', 22, '2014-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 17, 'Rubberneckers', 'Stan''s co-workers at the CIA teach him about "rubbernecking," the art of checking out other women on the sly, away from the gaze of their wives. But when Stan causes a massive accident in an attempt to take a picture of an attractive jogger, he''s interviewed by an intimidating insurance inspector who may rat out Stan to Francine. Meanwhile, Roger and Klaus spill wine on the Smiths'' brand new couch, and vow never to tell the other family members by sitting on the stained spot for the rest of their lives.', 22, '2014-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 18, 'Permanent Record Wrecker', 'Stan is fired from the CIA in a round of budget cuts, but since his 20 years of work experience are classified and hidden from his "permanent record", the only job he''s able to land is at the local grocery store where Steve is the manager. Meanwhile, Roger bets an annoying coffee shop musician that he can outplay him in one week. To accomplish his goal, he enters into a Faustian bargain with Lorenzo, a guitar-instructing infomercial host.', 22, '2014-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 19, 'News Glance with Genevieve Vavance', 'Hayley starts an internship at a local news station working for a Nancy Grace-type reporter, who happens to be Roger in disguise.', 22, '2014-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 10), 20, 'The Longest Distance Relationship', 'Hayley, still heartbroken over Jeff’s abduction, meets millionaire Matt Davis, who begins to help her move forward, until Steve and Snot discover that Jeff’s alive and trying to make it back to her.', 22, '2014-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 11, 'Season 11', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 11), 1, 'Roger Passes the Bar', 'Roger is forced to sell his beloved attic bar to a restaurant chain after suffering a heart attack, and a sexy new next-door neighbor promises to take Steve and his friends’ virginity in return for housework.', 21, '2014-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 11), 2, 'A Boy Named Michael', 'Greg and Terry decide to adopt a 10-year-old Russian boy named Michael. At a party celebrating the decision, Roger is jealous of Greg and Terry''s fabulous lifestyle of culture and sophistication. Roger rejects the Smith family as trashy and impersonates Michael, successfully integrating into his new home.', 21, '2014-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 11), 3, 'Blagsnarst: A Love Story', 'Roger and Francine discover an alien in the woods, and Roger capriciously has a one-night relationship with her before being fed up with her quirks. He tries to get rid of her by calling the CIA, but then realizes that he can’t go through with it.', 21, '2014-09-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 12, 'Season 12', 'Get ready for full-scale hilarity and huge laughs with this all-new collection of American Dad! episodes from the comically oversized minds of Mike Barker, Matt Weitzman and Family Guy Creator Seth MacFarlane. Bulging with celebrity guest voices, including Kristin Chenoweth, Ted Danson, Kim Kardashian, Dean Norris, Mickey Rooney and Uma Thurman, this outrageous assortment finds Stan miniaturized after seeing a shrink, Steve embraces his inner lesbian, Roger crushing on a crash-landed alien , and the return of Jeff from space?.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 1, 'Blonde Ambition', 'When her efforts to save the planet prove hopeless, Hayley decides that she might get more attention if she becomes a blonde. Meanwhile, Stan and Steve go on a mission to find a new home for the Smiths.', 22, '2014-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 2, 'CIAPOW', 'When Bullock sends a drone to do the job Stan and his colleagues are supposed to do, Stan is determined to prove that humans are better than robots. Meanwhile, Francine and the rest of the family participate in a slow motion race against one another in the living room.', 22, '2014-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 3, 'Scents and Sensei-bility', 'Steve and Snot are fed up with being bullied. When they enroll in a karate class, Snot is brainwashed by the sensei, and it''s Steve''s mission to get him back. Meanwhile, Klaus develops a horrible odor and is forced to be an outside pet.', 22, '2014-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 4, 'Big Stan on Campus', 'When the CIA is forced to make cutbacks and go on furlough, Stan volunteers to take a position as a college campus security guard. Meanwhile, Roger opens a bed and breakfast to boost the family''s income.', 22, '2014-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 5, 'Now and Gwen', 'When Francine''s sister Gwen comes to town, Hayley suspects she is up to no good. Meanwhile, Stan teaches Steve the art of hugging Aunt Gwen, and Klaus shadows Roger''s dramatic comments.', 22, '2014-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 6, 'Dreaming of a White Porsche Christmas', 'When Stan wishes he could have Principal Lewis'' carefree, single life, a la "It''s a Wonderful Life," his wish comes true. In Stan''s wish world, Principal Lewis has his family.', 22, '2014-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 7, 'LGBSteve', 'Hayley is dying to be on a roller derby team, but they only will let her play if her ''sister'' Steve gets to play. Meanwhile, a magical carpenter visits Stan and Francine, and Roger runs the roller rink.', 22, '2015-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 8, 'Morning Mimosa', 'When Steve swears at Francine, she refuses to cook for him, and he becomes a successful chef, appearing on a popular morning show. Meanwhile, Stan thinks he can make people invisible by snapping his fingers.', 22, '2015-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 9, 'My Affair Lady', 'Hayley gets a job and starts to fall for a co-worker. Meanwhile, Stan chauffers Steve and Francine to a Mother-Son dance.', 22, '2015-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 10, 'A Star is Reborn', 'While on vacation in Los Angeles, Stan joins the world of old Hollywood. Meanwhile, Roger kennel-trains Steve and Hayley.', 22, '2015-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 11, 'Manhattan Magical Murder Mystery Tour', 'Francine is up for an award for her lonely housewife novel, so the family heads to the Big Apple for the ceremony. Meanwhile, Stan and Hayley hang out with actor Robert Wuhl, and Steve and Roger recreate their Wheels and the Legman personas.', 22, '2015-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 12, 'The Shrink', 'Stan is horrified when he sees a couple die in a car crash, and he goes to see a shrink. Meanwhile, Roger and Klaus study for a wine tasting.', 22, '2015-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 13, 'Holy S***, Jeff''s Back!', 'Jeff returns from space ... or does he? Meanwhile, Steve watches after Snot''s hamster.', 22, '2015-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 14, 'American Fung', '"American Dad" is sold to a Chinese businessman. Meanwhile, Stan has Francine committed to an insane asylum when he forgets their anniversary.', 22, '2015-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 12), 15, 'Seizures Suit Stanny', 'When Stan lies about his texting-and-driving accident, he takes a seizure medication and suffers from the side effects. Meanwhile, Roger helps Steve with his performance anxiety.', 22, '2015-06-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')), 13, 'Season 13', 'Run for your lives! Or better yet, "Stan" your ground and enjoy this all-new collection of American Dad! episodes from the explosive comic minds of Mike Barker, Matt Weitzman and Family Guy creator Seth MacFarlane. Stuffed with celebrity guest voices, including Billy Bob Thornton, Joan Cusack, Sam Elliott, Oliver Platt, and not heavy metal rock god James Hetfield, this hilarious assortmend finds the Smith family in a flood of trouble aboard Stan''s modern-day ark, a time-travelling Steve trying to save his cool future self, Roger deciding to quit all his personas, and everyone fighting to survive the post-apocalyptic 200th episode.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0397306')) AND numero_temporada = 13), 1, 'Roots', 'Stan sets out to stop a tree that he considers his father from being cut down. Steve realizes he''s stopped growing and considers surgery.', 22, '2016-01-25');
