INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')), 1, 'Season 1', 'Deep within the Hidden Leaf Village, young ninja Naruto Uzumaki carries sealed inside him the Nine-Tailed Fox Spirit, which once almost destroyed the village. Always an outcast because of his secret, now Naruto battles alongside his teammates Sasuke and Sakura to prove to himself and everyone else that he''s the greatest ninja ever. But he''s got a long list of challenges to face before he gets there!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 1, 'Enter: Naruto Uzumaki!', 'Welcome to the Village Hidden in the Leaves, where deadly serious Ninja roam the landscape and the seriously mischievous Naruto Uzumaki causes trouble everywhere he goes. But when he steals the ancient scroll of sealing, he unleashes a rare power rarely seen in a 12-year-old boy!', 24, '2002-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 2, 'My Name Is Konohamaru!', 'Naruto finally graduates from the Ninja Academy and claims to know it all. Well, at least that what he tells Konohamaru, the Village elder''s pint-size grandson. Much to the dismay of Ebisu, Konohamaru''s teacher and mentor, Naruto teaches him the hormonally lethal "Sexy Jutsu!"', 24, '2002-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 3, 'Sasuke and Sakura: Friends or Foes?', 'On the way to becoming a ninja, Naruto must team up with his classmates, the pretty Sakura and the pretty serious Sasuke...', 24, '2002-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 4, 'Pass or Fail: Survival Test', 'Now that Naruto, Sasuke, and Sakura are a team, they meet with their sensei, the enigmatic and aloof Kakashi.', 24, '2002-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 5, 'You Failed! Kakashi''s Final Decision', 'With the threat of failure hanging over their heads, Naruto, Sasuke and Sakura try everything they know to pass the grueling survival test.', 24, '2002-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 6, 'A Dangerous Mission! Journey to the Land of Waves!', 'Tired of doing lame missions, Naruto asks the Hokage to give them something challenging. The Hokage caves and gives them a C-rank mission. They will be bodyguards for a bridge builder. It appears to be a simple mission, until the group is attacked by something more than common thugs...other ninja!', 24, '2002-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 7, 'The Assassin of the Mist!', 'Naruto and his squad arrive in the Land of the Waves and learn that an evil businessman named Gato has taken over the land.', 24, '2002-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 8, 'The Oath of Pain', 'With Kakashi captured, Naruto, Sasuke and Sakura must defend against Zabuza''s attacks. Naruto realizes that working together with Sasuke may be the only way to save Kakashi. Will the combined effort of the two be enough to free Kakashi and defeat Zabuza?', 24, '2002-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 9, 'Kakashi: Sharingan Warrior', 'With Kakashi free, the fight between him and Zabuza resumes. Kakashi decides to show Zabuza what the Sharingan is really capable of. Can Kakashi''s Sharingan defeat Zabuza? And who is the mysterious person watching the fight?', 24, '2002-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 10, 'The Forest of Chakra', 'With Zabuza gone things are now settling and Tazuna can go and build the bridge without fear. Or so everyone thinks. Kakashi believes something is wrong with Zabuza''s death and teaches Naruto, Sakura, and Sasuke a way to train so they could better use their chakra. Is Zabuza really dead?', 24, '2002-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 11, 'The Land Where a Hero Once Lived', 'While Naruto and Sasuke train, Sakura watches over Tazuna. During a nice dinner, Sakura notices a man''s face torn from a picture. The man''s name was Kaiza, and he was what the country called...a "hero". What happened to cause Inari so much pain?', 24, '2002-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 12, 'Battle on the Bridge! Zabuza Returns!', 'Naruto has a dangerous encounter with Haku in the forest, but is Haku there to cause trouble? Naruto and Sasuke better complete their training, as Zabuza is alive and has returned for round 2. Will Kakashi, Sasuke, and Sakura be able to defeat the Demon of the Mist? And, can Naruto arrive in time to help out?', 24, '2002-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 13, 'Haku''s Secret Jutsu: Crystal Ice Mirrors', 'Round two with Zabuza has started, but this time...Zabuza has Haku fighting along side him. Haku and Sasuke go at it with Sasuke falling behind until he manages to get a kick in. Meanwhile Naruto deals with some of Gato''s henchmen. Back at the bridge Haku uses his secret jutsu, Demonic Ice Mirrors. What does this jutsu hold in store for Sasuke? Will Naruto make it to the bridge in time and save Tsunami and Inari as well?', 24, '2002-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 14, 'The Number One Hyperactive, Knucklehead Ninja Joins the Fight!', 'Naruto finally joins the battle on the bridge. But when Naruto stupidly gets caught in the middle of Haku''s jutsu as well, he and Sasuke must work together to escape. Kakashi is unable to help them, as he must deal with Zabuza to protect Sakura and Tazuna. How will the two escape from the ice mirrors without any help?', 24, '2003-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 15, 'Zero Visibility: The Sharingan Shatters', 'Naruto and Sasuke continue to fight Haku and are getting beaten bad. After having Naruto try and escape a few times, Sasuke begins to see a pattern. Meanwhile, outside Kakashi and Zabuza begin their fight. Can Naruto and Sasuke escape from Haku''s jutsu? What plan does Zabuza have to defeat the Sharingan?', 24, '2003-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 16, 'The Broken Seal', 'Naruto and Sasuke continue their rigorous battle against Haku. When Haku targets a vulnerable Naruto, Sasuke risks everything to save him. Seeing his friend lie before him, a powerful force awakens inside Naruto. Has Kyubi been set free. If so, can anyone stop him?', 24, '2003-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 17, 'White Past: Hidden Ambition', 'Naruto takes out his rage on Haku, who doesn''t stand a chance. However, Naruto realises that Haku is the boy he met back at the forest. Haku tells Naruto the story of his past and asks for Naruto to do him one favour..... Will Naruto do the one thing he could never do just as Haku wishes?', 24, '2003-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 18, 'The Weapons Known as Shinobi', 'Kakashi prepares to stop Zabuza once and for all, but Haku has other plans. Zabuza''s employer shows up and he''s decided to take matters into his own hands...', 24, '2003-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 19, 'The Demon in the Snow', 'Thinking of Haku, Naruto angrily confronts Zabuza, but he learns that cruel reality is the fate of a ninja.', 24, '2003-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 20, 'A New Chapter Begins: The Chunin Exam!', 'Naruto and his team return to the Village Hidden in the Leaves after their battle in Land of Waves.', 24, '2003-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 21, 'Identify Yourself: Powerful New Rivals', 'After the three ninjas take their leave, Sasuke realizes he has a powerful rival out there. The next day, Kakashi announces that he has recommended all of them for the Chuunin Exams. While Naruto and Sasuke are pleased, Sakura is afraid of letting everyone down. Also, someone decides they aren''t ready and decides to test their abilities.', 24, '2003-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 22, 'Chunin Challenge: Rock Lee vs. Sasuke!', 'Rock Lee challenges Sasuke to a one-on-one fight. Naruto grows angry and attacks him, only to be beaten in one attack. Sasuke realizes the challenge and eagerly accepts. But will Sasuke be defeated just as easily by this mysterious ninja? Sasuke''s only advantage seems to be his Sharingan, but what happens when not even that will work?', 24, '2003-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 23, 'Genin Takedown! All Nine Rookies Face Off!', 'A reunion of all the rookies isn''t a very happy one, as all of them prepare to take the Chuunin Exam. With so many rivals around, Naruto''s team will need help from a fellow ninja named Kabuto to know what they''re up against. Will the group be able to last through the exam?', 24, '2003-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 24, 'Start Your Engines: The Chunin Exam Begins!', 'The first test of the Chuunin Exam is just that, a written test. When Ibiki issues a strict set of rules, Naruto fails to realize the true objective of the test. Can Naruto realize the truth before time runs out? And what about the tenth question?', 24, '2003-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 25, 'The Tenth Question: All or Nothing!', 'Ibiki declares what seems like a harsh and unreasonable rule for the hardest part of the first exam.', 24, '2003-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 26, 'Special Report: Live from the Forest of Death!', 'Konohamaru, the grandson of Leaf Village''s Third Hokage, shows up at the Chunin Exam site. He comes along with Moegi and Udon to cover the events for the Ninja Academy''s school newspaper. Konohamaru looks up to Naruto like an older brother and through interviews with the characters, recaps their adventures thus far.', 24, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 27, 'The Chunin Exam Stage 2: The Forest of Death', 'The second exam is about to begin, and every ninja must sign a form so that their team can get either the Heaven or Earth Scroll. The goal is to get one of each scroll and make it to the tower in five days.', 24, '2003-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 28, 'Eat or Be Eaten: Panic in the Forest', 'To prevent further problems, Sasuke thinks up a password to determine friend from foe, but will it be that simple? Meanwhile Naruto has his hands full with a giant snake. Can he handle this on his own and what about Sasuke and Sakura, can they survive the ordeal?', 24, '2003-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 29, 'Naruto''s Counterattack: Never Give In!', 'Sasuke is about to give up and give their scroll to the enemy, when Naruto stops him and accuses him of being a fake. Naruto then turns his attention to the Grass Ninja.... The battle is intense and when the Grass Ninja appears to get the upper hand, can Sasuke muster up the courage to fight?', 24, '2003-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 30, 'The Sharingan Revived: Dragon-Flame Jutsu!', 'Sasuke is still stuck in his trance and even Sakura''s pleas can''t get him back to normal. Meanwhile, Anko searches for the grass ninja fake. When the team appear to get the upper hand the question begs to be asked. Are the ninja truly defeated, or is there more to them than meets the eye?', 24, '2003-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 31, 'Bushy Brow''s Pledge: Undying Love and Protection!', 'Since Sakura was the only one who did not get injured in the previous battle she must watch over and protect her teammates. Unknown to her though, there are enemies watching from the trees.... They attack, but a friend arrives to help. Will it be enough?', 24, '2003-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 32, 'Sakura Blossoms!', 'Lee in his weakened state is having trouble defeating Dosu. Sakura realises everyone has been protecting her until now and that its her time to protect them! Can Sakura succeed where even Lee failed?', 24, '2003-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 33, 'Battle Formation: Ino-Shika-Cho!', 'With Sakura defeated and facing certain death, more reinforcements step into the fray. However, they sense an even bigger level of power, and its not coming from the sound trio! Meanwhile Sasuke wakes up with an ominous dark aura surrounding him and the mysterious seal spreading over his body. He has but one goal....make his enemies pay!', 24, '2003-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 34, 'Akamaru Trembles: Gaara''s Cruel Strength!', 'Kiba, Shino, and Hinata decide to try and eliminate their opponents by taking more scrolls. They arrive upon a battlefield where three Rain ninjas are battling Gaara, Kankuro, and Temari. They remain hidden and observe the battle, thinking one of the Rain ninjas is a dangerous foe. After realizing Gaara''s amazing abilities, they discover who is the really the dangerous one, and will be lucky if they can sneak away with their lives!', 24, '2003-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 35, 'The Scroll''s Secret: No Peeking Allowed', 'To heal their wounds, Naruto and his team take a much-needed rest after their battle against the Sound ninja. But it has already been four days since the start of the exam and there is only one day remaining until time expires.', 24, '2003-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 36, 'Clone vs. Clone: Mine Are Better Than Yours!', 'Naruto''s team joins Kabuto on their journey to the tower, but on the way, they are trapped by the genjutsu (illusion technique) of the Hidden Rain Village''s genin (low rank ninja), Oboro''s team.', 24, '2003-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 37, 'Surviving the Cut! The Rookie Nine Together Again!', 'The exam is over, but did they truly pass? An old friend arrives to explain and show his concern. Meanwhile, Anko informs the ANBU about Orochimaru, the S-Class criminal who even they cannot stop. Later the Third Hokage explains to everyone what the third exam truly means....', 24, '2003-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 38, 'Narrowing the Field: Sudden Death Elimination!', 'With so many participants still left, the groups are told that they will be pitted against each other in preliminary matches. Kabuto leaves, then Sasuke is told he has to fight. They know that Sasuke was given the cursed seal and if it takes over they will stop him. Can Sasuke stop the seal from taking over again and still win?', 24, '2003-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 39, 'Bushy Brow''s Jealousy: Barrage of Lions Unleashed!', 'The preliminaries of the third exam consist of one-on-one combat, and the first match is between Sasuke and Orochimaru''s minion Yoroi.', 24, '2003-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 40, 'Kakashi and Orochimaru: Face-to-Face!', 'While Shino and Zaku finish their fight, Kakashi works on Sasuke''s cursed seal. However, someone sinister shows up to ruin things, will Kakashi be able to protect Sasuke from this skilled foe?', 24, '2003-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 41, 'Kunoichi Rumble: The Rivals Get Serious!', 'Kankuro takes on Kabuto''s teammate, Misumi, in a quick battle, proving how tough the Sand ninja really are. However, the real match comes when Sakura and Ino are pitted against one another!', 24, '2003-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 42, 'The Ultimate Battle: Cha!', 'Sakura and Ino prepare to settle the score once and for all! However, when Sakura becomes the victim of Ino''s Mind-Body Switch Justu, will she be forced to give up the match?', 24, '2003-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 43, 'Killer Kunoichi and a Shaky Shikamaru', 'Temari of the Sand Village battles against Tenten from the Leaf Village. After the battle its Shikamaru''s turn, but can he defeat an opponent who has already seen his moves once before?', 24, '2003-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 44, 'Akamaru Unleashed! Who''s Top Dog Now?', 'The match between Kiba and Naruto kicks off, with Kiba immediately proving he has the upper hand in the battle. Everyone still believes Naruto is the weak ninja he''s always been, everyone except for Hinata, Kakashi, and Sakura. Now it''s Naruto''s time to shine, and this time...everyone will be watching him!', 24, '2003-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 45, 'Surprise Attack! Naruto''s Secret Weapon!', 'The battle between Naruto and Kiba draws to a close, with each of them giving it everything they''ve got. After being tricked by Naruto, Kiba can no longer rely on Akamaru''s help. Naruto decides now is the time to release his new jutsu, only Kiba won''t give him time to prepare it!', 24, '2003-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 46, 'Byakugan Battle: Hinata Grows Bold!', 'Kiba alerts Hinata, as he''s being taken away, that there are only a few fighters left. He warns her that if she fights Gaara, she has to give up immediately or she could be killed. He also tells her to give up if paired against Neji, because Neji already has issues with her. Just then, the board shows the next fight...Hinata vs. Neji. Just how far will Hinata go to prove herself?', 24, '2003-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 47, 'A Failure Stands Tall!', 'Hinata will not give up so easily, especially with Naruto watching her. Will Hinata be willing to give up her own life in order to prove herself, or will the match be stopped before Neji can connect a killing move?', 24, '2003-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 48, 'Gaara vs. Rock Lee: The Power of Youth Explodes!', 'The second-to-last match finally arrives!  Rock Lee must face down the mysterious and dangerous Gaara, a ninja who is said to have never been truly injured in a fight before.', 24, '2003-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 49, 'Lee''s Hidden Strength: Forbidden Secret Jutsu!', 'As the battle between Lee and Gaara continues, Gai remembers how hard Lee used to train and how Lee has pretty much no ninjutsu or genjutsu skills. Lee is also a dropout, like Naruto. In order to defeat Gaara, Lee will have to use the move Gai forbade him to use.', 24, '2003-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 50, 'The Fifth Gate: A Splendid Ninja Is Born', 'The match between Gaara and Lee draws to an end as Lee unleashes his ultimate move. But will even this be enough to defeat Gaara? Even if Lee does make it out in one piece, even more shocking news awaits him.', 24, '2003-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 51, 'A Shadow in the Darkness: Danger Approaches Sasuke', 'As Chouji faces off against Dosu, Orochimaru gives an order for Kabuto to abduct Sasuke. He also tells Kabuto that if he wants to stop him, he''ll have to kill Sasuke. As Kabuto approaches Sasuke, he hesitates on what to do. His spy cover is soon blown though, as Kakashi appears on the scene. Will Kakashi save Sasuke from Kabuto''s grasp?', 24, '2003-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 1), 52, 'Ebisu Returns: Naruto''s Toughest Training Yet!', 'Naruto wants Kakashi to train him, but Kakashi has other plans. Ebisu arrives to an unhappy Naruto and makes a deal with him. If Naruto can get away from Ebisu, he''ll make Kakashi train him. Naruto decides to accept Ebisu''s challenge, but can he win?', 24, '2003-10-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')), 2, 'Season 2', 'Before the final round of the Chunin Exam, Naruto receives some special training from the legendary Toad Sage, Jiraiya. When the battles resume, Naruto is ready, but what about Sasuke? He''s about to face the one ninja no one, not even Naruto thinks he can beat. But in the midst of everything, a sinister plot is set in motion, and the Village Hidden in the Leaves finds itself under attack!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 53, 'Long Time No See: Jiraiya Returns!', 'While Ebisu trains Naruto at a hotspring, he spots someone trying to peep on the women bathing! Ebisu attacks, but it doesn''t go quite as planned. Naruto then demands that the stranger become his teacher instead, but he''s going to need some convincing. Does Naruto have any special Jutsu for this situation?', 24, '2003-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 54, 'The Summoning Jutsu: Wisdom of the Toad Sage!', 'While Jiraiya attempts to teach Naruto the Summoning Jutsu, while doing research as well, Dosu learns the hard way why Gaara is so dangerous. Meanwhile, Baki and Kabuto secretly meet and reveal a sinister plot against Konoha. When Hayate discovers this dark secret, he attempts to warn the Hokage. However, he''ll have to get through Baki first!', 24, '2003-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 55, 'A Feeling of Yearning, a Flower Full of Hope', 'Sakura goes to visit Sasuke and Lee in the hospital, along the way, she meets up with Ino and the two make the trip together. Lee tries to resume his training with limited success, making Sakura worry more about him and Sasuke.', 24, '2003-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 56, 'Live or Die: Risk It All to Win It All!', 'Since Naruto is having little to no success at summoning frogs, Jiraiya figures that if Naruto''s to learn how summon Kyubi''s chakra, he''s going to need to be put into a life-threating situation. After having Naruto do a bunch of tasks, he throws Naruto off a cliff. Naruto''s only hope of survival lies within an encounter with the Nine-Tailed Demon Fox himself. But, will Kyubi be willing to help him?', 24, '2003-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 57, 'He Flies! He Jumps! He Lurks! Chief Toad Appears!', 'Overjoyed at his success, Naruto manages to enrage Gamabunta. With him not willing to accept that Naruto was able to summon him, Naruto challenges Gamabunta to accept him as his subordinate if he is able to stay on his back until sundown.', 24, '2003-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 58, 'Hospital Besieged: The Evil Hand Revealed!', 'Due to the events with Gamabunta, Naruto is now stuck in the hospital. Shikamaru unexpectedly pays him a visit, saying the two of them are the types who never get girls to visit them. Meanwhile, Gaara approaches an unconscious Rock Lee, with the full intention of taking his life. Luckily for Lee, Naruto and Shikamaru are there to protect him. However, can they save even themselves after learning Gaara''s shocking secret? What is it that Naruto has realized about Gaara?', 24, '2003-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 59, 'The Final Rounds: Rush to the Battle Arena!', 'Waking up late, Naruto hurries to the stadium where the Chuunin matches will be held, along the way he stops at his old training ground and meets up with Hinata. Naruto tells Hinata that he''s afraid he''ll lose, but with Hinata''s encouragement and sort-of-confession of her feelings, Naruto is filled with renewed confidence and proceeds to the stadium leaving a shellshocked Hinata in his wake. Now Naruto must try to make it the stadium before it''s too late, and Konohamaru has a plan to help him out.', 24, '2003-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 60, 'Byakugan vs. Shadow Clone Jutsu!', 'The opening ceremony to the Final Matches begins and Sasuke is missing, worrying Naruto. The ceremony ends and Naruto starts his fight with Neji. Will Naruto''s confidence lead him to a victory or are Neji''s skills to much for him? And where is Sasuke?', 24, '2003-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 61, 'Ultimate Defense: Zero Blind Spot!', 'Naruto begins his assault with his Shadow Clones but Neji analyses Naruto''s actions and determines what he believes to be the real one. Unable to figure out why Naruto won''t admit defeat, he takes off his headband and reveals a mysterious mark on his forehead. What is the truth about his hatred towards the main family of the Hyuuga Clan?', 24, '2003-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 62, 'A Failure''s True Power', 'When it looks as if Naruto can''t win, Neji continues to tell him that he cannot change his fate and that he has no idea what it feels like to carry a seal that cannot be removed. Naruto thinks back about his childhood and how he was treated because of the Nine-Tails sealed inside him. However, that same curse may prove to be his only chance at winning...', 24, '2003-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 63, 'Hit It or Quit It: The Final Rounds Get Complicated!', 'With Sasuke still absent, and everyone anxiously anticipating his match against Gaara, the tournament is forced to move on to the next round. Meanwhile, Neji learns the shocking truth about his father.', 24, '2003-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 64, 'Zero Motivation: The Guy with Cloud Envy!', 'Shikamaru takes on Temari, only he doesn''t want to fight. Can the lazy Shikamaru even last the round? Or is there more to Shikamaru than meets the eye?', 24, '2003-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 65, 'Dancing Leaf, Squirming Sand', 'It''s time for Sasuke''s match against Gaara, only Sasuke has yet to show up. Normally they''d disqualify him, but everyone''s anxiously awaiting the match. Therefore, they give Sasuke a time limit before disqualifying him. As time slowly begins to run out, only one question remains on everyone''s mind...where''s Sasuke?', 24, '2004-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 66, 'Bushy Brow''s Jutsu: Sasuke Style!', 'Sasuke''s match against Gaara finally begins! Gaara seems to have the upper hand at the beginning, until Sasuke shows off his newly found taijutsu techniques. Gaara is reliving the battle against Rock Lee all over again, only this time he''s facing an opponent who can use more than simple taijutsu attacks.', 24, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 67, 'Late for the Show, But Ready to Go! The Ultimate Secret Technique is Born!', 'With Gaara''s ultimate defense in place, Sasuke''s only hope of winning lies within the move Kakashi taught him...Chidori. But, how will Gaara react when Sasuke causes him to bleed?', 24, '2004-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 68, 'Zero Hour! The Destruction of the Hidden Leaf Village Begins!', 'Sasuke''s match is interrupted when Orochimaru puts his plan into action. Temari and Kankuro are ordered to get Gaara to safety until he recovers, leaving Sasuke to chase after them. War has begun!', 24, '2004-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 69, 'Village in Distress: A New A-Ranked Mission!', 'Knowing that Sasuke is in over his head, Kakashi sends Naruto, Sakura, and Shikamaru, being guided by a dog named Pakkun, to stop Sasuke from pursuing Gaara.', 24, '2004-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 70, 'A Shirker''s Call to Action: Layabout No More!', 'Naruto, Sakura, Shikamaru, and Pakkun are being chased down by several Sound ninja. Shikamaru decides to stop and try to hold them off so the others can catch up to Sasuke without fear of pursuit. Shikamaru is the logical choice because of his Shadow Possession Jutsu...needless to say, Shikamaru''s not too thrilled by this.', 24, '2004-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 71, 'An Unrivaled Match: Hokage Battle Royale!', 'The battle of kings has begun as Orochimaru has summoned some unexpected help. How can the Third Hokage handle this uncomfortable situation? Meanwhile, Sasuke finally catches up with Kakurou, Gaara and Temari...', 24, '2004-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 72, 'A Mistake from the Past: A Face Revealed!', 'While Naruto and Sakura continue to catch up to Sasuke, Temari trys to stall Sasuke long enough for Kankuro to get Gaara to safety, but Sasuke doesn''t have time to waste on her! Meanwhile, The Third Hokage continues his battle with Orochimaru and is ready to use a move that not even he knows...', 24, '2004-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 73, 'Forbidden Secret Technique: Reaper Death Seal!', 'An unlikely ally appears to help Sasuke and allows him to continue to pursue Gaara. Meanwhile, the Hokage prepares to make the ultimate sacrifice to rid his village of Orochimaru!', 24, '2004-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 74, 'Astonishing Truth! Gaara''s Identity Emerges!', 'While Shino and Kankuro fight the match they should''ve fought back during the Chuunin Exam, Naruto, Sakura, and Pakkun slowly catch up to Sasuke. Meanwhile, Sasuke has finally caught up with Gaara and Temari, but is he ready to face true horror when Gaara reveals his demon form?', 24, '2004-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 75, 'Sasuke''s Decision: Pushed to the Edge!', 'Sasuke struggles to keep up with Gaara''s monstrous capacity. Only able to use Chidori twice in normal circumstances, Sasuke remembers that tragic day when his family died and realises he must risk the use of Chidori beyond his limit if he is to defeat Gaara. That is, if he can...', 24, '2004-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 76, 'Assassin of the Moonlit Night', 'As Sasuke is about to be defeated, Naruto and Sakura show up to save him. With this Gaara begins to have flashbacks of his childhood. What happened in Gaara''s past to make him experience so much suffering?', 24, '2004-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 77, 'Light vs. Dark: The Two Faces of Gaara', 'Gaara continues to talk about his past. When Gaara states that Naruto can''t become stronger when he fights for everyone else, Naruto recalls that if he didn''t meet his friends, he would be the same as Gaara. Realizing that he has to protect his friends, Naruto overcomes his fear and decides to take on Gaara.', 24, '2004-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 78, 'Naruto''s Ninja Handbook', 'Naruto and Gaara continue their fight. Naruto begins to get an advantage, and Gaara transforms into the final form of Shukaku of the Sand. As he begins to put the squeeze on Naruto, Naruto summons Gamabunta Oyabun, and his comeback begins. Once again, Naruto begins to get an advantage, but Gaara casts the technique of fake sleep, releasing the full power of Shukaku. Now that the demon is free, what will Naruto do?', 24, '2004-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 79, 'Beyond the Limit of Darkness and Light', 'Transformed into Kyubi, Naruto and Gamabunta prepare to stop Shukaku by waking Gaara up. Though they succeed, the battle is far from over as Gaara won''t stop until Naruto is dead. Naruto and Gaara prepare for their final attacks. Meanwhile, Sarutobi continues trying to defeat Orochimaru. And even though Sarutobi isn''t strong enough to kill Orochimaru, he does have enough strength to take away Orochimaru''s most prized possession...the use of his arms!', 24, '2004-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 80, 'The Third Hokage, Forever...', 'As the war draws to a close, Gaara admits his defeat to Naruto, and Orochimaru is forced to retreat as Sarutobi took away his arms. Now, all of the Konoha shinobi gather together to pay their respects to the person whom they respected the most...Sarutobi, the Third Hokage.', 24, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 81, 'Return of the Morning Mist', 'Two mysterious ninja infiltrate Konoha, and one of them bares the Sharingan. Just what are these two after? Why has Itachi Uchiha returned to Konoha?', 24, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 82, 'Eye to Eye: Sharingan vs. Sharingan!', 'Kakashi takes on Itachi, with both of them using the Sharingan. However, Kakashi soon realizes that he stands no chance against the legendary ninja. Itachi reveals that he has not come for his little brother, but instead he''s come to do something else...abduct Naruto, and Kyubi as well!', 24, '2004-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 83, 'Jiraiya: Naruto''s Potential Disaster!', 'Jiraiya and Naruto begin their search for Tsunade, but are constantly sidetracked by Jiraiya''s peeping and hitting on pretty girls. Jiraiya tells Naruto some stories about the 3rd and 4th Hokages. Meanwhile, Sasuke learns that his brother, Itachi, is after Naruto and goes to warn him.', 24, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 84, 'Roar, Chidori! Brother vs. Brother!', 'Sasuke remembers the day that Itachi single-handedly wiped out the entire Uchiha clan as he desperately searches for Naruto. However, Itachi and Kisame have already found him.', 24, '2004-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 85, 'Hate Among the Uchihas: The Last of the Clan', 'Jiraiya and Naruto look on as Sasuke takes on Itachi alone. However, when the young ninja is severely outclassed, Jiraiya is forced to step in. Itachi and Kisame try to flee, but Jiraiya isn''t about to let them get away so easily.', 24, '2004-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 86, 'A New Training Begins: I Will Be Strong', 'Now that Sasuke is in safe hands, Naruto and Jiraiya can continue their search for Tsunade. When they arrive at a city with a festival on the way, Jiraiya and Naruto have some fun, at least until Naruto puts a stain on a man''s shirt. Jiraiya uses a new technique that easily defeats the man and offers to teach it to Naruto. What is this new technique and can Naruto master it?', 24, '2004-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 87, 'Keep on Training: Pop Goes the Water Balloon!', 'Jiraiya gives Naruto the task of rotating the water in a balloon until it pops. Naruto is confident that he will accomplish this stage of the training by night, but soon learns it''s not as easy as expected.', 24, '2004-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 88, 'Focal Point: The Mark of the Leaf', 'After passing stage one of the training, Naruto moves into stage two: power training. Jiraiya realizes that, like him, Naruto has a hard time concentrating, so he paints a spiral in the palm of Naruto''s hand to help him to focus. With the aid of the spiral and a quick flashback to Iruka-sensei, Naruto completes stage two. Meanwhile, Tsunade''s luck has become uncommonly good, which worries her. After being talked into sightseeing by her assistant, Tsunade meets Orochimaru...and she doesn''t look at all pleased.', 24, '2004-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 89, 'An Impossible Choice: The Pain Within Tsunade''s Heart', 'Naruto continues his training of the Rasengan, having mastered the stages of spin and power. The final stage proves to be the most difficult: control. Meanwhile, Orochimaru and Kabuto accost Tsunade and ask her to restore Orochimaru''s arms. If she restores Orochimaru''s arms, he promises to use his Rebirth of the Impure World kinjutsu to revive her lost lover and little brother.', 24, '2004-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 90, 'Unforgivable! A Total Lack of Respect!', 'Jiraiya and Naruto catch up to Tsunade, whereupon she learns that Konoha wants her to be the 5th Hokage. She refuses the title, angering Naruto, who mistakes her for being a weakling. Naruto learns first-hand how strong she really is. Naruto decides now is the time to try out the Rasengan, only he hasn''t perfected it yet.', 24, '2004-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 91, 'Inheritance! The Necklace of Death!', 'Naruto makes a bet with Tsunade, that if he can master the Rasengan in one week, she''ll give him a necklace belonging the to the First Hokage. However, Shizune reveals some startling information. Everybody, except for Tsunade, who''s worn that necklace has died the next day!', 24, '2004-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 92, 'A Dubious Offer! Tsunade''s Choice!', 'While Naruto continues to try and master the third step, Tsunade continues to think about Orochimaru''s offer. Jiraiya tries to convince her by taking her out for a drink, only she slipped a paralyzing potion into his drink while he wasn''t looking. Will Tsunade agree to Orochimaru''s offer? And will Naruto master the Rasengan before the week is up?', 24, '2004-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 93, 'Breakdown! The Deal is Off!', 'Because Orochimaru lied to her about not attacking Konoha, Tsunade begins her onslaught against him and Kabuto. Kabuto eats a food pill and begins to attack Tsunade with his medical techniques but are they enough to defeat her? Will Jiraiya, Shizune and Naruto show up in time?', 24, '2004-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 94, 'Attack! Fury of the Rasengan!', 'With Tsunade still paralized with fear and Naruto being a low level ninja, it is up to Shizune and Jiraiya to defeat Kabuto and Orochimaru. Orochimaru and Kabuto summon two giant snakes while Jiraiya summons Gamakichi, who does nothing. Naruto tries to help Jiraya, but he too only summons a small frog that also does nothing. Orochimaru and Kabuto attack and Shizune is easily defeated. Naruto tries Rasengan but fails. Can he master the technique before Kabuto does anything to Tsunade? How far will he go to master it?', 24, '2004-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 95, 'The Fifth Hokage! A Life on the Line!', 'Naruto finally lands a Rasengan into Kabuto''s stomach, but not before Kabuto assures Naruto''s certain death. Can Tsunade save him and protect him from Orochimaru?', 24, '2004-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 96, 'Deadlock! Sannin Showdown!', 'With Tsunade in her current conidtion, and Jiraiya still under the effects of the drug, Tsunade and Jiraiya must work together to defeat Orochimaru. And with all three ninja having summoned their signature beasts, it''s sure to be one heck of a battle!', 24, '2004-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 97, 'Kidnapped! Naruto''s Hot Spring Adventure!', 'The group are on their way back to Konoha when they stop at a town with hotsprings. Unknown to them they are being watched by men looking for Tsunade. Naruto''s room gets raided and the necklace he was given goes missing with nothing but a ransom note left behind. What does it all mean? Can Naruto get the necklace back and why are they looking for Tsunade in the first place?', 24, '2004-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 98, 'Tsunade''s Warning: Ninja No More!', 'Naruto, Tsunade, and Shizune finally return to Konoha so Tsunade can take over and become Hokage. Konohamaru finds out that Tsunade is the Fifth but refuses to believe it. Naruto then takes Tsunade to the hospital so she can heal Sasuke, Kakashi, and Lee. She heals Sasuke and Kakashi just fine...However, her diagnosis of Rock Lee has heartbreaking consequences for him and his future.', 24, '2004-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 99, 'The Will of Fire Still Burns!', 'Konohamaru locks himself in the office used by the 3rd to stop them from replacing his grandfather, the previous Hokage. Tsunade spends the day locked out of her office and researches a way to heal Rock Lee so he has a better chance of surviving the operation,', 24, '2004-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 100, 'Sensei and Student: The Bond of a Shinobi!', 'As Lee decides whether or not to go through with the operation, Gai decides to give him some motivation. Meanwhile, Tsunade frantically struggles to increase the operation''s success rate.', 24, '2004-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 101, 'Gotta See! Gotta Know! Kakashi-Sensei''s True Face!', 'After their mission, Naruto persuades Sakura and Sasuke to help him unmask their sensei, Kakashi. However, Squad 7 soon finds out that this is easier said than done...', 24, '2004-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 102, 'Mission: Help an Old Friend in the Land of Tea', 'Naruto, Sakura and Sasuke find out their newest mission will be without Kakashi who has responsibilities elsewhere. Tsunade sends them to the Tea Country to protect someone, but the details are vague at best. Along the way they meet Idate Morino who causes the group a lot of trouble, especially when they discover who they have to protect!', 24, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 103, 'The Race is On! Trouble on the High Seas!', 'The trio continue to follow Idate while fending off attacks by three Shinobi sent to kill him. They find out later just how important winning this race is to the Wasabi clan''s future...', 24, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 2), 104, 'Run Idate, Run! Nagi Island Awaits!', 'While the Shinobi that is working for Wasarabi begins to beat up Idate, Naruto, Sasuke and Sakura finally reach the same island. However, some old enemies appear to get in their way once again! Will they manage to find Idate and rescue him before its too late?', 24, '2004-10-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')), 3, 'Season 3', 'Naruto returns from his training journey eager to see his friend Sasuke. But Sasuke has only one thing on his mind: his quest for revenge against his older brother. His unquenchable thirst for power knows no bounds, and soon he is lured from the Leaf Village by Orochimaru''s minions, the Sound Four. Determined to get him back, Shikamaru and Naruto put together a team of the top genin in the village to go after him, and the chase begins!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 105, 'A Fierce Battle of Rolling Thunder!', 'With Naruto''s help, Idate reaches the Modoroki Shrine... But just as he''s about to cross the bridge, an old nemesis stands in his way.', 24, '2004-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 106, 'The Last Leg: A Final Act of Desperation', 'Now that Sasuke and Sakura are trapped at the bottom of a cliff, it''s up the Number One Knucklehead Ninja to defeat the malevolent Aoi and help Idate cross the finish line.', 24, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 107, 'The Battle Begins: Naruto vs. Sasuke', 'Hospital bound and feeling his pride shattered, Sasuke finds there is only way to redeem himself: Battle Naruto! Meanwhile, the Ino-Shika-Cho Squad sit down for some barbeque to celebrate a special occasion!', 24, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 108, 'Bitter Rivals and Broken Bonds', 'As their rivalry reaches a fever pitch, Kakashi-sensei breaks up the battle and sends Naruto and Sasuke to their corners. Meanwhile, Four Sound ninja enter the Hidden Leaf Village with only one thing on their mind... Sasuke!', 24, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 109, 'An Invitation from the Sound', 'Sasuke takes on all four Sound Ninja, but soon learns it''s going to take more than Chidori to defeat them!', 24, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 110, 'Formation! The Sasuke Retrieval Squad', 'Now that word of Sasuke''s departure has spread to the Fifth Hokage, she calls upon the newest Chunin, Shikamaru, to put together a squad to bring Sasuke back to the village.', 24, '2004-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 111, 'Sound vs. Leaf', 'The Sound Ninja have Sasuke in their clutches and it''s up to the Hidden Leaf Village''s top Shinobi to stop them.', 24, '2004-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 112, 'Squad Mutiny: Everything Falls Apart!', 'As Shikamaru and the rest of the squad move in, Jirobo, one of the Sound Ninja, traps them within an Earth Dome Prison and sucks up their chakra!', 24, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 113, 'Full Throttle Power! Choji, Ablaze!', 'Upon breaking free from the Earth Dome Prison, The Sasuke Retrieval Squad realize they don''t have enough chakra to take on Jirobo... but Choji''s got another idea up his sleeve.', 24, '2004-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 114, 'Good-bye Old Friend...! I''ll Always Believe in You!', 'With his life on the line against the Sound Ninja Jirobo, Choji looks back on the seeds of his friendship with Shikamaru. Can he defeat his fearsome opponent without any Chakra?', 24, '2004-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 115, 'Your Opponent Is Me!', 'Hot on Sasuke''s trail, Shikamaru and his squad get caught up in a web of unparalled chakra when they tangle with the six-armed Kidomaru!', 24, '2004-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 116, '360 Degrees of Vision: The Byakugan''s Blind Spot', 'While Naruto and the others go after Sasuke and the other Sound Ninja, Neji is locked in a desperate no-holds-barred battle with Kidomaru.', 24, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 117, 'Losing is Not an Option!', 'Neji''s on the run from Kidomaru''s bow and arrow attacks. Will Neji make it out alive or will his new-found enemy hit his blindspot dead on?', 24, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 118, 'The Vessel Arrives Too Late', 'In pursuit of the Sound Ninja, Naruto, Kiba and Shikamaru strike at dawn to retrieve Sasuke and bring him back to the Hidden Leaf Village.', 24, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 119, 'Miscalculation: A New Enemy Appears!', 'Naruto, Kiba and Shikamaru intercept Sasuke from the Sound Ninja Four, but little do they know that another ninja from the Sound Village has been dispatched to grab Sasuke as well.', 24, '2005-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 120, 'Roar and Howl! The Ultimate Tag-Team!', 'Faced against the vicious twin duo of Sakon and Ukon, Kiba and Akamaru team up to take them out, using their most powerful jutsu.', 24, '2005-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 121, 'To Each His Own Battle', 'With the Sasuke retrieval squad now split into individual battles, it''s up to Naruto, Kiba and Shikamaru to stop the sound ninja. But little do they realize that there''s more to their opponents than their basic techniques.', 24, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 122, 'Fakeout: Shikamaru''s Comeback!', 'Shikamaru''s got his hands full with Tayuya and her melodic attacks. Can he stop her and put an end to her malevolent flute playing?', 24, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 123, 'The Leaf''s Handsome Devil!', 'Naruto''s Shadow Clones are no match for Kimimaro''s attacks. But when an old bushy-browed buddy from the Leaf Village shows up, all bets are off!', 24, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 124, 'The Beast Within', 'Rock Lee''s back and he''s full of a special medicine that has Kimimaro on the run! Can he take out the fifth Sound Ninja?', 24, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 125, 'The Sand Shinobi: Allies of the Leaf', 'Down for the count and at the mercy of the Sound Ninja, Kiba, Shikamaru and Rock Lee get help from an unlikely bunch of new allies.', 24, '2005-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 126, 'Showdown: Gaara vs. Kimimaro', 'Itching to fight and with a sense of guilt from the past, Gaara tells Rock Lee to stand down and let him take on Kimimaro. Meanwhile, Naruto continues on his quest to catch the runaway Sasuke.', 24, '2005-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 127, 'Vengeful Strike! The Bracken Dance!', 'As Gaara demonstrates he has more than enough backbone to take on Kimimaro, Orochimaru recollects on how he brought him as a young man into the Sound Village.', 24, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 128, 'A Cry on Deaf Ears', 'Finally catching up to Sasuke, Naruto does all he can to keep him from going to Orochimaru. Does he have enough strength to stop him or is Sasuke gone for good?', 24, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 129, 'Brothers: Distance Among the Uchihas', 'Naruto and Sasuke face off in battle as we get a glimpse into Sasuke''s past where his achievements were ignored by his father and his brother Itachi''s behavior began to take a turn for the worst.', 24, '2005-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 130, 'Father and Son, the Broken Crest', 'As Sasuke squares off against Naruto, he reflects on his past when he was neglected by both his stern father and Itachi, his brooding older brother.', 24, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 131, 'The Secrets of the Mangekyo Sharingan!', 'While Naruto is busy underwater, Sasuke remembers the fateful day in which his clan was killed. He remembers why Itachi spared his life, and why Itachi did what what he did. Now, in order to gain the same power as his brother, he must kill his closest friend...Naruto!', 24, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 132, 'For a Friend', 'Kakashi learns the truth about the chase after Sasuke, and orders his dogs, including Pakkun, to go find Naruto and Sasuke. However, things are looking grim as the clash between the Chidori and the Rasengan ensues. The attacks are even, causing Naruto and Sasuke to both fly back. Naruto finally realizes how serious Sasuke is, and gets the snot beat out of him while he remembers how he always wanted to be friends with Sasuke.', 24, '2005-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 133, 'A Plea from a Friend', 'Naruto proves to be too much for Sasuke to handle as Naruto fights back with renewed vigour. Finally acknowledging Naruto''s strength, Sasuke puts on his forehead protector, symbolizing both as equals. But when Sasuke''s Sharingan is upgraded to level 3, the tables turn on Naruto. Just when all hope seems lost for Naruto, he undergoes a startling transformation, but will it be enough?', 24, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 134, 'The End of Tears', 'The battle between Naruto and Sasuke comes to a close, as One-Tailed Naruto takes on Cursed Seal Level 2 Sasuke in one final Rasengan vs. Chidori clash! And this time...only one person will emerge victorious. Will Kakashi and Pakkun make it in time? And who is this mysterious ninja watching everything?', 24, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 135, 'The Promise That Could Not Be Kept', 'Shikamaru''s group is brought back to Konoha with many injuries. Neji and Chouji could possibly die, Kiba has a deep wound but nothing too serious, and Naruto and Shimakamru have a few injuries. When Sakura finds out they are back ,she goes immediatley to see Sasuke and Naruto but finds out Sasuke got away. Can Naruto keep his promise to Sakura? And what news does the Jiraiya have for Naruto?', 24, '2005-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 136, 'Deep Cover?! A Super S-Ranked Mission!', 'Jiraiya begins to worry about Naruto and Sakura''s wellbeing. He then requests that Tsunade send them on a mission with him. He finds Naruto telling Sakura he is not going to stop her from going after Sasuke, but he is going with her, and tells them about the mission. They head off to Rice Country to find the Hidden Sound Village, and hopefully Sasuke as well.', 24, '2005-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 137, 'A Town of Outlaws, The Shadow of the Fuma Clan', 'Naruto, Sakura and Jiraiya end up in a town that is even worse than the one they were chased out of. Jiraiya heads off and leaves Naruto and Sakura to get some food. Along the way they find the ninja that attacked them before, but things are not as clearcut as they might seem.', 24, '2005-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 138, 'Pure Betrayal, and a Fleeting Plea!', 'When Sasame drugs the gang, she prepares to hand them over to Orochimaru. But, when she discovers that they are to be killed, she has a change of heart...', 24, '2005-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 139, 'Pure Terror! The House of Orochimaru', 'Sasame leads Naruto, Jiraiya, and Sakura to Orochimaru''s hideout. They send Sasame back to the village because of the danger level. Jiraiya summons Gamakichi to go in first and investigate. The four come to three tunnels. Jiraiya goes off to the right, Naruto and Sakura down the middle and Gamakichi down the left. Will the four of them make it past the traps?', 24, '2005-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 140, 'Two Heartbeats: Kabuto''s Trap', 'Naruto arrives in the nick of time to save Sakura, but not before Kabuto tells her that Sasuke is dead! Naruto attacks but ends up tangled in a deadly trap of Kabuto''s. Is it all over for our hero and will they find Arashi?', 24, '2005-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 141, 'Sakura''s Determination', 'The battle between Naruto and Arashi continues, but Naruto''s injury is making it difficult for him to succeed. Sasame jumps in to try to save Naruto but will it be enough?', 24, '2005-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 142, 'The Three Villains from the Maximum Security Prison', 'With the events of the Rice Field Country behind them, everyone prepares for their training. But a new threat soon arises. Remember Mizuki? He''s back and he''s planning to break out of Konoha''s Correctional', 24, '2005-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 143, 'Tonton! I''m Counting on You!', 'Shizune and her team encounter Mizuki, but it doesn''t go as planned! When Ton-ton comes back to warn Tsunade, Naruto takes the initiative to find Shizune with Ton-ton''s help. Kakashi arrives and lends Pakkun''s assistance to Iruka before departing on a mission of his own. Will it all be enough to save the day?', 24, '2005-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 144, 'A New Squad! Two People and a Dog?!', 'Naruto is having trouble with the two brothers and Iruka is having his share of difficulties with Mizuki! Iruka struggles to try and get the old Mizuki back but he doesn''t have much success.... Meanwhile, when things are looking bleak for Naruto, can 3 friendly Ninja save the day?', 24, '2005-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 145, 'A New Formation: Ino-Shika-Cho!', 'Naruto''s backup has arrived and they are Shikamaru, Ino, and Chouji. They tell Naruto that they will take care of the brothers. Naruto leaves to catch up to Iruka, who is fighting Mizuki. Can Naruto arrive before Mizuki kills Iruka? And can Shikamaru, Ino, and Chouji hold off the brothers?', 24, '2005-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 146, 'Orochimaru''s Shadow', 'Naruto, Iruka and Pakkun meet up with Mizuki''s fiancee Tsubaki and she has come to offer help to the three. Meanwhile, Shikamaru, Ino and Chouji are having trouble holding the two brothers at bay. While this is going on, Tsunade discovers a startling secret about Mizuki and Orochimaru and plans to take matters into her own hands....', 24, '2005-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 147, 'A Clash of Fate: You Can''t Bring Me Down!', 'Mizuki is determined to make Naruto and Iruka suffer and it appears that he has the upper edge with his improved strength and speed! Shikamaru, Ino and Chouji are also at their limits and now Fuujin and Raijin are free. Can Tsunade arrive in time to help?', 24, '2005-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 148, 'Search for the Rare Bikochu Beetle', 'Naruto is unable to search for Sasuke due to Tsunade''s orders, while Kiba and Hinata wonder how they can help him out. Shino remembers a special type of bug that if it is found, could easily track Sasuke down. they go and discuss it with Tsunade, who agrees to let them search for it, making Shino the leader. Tsunade discovers Naruto eavsfropping the conversation and lets him go with them. But, can they complete a mission with only a 10% success rate? As they travel, Naruto has difficulty dealing with Shino''s bizzare behavior. Hinata also sneaks out in the middle of the night to practice some mysterious moves. After two days of travelling, they finally reach their destination. And they''re not alone, a mysterious group is also after the same thing.', 24, '2005-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 149, 'What''s the Difference? Don''t All Insects Look Alike?', 'The group struggles to find a Bikouchuu, but seem to fail at every turn. When it starts to rain they realise they only have one more chance to find it, will Hinata''s Byakugan be enough?', 24, '2005-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 150, 'A Battle of Bugs: The Deceivers and the Deceived', 'With Hinata''s safety in danger, the group must try and figure out a way to save her and protect the Bikouchuu at the same time. Every time one side seems to have an edge though, the other reveals yet a new trick. As dawn approaches, they don''t have long left....can they succeed?', 24, '2005-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 151, 'Blaze Away, Byakugan! This is My Ninja Way!', 'With the group trapped, Shino makes a deal to trade the Bikouchuu for Hinata. Unfortunately for the opponents, Hinata got away, making the deal worthless! They begin to attack but can Hinata show up to save the day?', 24, '2005-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 152, 'Funeral March for the Living', 'When Naruto rescues three strangers he finds himself dragged into yet another mission. However, this time he doesn''t want to partake in it! That is until he hears that there might be a connection to Akatsuki. With Neji, Lee and Tenten as his teammates, will he find the information he is looking for?', 24, '2005-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 153, 'A Lesson Learned: The Iron Fist of Love!', 'Out to try and save Rourusuke, Naruto and the others ambush members of the Kurosuke Family and save an old man. They soon hear the funeral bell and go and save Rourusuke. However, Rock lee meets an old friend among the group, and Lee must now convince Kurashi to return his his old way of life. Their time together is cut short, as Raiga watches from the sidelines. Can Naruto, Neji, Rock Lee, and Tenten defeat an enemy that not even Neji''s Byakugan can see?', 24, '2005-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 154, 'The Enemy of the Byakugan', 'Naruto, Tenten, Neji and Lee continue their mission to stop Raiga and save the Rourusuke Family. They try to work out a plan but the thick fog makes it difficult for them to see. Even Neji''s Byakugan doesn''t seem to help. Lee fights Raiga and manages to knock a bag off his back. What is this bag and what is inside it that seems so important? Meanwhile Naruto steps up to battle Raiga. Will he be able to defeat him?', 24, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 155, 'The Dark Creeping Clouds', 'With Raiga seemingly defeated, the group can get on with clearing up the remaining enemy Ninja and returning the village to normal. However, what will they do with Ranmaru who tells them about his tragic past?', 24, '2005-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 156, 'Raiga''s Counterattack', 'Ranmaru is determined to bring Raiga back from the dead and appears to suceed! An enraged raiga now goes on the offensive, starting with Tenten. Karashi runs back to the Curry House to tell the others what has happened, but who''s side is he really on?', 24, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 157, 'Run! The Curry of Life', 'Lee is left facing Raiga alone while Tenten and the others hurry to bring them the curry of life. Ranmaru is reunited with Raiga, but are things the same as they were before?', 24, '2005-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 3), 158, 'Follow My Lead! The Great Survival Challenge', 'Every Genin is assigned a squad of Cadets to lead on a mission that forces all of them to race to the top of a mountain to retrieve a scroll and, wouldn''t you know it, guess who Naruto ends up leading? Its none other than the Konohamaru corps. However, when a storm causes the mission to be cancelled without his knowing, he will have to be a better leader than ever to keep his team alive!', 24, '2005-11-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')), 4, 'Season 4', 'In the Village Hidden in the Leaves, there are few things Naruto and Choji love more than a steaming bowl of Ichiraku ramen, and when the daughter of the owner is kidnapped, they''re on the case. Then, missions for the Leaf ninja lead them to the Land of Bears after a fallen meteorite and the Land of Greens to protect a princess. When an evil ninja who''s after the princess gets in their way, it''s Naruto''s life on the line!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 159, 'Bounty Hunter from the Wilderness', 'Naruto, Hinata and Kiba are sent off on a mission to capture a thief named Gosunkugi. However, on the way they meet another bounty hunter, who is after the same target as them....', 24, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 160, 'Hunt or Be Hunted?! Showdown at the O.K. Temple!', 'Turns out Sazanami is really a wanted criminal named Toukichi who is wanted for the murder of a family of three. Truth is however, he''s innocent, and wants to capture the man responsible to prove it! Sazanami teams up with the Konoha group to stop Gosunki once and for all....', 24, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 161, 'The Appearance of Strange Visitors', 'As Gai and Lee leave Konoha on a mission, two strangers disguise themselves as them and sneak into the village to learn its secrets. Tsunade, Sakura and Tenten have big plans in store for these imposters, plans that''ll make their lives miserable.', 24, '2005-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 162, 'The Cursed Warrior', 'Naruto, Tenten, and Neji travel to the Bird Country to exterminate a ghost named Noroimusha.', 24, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 163, 'The Tactician''s Intent', 'Naruto and the others attempt to prove that Kouhmei is the one responsible for the ghost. However, what Naruto and the gang discover leaves even more mysteries unsolved.', 24, '2005-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 164, 'Too Late for Help', 'Naruto decides to do some investigating on his own over the matter of the ghost, while Neji and Tenten try a different approach. WIth the help of two frogs, Naruto begins to learn more and more about the truth of the matter....but will what he discovers, cost him his life?', 24, '2005-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 165, 'The Death of Naruto', 'Kakashi orders Neji and Tenten to return to the village with him, much to their protest. Meanwhile Koumei is about to be executed, at least until the Noroimusha shows up! Is the ghost an ally or an enemy and whatever became of Naruto? Questions are answered as Sagi reveals the truth!', 24, '2005-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 166, 'When Time Stands Still', 'Sagi prepares his plans for revenge and he won''t let anyone stand in his way! Disguised as the Noroimusha, he confronts Musou, but shocking news is revealed when they both reveal their true identities!', 24, '2006-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 167, 'When Egrets Flap Their Wings', 'Shima saves Naruto from Ooki''s genjutsu trap and proceeds to try and protect him. When all seems lost for our hero, a mysterious white figure appears and asks him to grant one last wish. Will Naruto find the strength to grant this request and save the day?', 24, '2006-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 168, 'Mix It, Stretch It, Boil It Up! Burn, Copper Pot, Burn!', 'Mr. Ichiraku, the owner of the Ichiraku Ramen shop is in trouble. His daughter has been kidnapped and he only has two days to win her back! Can Nauruto, Chouji and Sakura help Mr. Ichiraku win the contest, or will he have to hand over his Legendary Ramen recipe?', 24, '2006-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 169, 'Remembrance: The Lost Page', 'Being some of the few Genins available, Naruto, Ino, and Shino are forced to accompany Anko on her mission to the Sea Country to destroy a sea monster and protect a boat carrying gold. However, Anko is acting strange as she begins to remember more and more events from her past, and the connection she once had with Orochimaru.', 24, '2006-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 170, 'The Closed Door', 'Naruto is recovering thanks to the mysterious girl, Isaribi. While Naruto is recovering, Anko, Shino, and Ino search for him and also meet the man in charge of the payroll shipment. The group eventually meets back up, but not before finding the sea monster''s lair.', 24, '2006-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 171, 'Infiltration: The Set-Up!', 'After Isaribi escapes, Naruto and his team decide to go to the forbidden island and confront Orochimaru and his subordinates. They soon discover that Orochimaru is not the man behind the curtain, but a man known as Amachi. Amachi is the one responsible for turning Isaribi into a monster, so why is she helping him?', 24, '2006-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 172, 'Despair: A Fractured Heart', 'After narrowly escaping the collapsing lab, Naruto and the others must catch up to the money convoy. However, Amachi has already set his trap, and the convoy crew has taken the bait. Naruto and the others arrive to save the day, as all of them prepare for battle. But can the group defeat Amachi when he reveals his true self? And what will happen when Isaribi realizes how far Naruto will go to save her?', 24, '2006-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 173, 'The Battle at Sea: The Power Unleashed!', 'Naruto and Amachi''s battle comes to a rather quick end, or does it? Also, Anko recovers more of her past including a significant event.', 24, '2006-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 174, 'Impossible! Celebrity Ninja Art - Money Style Jutsu!', 'Naruto was assigned a special mission to protect the son of a VIP. The boy was a spoiled brat who thought money could buy him anything. Naruto was tasked with teaching the boy about ninja skills, but the boy was more interested in playing video games.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 175, 'The Treasure Hunt is On!', 'Naruto, Kiba, and Hinata were assigned a special mission to find a hidden treasure. The treasure was said to be buried in a cave in the mountains. The three ninjas set off on their mission, and they soon found the cave.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 176, 'Run, Dodge, Zigzag! Chase or Be Chased!', 'Naruto, Kiba, and Hinata were on their way back to Konoha when they were attacked by a group of ninjas. The ninjas were wearing the same uniforms as Naruto, Kiba, and Hinata, and they claimed to be the real ninjas.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 177, 'Please, Mr. Postman!!', 'Naruto accidentally met up with Jiraiya while he was working on his next book. Naruto begged Jiraiya to train him, but Jiraiya refused. He told Naruto that he had to finish his book first.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 178, 'Encounter! The Boy with a Star''s Name', 'About 200 years, a star fell to the Hidden Star Village. This star supposedly as mystic powers. However, the village has few ninja, so they require the help of other villages. Naruto accompanies Lee, Neji, and Tenten on a mission to protect it.', 24, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 179, 'The Remembered Lullaby', 'When the mysterious attacker flies away with the star, using only their Chakra, the Konoha group are left in the dust. They swear to reclaim the star but it isn''t as simple as they might hope. Meanwhile, Naruto learns some of Subaru''s history and Natsuhiboshi...', 24, '2006-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 180, 'Hidden Jutsu! The Price of the Ninja Art: Kujaku', 'The Konoha team continue to investigate the star''s theft and start to realise everything is not quite as it seems. Everything seems to be leading to a final battle, but who is the real enemy behind all this?', 24, '2006-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 181, 'Hoshikage: The Buried Truth', 'Naruto has been rescued by the mysterious woman and soon learns who she really is. Can the two of them continue the mission the was started so very long ago and what will Subaru think when he discovers the truth?', 24, '2006-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 182, 'Reunion, The Remaining Time', 'Subaru finally meets his mother, but is it too late for them? Can Naruto defeat Akahoshi and stop the star from falling back into his hands, and what side will the village choose to take?', 24, '2006-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 183, 'The Star''s Radiance', 'After Akahoshi tries to execute Sumaru, Hakato and the rest of the children stand up to protect their village. Akahoshi, finding the village turning against him, takes drastic steps to ensure his success. Naruto is the only one left who can take down this menace, can he do it alone? or will he find help from someone more powerful....', 24, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 184, 'Kiba''s Long Day!', 'When Akamaru is taken ill and starts to undergo a mysterious transformation, can Kiba do anything to save his friend? When the whole village appears to be against him what lengths will he go through, to protect his friend?', 24, '2006-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 185, 'A Legend from the Hidden Leaf: The Onbaa!', 'While Naruto trains in the forest, a mysterious creature latches onto his back. This legendary creature can''t be removed until it becomes an adult, but that''s only the beginning of Naruto''s problems.', 24, '2006-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 186, 'Laughing Shino', 'Naruto and Shino go on a mission together to Motoyoshi Village, where a man named Fuuta has a strange request. To receive his inheritance money, he must not laugh at his fathers funeral. There is however one clause that may be enough to save him from losing everything when his relatives try every trick in the book, to cause laughter...', 24, '2006-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 187, 'Open for Business! The Leaf Moving Service', 'Naruto, Hinata, and Chouji are chosen on a mission to protect some peddlers running away from a war at the Greenery Country. However, Tsunade gave them more than just a simple guard duty mission, making them movers as well. The peddlers are just simple folk, who were never even registered citizens in the country. But, when Naruto discovers the group is being pursued, the three ninja realize that there is more going on than meets the eyes.', 24, '2006-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 188, 'Mystery of the Targeted Merchants', 'The group splits off into two, in an attempt to deter their mysterious attackers. However, when Naruto and Chouji discover the plan hasn''t worked as intended, they soon realise that somebody is hiding something important....', 24, '2006-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 189, 'A Limitless Supply of Ninja Tools', 'Naruto, Chouji, and Yurinojou take on Ruiga, who uses water as a weapon. Ruiga has the power to draw out water from the Earth, giving him an unlimited supply of ninja weapons. How can they defeat an opponent who has a limitless supply of water? Even if they can win, can they defeat the second ninja, Jiga? Also, what is the Princess'' true motive for running away?', 24, '2006-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 190, 'The Byakugan Sees the Blind Spot!', 'With Naruto defeated, Hinata decides to join the fight. Will she be able to defeat the second evil ninja? And what of the princess?', 24, '2006-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 191, 'Forecast: Death! Cloudy with Chance of Sun!', 'The battle with the third and final evil ninja is on. He has only one desire and that is to kill Princess Haruna. Will Naruto be able to defeat this new menace and save Haruna?', 24, '2006-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 192, 'Ino Screams! Chubby Paradise!', 'When the daughter of a Feudal Lord calls for a double, Ino is brought in to take her place. The only problem is they look nothing alike, the princess has become big boned because she had a lot of stress and ate a lot. Now Ino must stand in for her and arrange a marriage with a man from Udon Country. Can Ino arrage the marriage without problem?', 24, '2006-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 193, 'Viva Dojo Challenge! Youth is All About Passion!', 'When Naruto returns from a mission, he discovers that Lee has set up a Dojo and is desperate for a challenger. When Gai discovers nobody has challenged him he steps up to the plate! However, a last minute change in plans throws changes everything, and when an imposter joins the fray, chaos ensues....', 24, '2006-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 194, 'The Mysterious Curse of the Haunted Castle', 'Naruto, Hinata, and Kiba are sent to the Land of Honey to search for the Daimyō''s wife. There, they find an eerie castle, and journey inside to search for clues.', 24, '2006-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 195, 'The Third Super-Beast!', 'When Lee misses his check-up with Tsunade, Naruto is sent to find him. Meanwhile Gai is training someone called Yagura and has decided that Lee and Yagura should have a training match. Can Lee beat the new trainee after hearing some uncomfortable news at his examination?', 24, '2006-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 196, 'Hot-Blooded Confrontation: Student vs. Sensei', 'Gai is trapped inside a fortress made of practice posts. Yagura appears but is he there to help or to hinder? Naruto, Neji and Tenten show up to try and rescue Gai, but will it be too much for them to handle on their own?', 24, '2006-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 197, 'Crisis: The Hidden Leaf 11 Gather!', 'Naruto meets an old man, a construction worker named Gennou. However, when Gennou steals plans for some of the buildings in Konoha, Naruto suddenly finds himself under investigation by the ANBU. What is the truth behind Gennou and why does nobody seem to know what is going on?', 24, '2006-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 198, 'The ANBU Gives Up? Naruto''s Recollection', 'In order to get the information they need about Gennou, the ANBU put Naruto in a trance, hoping to prong the information they need from Naruto''s memory. However, even by doing all of this, will they get the information they need?', 24, '2006-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 199, 'The Missed Target', 'Naruto and the others continue their search for any clues leading to Gennou or his plan. During an investigation of the Ninja Academy, they discover a suspicious training post which leads to an even scarier discovery.', 24, '2006-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 200, 'The Powerful Helper', 'With the city of Konoha mapped in explosive tags, a decision must be made weather to try and remove them, or to evacuate the entire city! However, something is strange about these tags, can they discover what it is? And can they remove all of them in time?', 24, '2006-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 201, 'Multiple Traps! Countdown to Destruction', 'While Shikamaru tries to figure out what Gennou is planning next, Naruto is fighting Gennou in the Great Stone faces. Can Shikamaru stop Gennou''s next step in the plan before it is to late? And will Naruto be able to defeat the Trap Master?', 24, '2006-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 202, 'The Top 5 Ninja Battles!', 'Naruto and Sakura host a special recap episode featuring the top five battles so far! There are also interviews with some of the team, and perhaps even some of the enemy....', 24, '2006-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 203, 'Kurenai''s Decision: Squad 8 Left Behind', 'Naruto encounters a girl named Yakumo who has a surprising talent for destruction. Shortly after, Kurenai Yuhi, leader of Team 8 makes a startling decision and Naruto is determined to find out why.', 24, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 204, 'Yakumo''s Sealed Ability', 'Naruto sneaks into Yakumo''s mansion in the night, and has a dream that Kurenai threatened to seal Yakumo''s abilities. He then discovers that this is the reason why she left the team, but Kurenai refuses to disclose any more. As Kurenai goes to see Yakumo, several Kurama Clan members attack.', 24, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 205, 'Kurenai''s Top Secret Mission: The Promise with the Third Hokage', 'As Kurenai attempts to escape with Yakumo, Naruto and Sakura, Team 8 and Might Gai arrive to lend their assistance. We learn some of the history between Kurenai and Yakumo and discover why things have turned out the way they have...', 24, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 206, 'Genjutsu or Reality?', 'Naruto, Kurenai, Yakumo and Team 8 return to Konoha to a shocking discovery. Can this really be reality or is it all some kind of sick illusion?', 24, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 207, 'The Supposed Sealed Ability', 'Naruto and the members of Team 8 head into Yakumo''s house to find her with Kurenai. It is revealed that a mysterious entity might be behind all this. Can the group discover the truth in time?', 24, '2006-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 208, 'The Weight of the Prized Artifact!', 'Naruto and Kiba are ordered to escort a man named Shinemon who is transporting a rare and valuable artifact. However, when Bandits steal the artifact, can the pair retrieve it and keep Shinemon alive?', 24, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 209, 'The Enemy: Ninja Dropouts', 'Naruto, Sakura and Lee are sent to escort a prisoner named Gantetsu to the Forest Country Capital. Their job is only to back up the escort group incase something goes wrong, which inevitably, it does....', 24, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 210, 'The Bewildering Forest', 'With the ship split in half, Naruto, Todoroki and Gantetsu are seperated from the others. Now Naruto must face the other three Shinobazu that Gantetsu was with. Can Naruto lead them out or will they have to trust Gantetsu to lead the way?', 24, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 211, 'Memory of Flames', 'Todoroki wants to avenge his family and kill Gantetsu. The only problem is that Naruto has other ideas. Elsewhere, Lee and Sakura are surrounded by children who are demanding they give them Gantetsu. Can Naruto and Todoroki get Gantetsu back? And what are the childrens reasons for wanting him?', 24, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 212, 'To Each His Own Path', 'Naruto arrives to save Gantetsu and the kids but has trouble when Akio is kidnapped and Todoroki realizes his brother is alive. Will Naruto and Todoroki be able to save Akio?', 24, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 213, 'Vanished Memories', 'Naruto rescues a kid who was injured but he is an outsider to Konoha. Tsunade assigns Naruto to take care of the kid until he gets his memory back. What was this kid doing outside of Konoha and why can''t he remember anything?', 24, '2006-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 214, 'Bringing Back Reality', 'Naruto and Menma manage to get Tsunade to let them go find Menma''s memories. However, they are forced to go with Neji and Tenten guarding them. On the way, they come across a burned-down village. There, they greet the villagers and ask them what happened. Unfortunately, the villagers aren''t too happy to see them.', 24, '2006-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 215, 'A Past to Be Erased', 'Ran wants to kill Menma, upon seeing the mark on his arm, but Neji stands in the way, saying it would be unfair to kill a criminal without any memories of his crimes. Ran finally agrees and performs surgery on Menma, saving his life, but the villagers aren’t as happy. Are they prepared for when foreign shinobi group comes for a second attack?', 24, '2006-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 216, 'The Targeted Shukaku', 'A Sand shinobi, Matsuri, has been abducted by a mysterious ninja. In order to bring them bring back, Gaara must accept the mystery ninja''s challenge. Can Naruto prevent this challenge ending in catastrophe?', 24, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 217, 'Sand Alliance With The Leaf Shinobi', 'The rogue ninjas continue running as Gaara, Temari and Kankuro give chase. At the same time, Shino, Hinata and Neji are using their abilities to try and find the Shitenshounnin. Who will end up fighting first and, who will ultimately win?', 24, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 218, 'The Counterattack!', 'Shikamaru and Ino arrive to help out Temari against Kyaku, while Kiba and Chouji go to help Konkuro. All seems to be going well until Neji notices something odd...', 24, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 219, 'The Ultimate Weapon Reborn', 'Even with his chakra so low, Gaara fights the Shitenshounin leader. When he fails and is trapped, Naruto arrives to try and rescue him. But when the leader of Takumi Village, Seimei, is revived, can Naruto save Gaara before Shukaku takes complete control of him?', 24, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0409591')) AND numero_temporada = 4), 220, 'Departure', 'The exciting conclusion to Naruto. What will become of Gaara, and now that Jiraiya has returned, will Naruto finally leave Konoha to begin his training?', 24, '2007-02-08');
