INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0414852', 'District B13', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0603628'), 'PELICULA', 'Captain Damien must team up with Leito, a local insurgent from District 13, to defuse a neutron bomb that has fallen into the hands of a local drug lord, Taha, and rescue Leito''s sister Lola.', '2004-01-01', 'https://m.media-amazon.com/images/M/MV5BYTBiN2MyZTEtY2VjMi00ZDg1LWE3MGUtY2I1MDJmNjMxNGE5XkEyXkFqcGc@._V1_.jpg');
