INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')), 1, 'Season 1', 'Mysteries abound on the first season of LOST as the survivors of Oceanic Air flight 815 find themselves stranded on an unidentified island with little hope of rescue.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 1, 'Pilot (1)', 'Stripped of everything, the 48 survivors scavenge what they can from the plane for their survival. Some panic. Some pin their hopes on rescue. A few find inner strength they never knew they had-like Kate who, with no medical training, suddenly finds herself suturing the doctor''s wounds. The band of friends, family, enemies and strangers must work together against the cruel weather and harsh terrain. But the intense howls of  mysterious creatures stalking the jungle fill them all with fear. Fortunately, thanks to the calm leadership of quick-thinking Jack and level-headed Kate, they have hope. But even heroes have secrets, as the survivors will come to learn.', 42, '2004-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 2, 'Pilot (2)', 'Having escaped the "creature" and retrieved the plane transceiver, a group of the survivors travel to higher ground so they can transmit a signal. En route, they receive a mysterious transmission and encounter another of the island''s inhabitants. Meanwhile, back at camp, Jack tends to a wounded man who reveals a secret about Kate.', 41, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 3, 'Tabula Rasa', 'Jack and Hurley discover an alarming secret about Kate, as the marshal''s life hangs in the balance and he suffers a lot of pain. Meanwhile Kate, Charlie, Sawyer, Sayid, Boone and Shannon ponder the mysteries they have begun to uncover and worry that telling the other survivors will cause panic. They decide to lie for the time being. Also, Locke''s befriending of Walt disturbs Michael, but Walt is more concerned in finding his dog. Lastly, Kate flashes back to when she was arrested by the marshal in Australia.', 44, '2004-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 4, 'Walkabout', 'The survivors are jolted awake in the middle of the night when wild island beasts (which are wild boars) invade the beach encampment. Kate and Michael join the mysterious Locke on a hunt for food -- and a shocking secret about Locke is revealed. On the hunt for food someone is injured. Meanwhile, some survivors are horrified by Jack''s plan for the dead bodies still scattered among the wreckage -- he wants to burn them. Jack sees someone that''s not there, and we find out that one of the survivors was not able to walk but now he can.', 43, '2004-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 5, 'White Rabbit', 'Jack is nearly delirious from lack of sleep and struggles to overcome the haunting events that brought him to Australia and, subsequently, to the island. Meanwhile, Boone gets caught in a treacherous riptide trying to save a woman who went out swimming. A pregnant Claire''s health takes a bad turn from lack of fluids, and a thief may have stolen the last bottles of water. Veronica Hamel guest-stars as Jack''s mother, Margo.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 6, 'House of the Rising Sun', 'Walt and the others are shocked when Michael is brutally beaten, but only the non-English-speaking Jin and Sun know the truth behind the attack. Meanwhile Kate, Jack, Sawyer and Sayid argue about where the survivors should camp -- on the beach, where they''re more likely to be seen, or in a remote inland valley where fresh water abounds; and Locke discovers Charlie''s secret.', 43, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 7, 'The Moth', 'Charlie begins a painful journey of withdrawal from drugs, surprisingly aided by Locke, whose true motive for helping Charlie is a mystery. Meanwhile, survivors struggle to find and free Jack when he''s buried alive in a cave collapse, and someone might be secretly thwarting Sayid, Kate, and Boone when they enact a plan to find the source of the French transmission.', 44, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 8, 'Confidence Man', 'Shannon''s inhaler runs out and Boone believes Sawyer has the remaining three in his stash. When Sawyer refuses to give them up, Jack and Sayid resort to torturing Sawyer until he agrees to reveal the location of the inhalers. In flashback we hear Sawyer''s story and find he is not who he says he is.', 44, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 9, 'Solitary', 'Sayid''s life is placed in grave danger after he stumbles upon the source of the mysterious French transmission, the woman Danielle Rousseau (guest-star Mira Furlan). She was on the distress call and is found alive. Meanwhile, Hurley has a ridiculous plan to make life on the island a little more civilized.  The plan involves golf clubs he finds in the debris, and it looks like it just might work.  Lastly, we flash back to Sayid''s childhood friend Nadia as well as his participation in hostage situations in Iraq.', 44, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 10, 'Raised by Another', 'Claire has a horribly realistic nightmare about her new baby being harmed or kidnapped. Flashbacks reveal Claire''s backstory: the former boyfriend who got her pregnant, then abandoned her, and the psychic who convinced her to take the ill-fated flight that landed her on the island.  Hurley is shocked and confused when he discovers that Ethan Rom (guest-star William Mapother), another plane crash survivor, does not appear on the flight manifest.', 43, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 11, 'All the Best Cowboys Have Daddy Issues', 'Survivors wonder why Charlie and Claire have been abducted - and by whom - and a search party ventures into the treacherous jungle to look for the pair. Suspicions focus on Ethan Rom (guest-star William Mapother), who, it was recently discovered, was not a passenger on the doomed flight.  Jack battles inner demons relating to his father,  while Boone and Locke discover another island mystery.', 43, '2004-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 12, 'Whatever the Case May Be', 'Jack, Kate and Sawyer fight over possession of a newly discovered locked metal briefcase which might contain insights into Kate''s mysterious past. Meanwhile, Sayid asks a reluctant Shannon to translate notes he took from the French woman. A rising tide threatens to engulf the fuselage and the entire beach encampment, and Rose and a grieving Charlie tentatively bond over Claire''s baffling kidnapping.', 44, '2005-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 13, 'Hearts and Minds', 'When Locke learns that Boone wants to share their "secret" with Shannon, Locke decides to teach him a lesson.  This leads to Shannon''s life being placed in what seems like peril.  Boone and Shannon''s dark past is revealed in a shocking backstory that recalls their relationship right before the plane crash and presages the return of the beast. Kate, who has become a confidante to the soft-spoken Sun, is puzzled by Sun''s mysterious behavior and the revelation that she can speak English.  A hungry Hurley must convince Jin to share his fish by making up for offending Jin by rejecting his offer of raw fish early on, or he''ll continue to suffer digestive problems from the limited island diet.', 44, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 14, 'Special', 'Violence ensues and a mysterious island beast makes a re-appearance when Michael and Locke clash over Walt''s upbringing. Meanwhile, Charlie is tempted to read the missing Claire''s diary, and Sayid enlists Shannon to help decipher the French woman''s map.', 44, '2005-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 15, 'Homecoming', 'After the missing Claire returns with no recollection of what has happened since before she boarded the doomed Oceanic flight 815, Jack and Locke formulate a plan of defense against her kidnapper, the mysterious Ethan (guest-star William Mapother), who threatens to kill off the other survivors one by one unless Claire is returned to him. Meanwhile, the disappointment Charlie feels when Claire does not remember him triggers recollections of a woman he had let down in the past.', 42, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 16, 'Outlaws', 'Kate and Sawyer divulge dark secrets to each other while tracking a renegade boar that Sawyer swears is purposely harassing him.  Hurley and Sayid worry that Charlie is losing it after facing a brush with death and killing Ethan with 6 bullets to the chest.  A shocking prior connection between Sawyer and Jack is revealed in a flashback which shows Sawyer meeting Jack''s father in a bar. Robert Patrick ("Terminator 2: Judgment Day," "The X-File") guest stars.', 44, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 17, '...In Translation', 'When the raft the survivors have been building mysteriously burns down, Michael is convinced that Jin is responsible for the sabotage, which only serves to escalate their rivalry. Meanwhile, Sun stuns her fellow survivors with a surprising revelation, and Boone gives Sayid a warning about his step-sister Shannon. Lastly, more details of Jin and Sun''s troubled marriage are revealed through flashbacks.', 44, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 18, 'Numbers', 'When Hurley becomes obsessed with the French woman and heads into the jungle to find her, Jack, Sayid and Charlie have no choice but to follow. Hurley flashes back to the hugely life-altering experience he had before boarding the plane.', 44, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 19, 'Deus Ex Machina', 'Locke thinks he''s being sent a sign on how to get the hatch open, and he and Boone venture inland. Jack is reluctant to offer assistance when Sawyer begins to experience excruciating headaches and needs glasses.', 43, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 20, 'Do No Harm', 'Jack tends to a severely wounded Boone after Locke returns him to the caves.  In the confusion, Locke slips away to deal with his guilt over the crisis. Meanwhile, Claire unexpectedly goes into labor while deep in the forest.', 44, '2005-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 21, 'The Greater Good', 'After another funeral, tempers rise as the survivors'' suspicions of each other grow, and an unlikely survivor vows revenge. The events that landed Sayid on Flight 815 play out as he engages Locke in a psychological game of cat and mouse to uncover the truth about the mishap that claimed Boone''s life.', 44, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 22, 'Born to Run', 'Jack suspects foul play when Michael becomes violently ill while building the raft. The suspects include Sawyer and Kate, who compete for the last seat on the raft and do anything possible to prevent each other from getting it.  Meanwhile, a secret from Kate''s past is revealed to the other survivors on the island.', 44, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 23, 'Exodus (1)', 'The French woman-Danielle Rousseau-shocks the survivors by showing up to the camp with a dire warning about "the Others" who are on the island, and the black smoke that precedes them. Meanwhile, Michael and Jin ready the raft for sailing.  In flashbacks, we see the survivors final moments before they boarded their fateful flight.', 44, '2005-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 1), 24, 'Exodus (2)', 'The castaways on the raft are surprised at sea by something unexpected. Meanwhile, remaining islanders attempt to blow open the hatch, and a visitor to the encampment might be a threat to Claire''s infant son.', 87, '2005-05-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')), 2, 'Season 2', 'The motley crew of castaways remains stranded on the eerie deserted island populated by mysterious things that go bump in the night.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 1, 'Man of Science, Man of Faith', 'Jack, Locke and Kate explore the mysterious hatch but Jack decides to wait before going down into the hatch. Kate and Locke aren''t so patient. When Shannon chases after Vincent the dog, she encounters a familiar face in the jungle.', 44, '2005-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 2, 'Adrift', 'With the abduction of Walt fresh on their minds, their raft destroyed, and Jin missing, Michael and Sawyer fight for their lives in the middle of nowhere in the ocean and discover a new predator in the roiling sea. Meanwhile on land, Locke must descend into the hatch when Kate goes missing inside.  Also, Jack isn''t too far behind Locke as he decides to go into the hatch as well later on. Lastly, flashbacks reveal more of Michael''s troubled relationship with ex-lover Susan and their baby son Walt as they fight over custody for Walt and Michael must let go.', 43, '2005-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 3, 'Orientation', 'Michael, Sawyer, and Jin find themselves prisoners after they encounter what they believe to be a group of Others. At the Hatch, the group learns more about their new surroundings but are confused at Desmond''s reaction when the strange computer equipment is broken.', 44, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 4, 'Everybody Hates Hugo', 'Hurley struggles with an assigned task inside the hatch as he flashbacks to disturbing memories in his life before the crash. Meanwhile, Sawyer, Michael and Jin learn the identities of their captors on the island. Claire uncovers a startling piece of information about the fate of the raft.', 44, '2005-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 5, '...And Found', 'The tail-section survivors trek back to the southern beaches of the Island, but encounter trouble as Michael sets off by himself to find Walt. Meanwhile, at the main camp, Sun is heartbroken as she realizes that she has lost her wedding ring.', 43, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 6, 'Abandoned', 'Sawyer''s wound becomes life-threatening as he, Michael and Jin make their way through the interior of the island with the tail section survivors. Meanwhile, Shannon is once again haunted by visions of Walt.', 43, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 7, 'The Other 48 Days', 'The harrowing first 48 days in the lives of the tail section survivors are revealed. Flashbacks reveal the point of view of Ana-Lucia, Mr. Eko, Bernard and Libby and other survivors as they landed on the other side of the island on the beach. As the days progress danger hits their camp as well when "The Others" start taking people against their will.  As the survivors race inland, trying to stay a step ahead of The Others, they realize that someone among them wasn''t on Flight 815.', 47, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 8, 'Collision', 'Violence erupts when Ana Lucia and her group stumble upon Sayid and the other castaways on the island. Ana Lucia holds Sayid captive. Kate and Jack care for Sawyer when Mr. Eko brings him back to the camp himself. Flashbacks reveal Ana Lucia''s troubled life as a cop.', 43, '2005-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 9, 'What Kate Did', 'As Kate’s backstory continues, her original crime is revealed. She thinks something is haunting her through Sawyer.  Locke and Eko make an interesting discovery about the film, and Michael has a mysterious encounter with the computer.', 46, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 10, 'The 23rd Psalm', 'When Eko finds Charlie''s Virgin Mary statue, he demands that he take him to where he found it at once. Michael continues to communicate on the Swan computer without the other survivors knowing.', 44, '2006-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 11, 'The Hunting Party', 'Jack, Locke and Sawyer follow after a determined Michael after he heads into the jungle toward the dreaded "Others" in search of Walt. Meanwhile, Sun has a surprising reaction to Jin''s desire to join the search party, and Hurley and Charlie commiserate over the age-old conundrum of "what women want."', 44, '2006-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 12, 'Fire + Water', 'When Charlie''s vividly surreal dreams lead him to believe Claire''s baby, Aaron, is in danger, Locke suspects Charlie may be using again. Meanwhile, Sawyer encourages Hurley to act on his attraction to Libby.', 44, '2006-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 13, 'The Long Con', 'Some of the island survivors fear that "The Others" may have returned when Sun is greatly injured during a failed kidnapping attempt at her plant garden. Also, the trust barrier becomes very thin between Locke and Jack in terms of locking up the guns and being kept safe. Meanwhile, Sawyer is an amused but highly interested bystander when tension escalates between Jack, Locke, Kate and Ana Lucia. When Jack purposely takes Sawyer''s medication from him he pushes more in favor of helping Locke. Lastly, flashbacks reveal more of Sawyer''s con artist past.', 45, '2006-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 14, 'One of Them', 'After Sun is attacked, some of the survivors begin to think that one of the "other survivors" might be one of "The Others." When French woman Danielle Rousseau leads Sayid to a mysterious captive in the jungle, he becomes determined to find out if he is one of "The Others". Meanwhile, Sawyer discovers Hurley’s potentially devastating breach of the survivors’ trust and blackmails him into helping track an elusive island creature that won’t leave Sawyer alone.', 45, '2006-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 15, 'Maternity Leave', 'A mysterious illness that baby Aaron suddenly contracts sends a desperate Claire, Kate and French woman Danielle to return to the same area where Claire was initially kidnapped. It is there where she believes she can find a cure for Aaron''s illness. In the meantime, Jack and Locke are doing their best to keep their prisoner a secret from the rest of the survivors on the island.', 47, '2006-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 16, 'The Whole Truth', 'Sun comes to the realization that she might be pregnant. She struggles on whether to tell Jin about the situation. Meanwhile, with no success from Jack or Sayid, Ana-Lucia is called in by Locke to interrogate the new prisoner Henry Gale to get more information out of him about the balloon that he and his wife supposedly landed on the island with.', 44, '2006-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 17, 'Lockdown', 'When the hatch suddenly takes on a life of its own, Locke is forced to enlist the help of an unlikely ally to control the matter. Meanwhile, Ana Lucia, Sayid and Charlie go off into the jungle to find out the truth about Henry Gale and see if there really is balloon craft out there in the jungle that carried him and his wife to the island.', 44, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 18, 'Dave', 'Libby lends a helping hand to Hurley to support him when he begins to think the island is having a strange effect on him. Hurley begins to see Dave (guest-star Evan Handler, Sex and the City) on the island, who was his friend in the mental institution Hurley was in. Also, Locke''s sense of purpose is shaken when the prisoner gives him new information about the hatch.', 47, '2006-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 19, 'S.O.S.', 'Rose is surprisingly and vehemently opposed to Bernard''s plan to create an S.O.S. signal; romantic sparks are rekindled between Jack and Kate when they trek into the jungle to propose a "trade" with "The Others"; and Locke begins to question his faith in the island.', 44, '2006-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 20, 'Two for the Road', 'After finding an exhausted Michael in the forest, Jack and Kate bring him back to the main camp. When he finally wakes up, Michael has some new details about "The Others." Also, a lovestruck Hurley plans a date for Libby.', 44, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 21, '?', 'Mr. Eko has dreams about his brother leading him somewhere. He seeks Locke''s help in finding a secret location, the "question mark." Meanwhile, Jack and the other survivors grapple with the horrific situation in the hatch with the death of Ana-Lucia and Libby clinging to life.', 47, '2006-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 22, 'Three Minutes', 'A determined Michael convinces Jack and several castaways to help him rescue Walt from "The Others." With Jack away, Locke is left in charge of the hatch and must decide if he should believe Henry and not push the button, risking everyone''s safety.  Meanwhile, the events that happened to Michael after he left are finally revealed. Meanwhile, Charlie struggles with Eko''s decision to discontinue building the church.', 46, '2006-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 23, 'Live Together, Die Alone (1)', 'After discovering something odd just offshore, Jack and Sayid come up with a plan to confront "The Others" and hopefully get Walt back. At the same time there will be an answer to the question of where Michael has been and resolution of him and Walt. Meanwhile, Eko and Locke come to blows as Locke makes a potentially cataclysmic decision regarding the "button" and the hatch. Lastly, Desmond returns and he sheds some more light on his experience on the island in the three years prior to when Locke came down into that hatch.', 44, '2006-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 2), 24, 'Live Together, Die Alone (2)', 'After discovering something odd just offshore, Jack and Sayid come up with a plan to confront "The Others" and hopefully get Walt back. Meanwhile, Eko and Locke come to blows as Locke makes a potentially cataclysmic decision regarding the "button" and the hatch.', 44, '2006-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')), 3, 'Season 3', 'The castaways continue to seek strength as paranoia increases, prompting the revelation of more backstories -- and more secrets about the island.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 1, 'A Tale of Two Cities', 'Jack, Kate, and Sawyer are prisoners of the mysterious "Others." After their captors drug them and take blood samples, they are held in separate areas. The camp leaders--Ben (Henry Gale), Mr. Friendly and a new woman, Juliet--try to make the castaways adjust to their new circumstances.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 2, 'The Glass Ballerina', 'Sun and Jin''s lives are put in danger when Sayid tries to locate Jack and the other missing castaways. Sayid also creates a plan in order to get the attention of the "Others" on the beach. Meanwhile, Henry (i.e. Ben) gives Jack an offer that is very tempting in exchange for his cooperation. Lastly, Kate and Sawyer must adjust to harsh conditions that are being forced upon them by "The Others."', 43, '2006-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 3, 'Further Instructions', 'Locke, Eko and Desmond are found scattered about the island after the implosion of the hatch. Locke receives a message from the Island asking him to fix the situation he caused.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 4, 'Every Man for Himself', 'The Others prevent Sawyer and Kate from escaping, leaving Sawyer perplexed by the extent of the measures taken to keep them imprisoned. Jack is asked to use his medical training to save the life of one of the Others. At the beach, Desmond''s strange behavior attracts attention. He begins to construct a mysterious device.', 43, '2006-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 5, 'The Cost of Living', 'A delirious Eko wrestles with past demons; some of the castaways go to the Pearl station to find a computer they can use to locate Jack, Kate and Sawyer; Jack does not know who to trust when two of the Others are at odds with each other.', 43, '2006-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 6, 'I Do', 'Jack makes a decision regarding Ben''s offer. Sawyer''s life is placed in danger when Pickett decides to make good on his threat. Locke discovers a hidden message that may help unlock the island''s secrets. Kate recalls memories from the past, which caused her to make an important choice.', 43, '2006-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 7, 'Not in Portland', 'Jack has the Others in a desperate situation as he holds Ben''s life in his hands.  Meanwhile, Kate and Sawyer try to escape from their captors. Flashbacks reveal Juliet''s past as a medical researcher in Miami.', 43, '2007-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 8, 'Flashes Before Your Eyes', 'After Desmond rescues Claire from drowning, Charlie gets Hurley to help him find out why Desmond has seemed able to predict the future. Desmond recalls exactly what took place in the moments after he turns the key, where he experienced a strange vision of his life prior to his Army days.', 43, '2007-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 9, 'Stranger in a Strange Land', 'As Kate and Sawyer journey back to the main island with Karl, who is exhibiting effects of the brainwashing video, they argue over whether to go back and save Jack. On Hydra island, as Juliet''s fate rests in his hands and a power struggle within the Others ensues, Jack recollects the time he spent in Phuket, Thailand and his relationship with Achara, a mysterious tattoo artist.', 43, '2007-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 10, 'Tricia Tanaka Is Dead', 'Kate is still struggling over their decision to leave Jack in the hands of the Others as she and Sawyer return to their camp.  Meanwhile, Hurley finds an old van in the jungle and attempts to use it to help a fellow survivor in need of faith and hope.  Flashbacks reveal more of Hurley''s tumultuous past with the numbers curse.', 43, '2007-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 11, 'Enter 77', 'On their mission to rescue Jack, Kate, Sayid, and Locke stumble upon a mysterious structure surrounded by farm animals and meet its strange inhabitant. Back at the camp, in order to reclaim his belongings, Sawyer plays in a ping-pong competition.', 44, '2007-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 12, 'Par Avion', 'Claire has an idea to send a message to the outside world. Charlie, however, is resistant to the idea, and Desmond tries to sabotage the plan. As Claire tries to get the truth behind their actions out of the pair, she remembers traumatic events from her past. Meanwhile, the rescue party encounters a dangerous obstacle.', 44, '2007-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 13, 'The Man from Tallahassee', 'When Kate and Locke arrive at the Others'' camp, Ben promises to tell Locke the island''s secrets as long as he stops his destructive plan, and Kate''s reunion with Jack doesn''t go very well when she learns that the Others have offered him a deal. More of Locke''s troubled past is revealed.', 43, '2007-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 14, 'Exposé', 'As the truth about Sun''s kidnapping by "the Others" comes to her attention, Hurley becomes suspicious of Sawyer''s attempt to reveal the mystery behind two fellow survivors, Nikki and Paulo. Through series of flashbacks we will discover what Nikki and Paulo were doing before the crash and how they survived 65 days on the island.', 42, '2007-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 15, 'Left Behind', 'Kate and Juliet are stranded in the jungle after Kate learns that there is a traitor in the survivor''s midst. Meanwhile, Sawyer''s poor attitude and selfish ways towards the beach community may earn him a vote of banishment if he doesn''t have a change of heart.', 43, '2007-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 16, 'One of Us', 'The celebration of Jack''s return is cut short when he arrives at the beach with an Other, Juliet, whose flashbacks pick up from where they left off, showing us how she got onto the island and became an other. Meanwhile, Claire is threatened by a strange illness.', 43, '2007-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 17, 'Catch-22', 'Desmond convinces Hurley, Jin, and Charlie to follow him on a trek through the jungle after he receives a series of visions. Flashbacks reveal the time that Desmond spent with a cloister of monks. Meanwhile, a despondent Kate turns to Sawyer for companionship after seeing Jack and Juliet together.', 42, '2007-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 18, 'D.O.C.', 'Sun allows Juliet to examine her when she learns that all of "The Others" pregnant woman died before they gave birth on the island. Meanwhile, Desmond and an unlikely nemesis collaborate to save a new island inhabitant''s life.', 43, '2007-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 19, 'The Brig', 'After abandoning the Others, Locke takes Sawyer on a trek through the jungle to help him eliminate a common enemy. Meanwhile, back at the beach, the parachutist Naomi has crucial information about flight 815.', 43, '2007-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 20, 'The Man Behind the Curtain', 'Ben unwillingly divulges information to Locke about the island, taking him on a journey to various locations including strange monuments and the mysterious Jacob. Back at the beach, Juliet''s secret is revealed. Flashbacks will show us the origins of DHARMA and the history of the island, including ''the purge.''', 43, '2007-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 21, 'Greatest Hits', 'While Jack devises a plan to do away with "The Others" once and for all, Sayid uncovers a flaw in "The Others''" system that could lead to everyone''s rescue. But it requires Charlie to take on a dangerous task that may make Desmond''s premonition come true.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 22, 'Through the Looking Glass (1)', 'The season 3 finale finds the castaways preparing for an invasion by the slightly less mysterious Others, while Charlie and Desmond find more than they were looking for in the underwater "Looking Glass Hatch".', 43, '2007-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 3), 23, 'Through the Looking Glass (2)', 'The season 3 finale finds the castaways preparing for an invasion by the slightly less mysterious Others, while Charlie and Desmond find more than they were looking for in the underwater "Looking Glass Hatch".', 43, '2007-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')), 4, 'Season 4', 'Picking up from the shocking Season 3 finale, learn via "flash forwards" who from Oceanic Airlines flight 815 gets off the island.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 1, 'The Beginning of the End', 'They thought they had met the enemy. They thought they had seen evil. They thought wrong. As the new season begins, the survivors feel that rescue is close at hand, but they don''t know whether or not to believe Charlie''s final message that the people claiming to liberate them are not who they seem to be. As unlikely alliances are formed, those they thought could be trusted may turn against them, as the enemy of their enemy becomes their friend. But who can be trusted? Is rescue really as close as it seems?', 43, '2008-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 2, 'Confirmed Dead', 'The survivors begin to question the intentions of their supposed rescuers when four strangers arrive on the island.', 43, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 3, 'The Economist', 'Locke''s hostage may be the key to getting off the island, so Sayid and Kate go in search of their fellow castaway in an attempt to negotiate a peaceful deal.', 43, '2008-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 4, 'Eggtown', 'Kate needs to get information out of the hostages, but it may jeopardize her standing with Locke -- as well as with Sawyer. Meanwhile in the future Kate''s Court hearings take place.', 43, '2008-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 5, 'The Constant', 'Sayid and Desmond hit a bit of turbulence on the way to the freighter, which causes Desmond to experience some unexpected side effects.', 43, '2008-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 6, 'The Other Woman', 'Juliet receives an unwelcome visit from someone from her past and is given orders to track down Charlotte and Faraday in order to stop them from completing their mission -- by any means necessary. Meanwhile, Ben offers Locke an enticing deal.', 43, '2008-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 7, 'Ji Yeon', 'Juliet is forced to reveal some startling news to Jin when Sun threatens to move to Locke''s camp. Meanwhile, Sayid and Desmond begin to get an idea of the freighter''s crew when they meet the ship''s captain.', 43, '2008-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 8, 'Meet Kevin Johnson', 'Sayid confronts Ben''s spy on the freighter, and Ben urges daughter Alex to flee Locke''s camp in order to survive an impending attack.', 43, '2008-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 9, 'The Shape of Things to Come', 'Jack tries to discover the identity of a body that has washed ashore. Meanwhile, Locke''s camp is attacked by Ben''s adversaries.', 43, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 10, 'Something Nice Back Home', 'Kate and Juliet must learn to work together when Jack''s health is seriously compromised, and something goes wrong as Sawyer, Claire, Aaron and Miles continue their trek away from Locke''s camp and back to the beach', 43, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 11, 'Cabin Fever', 'Locke finds out where Jacob''s cabin is. Life on the freighter becomes dangerous.', 43, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 12, 'There''s No Place Like Home (1)', 'Sayid goes back to the island to bring the rest of the people to the freighter. Ben, Locke, and Hurley go to another Dharma station in order to "move the island".', 43, '2008-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 4), 13, 'There''s No Place Like Home (2)', 'The face-off between the survivors and the freighter people continues, and the Oceanic Six find themselves closer to rescue.', 85, '2008-05-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')), 5, 'Season 5', 'Season 5 finds six survivors of Oceanic Air Flight 815 returning to civilization and wrestling with the memories of those they left behind.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 1, 'Because You Left', 'The remaining island survivors start to feel the effects of the aftermath of moving the island, and Jack and Ben begin their quest to reunite the Oceanic 6 in order to return to the island with Locke''s body in an attempt to save their former fellow castaways.', 43, '2009-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 2, 'The Lie', 'Hurley and Sayid are on the run from the cops after stumbling into trouble at the safehouse; the island survivors come under attack by unknown forces; and an old friend offers some shocking advice to Kate in order to ensure that "the lie" remain a secret.', 42, '2009-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 3, 'Jughead', 'Desmond looks for a woman who might be the key to helping Faraday stop the island''s unpredictable movements through time; Locke finds out who has been attacking the survivors.', 43, '2009-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 4, 'The Little Prince', 'Kate discovers that someone knows the secret of Aaron''s true parental lineage. Meanwhile, the dramatic shifts through time are placing the lives of the remaining island survivors in extreme peril.', 43, '2009-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 5, 'This Place Is Death', 'Locke shoulders the burden of ending the island''s increasingly violent movements through time; Ben is stymied in his efforts to reunite the Oceanic 6 and bring them back to the island.', 43, '2009-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 6, '316', 'The members of Oceanic 6 discover how to get back to the island, but not all of them want to return.', 43, '2009-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 7, 'The Life and Death of Jeremy Bentham', 'Locke''s mission off the island as Jeremy is revealed.', 46, '2009-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 8, 'LaFleur', 'Sawyer perpetuates a lie with some of the other island survivors in order to protect themselves from mistakes of the past.', 43, '2009-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 9, 'Namaste', 'After meeting old acquaintances Sawyer is forced to continue lying to protect them.', 43, '2009-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 10, 'He''s Our You', 'Everyone on the island is at risk when one of the survivors decides to go against them and taking matters into their own hands.', 43, '2009-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 11, 'Whatever Happened, Happened', 'Kate goes to extreme measures to save Ben''s life when Jack refuses to help. Meanwhile, Kate begins to tell the truth about the lie in order to protect Aaron.', 43, '2009-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 12, 'Dead Is Dead', 'To atone for sins of the past, Ben must attempt to summon the smoke monster in order to be judged.', 43, '2009-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 13, 'Some Like It Hoth', 'Suspicions about a possible breach intensify after Ben is taken from the infirmary, and a reluctant Miles is forced to work with Hurley when he''s asked to deliver an important package to a top Dharma official.', 43, '2009-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 14, 'The Variable', 'On the 100th episode milestone for the series, the time of reckoning has begun when Daniel Faraday comes clean regarding what he knows about the island.', 43, '2009-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 15, 'Follow the Leader', 'Jack and Kate find themselves at odds over the direction to take to save their fellow island survivors, Locke further solidifies his stance as leader of "The Others," and Sawyer and Juliet come under scrutiny from the Dharma Initiative.', 43, '2009-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 16, 'The Incident (1)', 'Jack''s decision to put a plan in action in order to set things right on the island is met with some strong resistance by those close to him, and Locke assigns Ben a difficult task.', 46, '2009-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 5), 17, 'The Incident (2)', 'Jack''s decision to put a plan in action in order to set things right on the island is met with some strong resistance by those close to him, and Locke assigns Ben a difficult task.', 42, '2009-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')), 6, 'Season 6', 'After Season 5’s explosive finish, everything is up in the air for the survivors of flight 815. No one knows what — or who — the future will hold. Will Juliet’s sacrifice to save her friends work? Can Kate choose, once and for all, between Jack and Sawyer? Will Sun and Jin be reunited? Is it too late to save Claire? Whatever awaits everyone on the island, one thing is for certain — the moment of truth has arrived.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 1, 'LA X (1)', 'Two outcomes of the detonation of the hydrogen bomb are presented. Flight 815 lands safely at LAX, where Kate escapes from the marshal and Jack learns that his father''s body was lost in transit.', 44, '2010-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 2, 'LA X (2)', 'Jack, Sawyer, Kate, Miles and Hurley, struggling to save Sayid, face an ancient secret. Meanwhile, a fake Locke exits the chamber to everyone''s awe.', 43, '2010-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 3, 'What Kate Does', 'When Sawyer escapes from the temple, Kate and Jin are sent to bring him back. Meanwhile, the Others determine Sayid is infected and attempt to poison him. In the flash sideways, Kate, still on the run, takes Claire to a hospital when she goes into labor.', 43, '2010-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 4, 'The Substitute', 'On the island, the Man in Black attempts to recruit Sawyer in his attempt to leave the island, while an impromptu funeral is held for the real Locke. In the flash sideways, Locke is fired from his job and becomes a substitute teacher.', 44, '2010-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 5, 'Lighthouse', 'On Jacob''s orders, Hurley leads Jack to a lighthouse. Meanwhile, Claire questions an Other she has captured while tending to an injured Jin. In the flash sideways, Jack is a single father trying to bond with his son.', 45, '2010-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 6, 'Sundown', 'After recruiting Sayid to his cause, the Man in Black issues an ultimatum to the Others: either join him or die. Meanwhile, Kate is reunited with Claire. In the flash sideways, Sayid helps his brother, who is in debt to a loan shark.', 43, '2010-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 7, 'Dr. Linus', 'Ilana discovers Ben killed Jacob, so she plans to kill him. Meanwhile, Jack, Hurley and a suicidal Richard visit the Black Rock. In the flash sideways, Ben, a high school teacher, tries to blackmail the school''s principal.', 44, '2010-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 8, 'Recon', 'The Man in Black sends Sawyer on a reconnaissance mission to Hydra Island, where he discovers that Charles Widmore has returned to the island with a team of scientists. In the flash sideways, Sawyer is a lonely cop who is still searching for the original Sawyer.', 44, '2010-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 9, 'Ab Aeterno', 'Richard Alpert''s back story is shown: In 1867, he is brought to the island on the Black Rock as a slave. He makes a deal with Jacob to be his representative in exchange for immortality. In the present day, Hurley convinces him to help the candidates replace Jacob and stop the Man in Black from leaving the Island.', 48, '2010-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 10, 'The Package', 'After Jin is kidnapped and taken to Hydra Island by Widmore''s team, the Man in Black confronts Widmore. On the main island, Sun loses her ability to speak English. In the flash sideways, Sun and Jin are abducted after failing to complete a transaction for Sun''s father.', 44, '2010-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 11, 'Happily Ever After', 'On the island, Widmore subjects Desmond to a large amount of electromagnetic energy as an experiment. In the flash sideways, Desmond, with the aid of Charlie, starts to have visions of his life in the original timeline.', 43, '2010-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 12, 'Everybody Loves Hugo', 'In order to prevent more loss of life, Hurley leads the other survivors to speak with the Man in Black. In the flash sideways, Hurley meets Libby, while Desmond continues his mission to let the Oceanic 815 passengers know of their lives on the island.', 43, '2010-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 13, 'The Last Recruit', 'The survivors split into two groups; one led by Sawyer, the other by the Man in Black. Sawyer''s group travels to Hydra Island, where they are captured by Widmore''s crew after Sun and Jin are reunited. In the flash sideways, the passengers of Oceanic 815 continue to cross paths with each other.', 44, '2010-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 14, 'The Candidate', 'After the remaining survivors are reunited, Sawyer and Jack hatch a plan to divert the Man in Black''s attention and leave the island without him on Widmore''s submarine, but disastrous consequences await them. In the flash sideways, Jack investigates the cause of Locke''s paralysis and offers treatment.', 44, '2010-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 15, 'Across the Sea', 'Jacob and the Man in Black are revealed to be twin brothers. They are raised by a mysterious woman who is charged with protecting the island. As revenge for the murder of their adoptive mother (who killed their real mother), Jacob throws his brother into the source of electromagnetism after being made the island''s guardian, which transforms the Man in Black into the smoke monster.', 44, '2010-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 16, 'What They Died For', 'Ben finally takes his revenge on Widmore after accepting the Man in Black''s request for assistance. Jacob explains the purpose of the candidates, and Jack volunteers to take his place. The search for Desmond reveals that he has been rescued and the Man in Black plans to use him to destroy the island. In the flash sideways, each person ends up on their way to a concert.', 44, '2010-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0411008')) AND numero_temporada = 6), 17, 'The End', 'For different reasons, Jack and the Man in Black both use Desmond to extinguish the light at the heart of the island. The island starts disintegrating, but The Man in Black is also made mortal. Still desperate to escape, The Man in Black fights Jack and mortally wounds him, but with help from Kate, Jack kills him. Realizing his destiny, Jack sacrifices himself to relight the heart of the island, so his friends can escape on the Ajira plane. Hurley takes Jack''s place as protector of the island and makes Ben the new advisor. The flash sideways is revealed to be a type of limbo, or holding pattern, for the main characters, where they reside until accepting their life and death, and are then able to let go and move on together.', 105, '2010-05-23');
