INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0412253', 'Veronica Mars', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0470971'), 'SERIE', 'After her best friend is murdered and her father is removed as county sheriff, Veronica Mars dedicates her life to cracking the toughest mysteries in the affluent town of Neptune.', '2004-01-01', 'https://m.media-amazon.com/images/M/MV5BYjYyODQ3OTktM2IyMC00ZDk4LWIzMjYtZjczN2FkZGRhMDYwXkEyXkFqcGc@._V1_.jpg');
