INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')), 1, 'Season 1', 'The season revolves around Veronica Mars, a high school student and private investigator in the fictional Southern California seaside town of Neptune. When Veronica''s best friend, Lilly Kane, is murdered, her life falls apart. Her father, County Sheriff Keith Mars, accuses Lilly''s father of being involved in the murder. This provokes Neptune''s wrath and Keith''s ousting as sheriff in a recall election. Veronica''s mother, Lianne, develops a drinking problem and leaves town. Veronica''s "09er" friends—wealthy students from the fictional 90909 ZIP code—force her to choose between them and her father; she chooses her father. Keith opens a private investigation agency, Mars Investigations, where Veronica works part-time.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 1, 'Pilot', 'While trying to navigate the everyday drama of high school, the smart, fearless, 17-year-old Veronica Mars also moonlights as an apprentice private investigator out to solve her wealthy town of Neptune''s toughest mysteries. After coming to the aid of the new kid, sophomore Wallace Fennel, who''s been duct-taped to the school''s flagpole, Veronica ends up incurring the wrath of the thugs who put him there, Eli "Weevil" Navarro and his P.C.H. Biker Boyz. To get Weevil and his gang off her and Wallace''s case, Veronica devises an intricate plan that helps some of Weevil''s cronies avoid trouble with the law.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 2, 'Credit Where Credit''s Due', 'Veronica doesn''t believe the evidence adds up against Weevil, who has confessed to stealing credit card applications from Logan''s family, and launches an investigation to help her new ally.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 3, 'Meet John Smith', 'With only a commonplace name, an old address and dim memories as leads, Veronica and Wallace attempt to help classmate Justin Smith find his father John, who disappeared 10 years earlier.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 4, 'The Wrath of Con', 'In an effort to help Wallace''s new crush Georgia, who was duped out of her money in an internet scheme, Veronica must outwit a group of computer "thugs," known as the Silicon Mafia.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 5, 'You Think You Know Somebody', 'Veronica tries to help her new boyfriend Troy find his father''s stolen car and turns to Weevil for assistance, but the situation becomes dangerous when she discovers that Logan and Troy''s buddy Luke might have left more than a piata in the car after their night out in Tijuana.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 6, 'Return of the Kane', 'Veronica investigates possible fraud in the election of student council president at school after Duncan wins, beating a more popular, but less affluent student who promised to eliminate the wealthy students'' on-campus perks.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 7, 'The Girl Next Door', 'Veronica becomes suspicious when a young pregnant woman who lives in their apartment complex with her volatile boyfriend suddenly disappears; fearing the worst, Keith steps in to help his daughter investigate this case for the girl''s estranged parents.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 8, 'Like a Virgin', 'To help restore a cheerleader''s ruined reputation, Veronica turns to funky computer geek Mac to find the hacker responsible for leaking the embarrassing, private results of a popular online "purity test" to all of Neptune High. Meanwhile, Keith helps Wallace and his mom with an unruly tenant in their building. Later, to get answers about Lilly''s murder, Veronica attempts to visit Lilly''s confessed, condemned killer Abel Koontz in prison.', 42, '2004-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 9, 'Drinking the Kool-Aid', 'The wealthy parents of a Neptune High senior hire Keith and Veronica to investigate a cult-like group and its charismatic leader after their son Casey moves out to live on the collective farm. Meanwhile, Veronica attempts to get to the bottom of Abel Koontz'' claim that her real father is Jake Kane.', 40, '2004-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 10, 'An Echolls Family Christmas', 'When Weevil''s poker winnings go missing after a game at Logan''s place, Veronica questions each player to piece together the evening''s events and catch the thief. Meanwhile, on the eve of the Echolls'' annual Christmas party extravaganza, Keith is hired by Lynn Echolls to track down one of her husband Aaron''s potential stalkers.', 39, '2004-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 11, 'Silence of the Lamb', 'Veronica uncovers information that her fellow outcast Mac was switched at birth with a more affluent student, causing Veronica to examine her own questions about whom her real father may be. Meanwhile, a serial killer has resurfaced in Neptune forcing Sheriff Lamb to forge a reluctant, tense partnership with Keith. Later, Veronica flirts with a handsome young rookie at the sheriff''s department to obtain more information on Lilly''s murder.', 40, '2005-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 12, 'Clash of the Tritons', 'When a family accuses Veronica of providing a fake ID to their son, now in an alcohol-induced coma, and files suit, the search to find who''s really responsible leads Veronica to a clandestine, exclusive organization operating on Neptune High''s campus with a possible connection to Duncan.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 13, 'Lord of the Bling', 'After being hired by hip-hop heavyweight Percy "Bone" Hamilton to find his kidnapped daughter, Veronica and Keith look to the music mogul''s long list of enemies, family members and the girl''s Neptune High social circle for clues on her whereabouts. Meanwhile, following Lynn Echolls'' apparent suicide, Logan cynically endures his father Aaron''s effusive displays of grief as they prepare for her memorial ceremony.', 40, '2005-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 14, 'Mars vs. Mars', 'When one of Neptune High''s haughtier students brings a sexual harassment suit against a favorite teacher, Veronica finds herself pitted against her father when the girl''s parents hire Keith to help in their case. Meanwhile, with the tabloids claiming his mom is still alive, Logan turns to Veronica to help him track down the truth. Later, Veronica discovers more unsettling information about Duncan''s hidden medical condition.', 40, '2005-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 15, 'Ruskie Business', 'Veronica surprisingly finds herself working as a "love detective" when she''s asked to track down her friend Meg''s secret admirer and a Russian bride''s estranged fiancé.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 16, 'Betty and Veronica', 'Following an emotional reunion with her mother, Veronica is hired to track down Neptune High''s beloved mascot, Polly the Parrot, which was apparently kidnapped by a rival school on the eve of a big basketball game.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 17, 'Kanes and Abel''s', 'Veronica investigates who at school is doing everything possible to distract Sabrina from studying and wreck her grades in an obvious attempt to sabotage her chances at becoming valedictorian.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 18, 'Weapons of Class Destruction', 'A series of fire drills leads Veronica to discover that Neptune High has been receiving bomb threats, so she enlists Wallace and Mac''s help to investigate classmates who could pose a serious threat to the school, including new student Ben.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 19, 'Hot Dogs', 'While helping her classmate Mandy search for her missing Jack Russell terrier, Veronica stumbles onto a bigger mystery, which affects pets all over Neptune.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 20, 'M.A.D.', 'When a classmate''s boyfriend threatens to post a humiliating video of the girl online if she dumps him, Veronica helps her concoct a scheme to ensure "mutually assured destruction" if he doesn''t allow the relationship to end peacefully.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 21, 'A Trip to the Dentist', 'Determined to get to the truth behind who drugged and assaulted her at a party the year before, Veronica questions her friends and many rivals about the chain of events that night at Shelley Pomroy''s house. Meanwhile, when one of Veronica and Wallace''s stunts affects her job at Kane Software, Alicia confronts Keith about his daughter''s behavior. Later, in an attempt to get closer to his son, Aaron throws a birthday party for Logan that inadvertently surprises everyone.', 40, '2005-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 1), 22, 'Leave It to Beaver', 'In the shocking, action-packed season finale, a determined Veronica must betray someone she cares deeply about in order to solve the season-long mystery of who murdered her best friend Lilly Kane, but what she discovers puts her life in serious danger. Meanwhile, on the eve of a reception for the Governor of Calif., Jake Kane asks Duncan if he really wants to know what happened on the night Lilly died. Later, Keith awaits the results of a paternity test.', 41, '2005-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')), 2, 'Season 2', 'The season begins with the introduction of two new cases: when a school bus full of Neptune High students plunges off a cliff, killing almost everyone on board, Veronica Mars makes it her mission to discover why the bus crashed. Logan Echolls is accused of killing a Pacific Coast Highway biker gang member after drunkenly picking a fight with Eli "Weevil" Navarro and the PCHers.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 1, 'Normal Is the Watchword', 'After the summer fireworks caused by a dangerous confrontation with Lilly Kane''s murderer and a surprising visitor at her door, Veronica attempts to settle into "normal" life, complete with a new after-school job and a return to the popular fold at Neptune High, but she gets pulled back into the investigation business when Wallace is kicked off the basketball team for testing positive for drugs.Meanwhile, Keith sits down with reporter Julie Chen to discuss his new book on the Lilly Kane murder, "Big Murder, Small Town." Later, after seeing his father arrested for murder and being charged and tried for murder himself, Logan seeks refuge from the paparazzi and relaxes poolside at the Casablancas mansion with buddies Dick and "Beaver"  and their sexy stepmother Kendall.', 40, '2005-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 2, 'Driver Ed', 'After tragedy strikes Neptune, Calif. and the local sheriff rushes to judgment, an emotional Veronica attempts to help a grieving family member rule out suicide as a contributing cause in the calamity. Meanwhile, Wallace offers to help transfer student Jackie Cook, the fiery, flirty daughter of professional baseball player Terrence Cook, track down the person who damaged her car in the school lot. Later, mayoral candidate Woody Goodman asks Keith to consider running for sheriff.', 40, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 3, 'Cheatty Cheatty Bang Bang', 'Beaver hires Veronica to investigate his stepmother, Kendall, who he believes is cheating on his dad and planning to clean him out, but both are shocked by what they discover. Meanwhile, Wallace begins dating Jackie, against Veronica''s advice.', 40, '2005-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 4, 'Green-Eyed Monster', 'While dealing with her own feelings of jealousy regarding Duncan, Veronica helps a young woman who believes that her new fiancée is secretly after her fortune by sifting through his background and even posing as a sexy, available coed to entrap the guy.', 40, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 5, 'Blast from the Past', 'Deciding to give Jackie the benefit of the doubt since she''s dating Wallace, Veronica tries to help Jackie determine who stole her credit card, leading Veronica to appear on a psychic''s community access show to pursue a lead. Meanwhile, Wallace confronts his mother Alicia about who his real father is. Later, Veronica learns of a voice mail recording from one of the students that died, made at the moment the bus crash.', 40, '2005-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 6, 'Rat Saw God', 'With Aaron Echolls facing trial for Lilly''s murder, the previously accused Abel Koontz appears to enlist Veronica''s help in finding his missing daughter Amelia, leading to a confrontation with Kane Software''s head of security. Meanwhile, Logan is arrested', 40, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 7, 'Nobody Puts Baby in a Corner', 'Veronica and Duncan discover that the still-comatose Meg had been babysitting an abused child, leading Veronica to take on an unfamiliar role as a babysitter to determine the kid''s identity. Meanwhile, Kendall continues her affair with Logan as her stepso', 40, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 8, 'Ahoy, Mateys!', 'Veronica helps Keith determine who is haunting a school bus crash victim''s parents, currently embroiled in a suit against the school district for negligence.Meanwhile, after Logan asks for help fighting the murder charge against him, Veronica stumbles', 40, '2005-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 9, 'My Mother, the Fiend', 'After finding her mother''s old permanent record at school, Veronica wonders how well she knew her mother at all, and decides to investigate her mother''s school friends. Meanwhile, Trina takes the role of director in the school play, and while she has a confrontation with Kendall, Veronica has one with Celeste.', 40, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 10, 'One Angry Veronica', 'Called to jury duty over Christmas break, Veronica must sit on a difficult, polarizing case against a pair of affluent 09''er defendants accused of assaulting a young Hispanic woman. Meanwhile, when the Aaron Echolls/Lilly Kane sex tapes go missing from th', 40, '2005-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 11, 'Donut Run', 'When Duncan disappears with Meg''s baby, Lamb must work with two FBI agents to extract as much information as possible from an uncooperative Veronica. Meanwhile, Wallace reveals the real reason he returned to Neptune, and Weevil and Logan make a breakthrough in their hunt for the rogue gang member.', 40, '2006-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 12, 'Rashard and Wallace Go to White Castle', 'Wallace''s hopes of escaping his trouble in Chicago are dashed when Rashard''s uncle accuses him in the press of a hit and run. Meanwhile, Weevil has Veronica bug a church confessional to smoke out the traitor in his bike gang.', 39, '2006-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 13, 'Ain''t No Magic Mountain High Enough', 'When the profits from the Neptune High Winter Carnival go missing, Veronica finds herself defending Jackie from the condemning teachers and students. Meanwhile, Keith meets with her father, Terrence Cook, after he is accused of playing a role in the bus crash, and Logan initiates a new relationship while Beaver continues an old one.', 40, '2006-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 14, 'Versatile Toppings', 'When a private website for Neptune High''s gay students is hacked, and the members blackmailed, Veronica finds it difficult to track down the culprit when the victims want to remain anonymous. Meanwhile, Hannah finds out Logan''s true intentions, and Keith believes he has found an alibi for Terrence.', 40, '2006-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 15, 'The Quick and the Wed', 'Wallace''s new girlfriend Jane enlists Veronica''s help when her older sister Heidi appears to be a "runaway bride," but the clues suggest something possibly more disturbing happened on the way to the altar. Meanwhile, Keith and Veronica decide that they have no choice but to go to Sheriff Lamb with the evidence they''ve uncovered about the bus crash. Later, Kendall has a tempting offer for Aaron Echolls.', 38, '2006-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 16, 'The Rapes of Graff', 'While accompanying Wallace to Hearst College, she runs into her ex, Troy Vandergraff, who enlists her help when he is accused of date rape. Meanwhile, Keith helps Cliff with a personal problem involving a prostitute, and Logan makes a decision regarding his relationship with Hannah.', 40, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 17, 'Plan B', 'Overcome with guilt and frustration, Weevil asks Veronica for help to bring Felix''s true killer to justice, but realizes he may have to take matters into his own hands.Meanwhile, Keith reviews a strange DVD that Woody receives in the mail, and relationship troubles brew between Wallace and Jane, and Mac and Cassidy.', 40, '2006-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 18, 'I Am God', 'Veronica begins having dreams involving the dead students from the bus crash, who drop clues along the way. Meanwhile, Logan and Wallace become unlikely lab partners in Mr. Wu''s class, and Keith helps Clemmons expose a doctor''s scam.', 40, '2006-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 19, 'Nevermind the Buttocks', 'What promises to be a simple case of finding out who ran over a classmate''s dog turns into a startling revelation when new secrets about the bus crash come pouring out and Veronica finds herself again revisiting Lilly''s murder case. Meanwhile, Wallace and Jackie try to turn their relationship around the corner, and the PCHers turn to Weevil for protection from the Fitzpatricks.', 40, '2006-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 20, 'Look Who''s Stalking', 'Gia enlists Veronica''s help to find out who is stalking her, and Clemmons cancels the senior prom.', 40, '2006-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 21, 'Happy Go Lucky', 'Veronica takes the stand in Aaron Echolls''s murder trial, and is distracted during final exams while waiting for the verdict. Meanwhile, Keith takes new evidence about the mayor to Lamb, and Weevil asks Mac and Cassidy for help to pass algebra.', 40, '2006-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 2), 22, 'Not Pictured', 'After discovering the true perpetrator of the bus crash, Veronica is desperate to warn others before it''s too late. However, she inadvertently puts herself and her loved ones at risk in the process.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')), 3, 'Season 3', 'The season continues the story of Veronica Mars, now a freshman studying at Hearst College while moonlighting as a private investigator under the wing of her detective father.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 1, 'Welcome Wagon', 'Veronica begins college with Logan, Wallace and Mac, but is immediately drawn back into old detective habits when Piz, Wallace''s new roommate, gets all his stuff stolen. Meanwhile, Keith helps reunite Kendall with an old love, recently released from prison.', 40, '2006-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 2, 'My Big Fat Greek Rush Week', 'The campus newspaper hires Veronica for an undercover expose on the Zeta Theta sorority sisters during rush week to investigate Parker’s rape. Veronica begins to realize though that not everything is as it appears in the sorority house. Logan and Wallace take part in a challenging Sociology class role-playing experiment as prisoner and prison guard, and Keith treks through the desert after escaping from the scene of a crime.', 40, '2006-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 3, 'Wichita Linebacker', 'Veronica''s detective prowess is again used on campus when Piz''s football friend loses the team playbook and Veronica must get it back before the game. The Dean threatens to expel Veronica if she doesn''t reveal the source of her newspaper article. Meanwhile, Keith hires Weevil to work in the office, and Logan''s antics catch up with him.', 40, '2006-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 4, 'Charlie Don’t Surf', 'Logan gets a big surprise when he hires Veronica to find the source of his missing inheritance, which escalates from weird to worse. Meanwhile, Dick''s fraternity asks Veronica to prove their innocence in the campus rapes, and Keith helps an old acquaintance prove her husband is cheating.', 40, '2006-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 5, 'President Evil', 'When the illegal casino Veronica frequents is robbed, she must track down the thief to recover the necklace Lilly gave her years before. Meanwhile, Dean O''Dell''s stepson is dying of cancer and needs Keith to track down his biological father for a transplant (with Cliff''s help), and Wallace fears he may flunk out of his most important class.', 40, '2006-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 6, 'Hi, Infidelity', 'When Veronica''s term paper appears on the internet, she is accused of cheating by the TA and must prove her innocence. Meanwhile, Wallace has problems of his own when long basketball practices distract him from his studies, and Keith begins seeing Harmony Chase.', 40, '2006-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 7, 'Of Vice and Men', 'Veronica helps a girl named Meryl who is certain that her boyfriend is in trouble, while a jaded Veronica tries to convince her that he is cheating. Meanwhile, Logan reluctantly tells Veronica why he is sure Mercer didn''t commit the rapes, and Keith finds that there is a heavy price to pay for committing adultery.', 40, '2006-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 8, 'Lord of the Pi’s', 'Keith and Veronica are hired to help find the missing grand-daughter of the founder of Hearst College, whose swing vote could spell the end of fraternities and sororities at Hearst. Meanwhile, Logan fears for Veronica''s safety as she gets closer to the truth regarding the campus rapes.', 38, '2006-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 9, 'Spit & Eggs', 'After the campus rapist anonymously announces the location of his next rape, Veronica hires her friends to help her track him down, but is shocked when she discovers the rapist''s identity. Meanwhile, Logan makes a drastic decision about his future with Veronica, and Dean O''Dell hires Keith to prove that his wife is unfaithful.', 40, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 10, 'Show Me the Monkey', 'Veronica and Mac help campus researchers locate a missing monkey who was allegedly stolen by animal rights activists. Meanwhile, Keith is approached by Mindy O''Dell, who claims her husband''s death was murder, not suicide. And in the aftermath of his breakup with Veronica, Logan turns to Dick for advice.', 40, '2007-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 11, 'Poughkeepsie, Tramps and Thieves', 'Veronica is hired to track down a one-night-stand, but the situation becomes more complicated when she turns out to be a hooker. Meanwhile, Keith continues his investigation in Dean O''Dell''s death, and a visit by Madison Sinclair causes trouble for Veronica and Logan.', 40, '2007-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 12, 'There''s Got to be a Morning After Pill', 'Veronica is hired to find out who slipped a classmate a drug causing her to have a miscarriage against her will, but is distracted by Logan who admits to sleeping with Madison Sinclair. Meanwhile, Keith helps Mindy O''Dell when her ex-husband breaks into their house.', 40, '2007-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 13, 'Postgame Mortem', 'Keith takes on a second concurrent murder case when the head of the Hearst basketball team turns up dead and his son is the prime suspect. Meanwhile, a depressed Logan refuses to leave his hotel room and ends up babysitting Dick''s girlfriend''s little sister for days.', 40, '2007-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 14, 'Mars, Bars', 'When Veronica is released from jail, she is contacted by Josh Barry who is desperate to prove his innocence in his father''s murder. Meanwhile, Keith gets bittersweet news from the county commissioner, and Logan helps Mac and Parker on a scavenger hunt.', 40, '2007-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 15, 'Papa''s Cabin', 'When Veronica discovers Timothy Foyle breaking into Mars Investigations, she uses his help to track down Dean O''Dell''s true killer. Meanwhile, Logan and Parker''s relationship takes an unexpected turn, and acting Sheriff Mars brings another murderer to justice.', 40, '2007-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 16, 'Un-American Graffiti', 'With Keith acting-sheriff, Veronica goes solo on a case involving a local restaurant whose owners are the targets of hate crimes. Meanwhile, Keith is disturbed by the lack of professionalism in his deputies when he orders them to fine bars serving alcohol to underage patrons. Logan throws a birthday party for Parker, and Piz decides to finally confront Veronica about his feelings.', 40, '2007-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 17, 'Debasement Tapes', 'Desmond Fellows, a singer/musician from a 1990''s pop band arrives on the Hearst campus to perform at a benefit concert to keep the station from going out of business. Piz gets the job of his dreams when he is put in charge of hosting Fellows around campus and on air. However his dreams start to dissolve as things don''t go quite how he imagined, in more ways then one. Keith is excited about the upcoming Sheriff''s race unopposed until he unwittingly helps promote an unlikely candidate who throws his hat into the ring.', 40, '2007-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 18, 'I Know What You''ll Do Next Summer', 'Apollo, a Hearst student who suffered hardships as a child soldier in Africa, appears on Piz''s radio show, prompting a man to come forth claiming to be his father. But Veronica''s investigation unearths some surprises. Meanwhile, Neptune is faced with a crime spree that could spell trouble for Keith''s campaign, and Logan finds himself in a difficult situation when Parker wants to spend to summer with him. Veronica awaits the results of her FBI exam.', 41, '2007-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 19, 'Weevils Wobble But They Don''t Go Down', 'Weevil asks Veronica to clear his name after he''s arrested for selling fake debit cards to Hearst students, claiming he''s being framed because of his criminal background.', 41, '2007-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 3), 20, 'The Bitch Is Back', 'As the end of the first semester at Hearst College draws to an end, the election for sheriff in Neptune comes to a close and Veronica and Piz discuss the effect a summer apart will have on their relationship.', 41, '2007-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')), 4, 'Season 4', 'Mystery. Parties. Scandal. Corruption. Season 4 is going be the most explosive one yet. Spring breakers are getting murdered in Neptune. After Mars Investigations is hired by the family of one of the victims to find their son’s killer, Veronica is drawn into an epic mystery that pits the enclave’s wealthy elites, who would rather put an end to the month-long bacchanalia, against a working class that relies on the cash influx that comes with being the West Coast’s answer to Daytona Beach.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 1, 'Spring Break Forever', 'Panic spreads through Neptune when a bomb goes off during spring break. Veronica and Keith are hired by the wealthy family of one victim injured in the bombing to find out who is responsible.', 49, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 2, 'Chino and the Man', 'Veronica and Keith launch their investigation. Their involvement puts Police Chief Langdon on edge. Penn goes public with his theory on who the bomber is. Meanwhile, local teen Matty Ross begins her own search for her father’s killer.', 50, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 3, 'Keep Calm and Party On', 'Veronica and Keith’s client, Daniel Maloof, makes a shocking confession. Sheriff Langdon closes in on her top suspect. Veronica and Matty join forces, just as the whole investigation is flipped on its head.', 51, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 4, 'Heads You Lose', 'Convinced the bomber is still at large, Veronica visits Chino to learn more about Clyde and Big Dick. Mayor Dobbins’ request for help from the FBI brings an old flame to Neptune. Veronica confronts her mugger.', 53, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 5, 'Losing Streak', 'Veronica discovers Keith has been hiding something scary from her. The real reason for Penn’s latest theory on the bomber comes to light. Veronica loses confidence in new friend, Nicole, owner of Comrade Quacks.', 54, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 6, 'Entering a World of Pain', 'As Veronica learns more about Nicole''s past, her suspicion deepens. A frantic phone call from Paris leads to a search for Matty. Veronica unwittingly does legwork for Leo.', 51, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 7, 'Gods of War', 'Veronica debates coming clean to Nicole. Veronica’s fidelity is tested. Veronica and Keith discover they aren’t the only ones who believe they’ve found the bomber. A surprising potential client tries to hire Mars Investigations.', 52, '2019-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412253')) AND numero_temporada = 4), 8, 'Years, Continents, Bloodshed', 'Veronica and Keith follow a new lead, and discover another victim. Matty follows her own instincts, landing herself dangerously close to a killer. Veronica has a tragic epiphany as the clock is ticking.', 54, '2019-07-19');
