INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 1, 'Season 1', 'Dr. Gregory House is devoid of bedside manner  and wouldn''t even talk to his patients if he could get away with it.  Dealing with his own constant physical pain, he uses a cane that seems  to punctuate his acerbic, brutally honest demeanor. While his behavior  can border on antisocial, House is a maverick physician whose  unconventional thinking and flawless instincts have afforded him a great  deal of respect. House''s roster of medical cases are the inexplicable  ones other doctors can''t solve, and he has assembled an elite team of  young medical experts to help him in his effort to solve these  diagnostic mysteries.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 1, 'Pilot', 'Dr. Gregory House, a brilliant diagnostician but devoid of bedside manner, and his elite team of young medical experts rush to save the life of a kindergarten teacher who started speaking gibberish and passed out in front of her class.', 44, '2004-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 2, 'Paternity', 'Dr. House goes with his gut and performs an unethical act to prove what he suspects to be the link to a teenage lacrosse player''s illness in order to save the boy''s life.', 43, '2004-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 3, 'Occam''s Razor', 'Dr. House and his team race to save a young man who may have not one, but two illnesses killing him.', 44, '2004-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 4, 'Maternity', 'A maternity ward epidemic forces House to decide whether to save the life of one child over another.', 43, '2004-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 5, 'Damned If You Do', 'Dr. House''s approach is questioned when he treats a nun for what he believes to be an allergy, not realizing the nun''s past is coming back to haunt her.', 44, '2004-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 6, 'The Socratic Method', 'The case of a schizophrenic mom with a deadly disease and her teenage son who have traded caretaking roles holds a special interest for Dr. House.', 44, '2004-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 7, 'Fidelity', 'Dr. House''s diagnosis of a married woman with a rare sleep disorder forces her and her husband to examine their marriage and question their trust for each other.', 44, '2004-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 8, 'Poison', 'House and his team have to act fast when a high school student is admitted with a mysterious and lethal poisoning, especially when they discover more teens have been diagnosed with the same deadly illness.', 44, '2005-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 9, 'DNR', 'House has to defend himself when he treats a patient who has legally chosen to refuse treatment.', 44, '2005-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 10, 'Histories', 'Dr. House and the team treat a homeless woman whose worsening symptoms and unknown identity prove to be a complex mystery.', 44, '2005-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 11, 'Detox', 'Dr. House takes Cuddy''s challenge to go off his painkillers for a week, but the effects of his withdrawal symptoms may put his patient in danger.', 44, '2005-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 12, 'Sports Medicine', 'A baseball player''s comeback is cut short when he breaks his arm and House and his team have to act fast to figure out what is causing major bone loss that''s killing the player and his dreams.', 43, '2005-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 13, 'Cursed', 'Dr. House''s young patient believes his illness is the result of a curse while House uncovers important information about Chase''s father.', 44, '2005-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 14, 'Control', 'The hospital''s new Chairman of the Board has it out for Dr. House, questioning his importance to the hospital and threatening to eliminate House and his team.', 44, '2005-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 15, 'Mob Rules', 'Dr. House and his team race to diagnose a member of the mob and get him well enough to testify and enter the witness protection program while Cuddy works to convince Vogler of House''s importance to the hospital.', 44, '2005-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 16, 'Heavy', 'Dr. House and his team try to uncover the reason a 10-year-old has a heart attack while House suspects one of his team is selling him out to Vogler.', 44, '2005-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 17, 'Role Model', 'House and his team battle to save a presidential hopeful, and House refuses to give in to Vogler''s ultimatum when given the chance to save one of his team members.', 44, '2005-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 18, 'Babies & Bathwater', 'House and his team battle to diagnose a pregnant patient''s life-threatening illness, prompting her to make the most emotional decision of her life, and Vogler is determined to fire House.', 44, '2005-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 19, 'Kids', 'House and his team race to diagnose a 12-year-old''s illness - an illness with a shocking origin - and House asks Cameron to come back to her job.', 44, '2005-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 20, 'Love Hurts', 'House and his team tackle the case of a young man with a penchant for odd behavior, and House prepares for his date with Cameron.', 44, '2005-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 21, 'Three Stories', 'House must decide whether to take the case of his ex-love''s husband and he gives medical students a lecture they''ll never forget.', 44, '2005-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 1), 22, 'Honeymoon', 'House is faced with a problem he may not be able to solve and Stacy returns.', 44, '2005-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 2, 'Season 2', 'House will do whatever it takes to solve a  case before it''s too late, from sending one of his team to break into a  patient''s home in search of clues, to attempting a controversial,  trial-and-error form of treatment to see how a patient responds. House''s  methods may be suspect, but his results are not — he saves lives no one  else can. Always in House''s way is Dr. Lisa Cuddy, the Dean of Medicine  and hospital administrator — and ethical gatekeeper of the hospital who  is in constant conflict with House over his extreme treatments and  unconventional behavior. House''s former love Stacy Warner recently  accepted a job as General Counsel to the hospital, and her presence  there has reignited feelings House thought were safely buried.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 1, 'Acceptance', 'When a Death Row inmate mysteriously and  suddenly collapses after hallucinating, House jumps at the chance to  take the case for its difficulty and because it''s "cool."', 44, '2005-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 2, 'Autopsy', 'A girl''s unimaginable bravery toward her terminal illness makes House suspicious as he puts a life-or-death decision about her case in her young hands.', 44, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 3, 'Humpty Dumpty', 'Cuddy struggles with a case of guilt when her handyman is injured while at her place, and House and his team have to work fast to save the young man''s pursuit of the American Dream.', 44, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 4, 'TB or Not TB', 'House''s patient is willing to die in order to further his social cause.', 44, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 5, 'Daddy''s Boy', 'Lies between a father and son may prevent House and his team from saving their patient.', 44, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 6, 'Spin', 'House''s wheels start turning when a pro-cyclist admits to taking performance-enhancing drugs.', 44, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 7, 'Hunting', 'A patient with AIDS stalks House to get him to take his case; House and Stacy stalk a mouse in her attic; and Cameron faces a health scare of her own.', 44, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 8, 'The Mistake', 'A patient''s death prompts an investigation into whether Chase or House may have been responsible for her death.', 44, '2005-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 9, 'Deception', 'With Foreman as House''s supervisor, the team must figure out if a woman who cried wolf  too many times is really ill.', 44, '2005-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 10, 'Failure to Communicate', 'A journalist''s head injury results in unintelligible speech, leaving House and his team at a loss; and the heat is turned up between House and Stacy when they''re out of town.', 44, '2006-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 11, 'Need to Know', 'While House''s staff tries to diagnose a woman whose uncontrollable muscle flailing caused her to crash her car, House and Stacy try to resolve their relationship issues once and for all. Cameron refuses to take her HIV test, wary of the results.', 44, '2006-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 12, 'Distractions', 'While a severely burned teenager is admitted and his blood tests come back with strange results, House makes himself the guinea pig in his own unofficial tests of a new drug designed to treat migraines to prove a former medical school colleague is wrong about the drug.', 44, '2006-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 13, 'Skin Deep', 'House uncovers a startling secret when he treats a teenage supermodel for heroin addiction. Meanwhile, Wilson hopes the increased leg pain in House''s leg is an indication his leg nerves are regenerating.', 44, '2006-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 14, 'Sex Kills', 'House takes the case of a man who experienced a seizure but wasn''t aware it happened. When the man suffers a heart attack and needs a heart transplant, the team races to diagnose a dead woman''s illness so they can harvest her heart to save their living patient.', 44, '2006-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 15, 'Clueless', 'House believes a woman is trying to kill her husband and tries to find the proof to confirm his suspicions. When Wilson moves in with House after separating from his wife, he learns Wilson is a great cook.', 44, '2006-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 16, 'Safe', 'A teenage heart transplant patient is rushed to the hospital when she has an allergic reaction while living in a "clean" room, and House and Wilson work out the kinks of their new living arrangement.', 43, '2006-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 17, 'All In', 'When a six-year-old boy is brought in with the same symptoms as another patient who died years ago under House''s care, House believes the cases are identical and he can predict the course of the boy''s illness. Meanwhile, the clinic hosts a poker night to benefit the oncology department.', 44, '2006-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 18, 'Sleeping Dogs Lie', 'House has to work fast when a woman comes in with a life-threatening case of insomnia. Meanwhile Cameron is angry at Foreman for stealing an article she worked on.', 44, '2006-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 19, 'House vs. God', 'House treats a 15 year old faith healer, while Wilson feels left out when he finds out House has a weekly poker game.', 44, '2006-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 20, 'Euphoria (1)', 'When a police officer with a gunshot wound to the head and uncontrollable laughter is admitted, House and the team are baffled. When Foreman begins showing the same symptoms, they race to determine the cause of the illness before Foreman''s condition takes the same path.', 44, '2006-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 21, 'Euphoria (2)', 'Foreman continues to experience the same progression of symptoms as the police officer. When he realizes he may be facing imminent death, he calls his father who comes to his son''s side. As it comes down to a race against time, House believes the solution to the illness is in the police officer''s apartment.', 44, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 22, 'Forever', 'A young mother has a seizure while bathing her newborn son and nearly drowns him. House and the team have two cases at one time as they try to save the infant and determine the cause of the mother''s seizures.', 44, '2006-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 23, 'Who''s Your Daddy?', 'A 16-year-old Hurricane Katrina victim suffering from hallucinations as a result of the tragedy is brought to House by his former bandmate who recently found out the girl is his daughter. Although House fears his friend is being scammed, he takes the case. As he works his way through the girl''s lies so he can diagnose and treat her, he''s forced to tell a few lies of his own.', 44, '2006-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 2), 24, 'No Reason', 'House is shot by a former patient and must share a recovery room with the gunman.', 44, '2006-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 3, 'Season 3', 'In the Season 2 finale, House suffered  multiple gunshot wounds inflicted by a former patient''s husband  determined to carry out retribution for House''s treatment of his wife''s  case. In a shocking surprise to his co-workers, House comes through the  ordeal with a slightly new perspective on his treatment of patients —  but will it affect how he makes medical decisions? And will it last?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 1, 'Meaning', 'After recovering from his gunshot wounds, House works feverishly on two cases at the same time: a paralyzed man who drove his wheelchair into a swimming pool and a woman who became paralyzed after a yoga session.', 44, '2006-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 2, 'Cane & Able', 'House and the team treat a young boy who claims there is a tracking device in his neck and believes he has been the subject of alien experimentation. Cameron is outraged when she learns Cuddy and Wilson have been lying to House about the diagnosis on his last case.', 44, '2006-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 3, 'Informed Consent', 'House puts a well-known medical researcher through a battery of tests to determine why he collapsed in his lab. When the team is unable to diagnose the problem, the doctor asks the team to help him end his life. House is forced to use his cane again after the ketamine has worn off as he deals with a clinic patient''s teenaged daughter who has a crush on him.', 44, '2006-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 4, 'Lines in the Sand', 'When doctors are unable to diagnose why a severely autistic boy screams loudly for no apparent reason, House takes the case. As the boy''s condition worsens, it becomes obvious that House relates to the boy because he has no social niceties.', 44, '2006-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 5, 'Fools for Love', 'House takes the case of a young woman who has been rushed to the hospital with problems breathing and severe stomach pain after she and her husband were robbed. After her husband collapses, the team believes the couple''s illnesses are related. Meanwhile, Michael Tritter, a clinic patient, causes problems for House that could have serious ramifications.', 44, '2006-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 6, 'Que Será Será', 'The team encounters logistical problems while trying to run tests on a 600-pound man due to his extremely large size. Meanwhile, House spends the night in jail after being arrested by Detective Tritter for various charges, including resisting arrest.', 43, '2006-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 7, 'Son of Coma Guy', 'House decides to awaken a comatose patient so he can question the man regarding the family history of his son, who may have a genetic condition and the father is the only living relative. Meanwhile, Wilson confronts House about the stolen prescription pad as Tritter approaches Cameron, Chase, and Foreman in an attempt to divide the team and reveal their loyalties.', 44, '2006-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 8, 'Whac-A-Mole', 'An 18-year-old teenager is brought to the hospital after having a heart attack. House reviews the boy''s file and believes he has the diagnosis. He then turns the case into a game by sealing his opinion in an envelope and challenging Cameron, Foreman, and Chase to guess House''s diagnosis on their own. Meanwhile, Tritter''s actions against Wilson continue to strain the oncologist''s relationship with House and destroy his ability to practice medicine.', 44, '2006-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 9, 'Finding Judas', 'House takes the case of a young girl who has been diagnosed with pancreatitis. When he takes her divorced parents to court to force them to allow treatment because they can''t agree, the judge awards guardianship of the girl to Cuddy. Meanwhile, Tritter continues his strategy to force House to admit to his drug use by offering one of the team members a deal.', 44, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 10, 'Merry Little Christmas', 'Wilson arranges for House to make a deal with Tritter, but House refuses. Meanwhile, Cuddy cuts House off Vicodin and removes him from the team''s case: a 15-year-old little person who entered the hospital with a collapsed lung and anemia.', 44, '2006-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 11, 'Words and Deeds', 'House splits his time between treating a firefighter for uncontrollable shivering, giving Tritter a piece of his mind, and handling his trial for forging prescriptions.', 44, '2007-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 12, 'One Day, One Room', 'While House is forced to work full-time in the clinic and deal with a rape victim who insists on confiding with him, Cameron deals with a terminal cancer patient trying to take advantage of her state of mind.', 44, '2007-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 13, 'Needle in a Haystack', 'House and his staff must deal with a teenage Gypsy boy suffering from inexplicable respiratory distress. However, House has bigger issues on his mind: Cuddy has given away his handicapped spot.', 43, '2007-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 14, 'Insensitive', 'It''s Valentine''s Day, and Cuddy has a blind date. Meanwhile, House leaves ER duty to take the case of a child patient named Hannah.', 44, '2007-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 15, 'Half-Wit', 'House encounters a brain-damaged musical prodigy with inexplicable abilities while the team faces serious concerns about House''s own health.', 44, '2007-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 16, 'Top Secret', 'The ex-marine that saved House''s life, in a dream he had the day before, is admitted in the hospital with symptoms resembling Gulf War Syndrome. While House is busy dealing with his own health issues, and Chase and Cameron are too busy with each other, the ex-marine gets worse.', 44, '2007-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 17, 'Fetal Position', 'A famous celebrity photographer suffers from a stroke while being pregnant at her early forties. House and his team have to deal with a great dilemma, save the mother or her unborn child.', 44, '2007-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 18, 'Airborne', 'On House and Cuddy''s flight from Singapore a passenger gets ill and Cuddy suspects an epidemic. At the hospital, Wilson leads the team as they deal with a middle-aged woman suffering from seizures.', 44, '2007-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 19, 'Act Your Age', 'A 6-year-old girl suffers ailments expected in patients much older. Tensions between Chase and Cameron lead House to intentionally assign them to the same tasks, including investigating the young girl''s home.', 44, '2007-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 20, 'House Training', 'The doctors try to find what''s wrong with a scam artist who collapses after her brain "freezes," but the case becomes personal for Foreman.', 44, '2007-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 21, 'Family', 'Wilson prepares to transplant bone marrow from Matty to his brother Nick. But when Matty gets sick, the team must cure him as he''s the only safe donor. Meanwhile Foreman deals with the consequences of his mistake and House has a battle of wills with his new pet Hector.', 44, '2007-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 22, 'Resignation', 'The team deals with a 19-year-old college student, while Foreman suddenly and without a reason hands in his resignation. House seems to have already found Foreman''s replacement, an attractive nutritionist named Honey.', 44, '2007-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 23, 'The Jerk', 'House treats a 16-year-old chess prodigy who gets everyone on the team annoyed with his behavior. Foreman is upset with House because he thinks his boss sabotaged his job interview with another hospital.', 44, '2007-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 3), 24, 'Human Error', 'A Cuban couple attempt to get to America by raft... to see House about the wife''s heart condition. But when she gets worse House wonders if someone on his staff messed up. Meanwhile Foreman prepares to leave and his departure threatens to shake up the entire team.', 44, '2007-05-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 4, 'Season 4', 'In the Season 3 finale, the set-in-his-ways House was confronted  with a series of major changes to his team — but any effects of this  “house-cleaning," or the changes it may bring to House professionally or  personally, remain to be seen...');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 1, 'Alone', 'With his diagnostic team gone, House tries to diagnose a young woman who survived an office building collapse. With the condition getting worse, Cuddy puts pressure on House to hire a new team, but instead attempts a differential diagnosis with help from the janitor.', 44, '2007-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 2, 'The Right Stuff', 'House is secretly trying to treat a fighter pilot who is a candidate for NASA''s astronaut training program. Her diagnosis will be the test to choose which ones of the 40 applicants are going to take the empty spots in his team.', 44, '2007-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 3, '97 Seconds', 'The candidates are now two teams of five women and five men, competing on diagnosing and treating a wheelchair-bound man. Meanwhile House does experiments on himself to test what happens after death, and Foreman, at another hospital, is treating his team in a House-like manner.', 44, '2007-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 4, 'Guardian Angels', 'House finds that some of his own fellowship students will do whatever it takes, when they deal with a woman who believes she can talk to the dead.', 44, '2007-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 5, 'Mirror Mirror', 'House deals with a patient who mirrors the personality of anyone he meets. Meanwhile, Foreman is put in charge of overseeing the fellowship candidates.', 44, '2007-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 6, 'Whatever It Takes', 'Based on practically no information and no medical history about a mystery patient sent by the CIA, House is using some unorthodox methods to diagnose and treat him. Meanwhile the remaining candidates are questioning Foreman''s judgment.', 44, '2007-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 7, 'Ugly', 'A film crew and the candidates are following around House distracting him while he is trying to diagnose a teenager who suffers from a heart attack prior to a serious plastic surgery.', 44, '2007-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 8, 'You Don''t Want to Know', 'House treats a magician but comes to believe he''s faking illness to cover up his own incompetence. Meanwhile, House pits the fellows against each other in his version of an immunity challenge.', 44, '2007-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 9, 'Games', 'Under Cuddy’s pressure to choose his team, House gives the candidates a case of a former punk rock star who is a drug user. Whoever diagnoses the patient is going to have a future as a member of House’s team.', 44, '2007-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 10, 'It''s a Wonderful Lie', 'A mother''s sudden paralysis during a indoor rock-climbing incident leaves her daughter injured, and House''s new team looking for a cure. Meanwhile, House organizes his new recruits'' Secret Santa gift exchange... with a few twists of his own.', 44, '2008-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 11, 'Frozen', 'House and his team have to diagnose a case at a distance when a researcher at a South Pole base is taken ill.', 44, '2008-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 12, 'Don''t Ever Change', 'House and his team must diagnose a Jewish bride who is taken ill at her wedding. However, House is more interested in analyzing Wilson''s relationship with his new girlfriend.', 44, '2008-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 13, 'No More Mr. Nice Guy', 'House copes with a patient whose symptoms conceal a greater problem, but spends much of his time dodging Cuddy''s orders to give performance reviews, and fighting with Amber over who gets to spend more time with Wilson.', 44, '2008-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 14, 'Living the Dream', 'House is convinced one of the actors on his favorite soap opera “Prescription Passion” has a serious medical condition after observing his symptoms on television. House decides to intervene and take matters into his own hands, but both the actor and House''s own team dismiss House’s assessment and do not believe there is anything wrong with him.', 44, '2008-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 15, 'House''s Head (1)', 'A bus accident leaves House with serious head trauma and partial amnesia. He comes to believe that a patient on the bus had a life-threatening disease and struggles to recall who it was, and what they had.', 44, '2008-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 4), 16, 'Wilson''s Heart (2)', 'In the aftermath of the bus accident, House struggles with his head injuries and short-term memory loss, and must deal with a concerned Wilson who believes his friend''s health may be in danger.', 44, '2008-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 5, 'Season 5', 'In the Season 4 finale, after a massive bus accident left House without  recollection of the accident, he and  the team put the pieces of his  memory together and discover Wilson’s girlfriend Amber was on the bus  with him and was fatally injured.  Wilson has to face the shocking  realization that House was involved in Amber’s death.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 1, 'Dying Changes Everything', 'In the aftermath of personal tragedy, Wilson resigns from the hospital... and from his friendship with House. Meanwhile, Thirteen struggles with her personal medical problems while helping treat an executive assistant with a similar situation to her own.', 44, '2008-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 2, 'Not Cancer', 'The team deals with an organ donor whose organs prove fatal, and the two surviving patients. Meanwhile, House hires a private detective to spy on Wilson, but hears a few things about himself that he''d rather not.', 44, '2008-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 3, 'Adverse Events', 'A painter''s undiagnosed illness affects his work, and House and his team must look at the man''s paintings to determine what''s wrong with him.', 44, '2008-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 4, 'Birthmarks', 'While en route to his father''s funeral, House must help the team with a differential diagnosis on a young Chinese girl who has collapsed under mysterious circumstances.', 44, '2008-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 5, 'Lucky Thirteen', 'Thirteen brings her one-night stand to the hospital after the woman has a seizure. However, the woman admits she slept with Thirteen just so she could get to House and have him diagnose her condition. Meanwhile, House continues to pay Lucas to spy on Wilson.', 44, '2008-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 6, 'Joy', 'An ailing man suffers from blackouts and sleepwalks, leading the team to wonder if his sleepwalking is a symptom, or how the man is becoming exposed to something else. When the man''s daughter grows ill as well, the team must provide a diagnosis before both die. Meanwhile, Cuddy adopts a newborn but when the birth mother displays a rash, she has to make a decision between putting the mother or daughter at risk.', 44, '2008-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 7, 'The Itch', 'The team must treat an agoraphobic who refuses to leave his house, and have to work around Cuddy, who is less than thrilled at having hospital equipment relocated. Meanwhile, House is plagued by an itch, and Cameron and Chase have relationship issues.', 44, '2008-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 8, 'Emancipation', 'While Foreman takes on a pediatric case on his own, the rest of the team deals with a 16-year-old factory manager and emancipated minor who collapses at work. When Foreman''s patient takes a turn for the worse, he''s forced to question whether he can deal with the situation on his own, or if he needs House''s help.', 44, '2008-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 9, 'Last Resort', 'A gun-wielding man from the waiting room at the Princeton-Plainsboro clinic takes House, Thirteen and several patients from the waiting room hostage in Cuddy''s office. The man claims to be sick with a long undiagnosed illness and demands medical attention from the best doctor in the hospital, threatening to kill any hostages necessary along the way.', 43, '2008-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 10, 'Let Them Eat Cake', 'The team takes on the case of a fitness guru on an all-natural diet who collapsed while filming a video. Meanwhile, Foreman conducts Huntington''s Disease drug trials and Thirteen signs on as a subject, Cuddy is forced to move into House''s office, and Kutner uses House''s name to run an online medical-advice website.', 44, '2008-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 11, 'Joy to the World', 'House and his team deal with a bullied girl who collapses during her school''s Christmas program. Meanwhile, Foreman and Thirteen grow closer during the Huntington''s disease drug trials, House gives a patient a gift, the staff wonder who gave House a special gift, and Cuddy gets an unexpected gift.', 44, '2008-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 12, 'Painless', 'House and the team try to diagnose a man living with severe, chronic pain; Thirteen and Foreman explore their complicated relationship; Cuddy discovers that caring for her baby leaves her with little time to run the hospital.', 44, '2009-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 13, 'Big Baby', 'Cuddy decides to spend more time at home to take care of her newly adopted baby and passes some of her day-to-day responsibilities off to Cameron, including supervising House. Cameron is forced to play House’s games and becomes involved in a power struggle as he and the team take on the case of a Special Education teacher who collapsed after spitting up blood in the middle of class. As House tests Cameron’s tolerance for his extreme measures, the patient continues to fall ill and House insists the teacher’s seemingly inherent goodness is actually a pathology.', 44, '2009-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 14, 'The Greater Good', 'House and the team take on the case of a woman who collapsed in the middle of a cooking class, and they soon learn she is a highly-renowned cancer researcher who recently gave up her entire career in order to pursue her own personal happiness. Though the team struggles to understand how the woman could give up saving lives for the sake of her own contentment, each grapple with the pursuit of happiness (or lack thereof) in their own lives. As the patient’s condition continues to worsen, so does Thirteen’s as she begins to suffer serious and life-threatening reactions to the experimental Huntington’s Disease clinical trial. Meanwhile, Cuddy attempts to make House’s life miserable for him in retaliation for his part in her own unhappiness.', 44, '2009-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 15, 'Unfaithful', 'When a priest who runs a homeless shelter sees a bleeding Jesus hovering at his doorstep, he is admitted to the ER. House takes on the case as a distraction for the team while he confronts Foreman and Thirteen about their relationship. The team soon learns the priest had been involved in a molestation scandal that caused him to lose his faith. However, just as they are about to dismiss his case, the patient’s condition takes a drastic turn for the worse, and House grapples with his past and his belief', 44, '2009-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 16, 'The Softer Side', 'A patient with both male and female DNA has the team stumped. Meanwhile, House starts acting nicely, raising Cuddy''s and Wilson''s suspicions that something is terribly wrong.', 44, '2009-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 17, 'The Social Contract', 'House and the team take on the case of Nick, a book editor who loses his inhibitions. The team realizes Nick has frontal lobe disinhibition, which causes him to speak his mind having no control over what he says and making him just like House. Meanwhile, House suspects Wilson and Taub are keeping something from him.', 44, '2009-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 18, 'Here Kitty', 'Morgan works in a nursing home with a pet cat who only sleeps next to people if they are about to die - and does so with alarmingly accuracy. When it seems the cat has predicted her own death, Morgan, convinced she is about to die, fakes a seizure in order to get to House to have him diagnose her before it’s too late.', 44, '2009-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 19, 'Locked In', 'A man awakens in New York after a bicycle accident unable to move or communicate in any way. House, himself injured in a motorcycle mishap, occupies the hospital bed next to Lee and quickly annoys the doctors treating them both by insisting that Lee has “locked-in” syndrome.', 44, '2009-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 20, 'Simple Explanation', 'Charlotte, an older woman who has spent the last six months taking care of her dying husband Eddie, is rushed to Princeton Plainsboro after collapsing from respiratory failure. The couple becomes a double mystery for the team when Eddie begins to improve as Charlotte’s condition worsens. The previously unthinkable becomes real when it seems that Charlotte will die before Eddie, and the team will be forced to make a difficult decision.', 44, '2009-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 21, 'Saviors', 'Cameron postpones her vacation with Chase in order to ask House to accept the case of an environmental radical who collapsed at a protest with unexplainable symptoms. Although suspicious of her motives, House agrees. Since she pushed him to take the case so emphatically, House forces Cameron to take the lead and run many of the tests on the patient. Meanwhile, House is unsure of Wilson’s new healthy diet.', 44, '2009-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 22, 'House Divided', 'The team takes on the case of a deaf 14-year-old named Seth who collapsed after he started “hearing” explosions while competing in a wrestling match. When the team tries to test him for seizures, Seth loses vision in one eye, complicating House’s bunk theory of “Exploding Head Syndrome.” As his condition worsens, the team has an ethical disagreement about the patient and his mother’s adamant decision to forego cochlear implants to supplement his hearing. When the prospect of giving Seth the ability to hear for the first time in his life arises, House and the team are faced with a resounding decision. Meanwhile, House’s lack of sleep starts to play tricks on his mind, but he finds his insomnia may be a gift instead of a burden', 44, '2009-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 23, 'Under My Skin', 'House and the team take on the case of a ballerina whose lungs collapse in the middle of a performance. When the treatment causes her skin to fall off, the dancer faces not only the prospect of never dancing again but also of dying an agonizing death. The team must use their imaginations to carefully choreograph ways to test and treat her delicate body without killing her. Meanwhile, House continues to suffer from what he thinks is insomnia, and he is willing to go to desperate measures to cure it.', 44, '2009-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 5), 24, 'Both Sides Now', 'House and the team are intrigued by Scott, a man whose left brain and right brain operate independently, leaving him with two distinct personalities and no control over some of his actions. As the two sides of Scott’s brain struggle for dominance, his warring personalities make it increasingly difficult for the team to figure out what is causing the unique problem. The team is forced to use some unusual methods to get him to cooperate with their necessary testing. Meanwhile, when House refuses to make an appearance in the clinic, Cuddy takes an unconventional approach to force House to make up the time with a particular patient.', 44, '2009-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 6, 'Season 6', 'When the previous season concluded, House was  forced to admit that he had lost his grip on reality and could no longer  practice medicine.  Out of options, he checked himself into a  psychiatric hospital. Season 6 will explore  House’s long and twisted road to recovery: Can he find some version of  sanity and normalcy? Can he stay away from the workplace that arguably  drove him to mental instability but is also the only stable foundation  in his life? Can Princeton-Plainsboro continue its celebrated Department  of Diagnostics without him? How will Cuddy’s relationship with House  change, now that their imagined affair is out in the open?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 1, 'Broken', 'House is detoxing at a mental hospital and being held against his will by his attending physician, so he concocts an escape plan, aided by his roommate and a visitor named Lydia.', 88, '2009-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 2, 'Epic Fail', 'House returns home to Princeton where he continues to focus on his recovery, but surprises Cuddy with the news that he''s making a big change in his life. Meanwhile, the team is unable to diagnose a loud-mouthed video game creator who posts each new symptom on the internet and opts for treatments suggested by the online community rather than by the doctors, and Foreman angles for House''s job, but the pressure to solve the case creates tension in his relationship with Thirteen.', 44, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 3, 'The Tyrant', 'When a controversial African politician falls ill, he is brought to Princeton Plainsboro for treatment. The team struggles with whether to help a merciless dictator being subpoenaed for crimes against humanity in his country. Meanwhile, Wilson tries to make peace with a feuding neighbor, but House’s prying exacerbates the problem.', 44, '2009-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 4, 'Instant Karma', 'A wealthy businessman brings his teenage son, who is suffering from inexplicable stomach pains, to Princeton Plainsboro and insists on having Dr. House handle the case. The father of the patient believes the karmic penalty of his financial success is that he is victim to personal tragedy, and that the answer to his son''s medical mystery lies in a reverse of fate rather than medical treatment. Meanwhile, Foreman and Chase prepare to present information on the Dibala case.', 44, '2009-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 5, 'Brave Heart', 'A dying patient insists that he has the same disease affecting his heart that killed his father and grandfather at the age of 40. Meanwhile, House discovers that he has a hearing problem while trying to duck student rounds.', 44, '2009-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 6, 'Known Unknowns', 'After a wild night out, a teenage girl is brought to Princeton Plainsborough with severely swollen appendages. The team must work to diagnose the young girl, who is less than honest about what happened the night she fell ill. As her condition worsens, she becomes unable to distinguish fact from fiction. Meanwhile, Cuddy, Wilson and House spend a weekend away from the hospital to attend a medical conference, but things don’t go as planned when House’s private investigator, Lucas returns.', 44, '2009-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 7, 'Teamwork', 'After House’s medical license is reinstated, he reclaims his role as Head of Diagnostics in time to treat Hank Hardwick, an adult film star admitted to Princeton Plainsborough for pulsating eye pain. Meanwhile, Cuddy is reminded that Princeton Plainsborough is not conducive to healthy personal relationships.', 44, '2009-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 8, 'Ignorance Is Bliss', 'On the eve of Thanksgiving, House and the team take on the case of James Sidas, an exceptionally brilliant physicist and author who traded his successful career for a job as a courier. For the ailing patient, intelligence is a miserable burden that has prompted depression and addiction, and this, coupled with a myriad of strange symptoms, nearly stumps the team. Meanwhile the doctors at Princeton Plainsboro wrestle with strained personal relationships.', 44, '2009-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 9, 'Wilson', 'When an old friend and former patient of Wilson’s exhibits paralysis in his right arm, Wilson puts himself on the case. House wagers Wilson that the patient’s symptoms are attributed to new cancer cells. Wilson accepts even though he is reluctant to believe the cancer has returned. With the help of the team, Wilson works to diagnose the patient more optimistic results, but when things take a turn for the worse, Wilson must address his inability to separate patient from friend. Meanwhile, Cuddy seeks advice in her search for real estate.', 44, '2009-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 10, 'The Down Low', 'When drug dealer Mickey mysteriously collapses while negotiating a sale, his partner-in-crime, Eddie, accompanies him to Princeton Plainsboro for treatment. But with a major deal pending, Mickey is not forthcoming with the necessary personal information the team needs to treat him. As Mickey''s condition worsens, the team resorts to old-fashioned detective work to solve the case. Meanwhile, House and Wilson compete for the affection of a new neighbor, and Chase, Thirteen and Taub attempt to play a practical joke on Foreman.', 44, '2010-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 11, 'Remorse', 'The team takes on the case of Valerie, an attractive female executive experiencing random episodes of excruciating pain. House agrees to take the case based on Valerie’s looks, and while treating her, the men on the team are charmed by Valerie’s beauty and personality, with Thirteen looking beyond the superficial to try to discover a link to her illness. Meanwhile, House uncharacteristically attempts to alleviate his conscience by reaching out to a former medical school colleague he wronged.', 44, '2010-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 12, 'Moving the Chains', 'House and the team rush to treat an ailing college football star in time for the patient to compete in NFL tryouts. But when the patient experiences an onslaught of varied and unusual symptoms, the team has trouble reaching a consensus on how to effectively treat him in time. Meanwhile, Foreman’s brother Marcus makes a surprise visit to the hospital.', 44, '2010-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 13, '5 to 9', 'During a day in the life of Princeton Plainsboro''s Dean of Medicine, Dr. Lisa Cuddy, the inner workings of the hospital are seen through her eyes. This day proves to be especially trying as Cuddy wrestles with myriad hospital issues and staff disputes that test her perseverance and skills as an administrator, all while juggling issues in her personal life.', 44, '2010-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 14, 'Private Lives', 'House and the team take on the case of an avid blogger admitted with sudden bruising and bleeding. From her hospital bed, the patient blogs about her symptoms, doctors and prospective diagnoses to her dedicated band of followers and solicits their advice on a course of treatment. Such openness leads the team to contemplate the value of privacy, especially after House and Wilson uncover secrets from one another ''s past. Meanwhile, Chase is coaxed into testing out the dating scene.', 44, '2010-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 15, 'Black Hole', 'The team takes on the case of a high school senior who inexplicably blacks out during a class field trip. While in the hospital, the patient repeatedly hallucinates. After exhausting myriad ineffective treatments for her mysterious ailments, House attempts one last controversial approach to diagnosing her: monitoring her cognitive patterns and looking for clues. Meanwhile, Taub airs his dirty laundry at work, and Wilson attempts to furnish his condo.', 44, '2010-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 16, 'Lockdown', 'This episode has five storylines: When the hospital is sent into lock-down mode due to a missing infant, all of the doctors must remain where they are, leaving Foreman and Taub in the file room, Wilson and Thirteen in the cafeteria playing truth or dare, House in a room with a patient, and Chase with his soon-to-be ex-wife, Cameron, as Cuddy tries to help police locate the infant. This episode is one of the show''s rare instances when no medical mystery is presented, though House still deals with his "patient of the week".', 44, '2010-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 17, 'Knight Fall', 'House and the team take on the case of Sir William, a "knight" in a closed-off community of men and women living according to the ideals of the High Renaissance. As the team searches the medieval village for environmental factors contributing to Sir William''s rapidly deteriorating health, Thirteen and Sir William debate the acts that define honor and loyalty, especially in regard to the "queen" of the community, one of Sir William''s most frequent visitors. Meanwhile, Wilson starts over with an ex.', 44, '2010-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 18, 'Open and Shut', 'House and the team take on the case of a woman Julia, who is in an open marriage and becomes ill during a date with her on-the-side boyfriend. As perplexing as the case is, Julia''s happy and healthy, yet polyamorous relationship is equally baffling to the team. Meanwhile, House tests Wilson''s relationship with Sam.', 44, '2010-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 19, 'The Choice', 'The team takes on the case of an ailing groom-to-be who harbors undisclosed secrets from a previous relationship. As his fiancée tries to get answers to her many questions, a frustrated team winnows down the possibilities. Meanwhile, House spends extra-curricular time with his Princeton Plainsboro colleagues, performing a karaoke rendition of a Gladys Knight & The Pips classic with Foreman and Chase.', 44, '2010-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 20, 'Baggage', 'During a session with Dr. Nolan, House recounts the case of a woman who arrives at the Princeton Plainsboro emergency room with an unexplained illness and no recollection of who she is. While trying to solve the mystery of the woman''s illness, House must also help her piece together her identity.', 44, '2010-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 6), 21, 'Help Me', 'Cuddy, House and members of the team join forces with a search-and-rescue team to provide much-needed medical attention at the scene of an emergency.', 45, '2010-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 7, 'Season 7', 'In the Season 6 finale, House, driven by the  loss of a patient he treated at an accident site and confronted with  the unexpected news that Cuddy was now engaged, spiraled into despair  and considered treating his mental and emotional anguish with Vicodin,  potentially prompting the cycle of his dependency and addiction all over  again. But in a surprising turn, Cuddy revealed that she called off her  engagement and admitted to House she loves him, despite wishing she  didn’t. Also, Thirteen submitted her leave of absence from the hospital,  prompting questions about the status of her health.  As Season 7 begins, House and Cuddy attempt to make a real  relationship work and face the question as to whether their new  relationship will affect their ability to diagnose patients.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 1, 'Now What?', 'House and Cuddy are exploring the ramifications of those feelings and attempting to make a real relationship work. Meanwhile, due to a colleague''s illness, Princeton Plainsboro is left without a neurosurgeon on site, threatening the hospital''s accreditation as a Level 1 Trauma Center. As the team attempts treatment to get their sick colleague back to work, they discover there is more to the illness than they originally suspected and turn to House for direction. Instead, House remains elusive, leaving the team on its own.', 42, '2010-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 2, 'Selfish', 'A seemingly healthy 14-year-old girl collapses during a skateboarding exhibition; House and Cuddy face the challenge of handling their romantic relationship at work.', 44, '2010-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 3, 'Unwritten', 'A children''s novelist tries to kill herself, but is thwarted when she has a seizure. House, a fan of the books, puts her on psych hold but has to deal with a patient that is eager to die rather than be cured. Meanwhile, House worries that he''ll lose Cuddy because they have nothing in common.', 44, '2010-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 4, 'Massage Therapy', 'House and his team make unexpected discoveries about a female patient admitted to the hospital after severe and uncontrollable vomiting; House and Cuddy are forced to face the reservations in their relationship after a visit from a massage therapist.', 44, '2010-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 5, 'Unplanned Parenthood', 'When an infant suffers breathing trouble and liver failure, House and the team must look at the medical history of the mother in order to find an answer, and ultimately land on a discovery that forces the mother to jeopardize not only her child''s health but her own. Meanwhile Taub and Foreman must find a new female doctor to fill the spot vacated by Thirteen and House and Wilson learn a thing or two about parenting while caring for Cuddy''s daughter.', 44, '2010-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 6, 'Office Politics', 'It’s election season, and in the midst of a tight campaign, an incumbent New Jersey senator’s campaign manager falls ill with liver failure and temporary paralysis. Cuddy pushes House to add a female doctor to his team by hiring brilliant third-year medical student Martha Masters in Thirteen’s absence.', 44, '2010-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 7, 'A Pox on Our House', 'After a 200-year-old medicine jar found on an off-shore shipwreck shatters in a teenage girl''s palm, she is admitted to Princeton Plainsboro for symptoms closely linked to smallpox.', 44, '2010-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 8, 'Small Sacrifices', 'Science and faith are called into question when a patient is admitted to the hospital following his reenactment of the Crucifixion. Meanwhile, Taub questions his wife about her relationship with an infidelity support group member, and the team attends a co-worker''s wedding.', 44, '2010-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 9, 'Larger Than Life', 'After saving a stranger who fell onto subway tracks, a man suddenly collapses despite appearing to be unscathed; House tries to avoid a dinner with Cuddy and her opinionated mother.', 44, '2011-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 10, 'Carrot or Stick', 'House and the team try to link symptoms of a teenage military recruit and his drill sergeant, while House secretly helps Cuddy''s daughter get into a prestigious preschool. Someone posted a disparaging photo of Chase on a social-networking site.', 44, '2011-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 11, 'Family Practice', 'Cuddy’s mother, Arlene, is admitted to Princeton Plansboro after complaining about unusual symptoms, but stubborn Arlene insists that House be removed from the case, forcing House to come up with non-conventional means to treat his patient.', 44, '2011-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 12, 'You Must Remember This', 'When a waitress with a perfect memory suffers temporary paralysis, her older sister visits her in the hospital, which triggers high stress levels and even more health complications.', 44, '2011-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 13, 'Two Stories', 'House participates in a school’s Career Day and breaks a few rules by sharing explicit medical stories. Waiting outside the principal’s office, he meets two fifth-grade students who assess House’s relationship woes and try to help him understand how his selfish antics get in the way of showing Cuddy how he really feels.', 44, '2011-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 14, 'Recession Proof', 'A patient is admitted after breaking out in a severe rash triggered by caustic chemical exposure at his blue-collar job. Meanwhile, Cuddy is honored with an award and needs House to be at the charity event for support, but his attendance is threatened when his patient’s battle to survive forces him to question his practice and his own happiness.', 44, '2011-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 15, 'Bombshells', 'Tension reaches new heights when Cuddy faces sobering news that propels her to reevaluate her priorities. While House is distracted by his concern for Cuddy’s well-being, the team treats a teenage patient whose worsening symptoms and suspicious body scars indicate more than just physical illness.', 44, '2011-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 16, 'Out of the Chute', 'The team treats a professional bull rider who is attacked by a bull. The team must determine the causes behind the patients disappearing symptoms and seizures while taking House''s advice from outside the hospital as he attends to issues unrelated to the case. Meanwhile, Masters develops a crush on the patient.', 44, '2011-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 17, 'Fall from Grace', 'A homeless man with a history of drug abuse is admitted to Princeton Plainsboro with burns and scars on his chest. Meanwhile, Cuddy reveals her guilt to Wilson about breaking up with House.', 44, '2011-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 18, 'The Dig', 'Thirteen has been in prison for the past year, but the real mystery for House is what she did to get there. At the hospital, the team treats a science teacher suffering from severe respiratory illness. Taub tries to get back into the dating scene, but winds up retreating to his old habits.', 44, '2011-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 19, 'Last Temptation', 'Masters faces a career crossroads on her last day as a medical student and struggles with the choice to continue on the path to become a surgeon or to accept the rare opportunity to join House’s team officially. Meanwhile, the team treats a 16-year-old girl who inexplicably collapsed days before embarking on an ambitious sailing tour around the globe. Despite the patient''s life-changing diagnosis, the patient''s family insists on getting her back on the seas in time for her potentially record-breaking launch. But to the team''s surprise, including House, Masters makes a bold decision regarding the patient’s treatment.', 44, '2011-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 20, 'Changes', 'The team takes on the case of a lottery winner (Donal Logue) suffering from paralysis and multiple types of cancer, and they must figure out if it his new millionaire lifestyle that is making him sick. Meanwhile, Cuddy''s mother threatens to sue the hospital over her treatment, and Foreman and Chase make a bet over who is repressing the uglier side of their personality more.', 44, '2011-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 21, 'The Fix', 'After losing a bet with Wilson over a boxing match, House is convinced that his fighter has an underlying medical condition that cost him the fight. While he tries to prove it, he leaves his team alone to help a bomb scientist who suffered a seizure. Meanwhile, House may be experimenting with a new drug to help his leg pain.', 44, '2011-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 22, 'After Hours', 'When House discovers that the experimental drug he''s been using causes fatal tumors, he decides to attempt to excise them himself. However, he can''t complete the surgery and ends up needing Cuddy''s help. Meanwhile, Thirteen''s friend from prison (Amy Landecker), a relapsed drug user, arrives at her apartment needing medical care after being stabbed. With her friend unwilling to go to the hospital, Thirteen enlists Chase''s assistance when the friend loses sensation and movement in her arm. Also, Taub receives some unexpected news that could change his life.', 44, '2011-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 7), 23, 'Moving On', 'The team treats a performance artist (Shohreh Aghdashloo) who deliberately made herself ill with the aim of turning the diagnostics department into her new masterpiece, as House must decide which of her symptoms are real, and which are self-inflicted. As the case progresses, House vows to make changes in his life, but remains rooted in old habits. After the case is over, House finally deals with his anger over the breakup and lashes out by driving through Cuddy''s dining room and escaping to a beach.', 44, '2011-05-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')), 8, 'Season 8', 'Last season, House and Cuddy finally decided to take  their relationship to the next level, but struggled to find a balance  between their professional and personal lives, and ultimately, Cuddy  made the very emotional decision to end their relationship. As each of  them dealt with the aftermath of the break-up, House got married to an  immigrant in need of a Green Card. In the series'' milestone 150th  episode, Thirteen was released from prison after euthanizing her brother  who was suffering from the late stages of Huntington''s Disease, the  same disease with which she is afflicted.  As the season comes to a  close, when House''s attempts to mend his relationship with Cuddy fall  short, he''s compelled to take drastic and possibly irrevocable measures  that could forever change the course of their relationship.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 1, 'Twenty Vicodin', 'House is serving out a lengthy prison sentence for his various misdeeds, including his trip outside the country in an attempt to escape responsibility. Entirely cut off from his old life, House determines his current problems are the result of his inability to deal with people. Feeling he will never be able to practice medicine again, he plans instead to go back to university to earn a doctorate in physics - a field that will all but assure his isolation from other human beings.', 44, '2011-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 2, 'Transplant', 'A surprising visitor makes House an offer he can''t refuse by giving him the opportunity to help the Princeton Plainsboro team treat a unique patient in order to save the life of an organ recipient being treated by Wilson. Although House finds himself back on familiar ground, he quickly realizes that much has changed since he left, and he is forced to work on the case with smart yet timid resident Dr. Chi Park. After several inconclusive treatments and with time running out, House and Dr. Park are left with one last option to examine the patient''s medical history that could compromise House''s conditional agreement with the hospital. Meanwhile, House makes an effort to reconnect with Wilson despite a cold reception.', 44, '2011-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 3, 'Charity Case', 'House and Park treat a patient, Benjamin, who collapsed after making a surprisingly large charity donation, and come to suspect that the altruistic behavior is a symptom of a deeper disorder. When the patient offers to donate an organ for another patient, the doctors must convince Dr. Adams to help them confirm whether Benjamin is in his right mind or not.', 44, '2011-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 4, 'Risky Business', 'A CEO falls mysteriously ill just days before he signs a contract that would relocate his company''s entire labor force to China. House attempts to make an underhanded business transaction with his wealthy patient, but when the patient''s condition worsens, the team must work around the clock to save his life. Meanwhile, Park prepares for her hearing with the Princeton Plainsboro Disciplinary Committee chaired by Foreman, and Adams'' outlook on her patient''s business venture reveals her deeper feelings about loyalty.', 44, '2011-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 5, 'The Confession', 'A man well-respected in his community suddenly collapses, and in the process of diagnosing his symptoms, the team discovers that the patient has been hiding dark and dishonest secrets about his personal and professional life. But when the patient openly confesses his wrongdoings to his family and community, he compromises his chances of receiving the proper medical treatment. Meanwhile, House will stop at nothing to manipulate Taub into taking a DNA test to prove he is the father of his two six-month-old daughters.', 44, '2011-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 6, 'Parents', 'A teenage boy attempting to follow in his late father’s footsteps as an entertainer is admitted to Princeton Plainsboro with partial paralysis. As the team searches for a bone marrow match, they uncover a disturbing family secret. Meanwhile, House looks for creative ways to remove his ankle monitor so that he can attend a boxing match in Atlantic City, and he treats a patient who is convinced he is suffering from diabetes. Also, Taub faces a tough decision when his ex-wife Rachel tells him that she wants to move across the country with their infant daughter.', 44, '2011-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 7, 'Dead & Buried', 'The team learns that their 14-year-old patient is suffering from more than teen angst when her physical symptoms worsen. Despite Foreman’s firm opposition, House becomes obsessed with solving a peculiar case of a deceased four-year-old patient, which gets him into serious trouble. Meanwhile, Park tries to get Chase to admit the reason behind his recent obsession with grooming.', 44, '2011-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 8, 'Perils of Paranoia', 'A prosecutor suffers from what he believes to be cardiac arrest during an interrogation at the witness stand. The team''s preliminary diagnosis is hyper-anxiety, but when Adams and Park investigate the patient''s home and find a hidden arsenal of firearms, they uncover a more alarming and deep-seated psychological disorder.', 44, '2011-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 9, 'Better Half', 'House and his team treat an Alzheimer''s patient who vomits blood and flies into violent rages. Meanwhile, when Wilson tells House about a patient who has never had sex with her husband of 10 years, claiming A-sexuality, House makes a wager with him that there has to be an underlying cause.', 44, '2012-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 10, 'Runaways', 'When a runaway teen requires hospitalization, Adams butts heads with House when she insists they contact Social Services. Meanwhile, Taub has trouble forming a personal connection with his baby daughters and Foreman''s relationship with a married woman comes out.', 44, '2012-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 11, 'Nobody''s Fault', 'House and his team are placed under review after a staff member gets hurt.', 44, '2012-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 12, 'Chase', 'Chase''s religious faith bubbles to the surface when he treats a young nun. In addition, he and House reach a fundamental disagreement about the patient that may finally end Chase''s reputation as House''s "yes man" but also bring''s House''s methods, reputation and objectivity are given more serious scrutiny.', 44, '2012-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 13, 'Man of the House', 'House''s green-card wife, Dominika, will return in order to prove to the proper authorities that she and House are actually married. This in turn will lead to a crash course in which both will learn a little something about love and marriage.', 44, '2012-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 14, 'Love Is Blind', 'A successful, independent blind man is struck down with a mysterious illness, just prior to him asking for his girlfriend''s hand in marriage. Meanwhile, House has a family member visit to inform him of a life change. "Love Is Blind" is the fourteenth episode of season eight of House and the 169th overall. The episode debuted in Canada on Global on February 27, 2012, and aired three weeks later in the United States on Fox on March 19, 2012. The unusual three-week delay was a byproduct of the 2012 Daytona 500 rain delay of 30 hours.', 44, '2012-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 15, 'Blowing the Whistle', 'The team treats an Army veteran charged with treason after he leaked classified information. But the patient''s life is put at risk when he refuses treatment unless he and his brother are given information about their late father, a war veteran, which raises questions about loyalty to one''s family and country. Meanwhile, Adams suspects House may be sick, so she recruits Wilson and the other team members to plan an intervention and investigate his illness.', 43, '2012-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 16, 'Gut Check', 'House and the team take on the case of a 22-year-old minor league hockey player who collapsed while coughing up blood after a fight on the ice. Meanwhile, House drops a bomb on Wilson, and Chase offers to help Park change her living arrangement.', 44, '2012-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 17, 'We Need the Eggs', 'House and the team take on the case of a man who starts tearing blood. Meanwhile, House is interviewing for a new favorite hooker, since his current favorite, Emily, has decided to get married and leave the business. Desperate for Emily "companionship," House teams up with his "wife" Dominika to sabotage Emily''s budding relationship.', 44, '2012-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 18, 'Body and Soul', 'House and the team take on the case of a young boy who has violent dreams of being choked, and then wakes up but still can''t take in air. Meanwhile, Park is having intimate dreams involving co-workers, which causes the team to question whether or not there''s significance to what each of them dreams. Dominika discovers House has been keeping a secret from her and Wilson drops a bombshell on him.', 44, '2012-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 19, 'The C-Word', 'When House and Wilson disappear off the grid for several days, without explanation, the team is left to deal with a difficult case concerning a 6-year old with numerous problems and complications, including an overbearing mother who also happens to be her physician.', 44, '2012-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 20, 'Post Mortem', 'Over the years, during the course of performing autopsies at Princeton-Plainsboro, Dr. Peter Treiber has often identified mistakes made by physicians that caused the patient''s death. These observations have left him questioning the skills of nearly all the doctors on staff... all, that is, except House. When he falls ill, he demands that only House make medical decisions concerning his care. Unfortunately, House and Wilson have taken off on an impromptu road trip without telling anyone, leaving the team to fend alone and lie to their patient to make him believe that House is the guy calling all the shots.', 44, '2012-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 21, 'Holding On', 'The team takes on the case of Derrick, a 19-year-old college student who had a mysterious nose bleed during cheerleading practice, and discovers that his health issues are likely both physiological and psychological. Possibly suffering from schizophrenia, Derrick claims to hear his deceased brother’s voice in his head. Meanwhile, Foreman tries a different approach with House.', 44, '2012-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0412142')) AND numero_temporada = 8), 22, 'Everybody Dies', 'Facing a 6-month jail term, and the realization that he won''t be there for Wilson at the end, House finds himself examining his entire life while contemplating a dismal future without his best friend.', 44, '2012-05-21');
