INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')), 1, 'Book One: Water', 'Katara and Sokka (a brother and sister from the Southern Water Tribe) discover the Avatar (a 12-year-old Airbender boy named Aang) frozen in an iceberg. Together the three begin their journey to the North Pole to find a master waterbender so Aang can begin his Avatar training!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 1, 'The Boy in the Iceberg', 'Two teenage siblings (Sokka and Katara) living in the South Pole discover a very strange boy (Aang), along with his pet flying bison Appa, in an iceberg. But can they trust him when he accidentally draws the war to their village''s doorstep?', 24, '2005-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 2, 'The Avatar Returns', 'Katara and Sokka discover that Aang is the long-lost Avatar and must rescue him when a firebending prince named Zuko kidnaps him.', 24, '2005-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 3, 'The Southern Air Temple', 'Aang is excited about going home for the first time in one hundred years, but he is shocked to find out that the temple is deserted. Aang tells Sokka and Katara about his childhood as they explore the temple, but they soon discover something that Aang never expected. Meanwhile, Zuko must make repairs to his ship and the only way he can do it is to dock his ship at his rival''s naval base.', 25, '2005-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 4, 'The Warriors of Kyoshi', 'The gang arrives at Kyoshi Island and are captured by some Kyoshi warriors. When Aang reveals that he is the avatar, news quickly spreads out, eventually reaching Zuko, who then goes to Kyoshi Island to capture him.', 24, '2005-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 5, 'The King of Omashu', 'Aang''s abilities as an airbender are challenged by a strange king.', 25, '2005-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 6, 'Imprisoned', 'In a nearby Earth Village, the gang meets a teenage earthbender named Haru. This village lives in fear of the Fire Nation, for soldiers there capture any earthbenders they can find. After Haru is captured for earthbending, Katara is compelled to rescue him.', 25, '2005-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 7, 'The Spirit World: Winter Solstice (1)', 'Aang and friends visit a village being terrorized by an angry spirit. Iroh is captured by Earth Kingdom soldiers.', 25, '2005-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 8, 'Avatar Roku: Winter Solstice (2)', 'To contact the spirit of the previous Avatar, Aang must reach a temple in the Fire Nation before the sun sets on the following day. There he will learn what he must do to restore balance to the world. Zuko must defy his banishment to follow Aang.', 24, '2005-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 9, 'The Waterbending Scroll', 'After Katara attempts to teach Aang waterbending, but realizes that he is learning it much faster than she is, she is desperate to improve her abilities.  When Katara inadvertently stumbles across a waterbending scroll that can help improve her abilities at a pirate’s store, she decides to steal it, realizing that she couldn’t hope to afford it.', 25, '2005-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 10, 'Jet', 'While traveling towards the North Pole, the group almost gets captured by the Fire Nation.  However, when a charismatic young man and his band of rebels attack the Fire Nation camp and rescue them, they learn that they are trying to resist the Fire Nation’s motives to expand their territory.  Katara and Aang really enjoy their time with the band of rebels, but Sokka soon discovers that they aren’t as noble as meets the eye.', 25, '2005-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 11, 'The Great Divide', 'While on their way to the North Pole, Aang and his friends arrive at a giant canyon where two groups of refugees are bickering over who should get to go across.  Aang decides to walk across with the two groups to ensure they don’t fight one another.  However, he soon learns that the two tribes have been feuding for one hundred years and they both believe their actions are justified.  But when the predators inside the canyon start to come out, Aang is stuck trying to defend both tribes from each other and the vicious wildlife.', 25, '2005-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 12, 'The Storm', 'Sokka accepts a job for a fisherman who is looking for someone to help him out with his fishing. After the fisherman finds out Aang is the Avatar, Aang runs away in response to the fisherman''s hostile reaction. When Katara finds Aang, he begins to reveal his life before he was frozen in the iceberg. Meanwhile, after Zuko gets into a fight with his crew, Iroh tells them about Zuko''s complicated past, attempting to make both sides understand each other.', 25, '2005-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 13, 'The Blue Spirit', 'While Aang, Katara and Sokka are traveling, Sokka gets a fever. Katara and Aang try to help Sokka, when Katara also catches the fever. It''s up to Aang to go up on his own to save his two friends. But before he can get the medicine he is captured by the newly promoted Admiral Zhao and put in Zhao''s fortress.', 25, '2005-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 14, 'The Fortuneteller', 'When the group tries to help a man who is being attacked by a platypus-bear, they discover that the local town has a fortuneteller named Aunt Wu in it, who has been forecasting the town''s fate for years. But when Sokka and Aang discover one of the fortuneteller''s most vital predictions is dead wrong, they have to develop a plan to convince the stubborn townspeople that their beloved Aunt Wu was wrong.', 25, '2005-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 15, 'Bato of the Water Tribe', 'Aang feels neglected as Katara and Sokka reunite with Bato, an old friend of their father’s from the South Pole. They begin to reminisce on their times in the past while they wait for a message to arrive from their father. Aang believes Katara and Sokka will abandon him and go out to find their father should the message arrive. However, when the messenger gives Aang the message to give to Bato, Aang betrays his friends in a way Katara or Sokka could never imagine. However, when Zuko recruits a bounty hunter named June to track Aang down, his friendship is put to the test as he must deal with the fact that he betrayed his friends while defending himself from yet another fight.', 25, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 16, 'The Deserter', 'Aang and his friends go to a Fire Nation town so that Aang can witness some firebending, but their plan soon goes awry when it’s discovered that he is the Avatar. Fortunately, he''s rescued by an individual who serves a firebending master named Jeong Jeong who has abandoned the Fire Nation, so Aang decides to use this time to attempt to learn firebending. The firebending master, however, seems reluctant to teach Aang.', 25, '2005-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 17, 'The Northern Air Temple', 'When Aang and his friends hear rumors about surviving airbenders, they decide to stop by the Northern Air Temple on their way to the North Pole to see for themselves. What they find is a bunch of people who are not airbenders, but have mastered the art of gliding; though this upsets Aang because they have been defacing the temple. However, there was one part of the temple where nobody has been able to enter, and what Aang and his friends discover inside spells oncoming conflict.', 25, '2005-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 18, 'The Waterbending Master', 'When Aang tries to find the north pole, he is found by the north pole instead. As they are taken there, Aang and Katara are eager to find a waterbending master, only to discover that girls are not allowed to learn waterbending.', 25, '2005-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 19, 'The Siege of the North (1)', 'Zhao begins to launch his attack against the Northern Water Tribe. As the walls of the prestiged city begin to fall, the Avatar taps into the spirit world and seeks the help of one of the oldest spirits, in hopes of saving one of the most prominent areas of the world.', 25, '2005-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 1), 20, 'The Siege of the North (2)', 'Aang returns from the spirit world to a big surprise. Meanwhile, Zhao and his forces continue to press deeper into the Northern Water Tribe. Iroh makes a powerful stand and Zuko struggles to keep his plan intact.', 26, '2005-12-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')), 2, 'Book Two: Earth', 'Aang, along with Katara, Sokka, and their animal friends Appa and Momo, continues on his quest to fulfill his destiny as the Avatar. According to the Avatar cycle, the group must now enter the Earth Kingdom to search for a master earthbender to teach Aang.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 1, 'The Avatar State', 'Plagued with nightmares featuring the devastating power of his Avatar State, Aang and the gang meet an Earth Kingdom general who has big plans for defeating the Fire Nation. Meanwhile, Zuko and Iroh, having survived the failed attack on the North Water Tribe, have a surprise visit from Zuko''s sister with seemingly good news.', 25, '2006-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 2, 'The Cave of Two Lovers', 'On their way to Omashu, Aang, Katara, and Sokka meet a group of nomads who show them a shortcut through the "Cave of Two Lovers". But when the group becomes trapped in the cave, it''s up to Aang and Katara to save the group by trusting in love, possibly questioning their relationship. Meanwhile, Iroh gets a lethal rash so Zuko and Iroh head to a small Earth Kingdom town for help, hoping their real identities will not be discovered.', 25, '2006-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 3, 'Return to Omashu', 'Despite the shocking news the gang have just discovered, Aang insists on trying to find Bumi within Omashu''s borders, even with the dangers that will await him and his friends if his real identity is discovered.  Meanwhile Azula goes in search of old friends to help her with her mission.', 25, '2006-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 4, 'The Swamp', 'A mysterious tornado pulls the kids into a supernatural swamp where Katara, Sokka and Aang have mysterious visions. Meanwhile, Momo and Appa are chased by rogue swamp dwellers and only Aang and the gang can save them.', 24, '2006-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 5, 'Avatar Day', 'Aang and the gang discover an Earth town that celebrates something called "Avatar Day." But when they get there and learn the festival is of "anti-Avatar" sentiment and Aang is put on trial for a crime a past incarnation allegedly committed. Looking to clear the Avatar''s good name, Katara and Sokka venture back to a familiar  place to gather evidence and discover the truth.', 25, '2006-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 6, 'The Blind Bandit', 'In search for an earthbending teacher for Aang, the kids go to an underground earthbending tournament called Earth Rumble 6, where they encounter Toph, a blind but powerful earthbending girl. After seeing her unique style of earthbending, Aang wants Toph to become his teacher, but there are complications with Toph''s family.', 25, '2006-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 7, 'Zuko Alone', 'Zuko travels by himself to an Earth Kingdom town where he meets a local boy. The two almost become friends, while Zuko suffers from flashbacks of his past.', 25, '2006-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 8, 'The Chase', 'Tired from trying to escape a machine that shows up every time they try to sleep, Aang and the gang have to escape Azula and her team, but their exhaustion leads to a tight situation. Meanwhile, Zuko must deal with something personal, and Iroh bonds with an unlikely individual.', 25, '2006-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 9, 'Bitter Work', 'Toph''s instructing abilities come into question when Aang cannot seem to overcome a block that keeps him from earthbending. Sokka gets himself in a jam, while befriending what was, moments before, his next meal, and Iroh and Zuko begin training utilizing new philosophies and methods that originate from the other elements.', 25, '2006-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 10, 'The Library', 'When Aang and his friends find a professor who knows of a library that contains information about the world, Sokka decides to go there to hopefully find some information to use against the Fire Nation. The library is guarded by the knowledge spirit, Wan Shi Tong, who unfortunately doesn''t welcome humans into his library, because he believes they only seek information for evil purposes.', 25, '2006-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 11, 'The Desert', 'Aang searches for Appa while Katara struggles to keep everyone together to survive in the vast desert. Meanwhile, Iroh and Zuko seek help from an ancient secret society.', 25, '2006-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 12, 'The Serpent''s Pass', 'When Aang and the gang meet up with a group of refugees, they tell the gang where they can get on a ferry to Ba Sing Se. But after a series of events they have to take a deadly route called the serpent''s pass with the help of an old friend, Suki. Meanwhile, Zuko and Iroh meet up with a boy named Jet and his freedom fighters.', 25, '2006-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 13, 'The Drill', 'Having made it to the outer wall of Ba Sing Se, the kids confront a Fire Nation army that is driving a massive Fire Nation drill, which poses an imminent threat to the last Earth Kingdom stronghold. Meanwhile, Zuko and Iroh make crucial mistakes which begin to attract Jet''s suspicions.', 25, '2006-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 14, 'City of Walls and Secrets', 'Having finally made it into Ba Sing Se, the kids are given a house in the upper ring. The kids are anxious to tell the Earth King their plan but there are complications. Meanwhile, still convinced that Iroh and Zuko may be Fire Nation, Jet decides to take matters into his own hands and do whatever it takes to get the refugees to reveal their true nature.', 25, '2006-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 15, 'The Tales of Ba Sing Se', 'A series of short stories, highlighting different characters and their individual adventures in the city. Tales of Katara and Toph, Iroh, Sokka, Aang, Zuko, and Momo.', 25, '2006-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 16, 'Appa''s Lost Days', 'Appa''s journey from being abducted in the desert to the present is explored.', 25, '2006-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 17, 'Lake Laogai', 'Aang and his friends continue to search for Appa and, unbeknownst to them, they aren''t the only ones looking for him. During their search, the kids meet up with Jet, whom they are understandably reluctant to trust. The kids soon realize that the Dai Li are doing their best to thwart the kids'' efforts to find Appa. Meanwhile, Iroh is offered his own tea shop in the upper ring, and Zuko discovers the avatar is in the city.', 25, '2006-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 18, 'The Earth King', 'The kids battle Long Feng and the Dai Li when they attempt to show the Earth King the vast conspiracy taking place in his city. Zuko becomes seriously ill and has feverish dreams as he faces a spiritual crisis.', 25, '2006-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 19, 'The Guru', 'Aang travels to the Eastern Air temple to receive guidance from Guru Pathik while Sokka is reunited with his long-lost father. Meanwhile, Azula has something diabolical in store for her enemies in the Earth Kingdom, including Zuko and Iroh.', 25, '2006-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 2), 20, 'The Crossroads of Destiny', 'Everyone races against time to stop Azula''s sinister plan. Zuko finds companionship in an unlikely source. Aang''s destiny hangs in the balance—and so does Zuko''s, as Iroh tells him it''s time to make a choice.', 22, '2006-12-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')), 3, 'Book Three: Fire', 'Aang wakes up from his battle with Azula to discover that Ba Sing Se has fallen and the world thinks he''s dead. So he and his friends set off undercover across the Fire Nation to find Fire Lord Ozai before the Day of Black Sun. Prince Zuko returns home as the triumphant son, but soon finds the honor he so greatly craved from his father is worthless. New alliances are formed and Team Avatar forges a new plan to stop the Fire Lord. But will they find him in time?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 1, 'The Awakening', 'Aang awakens to find himself aboard a captured Fire Nation ship with a full head of hair and sustaining serious injuries from the previous battle for Ba Sing Se. At his side are Katara, Sokka, and their father Hakoda who recount the events that led the four to the ship and contemplate their next move. Aang struggles to fight his own desire to face the Fire Lord before he is ready. Meanwhile, Zuko deals with his own issues as he makes his long-awaited journey home, with the fear of his father''s rejection hanging over his head.', 25, '2007-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 2, 'The Headband', 'To better blend in as Fire Nation citizens, Aang enrolls in a Fire Nation school, giving himself an opportunity to learn more about the Nation and to enjoy life as a normal kid for the first time since he discovered he was the Avatar. Meanwhile Zuko, growing more and more paranoid about the Avatar''s false demise, brings himself to confront the imprisoned Iroh.', 25, '2007-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 3, 'The Painted Lady', 'When the gang arrives at a suffering fishing village, a mysterious spirit appears to help the villagers.', 25, '2007-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 4, 'Sokka''s Master', 'Feeling as though he isn''t contributing enough to the group, Sokka seeks out an elusive swordsmaster from whom he can learn the ways of the blade.', 25, '2007-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 5, 'The Beach', 'Zuko, Azula, Mai and Ty Lee take a vacation to Ember Island. In the process, they come to learn more about themselves and each other as well as their desires for the future. Elsewhere, Aang and the others face off against a new adversary.', 25, '2007-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 6, 'The Avatar and the Firelord', 'The tale of Avatar Roku and Fire Lord Sozin is revealed to Aang and Zuko by different sources.  Both learn about themselves and are shown the origins of the war.', 24, '2007-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 7, 'The Runaway', 'When Katara expresses her disapproval of Toph''s new way to make quick cash, the group finds her too motherly and tension grows between Katara and Toph. When Katara finally decides to participate in this scam to disprove Toph''s accusations, they are left vulnerable and are forced to face the dire consequences.', 24, '2007-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 8, 'The Puppetmaster', 'The gang investigates the bizarre disappearances taking place within an eerie town.', 25, '2007-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 9, 'Nightmares and Daydreams', 'Four days prior the invasion, Aang becomes nervous over his soon-to-come confrontation with the Fire Lord. His anxiety gets the better of him as he begins to suffer from outrageous nightmares and hallucinations. Meanwhile, Zuko becomes upset to learn that he was not informed about a war meeting.', 25, '2007-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 10, 'The Day of Black Sun: The Invasion (1)', 'The day of the eclipse has arrived, and the invasion force gathers together to make last preparations. They infiltrate the island and the battle begins. Meanwhile, Aang searches for the Fire Lord.', 24, '2007-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 11, 'The Day of Black Sun: The Eclipse (2)', 'As the invasion force fights their way to the Fire Nation capital, the kids help Aang find the Fire Lord in time for the eclipse. Zuko confronts his father with shocking news.', 24, '2007-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 12, 'The Western Air Temple', 'Aang and the group arrive at the Western Air Temple, with Zuko in pursuit. Zuko wishes to help the Avatar end the war by teaching him firebending.', 25, '2008-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 13, 'The Firebending Masters', 'While teaching Aang firebending, Zuko realizes that he has lost all his firebending skills. To regain his powers, Zuko and Aang must seek the original source of firebending within the ruins of a lost civilization.', 25, '2008-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 14, 'The Boiling Rock (1)', 'Sokka wants to break his father out of jail and asks Zuko for information on Fire Nation prisons. Sokka and Zuko head for the Boiling Rock, a prison located in the middle of a volcano, to rescue Sokka''s father.', 24, '2008-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 15, 'The Boiling Rock (2)', 'Zuko and Sokka make new plans to break out of the prison with Suki, Sokka''s father and some others while a shocking twist leaves Azula none too happy with her two closest friends.', 23, '2008-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 16, 'The Southern Raiders', 'Katara decides to confront the Fire Nation soldier responsible for her mother''s death. Aang tries to talk her out of it, but she doesn''t listen.', 25, '2008-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 17, 'The Ember Island Players', 'A play recounting the gang''s adventures does not sit well with Aang and his friends, except for Toph who enjoys it very much. Meanwhile, Aang confesses his love to Katara, but the response is ambiguous.', 25, '2008-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 18, 'Sozin''s Comet: The Phoenix King (1)', 'Aang struggles to decide whether or not he has to kill the Fire Lord and, during the night, is drawn toward an island which disappears before morning. Zuko leads the rest of the group to the Earth Kingdom to meet a tracker whom they hope can find Aang. The Fire Lord crowns himself Phoenix King and Aang awakens on the island not knowing where he is.', 23, '2008-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 19, 'Sozin''s Comet: The Old Masters (2)', 'While on the island, Aang seeks guidance from his past lives, but is not pleased with what he is told. The island, in fact, turns out to be a lion turtle from which Aang is given the guidance he had been seeking. Meanwhile, after the tracker is unable to track Aang, the rest of the group decide they must find Iroh. While tracking him down, the group meets up with The Order of the White Lotus, a group that transcends the division of the four nations.', 23, '2008-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 20, 'Sozin''s Comet: Into the Inferno (3)', 'Sokka, Suki, and Toph try to stop the Fire Nation''s air fleet. Meanwhile, Zuko and Azula duel in an Agni Kai and Aang confronts the Fire Lord.', 23, '2008-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0417299')) AND numero_temporada = 3), 21, 'Sozin''s Comet: Avatar Aang (4)', 'Aang is on the offensive after getting hit in the back of his scar and triggering the Avatar State. Meanwhile, after Zuko seems to have the upper hand against Azula, Katara is forced to join the fight when Azula resorts to desperate measures.', 24, '2008-07-19');
