INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0420294', 'The Texas Chainsaw Massacre: The Beginning', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0509448'), 'PELICULA', 'Before being sent to serve in Vietnam, two brothers and their girlfriends take one last road trip, but when they get into an accident, a terrifying experience will take them to a secluded house of horrors, with a chainsaw-wielding killer.', '2006-01-01', 'https://m.media-amazon.com/images/M/MV5BZjBmZjYyMDktODIzZi00NDM3LWIxZDktYzkxZGJhNTk5MGEzXkEyXkFqcGc@._V1_.jpg');
