INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 1, 'Tempestuous Temperaments', 'Fuu is a part-time teahouse worker whose life changes forever when two vagabond warriors, Mugen and Jin, stumble into her place of business and end up in hot water with the local magistrate.', 24, '2004-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 2, 'Redeye Reprisal', 'When Mugen wounds an enemy''s arm, it sets off a dangerous chain reaction. Fuu is kidnapped, and two deadly assassins are dispatched to make short work of vagabond Mugen and ronin Jin.', 24, '2004-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 3, 'Hellhounds for Hire (1)', 'After leaving the domineering Fuu behind, Mugen and Jin arrive in town. Once there, it''s not long before they''re hired on as bodyguards by the two clans that run the city.', 24, '2004-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 4, 'Hellhounds for Hire (2)', 'The paths Mugen, Jin, and Fuu follow bring them together again, but their reunion is put on hold when an untimely mistake intensifies the struggle between two clans fighting for control of one city.', 24, '2004-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 5, 'Artistic Anarchy', 'An unknown artist hires Fuu for a private modeling session, but his passion for painting turns out to be a front for a human trafficking ring. Will Mugen crack the case in time to save Fuu from a life of slavery?', 24, '2004-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 6, 'Stranger Searching', 'Mugen and Jin loses their weapons and their appetites - in an rice-eating contest, and the only way to get them back is by posing as tour guides for a mysterious European with a penchant for man love!', 24, '2004-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 7, 'A Risky Racket', 'Fuu gets caught in a web of deception when she falls for prolific pickpocket with a heart of gold. But when her sticky-fingered friend slips his hands into the wrong pocket, he could be headed for a beat down.', 24, '2004-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 8, 'The Art of Altercation', 'A cocky sword-slinger with a crush on Fuu dishes the dirt on Jin''s disgraceful past. If the renegade ronin wants to restore his good name, he''ll need to get his glasses out of hock and make ready for a throw down!', 24, '2004-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 9, 'Beatbox Bandits', 'The crew is headed for the gallows after getting caught flashing fake travel permits, but Mugen can win back their freedom by out hustling a deranged gang of warrior priests.', 24, '2004-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 10, 'Lethal Lunacy', 'Mugen takes his training to the next level in preparation for a full moon death match with a killer who uses a deadly armor-piercing attack to soak the streets in the blood of his victims.', 24, '2004-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 11, 'Gamblers and Gallantry', 'Jin falls in love with a suicidal beauty whose husband sold her into slavery, and Mugen tries to make his fortune in the cutthroat world of beetle sumo wrestling.', 24, '2004-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 12, 'The Disorder Diaries', 'When Mugen and Jin do the unthinkable and read Fuu''s diary, they are treated to a riveting recap of all their greatest misadventures.', 24, '2004-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 13, 'Misguided Miscreants (1)', 'When Mugen crosses paths with a face his past, he reluctantly signs on for a heist that could land him a fortune in stolen gold. Unfortunately for him, some old friends aren''t to be trusted.', 24, '2004-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 14, 'Misguided Miscreants (2)', 'Mugen - double-crossed and headed for the bottom of the ocean - flashes back to his life before he died for the first time. Back on land, a pretty young thing convinces Jin to brandish his blades in the name of vengeance.', 24, '2004-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 15, 'Bogus Booty', 'Mugen goes under the covers with an undercover investigator who''s out to put the smack down on a murderous ring of counterfeiters. Will he finally get the booty he''s after?', 24, '2004-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 16, 'Lullabies of the Lost (1)', 'Tempers flare, harsh words are exchanged, and the gang splinters, each member marching off in a different direction. Mugen and Jin wander into some swordplay, and Fuu ends up at the bottom of a river.', 24, '2004-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 17, 'Lullabies of the Lost (2)', 'Jin and Fuu reunite, only to be attacked by a vengeance-driven samurai from Jin''s old life. Meanwhile, Mugen takes aim at an arrow-slinging madman who''s at the top of everyone''s most wanted list.', 24, '2004-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 18, 'War of the Words', 'Mugen learns his letters from a sake-guzzling maniac, Jin makes good on a promise from many years ago, and Fuu sparks a jealous showdown between two bickering graffiti artists.', 24, '2005-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 19, 'Unholy Union', 'Fuu harbors a female fugitive who''s on the run from a bogus, gun-slinging missionary. The new girl is trouble, no doubt about it, but she may hold the finding the samurai who smells like sunflowers.', 24, '2005-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 20, 'Elegy of Entrapment (1)', 'Mugen defends the honor of beautiful blind songstress, but when the when the trio of wanderers becomes a quartet, Fuu will be faced with an impossible decision.', 24, '2005-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 21, 'Elegy of Entrapment (2)', 'Mugen''s has his own deadly run-in with the same blind beauty that sent Jin plummeting towards a gruesome end. Who is this seductive assassin, and why is she targeting the Champloo crew?', 24, '2005-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 22, 'Cosmic Collisions', 'Jin, Mugen, and Fuu fall into the clutches of a hoard of rotting zombie treasure hunters. Next, they get blown to oblivion by an asteroid. Or maybe they just ate some bad mushrooms.', 24, '2005-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 23, 'Baseball Blues', 'Mugen''s failed attempt at a dine-and-dash restaurant caper lands him in hot water with the locals. Redemption lies with leading the town''s baseball team to a victory over the arrogant and unwelcome Americans.', 24, '2005-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 24, 'Evanescent Encounter (1)', 'As the crew draws ever nearer their final destination, Fuu makes a bold and startling decision. Elsewhere, unnamed adversaries pursue the travelling trio.', 24, '2005-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 25, 'Evanescent Encounter (2)', 'Jin enters a bloody grudge match with the man responsible for the ruin of his rep. Meanwhile, Mugen races to save Fuu from the clutches of a sadistic madman bent on bloodshed.', 24, '2005-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0423731')) AND numero_temporada = 1), 26, 'Evanescent Encounter (3)', 'Old scores are finally settled as Mugen, Jin, and Fuu finally come face to face with the ghosts of their respective pasts.', 24, '2005-03-19');
