INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0427309', 'The Great Debaters', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0000243'), 'PELICULA', 'A drama based on the true story of Melvin B. Tolson, a professor at Wiley College Texas. In 1935, he inspired students to form the school''s first debate team, which went on to challenge Harvard in the national championship.', '2007-01-01', 'https://m.media-amazon.com/images/M/MV5BMTQxMDc1NzkwMF5BMl5BanBnXkFtZTcwMDI5MjU1MQ@@._V1_.jpg');
