INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 1, 'Season 1', 'Meredith Grey, the daughter of the once-renowned surgeon Ellis Grey, becomes an intern at the Seattle Grace Hospital. She meets fellow interns Cristina Yang, Isobel "Izzie" Stevens, George O''Malley and Alex Karev who become her closest friends during the intern program. She finds herself working with renowned surgeons such as the heart surgeon Preston Burke and Richard Webber, chief of surgery and old friend of her mother. She finds herself working under her one night stand and famous neurosurgeon Derek Shepherd and working with her resident Dr. Miranda Bailey also known as The Nazi.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 1, 'A Hard Day''s Night', 'Meet Meredith Grey. Daughter of famous surgeon Ellis Grey and currently recovering from a one-night stand. She shoos away her evening''s companion, saying she''ll be late for her first day of work. She is a first year intern at Seattle Grace Hospital and is working alongside some colorful characters. Cristina Yang is a highly competitive Stanford graduate who befriends Meredith. George O''Malley is a quirky warm hearted man who learns a lesson or two on his first day. Izzie Stevens is a former model who doesn''t get any special treatment on her first day. And Alex Karev is an arrogant jerk who misdiagnoses a patient on his first shift. Overseeing them is Miranda Bailey, (not-so-) affectionately dubbed ''The Nazi''. Meredith also gets a surprise when she realizes that her friend from the night before is a co-worker, and even worse, her boss.', 43, '2005-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 2, 'The First Cut is the Deepest', 'The surgical staff tries to be optimistic as a young woman clings to life after a brutal attack. Meanwhile Meredith puts her career on the line to save a newborn in the hospital nursery, and the other interns learn that it takes more than just medical knowledge to be good at their jobs.', 43, '2005-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 3, 'Winning a Battle, Losing the War', 'A bike race injures several pedestrians as well as well as participants.  One pedestrian is left brain dead.  Christina and Issie wish to use his organs for organ donation but with Christina''s detachment and Issie''s ever hopeful attitude that the man will recover, they will find the organ harvesting process an emotional one.  Preston faces feelings of his dislike of organ harvesting - as a surgeon, he likes saving lives; harvesting organs doesn''t save the person''s life.  George deals with Mac, a friend of the chief, who won''t stop flirting with him.  He is in need of a new liver.   Meredith is fed up with Alex showing off as she continues trying to push Derek away.  She also is reaching the limits of Issie''s sunshine and George''s politeness as she goes on living with them.  Then there is their desire to see Meredith''s mother''s medical tapes.  Getting through the day, Meredith realizes the keys to winning the race.', 43, '2005-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 4, 'No Man''s Land', 'While George is feeling a little less masculine because of the way Izzie and Meredith have been treating him (like a sister), Izzie is assigned to a patient about to loose all of his masculinity. Cristina, true to her competitive spirit, shows up early and assigns herself to an ill woman, who happens to have been Meredith''s moms scrub nurse. Alex, meanwhile, is busying himself copying and pasting pictures of Izzie''s racy magazine spread all over the interns'' locker room. And while Meredith is trying to cope with her mother''s Alzheimer''s, Derek treats a patient who has managed to get nails stuck in his head.', 43, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 5, 'Shake Your Groove Thing', 'Meredith realizes that she must take on a lot more responsibility when she is told that her mother needs to sign over all of her assets to her. As Izzie prepares to have a party for her boyfriend Hank (the scale of which is unknown to Meredith), Meredith has her first heart surgery.  During the surgery she fears that she has fallen asleep and damaged the patient''s heart. Meanwhile, Cristina and Burke hit it off. At the party, Meredith and Derek get caught together by Dr. Bailey.', 43, '2005-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 6, 'If Tomorrow Never Comes', 'Izzie tries to get George to find the courage to ask Meredith out.   All of the interns are in awe when a woman comes in with a record breaking tumor, but it is so far advanced that the woman''s prognosis is not good.   Now that Bailey knows about Meredith and Derek''s affair, their jobs are in jeopardy, and she advises Meredith to end it.   Meanwhile, Cristina and Burke''s secret relationship is also getting more complicated...', 43, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 7, 'The Self-Destruct Button', 'Derek and Meredith try (unsuccessfully) to be discreet as they spend the night together at Meredith''s house, but their haggard appearance speaks volumes to everyone - including Bailey, who warns Meredith to end the relationship. Meanwhile George suspects an anesthesiologist of drinking on the job but is reluctant to speak up about it, Alex treats a former competitor who now finds honor in self-mutilation, Izzie has to deal with a patient who won''t let go of his girlfriend - literally, and Cristina seems to be battling a case of the flu.', 43, '2005-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 8, 'Save Me', 'Meredith grows increasingly dissatisfied with the unknown details of Derek''s life. Meanwhile, Alex treats Devo, a patient whose religious beliefs jeopardize her chances for recovery; Izzie contemplates reconnecting with her estranged mother; Zoey, a pregnant woman in her 40s who''s been diagnosed with cancer, disagrees with Cristina''s medical advice; and the interns are mystified by Cable, a patient who''s being treated for seizures and who thinks he''s psychic.', 43, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 1), 9, 'Who''s Zoomin'' Who?', 'A sexually transmitted disease breaks out and affects several members of the hospital staff. Chief Webber promptly calls a meeting. Meanwhile, the chief reluctantly tells Dr. Derek Shepherd about his own medical concerns. Izzie and Cristina worry about a patient''s wife and daughter who can''t agree on his care. Burke treats his college buddy Bill, whose medical diagnosis raises some questions regarding his wife''s actions. Then just as Meredith and Derek grow more intimate, a surprise is revealed.', 43, '2005-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 2, 'Season 2', 'The season continued to focus on the surgical residency of five young interns as they try to balance to the challenges of their competitive careers, with the difficulties that determine their personal lives. It was set in the fictional Seattle Grace Hospital, located in the city of Seattle, Washington. Whereas the first season put the emphasis mainly on the unexpected impact the surgical field has on the main characters, the second one provides a detailed perspective on the personal background of each character, focusing on the consequences that their decisions have on their careers. Throughout the season, new story lines were introduced, including the love triangle between Meredith Grey, Derek Shepherd, and Addison Montgomery, the main arc of the season. Also heavily developed was the story line involving Izzie Stevens'' relationship with patient Denny Duquette, which resulted in critical acclaim and positive fan response.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 1, 'Raindrops Keep Falling On My Head', 'Picks up where the last episode left off. Meredith attempts to work with Addison Shepard. George is pimped out to relay the hospital gossip back to Webber. Meredith and Cristina relate at Emerald City Bar about what dating their respective attendings is like. Cristina ponders her relationship with Burke while trying to make a decision. Meredith is devastated by the latest blow to her love life. Meanwhile, Joe the bartender collapses.', 43, '2005-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 2, 'Enough is Enough (No More Tears)', 'There''s tension between Meredith and Addison. We find out why Derek and Addison aren''t together. Bailey puts George on an impossible case. The rest of the interns operate on a family that was just in a car accident.', 43, '2005-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 3, 'Make Me Lose Control', 'Cristina and Meredith try to figure out if Cristina should tell Burke that she''s pregnant right before Cristina faces an emergency. Alex and Izzie get closer while Meredith''s mother gets too close.', 43, '2005-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 4, 'Deny, Deny, Deny', 'As Cristina tries to recover, she proves to be a very difficult patient, and a visit from her mother doesn''t improve her demeanor any. And Meredith''s mother, Dr. Ellis Grey, has the hospital staff running in circles.', 43, '2005-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 5, 'Bring the Pain', 'Cristina goes right back to working right after being discharged. Izzie isn''t talking to Alex. Derek and Meredith treat a patient. George and Alex get stuck in an elevator.', 43, '2005-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 6, 'Into You Like a Train', 'Train Wreck victims come to Seattle Grace and all staff gets called in. Everyone deals with really weird cases. Except Addison and Izzie. They work with a woman who is pregnant.', 43, '2005-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 7, 'Something to Talk About', 'Cristina, Izzie and Meredith take care of Shane, a man who appears to be crazy and claims that he is pregnant. Shane''s case induces a spreading fascination among the staff. George relates to a patient''s husband.', 43, '2005-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 8, 'Let It Be', 'Meredith tries to avoid the Shepherds. Cristina and Burke go out on a date and end up getting caught up in their jobs. Derek asks Meredith not to ignore him until Addison comes walking around the corner.', 43, '2005-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 9, 'Thanks for the Memories', 'It''s Thanksgiving at Seattle Grace Hospital but the holiday''s festivites are less than in order. Meredith and Derek try to counsel a family after their relative has had a seriously traumatic accident.', 43, '2005-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 10, 'Much Too Much', 'Dorie Russell is waiting for quintuplets, all 5 girls. Her husband seems more concerned than she is but she is set to bring her babies to their term of 36 weeks. All the departments are on call for the quintuplets as three of them have developped problems of different kinds.    Meredith last night''s stand shows up at the hospital with priapism and they need to call Derek Sheperd for a consult which puts Meredith in a very embarassing position. Alex and Derek must take care of a patient who has a tumor inducing thirst as a side effect.   On the love side, Alex and Izzie are having some slight sexual problems, while Meredith goes on adding one night stands and Cristina is thrown off course by being "keyed."', 43, '2005-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 11, 'Owner of a Lonely Heart', 'Cristina Yang has little sympathy for Constance Ferguson (special guest star Rosanna Arquette), a prison inmate who jeopardizes her health just to get out of solitary confinement. Meanwhile the interns all keep careful watch on the family of premature quintuplets with a variety of serious health challenges, Izzie''s anger at Alex reaches boiling point, and Dr. Addison Shepherd decides to teach Izzie a very painful lesson.', 43, '2005-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 12, 'Grandma Got Run Over By a Reindeer', 'The holiday season has started but not everyone is in a festive mood. This is Alex''s last day in the hospital unless he passes his boards practical exam the next day, thus everyone helps him to review so that he succeeds. However, Izzie is not happy about the others helping him and Meredith has to remind her of the true spirit of the Christmas holiday. Justin is in need of a new heart. One is available but he does not want it because he does not believe Santa gave it to him as his mother said. Cristina and Burke, both handling Justin''s case, have opposing views on the matter due to their different stances on religion. Despite a reconciliation with his wife, Derek isn''t in a festive mood. George has a simple case of a woman who has a bleeding ulcer, he realizes that the ulcer is caused by her entourage but fails to keep them away, with the consequence that it perforates.', 43, '2005-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 13, 'Begin the Begin', 'Cristina is bothered by a new year''s mandatory work limit. Izzie patient, Denny Duquette, wants two things: 1. a heart transplant, 2. Izzie. Addison detests Derek''s trailer, Derek visits Meredith''s mom, George treats a young teen hermaphrodite frustrated by her  pre-pubescence. Other news includes patients doing uncanny things and relationship havoc being wrecked between the doctors, as per usual.', 43, '2006-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 14, 'Tell Me Sweet Little Lies', 'Meredith and Cristina lie to each other and themselves about their relationships with McDreamy and Burke, respectively.  George is given a hard task to expel a discharged and defiant woman from the hospital. Alex learns his fate after re-taking his medical exams. At the same time Izzie is trying to stop Alex from making stupid decisions when a patient that doesn''t speak English is lied to by her coach. George, Cristina, and Alex compete in a hot dog eating competition.', 43, '2006-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 15, 'Break on Through', 'All the nurses at Seattle Grace Hospital go on strike, leaving the doctors to fend for themselves. George refuses to cross the picket line and finally joins the nurses on their strike while Alex, Cristina, Izzie and Meredith meets Bailey''s stand-in: Dr. Cindy Aaron, the complete opposite of Miranda Bailey. Izzie agrees to work on a difficult pregnancy case with Addison, while Cristina and Alex are in the pit attending to a young married woman with a real bad case of rash. Meredith happens on an old woman that she needs to intubate and then learns she was DNR.', 43, '2006-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 16, 'It''s the End of the World', 'An explosive case arrives at the O.R. that might endanger all the lives of the people working there, which leads Dr. Burke to declare a "Code Black" for the hospital. Bailey worries where her husband is as she is in labor.  Also Izzie and Alex may be creating some heat.', 43, '2006-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 17, 'As We Know It', 'Derek is still operating when he finds out about Meredith''s current situation. Meredith is freaking out about her situation. Webber and Bailey are dealing with medical health issues. Cristina and Izzie have their own issues to deal with because of Meredith''s situation. Addison freaks out when George tries to find a solution to Bailey''s impromtu postponement. Overall, Seattle Grace Hospital is still under code black and the situation is getting worse.', 43, '2006-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 18, 'Yesterday', 'Derek and Addison''s relationship is rocked to the core when a former friend comes to Seattle Grace and his presence promises to shake things up for a few members of the staff. Burke and Cristina''s relationship is affected when one of her secrets is outted. Alex and Izzie are having similar reactions to their closet scenes during the Code Black crisis. On top of this a cocky doctor shows up to piss Derek off in all kinds of ways. A patient is suffering from constant orgasms and her condition sparks interesting conversations among the staff. George is trying to figure out how to get Meredith to see him as more than just a housemate. Another patient, that Derek is treating, is dealing with a rare disorder and needs his parents support and understanding. Burke has a patient who inspires him to talk to Meredith and Cristina about doing what they say they will. Meanwhile, Meredith learns more about her family (in fact maybe more than she may have wanted to know) through her parents.', 43, '2006-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 19, 'What Have I Done to Deserve This?', 'Meredith and George are experiencing  morning-after tension at home and at work and it has the rest of the doctors wondering what''s up. Derek and Addison are experiencing their own version of morning-after tension as a result of Mark''s visit to Seattle. Bailey, returning the favor that was done for her during the Code Black situation, must treat Addison for a specific feminine problem. Izzie and Alex are making headway in their relationship until Denny Duquette comes back. Soon Alex is not-so-oddly jealous of the attention Izzie is showing to Denny. Someone finds comfort in confiding in a patient who is going through an ordeal of his own. Burke deals with a patient and gets to observe the patient''s unstable relationship with his fiancée.', 43, '2006-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 20, 'Band-Aid Covers the Bullet Hole', 'The doctors are up to their necks in their usual levels of drama. Meredith is dealing with the backlash of sleeping with George, George and Burke are bonding in ways that bother and creep out Cristina, Cristina gets stuck on diaper duty, Bailey gets involved in a case even though she''s still supposed to be on maternity leave, Addison and Derek have a talk, and Izzie is still flaking on Alex for Denny Duquette, the heart patient who didn''t get a heart. In the patients-of-the-week department we''ve got a very pregnant woman, a hockey player who desires medically unnessasary amputation, and a woman with a fork in her neck who happens to be dying and has a struggling marriage.', 43, '2006-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 21, 'Superstition', 'After a series of deaths at the hospital some of the staff become very superstitious. Izzie worries about Denny and gets confronted by Alex.  A patient with OCD drives Cristina crazy. Derek and Addison discuss their relationships with Meredith. Richard treats a friend from 17 years ago who reveals a secret about a dark time in his past that involves Ellis. George gets an earful about the women he''s not talking to. Burke and Cristina argue about kicking George out.', 43, '2006-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 22, 'The Name of the Game', 'Meredith and Izzie take up knitting. Derek operates on Andrew, a spelling bee champ with a serious head injury. Bailey gets in on Andrew''s surgery because she''s worried that her coworkers won''t recognize her Nazi-status now that she''s a mother. Addison''s patient has an unborn baby with medical issues. After Alex fails to bite his tongue when a terminal patient routinely lies to her daughter about her health he gets a lesson in bedside manners from Burke. George also begins to overstay his welcome at Burke''s apartment after Callie visits him. Meredith has more confusing and uncomfortable encounters with members of her family. One of the female doctors meets a veterinarian named Finn. Izzie flirts with Denny and they play more naughty-Scrabble. Meredith, Derek, and Addison sarcastically take another small stab at their friendships.', 43, '2006-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 23, 'Blues for Sister Someone', 'Addison''s patient is a Catholic mother of seven. Addison gets in trouble after learning that the patient''s husband won''t use contraceptives. Derek treats a divorce attorney who asks if Derek is in need of her services. While Izzie and George are talking about their personal lives they "overhear" part of Derek''s conversation with the divorce attorney who calls herself one of Seattle''s best. Alex gets in trouble with Addison yet again for not being able to keep his mouth shut when other people think he should. A legendary jazz musician refuses to see medical reason. The musician is Burke''s musical hero. Finn makes Meredith breakfast.', 43, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 24, 'Damage Case', 'The staff attends to an intern from another hospital who has short-term memory loss. This intern, named Marshall, also has caused a car accident that involved a married couple, their unborn baby and the woman''s parents who the staff are also treating. The pregnant woman is named Melanie and she will die but her baby may survive. One of the female interns meets up with a woman from her past who is planning on having a family of her own. Cristina is in a good mood although Alex, Izzie, George, and Meredith are having problems but in the meantime Burke hasn''t forgiven Cristina for her late night faux pas. Meredith and Izzie are making fun of Callie''s household habits and George and Callie are having a fight because of George''s roommates. Addison is continuing to own Alex and he''s upset about it. Denny has an outburst at Izzie and Derek has an outburst at Meredith.', 43, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 25, '17 Seconds', 'George and Derek work together, Denny still doesn''t have a heart, and Meredith gets paired with Callie. A 12-week pregnant girl dies in the O.R. and her parents try to keep the baby alive. This causes tension between Derek and Addison. One doctor''s overreaction unites two bickering patients. Finn is still treating Doc for medical problems.', 43, '2006-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 26, 'Deterioration of the Fight or Flight Response', 'Denny needs a heart or else. Izzie and George go crazy trying to get him one. Derek has the life of a friend in his hands as he operates on Burke who has been shot. Burke cannot operate on Denny after Denny''s heart stopped and now Denny is in a dire condition. Cristina gets put in charge of the ER and she is worried about Burke.', 43, '2006-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 2), 27, 'Losing My Religion', 'This episode is the second part of a two-hour season finale.  Richard tries to get information from Addison about a family member''s condition. Callie and George have a talk about his feelings. Meredith and Derek have a talk about Doc.', 43, '2006-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 3, 'Season 3', 'The season followed the continuation of the surgical residency of five young interns, as they experience the demands of the competitive field of medicine, which becomes defining in their personal evolution. Although set in fictional Seattle Grace Hospital, located in Seattle, Washington, filming primarily occurred in Los Angeles, California. Whereas the first season mainly focused on the impact the surgical field has on the main characters, and the second one provided a detailed perspective on the physicians'' private lives, the third season deals with the tough challenges brought by the last phase of the surgeons'' internship, combining the professional motif emphasized in the first season, with the complex personal background used in the second. Through the season, several new storylines are introduced, including the arrival of Dane''s character, Dr. Mark Sloan, conceived and introduced as an antagonizing presence.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 1, 'Time Has Come Today', 'Meredith must make an important choice about which path she wants to follow to determine the future of her love life. While she considers her future she and others have flashbacks of their pasts. Cristina spends time with Burke while he recovers. Webber and Adele have a conversation after he spends the night at the hospital. Everyone attempts to deal with Izzie''s choice to quit. George seeks relationship advice from Derek.', 43, '2006-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 2, 'I Am a Tree', 'Cristina meets Burke''s parents, the interns try to get Izzie''s job back, and Addison takes a day off, a surgical patient may be living her last day. Some of the interns want to know why Bailey won''t talk to Izzie. Meredith tries to decide between Derek and Finn and comes to a decision somewhat. Webber finds out that Callie has been living in the hospital and he confronts her about it.', 43, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 3, 'Sometimes a Fantasy', 'The staff tries to prevent a patient from getting an elective surgery. Cristina tries to help Preston cope with the after effects of his surgery. A patient bails on their surgery. Someone goes to a bed-and breakfast. Alex deals with a patient who has had a high amount of injuries in the past. A man undergoes surgery. Before the surgery his wife was only somewhat supportive, but the results may be too much for her to handle. Izzie tries to go back to the hospital for the first time since Denny died. One child''s constant visits are noted by a nurse. Two foster patients are met with suspicions of child abuse. George and Callie''s relationship moves forward.', 43, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 4, 'What I Am', 'Shawn Sullivan, a car salesman who just had surgery, wants to get back to his routine so he doesn''t lose his renown. Addison works with a pregnant woman named Rebecca who may need a C-section and Addison doubts her medical skills. Rebecca wants to have the baby naturally. Derek and Mark''s opinions clash when the try to decide the course of treatment for a burn victim. Izzie gets surprised. Cristina pushes Burke to get better faster.', 43, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 5, 'Oh, the Guilt', 'Derek learns one of Addison''s secrets. Bailey talks about motherhood and depression to a mother who is set to have cancer surgery and who seems to not care about any decisions concerning the future. A resident is fiercely questioned about the death of a male patient. An ex-couple meet before lunch and get stuck - Meredith and Addison work on their case. Things get awkward when the ex-couple''s daughter, Michelle, arrives at the hospital.', 43, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 6, 'Let the Angels Commit', 'Cristina gets to scrub in on a rare surgery which incites envy. Alex questions his future in plastics. George and Addison work together with Noelle. Noelle is pregnant with twins but one of them is growing slower than the other. Her fiancé has problems of his own. Derek''s sister visits. A patient''s wife makes things hard on the staff since she has made her husband''s health her job. A woman''s sexual exploits are questioned.', 43, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 7, 'Where the Boys Are', 'The men of Seattle Grace go on a camping trip together, Addison and Callie must team up to work on a patient, Meredith assists Sloan with a procedure unlike any she has experienced, and, suspicious of her recent actions at the hospital, Bailey confronts Cristina. A 9-year-old is seen by Cristina after he swallowed Monopoly game pieces. A pregnant 25-year-old, is brought in after she slipped in the shower. She doesn''t want medicine to take away the pain from her injury so not to put her baby''s growth in jeopardy. Doctors take care of Daniel, a man who wants a sexual reassignment surgery and who now goes under the name Donna. Accompanying Daniel is his wife of the past 10 years, who was surprised to see him want that surgery but, after much struggling, decided to stay by his side.', 43, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 8, 'Staring at the Sun', 'George''s father has a serious heart problem that requires surgery and George chooses Burke to do the procedure. Burke doubts himself because he knows the pressure this kind of surgery will put on him, but Cristina believes the team can handle it. Derek works with Meredith on being a couple again and tries work with Addison on more civil terms. A patient has had mutiple plastic surgeries so that his girlfriend will like him more. A mom wants her daughter''s babysitter fired, after she is brought in with multiple injuries, but the girl likes the babysitter more than her mother.', 43, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 9, 'From a Whisper to a Scream', 'A traumatic car accident fills the ER. Izzie pushes the boundaries of her probation. Cristina has a crisis of conscience about her deceptive teamwork with Burke.', 43, '2006-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 10, 'Don''t Stand So Close to Me', 'Recent events strain Burke and Cristina''s relationship. Mark and Derek must work together when two close-knit brothers seek medical help. One of Meredith''s half sisters is admitted to the hospital.', 43, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 11, 'Six Days (1)', 'Meredith discovers that Derek has a problem sleeping while her father comes to visit the hospital. George''s father is moving from one surgery to another. A patient named Heather checks into the hospital. Heather is 17 and has a nasty attitude that results from her medical condition and all the surgeries it has required her to have. Izzie has an emotional breakdown when she tries to hand over something very important to her. George''s family comes to visit to celebrate his father''s surgery. Cristina and Burke are playing Uncle.', 43, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 12, 'Six Days (2)', 'Cristina and Burke continue to play Uncle until one of them gives in. Derek and Meredith are fighting over the reason for their sleepless nights. Meredith tries to talk to her father about his side of the story. There''s tension between Alex and Addison. There is even more tension between Addison and Mark. Addison confides in Callie. Bailey wishes she didn''t have to keep a secret from one of the interns. Callie rushes to be with George after she learns that his dad needs an emergency procedure. Izzie may have found ''some good to do'' with her inheritance.', 43, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 13, 'Great Expectations', 'After the Chief announces his retirement, rumors begin to circulate on his departure and successor. Mark is determined to leave Seattle for good but Meredith accidentally has him stay after letting him know of the open Chief position. Derek is angry at Meredith for causing Mark to stay in Seattle, but soon realizes that she is not the reason he is really angry. The attending physicians at Seattle Grace Hospital fight to get Richard''s attention, but he expresses his disappointment. He also displays his lack of support in Bailey''s plan to create a free medical clinic, but she ultimately goes through with her plan when Izzie offers to spend her entire 8.7 million dollar inheritance on the project. George, devastated after his father''s death, uses sex to overcome his grief, and eventually proposes to Callie. Cristina and Burke still don''t speak to each other, but he breaks the agreement when he proposes to her. Richard endeavors to reunite with his wife, Adele, and decides to retire, only to come home and find his wife with another man.', 43, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 14, 'Wishin'' and Hopin''', 'The race for the Chief''s position is on, and the attending physicians, Derek, Burke, Addison and Mark, compete for Richard''s affections by trying to help out everywhere possible. The Denny Duquette Memorial Clinic is open for business, but only one single patient shows up. Izzie is disappointed in what she invested Denny''s legacy in, and tries to steal patients from the emergency room. Callie and George get back from Las Vegas, announcing their marriage, much to everyone''s disbelief. Izzie is not supportive of their marriage and tries to get George to realize the mistake he has made. Meanwhile, Meredith''s Alzheimer''s-stricken mother, Ellis Grey, experiences a change in her medical condition by becoming lucid for the day. She is disappointed in the mediocrity her daughter has fallen into and begins to despise Derek, blaming him for what happened to the Meredith that used to be "a force of nature". Ellis has to have heart surgery and, despite her wishes, Meredith schedules her upcoming surgery. Richard talks to Ellis and realizes that she is still in love with him, but loses her memory after their talk ends, before Meredith has the chance to tell her how she really feels.', 43, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 15, 'Walk on Water', 'A mass trauma situation, which turns out to be a ferryboat accident, challenges the whole staff of Seattle Grace Hospital. Richard finds difficulty in coping with his separation from his wife and dyes his hair "for the ladies", which becomes an internal joke between Mark, Burke and Derek. Cristina tries to tell Meredith about her upcoming marriage, but doesn''t have the strength to. George promises to find a woman''s son, who has been separated from her at the accident. The woman refuses to go into surgery until she is assured that her son is alive. Izzie has to take care of a man who got stuck between two cars on the ferry, but nobody helps her due to the large number of injured people. Alex rescues a pregnant woman with severe wounds on her face, and promises to take care of her. Meredith looks after a girl who has been separated from her mother after the accident, but accidentally falls into the water and drowns, with nobody but the little girl as a witness.', 43, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 16, 'Drowning on Dry Land', 'Meredith is still underwater, but nobody seems to notice. Her worsening condition makes her rescuing an urgent matter. Derek finds her coat on a man she had helped, and starts looking for her and, much to his shock, the little girl Meredith took care of suggests that she is in the water. Derek saves her, but she is almost dead, due to hypothermia. Izzie has to perform brain surgery on a man stuck between cars, as he begins to experience seizures. She drills holes into his head, perforates his skull and ultimately saves his life before he is rescued and transferred to Seattle Grace Hospital. George lies to the woman whose son he had been looking for, in order to get to surgery, but still doesn''t have any luck in locating him. Alex finds no hope in searching for the pregnant Jane Doe''s family as she undergoes surgery. The interns find out about Meredith''s situation and express their hopelessness. She wakes up in what appears to be limbo and meets her deceased acquaintances.', 43, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 17, 'Some Kind of Miracle', 'Everyone is pushing for Meredith to survive, or in this case to be revived. People are still dealing with the fallout from the ferry disaster. A young man named Lucas is having problems with brain-mouth coordination. Someone else dies.', 43, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 18, 'Scars and Souvenirs', 'The race between the attending physicians for the Chief of Surgery position heats up after a new competitor enters the fray. They soon realize that the new surgeon, Colin Marlow, was Cristina''s professor in medical school and they used to have a long-term relationship. He begins to lie to Burke in order to protect her secret, but is soon faced with the realization that their relationship is on the rocks. George finds out that Callie''s family is rich, but she had previously hidden the fact in order to find out whether George loves her for who she really is. Derek treats his former colleague from New York, and forces her to have surgery for brain cancer in order to save her future, no matter what the post-surgery risks are. Alex continues to work with Jane Doe, whose memory doesn''t seem to come back. He moves in with Meredith and they have a dinner with her father and stepmother. She seems to connect with Susan, but her relationship with Thatcher seems to be irreparable. Izzie wakes up, realizing that she has slept with George while they were both drunk.', 43, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 19, 'My Favorite Mistake', 'In the aftermath of Izzie''s affair with George, he doesn''t seem to remember anything. Callie lets him know that they will be having dinner with her father, but George does not make a good impression, being hung over after last night''s events. Alex helps Jane Doe choose how her face will look like after Mark Sloan performs reconstructive surgery on her. He also gives her a new perspective on how the world will see her from then on. The hospital board begins interviewing the candidates for the Chief''s position, and Colin Marlow intimidates everyone with his ten-year plan. However, after taking advice from Bailey, Mark seems to have convinced the board that he is appropriate for the job, despite continuous efforts from Derek, Burke and Addison, whose careers in the hospital outlast his. Izzie seeks advice from Addison about her affair, telling her sleeping with George felt right, despite him being married.', 43, '2007-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 20, 'Time After Time', 'Colin Marlow continues to try to get in the way of Cristina and Burke''s relationship. The daughter that Izzie gave up for adoption needs something from her. This episode features a pro chess player, a flirtatious woman, and a mother named Mrs. Malone. Mr. and Mrs. Malone haven''t talked to their daugther in a while because of their son-in-law. Someone goes to see a priest.', 43, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 21, 'Desire', 'The attendings vie to be Chief. Two people who haven''t slept together before, will. McSteamy''s 60-day vow of chastity has a conclusion. We meet a boss, his assistant, and his wife. We also get to see someone being treated in the clinic. Derek has more questions about his relationship with Meredith. The chairman of the hospital board is admitted as patient. Callie confronts Izzie about her relationship with George.', 43, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 22, 'The Other Side of This Life (1)', 'Meredith works on her relationship with Susan and Thatcher. Cristina has to deal with her mother and Burke''s. Alex continues to tend to Jane Doe/Ava. Meredith and Derek''s relationship has a problem that needs resolution quick. Addison sees her god-daughter which leads to a job offer outside of Seattle. Derek has to perform surgery. Burke has a reservation about marrying Cristina. Many new people guest star in the course of Addison''s road trip to California. Addison considers moving to be closer to her old med school friends until she discovers that drama she wishes to leave behind isn''t exclusive to Seattle. Her friends who she thought had it all, are divorced. A pregnant woman must discover who the father of her child is.', 43, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 23, 'The Other Side of This Life (2)', 'Meredith works on her relationship with Susan and Thatcher. Cristina has to deal with her mother and Burke''s. Alex continues to tend to Jane Doe/Ava. Meredith and Derek''s relationship has a problem that needs resolution quick. Addison sees her god-daughter which leads to a job offer outside of Seattle. Derek has to perform surgery. Burke has a reservation about marrying Cristina. Many new people guest star in the course of Addison''s road trip to California. Addison considers moving to be closer to her old med school friends until she discovers that drama she wishes to leave behind isn''t exclusive to Seattle. Her friends who she thought had it all, are divorced. A pregnant woman must discover who the father of her child is.', 43, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 24, 'Testing 1-2-3', 'The interns finally take their first year medical exams, the biggest test of their careers, and one of them is ill-prepared. Callie grows more suspicious of George and Izzie. The doctors treat a patient named Dale. Three mountain climbers are treated. Cristina works on her vows. Adele wants Addison to keep a secret from Richard.', 43, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 3), 25, 'Didn''t We Almost Have It All?', 'The mountain climbers lie about the axe in their friend''s head, telling Derek that it accidentally got there. During surgery, he and George discover that it was deliberately put there, and one of the climbers admit that he was trying to "put him out of his misery". Adele is saved after Richard finds her lying in the bathroom and is stabilized, but soon suffers a miscarriage. Richard learns Adele was actually pregnant with his son, not someone she had one night stand with. Bailey is disappointed to see that Callie is the new Chief Resident and begins to question her abilities as a surgeon. Richard chooses Derek as Chief of Surgery, but he refuses, telling him that he isn''t done doing what he does best. Cristina and Burke''s wedding day arrives, but Cristina won''t stay out of the hospital. However, Cristina''s nervousness results in Burke''s realizing that he does not love the real Cristina and leaves her. Meredith and Derek are uncertain about their future and despite Derek admitting that she is the love of his life, they call their relationship over.', 43, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 4, 'Season 4', 'Enter a world of change in the irresistible and unforgettable fourth season of Grey''s Anatomy. Love, lies, and family ties are revealed as the surgeons of Seattle Grace discover that their choices have major unintended consequences. And coupled with the arrival of some very eager new interns, life at the hospital sizzles with more emotion, excitement, and heartbreak than ever before.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 1, 'A Change Is Gonna Come', 'Entering their first year as residents, Meredith Grey, Cristina Yang, Izzie Stevens and Alex Karev now have interns of their own to mentor. Among the new interns are George, forced to repeat his internship after failing his exams, and Lexie Grey, Meredith''s half-sister. Another two new interns will be introduced in this season premiere. And they''ll have their hands full when a three-car accident sends multiple casualties pouring into Seattle Grace. Some of the doctors need to deal with new stressed out interns. A young boy brings his bleeding deer to the hospital in the hope a doctor will save her.', 43, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 2, 'Love/Addiction', 'A patient is in the hospital because they fell asleep in a hazardous situation. A patient''s home laboratory blew up in an apartment building and the victims flood the hospital. Alex investigates the cause of the incident by talking to a really old guy who lived in the building. Jane Burke shows up to deal with what her son left behind. Lexie tries to talk to Meredith. Callie is overwhelmed by her new position while Bailey is searching for things to do.', 43, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 3, 'Let the Truth Sting', 'The doctors meet the world''s oldest intern. Marcy brings in her son Henry because she finds his change in behavior suspicious. A patient named Connie may lose her vocal chords unless Mark and Richard can perform a radical new surgery. George impresses the other interns at work but at home he is trying to deal with his guilt about having sex with Izzie.', 43, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 4, 'The Heart of the Matter', 'A face familiar to one of the year-twos shows up and dredges up issues that were never really dealt with. A teen soccer player needs counseling because of his father and surgery for an injury he sustained while playing the game. Another patient''s, named Courtney, finds out that her cancer is back.', 43, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 5, 'Haunt You Every Day', 'It''s Halloween at Seattle Grace! There may be jokes, pranks, and/or scare tactics. Some of the women form a club based on an experience they all share. A man volunteers for what most of the doctors believe is an unnecessary surgery. One of the patients is in the hospital because they tried to carve a pumpkin in an unconventional manner.', 43, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 6, 'Kung Fu Fighting', 'A patient comes to the ER with a dream and a condition which may prevent him form realizing it. Two patients are competing to win something big. One of them convinces an intern to take their place.', 43, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 7, 'Physical Attraction, Chemical Reaction', 'Izzie and George''s new-founded relationship results in them having bad sex. Callie''s Chief Resident position is taken away from her, and Bailey is the humble replacement. Meredith can barely handle it with Lexie anymore.', 43, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 8, 'Forever Young', 'There has been a bus crash and the patients are in the ER. Meredith and Derek''s relationship gets more complicated when he dates a fellow doctor. Meredith''s dad goes to visit her at the hospital.', 43, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 9, 'Crash Into Me (1)', 'An ambulance crash endangers the lives of the paramedics involved, as Meredith and the Chief work on-site to save them, Bailey treats a patient who refuses her help, and Ava returns for Alex and meets his other girlfriend in the process.', 43, '2007-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 10, 'Crash Into Me (2)', 'Meredith works furiously to save a paramedic trapped in an ambulance; Lexie holds the life of a patient in her hands; Derek must rely on a nurse to save a patient; Bailey struggles to balance her personal life with her work.', 43, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 11, 'Lay Your Hands on Me', 'George has a surprise visitor. Bailey''s family is falling apart. Derek sorts through what kissing Rose means. Meredith discovers something that doesn''t inspire hope or happiness in her. Alex treats a faith healer.', 43, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 12, 'Where The Wild Things Are', 'Time has passed but not much has changed. Sexual angst still runs rampant in the halls of Seattle Grace. Derek and Rose have been dating and Meredith has noticed the activities of her current off-again ex-boyfriend. The doctor''s are in the midst of a competition.', 43, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 13, 'Piece of My Heart', 'Addison visits Seattle Grace because they need skills that only she has. Rebecca/Ava returns with news for Alex. Meredith and Derek''s clinical trial experiences one or two developments.', 43, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 14, 'The Becoming', 'The clinical trial continues to make progress. The anti-McSteamy club creates new initiatives but that isn''t enough to stop one woman from spending time with him. Christina is affected by Burke''s career developments.', 43, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 15, 'Losing My Mind', 'Dr. Wyatt refuses to let Meredith give up on therapy. Alex learns something else about Rebecca. The Chief wants Erica to perform a daring surgery. Christina continues to act strangely.', 43, '2008-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 16, 'Freedom (1)', 'A couple undergoes surgery. Derek and Meredith''s clinical trial gets a second shot from a new patient. Izzie helps Alex. McSteamy hooks up with someone.', 43, '2008-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 4), 17, 'Freedom (2)', 'A couple undergoes surgery. Derek and Meredith''s clinical trial gets a second shot from a new patient. Izzie helps Alex. McSteamy hooks up with someone.', 43, '2008-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 5, 'Season 5', 'Live for the moment. Dive deeper into the lives and loves of "Grey''s Anatomy"! The doctors struggle and thrive as they enter uncharted territories of life. Discover what happens in the on-again, off-again world of Derek and Meredith, and witness the budding relationship between Cristina and Owen, Seattle Grace''s newest doctor.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 1, 'Dream a Little Dream of Me (1)', 'As Meredith and Derek begin to find that their "happily ever after" is anything but easy, Cristina develops a crush on a military doctor who brings in a trauma patient. Meanwhile, the Chief and his staff cope with the news that Seattle Grace is no longer considered a top-tier teaching hospital.', 43, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 2, 'Dream a Little Dream of Me (2)', 'Alex is offended when Izzie talks about how great a man Alex is to Meredith. Derek is stabbed with the scalpel in the palm of his hand by Rose, while the Chief is stunned over Mercy West''s increase in the number of patients, a deadly ice storm ravages Seattle.', 43, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 3, 'Here Comes the Flood', 'When the plumbing springs a leak, chaos breaks out at Seattle Grace as the Chief tries to put in place new teaching methods. Meanwhile, George takes his residency exam; and Derek attempts to get Meredith''s roommates to move out, much to their surprise.', 43, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 4, 'Brave New World', 'Meredith is sent into a state of panic when Derek finds her mother''s diary in the house. Meanwhile, Callie stresses while preparing for her first date with Erica. Later, Cristina stumbles across a part of the hospital no one has ever seen before.', 43, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 5, 'There''s No ''I'' in Team', 'Bailey heads up a "domino procedure" in which each surgery hinges on the one preceding it. Meanwhile, Derek gets sole credit for the brain-tumor study he did with Meredith; Lexie tries to get George to notice her romantically; and Sloan counsels a desperate Callie in the ways of love.', 43, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 6, 'Life During Wartime', 'The chief gives Bailey new power and responsibility. He also gives her a very difficult surgical assignment: remove a girl''s inoperable tumor. Meanwhile, new trauma chief Owen (Kevin McKidd) challenges the attendings'' methods and the residents'' skills.', 43, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 7, 'Rise Up', 'When the Chief makes an announcement that a solo surgery is up as an award, the residents are sent into a frenzy all trying to get an edge over one another. Meanwhile, Derek asks Bailey for advice after Cristina continues to interfere in his relationship with Meredith. Elsewhere, Erica uncovers a shocking connection between a resident and a patient.', 43, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 8, 'These Ties That Bind', 'One of Meredith''s oldest friends, Sadie, becomes an intern at Seattle Grace, but Mer''s friends are less-than-welcoming to her.', 43, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 9, 'In the Midnight Hour', 'Meredith, Cristina and Bailey come to Lexie and Sadie''s rescue when a routine surgery goes horribly wrong, as Owen and Derek treat a man seriously injured while sleepwalking and Mark comforts the sleepwalker''s distraught daughter.', 43, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 10, 'All by Myself', 'Cristina is awarded the first solo surgery among the residents, but she is forced to give it up and choose her replacement; Lexie is impressed when Mark performs a cutting-edge procedure; Callie doesn''t know if Sadie is friendly or flirtatious.', 43, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 11, 'Wish You Were Here', 'Bailey teams with Seattle Grace''s new pediatric surgeon, Dr. Arizona Robbins, to save the life of a young patient near and dear to her heart, as the admittance of a death row inmate at the hospital stirs anger in Derek and further erodes Meredith and Cristina''s friendship; meanwhile, Callie and Sloan work as a team to fight their respective attractions to Sadie and Lexie, and Izzie tells Alex that she''s seeing Denny.', 43, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 12, 'Sympathy for the Devil', 'Derek''s mother, Carolyn, makes a surprise visit to Seattle and meets Meredith for the first time, as Mark tries to conceal his relationship with Lexie from her as well; meanwhile, death row inmate William wishes to donate his organs to Bailey and Arizona''s patient, as Owen and Cristina try to go on their first date.', 43, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 13, 'Stairway to Heaven', 'Bailey grows desperate as a patient''s condition becomes more and more dire. Everyone in the hospital is stepping up to try to find the boy a new organ donor, including Meredith, who considers a death row patient''s wish to die before execution. Meanwhile, an injury leaves Mark in a compromising position in the OR and Cristina awkwardly avoids Owen.', 43, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 14, 'Beat Your Heart Out', 'Now that Derek has the engagement ring, he searches for the perfect way to propose to Meredith, as Lexie demands that Mark go public with their relationship, and Bailey, encouraged by her work on recent cases and by Dr. Dixon, considers a new direction for her medical career.', 43, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 15, 'Before and After', 'Addison, Naomi and Sam rush the ailing Archer to Seattle Grace and reunite with old friends Derek and Mark to help save his life; meanwhile, Izzie employs her fellow doctors in a medical game designed to help teach the interns, and Owen runs into a significant someone from his past', 43, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 16, 'An Honest Mistake', 'Derek''s confidence is shaken like never before as he faces off with Addison over what course is best for their dying pregnant patient; Cristina calls the abilities of a renown surgeon into question after she botches a standard procedure; and Bailey, who has decided to pursue a fellowship in Pediatrics, is appalled by the Chief''s less-than-stellar recommendation letter.', 43, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 17, 'I Will Follow You Into the Dark', 'Derek decides to quit after learning that more of his patients have died than survived; Izzie''s interns make an unsettling discovery about "Patient X."', 43, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 18, 'Stand By Me', 'After his fellow surgeons try and fail to bring Derek back to work, Meredith must summon the strength to convince him. Meanwhile the hospital is abuzz as Mark attempts a rare face transplant surgery. Cristina, at last awarded her first solo surgery, is more focused on the needs of her friends, and Izzie does her best to keep her medical condition a secret.', 43, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 19, 'Elevator Love Letter', 'All eyes are on Derek as he is set to perform his first surgery after his breakdown; attention is also set on Izzie, whose medical condition requires her to undergo a difficult surgery; and Owen has another PTSD episode that injures Cristina and traumatizes both of them, throwing the future of their relationship into question.', 43, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 20, 'Sweet Surrender', 'As she endures aggressive treatment for her cancer, Izzie throws herself into planning Derek and Meredith''s wedding.', 43, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 21, 'No Good at Saying Sorry (One More Chance)', 'As preparations continue for Meredith and Derek''s wedding, Izzie receives a surprise hospital visit from her handful-of-a-mother, Robbie. Meanwhile, a newly sober Thatcher visits his daughters, Meredith and Lexie, in order to make amends, and the Chief and Meredith bitterly fight over a controversial medical case.', 43, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 22, 'What a Difference a Day Makes', 'As Meredith, Derek and all of their friends prepare for the big wedding, a group of college students, injured in a car crash as they were heading to their graduation ceremony, is admitted to the ER. Meanwhile, Izzie fears the worst when she begins experiencing familiar symptoms.', 43, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 23, 'Here''s to Future Days', 'In the first part of the two hour season finale, Izzie spends time with a fellow cancer patient and contemplates whether or not to undergo a risky surgery, as Mark is ready to take his relationship with Lexie to the next level and a patient makes Owen reassess his place at Seattle Grace.', 43, '2009-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 5), 24, 'Now or Never', 'In the second part of the two hour season finale, George delivers stunning news to Bailey, sending shockwaves throughout the hospital, and Izzie''s friends anxiously await her recovery from surgery. Meanwhile Bailey is surprisingly displeased after being accepted into the pediatric fellowship program, and the victim of a near-fatal traffic accident brings the talents of Seattle Grace''s doctors together. This is the second hour of a 2-hour season finale.', 43, '2009-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 6, 'Season 6', 'The season follows the story of surgical interns, residents and their competent mentors, as they experience the difficulties of the competitive careers they have chosen. It is set in the surgical wing of the fictional Seattle Grace Hospital, located in Seattle, Washington. A major storyline of the season is the characters adapting to change, as their beloved co-worker Stevens departed following the breakdown of her marriage, O''Malley died in the season premiere—following his being dragged by a bus, and new cardiothoracic surgeon Teddy Altman is given employment at the hospital. Further storylines include Shepherd being promoted to chief of surgery, Seattle Grace Hospital merging with the neighboring Mercy West —introducing several new doctors, and several physicians lives being placed into danger—when a grieving deceased patient''s husband embarks on a shooting spree at the hospital, seeking revenge for his wife''s death.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 1, 'Good Mourning', 'The hospital staff is left to deal with the aftermath of George''s passing. Hitting the staff hard, they all find unique ways to get through the various stages of grief. George''s mom returns, faced with the difficult task of deciding what to do with his organs.', 43, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 2, 'Goodbye', 'Everyone is struggling after losing one of their own and are turning to any distraction they can find. Meredith and Derek seem to be consummating their marriage anywhere and everywhere, while Cristina and Owen have been instructed to abstain from sex by Dr. Wyatt.', 43, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 3, 'I Always Feel Like Somebody''s Watchin'' Me', 'Several weeks after her near-death experience, a recovering Izzie returns to work. Meanwhile, nervous that there will be layoffs in the hospital in the wake of an announcement from the Chief, the Seattle Grace residents compete to survive the cuts, including Cristina, who attempts to work alongside Arizona in pediatrics. And Bailey and Alex''s patient''s already complex case is further complicated by her schizophrenic son.', 43, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 4, 'Tainted Obligation', 'When Meredith and Lexie''s father, Thatcher, returns to the hospital with a failed liver, it''s up to Meredith to save his life. Meanwhile, Izzie empathizes with a patient riddled with tumors, as Mark, annoyed with Cristina''s competitive zeal, tricks her into assisting on an unusual surgery.', 43, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 5, 'Invasion', 'The residents of Seattle Grace and Mercy West vie for surgeries and their careers as day one of the hospital merger begins. Meanwhile, Arizona stands by an enraged Callie when her father, Mr. Torres, employs a priest to help convince her to date men, and Izzie experiences the brunt of her new surgical competition.', 43, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 6, 'I Saw What I Saw', 'After a burn victim unexpectedly dies in the midst of a chaotic ER, the Chief and board member Jennings interrogate the residents to find the culprit, as all the Mercy West and Seattle Grace resident defends their actions in an effort to save their jobs.', 43, '2009-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 7, 'Give Peace a Chance', 'When Isaac has an inoperable tumor wrapped around his spine, he wants Derek to do the impossible. Derek tests the Chief''s authority when Richard objects to moving forward with the risky surgery.', 43, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 8, 'Invest In Love', 'A generous 25 million donation is offered to Seattle Grace by the parents of Arizonas 10-year-old patient, she finds herself in a conflict of interest when his condition worsens. Cristina tests her boundaries with Owen at the hospital. Alex is left with all of Izzies hospital bills to contend with.', 43, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 9, 'New History', 'Owen recruits Dr. Teddy Altman, a former Iraqi veteran, as the new cardiothoracic surgeon.  Cristina questions her abilities in the E.R. and relationship with Owen.  Izzie returns to Seattle Grace with her high school mentor seeking treatment for his dementia.  Richard''s responsibilities, post-merger, are taking a toll on him.', 43, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 10, 'Holidaze', 'As Thanksgiving, Christmas and New Year''s pass, Miranda gets a visit from her father, William who disapproves of her choices in life. Mark and Lexie cope with an arrival of a woman from his past. Thatcher questions the Chief''s recent behavior as Meredith comes to his defense.', 43, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 11, 'Blink', 'Mark flies Addison to Seattle to help with a difficult procedure on his pregnant daughter, Sloan, Owen questions Teddy''s motives when she assigns Cristina the lead on a complicated surgery, and Derek''s suspicions are raised when the Chief recruits Meredith to assist with a high profile operation on.', 43, '2010-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 12, 'I Like You So Much Better When You''re Naked', 'After learning of Richard''s drinking problem, Derek confronts him for the sake of his friend and the hospital, Izzie returns, hoping to reconcile with Alex, and tensions run high between Teddy, Cristina and Owen in the aftermath of Cristina''s startling confession.', 43, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 13, 'State of Love and Trust', 'As Derek begins his role as interim chief, he faces a potential lawsuit when Bailey and Meredith''s patient awakens from anesthesia mid-surgery. Meanwhile, Teddy refuses to place Cristina on her service, as Arizona tests Alex out in Pediatrics, and Mark refuses to speak to a heartbroken Lexie.', 43, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 14, 'Valentine''s Day Massacre', 'It''s Valentine''s Day, and the doctors must treat dozens of injured people after the roof collapses at a popular romantic restaurant; Derek tries to manage his busy schedule as Chief of Surgery; Meredith wrestles with her new duties as the Chief''s wife; and Mark and Callie team up to convince Sloan to do the right thing for her baby.', 43, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 15, 'The Time Warp', 'In his new role as Chief, Derek restores the hospital lecture series, and Richard, Bailey and Callie present to the group pivotal surgical cases from their pasts Bailey reflects on her first days as a shy resident, Callie looks back on a polio case, and Richard recalls a case in which he and Ellis worked on a patient diagnosed with GRID, a virus later called AIDS.', 43, '2010-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 16, 'Perfect Little Accident', 'When famous surgeon Dr. Harper Avery is rushed to Seattle Grace-Mercy West, the staff is surprised to discover that one of their own is related to this legend, and his unorthodox request for his surgery causes tensions t between Derek and Richard. Meanwhile Callie and Arizona try to help Teddy and Sloan move on from their pasts and find greener pastures.', 43, '2010-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 17, 'Push', 'A patient who needs an extremely difficult surgery comes to Seattle Grace, and it''s Richard and Owen who vie for the opportunity to tackle it. But the decision lies in the hands of Derek, who deems that Owen should take on the surgery, leaving Richard bitter. Meanwhile, Bailey deals with her own personal struggles when she nervously prepares for another date with Ben.', 43, '2010-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 18, 'Suicide is Painless', 'When Teddy''s patient seeks to end treatment and her life, she turns to Hunt for help. The situation triggers Hunt''s memories of his life at war and his past relationship with Teddy. Meanwhile, Callie and Arizona have a difference in opinion on what their future holds, and Richard tries to adjust to his role as a surgeon.', 43, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 19, 'Sympathy for the Parents', 'When Alex''s younger brother, Aaron, shows up at Seattle Grace-Mercy West with a hernia, it''s up to Alex to get Bailey''s approval for his pro bono surgery. Matters are further complicated when Aaron discloses that his family has not heard from Alex since he arrived in Seattle, and parts of Alex''s past long kept secret are revealed to his friends and fellow doctors.', 43, '2010-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 20, 'Hook, Line and Sinner', 'Sloan returns to Mark''s apartment, just as she''s going into labor, and Teddy, Mark and the still-fighting Callie and Arizona are there to help with the birth and to get Mark through his grandson''s pending adoption. Meanwhile Teddy sees Derek''s invitation to illustrious cardiothoracic surgeon Tom Evans'' as a threat to her future employment at the hospital, and the team work on a crab boat captain who has been stabbed with a giant shark hook.', 43, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 21, 'How Insensitive', 'Bailey preps the team with mandatory sensitivity training prior to admitting a 700-pound patient with compounded medical issues, and the case proves to be challenging in every sense of the word. Meanwhile Derek has to come face to face with a former patient''s husband in a wrongful death deposition, and spending time with a heart patient''s daughter opens up some old wounds for Cristina.', 43, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 22, 'Shiny Happy People', 'An elderly patient admitted into the E.R. for a heart condition sees a familiar face, a long lost love who happens to be in the E.R. as well for a fractured arm, and the staff find themselves caught up in their love story. Meanwhile, Karev treats a troubled teenage patient (guest star Demi Lovato) whose parents brought her in for schizophrenia, and Meredith can''t help but tell Cristina about her suspicions of Owen -- which inevitably messes with Cristina''s head.', 43, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 23, 'Sanctuary', 'Seattle Grace Hospital is hit with a crisis like no other in its'' history.', 43, '2010-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 6), 24, 'Death and All His Friends', 'Cristina and Meredith''s surgical skills are put to the ultimate test.', 43, '2010-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 7, 'Season 7', 'Let the healing begin. It''s a year of new beginnings for the medical team of Seattle Grace Hospital as they slowly recover from the tragedy that hit too close to home. New relationships emerge and the strongest commitments are tested. From successes in the operating room to mistakes in the bedroom and all the thrilling drama in between the doctors find a way to survive as long as they lean on one another.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 1, 'With You I''m Born Again', 'In the wake of the shooting at Seattle Grace-Mercy West, the doctors find themselves in a frenzy: Christina and Owen will be getting married, and others are trying to deal with the recent blood bath. Derek is arrested for speeding!', 43, '2010-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 2, 'Shock to the System', 'Meredith finally tells Derek about her pregnancy and miscarriage; during a surgery, Cristina experiences PTSD; Bailey won''t let Alex operate until he has the bullet in his chest removed.', 43, '2010-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 3, 'Superfreak', 'Issues surface when Derek''s estranged sister, Amelia (Caterina Scorsone), visits unexpectedly; Meredith and Derek continue to try to ease Cristina back into surgery.', 43, '2010-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 4, 'Can''t Fight Biology', 'Derek and Meredith visit the obstetrician and receive disturbing news; Lexie notices April and Meredith growing closer; Jackson tries to get ahead in the operating room.', 43, '2010-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 5, 'Almost Grown', 'As part of their training, Seattle Grace''s residents are put in charge; the attending surgeons compete for a million-dollar grant.', 43, '2010-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 6, 'These Arms of Mine', 'A documentary crew visits the hospital six months after the shooting to document the road to recovery for doctors and patients; Meredith helps Cristina put on a brave face for the cameras.', 43, '2010-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 7, 'That''s Me Trying', 'Owen puts the residents through a rigorous trauma certification drill; Cristina is left alone to monitor an ill lung transplant patient.', 43, '2010-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 8, 'Something''s Gotta Give', 'A team of doctors tries to save the life of a political figure from the Middle East; Cristina decides to decorate her new place and throw a housewarming party; Alex shows up late to his first day of rounds with the new pediatrics attending.', 43, '2010-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 9, 'Slow Night, So Long', 'The residents are on their own with the dreaded night shifts while the attendings go out to play to celebrate Derek''s grant for his clinical trial.', 43, '2010-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 10, 'Adrift and at Peace', 'Derek takes Cristina out on a fishing trip; Teddy tries to help a patient who lacks the proper insurance to seek medical treatment.', 43, '2010-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 11, 'Disarm', 'A gunman opens fire at a local college, sending mass casualties to the hospital; Arizona''s return is not warmly received.', 43, '2011-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 12, 'Start Me Up', 'Arizona tries to reconcile with Callie, who has big news to share; Teddy faces an important decision; the residents receive new interns; the Chief makes an announcement.', 43, '2011-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 13, 'Don''t Deceive Me (Please Don''t Go)', 'Derek breaks ground on his Alzheimer''s clinical trial and Meredith can''t help but feel left out; Bailey''s attempt to take the hospital into the age of new media with live tweets from the OR does not go over well with the Chief; and Callie, Mark and Arizona must learn to navigate through the pregnancy together, which starts off with Callie driving her new obstetrician crazy.', 43, '2011-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 14, 'P.Y.T. (Pretty Young Thing)', 'Thatcher Grey, Meredith and Lexie''s father, returns to Seattle Grace with stomach pains and a new, twenty-something tattooed girlfriend, Danielle. Meanwhile, Alex clashes with the new OB, Dr. Lucy Fields, over a patient and Mark places Jackson on his service in exchange for information on Lexie.', 43, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 15, 'Golden Hour', 'Meredith, looking to prove she is Chief Resident material, learns that anything and everything can happen in an hour''s time when she steps up to run the ER for a night; meanwhile, Bailey sneaks off with Eli and gets into a little mischief, and everyone is surprised when the Chief''s wife, Adele, shows up as one of the ER patients.', 43, '2011-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 16, 'Not Responsible', 'Meredith must choose between her fertility treatments and her eyesight when she begins having trouble seeing, Mark makes it clear to Callie and Arizona that he takes his role as father-to-be very seriously, and April discovers there''s more to Dr. Stark than first appears.', 43, '2011-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 17, 'This is How We Do it', 'Richard is desperate for Derek and Meredith to accept Adele into their Alzheimer''s trial, but will Adele stand in her own way? Meanwhile Mark and Arizona have conflicting ideas of the kind of baby shower Callie wants, Teddy is freaked out when Henry has another health complication -- leaving them both a little exposed -- and the competitiveness amongst the residents for the Chief Resident position is amplified when Richard receives the green light for his diabetes clinical trial.', 43, '2011-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 18, 'Song Beneath the Song', 'A cataclysmic event leaves the doctors shaken; Callie, on the verge of a life-changing moment, starts imagining about the hospital and her friends.', 43, '2011-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 19, 'It''s a Long Way Back', 'Everyone pulls together to help Callie and baby Sofia on their painstaking journeys to recovery in hopes of allowing mother and baby to finally meet; the sudden death of a clinical trial patient has Derek proceeding with more caution while Meredith makes a calculated and risky move; Alex treats a cranky old rich woman dying of cancer and gets an idea for a grandiose endeavor that is sure to get him the Chief Resident spot; and Teddy is pleasantly surprised by the return of a familiar face.', 43, '2011-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 20, 'White Wedding', 'As Callie and Arizona''s wedding approaches, the couple quickly realize that the day they''ve been looking forward to is not turning out the way they''d envisioned. Meanwhile Alex continues to make the other residents jealous as he appears to be the top contender for Chief Resident, Meredith and Derek make a decision that will change their lives forever, and Dr. Perkins presents Teddy with a very tempting proposition.', 43, '2011-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 21, 'I Will Survive', 'Personal and work pressures are adding up and have Meredith visibly on edge, Owen conducts formal interviews for the Chief Resident position, Cristina grows increasingly defiant, Alex and Lucy''s undefined relationship gets tested, and Jackson suddenly backs out of the Webber''s diabetes trial.', 43, '2011-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 7), 22, 'Unaccompanied Minor', 'News of Meredith''s dishonesty in the clinical trial comes to light, leading to unanticipated consequences for her and others; Cristina finds herself in a compromising situation, which forces her to decide between her career and her relationship; Owen posts his decision for Chief Resident, and Teddy makes a surprising choice regarding her love life -- and her future.', 43, '2011-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 8, 'Season 8', 'No matter how hot it gets - in the operating room or in the bedroom - the doctors of Seattle Grace know they can always lean on one another. As fifth-year residents, it''s do or die for the doctors, and things get bumpy when the chief makes a decision that rocks the entire staff. Outside the hospital, Meredith and Derek struggle to keep their relationship afloat while they try to adopt an orphaned baby girl, and Cristina wrestles with a difficult choice that threatens to ruin her marriage.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 1, 'Free Falling', 'The fifth-year residents return for the first day of a year that will make or break their careers: Meredith faces the consequences of tampering with Derek''s clinical trial and is terminated at the hospital; April tries to step up to the plate as Chief Resident in the wake of a giant sinkhole in the middle of Seattle; and Cristina and Owen are still at odds over their drastically different feelings for their unborn child.', 43, '2011-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 2, 'She''s Gone', 'News of Meredith and Derek''s unsteady relationship raises a red flag for Zola''s adoption counselor; Alex quickly realizes that he has become the outcast of the group after ratting out Meredith; and Cristina makes a tough decision regarding her unexpected pregnancy. Also, Chief Webber brings Henry in for a last minute surgery, alarming Teddy.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 3, 'Take the Lead', 'The chief makes a decision that shocks everyone at Seattle Grace; Owen and Cristina attempt to find normalcy; April struggles in her new role; the 5th-year residents receive their first solo surgery assignments.', 43, '2011-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 4, 'What is it About Men?', 'A stampede at a comic book convention leads to an influx of colorful characters in the ER; Mark continues to make life difficult for Jackson; Ben returns and realizes Bailey has moved on.', 43, '2011-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 5, 'Love, Loss and Legacy', 'The residents try their hardest to impress surgical great Catherine Avery-who also happens to be Jackson''s mother-when she arrives at Seattle Grace to perform a groundbreaking transplant surgery; Arizona and Alex find their hands tied with a confidentiality issue when a familiar patient comes into the ER; meanwhile, a love-struck Teddy throws a dinner party for the couples, and Bailey makes a decision regarding her love life', 43, '2011-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 6, 'Poker Face', 'After being blackballed by most of the surgeons, Meredith uses Lexie to spark Derek''s interest in her patient''s rare brain tumor case and, in secret, gives guidance to April with Bailey''s clinical trial; Callie''s wish for Arizona and Mark to form a friendship comes to fruition and she realizes it''s more irritating than helpful; Alex and Teddy research alternative surgeries for a very superficial patient; and Callie and Cristina struggle with a very difficult spinal surgery.', 43, '2011-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 7, 'Put Me In, Coach', 'Owen stresses teamwork and moves his leadership role over to the baseball field when he signs the doctors up for a baseball league, pitting them against their biggest competition, Seattle Presbyterian; Lexie tries to hide her jealous rage when she sees Mark with a new woman, but her emotions get the better of her; Alex fights to keep Zola at Seattle Grace after it is suggested that she be moved to another hospital due to a conflict of interest with Meredith and Derek; and Richard scolds Meredith and Bailey for their feud', 43, '2011-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 8, 'Heart-Shaped Box', 'The doctors become nostalgic when George O''Malley''s mother, Louise, returns to Seattle Grace for medical help after a botched surgery at a neighboring hospital; the residents are inspired by a medical miracle when they witness a harvested heart that continues to beat outside the body; a new pediatric fellow excites Arizona and makes Alex feel threatened; Jackson lets his suspicions about Mark and Lexie interfere with his work; and Henry and Teddy have their first marital fight when he expresses interest in pursuing medical school', 43, '2011-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 9, 'Dark Was the Night', 'Teddy puts her husband’s life in the hands of her peers when Henry is sent to the OR for surgery and she’s called away on another case; Meredith and Derek receive the long-awaited news about Zola; Callie and Jackson come under fire when their patient experiences post-surgery complications; and Meredith and Alex are involved in a life-threatening situation when they travel to a neighboring hospital to tend to a sick newborn, on Grey’s Anatomy', 43, '2011-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 10, 'Suddenly', 'A severe car crash involving an entire family results in an all-hands-on situation in the ER, as the eldest daughter is left to make the toughest decision of her life. Meanwhile Teddy, still in the dark about Henry''s death, calls upon Cristina to help with her patient in the O.R., and Lexie finds herself working alongside Mark''s new girlfriend, Julia, during an eye surgery.', 43, '2012-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 11, 'This Magic Moment', 'The doctors split into teams for a risky surgery involving conjoined twins; Bailey recruits Meredith to be a buffer between her and Ben when he puts pressure on moving their relationship to a more serious level; Richard teaches Alex a tough lesson in the OR; meanwhile Teddy questions Cristina about what exactly happened to Henry during his surgery.', 43, '2012-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 12, 'Hope for the Hopeless', 'Richard performs a monumental surgery in his career; Derek and Lexie attempt to work miracles for a patient with an inoperable tumor', 43, '2012-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 13, 'If/Then', 'As Meredith puts Zola to bed and falls asleep, she begins to wonder -- what if her mother had never had Alzheimer''s and she''d had loving, supportive parents? The reverberations of a happy Meredith Grey change the world of Seattle Grace as we know it. What if she had never met Derek in that bar and he had never separated from Addison? What if Callie and Owen had become a couple long before she met Arizona? And what if Bailey never evolved from the meek intern she once was?', 43, '2012-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 14, 'All You Need is Love', 'In the spirit of Valentine''s Day, Meredith and Derek try to have a night to themselves when Lexie offers to watch Zola; Callie hands babysitting duties over to Mark so that she can surprise Arizona with a romantic evening; and Ben proves to Bailey that he knows her better than she thinks. Meanwhile, the ER fills with romantics, including a 10-year-old girl who has an allergic reaction to chocolates from her valentine and a man who is hit by a car while chasing down his frustrated girlfriend.', 43, '2012-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 15, 'Have You Seen Me Lately?', 'Amelia arrives at Seattle Grace to beg Derek to help with the gliosarcoma case; Cristina and Owen have heated arguments during marriage counseling; Alex realizes he needs to improve his people skills in order to be a good doctor.', 43, '2012-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 16, 'If Only You Were Lonely', 'As Adele''s condition continues to deteriorate, Richard considers altering their living situation; an explosion at a local coffee shop results in a busy day in the ER for the doctors; Callie takes Meredith under her wing by helping her study for her boards; Lexie joins Arizona and Alex in peds, as they continue to care for intern Morgan''s premature son; and when Jackson snaps at a patient, Mark encourages him to find ways to relieve his stress. Meanwhile, Cristina lets her suspicions get the best of her.', 43, '2012-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 17, 'One Step Too Far', 'Derek encourages a hesitant Meredith to work with him again in neurology; Jackson''s mother, Catherine Avery, returns to Seattle Grace with a urology fellow and develops an interest in Richard; and Cristina becomes increasingly suspicious of Owen''s every move. Meanwhile, Alex tries to deny the fact that Morgan may be falling for him.', 43, '2012-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 18, 'The Lion Sleeps Tonight', 'A lion breaks loose in Seattle, leaving a couple''s lives and relationship at risk; Lexie overhears Mark''s discussion about moving in with Julia; Teddy begins to take steps towards coming to terms with Henry''s death; Callie grills Arizona on her past lovers; and Alex requests to be taken off Morgan''s preemie case when she becomes too dependent on him. Meanwhile, Meredith tries to be a support for Cristina as the tension between her and Owen hits a boiling point.', 43, '2012-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 19, 'Support System', 'A devastated Cristina presses Owen to confess the intimate details of his affair; Mark takes his new authority very seriously when he steps in as chief for the day and butts heads with Richard over a patient''s liver transplant; and Callie deems Meredith ready for the boards, while the rest of the residents continue to stress about the exam. Meanwhile, Callie, Arizona and Bailey plan a much needed ladies night for Teddy.', 43, '2012-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 20, 'The Girl with No Name', 'The doctors work on a Jane Doe, who turns out to be the subject of a case that gained national interest; Cristina proves to be the highest in demand as the residents begin their interviews for post-residency positions at prospective hospitals; and Richard is faced with an unsettling realization when he visits Adele at Rose Ridge.', 43, '2012-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 21, 'Moment of Truth', 'After eight years of practice, the residents head to San Francisco for their oral boards; sparks fly between Catherine and Richard when they bump into each other at the hotel; Bailey intervenes after Owen and Teddy get into a heated argument about their young car crash patient; and Mark tries to recruit Lexie for one of his cases. Meanwhile, Alex feels guilty for being away from the hospital when Tommy''s health begins to fail.', 43, '2012-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 22, 'Let the Bad Times Roll', 'The residents agonize over their oral boards, reliving every answer they gave during their exams; Arizona''s close childhood friend comes to Seattle Grace for medical help; the doctors work on a patient who is missing one third of his skull; and Julia asks Mark to start a family with her. Meanwhile Catherine tells Richard that one of his residents has failed.', 43, '2012-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 23, 'Migration', 'The residents determine their future as they make their final decisions regarding post residency positions; Mark admits to Derek that he is torn between his love for Lexie and the fact that Julia can give him everything he''s ever wanted; Ben plans something extra special for Bailey, but she is preoccupied with her work; and Arizona encourages her childhood friend, Nick, to have surgery. Meanwhile a couple on their third honeymoon come to the hospital complaining of mysterious symptoms.', 43, '2012-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 8), 24, 'Flight', 'Faced with a life threatening situation, the doctors must fight to stay alive while trying to save the lives of their peers; Bailey and Ben make a decision regarding their relationship; and Teddy is presented with a tempting offer. Meanwhile, Richard plans a special dinner for the residents.', 43, '2012-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 9, 'Season 9', 'It''s a year of bold new beginnings as your favorite doctors return to Seattle Grace for the biggest challenge of their lives. The plane crash that took the lives of Lexie Grey and Mark Sloan sent shockwaves throughout the hospital. But from the ashes, romance will rise, with each surgeon handling the loss in their own personal way. Meredith finds her groove in the operating room while Derek''s hand injury forces him to focus on something other than surgery. And as Mark prepares to say goodbye, Alex falls for someone new, Cristina tries to rekindle the flame with Owen, and Bailey and Ben discover the perils of a long-distance relationship.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 1, 'Going Going Gone', 'The doctors of Seattle Grace are faced with the aftermath of last season''s plane crash. As they try to move on with their lives, they must learn to adapt to the changes, cope with their losses and move forward with their relationships and careers.', 43, '2012-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 2, 'Remember The Time', 'In this flashback episode, return to the site of the plane crash and watch as each doctor tries to cope with the heartache and injuries caused by the crash. Meanwhile, back at Seattle Grace, everyone struggles to find a bit of normalcy amidst the chaos.', 43, '2012-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 3, 'Love the One You''re With', 'The survivors from the crash are asked to make an almost impossible decision that will affect the rest of their lives. Meanwhile, tension grows between Jackson and April after they''re forced to work together, and Alex tries to restrain himself with one of the interns.', 43, '2012-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 4, 'I Saw Her Standing There', 'Aware that Derek might never operate again, Meredith stops talking about the surgeries she''s performing. Meanwhile, Richard calls on Dr. Catherine Avery to help him perform a complicated procedure, as things continue to heat up between Jackson and April; and Arizona''s struggle to accept her fate forces Callie and Alex to face their guilt.', 43, '2012-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 5, 'Beautiful Doom', 'In this Meredith & Cristina-centric episode, the two friends continue to cope with life after the plane crash and their ever-growing responsibilities at their respective hospitals. As Meredith juggles taking care of Zola with a case that hits close to home, Cristina assists Dr. Thomas on a challenging heart surgery.', 43, '2012-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 6, 'Second Opinion', 'As the doctors continue with their lawsuit, they’re forced to confront the realities of their injuries. Meanwhile, Bailey tricks Arizona into helping her with a pediatric case, and Cristina tries to find normalcy in her new environment.', 43, '2012-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 7, 'I Was Made for Lovin'' You', 'Cristina and Owen continue to figure out their relationship amidst the pending lawsuit; and Bailey argues with Ben over plans for their upcoming nuptials. Meanwhile, Callie recruits Jackson to help find a solution to Derek''s hand, but he is preoccupied by a shocking situation with April.', 43, '2012-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 8, 'Love Turns You Upside Down', 'The new batch of interns find themselves involved in all the drama at Seattle Grace: Meredith asks Heather to go above and beyond to help fix Derek''s hand; Cristina starts a healthy competition between Stephanie and Leah, which inadvertently leads to a medical emergency for Cristina''s patient; Alex sees Jo in a new light as they work to save a baby''s life, and April teaches Shane a valuable lesson during "lumps and bumps" duty.', 43, '2012-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 9, 'Run, Baby, Run', 'As the rest of the doctors prepare for Bailey''s wedding, Richard helps her through a bout of pre-wedding jitters. Meanwhile, Lizzie butts heads with Meredith, and Callie and Jackson try to convince Derek to participate in a risky surgery that could fix his hand.', 43, '2012-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 10, 'Things We Said Today', 'Bailey puts her wedding day on hold and continues her efforts to save Adele''s life, Cristina and Owen remain undecided about their pending divorce, while Arizona and Callie try to get their spark back. Meanwhile, the hospital becomes inundated with a group of bikers after a horrible accident.', 43, '2013-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 11, 'The End is the Beginning is the End', 'Meredith, Derek, Cristina and Arizona receive big news regarding the plane crash lawsuit, Richard avoids Catherine''s romantic advances and Jackson takes on one of Mark Sloan''s old patients. Meanwhile, Derek begins recovery on his hand.', 43, '2013-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 12, 'Walking on a Dream', 'The Seattle Grace doctors are on edge when a new medical professional enters the hospital; Arizona struggles with the emotional and physical pain of a phantom limb; and while battling pregnancy hormones, an overly-emotional Meredith is confronted with her worst fear.', 43, '2013-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 13, 'Bad Blood', 'As Derek and April work around the clock to find a solution for the hospital, Cristina struggles to respect the wishes of a family whose son is dying. Meanwhile, Arizona empathizes with a teenager who faces problems similar to her own.', 43, '2013-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 14, 'The Face of Change', 'Competition heats up as several of the doctors fight to become the new face of Seattle Grace; April brings in an emergency case, and Jackson and Alex work with a transgender teen couple. Meanwhile, the hospital implements new policies which test the patience of the staff.', 43, '2013-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 15, 'Hard Bargain', 'As the hospital spirals closer to financial ruin, Owen must make some tough decisions, which includes foregoing an expensive surgery that could save the life of a child. Meanwhile, Alex and Jo work together to save the life of an infant, and April asks Jackson for dating advice.', 43, '2013-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 16, 'This is Why We Fight', 'As word of Seattle Grace''s financial trouble spreads, Catherine encourages Jackson to move to Boston, and the interns fear they might lose their jobs. Meanwhile, the doctors meet with a potential investor in a last-ditch effort to save the hospital, and Alex impresses Jo while caring for a patient.', 43, '2013-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 17, 'Transplant Wasteland', 'The discord and chaos created by the hospital''s new management team causes one physician to question his future at Seattle Grace. Meanwhile, the doctors and the interns must juggle several transplant surgeries at once, each coming with its own set of obstacles.', 43, '2013-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 18, 'Idle Hands', 'As the hospital continues to make positive changes under the new management, the doctors begin to realize that owning a hospital comes with its own set of problems and responsibilities. Meanwhile, Meredith worries about the wellbeing of her unborn baby, Callie and Arizona try to get the spark back in their relationship, and Alex gives Jo‘s new boyfriend a run for his money.', 43, '2013-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 19, 'Can''t Fight This Feeling', 'A gas tanker explodes on a Seattle highway, causing multiple injuries, including paramedic Matthew. Meredith and Jo help a frantic mother whose child is suffering from a mysterious illness. Owen bonds with a young boy whose parents are in critical condition. Meanwhile true colors are revealed when Alex is forced to work with Jo''s boyfriend on an ailing patient.', 43, '2013-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 20, 'She''s Killing Me', 'Upon receiving some unsettling news, Meredith and Derek take preventative steps for their children’s future; a group of Syrian doctors arrive at Grey Sloan Memorial Hospital for a crash course in basic surgical skills that they plan to apply in the field; and April decides to come clean to Matthew regarding the truth about her virginity. Meanwhile, multiple pre-op patients develop infections, causing one doctor to wonder if she is at fault.', 43, '2013-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 21, 'Sleeping Monster', 'Bailey finds herself at the center of a CDC investigation surrounding the death of several of her patients, as Jackson and the rest of the board members argue over how to address the crisis with the public. Meanwhile, Cristina teases Alex about his unspoken feelings for Jo, and Owen continues to take special care of Ethan as the condition of his parents remains uncertain.', 43, '2013-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 22, 'Do You Believe in Magic?', 'The doctors reach out to Bailey but she continues to shut everyone out; after an incident with Ethan''s grandmother, Owen fears the child could end up in foster care. A new craniofacial specialist arrives at Grey Sloan Memorial Hospital to work on a young patient. Meanwhile, a magician''s assistant is rushed into the ER after a magic trick goes terribly wrong.', 43, '2013-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 23, 'Readiness is All', 'The doctors of Grey Sloan Memorial Hospital prepare for a super storm heading towards Seattle. Owen''s desire to be a parent gets stronger as he becomes closer to Ethan. One wrong move puts the lives of Meredith and her baby in jeopardy. Meanwhile, Jo looks to Alex for help in a moment of crisis, and one doctor gets the shock of her life.', 43, '2013-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 9), 24, 'Perfect Storm', 'Grey Sloan Memorial Hospital enters crisis mode as the storm rages, resources become scarce and patients flood in by the busload. Meanwhile, one of the doctors fights for their life.', 43, '2013-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 10, 'Season 10', 'The storm may have passed, but now the relationships and romance of Grey Sloan Memorial must survive in its wake. Bonds are tested, love is lost and the hospital bids farewell to Dr. Cristina Yang. Following a massive mudslide, the hospital becomes a madhouse, and the lives of two doctors hang in the balance. The drama escalates as Arizona tries desperately to mend her broken marriage, while Derek and Meredith juggle their roles as surgeons and new parents. Meanwhile, a stunning betrayal pits Cristina against Meredith and, as April prepares for her big day, a familiar face returns to town. Big secrets lead to big problems and turn best friends into rivals.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 1, 'Seal Our Fate', 'The Grey Sloan Memorial Hospital doctors are faced with the devastation left by the storm. A giant mudslide in Seattle injures a group of first responders and citizens, causing the already short handed ER to spring into action. Meanwhile, Meredith is faced with a tough decision that will affect the life of a loved one, Callie is rocked by the reality of Arizona’s infidelity, and Richard’s life is in extreme danger.', 43, '2013-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 2, 'I Want You with Me', 'Callie makes a decision about her relationship; the doctors receive devastating news.', 43, '2013-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 3, 'Everybody''s Crying Mercy', 'Derek and Meredith adjust to life at home with their newborn; Arizona tries to repair her marriage; Jackson and Owen clash over financial issues.', 43, '2013-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 4, 'Puttin'' on the Ritz', 'The doctors of Grey Sloan Memorial throw a fundraising gala which turns wildly competitive after Jackson makes a rash promise. Back at the hospital, Bailey’s patience is tested when she has to deal with several extremely difficult patients. Meanwhile, Shane and Stephanie handle an incredibly busy ER by themselves and Alex reveals an emotional secret to Jo.', 43, '2013-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 5, 'I Bet It Stung', 'Meredith struggles to balance her roles as a surgeon and a mother when she returns to work; Stephanie tries to impress Jackson''s mother; Jo becomes overly involved with a patient.', 43, '2013-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 6, 'Map of You', 'Derek and Callie work on a brain mapping project, Richard encourages the interns to use his physical condition as a learning tool and after a discussion with Callie, Meredith considers continuing her mother’s research. Meanwhile, Shane continues to feel guilty about Heather’s death.', 43, '2013-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 7, 'Thriller', 'Costumed patients create a challenge for the doctors; Derek and Ben work on a new surgical technique; Richard asks a resident to perform his next surgery, angering Bailey.', 43, '2013-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 8, 'Two Against One', 'A betrayal intensifies the issues between Cristina and Meredith; Matthew and April make a decision about their relationship; Bailey faces difficulties with Ben''s return.', 43, '2013-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 9, 'Sorry Seems to Be the Hardest Word', 'When an unexpected malpractice suit turns Callie''s world upside down, her supportive father  arrives and shares an interesting secret with her. Meanwhile, through flashbacks, we learn some surprising details about Callie and Arizona''s marriage.', 43, '2013-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 10, 'Somebody That I Used To Know', 'Ben worries that a casual conversation with Derek could potentially cause issues for Bailey, Cristina turns to Shane as tension grows with Meredith, and April''s upcoming wedding makes for an uncomfortable situation between Jackson and Stephanie. Meanwhile, Meredith plans a Thanksgiving dinner at her house.', 43, '2013-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 11, 'Man on the Moon', 'April’s sisters arrive to help celebrate April’s upcoming nuptials and quickly get on her nerves. Matthew and Jackson are forced to work together when they witness a terrible accident, Callie and Arizona work hard to reestablish their relationship and Cristina is pressured to live stream an upcoming surgery. Meanwhile, a familiar face returns to the hospital.', 43, '2013-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 12, 'Get Up, Stand Up', 'On the day of April''s wedding, the Grey Sloan Memorial doctors are all preoccupied with their own drama. Meredith and Cristina continue to argue about their research and careers, Bailey comes clean to Ben about her feelings regarding him moving back to Seattle, and Shane puts himself in a risky situation. Meanwhile, Derek gets a phone call that will change his life.', 43, '2013-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 13, 'Take It Back', 'The doctors are faced with the consequences of the events at April''s wedding. Alex reacts to the news about his father. Callie and Arizona make a decision about their relationship.', 43, '2014-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 14, 'You''ve Got to Hide Your Love Away', 'After an anonymous complaint is issued by one of their own, the hospital implements a non-fraternizing policy causing the couples to panic. Meanwhile, Emma and Owen talk about the future, Cristina and Meredith enjoy a little girl time, and Richard enlists the residents to help research a rare cancer case.', 43, '2014-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 15, 'Throwing it All Away', 'Arizona has a bad day which escalates when she advises one of Callie''s patients on a potential double amputation. Derek goes back on a promise to Callie, and Jo and Stephanie come across an abandoned baby outside the hospital. Meanwhile, the doctors deal with the repercussions of the non-fraternization rule, which include meetings with HR and one doctor''s suspension.', 43, '2014-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 16, 'We Gotta Get Out of This Place', 'It''s Richard''s birthday and Bailey invites him to scrub in on the case of a lifetime. Meredith hires a research assistant to help with her portal vein project. A scorned Callie gives Derek quite the shock. Meanwhile, Shane helps screen candidates for Cristina''s clinical trial and meets a young expectant mother who needs his help.', 43, '2014-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 17, 'Do You Know?', 'Cristina imagines the two routes her life can take based on one decision she makes. Meanwhile one of the hospital’s patients decides whether or not to live.', 43, '2014-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 18, 'You Be Illin''', 'The hospital gets inundated with flu infected patients, which causes the doctors to slowly fall ill one by one. Derek must fight off the sickness as he prepares to give a speech on brain mapping and the residents place bets on who will fall ill first. Meanwhile, a new doctor at the hospital gives Alex a glimpse into an alternate form of medical practice.', 43, '2014-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 19, 'I''m Winning', 'Cristina won''t let herself get excited when she is nominated for a Harper Avery award; Alex thinks about making a change; Callie and Derek work with a machine that recognizes emotions.', 43, '2014-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 20, 'Go It Alone', 'Cristina enlists Meredith to help her prepare an acceptance speech for her possible Harper Avery win and while Owen offers to attend the ceremony with her, she insists on going alone. Meanwhile, Derek feels overwhelmed between his responsibilities at home and at the hospital. April and Jackson come to a disagreement on children and religion, and Callie and Arizona try to reconnect in their marriage.', 43, '2014-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 21, 'Change of Heart', 'Jackson is given the daunting task of delivering disappointing news to the doctors. Meanwhile, Derek''s sister Amelia drops by for a surprise visit, Richard surprises Catherine in Boston and when Bailey gets frustrated by the slow pace of her research, she makes a risky decision.', 43, '2014-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 22, 'We Are Never Ever Getting Back Together', 'Cristina considers her future at the hospital; Amelia and Derek collaborate on a tough surgery involving conjoined twins; Jo takes on too many cases at once; Stephanie stumbles on the truth about Bailey''s case.', 43, '2014-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 23, 'Everything I Try to Do, Nothing Seems to Turn Out Right', 'With Derek away, Meredith spends time with Amelia and finds out her true feelings about her time in Seattle. Bailey deals with the ramifications of her actions and Callie receives devastating news. Meanwhile, the residents panic after hearing that one of them will be fired', 43, '2014-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 10), 24, 'Fear (of the Unknown)', 'The doctors of Grey Sloan Memorial Hospital bid an emotional farewell to the beloved Cristina Yang. A possible act of terrorism rocks Seattle and causes chaos at the hospital. Meanwhile, Meredith makes a life changing decision and one doctor receives shocking news.', 43, '2014-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 11, 'Season 11', 'During an interview, Shonda Rhimes stated that "Season 11 is really a Meredith-centric season. She lost her ‘person’, her half-sister has shown up, her husband is chafing to go someplace else…" She went on to reveal that she''s been wanting to do the "familial grenade" storyline for a long time, and at the end of Season 10, she knew it was the time to do it. Rhimes also claimed that Season 11 will pick up right where Season 10 left us, so there won''t be much that the audience won''t see. In another interview discussing this storyline, Rhimes revealed that she and the writers are thinking about doing flashback periods to the younger days of Drs. Ellis Grey and Richard Webber.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 1, 'I Must Have Lost It on the Wind', 'With Cristina gone, a new doctor, Maggie Pierce, making the rounds and Derek wanting to move to Washington DC, Meredith struggles to regain a sense of normalcy both at home and in the hospital. Meanwhile, Callie and Arizona come to a decision about surrogacy, Amelia overhears a big secret, Bailey realizes she will have to fight Alex for Cristina’s board seat and a freak accident causes two teenagers to be caught in a very compromising position.', 43, '2014-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 2, 'Puzzle with a Piece Missing', 'Maggie tries to make a good impression but finds herself in unfortunate situations; Richard keeps hiding his secret.', 43, '2014-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 3, 'Got to Be Real', 'Owen tries to get Callie to help Veterans Hospital patients with the robotic limb lab. Alex and Meredith''s friendship makes Jo jealous. Alex and Bailey prepare to go in front of the board.', 43, '2014-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 4, 'Only Mama Knows', 'Secrets from Ellis Grey’s past come to light when Meredith watches old videos and reads through her mother’s journals. Meanwhile, Maggie rocks the hospital with an unexpected announcement; Alex gets new responsibilities and Callie focuses her attention on the Veterans’ project.', 43, '2014-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 5, 'Bend and Break', 'Callie and Arizona examine their marital problems and what''s contributed to them. Meanwhile, Callie devotes herself to the veterans'' project, Arizona strives to impress Dr. Herman, and Richard seeks guidance from Bailey.', 43, '2014-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 6, 'Don''t Let''s Start', 'Owen becomes invested in a patient when he realizes she may have served in the military, April’s mother pays her daughter a visit and bonds with Jackson, and Derek plans a family dinner. Meanwhile, a patient’s diagnosis causes Bailey to reconsider her own health issues and Dr. Herman drops a bombshell on Arizona', 43, '2014-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 7, 'Could We Start Again, Please?', 'Information about Amelia''s past emerges and causes problems for her at the hospital.', 43, '2014-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 8, 'Risk', 'Maggie and Meredith disagree with Derek about the best way to approach a patient’s case, which leads to a bigger argument between the couple. Meanwhile Callie feels responsible when one of her veterans is pushed too far and one doctor’s routine procedure results in a devastating diagnosis.', 43, '2014-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 9, 'Where Do We Go from Here?', 'As Derek prepares for his move to DC, Meredith keeps herself busy at the hospital. Meanwhile, Jackson and April deal with difficult news, and Arizona and Amelia discuss how to best approach Dr. Herman.', 43, '2015-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 10, 'The Bed''s Too Big Without You', 'April stays optimistic as Arizona begins testing on her baby; Dr. Herman plans out a crash course in fetal surgery; and Owen and Callie encourage each other to get back into the dating scene. Meanwhile, Meredith, Maggie and Bailey use the 3D printer to gain a better understanding of their patient''s tumor.', 43, '2015-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 11, 'All I Could Do Was Cry', 'After several discussions with Dr. Herman, April and Jackson must face their situation head on and make a difficult decision regarding their unborn child. Catherine arrives in Seattle and bumps into Richard at the hospital. Meanwhile, Meredith tries to find someone to take care of the kids so she can visit Derek for the weekend, and Amelia shows Stephanie some tough love when they work together on a case', 43, '2015-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 12, 'The Great Pretender', 'Maggie gets upset when Meredith dodges her questions about DC; Bailey and Ben become concerned about Ben’s brother after he is admitted to the hospital, and Dr. Herman starts to warm up to Arizona. Meanwhile, Richard feels manipulated by Catherine.', 43, '2015-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 13, 'Staring at the End', 'The hospital doctors become fascinated with Dr. Herman’s case when Amelia gives a lecture detailing the intricacies of the surgery. Arizona and Herman continue to bond over the amount of cases they are trying to complete before the big surgery. Meanwhile, Bailey brings them a case of a pregnant woman who is close to her heart.', 43, '2015-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 14, 'The Distance', 'In this Amelia-centric episode, Amelia engages in the surgery of a lifetime as a crowd of doctors look on from the gallery. With Stephanie by her side, she begins operating on Dr. Herman, but quickly realizes it''s far more difficult than she anticipated. Meanwhile, Bailey becomes skeptical when Arizona takes on one of Herman’s cases.', 43, '2015-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 15, 'I Feel the Earth Move', 'An earthquake shakes the ground at Grey Sloan Memorial Hospital, trapping Maggie in an elevator and threatening Meredith’s long streak of successful surgeries. Meanwhile, Owen gives medical advice to a child over the phone and Ben confides in Jackson.', 43, '2015-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 16, 'Don''t Dream It''s Over', 'A patient''s condition sparks a conversation between Richard and Maggie about Alzheimer''s disease; April and Jackson struggle to return to their normal lives and Arizona is faced with the reality that Callie is moving on. Meanwhile, Meredith reveals her biggest fears about Derek.', 43, '2015-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 17, 'With or Without You', 'Meredith, rattled by the latest events, tries to figure out what to do about Derek. Meanwhile, Owen is shocked when his mother is admitted to the hospital.', 43, '2015-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 18, 'When I Grow Up', 'A school field trip to the hospital takes a dramatic turn when the kids witness two injured cops enter the emergency room. Meanwhile, Stephanie sets her eyes on one of the chaperons, Callie operates on the leg of the police captain and Amelia must face her feelings for Owen.', 43, '2015-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 19, 'Crazy Love', 'Upon realizing that Owen and Amelia have been seeing each other behind her back, Meredith comes down hard on her sister-in-law causing Amelia to rethink things. Meanwhile, Catherine springs into action when a man is brought into the hospital after his wife seeks revenge on his cheating ways.', 43, '2015-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 20, 'One Flight Down', 'A small plane crash in Seattle causes multiple casualties and brings back horrible memories for the doctors, especially Meredith and Arizona. Meanwhile, friction between Owen and Amelia makes for an uncomfortable working situation for Stephanie.', 43, '2015-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 21, 'How to Save a Life', 'Derek witnesses a horrible car accident and springs into action to save lives.', 43, '2015-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 22, 'She''s Leaving Home', 'Meredith and the staff feel the impact of losing one of their own; Jackson struggles with April''s decision; Bailey and Ben argue about their future. Months after Derek''s funeral, Amelia struggles with her emotions; April plans to return; and Derek''s part in Meredith''s life continues to grow.', 83, '2015-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 23, 'Time Stops', 'The doctors of Grey Sloan Memorial Hospital are forced to put their emotions aside when a catastrophic event occurs.', 43, '2015-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 11), 24, 'You''re My Home', 'As the doctors continue to tackle an unfathomable crisis, they are reminded of what is important and are brought closer together.', 43, '2015-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 12, 'Season 12', 'The doctors find themselves simmering in a world of sexual politics. Bailey struggles with what it means to be a woman in charge of the hospital and her husband, while Maggie faces the challenges of dating a younger man and Amelia battles her own demons. Meanwhile, in the wake of a brutal attack, Meredith finds comfort and love in the most unexpected place, Callie and Arizona find themselves in a fight for their lives, and tensions run high when Amelia and Meredith come face to face with the doctor responsible for Derek''s death.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 1, 'Sledgehammer', 'The doctors from Grey Sloan Memorial Hospital spring into action to save the lives of two girls with a powerful story. Meanwhile, Meredith tries  to cope with the fact that Amelia is now living with her and Jackson prepares for April''s return back to Seattle.', 43, '2015-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 2, 'Walking Tall', 'The pressure is on as a determined Bailey tackles her first day as Chief; meanwhile, April''s marriage is in jeopardy and she finds herself  unable to address her problems; Meredith struggles to juggle all her responsibilities and Amelia works to define her relationship with Owen.', 43, '2015-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 3, 'I Choose You', 'Maggie reevaluates her life choices after receiving an invitation to her ex-boyfriend’s wedding; Richard questions Bailey’s loyalty, and Jo confides in Stephanie about a secret she’s been keeping from Alex. Meanwhile, Alex struggles with making a difficult decision that will affect the lives of newborn twins.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 4, 'Old-Time Rock-and-Roll', 'Owen suggests the interns learn a vital lesson on how to break bad news to patients’ families, and Arizona’s 90-year-old patient reassures her that she’s destined to find love again. Meanwhile, the sisters completely forget about the dinner party they’re hosting for everyone.', 43, '2015-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 5, 'Guess Who''s Coming to Dinner?', 'In the midst of the sisters’ dinner party, Maggie ditches her cooking duties to rush to the hospital. Meanwhile, April steps in to help cook as an attempt to avoid Jackson, and Arizona nervously waits to find out more about Callie’s new girlfriend.', 43, '2015-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 6, 'The Me Nobody Knows', 'Grey Sloan Memorial not only welcomes a new transfer resident, but also a patient who''s the topic of converstation after accidentally sending his sex tape to his entire congregation. Meanwhile, Richard wrestles with how to progress his relationship with Maggie when an old friend visits the hospital, and April brings in a case of a young boy from the Middle-East.', 43, '2015-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 7, 'Something Against You', 'The team of doctors work on a high stakes case of a long time patient, adding additional pressure to an already tense environment. Meanwhile, Bailey wants Ben to kick out their new roommate, and Arizona is eager to get back into the dating world with a new wingman.', 43, '2015-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 8, 'Things We Lost in the Fire', 'Midseason Finale -  As the rumor mill around the hospital continues to spiral out of control, Grey Sloan Memorial is flooded with injured firefighters from a nearby wildfire. Maggie struggles to keep things with Andrew professional at work; meanwhile, Jo questions Alex’s priorities.', 43, '2015-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 9, 'The Sound of Silence', 'Meredith is brutally attacked by a patient, and Penny is the one who discovers her. The doctors of Grey Sloan Memorial rush to stabilize Meredith and remain by her side in the harrowing aftermath.', 43, '2016-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 10, 'All I Want Is You', 'Everybody attempts to deals with Meredith''s trauma as Maggie and Callie perform a risky, experimental surgery on a teenager. Nathan and Owen continue to be at odds. Maggie and Andrew''s relationship continues to progress.', 43, '2016-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 11, 'Unbreak My Heart', 'The evolution of April and Jackson’s relationship is revealed through a series of flashbacks dating back to when they first met. Simultaneously, we follow the years-long progress of one of Jackson’s patients.', 43, '2016-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 12, 'My Next Life', 'A patient from Meredith''s very first surgery as an Intern is readmitted to Grey Sloan Memorial with a new aneurysm, and Amelia takes her case. Meanwhile, Maggie suspects that Richard knows about her relationship with Andrew, and Arizona debates dating again.', 43, '2016-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 13, 'All Eyez on Me', 'Meredith, Bailey, Jackson, Callie and Jo travel to a military hospital to perform an extraordinary and extremely risky surgery on a veteran with an advanced tumor. Meanwhile back at Grey Sloan, Andrew is tired of being Maggie’s worst kept secret; Ben makes an impulsive surgical decision; and a team of cheerleaders wreak havoc in the ER.', 43, '2016-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 14, 'Odd Man Out', 'There is plenty of turmoil after Richard messes with the staff pairings. Arizona takes a risk to help a woman who is pregnant with quadruplets.', 43, '2016-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 15, 'I Am Not Waiting Anymore', 'Jackson learns about April''s pregnancy, while Alex and the team of doctors handle an hours-long triple-organ transplant surgery. Meredith considers dating again, and Andrew insists on not receiving special treatment after he and Maggie go public.', 43, '2016-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 16, 'When It Hurts So Bad', 'Meredith takes a step forward with Will but quickly regrets it; Maggie senses a disconnection with Andrew; and Amelia reevaluates her relationship with Owen. Meanwhile, Catherine comes into town and really shakes things up with April and Jackson.', 43, '2016-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 17, 'I Wear the Face', 'Meredith goes on an ambulance ride with Owen and Nathan to pick up a heart for a transplant patient. Musician &amp; MS patient Kyle Diaz is admitted to Grey Sloan Memorial with a tremor in his hand, and the residents apply for the Preminger Grant. Meanwhile, Catherine continues to insert herself into Jackson and April’s business against Richard’s wishes.', 43, '2016-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 18, 'There’s a Fine, Fine Line', 'After a missing child forces the hospital into lockdown, Ben decides to operate on a pregnant mother without the proper surgical equipment. Miranda, as Chief, is faced with the repercussions of  the event and whether or not Ben''s impulsive actions were justified.', 43, '2016-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 19, 'It’s Alright, Ma (I’m Only Bleeding)', 'Miranda continues to deal with the aftermath of Ben''s reckless decision and forms an advisory committee to recommend proper disciplinary action against him. Meanwhile, April and Jackson try to put their differences aside for the sake of their baby, and Arizona makes a decision that could affect her relationship with Callie forever.', 43, '2016-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 20, 'Trigger Happy', 'The doctors work frantically to save a young boy who was accidentally shot. Meanwhile, Arizona is upset when Callie tries to make an important decision about Sofia’s future without consulting her', 43, '2016-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 21, 'You''re Gonna Need Someone on Your Side', 'Stephanie’s relationship with Kyle becomes complicated. Meanwhile, Meredith encourages Amelia and Owen to take a chance and choose to be a real couple. Arizona and Callie are at odds and put their friends in the middle of an uncomfortable situation.', 43, '2016-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 22, 'Mama Tried', 'Callie and Arizona are at odds over Sofia’s future, and Stephanie questions the status of her relationship with Kyle. Meanwhile, Alex and April work on a pregnant teen that is readmitted to Grey Sloan Memorial.', 43, '2016-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 23, 'At Last', 'Owen and Amelia take their relationship to the next level; Alex gains some clarity on his future with Jo; and Callie and Arizona continue to struggle with the current custody arrangement.', 43, '2016-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 12), 24, 'Family Affair', 'Meredith and Maggie support Amelia on an important day; Jo reveals that she has been keeping secrets from Alex while Arizona and Callie deal with the impact of their custody arrangement. Meanwhile, Ben leaps into action to help a friend.', 43, '2016-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 13, 'Season 13', 'After being on her own for some time, Meredith is beginning to explore the idea of a romance with Riggs. Unfortunately, Maggie desires him as well, which threatens to drive a bitter wedge between the sisters. At the same time, despite their differences, Jackson and April must come together when they are assigned a difficult case. Meanwhile, Alex faces the consequences of his vicious attack on DeLuca, Owen and Amelia''s marriage implodes and a hospital-wide mutiny erupts when Bailey demotes Webber. Finally, Arizona may have found love again - but is she sleeping with the enemy?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 1, 'Undo', 'When one of Grey Sloan’s own lands in the hospital, Bailey tries to figure out what happened while the rest of the doctors jump in to help. Meredith juggles huge secrets that affect her relationships with Alex and Maggie. While Richard helps Jo with a big decision, April and Catherine clash over the new baby.', 43, '2016-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 2, 'Catastrophe and the Cure', 'Meredith considers her loyalties, as Alex deals with the repercussions of his actions. Newlyweds Amelia and Owen host a dinner party with unlikely guests, and Jackson proposes an arrangement to help April through her recovery.', 43, '2016-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 3, 'I Ain''t No Miracle Worker', 'A car crash at a funeral brings a bickering family into the hospital. Back from New York, Arizona ends up caught between Alex and Andrew. While Ben takes on a new parenting role, Amelia helps Meredith and Maggie through a problem.', 43, '2016-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 4, 'Falling Slowly', 'Alex tries to do the right thing but still cant catch a break. Jackson and April adjust to their “new normal” with the baby. While Meredith and Nathan establish what’s going on between them, Amelia questions the state of her relationship with Owen.', 43, '2016-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 5, 'Both Sides Now', 'Meredith and Bailey are at odds when both of their patients need a liver transplant, Owen seeks help from the other doctors when he is charged with babysitting baby Harriet for the day, and Amelia struggles with telling Owen some important news.', 43, '2016-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 6, 'Roar', 'A familiar face returns to Grey Sloan, throwing many of the doctors for a loop. With Catherine putting on the pressure, Bailey has to make a decision about Alex while a tough ER case makes Amelia’s bad day even worse.', 43, '2016-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 7, 'Why Try to Change Me Now', 'The arrival of a new consultant puts all of the doctors on edge, especially once she starts stepping on toes in the OR. Amelia and Owen bring their personal problems into the hospital, while April explores some uncharted territory.', 43, '2016-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 8, 'The Room Where It Happens', 'A difficult surgery brings back pivotal memories for Meredith, Richard, Owen and Stephanie, as they work together to save a life.', 43, '2016-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 9, 'You Haven''t Done Nothin''', 'Believing he is going to jail tomorrow, Alex makes a big decision about his future. While the hospital is overrun with victims of a building collapse, Richard demands answers from Bailey about Eliza’s presence at Grey Sloan.', 43, '2016-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 10, 'You Can Look (But You''d Better Not Touch)', 'Bailey, Arizona and Jo go to a maximum security women’s prison to treat a violent, 16-year-old pregnant girl and her unborn baby.', 43, '2017-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 11, 'Jukebox Hero', 'Richard and the attendings set out to make Eliza’s first day at Grey Sloan a bumpy one. Meanwhile, Meredith tries to track down Alex.', 43, '2017-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 12, 'None of Your Business', 'Maggie gets a surprise visit from her mother at the hospital. Bailey has to make a difficult decision when one of the attendings refuses to work with Eliza, and Stephanie gets caught up in Owen and Amelia’s personal drama.', 43, '2017-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 13, 'It Only Gets Much Worse', 'The residents are excited for Eliza’s next phase of teaching, but they spend the day caught between the warring attendings. Meanwhile, April has a challenging first day in her new role at the hospital.', 43, '2017-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 14, 'Back Where You Belong', 'Alex returns to the hospital and discovers a lot has changed since he left. Meanwhile, Jo has to make a difficult decision on a case, and Arizona tries to distance herself from Eliza.', 43, '2017-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 15, 'Civil War', 'Richard, Jackson, April and Catherine tackle a grueling trauma case intensified by hospital politics. Amelia finally faces her feelings about Owen, and Meredith gets caught between Nathan and Alex over a patient.', 43, '2017-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 16, 'Who Is He (And What Is He To You)?', 'Jackson and April travel to Montana in order to perform a complicated surgery on a young patient, but Jackson’s mind is elsewhere, and April is forced to step up and get him back on track.', 43, '2017-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 17, '''Til I Hear It from You', 'Diane Pierce returns to Grey Sloan, but Maggie is still in the dark as to why she’s really there. Owen and Amelia hash out their problems as they work a trauma case together, and Bailey tries to mend her relationship with Richard.', 43, '2017-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 18, 'Be Still, My Soul', 'When Maggie’s mom’s health deteriorates, the doctors are at odds over how to treat her. Meanwhile, Richard comes to grips with Bailey’s betrayal over the Residency Program.', 43, '2017-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 19, 'What''s Inside', 'When Maggie takes on a big case, many of the doctors are worried she’s not the right one for the job while Stephanie makes a mistake treating one of Grey Sloan’s own.', 43, '2017-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 20, 'In the Air Tonight', 'Meredith and Nathan have to confront their feelings when they are are stuck sitting next to each other on a plane.', 43, '2017-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 21, 'Don''t Stop Me Now', 'Bailey and April work to fix things between Richard and Catherine; Eliza continues to pursue Arizona; one of Alex''s previous patients returns to Grey Sloan.', 43, '2017-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 22, 'Leave It Inside', 'April and Andrew consult with a fiery patient who has a giant, inoperable heart tumor. Meanwhile, Alex and Eliza are at odds over the treatment of a young patient, and Stephanie and Ben make decisions that could affect their careers.', 43, '2017-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 23, 'True Colors', 'The doctors of Grey Sloan encounter a difficult case involving a dangerous patient. Meanwhile, Owen receives life-changing news that pushes Amelia to step up to support him, and Alex attends a medical conference after making a shocking discovery.', 43, '2017-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 13), 24, 'Ring of Fire', 'The doctors’ lives are at risk after a dangerous patient escapes the hospital room. Alex must make a hard choice in his relationship with Jo while Meredith has some big news for Nathan that brings things to a turning point.', 43, '2017-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 14, 'Season 14', 'After the fire, Miranda Bailey starts renovations at the hospital. She discovers she''ll need more than new walls and paint to repair broken trust, tainted reputations and broken relationships. Against the backdrop of a year full of love, loss and groundbreaking changes, Meredith pioneers a revolutionary surgical technique that earns her a nomination for the coveted award named after its founder, Harper Avery. But when former legend Dr. Avery gets involved in a scandal, Meredith''s efforts and the future of Grey Sloan are put in jeopardy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 1, 'Break Down the House', 'Meredith and the team are focused on helping Owen’s sister after her shocking return, and Amelia faces a conflict over a patient. Meanwhile, Bailey is forced to give Grey Sloan a facelift after the fire, and the doctors are introduced to a few new faces that spice things up around the hospital.', 43, '2017-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 2, 'Get Off on the Pain', 'Meredith struggles to come up with a new plan for Owen’s sister. Jo makes a surprising choice regarding Alex, and Andrew’s sister’s controversial research leads to a shocking discovery.', 43, '2017-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 3, 'Go Big or Go Home', 'Harper Avery arrives at Grey Sloan, putting Bailey on edge. A familiar face from Meredith’s past returns as a patient, and Amelia tries to manage a secret.', 43, '2017-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 4, 'Ain''t That a Kick in the Head', 'Amelia confronts a difficult situation, while Meredith deals with the fallout from her conversation with Nathan. Maggie finds herself at an awkward family dinner, Jackson receives big news, and Richard and Bailey search for the stars of tomorrow.', 43, '2017-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 5, 'Danger Zone', 'In a flashback to Iraq in 2007, the events leading up to Megan’s kidnapping are revealed. In present day, Owen and Megan hash out old wounds.', 43, '2017-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 6, 'Come on Down to My Boat, Baby', 'Jackson decides he needs some time off and invites the guys to join him on a day out at sea. Meanwhile, Arizona, April and Maggie treat a woman who’s hiding a deadly secret.', 43, '2017-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 7, 'Who Lives, Who Dies, Who Tells Your Story', 'After a roller coaster car falls off the track at the county fair, the doctors at Grey Sloan tend to patients who spark memories about ghosts from their past. The series 300th episode!', 43, '2017-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 8, 'Out of Nowhere', 'A hacker compromises the hospital’s computer system, causing monitors, phones, labs and patient files to all go down. As technology fails them, Bailey attempts to keep the peace but chaos erupts and the doctors are forced to get creative in their methods to treat the patients.', 43, '2017-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 9, '1-800-799-7233', 'Jo finally faces her estranged, abusive husband Paul Stadler, while Grey Sloan continues to work with the FBI after a hacker has compromised the hospital’s computer system.', 43, '2018-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 10, 'Personal Jesus', 'A young boy is admitted to Grey Sloan Memorial and his case has a profound impact on the doctors. Meanwhile, April is faced with a surprising patient, and Jo continues to deal with her estranged husband.', 43, '2018-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 11, '(Don''t Fear) the Reaper', 'The stress of managing the hospital and coming to terms with Ben’s decision to become a Seattle firefighter pushes Bailey to her limits.', 43, '2018-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 12, 'Harder, Better, Faster, Stronger', 'April is in charge of the new Grey Sloan Surgical Innovation Contest, and the doctors are eager to start their projects. Meanwhile, Catherine’s old friend has a shocking idea for Catherine and Jackson; and Meredith treats a returning patient who inspires her project.', 43, '2018-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 13, 'You Really Got a Hold on Me', 'Seattle firefighters Ben Warren and Andy Herrera head to Grey Sloan after rescuing two boys who were injured in a house fire; the doctors work on their projects for the surgical innovation contest; Amelia brings Tom Koracick in to consult.', 43, '2018-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 14, 'Games People Play', 'Maggie''s relationship with Clive starts to progress; she invites him over for a game night to meet Meredith and Amelia; Meredith and Jo meet with the owner of the patent to the polymer they need for their project, who is a friend of the family.', 43, '2018-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 15, 'Old Scars, Future Hearts', 'Meredith tries to learn more about Marie Cerone''s history with her mother. Meanwhile, Jo is applying for fellowships around the country and it throws Alex for a loop; and Tom Koracick helps April acknowledge her crisis of faith.', 43, '2018-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 16, 'Caught Somewhere in Time', 'Maggie and Jackson are enjoying spending time together, but he must turn his concentration toward the groundbreaking vaginoplasty surgery he has scheduled with Catherine and Richard. Meanwhile, Meredith and Jo hit a roadblock with their contest submission, so Jo helps Bailey with an incoming trauma patient who used to be an astronaut', 43, '2018-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 17, 'One Day Like This', 'April''s crisis of faith is challenged by a patient she treats who is a rabbi, and Meredith treats a patient who is a transplant surgeon from another hospital.', 43, '2018-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 18, 'Hold Back the River', 'Amelia, Koracick and DeLuca perform a risky, groundbreaking procedure using ultrasound waves to remove a young patient’s brain tumor. Meanwhile, Meredith and Jo work with different polymers to try to salvage their project submission; and Richard’s AA sponsor is admitted to Grey Sloan with a DNR.', 43, '2018-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 19, 'Beautiful Dreamer', 'An agent from ICE shows up at Grey Sloan in search of an employee who may be working in the U.S. under DACA. Alex’s patient Kimmie wants to leave the hospital to enjoy her final days, but Alex feels differently. Meanwhile, Arizona treats Matthew Taylor’s baby and April wants to do whatever she can to help.', 43, '2018-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 20, 'Judgment Day', 'During presentations on Grey Sloan Surgical Innovation Prototypes Day, Arizona shares cookies from an appreciative patient that, unbeknownst to her, contain a special ingredient. Meanwhile, Catherine reveals shocking details to Jackson about his grandfather''s past; and Jo steps in mid-operation on a major surgery.', 43, '2018-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 21, 'Bad Reputation', 'The hospital brings in crisis management to help them sort out allegations against Harper Avery. Nurse Olivia shows up at Grey Sloan with her son, throwing Alex and Jo for a loop Arizona decides to spend more time with Sofia who is having a hard time at school.', 43, '2018-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 22, 'Fight for Your Mind', 'Alex and Jo go on a road trip to Iowa to find Alex’s mom, whom he hasn’t heard from in a very long time. Meanwhile, Meredith gives a presentation on her mini-livers project, which attracts a ton of attention; and Jackson works to rebuild the foundation after its reputation is threatened.', 43, '2018-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 23, 'Cold as Ice', 'One of Grey Sloan Memorial’s own is seriously injured, making the team reflect on what is truly important to them. Meanwhile, Nicole Herman pays a visit to Grey Sloan and talks to Arizona about an exciting opportunity.', 43, '2018-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 14), 24, 'All of Me', 'Meredith Grey and the team of doctors at Grey Sloan Memorial are faced with life-or-death decisions on a daily basis. They seek comfort from one another, and, at times, more than just friendship. Together they discover that neither medicine nor relationships can be defined in black and white.', 43, '2018-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 15, 'Season 15', 'Romance is brewing in ways you did not see coming as doctor Teddy Altman is back in an explosive love triangle. And the drama continues as a windstorm blows through Seattle, causing the power to go out at Grey Sloan, leaving the doctors scrambling to save their patients'' lives, including Meredith, who desperately needs to get to her patient for her heart transplant.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 1, 'With a Wonder and a Wild Desire', 'The doctors at Grey Sloan Memorial vie for a new position. Meredith is seemingly distracted and struggles to stay focused, and Maggie finds herself the keeper of a big secret while Amelia and Owen try to figure out their relationship. Meanwhile, Jo and Alex''s honeymoon doesn''t go exactly as planned.', 43, '2018-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 2, 'Broken Together', 'New doctors continue to shake up the hospital in typical Grey Sloan manner. Meredith bonds with a patient while Jackson struggles with the meaning behind recent experiences; and after making a life-changing decision, Jo forms an unexpected alliance.', 43, '2018-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 3, 'Gut Feeling', 'Meredith works on a patient who happens to specialize in matchmaking, and a seemingly drunk patient pushes Richard''s buttons and gives him a medical mystery to solve. Meanwhile, Maggie tries to reach Teddy after bearing the burden of her secret becomes overwhelming as she struggles with issues in her own personal life.', 43, '2018-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 4, 'Momma Knows Best', 'Meredith turns heads when she shows up to work done up and ready for her blind date later that day, while Alex makes a questionable decision in order to save a patient. Meanwhile, the burden of knowing Teddy’s secret keeps Maggie up at night, ultimately making her decide she has to tell someone.', 43, '2018-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 5, 'Everyday Angel', 'Meredith reaches out to Teddy and helps her talk through some of her personal struggles. Owen and Amelia hide out near Betty’s school after she becomes a flight risk. Meanwhile, Jo wants to get to work on the fellowship, but Bailey’s attention is elsewhere.', 43, '2018-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 6, 'Flowers Grow Out of My Grave', 'Meredith has a patient whose family is celebrating Day of the Dead, making the doctors remember loved ones they have lost. Richard shares unexpected news with Meredith about her father, Thatcher. Meanwhile, Teddy tries to tell Owen that she is pregnant but they get sidetracked, and Jo encourages Link to pursue one of the doctors.', 43, '2018-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 7, 'Anybody Have a Map?', 'Catherine is in Los Angeles getting the new foundation ready and summons Meredith and Koracick to visit for a highly confidential consult. Meanwhile, one of the nurses is 28 weeks pregnant and collapses at the hospital while talking to Richard.', 43, '2018-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 8, 'Blowin'' in the Wind', 'Seattle is hit by a huge wind storm and Grey Sloan becomes inundated with patients. Alex and Jo are stuck at home and decide to make the best of it by having a second honeymoon, while Meredith confronts Richard about getting his life back on track. The winter finale.', 43, '2018-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 9, 'Shelter from the Storm', 'When the power goes out at Grey Sloan, the doctors are left scrambling to save their patients'' lives; Owen, Amelia and Teddy confront their complicated situation.', 43, '2019-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 10, 'Help, I''m Alive', 'Meredith questions Link’s laid-back approach over a patient’s treatment. Maggie worries that Richard, Jackson and Catherine haven’t come to terms with Catherine’s diagnosis. Meanwhile, Deluca steps up in the O.R. when Owen faces a setback.', 43, '2019-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 11, 'The Winner Takes It All', 'Amelia and Koracick tackle a daunting surgery on Catherine while Richard and Jackson hope for the best. Meanwhile, Richard urges Meredith to visit her father, Thatcher, before his time is up.', 43, '2019-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 12, 'Girlfriend in a Coma', 'A patient gives Meredith some clarity on her dating situation around the holidays. The strain on Bailey and Ben’s marriage comes to a head. Meanwhile, Betty drops a bomb on Owen and Amelia.', 43, '2019-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 13, 'I Walk the Line', 'Patients flood the hospital after gunfire goes off at a parade; a blast from the past throws Maggie off her game on the same day that Meredith tries to talk to her about dating Deluca; Owen and Amelia get some potentially life-altering news.', 43, '2019-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 14, 'I Want a New Drug', 'Meredith breaks a hospital record; the doctors are sent scrambling in the wake of a massive overdose within the community; Jackson wants to take Maggie camping; Levi and Nico''s relationship continues to develop.', 43, '2019-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 15, 'We Didn''t Start the Fire', 'When Jackson throws a party to celebrate Catherine’s surgery and those who worked to save her, literally nothing goes as planned. Meanwhile, Helen pays Alex and Jo a surprise visit.', 43, '2019-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 16, 'Blood and Water', 'Meredith finds herself having to side with either Alex or DeLuca during a difficult situation, but she doesn’t want to betray either of them. Meanwhile, Maggie reveals details about her personal life that cause a public stir, and Levi struggles with whether or not to tell his family about Nico.', 43, '2019-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 17, 'And Dream of Sheep', 'Ties are strained as Andrew and Carina confront an unforgiving family history. Meanwhile, Teddy and Owen work together on a married couple who is expecting, and Amelia attends a conference for alternative pain relief.', 43, '2019-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 18, 'Add It Up', 'Maggie introduces mood rooms as an alternative approach to medicine. Alex and DeLuca butt heads over an 11-year-old patient who tries to sabotage her own surgery. Jackson and Richard deal with a gender non-binary patient. Meanwhile, Teddy has a pregnancy scare that brings Owen and Koracick to odds.', 43, '2019-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 19, 'Silent All These Years', 'When a trauma patient arrives at Grey Sloan, it forces Jo to confront her past. Meanwhile, Bailey and Ben have to talk to Tuck about dating.', 43, '2019-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 20, 'The Whole Package', 'Owen and Teddy have to deal with the surprise arrival of Megan Hunt, who knows nothing about their situation. Catherine preps for her first surgery back on a war veteran who’s not emotionally prepared for his procedure. Meredith worries about DeLuca operating alone with Richard.', 43, '2019-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 21, 'Good Shepherd', 'Amelia and Link travel to New York to operate on a patient with a severe spinal deformity, but they’re in for more than they bargained for when Nancy Shepherd invites them to dinner at her home.', 43, '2019-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 22, 'Head Over High Heels', 'Meredith debates how to handle an unexpected situation in her personal life, while Richard has an untimely reunion with an old friend. Jo has a hard time at work, and Owen tries therapy.', 43, '2019-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 23, 'What I Did for Love (I)', 'Maggie treats one of Station 19’s own, and Jo learns a hard lesson. Meanwhile, when working with a family seeking asylum, Meredith makes a call that could jeopardize her career.  The crossover continues on Station 19 S02E15 Always Ready (II).', 43, '2019-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 24, 'Drawn to the Blood', 'Alex tries desperately to save his patient Gus while he waits for a severely agoraphobic blood donor to arrive from London. Jo reveals to Meredith why she’s been so down, while Catherine and Bailey hold a meeting to get down to the bottom of an insurance issue. Meanwhile, Maggie and Jackson go camping.', 43, '2019-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 15), 25, 'Jump into the Fog', 'As fog begins to cover Seattle, the doctors of Grey Sloan navigate through personal complications. Meredith and Alex attempt to save Gus, while Levi talks some sense into a struggling Nico.', 43, '2019-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 16, 'Season 16', 'Meredith, Richard and Alex face the future after the insurance fraud scandal. The hospital gains a new leadership.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 1, 'Nothing Left to Cling To', 'Meredith, Richard and Alex must deal with the consequences after Bailey fires them from Grey Sloan for insurance fraud. After disappearing in the fog, Jackson helps a man in a dangerous situation, as his relationship with Maggie comes to a new crossroad. Meanwhile, Tom gets new responsibilities at the hospital that throw the doctors for a loop.', 43, '2019-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 2, 'Back in the Saddle', 'The doctors operate on a man who crashed into Maggie''s car as Owen, back from paternity leave, struggles with Tom''s new position. Meredith''s recent firing doesn''t stop her from diagnosing those around her. Richard and Alex start anew and it''s not easy.', 43, '2019-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 3, 'Reunited', 'A patient at the hospital is brain dead after falling into a construction site, and her two sisters must decide whether or not to keep her alive.', 43, '2019-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 4, 'It''s Raining Men', 'After Meredith inadvertently stirs up negative press for Grey Sloan, she tries to make things right with her former colleagues, jeopardizing her community service hours. Station 19’s Ben and Vic bring a young woman into the hospital, and Jackson stands up to Koracick when he goes too far with a patient’s family. Meanwhile, Bailey receives unexpected news; and Owen finds himself at Pac-Gen North, which Alex sees as a recruiting opportunity.', 43, '2019-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 5, 'Breathe Again', 'Meredith has a court hearing after skipping out on community service, while Bailey and Jo have a patient that Jo realizes is from the treatment facility. Richard and Gemma grab breakfast together and things go awry.', 43, '2019-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 6, 'Whistlin'' Past the Graveyard', 'Alex enlists Richard to help distract investors when he hears disturbing news about skeletons on the construction site grounds. Teddy tasks herself with creating original Halloween costumes for Allison and Leo.', 43, '2019-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 7, 'Papa Don''t Preach', 'Catherine is back in town and has no idea what’s been going on between Jackson and Maggie, while her relationship with Richard has become distant. Owen and Amelia treat a woman who fell in the basement and quickly realize that there is more to the story, and Maggie is shocked to learn about some of Richard’s relatives who are seeking help.', 43, '2019-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 8, 'My Shot', 'Meredith faces the medical board as her future as a doctor remains uncertain, and she’s forced to reckon with her past in some challenging ways. Meanwhile, the interns are put to the test as they are each vying to be the most successful on their respective cases in the absence of some of the attendings.', 43, '2019-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 9, 'Let''s All Go to the Bar', 'Jo becomes a safe haven volunteer and gets a call that a baby has been dropped off at Station 19. Meanwhile, Meredith moves forward with her life after facing the medical board. Jackson takes a big step in his budding romance with Vic, while Bailey and Amelia swap pregnancy updates.', 43, '2019-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 10, 'Help Me Through the Night (II)', 'Following the car crash at Joe’s Bar and subsequent rescue efforts led by the Station 19 firefighters, Grey Sloan doctors work through the night to save the lives of their colleagues. Meanwhile, Amelia worries about sharing her pregnancy revelation with Link. Owen and Teddy take a big step, and Bailey deals with grief over her recent loss.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 11, 'A Hard Pill to Swallow', 'Richard finds out Maggie quit Grey Sloan and is concerned about how she’s handling the death of her patient who was her estranged cousin. Bailey returns to work after taking some personal time off, although Koracick doesn’t make her first day as easy as she’d like. Meanwhile, Meredith thinks she might miss DeLuca, and Amelia has an update for Link on her pregnancy.', 43, '2020-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 12, 'The Last Supper', 'Jackson creates an uncomfortable situation when he invites new girlfriend, Vic, to what he thinks is Richard and Catherine’s anniversary celebration, only to discover the dinner was called for different reasons. Elsewhere, Levi brings Nico on a trip to visit an ailing family member.', 43, '2020-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 13, 'Save the Last Dance for Me', 'DeLuca can’t figure out what’s going on with his incurable patient Suzanne and he turns to a diagnostics genius, Dr. Riley from UCSF, for help. Bailey checks in on Joey, a foster kid that Ben brought into Grey Sloan. Meanwhile, Amelia is getting the results of her paternity test and Jo confronts her about how she is treating Link.', 43, '2020-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 14, 'A Diagnosis', 'DeLuca is irritated after Meredith takes over his patient Suzanne whose symptoms continue to stump the doctors at Grey Sloan. Elsewhere in the hospital, Jackson, Owen and Jo work on a couple injured in a bear attack; and Levi is hurt when Nico doesn’t want him to meet his parents.', 43, '2020-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 15, 'Snowblind', 'Meredith and Carina question DeLuca’s uncharacteristic behavior when he volunteers to perform a life-threatening task during a blizzard. Meanwhile, Bailey tries to help Joey with his future, while Richard trains a new intern at the hospital.', 43, '2020-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 16, 'Leave a Light On', 'Bailey and Ben face a huge, life-altering decision, while Meredith and several of the doctors reflect on the past.', 43, '2020-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 17, 'Life on Mars?', 'A wealthy inventor arrives at Grey Sloan and asks Koracick for help, while Meredith struggles to save a woman with diabetes who has been rationing her insulin. Jo and Link fight to save a young man who fell onto train tracks, and Jackson and Vic''s relationship hits a snag.', 43, '2020-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 18, 'Give a Little Bit', 'Meredith heads up a pro bono surgery day, but the overwhelming patient response causes her to struggle to keep things in order. DeLuca treats a teenage patient whom he suspects is in danger and desperately tries to get Bailey to support his theory.', 43, '2020-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 19, 'Love of My Life', 'Richard preps to present his PATH pen at the LA Surgical Innovation Conference but becomes distracted by his issues with Catherine. Maggie and Teddy run into people from their past at the same conference, while Hayes relives moments from when he met his late wife.', 43, '2020-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 20, 'Sing It Again', 'Owen and Link treat an older woman who wakes up from surgery and can’t stop singing, while Teddy helps Koracick stay afloat after an estranged loved one from his past comes to the hospital looking for help. Meredith, Bailey and Maggie focus their efforts on a difficult patient with a tricky diagnosis.', 43, '2020-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 16), 21, 'Put on a Happy Face', 'Link tries to convince Amelia to take it easy during the final stage of her pregnancy. Hayes asks Meredith a surprising question, and Owen makes a shocking discovery.', 43, '2020-04-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 17, 'Season 17', 'The COVID-19 crisis forces the doctors at Grey Sloan to face uncharted territory. The team struggles with the pandemic and personal turmoil.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 1, 'All Tomorrow’s Parties', 'The doctors of Grey Sloan Memorial must contend with the COVID-19 pandemic; an unintentionally started fire has first responders from Station 19 bringing patients into the hospital for treatment.', 43, '2020-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 2, 'The Center Won''t Hold', 'Bailey finds herself in the middle of an argument with patients'' families as they await news about their children who were injured in a fire; Winston surprises Maggie; Amelia and Link try to have some fun as new parents.', 43, '2020-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 3, 'My Happy Ending', 'The Grey Sloan doctors continue to face their new COVID-19 reality and deal with a familiar and stubborn patient. Koracick is put in charge of the interns who recently joined the hospital ranks and Link operates on a sex therapist. Elsewhere, Maggie finds comfort in Winston''s virtual presence.', 43, '2020-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 4, 'You''ll Never Walk Alone', 'Owen faces a medical diagnosis that challenges more than he imagined. Meanwhile, Koracick begins to go stir crazy; and Maggie gets a not-so-subtle glimpse into Winston''s background.', 43, '2020-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 5, 'Fight the Power', 'Bailey panics as she hears there has been a surge of COVID-19 cases, knowing she has loved ones in an assisted living facility. Meanwhile, Jackson and Richard team up against Catherine to teach her a lesson, and Teddy continues to try to mend her frayed relationships. After an intense surgery, Jo is uncertain about her future.', 43, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 6, 'No Time for Despair', 'Grey Sloan Memorial faces new pressures as Seattle Pres is overloaded, and Grey Sloan Memorial is now on surge capacity protocol. Meanwhile, Owen and Amelia are faced with one of the most controversial surgeries of their careers.', 43, '2020-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 7, 'Helplessly Hoping', '“Grey’s Anatomy” picks up where the previous episode of “Station 19” left off as both teams tend to a tense situation with so much at stake. Meanwhile, Jo convinces Hayes to bend the rules on a case, and Maggie and Winston reconnect.', 43, '2021-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 8, 'It''s All Too Much', 'As traumas and pressure mount, Grey Sloan doctors try to find a path forward, and Richard questions his faith. Meanwhile, Maggie gives Winston hospital privileges and they work together to treat an uneasy patient. Jo, Link and Jackson play an unconventional drinking game.', 43, '2021-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 9, 'In My Life', 'After a heart-wrenching loss, Teddy struggles to cope and it triggers memories of her past. When Owen brings her home, she must face some long-standing truths. Meanwhile, Amelia tries to help the situation by encouraging Owen to accept and forgive Teddy.', 43, '2021-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 10, 'Breathe', 'The hospital ventilator shortage has the doctors gravely concerned when both a mother and daughter are in critical condition with COVID and fighting over the last ventilator. Meanwhile, Hayes’ high-risk sister-in-law with multiple sclerosis ends up in the hospital with a kidney stone, and the sister house has a few more kids join it as Amelia plays babysitter for the day.', 43, '2021-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 11, 'Sorry Doesn''t Always Make It Right', 'The Grey Sloan doctors are stuck in the middle of a fight between a newlywed couple who are injured in a car accident and brought to the hospital for treatment. Meanwhile, Jackson’s generosity with COVID-positive patients goes a bit too far, and Hayes works to rebuild Maggie’s confidence and convince her to perform an extremely risky heart surgery.', 43, '2021-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 12, 'Sign O'' the Times', 'Maggie is preoccupied with Winston while trying to treat a patient wounded in the Seattle protests. Meanwhile, Levi is tested by an emergency, and the doctors struggle to treat a patient who doesn''t believe in COVID.', 43, '2021-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 13, 'Good as Hell', 'Amidst the need for more surgeons, Jo tries to convince Bailey to let her switch specialties. Elsewhere, Link accuses Amelia of overstepping while he is treating a patient remotely, and Winston comes up with an out-of-the-box idea.', 43, '2021-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 14, 'Look Up Child', 'Jackson pays a visit to his father that helps set him on the right path.', 43, '2021-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 15, 'Tradition', 'Jackson shares his big news with his colleagues while Koracick and Levi fight to save a pregnant woman’s grandfather as she goes into labor. Maggie keeps a watchful eye on Meredith as Bailey and Richard put off telling her about DeLuca.', 43, '2021-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 16, 'I''m Still Standing', 'Levi gets accepted into the vaccine trial. Meanwhile, Amelia and Owen treat a car crash patient, and Hayes and Jo are met with Luna’s legal guardian.', 43, '2021-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 17), 17, 'Someone Saved My Life Tonight', 'It’s wedding day for Maggie and Winston. Meanwhile, Meredith takes on a new role at the hospital, and Jo makes a life-changing decision.', 43, '2021-06-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 18, 'Season 18', 'In the aftermath of the COVID-19 pandemic, the doctors at Grey Sloan Memorial face a new set of problems — and Meredith considers a big life change.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 1, 'Here Comes the Sun (II)', 'As the city of Seattle revels at the Phoenix Fair celebrating the city’s rebirth post-COVID, the Grey Sloan doctors treat a patient who encounters illegal fireworks. Meanwhile, Bailey has her sights set on hiring new doctors, but she’s having trouble finding viable options. Owen and Teddy attempt to take the next step in their engagement, and Meredith has a surprising opportunity when she meets a dynamic doctor from her mother‘s past.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 2, 'Some Kind of Tomorrow', 'Meredith seeks advice from Amelia. Meanwhile, Richard is reenergized as he takes teaching to a new level at the hospital, and Winston treats a patient suffering from kidney failure.', 43, '2021-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 3, 'Hotter Than Hell', 'Seattle’s favorite redhead returns and graces the Grey Sloan halls with her experience and expertise as she attempts to help Richard teach the newest crop of residents. Meanwhile, Meredith has a decision to make, and Link confides in Teddy.', 43, '2021-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 4, 'With a Little Help from My Friends', 'Richard recruits Meredith and Bailey to help him launch a new program. Meanwhile, Addison’s patient has complications from a procedure, and Jo helps a woman who goes into premature labor.', 43, '2021-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 5, 'Bottle Up and Explode!', 'The Grey Sloan doctors spring into action after an explosion rocks Seattle, with the incoming trauma hitting close to home. Owen experiences PTSD after he hears the explosion, while his sister Megan enlists help from Winston and Hayes in confidence. In Minnesota, Meredith and Amelia meet up with a familiar face who assists in their study.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 6, 'Every Day is a Holiday (With You)', 'It''s Thanksgiving, and while Meredith faces travel complications due to the weather, Nick steps in to help in more ways than one; Richard and Bailey seek out emergency surgeries; Amelia and Link reconnect.', 43, '2021-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 7, 'Today Was A Fairytale', 'Dr. Hamilton takes his frustrations out on Meredith, so Nick gives her a chance to blow off steam by scrubbing in on a surgery. Back in Seattle, Link and Jo take their kids to a fairytale theater performance that goes wrong. Bailey and Dr. Lin attend a recruitment fair in hopes of attracting more doctors to Grey Sloan but find themselves ill-prepared.', 43, '2021-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 8, 'It Came Upon A Midnight Clear', 'The doctors celebrate the holidays; Hamilton and Meredith prepare for a milestone on their project; Link wants to spend the holiday with Amelia and Scout as a family; Schmitt is faced with a difficult decision during surgery.', 43, '2021-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 9, 'No Time To Die', 'The Grey Sloan Memorial doctors grapple with the aftermath of the car crash that involved some of their own; Meredith works to save Dr. Hamilton''s life. Levi is impacted from his latest loss.', 43, '2022-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 10, 'Living in a House Divided', 'Schmitt must face the Morbidity and Mortality conference. Meanwhile, Meredith convinces Nick to scrub in on a surgery in Seattle, and Jo faces her feelings.', 42, '2022-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 11, 'Legacy', 'While Meredith, Amelia and the team prepare for Dr. Hamilton’s long-awaited, groundbreaking surgery, Bailey receives an unexpected offer. Owen’s impatience makes him a difficult physical therapy patient, forcing Link to intervene. In Minnesota, Nick makes a liver transplant a teaching moment.', 44, '2022-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 12, 'The Makings Of You', 'Nick whisks Meredith away to his Minnesota cabin for a romantic weekend, leaving Winston and Maggie to care for Meredith’s children. Meanwhile, Amelia and Kai grow closer.', 42, '2022-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 13, 'Put The Squeeze On Me', 'While Richard ponders his surgical abilities, Jo is charmed by her patient’s brother. Elsewhere, Megan makes sure Teddy and Owen talk out their differences, and a pet python causes an uproar.', 43, '2022-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 14, 'Road Trippin’', 'Tensions at Grey Sloan Memorial rise as the effects of the physician shortage begin to show. Meanwhile, Meredith struggles to step away from work as she spends a sick day at home with Zola, and the hospital receives an unexpected visitor.', 43, '2022-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 15, 'Put It To The Test', 'Bailey is on edge when an accreditation council stops by Grey Sloan to review the residency program, while Richard sets an assessment of his own for the same day. Meanwhile, Nick returns to Seattle to perform a first-of-its-kind operation with Meredith.', 42, '2022-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 16, 'Should I Stay or Should I Go?', 'Bailey faces an unhappy Catherine who is facing audits for several of her Foundation hospitals. Meanwhile, Addison is back at Grey Sloan; tensions rise between Meredith and Richard, and Owen returns to work.', 43, '2022-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 17, 'I''ll Cover You', 'A former patient of Link’s, Simon, is in the ER with his pregnant wife; and Bailey receives an offer from Nick.', 43, '2022-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 18, 'Stronger Than Hate', 'A dinner party is thrown at the sister house in Nick''s honor. Meanwhile, Grey Sloan Memorial receives a victim of a brutal hate crime.', 43, '2022-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 19, 'Out for Blood', 'Due to a blood shortage, Grey Sloan Memorial is setting up a voluntary donation center. Meanwhile, Nick asks Meredith for help with his patient and Winston is hung up on his relationship with his brother.', 43, '2022-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 18), 20, 'You Are the Blood', 'The blood shortage at Grey Sloan Memorial continues. Meanwhile, Meredith makes a risky decision regarding a patient, and Owen’s actions to help his fellow veterans come to light.', 43, '2022-05-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 19, 'Season 19', 'Six months after Grey Sloan Memorial lost its residency program, the hospital sees a slew of changes — from new arrivals to major goodbyes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 1, 'Everything Has Changed', 'After a long six months, Grey Sloan Memorial has reinstated its residency program. A group of talented and striving young interns has been recruited as the attending surgeons work to rebuild the program to its former glory. Meredith, still functioning as the interim chief, sees Nick for the first time since she rejected his offer to move to Minnesota. Meanwhile, Bailey tells Richard she is not ready to return to work. Levi works up the courage to break disappointing news to Jo, and things turn awkward when Link realizes he has met one of the interns already. With Amelia and Maggie’s help, the new doctors are thrown into their first day on the job dealing with injuries from a recent tornado.', 46, '2022-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 2, 'Wasn''t Expecting That', 'The attending surgeons and interns work together to solve a medical mystery when a college kid comes in with what first looks like food poisoning but has escalating and dire complications. Meanwhile, Jo spends her day off with Bailey.', 41, '2022-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 3, 'Let''s Talk About Sex', 'Bailey recruits the interns to create a series of social media videos informing teens about sexual health. The videos, filmed at Grey Sloan in front of a group of high schoolers, hit home as a student has medical complications during her visit. Elsewhere, Meredith and Maggie learn something new about Zola.', 44, '2022-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 4, 'Haunted', 'It’s Halloween night at Grey Sloan Memorial. Meredith and Nick try to spend some alone time together; Levi is stressed due to overworking, and Winston and Owen have the interns practice trauma training on a real cadaver.', 44, '2022-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 5, 'When I Get to the Border', 'Bailey and Addison take a road trip to volunteer at a family planning center, but a patient’s ectopic pregnancy leads to complications. Elsewhere, the interns play detective about Lucas’ relationship with Amelia, and Meredith catches up with Jackson on a trip to Boston.', 41, '2022-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 6, 'Thunderstruck', 'On the heels of life-changing news, a thunderstorm hits Grey Sloan. The attending surgeons and interns work together to save an injured reporter and family affected by the storm. Meanwhile, a beloved author undergoes a risky surgery, and complications from the storm arise.', 44, '2022-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 7, 'I''ll Follow the Sun', 'It’s Meredith’s last day at Grey Sloan Memorial and the doctors plan a goodbye surprise, while Nick confronts her about the future of their relationship. Elsewhere, the interns compete to scrub in on Maggie and Winston’s groundbreaking partial heart transplant procedure, and Richard asks Teddy an important question.', 45, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 8, 'All Star', 'Teddy makes a challenging decision. Meanwhile, Maggie and Winston aren’t on speaking terms, and Link leans on Jo for emotional support as he preps for a surgery on a well-known athlete. Simone and Lucas are surprised by an unlikely visitor.', 44, '2023-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 9, 'Love Don''t Cost a Thing', 'Simone is met with a life-changing decision upon the return of someone from her past. Blue shadows Maggie on a risky procedure, while Jo and Link tend to a pregnant woman. At the intern house, Lucas and Mika throw a party filled with surprises.', 45, '2023-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 10, 'Sisters Are Doin'' It for Themselves', 'Catherine returns to Grey Sloan for a surgical case that makes Lucas and Blue queasy. Amelia treats a possible cancer patient with a family that’s a little too supportive. Owen takes his medical future into his own hands, much to Teddy’s surprise.', 43, '2023-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 11, 'Training Day', 'Addison makes a special appearance at Grey Sloan to welcome Bailey’s new OB/GYN trainees. Maggie’s lung transplant is derailed, and Nick bonds with Lucas — before the day takes a shocking turn.', 43, '2023-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 12, 'Pick Yourself Up', 'In the immediate aftermath of shocking events at the clinic, the hospital goes on lockdown and the Grey Sloan doctors split up to save multiple lives; Maggie lands in hot water with Winston; Jules'' roommate makes a surprise appearance.', 42, '2023-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 13, 'Cowgirls Don''t Cry', 'A bull rider shows up at Grey Sloan with severe injuries, forcing Maggie, Amelia, Owen and Blue to examine their own biases. Elsewhere, Simone can’t find anyone to be her maid of honor, and Mika takes drastic measures to pay down her student debt.', 43, '2023-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 14, 'Shadow of Your Love', 'It’s Maggie’s last day. Amelia’s relationship with Kai is tested, and Ben worries as Bailey’s doxing intensifies.', 44, '2023-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 15, 'Mama Who Bore Me', 'With Levi’s help, a patient celebrates a milestone. Jo processes a difficult diagnosis, and Maggie and Winston decide their future.', 44, '2023-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 16, 'Gunpowder and Lead', 'Amelia takes her personal problems out on her work colleagues, and the threats against Bailey come to a terrifying head. Lucas and Jules make a risky decision on a patient, and Mika struggles with burnout.', 43, '2023-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 17, 'Come Fly with Me', 'Teddy calls an emergency meeting to discuss the intern program. Link wrestles with his own self-doubt as he preps for a massive surgery, and Nick shares some much-needed guidance with a struggling Lucas.', 43, '2023-05-04');
