INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 19, 'Wedding Bell Blues', 'Simone''s wedding day arrives as Jo and Link''s relationship hits a major turning point.', 42, '2023-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 19), 20, 'Happily Ever After?', 'The attending surgeons fly to Boston, forcing a reunion between Nick and Meredith. Bailey gets a big surprise.', 44, '2023-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 20, 'Season 20', 'The interns face new challenges as they grow into their roles, while the hospital recovers from a major health crisis involving Teddy. Meredith appears briefly, continuing her research in Boston. Bailey, Richard, Jo, and Link guide the next generation through high-stakes surgeries and personal drama.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 1, 'We''ve Only Just Begun', 'Meredith rethinks her plans. The interns are on thin ice following a patient''s death. Simone and Lucas are immediately tested in an emergency. Richard confides in Bailey. Teddy''s fate is revealed.', 44, '2024-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 2, 'Keep the Family Close', 'Bailey tells the interns they must complete dozens of basic procedures before being allowed back in surgery; things are awkward between Simone and Lucas; Amelia comes up with a solution to a complicated surgery.', 43, '2024-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 3, 'Walk on the Ocean', 'Meredith and Amelia work to secure funds for their research while Amelia finds herself at odds with a new attending. Levi runs into someone from his past, and Owen gives Winston advice. Lucas ditches Mika, forcing her to treat a patient alone.', 43, '2024-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 4, 'Baby Can I Hold You', 'Dr. Arizona Robbins returns to Grey Sloan for a particularly complicated case. The interns are interrogated about their past mistakes, while Teddy is eager to return to work after her health scare.', 44, '2024-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 5, 'Never Felt So Alone', 'It''s all hands on deck at Grey Sloan when a group of medical students is injured by a floor collapsing at their white coat party. Jo and Link are forced to talk about the future, while Jules confronts Winston about his attitude.', 44, '2024-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 6, 'The Marathon Continues', 'Mika and Teddy receive a patient from a nearby penitentiary. Catherine pushes back on Link and Monica''s treatment plan for a VIP. Bailey tries to integrate wellness into the residency program.', 43, '2024-05-02');
