INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 8, 'Blood, Sweat and Tears', 'Owen and Teddy have the day off but encounter an injured civilian. Monica enlists Amelia''s help with an operation on a young patient. The interns complete their procedure logs, allowing them back into the OR.', 43, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 9, 'I Carry Your Heart', 'Just as Amelia comes to a realization, Teddy encourages her and Meredith to speed up their Alzheimer''s research over fear of Catherine finding out. Mika finds herself caught in the middle of Link and Jo; meanwhile, Lucas receives bad news.', 44, '2024-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 20), 10, 'Burn It Down', 'Wildfires threaten the Seattle region, leading to a flood of patients and emergency procedures. The doctors juggle overcapacity in the ER, complex surgeries and personal stress. Meanwhile, Meredith makes a rash decision that can''t be undone.', 44, '2024-05-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')), 21, 'Season 21', 'The story deepens as the new doctors step into leadership. Emotional fallout from the past season lingers, and big decisions shape the future of Grey Sloan. Legacy characters and fresh faces continue to balance life, loss, and medicine.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 1, 'If Walls Could Talk', 'After firing some of Grey Sloan''s best, Catherine continues to interfere with Meredith and Amelia''s research. Accidents at a climate change protest bring unique cases to the hospital, and Bailey encounters a blast from the past.', 44, '2024-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 2, 'Take Me to Church', 'Meredith and Catherine continue to disagree, and Meredith confides in Bailey for support. Richard, Winston and Lucas spend the day outside of the hospital, and Blue deals with a relationship from his past. Levi meets the new hospital chaplain.', 43, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 3, 'I Can See Clearly Now', 'Simone and Lucas work to balance their relationship while competing to assist on an awake kidney transplant. Teddy offers Amelia a new opportunity, and Ben''s interview doesn''t go as planned. Meredith''s secret causes tension with Richard.', 43, '2024-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 4, 'This One''s for the Girls', 'Mika struggles with a life-altering personal matter. Meanwhile, Bailey and Ben navigate their personal and professional roles, while Levi finds a connection in an unlikely place. Jo and Link get surprising news.', 44, '2024-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 5, 'You Make My Heart Explode', 'During a high-stress day at Grey Sloan Memorial, the fates of a patient in critical condition and a helicopter-bound medical team hang in the balance. Teddy and Owen work on their marriage, while Bailey, Blue and Link treat a hospital employee.', 44, '2024-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 6, 'Night Moves', 'Teddy and Owen plan a date night that gets derailed in more ways than one, while Jo struggles to do it all at home. Mika adds more to her plate to make up for taking time off to be with her sister, and Levi is faced with a monumental decision.', 44, '2024-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 7, 'If You Leave', 'The doctors at Grey Sloan must put aside their emotions under intense circumstances. Levi asks James a shocking question that could impact their future.', 44, '2024-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 8, 'Drop It Like It''s Hot', 'In the midst of a deadly heat wave, the team at Grey Sloan struggles to keep up with an overwhelming amount of patients. Amelia and Winston face a challenging surgery, while Jo and Lucas run an errand for the hospital that takes an unexpected turn.', 44, '2024-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 9, 'Hit the Floor', 'The aftermath of the convenience store shooting brings chaos to Grey Sloan. Ben hits a wall with his new emergency preparedness plan. Romantic tensions surface for Owen, while Amelia and Winston disagree over the surgical plan for a young patient.', 43, '2025-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 10, 'Jump (For My Love)', 'Meredith and Nick return to Grey Sloan to treat a liver transplant patient. Meanwhile, Bailey hosts an intern retreat at her home, and Winston and Ben aid an unexpected crash victim.', 43, '2025-03-13');
