INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 14, 'Love in the Ice Age', 'Bailey welcomes a renowned surgeon, whom she greatly admires, to Grey Sloan to help on a challenging case. Meanwhile, Teddy, Owen, Jules and Ben team up to save the life of a patient who has been impaled by an ice pick.', 44, '2025-04-10');
