INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 21), 18, 'How Do I Live', 'While the interns are excited to transition to second-year residency, an ordinary day at Grey Sloan takes an unexpected turn when a medical emergency unfolds in the operating room, endangering lives inside the hospital.', 44, '2025-05-15');
