INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 22), 1, 'Only the Strong Survive', 'After the catastrophic hospital explosion, Grey Sloan''s staff scrambles to save not only their patients'' lives but also their own. Confronted with impossible surgical decisions and emotional turmoil, they fight to preserve life amid devastation.', 43, '2025-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 22), 2, 'We Built This City', 'The team at Grey Sloan navigates a chaotic first day of surgical rotations amid hospital renovations. Meanwhile, Meredith spends time with Amelia.', 44, '2025-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 22), 3, 'Between Two Lungs', 'A high-risk lung transplant pushes the surgical team to their limits. Meanwhile, Bailey juggles a trauma patient whose treatment hangs in the balance.', 43, '2025-10-23');
