INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0413573')) AND numero_temporada = 22), 10, 'Strip That Down', 'Addison Montgomery returns to Grey Sloan, seeking assistance with a patient with a neurological condition. Bailey joins Owen and Blue on a paramedic ride-along.', 44, '2026-01-29');
