INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 1, 'Herr Dr. Tenma', 'Dr. Kenzo Tenma, a leading neurosurgeon at the Dusseldorf Hospital has received massive acclaim for his successful surgery on a famous opera singer. However, he is burdened by guilt. Due to pressure from the director, he had operated on the opera singer on the night that he was supposed to operate on another man. As a result, when the director’s orders him to operate on the mayor, he decides to ignore the order and instead works on saving the life of a young boy, brought to the hospital from the scene of a serial homicide. However, the boy''s twin sister, who was brought in with the boy, and who still suffers from shock, keeps repeating the words ''kill him''.', 24, '2004-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 2, 'Downfall', 'The price for disobeying Dr. Heinemann''s orders to operate on the mayor is costly for Dr. Tenma. His career begins to plummet. The boy whom he saved finally awakens, but a horrible incident occurs soon after.', 24, '2004-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 3, 'A Murder', 'Things look brighter for Dr. Tenma, now that Dr. Heinemann is dead. His career takes off, and even Eva tries to win him back. But unfortunately, all that success has drawn the attention of Detective Lunge.', 24, '2004-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 4, 'Night of the Execution', 'Adolf Junkers has information about the serial murders that is vital to the police, but he is afraid to reveal them. Dr. Tenma''s care for Adolf Junkers however wins him over. His close relationship with Junkers however leads him to a night of shocking horror.', 24, '2004-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 5, 'The Girl of Heidelberg', 'Nina Fortner, a talented young student in Heidelberg has been having nightmares. She also cannot remember anything about her life before she was 10 years old. She soon suffers from fainting spells in university and starts receiving anonymous emails.', 24, '2004-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 6, 'The Missing', 'Nina finally receives an email informing her to meet the anonymous sender at a specified time and place. Dr. Tenma in his search for the Liebert girl, asks Mauler, an editor for a local publisher, for assistance in his investigations.', 24, '2004-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 7, 'House of Tragedy', 'Tenma and Nina return to the Fortners’ residence to find Mauler and Nina’s parents dead. Two detectives arrive to take them to the station for questioning, but certain things don''t look right.', 24, '2004-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 8, 'Pursued', 'Eva tries to threaten Dr. Tenma, unless he gets back with her, she would reveal to the police that the tie that was found at the scene of the crime is his!', 24, '2004-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 9, 'The Girl and the Seasoned Soldier', 'An old mercenary soldier named Hugo is interrogated by Lunge about a student of his, a doctor named Tenma.', 24, '2004-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 10, 'A Past Erased', 'Tenma encounters a burglar named Heckel who claims to have seen the killer. It soon results in Heckel leading Tenma to a couple of murderers.', 24, '2004-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 11, '511 Kinderheim', 'Tenma learns that Johan used to be in an orphanage known as Kinderheim 511. And he meets a former East German official named Hartmann who used to work there and an injured boy named Dieter.', 24, '2004-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 12, 'A Little Experiment', 'Dieter is picked up by Hartmann before Tenma could return. And Tenma learns more about the experiments in Kinderheim 511.', 24, '2004-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 13, 'Petra and Schumann', 'In a small village, Dr. Schumann worries over the health of his sick but stubborn old friend, Petra.', 24, '2004-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 14, 'Left Behind', 'Inspector Lunge investigates the murder of a prostitute and suspects a senator named Dr. Boltzmann of involvement. His dedication to his work however takes a toll on his family life. Meanwhile, the vindictive Eva continues to press Lunge to catch Tenma. She also has a new lover, her gardener.', 24, '2004-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 15, 'Be My Baby', 'Dr. Tenma and Nina Fortner''s investigations lead them to a powerful man known as ''The Baby'', who belongs in an extremist organisation. They soon learn that the organisation has special plans for the Turkish district tomorrow.', 24, '2004-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 16, 'Wolf''s Confession', 'Nina escapes the mansion. And Tenma meets with the unrecognizable General Wolf at the mansion later.', 24, '2004-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 17, 'Reunion', 'The extremists plans are put into action, and Tenma decides to postpone his search for Johan and instead heads to the Turkish district to warn the people there. Dieter and Heckel are captured by the skinheads and are left to burn in the fire. And Nina tries to get information about the ''main dish'' from ''The Baby''.', 24, '2004-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 18, 'Five Sugars', 'Nina meets with an old friend and boss, Mister Rosso. The delightful old boss however, has a very dark past.', 24, '2004-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 19, 'Monster''s Abyss', 'Tenma visits Rudy, a criminal psychologist, who is working on cases involving a murderer named Jurgens.', 24, '2004-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 20, 'Journey to Freiham', 'Tenma and Dieter hitch a ride with an elderly couple on the way to Freiham. Tenma wonders if the couple plan to turn him in.', 24, '2004-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 21, 'Happy Holidays', 'Nina confronts Muller, one of the two detectives responsible for the death of her foster parents, the Fortners. Muller discovers that his protege, Roberto, is actually working for Johan and is now tasked with killing Nina.', 24, '2004-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 22, 'Lunge''s Trap', 'Lunge determines that the murder of a wealthy, middle-aged, childless couple does not fit the usual modus operandi of the serial murders and decides to use this opportunity to lure Tenma to a trap. However, before he can arrest him, Lunge is critically wounded by the real criminal. Tenma is able to treat Lunge''s injuries.', 24, '2004-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 23, 'Eva''s Confession', 'Eva Heinemann is arrested for public drunkenness and hooks up with Roberto, with whom she was with the night before her arrest. Roberto then reveals his link to Johan and Eva confesses that she was actually a witness the night Junkers was killed by Johan.', 24, '2004-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 24, 'Of Men and Dining', 'In exchange for her life, Roberto tells Eva to confront Tenma, who is currently treating a mob boss at a country house. Eva is promptly wounded by Roberto when she is unable to complete her task but is saved by Tenma.', 24, '2004-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 25, 'Thursday''s Boy', 'Karl Neumann and Lotte Frank are both students who read latin to Hans Georg Schubert. Lotte attempts to assist Karl in finding out his past while trying to figure out the identity of a boy who reads to Schubert on Thursdays. When they both discover who he is, they find the boy, Edmund Farren, in his dormitory, dead.', 24, '2004-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 26, 'The Secret Woods', 'A man who claims to be the son of a millionaire has committed suicide, and a detective is determined to solve the case.', 24, '2004-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 27, 'Proof', 'Richard''s past and present situation is revealed. Johan continues to bond with the Schuwald family and his intention is revealed.', 24, '2004-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 28, 'Just One Case', 'Richard re-investigates his old homicide cases and makes a frightening discovery.', 24, '2004-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 29, 'Execution', 'Robert delves into Johan''s past and makes a shocking discovery. Dr. Gillen speaks to Peter Jurgens, a serial murderer about Johan''s possible involvement and gets a tragic reply. Johan confronts Robert about Stephen Joos. And Dr. Reichwen receives tragic news from the police.', 24, '2004-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 30, 'Decision', 'Suspecting foul play in Robert''s ''accidental'' death fall, Dr. Reichwen makes some discoveries in his investigations. But as he later realizes, his investigations may have put him in harms way.', 24, '2004-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 31, 'In Broad Daylight', 'Dr. Tenma and Dr. Reichwen finally meet. Dr. Reichwen intends to proof Dr. Tenma''s innocence in the homicides, but Dr. Tenma has other ideas.', 24, '2004-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 32, 'Sanctuary', 'Lotte, Frank and Karl are drifting apart. Lotte meets Nina Fortner and they become friends. Dr. Tenma searches for a perfect spot to shoot Johan.', 24, '2004-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 33, 'A Child''s View', 'Dieter learns of a life threatening game that children are playing. Mr. Schuwald decides to donate his whole book collection to the Munich University Library under the suggestion of Karl and Johan.', 24, '2004-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 34, 'At the Edge of Darkness', 'The ''Margot Langer'' impostor tries to blackmail Johan. Dr. Tenma helps a young ''doctor'' at an illegal clinic', 24, '2004-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 35, 'My Nameless Hero', 'Lunge tries to get into Dr. Tenma''s mind by pretending to be him. Dr. Gillen learns something about Johan during an interview with a psychotic killer. Dr. Reichwen tries to warn the Lieberts of Johan''s true nature. Dr. Tenma scouts for a perfect sniping location.', 24, '2004-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 36, 'The Monster of Chaos', 'Dr. Reichwein reveals the true nature of Johan to Mr. Schuwald. Dr. Tenma gets ready to assassinate Johan. Lunge concludes that Dr. Tenma will kill Schuwald next. Lotte confronts Nina about Johan.', 24, '2004-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 37, 'A Nameless Monster', 'The episode begins with a fairy tale about a Monster without a name. Nina reads the story from the picture book and has a sense of deja vu. Johan''s evil plans for the book donation ceremony is carried out. Dr. Tenma meets a big obstacle in his attempt to kill Johan.', 24, '2005-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 38, 'The Demon in My Eyes', 'Dr. Tenma has a gun pointed at Roberto, but Roberto has the rifle pointed at him. Nina, Dr.Reichwen and Dieter arrive to find the whole library in flames. People are trapped inside and the doors are all locked. Karl reads the report on his mother''s life and death. Dr. Tenma tries to rescue those trapped in the building. Johan reveals the monster inside of him to Schuwald.', 24, '2005-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 39, 'The Hell in His Eyes', 'Lunge, from the BKA, learns that Johan may indeed exist. Nina goes into regressive hypnosis to learn more about the picture book and her past. Mr. Schuwald has a message for Dr. Tenma and sends Karl to Dresden to pass it to him.', 24, '2005-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 40, 'Grimmer', 'The episode introduces Grimmer. Grimmer is a freelance journalist doing an in-depth research into the abuses in the orphanages in East Germany. Grimmer meets with Dr. Tenma during their trip to Prague, and they become more acquainted when Tenma is faced with an immigration problem.', 24, '2005-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 41, 'Ghosts of 511', 'Grimmer stubbornly stalks Petrov for his experimental research papers chronicaling the abuses at Kinderheim 511, but he gets a surprise instead.', 24, '2005-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 42, 'The Adventures of the Magnificent Steiner', 'Grimmer has the key that Petrov gave him, and a former Czechoslovakian secret police organization wants it. Caught and tortured, Grimmer tells his abductors about ''the Magnificent Steiner''.', 24, '2005-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 43, 'Detective Suk', 'A new inspector, detective Suk is on the case of Zeman''s homicide. During his investigation, he discovers that there is more to Zeman''s murder than first assumed. Suk also meets a lady whom he falls head over hills for', 24, '2005-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 44, 'Double Darkness', 'After the death of his seniors, Suk is left to re-investigate case from the very beginning. He gets information from the orphans about a meeting with Grimmer. His intention to arrest Grimmer takes a different turn however when he gets deeper into the investigation. The episode also reveals that there is more to the nameless lady at the bar than she lets on.', 24, '2005-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 45, 'The Monster''s Afterimage', 'Suk is put under surveillance by the new commissioner. Together with Grimmer, Suk retrieves the tape and research papers from the deposit box. But their movements is watched by various sides.', 24, '2005-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 46, 'Contact', 'Dr. Tenma learns about Suk''s fugitive status from a journalist. And sets out to find him. Meanwhile, Suk and Grimmer goes into hiding, but is quickly found, surrounded and attacked by the STB. The STB''s assault comes to a bloody end.', 24, '2005-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 47, 'The Door to Nightmares', 'Nina''s experience in Prague is a nightmare for her. Tenma and Grimmer meets with a top man in the Czechoslovakian STB. They are offered a deal which Grimmer refuses to accept.', 24, '2005-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 48, 'The Scariest Thing', 'Johan visits Suk''s mother. Tenma and Grimmer learns of his visit. They, including Col. Ranke, listen to Johan''s tape. Lunge arrives in Prague for a ''holiday''. His investigation leads him to the sketches of Franz Bonaparta.', 24, '2005-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 49, 'The Cruelest Thing', 'Grimmer and Tenma tries to stop Johan from subjecting Milo, one of the orphans, to one of the most cruel fate.', 24, '2005-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 50, 'The Rose Mansion', 'Lunge investigates the secret behind the Red Rose Mansion. Tenma and Grimmer separate, but Tenma finds himself in trouble.', 24, '2005-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 51, 'The Monster''s Love Letter', 'Schubert, with the help of Reichwein, re-explores his past with Karl Neumann''s real mother and realizes his link to Johan. As news of Tenma''s arrest spreads, various people react with shock and horror, with the exception of Eva Heinemann, who is insistent that Tenma pay dearly for rejecting her. Suk tries to leave the hospital he is in to try to help Tenma, but is stopped by the Prague Police who inform him that Grimmer has sent a note to them exonerating Suk from any involvement of the deaths of the police officers. Runge also gets news of the arrest as well, but he is more interested in the Mansion of Red Roses, where he obtains a letter possibly addressed to the twins'' mother. Tenma is deported back to Dusseldorf.', 24, '2005-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 52, 'The Lawyer', 'Former patients of Eisler Memorial Hospital enlist the aid of Alfred Baul, a lawyer, to represent Tenma. Baul in turn asks for the assistance of Fritz Vardemann. Vardemann visits Tenma in prison, and agrees to take on the defense, but is then called to the hospital when his wife goes into labor with their first child. When Baul visits Tenma in prison, Tenma is shocked to see that Baul is Roberto. Roberto then says that Eva Heinemann will be his next target.', 24, '2005-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 53, 'Determination', 'After hearing Roberto''s threat against Eva, Tenma decides to confess to all charges against him so he can be placed in the same van transporting a prisoner to a Federal Penetentary as the prisoner is arranging for a jailbreak.', 24, '2005-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 54, 'The Escape', 'Tenma and Milch are on the run with the injured Gustav and Helene. Eva finds her life in danger when she discovers that the attorney she''s supposed to meet, Mr.Baul, is none other than Roberto.', 24, '2005-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 55, 'Room 402', 'Dr. Tenma takes Verderman hostage in a desperate search for Eva. And Verderman''s dark past is revealed.', 24, '2005-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 56, 'The Neverending Journey', 'Nina and Dieter enters the Red Rose Mansion, but Nina faints from her disturbing experience. And they end up in the care of a puppeteer name Lipsky.', 24, '2005-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 57, 'That Night', 'A flashback to Johan’s and Nina’s past, to the time before the Liebert’s homicides reveals the reason behind Johan’s killing. Police makes a startling discovery at the burnt down mansion. Tenma finally learns where Eva is. And Lunge reveals Lipsky’s true identity.', 24, '2005-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 58, 'I Hate This Job', 'Martin, a hired hand, is hired by General Wolf''s ex-associates to ‘take care’ of Eva. But his emotions get in the way of his orders.', 24, '2005-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 59, 'The Man Who Saw the Devil', 'Tenma manages to find Martin. A drunken Eva spots Johan at a party. Martin receives his final orders from his boss but his feelings gets in the way. And Martin gets way over his head when he tries to investigate Johan and his disciple, and the truth about his past is revealed.', 24, '2005-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 60, 'The Man Who Knew Too Much', 'Martin’s attempt to save Eva costs him his life, his last minutes with Tenma reveals a terrible secrets about Martin’s boss, Peter Chapek and the about the experiments.', 24, '2005-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 61, 'The Door to Memories', 'Nina returns to the apartment that she lived in with her mother and Johan and encounters another memory. She then returns to Munich and Dr. Reichwein where she volunteers for hypnosis to find the truth behind these memories. After she nearly kills Dr. Gillen in a hypnotic rage, she leaves Dr. Reichwein''s house to try to stop Tenma from killing her brother. Meanwhile, Suk and Vardemann team up to interview former residents of the Mansion of Red Roses to gather information on Franz Bonaparta''s reading sessions with his picture books, and for Vardemann to find out more about his father''s true involvement.', 24, '2005-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 62, 'A Pleasant Dinner Table', 'While trying to escape from police in Frankfurt, Tenma is hit by a van. He awakes in the Turkish Quarter of the city, the same one that he saved from The Baby''s plot. The man who saved him plans to kill Petr Capek at a convention, but he fails at this task and is shot dead. Nina, in Frankfurt, sees the picture of Petr Capek and it triggers yet another memory.', 24, '2005-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 63, 'Unrelated Murders', 'Egon Weisbach was one of the first investigators in the murder of the Liebert parents. On his last day on the job before retirement, he is escorting a convicted serial murderer but wants to know why he killed someone who did not fit his modus operandi. At the same time, Dr. Gillen is interviewing several murderers wondering why they killed someone who also did not fit their usual targets. Both realize that all these criminals committed murders outside their usual scope at the request of a young man, presumably Johan.', 24, '2005-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 64, 'The Baby''s Depression', 'The Baby is killed by a prostitute, and his death sends shockwaves in Petr Capek''s organization. Capek becomes paranoid as to who is loyal or not and accidentally kills one of his guards. He makes it to his cottage where Johan is waiting for him.', 24, '2005-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 65, 'Johan''s Footprints', 'Capek tries to berate Johan for his actions and tells him that everything should be done according to Capek''s plans but Johan simply disagrees and disappears. Capek realizes his hold on his organization is crumbling and has his men pick up Nina in Frankfurt. Eva accosts the young man who was introduced to Johan, Christof Sievernich, demanding answers.', 24, '2005-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 66, 'Welcome Home', 'Capek reveals to Nina that her and her twin brother Johan are the products of a eugenics experiment designed to breed "the perfect children". Tenma has wounded Christof and is driving him and Eva to the hospital while demanding answers on Petr Capek. While Eva makes a phone call at a payphone, Tenma sneaks away.', 24, '2005-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 67, 'I''m Back', 'Nina confronts Johan who presents her with a story on what happened when many people were poisoned at the Mansion of Red Roses. Nina realizes that she was the one who witnessed these deaths, the shock of this revelation nearly drives her to suicide, but she is saved by Tenma. Capek is gunned down by members of his organization when they find out about the guard that Capek killed.', 24, '2005-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 68, 'Ruhenheim', 'With a postcard obtained by Lipsky, Lunge arrives in Ruhenheim. There he meets up with Grimmer, whose research has led him to this town as well. A working-class couple in this town realize they win the lottery and fearing that everyone else wants to kill them, the husband buys an arsenal of weapons.', 24, '2005-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 69, 'The Peaceful House', 'Lunge and Grimmer conclude something terrible is happening in Ruhenheim when random gunshots ring out, people are either murdered or disappearing, and any links out of town is flooded by torrential rain. As Nina recovers in a nearby hospital, Tenma, using a lead from Capek, travels to Prague and meets with Lipsky and determines that Johan is in Ruhenheim.', 24, '2005-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 70, 'The Town Massacre', 'As time passes, more people in Ruhenheim are being shot dead by mysterious people and each other. Both Grimmer and Lunge determine that the owner of a local hotel is Klaus Poppe, also known as Franz Bonaparta. After subduing a man who was giving weapons to everyone in the town, they obtain information that one of the ringleaders is in a second hotel.', 24, '2005-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 71, 'The Wrath of the Magnificent Steiner', 'Tenma runs into Lunge, the latter apologizing for his previous accusations against Tenma. Nina and Dr. Gillen rush to Ruhenheim. After the winning lottery couple is wounded in an attack on Bonaparta''s hotel, Grimmer rushes out to the streets to reason with the unknown assailants.', 24, '2005-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 72, 'A Nameless Man', 'Lunge confronts Roberto, one of the ringleaders, in a hotel room. Both are subsequently wounded in the fight. Nina and Gillen arrive in Ruhenheim where they find a house containing drawings of the two twins by Bonaparta. This triggers a final memory and the secret to Johan''s madness and motives, his quest for true solitude, as well as forgiveness for his actions. Bonaparta accompanies Tenma on his quest to find and kill Johan.', 24, '2005-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 73, 'Scenery for a Doomsday', 'Bonaparta attempts to shoot Johan dead, but is gunned down by Roberto, who dies of his own injuries soon afterwards. With the massacre now over, authorities rush into the town and attempt to determine what happened. Just as an officer is about to arrest Dr. Tenma, an ambulance worker arrives asking for Tenma''s assistance.', 24, '2005-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434706')) AND numero_temporada = 1), 74, 'The Real Monster', 'It has been some time since the tragic blood battle, and everyone is working hard to put their lives back to normal. Tenma finally locates a woman he has been searching for, and she reveals some startling information.', 24, '2005-09-28');
