INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 1, 'The Day I Became a Shinigami', 'Fifteen-year-old Ichigo Kurosaki has the uncanny ability to see ghosts, but otherwise lives an ordinary life. However, once a Shinigami named Rukia Kuchiki appears before him, everything changes.', 23, '2004-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 2, 'A Shinigami''s Work', 'After becoming a Shinigami, Ichigo Kurosaki refuses to help Rukia Kuchiki with her work as the local Shinigami of Karakura Town.', 23, '2004-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 3, 'The Older Brother''s Wish, the Younger Sister''s Wish', 'When a Hollowfied Sora Inoue attacks his younger sister, Ichigo Kurosaki and Rukia Kuchiki set out to save her.', 23, '2004-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 4, 'Cursed Parakeet', 'When Yasutora Sado receives a parakeet that contains the Soul of a young boy, it is up to Ichigo Kurosaki and Rukia Kuchiki to protect him from the Hollow that is after them.', 23, '2004-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 5, 'Beat the Invisible Enemy!', 'Rukia Kuchiki and Yasutora Sado team up to take on the Hollow Shrieker.', 23, '2004-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 6, 'Fight to the Death! Ichigo vs. Ichigo', 'At Rukia Kuchiki''s behest, Ichigo Kurosaki puts an artificial soul in his body to take care of it and not arouse suspicion while he carries out his Substitute Shinigami duties, but the artificial soul has its own agenda.', 23, '2004-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 7, 'Greetings from a Stuffed Lion', 'Ichigo Kurosaki becomes friends with the Modified Soul, Kon, and puts him into a plushie.', 23, '2004-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 8, 'June 17, Memories in the Rain', 'Ichigo Kurosaki goes to his mother''s grave with the rest of his family.', 23, '2004-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 9, 'Unbeatable Enemy', 'Ichigo Kurosaki battles against Grand Fisher.', 23, '2004-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 10, 'Assault on Trip at Sacred Ground!', 'While grudgingly attending Don Kanonji''s show with the rest of his family, Ichigo Kurosaki is forced to fight a Hollow inadvertently created by Don Kanonji himself.', 23, '2004-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 11, 'The Legendary Quincy', 'Ichigo Kurosaki and Rukia Kuchiki meet Uryū Ishida, a Quincy.', 23, '2004-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 12, 'A Gentle Right Arm', 'As Ichigo Kurosaki begins his duel with Uryū Ishida, Yasutora Sado gains a new power.', 23, '2004-12-21');
