INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 244, 'The Long Awaited... Kenpachi Appears!', '11th Division Captain Kenpachi Zaraki arrives and defeats Wabisuke before moving on to 6th Division Captain Byakuya Kuchiki. Meanwhile, 11th Division 5th Seat Yumichika Ayasegawa defeats his manifested Zanpakutō Spirit, Ruri''iro Kujaku.', 24, '2009-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0434665')) AND numero_temporada = 1), 245, 'Pursue Byakuya! The Confused Gotei Divisions', 'As 11th Division Captain Kenpachi Zaraki and 6th Division Byakuya Kuchiki fight, 11th Division Lieutenant Yachiru Kusajishi chases Ashisogi Jizō before 12th Division Captain Mayuri Kurotsuchi forces his Zanpakutō Spirit to self-destruct and tells others to not interfere. Muramasa takes Byakuya to see Captain-Commander Genryūsai Shigekuni Yamamoto, who is inside of a barrier guarded by a dark-haired woman, two white-haired boys, and a cloaked figure.', 24, '2009-11-10');
