INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 1, 'Pilot', 'To help capture a serial rapist-turned-killer, FBI Special Agent Don Eppes recruits his genius brother Charlie, who uses a mathematical equation to identify the killer''s point of origin by working back from the crime scene locations.', 43, '2005-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 2, 'Uncertainty Principle', 'Charlie accurately predicts where a band of bank robbers will strike next.  But when Don and his team confront them, a massive shoot-out occurs leaving four people, including an officer, dead.  The outcome disturbs Charlie and he retreats into the family garage to work out an unsolvable math problem that he also plunged into after his mother became ill a year earlier.  But Don needs his brother''s help and tries to get Charlie to return to the case.', 43, '2005-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 3, 'Vector', 'Various people in the L.A. area with seemingly nothing in common start to become extremely sick and die on the same day. Don fears bioterrorists may have released a deadly virus into the environment. While he tries to discover whether anyone is behind the outbreak, Charlie tries to locate the point of origin.', 42, '2005-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 4, 'Structural Corruption', 'After an engineering student at CalSci is found dead from an apparent suicide, Charlie convinces Don to launch an investigation after he reads the student''s thesis that asserted that the architecturally magnificent Cole Center in Los Angeles is structurally unstable. Although reluctant at first, Don and his FBI agents discover that the student''s findings were correct and uncover a dangerous and surprising conspiracy. Meanwhile, Alan prepares for a first date and convinces Don and Terry to join them, hoping they might rekindle their old romance.', 44, '2005-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 5, 'Prime Suspect', 'When a five-year-old girl is kidnapped from her birthday party, Don and Terry lead the investigation, but must rely on Charlie''s help because the girl''s father, Ethan, is also a mathematician. Charlie realizes the kidnapper''s motive when Ethan reveals he is close to solving Riemann''s Hypothesis, a difficult math problem.  If solved, the solution could not only earn him $1 million, but could break the code for internet security and unlock the world''s biggest financial secret.', 41, '2005-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 6, 'Sabotage', 'While consulting with the NTSB at the scene of the wreck, Don learns that this tragedy is one of a series of recreated accidents involving railroad negligence. As is the pattern with the previous train wrecks, an undecipherable numerical code is left at the site, which Don recruits Charlie to solve. By breaking the code, Charlie is able to establish that this accident was a recreation of a deadly wreck that left only one survivor several years ago. Don''s investigation leads him and his team to a dangerous standoff with their suspect, who has surprising ties to the railway system.', 40, '2005-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 7, 'Counterfeit Reality', 'Don learns that counterfeiters are at work producing small-denomination bills, and that they have taken an artist hostage to draw the images for the fake money.  If the missing woman isn''t located soon, Don fears that she will be killed when her work is finished on the phony cash.  The counterfeiters have already murdered at least five people, two of whom stole money from them.  The case is made more difficult for Don when his former lover, now a Secret Service agent, is assigned to it.', 41, '2005-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 8, 'Identity Crisis', 'A man wanted for stock fraud is found garroted in his apartment, and the crime is eerily similar to a murder committed a year earlier, a case in which Don closed when an ex-con confessed.  Now, Don must re-investigate the old case to determine if he put an innocent man in jail.  He asks Charlie to go over the evidence to see if he missed anything the first time around.', 42, '2005-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 9, 'Sniper Zero', 'The city is in a panic as a sniper goes on a shooting spree and randomly kills several people, including a postal worker.  The investigation reveals that more than one shooter is at work.  As Charlie works the case, he''s frustrated by a sniper expert Don brings in to help out.', 41, '2005-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 10, 'Dirty Bomb', 'A truck carrying radioactive material is stolen, and the thieves threaten to set off a dirty bomb in L.A. in 12 hours if they aren''t paid $20 million.  While Don attempts to track down the truck, Charlie tries to come up with the most likely location where the bomb may be detonated to inflict the most damage to the population.', 42, '2005-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 11, 'Sacrifice', 'A senior computer-science researcher working on a classified government project is found murdered in his Hollywood Hills home and data has been stolen from his computer.  The investigation reveals the victim was going through a bitter divorce and was trying to keep his wife from getting his money.  Charlie also learns the project on which the man was working might have involved baseball.', 40, '2005-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 12, 'Noisy Edge', 'Don and Agent Weston of the NTSB investigate eyewitness accounts of a mysterious unidentified object flying dangerously close to downtown Los Angeles that has raised concern of a terrorist attack. After Charlie is recruited to help with the investigation, it is discovered that the flying object is part of a new technology that could revolutionize air travel. But the investigation takes a turn when they learn that the lead engineer is found murdered.', 41, '2005-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 1), 13, 'Man Hunt', 'A dangerous felon escapes when a prison bus crashes and the FBI has reason to fear he''s intent on revenge against the witness whose testimony put him in jail.  However, finding the elusive killer proves to be a complicated challenge.  Don teams up with Agent Billy Cooper,  his former partner from the FBI''s Fugitive Recovery Division, and Alan worries that Don''s going to return to a more dark and obsessive time in his career.', 42, '2005-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')), 2, 'Season 2', 'Season two has several changes to Don''s FBI team: Terry Lake is reassigned to Washington and two new members join Don and David Sinclair: Megan Reeves and Colby Granger. Charlie is challenged on one of his long-standing mathematical workpieces and starts work on a new theory, cognitive emergence theory.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 1, 'Judgment Call', 'Don and Charlie investigate the murder of a judge''s wife who was shot in her garage.  It''s unclear whether she was the intended target or her husband, who was hearing a death penalty case involving a gang leader.  As the investigation continues, Don reconnects with a prosecutor whose life may also be in danger.', 44, '2005-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 2, 'Better or Worse', 'Don and his team are called in when a woman attempting to rob a jewelry store in Beverly Hills is shot by a security guard.   Charlie assists the FBI by using the keyless remote from the woman''s car to help identify her and locate the store owner''s kidnapped wife and daughter.', 42, '2005-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 3, 'Obsession', 'The FBI becomes involved in the stalking of a popular singer after she is threatened by an intruder in her house and reveals a series of threatening letters she''s received through the mail. Charlie determines the letters are from two different people after analyzing the handwriting. When a photographer is found dead near the singer''s house, Don believes the photographer was murdered and his death is somehow related to the stalking case.', 43, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 4, 'Calculated Risk', 'Don and Megan are called to the murder scene when the CFO of a powerful energy company - who was about to testify against her fellow executives - is murdered at her home and her son is the only witness. Knowing there could be thousands of disgruntled ex-employees, Don asks Charlie to narrow the list.', 45, '2005-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 5, 'Assassin', 'Don uncovers a secret code that begins the hunt for a skilled and trained assassin, and the efforts by the FBI to save the life of a Colombian exile living in Los Angeles.', 40, '2005-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 6, 'Soft Target', 'Don and his team are summoned to locate the person who released potentially lethal gas in the city''s subway system.', 43, '2005-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 7, 'Convergence', 'When a father is killed in a home invasion, Don and his team investigate the connection between the murder and a rash of  robberies in the upscale community.', 42, '2005-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 8, 'In Plain Sight', 'Megan feels responsible for an agent''s death following an explosion at a meth house the FBI had targeted for a bust. When the kingpin eludes capture, it''s discovered he may also be involved in child pornography when one of the photographs on his computer turns out to be a young girl in a sexually explicit position. The picture sends Charlie on a crusade of his own, as he remembers a girl he knew as a young child that he suspected was being abused, and he''s determined to save the little girl in the picture.', 41, '2005-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 9, 'Toxin', 'After four people nearly die from poisoning, Don learns someone is tampering with nonprescription drugs. When the perpetrator publishes a manifesto in a local paper, Don is led to believe the person may be a former employee of the drug company that manufactured the drug.', 44, '2005-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 10, 'Bones of Contention', 'When a researcher who specializes in Native American antiquities is killed at the museum where she works, the FBI is called in because the museum is on federal land.', 41, '2005-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 11, 'Scorched', 'An arsonist sets a fire at a car dealership that kills a sales person. The name of an extremist environmental group is spray-painted on the scene, but the group denies involvement. It becomes Don''s task to determine whether the group or someone else is responsible. Charlie is called in to help figure out if there is a pattern to the fires that would help provide a profile of the arsonist.', 44, '2005-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 12, 'The O.G.', 'When Don and his team are called to the scene of the murder of a Los Angeles gang member, they learn they are investigating the murder of another agent who had been working undercover.', 44, '2006-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 13, 'Double Down', 'A murder investigation at a Los Angeles card club leads the FBI to a complicated card-counting scheme involving college students.', 44, '2006-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 14, 'Harvest', 'When an Asian teenager is found in the basement of an old downtown hotel where she was apparently being tortured, the investigation soon reveals the girl and three other missing women, are victims of a black market organ-harvesting scheme. Amita assists the FBI by communicating with the girl, who is from the same part of India where Amita''s family once lived.', 44, '2006-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 15, 'The Running Man', 'When a DNA synthesizer with the capability of customizing diseases is stolen from the campus where Charlie teaches, Don fears the thieves may be terrorists out to start or advance a bio-warfare program and also believes the theft was an inside job.', 43, '2006-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 16, 'Protest', 'Don and his team investigate an anti-war bombing outside an Army recruiting center that resembles the work of a 1970s anti-war activist who disappeared 30 years earlier after being accused of planting a bomb that killed two people.  Retired Agent Thomas Larson, who tried to solve the case 30 years ago, returns to help but questions Don''s loyalty when it is revealed Alan knew the radical activist and participated in demonstrations with him, thus causing tension within the family.', 44, '2006-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 17, 'Mind Games', 'Don and his agents are asked to investigate when a search team finds three dead women in the wilderness who were apparently murdered under bizarre circumstances. The case becomes more suspicious when Don learns the search team was led to the crime scene by a psychic.  When the psychic offers to help the FBI in solving the crime, Charlie is determined to prove the psychic is a fraud.', 44, '2006-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 18, 'All''s Fair', 'In an effort to find the murderer of an Iraqi woman who had been making a documentary that promoted the rights of Muslim women, Don enlists the help of the victim''s cousin. Through her cousin, Don uncovers a connection to Saddam Hussein.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 19, 'Dark Matter', 'Don and his team investigate a school shooting. He learns two students could have a strong motive, so Charlie uses the school''s radio frequency identification system to track the shooters'' movements through the school''s hallways. When Charlie detects an abnormal pattern, the agents take a look at the evidence and discover a third participant no one had suspected earlier.', 44, '2006-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 20, 'Guns and Roses', 'When an ATF agent is found dead under unusual circumstances, Don wants to take the case, which revolves around an elaborate bank robbery, after he learns the victim was his former girlfriend. He then becomes quite introspective as he realizes the impact his career has had on his personal life and decides to turn his attention toward a new woman.', 44, '2006-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 21, 'Rampage', 'When an assailant opens fire in the FBI offices, Don and his team must determine his motive and possible connection to a dangerous arms dealer who is on trial. After nearly getting shot, Charlie is shaken and reluctant to return to the offices, which hinders his contribution to the case.', 43, '2006-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 22, 'Backscatter', 'An FBI investigation into a computer hacking scam that taps into a bank''s system to gain access to the identities and financial assets of its customers becomes personal for Don and the Eppes family.', 41, '2006-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 23, 'Undercurrents', 'The FBI becomes involved when the bodies of young Asian girls are washed up on the beach. The situation becomes more critical when it is discovered one girl has avian flu. As the investigation continues, Don and his team discover a connection between the girls and the sex trade industry.  Meanwhile, Amita considers a transfer to Harvard University, which causes Charlie to re-evaluate his feelings for her.', 44, '2006-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 2), 24, 'Hot Shot', 'Don investigates the murders of two young women found in their cars outside their homes. Their deaths were made to look like drug overdoses, but Don realizes a serial killer is responsible. Meanwhile, Charlie is having bizarre dreams about his parents. In one dream, his deceased mother appears and tells him he has a question to ask her, but he can''t imagine what it could be.', 44, '2006-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')), 3, 'Season 3', 'Charlie and Amita intensify their relationship, as do Larry and Megan, especially after Megan''s kidnapping. Amita has trouble adjusting to her new role as a CalSci professor, and Larry announces his leave of absence; he will be on the International Space Station for six months, which greatly distresses Charlie.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 1, 'Spree (1)', 'Don has a problem.  Crystal Hoyle and her boyfriend Buck are going on a robbery and killing spree.  Their terror is spread over seven states, and Charlie is called in to help.  However, problems between Alan and Charlie may hinder Charlie''s concentration.', 43, '2006-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 2, 'Two Daughters (2)', 'David tries to get information from one of Crystal''s old boyfriends, but he isn''t helping.  Things get personal for the team when Crystal kidnaps one of them.', 44, '2006-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 3, 'Provenance', 'Don and the rest of the team find themselves in the midst of a confusing case.  The investigation into a missing painting turns grim as a murder plot surfaces.  Add Nazis to the mix, and things take an even more interesting turn!', 43, '2006-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 4, 'The Mole', 'Don and the team attempt to figure out what happened when a Chinese interpreter turns up dead.', 44, '2006-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 5, 'Traffic', 'Don and the rest of the team investigate several attacks occurring on LA highways that may be connected.', 42, '2006-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 6, 'Longshot', 'Don and the team investigate a suspicious death at a horse track.  When Charlie starts looking into the crime, he uncovers something that will send the investigation into an entirely different direction.', 43, '2006-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 7, 'Blackout', 'Blackouts leave Los Angeles in the dark.  Don must work with his entire team to figure out if the power outages are a catastrophic accident or the sinister plot of terrorists.', 42, '2006-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 8, 'Hardball', 'The case of a dead minor league baseball player leaves Don and the team with more questions than answers.  When Charlie discovers that someone has come up with a statistical analysis that can identify which of the players are on steriods, the case gets more leads...and a suspect.', 44, '2006-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 9, 'Waste Not', 'The problem of the disposal of toxic waste becomes real to Don, Charlie and the team when several children are injured after a sinkhole collapses underneath a school playground.  Charlie attempts to help with the case, but faces opposition from his new boss.', 44, '2006-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 10, 'Brutus', 'A California State Senator and a psychiatrist--neither have much in common with the other except for one thing...they both turn up dead on Don''s watch. While the circumstances of their deaths are different, Don thinks the two murders are related, and tries to prove his hunch right. What he finds may bring to light a deep secret the government has been hiding for years.', 44, '2006-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 3), 11, 'Killer Chat', 'Don and Charlie track a killer who has murdered several sex predators.  The predators took advantage of teenage girls they met in chat rooms.  Meanwhile, Larry is ready to begin an adventure with NASA.', 44, '2006-12-15');
