INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 5), 18, '12:01 A.M.', 'The team gets a last minute tip that could exonerate a dangerous mob boss who is about to be executed; Charlie tries to help the CalSci basketball team break their losing streak.', 42, '2009-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 5), 19, 'Animal Rites', 'The investigation into a professor''s death takes a dangerous turn when the team finds their lead suspect has ties to a radical animal rights group.', 41, '2009-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 5), 20, 'The Fifth Man', 'Don''s life hangs in the balance after he is injured during a raid while investigating a series of home invasions.', 44, '2009-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 5), 21, 'Disturbed', 'Feeling guilty over the stabbing, Charlie puts his attention on finding a serial killer using math theories to help the team solve the case before another life is taken.', 44, '2009-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 5), 22, 'Greatest Hits', 'Don and the team are sent to look into a series of bank robberies and soon name former FBI Agent Roger Bloom as their lead suspect.', 43, '2009-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 5), 23, 'Angels and Devils', 'When Amita is abducted, Don and the team’s frantic search for her leads them to the delusional head of a cult, but it is up to a distraught Charlie to discover what the suspect’s bizarre plans for her are.', 44, '2009-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 1, 'Hangman', 'Don and his team are out to protect former radical Benjamin Polk from a determined sniper who wants him dead, and who is leading the FBI on a cat-and-mouse chase as he closes in on his prey.', 44, '2009-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 2, 'Friendly Fire', 'When two FBI agents, part of a unit headed by Don''s former mentor, are killed during a shootout with bank robbers, the team must investigate what exactly happened. Also, Charlie and Amita worry when Larry opts not to attend a conference in Geneva.', 41, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 3, '7 Men Out', 'Don and his team are called in to investigate who is behind a deadly gambling ring that is running a high-stakes Russian roulette tournament. Also, Don and Charlie become concerned about Alan''s financial health.', 41, '2009-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 4, 'Where Credit''s Due', 'As Larry prepares to embark on his adventure, the team must investigate a string of murders. The case takes an interesting turn when it is discovered that the murders mimic scenes from a movie that hasn''t even been released yet.', 44, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 5, 'Hydra', 'The team attempts to find the daughter of a geneticist who they suspect was kidnapped by the unstable mother. However, they become concerned about the case when they find evidence that suggests the young girl was a clone. Meanwhile, Charlie and Amita discuss having kids and Liz reveals a dark secret.', 43, '2009-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 6, 'Dreamland', 'The team investigates a decommissioned air base after a woman is found dead there, but their investigation is interrupted by paranormal happenings.', 43, '2009-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 7, 'Shadow Markets', 'A shrewd computer hacker cuts the ground from up under an undercover sting operation to bag a cyber crime lord. His actions trigger a turf war putting his life in peril.', 39, '2009-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 8, 'Ultimatum', 'While tracking down a felon running a heroin ring inside a prison, Agent Ian Edgerton becomes a murder suspect when the informant he meets with ends up dead, sending a desperate Edgerton over the edge when he takes a member of Don''s team hostage.', 41, '2009-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 9, 'Con Job', 'Charlie and Don reluctantly enlist the help of imprisoned con man John Buckley to help them catch a crook who''s using Buckley''s M.O. to rob the Diamond Exchange..', 41, '2009-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 10, 'Old Soldiers', 'When the team foils a robbery of an armored car full of Federal Reserve money and recover bills that trace back to the infamous D.B. Cooper heist, they call on Agent Roger Bloom, who worked on the Cooper case, for help with the investigation. Henry Winkler returns as former FBI Agent Roger Bloom, and Michael Hogan, the uncle of the slain armored car driver and a key player in the investigation.', 44, '2009-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 11, 'Scratch', 'Charlie meets his mathematical equivalent when lottery agent Jane assists in the investigation into a complex scam that involves thefts of unsold lottery tickets.', 41, '2010-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 12, 'Arm in Arms', 'The gang uses their math--and a reluctant gun merchant named Randall P. -- to track down a missing shipment of new, deadly but defective assault weapons which are hidden among the thousands of containers in one of L.A.''s busiest ports.', 44, '2010-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 13, 'Devil Girl', 'The Numbers team tracks a serial killer who targets johns.', 41, '2010-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 14, 'And the Winner Is...', 'The Numbers team hunts for a gang of criminals who targeted an unlikely scene of the crime: a televised entertainment awards show.', 44, '2010-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 15, 'Growin'' Up', 'The team investigates the deaths of two men who were part of a group of friends that had been sexually assaulted by a teacher when they were young boys. Also, Charlie and Amita get a fantastic job opportunity that could put a wrinkle in their wedding plans.', 44, '2010-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0433309')) AND numero_temporada = 6), 16, 'Cause and Effect', 'After Charlie and Amita get married and begin preparations for their London adventure, they put a slight hold on their wedded bliss when they assist the team in helping Don track down the whereabouts of his gun after it goes missing.', 43, '2010-03-12');
