INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100'), 'Crimen');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100'), 'Drama');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 1, 'Season 1', 'The first season of Weeds premiered on August 8, 2005, and consisted of 10 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 1, 'You Can''t Miss the Bear', 'In the series debut, housewife Nancy Botwin struggles to deal with the sudden death of her husband, while her best friend and neighbour Celia Hodes learns a devastating secret when she tries to catch her daughter in the act with Nancy''s son.', 31, '2005-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 2, 'Free Goat', 'As Celia deals with the other woman in her marriage, Nancy contemplates creating an enterprise to solve the cash-only financial issues caused by her drug dealing. Silas has to come to terms with his girlfriend''s sudden departure, while Shane tries to come to terms with missing his Dad.', 30, '2005-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 3, 'Good Sh#t Lollipop', 'A mountain lion is on the prowl in Agrestic, but it''s the medical marijuana facility that is causing the most havoc in Nancy''s life. Faced with the dilemma of having to compete, Nancy has to get cooking. Silas makes a move on Megan causing him some colourful problems of his own and Celia and Isabel''s war over weight issues gets dirty.', 29, '2005-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 4, 'Fashion of the Christ', 'Nancy gets a rude awakening when her brother-in-law Andy comes for a surprise visit. Doug has an idea for a location for the faux bakery, which Nancy may need more than ever with Andy in the way. While Andy wreaks havoc in the Botwins'' lives, Nancy is introduced to "The Candy Man" in order to help meet her customers'' needs, and Celia drops a bomb.', 26, '2005-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 5, 'Lude Awakening', 'Nancy gets a reality check about what a life of crime can entail. Andy acts like a fool and gets arrested. Celia tries alternative methods to deal with her breast cancer. She also steps out of her box and bonds with children. Shane gets in trouble at school. Again.', 27, '2005-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 6, 'Dead in the Nethers', 'Nancy attempt to play around in an effort to relieve some stress. Nancy, Celia, and Conrad go out to a club where Celia and Conrad "snuggle up." Meanwhile Andy meets a woman who he lies to like he would anyone else and Lupita starts investigating so as to gain the upper hand in her employee/employer relationship.', 27, '2005-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 7, 'Higher Education', 'Nancy hires an employee, and becomes known to a rival in the process. Shane makes a new friend, and Andy gets to know the new friend''s mother. Celia''s mother comes to visit after Celia''s surgery.', 26, '2005-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 8, 'The Punishment Light', 'Uncle Andy acts foolish at a ceremony for Judah. Shane gets in trouble again. Celia and Dean duke it out. Nancy finds out who it is that has been "delivering" pennies onto her car and fountain and she deals with them. Andy and Doug team up to bring more trouble into Nancy''s home while trying to flush out the infestation of a rat. Nancy turns down an interested single father. And Uncle Andy exposes too much of himself yet again.', 26, '2005-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 9, 'The Punishment Lighter', 'Nancy gets busted and Heylia teaches her about a $14,000 lesson. Doug and Celia make kitchen talk. The kids have daddy problems during diversity week. Bread-sticks and Scones, Nancy''s bakery, opens and doesn''t start off so well. And Celia retakes the PTA by way of a technicality.', 27, '2005-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 1), 10, 'The Godmother', 'Isabelle experiments, Andy gets drafted, Peter may not be who Nancy thinks he is, Silas gets high, and Nancy cuts out the middleman.', 30, '2005-10-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 2, 'Season 2', 'The second season of Weeds premiered on August 14, 2006, and consisted of 12 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 1, 'Corn Snake', 'After repeatedly having her suggestions ignored by the likes of Doug Wilson and having an eye-opening car accident Celia decides to run for city council. Nancy tries to break things off with Peter because her life is currently too illegal to be dating the DEA. Things gets even more hectic when Sanjay screws up at the bakery. Andy is still trying to get into a Rabbinical school so that he doesn''t get shipped off to Iraq.', 29, '2006-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 2, 'Cooking with Jesus', 'Nancy does her best to cope with the loss of Conrad''s help, who runs into some trouble while venturing out on his own. Andy is still trying to get into rabbinical school by writing an essay on what being Jewish means to him. And Silas deals with Megan''s acceptance to Princeton in his own unique way.', 29, '2006-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 3, 'Last Tango in Agrestic', 'While Nancy is trying to figure out what do with Peter, she comes home to problems of plumbing that are related to Shane and his arrival into puberty. Celia enrolls Isabelle in boot camp and ends up getting sucked into it herself. Heylia is interested in a Nation of Islam member and his bean pies.', 26, '2006-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 4, 'A.K.A. The Plant', 'Nancy takes on an alias to help Conrad set up the grow house. Isabelle get approached to be a model. Interesting things happen to Celia while she''s on the campaign trail. Shane makes an attempt to fit in at his school. Andy takes Shane to a massage parlor. Shane gets a surprise and Silas has one as well.', 29, '2006-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 5, 'Mrs. Botwin''s Neighborhood', 'Isabelle is auditioning for the Huskeroo ads afterall. Once Celia sees that Isabelle has an opportunity to go national she may change her mind about Isabelle''s involvement. Celia is still campaigning and is starting to wonder what Nancy does during all of her "free time" as a widowed housewife. Conrad lays out the details of the operations of their Armenian neighbors and Nancy comes up with a plan. Silas may have more to deal with than a baby on the way. Shane finally starts to fit in at school. Heylia prepares for her first date with Joseph.', 27, '2006-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 6, 'Crush Girl Love Panic', 'Conrad is beginning to grow suspicious of Nancy''s actions after the bust on the grow houses. Shane joins the debate team at school. Celia gets in the way when Isabelle goes to shoot her Huskeroos commercial. Isabelle talks to Doug about something she doesn''t want her mother to know about. Nancy has a surprise for the men in her life.', 28, '2006-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 7, 'Must Find Toes', 'It''s election day and the votes are being cast by friend and foe alike. Andy loses some of his toes at the grow house. Nancy tries to make peace with Conrad. She also has to deal with the romance or lack thereof in both of her sons lives. Doug and Celia are having problems in their respective marriages to Dana and Dean.', 26, '2006-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 8, 'MILF Money', 'Conrad and Nancy take their product to be tested in the market. They run into some upscale clients on the way. Celia tries to get Dean to help her with a speech that she must give in front of some kids as the new City Councilwoman. Celia wants to close a dog park. Nancy goes to invest some of her cash in jewelry. Heylia finds out that Nancy and Conrad are working together on their own seperate venture and she lets them know that she knows.', 26, '2006-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 9, 'Bash', 'Peter makes a visit to Heylia''s house with some of his DEA friends. Nancy and Conrad install a safe in the grow house. Doug tries to ruin Celia''s new job by showing her up at a City Council meeting. Silas and Shane celebrate their dad''s birthday.', 27, '2006-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 10, 'Mile Deep and a Foot Wide', 'Heylia treats Nancy like the trash that she thinks she is. Peter''s captain looks over his notes on the DEA bust. Celia and Doug''s relationship hasn''t changed since last week. Andy''s ex-girlfriend, Kat, shows up.', 26, '2006-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 11, 'Yeah, Like Tomatoes', 'Peter isn''t happy about the nickname "Agent Wonderbread" and he lets Nancy and Conrad know so with a convinving threat. Nancy looks to other people in the business for help. Kat''s got a secret and Shane''s girlfriend doesn''t like her. Heylia has a plan.', 27, '2006-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 2), 12, 'Pittsburgh', 'Nancy is having one of the worst and busiest days of life. One of sons is missing. Shane''s graduation and the deal with U-Turn make her feel like she needs to be in two places at once even though she really doesn''t feel like being in either of them. Heylia''s plan is put into action. Nancy tries to deal with Conrad''s kiss, Celia''s madness, and Kat''s craziness. Everything comes to a head when the deal goes wrong.', 26, '2006-10-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 3, 'Season 3', 'The third season of Weeds premiered on August 13, 2007, and consisted of 15 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 1, 'Doing the Backstroke', 'After being threatened by U-Turn and The Armenians, Nancy goes in search of Silas and her hijacked pot. Meanwhile, Celia has Silas arrested for stealing her "Drug Free Zone" signs. Nancy visits him in jail only to discover that the pot is still in his car - the one that Celia has just driven away in.', 27, '2007-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 2, 'A Pool and His Money', 'Sanjay has a new experience. Nancy gets bruised. Conrad won''t do what U-Turn wants him to. Lupita still won''t follow orders. Heylia''s out to handle a few things. The Amber Alert is still out on Shane. Andy gets in trouble with a couple who make him for a child molester. Silas gets to talk to Shane. Celia is still having problems with her husband and daughter. Doug begs Celia to forgive him.', 28, '2007-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 3, 'The Brick Dance', 'Conrad and Heylia find a new grow house. Celia attempts to bond with Isabel, while U-Turn forces Nancy to run a dangerous errand.', 28, '2007-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 4, 'Sh*t Highway', 'The DEA continues to probe Nancy''s life to figure out what happened to Peter. Shane helps Nancy get a job. Someone asks the city council for a favor on behalf of Majestic. Conrad and Heylia set up their new grow house. Silas runs into Pam while performing his community service.', 27, '2007-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 5, 'Bill Sussman', 'After going AWOL from the military Andy turns up in camouflage. The city council works with Sullivan. Shane goes to summer school in Majestic. Nancy''s involvement with U-Turn becomes more entrenched and Silas has business ideas. Sullivan asks Nancy to hold a cocktail party.', 26, '2007-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 6, 'Grasshopper', 'Silas makes a new friend, played by the smokin'' hot Mary-Kate Olsen; Nancy''s conflict with Conrad and Heylia comes to a head; and Nancy finds herself charged with the task of making peace between Agrestic and Majestic.', 26, '2007-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 7, 'He Taught Me How to Drive By', 'With U-Turn''s timely demise Nancy and Conrad check the status on their debts and then they check in with each other. Someone is pregnant and they are keeping it. Doug continues to try to sabotage Celia and Celia continues to sabotage Nancy. Nancy celebrates something. Silas begins spending more time with Tara.', 25, '2007-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 8, 'The Two Mrs. Scottsons', 'Celia and Sullivan step up their relationship. Andy gets more involved in a different business. Silas and Tara begin working together. Shane and Isabelle spend time together. Nancy meets Peter''s other ex-wife, Valerie.', 27, '2007-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 9, 'Release the Hounds', 'Doug and Sullivan fight over a golf membership and Doug get some revenge. Nancy spends time with Valerie, who considers her an “insane stalker person”. Conrad and Silas spend time together. Dean is injured and hospitalized. Tara tries to get deeper into Nancy''s business.', 25, '2007-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 10, 'Roy Till Called', 'Nancy''s up and running again until someone betrays her and sends in the DEA. Celia spends more time with Dean. Doug has ethics decisions to make.', 24, '2007-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 11, 'Cankles', 'Nancy discovers who betrayed her and finds out she''s being trailed. Some people lose their jobs. Silas discovers something about Tara. Shane installs a security system.', 25, '2007-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 12, 'The Dark Time', 'Andy and Dean play murderball. Nancy ponders a new venture while Heylia and Conrad must abandon theirs. Doug sinks to an all-time low.', 24, '2007-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 13, 'Risk', 'Nancy tries out a new source but it doesn''t go so well. Conrad and Nancy are having some good interplay. Heylia and Vaneeta like the new neighborhood. Celia is angry.', 24, '2007-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 14, 'Protection', 'Nancy has another full week of trouble to deal with and Doug isn''t helping. Heylia teaches Celia.', 24, '2007-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 3), 15, 'Go', 'As the wildfire approaches, everyone must evacuate. Nancy tells her family to pack up, while Conrad and Heylia must say goodbye to the growhouse. The authorities question Sullivan and Celia, while Shane continues to ask Nancy about Pittsburgh. As Andy deals at the evacuation center, Silas realizes the truth about Tara.', 26, '2007-11-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 4, 'Season 4', 'On November 5, 2007, Showtime ordered 13 new episodes for a fourth season of Weeds. It started on Monday, June 16, 2008 and concluded on Monday, September 15, 2008.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 1, 'Mother Thinks the Birds Are After Her', 'Nancy has relocated to the border in search of a new life but she soon finds her past to be inescapable. Both problems and people follow her on her journey, but some have finally been left behind.', 28, '2008-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 2, 'Lady''s a Charm', 'After settling her family in Ren Mar, Nancy turns her attention back to business. Later, Guillermo gives her a much-needed crash course in "running" across the border. Meanwhile, Celia gets further acquainted with life in prison. Lenny leaves Silas and Shane to care for Bubbie while he goes to the track. When Lenny returns, Andy confronts him about some family history.', 28, '2008-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 3, 'The Whole Blah Damn Thing', 'Nancy makes her first successful smuggling run across the border with both drugs and human cargo. Meanwhile, Captain Till strikes a deal with Celia to get her out of jail. In return, she must gather evidence to incriminate Nancy and Guillermo. Back in Ren Mar, Andy tries to convince the family, including his father, to put Bubbie out of her misery.', 28, '2008-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 4, 'The Three Coolers', 'After Bubbie''s death, the entire Botwin family sits shiva (the Jewish period of mourning) for seven days. After shiva, Nancy is sent on a mission and takes Andy along with her. Now that shiva is over and Bubbie is gone, Lenny decides to sell the house. Meanwhile, Celia continues her flirtation with Captain Till, and Doug finds refuge with the Botwins.', 28, '2008-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 5, 'No Man is Pudding', 'Guillermo gives Nancy a new job and she soon finds working retail isn''t as mundane as it appears on the surface. Celia''s deal with Captain Till brings her dangerously close to the action. Meanwhile, having been left in the desert by Nancy, Andy finds himself with a pack of immigrants and a very unfriendly Coyote. Back at home, the boys battle an infestation of bees.', 27, '2008-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 6, 'Excellent Treasures', 'Nancy follows the tunnel in the back of the maternity shop and sees something she shouldn''t at the other end. Dean takes a new job, leaving Isabelle to live with Celia. Meanwhile, Silas flirts with Lisa, and Doug falls in love with a vision of beauty who washes up on the beach.', 26, '2008-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 7, 'Yes I Can', 'When Nancy is denied a share of the incoming pot by Guillermo, she decides to go over his head to Esteban. Celia discovers the cheap medication at Mexican pharmacies. Silas and Lisa get intimate, while Shane discovers some shocking photos. Andy and Doug begin interviewing for their human smuggling operation.', 27, '2008-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 8, 'I Am the Table', 'A spontaneous date ends in near-violence for Nancy and Esteban; Silas reveals to Lisa that he grows pot, and she makes him a tempting offer; Andy and Doug smuggle their first customer across the border; Celia develops an addiction.', 28, '2008-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 9, 'Little Boats', 'Despite their busy schedules, Nancy and Esteban try to find some time for each other. After finding out about Shane''s fantasies and Silas''s new and much older girlfriend, Nancy also has to talk to both of her sons. With their relationship going on, Lisa and Silas add some special offerings to her cheese shop.', 28, '2008-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 10, 'The Love Circle Overlap', 'Nancy learns that the tunnel is being used for more than drugs. Esteban puts her fears to rest as well as her nagging headache with a strong remedy. Celia''s family stages an intervention in order to force her into rehab. Andy finds Maria and takes her across the border to an awaiting Doug. Silas babysits while Shane explores new territory with his two girlfriends.', 28, '2008-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 11, 'Head Cheese', 'Nancy must deal with the aftermath of Shane''s exploits, her Ayahuasca trip, and more confrontation with Guillermo. Celia''s struggles with her rehab partner, Barry, force her to find a new rehab facility. Doug and Maria''s relationship quickly goes south and they both turn to Andy for help. Meanwhile, Silas''s "sandwich" business has grown too big, forcing him to turn to Nancy for help.', 27, '2008-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 12, 'Till We Meet Again', 'A fed up Nancy squeals to the DEA to bust the tunnel while she plays it cool with Esteban. Embracing rehab, Celia sets out to make amends with her family. Andy succumbs to Maria''s advances, and later comes clean to Doug. Shane impresses his girlfriends with his drug scoring abilities.', 26, '2008-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 4), 13, 'If You Work for a Living, Then Why Do You Kill Yourself Working?', 'The DEA brings Nancy in for questioning and then she must explain things to Esteban. Celia travels deep into Mexico to make amends with estranged daughter Quinn. Meanwhile, Silas meets Lisa''s ex-husband and Doug finds a reason to live. Nancy makes a shocking revelation to Esteban.', 29, '2008-09-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 5, 'Season 5', 'The fifth season of Weeds consisted of 13 episodes. Its debut, on June 8, 2009, attracted 1.2 million viewers, with a rerun on the same night adding another 500,000 viewers for a cumulative 1.7 million. The season finale episode premiered on Monday, August 31, 2009, averaging 1.3 million viewers, up versus season 4''s finale that averaged 1 million.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 1, 'Wonderful Wonderful', 'After showing Esteban the proof of her baby, a sonogram picture. Nancy returns to Ren Mar to her family, but still unsure of her fate. Meanwhile, Celia is held hostage in Mexico by her estranged daughter Quinn who tries to ransom her off to all her friends, but they hilariously decline to deliver the cash for her release. Back in Ren Mar, Andy, Silas and Doug discuss plans to grow pot in a national forest.', 28, '2009-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 2, 'Machetes Up Top', 'Nancy pays a secret visit to Guillermo in prison; Celia puts her time in the rebel camp to good use by organizing their supplies; Shane decides to visit Nancy''s estranged sister; Silas and Doug second-guess their choice of a pot-growing plot.', 26, '2009-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 3, 'Su-Su-Sucio', 'Nancy gets a surprise visit from Jill; Nancy''s bodyguard goes missing; Celia''s micromanaging gets her sent back to the U.S.; Silas and Doug seek law enforcement approval.', 27, '2009-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 4, 'Super Lucky Happy', 'Nancy is visited by DEA agent Roy Till who has gone rogue and homecomer Celia moves into Nancy''s garage. Meanwhile, Andy tries to access his brother''s old bank account.', 28, '2009-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 5, 'Van Nuys', 'Nancy talks with her obstetrician about ending the pregnancy. After his teacher took his pot, Shane needs some help to get it back. Andy is still trying to get access to his late brother''s bank account. Meanwhile, Silas and Doug need to see "The Wizard" to make their pot selling dreams come true.', 27, '2009-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 6, 'A Modest Proposal', 'It''s six months since we last saw everyone and Nancy is in full bloom. Esteban proposes, and all seems right with the world until Nancy discovers there''s another woman in Esteban''s life. Andy, meanwhile, has gone on a spending spree and let himself go. Now he must come to terms with the new order of things. Celia, unhappy in her job at the mall, discovers an opportunity in the world of cosmetics. Shane spends an eye-opening day with Ignacio. Silas and Doug''s medical marijuana dispensary is in full operation. But Deputy C.P. Jones continues his meddling ways.', 28, '2009-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 7, 'Where the Sidewalk Ends', 'Nancy learns the identity of the other woman in Esteban''s life, as well as his plans for her childbirth delivery. With the help of Andy and Audra, Nancy takes matters into her own hands. Meanwhile, Celia discovers that getting rich quick isn''t always so easy. Silas and Doug learn the hard way that Deputy C.P. Jones is more trouble than he''s worth as the fate of their medical marijuana dispensary is jeopardized.', 28, '2009-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 8, 'A Distinctive Horn', 'The tension between Nancy and Esteban mounts as Pilar adds to the conflict. Nancy looks to Andy for help, just as hes focused on his relationship with Audra. Dean offers to help Silas and Doug get their dispensary back on track, but Celia sees an opportunity and steps in.', 27, '2009-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 9, 'Suck ''n'' Spit', 'Nancy and Andy grow closer together while they try to be good parents. In the meantime, Celia and Dean work together to exploit their product surplus.', 28, '2009-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 10, 'Perro Insano', 'With the arrival of new enemies, Shane and Silas needs Nancy''s protection. Meanwhile, Andy plans his future with Audra, while Doug and Dean make a plan to put an end to Celia''s marijuana business.', 25, '2009-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 11, 'Ducks and Tigers', 'A visit from Esteban''s daughter comes with new problems for Nancy. In the meantime, Isabelle joins Doug and Dean''s scheme of revenge against Celia.', 28, '2009-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 12, 'Glue', 'Nancy, Andy and Cesar team up to look for Esteban when he goes missing. In the meantime, Dean and Doug start their scheme of revenge against Celia, while Silas and Shane develop a need to protect their new stepsister.', 26, '2009-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 5), 13, 'All About My Mom', 'Nancy learns of Esteban''s fate and takes action to preserve her own. Andy makes a big change in his life. Dean, Doug and Celia find common ground. Silas helps Adelita with a disturbing medical issue.', 29, '2009-08-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 6, 'Season 6', 'The sixth season of Weeds premiered on Monday, August 16, 2010 at 10ET/PT on the television cable network Showtime, and consisted of 13 episodes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 1, 'Thwack', 'Faced with the aftermath of Shane having murdered Pilar, Nancy grabs Shane and Silas and they flee the scene. Andy is then met with the decision to split town with his family or stay and fight for Audra''s affection.', 24, '2010-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 2, 'Felling and Swamping', 'After hours of aimless driving, Nancy, ignoring Shane''s suggestion of hiding out in Pittsburgh, hatches a plan for the family to cross into Canada. Andy is tasked with acquiring fake IDs. Silas must decide if he''s willing to live on the lam. Elsewhere, Esteban must answer to authorities regarding Pilar''s murder and Nancy''s whereabouts.', 27, '2010-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 3, 'A Yippity Sippity', 'Nancy becomes a scab labor in a Seattle hotel while Shane looks after Stevie and Doug goes back to Ren Mar', 26, '2010-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 4, 'Bliss', 'Nancy makes a deal with the concierge and Shane becomes part of a mommy group. Meanwhile, Doug is questioned by Cesar and Ignacio.', 27, '2010-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 5, 'Boomerang', 'The Botwins'' flight continues after a parking violation and Doug gets into a hostage situation.', 28, '2010-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 6, 'A Shoe for a Shoe', 'Nancy brings her son back while Andy and Silas wait in a diner.', 25, '2010-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 7, 'Pinwheels and Whirligigs', 'Nancy decides that her family has seen enough gunslinging for a lifetime, so to lighten things up she takes them to a Montana fair. Andy and Silas enter a butter-eating contest while Doug looks after the baby and makes friends with the carneys. Elsewhere, Nancy escorts Shane on a rollercoaster where they stir up some trouble in line.', 24, '2010-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 8, 'Gentle Puppies', 'After acquiring an RV, Nancy lets Andy navigate the road and he leads them to Pioneer Town, a former western movie set now turned off-the-grid scab city. While Nancy attempts to get the lay of the land, she instructs the family to set up a mobile hash making shop inside the RV. Andy and Silas work on getting laundry machines while Doug and Shane try to obtain water.', 29, '2010-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 9, 'To Moscow, and Quickly', 'Nancy is met with yet another roadblock when baby Stevie gets sick leaving her and Andy to scramble to find a pediatrician. Meanwhile, Silas, Shane and Doug are tasked with unloading some merchandise at a kiddie concert.', 26, '2010-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 10, 'Dearborn-Again', 'Nancy, attempting to score some big cash, returns to her hometown where she takes up residence with Warren an old acquaintance. Andy and Doug try to secure information on where to locate fake passports. Meanwhile, Silas and Shane curiously dig into Nancy''s past.', 27, '2010-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 11, 'Viking Pride', 'Nancy, trying to get she and her family out of the country, is continually faced with unexpected guests from her past. Andy has to get creative in order to secure passports while Doug must find his own means of obtaining one. Meanwhile, Silas deals with the possibility that Lars could be his father. Shane is left to deal with Warren who is becoming unhinged.', 28, '2010-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 12, 'Fran Tarkenton', 'Nancy has a tense, one-on-one, sit-down interview with Vaughn. Andy, Shane and Warren to get more cash plus passports they''ll need for the family to enter Europe. Silas continues to wrestle with the fact that Lars may be his father. Meanwhile, Doug returns to Agrestic to locate his passport.', 28, '2010-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 6), 13, 'Theoretical Love Is Not Dead', 'In the season 6 finale, Nancy must free herself from the grip of Esteban in order to escape the country along with her family. At the airport, Andy attempts to calm the nerves of Shane and Warren. Meanwhile, Silas must decide whether to stay with Lars or leave with the Botwins.', 28, '2010-11-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 7, 'Season 7', 'The seventh season of Weeds premiered on June 27, 2011 at 10 E/9 C on the television cable network Showtime, and consisted of 13 episodes. As the season picks up, Nancy has spent three years in prison and now lives in a strictly monitored halfway house in New York City, where the family meet after the other Botwins have spent three years in Denmark.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 1, 'Bags', 'Three years after Nancy''s selfless act to save her family, Andy, Silas, Shane and Doug live their new lives in Copenhagen. When Nancy is released early from prison and put on parole to a New York halfway house, she finds out that she doesn''t need witness protection anymore.', 25, '2011-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 2, 'From Trauma Cometh Something', 'Nancy tries to get back on the right track after being released from prison, but faces a tough struggle living in New York City; Andy and Shane show up at Nancy''s door, sending her for a loop and tempting her to go back to her old ways.', 27, '2011-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 3, 'Game-Played', 'Nancy struggles to fit into the ranks at the halfway house; Jill drops a bombshell; Andy and Shane find a place to live; Silas scores a modeling gig; Doug is offered his dream job.', 28, '2011-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 4, 'A Hole in Her Niqab', 'Nancy pursues a job at Doug''s office; Andy may be in over his head; Shane tries to set up house; Silas attempts a partnership.', 28, '2011-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 5, 'Fingers Only Meat Banquet', 'Silas and Nancy''s lawyer assist her in getting to California as her custody battle with Jill heats up. Meanwhile, Andy''s relationship takes an intriguing turn; Shane decides to give it the old college try and enrolls in classes; and Doug is left to fend for himself at his job on Wall Street.', 25, '2011-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 6, 'Object Impermanence', 'Nancy confronts an old friend, leaving Silas caught in the crossfire; back at the loft, Andy comes up with a new business venture, and turns to Shane and Doug for help.', 28, '2011-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 7, 'Vehement vs. Vigorous', 'While Doug plays softball with the company team, Nancy deals pot on the sidelines; Andy opens his bike shop while Silas sells pot out of the back room; and a police detective offers Shane an internship.', 26, '2011-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 8, 'Synthetics', 'Nancy''s former cellmate Zoya shows up and complicates things between Nancy and her supplier; Silas and Andy bang heads over how to best utilize the bike shop; and Shane''s internship provides him with some surprising lessons.', 27, '2011-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 9, 'Cats! Cats! Cats!', 'Nancy and Andy try to put the brakes on Zoya''s attempt to take over the bike shop; Silas has an encounter with some local rival dealers; and Doug must do some business with the Securities and Exchange Commission.', 26, '2011-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 10, 'System Overhead', 'Nancy, Andy and Silas strike back at Emma; Doug has to keep his hedge fund up and running; Shane ends up closer to the law.', 26, '2011-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 11, 'Une Mère Que J''aimerais Baiser', 'In an attempt to further expand her business, Nancy follows Doug and Andy to the Hamptons for the weekend; Silas tries to win Emma back after a falling out over business; Detective Ouellette brings Shane along on a drug bust.', 24, '2011-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 12, 'Qualitative Spatial Reasoning', 'Nancy and Silas face off over who controls their drug business, while Andy tries to mediate; Shane goes to lengths to win back Detective Ouellette''s trust, while Doug tries to keep the SEC distracted from his hedge fund''s illegal activities.', 26, '2011-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 7), 13, 'Do Her / Don''t Do Her', 'In the Season 7 finale, Silas turns the tables on Nancy, as Shane makes one last attempt to keep her out of harm''s way and the clutches of Detective Ouellette. Meanwhile, back on Wall Street, Doug schemes to keep his hedge-fund scam alive.', 28, '2011-09-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')), 8, 'Season 8', 'The eighth and final season of Weeds premiered on July 1, 2012, and featured 13 episodes, bringing the series total to 102. It marks the return of the show''s theme song, "Little Boxes". Creator Jenji Kohan revealed that cover versions of the song would be used during the opening credits and confirmed that Ben Folds and the Mountain Goats would be featured artists. Kohan also confirmed that the song would be covered in a duet by Steve Martin and series regular Kevin Nealon, who each sang and played the banjo. Series co-star Hunter Parrish also provided a cover version for the season''s tenth episode. The final two episodes of the season aired back to back as a one-hour series finale, which was the series'' first and only one hour show in its eight-year run.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 1, 'Messy', 'Nancy is rushed to the hospital after being shot as the family follows close behind. The family grapples with the tragedy and hypothesizes on the shooter''s identity.', 26, '2012-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 2, 'A Beam of Sunshine', 'Andy makes his intentions known to Jill. Doug is presented with an enticing investment opportunity. While Nancy recuperates, Silas helps her with a new business venture. Shane figures out who shot his mother.', 28, '2012-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 3, 'See Blue and Smell Cheese and Die', 'Andy attempts to impress Jill by coaching the twin''s roller-derby team; Doug ponders about his financial future after being forced to resign from the company; Nancy and Silas race to thwart Shane''s actions, who is closing in on Tim.', 27, '2012-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 4, 'Only Judy Can Judge', 'Despite the demands of her marijuana business, Nancy decides to throw a family dinner, to which Shane invites his classmate Angela. In other pot news, Silas befriends a local grower. Meanwhile, Jill and Andy agree to watch Stevie during the day.', 27, '2012-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 5, 'Red in Tooth and Claw', 'Nancy is tempted to go back to her old pot-dealing ways to raise cash for Stevie''s soccer expenses; Jill gets revenge on Andy through Doug; Shane and Angela double-date with Ouellette and his wife; Silas and R.J.''s friendship takes an unusual turn.', 28, '2012-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 6, 'Allosaurus Crush Castle', 'Nancy undertakes a job search; Jill has big news for Andy and Doug; and Silas tries to track down his stolen plants. Meanwhile, Shane fabricates an ingenious plan to score some extra spending money at the police academy.', 28, '2012-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 7, 'Unfreeze', 'Andy visits a local synagogue to look for work while Nancy gets a quite competitive new job and Shane is ready to graduate from the police academy.', 28, '2012-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 8, 'Five Miles from Yetzer Hara', 'After receiving an interesting proposal from an unexpected source, Nancy struggles with a decision involving a questionable business.', 28, '2012-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 9, 'Saplings', 'A "cowboy capitalist" moseys into town with a tasty offer for Silas; and rumors spread about Rabbi Dave having an amorous encounter with a nonmember of the synagogue.', 28, '2012-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 10, 'Threshold', 'Silas contemplates a big professional move; Nancy has a dinner date with Rabbi Dave and some of his friends; and Andy experiences a slight hitch in his relationship status.', 28, '2012-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 11, 'God Willing and the Creek Don''t Rise', 'Nancy, Andy and Silas take a trip. Shane is busted for stealing property off the impound lot. Meanwhile, Doug gives up on his charity and decides to pursue a bigger, more lucrative scheme.', 29, '2012-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 12, 'It''s Time (1)', 'The Botwins (& Doug) are at a crossroads, romance-wise and professionally.', 29, '2012-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0439100')) AND numero_temporada = 8), 13, 'It''s Time (2)', 'At Stevie''s bar mitzvah, friends and family gather and Nancy tries to reconnect with her estranged loved ones.', 30, '2012-09-16');
