INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 1, 'Junk in the Trunk', 'Rachael Leigh Cook smashes more than eggs in her latest This Is Your Brain on Drugs public service announcement. Optimus Prime, leader of the Autobots, falls prey to prostate cancer. The outcome is never in doubt during "World''s Most One-Sided Fistfights Caught on Film." Outtakes from The Dukes of Hazzard, The X-Files, Battlestar Galactica and more come to light in "Bloopers."', 12, '2005-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 2, 'Nutcracker Sweet', 'Voltron engages in an old-school dance-off in "You Got Robo-Served." The secret lives of nature''s most fascinating beasts are exposed in "Secrets of the Animal Kingdom." Testicles are terrorized in "Ode to the Nut Shot." Walt Disney''s severed head with its giant robotic spider-body attacks Cuba. See how much the kids are horrified in "Scary Barney"', 12, '2005-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 3, 'Gold Dust Gasoline', 'The animals Noah left behind try to survive the flood in their very own ark. Enjoy instant nostalgia with "That ''00s Show." Mrs. McNally''s third-graders produce an animated abomination in "The Best Cowboy." The world''s most famous cars, from KITT to the General Lee and even Mario karts, race against each other in "3 Fast 3 Furious."', 12, '2005-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 4, 'Plastic Buffet', 'America sends Harrison Ford and Aerosmith into space to take out a killer asteroid in "Meteorgeddon." Household animals take to the slopes for "Winter Pet Games." Chucky from the Child''s Play series takes on the cutesy Lettuce Head Kids in the opening to season 8 of Buffy the Vampire Slayer. The Muppet Show''s band is spotlighted in "Behind the Music: Electric Mayhem."', 11, '2005-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 5, 'Toyz in the Hood', 'The tooth fairy stumbles into domestic violence and murder in "Tooth and Consequences." The world''s most diabolical supervillains get stuck in traffic. More of television''s greatest screw-ups, from CSI to Mister Rogers'' Neighborhood and Pro-sports, are highlighted in "Bloopers."', 12, '2005-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 6, 'Vegetable Fun Fest', 'The secrets of The Crying Game, Sleepaway Camp, Star Wars and The Village are exposed in "Welcome to the Spoilers." The Teen Titans strengthen their roster by adding Beavis and Butt-head. Travel back in time to witness Benny Hill''s funeral. The Great Pumpkin of Peanuts fame finally shows. Too bad he becomes murderous, and goes on a killing spree.', 11, '2005-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 7, 'A Piece of the Action', 'A teenage girl gets a fashion makeover in "Pimp My Sister." The Surreal Life gang gets sent on a mission to destroy an enchanted ring. Debbie Does Dallas gets re-told with the world''s cheapest puppets in "Exhausted Budget Theater." Geeks and nerds collide when a science fiction convention erupts into war.', 11, '2005-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 8, 'The Deep End', 'Seven of the world''s greatest heroes stop being polite and start getting real in "The Real World: Metropolis." Icons from Star Trek and Tiger Beat alike unite for canned sitcom laughs in "Two Kirks, a Khan and a Pizza Place." Jesus Christ hunts down his greatest nemesis, Tarantino-style in "Kill Bunny." The hottest game show from Japan is here: "Who Poop Last?!" The legends of rock ''n'' roll return from beyond the grave to haunt the "Zombie Idol" reality show.', 12, '2005-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 9, 'S&M Present', 'The last surviving member of ''N Sync, Joey Fatone, must avenge his murdered bandmates in a deadly martial arts tournament in "Enter the Fat One". Check out a little scrambled porn on your 1980s-era cable box. M. Night Shyamalan has endless fake-outs in store for viewers in "The Twist."', 12, '2005-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 10, 'Badunkadunk', 'The roller-coaster celebrity life of the Hulk is profiled in "Hollywood Spotlight." The Masters of the Universe are rocked by a Paris Hilton-style sex tape. Michael Jackson returns from space to confront his n''er-do-well alter ego in "Where''s Michael?"', 11, '2005-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 11, 'Toy Meets Girl', 'William Shatner''s toupee has adventures the action star can only dream of. Heaven is not all it is cracked up to be in "Can We Handle the Truth?" Hilary Duff''s new film combines history and teen drama in an updated "The Diary of Anne Frank." The fates of the greatest action figure toy lines from decades past are exposed in "Where Are They Now?" with host Michael Moore.', 12, '2005-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 12, 'Midnight Snack', '"The World''s Most One-Sided Fistfights" get wild at Mardi Gras. Benjamin Franklin grapples with historical figures like the Wright brothers and Mahatma Gandhi in "Educational Wrestling Federation." Oprah Winfrey fulfills all her viewers'' fondest wishes...almost. A man in a public restroom encounters the terror known as "Dumplestiltskin." "12 Angry Little People" deliberate a crime most heinous.', 11, '2005-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 13, 'Atta Toy', 'A teenage girl gets crazy about everyone around her. The world''s most famous monkey bursts loose on Skull Island in "Ding Dong, King Kong." Scandalous Hollywood news and gossip get the Pat O''Brien treatment. A father pigeon teaches his son to poop in a snorkel to make things wild. The Smurfs are terrorized by a murderer who kills based on the seven deadly sins in "Murder in Smurf Town X."', 12, '2005-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 14, 'Joint Point', 'Sailor Moon encounters a bone-chilling villain. A nerd wins a date with Scarlett Johansson. "Welcome to the Terror Drome" showcases inner-office machinations at the headquarters of G.I. Joe''s nemesis Cobra. "America''s Most Tragic Home Videos" will make you laugh and cry.', 12, '2005-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 15, 'Kiddie Pool', 'Michael Knight''s talking car parties hard in "KITT''s Day Out." A brawl rocks the nursing home in "Grandma Fu." Mary-Kate and Ashley Olsen unite to fight a rampaging dragon. George Jetson''s murder takes center stage in "Unsolved Case Files: I, Rosie."', 12, '2005-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 16, 'Nightmare Generator', 'Jaws gets a special edition DVD. A drug operation at the North Pole is revealed in "Unsolved Case Files: Claus & Effect." The A-Team solves its problems with maximum firepower and minimal intelligence.', 12, '2005-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 17, 'Operation Rich in Spirit', 'A new video game is taking video games by storm, "Codename: The Abortionator." A video dating experience a la The Ring scares a potential suitor. A man runs away from an Oriental masseuse looking for a "happy ending". Keanu Reeves, Christopher Walken, and William Shatner want you to buy his special brand of sausage. The Scooby-Doo gang encounters Jason Voorhees at Camp Crystal Lake.', 12, '2005-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 18, 'The Sack', 'It''s Alien vs. Predator on the battleground of love in a special episode of "First Date". Frogger creates a huge car wreck in this episode. See what the future holds in the Carousel of Tomorrow. Popeye experiences a world without his hamburger-leeching friend in "It''s a Wimpy-Filled Life." The modern video game Halo invades the old-school classic Donkey Kong. The cereal spokesbunny Stix Rabbit finds himself a new way to make a buck.', 11, '2005-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 19, 'That Hurts Me', 'Dean Devlin and Roland Emmerich re-make Godzilla...again. A crime-fighting monkey saves monkeys from a monkey supervillain. An average fellow named Doug wakes up in the world of the Huggytime Bears. Freddy Krueger, Jason Voorhees, Leatherface, Pinhead, Ghostface and Michael Myers sign on for the reality show "Big Brother".', 11, '2005-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 1), 20, 'The Black Cherry', 'Napoleon Bonamite pops up as a famous figure from history. Fizzing candy has terrible repercussions for young Mikey. Pennywise the Clown explains why everything floats in the sewers. A weakling turns into the "King of the Beach" with some illegal help. The laughter is canned for the sketch comedy show "You Can''t Do That on Robot Chicken."', 12, '2005-07-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 1, 'Suck It', 'Robot Chicken gets un-canceled! Learn tips for fighting terrorism! Mexico builds its greatest hero in "The Six Million Peso Man." Skater McGee is a re-animated corpse; an extreme re-animated corpse! Two aliens from Space Invaders revolt. A nerd polishes a unicorn''s magic horn. And it''s Mr. & Mrs. Smith, ''70s style in "Mr. & Mrs. Brady"! Space Ghost, Master Shake, and Peter Griffin come in.', 12, '2006-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 2, 'Federated Resources', 'A time-traveler wreaks havoc on history in "Dicks with Time Machines", but after he ends World War II by humiliating Adolf Hitler during a speech, the title changes to "Heroes with Time Machines". Lion-O, leader of the ThunderCats, is adopted as a little girl''s pet. Clifford the Big Red Dog gets in big red trouble. Evel Knievel wows his nursing home. The Swedish Chef "borks" his way through New York City. Corey Haim and Corey Feldman reunite to rescue the President''s daughters.', 12, '2006-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 3, 'Easter Basket', 'Fred and Barney brawl over a box of Fruity Pebbles. Kids have fun with the Phyllis Diller Spray-n-Play. An Egyptian pharaoh builds a pyramid out of Lego, with some "minor" design changes. Superspy Sydney Bristow gets aquatic in ''"Whalias". Anime and Santa collide in "A Very Dragon Ball Z Christmas".', 12, '2006-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 4, 'Celebrity Rocket', 'A Cuban youth plays Castro in "Dance Dance Counter-Revolution." Dirk the Daring from the video game Dragon''s Lair fights middle age. Mr. Six, the old dancing guy from the Six Flags commercials saves, and ruins, the day. Lindsay Lohan enters the world of Highlander and battles (and decapitates) teen starlet foes, such as Amanda Bynes and Hilary Duff.', 12, '2006-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 5, 'Dragon Nuts', 'People of all ages (including actor Bruce Campbell) love the new toy, "Morning Wood!" A man''s groin is possessed in "Idle Nuts". Live in fear when a giant midget attacks! A cleaning woman finds the Batcave the hard way. Atreyu and Falkor kick off a Neverending Party! An Omaha evening news broadcast spins out of control, with Paris Hilton as a weather reporter, and traffic copters anxiously watching a car, parodying Spy Hunter!', 12, '2006-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 6, '1987', 'Twinkie the Kid dispenses justice and lead! Popular board games from Chutes and Ladders to Hungry Hungry Hippos get turned into action-packed feature films. Meet Skeletor''s dentist, Mo-Larr! Emperor Palpatine gets a collect call from Darth Vader. Mortal Kombat''s Johnny Cage has a bad day on the job. An enraged Ted Turner transforms into his alter-ego, Captain Planet!', 12, '2006-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 7, 'Cracked China', 'Learn the secret of what Pikachu is up to inside his Poké Ball! Stupid kids get a new high from "numb-chucking." A checkers champion goes on the adventure of a lifetime. Meet Eagle Eye Smith, the blind athlete who will touch your heart. Then meet the four "My Little Ponys of the Apocalypse." The Golden Girls share their sexual escapades a la Sex and the City.', 12, '2006-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 8, 'Rodiggity', 'The Senior Mutant Ninja Turtles rock the nursing home! Rick Schroder is fighting crime in style in his new hit series "Rick Shaw". Order your movie tickets from Fan-Dingo, the paper bags want you to. The cast of Final Fantasy VII get jobs at a burger chain, and Sephiroth makes Cloud work overtime. The Booger Man makes a mess. Bugs Bunny goes hip-hop in "8 Carrot" (along with Porky Pig, Elmer Fudd, Daffy Duck, and Dr. Dre).', 12, '2006-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 9, 'Massage Chair', '"Cuddles," the fabric softener bear gets the wrong kind of hug. Corporate disputes get solved hand-to-hand in "Office Kombat." Monkeys explore outer space on a budget. George W. Bush discovers he has Jedi powers. And we''re back with more of those stupendous bloopers, including auditions tapes from MTV''s Jackass!', 12, '2006-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 10, 'Password: Swordfish', 'Care Bears care a lot...about ethnic cleansing. See the action-packed story of Heimlich and his quest to unblock your windpipe in "Heimlich Begins." A young soccer player named Ricky faces life''s obstacles. Harry Potter uses magic to fight the evil monster, Pubertus! Rated TV-MA.', 11, '2006-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 11, 'Adoption''s an Option', 'Robot Chicken whores itself out to corporate America. The Fantanas visit the Middle East peace Process. E.T. finally returns home and interacts with his peers. The secret life of jack-o''-lanterns are finally revealed. A child''s spaceship spells bad news for Dad. The mythical Pegasus meets a demented little girl. Skynet goes online, turning Inspector Gadget into an unstoppable killing machine!', 12, '2006-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 12, 'The Munnery', 'Meet Cork, America''s first mentally-challenged crime sleuth! The legendary Krakken sea monster learns freedom isn''t all it''s "krak-ed" up to be. "Weird Al" Yankovic''s "Weasel Stomping Day" gets a Robot Chicken music video treatment! The wishes of children come true, with dire results. The crew of the Starship Enterprise faces their gravest foe yet - themselves!', 12, '2006-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 13, 'Metal Militia', 'A kid gets a used-car surprise: a Tron light-cycle! Young Indiana Jones finds treasure in his elementary school. Rom the Spaceknight meets his ultimate nemesis! Into the Blue gets a relevant skewering. Murky and Lurky make a gruesome discovery when they try to rob Rainbow Brite. Hulk Hogan busts out of prison camp in "Hogan''s Heroes." Rated TV-MA.', 11, '2006-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 14, 'Veggies for Sloth', 'The classic movie The Beastmaster takes Broadway by storm. Lance Armstrong gets revenge on France. Buck Rogers learns what his name rhymes with. The gang from Archie Comics learn that nobody cheats Death for long! Rebroadcast as "Blankets in a Pig" on May 15, 2008 with Britney Spears as Citizen Spears instead of the Archies as the final segment.', 11, '2006-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 15, 'Sausage Fest', 'Lil'' Hitler will win your heart! The Library of Heaven yields answers even God doesn''t want you to know. The Burger King serves up some delicious B&E. Garfield and Heathcliff face off in court. A giraffe deals with the five stages of grief. The gang from Police Academy joins the X-Men. Rated TV-MA.', 12, '2006-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 16, 'Drippy Pony', 'Learn the secret life of Batman villain, The Penguin! Kids will love playing with "My Stalker!" Orlando Bloomin'' Onion must help his fellow passengers survive after a plane crash - with his delicious deep-fried onion hair! Jesus and the Argonauts find action and adventure, and turn the other cheek. The Micronauts climb the mountains which are big breasts. The U.S. government declares a war on Christmas.', 12, '2006-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 17, 'A Day at the Circus', 'Snow Job finds his specialized skills aren''t in high demand with G.I. Joe. Thing grows up and leaves The Addams Family nest. The Memory Game challenges the brainpower of contestants, and the penalty for failure is death! The Black Stallion teaches us about race relationships. Oprah and Dr. Phil team up in the greatest buddy cop movie ever!', 12, '2006-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 18, 'Lust for Puppets', 'Montezuma gets his revenge, and the results smell horrible. Cameron Diaz has just 24 hours to live! Calvin and Hobbes have fun therapy adventures. Mario and Luigi stumble into the violent world of "Grand Theft Auto."', 12, '2006-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 19, 'Anne Marie''s Pride', 'Mr. T and the Foo Fighters forge an unlikely alliance. Stretch Armstrong needs a corn syrup transplant. A guy dates his GPS navigational system. Learn the untold origin of Alvin and the Chipmunks! Roger Ebert and guest reviewer M. Night Shyamalan present upcoming feature films including Transporter 3, Happy Madison, Rudy 2, The Nightmare Before Hanukkah, and Speed 3, along with a sneak peek at Schindler''s List 2: Schindler''s Pissed.', 12, '2006-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 2), 20, 'Book of Corrine', 'Vince Vaughn presents his new hit show, "Vince Vaughn Bangs Your Mom." Meet Casper''s brother, "Jasper, the Douchebag Ghost." Ninjas compete in a game show. A nerd gives us a much-needed lesson on Gobots. The cast of Sesame Street deals with a viral outbreak when Big Bird catches the bird flu. A robot learns what it means to be alive. Robot Chicken holds a telethon that goes horribly awry.', 11, '2006-11-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 1, 'Werewolf vs. Unicorn', 'All the people killed in the 2nd season finale return as zombies. The Defenders of the Earth accept their limitations. Shout On and Shout Off with The Shouter. The Decepticon Soundwave discovers he’s a little dated. People can lose at The Game of Life. Governor Arnold Schwarzenegger investigates the illegal immigration issue with Speedy Gonzales and Dora the Explorer.', 12, '2007-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 2, 'Squaw Bury Shortcake', 'The MythBusters team tackles masturbation myths. G-Force’s Tiny needs to shed a few pounds. Popeye’s friends hold an intervention over his addiction to spinach. Godzilla takes a rookie out for a Training Day. Tablesmasher attempts to defeat The Council of Evil Tables. Dirty Harry deals with a punk that does feel lucky. After retirement, Bob Barker handles the neutering personally.', 12, '2007-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 3, 'Rabbits on a Roller Coaster', 'Randy experiences cross-dressing as the Pink Ranger and death in The Worst Halloween. The crew of Battlestar Galactica defeats the FCC threat. Dick Tracy earns his name. Behold, the newest adventure of Turbo Teen. M.A.S.K.’s Matt Tracker takes a bride.', 12, '2007-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 4, 'Tapping a Hero', 'Law & Order has never been chickenfied till now. President George W. Bush receives a gremlin. Don''t miss "The 33rd Year Old Virgin" starring Jesus Christ. Smokey Bear remembers how he got his name. Stan Lee and Pamela Anderson reveal superhero gossip on "Superheroes Tonight."', 12, '2007-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 5, 'Shoe', 'Ted Kennedy and Jenna Jameson battle celebrities in politics and porn! Link''s looking for a decent reward from Princess Zelda. The Homeless airlines sorta take flight. The SWAT Team finally "gets" Sonic the Hedgehog for speeding. Learn whatever happened to the Micro Machines Man. Skeletor''s latest plot to destroy Eternia and He-Man goes a little too well.', 12, '2007-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 6, 'Endless Breadsticks', 'Another black man in a fat suit movie. Big Jim tries to score. The Cat in the Hat has his way with the family pet and the kids need to get lost. Doug tells us about his life. When Snarf kicks it, Mumm-Ra sees his chance to destroy the ThunderCats as Lion-O''s new nanny.', 11, '2007-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 7, 'Yancy the Yo-Yo Boy', 'The dinosaurs face their Armageddon. Barbie and Yasmin (of the Bratz) go head-to-head on MTV''s Exposed. What happens on Tuesday when Wimpy has to pay for his burgers? The Greatest American Hero or greatest American nerd? Find out how infinite wealth has affected Richie Rich''s teenage years.', 12, '2007-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 8, 'More Blood, More Chocolate', 'An alien invasion isn''t quite what it seems. Haunted houses are common, but not one with THIS kind of ghost! Can Bob the Builder take on the union? Probably. "Inside the Battlefield" revisits G.I. Joe''s and Cobra''s battle of the Weather Dominator, twenty years later.', 11, '2007-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 9, 'Celebutard Mountain', 'Our PS3 Contest winner gets what''s coming to him. Mr. Rogers is turning Japanese. Spawn faces the Devil with his one true skill - fiddling. Fonzie takes care of Chachi the best he can in The Pursuit of Happy Days. Iron Man''s feet become his greatest weakness. VH1''s "Top 100 Final Episodes" features the end of Mork & Mindy, The Love Boat and more.', 11, '2007-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 10, 'Moesha Poppins', 'The Empire Strikes Back''s Lando Calrissian led our heroes into a dinnertime trap with Darth Vader, and hilarity''s the main course! In the spirit of 300 comes 1776. Michael Moore uncovers whatever happened to the girls'' toys of yesteryear.', 11, '2007-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 11, 'Ban on the Fun', 'The Maytag Man helps out...with his life. Crystar the Crystal Warrior gets smoked. Thelma & Louise regret their suicidal ways. The Maytag Repairman''s life really sucks. The Laff-A-Lympics gang faces their darkest games ever: Munich, 1972.', 12, '2007-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 12, 'Losin'' the Wobble', 'The Kool-Aid Man quenches some inconvenient thirsts. The mystery of why Encyclopedia Brown''s parents aren''t getting along. Wonder Woman reveals her revealing arch-enemy. Drunk celebrities are revealed to be reptilian-like aliens, referencing the 1983 made-for-television science fiction movie "V".', 12, '2007-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 13, 'Slaughterhouse on the Prairie', 'She-Ra cannot get a moment of peace as Etheria is constantly under attack while she suffers from period pains. The Grease Gang create a new hump machine. The Magic Garden discovers that the story box has a biblical story they will never forget. Lego goes Babel! The Smurfs Village is ravaged by a hurricane.', 12, '2007-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 14, 'Robot Chicken''s Half-Assed Christmas Special', '...Christmas Special: Hermey the Elf sucks at being a dentist. All Sally wants is a love note, but for Linus it''s Misery. A nerd is stuffed into a locker and into the magical and confusing land of Narnia.', 12, '2007-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 15, 'Tubba-Bubba''s Now Hubba-Hubba', 'The Super Friends make way for The Super Pets. The Carmen Sandiego host has girlfriend troubles. Pac-Man learns that he’s been living in The Matrix. The car version of Voltron gets to the rescue as fast as it can. The Cenobites guest star on Girls Gone Wild. 24 focuses on the night hours as Drac takes down the terrorists. This Episode aired on adult swim as a April Fools day Prank for a sneak peek of upcoming shows.', 12, '2008-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 16, 'Boo Cocky', 'Conan the Barbarian tells us "What is Best in Life" with a song. The Nerds find out Revenge comes with a price. President Jenna Bush trades the Oil Crisis for the Corn Crisis. The Saved by the Bell kids meet Jigsaw from Saw, and Screech will never be the same. The Borg track the Enterprise to its hiding place—Las Vegas’ Star Trek Experience.', 12, '2008-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 17, 'Bionic Cow', 'Sylar gets a new power in a Heroes parody. Behind the scenes of Excitebike. Mr. Magoo gets Laser Eye Surgery. Tarzan learns that not everything humans can teach him are as good as Jane’s boobs. When Paris Hilton was stuck in prison, it was up to Nicole Richie to stage a Prison Break.', 11, '2008-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 18, 'Monstourage', 'Vic Mackey from The Shield switches places with the Fantastic Four’s Thing, which references Michael Chiklis as he portrays both. Cowboys on a cattle drive have it bad in biblical proportions. Bronson Pinchot and Ludacris star in the off-Broadway production of "Don’t Be Ridiculous". Fraggle Rock meets Watership Down when the Fraggles are forced out of their home and onto a desperate hunt for survival.', 11, '2008-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 19, 'President Evil', 'Diggers have Dug their own grave, Dig Dug-style, ya dig? You’ve never seen a Vegas crime caper like Ocean’s Thirty-Eight. The government tries to contain an outbreak of cooties. Teenagers are exposed to movie trailers, but they’re not exactly watching the screen. Rated TV-MA.', 12, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 3), 20, 'Chirlaxx', 'The latest Japanese commercial for a yeast infection cream needs a famous pitch-woman. The enemies of America are on the run as President Bush becomes…Captain Texas! Sir Mix-a-Lot knows what King Arthur needs! A Glo Worm saves the day when a blackout strikes. We dedicate the season to the staff we’ve lost…and killed.', 12, '2008-10-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 1, 'Help Me', 'Seth and Matt enlist the help of Joss Whedon, Ron Moore and Seth MacFarlane to get their show renewed. PaRappa the Rapper is facing criminal charges when he takes his teacher''s advice and does a rap that rats out the real criminal. Filming of an episode of Tila Tequila''s "A Shot at Love" is interrupted when it''s revealed that she''s an experimental cyborg. Movie and TV favorites are trimmed down to "Just the Good Parts."', 12, '2008-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 2, 'They Took My Thumbs', 'A contractor demonstrates the various death traps being built to protect a temple from intruders. Jason Voorhees gets ready for Friday the 13th. Wildman shares some summer fun tips with a group of kids. What happens when the Justice League struggle through "Bring a Sidekick to Work Day?"', 12, '2008-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 3, 'I''m Trapped', 'Homonyms are explained in an educational musical. Vice President Dick Cheney is captured by terrorists and held captive along with Tony Stark. The truth behind James Bond''s sex life is revealed. Skeletor''s plot involving a less-than-perfect clone of He-Man doesn''t work out well.', 12, '2008-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 4, 'In a DVD Factory', 'It''s been said that "only" a silver bullet can kill a werewolf, but we''ll see about that! Witness the secret origin of Composite Santa Claus. The amount of advance planning Daredevil has to make in advance of a dramatic entrance is revealed. As the world mourns Hannah Montana''s death, her friends continue to protect her secret identity as Miley.', 12, '2008-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 5, 'Tell My Mom', 'Joey Fatone gives a pitch for a new sketch featuring himself. Sam Witwicky gets new scooter. The true story is revealed behind Billy Joel''s hit single, Piano Man. Annie learns about orphans in various countries. If you have a problem and the A-Team can''t be reached, maybe you should hire the B-Team!', 11, '2009-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 6, 'PS Yes, In That Way', 'Billy Dee Williams goes shopping. The Peculiar Purple Pie Man gets accused of stealing Black Cherry Pie''s black cherry. The Henderson family says goodbye to Harry, and get an unwelcome sendoff from his cousin in return. G.I. Joe takes on a new member, but they take the razzing a little too far.', 12, '2009-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 7, 'Love, Maurice', 'There is an uprising in the kingdom and Babar must fight for his life! Bitten by a radioactive deer, a new superhero is born: Kid Venison! Roger Rabbit makes a deal with O.J. Simpson. Steve Austin convinces Oscar to rebuild Jaime Sommers into his ideal Bionic Woman. Terminator Baby is sent to protect John and Sarah from Terminator Puppy.', 12, '2009-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 8, 'Two Weeks Without Food', 'Zeus decides to spice up "Clash of the Titans" with a monster truck! A young Iron Man fan gets swept up into a battle involving the Avengers and a giant robot. "Star Trek II: The Wrath of Khan" is re-imagined as an opera. Speed Racer competes in NASCAR Racing. When Dorothy leaves Oz, it''s back to business as usual for the Wizard. Watch the latest edition to MTV''s "The Hills."', 12, '2009-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 9, 'But Not In That Way', 'A girl''s father becomes obsessed with her own favorite anime show: Inuyasha. The Giving Tree has much to give. Punky Brewster discovers boys, leaving Glomer forgotten and alone in his closet. Stephen King meets his new neighbor, Dean Koontz. Black Manta narrates a story about the Joker''s life in prison in "The Arkham Redemption."', 11, '2009-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 10, 'I Love Her', 'What would happen if the Monchhichis drew first blood? Criss Angel substitutes for Professor Snape at Hogwarts. What would happen if the Power-Puff girls were on drugs? Freddy Kreuger''s day gets off to a bad start thanks to ill-conceived gifts from his daughter. In an episode of "Living Lohan", the nerds next door have to contend with their unruly neighbors.', 12, '2009-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 11, 'We Are a Humble Factory', 'The creators imagine an alternate ending to Armageddon, what a new Star Trek character might look like, the excitement that is M.A.S.K. And the WWF''s new up and coming challenger.', 12, '2009-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 12, 'Maurice Was Caught', 'Simon Belmont knows what works, Kermit introduces everyone to his cousin and the creators imagine what the new Gone With The Wind Re-make might look like, plus Annie Warbucks celebrates her Super Sweet Sixteen.', 12, '2009-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 13, 'Unionizing Our Labor', 'Superman takes it all off, meet the original Dukes of Hazzard, the creators imagine what the new Wii might look like and things come to blows when the Smurfs take on the Snorks.', 12, '2009-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 14, 'President Hu Forbids It', 'The Batmobile loses its wheel, spend a night with Jack Sparrow, the creators imagine what happens when Chris Hanson can''t catch a predator, plus Gyro-Robo adds some depth to D & D.', 12, '2009-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 15, 'Due to Constraints of Time and Budget', 'Indiana Jones knows when to keep his eyes shut, Transformers morn a fallen hero, the creators imagine what goes on in a Yellow Submarine, plus meet the new Transporter.', 11, '2009-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 16, 'The Ramblings of Maurice', 'Batman gets a new look at Two Face, G.I. Joe celebrate their years in service, the creators imagine what the next Traveling Pants movie might look like, plus a new Dark Crystal for the next generation.', 11, '2009-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 17, 'Cannot Be Erased, So Sorry', 'The creators imagine what the Humping Robot might look like on the big screen, John Connor tests out the new Terminator, Fantasy Island lives up to its name and the Nerd lands somewhere over the rainbow.', 12, '2009-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 18, 'Please Do Not Notify Our Contractors', 'Jason Bourne gets a new identity, the new Bachelor''s a beast, the creators take a skewed look at the Holy Grail and meet a character who knows how to speed things along.', 12, '2009-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 4), 19, 'Especially the Animal Keith Crofford!', 'The creators imagine the origin of the Wuzzles, what Cloverfield''s real intention was, a new spin on Hitchcock''s Rear Window, plus a super sappy season ender.', 12, '2009-09-20');
