INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 2, 'Saving Private Gigli', 'The creators imagine how Cabbage Patch Kids are made, what the real reaction to shows like STOMP! are, and we see what Skeletor is forced to do when Snake Mountain is foreclosed on.', 12, '2011-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 3, 'Terms of Endaredevil', 'Discover the secret origins of Mo-Larr, Eternian Destist! Lara Croft makes a terrifying find in a tomb, He-Man''s father proves that sometimes the apple falls very, very far from the tree, and the creators imagine how Gargamel might finally get the best of the Smurf''s in Smurfitar!', 12, '2011-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 4, 'Big Trouble in Little Clerks 2', 'The creators imagine what goes on deep in the jungles of Pandora late at night, Harold and his purple crayon go on an adventure in a bad neighborhood, Major Nelson uses Jeannie to get back at NASA for firing him, and everyone in the G.I. Joe ranks gets to animal sidekick.', 12, '2011-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 5, 'Kramer Vs. Showgirls', 'Kim Possible''s Dr. Drakken gets sent to prison, NASA''s Lego people have a very bad launch day; see how Andy treats his toys after he comes home from college in Toy Story 4, and we find out what happened to some of our most memorable TV characters from the 90''s. All this and more from the minds of the creators.', 11, '2011-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 6, 'Malcolm X: Fully Loaded', 'Find out what crimes your Thanksgiving turkey committed and was then pardoned for. The creators re-imagine the movie Marley and Me. See who earns the title of lamest villain ever.', 11, '2011-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 7, 'Major League of Extraordinary Gentlemen', 'The creators give us the best 60 seconds in TV history! Plus find out how the ice cream sundae was created; what having "Spider-sense" is really like, and if the Keebler Elves can defend their home against their greatest enemy: The Cookie Monster!', 12, '2011-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 8, 'Schindler''s Bucket List', 'Baby needs-a-name, from Strawberry Shortcake, gets a name no one will ever forget; a roast for Cobra Commander has a surprise ending and the creators finally reveal the secret of what happened to Skeeter from Muppet Babies.', 11, '2011-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 9, 'No Country for Old Dogs', 'Is the voice that Mortal Kombat''s Johnny Cage hears real or just in his own head? Also, the creators tackle the question of what was going through Morgan Freeman''s mind during his 2008 car crash. Find out what happens when a group of mentally challenged soldiers take on Hitler and the SS.', 11, '2011-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 10, 'Catch Me If You Kangaroo Jack', 'The creators ponder what a Diablo Cody eulogy would be like - home-skillett; the Joker finally gets what''s coming to him and find out how the Robot Chicken Nerd would fare in the world of Tron.', 12, '2011-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 11, 'Beastmaster & Commander', 'The creators imagine what CHiPs would have been like if the cops had actual potato chip heads, a magical zebra helps out a man with a broken cell phone, Green Lantern wears his ring on another part of his body, and the Bloopers Host returns with clips from his life.', 11, '2011-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 12, 'Casablankman', 'See! Rubik the Amazing Cube as he returns for one last adventure. Watch! As kids try out the newest fad - getting Supe''d. Discover! The secret behind a small doorway in a little boys room. And finally, the creators imagine what Eternia''s 24-hour gym might be like.', 11, '2011-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 13, 'The Departy Monster', 'Will the world ever find out what Master Chief looks like under his mask? What is life like for the pink Frankenstein''s Monster, Frankenberry? How did Princess Toadstool''s parents react when they first met Mario? How will the Scarecrow survive his time in the prison called Oz? The creators answer these questions and more in this thrilling episode!', 12, '2011-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 14, 'Some Like It Hitman', 'Think being a witch or wizard would be fun? The creators show you what life in Hogwart''s would really be like. Ever wonder why Winnie the Pooh likes honey so much? Can you say addict? Find out why Donald Duck''s nephew''s spend so much time with their uncle instead of their mother. All that, plus find out who''s ass Tommy Tapeworm will come wriggling out of.', 11, '2011-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 15, 'The Core, The Thief, His Wife and Her Lover', 'The creators imagine just how far Kratos, from the God of War series, will go to collect blood orbs. Superman flies back through time so he won''t have to hear Lois whine...ever again. The Velveteen Rabbit gets a raw deal. And what did the aliens from Close Encounters of the Third Kind really come to prove?', 11, '2011-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 16, 'The Godfather of the Bride II', 'Remember when MTV used to actually be about music? The MTV logo does and it''s out for revenge. The Robot Chicken Nerd dreams of hanging out with Michael Knight from Knight Rider. A bunch of Spocks from the future gather for a surprise party and the creators imagine what television will be like in the year 2013.', 11, '2011-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 17, 'The Curious Case Of The Box', 'Jesus & Grim Reaper, Dora the Explorer, Garden of Eden, slow motion clown car crash.', 12, '2011-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 18, 'Fool''s Goldfinger', 'Magneto makes Iron Man a ballet legend in Iron Marionette, Morpheus leaves a message on Neo''s answering machine, Walt Whitman causes trouble for a modern day high school student and the creators imagine a musical number from Grand Theft Auto''s Gay Tony.', 11, '2011-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 19, 'Casablankman II', 'Ever wonder how Doc Brown got the plutonium from the Libyan terrorists? Find out here! The creators imagine what it would be like if Jesus came down to talk to us normal humans. See what life would be like for Bella and Edward, who is a 109-year-old vampire.', 11, '2012-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 5), 20, 'Fight Club Paradise', 'The creators imagine what the movie Sex and the City 3 will be like if made more guy friendly, Yogi Bear battles with the Power Rangers from Jellystone Park, find out why no one cares about Woody Woodpecker anymore and see the nail biting, hair raising, super big finish of Season Five in Robot Chicken''s 100th episode finale!', 12, '2012-01-15');
