INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 9), 13, 'What Can You Tell Me About Butt Rashes?', 'The staff at Robot Chicken finally envision what a Sailor Earth would look like as the Sailor Scouts head out for churros. The Wicked Witch has some last-minute confessions you may not enjoy hearing. Richie Rich gets a lesson in capitalism.', 12, '2018-06-03');
