INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 9), 16, 'Jew #1 Opens a Treasure Chest', 'Robot Chicken is there when one of Scooby Doo''s villains realizes the silliness of his plan. Super Grover''s secret identity is revealed! Calvin grows up but Hobbes wants no part of it.', 12, '2018-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 9), 17, 'He''s Not Even Aiming at the Toilet', 'Robot Chicken reviews all the Star Wars plot holes that Galen Erso helped close in Rogue One. Peppa Pig''s family deal with Brexit fallout. Some swine dare to make a knock-off of the Broadway mega-hit Hamilton.', 12, '2018-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 9), 18, 'Your Mouth Is Hanging Off Your Face', 'Writers notice that King Kong fell from the Empire State Building butt-first; the Teenage Mutant Ninja Turtles don''t have money to pay for that pizza; the Smurfs try to smurf themselves some Sudafed.', 12, '2018-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 9), 19, 'No Wait, He Has a Cane', 'The writers of Robot Chicken tell Two-Face the most they''ve ever lost on a coin toss. The Joker bombs on stage, but not in our hearts. Jon Snow faces the greatest threat Westeros has ever seen!', 12, '2018-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 9), 20, 'Hi.', 'Robot Chicken ends the season with a bang and some nudity as the Nerd jumps the Grand Canyon. Stranger Things are happening to the school bully... VERY Stranger Things. Witness the greatest Japanese commercial of ALL TIME!', 12, '2018-07-22');
