INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 1, 'Ginger Hill in: Bursting Pipes', 'Season 10 explodes back onto the airwaves where the Robot Chicken Writers tell us what can take down the Teenage Mutant Ninja Turtles. Popeye and crew get rebooted to fit in with today''s audience. And Bitch Pudding takes on the role of a Handmaid.', 12, '2019-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 2, 'Bugs Keith in: I Can''t Call Heaven, Doug', 'The Robot Chicken crew shows us what events made Harold start drawing with his purple crayon. Jerry Seinfeld and The Joker have a very explosive chat in Jerry''s car. Miss Frizzle jumps on board the Fortnite Battle Bus and rides into battle.', 11, '2019-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 3, 'Fila Ogden in: Maggie''s Got a Full Load', 'April O''Neil and Donald Trump sit down and get to the truth about Shredder. We get a first glimpse at the next (and greatest) The Fast and The Furious movies. The RC Writers show us what happened to Pee Wee''s Playhouse while he was out looking for his stolen bicycle.', 12, '2019-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 4, 'Hermie Nursery in: Seafood Sensation', 'The Queer Eye guys take on their greatest challenge - The Babadook! Princess Leia gets blasted into space and emerges as Super Space Leia. And Robot Chicken puts together a musical number starring Offred and Commander Waterford from A Handmaid''s Tale will delight your ear holes.', 12, '2019-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 5, 'Garfield Stockman in: A Voice Like Wet Ham', 'Freddy Krueger is getting married and just wants an answer to one simple question: Who is his father? The RC team shows what it''s like being the daughter of a plastic Army Man. The Totally Spies girls learn what it''s like to violate international law...and get PTSD.', 12, '2019-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 6, 'Boogie Bardstown in: No Need, I Have Coupons', 'The RC creators imagine what would have happened if Stretch Armstrong had lived during Medieval times. The G.I. Joe team realizes that solving real world problems aren''t so easy. Gordon Ramsey gets some pretty impressive celebrity chef''s to be on his show, including the Thetans!', 12, '2019-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 7, 'Snoopy Camino Lindo in: Quick and Dirty Squirrel Shot', 'The Scooby Gang saves Velma from getting cancer; what really happened on Noah''s ark. The "Robot Chicken" writers wonder what happens to all the toys that have ever been recalled.', 12, '2019-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 8, 'Molly Lucero in: Your Friend''s Boob', 'Betty Spaghetty tries her best to save an elevator full of people. What goes on behind Bert and Ernie''s closed bedroom doors. “Godzilla: The Musical” comes to a Broadway theatre and brings the house down.', 12, '2019-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 9, 'Spike Fraser in: Should I Happen to Back Into a Horse', 'The "Robot Chicken" crew reveals what really happened to Bambi''s mother. An Animorph revives the Red Panda population. Brainy Smurf gets diagnosed with CTE. Bitch Pudding goes up against Norman Bates to see who is more psycho.', 12, '2019-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 10, 'Musya Shakhtyorov in: Honeyboogers', 'The Squatch Squad emerges from hiding to protect their forest home. The Wuzzles meet the Fly and things get a little bit crazy. The writers reveal Bill & Ted''s last and greatest adventure.', 12, '2019-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 11, 'Robot Chicken''s Santa''s Dead (Spoiler Alert) Holiday Murder Thing Special', 'Robot Chicken''s Christmas "whodunit" spoof. There''s been a murder on the North Pole Express and since each passenger could be the killer only Jesus can solve this tough case with many twisty turns. The suspects include Santa''s frienemy Krampus, Santa''s stereotypically Jewish nutcracker accountant called Nutsy Goldberg, Snowball the snowman, Santa''s inquisitive reindeer Comet, Christmas elf Peppermint, Santa''s gingerbread girlfriend and singer Ginger, the train''s accommodating porter and, of course, Tim Allen.', 12, '2019-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 12, 'Callie Greenhouse in: Fun. Sad. Epic. Tragic.', 'Batman''s addition to his costume causes some concerns among the other superheroes; a ride-along with the Westeros P.D. reveals how they solve crimes; Bitch Pudding is placed on Love Island to see what kind of match she will find.', 12, '2020-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 13, 'Max Caenen in: Why Would He Know If His Mother’s A Size Queen', 'The Lady of the Lake gives Percival some trouble when he goes to return Excalibur to her. The Robot Chicken crew shows what Dumbledore sees when he looks into the Mirror of Desire. Professor X reveals how the X-Men first discovered their powers. And Garfield gets buried in the pet cemetery.', 12, '2020-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0437745')) AND numero_temporada = 10), 14, 'Petless M in: Cars Are Couches of the Road', 'The RC writers imagine Harry Potter as a 70’s sitcom. The future looks bleak for Nostradamus’s assistant. We answer the question of what’s underneath Abe Lincoln’s hat. And the Jonas brothers learn they are more than just brothers.', 11, '2020-06-29');
