INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0445114', 'Extras', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0315041'), 'SERIE', 'Andy Millman is an actor with ambition and a script. Reduced to working as an extra with a useless agent, Andy''s attempts to boost his career invariably end in failure and embarrassment.', '2005-01-01', 'https://m.media-amazon.com/images/M/MV5BMGU5NmYzNDYtNGE0OC00YzkxLWIwMjctZGI3MzZlOWM0MTAxXkEyXkFqcGc@._V1_.jpg');
