INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')), 1, 'Season 1', 'Lincoln Burrows is currently on death row and scheduled to die in a few months for an assassination his younger brother Michael is convinced he did not commit. With no other options and time winding down, Michael takes drastic measures to get himself incarcerated alongside his brother in Fox River State Penitentiary. Once he''s inside, Michael, a structural engineer with the blueprints for the prison, begins to execute an elaborate plan to break Lincoln out and prove him innocent.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 1, 'Pilot', 'Michael Scofield, a structural engineer, attempts to rob a bank in order to get incarcerated at Fox River State Penitentiary, where his brother Lincoln Burrows, accused of murdering the Vice President''s brother, is scheduled to be executed. At Fox River, Michael approaches a number of inmates, all of whom play an important role in his plan to free his brother from the inside. Meanwhile, agents Kellerman and Hale are determined to make sure the execution goes through as planned. Lincoln''s son LJ gets into trouble.', 45, '2005-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 2, 'Allen', 'Michael seeks help of his fellow prison inhabitants to execute his escape plans.', 45, '2005-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 3, 'Cell Test', 'When Michael reveals his escape plan to Sucre, Sucre chooses to be no part of it, and requests a cell transfer. Michael gets a new cellmate called Haywire.', 45, '2005-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 4, 'Cute Poison', 'Veronica keeps uncovering new information regarding Lincoln''s case and decides she wants to work on the case full-time.  When no one wants to help her on the case, Nick Savrinn (an attorney) offers his assistance and the two of them visit Lincoln.', 45, '2005-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 5, 'English, Fitz or Percy', 'Kellerman and Hale blackmail Warden Pope. Michael finds out he might get out earlier than anticipated. Veronica becomes uncertain of her allies.', 45, '2005-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 6, 'Riots, Drills and the Devil (1)', 'Michael creates a lockdown by sabotaging the air conditioning in order to execute his breakout plan properly, and unintentionally causes a riot that gets Sara into huge trouble. Meanwhile, an ex-con is blackmailed into seeing to that Lincoln is killed.', 45, '2005-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 7, 'Riots, Drills and the Devil (2)', 'While the riot intensifies, Abruzzi and Sucre join forces. Michael must decide whether or not to save the life of Dr. Tancredi.', 44, '2005-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 8, 'The Old Head', 'Michael finds out a storeroom fundamental to his escape plans has been converted into a break room. Veronica and Nick are being threatened.', 45, '2005-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 9, 'Tweener', 'Abruzzi''s demotion in the prison hierachy puts the entire escape plan at risk. Michael finds himself in the uneviable position of trying to protect T-Bag''s new "fish" and facing the threat of T-Bag exposing the plan to the guards. The inmates dig themselves into a hole.', 45, '2005-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 10, 'Sleight of Hand', 'Michael is forced to give up Fibonacci''s location to Philly Falzone, and Kellerman and Hale get a little unwanted help to track down LJ who has gone missing. Veronica and Nick uncover evidence against the man Lincoln was convicted of murdering.', 45, '2005-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 11, 'And Then There Were 7', 'The escapees and Dr. Tancredi are shocked when they learn the identity of Michael''s visitor, who brings with her a very important piece of the escape plan.', 45, '2005-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 12, 'Odd Man Out', 'Michael sees proof his plan is working, so he begins to overcome the last obstacle. As the escape draws near, the group tries to reduce its number by one and targets T-Bag.', 44, '2005-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 13, 'End of the Tunnel', 'With Lincoln''s execution scheduled for the following day, Veronica comes out of hiding to contact him and gains an ally. Kellerman makes the ultimate sacrifice to preserve the conspiracy. Michael looks for a way to get Lincoln out of solitary confinement in time for the escape that evening. The inmates risk everything as they attempt their escape.', 45, '2005-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 14, 'The Rat', 'Veronica and Nick request a judge to postpone Lincoln''s execution. A C.O. becomes suspicious about a broken door.', 45, '2006-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 15, 'By the Skin and the Teeth', 'As Lincoln is about to be executed, he briefly sees his father in the viewing room. A phone call from judge Kessler delays the execution. After reviewing the newly surfaced evidence, the judge orders the exhumation of Steadman''s body.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 16, 'Brother''s Keeper', 'Flashbacks shed light on the past actions that led to the incarceration of Lincoln, Sucre, T-Bag and C-Note. Basis of Michael''s ingenious break-out plan are revealed. Dr. Tancredi memorizes how she ended up in Fox River State Penitentiary.', 45, '2006-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 17, 'J-Cat', 'Lincoln is worried about Michael''s sanity while Michael has trouble remembering some parts of the prison schematics. Sucre has to conceal the hole in the guard''s break room. Warden Pope transfers Michael to solitary after he declines his request.', 45, '2006-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 18, 'Bluff', 'In an effort to recreate the missing piece of the tattoo, Michael gets transferred to the psych ward, seeking the help of Haywire. T-Bag and C-Note have to join forces.', 45, '2006-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 19, 'The Key', 'Michael must get the key to the infirmary and enlist the help of an old face, while Lincoln learns the identity of his kidnapper and another inmate learns of the escape.', 45, '2006-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 20, 'Tonight', 'Westmoreland wants Michael to speed up the planned escape, and gets Bellick one step closer to unraveling it. Michael has to decide whether to involve Sara in the breakout plan. Tweener''s devotion is put to a test. Veronica finds out that her ally unexpectedly has a connection to an inmate serving time at Fox River.', 44, '2006-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 21, 'Go', 'Everyone''s ready to make their escapes across the high wire. Veronica and Nick realize they may be in over their heads. And Agent Kellerman helps Vice President Reynolds calm down before her debate.', 45, '2006-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 1), 22, 'Flight', 'As the escape is in progress, Warden Pope and Captain Bellick begin a search to detain the escapees. Michael and co. have to reach the aircraft fast as the police is hot on their heels. Veronica discovers a major piece of evidence that could prove Lincoln''s innocence. The Vice President is worried about losing her authority.', 44, '2006-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')), 2, 'Season 2', 'In season two, Michael, Lincoln and six other inmates, including pickpocket Tweener and the mentally unstable Haywire, have ultimately escaped from Fox River. Once outside the prison walls, however, the escape truly begins as the convicts race for their lives while trying to avoid capture by the authorities. The pursuers are led by FBI agent Alexander Mahone, who is haunted by his own demons; vengeful prison guard Captain Brad Bellick, who, driven by his own personal vendetta, will also stop at nothing until the escapees are captured or killed; and Secret Service Agent Paul Kellerman, who, under President Reynolds'' orders, will do anything to keep the truth about the conspiracy very much a secret.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 1, 'Manhunt', 'As eight hours has passed since the escape, Michael, Lincoln, Sucre, C-Note and Abruzzi attempt to evade their seekers. Bellick is forced to relinquish the command of the search party to FBI Special Agent Alexander Mahone whose ingenious approach makes Michael''s life as a fugitive harder. As a result from her overdose, Dr. Tancredi is in critical condition. A short-handed T-Bag faces the ultimate challenge.', 45, '2006-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 2, 'Otis', 'Mahone tries to lure the escapees by targeting an imprisoned LJ. Michael and Lincoln come up with a plan to free LJ from jail. Sucre, Abruzzi and C-Note have a plan of their own, but only to break free of their pursuers.Meanwhile, Bellick and Warden Pope feel the heat following their unsuccessful attempts to capture the escapees.Tweener infiltrates a bunch of college students on their way to spring break.', 45, '2006-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 3, 'Scan', 'Michael and a wounded Lincoln try to outmaneuver Mahone, who is hot on their trail. Sara gets a surprise visit to her bedside.Following his suspension, Bellick recruits a resolute partner to aid in his quest to get the escapees behind the bars.Sucre and C-Note head out for their family reunions-regardless of being observed by the authorities.', 45, '2006-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 4, 'First Down', 'Bellick, now teamed up with Michael, Lincoln and Nika, sets out to find the money stolen by Westmoreland during the 1971 skyjacking. Kellerman targets Sara, who receives a long-awaited phone call. T-Bag gets a ride from an unsuspecting family. Abruzzi resumes the search for Fibonacci to settle the scores once and for all.', 45, '2006-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 5, 'Map 1213', 'Michael and Lincoln are eager to locate the Double K ranch where Westmoreland hid his millions. Sucre goes to Las Vegas to prevent Maricruz from marrying his cousin Hector. C-Note gets on a train. Mahone is given an important package.', 45, '2006-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 6, 'Subdivision', 'Mahone takes an interest in the story of DB Cooper.In their quest to find Westmoreland''s treasure, Michael and Lincoln travel house-to-house in Utah. Haywire''s journey outside the prison walls continues. Sucre bumps into an acquaintance.', 45, '2006-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 7, 'Buried', 'Michael, Sucre, T-Bag and C-Note claim the hidden treasure.An anxious Lincoln risks everything to get to LJ. LJ grows wary about the easy getaway. Kellerman rethinks where his loyalties lie after Sara gets to The Company''s hit list. Mahone results to deadly force to get the truth out of Tweener.', 45, '2006-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 8, 'Dead Fall', 'In his efforts to try to get hold of all of the money Sucre runs into some unexpected difficulties. And Captain Bellick and his partner have not given up on finding their old inmates.', 45, '2006-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 9, 'Unearthed', 'In an effort to learn more about his pursuer Michael cozies up to Mahone''s wife. L.J. and Lincoln have a bumpy road-trip. T-Bag receives a surprise, and C-Note''s wife must choose between her daughter and husband.', 45, '2006-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 10, 'Rendezvous', 'As Michael reunites with Sara, Mahone and Kellerman strive to make sure they stay apart.On the road with LJ, Lincoln meets his father. Sucre tries to contact Maricruz. T-Bag has a reunion of his own.', 45, '2006-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 11, 'Bolshoi Booze', 'As Lincoln tries to reunite with Michael, he has to say goodbye to another loved one. Michael attempts to obtain a getaway plane. T-Bag gets revenge. Sara and Kellerman face-off.', 45, '2006-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 12, 'Disconnect', 'With Mahone on their trail, Michael, Lincoln, their father, and Sucre make a run for the getaway plane. Michael''s reunion with his father sheds light on his difficult childhood.The women in Bellick and Kellerman''s lives coerce their men to confess their sins.A medical emergency forces C-Note to risk it all.', 45, '2006-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 13, 'The Killing Box', 'Bellick is anything but happy about his sudden homecoming-to Fox River.Elsewhere, Michael and Lincoln might face a homecoming of their own. Mahone and Kellerman use everything they got to make certain that Michael and Lincoln do not get through their road trip alive.Sucre''s getaway plane encounters some difficulties. T-Bag closes on Mrs. Hollander.', 45, '2006-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 14, 'John Doe', 'Bellick gets a taste of the medicine he gave out when he was the Captain and Agent Mahone''s ex-wife makes another appearance.', 45, '2007-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 15, 'The Message', 'In Mexico, Sucre gets a car but gets in trouble by the police. Bellick has more trouble as the new inmate as prisoners who suffered with him want revenge.', 45, '2007-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 16, 'Chicago', 'C-Note gets into a tricky situation when a robber holds up the diner he is in and demands everyone go into the storage room until the police arrive. Michael, Lincoln and Kellerman get closer to revealing the conspiracy with the help of Sara. Mahone finds a new ally in Bellick.', 45, '2007-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 17, 'Bad Blood', 'Michael and Sara request Henry Pope''s help to retrieve the information that will topple The Company.Mahone pins down an escapee. Sucre discovers a new threat while hitchhiking to reunite with Maricruz. T-Bag brings the Hollander family to his home.', 45, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 18, 'Wash', 'T-Bag digs deep and finds his ''nice-side'' with the help of a psychiatrist. Michael, Lincoln, and Sara get their hands on evidence needed to bring down The Company, while Kellerman is close to finding the President.', 45, '2007-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 19, 'Sweet Caroline', 'An unlikely alliance forms between Bellick and Sucre while Michael is determined to face the president. T-Bag gets into some trouble when he loses his luggage and C-Note faces major consequences after some of his actions.', 45, '2007-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 20, 'Panama', 'Sara sacrifices herself for the safety of Michael so the brothers can get on with their final plan to attain freedom, but their plan gets ''shipwrecked''. Meanwhile, Bellick blackmails Sucre to partner up as T-Bag''s streak of murder continues to the south of the border.', 45, '2007-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 21, 'Fin Del Camino', 'The day has finally come for Sara''s trial while critical information that will exonerate her is being debunked. Meanwhile, Michael is determined to get his hands on the 5 million and to stop T-Bag''s reign of terror. Bellick is also money hungry and will do whatever it takes to hunt down T-Bag. Kellerman decides his fate while Lincoln and Mahone square off.', 45, '2007-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 2), 22, 'Sona', 'Michael tries to save his brother and himself from the unstoppable Mahone. Kellerman''s testimony at Sara''s trial proves different from what was expected, could this be the end for Sara? Sucre puts everything on the line to save his Maricruz. Just like old times, T-Bag and Bellick are at it again but this time there will be a winner.', 45, '2007-04-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')), 3, 'Season 3', 'Just when they thought they were out, they are pulled back in — for the most dangerous escape ever. Season three finds Michael Scofield wrongly incarcerated in Sona, a hellish Panamanian prison where there are no rules, no guards, and no escape.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 1, 'Orientación', 'Now locked up in a Panamanian prison known as Sona, Michael, T-Bag, Bellick, and Mahone try to find a way out. Much to their devastation, they soon find out that the prison has been abandoned by the authorities because of the immense threat from the vile inmates. Michael seeks for an inmate named Whistler in the prison sewers. As Lincoln is puzzled by Sara''s sudden disappearance, he learns that LJ has gotten into some trouble. He also tries to recover the 5 million dollars.', 41, '2007-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 2, 'Fire/Water', 'Michael and Mahone try to lure Whistler out of his hiding place. T-Bag gains some upward momentum in the prison hierarchy as the water supply is running low. Lincoln meets familiar and not so familiar faces on his quest to free Michael.', 45, '2007-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 3, 'Call Waiting', 'Whistler tells the truth to Michael. Michael tries to get in touch with Sara but the only phone is in Lechero''s quarters, so he has to rely on T-Bag''s help. Mahone battles his addiction. Bellick steps on some toes.', 45, '2007-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 4, 'Good Fences', 'After taking delivery of a package from The Company, Lincoln realizes that they are deadly serious. Michael''s new break out plan relies on electricity. Haywire is back from the dead, haunting disoriented Mahone. Bellick and T-Bag get special attention from Lechero.', 42, '2007-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 5, 'Interference', 'A new inmate named Tyge is brought to Sona. After he seemingly recognizes Whistler, Michael''s doubts arise. T-Bag enters a new area of commerce.Lincoln goes to the seaside with Sofia. Sucre takes over the side-business of his predecessor.', 45, '2007-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 6, 'Photo Finish', 'Michael threatens to cancel the escape plan unless he sees a proof that Sara is still alive. Whistler is accused of murdering an inmate and it is up to Michael to prove his innocence and save his life. Lincoln and Sofia help in monitoring the morning guards. Mahone may have another way to get out of Sona.', 45, '2007-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 7, 'Vamonos', 'Everything goes wrong for Michael as he tries to create a diversion.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 8, 'Bang and Burn', 'Susan jeopardizes Michael''s life as she puts her own escape plan into motion. Whistler''s past catches up to his girlfriend.The Company goes after Lincoln and Sucre. Justice prevails for Mahone. And Lechero sheds light into an empty tunnel.', 45, '2007-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 9, 'Boxed In', 'The Panamanian Army arranges Michael to get a taste of solitary. T-Bag reserves a spot in the escape. Bellick''s life turns into an uphill battle. Susan traps Sucre.', 45, '2008-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 10, 'Dirt Nap', 'Lechero''s demotion devastates Michael''s breakout plan as Sammy takes reigns at Sona. T-Bag forces Bellick to fight in a fight where the odds are stacked heavily against him. Lincoln and Sucre have some surprise fireworks set for Susan.', 45, '2008-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 11, 'Under and Out', 'Michael''s escape may be in jeopardy because of heavy rain. T-Bag and Lechero join forces, while Bellick hopes to do the same with Mahone.', 45, '2008-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 12, 'Hell or High Water', 'Michael, Whistler, and Mahone make their break from Sona. But Mahone seems like the odd man out along the way.', 45, '2008-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 3), 13, 'The Art of the Deal', 'Michael and Lincoln are left with no choice but to hand Whistler over in exchange to save LJ and Sofia. A familiar face enters Sona while another inmate leaves.', 45, '2008-02-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')), 4, 'Season 4', 'After engineering a daring escape from the hellish, Panamanian prison Sona, brothers Michael Scofield and Lincoln Burrows are determined to seek justice against The Company, the shadowy group responsible for destroying their lives and killing the woman Michael loves, Dr. Sara Tancredi. Michael’s quest for vengeance leads him to Los Angeles, where his world is turned upside down when Company operative Gretchen/Susan B. Anthony informs him that Sara is still alive. Realizing the only way they will truly be free, Michael and Lincoln avow to find Sara and take down The Company. With the help of Homeland Security agent Don Self, they assemble a group of allies and familiar faces to accomplish their task: Mahone, Sucre, Bellick and computer expert Roland Glenn. Unfortunately for the brothers, they must also evade company assassin Wyatt and find an on-the-loose T-Bag. Michael and Lincoln soon discover the only thing harder than breaking out will be breaking in.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 1, 'Scylla', 'Michael has trailed Gretchen/Susan, Whistler and Mahone to L.A. Chaos reigns in SONA while T-Bag, Bellick and Sucre go missing. Lincoln and L.J. continue to stay with Sofia.', 45, '2008-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 2, 'Breaking & Entering', 'The gang has to break into the well-guarded home of company man Stuart Tuxhorn. Elsewhere, T-Bag must go to extremes to survive.', 45, '2008-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 3, 'Shut Down', 'Michael attempts to track the cardholder and avoid going back to prison. Wyatt finds new information regarding Sara''s whereabouts. Elsewhere, T-Bag uses a new identity to make a new life for himself.', 45, '2008-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 4, 'Eagles and Angels', 'Michael, Lincoln and Sucre must crash a police benefit to obtain the next card key. Reeling from another death, Sara falls back into an old habit. T-Bag arouses suspicion and runs into some old “friends” his first day on the job.', 45, '2008-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 5, 'Safe and Sound', 'Self locates another card hidden in a safe within a secure federal building, as Mahone continues his quest for revenge. Meanwhile, T-Bag''s new life may be in jeopardy.', 45, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 6, 'Blow Out', 'The entire operation may be in jeopardy when Mahone gets into trouble with the law. Gretchen''s sister receives a surprise visitor. The Company may be onto Self. T-Bag continues to raise suspicions at Gate.', 45, '2008-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 7, 'Five the Hard Way', 'Lincoln takes members of the team to Las Vegas where Sucre gets an indecent proposal. Sara learns about Michael’s condition, and Roland pushes his luck too far. Gretchen teams up with T-Bag who makes an offer to Michael he cannot refuse. Meanwhile, the secrets in Whistler’s bird book are finally revealed.', 45, '2008-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 8, 'The Price', 'Lincoln works to retrieve the final card, which is being held by the General. Michael and Self are forced to work with Gretchen. Meanwhile, Roland continues to be berated for losing the transcribing device in Las Vegas.', 45, '2008-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 9, 'Greatness Achieved', 'Wyatt gets a taste of his own medicine, and Mahone finds some resolution. T-Bag scrambles when the police investigate his missing co-worker while Gretchen gets cozy with a Company man. Meanwhile, Michael’s condition continues to worsen, and a team member makes the ultimate sacrifice while planning the underground break-in for Scylla.', 45, '2008-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 10, 'The Legend', 'Sara is left with no choice but to take Michael to the hospital as his condtion rapidly worsens. Sucre and Lincoln are faced with unknown territory as they are left in charge of the operation. Elsewhere, agent Self makes a surprising ally.', 45, '2008-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 11, 'Quiet Riot', 'Michael races against time and his ailing health to break into the Company headquarters to steal Scylla, but the break-in’s success lies with Sucre. Gretchen dresses up for a meeting with the General and one final attempt to get the last card key. T-Bag must make a decision to leave his criminal ways for good.', 45, '2008-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 12, 'Selfless', 'Sara takes a hostage in a bid to secure Scylla. In the meantime, Michael and Lincoln finally meet the General while one of their members switches allegiance.', 45, '2008-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 13, 'Deal Or No Deal', 'It''s up to Michael to hold the gang together after they find out they were betrayed by one of their own. Meanwhile, Gretchen is blackmailed by T-Bag''s new partner.', 45, '2008-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 14, 'Just Business', 'Michael, whose condition is deteriorating, winds up in the hands of The Company who promise Lincoln that they can save Michael''s life in exchange for a favor. Elsewhere, Gretchen and Self wind up with Scylla and a buyer.', 45, '2008-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 15, 'Going Under', 'Michael gets medical attention from the most unlikely of places, and Charles Westmoreland returns to help uncover the true meaning of Scylla. Meanwhile, Lincoln and Sucre race to stop Gretchen before Scylla is lost forever.', 45, '2008-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 16, 'The Sunshine State', 'Lincoln and his new partners arrive in Miami to recover Scylla from its shocking new owner, and Sara searches for a missing Michael who learns some surprising information about his past. Meanwhile, a double-crossing leads to a death and an arrest in "The Sunshine State."', 45, '2008-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 17, 'The Mother Lode', 'Michael and Sara journey to Miami while Lincoln meets with his mother. T-Bag and Self''s mission to locate Scylla takes a dramatic turn. The General comes under pressure.', 45, '2009-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 18, 'VS.', 'Michael and Lincoln come to blows over Scylla as Christina sets the wheels in motion for her plan. Meanwhile, Sara receives life-changing news. T-Bag arrives at the Indian Embassy. The General becomes increasingly paranoid.', 45, '2009-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 19, 'S.O.B.', 'Michael''s reunion with Christina is soured when she drops a bombshell regarding Lincoln, and T-Bag grows determined to prove he is worthy of being a member of the Company.', 45, '2009-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 20, 'Cowboys and Indians', 'Pandemonium erupts at the hotel following the assassination, and Christina puts the final pieces of her plan together. Meanwhile, the General makes good on his threat, and Michael is forced to choose between saving either Lincoln or Sara.', 45, '2009-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 21, 'Rate of Exchange', 'Familiar faces return to help Michael end his quest to bring down The Company once and for all.', 45, '2009-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 4), 22, 'Killing Your Number', 'Michael tries to bring down the Company once and for all.', 45, '2009-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')), 5, 'Resurrection', 'Seven years later, thanks to an information provided by T-Bag, Lincoln and Sara discover that Michael is still alive in a Yemen prison, so they develop a plan to get him out.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 1, 'Ogygia', 'It''s been seven years since Michael was presumed dead, but when clues suggest that he might still be alive, Lincoln reunites with Sara to help track down the truth.', 45, '2017-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 2, 'Kaniel Outis', 'As Lincoln and C-Note search for the "Sheik of Light," Michael and his cellmate, Whip, attempt an escape from Ogygia. Meanwhile, Sara''s investigation into Michael''s reappearance leads her to the state department and an uneasy reunion with Paul Kellerman.', 45, '2017-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 3, 'The Liar', 'When T-Bag ambushes Sara, he warns her that two of Poseidon''s henchmen, Van Gogh and A&W, may be following her. Meanwhile, Lincoln attempts to retrieve his confiscated passport to escape Yemen, and Michael plans his next move.', 45, '2017-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 4, 'The Prisoner''s Dilemma', 'Michael, Whip and Ja make their last attempt to break from Ogygia, but must make a deal with the devil to do so. Lincoln races against the clock to help with the escape, as T-Bag meets with Kellerman to gather more info on Michael''s resurrection.', 45, '2017-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 5, 'Contingency', 'Lincoln becomes frustrated as he tries to understand what really happened to Michael. C-Note has a new escape plan, but fears it will not be executed quickly enough, as Cyclops is trailing closely behind. Meanwhile, Sara struggles with the idea that Michael may be alive.', 45, '2017-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 6, 'Phaecia', 'As Michael, Lincoln and the remaining Ogygia gang try to escape Yemen, they find themselves racing though the desert from a vengeful Cyclops. Meanwhile, A&W and Van Gogh question their roles as their pursuit of the escapees leads them to...Graceland.', 45, '2017-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 7, 'Wine Dark Sea', 'Sara becomes fearful of her family''s safety when she discovers the real reason that Michael faked his own death. In the meantime, Michael and Lincoln continue to try find a way home with the help of Sucre, and the real identity of Poseidon is revealed.', 45, '2017-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 8, 'Progeny', 'When Sara and her son''s safety is threatened, Michael and Lincoln recruit the help of Sheba and C-Note to try and catch Poseidon. Meanwhile, Whip goes on a separate mission and T-Bag reveals a secret.', 45, '2017-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0455275')) AND numero_temporada = 5), 9, 'Behind the Eyes', 'Dangerous threats keep Michael and Lincoln fighting to protect Sara and Mike. Meanwhile, Poseidon continues to try and outsmart Michael and the rest of the gang, which leads them to the ultimate showdown, and not everyone makes it out alive.', 45, '2017-05-30');
