INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 1, 'Extreme Aggressor', 'After a fourth woman goes missing in as many months, the team is brought in to track down the guy before he kidnaps again. Hotch is asked to secretly evaluate Gideon to see if he is ready to work full time again.', 40, '2005-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 2, 'Compulsion', 'The team of investigators tries to capture a serial arsonist who has been terrorizing a college campus.', 43, '2005-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 3, 'Won''t Get Fooled Again', 'Gideon and his team track down a copycat bomber terrorizing a quiet community.', 41, '2005-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 4, 'Plain Sight', 'The BAU team travels to San Diego to stop a rapist and murderer who commits his crimes in the middle of the day.', 40, '2005-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 5, 'Broken Mirror', 'The BAU investigates the kidnapping of a U.S. District Attorney''s daughter and determines the kidnapper isn''t seeking money -- he''s after her twin sister.', 42, '2005-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 6, 'L.D.S.K.', 'The BAU is asked to identify a killer who is shooting at victims in broad daylight, and the team works with local law enforcement officers to recreate one of the shootings.', 40, '2005-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 7, 'The Fox', 'The BAU profiles a serial killer who takes families hostage and lives with them as a father figure during what is supposed to be their family vacations.', 42, '2005-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 8, 'Natural Born Killer', 'When an undercover cop in Baltimore involved in a mob investigation goes missing, the BAU believes a serial killer rather than organized crime has something to do with his disappearance. The probe leads to several unsolved missing persons cases.', 42, '2005-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 9, 'Derailed', 'Elle, along with many others, is held hostage on a train in Texas by a paranoid schizophrenic who is convinced that the U.S. government is monitoring him. Hotchner and Gideon are forced to play into the man''s fantasy to save the people he has taken hostage.', 41, '2005-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 10, 'The Popular Kids', 'The team investigates the death of one teen, and the disappearance of another , which may be linked to a satanic ritual.', 41, '2005-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 11, 'Blood Hungry', 'While Gideon is stuck at the office on crutches, the rest of the team travels to Tennessee to track down a killer who disembowels his victims and supposedly eats their organs.', 43, '2005-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 12, 'What Fresh Hell?', 'When a young girl is abducted in broad daylight from a playground in a seemingly safe neighborhood, the BAU team initially believes her father is responsible. When he is able to provide an alibi, the team is forced to look for clues where the girl lives to determine who is really responsible.', 43, '2006-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 13, 'Poison', 'The team travels to New Jersey where several people have been poisoned, one of them fatally with LSD, ten times more potent than the street version.', 40, '2006-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 14, 'Riding the Lightning', 'After interviewing a couple on death row for serial murders, Gideon suspects that the woman is actually innocent. But since she''s set to be executed in two days, it''s a race against time to prove it.', 43, '2006-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 15, 'Unfinished Business', 'A serial killer reappears after 20 years of silence and contacts the BAU with the promise he will kill another victim in the next five days.', 41, '2006-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 16, 'The Tribe', 'The BAU team believes a dangerous cult may be responsible for the mass murders of five college students in an empty house.', 43, '2006-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 17, 'A Real Rain', 'The BAU unit travels to NYC to investigate a series of murders that appears to have been committed by a vigilante conducting revenge on former criminals who have been released by the justice system.', 42, '2006-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 18, 'Somebody''s Watching', 'Reid finds himself in danger when he falls for a starlet whose stalker has turned into a killer.', 42, '2006-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 19, 'Machismo', 'The BAU team travels to Mexico to aid in the capture of a serial killer who is targeting elderly women.', 41, '2006-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 20, 'Charm and Harm', 'The BAU works to capture a serial killer who has evaded capture by altering his appearance.', 41, '2006-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 21, 'Secrets and Lies', 'The BAU works with the CIA to identify a mole within that organization, whose leaks are putting operatives at risk.', 42, '2006-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 1), 22, 'The Fisher King (1)', 'While on their vacations, each of the team receives a clue from a psychopathic killer challenging them to save his next victim.', 41, '2006-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 1, 'The Fisher King (2)', 'The BAU team continues to unravel the clues given to each of them by a psychopath in order to save his most recent victim. Gideon decides not to focus on the personal aspects of the case. Rather, he tells the team to profile the killer as they would in any other investigation. Reid stays behind to work on a personal connection that could solve the case as one member of the team fights for life.', 41, '2006-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 2, 'P911', 'A young boy who had disappeared a year ago turns up for sale by a child pornographer on an online auction in Cleveland. A former profiler who now heads the FBI''s Crimes Against Children Unit asks Hotch and the BAU to help her save the boy''s life before it''s too late.', 41, '2006-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 3, 'The Perfect Storm', 'The BAU has reason to believe a series of murders might have been committed by two people working as a team after the victims'' families receive DVDs after each crime that includes psychological attacks.', 43, '2006-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 4, 'Psychodrama', 'The BAU is called to investigate a series of bank robberies after it becomes evident the crimes are not based on money because the robber abuses his victims by forcing them to undress before he leaves the crime scene.', 41, '2006-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 5, 'Aftermath', 'The BAU investigates a serial rapist who had been attacking young women at religious schools and stopped for six weeks. He has resumed his attacks, but is now targeting a different demographic of women. Elle makes a decision that could end her career with the BAU.', 43, '2006-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 6, 'The Boogeyman', 'The BAU travels to a small Texas community to investigate the murders of children. Meanwhile, Elle is having readjustment issues after being shot, and Hotch becomes worried about her when she misses a mandatory psych evaluation and isn''t answering her cell phone.', 43, '2006-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 7, 'North Mammon', 'After a man kidnaps three teenaged girls and locks them in a cellar, he tells them only two of them will live and they must choose which one will die. The BAU team takes the case when the mother of one of the girls travels to Quantico to ask JJ to intercede with the FBI on the girls'' behalf.', 43, '2006-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 8, 'Empty Planet', 'The BAU travels to Seattle to identify and catch a serial bomber who has been terrorizing the city and targeting centers of automated techology. Working with the author of a science fiction novel that has become a guide for the bomber, the team attempts to determine why certain sites have been chosen as targets.', 42, '2006-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 9, 'The Last Word', 'The daughter of high-powered diplomats, Special Agent Emily Prentiss joins the team, and she must convince Gideon and Hotchner she deserves the job based on merit and not on her family connections. The BAU is then called to St. Louis to investigate two serial killers who appear to be competing with each other. By setting a trap based on one killer''s profile, the team creates a media event by which to capture the second killer.', 43, '2006-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 10, 'Lessons Learned', 'Gideon, Reid and Prentiss travel to Guantanamo Bay to interrogate the leader of a terror sleeper cell being detained there after a chemical weapons dispersal device is discovered during a raid at a suspicious house. Working with Reid, Emily''s fluency in Arabic proves to be useful as they scrutinize the suspect.', 42, '2006-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 11, 'Sex, Birth, Death', 'The BAU is called to investigate a series of murders of prostitutes in Washington D.C. and Reid suspects a teenager he met asking for his help is guilty of the crimes. The case becomes complicated when a congresswoman, who about to make a speech to praise the city''s lower crime rate, threatens to take away the case if Hotchner calls a press conference to discuss it.', 43, '2006-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 12, 'Profiler, Profiled', 'Morgan is arrested as a serial killer after he goes home to Chicago to visit his family. Because the detective making the arrest had used a profile provided by Gideon, the team travels to Chicago to help the local authorities find the real killer and exonerate Morgan.', 42, '2006-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 13, 'No Way Out (1)', 'Gideon is pitted against the scariest and most evil murderer in his entire career. When the BAU confronts the sadistic killer in a remote diner in the Nevada desert, the local authorities want to move quickly and make an arrest. But Gideon bides his time as he attempts to persuade the man, who has sworn not be captured, to reveal the whereabouts of a woman he is holding hostage.', 43, '2007-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 14, 'The Big Game (1)', 'The BAU is called to investigate after a wealthy couple is murdered in their home following a Super Bowl party.', 41, '2007-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 15, 'Revelations (2)', 'In this conclusion of a special two-part episode, finding the serial killer becomes critical to the BAU when the team realizes Reid is being held captive and a live feed of him being tortured is shown on the internet. Meanwhile, Reid''s troubled childhood is revealed in flashback sequences as he drifts in and out of consciousness.', 43, '2007-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 16, 'Fear and Loathing', 'The BAU becomes involved to prevent a possible race riot when the murder of four young black women in a mostly white New York suburb appear to be hate crimes.', 43, '2007-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 17, 'Distress', 'The BAU travels to Houston to investigate a series of murders that have occurred near construction sites and abandoned buildings. Because the murders appear to be random, the team believes the killer could be a homeless person. Meanwhile, everyone is noticing an apparent change in Reid''s behavior.', 41, '2007-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 18, 'Jones', 'A case involving a serial killer believed to be copying Jack the Ripper takes Gideon to New Orleans after three victims are found with their throats cut. Once thought to have been killed in Hurricane Katrina, the discovery of a fourth victim in the French Quarter confirms the murderer is still alive. All the evidence and files had been lost in the flood, so the only clue the team has is the word "Jones" that the lead detective wrote on the wall just before he drowned. Meanwhile, Reid meets up with an old rival as he continues to struggle with the aftermath of being held hostage.', 41, '2007-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 19, 'Ashes and Dust', 'A serial arsonist who targets the homes of upper-middle-class families as they sleep is investigated. The BAU determines the arson victims are linked together through corporate development companies that have been accused of building on contaminated land.', 43, '2007-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 20, 'Honor Among Thieves', 'Elizabeth Prentiss, a foreign ambassador and SSA Emily Prentiss'' mother, seeks the aid of the BAU when a Russian immigrant is kidnapped and held for ransom.', 42, '2007-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 21, 'Open Season', 'The BAU is called to investigate after the bodies of missing people are discovered in a remote region of the Idaho wilderness. The gruesome find also leads the team to determine the unsubs have been hunting humans for sport.', 43, '2007-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 22, 'Legacy', 'When homeless persons begin going missing mysteriously from the streets in Kansas City, a local detective calls the BAU to investigate the disappearances.', 42, '2007-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 2), 23, 'No Way Out: The Evilution of Frank (2)', 'When the prolific serial killer Frank returns and murders Gideon''s girlfriend, Gideon takes off to find him without telling the team where he is going. The BAU must then profile Gideon as well as Frank to find both of them.', 42, '2007-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 1, 'Doubt', 'The team investigates a serial killer who is targeting women at a small college in Flagstaff, Arizona. The BAU shuts down the campus, creates a detailed profile of the unsub, and arrests a suspect. However, the team members begin to have doubts about themselves when another woman is killed while the suspect is in custody.', 43, '2007-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 2, 'In Name and Blood', 'In Milwaukee, a series of women have been found murdered with their hearts crudely removed. The BAU is assigned to the case, but they are short three members: Gideon, who is missing, Hotch, who is on suspension and Prentiss, who resigns her commission to join the Foreign Service. Supervisor Strauss steps in as lead, but she doesn''t handle herself well in the field.', 42, '2007-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 3, 'Scared to Death', 'The BAU travels to Portland to assist local authorities in investigating the disappearances of people who are new to the city and have no strong social ties.', 42, '2007-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 4, 'Children of the Dark', 'When home invasions involve the murder of entire families, the BAU is called to Denver to identify the killers who possibly have been abused while in foster care.', 42, '2007-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 5, 'Seven Seconds', 'The investigation turns to the family as the BAU and local authorities race against time to locate a young girl who has disappeared from a local shopping mall.', 41, '2007-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 6, 'About Face', 'The team gains a new, familiar member and some growing pains while trying to find the latest victim of a killer who puts up wanted posters of his victims before he abducts them.', 40, '2007-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 3), 7, 'Identity', 'The team is called to Montana to investigate the case of four kidnapped and murdered women. When another woman disappears, the search leads to a man who apparently has assumed the identity of his dead partner.', 41, '2007-11-07');
