INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 8, 'Hope', 'It’s personal for Garcia when the BAU investigate the disappearance of a woman in her survivors’ support group whose daughter went missing seven years earlier.', 42, '2011-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 9, 'Self-Fulfilling Prophecy', 'The BAU team looks into the real reasons behind an apparent mass suicide of a small group of youths at a military academy. Also, Hotch and Morgan butt heads when a team member could be in jeopardy.', 42, '2011-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 10, 'The Bittersweet Science', 'The investigation of a series of bludgeonings in Philadelphia leads the team to the city''s boxing scene; Hotch connects with a fellow runner while training for the triathlon.', 42, '2011-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 11, 'True Genius', 'A series of murders in San Francisco bearing the tell-tale signs of the infamous Zodiac Killer have the BAU wondering if the notorious serial killer has returned. Also, Reid ponders if he should be doing more with his genius abilities.', 42, '2012-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 12, 'Unknown Subject', 'The team is called to Texas to search for a serial rapist in Houston known as "The Piano Man" who has returned and is attacking his past victims. Meanwhile, Prentiss begins to deal with the traumatic experience caused by Ian Doyle after returning to the BAU.', 42, '2012-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 13, 'Snake Eyes', 'The BAU tries their luck in Atlantic City when the team is called in to investigate a series of ritualistic casino-related murders. Also, after a spat with her boyfriend, Kevin, Garcia thinks she and Morgan may have gotten a little too friendly with each other.', 42, '2012-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 14, 'Closing Time', 'The team hunts a killer when bodies are found hidden in lifeguard towers on Southern California beaches.', 42, '2012-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 15, 'A Thin Line', 'The BAU team investigates a series of brutal home invasions and murders in California''s Inland Empire that appear to be gang-related, but their investigation may uncover a more sinister motivation.', 42, '2012-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 16, 'A Family Affair', 'When the BAU travels to Atlanta to investigate the murders of women, the clues lead them to look for an unsub who is not working alone.', 42, '2012-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 17, 'I Love You, Tommy Brown', 'When married couples fostering young children end up being killed in Seattle, the BAU team looks for an unsub with a maternal-yet-murderous instinct. Also, Garcia fears a possible proposition from Kevin.', 42, '2012-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 18, 'Foundation', 'The team hunts for a kidnapper when an emaciated boy is found in the desert and another goes missing.', 42, '2012-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 19, 'Heathridge Manor', 'The BAU team heads to Oregon to investigate a series of gothic, ritualistic murders.', 42, '2012-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 20, 'The Company', 'When Morgan''s sister sees a woman who looks like their presumed-dead cousin, Cindi, it forces Morgan to confront a lie he told his family last year to provide closure and compels the BAU to reopen the case of her disappearance.', 42, '2012-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 21, 'Divining Rod', 'A serial killer is executed, in Oklahoma, a copycat shows up and the BAU are called to find him. Meanwhile, Prentiss gets nervous about a real estate purchase.', 42, '2012-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 22, 'Profiling 101', 'Rossi and the team teach college students the science of criminal profiling by taking the class through a serial-killer case that spanned 20 years.', 42, '2012-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 23, 'Hit (1)', 'When the BAU goes up against a gang of serial-killing bank robbers in Washington, D.C., the team tries to negotiate the situation unfolding inside the bank, but the stakes rise when one of their own becomes a hostage.', 42, '2012-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 7), 24, 'Run (2)', 'As the BAU team continues to pursue the bank-robbing serial killers, the team determines that the suspects have a bigger target in the Nation''s capital, and with one of the team still a hostage, they must work quickly to diffuse an explosive situation. Also, wedding bells ring for one of the BAU, and Prentiss ponders her future.', 42, '2012-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 8, 'Season 8', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 1, 'The Silencer', 'When a Texas prisoner escapes during a transfer, he leaves behind victims with his unique trademark, sewing their mouths shut, a signature the BAU remembers as unique to the UnSub "The Silencer." While they investigate who he was and who he''s become, the BAU also gets to know the newest member of the team.', 42, '2012-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 2, 'The Pact', 'When the bodies of two seemingly unrelated victims are found just hours apart in San Diego and Los Angeles respectively, the BAU suspects that that not one, but two killers are working together to commit these murders.', 42, '2012-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 3, 'Through the Looking Glass', 'An UNSUB who kidnaps families with the intention of making them admit to and pay for their indiscretions.', 42, '2012-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 4, 'God Complex', 'When a legless body is found in the New Mexico desert and a second unwilling amputee shows up at the hospital, the BAU team searches for this amateur surgeon before he preys upon his next reluctant victim. Also, Reid''s phone calls to a mystery woman have the team intrigued.', 42, '2012-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 5, 'The Good Earth', 'The team heads to Oregon as four men have gone missing.', 42, '2012-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 6, 'The Apprenticeship', 'When prostitutes in Miami are discovered murdered in a similar style to local animals found dead there, the BAU must work fast to find an unsub whose confidence is quickly escalating. Also, Morgan tries to increase Reid''s athletic skills by convincing him to join the bureau''s softball team.', 42, '2012-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 7, 'The Fallen', 'The BAU travels to Santa Monica when burned bodies of homeless people begin showing up by the famous pier. Also, Rossi reconnects with his former Marine sergeant from Vietnam.', 42, '2012-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 8, 'The Wheels on the Bus...', 'The BAU team goes in pursuit of a missing school bus full of children outside the Washington, D.C. area, and it becomes a race against time for them to bring them home safely.', 42, '2012-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 9, 'Magnificent Light', 'An attendee at a popular motivational-speaker''s conference in Seattle is murdered and the speaker himself disappears soon afterward. Meanwhile, Garcia is puzzled when Morgan refuses to attend a dinner honoring an old family friend.', 42, '2012-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 10, 'The Lesson', 'A ritualistic killer is hunted after male bodies are found that have been physically altered. Meanwhile, Reid gets anxious at the prospect of meeting his mystery woman.', 42, '2012-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 11, 'Perennials', 'The BAU heads south to investigate a fast-moving UnSub whose signature matches that of a serial killer from 30 years ago. Also, the team learns that someone is tracking their cases and replicating crimes the BAU is solving.', 42, '2012-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 12, 'Zugzwang', 'When Reid discovers that his girlfriend has been kidnapped by her stalker, he and the BAU team band together to find her before it''s too late.', 42, '2013-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 13, 'Magnum Opus', 'While Reid copes with a loss in his personal life, the rest of the BAU travels to San Francisco to investigate victims discovered in the Mission District.', 42, '2013-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 14, 'All That Remains', 'A writer''s daughters vanish on the anniversary of their mother''s disappearance, which leads the BAU to investigate the man as a possible suspect.', 42, '2013-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 15, 'Broken', 'The BAU heads to Austin to investigate victims found there with their watches set inaccurately, a clue which may connect the crimes. Meanwhile, the UnSub stalking the BAU inches closer in his pursuit of the team.', 42, '2013-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 16, 'Carbon Copy', 'When victims are found in Philadelphia in a similar style to victims of The Replicator, the stalker who has been tracking the BAU''s every move, the team thinks this could be the break they need to try and apprehend him.', 42, '2013-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 17, 'The Gathering', 'The BAU investigates victims who were documenting their personal lives and inner desires on blog posts and social media. Also, Kevin gets jealous when he learns Garcia may have a new love interest.', 42, '2013-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 18, 'Restoration', 'The BAU goes to Morgan''s old neighborhood in urban Chicago in search of an unsub targeting middle-aged men, and a clue leads Morgan to believe that they are after someone connected to the man who molested him as a child.', 42, '2013-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 19, 'Pay It Forward', 'When a time capsule in a small Colorado town is opened twenty-five years later and contains a gruesome discovery, the BAU investigates the crime and find a possible link to the death of a local police officer.', 42, '2013-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 20, 'Alchemy', 'The BAU travel to Rapid City after two male victims are discovered murdered in a ritualistic manner. Also, Reid continues to grieve over Maeve’s death.', 42, '2013-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 21, 'Nanny Dearest', 'The BAU travels to Los Angeles looking for an UnSub who is kidnapping nannies and the children they care for on the same day each year.', 42, '2013-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 22, 'Number Six', 'The BAU goes to Detroit to track an UnSub with a rapidly changing MO. Also, Blake''s husband returns from overseas with a life-changing career proposition for her.', 42, '2013-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 23, 'Brothers Hotchner (1)', 'The Replicator zeroes in on the BAU when the killer targets one of the team as the next victim. Also, the BAU is called in to investigate a string of deaths in Manhattan tied to apparent ecstasy overdoses, and Hotch discovers that his estranged brother, Sean, is caught in the middle.', 42, '2013-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 8), 24, 'The Replicator (2)', 'The Replicator zeroes in on the BAU when the killer targets one of the team as the next victim. Also, the BAU is called in to investigate a string of deaths in Manhattan tied to apparent ecstasy overdoses, and Hotch discovers that his estranged brother, Sean, is caught in the middle.', 42, '2013-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 9, 'Season 9', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 1, 'The Inspiration (1)', 'The hunt for a methodical killer takes the BAU to Arizona to search for an increasingly devolving unsub, and the team speculates that Hotch is in the running to be the new BAU Section Chief following the death of Erin Strauss.', 42, '2013-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 2, 'The Inspired (2)', 'As the BAU zeroes in on the suspect of the ritualistic killings they''ve been investigating in Arizona, a bizarre connection within the unsub''s family could lead them to finally nab the suspect.', 42, '2013-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 3, 'Final Shot', 'When a sniper strikes Dallas, the BAU investigates whether the upcoming anniversary of the Kennedy assassination is a motivating factor or if something else is driving the unsub.', 42, '2013-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 4, 'To Bear Witness', 'The BAU meets their new section chief, Mateo Cruz, who, unbeknownst to them, shares a long work history with JJ. Cruz joins the team as they comb the streets of Baltimore for an unsub who leaves victims unable to communicate.', 42, '2013-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 5, 'Route 66', 'As Hotch fights for his life due to complications from his stabbing at the hands of George Foyet, a.k.a. "The Reaper," he experiences visions of his late wife, Haley, and his nemesis, Foyet. Meanwhile, the BAU searches for a missing teenager and investigate her estranged father as a suspect in her disappearance.', 42, '2013-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 6, 'In the Blood', 'The BAU are called to Utah to investigate the murder of a women who died by being buried under stones. All while Penelope plans a Day of the Dead party.', 42, '2013-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 7, 'Gatekeeper', 'Though Rossi is sad because his favorite bar is closing, the team goes to Boston to solve a series of strangulations.', 42, '2013-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 8, 'The Return', 'When teenagers who were reported missing are suspected of a series of mass murders in Chicago, the BAU investigates their whereabouts to find a motive for the crimes. Also, Morgan has conflicting feelings when his girlfriend takes her job at a hospital as seriously as he takes his.', 42, '2013-11-13');
