INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 12, 'The Black Queen', 'A murder investigation leads to Garcia delving into her hacker past -- and reconnecting with her former love.', 42, '2014-01-15');
