INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 18, 'Rabid', 'When three bodies are found with animal and human bite marks in a shallow grave near Milwaukee, the BAU has puzzling questions to answer. Meanwhile, Reid and Garcia work out for a company fitness test, but try to hide their preparation from Morgan.', 42, '2014-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 19, 'The Edge of Winter', 'Morgan''s visit with a survivor of unusual stabbings in upstate New York leads to more questions about the case.', 42, '2014-03-19');
