INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 9), 21, 'What Happens in Mecklinburg...', 'The team searches for a commonality when a series of target abductions take place; Savannah is frustrated with Morgan''s traveling.', 42, '2014-04-09');
