INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 2, 'Burn', 'A series of abductions and murders in Seattle send the BAU seeking an UnSub who was abused in the past and is out for revenge. Garcia heads to Texas to confront the man she shot while defending Reid and herself, as he waits on death row.', 42, '2014-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 3, 'A Thousand Suns', 'When a passenger jet crashes in Colorado, the BAU team is called to build a profile around the suspicious circumstances. The case hits close to home for Kate, who is reminded of a family tragedy.', 42, '2014-10-15');
