INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 6, 'If the Shoe Fits', 'The BAU is stumped to find the common denominator among male victims in Montana, making in difficult to profile the UnSub. JJ confronts her feelings about her sister''s tragic death.', 42, '2014-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 7, 'Hashtag', 'When victims with large social media followings are found dead in Maryland, the BAU searches for an UnSub taking on the persona of an Internet urban legend. Morgan and Savannah struggle to find quality time for each other with their busy careers.', 42, '2014-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 8, 'The Boys of Sudworth Place', 'When a prominent attorney goes missing in Boston, the BAU unearths secrets in his past which could point to the reasons for his disappearance.', 42, '2014-11-19');
