INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 10, 'Amelia Porter', 'When the BAU is called to Salt Lake City Utah to investigate a triple homicide, the search for a connection among the victims could lead them to a fugitive who could have ties to the UnSub.', 42, '2014-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 11, 'The Forever People', 'When frozen bodies are found in Nevada floating in water, the BAU’s investigation leads them to suspect that the victims were part of a cult that could be behind the deaths. Also, JJ confronts old demons from her abduction and torture last year.', 42, '2015-01-14');
