INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 16, 'Lockdown', 'When two guards at a privatized maximum security prison in Texas are murdered, the BAU suspects that more than one UnSub within the prison could be at work.', 42, '2015-03-04');
