INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 18, 'Rock Creek Park', 'When the wife of an up-and-coming congressman disappears, the BAU investigates his political enemies as possible suspects.', 42, '2015-03-25');
