INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 10), 20, 'A Place at the Table', 'When a Maryland family is found murdered at their dining room table, the team tracks down other family members and friends to uncover secrets that may have led to it. Also, Hotch must try to make peace with his father-in-law, Roy, after discovering he’s been diagnosed with Alzheimer’s.', 42, '2015-04-15');
