INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 11), 6, 'Pariahville', 'When a woman is murdered in a small town in Florida inhabited entirely by sex offenders, the BAU faces a community full of suspects. Also, Lewis receives a career opportunity that may take her away from the BAU.', 42, '2015-11-04');
