INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 9, 'False Flag', 'When two members of a conspiracy group in Roswell, N.M., perish in quick succession, the BAU is called to investigate.', 42, '2017-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 10, 'Submerged', 'When a series of backyard pool homicides are reported in California, the BAU team searches for an UnSub with a puzzling past.', 42, '2018-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 11, 'Full-Tilt Boogie', 'The BAU team’s investigation into the home invasion and attempted homicide of a police chief’s wife uncovers a world of secrets in a small town in Virginia.', 42, '2018-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 12, 'Bad Moon on the Rise', 'The BAU is called to New York when several casualties of a brutal nature are reported in Central Park.', 42, '2018-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 13, 'Cure', 'The BAU is called to investigate a series of D.C. homicides where cryptic messages are found inside the mouths of each victim.', 42, '2018-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 14, 'Miasma', 'The BAU is called when the New Orleans P.D. discovers a mass grave inside a vandalized above-ground crypt in a local cemetery.', 42, '2018-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 15, 'Annihilator', 'The FBI''s assistant director of national security, Linda Barnes, joins the BAU as they investigate a quadruple homicide of a group of roommates in St. Louis.', 42, '2018-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 16, 'Last Gasp', 'Away from the watchful eye of the FBI''s assistant director of national security, Linda Barnes, the BAU meets in secret to investigate an UnSub who appears to be kidnapping and photographing young women.', 42, '2018-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 17, 'The Capilanos', 'The BAU is called to Oklahoma to investigate a murderous clown terrorizing the sleepy town of Guymon.', 42, '2018-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 18, 'The Dance of Love', 'The BAU travels to Chicago to investigate an unsub who leaves red roses on each victim. Also, Rossi gets an unexpected visit from his ex-wife, Krystall Richards.', 42, '2018-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 19, 'Ex Parte', 'The BAU takes charge of a hostage situation at a law firm in D.C., where Matt Simmons’ wife, Kristy works.', 42, '2018-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 20, 'All You Can Eat', 'The BAU is called to investigate a series of deaths in Virginia suspected by the Center for Disease Control to be caused by bio-terrorism; Garcia visits her stepbrother to take care of a family issue.', 42, '2018-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 21, 'Mixed Signals', 'The BAU is called to Taos, N.M. to investigate an UnSub who is targeting his victims'' temporal lobes.', 42, '2018-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 13), 22, 'Believer', 'When Reid discovers former FBI Special Agent Owen Quinn locked inside a storage unit, the BAU questions the credibility of Quinn''s bizarre accounts of searching for an UnSub that he named "The Strangler".', 42, '2018-04-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 14, 'Season 14', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 1, '300', 'When Reid and Garcia are abducted by Benjamin Merva, it''s up to the rest of the team to find them. The BAU finds surprising clues in their own history to solve why the two heroes have been targeted by a mass murderer. It''s a race to save them before a Believer''s prophecy is fulfilled.', 42, '2018-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 2, 'Starter Home', 'When the mummified remains of numerous victims are found in the walls of an elderly couple''s remote South Carolina home, Rossi, JJ and Simmons are dispatched to track down a trail of clues that date back over 20 years. The hunt becomes urgent after BAU learns the killer has a specific ritual of when to strike, and like clockwork another person goes missing. Rossi reconnects with his ex-wife.', 42, '2018-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 3, 'Rule 34', 'The BAU must determine what connects six people that each received a mysterious package in order to identify the Unsub. Simmons and his wife deal with their son''s suspension from school.', 42, '2018-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 4, 'Innocence', 'The BAU steps in to help local law enforcement isolate a prime suspect for a ritualistic murder in Tallahassee, Fla., and soon after a second person who is related to the first victim is killed under similar circumstances. Prentiss is concerned about Garcia’s behavior in the aftermath of her abduction and has an idea of how to help with the healing process.', 42, '2018-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 5, 'The Tall Man', 'The BAU investigates a spooky local ghost story of the ''Tall Man'' and the clues it provides when two people go missing in the woods of East Allegheny’s Dead Man’s Conservatory, and a third mysteriously surfaces the following day with limited details as to what happened to her friends. To assist with the case, JJ reluctantly returns to her hometown, triggering emotional flashbacks to age 11 and her older sister’s tragic death.', 42, '2018-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 6, 'Luke', 'The BAU heads to Bethesda, Md., to investigate four murders in the span of three days along the eastern seaboard. The crimes become personal for Alvez, when the team discovers there are ties to his time spent five years ago working alongside the DEA and the Mexican police force in pursuit of the most notorious hitman in Mexico. Alvez and his girlfriend decide to move in together.', 42, '2018-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 7, 'Twenty Seven', 'The BAU races to capture the vigilantes behind a series of attacks taking place every 27 minutes in the nation’s capital. Prentiss and Unit Chief Andrew Mendoza lead the effort to identify the Unsubs and what’s motivating them.', 42, '2018-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 8, 'Ashley', 'The BAU investigates a double homicide and kidnapping in New Hampshire. Rossi''s plans to elevate his relationship with Krystall don''t go as planned.', 42, '2018-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 9, 'Broken Wing', 'A professor from Lewis’ past tips off the BAU to an alarming number of overdose deaths of patients who just completed rehab.', 42, '2018-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 10, 'Flesh and Blood', 'Prentiss faces her past when the BAU is sent to investigate the murders of prominent businessmen, all of whom are missing their hearts. Also, Prentiss plans a romantic first date with Mendoza, but the evening is cut short by an urgent call from Rossi.', 42, '2018-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 11, 'Night Lights', 'The BAU team heads to Portland, Ore., to investigate a chilling abduction that may be linked to a local couple killed in their home a week earlier.', 42, '2019-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 12, 'Hamelin', 'Prentiss and the team fly to Iowa to investigate the disappearance of three 10-year-old children who appear to have been abducted from their homes in the middle of the night, with surveillance video from a neighborhood park as their only lead to finding the children’s whereabouts.', 42, '2019-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 13, 'Chameleon', 'Rossi questions his actions in the aftermath of a near-death struggle with a serial killer who appears to have outsmarted the BAU.', 42, '2019-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 14, 'Sick and Evil', 'The BAU investigates a string of murders taking place in supposedly haunted houses in Lewiston, Maine.', 42, '2019-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 14), 15, 'Truth or Dare', 'Wedding bells are ringing as Rossi prepares to marry Krystall. But first, the BAU team travels to Los Angeles to investigate a series of fatal shootings in broad daylight following car accidents.', 42, '2019-02-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 15, 'Season 15', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 1, 'Under the Skin', 'The BAU team investigates an UnSub with striking similarities to Rossi’s latest obsession, “The Chameleon,” a.k.a. Everett Lynch, who nearly killed him and then disappeared.', 42, '2020-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 2, 'Awakenings', 'With a member of the BAU in the hospital, the team searches for Everett Lynch, and his daughter, Grace. Also, Spencer has a meaningful visit with his mother, Diana Reid, while she’s experiencing a period of lucidity.', 42, '2020-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 3, 'Spectator Slowing', 'The BAU team investigates a series of seemingly random fatal explosions throughout Kentucky and Tennessee.', 42, '2020-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 4, 'Saturday', 'The members of the BAU enjoy a Saturday off in vastly different ways. While Rossi and Prentiss help Simmons assemble a new crib, Garcia leads a hacking competition, and Dr. Reid strikes up a conversation with a woman named Maxine.', 42, '2020-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 5, 'Ghost', 'Following a series of fatal shootings, the BAU team travels to Des Plaines, Ill. to investigate what appears to be a copycat serial killer. Their efforts are thrown off track when members of the BAU are targeted.', 42, '2020-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 6, 'Date Night', 'After a father and daughter get kidnapped, a former foe of the BAU returns with very specific demands for Dr. Reid that give a whole new meaning to the phrase “wheels up".', 42, '2020-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 7, 'Rusty', 'When the BAU team travels to Denver to investigate several murders, Prentiss is forced to evaluate her relationship with Special Agent Andrew Mendoza.', 42, '2020-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 8, 'Family Tree', 'Prentiss and J.J. are faced with important decisions to make about their futures as the BAU travels to Beaumont, Texas to investigate a series of murdered businessmen.', 42, '2020-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 9, 'Face Off (1)', 'It has been a year since Rossi nearly died at the hands of Everett Lynch, a.k.a. “The Chameleon,” and he has developed some new theories, with inspiration from his former partner, Jason Gideon. The BAU team sets out on an epic hunt to capture Lynch.', 42, '2020-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 15), 10, 'And in the End (2)', 'Following an explosive face-to-face encounter with Everett Lynch, a.k.a. “The Chameleon,” Dr. Reid suffers from a brain injury and, while experiencing hallucinations, is visited by ghosts from his past. Also, the BAU makes a shocking discovery about Lynch that affects Rossi personally, and the entire BAU team comes together to celebrate Rossi’s retirement.', 42, '2020-02-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 16, 'Season 16: Evolution Season 1', 'The FBI''s elite team of criminal profilers come up against their greatest threat yet, an UnSub who has used the pandemic to build a network of other serial killers. As the world opens back up and the network goes operational, the team must hunt them down, one murder at a time.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 1, 'Just Getting Started', 'When a family annihilator abducts a teen girl, the Behavioral Analysis Unit works the case on either side of the country to save her. But an unlikely connection to a mysterious kit leads to a bigger investigation and at the center of it is Penelope Garcia.', 51, '2022-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 2, 'Sicarius', 'As the team hunts an UnSub who severs spinal cords, they uncover a clue from their last case that points to a serial killing network. To figure out how big this network is, Rossi has to convince a reluctant Garcia to do the one thing she doesn’t want: come back to the BAU.', 54, '2022-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 3, 'Moose', 'At the heart of the serial killing network is Elias Voit. Dangerous psychopath. Manipulative narcissist. Loving father and husband. In order to find him, the team must find all of his kill kits. But one is missing, and the path leads to a bomb in the middle of Washington, D.C.', 44, '2022-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 4, 'Pay-Per-View', 'The BAU hunts for the next connection to the serial killer network when they pursue a home invasion team. Alvez and Garcia convince Tyler Green to submit a cognitive interview to unlock his memories of Sicarius.', 48, '2022-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 5, 'Oedipus Wrecks', 'A surprising connection forces Deputy Director Bailey to ask the BAU to take a case involving young D.C. socialites who are bitten by a sadistic UnSub. But when the case turns political, the BAU finds themselves in the crosshairs from a high-powered senator. The team is led to a second shipping container that’s rigged to blow.', 53, '2022-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 6, 'True Conviction', 'The explosion looks to have exposed the true mastermind behind Sicarius, but all is not what it seems. Is someone taking the fall for these deadly actions? The BAU is determined to seek the truth.', 56, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 7, 'What Doesn’t Kill Us', 'With the fate of the Sicarius investigation hanging in the balance, the BAU takes a case in West Virginia, where an UnSub practices his own twisted form of Old Testament vengeance.', 55, '2023-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 8, 'Forget Me Knots', 'Voit’s internal struggles with himself lead him to a desperate kidnapping. But Rossi’s obsession brings the BAU closer to the truth than they’ve ever been.', 47, '2023-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 9, 'Memento Mori', 'Rossi will go to any lengths to prove that Elias Voit is Sicarius. But Voit turns Rossi into his own worst enemy, putting his future at the BAU in jeopardy.', 57, '2023-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 16), 10, 'Dead End', 'With Rossi in Voit’s clutches, he grapples with the limits of his technical know-how and mental strength. As the BAU tightens their grip on Voit, he reveals just how far he’s willing to take his deadly crusade.', 56, '2023-02-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 17, 'Season 17: Evolution Season 2', 'Evolution season 2 picks up as the FBI''s elite team of profilers investigates the deadly mystery of Gold Star. As the conspiracy unfolds, the Behavioral Analysis Unit is met with an unexpected complication when serial killer Elias Voit negotiates a deal that transfers him to federal custody in the BAU''s own backyard. The team faces its biggest threat yet and cannot emerge unscathed from the mind-bending consequences.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 1, 'Gold Star', 'Prentiss uncovers a series of brutal killings linked by a specific calling card. Despite being haunted by Elias Voit, the BAU is forced to team up with him to track the Gold Star killer. Rossi and Prentiss devise a plan to gain leverage over Voit.', 53, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 2, 'Contagion', 'The BAU investigates a series of killings with the same brutal M.O. they saw with the strike team deaths. The team tries to link the victims to determine if they are dealing with the same killer. Rebecca joins Lewis and Tyler Green on a stakeout.', 50, '2024-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 3, 'Homesick', 'The BAU investigates the "Moving Day Murders" and track a ritualistic killer with a twisted method of subduing his victims. Tyler goes rogue to track down the latest Gold Star lead. Prentiss is targeted by conspiracy theorists.', 49, '2024-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 4, 'Kingdom of the Blind', 'The BAU is faced with more Gold Star killing with the same gruesome M.O. Elias Voit says goodbye to his family. Prentiss wrestles with the fallout of her run-in with Brian Garrity. Garcia hacks the cloned phone brought in by Tyler Green.', 49, '2024-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 5, 'Conspiracy vs. Theory', 'The BAU enlists Voit to help capture Jade and Damien, the UnSubs behind the Gold Star killings. Damien and Jade get the upper hand and the BAU must watch as Voit tries to negotiate with them in order to avoid a mass casualty event.', 48, '2024-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 6, 'Message in a Bottle', 'Alvez and Garcia profile who might be targeting Tyler''s ex-girlfriend. JJ helps Prentiss work through an existential hangover. When Rossi''s Voit delusions reach a breaking point, Rossi confronts Voit and unpack what has been truly haunting him.', 59, '2024-07-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 7, 'Piranha', 'The BAU zeroes in on a sadistic UnSub in D.C. with a twisted M.O. Prentiss and Rossi dive into the BAU''s history to find connections to Gold Star. Prentiss reaches out to someone from Rossi''s past. Voit utilizes his lawyer to reach out to Damien.', 56, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 8, 'North Star', 'The BAU tries to get ahead of Jade and Damien who are on a killing spree. Rossi must confront an old flame to unpack the secrets behind the Gold Star program. Tyler and Rebecca attempt to gain leverage over Elias Voit''s lawyer.', 58, '2024-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 9, 'Stars & Stripes', 'With Jade on the run, the BAU continues to assemble the pieces connecting Gold Star victims to Aida Limited. Jade and Dana follow Voit’s breadcrumbs to the heart of the “conspiracy.” A search warrant execution by the BAU has deadly consequences.', 52, '2024-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 17), 10, 'Save the Children', 'When the identity of the last Gold Star member is revealed, the pieces of the puzzle click together. Prentiss, now in mortal danger, must confront Jade and her accomplice to expose the truth behind the “conspiracy” before time runs out for the BAU.', 55, '2024-08-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')), 18, 'Season 18: Evolution Season 3', 'The new season picks up six months after fellow inmates attacked the notorious Sicarius Killer, Elias Voit, leading his restless followers on the dark web to begin wreaking havoc all over the country. In order to stop this nefarious group from killing more innocents, the BAU is forced to work alongside an increasingly unpredictable Voit, who of course has his own agenda.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 1, 'Swimmer''s Calculus', 'When bodies wash up on the Maryland shoreline, the BAU races to find the UnSub. After surviving a prison attack, Elias Voit has been placed in a medically induced coma while Rossi is investigated for the incident.', 48, '2025-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 2, 'The Zookeeper', 'Voit awakens from his coma. The team finds videos from a dormant Sicarius Network killer called "The Zookeeper" indicating that the network has reactivated. With Voit still in recovery, the BAU must tackle this reawakened network on their own.', 58, '2025-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 3, 'Time to Say Goodbye', 'Rossi and Lewis enlist the help of Ramona, Voit''s sole survivor, to help unlock Voit''s memory. JJ and the team say goodbye to Will.', 58, '2025-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 4, 'I''m Fine, It''s Fine. Everything Is Fine', 'While the team works an organ harvesting case, Voit''s recovery process leads him to suspect he is more likely a prisoner than victim. JJ finds a cryptic video posted to the BAU-Gate website of a masked UnSub that could be connected to Voit''s network.', 55, '2025-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 5, 'The Brutal Man', 'JJ works with Dr. Ochoa to help Voit process the truth about his violent past, and tells him that one of his followers has a message from a mysterious unsub who appears to be organizing the remaining members of Voit''s serial killer network.', 53, '2025-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 6, 'Hell Is Empty…', 'The team investigates a network killer who buries his victims alive, and Tara confronts Rebecca''s ex who has recently re-entered her life. Ronald Graber delivers a message from his Disciple to Voit.', 53, '2025-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 7, '…All the Devils are Here', 'Network UnSubs torture and kill hostages as Voit works with the BAU to stop them. Rebecca''s ex, Evan Delray, is appointed Voit''s new liaison.', 50, '2025-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 8, 'Tara', 'When the team works to hunt down the person who shot Tara, they discover "The Disciple" deliberately had them chasing their tails. While undergoing critical surgery, Tara gets to the root of her relationship issues.', 54, '2025-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 9, 'CollateRal', 'The team inches closer to uncovering the identity of "The Disciple", someone they believe is linked to Voit''s past, but Voit''s unpredictable behavior puts their progress in jeopardy.', 49, '2025-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0452046')) AND numero_temporada = 18), 10, 'The Disciple', 'After Voit and Ochoa are kidnapped by "The Disciple", the team races to find them. While in The Disciple''s custody, Voit wrestles with keeping the monster inside him at bay.', 55, '2025-07-10');
