INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')), 1, 'Season 1', 'Earl is learning the hard way that when you do something bad, it has a way of coming back and biting you in the butt! Hoping to turn his life around, Earl''s got a lengthy list of detestable deeds to make up for, from stealing a one-legged girl''s car, to avoiding a nasty break-up by faking his own death.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 1, 'Pilot', 'Today is the first day of the rest of Earl Hickey''s life. After coming into a $100,000 scratch-off lottery ticket and losing it just as fast upon being hit by a car, Earl has an epiphany in the hospital--to make up for all the terrible things he''s done in the past. With his brother Randy and a motel maid named Catalina, Earl writes up a list of every misdeed he was a part of. Earl sets out to do just that, starting with #64--Kenny James, a boy he picked on in elementary school.', 22, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 2, 'Quit Smoking', 'Earl must make amends to Donny, an intimidating thug who spent two years in jail for a robbery Earl committed. Oddly enough, the only way he can do this is by helping Donny''s mom quit smoking. Meanwhile, Joy discovers she''s the beneficiary of Earl''s will and decides to kill him!', 22, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 3, 'Randy''s Touchdown', 'Back in their high school days, Earl ruined Randy''s chance to score a touchdown during a key football game; now Earl must figure out a way to make things right.', 22, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 4, 'Faked My Own Death', 'When Earl meets a tough biker chick at a Halloween party, it looks like a match made in heaven--but when the costumes come off, the mismatch becomes apparent and Earl takes drastic measures to get out of the relationship.  Now, years later, Earl must find a way to make amends for deceiving the girl.', 22, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 5, 'Teacher Earl', 'Earl decides to teach English as a Second language to cross "Made fun of people with accents" off his karma list. While Ralph an old friend is released from prison, Earl tries to convince him in the ways of karma however Ralph ends up kidnapping Randy trying to get his hands on Earl’s lotto winnings.', 22, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 6, 'Broke Joy''s Fancy Figurine', 'In order to replace a fancy figurine that he broke, Earl lends a hand to help Joy''s former adversary and her daughter win a mother/daughter beauty pageant . However, Joy enters the pageant also with her "dead" mother trying to win that same figurine, hoping to trade it for a hot tub.', 22, '2005-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 7, 'Stole Beer From a Golfer', 'Earl attempts to help Scott get over his preoccupation with golf--an obsession caused when he and Randy started fixing Scott’s golf game to get free beer. But after becoming so thoroughly entangled in Scott’s personal life that he drives Randy away, Earl realizes that he may be the one with the obsession.', 22, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 8, 'Joy''s Wedding', 'Darnell and Joy decided to tie the knot while Earl learns thru Randy’s invitation that he is not invited.  To make things worse Joy has scheduled the wedding on Earl’s birthday so that all of their friends will be unable to celebrate with him. A drunken Earl crashes the party accidentally breaking Joy’s nose and now is forced to add “ruined Joy’s wedding” to his list.', 22, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 9, 'Cost Dad the Election', 'Earl tries to cross of number four off his list “Blew dad’s chance to be elected mayor”. Four years earlier, Carl Hickey ran for mayor to redirect a proposed airplane traffic route over his house and away from the wealthy part of town. Earl unfortunately ruins any chances of his father winning when caught in on tape assaulting a police officer.  Earl must now help his father get elected and mend his relationship with his father.', 22, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 10, 'White Lie Christmas', 'As the holiday season comes under way a few secrets are exposed when Earl attempts to cross number seventy-four off of his list: "always ruined Joy''s Christmas." Earl, Randy, and Catalina enter a radio contest to win a brand new car for Joy to make up for all of the thoughtless Christmas presents Earl gave her while they were married. While Randy and Catalina vie over the car, Earl finds out that Joy''s parents believe that he''s still their son-in-law and that he''s just returned from the war in Iraq. Joy is afraid to tell her father, an alleged racist, that she is now married to Darnell, so Earl plays the part, afraid of ruining another one of her Christmases.', 22, '2005-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 11, 'Barn Burner', 'When trying to enroll her children into the Right Choice Ranch for troubled youth, Joy is denied enrollment because of a barn burning incident at the hands of a younger Earl. Earl, Randy and Catalina travel to the camp to make amends for the barn burning by building a pen for the camp’s ostrich.  Earl learns the real reason behind the barn burning incident and decides that every incident on his list after the fire should be shared by Randy.', 22, '2006-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 12, 'O Karma, Where Art Thou?', 'When Earl and Randy try to return a stolen wallet they find out taking the money had cost two newlyweds their honeymoon. In an attempt to make things right Earl takes over for the groom at his fast food restaurant. After time Earl finds out the boss is a jerk and Earl wonders how such a man with a luxurious house and beautiful wife could not be affected by the only thing he believes in, Karma.', 22, '2006-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 13, 'Stole P''s HD Cart', 'Earl crosses another number off the list when he returns Pops’ Weiner Hot Dog cart he and Ralph stole in his youth. The good deed does not last long as Ralph, who works for a competing franchise sets fire to Pops cart. Earl now must set things right with a bizarre plan while recruiting Randy, Joy, Catalina and Darnell to assist him.', 22, '2006-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 14, 'Monkeys in Space', 'Earl tackles number eighteen on his list when one of his old friends is arrested. Remebering that he told an inappropriate story at his birthday party he must give him one great day to make up the the terrible one before he was sent to prison.', 22, '2006-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 15, 'Something to Live For', 'Earl takes his car troubles as a sign that it is time for him to redeem himself for a long run of stealing gas out of a complete stranger''s car.', 22, '2006-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 16, 'The Professor', 'Earl''s nervous about returning a laptop computer he stole from a college professor, mostly because he''s uncomfortable around smart people. When the professor turns out to be a beautiful woman, he feels even more ill at ease, until she flatters him and asks him to speak about his list in front of her class. Meanwhile, Randy experiences fraternity life---and absolutely loves it.', 22, '2006-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 17, 'Didn''t Pay Taxes', 'Earl attempts to cross off another deed of his list. This time trying to repay the government after failing to pay his taxes in the past.', 22, '2006-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 18, 'Dad''s Car', 'It''s Mother''s Day again when Earl  remembers that he has never given his mother a Mother''s Day gift Just as he and Randy are about to finish carrying out his long overdue gift his mother decides her repayment should include Earl doing something for his father.', 22, '2006-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 19, 'Y2K', 'When Earl is attempting to cross number 24 ("Stole a red ''Take-a-number'' machine” ) off his list, Randy tries to get Earl to back down by trying to make him remember, through a flashback, how they got the machine around New Year’s Eve 1999. Darnell convinces the gang to believe that Y2K will signal the end of the world and they, happily, will be the last people on Earth.', 22, '2006-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 20, 'Boogeyman', 'Earl decides to cross off "made a kid scared of the boogeyman" from his list. Earl soon discovers just what kind of lasting affect he had on the little boy.', 22, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 21, 'The Bounty Hunter', 'Number forty-five "Ditched Jessie to Marry Joy" is next on the list when Jessie, Earl''s ex-girlfriend returns to town seeking revenge. Earl must protect Joy in a lakeside retreat while Randy fights not to reveal their location to Jessie.', 22, '2006-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 22, 'Stole a Badge', 'Earl tackles No. 127 on his list by making amends for pilfering a police officer''s badge. When he discovers that the theft resulted in the cop''s demotion, he tries to get the officer reinstated.', 22, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 23, 'BB', 'Earl attempts to cross out number 147 on his list "Shot Gwen Waters with a BB Gun."  To make things right he must reunite Gwen with her estranged father which Earl finds increasingly difficult.', 21, '2006-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 1), 24, 'Number One', 'In the season finale, Earl decides to cross off the first number on his karma list, “Stole ten dollars from a guy at the Camden Market.” Earl to his dismay finds out that he owes much more than ten dollars, in fact he must surrender all his lotto winnings. Earl now ponders when karma is going to help him with his misfortunes.', 22, '2006-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')), 2, 'Season 2', 'Doing the right thing isn''t always easy. Just ask Earl Hickley (Jason Lee), a recovering ne''er-do-well with a lifetime''s worth of dirty deeds to make up for. In order to turn his life around, Earl needs a G.E.D., a job, an apartment, and a whole lot of good karma. And, if he can keep his ex-wife out of prison, so much the better!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 1, 'Very Bad Things', 'When Joy and Darnell get into an argument over her surprise birthday, Earl jumps at the opportunity to cross off number 183 on his list “Never took Joy’s side”. Meanwhile Joy runs into various problems after trying to return a television set she recently purchased.', 21, '2006-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 2, 'Jump For Joy', 'In order to help a friend Earl has to raise a lot of money.  He goes to Richard Chubby (Burt Reynolds), owner of Club Chubby a local strip club.  He agrees to loan Earl the money if Earl can convince his most popular dancer to come back and work for him.', 22, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 3, 'Sticks & Stones', 'Earl decides to cross off number ninety-one on his list "Made fun of Maggie Lester for having a moustache." Earl and Randy visit Maggie who is now working for a carnival as "The Amazing Bearded Woman" meanwhile Joy has a run in with the law.', 22, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 4, 'Larceny of a Kitty Cat', 'Earl scratches number 56 off his list when he must return a prize winning cat back to its owner after sabotaging a cat show in Joy''s favor. Meanwhile Randy forms an attraction with the cat’s owner.', 22, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 5, 'Van Hickey', 'Earl tries to make amends with Tom (number 50), the older man they let be the lead singer in his band but then kicked out before their first performance.  While trying to arrange a reunion show Earl must also deal with Number 51, "Slept with Ralph''s mom."', 22, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 6, 'Made a Lady Think I Was God', 'Earl takes on Number 12 on his list "Made a lady think I was God."  Millie Banks, she was the manager of Earl''s trailer park, he pretended to be the voice of God to get her to stop bothering them.', 22, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 7, 'Mailbox', 'Catalina helps Earl cross off No. 75 on his list "Used a mailbox as a trash can" This leads to the discovery of two undelivered letters one is a declaration of a man''s love the other reveals Darnell''s secret.', 22, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 8, 'Robbed a Stoner Blind', 'In the middle of a heat wave, Earl decides to cross number 26 off his list "Robbed a Stoner Blind." To accomplish this task Earl and Randy find Woody the stoner and must live an environmentally conscious life in the commune with Woody for a week.', 25, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 9, 'Born a Gamblin'' Man', 'Earl tackles number 146 on his list.  He decides to make 274 bologna sandwiches for Kenny because he stole them from him in school when they were kids. While delivering the sandwiches, Earl moves onto a new mission, to teach Kenny how to gamble but has trouble stopping. Joy goes to group therapy for her anger management issues.', 22, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 10, 'South of the Border (1)', 'In the first half of this special one hour episode, Earl and Randy face problems in their quest to take Catalina off Earl''s list and bring her home after she was deported because of Earl.  Joy''s friendly attitude causes the neighbors to get closer and Darnell doesn''t like it at all.', 22, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 11, 'South of the Border (2)', 'In the second half of this special one hour episode, Earl and Randy face problems in their quest to take Catalina off Earl''s list and bring her home after she was deported because of Earl. Joy''s friendly attitude causes the neighbors to get closer and Darnell doesn''t like it at all.', 22, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 12, 'Our ''Cops'' is On!', 'It''s a trip down memory lane for Earl, Randy, Joy, Darnell and the Crab Shack regulars when they remember their fifteen minutes of fame watching a 2003 repeat of the TV show "Cops," which was filmed in Camden County.', 22, '2007-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 13, 'Buried Treasure', 'In classic whodunit fashion, Earl must determine who took his stolen "treasure" so he can cross it off his list. Joy, Darnell and Randy all give their own version of what happened to the buried treasure.', 22, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 14, 'Kept a Guy Locked in a Truck', 'Earl attempts to figure out how to make amends to a dead guy that he once locked in a truck.  Meanwhile, newlyweds Randy and Catalina go hunting for an apartment.', 22, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 15, 'Foreign Exchange Student', 'Earl goes for #44 on his list trying to help Pierre, a French foreign exchange student, he made fun of when they went to school together. Earl flies him back to the US and he tries to hook Pierre up with a girl he had a crush on as a child. Meanwhile, newlyweds Randy and Catalina find their marriage changes in ways they would never imagine.', 23, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 16, 'Blow', 'Earl takes on number 101 on his list, "Stole a girl''s identity."  The girl turns out to be Joy''s half-sister that she never knew about and the one person that could possibly help her get sympathy from the jury.  The problem, Joy and Liberty are enemies.', 22, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 17, 'The Birthday Party', 'Earl wants to use his birthday to look back on all the good he''s done over the past year, but at his party, everyone seems to want to talk about his past misdeeds instead.', 22, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 18, 'Guess Who''s Coming Out of Joy', 'With Joy now pregnant again, Earl looks back on her pregnancy during their marriage, and how his father was responsible for one of his first truly good deeds.', 22, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 19, 'Harassed a Reporter', 'As Earl and Randy work to cross No. 29 on the list "Harassed A Reporter," Randy gets tired of being in his brother''s shadow. In an attempt to distance himself from his brother, Randy realizes the true power of karma and the media.', 22, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 20, 'Two Balls, Two Strikes', 'After Richard Chubby dies, Little Chubby comes to town to take over the family business. While Earl tries to cross an item off his list he learns the true meaning of sacrifice.', 22, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 21, 'G.E.D.', 'Earl tries to apply for a credit card but is declined because he doesn''t have a job or a proper place to live, so he goes back to school to receive a diploma, where he realizes how hard it is for teachers to put up with badly behaved kids - just like the one he used to be.', 22, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 22, 'Get a Real Job', 'When Earl decides to get his first real job at an appliance store, he experiences ''growing pains''. Meanwhile, Joy makes another irrational decision when the forthcoming trial continues to get to her.', 25, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 2), 23, 'The Trial', 'Things are finally looking up for Earl with a GED, a job, a new apartment and love interest however it may all come crashing down during Joy''s trial date. Earl''s shocking testimony could help Joy but at what cost?', 30, '2007-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')), 3, 'Season 3', 'Life behind bars is a real pain in the butt. Just ask Earl, whose commitment to good karma has landed him in the Big House. His shackled hands are full - there''s a gang war to stifle and a gala prison prom to plan. Even conjugal visit day is one big headache! With a pregnant ex-wife and a hilariously inept prison guard for a brother, Earl suffers a karmic crisis and finally goes over the top!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 1, 'My Name Is Inmate #28301-016', 'Earl begins his prison sentence. Meanwhile, Joy tries to repay Earl by taking care of Randy (who is struggling to adjust) and a prison bully is looking for Earl.', 42, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 2, 'The Gangs of Camden County', 'Earl is offered a deal to receive a lesser sentence if he can resolve problems between rival gangs. But, he finds the task harder than he expected. Meanwhile, Randy looks for ways to join Earl in prison.', 22, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 3, 'The Frank Factor', 'Joy visits Earl in prison and they are surprised to meet an old friend who is also in prison. The three reminisce about their past and how they met.', 22, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 4, 'Creative Writing', 'Earl is given an assignment after attending a prison class which focuses on creative writing: to write a story. Soon Earl realises that writing is harder than he thought.', 22, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 5, 'Frank''s Girl', 'It''s conjugal visiting day at the prison and since no one is visiting Earl, Frank wants Earl to explain to his girlfriend why he cannot see her today. Things don''t go as planned and Frank''s girlfriend dumps him because of Earl. Earl is blames himself and vows to get them back together.', 22, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 6, 'Our Other Cops is On!', 'Earl and Randy watch the filming of Cops in Camden County where the different situations are slightly related to Earl. Meanwhile, Kenny''s hatred for Earl is caught on camera.', 39, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 7, 'Randy In Charge (...Of Our Days and Our Nights)', 'The Warden ask Earl to make a skit called ''scared straight'' that will stop kids from committing crimes and stay out of jail. Meanwhile, Randy uses his authority to make Earl''s life difficult in prison.', 21, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 8, 'Midnight Bun', 'Joy enlists the help of Darnell to expediate the baby''s birth. Meanwhile, Frank escapes from prison when Randy takes the convicts out for ice cream. Elsewhere, Catalina baby-sits Dodge and Earl Jr.', 22, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 9, 'Burn Victim', 'Earl helps the Warden solve another jail house problem between an inmate and his victims. Later Earl realizes that planning a prom for the inmates might deplete his lottery winnings.', 21, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 10, 'Early Release', 'When Earl finds out that the Warden has destroyed all the certificates that would grant him early release from prison, he seeks the help of his friends to escape.', 21, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 11, 'Bad Earl', 'Earl is having difficulty re-adjusting to life on the outside. He returns to his old ways after he encounters Ralph. Randy plans an intervention for Earl on Christmas morning.', 23, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 12, 'I Won''t Die With a Little Help From My Friends', 'After a car accident Earl is put in a coma and finds himself in an alternate world shown as a sitcom, while his friends try to keep him alive.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 13, 'Stole a Motorcycle', 'While Earl is still in a coma, Randy starts to believe that he can help Earl get better by crossing things off the list.', 22, '2008-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 14, 'No Heads and a Duffel Bag', 'When Randy visits his parents to make up for their ruined vacation, he realizes that he forgot to tell them about Earl''s prison sentence and the following coma at all.', 22, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 15, 'Killerball', 'When the hospital wants to get rid of Earl, Randy decides to take care of his brother by himself. But instead of working on the list for Earl, he uses Earl''s help to cross things off in order to help him get better.', 22, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 16, 'Love Octagon', 'When Earl finally wakes up from his coma, he believes in Karma again and considers Billie his soul mate.', 22, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 17, 'Girl Earl', 'Inspired by Earl, Billie starts a list of her own and when Earl is getting annoyed by Billie''s little habits, he decides to focus on working on the list instead. He picks a task that is on both of their lists, atones for the injury of a champion grocery-bagger and discovers a unique talent of his own. But Earl soon finds out that they have different ways of interpreting Karma.', 21, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 3), 18, 'Camdenites', 'When Earl finds out that making up for all the bad things he did to women changes Billie''s behavior to the good, he picks the worst thing he ever did to women on his list. Billie wants him to choose between her and his list. When he picks the list, she steals it and starts undoing the items he has already accomplished.', 43, '2008-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')), 4, 'Season 4', '"Karma" should be a four-letter word. Just ask Earl, the lovable loser with a hilarious laundry list of dirty deeds that need undoing, from stealing a children''s bookmobile to getting his babysitter pregnant - the hard way! And, while Earl''s brother Randy starts a karmic list of his own, Earl''s ex-wife, Joy, and her husband are movin'' on up to the suburbs. Trouble is, you can take the girl out of the trailer park, but you can''t take the trailer park out of the girl.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 1, 'The Magic Hour', 'When Joy cons Make-A-Wish to send a celebrity to her trailer, Earl remembers a wish he stole from a dying child and decides it''s time to cross him off the list. When he returns to the kid''s home, he finds that little Buddy has exceeded all of the doctors'' expectations and is still alive. Buddy asks Earl to produce his movie and suddenly all of Camden County find themselves starring in a high-octane action film. Randy surprises everyone when his acting skills get rave reviews.', 22, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 2, 'Monkeys Take a Bath', 'Earl and Randy decide it''s time to make amends with their childhood neighbors, the Clarks. But when they discover more skeletons in the closet than they had expected, the brothers find themselves needing to sort out some family issues between their mom and dad. Meanwhile, Joy has duped one-eyed Willy out of his glass eye, and despite Darnell''s efforts Willy may never "see" that eye again.', 23, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 3, 'Joy in a Bubble', 'Earl''s attempt to give Joy the hot tub she''s always wanted backfires and she is forced to stay in a makeshift bubble because of a flesh eating toe infection. While she is out of commission, Earl must fill in as the new Joy. Between gossiping with the ladies at the salon and shopping for meat out of some guy''s trunk, Earl learns about the Turner family. This includes the fact that Dodge and Earl Jr. might have a social disorder that causes them to have no friends. Can Earl fix this problem too?', 22, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 4, 'Stole an RV', 'To cross Jerry off of his list, Earl can''t just return the RV he stole, mostly because Randy blew it up. Earl and Randy set out to find what might make this grumpy war hero happy, and accidentally turn him into a 75-year-old killing machine. Elsewhere, Joy and Darnell attempt to turn the legend of a giant pig that lives near the trailer park into a one-of-a-kind, money making sideshow.', 22, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 5, 'Sweet Johnny', 'Earl wants to make up for sleeping with local stuntman Sweet Johnny''s girlfriend, while Joy feels the need to buy a gun.', 21, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 6, 'We''ve Got Spirit', 'To cross Randy off his list, Earl takes his brother to cheerleading camp. Once there, the tight cheer pants and their lack of flexibility are not their only problem. They also have to deal with Kimmi Himmler, the camp owner with a deeply scarred face and milky eye - both a result of a badger accident suffered while cheering in high school. When Himmler wants the brothers out of her camp, Earl goes to drastic measure to make sure that Randy''s cheerleading dreams will come true. Elsewhere, Joy is hurt when her son Dodge indicates that Catalina is the most beautiful woman in Camden.', 21, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 7, 'Quit Your Snitchin''', 'When Randy''s birthday is coming up, Earl gets him a new car, but it is stolen before he can present it to Randy. Apparently, Earl no longer falls under the code of criminals, that no criminal steals from another one. Now that he is treated as a "civilian", he needs to decide whether to take the matter to the police and become a snitch.', 21, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 8, 'Little Bad Voodoo Brother', 'Earl plans a Halloween party for Dodge and Earl Jr, while Catalina''s nephew Oscar visits. This poses an opportunity for Randy to become the big brother he always wanted to be.', 22, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 9, 'Sold a Guy a Lemon Car', 'Suddenly at the top of Earl''s list a life-or-death item appears right after a new mysterious man moves in next door. Meanwhile, a science fair has Joy all worked up to the point of obsession. She'' so fixated on winning the fair so she can buy something special with the prize money.', 22, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 10, 'Earl and Joy''s Anniversary', 'Earl remembers his first wedding anniversary and the events that finally lead to their break up, involving Earl''s cousin Blake and an invasion of killer bees.', 22, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 11, 'Nature''s Game Show', 'Earl loses his list while tornado''s hit Camden County. Meanwhile, Randy thinks he''s invincible after a wild boat ride and contemplates how he should use his new found power. Elsewhere, who''s the smartest, Joy or Darnell? that''s what this weeks argument is about and Catalina and Patty have a religious awakening.', 22, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 12, 'Reading Is a Fundamental Case', 'Earl remembers a list item he crossed off while reading to the children of Camden County. While going down memory lane, Earl recalls that his old friend Raynard kept company with a raccoon while living in the great outdoors.', 22, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 13, 'Orphan Earl', 'Earl discovers that Joy has continued a holiday scam they started years before, and has expanded the scam to include her friends.', 22, '2008-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 14, 'Got the Babysitter Pregnant', 'A young Earl gets his heart broken by the babysitter and swears revenge on her and her boyfriend. Now, Earl is older and wiser, so he decides to cross them off his list, but it may have terrible repercussions for Randy. Meanwhile, Joy loses Darnell''s pet turtle', 22, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 15, 'Darnell Outed (1)', 'Joy steals Randy''s audition for Erik Estrada''s reality show "Estrada or Nada", but her public appearance has consequences for Darnell.', 22, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 16, 'Darnell Outed (2)', 'In the aftermath of having his cover blown, Darnell must pack up and leave Camden. Meanwhile, Earl, Randy and Catalina discover a devastating truth within the post office.', 22, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 17, 'Randy''s List Item', 'When Randy loses his winning lottery ticket, he assumes the event to be a message from Karma, so he starts a list of his own. Meanwhile, Joy is not happy with her cover identity of the witness protection program.', 22, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 18, 'Friends with Benefits', 'When Mr. Turtle returns back to Earl, he wants to bring him back to Darnell. Meanwhile, Joy and Darnell have to adapt to a new lifestyle of their cover identities.', 22, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 19, 'My Name Is Alias', 'Danny Glover guest stars as Darnell''s father who comes looking for him in Camden only to raise Earl and Randy''s suspicions. However, a family reunion leads to father and son partaking in one last undercover mission.', 22, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 20, 'Chaz Dalton''s Space Academy', 'Earl works on a list item that has to do with Chaz Dalton, his childhood hero. Meanwhile, Darnell tries to help Joy make friends using the internet.', 22, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 21, 'Witch Lady', 'Earl works on a list item that deals with a crazy witch lady. Meanwhile, Joy wants to show Darnell her good side.', 23, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 22, 'Pinky', 'Earl helps Randy find his first love, Pinky.', 23, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 23, 'Bullies', 'Randy busts into the motel room, demanding that Earl drive to Joy''s and punch her in the face. Over time, Randy has invested lots of time and money in the Crab Shack''s claw machine, but every time he wins a cute stuffed animal, Joy bullies him into giving it to her. This last time he won a fancy bird dressed up for a wedding and the loss has put Randy over the edge. Earl points out that Randy is 32 years old, and it''s time he learned to stick up for himself - Earl''s not going to protect him anymore.', 22, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 24, 'Gospel', 'Earl tests the faith of a former gangbanger-turned-born-again reverend, whom he''s wronged many, many times.', 22, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 25, 'Inside Probe (1)', 'News show "Inside Probe" investigates the disappearance of the Crab Shack owner. After eight years the show airs on TV, and several Camden residents become murder suspects.', 22, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 26, 'Inside Probe (2)', 'The mystery of the disappearance of the former Crab Shack owner is finally resolved.', 21, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460091')) AND numero_temporada = 4), 27, 'Dodge''s Dad', 'When Dodge tells Joy he doesn''t want Darnell to speak at career day, she enlists Earl to pretend to be his father. Things don''t go well and Earl realizes Dodge needs to know his real dad. Despite Joy''s protests, Earl enlists Randy and Catalina to help him hunt down the deadbeat dad, but what they discover is worse than they could have imagined.', 22, '2009-05-14');
