INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 1, 'Pilot', 'Melinda Gordon just got married; during the dinner she sees something being drawn on the window and she knows it''s a ghost. But for the first time, the ghost comes inside her house and that unsettles her. Despite being afraid, she tries to help him reunite with his family and pass along the message he needs her to say.', 45, '2005-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 2, 'The Crossing', 'A boy who was killed in a collision with a train wants Melinda''s help to ensure his mother that his death was not caused by her.', 43, '2005-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 3, 'Ghost, Interrupted', 'The identical twin sister of a teenage girl requests Melinda to help her apologize to her sister who is a psychiatric patient.', 44, '2005-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 4, 'Mended Hearts', 'A man killed in a biking accident seeks Melinda''s help to save his fiance''s life and finding out who received his heart afterwards.', 42, '2005-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 5, 'Lost Boys', 'Melinda encounters the ghosts of three boys who died in the fire of an orphanage. They must cross over prior to the demolition of the building holding them inside.', 45, '2005-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 6, 'Homecoming', 'Melinda helps an angry teenage ghost and discovers the secret that is likely to shake up the ones left behind by him.', 44, '2005-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 7, 'Hope and Mercy', 'In a hospital, Melinda encounters a woman who wants to determine what caused her death during a surgery.', 43, '2005-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 8, 'On the Wings of a Dove', 'An evil spirit is haunting Jim, causing him to begin doubting his sanity. Melinda must help this spirit, even though he is dangerous, in order to help Jim. .', 45, '2005-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 9, 'Voices', 'The spirit of the mother of a teenage boy attempts to communicate with her son via white noise. Melinda must find a way to get her messages across.', 45, '2005-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 10, 'Ghost Bride', 'A ghost of a bride who didn''t make it through her wedding night is back with a vengeance haunting her husbands new fiancée to the point of her leaving him at the alter.', 44, '2005-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 11, 'Shadow Boxer', 'The dead mother of a boxer requests Melinda to assist in getting her son back together with his father. The son is furious because his father caused him not to be able to spent time with his dying mother.', 42, '2005-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 12, 'Undead Comic', 'After a stand-up comedian commits suicide, he''s left in between worlds. Melinda tries to help him find closure.', 45, '2005-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 13, 'Friendly Neighborhood Ghost', 'The ghost of an elderly man suspects Melinda''s new neighbor of killing his granddaughter.', 44, '2006-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 14, 'Last Execution', 'A hanged man''s ghost follows Melinda home from a macabre art installation, haunting her into contacting his troubled daughter.  A woman sues Melinda''s paramedic husband, claiming he further injured her whilst performing life-saving CPR.', 44, '2006-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 15, 'Melinda''s First Ghost', 'Melinda is forced to remember how her relationship with her mother became strained after Melinda’s first ghost emerges.  Melinda’s mother could not understand how to deal with Melinda’s gift.  Melinda must reunite with her mother to help the ghost.', 45, '2006-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 16, 'Dead Man''s Ridge', 'Andrea’s friend has gone missing during a hike and Melinda’s called in so she can use her abilities to find him.', 43, '2006-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 17, 'Demon Child', 'Melinda comes across the spirit of an infuriated young boy, who''s terrorizing his mother and baby sister.', 44, '2006-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 18, 'Miss Fortune', 'When a traveling circus arrives, Melinda meets the bitter ghost of a magician who accuses his envious brother of his death, deemed to have been accidental.', 45, '2006-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 19, 'Fury', 'Melinda must help the ghost of an African-American man who had been attacked and killed by a white co-worker in the 1970''s.  The ghost is haunting the prosecutor who had enough evidence but still failed to file charges against the white co-worker.  Melinda tries to help the ghost find justice and help his son to change his racist views before they''re passed on to the next generation.', 43, '2006-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 20, 'The Vanishing', 'A head injury caused by an accident puts Melinda''s abilities at risk. Melinda must deal with the possibility of permanently losing her gift as she attempts to help a young girl whose boyfriend has recently died.', 45, '2006-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 21, 'Free Fall', 'Melinda experiences a sense of dread when she realizes that a plane is going to crash when the spirits of the pilot and flight attendant contact her.', 45, '2006-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 1), 22, 'The One', 'After a jetliner crashes Melinda faces the overwhelming task of helping hundreds of passengers crossover.  While Melinda faces this task she finds that the “Wide Brim Man” is working against her.  Melinda must also try to work with the crash investigators who are trying to find out how Melinda knew that the plane was going to crash.', 45, '2006-05-05');
