INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 2, 'Love Still Won''t Die', 'A rock and roll enthusiast expands his love to living teens by tormenting them into stealing. Melinda must also deal with the ghost of her scheming ex-boyfriend.', 45, '2006-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 3, 'Drowned Lives', 'When Melinda goes to visit friends who are experiencing problems with their house, she finds the ghost of six-year-old little girl who drowned.  Melinda then tries to help the family of the little girl.', 45, '2006-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 4, 'The Ghost Within', 'After purchasing a set of ornaments at a flea market, Melinda finds that they are haunted.  Melinda uses the ornaments to meet Dennis’s ghost.  Dennis wants Melinda to reunite his girlfriend with her birth mother.', 45, '2006-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 5, 'A Grave Matter', 'The ghost of a man who was buried in the wrong grave starts to haunt a cemetery as someone else’s wife is coming to mourn him every night.  Melinda must reconcile the man with his hostile wife and daughter in order for him to be able to cross-over.', 45, '2006-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 6, 'The Woman of His Dreams', 'Jim has a ghost who died during surgery come to his dreams.  Melinda and Jim find that the ghost, a supermodel, cannot cross-over as she wants to save her little sister from suffering the same destiny.  Jim''s friends are frightened by the crazy events that occur at his house.', 45, '2006-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 7, 'A Vicious Cycle', 'Melinda and Jim''s first camping trip is interrupted as Melinda helps the ghost of a woman who left her husband and young daughter.  Before the woman can cross over Melinda must find the woman’s daughter and help her to learn the truth about her parent’s past in order for her to be safe now.', 45, '2006-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 8, 'The Night We Met', 'The ghost of chef who died in a fire at a Chinese restaurant meets Melinda after the restaurant he died in burns for a second time.  He demands that Melinda go out and find the person that really set the fire he was blamed for.', 45, '2006-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 9, 'The Curse of the Ninth', 'When Melinda meets a nightclub waiter who has not played his guitar since his friend died, she finds that he is being haunted by two ghosts.', 45, '2006-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 10, 'Giving Up The Ghost', 'A high school baseball pitcher Justin finds that he is haunted by the former baseball star pitcher.  The ghost is out for revenge on the coach who he blames for his death.', 42, '2006-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 11, 'Cat''s Claw', 'While Melinda is at the University’s botany lab she deals with some telekinetic events while dealing with a plant from Peru that is bleeding.  Melinda finds that she must help a Doctor save herself.', 45, '2006-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 12, 'Dead To Rights', 'Melinda has trouble talking to a ghost only to find that it''s because he is not dead but is in a coma. While Lisa, his wife is in a legal battle against his parents to take him off of the life support. Meanwhile Delia struggles with teaching Ned about closure while also finding closure for herself.', 43, '2007-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 13, 'Deja Boo', 'Melinda finds that she must stop a ghost who doesn''t want to be reincarnated again.  Melinda finds out that someone knows her secret.  Delia has second thoughts about dinner date.', 45, '2007-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 14, 'Speed Demon', 'Melinda''s Jeep breaks down on a deserted road and a young woman who owns an auto shop comes by to help. Melinda meets a ghost who comes to her in the form of a skeleton.  Melinda must first decipher the mysterious code that is linked to the drag racing society. Melinda finds that Ned is involved with the society and needs his help. Ned lies to his mom and sneaks out to go to the drag races. At the end the ghost finds closure and crosses over into the light.', 43, '2007-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 15, 'Mean Ghost', 'Melinda gives a speech on her career at Grandview High.  While she’s at the school she sees a group of cheerleaders who are having some mean and vicious things happening to them just as their cheerleading semi-finals are approaching in just a few days. Melinda discovers that the dead cheerleader can’t cross over and someone else has been casting spells on the squad.', 44, '2007-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 16, 'The Cradle Will Rock', 'Melinda accompanies Delia to the local jewelry store so she can get her newly refurbished engagement ring.  An armed robbery occurs while they are in the jewelers.  Later, the ghost of jewelry salesman visits Melinda and she must help him make things right again.', 43, '2007-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 17, 'The Walk-In', 'A body goes missing from the morgue and Melinda searches for the body.  When the ghost visits Melinda she finds she needs help from Professor Payne to figure it out.', 44, '2007-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 18, 'Children Of Ghosts', 'Melinda and Jim become foster parents temporarily for a young girl whose mother is missing.  The ghost of the mother comes to Melinda and tells her where Melinda can find her body.  The mother confesses a secret to Melinda and Melinda and Jim set out to help the little girl.', 45, '2007-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 19, 'Delia''s First Ghost', 'Melinda helps Ned deal with a ghost who had just put a scare into him. Melinda also helps a ghost who appears to without any clothes on.  Delia sees that Melinda is once again talking to herself and Melinda decides it’s time to share her gift with Delia.', 45, '2007-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 20, 'The Collector', 'Melinda meets a man who has the same abilities to see and talk to the dead.  Melinda later learns that he has a different plan for the dead.  A ghost enlists Professor Payne to help Melinda.', 45, '2007-04-27');
