INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 2), 22, 'The Gathering', 'Melinda visits the Mayor of Grandview and asks him to cancel the memorial dedication they are holding. She speaks to the ghost of a mail person and is looking for a young girl named Kristen. Later, Melinda and Professor Payne search for missing children after their Nanny says that they left with a man named Gabriel. Meanwhile, a mysterious man tries to get Melinda to stop helping the good guys.', 43, '2007-05-11');
