INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 10, 'Excessive Forces', 'When the ghost of a high school boy accuses a Grandview cop of murdering him, Melinda is convinced that his death wasn''t a mere skateboarding accident.', 44, '2009-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 11, 'Dead Air', 'Melinda must help Ned stop a ghost out for revenge when the Grandview radio station broadcasts the humiliating secrets that led to his death.', 45, '2010-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 12, 'Blessings in Disguise', 'Melinda must discover the truth hidden within a family before it threatens to tear the her family apart.', 44, '2010-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 13, 'Living Nightmare', 'When Melinda discovers a family secret, madness grips the hospital and the town when a ghost who is making no sense haunts a patient who''s making even less. Melinda must unravel the mystery behind a madness that grips Jim''s (David Conrad) hospital - and the rest of Grandview.', 45, '2010-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 14, 'Dead to Me', 'Ned''s Occult Anthropology professor is stalked by the ghost of a secret admirer. Ned tries to use a Ouija board to help solve the mystery but instead is warned that someone they know is going to die soon.', 44, '2010-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 15, 'Implosion', 'A ghost who knows of a hidden munitions dump with unexploded bombs confides in Melinda that one of those bombs is missing and in the wrong hands', 44, '2010-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 16, 'Old Sins Cast Long Shadows', 'Dark forces are fighting for the soul of a little girl that cannot escape the haunted house she has been trapped in for years.', 45, '2010-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 17, 'On Thin Ice', 'Damon is a graphic (comic) novelist; kind of hip and edgy, he is being haunted by the ghost of a teen boy as he is ready to release his new novel and strange things start to happen to him and the ghost is tormenting him until Melinda can help him find out who is trying to stop his work, while the things the ghost does to Damon are predicted in his comics.', 45, '2010-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 18, 'Dead Eye', 'When a confused ghost dressed as a clown begins haunting Melinda''s house, it''s up to her and Eli to look for answers in the ghost''s final case as a private investigator - a love story involving greed and suspicion.', 44, '2010-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 19, 'Lethal Combination', 'When Aiden is put in danger, Melinda won''t accept anything but the truth and sets out on a shocking investigation into the life of an angry murdered ghost. Meanwhile, Jim is caught snooping through files in the file room at his work by the morgue coroner Dr. Mavis.', 45, '2010-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 20, 'Blood Money', 'Henry was 18 years old when he was killed, with a gunshot wound in his chest. In life he was a decent boy from a wealthy, loving family, whose parents believed that he should earn his own living and not rely on their handouts. He masterminded his own kidnapping with a friend of his, and seems relieved to be able to explain to his mother, via Melinda, that he''s felt guilt and remorse ever since.', 45, '2010-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 21, 'Dead Ringer', 'When the ghost Melinda is trying to help suddenly turns up alive, she finds herself in the middle of a dangerous revenge plot and battling enemies she was unaware she had.', 45, '2010-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460644')) AND numero_temporada = 5), 22, 'The Children''s Parade', 'Jim''s hospital is being haunted by the ghosts of kids from an abandoned polio ward in the early 1900’s. And the connection of Aidan, Melinda, the Shinies and the Shadows will come to a climax and Melinda and Jim will realize that they know almost nothing about Aiden''s powers.', 45, '2010-05-21');
