INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649'), 'Comedia');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649'), 'Drama');
INSERT IGNORE INTO ContenidoPerteneceACategoria (id_contenido, nombreCategoria) VALUES ((SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649'), 'Romance');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 1, 'Season 1', 'A love story in reverse: How I Met Your Mother is a fresh new comedy about Ted (Josh Radnor) and how he fell in love. When Ted''s best friends Marshall (Jason Segel) and Lily (Alyson Hannigan) decide to tie the knot, it sparks the search for his own Miss Right. Helping him in his quest is his bar-hopping "wing-man" Barney (Neil Patrick Harris), a confirmed bachelor with plenty of wild schemes for picking up women. Ted''s sights are set on the charming and independent Robin (Cobie Smulders), but destiny may have something different in mind. Told through a series of flashbacks, Ted recalls his single days, the highs and lows of dating and the search for true love.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 1, 'Pilot', 'When Ted''s best friend Marshall proposes to his girlfriend, Lily, Ted realizes he''d better get a move on if he hopes to find true love. Ted soon meets Robin in a neighborhood bar, immediately becomes smitten and scores a first date. But when Ted can hardly wait to see her again, his eagerness threatens to scare her away.', 23, '2005-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 2, 'Purple Giraffe', 'In a desperate attempt for a second date, Ted invites Robin to a party he is throwing. However, she doesn''t show up and he keeps throwing parties in the hopes she will finally arrive.', 23, '2005-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 3, 'Sweet Taste of Liberty', 'Ted agrees to let Barney spice up his love life, and ends up on a crazy adventure of flying to Philadelphia, encountering the law and visiting the Liberty Bell.', 21, '2005-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 4, 'Return of the Shirt', 'Ted''s outlook on his continuing search for love is altered when he rediscovers a shirt that has not seen daylight in years. Meanwhile, Barney amuses himself by coaxing Robin into sacrificing her job by saying completely outlandish things on air live for a cash reward.', 23, '2005-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 5, 'Okay Awesome', 'Ted and Barney start checking out the club scene with their friend Robin, whereas Lily and Marshall try to participate in some more "grown-up" activities, as they draw slowly nearer to their wedding.', 22, '2005-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 6, 'The Slutty Pumpkin', 'Ted makes his yearly pilgrimage to the rooftop Halloween party in search of a girl dressed as a pumpkin who he met years ago. Meanwhile, Robin is dumped after driving her new boyfriend away with her independent ways.', 22, '2005-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 7, 'Matchmaker', 'When a matchmaker with a 100% success rate turns Ted away because he is not compatible with any of the available women in her database, he is still determined that he is going to find his match. After getting information from the matchmaker''s computer, Ted pays a visit to a very cute, but taken, dermatologist in an effort to prove the prediction wrong that there are no women out there for him. Meanwhile, Marshall and Lily are obsessed with ridding their apartment of a critter.', 22, '2005-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 8, 'The Duel', 'As Lily becomes more of a permanent fixture in the apartment, Ted feels like he is being edged out of the mix by his engaged roomies. Petrified of being left alone and homeless, Ted tells Marshall that when he and Lily are married, he wants the apartment. The problem is that Marshall wants to keep the place too, so they settle it like real "grown-ups" -- launching into a sword fight that leaves one man down for the count.', 22, '2005-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 9, 'Belly Full of Turkey', 'Ted and Robin are surprised to run into Barney when they volunteer at a homeless shelter on Thanksgiving. Lily is on the brink of freaking out when she goes to Thanksgiving dinner at her future in-laws house.', 22, '2005-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 10, 'The Pineapple Incident', 'After being forced into knocking back 5 shots, so he will stop thinking, Ted goes on a partying rampage. The next morning he wakes up with a woman in his bed, but he does not know who it is. So he turns to his friends to try and piece the night together and work out who the woman is in his bed.', 22, '2005-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 11, 'The Limo', 'Ted rents a limo to take the gang out to sample five New Year''s Eve parties in a quest to find the perfect celebration.', 23, '2005-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 12, 'The Wedding', 'Robin accepts Ted''s invite to a friend''s wedding, but thanks to Ted, the couple may never make it down the aisle.', 22, '2006-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 13, 'Drumroll, Please', 'Ted finds a new woman at the wedding. They want to remember the evening so they don''t exchange last names or numbers; but Ted takes a big fall when he tries to find out her name.', 22, '2006-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 14, 'Zip, Zip, Zip', 'After agreeing to take things slowly and not have sex for a month, Ted and Victoria decide that they have waited long enough.', 23, '2006-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 15, 'Game Night', 'A mysterious tape arrives for Barney from one of his numerous ex-girlfriends, and the entire gang watches it. But, in order for them all to find out how she broke Barney''s heart and made him into a suit-wearing bachelor, everyone must share their most embarrassing moment.', 22, '2006-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 16, 'Cupcake', 'Things are going great with Ted and Victoria''s relationship, but when Victoria is offered her dream job, the couple have to make serious relationship decisions. Meanwhile Marshall and Lily set out to purchase their wedding outfits and find out that none can afford what they bought.', 22, '2006-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 17, 'Life Among the Gorillas', 'Marshall interns at the corporation where Barney works and Lily finds that he is becoming a shallow jerk as he tries to fit in with his crude fratty coworkers. Meanwhile, Ted feels guilty when he receives several gifts from Victoria (Erika Singh) while he hasn''t sent her anything.', 22, '2006-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 18, 'Nothing Good Happens After 2 A.M.', 'Robin, who is very lonely, asks Ted to come over to her apartment after 2 A.M., but he isn''t sure if he wants to go as he has a phone call on the way over with his friends, and with Victoria on his mind', 22, '2006-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 19, 'Mary the Paralegal', 'Robin is nominated to receive an award for a news report and everyone needs a date to take to the show. Barney introduces Ted to Mary as a date that Ted can take to the show. Originally Ted is opposed to the idea of just trying to save face in front of Robin but when she shows up with a date he changes his mind. Robin asks Mary lots of questions, and Ted begins to really like Mary, despite her occupation.', 22, '2006-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 20, 'Best Prom Ever', 'Lily, Barney and Robin attend a high school prom to scout out a potential band for Lily and Marshall''s wedding reception. In order to get in Lily and Robin pretend to be the dates of two kids who were going alone. Ted and Marshall are back at the apartment where they are preparing the invitations to be sent out.', 22, '2006-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 21, 'Milk', 'When a matchmaking company calls Ted claiming they have found his soul mate, he is forced to postpone his date when Lily asks for his help.', 22, '2006-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 1), 22, 'Come On', 'Ted tries to keep Robin from going on a camping trip so that she can spend time with him. Barney enlists the help of an old flame to perform a rain dance. At the same time Marshall finds out about Lily''s interview for the fellowship in San Francisco.', 22, '2006-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 2, 'Season 2', 'The woman of his dreams is out there — the question is, who is she? — Told in a series of flash backs, How I Met Your Mother is the hilariously unpredictable story of how twenty-something Ted meets his soul mate and says goodbye to the singles world of pick-up lines, one night stands, and relationship "deal-breakers." With friends Marshall and Lily''s wedding fast approaching, the outrageously inappropriate Barney remains a consummate bachelor, while Ted''s romance with Robin heats up, but is she really the one for him? Things have a funny way of working out in this delightfully fresh and fast-paced comedy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 1, 'Where Were We?', 'The gang tries to help Marshall get over Lily, especially when he finds a credit card bill that leads to a hotel in New York City where some of her charges are listed.', 21, '2006-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 2, 'The Scorpion and the Toad', 'Barney works with Marshall on his bachelor skills, which include hitting on women. Lily is back from her venture. Robin helps her look for a new apartment but gets sick of hearing about San Francisco.', 22, '2006-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 3, 'Brunch', 'Ted''s parents visit New York for their anniversary and he learns a family secret. Robin worries that they won''t like her. Lily and Marshall try to adjust to the new format of their relationship now that they are no longer together.', 23, '2006-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 4, 'Ted Mosby, Architect', 'After Ted and Robin''s first big fight, Barney tries to convince Ted that being an architect is an easy in to picking up chicks. Lily and Robin start following his trail after discovering that Ted hit it off with a girl named Anna shortly afterward.', 23, '2006-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 5, 'World''s Greatest Couple', 'Marshall tries to get used to being single in a world that is very coupled-oriented. Barney intended one-night-stand won''t go away. Barney uses Lily to get out of his "horrifying" situation. Lily finds a place to stay.', 23, '2006-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 6, 'Aldrin Justice', 'Barney seduces Marshall''s law professor in hopes of getting her to grade more leniently. Lily takes a job at Ted''s office, where she promptly steals to teach Ted''s boss a lesson.', 22, '2006-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 7, 'Swarley', 'Marshall goes on his first real date post-breakup with Lily. Not only do Ted and Barney try to warn him that this girl has got the crazy eyes, but Lily decides to do everything she can to find out about this her and break them up. Also, Barney gets a new name.', 22, '2006-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 8, 'Atlantic City', 'Marshall and Lily drag the gang to Atlantic City to elope, and their quest to overcome the three-day wait for a marriage license crosses them with some Chinese gamblers, a ship captain, and a sexy novelty shirt.', 22, '2006-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 9, 'Slap Bet', 'Ted and Barney discusses their viewpoints on knowing things about women. Barney thinks that the more you know the more likely you are to find a deal breaker. Ted wants to know the deal breakers right away, as Robin refuses to go to the mall to cover her secret.', 23, '2006-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 10, 'Single Stamina', 'Barney''s brother, James (Wayne Brady), visits and Robin, the only one in the group that has never met him, is suprised. But James has a surprise for Barney that he finds difficult to swallow.', 23, '2006-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 11, 'How Lily Stole Christmas', 'Ted almost ruins Christmas for everyone when, still carrying around anger toward Lily, he calls her a horribly disgusting name. Robin tends to Barney while he has a cold.', 23, '2006-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 12, 'First Time in New York', 'Robin wants to tell Ted that she loves him, but she can''t tell him. Meanwhile, her sister visits and brings her boyfriend, and Robin doesn''t know how to react when her sister says she''s ready to lose her virginity.', 23, '2007-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 13, 'Columns', 'When Ted is constantly insulted by his former boss, who is now working for him on a project, he is told to fire the man, but he finds that a hard thing to do. Meanwhile, Barney offers Lily a lot of money to paint a nude portrait of him.', 22, '2007-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 14, 'Monday Night Football', 'When a funeral conflicts with the Super Bowl, the gang vows to avoid hearing the score and watch it together on Monday. This proves difficult, as Marshall is threatened with the score by a boy in Lily''s class, while doing the news puts Robin in danger of finding out who won.', 22, '2007-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 15, 'Lucky Penny', 'Ted can''t seem to catch a flight to interview for his dream job and he and Robin contemplate why. The story unfolds backwards as they think about it they remember when Robin and Lily went hunting for a wedding dress and when Barney got stuck on the subway.', 23, '2007-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 16, 'Stuff', 'Lily gets asked to play in an off-off-off-off-broadway play, and the gang shows up to support her. Ted and Robin get hung up on what each kept from their past relationships. Barney performs his own play to prove a point to Lily.', 22, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 17, 'Arrivederci, Fiero', 'Marshall is all set to celebrate his beloved Fiero hitting the 200,000 mile mark but it stops. While the gang sits in the mechanic''s garage and waits to hear what will happen to the vehicle they think about times gone by that they have spent together in the car. We also get the story of how Ted met Marshall.', 22, '2007-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 18, 'Moving Day', 'Barney takes drastic measures to prevent Ted from moving into Robin''s apartment. Meanwhile, Marshall and Lily are discovering the ups and downs of having the apartment to themselves. Barney considers moving in with Marshall and Lily.', 23, '2007-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 19, 'Bachelor Party', 'Robin attends Lily''s bridal shower and finds the gift that she brought is out of place. Barney hires a stripper for Marshall''s bachelor party.', 23, '2007-04-09');
