INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 2), 22, 'Something Blue', 'It''s still Marshall and Lily''s big wedding day but now we''re at the reception. Robin tries to tell a story but keeps getting interrupted. Barney tries his hardest to figure out Ted and Robin''s secret.', 23, '2007-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 3, 'Season 3', 'It''s Season Three and the search for a soul mate has never been so wildly inappropriate! Thirty-year-old Ted is still looking for Miss Right, but his road to domestic bliss is improbably paved with punk rock girls, tattoos, adult video expos and an epic St. Patrick''s Day bender. Meanwhile, as Marshall and Lily adjust to the quirks of married life, the outrageously incorrigible Barney commits a major violation of "The Bro Code." Plus, Season Three features a host of hilarious guest stars, including BRITNEY SPEARS, SARAH CHALKE (TV''s Scrubs), ENRIQUE IGLESIAS, MANDY MOORE and supermodel HEIDI KLUM.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 3), 1, 'Wait for It', 'Robin shows up with a date and this motivates Ted to ''get back out there''. We also learn something major about ''the Mother''.', 21, '2007-09-24');
