INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 4), 22, 'Right Place, Right Time', 'Ted ponders how being in the right place at the right time can impact a person''s life; Barney celebrates his 200th female conquest.', 21, '2009-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 4), 23, 'As Fast as She Can', 'Ted is trying to find a new job, and when an old acquaintance tries to help nothing goes as planned. Barney tries to smooth talk his way out of a ticket.', 23, '2009-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 4), 24, 'The Leap', 'Ted is trying to keep his architecture firm afloat by doing an all-nighter, but Marshall tries to lure him to the roof for a surprise 31st birthday party, on the fourth season finale.', 23, '2009-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 5, 'Season 5', 'Suit up for the hilarious Season Five of How I Met Your Mother, the outrageous, Emmy®-nominated hit starring Neil Patrick Harris, Jason Segel and Alyson Hannigan! The show''s funniest season to date is loaded with hook-ups, break-ups and the return of Slapsgiving — not to mention the hottest guest stars imaginable, including Jennifer Lopez, Carrie Underwood, Amanda Peet and Rachel Bilson. On the dating front, Barney and Robin take their relationship to the next level — before calling it off — and Ted meets the roommate of his future wife in this uproarious, modern-day love story told in reverse.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 1, 'Definitions', 'After sharing a kiss at the beginning of the summer, Robin and Barney are unsure how to handle their mutual attraction. After some consideration they tell the gang they have decided to remain just friends, but secretly continue seeing each other. They are able to get away with their secret romance for a couple months, but are discovered when Ted, Marshall and Lily walk in on them together. They explain to the gang that they are happy with their casual relationship, and didn''t want to complicate it by defining it. This is unacceptable to Lily, who pressures them to label their situation, and ultimately locks them in Robin''s room to force them to address it. Meanwhile, Ted is anxious about his first days as a professor at Columbia, which is made worse when he shows up at the wrong class and starts his lecture.', 23, '2009-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 2, 'Double Date', 'Barney takes Marshall, and Robin to a strip club where they find a stripper who looks almost exactly like Lily. Meanwhile, Ted discovers he had been fixed up with the same woman, Jen seven years earlier.', 23, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 3, 'Robin 101', 'When Robin fears that Barney is cheating on her, she soon discovers that he is spending his evenings with Ted learning everything there is to know on how to date her.', 23, '2009-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 4, 'The Sexless Innkeeper', 'Marshall and Lily want to hook up with Barney and Robin for double-dating and fun, but their desperate eagerness to please is a huge turn-off. Meanwhile, when a succession of girls come to his apartment and immediately fall asleep, Ted is bummed to learn he is a "Sexless Innkeeper" whose "dates" are only interested in a comfy place to crash', 23, '2009-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 5, 'Duel Citizenship', 'Barney tries his best hoping to convince Robin into becoming an American citizen, while Ted and Marshall''s road trip takes an unexpected turn for the worst when Marshall invites Lily to come along.', 23, '2009-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 6, 'Bagpipes', 'Even though they do their best in order to be the perfect couple, Barney''s attitude of know-it-all lands him in trouble with Robin and they are forced to seek Marshall and Lily for advice.', 23, '2009-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 7, 'The Rough Patch', 'Lily comes up with a perfect plan to break up the relationship between Barney and Robin when they have a rough patch, but she needs help from Robin''s famous friend, Alan Thicke, in order to make it work.', 23, '2009-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 8, 'The Playbook', 'After his relationship with Robin ends, Barney dusts off his "playbook" to help him back into the dating scene', 23, '2009-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 9, 'Slapsgiving 2: Revenge of the Slap', 'Barney freaks out when Marshall bequeaths a "slap bet" slap to Ted and Robin. Meanwhile, Lily''s estranged father shows up for Thanksgiving.', 23, '2009-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 10, 'The Window', 'When a perfect girl finally shows up, the gang tries everything to help Ted, while Marshall takes action when he discovers a letter written by younger himself.', 23, '2009-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 11, 'Last Cigarette Ever', 'When Marshall picks up smoking again, it prompts Lily, Ted and Barney, ex-smokers all, to succumb as well. Meanwhile, Robin gets a new co-anchor at her show...', 23, '2009-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 12, 'Girls vs. Suits', 'When Barney debates giving up wearing suits in order to land a hot bartender, his conflicted feelings lead to an amazingly awesome musical number. Meanwhile, Ted gets one step closer to meeting the future mother of his kids.', 23, '2010-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 13, 'Jenkins', 'When Lily refuses to believe that Jenkins, Marshall''s attractive female colleague, kissed him, Marshall insists Jenkins tell Lily what really happened. Meanwhile, Robin finds out that a drinking game has been made up about her.', 23, '2010-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 14, 'Perfect Week', 'When Barney is about to complete the perfect week - landing seven different girls in seven days - the gang roots him on in order to forget about their own miserable week.', 23, '2010-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 15, 'Rabbit or Duck', 'When Lily and Marshall forget to fix up Ted on a blind date for Valentine''s Day, they use one of Barney''s many discarded girls to see if they may become Ted''s future wife. Meanwhile, Robin''s obnoxious colleague invites her to a party at his apartment', 23, '2010-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 16, 'Hooked', 'When the gang tries to convince Ted that he is being strung along by Tiffany, they reflect about relationships where each of them has been in the same situation.', 23, '2010-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 17, 'Of Course', 'When Robin confesses that she is still angry with Barney for the way he handled their break-up, she enlists the help of Anita, a self-help author who plans to beat Barney at his own game.', 23, '2010-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 18, 'Say Cheese', 'When Ted ruins Lily''s birthday dinner celebration by bringing a date, Lily goes to great lengths to keep her out of the traditional photo she takes every year of the gang.', 23, '2010-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 19, 'Zoo or False', 'When Marshall gets mugged, Lily decides she wants to get a gun for protection, so Marshall comes up with a convoluted story about the mugging to deter Lily from following through.', 23, '2010-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 20, 'Home Wreckers', 'When Ted attends his mother''s wedding, he is extremely disturbed by her overly affectionate relationship with her fiancé, which forces him to think about his own life and make an impulsive decision.', 23, '2010-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 21, 'Twin Beds', 'When Ted and Barney jeopardize Robin''s new relationship by professing their love for her, Robin realizes that she is finally over them. Meanwhile, after spending a weekend sleeping in twin beds, Marshall and Lily decide to get twin beds at home.', 23, '2010-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 22, 'Robots vs. Wrestlers', 'When Ted, Marshall, Lily and Barney crash a highfalutin party at a swanky New York apartment, Ted gets the chance to mingle with the snooty guests and show off his intellectual side.', 23, '2010-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 23, 'The Wedding Bride', 'When Ted takes a date to see a new hit movie, "The Wedding Bride," he is shocked to learn the story is loosely based on his life, and that it was written by Tony, the man Stella left him for at the altar.', 21, '2010-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 5), 24, 'Doppelgangers', 'Marshall and Lily make a secret pact to start trying to have a baby if they ever finally see Barney''s doppelganger. Meanwhile, Robin finally gets an offer for her dream job.', 23, '2010-05-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 6, 'Season 6', 'The more things change, the more things get interesting in this all-new hilarious season of How I Met Your Mother. Ted''s (Josh Radnor) search for "the one" continues while Marshall and Lily (Jason Segel and Alyson Hannigan) hope to become parents, Barney (Neil Patrick Harris) makes an uproariously awkward attempt to find his real father, and Robin (Cobie Smulders) finally feels like a true New Yorker. Featuring epic guest stars like Katy Perry and Jorge Garcia as "The Blitz," Season Six is filled with just plain awesomeness.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 1, 'Big Days', 'When Ted and Barney argue about who has "dibs" on a hot girl, Ted realizes that she is there with Cindy, a girl he previously dated who is also the roommate of his future wife. Meanwhile, Robin is heartbroken over Don, and Marshall can''t keep quiet about his desire to start a family.', 23, '2010-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 2, 'Cleaning House', 'When Barney convinces the gang to help his mom move out of her home, they quickly learn that she has been very protective of Barney and lied to him about events throughout his life. Meanwhile, Ted gets upset when Robin oversells him to a blind date.', 23, '2010-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 3, 'Unfinished', 'Barney uses his best womanizing tactics to try to convince Ted to design the new GNB building; Robin drunk dials Don.', 23, '2010-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 4, 'Subway Wars', 'When the gang teases Robin about not being a real New Yorker, she sets out to prove them wrong by racing to catch a glimpse of Woody Allen.', 23, '2010-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 5, 'Architect of Destruction', 'Ted becomes conflicted after meeting an attractive woman who is passionate about saving the landmark building being torn down for his new project.', 23, '2010-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 6, 'Baby Talk', 'Marshall and Lily try to figure out how to conceive a baby with the gender of their choice; Robin''s perky new co-anchor irritates her.', 23, '2010-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 7, 'Canning Randy', 'When Zoey enrolls in Ted''s class, she manipulates his students into taking her side in the fight to save the building being torn down to make room for his project. Meanwhile, Marshall and Lily spot Robin marching in the Halloween parade of shame.', 23, '2010-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 8, 'Natural History', 'When the gang goes to a black tie event at the Natural History Museum, Ted gets introduced to Zoey''s husband, The Captain.', 23, '2010-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 9, 'Glitter', 'Barney''s discovery of a Canadian kids show called Space Teens, that Robin appeared on as Robin Sparkles, leads the gang to get her to reach out to her co-star, Jessica Glitter.', 23, '2010-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 10, 'Blitzgiving', 'When Ted leaves the bar early to prepare a Thanksgiving feast for his friends, the gang winds up partying all night with The Blitz, an old friend from college who has bad luck. As a result Ted is forced to spend Thanksgiving with Zoey.', 23, '2010-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 11, 'The Mermaid Theory', 'When Ted''s new friendship with Zoey tests the theory that single men and married women can''t be friends, he invites her husband, "The Captain," to hang out with them. Meanwhile, Marshall and Robin decide to spend alone time together, and Barney and Lily possibly have a fight.', 23, '2010-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 12, 'False Positive', 'Lily and Marshall receive shocking news that has a profound impact on the gang. Ted begins his duties as best man for an old friend''s wedding.', 21, '2010-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 13, 'Bad News', 'Afraid they will never get pregnant, Lily and Marshall decide to see a specialist. Robin begins her new job.', 23, '2011-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 14, 'Last Words', 'While on a trip to Minnesota, Ted and Barney try anything to make Marshall laugh. Marshall runs into an old nemesis from high school.', 23, '2011-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 15, 'Oh Honey', 'Barney gets emotional when he opens up to Honey about his life. Ted admits to having feelings for Zoey to the group.', 23, '2011-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 16, 'Desperation Day', 'Barney declares February 13th a holiday for desperate women. Marshall receives a Valentine''s Day surprise from Lily. Zoey and Ted work on figuring out their relationship.', 23, '2011-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 17, 'Garbage Island', 'Marshall becomes obsessed with saving the environment after seeing a documentary on garbage. Ted runs into The Captain. Barney admits he has feelings for a woman.', 23, '2011-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 18, 'A Change of Heart', 'When Barney starts to have real feelings for Nora, he worries that something is wrong with his heart. Meanwhile, Robin starts dating a guy who acts a lot like a dog.', 21, '2011-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 19, 'Legendaddy', 'Barney meets his father and is shocked by the differences in their lives. The rest of the gang learn their "gaps"; knowledge they should have by now, but don''t.', 23, '2011-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 20, 'The Exploding Meatball Sub', 'Lily and Barney react badly when Marshall finally quits his job at Goliath National Bank to take a volunteer position at an environmental organization. Meanwhile, Ted and Zoey''s opposing positions on the future of the Arcadia come between them.', 23, '2011-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 21, 'Hopeless', 'When Barney tries to bond with his father, he asks the gang to help make his life seem more exciting by lying about their own lives. Meanwhile, Robin runs into a guy she has a crush on.', 23, '2011-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 22, 'The Perfect Cocktail', 'When Marshall and Barney argue over the destruction of the Arcadian Hotel, Robin and Lily try to mix the right combination of cocktails that will force them to make up. Meanwhile, Ted plans a romantic weekend away with Zoey.', 23, '2011-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 23, 'Landmarks', 'When Ted is faced with an important decision that might affect his future with Zoey, the gang expresses their true feelings about her.', 23, '2011-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 6), 24, 'Challenge Accepted', 'Robin and Barney bond when they intervene in Ted''s relationship, and Marshall and Lily watch a ticking clock as he fears that he soon will be the victim of food poisoning.', 23, '2011-05-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 7, 'Season 7', 'With both a baby and a wedding on the way, change is in the air and awesomeness abounds in the hilariously unpredictable Season Seven of How I Met Your Mother. As Marshall and Lily move away to start their family, Ted continues the search for the woman of his dreams. Meanwhile, Robin reveals a shocking secret and special guest star Katie Holmes joins the fun in the long-awaited return of the Slutty Pumpkin! And, wedding bells are ringing at last for confirmed bachelor Barney, but why is he wearing that ridiculous ducky tie, and just who is the "lucky" lady?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 1, 'The Best Man', 'While Barney prepares for his wedding to a mystery bride, he and Ted reminisce about Punchy''s wedding, including when Marshall and Lily announced they are having a baby. Meanwhile, Robin considers telling Barney she has feelings for him.', 23, '2011-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 2, 'The Naked Truth', 'Marshall gets a great job offer that he fears may be scuttled by a social media background check. Ted needs a date for the Architects Ball.', 23, '2011-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 3, 'Ducky Tie', 'Barney faces having to wear Marshall''s ducky tie if he loses a bet with him. Meanwhile, Ted hopes to apologize to an ex for cheating on her.', 23, '2011-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 4, 'The Stinson Missile Crisis', 'After Robin assaults a girl who is out to ruin Barney''s relationship, she is forced to begin court-mandated therapy sessions. Meanwhile, Ted gets too involved in Lily''s pregnancy.', 23, '2011-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 5, 'Field Trip', 'Marshall decides to step in after seeing his boss''s approach to settling with a million dollar company. Ted''s class trip isn''t what he envisioned.', 23, '2011-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 6, 'Mystery vs. History', 'When Ted goes on a date without researching the girl on the Internet, the gang interferes, showing Kevin that they are too into each other''s business. Meanwhile, Lily and Marshall come to terms with finding out the sex of their baby.', 23, '2011-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 7, 'Noretta', 'The gang begins to realize their romantic partner reminds them of one of their parents. Meanwhile, Barney and Nora''s planned romantic evening is ruined by a string of bad events.', 23, '2011-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 8, 'The Slutty Pumpkin Returns', 'Ted finally meets his mystery girl in the Slutty Pumpkin costume. Meanwhile, Barney learns he is part Canadian, and Lily has pregnancy brain.', 23, '2011-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 9, 'Disaster Averted', 'While the gang reminisces about Hurricane Irene, Barney tries to cut a deal with Marshall and Lily to get out of wearing the Ducky Tie.', 23, '2011-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 10, 'Tick Tick Tick', 'Barney and Robin are afraid to break the news to Nora and Kevin that they cheated with each other and want to get back together, while Ted and Marshall get stoned together at a concert.', 23, '2011-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 11, 'The Rebound Girl', 'Ted and Barney discuss making a life-changing decision together, and Robin tries to discourage Marshall and Lily from moving to Long Island.', 23, '2011-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 12, 'Symphony of Illumination', 'Robin receives bad news and decides to hide it from the gang. Marshall hangs Christmas decorations in his house in the suburbs with some help from his neighbor.', 23, '2011-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 13, 'Tailgate', 'After celebrating New Year''s Eve, Marshall visits his father''s graveside to carry on their tradition of tailgating. Meanwhile, Barney and Ted open a bar called "Puzzles," and Robin is forced to fill in for an inebriated news anchor.', 23, '2012-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 14, '46 Minutes', 'Lily and Marshall officially move to the suburbs and realize that Lily''s bossy father refuses to move out of their house. Meanwhile, the gang adjusts to them moving by going to a strip club.', 23, '2012-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 15, 'The Burning Beekeeper', 'Lily asks for her father''s help when she and Marshall decide to throw a housewarming party. Marshall''s boss gets under Ted''s skin and the two nearly come to blows, and Barney puts the moves on a wacky divorcée.', 20, '2012-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 16, 'The Drunk Train', 'Lily and Marshall invite Robin and Kevin on a Valentine''s Day trip to Vermont. Kevin and Robin use the trip to talk about taking their relationship to the next level. Meanwhile, Barney realizes he has finally met his match.', 23, '2012-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 17, 'No Pressure', 'When Robin breaks up with Kevin, Ted confesses his feelings to her. Meanwhile, Barney is on a mission to find something private of Marshall and Lily''s.', 23, '2012-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 18, 'Karma', 'Barney continues his pursuit of Quinn. Ted has to deal with Robin''s old room, while Robin gets a taste of suburban life from Marshall and Lily.', 23, '2012-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 19, 'The Broath', 'The gang tries to break up Barney and Quinn after learning they plan on moving in together, leaving Robin and Ted to fight over who deserves to sublet her apartment.', 23, '2012-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 20, 'Trilogy Time', 'Ted, Marshall and Barney embark on another "trilogy time", where they get together every three years to watch the "Star Wars" trilogy and envision what their lives will be like in another three years. Meanwhile Barney and Quinn move in together.', 23, '2012-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 21, 'Now We''re Even', 'Although Ted is happy with living alone at his new apartment, Barney tries to convince him about going out every night. Lily has a naughty dream about someone other than Marshall. Robin finally starts her stint as a news anchor at World Wide News.', 23, '2012-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 22, 'Good Crazy', 'Marshall panics when a baby shower indicates that the birth is close at hand and accidentally takes a road trip with Barney. Ted hallucinates seeing Robin while trying to get over her and decides to patch up their differences. Barney tries to talk Quinn out of being a stripper.', 23, '2012-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 23, 'The Magician''s Code (1)', 'When Lily goes into labor, Ted and Robin distract her by telling her stories while Marshall hurries back from Atlantic City.', 23, '2012-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 7), 24, 'The Magician''s Code (2)', 'Ted is conflicted when Victoria approaches him on her wedding day and asks him to elope. Meanwhile, Barney and Quinn are arrested by airport security while on the way to Hawaii when Barney refuses to open a box they are travelling with.', 23, '2012-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 8, 'Season 8', 'In the uproarious Eighth Season of How I Met Your Mother, the arrival of baby Marvin reminds Marshall and Lily of things they need, like sleep, better jobs and sex! Meanwhile Barney uses his playbook to win over Robin, but not her scary dad. Marshall tries to right a wrong in court in hopes of becoming a judge, and Robin''s past is judged. Ted designs an amazing building, and also has designs on Barney''s half-sister! But does he meet his future wife? Check out all hilarious, legend — wait for it — dary Season 8 episodes, featuring guest stars like Paul Shaffer, Ralph Macchio and Kyle MacLachlan!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 1, 'Farhampton', 'Robin''s anxiety on her wedding day to Barney prompts Ted to recount the time he insisted on leaving Victoria''s jilted fiancé a note before they drove off into the sunset together.', 23, '2012-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 2, 'The Pre-Nup', 'When Barney designs an extensive pre-nup, the guys take note and propose their own relationship amendments to their significant others. Meanwhile, Quinn is outraged and draws up a pre-nup of her own, which causes friction between the sexes.', 23, '2012-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 3, 'Nannies', 'When Lily and Marshall have trouble finding a nanny, they learn it''s because of an elaborate scheme Barney came up with to meet girls. Meanwhile, Robin and Ted butt heads over who has a more serious relationship.', 23, '2012-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 4, 'Who Wants to Be a Godparent?', 'When Lily and Marshall can''t decide on godparents for Marvin, they put the gang to the test to see who would make the best one.', 21, '2012-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 5, 'The Autumn of Break-Ups', 'As the season of break-ups continues, Ted and Victoria must choose the next step in their long and complicated relationship. Meanwhile, Robin worries about Barney when he chooses a dog to be his wingman.', 23, '2012-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 6, 'Splitsville', 'When Robin is hesitant to break up with Nick, Barney takes matters into his own hands. Meanwhile, Lily and Marshall are desperate for some private time.', 23, '2012-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 7, 'The Stamp Tramp', 'Marshall recommends his old law school classmate Brad for a job at his firm, but the interview goes awry, leaving Marshall to do damage control with his boss. Meanwhile, Robin helps negotiate Barney''s return to the strip club circuit.', 23, '2012-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 8, 'Twelve Horny Women', 'Marshall takes on his old friend/new nemesis Brad in the biggest case of his career. Meanwhile, the gang reminisces about their own run-ins with the law, leading to a debate over who was the biggest delinquent as a teenager.', 23, '2012-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 9, 'Lobster Crawl', 'Robin is determined to get Barney back no matter what it takes. Meanwhile, Ted fills in as Marvin''s Nanny, leading Marshall and Lily to realize that Ted is using baby Marvin to replace his other baby, the GNB building.', 23, '2012-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 10, 'The Over-Correction', 'Barney''s developing relationship with Patrice leaves Robin questioning his motives. Marshall''s widowed mother gets back into the dating pool, but he thinks she may be swimming with a shark.', 23, '2012-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 11, 'The Final Page (1)', 'Robin takes steps to have Patrice fired from WWN, while Marshall puts a jinx on Barney. Later, Ted invites his architecture professor to the dedication of the GNB building, and Marshall and Lily bump into an oddball acquaintance from college.', 23, '2012-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 12, 'The Final Page (2)', 'Christmas approaches and Ted wrestles with whether to tell Robin about Barney''s intentions involving Patrice, while Marshall and Lily get an early Yule gift, a night away from Marvin, but a case of separation anxiety strikes and threatens to ruin the evening.', 23, '2012-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 13, 'Band or DJ?', 'When Robin learns that Barney never asked her father''s permission before proposing, she insists that he seek his approval before announcing their engagement. Meanwhile, Ted keeps his feelings concealed by throwing himself into planning their wedding.', 21, '2013-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 14, 'Ring Up!', 'Barney begs Ted to continue seeing his much younger, much wilder girlfriend, even though Ted has nothing in common with her. Meanwhile, Robin must adjust to the power of the bling.', 23, '2013-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 15, 'P.S. I Love You', 'Barney uncovers the lost episode of Robin''s “Underneath the Tunes” as Robin Sparkles. Meanwhile, Marshall and Lily are concerned that Ted''s new girlfriend is a stalker.', 23, '2013-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 16, 'Bad Crazy', 'Ted is reluctant to break up with his crazy girlfriend Jeanette. Meanwhile, Robin becomes attached to Marvin after finally holding him for the first time.', 23, '2013-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 17, 'The Ashtray', 'When Ted receives an unexpected call from The Captain, the gang reminisced about their last awkward encounter with him.', 23, '2013-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 18, 'Weekend at Barney''s', 'Barney''s legendary relationship playbook, which Robin thought was destroyed, rears its head when Ted and Jeanette break up and Barney decides to use his chick manual to help Ted find a new girlfriend.', 23, '2013-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 19, 'The Fortress', 'Barney reluctantly attempts to sell his apartment by holding an open house, during which Ted and Marshall get mistaken for a couple. Tension arises between Lily and Marshall when her new job causes her to spend less time at home.', 23, '2013-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 20, 'The Time Travelers', 'Ted and Barney''s future versions attempt to persuade present day Ted to go see Robots Versus Wrestlers. Marshall and Robin have a dance-off.', 23, '2013-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 21, 'Romeward Bound', 'When The Captain asks Lily to move to Rome for a year as his art consultant, she fears that Marshall will resent her. Meanwhile, Ted and Barney become obsessed with a girl who is hiding her amazing body under a puffy coat.', 21, '2013-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 22, 'The Bro Mitzvah', 'The gang works together to plan a legendary bachelor party for Barney.', 21, '2013-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 23, 'Something Old', 'Robin desperately tries to locate the item that she buried in Central Park years earlier to wear as her "Something Old" for the wedding. Meanwhile, Marshall and Lily ask Ted to help them pack for Italy, and Barney invites Robin''s father to play Laser Tag in order to bond with him.', 21, '2013-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 8), 24, 'Something New', 'As the gang prepares to go to Robin and Barney''s wedding, Ted invites Lily to see the house he''s finally finished fixing up. Meanwhile, Robin and Barney''s night of relaxation is ruined by an obnoxious couple, and Marshall takes the baby on a last-minute trip to Minnesota to see his family.', 23, '2013-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')), 9, 'Season 9', 'Suit up and give one last high-five for the legend — wait for it — dary final season of How I Met Your Mother. Surprising answers to hilarious questions will be revealed during one epic wedding weekend. Can Marshall complete a cross-country road trip and make it to the ceremony? Will Robin and Barney really tie the knot? Is Lily hiding a shocking secret? Will Ted finally meet the mother of his children... and is she truly "the one"? It all builds to a climactic two-part series finale, leading to one of the most talked about endings in TV history.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 1, 'The Locket', 'On their way to Long Island for their wedding weekend, Robin and Barney come across a startling family discovery. Meanwhile, Marshall sees something online that changes the course of his journey east, while Lily confronts Ted about letting go of Robin.', 22, '2013-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 2, 'Coming Back', 'When James reveals that he is getting divorced, Robin worries about how Barney will take the news. Meanwhile, Marshall races to find a way to get to New York in time for the wedding, and Ted deals with being alone at a romantic hotel.', 21, '2013-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 3, 'Last Time in New York', 'When Lily discovers Ted''s list of things he wants to do in New York before he moves for Chicago, she becomes frustrated that she is the only person who knows about his plans. Meanwhile, Robin and Barney realize they have very little time together before their relatives arrive for their wedding.', 23, '2013-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 4, 'The Broken Code', 'While Barney works through his anger at Ted after finding out he still has feelings for Robin, Marshall Skypes in to act as a judge and help settle their dispute. Meanwhile, Lily realizes she is Robin''s only girlfriend.', 23, '2013-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 5, 'The Poker Game', 'Barney is upset after Robin wins James''s wedding ring during the poker game, and Ted argues with Marshall and Lily over whether he gave them a wedding gift.', 23, '2013-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 6, 'Knight Vision', 'When Ted finds himself with three prospects to be his date for the wedding weekend, he chooses poorly. Meanwhile, Barney and Robin have a confrontation with their minister, and Marshall learns more about his driving companion, Daphne.', 23, '2013-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 7, 'No Questions Asked', 'When Daphne sends a troubling text message to Lily, Marshall enlists the gang''s help to remove the message while enforcing the "No Questions Asked" rule.', 23, '2013-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 8, 'The Lighthouse', 'When Robin and Loretta''s conflict escalates, Barney is caught in the middle. Meanwhile, Marshall and Daphne deal with a stowaway on their road trip, and Ted and Cassie try to enjoy a trip to a lighthouse.', 23, '2013-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 9, 'Platonish', 'During a flashback, the gang wonders how the Ted, Robin and Barney love triangle will play out; Barney accepts challenges from Robin and Lily.', 23, '2013-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 10, 'Mom and Dad', 'Barney concocts a plan when his father arrives at the hotel; Ted thinks he is being framed when a wedding-related duty gets messed up.', 23, '2013-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 11, 'Bedtime Stories', 'Marshall tries to get Marvin to sleep by reciting rhyming bedtime stories.', 21, '2013-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 12, 'The Rehearsal Dinner', 'Robin is dismayed when Barney wants to have their rehearsal dinner at a laser tag arena; Ted aggravates Lily by not following through with a promise.', 21, '2013-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 13, 'Bass Player Wanted', 'A man at the wedding intentionally stirs up trouble; Marshall finally arrives at the Farhampton Inn.', 23, '2013-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 14, 'Slapsgiving 3: Slappointment in Slapmarra', 'In an attempt to deliver a devastating final slap to Barney, Marshall explains how he mastered the Slap of A Million Exploding Suns.', 23, '2014-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 15, 'Unpause', 'Robin and Ted try to get Barney to reveal secrets after he drinks too much; Marshall tries to avoid fighting with Lily.', 23, '2014-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 16, 'How Your Mother Met Me', 'The mother reveals how she met Ted and what she has been doing over the past eight years.', 24, '2014-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 17, 'Sunrise', 'Robin and Ted reminisce about past relationships as they search for a drunken Barney on the day of the wedding; Lily and Marshall come to a resolution; Barney befriends two men who are eager to meet women.', 23, '2014-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 18, 'Rally', 'The gang must figure out how to make the Stinson Hangover Fixer Elixir to help Barney recover on the day of the wedding.', 21, '2014-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 19, 'Vesuvius', 'Robin and Lily have a fight on the morning of the wedding; Barney can''t decide what suit to wear; the gang watches a movie that Ted didn''t want them to see.', 23, '2014-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 20, 'Daisy', 'Marshall asks Barney and Ted for help figuring out where Lily went in the middle of the night during their argument.', 23, '2014-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 21, 'Gary Blauman', 'When Gary Blauman shows up at the wedding, it sends the gang into a frenzy as they each recall an encounter with him.', 23, '2014-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460649')) AND numero_temporada = 9), 22, 'The End of the Aisle', 'With only a half an hour left before the wedding, Robin and Barney panic; Lily and Marshall rewrite their wedding vows.', 23, '2014-03-24');
