INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 9), 22, 'The Nail in the Coffin', 'When the remains of a woman from a wealthy family are found in a national park, the team thinks she may be a victim of the Ghost Killer; Booth''s career might be in for some changes.', 44, '2014-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 9), 23, 'The Drama in the Queen', 'When the head swim coach of a community college is found dead at the bottom of the well, possible suspects think he may have been having an affair; Sweets covers for Booth in the investigation as Booth prepares for a congressional subcommittee.', 44, '2014-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 9), 24, 'The Recluse in the Recliner', 'The team investigates the death of a man who had offered Booth information on a possible government cover-up related to a previous case, but was killed before their meeting took place. As Booth and the Jeffersonian team dig deeper into the burgeoning conspiracy surrounding the man’s death, it’s evident Booth may be in over his head, and his future with the FBI is put in question.', 44, '2014-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')), 10, 'Season 10', 'After tragedy strikes, the team must regroup and heal. With shifting alliances and major life changes, they face one of their biggest threats yet.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 1, 'The Conspiracy in the Corpse', 'Brennan and the team attempt to absolve Booth and get him released from prison. The remains of a man who has been dead for over sixteen years prove to be significant.', 44, '2014-09-25');
