INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 4, 'The Geek in the Guck', 'The investigation of the murder of a video-game designer reveals the wealth he accumulated during his career, which makes a suspect out of everyone who was in his inner circle. Meanwhile, "squintern" Jessica sheds light on an educational opportunity; and Brennan and Booth discuss Christine''s future.', 44, '2014-10-16');
