INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 7, 'The Money Maker on the Merry-Go-Round', 'The team investigate a billion dollar hedge fund company when severely damaged remains from human''s are found under a merry go round.', 44, '2014-11-13');
