INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 10, 'The 200th in the 10th', 'Paying homage to Alfred Hitchcock in an episode that reimagines the Jeffersonian and FBI teams in 1950s Hollywood. Brennan plays an LAPD detective who''s battling sexism on the force, and Booth is a notorious jewel thief who is far more than he seems to be. When Booth is framed for the murder of a rich socialite, he and Brennan team up to clear his name and find the true identity of the murderer.', 44, '2014-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 11, 'The Psychic in the Soup', 'Angela’s psychic friend is enlisted when the body of a local psychic is found.', 44, '2015-03-26');
