INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 15, 'The Eye in the Sky', 'Booth and Brennan work undercover as they become involved in the world of underground poker.', 44, '2015-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 16, 'The Big Beef at the Royal Diner', 'The team are called in after the remains of a celebrity chef are found in a local park.', 44, '2015-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 17, 'The Lost in the Found', 'Brennan and Booth believe that bullying is behind the death of a private high school student.', 44, '2015-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 18, 'The Verdict in the Victims', 'The team attempt to find evidence that Alex Rockwell did not commit the crimes of which he was convicted for.', 44, '2015-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 19, 'The Murder in the Middle East', 'The team must race against the clock to expose the killer of the son of a powerful diplomat.', 44, '2015-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 20, 'The Woman in the Whirlpool', 'A well-known cookie jar collector''s body is found on a riverbank.', 44, '2015-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 21, 'The Life in the Light', 'The team take a look into the death of an ex-con who has become a yoga instructor.', 44, '2015-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 10), 22, 'The Next in the Last', 'When the Jeffersonian team discovers remains of a victim, and elements of the crime scene point to a possible protege of serial killer Christopher Pelant, they must revisit their prior work on Pelant while tracing new clues that will hopefully lead them to the copycat killer. Meanwhile, Angela is skeptical about her and Hodgins decision to move to Paris and Brennan and Booth contemplate options outside of the Jeffersonian and FBI.', 44, '2015-06-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')), 11, 'Season 11', 'New agents join the team as Booth and Brennan grapple with past decisions. Mysterious disappearances and shocking twists reshape their future.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 1, 'The Loyalty in the Lie', 'Booth goes missing six months after he and Brennan left their careers behind, but a case with ties to the couple pulls Brennan back into the world of forensic analysis, which brings her into contact with a member of Booth''s family and Arastoo Vaziri, who''s taken the lead at the Jeffersonian in her absence. Meanwhile, the FBI investigate Booth''s disappearance, but one agent''s tactics are bad for the team''s morale.', 44, '2015-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 2, 'The Brother in the Basement', 'Booth is still missing, but the team learns that Agent Miller has hidden information about his whereabouts and physical state. Meanwhile, a digital forensic scientist helps Angela try to decipher information pertaining to Booth''s location and the circumstances of his disappearance; and Arastoo makes a decision that will change his and Cam''s personal and professional relationships.', 44, '2015-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 3, 'The Donor in the Drink', 'On Brennan and Booth’s first official day back at their respective positions at the Jeffersonian and the FBI, things get exciting when remains are found at a fish farm under suspicious conditions, prompting them to investigate. After it’s discovered that someone harvested several of the victim’s internal organs before he was dumped in the water, Angela tracks down the seller and buyer of the organs to try to uncover important details in the case. Meanwhile, Booth readjusts to his position back at the FBI and discovers Aubrey has taken over his old office; Hodgins pushes Angela to showcase her photography work; and Cam struggles with her decision to choose work over her relationship with Arastoo.', 44, '2015-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 4, 'The Carpals in the Coy-Wolves', 'When remains of real estate agent Justin Ross are discovered in a forest and appear to have been destroyed by coyote-wolf hybrids, Brennan enlists the help of fellow brilliant forensic anthropologist Dr. Beth Mayer to assist in the investigation. In addition to her professional achievements, Mayer is surprisingly knowledgeable about the world of fantasy football, a key link to Ross’ past and one that could provide vital information in finding his killer. As Booth and Aubrey dig into Ross’ fantasy football league history, they discover he was actively involved in a Twitter feud with NFL star Lou Divers, and was also owed a large sum of money from the league’s commissioner, making each of them suspects. Meanwhile, Brennan resists feeling competitive as Mayer impresses the team with her expertise and decades of accomplishments.', 44, '2015-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 5, 'The Resurrection in the Remains (I)', 'It’s Halloween time at The Jeffersonian as the team gets a surprise visit from Lt. Abbie Mills and Ichabod Crane, who have traveled from the spooky town of Sleepy Hollow to help on a murder case of a young woman whose body is found on top of a 18th century military general’s headless body. The new foursome must figure out how to work together to discover who the 200-year-old headless corpse is and how the two murders are linked. Meanwhile, Booth and Brennan come up with the ultimate Halloween pranks to play on each other. 
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 6, 'The Senator in the Street Sweeper', 'A pair of funny sanitation workers discover the shredded body of a U.S. Senator in a street sweeper, which leads Brennan, Booth and the team to Capitol Hill, where they meet with U.S. Senator and majority whip Hayley Winters and the victim''s chief of staff Eric Morales to get to the bottom of this political murder. Meanwhile, as Aubrey starts to develop a relationship with squintern Jessica, he looks into her past to make sure nothing will harm his dream of a future in politics', 44, '2015-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 7, 'The Promise in the Palace', 'The team investigates the murder of an escape artist whose body is found in the woods. They discover that the victim worked at the Magic Palace, and had some secret activities in the works that might have made him enemies in the magic community. Meanwhile, Brennan and Booth poll their friends as to whether or not the tooth fairy should visit Christine, and Angela continues to work with Sebastian Kohl on her photography.', 44, '2015-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 8, 'High Treason in the Holiday Season', 'The team investigates the high-stakes murder of a political journalist who was found dead after recently publishing an article exposing corruption in the NSA. Due to the nature of the investigation, Hodgins’ paranoia takes over as the team realizes their every move is being watched. Meanwhile, Brennan secretly tries to plan a surprise for Booth and the whole team celebrates Thanksgiving together.', 44, '2015-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 9, 'The Cowboy in the Contest', 'Booth and Brennan go under cover at an Old West-style shooting competition; Angela and Hodgins talk about the future; Cam and Sebastian grow closer.', 44, '2015-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 10, 'The Doom in the Boom', 'The team investigates a police officer''s murder and decides what is important to their futures.', 44, '2015-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 11, 'The Death in the Defense', 'Hodgins is eight weeks into his rehabilitation for his paralysis and forced to navigate life in a wheelchair. Meanwhile, Brennan and Booth investigate the death of a public defender who had multiple defendants from previous cases with motives to kill her.', 44, '2016-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 12, 'The Murder of the Meninist', 'The team investigates a body found in a car crash, the remains of which belong to a founder of a men''s rights organization who may have been the victim of domestic abuse. As Brennan learns more about the tenets of the victim''s organization, which claims middle-aged white men are oppressed and feminists are man-haters, Brennan uncharacteristically loses her cool during an interrogation and assaults the organization''s co-founder. Meanwhile, Angela and the team struggle to deal with Hodgins post-wheelchair bitterness and Booth is convinced Brennan is a jinx for the Philadelphia Flyers.', 44, '2016-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 13, 'The Monster in the Closet', 'The Jeffersonian investigates the decomposing body of a social worker in the park, but evidence suggests the killer lived with the body for months before dumping it. Things get even more complicated when they determine another set of remains has similar details, which link the victims to a serial murderer who had sinister interactions with his victims'' bodies. Booth and Aubrey consult with behavioral analyst Karen Delfs to help with clues to the killer''s identity, while Cam tries to determine what (and who) she wants in her romantic life.', 44, '2016-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 14, 'The Last Shot at a Second Chance', 'The Jeffersonian investigates the murder of a convicted felon who had been released to a halfway house, but disappeared, and a suspect in the case has ties to Booth. Meanwhile, Brennan testifies at an FBI hearing about the circumstances regarding her assault of an unarmed suspect from a previous case, and the outcome of the hearing could lead to her suspension and prevent her from working with the FBI. Aubrey and Jessica’s first kiss is delayed again and Hodgins continues to push Angela away.', 44, '2016-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 15, 'The Fight in the Fixer', 'The team investigates the body of a private investigator who was found frozen in ice, after being dumped in the Potomac. The victim, a man with many enemies, was a "fixer" who made sure his clients'' problems got "resolved." Meanwhile, Aubrey is shocked to find information tied to his father''s whereabouts, Angela and Hodgins continue to work on their rocky relationship, Brennan and Booth get Christine''s first report card and criminal behaviorist Karen Delfs asks Aubrey out on a date.', 44, '2016-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 16, 'The Strike in the Chord', 'The team investigates the death of the leader of the Lynwood University male acapella singing group, "The Whippersnaps," whose body was found in the school rat lab. The victim recently kicked out Ian Jansen, one of the group''s best singers, sending Booth and Aubrey to question Ian and other current members of the male group and some stars of the competing female acapella group to get a handle on the group dynamics and what could have led to the murder of one of their own. Meanwhile, surprising information about Aubrey''s own college experience is brought to light, Hodgins applies for an experimental nerve regeneration study, Booth tries to plan a summer trip with Parker and a new intern joins the Jeffersonian lab.', 44, '2016-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 17, 'The Secret in the Service', 'A drunk college student discovers the dead body of a Secret Service agent just before a presidential visit to the area. Booth is ready to hit the ground running and turns to Secret Service agent and former colleague Brandt Walker for information, but is surprised to learn the Secret Service has reservations about Booth’s involvement in the case. The team uncovers some shocking evidence that heightens the seriousness of the case, causing Booth to step up for his country. Meanwhile, Brennan is out sick with the flu and former intern Dr. Colin Fisher returns to the Jeffersonian to run lead on the case, but Brennan refuses to be kept out of the loop. Also, Hodgins takes his life into his own hands and turns a corner after a potentially dangerous experiment.', 44, '2016-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 18, 'The Movie in the Making', 'To produce a television segment on the Jeffersonian’s Medico-Legal lab, a documentary crew follows Brennan, Booth and the Jeffersonian/FBI team on a “typical” case as they investigate a corpse found in a landfill that was buried there more than a decade ago. The camera captures normally unseen footage of the team at work, while candid commentary by each of the team members provides an inside look at the investigation as Booth and Aubrey show off their unique skills in the field, and Brennan and her team prove their expertise and integral importance to solving murder cases.', 44, '2016-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 19, 'The Head in the Abutment', 'The team investigates the death of a popular professional hockey player whose headless corpse was dumped in the river. As Booth and Aubrey question the player''s coach, Booth''s depth of hockey knowledge is integral to solving the case, and he''s reunited with a hockey rival from his past, putting him back on the ice once again to face off against him. Meanwhile, Hodgins and Oliver have a competition of their own when Hodgins builds two drones and they compete to retrieve the victim''s missing head, and Booth and Brennan attempt to declutter their home.', 44, '2016-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 20, 'The Stiff in the Cliff', 'When the remains of famous billionaire explorer Henry Charles are found in Antarctica, the high profile case is brought to Brennan and Booth to determine if his death was a murder. The Jeffersonian team confirms he was killed when he went missing ten years ago on an expedition, but the timeframe puts the Jeffersonian''s Dr. Clark Edison, who was with Charles for the expedition, on the short list of suspects. Meanwhile, Cam''s sister comes into town to help with wedding plans and old family friction comes into the picture.', 44, '2016-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 21, 'The Jewel in the Crown', 'The team investigates a body found at a glass recycling plant with a diamond lodged in its jaw. French Inspector Rousseau approaches the team with an accusation against the Marquis De Chaussin, who is revealed to be the victim''s husband and lives in Virginia. Meanwhile, Booth discovers he suffers from a temporary eye illness, and Hodgins thinks he''s being followed by a ghost.', 44, '2016-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 11), 22, 'The Nightmare Within the Nightmare', 'The team dives back into investigating a serial killer from the past, attempting to find “The Puppeteer,” who lives with his victims’ bodies before disposing of them. Meanwhile, Brennan works through her guilt over her retirement last year, blaming herself for not stopping the serial killer earlier. However, little does she know she might be in some trouble of her own.', 44, '2016-07-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')), 12, 'Season 12 - The Final Chapter', 'The final chapter brings old enemies and unresolved mysteries to the forefront. As the team fights to protect each other, they must confront what they’ve become—and what lies ahead.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 1, 'The Hope in the Horror', 'Booth and the rest of the lab desperately search for Brennan who was kidnapped by her former assistant, Zack Addy. Brennan''s rescue is, however, just the beginning of their problems.', 44, '2017-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 2, 'The Brain in the Bot', 'After discovering the body of a man involved with creating artificial intelligence bots, the team must figure out whether the victim''s own A.I. bot was programmed to kill him. In the meantime, Bones plans a special surprise for everyone for her 40th birthday.', 44, '2017-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 3, 'The New Tricks in the Old Dogs', 'When the body of an old man is found in an acid dump site, the team becomes enmeshed in retirement home drama. As they explore the case, talk of marriage and kids begins to dominate the conversation back at the lab.', 44, '2017-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 4, 'The Price for the Past', 'The team investigates the murder of someone from Booth and Brennan''s past. Meanwhile, Aubrey faces a moral dilemma of his own when he discovers his dad is back in the picture.', 44, '2017-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 5, 'The Tutor in the Tussle', 'When a tutor of privileged students turns up dead, the team sorts through all the possible perpetrators, from disgruntled parents to the tutor''s roommate with a criminal record. Meanwhile, Bones is frustrated with the voice of her audio book and tries to prove that she can record it herself.', 44, '2017-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 6, 'The Flaw in the Saw', 'The dismembered body of successful golfer-turned-lumberjack Phyllis Paul brings the squints to the Lumber Sports Regional Championships. At this competition, Booth and Brennan discover numerous secrets that could have resulted in Phyllis'' murder, including an affair with a married rival. Meanwhile, Hodgins secretly analyzes the bacteria on the bone of a prior victim that he believes will exonerate Zack.', 44, '2017-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 7, 'The Scare in the Score', 'When a series of corpses with ties to Booth''s former Army unit appear around D.C., Booth must dive into his past to find the killer before the killer finds Booth. Meanwhile, Brennan''s father, Max, hides a serious medical procedure from Brennan, leaving her to grapple with her father''s trust and mortality, as well as her family being in danger.', 44, '2017-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 8, 'The Grief and the Girl', 'A recent loss creates a rift between Booth and Brennan, as they deal with their grief in different ways. Meanwhile, an old flame from Brennan''s past comes to visit.', 44, '2017-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 9, 'The Steal in the Wheels', 'When a young man dies in a horrendous hay baler accident, Booth, Brennan and Aubrey slap on trashy disguises and go undercover at a rowdy demolition derby competition to investigate the case. Meanwhile, Dr. Gordon Wyatt returns and assists Hodgins and Cam when the ongoing Gormogon case hits a dead end.', 44, '2017-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 10, 'The Radioactive Panthers in the Party', 'When the burning, bruised body of an aspiring writer/director crash-lands onto a passing car, the team investigates a series of odd locations and characters that are connected to his film. Meanwhile, Bones seeks guidance from Dr. Mayer on the meaning of passion in the work place and Booth allows Aubrey to take the reins on their current case.', 44, '2017-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 11, 'The Day in the Life', 'Brennan testifies for Zach in trial, Angela reveals some big news, while Aubrey and Jessica come to terms about their future together. All the while, the team discovers Kovac has escaped, leaving Booth in a race against the clock to protect himself and those closest to him from what may be Kovac''s most dangerous plan yet.', 44, '2017-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460627')) AND numero_temporada = 12), 12, 'The End in the End', 'With Kovac still at large, the team searches for evidence to track him down. After Brennan experiences a setback, the rest of the team must figure out how to find Kovac without her, putting everything she has ever taught them to the test. When all signs point to Kovac having outside help, as well as a hideout, Booth and Brennan go searching for him.', 44, '2017-03-28');
