INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 1, 'Season 1', 'The Creepy. The Demented. The Unexplained. The Unearthly. Sam Winchester grew up hunting such terrifying things. But that’s all past. Law school beckons him. So does safety and normalcy. That is, until Sam’s estranged brother Dean appears with troubling news: their father has disappeared, a man who’s hunted evil for 22 years. So to find their father, the brothers must hunt what their father hunts…and Sam must return to the life he’d rather leave behind.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 1, 'Pilot', 'Two brothers, Sam and Dean Winchester,  witness their mother''s paranormal death as children and grow up trained  to fight by a distraught father who wants nothing more then to hunt  down the thing that killed his wife. Sam escapes to college to start a  new, normal life, but gets pulled back in after Dean shows up on his  doorstep to tell him their father is missing.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 2, 'Wendigo', 'Sam and Dean follow the coordinates  left in their father''s journal and land in the middle of the woods where  they investigate the disappearance of several campers. The two brothers  soon learn they are dealing with a Wendigo, a creature made famous in  Native America legends. A Wendigo is a former human whose cannibalism  has transformed him into a creature with superhuman strength and speed  that feasts on human flesh.', 43, '2005-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 3, 'Dead in the Water', 'Sam and Dean investigate a series of  mysterious drownings written off as suicides. They discover the spirit  is an angry little boy with the power to travel through water who is  taking revenge on certain town inhabitants for a dark secret buried long  ago. Dean forms a bond with a young boy who seems to have the power of  premonition.', 43, '2005-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 4, 'Phantom Traveler', 'On TransNational flight 2485, a man possessed by the spirit of the  Phantom Traveler causes the plane to crash, leaving only five survivors  left alive. Sam and Dean must exorcise  the angry spirit before it attacks the survivors. The brothers realize  the only way to do that is to take the battle to the skies.', 42, '2005-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 5, 'Bloody Mary', 'In suburban Nebraska, a group of partying high school teens jokingly  dare their friend Charlie to look into  the mirror and repeat "Bloody Mary, Bloody Mary, Bloody Mary," not  knowing this will unleash a series of mysterious murders. Sam and Dean realize that Bloody Mary has the  power to travel through all reflective surfaces when she is hunting a  victim. Worried that teens are accidentally summoning Bloody Mary, Sam  and Dean race to destroy the violent spirit before she can kill again.', 43, '2005-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 6, 'Skin', 'Sam and Dean come to the aid of Sam''s  old college buddy after he is accused of a murder he swears he didn''t  commit. The brothers discover a shapeshifter is adopting the likenesses  of others and murdering people. The brothers'' race to stop the  shapeshifter takes a terrifying turn when he shifts into the likeness of  Dean.', 42, '2005-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 7, 'Hook Man', 'The infamous "Hook Man," a vengeful spirit who kills his victims with a shiny hook that serves as his hand, terrorizes a small college town in Iowa. Sam and Dean learn that all the victims are connected to the daughter of a local minister and race to find and destroy the Hook Man''s bones before he comes for them.', 40, '2005-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 8, 'Bugs', 'After a construction worker is killed by insects burrowing into his  brain, Sam and Dean investigate the  town''s history and find that the new housing development is being built  on sacred Indian land. The Indians put a curse on the land after their  reservation had been ravished and destroyed. Sam and Dean must find a  way to survive and kill the deadly swarm of bees, locusts, spiders and  beetles.', 43, '2005-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 9, 'Home', 'Sam is haunted by a vision of a woman trapped in his  childhood house and convinces a reluctant Dean that they  need to go home. Upon arrival, they meet the woman in Sam''s premonition  and she reveals that the house is haunted. Looking into their personal  history, the brothers discover their father had visited a psychic after their mother''s  death and they turn to the same woman for answers of their own.  Together they discover a malevolent poltergeist has inhabited the house  and set out to exorcise it, but are blindsided when another unseen  spirit steps in.', 43, '2005-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 10, 'Asylum', 'Sam and Dean investigate an abandoned  sanitarium and discover that when the hospital was open, the patients  held a revolt against the cruel and unusual punishments inflicted by the  head doctor. While the brothers search the premises for four lost  college students, the tortured spirits cause them to go insane, turning  Dean against Sam.', 43, '2005-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 11, 'Scarecrow', 'Sam and Dean finally make contact with their father,  but he tells them to stop looking for him and sends them on another  ghost-hunting job. Frustrated with their father''s evasiveness, Sam sets  out alone to find him while Dean stays back to obey his father. Dean  investigates a small town in Indiana where couples have gone missing the  same day each year and discovers the farmers are sacrificing them to a  Pagan God who takes the form of a scarecrow.', 43, '2006-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 12, 'Faith', 'While battling a demon, Dean is electrocuted, resulting  in permanent damage to his heart and leaving him with only a couple of  months to live. A despondent Sam searches desperately  for a way to save his brother and believes he may have found an answer  through a preacher who claims to heal the incurable. However, Dean and  Sam discover that the preacher is getting help from the Grim Reaper who  is trading one life for another he feels is less worthy.', 43, '2006-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 13, 'Route 666', 'Dean is contacted by his first love Cassie, an African-America girl, who asks him to come to  Mississippi to investigate a string of racially motivated murders. Each  murder is linked to a mysterious truck that seems to have no driver and  leave no tracks. Sam is stunned to see this new side  of his brother as Dean struggles to come to grips with the residual  feelings he has for Cassie.', 40, '2006-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 14, 'Nightmare', 'Sam has a premonition in which a man is killed, but  the murder is made to look like a suicide. Sam convinces Dean that they must investigate the case, but the two are puzzled  when they fail to find anything that indicates that the death was  supernatural in nature. That is, until they find out that Max, the reclusive son of the first victim, has been using his  recently acquired power of telekinesis to kill the family members that  once abused him. Sam also discovers Max''s mother was killed by the same  fiery demon that took his own mom.', 43, '2006-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 15, 'The Benders', 'Sam and Dean head to Minnesota where a  young boy witnesses a man vanish into thin  air. Upon searching for clues, Sam is abducted by what he assumes is a  supernatural being, and Dean is left to search frantically for his  brother. However, both are stunned when they realize the kidnappers are  human, and using the captives as human prey for a twisted hunting  expedition.', 43, '2006-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 16, 'Shadow', 'Sam has a reunion with a girl he once met, Meg, but it turns out that she is using the brothers to lure their father John to his doom.', 42, '2006-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 17, 'Hell House', 'Sam and Dean investigate the case of a maniacal ghost inhabiting a long abandoned Texas farmhouse known as "Hell House." They believe the ghost is the spirit of a deceased Depression-era farmer who killed his family, but they soon realize it is something far more powerful.', 41, '2006-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 18, 'Something Wicked', 'Sam and Dean battle a Shtriga, a witch that sneaks into childrens'' bedrooms and sucks the lives out of them. Dean must relive his childhood when he remembers that he encountered the Shtriga years ago.', 42, '2006-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 19, 'Provenance', 'The Winchesters must deal with a dangerous spirit bound to an old family portrait that brings misfortune and death to anyone who buys it.', 43, '2006-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 20, 'Dead Man''s Blood', 'To obtain a mystic gun capable of destroying the demon that killed their mother, Sam and Dean must team up with their father John and face off against vampires.', 42, '2006-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 21, 'Salvation', 'John has realized where the demon will strike next and the Winchesters head there to stop the next killing. But Meg begins killing John''s friends and demands the Colt or she''ll keep going until everyone John knows is dead.', 41, '2006-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 1), 22, 'Devil''s Trap', 'When Meg boasts that John is her prisoner, the boys visit a friend of their father''s to get information about demonic possessions and ways to trap a demon. It turns out Meg is not what she appears.', 43, '2006-05-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 2, 'Season 2', 'They''re back the ghouls and vampires, the ghosts and spirits and even more terrifying entities. And wherever these evil beings are, you''ll find brothers Sam and Dean Winchester, hunters on the trail of the demon who murdered their mother…and of any other unholy agent of the Supernatural. Join the brothers in their mind-bending, bone-chilling Season 2 road trip across America a journey deeper into the mystery of their own destinies.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 1, 'In My Time of Dying', 'In the aftermath of the car crash, the surviving Winchesters go to the hospital, where one is stalked by a Reaper while another must consider sacrificing himself to save the others.', 42, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 2, 'Everybody Loves a Clown', 'After the events at the hospital, the brothers have no idea where the demon that killed their mother is hiding. While biding their time trying to come up with an idea, they investigate murders committed by a killer clown.', 42, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 3, 'Bloodlust', 'Sam and Dean encounter a vampire hunter whose obsession may get them all killed.', 43, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 4, 'Children Shouldn''t Play With Dead Things', 'Dean and Sam investigate the death of a young college student who died in a car accident, but whose grave is now surrounded by a circle of dead plants.', 42, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 5, 'Simon Said', 'Sam and Dean meet Andy Gallagher, a slacker with psychic powers of persuasion. Once the brothers learn that Andy’s family was visited by the Demon, Sam wonders if he could be one of the special children.', 40, '2006-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 6, 'No Exit', 'Sam and Dean investigate the slayings of blonde women and find that the ghost of the first known serial killer in US history is responsible. Jo disobeys Ellen''s wishes and follows them along, and is captured by the ghost.', 41, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 7, 'The Usual Suspects', 'Sam and Dean investigate the murder of a lawyer and his wife, who claimed to have seen a ghost before they were killed. However, local authorities arrest the Winchesters after looking into their past.', 42, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 8, 'Crossroad Blues', 'Dean calls a demon to make a deal to save a man named Evan Hudson, in exchange for himself. While making the deal, the demon confronts Dean’s worst nightmare about their dad.', 42, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 9, 'Croatoan', 'Sam has a vision of Dean shooting a defenseless man, and they go to the town of River Grove, where they find the townspeople have been possessed by a virus that makes them violent.', 41, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 10, 'Hunted', 'Sam meets a woman who shares his ability to have visions, and she warns him that she has seen the future... where he dies in an explosion.', 42, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 11, 'Playthings', 'Sam and Dean investigate an Connecticut inn run by a single mother where mysterious deaths are taking place. They find evidence of Hoodoo, and try to figure out who is causing the chaos.', 39, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 12, 'Nightshifter', 'The Winchesters investigate a series of crimes where robbers with no criminal past commit suicide after the hold-ups.', 41, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 13, 'Houses of the Holy', 'An angel causes people to cheerfully go out to murder, and when the Winchesters investigate one of them falls under its sway.', 41, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 14, 'Born Under a Bad Sign', 'Sam contacts Dean after being missing for a week. When they reunite, Dean finds Sam covered in blood and with no recollection of what happened.', 43, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 15, 'Tall Tales', 'The Winchester brothers seek the help of their family friend Bobby while investigating a series of unexplained happenings on a local college campus.', 39, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 16, 'Roadkill', 'A fatal automobile accident from 1992 leaves an angry apparition haunting a remote stretch of highway, and Sam and Dean try to lay it to rest.', 40, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 17, 'Heart', 'Sam and Dean investigate a brutal death and discover that the killer is a lycanthrope: a werewolf.', 40, '2007-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 18, 'Hollywood Babylon', 'Sam and Dean discover that a group of ghosts are attempting to shut down production of a movie that they feel is mocking them.', 40, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 19, 'Folsom Prison Blues', 'Sam and Dean allow themselves to be arrested in order to investigate a series of murders inside a penitentiary. However things get complicated when FBI agent Henricksen shows up to take over their case.', 41, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 20, 'What Is and What Should Never Be', 'Dean is attacked by a Djinn... and finds himself in a new reality where his mother is still alive and a mysterious woman holds the key to everything.', 42, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 21, 'All Hell Breaks Loose (1)', 'Sam and other "special children" are abducted by the Yellow-Eyed Demon and taken to a ghost town, where the ultimate battle must start.', 41, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 2), 22, 'All Hell Breaks Loose (2)', 'After the fight between Jake and Sam, Dean has to make the ultimate sacrifice for his brother. Meanwhile the Yellow-Eyed Demon has his new servant and plans to unleash the hordes of Hell.', 41, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 3, 'Season 3', 'The yellow-eyed demon is vanquished, but at a terrible price. The battle that brought him down released hundreds of demons from Hell into an unsuspecting world. And it cost Sam his life. But a grief-stricken Dean made a deal with the Crossroad Demon: his soul for Sam''s resurrection. Now Dean has just one year to live. One year to fight the unholy, the twisted, the ghoulish. One year to say farewell to Sam. And one year for Sam to search desperately for some way to save his brother. Mind-bending adventure awaits as the Winchester brothers continue their astonishing odyssey into the supernatural...and their personal odyssey into destiny.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 1, 'The Magnificent Seven', 'Seven demons, based on the Seven Deadly Sins, are released into the world and the brothers must combat them with the aid of a married Hunter couple.', 40, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 2, 'The Kids Are Alright', 'Sam & Dean track down changelings that are pursuing mothers and their children. A boy they protect bears a strange resemblance to Dean, which at first makes Dean uncomfortable because he once had a one-night stand with the boy''s mother Lisa.', 42, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 3, 'Bad Day at Black Rock', 'The Winchesters are called regarding a robbery of their father''s storage unit, and track down the robbers to find the item stolen is a cursed rabbit''s foot, which provides great luck until lost, and once lost the previous owner dies within a week.', 39, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 4, 'Sin City', 'The brothers investigate the death of a man who committed suicide in a church. However, Sam is forced to team up with an unexpected ally when Dean disappears with a female demon who is interested in him personally.', 41, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 5, 'Bedtime Stories', 'A young girl trapped in a coma by her wicked stepmother sets off a series of murders based on the fairy tales her father reads her. Meanwhile, Sam tries to get Dean out of his deal.', 40, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 6, 'Red Sky at Morning', 'Bela gets in the way yet again as Sam and Dean are investigating multiple victims who drowned even though they were nowhere near water.  Sam and Dean make the creepy discovery that the victims all saw a ghost ship right before dying.  They tell Bela to stay away, but she''s not so willing to leave, as someone''s paying her a lot to solve the same case Sam and Dean are investigating.', 41, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 7, 'Fresh Blood', 'The brothers capture a female vampire named Lucy who has no idea how she became one, which leads them to Dixon, a male vampire who is a little too giving. Gordon returns with a vengeance leaving Sam in danger.', 40, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 8, 'A Very Supernatural Christmas', 'In this Christmas-themed episode, Sam and Dean follow the trail of a creature that abducts its victims by using their chimneys. Dean would like to celebrate Christmas like they used to when they were children, but Sam isn''t exactly feeling the Christmas spirit.', 42, '2007-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 9, 'Malleus Maleficarum', 'The seemingly harmless practices of a group of neighborhood witches goes bad when one of them kills a woman. Ruby offers her assistance... but she has a few secrets of her own.', 40, '2008-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 10, 'Dream a Little Dream of Me', 'Dean interrogates a college student after the death of Dr. Greggs. Bobby, Sam and Dean all discover the truth behind the fatal death when they all get locked in a nightmare of their own.', 40, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 11, 'Mystery Spot', 'Dean is killed after looking into a case about the disappearance of a man with Sam. The next morning, Sam is shocked to find Dean alive and is hit with the realization that he is reliving the day before.', 40, '2008-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 12, 'Jus in Bello', 'FBI Agent Henricksen finally captures Sam and Dean, but is caught in the middle when a horde of demons descends on the small-town jail to eliminate the brothers.', 43, '2008-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 13, 'Ghostfacers!', 'In a change of pace, Sam and Dean decide to star in a violent, profane reality show named Ghostfacers. The show takes them to the haunted Morton Mansion, and they soon realize they''re in over their heads.', 42, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 14, 'Long-Distance Call', 'Sam and Dean search for a Crocotta that uses the phone and computer as a means to communicate with people. Its goal is to get people to commit suicide and take their soul. Dean gets some news from an unlikely source about a demon holding the contract to his soul.', 40, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 15, 'Time Is on My Side', 'Sam and Dean discover a doctor who, back in 1816, became obsessed with finding the secret of eternal life by taking people''s vital organs. Meanwhile, Bobby finds Bela and Dean leaves Sam to confront her.', 43, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 3), 16, 'No Rest for the Wicked', 'Sam, Dean, and Bobby hunt down Lilith and fight her and her demons in a final effort to save Dean''s life.', 39, '2008-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 4, 'Season 4', 'Resurrection. After enduring unspeakable torture, Dean escapes from Hell, rescued by an all-powerful creature he''s never seen before an Angel a warrior of God who recruits Sam and Dean in Heaven''s battle against Hell. And there are whispers that a certain fallen angel will soon be freed from his prison deep in Hell: Lucifer. If Sam and Dean can''t stop it if Lucifer walks free he''ll bring on the Apocalypse. Meanwhile, the Winchester brothers reunite and hit the road, battling the supernatural wherever they go. They encounter demons, spirits, Dracula himself and even a drunk, heavily armed seven-foot-tall teddy bear. All the while, the ultimate war draws them into its horror. Caught between Heaven and Hell, between God and the Devil, the Winchester brothers must battle for the future of humankind.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 1, 'Lazarus Rising', 'Dean wakes up in his own coffin. How did he return from the dead? What caused the hand-shaped welt on his shoulder? And what happened in the four months he spent in Hell, time he can''t remember?', 43, '2008-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 2, 'Are You There, God? It''s Me, Dean Winchester', 'After Dean''s encounter with Castiel, Dean, Sam and Bobby brush up on their biblical lore when they''re attacked by the vengeful spirits of people from the Winchesters'' past. They''re warned it''s a sign that someone is trying to break seals which will bring on the apocalypse.', 41, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 3, 'In the Beginning', 'Back to the future, Castiel sends Dean to 1973 Lawrence, Kansas, where he meets a nice young couple named John and Mary Winchester. Dean''s parents. And Mary has a secret.', 43, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 4, 'Metamorphosis', 'Dark powers. Dean fears Sam is using his paranormal gifts in conflict with God''s plan. And an ordinary guy in an ordinary town gets a major case of the munchies. It starts with steak - and moves to human flesh.', 41, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 5, 'Monster Movie', 'In a black-and-white world reminiscent of classic horror flicks, the brothers tangle with a vampire, a werewolf and a mummy who are thinning the crowds at a quaint Oktoberfest.', 42, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 6, 'Yellow Fever', 'Hell beckons again when Dean is stricken with a mysterious illness that frightens its sufferers to death. Sam and Dean scramble to find the cause of the disease in time to save Dean from sure death.', 43, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 7, 'It''s the Great Pumpkin, Sam Winchester', 'Chomping candy, bobbing for apples. Halloween is such fun. Until gruesome deaths signify another seal is being broken. To stop it, Castiel and another angel plan a mass annihilation of the town.', 42, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 8, 'Wishful Thinking', 'Want to score a hot girlfriend, win the lottery or have your favorite teddy bear come to life? Then plunk a coin in a small town''s wishing well and stand back. One problem: The wishes come true with a twist.', 42, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 9, 'I Know What You Did Last Summer', 'What happened to Sam during the months Dean was dead? During the search for a girl named Anna Milton, who has a mysterious connection to angels, Sam reveals the astonishing events of the summer.', 42, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 10, 'Heaven and Hell', 'The angels want Anna dead, so Sam and Dean go on the run with the frightened girl, determined to discover the secret that has set the furies of Heaven on her.', 43, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 11, 'Family Remains', 'Dad, Mom, two kids and a dog. An all-American family doesn''t stand a ghost of a chance against the bloodthirsty force that turns their new home-sweet-home into a haunted house.', 42, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 12, 'Criss Angel Is a Douchebag', 'Aging magician The Incredible Jay performs the dangerous Table of Death trick and emerges unscathed. Jay cheated the Grim Reaper, but one of his rivals didn''t. He checked out while Jay was doing his act.', 43, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 13, 'After School Special', 'Fast times at Truman High. Murder brings Sam and Dean back to one of their old high schools, where they investigate possible demonic possession and take a few trips down memory lane.', 40, '2009-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 14, 'Sex and Violence', 'In a small town in Iowa, three loving husbands kill their wives. Turns out these guys believe in spreading their love around: Each is spending plenty of the family income on strippers at a nearby nudie bar.', 42, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 15, 'Death Takes a Holiday', 'Reapers take a break from work, and that means no one can die. But the escorts to the next world aren''t off getting some R&R, unless you call being held hostage by a demon restful and relaxing.', 42, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 16, 'On the Head of a Pin', 'Can torture be God''s work? After seven angels are mysteriously murdered, Castiel and Uriel demand that Dean use the agony-inducing skills he learned in Hell to extract information from Alastair.', 43, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 17, 'It''s a Terrible Life', 'At Sandover Bridge & Iron Inc., Dean is Dean Smith, the buttoned-down director of Sales & Marketing. Sam is Sam Wesson, a cubicle-dwelling tech support guy. What the heck is going on? Or is it what the Hell?', 42, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 18, 'The Monster at the End of this Book', 'Familiar plot. Familiar characters. Sam and Dean come across a series of graphic novels called "Supernatural" featuring two demon-hunting brothers named Sam and Dean.', 42, '2009-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 19, 'Jump the Shark', 'Meet the Winchester boys: Dean, Sam and... Adam. The Winchesters discover they have a younger half-brother, whose mother vanishes just as a long-dormant grave robber renews his ghoulish career.', 42, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 20, 'The Rapture', 'The body Castiel walks around in isn''t his. Instead, it belongs to a regular guy named Jimmy who wants his body - and his life - back. He gets the body. But the life may be a different story.', 39, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 21, 'When the Levee Breaks', 'Dean and Bobby have something frightening locked in Bobby''s panic room: Sam, who is corrupted by demon blood. With the apocalypse drawing nearer, Bobby wants to free Sam to fight on their side.', 43, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 4), 22, 'Lucifer Rising', 'The brothers prepare to fight the forces of the apocalypse in different camps. While Sam and Ruby hunt down Lilith, Dean joins Castiel and Zachariah to take on Lucifer.', 43, '2009-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 5, 'Season 5', 'Two brothers and one fallen angel - against all the might of Satan and his army! As the Apocalypse grows closer, threatening to turn Earth into a battlefield soaked with human blood, Sam, Dean and Castiel struggle against daunting odds. New foes arise, including the Four Horsemen of the Apocalypse. Old friends depart, consumed by the fearsome wrath of Hell. Through it all, the Winchesters are targeted by demons and angels alike, who warn that each brother has a special and terrible role to play in the coming devastation. Season Five follows Sam and Dean on their most terrifying journey yet, one that may lead them to the only ally strong enough to defeat the Devil: God.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 1, 'Sympathy for the Devil', 'Sam, Dean, and Bobby must deal with the aftermath of the Devil''s escape from Hell, and receive startling news from the Prophet Chuck.', 42, '2009-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 2, 'Good God, Y''All!', 'Hunter Rufus Turner calls in Bobby, Sam, and Dean to deal with a demon infestation in his town, but they soon discover the truth is much more horrifying. Meanwhile, Castiel goes to seek the only entity that can defeat Lucifer.', 42, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 3, 'Free to Be You and Me', 'Sam decides to stop hunting but has a hard time after he receives a surprise visit. Dean and Castiel try to find the Archangel Raphael in their bid to stop the Apocalypse.', 41, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 4, 'The End', 'Dean refuses Sam''s efforts to help him battle the Devil, and then wakes up to find himself five years in the future, in a wasteland where Lucifer has begun his endgame by unleashing a virus that transforms humans into zombies.', 42, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 5, 'Fallen Idols', 'Sam and Dean head to a small town where people are murdered by famous dead icons. However the brothers come to a dead end when two teenagers reveal they saw Paris Hilton kidnap their friend.', 40, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 6, 'I Believe the Children Are Our Future', 'Sam and Dean investigate a series of odd murders that strangely resemble fairytales and urban legends. The brothers track down an 11-year-old boy named Jesse and realize that whatever Jesse believes is coming true. Castiel tells Sam and Dean that Jesse is a serious threat and needs to be eliminated.', 42, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 7, 'The Curious Case of Dean Winchester', 'Sam and Dean discover a witch is running a high-stakes poker game where the currency is life years vs. money. Bobby sees the game as a chance to get out of the wheelchair and bets 25 years, but loses. As Bobby begins to age rapidly, Dean steps in to save him but also ends up turning into an old man, leaving Sam holding the bag for their survival.', 42, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 8, 'Changing Channels', 'When Sam and Dean find themselves living their lives on what appear to be TV shows, it makes for a whole new style of reality television and they wonder if the Trickster is to blame. From a sitcom to a soapy hospital drama to a Japanese game show to a crime procedural, each new experience they encounter is more bizarre than the next and they want out. But is the Trickster really the mastermind behind the madness?', 41, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 9, 'The Real Ghostbusters', 'Super fan Becky uses Chuck’s phone to trick Sam and Dean into attending a Supernatural fan convention, complete with fans dressed up as Sam and Dean. One of the activities is a live action role playing game, but things quickly turn sour after a real ghost appears on the scene.', 40, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 10, 'Abandon All Hope...', 'Sam, Dean and Castiel track down the Colt and head off to find Lucifer to send him back to Hell. It’s a hunters’ reunion when the crew joins forces with Bobby, Ellen and Jo for what could be their last night on Earth.', 42, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 11, 'Sam, Interrupted', 'A former hunter named Martin, who is currently institutionalized, calls Sam and Dean for help investigating a case in the mental hospital. The brothers get themselves admitted as patients to check out the mysterious monster that is attacking the patients, but their incarceration pushes both to the breaking point as they unleash their inner demons against each other.', 41, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 12, 'Swap Meat', 'Gary, a teenage nerd, conjures up a body-switching spell and changes bodies with Sam. Thrilled by his new handsome and built body, Gary (now Sam) investigates a case with Dean and takes advantage of his good looks and age by hitting on women and getting drunk.  Meanwhile, Sam is stuck in Gary''s teenage body, dealing with intrusive parents and high school.', 42, '2010-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 13, 'The Song Remains the Same', 'The angels send Anna back in time to kill John and Mary Winchester before they can conceive Sam knowing that if Sam was never born then Lucifer won''t be able to use him as his vessel.  Castiel sends Sam and Dean back to 1978 so they can stop Anna, and the two brothers are reunited with their parents.  Mary recognizes Dean as a hunter since he visited her in the past once before but tries to keep the truth from John.', 41, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 14, 'My Bloody Valentine', 'Castiel helps Sam and Dean hunt down Cupid on Valentine''s Day after townspeople start to kill each other for love. However, after Cupid tells them he''s innocent, they discover Famine, one of the Four Horsemen of the Apocalypse, has arrived in town.', 41, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 15, 'Dead Men Don''t Wear Plaid', 'Sam and Dean investigate Bobby''s home town where the dead are rising from the grave but instead of attacking humans, they are happily reuniting with their families. The brothers turn to Bobby for help but he tells them not to worry about it and to leave town. Suspicious, Dean investigates and comes face to face with Bobby''s dead wife, who has no memory of what happened to her. Once the zombies start turning evil, the boys tell Bobby he has to kill his wife but he refuses.', 42, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 16, 'Dark Side of the Moon', 'Ambushed by angry hunters, Sam and Dean are shot and killed. When they wake up in heaven, Castiel tells them that they need to find an angel named Joshua, who talks directly with God. But he also has a warning, Zachariah is searching for them.', 41, '2010-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 17, '99 Problems', 'Sam and Dean are outnumbered by demons, but are saved at the last minute by Rob and his townspeople, who are aware of the Apocalypse, and have been training to fight and kill demons. The small town is very religious and Sam and Dean meet Pastor Gideon, who introduces them to his daughter Leah, whom he claims is a prophet. Leah tells the townspeople they must obey her orders if they want a spot in Heaven but when she starts turning the townspeople against each other in the name of the Lord, the brothers realize they must kill her.', 41, '2010-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 18, 'Point of No Return', 'Dean begins to think the only way to stop Lucifer is to say yes to Michael, but the angels decide they don''t need him anymore. Dean, Sam, and Castiel are horrified at the angels'' new game plan and take on Zachariah to prevent an all out war on Earth. Meanwhile, a familiar face returns.', 42, '2010-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 19, 'Hammer of the Gods', 'Sam and Dean are kidnapped by a group of gods, including Kali, Ganesh, and Baldur and held hostage in a small hotel. The gods want to use Sam and Dean as bargaining chips to stop the Apocalypse, but Gabriel shows up and warns them that if Lucifer finds them he will kill them all. Unfortunately, one of the gods turns on the rest and Lucifer appears.', 40, '2010-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 20, 'The Devil You Know', 'The demon Crowley tells Sam and Dean he can help them find the remaining Horsemen rings so they can trap Lucifer. The brothers are doubtful until Crowley leads them to Brady, the Handler for Pestilence and Death. However, Brady refuses to give up their locations and sets Pestilence after the Winchesters.', 42, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 21, 'Two Minutes to Midnight', 'Crowley tells Bobby he will give him the location of Death, the fourth horseman, in exchange for his soul. Knowing Sam and Dean need that fourth ring to stop the Apocalypse, Bobby reluctantly agrees. Sam and Dean confront Pestilence, but he unleashes a deadly virus upon them, so Castiel must intervene on their behalf. Dean has a meeting with Death to discuss Lucifer, and an unholy alliance is formed at a very high price for Dean.', 42, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 5), 22, 'Swan Song', 'The showdown between good and evil is at hand.  With the Apocalypse looming, Sam and Dean realize they are out of options and make heart-breaking decisions that will change their lives forever.  A beloved character faces death.', 42, '2010-05-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 6, 'Season 6', ' The prize: ending the Apocalypse. The price: Sam''s life. Season 5''s horrific finale left Dean alone, as Sam descended into Hell. Now a different man, Dean vows to stop hunting and devote himself to building a family with Lisa and her son Ben. Then, mysteriously, Sam reappears, drawing Dean back into the old life. But Sam''s a different man too. He''s returned without his soul. How the Winchesters confront this greatest challenge yet to their powerful bond is the troubled heart - and soul - of the profound and thrilling 22-Episode Season 6. As the brothers struggle to reunite, they must also battle deadly supernatural forces. Demons. Angels. Vampires. Shapeshifters. And a terrifying new foe called the Mother of All.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 1, 'Exile on Main St.', 'Sam is mysteriously released from Hell and seeks out his brother, trying to have a normal life. Together the brothers must join forces with their maternal grandfather, Samuel, and begin the fight anew.', 42, '2010-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 2, 'Two and a Half Men', 'Sam investigates a case about missing babies whose parents are being murdered. At one of the crime scenes, he discovers a baby that was left behind and calls Dean for help. Reluctant to leave Lisa and Ben, Dean finally agrees to meet Sam and surprises his brother with how parental he has become. The brothers take the baby to Samuel, who decides to raise it as a hunter, which infuriates Dean. However, before they can decide the baby''s future, a shape-shifter breaks in and attempts to kidnap the baby.', 41, '2010-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 3, 'The Third Man', 'Sam and Dean call Castiel for help when they investigate a case about several dead police officers who seem to have been killed by the plagues of Egypt. Castiel confirms the staff of Moses was used to kill the cops and tells Sam and Dean that Heaven is in a state of chaos and God''s weapons have been stolen. The three head off to find the thief and come face to face with an old enemy.', 41, '2010-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 4, 'Weekend at Bobby''s', 'After Bobby discovers Crowley has no intentions of returning Bobby''s soul, the hunter takes matters into his own hands. He calls on Sam and Dean for help after he unearths one of Crowley''s deepest secrets. Meanwhile, Sam and Dean learn what Bobby does all day when they are not around.', 41, '2010-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 5, 'Live Free or Twihard', 'After a group of young girls go missing Sam and Dean realize that a group of vampires have taken up residence in the small town. After a fight with two of the blood-suckers, Dean is bitten and turns into a vampire. Samuel  tells Dean he can change him back but he’d have to get the blood of the vampire who turned him. Dean infiltrates the nest and runs into the Alpha...', 42, '2010-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 6, 'You Can''t Handle the Truth', 'Sam and Dean investigate a series of suicides and discover the victims were being told brutal truths that drove them crazy. They find out someone is invoking the Goddess of Truth, Veritas, forcing people to be cruelly honest against their will and Dean is the next victim. Dean is forced to tell Sam the truth about how he feels about his return from Hell.', 41, '2010-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 7, 'Family Matters', 'Dean becomes suspicious of Samuel''s motives, but Sam isn''t sold on the idea that their grandfather is doing anything wrong. The brothers go along on a hunt with Samuel and the other Campbells, but things go terribly awry.', 41, '2010-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 8, 'All Dogs Go to Heaven', 'Dean and Sam investigate what seems to be a werewolf killing but turns out to be a skinwalker posing as a family dog who is taking revenge on his owner’s enemies.', 42, '2010-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 9, 'Clap Your Hands If You Believe...', 'While Sam and Dean are investigating a UFO sighting, Dean is abducted from a crop circle. However, when he awakens, he discovers he isn''t dealing with aliens, but fairies! Unfortunately, only Dean can see the fairy that keeps attacking him which makes tracing and stopping them difficult. The brothers become even more perplexed when Sam''s investigation leads them to a world full of elves, gnomes and a leprechaun.', 42, '2010-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 10, 'Caged Heat', 'Meg kidnaps Sam and Dean and tries to force them to tell her where Crowley is hiding. Sam makes her a deal - they will help her find Crowley if she promises to torture him for information about how to get Sam''s soul back. Castiel joins the fight but finds it difficult to work with Meg.', 42, '2010-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 11, 'Appointment in Samarra', 'Dean seeks out Death to help get Sam''s soul back. Death tells Dean he will help Sam if Dean will agree to act as Death for 24 hours. Meanwhile, Sam decides he doesn''t want his soul back and asks Balthazar for a protective spell to keep his soul out of his body. Balthazar tells Sam he needs the blood of his father for the spell to work and since John Winchester is dead, Sam decides Bobby is the next best thing.', 42, '2010-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 12, 'Like a Virgin', 'Dean and Bobby anxiously wait for Sam to wake up to see if Death was able to restore his soul without causing Sam to lose his mind. Meanwhile, Dean and Bobby investigate a disappearance of virgins and discover dragons are behind the kidnappings. Bobby sends Dean to a doctor who owns the only weapon in the world that can slay a dragon, but Dean must prove himself worthy enough to take it', 42, '2011-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 13, 'Unforgiven', 'Sam starts to have flashbacks to a case he worked on with Samuel before he reconnected with Dean. Sam receives a mysterious text with coordinates to a small town, so the brothers decide to investigate. Dean is surprised when the townspeople start telling him some of the things Sam did while he lived there.', 41, '2011-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 14, 'Mannequin 3: The Reckoning', 'Ben calls Dean and tells him Lisa is in trouble. Dean leaves Sam to investigate a case alone and rushes home to rescue Lisa, however, he’s not prepared for what meets him at the door. Meanwhile, Sam discovers the men that were murdered were all a part of a cruel practical joke played on a female co-worker who went missing.', 40, '2011-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 15, 'The French Mistake', 'Dean and Sam find themselves in an alternate reality where everyone believes they are two actors named Jensen Ackles and Jared Padalecki, who star in a TV show called Supernatural about two brothers who hunt monsters.', 42, '2011-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 16, '...And Then There Were None', 'Eve, the Mother of All, unleashes a new monster upon the world: a black worm-slug that can enter the brain and force people to kill. Sam and Dean join forces with Bobby and Rufus and track it to a cannery, only to discover that Gwen and Samuel are also there looking for the monster... and none of them know who the monster is inside.', 42, '2011-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 17, 'My Heart Will Go On', 'After Balthazar changes history and keeps the Titanic from sinking, Fate intervenes and begins killing those that would have died on the ship. Castiel tells Sam and Dean that Fate is very upset with the two of them and the only way they can stay alive is to kill her.', 42, '2011-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 18, 'Frontierland', 'While searching for a way to defeat Eve, Dean stumbles upon Samuel Colt’s journal in the Campbell library. Realizing Samuel might have the answer to their problems, Sam and Dean ask Castiel to send them back in time so they can meet the man himself. While Sam is a bit reluctant to time travel, Dean is beside himself with excitement to return to the Wild, Wild West.', 41, '2011-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 19, 'Mommy Dearest', 'Sam, Dean, Bobby and Castiel track Eve to a small town in Oregon. The guys discover the townspeople have been converted to demons, but surprisingly, they all appear to be dying. When they finally do meet Eve, she decides to torture the brothers by bringing back their mother.', 42, '2011-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 20, 'The Man Who Would Be King', 'Castiel tells Sam, Dean and Bobby about the war in Heaven and how he and Raphael became enemies. Bobby believes Castiel is hiding something, but Dean refuses to believe it.', 42, '2011-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 21, 'Let It Bleed', 'A demon kidnaps Ben and Lisa to get to Dean. Sam and Dean are forced to join with an unlikely ally to free them.', 42, '2011-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 6), 22, 'The Man Who Knew Too Much', 'The wall comes down in Sam’s head and all hell breaks loose. Dean and Bobby are, for once, at a total loss on how to help him and are forced to stand by and do nothing while Sam breaks. The battle for heaven comes to a head.', 42, '2011-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 7, 'Season 7', ' In Season 7, Sam and Dean fight demons. Real demons, like Lucifer, who tortures Sam with visions of Hell. Private demons, as the brothers face a traumatic personal loss when Bobby is cut down by alien forces. And as Sam and Dean travel the back roads of America, hunting monsters who wreak havoc on the innocent, a new and more terrible foe hunts them: Leviathans, freed from Purgatory and immune to the brothers'' arsenal of weapons and cunning. With Bobby gone, all Sam and Dean can rely on is each other. But will that be enough?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 1, 'Meet the New Boss', 'Castiel doesn''t kill Sam, Dean and Bobby but warns them not to interfere in his business. Assuming his new role as God, Castiel sets out to right some of the wrongs in the world. Dean decides they should bind Death and order him to stop Castiel, but the former angel is one step ahead of them, leaving Dean to face a very angry Death. Meanwhile Sam struggles to deal with the broken wall in his head.', 42, '2011-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 2, 'Hello, Cruel World', 'The broken wall in Sam''s head causes him to have hallucinations, and he has difficulty discerning what''s real and what''s not. Bobby worries that Dean is beginning to stumble under the weight of fighting and keeping an eye on Sam.', 42, '2011-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 3, 'The Girl Next Door', 'Dean is furious after Sam disappears to follow a lead on a case with clues that are identical to a case Sam solved as a kid. The demon turns out to be Amy, who has been killing low-life thugs and taking their brains for dinner - the same demon Sam found as a kid.', 42, '2011-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 4, 'Defending Your Life', 'Sam and Dean investigate a string of gruesome murders and discover the Egyptian god Osiris is behind the deaths. The vengeful god is putting people on trial for their past mistakes and killing them if found guilty. Osiris hones in on Dean’s guilt and decides he’s the next to stand trial. Sam steps in as Dean’s lawyer, but both brothers are unprepared when Osiris calls an unexpected witness Jo.', 42, '2011-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 5, 'Shut Up, Dr. Phil', 'Sam and Dean meet Maggie Stark, a witch who has unleashed her wrath on a small town, resulting in numerous deaths. Sam and Dean track down her husband, Donald, to see if he can help. Donald tells the brothers that Maggie is mad at him for having an affair and is taking it out on the townspeople.', 42, '2011-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 6, 'Slash Fiction', 'Sam and Dean are once again on the FBI’s “Most Wanted” list when two Leviathans clone the brothers and go on a killing spree. The subject of a nationwide manhunt, Sam and Dean need to drop off the grid so Bobby sends them to Frank Deveraux, a quirky surveillance expert, for help. Meanwhile, Bobby continues to search for a way to kill the Levianthans, or at least slow them down, so the real Winchesters can stop their evil doppelgangers.', 42, '2011-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 7, 'The Mentalists', 'Sam and Dean investigate the gruesome murders of resident mediums in Lily Dale, the most “psychic” town in America. They discover that an angry spirit is killing off the psychics one by one, but in a town full of people who claim to be summoning spirits, they have a little trouble identifying the medium controlling the ghost.', 42, '2011-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 8, 'Season Seven, Time for a Wedding!', 'While on a hunt, Sam runs into someone from his past and a confrontation ensues. Meanwhile, Dean reluctantly teams up with a quirky, laid-back hunter named Garth, when he finds himself in a situation that he just cannot explain.', 42, '2011-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 9, 'How to Win Friends and Influence Monsters', 'Sam, Dean, and Bobby become actual hunters, in the true sense of the word, when they set up camp in a New Jersey state park to track a creature that has been attacking people in the woods. The townsfolk claim it is the real Jersey Devil. Meanwhile, Dean is beyond thrilled to find a Biggerson’s restaurant in town, but is devastated when he discovers the restaurant’s special sandwich seems to be making people crazy.', 40, '2011-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 10, 'Death''s Door', 'As Sam and Dean race the clock on a high-stakes mission, Bobby seeks the help of an unlikely old friend to solve one of the most personal cases of his life.', 42, '2011-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 11, 'Adventures in Babysitting', 'Still reeling after what happened to Bobby, Dean becomes dangerously obsessed over finding a way to take down Dick Roman. Meanwhile, Sam decides to help a teenage girl look for her father, a hunter who has gone missing. Sam traces his last steps to a truck stop where the help  turns out not to be so friendly.', 42, '2012-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 12, 'Time After Time', 'Sam and Dean tangle with the God of Time, who sends Dean back to 1944, where he is immediately arrested by none other than the one and only Eliot Ness. While trying to figure out how to retrieve his brother, Sam is surprised by the reappearance of an old friend.', 42, '2012-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 13, 'The Slice Girls', 'Sam and Dean investigate a case where the victims'' hands and feet have been severed and each have been branded with a strange symbol. While Sam does some research at a local university, Dean heads to one of his favorite places to investigate - the town bar. Dean strikes up a conversation with a local named Lydia, and the two go back to her place. Sam discovers the symbol on the bodies is a sign of Amazon warriors.', 41, '2012-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 14, 'Plucky Pennywhistle''s Magical Menagerie', 'Sam and Dean investigate strange happenings in a town where childhood fears are coming to life. To Sam''s horror his childhood fear of clowns manifests in a very violent and traumatic way which in turn leads to Dean''s childhood fear, losing his brother.', 41, '2012-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 15, 'Repo Man', 'Four years ago, Sam and Dean helped a woman named Nora exorcise a demon that was systematically killing women in a small town. They managed to save a postal worker, Jeffrey, while vanquishing the demon, but now it seems the black-eyed monster has reared his ugly head and returned for a second helping. The brothers visit Jeffrey, who has been locked in a psych ward since the incident, to see if he can remember any of the demon’s plans while he was possessed.', 42, '2012-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 16, 'Out with the Old', 'After a ballerina is found dead from dancing herself to death, Sam and Dean look into the case and discover the ballet slippers she wore were cursed. When Dean accidentally touches the shoes the power of the curse starts to take hold of him.', 42, '2012-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 17, 'The Born-Again Identity', 'Lucifer drives Sam to the breaking point and Sam ends up in a mental hospital. Desperate to save his brother, Dean calls every hunter he knows for help. One of the hunters gives him the name of a healer who turns out to have a very familiar face.', 42, '2012-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 18, 'Party On, Garth', 'Dean is surprised when he gets a call from Garth asking for the brothers’ help on a case. Sam and Dean discover they are battling a Shojo, a Japanese creature sent to seek revenge on enemies. The worst part about fighting a Shojo? You can only see it when you’re drunk.', 42, '2012-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 19, 'Of Grave Importance', 'Sam and Dean get a call from Annie Hawkins, an old hunter friend, asking for help on a case. When they arrive in town, they find out Annie has disappeared. They trace her last whereabouts to an old abandoned house that is haunted by a powerful ghost.', 41, '2012-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 20, 'The Girl with the Dungeons and Dragons Tattoo', 'Dick Roman acquires Frank''s hard drive that contains sensitive information about the Winchesters and gives it to an unsuspecting brilliant hacker named Charlie telling her she has 3 days to crack the encryptionl or she is fired. Sam and Dean are tipped off that Dick has the hard drive and race to get to Charlie before she breaks the code. Meanwhile, Bobby tries to help the brothers, but his rage towards Dick for killing him starts to get in the way.', 42, '2012-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 21, 'Reading is Fundamental', 'Meg calls Dean and Sam and tells them Castiel is awake and talking. Meanwhile, a teenager named Kevin gets hit by a bolt of lightning and is turned into a reluctant prophet. Sam and Dean believe Kevin holds the key to defeating the Leviathans but must fight off two Archangels who want him for their own purposes.', 42, '2012-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 22, 'There Will Be Blood', 'In order to defeat Dick Roman and the Leviathans, Sam and Dean must locate three key items. Castiel gets one of them but for the other two, the Winchesters must face two of their strongest opponents.', 43, '2012-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 7), 23, 'Survival of the Fittest', 'Dean and Sam prepare for battle with Dick Roman, who is in the final phase of his plan. The Winchesters must team up with Castiel, Bobby, Meg, and Kevin in order to stop him.', 42, '2012-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 8, 'Season 8', 'After a year apart, Sam and Dean are reunited in the Eighth Season premiere. After escaping from Purgatory with the help of a vampire named Benny, Dean heads straight for Sam, but the reunion isn''t exactly everything he imagined it would be. Although Sam drops everything to join his brother, leaving the life he had grown accustomed to enjoy turns out to be harder than he imagined. In the meantime, Benny’s help turns out to be more than what Dean bargained for. As the brothers struggle with their unexpected reunion, they make a shocking discovery that could lead them on a deeply personal mission to settle old scores. If only they could agree – is this a “family business” or isn’t it?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 1, 'We Need to Talk About Kevin', 'One Year Later, and Dean’s escaped from Purgatory, though Castiel is nowhere to be found. However, Dean isn’t alone. He’s returned with a mysterious comrade-in-arms whose reason for escape is perhaps more than Dean bargained for. Meanwhile, Sam finds himself reconciling the life he discovered while Dean was gone with Dean’s sudden reappearance.', 42, '2012-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 2, 'What''s Up, Tiger Mommy?', 'Kevin talks Sam and Dean into checking in on his mother. When they arrive, they see that Crowley has surrounded her with demons so they rescue her and take her along on their quest to find the tablet. However, they soon discover Kevin wasn’t kidding when he said his mother was a strong-willed woman after she tries to take on Crowley.', 42, '2012-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 3, 'Heartache', 'Sam and Dean investigate a string of unusual murders where the victims were all recipients of organs from the same donor. The killer is captured, but things become even more complicated when the brothers find their killer in a trance mumbling an ancient prayer.', 41, '2012-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 4, 'Bitten', 'Sam and Dean investigate a bizarre murder in a college town. Close on the tail of their suspect, they bust into an apartment to find two dead bodies and a laptop cued up to some disturbing video footage.', 42, '2012-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 5, 'Blood Brother', 'After Benny gets brutally beat up by vampires, he calls Dean for help who abruptly packs up and tells a confused Sam that he’s taking a personal day. Meanwhile, Sam uses his solo time to reflect on the life he left behind with Amelia.', 42, '2012-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 6, 'Southern Comfort', 'Sam and Dean investigate a murder and find Garth is already on the case. Dean is not happy to learn that Garth has assumed Bobby’s duties, but someone had to pick up the slack.', 42, '2012-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 7, 'A Little Slice of Kevin', 'Sam and Dean are stunned when Castiel suddenly appears back on Earth with no memory of how he escaped from Purgatory. Meanwhile, Mrs. Tran enlists a witch to concoct a demon bomb.', 42, '2012-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 8, 'Hunteri Heroici', 'Castiel tells Sam and Dean that he’s decided to become a hunter like them. Sam and Dean aren’t sold on the idea but agree to investigate a case Cas found where a man’s heart literally burst through his chest. The guys discover that all the deaths resemble cartoon deaths.', 42, '2012-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 9, 'Citizen Fang', 'Sam asks a hunter named Martin to keep an eye on Benny without telling Dean. However, when Martin tells Sam and Dean there was a vampire kill and that Benny is responsible, Dean defends his friend.', 42, '2012-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 10, 'Torn and Frayed', 'After Naomi orders Castiel to rescue an angel being held captive by Crowley, he turns to Dean for help. Meanwhile, Sam meets with Amelia who asks him to make a choice: stay with her or leave and never contact her again.', 43, '2013-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 11, 'LARP and the Real Girl', 'Sam and Dean investigate the mysterious deaths of two LARPers who were playing a game titled Moondoor. The guys are thrilled to discover that the Queen of Moondoor is none other than Charlie.', 43, '2013-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 12, 'As Time Goes By', 'Sam and Dean are stunned when a man who claims to be Henry Winchester, their grandfather, suddenly appears in their hotel room demanding to know where he can find John Winchester, their father.', 42, '2013-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 13, 'Everybody Hates Hitler', 'Sam and Dean investigate the death of Rabbi Bass, who appears to have spontaneously combusted. The case becomes even more confusing when they learn that the Rabbi was researching Nazi Necromancers.', 43, '2013-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 14, 'Trial and Error', 'Kevin deciphers the demon tablet and figures out how to close the gates of Hell. He tells Sam and Dean that according to the tablet one person must face a series of three trials, and the first one is to kill a hellhound.', 43, '2013-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 15, 'Man''s Best Friend with Benefits', 'A police officer named James, who turned to witchcraft after working a case with Sam and Dean, is plagued by nightmares in which he murders innocent people.', 42, '2013-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 16, 'Remember the Titans', 'Sam and Dean are stumped when they investigate a possible zombie case where an amnesiac man dies and then revives himself every day. After the man is attacked by the goddess Artemis, Sam and Dean realize he’s not a zombie.', 42, '2013-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 17, 'Goodbye, Stranger', 'Castiel reappears in Sam and Dean’s life and tells them Crowley has unleashed several demons into a small town in order to find Lucifer’s Crypt, which holds a valuable relicts. While interrogating a demon, the three discover Crowley has been torturing Meg, who knows the location of the crypt.', 42, '2013-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 18, 'Freaks and Geeks', 'Sam and Dean investigate some recent vampire kills and are surprised to learn Krissy Chambers is involved. They find Krissy and learn her father was killed and she’s been taken in by a man named Victor, who has taken in a group of orphan kids to teach them how to hunt.', 42, '2013-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 19, 'Taxi Driver', 'Kevin is terrified. He has started hearing Crowley''s voice in his head and calls Sam and Dean for help. After hearing Kevin''s news, Sam and Dean team up with a reaper named Ajay, who helps them with the second trial from the demon tablet.', 42, '2013-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 20, 'Pac-Man Fever', 'Concerned about the physical toll the second trial took on Sam, Dean benches his brother from hunting until he heals up. So, when geektastic hacker Charlie Bradbury stumbles upon a case, Dean decides it''s time to teach Charlie how to be a hunter-in-training.', 42, '2013-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 21, 'The Great Escapist', 'When Sam and Dean receive a distressing video message from Kevin Tran, they set out trying to uncover the third trial. The boys make a discovery that sends them to a casino in Colorado where they find a mysterious recluse who may be able to fill in the holes in Kevin’s research. Meanwhile, Castiel tries to elude Naomi and the angels hunting him.', 42, '2013-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 22, 'Clip Show', 'Sam and Dean are reunited with Castiel as they are digging through the Men of Letters'' files. They stumble upon an film which could be the key to completing the third trial. Metatron enlists Cass to mull over problems at home.', 42, '2013-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 8), 23, 'Sacrifice', 'With Crowley poised to undo all the good they’ve ever done as hunters, Sam and Dean find themselves cornered. But with Kevin''s help, the Winchesters ready themselves for one last play against the King of Hell. Metatron initiates a plan with Castiel to take on Naomi and the bureaucracy of Heaven.', 42, '2013-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 9, 'Season 9', ' After defeating the Leviathan, Sam and Dean set off on an epic quest to seal the Gates of Hell last season. Facing a series of trials, the Winchesters soon found themselves in the middle of an age-old power struggle between the King of Hell and legions of warrior angels. But with the angels cast out of heaven and walking the earth, things just got very unpredictable.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 1, 'I Think I''m Gonna Like It Here', 'With Sam''s life on the knife-edge, Dean appeals to the fallen angels for help. Unfortunately, most of them only see Dean as a means to get to Castiel and exact vengeance on the one who caused them to Fall.', 42, '2013-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 2, 'Devil May Care', 'Dean and Sam take a captive Crowley to the Men of Letters base in the hopes that he will give up the names of the people possessed by his minion demons. But before they can get any information they are called away to investigate the disappearance of three soldiers.', 41, '2013-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 3, 'I''m No Angel', 'Castiel makes his way to the Winchesters but discovers a band of angels are hunting him, intent on exacting vengeance for what they believe is his role in their fall from Heaven. Meanwhile, Ezekiel continues to repair Sam, but informs Dean that there is a price to be paid.', 42, '2013-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 4, 'Slumber Party', 'With the help from Charlie, Sam and Dean inadvertently release two individuals contained inside of the Men of Letters bunker who where both imprisoned in 1935. They soon discover that one of the individuals is Dorothy of Oz, and she is hot on the trail of the Wicked Witch of the West.', 42, '2013-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 5, 'Dog Dean Afternoon', 'To track down a killer, Dean uses a spell which allows him to speak with the only witness, a German Sheppard. However, he soon discovers that everything is going to the dogs when the spell starts making him act like a canine as well.', 41, '2013-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 6, 'Heaven Can''t Wait', 'Castiel is working as a convenience store clerk and learns of a series of local disappearances. He call the Winchesters, but Dean insists on Sam staying with Kevin to research the demon tablet while he help Cass.', 43, '2013-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 7, 'Bad Boys', 'Sonny, a man who runs a boy''s home, calls Dean for help after a mysterious death. When Sam wonders how his brother knows Sonny, Dean explains that he spent two months at the boy''s home when he was 16, after being arrested for theft.', 42, '2013-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 8, 'Rock and a Hard Place', 'When members of a virgin chastity group are abducted, Sheriff Jody Mills asks Sam and Dean for help. The Winchesters go undercover to track down the missing members, but when Dean disappears, Sam and Jody end up having to track him down.', 42, '2013-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 9, 'Holy Terror', 'The angels are embroiled in a bloody civil war, and Castiel is swept up in the conflict. Meanwhile, Dean realizes that Ezekiel is not who he claims to be and tries to warn Sam with dire results.', 42, '2013-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 10, 'Road Trip', 'Dean and Castiel make a deal with Crowley in order to contact Sam''s consciousness so he can expel the angel Gadreel from his body. However, Abaddon is hot on their trail and Crowley has plans of his own.', 43, '2014-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 11, 'First Born', 'Crowley turns to Dean for help to locate the First Blade, the only weapon that can kill Abaddon. However, the trail leads them to the biblical Cain. Meanwhile, Sam asks Castiel for help when they need to extract the remaining angel grace from Sam''s body to track Gadreel.', 42, '2014-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 12, 'Sharp Teeth', 'Six months after his disappearance, Garth turns up injured in a hospital. Sam and Dean arrive separately to investigate and soon discover that their friend has undergone a startling transformation.', 41, '2014-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 13, 'The Purge', 'Two dead victims show up with all the fat having being stolen from their bodies. Sam and Dean go undercover in order to investigate a local spa, and discover that a monster is preying on the overweight.', 42, '2014-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 14, 'Captives', 'While Sam and Dean try to track down Kevin''s mother, Castiel is captured by an old battle-comrade and learns more about the factions of angels.', 42, '2014-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 15, '#THINMAN', 'The Winchester brothers investigate a murder that was apparently caused by a ghost. Sam and Dean discover that the Ghostfacers, Ed and Harry, are already on the case.', 42, '2014-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 16, 'Blade Runners', 'Sam and Dean are searching for the First Blade and end up having to track down the missing Crowley and discover that he''s now thoroughly addicted to human blood. The Winchesters decide that going cold turkey is the only way.', 42, '2014-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 17, 'Mother''s Little Helper', 'When Dean chooses to stay in the bunker and try and locate Abaddon, Sam goes to a small Illinois town to investigate a string of vicious murders committed by seemingly harmless individuals.', 42, '2014-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 18, 'Meta Fiction', 'Castiel investigates the mass slaughter of angels and finds a lone survivor and an old friend. Meanwhile, Sam and Dean capture Gadreel, and Metatron begins the ending of his story.', 42, '2014-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 19, 'Alex Annie Alexis Ann', 'Sheriff Jody Mills befriends a young girl on the run from vampires. When she''s forced to kill one of the monsters, Jody calls in Sam and Dean for help. However, they discover that everything isn''t at it seems.', 43, '2014-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 20, 'Bloodlines', 'Sam and Dean learn about a monster killing in Chicago and head there to investigate. What they find is a young cop whose girlfriend was killed by the same creature, and who is caught between five powerful clans of monsters who jointly control the city.', 42, '2014-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 21, 'King of the Damned', 'Abaddon finally gets something that she can use as leverage against Crowley to force him to lure the Winchesters into a trap. Meanwhile, Castiel rallies his forces and asks Sam and Dean to come in and help him interrogate a captive angel with ties to Metatron.', 42, '2014-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 22, 'Stairway to Heaven', 'After an angel carries out a suicide attack on an ice cream shop to kill one angel from another faction. Sam and Dean investigate and discover that the target was one of Metatron''s angels and that Castiel may be responsible.', 42, '2014-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 9), 23, 'Do You Believe in Miracles?', 'After attacking Gadreel, Dean leaves with Crowley to track down Metatron and kill him. Meanwhile, Gadreel takes Castiel into Heaven to try and break Metatron''s connection to the angel tablet.', 42, '2014-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 10, 'Season 10', 'Season 10 begins with Sam’s frantic search for his missing brother, who is gone without a trace. The road to recovering the wayward Dean takes Sam down dark paths, with consequences that will shake the boys to their core. Meanwhile, Castiel has to pick up the pieces in the aftermath of Metatron’s campaign. With his grace failing and rogue angels still on the loose, Cas will face the ticking clock of his own mortality as all-new threats emerge to once again push all of our heroes to their limits.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 1, 'Black', 'Dean is a demon and running amuck with Crowley while Sam tries to figure out what happened to his brother. Meanwhile, Castiel is dealing with his fading grace.', 42, '2014-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 2, 'Reichenbach', 'Crowley is worried that Dean, driven by the mark, is getting out of control. Sam struggles to escape from Cole. Hannah tries to convince Metatron to give Castiel his grace back.', 42, '2014-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 3, 'Soul Survivor', 'Sam continues to try to save Dean from the Mark of Cain. Realizing that Dean''s antics are causing problems for him in hell, Crowley seeks help from a reluctant Castiel.', 42, '2014-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 4, 'Paper Moon', 'Sam and Dean investigate a series of werewolf attacks.', 41, '2014-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 5, 'Fan Fiction', 'Sam and Dean investigate a haunting at a theatre.', 42, '2014-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 6, 'Ask Jeeves', 'After Dean hears a surprising message on Bobby''s phone, he and Sam head out to investigate.', 42, '2014-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 7, 'Girls, Girls, Girls', 'Sam and Dean discover a group of witches on a gone wild trip and attempt to stop them.', 42, '2014-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 8, 'Hibbing 911', 'Sheriff Jody Mills is matched with an overeager partner during a mandatory sheriff''s retreat and when a gruesome corpse is discovered, Jody calls Sam and Dean to help investigate.', 42, '2014-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 9, 'The Things We Left Behind', 'Castiel finds Jimmy’s daughter Claire in a group home and she convinces him to break her out. After she runs away from him, Castiel calls Sam and Dean to help find her before she gets in trouble.', 42, '2014-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 10, 'The Hunter Games', 'After the massacre at the ranch, Dean, Sam, and Castiel double their efforts to find a cure for the Mark of Cain. Desperate, Castiel comes up with an idea that Sam deems the single worst idea he''s ever heard. Meanwhile, Rowena continues to plot against Crowley.', 43, '2015-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 11, 'There''s No Place Like Home', 'Sam is scanning the internet for suspicious paranormal activity and comes across a video of Charlie beating up a district attorney. Dean suspects she’s back from Oz and hunting on her own, assuming the district attorney must have been a demon.', 43, '2015-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 12, 'About a Boy', 'Looking to get Dean out of the bunker, Sam finds a case for him and Dean to investigate – people are disappearing into thin air with only their clothes left behind.', 41, '2015-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 13, 'Halt & Catch Fire', 'A ghost starts killing people through various electronic devices. Sam and Dean discover who was killed and why this ghost is seeking revenge on a group of college students but what they can''t figure out is how he’s doing it.  With three dead, the brothers must stop the ghost before he claims his next victim.', 42, '2015-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 14, 'The Executioner''s Song', 'Dean, Sam and Castiel deal with Cain’s return.  Crowley and Rowena continue to grow closer but when Crowley bails on plans with his mother to help the Winchesters, Rowena lets him have it.', 42, '2015-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 15, 'The Things They Carried', 'Despite Dean''s directive to forget about looking for a cure for the Mark of Cain, Sam continues to do research. Dean suspects Sam is hiding something but decides to focus on a new murder case where they run into Cole. The three team up and learn a Khan worm is infecting men and turning them into murderers. Unfortunately, the worm makes its way into Cole.', 42, '2015-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 16, 'Paint It Black', 'Sam and Dean investigate a string of suicides committed by people with little in common other than the identical, grisly method of death – slow, self-administered disembowlment. All of the victims were members of a Catholic church and had recently given confession, leading the brothers to suspect the priest is somehow involved. Meanwhile, when Crowley captures Olivette, the leader of the Grand Coven, Rowena pleads her case to be allowed to practice magic freely again. ', 42, '2015-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 17, 'Inside Man', 'Sam and Castiel follow up on a lead about the Mark of Cain. Dean and Rowena meet. ', 42, '2015-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 18, 'Book of the Damned', 'Charlie calls Sam and Dean to tell them she found the Book of the Dead which could help remove the Mark of Cain. The Winchesters race to her after she tells them she’s been shot by a man named Jacob Styne who says the book belongs to his family and he won’t rest until he gets it back. Castiel and Metatron take a road trip to find Castiel’s grace but they hit a couple road bumps along the way.', 42, '2015-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 19, 'The Werther Project', 'Sam learns that former Men of Letters, Magnus, once built a magical box and Sam sets out to find it in the hopes it can cure Dean of the Mark of Cain.  However, what he’s not prepared for is the deadly alarm system Magnus set up on the box.  When Sam opens the box, he puts both his and Dean’s life in danger. ', 42, '2015-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 20, 'Angel Heart', 'When Claire Novak gets a lead on her mother, Amelia, who has been missing for years, Castiel asks Sam and Dean to help her. However, when they find out what took Amelia, they realize there is a chance Claire may not get her happy ending.', 42, '2015-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 21, 'Dark Dynasty', 'Dean and Sam investigate a bizarre murder and realize the killer bears the same tattoo as those from the Styne family. Meanwhile, Castiel acts as referee when Charlie and Rowena are forced to work together on the Book of the Damned. When Crowley discovers that his mother is missing, he turns to an old enemy for help.', 42, '2015-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 22, 'The Prisoner', 'When it comes to the Stynes, Dean decides to take matters into his own hands. Sam tries to come to terms with his decision.', 42, '2015-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 10), 23, 'Brother''s Keeper', 'Dean makes a shocking decision regarding the Mark of Cain that would change not only his life, but Sam’s too. Meanwhile, Crowley and Rowena face off and Castiel gets caught in the middle. ', 43, '2015-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 11, 'Season 11', 'Following the release of the Darkness, this season follows the Winchesters and their allies as they find themselves fighting the most powerful supernatural entity they''ve ever faced.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 1, 'Out of the Darkness, Into the Fire', 'Picking up where the finale left off, Sam and Dean must deal with the Darkness that has been unleashed. Castiel deals with the effects of Rowena’s spell and recalls his brutal battle with Crowley.', 42, '2015-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 2, 'Form and Void', 'Dean helps Jenna, the deputy he met after the Darkness fell, get back home safely and then sets off to help Sam deal with a town infected by a mysterious and deadly gas. However, when Jenna falls into dangerous hands, she calls Dean for help and Sam tells him to go back to her. Unfortunately for Sam, he isn''t able to handle the townspeople turned monsters as easily as he thought.', 42, '2015-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 3, 'The Bad Seed', 'While Rowena tries to consolidate her power to protect herself from the Winchesters, Sam and Dean search for a missing baby connected to the Darkness. Meanwhile, Castiel struggles to heal and Crowley tries to find a way to use the Darkness for his own personal gain.', 42, '2015-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 4, 'Baby', 'Seen entirely from the point of view of the Impala, Sam and Dean go on a road trip to fight monsters and demons.', 42, '2015-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 5, 'Thin Lizzie', 'Sam and Dean investigate a series of murders at a local B&B that also happens to be Lizzie Borden’s old home. When a local man, Len, tells them he saw a little girl around the B&B around the time of the murders, the brothers realize Amara may be responsible.', 42, '2015-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 6, 'Our Little World', 'Castiel seeks out Metatron’s help to stop the Darkness. However, Metatron is pretty happy with his new life as a freelance videographer for the local news and isn’t inclined to help the Winchesters or Castiel. Meanwhile, Crowley is losing his hold on Amara.', 42, '2015-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 7, 'Plush', 'Sheriff Donna calls Sam and Dean for help after a horrific murder with supernatural elements happens in her town. Sam continues to have visions and asks God for help, which frustrates Dean.', 41, '2015-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 8, 'Just My Imagination', 'Sam is shocked when his childhood imaginary friend Sully makes an unexpected appearance. Sam can’t understand why he’d see Sully now but what’s even more surprising is that Dean can see him, too. Flashbacks reveal young Sam’s friendship with Sully and why he needed him.', 42, '2015-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 9, 'O Brother Where Art Thou?', 'Amara unleashes her power on the local townspeople as she issues a shocking challenge. Dean tries to better understand the hold Amara has on him, while Sam and Crowley come up with a plan that could have disastrous consequences.', 42, '2015-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 10, 'The Devil in the Details', 'Now that he has Sam in the cage with him, Lucifer offers Sam a way out but it comes with a steep price. Dean and Castiel look into the angel smiting that could have killed Amara.', 42, '2016-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 11, 'Into the Mystic', 'Sam and Dean investigate a case where people are suffering violent deaths after hearing a mysterious song.', 42, '2016-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 12, 'Don''t You Forget About Me', 'Sam and Dean drop in on Jody Mills, Claire and Alex after receiving a panicked phone call from Claire. She believes the recent murders in town are supernatural and wants the boys’ help. However, Sheriff Mills tells Sam and Dean that Claire has been getting into trouble lately as she’s been attacking normal people and accusing them of being monsters.', 42, '2016-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 13, 'Love Hurts', 'Sam and Dean investigate a set of murders on Valentine’s Day and discover they are dealing with an ancient curse. Once kissed by the curse, the person is marked to die.', 42, '2016-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 14, 'The Vessel', 'Hoping to find a weapon powerful enough to defeat Amara, Dean convinces Castiel, who is still possessed by Lucifer, to send him back in time to 1944 to the fated submarine mission that sunk the Hand of God.', 42, '2016-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 15, 'Beyond the Mat', 'Sam and Dean attend a wrestling match to relive one of their fondest memories but when a wrestler turns up dead they suspect foul play.', 42, '2016-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 16, 'Safe House', 'A dangerous creature is accidentally released into an old house, attacking a mother and her child and leaving them both in a coma. Sam and Dean learn that Bobby and Rufus once tracked the same creature, so the Winchesters look to the past to come up with a plan to catch the monster.', 42, '2016-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 17, 'Red Meat', 'Sam and Dean battle a pair of werewolves who have captured two victims. Just as the brothers are about to win, one of the werewolves shoots Sam. Dean gets his brother and the victims out of the house but learns that a pack of werewolves are hot on their tail.', 41, '2016-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 18, 'Hell''s Angel', 'Lucifer takes a trip home and tries to assert himself into Heaven. Crowley tells Sam and Dean he has a way to take down Amara.', 42, '2016-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 19, 'The Chitters', 'In a small town in Colorado, mysterious disappearances happen every 27 years. Sam and Dean head to the town to investigate and meet two hunters who have a personal vendetta against these once-in-a-generation monsters.', 42, '2016-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 20, 'Don''t Call Me Shurley', 'Amara unleashes a dark fog on a small town, causing everyone to go mad. Dean and Sam realize this is a stronger version of the original black vein virus Amara previously unleashed. They team up with the sheriff to protect the town but their old remedy no longer works. Meanwhile, Chuck returns with an interesting proposal.', 42, '2016-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 21, 'All in the Family', 'Amara shows Dean how she’s torturing Lucifer. Worried for Castiel, Dean and Sam come up with a plan to rescue him from Amara’s clutches.', 42, '2016-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 22, 'We Happy Few', 'Sam and Dean face their biggest challenge yet. Rowena makes her move.', 42, '2016-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 11), 23, 'Alpha and Omega', 'God comes to a decision about Amara that has direct repercussions for Sam and Dean.', 42, '2016-05-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 12, 'Season 12', 'In the show''s eleventh season, the Winchesters found themselves battling an apocalyptic force: the Darkness. Now, rallying help from their allies - both human and supernatural - Sam and Dean are about to go toe-to-toe with the most destructive enemy they''ve ever seen. The question is, will they win? And at what price?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 1, 'Keep Calm and Carry On', 'Dean is overwhelmed as he comes face to face with his mom, Mary Winchester. Meanwhile, Sam is fighting for his life after Toni, from the Woman of Letters, shot him.', 42, '2016-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 2, 'Mamma Mia', 'Dean, Castiel and Mary have a lead on Sam and set out to rescue him. Dean is uncomfortable with putting Mary in danger but she insists on going along. Meanwhile, Crowley is tipped off that Lucifer has taken over the body of rock star Vince Vicente.', 42, '2016-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 3, 'The Foundry', 'When a crying baby leads to death in a mysterious abandoned house, Mary, Sam and Dean decide to investigate. Meanwhile, Castiel’s hunt for Lucifer leads him, begrudgingly, to partner up with Crowley.', 42, '2016-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 4, 'American Nightmare', 'Sam and Dean investigate a case that leads them to a devout religious family that lives off the grid. The brothers realize that the parents are hiding a huge secret that could destroy them all. Meanwhile, Dean struggles to accept Mary’s latest decision.', 42, '2016-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 5, 'The One You''ve Been Waiting For', 'After learning that the soul of Adolf Hitler has been trapped in a 1930’s gold pocket watch, Sam and Dean must act quickly to prevent a group of Nazi necromancers from resurrecting the Führer.', 41, '2016-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 6, 'Celebrating the Life of Asa Fox', 'When hunters gather together to celebrate the life and tragic death of one of their own, Sam, Dean, and Mary must take action when a demon starts picking off hunters one by one.', 42, '2016-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 7, 'Rock Never Dies', 'Lucifer realizes that as rock star Vince Vincente, he can get his fans to do whatever he wants. Thrilled with this power, Lucifer arranges to play a secret VIP concert in order to kill all of them. Sam, Dean and Castiel enter the underbelly of the music industry to try to stop him.', 42, '2016-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 8, 'LOTUS', 'Lucifer’s search for power and influence in a vessel lands him in the White House. The President of The United States unknowingly makes a deal with the devil, leading Sam, Dean, Castiel, Crowley and Rowena to band together to fight the Dark Lord.', 42, '2016-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 9, 'First Blood', 'After being arrested for the attempted assassination of the President of The United States, Sam and Dean must find a way out of an underground, government-run, detention facility in the middle of nowhere. Determined to find her sons, Mary and Castiel seek assistance from an unlikely source.', 42, '2017-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 10, 'Lily Sunder Has Some Regrets', 'Lily Sunder steeps herself in black magic, honing her powers for over a century, waiting to exact revenge on a band of angels that murdered her family. Sam and Dean must work quickly to stop Castiel from becoming her next victim.', 42, '2017-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 11, 'Regarding Dean', 'Sam enlists Rowena’s help to track down an old world, powerful family of witches after Dean gets hit by a spell that is rapidly erasing his memory.', 42, '2017-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 12, 'Stuck in the Middle (With You)', 'Mary asks Sam, Dean and Castiel for help on a case she’s working but neglects to mention the British Men of Letters are involved. When Mary is double crossed, everything is revealed.', 42, '2017-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 13, 'Family Feud', 'When Sam and Dean look into a murder at a museum, they learn a ghost from a merchant ship that sunk in 1723 may be at the heart of the mystery. After realizing “The Star” was the same ship that Crowley’s son Gavin McLeod should have been aboard, they enlist help from Rowena to track Gavin down. Kelly Kline, still pregnant with Lucifer’s child, takes refuge with a demon after an angel attempts to kill her.', 42, '2017-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 14, 'The Raid', 'A chance to take out a nest of vampires backfires when the alpha-vamp shows up and turns the tables on Mary and the British Men of Letters, who are doing their best to recruit Sam and Dean.', 42, '2017-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 15, 'Somewhere Between Heaven and Hell', 'An attack by an invisible hellhound at a campsite leads Sam  and Dean  to investigate the mysterious circumstances. Meanwhile, two of Crowley’s own personal demons uncover what he has been hiding. Castiel gets a lead on Kelly Kline.', 42, '2017-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 16, 'Ladies Drink Free', 'Sam and Dean let Mick Davies tag along on a case as they search for a werewolf. The three men run into Claire Novak, also working the hunt. However, the reunion is short lived after Claire is bitten and the brothers race to find a way to help her before she turns.', 42, '2017-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 17, 'The British Invasion', 'Sam and Dean get a lead on Kelly Kline’s whereabouts. Mick drops by the bunker unexpectedly and decides to join the hunt.', 42, '2017-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 18, 'The Memory Remains', 'Sam and Dean investigate a missing person’s case in a small town. The lead witness tells the Winchesters the attacker was a man with the head of a goat. Sam and Dean aren’t sure what to believe but when the witness goes missing they realize the town is hiding a dark secret.', 42, '2017-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 19, 'The Future', 'Sam comes up with a way to stop Lucifer’s baby but Castiel has something else in mind for Kelly. Dean is furious when he finds out someone stole the colt. Kelly makes a bold choice about the baby’s future.', 42, '2017-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 20, 'Twigs & Twine & Tasha Banes', 'Alicia Banes calls Mary for help after her mother, Tasha, goes missing. Sam answers Mary’s phone and he and Dean head out to help Alicia and her twin brother, Max, find their mother who was hunting a powerful witch. Meanwhile, Mary starts to have some doubts about the British Men of Letters.', 42, '2017-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 21, 'There''s Something About Mary', 'Sam and Dean are alarmed when they learn hunters are being killed by suspicious “accidents” all over the country. They decide it is best to find Mary and make sure she’s safe. Meanwhile, Toni is back in the states and she and Mary face off.', 42, '2017-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 22, 'Who We Are', 'Caught in a dangerous situation, Sam and Dean only have each other to rely on. Meanwhile, the fight between the American Hunters and the British Hunters comes to a head.', 42, '2017-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 12), 23, 'All Along the Watchtower', 'Lucifer battles Sam, Dean and Castiel for control of his unborn child.', 42, '2017-05-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 13, 'Season 13', 'Season 13 begins exactly where we left off, with Sam and Dean left to pick up the pieces after the loss of their mother, the demise of Crowley and the heartbreaking death of Castiel. The birth of Jack leaves the Winchester brothers with differing opinions on how to deal with a Nephilim. After being dragged into the breach, Mary must learn to survive Lucifer and an apocalyptic world.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 1, 'Lost and Found', 'Sam and Dean are left to pick up the pieces after the loss of their mother, the demise of Crowley and the heartbreaking death of Castiel. The birth of Jack leaves the Winchester brothers with differing opinions on how to deal with a Nephilim. After being dragged into the breach, Mary must learn to survive Lucifer and an apocalyptic world.', 42, '2017-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 2, 'The Rising Son', 'Sam and Dean begin to explore what Jack is capable of doing with his powers. An unexpected visit from Donatello alerts the boys to the fact that Jack will need more protection than the Winchesters can provide. There is a new Prince of Hell in town, Asmodeus, and with Lucifer out of the picture, he sets his sights set on Jack.', 42, '2017-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 3, 'Patience', 'When her friend is murdered by a wraith with a taste for psychics, Missouri enlists the help of Dean and Jody to protect her granddaughter, Patience, who has no idea she shares her grandmother’s trait and could be next on the wraith’s hit list. Meanwhile, Sam continues to work with Jack on learning how to control his powers.', 42, '2017-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 4, 'The Big Empty', 'When multiple patients of grief counselor Mia Vallens turn up dead, Dean, Sam and Jack investigate the mystery surrounding the murders and, each inadvertently, are forced to deal with unresolved grief of their own.', 42, '2017-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 5, 'Advanced Thanatology', 'While working on a case involving the ghost of a demented doctor, Sam and Dean get assistance from an unexpected source. Castiel finds his way back to the Winchesters.', 42, '2017-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 6, 'Tombstone', 'Castiel is reunited with Jack and together with Sam and Dean, they head to a sleepy old western town to investigate a murder. Dean gets to live out his boyhood fantasy when he comes face to face with a famous, gun-slinging outlaw.', 42, '2017-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 7, 'War of the Worlds', 'As Sam and Dean continue their search for Jack, with Asmodeus hot on their trail, they stumble across a familiar foe. Meanwhile, Lucifer manages to escape Michael’s grasp and finds himself an unlikely and mostly unwilling ally.', 42, '2017-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 8, 'The Scorpion and the Frog', 'Sam and Dean join the crew of a heist on behalf of a Crossroads Demon who has offered them a spell that can track Nephilim.', 42, '2017-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 9, 'The Bad Place', 'Jack, desperate to prove to Sam and Dean that he is good and that he can control his powers, enlists the help of a dreamcatcher named Kaia to help him find Mary Winchester and save her from the alternate universe. However, when plans go awry, the Winchester brothers are the ones who need saving.', 42, '2017-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 10, 'Wayward Sisters', 'When Sam and Dean go missing, Jody Mills calls Claire Novak, the rebellious rogue hunter, and tells her it is time to come home – they need to find the Winchesters. Claire returns and reunites with Alex Jones, who has stayed behind with Jody and tries to balance a “normal” life with being a part time hunter. While Jody is happy to have Claire home again, she’s plagued by Patience’s disturbing vision involving her adopted daughter. Claire and Alex search for Kaia Nieves, the dreamcatcher responsible for opening the rift that Sam and Dean went through, as she holds the key to their whereabouts. Jody calls her friend, Donna Hanscum, to round out the team and the women head off on the most important hunt of their lives.', 42, '2018-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 11, 'Breakdown', 'Donna calls Sam and Dean for help after her niece, Wendy, goes missing. The three hunters discover Wendy was kidnapped by a man who sells human parts to monsters in a grotesque online auction and race to save her before it is too late.', 42, '2018-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 12, 'Various & Sundry Villains', 'Dean falls victim to a couple of witches, sisters Jamie and Jennie Plum, who manage to steal a powerful book of spells from the Winchester brothers. When Sam and Dean go after the book, they get help from a powerful and surprising ally when Rowena, back from the dead, intervenes to assist them.', 42, '2018-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 13, 'Devil''s Bargain', 'Sam, Dean and Castiel search for Lucifer who, meanwhile, strikes an unlikely deal with a local faith healer named Sister Jo. Asmodeus inches closer to finding Jack.', 42, '2018-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 14, 'Good Intentions', 'Jack and Mary manage to escape Michael’s clutches and end up finding an ally in “apocalyptic world” Bobby Singer. Meanwhile, Sam, Dean and Castiel continue to search for a way to open a breach, not realizing that one of their own may be working against them and costing them precious time.', 42, '2018-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 15, 'A Most Holy Man', 'Sam and Dean are close to collecting everything they need to open a rift into the Apocalyptic World and possibly rescuing Mary and Jack. The one missing ingredient leads the Winchesters to a black market for religious relics where everything is not always as it seems.', 42, '2018-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 16, 'ScoobyNatural', 'Sam, Dean and Castiel are transported into the animated world of Scooby Doo where they join forces with the Scooby gang to solve a ghostly mystery.', 42, '2018-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 17, 'The Thing', 'Sam and Dean continue to collect the pieces necessary to open a rift to the other world in order to save their family. Their latest quest leads them to a Men of Letters bunker from the 1920s and a hungry God from another dimension. Meanwhile, Ketch makes a shocking decision about Gabriel after an unruly encounter with Asmodeus.', 42, '2018-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 18, 'Bring ''em Back Alive', 'Lucifer rules over heaven but things aren’t going exactly as planned, exasperating his first lady, Jo. Sam and Castiel are perplexed by the return of Gabriel. Meanwhile, Dean gets one step closer to finding Mary and Jack.', 42, '2018-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 19, 'Funeralia', 'Sam and Dean must stop Rowena, who is on a deadly mission. Meanwhile, Castiel looks to heaven to recruit angels for an impending invasion but is shocked by not only what he finds, but who.', 42, '2018-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 20, 'Unfinished Business', 'Gabriel is back and drags Sam and Dean into his plot for revenge on the demigods who sold him to Asmodeus. Meanwhile, Jack''s inflating confidence leads to reckless decisions that could put others in harm''s way.', 42, '2018-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 21, 'Beat the Devil', 'Sam, Dean, Castiel and Gabriel must work together if they have any hope of bringing Mary and Jack home. Meanwhile, Rowena’s encounter with Lucifer may alter the outcome of the journey for one of our heroes.', 42, '2018-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 22, 'Exodus', 'Sam and Dean devise a plan that will save innocent lives. Meanwhile, Jack continues to wrestle with the consequences of his decisions.', 42, '2018-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 13), 23, 'Let the Good Times Roll', 'Our heroes, Sam and Dean Winchester, continue to be tested in the battle between good and evil, but one impulsive decision could alter the lives of one the brothers forever.', 42, '2018-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 14, 'Season 14', 'The season follows Sam and Dean who, along with Jack and Castiel, try to take down the archangel Michael from another world, and learn something bigger is at hand.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 1, 'Stranger in a Strange Land', 'Sam enlists everyone’s help in trying to track down Dean, who can literally be anywhere. Meanwhile, Castiel may be in over his head after meeting up with an unreliable source. After being drained of his grace, Jack is adjusting to life as a human, learning new skills and figuring out how he fits in to this world of hunters.', 42, '2018-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 2, 'Gods and Monsters', 'Sam finds a clue to Dean’s whereabouts, so he, Mary and Bobby set out to investigate. Castiel imparts some sage advice on Jack, who, still desperate to belong, seeks out a familial connection.', 41, '2018-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 3, 'The Scar', 'Still trying to solve the mystery of what happened to Dean, Sam enlists the help of Sheriff Jody Mills who may unknowingly already be on the case. Castiel continues to be a father figure to Jack, who surprises even himself, when a life is on the line.', 42, '2018-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 4, 'Mint Condition', 'Dean continues to struggle. Meanwhile, Sam must think fast when action figures come to life, and our heroes find themselves living in a real-life horror movie.', 42, '2018-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 5, 'Nightmare Logic', 'After a hunt gone wrong leaves Maggie’s whereabouts unknown, Sam, Dean, Mary and Bobby race to find her, but what they find are their own worst nightmares.', 42, '2018-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 6, 'Optimism', 'Sam and Charlie team up to get to the bottom of a string of random disappearances. Meanwhile, Jack believes that he has found a case and convinces Dean to partner-up with him on the hunt.', 42, '2018-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 7, 'Unhuman Nature', 'Sam and Castiel track down a Shaman, who may be able to help a friend. Nick continues to spiral down a dark path as he looks for answers surrounding the deaths of his wife and son. Jack turns to Dean for help enjoying the human experience.', 42, '2018-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 8, 'Byzantium', 'When Sam and Dean join forces with an unexpected ally, the outcome will alter the course of two lives. Meanwhile, Heaven faces an attack from a dark force, driving Castiel to make an enormous sacrifice to make things right.', 42, '2018-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 9, 'The Spear', 'Sam and Dean enlist the help of their pal Garth to gain inside information on what Michael may be planning. The brothers split up to each go after weapons that can aid in their fight against the Archangel, but this may be a fight our heroes cannot win.', 41, '2018-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 10, 'Nihilism', 'Michael has re-taken control of Dean as his army of monsters continues to move in on our heroes. Sam devises a plan to try and reach Dean and stop Michael before anyone else has to die.', 42, '2019-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 11, 'Damaged Goods', 'Dean spends some bonding time with Mary and Donna. Nick finally finds the answer he has been searching for. Sam is left to make an unimaginable choice.', 42, '2019-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 12, 'Prophet and Loss', 'Sam and Dean must figure out how to stop the bloodshed when Donatello, who, in his current condition, is inadvertently scrambling the order of future prophets. Nick comes face to face with his past.', 42, '2019-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 13, 'Lebanon', 'Sam and Dean look to occult lore for a solution to their latest problem, but instead of a resolution, they find much more than either of them had anticipated.', 42, '2019-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 14, 'Ouroboros', 'Sam and Dean enlist the help of Rowena to track down a demi god who feasts on human flesh. The challenge of keeping Michael at bay is proving to be more difficult than originally anticipated.', 42, '2019-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 15, 'Peace of Mind', 'Sam and Castiel follow a case to a picturesque little town in Arkansas, only to find out nothing is as idyllic as it appears to be. Dean and Jack take a road trip to visit an old friend.', 42, '2019-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 16, 'Don''t Go in the Woods', 'Sam and Dean are baffled when they come up against a monster they have never heard of before. Jack does his best to impress a new group of friends.', 41, '2019-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 17, 'Game Night', 'Sam and Dean race to help a friend in need. Meanwhile, Mary is concerned for Jack’s well-being, and Castiel enlists help from Jo/Anael to track down a miracle.', 42, '2019-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 18, 'Absence', 'Sam and Dean continue to worry about the condition of Jack’s soul.', 42, '2019-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 19, 'Jack in the Box', 'Sam, Dean and Castiel investigate a string of suspicious deaths that have a biblical element to them.', 42, '2019-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 14), 20, 'Moriah', 'Sam, Dean and Castiel are thrown into an epic battle. Meanwhile, Jack becomes disenchanted with all the lies, and an old friend from the past shows up.', 42, '2019-04-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')), 15, 'Season 15', 'The Winchester brothers'' epic journey comes to a thrilling and terrifying close in Season 15.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 1, 'Back and to the Future', 'Picking up here we left off last season, Sam, Dean and Castiel are left to defend the world after all the souls in hell have been released and are back on Earth and free to kill again.', 41, '2019-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 2, 'Raising Hell', 'Sam, Dean and Castiel call on Rowena to help keep the evil souls at bay and get an unexpected assist from Ketch.', 42, '2019-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 3, 'The Rupture', 'Sam and Dean together with Rowena work tirelessly to keep all of hell from breaking loose. Castiel cannot forgive an arrogant betrayal.', 41, '2019-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 4, 'Atomic Monsters', 'Sam and Dean investigate the mysterious death of a girl and the disappearance of another.', 42, '2019-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 5, 'Proverbs 17:3', 'Sam and Dean’s routine case turns out to be anything but.', 42, '2019-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 6, 'Golden Time', 'Sam and Dean are visited by an old friend. Castiel investigates the disappearance of a local teen.', 42, '2019-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 7, 'Last Call', 'Dean goes off on his own to take on a case. Meanwhile, Castiel has an idea of how he can help Sam track down God.', 42, '2019-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 8, 'Our Father, Who Aren''t in Heaven', 'Sam, Dean and Castiel’s continued search for a way to defeat Chuck leads them to unexpected places and toward unlikely allies.', 42, '2019-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 9, 'The Trap', 'Sam and Eileen are faced with the brutal truth. Meanwhile Dean and Cass work together in the hopes of getting a step ahead of Chuck.', 42, '2020-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 10, 'The Heroes'' Journey', 'Sam and Dean hit the road to help an old friend, but it appears that their luck may have finally run out and they are the ones who may be in need of rescue.', 42, '2020-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 11, 'The Gamblers', 'Sam and Dean press their luck in a winner-takes-all game of pool. Meanwhile, Castiel hunts down a would-be murderer, but not for reasons one might think.', 42, '2020-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 12, 'Galaxy Brain', 'Sam and Dean respond to a frantic call and together along with Castiel, Jack and Jody, assist in an extraordinary and heartbreaking rescue. Billie surprises everyone with a visit to the bunker.', 42, '2020-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 13, 'Destiny''s Child', 'A search for the one thing that may give the Winchesters an edge against God leads Sam and Dean to Jo’s door and to a secret that may have died with Ruby. Meanwhile, Castiel asks Jack to do the unthinkable to help the brothers in their quest.', 42, '2020-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 14, 'Last Holiday', 'Sam and Dean discover a wood nymph living in the bunker who is determined to protect her family, at any cost.', 42, '2020-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 15, 'Gimme Shelter', 'Castiel and Jack work a case involving members of a local church. Meanwhile, Sam and Dean go off in search of Amara.', 42, '2020-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 16, 'Drag Me Away (From You)', 'Sam and Dean are asked to investigate the murder of a childhood friend, calling them back to a motel from their past and perplexing the brothers with a case they thought was solved a long time ago.', 42, '2020-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 17, 'Unity', 'Dean hits the road with Jack who needs to complete a final ritual in the quest to beat Chuck. A difference of opinion leaves Sam and Castiel behind looking for answers to questions of their own.', 42, '2020-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 18, 'Despair', 'With the plan in full motion, Sam, Dean, Castiel and Jack fight for the good of the common goal.', 41, '2020-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 19, 'Inherit the Earth', 'Everything is on the line as the battle against God continues. A familiar face returns to join the fight.', 42, '2020-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0460681')) AND numero_temporada = 15), 20, 'Carry On', 'It''s the final ride for the Winchesters saving people and hunting things.', 42, '2020-11-19');
