INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0475784', 'Westworld', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0003557'), 'SERIE', 'At the intersection of the near future and the reimagined past, waits a world in which every human appetite can be indulged without consequence.', '2016-01-01', 'https://m.media-amazon.com/images/M/MV5BMjM2MTA5NjIwNV5BMl5BanBnXkFtZTgwNjI2OTMxNTM@._V1_.jpg');
