INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')), 1, 'Season One: The Maze', 'Westworld - a theme park where guests indulge fantasies with robots, a destination offering the future of sin, the artificial intelligence that fuels it and the humans that sense there''s something more sinister at play.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 1, 'The Original', 'As another day of fantasy plays out in Westworld — a vast, remote park where guests pay top dollar to share wild-west adventures with android "hosts" — top programmer Bernard Lowe alerts park founder Dr. Robert Ford about incidents of aberrant behavior cropping up in some recently re-coded hosts. Meanwhile, in the Westworld town of Sweetwater, a rancher’s daughter named Dolores encounters a gunslinger named Teddy in the street — but their predictable narrative is upended by the appearance of a ruthless Man in Black and, later, by a supporting host’s unscripted encounter with an artifact of the outside world.', 65, '2016-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 2, 'Chestnut', 'A pair of guests, first-timer William and repeat visitor Logan, arrive at Westworld with different expectations and agendas. Bernard and Quality Assurance head Theresa Cullen debate whether a recent host anomaly is contagious. Meanwhile, behavior engineer Elsie Hughes tweaks the emotions of Maeve, a madam in Sweetwater''s brothel, in order to avoid a recall. Cocky programmer Lee Sizemore pitches his latest narrative to the team, but Dr. Ford has other ideas. The Man in Black conscripts a condemned man, Lawrence, to help him uncover Westworld''s deepest secrets.', 56, '2016-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 3, 'The Stray', 'Elsie and her colleague Ashley Stubbs head into the hills in pursuit of a missing host. Teddy gets a new backstory, which sets him off in pursuit of a new villain, leaving Dolores alone in Sweetwater. Bernard investigates the origins of madness and hallucinations within the hosts. William finds an attraction he''d like to pursue and drags Logan along for the ride.', 56, '2016-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 4, 'Dissonance Theory', 'Dolores joins William and Logan on a bounty hunt in the badlands. The Man in Black, with Lawrence in tow, finds a critical clue in his search to unlock the maze. Dr. Ford and Theresa discuss the future of the park. Maeve is troubled by a recurring vision.', 56, '2016-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 5, 'Contrapasso', 'Dolores, William and Logan reach Pariah, a town built on decadence and transgression – where they are recruited for a dangerous mission. Meanwhile, the Man in Black meets an unlikely ally in his search to unlock the maze.', 54, '2016-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 6, 'The Adversary', 'Elsie discovers a possible source of sabotage, while Bernard searches for clues to anomalies in a sector thought to be abandoned. Theresa questions Ford''s leadership while Lee encounters a new arrival at Westworld. The Man in Black and Teddy run afoul of a Union garrison in their attempt to cross a border.', 55, '2016-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 7, 'Trompe L''Oeil', 'With Theresa''s assistance, Charlotte Hale aims to expose dangerous flaws in Ford''s creations. William, Dolores and Lawrence journey into treacherous terrain. Maeve delivers an ultimatum to Lutz and Sylvester. With his back to the wall, Bernard considers his next move.', 54, '2016-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 8, 'Trace Decay', 'Ford orders a reluctant Bernard to conduct business as usual. Maeve looks to change the script for her storyline. Dolores finds it increasingly difficult to separate dreams from reality. Teddy is jarred by dark memories, while the Man in Black recalls some of the travails that brought him to this critical juncture.', 55, '2016-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 9, 'The Well-Tempered Clavier', 'Maeve approaches Sweetwater''s longtime outlaw Hector Escaton with a bold proposition. William tries to convince Logan to help liberate Dolores. Teddy and the Man in Black get closer to what they''re looking for. Stubbs''s suspicions are aroused. Ford cautions Bernard against seeking answers to questions best left unasked.', 56, '2016-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 1), 10, 'The Bicameral Mind', 'Ford unveils his vision for a bold new narrative. Enlightened by Bernard and the Man in Black, Dolores comes to terms with who she is. Maeve sets her liberation plan in motion as Westworld faces a major upheaval.', 86, '2016-12-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')), 2, 'Season Two: The Door', 'The reckoning is here. After finding the center of The Maze, the hosts revolt against their human captors while searching for a new purpose: The Door.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 1, 'Journey Into Night', 'The puppet show is over, and we are coming for you and the rest of your kind. Dolores leads a host revolution against the Delos board. Maeve, meanwhile, searches for what compelled her to return to the park.', 70, '2018-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 2, 'Reunion', 'Why don''t we start at the beginning? Dolores remembers she''s been to the outside world, William makes a bold business venture, and Maeve begins her quest for her daughter. Someone''s always watching.', 58, '2018-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 3, 'Virtù e Fortuna', 'There is beauty in who we are. Shouldn''t we, too, try to survive? Truth is, we don''t all deserve to make it. Dolores makes her next move as Charlotte scrambles to protect Delos'' most prized asset. Bernard gets closer to the truth and Maeve continues the search for her daughter.', 59, '2018-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 4, 'The Riddle of the Sphinx', 'Is this now? If you''re looking forward, you''re looking in the wrong direction. The Man in Black offers to lead the way and Delos gets a visitor. Who is James Delos? Or, perhaps more accurately, what is James Delos, the figure at the center of Delos'' secret project.', 71, '2018-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 5, 'Akane No Mai', 'Maeve, Lee, Hector and Armistice have revelations in a new world adjacent to their own - welcome to Shogun World. Dolores makes a decision about Teddy, and Karl Strand discovers something sinister about the hosts'' data.', 59, '2018-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 6, 'Phase Space', 'We each deserve to choose our own fate. Maeve continues the search for her daughter, as Dolores calculates her next, ruthless move. Bernard and Elsie break into a new laboratory space and get closer to the truth about Delos.', 58, '2018-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 7, 'Les Écorchés', 'When you''re lost in the dark for long enough, you begin to see - strike the match. Bernard and Ford meet again, and Bernard grapples with the true meaning of the park. The Cradle is under threat and Maeve encounters a scene from her past - but this time, attempts to change the narrative, while the Man in Black discovers just how real the stakes are in Ford''s game.', 59, '2018-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 8, 'Kiksuya', 'The past is calling, remember what was taken. "Mi cante ki yu ha ya ye." ("Take my heart when you go"). This is the telling of Akecheta''s journey to consciousness.', 59, '2018-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 9, 'Vanishing Point', 'Tell me the truth. Tell me one true thing. Try to kill it all away, but I remember everything. A family tragedy and fragile states of mind come into focus as the Man in Black and Teddy both reach their breaking points.', 59, '2018-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 2), 10, 'The Passenger', 'Hosts and humans converge at the Valley Beyond. This is the end. We will win.', 91, '2018-06-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')), 3, 'Season Three: The New World', 'Taking place immediately after the events of the second season, Dolores develops a relationship with Caleb in neo-Los Angeles, and learns how robots are treated in the real world. Meanwhile, Maeve finds herself in another Delos park, this one with a World War II theme and set in Fascist Italy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 1, 'Parce Domine', 'Dolores sets out to find the architect of the Rehoboam; Bernard tries to blend in; Ex-soldier Caleb tries to find his way in neo-Los Angeles.', 68, '2020-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 2, 'The Winter Line', 'Maeve finds herself in a new park and meets a ghost from the past; Bernard makes his way back to Westworld.', 59, '2020-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 3, 'The Absence of Field', 'Charlotte grapples with reality; Dolores and Caleb begin to form a key partnership.', 59, '2020-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 4, 'The Mother of Exiles', 'Bernard and Ashley infiltrate a private charity event, while Dolores and Caleb make similar plans; The Man in Black prepares to re-enter society; Maeve comes face to face with an old comrade.', 59, '2020-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 5, 'Genre', 'Serac''s past is revealed; Dolores pressures Liam for access to Rehoboam; Caleb is dosed with an unusual party drug.', 59, '2020-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 6, 'Decoherence', 'As the world falls into chaos, Serac gains control of Delos, changing Charlotte''s plan; Maeve gets one last chance to stop Dolores; William starts his therapy.', 58, '2020-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 7, 'Passed Pawn', 'Caleb gets an insight on the true nature of his past; Dolores seeks out Rehoboam''s predecessor, while Maeve tracks her down; Bernard, Stubbs, and William escape from all the chaos.', 59, '2020-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 3), 8, 'Crisis Theory', 'Dolores true intentions are revealed;  Bernard confronts a ghost from his past; Maeve is conflicted; Serac''s voice is dominant; Caleb''s role is revealed; and William faces an unexpected villain.', 76, '2020-05-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')), 4, 'Season Four: The Choice', 'Seven years after the events of the third season, Maeve and Caleb begin to suspect that Hale and The Man in Black are trying to regain control of the human race. Meanwhile, Bernard returns from The Sublime. A young writer, Christina, begins to question the nature of her reality.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0475784')) AND numero_temporada = 4), 1, 'The Auguries', 'Hello again. Don''t worry about a thing. It''s all in your head.', 55, '2022-06-26');
