INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 1, 'The Gang Gets Racist', 'The guys hire Dee''s friend, Terrell to promote the bar.  Meanwhile, Charlie tries to prove that he is not a racist.', 23, '2005-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 2, 'Charlie Wants an Abortion', 'A girl from Charlie''s past reveals they have a child together.  Mac sees the benefits in being a pro-life advocate, while Dennis uses an abortion rally to meet women.', 23, '2005-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 3, 'Underage Drinking: A National Concern', 'After reminiscing about high school, the guys conclude that it would be a public service if they allowed teens to drink in the bar, thus providing a safe and controlled environment for teens to party. Feeling that she missed out on a lot as a teenager due to having to wear a brace for her scoliosis, Dee begins dating a high school jock.', 23, '2005-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 4, 'Charlie Has Cancer', 'After discovering that he might have cancer, Mac and Dennis attempt to find a woman who will sleep with Charlie.  In the midst of their search, Mac falls in love with a transsexual he meets at the bar named Carmen.  Overwhelmed by the extra workload that she had to take on since Charlie has taken a leave of absence, Dee tries to get Dennis to hire a recently out of work actress friend to help out.', 23, '2005-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 5, 'Gun Fever', 'The guys buy a gun after the bar''s safe is stolen.', 22, '2005-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 6, 'The Gang Finds a Dead Guy', 'Mac and Dennis befriend a patron found dead at their bar in order to win the affection of his granddaughter.', 23, '2005-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 1), 7, 'Charlie Got Molested', 'Charlie and Mac''s old high school gym teacher is accused of molestation.', 19, '2005-09-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 1, 'Charlie Gets Crippled', 'An accident that puts Charlie in a wheelchair opens up a window of possibilities for the gang. Meanwhile, Dennis and Dee’s estranged father reenters their life in hopes of starting anew with his children and soon discovers that he enjoys the lifestyle of their friends.', 23, '2006-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 2, 'The Gang Goes Jihad', 'When the gang learns that they are in danger of losing their bar due to a zoning mishap, they resort to some outlandish and extreme methods to prevent that from happening. Meanwhile, Frank isn’t too happy when his wife returns to town.', 23, '2006-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 3, 'Dennis and Dee Go on Welfare', 'After quitting their job due to Frank''s continuing interference, Dennis and Dee decide to seek alternative income by going on welfare. Meanwhile, Mac and Charlie must now bear the consequences of their friends’ departures from the business.', 23, '2006-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 4, 'Mac Bangs Dennis'' Mom', 'Barbara hooks up with Mac to make Frank jealous, which leads to retaliation from Dennis.', 24, '2006-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 5, 'Hundred Dollar Baby', 'Frank runs into an old adversary at the gym when he begins teaching Dee to box after she was robbed. Hoping to make some extra money on the side, Mac and Dennis make preparations for Charlie to compete in an underground street fighting match.', 24, '2006-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 6, 'The Gang Gives Back', 'After being arrested for arson the gang is sentenced to do community service. Frank makes an effort to connect more with Dennis. Meanwhile, Charlie is also ordered to attend AA where he makes a startling discovery that might be beneficial in his ongoing quest to hook up with the Waitress.', 23, '2006-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 7, 'The Gang Exploits a Miracle', 'Mac and Dee become uncomfortable when the rest of the guys decide to make some extra money by exploiting the similarities between a water stain and the Virgin Mary. A reunion with someone from the past, stirs up forbidden feelings within Dee.', 23, '2006-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 8, 'The Gang Runs for Office', 'Driven by Frank''s insight into the world of politics, Dennis pursues a political career by running for office.', 24, '2006-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 9, 'Charlie Goes America All Over Everybody''s Ass', 'Dennis and Mac make a decision to take away all rules concerning moral and behavioral etiquette at Paddy''s after an argument about the Constitution. Frank uses the decision and it''s following consequences to his own gain. Meanwhile, Charlie tries to convey his love for America by protesting while Dee attempts to reaffirm her goal of being an actress.', 22, '2006-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 2), 10, 'Dennis and Dee Get a New Dad', 'Dee receives e-mails from a stranger claiming to be her and Dennis'' real father. Meanwhile, Mac decides to visit his father who is in prison.', 24, '2006-08-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 1, 'The Gang Finds a Dumpster Baby', 'Dennis joins up with an environmentalist group, but his altruistic intentions quickly sour when he''s snubbed by the activists. Dee and Mac decide to raise a baby they find in the dumpster, but quickly find out that it''s not nearly as fun as they thought it would be, and Frank and Charlie take the concept of recycling a bit too far.', 23, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 2, 'The Gang Gets Invincible', 'Mac, Dennis and Dee try out for the Philadelphia Eagles.  Also interested in becoming an Eagle is Liam and Ryan McPoyle''s brother, Doyle.', 22, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 3, 'Dennis and Dee''s Mom Is Dead', 'After Barbara''s death, Dee and Frank are unhappy to learn that she left them both out of the will, while Dennis inherits the mansion which he plans to turn into a party pad.', 23, '2007-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 4, 'The Gang Gets Held Hostage', 'The McPoyles hold the entire gang hostage at Paddys while Frank is busy searching for his will in the air ducts.', 23, '2007-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 5, 'The Aluminum Monster vs. Fatty Magoo', 'Dee is shocked to learn that an overweight social outcast from her High School has become a rich and skinny fashion designer.', 23, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 6, 'The Gang Solves the North Korea Situation', 'A Korean restaurant owner threatens to get Paddy''s kicked off the route for the city''s annual pub crawl. The gang''s response: War.', 23, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 7, 'The Gang Sells Out', 'The gang agrees to sell Paddys when they get an offer that is too good to refuse, but it forces the bar''s non-partners, Dee and Charlie to find new jobs.', 23, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 8, 'Frank Sets Sweet Dee On Fire', 'Mac teams up with Frank and Charlie to create a public access newscast after he misses his chance at fame in the news. Meanwhile, Dennis and Dee try to make it big in the club scene.', 23, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 9, 'Sweet Dee''s Dating a Retarded Person', 'Dee gets involved with a famous local rapper who might be mentally challenged, and whose success inspires the rest of the gang to start a band.', 21, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 10, 'Mac Is a Serial Killer', 'After Mac arrives to the bar with scratches on his neck and exhibiting strange behavior, Frank comes to the conclusion that he is the serial killer terrorizing young women in Philadelphia. Frank sets out with his trusty chainsaw and a doubtful Charlie to find evidence to implicate Mac in the murders. In search of another suspect, Dennis and Dee do a little role-playing in order to help themselves better understand who they might be dealing with.', 23, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 11, 'Dennis Looks Like a Registered Sex Offender', 'When Dennis is mistaken for a recently released child molester, he is more bothered by the fact that the guy is overweight rather than him being a sex offender.  Meanwhile, Mac tries once again to bond with his ex-con father, who shows an interest in Dee.', 23, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 12, 'The Gang Gets Whacked (1)', 'After stumbling upon a kilo of cocaine, the gang is forced to pay off a $25,000 debt to the mob. Mac becomes a mob informant, while Frank pimps out Dennis as an escort at the local country club. Charlie stumbles upon an opportunity to sell illegal narcotics.', 21, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 13, 'The Gang Gets Whacked (2)', 'While paying off their debt to the mob, Charlie and Dee try to find a way to make fake cocaine in order to fool them, while Dennis ranks in thousands of dollars being pimped out at the local country club. Mac realizes his position as a mob informant isn''t being utilized to its full potential.', 22, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 14, 'Bums: Making a Mess All Over the City', 'Mac and Dee become vigilantes in order to remove the homeless from their neighborhood, while Frank and Dennis impersonate police officers.', 21, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 3), 15, 'The Gang Dances Their Asses Off', 'In the season finale, Charlie accidentally puts Paddy''s up as a prize for a dance marathon, which prompts the gang to enter the competition in order to save their bar.', 22, '2007-11-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 1, 'Mac and Dennis: Manhunters', 'Charlie and Dee have been stealing Frank''s delicious meats, so Frank leaves out human meat to get back at them. Driven by their cannibalistic needs, Charlie and Dee go in search of human flesh. Mac and Dennis harass Frank for hunting defenseless animals and think it would be much more badass to hunt something that could fight back ... like a human.', 21, '2008-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 2, 'The Gang Solves the Gas Crisis', 'Charlie, Mac, and Dennis formulate a plan to take advantage of the rising gas prices. By purchasing excess amounts now, they can sell it in the future and profit. As usual, things don''t go as planned. Dee is also out to make money when she learns that Bruce is going to give the family fortune to a Muslim cultural center. She and Frank try to stop him and get the cash for themselves.', 22, '2008-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 3, 'America’s Next Top Paddy’s Billboard Model Contest', 'Due to the gang''s latest "business expenses," Paddy''s is in dire need of money. Frank buys a billboard to advertise the bar, but Dee decides to create a viral video to post on YouTube for promotion. Charlie quickly joins her, leaving Frank and Mac to hold a contest for some hot models to feature on the billboard. Naturally, Dennis joins the competition to prove his worth.', 21, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 4, 'Mac’s Banging the Waitress', 'Charlie finds out that the waitress has been seeing someone. He calls on Mac, his so-called best friend, to find out more information about the guy and to beat him up. However, it turns out that Mac is the guy the waitress has supposedly been seeing. Dennis, heartbroken that he''s not Charlie''s best friend, tries to win him over.', 21, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 5, 'Mac and Charlie Die (1)', 'Part 1 of 2. Mac and Charlie fake their deaths to avoid the wrath of Mac''s father who was released from prison and is out for vengeance.', 21, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 6, 'Mac and Charlie Die (2)', 'Part 2 of 2. Dennis, Frank, and Dee find unique ways of coping with the apparent loss of their friends.', 21, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 7, 'Who Pooped the Bed?', 'Charlie and Frank awake to find poop in their bed. Neither will confess to being the owner, so they, Mac, and Dennis try to scientifically deduce who dropped the deuce. Dee wants to do something a bit more sophisticated, so she invites the waitress and Artemis to a girls'' night out.', 21, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 8, 'Paddy’s Pub: The Worst Bar in Philadelphia', 'A newspaper critic is kidnapped by the gang after he calls Paddy''s pub the worst bar in Philadelphia.', 21, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 9, 'Dennis Reynolds: An Erotic Life', 'After discovering Dennis'' erotic memoir, Mac and Frank attempt to make some money off of it. Meanwhile, Dee and Charlie decide to spend a day in each other''s shoes.', 23, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 10, 'Sweet Dee Has a Heart Attack', 'After Dee suffers a heart attack, she and Dennis try to live a healthier lifestyle. Meanwhile, Charlie and Mac take corporate jobs to get health insurance.', 21, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 11, 'The Gang Cracks the Liberty Bell', 'The gang fudge history by claiming that Paddy''s Pub was responsible for cracking the Liberty Bell in an attempt to turn their dive into a Philadelphia landmark.', 21, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 12, 'The Gang Gets Extreme: Home Makeover Edition', 'Hoping to make their own dreams come true, the gang sets out to give an unexpected family an extreme home makeover.', 21, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 4), 13, 'The Nightman Cometh', 'In the season finale, Charlie gets the gang to help him put together a rock opera based on his song "Nightman."', 21, '2008-11-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 5), 1, 'The Gang Exploits the Mortgage Crisis', 'Dennis, Mac, and Frank go into real estate, while Dee sets out to be a surrogate for a wealthy couple. Charlie gets into it with an attorney over the law.', 22, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 5), 2, 'The Gang Hits the Road', 'The gang tries to expand their horizons by going on a road trip to the Grand Canyon.', 21, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 5), 3, 'The Great Recession', 'With a shantytown taking shape outside, Mac and Dennis try to keep Paddy''s going in tough times. Meanwhile, Frank and Dee start a family business.', 21, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 5), 4, 'The Gang Gives Frank an Intervention', 'Frank''s behavior is more bizarre than usual---so bizarre that even the gang notice---so they decide to stage an intervention.', 21, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 5), 5, 'The Waitress Is Getting Married', 'The waitress is getting married, Dee is jealous that she''s beating her to the altar, so she tries to derail the wedding.', 21, '2009-10-15');
