INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 9), 5, 'Mac Day', 'Everyone in the gang gets a day to do what they want while everyone else in the gang must participate willingly. This is Mac''s Day... and its got twice the "Mac".', 22, '2013-10-02');
