INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 12, 'Season 12', 'In season twelve, Mac, Dennis, Charlie, Dee and Frank tackle all new adventures that include going to a waterpark, dealing with a Wolf Cola PR nightmare, and actually spending a whole day tending bar!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 1, 'The Gang Turns Black', 'After an electric heating blanket shorts out while the gang watches the Wiz they look in the mirror and realize they''ve turned black. They have to figure out how to get back to being themselves by going through all the classic body switch movie shenanigans they encounter.', 22, '2017-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 2, 'The Gang Goes to a Water Park', 'The gang takes a trip to a local waterpark. Dennis takes on a protégé. Frank and Charlie are determined to ride every ride. Mac and Dee get stuck in a tube slide.', 19, '2017-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 3, 'Old Lady House: A Situation Comedy', 'Charlie thinks Mac''s mom is holding his mom hostage so the gang installs spy cameras in their house. They discover the moms are quite entertaining once Dennis makes edits to the footage.', 21, '2017-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 4, 'Wolf Cola: A Public Relations Nightmare', 'Franks Fluids LLC is in big trouble after a news segment. Dee and Dennis help with the PR nightmare and Charlie and Mac work on a scheme to make Fight Milk the official drink of the UFC.', 20, '2017-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 5, 'Making Dennis Reynolds a Murderer', 'A cat-woman is killed and Dennis becomes the main suspect.', 22, '2017-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 6, 'Hero or Hate Crime?', 'The gang fight over a lottery ticket and seek out an arbitrator to decide a rightful owner, who also decides if Frank is a hero or hate monger.', 22, '2017-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 7, 'PTSDee', 'Dee dates a male stripper and tries to prove her worth after learning she''s his "rock bottom." Elsewhere: Mac and Frank get sucked into a VR war game, leading Mac to develop a case PTSD.', 22, '2017-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 8, 'The Gang Tends Bar', 'It’s Valentine’s Day and Paddy’s is packed with customers. Dennis implores the gang to do one day of actual work but everyone else is distracted by a mystery crate Cricket spotted in the alley. Eventually, the gang becomes convinced Dennis really wants them to work on their relationships and everyone shares their grievances without much resolution.', 22, '2017-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 9, 'A Cricket''s Tale', 'We get to see a typical day in Cricket''s world and then a possible redemption when his family intervenes. Will Cricket finally move on from the gang, finding love in the process? Will Cricket go from filthy beast to his former self, Matthew Mara?', 18, '2017-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 12), 10, 'Dennis'' Double Life', 'Dennis reveals he has a baby after his Wade Boggs layover in North Dakota and the gang try to help him get out of the jam, but their suggestions border on the extreme.', 22, '2017-03-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 13, 'Season 13', 'The Gang returns... mostly... in Season 13. Mac, Charlie, Dee, and Frank return to their duplicitous, scheming ways at Paddy’s Pub, while Dennis takes on the new role of father in North Dakota. Even without Dennis, the Gang has its hands full as Charlie hopes to have a child with The Waitress, Mac sets out to understand his newfound sexuality, Dee takes feminism to new heights, and Frank goes to great lengths for the Gang to experience the greatest moment in Philadelphia sports history – an Eagles Super Bowl victory.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 1, 'The Gang Makes Paddy''s Great Again', 'Meet Cindy, the new, ethnically diverse female member of the gang who can successfully pull off scams. Everything is working until Mac introduces a new member: a life-like sex doll that looks exactly like Dennis.', 22, '2018-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 2, 'The Gang Escapes', 'To boost productivity, Dee hires an at-home "Escape Room Experience" service to come to Dennis and Mac''s apartment. Will they escape? Who will get the credit? What could go wrong?', 22, '2018-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 3, 'The Gang Beats Boggs: Ladies Reboot', 'To one-up the guys, Dee has organized an "all-female reboot" of the Wade Boggs challenge on a first-of-its-kind, all-female flight headed to L.A. for the women''s march.', 20, '2018-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 4, 'Time''s Up for the Gang', 'Paddy''s has been put on a list of bars that are sexually hostile to women, and the gang must attend a sexual harassment seminar to get off the list.', 21, '2018-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 5, 'The Gang Gets New Wheels', 'Dee gets in with a group of cool, rich housewives. Dennis hits it off with some everyday blue-collar bros. Frank struggles to renew his license, and Charlie and Mac deal with a new generation of bicycle bullies.', 24, '2018-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 6, 'The Gang Solves the Bathroom Problem', 'Jimmy Buffett is in town and the positive vibes are alive at the bar. But when Mac comes out of the women''s bathroom, no one can leave until the bathroom situation is solved.', 22, '2018-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 7, 'The Gang Does a Clip Show', 'With nothing to do while their phones update to the latest software, the gang decides to reminisce on old times. As everyone misremembers events from their past, the gang''s current reality becomes altered.', 21, '2018-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 8, 'Charlie''s Home Alone', 'It''s the weekend of Super Bowl LII from Charlie''s perspective. While Charlie searches the back office, Cricket steals the suit leaving Charlie home alone to defend himself.', 19, '2018-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 9, 'The Gang Wins the Big Game', 'It’s the most important weekend of their lives and Frank has treated the gang and a crew of their ragtag hangers-on with tickets to see the Eagles in the Super Bowl!', 20, '2018-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 13), 10, 'Mac Finds His Pride', 'Frank tries to recruit Mac for the gang’s kickass float for the Gay Pride Parade. It dawns on Frank that Mac will never be secure with his sexual identity unless he comes out to his father.', 21, '2018-11-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 14, 'Season 14', 'The 14th season guns for the Best 14th Season accolade as the Gang goes to extremes for the role – Mac learns a new language, Charlie does a period piece, Dennis attempts a one-act play, Dee cuts her hair, and Frank performs a death scene.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 1, 'The Gang Gets Romantic', 'Mac concocts a scheme to attract single women to Airbnb Dennis'' bedroom, while Frank and Charlie concoct similar plans to attract young, European coeds. But neither ad attracts their intended target.', 24, '2019-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 2, 'Thunder Gun 4: Maximum Cool', 'The Gang finds themselves in the middle of a focus group after a screening of Thunder Gun 4: Maximum Cool. They are determined to restore glory and traditional American values back into the franchise, even if it involves sabotage.', 22, '2019-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 3, 'Dee Day', 'The Guys are in the final preparation stage for an unknown scheme when Dee excitedly enters to inform them that today is “Dee Day.” The guys have to do everything she wants without complaint.', 24, '2019-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 4, 'The Gang Chokes', 'Annoyed that the Gang failed to react as he nearly choked to death on an appetizer, Frank decides the Waiter, his savior, is the only person who has his back.', 23, '2019-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 5, 'The Gang Texts', 'During their trip to the Philadelphia Zoo, Mac sets up a text group chain for The Gang, but confusion sets in and The Gang must learn from the meerkats on how to communicate properly in a group.', 22, '2019-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 6, 'The Janitor Always Mops Twice', 'In the black-and-white noir world of his memory, Charlie navigates the seedy underbelly of Philadelphia as Frank has been "diarrhea poisoned," and it''s up to Charlie to clean up the mess.', 22, '2019-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 7, 'The Gang Solves Global Warming', 'As a record-breaking heat wave overtakes Philly, the Gang plans to profit from global warming by pumping up the A/C so people will congregate at Paddy''s and save energy at home.', 19, '2019-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 8, 'Paddy''s Has a Jumper', 'Trapped inside Paddy''s with a suicide jumper on the roof, the Gang wonders if they should bother intervening with an algorithm of their own - Could he, would he, should we? the second half hour, Dennis and Charlie stand guard at the entrance to their laser tag base waiting to ambush the legendary "Big Mo," but Dennis begins to ponder the reasons they play laser tag and if their pursuit of a victory is worth their effort.', 21, '2019-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 9, 'A Woman''s Right to Chop', 'When a trendy new hair salon opens up right next door to Paddy''s, Dennis and Frank go on the offensive to stop women from cutting off their hair. Meanwhile, Mac is reunited with his childhood dog Poppins..', 21, '2019-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 14), 10, 'Waiting for Big Mo', 'In this spoof of Waiting for Godot, Dennis and Charlie stand guard at their laser tag base waiting to ambush their enemy, Big Mo, but Dennis has doubts about why they play laser tag and whether or not the victory is worth it.', 21, '2019-11-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 15, 'Season 15', 'In season fifteen, the gang finds themselves at a crossroads in this strange new world in the wake of Covid-19 and all things 2020. The rules are changing quicker than anyone can keep up with, despite herculean efforts from Mac, Charlie, Dennis, Dee, and Frank to continue business as usual. They must also now face the music and decide who they’ll become in the cultural upheaval that is 2021.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 1, '2020: A Year in Review', 'The Gang looks back on 2020 to justify their numerous PPE loans. In doing so, it is revealed that they contributed to the chaos of the past political year way more than anyone could have imagined.', 23, '2021-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 2, 'The Gang Makes Lethal Weapon 7', 'Upon discovering that their self-made Lethal Weapon sequels have been pulled from the local library, the Gang decides to address their political incorrectness by making another film — Lethal Weapon 7.', 23, '2021-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 3, 'The Gang Buys a Roller Rink', 'In the past, an innocent Dennis learns the horrifying details of Frank''s business, a truly sweet Dee is excited to head off for Hollywood, while Charlie and Mac''s jobs at the roller rink are in jeopardy.', 23, '2021-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 4, 'The Gang Replaces Dee with a Monkey', 'When the Gang suspects Dee is menopausal, they scramble to find a new employee for Paddy''s Pub. Dee decides to put her acting career on hold in order to mentor young actors.', 22, '2021-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 5, 'The Gang Goes to Ireland', 'The gang''s in Dublin where Dennis ends up helping Frank with some of his business''s dirty work. Mac and Charlie learn about their Irish heritage. Dee rushes to the set of an Irish soap opera, where she will play an "Obnoxious American MILF."', 22, '2021-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 6, 'The Gang''s Still in Ireland', 'Dennis and Dee explore their new accommodations in the countryside. Frank accompanies Charlie to find the truth about Charlie''s Irish childhood pen pal. Mac has an identity crisis and decides to join the seminary.', 23, '2021-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 7, 'Dee Sinks in a Bog', 'Mac spends a day at the seminary to truly understand what it takes to become a priest. Dennis and Frank plan an elaborate trap to humiliate Charlie''s pen pal. Dee prepares for a date with an Irish doctor. Charlie bonds with his pen pal.', 24, '2021-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 15), 8, 'The Gang Carries a Corpse Up a Mountain', 'The Gang attempts to ascend a mountain in order for Charlie to fulfill an old and mysterious Irish burial tradition. One by one, the Gang backs out until Charlie is left to honor the dead body alone.', 23, '2021-12-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 16, 'Season 16', 'In Season sixteen, it’s a challenge for Ronald "Mac" MacDonald, Charlie Kelly, Dennis Reynolds, Dee Reynolds, and Frank Reynolds who yearn for the past as they attempt to survive in 2023. This year alone, Mac battles with allergies and long-distance dating, Charlie takes on his long-forgotten sisters, Dee fights for rent control and women''s athletics, Frank wrestles for his gun, and Dennis struggles to improve his mental health. At the end of the day, they''re navigating 2023 with 16 years of baggage as a few figures from their past rear their heads.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 1, 'The Gang Inflates', 'Dennis and Mac get into inflatable furniture to deal with the economy’s inflation, while Dee tries to find a place to crash after being evicted by her greedy landlord and Charlie wants to pitch Frank his crypto/online investment idea. And in this inflation episode everything gets bigger - Dee’s desperation, Mac’s lips, and even Charlie’s apartment!', 24, '2023-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 2, 'Frank Shoots Every Member of the Gang', 'After Frank shoots Dennis and Dee, they resolve to take Frank’s gun away. Mac and Charlie go on a road trip with their moms to get their inheritances -- for Mac, it’s letters written by his grandfather which have fallen into his Uncle Donald’s hands, while for Charlie, it’s a jar of teeth that is now in the hands of his sisters, Bunny and Candy.', 23, '2023-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 3, 'The Gang Gets Cursed', 'The Gang’s going to be on Bar Rescue but a series of bad omens leads them to believe they are all cursed. They set off to undo the curses and make amends to those they’ve wronged, while Mac, who’s on a run of good luck, meets Chase Utley and invites him for a catch.', 23, '2023-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 4, 'Frank vs. Russia', 'Charlie cheers on Frank at a local chess tournament against a Russian grandmaster. Dennis helps Mac and Dee find boyfriends after getting irritated by Mac’s current boyfriend, Johnny.', 21, '2023-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 5, 'Celebrity Booze: The Ultimate Cash Grab', 'When news spreads of Bryan Cranston and Aaron Paul’s visit to Philadelphia to promote their Dos Hermanos mezcal brand, the Guys decide to pitch them their own liquor. The Gang takes to the skies to get a taste of the glamorous high life.', 22, '2023-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 6, 'Risk E. Rat''s Pizza and Amusement Center', 'The gang goes to Risk E. Rat''s, finding it updated with safety and overcautiousness. Dee takes Frank on a scavenger hunt to find risqué jokes hidden throughout the establishment. Mac plays Skee-Ball to win tickets for a prize.', 22, '2023-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 7, 'The Gang Goes Bowling', 'The guys crash Dee''s bowling league night and compete in a Battle of the Sexes at a bowling alley owned by the McPoyles. Dee, The Waitress, Artemis, and Gail the Snail versus Dennis, Mac, Charlie, and Frank in a classic match to prove who is better.', 24, '2023-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 16), 8, 'Dennis Takes a Mental Health Day', 'After a physical reveals Dennis has high blood pressure, he decides to take a day away from The Gang to de-stress at the beach. But life has other plans, and his day spirals into a string of mishaps until he can no longer contain his rage.', 24, '2023-07-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')), 17, 'Season 17', 'In Season 17 of It''s Always Sunny in Philadelphia, the Gang craves money and parasitic social privileges. That''s been plain since 2005. But they''re also human beings.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 1, 'The Gang F***s Up Abbott Elementary', 'Months after the Gang visited, Abbott''s Principal Ava walks viewers through some of the unseen footage of the Gang''s volunteerism and reveals their true intentions.', 24, '2025-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 2, 'Frank Is in a Coma', 'The five stages of grief set in for Dee as Frank lies on his deathbed. Meanwhile, the Guys plot their new path forward by pitching their business ventures to Philadelphia''s elite.', 23, '2025-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 3, 'Mac and Dennis Become EMTs', 'After witnessing EMTs resuscitate a Paddy''s patron, Mac and Dennis set out to become the pinnacle of masculinity; Frank tries to prove a prank''s innocence with The Lawyer; Dee attempts to hack her part-time side hustle with Charlie''s help as he descends into the fast-paced life of a chef.', 23, '2025-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 4, 'Thought Leadership: A Corporate Conversation', 'Desperate to stave off a public relations nightmare, the Gang embraces their newfound corporate professionalism to strategically scapegoat one Paddy''s employee to fall on the proverbial sword.', 22, '2025-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 5, 'The Gang Goes to a Dog Track', 'Frank attempts to win big with an old business associate at a West Virginia dog track; Dennis and Dee lose more than their shirts to gambling addiction; Mac and Charlie learn about a simpler way of life.', 21, '2025-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 6, 'Overage Drinking: A National Concern', 'When Tammy and Trey, now in their 40s, show up to remove their teenage son from Paddy''s, Dennis and Dee attempt to reconnect with their former prom dates. Frank''s sudden disappearance sends Mac and Charlie on a mission to track down his whereabouts.', 23, '2025-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 7, 'The Gang Gets Ready for Prime Time', 'Upon learning that Frank''s making a "Hometown Visit" with his Golden Bachelor partners, the Gang rehearses their family dinner to appeal to America.', 25, '2025-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0472954')) AND numero_temporada = 17), 8, 'The Golden Bachelor Live', 'Host Jesse Palmer walks the audience through Frank''s journey up until his final rose ceremony in the "Golden Bachelor" finale. But whom will he pick: a young internet celebrity, a confident woman his age, or a familiar face?', 26, '2025-08-20');
