INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0485301', 'Torchwood', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0323758'), 'SERIE', 'The members of the Torchwood Institute, a secret organization founded by the British Crown, fight to protect the Earth from extraterrestrial and supernatural threats.', '2006-01-01', 'https://m.media-amazon.com/images/M/MV5BMDliY2E3NzctNzIyNC00ODM4LWExMTEtYmFmZDJjZmE3MmI5XkEyXkFqcGc@._V1_.jpg');
