INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')), 1, 'Series 1', 'Separate from the government, outside the police, beyond the United Nations, Torchwood sets its own rules. Led by the enigmatic, ever watchful Captain Jack Harkness, the Torchwood team delves into the unknown and fights the impossible. Everyone who works for Torchwood is young. Some say that’s because it’s a new science. Others say it’s because they die young.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 1, 'Everything Changes', 'WPC Gwen Cooper is at the scene of a brutal murder, when the "special ops," known only as Torchwood, arrive. After witnessing the group bring the dead man back to life, Gwen goes in pursuit of this mysterious organisation, only to see weirder things than she could ever imagine existed. Soon after, she begins to regret giving in to her curiosity, when she meets Captain Jack Harkness.', 52, '2006-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 2, 'Day One', 'It''s Gwen''s first day on the job, and it''s not going very well. After accidentally releasing a mysterious gas from a comet that landed, a new type of alien is let loose on the streets - an alien that''s addicted to sex. Torchwood must find the inhabited body, and prevent anymore deaths from the violent form of sex.', 48, '2006-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 3, 'Ghost Machine', 'Whilst chasing a man, Gwen retrieves an unusual machine that allows the user to see back into the past. It is considered dangerous, and no members of Torchwood are permitted to use it. But Owen has other plans, and witnesses a violent murder that took place over forty years ago. Using the information he gathered, Owen starts to track down the still-living murderer.', 49, '2006-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 4, 'Cyberwoman', 'A Ianto themed episode
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 5, 'Small Worlds', 'Jack catches up with a very old friend of his, who is investigating fairy sightings in the local wood. After having visited her, Torchwood are informed of a man''s mysterious death in a prison cell. Then, Tosh uncovers a series of localised, extreme weather patterns. Nobody at the organisation is sure of these events, or how they may be connected. Except Jack, who has witnessed the creatures causing this, almost a century ago.', 47, '2006-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 6, 'Countrycide', 'Whilst investigating a group of unexplainable deaths in a village, the Torchwood team are separated. Discovering further, Jack, Gwen and Owen find a scared man, hiding from the thing responsible for the murders. But Tosh and Ianto go that one step extra, and locate the killer, who wants them as their next victims.', 47, '2006-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 7, 'Greeks Bearing Gifts', 'A Toshiko themed episode
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 8, 'They Keep Killing Suzie', 'A Suzie themed episode
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 9, 'Random Shoes', 'Eugene Jones wakes up, finding himself lying on the middle of a road. He then discovers that he has been the victim of a hit-and-run incident, and is, now, not only dead, but invisible. Eugene recalls events leading up to his death, involving a mysterious alien eye. Simultaneously, Gwen investigates the suspicious circumstances around his fatality.', 50, '2006-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 10, 'Out of Time', 'Three passengers from 1953 arrive in modern day Cardiff, when their plane flies through the Rift. With no means of travelling back, each person must adapt to their new life, starting personal relationships with the separate members of Torchwood.', 50, '2006-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 11, 'Combat', 'An Owen themed episode
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 12, 'Captain Jack Harkness', 'A Jack themed episode
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 1), 13, 'End of Days', 'With the Rift having been opened, people and objects throughout time are falling through it, and being spread across the world. "The thing in the darkness" has finally come, and Jack realises that he is the only one who can save planet Earth from the destruction that "the son of the Beast" will cause.', 47, '2007-01-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')), 2, 'Series 2', 'The second season takes the Torchwood team through dare-devil action, temptation, heartache, and a life-changing event. They journey to the 51st Century and World War I, save a stranded creature from horrific abuse, battle a memory thief who uncovers long-forgotten secrets among the entire team, and come face-to-face with an entity that may well be Death itself. And slick Captain Jack returns to battle a rogue Time Agent, the charismatic-but-psychopathic Captain John Hart.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 1, 'Kiss Kiss, Bang Bang', 'Captain Jack returns, as the Torchwood team reunite to fight a rogue Time Agent. The mysterious Captain John Hart is determined to wreak havoc, and needs to find something hidden on Earth. But with Gwen''s life in danger, and cluster bombs scattered across the city, whose side is Jack on?', 50, '2008-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 2, 'Sleeper', 'When a burglary turns into a slaughter, Torchwood suspect alien involvement. Who is Beth, and can she be as innocent as she seems? But when the investigation escalates into a city-wide assault, Jack realises that the whole planet is in danger.', 50, '2008-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 3, 'To the Last Man', 'Toshiko falls for a handsome soldier, trapped out of his time, who unwittingly holds the key to saving the world. With an old hospital haunted by ghosts from 1918, a crisis foreseen by Torchwood 90 years ago is about to reach its climax. Time zones are colliding and with life and death decisions to be made, will Torchwood be able to stop an explosive end for Cardiff?', 50, '2008-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 4, 'Meat', 'When Rhys discovers the truth about Torchwood, he helps the gang to find the source of an unusual alien meat supply.', 50, '2008-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 5, 'Adam', 'A memory thief gets in to the minds of the Torchwood team, and uncovers long forgotten secrets.', 50, '2008-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 6, 'Reset', 'Jack calls in an old friend for a favour, none other than Martha Jones, as they attempt to stop a pharmaceutical facility that uses aliens in the hope of discovering a cure for all diseases.', 50, '2008-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 7, 'Dead Man Walking', 'Captain Jack resurrects Owen with a resurrection glove, only to find out that the new glove isn''t quite what they''d bargained for. Owen, in an undead state, helps the team figure out why he''s still around.', 50, '2008-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 8, 'A Day in the Death', 'A victim of his newfound circumstances, Owen Harper believes he needs absolution. Will the lonely girl on the rooftop help him, or will it be a mission to the retrieve an alien device that is proving more lethal by the second? And how far will Toshiko go to help him?', 50, '2008-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 9, 'Something Borrowed', 'Gwen awakes on her wedding day to find she has been impregnated by a shape-shifting alien male. With it''s life-partner eager to retrieve it''s mate at the cost of Gwen''s life, the team race to intercept her as Gwen decides to go through with her marriage at a secluded location with all of her family present', 50, '2008-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 10, 'From Out of the Rain', 'An old cinema reopens and mysterious horrors of the past return to Cardiff.  Why are people trapped between life and death, questions are asked about the Night Travellers, and what Torchwood can do to stop them.', 45, '2008-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 11, 'Adrift', 'Gwen finds the darker side of Torchwood when a teenager disappears, investigating why hundreds of people have vanished without a trace. Jack is obstructing attempts to find them, and the answer appears to lie in the Rift.', 50, '2008-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 12, 'Fragments', 'As the team are knocked unconscious we find out how Jack, Toshiko, Ianto and Owen were initiated into Torchwood.', 50, '2008-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 2), 13, 'Exit Wounds', 'Captain John Hart returns to wreak havoc upon Jack''s world, who ends up getting captured. It is up to the Torchwood team to rescue him and save the city.', 50, '2008-04-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')), 3, 'Children of Earth', 'In 1965 twelve children are gathered together on a deserted moor when they become surrounded by a harsh, bright light, and then suddenly they are gone. Back in the present day, all over planet Earth, children stop moving. Stop playing. Stop laughing. Stop everything. Then, as one, they begin to speak with the same voice, announcing to the governments of the world the imminent arrival of a new alien threat. It becomes clear to the Torchwood team that this isn''t the aliens'' first visit to Earth, and a terrible price is going to be paid for sins of the past.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 3), 1, 'Day One', 'At 8.45am, every child in the world suddenly stops, chanting the words "we are coming" again and again. Whilst investigating, the remaining Torchwood team face greater personal and professional challenges than ever before, having to work with their numbers depleted.', 58, '2009-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 3), 2, 'Day Two', 'Torchwood are forced underground, as the government takes swift and brutal action.  With members of the team being hunted down, only Lois holds the key to Torchwood''s salvation - but she is helpless as her superiors make plans for the mysterious Floor 13.', 58, '2009-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 3), 3, 'Day Three', 'The eyes of the world turn to Britain, as the 456 announce, ''We are here''. As a pillar of fire descends upon London, the members of Torchwood must battle to protect their own families, as the fight gets personal. But will Clem''s memories destroy everything?', 58, '2009-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 3), 4, 'Day Four', 'Torchwood finally learns the truth about the events of 1965. But Britain is in danger of becoming a rogue state, and everything now pivots around John Frobisher, as the Ambassador of the 456 destroys its old allegiances and reveals its true intent.', 59, '2009-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 3), 5, 'Day Five', 'Torchwood is defenceless, and Gwen Cooper stands alone, as the final sanction begins. As violence erupts and the world descends into anarchy, an ordinary council estate becomes a battleground where the future of the human race will be decided.', 58, '2009-07-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')), 4, 'Miracle Day', 'One day, nobody dies. All across the world, nobody dies. And then the next day, and the next, and the next, people keep ageing - they get hurt and sick - but they never die. The result: a population boom, overnight. With all the extra people, resources are finite. It’s said that in four month''s time, the human race will cease to be viable. But this can’t be a natural event – someone’s got to be behind it. It’s a race against time as CIA agent Rex Matheson investigates a global conspiracy. The answers lie within an old, secret British institute. As Rex keeps asking “What is Torchwood?” he’s drawn into a world of adventure, and a threat to change what it means to be human, forever.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 1, 'The New World', 'Convicted child killer Oswald Danes is executed for his crimes and when he miraculously survives his fate a series of events is set in place that forces CIA Agent Rex Matheson to investigate a global event. His investigation leads him from America to Wales and an old defunct British Institute - Torchwood.', 54, '2011-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 2, 'Rendition', 'As the Torchwood team is reunited, Jack realizes he''s the most vulnerable man on Earth. A flight to the United States turns into a desperate battle for survival.', 54, '2011-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 3, 'Dead of Night', 'Torchwood goes on the run and finds a new enemy, but as they launch a raid on PhiCorp headquarters, Jack must confront the mysterious Oswald Danes.', 56, '2011-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 4, 'Escape to L.A.', 'Torchwood relocates to LA to sneak into PhiCorp''s headquarters to find some useful information, unaware that their mission has been compromised. Elsewhere, Oswald and Jilly face a new adversary in Ellis Hartley Monroe, who is using the Miracle Day for her own agenda.', 57, '2011-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 5, 'The Categories of Life', 'Torchwood goes undercover and discovers the terrible truth behind the Miracle. The enemy is closing in, and death is about to make a shocking return.', 54, '2011-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 6, 'The Middle Men', 'With Gwen, Rex and Esther trapped on both sides of the Atlantic, it''s a race against time as Jack goes straight to the heart of the conspiracy.', 54, '2011-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 7, 'Immortal Sins', 'Gwen must fight to protect her family and takes a terrifying journey, covering both miles and decades, as the long history of the Miracle is revealed.', 54, '2011-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 8, 'End of the Road', 'Jack faces a showdown with a man he thought was long since dead, while Rex takes extreme action to prevent the collapse of society.', 55, '2011-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 9, 'The Gathering', 'With the whole world in recession, a defeated Torchwood team take their last chance and make a deal with the devil.', 56, '2011-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0485301')) AND numero_temporada = 4), 10, 'The Blood Line', 'As the Torchwood team launch a final, desperate mission against the seemingly undefeatable Three Families, they realize it may come down to the ultimate sacrifice.', 56, '2011-09-15');
