INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')), 1, 'Season 1', 'In season one, Roy and Moss toil in the squalid basement of a huge company, fielding IT help-desk calls. Roy has a lousy attitude coupled with an eye for the ladies, while Moss is dressed by his mother and has an aerosol can of water clipped to his belt with which to spray his ear when it gets hot. Into their life of users, pizza, science fiction and firewalls comes middle manager Jen, a punky can-do career gal who doesn''t know one end of laptop from the other.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 1), 1, 'Yesterday''s Jam', 'It''s Jen''s first day at Reynholm Industries and she is assigned the position of manager of the IT department. Roy and Moss quickly find out that she has absolutely no knowledge of computers whatsoever.', 24, '2006-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 1), 2, 'Calamity Jen', 'Denholm tries to reduce stress in the work place and invites a stress expert to give the employees a class about dealing with stress. Meanwhile, Jen buys new shoes that are a few sizes too small, which leads to a very painful result.', 25, '2006-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 1), 3, 'Fifty-Fifty', 'Moss and Roy go on a lonely hearts website. Meanwhile Jen meets the man of her dreams.', 25, '2006-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 1), 4, 'The Red Door', 'What lies behind the mysterious red door in the IT department? What has happened to Moss''s new mug? And why is Roy in danger of becoming known as a ''desk rabbit''?', 24, '2006-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 1), 5, 'The Haunting of Bill Crouse', 'When her date Bill turns out to be a jerk, Jen asks Moss to send him away if he stops by. When he does and Moss can''t convince him to leave, Moss has to lie and ends up telling Bill that Jen is dead.', 24, '2006-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 1), 6, 'Aunt Irma Visits', 'Roy and Moss get the same symptoms as Jen when it''s her time of the month.', 26, '2006-03-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')), 2, 'Season 2', 'In the second series, team cohesion in IT at Reynholm Industries is running at capacity, largely thanks to work outings, dinner parties and the manipulation of cannibals in order to watch pirate DVDs.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 2), 1, 'The Work Outing', 'Jen is asked out on a date by Philip, and Roy and Moss decide to tag along, which ruins any chance of romance Jen was hoping for.', 25, '2007-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 2), 2, 'Return of the Golden Child', 'Moss uses a website to calculate Roy''s time of death, but Roy doesn''t want to know. Nevertheless Moss spills it anyway, making Roy very nervous. Meanwhile, Denholm''s death means trouble for Jen, Roy and Moss, until support appears in the form of a mysterious, albeit libidinous, stranger.', 24, '2007-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 2), 3, 'Moss and the German', 'Moss decides to sign himself up for a German cookery course, but due to a slight miscommunication between Moss and the advertiser, it turns out to be something else entirely.  Roy tries to see a film before someone can spoil the ending for him.  Jen finds out smoking is not as glamorous as she used to think.', 25, '2007-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 2), 4, 'The Dinner Party', 'Jen''s attempt to throw a successful dinner party don''t go exactly the way she was hoping. The evening isn''t a total disaster for everyone, though, as Richmond meets the woman of his dreams.', 22, '2007-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 2), 5, 'Smoke and Mirrors', 'When Jen complains about her bad bra, Moss attempts to create the world''s most perfect bra. When he succeeds, he attempts to get onto the BBC show Dragon''s Den to demonstrate it, which turns out a bit awkward.', 25, '2007-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 2), 6, 'Men Without Women', 'After making several unsuccessful advances, Douglas offers Jen the job as his new PA in order to get even closer to her. This way he hopes to slip a potion in her tea, that he obtained from a sorcerer and which should make Douglas irresistable to Jen.', 24, '2007-09-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')), 3, 'Season 3', 'For Moss, Roy and Jen, social networks and problems with naked calendars are welcome distractions from important duties, like protecting a certain little black box that''s also known as ''the internet''.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 3), 1, 'From Hell', 'Douglas''s neglegance in running the company nearly ruins Reynholm Industries. Meanwhile, Jen has a builder over at her house to do some renovations. When Roy seems to remember the guy from being on a TV show "Builders from hell", Jen gets a bit nervous.', 24, '2008-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 3), 2, 'Are We Not Men?', 'Roy and Moss try to meet new friends by getting familiar with the latest football news and slang. They meet new, yet peculiar friends. Meanwhile, Jen dates a guy who looks like a magician.', 22, '2008-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 3), 3, 'Tramps Like Us', 'When a sexual harassment case ends with a low pay out, Jen, Roy and Moss find themselves all moving in different directions. ', 22, '2008-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 3), 4, 'The Speech', 'Jen makes enemies of Roy and Moss after trying to assert herself more after being named as Employee of the Month. Douglas discovers that the woman who he loves is not quite as she seems.', 25, '2008-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 3), 5, 'Friendface', 'The boys are introduced to a social networking website by Jen.  Through the site they get in touch with old acquaintances to which they brag a little bit too much, which leads to awkward situations.', 23, '2008-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 3), 6, 'Calendar Geeks', 'To raise money for charity, the girls of the 7th floor come up with the idea to do a nude calendar. Roy -who happens to be there to fix a computer- gets excited when the girls ask him to do the photography. Jen doesn''t like the idea so much and comes up with an alternative.', 24, '2008-12-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')), 4, 'Season 4', 'As Moss wins big on a quiz show and Roy frets about his reputation, Jen seeks a new job. Douglas'' behavior continues to put the company in jeopardy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 4), 1, 'Jen the Fredo', 'Jen decides she wants to stretch herself more at work and applies for the post of Entertainment Manager. After discovering that her boss Douglas''s business connections have wilder tastes than she planned for, she ends up turning to Moss and Roy for help.', 25, '2010-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 4), 2, 'The Final Countdown', 'Moss ends up becoming a celebrity after he beats all the records on a popular daytime quiz show. Roy tries to explain to an old mate after being mistaken for a window cleaner. Jen finds herself pre-occupied with Douglas'' secret head of department meetings.', 24, '2010-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 4), 3, 'Something Happened', 'Douglas finds himself becoming a Spaceologist. Some bad luck changes Roy''s life. Jen ends up getting involved with a rock band.', 24, '2010-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 4), 4, 'Italian for Beginners', 'Roy gets obsessed by his latest girlfriend''s sad family history, while Jen tells an absolute whopper to get some attention.', 25, '2010-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 4), 5, 'Bad Boys', 'When Roy and Moss become juvenile delinquents for the day they end up having an uncomfortable experience at a local shopping centre.', 22, '2010-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0487831')) AND numero_temporada = 4), 6, 'Reynholm vs Reynholm', 'Douglas discovers that marriage agrees with him for all of a fortnight. He then finds himself in court defending himself with Jen, Roy and Moss'' help.', 25, '2010-07-30');
