INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0489974', 'Carnival Row', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0294457'), 'SERIE', 'A human detective and a fairy rekindle a dangerous affair in a Victorian fantasy world, where the city''s uneasy peace collapses when a string of murders reveals an unimaginable monster.', '2019-01-01', 'https://m.media-amazon.com/images/M/MV5BNzgzYmQ0OTYtMjMwMS00ZGI2LWE5MjMtMWViZjkwMGY4NGZmXkEyXkFqcGc@._V1_.jpg');
