INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')), 1, 'Season 1', 'With a serial killer loose on Carnival Row, and a government that turns a blind eye to the deaths of its lower class citizens, Rycroft Philostrate, a war-hardened investigator, is the only person willing to stop the murders and maintain the fragile peace. But when Vignette Stonemoss, a faerie refugee, turns up in the Burgue, she forces Philo to reckon with a past he''s tried to forget.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 1, 'Some Dark God Wakes', 'Rycroft “Philo” Philostrate investigates “Unseelie Jack”, a mysterious assailant with a grudge against the fae. Vignette Stonemoss barely escapes Tirnanoc with her life and arrives in The Burgue looking for a fresh start. Imogen Spurnrose meets her new neighbor. In Parliament, the fight over the critch heats up.', 61, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 2, 'Aisling', 'Philo investigates the murder of a mysterious fae. Tourmaline introduces Vignette to a new group of faeries. Imogen tries to have Agreus removed from the neighborhood. Jonah disappears.', 51, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 3, 'Kingdoms of the Moon', 'Once, as a Burguish soldier, Philo was tasked with protecting a faerish mimasery. While The Pact bears down on them, Philo meets Vignette and finds love in the most unlikely of places.', 60, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 4, 'The Joining of Unlike Things', 'Philo investigates the murder of his childhood headmaster. Vignette ingratiates herself into the Black Raven. Imogen hatches a plan to help her brother. Breakspear goes on the offensive with Longerbane.', 56, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 5, 'Grieve No More', 'Philo consults a Haruspex in an effort to find clues about the killer. Vignette grows closer with her newfound family. Upon Jonah’s return home, his parents cast a more watchful eye over him as a new player makes a splash in Parliament. Imogen brings Agreus into her circle.', 54, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 6, 'Unaccompanied Fae', 'The pieces of the puzzle start to come together for Philo. Vignette finds home in a place she never expected. Jonah sneaks off to see someone he shouldn’t. Imogen and Agreus step out together in public.', 50, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 7, 'The World to Come', 'Because he withheld evidence from his fellow detectives, Philo is accused of being the man behind the string of murders and is thrown in jail. There, he finds some unexpected help from Vignette. Elsewhere, Ezra takes exception to Imogen’s relationship with Agreus. Sophie offers Jonah a deal.', 50, '2019-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 1), 8, 'The Gloaming', 'As tensions rise on Carnival Row, Philo must confront both darkness incarnate and the evil that controls it. Vignette gleans the true nature of The Burgue. Imogen lets her feelings for Agreus go unbridled. Breakspear''s secrets catch up to him.', 67, '2019-08-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')), 2, 'Season 2', 'Love. Murder. Conspiracy. Revolution. When mysterious killings inflame tensions between the Faefolk and their Human oppressors, each denizen of Carnival Row must choose who they are and how to act.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 1, 'Fight or Flight', 'Lovers Philo and Vignette risk their lives to help the oppressed Faefolk of Carnival Row.', 59, '2023-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 2, 'New Dawn', 'When Philo plots to challenge Jonah''s hereditary claim to the Chancellorship, Vignette intervenes.', 61, '2023-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 3, 'The Martyr''s Hand', 'While Philo investigates the murders of the Black Raven’s leaders, Vignette plots revenge.', 49, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 4, 'An Unkindness of Ravens', 'Philo races to stop Vignette’s revenge before the Black Raven spark even worse violence.', 52, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 5, 'Reckoning', 'Philo plots Vignette’s rescue with an unlikely ally.  Jonah discovers Sophie’s treachery.  The murderer strikes again.', 56, '2023-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 6, 'Original Sins', 'A painful truth haunts Philo as Carnival Row faces reprisals for the horrific events at Bleakness Keep.', 60, '2023-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 7, 'Kindred', 'Torn between his Human and Fae sides, Philo makes a choice.', 52, '2023-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 8, 'Facta Non Verba', 'Reeling from the consequences of his choices, Philo rejects defining himself as either Human or Fae.', 49, '2023-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 9, 'Battle Lines', 'Justice later through peace, or now through blood?', 52, '2023-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0489974')) AND numero_temporada = 2), 10, 'Carnival Row', 'The epic finale of “Carnival Row.”', 56, '2023-03-16');
