INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')), 1, 'Season 1', 'When Miley Stewart moves to a new city, it seems she''s just an ordinary teen who wants to make new friends and fit into her new school. But she''s got a huge secret: She''s also the glamorous pop-star Hannah Montana, who''s living the celebrity dream with awesome concerts, limos and a huge closet full of the latest styles. Y''all won''t believe the hilarious things she does to keep her double identity a secret. It all works out, though, because this girl totally rocks!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 1, 'Lilly, Do You Want to Know a Secret?', 'Lilly is ecstatic when she gets two tickets to a Hannah Montana concert and invites Miley to accompany her. Miley refuses, saying that she doesn''t like Hannah Montana. Miley''s dad, Robby, tries to convince her to tell Lilly her secret: That she is Hannah Montana. When Lilly finds out what Miley''s been hiding, will she treat her the same? Jackson won''t take no for an answer when he wants to borrow money for his big date. But his dad keeps refusing to be his personal ATM.', 23, '2006-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 2, 'Miley Get Your Gum', 'Oliver has a huge crush on Hannah Montana, but his feelings of love are not shared by Miley. No matter what she does, she can''t seem to make Oliver realize that he & Hannah can never be - until Lilly comes up with a plan to burst Oliver''s love bubble. Jackson''s proud to be the owner of a "Brand New" used car that he bought with his own money, but the joy fades once he learns that this particular kind of car is only driven by girls.', 23, '2006-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 3, 'She''s a Super Sneak', 'Miley and her friends want to meet Ashton Kutcher at his movie premiere and Jackson and Cooper want to meet the beautiful girls who want to meet Ashton Kutcher. So both Miley & Jackson decide to disobey their father and sneak out. The super-sneaky siblings get a surprising eyeful when they spy their dad at the movie theater on a date. Miley becomes upset because he lied to them by saying he would be at a meeting and she thinks he''s trying to replace their mother.', 23, '2006-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 4, 'I Can''t Make You Love Hannah If You Don''t', 'Miley adores her new beau, Josh, but is unsettled to learn that he despises Hannah Montana. After spending their whole date trying to get Josh to change his mind about Hannah, he decides to attend a Hannah Montana concert, but only if Miley will go with him. Sparks fly when Jackson meets a new girl who actually likes him for himself. Unfortunately, there are even bigger sparks between Jackson and Cooper, once Cooper realizes that Jackson''s dream girl is his little sister, Olivia.', 23, '2006-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 5, 'It''s My Party And I''ll Lie If I Want To', 'After Lilly embarrasses her at a Hannah Montana concert along with added pressure from her "Hannah Friends", Miley decides to lie to Lilly and tell her that the birthday party for Kelly Clarkson that they were going to was called off. Miley attends the party as Hannah but must cover up her lie when she lands on the front page of the news. Jackson meets a beautician named Nina at work who asks if she could use him to practice on. He''s more than happy to oblige the pretty lady, not knowing that it''s one of Rico''s pranks.', 23, '2006-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 6, 'Grandma Don''t Let Your Babies Grow Up to Be Favorites', 'The Stewarts are having a busy week. Hannah Montana is about to perform for the Queen of England and the Queen''s granddaughter; Jackson is in his school''s volleyball championship; and Mamaw Ruthie is in town on a surprise visit. But when Mamaw only spends time with Jackson, Miley believes that Jackson is Mamaw''s favorite.', 23, '2006-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 7, 'It''s a Mannequin''s World', 'It''s Miley''s birthday! Robbie is trying to find something special for his little girl. Miley tells Lilly to steer Robbie to the right clothes, but it still doesn''t work. Now Miley has to wear a tacky sweater to her birthday party. Meanwhile, Jackson is trying really hard to give Miley a birthday cake and not mess things up (again).', 23, '2006-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 8, 'Mascot Love', 'Lilly decides to be a cheerleader with Miley in order to spend more time together, but they end up doing the opposite when Miley ends up being the team mascot. Meanwhile, in order to get some money from his father Robby Ray, Jackson willingly volunteers to unclog the sink for him. However, it''s not as easy as he thinks.', 23, '2006-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 9, 'Ooh, Ooh, Itchy Woman', 'Miley, Lilly, and Oliver are just itching to get revenge on bratty Amber & Ashley during a class camping trip, even though Robbie told Miley not to sink to their level. When Miley and her friends give the girls their comeuppance, she thinks that they got away with it, but she finds herself with a whole new itch to scratch as Hannah Montana. Meanwhile, Jackson and Robbie try to rid themselves of a mouse with a surprising talent.', 23, '2006-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 10, 'O Say Can You Remember the Words?', 'Frustrated by Oliver''s stage fright, Miley vents to her dad that she doesn''t want to help him with their upcoming drama class performance anymore, which a dismayed Oliver accidentally overhears. Miley gets a taste of what Oliver goes through when Hannah Montana forgets the words to the National Anthem while singing at a Lakers game. Rico''s dad entrusts Jackson to get rid of sugar addict Rico''s candy stash after a bad trip to the dentist. He manages to get Rico off the goodies, but Jackson becomes even more addicted to sweets than Rico.', 23, '2006-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 11, 'Oops! I Meddled Again', 'Miley & Lilly play matchmakers for a Hannah Montana fan named Becca. The object of Becca''s affection is Oliver & the girls manage to get them together. Oliver wishes that they would have stayed out of his love life when Lilly and Miley find out something upsetting about his new squeeze. Jackson learns why the chicken crossed the road... to get away from spoiled Rico and his demands!', 23, '2006-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 12, 'On the Road Again (III)', 'Hannah Montana isn''t the only Stewart family secret! Miley discovers that Robbie was once a pop star in his own right, but just as his career was taking off, he disappeared. Without asking her father if he even wants to make a comeback, Miley gets him a singing gig so that he can get on the road again.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 13, 'You''re So Vain, You Probably Think This Zit Is About You', 'Lilly''s pride takes a hit when she''s forced to wear her awful-looking glasses right before a skateboarding contest. Hoping to help, Miley convinces her friend not to worry about her appearance and to go ahead with the competition. Miley refuses to take her own advice, however, when it''s her vanity that''s damaged. Jackson wishes Rico would disappear when he realizes that his new raise depends on Rico''s opinion of him.', 23, '2006-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 14, 'New Kid in School', 'TV star Jake Ryan starts to attend classes at Seaview. All of the students & teachers are starstruck (except for Miley) and cater to his every need. After being mistreated and getting into trouble for the same things that Jake was allowed to do, a frustrated Miley decides to tell everyone that she''s Hannah. Will a surprising person convince her to change her mind before it''s too late? Stern Robby lets Jackson take his brand-new convertible out on a date when his car refuses to start, but only after instructing Jackson to not let anything happen to the car. Robbie wishes that he hadn''t been so strict, however, when he accidentally damages Jackson''s car.', 23, '2006-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 15, 'More Than a Zombie to Me', 'Miley declines Jake''s invitation to the school dance. While Hannah is filming a guest spot on Jake''s show, she learns that Jake has feelings for a girl named Miley. She changes her mind about his dance invite, but Miley finds out that he has asked Lilly instead. Jackson and Robby decide to see who''s the better prankster by pulling practical jokes on one another.', 23, '2006-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 16, 'Good Golly Miss Dolly', 'Good golly! Miley''s tells her visiting godmother, Aunt Dolly, all about her crush on Jake. Unfortunately, Aunt Dolly accidentally videotaped her confession and the tape is now in Jake''s hands. Aunt Dolly, Miley, and Lilly hatch a plan to get it back before Jake can watch it. Robbie and Jackson find it hard to resist Aunt Dolly''s attempts to add her "special touch" to every aspect of their lives.', 23, '2006-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 17, 'Torn Between Two Hannahs', 'This Halloween, it''s not ghosts or goblins that are frightening Miley, but her "treat" of a cousin, Luann. Apparently, Luann, who could pass for Miley''s twin, is really a "trickster" and try as she might, Miley cannot get anyone to believe that Luann is out to get her. As Luann aims to expose Miley''s and Hannah''s secret, will Miley be able to stop her dubious doppelganger in time? Jackson and Robbie give the phrase "Anything you can do, I can do better" a new meaning when they keep trying to top Mr. Dontzig''s ghoulish decorations.', 23, '2006-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 18, 'People Who Use People', 'Miley sees Jake with a girl named Holly and thinks she''s his girlfriend, so she attempts to make him jealous by going out with another guy. Meanwhile, Jackson tries to get an "A" in his class by using Robby and trying to make him go out with his teacher, Ms. Kunkle.', 23, '2006-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 19, 'Money for Nothing, Guilt for Free', 'Sick of Amber and Ashley constantly winning the school''s charity fundraiser, Miley, Lilly, and Oliver team up to raise more cash than the girls. Jackson needs Cooper''s help if he wants to beat Robbie at ping pong.', 23, '2006-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 20, 'Debt It Be', 'After Miley charges a wild shopping spree to her emergency credit card, she begs Jackson to help her pay it off before Robbie finds out. Jackson hatches a plan to auction off Hannah''s old clothes and a fake pair of sapphire earrings given to her for a video shoot. The siblings manage to raise the money to cover her debt and she thinks that they are home-free. That is until Robbie tells them that the jeweler wants the sapphire earrings back because they mistakenly gave Hannah the real pair instead of the fake ones.', 23, '2006-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 21, 'My Boyfriend''s Jackson and There''s Gonna Be Trouble', 'A sneaky photographer takes a picture of Hannah and Jackson, causing everyone to think that Jackson and Hannah are a couple. Meanwhile, Oliver has a school assignment with Sarah and he finds himself liking her.', 23, '2007-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 22, 'We Are Family: Now Get Me Some Water!', 'Miley offers to let Jackson be Hannah''s personal assistant after he loses his job because of her. But Jackson''s assistance turns out to be more stressful than helpful.', 23, '2007-01-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 23, 'Schooly Bully', 'A girl called "The Cracker" is constantly harassing Miley, so she turns to Roxy for ideas on how to stop the bully. Robby and Jackson are wishin'' that they hadn''t gone fishin'' when they get stuck in a cabin during a blizzard.', 23, '2007-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 24, 'The Idol Side of Me', 'Amber and Ashley are up to their old tricks again, only this time Miley and Lilly devise a plan to give one of the girls a taste of her own medicine. A persnickety pooch named Oscar drives Robby and Jackson batty with its constant barking.', 23, '2007-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 25, 'Smells Like Teen Sellout', 'Hannah Montana agrees to endorse a new perfume, only she can''t stand the smell because it brings back bad memories. Meanwhile, Jackson tries out for a television survival program.', 23, '2007-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 1), 26, 'Bad Moose Rising', 'The Stewarts'' nasty neighbor gets Miley and Jackson to look after his equally nasty niece. Robby gets the flu and Roxy has to look after him.', 23, '2007-03-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')), 2, 'Season 2', 'Totally sweet Miley Stewart has a hard enough time balancing school, crushing on cute boys and trying to fit into the social scene in trendy Malibu. On top of it all, she has a big secret: She also rocks the house as superstar Hannah Montana! Even though her life as a celebrity is glamorous, it has its challenges. Miley relies on her family and her true friends, Lilly and Oliver, to remind her to be true to herself first. But sweet niblets! Nobody is perfect, and you will laugh out loud as you see all the outrageously funny things she does as she figures out how to keep it real.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 1, 'Me and Rico Down by the School Yard', 'Miley is forced to become Rico''s gal pal when the troublesome tyke claims to know her secret. A new kid in town named Thor decides to make Jackson his new best friend. But Jackson, a former hillbilly, wants nothing to do with a hayseed like Thor...', 23, '2007-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 2, 'Cuffs Will Keep Us Together', 'Oliver believes that the key to getting Lilly and Miley''s friendship back on track is by handcuffing the girls together. Unfortunately, his plan backfires and he may lose his friendship with both girls if he can''t find where he put the handcuff keys. Robby discovers that silence really is golden when he wants his son to pay attention to him.', 23, '2007-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 3, 'You Are So Sue-Able to Me', 'Lilly goes from "Skater Girl" to "Glamor Girl" in order to impress her crush on a date. But when her new beau is a no-show, Lilly decides that their next date will be on TV''s "The Teen Court". Jackson is the happiest boy in the world after he wins two courtside tickets to a Lakers playoff game. However, his joy is dampened when both Robby and Thor want the extra seat.', 23, '2007-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 4, 'Get Down Study-udy-udy', 'Miley focuses on Hannah''s impending tour of Europe, instead of paying attention to her schoolwork. After Robby learns that her grades are suffering, he tells Miley that he''ll call the tour off, unless she finds a way to bring her grades up. Jackson wishes he could fly the coop when Snowball, Thor''s talkative pet bird, uses his gift of gab to get Jackson into trouble.', 23, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 5, 'I Am Hannah, Hear Me Croak', 'Miley wishes that she could sing the blues (or any song for that matter) when she needs to undergo throat surgery. But can a dream about her late mother have her whistling a happy tune?', 23, '2007-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 6, 'You Gotta Not Fight for Your Right to Party', 'Robby, tired of refereeing Jackson and Miley''s latest feud, puts the skids on his kids'' weekend plans. When Miley and Jackson make a break for freedom, the pair''s bickering leads to a bigger problem. Will Jackson''s actions finally make Miley smile?', 23, '2007-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 7, 'My Best Friend''s Boyfriend', 'Miley decides to play amateur sleuth when she discovers that Lilly''s boyfriend is a two-timing Romeo.', 23, '2007-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 8, 'Take This Job and Love It', 'Roxy''s overprotecting nature causes her to ruin Miley''s date, so Miley convinces her to take up a security job working for the President of the United States. Jackson pretends to be a professional motocross racer to impress a girl.', 23, '2007-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 9, 'Achey Jakey Heart (1)', 'Jake Ryan returns from his movie shoot, only to find out that Miley has lost interest in him. Jake tries to win Miley back but only woos other fanatic girls. Jackson and Oliver create a successful business selling Cheeze Jerky, which makes Rico jealous and causes him to create a plan to steal the recipe.', 23, '2007-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 10, 'Achey Jakey Heart (2)', 'Miley realizes that Jake isn''t the guy she thought he was, so she tries to make Jake break up with her. Meanwhile, Jackson and Oliver continue to make Rico jealous with their successful Cheeze Jerky business.', 23, '2007-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 11, 'Sleepwalk This Way', 'Miley starts sleepwalking and telling the truth to everyone, which gets her into hot water with the sternest teacher in school.', 23, '2007-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 12, 'When You Wish You Were the Star', 'Will Miley learn to be careful what she wishes for, when the desire to be Hannah Montana all of the time gets the best of her?', 23, '2007-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 13, 'I Want You to Want Me... to Go to Florida', 'Miley''s competitive nature is at it again! However, in order to pull off this caper she must deceive Roxy first so that she can save Hannah''s fans.', 23, '2007-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 14, 'Everybody Was Best Friend Fighting', 'When Hannah gets an extra ticket to a celebrity tennis tournament, Lilly and Oliver battle for the ticket. Who will win out?', 23, '2007-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 15, 'Song Sung Bad', 'When Lilly records a song for her mom and sounds horrible, Miley and Robby Ray doctor the recording. Thinking she is a great singer, Lilly challenges Amber to a sing-off.', 23, '2007-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 16, 'Me and Mr. Jonas and Mr. Jonas and Mr. Jonas', 'Miley is envious of her Dad spending time jamming with the Jonas Brothers. Jackson tries to break the World Pogo-stick record.', 23, '2007-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 17, 'Don''t Stop ''Til You Get the Phone', 'When Miley''s dad won''t let her get a new phone, she sells a Hannah picture to the press to buy it herself. Unfortunately, the picture seems to be revealing her secret.', 23, '2007-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 18, 'That''s What Friends Are For?', 'Jake comes back and wants to be just friends with Miley. Miley thinks this plan is perfect, but then finds out that Jake is doing a movie where he has to kiss her enemy Mikayla. Rico makes a bet that causes Oliver and Jackson to appreciate cleanliness more than ever.', 23, '2007-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 19, 'Lilly''s Mom Has Got It Goin'' On', 'Robby goes on a date with Lilly''s mom, but when things don''t go as planned, Miley & Lilly fight over who''s at fault. Jackson and Rico pretend to be each other.', 23, '2007-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 20, 'I Will Always Loathe You', 'Aunt Dolly And Mamaw drag an unwilling Miley into their long-time feud. Oliver and Rico have auditions for the best "Rico" to star in a commercial for the shack.', 23, '2007-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 21, 'Bye Bye Ball', 'Miley thinks she has hit a home run when she finds a way to replace Jackson''s prize possession she ruined.', 23, '2008-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 22, '(We''re So Sorry) Uncle Earl', 'Uncle Earl comes to visit and expects Miley to help him become a rock star.', 23, '2008-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 23, 'The Way We Almost Weren''t', 'Miley is almost struck by lightning which makes her and Jackson travel back in time to when their parents met.', 23, '2008-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 24, 'You Didn''t Say It Was Your Birthday', 'Miley and Jackson forget that it''s Robby''s 40th birthday, and argue over why he is annoyed at them. When they find out, Miley distracts Robby at a CD signing, while Jackson tries to organize a last-minute surprise party to cover up that they forgot.', 23, '2008-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 25, 'Hannah in the Streets with Diamonds', 'Hannah gets her own diamond on the Hollywood Parade of Stars, but a guy is selling messy chili dogs next to her diamond. Then, a gross flower vendor spits on her diamond. So she decides to change her diamond''s location. Meanwhile, Jackson''s car is broken, so Robby works for Rico until Jackson is back to work. But when Rico is mean to Robby, Jackson gets fired.', 23, '2008-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 26, 'Yet Another Side of Me', 'Hannah meets her idol, Isis, who inspires her to change her image to keep fresh. Hannah does this to impress the Sunshine Girls after being named Role Model of the Year. Meanwhile, Jackson befriends Rico.', 23, '2008-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 27, 'The Test of My Love', 'Miley successfully manages to catch a date with a rich boy. However, the boy''s parents are rude to Miley because she is some yokel from Tennessee, so she tries to impress them by pretending to be rich and fancy herself.', 23, '2008-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 28, 'Joannie B. Goode', 'Oliver and Joannie start dating and Oliver wants Miley and Lilly to be friends with her. After a sleepover Lilly and Joannie find they have more in common than they thought and Miley starts to get jealous and thinks she''s losing her friends. Meanwhile, Jackson gets a date with Rico''s cousin.', 23, '2008-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 2), 29, 'We''re All on This Date Together', 'In an auction hosted by Donny Osmond, Hannah is up for bid in a special "Date with Hannah Montana" prize. Ray Romano makes an appearance at the auction, although Hannah doesn''t know who he is. After a bidding war between Hannah''s crush Johnny Collins and Rico, she has to take both on the date together.', 23, '2008-10-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')), 3, 'Season 3', 'Being a world-famous celebrity like Hannah has its perks and its challenges – especially when underneath the glamorous wig you are just a normal teenage girl like Miley Stewart! Get ready to laugh out loud as Miley juggles real life growing up stuff while making the most of her exciting career as a pop star. Will she get her driver''s license? Land a big movie role? Keep it together when a secret romance is revealed? Totally freak out when both of her worlds threaten to collide?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 1, 'He Ain''t a Hottie, He''s My Brother', 'Jackson and Lilly toy with the idea of going out together, while Miley thinks of ways to nip their romance in the bud.', 23, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 2, 'Ready, Set, Don''t Drive', 'Miley is riding high when she begins Drivers'' Ed, but she comes crashing down to earth after she learns that the class is not the easy ride she thought it was.', 23, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 3, 'Don''t Go Breaking My Tooth', 'When Miley insists on going to the dentist without her father''s hand to hold, she ultimately can''t go through with the treatment but doesn''t admit it to Robby. Her appearance as Hannah on a popular food show goes completely awry as a result of her swollen tooth.', 23, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 4, 'You Never Give Me My Money', 'When Miley asks for a raise on her allowance, Robby decides to teach her about fiscal responsibility.', 23, '2008-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 5, 'Killing Me Softly with His Height', 'Miley agrees to go out with a charming boy named Connor for the holidays. Connor''s elfin stature and his job helping Santa at the mall, however, clashes with her idea of the perfect guy. The neighborhood Scrooge, Mr. Dontzig, offers to get Jackson into the college of his dreams, but only if Jackson and Robby do everything that he asks of them.', 23, '2008-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 6, 'Would I Lie to You, Lilly?', 'Lilly holds a yard sale to raise money for a class trip to Washington, D.C., and Miley gets a man to buy Lilly''s hat for a thousand dollars. Miley helped her even though she didn''t want her help. Miley and Lilly reconcile when they stumble into a White House press conference with Miley mentioning that Lilly is more of a sister than her best friend. Meanwhile, Rico hires Sarah to work at Rico''s because he knows it will annoy Jackson, but then realizes that he isn''t happy with Sarah.', 23, '2009-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 7, 'You Gotta Lose That Job', 'Miley, dressed as Hannah, blows a movie audition with director Rob Reiner on purpose to make Oliver feel better about not getting into a band. Meanwhile, Rico destroys Jackson''s ventriloquist dummy, and therefore Rico is forced to act as the dummy for a birthday party.', 23, '2009-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 8, 'Welcome to the Bungle', 'Hannah is on a talk show and says she doesn''t like carrots and books and her fans have no choice but to do likewise.', 23, '2009-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 9, 'Papa''s Got a Brand New Friend', 'Robby becomes close friends with Hannah''s new choreographer, making it hard for Miley to get rid of him. Oliver doesn''t like his new bossy girlfriend and gets Jackson''s help to rid himself of her.', 23, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 10, 'Cheat It', 'Hannah pretends to date a celebrity she can''t stand to get in the news. Jackson thinks that he has to cheat on a test in school. Robby clashes with Rico.', 23, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 11, 'Knock Knock Knockin'' on Jackson''s Head', 'Jackson''s memory loss seems to be the perfect opportunity for Miley to change their relationship for her benefit. Meanwhile, Rico forces Lilly to pretend to be his girlfriend while his cousin Angus is in town in exchange for his help with her math.', 23, '2009-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 12, 'You Give Lunch a Bad Name', 'Miley and Jackson have to figure out a way to get things back to normal at school after Mamaw takes over as the lunch lady.', 23, '2009-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 13, 'What I Don''t Like About You', 'Miley returns from filming a movie and finds that Lilly and Oliver have started dating. There is something about Lilly that Oliver doesn''t like and there''s something about Oliver that Lilly doesn''t like. Jackson gets an interview with a university and lies about himself to the representative in order to have a better chance of admission.', 23, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 14, 'Promma Mia', 'Miley tries to get out of going to prom with the school nerd and when the chance comes for her to record a duet with David Archuleta, she uses it as the perfect excuse.', 23, '2009-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 15, 'Once, Twice, Three Times Afraidy', 'Lilly and Oliver won''t stop giving Miley a hard time over the fact that she doesn''t have a boyfriend, so she decides to pay an actor to pretend to be her boyfriend so they will leave her alone. But when the actor she paid backs out and sends his not-so-attractive, middle-aged roommate to fill in, Miley finds herself in a bigger mess than the one she started out in. Meanwhile, Jackson has a hard time believing that Rico''s act of kindness is genuine.', 23, '2009-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 16, 'Jake... Another Little Piece of My Heart', 'Miley runs into Jake Ryan in Las Vegas. She''s shocked to learn that he plans to marry Traci, so she plots to stop the wedding. Meanwhile, Rico tries to disrupt Jackson''s date.', 23, '2009-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 17, 'Miley Hurt the Feelings of the Radio Star', 'Miley and Oliver become temporary DJs at a teen-oriented radio station after the regular host takes an unexpected leave. Meanwhile, Rico lets Jackson run the snack shack in hopes that it will lose money and his dad won''t be able to sell it.', 23, '2009-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 18, 'He Could Be the One', 'Miley agrees to go steady with Jake again, but she worries that all of the times she complained about Jake might have turned Robby against the young man. When she learns that Robby dislikes Jesse, a troublemaking teen guitarist in Hannah''s band, Miley hatches a plan to make Jake look great.', 46, '2009-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 19, 'Super(stitious) Girl (III)', 'Miley experiences nothing but bad luck on the SS Tipton after she loses an ankle bracelet her mom gave her. Miley believes the missing jewelry is a good-luck charm and is desperate to get it back. At home, Jackson opens a large package after Robby forbids him to do so, and he suffers the consequences.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 20, 'I Honestly Love You (No, Not You)', 'Miley is desperate to keep Lilly and Oliver together after she mistakenly concludes that Oliver is falling in love with her instead.', 23, '2009-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 21, 'For (Give) a Little Bit', 'Hannah reveals something embarrassing about Jackson in an interview and while she tries to make it up to Jackson he appears to do the same thing to her, or did he?', 23, '2009-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 22, 'B-B-B-Bad to the Chrome', 'Robbie and the kids trade in Mamaw''s old rust bucket for a regal new convertible. They are unaware, however, that Mamaw is extremely attached to the decrepit car she calls Loretta. Rico is forced to play peacemaker when Lilly and Oliver''s constant quarreling drives his customers away.', 23, '2009-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 23, 'Uptight (Oliver''s Alright)', 'Miley and Lilly find out that Oliver has diabetes, and they try to play food police at Traci''s birthday party. (Due to negative feedback, the episode was re-edited from the original titled "No Sugar, Sugar" that aired in some countries.)', 23, '2009-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 24, 'Judge Me Tender', 'Oliver becomes an overnight sensation after performing on a TV talent show and the success quickly goes to his head. Miley and Lilly decide that the only way to get their old pal back is if Hannah, who will be a judge for the show''s finale, persuades the other judges to vote against Oliver. Robby and Jackson must fight the law when Jackson keeps receiving tickets for traffic violations that he didn''t commit.', 23, '2009-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 25, 'Can''t Get Home to You, Girl', 'An apologetic Miley plans to make up for the fiasco that Hannah caused at Lilly''s last birthday with a special girl''s night out. Unfortunately, she ends up stranded in the middle of nowhere on the big day, which leaves Jackson in charge of keeping an increasingly upset Lilly busy until Miley arrives.', 23, '2009-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 26, 'Come Fail Away', 'Hannah assumes that she will take to voiceover work like a duck to water. Jackson is tired of Robby treating him like a child. Rico outfits the Surf Shack with high-tech equipment.', 23, '2009-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 27, 'Got to Get Her Out of My House', 'When Miley accidentally gets Lilly fired, Lilly becomes the Stewarts'' housekeeper.', 23, '2010-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 28, 'The Wheel Near My Bed (Keeps On Turnin'')', 'Miley offers to share her own room with Lilly after Lilly''s mother gets a job in another state, but being roommates quickly takes a toll on the girls'' friendship.', 23, '2010-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 29, 'Miley Says Goodbye? (1)', 'Miley starts to miss her old life in Tennessee. Oliver gets an offer to go on a concert tour, but his joy is dampened when realizes that he won''t be able to see Lilly for six months. Jackson decides that it is time for him to leave home.', 23, '2010-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 3), 30, 'Miley Says Goodbye? (2)', 'Jackson makes himself at home in his new bachelor pad but quickly finds out that the place is a crumbling wreck. Miley mulls over the idea of going back to the simple life in Tennessee. Oliver contemplates giving up the tour to be with Lilly, while Lilly tries to figure out what she will do without Oliver and Miley in her life.', 23, '2010-03-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')), 4, 'Hannah Montana Forever', 'You''ve been part of Miley Stewart''s life for four amazing years and have watched with her best friends, Lilly and Oliver. Now it''s senior year, and Miley is at a crossroads. After all these years, does she still have the best of both worlds? Can she continue her alter ego, Hannah Montana, or will she leave it all behind to be an ordinary girl?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 1, 'Sweet Home, Hannah Montana', 'Miley is forced to make an unwanted trip down memory lane after Robby has her room redecorated. Jackson becomes a believer in the golden rule once he lays eyes on his new neighbor.', 23, '2010-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 2, 'Hannah Montana to the Principal''s Office', 'Hannah enrolls in Seaview High after a mix up prevents Miley from attending the school for her senior year. Siena invites Jackson for an evening on the town.', 23, '2010-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 3, 'California Screamin''', 'Miley is finally ready for Robby to start dating again. Jackson eagerly awaits his first kiss from Siena.', 23, '2010-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 4, '‎De-Do-Do-Do, Da-Don''t-Don''t-Don''t Tell My Secret!', 'When Siena sees Hannah Montana outside the house, Jackson threatens to tell Siena the secret against Miley''s wishes. Meanwhile, Robby uses fishing to get Rico to relax.', 23, '2010-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 5, 'It''s the End of the Jake as We Know It', 'Oliver comes to visit Lilly and shows her a picture of Jake cheating on Miley. They try to keep this news from Miley, but when Miley says she wants Jake to come to visit, they decide to tell Miley the truth.', 23, '2010-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 6, 'Been Here All Along', 'Robbie''s feelings are hurt when Miley starts spending less time with him.', 23, '2010-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 7, 'Love That Let''s Go', 'Blue Jeans and Lilly are accidentally injured on a ride through the woods. Jackson tries to share Siena''s interest in reading, but he finds that her choices in literature are vastly different from his own.', 23, '2010-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 8, 'Hannah''s Gonna Get This', 'After having music block, Miley finally becomes inspired by the sounds that she hears around the pier.', 23, '2010-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 9, 'I''ll Always Remember You', 'Jay Leno and Dr. Phil guest star as themselves when international superstar Hannah Montana contemplates removing her blond wig and telling the world she''s really Miley Stewart.', 46, '2010-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 10, 'Can You See the Real Me?', 'In an interview with Robin Roberts, Miley describes what really went on during the years she lived a double life.', 23, '2010-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 11, 'Kiss It All Goodbye', 'Miley deals with her new life as a celebrity and finds her way back to the stage with help from her Aunt Dolly.', 23, '2010-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 12, 'I am Mamaw, Hear Me Roar', 'When graduation day arrives, Mamaw is disappointed that she couldn''t even get a picture with Miley because of her fans. Mamaw becomes distraught that her granddaughter is caring more about her fans than her own grandmother. Meanwhile, Rico tricks Jackson into saying that he wouldn''t be into Siena if she had short hair.', 23, '2011-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0493093')) AND numero_temporada = 4), 13, 'Wherever I Go', 'Miley gets a movie deal that will take a year away from her, making her incapable of going to college with her best friend. She keeps this from Lilly and tries to get Lilly to come to the decision of not wanting to go to college with Miley. Rico finds Jackson a dream job, and Rico and Jackson finally reveal that while they may fight, they are also close friends.', 52, '2011-01-16');
