INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')), 1, 'Season 1', 'Thanks to a childhood spent with a police officer father, Shawn Spencer possesses an incredible photographic memory and notices seemingly insignificant details. These traits allow him to spend his jobless days providing the police with mystery-solving tips—but his knowledge soon makes him a suspect. In order to clear his name, the unlikely sleuth declares that he has clairvoyant abilities and launches his own investigative agency, Psych, with his best friend Gus.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 1, 'Pilot', 'When Shawn Spencer is arrested for calling in an accurate tip to the police because only the perpetrator would know the details, his only way out is pretending to be a psychic.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 2, 'The Spellingg Bee', 'When what begins as a little competitive sabotage in a regional spelling bee quickly escalates to murder.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 3, 'Speak Now or Forever Hold Your Piece', 'Shawn and Gus become wedding crashers at a posh ceremony in order to retrieve a stolen antique engagement ring inexplicably taken from an inpenetrable vault under surveillance.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 4, 'Woman Seeking Dead Husband - Smokers Okay, No Pets', 'Shawn and Gus land their first non-SBPD case when a widow hires them to find some cash that her husband stole from a bank.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 5, '9 Lives', 'Shawn claims a psychic connection with a cat so he can continue his investigation into a what he believes is a murder, but that the police have labeled a suicide, and the link he finds to a hotline may involve one of SBPD''s own officers.', 43, '2006-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 6, 'Weekend Warriors', 'Shawn and Gus attend a Civil War reenactment rehearsal for the sheer pleasure of watching Lassiter have a nervous breakdown as he runs it.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 7, 'Who Ya Gonna Call?', 'Shawn reluctantly settles for a private client who claims a ghost has it in for him after Lassiter kicks Gus and him off the much more interesting case of a murdered psychologist.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 8, 'Shawn vs. the Red Phantom', 'Gus is ecstatic when it turns out the only real clue in his and Shawn''s missing-person case is TriCon, the comic book and science fiction convention currently running in Santa Barbara.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 9, 'Forget Me Not', 'Henry''s old captain believes he''s solved a murder, but his Alzheimer''s has caused him to forget the most important details: the crime, and who committed it.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 10, 'From Earth to Starbucks', 'When Lassiter doubts his own crime-solving ability, Shawn tries to boost his confidence by helping him solve an astronomer''s mysterious death.', 43, '2007-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 11, 'He Loves Me, He Loves Me Not, He Loves Me, Oops He''s Dead', 'The duo''s latest case, a gag from Lassiter, turns from an alien abduction investigation to a murder case with the discovery of naked body.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 12, 'Cloudy... With a Chance of Murder', 'A local weatherman is found dead the morning after a tryst and his lover is charged with his murder despite her claims of innocence.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 13, 'Game Set... Muuurder?', 'Lonely and bored, Shawn convinces Juliet to give him a shot with a case involving a missing tennis star, but first he has to spring an unwilling Gus from a corporate retreat.', 43, '2007-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 14, 'Poker? I Barely Know Her', 'Henry''s friend refuses to report his son, Brandon, missing after the son steals 30,000 dollars. Shawn agrees to help locate the son, and finds out that Brandon has been involved in some underground poker.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 1), 15, 'Scary Sherry: Bianca''s Toast', 'Juliet asks Shawn and Gus for assistance on her undercover assignment. They''re only too glad to help, since it involves sorority sisters. Unfortunately, what''s supposed to be an easy case turns out to have ties to their past and may endanger Juliet.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 1, 'American Duos', 'Shawn and Gus go undercover as talent show contestants to investigate a number of failed attempts to kill one of the judges.', 43, '2007-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 2, '65 Million Years Off', 'The discovery of a washed-up body sparks a debate between Shawn and the police, who both disagree as to how the man died.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 3, 'Psy vs. Psy', 'The FBI employs their own psychic in a search for a counterfeiter, causing the department to work together in an effort to prove that Shawn is the better psychic.', 43, '2007-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 4, 'Zero to Murder in Sixty Seconds', 'Shawn tracks down Lassiter''s car with little difficulty after it''s stolen. However, Shawn discovers that there''s more to the situation than meets the eye and calls Gus back from vacation to help with the investigation.', 43, '2007-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 5, 'And Down the Stretch Comes Murder', 'Gus and Shawn''s childhood nemesis, now a horse jockey, asks the duo for help in discovering why his horses never win. But the investigation develops into a murder case after a jockey dies while racing.', 43, '2007-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 6, 'Meat Is Murder, but Murder Is Also Murder', 'Shawn and Gus are put on the case when a food critic is murdered. However, Gus'' Uncle Burton is in town, and due to a misunderstanding, Gus must pretend to be the psychic detective to avoid disappointing his family.', 43, '2007-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 7, 'If You''re So Smart, Then Why Are You Dead?', 'Shawn and Gus take on academia as lecturers at a school for the gifted where two students suspect a teacher of murder, they just don''t know who''s been murdered or the murderer''s identity. At the precinct, Juliet lobbies hard for lead position on the next case, and Lassiter hands her a "gimme". The same case Gus and Shawn are working.', 43, '2007-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 8, 'Rob-a-Bye Baby', 'Shawn and Gus want to be put on Lassiter''s burglary case, but a sleep-deprived Chief Vick orders them to find her a nanny instead. Unfortunately, at least from Lassiter''s view, the two teams keep crossing paths, and Shawn sees an opportunity to horn in on the more interesting case.', 43, '2007-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 9, 'Bounty Hunters!', 'Shawn and Gus find themselves trying to outwit a bounty hunter when Juliet asks them to find a suspect who escaped from her custody. The problem is, once they find him, Shawn believes his claims of innocence, meaning they not only have to capture him, but prove he''s been set up.', 43, '2007-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 10, 'Gus'' Dad May Have Killed an Old Guy', 'Christmas with the Gusters is ruined when Gus'' parents'' neighbor is killed, a clue leads Lassiter to look at Mr. Guster more closely. Evidence leads the police into arresting Gus'' mother too, and Shawn and Gus vow to get them out of jail.', 43, '2007-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 11, 'There''s Something About Mira', 'Shawn is shocked when he learns that Gus is married after Gus'' wife unexpectedly shows up. She asks the men to take on a missing-persons case.', 43, '2008-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 12, 'The Old and the Restless', 'A missing persons case from a posh retirement community turns into a family affair when Shawn and Gus must team up with Henry to solve the case.', 43, '2008-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 13, 'Lights, Camera... Homicidio', 'The star of a Spanish telenovela has been murdered by another actor on the show. The murderer insists that it was an accident and claims that the prop knife was switched with a real knife without his knowledge. Shawn and Gus believe that he was framed and investigate the crime. Gus is especially excited to be working on the set of his favorite soap opera, but it''s Shawn who gets a recurring role on the show.', 43, '2008-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 14, 'Dis-Lodged', 'Henry bails on his weekend outing with Shawn, stating that he''s too ill to leave the house. Shawn is nowhere near upset until he and Gus catch Henry driving by, clearly not sick at all. Naturally, they follow him and discover he used to be a member of the Monarch Lodge, a clandestine society. They barge inside looking for an explanation and are surprised to find one of the Lodge members lying dead before them. Shawn suspects murder, and in order to conduct an inside investigation, he becomes a member of the society.', 43, '2008-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 15, 'Black and Tan: A Crime of Fashion', 'It''s Gus'' birthday, so Shawn takes him to the launch party for Ciao clothing''s new fall line. While Gus tries to make a move on his favorite model, one of the owners of Ciao is suddenly electrocuted via the stage''s microphone. Shawn is certain that his death was no accident, so Shawn and Gus move in to the loft where the Ciao models live.', 43, '2008-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 2), 16, 'Shawn (and Gus) of the Dead', 'Lassiter and Juliet get called to a museum to investigate the disappearance of a 3,000-year-old mummy. Lassiter insists it''s just a prank that''s not worth his time. He''s busy working on another case involving the death of philanthropist William Wyles III. However, the assistant curator insists that something weird is going on, something possibly supernatural that requires special help. Shawn is then brought in on the case, and he declares that the mummy was not stolen, iit walked away on its own.', 43, '2008-02-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 1, 'Ghosts', 'Gus'' supervisor, Frankjim Ogletree, demands that he quit moonlighting at Psych, lest he face termination. The vice-president of Gus'' pharmaceutical company, however, decides to hire the duo as his wife believes that their home is haunted.', 43, '2008-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 2, 'Murder?... Anyone?... Anyone?... Bueller?', 'Shawn and Gus attend their high school reunion. Shawn sees a body fly past a window, but on further inspection the body has vanished. When Gus assumes the worst, and Lassiter refuses to help, Shawn seeks assistance from Juliet.', 43, '2008-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 3, 'Daredevils!', 'Shawn and Gus get hired by the son of daredevil Dutch "The Clutch" Jenkins. They have to figure out what''s going on, after "accidents" keep happening to The Clutch.', 43, '2008-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 4, 'The Greatest Adventure in the History of Basic Cable', 'Henry''s brother, Jack, claims that he has a map that leads to buried treasure. Shawn and Gus assist Jack in his search for the treasure, but it turns out that Jack has got more going on than meets the eye.', 43, '2008-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 5, 'Disco Didn''t Die. It Was Murdered!', 'Eugene Franks, arrested by Henry in 1978 for plotting to bomb the SBPD, is released after his conviction is quashed by the D.A. When Shawn is instructed to solve the case, his father insists on helping him; however, the case is not as clear cut as he once thought.', 43, '2008-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 6, 'There Might Be Blood', 'Shawn and Gus investigate the death of a safety inspector aboard an offshore oil rig. The investigation is complicated by the commander of the coast guard, Barbara Dunlap, Chief Vick''s sister.', 43, '2008-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 7, 'Talk Derby to Me', 'A surveillance tape from the latest robbery in a string of break-ins leads Shawn to believe that women are the culprits. He futher narrows the suspects down to a local roller derby team and suggests that in order to pinpoint the people responsible, Juliet needs to go undercover as a member of their team. Though it''s technically her investigation, Shawn can''t help getting involved in the case.', 43, '2008-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 8, 'Gus Walks into a Bank', 'Gus is taken hostage at the Santa Barbara Savings and Loan Bank while making a deposit for Shawn.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 9, 'Christmas Joy', 'Shawn and Gus investigate a department store Santa who they suspect is up to no good. Meanwhile, Gus'' sister flies in for Christmas.', 43, '2008-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 3), 10, 'Six Feet Under the Sea', 'When Shabby the sea lion is found dead after being released into the wild, Shawn sets out to prove it was murder and stumbles onto a bigger mystery.', 43, '2009-01-09');
