INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 1, 'Extradition: British Columbia', 'Shawn and Gus spot an art thief whom Lassiter has been trying to arrest for years. So, although they are on a skiing vacation in Canada, they appeal to the local constabulary with mixed results: someone gets axed, another finds himself interrogated and Pierre Despereaux may get away scot-free, once again.', 43, '2009-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 2, 'He Dead', 'A billionaire hedge fund manager asks Shawn and Gus to find his murderer – a last request Shawn can''t resist. So he and Gus step into a world of privilege that''s rivaled only by the depths of betrayal it contains.', 43, '2009-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 3, 'High Noon-ish', 'Lassiter reluctantly asks Shawn and Gus for help when his surrogate father, sheriff of Sonora, thinks a ghost is wreaking havoc in his town. And even though this Wild West re-creation town is bigger on show than facts, it turns out a real crime is being planned and the murder of the Sheriff''s business rival is only the beginning.', 43, '2009-08-21');
