INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 5, 'Shawn Gets the Yips', 'After a cop bar is shot up in an apparent robbery during Officer McNab''s birthday celebration, Shawn realizes the shooter was actually targeting Lassiter.', 43, '2009-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 6, 'Bollywood Homicide', 'Raj, a young East Indian man whose serious girlfriends have all met with suspicious accidents, is convinced that he is the victim of a curse, but Shawn and Gus aren''t buying the supernatural explanation. They are convinced that a mysterious assailant is actually responsible and they''re out to catch the culprit.', 43, '2009-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 7, 'High Top Fade Out', 'Shawn and Gus investigate the death of Leonald Callahan, aka Diddle, a computer cryptologist who was the baritone in Gus’s old college a capella group.', 43, '2009-09-25');
