INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 13, 'Death Is in the Air', 'Shawn and Gus must recover a deadly pathogen before a thief releases it into the city.', 43, '2010-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 14, 'Think Tank', 'Shawn and Gus are recruited into a think tank to help prevent the murder of a business tycoon, but once the group has disbanded, they realize that one of the members plans to use the assassination ideas to kill the client instead of save him.', 43, '2010-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 4), 15, 'The Head, the Tail, the Whole Damn Episode', 'After Lassiter takes a page out of Shawn''s book and claims a shark attack victim was actually murdered, the guys must then scramble to find the fish and prove him right.', 43, '2010-03-03');
