INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 3, 'Not Even Close... Encounters', 'Shawn and Gus get themselves hired onto the case when an unstable lawyer claims his assistant was abducted by aliens.', 43, '2010-07-28');
