INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 5, 'Shawn and Gus in Drag (Racing)', 'When a member of a gang of car thieves turns up dead, Shawn and Gus must infiltrate a drag racing ring to find the killer. Shawn soon finds himself enjoying the fast lane too much, which not only endangers the investigation but also their lives.', 43, '2010-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 6, 'Viagra Falls', 'Shawn and Gus work with two retired police officers to solve the murder of a police chief.', 43, '2010-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 7, 'Ferry Tale', 'Shawn and Gus help a prison guard locate his escaped inmates while on a ferry boat headed to the Channel Islands.', 43, '2010-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 8, 'Shawn 2.0', 'Shawn has to face serious competition when a talented criminal profiler named Declan Rand comes to Santa Barbara to help solve the murders of donors on a liver-transplant list.', 43, '2010-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 9, 'One, Maybe Two, Ways Out', 'When a spy is framed for a crime she didn''t commit, she decides to use Shawn and Gus to prove her innocence.', 43, '2010-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 10, 'Extradition II: The Actual Extradition Part', 'Shawn and Gus return to Vancouver to visit their old nemesis Despereaux in prison at the felon''s request, who then uses them to escape and pull one last job before he is extradited to the United States. Only while he is out, he is framed for the murder of a Crown Attorney and now asks the guys for help clearing his name of this most recent – and frankly unseemly – charge.', 43, '2010-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 11, 'In Plain Fright', 'While on the haunted house ride at Santa Barbara''s Scare Fest, Shawn and Gus witness a murder and are soon led to believe the person who committed it is the ghost of a man who fell to his death at Scare Fest 13 years ago.', 43, '2010-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 12, 'Dual Spires', 'The episode kicks off with Shawn and Gus receiving a mysterious e-mail inviting them to the annual Cinnamon Festival in Dual Spires, a quirky Northern California town nearly invisible on the map. When they arrive the pair quickly find themselves embroiled in the mysterious death of local high school student Paula Merral. As Shawn and Gus unravel the many secrets of the town, they meet several local residents including town doctor/lawyer/veterinarian Donna Gooden, Sheriff Andrew Jackson, proprietors of the local diner Robert and Michelle Barker, the mysterious Woman with Wood and enigmatic bookish beauty Maudette Hornsby. The pool of suspects proves to be deeper than suspected as Shawn and Gus must work to figure out who killed Paula Merral.', 43, '2010-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 13, 'We''d Like to Thank the Academy', 'When they solve a case without following proper protocols, Shawn and Gus are ordered by the Chief to take a crash course at the police academy in order to learn the correct way to handle cases, but the two resort back to their old ways.', 43, '2010-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 14, 'The Polarizing Express', 'Due to an unlawful entry into a criminals property, Shawn gets suspended from his consultant postition and gets Henry fired from his position at the SBPD at the same time. Shawn has a series of Scrooge type dreams where Tony Cox is his ''spirit guide''.', 43, '2010-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 15, 'Dead Bear Walking', 'When a polar bear trainer is found dead, Shawn works to prove the bear''s innocence.', 43, '2010-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 5), 16, 'Yang 3 in 2D', 'The Yin/Yang trilogy comes to a thrilling close as Shawn and Gus race to save a woman kidnapped by Yin. Only this time, they are forced to use Yang''s knowledge of Yin to solve the case by allowing her to accompany them on the investigation.', 43, '2010-12-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 1, 'Shawn Rescues Darth Vader', 'Shawn stumbles across a dead body at the British consulate''s home while working a case to recover a stolen "Star Wars" collector''s item. In order to get the police on the case, Shawn claims he had a vision of the murder and puts his reputation as a psychic on the line.', 43, '2011-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 2, 'Last Night Gus', 'A night of partying which no one remembers that turned deadly sets Shawn, Gus, Woody and Lassiter on the trail of their deeds and a way to clear their names of suspected murder. Unfortunately, they may have to depend on Shawn''s "psychic" memories of the night''s events.', 43, '2011-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 3, 'This Episode Sucks', 'A body is discovered, and appears to have been killed by a vampire. Meanwhile, Lassiter becomes romantically involved with a woman whom Shawn suspects is the murderer.', 43, '2011-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 4, 'The Amazing Psych-Man & Tap Man, Issue #2', 'Shawn and Gus investigate the whereabouts of a mysterious, masked vigilante named The Mantis, who is trying to take down a local drug syndicate called The Caminos. The SBPD is also trying to take down The Camino syndicate, however The Mantis always seems to be one step ahead of everyone''s game. Joey McIntyre and Miles Fisher guest star.', 43, '2011-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 5, 'Dead Man''s Curveball', 'When the hitting coach of the Santa Barbara Seabirds suddenly dies, the team''s manager hires Shawn and Gus to go undercover as the new coach and mascot in order to investigate.', 43, '2011-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 6, 'Shawn, Interrupted', 'After a billionaire murderer pleas insanity at his trial, Shawn and Gus go undercover at a mental hospital in order to prove that the man is, in fact, sane. While at the hospital, Shawn and Gus receive some hostility from one of the nurses.', 43, '2011-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 7, 'In for a Penny...', 'Juliet''s con-man father travels to Santa Barbara to reunite with his daughter, but finds himself slipping back into his criminal past when confronted with a dream con.', 43, '2011-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 8, 'The Tao of Gus', 'After a woman tells the SBPD she witnessed a murder happen in broad daylight, Shawn and Gus are the only ones who believe her, and therefore protect her by hiding her at a remote commune called Box Canyon Ranch, a place whose inhabitants label themselves as progressive intellectuals.', 43, '2011-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 9, 'Neil Simon''s Lover''s Retreat', 'Shawn and Juliet''s romantic getaway vacation to a spa gets interrupted by robberies and a dead body at a nearby winery.', 43, '2011-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 10, 'Indiana Shawn and the Temple of the Kinda Crappy, Rusty Old Dagger', 'Shawn and Gus team up with Despereaux to locate a mythical dagger rumored to be the key to unlocking a dead billionaire''s treasure.', 43, '2012-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 11, 'Heeeeere''s Lassie!', 'Lassiter hires Shawn and Gus to get to the bottom of strange occurrences at his new condo.', 43, '2012-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 12, 'Shawn and the Real Girl', 'Shawn and Gus go undercover to investigate an attack on a reality-TV contestant who appeared on a dating show in which men compete for the affections of a woman they''ve crossed paths with but never officially met.', 43, '2012-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 13, 'Let''s Doo-Wop It Again', 'When the founder of "Right Now", Santa Barbara''s oldest at-risk youth program, is shot and almost killed, Shawn, Gus and a few members of Gus''s a capella group from college investigate to find the culprit.', 43, '2012-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 14, 'Autopsy Turvy', 'The race is on to clear Woody''s name and reputation when a mere mortician finds a mistake in the coroner''s autopsy.', 43, '2012-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 15, 'True Grits', 'A wrongly convicted Southern chef hires Shawn and Gus to find the real thief after the Innocence Project frees him from prison.', 43, '2012-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 6), 16, 'Santabarbaratown', 'A body relating to a 20-year-old case is finally found, and Shawn, Gus, and Henry revisit all the old suspects in order to solve the case', 43, '2012-04-11');
