INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 5, '100 Clues', 'On the 100th episode of Psych... Shawn and Gus attend a party hosted by an aging rockstar named Billy Lipps, a man the SBPD arrested years ago for a murder he doesn''t remember committing.', 43, '2013-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 6, 'Cirque du Soul', 'After Gus is tasked with taking care of his girlfriend''s son Maximus for the day, he jeopardizes their relationship when an innocent trip to the circus turns deadly.', 43, '2013-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 7, 'Deez Nups', 'The gang spends the weekend at a casino resort for a wedding and crosses paths with a local crime boss whose presence jeopardizes the impending nuptials.', 43, '2013-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 8, 'Right Turn or Left for Dead', 'Shawn solves a case involving a mysterious Swedish woman and imagines how the same case would have been solved had he done one thing differently.', 43, '2013-04-17');
