INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 10, 'The Santabarbarian Candidate', 'After the Mayor dies in what appears to be a surfing accident, Shawn investigates and ends up running for mayor himself.', 43, '2013-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 11, 'Office Space', 'After Gus accidentally tampers with the crime where his boss was killed, Shawn helps him find the real murderer before Gus is arrested.', 43, '2013-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 12, 'Dead Air', 'After Shawn and Gus'' favorite radio DJ is murdered, they go undercover as on-air personalities to find his killer.', 43, '2013-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 13, 'Nip and Suck It!', 'After a woman dies from what appears to be a plastic surgery mishap, Shawn and Gus believe the killer is her doctor, a woman who happens to be an old flame of Henry''s.', 43, '2013-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 14, 'No Trout About It', 'An eccentric police consultant is brought into the SBPD to interview Shawn, Gus, Lassiter and Juliet about their seemingly poor police work on a tough case.', 43, '2013-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 7), 15, 'Psych: The Musical', 'This musical extravaganza follows Shawn and Gus'' search for an escaped playwright who was declared criminally insane following a suspicious fire. Complicating matters, a person who may have important evidence is an enemy from Shawn''s past.', 86, '2013-12-15');
