INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 1, 'Lock, Stock, Some Smoking Barrels and Burton Guster''s Goblet of Fire', 'Stylish art thief Pierre Despereaux summons Shawn to London to help on an undercover operation.', 43, '2014-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 2, 'S.E.I.Z.E. the Day', 'Lassiter receives some life-changing news and begins to lose his nerve on the job. As a result, he enlists Shawn and Gus to help him take down a dangerous criminal who tried to kill the SBPD’s Interim Chief while he was giving a speech at a press conference.', 43, '2014-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 3, 'Remake A.K.A. Cloudy... With a Chance of Improvement', 'A star studded cast of Psych ALL STARS joins our crew as they dive back into 2006 and re-tell the story of Sandra Panitch, a woman wrongfully accused of the murder of local weatherman Jackson Hale.', 43, '2014-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 4, 'Someone''s Got a Woody', 'A man enters the morgue and tells Woody that he was framed for the murder of the person lying dead on the slab. When Woody won’t let him take the body, the man pulls a gun on him and holds Woody hostage in order to get what he wants. Shawn, Gus, Lassiter and Juliet try to resolve the situation calmly and carefully, but Interim Chief Trout has a plan of his own.', 43, '2014-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 5, 'Cog Blocked', 'Gus is determined to solve the murder of a man whose life was strangely similar to his own. Along the way, Gus hits it off with a beautiful Private Investigator named Emanuelle. Meanwhile, Shawn realizes he''s been mooching off of Gus, Henry and Juliet, so he tries desperately to make up for it.', 43, '2014-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 6, '1967: A Psych Odyssey', 'Lassiter is determined to be appointed Chief of Police, so he sets out to prove himself worthy of the job by solving the murder of the Mayor’s beloved uncle, Archie Baxter, who was killed back in the 60s but the case was never solved. Meanwhile, Juliet receives some news that tests her relationship with Shawn.', 43, '2014-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 7, 'Shawn and Gus Truck Things Up', 'Shawn and Gus are bummed to find out the owner of their favorite food truck has been murdered. The two of them go undercover to learn the food truck ropes and find out who the killer is. While working on the case, Marlowe visits them to cure a pregnancy craving and goes into labor at the most inconvenient time.', 43, '2014-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 8, 'A Touch of Sweevil', 'Shawn is ecstatic when he discovers he’s finally been invited to a prestigious paranormal convention for police consultants. As the main event begins, the leader collapses on stage, and it is clear he has been murdered. All of the police consultants on the panel jump to solve the murder, and everyone’s unorthodox crime solving skills are put together to catch the culprit.', 43, '2014-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 9, 'A Nightmare on State Street', 'Gus'' nightmares start to feel like reality when he and Shawn work to solve an unlikely case for the SBPD.', 43, '2014-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0491738')) AND numero_temporada = 8), 10, 'The Break-Up', 'Shawn and Gus help Detective Lassiter enlist the help of Henry and Woody to solve the murder of a real estate executive. Meanwhile, Shawn struggles with a life decision.', 43, '2014-03-26');
