INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0496424', '30 Rock', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0769135'), 'SERIE', 'Liz Lemon, head writer of the sketch-comedy show "TGS with Tracy Jordan", must deal with an arrogant new boss and a crazy new star while trying to run a successful television show without losing her mind.', '2006-01-01', 'https://m.media-amazon.com/images/M/MV5BMTQ4NDQ4OTUzOV5BMl5BanBnXkFtZTcwMjMzMTUyNw@@._V1_.jpg');
