INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 1, 'Pilot', 'Liz Lemon is the head writer on a demanding, live TV program in New York City. However, things begin to get complicated when her new boss insists that a wild and unpredictable movie star joins the cast.', 22, '2006-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 2, 'The Aftermath', 'Now that major changes have occurred on the The Girlie Show, Liz struggles to bring everyone and everything together. However, despite his erratic behavior, Tracy manages to bring everything to order.', 22, '2006-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 3, 'Blind Date', 'Jack sets Liz up on a blind date with his friend, Thomas. While Liz is busy preparing for the date, Jack infiltrates the writers'' weekly poker game.', 22, '2006-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 4, 'Jack the Writer', 'Liz struggles to keep Jack out of the writers'' room and Kenneth soon learns that working for Tracy may be more than he expected.', 22, '2006-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 5, 'Jack-Tor', 'After being pressured by Jack to plug GE products into her show, Liz integrates Jack into a sketch. While Jack hones his questionable acting chops, Frank and Toofer trick Jenna into fearing for her job and Liz wonders if Tracy is faking illiteracy to skip out on rehearsals.', 27, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 6, 'Jack Meets Dennis', 'After Liz takes her ex-boyfriend, Dennis, back simply because he asks, Jack takes it upon himself to mentor her as he thinks that she is leading a life of mediocrity. Meanwhile, Tracy gets a tattoo in the face, Jenna gets botox and collagen injections, and Josh is given two black eyes by an angry Liz Taylor.', 22, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 7, 'Tracy Does Conan', 'Jack bumps Jenna''s scheduled appearance on ''Late Night with Conan O''Brien'' by booking new star Tracy. Jenna, still irate over watching the show change to "TGS with Tracy Jordan," lashes out at Liz. To make matters worse, Tracy''s gone off his medication and he''s about to go on national television.', 22, '2006-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 8, 'The Break-Up', 'When Liz finally dumps her boyfriend Dennis, she prowls the singles scene under Jenna''s tutelage. Love also stinks for Jack, as he discovers dating a Bush administration official has its downside. And Tracy and Toofer clash, which lands both in sensitivity training.', 22, '2006-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 9, 'The Baby Show', 'When ditzy receptionist Cerie spreads news of her engagement to a filthy rich Greek heir, Liz confronts her own marital and maternal status. Meanwhile, emotionally hardened Jack softens due to "mommy issues."', 22, '2007-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 10, 'The Rural Juror', 'Jenna anticipates the opening of her independent movie “The Rural Juror”, but the title proves to be a mighty tongue twister for the gang. Meanwhile, cash-challenged Tracy endorses his own celebrity product in an effort to get out of debt.', 22, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 11, 'The Head and the Hair', 'Liz and Jenna work on their dating game when they''re beguiled by two very different MSNBC staffers: a brainy geek and a brawny hunk, but cerebral Liz finds it strange that she''s more interested in the attractive one. Meanwhile, Kenneth and Jack switch roles.', 22, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 12, 'Black Tie', 'Liz wonders if she''s actually on a date with Jack as she accompanies him to a birthday celebration for a foreign prince. While at the ball, Liz sees a different side to Jack as he unexpectedly runs in to his ex-wife. Back at 30 Rock, Tracy tempts Pete with a booze- and babe-filled party in the office, while Kenneth tries to keep Pete on the straight and narrow.', 22, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 13, 'Up All Night', 'It''s Valentine''s Day, and the TGS crew is celebrating by pulling an all nighter to put together a new episode. While Pete completely forgets the holiday, Kenneth and Cerie may be starting an office romance. Meanwhile, Liz wonders if Dennis is back in her life after she receives flowers from a secret admirer and newly divorced Jack wants to party with Tracy, who for once wants to spend a night alone with his wife instead.', 22, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 14, 'The C Word', 'As shocked as she is to be called the c-word by Lutz, Liz is more horrified to realize he may be right. Meanwhile, Jack brings Tracy to a charity golf event to get closer to the chairman, however his plan backfires when Tracy acts too much like his uncensored self.', 22, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 15, 'Hard Ball', 'Jack sees an opportunity for budget cuts when Josh''s contract is up, forcing Liz to go out of her way to motivate Josh into staying with TGS and not moving on to a rival show. Meanwhile, Kenneth earns a coveted spot in Tracy''s entourage and Jenna gets in trouble over a misquote in Maxim.', 22, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 16, 'The Source Awards', 'Jack forces Tracy to attend the Source Awards and Kenneth has words with a rap artist. Meanwhile, Liz goes to great lengths to prove to her African-American date that she''s not racist.', 22, '2007-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 17, 'The Fighting Irish', 'Jack helps his brother Eddie land a job at ''TGS'', Liz is forced to make desperate staff cutbacks, and Tracy seeks spiritual fulfillment with help from Kenneth.', 22, '2007-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 18, 'Fireworks', 'Jack and Kenneth work together when Jack discovers that another NBC executive is after his job. Meanwhile, Pete and Liz adjust to life as roommates and Tracy receives paternity papers.', 22, '2007-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 19, 'Corporate Crush', 'The tables have turned inside 30 Rock: Liz is actually happy in her new relationship with Floyd while Jack finds his job may be in jeopardy after his televised fireworks fiasco prompts top GE man Don Geiss to warn he''s got his eye on Jack''s performance. Tracy vies for Geiss'' attention, hoping to turn his feature film idea for Jefferson into a reality.', 22, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 20, 'Cleveland', 'Sick of New York and frustrated with his career, Floyd contemplates a move to the Midwest and asks Liz if she''s consider leaving TGS behind. Jack rushes to Paris (and soon, the altar) with Christie''s auctioneer Phoebe while Tracy works furiously on financing his latest career move, dubbed the "Tracy Jordan Comeback."', 22, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 1), 21, 'Hiatus', 'As TGS'' summer hiatus approaches, Liz deals with the difficulties of her long-distance relationship with Floyd while she enlists Kenneth''s help in locating on-the-lam Tracy. Meanwhile, Jack''s impending marriage to Phoebe brings his mother, Colleen Donaghy to town.', 22, '2007-04-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 1, 'Seinfeldvision', 'As the cast and crew of TGS with Tracy Jordan returns for a new season, Liz is excited to see Jack again. However, her excitement quickly fades as Jack insists that Liz is still not over Floyd. Meanwhile, Jerry Seinfeld shows up at Jack''s office in an upset mood after Jack announces his newest plan. Finally, Kenneth becomes Tracy''s office wife when Tracy separates from his wife and Jenna returns to set a whole lot heavier now that she has been involved in Mystic Pizza: The Musical!.', 22, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 2, 'Jack Gets in the Game', 'When Jack discovers that his boss is retiring, he decides to get in the competition for his position. Meanwhile, Jenna begins to enjoy her fame for being fat and along with Jack encourages Liz to get her act together. Finally, Kenneth makes it his mission to get Tracy and Angie back together.', 22, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 3, 'The Collection', 'Jack hires his own private investigator to lead GE in the wrong direction so that they will not be able to find any dirt on him that might put him in a compromising position. However, when he is asked to give up his cookie jar collection, Jack finds the task too much of a challenge. Meanwhile, Angie announces that she will follow Tracy at all times to keep him in line, which Liz believes to be good until she covers for Tracy and gets on Angie''s bad side. Finally, Jenna starts to worry once she starts to lose all the weight she gained over the summer and her popularity begins to hang on the line.', 22, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 4, 'Rosemary''s Baby', 'Liz meets her longtime idol, Rosemary Howard, and invites her to be a guest writer on "TGS with Tracy Jordan". However, Rosemary''s ideas turn out to be too much for the show, prompting Jack to pressure Liz into firing her. Meanwhile, Jack takes Tracy to a therapist to explain to him why he must do the opposite of what he is told, and Jenna ruins Kenneth''s page jacket, causing him to compete in a page-off to keep his job.', 22, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 5, 'Greenzo', 'It''s time for Kenneth''s annual house party, but he may be the only one excited about it. The soiree has only been attended by Liz in the past, so in order to get a better turnout Tracy spreads rumors that ultimately get out of hand.  Meanwhile, Jack deals with NBC''s new environmentally-friendly mascot, whose new-found stardom goes to his head.', 22, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 6, 'Somebody to Love', 'Jack falls for a congresswoman he meets at a cocktail party and despite the fact that they hold opposite views, the couple agrees to put politics aside and have a secret affair. Meanwhile, Liz believes her Middle Eastern neighbor to be a terrorist and tips off Homeland Security, creating a big mess.', 22, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 7, 'Cougars', 'As part of his community service, Tracy must coach a little league team. All goes well until Jack takes interest in the team and turmoil starts from there. Meanwhile, Liz is asked out on a date by Jamie, the new coffee boy, who thinks Liz is actually younger than she truly is.', 22, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 8, 'Secrets and Lies', 'C.C. and Jack face a block in their relationship when C.C. decides to go public about the affair but Jack refuses. Meanwhile, Liz struggles to keep both Tracy and Jenna happy when the two find it hard to share the spotlight, while Frank makes fun of Toofer''s Harvard education with bizarre results.', 22, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 9, 'Ludachristmas', 'Jack gets attached to Liz''s nurturing parents because they provide the love and support he never got from his mom. The staffers get ready for their raunchy holiday party, but Kenneth changes their plans at the last minute.', 22, '2007-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 10, 'Episode 210', 'Jack and C.C. try to make their long distance romance work, Liz decides to invest in real estate, and Kenneth becomes addicted to caffeine.', 22, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 11, 'MILF Island', 'When someone on the ''TGS with Tracy Jordan'' staff insults Jack in a newspaper article about the season finale of ''MILF Island'', he frantically sends Jonathan to interrogate everyone on ''TGS'' until the culprit is found.', 22, '2008-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 12, 'Subway Hero', 'Dennis becomes a New York City celebrity after jumping in front of a train and saving someone who fell on the tracks. Meanwhile, Jack desperately tries to persuade Tracy to become the celebrity face of the Republican Party.', 22, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 13, 'Succession', 'When Don decides to promote Jack and make him his successor over Devon, Jack decides to give his old job to Liz because she always has his back. However, a turn of events concerning Don''s health compromises Jack''s promotion. Meanwhile, Tracy thinks that his son is embarrassed of his career because he did not invite him to fathers day at school.', 22, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 14, 'Sandwich Day', 'Floyd stays at Liz''s place overnight when his flight is canceled. Meanwhile, Jack is demoted to the 12th floor, causing him to question his future status at the company. Finally, the staff celebrates Annual Sandwich Day with mysterious sandwiches from a secret location in Brooklyn.', 22, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 2), 15, 'Cooter', 'In the second season finale, Jack moves on to a new job involving politics in Washington, but the position is not quite what he anticipated. Meanwhile, Liz suffers a pregnancy scare, Kenneth confronts rival page Donny when applying for a summer job, and Tracy works on his latest invention.', 22, '2008-05-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 3, 'Season 3', 'Liz focuses heavily on her personal life, trying to adopt a child and find a new romantic partner. Meanwhile, Jack Donaghy pursues a new relationship, Jenna Maroney undertakes a new Janis Joplin-based film project, and Tracy Jordan enjoys the success of his video game developed at the end of the previous season.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 1, 'Do-Over', 'Worried that Liz''s hectic lifestyle may be too much to adopt a child, Bev, the adoption agent, visits the set. Panicked, Liz tells everyone to act normal, but chaos soon ensues as a fight arises between Jenna and Tracy. Meanwhile, Jack returns to 30 Rock and vows to do whatever it takes to get his position back from Devin.', 22, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 2, 'Believe in the Stars', 'Liz heads to Chicago to get out of jury duty and on her flight back to New York she is assigned a seat next to Oprah. Liz seizes the opportunity to ask Oprah for advice with some of the problems she''s been having. Back in New York, the feud continues between Tracy and Jenna, and Jack''s morals are tested by Kenneth after an Olympics snafu.', 22, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 3, 'The One with the Cast of Night Court', 'Liz and Jenna are randomly visited by Claire Harper, a free-spirited, Fatal Attraction-like stalker. Claire first targets Jack and claims him for her own. Kenneth, distressed and disappointed by the new page uniforms, looks to be cheered up by Tracy. To make Kenneth smile again, Tracy gives him a surprise which involves the cast of ''Night Court''.', 22, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 4, 'Gavin Volure', 'Jack and Liz make a visit to a colorful businessman named Gavin Volure, who has a confidential business proposal...and has fallen in love with Liz. Meanwhile, Tracy is afraid that his kids may have figured out an evil plot against him.', 22, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 5, 'Reunion', 'Jack manages to convince a reluctant Liz to attend her high school reunion. Meanwhile, Don Geiss awakens from his coma and shocks Jack with a declaration of who he wants to be the CEO of GE. A shaken Jack decides he needs to get away and blow off some steam, but tags along with Liz to her reunion instead due to bad weather.', 22, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 6, 'Christmas Special', 'As Christmas nears, Liz''s parents ditch her for a couples-only retreat, leaving her all alone for the holiday. Because of this, Liz decides to work for a charity program, "Letters to Santa." Meanwhile, Jack takes his frustration out on the staff after his dream holiday is ruined.', 22, '2008-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 7, 'Señor Macho Solo', 'Amid a health scare that sees him growing close to his mother''s nurse, Jack helps Tracy and his wife Angie develop a "post-nup" and gets Jenna an audition to play Janis Joplin. Jenna thinks Liz is only attracted to a little person because she wants a child.', 22, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 8, 'Flu Shot', 'Flu is spreading amongst the "TGS" cast and crew fast, and Liz is determined not to catch it too. Dr. Spaceman is giving vaccinations, but Jack is being selective about who gets one. Liz is offered one, but refuses to accept it, championing the rights of the crew. Meanwhile, Jack must be creative if he is to spend any time with Elisa, since she is working seven days a week.', 22, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 9, 'Retreat to Move Forward', 'Jack nervously coaxes Liz into joining him at a corporate retreat. Meanwhile, Jenna employs method acting techniques in preparing for her role as Janis Joplin, with Frank''s help. And Kenneth wants to prove to Tracy that diet impacts diabetes.', 22, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 10, 'Generalissimo', 'Liz tries to begin a relationship with a new tenant after accidentally receiving his mail. Meanwhile, Jack''s appearance causes Elisa''s grandmother to disapprove of the relationship, and Tracy has trouble maintaining the lifestyles of Wall Street frat boys.', 22, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 11, 'St. Valentine''s Day', 'Liz insists that she and Drew have their first official date on Valentine''s Day. Elisa brings Jack to church to celebrate the day, which is very different from the way he traditionally celebrates. Kenneth employs the help of Tracy to try to win the affection of a new worker.', 22, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 12, 'Larry King', 'Jack wonders if his career will get in the way of taking his relationship with Elisa to the next level. Tracy does an interview with Larry King and causes mayhem throughout New York City. Liz loses her cell phone in a cab and brings Kenneth with her out to Queens to retrieve it.', 22, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 13, 'Goodbye, My Friend', 'Liz befriends a pregnant teenager from a donut shop she visits in the hopes to adopt her baby. Kenneth plans a combined birthday party for Tracy and Jenna, but Jenna wants all of the attention and a party of her own. Jack agrees to go out and party with Frank to keep his mind off of his absent girlfriend and ends up bonding with him over their parental issues.', 22, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 14, 'The Funcooker', '30 Rock is left in shambles by the cast and crew after Liz is called away for jury duty. Meanwhile, Jack fails to listen to everyone when he becomes obsessed with launching a new big-money product.', 22, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 15, 'The Bubble', 'Liz gives attention to her building relationship with Drew, and discovers that he has been granted special treatment in life due to his pleasing appearance. Meanwhile, Jack goes all out to re-sign Tracy now that his contract has expired. And Jenna''s latest ploy to attract attention is to change her hairstyle.', 22, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 16, 'Apollo, Apollo', 'While Jack puts together the perfect 50th birthday party for himself, home videos inspire him to try to recreate his happiest moment. Dennis decides to tell Liz about his addiction. Meanwhile, Kenneth and Pete work to make Tracy''s childhood dream come true.', 22, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 17, 'Cutbacks', 'Despite the 50th episode of TGS airing, everyone is preoccupied with news of budget cuts. Jack has to dole out cutbacks while Kenneth has to take on extra duties. Meanwhile, Liz tries to save her staff and crew and Jenna and Tracy try to uncover Kenneth''s secret.', 22, '2009-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 18, 'Jackie Jormp-Jomp', 'During her short-term suspension, Liz is lost without TGS and the stress that comes with her job. Jack works with Jenna so she can use her celebrity status to generate some promotional buzz for her Janis Joplin bio-film.', 22, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 19, 'The Ones', 'Jack goes shopping for an engagement ring, for Elisa, with Liz. Elisa tells Liz a secret, and a prank results in an injury back at TGS.', 22, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 20, 'The Natural Order', 'When Liz reprimands Tracy in front of the TGS staff, Tracy asks Liz to stop giving him preferential treatment. Liz agrees, but Tracy thinks that Liz should give up some of her privileges also. Jack remembers some unpleasant memories of his father after his mother, Colleen, visits. Jenna adopts a pet gibbon.', 22, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 21, 'Mamma Mia', 'Liz and Tracy encourage Jack to search for his real father. Tracy meets his new found illegitimate son, but Liz and Pete question the son''s intentions. Jenna takes the credit for one of Liz''s ideas.', 22, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 3), 22, 'Kidney Now!', 'Jack''s biological father''s health hangs in the balance as the pair start to build a relationship. Liz draws some attention as a relationship expert, despite her own many failed relationships, after an appearance on a talk show. Tracy is invited to speak at his old high school and Kenneth helps him overcome some embarrassing memories from those years.', 22, '2009-05-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 1, 'Season 4', 'Jack demands changes to make TGS both more relatable to average Americans and more cost-conscious and sends Liz and Pete to search for fresh blood. Kenneth organizes a strike by the pages.', 22, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 2, 'Into the Crevasse', 'Jack tries to protect his job and the company when Devin returns to seek revenge; Tracy and Jenna try to make Liz''s life miserable; Kenneth volunteers at an animal shelter.', 22, '2009-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 3, 'Stone Mountain', 'Jack and Liz search for new talent as they travel to Kenneth''s hometown. Jenna makes an attempt to become friends with the writers. Tracy fears he may die next after a pair of celebrities pass away.', 22, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 4, 'Audition Day', 'Liz and Pete try to rig the audition process; Tracy and Jenna decide they should conduct their own search for the next ''TGS'' star.', 22, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 5, 'The Problem Solvers', 'The crew awaits the arrival of the new cast member. Tracy and Jenna rethink how they treat Kenneth. Jack offers Liz a talk show.', 22, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 6, 'Sun Tea', 'When Liz''s apartment building is converted to condos she has to make a drastic change to her living arrangements. Meanwhile, Jack and Tracy reevaluate their plans for parenthood and Kenneth is on a mission to make "TGS" greener during NBC''s annual "Green Week."', 22, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 7, 'Dealbreakers Talk Show #0001', 'The tables are turned when production begins on Liz’s new talk show, “Dealbreakers,” and she experiences what its like to walk a mile in Jenna’s  shoes. Jack, dealing with pressure from Devin, calculates to make “Dealbreakers” a success. Meanwhile, Tracy takes on the ultimate Hollywood challenge in order to prove his commitment to his wife. Everyone pitches in to help Tracy reach his goal including Kenneth, Dotcom  and Grizz.', 22, '2009-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 8, 'Secret Santa', 'Jack’s interest in a new social networking site unexpectedly reconnects him with a high school crush. Kenneth tries to organize a Secret Santa Fun Swap, but not without resistance from some of the staff members. Meanwhile, Liz battles the task of buying a gift that’s good enough for Jack, and Jenna is horrified at the prospect of sharing her annual Christmas solo.', 22, '2009-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 9, 'Klaus and Greta', 'Following a wild New Year''s Eve, Jack has to try to repair the damage he did after leaving a drunken message on an ex''s voicemail. Meanwhile, Jenna tries to get into a relationship with James Franco in order to cover up his secret; and Liz, after accidentally "outing" her cousin to his family, welcomes him to New York City; and Tracy finds new respect for women.', 22, '2010-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 10, 'Black Light Attack!', 'Jack tries to squash the burgeoning relationship between Liz and Danny. Tracy asks Sue to be in his entourage. Jenna tries out for Gossip Girl.', 22, '2010-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 11, 'Winter Madness', 'Hoping to boost staffers'' spirits, Liz takes TGS on the road, but Jack takes over for his own reasons, and the staff find reasons to blame Liz for all that''s wrong in their lives.', 22, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 12, 'Verna', 'Jenna''s mother comes to visit, and she looks to Jack to help. Frank moves in with Liz as a boarder, and they decide to aid one another stop some bad habits.', 22, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 13, 'Anna Howard Shaw Day', 'Liz schedules a root canal to avoid feeling lonely on Valentine''s Day; Jack woos an attractive and successful TV host; Jenna''s stalker loses interest.', 22, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 14, 'Future Husband', 'Liz searches for a man she met in her dentist''s waiting room. Jack fears for the future when he learns a cable company may have its sights on NBC. Jenna helps Tracy try to get a Tony award.', 22, '2010-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 15, 'Don Geiss, America and Hope', 'Jack needs to reestablish himself within the new corporate structure. Liz and Wesley continually run into each other, making them consider fate''s role in their lives. Tracy''s nanny writes an exposé.', 22, '2010-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 16, 'Floyd', 'Liz reevaluates her feelings for an old flame, Floyd, when he returns with big news, and Jack Donaghy teaches Danny Baker the finer points of pranks after the TGS writers play a trick on him. Jenna Maroney and Tracy Jordan see Kenneth Parcell in a disturbing new light after they spend a very long day listening to him tell stories about his childhood.', 22, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 17, 'Lee Marvin vs. Derek Jeter', 'Liz Lemon starts making an effort to date by attending singles events with Jenna Maroney, and Jack Donaghy feels forced to choose between childhood love, Nancy Donovan and news anchor Avery Jessup. Meanwhile, a racist comment sparks an office-wide debate on affirmative action and leaves Toofer with a big decision to make regarding his future at TGS.', 22, '2010-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 18, 'Khonani', 'Liz discovers that the TGS staff have been excluding her from their weekly hangouts, and strives to prove that she can be fun. Jack must choose between janitors and the shift time they both want, and Kenneth aids Tracy Jordan in being a good husband.', 22, '2010-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 19, 'Argus', 'Wedding fever hits TGS, leaving Liz to sort out Grizz''s dilemma when both Tracy and Dot Com want to be his best man. Jenna''s new boyfriend, Paul, raises Liz and Pete''s suspicions, while Jack is finally forced to deal with the death of his mentor, Don Geiss, when Geiss leaves him a strange but meaningful inheritance.', 22, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 20, 'The Moms', 'Liz Lemon meets her mother''s old flame, while Jack Donaghy''s mother, Colleen, gets tangled in his relationships with Avery Jessup and high school love, Nancy Donovan. Jenna''s mother, Verna returns, while Tracy learns a lesson from his "mom".', 22, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 21, 'Emanuelle Goes to Dinosaur Land', 'Jack becomes even more entangled in his love triangle between Avery Jessup and Nancy Donovan, and he turns for advice to Liz, who is focusing on her own romantic problems. When Liz can''t find a date to Floyd''s wedding, she revisits her old boyfriends in hope that a spark will reignite. Meanwhile, Tracy continues his journey to earn his egot.', 22, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 4), 22, 'I Do Do', 'Liz questions fate when she meets the man of her dreams, while Jack''s love triangle between high school love, Nancy Donovan, and CNBC anchor, Avery Jessup, comes to a head. Meanwhile, Jenna''s boyfriend is confronted with a similar dilemma when his desire for another woman threatens to ruin their relationship, and Kenneth, with the help of Tracy, tries to avoid a promotion that would land him in LA.', 22, '2010-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 1, 'The Fabian Strategy', 'Jack begins to meddle in Liz''s new relationship with Carol.', 22, '2010-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 2, 'When It Rains, It Pours', 'Liz uses her newfound confidence to solve Pete''s problem with a difficult editor (Paul Giamatti); Jack tries to cheat mortality; Tracy vows to be present when his wife gives birth.', 22, '2010-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 3, 'Let''s Stay Together', 'Jack must appear before Congress to discuss NBC''s merger with KableTown. He hopes that he will charm celebrity members, but one Congresswoman, Regina Bookman, demands more diversity in its programming lineup. Jack quickly enlists Tracy to come up with some new development ideas. Meanwhile, Liz is fed up with the flack her writing staff gives her, and Jenna helps Kenneth reapply to the extremely competitive Page Program.', 22, '2010-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 4, 'Live Show', 'On show night, Liz Lemon grows increasingly infuriated when no one seems to remember that it''s her 40th birthday. Just before the taping, Tracy Jordan becomes convinced that nothing is funnier than a performer laughing and breaking character, which he elects to do all night, much to Jenna Maroney''s chagrin. Meanwhile, Jack Donaghy struggles with the consequences of his promise to give up drinking while Avery is pregnant.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 5, 'Reaganing', 'Jack''s determined to save Liz''s relationship with Carol and Tracy shoots a commercial.', 22, '2010-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 6, 'Gentleman''s Intermission', 'Avery Jessup becomes suspicious of the relationship her fiancé Jack Donaghy has with his employee and friend Liz Lemon, so she orders Jack to set boundaries in their friendship. This proves a problem for Liz when her father, Dick Lemon arrives in town on a break from his marriage. Meanwhile, actor Tracy Jordan is upset when he discovers that his pre-recorded NBC obituary shows him to have done nothing worthwhile in his life, whilst Jenna Maroney learns of the video obituaries, she decides to make a video of her own.', 22, '2010-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 7, 'Brooklyn Without Limits', 'Jack rocks the vote, manipulating a congressional election to help a particular candidate, thereby leveraging advantage for the network. Meanwhile, a perfect pair of new jeans gives Liz confidence; Tracy organizes a Golden Globe event with Jenna''s help.', 22, '2010-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 8, 'College', 'Jack worries that GE''s microwave sales have improved too much without his help and tries to find glitches in their newest design. Meanwhile, Liz partakes in a crew lottery despite Jenna and Tracy''s warning her not to do so. Elsewhere, the TGS writers discover that Jack is the voice of an online dictionary''s pronunciation guide.', 22, '2010-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 9, 'Chain Reaction of Mental Anguish', 'Jack recommends that Liz start seeing a therapist when she worries that Carol is getting bored with their relationship. In an attempt to take Jack''s advice, Liz begins talking to Kenneth about her problems. Jack also finds himself caught up in one of Tracy''s schemes when Tracy tries to convince him to invest in his son''s theme restaurant in Times Square. Meanwhile, Jenna and Paul celebrate their six month anniversary.', 22, '2010-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 10, 'Christmas Attack Zone', 'Liz and Avery try to persuade Jack to disclose two secrets he''s been hiding from his mother, who visits for the holidays. Then, Liz tries to repair Jenna''s relationship with Paul; and Tracy tries to block his film''s release because it undermines his newly invented serious persona.', 22, '2010-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 11, 'Mrs. Donaghy', 'Budget cuts at the company impact the "TGS" gang. Elsewhere, Liz''s New Year''s resolution adds a potential snarl to Jack''s wedding; Jenna and Danny share a dressing room; and a health scare hits Tracy.', 22, '2011-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 12, 'Operation Righteous Cowboy Lightning', 'A reality TV series trails Tracy, which Liz tries to exploit for her own gain. Jack does his own exploiting: He attempts to make a fast buck off natural-disaster telethons. And Lutz sets out to increase his worth in the event of an apocalypse.', 22, '2011-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 13, '¡Qué Sorpresa!', 'As Jack tries to cozy up to the owner of Kabletown, Liz fakes being pregnant to help Avery gain advantage over a competitive colleague. Elsewhere, Tracy and Jenna clash when trying to share a gift from their new bosses.', 22, '2011-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 14, 'Double-Edged Sword', 'Jack and a very pregnant Avery take a romantic break in Canada. When Avery goes into labor, the power couple desperately scramble to not give birth to a Canadian. Meanwhile, Liz''s getaway with Carol gets grounded, literally, when their plane collects dust on the tarmac. And Tracy is an EGOT winner, but with that comes overwhelming demands.', 22, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 15, 'It''s Never Too Late for Now', 'Jenna tries to help a lovelorn Liz rebound from a broken relationship. Elsewhere, sleep deprivation impacts new father Jack, who begins to lose his business savvy and negotiating prowess; and Pete and Frank form a rock band.', 22, '2011-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 16, 'TGS Hates Women', 'Liz hires a new female writer after a blog declares "TGS" misogynistic. Meanwhile, Jack plots his takeover of Kabletown by zeroing in on his main competition--the CEO''s granddaughter.', 22, '2011-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 17, 'Queen of Jordan', 'Angie''s reality show visits "TGS", resulting in a red-faced situation for Jack, Jenna pining for attention, and Liz leading a scheme to lure Tracy back from Africa. Meanwhile, Frank reconnects with a lost love.', 22, '2011-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 18, 'Plan B', '"TGS" is forced into hiatus, spurring the show''s staffers to seek backup jobs. Meanwhile, Jack tries to rescue a cable network by forging an unlikely alliance with his archenemy, Devin Banks.', 22, '2011-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 19, 'I Heart Connecticut', 'As cancellation looms for "TGS", Liz snoops with Kenneth to find a missing Tracy. Meanwhile, Jack works his magic to ensure the financial success of Jenna''s newest endeavor; and an emasculated Pete organizes a manly contest for the writers and crew.', 22, '2011-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 20, '100 (1)', 'Chaos builds when bigwig Hank Hooper marks "TGS" for cancellation, yet Jack persuades him to let the staffers stage the show''s 100th episode.', 22, '2011-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 21, '100 (2)', 'With their show targeted for cancellation, the "TGS" crew desperately scramble to mount a top-notch production for their 100th episode. Meanwhile, Jack reconsiders a vital decision in his life, and Jenna mulls over motherhood.', 22, '2011-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 22, 'Everything Sunny All the Time Always', 'Liz tries to turn her personal life from drab to fab by revamping her dream apartment. Meanwhile, Avery is held hostage, and Tracy discovers that Kenneth, Dot Com and Grizz have forged a solid bond while he was away.', 22, '2011-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 5), 23, 'Respawn', 'The "TGS" crew anticipate their summer vacation. Liz lands in the Hamptons for some rest and relaxation, but she gets the summertime blues when Tracy moves in next door. Elsewhere, a lonely Jack latches onto Kenneth for company; and Jenna''s new job impacts her relationship with Paul.', 22, '2011-05-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 1, 'Dance Like Nobody''s Watching', 'Tracy becomes frustrated in his attempts to anger Liz. Jack questions the family value of the network''s new talent competition and Kenneth awaits the Rapture.', 22, '2012-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 2, 'Idiots Are People Two! (1)', 'An offensive rant by Tracy is leaked online. Jack disapproves of Liz''s new boyfriend, and Jenna enlists Kenneth in helping to replace her dressing room lights.', 22, '2012-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 3, 'Idiots Are People Three! (2)', 'Tracy challenges Liz by leading his own protest in defense of idiots everywhere. Jack faces off with Devin Banks yet again, and the Best Friends Gang is reunited when Kenneth and Jenna call for the help of Kelsey Grammer.', 22, '2012-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 4, 'The Ballad of Kenneth Parcell', 'Liz looks for a new best friend after discovering that Jenna has traded their friendship for fame. Tracy contemplates mortality as Dotcom and Grizz scramble to show him that life is still worth living. Meanwhile, Jack decides to end the page program in order to impress Hank Hooper.', 22, '2012-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 5, 'Today You Are a Man', 'Liz finds a secret weapon to help in her contract negotiations with Jack, Kenneth leaves his job because he feels under-appreciated, and Tracy and Jenna perform at their accountant''s ungrateful son''s Bar Mitzvah.', 22, '2012-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 6, 'Hey, Baby, What''s Wrong? (1)', 'Criss and Liz decide to celebrate Valentine''s Day, but they need to buy a dining room table first. Jack entertains his mother-in-law, Diana, as Jenna frantically looks to Pete to fill in last-minute as the producer of her first live performance on "America''s Kidz Got Singing." Back at the office, Tracy and Frank try to help Lutz find someone to spend Valentine''s with.', 22, '2012-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 7, 'Hey, Baby, What''s Wrong? (2)', 'Criss and Liz decide to celebrate Valentine''s Day, but they need to buy a dining room table first. Jack entertains his mother-in-law, Diana, as Jenna frantically looks to Pete to fill in last-minute as the producer of her first live performance on "America''s Kidz Got Singing." Back at the office, Tracy and Frank try to help Lutz find someone to spend Valentine''s with.', 22, '2012-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 8, 'The Tuxedo Begins', 'Fed up with New York City after being mugged, Jack sets out to protect the safety of the city''s elite by announcing his run for mayor. Meanwhile, Liz revels in sacrificing the good of the city to look out for her own interests, and Jenna and Paul are thrilled by the perversion of acting like a normal couple.', 22, '2012-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 9, 'Leap Day', 'Jack learns to appreciate Leap Day while Tracy takes the writers to a restaurant to spend an almost-expired gift card. Liz helps Jenna seduce an internet billionaire.', 22, '2012-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 10, 'Alexis Goodlooking and the Case of the Missing Whisky', 'In order to hide his relationship with Lynn, Frank convinces his mother that he is dating Liz. Tracy and Jenna team up to try to solve the case of Pete''s missing whisky. Meanwhile, Jack teaches Kenneth how to take down his first business nemesis.', 22, '2012-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 11, 'Standards and Practices', 'Jenna hatches a surprising new plan to get publicity, while Jack finds himself begrudgingly playing parent to his teenage nemesis, Kaylie Hooper. Liz rejects the new authority Kenneth has over “TGS” with his new job in Standards.', 22, '2012-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 12, 'St. Patrick''s Day', 'Jack feels unworthy of his latest award and attempts to redeem himself by taking on the writers in a strategic board game. Liz believes she''s cursed on St. Patrick''s Day when her ex-boyfriend Dennis shows up to derail her relationship with Criss. Meanwhile, Hazel struggles to keep the peace between Tracy and Jenna.', 22, '2012-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 13, 'Grandmentor', 'Liz struggles in her new role as mentor to Hazel. Kenneth has a difficult time letting go of his page duties and takes drastic measures to make sure Tracy is taken care of. Meanwhile, Jack and Jenna come up with a plan to get Avery back in the headlines.', 22, '2012-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 14, 'Kidnapped by Danger', 'Liz''s scripted version of Jack and Avery''s love story leaves Jack confused and frustrated by his feelings for Diana. Meanwhile, Jenna and Tracy attempt to beat Weird Al Yankovic at his own game, and Kenneth gets an unexpected new job at NBC.', 22, '2012-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 15, 'The Shower Principle', 'A curse strikes TGS. Liz dares to be different after realizing that the same things happen every year, and Jack vows to wow Hank Hooper.', 22, '2012-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 16, 'Nothing Left to Lose', 'Tracy regains his sense of smell and finds an unusual father figure in Liz, while the writers spark a prank war with Jenna.', 22, '2012-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 17, 'Meet the Woggels!', 'Jack''s mom upstages his ribbon-cutting ceremony. Meanwhile Jenna hooks up with a "rock star" and Tracy frets about his son heading to college.', 22, '2012-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 18, 'Murphy Brown Lied to Us', 'Jack sets Liz up on a blind date to show her what she''s missing in her relationship with Criss. Meanwhile at KableTown, Jack has to scramble when his plan to manufacture couches hits a speed bump. With Tracy''s help, Jenna orchestrates a public meltdown to get Paul''s attention.', 22, '2012-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 19, 'Live from Studio 6H', 'Kabletown chooses to stop funding live shows for TGS. While Liz and Jack embrace the change, Kenneth argues that live format should be kept intact, and he tries to convince the TGS staff to fight for their right to be live by taking them and our audience through a magical look back at the illustrious history of Studio 6H.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 20, 'Queen of Jordan II: Mystery of the Phantom Pooper', 'Angie brings "Queen of Jordan'''' back to TGS. News about Avery forces Jack to confront his feelings for her mother, and Liz finds herself in a feud.', 22, '2012-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 21, 'The Return of Avery Jessup', 'Avery finally returns home from her kidnapping ordeal in North Korea, yet Jack grows uncertain of her fidelity while she was away. Elsewhere, Criss is crossed due to Liz''s role as top wage earner, and Jenna seeks a sponsor for her approaching nuptials.', 22, '2012-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 6), 22, 'What Will Happen to the Gang Next Year?', 'Determined to prove his marriage has survived Avery''s kidnapping unscathed, Jack asks Liz to officiate their vow renewal. Meanwhile, Criss tries to convince Liz that he''s worth sticking around for. Tracy meets with Cornel West to discuss his influence as a black celebrity.', 22, '2012-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 1, 'The Beginning of the End', 'The "TGS" gang returning from hiatus, only to be shocked by Jack''s awful fall programming lineup. Meanwhile, bridezilla Jenna taps Liz to be her maid of honor, and Tracy is invited to a dinner party by Kenneth and Hazel.', 22, '2012-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 2, 'Governor Dunston', 'Jack and Liz find themselves at odds over political satire at "TGS". Criss and Liz make a surprising relationship breakthrough. Meanwhile, Jenna, discouraged by the disappointing sales of her summer dance hit, is thrilled to learn that Kenneth''s mother and her boyfriend still buy music.', 22, '2012-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 3, 'Stride of Pride', 'Liz works to prove to Tracy that women are funny while simultaneously attempting to head off a meltdown from Jenna after some negative publicity. Jack tries out an unconventional dating strategy.', 22, '2012-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 4, 'Unwindulax (1)', 'Liz and Jack find themselves battling to influence voters in the upcoming presidential election. Meanwhile, as Jenna goes to great lengths to please her new fan base, the writers seek out new ways to mess with her.', 22, '2012-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 5, 'There''s No I in America (2)', 'Realizing that Jenna could decide the Presidential election, Liz and Jack stage a debate to win her support and her followers. Kenneth turns to Tracy for advice on how to be an informed voter, while Pete tries to recreate the magic of the 2008 election.', 22, '2012-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 6, 'Aunt Phatso vs. Jack Donaghy', 'Tracy and Jack engage in a battle of wits after Tracy depicts Jack as a villain in his latest project. On Jack''s advice, Liz puts her own needs ahead of those of "TGS." Meanwhile, Jenna tries to shield Kenneth from Hazel''s manipulation but her own selfishness gets in the way.', 22, '2012-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 7, 'Mazel Tov, Dummies!', 'After an encounter with Dennis Duffy, Liz and Criss decide to take drastic measures to start a family. As Liz looks toward the future, Jack and Jenna evaluate their own self-worth, and Tracy laments a shocking medical diagnosis.', 22, '2012-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 8, 'My Whole Life Is Thunder', 'Jenna annoys Liz with her wedding envy, Jack devises a plan to avoid disappointing his visiting mother and Tracy attempts to cheer up Kenneth.', 22, '2012-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 9, 'Game Over', 'Jack asks Devin Banks to help him discredit Kaylie Hooper, Jack''s teenage nemesis and KableTown''s future CEO. Liz considers her options as she tries to become a mother. Tracy directs Octavia Spencer in his movie.', 22, '2013-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 10, 'Florida', 'When Jack persuades Liz to go to Florida with him, they make a shocking discovery about his mother. Jenna and Tracy assume responsibility for the show in Liz''s absence, resulting in disaster for Kenneth.', 22, '2013-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 11, 'A Goon''s Deed in a Weary World', 'As her new kids arrive, Liz scrambles to save TGS from cancellation. Jack finds a new NBC president.', 22, '2013-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 12, 'Hogcock!', 'Liz has trouble adjusting to being a stay-at-home mother. Jack takes stock of his life, and Tracy struggles to get on without Kenneth.', 22, '2013-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0496424')) AND numero_temporada = 7), 13, 'Last Lunch', 'Jenna prepares an emotional farewell song as the cast and crew reunite for one final "TGS".', 22, '2013-01-31');
