INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0758745', 'Friday Night Lights', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0718001'), 'SERIE', 'A drama that follows the lives of the Dillon Panthers, one of the nation''s best high school football teams, and their head coach Eric Taylor.', '2006-01-01', 'https://m.media-amazon.com/images/M/MV5BNzMxNzQwODItNDFiYy00YjFhLWJjMzUtYjc0Nzk5ZTI4ODA1XkEyXkFqcGc@._V1_.jpg');
