INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')), 1, 'Season 1', 'In the small town of Dillon, Texas, everyone comes together on Friday nights when the Dillon High Panthers play. But life is not a game; and the charismatic players, new coach Eric Taylor, and the passionate fans find that their biggest challenges and obstacles come off the field in the compelling day-to-day dramas of their tight-knit community.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 1, 'Pilot', 'A newcomer coach Eric Taylor finds himself helming a promising high school football team, the Dillon Panthers, that has a real chance to make it to the top.', 46, '2006-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 2, 'Eyes Wide Open', 'As the team pulls together and tries to help Matt get used to his new role as quarterback after Jason''s injury, Lyla offers her support to Tim.Jason learns about the extent of his injury, and Tami gets a job as the school guidance counselor.', 44, '2006-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 3, 'Wind Sprints', 'The situation in town begins to get ugly as Coach Taylor and his family is forced to endure heat from a difficult loss against the San Marco HS Rattlers.Tim and Tyra break up after he confronts her about Smash, and Lyla, after having an argument with Jason, vents her anger onto Tim.', 44, '2006-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 4, 'Who''s Your Daddy', 'As the Panthers prepare for a match against the Tigers, who are their biggest rival, Jason''s new roommate tries to help him understand the potential he has for recovery.Lyla tells Tim of her regrets about what happened between them, and Matt hits an all-time low.', 43, '2006-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 5, 'Git ''Er Done', 'The big game against the Tigers drawing closer, Coach Taylor must decide between Matt and the self-assured recruit Ray "Voodoo" Tatum for the starting quarterback. The feelings between Tim and Lyla grow stronger. Jason''s newly-found motivation strives him to begin the rehab.', 44, '2006-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 6, 'El Accidente', 'Ray Tatum faces the blame of his team mates after Panthers'' win in the game last week might be overturned.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 7, 'Homecoming', 'As the Panthers get ready to face the dominating Laribee Lions, the 2000 State Champ quarterback, Lucas Mize is set to join the team.Smash catches his chance to convince a college scout of his talents. A focused Tim quits drinking. Jason''s suspicions of Lyla and Tim''s affair grow. Tyra and Billy set up an after game homecoming party.', 43, '2006-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 8, 'Crossing the Line', 'Julie thinks about going on a date with Matt. A discouraged Smash turns to foul play to improve his on-pitch performance. Cheered by Lyla and Tim, Jason has his first quad rugby game. A dinner turns into a fight for Coach Taylor, Tami, Riggins and his brother.', 43, '2006-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 9, 'Full Hearts', 'Smash continues to go the extreme to improve his performance. Rumors begin to spread about Tim and Lyla''s relationship. Julie and Matt attempt to go out on a date but it is cursed from the beginning.The Panthers are in much anticipation for their upcoming game against the Gatling High.', 43, '2006-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 10, 'It''s Different for Girls', 'The cheerleaders prepare for Championship Classic. Lyla is picked on when people find out about her and Riggins. Coach Taylor tries to keep Matt and Julie apart. Jason goes home after being released from rehab.', 43, '2006-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 11, 'Nevermind', 'The Panthers are preparing for another game they can''t lose. Matt''s father comes back from Iraq but his mother''s condition is difficult to take in.Tami Taylor sees Tim Riggins regarding his grades. She believes he''s not doing his homework by himself and asks Landry to tutor him for his next oral exam. If he doesn''t pass, he won''t play in the football team.', 43, '2007-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 12, 'What to Do While You''re Waiting', 'The Panther''s fate is hung up on the result of a game between two other teams and there is nothing they can do about it.Meanwhile, there is tension at the Street''s house because of the lawsuit they introduced against Coach Taylor.Matt''s father has a hard time adjusting back to real life.', 43, '2007-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 13, 'Little Girl I Wanna Marry You', 'The Panthers have only one more game to win in order to qualify for the play-offs. Smash''s mother discovers something that could end his football dreams.', 43, '2007-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 14, 'Upping the Ante', 'The Panthers prepare for their first playoff game.Coach Taylor gets distracted as he has to come up with a solution to Smash''s use of drugs. Tyra and Julie befriend while Riggins bonds with his alienated father.Buddy learns about Jason and Lyla''s engagement.', 43, '2007-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 15, 'Blinders', 'The Panthers savor their crucial playoff-win-until race issues emerge and sorely test their bond after Mac makes racial statements.Tami frowns upon Julie''s newfound friendship with Tyra. The girls play a powder-puff football game.', 43, '2007-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 16, 'Black Eyes & Broken Hearts', 'Due to racial comments from Coach Mac, the black players on the team refuse to play unless he is sacked.Julie is sucked deeper into the vortex as her friendship with Tyra develops. Matt tries to win Julie back.', 43, '2007-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 17, 'I Think We Should Have Sex', 'After Julie reveals to Matt that she wants to have sex with him, Matt feels the need to put together something special. Tim clashes with his father.The Panthers are into the next round of the playoffs and looking solid.', 45, '2007-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 18, 'Extended Families', 'Lyla makes a surprise visit to the quad rugby camp where Jason is playing at, but she doesn''t find the comfort she came looking for.Buddy Garrity''s affair with Tyra''s mother comes out. Consequently, Buddy decides to move in with the Taylors.Smash becomes suspicious about Waverly when she goes for a midnight swim with him.', 43, '2007-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 19, 'Ch-Ch-Ch-Ch-Changes', 'With TMU trying to recruit Coach Taylor, Julie insists that she will not be moved away from Matt and Dillon. The quad rugby recruiters in Austin deliver some bad news to Jason. Riggins becomes friends with a single mother and her son.', 43, '2007-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 20, 'Mud Bowl', 'An chemical spill near Dillon High School forces Coach Taylor and the Panthers to seek another facility in which to play the crucial State Semi-Final game.', 43, '2007-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 21, 'Best Laid Plans', 'Coach Taylor buckles under the pressure from Texas Methodist University. The news of his decision is not taken lightly by his family.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 1), 22, 'State', 'The rumors about Coach Taylor leaving the team at the end of the season get a boost when an inside source decides to speak up.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')), 2, 'Season 2', 'In season two, Coach Taylor returns from his new position to witness his daughter''s birth — only to face pressure from a family and town that feel he''s abandoned them. Tami is disheartened by the distance between herself and her teenage daughter. Tyra and Landry develop a secret bond after a deadly confrontation. Tensions between Smash and Saracen explode as the team falls apart under the rigid, cold leadership of Coach MacGregor. Lyla discovers faith and tries to convert Riggins, whose feelings for her only get in the way.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 1, 'Last Days of Summer', 'Changes in the team force Dillon Panthers to work harder than ever before to achieve the same level of success they had last season. Losing Coach Taylor to TMU might prove to be their biggest setback. Tyra gets a shock visitor. Matt and Landry struggle with their everyday life, as it is not what they expected.', 45, '2007-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 2, 'Bad Ideas', 'So many things have changed at Dillon High and the first day of school is the real test. Matt stands by as his world comes crashing down, while Landry still copes to make sense of his. All eyes seem to be focusing on Smash, while Tami tries to adjust to having a teenager and a newborn.', 43, '2007-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 3, 'Are You Ready for Friday Night?', 'Matt and Smash have a hard time listening to their coach as they prepare for their first game of the new season. Coach Taylor heads back to Dillon to check on his family and finds out just what is happening to the Panthers since he''s left.', 43, '2007-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 4, 'Backfire', 'Tim and Jason go to Mexico as Street hopes to explore experimental surgery. Riggins, who is worried about Street, turns to Lyla Garrity, who''s busy helping a newcomer acclimate to Dillon. Meanwhile, Coach Taylor decides on a big career move that will change his life. A development in a police search deeply affects the lives of Tyra and Landry.', 43, '2007-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 5, 'Let''s Get It On', 'Coach Taylor returns to Dillon, but it is not an easy homecoming; the team must deal with conflict between Saracen and Smash; Riggins turns to Lyla for help in changing Street''s mind about surgery.', 44, '2007-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 6, 'How Did I Get Here?', 'Key evidence comes in implicating Landry; when Tami''s sister visits to help her with the baby, she stirs things up in the house; Riggins must prove to coach Taylor that he wants to be a part of the team.', 44, '2007-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 7, 'Pantherama!', 'As college football scouts approach Smash, he must make a life-changing decision. Coach Taylor has set his sights on a potential addition to the team. Tami appoints Lyla and Tyra to be in charge of this year''s Pantherama. Matt is living his dream, with his new cheerleader girlfriend by his side, but yet he is drawn to the live-in nurse. Julie turns her jealousy into a twisted relationship.', 43, '2007-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 8, 'Seeing Other People', 'As Smash sets out on his first recruitment trip, Saracen asks his cheerleader girlfriend for an open relationship.', 43, '2007-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 9, 'The Confession', 'Landry admits to the murder of Tyra’s assaulter but the struggle with his conscience continues. Meanwhile Jason Street is set up with an online dating service by Herc. The Taylors get ready for baby Gracie’s christening, while tensions increase between Tami and Julie.', 43, '2007-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 10, 'There Goes the Neighborhood', 'Dillon County is hit by a tornado with Laribee High School affected by the damage forcing both rivals to share Dillon''s resources. Julie and Tami adjust to Tim Riggins'' living in their house, and tension builds between Landry and Tyra.', 43, '2008-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 11, 'Jumping the Gun', 'Brian "Smash" Williams takes heat from the major colleges that want a verbal commitment to their program. Meanwhile tension is still high between Coach Taylor and Tim Riggins regarding the situation with Julie. Tim doesn''t know where to turn. And all eyes are on Coach Taylor as he prepares the Panthers to play Laribee High School in the season''s biggest game.', 43, '2008-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 12, 'Who Do You Think You Are?', 'Tami and Coach Taylor look into day care for Gracie, but find themselves having a tough time letting go. Meanwhile, Lyla starts working as a deejay on a Christian radio station and, despite being ridiculed by Tim Riggins, she is able to strike a chord with him. Elsewhere, Matt Saracen discovers that he is actually in love with his grandma''s at-home nurse, while Brian "Smash" Williams learns that those close to him may not be ready for interracial dating.', 43, '2008-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 13, 'Humble Pie', 'Coach Taylor hires Tami as the girls volleyball coach and enlists the help of Tyra. Smash has a confrontation at a movie theater and is faced with a dilemma.', 43, '2008-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 14, 'Leave No One Behind', 'Matt Saracen reaches at his lowest point. Meanwhile, Tami Taylor’s relationship continues to blossom with Tyra. Julie  becomes envious. Landry has an admirer. Elsewhere, Smash seeks advice from Coach Taylor.', 43, '2008-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 2), 15, 'May the Best Man Win', 'Smash''s hunt for a college football scholarship turns into something completely different. Tami comes across her high school boyfriend, whose job as a real estate magnate has brought him to Dillon, making Coach Taylor jealous.
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')), 3, 'Season 3', 'The third season of the American serial drama television series Friday Night Lights began airing in the United States and Canada on October 1, 2008. It was the first season to be aired on DirecTV''s The 101 Network. The 13-episode season concluded on The 101 Network on January 14, 2009 and then began its run on NBC two nights later on January 16, 2009. The show was renewed for two more seasons in March 2009, with both seasons airing in the same format as season 3, containing 13 episodes each.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 1, 'I Knew You When', 'In the third-season opener, Eric fights to keep his job and helps Smash rebound. Elsewhere, Tami faces new challenges as principal; Tyra frets over college; Billy proposes; and tension escalates between Lyla and Riggins.', 47, '2008-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 2, 'Tami Knows Best', 'Tami becomes angry by Tyra''s actions. In an effort to help his grandma, Matt stumbles upon his estranged mother. Coach Taylor tries his best to encourage Smash as he tries to make the college tryouts.', 43, '2008-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 3, 'How the Other Half Lives', 'Coach worries and fears for his job as Tami befriends Katie McCoy. The pressure is on Matt as everyone''s hopes turn to the new quarterback. Matt''s friendly with Julie. Billy drags Tim into a risky scheme to get them out of debt. Lyla cautions Tim.', 43, '2008-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 4, 'Hello, Goodbye', 'Tami embarrasses herself with the superintendent. Tyra breaks with Landry to take up with Cash, the new bad boy in town. Julie advises Matt who is upset with his mother who has come to help with grandma. Smash has an emotional goodbye with Coach.', 43, '2008-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 5, 'Every Rose Has Its Thorn', 'Matt grapples with his mother, his emotions and Coach Taylor as McCoy garners more attention. Tami tangles with Tyra about Julie and Tyra''s interest in Cash. Tyra experiences Cash''s darker side. Erin disappoints Jason.', 43, '2008-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 6, 'It Ain''t Easy Being J.D. McCoy', 'Coach is furious with Tim and the team for a freshman hazing. J.D. wins the respect of the town and team. A late night swim at the lake turns into more for Julie and Matt. Tyra is shocked when a woman shows up claiming Cash owes her child support.', 43, '2008-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 7, 'Keeping Up Appearances', 'Eric and Tami try to calm Jamarca''s angry parents; Billy helps Tim pursue a scholarship; and Jason, Herc and the Riggins brothers receive good news.', 43, '2008-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 8, 'New York, New York', 'Tim is worried when Jason talks about leaving Dillon. Money troubles cause a riff between Tami and Eric. Tyra leans on Cash when things get tough, while Julie talks to her dad about Matt''s idea.', 43, '2008-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 9, 'Game of the Week', 'Tim returns to find both good and bad surprises. Coach has to change his plans and reluctantly supports Tami when she feels obligated to help Tyra out of a jam. Saracen has second thoughts and clashes with Shelby. Lyla and Mindy team up.', 43, '2008-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 10, 'The Giving Tree', 'It becomes clear JD has no interest in his father''s advice regarding Madison. Lyla turns to Riggins when Buddy reveals a secret. Coach is emotionally challenged both on and off the field. Tyra has a plan to repair her relationship with Landry.', 43, '2008-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 11, 'A Hard Rain''s Gonna Fall', 'Tyra is desperate and once again turns to Landry. Coach and Tami learn of a change that could dismantle the Panthers team. Tim sees another side of Lyla. Matt flips out when Grandma suffers an accident. Tensions escalate between JD and Joe.', 43, '2008-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 12, 'Underdogs', 'J.D.''s dad has to deal with child protective services after his fight with J.D. Tyra realizes that life isn''t fair and that she needs to do whatever is necessary to get in to college. Matt and Tim prepare for the last game of their high school career: The Texas State Championship.', 43, '2009-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 3), 13, 'Tomorrow Blues', 'Five months later, Coach Taylor''s contract is up for review on Billy and Mindy''s wedding day. Tyra grows anxious about her waitlist status. Matt leaves Grandma Saracen and Julie behind to attend college. Tim and Lyla question their future together.', 45, '2009-01-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')), 4, 'Season 4', 'A redistricting plan leaves Dillon divided in season 4, and Coach Taylor is faced with the daunting task of building an East Dillon Lions football team from scratch. Tensions follow him off the field as he and Tami find themselves increasingly at odds with one another and the roles the redistricting has forced upon them.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 1, 'East of Dillon', 'Coach Taylor wonders how low his fortunes can sink as he struggles to pull the East Dillon Lions together while Tami navigates the new politics at West Dillon. Meanwhile, Matt gets a taste of life as a townie and Tim is inspired by a college lecture on "the hero''s journey."', 43, '2009-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 2, 'After the Fall', 'A controversy at West Dillon puts star player Luke Cafferty on the Lions'' roster. Elsewhere, Coach tries to reenergize his demoralized team and Tami takes an unpopular stand. Meanwhile, Matt meets an uncouth local artist and Tim finds a new living situation in an unexpected place.', 44, '2009-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 3, 'In the Skin of a Lion', 'Coach betrays Tami''s trust over a financial decision. tensions between Vince and Luke threaten the team''s chances on the field. Tim helps Coach condition his players. Julie doesn''t want to go to church.', 43, '2009-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 4, 'A Sort of Homecoming', 'Homecoming at the newly-reopened school prompts Coach to investigate East Dillon''s history. Tami feels the wrath of the boosters. Landry and Vince both like Jess. Julie accompanies Devin to a gay bar. Matt and Tim go hunting.', 43, '2009-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 5, 'The Son', 'Julie, Landry, Coach, and Tami rally around Matt in a time of crisis; Vince endangers his rising star as a football player by engaging in criminal activity in order to support his family; Becky and Tim grow closer.', 45, '2009-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 6, 'Stay', 'Coach searches for a strategy to shut down their toughest opponent yet. Tim reconnects with Lyla. Vince discovers he has a gift for car theft. Julie and Matt attend a concert in Austin and reach a critical juncture in their relationship.', 43, '2009-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 7, 'In the Bag', 'Despite some doubt, Coach makes Vince quarterback. Tami struggles to comfort Julie who''s grieving over Matt''s sudden departure. Tim has a confrontation with Becky''s dad. Luke is badly injured. Landry makes a play for Jess.', 43, '2009-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 8, 'Toilet Bowl', 'Eric realizes that East Dillon''s problems aren''t only on the field; Jess tries to choose between Vince and Landry; Luke''s injury takes a toll on him; and Riggins makes a decision that could backfire.', 43, '2010-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 9, 'The Lights in Carroll Park', 'Coach talks tough to shady characters when trying to clean up a park ridden with drugs and gang violence. Becky discovers she''s pregnant. Jess''s relationship with Landry is heating up. Julie makes a new friend.', 43, '2010-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 10, 'I Can''t', 'Riggins puts Tami in a tough spot; Julie asks a friend to dinner; Vince’s mom has a health crisis; Luke’s parents look for ways to help him; and Eric is urged to change his coaching style.', 43, '2010-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 11, 'Injury List', 'The team can''t focus on their next game. Tami gets involved in a controversy. Vince wants to end his deal with Kennard. Julie gets an unexpected phone call from Matt.', 43, '2010-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 12, 'Laboring', 'Tensions in town run high as the Panthers/Lions game approaches; Coach tells Luke he won''t be playing; Tami attempts to placate her detractors; developments both good and bad shake up the Riggins boys; Vince teams up with Kennard to seek revenge.', 43, '2010-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 4), 13, 'Thanksgiving', 'The Taylors host Thanksgiving dinner; Coach tells Vince he has to be more selfish; Tami must make an apology; Julie and Landry are surprised by a visitor from their past; Tim makes a difficult decision; East Dillon rallies around the Lions.', 45, '2010-02-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')), 5, 'Season 5', 'In the fifth and final season, everyone is playing for keeps. The East Dillon Lions are back and competing at a top caliber level, but that only means the town’s expectations are running higher than ever. When a controversy erupts that takes the whole town by storm, Coach Taylor feels he’s losing his grip on the team. Luke faces pressure at the prospect of becoming QB-1, Billy learns some surprising news from Mindy, Becky starts a surprising new job and Tami is caught off guard by Julie’s plans. Will the Lions go state? Will the coach leave the team? That may be the least of the town’s worries in the powerful series finale that culminates in a true championship ending.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 1, 'Expectations', 'Coach tempers high expectations for East Dillon''s impending season; Vince and Luke work to recruit a new player for the Lions'' squad; Dillon bids farewell to two alumni as they prepare to leave for college.', 43, '2010-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 2, 'On the Outside Looking In', 'Eric realizes that the Lions'' performance in the first game of the season hasn''t satisfied everyone; Vince receives unexpected benefits from his status as a football player; and Luke''s aggression on the field has repercussions.', 43, '2010-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 3, 'The Right Hand of the Father', 'Someone from Vince''s past resurfaces. Julie connects with a faculty member. Eric tries to instill discipline in the team. Buddy is troubled after learning something about his son.', 43, '2010-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 4, 'Keep Looking', 'Coach is forced to play mediator as tensions erupt in the locker room. Luke gets recruited. Buddy deals with the trials and tribulations of fatherhood. Tami deals with a troubled student. The Lions welcome a new player.', 43, '2010-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 5, 'Kingdom', 'Coach discusses recruitment regulations. The Lions take a road trip. East Dillon''s four stars make a pact. Julie''s relationship becomes more complicated.', 43, '2010-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 6, 'Swerve', 'A popular magazine hails Coach as the "Kingmaker." Vince''s past catches up to him. Luke reacts to the truth. A suspicious accident delays Julie''s return to college.', 43, '2010-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 7, 'Perfect Record', 'Rivalry week stirs up controversy. Vince is caught in the middle between Coach and Ornette. Billy takes Luke under his wing.', 43, '2010-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 8, 'Fracture', 'Coach fears he''s beginning to lose his grip on the team. Tami worries that one of her students is being neglected. Vince alienates his teammates. Becky enters a beauty pageant.', 43, '2011-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 9, 'Gut Check', 'Coach threatens to suspend Vince. Luke faces pressure. Billy learns some surprising news from Mindy. Becky starts a surprising new job.', 43, '2011-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 10, 'Don''t Go', 'An elite college football program attempts to lure Coach away from East Dillon. Vince vows to earn his spot back. Friends and family speak at Tim''s parole hearing. East Dillon holds a Fall Sports Banquet.', 43, '2011-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 11, 'The March', 'Coach Taylor feels threatened as East Dillon faces serious budget cuts; Tami is flown to Pennsylvania for the opportunity of a lifetime; The Lions begin their quest for state; Vince becomes the man of the house again.', 43, '2011-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 12, 'Texas Whatever', 'Coach Taylor is offered a deal he can’t refuse; Tim assesses his future plans when an old flame returns to Dillon; The fate of East Dillon’s football program is decided.', 43, '2011-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0758745')) AND numero_temporada = 5), 13, 'Always', 'While the Lions prepare for the state championship game, the Taylors face several decisions that could change their lives forever.', 62, '2011-02-09');
