INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0758790', 'The Tudors', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1012772'), 'SERIE', 'Epic series reveals the scandalous life of a young king whose affairs and obsession with producing a male heir changed marriage, the church, and the world.', '2007-01-01', 'https://m.media-amazon.com/images/M/MV5BYzQ4ZDhmZDEtNDA5YS00NzJlLWE3YjgtODEzZmQ2ZTFlMTYwXkEyXkFqcGc@._V1_.jpg');
