INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0773262', 'Dexter', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0001093'), 'SERIE', 'He''s smart. He''s lovable. He''s Dexter Morgan, America''s favorite serial killer, who spends his days solving crimes and his nights committing them.', '2006-01-01', 'https://m.media-amazon.com/images/M/MV5BNTE5ZGI2N2UtYmFiMi00ZGIxLWI1ZTMtYWJkZDYxNDZiOTQwXkEyXkFqcGc@._V1_.jpg');
