INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')), 1, 'Season 1', 'The first season of the fantasy series set in the quirky and seemingly perfect small town of Eureka, where the hidden work of America''s brightest scientists can lead to innovation or utter chaos.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 1, 'Pilot', 'An accident leads a U.S. Marshal and a teenage girl to a peculiar town populated by scientists and their families where 10-year-old boys are in 11th grade, the local diner doesn''t believe in menus, and E=MC² was just the beginning. Just as the Marshal starts to get settled into the swing of things, a local scientist develops a bomb that seems to appear anywhere and eats all the matter around it.', 85, '2006-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 2, 'Many Happy Returns', 'The citizens of Eureka attend the funeral of Susan Perkins, only to find out that she is in fact alive. Meanwhile the Sheriff moves into an underground bunker that is actually a ''smart house'' controlled by a computer dubbed ''S.A.R.A.H., and begins to investigate a ''ghost'' that has been appearing in town.', 43, '2006-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 3, 'Before I Forget', 'Something starts to steal the townspeople''s memory...', 44, '2006-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 4, 'Alienated', 'After hosting a movie party, Spencer is found the next day in the middle of a crop circle, claiming he was abducted by aliens; and then other people who attended the party start to go missing as well. Elsewhere, the legislator responsible for Eureka''s funding visits the town, and gets dragged into a Sector 5 experiment...', 42, '2006-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 5, 'Invincible', 'An unpredictable researcher accidentally unleashes a dangerous artifact which was previously hidden by Nathan Stark.', 44, '2006-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 6, 'Dr. Nobel', 'A sleeping weapons system is accidentally awakened by Fargo and Spencer. Henry tries to avert the pending catastrophe with the help of a retired, nonsensical scientist.', 43, '2006-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 7, 'Blink', 'Carter investigates an unusual car accident. Meanwhile, Stark, under the stress of completing a project on time, pressures two research teams to produce results. ', 42, '2006-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 8, 'Right as Raynes', 'A former resident returns to Eureka and creates mayhem which threatens Global Dynamics, prompting Stark to take action.', 44, '2006-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 9, 'Primal', 'Taggart achieves a medical breakthrough while Fargo invents a device that bridges the divide between computers and human brains.', 41, '2006-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 10, 'Purple Haze', 'Strange behavior exhibited by the townspeople is investigated by Carter,who has to solve the mystery before Stark makes a decision that could affect the world.', 44, '2006-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 11, 'H.O.U.S.E. Rules', 'A bad day in the lab forces Carter to rethink his decision to live in Eureka, prompting an intervention from S.A.R.A.H. (the self Activated Residential Automated Habitat.', 44, '2006-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 1), 12, 'Once in a Lifetime', 'Ambition trumps common sense when Stark is given a chance to try out the Top-secret artifact. Once it''s tested, Eureka warps into the future and ends up in 2010, where the town is different.', 44, '2006-10-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')), 2, 'Season 2', 'The second season of the fantasy series set in the quirky and seemingly perfect small town of Eureka, where the hidden work of America''s brightest scientists can lead to innovation or utter chaos.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 1, 'Phoenix Rising', 'Taggart''s theory is that solar flares caused by the eclipse, or the ''Phoenix Effect'', are to blame when people start to spontaneously combust.  When Carter discovers that a blast of radiation from the artifact had penetrated the wall of the chamber and is actually to blame for the spontaneous combustion, it becomes a race against time to save the other two people exposed - Nathan and Kevin!', 44, '2007-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 2, 'Try, Try Again', 'Fargo accidentally triggers a prototype for a personal force field, which goes out of control, forcing Carter to enlist Stark''s help.', 44, '2007-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 3, 'Unpredictable', 'Dr. Whiticus creates an incredible "weather machine" intended to reverse the effects of global warming which instead stirs unexpected results.', 44, '2007-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 4, 'Games People Play', 'Carter suffers a blow to the head, and after arguing with Zoe, he suddenly finds himself in a parallel Eureka, where the residents seem to be mysteriously vanishing.', 43, '2007-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 5, 'Duck, Duck Goose', 'Falling space debris threatens Eureka residents and Carter turns to high school science fair participants to solve the problem. Specifically, he taps a student science project created to harness the sun''s energy. Also, Zoe gets an eco-friendly automobile.', 42, '2007-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 6, 'Noche de Sueños', 'One of the Global Dynamics tanker trucks spills, potentially causing a change in everyone''s sleep habits... In the course of the episode, we come to learn that Global Dynamics has developed a technology that enables them to distill six months of the town waste and by-products into one truck, an amount that would normally fill Lake Erie.', 43, '2007-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 7, 'Family Reunion', 'Fargo''s grandfather awakens after 50 years in cryogenic suspension and accuses his rival of putting him there and stealing his work.', 44, '2007-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 8, 'E=MC...?', 'As an experiment that will recreate the first moment of the origins of the universe, the Big Bang, goes terribly awry, the town’s geniuses turn into morons, leaving the fate of Eureka in the hand of Jack Carter and an antisocial young ubergenius.', 44, '2007-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 9, 'Sight Unseen', 'An abandoned research project on invisibility returns to haunt Eureka. Carter and Zoé become tangled in a web of strange occurrences that lead to Carter’s disappearance and the possibility that he might never reappear.', 44, '2007-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 10, 'God is in the Details', 'Sudden muteness, human bioluminescence and faucets running blood cause many of Eureka’s citizens to believe that they are the victims of a biblical plague.', 44, '2007-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 11, 'Maneater', 'Sheriff Jack Carter becomes absolutely irresistible to every woman in Eureka. But if he doesn''t get his mojo under control, they might just eat him alive.', 43, '2007-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 12, 'All That Glitters', 'Beverly Barlow returns to town just as a parasitic bacterium threatens to destroy Eureka, by turning everything to gold and then into rust --- people included.', 44, '2007-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 2), 13, 'A Night at Global Dynamics', 'Nathan Stark and Jack Carter must put aside their rivalry to stop a deadly bacteria from destroying the town and killing Allison’s son. But can Carter ignore Stark’s crimes, as well?', 43, '2007-10-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')), 3, 'Season 3', 'The third season of the fantasy series set in the quirky and seemingly perfect small town of Eureka, where the hidden work of America''s brightest scientists can lead to innovation or utter chaos.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 1, 'Bad to the Drone', 'The search is on for an escaped drone as Eva Thorne arrives to assist the cleanup of damages which Global Dynamics has caused.', 44, '2008-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 2, 'What About Bob?', 'Carter and Allison investigate when a scientist mysteriously disappears from a sealed biosphere. Meanwhile, the "Fixer" tries to make Eureka''s efforts more profitable.', 44, '2008-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 3, 'Best in Faux', 'Eureka''s annual dog show is underway and is like none other. Meanwhile, Sheriff Carter experiences an earthquake; Zoe debates quitting the accelerated physics program; and Allison starts the process of fitting her wedding dress.', 44, '2008-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 4, 'I Do Over', 'It''s Allison and Stark''s wedding day and Carter finds himself reliving it over and over. Meanwhile, Carter''s sister, Lexi, visits the town.', 44, '2008-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 5, 'Show Me the Mummy', 'A search for a mummy ensues after a famed archaeologist opens the tomb of an Egyptian queen at Global Dynamics.', 44, '2008-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 6, 'Phased and Confused', 'Carter''s job is made more difficult when a super hero emerges. Meanwhile, Zoe and her friends are imperiled when Thorne makes a subterranean search beneath Eureka.', 43, '2008-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 7, 'Here Come the Suns', 'The Eureka mayoral race is overshadowed by the sudden arrival of a second sun, forcing Carter, Allison and Zane to investigate it more closely.', 43, '2008-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 8, 'From Fear to Eternity', 'Trust issues are produced by a scientific find, along with sinister results. Zoe''s life is in jeopardy, and Eva Thorne knows what has caused the predicament.', 44, '2008-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 9, 'Welcome Back Carter', 'Carter interviews for a job with the Department of Homeland Security, after being terminated as the sheriff. Deputy Lupo decides to resign after discovering that a very personable robot is the new sheriff.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 10, 'Your Face Or Mine', 'Jo displays atypical behavior after a DNA scan malfunctions, unfortunately it''s while she''s interim sheriff because Carter is undergoing a 48-hour DOD recertification test.', 44, '2009-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 11, 'Insane In The P-Brane', 'Dr. Tess Fontana reopens Section 5, causing objects to become ambulatory , possibly due to poltergeists.', 44, '2009-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 12, 'It''s Not Easy Being Green', 'Carter finds himself chasing down creation of blob-ical like proportions when a series of escalating pranks turn deadly. Elsewhere, long-term rivals from Area 51 come to Eureka for a bowling tournament.', 44, '2009-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 13, 'If You Build It...', 'Eureka''s teenagers who appear to have been manipulated while asleep, gathered in a field where they assembled a strange structure comprised of scrap metal and electronics.', 44, '2009-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 14, 'Ship Happens', 'Henry''s ship returns causing Carter to fear it maybe linked to the town''s deadly electrical anomalies.', 44, '2009-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 15, 'Shower the People', 'Allison''s baby shower fetches her a load of eco-friendly gifts and the discovery of a drowned scientist in a location where drowning is impossible.', 44, '2009-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 16, 'You Don''t Know Jack', 'Global Dynamics sonic cleaning coincides with a phenomenon in which the citizens of Eureka develop a form of amnesia. Meanwhile, Allison goes into labor.', 43, '2009-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 17, 'Have an Ice Day', 'The first day on the job as temporary head of Global Dynamics proves daunting for Tess when a new Ice Age comes to Eureka; and a familiar face returns in the process.', 44, '2009-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 3), 18, 'What Goes Around Comes Around', 'Tess has a job offer from Australia, Zoe is prepared to leave for Harvard and Carter has a magnetic disturbance above Eureka to contend with, in the third season finale.', 44, '2009-09-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')), 4, 'Season 4', 'The fourth season of the fantasy series set in the quirky and seemingly perfect small town of Eureka, where the hidden work of America''s brightest scientists can lead to innovation or utter chaos.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 1, 'Founder''s Day', 'It''s Founder''s Day in Eureka and everyone is in the spirit of the celebration until Jack, Allison, Henry, Jo and Fargo are transported back to 1947 where they meet some familiar faces along the way. Will they be able to get back to 2010 or will they be stuck forever in 1947 where Eureka is not a town, but an Army base.', 44, '2010-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 2, 'A New World', 'When the 5 get back to their time, things are changed everywhere. As Henry tries to fix the machine that transported them in the first place, Dr. Grant is making himself as comfortable as he can. Jack is still trying to wrap his mind around the fact that he asked Tess something that she says yes to and the fact that the group''s positions changed. As one thing leads to another, a twist happens and things get a little dicey.', 44, '2010-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 3, 'All the Rage', 'When a prototype sets everyone into bad temper mode, the issue escalates and gets worse beyond the control of what Jack can handle. As Jack and Allison and Tess are the only sane people at Global Dynamics they have to devise a plan that will make everything calm and happy again. Meanwhile, Henry is helping Dr. Grant re-build the bridge that got them back to the new world except everything they touch disappears.', 44, '2010-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 4, 'The Story of O2', 'It''s space week in Eureka, and everyone is gearing up for the rocket race - except for Carter. General Mansfield is in town for the big Race to the Moon, and is debriefed on a new oxygen-generating fluid designed, called TAP, for colonizing Mars. When the question about someone using TAP to fuel their rocket, the whole town of Eureka is in danger and it is up to Kevin to save the day this time. Will he do it, or will Jack come back to see charred remains of his friends?', 44, '2010-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 5, 'Crossing Over', 'Claudia Donovan visits Eureka to see if Fargo''s promises of wondrous devices are true, but she finds herself in the middle of a mystery suitable for Warehouse 13 when objects begin to appear randomly around the town and GD, and it must be solved before there are deadly consequences.', 44, '2010-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 6, 'Momstrosity', 'When Sara gives Andy a (as Zane calls it ) an EMO download to give him emotion, she inadvertently affects all Level 6 AIs. Including Tiny. She escapes while being transported to NASA and  is on the loose. Meanwhile, Jack takes Kevin camping with Fargo and Grant and Jack is not happy that Grant is there. They argue on who is with Allison and who is not and they are interrupted by Tiny who has an attachment to a certain object of Kevin''s.', 44, '2010-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 7, 'Stoned', 'Love is in the air as Carter gets fed up with Grant''s pursuit of Allison, Zoe conceals her love and Henry courts Grace. But all the emotions may have to be put on simmer when people in town start turning to stone.', 43, '2010-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 8, 'The Ex-Files', 'Eureka''s citizens face the return of people from the past; Global Dynamics tests a new device.', 44, '2010-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 9, 'I''ll Be Seeing You', 'When Grant and Carter become stranded, they must race back in time to save Eureka.', 44, '2010-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 10, 'O Little Town', 'Carter can''t get into the Christmas spirit especially with the town surrounded by a force-field. Fargo organizes the GD holiday party, and Allison is full of holiday cheer.', 44, '2010-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 11, 'Lift Off', 'Zane pesters Jo for details she does not want to reveal. Carter problem-solves at Andy and S.A.R.A.H.''s wedding. Elsewhere, Zane''s actions make him and Fargo unexpectedly airborne.', 44, '2011-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 12, 'Reprise', 'Carter''s duties expand to babysitting when Allison attends a medical conference, and Fargo finds his groove when a certain song is played. Meanwhile, a rocket scientist appears at Café Diem.', 44, '2011-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 13, 'Glimpse', 'Jo receives a technical boost to her crime-fighting ability with lenses that predict security breaches. Allison''s headaches won''t go away so Carter plans a vacation. Fargo, meanwhile, deals with an onslaught of volunteers when he announces a space mission with room for civilians.', 44, '2011-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 14, 'Up in the Air', 'Jack deals with a bank robbery which may relate to the sudden gravity issues besetting the citizens of Eureka. Meanwhile, Fargo''s rivalry with Isaac Parrish is boosted when he learns Holly and Parrish went on a date.', 44, '2011-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 15, 'Omega Girls', 'When Zoe comes home for a visit, Jo faces an angry woman who doesn''t accept her fumbling explanations about Zane. This all fades to background noise, however, when they find everyone in Eureka unconscious and must find a way to work together so they can revive the town and beat Beverly before she gets hold of valuable data.', 44, '2011-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 16, 'Of Mites and Men', 'When mites threaten to take down Global Dynamics, Jack is called into action since Jo is in the middle of training. Allison is struggling with the fact that everyone things that her brain doesn''t work and she is determined to prove that she is back in action again. ', 44, '2011-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 17, 'Clash of the Titans', 'The Eureka atmosphere becomes toxic when Department of Defense auditor comes to assess the team''s relationships.', 44, '2011-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 18, 'This One Time at Space Camp...', 'The Astraeus candidates go through their final interviews while Carter and Allison appeal their relationship audit.', 44, '2011-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 19, 'One Small Step...', 'When an explosion in the Astraeus lab accidentally sends Andy to Titan the team must devise a plan to save him before it''s too late! Eureka', 44, '2011-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 20, 'One Giant Leap...', 'In the season finale - It''s chaos in Eureka when an energy beam rips through main street but the Astraeus launch must go on...with or without Eureka intact.', 44, '2011-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 4), 21, 'Do You See What I See', 'The quaint town of geniuses is transformed into animated versions of themselves. Sheriff Carter and Allison Blake are secretly planning the perfect holiday surprise for their kids. But a mysterious kaleidoscopic wave of color crashes over Eureka, leaving the entire town and its inhabitants animated.', 43, '2011-12-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')), 5, 'Season 5', 'The fifth and final season of the fantasy series set in the quirky and seemingly perfect small town of Eureka, where the hidden work of America''s brightest scientists can lead to innovation or utter chaos.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 1, 'Lost', 'The Astraeus crew returns to Eureka four years later and must adapt to a myriad of changes, including a more oppressive version of Deputy Andy.', 43, '2012-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 2, 'The Real Thing', 'The town huddles in a last attempt to locate the vanished Astraeus before it''s too late!', 43, '2012-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 3, 'Force Quit', 'Beverly Barlowe resurfaces in Eureka seeking Carter''s help to free the Astraeus crew, and the rescue plan lands Carter in the crew''s virtual world. ', 43, '2012-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 4, 'Friendly Fire', 'When a smart fire experiment gets out of control, Carter and team discover that the Astraeus victims may be the cause.', 43, '2012-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 5, 'Jack of All Trades', 'The crew moves forward after an ordeal and Warren''s visit adds to the pressure.', 43, '2012-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 6, 'Worst Case Scenario', 'Henry conducts a preparedness drill that winds up a disaster and Fargo faces a hard reality.', 43, '2012-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 7, 'Ex Machina', 'Fargo is convinced that Holly is still inside of the Matrix computer, but the DOD is determined to wipe its hard drive clean -- losing Dr. Marten forever.', 43, '2012-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 8, 'In Too Deep', 'Carter''s romantic surprise for Allison turns deadly when they''re trapped in a sinking marine lab with time and oxygen quickly running out.', 43, '2012-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 9, 'Smarter Carter', 'When Allison''s genius older brother comes to meet her new husband, Carter feels the pressure of not being smart enough to measure up.', 43, '2012-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 10, 'The Honeymooners', 'Jack and Allison''s perfect honeymoon is interrupted when sabotage is discovered in Eureka. Elsewhere, Holly faces another hurdle to remain intact.', 43, '2012-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 11, 'Mirror, Mirror', 'Eureka is cut off from the world by a malfunctioning experiment that threatens to eradicate the town''s populace.', 43, '2012-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 12, 'Double Take', 'The people of Eureka are being kidnapped and replaced by body-doubles one by one unless Allison, Fargo and Zane can figure out how to avoid capture and save their town.', 43, '2012-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0796264')) AND numero_temporada = 5), 13, 'Just Another Day...', 'Wormholes randomly materialize around Eureka as the Department of Defense is set to shut the town.', 43, '2012-07-16');
