INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')), 1, 'Season 1', 'Follow a band of exiles on their monumental journey to save humanity and rebuild civilization amid the fall of the Galactic Empire.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 1, 'The Emperor''s Peace', 'Gaal Dornick leaves her life in Synnax behind when the galaxy''s greatest mathematician, Hari Seldon, invites her to Trantor.', 70, '2021-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 2, 'Preparing to Live', 'The Foundation makes the long journey to Terminus as Gaal and Raych grow closer. The Empire faces a difficult decision.', 62, '2021-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 3, 'The Mathematician''s Ghost', 'Brother Dusk reflects on his legacy as he prepares for ascension. The Foundation arrives on Terminus and finds a mysterious object.', 50, '2021-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 4, 'Barbarians at the Gate', 'Salvor faces off with an enemy of the Empire. Brothers Day and Dusk are at odds, while Brother Dawn wrestles with his truth.', 46, '2021-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 5, 'Upon Awakening', 'A flashback reveals the origin of Gaal’s conflict between faith and science. The standoff on Terminus takes an unfortunate turn.', 54, '2021-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 6, 'Death and the Maiden', 'Brother Day meets Zephyr Halima—a would-be leader who opposes the Empire. Brother Dusk grows suspicious of Brother Dawn.', 56, '2021-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 7, 'Mysteries and Martyrs', 'The Anacreons and their hostages board the fabled Invictus warship. The bond between Brother Dawn and Azura intesifies.', 49, '2021-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 8, 'The Missing Piece', 'Brother Day embarks on a journey that no other Cleon has ever attempted. Salvor prepares to make the ultimate sacrifice to return home.', 57, '2021-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 9, 'The First Crisis', 'On Terminus, Salvor witnesses how powerful the null field has become. Brother Dawn makes a daring choice.', 58, '2021-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 1), 10, 'The Leap', 'An unexpected ally helps Salvor broker an alliance. A confrontation between the Brothers leads to unthinkable consequences.', 60, '2021-11-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')), 2, 'Season 2', 'More than a century after the events in the Season 1 finale, tension mounts throughout the galaxy. As the ruling dynasty begins to unravel, a young queen plots her revenge. Meanwhile, a colony of people with special abilities poses a new threat. And it’s all leading toward a collision course for war. INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 1, 'In Seldon''s Shadow', 'Hari finds himself trapped in a mysterious prison. An assassination attempt leaves Day shaken. Gaal and Salvor devise an escape plan.', 50, '2023-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 2, 'A Glimpse of Darkness', 'Gaal has a disturbing vision. Day''s bond with Queen Sareth grows stronger. The Vault opens and reveals a cryptic message.', 53, '2023-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 3, 'King and Commoner', 'The Empire recruits Bel Riose to investigate the resurgent Foundation. Hari leads Gaal and Salvor to a desert planet.', 54, '2023-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 4, 'Where the Stars Are Scattered Thinly', 'Queen Sareth and Dawn share a moment as she tries to learn more about Day. Brothers Constant and Poly bring Hober Mallow to Terminus.', 53, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 5, 'The Sighted and the Seen', 'Gaal, Salvor, and Hari arrive on Ignis and meet the source of the strange signal they''ve been tracking. Dawn and Dusk are suspicious of Day.', 48, '2023-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 6, 'Why the Gods Made Wine', 'Day and Queen Sareth make an announcement. Tellem sows seeds of distrust between Gaal and Hari. Hober Mallow reaches his destination.', 59, '2023-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 7, 'A Necessary Death', 'Salvor begins to question the Mentalics'' motives. Hober Mallow’s proposal to the Spacers meets resistance. Brothers Constant and Poly stand trial.', 54, '2023-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 8, 'The Last Empress', 'Enjoiner Rue confides in Dusk about her distrust of Demerzel. Hober Mallow pulls a daring move. Day sets course for Terminus and the Foundation.', 61, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 9, 'Long Ago, Not Far Away', 'Dusk and Enjoiner Rue learn Demerzel''s origin and true purpose. Tellem''s plans for Gaal take a dark turn. On Terminus, Day confronts Dr. Seldon.', 62, '2023-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 2), 10, 'Creation Myths', 'Gaal, Salvor, and Hari chart a new path forward on Ignis. Demerzel heads to Trantor, taking actions that will change Empire forever.', 54, '2023-09-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')), 3, 'Season 3', '152 years after the events of season two, The Foundation has become increasingly established far beyond its humble beginnings while the Cleonic Dynasty''s Empire has dwindled. As both of these galactic powers forge an uneasy alliance, a threat to the entire galaxy appears in the fearsome form of a warlord known as "The Mule," whose sights are set on ruling the universe by use of physical and military force as well as mind control. It’s anyone''s guess who will win, who will lose, who will live and who will die as Hari Seldon, Gaal Dornick, the Cleons and Demerzel play a potentially deadly game of intergalactic chess.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 1, 'A Song for the End of Everything', 'A mysterious new pirate with terrifying abilities—known as the Mule—catches the attention of the Foundation and Empire.', 52, '2025-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 2, 'Shadows in the Math', 'Gaal and Hari advance their plans on Ignis. Empire grapples with an unforeseen prediction. Pritcher enlists help to investigate the Mule.', 49, '2025-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 3, 'When a Book Finds You', 'An unexpected alliance is formed. Pritcher, Bayta, and Toran come face-to-face with the Mule. Demerzel seeks spiritual guidance.', 51, '2025-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 4, 'The Stress of Her Regard', 'Demerzel struggles with the paradox of her programming. Pritcher''s true loyalties are revealed. Day sets off on a quest for answers.', 49, '2025-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 5, 'Where Tyrants Spend Eternity', 'Day enters uncharted territory. Dawn and Gaal put their plan in motion. Magnifico''s worth becomes clear. Demerzel attempts to restore power.', 47, '2025-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 6, 'The Shape of Time', 'A long-awaited reunion turns violent. Day looks for Song. On New Terminus, the Vault opens—and the Mule takes aim.', 45, '2025-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 7, 'Foundation''s End', 'Chaos and destruction rain down on New Terminus. Back on Trantor, Dusk and Quent unite to assess the state of the galaxy.', 60, '2025-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 8, 'Skin in the Game', 'Gaal and the Second Foundation reckon with the fall of New Terminus. Day faces judgment on Mycogen. Dusk''s ascension looms.', 47, '2025-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 9, 'The Paths That Choose Us', 'Gaal confronts the power of the Mule''s conversions. Dusk resorts to drastic measures. Demerzel searches for clarity about the future.', 47, '2025-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804484')) AND numero_temporada = 3), 10, 'The Darkness', 'Gaal and the Second Foundation take the fight to the Mule as Empire''s legacy suffers a catastrophic blow.', 52, '2025-09-11');
