INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0805663', 'Jericho', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0066218'), 'SERIE', 'A small town in Kansas is literally left in the dark after seeing a mushroom cloud over nearby Denver, Colorado. The townspeople struggle to find answers about the blast and solutions on how to survive.', '2006-01-01', 'https://m.media-amazon.com/images/M/MV5BY2Y4MjE2MjYtMjk0MC00MGMzLWE1ZDktNDEwY2Y4MTZmZjU5XkEyXkFqcGc@._V1_.jpg');
