INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 1, 'Pilot', 'After a nuclear disaster caused by several terrorist attacks wipes out most of North America, residents of a small Kansas town have to come to terms with a very different reality.', 39, '2006-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 2, 'Fallout', 'The fallout from the nuclear blast in Denver will hit Jericho in an hour and Jake has to get the residents inside.  The official shelter is not adequate and Jake must find another shelter to protect them. Emily faces troubles of her own while being picked up by who she thinks are two officers.', 41, '2006-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 3, 'Four Horsemen', 'After seeing a broadcast via satellite from Asia, Jake gathers a group of people together for information gathering.  After finding out that there is information out there, Jake suggests having four search parties to go out to get a better understanding what is going on outside of Jericho.  The search parties set off in four different directions.', 43, '2006-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 4, 'Walls of Jericho', 'Jake finds a stranger who is sick with radiation poisoning and he must make a decision whether or not to help him.  The hospital’s generator is running out of gas and the residents find that their supplies are also running low.', 39, '2006-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 5, 'Federal Response', 'The children of Jericho start to return back to school. A power line that has fallen causes an accident on the playground when the power returns. Jake has an argument with his mother regarding a secret that Jake hasn''t disclosed to his dad.', 41, '2006-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 6, '9:02', 'Hawkins must step in when an argument between Jake and an adversary becomes heated.  After an electromagnetic pulse leaves Jericho in the dark crime runs rampant. Later, Jake is held at gunpoint and is rescued.', 41, '2006-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 7, 'Long Live the Mayor', 'The slick gang leader Jonah bails Mitchell out of jail and agrees to give back the food that his bandits stole and agrees to keep out of Jericho. This plan strays off-course as Jonah negotiates new terms involving Jake and Emily.', 45, '2006-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 8, 'Rogue River', 'Jake and Eric head out of Jericho to the nearby town of Rogue River to try and acquire some medicine for their father.  While the brothers are at the hospital they encounter a combative group of individuals who call themselves Ravenwood. The brothers find that they’re trapped and must find a way back to Jericho.', 43, '2006-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 9, 'Crossroads', 'The residents of Jericho receive a visit from a group of questionable outsiders and they realize that they need to form a plan to keep the outsiders out. Emily has a dream about her wedding morning to Roger. She wakes up and realizes that he is probably dead.', 43, '2006-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 10, 'Red Flag', 'Supplies are dropped by air into Jericho and the Green''s and Hawkins think that they know where they came from. Jonah Prowse returns to Jericho causing even more trouble.', 42, '2006-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 11, 'Vox Populi', 'Some of the residents of Jericho are concerned that Gray''s actions may actually make Gray the new mayor. In other news, Mitchell claims that Jonah is the killer under much speculation.', 45, '2006-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 12, 'The Day Before', 'The lives of Jake and Hawkins are explored during this flashback episode. This episode begins 36 hours before the bombs went off. Sarah is introduced and is associated to Hawkins. Jake had been living in San Diego.', 42, '2007-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 13, 'Black Jack', 'Jake, his dad, Heather and Dale visit Black Jack to try and find the parts needed to fix the windmill. Sarah goes home with Hawkins against the rest of his family''s wishes.', 43, '2007-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 14, 'Heart of Winter', 'While on a hunting trip outside of Jericho, Jake, Stanley and Mimi find themselves in a dangerous situation when they run into some strangers.  Meanwhile, Hawkins realizes that his family is in danger because of him. Emily and Roger work on their relationship.', 45, '2007-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 15, 'Semper Fidelis', 'After a company of Marines show up, the town of Jericho has hopes that life will finally start to return to normal. However, their behavior raises Jake''s and Johnston''s suspicions.', 43, '2007-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 16, 'Winter''s End', 'After April collapses and goes into early labor, Jake makes Kenchy face his problems so that they can save April. The wind turbine arrives from New Bern but Heather does not return. Jericho makes a deal with New Bern to send ten of their people to New Bern to make more wind turbines as long as New Bern receives a percentage of their spring crop.', 45, '2007-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 17, 'One Man''s Terrorist', 'Roger gets desperate after Gray kicks the refugees out of Jericho. Dale and Skylar collect on some debts. Hawkins continues his quest to find Sarah''s contacts.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 18, 'A.K.A.', 'Jake finds that Hawkins has not been honest with the residents of Jericho about his past and holds him at gunpoint for answers.', 43, '2007-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 19, 'Casus Belli', 'Jake believes something more is wrong after Eric doesn’t return from New Bern. Jake and Hawkins go to New Bern and discover that Jericho is in danger.', 45, '2007-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 20, 'One If By Land', 'The hostility mounts between the citizens of Jericho and New Bern. A handful of residents of New Bern are shot and injured after getting caught trying to steal from the Jericho salt mine.', 42, '2007-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 21, 'Coalition of the Willing', 'The residents of Jericho and New Bern fight over precious resources and Gray  must make a tough decision after the streets of Jericho are bombed.', 45, '2007-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 1), 22, 'Why We Fight', 'The battle with New Bern ensues, with Jericho residents out-manned and out-gunned, but not outsmarted. Jericho gains the upper hand but suffers a significant casualty. A friend of Jake''s sends help from an unexpected source.', 44, '2007-05-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 1, 'Reconstruction', 'Following the battle of New Bern, Jericho begins the rebuilding process, while the Cheyenne government shows a particular interest in the town. While the dispute between Jericho and New Bern is being sorted out by the Cheyenne government, Heather returns. Meanwhile, an old friend of Rob comes to Jericho.', 44, '2008-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 2, 'Condor', 'Jericho gets ready for a very important visitor from the new Cheyenne government.  Meanwhile, Hawkins and Chavez work to find the new leaderships secrets.', 45, '2008-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 3, 'Jennings & Rall', 'The deadly Hudson River virus hits the area and a vaccine is being withheld from the citizens by a government official. Jake and the Rangers find a way to protect Jericho.', 43, '2008-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 4, 'Oversight', 'Hawkins receives a call on from someone who knows who he is, where he is and lets Hawkins know exactly when he''ll be caught. Meanwhile, tragedy strikes.', 44, '2008-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 5, 'Termination for Cause', 'Jake and the Rangers take on Goetz and Ravenwood while a Jericho Ranger makes a choice that will alter his life. Meanwhile, an old friend comes to warn Heather that her loyalties to Major Beck have placed her in serious danger.', 43, '2008-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 6, 'Sedition', 'Following the Rangers'' decision to take justice into their own hands, Major Beck goes to extreme measures to prove he''s in complete control of the town, while Hawkins receives a call from Chavez telling him that it''s time to transport the bomb.', 44, '2008-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805663')) AND numero_temporada = 2), 7, 'Patriots and Tyrants', 'Jake and Hawkins have one chance to expose the conspiracy behind the Cheyenne government to the independent Texas administration. However, getting there proves to be the most difficult part of their plan.', 41, '2008-03-25');
