INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')), 1, 'Season 1', 'INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 1, 'Pilot', 'Betty has always dreamed of working in the publishing world, but it seems as though there''s no place for the non-thin and non-beautiful in the business. People already have their minds set in the idea that beautiful women are only the thin and perfect! Betty really wants a job in that wonderful, yet cruel, world. But can she really find a place in it?', 43, '2006-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 2, 'The Box and the Bunny', 'Betty loses a book, which is the complete new edition of the magazine and is containing un-retouched photos of a popular actress. She has to find the book before the photos get out to the rest of the press. Meanwhile, Wilhelmina plots to use the snafu to bring Daniel down and Bradford Meade secretively inquires about Fey Sommers'' final effects.', 43, '2006-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 3, 'Queens for a Day', 'Betty uses her Queens connections to lure big time photographer Vincent Bianchi to shoot for the magazine. When Bianchi insists that Betty meet him at a posh restaurant, she gets a makeover but things don''t quite turn out as planned. In the mean time, Bradford tries to get his hands on Fey Sommers'' death car and Wilhelmina primps for a big date.', 43, '2006-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 4, 'Fey''s Sleigh Ride', 'After Mode is forced to abandon its big Christmas photo shoot because another magazine has copied the idea, Betty forms an uneasy alliance with Marc and Amanda. The three fear they may have leaked the idea to someone at the rival mag. Meanwhile, Daniel and Wilhelmina reluctantly work together to come up with a new photo spread as Mode''s deadline looms, and Betty''s nephew, Justin, is oblivious to the turmoil as he spends a day at the magazine for a class project.', 43, '2006-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 5, 'The Lyin'', the Watch and the Wardrobe', 'It''s Halloween and Betty is in for a series of frightful experiences, ranging from showing up dressed for the Mode costume contest until she learns that there isn''t one, to dealing with her growing attraction to Henry, and tracking down a watch Daniel left at one of his many girlfriends'' apartments, but can''t remember which one. Meanwhile, Daniel pays a visit to his mom in rehab, and Wilhelmina is horrified to learn that she can''t fit into a designer gown.', 43, '2006-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 6, 'Trust, Lust, and Must', 'Wilhelmina deals with the strong character of her daughter while Betty and Hilda try to gather $20,000 to save their father from deportation.', 43, '2006-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 7, 'After Hours', 'Betty takes a break from her escalating family troubles when she''s assigned to review a posh new hotel. Meanwhile, Daniel is dismayed when Sofia Reyes and her team take up residence in the Mode conference room, and Wilhelmina goes a little bit country to woo a mega rich Texan to advertise his stores in Mode.', 43, '2006-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 8, 'Four Thanksgivings and a Funeral', 'To his dismay, Daniel must attend his family''s Thanksgiving gathering at the Country Club. Meanwhile, Amanda and Marc create their own gathering at Mode and there is also a dinner at Betty''s house where Santos, Justin''s father, is in attendance. Meanwhile, Wilhelmina also hosts a Thanksgiving dinner as well but her feast doesn''t look as good as it does in magazine pictures.', 43, '2006-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 9, 'Lose the Boss', 'Betty is left alone during an important photo shoot during which the photographer, Bruno, has come up with questionable concepts. Meanwhile, Daniel wants people to believe he is a family man, Mr. Green interrogates a mortician about the remains of a client and Ignacio gets in trouble with Immigration and Customs.', 43, '2006-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 10, 'Fake Plastic Snow', 'While everyone at Mode is celebrating Christmas, Betty is questioning her relationship with Walter and the feelings she has for Henry. Meanwhile, Daniel is sure of his love for Sofia, and Amanda, in order to get Betty''s position, is planning a perfect Mode holiday party that fills the office with Styrofoam snow and holiday wishes.', 43, '2006-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 11, 'Swag', 'Christina''s swag lottery, with the Mode closet clothes and accessories, creates a feeding frenzy among the office fashionistas, while Betty wears herself out helping Daniel who had his credit card cut off, because of a $20,000 expense report that Betty filled and who was rejected, making it impossible for him to wine and dine an important Japanese designer, Oshi.', 43, '2007-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 12, 'Sofia''s Choice', 'Betty meets a look-a-like -- Ruthie, an editorial assistant at MYW Magazine who dresses and looks like her. Meanwhile, Daniel is in for a surprising revelation from Sofia that leaves everyone stunned.', 43, '2007-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 13, 'In or Out', 'While Daniel is still suffering from his break up with Sofia, Betty is doing her best to get him back to work and over Sofia. Meanwhile, Wilhelmina decides who will continue to work at Mode once her ambitions to be named Editor-in-Chief are realized.', 43, '2007-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 14, 'I''m Coming Out', 'Betty has her job cut out for her getting prepared for Mode''s huge event during New York City''s Fashion Week. Meanwhile, Marc and Amanda can''t delay getting their hands on something everybody desires, Christina wishes to create her mark in the design world and Daniel calls for Hilda to grant her sister a hand.', 43, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 15, 'Brothers', 'Alexis'' shocking announcement causes great commotion at both Mode and the Meade home. Betty tries to maintain the peace and order at Mode, however, she is about to face her own personal turmoil when Henry asks her out on a date and Walter tells her he''s got a big surprise in store. Meanwhile, Whilhelmina plots her next move to conquer Mode and Justin gets sent home from school for fighting.', 43, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 16, 'Derailed', 'Daniel reconnects with Grace Chin, a girl he once stood up for a date in college, and who is now New York City''s top lawyer. Meanwhile, Betty befriends Charlie, an out-of-towner she meets at the Mode cafeteria, whom she later discovers to be Henry''s girlfriend.', 43, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 17, 'Icing on the Cake', 'Daniel keeps secret from Alexis the fact that he is the one who hired Grace to defend their father, something which Wilhelmina uses to bring the siblings apart. Meanwhile, when invited by Henry to Charlie''s birthday party, a desperate Betty asks Dr. Farkas, her orthodontist, to be her date. Finally, Amanda catches the eye of an unusual designer who claims that she is his muse.', 43, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 18, 'Don''t Ask, Don''t Tell', 'Betty is in for some wild drama when Marc''s mother stops by, given that the latter doesn''t seem to know that her son is gay and Betty acts as his girlfriend to help him keep his secret. Meanwhile, Daniel and Alexis are forced to work together when Claire names them both co-editors-in-chief.', 43, '2007-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 19, 'Punch Out', 'The Meades are in for some troubling times when a tell-all writer in possession of Fey Sommer''s diaries starts stalking the family. Meanwhile, Betty has a hard time getting Daniel focused on his work now that he has reverted back to his old ways with women. Finally, Wilhelmina and Alexis both try desperately to get a hold of Fey''s diaries, but each with her own intentions.', 43, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 20, 'Petra-Gate', 'After seeing her working relationship with Daniel, her close friendship with Christina, and her chance to date Henry all fall apart, Betty is left with no choice but to turn her back on all three. Meanwhile, romance is in the air: At MODE, Alexis catches the attention of a guy and he asks her out; Amanda flirts with a designer who she believes is gay; and Wilhelmina finds her latest advances very tiring. Over at the Suarez''s, Santos gives Hilda a little surprise.', 43, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 21, 'Secretaries'' Day', 'Betty struggles with a dilemma as she attempts to bail her family out of a financial crisis while juggling with the task of planning MODE''s big assistants week at a medieval-themed restaurant...where Amanda''s past ties to the establishment has a link and could come back to haunt her in a surprising way. On the romantic front involving the Meade siblings, Betty tries to give Daniel advice about his endless sexual addiction, while Alexis ponders about whether she should start taking up Rodrigo''s offer. Meanwhile, Hilda prepares for her first exam to determine her future at cosmetology school as Wilhelmina prepares for her future plans to take over MODE as she makes even bolder moves for domination behind the scenes.', 43, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 22, 'A Tree Grows in Guadalajara', 'The Suarez family travel to Mexico in a effort to help Ignacio obtain a US Visa and find out more about their true family roots, especially Ignacio''s real identity.', 43, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 1), 23, 'East Side Story', 'Betty and Henry''s romance heats up. Meanwhile, Wilhelmina makes great strides in her ambitious power play, as Daniel descends further in a downward spiral. The Suarez family trip to Mexico takes a dangerous turn, with old ghosts creating new problems. Explosive secrets will be revealed, and everything will be tied together by a beloved Broadway musical.', 43, '2007-05-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 1, 'How Betty Got Her Grieve Back', 'Betty''s life is turned into turmoil after the numerous upsetting events that have recently occurred. Despite all this, she refuses to accept the fact that Henry''s leaving has deeply affected her. Meanwhile, Amanda has a hard time coping with the news she recently discovered about who her real mother is and Wilhelmina plans to use all the recent tragedies to her advantage.', 43, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 2, 'Family/Affair', 'Betty gets a little overwhelmed about Wilhelmina''s brand new hunky bodyguard.  Plus, Henry returns to pay for insurance, which has Betty concerned about their relationship.  Because of the fatal crash, Alexis gets amnesia and Bradford uses it to his advantage.  Hilda comes to terms with recent events.  And Amanda gets a surprise inheritance from her late biological mother.', 43, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 3, 'Betty''s Wait Problem', 'Even though Henry is kind of back in her life, Betty finds herself annoyed and yet intrigued by the new sandwich guy, Giovanni.  Meanwhile, everyone at Mode prepare for the Meades'' Black and White Ball.  Wilhelmina tries to get her wedding back on track.  Amanda prepares to make her first appearance as Fey Sommers'' birth child and fugitive Claire Meade invites herself to Wilhelmina''s wedding.', 43, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 4, 'Grin and Bear It', 'Betty gets into trouble in her writing class when she submits a pre-written MODE story written by a woman who survived a bear attack (hence the title).  Alexis returns to work, still with memory loss and having no idea how to act like a girl.  Daniel receives a threat from their top advertiser who is against transsexuals and wants Daniel to fire his own sister.  Amanda, still trying to figure out who her real father is, learns a shocking secret about Wilhelmina''s past.', 43, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 5, 'A League of Their Own', 'Betty tries internet dating and she gets asked out; Marc attracts the attention of a photographer that Marc doesn''t see as attractive; Wilhelmina tries to prove to the skeptical Daniel and Alexis that she can be part of the Meade family; Hilda is unaware that Justin has become a changed teen when he starts hanging with the wrong crowd and skips school.', 43, '2007-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 6, 'Something Wicked This Way Comes', 'Betty and Henry secretly go on a date to see Wicked, but Daniel, thinking that her date is Gio, gives two tickets to Betty and Gio and Gio does not want to give up those tickets.  Meanwhile, Daniel gets in a meeting with an advertiser, a woman who has an interest in younger men, namely Daniel.', 43, '2007-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 7, 'A Nice Day for a Posh Wedding', 'As Wilhelmina prepares for her flamboyant wedding, she quickly realizes that her maid of honor, Victoria Beckham, is stealing all her thunder. Meanwhile, Betty is filled with guilt about her pact with Wilhelmina to keep  the latter''s affair a secret and Ignacio prepares for his big day as he is about to become an official U.S. citizen. However, when Betty moves in with Henry the father/daughter relationship is strained.', 43, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 8, 'I See Me, I.C.U.', 'Following the wedding fiasco, Wilhelmina wastes no time and plots her next move to conquer Mode. Meanwhile, Betty tries her best to regain Daniel''s affections.', 43, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 9, 'Giving Up the Ghost', 'A crisis caused by Wilhelmina has the team at Mode struggling to meet a deadline under extreme time constraints. Consequently, Alexis is forced to flirt with the printer for an extension, and Betty and Daniel try to free a teen star out of rehabilitation for a re-shoot.', 43, '2007-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 10, 'Bananas for Betty', 'Henry and Betty go on a double date with  Hilda and Gio. Wilhelmina tries to change her image as the queen of mean but fails miserably.', 43, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 11, 'Zero Worship', 'When Justin and his classmates visit Mode, Betty is bothered by the message the magazine is sending across to the kids and encourages Daniel to use ordinary women as models during fashion week.  Meanwhile, Amanda visits a psychic for news about her biological father and Wilhelmina gets an unprecedented turnout in her latest plan for absolute power.', 43, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 12, 'Odor in the Court', 'Wilhelmina tries to becomes part of the Meade family by any means necessary.  Amanda withholds evidence and Betty applies a deadly perfume made by Fey Sommers.', 43, '2008-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 13, 'A Thousand Words by Friday', 'Betty is assigned to interview a novelist. Amanda and Marc may have uncovered who Amanda''s biological father is. Daniel unknowingly dates Wilhelmina''s sister.', 43, '2008-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 14, 'Twenty-Four Candles', 'Betty plans to spend her 24th birthday accompanied by Henry, but Charlie''s sudden appearance jeopardizes her plans. Meanwhile, Wilhelmina plots against Renee and Daniel''s relationship by hinting at secrets from a hidden past in her sister''s life.', 43, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 15, 'Burning Questions', 'Renee becomes convinced that Betty is in love with Daniel and thus starts a rivalry between the two for his affections. In the meantime, Gina returns to Queens to flash her new life and rich husband before Hilda''s face.', 43, '2008-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 16, 'Betty''s Baby Bump', 'Betty decides to patch things up with Charlie by throwing her an unforgettable baby shower. Meanwhile, Hilda decides to confront Justin''s teacher after learning that he is failing gym class and Christina learns who the father of Wilhelmina''s baby really is.', 43, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 17, 'The Kids Are Alright', 'Betty finds her attempts to suppress her feelings for Gio useless when the two end up chaperoning Justin''s school dance together. Meanwhile, Amanda agrees to do a reality show with Gene, and Hilda goes out of her way to catch the eye of Coach Diaz. Finally, Wilhelmina makes her return to MODE, much to the distaste of the Meade family.', 43, '2008-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 2), 18, 'Jump', 'Betty finds herself in a dilemma between Henry and Gio when each makes a romantic offer to her. Meanwhile, a softball game between ELLE and Mode has rivals Wilhelmina and Naomi Campbell facing off in the field. Finally, Hilda makes quite a discovery about Coach Diaz, and a surprise visit from an orphaned French boy stirs things up at Mode.', 43, '2008-05-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 1, 'The Manhattan Project', 'Betty must make a life-altering decision about what to do with her life. Meanwhile, Ignacio lands a job at a fast food restaurant while Wilhelmina forces Daniel to make changes in his life.', 43, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 2, 'Filing for the Enemy', 'Wilhelmina, getting ready for her first issue as editor, offers Betty a job as her assistant. Meanwhile, Daniel learns he will have to undergo a custody battle if he wants to keep Daniel Jr. in the U.S. Later, Hilda''s romance with Coach Diaz continues to heat up.', 43, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 3, 'Crimes of Fashion', 'A tragic accident leaves the Mode staff stunned and Betty must find out what really happened when a detective comes looking for answers. Meanwhile, Ignacio learns about Hilda and Coach Diaz.', 43, '2008-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 4, 'Betty Suarez Land', 'Gio returns to town, forcing Betty to attempt to make amends. However, Gio resists her attempts to make things right. Meanwhile, Daniel must cope with shocking family news.', 43, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 5, 'Granny Pants', 'Kimmie Keegan goes to Betty for help in finding a job. Meanwhile, Daniel decides to try a matchmaking service and gets a shocking "perfect" match. Elsewhere, Justin tries out for a Broadway musical.', 43, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 6, 'Ugly Berry', 'Betty finds herself competing with Kimmie who finally shows her true colors, and new citizen Ignacio prepares to vote for the first time.', 43, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 7, 'Crush''d', 'Betty wants to be noticed by her cute neighbor, Jesse, by coming home later each night. Meanwhile, Amanda unexpectedly moves in with Betty after having nowhere else to go. Elsewhere, Marc and Cliff mull over the idea of moving in together.', 43, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 8, 'Tornado Girl', 'Betty needs Daniel''s help to prevent a PR nightmare for the magazine. The problem is, he''s unreachable at a company retreat.', 43, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 9, 'When Betty Met YETI', 'Competition gets fierce when Betty and Marc both apply to YETI, the Young Editors Training Program that could be their ticket out of assistant-land.', 43, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 10, 'Bad Amanda', 'Amanda and Betty are forced to work together for an article called "How I Blew Ten Grand Without Spending a Dime."', 43, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 11, 'Dress for Success', 'Betty juggles work and family without much success as she struggles to impress her idol, Jodie Papadakis (guest star Bernadette Peters), the editor running YETI.', 43, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 12, 'Sisters on the Verge of a Nervous Breakdown', 'Betty finds herself stuck between work and home life as she tries her best to appease both Hilda; Daniel, Molly, Connor and Wilhelmina.', 43, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 13, 'Kissed Off', 'Betty comes up with a solution to deal with her personal problems but she has her sexy neighbor Jesse who keeps her distracted from her goals. Daniel does his best to cover his tracks as Connor is adamant on unveiling Molly''s admirer.', 43, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 14, 'The Courtship of Betty''s Father', 'It''s Claire''s 60th birthday and Betty makes her a video which reveals some unintentional footage of Mrs Meade. Also, Daniel and Wilhelmina are finding it hard having someone new in their lives.', 43, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 15, 'There''s No Place Like Mode', 'Fashion Week hits town which causes problems for the staff at Mode. Betty has to split her time between working on her Yeti assignment and working with a new designer. Elsewhere, Wilhelmina has lost her way because of Connor and there''s a new person working at Mode.', 43, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 16, 'Things Fall Apart', 'Betty and Marc team up together to analyse Mode''s budget. Matt continues with his pursuit to win Betty while she deals with some startling news on Facebook by a former flame', 43, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 17, 'Sugar Daddy', 'The Suarez family attempt to buy their rented house from their landlord. Ignacio goes head to head with Frankie Burrata, a celebrity chef. While everyone in Mode comes to deal with their shock.', 43, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 18, 'A Mother of a Problem', 'Betty meets Matt''s mother, but the meeting turns into a disaster. Meanwhile, Wilhelmina comes up with a way to solve the company''s cash problem; Daniel deals with his relationship with Molly; and the Suarez''s work together to set Hilda up with Archie.', 43, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 19, 'The Sex Issue', 'Daniel and Wilhelmina make Mode''s issue based on sex to spice things up. Matt is hesitant to take the next step with Betty. Marc and Amanda provide Betty with a makeover.', 43, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 20, 'Rabbit Test', 'Daniel hatches up an idea to boost the Mode''s financial situation after discovering that Betty and her family have been invited to the home of Matt''s obscenely wealthy father, for an Easter egg hunt. Meanwhile, Wilhelmina discovers a reason to become suspicious of her son''s DNA.', 43, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 21, 'The Born Identity', 'Baby William is the unlikely hold up in Mode receiving the money it needs to save the company, whilst Hilda is asked to help with a political campaign.', 43, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 22, 'In the Stars', 'Betty, Matt and Marc come together in order to succeded in their final YETI project, a photo session with singer, Adele. Love is in the air for one lucky couple as proposals are made. Claire and Wilhelmina continue to argue.', 43, '2009-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 23, 'Curveball', 'Just as Betty agrees to move in with Matt, Henry pays a visit to NYC, forcing Betty to admit she still has feelings for her former fiancé.', 43, '2009-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 3), 24, 'The Fall Issue', 'The sudden death of a Mode editor leaves Betty and Marc competing for the same job. Meanwhile, Matt lets his jealousy over Henry get the best of him.', 43, '2009-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 1, 'The Butterfly Effect (1)', 'Betty finds that everything is changing as she begins her new job as associate features editor, especially since her boss is her ex-boyfriend, Matt Hartley, who is still unhappy about their breakup. In addition, Betty''s new officemate, Megan, openly resents her, while Marc is constantly undermining her because he felt he was more deserving of the promotion. Meanwhile, without Betty as his assistant, Daniel is adrift, still mourning the loss of his wife, Molly. Betty tries to help Megan out on an assignment and connects with a thoughtful insect jewelry designer, Olivia, while Justin starts high school and is victimized by bullies-but won''t tell his mom, Hilda. Claire Meade is finding that her power struggle at the company has her sitting pretty - for the moment -- opposite Wilhemina, who lost her claim to the Meade throne last season. But Wili has perhaps an even bigger problem than job security - she is harboring a secret at home that is driving Marc to distraction.', 43, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 2, 'The Butterfly Effect (2)', 'Betty gets to run her own Mode photo shoot at the United Nations to promote their anti-malaria initiative, "Nothing but Nets," but her big opportunity becomes a baptism by fire when Daniel''s neediness takes its toll, and Matt openly demoralizes her. Meanwhile, Amanda does some soul-searching when she bonds with Daniel''s new temp, Helen, a career receptionist as fabulous as Amanda is. Wili makes it her personal mission to protect a loved one, and Hilda reaches out to Marc to figure out how to help Justin.', 43, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 3, 'Blue On Blue', 'Betty tries to get a scoop with Gucci''s new designer, Evan York, through Hilda''s customer, Sammy. Marc tries to stop her by getting Amanda and Matt to stage a showdown at Ignacio''s restaurant. Daniel goes to a bereavement group and meets Natalie who shows him an interesting night. Wilhelmina flies to Bermuda to try and find Connor. ', 43, '2009-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 4, 'The Wiener, the Bun and the Boob', 'Betty has Marc as be her temporary assistant thanks to Wilhelmina. Betty ends up covering the worst jobs in New York as an assignment but she needs to dress up as a hot dog and perform a Bollywood style dance. Marc has insecurities about how his idol at Vogue magazine will perceive him. Daniel is targeted by the leader of the Community.', 43, '2009-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 5, 'Plus None', 'At Wilhelmina''s fund-raiser for Tibetan orphans Matt asks someone to be his partner. Daniel hires Natalie as his assistant, making Betty feel unneeded. Daniel finds out that Claire has a secret.', 43, '2009-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 6, 'Backseat Betty', 'Hilda has doubts over her relationship with Archie after seeing an old flame Bobby Talercio. Marc helps Justin to fit in high school by telling him to become friends with some mean girls. Elsewhere Daniel is lured into a trap by Bennett. Wilhemina tries to come up with money to help Nico out of trouble.', 43, '2009-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 7, 'Level (7) with Me', 'Daniel hands over the power to the Community of the Phoenix to run Mode. Betty steps in to help Daniel with Bennet. She comes up with an cunning plan with the help of Claire. Wilhemina goes out in public wearing sweats creating mayhem with the media trying to get a scoop.', 43, '2009-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 8, 'The Bahamas Triangle', 'Betty, Matt and Amanda''s love triangle in the Bahamas reaches boiling point. Betty has trouble with a photo shoot when Penelope Graybridge steals the shoot from her enemy Wilhemina. Marc falls for super sexy Troy.', 43, '2009-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 9, 'Be-Shure', 'Ignacio prepares a romantic dinner for his Jean. Betty and Hilda take the Be-Shure instant pregnancy tests. Meanwhile, Hartley gets Denise Ludwig to fill in for Wilhemina. However Marc plans to bring Willie back. Claire with Amanda track down Tyler, the son she gave up for adoption.', 43, '2009-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 10, 'The Passion of the Betty', 'When Betty becomes concerned that she and Matt are spending too much time together, she tries to give him something else to be passionate about -- a surprise gallery showing of his art work -- with unintended results. Meanwhile, Marc is horrified that his one-night stand, Troy, is falling for him, since Marc was Troy''s "first", Hilda grapples with whether or not to tell Bobby that he''s the father of her unborn child, and Cal officially replaces Wilhelmina with Denise. ', 43, '2010-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 11, 'Back in Her Place', 'A battered but unbowed Betty recounts her worst week EVER to Mr. Z as the show flashes back to her horrible last few days. Frustrated over the frivolous assignments Wilhelmina gives her at Mode, and inspired by Audrey Hepburn''s memoir, Betty creates her own blog about amazing charitable ventures that inspire her. However, as her hobby enriches her, her job is nearly killing her, since Wilhelmina tortures Betty with beauty experiments for future stories. Meanwhile, Daniel fears Marc is sabotaging him -- and he is; Bobby treats a hormonal Hilda to some pampering during "Hilda Week," which goes awry, and Wilhelmina makes a long-term commitment to the incarcerated Connor.', 43, '2010-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 12, 'Blackout!', 'Betty invites Hilda and Justin to stay for dinner after Justin''s acting class audition, but they decline. Living alone in her, Betty realizes that she misses Matt and fears that if something happened to her, no one would know. Though Amanda and Marc live in the same building, they do not want to walk to work with her, increasing her loneliness. Meanwhile, Marc is feeling tension working for both Daniel and Wilhelmina, and sees a career opportunity when he hears the vacant Senior Fashion Editor position will be filled. ', 43, '2010-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 13, 'Chica and the Man', 'Wilhemina is livid when she lays eyes on drag queen impersonator - Wilhediva Hater. Betty and Daniel go through a rough patch as she wins an award for her blog. Daniel has the press hot on his heels. While Marc is pleased with himself when a famous director does a photo shoot with him.', 43, '2010-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 14, 'Smokin'' Hot', 'Daniel helps Betty to cover a low-priority show. Betty discovers a new designer, Marisa, and decides to promote her however she faces stiff competition from Marc. Amanda struggles to persuade Marc or Betty to vouch for her to Wilhemina about her clothing line. Tyler tries to find Claire in New York.', 43, '2010-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 15, 'Fire and Nice', 'To speed along the investigation into her house fire, Betty is pressured to date an annoying fireman. Wilhemina tries to prove to Don, an old flame from her past, that she''s just "Wanda from the block" instead of an uber-bitch, and Amanda draws closer to Tyler, convincing Claire to hire him as an in-house model at Mode. Meanwhile, Hilda meets Bobby''s parents for the first time.', 43, '2010-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 16, 'All The World''s A Stage', 'Justin is enjoying his acting class with his eccentric teacher, Lena Korvinka. When Betty thinks there might be a problem with him and his friends, Austin and Lilly, she drops by the class to check up on him. Betty gets sidetracked when a playwright called Zachary is introduced to the class. Betty tells Hilda about Zachary and believes his speech about reinvention was aimed at her. ', 43, '2010-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 17, 'Million Dollar Smile', 'In the episode, Betty Suarez finally has her braces removed, but only after she enters a dream sequence in which she sees what her life would be like if she had had perfect teeth. At the same time, Justin Suarez tries to contact Austin, who he kissed in the previous episode and Daniel Meade secures the Million Dollar Bra for a MODE cover shoot. Meanwhile Amanda Tanen reveals that her relationship with Tyler is getting serious.', 43, '2010-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 18, 'London Calling', 'Hilda is planning her wedding, which is getting closer and asks Betty about the plans for her bachelorette party. Betty tells her that she''s planned a champagne tour of The Met museum, but Hilda and Bobby believe it''s a joke and Betty has to think of something else. Bobby is put out when Justin turns down a lift to school in favour of walking with Austin. ', 43, '2010-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 19, 'The Past Presents the Future', 'As Hilda''s wedding approaches, Betty asks Daniel to be her guest, Amanda tries to set Marc up with soap opera star Spencer Cannon, Justin wonders whether he can invite Austin, Wilhelmina finds a way to get the Meade empire and Betty gets an unexpected offer in both her personal and professional lives.', 43, '2010-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0805669')) AND numero_temporada = 4), 20, 'Hello Goodbye', 'The episode focuses on Betty Suarez struggling to tell her friend and boss, Daniel Meade about her new job in London. At the same time, Betty''s sister, Hilda tries to keep their father from finding out she is moving to Manhattan. Wilhelmina Slater recovers from being shot by Tyler and Amanda Tanen finally finds her father.', 43, '2010-04-14');
