INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0804503', 'Mad Men', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0008971'), 'SERIE', 'A drama about one of New York''s most prestigious ad agencies at the beginning of the 1960s, focusing on one of the firm''s most mysterious but extremely talented ad executives, Donald Draper.', '2007-01-01', 'https://m.media-amazon.com/images/M/MV5BYTNjNjc5OWQtYjMxNC00MzEwLWIxM2UtNjU3NzhkNjZmNGI3XkEyXkFqcGc@._V1_.jpg');
