INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')), 1, 'Season 1', 'Season one takes place between March and November 1960. It introduces the fictional advertising agency Sterling Cooper. The season begins with the new secretary, Peggy Olson, starting her first day with the firm. As the season unfolds, the mysterious backstory of enigmatic ad man Don Draper is revealed as are the growing confidence and success of Peggy Olson.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 1, 'Smoke Gets in Your Eyes', 'In 1960 New York City - the high-powered and glamorous "Golden Age" of advertising - Don Draper, the biggest ad man in the business, struggles to stay a step ahead of the rapidly changing times and the young executives nipping at his heels.', 49, '2007-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 2, 'Ladies Room', 'Don continues to conceal his increasingly complicated personal life, even in the face of Roger Sterling''s invitation to open up. Meanwhile, Peggy pines for the absent Pete  still on his honeymoon  while fending off the advances of several of the men of Sterling Cooper.', 47, '2007-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 3, 'Marriage of Figaro', 'Pete returns from his honeymoon, excited about his new marriage, but conflicted about his past encounter with Peggy. After his business relationship with Rachel takes an unforeseen turn, Don attends a party which further illuminates his increasing dissatisfaction with his present life.', 44, '2007-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 4, 'New Amsterdam', 'Pete''s professional and personal lives become more complicated as he struggles to assert power in both. While facing pressure from his wife regarding a new apartment, he further alienates Don and endangers his own position at Sterling Cooper.', 45, '2007-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 5, '5G', 'After Don wins an award, his photo is featured in Advertising Age. Don must deal with the fallout as the photo brings back a past he isnt ready to confront. Ken gets a short story published in The Atlantic Monthly, inciting jealousy among his colleagues and driving Pete to make an unorthodox request of his wife. Peggy overhears a startling conversation in the office and shares the secret with Joan.', 48, '2007-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 6, 'Babylon', 'A taboo office romance is revealed. At a brainstorming session, Peggy proves to be more than a secretary, opening up new opportunities for her at Sterling Cooper. Meanwhile, Rachel faces her conflicted feelings for Don after he seeks out her advice on a new campaign.', 47, '2007-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 7, 'Red in the Face', 'Roger joins Don for an evening of dinner and drinking, during which Roger''s behavior leads to a rift in their friendship. Though Don accepts his apology, there are further consequences for Roger. Pete faces trouble at home as he continues to struggle with the demands of his new marriage.', 47, '2007-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 8, 'The Hobo Code', 'Don is tormented as pieces of his secretive past begin to haunt him. Peggy''s new success at work, and resulting boost in confidence, threaten her office relationship. Salvatore Romano gets a little too close with a client.', 48, '2007-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 9, 'Shoot', 'A rival ad agency courts Don, involving Betty in their attempt to lure him from Sterling Cooper. As the presidential campaign heats up, the agency looks for new ways to counter the latest Kennedy ads. Tempers flare over Peggy.', 48, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 10, 'Long Weekend', 'Don loses an account. Roger, stuck in the city for Labor Day weekend, attempts to cheer him up. Meanwhile, Joan has a night out on the town with her roommate.', 48, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 11, 'Indian Summer', 'Peggy is given a difficult assignment. Roger''s work problems provide new opportunities for Don, and Pete grows more frustrated. Betty finds a new outlet for her growing dissatisfaction.', 48, '2007-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 12, 'Nixon vs. Kennedy', 'On election night, the Sterling Cooper staff pulls a rowdy all-nighter while watching the returns. Pete''s ambitions cause him to directly challenge Don. Don remembers his past as a soldier in the Korean War.', 48, '2007-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 1), 13, 'The Wheel', 'As Thanksgiving approaches, Don''s work responsibilities interfere with his domestic life. Peggy is given a new opportunity, provoking the ire of some of her colleagues. Betty makes a startling discovery.', 49, '2007-10-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')), 2, 'Season 2', 'Season two takes place between February and October 1962, culminating with the Cuban Missile Crisis. It expands on Peggy''s rise in the workplace and the marital strife between Don and Betty Draper as Don''s infidelities further intrude on his family life. The second season also introduces an unknown acquaintance of Don Draper. Draper is corresponding by letter with this unseen acquaintance in secret.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 1, 'For Those Who Think Young', 'It’s Valentine’s Day, and the Sterling Cooper advertising agency is hustling to stay on top of its game and buzzing over the newest office equipment. Don and Duck find themselves at odds over an account. Betty reconnects with an old friend and once again finds herself struggling with car trouble.', 49, '2008-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 2, 'Flight 1', 'Paul hosts a party at his apartment and introduces someone special to his Sterling Cooper colleagues. Peggy visits her family for dinner. Despite a conflict of interest, the Sterling Cooper agency aggressively pursues an airline account and Duck attempts to appeal to the client using an unorthodox approach.', 49, '2008-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 3, 'The Benefactor', 'Trouble arises on the set of a commercial; Harry tries to gather support for a controversial sponsorship; Betty and Don try to appease a client with a friendly dinner.', 47, '2008-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 4, 'Three Sundays', 'Peggy''s family hosts a lunch for their church''s new priest; Don and Betty enjoy a weekend together; Pete and Ken take a client out to lunch; the staff works to prepare for a last minute pitch meeting.', 48, '2008-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 5, 'The New Girl', 'Don has to deal with issues between a TV comedian and his wife; Joan finds Don the perfect secretary.', 49, '2008-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 6, 'Maidenform', 'Don and Duck try to make peace; Peggy tries to get into the executive''s after-hours meetings; Duck deals with a family visit.', 48, '2008-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 7, 'The Gold Violin', 'Don buys a new car; Pete, Harry and Ken strategize to attract new business; Don''s secretary makes a grave error; Cooper has a new piece of art in his office.', 48, '2008-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 8, 'A Night to Remember', 'Peggy contributes on a church project; Duck and Don try to create market appeal for a foreign beer brand; Harry recruits assistance to help with the workload in his department.', 49, '2008-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 9, 'Six Month Leave', 'Freddy Rumsen disappoints his team during a pitch. Pete finds an opportunity at the office to exploit while Don proves his loyalty to an old friend. Betty finds a welcome distraction in Sara Beth.', 49, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 10, 'The Inheritance', 'Betty visits her father; Paul''s girlfriend tries to convince him to prioritize his duties; Pete''s mother disapproves of his and Trudy''s idea.', 48, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 11, 'The Jet Set', 'Don makes some new friends on his trip to Los Angeles; Peggy looks for romance; Duck ponders the future of Sterling Cooper.', 48, '2008-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 12, 'The Mountain King', 'Don meets up with an old friend; Pete''s personal life presents problems; Joan brings her boyfriend to the office.', 48, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 2), 13, 'Meditations in an Emergency', 'The office scrambles without Don; Betty learns some disconcerting news.', 48, '2008-10-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')), 3, 'Season 3', 'Season three takes place six months after the conclusion of the second season and ends in December 1963. It chronicles the end of the "Camelot era" as the characters go through immense change in their professional and personal lives.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 1, 'Out of Town', 'In the third-season opener, Salvatore and Don take a business trip out of town. Pete Campbell and Ken Cosgrove worry about the changes at Sterling-Cooper and how the changes will impact them.', 48, '2009-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 2, 'Love Among the Ruins', 'Don''s father-in-law pays a visit to his daughter''s family. Peggy works hard on a campaign while the firm tries to decide if they will accommodate an unusual request from a client. Elsewhere, Roger plans a wedding.', 48, '2009-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 3, 'My Old Kentucky Home', 'The writers make an attempt to stave off late-night boredom during a mandatory overtime session. Roger throws a party as Joan and Greg host their own party. Sally has a run-in with Grandpa.', 48, '2009-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 4, 'The Arrangements', 'Don and his father-in-law cross paths. Meanwhile, Peggy is in search of a new roommate; and a rich new client is excited to be doing business with the firm.', 48, '2009-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 5, 'The Fog', 'Sally''s behavior causes concern for Don and Betty. Betty has an eye-opening dream that has a strange effect on her. Pete tries to work a new business angle in his dealings.', 48, '2009-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 6, 'Guy Walks Into an Advertising Agency', 'Sterling Cooper receives a surprise visitor; Sally has been spooked by something (or someone); and Joan receives some shocking news.', 48, '2009-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 7, 'Seven Twenty Three', 'Betty tries her hand at local politics. Don is forced into thinking about the future. Peggy receives a luxurious gift.', 48, '2009-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 8, 'Souvenir', 'Don decides to include Betty on a company business trip. Pete lends a hand to a neighbor in his apartment building.', 48, '2009-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 9, 'Wee Small Hours', 'There is trouble for Don and Sal in giving their clients what they ask for. Meanwhile, Betty hosts a fundraiser.', 48, '2009-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 10, 'The Color Blue', 'The firm celebrates as they hit a milestone. Peggy and Paul compete to secure the same account.', 48, '2009-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 11, 'The Gypsy and the Hobo', 'A former client makes a return; Betty and her kids go on a trip; and Joan and Greg make plans for their future.', 48, '2009-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 12, 'The Grown-Ups', 'Peggy''s taste in men proves questionable. Pete has to make a big decision about his career and a candidate makes a big impression on Don.', 47, '2009-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 3), 13, 'Shut the Door. Have a Seat', 'Don has a big meeting with Connie about their future relationship. Betty is the beneficiary of some interesting advice and Pete has a serious sit-down with some clients.', 48, '2009-11-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')), 4, 'Season 4', 'Season four takes place between November 1964 and October 1965. It is set at the new and considerably more modern advertising agency, Sterling Cooper Draper Pryce. The main narrative of the fourth season is driven by Don Draper''s identity crisis. As Don falls deeper into existential despair, he begins regularly meeting with women of loose moral character and faces debilitating alcoholism.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 4), 1, 'Public Relations', 'Don deals with a trade-paper interview but doesn''t want to talk about himself. A manufacturer of a "wholesome" two-piece bathing suit wants to hire the firm but doesn''t want anything too risque. Pete and Peggy try to secure more money for the firm.', 48, '2010-07-25');
