INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 4), 9, 'The Beautiful Girls', 'Peggy is forced to face some unpleasant facts about a client''s discriminatory business practices. Don and Faye''s burgeoning relationship is tested when Sally runs away from home and turns up at the office. Roger tries to rekindle his affair with Joan.', 47, '2010-09-19');
