INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')), 5, 'Season 5', 'Season 5 takes place between Memorial Day 1966 and spring 1967. The season explores Don Draper''s new marriage to Megan, which leads him to ignore his work at the Sterling Cooper Draper Pryce advertising agency. Meanwhile, Lane, Pete, Roger, Joan, and Peggy learn that it is "every man for himself" in their personal and professional lives, as they each face painful new beginnings.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 1, 'A Little Kiss (1)', 'For the Draper family, life has changed. The children must adapt to a new home, a new brother, and a new stepmother. Don seems to have everything a man could want. However, Megan, still employed at the agency, has difficulty interpreting Don''s expectations for a sex kitten at home and a prim and proper employee at the office.', 48, '2012-03-25');
