INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 3, 'Tea Leaves', 'As Sterling Cooper Draper Pryce tries to build upon its current business, Peggy is given new responsibility. Don and Harry indulge a client. Betty contemplates her mortality after seeing a doctor.', 48, '2012-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 4, 'Mystery Date', 'Don has an encounter with someone from the past. Meanwhile, Roger increases Peggy''s workload, and Joan comes to a momentous decision.', 48, '2012-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 5, 'Signal 30', 'Lane attempts to land an account with Jaguar Cars, leading to a altercation with Pete. Pete and Trudy host a dinner party in the suburbs.', 48, '2012-04-15');
