INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 7, 'At the Codfish Ball', 'Don is honored at a banquet for the American Cancer Society, but finds his professional reputation has been damaged. Sally lends a hand to a relative. Megan''s parents come to visit from Canada.', 48, '2012-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 8, 'Lady Lazarus', 'Megan has second thoughts about her future at Sterling, Cooper, Draper, Pryce. Peggy lashes out when she''s inadvertently put in the uncomfortable position of having to lie. Pete''s effort to protect an acquaintance doesn''t turn out quite like he expected.', 48, '2012-05-06');
