INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 10, 'Christmas Waltz', 'Harry finds himself in an uncomfortable position after reconnecting with Paul Kinsey who has joined the Hare Krishnas. Lane takes drastic and unethical measures to get out of financial trouble. Don spends an afternoon with Joan to get her mind off her marital problems.', 48, '2012-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 11, 'The Other Woman', 'Pete asks Joan to make a personal and moral sacrifice to ensure the company lands the Jaguar account. Don becomes furious after learning of the impact Megan''s new profession will have on their life. Feeling unappreciated, Peggy attends lunch with Freddy Rumsen, who encourages her to make a move.', 48, '2012-05-27');
