INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0804503')) AND numero_temporada = 5), 13, 'The Phantom', 'Roger seeks to expand his affair with Megan''s mother. Pete has a "last" encounter with Beth with lasting repercussions. Megan struggles to find acting work and asks for Don''s help getting an audition. Peggy still seeks Don''s approval.', 48, '2012-06-10');
