INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 1, 'Pilot', 'While on assignment, agent Michael Westen gets a "Burn Notice" and becomes untouchable. Having no idea what or who triggered his demise, Michael returns to his hometown, Miami, determined to find out the reason for his sudden termination.', 67, '2007-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 2, 'Identity', 'Michael helps Madeline''s friend retrieve money from a swindler, and in return he receives information about some visitors that came to his mother''s home.', 45, '2007-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 3, 'Fight or Flight', 'A drug dealer is witnessed brutally beating up a man by a single mother. Oleg asks Michael to help the woman, Cara, his best waitress, after she stops showing up for work.', 45, '2007-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 4, 'Old Friends', 'Michael''s friend, Bill, asks for the spy''s help in freeing his daughter from a prostitution ring. Meanwhile, Michael dodges multiple assassination attempts.', 45, '2007-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 5, 'Family Business', 'Michael takes on arms dealers for an airport worker, while Nate obsesses about the car and their dad''s will together.', 45, '2007-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 6, 'Unpaid Debts', 'Michael discovers a surprise aboard a boat he has retrieved from Jamaican gangsters. Meanwhile, a CSS agent urges Michael to stop his investigation into who burned him.', 45, '2007-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 7, 'Broken Rules', 'Michael works to rid a community in little Havana of a crime boss, all the while baiting Jason Bly at the risk of his family and friends.', 45, '2007-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 8, 'Wanted Man', 'With Michael''s assistance, Fiona helps a man who has been framed for the theft of an expensive brooch.', 45, '2007-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 9, 'Hard Bargain', 'A slightly dim house sitter''s fiancée has been kidnapped, and Sam guilts Michael into a rescue while he''s negotiating with a D.C. bureaucrat to stop the burn notice.', 45, '2007-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 10, 'False Flag', 'Michael is hired to track down a woman''s estranged husband, who has disappeared with their son. Michael soon finds himself pitted against somebody just as skilled and dangerous as he is.', 45, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 11, 'Dead Drop (1)', 'Sam takes on a case for a woman named Gillian, who is being blackmailed into using her security clearance to help smuggle heroin into the United States. Meanwhile, Michael is busy trying to arrange a meeting with Philip Cowan.', 45, '2007-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 1), 12, 'Loose Ends (2)', 'Michael must rescue Sam from heroin smugglers, who happen to be ex-Special Forces, while also evading agents who are out to get him.', 45, '2007-09-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 1, 'Breaking and Entering', 'Having been recruited by the people who burned him, Michael''s new handler, Carla, tasks him with helping a computer tech, whose wife and daughter were kidnapped, liberate some information that is guarded by mercenaries.', 45, '2008-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 2, 'Turn and Burn', 'While Michael''s new handler asks him to locate a Tunisian counterfeiter, Sam asks him to help a woman who says she is being stalked by a drug dealer, and his mother asks him to join her in seeing a therapist.', 45, '2008-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 3, 'Trust Me', 'Andy, a cell-phone salesman, was conned into investing in a fake Cuban nightclub. Michael helps Andy when the people he borrowed the money from come knocking.', 45, '2008-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 4, 'Comrades', 'Michael helps a Russian woman, Katya, whose sister was smuggled into the U.S. by gangsters; however, Katya cannot afford their extortionate demands and her sister is being held captive.', 45, '2008-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 5, 'Scatter Point', 'Michael poses as a safe cracker to help out a reformed ex-con who is unwillingly part of a heist, and tries to sneak into the heavily-guarded office of his handler. Meanwhile, Sam gets an unexpected proposition from his girlfriend.', 45, '2008-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 6, 'Bad Blood', 'When someone''s suspected of embezzling from a hip-hop mogul''s charity, Michael attempts to trick the thief into stealing a larger sum.', 45, '2008-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 7, 'Rough Seas', 'Michael is hired to track down nearly a million dollars worth of pharmaceuticals that were stolen by thieves on their way to Tanzania.', 45, '2008-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 8, 'Double Booked', 'Michael and Sam discover the location of Bill Johnson (Joe Kimble) by going through his trash and finding laundry bluing, a staple among spies to prevent snooping in trash. Michael returns to his loft to find Larry Sizemore (Tim Matheson), a former mentor of Michael''s. Larry offers Michael $20,000, but then Michael raises it to $30,000, to kill a nurse named Jeannie (Amy Pietz) who stands to gain a lot of money when her ailing husband dies. Michael and Fiona track down Jeannie and inform her that Drew (Zachery Ty Bryan), her stepson, has placed out a bounty on her head. Michael protects Jeannie by faking her poisoning, aided by Fiona''s new boyfriend, Campbell (Gary Weeks), a paramedic. Larry kills Drew to cover his tracks and leaves Miami. Michael and Sam follow Bill Johnson into a building and find out that Carla has been using Michael for tactical support for an unknown operation. Michael had collected the ID card for entry into the building (Episode 2), and the rifle that sniper Bill Johnson would be using. Michael also attends family counseling with his mother.', 45, '2008-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 9, 'Good Soldier (1)', 'Hired by Fiona''s boyfriend''s friend Henry, Michael poses as a disgruntled bodyguard to thwart a kidnapping plot masterminded by a ruthless man named Lesher.', 45, '2008-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 10, 'Do No Harm (2)', 'Michael prevents a man from committing suicide, whose son suffers from a heart condition. He had lost his savings in a scam after investing in a "miracle drug" for his son, so Michael decides to get him his money back.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 11, 'Hot Spot', 'Sam calls in a favor and asks Michael to talk to Sean Martin, a football coach who helps impoverished kids. Sean wants Michael''s assistance helping one of his players, Corey Jensen, who''s being targeted by gangsters.', 45, '2009-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 12, 'Seek and Destroy', 'Michael, under the alias of Miles Parker, is hired by Scott Chandler to investigate strange activity - log-ins at odd hours, unusual computer activity and telephone bugging - at an art gallery. But after being attacked by the the gallery''s receptionist, Michael finds himself working against Chandler.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 13, 'Bad Breaks', 'A federal agent with a knack for giving Michael trouble returns to Miami to force Michael to hand over blackmail materials; the two enemies must work together during a bank robbery.', 45, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 14, 'Truth & Reconciliation', 'Michael takes on a sympathy case for a Haitian man whose daughter was murdered by a corrupt government official he believes is hiding in Miami. Michael gets closer to tracking down the person who tried to kill him.', 45, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 15, 'Sins of Omission', 'Michael''s ex-fiancé seeks the spy''s help in freeing her son, who was kidnapped by a disillusioned ex-spy named Brennen.', 45, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 2), 16, 'Lesser Evil', 'Michael gets to know Victor''s motivation and his connection to Carla after capturing him. When the truth about Carla''s organization is revealed, everyone is put in danger.', 45, '2009-03-05');
