INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 2, 'Question and Answer', 'Michael faces a new foe in Detective Paxson, who has tracked down some explosives Michael has been hiding in a storage facility, forcing Michael to surreptitiously get them out before Paxson gets a warrant.  Meanwhile, Michael and team must rescue a kidnapped child by using reverse interrogation.', 45, '2009-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 3, 'End Run', 'Arms trader Brennen returns and kidnaps Nate, forcing Michael to help him pull off an elaborate heist. Michael must also contend with Paxson''s ongoing investigation.', 45, '2009-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 4, 'Fearless Leader', 'Michael gets a hold of a crime lord who seems to be the prime suspect in a Miami PD investigation, so he wants to hand him over in return for being left alone.', 45, '2009-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 5, 'Signals and Codes', 'A paranoid mathematician enlists Michael''s help to stop the vice president of a defense firm from selling company secrets; Michael tracks down a new contact in the intelligence community.', 45, '2009-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 6, 'The Hunter', 'When he hears about an operative from his past who is hunting him, Michael turns to a prominent member of Miami''s underworld for help; a man approaches Michael with an offer.', 45, '2009-07-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 7, 'Shot In The Dark', 'Michael convinces an abusive stepfather of a young boy to leave town by telling him he is the target of an assassination plot. Elsewhere, Strickler makes a promise to Michael that he will help him get back into the intelligence community if they can work together.', 45, '2009-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 8, 'Friends Like These', 'Barry enlists Michael''s help in tracking down his money-laundering client list, which has been stolen by a vicious thief. Michael goes after the thief, only to find that there''s a lot more to the situation than he realized. Fiona tries to be supportive of Michael''s efforts to reconnect with the intelligence community, but she and Michael find that their differences on the subject may not be reconcilable.', 45, '2009-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 9, 'Long Way Back', 'A dangerous man from Fiona''s past resurfaces in Miami after years of hiding, with deadly intentions. Teaming up with Fiona''s ruthless brother, Michael will do whatever it takes to save her... even if that means crossing a few lines.', 45, '2009-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 10, 'A Dark Road', 'When a recently widowed woman hires Michael and Fiona to get her away from a group of violent con men, Michael turns to Madeline for help — but he may ask her to go too far. Meanwhile, a mysterious contact goes to extreme lengths to get Michael''s attention.', 45, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 11, 'Friendly Fire', 'When Sam gets an unexpected visit from a former Seal buddy asking for help, Michael must infiltrate a protected urban barrio and hunt down a child predator. Michael also befriends a psychotic former spy runner in order to learn more about his destructive plans while in town.', 45, '2010-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 12, 'Noble Causes', 'Michael is caught off guard by a visit from his drug dealing neighbor Sugar. But to Michael’s surprise, Sugar isn''t looking for trouble; He needs Michael''s help fending off a crew of notorious thieves. Meanwhile, Michael struggles with working beside an unexpected partner.', 45, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 13, 'Enemies Closer', 'When Michael''s old acquaintance Larry shows up unannounced, it is up to Michael to clean up his mess. Meanwhile, Michael''s brother Nate shows up with his new wife Ruth.', 45, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 14, 'Partners in Crime', 'Sam convinces Michael to investigate a robbery at a chic fashion house, but they quickly realize the world of design isn''t always pretty. Meanwhile, Michael and Fiona gain the trust of a Polish intelligence officer to get information on an unlisted "black flight," transporting dangerous cargo.', 45, '2010-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 15, 'Good Intentions', 'Fiona deals with a paranoid kidnapper who''s hiding a secret. Elsewhere, Michael tries to take down a black operative, but the mission soon gets out of control.', 45, '2010-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 3), 16, 'Devil You Know', 'International fugitive Simon is loose and Michael''s on the run from the FBI for his role in Simon’s escape. When Simon confronts Michael and threatens to blow up a Miami Beach hotel, Michael must call on his friends and an old enemy to help him avoid disaster and put Simon back in the dark hole where he belongs.', 45, '2010-03-04');
