INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 6), 15, 'Best Laid Plans', 'Michael brokers a deal selling an expensive piece of technology to a ruthless thief, but things become complicated when Sam is dragged in as part of a high stakes robbery. Meanwhile, Madeline goes to Barry to ask for a dangerous favor.', 45, '2012-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 6), 16, 'Odd Man Out', 'Michael seeks refuge in a warehouse when he''s caught in the middle of a smuggler''s attempt to get revenge on his former client. Survival becomes a challenge as supplies run low and the exits are blocked.', 45, '2012-12-13');
