INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 1, 'New Deal', 'Michael''s deal with the CIA sends him to the Dominican Republic to infiltrate a terrorist organization headed by an old contact. Sam, Fiona, and Jesse try to move on with their lives, but are drawn back in when someone starts asking questions about Michael''s whereabouts. Maddie tries to get custody of her grandson.', 45, '2013-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 2, 'Forget Me Not', 'Michael returns to Miami to track down someone who is trying to blow his cover; Michael is forbidden from contacting his crew.', 45, '2013-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 3, 'Down Range', 'Sam and Jesse travel to the Dominican Republic to help Michael with a high-stakes trade; Fiona intervenes when a bookie tries to extort Madeline.', 45, '2013-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 4, 'Brothers in Arms', 'Michael tries to learn about Burke''s underground network; Fiona and Madeline must frame a corrupt Russian bureaucrat for treason.', 45, '2013-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 5, 'Exit Plan', 'Michael meets a former Russian operative who now works as part of Burke’s mysterious organization. In order to get out of Cuba, they’ll have to outwit a bloodthirsty counterintelligence expert who’s locking down the island. Strong convinces Fiona to help Michael’s mission by making her an offer she can’t refuse.', 45, '2013-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 6, 'All or Nothing', 'Michael and Fiona pose as hackers at a malicious programming syndicate in order to steal information for Sonya. But Michael’s life gets complicated when working with Fiona again brings back painful memories. Meanwhile, Sam and Jesse help Barry track down a former girlfriend in exchange for falsified documents.', 45, '2013-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 7, 'Psychological Warfare', 'Michael finally meets with the head of the organization he’s been assigned to dismantle, but things get dicey when the leader drugs him at gunpoint in order to learn his deepest secrets. In danger of exposing his cover, Michael soon realizes that in order to protect his future... he''ll have to face his past first.', 45, '2013-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 8, 'Nature of the Beast', 'Michael goes after a drug smuggler at the bidding of the organization he''s trying to infiltrate. Elsewhere, Fiona, Jesse and Strong visit a mental hospital in a search for more information about James.', 45, '2013-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 9, 'Bitter Pill', 'The team look for an antidote at the manufacturer''s lab in order to save a poisoned Middle Eastern diplomat. Elsewhere, Madeline takes action when she suspects she''s being followed.', 45, '2013-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 10, 'Things Unseen', 'When Michael discovers an old friend digging up secrets that could expose his cover, he must decide just how far he will go to protect the mission. Meanwhile, Sam and Jesse are thrust in the middle of a street war involving a decade-old murder after Fiona’s boyfriend is targeted by a coldblooded gang member.', 45, '2013-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 11, 'Tipping Point', 'As Michael becomes ever more conflicted with his mission, he travels to Mexico with Sonya in order to help James with an important job. Anxious to finish the operation, Strong hires freelance mercenaries to extract James on site... but brings along an unexpected guest.', 45, '2013-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 12, 'Sea Change', 'Michael must expose his identity to James and Sonya. Meanwhile, Fiona, Sam and Jesse form a plan to retrieve Michael.', 45, '2013-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0810788')) AND numero_temporada = 7), 13, 'Reckoning', 'Michael must regain the trust of those closest to him in order to finish what he started.', 45, '2013-09-12');
