INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')), 1, 'Genesis', 'A genetics professor. A hospice nurse. A single mom. A street cop. A small town cheerleader. A tormented artist. A computer geek. From places as divergent as Tokyo, India, New York City and Odessa, Texas — they appear to be ordinary people. But they''re beginning to find out they''re not like everyone else. In fact, they''re meant for something much more... Heroes tells the fascinating story of people discovering remarkable abilities — to transport through time and space, to hear another''s thoughts, to be physically indestructible, to paint the future. Each must contend with their unique power. And as they struggle to make sense of what and why all this is happening, destiny will ultimately bring them together to change our world.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 1, 'Genesis', 'As a total eclipse casts its shadow across the globe, a genetics professor in India is led by his father''s disappearance to uncover a secret theory -- there are people with super powers living among us. A young dreamer tries to convince his politician brother that he can fly. A high school cheerleader learns that she is totally indestructible. A single mother struggles to make ends meet to support her young son and discovers that her mirror image has a secret. A gifted artist, whose drug addiction is destroying his life and relationship with his girlfriend, can paint the future. And in Japan, a young man develops a way to stop time through sheer will power. Yet, unbeknownst to them all, their ultimate destiny is nothing less than saving the world...', 53, '2006-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 2, 'Don''t Look Back', 'Outside a bizarre, gruesome crime scene, Los Angeles beat cop Matt Parkman is the only one who can hear the cries of a missing little girl. Claire almost reveals her secret ability to the entire school after learning that her injury attempt tape has disappeared. Thinking she''s going crazy, Niki loses another block of time after waking to find some brutally murdered thugs in her garage, only to be confronted by Social Services about son Micah. While office drone Hiro investigates New York, Nathan confronts Peter following his plunge off a building.', 43, '2006-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 3, 'One Giant Leap', 'As the "Heroes" continue to test their newfound extraordinary abilities, Claire tries to maintain a normal social life when a romance with the football quarterback takes a tragic turn. While Hiro convinces his friend that they are destined to travel to America to save the world, a frightened Niki follows instructions from a mysterious, unknown source that directs her to the middle of the desert.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 4, 'Collision', 'Suresh finally tracks down one of his father''s fabled genetically advanced "supermen." In Las Vegas, Hiro''s plan backfires when he cautiously turns time to his advantage at the gambling tables. Niki''s mafia debtors use their leverage to their benefit in a more elaborate scheme, while Nathan pays a personal visit to a wealthy Vegas contributor to raise additional campaign funds. Following a tragic turn at a bonfire, Claire''s uncanny healing abilities are put to the ultimate test, but according to Issac''s paintings, her future could be fraught with even more peril
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 5, 'Hiros', 'Confused after losing track of another block of time, Niki finds the police on her doorstep, searching for her fugitive husband D.L. Hawkins. Claire confesses to her father. Hiro and his friend get jumped by some Vegas high-rollers. Peter receives a life-changing message from an unlikely source.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 6, 'Better Halves', 'Hiro and his buddy embark on their heroic journey to New York, when they are stopped by a Vegas high-roller who offers them a deal they can''t refuse. As Noah Bennett sets up a meeting for his daughter Claire with her biological parents, she hopes that questions about her newfound indestructibility can be answered.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 7, 'Nothing to Hide', 'Facing a crisis involving her son Micah, a distraught Niki reveals her recent personal struggles to a friend. Pushing aside his own issues at home, Matt assists Audrey''s investigation into another bizarre murder, but their pursuit of mysterious serial killer Sylar takes an unexpected turn. After failing to act like a "superhero" when faced with danger, Hiro questions his heroism. Nathan and his wife Heidi strategize how to win the congressional election. Claire is shocked to learn where her missing tape wound up.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 8, 'Seven Minutes to Midnight', 'Back in India to mourn the passing of his father, Suresh encounters mysterious dreams of the past that force him to question what path to take next. Continuing their journey to New York, Hiro and Ando stop at a diner and meet someone interesting. In crisis, Niki comes to a personal understanding. Determined to see one of Isaac''s paintings that Simone recently sold, Peter asks Nathan for help in finding a key to the future. Intent on getting back to her normal life, Claire focuses on Homecoming preparations, unaware of what''s to come.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 9, 'Homecoming', 'As Mr. Bennet tries to protect his daughter by any means, Claire''s high school Homecoming celebration turns into a frightening night for many. Nathan and Simone work together to find Isaac''s painting for Peter, but this key to the future could lead to tragedy.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 10, 'Six Months Ago', 'As the clock turns back six months for all of the "Heroes," Mohinder''s father Chandra Suresh arrives in New York to begin his quest to find individuals with extraordinary abilities, and meets someone all to eager to be special. Peter celebrates his graduation from nursing school, and learns that Nathan plans to prosecute a case that could mean trouble for the entire Petrelli family. A surprise visit from her father brings out the worst in Niki. Hiro attempts to be a hero and change the future for someone important. Claire joins the cheerleading squad and makes a curious discovery. Mr. Bennet and the Haitian meet someone special.', 43, '2006-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 11, 'Fallout', 'The tragic events in Texas have sad, serious repercussions for many of the "heroes," their families and friends. Meanwhile, shocking details about the moments leading up to Isaac''s predicted New York City nuclear bombing are revealed. Later, Issac''s newest painting has fascinating future implications for a hero in crisis. Suresh takes the first steps along his new path. Matt and F.B.I. Agent Audrey Hanson pursue a break in the Sylar case. Horrified by Jessica''s recent actions, Niki makes a tough decision to protect her family.', 43, '2006-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 12, 'Godsend', 'Matt reveals his abilities to his wife. HRG confers with Mohinder. Now that she knows the truth, Claire tries to make sense of her life. Hiro seeks the sword that he is destined to own. Niki must face the consequences of her decision to turn herself in to the police. Simone and Nathan are worried about Peter, who has been in a coma for two weeks. Peter meets a new hero. Micah visits his mother.', 43, '2007-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 13, 'The Fix', 'Hiro continues to search for a sword while being chased by mysterious figures.  An invisible man named Claude has something to teach one of the heroes. D.L. takes on new family responsibilities, and Matt opens up to his wife. H.R.G. continues to focus on the captive Sylar. Claire seeks out the Haitian and then her birth parents. Mohinder looks for those on the list, and receives a surprise visitor.  A psychiatrist offers to help Niki.', 43, '2007-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 14, 'Distractions', 'Hiro deals with explaining his new heroic path in life to his ambitious sister and tycoon father. Niki has the chance to reunite with D.L and Micah. Claude''s mentoring of Peter leads Peter to question those closest to him. Claire goes to a trailer park looking for her birth mother. Sylar wears a disguise and makes a move against HRG.', 43, '2007-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 15, 'Run!', 'Matt enters the private security business and receives an objectionable client. Suresh finds another person on the list. As her home-life worsens, Claire strives to learn more about her birth parents. Hiro and Ando get sidetracked in Vegas again while searching for the sword. Nathan is forced to deal with a secret from his past. Still indebted to Mr. Linderman, Jessica resorts to unsavory methods that could spell doom for a fellow hero.', 43, '2007-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 16, 'Unexpected', 'Peter learns that he and Claude may have been betrayed. Matt''s reunited with the radioactive Ted Sprague and Hana Gitelman a woman with "wireless" mental abilities. Hiro makes a tough choice about his mission. Claire can no longer hold back her anger towards HRG.', 43, '2007-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 17, 'Company Man', 'H.R.G.''s past catches up to him as Matt and Ted Sprague come to Texas looking for answers, and take him, his wife, son and Claire hostage -- leading to a tragic, explosive showdown.', 43, '2007-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 18, 'Parasite', 'With the election and New York City''s destruction looming, Nathan has a disturbing face-to-face meeting with the shadowy Linderman. Hiro''s attempt to steal the sword steers him into a grim new direction. Suresh makes a breakthrough on the list—at great cost. D.L. begins to suspect all is not well at home. Isaac paints his most terrible painting yet. New hero Candice Wilmer makes an illusive debut.', 43, '2007-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 19, '.07%', 'After "helping" Suresh search for more people with special abilities, Sylar''s rampage continues with two "heroes" being confronted by the stronger-powered serial killer. Nathan must factor what he''s learned from Linderman into difficult decisions that will shape the future, for him, his family, New York City and the world.', 43, '2007-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 20, 'Five Years Gone', 'Hiro and Ando''s trek into the future leads them to meet some of the heroes as they are five years later, after the nuclear fallout. This includes a darker side of Matt, a Jessica/Niki with a clear winner in their battle, a brown-haired Claire, and a man named Andy, who''s a big hearted Texan. It also features an event at an upscale gentleman''s club.', 43, '2007-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 21, 'The Hard Part', 'Hiro and Ando''s determination is put to the test. Nathan wants to win the election and he''s taking drastic measures to ensure that he will. This episode will feature Sylar, his home life, and where he came from. Jessica and D.L. discover some of the stuff that Linderman wants from them and Micah. Also there is a new hero who is supposed to be holding the key to stopping Sylar.', 43, '2007-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 22, 'Landslide', 'Poised to become a member of Congress and maybe more, Nathan considers the cost to those he loves, along with his mother''s advice and Linderman''s prophecy. As he prepares to face Sylar to the death, Hiro learns of his lineage from his father. While various "heroes" fatefully arrive in New York City, Peter and Claire attempt to leave the city before the foretold explosion. H.R.G.', 43, '2007-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 1), 23, 'How to Stop an Exploding Man', 'Can Sylar be stopped? Will Linderman''s vision live on with Nathan? What will it take for Peter to save the world, what sacrifices will be made? With all the horrible predictions unfolding before them the heroes face moments of pain and peril in Kirby Plaza.', 43, '2007-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')), 2, 'Generations', 'Season 2 introduces new stories — and new heroes — following the apocalyptic showdown in New York City. Claire has moved with her family to Southern California in order to hide her indestructible abilities and there she encounters a young man with a secret of his own. Matt gains new authority in tracking down a murderous force stalking the Heroes, while Suresh uncovers a virus that could eradicate them all. As each sensational chapter unfolds, there is no resisting the extraordinary.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 1, 'Four Months Later...', 'Four months after the events of the showdown between Sylar and Peter, new Heroes emerge. These include brother and sister Alejandro and Maya. Hiro remains in the past, but what will come of this? Someone dies and someone isn''t dead. Claire and her father and the rest of their family get a new life.', 43, '2007-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 2, 'Lizards', 'Peter falls in with Irish gangsters who know about his past. Hiro works to contain the damage caused by his journey into the past. Kensei''s power will be revealed. Suresh locates and cures the Haitian. Matt investigates the murder of Mr. Nakamura. West comes to know of Claire''s powers. Maya and Alejandro enter Mexico and find their powers more of a hindrance than a help.', 43, '2007-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 3, 'Kindred', 'Suresh finds an undiscovered Isaac Mendez painting that shows someone''s death; Maya frees Alejandro from a Mexican jail; in the past Hiro discovers something new about Kensei; and Niki and Micah leave Las Vegas to get away from their past. Claire and West take a little trip.', 43, '2007-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 4, 'The Kindness of Strangers', 'Monica starts to exhibit new abilities while working with Micah, Nana, and Damon. Nana is the grandmother of Micah, Monica, and Damon. They all currently reside in New Orleans. Matt asks Molly to locate the man in her dreams. He may be the newest threat to the Heroes. Maya and Alejandro continue their trek to the U.S. Both Claire and her father are suspicious of one another. Angela reveals a lot of her secrets.', 43, '2007-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 5, 'Fight or Flight', 'A woman named Elle is searching for Peter. Ando looks for Hiro in the past. Matt looks for the man in Molly''s dreams. HRG takes another step in hopes of protecting his family and himself.', 43, '2007-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 6, 'The Line', 'Peter goes on a search. West convinces Claire to stand up to someone. Hiro struggles with his feelings for Yaeko. Suresh has more problems with the Company. HRG tries to locate more of Isaac''s paintings. Alejandro doesn''t trust Sylar.', 43, '2007-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 7, 'Out of Time', 'Peter and Caitlin learn about the endstage effects of the Heroes virus. Many of the Heroes work together to fight the Nightmare Man.  West is shocked to the identity of Claire''s father.  Hiro and Kensei''s journey comes to an end.', 43, '2007-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 8, 'Four Months Ago...', 'The events of the "missing four months" are explored. Maya and Alejandro must go on the run, it is explained how Peter ended up in Ireland and what happened to Nathan, Nikki, and D.L.', 43, '2007-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 9, 'Cautionary Tales', 'Mr. Bennet prepares to move his family when he thinks the Company has found them, but Claire doesn''t like the idea. Hiro returns to the present and upon discovering his father''s death, travels back in time to stop it. Meanwhile, Matt works to master his new mental abilities.', 43, '2007-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 10, 'Truth & Consequences', 'Peter travels to Primatech in Texas to destroy the virus, but not everything is what it seems. Hiro continues the pursuit of his father''s killer, while Matt pursues the last Company member in the photo. Nikki is reunited with Micah but has bad news, while Maya has to choose to remain with Alejandro, or go with Sylar.', 43, '2007-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 2), 11, 'Powerless', 'In Texas, Peter faces off against former friends due to Adam’s misleading story about the Shanti virus. Micah enlists the help of his mother to rescue Monica. Maya is shocked when she learns the truth about her new friend Sylar. Elle tries to make her father proud.', 43, '2007-12-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')), 3, 'Villains / Fugitives', 'In season 3, a shocking revelation suddenly divides our heroes and, as a cadre of villains is unleashed upon the world, its Heroes are called to their greatest quest yet.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 1, 'The Second Coming', 'After a look into the future, Nathan''s shooter is revealed. Matt chases him and winds up in a desert. Hiro receives an important message from his father. Sylar visits Claire. Maya gives Mohinder an idea for his research. Nathan recovers and gets a visit from Linderman.', 43, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 2, 'The Butterfly Effect', 'Sylar goes to the Company and inadvertently releases 12 super-powered criminals in a fight with Elle. Future Peter tries to fix his mistake. Angela takes over the company. Claire learns more about her powers. Hiro and Ando travel to Paris to track down the speedster who robbed them. Maya discovers that Mohinder''s injection has changed him. Matt meats Usutu, an African with a familiar power.', 43, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 3, 'One of Us, One of Them', 'HRG and his new partner go to a local bank heist with four villains; including Peter being trapped in one of them. Hiro and Ando track Daphne to Germany, and meet the Haitian. Tracy Strauss goes to New Orleans to find out more information about Niki. Meredith teaches Claire a lesson about fighting. Usutu shows Matt a series of paintings about him.', 43, '2008-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 4, 'I Am Become Death', 'Peter travels to the future and adopts a dangerous ability in order to try to save the world. Meanwhile, Mohinder struggles with his continuing evolution from the formula, and Hiro and Ando re-unite with an old enemy.', 43, '2008-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 5, 'Angels and Monsters', 'Claire decides to take on one of the villains herself, but she may not be as invulnerable as she believes. Nathan and Tracy search for the truth about their origins. Maya makes a shocking discovery. Hiro and Ando look for help in the most unlikely places.', 43, '2008-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 6, 'Dying of the Light', 'Villains Knox and Daphne are on a quest to recruit Hiro and others to the Pinehearst fold. Angela and the Company are paralyzed from recent events. Peter goes to Pinehearst searching for answers but is stunned to learn who the founder is. Claire and Sandra go on a mission to save Meredith from the clutches of Doyle, a villain with abilities to control people mentally and physically. Nathan and Tracy try to trace their origins with Mohinder''s help.', 43, '2008-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 7, 'Eris Quod Sum', 'Trapped, Nathan and Tracy must fight to save their lives against Suresh, who has changed dramatically. Elle returns with shocking news for Claire and her family. Meanwhile, Angela tries to convince Sylar to save Peter; Daphne is ordered to kill Matt or she will be killed herself; and Hiro questions Usutu''s advice.', 43, '2008-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 8, 'Villains', 'Hiro attempts to delve into Arthur Petrelli''s past to uncover the mystery behind him creating a rival company Pinehearst and his hatred towards Angela. Sylar stricken by guilt tries to stop his murderous ways with HRG and Elle vying for his blood. Meredith''s training goes up in smoke with the arrival of her brother.', 43, '2008-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 9, 'It''s Coming', 'Nathan learns of his father''s plans, while Flint and Knox launch attacks on Hiro, Ando, Peter, and Claire. Meanwhile, Matt tries to revive Angela, Sylar meets with Elle, and Mohinder begins testing of his newest superpower formula.', 43, '2008-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 10, 'The Eclipse (1)', 'The eclipse plays havoc with the heroes'' powers. Arthur orders Elle and Sylar to bring in Claire. Hiro, Ando, and Matt follow Daphne to her hometown to learn what hold Arthur has on her, and Peter and Nathan travel to the Haitian''s hometown to recruit him for the war with Pinehearst.', 43, '2008-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 11, 'The Eclipse (2)', 'The eclipse continues to create chaos. Sylar and Elle face HRG''s wrath. Peter, Nathan and the Haitian go up against Baron Samedi. Ando, Sam, and Frack try to help Hiro with his memory loss.', 43, '2008-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 12, 'Our Father', 'In order to stop Arthur, Hiro and Clair team up and travel back in time to when Kaito gave Claire to H.R.G. Meanwhile, Peter and the Haitian head out to stop Arthur, but are stopped by Sylar and Suresh has a breakthrough with the formula.', 43, '2008-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 13, 'Dual', 'Following the showdown against Arthur, Nathan and Peter find themselves pitted against one another, and Nathan makes a decision that will have an effect on the entire world. Meanwhile, Sylar holds Claire, H.R.G., Meredith and Angela hostage at Primatech; Ando, Matt and Daphne try to rescue Hiro and find their only hope may lie in Suresh.', 43, '2008-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 14, 'A Clear and Present Danger', 'Three weeks after the destruction of both Primatech and Pinehearst, and the death of Arthur Petrelli, the now-villainous Nathan returns with a vengeance by persuading the U.S. President and the government to round up all people with abilities, leading to Claire, Ando, Hiro, Matt, Peter, as well as Tracy to become fugitives from the people who were their former allies.', 43, '2009-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 15, 'Trust and Blood', 'Following a chain of unexpected events, our Heroes are on the run from their latest adversary and one of their own, Nathan Petrelli. After Matt paints a series of prophetic images, the tragic fate of someone close to him is revealed. Elsewhere, Sylar continues his search for his father and encounters a young outcast with information and an ability of his own.', 43, '2009-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 16, 'Building 26', 'Nathan''s plans face exposure as Homeland Security begins an investigation under direct orders from the President of the United States. Sylar and Luke embark on a road trip to find Sylar''s father, but are secretly being hunted by Nathan''s agents. Life gets complicated for the Bennet family as Claire goes into action to protect a young man with abilities from being captured by HRG. Elsewhere, Matt''s prophetic images lead Hiro and Ando to India and a mysterious ally comes to the aid of our Heroes', 43, '2009-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 17, 'Cold Wars', 'While being held hostage, HRG is subjected to Matt Parkman''s unique brand of interrogation, revealing how he became involved with Nathan''s government plot to capture those with abilities. Meanwhile, Matt''s discoveries bring Peter face-to-face with "The Hunter"', 43, '2009-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 18, 'Exposed', 'After receiving a tip from "Rebel", Matt and Peter race to Building 26 to rescue Daphne and recover files that will expose the government''s plans for those with abilities. Claire finds help from an unlikely source in smuggling Alex out of the city. As Sylar and Luke continue their road trip, Sylar begins to have memories of his father that lead him to the truth about his mother. Meanwhile, "The Hunter" puts his own agenda into action with an explosive surprise for one of our heroes.', 43, '2009-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 19, 'Shades of Gray', 'When Sylar comes face-to-face with his long lost father, the reunion proves to be what he least expected. Elsewhere, after receiving a tip from "Rebel", Claire must decide if she will help her sworn enemy, Eric Doyle, evade capture. Meanwhile, as "The Hunter" plans to uncover the Petrelli family''s secrets and take control of Nathan''s operation, Matt finds himself in the spotlight and on the verge of leveling Capitol Hill.', 43, '2009-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 20, 'Cold Snap', 'HRG convinces Emile Danko, a.k.a. "The Hunter", to release Tracy from Building 26, in hopes that she will lead them to "Rebel". As Angela evades capture, she turns to an old friend for help. In Los Angeles, Hiro and Ando continue on their latest mission from "Rebel" to protect the newest hero.', 43, '2009-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 21, 'Into Asylum', 'Now that Nathan’s ability has been revealed and he has lost control of his operation, he and Claire go into hiding in Mexico. With Emile Danko now in control of the government operation, his plan to destroy everyone with abilities is set into motion as he teams up with an unlikely partner. Meanwhile, Angela and Peter seek refuge in a church and begin to mend their broken relationship.', 43, '2009-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 22, 'Turn and Face the Strange', 'As Danko spearheads the government operation, someone close to him is put in the line of fire. HRG’s life continues to spiral out of control and his marriage is dangerously close to the breaking point. Meanwhile, Hiro and Ando continue their road trip with a special delivery for Matt Parkman. Elsewhere, Angela Petrelli unearths the demons of her past.', 43, '2009-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 23, '1961', 'As Nathan, Claire, Peter and H.R.G. help Angela uncover her past, she reveals the dark secrets that have haunted her for years. Meanwhile, Mohinder learns of his father’s involvement in a long forgotten government operation.', 43, '2009-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 24, 'I Am Sylar', 'Sylar continues his unusual partnership and begins to have an unexpected identity crisis. Hiro and Ando take measures toward bringing down Building 26. Meanwhile, Matt’s new found fatherhood changes his priorities. Elsewhere, Nathan sets a plan in motion to right the wrongs of his government operation.', 43, '2009-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 3), 25, 'An Invisible Thread', 'Nathan faces off against Sylar to keep him from meeting the President. Sylar has his own plans for his new partner. Meanwhile, Hiro learns that there are repercussions to regaining his ability. Elsewhere, Matt is forced to go to extraordinary lengths to protect his future with his family.', 43, '2009-04-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')), 4, 'Redemption', 'Season 4 begins with our heroes putting their lives back together. Claire finds that her biggest challenge is forgetting her old life and starting college. Hiro Nakamura goes back to his old life in Japan, but discovers that he has a terminal illness and sets out to fulfill his own personal bucket-list. Peter Petrelli returns to work as an ordinary New York City EMT. H.R.G. is adjusting to life as a single man, but when Mohinder Suresh offers H.R.G. compelling evidence of a new danger, it makes H.R.G. wonder if he should get back in the game. Nathan Petrelli returns to the Senate and begins to notice strange changes in himself. Matt Parkman returns to life as an ordinary family man, but finds something unfamiliar buried deep within his psyche. And a strange and dangerous carnival comprised of a traveling band of outsiders with powerful abilities suddenly poses a grave challenge.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 1, 'Orientation', 'Claire, back home in California, begins attending college, but is having difficulty adjusting when a mysterious death of a student during the orientation puts her back in the spotlight. In Japan, Hiro and Ando continue their quest to help people with abilities and go so much as to advertise themselves. Meanwhile, Angela fears Nathan/Syler will discover his true identity. Matt tries to settle down back in Los Angeles and raise his son and not worry about unexpected visitors. Elsewhere, Peter is using his ability for good when a mysterious carnival clan, led by Samuel Sullivan, arrives in town which could spell trouble for him and everyone else.', 43, '2009-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 2, 'Jump, Push, Fall', 'Claire and her new friend Gretchen investigate the death of Claire''s roommate Annie, while Noah comes to Peter for assistance. Samuel and Edgar recover the compass, Hiro realizes his new destiny, and Matt is tormented with mental images from a dangerous foe.', 43, '2009-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 3, 'Ink', 'Peter faces unexpected consequences for his heroic acts and encounters a reluctant new hero. As Claire continues to adjust to college life, she must figure out how to deal with her ability having been revealed. Meanwhile, Samuel moves heaven and earth to recapture the memories of his late brother Joseph. Elsewhere, Matt struggles with his internal demons as Sylar mysteriously resurfaces.', 43, '2009-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 4, 'Acceptance', 'As "Nathan" starts displaying new powers, he has visions of an incident from his past involving a young girl and decides to investigate. Hiro tries to save a co-worker and learns a truth about himself. Tracy tries to regain her old life and job.', 43, '2009-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 5, 'Hysterical Blindness', 'Samuel prepares for new additions to his family, while Lydia warns him of the consequences. Claire discovers that her roommate Gretchen may have a hidden agenda. Meanwhile, Peter finds an unexpected way to connect with Emma, who would prefer to stay distant. Elsewhere, a different side of Sylar emerges as he desperately tries to remember the person he used to be.', 43, '2009-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 6, 'Tabula Rasa', 'Under Samuel’s guidance, Sylar starts on a path to rediscover his true identity. Hiro helps Emma accept and understand the great possibilities that go along with having an ability. Meanwhile, Peter enlists HRG to help him find a healer who can save Hiro’s life.', 43, '2009-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 7, 'Strange Attractors', 'Matt goes to extreme measures to extinguish Sylar , who continues to torment him. Elsewhere, HRG calls in a favor from Tracy to save a troubled young boy whose misfortunes resemble her own. While Claire and Gretchen are being hazed by their new sorority sisters, they realize pledging might not be their biggest problem.', 43, '2009-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 8, 'Once Upon a Time in Texas', 'When Hiro travels three years into the past, he has a second chance to save Charlie from the hands of Sylar. However, Samuel’s presence serves to complicate Hiro’s mission even further. Elsewhere, H.R.G.’s past with his Primatech partner is revealed.', 43, '2009-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 9, 'Shadowboxing', 'Claire is determined to get to the bottom of the Sorority Rush attacks on her own, until H.R.G. intervenes only to realize he may be the source of her troubles. Meanwhile, Peter''s new ability is a perfect fit for his job and gives him the opportunity to help Emma accept her new life. Elsewhere, Sylar''s battle at gaining full control over Matt''s body escalates with potentially dangerous implications at stake.', 43, '2009-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 10, 'Brother''s Keeper', 'Samuel learns just how powerful he can become and takes dangerous measures to reach his full potential. Meanwhile, as Tracy begins to lose control of her ability, one of her own comes in harms way. Elsewhere, Sylar continues his battle with Matt.', 43, '2009-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 11, 'Thanksgiving', 'H.R.G. hosts an untraditional Thanksgiving dinner. Elsewhere, the Petrelli family gets a surprise guest at their table. Meanwhile, Samuel continues to hold Hiro hostage, as Lydia goes in search for the truth.', 43, '2009-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 12, 'The Fifth Stage', 'Unexpected visitors greet H.R.G.; Samuel''s plan starts to come to fruition; struggling to accept the truth, Peter takes extreme measures to get what he wants; Claire''s journey leads her to an unexpected destination.', 43, '2009-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 13, 'Upon This Rock', 'As Claire becomes immersed into the world of the Carnival, she becomes increasingly suspicious of Samuel''s motives. Hiro is on a mission to rescue one of his own, but has difficulty communicating his intentions to Ando.', 43, '2010-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 14, 'Let It Bleed', 'Sylar returns to the Carnival in search of answers, H.R.G. tries to forge an alliance with Edgar and Peter continues to struggle with the loss of his brother.', 43, '2010-01-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 15, 'Close to You', 'H.R.G. recruits Matt to help him take down Samuel, as they use his long-lost love, Vanessa, to lure him to them, but Samuel has his own plans for Vanessa in the works. Meanwhile, Hiro and Ando go to extreme lengths to save Dr. Suresh. Elsewhere, Peter''s introduction of Emma to his mother brings forth visions of a very grim future.', 43, '2010-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 16, 'Pass/Fail', 'Hiros life hangs in the balance as his brain tumor worsens, prompting him to subconsciously deal with some of his past decisions. Meanwhile, Sylar pays Claire an unexpected visit to get answers as to why he isn''t quite himself. Elsewhere, Samuels plan to impress his long-lost love, Vanessa, takes a terrifying turn.', 43, '2010-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 17, 'The Art of Deception', 'H.R.G. enacts his plan to take down the Carnival with the help of Lauren and Suresh. Sylar visits Matt looking to understand his desire to make a human connection, but Matt has a plan of his own. Meanwhile, Peter warns Emma of Samuel''s intentions after his grim vision of the future.', 43, '2010-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 18, 'The Wall', 'Fueled by his vision of Emma in grave danger, Peter attempts to rescue Sylar from his worst nightmare. At the carnival, Samuel reveals H.R.G.s secret past in order to bring Claire to his side. Meanwhile, Lauren makes a bold move to put a stop to Samuel.', 43, '2010-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0813715')) AND numero_temporada = 4), 19, 'Brave New World', 'Everyone bands together to try to stop Samuel from taking the lives of thousands. Peter joins forces with his most unexpected ally to save Emma. Meanwhile, H.R.G.''s life hangs in the balance as he and Claire find themselves trapped underground with oxygen quickly running out. Elsewhere, Hiro starts to come to grips with the decisions he has made and is called into action to help stop a disaster.', 43, '2010-02-08');
