INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 1, 'Tony', 'Tony''s a smart kid. So smart he believes that he can get his best mate Sid laid... and make a profit.', 45, '2007-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 2, 'Cassie', 'Cassie''s family and friends are too wrapped up in their own worlds to notice that she''s not eating - but there is someone who cares.', 44, '2007-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 3, 'Jal', 'How can Jal come within an ace of winning the Young Musician of the Year competition in the face of total indifference of all those around her?', 44, '2007-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 4, 'Chris', 'Happy-go-lucky party animal Chris wakes up one morning to find his mum''s gone away for a few days and left him a grand. But what do you do after you''ve thrown a party to end all parties and blown all the money?', 45, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 5, 'Sid', 'Sid''s in trouble. Deep trouble. His coursework hasn''t made the grade, he''s grounded, and as sexually frustrated as ever. Will Sid buckle down and focus on his future or will he continue to be hypnotized by his best friend''s girlfriend?', 44, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 6, 'Maxxie and Anwar', 'What happens when two friends suddenly run up against the limits of their friendship? Maxxie and Anwar are about to find out.', 45, '2007-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 7, 'Michelle', 'Time''s up for Tony. His girlfriend Michelle just isn''t going to take it anymore. Nor is she going to take her mum''s latest husband Malcolm; toy boy, business failure and serial idiot to boot.', 45, '2007-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 8, 'Effy', 'Has nobody noticed that Effy, Tony''s little sister, never utters a word? Has nobody ever noticed that she sneaks out at night? Tony has. And Tony doesn''t care about anybody or anything - except his little sister.', 45, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 1), 9, 'Everyone', 'It''s taken quite a lot of time and effort for everyone to fall out with each other. But they''ve worked at it and they certainly aren''t in the mood for apologies. Anwar''s crazy birthday party offers a chance for scores to be settled.', 44, '2007-03-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')), 2, 'Series 2', 'This series follows the lives of sixth form students Tony Stonem, Michelle Richardson, Sid Jenkins, Cassie Ainsworth, Chris Miles, Jal Fazer, Maxxie Oliver, Anwar Kharral and new character Lucy "Sketch".');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 1, 'Tony and Maxxie', 'Maxxie is looking after Tony, but he has his own problems. He desperately wants to leave college and follow his dream to become a dancer, but his dad is giving him hell about it.', 45, '2008-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 2, 'Sketch', 'Maxxie has a creepy feeling that someone is watching him. Someone close by. A hot boy maybe? No such luck! Sketch is Maxxie''s stalker. She''s prepared to do anything to get her man, and if she can''t have him, she''s going to make sure nobody can.', 45, '2008-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 3, 'Sid', 'Sid hasn''t coped at all well with the fact that his best friend Tony is a shadow of the man he was and that Cassie has moved away to Scotland, where as far as he can tell, she is having the time of her life.', 45, '2008-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 4, 'Michelle', 'Michelle''s mum has gone and done it again - another new husband. Before Michelle knows what''s happening, her manipulative new step sister Scarlett is invading her life, co-opting her friends and offering unwanted advice.', 45, '2008-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 5, 'Chris', 'It''s been a long road full of tribulations, drugs, petty theft, non attendance and resounding failure for Chris at college. So when the CCTV cameras catch him shagging Buck Tooth in the science corridor, the director calls time.', 45, '2008-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 6, 'Tony', 'Tony''s world is a strange one. Isolated and alone, he is desperate to find the way back to himself. He tries to act normal, but bumping into Sid and Michelle at a club sends him spiralling again.', 45, '2008-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 7, 'Effy', 'Effy takes care of her depressed mom, tries to restore the relationship between Tony and Michelle, and mentors the new girl at school.', 45, '2008-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 8, 'Jal', 'Jal has a secret so big, she can''t tell anyone until she works out what to do about it. But as revision, music school auditions and needy best friends press down on her, the secret starts to leak out.', 45, '2008-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 9, 'Cassie', 'What''s the matter with Cassie? She''s back together with Sid, Chris is on the mend, Michelle and Tony are back with each other and exams are finally over. But can Cassie be happy?', 45, '2008-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 2), 10, 'Final Goodbyes', 'It''s the day of final report cards, and the friends decide not to look at their grades until they''ve said goodbye to Chris.', 45, '2008-04-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')), 3, 'Series 3', 'This series sees the introduction of a new cast; it follows the lives of sixth form students Effy Stonem, Pandora Moon, Thomas Tomone, James Cook, Freddie McClair, JJ Jones, Naomi Campbell, and twin sisters Emily and Katie Fitch.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 1, 'Everyone', 'It''s the first day of the new term at Roundview College, and best friends Freddie, JJ and Cook''s world collides with Effy''s.', 43, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 2, 'Cook', 'It''s Cook''s 17th birthday, and half the college have been invited to his Uncle Keith''s pub to witness a night Cook believes will go down in history.', 45, '2009-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 3, 'Thomas', 'Thomas arrives in the UK from Congo alone. His family are due to join him in a few days - he must find somewhere for them to live so he moves into an abandoned flat on an estate.', 45, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 4, 'Pandora', 'The first and only boy Pandora''s ever fancied has been deported before she''s got beyond first base. But her lovesickness has to take a backseat when the Jim/Anthea/Steve love triangle is blown open.', 45, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 5, 'Freddie', 'Freddie''s big sister Karen has reached the final of a TV talent show. Freddie is emotionally blackmailed into upholding the story she and her dad are spinning about their dead mother, all to look good in front of the cameras.', 45, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 6, 'Naomi', 'Naomi thinks she''s got her world worked out - but her super smart exterior hides the insecurities beneath, and when the student president elections are announced, it stirs her into questioning what she really wants.', 45, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 7, 'JJ', 'Poor JJ. Everything''s gone pear-shaped since Effy came between his two best friends and split apart his friendship group - but Emily proves to be a true friend in his hour of need.', 45, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 8, 'Effy', 'Effy''s lost her mojo. Mindless sex with Cook no longer satisfies her and things in the Stonem household are becoming intolerable.', 47, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 9, 'Katie and Emily', 'Katie is too humiliated from the incident in the woods to leave the house. Lucky she''s got Emily to bail her out.', 46, '2009-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 3), 10, 'Finale', 'Outlaws Cook and Effy are running wild, clinging to each other and blocking out the rest of the world by getting totally off their faces.', 45, '2009-03-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')), 4, 'Series 4', 'Like the previous series, this series follows the lives of the second generation, which consists of Effy Stonem, Pandora Moon, Thomas Tomone, James Cook, Freddie McClair, JJ Jones, Naomi Campbell, and twin sisters Emily and Katie Fitch.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 1, 'Thomas', 'Thomas experiences a life-changing event, causing him to question everything - his faith, his family and even his choice of friends.', 45, '2010-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 2, 'Emily', 'Emily and Naomi are loved up and enjoying their extended summer of love together. The thorn in Emily''s side is her family. Her mother is unable to accept Naomi as anything other than a bad influence, and is keen for Emily to go travelling alone.', 45, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 3, 'Cook', 'Cook is in prison after what happened at the party. He''s told by his lawyer that he has no choice but to plead guilty... but Cook isn''t willing to accept responsibility.', 45, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 4, 'Katie', 'Katie Fitch has a problem. Katie''s family''s bankrupt, and they''ve got nowhere to live. And under the strain of it all, Jenna and Rob seem to be headed for splitsville and James Fitch is scared.', 44, '2010-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 5, 'Freddie', 'Freddie is loved up. Completely. He and Effy are enjoying their time together and carrying on their hedonistic ways with no thought of tomorrow.', 45, '2010-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 6, 'JJ', 'JJ is in love. Lara Lloyd is sweet perfection and he''s smitten. But JJ thinks she''s way out of his league and lacks the courage to ask her out.', 45, '2010-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 7, 'Effy', 'Effy has been in a psychiatric hospital recovering. After lots of sessions with her counsellor John Foster, he tells her she is ready to go back home.', 45, '2010-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 4), 8, 'Everyone', 'With A-level results in for most of the gang, thoughts about the past and the future are on their minds.', 49, '2010-03-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')), 5, 'Series 5', 'This series sees the introduction of a new cast; it follows the lives of the third generation of characters, which consists of Franky Fitzgerald, Rich Hardbeck, Mini McGuinness, Liv Malone, Alo Creevey, and brothers Nick and Matty Levan.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 1, 'Franky', 'Loner Franky accidentally challenges Mini''s position as Queen Bee. Mini plays the long game and Franky finds herself befriended by the girls.', 45, '2011-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 2, 'Rich', 'Rich uses his taste in extreme music to keep the world, especially girls, at bay. When Alo finds Rich''s perfect woman, Rich is forced to into pairing up with Grace to learn how to chat up girls.', 46, '2011-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 3, 'Mini', 'Mini is under threat. When Grace brings Franky into the charity fashion show, Mini sacks them both, and re-imagines the show in her own image to cement her power.', 48, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 4, 'Liv', 'Mini befriends the gang to isolate Liv. Liv takes off with a boy called Matty, and they take a day out of reality with no consequences or commitments.', 44, '2011-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 5, 'Nick', 'Nick is the star of the school and seems to have everything - he''s hot, he''s the son of a proud father, and he''s a rugby hero. But Matty''s reappearance has unsettled him and old wounds are re-opened.', 45, '2011-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 6, 'Alo', 'Sick of his constant partying and wild ways, Alo''s parents take him out of college and get him to buckle down on the farm. Alo rebels and has a party that ruins the farm, hoping this will show his parents that they can''t keep him trapped there.', 45, '2011-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 7, 'Grace', 'Grace has always believed in fairytales and happy endings, but she is forced to face reality when Rich meets her father.', 46, '2011-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 5), 8, 'Everyone', 'It''s the day of Rich and Grace''s wedding and the fractured gang try and make it a happy day but they''re at each other''s throats.', 45, '2011-03-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')), 6, 'Series 6', 'Like the previous series, it follows the lives of the third generation of characters, which consists of Franky Fitzgerald, Rich Hardbeck, Mini McGuinness, Liv Malone, Alo Creevey, brothers Nick and Matty Levan, and new character Alex Henley.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 1, 'Everyone', 'The gang are on a summer holiday in Morocco! The villa may be half finished, in the middle of nowhere and without running water, but they''ve found a load of weed under the floorboards so they don''t care.', 47, '2012-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 2, 'Rich', 'Professor David Blood has banned Rich from visiting Grace in hospital and it''s killing him. Alo tries to keep Rich out of trouble with band practice, but Rich is committed to his love.', 44, '2012-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 3, 'Alex', 'It''s Alex Henley''s first day at Roundview College, but he doesn''t seem to be worried about fitting in or making new friends.', 46, '2012-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 4, 'Franky', 'Franky is in a bad place - it''s the week of her mock exams and she''s unable to concentrate of her studies. Her friends are avoiding her, while Jeff and Geoff''s attempts at parental support only succeed in making her feel smothered.', 46, '2012-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 5, 'Mini', 'Mini''s mum has a pervy new live-in boyfriend who Mini hates with a passion. To makes matters worse, Alo has broken the rules of their no-strings-attached secret relationship and declared his love for her.', 46, '2012-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 6, 'Nick', 'Nick is desperately in love with Franky, but it''s a one-way street. He has no choice but to accept Franky as his friend and nothing more, but his love for her grows with each passing day.', 46, '2012-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 7, 'Alo', 'Alo still has no idea that Mini is carrying his baby. Fed up of trying to get back to the fun times they used to have, he attempts to get over Mini by hooking up with a new girl, Poppy Champion.', 45, '2012-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 8, 'Liv', 'Alone and forced to face up to the choices she''s made, Liv discovers that she''s not as strong as she thought she was.', 46, '2012-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 9, 'Mini and Franky', 'Mini and Franky have been hiding from the world in Mini''s house for several weeks. Mini''s bump is now too pronounced to hide, while Franky is avoiding Nick and doing her best to delay the inevitable moment when he realises his brother is back.', 45, '2012-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 6), 10, 'Finale', 'It''s the end of an era. Everyone''s futures hang in the balance as Franky struggles to confront her past.', 47, '2012-03-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')), 7, 'Series 7', 'The final series sees the return of several characters from the first two generations of the show.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 7), 1, 'Fire (1)', 'Working as an assistant at a hedge fund in the city, Effy becomes increasingly addicted to status. The risks she takes to get ahead become more and more extreme.', 48, '2013-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 7), 2, 'Fire (2)', 'Effy''s glamorous life begins to unravel as her company faces financial difficulties and her friend Naomi embarks on a grueling treatment plan.', 48, '2013-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 7), 3, 'Pure (1)', 'Cassie has returned from the USA, alone. As she negotiates a solitary new life in London, she finds friendship in unexpected places.', 47, '2013-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 7), 4, 'Pure (2)', 'Cassie''s strange new relationship is put to the test when she lets someone else take her picture.', 47, '2013-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 7), 5, 'Rise (1)', 'Working as a drug dealer and gangster run-around, Cook finds himself in hot water after his boss asks a favour of him.', 47, '2013-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0840196')) AND numero_temporada = 7), 6, 'Rise (2)', 'Cook gets more than he bargained for from the women in his life. They have varying expectations of him but Cook rises to their challenges - to explosive effect.', 46, '2013-08-05');
