INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0851851', 'Terminator: The Sarah Connor Chronicles', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0066596'), 'SERIE', 'Set after the events in Terminator 2: Judgment Day (1991), Sarah Connor and her son, John, try to stay under-the-radar from the government, as they plot to destroy the computer network Skynet in hopes of preventing Armageddon.', '2008-01-01', 'https://m.media-amazon.com/images/M/MV5BMjMwYTA0YWItNmFhOS00OGE1LTkzODMtMjU2NjRjNWE5YmFlXkEyXkFqcGc@._V1_.jpg');
