INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 1, 'Sally', 'Bret and Jemaine go to a party at Dave''s, where Jemaine meets and falls for the ''most beautiful girl in the room'', Sally. When it turns out that Sally used to go out with Bret, things get weird between Bret and Jemaine.', 28, '2007-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 2, 'Bret Gives Up the Dream', 'Faced with dire financial circumstances, Bret and Jemaine look for jobs. Bret gets a job holding signs but soon he has no time for the band and Murray and Jemaine start looking for a replacement.', 28, '2007-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 3, 'Mugged', 'Bret loses Jemaine''s trust after Bret abandons him when they get mugged. To regain it, Bret tries to retrieve Jemaine''s stolen "camera phone" (a phone with a camera taped to it) from their muggers, who are experiencing their own trust issues.', 27, '2007-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 4, 'Yoko', 'Bret''s relationship with Coco threatens to split up the duo.', 25, '2007-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 5, 'Sally Returns', 'Sally, the ex-girlfriend of both Bret and Jemaine, from the season premiere, returns to further complicate things in the band.', 27, '2007-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 6, 'Bowie', 'After a photo session, Bret develops body image issues and gets some dream advice from his idol, David Bowie. Jemaine plots to cheer him up and Murray tries to get one of the band''s tunes used for a musical greeting card.', 27, '2007-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 7, 'Drive By', 'Bret and Jemaine are shocked by the prejudiced actions of a fruit vendor who won''t sell to them because they are New Zealanders. Dave recommends a strong response and teaches them how to "flip the bird". Murray is smitten with the new tech support lady at the consulate.', 26, '2007-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 8, 'Girlfriends', 'Bret and Jemaine pick up two women at a croissant shop - but end up with very different dating experiences. Meanwhile, Murray makes an album deal for the band.', 28, '2007-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 9, 'What Goes on Tour', 'Using the band''s "emergency fund," Murray organizes a warm-up tour in preparation for a big gig in Central Park. At an airport bar, the boys get hooked by some "mermaids" from a woman''s water-polo team - nearly ruining the tour and their relationship with Murray.', 25, '2007-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 10, 'New Fans', 'A performance at a local "World Music Jam" results in the Conchords gaining two new fans, but Mel is suspicious of the newcomers and their motives. Murray encourages the band to adopt a more "rock star" attitude.', 27, '2007-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 11, 'The Actor', 'Bret and Jemaine enlist a semi-professional actor to cheer Murray up after a disappointing gig. Asked to place a good-hearted rejection call, the actor gets carried away, offering Murray and the Conchords a recording deal that''s too good to be true.', 28, '2007-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 1), 12, 'The Third Conchord', 'Murray introduces a new bongo-playing band member on Bret and Jemaine, triggering angry dances and mutant half-bands.', 27, '2007-09-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 1, 'A Good Opportunity', 'Bret and Jemaine fire Murray for neglecting them in favour of the Crazy Dogggz and almost immediately they receive an offer to write a jingle for a commercial. Meanwhile Murray''s fortunes reverse after he discovers that the Crazy Dogggz big hit is a rip-off of a 1990s Polish song.', 26, '2009-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 2, 'The New Cup', 'Bret and Jemaine s fortunes unravel after Bret buys a new tea cup; Jemaine goes to desperate measures to supplement his income.', 27, '2009-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 3, 'The Tough Brets', 'Bret organizes a gang to protect himself from rappers he dissed in a song; Murray and Jemaine confront a group of Aussie bullies; Mel paints a portrait Jemaine can''t get rid of.', 28, '2009-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 4, 'Murray Takes It to the Next Level', 'Murray tries to elevate Bret and Jemaine on his friendship graph, bringing his questioning pal Jim in on the plan; Mel demands an apology from Bret for inappropriate dream behavior.', 27, '2009-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 5, 'Unnatural Love', 'Jemaine starts dating an Australian, to Bret''s dismay and inconvenience.', 26, '2009-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 6, 'Love Is a Weapon of Choice', 'Bret and Jemaine become rivals for the attentions of the same woman, who happens to have an epileptic dog that has gone missing.', 27, '2009-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 7, 'Prime Minister', 'Murray sets up a meeting for the New Zealand prime minister; Jemaine gets mixed up with an Art Garfunkel fan at the end of a tribute gig.', 28, '2009-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 8, 'New Zealand Town', 'Trying to look cool for a gig at the Grand Opening of New York''s one-block New Zealand enclave, the Conchords end up getting hooked on hair gel.', 25, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 9, 'Wingmen', 'Jemaine and Dave help Bret woo the clerk at the cheap zoo (pet shop). Jemaine also helps Murry seek forgiveness from Greg.', 27, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0863046')) AND numero_temporada = 2), 10, 'Evicted', 'Bret and Jemaine can''t afford to pay their rent and are forced to move in with Mel and Doug, and Murray believes they can make some money with a theatrical production about the band.', 28, '2009-03-22');
