INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 1, 'Rollercoaster', 'While their mother is out shopping, the boys build a roller coaster. Dr. Doofenshmirtz and Perry battle due to the doctor''s evil plan of throwing the earth off its rotation.', 13, '2007-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 2, 'Lawn Gnome Beach Party of Terror', 'Phineas and Ferb''s newest backyard project is to create a tropical beach paradise. Meanwhile, Perry tries to stop Dr. Doofenshmirtz''s plan to steal all the garden lawn gnomes.', 11, '2007-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 3, 'Flop Starz', 'Phineas and Ferb decide to become a one hit wonder, Phineas and the Ferb-Tones and Candace wins the chance to sing with them. Meanwhile, Perry must stop Doofinshmirtz''s giant robot - disguised as a temp.', 11, '2008-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 4, 'The Fast and the Phineas', 'Phineas and Ferb enter the family car in an auto race, while Candace has to bust them and impress Jeremy. Meanwhile, Perry must stop Dr. Doofenshmirtz from deflating every inflatable object in the tri-state area.', 11, '2008-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 5, 'Lights, Candace, Action!', 'Upon hearing that her favorite play is being made a movie, Candace rushes to try for the lead, only to see that Phineas and Ferb have become the directors and changed the script to include a little more insanity. Meanwhile, Perry goes to Doofinshmirtz Evil Inc. to find out why Heinz has been so quiet lately.', 11, '2008-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 6, 'Raging Bully', 'Phineas enters a thumb-wrestling competition with a local bully, while Doofenshmirtz creates a hypnotic device to control people''s minds so they will sing him Happy Birthday.', 11, '2008-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 7, 'Candace Loses Her Head', 'Phineas and Ferb decide to carve Candace''s face into Mount Rushmore for her birthday present, while Perry attempts to stop Doofenshmirtz from making a tunnel to China.', 9, '2008-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 8, 'I, Brobot', 'Phineas and Ferb clone themselves so they can complete more projects while Doofenschmirtz hovers over his girlfriend''s house with a huge magnet to erase crazy messages on her answering machine, for the sake of recording new ones.', 11, '2008-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 9, 'Run Away Runway', 'Candace becomes a model, and is forced to wear outfits designed by Phineas and Ferb while Doofenshmirtz designs a machine to create clones of himself, to avoid having to wait in line.', 11, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 10, 'The Magnificent Few', 'When Doofinshmirtz unleashes his army of termites to eat all the wood in the tri-state area, Phineas and Ferb use their newfounded love of a cowboy life to herd the stampeding cattle back to the carnival, but with Agent P stuck in a room filling with lava, how will he survive?', 11, '2008-02-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 11, 'S''Winter', 'The boys use a sno-cone machine to create a Winter paradise during the middle of Summer in their backyard, Candace tries to pursue Jeremy (who thinks dropped her for a Swedish exchange student), and Doofenshmirtz tries to melt chocolate with a machine made from laser pointers.', 11, '2008-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 12, 'Jerk De Soleil', 'The boys create a circus for the neighborhood after their original circus plans are canceled, while Jeremy gives Candace wild parsnips which she is allergic to. Doofenshmirtz creates a device to make people''s voices higher so his own voice will seem lower.', 11, '2008-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 13, 'Are You My Mummy?', 'Phineas and Ferb visit an Egyptian-themed movie theater and attempt to get a mummy of their own, but they end up capturing Candace, who is wrapped in toilet paper, while Doofenshmirtz tries to raise the city''s water level so his real estate will become beachfront property.', 11, '2008-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 14, 'Ready For The Bettys', 'Ferb and Phineas accidentally discover Perry''s secret lair and are thrust into a spy mission of their own. Meanwhile, Candace travels on a tour bus with a girl band called "The Bettys"', 11, '2008-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 15, 'I Scream, You Scream', 'Phineas and Ferb make the biggest ice cream maker for Isabella after her tonsils are taken out. Doofenshmirtz''s daughter, Vanessa, spends the day at his lair and tries to convince his ex-wife that he''s evil.', 11, '2008-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 16, 'Toy to the World', 'Based on the fact that a platypus doesn''t do very much, Phineas and Ferb create a wooden toy version of Perry to sell to a toy company. Meanwhile, the real Perry heads off to stop Doofenshmirtz from building the Great Wall of the Tri-State Area and starting up toll booths at the only exits.', 11, '2008-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 17, 'Get That Bigfoot Outa My Face!', 'Candace and the boys visit their grandparents at a lake house and the boys try to scare her with a fake Bigfoot while Doofenshmirtz goes out on a date and Perry gets ends up in the middle of it.', 11, '2008-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 18, 'It''s a Mud, Mud, Mud, Mud World', 'Phineas and Ferb create a monster truck for Candace to practice driving while Dr. Doofenshmirtz tries to find investors for his line of monster trucks that are actual monsters, with a trump card to take down the competition.', 11, '2008-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 19, 'Mom''s Birthday', 'Candace plans a special birthday for Mom, and even a song, but Phineas and Ferb are always getting in her way of what she planned, unintentionally topping everything. Meanwhile, Doofenshmirtz creates a shrinking machine that will make whatever he hates implode.', 11, '2008-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 20, 'Journey to the Center of Candace', 'When the boys build a shrinking submarine to retrieve Isabella''s sash from Pinky''s stomach, they end up in the wrong place.', 11, '2008-02-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 21, 'It''s About Time!', 'Phineas and Ferb find a time machine at a museum and travel back to the Jurassic Age. Meanwhile, Perry is sad when Doofenshmirtz replaces him with a new nemesis, Peter the Panda, so he confides in a relationship talk-show host.', 22, '2008-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 22, 'Dude, We''re Getting the Band Back Together', 'The boys and Candace hatch a plot to reunite their mom and dad''s favorite band for a wedding anniversary concert.', 22, '2008-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 23, 'Tree to Get Ready', 'Phineas and Ferb build super tree houses for themselves and Candace, but things get a little out of hand when a treehouse fight instigates. Meanwhile, Dr. Doofenshmirtz plans to ruin a ceremony in his brother''s honor.', 11, '2008-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 24, 'The Ballad of Badbeard', 'The boys set out on a high-seas adventure after learning about a mysterious pirate from their grandpa. Meanwhile, Candace spies Perry and Dr. Doofenschmirtz up to their old tricks, but is it all in her head?', 11, '2008-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 25, 'Greece Lightning', 'The boys stage a chariot race through the town''s streets after learning about ancient Greece. Meanwhile, Dr. Doofenshmritz creates a giant robot named Norm to destroy Perry, once and for all.', 11, '2008-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 26, 'Leave the Busting to Us', 'Candace uses a reality show to secretly film her brothers designing a white-water rafting ride. Meanwhile, Perry must crush Doofenshmirtz'' dream of becoming a magician, as well as dominating the tri-state area.', 11, '2008-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 27, 'Crack That Whip', 'Phineas and Ferb set up a roller derby rink for Grandma Betty Jo.', 11, '2008-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 28, 'The Best Lazy Day Ever', 'Phineas and Ferb decide to do absolutely nothing for the day. Candace questions her purpose in life after realizing that she can''t bust her brothers for doing nothing. Meanwhile, Dr. Doofenshmirtz is tired of being the ugliest person around, so he invents a device that can turn anything and anyone ugly.', 11, '2008-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 29, 'Boyfriend From 27,000 B.C.', 'While on an archaeological dig, the boys discover a caveman who falls in love with Candace, who is dressed as a cave girl for costume party. Then, Phineas and Ferb assist Buford in locating his missing goldfish.', 11, '2008-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 30, 'Voyage to the Bottom of Buford', 'When Buford''s goldfish goes missing, the boys help him find it out at sea. Meanwhile, Dr. Doofenshmirtz tries to destroy a tape of him ''saving'' a kitten from a tree.', 11, '2008-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 31, 'A Hard Day''s Knight', 'Phineas, Ferb, and Candace go to a Renaissance festival and Phineas and Ferb get Candace to go into a jousting tournament.', 11, '2008-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 32, 'Traffic Cam Caper', 'Perry wants to destroy footage from a traffic camera to keep his identity a secret, as Candace tries to use the film in hopes of proving her brothers create unusual stuff. Then, the guys decide to build the largest bowling ball and pins in the world, while Doofenshmirtz wants to rid the world of rainbows.', 11, '2008-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 33, 'Bowl-R-Rama Drama', 'Phineas and Ferb build the world''s largest bowling ball and pins. Meanwhile, Doofenshmirtz wants to use his latest invention to freeze the Tri-State Area so the people will buy his hot chocolate.', 11, '2008-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 34, 'Got Game?', 'The guys decide to hold a competition between the girls to see which are better at sports. Also, the build a telescope in the backyard. Then, Jeremy''s sister is tormenting Candace. Doofenshmirtz wants to be the winner of a dog show, and makes an attempt to liquefy a steak.', 11, '2008-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 35, 'Comet Kermilian', 'The boys build a telescope, while Doofenshmirtz tries to liquify steak. Meanwhile, Candace has another encounter with Jeremy''s younger sister, Suzy.', 11, '2008-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 36, 'Put That Putter Away', 'Phineas and Ferb create the world''s largest golf course, and since Candace is sick, she asks her best friend Stacey to bust the boys for her.', 11, '2008-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 37, 'Does This Duckbill Make Me Look Fat?', 'Phineas and Ferb create a teleporting machine, but it ends up switching Candace and Perry''s brains.', 11, '2008-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 38, 'The Flying Fishmonger', 'The boys are helping Ferb''s grandfather live his life long dream - to jump a gorge in his motorcycle, the Holy Mackerel. Meanwhile, Perry sets out to stop Dr. Doofenshmirtz from exacting another petty revenge that dates all the way back to the sandbox.', 11, '2008-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 39, 'One Good Scare Ought to Do It!', 'When Isabella falls prey to hiccups, Phineas and Ferb gather the kids together to help scare them out of her, using a remote controlled haunted house. Meanwhile, Doofenshmirtz sets out to destroy his mentor''s hideout, so that no one could discover his secrets, but not if Perry has something to say about it!', 22, '2008-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 40, 'The Monster of Phineas-n-Ferbenstein', 'The boys learn about one of Ferb''s Victorian ancestors, who helped a scientist create a monster. Meanwhile, Doofenshmirtz recalls the story of his great-great-grandfather Dr. Jekyll Doofenshmirtz.', 11, '2008-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 41, 'Oil on Candace', 'When Django feels down for not being able to draw art on the same scale as his father, Phineas and Ferb get some big ideas for his piece and the famous "unpainted desert". Meanwhile, Perry faces off against Doofenshmirtz, as he does his best to impress his visiting evil professor.', 11, '2008-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 42, 'Out of Toon', 'The boys create a cartoon and cast themselves as superheroes and Candace as the villain, while Perry attempts to defeat Doofenshmirtz, who has taken control of the power of dance.', 11, '2008-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 43, 'Hail Doofania!', 'When Doofenshmirtz''s brother Roger is elected mayor, he decides to build his own country, where he can rule over everything, but how will he stop him when Perry is having trouble entering his hideout? Meanwhile, Phineas and Ferb, in an attempt to help Isabella see her "first" rainbow, create the Rainbow-enator, which harnesses the power of their breakfast cereal to make the light show. The strangest anomaly of the episode, however, is when Candace and Vanessa manage to get their clothes mixed up at the dry-cleaners, resulting in a backwards day for everyone.', 11, '2008-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 44, 'Out to Launch', 'The boys build a rocket ship to get a good look at a star named for them, and Candace accidentally takes a ride with them just as she is trying to find the courage to ask Jeremy to a dance, while Isabella tries her best to do the same with Phineas. Meanwhile, Perry must stop Dr. Doofenshmirtz, who, not only is conveniently in space too, but has created a massive spacestation in an attempt to get revenge on "Huge-Hands-Hans".', 22, '2008-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 45, 'Phineas and Ferb Get Busted', 'After taunting the boys for going to search for the "Lake Nose Monster", Candace begins freaking out on her lifeguard job, seeing the monster at every turn. Meanwhile, Dr. Doofenshmirtz tries to remove all the zinc from the lake, though even he''s not sure why.', 22, '2009-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 46, 'Unfair Science Fair', 'Phineas and Ferb help Baljeet build a portal to Mars for a special Summer science fair. Candace competes against another girl for getting a job at Mr. Slushy Burger. Meanwhile, Doofenshmitz builds a bicarbonate volcano for the science fair, in yet another attempt to redeem himself from his embarrassing childhood, where we discover where the -inator suffix originated from.', 11, '2009-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 1), 47, 'Unfair Science Fair Redux (Another Story)', 'When Candace believes that no one wants to be around her anymore, she quickly steps through Baljeet''s portal to Mars, where she is quickly heralded among the martians. Meanwhile, Perry accompanies Dr. Doofenshmirtz to help build his evil contraption for him to stop faster, with slightly less than pleasing results.', 11, '2009-02-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 1, 'The Lake Nose Monster', 'After taunting the boys for going to search for the "Lake Nose Monster", Candace begins freaking out on her lifeguard job, seeing the monster at every turn. Meanwhile, Dr. Doofenshmirtz tries to remove all the zinc from the lake, though even he''s not sure why.', 24, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 2, 'Interview with a Platypus', 'Curious as to what Perry''s chirping sound really means, Phineas and Ferb create a "Perry Translator". But they soon find it''s not just bound to translating platypuses, platypi, platypeople? Meanwhile, Perry himself is caught in a plan involving a shark cage that is half off, a remote to open the dam, complicated acronyms and the high tech BO-AT.', 11, '2009-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 3, 'Tip of the Day', 'The boys decide to spread the word about the tip of the shoelace, called the "aglet." Meanwhile, Doofenshmirtz is featured in the newest viral video to hit the internet.', 11, '2009-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 4, 'Attack of the 50 Foot Sister', 'Phineas and Ferb create a slow reacting growth potion to help Baljeet with his "giant" watermelon, but Candace decides to use it for herself, when she finds that she''s a little too short to be a flawless girl. Meanwhile, Perry must stop Doofenshmirtz from his most disgusting plan ever!', 11, '2009-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 5, 'Backyard Aquarium', 'Phineas and Ferb have a new pet, Goldy the goldfish, and to help make Goldy feel less lonely, Phineas and Ferb have built an aquarium with many other creatures. Meanwhile, Perry must stop Doofenshmirtz from a food related childhood revenge story.', 11, '2009-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 6, 'Day of the Living Gelatin!', 'When Phineas and Ferb get inspired by Candace''s dessert club to create the biggest piece of gelatin ever, even Jenny and Stacy want to join in. Meanwhile, Doofenshmirtz has a horrific plan, to turn Perry evil!', 11, '2009-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 7, 'Elementary, My Dear Stacy', 'While in London, Candace and Stacy decide to take a page out of Sherlock Holmes''…entire collection, to figure out what Phineas and Ferb have planned for the London Eye. Meanwhile, Perry must team up with British agent 00 Zero in order to stop Dr. Doofenshmirtz from moving Big Ben to the Tri-State Area.', 11, '2009-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 8, 'Don''t Even Blink', 'Fed up with her brother''s inventions always disappearing, Candace enlists the help of everyone in the neighbourhood to build and watch a big and obvious invention, that they might finally see exactly what happens to everything. Meanwhile, is it mime? No, it''s Doofenshmirtz'' new Invisibility Ray.', 11, '2009-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 9, 'Chez Platypus', 'Phineas and Ferb open Chez Platypus, which becomes the trendiest restaurant in town. Jeremy asks Candace out on a date to the restaurant. Meanwhile Doofenshmirtz goes on another date from his online dating service, and vows to destroy all love in the tri-state area if the date doesn''t go well.', 11, '2009-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 10, 'Perry Lays an Egg', 'When an early end to their daily project causes Phineas and Ferb to mistake an egg for Perry''s, the boys use all their technological knowhow to help hatch the new part of the family. However Candace has different plans for the egg, as a nature show brings her to be the one to convince Phineas and Ferb that the newborn will need a real mother. Meanwhile, Doofenshmirtz is doing all he can to convince Perry that his latest scheme really is evil.', 11, '2009-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 11, 'Gaming the System', 'Buford has a new game, "Jump and Duck", which everyone is loving the look of. But Phineas is always one for a challenge, and Candace''s comment about a game "sucking them in" is just the inspiration he needs to create a virtual reality machine of "Jump and Duck". The trouble begins when Candace, in her preparations for a Cotillion Jeremy has asked her to, gets pulled in before the boys. Meanwhile, Doofenshmirtz has a slightly more disturbing childhood horror revenge story, but is the song and dance really necessary for this one?', 11, '2009-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 12, 'The Chronicles of Meap', 'It''s another average, logic defying day for Phineas and Ferb, until a crashed space pod, carrying an unbearably cute alien, Meap, thrusts the boys into another adventure in space! Everyone has a different role to play, while Candace holds on to Meap by accident, Ferb is fixing up the ship, as Phineas uses the new cute tracker to find where their new friend is, to the slight irritation of Isabella, as he can''t get what *cough* is causing cute interference, but of course, it all has to lead up to the big explosive finale in SPACE -ace-ace. Meanwhile, Doofenshmirtz has a new plan, simplistic in nature, but buried in an avalanche of backstory, oh dears.', 22, '2009-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 13, 'Thaddeus and Thor', 'Visiting relatives of the Flynns'' neighbors bear an uncanny resemblance to Candace, Phineas and Ferb. Meanwhile, Perry finds himself in the middle of Dr. Doofenshmirtz''s family reunion.', 11, '2009-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 14, 'De Plane! De Plane!', 'Phineas and Ferb set out to build a bigger plane than Howard Hughes'' wooden Spruce Goose, so they build it out of papier-mâché, to do a similar theme to the Spruce Goose, complete with in-flight service and entertainment. Dr. Doofenshmirtz is doing his part to be green by using recycled materials to build an "Evaporator-inator" to dry up all the pools in the Tri-State area. Meanwhile, Candace and Stacy attend Jeremy''s pool party only to discover an adventurous Australian girl is capturing Jeremy''s attention.', 11, '2009-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 15, 'Let''s Take a Quiz', 'After hearing that Jeremy was in a commercial, Candace wants to gain popularity as well, by going on Phineas and Ferb''s TV game show.', 11, '2009-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 16, 'At the Car Wash', 'Phineas and Ferb create an automatic carwash in order to raise money for Isabella and the Fireside girls.', 11, '2009-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 17, 'Oh, There You Are, Perry!', 'Perry the Platypus is reassigned and forced to move to the Quad State area with a new family and battle a new villain, the Regurgitator. During his new assignment, Phineas, Ferb, and Candace put in every effort to find him, hoping he''ll return to them.', 11, '2009-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 18, 'Swiss Family Phineas', 'The family takes a short sail trip out to sea, but a storm causes them to wind up stranded on a remote island. To pass the time, Phineas, Ferb, and Isabella, build a set of treehouses with the most modern conveniences, to Candace''s dismay, as she wants to get back home in time to attend Jeremy''s party. Meanwhile, Perry the Platypus, who was left behind, must get away from the watchful eye of Baljeet and Buford, so he can go on his mission to stop Dr. Doofenshmirtz''s latest plot.', 11, '2009-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 19, 'Hide and Seek', 'To play a game of indoor hide-and-seek Phineas and Ferb shrink down their friends including, their new extreme fan, Irving. Meanwhile, Dr. Doofenshmirtz attaches a nanobot to Perry in an attempt to discover where he lives.', 11, '2009-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 20, 'That Sinking Feeling', 'Phineas and Ferb build a ocean liner so that Baljeet can go on a romantic cruise with his friend Mishti, whom he now notices is a very pretty girl. Meanwhile, Doofenshmirtz wants to move all the lighthouses to the other side of town so that he can get a good night''s sleep instead of hearing the constant noice from the boats surrounding the bay by his headquarters', 11, '2009-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 21, 'The Baljeatles', 'Phineas and Ferb learn that Baljeet has signed up for rock camp and worries he may get his first failing grade. So the boys help by forming a band to help him express his feelings, especially for math. Meanwhile, Candace wonders why Jeremy doesn''t give her a cool nickname as Stacy gets close to Coltrane, the rock camp director. Doofenshmirtz''s latest plan has him wanting his own army of babies by broadcasting his heartbeat all over the tristate area.', 11, '2009-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 22, 'Vanessassary Roughness', 'Vanessa Doofenshirtmz tries to convince her dad that she''s responsible enough to have her own car. For that, she has to get a special chemical for him in hopes she doesn''t always have to ride with him on the family scooter. At the mega mall, a chase for the chemical ensues as it''s tossed around between Candace and Stacy, Buford and Baljeet, and Ferb, who joins Vanessa''s quest in hopes he''ll be able to get her attention.', 11, '2009-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 23, 'No More Bunny Business', 'When Candace finds a rabbit, she wants him as her pet, but in hindsight, he''s actually a rouge agent trying to find Perry''s secret lair for information. Meanwhile, Phineas and Ferb try to make x-ray glasses. And since Perry isn''t around to stop his latest plot, Doofenshirtmz faces an unusual new foe.', 11, '2009-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 24, 'Spa Day', 'Stacy has a spa day planned for herself and Candace, but they get side tracked when Jeremy is participating in a house-building program for the homeless and Candace joins as well in hopes of impressing him. Fortunately, the girls are able to get their spa day after all when Phineas and Ferb build their own spa with its own special features. Meanwhile, Doofenshmritz finds a cat which causes a lot of problems when he''s trying to carry out his latest evil plot.', 11, '2009-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 25, 'Phineas and Ferb''s Quantum Boogaloo', 'The boys travel into the future to borrow a tool, but when their future sister Candace finds what they are up to, she realizes that she has the evidence she needs to travel back into the past to bust her brothers. When she returns to her own time, she realizes that she has made a terrible mistake that only she can fix.', 22, '2009-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 26, 'Phineas and Ferb''s Musical Cliptastic Countdown', 'Perry the Platypus is reassigned and forced to move to the Quad State area with a new family and battle a new villain, the Regurgitator. During his new assignment, Phineas, Ferb, and Candace put in every effort to find him, hoping he''ll return to them.', 22, '2009-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 27, 'Bubble Boys', 'The boys are able to create a giant bubble which enables them and their friends to float and view all of Danville from above as Candace tries to bust them while on a practice drive with Mom for her learner''s permit. Meanwhile, Dr. Doofenshmirtz tries to gain popularity by singing country and western music and Perry must stop him before the concert crowd submits to his latest invention.', 11, '2009-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 28, 'Isabella and the Temple of Sap', 'While Phineas and Ferb get the bubble ready, Isabella and the Fireside Girls head out to the "Old Abandoned Old Abandoned Amusement Park" where the maracanut tree is and try to get the sap from it. Meanwhile, Isabella''s pet dog, Pinky tries to stop his nemesis, Professor Poofenplotz, from stealing hairspray.', 11, '2009-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 29, 'Cheer Up, Candace', 'Candace feels depressed when Jeremy cancels their date, and Phineas and Ferb try to cheer her up. Meanwhile, Perry is accused of committing bad deeds and must attempt to clear his name.', 11, '2009-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 30, 'Fireside Girl Jamboree', 'Candace hopes to join the Fireside Girls before the Paisley Sideburn Brothers perform.', 11, '2009-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 31, 'The Bully Code', 'When Baljeet saved his life, Buford vows to become his slave. Then, when Candace and Stacy accidentally send bad pictures of Candace to Jeremy''s cell phone, they get a job at Mr. Slushy Dawg in order to get his phone and delete the pictures before he sees them.', 11, '2009-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 32, 'Finding Mary McGuffin', 'Dad accidentally sells Candace''s favorite doll at a yard sale. Phineas and Ferb become detectives and interview various people to find the doll. Meanwhile, Perry the Platypus tries to get the doll back from his nemesis.', 11, '2009-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 33, 'Picture This', 'After Ferb accidentally leaves his skateboard at his grandparents'' house, he and Phineas develop a teleportation device that can retrieve any object. Meanwhile, Dr. Doofenshmirtz tries to rid the world of mimes.', 11, '2009-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 34, 'Nerdy Dancin''', 'Unsure of his own dancing skills when he agrees to go on a TV show with Candace, Phineas and Ferb develop a device to help Jeremy imitate the dance moves of a professional. Meanwhile, Dr. Doofenshmirtz and several other villains try to broadcast an evil message during the taping of the show.', 11, '2009-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 35, 'What Do It Do', 'The boys reconstuct one of Doofenshmirtz''s inventions to discover what it does after it lands in their front yard.', 11, '2009-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 36, 'Atlantis', 'Phineas and Ferb discover the lost city of Atlantis, Candace enters a sand castle building contest, and Dr. Doofenshmirtz tries to use a growth formula to make plants evil.', 11, '2009-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 37, 'Phineas and Ferb Christmas Vacation', 'Phineas and Ferb are decorating their city for the arrival of Santa Claus. But when the evil mad scientist Dr. Heinz Doofenshmirtz uses a machine to ruin the holiday, Phineas and Ferb must find a way to fix it and save Christmas.', 36, '2009-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 38, 'Just Passing Through', 'Phineas and Ferb create an orb that allows its user to pass through objects to help find Linda''s guitar pick, Dr. Doofenshmirtz tries to destroy a statue honoring his brother Roger.', 11, '2010-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 39, 'Candace''s Big Day', 'When Aunt Tiana and Uncle Bob’s wedding is moved to the Flynn-Fletcher''s backyard, Candace hopes that her brothers do not upstage her role as maid of honor. Meanwhile, Dr. Doofenshmirtz tries to transform food into junk food', 11, '2010-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 40, 'I Was a Middle Aged Robot', 'Lawrence''s memory is accidentally erased by a gadget in Perry''s lair before participating in a father-daughter race with Candace, so Perry operates a robot version of Lawrence to fill in for him. Meanwhile, Dr. Doofenshmirtz invents an opposite of glue named "Eulg," which breaks stuff apart rather than join it together.', 11, '2010-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 41, 'Suddenly Suzy', 'Candace panics when she inadvertently agrees to babysit Jeremy''s little sister Suzy but to her surprise, Suzy is docile in the absence of her brother, saying that when Jeremy isn''t around, she''s "off the clock." The two of them bond and Suzy shows Candace how to get Phineas and Ferb to bust themselves. Meanwhile, the boys build a replica of Niagara Falls in their backyard with the intention of riding over the falls in a barrel. Back at Doofenshmirtz Evil Inc., Dr. Doofenshmirtz decides to increase his carbon footprint, (though he doesn''t know what that is), by inventing a Carbon Footprint-inator.', 11, '2010-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 42, 'Undercover Carl', 'When the boys build an Anti-Gravity Fun Launcher, Carl accidentally intercepts their plans and assumes they are working for Dr. Doofenshmirtz, so he is sent undercover to figure out what they are doing. Meanwhile, Perry tries to find a lost agent, and Dr. Doofenshmirtz also acquires the blueprints to help with a parking issue on his street.', 11, '2010-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 43, 'Hip Hip Parade', 'Phineas and Ferb decide to help build floats for all the neighborhood kids in the yearly "Tri-State Area Unification Day" parade, but a family grudge leads Buford and his family to try and wreak havoc on the parade.', 11, '2010-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 44, 'Invasion of the Ferb Snatchers', 'After watching a sci-fi movie marathon, Candace becomes convinced that Ferb is an alien. Meanwhile, Dr. Doofenshmirtz tries to market an evil invention by claiming it to be a cleaning device.', 11, '2010-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 45, 'Ain''t No Kiddie Ride', 'The boys trick out the kiddie rides at a store, Dr. Doofenshmirtz tries to burn his name into the atmosphere.', 11, '2010-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 46, 'Not Phineas and Ferb', 'Irving’s brother Albert doesn’t believe that Phineas and Ferb are anything special, and since he claims to be the “Truth Detector,” he can prove it. Desperate to prove Albert wrong, Irving convinces Baljeet and Buford to pose as Phineas and Ferb beside a giant hologram of the boys’ Eiffel Tower construction. Meanwhile, Dr. Doofenshmirtz is fed up with the quality of accessories for his model train set, and decides to shrink down a variety of national monuments to add to his collection.', 11, '2010-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 47, 'Phineas and Ferb-Busters', 'Candace, Stacy, and Jenny team up to try and bust Phineas and Ferb together. Meanwhile, Dr. Doofenshmirtz enlists a new robot to replace Norm, but a power surge causes it to glitch and turn against him.', 11, '2010-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 48, 'The Lizard Whisperer', 'Phineas and Ferb find a chameleon in the backyard, who grows to the size of a dinosaur, thanks to Doofenshmirtz''s Gigant-Inator, and takes a walk through downtown. Meanwhile, Jeremy teaches a song to Doofenshmirtz, who plans to use it to summon aliens to do his bidding.', 11, '2010-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 49, 'Robot Rodeo', 'Phineas and Ferb build a robotic rodeo in the backyard. Candace tries to prove she can focus so she can go to a concert with Stacy. Doofenshmirtz stalls to finish his entry into the Inator Creator competition.', 11, '2010-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 50, 'The Beak', 'Khaka Peü Peü arrives in Danville to challenge Phineas and Ferb after the boys are mistaken as a superhero (while wearing an indestructible suit they designed to safely conquer their newly built extreme skate-track) known as The Beak. With the super villain wreaking havoc, it''s up to Phineas and Ferb to thwart him while Dr. Doofenshmirtz tells the people of the Tri-State area that he is in charge, in hopes that they will actually just go along with it. Meanwhile, his brother Roger is worried that everyone will blame him for the recent super villain catastrophe so he decides to make Doofenshmirtz Mayor.', 22, '2010-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 51, 'She''s the Mayor', 'Candace is awarded the opportunity to be mayor for the day, so she create laws that can bust her brothers. Back at home, Phineas and Ferb build an authentic log cabin and pioneer village. Meanwhile, Dr. Doofenshmirtz is scheduled to play golf with his brother Rodger but isn''t happy about it.', 11, '2010-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 52, 'The Lemonade Stand', 'Phineas and Ferb build the ultimate lemonade stand and begin to offer franchise opportunities. Meanwhile, Candace and Stacy’s relationship is put to the test when Candace feels she must pick between their friendship and busting her brothers, while Dr. Doofenshmirtz creates a “Paper-Cut-Inator” so that he can make millions selling band-aids.', 11, '2010-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 53, 'Phineas and Ferb Hawaiian Vacation (1)', 'The Flynn-Fletcher Family go on a vacation to Hawaii. While they are there, Phineas and Ferb make living sea creatures and Candace find a lava necklace of bad luck. Meanwhile, Doofenshmirtz creates a De-Evolution-inator and Perry and him get stranded on a island.', 11, '2010-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 54, 'Phineas and Ferb Hawaiian Vacation (2)', 'The Flynn-Fletcher Family go on a vacation to Hawaii. While they are there, Phineas and Ferb make living sea creatures and Candace find a lava necklace of bad luck. Meanwhile, Doofenshmirtz creates a De-Evolution-inator and Perry and him get stranded on a island.', 11, '2010-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 55, 'Phineas and Ferb: Summer Belongs to You!', 'It''s the summer solstice, so Phineas, Ferb, and their friends decide to travel around the world in one day in an effort to create the "biggest, longest, funnest summer day of all time". But not everyone believes they can actually achieve what they have set out to do, especially Buford. Candace tags along because Jeremy is on a trip to Paris, and she fears that there he may meet other girls. Also, Isabella finds her affections for Phineas sorely tested when his steadfast focus on achieving his goal puts pressure on her. Meanwhile, Dr. Doofenshmirtz takes a father trip to Tokyo, Japan with Vanessa, but sets out with Perry and Major Monogram to find her when she joins Phineas, Ferb and the others.', 48, '2010-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 56, 'Nerds of a Feather', 'Phineas and Ferb head to the Tri-State area’s annual sci-fi/comic book convention to meet their hero, special effects guru Clive Addison. Their plan gets sidetracked when they’re swept into a duel between fantasy fans and sci-fi geeks. Meanwhile, Candace tries to keep secret that she’s a fan of Ducky Mo-Mo, another convention staple. Across the convention hall, Dr. Doofenshmirtz has taken television executive Jeff McGarland hostage so he can pitch him a show he’s developed, Doof ‘N’ Puss.', 22, '2010-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 57, 'Wizard of Odd', 'When Phineas and Ferb spin the house in order to paint it more quickly, Candace, inside the house, gets dizzy and collapses. She wakes up in the magical land of Odd and heads down the yellow sidewalk to Bustopolis to meet the Wizard.', 22, '2010-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 58, 'We Call it Maze', 'Phineas and Ferb create a life sized maze filled with fun obstacles. Melissa, the leader of the Little Sparks, a younger branch of the Fireside Girls, is immediately captivated when she meets Candace and finds out that she was a Fireside Girl who earned 50 patches in one day. When the girls try out the maze, Candace takes charge, but things don’t go as planned. Meanwhile, Dr. Doofenshmirtz reasons that if the Leaning Tower of Pisa can generate souvenir revenue, then surely he can use his latest invention, the "Tilt-inator," to tilt buildings so he can sell souvenir replicas.', 11, '2010-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 59, 'Ladies and Gentlemen, Meet Max Modem!', 'When Linda is asked to do a Lindana reunion concert, Lawrence worries that she might be missing the excitement of her old life, so he asks the boys to help turn him into a pop star so that he can perform at the concert and show mom he too is an exciting guy. Across town, Dr. Doofenshmirtz plans a faux alien invasion in order to take over the Tri-State area.', 11, '2010-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 60, 'The Secret of Success', 'Phineas and Ferb are building an ATV powerful enough to handle extreme terrains and even buildings. Meanwhile, Candace and Stacy go to a leadership seminar where Candace learns the steps needed to achieve her ultimate goal of busting her brothers. Dr. Doofenshmirtz is hosting a Telethon of Evil.', 11, '2010-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 61, 'The Doof Side of the Moon', 'Phineas and Ferb plan to put Danville on the map by building the world''s tallest building. However, Candace teams up with Albert and utilizes his expertise to bust her brothers. Meanwhile, Dr. Doofenshmirtz wants to be responsible for all the evil in the Tri-State Area, and since he believes that evil levels rise during a full moon, he plans to rotate it so that only the infamous "dark side of the moon" faces Earth.', 11, '2010-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 62, 'Split Personality', 'Candace accidentally gets hit by Phineas and Ferb''s molecular separator ray which causes her to have two different personalities - Romantic Candace and Busting Candace, so the boys have to figure out a way to put her back together again. Meanwhile, Dr. Doofenshmirtz tries to get over his fear of high diving, but he figures that if he can''t, he will just use his "Look-away-inator" to zap everyone so that they do not witness his shame.', 11, '2010-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 63, 'Brain Drain', 'Phineas, Ferb and the gang are all sick with a cold, so they decide to make it the best "sick day" ever by creating a live television feed to their friends'' homes so that they can all enjoy a day of fun together. Meanwhile, Vanessa learns from her mom, Charlene, that her dad is picking her up from a party she is going to with her punk rock boyfriend Johnny and is worried that he will embarrass her yet again. However, Dr. Doofenshmirtz is busy trying to use his "Deevolution-ator" to drain Agent P''s will power so that he can control him, and things get out of hand when Dr. Doofenshmirtz picks up Vanessa at the party, and it''s up to Agent P to save the day.', 11, '2010-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 64, 'Rollercoaster: The Musical!', 'A musical in which Phineas and Ferb revisit the day they built a gigantic roller coaster in their backyard. Doofenshmirtz tries to pull the East Coast to the west using tinfoil and a huge magnet.', 22, '2011-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 65, 'Make Play', 'Candace switches places with a princess who looks exactly like her, while the real princess helps the boys build a giant jukebox filled with live bands.', 11, '2011-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 2), 66, 'Candace Gets Busted', 'When Linda and Lawrence go on a trip, Candace decides to have an Intimate Get Together with Stacy and Jenny. But, then more people come and makes it into a party. Later, when her parents get home, Candace gets busted.', 11, '2011-02-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 1, 'The Great Indoors', 'The third season begins with Phineas and Ferb building a gigantic biome during a bit of bad weather to help Isabella earn a Fireside Girl patch.', 11, '2011-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 2, 'Canderemy', 'Candace realizes that she needs to spend more time with Stacy, so she vows to spend the whole day with her only. But while visiting Jeremy and his mom, Mrs. Johnson, Dr. Doofenshmirtz''s "combine-inator" zaps her and Jeremy, literally joining them at the hip. Meanwhile, Phineas and Ferb build a giant robot dog that causes a lot of mischief.', 11, '2011-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 3, 'Run, Candace, Run', 'Phineas and Ferb''s newest invention is a pair of boots that make the wearer extraordinarily fast. Candace decides to wear them so that she can be in two places at once; at Jeremy''s family picnic, where she runs into Mrs. Johnson, and also at the library where she promised Mom she would read to the kids. Meanwhile, Dr. Doofenshmirtz''s building is put up for sale so he tries to convince a prospective buyer, Annabelle, who turns out to be a long lost relative of the Johnson family, that it is not worth buying.', 11, '2011-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 4, 'Last Train to Bustville', 'While visiting their grandparents, the kids decide to create and race a giant hot air balloon. Meanwhile, Candace is inspired by train engineer Glenda''s can-do attitude and decides to "give up" on busting her brothers. On the other side of town, Dr. Doofenshmirtz finds a Dodo bird egg and is convinced that it is a fierce bird-monster that can help him take over the Tri-state area, but discovers the exact opposite when the egg hatches.', 11, '2011-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 5, 'Phineas'' Birthday Clip-o-Rama!', 'It''s Phineas'' birthday and for the special occasion, Ferb puts together a clip show of the gang''s favorite moments. Meanwhile, Agent P has to stop Dr. Doofenshmirtz from using his ''non-inator'' to pre-empt his brother''s biography from appearing on television.', 24, '2011-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 6, 'The Belly of the Beast', 'For Harbor Days Festival, Phineas and Ferb celebrate by creating a mechanical version of the historical elusive shark of Danville Harbor. Seeing what the boys are up to, Candace enlists some help to capture the mysterious shark. Meanwhile, Dr. Doofenshmirtz invents the ''Salt Water Taffy-inator'' to give cavities to every kid in the Tri-State Area.', 11, '2011-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 7, 'Moon Farm', 'Inspired by the lost verse from the nursery rhyme, "Hey, Diddle Diddle", the boys decide to take some cows to the moon to see if its low gravitational pull actually does produce the best tasting ice cream ever. Back at home, Candace decides to take advantage of the boys being gone and attempts to make a fancy dinner for Jeremy, but her lack of cooking skills don''t add anything to the plate. Meanwhile, Dr. Doofenshmirtz attempts to use his ''Moisture Suck-inator'' to turn his neighbor''s plants brown, so that his plants will be greener by comparison.', 11, '2011-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 8, 'Ask a Foolish Question', 'When Candace discovers that Phineas and Ferb have invented a computer that can answer anything, she asks it how she can finally bust her brothers once and for all. Meanwhile, Dr. Doofenshmirtz loses the key to his latest invention, the "All Purpose-inator," and Agent P must find it before he does.', 11, '2011-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 9, 'Misperceived Monotreme', 'Perry misses his 100th battle against Dr. Doofenshmirtz when Candace takes him to the Charity Pet Wash with her. Perry''s absence goes unnoticed when the zookeeper''s typical platypus at the Danville Zoo stops Dr. Doofenshmirtz''s plan to zap his brother with his "Least Likely-inator." Meanwhile, the boys build a fun house Phineas and Ferb style.', 11, '2011-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 10, 'Candace Disconnected', 'Candace has no choice but to go to her brothers for help after she loses her phone for the fifth time. Unbeknownst to her, the phone that they invent for her has a voice activated phone transfer app that sends her to Easter Island. Meanwhile, back at Evil Inc., Dr. Doofenshmirtz invents a "Pick ''Em Up-inator" to pick Vanessa up from class, then he finds Sarcastic Norm Head, the Norm head prototype that has an affinity for sarcasm, later Doofenshmirtz and Perry watch an exercise show.', 11, '2011-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 11, 'Magic Carpet Ride', 'Inspired by Dad''s favorite childhood program, the boys decide to create a magic carpet, and Candace is convinced that fortune cookies will lead her to bust her brothers. Meanwhile, Dr. Doofenshmirtz plans on ruining his brother''s art unveiling by using his "Stain-inator" to ruin a mysterious painting, but as it turns out, the painting is Dr. Doofenshmirtz''s very own masterpiece that he created when he was a youth back in Gimmelshtump.', 11, '2011-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 12, 'Bad Hair Day', 'Candace gets a bad haircut and must rely on Phineas and Ferb''s hair growing machine to correct it before she attends the Endangered Animal Benefit with Jeremy and his mom. However, when Candace turns up the power, her hair grows much more than expected and she is mistaken for a rare tangerine orangutan. Meanwhile, Dr. Doofenshmirtz is developing his Very, Very ''Bad-inator.''', 11, '2011-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 13, 'Meatloaf Surprise', 'Mom joins Jamie Oliver as one of the judges for Danville''s Meatloaf Festival Cook-off, as he stresses healthy eating and fresh ingredients. Meanwhile, Candace puts a bid on a prized souvenir resembling band members Nigel and Adrian from her favorite band, Tiny Cowboy, at the Rock and Roll Memorabilia Auction, but gets distracted when her brothers build a bounce house in their backyard. On the other side of town, Dr. Doofenshmirtz has plans to enter his family meatloaf recipe into the competition using "hate" as the special ingredient.', 11, '2011-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 14, 'Phineas and Ferb Interrupted', 'When Mom tells Candace she wants to spend the day with her, Candace spends the entire time with her in the backyard so that she can bust her brothers. Unfortunately, Phineas and Ferb''s grand plan for the day only entail watching the grass grow after getting zapped by Dr. Doofenshmirtz''s Dull-and-Boring-inator earlier that day. Meanwhile, Agent P partners up with Dr. Doofenshmirtz to fix the now destroyed Dull-and-Boring-inator into a Dynamic-inator in order to fix Phineas and Ferb.', 11, '2011-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 15, 'A Real Boy', 'When Dr. Doofenshmirtz thinks Vanessa overhears him say he would rather have a son to do his evil bidding, he feels terrible so he intends to zap her with the "Forget-about-it-Inator." Meanwhile, Norm shares his feelings of wanting to be a real boy with Dr. Doofenshmirtz and decides to play up the "son" role. Back at the Flynn-Fletcher household, Candace has Stacy hypnotize her into ignoring the need to bust her brothers so that she can spend the entire afternoon relaxing with Jeremy, but unfortunately the hypnosis trigger words end up playing right into her date with Jeremy.', 11, '2011-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 16, 'Mommy Can You Hear Me?', 'After Candace injures her ankle and is told to stay in bed, she drives herself crazy trying to get her Mom''s attention in order to bust her brothers. Fortunately, Phineas and Ferb provide her with a box of items to stave off her boredom. However, it ends up being more of a hindrance, until she unknowingly helps the boys warn their cosmonaut friend about a dangerous obstacle approaching them. Meanwhile, Perry interrupts Dr. Doofenshmirtz''s Chicken Soup themed escapade.', 11, '2011-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 17, 'Road Trip', 'On the last day of the Flynn-Fletcher family road trip, Candace thinks she’ll finally have a couple of hours to relax and not worry about busting her brothers. However, Phineas and Ferb decide to build a truck stop diner on top of the RV. Meanwhile, Doofenshmirtz is also doing a road trip, but he’s using a big rig to transport his boom juice across the Tri-State Area.', 11, '2011-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 18, 'Tour de Ferb', 'Phineas and Ferb enlist the help of cyclist Greg LeMond to help Baljeet compete in a bicycle race. Meanwhile, Doofenshmirtz tries to bring the city to a standstill so he can bid on an auction unopposed.', 11, '2011-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 19, 'Skiddley Whiffers', 'Phineas and Ferb build a giant version of a favorite childhood game, with Danville as the central location. Meanwhile, Doofenshmirtz takes Vanessa on a camping trip.', 11, '2011-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 20, 'My Fair Goalie', 'When Ferb''s cousins visit from England and challenge him to a soccer match, he and Phineas warp the walls of physics and build a high tech 3D stadium. Meanwhile, convinced that her relationship with Jeremy depends on her being more proper, Candace enlists the help of Ferb''s British cousin, Eliza, to teach her the rules of etiquette. Back at Doofenshmirtz Evil Inc., Dr. Doofenshmirtz is sick in couch but forces himself to set off his \"If-A-Tree-Fell-in-the-Forest-Inator\", which causes any tree that falls to say his name.', 24, '2011-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 21, 'Bullseye!', 'When Lawrence heads out to attend a speaking engagement on antiques, he unwittingly finds himself participating in the L.O.V.E.M.U.F.F.I.N. Pageant of Evil against Dr. Doofenshmirtz and Rodney. As a special host oversees the proceedings, Perry is tasked with monitoring the situation, but Lawrence gets hit with Rodney''s "Make-Everything-Evil-Izer", and is crowned the supreme leader of L.O.V.E.M.U.F.F.I.N. Meanwhile, Candace is determined to bust the boys but doesn''t realize that the object she''s looking at is not theirs. Across town, the boys are playing a giant game of darts.', 11, '2011-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 22, 'That''s the Spirit', 'It''s Halloween night and the kids encounter a strange boy named Russell who is convinced his house is haunted. Meanwhile, Dr. Doofenshmirtz''s disdain for grass causes him to invent a "mind-transfer-inator" enabling him to merge minds with a cow and destroy all the grass in the Tri-State Area. Unfortunately, his plan backfires and he transforms into a scary "were-cow" that wreaks havoc any time there is a full moon. It''s now up to Agent P to stop him and save Danville.', 11, '2011-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 23, 'The Curse of Candace', 'Candace is bitten by a bat after watching a popular vampire movie with Stacy and worries that she is becoming a vampire. Phineas and Ferb''s latest gadgets lead Candace to believe that she has indeed made the change from teenager to teen vampire. Meanwhile, Dr. Doofenshmirtz plans to change the Tri-State Area into a carbon copy of Gimmelshtump so that it will be easier to take over.', 11, '2011-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 24, 'Escape From Phineas Tower', 'When Phineas and Ferb are inspired by an antique escape chamber that Dad acquires, they decide to build a computer-controlled tower that will trap them inside and allow them to explore the world of escapement. Meanwhile, Dr. Doofenshmirtz invents a "Rude-Inator" to ruin Roger''s meeting with a visiting dignitary from England.', 11, '2011-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 25, 'Lotsa Latkes', 'Potato gremlins appear all over town when Phineas and Ferb clone a potato chip from Buford and it mixes with his DNA; Doofenshmirtz tries to summon the Spartan army with his historical army retrieve-inator.', 11, '2011-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 26, 'Ferb Latin', 'Phineas and Ferb create their own language, Ferb Latin, which quickly catches on. Unfortunately for Candace, she awakes from a massage puzzled to find everyone else speaking a language she doesn''t understand. Meanwhile, Dr. Doofenshmirtz decides to use propaganda as his new "-inator," believing that it will work since people will believe anything they read.', 11, '2011-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 27, 'A Phineas and Ferb Family Christmas', 'The boys decide to put on a traditional family Christmas special featuring their family, friends and a few very special guests, including Grammy winning recording artist Kelly Clarkson (playing herself). The episode features three new holiday songs - Isabella''s "Let it Snow", a Buford and Baljeet rendition of "Good King Wenscelas" and the whole gang singing "We Wish You a Merry Christmas".', 11, '2011-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 28, 'Tri-Stone Area', 'It’s the Stone Age and Phineas and Ferb are cavemen who decide to invent something new, fun and useful…the wheel! Meanwhile, Dr. Doofenshmirtz attempts to make his digs more upscale by using the precursor to the Inator device... a plain old stick.', 11, '2012-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 29, 'Doof Dynasty', 'In ancient feudal China, Princess Isabella is part ruler and Master Perry has given up the way of the warrior. After Phineas and Ferb witness Doofus Khan capture the Princess and take her as a prisoner, they track down Master Perry and convince him to teach them his warrior ways so they can rescue Princess Isabella and save China.', 11, '2012-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 30, 'Excaliferb', 'During medieval times, Phineas and Ferb (or, Ferb-a-lot) set off on an epic quest to find the legendary sword, Excaliferb, so they can defeat the evil sorcerer, Millifishmirtz.', 24, '2012-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 31, 'Phineas and Ferb and the Temple of Juatchadoon', 'After locating and retrieving the Amulet of Juatchdoon, adventuring archeologist duo Ohio (Phineas) Flynn and Rhode Island (Ferb) Fletcher set off to South America to help Damsel in Distress Isabella find the Lost Temple of Juatchadoon and her missing mother. However, Dr. Doofenshmirtz has other plans for the amulet - to awaken the evil corn colossus to give him the power to destroy the world.', 11, '2012-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 32, 'Monster from the Id', 'After losing a gift that Jeremy made for her, Candace is determined to recreate it before Jeremy realizes it’s missing. Unfortunately, Candace can’t remember what it looks like, so she enlists Phineas and Ferb to use their mind machine to enter into her subconscious and recapture the memory. Meanwhile, Doofenshmirtz’s evil plan is to use his Underwear-Inator to take over the Tri-State Area, since everyone''s greatest fear is being caught in public in their underwear.', 11, '2012-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 33, 'Gi-Ants', 'Thinking it would be cool to be part of an ant society, Phineas and Ferb create and infiltrate the Antius Maximus, a massive ant farm filled with giant ants. Suspecting that the boys are up to something, Candace accidentally drenches herself in the ant pheromones and follows them inside. Meanwhile, Doofenshmirtz feels tired and lethargic after eating turkey and decides to create a Turkey-Inator that will create a sleeping epidemic in Danville by turning things into giant irresistible turkeys.', 11, '2012-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 34, 'The Remains of the Platypus', 'Craziness has ensued in Danville and no one has any idea what’s going on. The wackiness unfolds when Phineas and Ferb create Cheesetopia, Doofenshmirtz makes Perry his butler with his Butler-inator, and Carl is trapped by Doof while in a squirrel costume. All is explained, in an episode of Phineas and Ferb that starts at the end and works its way back to the beginning.', 11, '2012-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 35, 'Mom''s In The House', 'When Phineas and Ferb can’t find Perry, they decide to create the Perrytronic 3000, a mechanical structure that can assume any form. Of course, being aware of the boys’ every move, Candace decides to take a different tactic on her busting approach by using a new technique that keeps Phineas and Ferb from finishing their Perry project. Meanwhile, Doofenshmirtz invents a Duplicator-Inator-2 so that he can duplicate his own head and make himself twice as smart.', 11, '2012-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 36, 'Perry the Actorpus', 'The executive of Totally Tools oversees a contest to find the company''s \"spokesanimal\", and Perry is crowned the winner. However, the victory puts Perry''s secret identity in jeopardy, forcing Major Monogram to appoint Agent S as a temporary replacement, but when Dr. Doofenshmirtz sees his new nemesis is Sergei the Snail, he mistakenly underestimates his new opponent. Meanwhile, Candace has been welcomed into Mandy''s "Stop the Busting" retreat, which aims to teach Candace to control the urge to bust her brothers through positive reinforcement.', 11, '2012-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 37, 'Let''s Bounce', 'Inspired by Ferb''s personal anti-gravity device, Phineas thinks it would be fun to suspend trampolines all over Danville.', 11, '2012-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 38, 'Bully Bromance Break Up', 'Baljeet announces that he is no longer Buford''s nerd, and Buford is heartbroken.', 11, '2012-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 39, 'Quietest Day Ever', 'After Mom asks the kids to keep quiet while she prepares for her online knitting test, Phineas and Ferb create ninja outfits designed to hide the wearer from anyone who is not wearing them. Meanwhile, Candace becomes increasingly frustrated after she can’t find the boys and bust them. Across town, Dr. Doofenshmirtz invents the De-Handsome-Inator.', 11, '2012-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 40, 'The Doonkelberry Imperative', 'When Mom is out of Doonkleberries for her famous Doonkleberry pie, the boys set out to find some for her. Meanwhile, Perry and Dr. Doofenshmirtz find themselves across the ocean as Doofenshmirtz returns home to renew his Druesselsteinian driver’s license. Back in Danville, Candace is convinced she has discovered the answer to her busting problem.', 11, '2012-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 41, 'Meapless in Seattle', 'Meap''s world is put in danger and the boys try to help him save the universe when they travel to Seattle. Meanwhile, Doofenshmirtz visits former nemesis Peter the Panda.', 24, '2012-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 42, 'Delivery of Destiny', 'Paul the Delivery Guy discovers his job has a higher calling to save Danville as he makes stops at Phineas and Ferb''s house, Doofenshmirtz Evil, Inc., Danville City Hall and the OWCA, in a special episode seen through his eyes. The rock band, Love Händel, returns for some musical accompaniment. Meanwhile, at Doofenshmirtz Evil Inc., Perry has lost the tools in his hat.', 11, '2012-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 43, 'Buford Confidential', 'Brigitte, Josette, and Colette, the visiting Fireside Girls from France, help Isabella capture the American Grizzly Bear, one of the world''s most dangerous creatures. Buford''s plan to jokingly dress up as the bear backfires when he discovers the identity of Brigitte, throwing him off his game. Back at their grandparents'' cabin, Phineas and Ferb create the most amazing "run-through-the-sprinkler" experience. Meanwhile, Dr. Doofenshmirtz''s loathing of pretzels drives him to create the "De-Twist-Inator" to untwist every pretzel in Danville.', 11, '2012-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 44, 'The Mom Attractor', 'When the boys ask Candace to decide what they should do for the day, she slyly asks them to invent a device to attract their Mom so that she can finally bust her brothers. Meanwhile, Dr. Doofenshmirtz has invented a "Baby-Cry-Inator" designed to tarnish his goodie-two-shoes brother''s image with the electorate.', 11, '2012-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 45, 'Cranius Maximus', 'When Baljeet becomes concerned that he is losing his mental edge, the boys invent a cerebral stimulatory hat, or "Brain booster," to help him. But when the hat exceeds expectations and makes Baljeet exponentially smarter, he suddenly views everyone else as beneath him and becomes a threat to civilization by taking Earth''s atmosphere and bringing it to the moon. Meanwhile, Dr. Doofenshmirtz plans to use his "Key-Find-Inator" to collect all the keys in Danville in hopes that it will lead to the Key to the City.', 11, '2012-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 46, 'Agent Doof', 'Candace''s plans to watch over Phineas and Ferb backfire when Dr. Doofenshmirtz''s "Babe-inator" turns her brothers into babies. After having an epiphany, Dr. Doofenshmirtz shows up at the OWCA to give up his evil ways. Agent P has no choice but to show Dr. Doofenshmirtz the ropes of the trade, but things quickly sour between the two after Dr. Doofenshmirtz accidentally exposes the identity of a fellow animal agent.', 11, '2012-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 47, 'Minor Monogram', 'With Fall around the corner, Phineas and Ferb decide to invent "S''Fall", a colorful world full of giant leaf piles and gourds. Meanwhile, over at Evil Inc., Dr. Doofenshmirtz is mentoring Rodrigo, a budding student of evil. Unfortunately, Rodrigo truly is evil, and when he captures Dr. Doofenshmirtz and Agent P., it’s up to Major Monogram''s son, Monty, to save the day.', 11, '2012-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 48, 'What A Croc!', 'When the boys learn that the famous Crikey the Crocodile has gone missing, they set out to find and return him to his home at the Danville Nature Preserve. Meanwhile, to Candace''s amazement, Irving reveals his digital scrapbook compilation of all of Phineas and Ferb''s wild creations, and guest star Ray Liotta fills in for Major Monogram to give Perry his mission. Also, Dr. Doofenshmirtz plans to embarrass his brother by using his ''Chicken-Replace-inator'' to replace Roger''s mayoral award with the nearest chicken.', 11, '2012-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 49, 'Sleepwalk Surprise', 'Candace''s plans to hang out with Jeremy are derailed after he becomes interested in playing Phineas and Ferb''s newest game, jet pack volleyball. Meanwhile, when Dr. Doofenshmirtz discovers he invents "-inators" in his sleep, he decides to go back into his dreams to find out what is happening.', 11, '2012-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 50, 'Sci-Fi Pie Fly', 'Phineas and Ferb create their own flying saucer to help solve the mystery of a recent rash of crop circles. Meanwhile, Candace tries to give up her tattling habit by taking a "me" day, and across town, Dr. Doofenshmirtz challenges the local pizzeria''s "37 Minutes or it''s Free" rule by using his "dough-blow-inator" to generate a powerful current of air to hold the pizza dough aloft indefinitely.', 11, '2012-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 51, 'Sipping with the Enemy', 'Candace tries to bust Phineas and Ferb when they put on an enormous backyard magic show, while Vanessa and Major Monogram''s son Monty get coffee together despite their warring fathers. Meanwhile, Dr. Doofenshmirtz tries to become hip in an attempt to get youthful followers.', 11, '2012-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 52, 'Tri-State Treasure: Boot of Secrets', 'The guys help their dad unearth a missing piece of Danville history; Doofenshmirtz tries to make himself younger to win a children''s film festival.', 11, '2012-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 53, 'Doofapus', 'Candace accidentally turns into a fluid when she comes into contact with a device that turns solids into liquids. Meanwhile, Doofenshmirtz turns himself into a platypus to defeat Perry in battle.', 11, '2012-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 54, 'Norm Unleashed', 'Candace finds it difficult to bust Phineas and Ferb when her brothers build nanobots that can assemble into any object they can imagine. Meanwhile, Dr. Doofenshmirtz has jury duty, so Norm takes over the day’s evil scheme -- to destroy Danville by using weapons.', 11, '2012-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 55, 'Where''s Perry (1)', 'The Flynn-Fletchers are off on an African safari, leaving Perry at home to deal with Doofenshmirtz and his most evil plot yet: to take over the O.W.C.A. But when Doofenshmirtz accidentally zaps Carl the intern with his Ultimate-Evil-Inator ray, Carl takes over the O.W.C.A. (Organization Without a Cool Acronym) and imprisons Doof and Monogram. Agent P steps in but gets zapped with Doof’s many rays and in the cliffhanger of all cliffhangers, disappears.', 24, '2012-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 56, 'Where''s Perry (2)', 'Agent P''s fate is finally revealed in the action-packed finale of the two-part television special that left Phineas, Ferb and the gang hanging...literally off an unchartered gorge and Candace frantic over a phone call with Jeremy that left their relationship status in limbo. Now, with Agent P nowhere in sight, Dr. Doofenshmirtz and Major Monogram square off against evil Carl who controls a set of familiar-looking robots to take over the OWCA, in one of the biggest battles yet.', 24, '2012-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 57, 'Ferb TV', 'Phineas and Ferb create their own TV shows and commercials.', 11, '2012-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 58, 'When Worlds Collide', 'After discovering that a strange planet is hurtling directly towards Danville, Phineas and Ferb set out to avert a disaster, while Buford looks forward to making contact with its alien race. Meanwhile, Dr. Doofenshmirtz hopes to steal the world''s largest ball of twine.', 11, '2012-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 59, 'What''d I Miss?', 'Phineas and the gang introduce Ferb and Perry to their newest project - training domesticated squirrels to live in the wild. Meanwhile, Dr. Doofenshmirtz aims to do a better job of seeing through his evil plans now that Agent P is back.', 11, '2012-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 60, 'Road to Danville', 'When one of Dr. Doofenshmirtz''s "-inators" zaps him and Agent P into the middle of nowhere, they must embark on a comical journey filled with twists and turns to return home.', 11, '2012-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 61, 'This is Your Backstory', 'Agent P quickly figures out there is more to Norm''s odd reality show that celebrates the eventful life of his creator Dr. Doofenshmirtz, which is recreated through flashbacks and special guests.', 24, '2012-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 3), 62, 'Blackout', 'Candace is put in charge of Phineas and Ferb just before they seize the opportunity to make the most of Danville''s electricity blackout while Dr. Doofenshmirtz tries to use pity to his advantage.', 11, '2012-11-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')), 4, 'Season 4', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 1, 'For Your Ice Only', 'National Hockey League star Luc Robitaille offers his assistance when Phineas and Ferb take an ice hockey game to the extreme. Meanwhile, Doofenshmirtz build an Abominable-inator to make himself bigger, scarier and hairer.', 11, '2012-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 2, 'Happy New Year!', 'Phineas and Ferb plan their own New Year''s Eve ball drop, complete with a customized multi-dimensional ball, while Candace makes it her resolution to refrain from busting her brothers before the clock hits midnight. Meanwhile, Doofenshmirtz uses a Resolution-Changer-inator in his tie as he continues the never-ending attempts to take over the Tri-State Area.', 11, '2012-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 3, 'Fly on the Wall', 'Buford removes a part from a tire swing the boys are building and it accidentally shoots a ray that turns Candace into a fly. Meanwhile, Doofenshmirtz is suffering from evil scientist’s block.', 11, '2013-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 4, 'Bully Bust', 'Candace challenges Buford to keep Phineas and Ferb’s invention from disappearing so that she can sweep in and casually bust her brothers. Across town, Doofenshmirtz has had one too many lattes and is experiencing an extra burst of evil energy.', 11, '2013-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 5, 'My Sweet Ride', 'It''s time for Danville''s Doo Wop Hop and car show and the whole town is getting prepped for it. Doofenshmirtz is set on winning the show even if it means using his Rust-inator to turn all the other cars into red dust. Meanwhile, Candace''s hope for a car of her own has come true, but it''s not quite all she imagined.', 11, '2013-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 6, 'Der Kinderlumper', 'The boys create Rutabaga-themed vehicles when Candace is chosen to be Rutabaga princess and gets to start the "Running of the Chinchillas." Across town, Doofenshmirtz plans to turn himself into a real live Kinderlumper to scare Roger into relinquishing control of the Tri-State Area over to him.', 11, '2013-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 7, 'Sidetracked', 'Agent P teams up with an estranged former human partner named Lyla to stop a hijacked train to save the train''s passengers and Canada''s national treasure - a moose named Albert.', 24, '2013-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 8, 'Primal Perry', 'Perry comes face to face with an Australian platypus hunter set on destroying him. Baljeet is having an existential emergency and finds himself incapable of making decisions.', 24, '2013-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 9, 'Mind Share', 'The gang switches bodies with alien tourists for a free intergalactic vacation.', 11, '2013-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 10, 'Backyard Hodge Podge', 'The boys create a new invention using recycled parts from past projects. When Candace attempts to bust them, Mom is too exhausted from baking pies all night and can''t figure out what Candace is trying to show her.', 11, '2013-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 11, 'Bee Day', 'The boys make a giant inflatable wading pool for Mom. Candace reveals her "Emo" side. Doofenshmirtz attempts to become ruler of all bees.', 11, '2013-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 12, 'Bee Story', 'Isabella and the Fireside Girls turn themselves into bees. Poofenplotz tries to become Queen of the World by stealing and consuming massive amounts of royal jelly.', 11, '2013-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 13, 'Great Balls of Water', 'When Candace thinks Jeremy is bored with their usual hangouts, she sets out to find something unique to do with him. Meanwhile, Phineas and Ferb power through town surfing on a giant ball of water and Doofenshmirtz plans to use his Double-Negative-Inator to confuse his local eatery into giving him a wintery drink that is usually not served during summer.', 11, '2013-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 14, 'Where''s Pinky?', 'When Pinky goes missing, Phineas & Ferb create a machine that will amplify Buford’s senses to those of a dog’s. However, it works so well that the animal agents’ secret identities are put in jeopardy. Meanwhile, Candace tries to meet up with Jeremy for lunch at City Hall but gets stuck in a mandatory tour.', 11, '2013-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 15, 'Phineas and Ferb''s Musical Cliptastic Countdown Hosted by Kelly Osbourne', 'Dr. Doofenshmirtz and Major Monogram have their hearts set on revealing the top 10 musical numbers from Seasons 2 and 3, but soon find out that celebrity host Kelly Osbourne has been brought in to fill the role. Unwilling to submit to playing second fiddle, Doofenshmirtz makes it his mission to thwart Kelly until Perry the Platypus sets out to stop his nemesis from ruining the entire show. Maia Mitchell ("Teen Beach Movie") also guest stars.', 33, '2013-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 16, 'Knot My Problem', 'Candace thinks she can trap the boys at last when they ask her to call Mom if they get stuck in their giant Gordian Knot, but is distracted by helping Jeremy open his mini-safe.', 11, '2013-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 17, 'Just Desserts', 'Phineas and Ferb build a wall for climbing. Candace is recording a Fireside Girls book with Irving and loses her voice. Meanwhile, Dr. Doofenshmirtz creates the Just-Desserts-inator.', 11, '2013-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 18, 'La Candace-Cabra', 'The boys set out to prove the existence of the elusive Chupacabra to the world, but Candace can''t stand the wait and needs to first just prove it to Mom. Meanwhile, Doofenshmirtz has the brilliant idea to use his Switch-Place-Inator to remove hair from one person and give it to another so that he can in turn sell his hair growing tonic.', 11, '2013-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 19, 'Happy Birthday, Isabella', 'Phineas and the gang celebrate Isabella''s birthday in a big way, but all she really wants is some quiet time with Phineas. Meanwhile, Doofenshmirtz has installed his Bugs Me-Inator onto an evil bug bus and is driving around Danville turning all the things that bug him literally into bugs.', 11, '2013-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 20, 'Love at First Byte', 'When Linda becomes overwhelmed for organizing a block party, she asks Phineas and Ferb for help. Norm falls in love with Rodney''s female robot.', 11, '2013-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 21, 'One Good Turn', 'Candace and Stacy compete in Phineas and Ferb’s Ultimate Obstacle Course. Doofenshmirtz plans to humiliate his brother, the Mayor.', 11, '2013-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 22, 'Phineas and Ferb: Mission Marvel', 'The gang switches bodies with alien tourists for a free intergalactic vacation.', 46, '2013-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 23, 'Thanks But No Thanks', 'After learning about Monty and Vanessa''s secret relationship, Carl bribes Monty into helping him get some much needed acknowledgement from Monogram. Meanwhile, Candace is ecstatic when she discovers that her neighbor Peggy McGee has witnessed all of Phineas and Ferb''s summer antics and is happy to tell Mom about them. Also, Dr. Doofenshmirtz creates its "Inflator-inator" to try to silence his neighbor who plays the bagpipes every day.', 11, '2013-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 24, 'Troy Story', 'Inspired by Candace''s book club selection, The Iliad, the boys reenact the Trojan War -- but with a Phineas and Ferb twist. Meanwhile, Perry discovers that Doofenshmirtz has a major problem with throwing things away so he helps him find his De-Clutter-Inator.', 11, '2013-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 25, 'Druselsteinoween', 'Phineas and Ferb deejay at Vanessa''s Halloween party. Doofenshmirtz hunts for hidden treasure in a castle.', 11, '2013-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 26, 'Terrifying Tri-State Trilogy of Terror', 'Candace brings her plush Ducky to life. Doofenshmirtz encounters a Giant Floating Baby Head. Phineas, Ferb, and their friends confront a horde of evil platypuses.', 24, '2013-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 27, 'Face Your Fear', 'After studying hours of horror movies, Doofenshmirtz develops a theory that enlarging small, cute animals into giant beasts will help him take over the Tri-State area. But when he puts his plan into action, he soon realizes it might be too much for him to handle. Meanwhile, Phineas and Ferb make a giant revolving foam city so they can safely perform skateboarding tricks, and Candace''s tour of the Danville Space Laboratory gives her an opportunity for a high-tech bust.', 11, '2013-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 28, 'Cheers for Fears', 'When Candace is stumped about what to get Jeremy for his birthday, she reluctantly asks Phineas and Ferb for their help in creating the ultimate gift. Meanwhile, Doofenshmirtz plans to make fears a reality with his Worst-Fear-Inator, but his plans backfire when he finds himself battling his own fears instead.', 11, '2013-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 29, 'Steampunx', 'When Phineas and Ferb discover a commemorative coin from the 1903 Danville World’s Fair, Lawrence recounts the events of the festival to them, in which steam-driven devices were introduced and a set of kids, who were very much like them, were preparing for the highly anticipated event.', 11, '2013-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 30, 'Just Our Luck', 'When Candace is accidentally zapped by Doofenshmirtz’s Stinkelkrampen-Inator (aka Good Luck-Inator), she realizes she has a good chance of busting Phineas and Ferb.', 11, '2014-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 31, 'Return Policy', 'Annoyed at waiting in really long lines at the return counter, Doofenshmirtz invents a "Back-to-the-Store-inator" to send things back to the store where they came. Meanwhile, Phineas and Ferb stage an extreme batting challenge their friends take place in, and Candace''s obsession to bust coincides with her and Jeremy''s visit to the Extreme Water Park.', 11, '2014-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 32, 'Live and Let Drive', 'Agent P travels to the glamorous city of Montevillebad to stop Doof from winning the Grand Prix and collecting the prize money. When Doof uses his "I-don''t-care-Inator" to sabotage the race and eliminate the competition, including international racing legend of Italian-Scottish-Swiss-Dutch descent Paolo Vanderbeek (Patrick Dempsey), Agent P must take the wheel and go head-to-head with Doof on the racetrack.', 11, '2014-03-01');
