INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 34, 'Father''s Day', 'Perry helps Doof in retrieving his father''s old lawn gnome. Meanwhile, Phineas and Ferb help out their father on Father''s Day', 11, '2014-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 35, 'Imperfect Storm', 'Phineas and Ferb have created a device reinforcing the wind and test them on a giant kites in the park. Candace thinks she''s finally going to bust when Mom gives her backyard a makeover. Meanwhile, Doofenshmirtz builds a Water-Zalewator to celebrate his girlfriend of the past, who doused him with water, because Heinz she loved, but who then gave him the basket.', 11, '2014-06-11');
