INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0852863')) AND numero_temporada = 4), 38, 'The Klimpaloon Ultimatum', 'Phineas and the gang help Love Händel prove the existence of Klimpaloon, the magical old-timey bathing suit that lives in the Himalayas, to verify that their song, "The Ballad of Klimpaloon", is legitimate.', 24, '2014-07-07');
