INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 1, 'Season 1', 'The first season of the American television drama series True Blood premiered on September 7, 2008 and concluded on November 23, 2008. It consists of 12 episodes, each running approximately 55 minutes in length and was, for the most part, based on the novel Dead Until Dark, the first entry in The Southern Vampire Mysteries by Charlaine Harris. The story takes place in the fictional town of Bon Temps, Louisiana, two years after vampires have made their presence known to mankind, and follows telepathic waitress Sookie Stackhouse as she attempts to solve a series of murders that seem to be motivated by a hatred of vampires.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 1, 'Strange Love', 'Across the country, vampires have “come out of the coffin” following the invention of mass-produced synthetic blood. In Louisiana, Sookie Stack house, a waitress with telepathic abilities, falls under the spell of sexy, 173-year-old vampire Bill Compton whose thoughts she can’t read. After saving Bill from the Rat trays, a pair of ruthless “vampire drainers”, Sookie tests the limits of Bill’ s gratitude when the two are left alone in the dark. Meanwhile, Sookie’ s best friend Tara goes to work for Sam merlette at his bar and grill, while Sookie’ s roguish brother Jason finds himself in hot water when a “fang-banger” with whom he’s been intimate meets a tragic end.', 58, '2008-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 2, 'The First Taste', 'After Sookie gets saved by Bill she suffers a lot of injuries and Bill tries to save her "the Vampire way". The next day her brother is released from police custody and the bodies of Sookie''s attackers are found. Later that day Bill goes to visit Sookie''s family and gets a not so friendly welcome.', 54, '2008-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 3, 'Mine', 'Tara visits LaFayette seeking comfort from her woes, Sookie meets some of Bill''s rowdy friends and saves them from harm from a human among them, and, Sookie and Hugo visit the Church of the Fellowship of the Sun.', 52, '2008-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 4, 'Escape from Dragon House', 'One of the barmaids from Merlotte''s is murdered and all signs point to Jason as her killer. Also evident is the fact that she had been around vampires, and Sookie knows just where to go to find out who the girl had been with. Bill introduces Sookie to Fangtasia, the biggest vampire bar in Shreveport, and Eric, the oldest vampire in Shreveport. Her search could lead her into territory she never thought she''d cover.', 50, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 5, 'Sparks Fly Out', 'Bill wins over Adele''s church group with his vivid recollections from the Civil War; Sam reveals his feelings to Sookie; Jason gives vampire blood another shot with the help of Lafayette, and hurts Tara in the process.', 55, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 6, 'Cold Ground', 'Sookie seeks refuge from her friends'' and neighbors'' inner voices; Jason wrestles with withdrawal symptoms; Tara''s mother needs her help; Sam and Tara make a connection.', 52, '2008-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 7, 'Burning House of Love', 'Sookie''s painful childhood revelation spurs Bill into action; Tara agrees to pay for an exorcism for Lettie Mae; Jason travels to Fangtasia in search of V juice.', 53, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 8, 'The Fourth Man in the Fire', 'Sookie tries to hold herself together in the wake of another possible tragedy; Tara lashes out at Sookie and Sam; Amy charms the crowd at Merlotte''s.', 56, '2008-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 9, 'Plaisir D''Amour', 'Bill must pay a steep price for protecting Sookie; Jason and Amy break a taboo; Tara consults with Miss Jeanette about exorcising her inner demon; Bill enlists an unlikely bodyguard.', 53, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 10, 'I Don''t Wanna Know', 'Sam shares a secret with Sookie; Lettie Mae and Tara celebrate; Jason and Amy debate what to do with Eddie; Bill faces a harsh penalty.', 50, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 11, 'To Love Is to Bury', 'Sookie and Sam investigate her most recent vision; Jason helps clean up Amy''s mess; Tara becomes angry with Lettie Mae; Lafayette visits a senator.', 53, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 1), 12, 'You''ll Be the Death of Me', 'Sookie finds a link to the string of killings in Bon Temps; Tara wants to make the most of her second chance; Jason finds a new calling; Bill tempts fate; Sam is upset by an encounter with an old acquaintance.', 53, '2008-11-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 2, 'Season 2', 'The second season of the television series True Blood commenced airing in the United States on June 14, 2009, concluded on September 13, 2009, and contains 12 episodes. It is loosely based on the second novel of The Southern Vampire Mysteries, Living Dead in Dallas.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 1, 'Nothing But the Blood', 'A shocking murder outside Merlotte''s has Bon Temps reeling. Meanwhile, Sookie''s relationship with Bill is tested when she learns about Jessica, and of his involvement in her uncle''s death. Sam recalls a shape-shifting encounter he had with Maryann as a 17-year-old. Jason gets a sudden windfall that allows him to pay for a leadership retreat with the Fellowship of the Sun. Two adversaries find themselves sharing a mysterious dungeon and, possibly, the same fate.', 57, '2009-06-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 2, 'Keep This Party Going', 'Sookie is forced to babysit Jessica and the romantic inconveniences the teen vampire''s presence creates. At the Light of Day leadership conference, Jason makes an impression on its ambitious leaders, Steve and Sarah Newlin. While one of his fellow campers, Amanda Jane with her band, the God Rockets, livens the spirits at camp with their hit single, Jesus Asked Me Out Today. Maryann casts her spell on Merlotte''s patrons.', 55, '2009-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 3, 'Scratches', 'Bill and Eric team up to save Sookie from a mysterious creature. Jason has second thoughts about the Light of Day retreat anti-vampire agenda, but Sarah and Steve counter his doubts with flattery and promises. Sam leaves town after alienating everyone. Jessica heads over to Merlotte''s, where a smitten Hoyt falls for her. Tara is attracted to Eggs but is rudely interrupted by a fog.', 57, '2009-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 4, 'Shake and Fingerpop', 'Bill and Sookie travel to Dallas to carry out Eric''s mission; Jason falls victim to a practical joke; Maryann throws a birthday party for Tara.', 55, '2009-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 5, 'Never Let Me Go', 'While in Dallas, Sookie connects with one of her own; Jason is rewarded for his hard work at the Light of Day boot camp; Eric shares a secret about his past with Bill. Lafayette is given his job back.', 52, '2009-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 6, 'Hard-Hearted Hannah', 'Sookie embarks on a dangerous mission to locate Godric. Bill is shocked when a vampire from his past resurfaces in Dallas and keeps him hostage. Jason makes some difficult decisions. Andy interrogates Lafayette about his disappearance, Terry intervenes.', 53, '2009-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 7, 'Release Me', 'Drunken Andy helps Sam escape from Maryann''s clasp. Sookie uncovers the traitor. Sam confront Daphne to discover Maryann is a Maenad. Jason gets caught fleeing the L.O.D. church by Sarah. Eric overhears Barry''s message to Bill and goes to Sookie''s aid.', 53, '2009-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 8, 'Timebomb', 'Sookie''s captivity takes an unexpected turn; Sam makes a gruesome discovery at Merlotte''s; Tara and Eggs eat a mysterious meal prepared by Maryann; Jason pays off his debt to Eric.', 52, '2009-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 9, 'I Will Rise Up', 'A wounded Eric plays Sookie for a sucker, to Bill’s dismay, and ends up getting inside her head. Later, Sookie and Jason bond over their recent adventures. Blaming Eggs for Tara’s bruises and bizarre behavior, Lafayette and Lettie Mae try to figure out a way to pry their kin from Maryann’s clutches. Hoyt defends his relationship with Jessica to Maxine, to no avail. Jailed by Bud along with a group of Bon Temps revelers, Sam looks for a way to escape and avoid capture by an increasingly obsessed Maryann. In Dallas, Eric and the vampires defend their recent actions to Nan Flanagan and are shocked when Godric decides to take the fall for their PR disaster.', 52, '2009-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 10, 'New World in My View', 'Sookie, Bill and Jason return to a Bon Temps turned upside down by Maryann. Lured to Merlotte’s by Arlene, Sam and Andy find cold comfort in their refuge from a group of bloodthirsty revelers. Bill discovers that traditional vampire techniques don’t work on Maryann; Hoyt and Jessica try to keep a lid on Maxine’s madness; and Sookie tries to push through the darkness consuming Tara. With all hell breaking loose, Jason takes the bull by the horns to rescue Sam, at least for the moment.', 44, '2009-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 11, 'Frenzy', 'With the crisis in Bon Temps careening out of control, Bill seeks out the advice of Sophie-Anne, the Vampire Queen of Louisiana, but must exercise patience before she gives him critical information. Meanwhile, Sookie and Lafayette find that protecting Tara from herself is more difficult than they anticipated; a desperate Sam turns to an unlikely source for assistance; and Jessica tests Hoyt’s allegiance to Maxine.', 53, '2009-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 2), 12, 'Beyond Here Lies Nothin''', 'Bon Temps reaches a fever pitch as Maryann prepares for her ultimate bestial sacrifice, conscripting Sookie to be Maid of Honor at the bloody nuptials. Meanwhile, Sophie-Anne warns Eric to keep the lid on Bill''s inquisitiveness; Jason leads Andy into the heroic abyss; and Hoyt struggles with Maxine''s endless stream of insults. Deliberating on what may be his final move to save Sookie and the town, Sam places his trust, and his life, in a most unlikely ally', 57, '2009-09-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 3, 'Season 3', 'The third season of the television series True Blood premiered on June 13, 2010 simultaneously on HBO and HBO Canada. It concluded its run on September 12, 2010 and contained 12 episodes, bringing the series total to 36. It loosely follows the plot of the third novel of The Southern Vampire Mysteries series, Club Dead.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 1, 'Bad Blood', 'Sookie turns to Eric for help finding Bill; Andy urges Jason to stay the course; Sam reconnects with his past; Tara seeks refuge from her grief.', 51, '2010-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 2, 'Beautifully Broken', 'Russell Edgington, the Vampire King of Mississippi, concocts a plan to consolidate his power. Eric remembers his past; Sam tests the strength of his family bonds; Tara finds an ally in a shady vampire named Franklin Mott.', 56, '2010-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 3, 'It Hurts Me Too', 'In search of Bill, Sookie heads to Mississippi in the company of Alcide, a werewolf bodyguard. Haunted by visions from his past, Bill makes a surprising pledge of allegiance.', 58, '2010-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 4, '9 Crimes', 'Sookie joins Alcide at a raucous engagement party for his former fiancee. Bill "procures" dinner for Russell and Lorena. Sam brokers a deal with Tommy and his parents. Andy gets a promotion and draws Jason''s attention. Arlene is irked by Jessica''s arrival at Merlotte''s. Eric is given a deadline to locate Bill. Franklin takes Tara on a road trip.', 54, '2010-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 5, 'Trouble', 'Alcide and Sookie turn to an alpha-wolf "packmaster" for advice on how to deal with Russell''s minions. Tara considers a proposal from Franklin, who''s completed his mission for Russell; Joe Lee breaks his promise to Sam and Tommy; Lafayette learns the meaning of patience from Jesus, his mother''s orderly; Jason meets his match in a mysterious girl named Crystal. An heirloom reminds Eric of his past and his ongoing thirst for vengeance.', 56, '2010-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 6, 'I Got a Right to Sing the Blues', 'Spurned by Eric, Sookie fears the worst for Bill, whose fate now lies in Lorena''s hands. Fueled by a night of bloody passion, Tara executes a desperate plan to stave off Franklin''s advances. In Bon Temps, Tommy finds it difficult to leave the family nest; Jessica gets her fix from a Merlotte''s customer; and Jason''s romance with Crystal hits a snag, as does Lafayette''s with Jesus. After revealing his master plan to Eric, Russell pays a visit to Louisiana in order to start executing it.', 57, '2010-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 7, 'Hitting the Ground', 'Sookie''s attempt to rescue Bill has unforseen consequences. Meanwhile, Jason seeks the truth about Crystal. Sam must step in when Tommy gets involved in a dog fighting ring, all thanks to Melinda and Joe Lee''s quest for money. Eric figures out how to get the information he wants from Sophie-Anne. Debbie plans to get even with Alcide while Russell ignores the Magister.', 47, '2010-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 8, 'Night on the Sun', 'While Sookie must rethink her relationship with Bill, he reconciles with Jessica. As Russell decides what he''s going to do next, Sophie-Anne relocates her residence. Jason offers a challenge to save Crystal while Ruby Jean pays Lafayette a surprise visit. A new waitress starts at Merlotte. Eric''s allegiance to Russell is proven. Alcide''s family emergency puts Sookie in a vulnerable position.', 57, '2010-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 9, 'Everything Is Broken', 'The Vampire Rights Amendment is close to being ratified so Nan confronts Eric at Fangtasia about the whereabouts of the Magister. Russell vows revenge against all his vampire and human adversaries. Bill discovers the truth about Sookie''s true identity. Unexpected help arrives as Jason goes up against Felton and Calvin. Arlene is overcome by a sense of futility about her future while Tara meets up with a new ally and with someone who caused her pain in the past. Sookie meets a new family member. Hoyt addresses his real feelings head on.', 59, '2010-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 10, 'I Smell a Rat', 'Sookie is warned about the dangers she will have to deal with. Dark memories surface for Sam. Arlene must ask Holly for help while Jason faces unexpected dealings with Tara and Crystal. Jesus'' interest in V''s qualities is aroused. Arlene seeks out Holly for help. Russell vows to inflict punishment on his enemies. After precautions, Eric satisfies a wish.', 55, '2010-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 11, 'Fresh Blood', 'Bill wants to earn back Sookie''s trust but once again brings her close to danger. Eric tempts Russell with "ultimate vampire dream". Jason tries to comprehend what he''s learned about Crystal. Sam alienates everyone but Tara. Jessica and Hoyt take their romance up a notch. Lafayette struggles with new demons.', 50, '2010-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 3), 12, 'Evil Is Going On', 'Eric plots his revenge against Russell; Sookie considers a new life without Bill; Tara discovers some surprising news about Sam; Jason finds a new calling; Lafayette turns to Jesus for help; Hoyt hopes for a future with Jessica.', 54, '2010-09-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 4, 'Season 4', 'The fourth season of the television series True Blood contains 12 episodes, bringing the series total to 48. The season premiered on June 26, 2011. Though the storyline picks twelve and a half months after the events of season three; the season still begins immediately after final scene of "Evil Is Going On". It is loosely based on the fourth novel in The Southern Vampire Mysteries series, Dead to the World.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 1, 'She''s Not There', 'Sookie journeys away from Bon Temps; Eric and Bill try to win back the human public; Jason learns that no good deed goes unpunished; Tara finds refuge in close quarters; Sam bonds with his own; Hoyt and Jessica debate the dinner menu; Jesus urges Lafayette to join a coven; and Terry tries to alleviate Arlene’s fears about the baby.', 56, '2011-06-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 2, 'You Smell Like Dinner', 'Sookie adjusts to Bon Temps'' new realities; Bill reveals pieces of his past; Eric crashes a witches'' meeting; Jason gets his wounds licked; Andy struggles with his addiction; Sam learns of Luna''s special talents; Jessica satisfies her blood cravings; and Arlene witnesses strange behavior from her family.', 54, '2011-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 3, 'If You Love Me, Why am I Dyin''?', 'Sookie makes a deal with Eric and reconnects with Alcide; Bill punishes an errant vampire and counsels a guilt-ridden Jessica; Jason is cast as a reluctant savior; Tommy eyes a scam and alienates Sam; Marnie flexes her newfound powers; Pam delivers an ultimatum to Lafayette, Tara and Jesus; Eric spoils Sookie''s faerie reunion.', 55, '2011-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 4, 'I''m Alive and On Fire', 'Alcide helps Sookie hunt for Eric; Marnie searches for guidance to break a spell; Bill discovers a common bond with the Bellefleurs; Jason begs for liberation from Hotshot; Sam penetrates Luna''s inner circle; Arlene sees the writing on the wall; Tommy returns to his roots.', 50, '2011-07-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 5, 'Me and the Devil', 'Sookie nurtures Eric; Bill gets involved personally in the necromancy crisis; Pam takes the veil; Sam becomes Tommy''s accomplice; Arlene and Terry look to religion to solve their problem; Jesus and Lafayette head to Mexico to harness a shaman''s power; Jason convalesces.', 50, '2011-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 6, 'I Wish I Was the Moon', 'Sookie searches for Jason under a full moon; Marnie connects with spirits of the past; Arlene and Terry cope with a suspicious inferno; Debbie urges Alcide to join a new werewolf community; Tommy trades places with Sam; Lafayette feels the spirit in Mexico; Eric surrenders to his King''s will.', 59, '2011-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 7, 'Cold Grey Light of Dawn', 'With Marnie empowered by spirits of the dead, Bill issues an unpopular order to save vampires from the light. Eric embraces his amnesia; Luna discovers Sam’s not the man she thought he was; Lafayette expands his consciousness; Pam gets a body peel; Andy’s date with Holly doesn’t go as planned; Jessica has doubts about her future with Hoyt; Alcide and Debbie join a new pack.', 57, '2011-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 8, 'Spellbound', 'Bill and Marnie get ready for an open confrontation. The King secures the loyalty of Sookie and Eric. Jason is conflicted emotionally. A spirit manipulates Lafayette for its own purposes. Sam must deal with Marcus who just happens to be Luna''s ex.', 56, '2011-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 9, 'Let''s Get Out of Here', 'Sookie tries to figure out how to fit both Bill and Eric into her life. Lafayette needs Jesus'' help to rid him of the spirit that has taken over. Alcide is called upon by Marcus to help render assistance. Opposing ideas bring Bill into direct conflict with Nan. Marnie secretly plans out the strategy for her next step against the vampires in spite of Tara and Holly''s apprehension about the outcome.', 52, '2011-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 10, 'Burning Down the House', 'Bill needs Sookie to use her powers which results in breaking a spell. Jessica is implored to glamour Jason. Terry tries to help Andy with an intervention. Alcide reassesses his loyalties. Bill organizes the vampires to attack Marnie''s Moon Goddess Emporium while Jesus, Lafayette, Sookie and Jason attempt to free Tara and Holly.', 51, '2011-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 11, 'Soul of Fire', 'It''s up to Sookie and her powers to keep Bill, Eric and Pam from harm. While Jesus casts a spell, Lafayette is totally absorbed by the past. Sams gets even with Marcus and Alcide deals with Debbie head on. Andy''s foray into the forest is filled with deep, overwhelming emotion.', 48, '2011-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 4), 12, 'And When I Die', 'The souls of the dead rise up in Bon Temps. Sookie makes some important associations. Jesus and Lafayette''s connection is imperiled. Sam and Luna imagine a happy and perfect future. Sookie and Tara are confronted by Debbie.', 58, '2011-09-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 5, 'Season 5', 'The fifth season of the HBO supernatural drama series True Blood premiered on June 10, 2012 and features twelve episodes, bringing the series total to 60. It picks up right after the events of season four. It is loosely based on the fifth book in The Southern Vampire Mysteries series, Dead as a Doornail, but incorporates much more of the following books than the previous seasons have.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 1, 'Turn! Turn! Turn!', 'Sookie and Lafayette clean up the mess. Bill and Eric have a visit from the Vampire authority. Sam and Alcide come to terms with an angry pack.', 52, '2012-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 2, 'Authority Always Wins', 'Tara resurfaces in Bom Temps. Pam recalls her human life when she met Eric.', 55, '2012-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 3, 'Whatever I Am, You Made Me', 'Bill and Eric barter for their lives with Roman, the head of the Authority; Jason reunites with his old high school teacher; Sookie searches for Tara.', 59, '2012-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 4, 'We''ll Meet Again', 'Eric and Bill fear for their lives; Lafayette puts Sookie’s life in danger; Roman and Salome root out a Council traitor.', 56, '2012-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 5, 'Let''s Boot and Rally', 'Bill and Eric turn to Sookie for help with Russell’s whereabouts; Jason has a disturbing dream.', 47, '2012-07-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 6, 'Hopeless', 'Bill and Eric must now face Russell again after Roman is killed by him; Sookie and Jason go to a faery club where their family''s dark history and greatest secrets are revealed to them. Meanwhile, Sam volunteers to assist Andy with a case.', 51, '2012-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 7, 'In the Beginning', 'Salome reveals her true allegiances; Sookie embraces her human side; Sam sniffs out some perps; Alcide braces for a fight.', 57, '2012-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 8, 'Somebody That I Used to Know', 'The Authority revels in a new direction; Sookie and Jason visit the site of their parents’ deaths; Luna gets stuck on Sam.', 53, '2012-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 9, 'Everybody Wants to Rule the World', 'Vampires celebrate the start of the holy war; anti-supernatural zealots put Sookie in danger.', 57, '2012-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 10, 'Gone, Gone, Gone', 'Bill puts a spin on the rising vampire violence; Jason uncovers a mysterious scroll.', 48, '2012-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 11, 'Sunset', 'Bill slips into religious fervor; Sookie seeks insight from the faerie Elder.', 50, '2012-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 5), 12, 'Save Yourself', 'Eric tries to save Bill from losing his humanity.', 53, '2012-08-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 6, 'Season 6', 'The sixth season of the HBO supernatural drama series True Blood premiered on June 16, 2013. The season had an abbreviated run of ten episodes, as opposed to the usual twelve, partially to accommodate the pregnancy of lead actress Anna Paquin. It is also the first season not to be primarily based on the corresponding novel in The Southern Vampire Mysteries series, instead taking elements from multiple books in the series.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 1, 'Who Are You, Really?', 'A group flees the Authority compound in the wake of Bill''s reincarnation; Sam, Luna and Emma evade guards; Alcide learns about the packmaster job; Andy parents newborn human-faerie hybrids; Governor Truman Burrell vows open season on vampires.', 52, '2013-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 2, 'The Sun', 'Jason and Sookie meet a long-lost relative; Tara is victimized by a new government weapon; Eric attempts to thwart the governor''s anti-vampire initiatives; Sookie is drawn to a stranger; Alcide and Martha confront Sam about Emma''s future.', 51, '2013-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 3, 'You''re No Good', 'Eric is irate about Burrell''s aggression towards vampires; Bill enlists an innovator to synthesize a new type of blood; Sookie begins to learn why Warlow is after her; Sam receives unexpected help from Nicole; Steve Newlin struggles with his past.', 57, '2013-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 4, 'At Last', 'Sookie confronts her growing attraction to the mysterious Ben. Eric counters Burrell’s brutal anti-vampire initiatives by hitting his nemesis where it hurts the most. Growing up all too quickly, Andy’s faerie daughters end up keeping dangerous company. Sam and Nicole make a connection. Bill tasks Takahashi to synthesize a new kind of blood.', 55, '2013-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 5, 'F*ck the Pain Away', 'Wanting to finally learn the truth about her past Sookie recruits Lafayette to summon her parents while Warlow relives the events that led him back to Lilith after thousands of years, Eric and Tara attempt to rescue Pam.', 55, '2013-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 6, 'Don''t You Feel Me', 'Sookie escapes to a Fae land where Bill cannot influence her. Bill decides to seek Lillith''s advice. Eric, Pam, Nora, Jason and Jessica are in danger.', 55, '2013-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 7, 'In the Evening', 'Eric pledges loyalty to Bill as a last resort to save Nora. A tragedy close to home forces Sam to ignore the warnings of Alcide and return to Bon Temps. Jessica shows her gratitude to James, a prisoner.', 56, '2013-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 8, 'Dead Meat', 'Sookie faces a major dilemma in deciding whether to broker a deal between Warlow and Bill. Over in vamp camp, Jason gets to know Violet, while Sarah goes to extremes to keep Tru Blood flowing. Alcide makes a decision that will impact the futures of Nicole and Sam.', 57, '2013-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 9, 'Life Matters', 'A desperate Bill tries to ferry Warlow away from the faerie plain, but Sookie is having none of it. Meanwhile, Eric arrives at vamp camp, looking to inflict serious human damage. In Bon Temps, friends and family take emotional turns remembering a fallen neighbor. Bill feels the pull of Lilith’s sirens.', 53, '2013-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 6), 10, 'Radioactive', 'Jason feels a vampire attraction firsthand; and Bill finds that salvation isn''t free. Meanwhile, Sookie considers her future with Warlow as a new crisis poses a threat to humans and vampires alike.', 52, '2013-08-18');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')), 7, 'Season 7', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 1, 'Jesus Gonna Be Here', 'A band of rogue H-vamps crashes the vampire-human mixer at Bellefleur’s, with shocking results. As Sookie seeks refuge from accusations that she’s somehow to blame for the chaos in Bon Temps, the “one vampire for every human” plan moves forward. In the face of a vigilante insurrection led by redneck Vince, Bill receives aid from an unexpected source.', 50, '2014-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 2, 'I Found You', 'A trio of hostages taken in the Bellefleur’s attack looks to a familiar face as a possible liberator from the H-vamps. Sookie and Jason visit the neighboring town of Saint Alice, where a young woman’s diary offers clues to the potential fate of Bon Temps. Spurned by Lafayette, a desperate Lettie Mae turns to Willa to channel her family past. Vince whips his fellow vigilantes into a dangerous frenzy. Pam’s search for her maker leads her to a very familiar place.', 52, '2014-06-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 3, 'Fire in the Hole', 'Sookie hatches a dangerous plan to take down the H-Vamps, even as Vince and his armed vigilantes pose an equally serious threat. Lafayette gets high with James; Jason eyes a family future with Violet; Willa is forced to find a new place to stay; Sarah Newlin sheds her past. Pam offers Eric a compelling reason to return to Louisiana – and be the vampire he used to be.', 57, '2014-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 4, 'Death is Not the End', 'In the aftermath of yet another bloodbath, Sam, Sookie and Jason find themselves the bearers of bad news in Bon Temps and beyond. Pam recalls the events that led her and Eric to Shreveport and Fangtasia. Bill and Jessica get nourishment from unexpected sources. Following a new lead, Sookie enlists a band of vampires and humans to track down the H-Vamps.', 54, '2014-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 5, 'Lost Cause', 'Exhausted from her recent travails, Sookie finds herself the unwilling host of a festive mainstreaming party in Bon Temps. In search of an elusive adversary, Eric and Pam head to Dallas and attend a gala fundraiser. Andy makes a life-changing decision; Jessica and James reach a crossroads; Bill loses himself in remembrance of human days.', 58, '2014-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 6, 'Karma', 'Eric and Pam find a new ally in their search for a common enemy; Sookie makes a startling discovery that forces her to rethink her recent involvement with Bill; Lafayette shares a vision with Lettie Mae; Jason realizes how he really feels about Violet; Sam isn''t sure what to do about Nicole.', 57, '2014-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 7, 'May Be the Last Time', 'Sookie looks for a miracle; Eric and Pam zero in on Sarah Newlin; Adilyn and Wade seek protection from Violet.', 58, '2014-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 8, 'Almost Home', 'Eric mulls his options; Sookie puts her life on the line for Bill; Lettie Mae finds closure; Violet has revenge on her mind.', 53, '2014-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 9, 'Love Is to Die', 'Bill alienates Sookie; Hoyt remembers the past; Eric faces a dilemma.', 56, '2014-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0844441')) AND numero_temporada = 7), 10, 'Thank You', 'Sookie weighs a future with and without Bill. Eric and Pam struggle with their uncomfortable partnership with Mr. Gus. Sam makes a choice, while Andy comes upon an unexpected inheritance. Series Finale.', 64, '2014-08-24');
