INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')), 1, 'Season 1', 'Former pitcher Kenny Powers finds himself out of baseball and reduced to teaching Phys Ed at the North Carolina school he once attended. Wreaking havoc both at school and at the home of his brother Dustin where he crashes, the loutish, foul-mouthed Kenny plots his return to the majors . . . while trying to win back his former high-school squeeze April, now a teacher engaged to principal Terrence Cutler.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 1), 1, 'Chapter 1', 'Series premiere. Burned out and broke, former big-league pitcher Kenny Powers returns home to North Carolina to teach PE at the local middle school he once attended. Wreaking havoc at school, around town and at the home of his brother Dustin, Kenny settles into his role as the town''s loose-cannon agitator, setting his sights on winning back his high-school flame April, now a teacher engaged to the school principal, Terrence Cutler.', 30, '2009-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 1), 2, 'Chapter 2', 'Kenny tries to make extra money by pitching himself as spokesman for a luxury car dealership; Kenny and his driver make an appearance at the middle school dance.', 26, '2009-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 1), 3, 'Chapter 3', 'Stevie gets a scoop on Kenny''s possible competition when he hears of a promising young high school pitcher. Cassie wants to sell off all of Kenny''s baseball memorabilia on the computer. Meanwhile, Kenny makes a commitment to a new exercise regimen.', 27, '2009-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 1), 4, 'Chapter 4', 'Kenny attends a BBQ at April and Terrence''s house where his romantic feelings for April intensify. Later, Stevie puts together a DVD of Kenny''s greatest moments in the hopes that the major leagues will notice.', 27, '2009-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 1), 5, 'Chapter 5', 'Kenny decides to give up on his dream of returning to professional baseball. Meanwhile, arrogant car dealer Ashley comes back into the picture.', 30, '2009-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 1), 6, 'Chapter 6', 'Kenny gets an offer from a professional team and is forced to say goodbye to his family and teaching job.', 30, '2009-03-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')), 2, 'Season 2', 'Spurned by the big leagues and humiliated in his own hometown, Kenny Powers is heading south of the border to lick his wounds--and plot a comeback that might just land him back in the spotlight. In the wake of a bogus pitching offer, Kenny takes up residence in a small Mexican town and prepares to fashion a comeback scenario that involves a local baseball team and its filthy-rich owner.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 1, 'Chapter 7', 'Kenny Powers heads to Mexico to lick his wounds and start a new, more anonymous life. Befriended by a neighboring Mexican family and a sultry bar singer named Vida, Kenny emerges from "the darkest hole I''ve ever been in" by planning a comeback.', 29, '2010-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 2, 'Chapter 8', 'Charros owner Sebastian Cisneros agrees to pull out all the stops in promoting Kenny Powers’ return to organized baseball, but Kenny loses motivation after learning a secret about April from an old friend.', 29, '2010-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 3, 'Chapter 9', 'Puzzled by the Mexican fans’ lukewarm reception, Kenny starts a grassroots PR campaign to burnish his image. But it takes a vintage Powers flare-up to bring the fans to their feet. Kenny makes inroads with Vida by inviting her to Sebastian’s yacht party.', 28, '2010-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 4, 'Chapter 10', 'Though Charros fans respond to Kenny, he is warned by Roger about the perils of showboating. Kenny finds he has serious competition in his courtship of Vida. Stevie finds short-lived romance.', 29, '2010-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 5, 'Chapter 11', 'Kenny considers a new full-time life working in Mexico.', 28, '2010-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 6, 'Chapter 12', 'Kenny settles his debt with Sebastian; later, he settles a score with Aaron and Hector, and bids adios to Vida. Kenny passes a final test with the Charros team.', 29, '2010-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 2), 7, 'Chapter 13', 'Kenny confronts his future.', 31, '2010-11-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')), 3, 'Season 3', 'Picking up one year after Season Two, Kenny brings his boorish behavior to Myrtle Beach, SC and somehow resurrects his baseball career as the closer for the minor-league Myrtle Beach Mermen. Even as he postures himself as the new King of Myrtle Beach, Kenny struggles to come to terms with growing older, both in his personal life, and professionally with the arrival of some talented up-and-comers on the team.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 1, 'Chapter 14', 'In the third-season premiere, Kenny finds himself in Myrtle Beach, S.C., as the closer for a minor-league baseball team, but he also has a reunion with April for his son''s first birthday in his North Carolina hometown.', 29, '2012-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 2, 'Chapter 15', 'Kenny tracks down Stevie, who''s working at Ashley Schaeffer''s car dealership, when he heads north with the baby to find April.', 30, '2012-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 3, 'Chapter 16', 'Pro scout Roy McDaniel asks Kenny to take a promising Russian pitching prospect under his wing; Stevie takes stock of Shane''s status while negotiating his return to Kenny''s entourage.', 29, '2012-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 4, 'Chapter 17', 'Kenny thinks his son, Toby, is cursed, and might be to blame for a recent run of bad luck; and later tries to bond with Shane''s puritanical family. Meanwhile, Stevie is racked with guilt.', 29, '2012-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 5, 'Chapter 18', 'Kenny gets surprise visitors, and tries to regain control of the team by throwing the mother of all Fourth of July parties. Meanwhile, Stevie frets over delivering bad news to Maria.', 29, '2012-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 6, 'Chapter 19', 'Kenny tries a new pitch while attempting to be a better man and more responsible father; Stevie can''t shake his feelings of remorse.', 29, '2012-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 7, 'Chapter 20', 'Kenny hopes to get back on his coach''s good side and return to his spot on the pitching staff, but his bumpy ride on the road to redemption continues. Meanwhile, Stevie tries to make things right with Maria.', 29, '2012-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 3), 8, 'Chapter 21', 'As Kenny adjusts to the new realities of his life, a twist of fate alters his future with the Mermen.', 28, '2012-04-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')), 4, 'Season 4', 'Taking place several years after he made it back to the majors only to fake his death and head home, Season 4 finds Kenny a new man: working at a car-rental outlet, dabbling in screenwriting, attempting to enjoy couples nights. The vices of his playing days are a thing of the past...until Kenny runs into former teammates and current talk-show host Guy Young who convinces Kenny to get back in the game as a celebrity "titan" who deserves greatness and the lifestyle of the rich, famous and arrogant.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 1, 'Chapter 22', 'In the Season 4 premiere, Kenny Powers is now a family man—with his wife, April, two little kids and a home in the suburbs—but a night out with a former teammate and current TV star has him yearning to get back in the limelight.', 30, '2013-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 2, 'Chapter 23', 'Kenny visits Guy Young to discuss a career change, and tries to convince Stevie to rejoin the Powers team.', 30, '2013-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 3, 'Chapter 24', 'Kenny takes his family and friends on a trip to the local water park.', 28, '2013-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 4, 'Chapter 25', 'Kenny follows through on a threat; Stevie finds Kenny a charity to promote during Guy''s goodwill dragon boat race; Toby tries to find the courage to feed his new pet.', 30, '2013-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 5, 'Chapter 26', 'April gets Kenny to agree to undergo couples therapy; Kenny and Stevie plan a new business venture.', 27, '2013-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 6, 'Chapter 27', ' Kenny is rattled when Guy introduces a wildcard to the show; Stevie enlists Maria''s help to promote Kenny''s side business; April is frustrated with "Famous Kenny".', 29, '2013-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0866442')) AND numero_temporada = 4), 7, 'Chapter 28', 'Kenny''s personal life takes a toll on his work; Stevie keeps up appearances in the face of adversity; Kenny learns a valuable Christmas lesson.', 31, '2013-11-10');
