INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 1, 'Pie-lette', 'Ned works in a pie store and seems to lead a perfectly normal life. This, however, is far from the truth. Ned can, through the touch of his hand, wake people from the dead. He decides to use this ability of his to solve crimes, but this appears to be much more difficult than it sounds, when he gives life to his childhood crush, and decides to let keep living.', 42, '2007-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 2, 'Dummy', 'Ned, Emerson and Chuck visit the morgue to inspect the body of a victim of a car accident, a 45 year old man who specialized in automobile safety. The police is offering a reward to anyone who can find the killer and Emerson wants answers to be able to get the reward.', 42, '2007-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 3, 'The Fun in Funeral', 'Chuck holds true to the threat she made in the pilot by baking anti-depressants into her aunt''s food, in the form of Ned''s pies. Olive delivers one to them and stumbles onto Chuck''s secret. Now that she has dirt on Chuck - that her aunts think she''s dead - will Olive use it against her to get Ned?', 43, '2007-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 4, 'Pigeon', 'Emerson, Ned and Chuck are hired to prove that a pilot was murdered, rather than committing suicide, but soon become involved in a case of stolen jewelry and an escaped prisoner.', 42, '2007-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 5, 'Girth', 'In this Halloween episode, Emerson and Olive track down "the ghost" who''s been killing the jockeys at the old race arena where Olive used to race as a former jockey herself. With help from Ned and Chuck, they try to solve the big mystery.', 43, '2007-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 6, 'Bitches', 'Ned, Chuck, Emerson and Olive tackle a murder mystery involving a man who was murdered over a dog and claims to have been killed by his wife. Problem is, he''s a polygamist with four wives.', 42, '2007-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 7, 'Smell of Success', 'Ned, Emerson, and Chuck''s next case involves an olfactory assistant who was killed when her scratch-''n''-sniff book combusted.', 44, '2007-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 8, 'Bitter Sweets', 'Emerson, Ned and Chuck investigate the death of Tony DiNapoli, who appears to have been strangled by a woman. Meanwhile, business at the Pie Hole plummets when a new candy store opens in town.  Alfredo Aldarisio returns and continues to pursue an oblivious Olive who, herself, still pines for affection from the Pie Maker.', 43, '2007-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 1), 9, 'Corpsicle', 'Chuck learns the most shocking secret of her life and refuses to forgive Ned. In order to take the Pie Maker''s mind off of Chuck, Emerson gets him to solve the mystery of a man killing life insurance agents and hiding them in snow banks. Oscar Vibenius returns to investigate why Chuck has an unique smell. Meanwhile, the aunts'' antidepressant-laced pies begin to show some hallucinogenic effects.', 43, '2007-12-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 1, 'Bzzzzzzzzz!', 'Emerson is hired by Dusty Fitz, whose wife Kentucky died in a tragic bee-related incident. She was involved with another man who Dusty claims she was preparing to leave, and Dusty suspects murder. Meanwhile, Lily helps Olive move to a nunnery.', 44, '2008-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 2, 'Circus, Circus', 'Georgeann Heaps hires Emerson to find her missing daughter, and the trail leads to a circus. Meanwhile Ned and Chuck try to deal with the change in their relationship, and Olive considers staying longer at the nunnery.', 44, '2008-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 3, 'Bad Habits', 'Olive calls on the Pie Maker and Emerson to solve a suspicious suicide of a fellow nun that she believes is murder. Meanwhile, Chuck considers what to do in the present with her new lease on life.', 44, '2008-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 4, 'Frescorts', 'A sexy new client hires Emerson to solve the murder of her best friend Joe. Emerson and the gang discover that Joe had a lot of best friends... and they all had a reason to kill Joe.', 44, '2008-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 5, 'Dim Sum Lose Some', 'The wife of a murdered chef, Bao Di, hires Emerson to investigate the death of her husband. They soon discover that Bao was heavily in debt, and wagered his daughter Mei''s hand in marriage to cover his markers.', 43, '2008-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 6, 'Oh Oh Oh… It''s Magic', 'Ned agrees to help a famed magician whose animal assistants are being killed off; Dwight Dixon tries to cozy up to Lily and Vivian, but Lily is suspicious of his motives.', 44, '2008-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 7, 'Robbing Hood', 'A lawyer for the late Gustav Hoffer suspects his client''s death was not part of a robbery gone wrong as was reported, but rather murder.  He hires Emerson Cod and Ned to find out who killed Hoffer.', 42, '2008-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 8, 'Comfort Food', 'Ned brings back to life Colonel Likken, who was mysteriously deep fried to death.  His world-famous original recipe has gone missing and Likken asks Ned, Emerson, and Chuck to find who stole it.', 43, '2008-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 9, 'The Legend of Merle McQuoddy', 'Chuck and Ned deal with the shocking return of someone from their past; Emerson and Olive investigate the death of a lighthouse keeper.', 44, '2008-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 10, 'The Norwegians', 'After Emerson turns down Vivian''s request to look into Dwight Dixon''s sudden disappearance, she turns to another P.I. team led by Magnus Olsdatter, Emerson''s bitter rival.', 42, '2008-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 11, 'Window Dressed to Kill', 'Erin Embry, window dresser extraordinaire for Dicker’s department store, is killed and Chuck manages to get the Pie Hole gang on the case. Erin’s fans think it was her window-dressing partner, Coco Juniper, who did the deed. Apparently the two artistic minds did not always meet. Meanwhile, Ned loses his zapping ability which causes him a small crisis of identity. How can he assist in solving cases if he can’t undead and redead? How does it change his relationship with Chuck? And why are Ned and Olive posing as a couple?', 44, '2009-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 12, 'Water & Power', 'Lila Robinson, a beautiful grifter from Emerson’s past resurfaces, revealing a painful secret that Emerson has kept hidden all these years. Now on the lam for murder, Lila promises Emerson a quid pro quo if he clears her name.', 44, '2009-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0925266')) AND numero_temporada = 2), 13, 'Kerplunk', 'The past becomes the present when one half of the Darling Mermaid Darlings’ arch rivals, the Aquadolls, is killed. In order to find the murderer, the Darling Mermaid Darlings must come out of retirement with Ned as their manager and Olive as their stylist. Chuck, of course, cannot participate. Olive gets close to Sid, with whom she shares her experiences in gender discrimination, what with him being a male synchronized swimmer and her attending Vassar on a jockey scholarship. But was Sid jealous enough of the headliners to commit murder?', 44, '2009-06-13');
