INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0904208', 'Californication', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1204568'), 'SERIE', 'A writer tries to juggle his career, his relationship with his daughter and his ex-girlfriend, as well as his addiction to beautiful women.', '2007-01-01', 'https://m.media-amazon.com/images/M/MV5BMjAyMDM2ODExNF5BMl5BanBnXkFtZTgwNTI2MjkzMTE@._V1_.jpg');
