INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 1, 'Season 1', 'Novelist Hank Moody struggles to help raise his 13-year-old daughter, while carrying a torch for his ex-girlfriend Karen. His obsession with honesty and his self-destructive behavior are simultaneously destroying and enriching his career. . . all this in the city he loathes the most: Los Angeles.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 1, 'Pilot', 'A transplanted author suffers from writer''s block and is disappointed that his novel has been turned into a romantic comedy for the big screen. He also learns his ex is engaged and that their 12-year-old daughter is acting on her “emerging sexuality.”', 28, '2007-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 2, 'Hell-A Woman', 'Hank begins his blogging job at Hell-A-Magazine.  Karen is able to set Hank up with her friend Sonja by disguising the get together as a family dinner.  At dinner, Becca reveals how Hank met Karen.', 28, '2007-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 3, 'The Whore of Babylon', 'At a book signing, Hank gets into a scrap with the disgruntled director of the film based on his novel, and later runs into a woman whom he embarrassed and insulted on a blind date. Mia attempts to steal some of Hank''s work to use for her high-school creative-writing class.', 28, '2007-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 4, 'Fear and Loathing at the Fundraiser', 'Meredith convinces Hank to escort her to an environmental fundraiser. Coincidentally Bill and Karen are at the same event, where Karen makes a scene. Also, Hank runs into Dani and Charlie while they are in his office.', 28, '2007-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 5, 'LOL', 'Bill asks Hank to step in as a guest speaker at Mia''s creative writing class. During a radio interview, Hank talks about his writing and motivations. Meanwhile, Becca develops a crush on her guitar teacher Dave, but he ends up with Mia.', 28, '2007-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 6, 'Absinthe Makes the Heart Grow Fonder', 'Hank spends the night with a sexy surfer girl and in return she robs him. Mia wants more of Hank''s writing to pass her class, instead he offers her to help her with her own writing. Charlie wants to spice up the sex life with his wife, but she is not as fond of spanking as Dani is.', 28, '2007-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 7, 'Girls, Interrupted', 'Hank is disturbed by Becca''s negative reaction towards the concept of happy endings, even more so when he finds out that it is partially his fault.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 8, 'California Son', 'Hank''s father dies. Despite the memories of his father floating to the surface, he doesn''t want to go to the funeral. To ease his pain, he goes to bed with a hooker named Trixie, despite the fact he doesn''t have enough money to pay her. Meanwhile, Karen does her best to help him overcome the pain.', 28, '2007-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 9, 'Filthy Lucre', 'After the funeral of Hank''s father Al, Hank comes back to L.A. with a new manuscript, that he wants Karen to read. After receiving a bonus paycheck, he buys a new car for himself and a new guitar for Becca.', 28, '2007-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 10, 'The Devil''s Threesome', 'A new threesome including Hank and Charlie evolves from a meeting at the gym, while Karen and Marcy have a girl''s night out at which they decide to surprise Hank and Charlie.', 28, '2007-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 11, 'Turn the Page', 'Charlie and Dani represent Mia after she wrote a book that seems to have come out of Hank''s feather.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 1), 12, 'The Last Waltz', 'As Karen''s wedding to Bill nears, Hank struggles with accepting what appears to be inevitable. Bill informs Mia that he will not allow her book to be published and Hank has a unique solution to dealing with Becca''s surprise visitor.', 28, '2007-10-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 2, 'Season 2', 'This season, Hank and Karen will finally rekindle their long-lost romance. But their road to love will hit a major snag when Hank''s new job as biography writer for a legendary music producer lands him waist-deep in his three favorite vices — sex, drugs, and rock &amp; roll. Meanwhile, daughter Becca is growing up way too fast; best friend and agent Charlie and wife Marcy are working through the fallout from last season''s affair; and Hank''s newest book is a huge hit — for someone else, who stole the manuscript from him and is basking in her newfound, totally unearned fame. But nothing gets good old Hank down for long — it''s all just another day in the city for our favorite hedonistic scribe.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 1, 'Slip of the Tongue', 'After reuniting at the end of Season One, Hank and Karen decide to pack up and head to New York. As part of the reconciliation, Hank undergoes a grueling vasectomy at Karen''s request. Hank has an accident when he confuses a partygoer for Karen. Hank gets arrested for driving under the influence and assaulting an officer.', 28, '2008-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 2, 'The Great Ashby', 'Hank finds himself in jail after assaulting a mouthy police officer. Karen, still upset at Hank for his accident at the party, refuses to bail him out. Meanwhile, Charlie gets fired after his former assistant, Dani, plays the agency president a montage of Charlie’s self-pleasuring office sessions.', 28, '2008-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 3, 'No Way to Treat a Lady', 'Charlie wants to help Daisy with her porn career, while Hanks starts writing Lew Ashby''s biography. Becca has her first day at a private school, while Karen meets Sonja and Julian again.', 28, '2008-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 4, 'The Raw & the Cooked', 'Hank proposes to Karen right before a dinner party, to which Mia, Charlie, Marcy, Lew Ashby, Sonja and Julian are invited. Drugs and special circumstances turn the evening in an unexpected direction.', 28, '2008-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 5, 'Vaginatown', 'In order to distract Hank from his heartbreak, Ashby arranges a sex session with popular, yet incredibly annoying, celebrity chef, Chloe Metz. Charlie takes on a new client who’s eager to land the lead in a porn film called Vaginatown. Charlie meets with the film’s director and secures her the part, but only after investing $100,000 of his own savings.', 28, '2008-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 6, 'Coke Dick & the First Kick', 'Hank decides to seek out Lew Ashby’s long lost love, Janie Jones. Hank accidentally walks in on Julian going at it with a rocker chick he’s “mentoring”. Mia spends the day trailed by Rolling Stone reporter Annika Staley. The Runkle residence is transformed into the set of Vaginatown.', 28, '2008-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 7, 'In a Lonely Place', 'Hank attempts to find a love interest for Becca''s teacher. Charlie uncovers Marcy''s secret which could have fatal effects on their finances.', 28, '2008-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 8, 'Going Down and Out in Beverly Hills', 'Hank tries to get the truth about Ashby; Karen confronts the record producer; Marcy detoxes at her mother''s house; Charlie succumbs to temptation.', 28, '2008-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 9, 'La Ronde', 'Hank turns down an offer of sex which is unthinkable (for him). Karen gives in to Ashby''s asking and agrees to date him. Charlie and Daisy have a bonding moment over the film Dirty Dancing, while Marcy is still in rehab.', 28, '2008-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 10, 'In Utero', 'Hank awaits test results and reflects on his early days with Karen; Charlie begs Daisy to move out.', 28, '2008-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 11, 'Blues from Laurel Canyon', 'Ashby hosts a party to celebrate the publication of Mia''s book. Becca is devastated to catch Damien cheating on her.', 28, '2008-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 2), 12, 'La Petite Mort', 'Hank completes his biography of Ashby. Charlie is reduced to working at a car dealership. Sonja gives birth. Karen accepts a job offer back home in New York, forcing Hank and Becca to make painful choices.', 28, '2008-12-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 3, 'Season 3', 'This season Hank Moody’s life, like the economy, is officially turned upside down. The lack of writing assignments forces him to get a “real” job as a college professor while trying to keep wild child Becca on the straight and narrow with Karen still working in New York. Can he learn to keep “regular” hours and inspire the next generation of scribes? First, he''ll have to stay on the right side of the dean of students, the dean’s wife and a teacher’s assistant who’s immune to his charms… Meanwhile, Charlie’s returned to the mainstream -- he’s ditched the porn world for a job at a legitimate agency. His only problem is a boss/agency head who’s more interested in him than her clients (hello, Rick Springfield!). It would all be manageable with Marcy by his side, but she’s still bitter over his affair and is even back on the dating scene, which is further complicated since the two are platonically sharing the house – who can afford a divorce in a recession?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 1, 'Wish You Were Here', 'With Karen gone, Hank has to deal with a more and more rebellious Becca. Meanwhile, Charlie and Marcy move back together though they still plan to divorce each other.', 28, '2009-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 2, 'The Land of Rape and Honey', 'Hank starts working as college professor and soon gets into trouble while Charlie interferes with Marcie''s romantic life.', 28, '2009-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 3, 'Verities & Balderdash', 'Hank attends a university mixer and consoles his jilted assistant; Charlie celebrates his first talent signing.', 28, '2009-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 4, 'Zoso', 'Hank objects to Becca''s adult fashion sense; Hank and Charlie visit a strip club to discover the secret life of a talented student; Charlie and Marcy''s house sale goes awry.', 28, '2009-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 5, 'Slow Happy Boys', 'Hank has the apartment all to his bad self when Becca visits Karen in New York. Hank''s old buddy from Long Island pays a visit. Hank shows him an epic time. Hank and his talented pupil Jackie take their student / teacher relationship to the next level. Charlie and Marcy are finally hitting the sheets again.', 28, '2009-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 6, 'Glass Houses', 'Karen hatches a plan to move the family back to New York for good. Hank''s mighty pleased, but Becca''s crestfallen about leaving her new best friend, Chelsea. After inviting herself to Hank''s class, Karen meets the comely ladies of the university: T.A. Jill Robinson and sexpot student Jackie. Later on, tempers flare when Becca and Chelsea get into some serious trouble and Hank and Karen are forced to pay a tense visit to Chelsea''s parents, Felicia and Stacy Koons.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 7, 'So Here''s the Thing...', 'Hank''s attempts to set things right with Karen lead to even deeper entanglements with the campus ladies. In the meantime, Charlie tries to prevent Sue''s top client from leaving the agency and Becca scolds Hank for being a terrible role model for her.', 28, '2009-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 8, 'The Apartment', 'Hank''s in for a hedonistic night to remember when Jackie and two stripper friends arrive at his doorstep, unannounced. The next morning, before Hank can escort his new friends from the apartment, Charlie shows up with a verbally abusive Rick Springfield. Hank’s forced to hide the hung-over party girls all over the house after Jill and Felicia pay surprise visits. The charade reaches its boiling point when Dean Koons arrives on the scene, resulting in a messy catharsis by fire.', 28, '2009-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 9, 'Mr. Bad Example', 'When Becca and her friend Chelsea get into a brawl on campus, it leads to the revelation of one of Hank''s affairs. In the meantime, Charlie risks his job trying to hold Marcy off drug addict Rick Springfield.', 28, '2009-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 10, 'Dogtown', 'Hank takes Charlie out on the town to drown his sorrows after Sue Collini fires him for causing client Rick Springfield to leave the agency. Meanwhile, Karen, still miffed by Hank''s dalliance with Felicia, organizes a girls'' night out with Becca and Marcy.', 28, '2009-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 11, 'Comings & Goings', 'Karen drags Hank to an end of the semester goodbye luncheon at Felicia’s. Hank realizes he’s walked into a hornet’s nest as Felicia, Jackie and Jill all gang up on him. The Hank bashing is interrupted when Richard Bates, the novelist / professor Hank replaced at the college, pays a surprise visit.', 28, '2009-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 3), 12, 'Mia Culpa', 'As the Moodys at last prepare to move to New York, Becca tells Hank about an intimate coming of age experience she had. Hank’s stunned when Mia shows up at the house unannounced, in town with her slimy boyfriend / manager PAUL for a book signing. Hank fails to prevent Mia and Paul from hatching a devious publicity stunt, forcing Hank to finally share the long-buried heartbreaking secret with Karen. gives Charlie a career opportunity of a lifetime, but Charlie must confront the fact that he might be losing Marcy for good.', 28, '2009-12-13');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 4, 'Season 4', 'Hank Moody is back and he couldn’t be more screwed. A one-night misunderstanding has landed him in serious hot water, but his troubles don’t end there. Hank''s literary sex scandal has caused a sensation, even as he prepares to defend himself in court and tries to get Karen and Becca to speak to him, and a movie based on his stolen book begins production.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 1, 'Exile on Main St.', 'Just as Hank is released from a 72 hour jail period for assault he is picked up by Charlie and dragged off to show the recent events of F&P with Mia becoming public and dropped into a meeting with a young actress that wants to capitalize on the publicity, and make a movie out of F&P. whom which he later re-enacts F&P in her hotel room. The episode ends with Hank hearing from his lawyer that the assault charges have been dropped and he is then arrested for statutory rape.', 28, '2011-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 2, 'Suicide Solution', 'Hank is told he faces 3 years in prison because the DA wants to make an example of him. There are signs Marcy is pregnant. Hank tries to fix things with Becca. The episode ends as Hank high on drugs and liquor writes a letter to Becca and then passes out.', 28, '2011-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 3, 'Home Sweet Home', 'Hank takes advantage of the misperception that he tried to commit suicide and moves back home with Karen and Becca, but his daughter knows the truth; Charlie sets out to reach a sexual benchmark while a wealthy producer pursues Marcy.', 28, '2011-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 4, 'Monkey Business', 'Hank Moody is notified by his attorney Abby that he will be going to trial for statutory rape. But not before Hank hands the completed F&P script to Charlie, who promptly drags him to a meeting with the Director, producer Stu Beggs and eccentric financier Zig Samitaur, setting off a chain of events that leads to Hank and Charlie having to explain why there’s a dead billionaire in the bathroom.', 28, '2011-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 5, 'Freeze-Frame', 'After a personal grooming mishap, Charlie discovers that his vasectomy was botched and that Marcy''s baby could be his; Hank''s relationship with lawyer Abby gets more personal but a good deed yields a compromising photo that could ruin Hank''s life.', 28, '2011-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 6, 'Lawyers, Guns and Money', 'A sensational photo derails Hank''s case and threatens to destroy his movie project until his sincere love for Becca rescues his career, while Karen resuscitates her ex-husband''s relationship with his beautiful lawyer.', 28, '2011-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 7, 'The Recused', 'Forced by her relationship with Hank to recuse herself as his lawyer, Abby pitches the case to a senior partner on the golf course; Hank is dismayed by Karen''s growing relationship with artist Ben; Marcy and Stu ask Charlie to help them pitch a TV project.', 28, '2011-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 8, 'Lights, Camera, Asshole', 'Hank takes a gig rewriting dialogue on a zombie sequel but threatens his job when he hooks up with a sexy woman with close ties to the film''s female lead; Marcy tells Stu she''s pregnant but not that the baby may be Charlie''s.', 28, '2011-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 9, 'Another Perfect Day', 'Evicted from his apartment, Hank moves back in with Karen and Becca while he prepares for his trial and teaches his daughter to drive; while Karen''s out on a date with Ben, Becca and Pearl steal the Porsche and wreck it.', 28, '2011-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 10, 'The Trial', 'A nervous Hank discovers that he''s got good reason to panic when his trial turns into an all-out character assassination, with even friendly witnesses Charlie and Karen unable to portray him as anything other than a drunken, oversexed lout.', 28, '2011-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 11, 'The Last Supper', 'Found guilty of statutory rape, Hank buys a used Porsche and considers fleeing from Los Angeles, but instead enjoys one last night in the company of his friends and family.', 28, '2011-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 4), 12, '...And Justice for All', 'As Hank awaits sentencing, the lines between his real life and the movie based on his life blur as the film''s star hits on his ex-wife and he feels stirrings of passion for the actress hired to play Karen.', 28, '2011-03-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 5, 'Season 5', 'Hank Moody has become hip hop’s most wanted. Rich and powerful rap mogul extraordinaire Samurai Apocalypse is pimped-out famous – and hell bent on getting our bad boy writer into more trouble than he’s ever known. With Charlie chasing strange and pining over Marcy, and an insufferable 20-year-old Hank wannabe dating his beloved daughter Becca, Hank’s got more on his plate than ever in the town he hates to love.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 1, 'JFK to LAX', 'A few years have passed and Hank is living in New York but looking for a ticket out of town after his latest breakup. He accepts an invitation from Charlie to come to Los Angeles for a job writing a film starring rapper/actor Samurai Apolcaypse, then reunites with Karen, her former professor and now-husband Richard, and his daughter Becca, who now has a boyfriend named Tyler that is the spitting image of Hank himself ... in the worst possible way.', 28, '2012-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 2, 'The Way of the Fist', 'Hank passes on writing Samurai Apocalypse''s new movie but Sam won''t take no for an answer and drags Hank to a meeting with director Peter Berg, where they discover that Hank and Peter have shared more than just a love of the written word. Sam takes it on himself to get rid of Tyler, which makes things worse between Hank and Becca. Co-parents Charlie, Marcy and Stu have their hands full when Little Stuart exposes himself to a preschool classmate, and Charlie takes it upon himself to mend fences with the offended girl''s attractive mother.', 28, '2012-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 3, 'Boys & Girls', 'Hank hands a completed draft of "Santa Monica Cop" over to Samurai Apocalypse, but he still finds himself stuck in L.A. when he''s asked to take Kali, his "acquaintance" from the flight to Los Angles, out for a night on the town. Tyler crashes at Karen and Becca''s house while he recovers from his injuries. Charlie is rescued from  a serious parental crisis by Stuart''s nanny, Lizzie.', 28, '2012-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 4, 'Waiting for the Miracle', 'Hank receives an unwelcome surprise in the form of Carrie, ex-girlfriend and arsonist that he''s forced to invite along when Karen and Becca show up to invite him to a dinner party. Stu, Marcy and Bates'' talk of sexual proclivities leaves the Moodys searching for the nearest exit, but the party gets even more out of control when Carrie has a realization about Hank. Meanwhile, Charlie goes on a blind date with Mary, a "nice girl" who''s more than a little inexperienced.', 28, '2012-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 5, 'The Ride-Along', 'Charlie''s boyhood dream is realized and Hank''s worst nightmare comes true when Samurai Apocalypse invites the boys on a ride-along with the Santa Monica Police Department and takes them on a joyride that goes sexually awry for Charlie; Richard hits the bottle at a crowded Venice restaurant but Hank and the boys arrive to save the day for Karen and Becca, and Tyler realizes he''s seen Sam somewhere before.', 28, '2012-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 6, 'Love Song', 'When Samurai Apocalypse hits a lyrical roadblock with his protege, he calls on the best writer he knows: Hank Moody, who unites with Kali to imbibe, bear his soul, and write a song that takes Hank back in time to an era when he, Karen and Charlie were happier and life was simpler before "A Crazy Little Thing Called Love." But the present comes roaring back when Karen shows up at Hank''s door, worried that she made a mistake.', 28, '2012-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 7, 'Here I Go Again', 'Hank saves Karen from embarrassment with a drunk Richard, then covers for Richard by pretending to be dating a stripper named Holly, who takes a liking to Tyler and offends his girlfriend, Becca. Meanwhile, when she''s fired after an inappropriate encounter with Stu, nanny Lizzie calls on Charlie and allows their relationship to progress, only to have Marcy beg for her return.', 28, '2012-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 8, 'Raw', 'Hank is stuck reading Tyler''s screenplay but discovers some talent under that head of hair, even though the script appears to be disturbingly autobiographical account of the author''s relationship with Becca. Charlie and Lizzie''s love quadrangle with Stu and Marcy heats up, but when their bedroom games hit too close to home for Charlie, it may be off to therapy for all four of them.', 28, '2012-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 9, 'At the Movies', 'On the first day of production on Hank Moody''s latest movie "Santa Monica Cop," Stu has brought back his "F--king and Punching" director in hopes of creating a cinematic masterpiece, but Hank''s rendezvous with the film''s leading lady puts his relationship with Sam in jeopardy. Luckily for Hank, Stu and the production''s crew, Charlie has a backup plan.', 28, '2012-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 10, 'Perverts & Whores', 'Minus one agent and best friend, Hank crashes with his two favorite ladies, Karen and Becca. Looking for new representation, he meets with Hollywood power agent Larry Levine, who quickly sets a meeting with world-class filmmaker and Hank Moody idol Lars Manderhoff. It may be a match made in heaven when Lars surprises Hank with one of his favorite working girls, Trixie (guest star Judy Greer). Distraught over his personal losses, Charlie seeks comfort from Marcy while Lizzie enjoys her big break, a part in "Santa Monica Cop" courtesy of Stu.', 28, '2012-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 11, 'The Party', 'Hank overstays his welcome at the house of Karen and Richard and hits the road with one last stop at Malibar, where he runs into Lizzie, who uses her newly acquired acting chops to lure him back to the Runkle Manor. Once there, Hank is surprised by everyone he loves and loathes: Karen, Becca, Charlie, Marcy, Stu, Richard and his creepy sponsor, Gabriel. Even Sam and Kali show up, but it''s not a party until someone gets hurt and luckily for these partygoers, Hank has it in him for one final run-in with Tyler.', 28, '2012-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 5), 12, 'Hell Ain''t a Bad Place to Be', 'Hank discovers the bartender at a local watering hole is his late friend Lew Ashby and wonders if he''s in Hell. Richard makes a startling announcement about Hank and Karen. Hank tries to make things right with Becca, but her news about Tyler leaves him stunned. On the set of "Santa Monica Cop," Sam''s jealousy and fondness for firearms give Charlie an opportunity to show how much he loves his best friend and number-one client; Hank''s arsonist ex-girlfriend surprises him with a way for them to be together forever.', 28, '2012-04-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 6, 'Season 6', 'This season Hank collaborates on a musical with a rock star while taking up with his beautiful muse, Charlie and Stu compete for Marcy, Marcy falls under the spell of a radical feminist, and Becca drops out of college to become a writer.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 1, 'The Unforgiven', 'Hank Moody narrowly survives the aftermath of his scorned ex-lover Carrie; her attempted suicide to see them both together, free from the constraints around them. Charlie takes Hank to see Atticus Fetch, a rocker who is interested in turning "A Crazy Little Thing Called Love" into a Broadway show. Meanwhile, Karen, Marcy and Charlie have to deal with Hank, after a revelation about Becca.', 28, '2013-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 2, 'Quitters', 'Hank reluctantly heeds the advice from his family and friends, but Faith, muse to many-a-rock-star, may be his light at the end of the tunnel. Charlie runs into out-and-proud movie star Robbie Mac and finds himself taking drastic action in order to land the award winner as a client. Marcy loses her resolve with Stu, while Karen lands a new job.', 28, '2013-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 3, 'Dead Rock Stars', 'Hank and Faith attend a funeral. Later, Karen finds Hank in a compromising position. Robbie Mac and Ken take Charlie out on the town, which doesn''t sit well with Marcy.', 28, '2013-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 4, 'Hell Bent for Leather', 'Hank and Charlie''s meeting with Robbie Mac isn''t as promising as they hoped; and later, Hank reconnects with an entertainment exec he''d worked with. Meanwhile, Marcy, Ophelia and Karen swap tales over dinner, while Becca proves she''s her father''s daughter at a reading of her work.', 28, '2013-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 5, 'Rock and a Hard Place', 'Ken discovers Charlie’s secret. Atticus sends Hank and Charlie on a hunt, so they enlist the help of Hank’s daughter Becca. Marcy makes a decision about Stu that is influenced by her man-hating spiritual guide, Ophelia Robbins.', 28, '2013-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 6, 'In the Clouds', 'Karen asks Hank to intervene with Becca. Later, the boys board Air Force 69 with Atticus Fetch to fly to NYC to present the songs for the Broadway adaptation of "A Crazy Little Thing Called Love." Charlie faces a serious case of aerophobia. Atticus is surprised by Faith, while his wife surprises Hank.', 28, '2013-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 7, 'The Dope Show', 'Hank returns from his trip to find Becca spiraling, but his plan to help her backfires when they go to visit Atticus and meet his current house guest (guest star MARILYN MANSON as himself). Hank has an encounter that puts him in a very awkward position with Karen. Charlie takes Stuart out for the day and has an encounter of his own.', 28, '2013-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 8, 'Everybody''s a F**king Critic', 'The reviews are in for the first draft of "A Crazy Little Thing Called Love: The Musical." Hank looks for inspiration from Faith to help get him to the next level. Becca contemplates alternate careers. Charlie and Stu join forces to win back Marcy, but first, they''ll have to pry her from the man-hating clutches of Ophelia Robbins.', 28, '2013-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 9, 'Mad Dogs & Englishmen', 'Atticus throws a party. Faith provides the girls, The Dealer provides the recreation and Hank''s old friend provides the entertainment. Hank gets a taste of his own medicine with Karen. Atticus tries to recreate rock and roll folklore with one of his biggest fans while Charlie reunites with The Widow.', 28, '2013-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 10, 'Blind Faith', 'Hank seeks comfort from Faith, only to find her with Beckett. Hank meets two very important people in Faith’s life. On the home front, Becca has some big news.', 28, '2013-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 11, 'The Abby', 'Hank and Faith join forces to track down Atticus, but Becca is the only person who can really help. Marcy''s outing with Ophelia leaves her a little tied up and Charlie''s response to a curious message reveals the true feelings between the two exes. Karen has an epiphany about Becca.', 28, '2013-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 6), 12, 'I''ll Lay My Monsters Down', 'Hank makes a big decision about his future, which affects Faith. Charlie and Marcy also make a decision. The troops are rallied to ensure Atticus makes it to the Greek Theatre for his co-headlining gig with Marilyn Manson. A call from Becca and a visit from a dearly departed friend set Hank in motion.', 28, '2013-04-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')), 7, 'Season 7', 'He’s come a long way. After blowing every chance at love and happiness – and burning every bridge in Hollywood – Hank Moody is finally ready to put the past to bed. But as always, old indiscretions turn up to bite him squarely in the ass. Could it be too late to pull off a happy ending?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 1, 'Levon', 'Hank''s reunion with Karen doesn''t go quite as he planned. Meanwhile, Hank gets hired by the "Santa Monica Cop" showrunner, and a reporter asks to interview Hank for his college paper.', 28, '2014-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 2, 'Julia', 'Hank gets frustrated with his "Santa Monica Cop" coworkers on his first day in the show''s writer''s room, and he gets a surprise when he visits Levon''s apartment. Meanwhile, Charlie meets Rath''s new assistant; and Karen gets an unexpected surprise.', 28, '2014-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 3, 'Like Father Like Son', 'Hank gets his first episode assignment, much to the dismay of coworkers Terry and Hugh. Meanwhile, Levon tries to bond with Rath''s assistant; Charlie attempts to patch things up with Marcy; and Karen considers giving up on Hank.', 28, '2014-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 4, 'Dicks', 'Hank and Levon help Julia celebrate her new role. Meanwhile, financial trouble adds to Charlie and Marcy''s marital unrest, but a new client may put Charlie back in the black; and Levon tries to get some alone time with Melanie, but the Director keeps getting in the way.', 28, '2014-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 5, 'Getting the Poison Out', 'Levon enjoys a night with Nikki, while Karen, Hank and Marcy are forced to endure the company of Nikki''s creepy friend. Meanwhile, Charlie gets in over his head with a new client.', 28, '2014-05-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 6, 'Kickoff', 'A "Santa Monica Cop" kickoff party is hosted by Rath, where Hank conducts an intimate notes session with the show''s leading lady, and Hashtag Black eyes Julia. Meanwhile, Charlie manages head-case client Goldie; and Stu makes Charlie an offer.', 28, '2014-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 7, 'Smile', 'Rath demands a rewrite of Hank''s ''Santa Monica Cop'' script. Julia''s new boss, Dr. Dan, gives her some career advice, but Levon and Hank have other ideas. Charlie and Marcy consider Stu''s offer - until Atticus'' old rock ''n'' roll butler Krull offers an alternative solution to their money woes.', 28, '2014-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 8, '30 Minutes or Less', 'Hank has problems with Hashtag Black. Stu''s offer leads to fisticuffs.', 28, '2014-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 9, 'Faith, Hope, Love', 'Hank recalls turbulent times with Karen, a confused Becca, and their days with a happier Charlie and Marcy. Meanwhile, a nun helps Hank put things into perspective.', 28, '2014-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 10, 'Dinner with Friends', 'Hank entices Karen to have dinner with him, but Julia interrupts their romantic evening. Later, Charlie, Marcy, Krull, Levon and his new friend bring even more drama to the night; and chaos ensues when Stu assaults Charlie''s manhood.', 28, '2014-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 11, 'Daughter', 'Hank might soon be out of a job. Becca makes a big announcement.', 28, '2014-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0904208')) AND numero_temporada = 7), 12, 'Grace', 'Hank makes a life-altering decision. Series finale.', 28, '2014-06-29');
