INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')), 1, 'Season 1', 'University physicists Leonard and Sheldon know whether to use an integral or a differential to solve the area under a curve. But they don''t have a clue about girls. Or dating. Or clothes. Or parties. Or having fun. Or, basically, life. So when a pretty blonde named Penny moves in the apartment across the hall, the guys decide to get an education outside of the classroom. Boys, you have a lot to learn.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 1, 'Pilot', 'Brilliant physicist roommates Leonard and Sheldon meet their new neighbor Penny, who begins showing them that as much as they know about science, they know little about actual living.', 23, '2007-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 2, 'The Big Bran Hypothesis', 'Leonard volunteers to sign for a package in an attempt to make a good impression on Penny, but when he enlists Sheldon for help, his attempt at chivalry goes terribly awry.', 21, '2007-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 3, 'The Fuzzy Boots Corollary', 'Leonard asks a woman out after he finds out that Penny is seeing someone.', 22, '2007-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 4, 'The Luminous Fish Effect', 'Sheldon''s getting fired forces him to explore what life has to offer outside physics, leaving Leonard to take drastic action to snap his friend out of his funk.', 21, '2007-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 5, 'The Hamburger Postulate', 'Fearing he''s wasting his time on Penny, Leonard ends up making a connection with Leslie.', 20, '2007-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 6, 'The Middle-Earth Paradigm', 'Penny hosts a Halloween party, putting Leonard, Sheldon, Wolowitz, and Koothrappali through a new test of their social skills.', 21, '2007-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 7, 'The Dumpling Paradox', 'With Wolowitz AWOL with one of her friends, Penny''s recruited to fill in for him on the guys'' Halo team', 21, '2007-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 8, 'The Grasshopper Experiment', 'Raj''s parents set him up on a blind date, but just when he discovers he can talk to her, she shows interest in Sheldon.', 20, '2007-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 9, 'The Cooper-Hofstadter Polarization', 'When they''re invited to present at a physics conference, Sheldon''s reluctance to share the credit leads to a tiff between him and Leonard, and Penny''s intervention only exacerbates the situation.', 19, '2008-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 10, 'The Loobenfeld Decay', 'Leonard and Sheldon each lie to avoid seeing Penny''s concert, but Sheldon''s is a bit too complicated for his own good.', 21, '2008-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 11, 'The Pancake Batter Anomaly', 'With his friends knowing how sour he acts when sick—and avoiding him as a result—Sheldon is nursed by Penny, who hasn''t a clue what she''s in for.', 22, '2008-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 12, 'The Jerusalem Duality', 'With Sheldon rattled over meeting Dennis, a 15-year-old physicist who''s smarter than he, Leonard helps him look for a way to debunk Dennis''s research.', 20, '2008-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 13, 'The Bat Jar Conjecture', 'Sheldon finds himself booted from the gang''s Physics Bowl team and replaced with Leslie, so he forms his own team, hoping to prove he''s superior.', 22, '2008-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 14, 'The Nerdvana Annihilation', 'When delivery of another collectible leads to Penny''s lashing out at Leonard, he decides it''s time to give up his habit, much to his friends'' protestation.', 20, '2008-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 15, 'The Pork Chop Indeterminacy', 'The rest of the gang fall for Sheldon''s twin sister, and Leonard''s plan to win her heart is derailed when Sheldon declares he''ll be the one to decide who can date her.', 22, '2008-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 16, 'The Peanut Reaction', 'Penny wants to throw a surprise party for Leonard, but Sheldon''s indulgence at an electronics store throws her off-track.', 20, '2008-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 1), 17, 'The Tangerine Factor', 'Penny''s break-up spurs Leonard to summon the courage to ask her out, and each goes to Sheldon for advice on their upcoming date.', 20, '2008-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')), 2, 'Season 2', 'This season, Leonard gets a girl. So does Sheldon. Howard drives the Mars Rover into a ditch. Raj woos a terminator. Gorgeous girl-next-door Penny falls under the spell of Age of Conan. And super-smart, ueberconfident Leslie Winkler reduces mere men to spineless jellyfish.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 1, 'The Bad Fish Paradigm', 'Penny''s first date with Leonard goes awry; Penny finds Sheldon to be an unwilling confidant.', 22, '2008-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 2, 'The Codpiece Topology', 'A jealous Leonard reacts to Penny''s new guy by rebounding with Leslie.', 21, '2008-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 3, 'The Barbarian Sublimation', 'Sheldon creates a monster when he introduces Penny to online gaming.', 21, '2008-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 4, 'The Griffin Equivalency', 'Raj gets an inflated ego and makes a play for Penny after being referenced in a magazine article.', 21, '2008-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 5, 'The Euclid Alternative', 'Leonard and his friends stage an intervention to force Sheldon to face his fear of driving.', 20, '2008-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 6, 'The Cooper-Nowitzki Theorem', 'Sheldon and the gang are confused when a young grad student is attracted to him.', 21, '2008-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 7, 'The Panty Piñata Polarization', 'When Sheldon bans Penny from the apartment for numerous minor infractions, she decides to retaliate.', 21, '2008-11-10');
