INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 9, 'The White Asparagus Triangulation', 'Sheldon is thrilled when Leonard starts dating a woman who meets Sheldon''s stringent standards.', 21, '2008-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 10, 'The Vartabedian Conundrum', 'Leonard asks Penny for advice when his new relationship starts moving too fast.', 21, '2008-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 11, 'The Bath Item Gift Hypothesis', 'Penny starts dating Leonard''s handsome colleague; Leonard and his friends are tortured by Sheldon''s obsession with gift-giving etiquette.', 21, '2008-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 12, 'The Killer Robot Instability', 'Penny''s criticism of Wolowitz''s romantic life pushes him into depression and AWOL for a fighting robot battle the rest of guys are depending on him for.', 21, '2009-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 2), 13, 'The Friendship Algorithm', 'Sheldon creates a scientific procedure for making friends.', 21, '2009-01-19');
