INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 18, 'The Prestidigitation Approximation', 'Sheldon is baffled by Wolowitz''s magic trick. Meanwhile, Leonard realizes dating Priya may make it impossible to continue being friends with Penny.', 21, '2011-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 19, 'The Zarnecki Incursion', 'Sheldon''s online-game account is hacked by Todd Zarnecki, who then proceeds to steal all his items prompting the guys to go on a quest to retrieve them.  Penny, Bernadette and Amy discuss how Penny groomed Leonard to be willing to try various things and more adventurous boyfriend... for some other woman — Priya.', 21, '2011-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 20, 'The Herb Garden Germination', 'Sheldon and Amy decide to start several rumors about the others as a test. Meanwhile, Howard takes his relationship with Bernadette to even higher level.', 21, '2011-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 21, 'The Agreement Dissection', 'When Leonard spends too much time in the shower with Priya, Sheldon charges Leonard with two violations of the roommate agreement. However, before he can get too far, Priya uses her skills as a lawyer to nullify the charges due to the agreement''s vague wording, much to Sheldon''s dismay. When the guys take advantage of Priya''s skills in order to eat Greek food on pizza night, Sheldon goes to Penny, who invites him to a girls'' night out with Amy and Bernadette, which Sheldon agrees to after Penny mentions that they may be talking trash about Priya. After the girls drink some cocktails, they decide to take Sheldon dancing, which Sheldon reluctantly goes along with. After dancing, Sheldon takes an intoxicated Amy back to her apartment and as well as talking about Priya, meets a monkey who is addicted to smoking cigarettes. Amy tells Sheldon not to give in to Priya''s law skills, before kissing him and going to her bathroom to vomit.', 21, '2011-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 22, 'The Wildebeest Implementation', 'Raj attempts to cure his social anxiety disorder while Penny uses Bernadette to spy on Leonard and his girlfriend.', 21, '2011-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 23, 'The Engagement Reaction', 'When Howard finally breaks the news to his mom that he''s engaged to Bernadette, it lands her in the hospital.', 20, '2011-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 4), 24, 'The Roommate Transmogrification', 'When Bernadette receives her PhD, Wolowitz feels emasculated. Raj and Leonard swap places and Penny does something she''s regrets.', 21, '2011-05-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')), 5, 'Season 5', 'In season five, Penny and Leonard''s relationship is relaunched in full "beta test" mode, while Sheldon, Howard, and Raj discover the feminine mystique is something that cannot be easily graphed or calculated. As Sheldon makes begrudging amendments to his "Relationship Agreement" with his "friend-who-happens-to-be-a-girl" Amy Farrah Fowler, Raj contemplates an arranged marriage, and Howard is all-systems-go for both is NASA space launch and wedding to the spirited Bernadette.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 5), 1, 'The Skank Reflex Analysis', 'Penny is worried with how damaged her friendship with the guys will be in the aftermath of her sleeping with Raj while Sheldon becomes the leader of the paintball team.', 21, '2011-09-22');
