INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 7, 'The Proton Displacement', 'Sheldon seeks payback when Arthur "Professor Proton" Jeffries asks Leonard for help on a project instead of him. Raj gets upset at Howard for crashing his night with the girls.', 20, '2013-11-07');
