INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 12, 'The Hesitation Ramification', 'When Penny’s big acting break on NCIS is a bust, Leonard struggles to help her, which results in Penny asking Leonard a bold relationship question. Meanwhile, Raj and Stuart try to practice their social skills, and Sheldon navigates the intricacies of being funny.', 21, '2014-01-02');
