INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 14, 'The Convention Conundrum', 'After the guys can’t get Comic-Con tickets, Sheldon tries to hold his own convention and winds up spending a wild night with James Earl Jones. Meanwhile, the girls try to feel more mature by going to a fancy hotel for tea.', 21, '2014-01-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 15, 'The Locomotive Manipulation', 'Sheldon and Amy take a train ride to Napa Valley with Howard and Bernadette on Valentine''s Day. Leonard and Penny take Raj''s dog to the vet when she accidentally eats some chocolate.', 20, '2014-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 16, 'The Table Polarization', 'Leonard buys a dining room table and it causes Sheldon to reevaluate the changes in his life. Meanwhile, Wolowitz is offered a chance to go back to space and Bernadette struggles with whether or not to encourage him.', 20, '2014-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 17, 'The Friendship Turbulence', 'After arguing with Sheldon, Howard tries to make amends by taking him to NASA headquarters in Houston. Penny has second thoughts about quitting her waitressing job when her car dies. Amy gets involved in trying to find Raj a date.', 19, '2014-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 18, 'The Mommy Observation', 'When Sheldon visits his Mom in Houston, he is forced to confront a new reality. Meanwhile, Raj’s ‘Murder Mystery’ party starts some fights within the gang.', 21, '2014-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 19, 'The Indecision Amalgamation', 'While Raj is wracked with guilt when he tries to date two women at once, Penny wrestles with whether to take a role in a cheesy movie and Sheldon is torn trying to choose between two gaming systems.', 19, '2014-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 20, 'The Relationship Diremption', 'Sheldon faces a personal crisis after deciding he’s wasting his time with string theory. Meanwhile, a double date between Raj, Emily and the Wolowitzes ends in embarrassment for Howard.', 21, '2014-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 21, 'The Anything Can Happen Recurrence', 'To prepare for a date with Emily, Howard acclimates Raj to horror movies. Penny and Sheldon are upset when they discover Amy and Bernadette lied to avoid hanging out with them.', 19, '2014-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 22, 'The Proton Transmogrification', 'As the gang celebrates Star Wars Day, Sheldon has difficulty dealing with the recent death of Arthur "Professor Proton" Jeffries.', 21, '2014-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 23, 'The Gorilla Dissolution', 'A bad day causes Penny to reevaluate her life choices – including Leonard. Meanwhile, Howard and Bernadette struggle to care for Mrs. Wolowitz, and Raj gets relationship advice from Sheldon.', 19, '2014-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 7), 24, 'The Status Quo Combustion', 'Sheldon get upset about his career, the destruction of the comic book store and Leonard and Penny''s future living arrangements. Howard and Bernadette can''t keep hold of a caretaker for his mother. With his entire world changing around him, Sheldon considers a major move.', 21, '2014-05-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')), 8, 'Season 8', 'Sheldon is rescued from his soul-searching cross-country train trip (older but no wiser) and that means The Big Bang Theory gang''s all here to spread another gear''s cheer as TV''s most attended laugh seminar. Enrol in the comic curriculum to observe Leonard''s minor surgery, which signals a major catastrophe for Sheldon, Howard''s obsession over his mum''s relationship with friend-turned-freeloader Stuart and the unexpected results of Penny''s technique as a pharmaceutical sales rep. Discover ways to re-create proms not attended or holiday celebrations not especially beloved and play a new game based on Raj''s dating life. Savour online fan Fiction by Amy, watch Bernadette take indelicate command of some delicate family matters and, who knows, you might spot a cool special guest or two.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 8), 1, 'The Locomotion Interruption', 'Leonard and Amy make an unexpected trip to Arizona to fetch Sheldon; Penny interviews for a job at Bernadette''s company; Stuart''s relationship with Mrs. Wolowitz disturbs Howard.', 21, '2014-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 8), 2, 'The Junior Professor Solution', 'Sheldon is forced to teach a class as a Junior Professor and Howard decides to enroll in it. Meanwhile, Amy plays both sides when tension arises between Penny and Bernadette.', 20, '2014-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 8), 3, 'The First Pitch Insufficiency', 'Wolowitz feels nervous when he is asked to throw the first pitch at a Los Angeles Angels game. Penny and Leonard want to prove Sheldon wrong after he says he and Amy are the better couple.', 19, '2014-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0898266')) AND numero_temporada = 8), 4, 'The Hook-Up Reverberation', 'Raj''s honesty comes back to haunt him when his new girlfriend is unfriendly to Penny. The guys think about becoming part owners in Stuart''s store.', 19, '2014-10-06');
