INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt0972534', 'iCarly', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1543688'), 'SERIE', 'Carly hosts her own home-grown web show, iCarly, Carly and sidekick Sam''s regular webcasts ultimately feature everything from comedy sketches and talent contests to interviews, recipes, and problem-solving.', '2007-01-01', 'https://m.media-amazon.com/images/M/MV5BY2JlM2JiNmQtNTdhNy00MDljLThjNDQtZDExNWI0NTNhMjVlXkEyXkFqcGc@._V1_.jpg');
