INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 1, 'iPilot', 'Carly''s teacher, Ms. Briggs puts her in charge of the school talent show. After Freddie uploads the auditions, hosted by Carly and Sam, to the Internet, it becomes a huge sensation. So Carly and her friends decide to create a weekly variety show.', 24, '2007-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 2, 'iWant More Viewers', 'It''s Carly and Sam versus Freddie and Spencer in the ultimate competition to see who can attract more viewers to the show. Things go crazy when they carry out their plans.', 24, '2007-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 3, 'iDream of Dance', 'Carly and Sam get inspiration to dance from dance videos sent by fans of their web show. Carly struts her stuff in a dream with her charming partner.', 24, '2007-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 4, 'iLike Jake', 'After Jake, Carly''s crush, agrees to sing a song on the webcast, Carly gets extremely excited. But, it is soon discovered that Jake is a terrible singer, so Carly asks Freddie to digitally enhance Jake''s performance.', 24, '2007-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 5, 'iWanna Stay With Spencer', 'Carly''s grandfather comes for a visit and is appalled by Spencer''s unusual behavior, so he questions Spencer''s ability to be in charge. Carly must convince him that Spencer is capable of being her guardian.', 24, '2007-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 6, 'iNevel', 'Carly, Sam and Freddie want their show to be reviewed. Carly risks receiving a bad review when she insults the annoying eleven year old who runs a popular site that rates web casts.', 24, '2007-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 7, 'iScream on Halloween', 'Carly, Sam and Freddie do their Halloween webcast from an apartment that is rumored to be haunted. When creepy things start happening, the friends worry that the ghost rumors just might be true. Carly''s strangely secretive neighbor, Mrs. Halberstadt, adds to their anxiety. Meanwhile, when Spencer forgets to buy candy, he''s got a bunch of angry trick-or-treaters on his hands', 24, '2007-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 8, 'iSpy a Mean Teacher', 'The topic for the next iCarly webcast is figuring out what mean teachers do outside of school. When Carly and Freddie follow Ms. Briggs home, they get stuck inside her house.', 24, '2007-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 9, 'iWant to Date Freddie', 'Valerie, a girl from school, shows interest in Freddie, and they become boyfriend and girlfriend. She tries to tear Freddie away from iCarly to film her webcast and tries to recruit Sam, too.', 24, '2007-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 10, 'iWant a World Record', 'Carly, Freddie and Sam want to get into the world record book so they decide to try and beat the record for longest ongoing webcast. Meanwhile, Spencer builds an enormous sculpture.', 24, '2007-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 11, 'iRue the Day', 'The Plain White T''s are set to perform on iCarly, but Nevel plans to ruin the event by hacking into the site.', 24, '2007-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 12, 'iPromise Not to Tell', 'Carly gets a B on her history paper and becomes upset because she thinks she deserves better. Sam hacks into the school computer to change the grade and all is fine until Carly has to deal with her guilty conscience.', 24, '2008-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 13, 'iAm Your Biggest Fan', 'Carly invites her biggest fan to watch a live taping of iCarly but the girl is so obsessed that they can''t get rid of her. Meanwhile, Spencer discovers that his band puts up with him only to use his apartment to rehearse.', 24, '2008-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 14, 'iHeart Art', 'Spencer becomes depressed and uninterested in art after his idol criticizes his work. Carly tries to cheer him up by featuring some of his sculptures on the show.', 24, '2008-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 15, 'iHate Sam''s Boyfriend', 'When Sam''s new relationship starts affecting the web show, Carly and Freddie try everything to get Sam and her new boyfriend broken up. But the problem is, they cannot be separated. Meanwhile, Spencer attempts to make a Claymation film.', 24, '2008-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 16, 'iHatch Chicks', 'Carly and Sam have a science project to hatch chicks. When the eggs hatch earlier than expected, they have to search the apartment for the runaway chicks.', 24, '2008-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 17, 'iDon''t Want to Fight', 'Carly becomes angry at Sam after she trades the shirt Carly made her for concert tickets. Meanwhile, Spencer invents a contraption to feed his fish', 24, '2008-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 18, 'iPromote Techfoots', 'Daka Shoes wants iCarly to promote their new shoe, Techfoots. Carly accepts and tells all her viewers to buy the shoe. Unfortunately, the shoes are no good and fans began to complain. The gang has to find a way out of the contract. Meanwhile, Spencer expresses his dislike for public transportation after he falls asleep on a bus and ends up in Canada.', 24, '2008-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 19, 'iGot Detention', 'Carly''s show''s 50th airing is coming up but Sam gets detention. Carly and Freddie do bad things to get in detention to shoot the show from there. Meanwhile, Spencer drops his phone into a large coffee cup built by him', 24, '2008-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 20, 'iStakeout', 'The police use the loft as a stakeout to catch movie bootleggers; Spencer is shocked when one of the policemen turn out to be his childhood bully. Meanwhile, Freddie and Sam make a bet and the loser has to get a tattoo of the winner''s face.', 24, '2008-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 21, 'iMight Switch Schools', 'Freddie, Sam and her webcast, iCarly. Freddie and Sam scheme to make sure that Carly stays. Meanwhile, Spencer builds a mini golf course that becomes popular.', 24, '2008-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 22, 'iFence', 'Freddie''s in need of some guy time, so he tags along with Spencer to go fencing. Freddie''s a natural, but things get complicated when Spencer gets him involved in a match with the amazing Doug Toder. Meanwhile, Carly has to plan a dinner for her weird relatives, the Dorfmans, and with Spencer busy fencing, she might not get much help. Sam reveals that she has never read a real book, and a bet begins between her and Freddie: can Sam finish a book?', 24, '2008-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 23, 'iCarly Saves TV', 'A television programming director realizes that iCarly is funnier than anything his network currently has available for the upcoming fall lineup. Unfortunatley, upon acquiring the show, the network takes it further and further away from Carly''s original vision, and exploits and torments Freddie more than Sam and his mother combined.', 24, '2008-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 24, 'iWin A Date', 'Carly tries to get her web show viewers to take a boy in her school on a date.', 24, '2008-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 1), 25, 'iHave a Lovesick Teacher', 'Lauren Ackerman, Carly''s history teacher has become an emotional wreck after her boyfriend dumps her, and she takes her heartache out on everybody in class, including Carly. When Spencer discovers her agony during what passes for a parent-teacher conference, he decides to be her new knight in shining armor and fills the hole in her heart. Though things go smoothly for Spencer, Miss Ackerman, and her class at first, soon Spencer, Carly, Sam, and Freddie find that it''s going to take a lot more than just a little loving to keep the teacher happy, and her class safe.', 24, '2008-07-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 1, 'iSaw Him First', 'In the second-season opener, Carly and Sam both develop a crush on Freddie''s "nerd" pal, Shane. When they cannot decide who should date him, they decide to go by the first one to kiss him. They constantly try to kiss him, and always become unseccessful. Meanwhile, Spencer hires a repairman to fix the elevator, but the repairman proves to be no help at all, just a dancer. Because of the broken elevator, Shane accidentally falls from the iCarly studio to the basement when he finds out that Sam and Carly are competing for him. When the gang visits him at the hospital Carly kisses him.', 24, '2008-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 2, 'iStage an Intervention', 'Spencer finds a Pak-Rat video game cabinet in a junkyard and becomes addicted to it, whilst procrastinating on a commissioned Labradoodle sculpture. To curb his addiction, Carly brings Sasha Striker, the top Pak-Rat player in the world, to compete against Spencer to defend her title as the world champion of Pak-Rat. Meanwhile, Freddie experiences a streak of "bad luck" after deleting and not forwarding a chain email, passing it off as a superstition.', 24, '2008-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 3, 'iOwe You', 'Sam owes Carly and Freddie $526, so she gets a job to earn the money, and pay them back. Carly, Sam, and Freddie make a broadcast on iCarly to all their fans to donate money to Sam. However, they find out its illegal to solicit money over the internet. Meanwhile Spencer tries to impress an attractive single mom by helping her daughter sell fudge balls, an equivalent to Girl Scout cookies, but two scouts stole Spencer''s place at the market. Spencer comes up with the idea to send every iCarly fan who sent them money to send them fudge balls. Carly and Freddie then hire someone to give the money they earned to Sam in a tip. At the end, everyone enjoys what Sam got with her money except Spencer.', 24, '2008-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 4, 'iHurt Lewbert', 'Lewbert, Carly''s doorman, is injured during an exploding muffin basket prank. Spencer suggests that Carly, Sam, and Freddie help him until he''s back on his feet, but it is more easily said than done. When Freddie''s mother takes over, she makes it look easy, but leaves the group extremely concerned. Freddie''s mother and Lewbert fall in love. Meanwhile, while using a CB radio, Spencer upsets two truckers nicknamed Porkchop and Sledgehammer.', 24, '2008-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 5, 'iGo to Japan (1)', 'The iCarly gang travel to Tokyo after the show is nominated for a prestigious iWeb award.', 24, '2008-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 6, 'iGo to Japan (2)', 'The group lands in a deserted area of Tokyo, where they are found by a Japanese policeman who brings them safely to their hotel. They are visited by Kyoko and Yûki, the stars of a competing webshow. The pair give Spencer and Marissa free passes to a Nakamura Spa where their cousins work and take Carly, Sam and Freddie shopping.', 24, '2008-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 7, 'iGo to Japan (3)', 'After discovering Kyoko and Yûki''s sabotage attempt, Marissa locates the lost iCarly gang. The group reunites and gets to the iWeb Awards, but are apprehended when the guards do not understand English.', 24, '2008-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 8, 'iPie', 'When the group''s favorite pie shop closes down due to the death of the head chef, they go out to find the recipe for their favorite pie. The only person believed to have the recipe is the chef''s granddaughter. She agrees to give them the recipe if she can go on a date with Spencer. She takes it a bit too far, and confesses that she never owned the recipe. Carly, Sam and Freddie hatch a plan to find the recipe. Meanwhile, Mrs. Benson''s cousin''s baby visits for a few days, making Freddie uneasy about it because his cousin always has a blank expression when she sees Freddie. Freddie tries finding a way to succeed in making his cousin laugh.', 24, '2008-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 9, 'iChristmas', 'In an attempt to spice up the Christmas tradition with an unconventional tree, Spencer accidentally sets fire to all of Carly''s presents. Carly makes a wish that Spencer was born normal.', 24, '2008-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 10, 'iKiss', 'Freddie and Sam are in a prank war,  and Sam exposes to iCarly viewers that Freddie has never had his first kiss. Meanwhile, Spencer decides to train for the Seattle Cobras football team.', 24, '2009-01-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 11, 'iGive Away a Car', 'iCarly holds a giveaway contest for a new car -- won by their nemesis, Nevel Papperman. Meanwhile, Spencer buys a Galaxy Wars prop online.', 24, '2009-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 12, 'iRocked the Vote', 'The iCarly crew tells their viewers to vote for David Archuleta on America Sings, who is crowned the winner. Feeling guilty about swaying the votes, they invite the America Sings runner-up, Wade Collins onto their show. Meanwhile, Sam teaches Spencer how to lie so he can deceive a local video store.', 24, '2009-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 13, 'iMeet Fred', 'When Freddie offends an international internet sensation, Fred, he gets crushed and says to all of his fans that he will not make any more Fred videos. Carly, Sam, and Freddie soon start losing friends and acquaintances that are fans of Fred, and everybody in Ridgeway Jr High hates the iCarly group and Freddie is banned from all clubs. Then meet Lucas, Fred''s creator and portrayer, in his home in Idaho for Freddie to forgive him about the Fred videos comment. Lucas later apologizes because he wasn''t really mad, it was so Fred and iCarly had more ratings. At the end they apologize live in the iCarly webshow and presented a new Fred video with Carly, Sam, Feddie and Spencer guest starring as themselves with high-pitched voices like Fred. Meanwhile Spencer puts a Magic Eight Ball-like toy (called a "Magic Meatball") in control of his life, with disastrous results.', 24, '2009-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 14, 'iLook Alike', 'Sam, Freddie, and Carly search America to find three people who look like them the most. After being told that they''re not allowed to go to a Mixed Martial Arts fight, they bring the look alikes back to the studio to fake out Spencer while the go to the MMA fight.', 24, '2009-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 15, 'iWant My Website Back', 'Spencer gets a new credit card after canceling his old one, causing Carly, Sam, and Freddie to lose control of the iCarly.com domain. Luckily, Mandy (who appeared in "iAm Your Biggest Fan") returns to buy their website back for them, but she gets tricked into giving it to Nevel. Spencer disguises as an old woman to trick Nevel into signing the URL transfer document during a book signing, but is chased out by security after Nevel recognized him. Later, Nevel demands a kiss from Carly in return to claim the transfer document. Carly confronts Nevel, and Nevel signs the document. However Carly escapes with the signed document without having to kiss Nevel and succeeds in reclaiming their website.', 24, '2009-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 16, 'iMake Sam Girlier', 'Sam wants lessons from Carly on how to be girlier and be a better person to attract her classmate, Pete. At the end of the episode, Pete arrives at the Groovy Smoothie, ready to go on a date with Sam. The bully at school, Jocelyn also arrives to bother the iCarly team. So Sam beats her up, not knowing that Pete was watching. Meanwhile, Spencer starts sporting his tuxedo daily because he thinks it''s the reason why a woman he met likes him. He is convinced later that she doesn''t just like him in his tux because she kisses him (even though the tux is still on, so she might just like him with the tux on).', 24, '2009-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 17, 'iGo Nuclear', 'Carly has to do a project for green week, so she makes an electric scooter. But, it can only go for 4mph and it caught on fire, so she is given the weekend to make a new project. Spencer brings in a good-looking Science geek named Cal who helps her make a generator for iCarly, and Carly gets an A+. It is then revealed the generator was illegal and Cal was a criminal for buying Uranium, so she has to go on the Root-and-Berry Retreat to get extra credit.', 24, '2009-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 18, 'iDate a Bad Boy (1)', 'Carly and Spencer become upset when their new neighbor Griffin steals Spencer''s motorcycle. Spencer lets Griffin off the hook, making Carly upset. However, when Spencer later goes out to get smoothies, he returns to find Carly and Griffin kissing on the couch. Spencer becomes furious and forbids Carly to see him. Meanwhile, Sam pays Freddie $50 to make a website.', 24, '2009-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 19, 'iDate a Bad Boy (2)', 'With Spencer''s blessing, Carly and Griffin''s relationship advances happily and without flaw, until Griffin reveals that he obsessively and neurotically collects a series of stuffed animals called "Pee Wee Babies".', 24, '2009-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 20, 'iReunite With Missy', 'When Carly''s old friend Missy Robinson returns to Seattle, Sam believes Missy is trying to replace her as Carly''s best friend.', 24, '2009-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 21, 'iTake on Dingo', 'When Carly, Sam, and Freddie find out that a TV show on the Dingo Channel has been copying material from iCarly, the kids and Spencer go to Los Angeles to confront the writers of the show.', 24, '2009-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 22, 'iMust Have Locker 239', 'Sam and Freddie are forced to share a big locker after they both answered how many Fat Cakes that were in the inside the container. Meanwhile, Carly decides to take drawing lessons from Spencer, but she becomes frustrated with her brother''s teachings. Carly decides to take an art class in secret, but Spencer finds out, he embarrasses Carly and he tells the art teacher that art students should be spontaneous and passionate. The art teacher finally takes Spencer''s words into consideration and they share a passionate kiss. Sam decides to let Freddie have locker 239, she takes his money and she goes home with her mother after getting laser eye surgery. As a result, locker 239 gets destroyed, courtesy of Mrs. Puckett''s reckless driving, Freddie gets in trouble for the incident.', 24, '2009-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 23, 'iTwins', 'Freddie tries to prove that Melanie, Sam''s twin sister, is just Sam in disguise. Meanwhile, when Carly tutors Spencer''s nemesis, Chuck, Spencer tries to convince her that Chuck is evil.', 24, '2009-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 24, 'iFight Shelby Marx (1)', 'When Carly jokingly challenges MMA fighter Shelby Marx to fight, the two agree to have an exhibition fight for charity. Unfortunately, Carly accidentally falls on Shelby''s grandmother during a press conference. Thinking Shelby wants revenge, Carly backs out of the fight, only to be ridiculed as a coward.', 24, '2009-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 2), 25, 'iFight Shelby Marx (2)', 'Carly visits Shelby and apologizes, and the fight is back on. However, when Nevel Papperman alters a clip of the press conference to make it look like Carly intentionally tackled Shelby''s grandma, Shelby becomes furious and genuinely attacks Carly during their boxing match.', 24, '2009-08-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 1, 'iThink They Kissed', 'On iCarly, Sam''s tooth falls out, leading Carly to take Sam to the dentist. When the doctor gives Sam laughing gas, Sam accidentally reveals that she and Freddie shared a secret kiss with each other. Carly gets angry because friends aren''t supposed to keep secrets, but in the end she is OK with it. Meanwhile, Spencer teaches an art class in a prison, he and the prisoners build a big pair of pants that two prisoners hide in and jump out in Carly''s house and tape Carly Sam and Freddie to three chairs after Freddie threatens to call the Police.', 24, '2009-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 2, 'iCook', 'When Carly, Sam, and Freddie defeat a famous TV chef in a cooking challenge, the chef gives up cooking, quits his show, and refuses to come out of his bedroom. Spencer tries to make his vision of the future a reality.', 24, '2009-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 3, 'iSpeed Date', 'When Carly has trouble finding a date to a dance, Sam asks for Seattle-area boys to apply to be her date. When the gang is overwhelmed by the amount of boys who show up, they hold a speed-dating session. Meanwhile, Carly convinces Sam to ask Gibby to the dance since no one else did, but Sam becomes enraged when Gibby turns her down. Carly finally finds a boy, whom after the dance, she dumps for being so talkative. In the end, Carly and Freddie share a dance together at the Groovy Smoothie, which Sam walks in on. Upon seeing them, she silently leaves.', 24, '2009-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 4, 'iCarly Awards', 'Carly, Sam and Freddie present iCarly awards for best user-generated content; Spencer enlists the help of European swimsuit models to make statuettes.', 24, '2009-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 5, 'iHave My Principals', 'Principal Franklin is fired after appearing as a guest on iCarly; Spencer hires a rodeo star to teach him how to ride a mechanical bull.', 24, '2009-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 6, 'iFind Lewbert''s Lost Love', 'After a prank on Lewbert Sam loses her phone in his office, when her and Freddie get it back Sam steals a personal box from Lewbert’s office. Sam, Freddie and Carly look through it, only to find some interesting stuff about Lewbert, biggest him having had a girlfriend. Getting an Idea they set out to reunite him with her so he can be happy and leave them alone, only to find out Lewbert doesn’t exactly “like” her. Meanwhile after a rash of robberies Ms. Benson signs Spencer up to a watch group with a little pest from his past.', 24, '2009-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 7, 'iMove Out', 'After Mrs. Benson pushes Freddie too far by making Freddie eat asparagus while doing iCarly, showing people at school his baby pictures, and vacuuming his ear while he was sleeping, Freddie gets upset, moves out and gets his own apartment on the top floor of Bushwell Plaza. In the meanwhile, Carly, Sam, and Freddie start a pet photography business, only to see their studio destroyed by a snooty competing pet photography business owners Stewart Butler and Ollie Paisley. In the end, Marissa realizes she needs Freddie, begging him to return; Freddie makes her promise not to embarrass him in public ever again.', 24, '2009-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 8, 'iQuit iCarly (1)', 'Carly and Sam agree to help up and coming comedians Fleck and Dave make a contest-winning video, but when the two comedians fight and choose to end their friendship, Carly and Sam feel responsible. They try to patch things up between the two, only to find the problems ring familiar. Carly and Sam take sides and begin to fight.', 24, '2009-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 9, 'iQuit iCarly (2)', 'After arguing, Sam and Carly decide to end iCarly for good. Meanwhile, Spencer gets obsessed with winning a boat only to find out he has no place to put it.', 24, '2009-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 10, 'iSaved Your Life', 'Carly, unaware of an oncoming taco truck, is pushed aside by Freddie, who subsequently gets hit. Carly, grateful to Freddie for saving her life, develops an attraction towards him. However, Freddie thinks that this attraction stems from his actions, and not himself, so the two break up but agree that if the whole "hero" thing wears off that if Carly still feels attracted to him they''ll try the relationship again. Meanwhile, Sam and Spencer engage in an intense game of assassin.', 24, '2010-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 11, 'iWas a Pageant Girl', 'Sam admits she was a pageant girl after she stormed off the iCarly set. Desperate to defeat her rival she gets Carly to enter the pageant for her, only to take her place later. Meanwhile, Spencer and Freddie double date, however, the date goes bad when the two get caught up in a board game.', 24, '2010-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 12, 'iEnrage Gibby', 'Freddie feels the wrath of Gibby when he is caught getting too close to Gibby''s girlfriend. Elsewhere, reports of Spencer''s death are greatly exaggerated, but thanks to this newspaper error, Spencer sees a spike in sales of his artwork.', 24, '2010-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 13, 'iSpaceout', 'An eccentric billionaire asks the iCarly gang to perform a web show from outer space; Spencer is visited by a mysterious little girl.', 24, '2010-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 14, 'iFix a Popstar', 'Carly and her pals try to help a former pop star make a comeback video, but the task proves challenging when they realize the ex-star is all washed up. Elsewhere, Spencer is surprised to learn the new woman he''s been dating is Gibby''s mother.', 24, '2010-03-19');
