INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 17, 'iBelieve in Bigfoot', 'Carly and the gang try to prove that there is a Bigfoot somewhere out there.', 24, '2010-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 18, 'iPsycho (1)', 'Carly, Sam and Freddie try to cheer up a lonely fan named Nora on her birthday. Gibby does home repairs for Spencer in exchange for setting up a camp in the loft.', 24, '2010-06-04');
