INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 3), 20, 'iBeat the Heat', 'Spencer comes to the rescue when a heat wave hits Seattle and the power goes out.', 24, '2010-06-26');
