INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 1, 'iGot a Hot Room', 'Spencer tries to give Carly the best birthday ever. He lets Gibby''s grandfather cut his hair and Spencer makes Carly a gummy bear lamp. Everything thing goes bad after a gummy bear lamp Spencer made catches Carly''s room on fire. Spencer then finds out that his relative''s watch that Carly had was destroyed and was worth $82,000. Spencer convinces Carly to get a part-time job at the Groovy Smoothie while he, Freddie, Sam, and a working crew put together an amazing new room to Carly''s surprise.', 24, '2010-07-30');
