INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 3, 'iGet Pranky', 'After Carly recruits Spencer to help her prank Sam and Freddie, Spencer can not stop pulling pranks.', 24, '2010-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 4, 'iSell Penny-Tees', 'When the gang goes into business selling penny T-shirts, Sam recruits children in fourth grade to help make them.', 24, '2010-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 5, 'iDo', 'An iCarly fan proposes to his girlfriend live on the web show; Carly must come to the rescue when a bride gets cold feet.', 24, '2010-10-11');
