INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 8, 'iHire An Idiot', 'Carly and Sam hire an attractive male intern who winds up being bad at his job, so Freddie tries to convince them to fire the new guy', 24, '2011-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 9, 'iPity the Nevel', 'Nevel''s image is ruined after a video of him berating a child goes viral, so he asks Carly and the gang for help in restoring his reputation.', 24, '2011-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 10, 'iOMG', 'Carly and her pals work on completing assignments during a "lock-in" at their school. Carly and Freddie think that Sam has a new crush and assume the lucky guy is their intern, Brad. Freddie then uses his Mood Reader app, which confirms that Sam is in love but doesn''t specify with whom.', 24, '2011-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 11, 'iParty With Victorious (1)', 'Carly is dating a boy named Steven who divides his time between his divorced parents who live in Seattle and Los Angeles. Meanwhile, Tori is also spending time with her new boyfriend who, unbeknownst to her, is the very same boy Carly is seeing. The iCarly gang stumbles upon a photo of Steven and Tori on The Slap. André gets permission to host a party at Kenan Thompson''s house with his friends.', 23, '2011-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 4), 12, 'iParty With Victorious (2)', 'The iCarly gang disguise themselves and visit André''s party in Los Angeles after learning that Steven might be cheating on Carly.', 23, '2011-06-10');
