INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 2, 'iDate Sam & Freddie', 'Carly settles a disagreement between Sam and Freddie, and soon they rely on her to play peacemaker.', 24, '2011-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 3, 'iCan''t Take It', 'Gibby wants to sabotage Sam and Freddie''s romance, and Carly is torn about whether to help him.', 24, '2011-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 4, 'iLove You', 'Carly suggests that Sam and Freddie try each other''s favorite hobbies; Spencer asks his former babysitter to dinner. Also, Sam and Freddie go see her Uncle Carmine and his friend, Chaz, in prison. Chaz threatens Freddie so Sam and Freddie must come to terms with their relationship.', 24, '2011-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 5, 'iQ', 'Carly pretends to be very brainy to score points with her new boyfriend. Meanwhile, T-Bo needs to find a new home after he''s evicted from the Groovy Smoothie.', 24, '2011-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 6, 'iBloop 2: Electric Bloopaloo', 'Christopher Cane (Rex from Victorious) interviews the cast and shows their bloopers from the show. This is the sequel to iBloop, a Season 3 episode, where it showed every cast members'' bloopers during filming various episodes.', 24, '2011-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 7, 'iStill Psycho (1)', 'Nora has a parole hearing, and Carly, Sam, Freddie, and Gibby are invited to give their opinions whether she should be kept in prison or be released. After allowing her release, the group attends her welcome home party to celebrate her potential reform, but it turns out to be too good to be true. Meanwhile, T-Bo tries to act fancy to keep a room in Mrs. Benson''s apartment.', 24, '2011-12-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 8, 'iStill Psycho (2)', 'After Nora once again kidnaps the iCarly cast, they are forced to participate in a birthday party that lasts "forever and ever and ever and ever..."', 24, '2011-12-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 9, 'iBalls', 'Freddie decides he wants to be a creative member of the iCarly team which includes him wanting to perform on the show. Freddie wants to co-host the show with Sam while Gibby works the camera. Things, however, go awry. During the episode, Freddie broadcasts a web show with 3-D effects, which messes up people''s vision. Meanwhile, Spencer hires a personal assistant named Marty..', 24, '2012-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 10, 'iMeet the First Lady', 'It''s Carly''s dad''s birthday, and things don''t go as planned. He was supposed to come home for his birthday and celebrate it with Carly and Spencer, but can''t make it because of some emergency. Sam and Freddie feel bad about what happened so they connect her up with him through a video chat.', 24, '2012-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 5), 11, 'iToe Fat Cakes', 'After Sam wins a golden ticket for a Canadian Fat Cake VIP Tour, Sam, Freddie, Spencer, and Gibby go to the Fat Cake factory in Canada, but Sam''s greed finally gets the better of her when she tries to smuggle over 100 Fat Cakes over the border, since Canadian Fat Cakes are illegal in America.', 24, '2012-01-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')), 6, 'Season 6', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 1, 'iApril Fools', 'Carly and Spencer are being evicted from their apartment, and the gang reminisces about their time in Bushwell Plaza. Although, their memories may not be quite how we remember them.', 24, '2012-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 2, 'iGo One Direction', 'One Direction has accepted an invitation to perform on iCarly. Band member Harry becomes sick and Carly dotes over him. Realizing Harry is playing sick for the attention, they hatch a plan to get him back in the group by telling him Gibby has become their newest band member. Meanwhile, Spencer becomes a personal trainer and gives a bratty girl a makeover.', 24, '2012-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 3, 'iOpen a Restaurant', 'Sam and Gibby secretly operate a restaurant in the basement at school, while Spencer creates a security robot that goes haywire.', 24, '2012-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 4, 'iHalfoween', 'Carly, Sam, and Freddie wonder why people can''t celebrate Halloween more than once a year. They decide to celebrate it halfway through the year as well creating a new holiday termed "Halfoween" and have a party.', 24, '2012-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 5, 'iPear Store', 'When Freddie gets a new job at the Pear Store, Sam, who is employed with him, accidentally ruins it. Meanwhile, Spencer makes a fire for the 18th time and because of their tiredness, the fire department is done with the Shays and to apologize, Spencer brings a batch of brownies to the station. Unfortunately, the vengeful staff makes him volunteer at the fire station, which leads to another fire, this time at the station. Also, Carly meets a boy at the the Pear Store named Trey and becomes obsessed to get him to ask her out.', 24, '2012-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 6, 'iBattle Chip', 'After Spencer''s arch-nemesis Chuck pulls his latest prank on him and steals his clothes, Spencer finally gets rid of his nemesis by getting Chuck sent to military school. However, this causes Chuck''s younger brother Chip to hate Spencer and terrorize him more than Chuck did. Meanwhile, Gibby buys a Galaxy Wars toy phaser and becomes depressed when Sam accidentally breaks it while beating up a bully.', 24, '2012-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 7, 'iShock America', 'The iCarly Crew performs sketches on their show that spoof those on "Late Night with Jimmy Fallon," which the host finds so impressive, that he invites them on his show for a rare live performance. Thanks to some of Gibby''s usual misfortune however, the cast of both shows almost gets in trouble.', 44, '2012-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 8, 'iGet Banned', 'When Carly bans T-Bo from the loft, he retaliates by not letting Carly into the Groovy Smoothie. Meanwhile, Freddie and Gibby discover being in a band has many perks... and a few drawbacks.', 24, '2012-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 9, 'iFind Spencer Friends', 'The iCarly crew tries to find an adult friend for Spencer.', 24, '2012-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 10, 'iRescue Carly', 'Sam''s friend gets out of juvy and Sam warns everyone to stay away, but Carly doesn''t listen and finds herself in over her head. Back at the loft, Spencer finds a pair of night vision goggles.', 24, '2012-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 11, 'iLost My Head in Vegas', 'When Sam learns her Mom is in a Vegas jail, the gang decides to gather their most prized possessions, drive to Vegas and pawn their stuff to make enough money to bail her out.', 24, '2012-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 12, 'iBust a Thief', 'When Sam''s laptop gets stolen, the iCarly gang tries to help track down the thief. Meanwhile, Spencer can''t visit his favorite arcade unless he''s accompanied by a child. His luck turns when Guppy needs a babysitter.', 24, '2012-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0972534')) AND numero_temporada = 6), 13, 'iGoodbye', 'Carly is sad when her father cannot escort her to a military dance. Sam and Spencer fix a motorcycle. Gibby gets his head stuck in an "artificial head machine" (because he sold his first one at the pawn shop). Freddie gets a new phone.', 47, '2012-11-24');
