INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')), 1, 'Season 1', 'On the eve of Prohibition in 1920, Atlantic City county treasurer Enoch "Nucky" Thompson is looking to cash in. Prohibition may have outlawed alcohol, but in Nucky''s world it has opened up highly lucrative opportunities for gangsters and rumrunners looking to provide "liquid gold" for a thirsty nation. In a city defined by notorious backroom politics and vicious power struggles, Nucky battles a relentless federal agent, ambitious underlings, and opportunistic rivals—including Arnold Rothstein, Lucky Luciano, and Al Capone.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 1, 'Boardwalk Empire', 'January 1920. On the eve of Prohibition, Atlantic City''s Treasurer, Nucky Thompson, condemns alcohol at a Women''s Temperance League meeting, where he is noticed by Margaret Schroeder, a pretty, pregnant housewife who comes to him for help in getting her abusive husband Hans a job. Later that evening, the duplicitous Nucky privately tells his ward bosses about the opportunity to make huge profits selling bootleg liquor. At a countdown-to-midnight blast at Babette''s Supper Club, he assures Jimmy Darmody, a recently returned WWI vet, that his appointment as "Man Friday" to the new Chief Clerk of the Fourth Ward, Paddy Ryan, will lead to bigger things. Jimmy, meanwhile, has higher aspirations and ends up making an alliance that could have dire consequences for both him and Nucky.', 73, '2010-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 2, 'The Ivory Tower', 'Nucky deals with the fallout from Jimmy''s rogue heist, sending Eli to sow the seeds of doubt in the mind of Margaret, who seeks help in the wake of her husband''s demise.', 53, '2010-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 3, 'Broadway Limited', 'An unlikely witness to the woods massacre threatens to expose the perpetrators, sending both Eli and Van Alden rushing to the hospital. Margaret starts a new job at an upscale French dress shop at the Ritz, while Chalky''s team pays a heavy price for taking over Mickey Doyle''s bootleg operation.', 52, '2010-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 4, 'Anastasia', 'In Chicago, Jimmy bonds with one of Johnny Torrio''s prostitutes, Pearl, and finds himself increasingly at odds with the hot-headed Al Capone. Back in Atlantic City, Nucky looks to leverage his political relationships with ambitious U.S. Senator Walter Edge and Jersey City Mayor Frank Hague, while Eli and Chalky go to extremes to interrogate a local KKK leader.', 54, '2010-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 5, 'Nights in Ballygran', 'On the day of the annual St. Patrick''s Eve dinner, Nucky deals with Eli''s oratory ambitions, as well as a group of disenchanted "Leprechauns". Feeling ignored by Nucky, a frustrated Margaret feeds Van Alden information. In Chicago, Jimmy copes with the aftermath of a vicious attack orchestrated by Torrio rival Charlie Sheridan.', 54, '2010-10-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 6, 'Family Limitation', 'After the brazen robbery of one of his ward bosses, Nucky turns up the heat on Lucky Luciano. An emboldened Margaret stands up to Lucy at the dress shop and accepts an offer from Nucky to change her circumstances. In Chicago, Al''s frustration over family issues spills over into his relationship with Jimmy, who scores points with Johnny Torrio for a bold power play involving Sheridan and the neighborhood of Greektown.', 60, '2010-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 7, 'Home', 'After his father Ethan is injured in a fall, Nucky uses the opportunity to refurbish his childhood home. On a double-date with new friend Annabelle and her beaux, Margaret tries to get Nucky to open up about some painful childhood memories. During a visit to an army hospital, Jimmy befriends disfigured vet Richard Harrow, whose sharp eye proves invaluable. Van Alden gets a lead on the woods massacre.', 53, '2010-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 8, 'Hold Me in Paradise', 'Nucky visits Chicago for the Republican National Convention, where he finds himself intrigued by the candidacy of Warren G. Harding over more established candidates. The D''Alessio gang moves in on Nucky''s territory at the expense of Eli, who has been watching over his brother''s affairs. Margaret finds herself entangled in Nucky''s business affairs, while Van Alden struggles with his wife''s desire for a child. Rothstein prepares for legal trouble over his role in fixing the 1919 World Series. Nucky asks Jimmy to return to Atlantic City to reinforce his position.', 50, '2010-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 9, 'Belle Femme', 'Nucky is forced to readjust his political alliances with a Democratic mayoral candidate promising to wipe out corruption. Jimmy returns from Chicago to deal with the D''Alessio gang, which has allied with Rothstein to import European scotch through Atlantic City, but is arrested by Agent Van Alden for the massacre in the woods. Margaret intercedes with Nucky on Madame Jeunet''s behalf, while Angela finds her romantic and artistic ambitions halted by Jimmy''s return.', 53, '2010-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 10, 'The Emerald City', 'Nucky asks for Margaret''s assistance in backing his mayoral candidate with the passage of women''s right to vote, leaving her conflicted about her role. Doyle switches sides back from Rothstein, which leads Nucky to conspire with Chalky against Lansky and the D''Alessios. Angela witnesses Jimmy''s violent side against her photographer friend, and considers leaving Atlantic City for good in the aftermath. Van Alden grapples with his emotions, and has encounters with both Margaret and Lucy.', 59, '2010-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 11, 'Paris Green', 'Nucky has emotionally charged conversations with both Margaret and Eli over his business and the killing of Margaret''s husband. Jimmy meets with his dying father for the first time in years. Van Alden and Agent Sebso''s working relationship is pushed to the limit by Van Alden''s suspicions. Angela prepares to flee from Jimmy to Paris.', 57, '2010-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 1), 12, 'A Return to Normalcy', 'Nucky faces Election Day in Atlantic City and pulls out all the stops to keep power in Republican hands. Torrio brokers a discussion between Nucky and Rothstein to resolve their growing gang war, as well as Rothstein''s looming federal indictment over the World Series.  Both Jimmy and Eli voice their growing resentment towards Nucky, and find they have an ally in the Commodore. Van Alden seeks a sign on whether or not to leave Atlantic City, but receives unexpected news from Lucy. Margaret weighs new information about Nucky''s first marriage and her uncertain future to make a final decision on her role in his life.', 61, '2010-12-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')), 2, 'Season 2', 'It''s 1921 and after rigging the Atlantic City mayoral election, Nucky appears to be in control of the city. However, Nucky''s grip soon begins to unravel as he is arrested for election fraud and members of both his inner circle and family begin to question their allegiances, while mobsters including Arnold Rothstein, Lucky Luciano, Meyer Lansky, and Al Capone wait in the wings, looking for the right opportunity to grab a bigger piece of Nucky''s pie.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 1, '21', 'Nucky is shocked by an insurrection among his inner circle. An attack threatens Chalky''s life and livelihood. Margaret deals with her son''s problems. Angela vies for Jimmy''s affection. Van Alden shows his wife around town.', 54, '2011-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 2, 'Ourselves Alone', 'Despite being publicly embarrassed by legal trouble, Nucky''s biggest concern may be holding on to his private army in a battle for control of Atlantic City. Meanwhile, Jimmy pitches a business deal to Arnold Rothstein in New York, but may have more in common with Meyer Lansky and Lucky Luciano. Margaret draws on past experience to retrieve some valuable information, Chalky clashes with a fellow inmate, and an Irish nationalist comes to town looking for support.', 59, '2011-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 3, 'A Dangerous Maid', 'The Commodore throws his weight around with the Coast Guard to disrupt the delivery of alcohol, which creates an opportunity for Owen to demonstrate his value to Nucky and a struggling casino. Meanwhile, a letter dredges up painful memories for Margaret, Nucky calls in a favor with the U.S. attorney general, Meyer and Lucky learn the price of power, and Lucy searches for ways to cure her loneliness.', 56, '2011-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 4, 'What Does the Bee Do?', 'During Mayor Bader''s birthday party, Nucky''s attorney comes up with a solution that might help Nucky in his election-rigging case. With a liquor surplus likely, Jimmy and Mickey travel to Philadelphia to search for buyers while Nucky makes a surprising deal to try and get alcohol into Atlantic City. Eli is concerned over the Commodore''s ability to lead. Margaret decides to give her staff bonuses. Chalky is cornered while at work and home. Owen takes his munitions expertise and uses it. Van Alden''s agents set their eyes on Mickey''s warehouse. Richard lets his guard down in the name of art. And Gillian thinks of the first time she was ever with the Commodore.', 58, '2011-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 5, 'Gimcrack & Bunkum', 'After a dispute with his enemies, Nucky brings in a surprise guest speaker at a Memorial Day dedication for war veterans. Running out of options, Eli questions his allegiances, but it ends up sending him deeper into the hole. Nucky hires a new lawyer. Jimmy is taught a lesson by one of the Commodore''s men that he won''t soon forget. Richard decides to go hunting in the forest.', 50, '2011-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 6, 'The Age of Reason', 'Nucky tries to set up a risky liquor delivery to Philadelphia. Later, Attorney General Daugherty sees a problem that might complicate Nucky''s case. Jimmy finds a new mentor in Leander Whitlock who is the Commodore''s lawyer. Margaret finally goes to confessional. Lucy continues to struggle with loneliness while Van Alden tries to settle his conscience.', 59, '2011-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 7, 'Peg of Old', 'Margaret has a family reunion. Owen gets even with a rival. Van Alden recognizes the hierarchy of the law. Jimmy wonders how a decision will affect the future.', 59, '2011-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 8, 'Two Boats and a Lifeguard', 'In the wake of a personal loss, Nucky solicits advice on his political situation from Arnold Rothstein, while Eli remains suspicious of his brother’s actions. Nucky finds himself in the unfamiliar position of showing gratitude toward a federal agent. Angela meets a new friend at the beach, and eavesdrops on her husband’s treachery. Nelson gets a nanny. Nucky approaches Owen with an overseas proposition. Jimmy flexes his muscles, at Mickey Doyle’s expense.', 60, '2011-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 9, 'Battle of the Century', 'Arriving in Belfast, Nucky and Owen meet with IRA leaders with a barter proposition. Meanwhile, in Atlantic City, Jimmy and his partners broker a deal with George Remus for his “medicinal” alcohol before taking a break to see/hear the Dempsey fight. Margaret frets when Emily’s illness takes a turn for the worse. Dunn Purnsley orchestrates a worker’s strike at the Ritz. Waxey Gordon takes action against Manny Horvitz in Philadelphia, and Randolph and Clifford Lathrop grill Halloran about Nucky’s past.', 49, '2011-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 10, 'Georgia Peaches', 'Undercut by Nucky, who has a new source for alcohol, Jimmy and his partners look to cultivate a new revenue stream in Atlantic City. With the peak tourist season approaching, the Commodore’s crew faces a choice in dealing with the city’s striking workers; either negotiate or fight back. Fearing that sin has led to misfortune, Margaret approaches Father Brennan with an “act of devotion.” Nucky gets a new lawyer. Van Alden faces an uncertain future. Manny Horvitz takes exception to a debt payment.', 59, '2011-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 11, 'Under God''s Power She Flourishes', 'With Margaret pondering the consequences of sin, Nucky prepares her for a worst-case scenario as Esther Randolph plays out her trump cards. Jimmy revisits his college days with Angela and Gillian. Mickey Doyle chafes at sharing his liquor profits. Eli refuses to cop a plea. Nelson''s past comes back to haunt him, tipping the scale in Nucky''s favor.', 59, '2011-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 2), 12, 'To the Lost', 'Nucky faces a difficult, bottom-line business decision.', 58, '2011-12-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')), 3, 'Season 3', 'Atlantic City, 1922: The Roaring ''20s are about to begin in earnest and despite a booming economy, alcohol is scarce and gangster violence is heating up. Amidst this backdrop, Nucky, whose marriage to Margaret has become a sham after she signed away his highway windfall to the church, faces the challenge of mending old relationships while encountering new competition from hair-trigger gangster Gyp Rosetti, who builds a strategic bulkhead between New York and Atlantic City in an effort to siphon off Nucky''s alcohol business.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 1, 'Resolution', 'Nucky makes a resolution; Margaret considers a hospital expansion; Gillian builds a new business; Van Alden stumbles onto a confrontation.', 57, '2012-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 2, 'Spaghetti & Coffee', 'Mixing business with pleasure in New York, Nucky bristles at the collection tactics of Gaston Means, a “special investigator” with ties to Attorney General Harry Daugherty. At St. Theresa’s, Margaret is troubled when her altruism is met with resistance by both a patient and an idealistic doctor. Gyp extends his stopover in Tabor Heights, a town halfway between Atlantic City and New York, with an eye towards establishing a strategic foothold. Chalky and his daughter Maybelle (Christina Jackson) fail to agree on her future with Samuel (Ty Michael Robinson); Eli gets a new boss and faces new realities at home; a major liquor shipment takes an unexpected detour.', 58, '2012-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 3, 'Bone for Tuna', 'Disturbed by a recent nightmare and Billie’s absence, Nucky reluctantly joins Margaret to receive a high honor from the Church. Meanwhile, Gyp makes a deal with Nucky for a onetime liquor shipment, though the mobster’s longtime intentions remain very much up in the air. Van Alden regrets trying to socialize with his co-workers; Margaret takes her women’s-clinic pitch to a higher authority; Lucky and Meyer (Anatol Yusef) protect their investments; Richard sets the record straight with Mickey, and with Nucky.', 56, '2012-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 4, 'Blue Bell Boy', 'After tracking down a liquor thief, Nucky and Owen spend a long night hiding out from the fedswith the precocious perp. In his boss’ absence, and with Rothstein fuming over a late delivery, Mickey overrules Eli to make a routing call that will have far-reaching consequences for Nucky and Gyp. Margaret encounters a familiar face while promoting Dr. Mason’s classes at the new women’s clinic at St. Theresa’s. In New York, Lucky haggles with Joe Masseria over heroin splits, while in Chicago, Capone’s feud with O’Banion heats up when one of his collectors gets roughed up on the South Side.', 57, '2012-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 5, 'You''d Be Surprised', 'Rothstein vents to Nucky and delivers a message to Gyp. Gaston Means sees an opportunity. Billie gets a new co-start. Van Alden and Sigrid receive an unexpected visitor. Gillian worries about her business.', 59, '2012-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 6, 'Ging Gang Goolie', 'Nucky is detained in Washington; Margaret copes with Teddy''s demons; Owen investigates a suspicious fire; Richard makes a connection with a veteran and his daughter.', 56, '2012-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 7, 'Sunday Best', 'Eli hopes to get back in Nucky''s good graces; Gillian tries to improve her future; Gyp asks for a blessing in New York.', 59, '2012-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 8, 'The Pony', 'Gillian makes her peace with Jimmy''s death; Van Alden attends a meeting with Capone and Torrio; Nucky makes an offer to Andrew Mellon; Margaret makes a stand on birth control; Nucky and Owen shop for a pony; Billie considers a future in film.', 59, '2012-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 9, 'The Milkmaid''s Lot', 'Nucky vows to eliminate his nemesis. A high-profile bootlegger is arrested. Emily''s birthday party is scaled down. Gillian blames Harrow for Tommy''s trouble. Gyp decides to buy a town''s silence.', 54, '2012-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 10, 'A Man, A Plan...', 'Nucky tries to keep Jess Smith quiet and neutralize Gyp''s alliance with Joe Masseria; Margaret considers an alternate future; Van Alden''s side business backfires; Gyp''s shipment is short; Chalky sees an opportunity.', 58, '2012-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 11, 'Two Impostors', 'Gyp makes his move in Atlantic City, forcing Nucky and Eddie to seek refuge with Chalky. With the Artemis Club overrun by Rosetti thugs, Gillian contemplates a business future that includes an unwelcome partner. Luciano makes a deal he’ll come to regret. Harrow loses his house privileges.', 50, '2012-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 3), 12, 'Margate Sands', 'Nucky makes a deal with Rothstein as his war with Gyp Rosetti reaches its climax. Season finale.', 60, '2012-12-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')), 4, 'Season 4', 'Atlantic City, 1924: Nucky is laying low at the end of the Boardwalk after barely surviving an overthrow by gangster Gyp Rosetti. But the calm will be short-lived, as Nucky faces new challenges, including a clash with a violent Harlem power broker, a battle with his brother Eli over Eli''s college-age son, and the irresistible lure of lucrative—and perilous—opportunities in Florida.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 1, 'New York Sour', 'Following his battle with Gyp Rosetti, Nucky makes a peace offering to Joe Masseria while working the odds with Arnold Rothstein. While Chalky is busy running the Onyx Club on the Boardwalk, the impulsive Dunn Purnsley clashes with a booking agent. Fresh-faced Federal Agent Warren Knox arrives in Atlantic City to learn the ropes from Agent Sawicki. Gillian seeks custody of her grandson, Tommy, while trying to find a “good” man to keep the Artemis Club afloat. Eli’s college-age son, Willie, turns to Nucky for career advice. Al Capone enlists his brothers, Frank and Ralph, to help him expand his business in the Chicago suburb of Cicero. Richard Harrow returns to his violent ways.', 59, '2013-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 2, 'Resignation', 'Now working as a “delivery man” for Dean O’Banion, Van Alden is ordered to keep tabs on Al Capone, joining the ascendant mobster to help keep Cicero voters “informed” at a political rally. Dr. Valentin Narcisse arrives in Atlantic City, clashing with Chalky and Nucky over the loss of an employee. In Washington, Agent Knox aligns himself with J. Edgar Hoover, acting director of the Bureau of Investigation. Harrow fails to finish a job in Milwaukee, while Eddie demands a promotion after 11 years of service. With a business opportunity on the horizon, Nucky departs for Florida.', 58, '2013-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 3, 'Acres of Diamonds', 'Nucky has reservations about investing in a Tampa land deal engineered by transplanted bootlegger Bill McCoy. While there, he meets speakeasy owner Sally Wheet. Valentin Narcisse books a sexy jazz singer, Daughter Maitland, to perform at the Onyx, and gauges Dunn Purnsley’s allegiance to Chalky. Willie, Eli’s son, turns to Mickey Doyle and his bootleg warehouse to elevate his social standing at college. Gillian agrees to pose as Roy Phillips’ wife to impress a possible partner. Harrow tries to bury his past, though not before taking care of some unfinished business with Emma.', 56, '2013-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 4, 'All In', 'Nucky gets to know Arnold Rothstein over a card game, and sizes up an unexpected partner for his Tampa land deal. A newly promoted Eddie Kessler gets detoured after making a train-station delivery. When one of their collectors is incapacitated, Al and Frank Capone decide to finish his route, enlisting a reluctant Van Alden to tag along. Agent Knox fills Hoover in on the Thompson operation, vowing to exploit Nucky''s weakest link. Chalky is intrigued by Daughter Maitland’s presence. Dunn Purnsley goes to Harlem, and is courted by Valentin Narcisse. Willie and his college roommate, Clayton, carry a practical joke too far.', 57, '2013-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 5, 'Erlkönig', 'Nucky heads to Philadelphia; Agent Knox detains Eddie Kessler to obtain information about Nucky''s organization; Gillian tries to score a fix; Van Alden is recruited by the Capones.', 59, '2013-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 6, 'The North Star', 'Nucky heads to Tampa to work out details of his land deal with Bill McCoy; Richard Harrow returns to Atlantic City; Agent Knox tries to gain Eli''s trust; Chalky takes out his frustrations on Daughter Maitland.', 59, '2013-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 7, 'William Wilson', 'Eli confronts Nucky after Willie makes an unpopular decision. Margaret has a surprise encounter at her job on Wall Street. Joe Masseria orders Lucky Luciano to return to Tampa and deal with Vincenzo Petrucelli. Gillian goes cold turkey, with Roy Phillips’ help. Still seething over his brother’s death, Al Capone tries to get Johnny Torrio to turn on rival gangster Dean O’Banion. As Chalky White and Daughter Maitland’s relationship deepens, Valentin Narcisse exerts his control over Dunn Purnsley and the Northside.', 57, '2013-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 8, 'The Old Ship of Zion', 'Nucky’s shipment from Florida arrives with some unexpected cargo. Eli is backed into a corner after Agent Knox uncovers some new dirt on the Thompsons. After talking things over with Nucky, Willie reconsiders his recent life choices. Chalky throws down the gauntlet toward Valentin Narcisse, upholding his leadership on the Northside.', 58, '2013-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 9, 'Marriage and Hunting', 'Nucky refuses to back Chalky in a conflict; Gillian makes her custody case in court; Van Alden stands up to Capone and comes clean to O''Banion; Rothstein tries to make a trade.', 57, '2013-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 10, 'White Horse Pike', 'Nucky enlists Eli and Agent Knox to check the cargo in the Florida shipments; Margaret considers making a deal with Rothstein; Capone grows suspicious of Torrio; Nucky faces a dilemma.', 54, '2013-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 11, 'Havre de Grace', 'Nucky takes inventory after being warned of a skunk in his cellar. On the lam following a close call, Chalky and Daughter take refuge outside Wilmington with Oscar Boneau, his mentor from years ago. Gillian considers selling her mansion and starting a new life with Roy Phillips.', 58, '2013-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 4), 12, 'Farewell Daddy Blues', 'Eli braces for the worst as Agent Knox launches his plan to bring Nucky down. Capone and Torrio reach an agreement in Cicero. Chalky looks to settle scores. Richard steps forward to save Tommy, at Gillian’s expense', 57, '2013-11-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')), 5, 'Season 5', 'It''s 1931 and in stark contrast with the Roaring ''20s, the country is now in the throes of the Great Depression. With the end of Prohibition in sight, Nucky looks to legitimize himself by forging alliances with liquor producers.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 1, 'Golden Days for Boys and Girls', 'Nucky reminisces about catching the Commodore''s eye; Nucky joins Sally Wheet in Cuba; Margaret finds herself in the hot seat; Chalky tries to extricate himself from a difficult situation; Lucky Luciano sets a bold plan in motion.', 58, '2014-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 2, 'The Good Listener', 'Nucky pays a visit to Johnny Torrio; Eli and Van Alden must recoup money lost during a federal raid by Eliot Ness; Willie has a job interview; in 1884, young Nucky deals with the death of his sister.', 56, '2014-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 3, 'What Jesus Said', 'Chalky heads in a new direction; Margaret finds herself in a quandary; Nucky hosts a prospective partner from Boston; Luciano and Siegel meet with Narcisse in Harlem; in 1884, young Nucky flirts with a girl.', 54, '2014-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 4, 'Cuanto', 'Nucky and Margaret find common ground in Atlantic City; Luciano encounters an old adversary; Sally Wheet makes a payment in Cuba; in 1884, young Nucky moves up the Commodore''s ladder.', 59, '2014-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 5, 'King of Norway', 'Chalky returns to Atlantic City; Nucky arranges a meeting with Maranzano; Eli reunites with June.', 54, '2014-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 6, 'Devil You Know', 'Federal agents enlist the help of Eli and Van Alden to take down the Capone organization.', 58, '2014-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 7, 'Friendless Child', 'Nucky tries to hold onto his assets in Atlantic City; Willie and Eli become involved in Nucky''s war.', 57, '2014-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0979432')) AND numero_temporada = 5), 8, 'Eldorado', 'Nucky plans to relocate to Manhattan; Margaret impresses Nucky and a grain company stockholder.', 60, '2014-10-26');
