INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')), 1, 'Season 1', 'The complicated life of a modern-day first-generation Indian American teenage girl, inspired by Kaling''s own childhood.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 1, 'Pilot', 'After recent trauma, Devi starts her first day as a high school sophomore determined to shake off old labels and finally become cool.', 28, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 2, '... had sex with Paxton Hall-Yoshida', 'Devi hesitates to tell her friends the truth about her awkward interactions with Paxton. The prospect of an arranged marriage puts Kamala under pressure.', 30, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 3, '... gotten drunk with the popular kids', 'Devi hopes to win cool points with Paxton at a party, until a surprising turn of events. Hidden emotions emerge for Fabiola. Kamala makes a choice.', 30, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 4, '... felt super Indian', 'At Ganesh Puja celebrations, Devi questions how much she identifies with Indian culture, Nalini dodges acerbic aunties and Kamala frets over her future.', 22, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 5, '... started a nuclear war', 'Devi allows rumors about her and Paxton to swirl during an overnight school trip. Fabiola opens up to Eleanor, who gets upsetting news about her mother.', 29, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 6, '... been the loneliest boy in the world', 'With absentee parents, a shallow girlfriend and no one to hang out with, Ben Gross is lonelier than ever, until an unlikely invitation offers some hope.', 23, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 7, '... been a big, fat liar', 'Devi oversteps several boundaries in an attempt to be a better friend. Eleanor’s reunion with her mother leads to multiple revelations and confessions.', 25, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 8, '... pissed off everyone I know', 'After another fallout with her friends, Devi grapples with unresolved trauma. A party at Ben’s turns out to be equal parts awkward, awful and amazing.', 29, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 9, '... had to be on my best behavior', 'Flashbacks unearth painful memories and resentment for Devi. Meanwhile, Kamala is forced to get honest as the family welcomes her suitor at home.', 24, '2020-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 1), 10, '... said I''m sorry', 'After unwelcome news sparks a fight with her mother, Devi seeks an escape. Mohan’s birthday brings an opportunity for closure — and for new beginnings.', 29, '2020-04-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')), 2, 'Season 2', 'A new love life, a new classmate and new reasons to bicker with mom give Devi plenty more ways to make courageous moves... and questionable decisions.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 1, '… been a playa', 'Ahead of their impending move to India, Devi faces her first-ever love triangle, while Nalini tries to sell her patient roster to a flashy competitor.', 28, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 2, '... thrown a rager', 'Devi plans to throw the ultimate party, but her knotty dating life may turn it into a different kind of blowout. Nalini has an eye-opening trip to India.', 32, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 3, '... opened a textbook', 'Making good grades has never been a priority for Paxton — until a mishap urges him to prove he’s more than a campus heartthrob and star swimmer.', 27, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 4, '... had an Indian frenemy', 'Devi instantly resents the new Indian girl at school, but is taken by surprise as they get acquainted. Kamala struggles to be respected at her lab.', 28, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 5, '... ruined someone''s life', 'At a 24-hour school relay, Devi’s impulsive words spark an insensitive rumor. Fabiola hesitates to introduce her overenthusiastic mother to Eve.', 29, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 6, '... betrayed a friend', 'While attempting to cover her trail for fueling gossip about Aneesa, Devi''s guilt grows. Nalini warms up to a nemesis. Kamala gets a rude shock.', 27, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 7, '... begged for forgiveness', 'Devi must learn the art of a genuine apology before it’s too late. Kamala considers standing up for herself. Nalini takes some parenting advice.', 29, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 8, '... been Daisy Buchanan', 'Watching an ex with someone new tests Devi’s resolve to be more mature. Fabiola struggles to stay true to herself, and grows concerned for Eleanor.', 28, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 9, '... stalked my own mother', 'A disastrous snooping incident compels Devi and Nalini to do some introspection. Paxton steps out of his comfort zone. Eleanor has a breakthrough.', 31, '2021-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 2), 10, '... been a perfect girl', 'As Paxton''s mixed messages have Devi questioning herself, the upcoming winter dance offers a chance to determine where she stands — and what she needs.', 31, '2021-07-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')), 3, 'Season 3', 'Devi and her friends may finally be single no more. But they''re about to learn that relationships come with a lot of self-discovery — and all the drama.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 1, '...been slut-shamed', 'At last, Devi is dating her dream guy, but some catty gossip has her worried about taking things slow. Nalini urges Kamala to rethink a decision.', 30, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 2, '...had my own troll', 'Anonymous messages about Paxton have Devi playing detective. Aneesa feels neglected by Ben. Pati hosts a mixer to find Kamala a "suitable" partner.', 30, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 3, '…had a valentine', 'On Valentine''s Day, a compatibility test''s results spark more drama than romance among the Sherman Oaks couples. Meanwhile, Nalini makes a new friend.', 32, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 4, '...made someone jealous', 'Kamala invites Manish over for Navratri, to Pati''s annoyance. Devi isn''t thrilled about taking Rhyah''s son to a house party, but she''s in for a surprise.', 27, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 5, '...been ghosted', 'A charity event gives Devi the chance to polish her rusty flirting skills. As awkward vibes between Fabiola and Aneesa lingers, Paxton offers advice.', 26, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 6, '...had a breakdown', 'Chasing Ivy League dreams and his dad''s approval, Ben ignores warning signs of burnout until the stress of his jam-packed workload builds up — literally.', 25, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 7, '...cheated', 'Up against Des'' team at a debate tournament, Devi takes her competitiveness too far. An opportunity arises for Eleanor. Pati explains herself to Kamala.', 27, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 8, '...hooked up with my boyfriend', 'A game night gives Devi and Fab a chance for alone time with Des and Aneesa, but other guests throw the evening off course. An art tutor surprises Ben.', 26, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 9, '…had an Indian boyfriend', 'Watching Devi struggle with a painful memory, a nervous Rhyah orders Des to keep his distance. Paxton enlists Eleanor''s help to break some news to Trent.', 30, '2022-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 3), 10, '...lived the dream', 'The end of the school year has the Sherman Oaks crew all up in their feels. Devi is torn between planning the future and enjoying the present.', 29, '2022-08-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')), 4, 'Season 4', 'Senior year has finally arrived. Between college conundrums, identity crises and crushes that won''t fade, are Devi and the gang ready to face the future?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 1, '...lost my virginity', 'An awkward end to an intimate moment has Devi fuming all summer. As senior year begins, the crew has college — and complicated feelings — on the brain.', 29, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 2, '...gotten sweet revenge', 'Bent on exposing who vandalized her car, Devi makes a bold accusation. Fabiola shakes up the robotics club''s culture. Pati hides a secret from the family.', 27, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 3, '...liked a bad boy', 'As senior year continues to spiral, Devi''s resolve to avoid Ethan weakens. Paxton returns to a comforting place. Nalini tackles termite issues.', 26, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 4, '...wrecked my future', 'At a college fair, Devi juggles her love life with her academic ambitions, Fabiola ponders a tricky decision and an unlikely ally comes to Ben''s rescue.', 29, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 5, '...been to New Jersey', 'On a school trip to New York, Devi discovers that college may be scarier than she thought, Eleanor faces disappointment and Fabiola remains tight-lipped.', 28, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 6, '...had my dream stolen', 'With early college admissions rolling in, Devi''s in for more than one surprise. Kamala warns a smitten Pati about Len. Ben overhears a hurtful comment.', 33, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 7, '...had an identity crisis', 'As Paxton struggles to let go of his past as the king of high school, he seizes a chance to thrive as a swim coach and finds closure with an old flame.', 27, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 8, '...set my mom up', 'Unsure about her own love life, Devi focuses on Nalini''s — but it will mean befriending an enemy. Pati''s birthday ends on a high note no one sees coming.', 33, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 9, '...gone to prom', 'After a major setback, Devi feels the burden of telling a lie and must dig deep for a second chance. On prom night, the friends share their truths.', 31, '2023-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10062292')) AND numero_temporada = 4), 10, '...said goodbye', 'The last weekend of summer coincides with a festive occasion — and on the brink of their new lives, Devi, her family and friends have lots to celebrate.', 32, '2023-06-08');
