INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')), 3, 'Season 3', 'Season 3 follows classic characters as they make unexpected choices that will mutate their worlds into spectacular alternate versions of the MCU.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 1, 'What If... The Hulk Fought the Mech Avengers?', 'Captain America/Sam Wilson must suit up in a colossal mech suit to battle Bruce Banner after an attempt to cure himself of the Hulk goes horribly wrong. Bucky Barnes, Monica Rambeau, Moon Knight, and others must join Sam as his new team of Mech Avengers.', 31, '2024-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 2, 'What If... Agatha Went to Hollywood?', 'On the set of Stark Pictures'' first production, the playboy auteur quickly finds himself enchanted by his bewitching lead actress, Agatha Harkness. Little does she know there will be another superpower co-star on the call sheet… Kingo.', 30, '2024-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 3, 'What If... The Red Guardian Stopped the Winter Soldier?', 'It is 1991, and the Red Guardian takes it upon himself to join a high-profile mission and prove himself to his Red Room superiors. When his antics interfere with the Winter Soldier''s own mission to kill Howard Stark, the two Soviet supersoldiers must form an alliance to escape the United States.', 33, '2024-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 4, 'What If... Howard the Duck Got Hitched?', 'Howard the Duck and Darcy Lewis find themselves on an intergalactic pleasure cruise. When dangerous factions from across the galaxy descend to threaten their trip, they must discover their own cosmic powers to withstand the onslaught.', 32, '2024-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 5, 'What If... The Emergence Destroyed the Earth?', 'In a Universe where The Eternals never stopped The Emergence, the birth of an incubating Celestial shatters the Earth. Civilization endures on the rocky remnants of our planet, where Quentin Beck leads an authoritarian regime until freedom fighters recruit Riri Williams on a deadly mission to take him down.', 33, '2024-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 6, 'What If... 1872?', 'In a universe where the heroes of the MCU live in the Old West, Shang-Chi and his pistol-packing partner, Kate Bishop, traverse the frontier, saving the innocent from the evils of The Hood.', 32, '2024-12-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 7, 'What If... The Watcher Disappeared? (1)', 'The Watcher must stand trial for his many interventions.', 28, '2024-12-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10168312')) AND numero_temporada = 3), 8, 'What If... What If? (2)', 'The end of the beginning...', 34, '2024-12-29');
