INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 1, 'S1 • Kazekage Rescue', 'Naruto Uzumaki is back! After two and a half years of training on the road with Jiraiya of the Sannin, Naruto is back in the Village Hidden in the Leaves and he''s ready to show off his new skills. He and Sakura team up to take on their old master Kakashi, who''s pretty impressed with their progress. They''ll have plenty of opportunity to put it into action when news arrives from the Sand Village that Gaara, Naruto''s former rival and now Kazekage of the Sand, has been kidnapped! And the culprits are the very same group who are after Naruto - the Akatsuki!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 1, 'Homecoming', 'A figure passes through the gates. It''s an older Naruto, who has returned from a long training journey with Jiraiya. Naruto Uzumaki is back!', 23, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 2, 'The Akatsuki Makes Its Move', 'Naruto and Sakura team up and challenge Kakashi to a survival challenge to show off their progress.', 23, '2007-02-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 3, 'The Results of Training', 'Naruto’s and Sakura’s combined skills force Kakashi to use his Sharingan right off the bat. Naruto masterfully unleashes his jutsu one after another.', 23, '2007-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 4, 'The Jinchuriki of the Sand', 'Gaara is quick to detect Deidara’s presence, and an aerial battle ensues with Deidara on his giant bird and Gaara atop sand.', 23, '2007-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 5, 'The Kazekage Stands Tall', 'Naruto and Sakura defeat Kakashi in the survival challenge. Tsunade assigns them to a three-man squad led by Kakashi, who tells them they are now his equals.', 23, '2007-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 6, 'Mission Cleared', 'In order to protect his village from Deidara’s explosive clay, Gaara uses his chakra to create a giant sand shield.', 23, '2007-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 7, 'Run, Kankuro', 'Gaara, his strength completely exhausted, is whisked away by Deidara. Kankuro ignores Baki’s efforts to stop him and immediately sets out in pursuit with a platoon to rescue Gaara.', 23, '2007-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 8, 'Team Kakashi, Deployed', 'An urgent message from the Sand Village detailing the Akatsuki’s kidnapping of the Kazekage reaches the Hidden Leaf Village. Tsunade wastes no time in ordering Team Kakashi to the Sand Village.', 23, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 9, 'The Jinchuriki''s Tears', 'On her way to the Sand Village, Temari encounters Kakashi and his team. Kakashi admonishes Naruto when he tries to rush ahead…', 23, '2007-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 10, 'Sealing Jutsu: Nine Phantom Dragons', 'The Sand ninja fight against time to treat Kankuro. Even the Sand’s poison expert, Granny Chiyo, is baffled. The only hope lies with the reinforcements sent by Tsunade.', 23, '2007-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 11, 'The Medical Ninja''s Student', 'Sakura treats a critically ill Kankuro. After extensive training she’s now a full-fledged Medic Ninja, and Sakura amazes everyone with her sure, steady hands.', 23, '2007-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 12, 'The Retired Granny''s Determination', 'Pakkun finds the hideout of the Akatsuki. Team Kakashi and Temari prepare to set out to get Gaara back, but Temari is ordered to stay behind and help guard the village.', 23, '2007-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 13, 'A Meeting With Destiny', 'Guy prepares to use a forbidden secret jutsu. Meanwhile, Naruto falls under Itachi’s genjutsu, and all the anti-genjutsu training he underwent with Jiraiya races through Naruto’s mind.', 23, '2007-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 14, 'Naruto''s Growth', 'Guy prepares to use a forbidden secret jutsu. Meanwhile, Naruto falls under Itachi’s genjutsu, and all the anti-genjutsu training he underwent with Jiraiya races through Naruto’s mind.', 23, '2007-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 15, 'The Secret Weapon is Called...', 'Granny Chiyo and Sakura rescue Naruto from Itachi’s genjutsu. Without a moment’s delay, Kakashi begins a counterattack.', 23, '2007-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 16, 'The Secret of Jinchuriki', 'Chiyo and Kakashi realize that the attack was just a diversion, and that the Akatsuki have already begun the process of extracting the Tailed Beast from Gaara.', 23, '2007-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 17, 'The Death of Gaara!', 'Teams Kakashi and Guy take a short rest. Granny Chiyo watches Naruto dozing off and is reminded of Sasori as a child. The pursuit resumes, and when Chiyo wonders why Naruto puts such effort into...', 23, '2007-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 18, 'Charge Tactic! Button Hook Entry!!', 'Teams Kakashi and Guy reach the Akatsuki hideout. They hurry to infiltrate but are thwarted by a five-seal barrier. The only way to break the barrier is to remove all five seals at once.', 23, '2007-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 19, 'Traps Activate! Team Guy''s Enemy', 'Breaking the five-seal barrier set off a trap, which now has Team Guy battling amazingly accurate copies of themselves. Back at the Akatsuki hideout, Deidara and Sasori struggle to take the Nine-Tail Jinchûriki.', 23, '2007-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 20, 'Hiruko Vs. Two Kunoichi!', 'At last, the showdown between the old woman and her grandson begins. Sakura is confused by Sasori’s strange appearance, and Granny Chiyo explains that this is Hiruko…', 23, '2007-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 21, 'Sasori''s Real Face', 'Granny Chiyo and Sakura manage to expose Sasori, who amazingly looks no older than he did twenty years earlier.', 23, '2007-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 22, 'Chiyo''s Secret Skills', 'Sakura is caught by Sasori’s tactic and surrounded by a poison cloud.', 23, '2007-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 23, 'Father and Mother', 'Chiyo and Sakura take cover, and Sasori wastes no time unleashing a ruthless attack.', 23, '2007-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 24, 'The Third Kazekage', 'Sakura counters the Iron Sand attack of the Third Kazekage puppet with superhuman strength.', 23, '2007-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 25, 'Three Minutes Between Life and Death', 'Sakura destroys the Third Kazekage puppet thanks to a secret antidote she had taken.', 23, '2007-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 26, 'Puppet Fight: 10 vs. 100!', 'Sakura and Granny Chiyo are engaged in a fierce battle with Sasori, who is able turn himself into a human puppet. They somehow bring Sasori down within the time limit, but he ends up reviving.', 23, '2007-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 27, 'Impossible Dream', 'Although stung with poison herself, Granny Chiyo uses the last of the antidote on Sakura. Mocking the tender scene between Granny Chiyo and Sakura, Sasori attempts to end Granny Chiyo''s life.', 23, '2007-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 28, 'Revival of the Beasts', 'Team Guy senses the result of the Sakura and Granny Chiyo’s desperate struggle while still in battle with his deadly copy. Although Guy’s team members are showing fatigue, their copies remain strong!', 23, '2007-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 29, 'Kakashi''s Enlightened!', 'Sakura hurries to get to Naruto with Granny Chiyo, who is suffering from the poison. The members of Team Guy rush to assist Team Kakashi. Meanwhile, with all preparations complete, Kakashi reveals his Mangekyo Sharingan.', 23, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 30, 'Aesthetics of an Instant', 'Naruto loses all reason to anger and is gradually taken over by the Nine-Tailed Fox Spirit. Having been forewarned by Jiraiya, Kakashi narrowly manages to suppress the Nine-Tailed Fox.', 23, '2007-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 31, 'The Legacy', 'Relying on Naruto''s power, Granny Chiyo performs the Transmigration Jutsu on Gaara.', 23, '2007-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 1), 32, 'Return of the Kazekage', 'Gaara and his rescuers make a triumphant return to the Hidden Sand Village.', 23, '2007-10-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 2, 'S2 • Long-Awaited Reunion', 'In the midst of its spying mission, Team Kakashi is suddenly confronted with the Leaf Village''s sworn enemy, Orochimaru. Naruto challenges him, and during their battle, his anger brings forth the power of the Nine-Tailed Fox. Naruto will never give up his determination to find Sasuke and bring him home, but in his rage he risks losing all awareness of himself and hurting those he cares for the most.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 33, 'The New Target', 'Teams Kakashi and Guy return home to Konoha. As Kakashi rests in the infirmary, Sakura tells Tsunade about the information Sasori gave her as a reward for defeating him. Sasori had a meeting scheduled with a spy from within Orochimaru''s ranks in 10 days. 4 days have passed since Sakura received this information, and now Naruto and Sakura need to recruit a new team member to go and investigate. As Naruto searches Konoha for a willing recruit, he meets some of his old friends. Just as Choji agrees to help, Shikamaru, Choji, and Naruto are attacked by a Konoha shinobi unknown to them, Sai.', 23, '2007-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 34, 'Formation! New Team Kakashi', 'Naruto, Choji and Shikamaru attempt to capture and interrogate Sai, but Sai withdraws after insulting Naruto. Shortly afterward, Ino appears. Concerned that the demon fox could fall into Akatsuki hands, the village elders challenge Tsunade''s plan to send Naruto out of the village without the still bedridden Kakashi. Tsunade promises to protect Konoha with her own life if Naruto is captured, but is still forced to compromise with Danzo by adding Sai to Team Kakashi. She also temporarily replaces Kakashi with ANBU member Yamato and warns him to keep an eye on Sai. Naruto and Sakura finally meet their new team members, and Naruto is immediately angered upon Sai''s appearance.', 23, '2007-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 35, 'An Unneeded Addition', 'Yamato takes temporary leadership of Team Kakashi while Sai insults both Naruto and Sakura. While preparing to set off, Sai receives an envelope from a Root shinobi containing secret orders from Danzo, and Sakura consults with Tsunade. Jiraiya then meets with Tsunade and Yamato in Kakashi''s hospital room to brief Yamato on the demon fox within Naruto, detailing the "demon fox''s cloak", and revealing a scar he got from Naruto when the fourth tail formed. Finally the new Team Kakashi set off on their new mission, to intercept an Akatsuki spy and gather information about Sasuke.', 23, '2007-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 36, 'The Fake Smile', 'The new team Kakashi heads out for the Heaven and Earth bridge. Sai, Sakura, and Naruto come to blows after just 5 minutes on the same team due to Sai making fun of Sasuke. Therefore, Yamato decides they need to improve on teamwork and uses Mokuton to create a wooden cage threatening to lock the team up unless they behave. Given an ultimatum between being locked up or spending the night at a hot springs, the team chooses to visit the springs to improve team cohesion. Naruto still despises Sai despite this effort, and several insulting remarks from Sai worsen team relations.', 23, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 37, 'Untitled', 'Sakura sees Sai drawing by the river and finds out that Sai has artistic talent but has never given titles to anything he ever drew. Naruto and Sakura begin to realize the reason behind Sai''s repulsive personality. After the hot springs, the team heads off to the bridge to meet the spy. Yamato is suspicious of traps so they go off the main road into the forest. Camping for the night, Yamato then creates a two story house by again using his Mokuton jutsu. Inside this house, the team formulates their plan.', 23, '2007-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 38, 'Simulation', 'Naruto is paired with Sai for the Buddy team of two, over his and Sakura''s objections, while Sakura is assigned to support Yamato. Yamato conducts a simulation of the spy meeting with himself as the spy to gauge Naruto and Sai''s abilities and teamwork. After Naruto makes a mistake when attacking Yamato, Sai immobilizes him and goes on to capture Yamato alone. Naruto is angry with Sai for not acting as a comrade would, but resolves to work together with him if doing so will help bring Sasuke back. Sai reveals to Sakura that he has no emotions, and little understanding of them. The group then prepares to head to the bridge.', 23, '2007-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 39, 'The Tenchi Bridge', 'Yamato disguises himself as Sasori after creating a wood replica of Hiruko, and goes to meet the spy. The spy turns out to be Orochimaru''s right-hand man, Kabuto Yakushi, who reveals the location of Orochimaru''s current hideout to Yamato. Orochimaru interrupts the meeting, appearing to attack Kabuto, and while it initially appears that Orochimaru has come after Kabuto, Kabuto attacks Yamato and reveals that he is truly loyal to Orochimaru. Orochimaru calls out Naruto, Sakura and Sai from where they are hiding and observing the meeting, and prepares to fight the team.', 23, '2007-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 40, 'The Nine-Tails Unleashed!!', 'Immediately after Yamato signals Naruto and the others out to the bridge where Orochimaru and Kabuto are waiting, Naruto''s chakra begins to boil with the chakra of the Nine-Tailed Fox. Slowly, Naruto grows more tails as Orochimaru taunts him and makes him even more angry. Meanwhile, Yamato remembers Jiraiya speaking of how many tails he has seen Naruto grow. Jiraiya explains more about what happened and more about how Naruto acts when he''s in his Nine-Tails form.', 23, '2007-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 41, 'The Top-Secret Mission Begins', 'Naruto continues to get even more enraged and easily counters Kabuto''s attack, flinging him away. Naruto''s counter throws Kabuto into Sakura, knocking her unconscious. Orochimaru continues to watch Naruto become more enraged, eventually destroying the Bridge of Heaven and Earth. As the bridge collapses, Sakura slides off the edge. Sai draws a bird to fly, but chooses to follow Naruto and Orochimaru instead of saving Sakura. Yamato saves her at the last second, and creates a wood clone to catch up to the battle. Eventually the fourth tail appears, allowing the vile chakra to completely control Naruto''s body, forming him into a miniature Nine-Tailed Fox.', 23, '2007-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 42, 'Orochimaru vs. Jinchuriki', 'Naruto, in the four-tailed state, begins attacking Orochimaru with incredible force, devastating the surrounding landscape and preventing Sai and Yamato''s wood clone from approaching him. The majority of Orochimaru''s attacks prove to be ineffective, but Naruto also fails to kill Orochimaru as he regenerates from any injuries he sustains. Meanwhile, Kabuto advances toward Sakura and Yamato, deducing that Sasori has died. Orochimaru finally manages to strike Naruto with a sword blade from his mouth, and Sakura reacts in horror when she sees Naruto''s four-tailed state.', 23, '2008-01-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 43, 'Sakura''s Tears', 'Kabuto comments that Naruto''s state is a consequence of his desperation to bring back Sasuke. Sakura begins to cry and approaches Naruto but is injured when his attention turns to her. Yamato uses the mokuton jutsu to bind Naruto before he does any more harm. Kabuto heals Sakura, reasoning that the Konoha ninja are not Orochimaru''s enemies because they are also fighting Akatsuki. Yamato uses the abilities of the 1st Hokage to forcibly return Naruto to his normal state. Meanwhile Sai confronts Orochimaru with a message from Danzo. Orochimaru responds by piercing Sai with Kusanagi.', 23, '2008-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 44, 'The Secret of the Battle!', 'Yamato uses the first Hokage''s chakra to suppress the demon fox''s chakra and Naruto returns to normal, but with severe injuries. Sakura begins to heal him, but notes that medical ninjutsu has little effect on his wounds. Orochimaru''s sword is revealed to have only pierced one of Sai''s clones. The real Sai emerges, talks to Orochimaru and gives him a letter from Danzo. Sai then leaves with Orochimaru and Kabuto but Yamato''s wood clone stays close on their trail. Naruto comes to his senses and wonders what happened but Sakura decides not to tell him the truth. They reach the meeting spot, picking up the picture book Sai left behind. Yamato infers that Danzo seeks to destroy and remake Konoha by collaborating with Orochimaru.', 23, '2008-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 45, 'The Consequences of Betrayal', 'Kabuto creates a fake corpse that resembles Sai, containing hidden traps to slow down Yamato''s clone after sensing it. Naruto hasn''t completely recovered from using the Demon Fox''s chakra, and Yamato says that he will be left behind if he cannot keep up. Naruto is determined to finish his mission and not slow the team down. However Team Kakashi is forced to take a break when it''s clear that Sakura has not fully recovered from her own injuries. Yamato then uses this opportunity to talk to Naruto alone and reveals to him that the one who hurt Sakura was Naruto himself. Naruto is shocked by what Yamato says to him.', 23, '2008-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 46, 'The Unfinished Page', 'Naruto finally makes sense of the destruction he witnessed around him earlier. Yamato tells Naruto not to rely on the demon because Naruto is strong enough to withstand the demon''s terrible chakra. Sai discovers the loss of his book while resting. Team Kakashi browse Sai''s book, and they notice that the book (which can be read from both ends) contains different paths of two boys who meet in the middle. Each page has the boys fighting someone new, each time collecting the opponent''s armor and weapons into the next page. The pages where the two boys would meet are unfinished. Orochimaru''s group reach their base, not realizing that Yamato''s wood clone trailed them there. Sai gets a glimpse of Sasuke''s silhouette and eyes and discovers that he is the man Naruto and Sakura are looking for.', 23, '2008-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 47, 'Infiltration: The Den of the Snake!', 'Sai receives a chilling glare from Sasuke''s Sharingan that frightens him. Sai gives Orochimaru a bundle with information about Konoha''s ANBU. Yamato gives Sakura and Naruto seeds with his chakra that enables him to track them inside the lair, and reveals that he was able to track Sai because he put a seed in Sai''s clothing and food during the visit to the hot springs. Kabuto locks Sai in a room, and the boy summons a bingo book from scrolls he carries. Yamato uses a jutsu to open a tunnel into Orochimaru''s hideout, and he, Naruto and Sakura travel to Sai''s room undetected.', 23, '2008-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 48, 'Bonds', 'Yamato and the team enter Sai''s room and confront him while Kabuto makes his way there as well. Sai tells Team Kakashi that not only was he to help with Konoha''s destruction but also act as a spy against Orochimaru. Yamato reveals the secret of "Root"- its members were trained like Kirigakure''s students in that they had to kill their friends so as to eliminate their emotions. Sakura returns Sai''s book to him, remarking that he still has emotions because he treasures it. Sai then tells the group about his bond with his brother. Finally the team decides what to do about Sai''s betrayal outside the lair. In doing so, Naruto tells the group about his own bonds and about how far he''s willing to go to bring Sasuke back.', 23, '2008-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 49, 'Something Important...', 'Kabuto fights Team Kakashi and frees Sai. However, Sai, who intends to learn more about his bond with his brother through Naruto''s bond with Sasuke, betrays him. Captured, Kabuto gives a vague description of Sasuke''s location to the team. Leaving Yamato''s wood clone to watch over Kabuto, Team Kakashi enters Orochimaru''s hideout and splits up to find Sasuke.', 23, '2008-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 50, 'The Picture Book''s Story', 'As Team Kakashi continues their search for Sasuke, Naruto suddenly collapses due to his previous fight with Orochimaru. As Naruto wakes up, Sai begins to reveal more about his brother, but Orochimaru suddenly attacks them. Sakura and Yamato come to Naruto''s aid against Orochimaru, while Sai continues the search. Just as Sai finds Sasuke, Yamato finds Sai''s bingo book with Sasuke listed as a target for assassination.', 23, '2008-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 51, 'Reunion', 'As Team Kakashi continues their search for Sasuke, Sai approaches Sasuke''s room and awakens him. Shaken by the image of Sasuke''s Sharingan from earlier, Sai attempts to restrain him. A large explosion occurs and Sakura, Naruto and Yamato catch up. At first Sakura tries to restrain Sai in order to find out his true objective, but she stops, stunned at seeing her former comrade. Contrary to what the rest of the team assumed to be his mission, Sai tells them that he wishes to bring Sasuke back to Konoha.', 23, '2008-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 52, 'The Power of Uchiha', 'Sasuke begins to attack Naruto, but Sai restrains him only for them both to be blown away by Sasuke''s Chidori Nagashi. Sakura charges at Sasuke, but Yamato intervenes and winds up being stabbed by Sasuke''s unique blade infused with his Chidori. The Nine-Tailed Fox tempts Naruto with its power, but he refuses it. Sasuke sees this using his Sharingan, appearing in Naruto''s mind. The Nine-Tails says that Sasuke''s chakra reminds him of Madara Uchiha, then Sasuke suppresses the Nine-Tailed Fox''s chakra. Before the Nine-Tailed Fox returns to its cage, it warns Sasuke not to kill Naruto, saying that he will live to regret it forever.', 23, '2008-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 2), 53, 'The Leaves Sprout!', 'Orochimaru and Kabuto convince Sasuke to withdraw with them, and Naruto weeps over his failure to return Sasuke to the village, but Sakura reassures him that they will bring Sasuke back together. Naruto''s team reports to Tsunade about the results of the mission, and Tsunade is greatly angered over Danzo''s scheme, particularly his leaking classified information to further it. Sai asks Danzo to allow him to remain with Team Kakashi, and Danzo reluctantly agrees. Sai goes on a mission with his team, having come to see them as his friends.', 23, '2008-04-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 3, 'S3 • Twelve Guardian Ninja', 'Defeated by Sasuke, Naruto returns to the hidden Leaf Village to start a new training program with Kakashi and Yamato. Naruto learns that he has Wind-style chakra. Meanwhile, a group of four mysterious people attacks a village in the countryside of the Fire Country. Who are they and what exactly do they want from the Leaf Village ninja?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 54, 'Nightmare', 'Naruto''s been having nightmares about the release of the Nine-Tail''s power. Afterward, Kakashi informs Naruto that he has special training for him that will make him strong quickly. They are cut off by Team 10, who have also come to visit. Sai lunches with them and, trying to make friends by using nicknames, angers Sakura by calling Ino "gorgeous" after concluding that women do not like to hear how they really are.', 23, '2008-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 55, 'Wind', 'Kakashi is released from the hospital and begins Naruto''s training program. Naruto learns that he has Wind-style chakra. Yamato helps by setting up the training field with his special jutsu. Naruto also learns that he can use his Multi Shadow Clone jutsu to speed up his training, since whatever the clones learn, the original user learns upon the clone''s dispersal. Naruto and his mass of clones each take a leaf and attempt to slice it in half with wind chakra as the first step to creating his new jutsu.', 23, '2008-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 56, 'Writhe', 'Naruto and his clones continue to work on chakra nature manipulation by slicing leaves. After some struggling, Naruto approaches Asuma, who is also a wind type, for advice, after which Asuma gives Naruto''s clone a few pointers. Naruto is subsequently able to slice a leaf in half. Asuma and Yamato head out with their teams on new missions. It is revealed that Asuma is the Third Hokage''s son and that he is in a relationship with Kurenai. Meanwhile, on a hill overlooking a burnt village, four cloaked figures discuss the awakening of the Fire Country by eliminating the Leaf Village.', 23, '2008-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 57, 'Deprived of Eternal Sleep', 'Naruto, Sakura, Sai and Yamato head out for a new mission near the Fire Temple. When the other party fails to show up at the rendezvous point, the team gets separated and Naruto stumbles upon one of the four hidden tombs they came to protect. Due to a misunderstanding, he fights one of the monks-in-training from the Fire Temple, Sora, who also uses wind chakra based techniques. After the confusion, the monks and Team Kakashi travel to the Fire Temple, and Naruto recognizes it from his nightmare.', 23, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 58, 'Loneliness', 'The temple monks explain that the tombs hold the loyal bodyguards of Fire Country''s feudal lord. Naruto observes Sora sparring with other monks and becomes offended upon realizing he is holding back. Naruto challenges Sora, but just as the matter is about to get serious, another monk stops him. Naruto realizes Sora is despised by the other monks as he was himself and wishes to befriend him. Naruto visits Sora again and observes him practicing his wind jutsu in earnest, hoping to get strong enough to avenge his father. They later return to the temple to receive news that another tomb has been robbed.', 23, '2008-05-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 59, 'A New Enemy', 'Tsunade suspects that Danzou is plotting something and orders an investigation of him. Team Kakashi, Chiriku and Sora notice the coffins moving on their own, but fail to intercept them. The coffins emerge on a cliff, where the leader of the enemy ninja orders his subordinates to deal with their foes. The ninjas turn the area into a maze of rocky canyons and pits, full of deadly traps. The team members are separated from each other, and begin facing off against the enemy. Yamato speculates that the ninja may have orchestrated the theft in order to target someone on his team.', 23, '2008-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 60, 'Impermanence', 'Team Kakashi begins facing off against the enemy shinobi. Yamato eludes his opponent, Fudo, by faking his death. Sora, unwilling to look for Naruto, goes off on his own. Back in Konoha, Danzo reveals that he is aware that he is being watched by Tsunade''s ANBU. Naruto fights Fūka, whose kiss is fatal and shows her ability to use earth, fire, water and lightning jutsus. Sai manages to escape from his attacker, Fuen, and later saves Sakura from an enormous spider, becoming injured in the process. Sora then hits upon the enemy leader, Furido, and it is revealed that he was the group''s target.', 23, '2008-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 61, 'Contact', 'Furido taunts Sora until Sora unleashes his true powers, before informing Sora that he is planning to use the four corpses to save the Land of Fire. Naruto continues his fight with F?ka and learns that she can use all five elements. F?ka manages to kiss Naruto and begins draining his chakra. Realizing that Naruto is in trouble from extra-sensory perception, Sora rushes to rescue him. Sakura, Sai and Yamato arrive to help but are trapped by Fudo and Fuen. F?ka drains Naruto''s chakra until she begins drawing on the Nine-tails''s, which is too unnatural for her to successfully absorb. The enemy team retreats when Chiriku brings reinforcements.', 23, '2008-05-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 62, 'Teammate', 'Asuma''s team returns from its mission. Team Kakashi returns to Konoha as well, with Sora replacing Sai on the team. Naruto tries to show Sora around Konoha but Sora goes his own way. Sora''s insults precipitate a brawl with Kiba and Choji, with Naruto and Rock Lee joining in. Shikamaru and Asuma stop the fight. Later Asuma tells Sora he knew Sora''s father, who is revealed as one of the Guardians involved in the coup attempt. He also shows Sora his chakra blade attack. Furido and the other body snatchers begin their attack on the Kohaku Clan.', 23, '2008-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 63, 'The Two Kings', 'Asuma supervises Naruto and Sora''s wind chakra training, and notices that Sora, like Naruto, has very powerful chakra. Tsunade and Yamato learn from Chiriku that Sora was inadvertently responsible for an incident in which the Temple of Fire was destroyed. Later, Asuma gives Sora a claw made from the same materials as his chakra blades. It is revealed that Asuma killed Sora''s father Kazuma, who had planned to kill the Hokage. Furido then approaches Sora, telling him that Asuma is responsible for his father''s death and passing him two "king" pieces from a Shogi set for Asuma. Danzo mysteriously disappears. Naruto approaches a furious Sora in the training grounds, who easily throws a chakra-powered kunai through a tree and destroys the stone behind it.', 23, '2008-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 64, 'Jet-Black Signal Fire', 'Danzou is brought in for questioning after being caught meeting with a young Rain ninja. Sora confronts Asuma, and Asuma admits to having killed Kazuma. He attacks Asuma, his arm once again assuming a demonic form. Afterward, Naruto gets injured while shielding Sora from the attacks of an unknown individual, presumably from Root. Furido then approaches Sora, telling him to kill both Asuma and the Hokage to avenge his father. Later on, Naruto catches Sora going after Tsunade. Sora retreats as Shizune and a few other ninja arrive, but Naruto pursues him. At that moment, a mysterious lightning storm strikes, cutting off power to the entire village.', 23, '2008-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 65, 'Lockdown of Darkness', 'With Konoha in complete darkness, the village struggles to defend against the four attackers who have sealed the entire village behind a barrier. The entire village is in a state of emergency. Asuma, commanded by Tsunade to follow Sora and Naruto, finally catches up to them. Asuma realizes that the four invaders plan to annihilate the entire village using the lightning powers of the corpses that they stole. The revelation shocks Sora. As Asuma leaves to help hold off the attackers, he instructs Naruto to continue pursuing Sora.', 23, '2008-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 66, 'Revived Souls', 'Konoha''s ninja fight off the revived zombie members of the Kohaku clan. The four Guardian Ninjas, Seito, Tōu, Nauma and Kitane, are also revived. Asuma realizes that they are planning to use Limelight, a jutsu in which the four create a lightning blast powerful enough to destroy Konoha. Asuma sends Sakura and Yamato after the other three while he remains behind to battle Kitane, but Fuen tackles Sakura and Fudo fights Yamato. Meanwhile, Naruto catches up to Sora, but Sora runs off in search of Furido. Naruto tries to pursue him, but is assailed by Fuuka. Soon after, Sora reaches Furido, who admits that he had planned to destroy Konoha.', 23, '2008-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 67, 'Everyone''s Struggle to the Death', 'Sora refuses to let Furido destroy the village despite his grudge against Asuma and the Hokage. He is beaten up by Furido, who claims that his father had a similar flaw. Asuma gets trapped by Kitane in a force field of lightning. Meanwhile, Yamato and Sakura kill their opponents, and Shikamaru heads to the battlefield with a plan to defeat the zombies. Just as he puts it into motion, however, Fuen''s barrier falls and Fudo''s revival technique ends, and the zombies turn to dust.', 23, '2008-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 68, 'Moment of Awakening', 'Naruto deduces that Fuuka''s secret consists of switching bodies to use each corresponding element and that her hair preserves her youth and body. Naruto damages her hair and it takes a life of its own dispensing the body, but Naruto finally kills it with a Rasengan. Meanwhile, Asuma manages to break free of the electric barrier, catch up with Kitane and defeat him in a short fight. Realizing that Kitane is no more, and that his three other companions were killed, Furido causes the 3 other ninja guardians to disappear. But Furido has a back up plan, Sora.', 23, '2008-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 69, 'Despair', 'Furido releases Sora''s seal, and tells him the truth: Sora is a pseudo-Jinchuuriki. The chakra that had leaked from the Nine Tailed Fox when it attacked Konoha 15 and a half years ago was harvested and implanted into Sora. Just then, Asuma arrives at the scene with Naruto. Asuma recognizes Furido and it is revealed that he is Kazuma, Sora''s father. Yamato, Sakura, Kiba, Lee, Ino, Choji and Shikamaru also turn up. Enraged, Sora wants to destroy everything, and turns into the Three-Tailed form of the Nine-tails. However, Yamato is unable to restrain him, because he does not have the First''s necklace on him.', 23, '2008-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 70, 'Resonance', 'The chakra of the Nine-tails rages out of control within Sora, preventing Naruto and the others from subduing him. Asuma and Kazuma resume their old battle, while Kazuma justifies his actions with his duty as a pawn to the "King" of the Fire Country. Naruto is repeatedly knocked down in his attempts to restrain Sora, and the chakra seeps into him and transforms him as well. Yamato is unable to suppress the Nine-tails'' chakra in both Jinchūriki, being prevented by an unknown outside force. Sora''s fourth tail emerges, causing the Nine-tails''s Cloak to envelop his body. He temporarily gains his own consciousness when he witnesses Naruto stab himself in the leg and successfully prevent the original Nine-tails'' Cloak from emerging.', 23, '2008-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 3), 71, 'My Friend', 'The struggle between Naruto and Sora continues. Asuma and Kazuma fight. Sai arrives, having snuck out of hospital, and binds Kazuma with an ink snake. Kazuma breaks out of Sai''s jutsu and charges Asuma, but is killed. Naruto eventually reaches Sora, who manages to release the Nine Tails''s chakra. Sora then leaves the village to travel the world. Asuma and Shikamaru play shogi and discuss who the king of Konoha is. Elsewhere, two Akatsuki members, Hidan and Kakuzu, appear chasing the Two Tails Jinchūriki.', 23, '2008-08-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 4, 'S4 • Immortal Devastators - Hidan & Kakuzu', 'Asuma and Shikamaru have to think on their feet as they face the mind-boggling jutsu of the Akatsuki pair, Hidan and Kakuzu. At the last minute, the Akatsuki are called away, but not before dealing a fatal blow to a revered shinobi of the Leaf. The devastated ninja left behind can think only of revenge, but Tsunade is opposed to the scheme until an offer of help arrives from an unexpected source.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 72, 'The Quietly Approaching Threat', 'Asuma apologizes at the grave of the Third Hokage for not understanding his advice concerning what the "king" of the Fire Country is. At the hospital, Naruto and Sai recover, despite Naruto''s desire to resume his training. Tsunade receives a report from Kakashi that Akatsuki is on the move. Elsewhere, Yugito Nii, the Two Tails Jinchūriki, struggles against Hidan and Kakuzu and unleashes the Two Tails, but is defeated and captured. Hidan and Kakuzu then turn their attention to the Fire Country for their next target.', 23, '2008-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 73, 'Akatsuki''s Invasion', 'Naruto proceeds to the next step of his training, the cutting of a waterfall. Hidan and Kakuzu reach the Fire Temple and fight Chiriku, so as to obtain the bounty on his head. After defeating him, they move out to claim the bounty and thereafter target the Nine Tails Jinchūriki Naruto.', 23, '2008-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 74, 'Under the Starry Sky', 'The second stage of Naruto''s training continues, while Tsunade sends out twenty teams composed of four ninja each to deal with the Akatsuki members in the Fire Country. Shikamaru leaves with Asuma, Izumo and Kotetsu, whereas Ino and Choji leave with Raido and Aoba. After putting in considerable effort, Naruto clears the second stage of his training, but collapses from hunger and exhaustion almost immediately afterward.', 23, '2008-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 75, 'The Old Monk''s Prayer', 'Asuma mourns Chiriku''s death, and realizes that Hidan and Kakuzu are trying to claim the bounty on his head. Meanwhile, Hidan and Kakuzu take Chiriku in for their payment. Meanwhile, Kakashi shows Naruto what the true goal of his training will be.', 23, '2008-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 76, 'The Next Step', 'Kakashi reveals that while he knows how to perform Rasengan, he cannot combine his own lightning-based chakra. He adds that even the Fourth Hokage, who created the move, could not combine his elemental chakra with the technique, but that Naruto might be able to. Asuma sends word to other teams about Akatsuki’s location and proceeds on despite his concern about Akatsuki’s strength. Kakuzu turns in Chiriku’s corpse despite Hidan’s complaints, and says that he is partnered with Hidan because he cannot kill him. The stress of the training causes Naruto to be enveloped in the Nine-tails''s "Demon Fox''s Cloak", but Yamato suppresses it.', 23, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 77, 'Climbing Silver', 'Asuma’s team reaches the bounty station and ambushes Hidan. Izumo and Kotetsu attack Hidan, but are unable to kill him despite stabbing his vital organs. Asuma tells his teammates that if they retreat they will be killed and Konoha will be endangered. Shikamaru realizes that Asuma is considering sacrificing himself to help defeat the enemy, based on what he knows of Asuma''s shogi strategy. Asuma begins fighting Hidan, while Shikamaru distracts him by forcing him to dodge Shadow Sewing. Hidan cuts Asuma on the cheek and steps into a circle of blood as Asuma uses a jutsu to engulf Hidan in a cloud of ash. Asuma then sets the cloud ablaze, supposedly killing Hidan.', 23, '2008-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 78, 'The Judgment', 'Asuma’s fire jutsu strikes Hidan, but much to the team''s surprise, Asuma is also burned. Hidan reveals his ability: By ingesting an opponent’s blood and standing in a ritual circle drawn with blood, the "curse" links him to his opponent and all damage inflicted on him is also inflicted on the opponent. Asuma rushes at Hidan but collapses after Hidan stabs himself in the leg. Shikamaru realizes Hidan needs to be in the circle for the curse to take effect, and uses his shadow possession jutsu to force Hidan to step out of it. Asuma forces himself to stand up and beheads the restrained Hidan.', 23, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 79, 'Unfulfilled Scream', 'Team Asuma continues their battle with Akatsuki''s Hiden and Kakuzu.', 23, '2008-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 80, 'Last Words', 'A call from the Akatsuki leader forces Hidan and Kakuzu to fall back, but in the wake of the aftermath, not everyone makes it back to Konoha alive.', 23, '2008-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 81, 'The Sad News', 'While Akatsuki discusses the true goals of their organization, Naruto continues his training. Meanwhile, Tsunade receives the tragic news.', 23, '2008-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 82, 'Team Ten', 'All of Konoha mourns the tragic loss of Asuma Sarutobi. Knowing that Hidan and Kakuzu are bound to return, Shikamaru, Choji, and Ino prepare to head off to take revenge upon the duo while Kakashi takes temporary leadership of the team.', 23, '2008-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 83, 'Target: Locked On', 'With careful planning, the group manages to find and trap Hidan and Kakuzu. However, things seem to be going a bit too smoothly.', 23, '2008-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 84, 'Kakuzu''s Abilities', 'When Kakashi strikes Kakuzu through the heart, the battle seems to be over. However, when Kakuzu not only survives the attack, but also manages to escape from Shikamaru''s trap, it soon becomes clear that the fight is only just beginning..', 23, '2008-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 85, 'The Terrifying Secret', 'As Kakashi and the others continue to struggle against the Akatsuki duo, Kakuzu reveals that he has not one, but five hearts! In order to kill him, one must take out all five of his hearts. Meanwhile, Shikamaru decides to challenge Hidan alone, and forces him away from his partner.', 23, '2008-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 86, 'Shikamaru''s Genius', 'Shikamaru continues his fight with Hidan. Hidan manages to injure Shikamaru and curses him the same way he did Asuma, but when Shikamaru survives Hidan''s attack, Hidan realizes something isn''t quite right.', 23, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 87, 'When You Curse Someone, You Dig Your Own Grave', 'Hidan falls into Shikamaru''s trap, but now that he has Hidan cornered, can he find a way to defeat Hidan''s immortality? Elsewhere, things are looking grim for Kakashi, Choji, and Ino as they continue fighting Kakuzu, but a surprise back-up unit arrives on the scene to provide some much needed assistance.', 23, '2008-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 4), 88, 'Wind Style: Rasen Shuriken!', 'Naruto challenges Kakuzu with his new technique, the Rasen Shuriken, but can he defeat Kakuzu when his technique isn''t even complete yet?', 23, '2008-12-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 5, 'S5 • The Three-Tailed Demon Turtle', 'Naruto''s new jutsu Rasen Shuriken is unbelievably powerful - but because of the risks to the user, Tsunade forbids Naruto to use it! When Jiraiya returns to the village, Naruto seeks his guidance, and the two head off to a hot springs resort to work on a solution. Meanwhile, Kakashi leads a team in search of Orochimaru''s hideout, and when Naruto hears about it, he begs to join them.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 89, 'The Price of Power', 'In the aftermath of the battle, Teams 7 and 10 return to Konoha. After examining Naruto, Tsunade officially classifies Naruto''s new technique as a Forbidden Jutsu and warns Kakashi never to let him use it again. What is the terrible secret of the Rasen Shuriken that has left even Tsunade stunned by its power? Meanwhile, Orochimaru orders Kabuto to search for a woman who will help him reach his goal.', 23, '2008-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 90, 'A Shinobi''s Determination', 'As Naruto recovers from his injury, Kakashi prepares to tell him the grim news about his new technique. Meanwhile, Sasuke secretly trains and has an encounter with a strange young girl.', 23, '2008-12-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 91, 'Orochimaru''s Hideout Discovered', 'Kakashi leads Kiba, Hinata, and Shino on a mission to infiltrate Orochimaru''s lair. What horrors and traps await them?', 23, '2009-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 92, 'Encounter', 'Kabuto and Yūkimaru travel to a lake, where Kabuto attempts to draw out a mysterious creature. Guren branches off from her men to find Orochimaru, who has Sasuke fight an army of Sound Ninja as training. Sasuke defeats them all, but declares that he wants to kill Itachi more than them. Naruto continues his training by summoning Gamakichi and Gamatatsu, but still doesn''t understand the concept of connecting to another person''s heart. Kabuto and Yūkimaru arrive at the Hot Springs Village where Naruto and Jiraiya are.', 23, '2009-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 93, 'Connecting Hearts', 'Naruto runs into unexpected difficulties as he trains with Gamakichi and Gamatatsu. While Kakashi''s group searches for Guren and her gang, Yukimaru seems to develop interest in Naruto.', 23, '2009-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 94, 'A Night of Rain', 'Kabuto assigns Guren to look after Yukimaru. Guren isn''t all too happy about the assignment, and things only become worse when Yukimaru falls ill on a rainy night. Elsewhere, Kiba discovers the mystery of where the dog whistle is coming from, and Tsunade sends assistance to Kakashi and Team 8.', 23, '2009-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 95, 'The Two Charms', 'While Naruto continues his training with Gamakichi and Gamatatsu, Yamato, Sakura, and Sai prepare to leave and back-up Kakashi''s group. As Guren and her gang prepares to intercept Kakashi''s group, Yukimaru grows concerned for her safety and gives her a charm in hope of a safe return.', 23, '2009-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 96, 'The Unseeing Enemy', 'While Naruto continues practicing a combo attack with Gamatatsu, Kakashi, Kiba, Hinata, and Shino have a run-in with Guren''s gang. Will Kakashi and Team 8 be able to defeat these strange foes?', 23, '2009-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 97, 'The Labyrinth of Distorted Reflection', 'In Konoha, Tsunade discovers they have an enemy using Crystal Style. While on his mission with Team Kakashi, Naruto meets Yūkimaru once again and talks to him. Guren puts a gigantic Crystal Prison over the forest trapping Team Kurenai inside. Guren then prepares six Crystal Clones and attacks Team Kurenai with them. Hinata defeats one clone but is locked up in a Crystal Prison by another. Team Kakashi reaches the borders of the giant prison and Naruto uses his new Jutsu with Gamatatsu to bust a way in.', 23, '2009-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 98, 'The Target Appears', 'Naruto successfully breaks down the crystal labyrinth with his new jutsu and he and the rest of Team Kakashi come to Kakashi, Kiba and Shino''s aide, and rescue Hinata as well. Meanwhile, Kabuto, Guren, Yukimaru and Gozu head to the lake Kabuto and Yukimaru went to before. What could be in the lake that Orochimaru wants?', 23, '2009-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 99, 'The Rampaging Tailed Beast', 'Yūkimaru summons the Three-Tailed and immobilizes it while Guren tries to capture it. It manages to break free and attack. Kakashi tells Naruto to investigate the lake, while they find Rinji and the others. Rinji and his men prepare an ambush, but Hinata, Sakura, and Sai arrive to avert it. Naruto summons Gamakichi and Gamatatsu and approach the Three-Tails, where they see Yūkimaru and learn of his allegiance to Guren. Trying to save Guren, Yūkimaru tries to suppress the Three-Tails once more, before managing to escape with her.', 23, '2009-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 100, 'Inside the Mist', 'Guren is rendered unconscious and relives her past as Naruto is caught in an illusion about Sasuke. After Kakashi finds him, Teams Kakashi and Kurenai conclude the mist around them causes Genjutsu courtesy of the Three-Tails. After Guren wakes up, Yūkimaru suffers another fever and passes out. Tsunade hears of the Three-Tails and assmbles Shizune, Ino, Tenten and Lee to go and seal it before the Akatsuki do. Naruto and Sakura talk about the home that people should return to before Naruto heads off to find Yūkimaru.', 23, '2009-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 101, 'Everyone''s Feelings', 'Naruto runs into Guren while trying to find Yūkimaru. Yamato and Kakashi find Naruto and bring him back to the group. Kabuto tells Guren that Yūkimaru is only a tool to control the Three-Tails, which upsets Guren. Meanwhile, Shizune, Ino, Tenten and Lee meet up with the team and tell them that their new mission is to rescue Yūkimaru and capture the Three-Tails before Orochimaru''s group can capture it.', 23, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 102, 'Regroup!', 'Shizune, Ino, Lee and Tenten arrive and Kakashi, Shizune and Yamato discuss about a strategy to seal the Sanbi and rescue Yukimaru. Meanwhile, Kabuto and Rinji notice Guren''s care for Yukimaru and become concerned.', 23, '2009-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 103, 'The Four-Corner Sealing Barrier', 'The sealing unit prepares the sealing barrier and the other two teams go into battle with Guren and her henchmen. Kakashi, Naruto and Sai stall Guren and Gozu while Shino prepares to go against Guren''s crystal style. Meanwhile, Lee goes against Guren''s other henchmen and gets trapped in their smokescreen. Can Lee find a way to defeat them?', 23, '2009-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 104, 'Breaking the Crystal Style', 'After Shino finishes preparing his insects, he goes against Guren''s crystal style. Elsewhere, while Shizune, Sakura, Ino and Hinata are bringing the sealing barrier to the Sanbi, they are being watched by Tobi and Rinji.', 23, '2009-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 105, 'The Battle Over the Barrier', 'Kabuto plans on breaking Leaf’s The Four-Corner Sealing Barrier from the inside by using Yukimaru’s power and have the Three-Tailed Beast go on a rampage.', 23, '2009-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 106, 'Red Camellia', 'Yūkimaru falters and the Three-Tails injures Guren. Rinji tells Yūkimaru to suppress the beast to save her, but he is unable to do so. Guren leaves her position and protects Yūkimaru with a Crystal Style shield. Naruto goes out to find Yūkimaru, but ends up fighting the Three-Tails with Guren. Despite their efforts to defeat it, the beast overpowers the two of them, and then it proceeds to swallow them. Meanwhile, Kakashi, Shino and Sai find Yūkimaru unconcious and flee with him, leaving Kabuto frustrated.', 23, '2009-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 107, 'Strange Bedfellows', 'Guren tries to attack Naruto within the Three-Tails, but, in her weakened state, is unable to do so and passes out. Meanwhile, Kakashi tells Sakura and Ino to heal Yūkimaru while he, Shizune, Kiba, Sai, and Hinata search for Naruto. Naruto and Guren soon encounter a horde of mini Three-Tails that try to attack them, but they evade them and begin to argue about Yūkimaru. While Yūkimaru awakens, Naruto summons a bunch of Shadow Clones to look for a way out of the beast''s stomach. Elsewhere, Kabuto gives Curse Marks to Rinji''s men.', 23, '2009-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 108, 'Guidepost of the Camellia', 'Yukimaru informs Kakashi and the others to Naruto and Guren''s whereabouts and they attempt to free them with Yukimaru''s help. Kiba, Tenten and Lee once again battle Kihou, Kigiri and Nurari after gaining more power from Kabuto. Naruto and Guren continue to search for a way out, coming across human-sized Sanbi-like creatures and illusions. Will Naruto and Guren ever find a way out?', 23, '2009-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 109, 'Counterattack of the Curse Mark', 'The Sealing Team prepared to start sealing the Three-Tails and tell Sai to take Yūkimaru somewhere safe, but he gets attacked by Kabuto''s men. Kabuto meanwhile prepares his plans while Lee, Tenten, and Kiba are also attacked. Rinji finds his men and converts them back to his side, ordering them to attack the Sealing Team; they''re stopped by Kakashi, Yamato and Shino. Rinji then makes Yūkimaru eat the pills to control the Three-Tails, which Naruto and Guren learn about.', 23, '2009-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 110, 'Memory of Guilt', 'Katsuyu arrives to help the sealing team with the sealing barrier. Naruto and Guren arrive to save Yukimaru from Rinji, but after Guren and Yukimaru have a brief discussion, Rinji reveals the truth about Guren to Yukimaru in hope that he''ll make the Sanbi go wild. What will Yukimaru''s reaction be when he discovers Guren killed his mother?', 23, '2009-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 111, 'Shattered Promise', 'The sealing team continue their efforts to seal the Sanbi while Kakashi and the others face against a monster fused together by Kigiri, Nurari and Kihou. Kabuto reveals Orochimaru''s plans involving the Sanbi and he and Naruto begin to fight. While protecting Yukimaru, Guren fights against the real Rinji, who has been resurrected by Kabuto. When Guren sacrifices her life to save Yukimaru, Yukimaru''s powers go into full effect. Now, in order to protect Yukimaru, Naruto prepares to go against the rampaging Sanbi.', 23, '2009-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 5), 112, 'The Place to Return To', 'The battle for the Sanbi comes to an end as neither the Konoha ninja nor Orochimaru are successful at obtaining it. Tsunade classifies the mission of catching the Sanbi as a failure, for it is too dangerous to accomplish. As Naruto and the others prepare to return home, Yukimaru goes missing. Unbeknownst to everyone, Akatsuki lies in wait, and they have their own plans for the Sanbi.', 23, '2009-06-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 6, 'S6 • Master''s Prophecy and Vengeance', 'Sasuke''s future hangs in the balance as Orochimaru prepares for reanimation. It''s been three years since Sasuke left the Leaf Village seeking the power Orochimaru promised him. Now it''s time to face his mentor. Who will master whom in the battle for their very existence?
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 113, 'The Serpent''s Pupil', 'Orochimaru''s body has reached its limit and the time for the ritual has come. Sasuke has other plans, however, and seeks to target a bedridden Orochimaru.', 23, '2009-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 114, 'The Eye of the Hawk', 'Orochimaru reveals the true, hideous form his body has taken from years of experimenting on his body. Can Sasuke defeat this menacing form, or does Orochimaru still have a few tricks up his sleeves?', 23, '2009-06-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 115, 'Zabuza''s Blade', 'After Sasuke reverses Orochimaru''s body-switch with his Sharingan, he releases one of Orochimaru''s test subjects, Suigetsu. Determined to put together a team to achieve his goals, he decides to request Suigetsu''s assistance. Suigetsu agrees, but only if he''s willing make a detour to the Land of Waves first.', 23, '2009-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 116, 'Guardian of the Iron Wall', 'The second member of Sasuke''s team is revealed to be a woman named Karin. After Sasuke and Suigetsu arrive at the Southern Hideout, Sasuke requests that Karin comes with them. Despite her hesitations and quarrels with Suigetsu, Karin ultimately accepts after remembering her very first encounter with Sasuke. Sasuke orders Suigetsu to release the prisoners, and after that, they set off to recruit the final member of the team - Jugo.', 23, '2009-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 117, 'Jugo of the Northern Hideout', 'Having successfully recruited Karin, Sasuke seeks out the final member for his platoon, Jugo. Karin warns Sasuke and Suigetsu of Jugo''s uncontrollable murderous instincts, but as they arrive at the northern hideout, they find another matter they must attend to first. Elsewhere, shocking news reaches the ninja of Konoha.', 23, '2009-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 118, 'Formation!', 'After successfully convincing Jugo to join his team, Sasuke finally has everyone he needs for his platoon. He names his platoon Team Hebi, and explains the true reason as to why he gathered them all together. Back in Konoha, Naruto takes a guess on what Sasuke is planning and proposes a new plan to everyone: they must find and capture Itachi Uchiha.', 23, '2009-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 119, 'Kakashi Chronicles ~ Boys'' Life on the Battlefield ~ Part 1', 'Over ten years ago, the Five Great Nations’ were in the midst of the Third Great Ninja War. Future Fourth Hokage Minato Namikaze assigns young Kakashi, Obito of the Uchiha clan, and Rin, on a mission to Kannabi Bridge...', 23, '2009-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 120, 'Kakashi Chronicles ~ Boys'' Life on the Battlefield ~ Part 2', 'Obito ignores Kakashi’s order to continue with the mission and leaves to save Rin, who was kidnapped by the Rock ninja. But the enemies detect Obito’s arrival and defeat him. Kakashi arrives at the last minute and saves Obito…', 23, '2009-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 121, 'Assemble', 'As Akatsuki seals yet another tailed beast, Itachi and Kisame are warned that Sasuke and his group are after them. Both Konoha and Team Hebi prepare to move out for their quests to find Itachi, but Sasuke makes a little trip to an old Uchiha storage house first.', 23, '2009-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 122, 'The Hunt', 'Kakashi splits the two teams into five separate groups, each aided by a couple of his ninja dogs, in order to locate clues about Itachi and Sasuke''s whereabouts. Unbeknownst to everyone, familiar foes have set their eyes upon both Naruto''s group and Sasuke.', 23, '2009-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 123, 'Clash!', 'Upon encountering one another, Sasuke and Deidara engage in battle. After exchanging a few blows to test Sasuke’s strength, Deidara conjures up his specialty clay dragon and wages long-range attacks against Sasuke from high above. With Tobi’s backup support, the battle seems to be going to Deidara.', 23, '2009-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 124, 'Art', 'Sasuke''s Sharingan proves to be superior against Deidara''s explosives. Deidara creates one of his finest works, the C4 Karura, in order to take him down. What will Sasuke do now?', 23, '2009-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 125, 'Disappearance', 'By using himself as an explosive, Deidara creates an explosion ten kilometers in diameter, something not even Sasuke will be able to escape from. Is this the end of Sasuke? Elsewhere, someone approaches the Akatsuki leader and gives him orders to catch Naruto himself. Who is this true mastermind of the Akatsuki plot lurking in the shadows?', 23, '2009-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 126, 'Twilight', 'As Sasuke rests from his battle with Deidara, the Leaf ninja pick up on his trail. Noticing that they''re being followed, Karin tries to send them in the wrong direction while the members of Team Hebi head to the nearest Akatsuki hideout in hopes of finding Itachi. What will happen when Naruto and Sasuke have separate encounters with Itachi?', 23, '2009-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 127, 'Tales of a Gutsy Ninja ~Jiraiya Ninja Scroll ~ Part 1', 'Having become genin, Jiraiya, Tsunade, and Orochimaru are assigned to the future Third Hokage''s platoon. Watching Sarutobi''s space/time ninjutsu, Jiraiya becomes absorbed into learning it. One day, Jiraiya loses his way and stumbles upon Myouboku Mountain. There he meets the Great Toad Sage who predicted his arrival. See the origins of the Toad Sage Jiraiya!', 23, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 128, 'Tales of a Gutsy Ninja  ~ Jiraiya Ninja Scroll ~ Part 2', 'In the Rain Country, Jiraiya decides to take care of three young orphans for a while. Yahiko, a spunky young boy, wants Jiraiya to train him, Konan, and Nagato to be shinobi, but it''s not until he sees a strange phenomenon in Nagato that he decides to do so. What is the secret behind Nagato''s Rinnengan eyes? What will become of these three children?', 23, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 129, 'Infiltrate! The Village Hidden in the Rain', 'While the members of Team Hebi head towards Itachi''s location, Jiraiya infiltrates the Hidden Rain Village in hopes of gathering information on the Akatsuki leader. Jiraiya captures two Rain ninja and interrogates them about Pain, but what he learns shocks even him.', 23, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 130, 'The Man Who Became God', 'Having suspicions about the Nine-Tails'' attack on the Hidden Leaf Village years ago, Jiraiya tells one of his frogs that the time may come when Naruto will need to access the fox''s full power. His interrogations finished, Jiraiya sets out in search for Pain, but winds up encountering Konan instead. Is there a connection between Jiraiya, Konan, and the mysterious Pain? Elsewhere, one of Naruto''s shadow clones runs into Team Hebi.', 23, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 131, 'Honored Sage Mode!', 'Having no other choice against Pain''s powerful and strange summonings, Jiraiya undergoes a powerful transformation to go up against Pain with the help of the Toad Sages. Will this Sage Mode be enough for Jiraiya to take on not only the Pain he''s been fighting, but two more as well?', 23, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 132, 'In Attendance, the Six Paths of Pain', 'Jiraiya is now confronted by two new Pains who both possess different abilities than the one he was fighting. Just who is Pain and how many Pains are there?', 23, '2009-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 133, 'The Tale of Jiraiya the Gallant', 'Jiraiya realizes that the six Pains are all ninja he''s met before. Putting various pieces of information together, Jiraiya figures out Pain''s true identity, but Pain doesn''t intend to allow Jiraiya to leave with that information alive. Elsewhere, the fated meeting between Itachi and Sasuke arrives, and Sasuke foresees Itachi''s death.', 23, '2009-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 134, 'Banquet Invitation', 'Sasuke''s long awaited battle with Itachi begins with the Uchiha brothers throwing genjutsu after genjutsu at each other. Sasuke seems to have Itachi cornered and asks him a few questions of the Uchiha massacre. Is Itachi not the only one involved in the Uchiha massacre? And does Sasuke still not possess enough hatred to defeat Itachi?', 23, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 135, 'The Longest Moment', 'Sasuke''s long awaited battle with Itachi begins with the Uchiha brothers throwing genjutsu after genjutsu at each other. Sasuke seems to have Itachi cornered and asks him a few questions of the Uchiha massacre. Is Itachi not the only one involved in the Uchiha massacre? And does Sasuke still not possess enough hatred to defeat Itachi?', 23, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 136, 'The Light & Dark of the Mangekyo Sharingan', 'Itachi reveals to Sasuke that Madara is the second culprit behind the Uchiha massacre, as well as the history of the Mangekyo Sharingan and the first two Uchiha to obtain it: Madara and his brother. One question still remains: Why did Itachi really spare Sasuke''s life?', 23, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 137, 'Amaterasu!', 'After successfully breaking out of Itachi''s Tsukiyomi, Sasuke gains the upper hand on his weakened brother. With no other alternative, Itachi activates his second Mangekyo ability, Amaterasu, a black flame said to burn forever.', 23, '2009-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 138, 'The End', 'Sasuke thinks that he''s finally killed Itachi with the help of his most powerful technique, Kirin, but Itachi still has one final trick up his sleeve. Having used both Tsukiyomi and Amaterasu, Itachi calls upon the power of his third and final Mangekyo ability, Susano''o. Itachi has turned the tide of the battle against Sasuke, but the latter receives aid from an unexpected source. The battle between the Uchiha brothers is nearing its shocking conclusion!', 23, '2009-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 139, 'The Mystery of Tobi', 'As Sasuke has finally fulfilled his goal in killing Itachi and avenging his clan, he collapses from exhaustion. The news of his victory reaches the Leaf ninja and Tobi, who both race towards Sasuke''s location. What does Tobi plan to do with him and who will reach Sasuke first?', 23, '2009-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 140, 'Fate', 'Seeking to gain Sasuke''s trust, Madara reveals to him the origins of Konoha. Madara and the future First Hokage founded the village long ago, but a rivalry between them would one day stem a chain of events leading to THAT night, the night that Itachi Uchiha annihilated the Uchiha Clan.', 23, '2009-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 141, 'Truth', 'After Madara finishes telling Sasuke about his past, he reveals the unfathomable truth about Itachi''s massacre of the Uchiha Clan. What really happened on that night? Why did Itachi join Akatsuki? And for what reason did he really spare Sasuke''s life?', 23, '2009-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 142, 'Battle of Unraikyo', 'The Konoha teams decide to head back home as Sasuke remembers that he saw Itachi crying after the massacre. He then states that he cannot rebuild the Uchiha clan in the same way that Itachi had envisioned. Madara, happy that he can use Sasuke for himself, assigns Taka the task of capturing the Eight-Tails while Akatsuki hunts the last two. Taka tracks down the host, Killer Bee, to the Land of Lightning and engages him in battle. Bee manages to overpower Jugo and Suigetsu before Sasuke steps up to fight him one-on-one.', 23, '2010-01-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 6), 143, 'The Eight-Tails vs. Sasuke', 'Sasuke fights Killer Bee and is injured by his swords. Karin heals him, and Sasuke, Suigetsu, and Jugo then begin a combined assault on Bee until he decides to use the Eight-Tails'' power. Sasuke is injured and revived again by Jugo, who regresses in age as a result. All healed, Sasuke unleashes Amaterasu on Bee, finally able to subdue him. Meanwhile, two Cloud ninja watch the fight from a cliff, and they notice the Uchiha crest on Sasuke. They rush the news to Bee''s big brother, the Raikage.', 23, '2010-01-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 7, 'S7 • The Six-Tailed Demon Slug', 'The team is heading back to the village when an urgent assignment comes in from Tsunade that will lead them on a perilous journey to protect a young woman!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 144, 'The Wanderer', 'After failing to bring back Sasuke, the Leaf ninja start heading back to the Hidden Leaf Village. Tsunade, however, sends Katsuyu to inform them that the barrier of Mount Katsunagi of the Tsuchigumo Clan, which holds a powerful forbidden jutsu, is broken. While Kakashi and Team 8 head back to the Leaf Village, Team 7, lead by Yamato, must check out what events are taking place.', 23, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 145, 'Successor of the Forbidden Jutsu', 'Naruto, Sai, and Yamato escort Hotaru to the hidden village of the Tsuchigumo Clan. Upon arriving, however, the villagers don''t seem so happy to see Hotaru. Elsewhere, after Utakata reflects upon the time he spent with her, he comes face to face with Akaboshi and his group.', 23, '2010-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 146, 'The Successor''s Wish', 'As Naruto heads back to the Tsuchigumo Clan village, Akaboshi and his group find Hotaru with the help of Hotaru''s uncle. Hotaru manages to escape but the ninja bandits surround her in the forest. Utakata comes to her aid and manages to take her and escape from the ninja bandits. Akaboshi and his group are about to chase after them until their boss arrives and reveals to them that Utakata is in the Hidden Mist Village''s Bingo Book.', 23, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 147, 'Rogue Ninja''s Past', 'Naruto, Sai, and Yamato arrive to save Hotaru and Utakata from the attacking ninja who they discover are Anbu from the Hidden Mist Village. Yamato attempts to negotiate alone with the head of the Mist Anbu, Tsurugi, and after their discussion, Tsurugi talks to Utakata alone. Tsurugi attempts to convince Utakata to return to the Hidden Mist Village but the latter refuses and remembers the horrible pain he suffered at the hands of his former master.', 23, '2010-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 148, 'The Heir to Darkness', 'Naruto and his team, along with Hotaru and Utakata, return to Mount Katsuragi to plan their next move. Tonbei reveals a way to remove the forbidden jutsu from Hotaru''s body which would result in the jutsu losing it''s power. Hotaru states that if a man named Shiranami returned, the clan would be restored. Naruto decides to look for Shiranami within two days. Little do they know, the man they are looking for is actually the one after the forbidden jutsu. Meanwhile, Utakata wonders if Tsurugi spoke the truth about his master.', 23, '2010-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 149, 'Parting', 'Naruto manages to find Shiranami''s location but he discovers that the Shiranami he found was actually the ninja bandits disguised as him. Hotaru finds the real Shiranami where the latter convinces Hotaru not to have the forbidden jutsu removed, and takes her back to the Tsuchigumo Village. After Naruto is saved by Utakata from the ninja bandits, the two return to the Tsuchigumo Village, where they find that Shiranami has everyone in the village under his control.', 23, '2010-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 150, 'The Forbidden Jutsu Released', 'While the rest of Team Kakashi holds back the possessed villagers and the ninja bandits, Naruto and Utakata go to save Hotaru. When they find her, they discover that Shiranami has activated the jutsu and Hotaru is also under Shiranami''s control. Can Naruto and Utakata stop Shiranami and save Hotaru before the forbidden jutsu is fully charged?', 23, '2010-03-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 7), 151, 'Master and Student', 'After the peformance of the forbidden jutsu, Hotaru is horrified to see the damage the jutsu has done. Shiranami then notices the forbidden jutsu overflowing with chakra and the fact that it would destroy itself along with Hotaru. While Naruto chases the fleeing Shiranami, Utakata tries to save Hotaru using the hidden power within him. Can Utakata save Hotaru?', 23, '2010-03-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 8, 'S8 • Two Saviors', 'Naruto and his friends successfully decipher the code Jiraiya left behind, but it''s not enough to solve the mystery of Pain. For Naruto, Jiraiya''s passing is more than enough to inspire him to follow Fukasaku to Mount Myoboku, where he begins his training in Sage Jutsu. But will the antsy Naruto ever be able to sit still long enough to achieve Sage Mode? Back in the Leaf Village, disaster strikes when the Six Paths of Pain attack the village, and those dearest to Naruto are thrown into the chaos of battle!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 152, 'Somber News', 'Team Kakashi returns to the Hidden Leaf Village after completing their mission. As Naruto thinks back to the talk he had with Itachi, he''s summoned by Tsunade, where he discovers shocking news regarding Jiraiya.', 23, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 153, 'Following the Master''s Shadow', 'Shikamaru tries to decipher the dying message Jiraiya left before his death but cannot figure out what it says. Shikamaru asks for Naruto''s help, thinking he might know the code. Can the saddened Naruto decipher Jiraiya''s dying message?', 23, '2010-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 154, 'Decryption', 'The code Jiraiya left behind is finally deciphered, but what exactly does it mean? Meanwhile, Naruto continues his training.', 23, '2010-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 155, 'The First Challenge', 'After reading Jiraiya''s first book, Naruto becomes more determined than ever to complete his training. Elsewhere, the angered Raikage plans to call all of the kage together for a meeting.', 23, '2010-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 156, 'Surpassing the Master', 'Naruto succeeds in mastering his Sage Mode, taking it farther than even Jiraiya could. Things aren''t looking so great for Konoha, however, as Pain prepares to make his move.', 23, '2010-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 157, 'Assault on the Leaf Village!', 'The Akatsuki Leader, Pain, begins his invasion of the Hidden Leaf Village. The Leaf ninja assemble to protect Naruto''s whereabouts, but when Pain targets Iruka, Kakashi must face off against him.', 23, '2010-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 158, 'Power to Believe', 'Tsunade issues an order to call Naruto back to the village, but the elders do not trust her judgment on this issue. While Tsunade tries to convince them and prepares to join the battle herself, Kakashi fights Pain in an effort to figure out his abilities.', 23, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 159, 'Pain vs. Kakashi', 'Kakashi continues to fight against Pain. With the arrival of Chouji and Chouza, things start looking up, but Pain''s not out of tricks just yet.', 23, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 160, 'Mystery of Pain', 'When Kakashi falls against Pain, the situation only grows worse for Konoha. Shizune and Inoichi are close to unraveling the mystery of Pain, but when the Animal and Human paths of Pain appear before them, can they escape with the truth about Pain?', 23, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 161, 'Surname Is Sarutobi. Given Name, Konohamaru!', 'Ebisu protects Konohamaru from Pain and refuses to divulge any information about Naruto. Ebisu is willing to give up his life in order to protect both Naruto and Konohamaru. Konohamaru isn''t about to let his teacher throw his life away, but what can he possibly do against Pain?', 23, '2010-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 162, 'Pain to the World', 'Pain confronts Tsunade and questions her about Naruto''s whereabouts. Tsunade argues with Pain about his motives, but Pain soon gets the info he needs from another source. Before preparing to depart, Pain unleashes a devastating attack on the village! Meanwhile, Naruto prepares to return to the Leaf Village, but he may be too late.', 23, '2010-05-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 163, 'Explode! Sage Mode', 'Naruto returns and discovers that the village has been devastated by Pain''s Shinra Tensei attack. Naruto requests that everyone stays back as he prepares to take on all six paths of Pain at once.', 23, '2010-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 164, 'Danger! Sage Mode Limit Reached', 'Naruto successfully begins taking out Pain''s bodies one after another, but when his Sage Mode reaches its limit, Pain attempts to take control of the battle. Is the moment of Pain''s victory at hand, or does Naruto have a plan?', 23, '2010-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 165, 'Nine-Tails, Captured!', 'Pain''s God Realm finally enters the battle. As Naruto''s toad allies fall one by one, the situation begins to look grim. Can Naruto defeat Pain?', 23, '2010-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 166, 'Confessions', 'As Pain tells Naruto about why he does what he does, Hinata appears on the scene and confesses her feelings to Naruto. In order to save him, she attacks Pain... Things are about to get messy and Naruto is about to go over the edge!', 23, '2010-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 167, 'Planetary Devastation', 'Naruto''s rage pushes him to unleash six of the Kyubi''s tails against Pain. In order to combat this menace, Pain is forced to rely upon his most powerful technique to stop Naruto. Will Pain succeed in defeating Naruto, or will the most unexpected of allies appear to calm Naruto down?', 23, '2010-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 168, 'The Fourth Hokage', 'The Fourth Hokage appears in Naruto''s mind and prevents him from foolishly setting the Kyubi free. Will this confrontation between father and son give Naruto the confidence he needs to stop Pain once and for all?', 23, '2010-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 169, 'The Two Students', 'Naruto confronts Nagato and tells him that he''ll give him the answer to the question Pain asked him earlier after he hears about what made Nagato turn to his evil ways. What is Naruto''s answer, and what conclusion will Nagato reach?', 23, '2010-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 170, 'Big Adventure! The Quest for the Fourth Hokage''s Legacy ~ Part 1', 'The Fourth Hokage, Minato Namikaze, left behind his legacy before he passed away. Naruto, Sakura, and Sasuke attempt to find Minato''s legacy before the other shinobi teams can get to it.', 23, '2010-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 171, 'Big Adventure! The Quest for the Fourth Hokage''s Legacy ~ Part 2', 'Naruto, Sakura, Shikamaru, Ino, and Choji continue to search for the Fourth Hokage''s Legacy while chasing off some unexpected visitors.', 23, '2010-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 172, 'Meeting', 'Nagato tells Naruto about how he met Yahiko and Konan and later came to be Jiraiya''s disciple.', 23, '2010-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 173, 'Origin of Pain', 'Nagato reveals the truth about what happened to Yahiko and what made him disregard Jiraiya''s ideals. With his story done, he demands to hear Naruto''s answers. Will Naruto''s answer be enough to convince Nagato to stop his evil plans, or will Naruto be forced to kill Nagato?', 23, '2010-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 174, 'The Tale of Naruto Uzumaki', 'With Nagato''s story done, Naruto tells him his answer, declaring that he won''t abandon the legacy of his master, and he''ll keep striving for peace no matter what pain he''s put through. Nagato reflects on what Naruto says, thinking back to his final days as one of Jiraiya''s students. How will Nagato ultimately respond to Naruto''s answer?', 23, '2010-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 8), 175, 'The Hero of the Hidden Leaf', 'Deciding to believe in Naruto, Nagato uses the Gedo Art: Rinne Rebirth jutsu, expending the last of his chakra, and thus giving his life, to revive every person in the village who died in the attack, saying that it''s the least he can do. With Nagato dead, Konan leaves Akatsuki, taking Nagato and Pain''s God Realm (who is actually the body of Yahiko) with her, parting with Naruto saying that since Nagato believed in him to achieve true peace, she will as well. As Naruto returns to the Leaf, he is astonished to find the entire village awaiting his return, hailing him as a true hero. After all these years, Naruto has finally received the acknowledgment he''s always wanted.', 23, '2010-08-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 9, 'S9 • Past Arc: The Locus of Konoha', 'After Pain''s attack, the Leaf Ninja set about rebuilding their village. Naruto and Sakura are thrilled to be reunited with Tazuna and his grandson Inari from the Land of Waves, who have come to help. While the restoration proceeds, the Leaf Ninja and their friends reflect on past events that influenced the village and helped gain allies like the Sand.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 176, 'Rookie Instructor Iruka', 'In the aftermath of the destruction of the Leaf Village, Iruka thinks back to the time when the Third Hokage first gave him the task of being Naruto''s homeroom teacher at the Academy, since no one else would take him in.', 23, '2010-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 177, 'Iruka''s Ordeal', 'Iruka struggles to deal with his hate for the Nine-Tailed Fox inside Naruto as he tries to connect with Naruto after seeing him shunned by his peers.', 23, '2010-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 178, 'Iruka''s Decision', 'After discovering a kunai knife with a secret message on it, Naruto winds up being pursued by three kunoichi from the Hidden Waterfall Village. Iruka mangaes to find him, but when the situation grows worse, Kakashi appears to save them both.', 23, '2010-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 179, 'Kakashi Hatake, The Jonin in Charge', 'Kakashi has a flashback back when he was assigned to be the sensei of Team 7. In a bid to know his students, Naruto, Sasuke & Sakura, better, Kakashi spies on them and to see how they would all get along as a group. Angered by Sakura''s talk about calling Naruto a brat and that he has no family to tell him right or wrong, Sasuke tells Sakura she is annoying. Realizing Sakura''s sadness, Naruto goes to battle Sasuke, but gets defeated. It then goes back to the present and Kakashi claims that it is up to him to stop Sasuke.', 23, '2010-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 180, 'Inari''s Courage Put to the Test', 'As the ninja of the Hidden Leaf Village work on repairing their village in the aftermath of Pain''s invasion, Naruto and Sakura come across a familiar face among the carpenters: Inari and Tazuna have arrived to help out. Inari recalls what happened after Gato''s death and how Naruto and Sasuke came to his rescue.', 23, '2010-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 181, 'Naruto''s School of Revenge', 'In a flashback of Naruto and Sakura''s, Team 7 is on a mission to take an ostrich called Mr. Ostrich to his home. They arrive at a village where they see a swordsman named Tsukado who has a vendetta to carry on a man named Katazu who killed his distant relative Shikazo. Tsukado fails to defeat him so Naruto decides to teach him unusual revenge lessons. Katazu has then took his brother''s identity and attracted Shikazo''s pursuers while Kageki and his family went into hiding. Tsukado decides not to kill him and ends their years of fighting though Kanabun wants them to keep fighting. The swordsmen, Team 7 and Mr. Ostrich chase the Kanabun Gang out of town.', 23, '2010-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 182, 'Gaara''s Bond', 'After hearing the news about Akatsuki''s attack on the Hidden Leaf Village, Gaara worries about Naruto''s well-being. He remembers a time in the past where Team 7 was assigned to help him out with a problem, and how nobody, especially Naruto, was eager to trust him. Yet, when his life was put in danger by people he had wronged, Naruto was the first to come to his rescue.', 23, '2010-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 183, 'Naruto: Outbreak', 'Sakura reflects upon a time when she was infected with a strange disease by Naruto. In order to find a cure, an order was issued for Naruto to be quarantined at all costs before he could infect anybody else.', 23, '2010-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 184, 'Deploy! Team Tenten', 'While she and Neji prepare to visit an old man who makes ninja weapons, Tenten remembers the first time she visited him alongside Naruto and Neji. Utilizing a strange new weapon she had never seen before, Tenten fought against two ninja who had stolen two of the man''s powerful weapons.', 23, '2010-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 185, 'Animal District', 'An ostrich tells a story of when Naruto, Rock Lee, and Shino, all led by Kotetsu, entered the Leaf Village''s animal district in an effort to find and subdue him. However, he and the other animals proved that they weren''t willing to go down without a fight.', 23, '2010-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 186, 'Ah, the Medicine of Youth', 'Back before Rock Lee had his surgery, Naruto, after donning the suit given to him by Guy, set out on a mission with Sakura and Ino to obtain a special flower which was a necessary ingredient for Lee''s medicine. When Naruto picked one of the flowers, however, he had to face a strange technique that had taken on the form of Gaara.', 23, '2010-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 187, 'Gutsy Master and Student: The Training', 'During the two-and-a-half-year time period in which Naruto was training under Jiraiya, the latter decided that it was time for Naruto to learn how to repel genjutsu. During this training session, the two traveled to a village which Jiraiya had previously been associated with, but they discovered that something dark was amidst.', 23, '2010-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 188, 'Record of the Ninja Gutsy Master and Student', 'After having discovered that the village was under the control of rebels from the Hidden Rain Village, led by Hanzo, Naruto and Jiraiya decided to take action to help save the women and children taken hostage and free the village from the Rain''s tyrannical control.', 23, '2010-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 189, 'Sasuke''s Paw Encyclopedia', 'In the past, Naruto and Sakura joined Sasuke on a mission to collect the paw print of Nekomata, a large and powerful two-tailed ninja cat that ruled over all of the ninja cats.', 23, '2010-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 190, 'Naruto and the Old Soldier', 'Naruto, two jonin and an elder known as "the Eternal Genin" set off to a mission to patrol the border of the Land of Fire following Orochimaru''s attack. After some days with no incidents, a group of enemy ninjas cross the borders. The Eternal Genin proves to be a brave ninja and remembering the lessons he learned with the 2nd and 3rd hokages, sees the similarities between Naruto and his father.', 23, '2010-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 191, 'Kakashi Love Song', 'A female spy, Hanare, from the Hidden Lock Village (Land of Key) is caught by ANBU pretending to be a musician. She is interrogated. However, the interrogation proves unsuccessful. Slowly, her past is revealed and so is her relationship with Kakashi. Team 7 spy on the two as they go around town, under the impression that the two are dating. After The Lock Village keeps a Leaf Village ninja hostage, they exchange Hanare for the ninja. It is then revealed that Hanare has a special ability, causing a large chase to occur. In the end, Kakashi lets Hanare free. The musician seen at the beginning entertaining Konoha ninja reminds Kakashi of Hanare which prompts the flashback.', 23, '2010-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 192, 'Neji Chronicles', 'Konohamaru''s team asks Neji to talk about Naruto''s heroism. Instead, Neji tells them about an incident during the Chunin exams three years prior. While Orochimaru attacked Konoha, two rogue ninja take advantage of the commotion and kidnap Hinata. Neji, Tenten, Kiba, and Akamaru rush out to save her. They''re in trouble until Hiashi shows up and saves them, telling Neji that he''s the beloved memory of Hiashi''s younger brother. Neji realizes Naruto''s speech about destiny was right; he isn''t just a slave to the clan name. Konohamaru''s team complains that Naruto wasn''t in the story at all, and Neji cryptically answers that Naruto was the most important part.', 23, '2010-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 193, 'The Man Who Died Twice', 'Naruto thinks back to the time when he encountered the soul of a man named Kisuke. Kisuke didn''t recall anything about who he was, but a visit to the Leaf Village''s hospital revealed something startling. Meanwhile, higher-ups of the Fire Country met to decide on a new security system for the Leaf Village put together by a ninja named Sabiru. Who exactly were Kisuke and Sabiru, and what connection did the two have?', 23, '2011-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 194, 'The Worst Three-Legged Race', 'Naruto thinks back to the time when Team 7 was on a mission to capture a group of thieves who stole a golden statue. When making a move on the thieves, Naruto and Sasuke had managed to take back the statue but were separated from Sakura, who was captured. On top of that, the thieves'' leader had used a special thread-like technique to bind one of Naruto''s hands to one of Sasuke''s. Literally stuck to each other, would Naruto and Sasuke be able to work together to save Sakura and keep the golden statue safe at the same time?', 23, '2011-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 195, 'Team 10''s Teamwork', 'Shikamaru remembers the time when Teams 7 and 10 joined together to flush out a band of bandits who were terrorizing a nearby village and had kidnapped the headman''s granddaughter. With no assistance available from Kakashi or Asuma, Shikamaru was forced to lead the team of genin to the bandits'' fort and come up with a plan to rescue the headman''s granddaughter.', 23, '2011-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 9), 196, 'Drive Towards Darkness', 'Sasuke has a flashback while traveling to Konoha with his team, Taka. He once saved a girl named Naho not knowing that she''s a relative of the Feudal Lord. Meanwhile, Naruto and Sakura are sent on a mission to accompany Naho and act as her bodyguards while Kakashi and Sasuke are sent to discover the reason why internationally wanted bandits have entered their border. Kakashi and Sasuke later find out that the bandits intend to abduct Naho. Naruto and Sakura are defeated by the bandits and are taken hostage. Sasuke finds them first and proceeds to defeat the leader and mercilessly punches him because of his jealousy for Naruto''s growing power. A cut to the present reveals Naruto contemplating on his promise to have Sasuke return to the village.', 23, '2011-01-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 10, 'S10 • The Gathering of the Five Kage', 'In the aftermath of the attack on the village, Naruto and Sakura are shocked to discover that Danzo has been selected as the new Hokage. And his first order of business involves Team 7''s own Rogue Ninja-Sasuke! Then, the Kage from each village gather for a summit in the Land of Iron, and Naruto seeks a pardon for Sasuke from the Raikage. But the cycle of hatred runs deep in the shinobi world, and while the Five Kage discuss how to deal with the Akatsuki, the mysterious one calling himself Madara steps forward to reveal truths that will turn Naruto''s world upside down!
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 197, 'The Sixth Hokage Danzo', 'Naruto and Sakura learn that Danzo has been made Hokage and that his first order is to eliminate Sasuke. The two go to Sai and inquire about Danzo, but Sai reveals that a curse mark given to all members of the Foundation prevent him from revealing anything about the new Hokage. Soon afterward, Karui and Darui attack them, demanding information about Sasuke.', 23, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 198, 'Five Kage Summit''s Eve', 'Karui decides to get information about Sasuke from Naruto by any means necessary. When Naruto refuses to sell Sasuke out, Karui takes out her frustration upon the former. Meanwhile, Danzo prepares for the Kage Summit, and determines to keep Naruto confined to the Leaf Village.', 23, '2011-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 199, 'Enter the Five Kage!', 'The time has come for each Kage to leave for the Kage Summit in the Land of Iron. On his way to the meeting, Danzo gets attacked by shinobi from the Wood Country who want to take his head. Meanwhile, Naruto, with Kakashi and Yamato by his side, heads off to find the Raikage to convince him to spare Sasuke.', 23, '2011-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 200, 'Naruto''s Plea', 'Naruto stands before the Raikage and begs him to forgive Sasuke. Will the Raikage listen to what he has to say? Later, the Five Kage Summit gets underway. Mifune suggests that the Five Great Nations should form the first alliance of its kind; but also nominates Danzo to be the leader. How will the other Kages react to the latter proposal?', 23, '2011-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 201, 'Painful Decision', 'As chaos breaks out at the Five Kage Summit regarding Mifune''s proposal to make Danzo leader of the alliance, Ao discovers something unsettling about the new Hokage. Meanwhile, Shikamaru goes to Sakura and asks permission to take decisive action against Sasuke. How will Sakura react, and what is Danzo''s secret?', 23, '2011-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 202, 'Racing Lightning', 'Without any warning, Zetsu bursts through the floor in the middle of the Five Kage Summit and announces that Sasuke is somewhere in the vicinity. The Summit is immediately put on hold, and the Kages and samurai begin searching for him. Meanwhile, Naruto receives an unexpected visit from Madara, who says that he needs to talk to him. How will Sasuke respond to being discovered, and what are Madara''s intentions?', 23, '2011-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 203, 'Sasuke''s Ninja Way', 'With Team Hawk exposed, Sasuke begins to ruthlessly take down all opposing samurai. Raikage, along with Darui and Shii, track down Sasuke. The two sides engage in battle, and Suigetsu and Juugo join the fray. Which side will win this battle of overwhelming power?', 23, '2011-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 204, 'Power of the Five Kage', 'Sasuke uses Susano''o to slip past Gaara and the Raikage and heads towards Danzo. Just as the latter is within Sasuke''s grasp, however, the Mizukage stands in his way.', 23, '2011-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 205, 'Declaration of War', 'The four Kage are startled by the sudden appearance of Madara Uchiha. Having sent Sasuke away to safety using the Transportation Technique, Madara unveils to the Kage his “Project Tsuki no Me.”', 23, '2011-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 206, 'Sakura''s Feelings', 'Sakura, not wanting to cause Naruto any more pain, tells him that he can let go of his promise about bringing Sasuke back, and claims that she doesn''t feel anything more for Sasuke. To top it off, Sakura confesses her feelings for Naruto, taking everyone by surprise. How will Naruto respond? Meanwhile, Kisame tracks down Killer Bee and the battle for the Eight-Tails begins.', 23, '2011-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 207, 'The Tailed Beast vs. The Tailless Tailed Beast', 'As Killer Bee''s battle with Kisame rages on, the latter reveals a hidden trump card ability connected with Samehada. Meanwhile, Ao chases down Danzo, Fuu, and Torune, but they anticipate this and set a trap for him. Can Killer Bee and Ao make it through their individual clashes in one piece?', 23, '2011-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 208, 'As One''s Friend', 'One of Sai''s clones tells Naruto the truth surrounding Sasuke, something that Sakura couldn''t bring herself to do. Before Naruto can even comprehend what Sai just said, they are interrupted by Gaara. What additional bad news concerning Sasuke does Gaara bring for Naruto?', 23, '2011-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 209, 'Danzo''s Right Arm', 'Madara brings Sasuke out of his dimension to battle Danzo. When Sasuke demands answers concerning Itachi, things turn ugly, and Danzo reveals a few tricks he has up his sleeves (literally). What is Danzo''s true strength, and can Sasuke summon enough power to suppress it?', 23, '2011-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 210, 'The Forbidden Visual Jutsu', 'Danzo brings forth a forbidden genjutsu known as Izanagi, which has the astounding power to turn dreams into reality and vice versa. Izanagi''s great power comes with a time limit, but Sasuke''s strength is rapidly dwindling as well. Can Sasuke resist long enough, or will Danzo completely overpower him?', 23, '2011-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 211, 'Danzo Shimura', 'As the fight between Sasuke and Danzo comes to a close, the latter will do whatever it takes to finish off the former. Meanwhile, Sakura and her team close in on Sasuke.', 23, '2011-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 212, 'Sakura''s Resolve', 'Sakura ditches her team and goes alone to Sasuke''s location. Meanwhile, Madara advises Sasuke to finish off Karin, but at the last second Sakura intervenes. After so long, what interaction will take place between Sasuke and Sakura?', 23, '2011-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 213, 'Lost Bonds', 'As he is resting, Naruto starts dreaming his past experiences with Sasuke that made the two friends closer. When he tries to follow Kakashi, who is in pursuit of Sakura, he is stopped by Yamato, saying that he has orders from Kakashi to return Naruto to Konoha. Naruto devises a plan to sneak out and leaving a shadow clone to fool Yamato. He goes into Sage Mode to locate Kakashi. He then starts remembering the experiences that brought Sasuke pain in his life. Naruto decides what he can do for Sasuke if they come face to face.', 23, '2011-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 214, 'The Burden', 'Kakashi rescues Sakura from certain death at Sasuke''s hands and takes over the fight. After healing Karin, Sakura again decides to take on Sasuke, but her resolve fails her. Just as she comes close to death a second time, Naruto intervenes and saves her. After so long, the original Team 7 is reunited.', 23, '2011-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 215, 'Two Fates', 'Naruto reproaches Sasuke for attempting to kill Sakura. Then Sasuke reveals that he killed Danzo with his own hands. He goes on to declare his intent to purify the Uchiha clan’s name by annihilating the Hidden Leaf.', 23, '2011-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 216, 'High-Level Shinobi', 'As Naruto and Sasuke clash, their Rasengan and Chidori explode, sending them both flying. When Zetsu and Madara appear to aid Sasuke, they decide to retreat to the Akastuki headquarters. Before they leave, however, Naruto has one last thing to say to Sasuke; something that will have an impact on both of their lives.', 23, '2011-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 217, 'The Infiltrator', 'Naruto returns to the Leaf Village, and his teammates demand to know why he didn''t finish Sasuke off when the latter was in such a weak state. Naruto tells them that when the time is right, he will deal with Sasuke personally. Meanwhile, a supposedly deceased member of Akastuki has infiltrated the Hidden Cloud Village.', 23, '2011-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 218, 'The Five Great Nations Mobilize', 'The formation of the Allied Shinobi Forces is ratified by the Feudal Lords of the Five Great Nations. Each Kage returns to their village to prepare for the coming war.', 23, '2011-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 219, 'Kakashi Hatake, the Hokage', 'Naruto gathers his friends and tells them that he will defeat Sasuke alone. Meanwhile, the Elders of the Leaf officially nominate Kakashi to become the next Hokage.', 23, '2011-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 220, 'Prophecy of the Great Lord Elder', 'In Mount Myoboku, Gerotora, Fukasaku, and the Great Lord Elder are debating whether to give Naruto the key to the Tetragram Seal left behind by Jiraiya, an act that could unleash the Nine Tails.', 23, '2011-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 10), 221, 'Storage', 'At Mount Myoboku, Naruto prepares to store Gerotora within himself, but hesitates as it also holds the potential risk of unleashing the Nine Tails on the world.', 23, '2011-07-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 11, 'S11 • Paradise on the Ship', 'Naruto declares to his friends his intention to take on Sasuke by himself, while the Elders of the Leaf make a serious decision about who will fill the vacant seat of Hokage: Kakashi! In Mount Myoboku, Gerotora, Fukasaku and the Great Lord Elder debate whether or not to give Naruto the key to the Tetragram Seal that Gerotora holds, an act that could potentially unleash Nine Tails.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 222, 'The Five Kage''s Decision', 'The denizens of the Leaf Village ready themselves for the coming of the Fourth Great Ninja War.', 23, '2011-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 223, 'The Young Man and the Sea', 'Tsunade sends out Naruto under the guise of a top-secret mission to keep him hidden away from the Akatsuki. Unfortunately, Naruto, Yamato, Gai, and Aoba are stuck at the pier due to a report of a monster attacking ships.', 23, '2011-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 224, 'The Ninja of Benisu', 'During their voyage, Naruto, Yamato, Gai, and Aoba stop at an island to recover from severe seasickness. There, they unexpectedly meet up with Sakura, Ino, and Choji, who are on an assignment to gather medical herbs for Tsunade.', 23, '2011-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 225, 'The Cursed Ghost Ship', 'As they continue their voyage towards the Land of Lightning, Naruto, Aoba, Guy and Yamato sail through a thick fog. To pass the time, Yamato tells Aoba and Naruto some ghost stories (much to Naruto''s dislike).', 23, '2011-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 226, 'Battleship Island', 'On their way to the Land of Lightning, Naruto''s ship gets caught in a storm. When the crew gets out of it, they encounter a savage group of pirates, who attempt to sink their boat and capture them. Yamato shields the boat with a Wood technique and they escape underwater in a sub-like contraption, which promptly falls apart. They wash up in an underwater cavern underneath the island the pirates had taken over some time ago. The residents of the island had taken refuge in the caves until they all died. Naruto swears to avenge them all. With a clever plan, Naruto and the ship are rocketed out of the island''s dormant volcano top using underground hot springs and he successfully avenges the island folk by defeating the pirates.', 23, '2011-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 227, 'The Forgotten Island', 'Going after Guy, who was whisked away by a giant bird, Naruto, Yamato, and Aoba arrive on an island where they spot a young woman.', 23, '2011-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 228, 'Fight! Rock Lee!', 'Might Guy recalls their "visualization" training with Lee in order to avoid learning the Drunken Fist and forgetting an incident which Might Guy apologizes to the restaurant owner with humiliation. Lee, who is determined to train to be stronger than Naruto, follows Might Guy''s orders and resemble animal fighting styles which represent on a restaurant menu. However they failed, until they tried on training on a moving boat. Like Guy who has seasickness, Lee also suffers from seasickness but he uses it to balance the boat which resembles exactly as the Drunken Fist fighting style. Guy lately realizes that Lee is also aware of the restaurant incident and Lee was only protecting Guy from a drunk man which causes the restaurant to be totally damaged.', 23, '2011-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 229, 'Eat or Die! Mushrooms from Hell', 'Making a stop at a nearby port to stock up on supplies, Naruto buys a rare mushroom from a vegetable merchant. But soon after they set sail for their next destination, Naruto and the other crewmembers find their ship infested with poisonous mushrooms.', 23, '2011-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 230, 'Revenge of the Shadow Clones', 'The ship is caught in a storm and Naruto uses his shadow clones to protect the ship.After the storm, Naruto wakes up and a quarrel begins between Naruto and his Shadow clones. Soon his shadow clones revolt and take control of the ship and the crew is forced to land on a nearby island. Naruto is taken hostage by the shadow clones and they put forth their demands to him. Naruto is saved by Yamato and the others only to find that it was a dream. It was caused when a Shadow clone was released and the memories of it returned to Naruto. Naruto then realizes the worth of his clones and releases them.', 23, '2011-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 231, 'The Closed Route', 'Shikamaru begins to feel the pressure of shouldering the lives of his friends in the upcoming Fourth Shinobi World War. To help ease his mind, Shikaku sends his son along with Tenten on a mission to Mokuzu Island to replenish supplies.', 23, '2011-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 232, 'The Girls'' Get-Together', 'Hinata’s father Hiashi summons the Hyuga clan to discuss the role they will be playing in the upcoming Fourth Great Ninja War.', 23, '2011-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 233, 'Naruto''s Imposter', 'Naruto finds an imposter that has been building his reputation by attempting to steal from other people while his friend is also attempting to gain a reputation by "beating" the imposter up so he builds his reputation even further and become a ninja.', 23, '2011-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 234, 'Naruto''s Favorite Pupil', 'Konohamaru is eager to fight alongside his senior ninja in the coming war, but his young age prevents him from being assigned to the battlefield.', 23, '2011-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 235, 'The Kunoichi Of Nadeshiko Village', 'Naruto meets two kunoichi ninja named Shizuka and Tokiwa from the Nadeshiko village who are seeking the student of Jiraiya.', 23, '2011-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 236, 'Friends You Can Count On', 'While talking with his students, Shino talks about how he and his team got together and became more close as friends and teammates. The story switches to Shino''s flashback during the first part of Naruto. They are on a mission assigned by Kurenai in which a Jonin assassin from a neighboring village. Shino gets defeated because of weak taijutsu and descends into depression. He even reveals he was going to abandon the team that helped him because he didn''t think he was useful to them. But after his friends get in trouble with the rouge Shino comes back and defeats the rouge.', 23, '2011-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 237, 'Ah, My Hero Lady Tsunade!', 'Tenten remembers when she was little and how she really wanted to become like the legendary Tsunade. She finds out through hard training that she won''t be capable of the strength Tsunade has. She also finds out that she won''t be suitable to be a medical ninja for her poor chakra control. But at last, she discovers that she has the ability to summon ninja tools, thus creating her own style of fighting.', 23, '2011-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 238, 'Sai''s Day Off', 'Given the day off, Sai spends it strolling the village and drawing. He initially encounters three children that he at first finds it difficult to interact with but later realises that two of them remind him of his team-mates Naruto and Sakura. He has several flashbacks of their time together and the bonds they share. In the end he uses the doors of a destroyed house and paints a mural of Team 7 along with Sasuke holding hands.', 23, '2011-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 239, 'The Legendary Ino-Shika-Cho', 'As Team Asuma considers the impending war, they encounter Kosuke Maruboshi who reminds them of the time that they rescued him while they were still genin. With this, Kosuke retells the tale of the time their fathers saved him during the Invasion of Konoha with their Formation Ino–Shika–Chō. Somewhat rattled by this story, Kosuke reminds them that great shinobi weren''t made in a day. As the team contemplates everything, they decide to perfect their own formation, insisting that they''d be fine because they were not alone.', 23, '2011-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 240, 'Kiba''s Determination', 'Kiba trains hard to catch up to Naruto, who is now hailed as the hero of the Leaf Village, but with little success. Feeling desperate, Kiba asks Kakashi if he could train him.', 23, '2011-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 241, 'Kakashi, My Eternal Rival!', 'As the Leaf ninja’s ship heads toward their final stop for supplies before entering the Land of Lightning, Yamato warns the crew to stay alert for enemies who could mimic both the appearance and chakra of their closest allies.', 23, '2011-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 11), 242, 'Naruto''s Vow', 'During his final stop for supplies on an island in the Land of Water, Naruto runs into Akatsuchi and Kurotsuchi of the Hidden Stone, who are on an assignment to deliver a letter from the Tsuchikage addressed to the Mizukage.', 23, '2011-12-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 12, 'S12 • Nine-Tailed Fox Taming and Karmic Encounters', 'As the Leaf Village prepares for war, each shinobi and clan must contemplate the role they will play in the battles to come. While Naruto''s peers seek training from surprising sources, Naruto himself must confront both his biggest weakness and greatest strength – the Nine-Tailed Fox.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 243, 'Land Ahoy! Is this the Paradise Island?', 'After a long voyage at sea, Naruto’s ship finally arrives at the island of its destination. Before everyone can rejoice, a giant squid attacks the ship. Fortunately, the crew is saved by Killer Bee, the Eight Tails’ jinchuriki host.', 23, '2012-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 244, 'Killer Bee and Motoi', 'Motoi confesses to Naruto and Yamato that he attempted to kill Bee during their childhood because of his father''s death due to the sealing of the Eight Tails 30 years ago.', 23, '2012-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 245, 'The Next Challenge! Naruto vs. The Nine Tails!', 'With Killer Bee as his new master, Naruto begins his training to control the power of a Tailed Beast. In order to do so, one must fight the Tailed Beast head on and absorb its chakra, converting it into one’s own power.', 23, '2012-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 246, 'The Orange Spark', 'Inside his mind, Naruto continues his battle against Nine Tails to take control of its immense power.', 23, '2012-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 247, 'Target: Nine Tails', 'Sixteen years ago, Fourth Hokage Minato Namikaze and his wife Kushina are expecting their first child, much to the delight of the young couple.', 23, '2012-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 248, 'The Fourth Hokage''s Death Match!', 'Minato is forced to use his Flying Raijin jutsu and leave his wife Kushina behind to save their newborn son, Naruto, from a masked assailant.', 23, '2012-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 249, 'Thank You', 'The Nine Tails, having been released from Madara''s control, continues to wreck havoc in the city. The Third Hokage summons the Monkey King Enma and drives the Nine Tails away from the city. Minato then returns to the city and with the help of the toad Gamabunta is able to restrain the Nine Tails long enough for him to teleport it along with his family to the outskirts of the village. Kushina binds the Nine Tails and as Minato prepares to do the Reaper Death Seal to seal away half of the Nine Tails Chakra and seal the rest inside Naruto using the Eight Trigrams Seal. He also seals a bit of Kushina''s chakra to help Naruto tame the Nine Tails. All of this is witnessed by the Third Hokage and a few other ninja.', 23, '2012-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 250, 'Battle in Paradise! Odd Beast vs. The Monster!', 'Guy arrives at the Waterfall of Truth to help Naruto with his training. Instead he encounters Kisame, who has infiltrated the island to locate Naruto and Killer Bee.', 23, '2012-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 251, 'The Man Named Kisame', 'The after-effects of Guy''s Daytime Tiger are felt throughout the island. Kisame is defeated, and Guy explains his technique. Yamato restrains him so Aoba can gather intel. When he''s about to learn Tobi''s identity, Kisame forces himself awake by biting off his own tongue. Kisame breaks free of his restraints and creates a water dome around himself. He recalls Itachi''s words about learning what kind of person one is when they die. Knowing he''s too weak to resist, and to prevent his enemies from gathering intel, Kisame summons sharks and allows himself to be eaten. The others are impressed by Kisame''s resolution. When they open the scroll Kisame intended to deliver, it turns out to be a trap, leaving them stuck inside water prisons, while a summoned shark takes the scroll with the intel away.', 23, '2012-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 252, 'The Angelic Herald of Death', 'Tobi heads to Hidden Rain Village to retrieve Nagato''s Rinnegan. Konan, now a former member of Akatsuki, recollects her past until Tobi arrives. Tobi asks Konan where is Nagato''s Rinnegan and Konan replies that it is not located in the village. Their battle started and Tobi tells Konan that he encouraged Yahiko to form Akatsuki and he gave the Rinnegan to Nagato. Konan transforms into thousands of pieces of paper to self-destruct against Tobi, yet it fails and both survives. Konan unleashes a powerful paper technique that looks like a sea of paper beneath their feet.', 23, '2012-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 253, 'The Bridge to Peace', 'Konan encloses Tobi in an chasm with a large amount of explosive tags that detonates in a wide area. Tobi manages to survive with his Izanagi techique, sacrificing one eye, and pierces Konan behind. Tobi explains his technique to Konan. Konan refuses to give up and continues to fight Tobi. Tobi manages to subdue her and places Konan inside a genjutsu to force her to reveal the location of the Rinnegan. Tobi travels to the location and retrieves Nagato''s corpse and then takes his leave. A bloodied piece of paper is blown of Konan''s body by the wind and travels to her childhood hideout. As it travels, more of the Ame Orphans past with Jiraiya is revealed, as well as some of their time as the original Akatsuki. Meanwhile, Tobi, with a new outfit, is told by Zetsu that they have received intel on the Nine-Tails wherabouts from Kisame. He declares that it''s time to capture the Nine-Tails.', 23, '2012-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 254, 'The Super Secret S-Rank Mission', 'Zetsu reports on new intel from Kisame and Madara learns about Naruto hideout. Tsunade, Gaara, Lord Raikage, and others must figure out how to get Naruto out of the secret island of Land of Lighting and all without telling him about the war. New mission is introduced.', 23, '2012-03-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 255, 'The Artist Returns', 'Kabuto and a reanimated Deidara attempt to grab hold of the jinchuriki, but are stopped by the Tsuchikage, who has come to protect Naruto.', 23, '2012-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 256, 'Assemble! Allied Shinobi Forces!', 'Fourth Great Ninja War is about to begin, ninjas are going through their formations, medical supplies are being checked and restocked. The title of this Naruto Episode is "Assemble Allied Shinobi Forces". The headbands are done. Let''s go! Tsuchinage saves Nine Tails and Eight Tails, but Yamato gets captured.', 23, '2012-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 257, 'Meeting', 'Part One of the Four Week Long Special Project for the Broadcast''s Tenth Anniversary - A look back into the early years when Naruto and Sasuke first met.', 23, '2012-04-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 258, 'Rivals', 'Part Two of the Four Week Long Special Project for the Broadcast''s Tenth Anniversary - During the Chunin Exam, Sasuke witnesses Naruto’s growth as a shinobi.', 23, '2012-04-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 259, 'Rift', 'Part Three of the Four Week Long Special Project for the Broadcast''s Tenth Anniversary - Sasuke’s defeat to Gaara, and later Itachi, forces him to realize that he is not strong enough to get revenge against his older brother.', 23, '2012-04-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 260, 'Parting', 'Part Four of the Four Week Long Special Project for the Broadcast''s Tenth Anniversary - Naruto is determined to save Sasuke, who has deserted the Hidden Leaf.', 23, '2012-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 261, 'For My Friend', 'The Allied Shinobi Forces are on standby, ready to confront Madara’s army of reanimated shinobi and 100,000 White Zetsu. But distrust still exists among the Allied Shinobi Forces, who were once sworn enemies until recently.', 23, '2012-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 262, 'War Begins', 'Kankuro’s commando unit enters enemy territory to set up a stronghold for the Allied Shinobi Forces. They are immediately ambushed by the Akatsuki’s own commando unit comprised of the reanimated Deidara and Sasori.', 23, '2012-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 263, 'Sai and Shin', 'The Allied Shinobi Forces’ commando unit engages with the Akatsuki in the first wave of battle.', 23, '2012-05-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 264, 'Secrets of the Reanimation Jutsu', 'Under the guidance of Killer Bee, Naruto enters the final stage of training to master the Tailed Beast Bomb, a Jinchuriki’s most powerful technique.', 23, '2012-05-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 265, 'An Old Nemesis Returns', 'The commando unit is in hot water as they engage the reanimated Kekkei Genkai shinobi, which include Zabuza Momochi and Haku. Luckily, Kakashi and his unit arrive in time to assist them.', 23, '2012-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 266, 'The First and Last Opponent', 'Kakashi and his unit devise a strategy to take on the Kekkei Genkai shinobi, but it’s foiled by Kabuto, who uses the Reanimation Jutsu to summon the most powerful members of the Seven Ninja Swordsmen of the Mist.', 23, '2012-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 267, 'The Brilliant Military Advisor of the Hidden Leaf', 'The Akatsuki dispatch an army of powerful reanimated shinobi and White Zetsu across the war zone, causing chaos within the Allied Shinobi Forces’ chain of command.', 23, '2012-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 268, 'Battleground!', 'As Darui and his First Company engage an army of White Zetsu, the remaining forces must deal with reanimated shinobi.', 23, '2012-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 269, 'Forbidden Words', 'Atsui, Samui, and Darui face off against Kinkaku and Ginkaku, the legendary brothers from the Hidden Cloud, feared even by the Raikage.', 23, '2012-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 270, 'Golden Bonds', 'Darui manages to seal away Ginkaku. Fueled by the rage of losing his brother, Kinkaku transforms into a monster that resembles a jinchuriki’s Tailed Beast State.', 23, '2012-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 271, 'Road to Sakura', 'Ino sees Sakura falling from the sky. Although she manages to save her, the shock of the fall has left Sakura with amnesia.', 23, '2012-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 272, 'Mifune vs. Hanzou', 'Kankuro’s Commando Unit is cornered by Hanzo’s poison attack. Fortunately, Mifune and his Fifth Company arrive in time to provide assistance.', 23, '2012-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 273, 'True Kindness', 'The Ino-Shika-Cho trio is ordered by Shikaku to take down the reanimated Asuma. Remembering Asuma’s final words, Shikamaru and Ino are determined to stop their former teacher.', 23, '2012-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 274, 'The Complete Ino-Shika-Cho Formation!', 'Choji is unable to attack Asuma and loses his will to fight. Ino and Shikamaru try to snap Choji out of his paralysis.', 23, '2012-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 12), 275, 'A Message from the Heart', 'While training in Chakra Mode, Naruto senses the presence of the Nine Tails’ chakra seeping from Kinkaku outside. Curious to find out what’s happening, Naruto tries to leave the training room when Iruka suddenly steps in to stop him.', 23, '2012-08-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 13, 'S13 • The Seven Shinobi Swordsman', 'The Fourth Great Ninja War rages on, and danger comes from every angle. Old comrades and enemies have risen from the grave under the control of Kabuto to fight the Allied Forces. While some retain their calm, others must wrestle with their emotions. Naruto''s training has made him more powerful, but some believe his possession of the Nine Tails makes him a liability. Meanwhile, Sakura and the Medical Ninja face unique danger, as an enemy may be in their midst behind the allied lines. Can the Allied Forces survive assassins and their reanimated friends to win the war?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 276, 'Attack of the Gedo Statue', 'The Allied Shinobi Forces are on the verge of winning the war when Madara Uchiha appears. Madara summons the giant Gedo Statue and unleashes its devastating power.', 23, '2012-08-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 277, 'Unison Sign', 'Naruto and Killer Bee rush to the battlefield when Nine Tails suddenly speaks to Naruto inside his mind. The Nine Tails questions Naruto’s intent to end the hatred in the world and reminds him of how he was unable to save Sasuke.', 23, '2012-08-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 278, 'Medic Ninja in Danger', 'Over at the Medical Unit camp, Sakura and the other medic ninja work nonstop to treat the wounded. Neji is there to recover from overusing his Byakugan.', 23, '2012-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 279, 'White Zetsu''s Trap', 'Kiba, Shino, and Hinata are sent to investigate an area where the Akatsuki are supposedly getting through. There, the three are ambushed by a White Zetsu and get separated.', 23, '2012-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 280, 'Aesthetics of an Artist', 'As the Allied Shinobi Forces'' headquarters scramble to deal with White Zetsu Army clones infiltration issue, word reaches the Fifth Division of the development and Mifune instructs his division accordingly.', 23, '2012-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 281, 'The Allied Mom Forces!', 'Konohamaru participates in a meeting organized by Ebisu in Konoha of the remaining villagers, mostly including the children and wives. Ebisu attempts to rally everyones'' spirits together in the event that rogue ninja should attack the village while their shinobi families are away at war, but the mothers scoff and claim that they will protect the village as they always have while their husbands fought. Suddenly Konohamaru is approached by several children, each claiming to have seen terrifying rogue ninja roaming the east and west forests outside Konoha. He tries to recruit his classmates into hunting them down, but they refuse to beleive him. Konohamaru investigates the area alone with Moegi and Udon, only to find a traveling circus troupe in the forest instead of rogue ninja. Heading back, Konohamaru is again alerted that people are attacking the village on the west side, and this time, the rumors are true...', 23, '2012-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 282, 'The Secret Origin of the Ultimate Tag Team!', 'Tsunade and the Raikage arrive to prevent Naruto and Killer Bee from joining the battle. But the two Kage fail to convince the Jinchuriki to turn back, forcing the Raikage to use extreme force.', 23, '2012-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 283, 'Two Suns', 'Fourth Raikage Ay attacks Naruto in an attempt to prevent the Jinchuriki from falling into Madara’s hands. Ay is unwilling to listen to either Tsunade or Killer Bee’s pleas to change his mind.', 23, '2012-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 284, 'The Helmet Splitter: Jinin Akebino!', 'Kakashi assigns Sai to take over for the Sealing Corps, who are recovering from sealing the reanimated shinobi. But Sai is not sure if he can handle the responsibility. Soon afterwards, the Third Company is attacked by Jinin Akebino.', 23, '2012-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 285, 'User of the Scorch Style: Pakura of the Sand!', 'A group of Allied Shinobi, including Omoi and Maki of the Sand, battle against several reanimated enemies. Maki recognizes one of them as Pakura, her former master who was a Sand Village hero.', 23, '2012-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 286, 'Things You Can''t Get Back', 'Still coping with the loss of her loved ones, Tsunade indulges in gambling and drinking. Around the same time, the Raikage Ay and his men are on a mission to steal a scroll from a certain village.', 23, '2012-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 287, 'One Worth Betting On', 'The Raikage Ay and his team suffer critical injuries during an enemy attack. Unwilling to sacrifice any more of his men, Ay seeks medical help from Tsunade, who just happens to be in the area.', 23, '2012-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 288, 'Danger: Jinpachi and Kushimaru!', 'Kakashi races to the scene where the Seven Ninja Swordsmen Kushimaru Kuriarare and Jinpachi Munashi were last sighted. Enraged by the carnage they’ve left behind, Kakashi teams up with Might Guy.', 23, '2012-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 289, 'The Lightning Blade: Ameyuri Ringo!', 'As Guy and Kakashi prepare to regroup their forces, they receive word that one of the units were engaged in battle with Ameyuri Ringo and decide to head to that location.', 23, '2012-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 290, 'Power - Episode 1', 'Taking place in the aftermath of the Kage Summit, Team Kakashi is sent out on a mission by Tsunade to a location known as "The Hole" to investigate an incident where its people were killed.', 23, '2012-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 291, 'Power - Episode 2', 'The reborn Team Kakashi continues to investigate the recent attack by Kabuto and the reincarnated shinobi when Naruto gets swallowed by a giant snake, but manages to escape using shadow clones, and accidentally ingests snakes that were present in the pond which Kabuto uses to summon Hidan.', 23, '2012-11-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 292, 'Power - Episode 3', 'Miina wakes up in the middle of a night after having a nightmare where Naruto is consumed by numerous snakes inside his subconscious while the Nine-Tails looks on and goes to Dokku for consolation.', 23, '2012-12-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 293, 'Power - Episode 4', 'The Nine-Tailed Naruto clone tries to attack Dokku and the orphans, when Might Guy and Rock Lee arrive to repel it.', 23, '2012-12-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 294, 'Power - Episode 5', 'While the Saezuri is revealed, learning that Disonasu employed Kabuto Yakushi to wipe out the residents of Tonika Village, Dokku tried to attack Disonasu, but stopped by a reincarnated puppet and restrained by a resurrected Takigakure shinobi.', 23, '2012-12-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 13), 295, 'Power - Final Episode', 'The legendary Ama no Hoko imbues the Nine Tails’ clone with enough power to destroy the world. Naruto is overcome by its immense power and lies unconscious.', 23, '2013-01-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 14, 'S14 • The Fourth Great Ninja War - Assailants From Afar', 'Gaara leads the Fourth Company into battle against the previous Kage, including his own father. Meanwhile Naruto and Killer Bee face the reanimated Itachi Uchiha, who recognises Naruto’s growth as a shinobi and his potential to rescue his brother, Sasuke, from his path of vengeance. Battles rage, and all must face enemies—as well as friends—they never expected to see again!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 296, 'Naruto Enters the Battle!', 'Naruto makes his entrance onto the battlefield and uses his sensory powers to detect and destroy the transformed White Zetsu clones. During the battle, Shikaku updates Naruto with what they currently know on Madara.', 23, '2013-01-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 297, 'A Father''s Hope, A Mother''s Love', 'Gaara leads the Fourth Company into battle against the previous Kage, including his father, the late Fourth Kazekage. The Fourth Kazekage attacks Gaara in order to determine if his son is truly worthy to be the current Kazekage.', 23, '2013-01-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 298, 'Contact! Naruto vs. Itachi', 'Naruto and Killer Bee engage in battle against the reanimated Itachi Uchiha and Nagato. Itachi learns from Naruto that Sasuke has chosen the path of vengeance.', 23, '2013-01-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 299, 'The Acknowledged One', 'Itachi uses the ultimate genjutsu technique Koto Amatsukami to free himself from the Reanimation Jutsu. Itachi then joins Naruto and Killer Bee to fight Nagato, who is still under Kabuto’s control.', 23, '2013-02-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 300, 'The Mizukage, the Giant Clam, and the Mirage', 'The Fourth Company continue their fight against the reanimated Kage. Gaara and Ohnoki team up to hold off Second Tsuchikage Mu, while the remaining shinobi take on the Second Mizukage, who is willing to be sealed away.', 23, '2013-02-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 301, 'Paradox', 'Temari leads the attack on the Third Raikage using Wind Style, but even her strongest jutsu is not enough to penetrate the Raikage’s invincible armor.', 23, '2013-02-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 302, 'Terror: The Steam Imp', 'Gaara and Ohnoki manage to overcome the Second Mizukage’s mirage attack. Having taken an interest in Gaara, the Second Mizukage decides to further test the young Kage’s skills.', 23, '2013-02-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 303, 'Ghosts from the Past', 'Shikamaru, Choji, Neji, and Kiba find themselves up against some familiar faces from the past. The Sound Ninja Four have been brought back by Kabuto’s Reanimation Jutsu, and they are ready to seek vengeance.', 23, '2013-03-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 304, 'The Underworld Transfer Jutsu', 'Shikamaru, Neji, Choji, and Kiba succeed in defeating the Sound Ninja Four. But the enemy uses the Underworld Transfer Jutsu to trap the Leaf shinobi’s souls inside a barrier.', 23, '2013-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 305, 'The Vengeful', 'Time is running out for the Leaf shinobi whose souls are trapped inside the Sound Four’s barrier. Ino and Shino exhaust their own chakra to keep their friends alive.', 23, '2013-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 306, 'The Heart''s Eye', 'Hinata defends Neji from a White Zetsu clone while he’s recovering from an earlier fight. She then remembers the time Neji protected her the same way after she temporarily lost her sight.', 23, '2013-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 307, 'Fade into the Moonlight', 'Three years ago, Leaf Anbu Yugao Uzuki lost her lover Hayate Gekko in battle. Unable to cope with his death, Yugao has since left the Anbu and joined the Medical Corps. Meanwhile, Kabuto has reanimated Hayate.', 23, '2013-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 308, 'Night of the Crescent Moon', 'Yugao is ordered by Sukui to track down the reanimated Hayate. Still shaken by her lover’s unexpected return as an enemy, Yugao manages to catch up to Hayate and his men.', 23, '2013-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 309, 'An A-Rank Mission: The Contest', 'Naruto arrives to help a team of Allied Shinobi Forces led by Karui, who are struggling against a reanimated samurai. Naruto recognizes the samurai as Tatewaki, a man he met during a past mission.', 23, '2013-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 310, 'The Fallen Castle', 'The Leaf Shinobi succeed in bringing young lord Shu into custody, placing a disguised Naruto as his double. But Tatewaki soon uncovers Naruto’s identity and surrounds the intruder with his men.', 23, '2013-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 311, 'Prologue of Road to Ninja', 'Madara is prepping his new jutsu Limited Tsukuyomi, choosing Naruto as his test subject. Meanwhile, Naruto is spending his day off alone in his room. Thinking that Naruto is lonely, Lee suggests they all go to the bathhouse for some relaxation.', 23, '2013-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 312, 'The Old Master and the Dragon''s Eye', 'Might Guy arrives on the battlefield to stop a Reanimated Shinobi who he recognizes as Master Chen, the legendary Taijutsu User from the Third Great Ninja War.', 23, '2013-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 313, 'Rain Followed by Snow, With a Chance of Lightning', 'A reanimated boy who can control weather appears before Team Ino-Shika-Cho, Sakura, and Kiba, who are all fighting in different locations. To their surprise, the boy seems to know them.', 23, '2013-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 314, 'The Sad Sun Shower', 'The weather-controlling enemy is revealed to be Yota, a boy who came to the Leaf Village years ago and befriended the local kids, including Naruto.', 23, '2013-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 315, 'Lingering Snow', 'Naruto and the others finally regain their lost memories regarding Yota. Years ago, the Leaf Village kids came to befriend Yota, but the adults believed the young boy was a spy and took him away for questioning.', 23, '2013-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 316, 'The Reanimated Allied Forces', 'Kabuto reanimates an army of unknown shinobi led by Danzo’s former bodyguard Torune to retrieve the ones he lost to the Allied Forces. But aside from Torune, the reanimated shinobi are all weak and are quickly sealed away.', 23, '2013-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 317, 'Shino vs. Torune!', 'During their battle against the White Zetsu, Shino’s beetles detect the presence of another enemy. Leaving the fight to Kiba and the others, Shino goes to investigate and finds Torune preparing to unleash his forbidden jutsu.', 23, '2013-06-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 318, 'A Hole in the Heart: The Other Jinchuriki', 'Kabuto reanimates Fukai to attack Killer Bee and Motoi. Fukai warns Killer Bee to escape before being taken over by Kabuto. To everyone’s surprise, Fukai releases Eight Tails’ chakra and enters Tailed Beast State.', 23, '2013-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 319, 'The Soul Living Inside the Puppet', 'A reanimated Granny Chiyo attacks Kankuro and Mifune’s team. Kankuro fights back by using the human puppet of Sasori. The sight of Sasori causes Granny Chiyo to recall the painful memories that led her grandson to create his human puppets.', 23, '2013-06-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 14), 320, 'Run, Omoi!', 'The Allied Forces receive a report that Omoi has deserted his post, much to the Raikage’s shock. It is soon revealed that Omoi has defied orders to go save the Thundercloud Unit.', 23, '2013-07-04');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 15, 'S15 • The Fourth Great Ninja War - Sasuke & Itachi', 'As the Fourth Great Ninja War rages on, the endless waves of Reanimated Shinobi take their toll as the Allied Shinobi Forces are forced to keep fighting their own fallen friends and comrades. Meanwhile, Naruto deepens his understanding of warfare, learning to sense the disguised White Zetsu sowing confusion and distrust among the Allied Forces. But all the effort and pain aren''t for nothing, as Gaara and Ohnoki draw closer than ever to discovering who is really behind this devastating conflict.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 321, 'Reinforcements Arrive', 'White Zetsu’s ability to mimic people’s appearances has wrought confusion and distrust within the Allied Shinobi Forces. Naruto arrives to assist, and using his sensory powers, he identifies all the disguised White Zetsu clones, changing the tide of the battle.', 23, '2013-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 322, 'Madara Uchiha', 'The reanimated shinobi appearing before Gaara and Ohnoki is revealed to be none other than Madara Uchiha himself…which raises the question of who the masked man claiming to be Madara really is.', 23, '2013-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 323, 'The Five Kage Assemble', 'The power of the reanimated Madara Uchiha far exceeds what the Allied Forces expected. Despite the difference in power, the Third Tsuchikage, Ohnoki, along with Naruto and Gaara, refuses to give up.', 23, '2013-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 324, 'The Unbreakable Mask and the Shattered Bubble', 'Naruto and Killer Bee face off against the masked man originally thought to be Madara Uchiha, in addition to the reanimated Jinchuriki. Naruto is shocked when he recognizes one of the Jinchuriki.', 23, '2013-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 325, 'Jinchuriki vs. Jinchuriki!!', 'Naruto and Killer Bee take on the six Reanimated Jinchuriki, who’ve been equipped with the Rinnegan. Using his past experience from fighting the Six Paths of Pain, Naruto devises a plan to stop the Jinchuriki.', 23, '2013-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 326, 'Four Tails, the King of Sage Monkeys', 'Kakashi and Guy arrive in the nick of time to back up Naruto and Killer Bee. The fight intensifies even further when three out of the six Reanimated Jinchuriki enter Tailed Beast State, forcing Naruto and the others to throw in everything they’ve got.', 23, '2013-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 327, 'Nine Tails', 'Naruto finds himself inside Four Tails’ inner world, where he promises to free Four Tails from Madara’s control. Listening in on their conversation, Nine Tails recalls all the time he has spent sealed inside Naruto.', 23, '2013-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 328, 'Kurama', 'Naruto finds himself inside Four Tails’ inner world, where he promises to free Four Tails from Madara’s control. Listening in on their conversation, Nine Tails recalls all the time he has spent sealed inside Naruto.', 23, '2013-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 329, 'Two-Man Team', 'Naruto uses up the last of his chakra trying to free the Tailed Beasts from Madara’s control. When all seems lost, the Nine Tails finally acknowledges Naruto as its jinchuriki and offers its help.', 23, '2013-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 330, 'The Promise of Victory', 'The tide of battle is slowly shifting in the Allied Forces’ favor, but many are uncertain that they really stand a chance against Madara Uchiha. To help boost their spirits, Shikaku orders Inoichi to send out a message to every member of the forces.', 23, '2013-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 331, 'Eyes That See in the Dark', 'Suigetsu and Jugo’s search for Sasuke leads them to one of Orochimaru’s old hideouts where they come across his research data, which could tip the outcome of the Fourth Great War. Meanwhile, Sasuke finally sets out to settle his score with Naruto.', 23, '2013-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 332, 'A Will of Stone', 'The Five Kage are outmatched by the real Madara Uchiha’s devastating attacks. Just when Third Tsuchikage Ohnoki is about to give up, he remembers the words of the previous Tsuchikage.', 23, '2013-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 333, 'The Risks of the Reanimation Jutsu', 'Tsunade leaves her post as Medic Ninja to join the other Kage in fighting Madara. Meanwhile, Sasuke goes after Itachi and learns that his brother intends on stopping Kabuto’s Reanimation Jutsu.', 23, '2013-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 334, 'Sibling Tag Team', 'Sasuke and Itachi team up to stop Kabuto’s Reanimation Jutsu. But Kabuto’s new ability to use Nature Energy has made him a difficult target for the brothers to land their Susano’o attack.', 23, '2013-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 335, 'To Each Their Own Leaf', 'Kabuto attempts to bring Sasuke over to his side by pointing out that they both are fighting for the same goal: to bring down the Leaf Village. But Sasuke quickly rejects him.', 23, '2013-10-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 336, 'Kabuto Yakushi', 'Kabuto’s past is finally revealed. As child, a woman named Nonou raised Kabuto at an orphanage in the Leaf Village. One day, Danzo and Orochimaru visit the orphanage to provide financial aid under the condition that Nonou work as their spy.', 23, '2013-10-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 337, 'The Izanami Activated', 'Casting aside Itachi''s lectures to him, Kabuto reveals to the siblings that he had injected himself with the DNA of various shinobi, namely the Sound Five, also including Orochimaru.', 23, '2013-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 338, 'Izanagi and Izanami', 'With Izanami activated, and Kabuto trapped within its infinite loop, Sasuke uses this time to question his brother about the technique. Itachi tells Sasuke about the history behind Izanami''s creation as well as the Uchiha clan''s use of the technique.', 23, '2013-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 339, 'I Will Love You Always', 'Back at the front lines, the five Kage struggle to hold their own against Madara''s Susanoo-clad wood clones.  As the lights surrounding the reincarnated shinobi begin to illuminate the battlefield as they faded into pillars of light, Itachi approaches Sasuke and uses his Sharingan to show Sasuke everything about the Uchiha clan massacre.', 23, '2013-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 340, 'Reanimation Jutsu: Release!', 'Thanks to Itachi, the Reanimation Jutsu is released, and all the Reanimated Shinobi are returned to their resting places. But to everyone’s surprise, the real Madara still remains!', 23, '2013-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 341, 'Orochimaru''s Return', 'Suigetsu and Jugo finally catch up to Sasuke. In order to learn the truth behind the Leaf’s actions, Sasuke decides to resurrect the one man who can help him find the answer—Orochimaru.', 23, '2013-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 342, 'The Secret of the Transportation Technique', 'Having absorbed the chakras of all nine Tailed Beasts, the Gedo Statue begins its transformation into Ten Tails. Naruto, Killer Bee, Kakashi, and Guy try to destroy the Gedo Statue but are stopped by the masked man.', 23, '2013-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 343, 'Who Are You?', 'Kakashi discovers a strange connection between the masked man’s Transportation Technique and his own Kamui Jutsu. Naruto throws everything he’s got against the masked man and breaks his mask, finally revealing his identity!', 23, '2013-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 344, 'Obito and Madara', 'The identity of the masked man is revealed to be Kakashi’s old friend Obito, previously believed to have died in the battle of Kannabi Bridge. Naruto and the others are further shocked when they learn that Obito has been working with Madara Uchiha...', 23, '2014-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 345, 'I''m in Hell', 'After the Battle of Kannabi Bridge, Obito finds himself inside the hidden lair of Madara Uchiha, who saved the young shinobi’s life. There, Obito works to rehabilitate his injured body in the hopes of being reunited with Kakashi and Rin.', 23, '2014-01-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 346, 'World of Dreams', 'Obito watches in disbelief as Kakashi kills Rin. Unable to accept the harsh reality, Obito decides to carry out Madara’s dream so that he can create an ideal world where Rin still exists.', 23, '2014-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 347, 'Creeping Shadow', 'Being informed by Kakashi that the orphans he trained are now attempting to bring about change in the Hidden Rain Village through dialogue, Jiraiya expresses hist satisfaction with his students'' progress.', 23, '2014-01-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 15), 348, 'The New Akatsuki', 'Danzo deliberately misleads Hanzo, telling him that the Akatsuki are attempting to sabotage the peace talks between the Hidden Rain and Stone. Believing his story, Hanzo sets up a trap to crush the Akatsuki for the sake of his people.', 23, '2014-01-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 16, 'S16 • Kakashi - Shadow of the ANBU Black Ops', 'Years before he became Naruto''s teacher, Kakashi served as a member of the ANBU Black Ops team, so ruthless he earned the nickname "Cold-blooded Kakashi." But despite his reputation, he is haunted by the deaths of his closest friends during the Third Great Ninja War.
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 349, 'A Mask that Hides the Heart', 'After the end of the Third Great Ninja War, the Leaf Village is divided over who should become the next Hokage.', 23, '2014-02-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 350, 'Minato''s Death', 'Kakashi becomes part of the ANBU Black Ops, an elite team of shinobi who are under the direct command of the Fourth Hokage, Minato Namikaze.', 23, '2014-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 351, 'Hashirama''s Cells', 'At the Foundation, Kakashi meets a boy who uses Wood Style, a jutsu that only First Hokage Hashirama was capable of using. Kakashi goes to Third Hokage Hiruzen’s library to seek answers and discovers records regarding Hashirama’s cells.', 23, '2014-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 352, 'The Rogue Ninja Orochimaru', 'Orochimaru is forced to flee the Hidden Leaf after Third Hokage Hiruzen exposes his illegal experiments. Danzo, fearing that Orochimaru’s capture would lead to the exposure of his own involvement in the experiments, sends out one of his men to help.', 23, '2014-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 353, 'Orochimaru''s Test Subject', 'While pursuing Orochimaru, Kakashi wanders into a village inhabited by the Iburi Clan, a group of people with the unique ability to turn into smoke. Kakashi is soon captured and learns that the villagers all serve under Orochimaru.', 23, '2014-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 354, 'Their Own Paths', 'Yukimi leaves the village to see the outside world, taking “Tenzo” with her. Kakashi tries to convince the two to return so that he can set a trap to capture Orochimaru, who is after Yukimi’s blood.', 23, '2014-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 355, 'The Targeted Sharingan', 'Danzo orders Tenzo to kill Kakashi and take his Sharingan. Reluctant at first, Tenzo decides to carry out his orders after learning that the Leaf Shinobi has come to be known as “Kakashi the Friend Killer.”', 23, '2014-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 356, 'A Shinobi of the Leaf', 'After being saved by the target he was ordered to kill, Tenzo realizes that the man known as “Kakashi the Friend Killer” is someone who values the lives of his comrades more than anyone.', 23, '2014-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 357, 'An Uchiha ANBU', 'Itachi Uchiha is inducted into Kakashi’s unit as the youngest member of the ANBU Black Ops. Itachi’s father, Fugaku, is pleased, thinking this will grant the Uchiha access to exclusive, top-secret Leaf intel.', 23, '2014-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 358, 'Coup d''État', 'Following the aftermath of the Nine-Tails incident, many on the Leaf Council voice suspicions that the Uchiha Clan were behind this tragedy. The Uchiha are then placed under 24-hour surveillance by the ANBU, which causes further tensions to arise.', 23, '2014-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 359, 'The Night of the Tragedy', 'Kakashi visits the Uchiha District and notices that the community seems more antisocial than the last time he visited. Meanwhile Itachi finds concrete evidence regarding the Uchiha Clan’s coup against the Leaf. The fateful moment is fast approaching…', 23, '2014-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 360, 'Jonin Leader', 'Hiruzen relieves Kakashi of his ANBU duties and assigns him a new position as a Jonin Leader. Reflecting on his past mistakes, Kakashi decides to use the same test that Minato once used to measure one’s teamwork.', 23, '2014-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 16), 361, 'Squad Seven', 'Hiruzen assigns Kakashi to be in charge of Naruto, Sasuke, and Sakura, three genin that bear a striking resemblance to the former Team Minato.', 23, '2014-05-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 17, 'S17 • The Fourth Great Ninja War - The Return of Squad Seven', 'With Kakashi unable to get through to Obito, Naruto leaps to his Sensei''s defense. The release of Ten Tails forces the Allied Shinobi Forces into an assault on Obito and Madara, but the powerful Tailed Beast proves to be a formidable enemy. The devastation is severe, but Hinata''s words spur Naruto to continue fighting with renewed energy, while help arrives from unexpected quarters - including an old adversary! Will Naruto and the Allied Shinobi''s efforts be enough to fend off destruction?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 362, 'Kakashi''s Resolve', 'Kakashi desperately tries to reach out to Obito, but his words fall on deaf ears. Obito instead accuses Kakashi of being trash, which angers Naruto, forcing him to step in and defend his Sensei.', 23, '2014-05-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 363, 'The Allied Shinobi Forces Jutsu!', 'The barrier is shattered, and Ten Tails appears! With unfathomable power in its attack, it sends shock waves through the air! Kurama takes the lead and tries to go on the offensive, but is helpless against Ten Tails'' immense strength.', 23, '2014-05-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 364, 'The Ties That Bind', 'The Allied Shinobi Forces begin their onslaught against Obito and Madara. But Ten Tails suddenly transforms and hurls powerful Tailed Beast Bombs toward distant towns.', 23, '2014-06-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 365, 'Those Who Dance in the Shadows', 'Naruto is overcome with grief over Neji’s death, but Hinata''s words restore his fighting spirit.', 23, '2014-06-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 366, 'The All-Knowing', 'Sasuke returns to the Hidden Leaf Village seeking answers, and standing before him are First Hokage Hashirama, Second Hokage Tobirama, Third Hokage Hiruzen, and Fourth Hokage Minato, all reanimated.', 23, '2014-06-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 367, 'Hashirama and Madara', 'Villages did not exist when Hashirama was a child. It was during this strife-filled time that he met Madara Uchiha.', 23, '2014-07-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 368, 'The Era of Warring States', 'Madara and Hashirama eventually become the leaders of their respective clans.', 23, '2014-07-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 369, 'My True Dream', 'The Senju and Uchiha clans join together to build a shinobi village and fulfill their dreams.', 23, '2014-07-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 370, 'Sasuke''s Answer', 'After listening to what Hashirama and the rest of the former Hokage have to say, Sasuke finally understands how the Leaf Village and its shinobi came to be.', 23, '2014-07-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 371, 'Hole', 'The fighting rages between Naruto, who stands at the vanguard of the Allied Shinobi Forces, and the team of Madara and Obito.', 23, '2014-08-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 17), 372, 'Something to Fill the Hole', 'Ten Tails is on the brink of its final transformation and begins to form a massive Tailed Beast Bomb.', 23, '2014-08-14');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 18, 'S18 • The Fourth Great Ninja War - Obito Uchiha', 'On the same side once more, Naruto and Sasuke prepare for battle as Obito absorbs the power of Ten Tails to become the tailed beast''s Jinchuriki. As the other shinobi watch helplessly, Obito summons the Divine Tree and begins absorbing their chakra as he prepares to perform the Infinite Tsukuyomi. Naruto and his friends must rally their despairing allies to defeat Obito. But will the final battle truly be physical - or will it be a test of wills?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 373, 'Team 7 Assemble!', 'Team 7 is finally reunited when Naruto, Sakura and Sasuke join forces.', 23, '2014-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 374, 'The New Three-Way Deadlock', 'Bearing a close resemblance to the Legendary Sannin, Naruto, Sakura and Sasuke make a stunning arrival on the battlefield with each of their summonings.', 23, '2014-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 375, 'Kakashi vs. Obito', 'Kakashi holds on to the hope that Obito can return to being the young man that he remembers. But Obito has abandoned the present as well as the memories of his friends and is determined to end the world!', 23, '2014-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 376, 'The Directive to Take the Nine-Tails!', 'Part 1 of a special two-part extra edition! The townspeople are going about their daily business on the streets of the Leaf Village when someone suddenly appears and starts sending them flying!', 23, '2014-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 377, 'Naruto vs. Mecha Naruto', 'Part 2 of a special two-part extra edition! The townspeople are going about their daily business on the streets of the Leaf Village when someone suddenly appears and starts sending them flying!', 23, '2014-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 378, 'The Ten Tails'' Jinchuriki', 'Obito completely absorbs the giant Ten Tails, undergoes a transformation and becomes the Ten Tails'' Jinchuriki.', 23, '2014-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 379, 'An Opening', 'Obito has gained complete control over his power as the Ten Tails Jinchuriki. His powerful, cold-blooded attacks force Naruto and his friends into a corner.', 23, '2014-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 380, 'The Day Naruto Was Born', 'Minato is filled with regret during his confrontation with Obito. He thinks if only he had recognized Obito as the Masked Man during the assault on the Hidden Leaf Village, he could have stopped the attack, and maybe Kushina would not have died.', 23, '2014-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 381, 'The Divine Tree', 'Naruto and Minato combine their powers to perform a Sage Jutsu attack on Obito.', 23, '2014-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 382, 'A Shinobi''s Dream', 'The Ten Tails morphs into its final form, "The Divine Tree," and attacks the shinobi, absorbing their chakra one after another.', 23, '2014-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 383, 'Pursuing Hope', 'Naruto''s past, thoughts, and feelings flow into the consciousness of every shinobi, unifying their hearts.', 23, '2014-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 384, 'A Heart Filled With Comrades', 'Naruto and Sasuke size up Obito as the final battle looms.', 23, '2014-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 385, 'Obito Uchiha', 'Naruto objects to Obito’s claim that he is the second Sage of Six Paths and declares that he is Obito Uchiha.', 23, '2014-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 386, 'I''m Always Watching', 'Pressed by Naruto, Obito remembers the time he, Kakashi, and Rin teamed up for the Chunin Exam and when he promised Rin that he would become Hokage.', 23, '2014-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 387, 'The Promise That Was Kept', 'Naruto''s power of persuasion moves Obito''s heart. Due to the influence of the Ten Tails, visions of himself and Rin from the past appear in the inner realm and play havoc with Obito’s emotions.', 23, '2014-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 388, 'My First Friend', 'All the Tailed Beasts are freed, and old friends Kakashi and Obito come face to face with each other. What will Obito''s response be? Meanwhile, the Tailed Beasts and the Allied Shinobi Forces shift their focus onto their greatest foe, Madara Uchiha. Gaara is reunited with his former Tailed Beast, Shukaku. When Gaara asks Shukaku to lend his power to seal Madara, he refuses. Will their history of animosity prevent them from working together?', 23, '2014-11-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 389, 'The Adored Elder Sister', 'Hanabi adores her sister Hinata, who struggles to become a worthy successor to the Hyuga Clan.', 23, '2014-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 390, 'Hanabi''s Decision', 'When Hinata is labeled unfit as a successor, Hanabi''s heart becomes bound to her destiny.', 23, '2014-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 391, 'Madara Uchiha Arises', 'Naruto and the Allied Shinobi Forces successfully extract the Tailed Beasts from Obito. Only Madara remains, and Naruto heads out to tackle this foe.', 23, '2014-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 392, 'The Hidden Heart', 'With his newly revived strength, Madara doesn''t give in against the nine Tailed Beasts.', 23, '2014-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 18), 393, 'A True Ending', 'Despite all efforts, Kurama is extracted from Naruto, and ultimately, all the Tailed Beasts are imprisoned inside the Gedo Statue.', 23, '2014-12-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 19, 'S19 • Naruto''s Back: The Tracks of His Friends', 'Naruto and the Allied Shinobi manage to extract Obito’s Tailed Beasts, leaving Madara as the final foe to defeat. Obito realizes the error of his ways, but Black Zetsu prevents him from interfering. Nine Tails is extracted from Naruto, and he and Sasuke are left near death. In the midst of all this, the turbulent history of the Hyuga clan and events that took place in the Leaf Village while Naruto trained with Jiraya are revealed!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 394, 'The New Chunin Exams', 'The story travels back to the time after Sasuke''s defection from the Leaf and before Naruto''s return from his two-year training journey with Jiraiya.', 23, '2015-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 395, 'The Chunin Exams Begin!', 'The Hidden Leaf begin preparing for the Chunin Exams. Ino and Choji ask Sakura to join their three-man team as a stand-in for Shikamaru, who is already a chunin.', 23, '2015-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 396, 'The Three Questions', 'The Chunin Exams finally begin and the proctor for Round One is none other than Shikamaru!', 23, '2015-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 397, 'One Worthy As A Leader', 'The genin are unable to figure out the answer and start to panic.', 23, '2015-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 398, 'The Night Before the Second Exam', 'On the night before the Second Exam, the entrants gather in the cafeteria, and a brawl breaks out.', 23, '2015-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 399, 'Demon Desert Survival', 'The Second Exam finally begins! To pass this stage, each team must take possession of both the Heaven and Earth scrolls and make it to the designated site in the center of the Demon Desert within 72 hours.', 23, '2015-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 400, 'As a Taijutsu User', 'Noting the similarities of their circumstances, Lee is outraged at the ones who hurt and belittled Shira and sets out in pursuit!', 23, '2015-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 401, 'The Ultimate', 'Lee challenges Shira to a battle between taijutsu users!', 23, '2015-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 402, 'Escape vs. Pursuit', 'Kiba and his team are in pursuit of Hidden Grass Ninja who have stolen their scroll!', 23, '2015-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 403, 'Unwavering Gutsiness', 'Kiba and his team are in pursuit of Hidden Grass Ninja who have stolen their scroll!', 23, '2015-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 404, 'Tenten''s Troubles', 'As the team prepares for dinner, Tenten pulls out a scroll that contains all the ingredients for okonomiyaki.', 23, '2015-03-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 405, 'The Imprisoned Pair', 'An ancient ruin in Demon Desert comes crumbling down during the battle for the scrolls.', 23, '2015-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 406, 'The Place Where I Belong', 'Ino, Sakura and Choji trudge across a desert under the blazing sun without any provisions. Ino and Sakura are arguing when a giant scorpion attacks and injures Sakura.', 23, '2015-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 407, 'The Yamanaka Clan''s Secret Ninjutsu', 'As Ino and her team head toward an oasis, they are attacked by a team of Sand Shinobi comprised of Ameno, Shishio, and Kouji.', 23, '2015-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 408, 'The Cursed Puppet', 'Sakura and her team continue their trek across the desert towards the goal. Their continuous battles have depleted Sakura''s chakra, so they stop to rest. Just then, they encounter a puppet manipulated by a rival team from the Sand and end up being discovered.', 23, '2015-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 409, 'Their Backs', 'Ino and Choji fight to protect an immobilized Sakura although they have depleted most of their chakra due to the relentless fighting.', 23, '2015-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 410, 'The Hidden Plot Set Into Motion', 'Sand Jonin Fugi sneaks into the Demon Desert and creates a massive sandstorm in order to assassinate Gaara, the Fifth Kazekage.', 23, '2015-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 411, 'The Targeted Tailed Beast', 'Gaara heads out to rescue Matsuri and the others but is attacked by a mysterious priest who binds him with a Chakra Chain to capture his Tailed Beast.', 23, '2015-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 412, 'Neji''s Judgement', 'Neji and the team come across Matsuri collapsed in the desert and find out that Gaara is in danger. Meanwhile, the chains of a mysterious priest bind Gaara and Foo.', 23, '2015-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 19), 413, 'Hopes Entrusted to the Future', 'Gaara meets with Fugi, the mastermind behind the assassination attempt on his life. He confides that perhaps, after all the fear and pain he has wrought upon the Sand, he has no right to be their leader.', 23, '2015-05-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')), 20, 'S20 • Infinite Tsukuyomi: The Invocation', 'As Naruto and Sasuke lay near death, Kakashi and a reformed Obito prepare to confront Madara together. But Madara has gained the power of the Six Paths, and Guy may have to make the ultimate sacrifice and open the Gate of Death in order to fight him. But even that may not be enough once Madara activates the Infinite Tsukuyomi, trapping everyone in a dream world. Can this incredible power be broken?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 414, 'On the Brink of Death', 'After his Tailed Beast is extracted, Naruto is on the verge of dying. Sakura desperately tries to save him, but Naruto''s heart gives out.', 23, '2015-05-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 415, 'The Two Mangekyo', 'Madara has transformed into the Jinchuriki of the Ten Tails and appears before Kakashi. Kakashi and the others combine their powers to attack, but they are no match for Madara..', 23, '2015-06-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 416, 'The Formation of Team Minato', 'Kakashi has changed for the worse, and Obito doesn''t know why. He runs into Kakashi and tries to talk to him, but Kakashi gives him the cold shoulder.', 23, '2015-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 417, 'You''ll Be My Backup', 'Obito doesn’t understand Kakashi''s way of thinking, but he finally learns why Kakashi put his mission first that time at Kannabi Bridge. Presently, Obito and Kakashi return together to confront Madara.', 23, '2015-06-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 418, 'The Wild Green Beast vs. Six Paths Madara', 'Guy releases his Eight Inner Gates against Madara, but the Seventh Gate of Shock does not work against him!', 23, '2015-07-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 419, 'Papa''s Youth', 'Dai counsels his forlorn son, telling him what true victory and setting self-rules are about. They become principles that Guy carves deep into his heart. With his father''s teachings spurring him on, Guy sets out on his final battle.', 23, '2015-07-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 420, 'The Eight Inner Gates Formation', 'Guy activates the Eight Inner Gates Formation and relentlessly attacks Six Paths Madara. Even Madara, who has attained power strong enough to create huge fissures in the ground, tries to dodge Guy''s direct attacks.', 23, '2015-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 421, 'The Sage of the Six Paths', 'Naruto wakes up and encounters the legendary shinobi, the Sage of Six Paths. He reveals to Naruto that he is the reincarnation of his son, Ashura, and that Sasuke is the reincarnation of Indra, Ashura''s older brother.', 23, '2015-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 422, 'The Ones Who Will Inherit', 'It’s been three years since Naruto set out to train with Jiraiya, and he''s just returned to the Hidden Leaf Village. Konohamaru immediately begs Naruto to teach him a new jutsu and he starts to go over the basics...but his explanations are very vague. Soon after, Naruto sets out on a mission, leaving Konohamaru to figure it out alone!', 23, '2015-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 423, 'Naruto''s Rival', 'It’s been three years since Naruto set out to train with Jiraiya, and he''s just returned to the Hidden Leaf Village. Konohamaru immediately begs Naruto to teach him a new jutsu and he starts to go over the basics...but his explanations are very vague. Soon after, Naruto sets out on a mission, leaving Konohamaru to figure it out alone!', 23, '2015-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 424, 'To Rise Up', 'Madara sustains serious damage from the Eight Inner Gates Formation, the move Guy risks his life for.', 23, '2015-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 425, 'The Infinite Dream', 'Madara now possesses the Rinnegan in both eyes, and he is the strongest, most despicable enemy the newly reunited Team 7 has ever faced. Kakashi calls upon Team 7 to recall their first lesson with the bells, and to use teamwork!', 23, '2015-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 426, 'The Infinite Tsukuyomi', 'Madara activates the Infinite Tsukuyomi, and anyone exposed to the light of the full moon--including shinobi and ordinary citizens--loses consciousness. Once ensnared, there is no escape from the Infinite Tsukuyomi. Will mankind be destined to live in a dreamworld forever?', 23, '2015-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 427, 'Road to Tenten ~The World of Dreams', 'Tenten falls under the Infinite Tsukuyomi and wakes up in the Hidden Leaf Village. When Lee and Guy Sensei appear, Tenten is relieved to see that she is not alone. But her joy is short-lived, as both men act oddly and are dressed stylishly—just where has she been transported to?', 23, '2015-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 428, 'Road to Tenten ~ Where Tenten Belongs', 'Tenten falls under the Infinite Tsukuyomi and wakes up in the Hidden Leaf Village. When Lee and Guy Sensei appear, Tenten is relieved to see that she is not alone. But her joy is short-lived, as both men act oddly and are dressed stylishly—just where has she been transported to?', 23, '2015-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 429, 'Killer Bee''s Rap Chronicles: Scroll of Heaven', 'Killer Bee gets caught in the Infinite Tsukuyomi and begins dreaming. In his dream, Jinchuriki are being stripped of their Tailed Beast powers by the Akatsuki. Bee is determined to rescue those who have been captured, and vows to resist the Akatsuki who are coming after him!', 23, '2015-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 430, 'Killer Bee''s Rap Chronicles: Scroll of Earth', 'The Akatsuki summoned the Ten Tails, but the Princess of Rappu Castle sealed it away safely. Unfortunately, the seal will come undone on the next full moon. Now Killer Bee is determined to gather the power of all nine Jinchuriki before the next full moon and protect the princess. But one by one, adversaries who want to stop Bee appear, beginning with Itachi and Deidara, then Orochimaru, Kabuto and Sasuke!', 23, '2015-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 431, 'To See That Smile, Just One More Time', 'Karin is caught within the Infinite Tsukuyomi and dreams of her past. She was born into the Uzumaki Clan and has the unique ability to heal anyone who bites into her. Driven out of her village, the Hidden Grass takes her in, only to use her for this ability. Karin has no choice but to endure constant suffering in order to survive. She is later chosen to enter the Chunin Exams, where Sasuke saves her life. Karin has never forgotten what he did for her—or his smile.', 23, '2015-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 432, 'The Loser Ninja', 'With the exception of Naruto’s Team 7, which is protected by the Susano’o, all other shinobi have been swept into a dream world by the Infinite Tsukuyomi. Even the Hokage, Tsunade, has fallen into a dream state. She awakens to find herself in the Leaf Village, where she discovers Jiraiya''s final book, entitled "Jiraiya Ninja Scrolls," and begins to read...', 23, '2015-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 433, 'The Search Mission', 'Tsunade continues to read Jiraiya’s novel. Chunin- and jonin-level ninja have gone missing, and the Fourth Hokage, Minato, orders a search mission with teams of genin led by Guy and Kurenai. Kakashi’s Team 7 is also dispatched, but the hero Naruto Uzumaki, despite being the Hokage’s son, has the misfortune of being labeled a loser.', 23, '2015-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 434, 'Team Jiraiya', 'Tsunade continues to read Jiraiya’s novel. Chunin- and jonin-level ninja have gone missing, and the Fourth Hokage, Minato, orders a search mission with teams of genin led by Guy and Kurenai. Kakashi’s Team 7 is also dispatched, but the hero Naruto Uzumaki, despite being the Hokage’s son, has the misfortune of being labeled a loser.', 23, '2015-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 435, 'Order of Priority', 'Team Jiraiya, Shikamaru, and his Leaf teammates are lured into a mysterious village during their battle. A couple children from the village get caught in the crossfire and fall into a cave-in. Yahiko’s team rushes to the rescue, but Shikamaru doesn’t budge. Meanwhile, Naruto and Neji’s teams rendezvous, but a mysterious voice addresses them out of nowhere!', 23, '2015-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 436, 'The Masked Man', 'The Masked Man shows Neji and Naruto images of past incidents that occurred in the Leaf Village. Meanwhile, Shikamaru and friends join up with Team Jiraiya to rescue the children. After fighting side by side with the Leaf, Yahiko and the others seem to have a change of heart.', 23, '2015-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 437, 'The Sealed Power', 'The Masked Man is satisfied that the Hidden Leaf Genin chose the importance of life over their mission, but orders his team to continue their surveillance. Meanwhile, Naruto is frustrated at his inabilities, and recalls why his father Minato sealed the Nine Tails inside of him.', 23, '2015-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 438, 'The Rules or a Comrade?', 'Sasuke and Sakura join up with the others, but the Puppet User appears and blocks their path back to the Hidden Leaf Village. Sasuke wants to bring down the puppets and rush back to report to the Fourth Hokage, but Shikamaru and the others insist on staying and rescuing the jonin.', 23, '2015-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 439, 'Child of the Prophecy', 'Jiraiya weakens the seal on the Nine Tails in order to help Naruto learn how to control the Tailed Beast''s power. Jiraiya recalls the words spoken to him years ago by the Great Lord Elder. He told Jiraiya that he would have a student, and that his guidance would decide whether the student would save the Ninja World or destroy it.', 23, '2015-11-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 440, 'The Caged Bird', 'Naruto joins up with the rest of his comrades, and together they overcome the puppet attack. The masked man witnesses this and is convinced there is a future for the young shinobi. He promises to release the kidnapped jonin and begins to explain the truth, and the situation behind his motives.', 23, '2015-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 441, 'Returning Home', 'Naruto’s strength is recognized by his fellow genin, except Sasuke. But while Naruto enjoys a close relationship with his father, Sasuke’s father, Fugaku, constantly compares Sasuke with his older brother Itachi and barely pays attention to him…', 23, '2015-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 442, 'The Mutual Path', 'Sasuke takes his frustrations out on Naruto and the two begin to fight, this time with their respective new jutsu. Minato steps in just before it turns into a disaster. From this encounter, Sasuke realizes that he is nowhere equal to Naruto in strength and joins the Leaf Police Force, determined to beat him one day.', 23, '2015-12-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 443, 'The Difference in Power', 'Three years have passed since Sasuke joined the Leaf Police Force, and he''s now lieutenant. But his abusive Police Force has only increased anxiety within the village, and the Uchiha remain in poor regard. Now that his training with Jiraiya has ended, Naruto returns to Hidden Leaf Village and has an explosive encounter with Sasuke in the middle of town!', 23, '2015-12-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 444, 'Leaving the Village', 'Sasuke leaves the village in order to obtain power from Orochimaru. Naruto and his friends learn that Sasuke is in danger and decide to go after him. To keep this a secret, only Naruto and Shikamaru set out on this mission, but on the way the duo are accosted by masked ANBU shinobi!', 23, '2016-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 445, 'The Pursuer', 'The Anbu who attack Naruto and Shikamaru are agents sent by Danzo, who had promised Orochimaru that he would deliver Sasuke safely to him. Luckily, Neji, Lee and Tenten rush to their aid in the nick of time! Meanwhile, Hiruko reveals the truth behind the incident involving Hizashi', 23, '2016-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 446, 'The Collision', 'Naruto reaches the tower Sasuke was heading for, thanks to Neji, Lee and Tenten deterring the agents from the Foundation. But it''s too late—Sasuke''s already made contact with Orochimaru! Naruto passionately tries to reason with Sasuke, but ultimately their powers collide!', 23, '2016-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 447, 'Another Moon', 'Sasuke has left with Orochimaru, but Naruto is not about to give up. Determined to bring Sasuke back, he returns to the village with Shikamaru and the others. Meanwhile, Yahiko appears in the village, calling himself “Pain" and seeking revenge for the Hidden Leaf’s betrayal.', 23, '2016-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 448, 'Comrade', 'Seeing Hinata almost die triggers Naruto’s anger and he goes into Nine Tails State. Naruto''s power is enormous, but Pain releases his jutsu to seal him away. Hatred consumes Naruto as he tries to break the seal. With Naruto unable to calmly control the Nine Tails’ power, the village steadily heads toward destruction.', 23, '2016-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 449, 'The Shinobi Unite', 'Several months after Pain’s attack, Jiraiya arrives with intel regarding the Akatsuki, who are attacking shinobi villages and kidnapping their Kage and jonin. He also reveals that Sasuke is working with them. Naruto is determined to bring his friend and comrade Sasuke back, once and for all!', 23, '2016-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 450, 'Rivals', 'Naruto wants to bring Sasuke back to the village, but Sasuke burns with a desire to bring Naruto down. Why is Sasuke so confrontational, and how did his feelings toward Naruto develop? The truth rises to the surface during Sasuke’s relentless attack. Where will this battle lead? Find out in the conclusion of the “Jiraiya Ninja Scrolls.”', 23, '2016-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 451, 'Itachi''s Story - Light and Darkness: Birth and Death', 'The shinobi under Madara’s Infinite Tsukuyomi continue to slumber and have pleasant dreams. Meanwhile, Naruto and the others have escaped the genjutsu, thanks to Sasuke’s protective Susano’o. As Sasuke starts remembering the death of Itachi, his Sharingan starts to resonate and show him the truth that Itachi never spoke a word of.', 23, '2016-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 452, 'Itachi''s Story - Light and Darkness: The Genius', 'Having experienced the Great Ninja War as a young child, Itachi constantly questions the meaning the life and death, distancing him from other children his age. Soon after entering the Academy, Itachi exhibits his genius and finds himself at the top of his class.', 23, '2016-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 453, 'Itachi''s Story - Light and Darkness: The Pain of Living', 'Upon graduating from the Academy, Itachi becomes a genin and joins a team that includes Tenma, Shinko, and their Jonin Leader, Minazuki Sensei. They accept a mission from Granny Cat to look for a missing feline who''s a skilled Ninja Cat!', 23, '2016-03-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 454, 'Itachi''s Story - Light and Darkness: Shisui''s Request', 'Itachi accompanies his friend Shisui on a three-part training exercise. The two come across a battle between the Hokage’s ANBU and the Foundation. Itachi is confused by their motives and can''t discern which side is right or wrong. But Shisui is unwavering in his determination to stop the fighting.', 23, '2016-03-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 455, 'Itachi''s Story - Light and Darkness: Moonlit Night', 'Itachi joins the ANBU and is quickly promoted to captain. But he must report directly to Danzo, and is placed as a double agent to observe the Uchiha clan, who are in the midst of planning a coup d’état. With dissatisfaction rising within the clan, the Uchiha ultimately decide to carry out their revolt, and the fateful night approaches.', 23, '2016-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 456, 'Itachi''s Story - Light and Darkness: The Darkness of the Akatsuki', 'Itachi becomes a rogue ninja and joins the Akatsuki. He is welcomed and introduced by Pain and Orochimaru as the ex-Leaf ANBU and the man who massacred his entire clan. Itachi is paired up with a man named Juzo, and their first job together is to fulfill an assassination request in the Land of Water.', 23, '2016-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 457, 'Itachi''s Story - Light and Darkness: Partner', 'Itachi is partnered with Kisame and begins his missions as a member of the Akatsuki. The duo succeeds in recruiting Deidara, so Pain assigns the newly formed team of Deidara and Sasori to hunt down the deserter Orochimaru. Meanwhile, intel comes in about an immortal killer, so Itachi, Konan and Kakuzu head out to the Land of Steam.', 23, '2016-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 458, 'Itachi''s Story - Light and Darkness: Truth', 'Itachi confronts Sasuke, who for years bore the shame and anger that Itachi brought upon their clan. The truth behind Itachi’s story comes to light. Back on the battlefield of the Fourth Great Ninja War, Naruto and the others fight Madara, and just as he is declaring his victory, something unexpected occurs...', 23, '2016-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 459, 'She Of The Beginning', 'Kaguya Otsutsuki suddenly emerges from Madara’s body. She is the mother of Hagoromo, the Sage of the Six Paths who entrusted his powers to Naruto and Sasuke. Kaguya’s power is immense and instantly sends Naruto and Sasuke to an alternate dimension. Naruto and Sasuke are the only ones who can seal away Kaguya, but they can’t find a jutsu that works against her!', 23, '2016-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 460, 'Kaguya Otsutsuki', 'Kaguya Otsutsuki suddenly descends from the heavens as the people of the Land of Sou look on in surprise and suspicion. But their king, Tenji, is enthralled by her and takes her for his concubine. In this age of endless war, Kaguya wishes for nothing but peace. But as the self-proclaimed protector of the Divine Tree, she soon finds herself engulfed by the tides of chaos and war.', 23, '2016-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 461, 'Hagoromo and Hamura', 'Near the Divine Tree is an area known as the Peak of Demise. No one is allowed to go near it, except those chosen by Kaguya to undergo a ritual she has established. Gamamaru, a Sage Toad, says the truth lies beyond the peak—those words stir Hagoromo’s curiosity, and he decides to head out to investigate.', 23, '2016-05-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 462, 'A Fabricated Past', 'Kaguya is furious that Hagoromo has broken the law. Hagoromo finds out what Kaguya did in the past and makes up his mind to fight her. Knowing nothing about her, Hagoromo cannot trust her—he wonders if the love and the despair she experienced are the sole cause of her anger. Unable to reach an understanding, mother and sons begin their long, sad battle.', 23, '2016-05-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 463, 'The No. 1 Most Unpredictable Ninja', 'Black Zetsu reveals that he masterminded and influenced all the events from the end of Ashura and Indra''s era to the current Fourth Great Ninja War. Naruto rejects Black Zetsu’s claim that the entire history of shinobi was solely for the resurrection of his mother, Kaguya. Naruto and Sasuke work together to seal away Kaguya, but they can''t find a way to counter her.', 23, '2016-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 464, 'Ninshu: The Ninja Creed', 'The Infinite Tsukuyomi does not affect Hashirama, Tobirama, Hiruzen and Minato because they are reanimated. Hagoromo, the Sage of the Six Paths, appears and explains to the four that Hashirama and Madara are the reincarnations of his sons Ashura and Indra. Hagoromo recounts the tale of how he founded Ninshu, the Ninja Creed, and about the lives of Ashura and Indra.', 23, '2016-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 465, 'Ashura and Indra', 'Hagoromo''s two sons, Ashura and Indra, share a happy childhood, training and playing together. Indra is naturally gifted with great talent, and at a tender age is nicknamed the “genius of Ninshu.” On the other hand, Ashura has no aptitude for Ninshu. Still, the two boys are very close. But Hagoromo is unaware of the malevolent power stirring in the shadows…', 23, '2016-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 466, 'The Tumultuous Journey', 'Hagoromo sends the brothers to two battle-scarred regions left untouched since the fight with Ten Tails. He then announces that he will choose his successor depending on the outcome of their missions.', 23, '2016-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 467, 'Ashura''s Decision', 'Ashura sets out on a journey, intending never to return. He ends up in a village where the people suffer from a mysterious illness.', 23, '2016-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 468, 'The Successor', 'Everyone believes that Indra is the best choice to be Hagomoro''s successor, and the sage''s indecision begins to cause anxiety among his followers. Finally, Ashura returns home, and Hagoromo reveals who he has chosen.', 23, '2016-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 469, 'A Special Mission', 'Finally, the truth will be revealed... Do not miss the unveiling of the legend.', 23, '2016-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 470, 'Connecting Thoughts', 'Before Naruto and Sasuke can attempt to seal Kaguya away, she transports Sasuke into a different Time-Space. Obito realizes that Kaguya’s ability to travel through Time-Space is similar to Kakashi’s and his own Visual Prowess. Obito and Sakura team up and begin the search for Sasuke.', 23, '2016-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 471, 'The Two of Them...Always', 'Fearing that he will once again break a promise, Obito uses the last of his power to bring Sasuke and Sakura back, but the thought of his inability to protect Rin nags at him as he loses consciousness.', 23, '2016-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 472, 'You Better...', 'Recalling the time when he shared Naruto’s desire to become Hokage, Obito opens up to Naruto about his dreams.', 23, '2016-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 473, 'The Sharingan Revived', 'Chakra—whose energy connects this world to those beyond—allows Obito to leave Rin''s side for a moment and appear in Kakashi’s inner psyche. Obito gives him his Magekyo Sharingan and leaves with a parting wish that Kakashi become the Sixth Hokage.', 23, '2016-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 474, 'Congratulations', 'Team 7 joins forces and succeeds in sealing away Kaguya, and the Tailed Beasts that Kaguya absorbed are also freed. Black Zetsu escapes the seal to lie in wait for another time to resurrect his mother, but Naruto is not about to let him go!', 23, '2016-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 475, 'The Final Valley', 'The battle with Kaguya is over, and all that is left is for Naruto and Sasuke to combine their powers and release the Infinite Tsukuyomi. But before they can do this, Sasuke makes a shocking declaration.', 23, '2016-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 476, 'The Final Battle', 'Naruto and Sasuke have both become such high-level shinobi that each knows exactly what the other is thinking just by exchanging attacks. Despite knowing how Naruto feels, Sasuke is determined to cut him down.', 23, '2016-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 477, 'Naruto and Sasuke', 'Naruto and Sasuke have both become such high-level shinobi that each knows exactly what the other is thinking just by exchanging attacks. Despite knowing how Naruto feels, Sasuke is determined to cut him down.', 23, '2016-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 478, 'The Unison Sign', 'Naruto and Sasuke are enveloped in a huge, intense light after exchanging attacks. When they come to, scenes from their childhood unfold. Is this just a figment of their imagination? Or could this be the afterlife?', 23, '2016-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 479, 'Naruto Uzumaki!!', '"I''ll be a better shinobi than Lord Hokage! Then all the villagers will have to acknowledge my existence at last!" True to his word, Naruto has walked his own path until there are none who do not recognize that he''s become a great shinobi and a hero who has saved the world. But what path will Naruto take now? How will the world of the shinobi change? This is the story of the boy who blew through the hearts of all like a "shippu," an irresistible gale. This is the story of Naruto Uzumaki.', 23, '2016-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 480, 'Naruto and Hinata', 'As a result of having the Nine Tails sealed inside of him, Naruto is feared and hated by the villagers. He trains all alone in the woods, but one day, a certain man appears and strikes up a conversation with Naruto. Elsewhere, in the Leaf Village, a celebration is held to mark Hinata''s third birthday, where she meets Neji for the first time.', 23, '2016-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 481, 'Sasuke and Sakura', 'As a child, Sasuke craved attention from his older brother Itachi. Sasuke and Itachi have a chance to spend some time alone when their parents are away. Meanwhile, Sakura is very shy and tends to spend her free time by herself. One day, her new friend Ino gives her a present.', 23, '2016-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 482, 'Gaara and Shikamaru', 'A young Gaara is hated by his father and isolated by his siblings, who play in the sandbox with Gaara until their father separates them. During dinner, Gaara asks his uncle about his mother and how to feel happy. His uncle replies that the moon makes him feel better when he is sad, and Gaara agrees that the moon makes him feel happy. A young Shikamaru is bored in class lectures and wants to sleep but is punished along with Naruto and Choji by Iruka for interrupting class. They bond as they stand in the hallway and later hang out after school. Shikamaru criticises Naruto for defending Hinata from bullies and the boys later laugh at Ino for getting rejected by Sasuke.', 23, '2016-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 483, 'Jiraiya and Kakashi', 'Ever since he was young, Jiraiya has been a little pervy. He tries to involve Orochimaru in many of his exploits as well as his schemes to get Tsunade’s attention. In Kakashi''s story, we see him living on his own since his father, Sakumo, died. Rin and Obito are fascinated by Kakashi, but his aloofness makes him hard to figure out.', 23, '2016-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 484, 'Sasuke''s Story, Sunrise, Part 1: The Exploding Human', '"The fourth Great Shinobi World War has ended. But Sasuke decides to continue his solitary journey—this time to atone for his sins. Meanwhile, back at the Leaf Village, there is a growing number of missing shinobi. As Kakashi—the sixth Hokage—and the others discuss these incidents, the Leaf is attacked by a mysterious group of shinobi."', 23, '2016-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 485, 'Sasuke''s Story, Sunrise, Part 2: Colosseum', 'Instead of returning to the Hidden Leaf, Sasuke sets out with Chino and Nowaki to investigate the cause of the exploding humans.', 23, '2016-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 486, 'Sasuke''s Story, Sunrise, Part 3: Fūshin', 'Orochimaru brings Sasuke to the Coliseum fighting ring, to lure out En Oyashiro, who may have some information regarding the Exploding Human incident. The match is called off when more Exploding Humans appear and the opportunity to meet Oyashiro seems lost. However, impressed by Sasuke’s Sharingan, Oyashiro approaches him in person.', 23, '2016-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 487, 'Sasuke''s Story, Sunrise, Part 4: The Ketsuryūgan', 'Sasuke uncovers Fuushin’s true identity at last, and begins to fight him. The moment Sasuke tries to read Fuushin’s memories with his Sharingan, a wave of genjutsu from a massive red eye causes Sasuke to lose consciousness. He awakens to find himself alone, and sees tracks in the snow that indicate Fuushin has barely escaped alive.', 23, '2016-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 488, 'Sasuke''s Story, Sunrise, Part 5: The Last One', 'Sasuke begins his own investigation into the incidents. He overcomes many dangers on his path to the truth. The Exploding Humans, the Ketsuryugan, the Chinoike Clan, and the Uchiha Clan—just how are they connected? Where does his journey lead? The mystery is about to be solved...', 23, '2017-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 489, 'Shikamaru''s Story, A Cloud Drifting in the Silent Dark, Part 1: The State of Affairs', 'It’s been two years since the end of the Fourth Great Ninja War. Shikamaru now has an important role within the Hidden Leaf government, and as a representative of the Leaf in the Alliance. One day, a situation develops with shinobi disappearing in droves, and Shikamaru takes on a dangerous mission.', 23, '2017-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 490, 'Shikamaru''s Story, A Cloud Drifting in the Silent Dark, Part 2: Dark Clouds', 'After the Great War, many missing and Rogue Ninja made their way into the Land of Silence. Sai, who has infiltrated the region to investigate, sends a cryptic message back to the Leaf. Shikamaru, determined to find out what''s happening, heads for the Land of Silence with two members of the ANBU, Soku and Ro. However, they must first get past a heavily guarded checkpoint.', 23, '2017-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 491, 'Shikamaru''s Story, A Cloud Drifting in the Silent Dark, Part 3: Recklessness', 'Shikamaru and his team are within range of Fushu Castle, where Gengo is purported to be. But they are unable to glean any intel about the man. Learning that Gengo will make a public appearance, Shikamaru and company infiltrate the square, where they see Sai being held captive.', 23, '2017-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 492, 'Shikamaru''s Story, A Cloud Drifting in the Silent Dark, Part 4: Cloud of Suspicion', 'Shikamaru is captured while trying to save Sai and stop Gengo. Far from giving up, he racks his brain to find a away out of the situation. Just as an opportunity presents itself, Ro and Soku appear under Gengo’s control!', 23, '2017-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 493, 'Shikamaru''s Story, A Cloud Drifting in the Silent Dark, Part 5: Dawn', 'Ino, Choji, and Temari rush to Shikamaru’s aid! Choji takes on Ro, Temari goes after Soku, and Ino goes after Sai! Meanwhile, Shikamaru pursues Gengo. Can Shikamaru defeat Gengo’s evil ambitions? The final battle begins!', 23, '2017-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 494, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 1: Naruto''s Wedding', 'Naruto and Hinata’s wedding day has been set. As the date approaches, Kakashi encounters a problem: Naruto’s friends are all top shinobi—the first line of defense in the village. They work 24/7, and there are always a few who cannot attend celebrations. As Kakashi tries to find the most reasonable solution, he announces a super-secret mission to find the couple a wedding gift.', 23, '2017-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 495, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 2: A Full-Powered Wedding Gift', 'Naruto and Hinata’s wedding day has been set. As the date approaches, Kakashi encounters a problem: Naruto’s friends are all top shinobi—the first line of defense in the village. They work 24/7, and there are always a few who cannot attend celebrations. As Kakashi tries to find the most reasonable solution, he announces a super-secret mission to find the couple a wedding gift.', 23, '2017-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 496, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 3: Hot Springs and Food Pills', 'The super-secret mission to find Naruto and Hinata a wedding gift proves to be difficult for Shikamaru. Choji has found the perfect gift, which adds to Shikamaru''s panic. But then Choji mentions something in passing and Shikamaru gets an idea. All he needs now is to enlist Temari''s help!', 23, '2017-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 497, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 4: The Kazekage''s Wedding Gift', 'The Tsuchikage and Raikage, who are in the Leaf Village to attend the Five Kage Summit, mention that they have already prepared wedding gifts for Naruto. Gaara finds himself in a dilemma. He''s advised that the gift should be something that befits the Kazekage. He also learns that the Raikage is planning to perform a dance. Kankuro chimes in and suggests Gaara should dance as well—further plunging Gaara into indecision.', 23, '2017-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 498, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 5: The Last Mission', 'Shino and Kiba still don''t have a wedding gift for Hinata''s wedding. Kiba''s made it his goal to become the next Hokage, but unlike his teammates, who are steadfastly chasing their dreams, Shino is unsure about his. With this uncertainty, he sets out with Kiba and Akamaru on their final mission as Team 8!', 23, '2017-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 499, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 6: The Outcome of the Secret Mission!', 'Naruto''s wedding day approaches, and one by one, each of his friends is getting a gift ready. But the true purpose for this mission has not been revealed to anyone: the gifts will be judged to select who can attend the reception! Seeing the care and thought that went into each of the gifts, Kakashi begins to wonder if that''s the right thing to do.', 23, '2017-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt0988824')) AND numero_temporada = 20), 500, 'Hidden Leaf Story, The Perfect Day for a Wedding, Part 7: The Message', 'Naruto had once lived a lonely existence, ostracized by everyone. But Iruka''s words and his very presence have supported Naruto to this day. As Naruto''s wedding nears, Iruka begins to lose sight of what he was to Naruto, and is unsure of what to say for his message.', 23, '2017-03-23');
