INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 1, 'Pilot', 'After a hurricane, John B, JJ, Pope and Kiara plunge headlong into danger and adventure when they find a mysterious sunken wreck.', 55, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 2, 'The Lucky Compass', 'Convinced that the clue found onboard the boat connects to his missing father, John B leads his friends on an increasingly frantic search for answers.', 48, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 3, 'The Forbidden Zone', 'As the gang hatches an illicit scheme to get to the bottom of the deep-sea mystery, John B confronts Sarah while Pope jumps at the chance for revenge.', 48, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 4, 'Spy Games', 'When John B''s supervision-free home life catches up to him, he receives a well-timed assist — and some spiffing up — from the last person he expects.', 50, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 5, 'Midsummers', 'John B believes he''s made a breakthrough in the hunt for the gold, but his desire to include Sarah in the quest causes friction among the friends.', 48, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 6, 'Parcel 9', 'A spooky island legend, a broken friendship and John B’s new living situation keep the crew on their toes as they search high and low for the treasure.', 54, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 7, 'Dead Calm', 'JJ''s reckless behavior ramps up when the friends try to score some quick cash. Meanwhile, John B grows closer to Sarah — and makes her dad suspicious.', 47, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 8, 'The Runway', 'John B finally learns the truth about his dad — and sets off a chain of events that jeopardizes everything he and his friends have fought to accomplish.', 47, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 9, 'The Bell Tower', 'With his options dwindling and enemies closing in, John B looks for an exit plan. Sarah feels pressured to pick a side. Pope lets his emotions out.', 52, '2020-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 1), 10, 'The Phantom', 'An island crawling with law enforcement and a looming tropical storm are just two of the obstacles facing John B as he tries to make his escape.', 58, '2020-04-15');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')), 2, 'Season 2', 'With a fortune in gold at stake and their futures on the line, the Pogues rush headlong into danger and a fresh mystery as they face foes old and new.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 1, 'The Gold', 'John B tries to evade capture as he zeroes in on the gold, but a promise to Sarah could derail his plans. Back home, his friends face life without him.', 51, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 2, 'The Heist', 'With time running out, John B and Sarah strike an uneasy bargain, while Kiara, JJ and Pope search for evidence that could implicate Ward and Rafe.', 54, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 3, 'Prayers', 'A desperate scramble for help lands John B and Sarah in questionable surroundings. Pope receives a mysterious summons to an out-of-town meeting.', 45, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 4, 'Homecoming', 'Low on gas and strapped for cash, John B and Sarah run into trouble. Pope''s appointment in Charleston takes an ominous turn over a proposed trade.', 49, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 5, 'The Darkest Hour', 'JJ cooks up a risky plan to help out John B. Pope hunts down information about the key. Kiara and Sarah both deal with family fallout over the Pogues.', 50, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 6, 'My Druthers', 'John B bristles when Sarah reconnects with a former flame. Ward''s web of lies starts to unravel. Pope discovers a shocking family secret.', 47, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 7, 'The Bonfire', 'Reeling from Ward''s actions, Sarah finds her loyalties to John B and the Pogues put to the test. At the annual bonfire, jealousies and tempers flare.', 43, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 8, 'The Cross', 'Armed with new clues, the group braves perilous roads and swampland as they race to keep part of Pope''s history from falling into the wrong hands.', 42, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 9, 'Trapped', 'The Pogues deal with a slew of setbacks — a medical emergency, a nosy neighbor, parental ultimatums — as they attempt to save Pope''s family legacy.', 50, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 2), 10, 'The Coastal Venture', 'John B, Pope, JJ and Kiara brace for a showdown on board the ship, while Sarah realizes the harsh truth of her distressing family situation.', 61, '2021-07-30');
