INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 1, 'Poguelandia', 'An unexpected rescuer takes the Pogues from a remote island to Barbados, where they encounter a powerful treasure hunter with his own agenda.', 53, '2023-02-23');
