INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 3, 'Fathers and Sons', 'Big John and John B pick up where they left off — for better or worse. Cleo and Pope form a new club. Rafe reconnects with Ward.', 48, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 4, 'The Diary', 'An emotional homecoming is easier for some than others. Big John searches for the diary. Ward''s plans for a prized possession don''t sit well with Rafe.', 45, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 5, 'Heists', 'Sarah convinces an old friend to help with a high-risk, high-reward mission. Looking to access a museum collection, John B and his dad get creative.', 54, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 6, 'The Dark Forest', 'Secrets threaten to drive a wedge between John B and his friends. Sarah revisits a past life. Pope reaches a breaking point.', 51, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 7, 'Happy Anniversary', 'With Singh on the move, John B and JJ scramble to catch him. Pope makes a breakthrough. Sarah questions where her loyalties lie.', 54, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 8, 'Tapping the Rudder', 'Rafe lays his cards on the table and Sarah calls in two favors. JJ''s unorthodox plan to get to South America lands John B in hot water.', 49, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 9, 'Welcome to Kitty Hawk', 'With their ride to Orinoco waiting on the tarmac, Kiara and JJ run into several complications. Rafe has a change of heart.', 55, '2023-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 3), 10, 'Secret of the Gnomon', 'The Pogues'' search for El Dorado brings them deep into the jungle, where John B and Sarah face the ultimate test of their courage and family bonds.', 79, '2023-02-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')), 4, 'Season 4', 'The Pogues return home and start living their best life, but it''s not long before they''re back to doing what they do best: hunting for treasure.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 1, 'The Enduro', 'Flush with success, the Pogues have big plans to invest in their future. But when their fortunes take a turn, will a bold gamble pay off?', 49, '2024-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 2, 'Blackbeard', 'A strange tale of a family curse makes the Pogues think twice about accepting a lucrative offer to search for an amulet linked to Blackbeard.', 47, '2024-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 3, 'The Lupine Corsairs', 'The sheriff grills the Pogues about their dealings with Wes Genrette. JJ and Kiara have another close call. Pope gets wind of a mysterious artifact.', 40, '2024-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 4, 'The Swell', 'Tensions rise along with the waves when the Pogues and the Kooks hit the beach for the year''s best swell. As Pope digs for info, Cleo faces down danger.', 43, '2024-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 5, 'Albatross', 'The Pogues scramble when the sheriff turns up at the worst possible time. JJ receives a mysterious letter. The amulet''s clues point to Charleston.', 63, '2024-10-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 6, 'The Town Council', 'JJ learns about his past. The Pogues rally support for a zoning meeting that will decide their fate. Sarah and John B suss out a theory about the scroll.', 52, '2024-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 7, 'Mothers and Fathers', 'As a confrontation on Goat Island turns perilous, Sarah confirms a suspicion while searching for JJ, Pope''s future falters, and Topper taunts John B.', 44, '2024-11-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10293938')) AND numero_temporada = 4), 8, 'Family Plot', 'While JJ heads out on a grim mission with Groff, Sarah reveals her big news, Pope faces a moment of truth, and Rafe helps the sheriff connect the dots.', 62, '2024-11-07');
