INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10466872')) AND numero_temporada = 1), 1, 'The Hidden Hand', 'On Wallach IX, young Valya Harkonnen promises Mother Superior Raquella that she''ll protect the Sisterhood by putting one of their own on the Imperial Throne. Thirty years later, Valya faces a threat to her long-awaited plan.', 66, '2024-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10466872')) AND numero_temporada = 1), 2, 'Two Wolves', 'After receiving word about events on Salusa Secundus, Valya brings Theodosia to the Imperial House to help manage the situation. Meanwhile, a reluctant Tula enlists Lila for a vital mission.', 63, '2024-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10466872')) AND numero_temporada = 1), 3, 'Sisterhood Above All', 'Following a tragedy, young Tula worries about being accepted despite her family name, while a skeptical Valya struggles with the decision to take the Sisterhood vow. Years later, Valya receives a message that confirms her suspicions.', 62, '2024-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10466872')) AND numero_temporada = 1), 4, 'Twice Born', 'As Tula attempts to understand the acolytes'' shared dream, Valya sets her plan in motion to redeem House Harkonnen ahead of the Landsraad.', 63, '2024-12-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10466872')) AND numero_temporada = 1), 5, 'In Blood, Truth', 'While Tula tries to keep her secret project from being discovered by the other Sisters, Desmond goes on a warpath to root out insurgents.', 58, '2024-12-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10466872')) AND numero_temporada = 1), 6, 'The High-Handed Enemy', 'As Tula contends with his true identity, Valya''s maneuvering leads her into an epic confrontation with an increasingly powerful Desmond.', 81, '2024-12-22');
