INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')), 1, 'Season 1', 'In season one, Dick Grayson and Rachel Roth, a special young girl possessed by a strange darkness, get embroiled in a conspiracy that could bring Hell on Earth. Joining them along the way are the hot-headed Starfire and loveable Beast Boy. Together they become a surrogate family and team of heroes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 1, 'Titans', 'Rachel Roth, a teen haunted by dark visions and powers, falls under the wing of Detective Dick Grayson. We also meet Kory Anders and Beast Boy Gar Logan.', 51, '2018-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 2, 'Hawk and Dove', 'In search of a safe haven for Rachel, Dick arrives on the doorstep of vigilante heroes Hawk and Dove.', 44, '2018-10-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 3, 'Origins', 'Rachel and Kory travel to the convent where Rachel was raised, while Dick compares his own orphan experience to Rachel’s. Meanwhile, Rachel befriends Gar Logan.', 55, '2018-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 4, 'Doom Patrol', 'Gar brings Rachel home to his “family” – a group of misfit medical experiments we’ll come to know as The Doom Patrol (including Robotman, Negative Man and Elastigirl).', 45, '2018-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 5, 'Together', 'When the Nuclear Family tracks them down, Dick, Kory, Rachel and Gar decide to stop running and work together – and the team that will be known as “The Titans” is formed.', 41, '2018-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 6, 'Jason Todd', 'Before he can reunite with The Titans, Dick reluctantly teams with Jason Todd, the new Robin, to catch a serial killer targeting people from Dick’s past.', 47, '2018-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 7, 'Asylum', 'The Titans set out to rescue Rachel’s birth mother from a mysterious psychiatric facility, but find themselves confronting their deepest vulnerabilities and fears.', 47, '2018-11-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 8, 'Donna Troy', 'As The Titans go their separate ways, Dick turns to an old friend, Donna Troy, for answers.', 43, '2018-11-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 9, 'Hank and Dawn', 'The origin story of Hank Hall and Dawn Granger’s relationship and the loss in each of their pasts that brings them together as vigilante Super Heroes Hawk and Dove.', 47, '2018-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 10, 'Koriand''r', 'As Kory’s memories come flooding back, she discovers her true mission, regarding Rachel. While Dick and Donna discover Kory’s alien origins, Rachel uses her powers to save Gar.', 41, '2018-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 1), 11, 'Dick Grayson', 'Dick takes a dark journey back to Gotham in the finale.', 44, '2018-12-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')), 2, 'Season 2', 'In season two, following the aftermath of their encounter with Trigon, Dick Grayson reforms the Titans. Under his supervision in their new home at Titans Tower, Rachel, Gar and Jason Todd train together to hone their hero abilities and work together as a team. They are joined by Hank Hall and Dawn Granger aka Hawk and Dove and Donna Troy aka Wonder Girl. Although these original Titans attempt to transition into a regular life, when old enemies resurface everyone must come together to take care of unfinished business.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 1, 'Trigon', 'The season premiere continues the apocalyptic events of last season as Trigon sets out to win the Titans over to his side by embracing their inner darkness.', 52, '2019-09-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 2, 'Rose', 'While Dick trains the next generation of Titans, Donna and Kory track down a rogue metahuman. But an old threat drives the Titans – old and new – back together.', 41, '2019-09-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 3, 'Ghosts', 'The old Titans reluctantly return to Titans Tower to strategize against an old enemy. But the secrets of the Titans’ past threaten to tear apart this newly formed team from within.', 47, '2019-09-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 4, 'Aqualad', 'Four years ago, Dick, Donna, Hank & Dawn formed the Titans with Garth aka Aqualad. But the team is tested with the arrival of a new villain.', 44, '2019-09-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 5, 'Deathstroke', 'With the team in upheaval, the Titans do everything in their power to save Jason’s life. But when Deathstroke demands they turn over Rose, the dilemma threatens to tear the team apart.', 43, '2019-10-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 6, 'Conner', 'Conner Kent and Krypto escape from Cadmus Labs. His search for the truth about his past leads him to Lionel Luthor and genetic scientist Dr. Eve Watson.', 43, '2019-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 7, 'Bruce Wayne', 'With tensions running high at Titans Tower, Kory tries to learn more about Conner, while Dick sets out alone to track down Deathstroke – with a familiar voice haunting him.', 43, '2019-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 8, 'Jericho', 'Dick befriends Jericho Wilson to learn more about Deathstroke.', 49, '2019-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 9, 'Atonement', 'In the aftermath of his confession, Dick’s fear that his secret would break up the Titans comes true. Abandoning Titans Tower, the heroes all go their separate ways.', 46, '2019-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 10, 'Fallen', 'Titans Tower comes under attack by Mercy Graves.', 44, '2019-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 11, 'E.L._.O.', 'With Dick still in prison and Gar under the microscope at Cadmus, the remaining Titans are called together to save their teammates.', 48, '2019-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 12, 'Faux Hawk', 'Hank finds himself at a new low, cage-fighting for money, when he finds an imposter now acting as Hawk.', 49, '2019-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 2), 13, 'Nightwing', 'The Titans battle Deathstroke & more in the season finale.', 50, '2019-11-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')), 3, 'Season 3', 'In season three, circumstances draw our heroes to Gotham City, where they will reunite with old friends and face new threats.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 1, 'Barbara Gordon', 'Desperate to leave his mark, Jason Todd confronts the Joker once and for all. But when fatal consequences ensue, Dick Grayson is forced to step away from the Titans and return to Gotham City.', 45, '2021-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 2, 'Red Hood', 'With the Joker out of the picture, the mysterious Red Hood takes charge. But after bringing the Titans back to Gotham City, Dick is confronted by the city’s newest villain - and his shocking real identity.', 46, '2021-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 3, 'Hank & Dove', 'After unearthing an empty grave, the Titans confirm that an old friend is alive - and behind the city’s latest emerging threat. Then, when a Titan falls for Red Hood’s trap, the team races against the clock to save one of their own.', 42, '2021-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 4, 'Blackfire', 'Devastated by loss, the Titans find themselves in disarray. While Dick throws himself into drawing out Red Hood with Jonathan Crane, Kory and Gar work to understand Starfire''s escalating visions, leading them to a surprising source.', 44, '2021-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 5, 'Lazarus', 'In the aftermath of his fight with Nightwing, anti-heroes Red Hood and Jonathan Crane reteam for the first phase of their fearsome plan. Then, through a series of flashbacks, Red Hood’s origins are revealed.', 47, '2021-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 6, 'Lady Vic', 'Dick and Barbara work to unmask the latest killer unleashed by Crane. When Kory and Gar bring her to the Tower, Blackfire forms an unexpected connection with a Titan.', 49, '2021-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 7, '51%', 'Gotham’s crime families meet to discuss the fear toxin’s hold on the city – only to be confronted by the mastermind himself. As Dick and Barbara consult the Oracle to preempt Crane’s next move, Starfire and Blackfire reach an understanding.', 42, '2021-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 8, 'Home', 'As an emboldened Crane looks to filter his poison through Gotham’s water system, Starfire - still plagued by visions - enlists Blackfire and Superboy’s help, and Gar finally tracks down Jason.', 49, '2021-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 9, 'Souls', 'After waking up on a mysterious train, Tim Drake teams with two familiar heroes to locate an elusive bridge back to the land of the living. Meanwhile, Rachel grapples with her own powers in a desperate attempt to resurrect Donna.', 46, '2021-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 10, 'Troubled Water', 'Things go from bad to worse as the Titans are falsely blamed for poisoning the city, forcing them into a perilous position as they work to regain Gotham’s trust.', 45, '2021-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 11, 'The Call Is Coming from Inside the House', 'While Crane sets his ultimate sights on Nightwing, Gar and Rachel investigate Red Hood’s place of rebirth, Donna and Tim reconnect in the real world, and Kory learns the truth about her past.', 50, '2021-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 12, 'Prodigal', 'After Nightwing and Red Hood’s battle, Rachel and Gar try to save their friend. Meanwhile, Jason questions his allegiance. With Barbara behind bars, Donna leads her own resistance operation, and Conner helps Blackfire recover her ship.', 51, '2021-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 3), 13, 'Purple Rain', 'With Gotham once again at the mercy of Crane’s terror, it’s all hands on deck for the Titans as they infiltrate Wayne Manor and harness an ancient power that transcends life and death.', 53, '2021-10-21');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')), 4, 'Season 4', 'Having saved Gotham, the Titans hit the road to head back to San Francisco. But after a stop in Metropolis, they find themselves in the crosshairs of a supernatural cult with powers unlike anything they’ve faced before.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 1, 'Lex Luthor', 'After Superman requests a meeting with Conner, the Titans travel to Metropolis for exclusive access to S.T.A.R. Labs. But when unexpected complications arise, including the re-emergence of Lex Luthor, Conner faces a tough decision.', 53, '2022-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 2, 'Mother Mayhem', 'In the wake of Lex Luthor''s sudden demise, Conner finds himself framed for murder while the Titans try to piece together Luthor''s suspicious connection to Rachel''s haunting and clear their teammate''s name.', 50, '2022-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 3, 'Jinx', 'With Rachel left powerless, Dick turns to an old friend whose magic could be the key to identifying their mysterious enemy. Meanwhile, Conner and Tim investigate attack victims, and Sebastian finds himself at the center of an eerie plot.', 43, '2022-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 4, 'Super Super Mart', 'As she grows closer to Sebastian, Rachel makes an unsettling discovery that leads the Titans to The Organization’s Asylum – where they come face-to-face with their deadliest foes yet.', 43, '2022-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 5, 'Inside Man', 'As the Blood Moon rises, the Titans fight to keep Sebastian from Mother Mayhem’s clutches, and an injured Conner gives rise to a venomous threat that jeopardizes the team’s plan.', 45, '2022-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 6, 'Brother Blood', 'The Titans race against time to save Sebastian before the Blood Moon ritual, while Conner’s new hardened personality rears, and Gar is presented with an ominous choice.', 51, '2022-12-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 7, 'Caul''s Folly (1)', 'In the wake of Sebastian''s transformation, the Titans race to retrieve Traigon''s horn, leading them to the quaint – but eerie – town of Caul''s Folly.', 46, '2023-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 8, 'Dick & Carol & Ted & Kory (2)', 'With Dick and Kory at risk of falling victim to the spell of Caul''s Folly, Bernard and Tim attempt to crack the town''s mystery before it''s too late.', 52, '2023-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 9, 'Dude, Where''s My Gar', 'After being separated from the Titans, Gar uncovers long-lost secrets from his past as he confronts his mysterious connection to the Red.', 47, '2023-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 10, 'Game Over', 'With help from Conner at Lexcorp, Sebastian manifests his powers in a sinister new way, as Dick and Rachel have a close encounter with black magic.', 54, '2023-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 11, 'Project Starfire', 'An unexpected reunion sheds light on Project Starfire, forcing Kory to make a difficult decision that puts her powers to the ultimate test.', 57, '2023-05-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1043813')) AND numero_temporada = 4), 12, 'Titans Forever', 'With Brother Blood at full power and Conner left in critical condition, the Titans join forces to find and defeat Sebastian once and for all.', 54, '2023-05-11');
