INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')), 1, 'Season 1', 'Thousands of years after the fall of Humankind, the Four Lands is threatened by an evil Demon army. The fate of the world rests on the shoulders of an unlikely trio: Amberle, an Elvin Princess who dreams of a life outside of the palace walls; Eretria, a beautiful, wild and wily Human Rover; and Wil, a Half-Elf, Half-Human who knows nothing of the great destiny that runs through his veins.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 1, 'Chosen (1)', 'Thousands of years after the fall of Humankind, the Four Lands is in grave danger. The fate of the world rests on the shoulders of an unlikely trio: an Elvin Princess who dreams of a life outside of the palace walls, a beautiful, wild and wily Human Rover and a half-elf, who knows nothing of the great destiny that runs through his veins.', 41, '2016-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 2, 'Chosen (2)', 'Having seen an apocalyptic vision of the world’s destruction, Amberle leaves the palace in search of answers. But when Wil and Allanon realize that she is the key to saving the Four Lands, they set out to find the princess before the Dagda Mor’s Demons hunt her down.', 42, '2016-01-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 3, 'Fury', 'Wil and Amberle are kidnapped by Eretria and Cephalo while returning to the palace. But the Rovers are the least of their worries –Wil must learn how to use the Elfstones before a bloodthirsty Fury kills them all.', 42, '2016-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 4, 'Changeling', 'While Amberle embarks on a deadly task to prove her worth to the Ellcrys, the Dagda Mor sends the Changeling, an ancient, shape-shifting Demon, to kill her and anyone in its way. But when a demon can take shape of anyone in the palace, finding it won’t be easy.', 41, '2016-01-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 5, 'Reaper', 'Amberle, Wil and Eretria are forced to overcome their differences to survive the perils of their quest, including the nightmarish Reaper. At the palace, Ander attempts to recruit help from an unlikely ally to find the Dagda Mor - his brother’s murderer, Slanter, a Gnome assassin.', 41, '2016-01-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 6, 'Pykon', 'On the run from the relentless Reaper, Amberle, Wil and Eretria take shelter in Pykon, a snowy Elvin outpost that houses a grisly secret. Meanwhile, Ander and Slanter make a devastating discovery about the Dagda Mor’s forces.', 42, '2016-02-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 7, 'Breakline', 'Amberle and Eretria run from bloodthirsty Elf Hunters who relish in cutting off elves’ ears for fun, while Wil searches for them with the help of an unexpected friend. At the palace, the King sends Ander and Arion to assassinate the Dagda Mor - with devastating consequences.', 42, '2016-02-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 8, 'Utopia', 'Wil and Amberle desperately search for Eretria to save her from the vicious elf hunters who kidnapped her. Little do they know, she’s stumbled upon a secret settlement of Humans and may finally feel like she belongs. But their utopia is much more than meets the eyes. Meanwhile, Allanon must inspire Ander to accept his destiny.', 41, '2016-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 9, 'Safehold', 'With time running out, Wil, Amberle and Eretria must cross ancient Human ruins to reach the Bloodfire. But a nefarious evil stands in their way, testing their friendship and manipulating them against each other. At the palace, Allanon and Ander stave off a coup while facing the imminent attack from the Dagda Mor and his army.', 41, '2016-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 1), 10, 'Ellcrys', 'Wil and Amberle race to reach the Ellcrys while Allanon and Ander lead the Elvin army in an epic battle against the Dagda Mor and his Demon horde. But the cost of their quest could prove too great, altering everyone’s destinies forever.', 42, '2016-03-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')), 2, 'Season 2', 'One year later, the Four Lands are in chaos. The re-emergence of magic has the populace terrified, and an organization called The Crimson is hunting down magic users, using fear and intimidation to sow discord among the races. Wil, scarred by the loss of Amberle and his separation from Eretria, has turned his back on his magical destiny to become a healer. But when a mysterious woman named Mareth saves Wil from a Crimson attack, he is forced to rejoin the fight.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 1, 'Druid', 'A year after the War of the Forbidding, Wil’s new life is interrupted by a mysterious new figure. Eretria is reunited with someone from her past. Meanwhile, Allanon uncovers a plot that could send the Four Lands into darkness.', 43, '2017-10-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 2, 'Wraith', 'Wil and Mareth search for answers. While visiting a nearby kingdom, King Ander seeks reinforcement and is given an ultimatum.', 43, '2017-10-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 3, 'Graymark', 'With Wil trapped, Eretria and Mareth must work together to free him before time runs out.', 43, '2017-10-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 4, 'Dweller', 'Wil, Mareth and Allanon travel to a dangerous territory for an answer. King Ander meets the Princess of Leah, but finds she''s more than he bargained for.', 43, '2017-11-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 5, 'Paranor', 'Wil and Mareth move forward with a plan to confront Bandon, but will complications and suspicions drive apart the unlikely fellowship of heroes?', 43, '2017-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 6, 'Crimson', 'Wil and Mareth race against time to recover an item in uncharted territory.', 42, '2017-11-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 7, 'Warlock', 'Bandon and his followers race to resurrect the Warlock Lord. Mareth risks everything in the hope that she''s not too late.', 42, '2017-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 8, 'Amberle', 'Wil confronts his past and the bond between Allanon and Mareth continues to grow.', 43, '2017-11-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 9, 'Wilderun', 'Eretria confesses a dark secret to Wil. Bandon''s deepest wish is granted, but with a catch.', 42, '2017-11-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1051220')) AND numero_temporada = 2), 10, 'Blood', 'In the final showdown, Wil must save the Four Lands. Wil, Mareth and Eretria grapple with the loss of one of their own.', 42, '2017-11-22');
