INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')), 1, 'Season 1', 'An intense, arduous and frequently hilarious year in the life of Britain’s most unlikely farmer, Jeremy Clarkson. Join Jeremy and his rag-tag band of agricultural associates as they face-up to a backdrop of unhelpful weather, disobedient animals, unresponsive crops and an unexpected pandemic. This is Jeremy Clarkson as you’ve never seen him before.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 1, 'Tractoring', 'Jeremy Clarkson embarks on his path towards muddy misery and potential ruin by running his own farm.', 54, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 2, 'Sheeping', 'Jeremy decides to get a flock of sheep, not realising the added complications these high-maintenance animals will bring.', 51, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 3, 'Shopping', 'Jeremy Clarkson decides to open a farm shop to sell his own produce. This sounds like it should be easy. It isn''t.', 52, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 4, 'Wilding', 'Jeremy Clarkson decides to become a naturalist.', 49, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 5, 'Pan (dem) icking', 'As Covid-19 puts Britain on lockdown, Jeremy suddenly finds that his biggest worries aren''t all related to the upcoming lambing season.', 47, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 6, 'Melting', 'Jeremy discovers why British farmers are always complaining about the weather. It''s mostly because it never does what they want it to do.', 42, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 7, 'Fluffing', 'As the drought drags on and the harvest time gets closer, Jeremy and his motley crew have a fearsome list of jobs to complete.', 41, '2021-06-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 1), 8, 'Harvesting', 'After months of hard work Clarkson''s farm arrives at a make or break moment; harvest time.', 54, '2021-06-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')), 2, 'Season 2', 'Another year in the life of Diddly Squat Farm, run by Jeremy Clarkson, Britain''s best-known but least-qualified amateur farmer. In an effort to increase his annual profit (£144 last year) he''s diversifying, in the shape of cows, more chickens and his own restaurant.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 1, 'Surviving', 'Jeremy Clarkson sets out to diversify, as a way of increasing his annual profit (£144 last year).', 42, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 2, 'Cowering', 'Jeremy''s new herd of cows settle in, but soon reject the fence that keeps them in.', 46, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 3, 'Schmoozing', 'Faced with Council powers that be, Jeremy uses two of his greatest skills: diplomacy and respect for red tape.', 40, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 4, 'Badgering', 'Jeremy Clarkson comes face to face with his nemesis: the badger.', 45, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 5, 'Council-ing', 'The day of the Council''s decision on Jeremy''s restaurant arrives.', 48, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 6, 'Counselling', 'The fall-out from the Council''s decision continues to fall out.', 40, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 7, 'Scheming', 'Jeremy''s restaurant idea is re-born, and there''s not a moment to waste.', 44, '2023-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 2), 8, 'Climaxing', 'Secret preparations accelerate for the opening of Jeremy''s restaurant.', 52, '2023-02-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')), 3, 'Season 3', 'After the triumphant finale of Season 2, we return to Diddly Squat to find everything in turmoil. The council has shut the restaurant and the weather is ruining the crops. Desperate for new income streams Jeremy enters a world of pig breeding, goat attacks and mushroom mountains. Meanwhile Kaleb, promoted to farm manager, deals with an unwelcome rival. The funniest, most heartbreaking season yet.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 1, 'Unfarming', 'We return to Diddly Squat to find the farm in turmoil. The Council has shut down the restaurant, the weather is making planting crops impossible and costs are on the up. Jeremy needs to formulate a new plan to get his farm through the year.', 44, '2024-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 2, 'Porking', 'Jeremy sets to work getting the farm ready for its newest residents, some Sand and Black pigs. Meanwhile Kaleb is annoyed when he spots someone else drilling in his fields.', 46, '2024-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 3, 'Jobbing', 'It''s Christmas time on the farm and Kaleb gives Jeremy a festive surprise. However their relationship becomes strained as they bicker while getting on with the farms winter jobs.', 48, '2024-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 4, 'Harrowing', 'Jeremy treats Kaleb to something he hopes will help with his farming, and Lisa and Jeremy discover just how tough being pig farmers can be.', 49, '2024-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 5, 'Healing', 'Spring has sprung and rejuvinated Jeremy''s farming the unfarmed idea, as he takes on multiple new projects to try and turn a profit from his unused land.. And there are some one week old arrivals to the farm to lift everyone''s spirits.', 52, '2024-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 6, 'Mushrooming', 'Jeremy''s mushroom empire begins to appear all consuming as he struggles to keep on top of his newest venture and Kaleb and Charlie are off to London for a very important meeting.', 50, '2024-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 7, 'Parking', 'Team Diddly assemble for a much needed building project and Jeremy brings in the Chairman of the British Deer Society to help with the deer management issues on the farm.', 52, '2024-05-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 3), 8, 'Calculating', 'Harvest time arrives and is tenser than ever, as Jeremy and Kaleb find out how profitable both Jeremy''s new projects and Kaleb''s arable farming have been this year.', 60, '2024-05-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')), 4, 'Season 4', 'Jeremy is taking on his most ambitious project yet, setting out to buy a pub that will reignite his Farm to Fork restaurant vision. But the road to becoming a landlord isn’t exactly straightforward, and with new faces, new livestock and new machinery arriving at the farm, life at Diddly Squat is busier than ever.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 1, 'Solo-ing', 'Kaleb and Lisa are both away and Jeremy has been left to run the farm on his own. Help is soon needed, and the arrival of a new farmhand to ease the burden gives Jeremy space for some strategic thinking.', 39, '2025-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 2, 'Pubbing', 'Jeremy has found a promising pub, Diddly Squat’s newest arrival teaches him a thing or two about farming, and the ageing Lamborghini has competition.', 51, '2025-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 3, 'Crawling', 'Relentless wet weather puts the crop planting in crisis, Kaleb returns to find another farmer on his patch, and while his pub search continues, in an effort to dry the soil Jeremy gets to grips with a new piece of kit.', 49, '2025-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 4, 'Cottaging', 'There’s a big new arrival at the farm, a much smaller one down in the pig pens, and it looks as though the pub search might finally be over.', 44, '2025-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 5, 'Endgaming', 'It’s the middle of May, the livestock are heading out to graze, and while the goats are going high-tech, the cows are getting a bull-friend. If only progress with the pub was as positive.', 44, '2025-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 6, 'Splurging', 'With his pub plan finally taking shape, Jeremy heads to his first cattle market to buy up some beef. But calling in the experts to help get the pub off the ground, Jeremy soon discovers the costs are only just beginning.', 49, '2025-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 7, 'Hurrying', 'A diary cock-up turns the pub into a pressure cooker, and the start of the harvest runs Jeremy ragged. Team Diddly Squat will have to dig deep to get both across the line.', 52, '2025-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')) AND numero_temporada = 4), 8, 'Landlording', 'It’s bank holiday weekend and the pub opens for business. Whether it stays open for business is another matter. Back at Diddly Squat, the harvest results come in and the curtain falls on another farming year.', 49, '2025-06-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10541088')), 5, 'Season 5', 'Amidst a government budget that sends the UK farming community into uproar, Jeremy decides some big changes are needed to make the farm run more smoothly. But while the farm tries to go high-tech – resulting in Kaleb''s first ever trip abroad – even bigger developments are heading for Diddly Squat that are going to prove much more of a challenge.');
