INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 1, 'Meet', 'Stuck in a secret relationship, shy Charlie starts to crush on Nick, the school''s popular rugby star, and joins the team against his friends'' advice.', 27, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 2, 'Crush', 'Elle struggles to settle into her new school as Charlie and Tao are convinced Nick is straight. Nick starts to question his unfamiliar feelings.', 33, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 3, 'Kiss', 'Sparks fly at a birthday party where Nick''s friend Tara confides in him. Inspired, Nick shares his feelings with Charlie — and they grow even closer.', 30, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 4, 'Secret', 'Charlie and Nick agree to keep their relationship a secret at school while Nick figures things out. Nick''s friend Imogen asks him out on a date.', 29, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 5, 'Friend', 'Nick decides whether he should skip his date with Imogen for Charlie''s birthday. Tao vows to protect Charlie from Nick and his rude rugby friends.', 27, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 6, 'Girls', 'Tara makes her relationship official on social media, but she isn''t ready for the side effects. The friends try to play matchmaker with Elle and Tao.', 29, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 7, 'Bully', 'After both Nick and Tao get into fights with Harry, Charlie worries that he''s making Nick''s life too difficult and straining his friendship with Tao.', 26, '2022-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 1), 8, 'Boyfriend', 'As the boys and girls schools meet for a Sports Day, Charlie''s on the brink of breaking it all off with Nick while Elle and Tao share a special moment.', 33, '2022-04-22');
