INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 2, 'Family', 'With Charlie''s grades slipping, his parents tighten the rules. Tao''s jealous when Elle makes new friends. Nick''s older brother invades his privacy.', 35, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 3, 'Promise', 'Nick tries to come out to some of his teammates at a bonfire party after exams. Tao plans the perfect date. Things get weird between Tara and Darcy.', 32, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 4, 'Challenge', 'On a school trip to Paris, Nick and Charlie try to keep their relationship under wraps. Elle and Tao reconnect at a museum. Imogen stands up to Ben.', 37, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 5, 'Heat', 'Rumors spread when Charlie wakes up with something on his neck. A group tour of the city''s most famous sights reveals more than one major secret.', 35, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 6, 'Truth / Dare', 'On their last day in Paris, Nick introduces Charlie to his dad. Elle and Tao make it official. The truth comes out at a party that''s full of surprises.', 36, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 7, 'Sorry', 'Elle keeps big news from Tao, Ben pressures Charlie to forgive him, and Isaac opens up to James. Nick invites Charlie to a tense family dinner.', 34, '2023-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 2), 8, 'Perfect', 'The gang comes together for a memorable prom with a fitting theme: "Summer of Love." But with someone important missing... it feels incomplete.', 41, '2023-08-03');
