INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 2, 'Home', 'On holiday in Menorca, Nick worries about Charlie, who is struggling more than ever. Isaac starts to feel like a third wheel around Elle and Tao.', 39, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 3, 'Talk', 'It''s a new term, and Tao misses Elle now they''re at different schools. Charlie plans a birthday surprise for Nick, who''s still worried for his boyfriend.', 37, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 4, 'Journey', 'Charlie seeks medical help and begins the long road to recovery. Nick starts keeping a journal, and Tao makes a video to support his absent friend.', 34, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 5, 'Winter', 'It''s a tough Christmas for Charlie, and his family — except for Tori — isn''t helping. Elle and Tao talk about sex, and sparks fly at a New Year''s party.', 34, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 6, 'Body', 'Elle''s art going viral on social media lands her an interview. Charlie tells Nick he''s ready to go to the next level and Tara suffers a panic attack.', 36, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 7, 'Together', 'As the school year comes to an end and the students begin thinking about their futures, Charlie and Nick struggle to find a moment alone together.', 35, '2024-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10638036')) AND numero_temporada = 3), 8, 'Apart', 'Nick and the girls go on a road trip to look at unis, as he tries to decide whether to stay near Charlie or move away. Sahar''s band plays at a fete.', 36, '2024-10-03');
