INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')), 1, 'Season 1', 'An aimless gamer and his two friends find themselves in a parallel Tokyo, where they''re forced to compete in a series of sadistic games to survive.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 1, 'Episode 1', 'Arisu and his friends run into a public bathroom to hide from the police — but when they reemerge, the streets of Tokyo are suddenly completely empty.', 49, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 2, 'Episode 2', 'Leaving an injured Chota, Arisu and Karube head out to gain more experience. They come to a sprawling apartment, where a deadly game of tag awaits.', 51, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 3, 'Episode 3', 'With Chota''s and Shibuki''s visas fast expiring, the four enter a vast botanical garden in Shinjuku, where they take part in a cruel game of betrayal.', 43, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 4, 'Episode 4', 'Arisu is overwhelmed with guilt and ready to give up, but Usagi urges him to keep going. Next up is a game of endurance in an underground highway.', 48, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 5, 'Episode 5', 'After Arisu and Usagi find their way to the Beach, the king of the so-called utopian haven forces them to help gather the remaining playing cards.', 52, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 6, 'Episode 6', 'Chishiya recruits Arisu and Usagi to help him change the status quo. An unforeseen event rocks the fragile power dynamics of the Beach.', 42, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 7, 'Episode 7', 'Once a safe haven, the Beach becomes the arena for the next stage, where an epic witch hunt turns everyone against each other in a hostile showdown.', 49, '2020-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 1), 8, 'Episode 8', 'Tensions inside the resort reach a boiling point. As the game clock nears zero, those who''ve survived the onslaught now face an uncertain future.', 53, '2020-12-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')), 2, 'Season 2', 'The games are deadlier, this world more wild and cruel; but will Arisu ever make it back to the real world — and will it be worth everything he''s lost?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 1, 'Episode 1', 'Arisu, Usagi, Kuina and Chishiya have been waiting for over an hour in Shibuya crossing for the next stage to start, but nothing seems to be happening.', 49, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 2, 'Episode 2', 'Now that the King of Clubs has revealed himself in his full glory, the game finally begins. Much to Arisu''s surprise, things are going pretty well.', 61, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 3, 'Episode 3', 'With only a few minutes left in the game, the results for each team seems fixed. Arisu approaches Kyuma, and asks to shake his hand.', 67, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 4, 'Episode 4', 'There are just a handful of players left, and Chishiya''s the only one without a partner. The next round may very well be the last of the game.', 53, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 5, 'Episode 5', 'Aguni has one thing on his mind: to find and kill the King of Spades. He''s joined by Arisu and a determined high schooler named Akane Heiya.', 68, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 6, 'Episode 6', 'Usagi will have to change the hearts and minds of the cynical players on the Queen''s team. At the Supreme Court, Chishiya meets the King of Diamonds.', 76, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 7, 'Episode 7', 'In the middle of an overgrown Shibuya crossing, Niragi challenges Arisu and Chishiya to a game. But then the King of Spades arrives.', 60, '2022-12-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 2), 8, 'Episode 8', 'For their final game, they''ll need to survive three rounds of croquet — but before they can get very far, the Queen asks them to sit down for some tea.', 81, '2022-12-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')), 3, 'Season 3', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 3), 1, 'Episode 1', 'Back in the real world with no memories of Borderland, Arisu and Usagi encounter Ryuji, a professor with a fixation on near-death experiences.', 62, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 3), 2, 'Episode 2', 'The first game begins at a shrine. Arisu and the other players must solve math problems on the fly before everything goes up in flames.', 56, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 3), 3, 'Episode 3', 'As Rei''s plan unravels, Arisu takes a risky move to keep his team alive. On a separate stage, Usagi and Ryuji face a relentless barrage of lasers.', 63, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 3), 4, 'Episode 4', 'With time running out and a crash imminent, Usagi''s group must jump trains to survive. An explosive game of Kick the Can awaits Arisu''s team.', 62, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 3), 5, 'Episode 5', 'Arisu follows his digital double through a simulation of future Shibuya, stopping at a heartwarming scene — and the real Usagi before him.', 78, '2025-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10795658')) AND numero_temporada = 3), 6, 'Episode 6', 'Haunted by a devastating glimpse into the future, Arisu crumples under the pressure to save everyone. Will he, Usagi and the team make it to the exit?', 77, '2025-09-25');
