INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10813940')), 1, 'Season 1', 'Free-spirited Georgia and her two kids, Ginny and Austin, move north in search of a fresh start but find that the road to new beginnings can be bumpy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10813940')) AND numero_temporada = 1), 1, 'Pilot', 'Georgia Miller arrives in the quaint New England town of Wellsbury with her daughter, Ginny, and her son, Austin, and quickly makes a big impression.', 58, '2021-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10813940')) AND numero_temporada = 1), 2, 'It''s a Face Not a Mask', 'As Ginny struggles to fit in with her new friends, she faces fallout from a night with Marcus. Georgia helps problem-solve for both Paul and Ellen.', 50, '2021-02-24');
