INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')), 1, 'Season 1', 'Slowly but surely, Ted makes England his new home. Throughout the season, the down-on-their-luck players cannot help but be charmed and inspired by Ted. Even team owner Rebecca Welton who initially hired Ted to tank the team’s chances and to annoy her cheating ex-husband, was moved by Ted’s boyish innocence, determination, and outrageous tea biscuits.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 1, 'Pilot', 'American football coach Ted Lasso is hired by a wealthy divorcée to coach the English soccer team AFC Richmond.', 33, '2020-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 2, 'Biscuits', 'It''s Ted''s first day of coaching, and fans aren''t happy. He makes little headway but remains undeterred as the team plays its first match.', 32, '2020-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 3, 'Trent Crimm: The Independent', 'To arrange an in-depth exposé, Rebecca pairs cynical journalist Trent Crimm with Ted for a day. Ted and Roy venture into the community.', 33, '2020-08-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 4, 'For the Children', 'Rebecca hosts the team''s annual charity benefit, where Ted stages a reconciliation between Roy and Jamie.', 36, '2020-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 5, 'Tan Lines', 'With his wife and son visiting from America, Ted makes drastic changes to the lineup during a critical match.', 34, '2020-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 6, 'Two Aces', 'When Jamie refuses to train, Ted turns to talented new signing Dani Rojas—and the team is struck by an age-old curse.', 34, '2020-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 7, 'Make Rebecca Great Again', 'Rebecca celebrates her first anniversary as a divorcée as the team plays a match in Liverpool.', 35, '2020-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 8, 'The Diamond Dogs', 'Ted and Roy are both having relationship problems. Ted consults the Diamond Dogs while Roy has a talk with Keeley.', 32, '2020-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 9, 'All Apologies', 'After a series of mistakes on the pitch, pressure mounts to bench Roy. Rebecca drops a bombshell.', 34, '2020-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 1), 10, 'The Hope That Kills You', 'Richmond plays a climactic match that will determine the fates of Ted and his club.', 36, '2020-10-02');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')), 2, 'Season 2', 'Season 2 will no doubt be a redemption story. While the team will face struggles, Ted’s illuminating, yet often frustrating kindness will encourage the team to move forward. As Ted believes, everything will work out the way it’s supposed to. Struggling to adjust to their lower league status, Ted focuses the team’s attention toward leaving behind their losing streak. Ted adjusts to his life without his now ex-wife Michelle and his young son, Henry, who have returned to the US. A psychologist named Sharon joins the team. The lovable Keeley Jones and newly retired Roy Kent continue dating. Roy is adjusting to his new life on the sidelines. As for Rebecca Welton starts dating again.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 1, 'Goodbye Earl', 'AFC Richmond brings in a sports psychologist to help the team overcome their unprecedented seven game tie-streak.', 39, '2021-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 2, 'Lavender', 'Ted is surprised by the reappearance of a familiar face. Roy tries out a new gig.', 37, '2021-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 3, 'Do the Right-est Thing', 'Rebecca has a special visitor shadow her at work. A player''s return is not welcomed by the team.', 40, '2021-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 4, 'Carol of the Bells', 'It''s Christmas in Richmond. Rebecca enlists Ted for a secret mission, Roy and Keeley search for a miracle, and the Higginses open up their home.', 33, '2021-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 5, 'Rainbow', 'Nate learns how to be assertive from Keeley and Rebecca. Ted asks Roy for a favor.', 41, '2021-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 6, 'The Signal', 'Ted is fired up that the new team dynamic seems to be working. But will they have a chance in the quarterfinal?', 38, '2021-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 7, 'Headspace', 'With things turning around for Richmond, it''s time for everyone to work on their issues—like Ted''s discomfort, Nate''s confidence, and Roy''s attention.', 38, '2021-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 8, 'Man City', 'Ted and Dr. Sharon realize they might have to meet each other halfway. Tensions are high as the team prepares for the semifinal.', 48, '2021-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 9, 'Beard After Hours', 'After the semifinal, Beard sets out on an all-night odyssey through London in an effort to collect his thoughts.', 46, '2021-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 10, 'No Weddings and a Funeral', 'Rebecca is stunned by a sudden loss. The team rallies to show their support, but Ted finds himself grappling with a piece of his past.', 49, '2021-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 11, 'Midnight Train to Royston', 'A billionaire football enthusiast from Ghana makes Sam an unbelievable offer. Ted plans something special for Dr. Sharon''s last day with the team.', 45, '2021-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 2), 12, 'Inverting the Pyramid of Success', 'Richmond gets their final chance to win promotion as Ted deals with the fallout of Trent Crimm''s painfully honest exposé.', 53, '2021-10-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')), 3, 'Season 3', 'In this third season, the newly-promoted AFC Richmond faces ridicule as media predictions widely peg them as last in the Premier League and Nate, now hailed as the "wonder kid," has gone to work for Rupert at West Ham United. In the wake of Nate''s contentious departure from Richmond, Roy Kent steps up as assistant coach, alongside Beard. Meanwhile, while Ted deals with pressures at work, he continues to wrestle with his own personal issues back home, Rebecca is focused on defeating Rupert and Keeley navigates being the boss of her own PR agency. Things seem to be falling apart both on and off the pitch, but Team Lasso is set to give it their best shot anyway.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 1, 'Smells Like Mean Spirit', 'The newly promoted AFC Richmond face mockery as pundits predict they''ll finish dead last this season.', 47, '2023-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 2, '(I Don''t Want to Go to) Chelsea', 'News of a top player looking to move to London sends the English clubs into a frenzy. Richmond play their first game back in the Premier League.', 50, '2023-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 3, '4-5-1', 'Richmond adjust to an exciting change, but Jamie has reservations. Ted learns there''s something new going on back in Kansas as well.', 50, '2023-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 4, 'Big Week', 'Everyone''s feeling the pressure as Richmond gear up to play West Ham. Ted is reunited with an old friend.', 53, '2023-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 5, 'Signs', 'With their season in a tailspin, Richmond try to right the ship against mighty Manchester City. Off the pitch, everyone faces their own setbacks.', 53, '2023-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 6, 'Sunflowers', 'A friendly match takes the team to Amsterdam, where one night out unlocks truths for many.', 66, '2023-04-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 7, 'The Strings That Bind Us', 'The Greyhounds try a new strategy that has everyone thinking outside the box. Sam prepares to host a VIP guest at Ola''s.', 61, '2023-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 8, 'We''ll Never Have Paris', 'While watching Henry, Ted fights the urge to spiral when Michelle and Dr. Jacob go on a romantic trip. An online leak has massive implications for Keeley.', 58, '2023-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 9, 'La Locker Room Aux Folles', 'Colin and Isaac''s friendship is tested. Roy is asked to do a press conference.', 47, '2023-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 10, 'International Break', 'While some of the Greyhounds head home to play for their countries in international matches, Edwin Akufo brings a business proposal to Rebecca.', 67, '2023-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 11, 'Mom City', 'An unexpected guest has Ted on edge. When Richmond travel to Manchester for a big match, Roy and Keeley become concerned about Jamie.', 73, '2023-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt10986410')) AND numero_temporada = 3), 12, 'So Long, Farewell', 'AFC Richmond play their final game of the season.', 79, '2023-05-30');
