INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')), 1, 'Season 1', 'A thriving high school girls soccer squad is left stranded in the northern wilderness after a plane crash and descend into savage clans, where survival becomes even more important than the team.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 1, 'Pilot', 'On the eve of a fateful flight, a championship high school girls soccer squad celebrates being a team by betraying one another. 25 years later, the survivors do their best imitations of well-adjusted people.', 56, '2021-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 2, 'F Sharp', 'As the teens get their bearings among the wreckage, Misty finds hell on earth quite becoming. In the present: revenge, sex homework and the policeman formerly known as Goth.', 57, '2021-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 3, 'The Dollhouse', 'The Yellowjackets debate the merits of probably dying while staying put or probably dying while looking for shelter. Taissa navigates a dirty attack ad and the other C-word. Shauna sees about a boy.', 57, '2021-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 4, 'Bear Down', 'The girls play with guns to determine who is the most responsible. Natalie untangles a lifetime of piecing together broken men. Taissa greets the rich.', 58, '2021-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 5, 'Blood Hive', 'Out in the wilderness, the girls ride the crimson wave and plan a dark arts slumber party. Natalie and Misty tame a stallion. On Halloween night, Shauna parties like it’s 1996.', 58, '2021-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 6, 'Saints', 'The Yellowjackets tangle with the birds & the bees, navigating love, lust and DIY surgery. In the present : blackmail, bunnies and an icy reunion. Misty prepares for a surprise(d) houseguest.', 58, '2021-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 7, 'No Compass', 'As starvation looms, Taissa leads a last-ditch effort and/or suicide mission. Amid felony schemes and all-night stakeouts, the Yellowjackets are forced to commit small talk.', 58, '2021-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 8, 'Flight of the Bumblebee', 'What is madness and what is divine? While in triage after a vicious attack, the Yellowjackets are left to suss out the best of their worst ideas. Shauna dabbles in some light cyberstalking.', 58, '2022-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 9, 'Doomcoming', 'You are cordially invited to The Doomcoming. On the brink of death, the Yellowjackets opt to throw one last rager before careening into oblivion. An increasingly paranoid Shauna struggles between keeping her cool and being Shauna.', 58, '2022-01-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 1), 10, 'Sic Transit Gloria Mundi', 'On the night of their 25-year class reunion, the Yellowjackets navigate damning evidence, false alibis and a dubious attempt to “heal.” In the wilderness, the Doomcoming fallout finds everything firmly off the rails as simmering resentments come to a head. Season finale.', 59, '2022-01-16');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')), 2, 'Season 2', 'The Yellowjackets barely made it through summer in the woods, but now as winter begins to bite, hunger and desperation threatens to turn into full-on psychosis. Meanwhile, twenty-five years later, each survivor must ask themselves—is the darkness coming for them, or is it coming from them?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 1, 'Friends, Romans, Countrymen', 'Two months into winter the survivors cope with falling rations, low morale and their latest disastrous attempt to freeze a teammate out of the game. Shauna explores the secondary market for Yellowjackets memorabilia, while Taissa, Misty and Natalie all seek out best friends, both old and new. For those of you keeping the stat book: Lottie Matthews comes in off the bench.', 59, '2023-03-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 2, 'Edible Complex', 'The Yellowjackets barely made it through summer in the woods, but now as winter begins to bite, we’ll see if hunger and desperation turn into full-on psychosis. While there may or may not be a dark and powerful force inhabiting the wilderness, their survival could depend upon what they choose to believe. Meanwhile, twenty-five years later, each survivor must ask themselves – Is the darkness coming for them, or is it coming from them?', 60, '2023-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 3, 'Digestif', 'The girls experience an unusual hangover. Shauna learns the thrill of peer-to-peer car rentals. Natalie audits Lottie’s class in emotional apiology. Tai reflects, Misty hits the high seas, and you’ve never attended a baby shower like the one the Yellowjackets throw here.', 57, '2023-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 4, 'Old Wounds', 'Relive your youth by hitting the road! Take a roadtrip with your child! Go on vacation with a new friend! Hitchhike, if you must! Just make sure you pack a good playlist for the ride. Some recommendations from us: “Anything You Can Do,” “You Get What You Give,” “Instinct,” a famous composition by Frank Comstock, but absolutely not anything from “Starlight Express”.', 60, '2023-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 5, 'Two Truths and a Lie', 'Okay, Fellowjackets, rise and shine and don’t forget your booties because it’s coooold out there. Misty makes a leap of faith for her bestie, Natalie and Lottie play a game of surrender, Shauna finds herself unexpectedly randy, and Tai seeks out a movie recommendation.', 59, '2023-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 6, 'Qui', 'Trapped inside on a snow day, the Yellowjackets revisit the highlights, humiliations and traumas of “Health Class.” Tai and Van help each other kindly rewind, Misty explores joining a classic Cosmic American tribute band, Lisa helps Natalie carp the day, and Shauna gets a pop-quiz on her cookie-reading assignment.', 55, '2023-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 7, 'Burial', 'Sometimes the best therapy is cranking the hits to eleven, so today we’re exploring the hardcore kid-care revival movement, 11 o’clock theatrical birdcore numbers, some late hits of the renovationwave era (call us about a spinoff!), flower duets, and a classic live record. Out in the wilderness, Coach Scott does a great Karl Havoc impression for an unimpressed Misty.', 59, '2023-05-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 8, 'It Chooses', 'Shhh, it’s only going to get worse from here. Despite the whole “winter never’s gonna end” thing, the 1996 New Jersey state girls soccer champions decide to start their spring training early with an impromptu cardio session. Callie encounters an old flame, Van proves goalies never say die, most of the adults intentionally commune in the sharing shack, and, Lottie, baby, I hear the blues are calling for tossed salad and scrambled eggs. Mercy!', 51, '2023-05-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 2), 9, 'Storytelling', 'Heavy is the head that wears the antler crown is a lesson you don’t learn until much later in life… if you ever even learn it at all. Everything’s about to get really wild(erness), and we’re so excited (so excited!) and so, so scared to find out who paid attention to what lessons and when. So, on the count of three, you may pick up your pencil, open your testing booklet, and start this finale exam. One… Two…', 61, '2023-05-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')), 3, 'Season 3', 'In season three, as summer arrives, the Yellowjackets face a fragile victory—the brutal winter that nearly claimed them is finally behind them, but distrust in leadership and tension within the team jeopardize their chances of being rescued. In the present, long-buried secrets from their pasts begin to surface. As the women fight to keep their lives from unraveling, they must confront a chilling question: who are they really, and what dark truths are they hiding from each other and themselves?');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 1, 'It Girl', 'Summer inspires the Yellowjackets to ditch soccer for a more contact-intensive sport and revive an old pagan tradition. In the present, a cringe-worthy funeral flows organically into a bar therapy session.', 60, '2025-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 2, 'Dislocation', 'The Yellowjackets are stuck deciding whether to track down a missing teammate or just trip out on mushrooms. Shauna secures a spot on the world''s most unsupportive partner list. Misty finds herself tangled in the intimate chaos of sleepover parties.', 58, '2025-02-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 3, 'Them''s the Brakes', 'The return of a Yellowjacket sparks a vengeful frenzy in the team. Lottie''s rendition of Cool Aunt Without Kids leaves Callie with an open door to answers about her mother''s twisted past. Tai and Van receive a karmic payout for their dine and dash.', 55, '2025-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 4, '12 Angry Girls and 1 Drunk Travis', 'The Yellowjackets attempt to spin a hundred suspicions into proof. Coach Scott has an existential meltdown. Meanwhile, Jeff embarks on a crusade to make things right as Shauna is forcibly committed to some "me time." Spoiler: it''s not a spa day.', 55, '2025-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 5, 'Did Tai Do That?', 'The Yellowjackets confront the reality of having to pull an Old Yeller. Lottie mentors an up-and-coming prophet. In the present, Misty investigates a suspicious death. Shauna, desperate, turns to the last person she would trust – because, why not?', 55, '2025-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 6, 'Thanksgiving (Canada)', 'The Yellowjackets start turning on each other faster than a reality TV reunion special. Meanwhile, the Sadecki family "vacation" features a vending machine and a deep dive into questionable parenting choices. Misty uncovers an incriminating clue.', 54, '2025-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 7, 'Croak', 'The Yellowjackets realize their choices have snowballed into a catastrophe. Misty sets her sights on a fresh suspect, and even she''s surprised by the plot twist. Meanwhile, Taissa''s desperation is peeling back layers she didn''t even know she had.', 54, '2025-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 8, 'A Normal, Boring Life', 'With a possible escape from their nightmare, the Yellowjackets learn not everyone may be in a rush to leave. In the present, the unexpected return of an old teammate sends Shauna spiraling in ways that should probably concern everyone.', 55, '2025-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 9, 'How the Story Ends', 'The Yellowjackets'' rites of spring come to an end, with Misty getting a pick-me-up and Shauna facing a sticky Melissa problem, all while taking cues from Stravinsky (or Picciotto).', 55, '2025-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11041332')) AND numero_temporada = 3), 10, 'Full Circle', 'Things turn frigid as bloody new alliances get built and spilled. It''s our time, right now, down here in the new Queen''s court. Eat up, drink deep, and descend.', 60, '2025-04-13');
