INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 1, 'The Nigerian Job', 'A desperate aerospace CEO asks Nate Ford - an insurance investigator who once specialized in recovering stolen goods worth millions - to lead a team of expert thieves to recover airplane designs from the rival company that took them.', 57, '2008-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 2, 'The Homecoming Job', 'Leverage Consulting & Associates opens for business as the crew reunites to help a Reservist who''s been wounded in Iraq by private military contractors.', 42, '2008-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 3, 'The Two-Horse Job', 'After a Wall Street broker sets fire to his stable—killing his underachieving racehorses in the process, the team visits Kentucky to help the heartsick trainer, Eliot’s high school love.', 43, '2008-12-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 4, 'The Miracle Job', 'Nate''s childhood best friend seeks the help of Leverage Consulting & Associates in preventing the demolition of his church... by stealing a miracle.', 43, '2008-12-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 5, 'The Bank Shot Job', 'Sophie and Nate find themselves taken hostage during a bank robbery. They soon learn they are trapped inside with their latest target: a corrupt judge.', 43, '2008-12-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 6, 'The Stork Job', 'The Leverage team works to take down an adoption agency that has been stealing money from American couples.', 43, '2009-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 7, 'The Wedding Job', 'To pull of a heist, the team poses as wedding planners in order to get money promised to a family after they took the fall for a Mafia boss.', 43, '2009-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 8, 'The Mile High Job', 'The Leverage team attempts to expose a conglomerate’s cover-up of their toxic fertilizer, which has resulted in the death of a young girl. But the CEO has put all of the damning evidence on a plane to the Cayman Islands. The team races to catch the flight but, once airborne, they discover that the CEO’s intentions are far more sinister and that to avenge one life they’ll have to save their own.', 43, '2009-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 9, 'The Snow Job', 'While helping a National Guardsman, Nate puts his team on the line when he slips back into his alcoholic ways.', 43, '2009-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 10, 'The 12-Step Job', 'When the team cons an addicted embezzler into entering rehab, Nate confronts some of his own issues regarding alcoholism.', 43, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 11, 'The Juror #6 Job', 'When one of Parker''s aliases receives jury duty, Nate forces her to go, resulting in a showdown between the team and a corporation tampering with the jury.', 43, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 12, 'The First David Job (1)', 'The team puts together a plan to steal Nate''s former boss''s prized Michelangelo Maquette and sell it back to him.', 43, '2009-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 1), 13, 'The Second David Job (2)', 'Nate tries to piece together his team after coming out of hiding. However, the high stakes involved in his latest con could spell disaster for him and his friends.', 43, '2009-02-24');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 1, 'The Beantown Bailout Job', 'Nate, now sober, grudgingly reassembles the team to pit the local Irish mob against a banker who is gaming a government bailout. If they live, Nate has four thieves to deal with who believe he needs them in his life, whether he likes it or not.', 43, '2009-07-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 2, 'The Tap Out Job', 'The crew work to get a corrupt mixed martial arts promoter to invest all he has into a phony cable network, but their con is discovered. Now it is Elliot''s job to throw a fight.', 43, '2009-07-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 3, 'The Order 23 Job', 'The team must commandeer a full hospital floor in order to quarantine a convicted felon and get him to reveal the location of the stolen money, or die.', 43, '2009-07-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 4, 'The Fairy Godparents Job', 'Nate and his team continue to remove greed by focusing in on a avaricious investment banker. They''ll pose as "fairy godparents" to the awkward son of the white collar crook.', 43, '2009-08-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 5, 'The Three Days of the Hunter Job', 'The crew uses the world of government conspiracies to raise paranoia and expose a callous tabloid newscaster as a fraud.', 42, '2009-08-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 6, 'The Top Hat Job', 'The crew takes on a corrupt corporation which is marketing tainted foods. The scheme team needs to be tricky: they will put on a fake magic show so they can slip by the tight security.', 42, '2009-08-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 7, 'The Two Live Crew Job', 'Nate and his crew square off against a band of thieves in order to retrieve priceless stolen artwork.', 43, '2009-08-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 8, 'The Ice Man Job', 'Hardison fills in for Sophie as the inside man when the team sets their sights on an unscrupulous diamond merchant.', 43, '2009-09-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 9, 'The Lost Heir Job', 'The Leverage team targets a shady lawyer looking to usurp his client''s estate, with Parker playing the client''s long-lost daughter. With Sophie still out of the picture, the team works with an uptight lawyer as a chaperone, but there may be more to her than meets the eye. Summer season finale.', 43, '2009-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 10, 'The Runway Job', 'The Leverage team cons the owners of a clothing company after their employees are mistreated.', 43, '2010-01-13');
