INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 12, 'The Zanzibar Marketplace Job', 'The team is forced to work with their old enemy Sterling in order to free Nate’s ex-wife, Maggie from a Ukrainian jail and clear her name.', 43, '2010-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 13, 'The Future Job', 'The team goes after a con man masquerading as a psychic medium in order to drain the life savings of his bereaved clients.', 43, '2010-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1103987')) AND numero_temporada = 2), 14, 'The Three Strikes Job (1)', 'While trying to take down a corrupt local mayor exploiting his love of baseball, the Leverage team runs into an unexpected complication.', 43, '2010-02-10');
