INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt11117570', 'Tandav', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1804614'), 'SERIE', 'Tandav is a story that happens in the capital city of the world''s largest democracy - DILLI (New Delhi), where it takes you inside the closed, chaotic doors of power and manipulation and uncover the darkest lanes of Indian politics.', '2021-01-01', 'https://m.media-amazon.com/images/M/MV5BNjMwZmY1ODgtZTBhYi00ZDFhLTg3NmUtOWEyYjRkMGMzNTM0XkEyXkFqcGc@._V1_.jpg');
