INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')), 1, 'Season 1', 'Tandav is the coming together of different worlds under the gamut of politics. It is a dramatic take of the powerplay between people at the high level to secure their position. Youth plays a significant role in the story as we see where their future is headed in this dark abyss of politics.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 1, 'Tanashah', 'Farmer protests in Malakpur. JLD party members cheer outside Devki Niwas. VNU students file a complaint at the police station. Samar Pratap Singh and Devki Nandan have a conversation over a drink. Students get into trouble at the police station.', 35, '2021-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 2, 'Aazaadi', 'Breaking News spreads across the city and the country in turn. Shiva Shekhar takes the help of farmers at Malakpur and records a fake video about the protests which later goes viral.', 39, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 3, 'Chandragupta', 'Maithili Sharan gets a call from an unknown number and the man blackmails her. Farmers from Malakpur arrive at VNU for a rally. JLD party members make a huge decision at the JLD office.', 30, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 4, 'Left se Right', 'Farmers from Malakpur arrive at VNU to thank Shiva for all that he has done. Nomination day at VNU, SAI members nominate their respective candidates, and Gurpal speaks to Samar about Shiva.', 37, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 5, 'Jeevan aur Mrityu', 'Portfolios of various ministries are distributed among the JLD members. Swearing in of all the ministers takes place subsequently. SAI members find their missing friend.', 37, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 6, 'Babool ka Ped', 'Samar arrives at VNU and gives a speech to all the students present there recalling his last days at the university. Massive fight breaks out between students of VNU.', 37, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 7, 'Dhappa', 'Gurpal finds out a key piece of information via his informer Chhote Lal. Shiva meets Samar at his house and rejects an offer while Maithili searches for the Anonymous Caller and finds someone else instead.', 31, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 8, 'Tandav', 'VNU students request the election officers to postpone the elections. Shiva makes a major announcement at the Vivekananda Statue. Later, Presidential Debate takes place between Amit Mewani and Shiva.', 29, '2021-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11117570')) AND numero_temporada = 1), 9, 'Khel', 'Election day at VNU where all students cast their vote. Victory speech at VNU by the winning presidential candidate. Press conference held at JLD to make an important announcement.', 27, '2021-01-15');
