INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')), 1, 'Season 1', 'Set nearly 200 years before Game of Thrones, this season chronicles the events leading up to the Targaryen civil war, known as the Dance of the Dragons. King Viserys I Targaryen names his daughter, Princess Rhaenyra, as heir to the Iron Throne, breaking tradition and igniting tensions within the realm. The court becomes divided as Queen Alicent Hightower, Viserys’s second wife, promotes her son Aegon’s claim to the throne. Political intrigue, shifting alliances, and personal betrayals set the stage for a looming conflict that threatens to tear the Targaryen dynasty apart.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 1, 'The Heirs of the Dragon', 'Viserys hosts a tournament to celebrate the birth of his second child. Rhaenyra welcomes her uncle Daemon back to the Red Keep.', 66, '2022-08-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 2, 'The Rogue Prince', 'Princess Rhaenyra dives deep into the prophecies about House Targaryen while confronting a realm that resists the idea of a woman on the Iron Throne, and Prince Daemon, embittered over being passed over as the heir to Westeros, prepares to go to war.', 54, '2022-08-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 3, 'Second of His Name', 'Daemon and the Sea Snake battle the Crabfeeder. The realm celebrates Aegon''s second nameday. Rhaenyra faces the prospect of marriage.', 64, '2022-09-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 4, 'King of the Narrow Sea', 'Daemon returns to court after the successful completion of the battle. Princess Rhaenyra must deal with potential suitors in order to keep her line of succession.', 63, '2022-09-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 5, 'We Light the Way', 'Daemon visits his wife in the Vale. Viserys and Rhaenyra broker agreements with the Valeryons. Alicent seeks the truth about the princess.', 60, '2022-09-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 6, 'The Princess and the Queen', 'Ten years later. Rhaenyra navigates Alicent''s continued speculation about her children, while Daemon and Laena weigh an offer in Pentos.', 68, '2022-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 7, 'Driftmark', 'As the families gather on Driftmark for a funeral, Viserys calls for an end to infighting and Alicent demands justice.', 59, '2022-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 8, 'The Lord of the Tides', 'Six years later. With the Driftmark succession suddenly critical, Rhaenyra attempts to strike a bargain with Rhaenys.', 68, '2022-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 9, 'The Green Council', 'While Alicent enlists Cole and Aemond to track down Aegon, Otto gathers the great houses of Westeros to affirm their allegiance.', 58, '2022-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 1), 10, 'The Black Queen', 'Mourning a tragic death, Rhaenyra tries to hold the kingdom together and Daemon prepares for war.', 60, '2022-10-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')), 2, 'Season 2', 'The Dance of the Dragons erupts as Rhaenyra and Aegon II both assert their claims to the Iron Throne, plunging Westeros into a brutal civil war. The season delves into the complexities of loyalty, power, and family as both sides employ dragons and armies to assert dominance. Key events include the tragic assassination of Prince Jaehaerys, escalating the conflict, and the shifting dynamics among key players like Daemon Targaryen and Alicent Hightower. As the war intensifies, the realm witnesses the devastating consequences of ambition and the high cost of succession disputes.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 1, 'A Son for a Son', 'While Rhaenyra struggles to come to terms with her son''s murder, in King''s Landing, Alicent grows concerned that Aegon''s Small Council may lead them to an all-out war. Larys suggests Aegon needs a new Hand, and Rhaenyra arrives at a fateful decision.', 59, '2024-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 2, 'Rhaenyra the Cruel', 'As Otto schemes to turn the public against her, Rhaenyra questions Daemon''s loyalty. Meanwhile, Ser Criston Cole concocts a misguided plan for revenge.', 69, '2024-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 3, 'The Burning Mill', 'As ancient grudges resurface, Rhaenys suggests that Alicent may see reason while the men around her seek bloodshed. Ser Criston proposes a bold scheme. Daemon arrives at Harrenhal to raise an army for the Blacks.', 67, '2024-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 4, 'The Red Dragon and the Gold', 'In Rhaenyra''s absence and with no word from Daemon at Harrenhal, Rhaenys tries to keep the peace on the Black Council as Cole mounts a campaign into the Crownlands. In King''s Landing, Aemond continues to undermine Aegon''s fragile hold on authority.', 56, '2024-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 5, 'Regent', 'Amid whispers of bad omens, the Greens consider how to fill a void on Aegon''s Council, Jacaerys sets out on a rogue mission to strike a deal, and Daemon enlists Lord Willem Blackwood to help persuade the Brackens to bend the knee.', 63, '2024-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 6, 'Smallfolk', 'With few options left, Rhaenyra summons a trusted knight for a risky venture and plots with Mysaria to catalyze the smallfolk. Meanwhile, Daemon''s unease grows, and Aemond takes steps to reshape the Green Council.', 68, '2024-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 7, 'The Red Sowing', 'As Rhaenyra looks to gain an advantage by unusual means, Daemon pressures a young liege lord to raise up his bannermen.', 64, '2024-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11198330')) AND numero_temporada = 2), 8, 'The Queen Who Ever Was', 'As Aemond becomes more volatile, Larys plots an escape, and Alicent grows more concerned about Helaena''s safety. Flush with new power, Rhaenyra looks to press her advantage.', 70, '2024-08-04');
