INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt11192306', 'Superman & Lois', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0808376'), 'SERIE', 'The world''s most famous superhero and comic books'' most famous journalist face the pressures and complexities that come with balancing work, justice, and parenthood in today''s society.', '2021-01-01', 'https://m.media-amazon.com/images/M/MV5BMWU5NmFlYjktMmM1NS00NGMwLWIzN2MtMWQ2YTg0ZWMyNmVjXkEyXkFqcGc@._V1_.jpg');
