INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 1, 'Pilot', 'Superman and Lois'' return to idyllic Smallville is set to be upended by mysterious strangers.', 64, '2021-02-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 2, 'Heritage', 'While adjusting to their new lives in Smallville, Lois and Clark make an important decision concerning one of their sons. Meanwhile, tensions begin to rise between Lois and Morgan Edge. Lastly, Lana Lang Cushing invites the Kent family over for a barbecue.', 43, '2021-03-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 3, 'The Perks of Not Being a Wallflower', 'Clark shares some of his Kryptonian history with Jordan and Jonathan during a family breakfast. Meanwhile, Lois and Chrissy dig deeper to uncover the truth about Morgan Edge.', 44, '2021-03-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 4, 'Haywire', 'While sitting in the stands at the high school football game, Lois and Chrissy spot fish out of water Morgan Edge conversing with Mayor Dean and Kyle Kushing, and the two see right through this insincere move to try to win over the town. Meanwhile, Clark agrees to help Lois out at a town hall meeting, but things get tense when he finds himself pulled in two different directions. Lastly, Jonathan is having mixed emotions about Jordan''s newfound status.', 44, '2021-03-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 5, 'The Best of Smallville', 'As Smallville celebrates its first Harvest Festival since Martha’s passing, Clark is reminded what his mother meant to him and learns a lesson that will help him move past her death. Meanwhile, Lois makes a breakthrough in the investigation of Morgan Edge. Lastly, Kyle tries to reconnect with Lana, but it seems like he might be falling back into his old ways.', 42, '2021-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 6, 'Broken Trust', 'Clark reconsiders his decision to let Jordan play football. Meanwhile, Lois'' continued investigation of Morgan Edge requires her to trust an unexpected ally.', 44, '2021-05-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 7, 'Man of Steel', 'Clark struggles to help Jordan who is grappling with a new power. Meanwhile, Lois enlists Clark''s help which leads to a surprise encounter.', 43, '2021-05-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 8, 'Holding the Wrench', 'Clark encourages Lois to reach out for help after noticing her reaching a breaking point. Meanwhile, Jonathan finds himself in a dangerous situation. Lastly, Kyle encourages Sarah to audition for the musical revue at school.', 45, '2021-06-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 9, 'Loyal Subjekts', 'Chrissy and Clark team up to piece together the significance of Smallville to Morgan Edge.', 44, '2021-06-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 10, 'O Mother, Where Art Thou?', 'Lana reaches out to Lois and Clark when Kyle starts behaving strangely. Meanwhile, Jonathan opens up to Jordan. Lastly, Sarah storms out after accusing her mom of always covering for her dad.', 44, '2021-06-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 11, 'A Brief Reminiscence In-Between Cataclysmic Events', 'Clark makes a startling discovery about Morgan Edge.', 42, '2021-06-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 12, 'Through the Valley of Death', 'Lois and John Henry Irons can''t seem to agree on the best way to stop Morgan Edge. Meanwhile, Jonathan encourages Jordan to focus on strengthening his powers to help locate their dad. Lastly, an old friend is brought in to help with the search.', 43, '2021-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 13, 'Fail Safe', 'Superman pays a visit to Morgan Edge. Meanwhile, Lois and Chrissy work together on a story. Lastly, Jonathan finds a welcome distraction during a very stressful school day.', 45, '2021-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 14, 'The Eradicator', 'Lois is worried about Jordan as he and Sarah continue to grow closer. Meanwhile, Clark pays Lana a visit. Lastly, Jonathan has been spending more and more time with John Henry.', 41, '2021-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 1), 15, 'Last Sons of Krypton', 'Superman''s worst nightmare comes to life and Lois confronts Leslie Larr. Meanwhile, Lana, Kyle and Sarah agree to stay to help General Lane.', 46, '2021-08-17');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 1, 'What Lies Beneath', 'Lois and Clark struggle as a couple while Chrissy adjusts to running The Smallville Gazette with Lois. Jonathan faces new challenges on the football field, and secrets threaten to destroy Jordan and Sarah''s growing relationship. Meanwhile, Kyle grows concerned over Lana''s involvement with a new mayoral candidate. Lastly, John Henry Irons and his daughter Natalie attempt to make this new Earth their home.', 43, '2022-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 2, 'The Ties That Bind', 'Clark opens up to Lois about his ongoing struggle with visions and admits that there is only one person who might be able to help. Meanwhile, Lana receives some unexpected news and tensions begin to rise between Lois and Chrissy. Lastly, Sarah breaks plans with Jordan to spend time with Natalie.', 43, '2022-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 3, 'The Thing in the Mines', 'Lois reaches out to Ret. General Lane as Clark''s visions become worse during heated arguments with both Jonathan and Jordan. Meanwhile, Lana shares her frustrations with Kyle. Lastly, Natalie learns that her father didn''t follow through on a promise he made to her.', 43, '2022-01-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 4, 'The Inverse Method', 'Lois and Chrissy are on a mission to find Lois'' sister Lucy and Jonathan and Jordan become more and more unsettled as Clark''s painful visions continue. Meanwhile, Lana, Kyle and Sarah share a family breakfast and discuss Sarah''s upcoming quinceañera. Lastly, Natalie and her father share a bonding moment.', 44, '2022-02-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 5, 'Girl… You''ll Be a Woman, Soon', 'Lana, Kyle and Sarah prepare for Sarah''s quinceañera, but things don''t end up going as smoothly as they had hoped. Clark finds himself struggling with feelings of guilt about what happened to John Irons and Lois worries that she might have been wrong about Ally. Meanwhile, Jonathan learns that Ret. General Samuel Lane is planning to train Jordan. Lastly, Chrissy goes searching for the truth about Lois.', 43, '2022-02-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 6, 'Tried and True', 'Lois tells Clark that she and Chrissy plan to do a deeper dive into the Inverse Society and Lana and Sarah try to comfort each other after the fallout at Sarah''s quinceañera. Meanwhile, Jordan notices something suspicious in Jonathan''s book bag. Lastly, Lt. Mitch Anderson finds himself under fire for the deterioration of the department of defense''s relationship with Superman.', 43, '2022-03-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 7, 'Anti-Hero', 'Superman pleads with Lt. Anderson to investigate Ally Allston and Lois receives some very upsetting news. Meanwhile, Lois helps Lana prepare to fight the good fight. Lastly, Jordan is still irritated with Jonathan for lying to him.', 44, '2022-03-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 8, 'Into Oblivion', 'Lois, Clark, and Natalie notice a difference in John Henry''s behavior and fear something might be very wrong. Meanwhile, Kyle encounters an awkward moment with Lana while stopping by the house to pick Sarah up for school. Lastly, Jonathan and Jordan brace themselves when they realize a talking to from their parents is headed their way.', 43, '2022-03-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 9, '30 Days and 30 Nights', 'Lois thanks Lana for sticking up for Jonathan when one of the football players mother''s starts dogging him for getting football season cancelled. Meanwhile, Jordan''s unexpected departure on the mayoral election day leaves Sarah rattled. Lastly, Natalie and Sarah wonder if they notice a spark between John Henry and Lana.', 43, '2022-03-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 10, 'Bizarros in a Bizarro World', 'Superman races through the portal after Ally Allston, but when he arrives on the other side, he discovers everything on this parallel earth is... bizarre. Navigating his way through deceivingly familiar faces and landscapes, Superman goes on one wild ride in his fight to stop Ally from merging.', 43, '2022-04-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 11, 'Truth and Consequences', 'We pick up right where we left off with Jon-El smirking at Lois, who is still standing on the porch with Jordan. Jon-El, catches sight of his doppelganger Jonathan, standing not too far away. He lunges at him and Jordan tries to intervene but Jon-El appears to be stronger and faster than him.', 43, '2022-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 12, 'Lies That Bind', 'We pick up right where we left off with Clark levitating in front of Lana. Meanwhile, Jordan and Jonathan question whether Lois and Clark are telling them the complete story. Lastly, Natalie tries her best to get Sarah to acknowledge Jordan.', 42, '2022-05-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 13, 'All Is Lost', 'Clark and Lois disagree on the best way to figure out if Ally Allston went to the Inverse World. Meanwhile, John Henry makes a surprising discovery and Lois sets out to track Lucy down.', 43, '2022-06-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 14, 'Worlds War Bizarre', 'A weary Lois holds vigil at Superman''s bedside. Meanwhile, Jonathan and Jordan continue to worry about their father who seems more human now than ever. Lastly, John Henry and Natalie work together to figure out the best way to defend against Ally Allston''s powers.', 43, '2022-06-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 2), 15, 'Waiting for Superman', 'Chrissy Beppo, with the authorization of the Department of Defense, has a message for the people of Smallville, not only is the merging of planets real, it is happening.', 43, '2022-06-28');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')), 3, 'Season 3', 'In season 3, Clark and Lois are now working at the Smallville Gazette together and enjoying small town life. However, Lois'' work-life balance is put to the test when an undercover assignment reveals a deadly foe that promises to change the Kent family forever. Meanwhile, the Kent boys find themselves being pulled in opposite directions as Jordan discovers what a superhero-identity really means and Jonathan searches for purpose beyond the football field. Amid all this upheaval, John Henry is haunted by his doppelgänger''s past, leading to dangerous consequences for him and Natalie.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 1, 'Closer', 'Lois'' undercover assignment reveals a deadly foe that promises to change the Kent family forever. Meanwhile, the Kent boys find themselves being pulled in opposite directions.', 43, '2023-03-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 2, 'Uncontrollable Force', 'Clark and Chrissy both notice a small crack in Lois'' game face. Sarah and Jordan have an awkward encounter, and Lana receives a panicked phone call.', 42, '2023-03-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 3, 'In Cold Blood', 'Lois and Chrissy pursue a new lead in the Mannheim investigation against Clark''s wishes. Meanwhile, Jonathan, Jordan, and Nat face an unexpected obstacle.', 43, '2023-03-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 4, 'Too Close to Home', 'Lois interrupts an intense conversation between Clark and John Henry. Meanwhile, Jonathan has a heated discussion with Candice''s dad.', 43, '2023-04-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 5, 'Head On', 'Clark and General Lane are both having a hard time giving Lois room to make her own decisions. Meanwhile, Lana and Sarah have a run-in with an old friend at the diner.', 43, '2023-04-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 6, 'Of Sound Mind', 'Clark finds himself in uncharted territory, and Lois bonds with a new friend. Meanwhile, Superman pays Bruno Mannheim a surprise visit.', 43, '2023-04-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 7, 'Forever and Always', 'Lois and Clark dig deeper on Bruno Mannheim, starting with his connections to Hob''s Bay Medical Center, while Jonathan and Jordan panic at home over Lois'' dire diagnosis.', 43, '2023-05-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 8, 'Guess Who''s Coming to Dinner', 'After learning about Bruno and Peia, Clark works to reignite Lois'' interest in taking Bruno down; elsewhere, Natalie meets Matteo''s parents, with disastrous consequences.', 43, '2023-05-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 9, 'The Dress', 'Superman and John Henry clash over how to handle Bruno Mannheim, while Lois worries over upcoming treatments and confides in Lana about her early courtship with Clark.', 42, '2023-05-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 10, 'Collision Course', 'Lois attempts to interview Peia in the hopes of unearthing the truth about an old case, while Clark struggles to spend quality time with the boys.', 42, '2023-05-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 11, 'Complications', 'Clark helps Lois prepare for a procedure but must leave the boys with her to help John Henry and General Lane track down the Mannheims.', 43, '2023-06-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 12, 'Injustice', 'Finally, after seventeen years behind bars, Lex Luthor is set to be released from prison. Lois and Clark clash with Jordan over his carelessness around using his powers in public, while Jonathan struggles with Kyle''s change in behavior at the firehouse.', 43, '2023-06-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 3), 13, 'What Kills You Only Makes You Stronger', 'All of Smallville comes together to view a meteor shower, and Lex Luthor makes his move to take down Superman and Lois.', 43, '2023-06-27');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')), 4, 'Season 4', 'Following an action-packed and dramatic season three finale, the Kent family continues their fight against their biggest enemies in the upcoming final season. With Lois still reeling from her battle with cancer and Lex Luthor and his proxy Bizzarro-turned-Doomsday still a threat to Smallville and Superman, viewers are left hanging on edge amid this epic intergalactic battle in space.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 1, 'The End & the Beginning', 'Superman is in a brutal battle with Luthor''s monster; Lois and the boys race to save General Lane.', 43, '2024-10-07');
