INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 5, 'Break the Cycle', 'Lois takes bolder actions to stop Luthor; Jonathan juggles personal life and responsibilities; Clark discovers an unsettling truth.', 43, '2024-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 6, 'When the Lights Come On', 'Luthor plans to move LuthorCorp to Smallville, but finds opposition in Lana.', 43, '2024-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 7, 'A Regular Guy', 'After some concerning interactions in town, Clark is determined to protect the secret that he''s Superman – a task complicated by Jonathan and Jordan.', 43, '2024-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 8, 'Sharp Dressed Man', 'Luthor challenges Lois to a live telecast debate, though not everything is as it seems; John Henry and Clark face a troubling possibility.', 43, '2024-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 9, 'To Live and Die Again', 'Lois struggles against the fallout of the debate. Clark uses Luthor''s tactics against him, while Jonathan and Jordan prepare for an impending battle.', 43, '2024-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11192306')) AND numero_temporada = 4), 10, 'It Went By So Fast', 'The Kents fight with everything they have as Luthor makes his final move on Smallville.', 43, '2024-12-02');
