INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')), 1, 'Season 1', 'As the first season begins, FBI Special Agent Olivia Dunham is called in to investigate a mysterious outbreak that nearly kills her partner. The only person with any answers is an institutionalized scientist, Dr. Walter Bishop who can only be released under the care of his estranged son. Together, the three discover that the answer to this mystery is only a small piece of a much larger, more shocking truth.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 1, 'Pilot', 'When all the passengers on a plane die, FBI agent Olivia Dunham investigates the events and her partner almost dies. A desperate Olivia looks for help from Dr. Walter Bishop who has been institutionalized. Olivia, Dr. Bishop and his son Peter begin to discover what really happened on Flight 627 and begin to uncover a larger truth.', 82, '2008-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 2, 'The Same Old Story', 'Olivia, along with Peter and Walter Bishop, investigates the strange death of a woman who had an even stranger child. The woman was pregnant for only hours, yet the baby she birthed was fully developed - and also aged eighty years in the span of a few minutes. Olivia asks Nina Sharp of Massive Dynamic for help.', 51, '2008-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 3, 'The Ghost Network', 'The team investigates a bus full of dead commuters that appear to be fossilized and uncover a man who has visions of pattern-related disturbances before they happen; Dr. Bishop requests a piano in the lab to help him process data.', 51, '2008-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 4, 'The Arrival', 'Broyles calls in the team to investigate a deadly explosion and its source: a strange cylinder unharmed despite the destruction. Olivia determines that the same cylinder, or a similar one, is responsible for similar events in widely diverse locations.', 50, '2008-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 5, 'Power Hungry', 'The team investigate the case of a man who can project electricity... and is at the center of a series of strange deaths involving electricity.', 50, '2008-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 6, 'The Cure', 'The team investigates a woman that re-appears after weeks of being missing with a rare disease. She also inexplicably causes pain and death to the people she meets. During the investigation, dangerous level of radiation are detected. Walter obsesses about cotton candy; Peter strikes a deal with Nina Sharp; and a truth about Olivia is discovered.', 50, '2008-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 7, 'In Which We Meet Mr. Jones', 'When a strange parasite attaches itself to the internal organs of a dying FBI agent, Olivia suspects a connection to the Pattern; Peter and Walter tap into a dead man''s brain waves.', 50, '2008-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 8, 'The Equation', 'Walter thinks the abduction of a young music prodigy is linked back to his old bunkmate at St. Claire''s Hospital. When he kidnaps the child he sees a sequence of flashing lights. Olivia wants Walter to return to the mental institution much to Peter''s outcry, but Walter''s determination to help ends up having chilling ramifications.', 50, '2008-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 9, 'The Dreamscape', 'The team is called in to investigate why a man jumps out a window because he thinks he''s being attacked by butterflies. Olivia gets some breaks in solving the case from her former partner and that she is so desperate to rid herself of him that she demands to go back into the tank. Meanwhile, some former friends and current foes of Peter find out that he''s back in Boston.', 50, '2008-11-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 10, 'Safe', 'The team is called in on a bank robbery similar to other robberies in the area but this particular bank has the thief embedded inside the steel wall of the bank. Somehow the thieves have found a way to defy the law of physics. Walter thinks they''re after something of his. As the investigation deepens it all comes to a head when the thieves ambush one of the team.', 50, '2008-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 11, 'Bound', 'Olivia''s sister, Rachel, visits; Walter, Peter and Olivia try to solve the murder of an esteemed epidemiologist, which may be linked to Olivia''s abduction.', 51, '2009-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 12, 'The No-Brainer', 'Olivia, Walter and Peter are called in to investigate the death of a car salesman who was found in a pool of "goo," exactly like another man across the country. When Walter discovers that the "goo" is brain matter, the trio tries to figure out how the killer can liquefy human brains. As the deaths pile up, the investigation reveals a common thread linking the victims together in an unthinkable manner. Meanwhile, Olivia is horrified when the case places a loved one in harm''s way', 51, '2009-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 13, 'The Transformation', 'When the Fringe Division delves into another bizarre occurrence aboard an international jumbo jet, freakish remains are discovered at the crash site. Memories tip the team toward some promising leads, but the bigger picture and mysterious threat eludes them. With limited options and insufficient intelligence, Olivia and Peter go undercover.', 50, '2009-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 14, 'Ability', 'German agents question Olivia about her "relationship" with David Robert Jones, an escaped prisoner questioned months earlier now living in the U.S. The Fringe Division investigates a threatening case where victims die faceless from their orifices suddenly sealing.', 51, '2009-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 15, 'Inner Child', 'Just seconds before a building is demolished, a mysterious mute child that has been living alone underground is discovered. When the FBI''s Fringe Division investigates, the boy forms an unspoken connection with Agent Olivia Dunham. Meanwhile, an especially gruesome serial killer resurfaces and showcases his "artistry" by displaying his work publicly. As the boy gradually assimilates into a new environment, Olivia and the team must race against the clock to prevent the mad man from causing further massacre.', 50, '2009-04-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 16, 'Unleashed', 'As animal rights activists ransack a laboratory, they get more than they bargained for when one of the caged "animals" unleashes a ferocious appetite. Leaving grotesquely mutilated dead bodies in its wake, the scientifically engineered beast with the body of a lion, claws of an eagle, fangs of a viper, skin of a rhinoceros and tail of a serpent attacks Charlie. With Charlie’s life on the line, Walter must come face-to-face with both his past and the beast.', 51, '2009-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 17, 'Bad Dreams', 'Olivia dreams about a suicide as the event really happens at Grand Central Station; shocking information about the Z.F.T. manuscript is revealed.', 51, '2009-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 18, 'Midnight', 'The Fringe Division is on the case when severely mutilated bodies drained of spinal cord fluid begin to pile up. After their investigation leads them to a scientist with possible ties to the Z.F.T. bioterrorist cell, they are shocked to discover the identity and motive of the killer. When the kills occur with increasing frequency, Olivia, Peter and Walter go to desperate lengths to stop them.', 51, '2009-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 19, 'The Road Not Taken', 'Olivia experiences "awake dreams," seeing elaborate visions of things not really there. While investigating a disturbing case of a woman who apparently spontaneously combusted, Olivia throws caution to the wind and explores her unexplained visions further. Meanwhile, Walter discusses key information about the Z.F.T. manifesto, and Peter reveals a secret that yields unexpected results in the case.', 51, '2009-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 1), 20, 'There''s More Than One of Everything', 'Setting the stage for the dramatic and revealing first season finale are a sudden and unexpected attack on someone with close ties to Fringe Division, the return of bioterrorist David Robert Jones and the inexplicable disappearance of Walter. Find out more about the mysterious events surrounding our trio when questions are answered, observations made, loyalties are tested and the elusive William Bell is finally introduced.', 47, '2009-05-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')), 2, 'Season 2', 'Unable to police a world in which science has advanced beyond our wildest dreams — and nightmares — FBI Special Agent Olivia Dunham seeks help from brilliant but damaged scientist Dr. Walter Bishop and his estranged son with a dark past, Peter. Under the direction of Agent Phillip Broyles, they solve gruesome mysteries and prevent imminent attacks.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 1, 'A New Day in the Old Town', 'An amnesiac Olivia makes her return from the parallel universe, while Walter, Pete, and Junior Agent Amy Jessup investigate the mysterious death of a man found with puncture holes in his palate. Meanwhile, Broyles defends the Fringe Division from a Senate subcommittee threatening to shut the organization down.', 44, '2009-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 2, 'Night of Desirable Objects', 'A highway construction worker is the seventh in a series of mysterious disappearances in Lansdale, PA. The team come to investigate and finds traces of a mysterious paralytic. Meanwhile, Walter tries to send frogs to an alternate reality and Olivia realizes her recent trip has altered her in ways she can barely understand.', 44, '2009-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 3, 'Fracture', 'When an American officer who served in Iraq blows up in a Philadelphia train station, the Fringe Division investigates and determines that something turned the man into a living bomb. Peter and Olivia travel to Iraq to determine if Peter''s contacts can shed some light on the situation.', 44, '2009-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 4, 'Momentum Deferred', 'Olivia begins to regain her memories of her encounter with William Bell. Meanwhile, the "First Wave" tries to collect the head of their leader, and the traitor makes his move.', 44, '2009-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 5, 'Dream Logic', 'A man in Seattle goes berserk, attacking his boss and claiming his victim is a demon. After the killer dies of what appears to be exhaustion, the Fringe Division discover it''s only the first in a series of killings where the persons initiating the attacks were in a dreaming state while awake', 44, '2009-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 6, 'Earthling', 'Human beings are reduced to ash statues and Broyles realizes that the same person responsible murdered five other persons four years ago... a case that he never solved.', 44, '2009-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 7, 'Of Human Action', 'Two men kidnap a teenage boy using mind control abilities. The boy''s father works for Massive Dynamic but Nina insists that the company hasn''t been developing mind control, and has no idea who the two kidnappers are. The truth or falsehood of her statements are soon confirmed when Peter encounters the person responsible for the boy''s abduction.', 44, '2009-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 8, 'August', 'The Observer chooses to do something other than observe, abducting a college student. However, when the Fringe team investigates, they discover that there is more than one Observer.. in both time and space.', 44, '2009-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 9, 'Snakehead', 'A Chinese Triad is using illegal aliens to breed parasitic worms that eventually kill their hosts. When a ship runs aground, Fringe Division learns of the operation and tries to locate a second ship before the passengers on it suffer a slow, agonizing death.', 44, '2009-12-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 10, 'Grey Matters', 'The First Wave breaks into a mental hospital and cures a long-term patient suffering from schizophrenia. When the Fringe team investigates, Olivia discovers that the group''s leader has one of the heads stolen from cryogenic storage months earlier. Meanwhile, two other mental patients are cured of their schizophrenia and the team soon realize that something was taken from each patients'' brain... and Walter holds the key to realizing what First Wave is after.', 44, '2009-12-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 11, 'Unearthed', 'A teenage girl pronounced brain dead wakes up in the middle of the operation to remove her organs... speaking numbers in Russian. When the Navy confirms that the numbers are nuclear launch codes and a missing officer named Rusk knows them, the search is on for the missing man.', 44, '2010-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 12, 'Johari Window', 'A state trooper picks up a runaway boy, but when he undergoes a strange transformation, three murders result. The Fringe team is called in to investigate and discover that a small town harbors a horrible secret.', 44, '2010-01-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 13, 'What Lies Below', 'A Dutch industrial consultant arrives for an appointment and dies in a painful explosion of blood. Olivia and Peter arrive on the scene first and discover that the blood contains a pathogen and everyone in the building may be contaminated. While Walter and Astrid work outside the quarantined building to create a cure, the virus develops unique characteristics that pose a danger to the entire world.', 44, '2010-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 14, 'The Bishop Revival', 'When all of the groom''s relatives asphyxiate at a wedding, the Fringe division investigates and quickly ascertain that a human agency is responsible. Walter realizes that the formula for the toxin was based on research conducted by his father, Robert Bischoff, and that the killer isn''t stopping with a single test of his lethal concoction.', 44, '2010-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 15, 'Jacksonville', 'The arrival of a building from the alternate Earth causes massive death and destruction to those occupying the site at its arrival. Walter soon realizes that to equalize the balance between universes, another building will have to disappear... along with everyone inside it. The team''s only chance is for Walter to activate Olivia''s long-buried ability to distinguish objects from the other universe.', 44, '2010-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 16, 'Peter', 'Walter explains to Olivia how Peter came from the alternate universe, and how he was willing to risk everything to save his son.', 44, '2010-04-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 17, 'Olivia. In the Lab. With the Revolver.', 'A healthy woman dies of rapid-onset cancer in a matter of minutes, and the Fringe team is called in to investigate. The killer has connections to Jacksonville... and Olivia is a potential victim. Meanwhile, Olivia tries to come to terms with her knowledge of Peter''s origins.', 44, '2010-04-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 18, 'White Tulip', 'When the passengers on a commuter train all die instantly of massive power loss, the team realizes that a time traveler is responsible... and that it may be impossible to apprehend him. Meanwhile, Walter writes a letter to Peter explaining his origins.', 44, '2010-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 19, 'The Man From The Other Side', 'Two teenagers turn up dead and evidence indicates that shapeshifters have borrowed their forms for some special mission. While the Fringe team tries to track them down, Peter grows increasingly suspicious of Walter''s secretive behavior.', 44, '2010-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 20, 'Brown Betty', 'When Peter disappears, Walter seeks solace in marijuana. In that state of mind, he and Astrid babysit Olivia''s niece Ella, and Walter tells her a fairy tale of a gentle inventor, a stolen glass heart, a detective looking for true love, and a mysterious group of bald men known as the Watchers.', 44, '2010-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 21, 'Northwest Passage', 'In Noyo County, Washington, Peter stumbles across a grisly murder with ties to Newton and First Wave. He is forced to team up with a suspicious sheriff to get to the heart of the case. Meanwhile, Walter has trouble functioning without Peter, and worries he will be sent back to the mental institute.', 44, '2010-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 22, 'Over There (1)', 'When Walter discovers that Peter has traveled to the alternate universe, he and Olivia gather three cortexiphan children with the ability to transition safely between the two Earths.', 43, '2010-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 2), 23, 'Over There (2)', 'Walternate asks Peter to help complete the device, while the fugitives Walter and Olivia are reunited with William Bell. Meanwhile, the alternate world''s Fringe Division closes in on the invaders, and Peter must make a life-shattering decision.', 44, '2010-05-20');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')), 3, 'Season 3', 'Season three continues the rabbit-hole journey of three unlikely souls — FBI Agent Olivia Dunham, Fringe Scientist Walter Bishop and his jack-of-all-trades son Peter — through mind-bending investigations, parallel realities and threats growing in the borderlands between science and the unimaginable.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 1, 'Olivia', 'After the extraordinary turn of events that shockingly left an imprisoned Olivia "over there," she fights to find her way home. Meanwhile, Peter and Walter try to move on with their lives unknowingly alongside alternate Olivia.', 44, '2010-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 2, 'The Box', 'The story alternates to the Fringe Team "over here" where they investigate a mystifying case that people are discovered in a trance-like state that ultimately leads to their death. The unlikely suspect: a mysterious box. As Peter and Walter collaborate to study its properties, alternate Olivia presses on and turns up the heat on an unsuspecting Peter. Meanwhile, key information about the future is revealed when Walter and Nina meet at Massive Dynamic for the emotional reading of the last will and testament of William Bell.', 43, '2010-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 3, 'The Plateau', 'In this case, timing is everything as a series of anomalous events lead the Fringe Division to investigate deadly incidents with unimaginable coincidences. As the freaky crimes continue to occur, the team is in a race against time to protect potential victims. Meanwhile, Secretary Bishop shares his strategic plan with Colonel Broyles as Olivia grapples with a heart-stopping vision.', 44, '2010-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 4, 'Do Shapeshifters Dream of Electric Sheep?', 'Newton, concerned about the consequences of a distressing development involving a high-ranking official, is forced to call to action a sleeping shapeshifter. As Walter and the rest of the team gather evidence, they move the investigation to Massive Dynamic, where Olivia goes on high alert and Walter finds himself in a perilous situation.', 44, '2010-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 5, 'Amber 31422', 'The alternate universe Fringe Division investigates a shocking breach of security when a twin frees his brother from a quarantined Amber area. As the team sets out to crack this sophisticated case, Walternate experiments over there more with Olivia as she reenters the tank. Meanwhile, visions of Peter continue to haunt Olivia about returning to the “other side”.', 44, '2010-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 6, '6955 kHz', 'Back “over here,” the Fringe Division investigates a bizarre phenomenon when 15 people up and down the Eastern Seaboard, all suffer retrograde amnesia from listening to their shortwave radios on the same frequency. Much to Walter’s dismay, Peter presses on with piecing together the mass destruction device. Just as alternate Olivia and Peter’s chemistry deepens, the anticipation of Olivia’s return escalates.', 44, '2010-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 7, 'The Abducted', 'When a serial kidnapper “over there” strikes again, the emotional and familiar case hits home for Colonel Broyles, sending a determined Olivia to uncover additional details about the abductions. In the meantime, Olivia fights on and reunites with Henry to enlist his services on an intense and covert mission to return home.', 44, '2010-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 8, 'Entrada', 'Peter struggles to cope with recent events; Olivia searches for an ally; a device that communicates between universes is discovered...', 44, '2010-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 9, 'Marionette', 'When the Fringe Team investigates a case where a victim had his heart extracted, it’s just the beginning of a series of mysterious and reanimating events tied together. Meanwhile, Peter comes to terms with the reality of his relationship with Olivia.', 44, '2010-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 10, 'The Firefly', 'An Observer makes contact with the Fringe Team to help rectify a mistake. Meanwhile, Walter befriends Roscoe Joyce, keyboardist for Walter''s favorite 1970s band, "Violet Sedan Chair." Walter will learn the real reason the band broke up, and realize that the lives of these two men, who have never met before, overlap in strange and unexpected ways.', 44, '2011-01-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 11, 'Reciprocity', 'When the Fringe Team visits Massive Dynamic’s assembly of the doomsday device, Walter becomes greatly concerned for Peter’s well-being, so he turns to Nina for added brain power to understand the relationship between Peter and the superweapon. Meanwhile, the discovery of a dead body triggers an intense investigation.', 44, '2011-01-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 12, 'Concentrate and Ask Again', 'When a scientist falls dead after ingesting a lethal cloud of blue powder and his bones disintegrate in his body, the CDC suspects a biological attack. As the Fringe Team investigates further, a subject from Walter''s past with ties to Olivia reluctantly agrees to assist with the intense case.', 44, '2011-02-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 13, 'Immortality', 'As the story shifts back to life “over there,” the absence of Colonel Broyles changes the dynamic of the Fringe Team as they investigate a bioterrorist armed with an insect that has a taste for human flesh. Meanwhile, alternate Olivia is reunited with her beau, and Walternate remains determined to save his world but discovers there are certain lines he will not cross.', 44, '2011-02-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 14, '6B', 'A series of Fringe events leads the team to the home of a woman grieving over the death of her husband, while Peter and Olivia make an effort to repair the emotional rift between them.', 44, '2011-02-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 15, 'Subject 13', 'In a follow up to last season’s “Peter” flashback episode, the all-new “Six Months Later” episode revisits a poignant period of time for both the Bishops and Olivia.', 44, '2011-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 16, 'Os', 'The Fringe Team investigates a group of thieves who can break the laws of gravity. Meanwhile, Walter attempts to delay the damage he''s caused to the fabric of the universe.', 44, '2011-03-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 17, 'Stowaway', 'When the Fringe team investigates an apparent suicide victim, they uncover a second set of fingerprints leading them to a woman with uncanny characteristics that cannot die.', 44, '2011-03-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 18, 'Bloodline', 'The intensity of life “over there” accelerates as Olivia finds herself in mortal danger.', 44, '2011-03-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 19, 'Lysergic Acid Diethylamide', 'In an effort to remove Bell''s consciousness from Olivia''s mind, Peter, Bell, and Walter enter Olivia''s subconscious and attempt to find her personality, which has hidden itself somewhere safe.', 44, '2011-04-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 20, '6:02 AM EST', 'The beginning of the end is triggered when Walternate finds a way to wreak havoc “over here."', 43, '2011-04-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 21, 'The Last Sam Weiss', 'As devastation spreads on This Side, Walter, Olivia, and Sam Weiss struggle to find a way to stop the destruction and discover that one individual has the ability to allow Peter access to the Machine.', 44, '2011-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 3), 22, 'The Day We Died', 'As the thrilling third season propels to a climactic close, questions will be answered as Peter confronts his destiny and a beloved team member meets an untimely demise.', 44, '2011-05-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')), 4, 'Season 4', 'The fourth season of the American science fiction television series Fringe premiered on Fox on September 23, 2011 and concluded on May 11, 2012, consisting of 22 episodes. The series is produced by Bad Robot Productions in association with Warner Bros. Television. The show was officially renewed for a fourth season on March 24, 2011.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 1, 'Neither Here Nor There', 'Just one week after Peter Bishop saved the day and was then wiped from existence, the truce between the two worlds remains intact and the two sides are forced to work together. Lincoln Lee joins the Fringe team as they investigate a shapeshifter case that is very personal to him.', 44, '2011-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 2, 'One Night in October', 'As the victims of a highly intelligent serial killer "Over There" stack up, the Fringe Division "Over Here" is asked to assist. As the two sides tangle and innocent people remain at risk, the suspect''s doppelganger "Over Here," a professor who teaches Forensic Psychology, is brought into the fold and forces the team to consider the notion of sending civilians to the other side', 43, '2011-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 3, 'Alone in the World', 'Two young bullies are found dead and in just a few hours they rot to an advanced state of decomposition. The Fringe team investigates and uncovers an amorphous figure claiming more victims. Walter becomes increasingly distracted with his mental state.', 44, '2011-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 4, 'Subject 9', 'Olivia uncovers a dangerous force that may be connected to past experiments with Cortexiphan. The investigation forces Walter to leave the lab for the first time in years and travel to Massive Dynamic to examine old case files. Walter struggles with his emotional state as he confronts the demons of his past.', 44, '2011-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 5, 'Novation', 'Olivia and the others of Fringe division attempt to determine the origin of Peter Bishop, who purports himself as Walter''s son who had died as a young boy in the original time line.', 43, '2011-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 6, 'And Those We''ve Left Behind', 'The Fringe team must find the pattern between tragic time loop anomalies. As the investigation unfolds, Raymond, an electrical engineer, and his wife Kate, a professor of theoretical physics, enter the picture.', 44, '2011-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 7, 'Wallflower', 'When a man mysteriously dies by an invisible force, his body rapidly begins turning ghostly white. The Fringe team learns that this is not an isolated incident, and there’s evidence that links the predator to someone who passed away with an unknown genetic disorder. Meanwhile, Olivia suffers from migraines.', 44, '2011-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 8, 'Back to Where You''ve Never Been', 'In an effort to find a way home, Peter journeys to the Other Side to confront Walternate. However, his venture proves more dangerous than expected. Meanwhile, Olivia receives a dire premonition from an Observer.', 44, '2012-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 9, 'Enemy of My Enemy', 'Peter''s visit to the other side intensifies as the alternate FRINGE division faces off against a formidable new foe in a harrowing race against time.', 44, '2012-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 10, 'Forced Perspective', 'Olivia continues to cope with the ominous warning from the Observers, while Peter and the team track a girl with the mysterious ability to predict death.', 44, '2012-01-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 11, 'Making Angels', 'Over Here Astrid gets an unexpected visit from her Alternate, while Peter and Olivia track a killer using a toxin that has yet to be invented. Both universes collide in a case that pushes the boundaries of what is possible.', 44, '2012-02-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 12, 'Welcome to Westfield', 'Peter, Olivia and Walter come face to face with a mysterious and terrifying Fringe event as they get trapped in a town that there’s no escaping from.', 44, '2012-02-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 13, 'A Better Human Being', 'As the Fringe team investigates a mentally ill patient who appears to be connected to a series of murders, frightening clues and connections are uncovered that lead Olivia to some shocking revelations.', 44, '2012-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 14, 'The End of All Things', 'The dying Observer comes to see Walter and Peter, who must take extreme measures to learn what secrets he hides and determine if he knows where Olivia is. Meanwhile, David Robert Jones tries to force Olivia to use her cortexiphan abilities by torturing Nina.', 44, '2012-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 15, 'A Short Story About Love', 'Following the recent shocking revelations and emotional events, Peter weighs his options as the Fringe team investigates a killer targeting love.', 44, '2012-03-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 16, 'Nothing As It Seems', 'The Fringe team faces a case that appears familiar to Peter. Strangely, it takes place in this timeline.', 44, '2012-03-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 17, 'Everything in Its Right Place', 'Lincoln travels to the other side to join forces with Fauxlivia and his own alternate, as they search for a vigilante with a surprising connection to the shapeshifters.', 44, '2012-04-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 18, 'The Consultant', 'Walter travels to the Alternate Universe to assist in the investigation of a Fringe event with ties to both worlds. Meanwhile, David Robert Jones reveals his next target.', 43, '2012-04-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 19, 'Letters of Transit', 'The Fringe team goes back to the future as the story jumps ahead to 2036, when the Observers and the Fringe team engage in a game-changing battle.', 44, '2012-04-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 20, 'Worlds Apart', 'The teams on both sides fight on for a common cause, and there are shocking developments tied to the Cortexiphan children.', 43, '2012-04-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 21, 'Brave New World (1)', 'Walter is forced to revisit his painful past when a fringe event causes people to spontaneously combust; the team faces off with David Robert Jones.', 43, '2012-05-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 4), 22, 'Brave New World (2)', 'The Fringe team is pushed to the breaking point as they desperately attempt to prevent a catastrophic event that threatens the lives of everyone.', 44, '2012-05-11');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')), 5, 'Season 5', 'Season five picks up from events depicted in season four''s flash-forward episode the seemingly peaceful Observers seized control of our universe in 2015. Now, in 2036, they have become ruthless rulers who stand unopposed. What awaits in the future, however, is the Fringe Team''s final stand to protect our world.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 1, 'Transilience Thought Unifier Model-11', 'The Fringe team - preserved in amber for 20 years - is now a rebel resistance team fighting for freedom. Peter, reunited with his now adult daughter, Etta, sets out to find out what happened to his wife and Etta''s mom - Olivia - as they start their mission to save the world from the Observers.', 43, '2012-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 2, 'In Absentia', 'The Fringe team revisits the Harvard lab, now under Observer control, to try to find the information they need as the team fights on in their mission to save the world.', 42, '2012-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 3, 'The Recordist', 'As the rogue Fringe team continues to fight off the oppressive Observers’ invasion, unforeseen events lead them into a forest where they encounter a strange subculture of people devoted to recording human history.', 42, '2012-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 4, 'The Bullet That Saved the World', 'When the Fringe team tracks a lead into a hostile and heavily guarded location, Phillip Broyles resurfaces…but can he be trusted?', 43, '2012-10-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 5, 'An Origin Story', 'The Fringe team responds to recent devastating events, and a key member makes a pivotal and shocking move.', 44, '2012-11-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 6, 'Through the Looking Glass and What Walter Found There', 'Walter retrieves another video tape from the amber and it leads the team into a pocket universe.', 43, '2012-11-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 7, 'Five-Twenty-Ten', 'The team retrieves another cassette tape from the amber. With Nina Sharp''s help, the team recovers 2 cylinders. While Peter works independently to score a minor victory against the Observers, Olivia ascertains Peter''s secret.', 43, '2012-11-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 8, 'The Human Kind', 'Olivia encounters a very intuitive and oracle-like person named Simone as she looks to recover a key piece of equipment for Walter. Meanwhile, Peter finds himself in a perilous situation as he observes Windmark.', 44, '2012-12-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 9, 'Black Blotter', 'In attempt to recall a plan to defeat the Observers, Walter takes an LSD trip down memory lane. Meanwhile, Peter and Olivia trace a mysterious signal to the woods, where they come upon a grisly scene.', 43, '2012-12-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 10, 'Anomaly XB-6783746', 'The Fringe team is running out of time to save the world. As Peter, Olivia, Astrid and Walter scramble to tap into a key piece of the puzzle to defeat the Observers, they enlist the aid of Nina Sharp who conjures up a plan.', 44, '2012-12-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 11, 'The Boy Must Live', 'As time dramatically ticks down, Peter, Olivia and Walter stop at nothing to save the universe from Observer rule. Walter enters the infamous deprivation tank in an attempt to uncover a key piece of information about the mysterious figure, Donald. Meanwhile, Captain Windmark sets out on a revealing mission of his own as long-standing questions are answered.', 44, '2013-01-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 12, 'Liberty', 'Peter, Olivia, Walter, Astrid and Broyles face off against the Observers in one final and extraordinary battle for the fate of mankind.', 43, '2013-01-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1119644')) AND numero_temporada = 5), 13, 'An Enemy of Fate', 'The Fringe team engages a desperate plan as Olivia embarks on a dangerous and otherworldly journey into the unknown. Then, Peter, Olivia, Walter, Astrid and Broyles face off against the Observers in one final and extraordinary battle for the fate of mankind.', 44, '2013-01-18');
