INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11280740')), 1, 'Season 1', 'At Lumon Industries, employees undergo "severance," a procedure dividing their work and personal memories. Mark, a grieving team leader, begins to uncover the dark secrets of the company, forcing him and his coworkers to confront questions of identity, free will, and corporate control.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11280740')) AND numero_temporada = 1), 1, 'Good News About Hell', 'Mark is promoted to lead a team who''ve had their memories surgically divided between their work and personal lives.', 57, '2022-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11280740')) AND numero_temporada = 1), 2, 'Half Loop', 'The team train new hire Helly on macrodata refinement. Mark takes a day off to meet with a mysterious former colleague.', 53, '2022-02-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11280740')) AND numero_temporada = 1), 3, 'In Perpetuity', 'Mark takes the team on a field trip, but Helly continues to rebel. A deteriorating Petey struggles to tell Mark about Lumon’s misdeeds.', 56, '2022-02-24');
