INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')), 1, 'Season 1', 'The Sons of Anarchy live, ride, and die for brotherhood. But as the club''s leader Clay Morrow and his wife Gemma steer them in an increasingly lawless direction, Gemma''s son Jax is torn between loyalty and the legacy.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 1, 'Pilot', 'When a rival club cleans out and then destroys their illegal arms warehouse, SAMCRO (Sons of Anarchy Motorcycle Club, Redwood Original) executes their own sense of justice in retrieving their guns. Meanwhile, family issues take center stage with a medical emergency involving Jax Teller''s newborn son.', 57, '2008-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 2, 'Seeds', 'As the club deals with the aftermath of its illegal arms warehouse attack, the deputy chief of police poses a new threat to SAMCRO''s reign over Charming; Jax continues to worry about his newborn son''s fate; Opie faces a difficult decision.', 47, '2008-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 3, 'Fun Town', 'When a prominent Charming family''s young daughter is assaulted at a carnival, SAMCRO races against the authorities to capture the assailant; a new shipment of guns arrives from the group''s IRA connection; Tara''s ex-boyfriend arrives in Charming.', 48, '2008-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 4, 'Patch Over', 'The club travels to Nevada to store arms with a brother club; when the Mayans pose a threat, Clay decides to "patch-over" the tribe, making them an official charter; Tara''s ex, an ATF agent, investigates SAMCRO.', 44, '2008-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 5, 'Giving Back', 'Gemma hosts a town fundraiser, bringing the former club member responsible for Opie''s arrest back to town; Clay deals with protecting a perverse parolee who can lead to a big payoff.', 42, '2008-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 6, 'AK-51', 'A small favor for Piney''s old war buddy turns into a big problem for SAMCRO; Gemma deals with the effects of aging.', 43, '2008-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 7, 'Old Bones', 'When old bones are discovered on the outskirts of Charming, Clay must deal with long-buried secrets; the club sets its sights on prize money in a bare-knuckle brawl; Kohn''s investigation becomes personal when his true intentions are revealed.', 44, '2008-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 8, 'The Pull', 'With the IRA gun payment looming, Samcro scrambles to come up with the cash; the Mayans and Nords take a drastic step toward strengthening their alliance; Jax finds himself in a dangerous position with Tara.', 44, '2008-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 9, 'Hell Followed', 'SAMCRO plans retaliation on a rival biker club while dealing with wounded Cameron Hayes in the clubhouse; Jax, Bobby and Opie try to end the gun debt for good.', 45, '2008-10-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 10, 'Better Half', 'With Stahl pressing the women of SAMCRO, Jax sees Unser as the key to salvation; Cherry reveals interesting information about her past.', 44, '2008-11-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 11, 'Capybara', 'Jax''s loyalty to SAMCRO is tested when one member is arrested and another disappears. Meanwhile, Abel''s improving condition could spur his release from the NICU, but his homecoming may not be the only one.', 43, '2008-11-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 12, 'The Sleep of Babies', 'Clay''s solution to getting cash for Bobby''s defense leaves SAMCRO in a vulnerable position; Abel''s happy homecoming ends in turmoil for the club.', 47, '2008-11-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 1), 13, 'The Revelator', 'In the wake of a tragedy, the club must re-evaluate its bonds of brotherhood.', 60, '2008-11-26');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')), 2, 'Season 2', 'Reeling from the combined pressure of an ATF crackdown and an unprovoked murder, the Sons face a far more deadly threat from a cold-blooded enemy who wil stop at nothing to drive them out of Charming for good. As Jax and Clay square off over questions of leadership and loyalty, lines are drawn and chaos reigns as the club threatens to destroy itself—from the inside out.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 1, 'Albification', 'Donna''s death has the club divided, with Clay setting up a new gun deal with the IRA. Charming and SAMCRO ''s hold on the city is threatened after Ethan Zobelle a sophisticated separatist opens a tobacco shop. Zobelle and his less-sophisticated associate are determined to take SAMCRO down due to their black and Latino bikers.', 47, '2009-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 2, 'Small Tears', 'After Gemma experiences something horrible she can''t tell Jax and Clay. A rival porn producer comes to try and put Luanne out of business and Clay doesn''t like Jax''s decision making.', 43, '2009-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 3, 'Fix', 'Zobelle comes up with a problem that Hale can solve to frustrate SAMCRO. Meanwhile, Gemma being raped is really affecting her relationship with Clay and the fact that Jax is involved with Luanne''s porn business is bothering Tara. Clay decides to give Bobby the responsibility of running the business side of Luanne''s.', 41, '2009-09-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 4, 'Eureka', 'Tensions between Jax and Clay escalate when they disagree over strategy for rescuing Tig after he''s captured by bounty hunters on a gun-running mission. Back in Charming, Gemma is rattled by a graphic reminder of her attack, and she sets out to do something about it.', 43, '2009-09-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 5, 'Smite', 'While Jax and Clay lock horns (and line up support) over how to deal with Zobelle, Tara finds herself ensnared in Gemma''s emotional struggle in the aftermath of her attack. Meanwhile, SAMCRO gets help from an unlikely source.', 43, '2009-10-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 6, 'Falx Cerebri', 'Zoebelle incites Clay, who plans a course of retaliation, causing Jax to look to an unlikely source to keep the club from being destroyed. Tara learns from Gemma how an old lady handles anger.', 41, '2009-10-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 7, 'Gilead', 'Since The League has SAMCRO members behind bars, the club must make new alliances in prison to survive. Alcohol, Tobacco and Firearms Agent Stahl uses this imprisonment to test Jax and Clay''s relationship.', 44, '2009-10-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 8, 'Potlatch', 'Extreme measures are taken by SAMCRO to get a hold of weapons for a customer. A theft at Caracara Studios means revenge after one diva is put at risk. Tara''s professional and personal lives begin to collide.', 37, '2009-10-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 9, 'Fa Guan', 'When SAMCRO''s adult-film business becomes a hindrance to the club, Clay seizes the opportunity to revive the gun-running cartel. As Jax and Clay continue to clash over club activities, their relationship reaches a new level of antagonism.', 41, '2009-11-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 10, 'Balm', 'Agent Stahl (Ally Walker) takes notice at the handsome profits SAMCRO is reaping from the repo business. Meanwhile, the Jax- Clay standoff forces Gemma to make a difficult decision.', 54, '2009-11-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 11, 'Service', 'While Opie seeks both revenge and reconciliation, Chibs makes a secret deal with Agent Stahl (Ally Walker) to protect his wife and daughter.', 46, '2009-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 12, 'The Culling', 'Jax and Clay keep SAMCRO focused on their impending showdown with Zobelle''s group; thanks to Gemma, Tara improves her job security at the hospital; Weston finally discovers his boss''s intentions in Charming.', 42, '2009-11-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 2), 13, 'Na Trioblóidí', 'The second season ends with SAMCRO trying to get rid of Ethan Zobelle (Adam Arkin) and his cohorts once and for all.', 59, '2009-12-01');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')), 3, 'Season 3', 'This season begins with SAMCRO feeling powerless over Abel’s kidnapping, especially Jax, whose grief sends him into deeper turmoil over his future with the club. The search for Abel sends our guys to Ireland, where Jax faces not only the Irish Republican Army but an untold personal history as well. Meanwhile, still on the lam, Gemma is hit with unexpected news and risks her freedom to deal with it.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 3), 1, 'SO', 'The aftermath of Abel’s kidnapping has the Sons reeling - especially Jax, whose grief sends him into deeper turmoil over his future with the MC. Framed for murder, Gemma remains on the lam, and is hit with some unexpected news from her past.', 56, '2010-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 3), 2, 'Oiled', 'To get intel on Abel’s whereabouts, Jax and the club help a bounty hunter track down a skip. They also press a source for answers about the attack at Half-Sack’s wake - the MC way. Meanwhile, Gemma deals with her father’s dementia.', 42, '2010-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 3), 3, 'Caregiver', 'To secure weapons and raise money for Abel’s search, the club exploits its porn connections to entertain Henry Lin’s clients, which doesn’t sit well with Opie (Ryan Hurst). Jax’s decision to search for Abel in Canada gets derailed. When Gemma’s dad goes MIA, her prisoner makes plans to do the same.', 41, '2010-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 3), 4, 'Home', 'Jax and Clay head towards Canada after Jimmy provides misleading intel on Abel’s whereabouts. The rest of the club splits off to help Happy with a pharmaceutical favor in redneck territory. Gemma tries to put old family matters to rest.', 41, '2010-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 3), 5, 'Turning and Turning', 'To help Gemma, SAMCRO and Abel, Jax conspires with an unlikely source. Meanwhile, the MC puts Chucky undercover.', 44, '2010-10-05');
