INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 3), 13, 'NS', 'Both the ATF and the Russians prove obstacles as the club looks to heal old wounds.', 60, '2010-11-30');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')), 4, 'Season 4', 'This season begins with SAMCRO fresh out of jail and back into Charming. Upon their arrival, they encounter new law enforcement and head right back to business. The club is pressed with a decision that could challenge what SOA has always stood for and brings forth an unlikely alliance. Jax, fresh out of jail and dealing with the birth of his new-born son, is forced to put new plans into motion that could affect the club and ultimately his family. ');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1124373')) AND numero_temporada = 4), 1, 'Out', '14 months after going to prison on federal weapons charges Jax, Clay and the other SAMCRO members are released and return to Charming where they encounter new enemies in the form of a no nonsense sheriff and an Assistant U.S. Attorney out to nail the club for their dealings with Russian gunrunner Putlova. Also Jax makes a promise to Tara and Opie and Lyla get married.', 60, '2011-09-06');
