INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 2, 'Viking', 'To save the life of Freydis, Leif agrees to join Canute and Harald''s siege of London. Queen Emma dispatches stepson Edmund to secure an ally''s help.', 46, '2022-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 3, 'The Marshes', 'On a pilgrimage, Freydis and her party are savagely attacked. Harald and Leif seek a route through the marshes near London as Edmund is crowned king.', 46, '2022-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 4, 'The Bridge', 'Leif proposes an audacious assault on London, one that Emma and Godwin fear their brash and headstrong boy-king, Edmund, will be too reckless to defeat.', 45, '2022-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 5, 'Miracle', 'Schemes, betrayals and politics rule the day as a new monarch takes the throne of England. Leif is hailed as a hero but secretly questions his faith.', 60, '2022-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 6, 'The Last Daughter of Uppsala', 'Freydis returns to Kattegat and joins a sacred order. Canute solidifies his power in England. Kåre revisits the holy site of a childhood trauma.', 56, '2022-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 7, 'Choices', 'Olaf makes a pact with Kåre as Kattegat prepares for its defense. In Canute''s absence, his father, Sweyn Forkbeard, shares England''s throne with Edmund.', 54, '2022-02-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 1), 8, 'The End of the Beginning', 'Olaf and Kåre gather their forces to invade Kattegat. Palace intrigue over control of England''s throne results in an unexpected turn of events.', 49, '2022-02-25');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 1, 'The Web of Fate', 'Olaf lands in a terrible position after Forkbeard invades Kattegat. In hiding, Freydis and Harald must decide whether to fight for the throne or flee.', 55, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 2, 'Towers of Faith', 'Freydis finds a new home. Harald formulates a daring new plan to take back Norway, but Leif''s not on board. A new threat appears in London.', 50, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 3, 'Pieces of the Gods', 'While preparing for a journey to Constantinople, Harald assembles an unlikely crew, each with their own motives. Emma suspects Godwin of treachery.', 46, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 4, 'The Thaw', 'The travelers make a deadly miscalculation on the way to Constantinople. Olaf sets off after Harald, and Emma''s paranoia pushes her over the edge.', 43, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 5, 'Birth and Rebirth', 'Harald learns a devastating secret. The group encounters a dangerous stranger. Harekr reveals his true intentions for the future to Freydis in Jomsborg.', 49, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 6, 'Leap of Faith', 'Love blossoms on the ship as the crew makes a fateful decision, with Olaf hot on Harald''s heels. Jormundr stands trial. Canute makes Godwin an offer.', 53, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 7, 'Pecheneg', 'Harald makes a risky move and falls into the hands of the Pechenegs. Olaf sets out to find Jomsborg and stumbles upon an unlikely source of help.', 44, '2023-01-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 2), 8, 'The Reckoning', 'Leif says a painful goodbye. Harald''s new love is not what she seems. A key battle comes to an end, but the war to rule over Norway is just beginning.', 50, '2023-01-12');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')), 3, 'Season 3', 'Picking up up seven years after the conclusion of Season 2, Freydis is now the undisputed leader of pagan Jomsborg, and Leif and Harald have achieved glory in Constantinople. But greater challenges lie ahead in order for each to reach their ultimate destiny.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 1, 'Seven Years Later', 'Harald and Leif help Romanos lay siege at Syracuse. Canute travels to Rome to meet with the Pope. A new arrival in Jomsborg catches Freydis'' eye.', 44, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 2, 'Honour and Dishonour', 'Harald fights the Emir for control of Syracuse. Something causes the Jomsborg townsfolk to fall ill. Magnus Olafsson unexpectedly arrives in Kattegat.', 49, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 3, 'Lost', 'As the Byzantine army returns to Constantinople, Leif agonizes over the Syracuse horror. Magnus sails to Jomsborg as Freydis'' people begin to heal.', 44, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 4, 'The End of Jomsborg', 'Leif meets an unusual nun on his way to Corfu, Freydis devises a plan for Magnus'' imminent arrival and Harald''s indiscretion worries his friends.', 49, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 5, 'Greenland', 'Freydis reunites with her father, Erik the Red. Leif befriends mapmaker Calinicus, Canute returns to London and Harald gets caught in a bad situation.', 46, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 6, 'Return to Kattegat', 'Harald sacrifices everything to protect his friends, Canute gathers his sons in Kattegat and Erik tries to convince Freydis to stay in Greenland.', 44, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 7, 'Hardrada', 'Freydis confronts Erik over his schemes to make her stay, Canute declares a successor and Harald devises an escape plan.', 54, '2024-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11311302')) AND numero_temporada = 3), 8, 'Destinies', 'Emma prepares to defend the throne. Magnus and Harald vie to be King of Norway. Unbeknownst to each other, Leif and Freydis both return to Kattegat.', 58, '2024-07-11');
