INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 1, 'Ghost', 'Echo is one of the "Actives" in the elite and illegal Dollhouse. Through different personality downloads, she plays the role of a lovestruck girl on a romantic weekend, and then a ruthlessly efficient kidnapping negotiator. FBI Agent Paul Ballard is struggling with his assignment to uncover information on the Dollhouse.', 50, '2009-02-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 2, 'The Target', 'Echo becomes the female counterpart to an outdoorsman; Agent Ballard is encouraged when he receives a clue to Echo''s true identity.', 50, '2009-02-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 3, 'Stage Fright', 'Echo becomes a backup singer to watch out for a female singing sensation with a very overzealous fan. Agent Ballard''s investigation takes a turn for the worse.', 50, '2009-02-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 4, 'Gray Hour', 'Echo becomes an expert safe-cracker, and an invaluable piece of art is stolen from her on the engagement, forcing Sierra to take on a familiar persona. Agent Ballard gives Lubov an ultimatum, and Adelle confides shocking information to Topher.', 50, '2009-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 5, 'True Believer', 'Imprinted as a visually impaired woman, Echo must infiltrate a heavily guarded cult in order to rescue a woman held against her will.', 50, '2009-03-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 6, 'Man on the Street', 'Echo becomes the perfect wife for a lonely internet mogul, and Sierra''s attacker is revealed. Meanwhile, Mellie''s life is in danger and Agent Ballard''s investigation takes a surprising turn when he comes face-to-face and goes fist-to-fist with Echo for the first very time.', 50, '2009-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 7, 'Echoes', 'A deadly virus outbreak on a college campus sends Echo back to school where pieces of her past come into focus.', 50, '2009-03-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 8, 'Needs', 'When Echo, Sierra and Victor awaken in the Dollhouse with most of their original personalities and memories intact, Echo leads the charge to free the Actives from their apparent captivity and escape the Dollhouse forever. Meanwhile, Ballard discovers the Dollhouse is closer than he thinks.', 50, '2009-04-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 9, 'A Spy in the House of Love', 'When a traitor is discovered inside the Dollhouse, Echo and Sierra are programmed as spy hunters to uncover the culprit. Meanwhile, Ballard receives surprising news from Mellie, and Adelle harbors a secret.', 50, '2009-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 10, 'Haunted', 'When Adelle’s wealthy friend is murdered, Adelle imprints Echo with the woman’s memories and personality to solve the case. Ballard looks into Mellie’s past, and Topher secretly programs Sierra for an engagement.', 50, '2009-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 11, 'Briar Rose', 'Ballard’s investigation leads him to the agoraphobic designer of the Dollhouse (guest star Alan Tudyk), and the story of “Sleeping Beauty” foreshadows Echo’s future, while allowing her to help a young girl deal with her traumatic past. Adelle goes to the attic in search of answers, while Alpha reveals himself and sets his game in motion.', 49, '2009-05-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 1), 12, 'Omega', 'Alpha’s reign of terror continues as his obsession with Echo endangers Caroline’s survival. Ballard’s search for the Dollhouse comes to an end, forcing him to make a life-changing decision. Meanwhile, one Doll is permanently deactivated while another’s shocking past is revealed.', 50, '2009-05-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')), 2, 'Season 2', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 1, 'Vows', 'It has been several months since Alpha''s reign of terror and Echo, who is now randomly picking up flashes of past engagements, weds a British businessman who has ties to one of Ballard''s open FBI cases. Topher becomes the target of Dr. Saunder''s aggression after she finds out that she is actually a doll named Whiskey. Boyd takes on a risky venture and mixes business with pleasure, while DeWitt makes Ballard an irresistible offer.', 44, '2009-09-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 2, 'Instinct', 'Echo is imprinted with the personality of a mother with a newborn baby. Complications arise when, thanks to Topher''s programming, Echo takes too strongly to motherhood. Perrin ramps up his investigation into Rossum and DeWitt pays November a visit.', 44, '2009-10-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 3, 'Belle Chose', 'Echo and Victor’s imprints collide when Echo is sent on an assignment as a fun-loving, seductive college student and Victor is imprinted as the psychotic nephew of a Dollhouse shareholder.', 44, '2009-10-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 4, 'Belonging', 'Sierra is forced to face her past as her connection to the Rossum Corporation leads to obsession and murder.', 44, '2009-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 5, 'The Public Eye (1)', 'When Senator Perrin makes his stand against the Rossum Corporation, Echo attempts to stop his expose. Adelle, and Topher begin to see what they are up against in the rival of Washington DC.', 43, '2009-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 6, 'The Left Hand (2)', 'Echo and Bennett have a shocking meeting as Adelle goes head-to-head with the ruthless head of the DC Dollhouse. Topher sees double when he must involve Victor in his espionage. Perrin finds a surprising witness to testify against the Rossum Corporation, but find he may be living in a house of cards.', 44, '2009-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 7, 'Meet Jane Doe', 'After her entanglements with Senator Perrin and the DC Dollhouse, Echo finds herself out in the world-at-large as she struggles to control her multiple memory downloads. Topher discovers the dangers of science that will have devastating effects on the future, while Adelle engages in a power struggle with Harding.', 44, '2009-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 8, 'A Love Supreme', 'When Echo''s past romantic engagements are found murdered, the Dollhouse fears that Alpha has returned to seek his revenge. Adelle grows suspicious of Ballard who hopes to find allies in Boyd and Topher. The Actives turn against their handlers, leaving one member of the house permanently mind-wiped.', 44, '2009-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 9, 'Stop-Loss', 'As his contract with the Dollhouse expires, Victor is released back into the world, where his military past threatens his future with Sierra. Meanwhile, Echo is deemed too dangerous and is sent into her worst nightmare.', 44, '2009-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 10, 'The Attic', 'When Adelle, Boyd, and the rest of the Dollhouse fear that Echo''s uncontrollable mind imprints are making her a danger to their goals, they send her to "the Attic" where Echo is forced to face her worst nightmare in order to survive.', 44, '2009-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 11, 'Getting Closer', 'Topher races to reconstruct Echo''s original personality and memories when Adelle realizes they are the key to averting a devastating future. Meanwhile, Echo and Bennett''s shared past and the identity of The Rossum Corporation''s mysterious leader are revealed.', 44, '2010-01-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 12, 'The Hollow Men', 'Sacrifices are made when Echo leads her crew to Arizona to dismantle the Rossum Corporation''s mainframe.', 44, '2010-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1135300')) AND numero_temporada = 2), 13, 'Epitaph Two: Return', 'In the year 2020, Echo and her surviving Dollhouse crew attempt to restore order to a devastating future world before mankind is eliminated.', 44, '2010-01-29');
