INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt1132290', 'Warehouse 13', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm1084723'), 'SERIE', 'Pete and Myka, U.S Secret Service agents, are deployed in South Dakota''s Warehouse 13 with a new assignment from an authority above and outside the government.', '2009-01-01', 'https://m.media-amazon.com/images/M/MV5BMDVjOGI3MDEtYTQzYi00N2IxLTlkMGItM2UwMTIzZTcxYjY5XkEyXkFqcGc@._V1_.jpg');
