INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')), 1, 'Season 1', 'The first season of the American television series Warehouse 13 premiered on July 7, 2009, and concluded on September 22, 2009, on Syfy. The show aired on Tuesdays at 9:00 pm ET. The season consisted of 12 episodes. The show stars Eddie McClintock, Joanne Kelly, Saul Rubinek, Genelle Williams and Simon Reynolds.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 1, 'Pilot', 'Secret Service agents Lattimer and Bering are "rewarded" with a transfer to the top-secret Warehouse 13. They meet Artie Nielsen, the caretaker of the mysterious warehouse, who tells them about their new job. The agents are responsible for the collection of every supernatural and unexplained item that the U.S. Government has ever collected. For their first assignment, they are sent to Iowa to investigate a possible artifact belonging to a college student who went berserk and assaulted his girlfriend while chanting an Italian incantation.', 88, '2009-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 2, 'Resonance', 'Pete and Myka are after a team of bank robbers who have a distinctive weapon. Meanwhile, Artie examines the security breach at the warehouse.', 44, '2009-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 3, 'Magnetism', 'Pete and Myka are sent to investigate a town where the inhabitants'' minds are being altered making them act as they please. Meanwhile, Artie is confused by the energy flows going on in the warehouse.', 44, '2009-07-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 4, 'Claudia', 'A woman kidnaps Artie and insists that he help her recover her brother... who was lost in an artifact-related experiment 12 years ago.', 44, '2009-07-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 5, 'Elements', 'The theft of a sculpture leads Myka and Pete to a sacred Indian cave holding an ancient secret of creation... and destruction.', 44, '2009-08-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 6, 'Burnout', 'Pete and Myka take on a previous agent''s assignment after the man''s corpse turns up in the basement of a St. Louis police station.', 44, '2009-08-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 7, 'Implosion', 'Pete and Myka return to Washington to intercept a samurai sword that is to be presented to the president, and they discover a competitor for items that belong to the warehouse.', 44, '2009-08-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 8, 'Duped', 'Pete and Myka go to Las Vegas to fetch an artifact that is helping a couple of gamblers, but the mission goes awry when Myka becomes trapped in a famous author''s mirror.', 44, '2009-08-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 9, 'Regrets', 'Pete and Myka visit a Florida prison to probe a spate of unexplained suicides. Meanwhile, Claudia changes a light bulb with the help of an artifact.', 44, '2009-09-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 10, 'Breakdown', 'Artie gets questioned by the Regents and Mrs. Frederic. Meanwhile, Pete, Myka and Claudia become trapped inside Warehouse 13, where a dangerous predicament unfolds.', 44, '2009-09-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 11, 'Nevermore', 'After receiving word that her father is dying, Myka travels home to see her parents.', 43, '2009-09-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 1), 12, 'MacPherson', 'The team discovers that MacPherson is auctioning artifacts he has siphoned from the Warehouse shelves.', 44, '2009-09-22');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')), 2, 'Season 2', 'The second season of the American television series Warehouse 13 premiered on July 6, 2010, and concluded on December 7, 2010, on Syfy. Season two maintained the Tuesdays at 9:00 pm ET timeslot from the previous season. The season consisted of 13 episodes. The show stars Eddie McClintock, Joanne Kelly, Saul Rubinek, Genelle Williams and Allison Scagliotti.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 1, 'Time Will Tell', 'In the season two premiere, we pick up right where we left off. MacPherson has blown Artie to smithereens, and disappeared. Is Leena really a traitor? Where has Claudia gone? How will Pete, Myka and the Warehouse fare without Artie? What other havoc did MacPherson wreak when he was alone in the Warehouse? And is there yet a new villain on the horizon?', 44, '2010-07-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 2, 'Mild Mannered', 'A super-powered vigilante is at large in Detroit, and the agents try to track down the person responsible. Meanwhile, things between Leena and Claudia are still tense, and Artie is haunted by the spirit of his dead friend.', 44, '2010-07-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 3, 'Beyond Our Control', 'When an artifact meant for the Warehouse turns up in the small town next door, the team finds themselves in the middle of a B-movie meltdown complete with cowboys, gladiators, sci-fi robots and beach storming marines. Their only chance of survival rests with the man who invented television, Philo T. Farnsworth.', 44, '2010-07-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 4, 'Age Before Beauty', 'When young super models rapidly age 50 years overnight, Pete and Myka go undercover in the glam world of high fashion to discover who – and what – is behind the transformations.', 44, '2010-07-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 5, '13.1', 'Douglas Fargo of Eureka''s Global Dynamics is sent to Warehouse 13 to help update its aging computer system. This triggers a seemingly sentient computer virus that sends the Warehouse into lockdown and traps the team inside.', 43, '2010-08-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 6, 'Around the Bend', 'Mrs. Frederick secretly recruits Pete to find a mole within the organization who is buying artifacts. However, when the mole finds out, they go after those closest to Pete.', 44, '2010-08-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 7, 'For the Team', 'Claudia has just been given her first assignment, but when it involves a real human torch and H.G. Wells could it be too much for her to handle? Not to mention an appearance by an old love of Artie''s', 44, '2010-08-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 8, 'Merge with Caution', 'The agents hope to spend a weekend relaxing until an artifact gets in the way.', 44, '2010-08-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 9, 'Vendetta', 'Someone is using Artie''s artifacts to commit a series of murders.', 44, '2010-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 10, 'Where and When', 'Pete and Myka use H.G. Wells''s time machine to travel back to 1961.', 43, '2010-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 11, 'Buried (1)', 'When Mrs. Frederic is stricken ill, the agents must search for a cure before it''s too late. Their quest takes them to Egypt and the long-lost Warehouse 2.', 44, '2010-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 12, 'Reset (2)', 'The team tries to track down their rogue member, and discover the artifact they have is unexpectedly powerful. Meanwhile, Claudia wonders about her future with the Warehouse team and Pete must choose between Kelly and the mission.', 44, '2010-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 2), 13, 'Secret Santa', 'As the Warehouse team prepares to celebrate the holidays in snowy South Dakota, Pete and Myka are called upon to hunt down a malevolent Santa Claus. Meanwhile, in time for Hanukkah, Artie and his estranged father, Isadore Weisfelt reunite after 30 years.', 44, '2010-12-07');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')), 3, 'Season 3', 'The third season of the American television series Warehouse 13 premiered on July 11, 2011, on Syfy. The season consists of 13 episodes. The show stars Eddie McClintock, Joanne Kelly, Saul Rubinek, and Allison Scagliotti and Genelle Williams.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 1, 'The New Guy', 'When we last left agents Myka Bering and Pete Lattimer at the conclusion of season 2, Myka had decided to leave the top secret team with little to no warning. As season 3 begins, Artie fills Myka''s shoes with ''The New Guy,'' which also happens to be the name of the season premiere episode.', 44, '2011-07-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 2, 'Trials', 'While Pete and Myka go after someone using an artifact to induce Alzheimer''s, Claudia goes on her first case as a full agent with Steve to track down Typhoid Mary''s knife.', 43, '2011-07-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 3, 'Love Sick', 'While Artie and Claudia meet with Vanessa Calder and Hugo Miller to investigate a computer virus that transforms people into clay, Myka and Pete wake up naked in bed and try to find a missing Steve.', 43, '2011-07-25');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 4, 'Queen for a Day', 'Pete''s ex-wife arrives in town to remarry, but an artifact may derail the wedding. Steve and Claudia visit a Civil War reenactment in search of an artifact', 43, '2011-08-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 5, '3...2...1...', 'When a series of mysterious disintegration deaths occur in Pittsburgh, the team discovers that the artifact responsible, Joshua''s Horn, has ties to Helena''s time as an agent in 1893.', 43, '2011-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 6, 'Don''t Hate the Player', 'Pete, Claudia, and Myka are called in to help Fargo, who is trapped in a virtual reality swords & sorcery game. Meanwhile, Artie and Steve are summoned to New York to recover an artifact... by FBI agent Sally Stukowski.', 43, '2011-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 7, 'Past Imperfect', 'While in Denver, Myka picks up the trail of the counterfeiter who killed her former partner, Sam Martino. Meanwhile, Artie, Claudia, and Steve interrogate a dog that witnessed the theft of an artifact.', 43, '2011-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 8, 'The 40th Floor', 'Sally Stukowski and her partner make their move, attacking the Regents and using an artifact to trap them in a building and bring it down around them.', 43, '2011-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 9, 'Shadows', 'While Pete and his mother Jane try to determine the origins of their mysterious opponents, Myka and Claudia travel to Portland to stop a girl who can apparently vaporize anyone she hates with blasts of radiation.', 43, '2011-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 10, 'Insatiable', 'Myka and Pete deal with a plague of zombies in Ithaca, while Claudia deals with a new romance, a prophecy of death, and a rejection from a friend.', 43, '2011-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 11, 'Emily Lake (1)', 'As Sykes begins his end game, the agents discover that Helena is still alive... and teaching high school literature. Meanwhile, Jane reveals the full extent of her plan but one agent will lose their life carrying it out.', 43, '2011-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 12, 'Stand (2)', 'Pete and Myka race to stop Sykes from using his own cache of artifacts to destroy them and the Warehouse.', 43, '2011-10-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 3), 13, 'The Greatest Gift', 'Pete Lattimer is hit in the head by an artifact and wakes up to a life where he was never born. Pete must hunt down and persuade the Warehouse team (none of whom recognize him) to go on this life or death mission with him to vanquish a long dead nemesis from the past to get everyone’s lives back.', 43, '2011-12-06');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')), 4, 'Season 4', 'The fourth season of the American television series Warehouse 13 premiered on July 23, 2012 on Syfy. The season consists of 20 episodes. The show stars Eddie McClintock, Joanne Kelly, Saul Rubinek, Genelle Williams,  Allison Scagliotti, and Aaron Ashmore.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 1, 'A New Hope', 'In the aftermath of the warehouse''s destruction, the Warehouse team races against the clock to find a way to undo time itself and put right what went wrong. However, Artie finds himself facing a difficult decision when he is warned that saving the warehouse will unleash an even greater evil.', 43, '2012-07-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 2, 'An Evil Within', 'While Claudia tries to help a friend and gets unexpected help, Pete and Myka investigate an artifact that causes crowds to see certain individuals as monsters... and attack them.', 43, '2012-07-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 3, 'Personal Effects', 'A cache of Walter Skyes'' stolen artifacts turn up and all six agents go into the field to recover them. Artie unexpectedly reveals his secret to Leena, while Steve begins to realize the downside of the metronome that brought him back to life.', 43, '2012-08-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 4, 'There''s Always a Downside', 'While Pete and Claudia help Hugo Miller track down a bag of marbles at a boy''s academy, Myka and Steve travel to New Orleans on the trail of another artifact while Artie meets with Brother Adrian.', 43, '2012-08-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 5, 'No Pain, No Gain', 'While Pete and Myka go to Toronto to investigate an invulnerable hockey player, Steve helps Artie track down stolen artifacts while Claudia meets with Mrs. Fredericks to discuss her future as a warehouse guardian.', 43, '2012-08-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 6, 'Fractures', 'The Brotherhood continues its assault on Artie''s life, targeting someone close to him with Alice Liddell, the imprisoned spirit within the Dodgson Mirror. Meanwhile, Claudia learns of the connection between her and Steven.', 43, '2012-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 7, 'Endless Wonder', 'While Pete and Myka investigate a series of artifact-related growth spurts, Artie reluctantly takes Steve and Claudia with him to track down Brother Adrian before he can steal more artifacts from the warehouse.', 43, '2012-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 8, 'Second Chance', 'While Pete and Myka travel to West Virginia to investigate a rust-like infection among steelworkers, Steven and Claudia go to Steven''s home to find a way to break the metronome''s hold on him. Meanwhile, Helena, Leena, and Mrs. Frederic confront Artie with their knowledge of what he has done.', 43, '2012-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 9, 'The Ones You Love', 'Pete, Myka, and Claudia set off to rescue their loved ones when Brother Adrian sends them deadly artifacts. Meanwhile, Mrs. Frederic and Steve travel to Rome and learn Adrian''s dark secret.', 43, '2012-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 10, 'We All Fall Down', 'The team have no time to mourn a fallen comrade as they go after the person responsible, the nemesis that has been stalking Artie since he used Magellan''s Astrolabe to save the world.', 43, '2012-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 11, 'The Living and the Dead', 'With the fate of the world in their hands, Pete and Myka''s only hope of finding a cure to the Sweating Sickness is a drunken history professor. Meanwhile, Steven and Claudia enter Artie''s subconscious in an attempt to bring him out of his coma before he fades away for good.', 43, '2013-04-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 12, 'Parks and Rehabilitation', 'While Pete and Claudia travel to Oregon to look for an artifact used to kill enemies of the environmental movement, Artie deals with the repercussions of Leena''s death.', 43, '2013-05-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 13, 'The Big Snag', 'A mishap with an artifact traps Pete and Myka in a fictional 1940s world where they have to solve a murder to escape... but someone doesn''t want them to. Meanwhile, Claudia and Steven convince Artie to go along with them to investigate reports of stolen cars, and Artie starts taking dangerous risks.', 43, '2013-05-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 14, 'The Sky''s the Limit', 'While Pete and Myka travel to Las Vegas to investigate two deaths where the people inexplicably fell from great heights, Claudia and Steven investigate two jockeys in London who went into comas after winning their races. Meanwhile, Artie gets a visitor to the warehouse.', 43, '2013-05-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 15, 'Instinct', 'H.G. has created a new life for herself in Wisconsin, but calls in the agents when she comes up against an unidentified artifact. Meanwhile, Abigail joins the others on the floor of the warehouse to track down the source of mysterious tremors that threaten to destroy the building.', 43, '2013-06-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 16, 'Runaway', 'Pete, Myka, and Steven team up with a U.S. Marshal to track down two prisoners who used a lava-spewing artifact to escape prison. However, they discover that the Marshal is Steve''s ex. Meanwhile, Artie and Claudia try to track down part of an artifact that is rendering Artie deaf...', 43, '2013-06-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 17, 'What Matters Most', 'Someone in a gated community is using an artifact to extract vengeance and Myka and Pete go to investigate. Meanwhile, Artie and Claudia help a teen suffering from dangerous visions, and Steven and Abigail clean up the warehouse.', 43, '2013-06-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 18, 'Lost & Found', 'The agents track down a cache of artifacts stolen from Warehouse 12 by the infamous Roaring Dan Seavey... and guarded by his ghost. Meanwhile, Charlotte Dupres makes her move with the help of her inside person.', 43, '2013-06-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 19, 'All the Time in the World', 'Pete, Myka, and Charlotte must track down Sutton, the only man who knows where they can find Paracelsus and exchange the Philosopher''s Stone for the stele that will free Claudia from her bronze imprisonment... before she disintegrates.', 43, '2013-07-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 4), 20, 'The Truth Hurts', 'Pete and Myka capture Paracelsus but not before he makes himself immortal. When Myka''s cancer becomes worse, Pete must make a deal with Paracelsus to cure his partner. Meanwhile, Claudia receives some startling news from Artie.', 43, '2013-07-08');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')), 5, 'Season 5', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 5), 1, 'Endless Terror', 'When Paracelsus takes control of Warehouse 13, it proves to only be the first step in his plan to recreate the entire world in his image. To stop him, Pete and Myka must follow him back through time to 1541 and prevent him from killing the Regents and becoming the permanent master of the Warehouses.', 43, '2014-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 5), 2, 'Secret Services', 'While Pete and Myka team up with two former Secret Service co-workers to investigate a series of bizarre deaths in Washington DC, Artie agrees to show Claudia how and why her sister had to disappear.', 43, '2014-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 5), 3, 'A Faire to Remember', 'While Pete and Steven check out a life-threatening incident at a renaissance faire, Myka agrees to help Claudia revive her comatose sister. However, they discover that doing so has unexpected consequences that threaten the warehouse and everyone in it.', 43, '2014-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 5), 4, 'Savage Seduction', 'Pete''s former girlfriend Kelly Hernandez asks him to help her find her missing grandmother, and the trail leads into a cancelled telenovela. Meanwhile, Artie forces Claudia to go with Steve to investigate the case of a college student of whose spine broke in the middle of a classroom presentation.', 43, '2014-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 5), 5, 'Cangku Shisi', 'The alternate-timeline Valda makes his move, using Claire as his mindless slave. As Valda sets out to move Warehouse 13 to a new location that he can control, the team races desperately to stop him before it''s too late.', 43, '2014-05-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt1132290')) AND numero_temporada = 5), 6, 'Endless', 'While the team deals with the news that Warehouse 13 is moving, Mrs. Frederic has them load their greatest memories of their missions into an artifact for future generations.', 43, '2014-05-19');
