INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11514868')) AND numero_temporada = 1), 3, 'The Perfect Family', 'Greer works to keep up appearances for a magazine interview. Abby shares a scandalous secret. Amelia says the quiet part out loud during a family dinner.', 50, '2024-09-05');
