INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 1, 'Pilot', 'Samantha and Jay throw both caution and money to the wind when they decide to convert a rundown country estate they inherited into a bed & breakfast – only to find it’s inhabited by the many opinionated spirits of deceased residents who now call it home.', 23, '2021-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 2, 'Hello!', 'When Sam thinks she’s crazy because she continues to see the ghosts of Woodstone Manor, she tries to ignore them, making them even more determined to get her to acknowledge they’re real.', 22, '2021-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 3, 'Viking Funeral', 'When Thorfinn’s bones are discovered on the Woodstone property, he asks Sam to conduct the traditional Viking funeral he’s always wanted. However, Sam and Jay are torn when they learn that the bones could be sold to a museum for a lot of much-needed cash. Also, the ghosts conduct an election for a “ghost representative” to bring issues to Sam.', 22, '2021-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 4, 'Dinner Party', 'When Sam and Jay invite the nosy neighbors Henry and Margaret to a dinner party to woo them into allowing the bed and breakfast, the ghosts are desperately eager to be included on the guest list.', 22, '2021-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 5, 'Halloween', 'On Halloween at Woodstone Mansion, the ghosts try to help Sam and Jay protect their home from the neighborhood kids who annually vandalize the house.', 20, '2021-10-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 6, 'Pete''s Wife', 'Pete convinces Sam to invite his living wife to the mansion, only to discover she’s been keeping a dark secret from him for many years. Also, Sassapis gets angry with Thorfinn for binge-cheating their favorite show without him, and Trevor learns he may have a daughter.', 22, '2021-11-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 7, 'Flower''s Article', 'When Sam is commissioned to write an article about Flower and her friends holding up a bank during their commune days, Flower begs Sam not to accept the job because she’s embarrassed about a part of the story she’s never revealed.', 21, '2021-11-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 8, 'D&D', 'After Jay is kicked out of a Dungeons & Dragons campaign with his city friends, Sam agrees to facilitate a new one between him and the ghosts. Also, Isaac confronts his feelings for Nigel, a British soldier ghost from whom he’s been keeping a gigantic secret.', 22, '2021-11-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 9, 'Alberta''s Fan', 'Alberta is thrilled when a super-fan of her music visits the mansion to learn more about her. Also, Thor convinces Hetty to go on a walk with him in hopes that it will spark a special memory.', 22, '2021-12-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 10, 'Possession', 'Hetty accidentally possesses Jay’s body just as he and Sam are to about show Woodstone Mansion to a renowned wedding planner', 22, '2021-12-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 11, 'Sam''s Mom', 'Sam and Jay travel to where Sam’s mother, Sheryl, died to see if she’s now a ghost. Also, Sasappis divulges a secret to his fellow ghosts that he overheard Sam and Jay discussing.', 22, '2022-01-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 12, 'Jay''s Sister', 'When Jay’s sister, Bela, comes to visit Sam and Jay after being dumped by her boyfriend, they’re shocked to discover that she’s communicating with someone they know on a dating app.', 22, '2022-01-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 13, 'The Vault', 'Just as Sam and Jay are set to host a friend’s wedding that could get their B&B business off the ground, the ghost of Hetty’s husband, Elias Woodstone, tries to ruin it.', 21, '2022-01-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 14, 'Ghostwriter', 'When Sasappis offers to help Sam complete the B&B website so they can start taking reservations, they butt heads over the creative direction. Also, Pete bonds with Jay over basketball until Jay makes a new living friend, and Flower attempts to be Pete’s new basketball buddy.', 22, '2022-02-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 15, 'Thorapy', 'When Sam and Jay have the ghosts bunk together to free up rooms for guests at the B&B, they learn that Thorfinn has been having night terrors, which inspires Sam to enlist a therapist to help him. Also, Isaac makes a big, personal revelation after he’s compelled to seduce his new roommate, Hetty.', 22, '2022-03-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 16, 'Trevor''s Pants', 'The secret about Trevor’s missing pants is finally revealed when his wealthy former friend comes to Woodstone Mansion to buy the timepiece Sam and Jay found on Elias Woodstone’s corpse. Also, Thor decides to tell Flower how he feels about her.', 22, '2022-03-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 17, 'Attic Girl', 'An ‘80s “mean girl” ghost named Stephanie, who died on her prom night, is awakened in the attic, triggering Sam to confront what happened on her own prom night. Also, Alberta discovers she has another special gift.', 22, '2022-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 1), 18, 'Farnsby & B', 'As Sam and Jay await the arrival of their first official B&B guests, they face obstacles triggered by a Norse curse placed upon them by Thorfinn. Also, Isaac takes a huge, centuries-in-the-making step in his personal life.', 21, '2022-04-21');
