INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 2), 1, 'Spies', 'Sam enlists the Ghosts to help secure a good review from an overly critical couple staying at the B&B. Also, Isaac tries to integrate Nigel into his friend group.', 22, '2022-09-29');
