INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 4), 15, 'The Bachelorette Party', 'When Alberta''s descendant hosts a bachelorette party at Woodstone Mansion, Alberta becomes suspicious of her fiancé; Jay is excited about a positive review on his restaurant.', 21, '2025-03-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 4), 16, 'St. Hetty''s Day', 'Hetty''s ghost power is revealed when Jay''s cousin Sunil visits Woodstone Mansion on St. Patrick''s Day.', 22, '2025-03-13');
