INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 4), 18, 'Smooching and Smushing', 'Jay, Sam and the ghosts attempt to fix the ghost trap in hopes of getting Sasappis across the ghost boundary to visit his longtime crush, Shiki.', 22, '2025-04-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 4), 19, 'Pinkus Returns', 'When Trevor''s former co-worker Pinkus and his daughter Abby show up at Woodstone Mansion, Trevor gets the surprise of his afterlife.', 22, '2025-04-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 4), 20, 'I Know What You Did Thirty-Seven Summers Ago', 'When Sam and Jay host a fundraiser for the mayor to earn a favor for Jay''s restaurant, they learn of his bizarre connection to one of Woodstone''s ghosts.', 22, '2025-04-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 4), 21, 'Kyle', 'Sam and Jay''s relationship is tested when Kyle, a handsome living who shares Sam''s ability to see ghosts, arrives at Woodstone B&B.', 21, '2025-05-01');
