INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 1, 'Soul Custody', 'Sam, Jay and the ghosts attempt to extricate Jay from his deal with Elias Woodstone, the devil. Also, Isaac helps Patience through a crisis of confidence and Pete and Alberta navigate the fallout from their kiss.', 22, '2025-10-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 2, 'Viking Wedding', 'Sam and Jay try to impress their trendy city friends while a misplaced bookcase threatens Thor''s ability to deliver an important speech. Also, Isaac rallies the ghosts to help the couple navigate a tough customer service ordeal.', 22, '2025-10-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 3, 'Halloween 5: The Mummy', 'Sam and Jay''s Halloween takes a spooky turn when they accidentally unleash a mummy ghost.', 22, '2025-10-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 4, 'Bring Your Daughter to Work Day', 'Trevor finds a way to spend more time with his newly discovered daughter, Abby, by getting her at job at Jay''s restaurant.', 22, '2025-11-06');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 5, 'T-Daddy', 'Trevor''s relationship with his daughter is strained when he pushes her to follow a career in finance over poetry. Meanwhile, Jay confronts labor unrest at the restaurant.', 22, '2025-11-13');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 6, 'Planes, Shanes, and Automobiles', 'Sam and Pete get on each other''s nerves during a book tour road trip and things reach a breaking point when an airline strike threatens their ability to get home in time for Thanksgiving.', 22, '2025-11-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 7, 'The Proposal', 'Sam helps Eric plan the perfect proposal for Bela, until an encounter with Sasappis plants doubt in Bela''s mind. Meanwhile, Isaac tries to prove he''s "just one of the basement ghosts".', 22, '2025-12-04');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 8, 'The Life and Times of Esther Greene', 'Now a successful podcaster, Todd Pearlman returns to profile Sam and Isaac''s book, but becomes obsessed with Jay. Meanwhile, Pete tries to get to the bottom of why Alberta changed her name, forcing her to admit a hidden truth.', 22, '2025-12-11');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 9, 'It’s A Wonderful Christmas Carol (1)', 'Sam’s big Christmas Eve TV interview with Walter Storm takes an unexpected turn. Meanwhile, Trevor and Patience bond over their mutual disinterest in celebrating Christmas.', 21, '2025-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 10, 'It’s A Wonderful Christmas Carol (2)', 'Sam gets a glimpse of what her life would be like if she could never see the ghosts.', 21, '2025-12-18');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 11, 'The Others', 'Sam and the ghosts face The Others, a new group of spirits from one ghost''s past. Meanwhile, Trevor tries to deal with a demanding Patience, who seeks a committed relationship in the wake of their holiday hookup.', 21, '2026-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 12, 'The List', 'Sam and Jay work to secure Woodstone B&B a coveted spot on a prestigious luxury hotel list, only to face unexpected chaos when a vengeful newly discovered bunker ghost disrupts a crucial visit. Meanwhile, Flower and Thor clash over who gets to call the shots in their relationship.', 21, '2026-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 13, 'St. Hetty''s Day 2: The Help', 'A St. Patrick''s Day staffing emergency gives Hetty the chance to step into an unlikely role at the restaurant as she regains her once-a-year ability to be seen and heard by the living. Meanwhile, Kyle returns to watch over the ghosts and finds himself caught in an amusing supernatural dynamic.', 21, '2026-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 14, 'The Water Heater', 'Sam and Jay try to replace their broken water heater, but Isaac turns the upgrade into a campaign issue in his bid to represent the basement ghosts. Meanwhile, Kyle attempts to make Bela jealous by pretending he’s dating Hetty.', 21, '2026-04-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 15, 'Michael Jackson Goes to HR', 'Trevor lands himself in trouble when an inappropriate gift to a co‑worker forces him into an HR meeting only Jay can handle. Meanwhile, Pete unintentionally sparks drama with Alberta after casually mentioning a surprise visit to his ex.', 21, '2026-04-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 16, 'Woodstone Royale', 'Needing to raise a large sum of money to pay the IRS, Sam and Jay agree to host a high-stakes poker game at the mansion. Meanwhile, in an act of generosity, Isaac gifts Jay''s recliner to the basement ghosts.', 21, '2026-04-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 17, 'The Investor', 'When a promising opportunity to save Woodstone is threatened by a personal conflict, Sam and Jay are forced into a difficult choice. Meanwhile, election day arrives as Flower and Isaac go head‑to‑head to become Ghost Representative.', 0, '2026-04-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 18, 'Under New Management', 'When new pressures threaten Sam and Jay''s control over Woodstone, they''re forced to navigate unexpected challenges to protect its future. Meanwhile, a long-absent ghost returns, reopening emotional connections that complicate new relationships.', 0, '2026-04-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 19, 'Gate-gate', 'When an emotion‑driven decision puts Woodstone at risk, Sam and Jay step up to defend what they''ve built. Meanwhile, Isaac struggles to adjust to new surroundings, only to realize that some connections are too important to leave behind.', 0, '2026-05-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 20, 'Polar Opposites', NULL, 0, '2026-05-14');
