INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11379026')) AND numero_temporada = 5), 22, 'Across The Pond (2)', 'A trip abroad could determine Woodstone''s fate. Meanwhile, a major career opportunity takes Sam out of town, leaving others to step in and help with the ghosts.', 0, '2026-05-21');
