INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 1, 'The Void', 'Wyoming rancher Royal Abbott discovers an unfathomable mystery at the edge of his property, setting in motion a catastrophic chain of events.', 58, '2022-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 2, 'The Land', 'The Abbott family frantically conspires to cover up their crimes but can’t piece together what has happened to Royal.', 44, '2022-04-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 3, 'The Time', 'The investigation for the missing Tillerson brother forces Royal to ally with Autumn, until Amy makes an improbable discovery.', 47, '2022-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 4, 'The Loss', 'As word spreads about the Tillerson murder, Sheriff Joy interrogates the Abbotts, forcing Royal to wager far more than he can afford to lose.', 63, '2022-04-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 5, 'The Soil', 'Royal embarks on a quest to investigate the elusive dark mineral that is present on his land, only to intensify his growing rivalry with Autumn.', 42, '2022-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 6, 'The Family', 'With family ties beginning to fray, Royal takes violent measures to get rid of Autumn, but is foiled when he discovers she has manipulated someone close to him.', 42, '2022-04-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 7, 'The Unknown', 'As the Tillersons close in on the Abbott’s secrets, Royal must salvage what is left of his family and livelihood. Autumn orchestrates the unthinkable.', 51, '2022-05-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 1), 8, 'The West', 'The Abbott family faces a grand reckoning over the course of a single day as the showdown between Royal and Autumn culminates, unearthing a shattering revelation.', 55, '2022-05-05');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')), 2, 'Season 2', 'The mystery surrounding the enigmatic void on the west pasture of the Abbott family ranch deepens in Season Two, as Royal and his wife Cecelia struggle to keep their family together in the aftermath of their granddaughter’s sudden disappearance. The stakes have never been higher for the Abbotts, who now face threats on multiple fronts.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 1, 'One Night in Wabang', 'In the aftermath of the bison stampede, the Abbott family is more fractured than ever. Royal and Cecilia confront some difficult truths as they fight to keep their family together.', 59, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 2, 'Traces to Somewhere', 'Perry seeks help from an unexpected family member. The Tillersons promise revenge against the Abbotts, while Royal contends with a new threat to the West Pasture.', 53, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 3, 'Everybody Hurts', 'Royal and Cecelia become desperate in their attempt to save their ranch. The Tillerson’s are dealt with a startling turn of events.', 62, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 4, 'Ode to Joy', 'Lost in time with no way home, Sheriff Joy must navigate a new life among her Shoshone ancestors.', 51, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 5, 'All the World''s a Stage', 'Royal rediscovers an unlikely ally; Cecilia grapples with the possibility of Autumn’s identity as Autumn becomes increasingly unhinged.', 45, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 6, 'Do-Si-Do', 'Autumn’s erratic behavior reaches a fever pitch. Royal and Cecilia take matters into their own hands.', 59, '2024-05-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11685912')) AND numero_temporada = 2), 7, 'The End of Innocence', 'Time is a motherf**ker.', 56, '2024-05-16');
