INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt11712058', 'Mayor of Kingstown', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm0775358'), 'SERIE', 'The McLusky family are power brokers tackling themes of systemic racism, corruption and inequality in Kingstown, Michigan, where the business of incarceration is the only thriving industry.', '2021-01-01', 'https://m.media-amazon.com/images/M/MV5BOGZhODE5ZmEtMmE2OC00M2YzLWFjODMtYzI3ZTI0Mzk0MmY1XkEyXkFqcGc@._V1_.jpg');
