INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')), 1, 'Season 1', NULL);
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 1, 'The Mayor of Kingstown', 'Brothers Mitch and Mike McLusky navigate Kingstown, home to multiple prisons, as they act as the liaisons between prisoners and the community. When a young guard, Sam, is set up to deliver a letter for a prisoner, Mike works to get him off the hook.', 66, '2021-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 2, 'The End Begins', 'Local gang leader, Bunny is upset when one of his guys gets taken off the yard. Mike brokers a deal, and is later visited by two FBI agents whom Mitch worked for. Milo has instructions for Josef on how to get closer to Mike.', 50, '2021-11-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 3, 'Simply Murder', 'After a tragic accident has deadly consequences, an all-out manhunt ensues. Meanwhile, Mike reaches out to a former prison contact.', 55, '2021-11-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 4, 'The Price', 'Everyone wants something from Mike, who reminds them who is in control. Iris visits Mike’s office. Mariam and Mike discuss Kyle’s future.', 47, '2021-11-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 5, 'Orion', 'Kyle and Ian are questioned by internal affairs in the wake of the shootout. Bunny asks Mike for help with a close family member.', 47, '2021-12-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 6, 'Every Feather', 'When a fight breaks out on the yard, Sam finds himself in trouble again. Milo goes to extreme lengths to get what he wants. Mike sends a message.', 51, '2021-12-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 7, 'Along Came a Spider', 'Mike pays Milo a visit, looking for answers. Tensions at the men’s prison reach a boiling point. Mike makes a disturbing discovery.', 57, '2021-12-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 8, 'The Devil Is Us', 'Kyle and Kingstown PD try to make sense of the crime scene. Mike takes matters into his own hands. Sam makes a costly mistake.', 55, '2021-12-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 9, 'The Lie of the Truth', 'Tracy has good news for Kyle. Mike and Iris spend a peaceful day at the cabin, unaware of the trouble escalating back in town.', 47, '2022-01-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 1), 10, 'This Piece of My Soul', 'Kingstown Prison descends into total chaos. Mike desperately works to help stop a riot that will have serious consequences for all involved.', 51, '2022-01-09');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')), 2, 'Season 2', 'The struggle for power becomes tougher than ever as the McLuskys work to keep order on all sides of the gate.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 1, 'Never Missed a Pigeon', 'In the wake of the Kingstown Prison riot, violence and chaos ensue in the newly formed tent city. Mike and Bunny discuss what must be done to solve the leadership void on the inside. Kyle begins his new job with the Michigan State Police.', 53, '2023-01-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 2, 'Staring at the Devil', 'After a power vacuum in tent city spills out into Kingstown, Mike makes a bold move to try and restore order. Iris is uneasy about her new living arrangement. Kyle finds himself in a dangerous situation.', 47, '2023-01-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 3, 'Five at Five', 'Mike asks for help in finding Iris, and later takes matters into his own hands. A move by Robert and his team puts Mike''s larger plan in jeopardy. Kyle has a request for Kingstown PD.', 38, '2023-01-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 4, 'The Pool', 'Mike increases pressure on Evelyn to honor her side of the deal before another unexpected event at tent city. Bunny worries Mike has lost control. Mariam attempts an act of good will.', 40, '2023-02-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 5, 'Kill Box', 'In the wake of the tent city transfer, Mike finds himself in a race to locate Bunny. Kareem surveys the new power structure, and later gets some unsettling news. Kyle contemplates his next move. Milo looks to fix Joseph''s mistake.', 40, '2023-02-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 6, 'Left with the Nose', 'Mike leverages a favor with the new powers in charge. Bunny finds himself short on patience as Anchor Bay becomes increasingly volatile. Kyle and Mike have a heart to heart. Robert gets some troubling news.', 38, '2023-02-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 7, 'Drones', 'Robert, Kyle, and Ian look to get their story straight as the internal affairs investigation looms. In the wake of Lockett''s murder, Mike and Evelyn''s relationship grows tense. Mike takes care of a problem for Bunny. Tracy worries about Kyle.', 35, '2023-02-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 8, 'Santa Jesus', 'Mike spends his version of a day off the grid. Ian goes to great lengths to solve a problem. Bunny has a gift for Raphael. Milo speaks to Iris alone.', 47, '2023-03-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 9, 'Peace in the Valley', 'Mike and Milo discuss a possible trade. Bunny makes a brazen move and later has a demand for Mike. Mariam looks to track down Jacob. Evelyn is livid with Mike.', 37, '2023-03-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 2), 10, 'Little Green Ant', 'It''s all hands on deck as the war spills out into the streets of Kingstown. A mistake has serious repercussions. The trust between Mike and Bunny reaches a moment of truth. Iris finds herself with nowhere else to go.', 47, '2023-03-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')), 3, 'Season 3', 'In season three, a series of explosions rock Kingstown and its citizens, as a new face of the Russian mob sets up shop in the city, and a drug war rages inside and outside prison walls. The pressure is on Mike McLusky to end the war but things get complicated when a familiar face from his incarcerated past threatens to undermine the Mayor''s attempts to keep the peace among all factions.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 1, 'Soldier''s Heart', 'Tensions are high as tragedy strikes in Kingstown. Meanwhile, a new face of the Russian mob sets up shop in the city.', 55, '2024-06-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 2, 'Guts', 'Anchor Bay gets a new inmate as Mike investigates recent deaths both inside and outside of prison walls.', 43, '2024-06-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 3, 'Barbarians at the Gate', 'The Mayor makes his presence known to Konstantin. Bunny brings Mike up to speed on a failed assassination attempt.', 41, '2024-06-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 4, 'Rag Doll', 'Desperate to confirm the source of a spate of bombings, Mike extends an unlikely olive branch.', 41, '2024-06-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 5, 'Iris', 'Danger erupts when Iris confronts her past. The Mayor finds a new chess piece as Bunny and Konstantin''s rivalry reaches new heights.', 48, '2024-06-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 6, 'Ecotone', 'After an attack hits close to home, Mike is given an ultimatum that could change everything.', 39, '2024-07-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 7, 'Marya Was Here', 'An incident on the bridge raises questions across Kingstown. Mike sets a risky plan in motion.', 44, '2024-07-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')) AND numero_temporada = 3), 8, 'Captain of the Sh*t Out of Luck', 'Anchor Bay is attacked from outside its prison walls. Mike takes care of some important business at Kingstown Women''s Prison.', 46, '2024-07-21');
