INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11712058')), 4, 'Season 4', 'In season four, Mike''s control over Kingstown is threatened as new players compete to fill the power vacuum left in the Russians'' wake, compelling him to confront the resulting gang war and stop them from swallowing the town. Meanwhile, with those he loves in more danger than ever before, Mike must contend with a headstrong new Warden to protect his own while grappling with demons from his past.');
