INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')), 1, 'Season 1', 'When a grisly death occurs inside their exclusive Upper West Side apartment building, three strangers who share an obsession with true crime suspect murder and employ their precise knowledge of true crime to investigate the truth. As they record a podcast of their own to document the case, the three unravel the complex secrets of the building which stretch back years. Perhaps even more explosive are the lies they tell one another. Soon, the endangered trio comes to realize a killer might be living amongst them as they race to decipher the mounting clues before it’s too late.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 1, 'True Crime', 'Upper West Side neighbors Charles, Oliver & Mabel bond over a shared love of true crime. When a fellow resident dies in their building, the trio determine to solve the mystery and record an accompanying podcast.', 34, '2021-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 2, 'Who Is Tim Kono?', 'The group begins researching the victim. Meanwhile, Mabel’s secretive past starts to be unraveled.', 30, '2021-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 3, 'How Well Do You Know Your Neighbors?', 'Oliver employs his theater director skills to analyze the case. Charles & Mabel question an obsessive cat lover.', 35, '2021-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 4, 'The Sting', 'Believing the murderer might be a famous resident whom is difficult to access, the group seeks advice from a renowned podcasting host.', 34, '2021-09-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 5, 'Twist', 'Mabel slips away on a solo mission tracking the victim''s final days. Suspicious, Charles & Oliver follow her.', 26, '2021-09-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 6, 'To Protect and Serve', 'Mabel brings her new friends (and an old one) to her childhood home to meet her mother. Meanwhile, Detective Williams starts to have her own doubts about the case as she prepares for motherhood.', 33, '2021-09-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 7, 'The Boy from 6B', 'With the investigation scratching at a web of old crimes originating inside the building, a mysterious young man turns the tables to spy on Charles, Oliver & Mabel.', 32, '2021-09-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 8, 'Fan Fiction', 'Hitting a dead end, the group calls for reinforcements in the form of their podcast’s Superfans.', 32, '2021-10-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 9, 'Double Time', 'With the residents growing upset at the building’s negative publicity, the trio faces a revolt. Charles is visited by an old colleague who sheds light on his past.', 32, '2021-10-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 1), 10, 'Open and Shut', 'In the season finale, the trio races toward a resolution while their own lives are put in danger.', 36, '2021-10-19');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')), 2, 'Season 2', 'Season 2 picks up with the trio following the shocking death of Arconia Board President Bunny Folger, as they race to unmask her killer. However, three (unfortunate) complications ensue—the trio is publicly implicated in Bunny’s homicide, they are now the subjects of a competing podcast, and they have to deal with a bunch of New York neighbors who all think they committed murder.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 1, 'Persons of Interest', 'Welcome home, Arconiacs!  Minutes after Season 1’s finale, Charles, Oliver and Mabel are now implicated in the murder of Board President, Bunny Folger.  They must choose whether to lay low or risk their safety by catching the killer themselves.', 36, '2022-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 2, 'Framed', 'A memorial for Bunny provides an opportunity for our trio to question their neighbors, while they also try to get rid of a very implicating piece of evidence.  One of Bunny’s relatives makes an appearance and if you thought Bunny was a force, get ready...', 36, '2022-06-28');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 3, 'The Last Day of Bunny Folger', 'A foul-mouthed parrot becomes a critical window into Bunny Folger’s last day on Earth.  Some of the individuals with whom Bunny crossed paths will surprise both you and our trio... Along the way, a reveal deepens our trio''s need to solve Bunny''s case.', 32, '2022-07-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 4, 'Here''s Looking at You', 'Charles, Oliver and Mabel welcome an unexpected young visitor who reveals hidden secrets about the inner workings of the Arconia.  We also discover Charles once recorded a hit single that was huge in Germany.', 38, '2022-07-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 5, 'The Tell', 'Mabel hosts a party for an electric art crowd which also serves a double purpose for smoking on a liar in the trios’s midst.', 36, '2022-07-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 6, 'Performance Review', 'Charles, Oliver and Mabel collide with their podcasting mentor-turned-competitor, Cinda Canning.  Subsequently, a key clue requires the trio to orchestrate a classic stakeout — Brazzos-style.  New York has never been more glittering.', 34, '2022-07-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 7, 'Flipping the Pieces', 'Mabel’s incident on the subway leads her to gain help from an unlikely ally.  Their journey takes them to a legendary amusement park which turns out to be full of terror — while amusements and evidence reside back in the Arconia with Charles and Oliver.', 33, '2022-08-02');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 8, 'Hello, Darkness', 'A blackout throws the city into chaos.  As the trio races to save a loved one from the killer, other Arconia residents begin to explore unexpected connections in the midst of darkness — all enhanced by Gut Milk and a yodel or two.', 30, '2022-08-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 9, 'Sparring Partners', 'Closing in on the killer, Mabel takes her investigative talents into the ring.  Oliver and Charles duke it out over a birdcage only to end up confronting their deepest paternal struggles.', 30, '2022-08-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 2), 10, 'I Know Who Did It', 'One question remains: Who did it??? Oh, who are we kidding -- there''s a few more questions raised, too.', 38, '2022-08-23');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')), 3, 'Season 3', 'Season three finds Charles, Oliver & Mabel investigating a murder behind the scenes of a Broadway show. Ben Glenroy is a Hollywood action star whose Broadway debut is cut short by his untimely death. Aided by co-star Loretta Durkin, our trio embarks on their toughest case yet, all while director Oliver desperately attempts to put his show back together. Curtain up!');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 1, 'The Show Must...', 'Curtain up on Season 3! And Leading Man down! After Ben Glenroy''s collapse on stage, Charles, Oliver & Mabel piece together the show’s first days with a suspicious cast & crew to determine if foul play was involved. Spoiler alert...', 38, '2023-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 2, 'The Beat Goes On', 'Mabel, Oliver & Charles attend Ben’s lavish memorial full of fans and those with more dubious motives. As the actor''s sudden death is mourned, Oliver works to revive his shaky Broadway show.', 34, '2023-08-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 3, 'Grab Your Hankies', 'Oliver races to bring new life to his show as Mabel’s investigation into the actual murder collides with a surprising ally. Charles bonds with the cast, and Loretta proves her voice is invaluable.', 39, '2023-08-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 4, 'The White Room', 'Charles’s stage fright reaches unimaginable heights, involving a break from reality and multiple baby dolls. Mabel is confronted by a mysterious individual from her past with a pivotal proposal.', 36, '2023-08-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 5, 'Ah, Love!', 'Date night! New York proves itself both a jewel box and a fish tank of romance as Charles, Mabel & Oliver take their relationships to the next stage. And dating can reveal many hidden secrets, too...', 36, '2023-08-29');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 6, 'Ghost Light', 'All roads lead the trio back to the Goosebury Theater during a nerve-rattling thunderstorm. With Howard as their jittery guide, they track a legendary ghost who’s haunted the theater for generations. Boo.', 34, '2023-09-05');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 7, 'CoBro', 'Charles finds an unexpected source for a major clue. A Broadway icon comes knocking at Oliver’s door. And Mabel forms an alternate trio to pursue a lead that sheds light on Ben’s bro and CoBro history.', 37, '2023-09-12');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 8, 'Sitzprobe', 'On the day of the show’s most critical rehearsal, the pressure mounts. A familiar official returns to upend the case, Loretta’s complex past threatens to upend all else and Charles must finally sing his number without losing his marbles.', 39, '2023-09-19');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 9, 'Thirty', 'The trio have amassed a plethora (oh yes, a plethora) of clues, suspects & theories but find no concrete answers about Ben’s murder. They devise a peculiar method of throwing themselves into the actual case to recreate the final moments of Ben’s life.', 38, '2023-09-26');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 3), 10, 'Opening Night', 'Curtain call on Season 3! Charles, Mabel & Oliver race to entrap the killer on Opening Night. As the musical thrills its Broadway audience, the trio brave further twists & turns from behind, above and all around the stage.', 38, '2023-10-03');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')), 4, 'Season 4', 'The trio investigates the mysterious murder of Sazz Pataki, Charles'' stunt double, whose death raises questions about whether Sazz or Charles was the intended victim. The Arconia residents find themselves entangled in Hollywood drama as a studio adapts their podcast into a movie, leading to new faces and on-set chaos. As the action ramps up, the amateur sleuths return to New York, diving into the twisted lives of the Arconia''s West Tower residents.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 1, 'Once Upon a Time in the West', 'Charles, Oliver & Mabel are whisked to Los Angeles where a legendary film studio intends to adapt their podcast. However, Hollywood''s glitz is overshadowed by a stunning clue about Charles'' stunt double & friend Sazz Pataki.', 39, '2024-08-27');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 2, 'Gates of Heaven', 'Mabel & Oliver begin investigating Arconia''s West Tower and get trapped inside an ominous game. Meanwhile, Charles is visited by two individuals from his complex past.', 37, '2024-09-03');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 3, 'Two for the Road', 'Charles, Oliver & Mabel begrudgingly pair off with new investigators... actors Eugene Levy, Zach Galifianakis & Eva Longoria.', 41, '2024-09-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 4, 'The Stunt Man', 'Charles, Oliver & Mabel delve into the particular universe of stunt people. They encounter a suspect with an incredibly... familiar... face.', 36, '2024-09-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 5, 'Adaptation', 'The trio face off against a collection of individuals who deceive, manipulate, and threaten as second nature - a Hollywood cast & crew.', 34, '2024-09-24');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 6, 'Blow-Up', 'A documentary film is made by The Brothers Sisters.', 34, '2024-10-01');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 7, 'Valley of the Dolls', 'Terrified by a threat inside the Arconia, the trio race out of the city. A member of Charles'' family provides refuge and yet, this safe house proves to be anything but.', 40, '2024-10-08');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 8, 'Lifeboat', 'Charles, Oliver & Mabel combine forces with the film actors in an epic showdown against the Westies. You can''t handle the truth.', 37, '2024-10-15');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 9, 'Escape from Planet Klongo', 'Seeking a critical clue, Charles, Oliver & Mabel must infiltrate a film set to get the real "background" on why Sazz was killed.', 35, '2024-10-22');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 4), 10, 'My Best Friend''s Wedding', 'The final answers to our season are revealed - but not before the trio faces mortal danger and an Arconia wedding.', 37, '2024-10-29');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')), 5, 'Season 5', 'After their beloved doorman, Lester, dies under suspicious circumstances, Charles, Oliver, and Mabel refuse to believe it was an accident. Their investigation plunges them into the shadowy corners of New York and beyond - where the trio uncovers a dangerous web of secrets connecting powerful billionaires, old-school mobsters, and the mysterious residents of the Arconia. The trio discovers a deeper divide between their storied city they thought they knew and the new New York evolving around them - one where the old mob fights to hold on as newer, even more dangerous players emerge.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 1, 'Nail in the Coffin', 'While investigating Lester’s mysterious "accidental" death, the clues lure Charles, Oliver, and Mabel out of Manhattan — and straight into some dangerous new "old" territory.', 39, '2025-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 2, 'After You', 'A look back at Lester''s early days at the Arconia reveals how a young dreamer became a steadfast doorman — sacrificing his future to protect the residents from the building’s secrets.', 33, '2025-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 3, 'Rigor', 'The trio stumbles upon a crucial piece of evidence... and promptly compromises it. With time running out, they scramble to solve the mystery before the police close in on them.', 37, '2025-09-09');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 4, 'Dirty Birds', 'Snooping goes sideways when three billionaire suspects catch the trio and invite themselves over for an evening at Oliver''s.', 37, '2025-09-16');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 5, 'Tongue Tied', 'Thwarted in their investigative podcast plans, Mabel and Oliver look for help from the Arconia support staff — as Charles dines with another suspect and gets caught up in "catching" more than he bargained for.', 37, '2025-09-23');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 6, 'Flatbush', 'The investigation takes Oliver and Loretta back to the streets of his childhood, where buried memories surface and secrets about Lester and Nicky''s widows emerge. Mabel and Charles follow leads after a break-in.', 38, '2025-09-30');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 7, 'Silver Alert', 'The mayor warns the trio about the billionaires, sending them to investigate further at a villainous lair upstate — as Oliver boots it in an attempted escape.', 38, '2025-10-07');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 8, 'Cuckoo Chicks', 'Mabel gathers a ragtag group to crash an exclusive ladies night. While trying to save the Arconia from being sold, Charles and Oliver accidentally end up in couples'' therapy.', 41, '2025-10-14');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 9, 'LESTR', 'Told through the lens of one annoying robot who may hold the keys to more secrets than anyone realized — the Arconia throws one last party as the residents discover that a killer may still be in their building.', 35, '2025-10-21');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11691774')) AND numero_temporada = 5), 10, 'The House Always...', 'With the clock ticking, the trio doubles down to bring "new" and "old" forces together to bring down a killer — ending in one explosive showdown and the reveals they''ve been chasing all season.', 41, '2025-10-28');
