INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 1, 'ROMANCE DAWN', 'Stranded on a sinking boat, carefree Luffy begins his journey in search of a pirate king''s lost treasure. But first, he''ll need a crew, a ship and a map.', 66, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 2, 'THE MAN IN THE STRAW HAT', 'After securing a map to the Grand Line, Luffy, Nami and Zoro are taken hostage by a no-nonsense clown. New cadet Koby is cornered by Vice-Admiral Garp.', 57, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 3, 'TELL NO TALES', 'In need of a proper ship, the gang reaches Syrup Village and meets the cheerful Usopp and his best friend Kaya. A sinister threat disrupts their plans.', 59, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 4, 'THE PIRATES ARE COMING', 'With his friends in danger and Klahadore''s plan in motion, Usopp seeks help from the Marines. Blades clash when a fierce battle erupts at Kaya''s mansion.', 64, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 5, 'EAT AT BARATIE!', 'The Straw Hat Pirates face their first adversary as a group. At a floating fish house, Luffy befriends a cook, and Zoro enters a duel with a warlord.', 52, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 6, 'THE CHEF AND THE CHORE BOY', 'Sanji and head chef Zeff put their differences aside to save a severely wounded Zoro. A ruthless Fishman on a mission stirs up trouble for the crew.', 56, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 7, 'THE GIRL WITH THE SAWFISH TATTOO', 'After striking a deal with a familiar foe to find Arlong, Luffy and his friends set sail for Coco Village and learn about Nami''s mysterious past.', 60, '2023-08-31');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 1), 8, 'WORST IN THE EAST', 'The Straw Hat crew strives to take down Arlong and the Fishmen once and for all. After a tense family reunion, Luffy inches closer to his dreams.', 51, '2023-08-31');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')), 2, 'Into the Grand Line', 'In ONE PIECE: Into the Grand Line, Luffy and the Straw Hats set sail for the extraordinary Grand Line - a legendary stretch of sea where danger and wonder await at every turn. As they journey through this unpredictable realm in search of the world''s greatest treasure, they''ll encounter bizarre islands and a host of formidable new enemies.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 1, 'THE BEGINNING AND THE END', 'To prepare for the Grand Line, the Straw Hats visit Loguetown, birthplace of the Great Pirate Era — where rivals both old and new await.', 66, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 2, 'GOOD WHALE HUNTING', 'When the Merry lands in the belly of a giant whale, Luffy must win over a gruff lighthouse keeper to save his friends and his ship.', 64, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 3, 'WHISKY BUSINESS', 'The crew receives a warm welcome to the pirate-loving town of Whisky Peak. But with a pair of assassins on the loose, trouble isn''t far behind.', 64, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 4, 'BIG TROUBLE IN LITTLE GARDEN', 'A new addition to the ship raises the stakes. On the lush isle of Little Garden, the crew encounters an adventure of giant proportions.', 55, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 5, 'WAX ON, WAX OFF', 'The Straw Hats are held captive by two artists: one who colors emotions, and one intent on making them part of his latest — and deadliest — masterwork.', 58, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 6, 'NAMI DEEREST', 'When Nami is stricken by a mysterious illness, Luffy and Sanji embark on a perilous mission to save her. Smoker and Tashigi investigate a Marine outpost.', 56, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 7, 'REINDEER SHAMES', 'Dr. Kureha tells the heartwrenching story of Chopper''s origins, including how he met his mentor Dr. Hiriluk and their quest to cure all disease.', 61, '2026-03-10');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 2), 8, 'DEER AND LOATHING IN DRUM KINGDOM', 'The Straw Hats lend themselves to Drum Island''s cause when King Wapol and his army of monsters return to reclaim the throne.', 64, '2026-03-10');
INSERT IGNORE INTO Temporada (id_serie, numero_temporada, nombre, descripcion) VALUES ((SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')), 3, 'The Battle of Alabasta', 'In ONE PIECE: The Battle of Alabasta, war is coming for Monkey D. Luffy and the Straw Hat crew in the desert kingdom of Alabasta, Princess Vivi''s homeland. A rebellion threatens to tear the nation apart, fueled in secret by one of the Seven Warlords of the Sea, the ruthless Sir Crocodile, and his underground syndicate Baroque Works, who seek to conquer Alabasta for themselves. In a season defined by unbreakable bonds and impossible choices, the Straw Hats must face a brewing civil war and a powerful warlord to save Vivi''s kingdom before it crumbles into the sand.');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11737520')) AND numero_temporada = 3), 1, 'WHERE THERE''S SMOKE', NULL, 0, NULL);
