INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 1, 'Not Your Average Joe', 'Meet Joe Exotic, the gun-toting operator of an Oklahoma big cat park. He’s been accused of hiring someone to murder his chief rival, Carole Baskin.', 49, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 2, 'Cult of Personality', 'Subjected to long hours, little (or no) pay and the whims of eccentric bosses: are big cat park employees just cogs in a web of personality cults?', 47, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 3, 'The Secret', 'An incident in Carole''s past casts her in a suspicious light, and while she maintains her innocence, Joe is all too happy to point the finger at her.', 47, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 4, 'Playing with Fire', 'Joe ramps up his efforts to become an internet and TV star, but a mysterious fire and lawsuit threaten his plans — until an angel investor appears.', 46, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 5, 'Make America Exotic Again', 'As Joe dives into politics, he deals with turmoil and tragedy in his personal life. Meanwhile, the dynamics at the park change with the new owners.', 44, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 6, 'The Noble Thing to Do', 'James Garretson makes a shocking claim about Joe, leading to FBI involvement. Desperation sets in for Joe, who thinks Jeff and James have set him up.', 44, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 7, 'Dethroned', 'Joe faces the music in the courtroom but insists the story is far from over. Jeff’s business prospects crumble. Former G.W. Zoo workers try to move on.', 42, '2020-03-20');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 1), 8, 'The Tiger King and I', 'In this aftershow, Joel McHale talks with Jeff, Saff, Erik and more to get their reactions to the series, their portrayals  and their new fame', 44, '2020-04-12');
