INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 2), 2, 'The Carole Diaries', 'Renewed interest in Don''s disappearance leads authorities, journalists and his children to investigate how, when -- and even if -- he was killed.', 40, '2021-11-17');
INSERT IGNORE INTO Episodio (id_temporada, numero_episodio, titulo, descripcion, duracion, fecha_emision) VALUES ((SELECT id_temporada FROM Temporada WHERE id_serie = (SELECT id_serie FROM Serie WHERE id_contenido = (SELECT id_contenido FROM Contenido WHERE id_api = 'tt11823076')) AND numero_temporada = 2), 3, 'Bounty Hunting', 'Don''s daughters escalate their efforts to learn more about their father''s fate.  Carole''s version of events faces further scrutiny.', 44, '2021-11-17');
