INSERT IGNORE INTO Contenido (id_api, titulo_principal, id_director, tipo_contenido, descripcion, fecha, imagen_url) VALUES ('tt11912196', 'Asur: Welcome to Your Dark Side', (SELECT id_trabajador FROM Trabajadores WHERE id_api = 'nm11411263'), 'SERIE', 'Shubh returns for revenge and this season he takes the challenge to a whole new level. With the heroes fallen apart, will a desolate Dhananjay Rajpoot and a torn Nikhil Nair be able to stop him?', '2020-01-01', 'https://m.media-amazon.com/images/M/MV5BMDZkOGQzMjItNTliOC00NTIxLTg4ODEtNTMxZWY1OTk5ZWM0XkEyXkFqcGc@._V1_.jpg');
